-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-04-27
-- Description:	Check inventory
-- =============================================
CREATE FUNCTION [dbo].[usf_check_inventory]
(
	@v_vchWarehouseMasterID		NVARCHAR(40),
	@v_vchWarehouseItemMasterID NVARCHAR(40),
	@v_vchLocationID			NVARCHAR(40),
	@v_vchStatusID				NVARCHAR(40),
	@v_vchLPN					NVARCHAR(25)
	--@v_dtReceiveDate			DATE					
)
RETURNS Int
AS
BEGIN

	Declare @v_intCount INT
	
	select		@v_intCount = count(inventory_id) from t_wms_inventory
	where		wh_master_id = @v_vchWarehouseMasterID
				and wh_item_master_id = @v_vchWarehouseItemMasterID and location_id = @v_vchLocationID
				and inventory_status_id = @v_vchStatusID and isnull(lpn,'') = isnull(@v_vchLPN,'')
				--and isnull(convert(nvarchar,receive_date,112),'') = isnull(convert(nvarchar,@v_dtReceiveDate,112),'')
	
	-- Return the result of the function
	RETURN @v_intCount;

END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_check_inventory_attribute]    Script Date: 08/08/2025 11:11:28 ******/
