-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-05-14
-- Description:	Check exists in t_wms_inventory_attribute
-- =============================================
CREATE FUNCTION [dbo].[usf_check_inventory_attribute_by_allcontrol]
(
	@v_vchSerialNo		NVARCHAR(100),
	@v_vchLot			NVARCHAR(100),
	@v_vchExpiryDate	NVARCHAR(100),
	@v_vchInventoryID	NVARCHAR(40),
	@v_vchAttributeGroupID	NVARCHAR(40)
)
RETURNS Int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @v_intCount INT

	-- Add the T-SQL statements to compute the return value here
	SELECT	@v_intCount = COUNT(*) 
	FROM	t_wms_inventory_attribute 
	WHERE	(attribute_value = @v_vchSerialNo or
			attribute_value = @v_vchLot or
			attribute_value = @v_vchExpiryDate) and
			inventory_id = @v_vchInventoryID and 
			attribute_group_id = @v_vchAttributeGroupID

	-- Return the result of the function
	RETURN @v_intCount;

END
