/****** Object:  UserDefinedFunction [dbo].[usf_check_quantity_value]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-06-24
-- Description: Check quantity value
-- =============================================
CREATE FUNCTION [dbo].[usf_check_quantity_value]
(
	@in_fltSerialValue	FLOAT = null,
	@in_fltLotValue		FLOAT = null,
	@in_fltExpiryDateValue	FLOAT = null
)
RETURNS FLOAT
AS
BEGIN
	declare @v_fltReturnValue FLOAT
	
	If (@in_fltSerialValue is not null and @in_fltLotValue is not null and @in_fltExpiryDateValue is not null)
		Begin
			set @v_fltReturnValue = @in_fltSerialValue;
		End
	Else If (@in_fltSerialValue is not null and @in_fltLotValue is not null)
		Begin
			set @v_fltReturnValue = @in_fltSerialValue;
		End
	Else If (@in_fltSerialValue is not null and @in_fltExpiryDateValue is not null)
		Begin
			set @v_fltReturnValue = @in_fltSerialValue;
		End
	Else If (@in_fltLotValue is not null and @in_fltExpiryDateValue is not null)
		Begin
			If (@in_fltLotValue < @in_fltExpiryDateValue)
				Begin
					set @v_fltReturnValue = @in_fltLotValue;
				End
			Else
				Begin
					set @v_fltReturnValue = @in_fltExpiryDateValue;
				End
		End
	Else
		Begin
			return @v_fltReturnValue;
		End
	
	return @v_fltReturnValue;
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_count_external_generate_running_order]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_count_external_generate_running_order]
()
RETURNS NVARCHAR(50)
AS
BEGIN
	DECLARE @v_vchFormatDate	VARCHAR(40),
			@v_vchFormatRule	NVARCHAR(10),
			@v_intRunning		INT,
			@v_vchRunningID		VARCHAR(40),
			@v_vchCountID		NVARCHAR(50)


		SELECT @v_vchFormatDate = CONVERT(VARCHAR,GETDATE(),112)
		SELECT @v_vchFormatRule = ISNULL(value,'0') FROM t_wms_rule WHERE rule_code = 'FORMAT_COUNT_EXTERNAL_ID_FOR_RUNNING'


		SELECT @v_intRunning = CONVERT(INT,SUBSTRING(MAX(count_id),9,LEN(MAX(count_id))-8))
		FROM t_wms_count_plan_master_external
		WHERE LEFT(CONVERT(VARCHAR,count_id,112),8) = @v_vchFormatDate

	 	SET @v_vchRunningID = RIGHT(@v_vchFormatRule+CONVERT(VARCHAR,ISNULL(@v_intRunning,0) + 1),LEN(@v_vchFormatRule));
		SET @v_vchCountID = @v_vchFormatDate + @v_vchRunningID;
	
		RETURN @v_vchCountID
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_count_total_box]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_count_total_box]
(
	@v_vchCustomerCode		NVARCHAR(40),
	@v_vchShipDateActual	DATETIME,
	@v_vchOrderType			NVARCHAR(30)
)
RETURNS int
AS 
BEGIN
	DECLARE @v_intCountTotal INT
	SET @v_intCountTotal = 0
	
	SELECT @v_intCountTotal = SUM(outPack.MaxPack)
	FROM (SELECT DISTINCT
				 mas.outbound_order_number
				,CONVERT(VARCHAR, mas.ship_date_actual, 105) as ship_date_actual
				,mas.customer_code
				,MAX(CONVERT(INT,RIGHT(pack.lpn_pack,4))) MaxPack
			FROM t_wms_outbound_master mas
			LEFT JOIN t_wms_outbound_pack_detail pack ON mas.outbound_order_master_id = pack.outbound_order_master_id
			WHERE customer_code = @v_vchCustomerCode
			AND CONVERT(VARCHAR, mas.ship_date_actual, 112) = @v_vchShipDateActual
			AND mas.order_type = @v_vchOrderType
			GROUP BY mas.outbound_order_number
					,mas.customer_code
					, CONVERT(VARCHAR, mas.ship_date_actual, 105)
		  ) AS outPack
		  
	RETURN @v_intCountTotal
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_find_get_serial_receipt]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_find_get_serial_receipt] 
(
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER, 
	@in_vchWhItemMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	    NVARCHAR(50)  = NULL,
	@in_vchExpiryDate	    NVARCHAR(20)  = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL
)
RETURNS NVARCHAR(2000)
AS
BEGIN

	DECLARE @v_vchSerialDetail NVARCHAR(2000) 
	
	SELECT @v_vchSerialDetail = ISNULL(@v_vchSerialDetail,'') +', ' + ISNULL(serial_number,'') FROM t_wms_receipt_detail
	WHERE receipt_header_id = @in_vchReceiptHeaderID
	AND wh_item_master_id = @in_vchWhItemMasterID   
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')  
	AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')    
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND ISNULL(serial_number,'') <> ''

	RETURN RIGHT(@v_vchSerialDetail,len(@v_vchSerialDetail)-1)
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_find_outbound_order_allocate]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_find_outbound_order_allocate] 
(
	@in_vchWhMasterID	VARCHAR(40),
	@in_vchLocationID	VARCHAR(40),
	@in_vchLPN			VARCHAR(40),
	@in_vchWhItemMasterID VARCHAR(40),
	@in_vchLotNumber	NVARCHAR(50),
	@in_vchExpiryDate	NVARCHAR(50),
	@in_dtReceiveDate	DATE,
	@in_vchInvStatus	VARCHAR(40)
)
RETURNS VARCHAR(500)
AS
BEGIN

	DECLARE @v_vchOrderDesc	NVARCHAR(2000) = ''
	DECLARE @v_vchOrderNumber NVARCHAR(50) = ''

	SELECT @v_vchOrderDesc = @v_vchOrderDesc + ', ' + obMS.outbound_order_number 
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
	WHERE ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
	AND obMS.order_status NOT IN ('OPEN','SHIP')
	AND obMS.wh_master_id = @in_vchWhMasterID
	AND pickDT.location_id = @in_vchLocationID
	AND ISNULL(pickDT.LPN,'') = ISNULL(@in_vchLPN,'')
	AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
	AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	AND pickDT.receive_date = @in_dtReceiveDate
	AND obDT.default_item_status = @in_vchInvStatus
	ORDER BY obMS.outbound_order_number
	
	IF ISNULL(@v_vchOrderDesc,'') <> ''
		SET @v_vchOrderDesc =  RIGHT(@v_vchOrderDesc, LEN(@v_vchOrderDesc)-2)

	RETURN @v_vchOrderDesc
	
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_find_outbound_order_number]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_find_outbound_order_number] 
(
	@v_vchCustomerCode		NVARCHAR(40),
	@v_vchShipDateActual	DATETIME,
	@v_vchOrderType			NVARCHAR(30)
)
RETURNS VARCHAR(500)
AS
BEGIN

	DECLARE @v_vchOrderDesc			NVARCHAR(500)
	DECLARE @v_vchOrderNumber		NVARCHAR(40)
	
	DECLARE OrderNumberDesc_Cursor CURSOR FOR
	
	SELECT vOut.delivery_number
	FROM t_wms_outbound_master outMas
	LEFT JOIN v_wms_outbound_comment vOut ON (outMas.outbound_order_master_id = vOut.outbound_order_master_id AND vOut.result_status = 'COMPLETED')
	WHERE outMas.customer_code = @v_vchCustomerCode
		AND CONVERT(VARCHAR, outMas.ship_date_actual, 112) = @v_vchShipDateActual
		AND outMas.order_type = @v_vchOrderType
	ORDER BY outMas.outbound_order_number, vOut.sequence

/*--Comment เนื่องจากแสดงด้วยเลข Delivery Number
	--SELECT outbound_order_number
	--FROM t_wms_outbound_master 
	--WHERE customer_code = @v_vchCustomerCode
	--AND CONVERT(VARCHAR, ship_date_actual, 112) = @v_vchShipDateActual
	--AND order_type = @v_vchOrderType
	--ORDER BY outbound_order_number*/
	
	OPEN OrderNumberDesc_Cursor
	
	FETCH FROM OrderNumberDesc_Cursor INTO @v_vchOrderNumber
	
	set @v_vchOrderDesc = '';
	WHILE @@FETCH_STATUS = 0
	BEGIN
		If (@v_vchOrderDesc = '')
			Begin
				SET @v_vchOrderDesc = isnull(@v_vchOrderNumber,'')
			End
		Else
			Begin
				SET @v_vchOrderDesc = @v_vchOrderDesc + ', ' + isnull(@v_vchOrderNumber,'')
			End
		FETCH NEXT FROM OrderNumberDesc_Cursor INTO @v_vchOrderNumber
	END	  

	CLOSE OrderNumberDesc_Cursor                  	
	DEALLOCATE OrderNumberDesc_Cursor

	RETURN @v_vchOrderDesc
	
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_generate_running_number]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_generate_running_number]
(
	@in_vchLastRunning		VARCHAR(30),
	@in_intLength			INT,
	@in_vchFormatDate		NVARCHAR(15)
)
RETURNS NVARCHAR(50)
AS
BEGIN
	DECLARE	@v_fltLastNumber		FLOAT,
			@v_fltNextNumber		FLOAT,
			@out_vchRunningNumber	NVARCHAR(50) = '',
			@v_vchNumber			NVARCHAR(50) = '',
			@i						INT = 0
			
			SET @v_fltLastNumber = CONVERT(FLOAT,RIGHT(@in_vchLastRunning,@in_intLength))

			IF(ISNULL(@v_fltLastNumber,'') = '')
				BEGIN
					SET @v_fltLastNumber = 0
				END

			WHILE @i < @in_intLength
			BEGIN
			   SET @v_vchNumber = @v_vchNumber + '0'
			   SET @i = @i+1
			END

			SET @v_fltNextNumber = @v_fltLastNumber + 1;
			SET	@out_vchRunningNumber = @in_vchFormatDate + '-' +  RIGHT(@v_vchNumber + CONVERT(VARCHAR(20),@v_fltNextNumber),@in_intLength)
		RETURN @out_vchRunningNumber;
END


/*
--select dbo.usf_generate_running_number('',3,'20151201')

select '0'
select  RIGHT('000000' + CONVERT(VARCHAR(20),1),3)
*/
