/****** Object:  UserDefinedFunction [dbo].[usf_get_app_locale_text_value]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[usf_get_app_locale_text_value]
(
	@in_vchApplicationID VARCHAR(40),
    @in_vchResourceName  NVARCHAR(50),
    @in_intLocaleID   INTEGER
)
RETURNS NVARCHAR(100)
AS
BEGIN
    DECLARE
    -- Local Variables
    @v_vchTextValue             NVARCHAR(100)
    
    -------------------------------------------------------------------------
	--  Set Resource based on detail in the Resource Detail table
	-------------------------------------------------------------------------
    SELECT @v_vchTextValue = RSD.value
	FROM t_com_resource_detail RSD, t_com_resource_master RSM
	WHERE RSM.resource_master_id = RSD.resource_master_id
	AND RSM.resource_name = @in_vchResourceName
	AND RSD.locale_id = @in_intLocaleID
	AND RSM.app_id = @in_vchApplicationID
	
	-------------------------------------------------------------------------
	--  No Detail Records so set by Default in Master Record
	-------------------------------------------------------------------------
	IF @v_vchTextValue IS NULL
	BEGIN
		 SELECT @v_vchTextValue = default_value
		FROM t_com_resource_master RSM
		WHERE RSM.resource_name = @in_vchResourceName
	END
	
	-------------------------------------------------------------------------
	--  No Value in Master Record or No Master so Set a Default 
	-------------------------------------------------------------------------
	IF @v_vchTextValue IS NULL
	BEGIN
		SELECT @v_vchTextValue = 'NO RESOURCE CONFIGURED'
	END

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:

    -- Always leave from here.
    RETURN @v_vchTextValue 
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_get_HostInterfaceID]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-09-19
-- Description:	Get Hostinterface id
-- =============================================
CREATE FUNCTION [dbo].[usf_get_HostInterfaceID]
(

)
RETURNS NVARCHAR(20)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @v_vchHostInterfaceID	NVARCHAR(20),
			@v_intRunningID			INT

	-- Add the T-SQL statements to compute the return value here
	select @v_vchHostInterfaceID = max(CONVERT(decimal,working_date)),@v_intRunningID = last_running from t_com_interface_running
	where working_date = convert(nvarchar,GETDATE(),112) group by working_date,last_running
	
	If (@v_vchHostInterfaceID is null)
		Begin
			set @v_vchHostInterfaceID = convert(nvarchar,GETDATE(),112) + '0000001';
		End
	Else
		Begin
			set @v_vchHostInterfaceID = @v_vchHostInterfaceID + convert(nvarchar,RIGHT('000000' + convert(nvarchar,@v_intRunningID + 1),7))
		End
	-- Return the result of the function
	RETURN @v_vchHostInterfaceID;

END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_get_locale_id]    Script Date: 08/08/2025 11:11:28 ******/
