CREATE FUNCTION [dbo].[usf_get_locale_id]
(
	@in_vchUserID	NVARCHAR(10)
)
RETURNS nvarchar(40)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @LocaleID NVARCHAR(40)
	
	select @LocaleID = locale from WM3_Security.dbo.t_com_user tUser
	INNER JOIN WM3_Security.dbo.t_com_locale tLocal on tUser.locale_id = tLocal.locale_id
	WHERE tUser.[user_id] = @in_vchUserID
	
	return @LocaleID;

END
GO
