/****** Object:  UserDefinedFunction [dbo].[usf_get_month_name]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_get_month_name]
(
	@v_intMonth		int,
	@v_vchLocal		NVARCHAR(10)  --1052 = Thai, 1033 = Eng
)
RETURNS VARCHAR(500)
AS
BEGIN
	DECLARE @v_vchMonthName varchar(50)
	SET @v_vchMonthName = ''
	
	IF @v_vchLocal = '1054' 
		BEGIN
			--Thai
			IF @v_intMonth = 1
				SET @v_vchMonthName = 'มกราคม'
			ELSE IF @v_intMonth = 2
				SET @v_vchMonthName = 'กุมภาพันธ์'
			ELSE IF @v_intMonth = 3
				SET @v_vchMonthName = 'มีนาคม'
			ELSE IF @v_intMonth = 4
				SET @v_vchMonthName = 'เมษายน'
			ELSE IF @v_intMonth = 5
				SET @v_vchMonthName = 'พฤษภาคม'
			ELSE IF @v_intMonth = 6
				SET @v_vchMonthName = 'มิถุนายน'
			ELSE IF @v_intMonth = 7
				SET @v_vchMonthName = 'กรกฎาคม'
			ELSE IF @v_intMonth = 8
				SET @v_vchMonthName = 'สิงหาคม'
			ELSE IF @v_intMonth = 9
				SET @v_vchMonthName = 'กันยายน'
			ELSE IF @v_intMonth = 10
				SET @v_vchMonthName = 'ตุลาคม'
			ELSE IF @v_intMonth = 11
				SET @v_vchMonthName = 'พฤศจิกายน'
			ELSE IF @v_intMonth = 12
				SET @v_vchMonthName = 'ธันวาคม'
		END
	ELSE IF @v_vchLocal = '1033'
		BEGIN
			--Eng
			IF @v_intMonth = 1
				SET @v_vchMonthName = 'January'
			ELSE IF @v_intMonth = 2
				SET @v_vchMonthName = 'February'
			ELSE IF @v_intMonth = 3
				SET @v_vchMonthName = 'March'
			ELSE IF @v_intMonth = 4
				SET @v_vchMonthName = 'April'
			ELSE IF @v_intMonth = 5
				SET @v_vchMonthName = 'May'
			ELSE IF @v_intMonth = 6
				SET @v_vchMonthName = 'June'
			ELSE IF @v_intMonth = 7
				SET @v_vchMonthName = 'July'
			ELSE IF @v_intMonth = 8
				SET @v_vchMonthName = 'August'
			ELSE IF @v_intMonth = 9
				SET @v_vchMonthName = 'September'
			ELSE IF @v_intMonth = 10
				SET @v_vchMonthName = 'October'
			ELSE IF @v_intMonth = 11
				SET @v_vchMonthName = 'November'
			ELSE IF @v_intMonth = 12
				SET @v_vchMonthName = 'December'
		END
		
		RETURN @v_vchMonthName
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_get_resouce_value]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-08-24
-- Description:	Get resource
-- =============================================
CREATE FUNCTION [dbo].[usf_get_resouce_value]
(
	@in_vchApplicationID	NVARCHAR(40),
	@in_vchResourceName		NVARCHAR(50),
	@in_intLocaleID			INT,
	@in_vchParam1			NVARCHAR(50),
	@in_vchParam2			NVARCHAR(50),
	@in_vchParam3			NVARCHAR(50) = null,
	@in_vchParam4			NVARCHAR(50) = null,
	@in_vchParam5			NVARCHAR(50) = null
)
RETURNS nvarchar(250)
AS
BEGIN

	Declare @v_vchTextValue NVARCHAR(250)
		
		-------------------------------------------------------------------------  
	 --  Set Resource based on detail in the Resource Detail table  
	 -------------------------------------------------------------------------  
		SELECT @v_vchTextValue = RSD.value  
		 FROM t_com_resource_detail RSD, t_com_resource_master RSM  
		 WHERE RSM.resource_master_id = RSD.resource_master_id  
		 AND RSM.resource_name = @in_vchResourceName  
		 AND RSD.locale_id = @in_intLocaleID  
		 AND RSM.app_id = @in_vchApplicationID  
	   
	 -------------------------------------------------------------------------  
	 --  No Detail Records so set by Default in Master Record  
	 -------------------------------------------------------------------------  
	 IF @v_vchTextValue IS NULL  
	 BEGIN  
		SELECT @v_vchTextValue = default_value  
		FROM t_com_resource_master RSM  
		WHERE RSM.resource_name = @in_vchResourceName  
	 END  
	   
	 -------------------------------------------------------------------------  
	 --  No Value in Master Record or No Master so Set a Default   
	 -------------------------------------------------------------------------  
	 IF @v_vchTextValue IS NULL  
	 BEGIN  
		SELECT @v_vchTextValue = @in_vchResourceName --'NO RESOURCE CONFIGURED'  
	 END  
	  
	-----------------------------------------------------------------------------------  
	--                            Exit the Process  
	-----------------------------------------------------------------------------------  
	EXIT_LABEL:  
		
		set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param1',isnull(@in_vchParam1,''));
		set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param2',isnull(@in_vchParam2,''));
		set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param3',isnull(@in_vchParam3,''));
		set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param4',isnull(@in_vchParam4,''));
		set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param5',isnull(@in_vchParam5,''));
		
		-- Always leave from here.  
		return @v_vchTextValue

END
GO
