CREATE FUNCTION [dbo].[usf_GetRuleValue]
(
    @in_vchRuleCode NVARCHAR(40),
    @in_vchWarehouseID NVARCHAR(50),
    @in_vchRuleType NVARCHAR(40) = 'WH_CONTROL'
    )
RETURNS NVARCHAR(30)
AS
BEGIN
    DECLARE
    -- Local Variables
    @v_vchRuleID	varchar(40),
    @v_vchValue NVARCHAR(30)
    
    
    IF @in_vchWarehouseID IS NULL
    BEGIN
		SELECT  @v_vchValue = value, @v_vchRuleID = rule_id 
		FROM t_wms_rule
		WHERE rule_code = @in_vchRuleCode
		AND type = @in_vchRuleType
	END
	ELSE		
		BEGIN
