			FROM v_wms_wh_rule
			WHERE rule_code = @in_vchRuleCode
			AND wh_id = @in_vchWarehouseID
			AND type = @in_vchRuleType
		END		
	
	IF @v_vchValue IS NULL SET @v_vchValue = 'NO VALUE IN TABLE'

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:
    -- Always leave from here.
    RETURN @v_vchValue 
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_number_to_thai_baht]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[usf_number_to_thai_baht]
(
	@in_fltNumber FLOAT 
)
RETURNS VARCHAR(8000)
AS 
BEGIN
	DECLARE @number Numeric(38 , 0)
	DECLARE @decimal INT
	DECLARE @loops INT
	DECLARE @bigLoops INT
	DECLARE @counter INT
	DECLARE @bigCount INT
	DECLARE @mod INT
	DECLARE @numbersTable TABLE (number CHAR(1), word VARCHAR(10))
	DECLARE @numbersDigit TABLE (number CHAR(1), word VARCHAR(10))
	DECLARE @inputNumber VARCHAR(38)
	DECLARE @inputNumber1 VARCHAR(38)
	DECLARE @inputDecimal VARCHAR(2)
	DECLARE @charNumber CHAR(1)
	DECLARE @outputString VARCHAR(8000)
	DECLARE @outputString1 VARCHAR(8000)
	DECLARE @outputChar VARCHAR(10)
	DECLARE @outputChar1 VARCHAR(10)
	DECLARE @nextNumber CHAR(1)

	IF @in_fltNumber = 0 
		RETURN 'ศูนย์บาท'

	-- insert data for the numbers and words
	INSERT INTO @NumbersTable
	SELECT ' ', '' UNION ALL SELECT '0', ''
	UNION ALL SELECT '1', 'หนึ่ง' UNION ALL SELECT '2', 'สอง'
	UNION ALL SELECT '3', 'สาม' UNION ALL SELECT '4', 'สี่'
	UNION ALL SELECT '5', 'ห้า' UNION ALL SELECT '6', 'หก'
	UNION ALL SELECT '7', 'เจ็ด' UNION ALL SELECT '8', 'แปด'
	UNION ALL SELECT '9', 'เก้า'

	INSERT INTO @NumbersDigit
	SELECT '1', '' UNION ALL SELECT '2', 'สิบ'
	UNION ALL SELECT '3', 'ร้อย' UNION ALL SELECT '4', 'พัน'
	UNION ALL SELECT '5', 'หมื่น' UNION ALL SELECT '6', 'แสน'

	SET @number = FLOOR(@in_fltNumber)
	SET @decimal = FLOOR((ROUND(@in_fltNumber - FLOOR(@in_fltNumber),2)) * 100)
	SET @inputNumber1 = CONVERT(VARCHAR(38), @number)
	SET @inputDecimal = CONVERT(VARCHAR(2), @decimal)
	SET @bigLoops = FLOOR(LEN(@inputNumber1) / 6) + 1
	SET @mod = LEN(@inputNumber1) % 6
	SET @bigCount = 1
	SET @outputString = ''

	WHILE @bigCount <= @bigLoops 
		BEGIN
			IF @bigCount = 1 
				BEGIN
					SET @inputNumber = LEFT(@inputNumber1,@mod)
					SET @inputNumber1 = RIGHT(@inputNumber1,LEN(@inputNumber1)-@mod)
				END
			ELSE 
				BEGIN
					SET @inputNumber = LEFT(@inputNumber1,6) 
					IF @bigCount < @bigLoops
						SET @inputNumber1 = RIGHT(@inputNumber1,LEN(@inputNumber1)-6)
				END

			SET @outputString1 = ''
			SET @counter = 1
			SET @loops = LEN(@inputNumber)
			SET @nextNumber = ''
	
			WHILE 1 <= @loops 
				BEGIN
					SET @charNumber = SUBSTRING(@inputNumber,@loops,1)
					SET @nextNumber = SUBSTRING(@inputNumber,@loops-1,1)
					
					SELECT @outputChar = word FROM @NumbersTable WHERE @charNumber = number
					
					SELECT @outputChar1 = word FROM @NumbersDigit WHERE CONVERT(CHAR(1),@counter) = number
					
					IF @charNumber = '1' AND LEN(@inputNumber) > 1 AND @counter = 1 AND @nextNumber > '0'
						SET @outputChar = 'เอ็ด'
					IF @charNumber = '1' AND LEN(@inputNumber) >= 2 AND @counter = 2 
						SET @outputChar = ''
					IF @charNumber = '2' AND LEN(@inputNumber) >= 2 AND @counter = 2 
						SET @outputChar = 'ยี่'
					IF @charNumber = '0' SET @outputChar1 = ''
					
					SELECT @outputString1 = @outputChar + @outputChar1 + @outputString1
						,@counter = @counter + 1
						,@loops = @loops - 1
				END

			IF @bigCount < @bigLoops
				IF @outputString1 <> '' 
					SET @outputString = @outputString + @outputString1 + 'ล้าน'
				IF @bigCount >= @bigLoops 
					SET @outputString = @outputString + @outputString1 + 'บาท'
				SET @bigCount = @bigCount + 1
		END

	-- Decimal
	IF LEN(@inputDecimal)= 1 
		SET @inputDecimal = '0' + @inputDecimal
	SET @inputNumber = @inputDecimal
	SET @counter = 1
	SET @loops = LEN(@inputNumber)
	SET @outputString1 = ''
	SET @nextNumber = SUBSTRING(@inputNumber,@loops-1,1)

	WHILE 1 <= @loops 
		BEGIN
			SET @charNumber = SUBSTRING(@inputNumber,@loops,1)

			SELECT @outputChar = word FROM @NumbersTable WHERE @charNumber = number
			SELECT @outputChar1 = word FROM @NumbersDigit WHERE CONVERT(CHAR(1),@counter) = number

			IF @charNumber = '1' AND LEN(@inputNumber) > 1 AND @counter = 1 AND @nextNumber > '0'
				SET @outputChar = 'เอ็ด'
			IF @charNumber = '1' AND LEN(@inputNumber) >= 2 AND @counter = 2 
				SET @outputChar = ''
			IF @charNumber = '2' AND LEN(@inputNumber) >= 2 AND @counter = 2 
				SET @outputChar = 'ยี่'
			IF @charNumber = '0'
				SET @outputChar1 = ''
			SELECT @outputString1 = @outputChar + @outputChar1 + @outputString1,
				@counter = @counter + 1,
				@loops = @loops - 1
		END

	IF @inputDecimal = '00'
		SET @outputString = @outPutString + 'ถ้วน'
	ELSE 
		SET @outputString = @outputString + @outputString1 + 'สตางค์'

	RETURN @outputString -- return the result
	 
END
GO
/****** Object:  UserDefinedFunction [dbo].[usf_pick_qty_more_order_qty]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[usf_pick_qty_more_order_qty]
(
	-- Add the parameters for the function here
	@wh_id						NVARCHAR(50),
	@outbound_order_number		NVARCHAR(50),
	@item_number				NVARCHAR(50),
	@qty_issue					INT,
	@uom_prompt					NVARCHAR(50)
)
RETURNS bit
AS
BEGIN

	-- Declare Variable.
	DECLARE @qty_remain_pick					INT,
			@order_uom_prompt					NVARCHAR(50),
			@primary_uom						NVARCHAR(50),
			@issue_conversion_factor			FLOAT,
			@order_conversion_factor			FLOAT,
			@Result								BIT
	
	-- Get remain quantity
	SELECT	@qty_remain_pick = quantity_remain_pick,
			@order_uom_prompt = uom_prompt
	FROM	v_wms_outbound_pick_detail
	WHERE	wh_id = @wh_id
	AND		outbound_order_number = @outbound_order_number
	AND		item_number = @item_number
	
	
	IF (@uom_prompt = @order_uom_prompt)
	BEGIN
		IF (@qty_remain_pick >= @qty_issue)
		BEGIN
			Set @Result = 0;
		END
		ELSE
		BEGIN
			Set @result = 1;
		END
	END
	ELSE
	BEGIN
		
		-- Convert issue qty.
		SELECT	@issue_conversion_factor = conversion_factor
		FROM	v_wms_item_uom
		WHERE	item_number = @item_number
		AND		uom = @uom_prompt
				
		-- Convert order plan qty.
		SELECT	@order_conversion_factor = conversion_factor 
		FROM	v_wms_item_uom
		WHERE	item_number = @item_number
		AND		uom = @order_uom_prompt
		
		IF ((@issue_conversion_factor * @qty_issue) > = (@order_conversion_factor * @qty_remain_pick))
		BEGIN
			Set @Result = 0;
		END
		ELSE
		BEGIN
			Set @result = 1;
		END
		
	END
	
	RETURN @Result;
	
END
GO
