SELECT inv.wh_item_master_id
, item.item_master_id
, item.item_number
, item.description
, inv.owner_id
, own.owner_code
, SUM(ISNULL(inv.quantity, 0)) - SUM(ISNULL(inv.quantity_allocated, 0)) AS sumInv, uom.uom
FROM dbo.t_wms_inventory AS inv
INNER JOIN dbo.t_wms_inventory_status AS invs ON inv.inventory_status_id = invs.inventory_status_id
LEFT OUTER JOIN (SELECT inventory_id,attribute_group_id, attribute_value as expiry_date
				 FROM t_wms_inventory_attribute
				 WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248' 
				 ) invExp ON (invExp.inventory_id = inv.inventory_id AND invExp.attribute_group_id = inv.attribute_group_id)
LEFT OUTER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT OUTER JOIN dbo.t_wms_owner AS own ON inv.owner_id = own.owner_id 
LEFT OUTER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id 
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES' 
WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
AND (invs.inv_status = 'Available') 
AND (inv.wh_item_master_id IN (SELECT DISTINCT obDT.wh_item_master_id FROM dbo.t_wms_outbound_master obMS
								INNER JOIN dbo.t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
								WHERE obMS.order_status = 'OPEN'))
AND (CASE ISNULL(invExp.expiry_date,'') WHEN '' THEN '' ELSE invExp.expiry_date END) >= (CASE ISNULL(invExp.expiry_date,'') WHEN '' THEN '' ELSE CONVERT(VARCHAR(8),GETDATE()+ 1 ,112) END)
GROUP BY inv.wh_item_master_id
, item.item_master_id
, item.item_number
, item.description
, inv.owner_id
, own.owner_code
, uom.uom



GO
