/****** Object:  View [dbo].[v_wms_report_receipt_picking_slip]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_receipt_picking_slip]
AS
SELECT dbo.t_wms_receipt_header.inbound_order_master_id
	 , dbo.t_wms_inbound_master.inbound_order_number
     , dbo.t_wms_inbound_master.order_type
     , dbo.t_wms_inbound_master.order_status
     , dbo.t_wms_inbound_master.create_date
     , dbo.t_wms_inbound_master.wh_id
     , dbo.t_wms_inbound_master.owner_code
	 , dbo.t_wms_inbound_master.close_date
     , dbo.t_wms_inbound_detail.quantity_order
     , dbo.t_wms_inbound_detail.quantity_receive
     , dbo.t_wms_inbound_detail.uom
	 , dbo.t_wms_receipt_header.receipt_number
     , dbo.t_wms_receipt_header.user_def1
 	 , SUM(dbo.t_wms_receipt_detail.quantity_received) quantity_received
     , dbo.t_wms_receipt_detail.location_received 
	 , dbo.t_wms_item.item_number
     , dbo.t_wms_item.description
     , dbo.t_wms_supplier.supplier_code
     , dbo.t_wms_supplier.supplier_name   
     , loc.erp_location
FROM dbo.t_wms_inbound_master
     INNER JOIN dbo.t_wms_inbound_detail ON dbo.t_wms_inbound_detail.inbound_order_master_id = dbo.t_wms_inbound_master.inbound_order_master_id
	 INNER JOIN dbo.t_wms_receipt_header ON dbo.t_wms_receipt_header.inbound_order_master_id = dbo.t_wms_inbound_master.inbound_order_master_id
     INNER JOIN dbo.t_wms_receipt_detail ON dbo.t_wms_receipt_detail.receipt_header_id = dbo.t_wms_receipt_header.receipt_header_id 
	 INNER JOIN dbo.t_wms_item ON dbo.t_wms_item.item_number = dbo.t_wms_receipt_detail.item_number
							  AND dbo.t_wms_item.item_master_id = dbo.t_wms_inbound_detail.item_master_id
     INNER JOIN dbo.t_wms_supplier ON dbo.t_wms_supplier.supplier_id = dbo.t_wms_inbound_master.supplier_id
     INNER JOIN dbo.t_wms_location loc ON loc.location = dbo.t_wms_receipt_detail.location_received
GROUP BY dbo.t_wms_receipt_header.inbound_order_master_id
	 , dbo.t_wms_inbound_master.inbound_order_number
     , dbo.t_wms_inbound_master.order_type
     , dbo.t_wms_inbound_master.order_status
     , dbo.t_wms_inbound_master.create_date
     , dbo.t_wms_inbound_master.wh_id
     , dbo.t_wms_inbound_master.owner_code
	 , dbo.t_wms_inbound_master.close_date
     , dbo.t_wms_inbound_detail.quantity_order
     , dbo.t_wms_inbound_detail.quantity_receive
     , dbo.t_wms_inbound_detail.uom
	 , dbo.t_wms_receipt_header.receipt_number
     , dbo.t_wms_receipt_header.user_def1
     , dbo.t_wms_receipt_detail.location_received
	 , dbo.t_wms_item.item_number
     , dbo.t_wms_item.description
     , dbo.t_wms_supplier.supplier_code
     , dbo.t_wms_supplier.supplier_name   
     , loc.erp_location
HAVING (dbo.t_wms_inbound_master.order_status IN ('RECEIVING', 'CLOSE'))
GO
