/****** Object:  View [dbo].[v_wms_report_return_adjust_in]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_return_adjust_in]
AS

SELECT
tmp.customer_code
,tmp.customer_name
,tmp.item_category
,tmp.item_number
,tmp.description
,tmp.serial_number
,tmp.after_lot_number
,tmp.after_expiry_date
,tmp.quantity
,tmp.create_date
,tmp.create_by
,tmp.delivery_date
,tmp.delivery_number
,tmp.customer_id
,tmp.category_id
,tmp.item_master_id
,tmp.cate_description
FROM
(
SELECT isnull(obMS.customer_code,tLog.location) as customer_code
		,isnull(obMS.customer_name,(select top(1) customer_name from t_wms_customer where customer_code = tLog.location)) as customer_name
		,cate.item_category
		,item.item_number
		,item.description
		,tLog.serial_number
		,tLog.after_lot_number
		,tLog.after_expiry_date
		,tLog.quantity
		,tLog.create_date
		,tLog.create_by
		,obDV.delivery_date
		,obDV.delivery_number
		,obms.customer_id
		,cate.category_id
		,item.item_master_id
		,cate.description as cate_description
		,ROW_NUMBER() OVER(PARTITION BY tLog.serial_number ORDER BY tLog.create_date DESC) AS is_max
FROM t_com_tran_log tLog
LEFT JOIN t_wms_owner own ON tLog.to_owner = own.owner_code
INNER JOIN (SELECT ob.outbound_order_number
					,wh.wh_master_id
					,ob.wh_id
					,ob.owner_code
					,ob.delivery_number
					,ob.delivery_date
					,ob.serial_number
					,ROW_NUMBER() OVER(PARTITION BY ob.serial_number ORDER BY ob.create_date DESC) AS is_max
				FROM t_wms_outbound_delivery ob
				INNER JOIN t_wms_wh wh ON ob.wh_id = wh.wh_id
				)obDV ON tLog.serial_number = obDV.serial_number and is_max = 1
LEFT JOIN t_wms_outbound_master obMS ON obDV.outbound_order_number = obMS.outbound_order_number AND obMS.wh_master_id = obDV.wh_master_id
LEFT JOIN t_wms_item item ON tLog.item_number = item.item_number AND own.owner_id = item.owner_id
LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
WHERE tLog.tran_type = 'INV_RETURN'
AND tLog.sub_tran_type = 'INV_RETURN_SERIAL'
) as tmp WHERE tmp.is_max = 1

GO
/****** Object:  View [dbo].[v_outbound_inv_viewer_sum_qty_item_diff]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_outbound_inv_viewer_sum_qty_item_diff]
AS
SELECT tOutbound.wh_item_master_id
	, tOutbound.item_number
	, tOutbound.item_description
	, tOutbound.owner_id
	, tOutbound.owner_code
	, ISNULL(tInv.sumInv, 0) AS sumInv
	, ISNULL(tInv.sumInv, 0) - ISNULL(tOutbound.quantity_order, 0) AS quantity_diff
	, tOutbound.uom
	, tOutbound.item_category
	, tOutbound.category_id
	, tOutbound.wh_master_id
FROM dbo.v_outbound_inv_viewer_sum_qty_by_item tInv
RIGHT OUTER JOIN (SELECT wh_item_master_id
						,item_number
						,item_description
						,owner_id
						,owner_code 
						,uom
						,item_category
						,category_id
						,wh_master_id
						,SUM(ISNULL(quantity_order,0)) AS quantity_order
				  FROM dbo.v_outbound_viewer_sum_qty_by_item
				  GROUP BY wh_item_master_id
						,item_number
						,item_description
						,owner_id
						,owner_code 
						,uom
						,item_category
						,category_id
						,wh_master_id
				  ) tOutbound ON tInv.owner_id = tOutbound.owner_id 
							  AND tInv.wh_item_master_id = tOutbound.wh_item_master_id


GO
