/****** Object:  View [dbo].[v_wms_dashboard_warehouse_virtual]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE view [dbo].[v_wms_dashboard_warehouse_virtual] as

SELECT 
wh.wh_master_id
,wh.wh_id
,wh.x_max
,wh.y_max
,zone.zone_id
,zone.zone
,zone.zone_type
,loc.location_id
,loc.location
,loc.loc_type
,loc.location_level
,loc.capacity_qty
,loc.x_cordinate
,loc.y_cordinate
,loc.length
,loc.width
,loc.height
,loc.lpn_controlled
,loc.mix_owners
,loc.mix_lot
,loc.mix_expiry_dates
,loc.mix_items
,loc.mix_status
,loc.mix_attribute1
,loc.mix_attribute2
,loc.mix_attribute3
,loc.mix_attribute4
,loc.mix_attribute5
,inv.current_qty
,inv.current_qty - loc.capacity_qty as available_qty
,(inv.current_qty * 100) / loc.capacity_qty as usage_qty
FROM t_wms_location as loc
INNER JOIN t_wms_wh as wh on loc.wh_master_id = wh.wh_master_id
LEFT JOIN t_wms_zone_location as zone_loc on loc.location_id = zone_loc.location_id
LEFT JOIN t_wms_zone as zone on zone_loc.zone_id = zone.zone_id 
LEFT JOIN (
	select
	location_id 
	,sum(quantity) as current_qty
	from v_wms_inventory_data as i
	--where i.lpn_controlled = 'YES'
	group by 
	location_id) as inv on loc.location_id = inv.location_id



