SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_single_comment_for_outbound_report]
AS
SELECT DISTINCT SS.outbound_order_master_id,
                             (SELECT        ' || ' + US.comment
                               FROM            t_wms_outbound_comment US
                               WHERE        US.outbound_order_master_id = SS.outbound_order_master_id
                               ORDER BY US.outbound_order_master_id, US.sequence ASC FOR XML PATH('')) [SECTORS/USERS]
FROM            t_wms_outbound_comment SS
GROUP BY SS.comment, SS.outbound_order_master_id


