/****** Object:  View [dbo].[v_wms_outbound_pick_detail_print]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_outbound_pick_detail_print]
AS
SELECT     dbo.t_wms_wh.wh_id
, dbo.t_wms_outbound_master.outbound_order_master_id
, convert(varchar(36),dbo.t_wms_outbound_master.outbound_order_master_id) as str_outbound_order_master_id
, dbo.t_wms_outbound_pick_master.outbound_order_number
, dbo.t_wms_outbound_pick_detail.create_date
, dbo.t_wms_item.item_number
, dbo.t_wms_item.description
, dbo.t_wms_item.dg_code
, dbo.t_wms_outbound_detail.price
, dbo.t_wms_outbound_detail.grade
, dbo.t_wms_outbound_pick_detail.lpn
, dbo.t_wms_outbound_pick_detail.quantity_plan
, dbo.t_wms_location.location
, dbo.t_wms_outbound_master.order_type
, ISNULL(dbo.t_wms_customer.customer_code, N'') 
	+ N' ' + ISNULL(dbo.t_wms_customer.customer_name, N'') 
	+ N' ' + ISNULL(dbo.t_wms_customer.addr_line_1, N'') 
	+ N' ' + ISNULL(dbo.t_wms_customer.addr_line_2, N'') 
	+ N' ' + ISNULL(dbo.t_wms_customer.addr_line_3, N'') AS customer_code_name
, ISNULL(dbo.t_wms_outbound_master.ship_to_code, N'') 
	+ N' ' + ISNULL(dbo.t_wms_outbound_master.ship_to_name, N'')  AS ShipTo
, dbo.t_wms_customer.customer_code
, dbo.t_wms_outbound_pick_detail.parent_lpn
, dbo.t_wms_outbound_pick_detail.lot_number
, dbo.t_wms_outbound_pick_detail.expiry_date
, dbo.v_wms_single_comment_for_outbound_report.[SECTORS/USERS] AS comment
, dbo.t_wms_outbound_master.user_def1
, dbo.t_wms_outbound_master.user_def2
, dbo.t_wms_outbound_master.user_def3
, dbo.t_wms_outbound_master.user_def4
, dbo.t_wms_outbound_master.delivery_date_plan
, dbo.t_wms_item_uom.uom
, dbo.t_wms_item_uom.uom_prompt
FROM dbo.t_wms_outbound_pick_master 
INNER JOIN dbo.t_wms_outbound_pick_detail ON dbo.t_wms_outbound_pick_master.outbound_pick_master_id = dbo.t_wms_outbound_pick_detail.outbound_pick_master_id 
INNER JOIN dbo.t_wms_wh_item ON dbo.t_wms_outbound_pick_detail.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
INNER JOIN dbo.t_wms_wh ON dbo.t_wms_outbound_pick_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
INNER JOIN dbo.t_wms_outbound_detail ON dbo.t_wms_outbound_pick_detail.outbound_order_detail_id = dbo.t_wms_outbound_detail.outbound_order_detail_id 
INNER JOIN dbo.t_wms_item_uom on dbo.t_wms_item_uom.item_uom_id = dbo.t_wms_outbound_detail.item_uom_id
INNER JOIN dbo.t_wms_location ON dbo.t_wms_outbound_pick_detail.location_id = dbo.t_wms_location.location_id 
INNER JOIN dbo.t_wms_outbound_master ON dbo.t_wms_outbound_detail.outbound_order_master_id = dbo.t_wms_outbound_master.outbound_order_master_id 
LEFT OUTER JOIN dbo.v_wms_single_comment_for_outbound_report ON dbo.t_wms_outbound_master.outbound_order_master_id = dbo.v_wms_single_comment_for_outbound_report.outbound_order_master_id 
LEFT OUTER JOIN dbo.t_wms_customer ON dbo.t_wms_outbound_master.customer_code = dbo.t_wms_customer.customer_code and dbo.t_wms_outbound_master.owner_id = dbo.t_wms_customer.owner_id




GO
/****** Object:  View [dbo].[v_wms_visual_location_map]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_visual_location_map]
AS
SELECT        wh.wh_master_id, wh.wh_id, wh.wh_name, lo.location_id, lo.location, ISNULL(lo.location_level, 0) AS location_level, lo.loc_type, lo.x_cordinate, lo.y_cordinate, 
                         lo.lpn_controlled, ISNULL(lo.capacity_qty, 9999999) AS capacity_qty, z.zone_id, z.zone, R1.wh_item_master_id, R1.owner_id, R1.item_master_id, R1.item_number, 
                         R1.category_id, R1.lpn, R1.quantity
FROM            dbo.t_wms_location AS lo LEFT OUTER JOIN
                         dbo.t_wms_wh AS wh ON lo.wh_master_id = wh.wh_master_id LEFT OUTER JOIN
                         dbo.t_wms_zone_location AS zl ON lo.location_id = zl.location_id LEFT OUTER JOIN
                         dbo.t_wms_zone AS z ON z.zone_id = zl.zone_id LEFT OUTER JOIN
                             (SELECT        inv.wh_master_id, inv.location_id, inv.wh_item_master_id, inv.owner_id, item.item_master_id, item.item_number, item.category_id, inv.lpn, 
                                                         inv.quantity
                               FROM            dbo.t_wms_inventory AS inv LEFT OUTER JOIN
                                                         dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id LEFT OUTER JOIN
                                                         dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id) AS R1 ON lo.location_id = R1.location_id AND 
                         wh.wh_master_id = R1.wh_master_id


GO
