dbo.t_wms_outbound_master.outbound_order_number, dbo.t_wms_outbound_master.owner_id, dbo.t_wms_owner.owner_code, 
dbo.t_wms_outbound_master.order_type, dbo.t_wms_outbound_master.order_status, dbo.t_wms_outbound_master.order_date, 
dbo.t_wms_outbound_master.loading_date_plan, dbo.t_wms_outbound_master.delivery_date_plan, dbo.t_wms_outbound_master.ship_date_plan, 
dbo.t_wms_outbound_master.loading_date_actual, dbo.t_wms_outbound_master.delivery_date_actual, dbo.t_wms_outbound_master.ship_date_actual, 
dbo.t_wms_outbound_master.description, dbo.t_wms_outbound_master.department, dbo.t_wms_outbound_master.carrier_id, 
dbo.t_wms_outbound_master.truck_type_id,
dbo.t_wms_truck_type.truck_type,
dbo.t_wms_outbound_master.truck_no, dbo.t_wms_outbound_master.driver_name, 
dbo.t_wms_outbound_master.driver_license, dbo.t_wms_outbound_master.container_no, dbo.t_wms_outbound_master.seal_no, 
dbo.t_wms_outbound_master.load_id, dbo.t_wms_outbound_master.load_sequence_number, dbo.t_wms_outbound_master.tracking_number, 
dbo.t_wms_outbound_master.rush_order, dbo.t_wms_outbound_master.back_order_flag, dbo.t_wms_outbound_master.customer_order_number, 
dbo.t_wms_outbound_master.customer_purchase_order, dbo.t_wms_outbound_master.customer_code, dbo.t_wms_outbound_master.customer_name, 
dbo.t_wms_customer.customer_name AS customer_code_name, dbo.t_wms_outbound_master.cus_description, 
dbo.t_wms_outbound_master.cus_addr_line_1, dbo.t_wms_outbound_master.cus_addr_line_2, dbo.t_wms_outbound_master.cus_addr_line_3, 
dbo.t_wms_outbound_master.cus_city, dbo.t_wms_outbound_master.cus_province, dbo.t_wms_outbound_master.cus_postal_code, 
dbo.t_wms_outbound_master.cus_country_code, dbo.t_wms_outbound_master.cus_country_name, dbo.t_wms_outbound_master.cus_contact, 
dbo.t_wms_outbound_master.cus_phone, dbo.t_wms_outbound_master.cus_fax, dbo.t_wms_outbound_master.cus_email, 
dbo.t_wms_outbound_master.ship_to_code, dbo.t_wms_outbound_master.ship_to_name, dbo.t_wms_outbound_master.ship_to_description, 
dbo.t_wms_outbound_master.ship_to_addr_line_1, dbo.t_wms_outbound_master.ship_to_addr_line_2, dbo.t_wms_outbound_master.ship_to_addr_line_3, 
dbo.t_wms_outbound_master.ship_to_city, dbo.t_wms_outbound_master.ship_to_province, dbo.t_wms_outbound_master.ship_to_postal_code, 
dbo.t_wms_outbound_master.ship_to_country_code, dbo.t_wms_outbound_master.ship_to_country_name, dbo.t_wms_outbound_master.ship_to_contact, 
dbo.t_wms_outbound_master.ship_to_phone, dbo.t_wms_outbound_master.ship_to_fax, dbo.t_wms_outbound_master.ship_to_email, 
dbo.t_wms_outbound_master.user_def1, dbo.t_wms_outbound_master.user_def2, dbo.t_wms_outbound_master.user_def3, 
dbo.t_wms_outbound_master.user_def4, dbo.t_wms_outbound_master.user_def5, dbo.t_wms_outbound_master.user_def6, 
dbo.t_wms_outbound_master.user_def7, dbo.t_wms_outbound_master.user_def8, dbo.t_wms_outbound_master.user_def9, 
dbo.t_wms_outbound_master.user_def10, dbo.t_wms_outbound_master.cancel_date, dbo.t_wms_outbound_master.cancel_by, 
dbo.t_wms_outbound_master.cancel_remark, dbo.t_wms_outbound_master.grouping_no, dbo.t_wms_outbound_master.copy_no, 
dbo.t_wms_outbound_master.create_date, CONVERT(nvarchar, dbo.t_wms_outbound_master.create_date, 112) AS create_date_filter, 
dbo.t_wms_outbound_master.create_by, CONVERT(nvarchar, dbo.t_wms_outbound_master.update_date, 112) AS update_date_filter, 
dbo.t_wms_outbound_master.update_by,  dbo.t_wms_outbound_master.close_by, dbo.t_wms_outbound_master.close_date, close_remark
FROM dbo.t_wms_outbound_master 
LEFT OUTER JOIN dbo.t_wms_customer ON dbo.t_wms_outbound_master.owner_id = dbo.t_wms_customer.owner_id 
                     AND dbo.t_wms_outbound_master.customer_id = dbo.t_wms_customer.customer_id 
LEFT OUTER JOIN dbo.t_wms_wh ON dbo.t_wms_outbound_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
LEFT OUTER JOIN dbo.t_wms_owner ON dbo.t_wms_outbound_master.owner_id = dbo.t_wms_owner.owner_id
LEFT OUTER JOIN dbo.t_wms_truck_type ON dbo.t_wms_outbound_master.truck_type_id =  dbo.t_wms_truck_type.truck_type_id

GO
