CREATE VIEW [dbo].[v_Order_Header]
AS
SELECT        dbo.v_wms_outbound_master.customer_order_number AS [Invoice no], dbo.v_wms_outbound_master.cus_province, dbo.t_wms_carrier.carrier_name, dbo.v_wms_outbound_master.loading_date_actual, 
                         dbo.v_wms_outbound_master.delivery_date_actual, dbo.v_wms_outbound_master.user_def7 AS Consignment_No, dbo.v_wms_outbound_master.user_def2 AS Order_Reason, 
                         dbo.v_wms_outbound_master.delivery_date_plan, dbo.v_wms_outbound_master.ship_date_actual, dbo.v_wms_outbound_master.customer_code_name, dbo.v_wms_outbound_master.order_type, 
                         dbo.v_wms_outbound_master.order_status, dbo.v_wms_outbound_master.customer_name, dbo.v_wms_outbound_master.customer_code, dbo.v_wms_outbound_master.ship_date_plan, 
                         dbo.v_wms_outbound_master.outbound_order_number, dbo.v_wms_outbound_master.create_date, dbo.v_wms_outbound_master.close_date AS POD_Date, 
                         (CASE WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' THEN 'UPC' ELSE 'BKK' END) AS Area, (CASE WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' AND CONVERT(TIME, 
                         dbo.v_wms_outbound_master.create_date) <= '14:00:00' THEN 'Morning Cut Off' WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         > '14:00:00' THEN 'Afternoon Cut Off' WHEN dbo.t_wms_carrier.carrier_name NOT LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         <= '11:00:00' THEN 'Morning Cut Off' WHEN dbo.t_wms_carrier.carrier_name NOT LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         > '11:00:00' THEN 'Afternoon Cut Off' ELSE 'Afternoon Cut Off' END) AS Cut_Off_Time, dbo.v_wms_outbound_master.user_def3 AS Remark_Cut_Off, dbo.t_wms_customer.route_code, 
                         dbo.t_wms_customer.route_name
FROM            dbo.t_wms_customer INNER JOIN
                         dbo.v_wms_outbound_master ON dbo.t_wms_customer.customer_code = dbo.v_wms_outbound_master.customer_code RIGHT OUTER JOIN
                         dbo.t_wms_carrier ON dbo.v_wms_outbound_master.carrier_id = dbo.t_wms_carrier.carrier_id
GO
/****** Object:  View [dbo].[v_wms_dashb_center_card_inbound]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_dashb_center_card_inbound]
AS

WITH tInboundPast AS
(
	SELECT ibMS.wh_master_id
		,ibMS.wh_id
		,SUM(ISNULL(ibDT.quantity_order,0)) AS quantity_order 
	FROM t_wms_inbound_master ibMS
	INNER JOIN t_wms_inbound_detail ibDT on ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	WHERE ibMS.order_status IN ('RECEIVING','OPEN')
	AND ISNULL(ibDT.quantity_receive,0) < ISNULL(ibDT.quantity_order,0) 
	AND (CASE WHEN ibMS.expected_delivery_date IS NULL THEN CONVERT(DATE,ibDT.create_date) ELSE CONVERT(DATE,ibMS.expected_delivery_date) END) < CONVERT(DATE,GETDATE())
	GROUP BY ibMS.wh_master_id,ibMS.wh_id
)
,tInboundDaily AS
(
	SELECT ibMS.wh_master_id
		,ibMS.wh_id 
		,SUM(ISNULL(ibDT.quantity_order,0)) AS quantity_order 
	FROM t_wms_inbound_master ibMS
	INNER JOIN t_wms_inbound_detail ibDT on ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	WHERE (CASE WHEN ibMS.expected_delivery_date IS NULL THEN CONVERT(DATE,ibDT.create_date) ELSE CONVERT(DATE,ibMS.expected_delivery_date) END) = CONVERT(DATE,GETDATE())
	GROUP BY ibMS.wh_master_id,ibMS.wh_id
)
SELECT ISNULL(ibD.wh_master_id,ibP.wh_master_id) AS wh_master_id
	,ISNULL(ibD.wh_id,ibP.wh_id) AS wh_id
	,ISNULL(ibD.quantity_order,0) + isnull(ibP.quantity_order,0) as quantity_order
FROM tInboundDaily ibD
FULL JOIN tInboundPast ibP on ibD.wh_master_id = ibP.wh_master_id
GO
