CREATE VIEW [dbo].[v_wms_warranty]
AS
SELECT        warranty_id, host_record_id, record_type, processing_code, processing_status, wh_master_id, owner_id, reason_id, location_id, warranty_number, warranty_period, 
                         warranty_expire, warranty_printed, warranty_status, outbound_order_master_id, outbound_order_number, outbound_order_detail_id, order_line_id AS line_number, 
                         serial_number, wh_item_master_id, load_number, print_status, create_date, create_by,
                             (SELECT        item.item_number
                               FROM            dbo.t_wms_wh_item AS whitem LEFT OUTER JOIN
                                                         dbo.t_wms_item AS item ON whitem.item_master_id = item.item_master_id
                               WHERE        (whitem.wh_item_master_id = warr.wh_item_master_id)) AS item_number,
                             (SELECT        item.description
                               FROM            dbo.t_wms_wh_item AS whitem LEFT OUTER JOIN
                                                         dbo.t_wms_item AS item ON whitem.item_master_id = item.item_master_id
                               WHERE        (whitem.wh_item_master_id = warr.wh_item_master_id)) AS description,
                             (SELECT        location
                               FROM            dbo.t_wms_location AS locc
                               WHERE        (location_id = warr.location_id)) AS location,
                             (SELECT        short_description
                               FROM            dbo.t_wms_reason AS reas
                               WHERE        (reason_id = warr.reason_id)) AS short_description, (CASE WHEN warr.warranty_expire >= GETDATE() THEN 'NO' ELSE 'YES' END) AS is_expire
FROM            dbo.t_mod_warranty AS warr


GO
