SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_inventory_data_by_serial]  
AS
SELECT convert(varchar(50),inv.inventory_id) + '|' + isnull(invSN.serial_number,'') as key_id
	,inv.inventory_id
	, inv.attribute_group_id
	, inv.inv_type
	, wh.wh_id
	, inv.wh_master_id
	, own.owner_id
	, own.owner_code
	, inv.location_id
	, inv.parent_lpn
	, inv.lpn
	, inv.wh_item_master_id
	, item.item_number
	, uom.item_uom_id
	, uom.uom_prompt
	, uom.uom
	, ISNULL(invSN.quantity, inv.quantity) AS quantity
	, ISNULL(invSN.quantity_allocated,inv.quantity_allocated) AS quantity_allocated
	, ISNULL(invSN.quantity_incoming,inv.quantity_incoming) AS quantity_incoming
	, inv.receive_date
	, inv.mfg_date
	, invStatus.inv_status
	, inv.inventory_status_id
	, loc.location, loc.loc_type
	, loc.pick_sequence
	, loc.pick_area_id
	, '' AS alternate_item_number
	, item.[description]
	, z.zone
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, CONVERT(nvarchar(15), inv.receive_date, 112) AS receive_date_filter
	, item.dg_code
	, item.grade
	, item.price
	, item.cost
	, CAST(0 AS bit) AS Checked
	, CAST(0 AS decimal(18, 3)) AS adjust_qty
	, item.item_master_id
	, loc.lpn_controlled
	, invSN.serial_number
	, item.sn_control
	, invLot.lot_number
	, invExp.expiry_date
	, convert(datetime,invExp.expiry_date , 112) as exp_date
	, invAttribute1.attribute1
	, invAttribute2.attribute2
	, invAttribute3.attribute3
	, invAttribute4.attribute4
	, invAttribute5.attribute5
	, invExp.days_to_expire
	, inv.create_by
	, inv.create_date
	, NULL AS delivery_date
	, NULL AS delivery_number
	, item.lot_control
	, item.expiry_date_control
FROM dbo.t_wms_inventory AS inv 
INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
INNER JOIN dbo.t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id
INNER JOIN dbo.t_wms_owner own ON inv.owner_id = own.owner_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id AND inv.wh_master_id = whItem.wh_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
INNER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id
INNER JOIN dbo.t_wms_category AS cate ON item.category_id = cate.category_id 
INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT JOIN dbo.t_wms_zone_location zLoc ON loc.location_id = zLoc.location_id
LEFT JOIN dbo.t_wms_zone z ON zLoc.zone_id = z.zone_id
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS lot_number
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
		   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS expiry_date
				,DATEDIFF(dd,GETDATE(),CONVERT(date,attribute_value,112)) as days_to_expire
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248'
		   ) AS invExp ON (inv.inventory_id = invExp.inventory_id) AND (inv.attribute_group_id = invExp.attribute_group_id) 
LEFT JOIN (SELECT  inventory_id
				,attribute_group_id
				,attribute_value AS serial_number
				,quantity
				,quantity_allocated
				,quantity_incoming
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
		   ) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute1
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714'
		   ) AS invAttribute1 ON (inv.inventory_id = invAttribute1.inventory_id) AND (inv.attribute_group_id = invAttribute1.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute2
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A'
		   ) AS invAttribute2 ON (inv.inventory_id = invAttribute2.inventory_id) AND (inv.attribute_group_id = invAttribute2.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute3
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526'
		   ) AS invAttribute3 ON (inv.inventory_id = invAttribute3.inventory_id) AND (inv.attribute_group_id = invAttribute3.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute4
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580'
		   ) AS invAttribute4 ON (inv.inventory_id = invAttribute4.inventory_id) AND (inv.attribute_group_id = invAttribute4.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute5
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE'
		   ) AS invAttribute5 ON (inv.inventory_id = invAttribute5.inventory_id) AND (inv.attribute_group_id = invAttribute5.attribute_group_id)
WHERE uom.primary_uom = 'YES'
GO
/****** Object:  View [dbo].[v_wms_stock_expired45days_report]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_stock_expired45days_report]
AS
SELECT        TOP (100) PERCENT vidbs.zone, vidbs.location, dbo.t_wms_customer.customer_name, vidbs.item_category,
                             (SELECT        TOP (1) description
                               FROM            dbo.t_wms_category AS cat
                               WHERE        (category_id = vidbs.category_id)) AS cat_description, vidbs.item_number, vidbs.description, vidbs.lot_number, vidbs.expiry_date, CONVERT(datetime, vidbs.expiry_date) AS datetime_expiry_date, 
                         vidbs.serial_number, vidbs.quantity, vidbs.inv_status, vidbs.wh_item_master_id, R1_last_inbound_transaction.last_inbound_transaction
FROM            dbo.t_wms_customer INNER JOIN
                         dbo.t_wms_customer_location ON dbo.t_wms_customer.customer_id = dbo.t_wms_customer_location.customer_id RIGHT OUTER JOIN
                         dbo.v_wms_inventory_data_by_serial AS vidbs ON dbo.t_wms_customer_location.location_id = vidbs.location_id LEFT OUTER JOIN
                             (SELECT        ib_detail.wh_item_master_id, MAX(rc_detail.create_date) AS last_inbound_transaction
                               FROM            dbo.t_wms_receipt_detail AS rc_detail LEFT OUTER JOIN
                                                         dbo.t_wms_inbound_detail AS ib_detail ON rc_detail.inbound_order_detail_id = ib_detail.inbound_order_detail_id
                               GROUP BY ib_detail.wh_item_master_id) AS R1_last_inbound_transaction ON vidbs.wh_item_master_id = R1_last_inbound_transaction.wh_item_master_id
WHERE        (DATEDIFF(DAY, GETDATE(), CONVERT(DATE, SUBSTRING(vidbs.expiry_date, 1, 4) + '-' + SUBSTRING(vidbs.expiry_date, 5, 2) + '-' + SUBSTRING(vidbs.expiry_date, 7, 2))) <= 45) AND (vidbs.zone <> N'QUAR')
ORDER BY vidbs.zone DESC, dbo.t_wms_customer.customer_name
GO
/****** Object:  View [dbo].[v_wms_dashb_center_card_outbound]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[v_wms_dashb_center_card_outbound]
AS


WITH tOutboundPast AS
(
	SELECT obMS.wh_master_id
		,obMS.wh_id
		,SUM(ISNULL(obDT.quantity_order,0)) AS quantity_order 
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	WHERE obMS.order_status IN ('OPEN','RELEASE','PICK','PICKED')
	AND CONVERT(DATE,obMS.ship_date_plan) < CONVERT(DATE,GETDATE())
	AND ISNULL(obDT.quantity_pick,0) < ISNULL(obDT.quantity_order,0)
	GROUP BY obMS.wh_master_id,obMS.wh_id
)
,tOutboundDaily AS
(
	SELECT obMS.wh_master_id
		,obMS.wh_id
		,SUM(ISNULL(obDT.quantity_order,0)) AS quantity_order 
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	WHERE CONVERT(DATE,obMS.ship_date_plan) = CONVERT(DATE,GETDATE()) 
	GROUP BY obMS.wh_master_id,obMS.wh_id
)
SELECT ISNULL(obD.wh_master_id,obP.wh_master_id) AS wh_master_id
	,ISNULL(obD.wh_id,obP.wh_id) AS wh_id
	,ISNULL(obD.quantity_order,0) + isnull(obP.quantity_order,0) as quantity_order
FROM tOutboundDaily obD
FULL JOIN tOutboundPast obP ON obD.wh_master_id = obP.wh_master_id


GO
