SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


 
CREATE VIEW [dbo].[v_wms_inventory_data_by_serial_last_count]
AS
SELECT inv_sn.inventory_id
	,inv_sn.attribute_group_id
	,inv_sn.inv_type
	,inv_sn.wh_id
	,inv_sn.wh_master_id
	,inv_sn.owner_id
	,inv_sn.owner_code
	,inv_sn.location_id
	,inv_sn.parent_lpn
	,inv_sn.lpn
	,inv_sn.wh_item_master_id
	,inv_sn.item_number
	,inv_sn.uom_prompt
	,inv_sn.quantity
	,inv_sn.quantity_allocated
	,inv_sn.quantity_incoming
	,inv_sn.receive_date
	,inv_sn.mfg_date
	,inv_sn.inv_status
	,inv_sn.inventory_status_id
	,inv_sn.location
	,inv_sn.loc_type
	,inv_sn.pick_sequence
	,inv_sn.pick_area_id
	,inv_sn.description
	,inv_sn.zone
	,inv_sn.uom
	,inv_sn.category_id
	,inv_sn.item_category
	,inv_sn.cate_description
	,inv_sn.receive_date_filter
	,inv_sn.dg_code
	,inv_sn.grade
	,inv_sn.price
	,inv_sn.cost
	,inv_sn.Checked
	,inv_sn.adjust_qty
	,inv_sn.item_master_id
	,inv_sn.lpn_controlled
	,inv_sn.serial_number
	,inv_sn.lot_number
	,inv_sn.expiry_date
	,inv_sn.attribute1
	,inv_sn.attribute2
	,inv_sn.attribute3
	,inv_sn.attribute4
	,inv_sn.attribute5
	,inv_sn.days_to_expire
	,inv_sn.create_by
	,inv_sn.create_date
	,inv_sn.delivery_date
	,inv_sn.delivery_number
	,rfid.create_date as receipt_date
	,rec.last_create_date
FROM v_wms_inventory_data_by_serial inv_sn
INNER JOIN t_wms_inbound_rfid rfid ON inv_sn.serial_number = rfid.serial_number
LEFT JOIN  (SELECT tCount.location_id
				,MAX(tCount.create_date) AS last_create_date
		    FROM ( SELECT recon.location_id
						,CONVERT(DATE,recon.create_date) AS create_date--MAX(create_date) AS last_create_date
					FROM t_wms_count_reconcile recon
					INNER JOIN t_wms_count_plan_detail det ON det.serial_number = recon.serial_number and det.count_master_id = recon.count_master_id
					UNION
					SELECT recon.location_id
						,CONVERT(DATE,recon.create_date) AS create_date--MAX(create_date) AS last_create_date
					FROM t_wms_count_reconcile_external recon
					INNER JOIN t_wms_count_plan_detail_external det ON det.serial_number = recon.serial_number and det.count_master_id = recon.count_master_id

				 ) tCount
			GROUP BY tCount.location_id
			) AS rec ON inv_sn.location_id = rec.location_id



GO
