CREATE VIEW [dbo].[v_wms_inventory_adjustment]
AS
select 
sn.inventory_id,
sn.attribute_group_id,
sn.wh_master_id,
sn.wh_id,
sn.owner_code,
sn.zone,
sn.location,
sn.item_number,
sn.description,
sn.lpn,
sn.parent_lpn,
sn.inv_status,
sn.lot_number,
sn.expiry_date,
sn.quantity,
sn.quantity_allocated,
sn.uom,
sn.dg_code,
sn.serial_number,
sn.grade,
sn.item_category,
sn.price,
sn.receive_date,
sn.item_master_id,
sn.category_id,
sn.cate_description,
sn.owner_id, 
sn.location_id,
sn.loc_type,
sn.attribute1,
sn.attribute2,
sn.attribute3,
sn.attribute4,
sn.attribute5,
sn.delivery_number,
sn.delivery_date,
store.use_date,
store.user_def1
from v_wms_inventory_data_by_serial sn
left join (SELECT serial_number
				,use_date
				,user_def1
				,user_def2
				,user_def3
				,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
			FROM t_wms_store_item_status 
			)store on sn.serial_number = store.serial_number AND store.is_max = 1





