/****** Object:  View [dbo].[v_wms_report_inv_used_item]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_report_inv_used_item]
AS

select 
	inv_ser.location
	, inv_ser.location_id
	, inv_ser.item_number
	, inv_ser.[description]
	, inv_ser.lot_number
	, inv_ser.expiry_date
	, convert(datetime,inv_ser.expiry_date) as str_expiry_date
	, inv_ser.serial_number
	, store_item.use_date
	, store_item.user_def2 as doctor
	, store_item.user_def1 as patience
	, store_item.user_def3 as budget
	, store_item.memo
	, store_item.create_date as count_date
	, store_item.create_by as count_by
	, DATEDIFF ( day , store_item.create_date , GETDATE() ) as used_aged
	, store_item.outbound_order_number as delivery_number
	, store_item.delivery_date as delivery_date
	, (select top 1 cus.customer_name from [dbo].[t_wms_customer] cus where cus.customer_id = (
		select top 1 cus_loc.customer_id from [dbo].[t_wms_customer_location] cus_loc
		where cus_loc.location_id = inv_ser.location_id)) as customer_name
from v_wms_inventory_data_by_serial inv_ser
--left join t_wms_store_item_status store_item on inv_ser.serial_number = store_item.serial_number
LEFT JOIN (SELECT store_item_status_id
				,user_def1
				,user_def2
				,use_date
				,user_def3
				,memo
				,delivery_date
				,serial_number
				,create_date
				,create_by
				,outbound_order_number
				,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
			FROM t_wms_store_item_status
) store_item ON store_item.serial_number = inv_ser.serial_number and is_max = 1
where inv_status = 'Used'

GO
