/****** Object:  View [dbo].[v_wms_report_inv_missing_item]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 

CREATE VIEW [dbo].[v_wms_report_inv_missing_item]
AS

SELECT        
	count_merge.location
	 , count_merge.item_number
	 , count_merge.item_description
	 , count_merge.lot_number
	 , convert(datetime,count_merge.expiry_date) as str_expiry_date
	 , count_merge.serial_number
	 , count_merge.stock_qty as qty_consigned
	 , count_merge.count_qty as qty_scan
	 , count_merge.diff_qty as qty_discrepancy
	 , count_merge.delivery_date
	 , count_merge.delivery_no	 
	 , count_plan.close_date
	 , DATEDIFF ( day , count_plan.close_date , GETDATE() ) as count_age
	 , count_plan.close_by
	 , count_plan.customer_name
	 , count_merge.location_id
FROM
(
SELECT 
    tCount.count_master_id
	,tCount.location_id 
	,tCount.location
	,tCount.item_number
	,tCount.item_description
	,(CASE ISNULL(store.store_item_status_id,'') 
		WHEN '' THEN (CASE WHEN ISNULL(tCount.count_qty,0) = 0 THEN 'Missing CSM'  
					       WHEN ISNULL(planDT.count_master_id,'') = '' AND ISNULL(tCount.count_qty,0) > 0 THEN 'Unknown' ELSE planDT.inv_status END)
		ELSE 'Used' END) AS inv_status
	,tCount.lot_number
	,tCount.[expiry_date]
	,tCount.serial_number
	,ISNULL(planDT.stock_qty,0) AS stock_qty
	,ISNULL(tCount.count_qty,0) AS count_qty
	,ISNULL(tCount.count_qty,0) - ISNULL(planDT.stock_qty,0) AS diff_qty
	,tCount.outbound_order_number AS delivery_no
	--,store.user_def1 AS pateint
	--,store.user_def2 AS doctor
	--,store.use_date
	--,store.user_def3 AS budget
	--,store.memo
	,tCount.delivery_date
	--,tCount.item_category
	--,tCount.item_category_description
	,tCount.count_by
	,tCount.count_date
FROM (SELECT count_master_id
			,location_id 
			,location
			,item_number
			,item_description
			,item_category
			,item_category_description
			,lot_number
			,[expiry_date] 
			,serial_number
			,ISNULL(count_qty,0)	AS count_qty
			, create_by as count_by
			, create_date as count_date
			, outbound_order_number
			, delivery_date
		FROM t_wms_count_plan_detail_external
		UNION
		SELECT count_master_id
			,location_id
			,location
			,item_number
			,item_description
			,item_category
			,item_category_description
			,lot	AS lot_number
			,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
			,serial_number
			,ISNULL(count_qty,0)	AS count_qty
			, create_by as count_by
			, create_date as count_date
			, outbound_order_number
			, delivery_date
		FROM t_wms_count_reconcile_external
		) tCount
LEFT JOIN t_wms_count_plan_detail_external planDT ON tCount.count_master_id = planDT.count_master_id
												  AND tCount.location_id = planDT.location_id
												  AND tCount.item_number = planDT.item_number
												  AND tCount.lot_number = planDT.lot_number
												  AND tCount.expiry_date = planDT.expiry_date
												  AND tCount.serial_number = planDT.serial_number
--LEFT JOIN t_wms_customer_location cus_loc ON tCount.location_id = cus_loc.location_id
--LEFT JOIN t_wms_customer cus ON cus_loc.customer_id = cus.customer_id
--LEFT JOIN t_wms_location loc ON cus_loc.location_id = loc.location_id
LEFT JOIN t_wms_store_item_status store ON tCount.serial_number = store.serial_number
)count_merge
LEFT JOIN dbo.t_wms_count_plan_master_external count_plan ON count_plan.count_master_id = count_merge.count_master_id
WHERE inv_status = 'Missing CSM' 
AND (DATEPART(month,getdate()) = DATEPART(month,count_merge.count_date) AND DATEPART(year,getdate()) = DATEPART(year,count_merge.count_date))


GO
