/****** Object:  View [dbo].[v_wms_report_inv_unknown_item]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_inv_unknown_item]
AS

SELECT 
(select top 1 loc.location from [dbo].[t_wms_location] loc where loc.location_id = (
		select top 1 cus_loc.location_id from [dbo].[t_wms_customer_location] cus_loc
		where cus_loc.customer_id = (
		SELECT TOP 1 plan_master_external.customer_id FROM dbo.t_wms_count_plan_master_external plan_master_external
		WHERE plan_master_external.count_master_id = reconcile_external.count_master_id
		))
	 )as customer_plan_locatiion
	 , (select top 1 cus.customer_name from [dbo].[t_wms_customer] cus where cus.customer_id = (
		select top 1 cus_loc.customer_id from [dbo].[t_wms_customer_location] cus_loc
		where cus_loc.customer_id = (
		SELECT TOP 1 plan_master_external.customer_id FROM dbo.t_wms_count_plan_master_external plan_master_external
		WHERE plan_master_external.count_master_id = reconcile_external.count_master_id
		))
	 )as customer_name
	 , reconcile_external.item_number
	 , reconcile_external.item_description
	 , reconcile_external.lot as lot_number
	 , convert(datetime,reconcile_external.expiry_date) as str_expiry_date
	 , reconcile_external.serial_number
	 , reconcile_external.outbound_order_number as delivery_no
	 , reconcile_external.delivery_date as delivery_date
	 --, count_merge.location AS last_location
	 , (SELECT TOP (1) (CASE WHEN ISNULL(tlog.to_location, '') = '' THEN tlog.location ELSE tlog.to_location END) AS last_location_log
		FROM dbo.t_com_tran_log AS tlog
		WHERE (tran_type IN ('OO_SHIP', 'INV_MOVE', 'IO_RECEIPT')) 
		AND (sub_tran_type <> 'CLOSE_RECEIPT')
		AND (create_date >= DATEADD(year, - 2, GETDATE())) 
		AND (serial_number = reconcile_external.serial_number)
		ORDER BY create_date DESC) AS last_location
	 , reconcile_external.create_date as count_date
	 ,  DATEDIFF ( day , reconcile_external.create_date , GETDATE() ) as count_age
	 , reconcile_external.create_by  as count_by
	 , location_id
FROM t_wms_count_reconcile_external reconcile_external
WHERE [serial_number] NOT IN
(
	SELECT [serial_number] FROM t_wms_count_plan_detail_external plan_detail_external
	WHERE (DATEPART(month,getdate()) = DATEPART(month,plan_detail_external.create_date) AND DATEPART(year,getdate()) = DATEPART(year,plan_detail_external.create_date))
)
AND (DATEPART(month,getdate()) = DATEPART(month,reconcile_external.create_date) AND DATEPART(year,getdate()) = DATEPART(year,reconcile_external.create_date))




GO
