/****** Object:  View [dbo].[v_wms_stock_expired30days_report]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_stock_expired30days_report]
AS
SELECT        TOP (100) PERCENT vidbs.zone, vidbs.location, c.customer_name, vidbs.item_category,
                             (SELECT        TOP (1) description
                               FROM            dbo.t_wms_category AS cat
                               WHERE        (category_id = vidbs.category_id)) AS cat_description, vidbs.item_number, vidbs.description, vidbs.lot_number, vidbs.expiry_date, CONVERT(datetime, vidbs.expiry_date) AS datetime_expiry_date, 
                         vidbs.serial_number, vidbs.quantity, vidbs.inv_status, vidbs.wh_item_master_id, R1_last_inbound_transaction.last_inbound_transaction
FROM            dbo.v_wms_inventory_data_by_serial AS vidbs LEFT OUTER JOIN
                             (SELECT        ib_detail.wh_item_master_id, MAX(rc_detail.create_date) AS last_inbound_transaction
                               FROM            dbo.t_wms_receipt_detail AS rc_detail LEFT OUTER JOIN
                                                         dbo.t_wms_inbound_detail AS ib_detail ON rc_detail.inbound_order_detail_id = ib_detail.inbound_order_detail_id
                               GROUP BY ib_detail.wh_item_master_id) AS R1_last_inbound_transaction ON vidbs.wh_item_master_id = R1_last_inbound_transaction.wh_item_master_id LEFT OUTER JOIN
                         dbo.t_wms_customer_location AS cl ON vidbs.location_id = cl.location_id LEFT OUTER JOIN
                         dbo.t_wms_customer AS c ON cl.customer_id = c.customer_id
WHERE        (DATEDIFF(DAY, GETDATE(), CONVERT(DATE, SUBSTRING(vidbs.expiry_date, 1, 4) + '-' + SUBSTRING(vidbs.expiry_date, 5, 2) + '-' + SUBSTRING(vidbs.expiry_date, 7, 2))) <= 30) AND (vidbs.zone <> N'QUAR')
ORDER BY vidbs.zone DESC, c.customer_name
GO
/****** Object:  View [dbo].[v_wms_stock_expired15days_report]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_stock_expired15days_report]
AS
SELECT        TOP (100) PERCENT vidbs.zone, vidbs.location, c.customer_name, vidbs.item_category,
                             (SELECT        TOP (1) description
                               FROM            dbo.t_wms_category AS cat
                               WHERE        (category_id = vidbs.category_id)) AS cat_description, vidbs.item_number, vidbs.description, vidbs.lot_number, vidbs.expiry_date, CONVERT(datetime, vidbs.expiry_date) AS datetime_expiry_date, 
                         vidbs.serial_number, vidbs.quantity, vidbs.inv_status, vidbs.wh_item_master_id, R1_last_inbound_transaction.last_inbound_transaction
FROM            dbo.v_wms_inventory_data_by_serial AS vidbs LEFT OUTER JOIN
                             (SELECT        ib_detail.wh_item_master_id, MAX(rc_detail.create_date) AS last_inbound_transaction
                               FROM            dbo.t_wms_receipt_detail AS rc_detail LEFT OUTER JOIN
                                                         dbo.t_wms_inbound_detail AS ib_detail ON rc_detail.inbound_order_detail_id = ib_detail.inbound_order_detail_id
                               GROUP BY ib_detail.wh_item_master_id) AS R1_last_inbound_transaction ON vidbs.wh_item_master_id = R1_last_inbound_transaction.wh_item_master_id LEFT OUTER JOIN
                         dbo.t_wms_customer_location AS cl ON vidbs.location_id = cl.location_id LEFT OUTER JOIN
                         dbo.t_wms_customer AS c ON cl.customer_id = c.customer_id
WHERE        (DATEDIFF(DAY, GETDATE(), CONVERT(DATE, SUBSTRING(vidbs.expiry_date, 1, 4) + '-' + SUBSTRING(vidbs.expiry_date, 5, 2) + '-' + SUBSTRING(vidbs.expiry_date, 7, 2))) <= 15) AND (vidbs.zone <> N'QUAR')
ORDER BY vidbs.zone DESC, c.customer_name
GO
/****** Object:  View [dbo].[v_wms_stock_expired60days_report]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_stock_expired60days_report]
AS
SELECT        TOP (100) PERCENT vidbs.zone, vidbs.location, c.customer_name, vidbs.item_category,
                             (SELECT        TOP (1) description
                               FROM            dbo.t_wms_category AS cat
                               WHERE        (category_id = vidbs.category_id)) AS cat_description, vidbs.item_number, vidbs.description, vidbs.lot_number, vidbs.expiry_date, CONVERT(datetime, vidbs.expiry_date) AS datetime_expiry_date, 
                         vidbs.serial_number, vidbs.quantity, vidbs.inv_status, vidbs.wh_item_master_id, R1_last_inbound_transaction.last_inbound_transaction
FROM            dbo.v_wms_inventory_data_by_serial AS vidbs LEFT OUTER JOIN
                             (SELECT        ib_detail.wh_item_master_id, MAX(rc_detail.create_date) AS last_inbound_transaction
                               FROM            dbo.t_wms_receipt_detail AS rc_detail LEFT OUTER JOIN
                                                         dbo.t_wms_inbound_detail AS ib_detail ON rc_detail.inbound_order_detail_id = ib_detail.inbound_order_detail_id
                               GROUP BY ib_detail.wh_item_master_id) AS R1_last_inbound_transaction ON vidbs.wh_item_master_id = R1_last_inbound_transaction.wh_item_master_id LEFT OUTER JOIN
                         dbo.t_wms_customer_location AS cl ON vidbs.location_id = cl.location_id LEFT OUTER JOIN
                         dbo.t_wms_customer AS c ON cl.customer_id = c.customer_id
WHERE        (DATEDIFF(DAY, GETDATE(), CONVERT(DATE, SUBSTRING(vidbs.expiry_date, 1, 4) + '-' + SUBSTRING(vidbs.expiry_date, 5, 2) + '-' + SUBSTRING(vidbs.expiry_date, 7, 2))) <= 60) 
ORDER BY vidbs.zone DESC, c.customer_name
GO
