SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_adjust_export]
AS
SELECT t_wms_owner.owner_id
	,t_wms_owner.owner_code
	,t_log.serial_number
	,'' as adjust_number
	,t_log.item_number
	,t_wms_reason.short_description as reason_desc
	,t_wms_reason.reason_code
	,ISNULL(NULLIF(t_log.warehouse, ''),t_log.to_warehouse) as wh_code
	,t_log.create_date as adjust_date_export
	,t_log.create_by as adjust_by
	,ISNULL(NULLIF(t_log.location, ''),t_log.to_location) as location
	,t_log.create_date as adjust_date_stock
	,t_log.quantity
	,t_log.after_quantity
	,t_log.quantity_uom
	,ISNULL(NULLIF(t_log.lot_number, ''),t_log.after_lot_number) as lot_number
	,ISNULL(NULLIF(t_log.[expiry_date], ''),t_log.after_expiry_date) as expiry_date

FROM ( SELECT  ISNULL(NULLIF(t_com_tran_log.[owner], ''),t_com_tran_log.to_owner) AS owner_code
			,warehouse
			,to_warehouse
			,location
			,to_location
			,lot_number
			,after_lot_number
			,create_date
			,create_by
			,item_number
			,serial_number
			,reason_code
			,[expiry_date]
			,after_expiry_date
			,quantity
			,after_quantity
			,quantity_uom
			,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
		FROM t_com_tran_log
		WHERE tran_type = 'INV_ADJUST'
	) AS t_log
INNER JOIN t_wms_owner on t_log.owner_code = t_wms_owner.owner_code
LEFT JOIN t_wms_reason on t_log.reason_code = t_wms_reason.reason_code
GO
