GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_outbound_viewer_by_item_detail]
AS
SELECT wh.wh_master_id
	,wh.wh_id
	,own.owner_id
	,own.owner_code
	,obMS.outbound_order_master_id
	,obMS.outbound_order_number
	,obMS.order_type
	,obMS.delivery_date_plan
	,obMS.customer_id
	,obMS.customer_code
	,obMS.customer_name
	,obMS.customer_purchase_order
	,obMS.ship_to_code
	,obMS.ship_to_name
	,ISNULL(obMS.ship_to_code,'') + ' : '+ ISNULL(obMS.ship_to_name,'') AS ship_to
	,obDT.line_number
	,obDT.wh_item_master_id
	,item.item_master_id
	,item.item_number
	,item.description AS item_description
	,cate.category_id
	,cate.item_category
	,uom.item_uom_id
	,uom.uom
	,uom.uom_prompt
	,ISNULL(obDT.quantity_order,0) AS quantity_order
FROM t_wms_outbound_master obMS
LEFT JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
LEFT JOIN t_wms_wh_item whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
LEFT JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
LEFT JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
WHERE obMS.order_status = 'OPEN'
GO
