/****** Object:  View [dbo].[v_wms_count_history]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE view [dbo].[v_wms_count_history]
as

SELECT  cPlan.count_id
	, cPlan.location
	, cPlan.customer_name
	, cPlan.count_plan_date
	, ISNULL(cPlan.stock_qty,0) AS stock_qty
	, ISNULL(cNormal.normal_qty,0) AS normal_qty
	, ISNULL(cMissing.missing_qty,0) AS missing_qty
	, ISNULL(cShort.short_qty,0) AS short_count_qty
	, ISNULL(cExpire.expire_qty,0) AS expire_count_qty
	, ISNULL(cShort1.short_qty1,0) AS short_qty
	, ISNULL(cExpire1.expire_qty1,0) AS expire_qty
FROM (SELECT a.count_master_id
		, a.count_id
		, a.customer_code
		, a.customer_name
		, a.count_plan_date
		, b.location
		, SUM(b.stock_qty) AS stock_qty
	  FROM t_wms_count_plan_master_external AS a 
	  INNER JOIN t_wms_count_plan_detail_external AS b ON a.count_master_id = b.count_master_id
	  GROUP BY a.count_master_id, a.count_id, a.customer_code, a.customer_name, a.count_plan_date, b.location
	  ) cPlan
LEFT JOIN (SELECT count_master_id
			, location
			, SUM(count_qty) AS normal_qty
			FROM t_wms_count_plan_detail_external
			WHERE DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) > 45
			GROUP BY count_master_id, location
			) cNormal ON cPlan.count_master_id = cNormal.count_master_id AND cPlan.location = cNormal.location
LEFT JOIN (SELECT count_master_id
			, location
			, COUNT(count_plan_detail_id) AS missing_qty
		   FROM t_wms_count_plan_detail_external
		   WHERE ISNULL(count_qty,0) = 0
		   AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) > 45
		   GROUP BY count_master_id, location
		   ) cMissing ON cPlan.count_master_id = cMissing.count_master_id AND cPlan.location = cMissing.location
LEFT JOIN (SELECT count_master_id
			, location
			, COUNT(count_plan_detail_id) AS short_qty
		   FROM t_wms_count_plan_detail_external
		   WHERE (DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) > 0 AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) <= 45)
		   AND ISNULL(count_qty,0) > 0
		   GROUP BY count_master_id, location
		   ) cShort ON cPlan.count_master_id = cShort.count_master_id AND cPlan.location = cShort.location
LEFT JOIN (SELECT count_master_id
			, location
			, COUNT(count_plan_detail_id) AS expire_qty
		   FROM t_wms_count_plan_detail_external
		   WHERE DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) <= 0
		   AND ISNULL(count_qty,0) > 0
		   GROUP BY count_master_id, location
		   ) cExpire ON cPlan.count_master_id = cExpire.count_master_id AND cPlan.location = cExpire.location
LEFT JOIN (SELECT count_master_id
			, location
			, COUNT(count_plan_detail_id) AS short_qty1
		   FROM t_wms_count_plan_detail_external
		   WHERE (DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) > 0 AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) <= 45)
		   AND ISNULL(count_qty,0) = 0
		   GROUP BY count_master_id, location
		   ) cShort1 ON cPlan.count_master_id = cShort1.count_master_id AND cShort1.location = cShort.location
LEFT JOIN (SELECT count_master_id
			, location
			, COUNT(count_plan_detail_id) AS expire_qty1
		   FROM t_wms_count_plan_detail_external
		   WHERE DATEDIFF(DAY,GETDATE(),CONVERT(DATE,expiry_date)) <= 0
		   AND ISNULL(count_qty,0) = 0
		   GROUP BY count_master_id, location
		   ) cExpire1 ON cPlan.count_master_id = cExpire1.count_master_id AND cPlan.location = cExpire1.location
--WHERE cPlan.count_id  = 'jirapas20160408094645'
--AND cPlan.location = '107328'
GO
