/****** Object:  View [dbo].[v_wms_count_performance_achieve]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO










CREATE VIEW [dbo].[v_wms_count_performance_achieve]
AS
SELECT
[year] = isnull(tmp.[year],0)
,[month] = tmp.[month]
,[month_int] = tmp.[month_int]
,tmp.count_user_customer
,tmp.planned
,tmp.actual_work
,tmp.actual_work_notrepeat
,CASE WHEN tmp.count_user_customer = 0 THEN 0 ELSE CONVERT(decimal(15,2),(tmp.actual_work / tmp.count_user_customer) * 100) END as AchievementPlaned
,CASE WHEN tmp.count_user_customer = 0 THEN 0 ELSE CONVERT(decimal(15,2),(tmp.actual_work_notrepeat / tmp.count_user_customer) * 100) END as AchievementAssigned
,create_by = isnull(tmp.create_by,'')
FROM
(
	SELECT 
	YEAR(create_date) as [year]
	,MONTH(create_date) as [month_int]
	,DATENAME(month,create_date) as [month]
	,CONVERT(decimal(15,2),COUNT(count_master_id)) as planned
	,CONVERT(decimal(15,2),COUNT(count_master_id)) as actual_work
	,CONVERT(decimal(15,2),COUNT(distinct customer_id)) as actual_work_notrepeat

	,create_by
	,(select CONVERT(decimal(15,2),count(*)) from t_wms_customer_user where [user_id] = ext.create_by) as count_user_customer

	FROM t_wms_count_plan_master_external ext
	GROUP BY YEAR(create_date),MONTH(create_date),DATENAME(month,create_date),create_by
) as tmp



GO
/****** Object:  View [dbo].[v_wms_count_performance_export]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO







CREATE VIEW [dbo].[v_wms_count_performance_export]
AS
with detail as (
 select 
 det.count_master_id
 ,det.create_by
 ,det.location_id
 ,det.location
 ,count(det.stock_qty) as stock_qty
 ,count(case when det.inv_status = 'Consignment' then 1 else null end )  as Consignment
 ,count(case when(DATEDIFF(DAY,GETDATE(),CONVERT(DATE,det.[expiry_date])) > 0 AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,det.[expiry_date])) <= 45)
		   AND ISNULL(det.count_qty,0) > 0 then 1 else null end )  as Short
 ,count(case when  DATEDIFF(DAY,GETDATE(),CONVERT(DATE,det.[expiry_date])) <= 0
		   AND ISNULL(det.count_qty,0) > 0 then 1 else null end )  as Expire
 ,count(case when ISNULL(det.count_qty,0) = 0 AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,det.[expiry_date])) > 45 then 1 else null end )  as Missing
 from t_wms_count_plan_detail_external det
 group by  det.count_master_id
 ,det.create_by
 ,det.location_id
 ,det.location
)

select 
det.create_by
,mas.count_id
,mas.count_plan_date
,det.location_id
,det.location
,mas.customer_id
,mas.customer_code
,mas.customer_name
,cus.province
,det.stock_qty
,det.Consignment
,det.Short
,det.Expire
,det.Missing
,con.unknown as Unknown
from t_wms_count_plan_master_external mas
inner join detail det on mas.count_master_id = det.count_master_id
inner join t_wms_customer cus on cus.customer_id = mas.customer_id
inner join (
	select count(serial_number) as unknown,count_master_id 
	from t_wms_count_reconcile_external rec
	where not exists (select serial_number from t_wms_count_plan_detail_external ext where rec.serial_number = ext.serial_number and rec.count_master_id = ext.count_master_id)
	group by count_master_id
) as con on con.count_master_id = mas.count_master_id






GO
/****** Object:  View [dbo].[v_wms_count_performance_summary]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_count_performance_summary]
AS
SELECT
tmp2.[year]
,tmp2.[month_int]
,tmp2.[month]
,tmp2.province
,'' response
,tmp2.count_user_customer
,tmp2.actual_work
,tmp2.actual_work_distinct
,CONVERT(decimal(15,2),(tmp2.actual_work/tmp2.count_user_customer) * 100) as achievement_actual
,CONVERT(decimal(15,2),(tmp2.actual_work_distinct/tmp2.count_user_customer) * 100) as achievement_actual_distinct
,tmp2.create_by
FROM
(
	SELECT
		tmp.[year]
		,tmp.[month_int]
		,tmp.[month]
		,tmp.province
		,(select convert(decimal(15,2),count(*)) from t_wms_customer_user where [user_id] = tmp.create_by) as count_user_customer
		,convert(decimal(15,2),count(tmp.count_master_id)) as actual_work
		,convert(decimal(15,2),count(distinct tmp.customer_id)) as actual_work_distinct
		,tmp.create_by
	FROM
	(
		select 
		year(ext.create_date) as [year]
		,month(ext.create_date) as [month_int]
		,datename(month,ext.create_date) as [month]
		,case when UPPER(cus.province) like '%BAN%' then 'BKK'
		when isnull(cus.province,'') = '' then '-' 
		else 'UPC' end province
		,ext.create_by
		,ext.count_master_id
		,ext.customer_id
		from t_wms_count_plan_master_external ext
		inner join t_wms_customer cus on cus.customer_id = ext.customer_id
	) tmp
	group by 
	tmp.[year]
	,tmp.[month_int]
	,tmp.[month]
	,tmp.province
	,tmp.create_by
) tmp2



GO
/****** Object:  View [dbo].[v_wms_report_summary_count_reconcile]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_summary_count_reconcile]
AS 
WITH tPlanDetail AS
(
	SELECT count_master_id 
		,wh_item_master_id
		,inv_status
		,lot 
		,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,SUM(ISNULL(stock_qty,0)) AS stock_qty
	FROM t_wms_count_plan_detail
	GROUP BY count_master_id 
		,wh_item_master_id
		,inv_status 
		,lot 
		,CONVERT(VARCHAR,expiry_date,112)
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
)
,tReconcile AS
(
	SELECT count_master_id 
		,wh_item_master_id
		,inv_status
		,lot 
		,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,SUM(ISNULL(count_qty,0)) AS count_qty
	FROM t_wms_count_reconcile
	GROUP BY count_master_id 
		,wh_item_master_id
		,inv_status 
		,lot 
		,CONVERT(VARCHAR,expiry_date,112)
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
)
SELECT planMS.count_master_id
	, planMS.count_id
	, planMS.wh_master_id
	, planMS.count_plan_type
	, planMS.count_status
	, planMS.create_by
	, planMS.create_date
	, planMS.close_by
	, planMS.close_date
	, planMS.close_remark
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, item.item_number
	, item.description
	, tCount.lot
	, tCount.expiry_date AS expiry_date
	, tCount.serial_number AS serial_number 
	, tCount.inv_status AS inv_status 
	, ISNULL(planDT.stock_qty, 0) AS stock_qty
	, ISNULL(recDT.count_qty, 0) AS count_qty
	, ISNULL(recDT.count_qty, 0) - ISNULL(planDT.stock_qty, 0) AS diff_qty
	, uom.uom_prompt
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, tCount.attribute1
	, tCount.attribute2
	, tCount.attribute3
	, tCount.attribute4
	, tCount.attribute5
	, tRec.create_by	AS count_by
	, tRec.create_date	AS count_date
FROM (SELECT count_master_id 
			,wh_item_master_id
			,inv_status 
			,lot  
			,[expiry_date] 
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5
		FROM t_wms_count_plan_detail
		UNION
		SELECT count_master_id 
			,wh_item_master_id
			,inv_status 
			,lot 
			,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5 
		FROM t_wms_count_reconcile
		) tCount
LEFT JOIN tPlanDetail planDT ON tCount.count_master_id = planDT.count_master_id
										AND tCount.wh_item_master_id = planDT.wh_item_master_id
										AND tCount.inv_status = planDT.inv_status 
										AND ISNULL(tCount.lot,'') = ISNULL(planDT.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(planDT.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(planDT.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(planDT.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(planDT.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(planDT.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(planDT.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(planDT.attribute5,'')
LEFT JOIN tReconcile recDT ON tCount.count_master_id = recDT.count_master_id
										AND tCount.wh_item_master_id = recDT.wh_item_master_id
										AND tCount.inv_status = recDT.inv_status 
										AND ISNULL(tCount.lot,'') = ISNULL(recDT.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(recDT.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(recDT.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(recDT.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(recDT.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(recDT.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(recDT.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(recDT.attribute5,'')
LEFT JOIN (SELECT count_master_id 
				,wh_item_master_id
				,inv_status 
				,lot  
				,[expiry_date] 
				,serial_number
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,create_by
				,create_date
				,ROW_NUMBER() OVER(PARTITION BY count_master_id,wh_item_master_id,inv_status,lot,[expiry_date],serial_number,attribute1,attribute2,attribute3,attribute4,attribute5 ORDER BY create_date DESC) AS is_max
			FROM t_wms_count_reconcile) tRec ON tCount.count_master_id = tRec.count_master_id
										AND tCount.wh_item_master_id = tRec.wh_item_master_id
										AND tCount.inv_status = tRec.inv_status 
										AND ISNULL(tCount.lot,'') = ISNULL(tRec.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(tRec.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(tRec.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(tRec.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(tRec.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(tRec.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(tRec.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(tRec.attribute5,'')
										AND is_max = 1
INNER JOIN t_wms_count_plan_master planMS ON tCount.count_master_id = planMS.count_master_id
INNER JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id  = tCount.wh_item_master_id
INNER JOIN t_wms_item item ON item.item_master_id = whItem.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
INNER JOIN (SELECT item_master_id
				,item_uom_id
				,uom
				,uom_prompt
			FROM t_wms_item_uom
			WHERE primary_uom = 'YES'
			) uom ON item.item_master_id = uom.item_master_id
INNER JOIN t_wms_owner own ON planMS.owner_id = own.owner_id
INNER JOIN t_wms_wh wh ON planMS.wh_master_id = wh.wh_master_id
GO
/****** Object:  View [dbo].[v_wms_inventory_data_for_inv_compare]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_inventory_data_for_inv_compare]
AS
SELECT inv.inventory_id
	, inv.attribute_group_id
	, inv.inv_type
	, inv.wh_master_id
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, inv.location_id
	, loc.location
	, loc.loc_type
	, loc.lpn_controlled 
 	, inv.parent_lpn
	, inv.lpn
	, inv.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description
	, uom.item_uom_id
	, uom.uom_prompt
	, uom.uom 
	, inv.quantity
	, inv.quantity_allocated
	, inv.quantity_incoming
	, inv.receive_date
	, inv.mfg_date
	, inv.inventory_status_id 
	, invStatus.inv_status
	, invLot.lot_number
	, invExp.expiry_date AS expiry_date
	, CONVERT(DATETIME,invExp.expiry_date , 112) as exp_date
	, DATEDIFF(dd, GETDATE(), CONVERT(date, invExp.expiry_date, 112)) AS days_to_expire 
	, cate.category_id
	, cate.item_category
	, cate.description AS cate_description
	, invAttribute1.attribute1
	, invAttribute2.attribute2
	, invAttribute3.attribute3
	, invAttribute4.attribute4
	, invAttribute5.attribute5
	, inv.create_date
	, inv.create_by
FROM dbo.t_wms_inventory AS inv 
INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
INNER JOIN dbo.t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id AND inv.wh_master_id = whItem.wh_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
INNER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id
INNER JOIN dbo.t_wms_owner AS own ON inv.owner_id = own.owner_id 
INNER JOIN dbo.t_wms_category AS cate ON item.category_id = cate.category_id 
INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT OUTER JOIN  (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_6
				WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_5
				WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttribute1 ON inv.inventory_id = invAttribute1.inventory_id AND inv.attribute_group_id = invAttribute1.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_4
				WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttribute2 ON inv.inventory_id = invAttribute2.inventory_id AND inv.attribute_group_id = invAttribute2.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_3
				WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttribute3 ON inv.inventory_id = invAttribute3.inventory_id AND inv.attribute_group_id = invAttribute3.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_2
				WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttribute4 ON inv.inventory_id = invAttribute4.inventory_id AND inv.attribute_group_id = invAttribute4.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
				FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_1
				WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttribute5 ON inv.inventory_id = invAttribute5.inventory_id AND inv.attribute_group_id = invAttribute5.attribute_group_id 
WHERE (uom.primary_uom = 'YES')
AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
AND (invStatus.inv_status = 'Available') 
AND (CASE ISNULL(invExp.expiry_date,'') WHEN '' THEN '' ELSE invExp.expiry_date END) >= (CASE ISNULL(invExp.expiry_date,'') WHEN '' THEN '' ELSE CONVERT(VARCHAR(8),GETDATE()+ 1 ,112) END)

GO
/****** Object:  View [dbo].[v_wms_count_plan_detail]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 


CREATE VIEW [dbo].[v_wms_count_plan_detail]
AS
SELECT DISTINCT wh.wh_id
	, countMS.count_id
	, countMS.count_plan_type
	, own.owner_code
	, countDT.count_plan_detail_id
	, countDT.count_master_id
	, z.zone
	, countDT.location_id
	, loc.location 
	, loc.lpn_controlled
	, countDT.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description
	, item.dg_code
	, item.expiry_date_control
	, item.sn_control
	, item.lot_control
	, '' AS brand_name 
	, item.grade
	, item.price
	, countDT.lpn
	, countDT.parent_lpn
	, countDT.inv_status
	, countDT.stock_qty
	, uom.uom_prompt 
	, countDT.lot
	, countDT.expiry_date
	, countDT.serial_number
	, countDT.attribute1
	, countDT.attribute2
	, countDT.attribute3
	, countDT.attribute4
	, countDT.attribute5
	, countMS.create_by 
	, countMS.create_date
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
FROM t_wms_count_plan_master countMS
INNER JOIN t_wms_count_plan_detail countDT ON countMS.count_master_id = countDT.count_master_id
INNER JOIN t_wms_wh_item whItem ON countDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
INNER JOIN t_wms_owner own ON countMS.owner_id = own.owner_id
INNER JOIN t_wms_wh wh ON countMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_location loc ON countDT.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id





GO
/****** Object:  View [dbo].[v_wms_report_count_reconcile_detail]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_count_reconcile_detail]
AS 
WITH tPlanDetail AS
(
	SELECT count_master_id
		,location_id 
		,lpn
		,wh_item_master_id
		,inv_status
		,lot 
		,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,SUM(ISNULL(stock_qty,0)) AS stock_qty
	FROM t_wms_count_plan_detail
	GROUP BY count_master_id
		,location_id 
		,lpn
		,wh_item_master_id
		,inv_status 
		,lot 
		,CONVERT(VARCHAR,expiry_date,112)
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
)
SELECT planMS.count_master_id
	, planMS.count_id
	, planMS.wh_master_id
	, planMS.count_plan_type
	, planMS.count_status
	, planMS.create_by
	, planMS.create_date
	, planMS.close_by
	, planMS.close_date
	, planMS.close_remark
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, tCount.location_id AS location_id
	, loc.location
	, z.zone
	, item.item_number
	, item.description
	, tCount.lot
	, tCount.expiry_date AS expiry_date
	, tCount.serial_number AS serial_number 
	, tCount.inv_status AS inv_status 
	, ISNULL(planDT.stock_qty, 0) AS stock_qty
	, ISNULL(tRec.count_qty, 0) AS count_qty
	, ISNULL(tRec.count_qty, 0) - ISNULL(planDT.stock_qty, 0) AS diff_qty
	, uom.uom_prompt
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, tCount.attribute1
	, tCount.attribute2
	, tCount.attribute3
	, tCount.attribute4
	, tCount.attribute5
	, tRec.create_by	AS count_by
	, tRec.create_date	AS count_date
FROM (SELECT count_master_id 
			,location_id
			,lpn
			,wh_item_master_id
			,inv_status 
			,lot  
			,[expiry_date] 
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5
		FROM t_wms_count_plan_detail
		UNION
		SELECT count_master_id
			,location_id
			,lpn
			,wh_item_master_id
			,inv_status 
			,lot 
			,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5 
		FROM t_wms_count_reconcile
		) tCount
LEFT JOIN tPlanDetail planDT ON tCount.count_master_id = planDT.count_master_id
							 AND tCount.location_id = planDT.location_id
							 AND ISNULL(tCount.lpn,'') = ISNULL(planDT.lpn,'')
							 AND tCount.wh_item_master_id = planDT.wh_item_master_id
							 AND tCount.inv_status = planDT.inv_status 
							 AND ISNULL(tCount.lot,'') = ISNULL(planDT.lot,'')
							 AND ISNULL(tCount.expiry_date,'') = ISNULL(planDT.expiry_date,'')
							 AND ISNULL(tCount.serial_number,'') = ISNULL(planDT.serial_number,'')
							 AND ISNULL(tCount.attribute1,'') = ISNULL(planDT.attribute1,'')
							 AND ISNULL(tCount.attribute2,'') = ISNULL(planDT.attribute2,'')
							 AND ISNULL(tCount.attribute3,'') = ISNULL(planDT.attribute3,'')
							 AND ISNULL(tCount.attribute4,'') = ISNULL(planDT.attribute4,'')
							 AND ISNULL(tCount.attribute5,'') = ISNULL(planDT.attribute5,'')
 LEFT JOIN t_wms_count_reconcile tRec ON tCount.count_master_id = tRec.count_master_id
										AND tCount.location_id = tRec.location_id
										AND ISNULL(tCount.lpn,'') = ISNULL(tRec.lpn,'')
										AND tCount.wh_item_master_id = tRec.wh_item_master_id
										AND tCount.inv_status = tRec.inv_status 
										AND ISNULL(tCount.lot,'') = ISNULL(tRec.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(tRec.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(tRec.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(tRec.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(tRec.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(tRec.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(tRec.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(tRec.attribute5,'') 
INNER JOIN t_wms_count_plan_master planMS ON tCount.count_master_id = planMS.count_master_id
INNER JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id  = tCount.wh_item_master_id
INNER JOIN t_wms_item item ON item.item_master_id = whItem.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
INNER JOIN (SELECT item_master_id
				,item_uom_id
				,uom
				,uom_prompt
			FROM t_wms_item_uom
			WHERE primary_uom = 'YES'
			) uom ON item.item_master_id = uom.item_master_id
INNER JOIN t_wms_owner own ON planMS.owner_id = own.owner_id
INNER JOIN t_wms_wh wh ON planMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_location loc ON tCount.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id
GO
