CREATE VIEW [dbo].[v_wms_report_delivery]
AS
SELECT        dbo.t_wms_truck.truck_name, dbo.t_wms_truck.license_plate, dbo.t_wms_truck.driver_name1, dbo.t_wms_truck.id_card_driver1, dbo.t_wms_truck.driver_name2, dbo.t_wms_truck.id_card_driver2, 
                         dbo.t_wms_truck.driver_name3, dbo.t_wms_truck.id_card_driver3, dbo.t_wms_truck.brand, dbo.t_wms_truck.model, dbo.t_wms_truck.cost_per_km, dbo.t_wms_truck.truck_code, 
                         dbo.t_wms_outbound_manifest_tsp.tsp_manifest_id, dbo.t_wms_outbound_manifest_tsp.manifest_code, dbo.t_wms_outbound_manifest_tsp_order_de.tsp_order_detail_id, 
                         dbo.t_wms_outbound_manifest_tsp_order_de.manifest_code AS Expr1, dbo.t_wms_outbound_manifest_tsp_order_de.wh_master_id, dbo.t_wms_outbound_manifest_tsp_order_de.wh_id, 
                         dbo.t_wms_outbound_manifest_tsp_order_de.owner_id, dbo.t_wms_outbound_manifest_tsp_order_de.owner_code, dbo.t_wms_outbound_manifest_tsp_order_de.cus_province, 
                         dbo.t_wms_outbound_manifest_tsp_order_de.outbound_order_master_id, dbo.t_wms_outbound_manifest_tsp_order_de.outbound_order_number, dbo.t_wms_outbound_manifest_tsp_order_de.outbound_order_detail_id, 
                         dbo.t_wms_outbound_manifest_tsp_order_de.line_number, dbo.t_wms_outbound_manifest_tsp_order_de.item_master_id, dbo.t_wms_outbound_manifest_tsp_order_de.item_number, 
                         dbo.t_wms_outbound_manifest_tsp_order_de.item_quantity, dbo.t_wms_outbound_manifest_tsp_order_de.uom, dbo.t_wms_outbound_manifest_tsp_truck.tsp_truck_id, dbo.t_wms_outbound_manifest_tsp_truck.truck_id, 
                         dbo.t_wms_outbound_master.outbound_order_master_id AS Expr2, dbo.t_wms_outbound_master.order_date, dbo.t_wms_outbound_master.loading_date_plan, dbo.t_wms_outbound_master.delivery_date_plan, 
                         dbo.t_wms_outbound_master.ship_date_plan, dbo.t_wms_outbound_master.loading_date_actual, dbo.t_wms_outbound_master.delivery_date_actual, dbo.t_wms_outbound_master.ship_date_actual, 
                         dbo.t_wms_outbound_master.customer_order_number, dbo.t_wms_outbound_master.customer_purchase_order, dbo.t_wms_outbound_master.customer_id, dbo.t_wms_outbound_master.customer_code, 
                         dbo.t_wms_outbound_master.customer_name, dbo.t_wms_outbound_master.cus_description, dbo.t_wms_outbound_master.cus_addr_line_1, dbo.t_wms_outbound_master.cus_addr_line_2, 
                         dbo.t_wms_outbound_master.cus_addr_line_3, dbo.t_wms_outbound_master.cus_city, dbo.t_wms_outbound_master.cus_province AS Expr3, dbo.t_wms_outbound_master.cus_postal_code, 
                         dbo.t_wms_outbound_master.cus_country_code, dbo.t_wms_outbound_master.cus_country_name, dbo.t_wms_outbound_master.cus_contact, dbo.t_wms_outbound_master.cus_phone, dbo.t_wms_outbound_master.cus_fax, 
                         dbo.t_wms_outbound_master.cus_email, dbo.t_wms_truck_type.truck_type, dbo.t_wms_truck_type.volume, dbo.t_wms_truck_type.weight, dbo.t_wms_item.description, dbo.t_wms_outbound_master.order_status
FROM            dbo.t_wms_outbound_manifest_tsp_order_de INNER JOIN
                         dbo.t_wms_outbound_manifest_tsp ON dbo.t_wms_outbound_manifest_tsp_order_de.tsp_manifest_id = dbo.t_wms_outbound_manifest_tsp.tsp_manifest_id INNER JOIN
                         dbo.t_wms_outbound_manifest_tsp_truck ON dbo.t_wms_outbound_manifest_tsp_order_de.tsp_truck_id = dbo.t_wms_outbound_manifest_tsp_truck.tsp_truck_id AND 
                         dbo.t_wms_outbound_manifest_tsp.tsp_manifest_id = dbo.t_wms_outbound_manifest_tsp_truck.tsp_manifest_id INNER JOIN
                         dbo.t_wms_truck ON dbo.t_wms_outbound_manifest_tsp_truck.truck_id = dbo.t_wms_truck.truck_id INNER JOIN
                         dbo.t_wms_outbound_master ON dbo.t_wms_outbound_manifest_tsp_order_de.outbound_order_master_id = dbo.t_wms_outbound_master.outbound_order_master_id INNER JOIN
                         dbo.t_wms_truck_type ON dbo.t_wms_truck.truck_type_id = dbo.t_wms_truck_type.truck_type_id INNER JOIN
                         dbo.t_wms_item ON dbo.t_wms_outbound_manifest_tsp_order_de.item_master_id = dbo.t_wms_item.item_master_id
