CREATE VIEW [dbo].[v_wms_count_plan_detail_mini]
AS
SELECT planMS.count_master_id
	, planMS.wh_master_id
	, planMS.count_id
	, planMS.count_status
	, planDT.count_plan_detail_id
	, planDT.location_id
	, loc.location
	, loc.pick_sequence
	, planDT.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description AS item_description
	, item.lot_control
	, item.sn_control
	, item.attribute1_control
	, item.attribute2_control
	, item.attribute3_control
	, item.attribute4_control
	, item.attribute5_control
	, item.expiry_date_control 
	, planMS.owner_id
	, own.owner_code
	, planDT.parent_lpn
	, planDT.lpn
	, planDT.lot
	, planDT.expiry_date
	, planDT.serial_number
	, planDT.stock_qty
	, planDT.count_qty
	, planDT.attribute1
	, planDT.attribute2
	, planDT.attribute3
	, planDT.attribute4
	, planDT.attribute5
	, uom.item_uom_id
	, uom.uom_prompt
	, uom.uom
FROM dbo.t_wms_count_plan_master AS planMS 
INNER JOIN dbo.t_wms_count_plan_detail AS planDT ON planMS.count_master_id = planDT.count_master_id 
INNER JOIN dbo.t_wms_location AS loc ON planDT.location_id = loc.location_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON planDT.wh_item_master_id = whItem.wh_item_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
INNER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
INNER JOIN dbo.t_wms_owner AS own ON planMS.owner_id = own.owner_id




