/****** Object:  View [dbo].[v_wms_count_plan_diff_day]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE view [dbo].[v_wms_count_plan_diff_day]
AS
WITH countPlanEx AS
(
	SELECT ROW_NUMBER() OVER (ORDER BY customer_code,create_date,count_id) AS RowNumber
		, count_id
		, customer_code 
		, CONVERT(DATE, create_date) AS create_date	
	 FROM t_wms_count_plan_master_external
)
SELECT count_id
	, customer_code 
	, CONVERT(DATE, create_date) AS create_date
	, ISNULL((SELECT TOP 1 CONVERT(DATE, create_date) FROM countPlanEx planMS 
			   WHERE cPlan.customer_code = planMS.customer_code 
			   AND planMS.RowNumber > cPlan.RowNumber
			  ),CONVERT(DATE, create_date))	AS next_date
	, DATEDIFF(DAY,CONVERT(DATE, create_date),ISNULL((SELECT TOP 1 CONVERT(DATE, create_date) FROM countPlanEx planMS 
													   WHERE cPlan.customer_code = planMS.customer_code 
													   AND planMS.RowNumber > cPlan.RowNumber
													  ),CONVERT(DATE, create_date))) diffDay
FROM countPlanEx cPlan
--where customer_code = '107324'
----ORDER BY customer_code, create_date, count_id
GO
