CREATE VIEW [dbo].[v_wms_outbound_pack_for_check]
AS
SELECT pickMS.outbound_order_master_id
	,pickMS.outbound_pick_master_id
	,pickDT.outbound_pick_detail_id
	,pickDT.outbound_order_detail_id
	,obDT.line_number
	,pickDT.staging_location_id
	,pickDT.staging_parent_lpn
	,pickDT.staging_lpn
	,pickDT.wh_item_master_id
	,item.item_master_id
	,item.item_number
	,pickDT.pick_line_number
	,pickDT.lot_number
	,pickDT.expiry_date
	,pickDT.attribute1
	,pickDT.attribute2
	,pickDT.attribute3
	,pickDT.attribute4
	,pickDT.attribute5
	,pickDT.serial_number
	,pickDT.receive_date
	,pickDT.mfg_date
	,pickDT.quantity_stage
	,packDT.quantity_pack
	,obDT.default_item_status
	,pickDT.is_override
FROM t_wms_outbound_pick_master pickMS
INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
INNER JOIN t_wms_outbound_detail obDT on pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
INNER JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
LEFT JOIN (SELECT outbound_pick_detail_id
				,SUM(quantity_pack) as quantity_pack
			FROM t_wms_outbound_pack_detail
			GROUP BY outbound_pick_detail_id
			) packDT on pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id
 
GO
