CREATE VIEW [dbo].[v_wms_inventory_data_for_release]
AS
SELECT inv.inventory_id
, inv.attribute_group_id
, inv.inv_type
, inv.wh_master_id
, inv.owner_id 
, inv.location_id
, inv.parent_lpn
, inv.lpn
, inv.wh_item_master_id
, '' AS serial_number
, inv.quantity
, inv.quantity_allocated
, inv.quantity_incoming
--, invSn.serial_number AS serial_number
--, ISNULL(invSN.quantity, inv.quantity) AS quantity
--, ISNULL(invSN.quantity_allocated,inv.quantity_allocated) AS quantity_allocated
--, ISNULL(invSN.quantity_incoming,inv.quantity_incoming) AS quantity_incoming
, inv.receive_date
, inv.mfg_date
, invStatus.inv_status
, inv.inventory_status_id
, loc.location
, loc.loc_type
, loc.pick_sequence
, loc.pick_area_id 
, loc.putaway_sequence
, invLot.lot_number
, invExp.expiry_date AS expiry_date 
, loc.lpn_controlled 
, invAttribute1.attribute1
, invAttribute2.attribute2
, invAttribute3.attribute3
, invAttribute4.attribute4
, invAttribute5.attribute5 
FROM dbo.t_wms_inventory AS inv 
INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id
--LEFT JOIN (SELECT  inventory_id
--				,attribute_group_id
--				,attribute_value AS serial_number
--				,quantity
--				,quantity_allocated
--				,quantity_incoming
--		   FROM dbo.t_wms_inventory_attribute
--		   WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
--		   ) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id)  
LEFT OUTER JOIN  (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttribute1 ON inv.inventory_id = invAttribute1.inventory_id AND inv.attribute_group_id = invAttribute1.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttribute2 ON inv.inventory_id = invAttribute2.inventory_id AND inv.attribute_group_id = invAttribute2.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttribute3 ON inv.inventory_id = invAttribute3.inventory_id AND inv.attribute_group_id = invAttribute3.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttribute4 ON inv.inventory_id = invAttribute4.inventory_id AND inv.attribute_group_id = invAttribute4.attribute_group_id 
LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
				FROM dbo.t_wms_inventory_attribute
				WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttribute5 ON inv.inventory_id = invAttribute5.inventory_id AND inv.attribute_group_id = invAttribute5.attribute_group_id 


