/****** Object:  View [dbo].[v_wms_count_reconcile]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_count_reconcile]
AS
SELECT countMS.wh_master_id
	, wh.wh_id
	, countMS.count_master_id
	, countRec.count_reconcile_id
	, countMS.count_id
	, countMS.count_status
	, countMS.count_plan_type
	, countMS.create_by AS create_plan_by
	, own.owner_code AS owner_id
	, z.zone
	, loc.location
	, ISNULL(countRec.expect_qty,0) AS stock_qty
	, ISNULL(countRec.count_qty,0) AS count_qty
	, ISNULL(countRec.count_qty,0) - ISNULL(countRec.expect_qty,0) AS diff_qty
	, uom.uom_prompt 
	, countRec.wh_item_master_id
	, item.item_number
	, item.description
	, item.dg_code
	, item.price
	, item.grade
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, countRec.approve_adjust
	, countRec.cost
	, countRec.adjust_status 
	, countRec.host_qty
	, countRec.parent_lpn 
	, countRec.lpn
	, countRec.lot
	, countRec.expiry_date
	, countRec.serial_number
	, countRec.inv_status
	, countRec.attribute1
	, countRec.attribute2
	, countRec.attribute3
	, countRec.attribute4
	, countRec.attribute5
	, countRec.create_by
	, countRec.create_date
FROM t_wms_count_plan_master countMS
INNER JOIN t_wms_count_reconcile countRec ON countMS.count_master_id = countRec.count_master_id
INNER JOIN t_wms_wh_item whItem ON countRec.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
INNER JOIN t_wms_owner own ON countMS.owner_id = own.owner_id
INNER JOIN t_wms_wh wh ON countMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_location loc ON countRec.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id
 


GO
