SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_count_un_plan]
AS
SELECT        dbo.t_wms_count_plan_master.wh_master_id, dbo.t_wms_wh.wh_id, dbo.t_wms_owner.owner_id, dbo.t_wms_owner.owner_code, dbo.t_wms_count_plan_master.count_master_id, 
                         dbo.t_wms_count_plan_master.count_id, dbo.t_wms_item.item_number, dbo.t_wms_item.description, dbo.t_wms_zone.zone, dbo.t_wms_location.location, dbo.t_wms_count_reconcile.expect_qty AS stock_qty, 
                         dbo.t_wms_count_reconcile.count_qty, ISNULL(dbo.t_wms_count_reconcile.expect_qty, 0) - ISNULL(dbo.t_wms_count_reconcile.count_qty, 0) AS diff_qty,
                             (SELECT        uom_prompt
                               FROM            dbo.t_wms_item_uom
                               WHERE        (item_master_id = dbo.t_wms_item.item_master_id) AND (primary_uom = 'YES')) AS uom_prompt, dbo.t_wms_count_reconcile.lpn, dbo.t_wms_count_reconcile.lot, 
                         dbo.t_wms_count_reconcile.expiry_date, dbo.t_wms_count_reconcile.serial_number, dbo.t_wms_count_reconcile.location_id, dbo.t_wms_count_reconcile.inv_status, dbo.t_wms_count_reconcile.parent_lpn, 
                         dbo.t_wms_item.dg_code, dbo.t_wms_item.price, dbo.t_wms_item.grade
FROM            dbo.t_wms_zone_location INNER JOIN
                         dbo.t_wms_location INNER JOIN
                         dbo.t_wms_count_plan_master INNER JOIN
                         dbo.t_wms_wh ON dbo.t_wms_count_plan_master.wh_master_id = dbo.t_wms_wh.wh_master_id ON dbo.t_wms_location.wh_master_id = dbo.t_wms_wh.wh_master_id ON 
                         dbo.t_wms_zone_location.location_id = dbo.t_wms_location.location_id INNER JOIN
                         dbo.t_wms_zone ON dbo.t_wms_zone_location.zone_id = dbo.t_wms_zone.zone_id INNER JOIN
                         dbo.t_wms_count_reconcile ON dbo.t_wms_location.location_id = dbo.t_wms_count_reconcile.location_id AND 
                         dbo.t_wms_count_plan_master.count_master_id = dbo.t_wms_count_reconcile.count_master_id INNER JOIN
                         dbo.t_wms_item INNER JOIN
                         dbo.t_wms_wh_item ON dbo.t_wms_item.item_master_id = dbo.t_wms_wh_item.item_master_id INNER JOIN
                         dbo.t_wms_owner ON dbo.t_wms_item.owner_id = dbo.t_wms_owner.owner_id ON dbo.t_wms_count_reconcile.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id



