GO


CREATE VIEW [dbo].[v_wms_delivery_note_report]
AS
SELECT convert(varchar(36),obMS.outbound_order_master_id) AS outbound_order_master_id
	, t_owner.owner_id
	, t_owner.owner_code
	, t_owner.owner_name
	, ISNULL(t_owner.addr_line_1, '') + ' ' + ISNULL(t_owner.addr_line_2, '') + ' ' + ISNULL(t_owner.addr_line_3, '') + ' ' + ISNULL(t_owner.city, '') + ' ' + ISNULL(t_owner.province, '') + ' ' + ISNULL(t_owner.postal_code, '') AS owner_address
	, obMS.customer_code
	, obMS.customer_name
	, ISNULL(obMS.cus_addr_line_1, '') + ' ' + ISNULL(obMS.cus_addr_line_2, '') + ' ' + ISNULL(obMS.cus_addr_line_3, '') + ' ' + ISNULL(obMS.cus_city, '') + ' ' + ISNULL(obMS.cus_province, '') + ' ' + ISNULL(obMS.cus_postal_code, '') AS customer_address
	, ISNULL(obMS.ship_to_name, '') + ' ' + ISNULL(obMS.ship_to_addr_line_1, '') + ' ' + ISNULL(obMS.ship_to_addr_line_2, '') + ' ' + ISNULL(obMS.ship_to_addr_line_3, '') + ' ' + ISNULL(obMS.ship_to_city, '') + ' ' + ISNULL(obMS.ship_to_province, '') + ' ' + ISNULL(obMS.ship_to_postal_code, '') AS customer_ship_to
	, obMS.ship_to_description
	, obMS.ship_to_phone
	, obMS.ship_to_fax
	, obMS.outbound_order_number
	, obMS.order_type
	, obMS.order_date
	, obMS.delivery_date_plan
	, obMS.ship_date_plan
	, wh.wh_id
	, cust.route_code + '. ' + cust.route_name AS customer_route
	, CONVERT(INT, obDT.line_number) AS line_number
	, obDT.wh_item_master_id
	, item.item_number
	, item.description  AS item_description
	, obDT.lot_number
	, obDT.expiry_date
	, CONVERT(datetime, obDT.expiry_date) AS datetime2_expiry_date
	, obDT.outbound_order_detail_id
	, t_ob_pick.serial_number
	, t_ob_pick.quantity_load
	, obMS.customer_order_number
	, obMS.customer_purchase_order
FROM dbo.t_wms_outbound_master AS obMS 
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN dbo.t_wms_owner AS t_owner ON obMS.owner_id = t_owner.owner_id
INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_wh_item whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
LEFT JOIN t_wms_customer cust ON obMS.customer_id = cust.customer_id
LEFT JOIN dbo.t_wms_outbound_pick_detail AS t_ob_pick ON obDT.outbound_order_detail_id = t_ob_pick.outbound_order_detail_id 




GO
/****** Object:  View [dbo].[v_wms_outbound_master_load]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_outbound_master_load]
as
SELECT wh.wh_master_id
	, wh.wh_id
	, ow.owner_id
	, ow.owner_code
	, ms.dock_door_id
	, ms.load_id
	, ms.pick_type
	, COUNT(*) AS order_qty
	, (CASE WHEN COUNT(CASE WHEN ms.order_status = 'OPEN' THEN 1 END) = COUNT(*) THEN 'OPEN'    
		    WHEN COUNT(CASE WHEN ms.order_status = 'RELEASE' THEN 1 END) = COUNT(*) THEN 'RELEASE' 
		    WHEN COUNT(CASE WHEN ms.order_status = 'PICKED' THEN 1 END) = COUNT(*) THEN 'PICKED'
		    WHEN COUNT(CASE WHEN ms.order_status = 'LOADED' THEN 1 END) = COUNT(*) THEN 'LOADED' 
		    WHEN COUNT(CASE WHEN (ms.order_status = 'LOADING' OR ms.order_status = 'LOADED') THEN 1 END) > 0 THEN 'LOADING' 
		    WHEN COUNT(CASE WHEN (ms.order_status = 'PICK' OR ms.order_status = 'PICKED') THEN 1 END) > 0 THEN 'PICK' ELSE 'CLOSE' END) AS load_status
, (CASE WHEN COUNT(CASE WHEN (ms.order_status = 'OPEN' OR ms.order_status = 'RELEASE') THEN 1 END) = COUNT(*) THEN CONVERT(bit, 1) ELSE CONVERT(bit, 0) END) AS cancel_status
, MAX(ms.create_date) AS create_date
FROM dbo.t_wms_outbound_master AS ms 
INNER JOIN dbo.t_wms_wh AS wh ON ms.wh_master_id = wh.wh_master_id 
INNER JOIN dbo.t_wms_owner AS ow ON ms.owner_id = ow.owner_id
WHERE (ISNULL(ms.load_id, N'') <> '')
GROUP BY wh.wh_master_id, wh.wh_id, ow.owner_id, ow.owner_code, ms.dock_door_id, ms.load_id, ms.pick_type 
GO
/****** Object:  View [dbo].[v_wms_dashboard_trans_daily_outbound]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_dashboard_trans_daily_outbound]
AS

WITH tOutbound AS
(
SELECT obMS.wh_master_id 
	,obMS.wh_id
	,obMS.owner_id
	,obMS.owner_code
	,cate.category_id
	,item_category
	,obDT.item_master_id
	,obDT.item_number
	,obDT.quantity_order AS quantity
	,CONVERT(DATE,obMS.ship_date_plan)  AS trans_date
	,'OPEN' AS trans_type
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_item item ON obDT.item_master_id = item.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
WHERE CONVERT(DATE,obMS.ship_date_plan) = CONVERT(DATE,GETDATE())
)
, tTranPickShip AS
(
	SELECT wh_master_id
		,wh_id
		,owner_id
		,owner_code
		,category_id
		,item_category
		,item_master_id
		,item_number
		,quantity
		,trans_date
		,trans_type
	FROM t_wms_dashboard_trans_out
	WHERE trans_type IN ('PICK','SHIP')
	AND CONVERT(DATE,trans_date) = CONVERT(DATE,GETDATE())
)

SELECT 
tmp.trans_type
,tmp.wh_id
,tmp.wh_master_id
,Convert(datetime,FORMAT(tmp.trans_date,'MM-dd-yyyy hh:00')) as trans_date
,sum(tmp.quantity) as quantity
FROM
(
	SELECT * FROM tOutbound
	UNION ALL
	SELECT * FROM tTranPickShip
) as tmp
GROUP BY 
tmp.trans_type
,tmp.wh_id
,tmp.wh_master_id
,Convert(datetime,FORMAT(tmp.trans_date,'MM-dd-yyyy hh:00'))

GO
