CREATE VIEW [dbo].[v_wms_export_inbound_detail_receipt]
AS

SELECT '0' as sys_id,t_wms_wh_user.[user_id], t_wms_wh.wh_master_id, t_wms_wh.wh_id, t_wms_owner.owner_id, t_wms_owner.owner_code, t_wms_inbound_master.inbound_order_number, t_wms_inbound_master.order_type, t_wms_inbound_master.order_status, 
             t_wms_inbound_detail.line_number, t_wms_item.item_number, t_wms_item.[description], t_wms_receipt_detail.lot_number
			 , convert(date,t_wms_receipt_detail.[expiry_date],112) as [expiry_date]
			 , t_wms_receipt_detail.serial_number, t_wms_receipt_detail.quantity_received, t_wms_item_uom.uom, 
             t_wms_receipt_detail.receipt_item_status, t_wms_item.category_id, t_wms_category.item_category
			 , convert(date,t_wms_receipt_detail.create_date) as receive_date
			 ,t_wms_inbound_master.[description] as project_manager
			 ,t_wms_inbound_detail.user_def1 as customer_by_line
			 ,t_wms_receipt_header.receipt_number
			 ,t_wms_receipt_header.user_def1 as receipt_no
FROM   t_wms_receipt_detail INNER JOIN
			 t_wms_receipt_header ON t_wms_receipt_detail.receipt_header_id = t_wms_receipt_header.receipt_header_id INNER JOIN
             t_wms_inbound_detail ON t_wms_receipt_detail.inbound_order_detail_id = t_wms_inbound_detail.inbound_order_detail_id INNER JOIN
             t_wms_inbound_master ON t_wms_inbound_detail.inbound_order_master_id = t_wms_inbound_master.inbound_order_master_id INNER JOIN
             t_wms_wh ON t_wms_inbound_master.wh_master_id = t_wms_wh.wh_master_id INNER JOIN
             t_wms_wh_user ON t_wms_wh.wh_master_id = t_wms_wh_user.wh_master_id INNER JOIN
             t_wms_owner ON t_wms_inbound_master.owner_id = t_wms_owner.owner_id INNER JOIN
             t_wms_item_uom ON t_wms_receipt_detail.item_uom_id = t_wms_item_uom.item_uom_id INNER JOIN
             t_wms_item ON t_wms_item_uom.item_master_id = t_wms_item.item_master_id INNER JOIN
             t_wms_category ON t_wms_item.category_id = t_wms_category.category_id



