/****** Object:  View [dbo].[v_wms_dashboard_trans_daily_inbound]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_dashboard_trans_daily_inbound]
AS

WITH tInbound AS
(
SELECT ibMS.wh_master_id 
	,ibMS.wh_id
	,ibMS.owner_id
	,ibMS.owner_code
	,cate.category_id
	,item_category
	,ibDT.item_master_id
	,ibDT.item_number
	,ibDT.quantity_order AS quantity
	,(CASE WHEN ibMS.expected_delivery_date IS NULL THEN CONVERT(DATE,ibDT.create_date) ELSE CONVERT(DATE,ibMS.expected_delivery_date) END) AS trans_date
	,'OPEN' AS trans_type
FROM t_wms_inbound_master ibMS
INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
WHERE (CASE WHEN ibMS.expected_delivery_date IS NULL THEN CONVERT(DATE,ibDT.create_date) ELSE CONVERT(DATE,ibMS.expected_delivery_date) END) = CONVERT(DATE,GETDATE())
)
, tTranReciveClose AS
(
	SELECT wh_master_id
		,wh_id
		,owner_id
		,owner_code
		,category_id
		,item_category
		,item_master_id
		,item_number
		,quantity
		,trans_date
		,trans_type
	FROM t_wms_dashboard_trans_in 
	WHERE trans_type IN ('RECEIVING','CLOSE')
	AND CONVERT(DATE,trans_date) = CONVERT(DATE,GETDATE())
)

SELECT
tmp.trans_type
,tmp.wh_id
,tmp.wh_master_id
,Convert(datetime,FORMAT(tmp.trans_date,'MM-dd-yyyy hh:00')) as trans_date
,sum(tmp.quantity) as quantity
FROM
(
	SELECT * FROM tInbound
	UNION ALL
	SELECT * FROM tTranReciveClose
)as tmp
GROUP BY 
tmp.trans_type
,tmp.wh_id
,tmp.wh_master_id
,Convert(datetime,FORMAT(tmp.trans_date,'MM-dd-yyyy hh:00')) 

GO
/****** Object:  Table [dbo].[t_wms_item_bom_detail]    Script Date: 08/08/2025 11:11:28 ******/
