GO
CREATE TABLE [dbo].[t_wms_item_bom_detail](
	[bom_detail_id] [int] IDENTITY(1,1) NOT NULL,
	[bom_id] [int] NOT NULL,
	[line_no] [varchar](10) NOT NULL,
	[description] [nvarchar](255) NULL,
	[quantity] [float] NULL,
	[wh_item_master_id] [uniqueidentifier] NOT NULL,
	[item_master_id] [uniqueidentifier] NOT NULL,
	[item_number] [nvarchar](50) NOT NULL,
	[item_uom_id] [uniqueidentifier] NOT NULL,
	[uom] [nvarchar](20) NOT NULL,
	[create_by] [nvarchar](25) NOT NULL,
	[create_date] [datetime] NOT NULL,
