CREATE view [dbo].[v_wms_inbound_calc_bom]
AS

with inbound_detail_cte(inbound_order_master_id, wh_item_master_id, bom_wh_item_master_id, bom_id, bom_detail_id, quantity_order, quantity_receive, bom_quantity_receive)
as
(
	-- Get Inbound detail
	select 
		ibd.inbound_order_master_id
		 , ibd.wh_item_master_id
		 , ibd.bom_wh_item_master_id
		 , ibd.bom_id
		 , ibd.bom_detail_id 
		 , sum(isnull(ibd.quantity_order,0)) as quantity_order
		 , sum(isnull(ibd.quantity_receive,0)) as quantity_receive
		 , sum(isnull(ibd.bom_quantity_receive,0)) as bom_quantity_receive
	from t_wms_inbound_detail ibd
	where ibd.bom_id is not null
	--where ibd.inbound_order_master_id = @inbound_order_master_id	
	group by 
	ibd.inbound_order_master_id
	 , ibd.wh_item_master_id
	 , ibd.bom_wh_item_master_id
	 , ibd.bom_id
	 , ibd.bom_detail_id	  
), 
item_bom_detail_cte(
	bom_id, inbound_order_master_id, bom_mother_quantity)
as
(
	-- Get ว่าจะได้แม่เท่าไรของแต่ละ bom แม่	และ จำนวน rows ของ bom detial master จะต้องมีเท่ากับ rows ใน inbound detail
	select 
		R2.bom_id
		, R2.inbound_order_master_id
		, case when R1.count_bom_detail_rows = R2.count_inbound_rows then R2.bom_mother_quantity else 0 end as bom_mother_quantity
	from (
		select bom_id, count(bom_id) as count_bom_detail_rows from t_wms_item_bom_detail
		where bom_id in (select distinct inbound_detail_cte.bom_id from inbound_detail_cte)
		group by bom_id
	)R1 left join (	 
		select 
			 item_bom_detail.bom_id		 
			 , ibd.inbound_order_master_id			 
			 , min(convert(int,(case when (ibd.quantity_receive - ibd.bom_quantity_receive) >= isnull(item_bom_detail.quantity,1)
				 then (ibd.quantity_receive - ibd.bom_quantity_receive) / isnull(item_bom_detail.quantity,1)
				 else 0 end))
			 ) as bom_mother_quantity
			 , count(item_bom_detail.bom_id	) as count_inbound_rows					
		from t_wms_item_bom_detail item_bom_detail 
		left join inbound_detail_cte ibd on ibd.bom_id =  item_bom_detail.bom_id and ibd.bom_detail_id = item_bom_detail.bom_detail_id
		--where ibd.inbound_order_master_id = @inbound_order_master_id
		group by item_bom_detail.bom_id, ibd.inbound_order_master_id	
	) R2 on R1.bom_id = R2.bom_id			
),
calc_inbound_detail(
	bom_id, bom_detail_id, item_bom_detail_quantity, inbound_order_master_id, wh_item_master_id
, bom_wh_master_id, bom_owner_id, bom_wh_item_master_id, bom_item_master_id, bom_item_number
, quantity_order, quantity_receive, bom_quantity_receive, bom_mother_quantity, after_bom_quantity_receive)
as
(
	select 
		 ibd.bom_id
		 , ibd.bom_detail_id
		 , isnull(item_bom_detail.quantity,1) as item_bom_detail_quantity
		 , ibd.inbound_order_master_id
		 , ibd.wh_item_master_id
		 -- item แม่	
		 , item_bom.wh_master_id as bom_wh_master_id
		 , item_bom.owner_id as bom_owner_id
		 , ibd.bom_wh_item_master_id 
		 , item_bom.item_master_id as bom_item_master_id
		 , item_bom.item_number as bom_item_number
		 --
		 , ibd.quantity_order
		 , ibd.quantity_receive
		 , ibd.bom_quantity_receive	
		 --bom_mother_quantity
		 , item_bom_detail_cte.bom_mother_quantity
		 -- (จำนวนแม่ที่ได้ * จำนวน master qty ของ bom) // ไม่รวม qty bom เก่า เวลาจะ update จะต้องเอาไปเพิ่มเอง
		 --, isnull(ibd.bom_quantity_receive,0) + (item_bom_detail_cte.bom_mother_quantity * isnull(item_bom_detail.quantity,1)) as after_bom_quantity_receive			
		 , (item_bom_detail_cte.bom_mother_quantity * isnull(item_bom_detail.quantity,1)) as after_bom_quantity_receive		 
	from inbound_detail_cte ibd	
	left join t_wms_item_bom_detail item_bom_detail	on item_bom_detail.bom_id = ibd.bom_id 
		and item_bom_detail.bom_detail_id = ibd.bom_detail_id 
	left join t_wms_item_bom item_bom on item_bom.bom_id = item_bom_detail.bom_id
	left join item_bom_detail_cte item_bom_detail_cte on item_bom_detail_cte.bom_id = ibd.bom_id
		and item_bom_detail_cte.inbound_order_master_id = ibd.inbound_order_master_id
	--where ibd.inbound_order_master_id = @inbound_order_master_id
) select * from calc_inbound_detail



GO
