CREATE VIEW [dbo].[v_wms_inbound_detail]
AS
SELECT ibMS.wh_master_id
, wh.wh_id 
, ibMS.inbound_order_master_id
, convert(varchar(36),ibMS.inbound_order_master_id) as str_inbound_order_master_id
, ibMS.inbound_order_number
, ibMS.order_type
, ibMS.order_status
, ibMS.create_date AS order_create_date
, supp.supplier_code
, supp.supplier_name
, ISNULL(supp.supplier_code, '') + ' ' + ISNULL(supp.supplier_name, '') + ' ' + ISNULL(supp.addr_line_1, '') + ' ' + ISNULL(supp.addr_line_2, '') + ' ' + ISNULL(supp.addr_line_3, '') AS supplier_code_name
, ibMS.customer_id
, cust.customer_code
, cust.customer_name
, ISNULL(cust.customer_code, '') + ' ' + ISNULL(cust.customer_name, '') + ' ' + ISNULL(cust.addr_line_1, '') + ' ' + ISNULL(cust.addr_line_2, '') + ' ' + ISNULL(cust.addr_line_3, '') AS customer_code_name
, ibMS.expected_delivery_date
, ibDT.inbound_order_detail_id 
, ibDT.wh_item_master_id
, ibDT.line_number
, item.item_number
, item.description
, ibDT.quantity_order
, ibDT.quantity_receive
, ibDT.quantity_order - ISNULL(ibDT.quantity_receive,0) AS quantity_diff
, ibDT.item_uom_id
, uom.uom_prompt
, uom.uom
, ibDT.item_status 
, (ibDT.quantity_order - ibDT.quantity_receive) * ibDT.price AS total_price_diff
, ibDT.over_receipt_allowed
, ibDT.over_receipt_percentage
, ibDT.default_item_status
, ibDT.grade
, ibDT.price 
, ibDT.lpn
, ibDT.lot_number
, ibDT.expiry_date
, ibDT.serial_number 
, ibDT.user_def1
, ibDT.user_def2
, ibDT.user_def3
, ibDT.user_def4
, ibDT.user_def5
, ibDT.user_def6
, ibDT.user_def7
, ibMS.user_def1 AS ibMS_user_df1
, ibMS.user_def2 AS ibMS_user_df2
, ibMS.posting_date
, ibDT.create_date
, ibDT.create_by 
, ibDT.rowversion
FROM t_wms_inbound_master ibMS
INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
INNER JOIN t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN dbo.t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id 
 LEFT OUTER JOIN dbo.t_wms_customer cust ON ibMS.customer_id = cust.customer_id 
 LEFT OUTER JOIN dbo.t_wms_supplier supp ON ibMS.supplier_id = supp.supplier_id


GO
