CREATE VIEW [dbo].[v_wms_inbound_detail_bom_ms_comp_inv]
AS

select inb_bom.wh_item_master_id,inb_bom.item_master_id,inb_bom.item_number,inb_bom.bom_quantity,isnull(inv.inventory_quantity,0) as inventory_quantity
	,inb_bom.[description] as item_desc,inb_bom.owner_id,inb_bom.wh_master_id
	,inb_bom.owner_code,'' as owner_name
	,inb_bom.wh_id,'' as wh_name
	from (SELECT dbo.t_wms_item_bom.wh_item_master_id,dbo.t_wms_item_bom.item_master_id
			   , dbo.t_wms_item_bom.item_number, dbo.t_wms_item_bom.bom_desc as [description]
		,SUM(dbo.t_wms_inbound_bom_detail.quantity_order) AS bom_quantity
		,dbo.t_wms_inbound_bom_master.owner_id, dbo.t_wms_inbound_bom_master.wh_master_id
		,dbo.t_wms_inbound_bom_master.wh_id,dbo.t_wms_inbound_bom_master.owner_code
		FROM  dbo.t_wms_inbound_bom_master 
				INNER JOIN dbo.t_wms_inbound_bom_detail ON dbo.t_wms_inbound_bom_master.inbound_order_master_id = dbo.t_wms_inbound_bom_detail.inbound_order_master_id
				INNER JOIN dbo.t_wms_item_bom ON dbo.t_wms_inbound_bom_detail.bom_id = dbo.t_wms_item_bom.bom_id
		WHERE (dbo.t_wms_inbound_bom_master.is_copy_master = 0) AND (dbo.t_wms_inbound_bom_master.order_status = N'OPEN')
		GROUP BY dbo.t_wms_item_bom.wh_item_master_id,dbo.t_wms_item_bom.item_master_id,dbo.t_wms_item_bom.item_number
				 ,dbo.t_wms_item_bom.bom_desc
				 ,dbo.t_wms_inbound_bom_master.owner_id, dbo.t_wms_inbound_bom_master.wh_master_id
				 ,dbo.t_wms_inbound_bom_master.wh_id,dbo.t_wms_inbound_bom_master.owner_code
	) as inb_bom 
	
	outer apply (select SUM(inv.quantity) as inventory_quantity from dbo.t_wms_inventory inv 
						  where inv.wh_master_id=inb_bom.wh_master_id and inv.owner_id=inb_bom.owner_id 
							and inv.wh_item_master_id=inb_bom.wh_item_master_id and inv.quantity > 0) as inv

