CREATE VIEW [dbo].[v_wms_inbound_detail_report]
AS
SELECT ibMs.*
	,cust.customer_code
	,cust.customer_name
	,supp.supplier_code
	,supp.supplier_name
	,ibDT.line_number
	,ibDT.item_number
	,item.description	AS item_description
	,ISNULL(ibDT.quantity_order,0)  AS quantity_order
	,ISNULL(ibDT.quantity_receive,0) AS quantity_receive
	,ISNULL(ibDT.quantity_order,0) - ISNULL(ibDT.quantity_receive,0) AS quantity_remain
	,item.category_id
	,cate.item_category
FROM t_wms_inbound_master ibMs
INNER JOIN t_wms_inbound_detail ibDT on ibMs.inbound_order_master_id = ibDT.inbound_order_master_id
INNER JOIN t_wms_wh wh ON ibMs.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_wh_item whItem on ibDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
LEFT JOIN t_wms_customer cust on ibMs.customer_id = cust.customer_id
LEFT JOIN t_wms_supplier supp on supp.[supplier_id] = ibMs.[supplier_id]







