SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_inbound_log_receive]
AS
SELECT 
	  tranLog.to_warehouse	AS warehouse
	, tranLog.order_number 
	, tranLog.line_number
	, tranLog.item_number
	, item.description
	, ibDT.quantity_order
	, ibDT.quantity_receive
	, tranLog.quantity
	, tranLog.quantity_uom
	, tranLog.reason_code
	, tranLog.device
	, tranLog.tran_type
	, tranLog.create_by
	, tranLog.create_date
	, tranLog.parent_lpn
	, tranLog.lpn	
	, tranLog.lot_number
	, (CASE CONVERT(NVARCHAR,ISNULL(tranLog.expiry_date,''), 112) WHEN '19000101' THEN '' ELSE CONVERT(NVARCHAR,ISNULL(tranLog.expiry_date,''), 112) END) AS expiry_date
	, item.grade
	, item.price
	, itemUOM.uom
	, itemUOM.uom_prompt
	, lpnDetail.quantity			AS quantity_lpn
	, lpnDetail.quantity_receive	AS quantity_lpn_receive
	, tranLog.quantity - lpnDetail.quantity_receive AS quantity_lpn_diff
	, ibDT.lot_number				AS lot_number2
	, ibMS.order_type
	, ibMS.order_status
	, ibMS.user_def1				AS inbound_master_user_df1
	, supp.supplier_code
	, supp.supplier_name
FROM t_com_tran_log tranLog
LEFT JOIN t_wms_inbound_master ibMS ON tranLog.order_number = ibMS.inbound_order_number
LEFT JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
										AND tranLog.line_number = ibDT.line_number
LEFT JOIN t_wms_inbound_lpn_detail lpnDetail ON ibDT.inbound_order_detail_id = lpnDetail.inbound_order_detail_id
LEFT JOIN t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
LEFT JOIN t_wms_item_uom itemUOM ON ibDT.item_uom_id = itemUOM.item_uom_id
LEFT JOIN t_wms_supplier supp ON ibMS.supplier_id = supp.supplier_id
WHERE tran_type = 'IO_RECEIPT'
AND sub_tran_type = 'RECEIPT'







GO
