CREATE VIEW [dbo].[v_wms_inbound_master]
AS
SELECT        dbo.t_wms_inbound_master.inbound_order_master_id, dbo.t_wms_owner.owner_code, dbo.t_wms_wh_user.wh_user_id, 
                         dbo.t_wms_inbound_master.inbound_order_number, dbo.t_wms_inbound_master.order_type, dbo.t_wms_inbound_master.order_status, 
                         dbo.t_wms_inbound_master.expected_delivery_date, dbo.t_wms_supplier.supplier_name, dbo.t_wms_customer.customer_name, 
                         dbo.t_wms_inbound_master.create_by, dbo.t_wms_inbound_master.create_date, dbo.t_wms_wh_user.user_id, 
                         COUNT(dbo.t_wms_inbound_detail.inbound_order_master_id) AS line_count, dbo.t_wms_wh.wh_id
FROM            dbo.t_wms_wh_user INNER JOIN
                         dbo.t_wms_inbound_master INNER JOIN
                         dbo.t_wms_inbound_detail ON dbo.t_wms_inbound_master.inbound_order_master_id = dbo.t_wms_inbound_detail.inbound_order_master_id INNER JOIN
                         dbo.t_wms_owner ON dbo.t_wms_inbound_master.owner_id = dbo.t_wms_owner.owner_id INNER JOIN
                         dbo.t_wms_supplier ON dbo.t_wms_inbound_master.supplier_id = dbo.t_wms_supplier.supplier_id INNER JOIN
                         dbo.t_wms_wh ON dbo.t_wms_inbound_master.wh_master_id = dbo.t_wms_wh.wh_master_id ON 
                         dbo.t_wms_wh_user.wh_master_id = dbo.t_wms_wh.wh_master_id INNER JOIN
                         dbo.t_wms_customer ON dbo.t_wms_inbound_master.customer_id = dbo.t_wms_customer.customer_id
GROUP BY dbo.t_wms_inbound_master.inbound_order_master_id, dbo.t_wms_owner.owner_code, dbo.t_wms_wh_user.wh_user_id, 
                         dbo.t_wms_inbound_master.inbound_order_number, dbo.t_wms_inbound_master.order_type, dbo.t_wms_inbound_master.order_status, 
                         dbo.t_wms_inbound_master.expected_delivery_date, dbo.t_wms_supplier.supplier_name, dbo.t_wms_customer.customer_name, 
                         dbo.t_wms_inbound_master.create_by, dbo.t_wms_inbound_master.create_date, dbo.t_wms_wh_user.user_id, 
                         dbo.t_wms_inbound_detail.inbound_order_master_id, dbo.t_wms_wh.wh_id


GO
