CREATE VIEW [dbo].[v_wms_inbound_order_receive_detail_report]
AS
     SELECT dbo.t_wms_wh.wh_master_id, 
            CONVERT(VARCHAR(36), dbo.t_wms_wh.wh_master_id) AS str_wh_master_id, 
            ibMS.inbound_order_master_id, 
            CONVERT(VARCHAR(36), ibMS.inbound_order_master_id) AS str_inbound_order_master_id, 
            dbo.t_wms_wh.wh_id AS warehouse, 
            ibMS.inbound_order_number AS order_number, 
            ibDT.line_number, 
            item.item_number, 
            item.description, 
            ibDT.quantity_order, 
            recDT.quantity_received, 
            recDT.create_by, 
            recDT.create_date, 
            recDT.lpn, 
            recDT.lot_number, 
            recDT.expiry_date, 
            item.grade, 
            item.price, 
            uom.uom, 
            ibMS.order_type, 
            ibMS.order_status, 
            ibMS.customer_id, 
            ibMS.supplier_id, 
            cust.customer_name, 
            sup.supplier_name, 
            item.user_def1
     FROM dbo.t_wms_wh
          INNER JOIN dbo.t_wms_inbound_master ibMS ON dbo.t_wms_wh.wh_master_id = ibMS.wh_master_id
          INNER JOIN dbo.t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
          INNER JOIN dbo.t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
                                                 AND dbo.t_wms_wh.wh_master_id = whItem.wh_master_id
          INNER JOIN dbo.t_wms_item item ON whItem.item_master_id = item.item_master_id
          INNER JOIN dbo.t_wms_item_uom uom ON item.item_master_id = uom.item_master_id
          INNER JOIN dbo.t_wms_receipt_detail recDT ON uom.item_uom_id = recDT.item_uom_id
                                                       AND ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
          LEFT OUTER JOIN dbo.t_wms_customer cust ON ibMS.customer_id = cust.customer_id
          LEFT OUTER JOIN dbo.t_wms_supplier sup ON ibMS.supplier_id = sup.supplier_id;
GO
