CREATE VIEW [dbo].[v_wms_inbound_qty]
AS
	SELECT
		  ibMS.inbound_order_number 
		, ibMS.wh_master_id
		, item.item_number
		, item.dg_code
		, itemRef.alternate_item_number
		, ibDT.quantity_order
		, ibDT.quantity_receive
		, ibDT.over_receipt_allowed
		, ibDT.over_receipt_percentage
		, (CASE ibDT.over_receipt_allowed 
				WHEN 'YES' 
				THEN ISNULL(ibDT.quantity_order,0) + ((ISNULL(ibDT.quantity_order,0) * ISNULL(ibDT.over_receipt_percentage,0))/100)
				ELSE ISNULL(ibDT.quantity_order,0) 
				END)	AS quantity_over_receive
	FROM t_wms_inbound_master ibMS
	LEFT JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	LEFT JOIN t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
	LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id



