SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_outbound_order]
AS
--====================================================================================================
-- DATE			MODIFY		DESCRIPTION
------------------------------------------------------------------------------------------------------
-- 2020-10-07	NUI			Create new view
--====================================================================================================
	SELECT wh.wh_id
		 , wh.wh_name
		 , obMS.outbound_order_number
		 , obMS.order_type
		 , obMS.order_status
		 , obMS.order_date
		 , obMS.ship_date_actual
		 , obMS.truck_no
		 , obMS.customer_code
		 , obMS.customer_name
		 , obMS.ship_to_code
		 , obMS.ship_to_name
		 , obDT.line_number
		 , item.item_number
		 , item.description AS item_description
		 , obDT.lpn
		 , obDT.lot_number
		 , obDT.expiry_date
		 , obDT.serial_number	 
		 , ISNULL(obDT.quantity_order, 0) AS quantity_order		 
		 , ISNULL(obDT.quantity_pick, 0) AS quantity_pick
		 , ISNULL(obDT.quantity_load, 0) AS quantity_load
		 , ISNULL(obDT.quantity_ship, 0) AS quantity_ship
		 -- for Call Service
		 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
		 -- for Condition
		 , CONVERT(VARCHAR(36),obMS.outbound_order_master_id) AS outbound_order_master_id
	FROM dbo.t_wms_outbound_master AS obMS 
	INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
	INNER JOIN dbo.t_wms_owner AS own ON own.[owner_id] = obMS.[owner_id] 
	INNER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id
	INNER JOIN dbo.t_wms_wh_item AS whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id 
	INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
GO
