CREATE VIEW [dbo].[v_wms_inbound_receipt_detail]
AS
SELECT ibMS.inbound_order_master_id
	, ibMS.inbound_order_number
	, ibMS.wh_master_id
	, wh.wh_id
	, ibMS.order_type
	, ibMS.owner_id
	, own.owner_code
	, ibMS.posting_date
	, ibDT.line_number
	, item.item_number
	, item.description
	, ibDT.inbound_order_detail_id
	, recHD.receipt_header_id
	, recHD.receipt_number
	, recDT.receipt_item_status
	, recDT.quantity_received
	, uom.uom
	, recDT.location_received
	, recDT.parent_lpn
	, recDT.lpn
	, recDT.lot_number
	, recDT.expiry_date
	, recDT.serial_number
	, recDT.attribute1
	, recDT.attribute2
	, recDT.attribute3
	, recDT.attribute4
	, recDT.attribute5
	, supp.supplier_id
	, supp.supplier_code
	, cust.customer_id
	, cust.customer_code
	, ibDT.user_def1
	, ibDT.user_def2
	, ibDT.user_def3
	, ibDT.user_def4
	, ibDT.user_def5
	, ibDT.user_def6
	, ibDT.user_def7
	, ibDT.user_def8
	, ibDT.user_def9
	, ibDT.user_def10
	, recHD.user_def1 AS receipt_ref_no
FROM dbo.t_wms_inbound_detail ibDT
INNER JOIN dbo.t_wms_inbound_master ibMS  ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id 
INNER JOIN dbo.t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id 
INNER JOIN dbo.t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id 
INNER JOIN dbo.t_wms_item item ON whItem.item_master_id =item.item_master_id 
INNER JOIN dbo.t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id 
INNER JOIN dbo.t_wms_owner own ON ibMS.owner_id = own.owner_id 
LEFT JOIN dbo.t_wms_receipt_detail recDT ON ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id 
LEFT JOIN dbo.t_wms_receipt_header recHD ON recDT.receipt_header_id = recHD.receipt_header_id 
LEFT JOIN dbo.t_wms_customer cust ON ibMS.customer_id = cust.customer_id 
LEFT JOIN dbo.t_wms_supplier supp ON ibMS.supplier_id = supp.supplier_id

