CREATE VIEW [dbo].[v_wms_interface_get_uom_prompt]
AS
	SELECT item.item_master_id
		,item.item_number
		,uom.item_uom_id
		,uom.uom_prompt 
		,item.owner_id
		,own.owner_code
		,whItem.wh_master_id
		,wh.wh_id
		,uom.primary_uom
	FROM t_wms_item item
