/****** Object:  View [dbo].[v_wms_inventory_available]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_inventory_available]
AS
SELECT inv.wh_master_id
	,wh.wh_id
	,inv.owner_id
	,own.owner_code
	,zone.zone
	,inv.location_id
	,loc.location
	,item.category_id
	,cate.description AS cate_description
	,inv.wh_item_master_id
	,item.item_master_id
	,item.item_number
	,item.[description]
	,inv.lot_number
	,inv.count_used + inv.count_missing + inv.count_consignment + isnull(pending.count_pending,0) as avaliable
	,inv.count_avaliable
	,inv.count_used
	,inv.count_missing
	,inv.count_consignment
	,ISNULL(CONVERT(DECIMAL(9,0),pending.count_pending),0.0) count_pending 
	,rec.last_create_date
FROM (SELECT 
		--inv.inventory_id
		--,inv.attribute_group_id
		invLot.lot_number
		,inv.wh_master_id
		,inv.location_id
		,inv.owner_id
		,inv.wh_item_master_id
		,SUM(CASE WHEN invstatus.inv_status = 'Available' then inv.quantity else 0.0 end) count_avaliable
		,SUM(CASE WHEN invstatus.inv_status = 'Used' then inv.quantity else 0.0 end) count_used
		,SUM(CASE WHEN invstatus.inv_status = 'Missing CSM' then inv.quantity else 0.0 end) count_missing
		,SUM(CASE WHEN invstatus.inv_status = 'Consignment' then inv.quantity else 0.0 end) count_consignment
	  FROM t_wms_inventory inv
	  INNER JOIN dbo.t_wms_inventory_status as invstatus on inv.inventory_status_id = invstatus.inventory_status_id
	  LEFT JOIN (SELECT inventory_id
					,attribute_group_id
					,attribute_value AS lot_number
			   FROM dbo.t_wms_inventory_attribute
			   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
			   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id)
	  GROUP BY invLot.lot_number,inv.wh_master_id ,inv.location_id ,inv.owner_id ,inv.wh_item_master_id
	   ) inv
INNER JOIN t_wms_wh wh on wh.wh_master_id = inv.wh_master_id
INNER JOIN t_wms_owner own on own.owner_id = inv.owner_id
INNER JOIN t_wms_wh_item whItem on whItem.wh_item_master_id = inv.wh_item_master_id
INNER JOIN t_wms_item item on item.item_master_id = whItem.item_master_id
INNER JOIN t_wms_category cate on cate.category_id = item.category_id
INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc ON loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone zone ON zLoc.zone_id = zone.zone_id
--LEFT JOIN (SELECT inventory_id
--					,attribute_group_id
--					,attribute_value AS lot_number
--			   FROM dbo.t_wms_inventory_attribute
--			   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
--			   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id)
LEFT JOIN (	SELECT host_adj.location,host_adj.item_number,host_adj.lot_number
				,((ISNULL(host_adj.quantity_host_adj,0) - ISNULL(store_adj.quantity_store_adj,0))) * -1 count_pending
			FROM (SELECT h_adj.location, h_adj.item_number, h_adj.lot_number, SUM(h_adj.quantity) AS quantity_host_adj
				  FROM t_host_wms_inventory_adjust h_adj
				  GROUP BY h_adj.location,h_adj.item_number,h_adj.lot_number
				 ) AS host_adj
			LEFT JOIN (SELECT store.location, store.item_number, store.lot, COUNT(store.serial_number) AS quantity_store_adj
						FROM (SELECT tmp.location,tmp.item_number,tmp.lot,tmp.serial_number
								,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
							 FROM t_wms_store_item_status tmp
							 WHERE is_adjust = 'YES'
							 ) store
						 WHERE store.is_max = 1 
						 GROUP BY store.location,store.item_number,store.lot
						 ) store_adj ON store_adj.location = host_adj.location 
									 AND store_adj.item_number = host_adj.item_number
									 AND store_adj.lot = host_adj.lot_number
			) AS pending ON loc.location = pending.location 
							AND item.item_number = pending.item_number
							AND inv.lot_number = pending.lot_number
LEFT JOIN  (SELECT tCount.location_id
				,MAX(tCount.create_date) AS last_create_date
		    FROM ( SELECT recon.location_id
						,CONVERT(DATE,recon.create_date) AS create_date--MAX(create_date) AS last_create_date
					FROM t_wms_count_reconcile recon
					INNER JOIN t_wms_count_plan_detail det ON det.serial_number = recon.serial_number and det.count_master_id = recon.count_master_id
					UNION
					SELECT recon.location_id
						,CONVERT(DATE,recon.create_date) AS create_date--MAX(create_date) AS last_create_date
					FROM t_wms_count_reconcile_external recon
					INNER JOIN t_wms_count_plan_detail_external det ON det.serial_number = recon.serial_number and det.count_master_id = recon.count_master_id

				 ) tCount
			GROUP BY tCount.location_id
			) AS rec ON inv.location_id = rec.location_id

 

		

		


GO
/****** Object:  View [dbo].[v_wms_inventory_available_external]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_inventory_available_external]
AS
SELECT
 inv_sn.wh_master_id
 ,inv_sn.wh_id
,inv_sn.owner_id
,inv_sn.owner_code
,inv_sn.zone
,inv_sn.location_id
,inv_sn.location
,inv_sn.category_id
,inv_sn.cate_description
,inv_sn.wh_item_master_id
,inv_sn.item_master_id
,inv_sn.item_number
,inv_sn.[description]
,inv_sn.lot_number
,avaliable = inv_sn.count_used + inv_sn.count_missing + inv_sn.count_consignment + isnull(pending.count_pending,0)
,inv_sn.count_avaliable
,inv_sn.count_used
,inv_sn.count_missing
,inv_sn.count_consignment
,isnull(convert(decimal(9,0),pending.count_pending),0.0) count_pending 
,cus_user.[user_id]
,rec.last_create_date
FROM
(
	select  
	inv.wh_master_id,wh.wh_id
	,own.owner_id,own.owner_code
	,zone.zone
	,inv.location_id,loc.location
	,cate.category_id,cate.[description] as cate_description
	,inv.wh_item_master_id,item.item_master_id,item.item_number,item.[description]
	,invLot.lot_number
	,count(case when invstatus.inv_status = 'Available' then 1 else null end) count_avaliable
	,count(case when invstatus.inv_status = 'Used' then 1 else null end) count_used
	,count(case when invstatus.inv_status = 'Missing CSM' then 1 else null end) count_missing
	,count(case when invstatus.inv_status = 'Consignment' then 1 else null end) count_consignment
	from t_wms_inventory inv
	inner join dbo.t_wms_inventory_status as invstatus on inv.inventory_status_id = invstatus.inventory_status_id 

	left join t_wms_wh wh on wh.wh_master_id = inv.wh_master_id
	left join t_wms_owner own on own.owner_id = inv.owner_id
	left join t_wms_zone_location zLoc on zLoc.location_id = inv.location_id
	left join t_wms_zone zone on zone.zone_id = zLoc.zone_id
	left join t_wms_location loc on loc.location_id = inv.location_id
	left join t_wms_wh_item whItem on whItem.wh_item_master_id = inv.wh_item_master_id
	left join t_wms_item item on item.item_master_id = whItem.item_master_id
	left join t_wms_category cate on cate.category_id = item.category_id
	left join (SELECT inventory_id
					,attribute_group_id
					,attribute_value AS lot_number
			   FROM dbo.t_wms_inventory_attribute
			   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
			   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
	where loc.loc_type = 'STORE'
	group by inv.wh_master_id,wh.wh_id
	,own.owner_id,own.owner_code
	,zone.zone
	,inv.location_id,loc.location
	,cate.category_id,cate.[description]
	,inv.wh_item_master_id,item.item_master_id,item.item_number,item.[description]
	,invLot.lot_number
)as inv_sn
inner join t_wms_customer_location loc_cus on inv_sn.location_id = loc_cus.location_id
inner join t_wms_customer_user cus_user on loc_cus.customer_id = cus_user.customer_id
inner join t_wms_customer cus on loc_cus.customer_id = cus.customer_id


LEFT JOIN (
	SELECT
	host_adj.location,host_adj.item_number,host_adj.lot_number
	,host_adj.quantity_host_adj,store_adj.quantity_store_adj
	,((isnull(host_adj.quantity_host_adj,0) - isnull(store_adj.quantity_store_adj,0))) * -1 count_pending
	FROM
	(
		select 
		h_adj.location,h_adj.item_number,h_adj.lot_number,sum(h_adj.quantity) quantity_host_adj
		from t_host_wms_inventory_adjust h_adj
		group by h_adj.location,h_adj.item_number,h_adj.lot_number
	) host_adj
	LEFT JOIN (
		select 
		store.location,store.item_number,store.lot
		,count(store.serial_number) quantity_store_adj
		from
		(
			select 
			tmp.location,tmp.item_number,tmp.lot,tmp.serial_number,tmp.is_adjust 
			,row_number() over(partition by serial_number order by create_date desc) as is_max
			from t_wms_store_item_status tmp
		) store
		where store.is_max = 1 and is_adjust = 'YES'
		group by store.location,store.item_number,store.lot
	) store_adj on store_adj.location = host_adj.location 
	and store_adj.item_number = host_adj.item_number
	and store_adj.lot = host_adj.lot_number
) as pending 
ON inv_sn.location = pending.location 
and inv_sn.item_number = pending.item_number
and inv_sn.lot_number = pending.lot_number

LEFT JOIN (
			select recon.location_id,max(recon.create_date) last_create_date
			from t_wms_count_reconcile_external recon
			INNER JOIN t_wms_count_plan_detail_external det ON det.serial_number = recon.serial_number and det.count_master_id = recon.count_master_id
			group by recon.location_id
) as rec 
ON inv_sn.location_id = rec.location_id 






GO
