/****** Object:  View [dbo].[v_wms_inventory_bom_remain]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 

CREATE VIEW [dbo].[v_wms_inventory_bom_remain]
AS

SELECT wh.wh_master_id
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, wh.wh_name
	, own.owner_name
	, uom.item_master_id
	, item.item_number
	, item.[description]
	, (isnull(invBom.quantity_receive,0) - isnull(invBom.quantity_ship,0)) as bom_qty
	, uom.uom
	, uom.uom_prompt
FROM   t_wms_inventory_bom  invBom
INNER JOIN t_wms_wh wh ON invBom.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_owner own ON invBom.owner_id = own.owner_id 
INNER JOIN t_wms_item item ON invBom.bom_item_master_id = item.item_master_id 
INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id
WHERE uom.primary_uom='YES'


GO
/****** Object:  View [dbo].[v_wms_inventory_data_by_aging]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
