/****** Object:  View [dbo].[v_wms_report_outbound_picking_list]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_outbound_picking_list]
AS
--====================================================================================================
--	DATE		Modyfy	Description
--	2020-10-08	NUI		Create New View
--====================================================================================================
SELECT wh.wh_id
	 , wh.wh_name
	 , CONVERT(VARCHAR(36),obMS.outbound_order_master_id) AS outbound_order_master_id
	 , obMS.outbound_order_number
	 , obMS.customer_order_number
	 , obMS.customer_purchase_order
	 , NULL sale_order_number
	 , obMS.order_type
	 , obMS.order_date
	 , obMS.ship_date_plan
	 , obMS.ship_date_actual
	 , obMS.create_date
	 , cus.customer_code
	 , cus.customer_name
	 , com.[SECTORS/USERS] AS comment
	 --detail
	 , loc.location
	 , itm.item_number
	 , itm.description AS item_description
	 , uom.uom_prompt
	 , pickDT.lpn
	 , pickDT.lot_number
	 , CAST(pickDT.expiry_date AS DATETIME) expiry_date
	 , ISNULL(SUM(pickDT.quantity_plan), obDT.quantity_order) quantity_order
	 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
INNER JOIN t_wms_item itm
INNER JOIN t_wms_wh_item whitm ON itm.item_master_id = whitm.item_master_id
							   ON pickDT.wh_item_master_id = whitm.wh_item_master_id
INNER JOIN t_wms_item_uom uom ON itm.item_master_id = uom.item_master_id AND obDT.item_uom_id = uom.item_uom_id
LEFT JOIN v_wms_single_comment_for_outbound_report com ON obMS.outbound_order_master_id = com.outbound_order_master_id
LEFT JOIN t_wms_customer cus ON obMS.customer_id = cus.customer_id
GROUP BY wh.wh_id
	 , wh.wh_name
	 , obMS.outbound_order_master_id
	 , obMS.outbound_order_number
	 , obMS.customer_order_number
	 , obMS.customer_purchase_order
	 , obMS.order_type
	 , obMS.order_date
	 , obMS.ship_date_plan
	 , obMS.ship_date_actual
	 , obMS.create_date
	 , cus.customer_code
	 , cus.customer_name
	 , com.[SECTORS/USERS]
	 , loc.location
	 , itm.item_number
	 , itm.description
	 , uom.uom_prompt
	 , pickDT.lpn
	 , pickDT.lot_number
	 , pickDT.expiry_date
	 , obDT.quantity_order
GO
