CREATE VIEW [dbo].[v_wms_inventory_data_by_serial_web]
AS
SELECT 
	convert(varchar(50),inv.inventory_id) + '_' +invSN.serial_number as key_id
	, inv.inventory_id
	, inv.attribute_group_id
	, inv.inv_type
	, wh.wh_id
	, inv.wh_master_id
	, own.owner_id
	, own.owner_code
	, inv.location_id
	, inv.parent_lpn
	, inv.lpn
	, inv.wh_item_master_id
	, item.item_number
	, uom.uom_prompt 
	, ISNULL(invSN.quantity, inv.quantity) AS quantity
	, ISNULL(invSN.quantity_allocated,inv.quantity_allocated) AS quantity_allocated
	, ISNULL(invSN.quantity_incoming,inv.quantity_incoming) AS quantity_incoming
	, inv.receive_date
	, inv.mfg_date
	, invStatus.inv_status
	, inv.inventory_status_id
	, loc.location
	, loc.loc_type
	, loc.pick_sequence
	, loc.pick_area_id
	, item.[description]
	, z.zone
	, uom.uom
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, CONVERT(nvarchar(15), inv.receive_date, 112) AS receive_date_filter
	, item.dg_code
	, item.grade
	, item.price
	, item.cost
	, CAST(0 AS bit) AS Checked
	, CAST(0 AS decimal(18, 3)) AS adjust_qty
	, item.item_master_id
	, loc.lpn_controlled
	, invSN.serial_number
	, invLot.lot_number
	, invExp.expiry_date
	, convert(datetime,invExp.expiry_date , 112) as exp_date
	, invAttribute1.attribute1
	, invAttribute2.attribute2
	, invAttribute3.attribute3
	, invAttribute4.attribute4
	, invAttribute5.attribute5
	, invExp.days_to_expire
	, inv.create_by
	, inv.create_date
	, NULL AS delivery_date
	, NULL AS delivery_number
FROM dbo.t_wms_inventory AS inv 
INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
INNER JOIN dbo.t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id
INNER JOIN dbo.t_wms_owner own ON inv.owner_id = own.owner_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id AND inv.wh_master_id = whItem.wh_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
INNER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id
INNER JOIN dbo.t_wms_category AS cate ON item.category_id = cate.category_id 
INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT JOIN dbo.t_wms_zone_location zLoc ON loc.location_id = zLoc.location_id
LEFT JOIN dbo.t_wms_zone z ON zLoc.zone_id = z.zone_id
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS lot_number
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
		   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS expiry_date
				,DATEDIFF(dd,GETDATE(),CONVERT(date,attribute_value,112)) as days_to_expire
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248'
		   ) AS invExp ON (inv.inventory_id = invExp.inventory_id) AND (inv.attribute_group_id = invExp.attribute_group_id) 
INNER JOIN (SELECT  inventory_id
				,attribute_group_id
				,attribute_value AS serial_number
				,quantity
				,quantity_allocated
				,quantity_incoming
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
		   ) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
