CREATE VIEW [dbo].[v_wms_inventory_empty]
AS
SELECT wh.wh_master_id
,wh.wh_id
,own.owner_id
,own.owner_code
,item.item_master_id
,item.item_number
,item.[description]
,qty = 0
,uom.item_uom_id
,uom.uom
,cate.category_id
,cate.item_category
,item.is_active
,item.create_by
,item.create_date
,item.update_by
,item.update_date
FROM t_wms_item item
INNER JOIN t_wms_wh_item whItem on whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_wh wh on wh.wh_master_id = whItem.wh_master_id
INNER JOIN t_wms_owner own on own.owner_id = item.owner_id 
INNER JOIN t_wms_item_uom uom on uom.item_master_id = item.item_master_id and uom.primary_uom = 'YES'
INNER JOIN t_wms_category cate on cate.category_id = item.category_id
WHERE whItem.wh_item_master_id NOT IN (SELECT wh_item_master_id FROM t_wms_inventory)
AND item.is_active = 'YES'




GO
