/****** Object:  View [dbo].[v_wms_load_master]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[v_wms_load_master]
AS
	select mas.load_master_id
		  ,mas.load_number,truck.truck_name as truck_no
		  ,detail.volumns,detail.weights,loc.location as dock_door,detail.orders,mas.load_status as [status]
		  ,mas.create_date,mas.create_by
	from t_wms_load_master mas
	left join t_wms_truck truck on mas.truck_id=truck.truck_id
	left join t_wms_location loc on mas.dock_door_id=loc.location_id
	cross apply (select ISNULL(SUM(det.volumn),0) as volumns, ISNULL(SUM(det.[weight]),0) as weights,COUNT(det.outbound_order_number) as orders 
				 from t_wms_load_detail det
				 where det.load_master_id=mas.load_master_id) as detail





