CREATE VIEW [dbo].[v_wms_manage_cover_sheet]
AS

select 
	wh.wh_name
	, (
		isnull(wh.addr_line_1,'') + ' ' +
		isnull(wh.addr_line_2,'') + ' ' +
		isnull(wh.addr_line_3,'') + ' ' +
		isnull(wh.city,'') + ' ' +
		isnull(wh.province,'') + ' ' +
		isnull(wh.postal_code,'') 
	) as wh_address
	, t_grouping.grouping_no
	, t_grouping.create_date
	, t_o_master.outbound_order_number
	, t_o_master.customer_name
	, t_o_master.order_date
	, t_o_master.delivery_date_plan
	, R1_t_o_detail.quantity_ship
from [dbo].[t_wms_outbound_grouping] t_grouping
left join [dbo].[t_wms_outbound_master] t_o_master on t_grouping.grouping_no = t_o_master.grouping_no
left join [dbo].[t_wms_wh] wh on t_grouping.wh_master_id = wh.wh_master_id
left join ( select t_o_detail.outbound_order_master_id as R1_t_o_detail_outbound_order_master_id, sum(t_o_detail.quantity_ship)as quantity_ship
			from [dbo].[t_wms_outbound_detail] t_o_detail
			group by t_o_detail.outbound_order_master_id
			)R1_t_o_detail on R1_t_o_detail.R1_t_o_detail_outbound_order_master_id = t_o_master.outbound_order_master_id



