/****** Object:  View [dbo].[v_wms_report_inbound_order_detail]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_inbound_order_detail]
AS
--====================================================================================================
-- 2020-09-30	NUI		Create new view (old view: v_wms_inbound_detail_report)
--====================================================================================================
	SELECT own.owner_id, own.owner_code, own.owner_name
		 , wh.wh_master_id, wh.wh_id, wh.wh_name
		 , own.description owner_description
		 , cus.customer_id, customer_code, cus.customer_name, cus.description customer_description
		 , sup.supplier_id, sup.supplier_code, sup.supplier_name, sup.description supplier_description
		 , ibMS.inbound_order_master_id, ibMS.inbound_order_number
		 , ibMS.order_type, ibMS.order_status, ibMS.description order_description
		 , ibMS.expected_delivery_date, ibMS.posting_date
		 , ibMS.close_date, ibMS.close_by, ibMS.close_remark
		 , ibMS.reference_number
		 , ibMS.copy_no
		 , ibMS.bom_inbound_order_master_id
		 , ibMs.user_def1, ibMS.user_def2, ibMS.user_def3, ibMS.user_def4, ibMS.user_def5, ibMS.user_def6, ibMS.user_def7, ibMS.user_def8, ibMS.user_def9, ibMS.user_def10
		 , ibMS.create_by, ibMS.create_date
		 , ibMS.update_by, ibMs.update_date
		 , cate.category_id, cate.item_category, cate.description category_description
		 , ibDT.line_number
		 , itm.item_master_id, itm.item_number, itm.description item_description
		 , uom.item_uom_id, uom.uom, uom.uom_prompt, uom.conversion_factor
		 , ISNULL(ibDT.quantity_order,0)  AS quantity_order
		 , ISNULL(ibDT.quantity_receive,0) AS quantity_receive
		 , ISNULL(ibDT.quantity_order,0) - ISNULL(ibDT.quantity_receive,0) AS quantity_remain
	FROM t_wms_inbound_master ibMs
	INNER JOIN t_wms_inbound_detail ibDT on ibMs.inbound_order_master_id = ibDT.inbound_order_master_id
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	INNER JOIN t_wms_wh wh ON ibMs.wh_master_id = wh.wh_master_id
	INNER JOIN t_wms_wh_item whItem on ibDT.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item itm on whItem.item_master_id = itm.item_master_id
	INNER JOIN t_wms_item_uom uom ON itm.item_master_id = uom.item_master_id AND ibDT.item_uom_id = uom.item_uom_id
	INNER JOIN t_wms_category cate ON itm.category_id = cate.category_id
	LEFT JOIN t_wms_customer cus on ibMs.customer_id = cus.customer_id
	LEFT JOIN t_wms_supplier sup on ibMs.supplier_id = sup.supplier_id
GO
