/****** Object:  View [dbo].[v_wms_report_inbond_order_receiving_discrepancy_sku]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_inbond_order_receiving_discrepancy_sku]
AS
--====================================================================================================
-- 2020-09-30	NUI		Create new view
--====================================================================================================
	WITH receipt AS
	(
		SELECT rcpt.inbound_order_master_id
			 , rcpt.inbound_order_detail_id
			 , rcpt.wh_item_master_id
			 , SUM(rcpt.quantity_received) quantity_received
		FROM t_wms_receipt_detail rcpt
		GROUP BY rcpt.inbound_order_master_id
			 , rcpt.inbound_order_detail_id
			 , rcpt.wh_item_master_id
	)

	SELECT wh.wh_id
		 , wh.wh_name
		 , CONVERT(VARCHAR(36), ibMS.inbound_order_master_id) AS inbound_order_master_id
		 , ibMS.inbound_order_number
		 , ibMS.order_type
		 , ibMS.order_status
		 , ibMS.create_date
		 , cus.customer_code
		 , cus.customer_name
		 , ibDT.line_number
		 , item.item_number
		 , item.description
		 , uom.uom
		 , ibDT.lot_number
		 , ibDT.quantity_order
		 , ISNULL(rcpt.quantity_received, 0) quantity_received
		 , (ibDT.quantity_order - ISNULL(rcpt.quantity_received, 0)) quantity_diff
		 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
	FROM dbo.t_wms_inbound_master ibMS
	INNER JOIN dbo.t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	LEFT JOIN receipt rcpt ON ibDT.inbound_order_master_id = rcpt.inbound_order_master_id  
						  AND ibDT.inbound_order_detail_id = rcpt.inbound_order_detail_id 
						  AND ibDT.wh_item_master_id = rcpt.wh_item_master_id 
	INNER JOIN dbo.t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id
	INNER JOIN dbo.t_wms_item item ON ibDT.item_master_id = item.item_master_id
	INNER JOIN dbo.t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
	LEFT JOIN dbo.t_wms_customer cus ON ibMS.customer_id = cus.customer_id
	WHERE (ISNULL(ibDT.quantity_order,0) - ISNULL(rcpt.quantity_received,0)) > 0

GO
/****** Object:  View [dbo].[v_wms_outbound_all_pack_detail]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_outbound_all_pack_detail]
AS
SELECT obMS.wh_master_id  
	, wh.wh_id
	, obMS.outbound_order_master_id
	, obMS.outbound_order_number
	, obMS.order_status
	, obMS.load_id
	, obMS.owner_id
	, obMS.customer_code
	, pickDT.outbound_order_detail_id
	, pickDT.outbound_pick_master_id
	, packDT.outbound_pick_detail_id
	, packDT.outbound_pack_detail_id
	, obDT.line_number
	, obDT.default_item_status
	, packDT.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description
	, packDT.item_uom_id
	, itemUom.uom_prompt
	, obDT.price

	--Plan Pick
	, pickDT.location_id
	, loc.location
	, pickDT.parent_lpn
	, pickDT.lpn

	--Pack
	, packDT.pack_location_id
	, packLoc.location AS pack_location
	, packDT.parent_lpn_pack
	, packDT.lpn_pack

	--QTY
	, obDT.quantity_order
	, pickDT.quantity_plan
	, pickDT.quantity_pick
	, packDT.quantity_pack
	, packDT.quantity_stage
	, packDT.quantity_load

	, packDT.lot_number
	, packDT.expiry_date
	, packDT.serial_number

	--STG
	, packDT.staging_location_id
	, stgLoc.location AS staging_location
	, packDT.staging_parent_lpn
	, packDT.staging_lpn
	--Dock Door
	, packDT.dock_door_id
	, packDT.dock_door_parent_lpn
	, packDT.dock_door_lpn
	, packDT.load_status
	, pickDT.is_override
FROM dbo.t_wms_outbound_master AS obMS
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN dbo.t_wms_outbound_pick_detail AS pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id 
INNER JOIN dbo.t_wms_outbound_pack_detail AS packDT ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id 
INNER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON whItem.wh_item_master_id = packDT.wh_item_master_id
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS itemUom ON packDT.item_uom_id = itemUom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_location AS Loc ON pickDT.location_id = Loc.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS packLoc ON packDT.pack_location_id = packLoc.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS stgLoc ON packDT.staging_location_id = stgLoc.location_id



GO
/****** Object:  View [dbo].[v_wms_report_inbound_order_receipt]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_inbound_order_receipt]
AS
--====================================================================================================
-- 2020-09-30	NUI		Create new view
--====================================================================================================
	SELECT CONVERT(VARCHAR(36), wh.wh_master_id) AS wh_master_id
		 , wh.wh_id
		 , wh.wh_name
		 , CONVERT(VARCHAR(36), ibMS.inbound_order_master_id) AS inbound_order_master_id
		 , ibMS.inbound_order_number
		 , ibMS.order_type
		 , ibMS.order_status
		 , ibDT.line_number
		 , item.item_number
		 , item.description
		 , uom.uom	 
		 , ibDT.quantity_order	  
		 , recDT.lot_number
		 , CONVERT(DATETIME,recDT.expiry_date) expiry_date
		 , recDT.serial_number
		 , recDT.quantity_received	
		 , recDT.create_by
		 , recDT.create_date
	FROM dbo.t_wms_inbound_master ibMS
	INNER JOIN dbo.t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	INNER JOIN dbo.t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id
	INNER JOIN dbo.t_wms_wh_item whItem  ON ibDT.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN dbo.t_wms_item item ON whItem.item_master_id = item.item_master_id
	INNER JOIN dbo.t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
	INNER JOIN dbo.t_wms_receipt_detail recDT ON ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
											 

