/****** Object:  View [dbo].[v_wms_outbound_for_receipt_return]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_outbound_for_receipt_return]
AS
WITH tOutbound AS
(
	SELECT obMS.outbound_order_master_id
		,obMS.outbound_order_number
		,pickDT.outbound_pick_master_id 
		,pickDT.wh_item_master_id
		,ISNULL(pickDT.lot_number,'')  AS lot_number
		,ISNULL(pickDT.expiry_date,'') AS expiry_date
		,ISNULL(pickDT.attribute1,'')  AS attribute1
		,ISNULL(pickDT.attribute2,'')  AS attribute2
		,ISNULL(pickDT.attribute3,'')  AS attribute3
		,ISNULL(pickDT.attribute4,'')  AS attribute4
		,ISNULL(pickDT.attribute5,'')  AS attribute5
		,ISNULL(pickDT.serial_number,'') AS serial_number
		,pickDT.receive_date
		,pickDT.mfg_date
		,SUM(ISNULL(pickDT.quantity_ship,0)) AS quantity_ship
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
	WHERE ISNULL(quantity_ship,0) > 0
	GROUP BY obMS.outbound_order_master_id,obMS.outbound_order_number,pickDT.outbound_pick_master_id ,pickDT.wh_item_master_id,ISNULL(pickDT.lot_number,''),ISNULL(pickDT.expiry_date,'')
	,ISNULL(pickDT.attribute1,''),ISNULL(pickDT.attribute2,''),ISNULL(pickDT.attribute3,''),ISNULL(pickDT.attribute4,''),ISNULL(pickDT.attribute5,''),ISNULL(pickDT.serial_number,''),pickDT.receive_date,pickDT.mfg_date
)
, tReturn AS
(
	SELECT ibMS.inbound_order_master_id 
		, ibMS.inbound_order_number
		, ibMS.reference_number 
		, ibDT.wh_item_master_id
		, ISNULL(recDT.lot_number,'')  AS lot_number
		, ISNULL(recDT.expiry_date,'') AS expiry_date
		, ISNULL(recDT.attribute1,'')  AS attribute1
		, ISNULL(recDT.attribute2,'')  AS attribute2
		, ISNULL(recDT.attribute3,'')  AS attribute3
		, ISNULL(recDT.attribute4,'')  AS attribute4
		, ISNULL(recDT.attribute5,'')  AS attribute5
		, ISNULL(recDT.serial_number,'') AS serial_number
		, recDT.receive_date
		,SUM(ISNULL(recDT.quantity_received,0)) AS quantity_received
	FROM t_wms_inbound_master ibMS
	INNER JOIN t_wms_inbound_detail ibDT on ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	LEFT JOIN t_wms_receipt_detail recDT ON recDT.inbound_order_detail_id = ibDT.inbound_order_detail_id
	WHERE ibMS.order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES')
	GROUP BY ibMS.inbound_order_master_id, ibMS.inbound_order_number, ibMS.reference_number, ibDT.wh_item_master_id, ISNULL(recDT.lot_number,''), ISNULL(recDT.expiry_date,'')
	, ISNULL(recDT.attribute1,''), ISNULL(recDT.attribute2,''), ISNULL(recDT.attribute3,''), ISNULL(recDT.attribute4,''), ISNULL(recDT.attribute5,''), ISNULL(recDT.serial_number,''),recDT.receive_date
)
SELECT distinct tReturn.inbound_order_master_id
	, tReturn.inbound_order_number 
	, tReturn.reference_number
	, tOutbound.wh_item_master_id
	, ISNULL(tOutbound.lot_number,'')  AS lot_number
	, ISNULL(tOutbound.expiry_date,'') AS expiry_date
	, ISNULL(tOutbound.attribute1,'')  AS attribute1
	, ISNULL(tOutbound.attribute2,'')  AS attribute2
	, ISNULL(tOutbound.attribute3,'')  AS attribute3
	, ISNULL(tOutbound.attribute4,'')  AS attribute4
	, ISNULL(tOutbound.attribute5,'')  AS attribute5
	, ISNULL(tOutbound.serial_number,'') AS serial_number
	, tOutbound.receive_date
	, tOutbound.mfg_date
	, ISNULL(tOutbound.quantity_ship,0) AS quantity_ship
 	, (SELECT SUM(ISNULL(tReturn.quantity_received,0)) FROM tReturn 
		WHERE tOutbound.outbound_order_number = tReturn.reference_number
		AND (CASE WHEN ISNULL(tReturn.lot_number,'') = '' THEN '' ELSE ISNULL(tOutbound.lot_number,'') END) = (CASE WHEN ISNULL(tReturn.lot_number,'') = '' THEN '' ELSE ISNULL(tReturn.lot_number,'') END)
		AND (CASE WHEN ISNULL(tReturn.expiry_date,'') = '' THEN '' ELSE ISNULL(tOutbound.expiry_date,'') END) = (CASE WHEN ISNULL(tReturn.expiry_date,'') = '' THEN '' ELSE ISNULL(tReturn.expiry_date,'') END)
		AND (CASE WHEN ISNULL(tReturn.attribute1,'') = '' THEN '' ELSE ISNULL(tOutbound.attribute1,'') END) = (CASE WHEN ISNULL(tReturn.attribute1,'') = '' THEN '' ELSE ISNULL(tReturn.attribute1,'') END)
		AND (CASE WHEN ISNULL(tReturn.attribute2,'') = '' THEN '' ELSE ISNULL(tOutbound.attribute2,'') END) = (CASE WHEN ISNULL(tReturn.attribute2,'') = '' THEN '' ELSE ISNULL(tReturn.attribute2,'') END)
		AND (CASE WHEN ISNULL(tReturn.attribute3,'') = '' THEN '' ELSE ISNULL(tOutbound.attribute3,'') END) = (CASE WHEN ISNULL(tReturn.attribute3,'') = '' THEN '' ELSE ISNULL(tReturn.attribute3,'') END)
		AND (CASE WHEN ISNULL(tReturn.attribute4,'') = '' THEN '' ELSE ISNULL(tOutbound.attribute4,'') END) = (CASE WHEN ISNULL(tReturn.attribute4,'') = '' THEN '' ELSE ISNULL(tReturn.attribute4,'') END)
		AND (CASE WHEN ISNULL(tReturn.attribute5,'') = '' THEN '' ELSE ISNULL(tOutbound.attribute5,'') END) = (CASE WHEN ISNULL(tReturn.attribute5,'') = '' THEN '' ELSE ISNULL(tReturn.attribute5,'') END)
		AND (CASE WHEN ISNULL(tReturn.receive_date,'') = '' THEN '' ELSE ISNULL(tOutbound.receive_date,'') END) = (CASE WHEN ISNULL(tReturn.receive_date,'') = '' THEN '' ELSE ISNULL(tReturn.receive_date,'') END)
	   ) quantity_received
FROM tReturn
LEFT JOIN tOutbound ON tOutbound.outbound_order_number = tReturn.reference_number
					AND tOutbound.wh_item_master_id = tReturn.wh_item_master_id 
GO
