CREATE VIEW [dbo].[v_wms_outbound_checker_rfid]
AS
SELECT obMS.outbound_order_master_id
	,pickDT.wh_item_master_id
	,item.item_number	
	,item.description
	,chk.serial_number
	,chk.processing_status
FROM t_wms_outbound_master obMS
LEFT JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
INNER JOIN t_wms_outbound_checker_rfid chk ON obMS.outbound_order_master_id = chk.outbound_order_master_id 
											AND chk.serial_number = pickDT.serial_number
LEFT JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id

