/****** Object:  View [dbo].[v_wms_report_inbond_order_sku]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_inbond_order_sku]
AS
--====================================================================================================
-- 2020-09-30	NUI		Create new view
--====================================================================================================
	WITH receipt AS
	(
		SELECT rcpt.inbound_order_master_id
			 , rcpt.inbound_order_detail_id
			 , rcpt.wh_item_master_id
			 , SUM(rcpt.quantity_received) quantity_received
		FROM t_wms_receipt_detail rcpt 
		GROUP BY rcpt.inbound_order_master_id
			 , rcpt.inbound_order_detail_id
			 , rcpt.wh_item_master_id 
	)
	SELECT wh.wh_id
		 , wh.wh_name
		 , CONVERT(VARCHAR(36), ibMS.inbound_order_master_id) AS inbound_order_master_id
		 , ibMS.inbound_order_number
		 , ibMS.order_type
		 , ibMS.order_status
		 , ibMS.create_date
		 , cus.customer_code
		 , cus.customer_name
		 , ibDT.line_number
		 , item.item_number
		 , item.description
		 , uom.uom
		 , ibDT.lot_number
		 , ibDT.quantity_order
		 , ISNULL(rcpt.quantity_received, 0) quantity_received
		 , (ibDT.quantity_order - ISNULL(rcpt.quantity_received, 0)) quantity_diff
		 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
	FROM dbo.t_wms_inbound_master ibMS
	INNER JOIN dbo.t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	LEFT JOIN receipt rcpt ON ibDT.inbound_order_master_id = rcpt.inbound_order_master_id  
						  AND ibDT.inbound_order_detail_id = rcpt.inbound_order_detail_id 
						  AND ibDT.wh_item_master_id = rcpt.wh_item_master_id
	INNER JOIN dbo.t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id
	INNER JOIN dbo.t_wms_item item ON ibDT.item_master_id = item.item_master_id
	INNER JOIN dbo.t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
	LEFT JOIN dbo.t_wms_customer cus ON ibMS.customer_id = cus.customer_id

GO
