CREATE VIEW [dbo].[v_wms_outbound_manifest_truck_group]
AS
     SELECT dbo.t_wms_outbound_manifest_tsp_truck.tsp_manifest_id
		  , convert(varchar(36),dbo.t_wms_outbound_manifest_tsp_truck.tsp_manifest_id) as str_tsp_manifest_id
          , dbo.t_wms_outbound_manifest_tsp_truck.manifest_code
          , CONVERT(DATE, dbo.t_wms_outbound_manifest_tsp_truck.create_date) AS truck_create_date
          , dbo.t_wms_carrier.carrier_code
          , dbo.t_wms_carrier.carrier_name
          , dbo.t_wms_truck_type.truck_type
          , dbo.t_wms_truck.truck_id
		  , CONVERT(varchar(36),dbo.t_wms_truck.truck_id) as str_truck_id
          , dbo.t_wms_truck.license_plate
          , dbo.t_wms_truck.driver_name1
          , dbo.t_wms_outbound_manifest_tsp_truck.volume_total
          , dbo.t_wms_customer.customer_id
          , dbo.t_wms_customer.customer_code
          , dbo.t_wms_customer.customer_name
          , dbo.t_wms_outbound_master.outbound_order_master_id
          , dbo.t_wms_outbound_master.outbound_order_number
          , dbo.t_wms_outbound_manifest_tsp_order_de.line_number
          , dbo.t_wms_outbound_manifest_tsp_order_de.item_master_id
          , dbo.t_wms_outbound_manifest_tsp_order_de.item_number
          , dbo.t_wms_item.[description] AS item_description
          , dbo.t_wms_outbound_manifest_tsp_order_de.item_quantity
		  , dbo.t_wms_outbound_manifest_tsp_truck.create_date
     FROM dbo.t_wms_customer
          INNER JOIN dbo.t_wms_outbound_master ON dbo.t_wms_customer.customer_id = dbo.t_wms_outbound_master.customer_id
          INNER JOIN dbo.t_wms_outbound_manifest_tsp_truck
          INNER JOIN dbo.t_wms_truck ON dbo.t_wms_outbound_manifest_tsp_truck.truck_id = dbo.t_wms_truck.truck_id
          INNER JOIN dbo.t_wms_carrier ON dbo.t_wms_truck.carrier_id = dbo.t_wms_carrier.carrier_id
          INNER JOIN dbo.t_wms_truck_type ON dbo.t_wms_truck.truck_type_id = dbo.t_wms_truck_type.truck_type_id
          INNER JOIN dbo.t_wms_outbound_manifest_tsp_order_de ON dbo.t_wms_outbound_manifest_tsp_truck.tsp_truck_id = dbo.t_wms_outbound_manifest_tsp_order_de.tsp_truck_id ON dbo.t_wms_outbound_master.outbound_order_master_id = dbo.t_wms_outbound_manifest_tsp_order_de.outbound_order_master_id
          INNER JOIN dbo.t_wms_item ON dbo.t_wms_outbound_manifest_tsp_order_de.item_master_id = dbo.t_wms_item.item_master_id;
