CREATE VIEW [dbo].[v_wms_outbound_order_shipment_report]
AS

WITH bom_item_mother_cte (mather_item_master_id, mather_item_number, mather_description)  
AS  
(  
	select mather_bom.item_master_id as mather_item_master_id
		, mather_bom.item_number as mather_item_number
		, mather_bom.[description] as mather_description
	from t_wms_item mather_bom 
	where mather_bom.is_bom = 'YES'	
)
, bom_qty_son_cte (bom_id, total_bom_son, mather_uom)  
AS  
(  
	select  item_bom_detail.bom_id
		, sum(item_bom_detail.quantity) as total_bom_son 
		, max(item_bom.uom) as mather_uom
	from t_wms_item_bom_detail item_bom_detail
	left join t_wms_item_bom item_bom on item_bom.bom_id = item_bom_detail.bom_id
	group by item_bom_detail.bom_id
)	

SELECT obMS.outbound_order_master_id
, CONVERT(varchar(36),obMS.outbound_order_master_id) AS str_outbound_order_master_id
, PickPack.outbound_order_detail_id
, PickPack.outbound_pick_master_id
, PickPack.outbound_pick_detail_id
, PickPack.outbound_pack_detail_id
, wh.wh_id
, obMS.outbound_order_number
, obMS.order_status
, obMS.load_id
, obMS.owner_id
, obDT.line_number
, PickPack.pick_line_number
, PickPack.wh_item_master_id
, item.item_number
, item.description
, obDT.item_uom_id
, itemUom.uom_prompt
, obDT.price
, obDT.quantity_order
, ISNULL(PickPack.quantity_plan, 0) AS quantity_plan
, ISNULL(PickPack.quantity_pick, 0) AS quantity_pick
, ISNULL(PickPack.quantity_pack, 0) AS quantity_pack
, ISNULL(PickPack.quantity_load, 0) AS quantity_load
, ISNULL(PickPack.quantity_stage, 0) AS quantity_stage
, ISNULL(PickPack.quantity_ship, 0) AS quantity_ship
, PickPack.pick_location_id
, packLoc.location AS pick_location
, PickPack.pick_to_parent_lpn
, PickPack.pick_to_lpn
, ISNULL(PickPack.lot_number, '') AS lot_number
, ISNULL(PickPack.expiry_date, '') AS expiry_date
, ISNULL(PickPack.serial_number, '') AS serial_number
, PickPack.staging_location_id
, stgLoc.location AS staging_location
, PickPack.staging_parent_lpn
, PickPack.staging_lpn, PickPack.dock_door_id
, PickPack.dock_door_parent_lpn
, PickPack.dock_door_lpn
, PickPack.pick_status
, PickPack.load_status
, obMS.order_type
, obMS.order_date
, obMS.loading_date_plan
, obMS.delivery_date_plan
, obMS.ship_date_plan
, obMS.loading_date_actual
, obMS.delivery_date_actual
, obMS.ship_date_actual
, obMS.truck_type_id
, truck.truck_type
, obMS.truck_no
, obMS.driver_name
, obMS.driver_license
, obMS.container_no
, obMS.seal_no
, obMS.tracking_number
, obMS.customer_code
, obMS.customer_name
, obMS.cus_description
, obMS.cus_addr_line_1
, obMS.cus_addr_line_2
, obMS.cus_addr_line_3
, obMS.cus_city
, obMS.cus_province
, obMS.cus_postal_code
, obMS.cus_country_code
, obMS.cus_country_name
, obMS.ship_to_code
, obMS.ship_to_name
, obMS.ship_to_description
, obMS.ship_to_addr_line_1
, obMS.ship_to_addr_line_2
, obMS.ship_to_addr_line_3
, obMS.ship_to_city
, obMS.ship_to_province
, obMS.ship_to_postal_code
, obMS.ship_to_country_code
, obMS.ship_to_country_name
, obMS.ship_to_contact
, obMS.ship_to_phone
, obMS.ship_to_fax
, obMS.ship_to_email
, dbo.t_wms_carrier.carrier_name
, obMS.cus_contact
, obMS.cus_phone
, obMS.cus_fax
, obMS.cus_email
, obDT.bom_id
, bom_item_mother_cte.mather_item_number
, bom_item_mother_cte.mather_description
, bom_qty_son_cte.total_bom_son
, bom_qty_son_cte.mather_uom
FROM dbo.t_wms_outbound_master AS obMS 
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN (SELECT pickDT.outbound_order_detail_id
				, pickDT.outbound_pick_master_id
				, pickDT.outbound_pick_detail_id
				, packDT.outbound_pack_detail_id
				, pickDT.pick_status
				, pickDT.pick_line_number
				, pickDT.wh_item_master_id
				, pickDT.quantity_plan
				, pickDT.quantity_pick
				, packDT.quantity_pack
				,  pickDT.quantity_load
				, pickDT.quantity_ship
				, (CASE WHEN ISNULL(packDT.quantity_stage, '') = '' THEN pickDT.quantity_stage ELSE packDT.quantity_stage END) AS quantity_stage
				, (CASE WHEN packDT.pack_location_id IS NULL THEN pickDT.pick_location_id ELSE packDT.pack_location_id END) AS pick_location_id
				, (CASE WHEN ISNULL(packDT.parent_lpn_pack, '') = '' THEN pickDT.pick_to_parent_lpn ELSE packDT.parent_lpn_pack END) AS pick_to_parent_lpn
				, (CASE WHEN ISNULL(packDT.lpn_pack, '') = '' THEN pickDT.pick_to_lpn ELSE packDT.lpn_pack END) AS pick_to_lpn
				, (CASE WHEN ISNULL(packDT.lot_number, '') = '' THEN pickDT.lot_number ELSE packDT.lot_number END) AS lot_number
				, (CASE WHEN ISNULL(packDT.expiry_date, '')= '' THEN pickDT.expiry_date ELSE packDT.expiry_date END) AS expiry_date
				, (CASE WHEN ISNULL(packDT.serial_number, '')= '' THEN pickDT.serial_number ELSE packDT.serial_number END) AS serial_number
				, (CASE WHEN packDT.staging_location_id IS NULL THEN pickDT.staging_location_id ELSE packDT.staging_location_id END) AS staging_location_id
				, (CASE WHEN ISNULL(packDT.staging_parent_lpn,'') = '' THEN pickDT.staging_parent_lpn ELSE packDT.staging_parent_lpn END) AS staging_parent_lpn
				, (CASE WHEN ISNULL(packDT.staging_lpn, '')  = '' THEN pickDT.staging_lpn ELSE packDT.staging_lpn END) AS staging_lpn
				, (CASE WHEN packDT.dock_door_id IS NULL THEN pickDT.dock_door_id ELSE packDT.dock_door_id END) AS dock_door_id
				, (CASE WHEN ISNULL(packDT.dock_door_parent_lpn, '') = '' THEN pickDT.dock_door_parent_lpn ELSE packDT.dock_door_parent_lpn END) AS dock_door_parent_lpn
				, (CASE WHEN ISNULL(packDT.dock_door_lpn, '') = '' THEN pickDT.dock_door_lpn ELSE packDT.dock_door_lpn END) AS dock_door_lpn
				, (CASE WHEN ISNULL(packDT.load_status, '') = '' THEN pickDT.load_status ELSE packDT.load_status END) AS load_status
			FROM dbo.t_wms_outbound_pick_detail AS pickDT 
			LEFT OUTER JOIN dbo.t_wms_outbound_pack_detail AS packDT ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id  AND  pickDT.wh_item_master_id = packDT.wh_item_master_id
			) AS PickPack ON  obDT.outbound_order_detail_id = PickPack.outbound_order_detail_id 
LEFT OUTER JOIN dbo.t_wms_carrier ON obMS.carrier_id = dbo.t_wms_carrier.carrier_id 
LEFT OUTER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id 
LEFT OUTER JOIN dbo.t_wms_wh_item AS whItem ON whItem.wh_item_master_id = PickPack.wh_item_master_id 
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS itemUom ON obDT.item_uom_id = itemUom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_location AS packLoc ON PickPack.pick_location_id = packLoc.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS stgLoc ON PickPack.staging_location_id = stgLoc.location_id
LEFT OUTER JOIN dbo.t_wms_truck_type truck ON obMS.truck_type_id = truck.truck_type_id
LEFT OUTER JOIN bom_item_mother_cte ON bom_item_mother_cte.mather_item_master_id = obDT.bom_item_master_id
LEFT OUTER JOIN bom_qty_son_cte ON bom_qty_son_cte.bom_id = obDT.bom_id


