CREATE VIEW [dbo].[v_wms_outbound_pack_detail]
AS
SELECT obMS.wh_master_id  
	, wh.wh_id
	, obMS.outbound_order_master_id
	, obMS.outbound_order_number
	, obMS.order_status
	, obMS.order_type
	, obMS.load_id
	, obMS.owner_id
	, obMS.customer_id
	, obMS.customer_code
	, pickDT.outbound_order_detail_id
	, pickDT.outbound_pick_master_id
	, packDT.outbound_pick_detail_id
	, obDT.line_number
	, obDT.default_item_status
	, packDT.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description
	, packDT.item_uom_id
	, itemUom.uom_prompt
	, itemUom.uom
	, obDT.price
	, packLoc.location AS pack_location
	, packDT.parent_lpn_pack
	, packDT.lpn_pack
	, obDT.quantity_order
	, pickDT.quantity_pick
	, packDT.quantity_pack
	, packDT.quantity_stage
	, packDT.quantity_load
	, pickDT.quantity_ship
	, pickDT.is_override
	, packDT.lot_number
	, packDT.expiry_date
	, packDT.attribute1
	, packDT.attribute2
	, packDT.attribute3
	, packDT.attribute4
	, packDT.attribute5
	, packDT.serial_number
	, packDT.pack_location_id
	, packDT.outbound_pack_detail_id
	, packDT.staging_location_id
	, packDT.staging_parent_lpn
	, packDT.staging_lpn
	, packDT.dock_door_id
	, packDT.dock_door_parent_lpn
	, packDT.dock_door_lpn
	, packDT.load_status
	, stgLoc.location AS staging_location
	, item.lot_control
	, item.expiry_date_control
	, item.sn_control
	, item.attribute1_control
	, item.attribute2_control
	, item.attribute3_control
	, item.attribute4_control
	, item.attribute5_control
	, pickDT.pick_line_number
	, pickDT.location_id
	, loc.location
	, loc.erp_location
	, pickDT.receive_date
	, pickDT.mfg_date
	, z.zone_id
    , z.zone
FROM dbo.t_wms_outbound_master AS obMS
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN dbo.t_wms_outbound_pick_detail AS pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id 
INNER JOIN dbo.t_wms_outbound_pack_detail AS packDT ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id 
INNER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON whItem.wh_item_master_id = packDT.wh_item_master_id
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS itemUom ON packDT.item_uom_id = itemUom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_location AS packLoc ON packDT.pack_location_id = packLoc.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS stgLoc ON packDT.staging_location_id = stgLoc.location_id
LEFT OUTER JOIN dbo.t_wms_location AS loc ON pickDT.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc ON loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id
 
