CREATE VIEW [dbo].[v_wms_outbound_pack_detail_report]
AS
SELECT        wh.wh_id, obMS.outbound_order_master_id, obMS.outbound_order_number, obMS.order_status, obMS.load_id, obMS.owner_id, obMS.customer_code, 
pickDT.outbound_order_detail_id, pickDT.outbound_pick_master_id, packDT.outbound_pick_detail_id, obDT.line_number, packDT.wh_item_master_id, 
item.item_number, item.description, packDT.item_uom_id, itemUom.uom_prompt, obDT.price, packLoc.location AS pack_location, packDT.parent_lpn_pack, 
packDT.lpn_pack, obDT.quantity_order, pickDT.quantity_pick, packDT.quantity_pack, pickDT.quantity_stage, pickDT.quantity_load, packDT.lot_number, 
packDT.expiry_date, packDT.serial_number, packDT.pack_location_id, packDT.outbound_pack_detail_id, packDT.staging_location_id, packDT.staging_parent_lpn, 
packDT.staging_lpn, packDT.dock_door_id, packDT.dock_door_parent_lpn, packDT.dock_door_lpn, packDT.load_status, stgLoc.location AS staging_location, 
obMS.delivery_date_plan, obMS.order_date, obMS.order_type, obMS.truck_type_id,truck.truck_type, obMS.truck_no, obMS.container_no, obMS.seal_no, obMS.customer_name, 
obMS.cus_addr_line_1, obMS.cus_addr_line_2, obMS.cus_addr_line_3, obMS.cus_city, obMS.cus_province, obMS.cus_postal_code, obMS.cus_country_code, 
obMS.cus_country_name, obMS.cus_contact, obMS.driver_name, obMS.driver_license, obMS.tracking_number, obMS.ship_to_name, obMS.ship_date_actual, 
obMS.delivery_date_actual, obMS.loading_date_actual, obMS.ship_date_plan, obMS.loading_date_plan
FROM  dbo.t_wms_outbound_master AS obMS 
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN dbo.t_wms_outbound_pick_detail AS pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id 
INNER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id 
RIGHT OUTER JOIN dbo.t_wms_wh_item AS whItem 
INNER JOIN dbo.t_wms_outbound_pack_detail AS packDT ON whItem.wh_item_master_id = packDT.wh_item_master_id 
				ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id 
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS itemUom ON packDT.item_uom_id = itemUom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_location AS packLoc ON packDT.pack_location_id = packLoc.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS stgLoc ON packDT.staging_location_id = stgLoc.location_id
LEFT OUTER JOIN dbo.t_wms_truck_type AS truck ON obMS.truck_type_id = truck.truck_type_id



