/****** Object:  View [dbo].[v_wms_outbound_performance]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO






CREATE VIEW [dbo].[v_wms_outbound_performance]
AS

SELECT
tmp.owner_id,tmp.owner_code
,tmp.customer_id,tmp.customer_code,tmp.customer_name
,tmp.max_create_date,tmp.min_ship_date_actual,tmp.count_outbound_order_number
,DATEDIFF(MINUTE,tmp.min_ship_date_actual,tmp.max_create_date) as diff_minute
FROM
(
select
t_wms_owner.owner_id,t_wms_owner.owner_code
,customer_id,customer_code,customer_name
,max(t_wms_outbound_master.create_date) as max_create_date,min(ship_date_actual) as min_ship_date_actual
,count(outbound_order_number) as count_outbound_order_number
from t_wms_outbound_master
inner join t_wms_owner on t_wms_owner.owner_id = t_wms_outbound_master.owner_id
where t_wms_outbound_master.order_status = 'SHIP'
group by t_wms_owner.owner_id,t_wms_owner.owner_code
,customer_id,customer_code,customer_name
) tmp




