SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE view [dbo].[v_wms_mapping_location_item] as

SELECT 
tmp.[location]+ '_' + tmp.item_number  as key_id
,tmp.item_master_id
,tmp.item_number
,tmp.description
,tmp.location
,tmp.location_id
,cast(case when loc_i.item_location_id is not null then 1 else 0 end as bit) as is_active
,loc_i.create_by
,loc_i.create_date
FROM
(
	select 
	itm.item_master_id
	,itm.item_number
	,itm.description
	,loc.location
	,loc.location_id
	from t_wms_location as loc,t_wms_item as itm
) as tmp
LEFT JOIN t_wms_location_item as loc_i on loc_i.location_id = tmp.location_id and loc_i.item_master_id = tmp.item_master_id
--ORDER BY tmp.item_master_id

	
