CREATE VIEW [dbo].[v_wms_outbound_performance_detail]
AS
 
 
SELECT
tmp.owner_id,tmp.owner_code
,tmp.customer_id,tmp.customer_code,tmp.customer_name,tmp.outbound_order_number
,tmp.create_date,tmp.ship_date_actual,tmp.count_item
,DATEDIFF(MINUTE,tmp.ship_date_actual,tmp.create_date) as diff_minute
FROM
(
select
t_wms_owner.owner_id,t_wms_owner.owner_code
,customer_id,customer_code,customer_name,outbound_order_number
,t_wms_outbound_master.create_date,ship_date_actual,count(t_wms_outbound_detail.wh_item_master_id) as count_item
from t_wms_outbound_master
inner join t_wms_owner on t_wms_owner.owner_id = t_wms_outbound_master.owner_id
inner join t_wms_outbound_detail on t_wms_outbound_master.outbound_order_master_id = t_wms_outbound_detail.outbound_order_master_id
where t_wms_outbound_master.order_status = 'SHIP'
group by 
t_wms_owner.owner_id,t_wms_owner.owner_code
,customer_id,customer_code,customer_name,outbound_order_number
,t_wms_outbound_master.create_date,ship_date_actual
