CREATE VIEW [dbo].[v_wms_outbound_pick_detail]
AS
SELECT        dbo.t_wms_outbound_pick_master.outbound_order_number, dbo.t_wms_wh.wh_id, dbo.t_wms_outbound_pick_detail.pick_generate_method, 
dbo.t_wms_outbound_pick_master.pick_list_number, t_wms_location_1.location, t_wms_location_2.location AS pick_location, dbo.t_wms_item.item_number, 
dbo.t_wms_outbound_pick_detail.quantity_plan, dbo.t_wms_outbound_pick_detail.quantity_pick, 
dbo.t_wms_outbound_pick_detail.quantity_plan - dbo.t_wms_outbound_pick_detail.quantity_pick AS quantity_remain_pick, 
dbo.t_wms_outbound_pick_detail.quantity_plan - dbo.t_wms_outbound_pick_detail.quantity_pick AS quantity_confirm_pick, 
dbo.t_wms_outbound_pick_detail.quantity_pick - dbo.t_wms_outbound_pick_detail.quantity_stage AS quantity_remain_to_stage, 
dbo.t_wms_outbound_pick_detail.quantity_stage, dbo.t_wms_outbound_pick_detail.quantity_pack, 
dbo.t_wms_outbound_pick_detail.quantity_stage - dbo.t_wms_outbound_pick_detail.quantity_pack AS quantity_remain_pack, 
dbo.t_wms_outbound_pick_detail.quantity_stage - dbo.t_wms_outbound_pick_detail.quantity_pack AS quantity_confirm_pack, 
dbo.t_wms_outbound_pick_detail.quantity_load, dbo.t_wms_outbound_pick_detail.quantity_ship, dbo.t_wms_outbound_pick_detail.lpn, 
dbo.t_wms_outbound_pick_detail.lot_number, dbo.t_wms_outbound_pick_detail.expiry_date, CONVERT(varchar(10), CONVERT(datetime, 
dbo.t_wms_outbound_pick_detail.expiry_date, 126), 103) AS expiry_date_show, dbo.t_wms_outbound_pick_detail.serial_number, 
dbo.t_wms_outbound_pick_detail.user_assign, dbo.t_wms_outbound_pick_detail.create_date, dbo.t_wms_outbound_pick_detail.create_by, 
dbo.t_wms_outbound_pick_detail.outbound_pick_detail_id, dbo.t_wms_outbound_pick_detail.outbound_pick_master_id, 
dbo.t_wms_outbound_pick_detail.outbound_order_detail_id, dbo.t_wms_outbound_pick_detail.location_id, dbo.t_wms_outbound_pick_detail.pick_location_id,
dbo.t_wms_outbound_pick_detail.wh_item_master_id, dbo.t_wms_outbound_pick_master.wh_master_id, t_wms_location_1.lpn_controlled, 
dbo.t_wms_outbound_pick_detail.is_active, dbo.t_wms_item.expiry_date_control, dbo.t_wms_item.sn_control, dbo.t_wms_item.lot_control, 
dbo.t_wms_outbound_pick_detail.short_pick_reason_id, t_wms_reason_1.reason_code AS short_pick_reason_code, 
dbo.t_wms_location.location AS staging_location, t_wms_reason_2.reason_code AS next_location_reason_code, 
dbo.t_wms_reason.reason_code AS over_pick_reason_code, dbo.t_wms_outbound_pick_detail.pick_status, dbo.t_wms_outbound_pick_detail.pack_status, 
dbo.t_wms_item.description, dbo.t_wms_outbound_detail.line_number, dbo.t_wms_item_uom.uom_prompt, dbo.t_wms_outbound_pick_detail.ship_status, 
dbo.t_wms_outbound_master.customer_code, dbo.t_wms_outbound_master.ship_date_plan, dbo.t_wms_outbound_pick_detail.staging_lpn, 
dbo.t_wms_outbound_master.order_type, dbo.t_wms_outbound_master.order_status, dbo.t_wms_outbound_detail.price, dbo.t_wms_outbound_detail.grade, 
dbo.t_wms_item.dg_code, dbo.t_wms_outbound_pick_master.outbound_order_master_id, dbo.t_wms_outbound_detail.default_item_status, 
dbo.t_wms_item_crossref.alternate_item_number, dbo.t_wms_outbound_pick_detail.is_allocate, dbo.t_wms_outbound_pick_detail.is_override, 
dbo.t_wms_outbound_pick_detail.pick_override_reason, NULL AS brand_name, ISNULL(dbo.t_wms_customer.customer_code, '') 
+ ' ' + ISNULL(dbo.t_wms_customer.customer_name, '') + ' ' + ISNULL(dbo.t_wms_customer.addr_line_1, '') + ' ' + ISNULL(dbo.t_wms_customer.addr_line_2, 
'') + ' ' + (CASE WHEN SUBSTRING(ISNULL(t_wms_customer.addr_line_3, ''), 1, 6) 
= 'Normal' THEN 'Normal' WHEN SUBSTRING(ISNULL(t_wms_customer.addr_line_3, ''), 1, 9) = 'Promotion' THEN 'Promotion' ELSE '' END) 
AS customer_code_name, dbo.t_wms_outbound_pick_detail.parent_lpn, dbo.t_wms_outbound_pick_detail.staging_parent_lpn, 
dbo.t_wms_outbound_pick_detail.dock_door_id, dbo.t_wms_outbound_pick_detail.dock_door_parent_lpn, dbo.t_wms_outbound_pick_detail.dock_door_lpn, 
dbo.t_wms_outbound_pick_detail.load_status, dbo.t_wms_outbound_pick_detail.staging_location_id, dbo.t_wms_outbound_pick_detail.pick_to_parent_lpn, 
dbo.t_wms_outbound_detail.item_uom_id, dbo.t_wms_outbound_pick_detail.inventory_id, dbo.t_wms_outbound_master.seal_no, 
dbo.t_wms_outbound_master.container_no, dbo.t_wms_carrier.carrier_name, dbo.t_wms_outbound_master.truck_type_id, dbo.t_wms_truck_type.truck_type,
dbo.t_wms_outbound_master.truck_no, dbo.t_wms_outbound_detail.quantity_order, dbo.t_wms_category.item_category, 
dbo.t_wms_outbound_master.load_id, dbo.t_wms_outbound_master.owner_id, dbo.t_wms_outbound_pick_detail.pick_to_lpn,
dbo.t_wms_outbound_pick_detail.attribute1,
dbo.t_wms_outbound_pick_detail.attribute2,
dbo.t_wms_outbound_pick_detail.attribute3,
dbo.t_wms_outbound_pick_detail.attribute4,
dbo.t_wms_outbound_pick_detail.attribute5,
dbo.t_wms_outbound_detail.uom,
dbo.t_wms_outbound_pick_detail.receive_date
FROM dbo.t_wms_outbound_pick_detail 
INNER JOIN dbo.t_wms_outbound_pick_master ON dbo.t_wms_outbound_pick_detail.outbound_pick_master_id = dbo.t_wms_outbound_pick_master.outbound_pick_master_id 
INNER JOIN dbo.t_wms_wh ON dbo.t_wms_outbound_pick_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
LEFT OUTER JOIN dbo.t_wms_wh_item ON dbo.t_wms_outbound_pick_detail.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
LEFT OUTER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
INNER JOIN dbo.t_wms_outbound_detail ON dbo.t_wms_outbound_pick_detail.outbound_order_detail_id = dbo.t_wms_outbound_detail.outbound_order_detail_id 
INNER JOIN dbo.t_wms_outbound_master ON dbo.t_wms_outbound_detail.outbound_order_master_id = dbo.t_wms_outbound_master.outbound_order_master_id 
INNER JOIN dbo.t_wms_category ON dbo.t_wms_item.category_id = dbo.t_wms_category.category_id 
LEFT OUTER JOIN dbo.t_wms_carrier ON dbo.t_wms_outbound_master.carrier_id = dbo.t_wms_carrier.carrier_id 
LEFT OUTER JOIN dbo.t_wms_item_uom ON dbo.t_wms_outbound_detail.item_uom_id = dbo.t_wms_item_uom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_item_crossref ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_crossref.item_master_id 
LEFT OUTER JOIN dbo.t_wms_location AS t_wms_location_1 ON dbo.t_wms_outbound_pick_detail.location_id = t_wms_location_1.location_id 
LEFT OUTER JOIN dbo.t_wms_location AS t_wms_location_2 ON dbo.t_wms_outbound_pick_detail.pick_location_id = t_wms_location_2.location_id 
LEFT OUTER JOIN dbo.t_wms_location ON dbo.t_wms_outbound_pick_detail.staging_location_id = dbo.t_wms_location.location_id 
LEFT OUTER JOIN dbo.t_wms_customer ON dbo.t_wms_outbound_master.customer_code = dbo.t_wms_customer.customer_code 
						AND dbo.t_wms_outbound_master.owner_id = dbo.t_wms_customer.owner_id 
LEFT OUTER JOIN dbo.t_wms_reason ON dbo.t_wms_outbound_pick_detail.over_pick_reason_id = dbo.t_wms_reason.reason_id 
LEFT OUTER JOIN dbo.t_wms_reason AS t_wms_reason_2 ON dbo.t_wms_outbound_pick_detail.next_location_reason_id = t_wms_reason_2.reason_id 
LEFT OUTER JOIN dbo.t_wms_reason AS t_wms_reason_1 ON dbo.t_wms_outbound_pick_detail.short_pick_reason_id = t_wms_reason_1.reason_id
LEFT OUTER JOIN dbo.t_wms_truck_type ON dbo.t_wms_outbound_master.truck_type_id = dbo.t_wms_truck_type.truck_type_id


GO
