SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_outbound_pick_detail_id]
AS
SELECT obMS.outbound_order_master_id
	, obMS.outbound_order_number
	, obMS.load_id
	, obMS.wh_master_id
	, obMS.owner_id
	, obMS.order_status
	, obDT.outbound_order_detail_id
	, pickMS.outbound_pick_master_id
	, pickDT.outbound_pick_detail_id
	, obDT.line_number
	, pickDT.wh_item_master_id
 	, obDT.default_item_status
 	, obDT.item_uom_id
 	, pickDT.parent_lpn
	, pickDT.lpn
	, pickDT.lot_number
	, pickDT.expiry_date
	, pickDT.attribute1
	, pickDT.attribute2
	, pickDT.attribute3
	, pickDT.attribute4
	, pickDT.attribute5
	, obDT.quantity_order
	, pickDT.quantity_plan
	, ISNULL(pickDT.quantity_pick,0) AS quantity_pick
	, ISNULL(pickDT.quantity_pick,0) AS sn_quantity	--มีการปรับไม่ต้องดึง qty_pick จาก table pick serial แล้วให้ดึงจาก pick dt ได้เลย
	, ISNULL(pickDT.quantity_stage,0) AS quantity_stage
	, ISNULL(pickDT.quantity_pack,0) AS quantity_pack
	, ISNULL(pickDT.quantity_load,0) AS quantity_load
	, ISNULL(pickDT.quantity_ship,0) AS quantity_ship	
	, pickDT.location_id
 	, pickDT.is_override
	, pickDT.serial_number
	, pickDT.pick_to_lpn
	, pickDT.pick_to_parent_lpn 
	, pickDT.pick_line_number
	, pickDT.load_status
	, pickDT.dock_door_id
	, pickDT.dock_door_lpn 
	, pickDT.staging_location_id
	, pickDT.staging_parent_lpn
	, pickDT.staging_lpn
	, pickDT.receive_date
	, pickDT.mfg_date
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
 






GO
/****** Object:  View [dbo].[v_wms_outbound_pick_detail_linenumber]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_outbound_pick_detail_linenumber]
AS

SELECT pick_master.outbound_order_master_id
	,pick.outbound_pick_detail_id
	,pick.is_override
	,loc.location
	,item.item_number
	,detail.item_description
	,cate.item_category
	,category_description = cate.[description]
	,uom.uom
	,detail.grade
	,detail.price
	,pick.quantity_plan
	,pick.quantity_pick
	,quantity_remain = (pick.quantity_plan - pick.quantity_pick)
	,pick.quantity_pack
	,pick.quantity_stage
	,pick.quantity_load
	,pick.quantity_comfirm_pick_pc
	,pick.parent_lpn
	,pick.lpn
	,pick.lot_number
	,pick.[expiry_date]
	,pick.attribute1
	,pick.attribute2
	,pick.attribute3
	,pick.attribute4
	,pick.attribute5
	,is_staging_location = case when pick.staging_location_id is null then CAST('FALSE' as bit) else CAST('TRUE' as bit) end
	,pick.pick_line_number
	,pick_line_number_int = CONVERT(int,detail.line_number)
	,detail.serial_number
	,pick.confirm_serial_number_pc
	,item.sn_control
FROM t_wms_outbound_pick_detail pick
INNER JOIN t_wms_outbound_pick_master pick_master on pick_master.outbound_pick_master_id = pick.outbound_pick_master_id
INNER JOIN t_wms_outbound_detail detail on detail.outbound_order_detail_id = pick.outbound_order_detail_id
INNER JOIN t_wms_wh_item wh_item ON wh_item.wh_item_master_id = detail.wh_item_master_id
INNER JOIN t_wms_item item ON item.item_master_id = wh_item.item_master_id
INNER JOIN t_wms_category cate ON cate.category_id = item.category_id
INNER JOIN t_wms_item_uom uom ON uom.item_uom_id = detail.item_uom_id
INNER JOIN t_wms_location loc ON loc.location_id = pick.location_id



GO
