	, item.sn_control
	, item.lot_control
	, item.expiry_date_control
	, item.attribute1_control
	, item.attribute2_control
	, item.attribute3_control
	, item.attribute4_control
	, item.attribute5_control
	, obDT.item_uom_id
	, uom.uom
	, uom.uom_prompt
	, uom.conversion_factor
	, pickDT.parent_lpn
	, pickDT.lpn
	, pickDT.lot_number
	, pickDT.expiry_date
	, pickDT.attribute1
	, pickDT.attribute2
	, pickDT.attribute3
	, pickDT.attribute4
	, pickDT.attribute5
	, obDT.quantity_order
	, pickDT.quantity_plan
	, ISNULL(pickDT.quantity_pick,0) AS quantity_pick
	, ISNULL(pickDT.quantity_pick,0) AS sn_quantity	--มีการปรับไม่ต้องดึง qty_pick จาก table pick serial แล้วให้ดึงจาก pick dt ได้เลย
	, ISNULL(pickDT.quantity_stage,0) AS quantity_stage
	, ISNULL(pickDT.quantity_load,0) AS quantity_load
