											AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
INNER JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN dbo.t_wms_item_uom AS uom ON obDT.item_uom_id = uom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_location AS loc ON pickDT.location_id = loc.location_id
LEFT OUTER JOIN dbo.t_wms_location AS locPick ON pickDT.pick_location_id = locPick.location_id









