/****** Object:  View [dbo].[v_wms_dashboard_trans_daily_status]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_dashboard_trans_daily_status]
AS

SELECT
wh_master_id
,wh_id
,owner_id
,owner_code
,inventory_status_id
,inv_status
,isnull(trans_date,getdate()) as trans_date
,sum(quantity) as quantity
FROM
(
	SELECT wh_master_id
		,wh_id
		,owner_id
		,owner_code
		,category_id
		,item_category
		,item_master_id
		,item_number
		,inventory_status_id
		,inv_status
		,quantity
		--,trans_type
		,Convert(datetime,format(trans_date ,'yyyy-MM-dd hh:00:00')) as trans_date
	FROM t_wms_dashboard_trans_in 
	WHERE CONVERT(DATE,trans_date) = CONVERT(DATE,getdate())
	--WHERE CONVERT(DATE,trans_date) = CONVERT(DATE,'2019-12-19')
	UNION ALL
	SELECT wh_master_id
		,wh_id
		,owner_id
		,owner_code
		,category_id
		,item_category
		,item_master_id
		,item_number
		,inventory_status_id
		,inv_status
		,quantity
		--,trans_type
		,Convert(datetime,format(trans_date ,'yyyy-MM-dd hh:00:00')) as trans_date
	FROM t_wms_dashboard_trans_out
	WHERE CONVERT(DATE,trans_date) = CONVERT(DATE,getdate())
	--WHERE CONVERT(DATE,trans_date) = CONVERT(DATE,'2019-12-19')
) as tmp
GROUP BY
wh_master_id
,wh_id
,owner_id
,owner_code
,inventory_status_id
,inv_status
,trans_date

