/****** Object:  View [dbo].[v_wms_count_reconcile_merge_external]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_count_reconcile_merge_external]
AS
SELECT planMS.count_master_id
	--, planDT.count_plan_detail_id
	, planMS.count_id
	, planMS.wh_master_id
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, item.item_number
	, item.description
	, item.dg_code
	, item.price
	, item.grade
	, planDT.lpn
	, planDT.lot_number
	, planDT.expiry_date
	, planDT.serial_number
	, planDT.location_id
	, planDT.inv_status
	, planDT.parent_lpn
	, ISNULL(planDT.stock_qty, 0) AS stock_qty
	, ISNULL(planDT.count_qty, 0) AS count_qty
	, ISNULL(planDT.count_qty, 0) - ISNULL(planDT.stock_qty, 0) AS diff_qty
	, uom.uom_prompt
	, loc.location
	--, loc.location_id
	, z.zone
	--, z.zone_id
	,category.category_id
	,category.item_category
	,category.[description] as cate_description
	,planDT.attribute1
	,planDT.attribute2
	,planDT.attribute3
	,planDT.attribute4
	,planDT.attribute5
	,planDT.count_by
	,planDT.count_date
FROM t_wms_count_plan_master_external planMS
INNER JOIN t_wms_count_plan_detail_external planDT ON planMS.count_master_id = planDT.count_master_id
INNER JOIN t_wms_wh wh ON planMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_wh_item whItem ON planDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_category category  ON category.category_id = item.category_id
INNER JOIN t_wms_owner own ON item.owner_id = own.owner_id
INNER JOIN t_wms_item_uom uom ON (item.item_master_id = uom.item_master_id and uom.is_active = 'YES' and uom.primary_uom = 'YES')
INNER JOIN t_wms_location loc ON planDT.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc ON zLoc.location_id = loc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id




GO
/****** Object:  View [dbo].[v_wms_count_reconcile_merge_external_summary]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_count_reconcile_merge_external_summary]
AS
select count_master_id
,isnull(sum(ext.stock_qty),0.0) as stock_qty
--,isnull(sum(case when ext.inv_status = 'Consignment' then ext.count_qty else 0 end),0.0) as count_qty
,isnull(sum(ext.count_qty),0.0) as count_qty
,isnull(sum(ext.diff_qty),0.0) as diff_qty
,isnull(count(case when ext.inv_status = 'Missing CSM' then 1 else null end),0.0) count_miss
,isnull(count(case when ext.inv_status = 'Used' then 1 else null end),0.0) count_used
,isnull(count(case when ext.inv_status = 'Unknown' then 1 else null end),0.0) count_unknown
from v_wms_count_reconcile_merge_external ext
--where ext.count_master_id = '2A82D8B0-4AB1-46D3-B1B3-0DCFE7E2391D'
group by count_master_id



GO
/****** Object:  View [dbo].[v_wms_outbound_pick_list]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_outbound_pick_list]
AS
SELECT obMS.outbound_order_master_id
  , pickDT.outbound_order_detail_id
  , pickDT.outbound_pick_master_id
  , pickDT.outbound_pick_detail_id
  , obMS.wh_master_id
  , wh.wh_id
  , obMS.outbound_order_number
  , obMS.order_status
  , obMS.load_id
  , obMS.owner_id
  , obMS.customer_code
  , obDT.line_number
  , obDT.default_item_status
  , pickDT.location_id	  --Plan
  , loc.location		  --Plan
  , pickDT.parent_lpn	  --Plan
  , pickDT.lpn			  --Plan
  , pickDT.pick_line_number
  , pickDT.wh_item_master_id
  , item.item_master_id
  , item.item_number
  , item.description
  , obDT.item_uom_id
  , itemUom.uom_prompt
  , obDT.price
  , ISNULL(obDT.quantity_order,0)	AS quantity_order
  , ISNULL(pickDT.quantity_plan ,0) AS quantity_plan 
  , ISNULL(pickDT.quantity_pick ,0) AS quantity_pick 
  , ISNULL(pickDT.quantity_pack ,0) AS quantity_pack 
  , ISNULL(pickDT.quantity_load ,0) AS quantity_load 
  , ISNULL(pickDT.quantity_stage,0) AS quantity_stage
  , ISNULL(pickDT.quantity_ship,0)  AS quantity_ship
  , pickDT.pick_location_id
  , packLoc.location AS pick_location
  , pickDT.pick_to_parent_lpn
  , pickDT.pick_to_lpn
  , ISNULL(pickDT.lot_number,'')	AS lot_number
  , ISNULL(pickDT.expiry_date,'')   AS expiry_date
  , ISNULL(pickDT.serial_number,'') AS serial_number
  , pickDT.staging_location_id
  , stgLoc.location AS staging_location
  , pickDT.staging_parent_lpn
  , pickDT.staging_lpn
  , pickDT.dock_door_id
  , pickDT.dock_door_parent_lpn
  , pickDT.dock_door_lpn
  , pickDT.pick_status
  , pickDT.load_status
  , pickDT.is_override
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
LEFT JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id 
LEFT JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id = pickDT.wh_item_master_id 
LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id 
LEFT JOIN t_wms_item_uom itemUom ON obDT.item_uom_id = itemUom.item_uom_id
LEFT JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
LEFT JOIN t_wms_location packLoc ON pickDT.pick_location_id = packLoc.location_id
LEFT JOIN t_wms_location stgLoc ON pickDT.staging_location_id = stgLoc.location_id


GO
/****** Object:  View [dbo].[v_wms_inventory_api_viewer]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_inventory_api_viewer]
AS
SELECT inv.inventory_id 
	, wh.wh_id
	, inv.wh_master_id
	, own.owner_id
	, own.owner_code
	, inv.location_id
	, loc.location
	, ISNULL(inv.parent_lpn,'') AS parent_lpn
	, ISNULL(inv.lpn,'') AS lpn
	, inv.wh_item_master_id
	, item.item_master_id
	, item.item_number 
	, item.[description] as item_description
	, item.dg_code
	, ISNULL(invSN.quantity, inv.quantity) AS quantity
	, inv.inventory_status_id 
	, invStatus.inv_status
	, uom.uom_prompt
	, ISNULL(invLot.lot_number,'') AS lot_number
	, ISNULL(invExp.expiry_date,'') AS expiry_date
	, ISNULL(invAttribute1.attribute1,'') AS attribute1
	, ISNULL(invAttribute2.attribute2,'') AS attribute2
	, ISNULL(invAttribute3.attribute3,'') AS attribute3
	, ISNULL(invAttribute4.attribute4,'') AS attribute4
	, ISNULL(invAttribute5.attribute5,'') AS attribute5
	, ISNULL(invSN.serial_number,'') AS serial_number
	, inv.receive_date
FROM dbo.t_wms_inventory AS inv 
INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
INNER JOIN dbo.t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id
INNER JOIN dbo.t_wms_owner own ON inv.owner_id = own.owner_id 
INNER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id AND inv.wh_master_id = whItem.wh_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
INNER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS lot_number
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
		   ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS expiry_date
				,DATEDIFF(dd,GETDATE(),CONVERT(date,attribute_value,112)) as days_to_expire
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248'
		   ) AS invExp ON (inv.inventory_id = invExp.inventory_id) AND (inv.attribute_group_id = invExp.attribute_group_id) 
LEFT JOIN (SELECT  inventory_id
				,attribute_group_id
				,attribute_value AS serial_number
				,quantity
				,quantity_allocated
				,quantity_incoming
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
		   ) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute1
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714'
		   ) AS invAttribute1 ON (inv.inventory_id = invAttribute1.inventory_id) AND (inv.attribute_group_id = invAttribute1.attribute_group_id) 
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute2
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A'
		   ) AS invAttribute2 ON (inv.inventory_id = invAttribute2.inventory_id) AND (inv.attribute_group_id = invAttribute2.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute3
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526'
		   ) AS invAttribute3 ON (inv.inventory_id = invAttribute3.inventory_id) AND (inv.attribute_group_id = invAttribute3.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute4
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580'
		   ) AS invAttribute4 ON (inv.inventory_id = invAttribute4.inventory_id) AND (inv.attribute_group_id = invAttribute4.attribute_group_id)
LEFT JOIN (SELECT inventory_id
				,attribute_group_id
				,attribute_value AS attribute5
		   FROM dbo.t_wms_inventory_attribute
		   WHERE inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE'
		   ) AS invAttribute5 ON (inv.inventory_id = invAttribute5.inventory_id) AND (inv.attribute_group_id = invAttribute5.attribute_group_id)



GO
