  , item.item_number
  , item.description
  , obDT.item_uom_id
  , itemUom.uom_prompt 
  , itemUom.uom
  , obDT.quantity_order
  , ISNULL(pickDT.quantity_plan,0) AS quantity_plan 
  , ISNULL(pickDT.quantity_pick,0) AS quantity_pick
  , ISNULL(pickDT.quantity_load,0) AS quantity_load 
  , ISNULL(pickDT.quantity_stage,0) AS quantity_stage
  , ISNULL(pickDT.quantity_ship,0)  AS quantity_ship
  , pickDT.pick_location_id
  , pickDT.pick_to_parent_lpn
  , pickDT.pick_to_lpn
  , pickDT.lot_number
  , pickDT.expiry_date
  , pickDT.serial_number
  , pickDT.attribute1 
  , pickDT.attribute2 
  , pickDT.attribute3 
  , pickDT.attribute4 
  , pickDT.attribute5 
  , pickDT.staging_location_id
  , pickDT.staging_parent_lpn
  , pickDT.staging_lpn
  , pickDT.dock_door_id
  , pickDT.dock_door_parent_lpn
  , pickDT.dock_door_lpn
  , pickDT.pick_status
  , pickDT.load_status
  , item.lot_control
  , item.expiry_date_control
  , item.sn_control
  , item.attribute1_control
  , item.attribute2_control
  , item.attribute3_control
  , item.attribute4_control
  , item.attribute5_control
  , obDT.default_item_status
  , pickDT.is_override
  , pickDT.location_id
  , loc.location
  , loc.erp_location
  , pickDT.parent_lpn
  , pickDT.lpn
  , pickDT.receive_date
  , pickDT.mfg_date
  , obDT.user_def1
  , obDT.user_def2
  , obDT.user_def3
  , obDT.user_def4
  , obDT.user_def5
  , obDT.user_def6
  , obDT.user_def7
  , obDT.user_def8
  , obDT.user_def9
  , obDT.user_def10
  , obDT.interface_plan_uom_id
  , obDT.interface_plan_uom
  , z.zone_id
  , z.zone
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
INNER JOIN t_wms_location loc on pickDT.location_id = loc.location_id
INNER JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id = pickDT.wh_item_master_id 
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id 
INNER JOIN t_wms_item_uom itemUom ON obDT.item_uom_id = itemUom.item_uom_id
LEFT JOIN t_wms_zone_location zLoc ON loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id

 
