/****** Object:  View [dbo].[v_wms_dashboard_inventory_status]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create view [dbo].[v_wms_dashboard_inventory_status] as 

select 
sta.inv_status
,isnull(inv.quantity,0.0) as quantity
from t_wms_inventory_status as sta
LEFT JOIN
(	
	select 
	inventory_status_id 
	,sum(quantity) as quantity
	from t_wms_inventory
	group by inventory_status_id
) as inv on sta.inventory_status_id = inv.inventory_status_id
where sta.is_active = 'YES'
GO
