CREATE VIEW [dbo].[v_wms_count_reconcile_external]
AS
SELECT countMS.count_master_id
	, countMS.count_id
	, countMS.owner_code
	, countMS.count_status
	, countMS.count_plan_type
	, countMS.create_by AS create_plan_by
	, countRec.count_reconcile_id
	, countRec.approve_adjust
	, countRec.adjust_status
	, countRec.host_qty
	, countRec.location_id
	, countRec.location
	, countRec.parent_lpn
	, countRec.lpn
	, countRec.lot
	, countRec.expiry_date
	, countRec.serial_number
	, countRec.attribute1
	, countRec.attribute2
	, countRec.attribute3
	, countRec.attribute4
	, countRec.attribute5
	, countRec.create_by
	, countRec.create_date
	, countRec.expect_qty AS stock_qty
	, countRec.count_qty
	, countRec.count_qty - countRec.expect_qty AS diff_qty
	, countRec.inv_status
	, countRec.item_number
	, countRec.item_description
	, countRec.item_category
	, countRec.item_category_description
	, uom.uom_prompt
