LEFT JOIN t_wms_wh_item whItem On countRec.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item ON whitem.item_master_id = item.item_master_id
LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
LEFT JOIN t_wms_zone_location zoneLoc ON countRec.location_id = zoneLoc.location_id
