  , obDT.user_def3
  , obDT.user_def4
  , obDT.user_def5
  , obDT.user_def6
  , obDT.user_def7
  , obDT.user_def8
  , obDT.user_def9
  , obDT.user_def10
  , obDT.interface_plan_uom_id
  , obDT.interface_plan_uom
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
LEFT JOIN (SELECT pickDT.outbound_order_detail_id
				, pickDT.outbound_pick_master_id
				, pickDT.outbound_pick_detail_id
				, packDT.outbound_pack_detail_id
				, pickDT.pick_status
				, pickDT.location_id
				, loc.location
				, pickDT.parent_lpn
				, pickDT.lpn
				, pickDT.pick_line_number
				--, pickDT.wh_item_master_id
				, pickDT.quantity_plan
				, pickDT.quantity_pick
				, packDT.quantity_pack
				, pickDT.quantity_ship
				, pickDT.is_override
				, pickDT.receive_date
				-- ต้อง Case When เพราะว่า ถ้ามีการใช้ Function จะต้องดึงข้อมูลจาก Table Pack 
				, (CASE ISNULL(packDT.quantity_load,0) WHEN 0 THEN pickDT.quantity_load ELSE packDT.quantity_load END) AS quantity_load
				, (CASE ISNULL(packDT.quantity_stage,0) WHEN 0 THEN pickDT.quantity_stage ELSE packDT.quantity_stage END) AS quantity_stage
				, (CASE ISNULL(packDT.pack_location_id,'') WHEN '' THEN pickDT.pick_location_id ELSE packDT.pack_location_id END) AS pick_location_id
				, (CASE ISNULL(packDT.parent_lpn_pack,'') WHEN '' THEN pickDT.pick_to_parent_lpn ELSE packDT.parent_lpn_pack END) AS pick_to_parent_lpn
				, (CASE ISNULL(packDT.lpn_pack,'') WHEN '' THEN pickDT.pick_to_lpn ELSE packDT.lpn_pack END) AS pick_to_lpn
				, (CASE ISNULL(packDT.lot_number,'') WHEN '' THEN pickDT.lot_number ELSE packDT.lot_number END) AS lot_number
				, (CASE ISNULL(packDT.expiry_date,'') WHEN '' THEN pickDT.expiry_date ELSE packDT.expiry_date END) AS expiry_date
				, (CASE ISNULL(packDT.attribute1,'') WHEN '' THEN pickDT.attribute1 ELSE packDT.attribute1 END) AS attribute1
				, (CASE ISNULL(packDT.attribute2,'') WHEN '' THEN pickDT.attribute2 ELSE packDT.attribute2 END) AS attribute2
				, (CASE ISNULL(packDT.attribute3,'') WHEN '' THEN pickDT.attribute3 ELSE packDT.attribute3 END) AS attribute3
				, (CASE ISNULL(packDT.attribute4,'') WHEN '' THEN pickDT.attribute4 ELSE packDT.attribute4 END) AS attribute4
				, (CASE ISNULL(packDT.attribute5,'') WHEN '' THEN pickDT.attribute5 ELSE packDT.attribute5 END) AS attribute5
				, (CASE ISNULL(packDT.serial_number,'') WHEN '' THEN pickDT.serial_number ELSE packDT.serial_number END) AS serial_number
				, (CASE ISNULL(packDT.staging_location_id,'') WHEN '' THEN pickDT.staging_location_id ELSE packDT.staging_location_id END) AS staging_location_id
				, (CASE ISNULL(packDT.staging_parent_lpn,'') WHEN '' THEN pickDT.staging_parent_lpn ELSE packDT.staging_parent_lpn END) AS staging_parent_lpn
				, (CASE ISNULL(packDT.staging_lpn,'') WHEN '' THEN pickDT.staging_lpn ELSE packDT.staging_lpn END) AS staging_lpn
				, (CASE ISNULL(packDT.dock_door_id,'') WHEN '' THEN pickDT.dock_door_id ELSE packDT.dock_door_id END) AS dock_door_id
				, (CASE ISNULL(packDT.dock_door_parent_lpn,'') WHEN '' THEN pickDT.dock_door_parent_lpn ELSE packDT.dock_door_parent_lpn END) AS dock_door_parent_lpn
				, (CASE ISNULL(packDT.dock_door_lpn,'') WHEN '' THEN pickDT.dock_door_lpn ELSE packDT.dock_door_lpn END) AS dock_door_lpn
				, (CASE ISNULL(packDT.load_status,'') WHEN '' THEN pickDT.load_status ELSE packDT.load_status END) AS load_status
			FROM t_wms_outbound_pick_detail pickDT
			LEFT JOIN t_wms_outbound_pack_detail packDT ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id
														AND pickDT.wh_item_master_id = packDT.wh_item_master_id
			LEFT JOIN t_wms_location loc on pickDT.location_id = loc.location_id
		   ) PickPack ON obDT.outbound_order_detail_id = PickPack.outbound_order_detail_id
LEFT JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id 
LEFT JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id = obDT.wh_item_master_id 
LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id 
LEFT JOIN t_wms_item_uom itemUom ON obDT.item_uom_id = itemUom.item_uom_id


