SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[v_wms_outbound_print_pick_allocated]
AS
	SELECT  dbo.t_wms_outbound_pick_master.outbound_order_number
		 , dbo.t_wms_location.location
		 , dbo.t_wms_item.item_number
		 , dbo.t_wms_item.description
		 , dbo.t_wms_outbound_pick_detail.quantity_plan
		 , dbo.t_wms_item_uom.uom
		 , dbo.t_wms_outbound_pick_detail.lpn
		 , dbo.t_wms_outbound_pick_detail.lot_number
		 , dbo.t_wms_outbound_pick_detail.expiry_date
		 , dbo.t_wms_owner.owner_code
		 , dbo.t_wms_outbound_master.owner_id
		 , dbo.t_wms_location.pick_sequence
	FROM dbo.t_wms_outbound_pick_master 
	INNER JOIN dbo.t_wms_outbound_pick_detail ON dbo.t_wms_outbound_pick_master.outbound_pick_master_id = dbo.t_wms_outbound_pick_detail.outbound_pick_master_id 
	INNER JOIN dbo.t_wms_outbound_master ON dbo.t_wms_outbound_pick_master.outbound_order_master_id = dbo.t_wms_outbound_master.outbound_order_master_id 
	INNER JOIN dbo.t_wms_owner on dbo.t_wms_outbound_master.owner_id = dbo.t_wms_owner.owner_id
	INNER JOIN dbo.t_wms_wh_item ON dbo.t_wms_outbound_pick_detail.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
	INNER JOIN dbo.t_wms_wh ON dbo.t_wms_outbound_pick_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
	INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
	INNER JOIN dbo.t_wms_item_uom on dbo.t_wms_item_uom.item_master_id = dbo.t_wms_item.item_master_id
	INNER JOIN dbo.t_wms_location ON dbo.t_wms_outbound_pick_detail.location_id = dbo.t_wms_location.location_id 
	WHERE dbo.t_wms_outbound_master.order_status = 'RELEASE'
	

GO
/****** Object:  View [dbo].[v_wms_outbound_rel_by_load]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 
CREATE VIEW [dbo].[v_wms_outbound_rel_by_load]
AS
SELECT grb.wh_master_id
, grb.wh_id
, grb.owner_id
, grb.owner_code
, grb.dock_door_id
, grb.load_id,isnull(grb.pick_type,'') as pick_type
, grb.order_qty
, grb.load_status
, grb.cancel_status
, lc.location
, grb.create_date, us.user_id
FROM (SELECT wh.wh_master_id
	  		, wh.wh_id
	  		, ow.owner_id
	  		, ow.owner_code
	  		, ms.dock_door_id
	  		, ms.load_id
	  		, ms.pick_type
	  		, COUNT(*) AS order_qty
	  		, CASE WHEN COUNT(CASE WHEN ms.order_status = 'OPEN' THEN 1 END) = COUNT(*) THEN 'OPEN' 
	  							   WHEN COUNT(CASE WHEN ms.order_status = 'RELEASE' THEN 1 END) = COUNT(*) THEN 'RELEASE' 
	  							   WHEN COUNT(CASE WHEN ms.order_status = 'PICKED' THEN 1 END) = COUNT(*) THEN 'PICKED' 
	  							   WHEN COUNT(CASE WHEN ms.order_status = 'LOADED' THEN 1 END) = COUNT(*) THEN 'LOADED'
								   WHEN COUNT(CASE WHEN ms.order_status = 'SHIP' THEN 1 END) = COUNT(*) THEN 'SHIP'
								   WHEN COUNT(CASE WHEN ms.order_status = 'PICKED' OR ms.order_status = 'SHIP' THEN 1 END) = COUNT(*) THEN 'PICKED' 
	  							   WHEN COUNT(CASE WHEN (ms.order_status = 'LOADING' OR ms.order_status = 'LOADED') THEN 1 END) > 0 THEN 'LOADING' 
	  							   WHEN COUNT(CASE WHEN (ms.order_status = 'PICK' OR ms.order_status = 'PICKED') THEN 1 END) > 0 THEN 'PICK' ELSE 'CLOSE' END AS load_status
	  		, CASE WHEN COUNT(CASE WHEN (ms.order_status = 'OPEN' OR ms.order_status = 'RELEASE') THEN 1 END) = COUNT(*) THEN CONVERT(bit, 1) ELSE CONVERT(bit, 0) END AS cancel_status
	  		, MAX(ms.create_date) AS create_date
      FROM dbo.t_wms_outbound_master AS ms 
	  INNER JOIN dbo.t_wms_wh AS wh ON ms.wh_master_id = wh.wh_master_id 
	  INNER JOIN dbo.t_wms_owner AS ow ON ms.owner_id = ow.owner_id
      WHERE (ISNULL(ms.load_id, N'') <> '')
      GROUP BY wh.wh_master_id, wh.wh_id, ow.owner_id, ow.owner_code, ms.dock_door_id, ms.load_id,ms.pick_type
	  ) AS grb 
LEFT JOIN dbo.t_wms_location AS lc ON grb.dock_door_id = lc.location_id 
INNER JOIN dbo.t_wms_wh_user AS us ON grb.wh_master_id = us.wh_master_id






GO
/****** Object:  View [dbo].[v_wms_outbound_rel_by_load_detail]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_outbound_rel_by_load_detail]
AS
SELECT        det.default_item_status, item.item_number, det.item_description, cat.item_category, det.lot_number, det.lpn, det.expiry_date, det.grade, det.price, uom.uom, 
                         mas.wh_master_id, mas.load_id, SUM(det.quantity_order) AS quantity_order, SUM(det.quantity_pick) AS quantity_pick, SUM(det.quantity_load) AS quantity_load, 
                         SUM(det.quantity_ship) AS quantity_ship
FROM            dbo.t_wms_outbound_detail AS det INNER JOIN
                         dbo.t_wms_outbound_master AS mas ON det.outbound_order_master_id = mas.outbound_order_master_id INNER JOIN
                         dbo.t_wms_item_uom AS uom ON det.item_uom_id = uom.item_uom_id INNER JOIN
                         dbo.t_wms_wh_item ON det.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id INNER JOIN
                         dbo.t_wms_item AS item ON dbo.t_wms_wh_item.item_master_id = item.item_master_id INNER JOIN
                         dbo.t_wms_category AS cat ON item.category_id = cat.category_id
GROUP BY det.default_item_status, item.item_number, det.item_description, cat.item_category, det.lot_number, det.lpn, det.expiry_date, det.grade, det.price, uom.uom, 
                         mas.wh_master_id, mas.load_id



