SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_report_outbound_packing_list]
AS
--====================================================================================================
--	DATE		Modyfy	Description
--	2020-10-07	NUI		Create New View
--====================================================================================================
	SELECT wh.wh_id, wh.wh_name
		 , obMS.outbound_order_number
		 , obMS.order_type
		 , obMS.order_date
		 , obMS.delivery_date_plan
		 , ISNULL(cus.customer_code, '') customer_code
		 , ISNULL(cus.customer_name, '')customer_name
		 , ISNULL(cus.addr_line_1, '') addr_line_1
		 , ISNULL(cus.addr_line_2, '') addr_line_2
		 , ISNULL(cus.addr_line_3, '') addr_line_3
		 , ISNULL(cus.city, '') city
		 , ISNULL(cus.province, '') province
		 , ISNULL(cus.postal_code, '') postal_code
		 , ISNULL(cus.country_name, '') country_name
		 , comment.comment
		 , packDT.lpn_pack
		 , itm.item_number
		 , itm.description item_description
		 , pickDT.lot_number
		 , CAST(pickDT.expiry_date AS DATETIME) expiry_date
		 , pickDT.serial_number
		 , ISNULl(packDT.quantity_pack,0) quantity_pack
		 , uom.uom
		 		 , itm.user_def1
		 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
	LEFT JOIN t_wms_outbound_pack_detail packDT ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id
	LEFT JOIN t_wms_outbound_comment comment ON obMS.outbound_order_master_id = comment.outbound_order_master_id
	INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
	INNER JOIN t_wms_item itm ON obDT.item_master_id = itm.item_master_id
	INNER JOIN t_wms_item_uom uom ON itm.item_master_id = uom.item_master_id AND obDT.item_uom_id = uom.item_uom_id
	LEFT JOIN t_wms_customer cus ON obMS.customer_id = cus.customer_id

