CREATE VIEW [dbo].[v_wms_count_reconcile_detail]
AS
SELECT CountData.count_id
	, CountData.zone AS room
	, CountData.parent_lpn
	, CountData.location
	, CountData.item_number
	, CountData.description
	, CountData.lot AS Batch
	, CountData.expiry_date
	, CountData.expect_lpn AS countexpectlpn
	, CountData.expect_qty
	, CountData.countlpn
	, CountData.CountQty AS count_qty
	, CountData.uom
	, CountData.uom_prompt
	, CountData.count_status
	, CountData.count_plan_type
	, CountData.countlpn - CountData.expect_lpn AS diff_lpn
	, CountData.CountQty - CountData.expect_qty AS diff_qty
	, CountData.wh_id
	, CountData.create_by AS plan_user
	, CAST(CONVERT(VARCHAR(10), CountData.create_date, 102) AS DATETIME) AS create_date_plan	
	, ISNULL ((SELECT top 1 cr.create_by
					FROM dbo.t_wms_count_reconcile AS cr
					WHERE (count_master_id = CountData.count_master_id) 
					AND (wh_item_master_id = CountData.wh_item_master_id) 
					AND (location_id = CountData.location_id)
					AND (ISNULL(parent_lpn,'') = ISNULL(CountData.parent_lpn,'')) 
					AND (ISNULL(lot,'') = ISNULL(CountData.lot,''))		
					AND (ISNULL(expiry_date,'') = ISNULL(CountData.expiry_date,''))	
					), '') AS count_user
		, (SELECT top 1 MAX(cr.create_date)
					FROM dbo.t_wms_count_reconcile AS cr
					WHERE (count_master_id = CountData.count_master_id) 
					AND (wh_item_master_id = CountData.wh_item_master_id) 
					AND (location_id = CountData.location_id)
					AND (ISNULL(parent_lpn,'') = ISNULL(CountData.parent_lpn,'')) 
					AND (ISNULL(lot,'') = ISNULL(CountData.lot,''))
					AND (ISNULL(expiry_date,'') = ISNULL(CountData.expiry_date,''))			
					) AS count_date
FROM (

	SELECT 
		cm.count_id
		, cd.parent_lpn
		, dbo.t_wms_zone.zone
		, dbo.t_wms_location.location
		, dbo.t_wms_item.item_number
		, dbo.t_wms_item.description
		, cd.lot
		, cd.expiry_date
		, COUNT(cd.lpn) AS expect_lpn
		, SUM(cd.stock_qty) AS expect_qty
		, ISNULL ((SELECT  COUNT(lpn) AS Expr1
					FROM dbo.t_wms_count_reconcile AS cr
					WHERE (count_master_id = cm.count_master_id) 					 
					AND (wh_item_master_id = cd.wh_item_master_id) 
					AND (location_id = cd.location_id)
					AND (ISNULL(parent_lpn,'') = ISNULL(cd.parent_lpn,''))  
					AND (ISNULL(lot,'') = ISNULL(cd.lot,''))
					AND (ISNULL(expiry_date,'') = ISNULL(cd.expiry_date,''))
					), 0) AS countlpn
		, ISNULL ((SELECT  SUM(count_qty) AS Expr1
					FROM dbo.t_wms_count_reconcile AS cr
					WHERE (count_master_id = cm.count_master_id) 
					AND (wh_item_master_id = cd.wh_item_master_id) 
					AND (location_id = cd.location_id)
					AND (ISNULL(parent_lpn,'') = ISNULL(cd.parent_lpn,'')) 
					AND (ISNULL(lot,'') = ISNULL(cd.lot,''))
					AND (ISNULL(expiry_date,'') = ISNULL(cd.expiry_date,''))
					), 0) AS CountQty
		, dbo.t_wms_item_uom.uom
		, dbo.t_wms_item_uom.uom_prompt
		, cm.count_status
		, cm.count_plan_type
		, dbo.t_wms_wh.wh_id
		, cm.create_by
		, cm.create_date
		, cm.count_master_id
		, cd.wh_item_master_id
		, cd.location_id
	FROM dbo.t_wms_count_plan_master AS cm 
	INNER JOIN dbo.t_wms_count_plan_detail AS cd ON cm.count_master_id = cd.count_master_id
	INNER JOIN dbo.t_wms_wh ON cm.wh_master_id = dbo.t_wms_wh.wh_master_id
	INNER JOIN dbo.t_wms_wh_item ON cd.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
	INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
	INNER JOIN dbo.t_wms_item_uom ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_uom.item_master_id 
	INNER JOIN dbo.t_wms_location ON cd.location_id = dbo.t_wms_location.location_id 
	LEFT JOIN dbo.t_wms_zone_location ON dbo.t_wms_location.location_id = dbo.t_wms_zone_location.location_id
	LEFT JOIN dbo.t_wms_zone ON dbo.t_wms_zone.zone_id = dbo.t_wms_zone_location.zone_id

	WHERE (dbo.t_wms_item_uom.primary_uom = 'YES')
	GROUP BY cm.count_id
	, cd.parent_lpn
	, dbo.t_wms_zone.zone
	, dbo.t_wms_location.location
	, dbo.t_wms_item.item_number
	, dbo.t_wms_item.description
	, cd.lot
	, cd.expiry_date
	, dbo.t_wms_item_uom.uom
	, dbo.t_wms_item_uom.uom_prompt
	, cm.count_status
	, cm.count_plan_type
	, dbo.t_wms_wh.wh_id
	, cm.create_by
	, cm.create_date
	, cm.count_master_id
	, cd.wh_item_master_id
	, cd.location_id
	
	
	
	
							
) AS CountData 

-- พบมีการนับหลายครั้งใน t_wms_count_reconcile ทำให้การ group ในส่วนนี้ไม่ได้
--LEFT OUTER JOIN dbo.t_wms_count_reconcile ON CountData.wh_item_master_id = dbo.t_wms_count_reconcile.wh_item_master_id 
--											AND ISNULL(CountData.lot,'') = ISNULL(dbo.t_wms_count_reconcile.lot,'') 
--											AND ISNULL(CountData.parent_lpn,'') = ISNULL(dbo.t_wms_count_reconcile.parent_lpn,'')
--											AND CountData.count_master_id = dbo.t_wms_count_reconcile.count_master_id

--GROUP BY CountData.count_id, CountData.zone, CountData.parent_lpn, CountData.location, CountData.item_number, CountData.description, CountData.lot
--, CountData.expect_lpn, CountData.expect_qty, CountData.countlpn, CountData.CountQty, CountData.uom, CountData.uom_prompt, CountData.count_status
--, CountData.count_plan_type, CountData.countlpn - CountData.expect_lpn, CountData.CountQty - CountData.expect_qty
--, CountData.wh_id, CountData.create_by, CountData.create_date, CountData.count_master_id

--, dbo.t_wms_count_reconcile.create_by
--, CAST(CONVERT(VARCHAR(10), dbo.t_wms_count_reconcile.create_date, 102) AS DATETIME)





