/****** Object:  View [dbo].[v_wms_outbound_rel_by_load_pickdetail_serial]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_outbound_rel_by_load_pickdetail_serial]
AS
SELECT obMS.wh_master_id 
	, obMS.load_id
	, obMS.order_status	
	, item.item_number
	, item.description
	, locPick.location			AS pick_location--ส่วนที่จะไปหยิบ
	, pickDT.parent_lpn			--ส่วนที่จะไปหยิบ
	, pickDT.lpn				--ส่วนที่จะไปหยิบ
	, pickDT.lot_number			--ส่วนที่จะไปหยิบ
	, pickDT.expiry_date		--ส่วนที่จะไปหยิบ
	, locSN.location			AS pick_sn_to_location--หยิบมาแล้ว
	, pickDT.pick_to_parent_lpn	--หยิบมาแล้ว
	, pickDT.pick_to_lpn		--หยิบมาแล้ว
	, pickDT.pick_status		--หยิบมาแล้ว
	, pickDT.load_status		--หยิบมาแล้ว
	, pickDT.staging_lpn		--หยิบมาแล้ว
	, locSTG.location			AS pick_sn_to_staging--หยิบมาแล้ว
	, pickDT.quantity_pick		--หยิบมาแล้ว
	, pickDT.quantity_pack		--หยิบมาแล้ว
	, pickDT.quantity_load		--หยิบมาแล้ว
	, pickDT.quantity_stage		--หยิบมาแล้ว
	, pickDT.quantity_ship		--หยิบมาแล้ว
	, pickDT.serial_number		--หยิบมาแล้ว
	, pickDT.create_date	AS pick_sn_create_date
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
INNER JOIN t_wms_wh_item whItem on pickDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_location locPick on pickDT.location_id = locPick.location_id
LEFT JOIN t_wms_location locSN on pickDT.pick_location_id = locSN.location_id
LEFT JOIN t_wms_location locSTG on pickDT.staging_location_id = locSTG.location_id


