/****** Object:  View [dbo].[v_wms_count_reconcile_merge]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_count_reconcile_merge]
AS
WITH tReconcile AS
(
	SELECT count_master_id
		,location_id 
		,wh_item_master_id
		,inv_status
		,lpn
		,lot 
		,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,SUM(ISNULL(count_qty,0)) AS count_qty
	FROM t_wms_count_reconcile
	GROUP BY count_master_id
		,location_id 
		,wh_item_master_id
		,inv_status
		,lpn
		,lot 
		,CONVERT(VARCHAR,expiry_date,112)
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
)
SELECT  planMS.count_master_id
	, planMS.count_id
	, planMS.wh_master_id
	, wh.wh_id
	, own.owner_id
	, own.owner_code
	, item.item_number
	, item.description
	, item.dg_code
	, item.price
	, item.grade
	, tCount.lpn
	, tCount.lot
	, tCount.expiry_date AS expiry_date
	, tCount.serial_number AS serial_number
	, tCount.location_id AS location_id
	, tCount.inv_status AS inv_status
	, planDT.parent_lpn 
	, ISNULL(planDT.stock_qty, 0)	AS stock_qty
	, ISNULL(recDT.count_qty, 0)	AS count_qty
	, ISNULL(recDT.count_qty, 0) - ISNULL(planDT.stock_qty, 0) AS diff_qty
	, uom.uom_prompt
	, loc.location
	, z.zone_id
	, z.zone
	, cate.category_id
	, cate.item_category
	, cate.[description] as cate_description
	, tCount.attribute1
	, tCount.attribute2
	, tCount.attribute3
	, tCount.attribute4
	, tCount.attribute5
	, planDT.count_by
	, planDT.count_date
FROM (SELECT count_master_id
			,location_id 
			,wh_item_master_id
			,inv_status
			,lpn
			,lot  
			,[expiry_date] 
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5
		FROM t_wms_count_plan_detail
		UNION
		SELECT count_master_id
			,location_id 
			,wh_item_master_id
			,inv_status
			,lpn
			,lot 
			,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
			,serial_number
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5 
		FROM t_wms_count_reconcile
		) tCount
LEFT JOIN t_wms_count_plan_detail planDT ON tCount.count_master_id = planDT.count_master_id
										AND tCount.wh_item_master_id = planDT.wh_item_master_id
										AND tCount.inv_status = planDT.inv_status
										AND tCount.location_id = planDT.location_id
										AND ISNULL(tCount.lpn,'') = ISNULL(planDT.lpn,'')
										AND ISNULL(tCount.lot,'') = ISNULL(planDT.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(planDT.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(planDT.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(planDT.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(planDT.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(planDT.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(planDT.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(planDT.attribute5,'')
LEFT JOIN tReconcile recDT ON tCount.count_master_id = recDT.count_master_id
										AND tCount.wh_item_master_id = recDT.wh_item_master_id
										AND tCount.inv_status = recDT.inv_status
										AND tCount.location_id = recDT.location_id
										AND ISNULL(tCount.lpn,'') = ISNULL(recDT.lpn,'')
										AND ISNULL(tCount.lot,'') = ISNULL(recDT.lot,'')
										AND ISNULL(tCount.expiry_date,'') = ISNULL(recDT.expiry_date,'')
										AND ISNULL(tCount.serial_number,'') = ISNULL(recDT.serial_number,'')
										AND ISNULL(tCount.attribute1,'') = ISNULL(recDT.attribute1,'')
										AND ISNULL(tCount.attribute2,'') = ISNULL(recDT.attribute2,'')
										AND ISNULL(tCount.attribute3,'') = ISNULL(recDT.attribute3,'')
										AND ISNULL(tCount.attribute4,'') = ISNULL(recDT.attribute4,'')
										AND ISNULL(tCount.attribute5,'') = ISNULL(recDT.attribute5,'')
INNER JOIN t_wms_count_plan_master planMS ON tCount.count_master_id = planMS.count_master_id
INNER JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id  = tCount.wh_item_master_id
INNER JOIN t_wms_item item ON item.item_master_id = whItem.item_master_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
INNER JOIN (SELECT item_master_id
				,item_uom_id
				,uom
				,uom_prompt
			FROM t_wms_item_uom
			WHERE primary_uom = 'YES'
			) uom ON item.item_master_id = uom.item_master_id
INNER JOIN t_wms_owner own ON planMS.owner_id = own.owner_id
INNER JOIN t_wms_wh wh ON planMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_location loc ON tCount.location_id = loc.location_id
LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id









GO
/****** Object:  View [dbo].[v_wms_outbound_shipment]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[v_wms_outbound_shipment]
AS
SELECT        dbo.t_wms_wh.wh_id, dbo.t_wms_outbound_master.outbound_order_number, item.item_number, dbo.t_wms_outbound_pick_detail.quantity_plan AS quantity_order, 
CASE WHEN order_type = '601' OR
order_type = '901' THEN dbo.t_wms_outbound_pick_detail.quantity_load ELSE dbo.t_wms_outbound_pick_detail.quantity_stage END AS quantity_ship, 
uom.uom_prompt, item.description AS item_description, dbo.t_wms_outbound_detail.create_date, dbo.t_wms_outbound_detail.create_by, 
dbo.t_wms_outbound_master.customer_code, dbo.t_wms_outbound_master.order_type, dbo.t_wms_outbound_master.order_status, 
dbo.t_wms_outbound_master.customer_name, dbo.t_wms_outbound_master.ship_date_actual, 
dbo.t_wms_outbound_master.customer_code + ' ' + dbo.t_wms_outbound_master.customer_name AS customer_code_name, dbo.t_wms_carrier.carrier_name, 
dbo.t_wms_outbound_master.ship_to_name, dbo.t_wms_outbound_master.truck_no, dbo.t_wms_outbound_master.truck_type_id, dbo.t_wms_truck_type.truck_type,
dbo.t_wms_outbound_master.seal_no, dbo.t_wms_outbound_master.tracking_number AS booking_number, 
dbo.t_wms_outbound_master.loading_date_plan AS Container_Arrive, dbo.t_wms_outbound_master.loading_date_actual AS Container_Open, 
dbo.t_wms_outbound_pick_detail.quantity_load, dbo.t_wms_outbound_master.container_no, ISNULL(dbo.t_wms_outbound_pick_detail.dock_door_lpn, 
dbo.t_wms_outbound_pick_detail.staging_lpn) AS lpn, dbo.t_wms_outbound_pick_detail.lot_number, dbo.t_wms_location.location, 
dbo.t_wms_outbound_pick_detail.quantity_stage
FROM            dbo.t_wms_outbound_pick_detail 
INNER JOIN dbo.t_wms_outbound_detail ON dbo.t_wms_outbound_pick_detail.outbound_order_detail_id = dbo.t_wms_outbound_detail.outbound_order_detail_id 
LEFT OUTER JOIN dbo.t_wms_location ON dbo.t_wms_outbound_pick_detail.dock_door_id = dbo.t_wms_location.location_id 
RIGHT OUTER JOIN dbo.t_wms_carrier 
RIGHT OUTER JOIN dbo.t_wms_outbound_master ON dbo.t_wms_carrier.carrier_id = dbo.t_wms_outbound_master.carrier_id
			 ON dbo.t_wms_outbound_detail.outbound_order_master_id = dbo.t_wms_outbound_master.outbound_order_master_id 
LEFT OUTER JOIN dbo.t_wms_wh ON dbo.t_wms_outbound_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
LEFT OUTER JOIN dbo.t_wms_item_uom AS uom ON dbo.t_wms_outbound_detail.item_uom_id = uom.item_uom_id 
LEFT OUTER JOIN dbo.t_wms_rule ON uom.picking_class = dbo.t_wms_rule.rule_id 
LEFT OUTER JOIN dbo.t_wms_truck_type ON dbo.t_wms_outbound_master.truck_type_id =  dbo.t_wms_truck_type.truck_type_id 

FULL OUTER JOIN dbo.t_wms_wh_item AS whItem 
LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN dbo.t_wms_item_crossref AS cref ON item.item_master_id = cref.item_master_id 
				ON dbo.t_wms_outbound_detail.wh_item_master_id = whItem.wh_item_master_id
WHERE (dbo.t_wms_outbound_master.order_status = 'SHIP') 
AND (ISNULL(dbo.t_wms_outbound_pick_detail.dock_door_lpn, dbo.t_wms_outbound_pick_detail.staging_lpn) IS NOT NULL) 
AND (CASE WHEN order_type = '601' OR order_type = '901' THEN dbo.t_wms_outbound_pick_detail.quantity_load ELSE dbo.t_wms_outbound_pick_detail.quantity_stage END > 0)
GROUP BY dbo.t_wms_wh.wh_id, dbo.t_wms_outbound_master.outbound_order_number, item.item_number, dbo.t_wms_outbound_pick_detail.quantity_plan, 
dbo.t_wms_outbound_pick_detail.quantity_load, uom.uom_prompt, item.description, dbo.t_wms_outbound_detail.create_date, 
dbo.t_wms_outbound_detail.create_by, dbo.t_wms_outbound_master.customer_code, dbo.t_wms_outbound_master.order_type, 
dbo.t_wms_outbound_master.order_status, dbo.t_wms_outbound_master.customer_name, dbo.t_wms_outbound_master.ship_date_actual, 
dbo.t_wms_outbound_master.customer_code + ' ' + dbo.t_wms_outbound_master.customer_name, dbo.t_wms_carrier.carrier_name, 
dbo.t_wms_outbound_master.ship_to_name, dbo.t_wms_outbound_master.truck_no, dbo.t_wms_outbound_master.truck_type_id, dbo.t_wms_truck_type.truck_type,
dbo.t_wms_outbound_master.seal_no, dbo.t_wms_outbound_master.tracking_number, dbo.t_wms_outbound_master.loading_date_plan, 
dbo.t_wms_outbound_master.loading_date_actual, dbo.t_wms_outbound_detail.quantity_load, dbo.t_wms_outbound_master.container_no, 
dbo.t_wms_outbound_pick_detail.dock_door_lpn, dbo.t_wms_outbound_pick_detail.lot_number, dbo.t_wms_location.location, 
dbo.t_wms_outbound_pick_detail.quantity_stage, dbo.t_wms_outbound_pick_detail.staging_lpn



GO
/****** Object:  View [dbo].[v_wms_report_outbound_shipment]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[v_wms_report_outbound_shipment]
AS
--====================================================================================================
--	DATE		Modyfy	Description
--	2020-10-27	NUI		Create New View
--====================================================================================================
SELECT wh.wh_id
	 , wh.wh_name
	 , cus.customer_code
	 , cus.customer_name
	 , obMS.outbound_order_number
	 , obMS.order_type
	 , obMS.order_status
	 , obMS.ship_date_actual
	 , obMS.ship_to_code
	 , obMS.ship_to_name	 
	 , obMS.container_no
	 , obMS.loading_date_plan --Container Arrive
	 , obMS.loading_date_actual --Container Open
	 , obMS.seal_no
	 , obMS.truck_no	 
	 , truck.truck_code
	 , truck.truck_name
	 , truckT.truck_type	 
	 , carr.carrier_code
	 , carr.carrier_name
	 , itm.item_number
	 , itm.description item_description
	 , pickDT.staging_lpn
	 , pickDT.lot_number
	 , SUM(obDT.quantity_order) quantity_order
	 , SUM(pickDT.quantity_load) quantity_load
	 , SUM(pickDT.quantity_ship) quantity_ship
	 , uom.uom
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
INNER JOIN t_wms_item itm ON obDT.item_master_id = itm.item_master_id
INNER JOIN t_wms_item_uom uom ON itm.item_master_id = uom.item_master_id AND obDT.item_uom_id = uom.item_uom_id
LEFT JOIN t_wms_customer cus ON obMS.customer_id = cus.customer_id
LEFT JOIN t_wms_carrier carr ON obMS.carrier_id = carr.carrier_id
LEFT JOIN t_wms_truck_type truckT
LEFT JOIN t_wms_truck truck ON truckT.truck_type_id = truck.truck_type_id
						    ON obMS.truck_type_id = truckT.truck_type_id
GROUP BY wh.wh_id, wh.wh_name
	 , cus.customer_code, cus.customer_name
	 , obMS.outbound_order_number, obMS.order_type, obMS.order_status
	 , obMS.loading_date_plan, obMS.loading_date_actual, obMS.ship_date_actual
	 , obMS.ship_to_code, obMS.ship_to_name	 
	 , obMS.container_no, obMS.seal_no
	 , obMS.truck_no, truck.truck_code, truck.truck_name, truckT.truck_type
	 , carr.carrier_code, carr.carrier_name
	 , itm.item_number, itm.description, pickDT.staging_lpn, pickDT.lot_number, uom.uom
GO
/****** Object:  View [dbo].[v_wms_report_material_issue]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_material_issue]
AS
-- select * from v_wms_report_material_issue where outbound_order_number = 'Export-20191224-001'
WITH cte_item_master AS 
(
	SELECT itmw.wh_item_master_id, itm.item_master_id, itm.item_number, itm.description, itm.dg_code, itmu.item_uom_id, itmu.uom, itmu.uom_prompt
	FROM dbo.t_wms_item AS itm 
	INNER JOIN dbo.t_wms_wh_item AS itmw ON itm.item_master_id = itmw.item_master_id 
	INNER JOIN dbo.t_wms_item_uom AS itmu ON itm.item_master_id = itmu.item_master_id
), cte_outbound_order AS
(
	SELECT om.outbound_order_master_id, om.outbound_order_number, om.customer_order_number, om.customer_purchase_order
		 , wh.wh_master_id, wh.wh_id, wh.wh_name
		 , itm.wh_item_master_id, itm.item_master_id, itm.item_number, itm.description item_description, itm.dg_code
		 , itm.item_uom_id, itm.uom, itm.uom_prompt
		 , ISNULL(SUM(od.quantity_order), 0) AS quantity_order
		 , ISNULL(SUM(od.quantity_stage), 0) AS quantity_stage
		 , ISNULL(SUM(od.quantity_pick), 0) AS quantity_pick
		 , ISNULL(SUM(od.quantity_load), 0) AS quantity_load
		 , ISNULL(SUM(od.quantity_ship), 0) AS quantity_ship
	FROM dbo.t_wms_outbound_detail AS od 
	INNER JOIN dbo.t_wms_outbound_master AS om ON od.outbound_order_master_id = om.outbound_order_master_id 
	INNER JOIN dbo.t_wms_wh AS wh ON om.wh_master_id = wh.wh_master_id AND om.wh_id = wh.wh_id 
	INNER JOIN cte_item_master AS itm ON od.wh_item_master_id = itm.wh_item_master_id AND od.item_master_id = itm.item_master_id AND od.item_uom_id = itm.item_uom_id
	GROUP BY om.outbound_order_master_id, om.outbound_order_number, om.customer_order_number, om.customer_purchase_order, wh.wh_master_id, wh.wh_id, wh.wh_name, itm.wh_item_master_id, itm.item_master_id, itm.item_number, itm.description, itm.dg_code, itm.item_uom_id, itm.uom, itm.uom_prompt
), cte_inventory AS
(
	SELECT inv.wh_master_id, inv.wh_item_master_id--, inv.location_id
		 , ISNULL(SUM(inv.quantity), 0) AS quantity_onhand
	FROM dbo.t_wms_inventory AS inv 
	GROUP BY inv.wh_master_id, inv.wh_item_master_id--, inv.location_id
)
SELECT o.outbound_order_number
	 , o.wh_name
	 , o.item_number
	 , o.dg_code
	 , o.item_description
	 , o.uom
	 , loc.location
	 , inv.quantity_onhand	 
	 , o.quantity_order
	 , opd.lot_number
	 , SUM(opd.quantity_plan) quantity_plan
	 , SUM(opd.quantity_stage) quantity_stage
	 , SUM(opd.quantity_pack) quantity_pack
	 , SUM(opd.quantity_pick) quantity_pick
	 , SUM(opd.quantity_load) quantity_load
	 , SUM(opd.quantity_ship) quantity_ship	 
FROM dbo.t_wms_outbound_pick_detail AS opd 
INNER JOIN dbo.t_wms_outbound_pick_master AS opm ON opd.outbound_pick_master_id = opm.outbound_pick_master_id 
INNER JOIN cte_outbound_order AS o ON opm.outbound_order_master_id = o.outbound_order_master_id AND opd.wh_item_master_id = o.wh_item_master_id
INNER JOIN cte_inventory AS inv ON o.wh_master_id = inv.wh_master_id AND opd.wh_item_master_id = inv.wh_item_master_id
INNER JOIN dbo.t_wms_location AS loc ON opd.location_id = loc.location_id
GROUP BY o.outbound_order_number, o.wh_name, o.item_number, o.dg_code, o.item_description, o.uom, loc.location, inv.quantity_onhand, o.quantity_order, opd.lot_number

GO
