CREATE VIEW [dbo].[v_wms_outbound_sum_pick_detail_by_serial]
AS
SELECT obMS.outbound_order_master_id
	,obMS.outbound_order_number
	,obMS.wh_master_id
	,wh.wh_id
	,obMS.owner_id
	,obMS.load_id
	,obMS.order_status
	,obMS.order_type
	,pickMS.outbound_pick_master_id
	,pickDT.location_id
	,loc.location
	,pickDT.wh_item_master_id
	,item.item_number
	,item.description
	,item.price
	,item.grade
	,item.category_id
	,cate.item_category
	,obDT.item_uom_id
	,uom.uom
	,uom.uom_prompt
	,uom.conversion_factor
	,pickDT.parent_lpn
	,pickDT.lpn
	,pickDT.lot_number
	,pickDT.expiry_date
	,pickDT.attribute1
	,pickDT.attribute2
	,pickDT.attribute3
	,pickDT.attribute4
	,pickDT.attribute5
	,pickDT.is_override
	,pickDT.serial_number
	,obDT.default_item_status
	,pickDT.pick_location_id
	,pickLoc.location			AS pick_location
	,pickdt.pick_to_parent_lpn
	,pickDT.pick_to_lpn
	,ISNULL(pickDT.quantity_plan ,0) AS quantity_plan 
	,ISNULL(pickDT.quantity_pick ,0) AS quantity_pick 
	,ISNULL(pickDT.quantity_pack ,0) AS quantity_pack 
	,ISNULL(pickDT.quantity_load ,0) AS quantity_load 
	,ISNULL(pickDT.quantity_stage,0) AS quantity_stage
	,ISNULL(pickDT.quantity_ship ,0) AS quantity_ship 
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_item_uom uom on obDT.item_uom_id = uom.item_uom_id
INNER JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
											AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
											AND ISNULL(pickDT.serial_number,'') <> ''
INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id
LEFT JOIN t_wms_wh_item whItem on pickDT.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
LEFT JOIN t_wms_category cate on item.category_id = cate.category_id
LEFT JOIN t_wms_location loc on pickDT.location_id = loc.location_id
LEFT JOIN t_wms_location pickLoc on pickDT.pick_location_id = pickLoc.location_id



