CREATE VIEW [dbo].[v_wms_report_order_pick_list]
AS
WITH cte_item_master AS 
(
	SELECT itmw.wh_item_master_id
		 , itm.item_master_id
		 , itm.item_number
		 , itm.description
		 , itm.dg_code
		 , itmu.item_uom_id
		 , itmu.uom
		 , itmu.uom_prompt
	FROM dbo.t_wms_item AS itm 
	INNER JOIN dbo.t_wms_wh_item AS itmw ON itm.item_master_id = itmw.item_master_id 
	INNER JOIN dbo.t_wms_item_uom AS itmu ON itm.item_master_id = itmu.item_master_id
), cte_inventory AS
(
	SELECT wh_master_id
		 , wh_item_master_id
		 , ISNULL(SUM(quantity), 0) AS quantity_onhand
	FROM dbo.t_wms_inventory AS inv
	GROUP BY wh_master_id, wh_item_master_id
), cte_location_pick AS
(
	SELECT opd.outbound_pick_detail_id
		 , loc.location
		 , locp.location AS pick_location
		 , locs.location AS staging_location
	FROM dbo.t_wms_outbound_pick_detail AS opd 
	INNER JOIN dbo.t_wms_location AS loc ON opd.location_id = loc.location_id 
	INNER JOIN dbo.t_wms_location AS locp ON opd.pick_location_id = locp.location_id 
	INNER JOIN dbo.t_wms_location AS locs ON opd.staging_location_id = locs.location_id
)
SELECT om.outbound_order_number
	 , wh.wh_id
	 , wh.wh_name
	 --Bill to
	 , om.bill_to_code
	 , om.bill_to_name
	 , om.bill_to_address_line_1
	 , om.bill_to_address_line_2
	 , om.bill_to_address_line_3
	 , om.bill_to_city
	 , om.bill_to_province
	 , om.bill_to_postal_code
	 , om.bill_to_country
	 , om.bill_to_country_name
	 -- Ship to
	 , om.ship_to_code
	 , om.ship_to_name
	 , om.ship_to_addr_line_1
	 , om.ship_to_addr_line_2
	 , om.ship_to_addr_line_3
	 , om.ship_to_city
	 , om.ship_to_province
	 , om.ship_to_postal_code
	 , om.ship_to_country_code
	 , om.ship_to_country_name
	 -- Customer
	 , om.customer_code
	 , om.customer_name
	 , om.customer_order_number
	 , om.customer_purchase_order
	 , om.cus_contact
	 -- Detail
	 , opd.pick_line_number
	 , om.order_date
	 , loc_p.location
	 , NULL AS rel
	 , itm.item_number
	 , itm.description
	 , itm.uom
	 , opd.lot_number
	 , NULL AS reserved
	 , NULL AS manufacturer
	 , NULL AS manufacturer_item
	 , ISNULL(inv.quantity_onhand, 0) AS quantity_onhand
	 , od.quantity_order
	 , opd.quantity_pick
	 , od.quantity_order - opd.quantity_pick AS qty_back_order
FROM dbo.t_wms_outbound_pick_detail AS opd 
INNER JOIN dbo.t_wms_outbound_pick_master AS opm ON opd.outbound_pick_master_id = opm.outbound_pick_master_id 
INNER JOIN dbo.t_wms_outbound_master AS om ON opm.outbound_order_master_id = om.outbound_order_master_id 
INNER JOIN dbo.t_wms_outbound_detail AS od ON om.outbound_order_master_id = od.outbound_order_master_id AND opd.outbound_order_detail_id = od.outbound_order_detail_id 
INNER JOIN cte_location_pick AS loc_p ON opd.outbound_pick_detail_id = loc_p.outbound_pick_detail_id 
INNER JOIN cte_item_master AS itm ON opd.wh_item_master_id = itm.wh_item_master_id AND od.item_master_id = itm.item_master_id AND od.item_uom_id = itm.item_uom_id 
INNER JOIN cte_inventory AS inv ON om.wh_master_id = inv.wh_master_id AND opd.wh_item_master_id = inv.wh_item_master_id 
INNER JOIN dbo.t_wms_wh AS wh ON om.wh_id = wh.wh_id
GO
/****** Object:  View [dbo].[v_wms_pallet_return_export]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_pallet_return_export]
AS
SELECT        obMS.ship_date_actual, obMS.outbound_order_number, obMS.customer_code, obMS.customer_name, obMS.ship_to_name, 
                         obDT.sum_quantity_order AS quantity_ship, carr.carrier_code, item.item_number, pl.quantity_pallet, pl.quantity_return, pl.return_date, '' AS blank_return, 
                         '' AS blank_return_date, '' AS blank_create_by, '' AS blank_remark, pl.outbound_order_number AS Expr1, pl.customer_id, pl.owner_id, pl.carrier_id AS Expr2, 
                         pl.wh_item_master_id, pl.wh_master_id AS Expr3, whItem.wh_master_id
FROM            dbo.t_mod_cbd_pallet AS pl LEFT OUTER JOIN
                         dbo.t_wms_wh_item AS whItem ON pl.wh_item_master_id = whItem.wh_item_master_id LEFT OUTER JOIN
                         dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id LEFT OUTER JOIN
                         dbo.t_wms_outbound_master AS obMS ON pl.outbound_order_number = obMS.outbound_order_number LEFT OUTER JOIN
                             (SELECT        dt.outbound_order_master_id, SUM(dt.quantity_order / u.conversion_factor) AS sum_quantity_order
                               FROM            dbo.t_wms_outbound_detail AS dt LEFT OUTER JOIN
                                                         dbo.t_wms_wh_item AS wItem ON dt.wh_item_master_id = wItem.wh_item_master_id LEFT OUTER JOIN
                                                         dbo.t_wms_item AS it ON wItem.item_master_id = it.item_master_id LEFT OUTER JOIN
                                                         dbo.t_wms_item_uom AS u ON it.item_master_id = u.item_master_id AND u.sequence = 2 AND u.is_active = 'YES'
                               GROUP BY dt.outbound_order_master_id) AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id LEFT OUTER JOIN
                         dbo.t_wms_carrier AS carr ON pl.carrier_id = carr.carrier_id
WHERE        (obMS.order_type = 'SO')


GO
