CREATE VIEW [dbo].[v_wms_picking_slip_report]
--====================================================================================================
-- 2020-09-18	NUI		Add field barcode_service
--====================================================================================================
AS
	SELECT z.zone AS zone
		 , loc.location AS location_name
		 , item.item_number AS item_number
		 , item.description AS item_description
		 , R1_detail.location_id
		 , R1_detail.wh_item_master_id
		 , R1_detail.lot_number
		 , R1_detail.expiry_date
		 , R1_detail.qty
		 , R1_detail.outbound_order_master_id	
		 , CONVERT(VARCHAR(36),R1_detail.outbound_order_master_id) as str_outbound_order_master_id	
		 , R2_header.customer_route
		 , R2_header.R2_header_outbound_order_master_id
		 , R2_header.outbound_order_number
		 , R2_header.delivery_date_plan
		 , R2_header.customer_code
		 , R2_header.customer_name
		 , R2_header.customer_address
		 , R2_header.order_note
		 , R2_header.customer_order_number
		 , CONVERT(INT,R1_detail.line_number) AS line_number
		 , R2_header.order_type
		 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
	FROM (SELECT t_ob_pick_detail.location_id
			   , t_ob_pick_detail.wh_item_master_id
			   , t_ob_pick_detail.lot_number
			   , t_ob_pick_detail.expiry_date
			   , SUM(t_ob_pick_detail.quantity_plan) AS qty
			   , t_ob_detail.outbound_order_master_id
			   , t_ob_detail.line_number
		  FROM dbo.t_wms_outbound_pick_detail AS t_ob_pick_detail 
		  LEFT OUTER JOIN dbo.t_wms_outbound_detail AS t_ob_detail ON t_ob_detail.outbound_order_detail_id = t_ob_pick_detail.outbound_order_detail_id
		  GROUP BY t_ob_pick_detail.location_id
				 , t_ob_pick_detail.wh_item_master_id
				 , t_ob_pick_detail.lot_number
				 , t_ob_pick_detail.expiry_date
				 , t_ob_detail.outbound_order_master_id
				 , t_ob_detail.line_number)  AS R1_detail
	INNER JOIN t_wms_wh_item whItem ON R1_detail.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_location loc ON loc.location_id = R1_detail.location_id
	LEFT JOIN t_wms_zone_location zLoc ON zLoc.location_id = R1_detail.location_id
	LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id
	LEFT JOIN (SELECT ISNULL(cust.route_code,'') + '. ' + ISNULL(cust.route_name,'') AS customer_route
					, outbound_order_master_id AS R2_header_outbound_order_master_id
					, outbound_order_number
					, delivery_date_plan
					, cust.customer_code
					, cust.customer_name
					, customer_order_number
					, ISNULL(cus_addr_line_1, '') + ' ' + ISNULL(cus_addr_line_2, '') + ' ' + ISNULL(cus_addr_line_3, '') + ' ' + ISNULL(cus_city, '') + ' ' + ISNULL(cus_province, '') + ' ' + ISNULL(cus_postal_code, '') AS customer_address
					, ship_to_description AS order_note
					, order_type
				FROM dbo.t_wms_outbound_master AS t_ob_master
				LEFT JOIN t_wms_customer cust ON t_ob_master.customer_id = cust.customer_id) AS R2_header ON R1_detail.outbound_order_master_id = R2_header.R2_header_outbound_order_master_id
 
GO
