                         dbo.t_wms_inbound_detail.expiry_date, dbo.t_wms_inbound_detail.serial_number, dbo.t_wms_inbound_detail.user_def1 AS detail_udf1, 
                         dbo.t_wms_inbound_detail.user_def2 AS detail_udf2, dbo.t_wms_inbound_detail.user_def3 AS detail_udf3, dbo.t_wms_inbound_detail.user_def4 AS detail_udf4, 
