INNER JOIN dbo.t_wms_wh ON dbo.t_wms_inbound_master.wh_master_id = dbo.t_wms_wh.wh_master_id 
INNER JOIN dbo.t_wms_owner ON dbo.t_wms_item.owner_id = dbo.t_wms_owner.owner_id AND dbo.t_wms_inbound_master.owner_id = dbo.t_wms_owner.owner_id



