CREATE VIEW [dbo].[v_wms_receipt_detail_summary]
AS
WITH ReciptDetailCTE AS
(
	SELECT receipt_header_id 
		,inbound_order_detail_id
		,location_received
		,parent_lpn
		,lpn
		,receipt_item_status 
		,lot_number
		,mfg_date
		,expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,receive_date
		,SUM(quantity_received) AS quantity_received
	FROM t_wms_receipt_detail
	GROUP BY receipt_header_id 
		,inbound_order_detail_id
		,location_received
		,parent_lpn
		,lpn
		,receipt_item_status 
		,lot_number
		,mfg_date
		,expiry_date
		,serial_number
		,attribute1
		,attribute2
		,attribute3
		,attribute4
		,attribute5
		,receive_date
)

SELECT recHD.receipt_header_id
	, recHD.receipt_number
	, recHD.receipt_status
	, ibDT.inbound_order_detail_id
	, ibDT.line_number
	, ibDT.wh_item_master_id
	, ibDT.item_master_id
	, ibDT.item_number
	, recDT.receipt_item_status
	, recDT.quantity_received
	, ibDT.item_uom_id
	, ibDT.uom
	, recDT.location_received
	, recDT.parent_lpn
	, recDT.lpn
	, recDT.lot_number 
	, recDT.mfg_date
	, recDT.expiry_date
	, recDT.serial_number
	, recDT.attribute1
	, recDT.attribute2
	, recDT.attribute3
	, recDT.attribute4
	, recDT.attribute5 
	, recDT.receive_date
	, ibDT.user_def1
	, ibDT.user_def2
	, ibDT.user_def3
	, ibDT.user_def4
	, ibDT.user_def5
	, ibDT.user_def6
	, ibDT.user_def7
	, ibDT.user_def8
	, ibDT.user_def9
	, ibDT.user_def10
FROM ReciptDetailCTE recDT
INNER JOIN dbo.t_wms_inbound_detail ibDT ON recDT.inbound_order_detail_id = ibDT.inbound_order_detail_id 
INNER JOIN t_wms_receipt_header recHD ON recDT.receipt_header_id = recHD.receipt_header_id
GO
/****** Object:  View [dbo].[v_wms_receipt_detail_v2]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE view [dbo].[v_wms_receipt_detail_v2] as

select 
receipt_detail_id
,rec_d.receipt_header_id
,rec_d.inbound_order_master_id
,rec_d.inbound_order_number
,rec_d.inbound_order_detail_id
,rec_d.wh_item_master_id
--,rec_d.item_number
,rec_d.quantity_received
,rec_d.item_uom_id
,rec_d.receipt_item_status
,rec_d.location_received
,rec_d.lpn
,rec_d.parent_lpn
,rec_d.lot_number
,convert(date,rec_d.expiry_date,112) as expiry_date
,rec_d.serial_number
,rec_d.attribute1
,rec_d.attribute2
,rec_d.attribute3
,rec_d.attribute4
,rec_d.attribute5
,rec_d.posting_date
,rec_d.create_date
,rec_d.create_by

,inb_d.line_number
,inb_d.quantity_order
,inb_d.over_receipt_allowed

,item.item_master_id
,item.item_number
,item.description as item_description

,uom.uom

,cate.category_id
,cate.item_category
,cate.description as category_description

from t_wms_receipt_detail as rec_d
inner join t_wms_receipt_header as rec_h on rec_d.receipt_header_id = rec_h.receipt_header_id
inner join t_wms_inbound_detail as inb_d on inb_d.inbound_order_detail_id = rec_d.inbound_order_detail_id
left join t_wms_item as item on item.item_master_id = inb_d.item_master_id
left join t_wms_item_uom as uom on uom.item_master_id = item.item_master_id and uom.primary_uom = 'YES'
left join t_wms_category as cate on cate.category_id = item.category_id
GO
