SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [dbo].[v_wms_receipt_display]
AS
SELECT 
	ibMs.inbound_order_master_id
	,ibMs.inbound_order_number
	,ibMs.wh_master_id
	,wh.wh_id
	,ibms.owner_id
	,own.owner_code
	,own.owner_name
	,rechd.receipt_number
	,item.item_number
	,item.description
	,ibDT.quantity_order		
	,SUM(ISNULL(recDT.quantity_received,0))	AS quantity_received
	,ISNULL(recDT.receipt_item_status,'')	AS receipt_item_status
	,ISNULL(recDT.item_uom_id,'')	AS item_uom_id
	,ISNULL(uom.uom,'')				AS uom
	,ISNULL(uom.uom_prompt,'')		AS uom_prompt
	,ISNULL(ibDT.lot_number,'')		AS lot_number
	,ISNULL(ibDT.expiry_date,'')	AS expiry_date
FROM t_wms_inbound_master ibMs
LEFT JOIN t_wms_inbound_detail ibDT on ibMs.inbound_order_master_id = ibDt.inbound_order_master_id
LEFT JOIN t_wms_wh wh on ibMs.wh_master_id = wh.wh_master_id
LEFT JOIN t_wms_owner own on ibMs.owner_id = own.owner_id
LEFT JOIN t_wms_wh_item whItem on ibDt.wh_item_master_id = whItem.wh_item_master_id
LEFT JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
LEFT JOIN t_wms_receipt_header recHD on ibMs.inbound_order_master_id = recHD.inbound_order_master_id
LEFT JOIN t_wms_receipt_detail recDT on recHD.receipt_header_id = recDT.receipt_header_id 
									AND ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
LEFT JOIN t_wms_item_uom uom on ibDT.item_uom_id = uom.item_uom_id
GROUP BY ibMs.inbound_order_master_id
	,ibMs.inbound_order_number
	,ibMs.wh_master_id
	,wh.wh_id
	,ibms.owner_id
	,own.owner_code
	,own.owner_name
	,rechd.receipt_number
	,item.item_number
	,item.description	
	,ibDt.quantity_order
	,recDT.receipt_item_status
	,recDT.item_uom_id
	,uom.uom
	,uom.uom_prompt
	,ibDT.lot_number
	,ibDT.expiry_date







GO
