SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_receipt_lpn_display]
AS
(
	SELECT DISTINCT 
		   ibMS.inbound_order_master_id
		 , ibMS.inbound_order_number
		 , ibMS.wh_master_id
		 , wh.wh_id
		 , ibMS.owner_id
		 , own.owner_code
		 , ibDT.wh_item_master_id
		 , item.item_master_id
		 , item.item_number
		 , item.description
		 , ibLPN.lot_number
		 , ''							AS vch_mfg_date
		 , getdate()					AS mfg_date
		 , ibLPN.expiry_date
		 , ibLPN.lpn
		 , uom.uom_prompt
		 , uom.uom
		 , ISNULL(ibLPN.quantity,0)				AS lpn_qty
		 , ISNULL(ibLPN.quantity_receive,0)		AS lpn_qty_receive
	FROM t_wms_inbound_master ibMS
	LEFT JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	LEFT JOIN t_wms_inbound_lpn_detail ibLPN ON  ibDT.inbound_order_detail_id = ibLPN.inbound_order_detail_id
	LEFT JOIN t_wms_wh wh on ibMS.wh_master_id = wh.wh_master_id
	LEFT JOIN t_wms_owner own on ibMS.owner_id = own.owner_id
	LEFT JOIN t_wms_wh_item whItem on ibDT.wh_item_master_id = whItem.wh_item_master_id
	LEFT JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_uom uom on ibDT.item_uom_id = uom.item_uom_id
)


