/****** Object:  View [dbo].[v_wms_report_adjust_out]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[v_wms_report_adjust_out]
AS
SELECT tLog.tran_id
, tLog.location as location
, item.item_number
, tLog.lot_number
, tLog.expiry_date
, tLog.serial_number
, item.description
, tLog.reason_code
, tLog.quantity
, tLog.start_tran_datetime
, dbo.t_wms_outbound_delivery.delivery_date
, dbo.t_wms_outbound_delivery.delivery_number
FROM dbo.t_com_tran_log tLog
INNER JOIN t_wms_owner own ON tLog.to_owner = own.owner_code
INNER JOIN dbo.t_wms_item item ON tLog.item_number = item.item_number AND own.owner_id = item.owner_id
LEFT OUTER JOIN dbo.t_wms_outbound_delivery ON tLog.serial_number = dbo.t_wms_outbound_delivery.serial_number
WHERE tLog.tran_type = 'INV_ADJUST'
AND tLog.sub_tran_type IN ('ADJUST_OUT_NOT_ERP','ADJUST_OUT_TO_ERP','HIM_ADJUST_OUT')
GO
