SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 

CREATE VIEW [dbo].[v_wms_outbound_detail]
AS
SELECT obMS.outbound_order_master_id
	, CONVERT(VARCHAR(36),obMS.outbound_order_master_id) as str_outbound_order_master_id
	, obMS.wh_master_id
	, wh.wh_id
	, obMS.outbound_order_number
	, obMS.owner_id
	, own.owner_code
	, obMS.order_type
	, obMS.order_status
	, obMS.customer_code
	, obMS.customer_name
	, obMS.customer_code + ' ' + obMS.customer_name AS customer_code_name
	, obMS.delivery_date_plan 
	, obMS.ship_date_plan
	, obMS.ship_date_actual
	, CONVERT(nvarchar(10), obMS.ship_date_actual, 112) AS ship_date_actual_filter
	, obMS.load_id
	, obDT.outbound_order_detail_id
	, obDT.line_number
	, cate.category_id
	, cate.item_category
	, obDT.wh_item_master_id
	, item.item_master_id
	, item.item_number
	, item.description as item_description
	, obDT.quantity_order
	, ISNULL(obDT.quantity_pick, 0) AS quantity_pick
	, ISNULL(obDT.quantity_load, 0) AS quantity_load
	, obDT.quantity_ship 
	, obDT.quantity_ship * obDT.price AS total_price
	, obDT.price
	, obDT.grade
	, obDT.default_item_status 
	, obDT.item_uom_id
	, uom.uom
	, uom.uom_prompt
	, obDT.item_status
	, obDT.lpn
	, obDT.lot_number
	, obDT.serial_number  
	, obDT.expiry_date
	, obDT.customer_item_code
	, obDT.dangerous_good_flag 
	, obDT.user_def1
	, obDT.user_def2
	, obDT.user_def3
	, obDT.user_def4
	, obDT.user_def5
	, obDT.user_def6
	, obDT.user_def7	
	, obDT.create_date
	, obDT.create_by
	, obDT.rowversion
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON  obDT.outbound_order_master_id = obMS.outbound_order_master_id 
INNER JOIN t_wms_wh wh ON obMS.wh_master_id = wh.wh_master_id 
INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
INNER JOIN t_wms_wh_item whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id
INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
INNER JOIN t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
 

