	,wh_master_id
	,wh_id
	,zone
	,[location]
	,wh_item_master_id
	,item_master_id
	,item_number
	,item_description
	,lot_number
	,expiry_date
	,attribute1
	,attribute2
	,attribute3
	,attribute4
	,attribute5
	,min_qty
