/****** Object:  View [dbo].[v_wms_report_count_reconcile_external]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE VIEW [dbo].[v_wms_report_count_reconcile_external]
AS
-- ***majority use status get data from store item and other get from cont reconcile
SELECT  vCountExternal.inv_status 
	, tCountPlanMSExt.customer_code
	, tCountPlanMSExt.customer_name
	, isnull(tCountPlanMSExt.customer_code,'') + ' - ' + isnull(tCountPlanMSExt.customer_name,'') as customer_code_name
	, vCountExternal.item_number
	, vCountExternal.item_description
	, vCountExternal.lot_number as lot
	, vCountExternal.[expiry_date]	
	, convert(datetime,vCountExternal.[expiry_date]) as datetime_expiry_date
	, vCountExternal.serial_number
	, (case vCountExternal.inv_status when 'Used' then convert(float,1) else isnull(vCountExternal.count_qty,0) end) as count_qty
	, vCountExternal.stock_qty as expect_qty
	,((case vCountExternal.inv_status when 'Used' then convert(float,1) else isnull(vCountExternal.count_qty,0) end) - vCountExternal.stock_qty) AS Discrepancy
	, vCountExternal.delivery_no as outbound_order_number
	,(case vCountExternal.inv_status when 'Used' then vCountExternal.store_delivery_date else vCountExternal.delivery_date end) as delivery_date
    , tCountRecExt.create_by
	, tCountRecExt.create_date 
    , tCountPlanMSExt.hospital_signature
	, tCountPlanMSExt.doctor_name
	, tCountPlanMSExt.hospital_position
	, tCountPlanMSExt.staff_signature
	, tCountPlanMSExt.staff_name
	, tCountPlanMSExt.staff_position
	, tCountPlanMSExt.count_id
	, tCountPlanMSExt.count_master_id
	, tCountPlanMSExt.close_date
	, tCountPlanMSExt.close_by
FROM (SELECT loc.location
			,cus.customer_name
			,tCount.count_master_id
			,tCount.location_id 
			,tCount.item_number
			,tCount.item_description
			,(CASE ISNULL(store.store_item_status_id,'')  WHEN '' THEN (CASE WHEN ISNULL(tCount.count_qty,0) = 0 THEN 'Missing CSM'  
			  WHEN ISNULL(planDT.count_master_id,'') = '' AND ISNULL(tCount.count_qty,0) > 0 THEN 'Unknown' ELSE planDT.inv_status END)
		      ELSE 'Used' END) AS inv_status
			,tCount.lot_number
			,tCount.[expiry_date]
			,tCount.serial_number
			,ISNULL(planDT.stock_qty,0) AS stock_qty
			,ISNULL(tCount.count_qty,0) AS count_qty
			,ISNULL(tCount.count_qty,0) - ISNULL(planDT.stock_qty,0) AS diff_qty
			,tCount.outbound_order_number AS delivery_no	
			,store.user_def1 AS pateint
			,store.user_def2 AS doctor
			,store.use_date
			,store.user_def3 AS budget
			,store.memo
			,tCount.delivery_date
			,store.[delivery_date] as store_delivery_date
			,tCount.item_category
			,tCount.item_category_description
		FROM (SELECT count_master_id
					,location_id 
					,item_number
					,item_description
					,item_category
					,item_category_description
					,lot_number
					,[expiry_date] 
					,serial_number
					,ISNULL(count_qty,0)	AS count_qty
					, outbound_order_number 
					, delivery_date
				FROM t_wms_count_plan_detail_external
				UNION
				SELECT count_master_id
					,location_id
					,item_number
					,item_description
					,item_category
					,item_category_description
					,lot	AS lot_number
					,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
					,serial_number
					,ISNULL(count_qty,0)	AS count_qty
					, outbound_order_number 
					, delivery_date
				FROM t_wms_count_reconcile_external
				) tCount
		LEFT JOIN t_wms_count_plan_detail_external planDT ON tCount.count_master_id = planDT.count_master_id
														  AND tCount.location_id = planDT.location_id
														  AND tCount.item_number = planDT.item_number
														  AND tCount.lot_number = planDT.lot_number
														  AND tCount.expiry_date = planDT.expiry_date
														  AND tCount.serial_number = planDT.serial_number
		LEFT JOIN t_wms_customer_location cus_loc ON tCount.location_id = cus_loc.location_id
		LEFT JOIN t_wms_customer cus ON cus_loc.customer_id = cus.customer_id
		LEFT JOIN t_wms_location loc ON cus_loc.location_id = loc.location_id
		--LEFT JOIN t_wms_store_item_status store ON tCount.serial_number = store.serial_number
		LEFT JOIN (SELECT store_item_status_id
						,user_def1
						,user_def2
						,use_date
						,user_def3
						,memo
						,delivery_date
						,serial_number
						,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
					FROM t_wms_store_item_status
					) store ON store.serial_number = tCount.serial_number and is_max = 1
		) AS vCountExternal
LEFT JOIN dbo.t_wms_count_plan_master_external tCountPlanMSExt ON vCountExternal.count_master_id = tCountPlanMSExt.count_master_id
LEFT JOIN dbo.t_wms_count_reconcile_external tCountRecExt ON vCountExternal.count_master_id = tCountRecExt.count_master_id
															AND vCountExternal.serial_number = tCountRecExt.serial_number

GO
