/****** Object:  View [dbo].[v_wms_unbilled_usage]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[v_wms_unbilled_usage]
AS
SELECT 
cus.customer_code,cus.customer_name,sn.item_category,sn.category_id,sn.cate_description as category_desc
,sn.item_number,sn.[description] as item_description,sn.lot_number as lot
,store.use_date,sn.quantity as qty,c_pri.price,sn.quantity * c_pri.price as total
,store.create_date as count_date
FROM v_wms_inventory_data_by_serial sn
LEFT JOIN t_wms_customer_location c_loc on c_loc.location_id = sn.location_id
LEFT JOIN t_wms_customer cus on cus.customer_id = c_loc.customer_id
LEFT JOIN t_wms_customer_price c_pri on c_pri.customer_id = c_loc.customer_id and c_pri.wh_item_master_id = sn.wh_item_master_id
LEFT JOIN (	select * 
			from (	select 
					serial_number,use_date,convert(date,create_date) as create_date
					,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
					from t_wms_store_item_status
					where t_wms_store_item_status.inventory_status = 'USED') as tmp1 
			where tmp1.is_max = 1 ) as store on store.serial_number = sn.serial_number
WHERE sn.inv_status = 'USED'




