			,CONVERT(VARCHAR,expiry_date,112) AS expiry_date
			,serial_number
			,ISNULL(count_qty,0)	AS count_qty
			, create_by as count_by
			, create_date as count_date
			, outbound_order_number --unknown must get this
			, delivery_date --unknown must get this
		FROM t_wms_count_reconcile_external
		) tCount
LEFT JOIN t_wms_count_plan_detail_external planDT ON tCount.count_master_id = planDT.count_master_id
												  AND tCount.location_id = planDT.location_id
												  AND tCount.item_number = planDT.item_number
												  AND tCount.lot_number = planDT.lot_number
												  AND tCount.expiry_date = planDT.expiry_date
												  AND tCount.serial_number = planDT.serial_number
--LEFT JOIN t_wms_store_item_status store ON tCount.serial_number = store.serial_number
LEFT JOIN (SELECT store_item_status_id
				,user_def1
				,user_def2
				,use_date
				,user_def3
				,memo
				,delivery_date
				,serial_number
				,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
			FROM t_wms_store_item_status
) store ON store.serial_number = tCount.serial_number and is_max = 1
)count_merge
LEFT JOIN dbo.t_wms_count_plan_master_external count_plan ON count_plan.count_master_id = count_merge.count_master_id
WHERE inv_status = 'Unknown' 


GO
/****** Object:  View [dbo].[v_wms_outbound_order_report]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 

 
CREATE VIEW [dbo].[v_wms_outbound_order_report]
AS
SELECT obMS.wh_master_id
, wh.wh_id
, obMS.outbound_order_master_id
, CONVERT(VARCHAR(36),obMS.outbound_order_master_id) AS str_outbound_order_master_id
, obMS.outbound_order_number
, obMS.order_type
, obMS.order_status
, obMS.ship_date_actual
, obMS.truck_no
, obMS.customer_code
, obMS.customer_name
, obMS.ship_to_code
, obMS.ship_to_name
, obDT.line_number
, item.item_number
, item.description AS item_description
, NULL AS [SECTORS/USERS]
, ISNULL(obDT.quantity_order, 0) AS quantity_order
, ISNULL(obDT.quantity_ship, 0) AS quantity_ship
, ISNULL(obDT.quantity_pick, 0) AS quantity_pick
, ISNULL(obDT.quantity_load, 0) AS quantity_load
, obDT.expiry_date
, obDT.lot_number
, obDT.lpn
, obDT.serial_number
, obMS.order_date
, obDT.default_item_status
, own.owner_code
, own.owner_id
, obMS.load_id
, obMS.customer_purchase_order AS [customer_purchase_order]
, obMS.customer_id AS [customer_id]
, obMS.cus_province AS [province]
, obMS.delivery_date_plan AS [delivery_date_plan]
, obMS.loading_date_plan AS [loading_date_plan]
, obMS.customer_order_number AS [customer_order_number]
, item.category_id
FROM dbo.t_wms_outbound_master AS obMS 
INNER JOIN dbo.t_wms_outbound_detail AS obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id 
INNER JOIN dbo.t_wms_owner AS own ON own.[owner_id] = obMS.[owner_id] 
INNER JOIN dbo.t_wms_wh AS wh ON obMS.wh_master_id = wh.wh_master_id
INNER JOIN dbo.t_wms_wh_item AS whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id 
INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 

GO
/****** Object:  View [dbo].[v_wms_report_inven_aging]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_inven_aging]
AS
SELECT     
  wh.wh_id
, ISNULL(tLoc.location, '') AS location
, ISNULL(tLoc.zone, '') AS zone
, ISNULL(tItem.item_number, '') AS item_number
, ISNULL(tItem.description, '') AS description
, ISNULL(tItem.grade, '') AS grade
, ISNULL(tItem.dg_code, '') AS dg_code
, ISNULL(tItem.item_category, '') AS item_category
, inv.lpn
, inv.parent_lpn
, inv.receive_date
, Convert(varchar(8),inv.receive_date,112)	AS receive_date_filter
, invStatus.inv_status
, DATEDIFF(DAY, inv.receive_date, GETDATE()) AS aging
, SUM(inv.quantity) AS quantity
, tItem.uom
, tItem.max_qty
, tItem.min_qty
FROM dbo.t_wms_inventory AS inv 
LEFT OUTER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
LEFT OUTER JOIN dbo.t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id 
LEFT OUTER JOIN (SELECT 
					loc.location_id
					, loc.location
					, ISNULL(zone.zone, '') AS zone
                FROM dbo.t_wms_location AS loc 
				LEFT OUTER JOIN dbo.t_wms_zone_location AS zoneLoc ON zoneLoc.location_id = loc.location_id 
				LEFT OUTER JOIN dbo.t_wms_zone AS zone ON zoneLoc.zone_id = zone.zone_id
			    ) AS tLoc ON inv.location_id = tLoc.location_id 
LEFT OUTER JOIN (SELECT     
					whItem.wh_item_master_id
					, item.item_number
					, item.description
					, item.grade
					, item.dg_code
					, cate.item_category
					, uom.uom
					, item.max_qty
					, item.min_qty
                FROM dbo.t_wms_wh_item AS whItem 
				LEFT OUTER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
				LEFT OUTER JOIN dbo.t_wms_item_uom AS uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
				LEFT OUTER JOIN dbo.t_wms_category cate ON item.category_id = cate.category_id
			   ) AS tItem ON inv.wh_item_master_id = tItem.wh_item_master_id
GROUP BY wh.wh_id
, tLoc.location
, tLoc.zone
, tItem.item_number
, tItem.description
, tItem.grade
, tItem.dg_code
, tItem.item_category
, inv.lpn
, inv.parent_lpn
, inv.receive_date
, invStatus.inv_status
, tItem.uom
, tItem.max_qty
, tItem.min_qty

GO
