CREATE VIEW [dbo].[v_wms_outbound_rel_by_load_pickdetail]
AS
SELECT        pick.is_override, loc.location, item.item_number, det.item_description, cat.item_category, uom.uom, det.grade, det.price, pick.parent_lpn, pick.lpn, pick.lot_number, 
                         pick.expiry_date, mas.wh_master_id, mas.load_id, SUM(pick.quantity_plan) AS quantity_plan, SUM(pick.quantity_pick) AS quantity_pick, 
                         SUM(pick.quantity_plan - pick.quantity_pick) AS quantity_remain, SUM(pick.quantity_pack) AS quantity_pack, SUM(pick.quantity_stage) AS quantity_stage, 
                         SUM(pick.quantity_load) AS quantity_load, MAX(pick.create_date) AS create_date, MAX(pick.create_by) AS create_by
FROM            dbo.t_wms_outbound_pick_detail AS pick INNER JOIN
                         dbo.v_wms_location AS loc ON pick.location_id = loc.location_id INNER JOIN
                         dbo.t_wms_outbound_detail AS det ON pick.outbound_order_detail_id = det.outbound_order_detail_id INNER JOIN
                         dbo.t_wms_outbound_master AS mas ON det.outbound_order_master_id = mas.outbound_order_master_id INNER JOIN
                         dbo.t_wms_item_uom AS uom ON det.item_uom_id = uom.item_uom_id INNER JOIN
                         dbo.t_wms_wh_item ON det.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id INNER JOIN
                         dbo.t_wms_item AS item ON dbo.t_wms_wh_item.item_master_id = item.item_master_id INNER JOIN
                         dbo.t_wms_category AS cat ON item.category_id = cat.category_id
GROUP BY pick.is_override, loc.location, item.item_number, det.item_description, cat.item_category, uom.uom, det.grade, det.price, pick.parent_lpn, pick.lpn, pick.lot_number, 
                         pick.expiry_date, mas.wh_master_id, mas.load_id



