CREATE VIEW [dbo].[v_Order_Details]
AS
SELECT        TOP (100) PERCENT dbo.v_wms_outbound_master.customer_order_number AS [Invoice no], dbo.v_wms_outbound_master.cus_province, dbo.t_wms_carrier.carrier_name, 
                         dbo.v_wms_outbound_detail.line_number, dbo.v_wms_outbound_detail.item_number, dbo.v_wms_outbound_detail.quantity_order, dbo.v_wms_outbound_detail.quantity_pick, 
                         dbo.v_wms_outbound_detail.quantity_load, dbo.v_wms_outbound_detail.quantity_ship, dbo.v_wms_outbound_detail.uom_prompt, dbo.v_wms_outbound_detail.item_category, 
                         dbo.v_wms_outbound_detail.item_status, dbo.v_wms_outbound_detail.lot_number, dbo.v_wms_outbound_detail.item_description, dbo.v_wms_outbound_detail.expiry_date, 
                         dbo.v_wms_outbound_master.loading_date_actual, dbo.v_wms_outbound_master.delivery_date_actual, dbo.v_wms_outbound_master.user_def7 AS Consignment_No, 
                         dbo.v_wms_outbound_master.user_def2 AS Order_Reason, dbo.v_wms_outbound_master.delivery_date_plan, dbo.v_wms_outbound_master.ship_date_actual, 
                         dbo.v_wms_outbound_master.customer_code_name, dbo.v_wms_outbound_master.order_type, dbo.v_wms_outbound_master.order_status, dbo.v_wms_outbound_master.customer_name, 
                         dbo.v_wms_outbound_master.customer_code, dbo.v_wms_outbound_master.ship_date_plan, dbo.v_wms_outbound_master.outbound_order_number, dbo.v_wms_outbound_master.create_date, 
                         dbo.v_wms_outbound_master.close_date AS POD_Date, (CASE WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' THEN 'UPC' ELSE 'BKK' END) AS Area, 
                         (CASE WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         <= '14:00:00' THEN 'Morning Cut Off' WHEN dbo.t_wms_carrier.carrier_name LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         > '14:00:00' THEN 'Afternoon Cut Off' WHEN dbo.t_wms_carrier.carrier_name NOT LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         <= '11:00:00' THEN 'Morning Cut Off' WHEN dbo.t_wms_carrier.carrier_name NOT LIKE '%Kerry%' AND CONVERT(TIME, dbo.v_wms_outbound_master.create_date) 
                         > '11:00:00' THEN 'Afternoon Cut Off' ELSE 'Afternoon Cut Off' END) AS Cut_Off_Time, dbo.v_wms_outbound_master.user_def3 AS Remark_Cut_Off, dbo.t_wms_customer.route_code, 
                         dbo.t_wms_customer.route_name
FROM            dbo.t_wms_customer INNER JOIN
                         dbo.v_wms_outbound_master INNER JOIN
                         dbo.v_wms_outbound_detail ON dbo.v_wms_outbound_master.outbound_order_number = dbo.v_wms_outbound_detail.outbound_order_number ON 
                         dbo.t_wms_customer.customer_code = dbo.v_wms_outbound_master.customer_code RIGHT OUTER JOIN
                         dbo.t_wms_carrier ON dbo.v_wms_outbound_master.carrier_id = dbo.t_wms_carrier.carrier_id
GO
