CREATE VIEW [dbo].[v_wms_report_inventory_movent_tranfer]
AS
SELECT tExport.order_number
	 , tExport.host_record_id
	 , tExport.reference_number
	 , tExport.control_number
	 , tExport.create_date
     , tExport.user_def2
     , tExport.item_number
     , tExport.quantity
     , tExport.quantity_uom
     , tExport.tran_type
     , tExport.warehouse
     , tExport.location
     , tExport.to_location
     , dbo.t_wms_item.description
     , locFrom.erp_location AS erp_location_from
     , locTo.erp_location AS erp_location_to
     , tExport.owner
     , tExport.to_owner
FROM dbo.t_host_wms_trans_export tExport
INNER JOIN dbo.t_wms_location locFrom  ON tExport.location = locFrom.location 
INNER JOIN dbo.t_wms_location locTo ON tExport.to_location = locTo.location 
INNER JOIN dbo.t_wms_item ON tExport.item_number = dbo.t_wms_item.item_number
WHERE tExport.tran_type IN ('INV_MOVE')
