CREATE VIEW [dbo].[v_wms_report_inventory_outbound_tranfer]
AS
SELECT CASE WHEN t_host_wms_trans_export.order_number IS NOT NULL THEN t_host_wms_trans_export.order_number ELSE t_host_wms_trans_export.host_record_id END AS order_number
, dbo.t_host_wms_trans_export.create_date
, dbo.t_host_wms_trans_export.user_def2
, dbo.t_host_wms_trans_export.item_number
, dbo.t_host_wms_trans_export.quantity
, dbo.t_host_wms_trans_export.quantity_uom
, dbo.t_host_wms_trans_export.tran_type
, dbo.t_host_wms_trans_export.warehouse
, dbo.t_host_wms_trans_export.location
, dbo.t_host_wms_trans_export.to_location
, dbo.t_wms_item.description
, locMapERPFrom.erp_location AS erp_location_from
, locMapERPTo.erp_location AS erp_location_to
, dbo.t_host_wms_trans_export.host_record_id
, dbo.t_host_wms_trans_export.owner
, dbo.t_host_wms_trans_export.to_owner
FROM dbo.t_host_wms_trans_export 
INNER JOIN dbo.t_wms_location AS locMapERPFrom ON dbo.t_host_wms_trans_export.location = locMapERPFrom.location 
INNER JOIN dbo.t_wms_location AS locMapERPTo ON dbo.t_host_wms_trans_export.to_location = locMapERPTo.location 
INNER JOIN dbo.t_wms_item ON dbo.t_host_wms_trans_export.item_number = dbo.t_wms_item.item_number
