SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[v_wms_report_outbound_picking_ship]
AS
SELECT obMS.outbound_order_number, obMS.user_def2, obMS.order_date, obMS.ship_date_plan, obMS.ship_date_actual
	 --customer
	 , cus.customer_code, cus.customer_name
	 -- ship to
	 , obMS.ship_to_code, obMS.ship_to_name, obMS.ship_to_description
	 , obMS.ship_to_addr_line_1, obMS.ship_to_addr_line_2, obMS.ship_to_addr_line_3
	 , obMS.ship_to_city, obMS.ship_to_province, obMS.ship_to_postal_code
	 , obMS.ship_to_country_code, obMS.ship_to_country_name
	 , obMS.ship_to_contact, obMS.ship_to_phone, obMS.ship_to_fax, obMS.ship_to_email
	 -- transport
	 , trans.transport_by_code, trans.transport_by_name, trans.description
	 -- bom
	 , obDT.bom_item_number, obDT.bom_detail_quantity, obDT.bom_quantity_ship
	 --detail
	 , itm.item_number
	 , itm.description AS item_description
	 , uom.uom_prompt
	 , loc.location
	 , obDT.quantity_order
	 , SUM(ISNULL(pickDT.quantity_pick, 0)) quantity_pick	 
	 , ISNULL((SELECT TOP 1 barcode_service_url FROM t_com_config_barcode_service WHERE barcode_service_name = 'barcode_service' AND is_active = 'YES'), '') AS barcode_service
FROM t_wms_outbound_master obMS
INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
INNER JOIN t_wms_item itm ON obDT.item_master_id = itm.item_master_id
INNER JOIN t_wms_item_uom uom ON itm.item_master_id = uom.item_master_id AND obDT.item_uom_id = uom.item_uom_id
LEFT JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
LEFT JOIN t_wms_transport_by trans ON obMS.transport_by_code = trans.transport_by_code
LEFT JOIN t_wms_customer cus ON obMS.customer_id = cus.customer_id
LEFT JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
WHERE obMS.order_type <> 'Other' 
GROUP BY obMS.outbound_order_number, obMS.user_def2, obMS.order_date, obMS.ship_date_plan, obMS.ship_date_actual
	 , cus.customer_code, cus.customer_name
	 , obMS.ship_to_code, obMS.ship_to_name, obMS.ship_to_description
	 , obMS.ship_to_addr_line_1, obMS.ship_to_addr_line_2, obMS.ship_to_addr_line_3
	 , obMS.ship_to_city, obMS.ship_to_city, obMS.ship_to_province, obMS.ship_to_postal_code
	 , obMS.ship_to_country_code, obMS.ship_to_country_name
	 , obMS.ship_to_contact, obMS.ship_to_phone, obMS.ship_to_fax, obMS.ship_to_email
	 , trans.transport_by_code, trans.transport_by_name, trans.description
	 , obDT.bom_item_number, obDT.bom_detail_quantity, obDT.bom_quantity_ship
	 , itm.item_number, itm.description, uom.uom_prompt
	 , loc.location, obDT.quantity_order

GO
