/****** Object:  View [dbo].[v_wms_report_outbound_planning]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO










CREATE VIEW [dbo].[v_wms_report_outbound_planning]
AS

SELECT
	 whit.wh_item_master_id,item.item_master_id, item.item_number, item.[description] AS item_desc, item.min_qty,item.max_qty,ISNULL(CONVERT(int,item.user_def7),0) as LT
	
	,item_inv.qty_inv_f04,item_inv.qty_inv_p05
	,item_inv.qty_inv_f05_qc,item_inv.qty_inv_p05_qc
	,item_inv.qty_inv_f01,item_inv.qty_inv_p01
	,ISNULL(item_inv.qty_inv_total,0) as qty_inv_total

	,item_outb.qty_outb_so,0 as qty_outb_memo
	,ISNULL(item_outb.qty_outb_so,0) as qty_outb_sol

	,ISNULL(item_inv.qty_inv_total,0)-ISNULL(item_outb.qty_outb_so,0) as qty_sol_total

	,0 as qty_inb_opr,item_inb.qty_inb_po,item_inb.qty_inb_pd,item_outb.qty_outb_pd
	,(ISNULL(item_inv.qty_inv_total,0)-ISNULL(item_outb.qty_outb_so,0))+ISNULL(item_inb.qty_inb_po,0)+ISNULL(item_inb.qty_inb_pd,0)+ISNULL(item_outb.qty_outb_pd,0) as qty_remain_total

	,0 as qty_crit_min,0 as qty_crit_max,ISNULL(CONVERT(int,item_inv.qty_p07),0) as qty_p07,ISNULL(CONVERT(int,item_inv.qty_c01_c24),0) as qty_c01_c24,'' as remark
FROM  dbo.t_wms_item item
INNER JOIN dbo.t_wms_wh_item whit ON item.item_master_id=whit.item_master_id

OUTER APPLY
	(SELECT item_inv.qty_inv_f04,item_inv.qty_inv_p05
	,item_inv.qty_inv_f05_qc,item_inv.qty_inv_p05_qc
	,item_inv.qty_inv_f01,item_inv.qty_inv_p01
	,ISNULL(item_inv.qty_inv_f04+item_inv.qty_inv_p05+item_inv.qty_inv_f05_qc+item_inv.qty_inv_p05_qc+item_inv.qty_inv_f01+item_inv.qty_inv_p01,0) as qty_inv_total
	,item_inv.qty_p07,item_inv.qty_c01_c24
		FROM (
			    SELECT  SUM(CASE WHEN lomp.erp_location='F-04_ไม่ผ่านQC' THEN inve.quantity ELSE 0 END) as qty_inv_f04,
					    SUM(CASE WHEN lomp.erp_location='P-05_ไม่ผ่านQC' THEN inve.quantity ELSE 0 END) as qty_inv_p05,
						SUM(CASE WHEN lomp.erp_location LIKE 'F-05%' THEN inve.quantity ELSE 0 END) as qty_inv_f05_qc,
						SUM(CASE WHEN (lomp.erp_location='P-05_center') OR (lomp.erp_location='P-05_CENTER') THEN inve.quantity ELSE 0 END) as qty_inv_p05_qc,
						SUM(CASE WHEN lomp.erp_location='F-01' THEN inve.quantity ELSE 0 END) as qty_inv_f01,
						SUM(CASE WHEN lomp.erp_location='P-01' THEN inve.quantity ELSE 0 END) as qty_inv_p01,
						SUM(CASE WHEN lomp.erp_location='P_07_รอเปลี่ยนก' THEN inve.quantity ELSE 0 END) as qty_p07,
						SUM(CASE WHEN (lomp.erp_location LIKE 'c%') OR (lomp.erp_location LIKE 'C%') THEN inve.quantity ELSE 0 END) as qty_c01_c24
				FROM dbo.t_wms_inventory inve
				INNER JOIN dbo.t_wms_location loc ON inve.location_id=loc.location_id
				INNER JOIN dbo.t_wms_location lomp ON loc.[location]=lomp.location
				WHERE whit.wh_item_master_id=inve.wh_item_master_id AND inve.inventory_status_id='27F4619D-3F17-4897-B597-16AD22EE8B8A'
				GROUP BY inve.wh_item_master_id
			) as item_inv
	) as item_inv

OUTER APPLY
	(SELECT SUM(CASE WHEN hdr.order_type='Sales Order' THEN det.quantity_order ELSE 0 END) as qty_outb_so,
		SUM(CASE WHEN hdr.order_type='Production Order' THEN det.quantity_order ELSE 0 END) as qty_outb_pd
	FROM dbo.t_wms_outbound_detail det
    INNER JOIN dbo.t_wms_outbound_master hdr ON det.outbound_order_master_id=hdr.outbound_order_master_id
	WHERE det.wh_item_master_id=whit.wh_item_master_id AND hdr.order_status='OPEN'
	GROUP BY det.wh_item_master_id) as item_outb

OUTER APPLY
	(SELECT SUM(CASE WHEN hdr.order_type='Purchase order' THEN det.quantity_order ELSE 0 END) as qty_inb_po,
		SUM(CASE WHEN hdr.order_type='Production Order' THEN det.quantity_order ELSE 0 END) as qty_inb_pd
	FROM dbo.t_wms_inbound_detail det
    INNER JOIN dbo.t_wms_inbound_master hdr ON det.inbound_order_master_id=hdr.inbound_order_master_id
	WHERE det.wh_item_master_id=whit.wh_item_master_id AND hdr.order_status='OPEN'
	GROUP BY det.wh_item_master_id) as item_inb

GO
