CREATE VIEW [dbo].[v_wms_inventory_count_external_order]
AS
SELECT inv.inventory_id
, inv.attribute_group_id
, inv.inv_type
, inv.wh_master_id
, wh.wh_id
, own.owner_id
, own.owner_code
, inv.location_id
, loc.location
, loc.loc_type
, loc.pick_sequence
, loc.pick_area_id
, loc.lpn_controlled
, inv.parent_lpn
, inv.lpn
, inv.wh_item_master_id
, item.item_number
, item.description
, item.sn_control
, ISNULL(invSN.quantity, inv.quantity) AS quantity
, ISNULL(invSN.quantity_allocated, inv.quantity_allocated) AS quantity_allocated
, ISNULL(invSN.quantity_incoming, inv.quantity_incoming) AS quantity_incoming
, inv.receive_date
, invStatus.inv_status
, inv.inventory_status_id
, cate.category_id
, cate.item_category
, cate.description AS item_category_desc
, item.dg_code
, item.grade
, item.price
, item.cost
, item.item_master_id
, invLot.lot_number
, invExp.expiry_date
, invSN.serial_number
, invAttribute1.attribute1
, invAttribute2.attribute2
, invAttribute3.attribute3
, invAttribute4.attribute4
, invAttribute5.attribute5
, item.days_to_expire
, custLoc.customer_id
, cust.customer_code
, cust.customer_name
, obDV.delivery_date
, obDV.delivery_number
, inv.create_date
, inv.create_by
, subCate.sub_category
, subCate.description AS sub_category_desc
FROM  t_wms_inventory AS inv 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS lot_number
                FROM        t_wms_inventory_attribute
                WHERE     (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS expiry_date
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_7
                WHERE     (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS serial_number, quantity, quantity_allocated, quantity_incoming
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_6
                WHERE     (inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8')) AS invSN ON inv.inventory_id = invSN.inventory_id AND inv.attribute_group_id = invSN.attribute_group_id
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS attribute1
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_5
                WHERE     (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttribute1 ON inv.inventory_id = invAttribute1.inventory_id AND inv.attribute_group_id = invAttribute1.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS attribute2
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_4
                WHERE     (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttribute2 ON inv.inventory_id = invAttribute2.inventory_id AND inv.attribute_group_id = invAttribute2.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS attribute3
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_3
                WHERE     (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttribute3 ON inv.inventory_id = invAttribute3.inventory_id AND inv.attribute_group_id = invAttribute3.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS attribute4
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_2
                WHERE     (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttribute4 ON inv.inventory_id = invAttribute4.inventory_id AND inv.attribute_group_id = invAttribute4.attribute_group_id 
LEFT OUTER JOIN (SELECT     inventory_id, attribute_group_id, attribute_value AS attribute5
                FROM        t_wms_inventory_attribute AS t_wms_inventory_attribute_1
                WHERE     (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttribute5 ON inv.inventory_id = invAttribute5.inventory_id AND inv.attribute_group_id = invAttribute5.attribute_group_id 
LEFT OUTER JOIN t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
LEFT OUTER JOIN t_wms_wh AS wh ON inv.wh_master_id = wh.wh_master_id 
LEFT OUTER JOIN t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id AND inv.wh_master_id = whItem.wh_master_id 
LEFT OUTER JOIN t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
LEFT OUTER JOIN t_wms_owner AS own ON inv.owner_id = own.owner_id 
LEFT OUTER JOIN t_wms_location AS loc ON inv.location_id = loc.location_id 
LEFT OUTER JOIN t_wms_customer_location AS custLoc ON loc.location_id = custLoc.location_id 
LEFT OUTER JOIN t_wms_customer AS cust ON custLoc.customer_id = cust.customer_id 

LEFT JOIN (SELECT delivery_date
				,delivery_number
				,serial_number
				,ROW_NUMBER() OVER(PARTITION BY serial_number ORDER BY create_date DESC) AS is_max
			FROM t_wms_outbound_delivery
		  ) obDV ON invSN.serial_number = obDV.serial_number and obDV.is_max = 1
LEFT JOIN t_wms_category AS cate ON item.category_id = cate.category_id
LEFT JOIN t_wms_sub_category subCate ON item.sub_category_id = subCate.sub_category_id







GO
