CREATE VIEW [dbo].[v_wms_report_production_picking_slip]
AS
SELECT dbo.t_wms_outbound_consignment_master.outbound_order_number
     , dbo.t_wms_outbound_consignment_master.user_def3
     , dbo.t_wms_outbound_consignment_master.order_date
     , dbo.t_wms_outbound_consignment_detail.create_date
     , dbo.t_wms_outbound_consignment_detail.user_def2
     , dbo.t_wms_outbound_consignment_detail.item_number
     , dbo.t_wms_outbound_consignment_detail.item_description
     , dbo.t_wms_outbound_consignment_detail.ship_location
     , dbo.t_wms_outbound_consignment_detail.quantity_order
     , dbo.t_wms_outbound_consignment_detail.quantity_ship
     , dbo.t_host_wms_outbound_order.customer_purchase_order
     , dbo.t_wms_item.description
     , dbo.t_wms_item_uom.uom
     , dbo.t_host_wms_outbound_order.wh_id
     , dbo.t_host_wms_outbound_order.owner_id
	 , loc.erp_location
FROM dbo.t_wms_outbound_consignment_master
     INNER JOIN dbo.t_wms_outbound_consignment_detail ON dbo.t_wms_outbound_consignment_master.outbound_consignment_master_id = dbo.t_wms_outbound_consignment_detail.outbound_consignment_master_id
     INNER JOIN dbo.t_host_wms_outbound_order ON dbo.t_wms_outbound_consignment_master.outbound_order_number = dbo.t_host_wms_outbound_order.order_number
     INNER JOIN dbo.t_wms_item ON dbo.t_wms_item.item_master_id = dbo.t_wms_outbound_consignment_detail.item_master_id
     INNER JOIN dbo.t_wms_item_uom ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_uom.item_master_id
	 INNER JOIN dbo.t_wms_location loc ON loc.location = dbo.t_wms_outbound_consignment_detail.ship_location
GO
/****** Object:  View [dbo].[v_wms_inventory_external]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 

CREATE view [dbo].[v_wms_inventory_external]
as

SELECT tInv.location				
	,tInv.inv_quantity	AS total_quantity
	,ISNULL(tInv.inv_quantity,0) - ISNULL(tMissing.missing_quantity,0) - ISNULL(tShort.short_date_quantity,0) - ISNULL(tExpire.expire_quantity,0) AS normal_quantity
	,ISNULL(tMissing.missing_quantity,0) AS missing_quantity
	,ISNULL(tShort.short_date_quantity,0) AS short_date_quantity
	,ISNULL(tExpire.expire_quantity,0) AS expire_quantity
FROM (SELECT location_id
		,location
		,customer_id
		,customer_code
		,SUM(quantity) inv_quantity
		FROM v_wms_inventory_count_external_order
		WHERE inv_status in ('Consignment','Missing CSM')
		GROUP BY location_id, location, customer_id, customer_code
		) tInv
LEFT JOIN (SELECT inv.location_id
			, SUM(inv.quantity) missing_quantity
			, cust.customer_code
			FROM  t_wms_inventory AS inv 
			LEFT OUTER JOIN t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
			LEFT OUTER JOIN t_wms_customer_location AS custLoc ON inv.location_id = custLoc.location_id 
			LEFT OUTER JOIN t_wms_customer AS cust ON custLoc.customer_id = cust.customer_id
			WHERE invStatus.inv_status = 'Missing CSM'
			GROUP BY inv.location_id,cust.customer_code
			) tMissing ON tInv.location_id = tMissing.location_id and tInv.customer_code = tMissing.customer_code
LEFT JOIN (SELECT inv.location_id
			, SUM(inv.quantity)  short_date_quantity
			, cust.customer_code
			FROM  t_wms_inventory AS inv 
			LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
							FROM t_wms_inventory_attribute AS t_wms_inventory_attribute_7
							WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
			LEFT OUTER JOIN t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
			LEFT OUTER JOIN t_wms_customer_location AS custLoc ON inv.location_id = custLoc.location_id 
			LEFT OUTER JOIN t_wms_customer AS cust ON custLoc.customer_id = cust.customer_id 
			WHERE (DATEDIFF(DAY,GETDATE(),CONVERT(DATE,invExp.expiry_date)) > 0 AND DATEDIFF(DAY,GETDATE(),CONVERT(DATE,invExp.expiry_date)) <= 45)
			GROUP BY inv.location_id, cust.customer_code
		   ) tShort ON tInv.location_id = tShort.location_id AND tInv.customer_code = tShort.customer_code
LEFT JOIN (SELECT inv.location_id
			, SUM(inv.quantity) AS expire_quantity
			, cust.customer_code
			FROM  t_wms_inventory AS inv 
			LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
							FROM t_wms_inventory_attribute AS t_wms_inventory_attribute_7
							WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
			LEFT OUTER JOIN t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
			LEFT OUTER JOIN t_wms_customer_location AS custLoc ON inv.location_id = custLoc.location_id 
			LEFT OUTER JOIN t_wms_customer AS cust ON custLoc.customer_id = cust.customer_id 
			WHERE DATEDIFF(DAY,GETDATE(),CONVERT(DATE,invExp.expiry_date)) <= 0
			GROUP BY inv.location_id, cust.customer_code
		   ) tExpire ON tInv.location_id = tExpire.location_id AND tInv.customer_code = tExpire.customer_code
--WHERE tInv.customer_code = '114313'
	
GO
/****** Object:  View [dbo].[v_wms_report_production_receive]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 

CREATE VIEW [dbo].[v_wms_report_production_receive]
AS
SELECT dbo.t_wms_inbound_master.inbound_order_number
     , dbo.t_wms_inbound_master.user_def1
     , dbo.t_wms_inbound_master.order_type
     , dbo.t_wms_receipt_header.create_date
     , dbo.t_wms_receipt_detail.item_number
     , dbo.t_wms_receipt_detail.location_received
     , dbo.t_wms_receipt_detail.quantity_received
     , dbo.t_wms_item.description
     , dbo.t_wms_item_uom.uom
     , dbo.t_wms_inbound_master.owner_code
     , dbo.t_wms_inbound_master.wh_id
	 , loc.erp_location
FROM dbo.t_wms_inbound_master
     INNER JOIN dbo.t_wms_receipt_header ON dbo.t_wms_inbound_master.inbound_order_master_id = dbo.t_wms_receipt_header.inbound_order_master_id
     INNER JOIN dbo.t_wms_receipt_detail ON dbo.t_wms_receipt_header.inbound_order_master_id = dbo.t_wms_receipt_detail.inbound_order_master_id
     INNER JOIN dbo.t_wms_item ON dbo.t_wms_receipt_detail.item_number = dbo.t_wms_item.item_number
     INNER JOIN dbo.t_wms_item_uom ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_uom.item_master_id
	 INNER JOIN	dbo.t_wms_location loc ON loc.location = dbo.t_wms_receipt_detail.location_received
WHERE dbo.t_wms_inbound_master.order_type IN('Production Order')
GO
/****** Object:  View [dbo].[v_wms_user_group]    Script Date: 08/08/2025 11:11:28 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[v_wms_user_group]
AS

select 
u.[user_id]
,u.name
,u.first_name
,u.last_name
,u.is_active
,CASE WHEN ug.name = 'IOS User' THEN 'IOS' 
	  WHEN ug.name = 'IOS' THEn 'OTHER'
	  ELSE ug.name end  as group_name
--,ug.name  as group_name
,app.application_name
from WM3_Security.dbo.t_com_user_application u_app
inner join WM3_Security.dbo.t_com_application app on u_app.app_id = app.app_id
inner join WM3_Security.dbo.t_com_user u on u_app.[user_id] = u.[user_id]
inner join WM3_Security.dbo.t_com_user_group ug on u_app.user_group_id = ug.user_group_id
where u.is_active = 'YES'
GO
