/****** Object:  StoredProcedure [dbo].[sp_create_text]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_create_text]	
	@File        VARCHAR(2000),
	@Text        NTEXT
AS
BEGIN
	DECLARE @OLE            INT 
	EXECUTE sp_OACreate 'ADODB.Stream',  @OLE OUTPUT

	EXECUTE sp_OASetProperty             @OLE,    'Type',             2							--1 = binary, 2 = text
	EXECUTE sp_OASetProperty             @OLE,    'Mode',             3							--0 = not set, 1 read, 2 write, 3 read/write
	EXECUTE sp_OASetProperty             @OLE,    'Charset',          'UTF-8'					--'ISO-8859-1'
	EXECUTE sp_OASetProperty             @OLE,    'LineSeparator',    'adLF'
	EXECUTE sp_OAMethod                  @OLE,    'Open'  
	--EXECUTE sp_OAMethod                @OLE,    'WriteText',        NULL,       @Converted	--text method
	EXECUTE sp_OAMethod                  @OLE,    'WriteText',        NULL,       @Text 		--text method

	--Commit data and close text stream
	EXECUTE sp_OAMethod                  @OLE,    'SaveToFile',       NULL,       @File, 2		--1 = notexist 2 = overwrite
	EXECUTE sp_OAMethod                  @OLE,    'Close'
	EXECUTE sp_OADestroy                 @OLE

	EXECUTE sp_OADestroy @OLE 
	--select @OLE
END
GO
/****** Object:  StoredProcedure [dbo].[usp_adjust_serial_for_dch]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[usp_adjust_serial_for_dch]
AS
begin
 
	declare   @out_ErrorCode	nvarchar(50)	
	declare   @out_ErrorMessage	nvarchar(50)
	declare	  @v_vchSNNumber	VARCHAR(15)
	declare	  @v_intSNRunning	INT

	DECLARE @v_intRow	AS INT = 1; 
	DECLARE @v_intTotal AS INT = 150;
	WHILE (@v_intRow <= @v_intTotal) 
	BEGIN  
		SELECT @v_intSNRunning = NEXT VALUE FOR dbo.SerialSeq;   

		if @v_intSNRunning = 300000
			return;
		SET @v_vchSNNumber = NULL
		SET @v_vchSNNumber = RIGHT(CONVERT(VARCHAR(50),'000000000000' + CONVERT(VARCHAR,@v_intSNRunning)),12)
	 
		exec usp_inventory_adjust_in  @in_vchApplicationID	= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'			
									,@in_vchDevice			= 'Manual'
									,@in_vchUserID			= 'Manual'
									,@in_vchTransactionType	= 'INV_ADJUST'
									,@in_vchSubTranType		= 'INV_ADJUST'
									,@in_vchWhMasterID		= '42CA6B0D-7996-4E24-9561-C72C76339E49'
									,@in_vchOwnerID			= '0A57CCFC-5133-4C07-ADAD-4C31613AE999'
									,@in_vchInvStatusID		= 'E2758135-F79F-498D-AC9F-5A320864EF86'
									,@in_vchLocationID		= 'B4EA31F0-2683-45ED-BB43-EFDDA7FADA85'	--
									,@in_vchWhItemMasterID	= '8E2249D0-68E2-4E03-B000-73E4AA4D7949'	--
									,@in_vchParentLPN		= NULL
									,@in_vchLPN				= NULL
									,@in_vchLotNumber		= '20241104'
									,@in_vchExpiryDate		= '20271104'
									,@in_vchAttribute1		= NULL
									,@in_vchAttribute2		= NULL
									,@in_vchAttribute3		= NULL
									,@in_vchAttribute4		= NULL
									,@in_vchAttribute5		= NULL
									,@in_vchSerialNumber	= @v_vchSNNumber
									,@in_fltQty				= 1
									,@in_vchItemUomID		= '717FE431-7C70-405C-A472-A957C8BA4A5D' 
									,@in_vchReasonID		= NULL
									,@in_dtReceiveDate		= '2024-11-04'
									,@in_dtMfgDate			= NULL
									,@in_vchReferenceNumber	= ''
									,@out_ErrorCode			= @out_ErrorCode	output
									,@out_ErrorMessage		= @out_ErrorMessage output 
		select @out_ErrorCode,@out_ErrorMessage
		print @v_vchSNNumber
		select @v_intRow += 1
END


 


end
