CREATE PROCEDURE [dbo].[usp_api_binding_move_putaway]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchWhID				NVARCHAR(25), 
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,	
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		NVARCHAR(50) = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	NVARCHAR(50) = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25) = NULL,
	@in_vchSourceLPN		NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OWNER'
		BEGIN
			SELECT owner_code AS value_member
				, owner_code AS display_member
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
			RETURN;
		END 
	IF @in_vchControlName = 'SOURCE_LOCATION'
		BEGIN
			IF (@in_vchOwnerID IS NULL)
				BEGIN
					SELECT TOP 1 @in_vchOwnerID = own.owner_id 
					FROM t_wms_owner_user ownUser
					INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
					WHERE own.is_active = 'YES'
					AND ownUser.user_id = @in_vchUserID
				END

			SELECT DISTINCT loc.location_id  AS value_member
				,loc.location AS display_member
			FROM t_wms_location loc
			INNER JOIN t_wms_inventory inv WITH (NOLOCK) ON inv.location_id = loc.location_id 
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id = @in_vchOwnerID
			AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_FOR_PUTAWAY' AND is_active = 'YES')
			ORDER BY loc.location
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT DISTINCT invST.inv_status	AS value_member
				,invST.inv_status	AS display_member
			FROM t_wms_inventory_status invST
			INNER JOIN t_wms_inventory inv WITH (NOLOCK) ON inv.inventory_status_id = invST.inventory_status_id 
			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.location_id = @in_vchSourceLocationID
			AND invST.is_active = 'YES'
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT inv.parent_lpn AS value_member
				,inv.parent_lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK) 
 			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchSourceLocationID
			ORDER BY inv.parent_lpn
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT inv.lpn AS value_member
				,inv.lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK) 
 			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchSourceLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			ORDER BY inv.lpn
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT DISTINCT item.item_number AS value_member
				,item.item_number AS display_member
			FROM t_wms_inventory inv  WITH (NOLOCK) 
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
 			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchSourceLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchSourceLPN,'')
			ORDER BY item.item_number 
			RETURN;		
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number AS value_member
				,lot_number AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			ORDER BY lot_number
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT expiry_date AS value_member
				,expiry_date AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY expiry_date
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1 AS value_member
				,attribute1 AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY attribute1
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2 AS value_member
				,attribute2 AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			ORDER BY attribute2
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3 AS value_member
				,attribute3 AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			ORDER BY attribute3
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4 AS value_member
				,attribute4 AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			ORDER BY attribute4
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5 AS value_member
				,attribute5 AS display_member
			FROM v_wms_inventory_data_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY attribute5
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT serial_number AS value_member
				,serial_number AS display_member
			FROM v_wms_inventory_data_serial_by_id WITH (NOLOCK) 
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchSourceLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			ORDER BY serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION_DESTINATION'
		BEGIN
			--2023-08-30 : check back order ถ้ามี outbound order ที่ is_back_order = 'YES' และยังไม่ได้จองไม่ได้หยิบ จะต้อง default stg มาด้วย
			IF EXISTS (SELECT TOP 1 obMS.outbound_order_master_id
						FROM t_wms_outbound_master obMS WITH (NOLOCK)
						INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
						LEFT JOIN (SELECT outbound_order_detail_id
										, SUM(quantity_plan) AS quantity_plan
									FROM t_wms_outbound_pick_detail WITH (NOLOCK)
									GROUP BY outbound_order_detail_id
									) pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
						WHERE obMS.wh_master_id = @in_vchWhMasterID
						AND obMS.is_back_order = 'YES'
						AND obMS.order_status NOT IN ('OPEN','SHIP','CLOSE')
						AND ROUND(obDT.quantity_ship,@Round) < ROUND(obDT.quantity_order,@Round)
						AND ROUND(ISNULL(pickDT.quantity_plan,0),@Round) < ROUND(obDT.quantity_order,@Round)
						AND obDT.wh_item_master_id = @in_vchWhItemMasterID)
				BEGIN
					--ถ้าตรงกับ back order ที่ยังไม่ได้หยิบ จะให้ binding stg location ด้วย
					SELECT location_id  AS value_member
						,location AS display_member
					FROM t_wms_location
					WHERE wh_master_id =  @in_vchWhMasterID
					AND (loc_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_TO_DESTINATION' and is_active = 'YES')
						OR loc_type = 'STG')
					AND is_active = 'YES'
					ANd location <> @in_vchSourceLocation
					ORDER BY putaway_sequence, location
					RETURN;
				END
			ELSE
				BEGIN 
					SELECT location_id  AS value_member
						,location AS display_member
					FROM t_wms_location
					WHERE wh_master_id =  @in_vchWhMasterID
					AND loc_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_TO_DESTINATION' and is_active = 'YES')
					AND is_active = 'YES'
					ANd location <> @in_vchSourceLocation
					ORDER BY putaway_sequence, location
					RETURN;
				END
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_move_putaway_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_move_putaway_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchFromLocationID	UNIQUEIDENTIFIER= NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT inv.lpn AS value_member
				, inv.lpn AS display_member
			FROM t_wms_inventory inv
			INNER JOIN t_wms_location loc on inv.location_id = loc.location 
			WHERE ISNULL(lpn,'') <> ''
			AND loc.loc_type IN (select value from t_wms_rule WHERE rule_code = 'LOCATION_TYPE_FOR_PUTAWAY' AND is_active = 'YES')
			RETURN;
		END 
	IF @in_vchControlName = 'LOCATION_DESTINATION'
		BEGIN
			SELECT location_id  AS value_member
				,location AS display_member
			FROM t_wms_location
			WHERE wh_master_id =  @in_vchWhMasterID
			AND loc_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_TO_DESTINATION' and is_active = 'YES')
			AND lpn_controlled = 'YES'
			AND is_active = 'YES'
			ANd location_id <> @in_vchFromLocationID
			ORDER BY putaway_sequence, location
			RETURN;
		END
END
