CREATE PROCEDURE [dbo].[usp_api_binding_outbound_packing]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID UNIQUEIDENTIFIER,
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchPackNumber		NVARCHAR(25),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			SELECT DISTINCT obMS.outbound_order_master_id	 AS value_member
				,obMS.outbound_order_number	AS display_member
			FROM dbo.t_wms_outbound_master obMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
			INNER JOIN t_wms_outbound_pick_master pickMS WITH (NOLOCK) ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
			LEFT JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.order_type IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
 			AND obMS.order_status IN ('PICK','PICKED','PACK','PACKED')
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			AND (ROUND(ISNULL(pickDT.quantity_ship,0),@Round) < ROUND(ISNULL(pickDT.quantity_pack,0),@Round) OR ROUND(ISNULL(pickDT.quantity_pack,0),@Round) < ROUND(ISNULL(pickDT.quantity_pick,0),@Round))
			ORDER BY obMS.outbound_order_number
			RETURN; 
		END 
	IF @in_vchControlName = 'PACK_NUMBER'
		BEGIN
			SELECT DISTINCT lpn_pack AS value_member
				,lpn_pack AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT DISTINCT vPack.staging_location_id  AS value_member
				,loc.location AS display_member
			FROM v_wms_outbound_pack_for_check vPack WITH (NOLOCK)
			INNER JOIN t_wms_location loc ON vPack.staging_location_id = loc.location_id
			WHERE vPack.outbound_order_master_id = @in_vchOutboundMasterID
			AND vPack.staging_location_id IS NOT NULL
			RETURN;
		END 
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT DISTINCT staging_parent_lpn AS value_member
				,staging_parent_lpn AS display_member
			FROM v_wms_outbound_pack_for_check
 			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT staging_lpn AS value_member
				,staging_lpn AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT DISTINCT item_master_id AS value_member
				,item_number AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			ORDER BY item_number
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number AS value_member
				,lot_number AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') <> ''
			ORDER BY lot_number
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT expiry_date AS value_member
				,expiry_date AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') <> ''
			ORDER BY expiry_date
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1 AS value_member
				,attribute1 AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') <> ''
			ORDER BY attribute1
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2 AS value_member
				,attribute2 AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') <> ''
			ORDER BY attribute2
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3 AS value_member
				,attribute3 AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') <> ''
			ORDER BY attribute3
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4 AS value_member
				,attribute4 AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') <> ''
			ORDER BY attribute4
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5 AS value_member
				,attribute5 AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') <> ''
			ORDER BY attribute5
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT DISTINCT serial_number AS value_member
				,serial_number AS display_member
			FROM v_wms_outbound_pack_for_check WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0)
			AND staging_location_id = @in_vchLocationID
			AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') <> ''
			ORDER BY serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_outbound_unpack]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_outbound_unpack]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID UNIQUEIDENTIFIER,
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchPackNumber		NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			SELECT outbound_order_master_id	 AS value_member
				,outbound_order_number		 AS display_member
			FROM dbo.t_wms_outbound_master WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID
			AND order_type IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
 			AND order_status IN ('PICK','PICKED','PACK','PACKED')
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			ORDER BY outbound_order_number
			RETURN; 
		END 
	IF @in_vchControlName = 'PACK_NUMBER'
		BEGIN
			SELECT DISTINCT packDT.lpn_pack AS value_member
				,packDT.lpn_pack AS display_member
			FROM t_wms_outbound_pack_detail packDT WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON packDT.outbound_pick_detail_id = pickDT.outbound_pick_detail_id 
			WHERE packDT.outbound_order_master_id = @in_vchOutboundMasterID
			AND ROUND(ISNULL(pickDT.quantity_pack,0) - ISNULL(pickDT.quantity_ship,0),@Round) > 0 
			ORDER BY packDT.lpn_pack
			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT DISTINCT item.item_number AS value_member
				,item.item_number AS display_member
			FROM t_wms_outbound_pack_detail packDT WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON packDT.outbound_pick_detail_id = pickDT.outbound_pick_detail_id 
			INNER JOIN t_wms_wh_item whItem ON packDT.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE packDT.outbound_order_master_id = @in_vchOutboundMasterID
			AND packDT.lpn_pack = @in_vchPackNumber
			AND ROUND(ISNULL(pickDT.quantity_pack,0) - ISNULL(pickDT.quantity_ship,0),@Round) > 0 
			ORDER BY item.item_number
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number AS value_member
				,lot_number AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK) 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') <> ''
			ORDER BY lot_number
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT expiry_date AS value_member
				,expiry_date AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') <> ''
			ORDER BY expiry_date
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1 AS value_member
				,attribute1 AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK) 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') <> ''
			ORDER BY attribute1
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2 AS value_member
				,attribute2 AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') <> ''
			ORDER BY attribute2
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3 AS value_member
				,attribute3 AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK) 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') <> ''
			ORDER BY attribute3
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4 AS value_member
				,attribute4 AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') <> ''
			ORDER BY attribute4
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5 AS value_member
				,attribute5 AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK)  
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') <> ''
			ORDER BY attribute5
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT DISTINCT serial_number AS value_member
				,serial_number AS display_member
			FROM t_wms_outbound_pack_detail WITH (NOLOCK) 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND lpn_pack = @in_vchPackNumber
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') <> ''
			ORDER BY serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END 
END
