/****** Object:  StoredProcedure [dbo].[usp_api_binding_pickup]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_pickup]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OWNER'
		BEGIN
			SELECT owner_code AS value_member
				,owner_name AS display_member
			FROM t_wms_owner
			WHERE is_active = 'YES'
			RETURN;
		END 
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT DISTINCT loc.location_id  AS value_member
				,loc.location AS display_member
			FROM t_wms_location loc
			INNER JOIN t_wms_inventory inv ON inv.location_id = loc.location_id 
			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND (CASE WHEN ISNULL(@in_vchOwnerID,'') = '' THEN '' ELSE CONVERT(VARCHAR(36),inv.owner_id) END) = (CASE WHEN ISNULL(@in_vchOwnerID,'') = '' THEN '' ELSE @in_vchOwnerID END)
			AND loc.loc_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code ='LOCATION_TYPE_NOT_MOVE_ITEM' AND is_active = 'YES')
			ORDER BY loc.location
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT DISTINCT invST.inv_status	AS value_member
				,invST.inv_status	AS display_member
			FROM t_wms_inventory_status invST
			INNER JOIN t_wms_inventory inv ON inv.inventory_status_id = invST.inventory_status_id 
			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND invST.is_active = 'YES'
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT inv.parent_lpn AS value_member
				,inv.parent_lpn AS display_member
			FROM t_wms_inventory inv 
 			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchLocationID
			ORDER BY inv.parent_lpn
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT inv.lpn AS value_member
				,inv.lpn AS display_member
			FROM t_wms_inventory inv 
 			WHERE inv.wh_master_id =  @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			ORDER BY inv.lpn
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT DISTINCT item.item_number AS value_member
				,item.item_number AS display_member
			FROM t_wms_inventory inv 
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
 			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.inventory_status_id = @in_vchInvStatusID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
			ORDER BY item.item_number
			RETURN;		
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number AS value_member
				,lot_number AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			ORDER BY lot_number
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT expiry_date AS value_member
				,expiry_date AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY expiry_date
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1 AS value_member
				,attribute1 AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY attribute1
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2 AS value_member
				,attribute2 AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			ORDER BY attribute2
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3 AS value_member
				,attribute3 AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			ORDER BY attribute3
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4 AS value_member
				,attribute4 AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			ORDER BY attribute4
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5 AS value_member
				,attribute5 AS display_member
			FROM v_wms_inventory_data_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY attribute5
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT serial_number AS value_member
				,serial_number AS display_member
			FROM v_wms_inventory_data_serial_by_id
 			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			ORDER BY serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_receipt]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_receipt]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		NVARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchReceiptNumber	NVARCHAR(50) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL, 
	@in_vchReceiptMode		NVARCHAR(25) = NULL,
	@in_vchItemStatusID		UNIQUEIDENTIFIER = NULL,  
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_dtMFGDate			DATE = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL, 
	@in_vchReasonCode		NVARCHAR(20) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			----------------------------------------------------------
			-- Binding Inbound Order Number
			----------------------------------------------------------
			SELECT inbound_order_master_id	AS value_member
				, inbound_order_number		AS display_member
			FROM t_wms_inbound_master WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID
			AND order_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES')
			AND order_status NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			ORDER BY inbound_order_number
			RETURN; 
		END
	IF @in_vchControlName = 'PARTIAL_RECEIPT_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Partial Receipt Number
			----------------------------------------------------------
			SELECT DISTINCT receipt_number	AS value_member
				,receipt_number				AS display_member
			FROM t_wms_receipt_header WITH (NOLOCK)
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND receipt_status = 'OPEN'
			ORDER BY receipt_number
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Receipt
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location WITH (NOLOCK)
			WHERE wh_master_id =  @in_vchWhMasterID
			AND is_active = 'YES' 
			AND loc_type IN (SELECT value FROM t_wms_rule  WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
			ORDER BY putaway_sequence, location
			RETURN; 
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			----------------------------------------------------------
			-- Binding Parent LPN from t_wms_inventory
			----------------------------------------------------------
			SELECT DISTINCT inv.parent_lpn	AS value_member
				,inv.parent_lpn	AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			------------------------------------------------------------------------------
			-- ถ้า Control Parent LPN ก็ให้ดึง LPN ของ Parent LPN ที่สแกน
			------------------------------------------------------------------------------
			SELECT DISTINCT inv.lpn	AS value_member
				,inv.lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'LPN_RECEIPT'
		BEGIN
			------------------------------------------------------------------------------
			-- ให้ดึง LPN จาก Inbound LPN detail
			------------------------------------------------------------------------------
			SELECT DISTINCT ibLPN.lpn AS value_member
				,ibLPN.lpn AS display_member
			FROM t_wms_inbound_detail ibDT WITH (NOLOCK)
			LEFT JOIN t_wms_inbound_lpn_detail ibLPN ON  ibDT.inbound_order_detail_id = ibLPN.inbound_order_detail_id
			WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
			ORDER BY ibLPN.lpn
			RETURN;
		END
	IF @in_vchControlName = 'RECEIPT_MODE'
		BEGIN
			----------------------------------------------------------
			-- Binding Receipt Mode
			----------------------------------------------------------
			SELECT value_member
				, display_member
			FROM t_com_combobox_item
			WHERE group_name = 'receipt_mode'
			AND is_active = 'YES'
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT inv_status AS value_member
				,inv_status	AS display_member
			FROM t_wms_inventory_status
			WHERE is_active = 'YES'
			ORDER BY (CASE inv_status WHEN (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_STATUS_INBOUND_DEFAULT' AND is_active = 'YES') THEN 0 ELSE 1 END)
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Item Number
			----------------------------------------------------------
			SELECT DISTINCT item_number	AS value_member
				, item_number AS display_member
			FROM t_wms_inbound_detail WITH (NOLOCK)
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND ISNULL(quantity_receive,0) < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
														ELSE quantity_order END)
			ORDER BY item_number
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding LOT 
			-- ถ้าในแผนไม่มีให้ดึงจาก Inventory
			----------------------------------------------------------
			IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID  AND lot_number <> '') 
				BEGIN 
					SELECT DISTINCT lot_number AS value_member
						, lot_number AS display_member
					FROM v_wms_inventory_data_by_id WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID 
					ORDER BY lot_number
					RETURN;
				END
			ELSE
				BEGIN
					SELECT DISTINCT lot_number AS value_member
						, lot_number AS display_member
					FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID 
					AND ISNULL(quantity_receive,0) < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															ELSE quantity_order END)					
					AND ISNULL(lot_number,'') <> ''
					ORDER BY lot_number
					RETURN;
				END
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			----------------------------------------------------------
			-- Binding EXPIRY DATE 
			----------------------------------------------------------
			SELECT DISTINCT [expiry_date] AS value_member
				, [expiry_date] AS display_member
			FROM t_wms_inbound_detail WITH (NOLOCK)
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID 
			AND ISNULL(quantity_receive,0) < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
													WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
													WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
													ELSE quantity_order END)
			AND [expiry_date] <> ''
			ORDER BY [expiry_date]
			RETURN; 
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT item_uom_id  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
	IF @in_vchControlName = 'REASON'
		BEGIN
			SELECT reason_id AS value_member
				, reason_code AS display_member
			FROM t_wms_reason
			WHERE reason_type = 'OverReceive'
			AND is_active = 'YES'
			RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_receipt_all]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_receipt_all]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchInboundOrderNumber NVARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL, 
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL  
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			----------------------------------------------------------
			-- Binding Inbound Order Number
			----------------------------------------------------------
			SELECT inbound_order_master_id	AS value_member
				, inbound_order_number		AS display_member
			FROM t_wms_inbound_master
			WHERE wh_master_id = @in_vchWhMasterID
			AND order_type NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES')
			AND order_status NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			ORDER BY inbound_order_number
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Receipt
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE wh_master_id =  @in_vchWhMasterID
			AND is_active = 'YES' 
			AND loc_type IN (SELECT value FROM t_wms_rule  WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
			ORDER BY putaway_sequence, location
			RETURN; 
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_receipt_return]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_receipt_return]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOrderNumber		NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchOwnerCode		NVARCHAR(40),
	@in_vchReceiptNumber	NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchItemStatusID		UNIQUEIDENTIFIER = NULL,  
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchRefOutboundNumber NVARCHAR(50) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			----------------------------------------------------------
			-- Binding Inbound Order Number
			----------------------------------------------------------
			SELECT inbound_order_master_id	AS value_member
				, inbound_order_number		AS display_member
			FROM t_wms_inbound_master
			WHERE wh_master_id = @in_vchWhMasterID
			AND order_status NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
			AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES') 
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			ORDER BY inbound_order_number
			RETURN; 
		END
	IF @in_vchControlName = 'PARTIAL_RECEIPT_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Partial Receipt Number
			----------------------------------------------------------
			SELECT DISTINCT receipt_number	AS value_member
				,receipt_number				AS display_member
			FROM t_wms_receipt_header
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND receipt_status = 'OPEN'
			ORDER BY receipt_number
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Receipt
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE wh_master_id =  @in_vchWhMasterID
			AND is_active = 'YES' 
			AND loc_type IN (SELECT value FROM t_wms_rule  WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
			ORDER BY pick_sequence, location
			RETURN; 
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			----------------------------------------------------------
			-- Binding Parent LPN from t_wms_inventory
			----------------------------------------------------------
			SELECT DISTINCT inv.parent_lpn	AS value_member
				,inv.parent_lpn	AS display_member
			FROM t_wms_inventory inv
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			------------------------------------------------------------------------------
			-- ถ้า Control Parent LPN ก็ให้ดึง LPN ของ Parent LPN ที่สแกน
			------------------------------------------------------------------------------
			SELECT DISTINCT inv.lpn	AS value_member
				,inv.lpn AS display_member
			FROM t_wms_inventory inv
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT inventory_status_id AS value_member
				,inv_status	AS display_member
			FROM t_wms_inventory_status
			WHERE is_active = 'YES'
			ORDER BY (CASE inv_status WHEN (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_STATUS_INBOUND_DEFAULT' AND is_active = 'YES') THEN 0 ELSE 1 END)
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Item Number
			----------------------------------------------------------
			SELECT item_master_id AS value_member
				, item_number AS display_member
			FROM t_wms_inbound_detail 
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND ISNULL(quantity_receive,0) < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
														ELSE quantity_order END)
			ORDER BY item_number
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number AS value_member
				,lot_number AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			ORDER BY lot_number
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT [expiry_date] AS value_member
				,[expiry_date] AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY [expiry_date]
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1 AS value_member
				,attribute1 AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY attribute1
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2 AS value_member
				,attribute2 AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			ORDER BY attribute2
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3 AS value_member
				,attribute3 AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			ORDER BY attribute3
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4 AS value_member
				,attribute4 AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			ORDER BY attribute4 
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5 AS value_member
				,attribute5 AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY attribute5
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT serial_number AS value_member
				,serial_number AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			ORDER BY serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT item_uom_id  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
	IF @in_vchControlName = 'RECEIVE_DATE'
		BEGIN
			SELECT CONVERT(VARCHAR(10),receive_date) AS value_member
				,CONVERT(VARCHAR(10),receive_date) AS display_member
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_system_pick_load]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_system_pick_load]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25), 
	@in_vchLoadID			NVARCHAR(50),
	@in_vchBoxNumber		NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchReasonCode		NVARCHAR(20) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;

	IF @in_vchControlName = 'LOAD_ID'
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					-- กรณีที่ไม่ให้ช่วยกันหยิบ
					----------------------------------------------------------
					SELECT DISTINCT load_id	 AS value_member
						,load_id AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'SYSTEM_GROUP'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
					AND ISNULL(load_id,'') <> ''
					ORDER BY load_id
					RETURN;
				END
			ELSE
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					----------------------------------------------------------
					SELECT DISTINCT load_id	 AS value_member
						,load_id AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'SYSTEM_GROUP'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					AND ISNULL(load_id,'') <> ''
					ORDER BY load_id
					RETURN;
				END
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Box Number
			----------------------------------------------------------
			SELECT DISTINCT packDT.lpn_pack AS value_member
				,packDT.lpn_pack AS display_member
			FROM t_wms_outbound_master obMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_master pickMS WITH (NOLOCK) ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id														
			INNER JOIN t_wms_outbound_pack_detail packDT WITH (NOLOCK) ON packDT.outbound_order_master_id = obMS.outbound_order_master_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID
			AND packDT.lpn_pack NOT IN (SELECT staging_lpn FROM t_wms_outbound_pack_detail WHERE outbound_pick_detail_id = packDT.outbound_pick_detail_id AND ISNULL(staging_lpn,'') <> '')
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			SELECT value_member
				,display_member
			FROM (SELECT location_id AS value_member
					,location AS display_member
					,CONVERT(INT,line_number) AS line_number
					,ROW_NUMBER() OVER(PARTITION BY location ORDER BY pick_sequence,location,CONVERT(INT,line_number)) AS is_min
				  FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
				  WHERE wh_master_id = @in_vchWhMasterID 
				  AND ISNULL(load_id,'') = @in_vchLoadID
				  AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
				  AND is_override = 'NO') outbound
			WHERE outbound.is_min = 1
			ORDER BY CONVERT(INT,outbound.line_number)
			RETURN; 
		END
	IF (@in_vchControlName = 'STAGING_LOCATION')
		BEGIN
			----------------------------------------------------------
			-- Binding Location for STG Button
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE wh_master_id =  @in_vchWhMasterID
			AND loc_type = 'STG'
			AND is_active = 'YES'
			ORDER BY location
			RETURN; 
		END 
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT lpn AS value_member
				,lpn AS display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') <> ''
			ORDER BY lpn 
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT item.value_member
				,item.display_member
			FROM (SELECT item_master_id AS value_member
	  				,item_number AS display_member
	  				,ROW_NUMBER() OVER(PARTITION BY item_number ORDER BY CONVERT(INT,line_number)) AS is_min
	  				,CONVERT(INT,line_number) AS line_number
				 FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
				 WHERE wh_master_id = @in_vchWhMasterID 
				 AND ISNULL(load_id,'') = @in_vchLoadID
				 AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
				 AND is_override = 'NO'
				 AND location_id = @in_vchLocationID
				 AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				 AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				 ) item
			WHERE item.is_min = 1
			ORDER BY CONVERT(INT,item.line_number)
			RETURN; 
		END 
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number	AS value_member
				,lot_number	AS  display_member 
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			ORDER BY lot_number
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT expiry_date	AS value_member
				,expiry_date	AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY expiry_date
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1	AS value_member
				,attribute1	 AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY attribute1 
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2	AS value_member
				,attribute2	 AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			ORDER BY attribute2
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3	AS value_member
				,attribute3	 AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			ORDER BY attribute3
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4	AS value_member
				,attribute4	 AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			ORDER BY attribute4
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5	AS value_member
				,attribute5	 AS  display_member
			FROM v_wms_outbound_pick_detail_by_load WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY attribute5
			RETURN; 
		END 
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			DECLARE @v_vchOwnerID UNIQUEIDENTIFIER = NULL
			SELECT TOP 1 @v_vchOwnerID = owner_id FROM t_wms_outbound_master WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID
			
			SELECT pickDT.receive_date
				,pickDT.serial_number
				,invST.inventory_status_id
			INTO #tPick
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			INNER JOIN t_wms_outbound_master obMS WITH (NOLOCK) on obDT.outbound_order_master_id = obMS.outbound_order_master_id
			INNER JOIN t_wms_inventory_status invST on invST.inv_status = obDT.default_item_status 
			WHERE obMS.wh_master_id = @in_vchWhMasterID 
			AND ISNULL(obMS.load_id,'') = @in_vchLoadID
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
			AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')

			SELECT pickDT.serial_number 
			INTO #tPickOther
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			INNER JOIN t_wms_outbound_master obMS WITH (NOLOCK) on obDT.outbound_order_master_id = obMS.outbound_order_master_id
			INNER JOIN t_wms_inventory_status invST on invST.inv_status = obDT.default_item_status 
			WHERE obMS.wh_master_id = @in_vchWhMasterID 
			AND ISNULL(obMS.load_id,'') <> @in_vchLoadID
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) = 0
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
			AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(pickDT.serial_number,'') <> ''

			--ถ้าไม่มี Serial ที่เป็นค่าว่างเลยให้ดึงจาก Plan แสดงว่ามีการระบุ Serial มาทั้งหมด
			IF NOT EXISTS (SELECT * FROM #tPick WHERE ISNULL(serial_number,'') = '')
				BEGIN
					SELECT serial_number AS value_member
						,serial_number AS display_member
					FROM #tPick
					ORDER BY serial_number
				END
			ELSE
				BEGIN
					--Serial ดึงจาก Inventory
					SELECT serial_number AS value_member
						,serial_number AS display_member
					FROM v_wms_inventory_data_serial_by_id WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @v_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND receive_date IN (SELECT receive_date FROM #tPick)
					AND serial_number NOT IN (SELECT serial_number FROM #tPickOther)
					AND inventory_status_id IN (SELECT inventory_status_id FROM #tPick)
					ORDER BY serial_number
				END 
			 
			RETURN; 
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_system_pick_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_system_pick_lpn]
(
	@in_vchApplicationID	  VARCHAR(40),
	@in_vchControlName		  NVARCHAR(50),	--Current Screen
	@in_vchLocalID			  VARCHAR(40),
	@in_vchDeviceID			  NVARCHAR(50),
	@in_vchUserID			  NVARCHAR(25), 
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchWhID				  NVARCHAR(25),
	@in_vchOutboundMasterID	  UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID			  UNIQUEIDENTIFIER,
	@in_vchOwnerCode		  NVARCHAR(40), 
	@in_vchLocationID		  UNIQUEIDENTIFIER,
	@in_vchLocation			  NVARCHAR(50),
	@in_vchLPN				  NVARCHAR(25)
)
AS
BEGIN
	SET NOCOUNT ON;		
	DECLARE @v_intRound INT = 0
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					-- กรณีที่ไม่ให้ช่วยกันหยิบ
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND pick_type = 'SYSTEM'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID) 
					AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '') 
					ORDER BY outbound_order_number
				END
			ELSE
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND pick_type = 'SYSTEM' 
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY outbound_order_number
				END
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			SELECT DISTINCT value_member
				,display_member
			FROM (SELECT pickDT.location_id AS value_member
					,loc.location AS display_member
					,CONVERT(INT,obDT.line_number) AS line_number
					,ROW_NUMBER() OVER(PARTITION BY loc.location ORDER BY loc.pick_sequence,loc.location,CONVERT(INT,obDT.line_number)) AS is_min
				  FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
				  INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
				  INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
				  WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
				  AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
				  AND loc.lpn_controlled = 'YES'
				  AND pickDT.is_override = 'NO') outbound
			WHERE outbound.is_min = 1
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT pickDT.lpn AS value_member
				,pickDT.lpn AS display_member
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
			AND ROUND(ISNULL(pickDT.quantity_pick,0),@v_intRound) < ROUND(ISNULL(pickDT.quantity_plan,0),@v_intRound)
			AND pickDT.is_override = 'NO'
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.lpn,'') <> ''
			ORDER BY pickDT.lpn 
			RETURN; 
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_system_pick_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_system_pick_order]
(
	@in_vchApplicationID	  VARCHAR(40),
	@in_vchControlName		  NVARCHAR(50),	--Current Screen
	@in_vchLocalID			  VARCHAR(40),
	@in_vchDeviceID			  NVARCHAR(50),
	@in_vchUserID			  NVARCHAR(25), 
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchWhID				  NVARCHAR(25),
	@in_vchOutboundMasterID	  UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID			  UNIQUEIDENTIFIER,
	@in_vchOwnerCode		  NVARCHAR(40),
	@in_vchBoxNumber		  NVARCHAR(50),
	@in_vchLocationID		  UNIQUEIDENTIFIER,
	@in_vchLocation			  NVARCHAR(50), 
	@in_vchParentLPN		  NVARCHAR(25),
	@in_vchLPN				  NVARCHAR(25), 
	@in_vchPickMode			  NVARCHAR(25),
	@in_vchWhItemMasterID	  UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID		  UNIQUEIDENTIFIER  = NULL,
	@in_vchItemNumber		  NVARCHAR(50) = NULL, 
	@in_vchLotNumber		  NVARCHAR(50) = NULL,  
	@in_vchExpiryDate		  NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd 
	@in_vchSerialNumber	      NVARCHAR(50) = NULL,
	@in_vchAttribute1	      NVARCHAR(100) = NULL,
	@in_vchAttribute2	      NVARCHAR(100) = NULL,
	@in_vchAttribute3	      NVARCHAR(100) = NULL,
	@in_vchAttribute4	      NVARCHAR(100) = NULL,
	@in_vchAttribute5	      NVARCHAR(100) = NULL,
	@in_vchReasonCode	      NVARCHAR(20) = NULL,

	@in_vchOverLocationID	  UNIQUEIDENTIFIER,
	@in_vchOverLocation		  NVARCHAR(50),
	@in_vchOverLPN			  NVARCHAR(25),
	@in_vchOverWhItemMasterID UNIQUEIDENTIFIER  = NULL,
	@in_vchOverItemMasterID	  UNIQUEIDENTIFIER  = NULL,
	@in_vchOverItemNumber     NVARCHAR(50) = NULL, 
	@in_vchOverLotNumber      NVARCHAR(50) = NULL,
	@in_vchOverExpiryDate     NVARCHAR(20) = NULL	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchReasonType varchar(50) = ''
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					-- กรณีที่ไม่ให้ช่วยกันหยิบ
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code IN ('RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING','BLIND_PICK_ORDER_TYPE')  AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'SYSTEM'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '') 
					ORDER BY outbound_order_number
				END
			ELSE
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code IN ('RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING','BLIND_PICK_ORDER_TYPE')  AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'SYSTEM' 
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY outbound_order_number
				END
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Box Number
			----------------------------------------------------------
			SELECT DISTINCT packDT.lpn_pack AS value_member
				,packDT.lpn_pack AS display_member
			FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
			INNER JOIN t_wms_outbound_pack_detail packDT WITH (NOLOCK) ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id
			WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
			AND packDT.lpn_pack NOT IN (select staging_lpn from t_wms_outbound_pack_detail where outbound_pick_detail_id = packDT.outbound_pick_detail_id AND ISNULL(staging_lpn,'') <> '')
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			SELECT DISTINCT value_member
				,display_member
			FROM (SELECT pickDT.location_id AS value_member
					,loc.location AS display_member
					,CONVERT(INT,obDT.line_number) AS line_number
					,ROW_NUMBER() OVER(PARTITION BY loc.location ORDER BY loc.pick_sequence,loc.location,CONVERT(INT,obDT.line_number)) AS is_min
				  FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
				  INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
				  INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
				  WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
				  AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
				  AND pickDT.is_override = 'NO') outbound
			WHERE outbound.is_min = 1
			RETURN; 
		END
	IF (@in_vchControlName IN ('STAGING_LOCATION','STAGING_SHORT_PICK'))
		BEGIN
			----------------------------------------------------------
			-- Binding Location for STG Button
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE  wh_master_id =  @in_vchWhMasterID
			AND loc_type = 'STG'
			AND is_active = 'YES'
			ORDER BY location
			RETURN; 
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT DISTINCT pickDT.parent_lpn AS value_member
				,pickDT.parent_lpn AS display_member
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') <> ''
			ORDER by pickDT.parent_lpn
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT pickDT.lpn AS value_member
				,pickDT.lpn AS display_member
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') <> ''
			ORDER BY pickDT.lpn 
			RETURN; 
		END
	IF @in_vchControlName = 'PICK_MODE'
		BEGIN
			SELECT value_member
				,display_member
			FROM t_com_combobox_item
			WHERE group_name = 'PICK_MODE'
			AND is_active = 'YES'
			ORDER BY display_sequence
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT item.value_member
				,item.display_member
			FROM (SELECT obDT.item_master_id AS value_member
	  				,obDT.item_number AS display_member
	  				,ROW_NUMBER() OVER(PARTITION BY obDT.item_number ORDER BY CONVERT(INT,obDT.line_number)) AS is_min
	  				,CONVERT(INT,obDT.line_number) AS line_number
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
					AND pickDT.location_id = @in_vchLocationID
					AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
					AND pickDT.is_override = 'NO'
					AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
					) item
			WHERE item.is_min = 1
			ORDER BY CONVERT(INT,item.line_number)
			RETURN; 
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT DISTINCT lot_number	AS value_member
				,lot_number	AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			ORDER BY lot_number
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT DISTINCT CONVERT(DATE,expiry_date)	AS value_member
				,CONVERT(DATE,expiry_date)	AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY CONVERT(DATE,expiry_date)
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT DISTINCT attribute1	AS value_member
				,attribute1	 AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY attribute1 
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT DISTINCT attribute2	AS value_member
				,attribute2	 AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			ORDER BY attribute2
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT DISTINCT attribute3	AS value_member
				,attribute3	 AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			ORDER BY attribute3
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			SELECT DISTINCT attribute4	AS value_member
				,attribute4	 AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			ORDER BY attribute4
			RETURN; 
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			SELECT DISTINCT attribute5	AS value_member
				,attribute5	 AS  display_member
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY attribute5
			RETURN; 
		END 
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT pickDT.receive_date
				,pickDT.serial_number
				,invST.inventory_status_id
			INTO #tPick
			FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
			INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			INNER JOIN t_wms_inventory_status invST ON obDT.default_item_status = invST.inv_status
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
			AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')

			SELECT serial_number 
			INTO #tPickOther
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id <> @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) = 0
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') <> ''

			--ถ้าไม่มี Serial ที่เป็นค่าว่างเลยให้ดึงจาก Plan แสดงว่ามีการระบุ Serial มาทั้งหมด
			IF NOT EXISTS (SELECT * FROM #tPick WHERE ISNULL(serial_number,'') = '')
				BEGIN
					SELECT serial_number AS value_member
						,serial_number AS display_member
					FROM #tPick
					ORDER BY serial_number
				END
			ELSE
				BEGIN
					--Serial ดึงจาก Inventory
					SELECT serial_number AS value_member
						,serial_number AS display_member
					FROM v_wms_inventory_data_serial_by_id WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND receive_date IN (SELECT receive_date FROM #tPick)
					AND serial_number NOT IN (SELECT serial_number FROM #tPickOther)
					AND inventory_status_id IN (SELECT inventory_status_id FROM #tPick)
					ORDER BY serial_number
					print 'inv'
				END
			RETURN; 
		END 
	IF @in_vchControlName = 'CONT_NUMBER'
		BEGIN
			RETURN; 
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
	IF @in_vchControlName = 'REASON_NEXT_LOCATION'
		BEGIN
			SET @v_vchReasonType = 'PickNextLocation'
			GOTO REASON;
		END
	IF @in_vchControlName = 'REASON_STG'
		BEGIN
			SET @v_vchReasonType = 'ShortPick'
			GOTO REASON;
		END
	IF @in_vchControlName = 'REASON_OVER_PICK'
		BEGIN
			SET @v_vchReasonType = 'OverPick'
			GOTO REASON;
		END
	IF @in_vchControlName = 'OVERRIDE_LOCATION'
		BEGIN
			--Override เฉพาะ Item ที่อยู่ใน Picklist
			SELECT loc.location_id AS value_member
				,loc.location AS display_member  
			FROM t_wms_location loc
			INNER JOIN (SELECT DISTINCT inv.location_id FROM t_wms_inventory inv WITH (NOLOCK)
						INNER JOIN (SELECT pickDT.wh_item_master_id
										,invST.inventory_status_id
										,pickDT.location_id
									FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
									INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
									INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
									INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
									WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
									AND is_override = 'NO' 
									AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
									) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id AND inv.location_id <> tOutbound.location_id
						) tInv ON tInv.location_id = loc.location_id
			WHERE loc.is_active = 'YES'
			AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			ORDER BY loc.pick_sequence,loc.location,loc.loc_type
			RETURN; 
		END
	IF @in_vchControlName = 'OVERRIDE_LPN'
		BEGIN
			--Override เฉพาะ Item ที่อยู่ใน Picklist 
			SELECT DISTINCT inv.lpn AS value_member
				,inv.lpn AS display_member  
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN (SELECT pickDT.wh_item_master_id
							,invST.inventory_status_id
							,pickDT.lpn
						FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
						INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
						INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND is_override = 'NO' 
						AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
						) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id --AND inv.lpn <> tOutbound.lpn
 			WHERE inv.location_id = (CASE WHEN @in_vchOverLocationID IS NULL THEN @in_vchLocationID ELSE @in_vchOverLocationID END)
			AND ISNULL(inv.lpn,'') <> ''
			ORDER BY inv.lpn
			RETURN; 
		END
	IF @in_vchControlName = 'OVERRIDE_ITEM_NUMBER'
		BEGIN 
			--Override เฉพาะ Item ที่อยู่ใน Picklist 
			SELECT DISTINCT tOutbound.item_master_id AS value_member
				,tOutbound.item_number AS display_member  
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN (SELECT pickDT.wh_item_master_id
							,invST.inventory_status_id
							,obDT.item_master_id  
	  						,obDT.item_number
	  						,ROW_NUMBER() OVER(PARTITION BY obDT.item_number ORDER BY CONVERT(INT,obDT.line_number)) AS is_min
	  						,CONVERT(INT,obDT.line_number) AS line_number
						FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
						INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
						INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND is_override = 'NO' 
						AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
						) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id 
 			WHERE inv.location_id = (CASE WHEN @in_vchOverLocationID IS NULL THEN @in_vchLocationID ELSE @in_vchOverLocationID END)
			AND ISNULL(inv.lpn,'') = (CASE WHEN ISNULL(@in_vchOverLPN,'') = '' THEN ISNULL(@in_vchLPN,'') ELSE ISNULL(@in_vchOverLPN,'') END)
			AND tOutbound.is_min = 1
			ORDER BY tOutbound.item_number
			RETURN;
		END
	IF @in_vchControlName = 'OVERRIDE_LOT_NUMBER'
		BEGIN
			--Override เฉพาะ Item ที่อยู่ใน Picklist
			SELECT DISTINCT inv.lot_number AS value_member
				,inv.lot_number AS display_member  
			FROM v_wms_inventory_data_by_id inv WITH (NOLOCK)
			INNER JOIN (SELECT  pickDT.wh_item_master_id
							,invST.inventory_status_id
							,pickDT.lot_number
						FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
						INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
						INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND is_override = 'NO' 
						AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
						) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id --AND ISNULL(inv.lot_number,'') <> ISNULL(tOutbound.lot_number,'')
 			WHERE inv.location_id = (CASE WHEN @in_vchOverLocationID IS NULL THEN @in_vchLocationID ELSE @in_vchOverLocationID END)
			AND ISNULL(inv.lpn,'') = (CASE WHEN ISNULL(@in_vchOverLPN,'') = '' THEN ISNULL(@in_vchLPN,'') ELSE ISNULL(@in_vchOverLPN,'') END)
			AND inv.wh_item_master_id = @in_vchOverWhItemMasterID
			--AND ISNULL(inv.lot_number,'') NOT IN (SELECT ISNULL(lot_number,'') FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID AND wh_item_master_id = @in_vchOverWhItemMasterID)
			ORDER BY inv.lot_number
			RETURN;
		END
	IF @in_vchControlName = 'OVERRIDE_EXPIRY_DATE'
		BEGIN
			--Override เฉพาะ Item ที่อยู่ใน Picklist
			SELECT DISTINCT inv.expiry_date AS value_member
				,inv.expiry_date AS display_member  
			FROM v_wms_inventory_data_by_id inv
			INNER JOIN (SELECT pickDT.wh_item_master_id
							,invST.inventory_status_id
							,pickDT.expiry_date
						FROM t_wms_outbound_pick_master pickMS
						INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
						INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND is_override = 'NO' 
						AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
						) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id --AND ISNULL(inv.expiry_date,'') <> ISNULL(tOutbound.expiry_date,'')
 			WHERE inv.location_id = (CASE WHEN @in_vchOverLocationID IS NULL THEN @in_vchLocationID ELSE @in_vchOverLocationID END)
			AND ISNULL(inv.lpn,'') = (CASE WHEN ISNULL(@in_vchOverLPN,'') = '' THEN ISNULL(@in_vchLPN,'') ELSE ISNULL(@in_vchOverLPN,'') END)
			AND inv.wh_item_master_id = @in_vchOverWhItemMasterID
			AND ISNULL(inv.lot_number,'') = (CASE WHEN ISNULL(@in_vchOverLotNumber,'') = '' THEN ISNULL(@in_vchLotNumber,'') ELSE ISNULL(@in_vchOverLotNumber,'') END)
			--AND ISNULL(inv.expiry_date,'') NOT IN (SELECT ISNULL(expiry_date,'') FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID AND wh_item_master_id = @in_vchOverWhItemMasterID)
			ORDER BY inv.expiry_date
			RETURN;
		END
	IF @in_vchControlName = 'OVERRIDE_UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchOverItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END

	REASON:
		SELECT reason_id AS value_member
			, reason_code AS display_member
		FROM t_wms_reason
		WHERE reason_type = @v_vchReasonType
		AND is_active = 'YES'
		RETURN;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_unpick]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_unpick]
(
	@in_vchApplicationID	  VARCHAR(40),
	@in_vchControlName		  NVARCHAR(50),	--Current Screen
	@in_vchLocalID			  VARCHAR(40),
	@in_vchDeviceID			  NVARCHAR(50),
	@in_vchUserID			  NVARCHAR(25), 
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchWhID				  NVARCHAR(25),
	@in_vchOutboundMasterID	  UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID			  UNIQUEIDENTIFIER,
	@in_vchOwnerCode		  NVARCHAR(40),
	@in_vchStgLocationID	  UNIQUEIDENTIFIER,
	@in_vchStgLPN			  NVARCHAR(25),
	@in_vchWhItemMasterID	  UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID		  UNIQUEIDENTIFIER  = NULL,
	@in_vchItemNumber		  NVARCHAR(50) = NULL, 
	@in_vchLotNumber		  NVARCHAR(50) = NULL,  
	@in_vchExpiryDate		  NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd 
	@in_vchSerialNumber	      NVARCHAR(50) = NULL,
	@in_vchAttribute1	      NVARCHAR(100) = NULL,
	@in_vchAttribute2	      NVARCHAR(100) = NULL,
	@in_vchAttribute3	      NVARCHAR(100) = NULL,
	@in_vchAttribute4	      NVARCHAR(100) = NULL,
	@in_vchAttribute5	      NVARCHAR(100) = NULL,
	@in_vchUomPrompt		  NVARCHAR(40) = NULL,
	@in_fltQuantity			  FLOAT,
	@in_vchLotControl		  VARCHAR(5) = NULL,
	@in_vchExpDateControl	  VARCHAR(5) = NULL,
	@in_vchSNControl		  VARCHAR(5) = NULL,
	@in_vchAttribute1Control  VARCHAR(5) = NULL,
	@in_vchAttribute2Control  VARCHAR(5) = NULL,
	@in_vchAttribute3Control  VARCHAR(5) = NULL,
	@in_vchAttribute4Control  VARCHAR(5) = NULL,
	@in_vchAttribute5Control  VARCHAR(5) = NULL,
	@out_vchErrorCode		  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		  NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			SELECT outbound_order_master_id	 AS value_member
				,outbound_order_number AS display_member
			FROM t_wms_outbound_master WITH (NOLOCK)
			WHERE order_status NOT IN ('OPEN','RELEASE','SHIP','CLOSE')
			AND wh_master_id = @in_vchWhMasterID
			AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
			ORDER BY outbound_order_number
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--'Pick and Pack'
					SELECT DISTINCT tPack.staging_lpn AS value_member
						, tPack.staging_lpn AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID
					AND ISNULL(tPack.staging_lpn,'') <> ''
					ORDER BY tPack.staging_lpn
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.staging_lpn AS value_member
						, pickDT.staging_lpn AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID
					AND ISNULL(pickDT.staging_lpn,'') <> ''
					ORDER BY pickDT.staging_lpn
					RETURN;
				END	 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT item.item_master_id AS value_member
						, item.item_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					INNER JOIN t_wms_wh_item whItem ON tPack.wh_item_master_id = whItem.wh_item_master_id
					INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					ORDER BY item.item_number
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT item.item_master_id AS value_member
						, item.item_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
					INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					ORDER BY item.item_number
					RETURN;
				END	
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.lot_number AS value_member
						, tPack.lot_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') <> ''
					ORDER BY tPack.lot_number
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.lot_number AS value_member
						, pickDT.lot_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') <> ''
					ORDER BY pickDT.lot_number
					RETURN;
				END	
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.expiry_date AS value_member
						, tPack.expiry_date AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') <> ''
					ORDER BY tPack.expiry_date
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.expiry_date AS value_member
						, pickDT.expiry_date AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') <> ''
					ORDER BY pickDT.expiry_date
					RETURN;
				END
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.attribute1 AS value_member
						, tPack.attribute1 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') <> ''
					ORDER BY tPack.attribute1
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.attribute1 AS value_member
						, pickDT.attribute1 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') <> ''
					ORDER BY pickDT.attribute1
					RETURN;
				END
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.attribute2 AS value_member
						, tPack.attribute2 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(tPack.attribute2,'') <> ''
					ORDER BY tPack.attribute2
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.attribute2 AS value_member
						, pickDT.attribute2 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') <> ''
					ORDER BY pickDT.attribute2
					RETURN;
				END
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.attribute3 AS value_member
						, tPack.attribute3 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(tPack.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(tPack.attribute3,'') <> ''
					ORDER BY tPack.attribute3
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.attribute3 AS value_member
						, pickDT.attribute3 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(pickDT.attribute3,'') <> ''
					ORDER BY pickDT.attribute3
					RETURN;
				END
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.attribute4 AS value_member
						, tPack.attribute4 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(tPack.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(tPack.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(tPack.attribute4,'') <> ''
					ORDER BY tPack.attribute4
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.attribute4 AS value_member
						, pickDT.attribute4 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(pickDT.attribute4,'') <> ''
					ORDER BY pickDT.attribute4
					RETURN;
				END
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.attribute5 AS value_member
						, tPack.attribute5 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(tPack.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(tPack.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(tPack.attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(tPack.attribute5,'') <> ''
					ORDER BY tPack.attribute5
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.attribute5 AS value_member
						, pickDT.attribute5 AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(pickDT.attribute5,'') <> ''
					ORDER BY pickDT.attribute5
					RETURN;
				END
		END 
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Get WH_RULE Rule pick pack
			----------------------------------------------------------
			IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
				BEGIN
					--Pick and Pack
					SELECT DISTINCT tPack.serial_number AS value_member
						, tPack.serial_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					INNER JOIN t_wms_outbound_pack_detail tPack WITH (NOLOCK) ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND tPack.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND tPack.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(tPack.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(tPack.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(tPack.attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(tPack.attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(tPack.serial_number,'') <> ''
					ORDER BY tPack.serial_number
					RETURN;
				END
			ELSE
				BEGIN
					--pick
					SELECT DISTINCT pickDT.serial_number AS value_member
						, pickDT.serial_number AS display_member 
					FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(pickDT.quantity_pick,0) > 0
					AND pickDT.is_override = 'NO'
					AND pickDT.staging_location_id = @in_vchStgLocationID 
					AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(pickDT.serial_number,'') <> ''
					ORDER BY pickDT.serial_number
					RETURN;
				END
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			AND is_active = 'YES'
			ORDER BY [sequence]
			RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_binding_user_pick_load]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_binding_user_pick_load]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25), 
	@in_vchLoadID			NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchOwnerCode		NVARCHAR(40),
	@in_vchBoxNumber		NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchItemStatus		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchPickRule			NVARCHAR(50) = ''
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
	DECLARE @v_vchExpDate		NVARCHAR(50) = ''
	DECLARE @v_vchInvStatusID	UNIQUEIDENTIFIER = NULL
	IF ISNULL(@in_vchItemStatus,'') <> ''
		BEGIN
			SELECT TOP 1 @v_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status where inv_status = @in_vchItemStatus
		END

	IF @in_vchControlName IN ('LOT_NUMBER','EXPIRY_DATE','ATTRIBUTE1','ATTRIBUTE2','ATTRIBUTE3','ATTRIBUTE4','ATTRIBUTE5')
		BEGIN
			/*  
				RULE_PICK_BY_PICK_LOCATION	> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FIFO			> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FEFO			> ORDER BY expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
			*/

			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Rule ที่กำหนด 
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @v_vchInvStatusID
			AND CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(lot_number,'') END = CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE  ISNULL(@in_vchLotNumber,'') END 
			AND CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(expiry_date,'') END = CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(attribute1,'') END = CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute1,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(attribute2,'') END = CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute2,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(attribute3,'') END = CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute3,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(attribute4,'') END = CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute4,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(attribute5,'') END = CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute5,'') END
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')
		END
	IF @in_vchControlName = 'LOAD_ID'
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
				BEGIN
					----------------------------------------------------------
					-- Binding Load ID
					-- กรณีที่ไม่ให้ช่วยกันหยิบ
					----------------------------------------------------------
					SELECT DISTINCT load_id	 AS value_member
						,load_id AS display_member
					FROM t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'USER_GROUP'
					AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY load_id
				END
			ELSE
				BEGIN
					----------------------------------------------------------
					-- Binding Load ID
					----------------------------------------------------------
					SELECT DISTINCT load_id	 AS value_member
						,load_id AS display_member
					FROM t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'USER_GROUP'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY load_id
				END
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Box Number
			----------------------------------------------------------
			SELECT DISTINCT packDT.lpn_pack AS value_member
				,packDT.lpn_pack AS display_member
			FROM t_wms_outbound_master obMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_master pickMS WITH (NOLOCK) ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id														
			INNER JOIN t_wms_outbound_pack_detail packDT WITH (NOLOCK) ON packDT.outbound_order_master_id = obMS.outbound_order_master_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID
			AND packDT.lpn_pack NOT IN (SELECT staging_lpn FROM t_wms_outbound_pack_detail WHERE outbound_pick_detail_id = packDT.outbound_pick_detail_id AND ISNULL(staging_lpn,'') <> '')
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS WITH (NOLOCK)
				INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT loc.location_id AS value_member
				,loc.location AS display_member  
			FROM t_wms_location loc
			INNER JOIN (SELECT DISTINCT location_id
						FROM t_wms_inventory inv WITH (NOLOCK)
						INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
						WHERE inv.wh_master_id = @in_vchWhMasterID
						AND inv.owner_id = @in_vchOwnerID
						AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM tOutbound)
						AND invST.inv_status IN (SELECT default_item_status FROM tOutbound)
					    ) tInv ON tInv.location_id = loc.location_id
			WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			ORDER BY loc.pick_sequence,loc.location 
			RETURN; 
		END
	IF @in_vchControlName = 'STAGING_LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for STG Button
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE  wh_master_id =  @in_vchWhMasterID
			AND loc_type = 'STG'
			AND is_active = 'YES'
			ORDER BY putaway_sequence, location
			RETURN; 
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT DISTINCT inv.parent_lpn AS value_member
				,parent_lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			ORDER BY parent_lpn
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS WITH (NOLOCK)
				INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT DISTINCT inv.lpn AS value_member
				,lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM tOutbound)
			AND invST.inv_status IN (SELECT default_item_status FROM tOutbound)
			ORDER BY lpn
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS WITH (NOLOCK)
				INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) on obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT DISTINCT item.item_master_id AS value_member
				,item.item_number AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
			AND inv.wh_item_master_id  IN (SELECT wh_item_master_id FROM tOutbound)
			ORDER BY item.item_number
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT DISTINCT obDT.default_item_status AS value_member
				,obDT.default_item_status AS display_member
			FROM t_wms_outbound_master obMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) on obMS.outbound_order_master_id = obDT.outbound_order_master_id
			WHERE wh_master_id = @in_vchWhMasterID
			AND load_id = @in_vchLoadID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT lot_number AS value_member
						,lot_number AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					ORDER BY lot_number
				END
			ELSE
				BEGIN
					SELECT DISTINCT lot_number AS value_member
						,lot_number AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					ORDER BY lot_number 
				END
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			/*------------------------------------------------------------
				Binding EXP เงื่อนไข ดังนี้
				1. ถ้า Plan ไม่ได้ระบุ EXP ให้ Check EXP ที่ Scan ใน Inventory
				2. ถ้า Plan ระบุ EXP จะต้องใส่ EXP ให้ตรงกับ Plan
				**หมายเหตุ หากมีการระบุ EXP จะต้องทุกรายการ ทุก Order ของ item นั้น
			-------------------------------------------------------------*/
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
