CREATE PROCEDURE [dbo].[usp_api_binding_user_pick_order]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchItemStatus			NVARCHAR(50) = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL, 
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchPickRule				NVARCHAR(50) = ''
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
	DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
	DECLARE @v_vchInvStatusID	UNIQUEIDENTIFIER = NULL
	IF ISNULL(@in_vchItemStatus,'') <> ''
		BEGIN
			SELECT TOP 1 @v_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status where inv_status = @in_vchItemStatus
		END

	IF @in_vchControlName IN ('LOT_NUMBER','EXPIRY_DATE','ATTRIBUTE1','ATTRIBUTE2','ATTRIBUTE3','ATTRIBUTE4','ATTRIBUTE5')
		BEGIN
			/*  
				RULE_PICK_BY_PICK_LOCATION	> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FIFO			> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FEFO			> ORDER BY expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
			*/

			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Rule ที่กำหนด 
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @v_vchInvStatusID
			AND CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(lot_number,'') END = CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE  ISNULL(@in_vchLotNumber,'') END 
			AND CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(expiry_date,'') END = CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(attribute1,'') END = CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute1,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(attribute2,'') END = CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute2,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(attribute3,'') END = CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute3,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(attribute4,'') END = CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute4,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(attribute5,'') END = CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute5,'') END
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')
		END

	IF @in_vchControlName = 'ORDER_NUMBER'
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					-- กรณีที่ไม่ให้ช่วยกันหยิบ
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'USER'
					AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY outbound_order_number
				END
			ELSE
				BEGIN
					----------------------------------------------------------
					-- Binding Outbound Order Number
					----------------------------------------------------------
					SELECT outbound_order_master_id	 AS value_member
						,outbound_order_number		 AS display_member
					FROM dbo.t_wms_outbound_master WITH (NOLOCK)
					WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
					AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
					AND wh_master_id = @in_vchWhMasterID
					AND pick_type = 'USER'
					AND owner_id IN (SELECT owner_id FROM t_wms_owner_user WHERE user_id = @in_vchUserID)
					ORDER BY outbound_order_number
				END
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Box Number
			----------------------------------------------------------
			SELECT DISTINCT packDT.lpn_pack AS value_member
				,packDT.lpn_pack AS display_member
			FROM t_wms_outbound_pick_master pickMS WITH (NOLOCK)
			INNER JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
			INNER JOIN t_wms_outbound_pack_detail packDT WITH (NOLOCK) ON pickDT.outbound_pick_detail_id = packDT.outbound_pick_detail_id
			WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
			AND packDT.lpn_pack NOT IN (select staging_lpn from t_wms_outbound_pack_detail where outbound_pick_detail_id = packDT.outbound_pick_detail_id AND ISNULL(staging_lpn,'') <> '')
			RETURN; 
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			SELECT obDT.wh_item_master_id
				,obDT.default_item_status
			INTO #tOutbound 
			FROM t_wms_outbound_detail obDT WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(obDT.quantity_pick,0) < ISNULL(obDT.quantity_order,0)

			SELECT loc.location_id AS value_member
				,loc.location AS display_member  
			FROM t_wms_location loc
			INNER JOIN (SELECT DISTINCT location_id
						FROM t_wms_inventory inv WITH (NOLOCK)
						INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
						WHERE inv.wh_master_id = @in_vchWhMasterID
						AND inv.owner_id = @in_vchOwnerID
						AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM #tOutbound)
						AND invST.inv_status IN (SELECT default_item_status FROM #tOutbound)
					    ) tInv ON tInv.location_id = loc.location_id
			WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			ORDER BY loc.pick_sequence,loc.location
			RETURN; 
		END
	IF @in_vchControlName = 'STAGING_LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for STG Button
			----------------------------------------------------------
			SELECT location_id  AS value_member
				,location	AS display_member
			FROM t_wms_location
			WHERE  wh_master_id =  @in_vchWhMasterID
			AND loc_type = 'STG'
			AND is_active = 'YES'
			ORDER BY putaway_sequence, location
			RETURN; 
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			SELECT DISTINCT inv.parent_lpn AS value_member
				,parent_lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			ORDER BY parent_lpn
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			SELECT DISTINCT inv.lpn AS value_member
				,lpn AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id = @in_vchWhMasterID 
			AND inv.owner_id = @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))
			AND invST.inv_status IN (SELECT default_item_status FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID)
			ORDER BY lpn
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT DISTINCT item.item_master_id AS value_member
				,item.item_number AS display_member
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))
			ORDER BY item.item_number
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			SELECT DISTINCT default_item_status AS value_member
				,default_item_status AS display_member
			FROM t_wms_outbound_detail WITH (NOLOCK)
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(default_item_status,'') <> ''
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN 
					SELECT DISTINCT lot_number AS value_member
						,lot_number AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					ORDER BY lot_number
				END
			ELSE
				BEGIN
					SELECT DISTINCT lot_number AS value_member
						,lot_number AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					ORDER BY lot_number 
				END
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			/*------------------------------------------------------------
				Binding EXP เงื่อนไข ดังนี้
				1. ถ้า Plan ไม่ได้ระบุ EXP ให้ Check EXP ที่ Scan ใน Inventory
				2. ถ้า Plan ระบุ EXP จะต้องใส่ EXP ให้ตรงกับ Plan
				**หมายเหตุ หากมีการระบุ EXP จะต้องทุกรายการ ทุก Order ของ item นั้น
			-------------------------------------------------------------*/
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT expiry_date AS value_member
						,expiry_date AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date
				END
			ELSE
				BEGIN
					SELECT DISTINCT expiry_date AS value_member
						,expiry_date AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date 
				END
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT attribute1 AS value_member
						,attribute1 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					ORDER BY attribute1
				END
			ELSE
				BEGIN
					SELECT DISTINCT attribute1 AS value_member
						,attribute1 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					ORDER BY attribute1 
				END
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT attribute2 AS value_member
						,attribute2 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					ORDER BY attribute2
				END
			ELSE
				BEGIN
					SELECT DISTINCT attribute2 AS value_member
						,attribute2 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					ORDER BY attribute2 
				END
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT attribute3 AS value_member
						,attribute3 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					ORDER BY attribute3
				END
			ELSE
				BEGIN
					SELECT DISTINCT attribute3 AS value_member
						,attribute3 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					ORDER BY attribute3 
				END
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT attribute4 AS value_member
						,attribute4 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					ORDER BY attribute4
				END
			ELSE
				BEGIN
					SELECT DISTINCT attribute4 AS value_member
						,attribute4 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					ORDER BY attribute4 
				END
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT DISTINCT attribute5 AS value_member
						,attribute5 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					ORDER BY attribute5
				END
			ELSE
				BEGIN
					SELECT DISTINCT attribute5 AS value_member
						,attribute5 AS display_member
					FROM v_wms_inventory_for_user_pick WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					ORDER BY attribute5 
				END
			RETURN;
		END 
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT invSN.serial_number AS value_member
				,invSN.serial_number AS display_member
			FROM (SELECT inventory_id
						,attribute_group_id
					FROM v_wms_inventory_data_by_id WITH (NOLOCK)
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					) inv
			LEFT JOIN (SELECT inventory_id
						,attribute_group_id
						,attribute_value AS serial_number
					FROM dbo.t_wms_inventory_attribute WITH (NOLOCK)
					WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
					) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
			ORDER BY invSN.serial_number
			RETURN;
		END 
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			SELECT uom_prompt  AS value_member
				,uom_prompt	AS display_member
			FROM t_wms_item_uom
			WHERE item_master_id = @in_vchItemMasterID
			ORDER BY [sequence]
			RETURN;
		END
END
GO
