CREATE PROCEDURE [dbo].[usp_api_current_validate_blind_pick]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse			NVARCHAR(25) = NULL,
	@in_vchOwnerID				UNIQUEIDENTIFIER = NULL, 
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50) = NULL, 
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),

	@in_vchParentLPN			NVARCHAR(25) = NULL,
	@in_vchLPN					NVARCHAR(25) = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_fltDisplayDefaultQty	FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	DECLARE @v_vchLocation		NVARCHAR(50) = NULL
	DECLARE @v_fltQuantityPick	FLOAT = NULL

	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 

	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT TOP 1 @v_vchLocation = location 
			FROM v_wms_inventory_for_blind_pick 
			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id =  @in_vchOwnerID 
			AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND inventory_status_id = @in_vchInvStatusID 
			AND wh_item_master_id =  @in_vchWhItemMasterID

			--Get Quantity Pick
			SELECT @v_fltQuantityPick = CONVERT(VARCHAR,ROUND(ISNULL(SUM(obDT.quantity_pick),0),@Round))
			FROM t_wms_outbound_detail obDT
			INNER JOIN t_wms_outbound_master obMS on obDT.outbound_order_master_id = obMS.outbound_order_master_id
 			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.outbound_order_number = @in_vchOutboundOrderNumber
			AND obDT.wh_item_master_id = @in_vchWhItemMasterID

			SELECT @v_fltQuantityPick AS quantity_pick
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchLocation,'@param2','@param3','@param4','@param5')
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			 IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
				SET @in_fltDisplayDefaultQty = NULL

			SELECT TOP 1  uom_prompt
				, @in_fltDisplayDefaultQty AS qty 
			FROM t_wms_item_uom 
			WHERE item_master_id = @in_vchItemMasterID 
			AND primary_uom= 'YES' 
			AND is_active = 'YES'
			RETURN;
		END
END
GO
