CREATE PROCEDURE [dbo].[usp_api_current_validate_move_item_qty]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchWhID				NVARCHAR(25), 
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,	
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		NVARCHAR(50) = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_fltDisplayDefaultQty FLOAT,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT 
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'LPN'
		BEGIN
			--Default LPN กรณีที่เป็น Loction Unpick เนื่องจาก User อาจจะไม่รู้ LPN
			SELECT TOP 1 inv.lpn
			FROM t_wms_inventory inv
			INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
			WHERE inv.wh_master_id = @in_vchWhMasterID 
			AND inv.location_id = @in_vchSourceLocationID
			AND loc.loc_type = 'UNPICK'
			ORDER BY inv.lpn
		END
	IF @in_vchControlName = 'UOM_QTY'	
		BEGIN 
			IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
				SET @in_fltDisplayDefaultQty = NULL

			SELECT TOP 1  uom_prompt, @in_fltDisplayDefaultQty AS qty FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom= 'YES' AND is_active = 'YES'
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION_DESTINATION'
		BEGIN
			DECLARE @v_vchSuggestLocationID UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchSuggestLocation	NVARCHAR(50) = NULL

			EXEC usp_putaway_rule @in_vchWhMasterID		  	= @in_vchWhMasterID		  
								 ,@in_vchOwnerID			= @in_vchOwnerID			  
								 ,@in_vchItemNumber		  	= @in_vchItemNumber		  
								 ,@in_vchLocation			= @in_vchSourceLocation			  
								 ,@out_vchSuggestLocationID = @v_vchSuggestLocationID OUTPUT
								 ,@out_vchSuggestLocation	= @v_vchSuggestLocation OUTPUT
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_SUGGEST_LOCATION',@in_vchLocalID,@v_vchSuggestLocation,'@param2','@param3','@param4','@param5')
			RETURN;
		END 
END
GO
