/****** Object:  StoredProcedure [dbo].[usp_api_current_validate_receipt]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_receipt]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER, 
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchItemMasterID		 UNIQUEIDENTIFIER,
	@in_intItemShelfLife     INT = 0,
	@in_dtMFGDate			 DATE = NULL,
	@in_vchUomPrompt		 NVARCHAR(40) = NULL,
	@in_fltDisplayDefaultQty FLOAT,
	@in_vchAlternateID		 UNIQUEIDENTIFIER = NULL,
	@in_vchCrossRefUOMID	 UNIQUEIDENTIFIER = NULL,
	@in_vchCrossRefUomPrompt NVARCHAR(40) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT 
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES'
				BEGIN
					-----------------------------------------------------
					-- Use mfg date to calculate expiry date
					-- ส่งกลับหน้าจอเพื่อให้แทนค่า Expiry Date
					-----------------------------------------------------
					IF @in_dtMFGDate = NULL 
						SET @in_dtMFGDate = GETDATE()
					SELECT DATEADD(DAY,@in_intItemShelfLife,  @in_dtMFGDate) AS expiry_date
				END
			SET @out_vchErrorCode = '0'	   
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			DECLARE @Round INT
			DECLARE @v_fltQuantityOrder			FLOAT = 0
			DECLARE @v_fltQuantityReceipt		FLOAT = 0
			DECLARE @v_fltQuantityRemainReceipt FLOAT = 0
			SELECT @Round = value FROM t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'
			SELECT @v_fltQuantityOrder = ROUND(SUM(ISNULL(ibDT.quantity_order,0)),@round)
				 ,@v_fltQuantityReceipt = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round)
				 ,@v_fltQuantityRemainReceipt = ROUND(SUM(quantity_order - quantity_receive),@Round)
			FROM t_wms_inbound_detail ibDT WITH (NOLOCK)
 			LEFT JOIN t_wms_item_uom uom on ibDT.item_uom_id = uom.item_uom_id
			WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
			AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
			GROUP BY ibDT.wh_item_master_id 
			SELECT @v_fltQuantityOrder	  AS quantity_order
				, @v_fltQuantityReceipt   AS quantity_receive
				, ISNULL(@v_fltQuantityRemainReceipt,0)  AS quantity_remain_receive 
		END
	IF @in_vchControlName = 'UOM_QTY'	
		BEGIN 
			IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
				SET @in_fltDisplayDefaultQty = NULL
			IF @in_vchAlternateID is not null
				BEGIN
					SELECT @in_vchCrossRefUomPrompt AS uom_prompt
						, NULL AS qty
				END
			ELSE
				BEGIN
					SELECT TOP 1 uom_prompt
						, @in_fltDisplayDefaultQty AS qty 
					FROM t_wms_item_uom 
					WHERE item_master_id = @in_vchItemMasterID 
					AND primary_uom= 'YES' AND is_active = 'YES'
				END 
			RETURN;
		END
END
GO
