GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_system_pick_load]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchBoxNumber			NVARCHAR(25),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltDisplayDefaultQty	FLOAT, 
	@in_vchLotControl			VARCHAR(10) = NULL,	
	@in_vchExpDateControl		VARCHAR(10) = NULL,	
	@in_vchSNControl			VARCHAR(10) = NULL,
	@in_vchAttribute1Control	VARCHAR(10) = NULL,
	@in_vchAttribute2Control	VARCHAR(10) = NULL,
	@in_vchAttribute3Control	VARCHAR(10) = NULL,
	@in_vchAttribute4Control	VARCHAR(10) = NULL,
	@in_vchAttribute5Control	VARCHAR(10) = NULL, 
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	@in_vchOverPickReasonCode	NVARCHAR(20) = NULL,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255)	--For display on screen in information loyout
	DECLARE @v_vchItemNumber	NVARCHAR(50) = ''
	DECLARE @v_vchLotNumber		NVARCHAR(50) = ''
	DECLARE @v_vchExpiryDate	NVARCHAR(10) = ''
	DECLARE @v_fltQtyPlan		FLOAT
	DECLARE @v_fltQtyPick		FLOAT
	DECLARE @Round				INT
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	 
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT TOP 1 @v_vchMessage = location
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			ORDER BY pick_sequence,location, CONVERT(INT,line_number)
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			--Display Message 
			SELECT TOP 1 @v_vchMessage = lpn
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			and location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') <> ''
			ORDER BY lpn 
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LPN_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			--Display Message
			SELECT TOP 1 @v_vchItemNumber = item_number
				,@v_vchLotNumber = lot_number
				,@v_vchExpiryDate = CONVERT(DATE,expiry_date)
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			and location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			ORDER BY line_number
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_DETAIL_DISPLAY',@in_vchLocalID,@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,'@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			--Display Message
			SELECT TOP 1 @v_vchMessage = lot_number
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			and location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			ORDER BY lot_number
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOT_NUMBER_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			--Display Message
			DECLARE @v_dtExpiryDate DATE
			SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
				,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			and location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY expiry_date 
			 
			SELECT @v_dtExpiryDate as expiry_date
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_EXPIRY_DATE_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SELECT @v_fltQtyPlan = SUM(ISNULL(quantity_plan,0))
				,@v_fltQtyPick = SUM(ISNULL(quantity_pick,0))
			FROM t_wms_outbound_pick_detail_by_group pickGroup
			WHERE pickGroup.wh_master_id = @in_vchWhMasterID 
			AND ISNULL(pickGroup.load_id,'') = @in_vchLoadID
			AND pickGroup.location_id = @in_vchLocationID
			AND pickGroup.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickGroup.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickGroup.lpn,'') = ISNULL(@in_vchLPN,'')

			SELECT CONVERT(VARCHAR,ROUND(@v_fltQtyPlan,@Round)) AS quantity_plan
				,CONVERT(VARCHAR,ROUND(@v_fltQtyPick,@Round)) AS quantity_pick
				,'' AS serial_number
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			
			DECLARE @v_fltQtyRemainPick	FLOAT 
			DECLARE @v_fltConversionFactor FLOAT = NULL 
			DECLARE @v_vchUomPrompt NVARCHAR(40) = NULL
			 
 			SELECT @v_fltQtyPlan = SUM(quantity_plan)
				, @v_fltQtyPick = SUM(quantity_pick)
				, @v_fltQtyRemainPick = ROUND(SUM(quantity_plan - quantity_pick),@Round)  
			FROM v_wms_outbound_pick_detail_by_load
			WHERE wh_master_id = @in_vchWhMasterID 
			AND ISNULL(load_id,'') = @in_vchLoadID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			and location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
		
 			IF dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE
				END

			DECLARE @v_fltQtyInt	FLOAT = NULL
			DECLARE @v_fltQtyMod	FLOAT = NULL
			DECLARE @v_intNextSeq	INT = NULL 
			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC 
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_UOM;
							END
					END
		
			DISPLAY_MESSAGE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SELECT TOP 1 uom_prompt, @in_fltDisplayDefaultQty AS qty FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom= 'YES' AND is_active = 'YES'
				 
				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_REMAIN_PICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_current_validate_system_pick_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_system_pick_lpn]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40), 
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchLPN					NVARCHAR(25), 
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255)	--For display on screen in information loyout
	DECLARE @Round				INT 
	 
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	 IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT TOP 1 @v_vchMessage = loc.location
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			ORDER BY loc.pick_sequence,loc.location, CONVERT(INT,obDT.line_number)
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END

	IF @in_vchControlName = 'LPN'
		BEGIN
			--Display Message 
			DECLARE @v_vchLPN NVARCHAR(25)
			SELECT TOP 1 @v_vchLPN = pickDT.lpn
			FROM  t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.lpn,'') <> ''
			ORDER BY obDT.line_number	 
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LPN',@in_vchLocalID,@v_vchLPN,'@param2','@param3','@param4','@param5')
			RETURN;
		END
END
GO
