CREATE PROCEDURE [dbo].[usp_api_current_validate_system_pick_order]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),  
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_fltDisplayDefaultQty	FLOAT,

	@in_vchOverLocationID		UNIQUEIDENTIFIER,
	@in_vchOverLocation			NVARCHAR(50),
	@in_vchOverLPN				NVARCHAR(25),
	@in_vchOverWhItemMasterID	UNIQUEIDENTIFIER  = NULL,
	@in_vchOverItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchOverLotNumber		NVARCHAR(50) = NULL,
	@in_vchOverExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	--@in_fltOverDefaultQty		FLOAT,

	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255)	--For display on screen in information loyout
	DECLARE @Round				INT 
	DECLARE @v_fltQtyPlan		FLOAT
	DECLARE @v_fltQtyPick		FLOAT
	DECLARE @v_fltQtyRemainPick	FLOAT 
	DECLARE @v_fltConversionFactor FLOAT = NULL 
	DECLARE @v_vchUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_fltQtyInt		FLOAT = NULL
	DECLARE @v_fltQtyMod		FLOAT = NULL
	DECLARE @v_intNextSeq		INT = NULL 
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	DECLARE @v_vchItemNumber	NVARCHAR(50) = ''
	DECLARE @v_vchLotNumber		NVARCHAR(50) = ''
	DECLARE @v_vchExpiryDate	NVARCHAR(10) = ''

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT TOP 1 @v_vchMessage = loc.location
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			ORDER BY loc.pick_sequence,loc.location, CONVERT(INT,obDT.line_number)
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			--Display Message 
			SELECT TOP 1 @v_vchItemNumber = obDT.item_number
				,@v_vchLotNumber = pickDT.lot_number
				,@v_vchExpiryDate = CONVERT(DATE,pickDT.expiry_date)
			FROM  t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') <> ''
			ORDER BY obDT.line_number	 
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_DETAIL_DISPLAY',@in_vchLocalID,@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,'@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			--Display Message 
			SELECT TOP 1 @v_vchItemNumber = obDT.item_number
				,@v_vchLotNumber = pickDT.lot_number
				,@v_vchExpiryDate = CONVERT(DATE,pickDT.expiry_date)
			FROM  t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
			AND pickDT.location_id = @in_vchLocationID
			AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
			AND pickDT.is_override = 'NO'
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
			ORDER BY obDT.line_number	 
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_DETAIL_DISPLAY',@in_vchLocalID,@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,'@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			--Display Message 
			SELECT TOP 1 @v_vchMessage = lot_number
			FROM t_wms_outbound_pick_detail
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			ORDER BY lot_number 
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOT_NUMBER_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			--Display Message 
			DECLARE @v_dtExpiryDate DATE
			SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
				,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
			FROM t_wms_outbound_pick_detail
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND location_id = @in_vchLocationID
			AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
			AND is_override = 'NO'
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY expiry_date 
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_EXPIRY_DATE_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			SELECT @v_dtExpiryDate as expiry_date
			RETURN; 
		END
	IF @in_vchControlName IN ('UOM_QTY','SERIAL_NUMBER')
		BEGIN
 			SELECT @v_fltQtyPlan = SUM(pickDT.quantity_plan)
				, @v_fltQtyPick = SUM(pickDT.quantity_pick)
				, @v_fltQtyRemainPick = ROUND(SUM(pickDT.quantity_plan - pickDT.quantity_pick),@Round)  
			FROM t_wms_outbound_pick_detail pickDT
 			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND pickDT.location_id  = @in_vchLocationID
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND pickDT.is_override = 'NO'
		
 			IF  dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE
				END

			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC 
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_UOM;
							END
					END
		
			DISPLAY_MESSAGE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SELECT TOP 1 uom_prompt
					, @in_fltDisplayDefaultQty AS qty
					, '' as serial_number 
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom= 'YES' AND is_active = 'YES'

				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_REMAIN_PICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END
	IF @in_vchControlName IN ('OVERRIDE_UOM_QTY','OVERRIDE_SERIAL_NUMBER')
		BEGIN
			--Case Override ไม่สามารถ Where อื่นๆ ได้ เพราะไม่รู้ว่าต้องการ Override แบบไหน
 			SELECT @v_fltQtyPlan = SUM(pickDT.quantity_plan)
				, @v_fltQtyPick = SUM(pickDT.quantity_pick)
				, @v_fltQtyRemainPick = ROUND(SUM(pickDT.quantity_plan - pickDT.quantity_pick),@Round)  
			FROM t_wms_outbound_pick_detail pickDT
 			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			--AND pickDT.location_id  = @in_vchOverLocationID
			--AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			--AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchOverrideLPN,'')
			AND wh_item_master_id = @in_vchOverWhItemMasterID
			--AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchOverrideLotNumber,'')
			--AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchOverrideExpiryDate,'')
			--AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchOverrideAttribute1,'')
			--AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchOverrideAttribute2,'')
			--AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchOverrideAttribute3,'')
			--AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchOverrideAttribute4,'')
			--AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchOverrideAttribute5,'')
			AND pickDT.is_override = 'NO'
		
 			IF  dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchOverItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE_OVERRIDE;
				END
			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_OVERRIDE_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchOverItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC 
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_OVERRIDE_UOM;
							END
					END
		
			DISPLAY_MESSAGE_OVERRIDE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SELECT TOP 1 uom_prompt AS override_uom_prompt, @in_fltDisplayDefaultQty AS override_qty, '' as serial_number FROM t_wms_item_uom WHERE item_master_id = @in_vchOverItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'

				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_REMAIN_PICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_current_validate_unpick]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_unpick]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchStgLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	@in_vchStgParentLPN			NVARCHAR(25) = NULL,
	@in_vchStgLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_fltDisplayDefaultQty	FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255)	--For display on screen in information loyout
	DECLARE @Round				INT
	DECLARE @v_fltQtyRemainPick	FLOAT 
	DECLARE @v_fltConversionFactor FLOAT = NULL 
	DECLARE @v_vchUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_fltQtyInt		FLOAT = NULL
	DECLARE @v_fltQtyMod		FLOAT = NULL
	DECLARE @v_intNextSeq		INT = NULL 
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
 			SELECT @v_fltQtyRemainPick = ROUND(SUM(ISNULL(pickDT.quantity_pick,0) - ISNULL(pickDT.quantity_pack,0)),@Round)  
			FROM t_wms_outbound_pick_detail pickDT
 			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND pickDT.staging_location_id  = @in_vchStgLocationID
			AND ISNULL(pickDT.staging_parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
			AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND pickDT.is_override = 'NO'
		
 			IF  dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE
				END

			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_UOM;
							END
					END
		
			DISPLAY_MESSAGE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SELECT TOP 1 uom_prompt, @in_fltDisplayDefaultQty AS qty FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom= 'YES' AND is_active = 'YES'

				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_QTY_UNPICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_current_validate_user_pick_load]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_user_pick_load]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),  
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchItemStatus			NVARCHAR(50) = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	@in_vchPickRule				NVARCHAR(50) = '',
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltDisplayDefaultQty	FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255) = ''	--For display on screen in information loyout
	DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
	DECLARE @v_vchExpDate		NVARCHAR(50) = ''

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF @in_vchControlName IN ('LOT_NUMBER','EXPIRY_DATE','ATTRIBUTE1','ATTRIBUTE2','ATTRIBUTE3','ATTRIBUTE4','ATTRIBUTE5')
		BEGIN
			/*
				RULE_PICK_BY_PICK_LOCATION	> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FIFO			> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FEFO			> ORDER BY expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
			*/

			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Rule ที่กำหนด 
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			AND CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(lot_number,'') END = CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE  ISNULL(@in_vchLotNumber,'') END 
			AND CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(expiry_date,'') END = CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(attribute1,'') END = CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute1,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(attribute2,'') END = CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute2,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(attribute3,'') END = CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute3,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(attribute4,'') END = CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute4,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(attribute5,'') END = CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute5,'') END
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS
				INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT TOP 1 @v_vchMessage = loc.location
			FROM t_wms_inventory inv
			INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM tOutbound)			 
			AND invST.inv_status IN (SELECT default_item_status FROM tOutbound)
			ORDER BY loc.pick_sequence,loc.location 

			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			--Display Message
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS
				INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT TOP 1 @v_vchMessage = inv.lpn
			FROM t_wms_inventory inv 
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM tOutbound)
			AND invST.inv_status IN (SELECT default_item_status FROM tOutbound) 
			ORDER BY lpn
					
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LPN_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			--Display Message
			;With tOutbound AS
			(
				SELECT obDT.wh_item_master_id
					,obDT.default_item_status 
				FROM t_wms_outbound_master obMS
				INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND load_id = @in_vchLoadID
				AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)
			)
			SELECT TOP 1 @v_vchMessage = item.item_number
			FROM t_wms_inventory inv
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM tOutbound)
			ORDER BY item.item_number
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_ITEM_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			--Display Message
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT TOP 1 @v_vchMessage = lot_number 
					FROM v_wms_inventory_for_user_pick 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					ORDER BY lot_number
				END
			ELSE
				BEGIN
					SELECT TOP 1 @v_vchMessage = lot_number
					FROM v_wms_inventory_for_user_pick
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND CONVERT(VARCHAR(8),receive_date,112) = @v_vchReceiveDate --WHERE From Pick Rule
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpDate,'')		 --WHERE From Pick Rule
					ORDER BY lot_number 
				END
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOT_NUMBER_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			DECLARE @v_dtExpiryDate DATETIME
			--Display Message 
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
						,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
					FROM v_wms_inventory_for_user_pick 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date
				END
			ELSE
				BEGIN
					SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
						,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
					FROM v_wms_inventory_for_user_pick
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND CONVERT(VARCHAR(8),receive_date,112) = @v_vchReceiveDate --WHERE From Pick Rule
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpDate,'')		 --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date 
				END
			
			SELECT @v_dtExpiryDate AS expiry_date
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_EXPIRY_DATE_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			DECLARE @Round				INT 
			DECLARE @v_fltQtyPlan		FLOAT
			DECLARE @v_fltQtyPick		FLOAT
			DECLARE @v_fltQtyRemainPick	FLOAT 
			DECLARE @v_fltConversionFactor FLOAT = NULL 
			DECLARE @v_vchUomPrompt		NVARCHAR(40) = NULL

			SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
			 
 			SELECT @v_fltQtyPlan = SUM(obDT.quantity_order)
				, @v_fltQtyPick = SUM(ISNULL(obDT.quantity_pick,0))
				, @v_fltQtyRemainPick = ROUND(SUM(obDT.quantity_order - ISNULL(obDT.quantity_pick,0)),@Round)  
			FROM t_wms_outbound_master obMS
			INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID
			AND obDT.wh_item_master_id = @in_vchWhItemMasterID 
		
 			IF  dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE
				END

			DECLARE @v_fltQtyInt	FLOAT = NULL
			DECLARE @v_fltQtyMod	FLOAT = NULL
			DECLARE @v_intNextSeq	INT = NULL 
			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC 
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_UOM;
							END
					END
		
			DISPLAY_MESSAGE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SELECT TOP 1 uom_prompt, @in_fltDisplayDefaultQty AS qty FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom= 'YES' AND is_active = 'YES'
				
				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_REMAIN_PICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_current_validate_user_pick_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_current_validate_user_pick_order]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),  
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchItemStatus			NVARCHAR(50) = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	@in_vchPickRule				NVARCHAR(50) = '',
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltDisplayDefaultQty	FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchMessage		NVARCHAR(255) = ''	--For display on screen in information loyout
	DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
	DECLARE @v_vchExpDate		NVARCHAR(50) = ''

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF @in_vchControlName IN ('LOT_NUMBER','EXPIRY_DATE','ATTRIBUTE1','ATTRIBUTE2','ATTRIBUTE3','ATTRIBUTE4','ATTRIBUTE5')
		BEGIN
			/*
				RULE_PICK_BY_PICK_LOCATION	> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FIFO			> ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
				RULE_PICK_BY_FEFO			> ORDER BY expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn
			*/

			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Rule ที่กำหนด 
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			AND CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(lot_number,'') END = CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE  ISNULL(@in_vchLotNumber,'') END 
			AND CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(expiry_date,'') END = CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(attribute1,'') END = CASE WHEN ISNULL(@in_vchAttribute1,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute1,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(attribute2,'') END = CASE WHEN ISNULL(@in_vchAttribute2,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute2,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(attribute3,'') END = CASE WHEN ISNULL(@in_vchAttribute3,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute3,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(attribute4,'') END = CASE WHEN ISNULL(@in_vchAttribute4,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute4,'') END
			AND CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(attribute5,'') END = CASE WHEN ISNULL(@in_vchAttribute5,'') = '' THEN '' ELSE ISNULL(@in_vchAttribute5,'') END
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			SELECT TOP 1 @v_vchMessage = loc.location
			FROM t_wms_inventory inv
			INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))			 
			AND invST.inv_status IN (SELECT default_item_status FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID)
			ORDER BY loc.pick_sequence,loc.location 

			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOCATION_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			--Display Message
			SELECT TOP 1 @v_vchMessage = inv.lpn
			FROM t_wms_inventory inv 
			INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))
			AND invST.inv_status IN (SELECT default_item_status FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID) 
			ORDER BY lpn
					
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LPN_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			--Display Message
			SELECT TOP 1 @v_vchMessage = item.item_number
			FROM t_wms_inventory inv
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.wh_master_id =  @in_vchWhMasterID 
			AND inv.owner_id =  @in_vchOwnerID
			AND inv.location_id = @in_vchLocationID
			AND ISNULL(inv.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')	
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
			AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))
			ORDER BY item.item_number
			 
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_ITEM_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			--Display Message
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT TOP 1 @v_vchMessage = lot_number 
					FROM v_wms_inventory_for_user_pick 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					ORDER BY lot_number
				END
			ELSE
				BEGIN
					SELECT TOP 1 @v_vchMessage = lot_number
					FROM v_wms_inventory_for_user_pick
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND CONVERT(VARCHAR(8),receive_date,112) = @v_vchReceiveDate --WHERE From Pick Rule
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpDate,'')		 --WHERE From Pick Rule
					ORDER BY lot_number 
				END
			
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_LOT_NUMBER_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			DECLARE @v_dtExpiryDate DATETIME
			--Display Message 
			IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
					AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
				BEGIN
					SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
						,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
					FROM v_wms_inventory_for_user_pick 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date
				END
			ELSE
				BEGIN
					SELECT TOP 1 @v_vchMessage = CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103)
						,@v_dtExpiryDate = CONVERT(DATE,expiry_date)
					FROM v_wms_inventory_for_user_pick
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inv_status = @in_vchItemStatus
					AND CONVERT(VARCHAR(8),receive_date,112) = @v_vchReceiveDate --WHERE From Pick Rule
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpDate,'')		 --WHERE From Pick Rule
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					ORDER BY expiry_date 
				END
			
			SELECT @v_dtExpiryDate AS expiry_date
			SET @out_vchErrorCode = '0'
			SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_PICK_EXPIRY_DATE_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
			RETURN; 
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			DECLARE @Round				INT 
			DECLARE @v_fltQtyPlan		FLOAT
			DECLARE @v_fltQtyPick		FLOAT
			DECLARE @v_fltQtyRemainPick	FLOAT 
			DECLARE @v_fltConversionFactor FLOAT = NULL 
			DECLARE @v_vchUomPrompt		NVARCHAR(40) = NULL

			SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
			 
 			SELECT @v_fltQtyPlan = SUM(quantity_order)
				, @v_fltQtyPick = SUM(ISNULL(quantity_pick,0))
				, @v_fltQtyRemainPick = ROUND(SUM(quantity_order - ISNULL(quantity_pick,0)),@Round)  
			FROM t_wms_outbound_detail
 			WHERE outbound_order_master_id = @in_vchOutboundMasterID 
			AND wh_item_master_id = @in_vchWhItemMasterID 
		
 			IF  dbo.IsInteger(@v_fltQtyRemainPick) = 0
				BEGIN
					SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'
					SET @v_vchMessage = CONVERT(VARCHAR,@v_fltQtyRemainPick) + ' ' + ISNULL(@v_vchUomPrompt,'')
					GOTO DISPLAY_MESSAGE
				END

			DECLARE @v_fltQtyInt	FLOAT = NULL
			DECLARE @v_fltQtyMod	FLOAT = NULL
			DECLARE @v_intNextSeq	INT = NULL 
			SET @v_fltQtyMod = @v_fltQtyRemainPick
		 
			NEXT_UOM: 
				SET @v_vchUomPrompt = NULL
				SET @v_fltConversionFactor = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt
					,@v_fltConversionFactor = conversion_factor
					,@v_intNextSeq = CONVERT(INT,[sequence])
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND (CASE WHEN @v_intNextSeq IS NULL THEN 0 ELSE [sequence] END) < (CASE WHEN @v_intNextSeq IS NULL THEN 1 ELSE @v_intNextSeq END)
				ORDER BY [sequence] DESC, conversion_factor DESC 
			
				IF ISNULL(@v_vchUomPrompt,'') <> ''
					BEGIN
						SET @v_fltQtyInt = CAST(@v_fltQtyMod AS INT) / CAST(@v_fltConversionFactor AS INT)
						SET @v_fltQtyMod = CAST(@v_fltQtyMod AS INT) % CAST(@v_fltConversionFactor AS INT)
					
						IF @v_fltQtyInt <> 0 
							BEGIN
								SET @v_vchMessage = ISNULL(@v_vchMessage,'') + CONVERT(VARCHAR,@v_fltQtyInt) + ' ' + ISNULL(@v_vchUomPrompt,'') + ' '
							END

						IF @v_fltQtyMod <> 0 
							BEGIN 
								GOTO NEXT_UOM;
							END
					END
		
			DISPLAY_MESSAGE:
				--Default UOM to Control
				IF (SELECT value FROM t_wms_rule WHERE rule_code = 'SCAN_2D_DEFAULT_QTY' AND is_active = 'YES') = 'NO' OR ISNULL(@in_fltDisplayDefaultQty,0) = 0
					SET @in_fltDisplayDefaultQty = NULL

				SET @v_vchUomPrompt = NULL
				SELECT TOP 1 @v_vchUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND primary_uom= 'YES' AND is_active = 'YES'
				

				SELECT @v_vchUomPrompt AS uom_prompt
					,@in_fltDisplayDefaultQty AS qty
					,@v_fltQtyPlan	AS quantity_plan
					,@v_fltQtyPick	AS quantity_pick
					,@v_fltQtyRemainPick AS quantity_remain_pick

				--Display Message 
				SET @out_vchErrorCode = '0'
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_REMAIN_PICK_DISPLAY',@in_vchLocalID,@v_vchMessage,'@param2','@param3','@param4','@param5')
				RETURN;
		END 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_initial_blind_pick]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_api_initial_blind_pick]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchUserID		  NVARCHAR(25),
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	-----------------------------------------------	
	-- Validate owner master
	-----------------------------------------------
	IF (SELECT COUNT(owner_id) FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND is_active = 'YES') = 1
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_BLIND_PICK_SHOW_CUSTOMER' and is_active = 'YES') = 'NO'
				BEGIN
					IF EXISTS (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'
								AND value IN (SELECT value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
						BEGIN
							--สำหรับกรณี Auto Insert Inbound
							SET @out_vchNextScreen = 'TO_WAREHOUSE'
							GOTO NEXT_SCREEN;
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'ORDER_NUMBER'
							GOTO NEXT_SCREEN;
						END
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'CUSTOMER'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'OWNER'
			RETURN;
		END
	
	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	--SELECT TOP 1  own.owner_id
	--	, own.owner_code
	--FROM t_wms_owner_user ownUser
	--INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
	--WHERE own.is_active = 'YES'
	--AND ownUser.user_id = @in_vchUserID
	RETURN; 
		
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
