CREATE PROCEDURE [dbo].[usp_api_initial_putaway]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,	
	@in_vchForkID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocalID			VARCHAR(40) = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchForkID)
		BEGIN
			SET @out_vchErrorCode = 'NO-WORK-EXIST'
			GOTO EXIT_LABEL;
		END
	ELSE
		BEGIN
			-- กรณีที่บน Fork ไม่มี Parent LPN ก็ไม่ต้องแสดงหน้าจอ ถึงแม้ว่า Wh Rule กำหนด Control Parent LPN 
			IF EXISTS (SELECT inventory_id FROM t_wms_inventory  WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchForkID AND parent_lpn <> '')
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END 
		END
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END


GO
