			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			EXEC usp_api_validate_blind_pick_attribute1 @in_vchApplicationID	 = @in_vchApplicationID	
													   ,@in_vchUserID			 = @in_vchUserID			
													   ,@in_vchWhMasterID		 = @in_vchWhMasterID		
													   ,@in_vchWarehouse		 = @in_vchWarehouse		
