													   ,@in_vchInvStatusID		 = @in_vchInvStatusID		 
													   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	 
													   ,@in_vchItemMasterID		 = @in_vchItemMasterID		 
													   ,@in_vchLocationID		 = @in_vchLocationID		 
													   ,@in_vchParentLPN		 = @in_vchParentLPN		 
													   ,@in_vchLPN				 = @in_vchLPN				 
													   ,@in_vchPickRule			 = @in_vchPickRule			 
													   ,@in_vchLotNumber		 = @in_vchLotNumber		 
													   ,@in_vchExpiryDate		 = @in_vchExpiryDate		 
													   ,@in_vchAttribute1		 = @in_vchAttribute1		 
													   ,@in_vchAttribute2		 = @in_vchAttribute2		 
													   ,@in_vchAttribute3		 = @in_vchAttribute3		 
													   ,@in_vchAttribute4Control = @in_vchAttribute4Control 
													   ,@in_vchAttribute5Control = @in_vchAttribute5Control 
													   ,@in_vchSNControl		 = @in_vchSNControl		 
													   ,@in_vchLocalID			 = @in_vchLocalID			 
													   ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT			 
													   ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT		 
													   ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT		 

			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_blind_pick_attribute4 @in_vchApplicationID	 = @in_vchApplicationID	 
													   ,@in_vchUserID			 = @in_vchUserID			 
													   ,@in_vchWhMasterID		 = @in_vchWhMasterID		 
													   ,@in_vchWarehouse		 = @in_vchWarehouse		 
													   ,@in_vchOwnerID			 = @in_vchOwnerID			 
													   ,@in_vchInvStatusID		 = @in_vchInvStatusID		 
													   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	 
													   ,@in_vchItemMasterID		 = @in_vchItemMasterID		 
													   ,@in_vchLocationID		 = @in_vchLocationID		 
													   ,@in_vchParentLPN		 = @in_vchParentLPN		 
													   ,@in_vchLPN				 = @in_vchLPN				 
													   ,@in_vchPickRule			 = @in_vchPickRule			 
													   ,@in_vchLotNumber		 = @in_vchLotNumber		 
													   ,@in_vchExpiryDate		 = @in_vchExpiryDate		 
													   ,@in_vchAttribute1		 = @in_vchAttribute1		 
													   ,@in_vchAttribute2		 = @in_vchAttribute2		 
													   ,@in_vchAttribute3		 = @in_vchAttribute3		 
													   ,@in_vchAttribute4		 = @in_vchAttribute4		 
													   ,@in_vchAttribute5Control = @in_vchAttribute5Control 
													   ,@in_vchSNControl		 = @in_vchSNControl		 
													   ,@in_vchLocalID			 = @in_vchLocalID			 
													   ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
													   ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
													   ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT		 

			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_blind_pick_attribute5 @in_vchApplicationID	= @in_vchApplicationID	
													   ,@in_vchUserID			= @in_vchUserID			
													   ,@in_vchWhMasterID		= @in_vchWhMasterID		
													   ,@in_vchWarehouse		= @in_vchWarehouse		  
													   ,@in_vchOwnerID			= @in_vchOwnerID			
													   ,@in_vchInvStatusID		= @in_vchInvStatusID		
													   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
													   ,@in_vchItemMasterID		= @in_vchItemMasterID		
													   ,@in_vchLocationID		= @in_vchLocationID		
													   ,@in_vchParentLPN		= @in_vchParentLPN		
													   ,@in_vchLPN				= @in_vchLPN				
													   ,@in_vchPickRule			= @in_vchPickRule			
													   ,@in_vchLotNumber		= @in_vchLotNumber		
													   ,@in_vchExpiryDate		= @in_vchExpiryDate		
													   ,@in_vchAttribute1		= @in_vchAttribute1		
													   ,@in_vchAttribute2		= @in_vchAttribute2		
													   ,@in_vchAttribute3		= @in_vchAttribute3		
													   ,@in_vchAttribute4		= @in_vchAttribute4		
													   ,@in_vchAttribute5		= @in_vchAttribute5		
													   ,@in_vchSNControl		= @in_vchSNControl		
													   ,@in_vchLocalID			= @in_vchLocalID			
													   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
													   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
													   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END 
	IF @in_vchControlName = 'STAGING_LOCATION'
		BEGIN
			EXEC usp_outbound_update_pickto_staging @in_vchApplicationID	= @in_vchApplicationID
												   ,@in_vchWarehouse		= @in_vchWarehouse
												   ,@in_vchDeviceID			= @in_vchDeviceID
												   ,@in_vchUserID			= @in_vchUserID
												   ,@in_vchPicklistNumber	= @in_vchOutboundOrderNumber
												   ,@in_vchForklift			= @in_vchForkLocation
												   ,@in_vchStagingLocation	= @in_vchStgLocation
												   ,@out_ErrorCode			= @out_vchErrorMsg	  OUTPUT 
												   ,@out_ErrorMessage		= @out_vchNextScreen OUTPUT 

			IF ISNULL(@out_vchErrorMsg,'') = '0'
				BEGIN
					SET @out_vchNextScreen = 'OUTBOUND_ORDER'
				END 
			RETURN; 
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SET @in_fltQuantity = 1;
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:		
		print 'save'	 
		EXEC usp_outbound_generate_blind_pick @in_vchApplicationID		 = @in_vchApplicationID		
											 ,@in_vchLocalID			 = @in_vchLocalID					
											 ,@in_vchDeviceID			 = @in_vchDeviceID					
											 ,@in_vchUserID				 = @in_vchUserID				
											 ,@in_vchWhMasterID			 = @in_vchWhMasterID			
											 ,@in_vchWarehouse			 = @in_vchWarehouse			
											 ,@in_vchForkLocation		 = @in_vchForkLocation				
											 ,@in_vchCustomerID			 = @in_vchCustomerID			
											 ,@in_vchCustomerCode		 = @in_vchCustomerCode				
											 ,@in_vchToWarehouse		 = @in_vchToWarehouse		
											 ,@in_vchOutboundOrderNumber = @in_vchOutboundOrderNumber		
											 ,@in_vchOwnerID			 = @in_vchOwnerID					
											 ,@in_vchOwnerCode			 = @in_vchOwnerCode			
											 ,@in_vchBoxNumber			 = @in_vchBoxNumber			
											 ,@in_vchLocationID			 = @in_vchLocationID			
											 ,@in_vchLocation			 = @in_vchLocation					
											 ,@in_vchParentLPN			 = @in_vchParentLPN			
											 ,@in_vchLPN				 = @in_vchLPN						
											 ,@in_vchInvStatusID		 = @in_vchInvStatusID				
											 ,@in_vchInvStatus			 = @in_vchInvStatus			
											 ,@in_vchWhItemMasterID		 = @in_vchWhItemMasterID			
											 ,@in_vchItemNumber			 = @in_vchItemNumber			
											 ,@in_vchLotNumber			 = @in_vchLotNumber			
											 ,@in_vchExpiryDate			 = @in_vchExpiryDate			
											 ,@in_vchAttribute1			 = @in_vchAttribute1			
											 ,@in_vchAttribute2			 = @in_vchAttribute2			
											 ,@in_vchAttribute3			 = @in_vchAttribute3			
											 ,@in_vchAttribute4			 = @in_vchAttribute4			
											 ,@in_vchAttribute5			 = @in_vchAttribute5			
											 ,@in_vchSerialNumber		 = @in_vchSerialNumber				
											 ,@in_fltQuantity			 = @in_fltQuantity					
											 ,@in_vchUOMPrompt			 = @in_vchUOMPrompt			
											 ,@out_vchErrorCode			 = @out_vchErrorCode OUTPUT
											 ,@out_vchErrorMsg			 = @out_vchErrorMsg	OUTPUT
											 ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		IF @in_vchControlName = 'SERIAL_NUMBER'
			GOTO FINAL_SCREEN;
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_blind_pick_final_screen @in_vchApplicationID		 = @in_vchApplicationID		
													 ,@in_vchDeviceID			 = @in_vchDeviceID			
													 ,@in_vchUserID				 = @in_vchUserID			
													 ,@in_vchWhMasterID			 = @in_vchWhMasterID		
													 ,@in_vchOutboundOrderNumber = @in_vchOutboundOrderNumber
													 ,@in_vchLocationID			 = @in_vchLocationID		
													 ,@in_vchWhItemMasterID		 = @in_vchWhItemMasterID	
													 ,@in_vchItemMasterID		 = @in_vchItemMasterID		
													 ,@in_vchLocalID			 = @in_vchLocalID			
													 ,@out_vchErrorCode			 = @out_vchErrorCode OUTPUT
													 ,@out_vchErrorMsg			 = @out_vchErrorMsg	OUTPUT
													 ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_blind_receipt]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_blind_receipt]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40),
	@in_vchReceiptHeaderID	 UNIQUEIDENTIFIER,
	@in_vchReceiptNumber	 NVARCHAR(50),
	@in_vchOrderType		 NVARCHAR(30) = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER,
	@in_vchLocation			 NVARCHAR(50),
	@in_vchParentLPN		 NVARCHAR(25),
	@in_vchLPN				 NVARCHAR(25), 
	@in_vchReceiptMode		 NVARCHAR(25) = NULL,
	@in_vchInvStatus		 NVARCHAR(50) = NULL,
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL, 
	@in_intItemShelfLife	 INT = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_dtMFGDate			 DATE = NULL, 
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchUomPrompt		 NVARCHAR(40) = NULL,
	@in_fltQuantity			 FLOAT,
	@in_vchReasonCode		 NVARCHAR(20) = NULL,
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchExpDateControl	 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @Round INT
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'OWNER'
		BEGIN
			EXEC usp_api_validate_blind_receipt_owner @in_vchApplicationID 	= @in_vchApplicationID 
													 ,@in_vchLocalID		= @in_vchLocalID
													 ,@in_vchUserID			= @in_vchUserID	 
													 ,@in_vchWhMasterID	 	= @in_vchWhMasterID	 
													 ,@in_vchOwnerCode	 	= @in_vchOwnerCode	 
													 ,@out_vchErrorCode	 	= @out_vchErrorCode OUTPUT
													 ,@out_vchErrorMsg	 	= @out_vchErrorMsg OUTPUT
													 ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT 
			RETURN;
		END
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			EXEC usp_api_validate_blind_receipt_order_number  @in_vchApplicationID	    = @in_vchApplicationID	    
															 ,@in_vchLocalID		    = @in_vchLocalID		    
															 ,@in_vchUserID			    = @in_vchUserID			    
															 ,@in_vchDeviceID		    = @in_vchDeviceID		    
															 ,@in_vchWhMasterID		    = @in_vchWhMasterID		    
															 ,@in_vchWhID			    = @in_vchWhID			    
															 ,@in_vchOwnerID		    = @in_vchOwnerID		    
															 ,@in_vchInboundOrderNumber	= @in_vchInboundOrderNumber	
															 ,@out_vchErrorCode			= @out_vchErrorCode	OUTPUT
															 ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
															 ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'PARTIAL_RECEIPT_NUMBER'
		BEGIN
			EXEC usp_api_validate_blind_receipt_partial_receipt @in_vchApplicationID	  = @in_vchApplicationID	 
															   ,@in_vchLocalID			  = @in_vchLocalID			 
															   ,@in_vchWhMasterID		  = @in_vchWhMasterID		 
															   ,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
															   ,@in_vchInboundOrderNumber = @in_vchInboundOrderNumber
															   ,@in_vchReceiptNumber	  = @in_vchReceiptNumber	 
															   ,@out_vchErrorCode		  = @out_vchErrorCode OUTPUT
															   ,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
															   ,@out_vchNextScreen		  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_blind_receipt_location @in_vchApplicationID	= @in_vchApplicationID	
														,@in_vchLocalID			= @in_vchLocalID			
														,@in_vchWhMasterID		= @in_vchWhMasterID		
														,@in_vchInboundMasterID	= @in_vchInboundMasterID
														,@in_vchOrderType		= @in_vchOrderType
														,@in_vchLocation		= @in_vchLocation				
														,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			EXEC usp_api_validate_blind_receipt_parent_lpn @in_vchApplicationID	  = @in_vchApplicationID	
														  ,@in_vchLocalID		  = @in_vchLocalID			
														  ,@in_vchWhMasterID	  = @in_vchWhMasterID		
														  ,@in_vchInboundMasterID = @in_vchInboundMasterID	
														  ,@in_vchLocationID	  = @in_vchLocationID		
														  ,@in_vchParentLpn		  = @in_vchParentLpn		
														  ,@out_vchErrorCode	  = @out_vchErrorCode OUTPUT	
														  ,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_blind_receipt_lpn @in_vchApplicationID	= @in_vchApplicationID	 
												   ,@in_vchLocalID			= @in_vchLocalID			
												   ,@in_vchWhMasterID		= @in_vchWhMasterID		
												   ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
												   ,@in_vchOrderType		= @in_vchOrderType
												   ,@in_vchLocationID		= @in_vchLocationID		
												   ,@in_vchParentLpn		= @in_vchParentLpn		
												   ,@in_vchLpn				= @in_vchLpn				
												   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT	
												   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'RECEIPT_MODE'
		BEGIN
			EXEC usp_api_validate_blind_receipt_receipt_mode @in_vchApplicationID= @in_vchApplicationID 
													        ,@in_vchLocalID		 = @in_vchLocalID		 
													        ,@in_vchReceiptMode	 = @in_vchReceiptMode	 
													        ,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
													        ,@out_vchErrorMsg	 = @out_vchErrorMsg OUTPUT
													        ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_blind_receipt_item_status @in_vchApplicationID = @in_vchApplicationID 
													   ,@in_vchInvStatus	 = @in_vchInvStatus	 
													   ,@in_vchLocalID		 = @in_vchLocalID		 
													   ,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
													   ,@out_vchErrorMsg	 = @out_vchErrorMsg	OUTPUT
													   ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT
			RETURN;									   
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_blind_receipt_item_number @in_vchApplicationID   = @in_vchApplicationID	
														   ,@in_vchLocalID		   = @in_vchLocalID			
														   ,@in_vchWhMasterID	   = @in_vchWhMasterID		
														   ,@in_vchOwnerID		   = @in_vchOwnerID			
														   ,@in_vchInboundMasterID = @in_vchInboundMasterID	
														   ,@in_vchLocationID	   = @in_vchLocationID		
														   ,@in_vchReceiptMode	   = @in_vchReceiptMode		
														   ,@in_vchInvStatusID	   = @in_vchInvStatusID		
														   ,@in_vchItemNumber	   = @in_vchItemNumber	
														   ,@out_vchItemMasterID   = @in_vchItemMasterID OUTPUT
														   ,@out_vchWhItemMasterID = @in_vchWhItemMasterID OUTPUT
														   ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg	   = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen	   = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			EXEC usp_api_validate_blind_receipt_lot_number @in_vchApplicationID	    = @in_vchApplicationID	
														  ,@in_vchLocalID			= @in_vchLocalID			
														  ,@in_vchWhMasterID		= @in_vchWhMasterID		
														  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
														  ,@in_vchReceiptMode		= @in_vchReceiptMode		
														  ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID   
														  ,@in_intItemShelfLife     = @in_intItemShelfLife    
														  ,@in_vchLotNumber			= @in_vchLotNumber		
														  ,@in_vchExpDateControl    = @in_vchExpDateControl   
														  ,@in_vchAttribute1Control = @in_vchAttribute1Control
														  ,@in_vchAttribute2Control = @in_vchAttribute2Control
														  ,@in_vchAttribute3Control = @in_vchAttribute3Control
														  ,@in_vchAttribute4Control = @in_vchAttribute4Control
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control
														  ,@in_vchSNControl			= @in_vchSNControl	    
														  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT 
														  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT					     
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'MFG_DATE'
		BEGIN
			EXEC usp_api_validate_blind_receipt_mfg_date @in_vchApplicationID     = @in_vchApplicationID     
													    ,@in_vchLocalID		      = @in_vchLocalID		      
													    ,@in_vchInboundMasterID   = @in_vchInboundMasterID   
													    ,@in_vchReceiptMode		  = @in_vchReceiptMode		 
													    ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
													    ,@in_dtMFGDate			  = @in_dtMFGDate			 
													    ,@in_intItemShelfLife	  = @in_intItemShelfLife	 
													    ,@in_vchLotNumber		  = @in_vchLotNumber		 
													    ,@in_vchSNControl		  = @in_vchSNControl		 
													    ,@in_vchAttribute1Control = @in_vchAttribute1Control
													    ,@in_vchAttribute2Control = @in_vchAttribute2Control
													    ,@in_vchAttribute3Control = @in_vchAttribute3Control
													    ,@in_vchAttribute4Control = @in_vchAttribute4Control
													    ,@in_vchAttribute5Control = @in_vchAttribute5Control
													    ,@out_vchErrorCode	      = @out_vchErrorCode OUTPUT
													    ,@out_vchErrorMsg	      = @out_vchErrorMsg OUTPUT
													    ,@out_vchNextScreen		  = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			EXEC usp_api_validate_blind_receipt_expiry_date @in_vchApplicationID	 = @in_vchApplicationID	 
														   ,@in_vchLocalID			 = @in_vchLocalID			   
														   ,@in_vchWhMasterID		 = @in_vchWhMasterID		 
														   ,@in_vchInboundMasterID	 = @in_vchInboundMasterID	   
														   ,@in_vchReceiptMode		 = @in_vchReceiptMode		   
														   ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
														   ,@in_vchLotNumber		 = @in_vchLotNumber		 
														   ,@in_vchExpiryDate		 = @in_vchExpiryDate		 
														   ,@in_vchAttribute1Control = @in_vchAttribute1Control 
														   ,@in_vchAttribute2Control = @in_vchAttribute2Control 
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control 
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control 
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control 
														   ,@in_vchSNControl	     = @in_vchSNControl	     
														   ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			EXEC usp_api_validate_blind_receipt_attribute1 @in_vchApplicationID	    = @in_vchApplicationID	 
														  ,@in_vchLocalID			= @in_vchLocalID			 
														  ,@in_vchWhMasterID		= @in_vchWhMasterID		 
														  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	 
														  ,@in_vchReceiptMode		= @in_vchReceiptMode		 
														  ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
														  ,@in_vchLotNumber		 	= @in_vchLotNumber		 
														  ,@in_vchExpiryDate		= @in_vchExpiryDate		 
														  ,@in_vchAttribute1		= @in_vchAttribute1		 
														  ,@in_vchAttribute2Control = @in_vchAttribute2Control 
														  ,@in_vchAttribute3Control = @in_vchAttribute3Control 
														  ,@in_vchAttribute4Control = @in_vchAttribute4Control 
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control 
														  ,@in_vchSNControl	     	= @in_vchSNControl	     
														  ,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT	 
														  ,@out_vchErrorMsg		   	= @out_vchErrorMsg	 OUTPUT	 
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT		   
															  									 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_blind_receipt_attribute2 @in_vchApplicationID		= @in_vchApplicationID	 
														  ,@in_vchLocalID			= @in_vchLocalID			  
														  ,@in_vchWhMasterID		= @in_vchWhMasterID		  
														  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	  
														  ,@in_vchReceiptMode		= @in_vchReceiptMode		  
														  ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
														  ,@in_vchLotNumber		 	= @in_vchLotNumber		 
														  ,@in_vchExpiryDate		= @in_vchExpiryDate		  
														  ,@in_vchAttribute1		= @in_vchAttribute1		  
														  ,@in_vchAttribute2		= @in_vchAttribute2		  
														  ,@in_vchAttribute3Control = @in_vchAttribute3Control 
														  ,@in_vchAttribute4Control = @in_vchAttribute4Control 
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control 
														  ,@in_vchSNControl	     	= @in_vchSNControl	     
														  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														  ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT													 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_blind_receipt_attribute3 @in_vchApplicationID		= @in_vchApplicationID	 	
														  ,@in_vchLocalID			= @in_vchLocalID			  
														  ,@in_vchWhMasterID		= @in_vchWhMasterID		  
														  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	  
														  ,@in_vchReceiptMode		= @in_vchReceiptMode		  
														  ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
														  ,@in_vchLotNumber		 	= @in_vchLotNumber		 
														  ,@in_vchExpiryDate		= @in_vchExpiryDate		  
														  ,@in_vchAttribute1		= @in_vchAttribute1		  
														  ,@in_vchAttribute2		= @in_vchAttribute2		  
														  ,@in_vchAttribute3		= @in_vchAttribute3		  
														  ,@in_vchAttribute4Control = @in_vchAttribute4Control 
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control 
														  ,@in_vchSNControl	     	= @in_vchSNControl	     
														  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														  ,@out_vchErrorMsg		  	= @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_blind_receipt_attribute4 @in_vchApplicationID		= @in_vchApplicationID	 
														  ,@in_vchLocalID			= @in_vchLocalID			  
														  ,@in_vchWhMasterID		= @in_vchWhMasterID		  
														  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	  
														  ,@in_vchReceiptMode		= @in_vchReceiptMode		  
														  ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
														  ,@in_vchLotNumber		 	= @in_vchLotNumber		 
														  ,@in_vchExpiryDate		= @in_vchExpiryDate		  
														  ,@in_vchAttribute1		= @in_vchAttribute1		  
														  ,@in_vchAttribute2		= @in_vchAttribute2		  
														  ,@in_vchAttribute3		= @in_vchAttribute3		  
														  ,@in_vchAttribute4		= @in_vchAttribute4		  
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control 
														  ,@in_vchSNControl	     	= @in_vchSNControl	     
														  ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT
														  ,@out_vchErrorMsg		  	= @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_blind_receipt_attribute5 @in_vchApplicationID	  = @in_vchApplicationID	
														  ,@in_vchLocalID		  = @in_vchLocalID			
														  ,@in_vchWhMasterID	  = @in_vchWhMasterID		
														  ,@in_vchInboundMasterID = @in_vchInboundMasterID		
														  ,@in_vchReceiptMode	  = @in_vchReceiptMode		
														  ,@in_vchWhItemMasterID  = @in_vchWhItemMasterID    
														  ,@in_vchLotNumber		  = @in_vchLotNumber		
														  ,@in_vchExpiryDate	  = @in_vchExpiryDate		
														  ,@in_vchAttribute1	  = @in_vchAttribute1		
														  ,@in_vchAttribute2	  = @in_vchAttribute2		
														  ,@in_vchAttribute3	  = @in_vchAttribute3		
														  ,@in_vchAttribute4	  = @in_vchAttribute4		
														  ,@in_vchAttribute5	  = @in_vchAttribute5		
														  ,@in_vchSNControl	      = @in_vchSNControl	    
														  ,@out_vchErrorCode	  = @out_vchErrorCode OUTPUT
														  ,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
			RETURN;
		END 
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		--Save Transaction
		IF @in_vchReceiptMode = 'BY EACH'
			BEGIN
				SELECT TOP 1 @in_vchUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1;
			END

		EXEC usp_blind_receipt_update_qty @in_vchApplicationID	 = @in_vchApplicationID	  
										 ,@in_vchDeviceID		 = @in_vchDeviceID					
										 ,@in_vchUserID			 = @in_vchUserID			 
										 ,@in_vchWhMasterID		 = @in_vchWhMasterID		 
										 ,@in_vchInboundMasterID = @in_vchInboundMasterID		
										 ,@in_vchReceiptHeaderID = @in_vchReceiptHeaderID		
										 ,@in_vchLocationID		 = @in_vchLocationID		 
										 ,@in_vchParentLPN		 = NULL --@in_vchParentLPN		 
										 ,@in_vchLPN			 = NULL --@in_vchLPN					
										 ,@in_vchInvStatusID	 = @in_vchInvStatusID				
										 ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	 
										 ,@in_fltQuantity		 = @in_fltQuantity				
										 ,@in_vchUomPrompt		 = @in_vchUomPrompt		 
										 ,@in_vchLotNumber		 = @in_vchLotNumber		 
										 ,@in_vchExpiryDate		 = @in_vchExpiryDate		 
										 ,@in_vchSerialNumber	 = @in_vchSerialNumber			
										 ,@in_vchAttribute1		 = @in_vchAttribute1		 
										 ,@in_vchAttribute2		 = @in_vchAttribute2		 
										 ,@in_vchAttribute3		 = @in_vchAttribute3		 
										 ,@in_vchAttribute4		 = @in_vchAttribute4		 
										 ,@in_vchAttribute5		 = @in_vchAttribute5		 
										 ,@in_dtMfgDate			 = @in_dtMfgDate
										 ,@out_ErrorCode		 = @out_vchErrorCode OUTPUT
										 ,@out_ErrorMessage		 = @out_vchErrorMsg OUTPUT											
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
			 
		
		IF @in_vchReceiptMode = 'BY EACH' OR @in_vchControlName = 'SERIAL_NUMBER'
			GOTO FINAL_SCREEN;

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_blind_receipt_final_screen @in_vchWhMasterID		= @in_vchWhMasterID	
														,@in_vchInboundMasterID	= @in_vchInboundMasterID	
														,@in_vchLocationID		= @in_vchLocationID		
														,@in_vchWhItemMasterID	= @in_vchWhItemMasterID
														,@in_vchSNControl		= @in_vchSNControl
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_count]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_count]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchCountMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchCountID			 VARCHAR(50) = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		 NVARCHAR(40) = NULL,
	@in_vchCountMode		 NVARCHAR(50) = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
 	@in_vchLocation			 NVARCHAR(50) = NULL,
	@in_vchLPN				 NVARCHAR(25) = NULL,
	@in_vchItemStatus	     NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(50)  = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchUOMPrompt		 NVARCHAR(40),
	@in_fltQuantity			 FLOAT, 
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchExpDateControl	 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'COUNT_ID'
		BEGIN
			EXEC usp_api_validate_count_id @in_vchApplicationID = @in_vchApplicationID  
										  ,@in_vchWhMasterID	= @in_vchWhMasterID	   
										  ,@in_vchCountID		= @in_vchCountID		   
										  ,@in_vchLocalID		= @in_vchLocalID
										  ,@in_vchUserID		= @in_vchUserID
										  ,@out_vchErrorCode	= @out_vchErrorCode	 OUTPUT 
										  ,@out_vchErrorMsg	  	= @out_vchErrorMsg	 OUTPUT
										  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT   
			RETURN;
		END
	IF @in_vchControlName = 'COUNT_MODE'
		BEGIN
			EXEC usp_api_validate_count_mode @in_vchApplicationID = @in_vchApplicationID  
										  ,@in_vchWhMasterID	= @in_vchWhMasterID	   
										  ,@in_vchCountID		= @in_vchCountID
										  ,@in_vchCountMode		= @in_vchCountMode	   
										  ,@in_vchLocalID		= @in_vchLocalID		   
										  ,@out_vchErrorCode	= @out_vchErrorCode	 OUTPUT 
										  ,@out_vchErrorMsg	  	= @out_vchErrorMsg	 OUTPUT
										  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT   
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_count_location @in_vchApplicationID = @in_vchApplicationID 
												,@in_vchWhMasterID	  = @in_vchWhMasterID	 
												,@in_vchCountMasterID = @in_vchCountMasterID 
												,@in_vchLocation	  = @in_vchLocation		 
												,@in_vchLocalID		  = @in_vchLocalID		 
												,@out_vchErrorCode	  = @out_vchErrorCode	OUTPUT
												,@out_vchErrorMsg	  = @out_vchErrorMsg	OUTPUT
												,@out_vchNextScreen	  = @out_vchNextScreen	OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_count_item_status @in_vchApplicationID = @in_vchApplicationID  
												   ,@in_vchWhMasterID	 = @in_vchWhMasterID	  
												   ,@in_vchCountMasterID = @in_vchCountMasterID  
												   ,@in_vchLocationID	 = @in_vchLocationID	  
												   ,@in_vchItemStatus	 = @in_vchItemStatus	  
												   ,@in_vchLocalID		 = @in_vchLocalID		  
												   ,@out_vchErrorCode	 = @out_vchErrorCode  OUTPUT
												   ,@out_vchErrorMsg	 = @out_vchErrorMsg	  OUTPUT
												   ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT  
			RETURN;
		END 
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_count_lpn @in_vchApplicationID= @in_vchApplicationID 
										   ,@in_vchWhMasterID	= @in_vchWhMasterID	 
										   ,@in_vchCountMasterID= @in_vchCountMasterID 
										   ,@in_vchLocationID	= @in_vchLocationID	 
										   ,@in_vchLPN			= @in_vchLPN			 
										   ,@in_vchLocalID		= @in_vchLocalID		 
										   ,@out_vchErrorCode	= @out_vchErrorCode	 OUTPUT
										   ,@out_vchErrorMsg	= @out_vchErrorMsg	 OUTPUT
										   ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_count_item_number @in_vchApplicationID  = @in_vchApplicationID  
												   ,@in_vchWhMasterID	  = @in_vchWhMasterID	   
												   ,@in_vchCountMasterID  = @in_vchCountMasterID   
												   ,@in_vchOwnerID		  = @in_vchOwnerID		   
												   ,@in_vchCountMode	  = @in_vchCountMode
												   ,@in_vchLocationID	  = @in_vchLocationID	   
												   ,@in_vchLPN			  = @in_vchLPN			   
												   ,@in_vchItemNumber	  = @in_vchItemNumber
												   ,@in_vchLocalID		  = @in_vchLocalID		   
												   ,@out_vchItemMasterID   = @in_vchItemMasterID OUTPUT
												   ,@out_vchWhItemMasterID = @in_vchWhItemMasterID OUTPUT
												   ,@out_vchErrorCode	  = @out_vchErrorCode  OUTPUT
												   ,@out_vchErrorMsg	  = @out_vchErrorMsg   OUTPUT
												   ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			EXEC usp_api_validate_count_lot_number @in_vchApplicationID		 = @in_vchApplicationID	 
												  ,@in_vchWhMasterID		 = @in_vchWhMasterID		  
												  ,@in_vchCountMasterID	 	 = @in_vchCountMasterID	 
												  ,@in_vchOwnerID			 = @in_vchOwnerID
												  ,@in_vchCountMode			 = @in_vchCountMode  
												  ,@in_vchLocationID		 = @in_vchLocationID		  
												  ,@in_vchLPN				 = @in_vchLPN				  
												  ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	  
												  ,@in_vchLotNumber		 	 = @in_vchLotNumber		 
												  ,@in_vchExpiryDateControl  = @in_vchExpDateControl 
												  ,@in_vchAttribute1Control  = @in_vchAttribute1Control 
												  ,@in_vchAttribute2Control  = @in_vchAttribute2Control 
												  ,@in_vchAttribute3Control  = @in_vchAttribute3Control 
												  ,@in_vchAttribute4Control  = @in_vchAttribute4Control 
												  ,@in_vchAttribute5Control  = @in_vchAttribute5Control 
												  ,@in_vchSnControl		 	 = @in_vchSnControl		 
												  ,@in_vchLocalID			 = @in_vchLocalID			  
												  ,@out_vchErrorCode		 = @out_vchErrorCode  OUTPUT		  
												  ,@out_vchErrorMsg		 	 = @out_vchErrorMsg	  OUTPUT
												  ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT		  	   
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			EXEC usp_api_validate_count_expiry_date @in_vchApplicationID	 = @in_vchApplicationID	 
												   ,@in_vchWhMasterID		 = @in_vchWhMasterID		 
												   ,@in_vchCountMasterID	 = @in_vchCountMasterID	 
												   ,@in_vchOwnerID			 = @in_vchOwnerID
												   ,@in_vchCountMode		 = @in_vchCountMode 
												   ,@in_vchLocationID		 = @in_vchLocationID		 
												   ,@in_vchLPN				 = @in_vchLPN				 
												   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	 
