	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_count_attribute5 @in_vchApplicationID  = @in_vchApplicationID  
												  ,@in_vchWhMasterID	 = @in_vchWhMasterID	   
												  ,@in_vchCountMasterID  = @in_vchCountMasterID  
												  ,@in_vchOwnerID		 = @in_vchOwnerID
												  ,@in_vchCountMode		 = @in_vchCountMode	  	   
												  ,@in_vchLocationID	 = @in_vchLocationID	   
												  ,@in_vchLPN			 = @in_vchLPN			   
												  ,@in_vchWhItemMasterID = @in_vchWhItemMasterID 
												  ,@in_vchLotNumber	  	 = @in_vchLotNumber	  
												  ,@in_vchExpiryDate	 = @in_vchExpiryDate	   
												  ,@in_vchAttribute1	 = @in_vchAttribute1	   
												  ,@in_vchAttribute2	 = @in_vchAttribute2	   
												  ,@in_vchAttribute3	 = @in_vchAttribute3	   
												  ,@in_vchAttribute4	 = @in_vchAttribute4	   
												  ,@in_vchAttribute5	 = @in_vchAttribute5	   
												  ,@in_vchSnControl	  	 = @in_vchSnControl	  
												  ,@in_vchLocalID		 = @in_vchLocalID		   
												  ,@out_vchErrorCode	 = @out_vchErrorCode  OUTPUT   
												  ,@out_vchErrorMsg	  	 = @out_vchErrorMsg	  OUTPUT
												  ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT

			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			EXEC usp_api_validate_count_serial_number @in_vchApplicationID   = @in_vchApplicationID  
													 ,@in_vchWhMasterID	  	 = @in_vchWhMasterID	  
													 ,@in_vchCountMasterID   = @in_vchCountMasterID  
													 ,@in_vchOwnerID		 = @in_vchOwnerID     
													 ,@in_vchLocationID	  	 = @in_vchLocationID	  
													 ,@in_vchLPN			 = @in_vchLPN			  
													 ,@in_vchWhItemMasterID  = @in_vchWhItemMasterID 
													 ,@in_vchLotNumber	  	 = @in_vchLotNumber	  
													 ,@in_vchExpiryDate	  	 = @in_vchExpiryDate	  
													 ,@in_vchAttribute1	  	 = @in_vchAttribute1	  
													 ,@in_vchAttribute2	  	 = @in_vchAttribute2	  
													 ,@in_vchAttribute3	  	 = @in_vchAttribute3	  
													 ,@in_vchAttribute4	  	 = @in_vchAttribute4	  
													 ,@in_vchAttribute5	  	 = @in_vchAttribute5	  
													 ,@in_vchSerialNumber	 = @in_vchSerialNumber	  
													 ,@in_vchLocalID		 = @in_vchLocalID		  
													 ,@out_vchErrorCode	  	 = @out_vchErrorCode  OUTPUT
													 ,@out_vchErrorMsg	  	 = @out_vchErrorMsg	  OUTPUT
													 ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT
			
			--if validate success go to save transaction else show error
			IF (ISNULL(@out_vchErrorCode,'') = '' AND @out_vchNextScreen	= 'FINAL_SCREEN')
				GOTO SAVE_TRANS; 
			ELSE 
				RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		IF @in_vchCountMode = 'BY EACH'
			BEGIN
				SELECT TOP 1 @in_vchUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1; 
				SELECT @in_fltQuantity as qty
			END 

		--Save Transaction
		EXEC usp_physical_count @in_vchApplicationID	= @in_vchApplicationID	  
							   ,@in_vchDeviceID			= @in_vchDeviceID			  
							   ,@in_vchUserID			= @in_vchUserID			  
							   ,@in_vchWhMasterID		= @in_vchWhMasterID		  
							   ,@in_vchWhID				= @in_vchWhID				  
							   ,@in_vchCountID			= @in_vchCountID			  
							   ,@in_vchOwnerID			= @in_vchOwnerID			  
							   ,@in_vchOwnerCode		= @in_vchOwnerCode		  
							   ,@in_vchLocationID		= @in_vchLocationID		  
							   ,@in_vchLocation			= @in_vchLocation			  	
							   ,@in_vchLPN				= @in_vchLPN				  
							   ,@in_vchItemStatus	    = @in_vchItemStatus	      
							   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	  
							   ,@in_vchItemMasterID		= @in_vchItemMasterID		  
							   ,@in_vchItemNumber		= @in_vchItemNumber		  
							   ,@in_vchLotNumber		= @in_vchLotNumber		  
							   ,@in_vchExpiryDate		= @in_vchExpiryDate		  
							   ,@in_vchAttribute1		= @in_vchAttribute1		  
							   ,@in_vchAttribute2		= @in_vchAttribute2		  
							   ,@in_vchAttribute3		= @in_vchAttribute3		  
							   ,@in_vchAttribute4		= @in_vchAttribute4		  
							   ,@in_vchAttribute5		= @in_vchAttribute5		  
							   ,@in_vchSerialNumber		= @in_vchSerialNumber		  
							   ,@in_vchUOMPrompt		= @in_vchUOMPrompt		  
							   ,@in_fltQuantity			= @in_fltQuantity			  
							   ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT 
							   ,@out_vchErrorMessage	= @out_vchErrorMsg	OUTPUT  

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_count_final_screen @in_vchControlName	    = @in_vchControlName
												,@in_vchWhMasterID	    = @in_vchWhMasterID 		
												,@in_vchCountMasterID  	= @in_vchCountMasterID  	
												,@in_vchOwnerID		  	= @in_vchOwnerID		  	
												,@in_vchLocationID	  	= @in_vchLocationID  
												,@in_vchLPN			  	= @in_vchLPN			  	
												,@in_vchWhItemMasterID 	= @in_vchWhItemMasterID
												,@in_vchItemMasterID	= @in_vchItemMasterID
												,@in_vchItemNumber	  	= @in_vchItemNumber	  	
												,@out_vchNextScreen	  	= @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_count_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_count_lpn]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchCountMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchCountID			 VARCHAR(50) = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		 NVARCHAR(40) = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
 	@in_vchLocation			 NVARCHAR(50) = NULL,
	@in_fltCountQty			 FLOAT,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF @in_vchControlName = 'COUNT_ID'
		BEGIN
			EXEC usp_api_validate_count_lpn_count_id @in_vchApplicationID = @in_vchApplicationID  
													,@in_vchWhMasterID	= @in_vchWhMasterID	   
													,@in_vchCountID		= @in_vchCountID		   
													,@in_vchLocalID		= @in_vchLocalID
													,@in_vchUserID		= @in_vchUserID
													,@out_vchErrorCode	= @out_vchErrorCode OUTPUT 
													,@out_vchErrorMsg	= @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen	= @out_vchNextScreen OUTPUT   
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_count_lpn_location @in_vchApplicationID = @in_vchApplicationID 
													,@in_vchWhMasterID	  = @in_vchWhMasterID	 
													,@in_vchCountMasterID = @in_vchCountMasterID 
													,@in_vchLocation	  = @in_vchLocation		 
													,@in_vchLocalID		  = @in_vchLocalID		 
													,@out_vchErrorCode	  = @out_vchErrorCode OUTPUT
													,@out_vchErrorMsg	  = @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LPN_QTY'
		BEGIN
			GOTO SAVE_TRANS;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		--Save Transaction
		EXEC usp_count_lpn_counting @in_vchApplicationID	= @in_vchApplicationID
								   ,@in_vchDeviceID			= @in_vchDeviceID		
								   ,@in_vchUserID			= @in_vchUserID		
								   ,@in_vchWhMasterID		= @in_vchWhMasterID	
								   ,@in_vchWhID				= @in_vchWhID			
								   ,@in_vchCountMasterID	= @in_vchCountMasterID
								   ,@in_vchCountID			= @in_vchCountID		
								   ,@in_vchOwnerID			= @in_vchOwnerID		
								   ,@in_vchOwnerCode		= @in_vchOwnerCode	
								   ,@in_vchLocationID		= @in_vchLocationID	
								   ,@in_vchLocation			= @in_vchLocation		
								   ,@in_fltCountQty			= @in_fltCountQty		
								   ,@out_vchErrorCode		= @out_vchErrorCode		OUTPUT
								   ,@out_vchErrorMessage	= @out_vchErrorMsg	OUTPUT
									 
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
		 

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_count_lpn_final_screen @in_vchWhMasterID	  = @in_vchWhMasterID	  
													,@in_vchCountMasterID = @in_vchCountMasterID  
													,@in_vchOwnerID		  = @in_vchOwnerID		  
													,@in_vchLocationID	  = @in_vchLocationID	  
													,@in_vchLocation	  = @in_vchLocation		    
													,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_inventory_viewer]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_inventory_viewer]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInvViewerMode	NVARCHAR(50),
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchItemNumber		NVARCHAR(50), 
	@in_vchSerialNumber		NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'VIEW_MODE'
		BEGIN
			 -- Insert statements for procedure here
			DECLARE @v_vchValue nvarchar(50) = ''
			SELECT @v_vchValue = value_member FROM t_com_combobox_item WHERE group_name = 'INVENTORY_VIEWER' AND display_member = @in_vchInvViewerMode AND is_active = 'YES'
			IF (ISNULL(@v_vchValue,'') = '')
				BEGIN
					SET @out_vchErrorCode = 'INFO-VIEW-MODE-NOT-EXIST'
					GOTO EXIT_LABEL
				END

			--Return Next Screen
			IF (@v_vchValue = 'LOCATION_MODE')
				BEGIN
					SET @out_vchNextScreen = 'LOCATION'
				END
			ELSE IF (@v_vchValue = 'LPN_MODE')
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
			ELSE IF (@v_vchValue = 'ITEM_MODE')
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER'
				END 
			ELSE IF (@v_vchValue = 'SN_MODE')
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
				END
			ELSE IF (@v_vchValue = 'LPN_SUMMARY_MODE')
				BEGIN
					SET @out_vchNextScreen = 'SUMMARY_LPN'
				END
			ELSE IF (@v_vchValue = 'ITEM_SUMMARY_MODE')
				BEGIN
					SET @out_vchNextScreen = 'SUMMARY_ITEM'
				END 
			RETURN;
		END
	
	EXEC usp_api_validate_inventory_viewer @in_vchApplicationID	= @in_vchApplicationID	
										  ,@in_vchControlName	= @in_vchControlName			
										  ,@in_vchLocalID		= @in_vchLocalID				
										  ,@in_vchDeviceID		= @in_vchDeviceID				
										  ,@in_vchUserID		= @in_vchUserID				
										  ,@in_vchWhMasterID	= @in_vchWhMasterID			
										  ,@in_vchWhID			= @in_vchWhID					
										  ,@in_vchInvViewerMode	= @in_vchInvViewerMode	
										  ,@in_vchLocation		= @in_vchLocation				
										  ,@in_vchParentLPN		= @in_vchParentLPN		
										  ,@in_vchLPN			= @in_vchLPN					
										  ,@in_vchItemNumber	= @in_vchItemNumber			
										  ,@in_vchSerialNumber	= @in_vchSerialNumber			
										  ,@out_vchErrorCode	= @out_vchErrorCode	OUTPUT		
										  ,@out_vchErrorMsg		= @out_vchErrorMsg	OUTPUT	
										  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')	
END
GO
