														  ,@in_vchSourceParentLPN	= @in_vchSourceParentLPN
														  ,@in_vchSourceLPN		 	= @in_vchSourceLPN
														  ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID
														  ,@in_vchLotNumber		 	= @in_vchLotNumber
														  ,@in_vchExpiryDate		= @in_vchExpiryDate
														  ,@in_vchAttribute1		= @in_vchAttribute1
														  ,@in_vchAttribute2		= @in_vchAttribute2
														  ,@in_vchAttribute3		= @in_vchAttribute3
														  ,@in_vchAttribute4		= @in_vchAttribute4
														  ,@in_vchSNControl		 	= @in_vchSNControl
														  ,@in_vchAttribute5Control = @in_vchAttribute5Control
														  ,@in_vchLocalID			= @in_vchLocalID
														  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														  ,@out_vchErrorMsg		 	= @out_vchErrorMsg OUTPUT
														  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_move_item_qty_attribute5 @in_vchApplicationID	   = @in_vchApplicationID
														  ,@in_vchWhMasterID	   = @in_vchWhMasterID
														  ,@in_vchOwnerID		   = @in_vchOwnerID
														  ,@in_vchInvStatusID	   = @in_vchInvStatusID
														  ,@in_vchSourceLocationID = @in_vchSourceLocationID
														  ,@in_vchSourceParentLPN  = @in_vchSourceParentLPN
														  ,@in_vchSourceLPN		   = @in_vchSourceLPN
														  ,@in_vchWhItemMasterID   = @in_vchWhItemMasterID
														  ,@in_vchLotNumber		   = @in_vchLotNumber
														  ,@in_vchExpiryDate	   = @in_vchExpiryDate
														  ,@in_vchAttribute1	   = @in_vchAttribute1
														  ,@in_vchAttribute2	   = @in_vchAttribute2
														  ,@in_vchAttribute3	   = @in_vchAttribute3
														  ,@in_vchAttribute4	   = @in_vchAttribute4
														  ,@in_vchAttribute5	   = @in_vchAttribute5
														  ,@in_vchSNControl		   = @in_vchSNControl
														  ,@in_vchLocalID		   = @in_vchLocalID
														  ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT 		
														  ,@out_vchErrorMsg		   = @out_vchErrorMsg OUTPUT		
														  ,@out_vchNextScreen	   = @out_vchNextScreen OUTPUT		
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			EXEC usp_api_validate_move_item_qty_serial_number @in_vchApplicationID	  = @in_vchApplicationID
															 ,@in_vchWhMasterID		  = @in_vchWhMasterID
															 ,@in_vchOwnerID		  = @in_vchOwnerID
															 ,@in_vchInvStatusID	  = @in_vchInvStatusID
															 ,@in_vchSourceLocationID = @in_vchSourceLocationID
															 ,@in_vchSourceParentLPN  = @in_vchSourceParentLPN
															 ,@in_vchSourceLPN		  = @in_vchSourceLPN
															 ,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID
															 ,@in_vchLotNumber		  = @in_vchLotNumber
															 ,@in_vchExpiryDate		  = @in_vchExpiryDate
															 ,@in_vchAttribute1		  = @in_vchAttribute1
															 ,@in_vchAttribute2		  = @in_vchAttribute2
															 ,@in_vchAttribute3		  = @in_vchAttribute3
															 ,@in_vchAttribute4		  = @in_vchAttribute4
															 ,@in_vchAttribute5		  = @in_vchAttribute5
															 ,@in_vchSerialNumber	  = @in_vchSerialNumber
															 ,@in_vchLocalID		  = @in_vchLocalID
															 ,@out_vchErrorCode		  = @out_vchErrorCode OUTPUT
															 ,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
															 ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			EXEC usp_api_validate_move_item_qty_uom_qty @in_vchApplicationID	= @in_vchApplicationID	
												       ,@in_vchWhMasterID		= @in_vchWhMasterID		
												       ,@in_vchOwnerID			= @in_vchOwnerID			
												       ,@in_vchInvStatusID		= @in_vchInvStatusID		
												       ,@in_vchSourceLocationID	= @in_vchSourceLocationID	
												       ,@in_vchSourceParentLPN	= @in_vchSourceParentLPN	
												       ,@in_vchSourceLPN		= @in_vchSourceLPN		
												       ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
												       ,@in_vchItemMasterID		= @in_vchItemMasterID
													   ,@in_vchItemNumber		= @in_vchItemNumber
												       ,@in_vchLotNumber		= @in_vchLotNumber		
												       ,@in_vchExpiryDate		= @in_vchExpiryDate		
												       ,@in_vchAttribute1		= @in_vchAttribute1		
												       ,@in_vchAttribute2		= @in_vchAttribute2		
												       ,@in_vchAttribute3		= @in_vchAttribute3		
												       ,@in_vchAttribute4		= @in_vchAttribute4		
												       ,@in_vchAttribute5		= @in_vchAttribute5		
												       ,@in_fltQuantity			= @in_fltQuantity
												       ,@in_vchUOMPrompt		= @in_vchUOMPrompt	
												       ,@in_vchLocalID			= @in_vchLocalID			
												       ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT	
												       ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT	
												       ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION_DESTINATION'
		BEGIN
			EXEC usp_api_validate_move_item_qty_dest_location @in_vchApplicationID	 = @in_vchApplicationID	
															 ,@in_vchWhMasterID		 = @in_vchWhMasterID		
															 ,@in_vchOwnerID		 = @in_vchOwnerID				
															 ,@in_vchSourceLocation	 = @in_vchSourceLocation	
															 ,@in_vchDestLocation	 = @in_vchDestLocation			
															 ,@in_vchLocalID		 = @in_vchLocalID				
															 ,@out_vchErrorCode		 = @out_vchErrorCode output 
															 ,@out_vchErrorMsg		 = @out_vchErrorMsg	output	
															 ,@out_vchNextScreen	 = @out_vchNextScreen output
			IF @out_vchNextScreen = 'FINAL_SCREEN' AND ISNULL(@out_vchErrorCode,'') = ''
				BEGIN
					GOTO SAVE_TRANS;
					RETURN;
				END
			ELSE
				BEGIN
					RETURN;
				END
			RETURN;
		END
	IF @in_vchControlName = 'LPN_DESTINATION'
		BEGIN
			EXEC usp_api_validate_move_item_qty_dest_lpn @in_vchApplicationID  = @in_vchApplicationID  
														,@in_vchWhMasterID	   = @in_vchWhMasterID
														,@in_vchItemMasterID   = @in_vchItemMasterID
														,@in_fltQuantity	   = @in_fltQuantity
												        ,@in_vchUOMPrompt	   = @in_vchUOMPrompt
														,@in_vchDestLocationID = @in_vchDestLocationID
														,@in_vchDestLPN		   = @in_vchDestLPN		  
														,@in_vchLocalID		   = @in_vchLocalID		  
														,@out_vchErrorCode	   = @out_vchErrorCode output
														,@out_vchErrorMsg	   = @out_vchErrorMsg output
														,@out_vchNextScreen	   = @out_vchNextScreen	output
			IF @out_vchNextScreen = 'FINAL_SCREEN' AND ISNULL(@out_vchErrorCode,'') = ''
				BEGIN
					GOTO SAVE_TRANS;
					RETURN;
				END
			ELSE
				BEGIN
					RETURN;
				END
			RETURN;
		END
	IF @in_vchControlName = 'REASON'
		BEGIN
			SELECT TOP 1 @in_vchReasonCode = reason_code FROM t_wms_reason WHERE short_description = @in_vchReasonCode AND reason_type = 'ChangeLocation' AND is_active = 'YES'
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		DECLARE @v_vchReferenceNumber NVARCHAR(50)
		EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT
		 
		EXEC usp_inventory_control_for_pda @in_vchApplicationID		= @in_vchApplicationID
										   ,@in_vchDevice			= @in_vchDeviceID
										   ,@in_vchUserID			= @in_vchUserID
										   ,@in_vchTranDescription	= 'Move putaway item qty from PDA'
										   ,@in_vchWarehouse		= @in_vchWhID
										   ,@in_vchOwner			= @in_vchOwnerCode
										   ,@in_vchFromLocation		= @in_vchSourceLocation
										   ,@in_vchFromParentLPN	= @in_vchSourceParentLPN
										   ,@in_vchFromLPN			= @in_vchSourceLPN
										   ,@in_vchStatus			= @in_vchInvStatus
										   ,@in_vchLot				= @in_vchLotNumber
										   ,@in_vchExpiryDate		= @in_vchExpiryDate
										   ,@in_vchAttribute1		= @in_vchAttribute1
										   ,@in_vchAttribute2		= @in_vchAttribute2
										   ,@in_vchAttribute3		= @in_vchAttribute3
										   ,@in_vchAttribute4		= @in_vchAttribute4
										   ,@in_vchAttribute5		= @in_vchAttribute5			
										   ,@in_vchToLocation		= @in_vchDestLocation				
										   ,@in_vchToParentLPN		= @in_vchDestParentLPN				
										   ,@in_vchToLPN			= @in_vchDestLPN
										   ,@in_vchWhItemMasterID 	= @in_vchWhItemMasterID				
										   ,@in_fltQty				= @in_fltQuantity						
										   ,@in_vchUOMPrompt		= @in_vchUOMPrompt				
										   ,@in_vchSerialNumber		= @in_vchSerialNumber				
										   ,@in_vchReferenceNumber	= @v_vchReferenceNumber			
										   ,@in_vchReasonCode		= @in_vchReasonCode				
										   ,@out_ErrorCode			= @out_vchErrorCode	output
										   ,@out_ErrorMessage		= @out_vchErrorMsg	output

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		SET @out_vchNextScreen = 'SOURCE_LOCATION'
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_move_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_move_lpn]
(
	@in_vchApplicationID  VARCHAR(40),
	@in_vchControlName	  NVARCHAR(50),	--Current Screen
	@in_vchLocalID		  VARCHAR(40),
	@in_vchDeviceID		  NVARCHAR(50),
	@in_vchUserID		  NVARCHAR(25), 
	@in_vchWhMasterID	  UNIQUEIDENTIFIER= NULL,
	@in_vchWhID			  NVARCHAR(25), 
	@in_vchOwnerID		  UNIQUEIDENTIFIER = NULL, 
	@in_vchFromLocationID UNIQUEIDENTIFIER = NULL,
	@in_vchFromLocation	  NVARCHAR(50) = NULL, 
	@in_vchLPN			  NVARCHAR(25) = NULL, 
	@in_vchSuggestLocationID UNIQUEIDENTIFIER = NULL,
	@in_vchToLocation	  NVARCHAR(50) = NULL,		--Destination 
	@out_vchIsConfirm	  VARCHAR(3) OUTPUT,		--YES/NO
	@out_vchErrorCode	  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	DECLARE @v_vchToLocationID	 UNIQUEIDENTIFIER = NULL
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	   
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_move_lpn @in_vchApplicationID = @in_vchApplicationID
										  ,@in_vchLocalID		= @in_vchLocalID
										  ,@in_vchWhMasterID	= @in_vchWhMasterID
										  ,@in_vchLPN			= @in_vchLPN
										  ,@out_vchErrorCode	= @out_vchErrorCode output
										  ,@out_vchErrorMsg		= @out_vchErrorMsg output
										  ,@out_vchNextScreen	= @out_vchNextScreen output 
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION_DESTINATION'
		BEGIN 
			DECLARE @v_vchToLPNControl	 VARCHAR(3)
			DECLARE @v_vchDestLocType	 NVARCHAR(20) = NULL

			--------------------------------------------------------------------
			-- Check To Location in master data
			--------------------------------------------------------------------
			SELECT TOP 1 @v_vchToLocationID = location_id 
				,@v_vchToLPNControl = lpn_controlled
				,@v_vchDestLocType = loc_type
			FROM t_wms_location
			WHERE location = @in_vchToLocation
			AND wh_master_id = @in_vchWhMasterID
			AND is_active = 'YES'

			IF (@v_vchToLocationID IS NULL)
				BEGIN
					SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchToLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			IF @v_vchDestLocType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_TO_DESTINATION' and is_active = 'YES')
				BEGIN
					SET @out_vchErrorCode = 'INFO_LOCATION_DESTINATION_NOT_ALLOW_MOVE'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchToLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END

			IF @in_vchFromLocationID = @v_vchToLocationID
				BEGIN
					SET @out_vchErrorCode = 'INFO-SOURCE-LOC-CANNOT-DUP-DEST-LOC'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
					RETURN;
				END 

			IF @v_vchToLPNControl = 'NO' 
				BEGIN
					SET @out_vchIsConfirm = 'YES'
					SET @out_vchErrorCode = 'LOCATION-NOT-CONTROL-LPN'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
					RETURN;
				END

			SET @out_vchNextScreen = 'FINAL_SCREEN' 
			GOTO SAVE_TRANS;
			RETURN;
		END 

	IF @in_vchControlName = 'SAVE_CONFIRM_FINAL'
		BEGIN
			SET @v_vchToLocationID = NULL
			SELECT TOP 1 @v_vchToLocationID = location_id FROM t_wms_location WHERE location = @in_vchToLocation AND wh_master_id = @in_vchWhMasterID AND is_active = 'YES'

			GOTO SAVE_TRANS;
			RETURN;
		END

	IF @in_vchControlName = 'CONFIRM_NEXT_LOCATION_DESTINATION'
		BEGIN
			SET @v_vchToLocationID = NULL
			SELECT TOP 1 @v_vchToLocationID = location_id FROM t_wms_location WHERE location = @in_vchToLocation AND wh_master_id = @in_vchWhMasterID AND is_active = 'YES'

			GOTO SAVE_TRANS;
			RETURN;
		END

	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		DECLARE @v_vchReferenceNumber NVARCHAR(50)
		EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT	
		EXEC usp_inventory_for_move_lpn @in_vchApplicationID	= @in_vchApplicationID
									   ,@in_vchWhMasterID		= @in_vchWhMasterID
									   ,@in_vchOwnerID			= @in_vchOwnerID
									   ,@in_vchLPN				= @in_vchLPN
									   ,@in_vchToLocationID		= @v_vchToLocationID
									   ,@in_vchToParentLPN		= NULL
									   ,@in_vchReasonID			= NULL
									   ,@in_vchRemark			= NULL
									   ,@in_vchReferenceNumber	= @v_vchReferenceNumber
									   ,@in_vchDeviceID			= @in_vchDeviceID
									   ,@in_vchUserID			= @in_vchUserID
									   ,@out_ErrorCode			= @out_vchErrorCode output
									   ,@out_ErrorMessage		= @out_vchErrorMsg output
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		SET @out_vchNextScreen = 'LPN'
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_move_putaway]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_move_putaway]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchForkID			 UNIQUEIDENTIFIER = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				 NVARCHAR(25), 
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		 NVARCHAR(40) = NULL,	
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		 NVARCHAR(50) = NULL,
	@in_vchSourceLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	 NVARCHAR(50) = NULL,
	@in_vchSourceParentLPN	 NVARCHAR(25) = NULL,
	@in_vchSourceLPN		 NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL, 
	@in_vchLotNumber		 NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchExpDateControl	 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchUOMPrompt		 NVARCHAR(40),
	@in_fltQuantity			 FLOAT,
	@in_vchDestLocationID	 UNIQUEIDENTIFIER = NULL, --Destination
	@in_vchDestLocation		 NVARCHAR(50) = NULL,	  --Destination 
	@in_vchDestLPN			 NVARCHAR(25) = NULL,	  --Destination
	@in_vchReasonCode		 NVARCHAR(20) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF @in_vchControlName = 'OWNER'
		BEGIN
			EXEC usp_api_validate_move_putaway_owner @in_vchApplicationID 	= @in_vchApplicationID 
													 ,@in_vchWhMasterID	   	= @in_vchWhMasterID	
													 ,@in_vchOwnerCode	   	= @in_vchOwnerCode		
													 ,@in_vchLocalID		= @in_vchLocalID		
													 ,@out_vchErrorCode	   	= @out_vchErrorCode	OUTPUT
													 ,@out_vchErrorMsg	   	= @out_vchErrorMsg OUTPUT
													 ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	
	IF @in_vchControlName = 'SOURCE_LOCATION'
		BEGIN
			EXEC usp_api_validate_move_putaway_source_location @in_vchApplicationID  = @in_vchApplicationID
															   ,@in_vchUserID		  = @in_vchUserID
															   ,@in_vchWhMasterID	  = @in_vchWhMasterID
															   ,@in_vchOwnerID		  = @in_vchOwnerID 
															   ,@in_vchSourceLocation = @in_vchSourceLocation
															   ,@in_vchLocalID		  = @in_vchLocalID
															   ,@out_vchErrorCode	  = @out_vchErrorCode OUTPUT
															   ,@out_vchErrorMsg	  = @out_vchErrorMsg OUTPUT	
															   ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_move_putaway_status @in_vchApplicationID    = @in_vchApplicationID
													  ,@in_vchWhMasterID	   = @in_vchWhMasterID	
													  ,@in_vchOwnerID		   = @in_vchOwnerID
													  ,@in_vchSourceLocationID = @in_vchSourceLocationID	
													  ,@in_vchInvStatus	       = @in_vchInvStatus	
													  ,@in_vchLocalID		   = @in_vchLocalID		
													  ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT
													  ,@out_vchErrorMsg	       = @out_vchErrorMsg OUTPUT
													  ,@out_vchNextScreen	   = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			EXEC usp_api_validate_move_putaway_source_parent_lpn @in_vchApplicationID	  = @in_vchApplicationID
