		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_outbound_unpack_attribute3 @in_vchApplicationID	  = @in_vchApplicationID	
															,@in_vchWhMasterID		  = @in_vchWhMasterID		
															,@in_vchOutboundMasterID  = @in_vchOutboundMasterID	 
