															,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	
															,@in_vchLotNumber		  = @in_vchLotNumber		
															,@in_vchExpiryDate		  = @in_vchExpiryDate		
															,@in_vchAttribute1		  = @in_vchAttribute1		
															,@in_vchAttribute2		  = @in_vchAttribute2		
															,@in_vchAttribute3		  = @in_vchAttribute3		
