	SAVE_TRANS:
		DECLARE @v_vchDestLPN		  NVARCHAR(25)
		DECLARE @v_vchLPNControl	  VARCHAR(5)
		DECLARE @v_vchReferenceNumber NVARCHAR(50)
		DECLARE @v_fltConvertQtyEnter FLOAT
		DECLARE @v_fltInvQty		  FLOAT
		DECLARE @v_fltInvQtyAllocate  FLOAT
		-----------------------------------------------------------
		-- Get Destination LPN ให้กับของบน fork
		-- กรณี Location ที่หยิบไม่ได้ Control LPN ก็จะกำหนดให้ LPN Destination เป็น Fork
		-----------------------------------------------------------
		IF @v_vchLPNControl = 'NO'
			BEGIN
				SET @v_vchDestLPN = @in_vchForkLocation
			END
		ELSE
			BEGIN
				-----------------------------------------------------------
				-- Check จำนวนที่หยิบ กับใน Inv ถ้าเท่ากัน ให้เอา LPN ของตัวเองไปด้วย
				-----------------------------------------------------------
				SELECT @v_fltInvQty = SUM(quantity)
					,@v_fltInvQtyAllocate = SUM(ISNULL(quantity_allocated,0))
				FROM v_wms_inventory_data_by_id
				WHERE location_id = @IN_vchLocationID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				AND wh_item_master_id = @IN_vchWhItemMasterID
				AND owner_id = @in_vchOwnerID
				AND inventory_status_id = @in_vchInvStatusID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

				-----------------------------------------------------------
				-- Get Qty enter ให้เป็นหน่วยเล็กที่สุด
				-----------------------------------------------------------
				SELECT @v_fltConvertQtyEnter = @in_fltQuantity * conversion_factor 
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID
				AND uom_prompt = @in_vchUOMPrompt
				AND is_active = 'YES'

				-----------------------------------------------------------
				-- ถ้ามียอดจอง ไม่สามารถเอา LPN ตัวมันเองไปได้
				-----------------------------------------------------------
				IF @v_fltInvQtyAllocate = 0
					BEGIN
						---------------------------------------------------------
						-- ถ้าจำนวนที่หยิบ = จำนวนใน Inventory ต้องเอา LPN เดิมไปด้วย
						---------------------------------------------------------
						IF (@v_fltConvertQtyEnter = @v_fltInvQty)
							BEGIN
								SET @v_vchDestLPN = @in_vchLPN
								RETURN;
							END
						ELSE
							BEGIN
								SET @v_vchDestLPN = @in_vchForkLocation
								RETURN;
							END
					END
				ELSE
					BEGIN
						SET @v_vchDestLPN = @in_vchForkLocation
						RETURN;
					END
			END

		EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT
		EXEC usp_inventory_control_for_pda @in_vchApplicationID		= @in_vchApplicationID
										   ,@in_vchDevice			= @in_vchDeviceID
										   ,@in_vchUserID			= @in_vchUserID
										   ,@in_vchTransactionType	= 'INV_PUTAWAY'
										   ,@in_vchSubTranType		= 'PUTAWAY_SOURCE'
										   ,@in_vchWarehouse		= @in_vchWhID
										   ,@in_vchOwner			= @in_vchOwnerCode
										   ,@in_vchFromLocation		= @in_vchLocation
										   ,@in_vchFromParentLPN	= @in_vchParentLPN
										   ,@in_vchFromLPN			= @in_vchLPN
										   ,@in_vchStatus			= @in_vchInvStatus
										   ,@in_vchLot				= @in_vchLotNumber
										   ,@in_vchExpiryDate		= @in_vchExpiryDate
										   ,@in_vchAttribute1		= @in_vchAttribute1
										   ,@in_vchAttribute2		= @in_vchAttribute2
										   ,@in_vchAttribute3		= @in_vchAttribute3
										   ,@in_vchAttribute4		= @in_vchAttribute4
										   ,@in_vchAttribute5		= @in_vchAttribute5			
										   ,@in_vchToLocation		= @in_vchForkLocation				
										   ,@in_vchToParentLPN		= @in_vchParentLPN				
										   ,@in_vchToLPN			= @v_vchDestLPN
										   ,@in_vchWhItemMasterID 	= @in_vchWhItemMasterID				
										   ,@in_fltQty				= @in_fltQuantity						
										   ,@in_vchUOMPrompt		= @in_vchUOMPrompt				
										   ,@in_vchSerialNumber		= @in_vchSerialNumber				
										   ,@in_vchReferenceNumber	= @v_vchReferenceNumber			
										   ,@in_vchReasonCode		= NULL				
										   ,@out_ErrorCode			= @out_vchErrorCode	output
										   ,@out_ErrorMessage		= @out_vchErrorMsg	output

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		SET @out_vchNextScreen = 'LOCATION'
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_receipt]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_receipt]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchOrderNumber		 NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40),
	@in_vchReceiptHeaderID	 UNIQUEIDENTIFIER,
	@in_vchReceiptNumber	 NVARCHAR(50),
	@in_vchLocationID		 UNIQUEIDENTIFIER,
	@in_vchLocation			 NVARCHAR(50),
	@in_vchParentLPN		 NVARCHAR(25),
	@in_vchLPN				 NVARCHAR(25), 
	@in_vchReceiptMode		 NVARCHAR(25) = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchItemStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL, 
	@in_intItemShelfLife	 INT = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_dtMFGDate			 DATE = NULL, 
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_dtReceiveDate		 DATE = NULL,
	@in_vchUomPrompt		 NVARCHAR(40) = NULL,
	@in_fltQuantity			 FLOAT,
	@in_vchReasonCode		 NVARCHAR(20) = NULL,
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchExpDateControl	 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @Round INT
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			EXEC usp_api_validate_receipt_order_number @in_vchApplicationID = @in_vchApplicationID 
													  ,@in_vchLocalID		= @in_vchLocalID		 
													  ,@in_vchUserID		= @in_vchUserID		 
													  ,@in_vchDeviceID		= @in_vchDeviceID		 
													  ,@in_vchWhMasterID	= @in_vchWhMasterID	 
													  ,@in_vchOrderNumber	= @in_vchOrderNumber	 
													  ,@out_vchErrorCode	= @out_vchErrorCode	 OUTPUT
													  ,@out_vchErrorMsg	 	= @out_vchErrorMsg	 OUTPUT
													  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT	 

			RETURN;
		END
	IF @in_vchControlName = 'PARTIAL_RECEIPT_NUMBER'
		BEGIN
			EXEC usp_api_validate_receipt_partial_receipt_number @in_vchApplicationID	= @in_vchApplicationID	
																,@in_vchLocalID			= @in_vchLocalID			
																,@in_vchWhMasterID		= @in_vchWhMasterID		
																,@in_vchInboundMasterID	= @in_vchInboundMasterID	
																,@in_vchOrderNumber		= @in_vchOrderNumber		
																,@in_vchReceiptNumber	= @in_vchReceiptNumber	
																,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT
																,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
																,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_receipt_location @in_vchApplicationID		= @in_vchApplicationID	
												  , @in_vchLocalID			= @in_vchLocalID			
												  , @in_vchWhMasterID		= @in_vchWhMasterID		
												  , @in_vchInboundMasterID	= @in_vchInboundMasterID	
												  , @in_vchLocation			= @in_vchLocation			
												  , @out_vchErrorCode		= @out_vchErrorCode OUTPUT
												  , @out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
												  , @out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			------------------------------------------------------------------------------
			-- Check Rule 'Parent LPN'
			------------------------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_RECEIVE_INTERFACE_BY_LPN' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'LPN_RECEIPT'			
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_receipt_lpn @in_vchApplicationID	= @in_vchApplicationID	
											 ,@in_vchLocalID		= @in_vchLocalID			
											 ,@in_vchWhMasterID		= @in_vchWhMasterID	
											 ,@in_vchInboundMasterID= @in_vchInboundMasterID
											 ,@in_vchOrderNumber	= @in_vchOrderNumber		
											 ,@in_vchLocation		= @in_vchLocation			
											 ,@in_vchParentLPN		= @in_vchParentLPN		
											 ,@in_vchLPN			= @in_vchLPN				
			 								 ,@in_vchScreenName		= @in_vchControlName
											 ,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT
											 ,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT
											 ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'RECEIPT_MODE'
		BEGIN
			EXEC usp_api_validate_receipt_receipt_mode @in_vchApplicationID	= @in_vchApplicationID	
													  ,@in_vchLocalID		= @in_vchLocalID			
													  ,@in_vchReceiptMode	= @in_vchReceiptMode	
													  ,@out_vchErrorCode	= @out_vchErrorCode OUTPUT	
													  ,@out_vchErrorMsg		= @out_vchErrorMsg	OUTPUT
													  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_receipt_item_status  @in_vchApplicationID  = @in_vchApplicationID
													  ,@in_vchLocalID		 = @in_vchLocalID
													  ,@in_vchItemStatus	 = @in_vchItemStatus
													  ,@out_vchErrorCode	 = @out_vchErrorCode	OUTPUT
													  ,@out_vchErrorMsg	     = @out_vchErrorMsg	    OUTPUT
													  ,@out_vchNextScreen	 = @out_vchNextScreen	OUTPUT
			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_receipt_item_number @in_vchApplicationID	 = @in_vchApplicationID	
													 ,@in_vchLocalID		 = @in_vchLocalID			
													 ,@in_vchWhMasterID		 = @in_vchWhMasterID		
													 ,@in_vchInboundMasterID = @in_vchInboundMasterID	
													 ,@in_vchOrderNumber	 = @in_vchOrderNumber		
													 ,@in_vchOwnerID		 = @in_vchOwnerID			
													 ,@in_vchReceiptMode	 = @in_vchReceiptMode		
													 ,@in_vchParentLpn		 = @in_vchParentLpn		
													 ,@in_vchLPN			 = @in_vchLPN				
													 ,@in_vchItemNumber		 = @in_vchItemNumber
													 ,@out_vchItemMasterID	 = @in_vchItemMasterID OUTPUT
													 ,@out_vchWhItemMasterID = @in_vchWhItemMasterID OUTPUT 
													 ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
													 ,@out_vchErrorMsg		 = @out_vchErrorMsg	 OUTPUT
													 ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			EXEC usp_api_validate_receipt_lot_number @in_vchApplicationID     = @in_vchApplicationID    
												    ,@in_vchLocalID		      = @in_vchLocalID		    
												    ,@in_vchWhMasterID	      = @in_vchWhMasterID	    
												    ,@in_vchInboundMasterID   = @in_vchInboundMasterID  
												    ,@in_vchReceiptMode	      = @in_vchReceiptMode	    
												    ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID   
												    ,@in_intItemShelfLife     = @in_intItemShelfLife    
												    ,@in_vchLotNumber	      = @in_vchLotNumber	    
												    ,@in_vchExpDateControl    = @in_vchExpDateControl   
												    ,@in_vchSNControl	      = @in_vchSNControl	    
												    ,@in_vchAttribute1Control = @in_vchAttribute1Control
												    ,@in_vchAttribute2Control = @in_vchAttribute2Control
												    ,@in_vchAttribute3Control = @in_vchAttribute3Control
												    ,@in_vchAttribute4Control = @in_vchAttribute4Control
												    ,@in_vchAttribute5Control = @in_vchAttribute5Control
												    ,@out_vchErrorCode	      = @out_vchErrorCode	OUTPUT   
												    ,@out_vchErrorMsg	      = @out_vchErrorMsg	OUTPUT   
												    ,@out_vchNextScreen	      = @out_vchNextScreen	OUTPUT   					     
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'MFG_DATE'
		BEGIN
			EXEC usp_api_validate_receipt_mfg_date @in_vchApplicationID       = @in_vchApplicationID     
											      ,@in_vchLocalID		      = @in_vchLocalID		      
											      ,@in_vchInboundMasterID     = @in_vchInboundMasterID   
											      ,@in_vchReceiptMode		  = @in_vchReceiptMode		 
											      ,@in_vchWhItemMasterID      = @in_vchWhItemMasterID    
											      ,@in_dtMFGDate			  = @in_dtMFGDate			 
											      ,@in_intItemShelfLife	      = @in_intItemShelfLife	 
											      ,@in_vchLotNumber		      = @in_vchLotNumber		 
											      ,@in_vchSNControl		      = @in_vchSNControl		 
											      ,@in_vchAttribute1Control   = @in_vchAttribute1Control
											      ,@in_vchAttribute2Control   = @in_vchAttribute2Control
											      ,@in_vchAttribute3Control   = @in_vchAttribute3Control
											      ,@in_vchAttribute4Control   = @in_vchAttribute4Control
											      ,@in_vchAttribute5Control   = @in_vchAttribute5Control
											      ,@out_vchErrorCode	      = @out_vchErrorCode	OUTPUT
											      ,@out_vchErrorMsg	          = @out_vchErrorMsg	OUTPUT
											      ,@out_vchNextScreen		  = @out_vchNextScreen	OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			EXEC usp_api_validate_receipt_expiry_date @in_vchApplicationID		= @in_vchApplicationID	 
													 ,@in_vchLocalID			= @in_vchLocalID			  
													 ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
													 ,@in_vchInboundMasterID	= @in_vchInboundMasterID	  
													 ,@in_vchReceiptMode		= @in_vchReceiptMode		  
													 ,@in_vchWhItemMasterID	 	= @in_vchWhItemMasterID	 
													 ,@in_vchLotNumber		 	= @in_vchLotNumber		 
													 ,@in_vchExpiryDate		 	= @in_vchExpiryDate		 
													 ,@in_vchSNControl		 	= @in_vchSNControl		 
													 ,@in_vchAttribute1Control 	= @in_vchAttribute1Control 
													 ,@in_vchAttribute2Control 	= @in_vchAttribute2Control 
													 ,@in_vchAttribute3Control 	= @in_vchAttribute3Control 
													 ,@in_vchAttribute4Control 	= @in_vchAttribute4Control 
													 ,@in_vchAttribute5Control 	= @in_vchAttribute5Control 
													 ,@out_vchErrorCode		 	= @out_vchErrorCode	 OUTPUT
													 ,@out_vchErrorMsg		 	= @out_vchErrorMsg	 OUTPUT
													 ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	  
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			EXEC usp_api_validate_receipt_attribute1 @in_vchApplicationID     = @in_vchApplicationID     
													,@in_vchLocalID		      = @in_vchLocalID		     
													,@in_vchWhMasterID	      = @in_vchWhMasterID	     
													,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
													,@in_vchReceiptMode	      = @in_vchReceiptMode	     
													,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
													,@in_vchLotNumber	      = @in_vchLotNumber	     
													,@in_vchExpiryDate	      = @in_vchExpiryDate	     
													,@in_vchAttribute1		  = @in_vchAttribute1		 
													,@in_vchSnControl	      = @in_vchSnControl	     
													,@in_vchAttribute1Control = @in_vchAttribute1Control 
													,@in_vchAttribute2Control = @in_vchAttribute2Control 
													,@in_vchAttribute3Control = @in_vchAttribute3Control 
													,@in_vchAttribute4Control = @in_vchAttribute4Control 
													,@in_vchAttribute5Control = @in_vchAttribute5Control 
													,@out_vchErrorCode	      = @out_vchErrorCode	OUTPUT   
													,@out_vchErrorMsg	      = @out_vchErrorMsg	OUTPUT   
													,@out_vchNextScreen	      = @out_vchNextScreen	OUTPUT   									 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_receipt_attribute2 @in_vchApplicationID	  = @in_vchApplicationID	 
													,@in_vchLocalID			  = @in_vchLocalID			 
													,@in_vchWhMasterID		  = @in_vchWhMasterID		 
													,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
													,@in_vchReceiptMode		  = @in_vchReceiptMode		 
													,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	 
													,@in_vchLotNumber		  = @in_vchLotNumber		 
													,@in_vchExpiryDate		  = @in_vchExpiryDate		 
													,@in_vchAttribute1		  = @in_vchAttribute1		 
													,@in_vchAttribute2		  = @in_vchAttribute2		 
													,@in_vchSnControl		  = @in_vchSnControl		 
													,@in_vchAttribute2Control = @in_vchAttribute2Control  
													,@in_vchAttribute3Control = @in_vchAttribute3Control  
													,@in_vchAttribute4Control = @in_vchAttribute4Control  
													,@in_vchAttribute5Control = @in_vchAttribute5Control  
													,@out_vchErrorCode	      = @out_vchErrorCode	OUTPUT     
													,@out_vchErrorMsg	      = @out_vchErrorMsg	OUTPUT     
													,@out_vchNextScreen	      = @out_vchNextScreen	OUTPUT     
													 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_receipt_attribute3 @in_vchApplicationID	  = @in_vchApplicationID	 
													,@in_vchLocalID			  = @in_vchLocalID			 
													,@in_vchWhMasterID		  = @in_vchWhMasterID		 
													,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
													,@in_vchReceiptMode		  = @in_vchReceiptMode		 
													,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	 
													,@in_vchLotNumber		  = @in_vchLotNumber		 
													,@in_vchExpiryDate		  = @in_vchExpiryDate		 
													,@in_vchAttribute1		  = @in_vchAttribute1		 
													,@in_vchAttribute2		  = @in_vchAttribute2		 
													,@in_vchAttribute3		  = @in_vchAttribute3		 
													,@in_vchSnControl		  = @in_vchSnControl		 
													,@in_vchAttribute4Control = @in_vchAttribute4Control  
													,@in_vchAttribute5Control = @in_vchAttribute5Control  
													,@out_vchErrorCode		  = @out_vchErrorCode	OUTPUT	 
													,@out_vchErrorMsg		  = @out_vchErrorMsg	OUTPUT	 
													,@out_vchNextScreen		  = @out_vchNextScreen	OUTPUT	 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_receipt_attribute4 @in_vchApplicationID	  = @in_vchApplicationID	 
													,@in_vchLocalID			  = @in_vchLocalID			 
													,@in_vchWhMasterID		  = @in_vchWhMasterID		 
													,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
													,@in_vchReceiptMode		  = @in_vchReceiptMode		 
													,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	 
													,@in_vchLotNumber		  = @in_vchLotNumber		 
													,@in_vchExpiryDate		  = @in_vchExpiryDate		 
													,@in_vchAttribute1		  = @in_vchAttribute1		 
													,@in_vchAttribute2		  = @in_vchAttribute2		 
													,@in_vchAttribute3		  = @in_vchAttribute3		 
													,@in_vchAttribute4		  = @in_vchAttribute4		 
													,@in_vchSnControl		  = @in_vchSnControl		 
													,@in_vchAttribute5Control = @in_vchAttribute5Control  
													,@out_vchErrorCode		  = @out_vchErrorCode	OUTPUT 
													,@out_vchErrorMsg		  = @out_vchErrorMsg	OUTPUT 
													,@out_vchNextScreen		  = @out_vchNextScreen	OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_receipt_attribute5 @in_vchApplicationID	  = @in_vchApplicationID	 
													,@in_vchLocalID			  = @in_vchLocalID			 
													,@in_vchWhMasterID		  = @in_vchWhMasterID		 
													,@in_vchInboundMasterID	  = @in_vchInboundMasterID	 
													,@in_vchReceiptMode	      = @in_vchReceiptMode	     
													,@in_vchWhItemMasterID    = @in_vchWhItemMasterID    
													,@in_vchLotNumber	      = @in_vchLotNumber	     
													,@in_vchExpiryDate	      = @in_vchExpiryDate	     
													,@in_vchAttribute1		  = @in_vchAttribute1		 
													,@in_vchAttribute2		  = @in_vchAttribute2		 
													,@in_vchAttribute3		  = @in_vchAttribute3		 
													,@in_vchAttribute4		  = @in_vchAttribute4		 
													,@in_vchAttribute5		  = @in_vchAttribute5		 
													,@in_vchSnControl	      = @in_vchSnControl	     
													,@out_vchErrorCode		  = @out_vchErrorCode	OUTPUT	 
													,@out_vchErrorMsg		  = @out_vchErrorMsg	OUTPUT	 
													,@out_vchNextScreen		  = @out_vchNextScreen	OUTPUT	 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT TOP 1 @in_dtReceiveDate = receive_date FROM t_wms_inbound_detail 
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
					AND ROUND(quantity_receive,@Round) = 0				 
				END
			
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'RECEIVE_DATE'
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail 
									WHERE inbound_order_master_id = @in_vchInboundMasterID 
									AND wh_item_master_id = @in_vchWhItemMasterID
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
									AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
									AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
									AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																				WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																				WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																				ELSE ROUND(quantity_order,@Round) END)			 
									AND receive_date = @in_dtReceiveDate)
						BEGIN
							SET @out_vchErrorCode = 'NOT_FOUND_RECEIVE_DATE_IN_PLAN'
							SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
							RETURN;
						END
				END
				 
			IF (@in_vchSNControl = 'FULL')
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
					RETURN;
				END
			ELSE
				BEGIN 
					IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
						BEGIN
							SET @out_vchNextScreen = 'UOM_QTY'
							RETURN;
						END
					ELSE
						BEGIN
							GOTO SAVE_TRANS;
							RETURN;
						END
				END
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'REASON'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LPN_RECEIPT'
		BEGIN
			RETURN;
		END
	IF @in_vchControlName = 'LPN_CONFIRM'
		BEGIN
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		DECLARE @v_vchIsSave NVARCHAR(3) ='' 
		DECLARE @v_vchItemUOMID UNIQUEIDENTIFIER = NULL

		IF @in_vchReceiptMode = 'BY EACH'
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id 
					,@in_vchUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1;
			END
		ELSE
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUomPrompt AND is_active = 'YES'
			END
		EXEC usp_api_validate_receipt_qty_in_plan @in_vchScreenName		  = @in_vchControlName
												 ,@in_vchApplicationID	  = @in_vchApplicationID	
												 ,@in_vchLocalID		  = @in_vchLocalID				
												 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
												 ,@in_vchInboundMasterID  = @in_vchInboundMasterID    
												 ,@in_vchOrderNumber	  = @in_vchOrderNumber			
												 ,@in_vchOwnerID		  = @in_vchOwnerID				
												 ,@in_vchOwnerCode		  = @in_vchOwnerCode			
												 ,@in_vchParentLPN		  = @in_vchParentLPN		
												 ,@in_vchLPN			  = @in_vchLPN					
												 ,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	
												 ,@in_vchItemMasterID	  = @in_vchItemMasterID			
												 ,@in_vchItemNumber		  = @in_vchItemNumber			
												 ,@in_fltQtyEntered		  = @in_fltQuantity		
												 ,@in_vchItemUOMID		  = @v_vchItemUOMID			
												 ,@in_vchLot			  = @in_vchLotNumber					
												 ,@in_vchExpiryDate		  = @in_vchExpiryDate
												 ,@in_vchAttribute1		  = @in_vchAttribute1		
												 ,@in_vchAttribute2		  = @in_vchAttribute2		
												 ,@in_vchAttribute3		  = @in_vchAttribute3		
												 ,@in_vchAttribute4		  = @in_vchAttribute4		
												 ,@in_vchAttribute5		  = @in_vchAttribute5		
												 ,@in_vchSerialNumber	  = @in_vchSerialNumber	 			
												 ,@out_vchIsSave		  = @v_vchIsSave		OUTPUT		
												 ,@out_vchErrorCode		  = @out_vchErrorCode	OUTPUT	
												 ,@out_vchErrorMsg		  = @out_vchErrorMsg	OUTPUT	
												 ,@out_vchNextScreen	  = @out_vchNextScreen	OUTPUT		

		IF @v_vchIsSave = 'YES' 
			BEGIN
				--Save Transaction
				EXEC usp_inbound_update_receive_qty @in_vchApplicationID	= @in_vchApplicationID	
												   ,@in_vchDeviceID			= @in_vchDeviceID			
												   ,@in_vchUserID			= @in_vchUserID			
												   ,@in_vchWhMasterID		= @in_vchWhMasterID
												   ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
												   ,@in_vchReceiptHeaderID	= @in_vchReceiptHeaderID	
												   ,@in_vchLocationID		= @in_vchLocationID
												   ,@in_vchInvStatusID		= @in_vchItemStatusID
												   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
												   ,@in_fltQuantity			= @in_fltQuantity			
												   ,@in_vchItemUomID		= @v_vchItemUOMID		
												   ,@in_vchLot				= @in_vchLotNumber			
												   ,@in_vchExpiryDate		= @in_vchExpiryDate		
												   ,@in_vchSerial			= @in_vchSerialNumber		
												   ,@in_vchParentLPN		= @in_vchParentLPN		
												   ,@in_vchLPN				= @in_vchLPN				
												   ,@in_vchReasonCode		= @in_vchReasonCode
												   ,@in_vchAttribute1		= @in_vchAttribute1		
												   ,@in_vchAttribute2		= @in_vchAttribute2		
												   ,@in_vchAttribute3		= @in_vchAttribute3		
												   ,@in_vchAttribute4		= @in_vchAttribute4		
												   ,@in_vchAttribute5		= @in_vchAttribute5		
												   ,@in_dtReceiveDate		= @in_dtReceiveDate		
												   ,@in_dtMfgDate			= @in_dtMfgDate			
												   ,@out_ErrorCode			= @out_vchErrorCode	OUTPUT	
												   ,@out_ErrorMessage		= @out_vchErrorMsg	OUTPUT 
				IF ISNULL(@out_vchErrorCode,'') <> '0'
					BEGIN
						SET @out_vchNextScreen = NULL
						RETURN;
					END
			END
		ELSE 
			BEGIN
				RETURN;
			END
		
		IF @in_vchReceiptMode = 'BY EACH' OR @in_vchControlName = 'SERIAL_NUMBER'
			GOTO FINAL_SCREEN;

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_receipt_final_screen @in_vchWhMasterID	  = @in_vchWhMasterID	
												  ,@in_vchInboundMasterID = @in_vchInboundMasterID	
												  ,@in_vchLocationID	  = @in_vchLocationID		
												  ,@in_vchReceiptMode	  = @in_vchReceiptMode	
												  ,@in_vchParentLPN		  = @in_vchParentLPN	
												  ,@in_vchLPN			  = @in_vchLPN			
												  ,@in_vchWhItemMasterID  = @in_vchWhItemMasterID
												  ,@in_vchSNControl       = @in_vchSNControl
												  ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_receipt_all]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_receipt_all]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40), 
	@in_vchLocationID		 UNIQUEIDENTIFIER,
	@in_vchLocation			 NVARCHAR(50), 
	@in_vchLPN				 NVARCHAR(25),  
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @Round INT
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'INBOUND_ORDER'
		BEGIN
			EXEC usp_api_validate_receipt_all_order_number @in_vchApplicationID		 = @in_vchApplicationID 
														  ,@in_vchLocalID			 = @in_vchLocalID		 
														  ,@in_vchUserID			 = @in_vchUserID		 
														  ,@in_vchDeviceID			 = @in_vchDeviceID		 
														  ,@in_vchWhMasterID		 = @in_vchWhMasterID	 
														  ,@in_vchInboundOrderNumber = @in_vchInboundOrderNumber	 
														  ,@out_vchErrorCode		 = @out_vchErrorCode	 OUTPUT
														  ,@out_vchErrorMsg	 		 = @out_vchErrorMsg	 OUTPUT
														  ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT	 

			RETURN;
		END 
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_receipt_all_location @in_vchApplicationID		= @in_vchApplicationID	
													  ,@in_vchLocalID			= @in_vchLocalID			
													  ,@in_vchWhMasterID		= @in_vchWhMasterID		
													  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
													  ,@in_vchLocation			= @in_vchLocation			
													  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
													  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
													  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END 
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_receipt_all_lpn @in_vchApplicationID		= @in_vchApplicationID	  
											     ,@in_vchLocalID			= @in_vchLocalID			    
											     ,@in_vchWhMasterID		  	= @in_vchWhMasterID		  
											     ,@in_vchInboundMasterID	= @in_vchInboundMasterID	    
											     ,@in_vchInboundOrderNumber = @in_vchInboundOrderNumber 
											     ,@in_vchLocationID		  	= @in_vchLocationID		  
											     ,@in_vchLocation			= @in_vchLocation			    
											     ,@in_vchLPN				= @in_vchLPN				    
			 								     ,@out_vchErrorCode		  	= @out_vchErrorCode	OUTPUT	  
											     ,@out_vchErrorMsg		  	= @out_vchErrorMsg OUTPUT	  
											     ,@out_vchNextScreen 		= @out_vchNextScreen OUTPUT	  
			
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END 
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		--Save Transaction
		--กรณีที่เป็น Location ที่ไม่ได้ control LPN จะไม่ได้ Next ไป LPN ทำให้ไม่ได้ค่า Location ID ดังนั้นทำให้ต้อง get ใหม่อีกครั้ง 
		IF @in_vchLocationID IS NULL
			BEGIN
				SELECT TOP 1 @in_vchLocationID = location_id  
				FROM t_wms_location
				WHERE location = @in_vchLocation
				AND wh_master_id = @in_vchWhMasterID
				AND is_active = 'YES'
				AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')

				SELECT @in_vchLocationID AS location_id
			END

		EXEC usp_inbound_update_receive_all @in_vchApplicationID	= @in_vchApplicationID	
										   ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
										   ,@in_vchLocationID		= @in_vchLocationID		
										   ,@in_vchLPN				= @in_vchLPN				
										   ,@in_vchDeviceID			= @in_vchDeviceID			
										   ,@in_vchUserID			= @in_vchUserID	 	
										   ,@out_ErrorCode			= @out_vchErrorCode OUTPUT			
										   ,@out_ErrorMessage		= @out_vchErrorMsg	OUTPUT	
										 	
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_receipt_all_final_screen @in_vchWhMasterID	  = @in_vchWhMasterID	
													  ,@in_vchInboundMasterID = @in_vchInboundMasterID	
													  ,@in_vchLocationID	  = @in_vchLocationID		
													  ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_receipt_return]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_receipt_return]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchControlName		 NVARCHAR(50),	--Current Screen
	@in_vchLocalID			 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchOrderNumber		 NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40),
	@in_vchReceiptHeaderID	 UNIQUEIDENTIFIER,
	@in_vchReceiptNumber	 NVARCHAR(50),
	@in_vchLocationID		 UNIQUEIDENTIFIER,
	@in_vchLocation			 NVARCHAR(50),
	@in_vchParentLPN		 NVARCHAR(25),
	@in_vchLPN				 NVARCHAR(25),
	@in_vchItemStatusID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchItemStatus		 NVARCHAR(50) = NULL,   
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL,  
	@in_vchLotNumber		 NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_dtReceiveDate		 DATE = NULL,
	@in_vchUomPrompt		 NVARCHAR(40) = NULL, 
	@in_fltQuantity			 FLOAT,
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchExpDateControl	 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
