			SET @out_vchNextScreen = 'LPN'
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_receipt_return_lpn @in_vchApplicationID	= @in_vchApplicationID	
													,@in_vchLocalID			= @in_vchLocalID			
													,@in_vchWhMasterID		= @in_vchWhMasterID		
													,@in_vchInboundMasterID	= @in_vchInboundMasterID	
													,@in_vchOrderNumber		= @in_vchOrderNumber		
													,@in_vchLocationID		= @in_vchLocationID		
													,@in_vchLocation		= @in_vchLocation			
			 										,@in_vchParentLPN		= @in_vchParentLPN		
													,@in_vchLPN				= @in_vchLPN				
													,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
													,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen		= @out_vchNextScreen OUTPUT

			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_receipt_return_item_status  @in_vchApplicationID = @in_vchApplicationID
															 ,@in_vchLocalID	   = @in_vchLocalID
															 ,@in_vchItemStatus	   = @in_vchItemStatus
															 ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT
															 ,@out_vchErrorMsg	   = @out_vchErrorMsg OUTPUT
															 ,@out_vchNextScreen   = @out_vchNextScreen	OUTPUT
			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_receipt_return_item_number @in_vchApplicationID	= @in_vchApplicationID
															,@in_vchLocalID			= @in_vchLocalID
															,@in_vchWhMasterID		= @in_vchWhMasterID
															,@in_vchInboundMasterID	= @in_vchInboundMasterID
															,@in_vchOwnerID			= @in_vchOwnerID
															,@in_vchParentLpn		= @in_vchParentLpn
															,@in_vchLPN				= @in_vchLPN
															,@in_vchItemNumber		= @in_vchItemNumber
															,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
															,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
															,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			EXEC usp_api_validate_receipt_return_lot_number @in_vchApplicationID     = @in_vchApplicationID     
														   ,@in_vchLocalID		     = @in_vchLocalID		      
														   ,@in_vchWhMasterID	     = @in_vchWhMasterID	      
														   ,@in_vchInboundMasterID   = @in_vchInboundMasterID    
														   ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID     
														   ,@in_vchLotNumber	     = @in_vchLotNumber	      
														   ,@in_vchExpDateControl    = @in_vchExpDateControl     
														   ,@in_vchSNControl	     = @in_vchSNControl	      
														   ,@in_vchAttribute1Control = @in_vchAttribute1Control  
														   ,@in_vchAttribute2Control = @in_vchAttribute2Control  
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control  
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control  
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control  
														   ,@out_vchErrorCode	     = @out_vchErrorCode OUTPUT    
														   ,@out_vchErrorMsg	     = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen	     = @out_vchNextScreen OUTPUT								    					     
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			EXEC usp_api_validate_receipt_return_expiry_date @in_vchApplicationID	  = @in_vchApplicationID	 
															,@in_vchLocalID			  = @in_vchLocalID			   
															,@in_vchWhMasterID		  = @in_vchWhMasterID		 
															,@in_vchInboundMasterID	  = @in_vchInboundMasterID	   
															,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	   
															,@in_vchLotNumber		  = @in_vchLotNumber		 
															,@in_vchExpiryDate		  = @in_vchExpiryDate		 
															,@in_vchSNControl		  = @in_vchSNControl		 
															,@in_vchAttribute1Control = @in_vchAttribute1Control  
															,@in_vchAttribute2Control = @in_vchAttribute2Control  
															,@in_vchAttribute3Control = @in_vchAttribute3Control  
															,@in_vchAttribute4Control = @in_vchAttribute4Control  
															,@in_vchAttribute5Control = @in_vchAttribute5Control  
															,@out_vchErrorCode		  = @out_vchErrorCode OUTPUT
															,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
															,@out_vchNextScreen		  = @out_vchNextScreen OUTPUT					 	  
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			EXEC usp_api_validate_receipt_return_attribute1 @in_vchApplicationID     = @in_vchApplicationID    
														   ,@in_vchLocalID		     = @in_vchLocalID		    
														   ,@in_vchWhMasterID	     = @in_vchWhMasterID	    
														   ,@in_vchInboundMasterID	 = @in_vchInboundMasterID	
														   ,@in_vchWhItemMasterID    = @in_vchWhItemMasterID   
														   ,@in_vchLotNumber	     = @in_vchLotNumber	    
														   ,@in_vchExpiryDate	     = @in_vchExpiryDate	    
														   ,@in_vchAttribute1		 = @in_vchAttribute1		
														   ,@in_vchSnControl	     = @in_vchSnControl	    
														   ,@in_vchAttribute1Control = @in_vchAttribute1Control
														   ,@in_vchAttribute2Control = @in_vchAttribute2Control
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@out_vchErrorCode	     = @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg	     = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen	     = @out_vchNextScreen OUTPUT		   									 
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_receipt_return_attribute2 @in_vchApplicationID	 = @in_vchApplicationID	
														   ,@in_vchLocalID			 = @in_vchLocalID			
														   ,@in_vchWhMasterID		 = @in_vchWhMasterID		
														   ,@in_vchInboundMasterID	 = @in_vchInboundMasterID	
														   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	
														   ,@in_vchLotNumber		 = @in_vchLotNumber		
														   ,@in_vchExpiryDate		 = @in_vchExpiryDate		
														   ,@in_vchAttribute1		 = @in_vchAttribute1		
														   ,@in_vchAttribute2		 = @in_vchAttribute2		
														   ,@in_vchSnControl		 = @in_vchSnControl		
														   ,@in_vchAttribute2Control = @in_vchAttribute2Control
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@out_vchErrorCode	     = @out_vchErrorCode OUTPUT    
														   ,@out_vchErrorMsg	     = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen	     = @out_vchNextScreen OUTPUT					 
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_receipt_return_attribute3 @in_vchApplicationID	 = @in_vchApplicationID	
														   ,@in_vchLocalID			 = @in_vchLocalID			
														   ,@in_vchWhMasterID		 = @in_vchWhMasterID		
														   ,@in_vchInboundMasterID	 = @in_vchInboundMasterID	
														   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	
														   ,@in_vchLotNumber		 = @in_vchLotNumber		
														   ,@in_vchExpiryDate		 = @in_vchExpiryDate		
														   ,@in_vchAttribute1		 = @in_vchAttribute1		
														   ,@in_vchAttribute2		 = @in_vchAttribute2		
														   ,@in_vchAttribute3		 = @in_vchAttribute3		
														   ,@in_vchSnControl		 = @in_vchSnControl		
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
															 
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_receipt_return_attribute4 @in_vchApplicationID	 = @in_vchApplicationID	
														   ,@in_vchLocalID			 = @in_vchLocalID			
														   ,@in_vchWhMasterID		 = @in_vchWhMasterID		
														   ,@in_vchInboundMasterID	 = @in_vchInboundMasterID	
														   ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	
														   ,@in_vchLotNumber		 = @in_vchLotNumber		
														   ,@in_vchExpiryDate		 = @in_vchExpiryDate		
														   ,@in_vchAttribute1		 = @in_vchAttribute1		
														   ,@in_vchAttribute2		 = @in_vchAttribute2		
														   ,@in_vchAttribute3		 = @in_vchAttribute3		
														   ,@in_vchAttribute4		 = @in_vchAttribute4		
														   ,@in_vchSnControl		 = @in_vchSnControl		
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT		
														   ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT		
														   ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_receipt_return_attribute5 @in_vchApplicationID	= @in_vchApplicationID	
														   ,@in_vchLocalID			= @in_vchLocalID			
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		
														   ,@in_vchInboundMasterID	= @in_vchInboundMasterID	
														   ,@in_vchWhItemMasterID   = @in_vchWhItemMasterID   
														   ,@in_vchLotNumber	    = @in_vchLotNumber	    
														   ,@in_vchExpiryDate	    = @in_vchExpiryDate	    
														   ,@in_vchAttribute1		= @in_vchAttribute1		
														   ,@in_vchAttribute2		= @in_vchAttribute2		
														   ,@in_vchAttribute3		= @in_vchAttribute3		
														   ,@in_vchAttribute4		= @in_vchAttribute4		
														   ,@in_vchAttribute5		= @in_vchAttribute5		
														   ,@in_vchSnControl	    = @in_vchSnControl	    
														   ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT
														   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
																 
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			--------------------------------------------------------
			SELECT DISTINCT @in_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					RETURN;
				END 
			
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'RECEIVE_DATE'
		BEGIN
			IF @in_vchSnControl = 'FULL'
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
				END
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END 
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		IF @in_vchSNControl = 'FULL'
			SET @in_fltQuantity = 1

		--Save Transaction
		DECLARE @v_vchItemUOMID UNIQUEIDENTIFIER = NULL
		SELECT TOP 1 @v_vchItemUOMID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUomPrompt AND is_active = 'YES'

		EXEC usp_inbound_update_receive_return_qty @in_vchApplicationID	    = @in_vchApplicationID	 
												  ,@in_vchDeviceID			= @in_vchDeviceID			 
												  ,@in_vchUserID			= @in_vchUserID			 
												  ,@in_vchWhMasterID		= @in_vchWhMasterID		 
												  ,@in_vchOwnerID			= @in_vchOwnerID			 
												  ,@in_vchInboundMasterID	= @in_vchInboundMasterID	 
												  ,@in_vchReceiptHeaderID	= @in_vchReceiptHeaderID	 
												  ,@in_vchLocationID		= @in_vchLocationID 
												  ,@in_vchParentLpn		 	= @in_vchParentLpn		 
												  ,@in_vchLpn				= @in_vchLpn				 
												  ,@in_vchInvStatusID		= @in_vchItemStatusID 
												  ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	 
												  ,@in_fltQuantity			= @in_fltQuantity			 
												  ,@in_vchItemUomID		 	= @v_vchItemUOMID		 
												  ,@in_vchLotNumber		 	= @in_vchLotNumber		 
												  ,@in_vchExpiryDate		= @in_vchExpiryDate		 
												  ,@in_vchSerialNumber		= @in_vchSerialNumber		 
												  ,@in_vchAttribute1		= @in_vchAttribute1		 
												  ,@in_vchAttribute2		= @in_vchAttribute2		 
												  ,@in_vchAttribute3		= @in_vchAttribute3		 
												  ,@in_vchAttribute4		= @in_vchAttribute4		 
												  ,@in_vchAttribute5		= @in_vchAttribute5		 
												  ,@in_dtReceiveDate		= @in_dtReceiveDate		 
												  ,@out_ErrorCode			= @out_vchErrorCode OUTPUT 	 
												  ,@out_ErrorMessage		= @out_vchErrorMsg	OUTPUT

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
			 

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_receipt_return_final_screen @in_vchWhMasterID		 = @in_vchWhMasterID		
														 ,@in_vchInboundMasterID = @in_vchInboundMasterID		
														 ,@in_vchLocationID		 = @in_vchLocationID		
														 ,@in_vchParentLPN		 = @in_vchParentLPN		
														 ,@in_vchLPN			 = @in_vchLPN					
														 ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID	
														 ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT		
														 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_system_pick_load]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_system_pick_load]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchBoxNumber			NVARCHAR(25),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT, 
	@in_vchLotControl			VARCHAR(5) = NULL,	
	@in_vchExpDateControl		VARCHAR(5) = NULL,
	@in_vchAttribute1Control	VARCHAR(5) = NULL,
	@in_vchAttribute2Control	VARCHAR(5) = NULL,
	@in_vchAttribute3Control	VARCHAR(5) = NULL,
	@in_vchAttribute4Control	VARCHAR(5) = NULL,
	@in_vchAttribute5Control	VARCHAR(5) = NULL, 
	@in_vchSNControl			VARCHAR(5) = NULL,
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	@in_vchOverPickReasonCode	NVARCHAR(20) = NULL, 
	@out_vchErrorCode			VARCHAR(50) OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'LOAD_ID'
		BEGIN
			EXEC usp_api_validate_pick_load_id @in_vchApplicationID = @in_vchApplicationID
											  ,@in_vchDeviceID		= @in_vchDeviceID		
											  ,@in_vchUserID		= @in_vchUserID		
											  ,@in_vchWhMasterID	= @in_vchWhMasterID	
											  ,@in_vchWarehouse	    = @in_vchWhID	
											  ,@in_vchLoadID		= @in_vchLoadID		
											  ,@in_vchLocalID		= @in_vchLocalID		
											  ,@out_vchErrorCode	= @out_vchErrorCode OUTPUT
											  ,@out_vchErrorMsg	    = @out_vchErrorMsg OUTPUT
											  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
 			RETURN;
		END
