			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_pick_load_attribute2 @in_vchApplicationID		= @in_vchApplicationID	
													  ,@in_vchWhMasterID		= @in_vchWhMasterID		
