	IF @in_vchControlName = 'STAGING_LOCATION'
		BEGIN
			EXEC usp_outbound_update_pickto_staging_by_load @in_vchApplicationID	= @in_vchApplicationID	
														   ,@in_vchDeviceID			= @in_vchDeviceID			
														   ,@in_vchUserID			= @in_vchUserID			
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		
														   ,@in_vchLoadID			= @in_vchLoadID			
