			IF ISNULL(@out_vchErrorCode,'') = '0'
				BEGIN
					SET @out_vchNextScreen = 'LOAD_ID'
				END 
			RETURN;
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			EXEC usp_api_validate_pick_load_serial_number @in_vchApplicationID	= @in_vchApplicationID	
														 ,@in_vchWhMasterID		= @in_vchWhMasterID		
														 ,@in_vchLoadID			= @in_vchLoadID			
														 ,@in_vchLocationID		= @in_vchLocationID		
														 ,@in_vchParentLPN		= @in_vchParentLPN		
														 ,@in_vchLPN			= @in_vchLPN					
														 ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
														 ,@in_vchLotNumber		= @in_vchLotNumber		
														 ,@in_vchExpiryDate		= @in_vchExpiryDate		
														 ,@in_vchAttribute1		= @in_vchAttribute1		
														 ,@in_vchAttribute2		= @in_vchAttribute2		
														 ,@in_vchAttribute3		= @in_vchAttribute3		
														 ,@in_vchAttribute4		= @in_vchAttribute4		
														 ,@in_vchAttribute5		= @in_vchAttribute5		
														 ,@in_vchSerialNumber	= @in_vchSerialNumber			
														 ,@in_vchLocalID		= @in_vchLocalID				
														 ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														 ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														 ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			IF ISNULL(@out_vchErrorCode,'') = ''
				BEGIN
					
					IF ISNULL(@in_vchUOMPrompt,'') = ''
					BEGIN
						SELECT TOP 1 @in_vchUOMPrompt = uom_prompt
						FROM t_wms_item_uom 
						WHERE item_master_id = @in_vchItemMasterID 
						AND primary_uom = 'YES'
						AND is_active = 'YES'
					END
					
					--Select qty back to display on PDA screen 
					SET @in_fltQuantity = 1
					SELECT @in_fltQuantity AS qty

					GOTO SAVE_TRANS;
				END
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		

		EXEC usp_outbound_update_pick_item_by_load @in_vchApplicationID	 = @in_vchApplicationID	
												  ,@in_vchWarehouse		 = @in_vchWhID		
												  ,@in_vchDeviceID		 = @in_vchDeviceID			
												  ,@in_vchUserID		 = @in_vchUserID			
												  ,@in_vchLoadID		 = @in_vchLoadID				
												  ,@in_vchBoxNumber		 = @in_vchBoxNumber		
												  ,@in_vchFromLocation	 = @in_vchLocation			
												  ,@in_vchForkLift		 = @in_vchForkLocation				
												  ,@in_vchItemNumber	 = @in_vchItemNumber			
												  ,@in_fltQty			 = @in_fltQuantity				
												  ,@in_vchUOMPrompt		 = @in_vchUOMPrompt		
												  ,@in_vchFromParentLPN	 = @in_vchParentLPN	
												  ,@in_vchFromLPN		 = @in_vchLPN			
												  ,@in_vchToParentLPN	 = NULL
												  ,@in_vchLot			 = @in_vchLotNumber					
												  ,@in_vchExpiryDate	 = @in_vchExpiryDate		
												  ,@in_vchSerialNo		 = @in_vchSerialNumber		
												  ,@in_vchOverPickReasonCode = @in_vchOverPickReasonCode	
												  ,@in_vchAttribute1	 = @in_vchAttribute1		
												  ,@in_vchAttribute2	 = @in_vchAttribute2		
												  ,@in_vchAttribute3	 = @in_vchAttribute3		
												  ,@in_vchAttribute4	 = @in_vchAttribute4		
												  ,@in_vchAttribute5	 = @in_vchAttribute5		
												  ,@in_vchTrackingNo	 = NULL 
												  ,@out_ErrorCode		 = @out_vchErrorCode OUTPUT		
												  ,@out_ErrorMessage	 = @out_vchErrorMsg OUTPUT
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_pick_load_final_screen @in_vchApplicationID	= @in_vchApplicationID	
													,@in_vchControlName		= @in_vchControlName		
													,@in_vchWhMasterID		= @in_vchWhMasterID		
													,@in_vchLoadID			= @in_vchLoadID			
													,@in_vchLocationID		= @in_vchLocationID		
													,@in_vchParentLPN		= @in_vchParentLPN		
													,@in_vchLPN				= @in_vchLPN				
													,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
													,@in_vchItemMasterID	= @in_vchItemMasterID			
													,@in_vchLotNumber		= @in_vchLotNumber		
													,@in_vchExpDate			= @in_vchExpiryDate			
													,@in_vchSerialNumber	= @in_vchSerialNumber			
													,@in_vchLocalID			= @in_vchLocalID			
													,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT
													,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT
													,@out_vchNextScreen		= @out_vchNextScreen OUTPUT		 
END	
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_system_pick_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_system_pick_lpn]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40), 
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchLPN					NVARCHAR(25),  
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			EXEC usp_api_validate_picking_lpn_order_number @in_vchApplicationID	= @in_vchApplicationID	
												  ,@in_vchWhMasterID			= @in_vchWhMasterID			
												  ,@in_vchWarehouse				= @in_vchWhID		
												  ,@in_vchDeviceID				= @in_vchDeviceID				
												  ,@in_vchUserID				= @in_vchUserID					
												  ,@in_vchOutboundOrderNumber	= @in_vchOutboundOrderNumber			
												  ,@in_vchLocalID				= @in_vchLocalID				
												  ,@out_vchErrorCode			= @out_vchErrorCode		OUTPUT
												  ,@out_vchErrorMsg				= @out_vchErrorMsg		OUTPUT
												  ,@out_vchNextScreen			= @out_vchNextScreen	OUTPUT
			RETURN;
		END 
	IF @in_vchControlName = 'LOCATION'
		BEGIN
		EXEC usp_api_validate_picking_lpn_location @in_vchApplicationID			= @in_vchApplicationID		
												 ,@in_vchWhMasterID				= @in_vchWhMasterID			
												 ,@in_vchWhID					= @in_vchWhID					
												 ,@in_vchOutboundMasterID		= @in_vchOutboundMasterID		
												 ,@in_vchOutboundPickMasterID 	= @in_vchOutboundPickMasterID  				
												 ,@in_vchOwnerID				= @in_vchOwnerID	
												 ,@in_vchLocation				= @in_vchLocation 			
												 ,@in_vchLocalID				= @in_vchLocalID				
												 ,@in_vchUserID					= @in_vchUserID				
												 ,@out_vchErrorCode				= @out_vchErrorCode OUTPUT
												 ,@out_vchErrorMsg				= @out_vchErrorMsg OUTPUT	
												 ,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
		RETURN;
		END 
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_picking_lpn_lpn @in_vchApplicationID			= @in_vchApplicationID		
												 ,@in_vchWhMasterID				= @in_vchWhMasterID			
												 ,@in_vchWhID					= @in_vchWhID					
												 ,@in_vchOutboundMasterID		= @in_vchOutboundMasterID		
												 ,@in_vchOutboundPickMasterID 	= @in_vchOutboundPickMasterID  				
												 ,@in_vchOwnerID				= @in_vchOwnerID	
												 ,@in_vchLocationID				= @in_vchLocationID
												 ,@in_vchLPN					= @in_vchLPN					
												 ,@in_vchLocalID				= @in_vchLocalID				
												 ,@in_vchUserID					= @in_vchUserID				
												 ,@out_vchErrorCode				= @out_vchErrorCode OUTPUT
												 ,@out_vchErrorMsg				= @out_vchErrorMsg OUTPUT	
												 ,@out_vchNextScreen			= @out_vchNextScreen OUTPUT

			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
 
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END
	
	BEGIN --Save Normal
	SAVE_TRANS:
		EXEC usp_outbound_update_pick_item_by_lpn @in_vchApplicationID		= @in_vchApplicationID		
												 ,@in_vchDeviceID			= @in_vchDeviceID				
												 ,@in_vchUserID				= @in_vchUserID				
												 ,@in_vchWhMasterID			= @in_vchWhMasterID			
												 ,@in_vchWhID				= @in_vchWhID					
												 ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	
												 ,@in_vchLocationID			= @in_vchLocationID
												 ,@in_vchLPN				= @in_vchLPN
												 ,@in_vchForkLift			= @in_vchForkLocation	
												 ,@out_ErrorCode			= @out_vchErrorCode OUTPUT
												 ,@out_ErrorMessage			= @out_vchErrorMsg	OUTPUT

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
	END
	  
	--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
		BEGIN
			GOTO FINAL_SCREEN; 
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'FINAL_SCREEN';
			RETURN;
		END

	FINAL_SCREEN:
		EXEC usp_api_validate_picking_lpn_final_screen @in_vchApplicationID		    = @in_vchApplicationID		    
 													  ,@in_vchWhMasterID			= @in_vchWhMasterID			 
													  ,@in_vchWhID					= @in_vchWhID					 
													  ,@in_vchOutboundMasterID		= @in_vchOutboundMasterID		 
													  ,@in_vchOutboundPickMasterID  = @in_vchOutboundPickMasterID  
 													  ,@in_vchLPN					= @in_vchLPN					 
													  ,@in_vchLocalID				= @in_vchLocalID				 
													  ,@in_vchUserID				= @in_vchUserID				 
													  ,@out_vchErrorCode			= @out_vchErrorCode	OUTPUT	
													  ,@out_vchErrorMsg				= @out_vchErrorMsg OUTPUT	
													  ,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
END	
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_system_pick_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_system_pick_order]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25), 
	@in_vchPickMode				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT, 
	
	@in_vchOverLocationID		UNIQUEIDENTIFIER,
	@in_vchOverLocation			NVARCHAR(50),
	@in_vchOverLPN				NVARCHAR(25) = NULL,
	@in_vchOverWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOverItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOverItemNumber		NVARCHAR(50) = NULL, 
	@in_vchOverLotNumber		NVARCHAR(50),
	@in_vchOverExpiryDate		NVARCHAR(50),
	@in_vchOverAttribute1		NVARCHAR(100),
	@in_vchOverAttribute2		NVARCHAR(100),
	@in_vchOverAttribute3		NVARCHAR(100),
	@in_vchOverAttribute4		NVARCHAR(100),
	@in_vchOverAttribute5		NVARCHAR(100),
	@in_vchOverSerialNumber		NVARCHAR(100),
	@in_vchOverUOMPrompt		NVARCHAR(40),
	@in_fltOverQuantity			FLOAT, 
	@in_vchPickNextReasonCode	NVARCHAR(20) = NULL,
	@in_vchOverPickReasonCode	NVARCHAR(20) = NULL,
	@in_vchShortPickReasonCode	NVARCHAR(20) = NULL, 
	@in_vchStgLocation			NVARCHAR(50) = NULL,
	 
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL 
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL 
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL 
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL 
	DECLARE @v_vchAttribute2Control VARCHAR(5) = NULL 
	DECLARE @v_vchAttribute3Control VARCHAR(5) = NULL 
	DECLARE @v_vchAttribute4Control VARCHAR(5) = NULL 
	DECLARE @v_vchAttribute5Control VARCHAR(5) = NULL

	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'OUTBOUND_ORDER'
		BEGIN
			EXEC usp_api_validate_picking_order_number @in_vchApplicationID	= @in_vchApplicationID	
												  ,@in_vchWhMasterID	= @in_vchWhMasterID			
												  ,@in_vchWarehouse		= @in_vchWhID		
												  ,@in_vchDeviceID		= @in_vchDeviceID				
												  ,@in_vchUserID		= @in_vchUserID					
												  ,@in_vchOrderNumber	= @in_vchOutboundOrderNumber			
												  ,@in_vchLocalID		= @in_vchLocalID				
												  ,@out_vchErrorCode	= @out_vchErrorCode		OUTPUT
												  ,@out_vchErrorMsg		= @out_vchErrorMsg		OUTPUT
												  ,@out_vchNextScreen	= @out_vchNextScreen	OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			EXEC usp_api_validate_picking_box_number @in_vchApplicationID = @in_vchApplicationID
												,@in_vchWhMasterID	  = @in_vchWhMasterID
												,@in_vchOrderNumber	  = @in_vchOutboundOrderNumber
												,@in_vchBoxNumber	  = @in_vchBoxNumber
												,@in_vchFork		  = @in_vchForkLocation
												,@in_vchLocalID		  = @in_vchLocalID
												,@out_vchErrorCode	  = @out_vchErrorCode OUTPUT
												,@out_vchErrorMsg	  = @out_vchErrorMsg OUTPUT
												,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'PICK_MODE'
		BEGIN
			EXEC usp_api_validate_pick_mode @in_vchApplicationID= @in_vchApplicationID	
										,@in_vchLocalID		= @in_vchLocalID			
										,@in_vchPickMode	= @in_vchPickMode	
										,@out_vchErrorCode	= @out_vchErrorCode OUTPUT	
										,@out_vchErrorMsg	= @out_vchErrorMsg	OUTPUT
										,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_picking_location @in_vchApplicationID	= @in_vchApplicationID	
											  , @in_vchWhMasterID		= @in_vchWhMasterID			
											  , @in_vchOutboundMasterID	= @in_vchOutboundMasterID		
											  , @in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID	
											  , @in_vchLocation			= @in_vchLocation			
											  , @in_vchLocalID			= @in_vchLocalID	
											  , @out_vchErrorCode		= @out_vchErrorCode OUTPUT
											  , @out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
											  , @out_vchNextScreen		= @out_vchNextScreen OUTPUT

			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			EXEC usp_api_validate_picking_parent_lpn @in_vchApplicationID	 = @in_vchApplicationID
												, @in_vchWhMasterID		     = @in_vchWhMasterID
												, @in_vchOutboundMasterID	 = @in_vchOutboundMasterID 
												, @in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID
												, @in_vchLocationID		   	 = @in_vchLocationID 
												, @in_vchParentLPN		   	 = @in_vchParentLPN
												, @in_vchLocalID			 = @in_vchLocalID	
												, @out_vchErrorCode		   	 = @out_vchErrorCode OUTPUT
												, @out_vchErrorMsg		   	 = @out_vchErrorMsg	OUTPUT
												, @out_vchNextScreen		 = @out_vchNextScreen OUTPUT
 
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			EXEC usp_api_validate_picking_lpn  @in_vchApplicationID		= @in_vchApplicationID
										 , @in_vchWhMasterID			= @in_vchWhMasterID
										 , @in_vchWhID					= @in_vchWhID					
										 , @in_vchOutboundMasterID		= @in_vchOutboundMasterID
										 , @in_vchOutboundPickMasterID  = @in_vchOutboundPickMasterID
										 , @in_vchOrderNumber			= @in_vchOutboundOrderNumber			
										 , @in_vchOwnerID				= @in_vchOwnerID				
										 , @in_vchOwner					= @in_vchOwnerCode
										 , @in_vchLocationID			= @in_vchLocationID
										 , @in_vchParentLPN				= @in_vchParentLPN
										 , @in_vchLPN					= @in_vchLPN
										 , @in_vchLocalID				= @in_vchLocalID
										 , @in_vchDeviceID				= @in_vchDeviceID
										 , @in_vchUserID				= @in_vchUserID
										 , @out_vchErrorCode			= @out_vchErrorCode OUTPUT
										 , @out_vchErrorMsg				= @out_vchErrorMsg	OUTPUT
										 , @out_vchNextScreen			= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_picking_item_number  @in_vchApplicationID		= @in_vchApplicationID
												 , @in_vchWhMasterID			= @in_vchWhMasterID
												 , @in_vchOutboundMasterID		= @in_vchOutboundMasterID
												 , @in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												 , @in_vchOwnerID				= @in_vchOwnerID
												 , @in_vchLocationID			= @in_vchLocationID
												 , @in_vchParentLPN				= @in_vchParentLPN
												 , @in_vchLPN					= @in_vchLPN
												 , @in_vchItemNumber			= @in_vchItemNumber
												 , @in_vchPickMode			 	= @in_vchPickMode
												 , @in_vchLocalID			 	= @in_vchLocalID
												 , @out_vchItemMasterID			= @in_vchItemMasterID OUTPUT
												 , @out_vchWhItemMasterID		= @in_vchWhItemMasterID OUTPUT
												 , @out_vchErrorCode		 	= @out_vchErrorCode OUTPUT 
												 , @out_vchErrorMsg		 		= @out_vchErrorMsg OUTPUT 
												 , @out_vchNextScreen			= @out_vchNextScreen OUTPUT 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			SELECT TOP 1 @v_vchExpDateControl = expiry_date_control
				, @v_vchAttribute1Control = attribute1_control
				, @v_vchAttribute2Control = attribute2_control
				, @v_vchAttribute3Control = attribute3_control
				, @v_vchAttribute4Control = attribute4_control
				, @v_vchAttribute5Control = attribute5_control
				, @v_vchSNControl = sn_control
			FROM t_wms_item 
			WHERE item_master_id = @in_vchItemMasterID

			EXEC usp_api_validate_picking_lot_number @in_vchApplicationID	 = @in_vchApplicationID
												,@in_vchWhMasterID		     = @in_vchWhMasterID 	    
												,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID  
												,@in_vchLocationID		     = @in_vchLocationID		
												,@in_vchParentLPN		     = @in_vchParentLPN		    
												,@in_vchLPN				     = @in_vchLPN				
												,@in_vchWhItemMasterID	     = @in_vchWhItemMasterID
												,@in_vchLotNumber		     = @in_vchLotNumber		    
												,@in_vchExpiryDateControl    = @v_vchExpDateControl    
												,@in_vchSNControl		     = @v_vchSNControl		    
												,@in_vchAttribute1Control    = @v_vchAttribute1Control 
												,@in_vchAttribute2Control    = @v_vchAttribute2Control 
												,@in_vchAttribute3Control    = @v_vchAttribute3Control 
												,@in_vchAttribute4Control    = @v_vchAttribute4Control 
												,@in_vchAttribute5Control    = @v_vchAttribute5Control 
												,@in_vchPickMode			 = @in_vchPickMode
												,@in_vchLocalID			     = @in_vchLocalID	
												,@out_vchErrorCode		     = @out_vchErrorCode	OUTPUT	    
												,@out_vchErrorMsg		     = @out_vchErrorMsg		OUTPUT    
												,@out_vchNextScreen		     = @out_vchNextScreen	OUTPUT 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			SELECT TOP 1 @v_vchAttribute1Control = attribute1_control
				, @v_vchAttribute2Control = attribute2_control
				, @v_vchAttribute3Control = attribute3_control
				, @v_vchAttribute4Control = attribute4_control
				, @v_vchAttribute5Control = attribute5_control
				, @v_vchSNControl = sn_control
			FROM t_wms_item 
			WHERE item_master_id = @in_vchItemMasterID

			EXEC usp_api_validate_picking_expiry_date @in_vchApplicationID	  = @in_vchApplicationID
												 ,@in_vchWhMasterID		      = @in_vchWhMasterID 
												 ,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID 
												 ,@in_vchLocationID		      = @in_vchLocationID
												 ,@in_vchParentLPN		      = @in_vchParentLPN
												 ,@in_vchLPN				  = @in_vchLPN
												 ,@in_vchWhItemMasterID	      = @in_vchWhItemMasterID
												 ,@in_vchLotNumber		      = @in_vchLotNumber
												 ,@in_vchExpDate			  = @in_vchExpiryDate
												 ,@in_vchSNControl		      = @v_vchSNControl
												 ,@in_vchAttribute1Control    = @v_vchAttribute1Control
												 ,@in_vchAttribute2Control    = @v_vchAttribute2Control
												 ,@in_vchAttribute3Control    = @v_vchAttribute3Control
												 ,@in_vchAttribute4Control    = @v_vchAttribute4Control
												 ,@in_vchAttribute5Control    = @v_vchAttribute5Control
												 ,@in_vchPickMode			  = @in_vchPickMode
												 ,@in_vchLocalID			  = @in_vchLocalID
												 ,@out_vchErrorCode		      = @out_vchErrorCode	OUTPUT	    
												 ,@out_vchErrorMsg		      = @out_vchErrorMsg	OUTPUT	    
												 ,@out_vchNextScreen		  = @out_vchNextScreen	OUTPUT	      
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			SELECT TOP 1 @v_vchAttribute2Control = attribute2_control
				, @v_vchAttribute3Control = attribute3_control
				, @v_vchAttribute4Control = attribute4_control
				, @v_vchAttribute5Control = attribute5_control
				, @v_vchSNControl = sn_control
			FROM t_wms_item 
			WHERE item_master_id = @in_vchItemMasterID

			EXEC usp_api_validate_picking_attribute1 @in_vchApplicationID	 = @in_vchApplicationID
												,@in_vchWhMasterID			 = @in_vchWhMasterID
												,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID  
												,@in_vchLocationID			 = @in_vchLocationID
												,@in_vchParentLPN			 = @in_vchParentLPN
												,@in_vchLPN					 = @in_vchLPN
												,@in_vchWhItemMasterID		 = @in_vchWhItemMasterID
												,@in_vchLotNumber			 = @in_vchLotNumber
												,@in_vchExpDate				 = @in_vchExpiryDate
												,@in_vchAttribute1			 = @in_vchAttribute1
												,@in_vchAttribute2Control	 = @v_vchAttribute2Control
												,@in_vchAttribute3Control	 = @v_vchAttribute3Control
												,@in_vchAttribute4Control	 = @v_vchAttribute4Control
												,@in_vchAttribute5Control	 = @v_vchAttribute5Control
												,@in_vchSNControl			 = @v_vchSNControl
												,@in_vchPickMode			 = @in_vchPickMode
												,@in_vchLocalID				 = @in_vchLocalID
												,@out_vchErrorCode			 = @out_vchErrorCode OUTPUT		
												,@out_vchErrorMsg			 = @out_vchErrorMsg OUTPUT	
												,@out_vchNextScreen			 = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			SELECT TOP 1 @v_vchAttribute3Control = attribute3_control
				, @v_vchAttribute4Control = attribute4_control
				, @v_vchAttribute5Control = attribute5_control
				, @v_vchSNControl = sn_control
			FROM t_wms_item 
			WHERE item_master_id = @in_vchItemMasterID

			EXEC usp_api_validate_picking_attribute2 @in_vchApplicationID	 = @in_vchApplicationID
												,@in_vchWhMasterID			 = @in_vchWhMasterID
												,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID
												,@in_vchLocationID			 = @in_vchLocationID
												,@in_vchParentLPN			 = @in_vchParentLPN
												,@in_vchLPN					 = @in_vchLPN
												,@in_vchWhItemMasterID		 = @in_vchWhItemMasterID
												,@in_vchLotNumber			 = @in_vchLotNumber
												,@in_vchExpDate				 = @in_vchExpiryDate
												,@in_vchAttribute1			 = @in_vchAttribute1
												,@in_vchAttribute2			 = @in_vchAttribute2
												,@in_vchAttribute3Control	 = @v_vchAttribute3Control	 
												,@in_vchAttribute4Control	 = @v_vchAttribute4Control	 
												,@in_vchAttribute5Control	 = @v_vchAttribute5Control	 
												,@in_vchSNControl			 = @v_vchSNControl			 
												,@in_vchPickMode			 = @in_vchPickMode			 
												,@in_vchLocalID				 = @in_vchLocalID				 
												,@out_vchErrorCode			 = @out_vchErrorCode  OUTPUT			 
												,@out_vchErrorMsg			 = @out_vchErrorMsg	  OUTPUT	 
												,@out_vchNextScreen			 = @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			SELECT TOP 1 @v_vchAttribute4Control = attribute4_control
				, @v_vchAttribute5Control = attribute5_control
				, @v_vchSNControl = sn_control
			FROM t_wms_item 
			WHERE item_master_id = @in_vchItemMasterID

			EXEC usp_api_validate_picking_attribute3 @in_vchApplicationID	 = @in_vchApplicationID
