															 ,@in_vchSNControl		    = @v_vchSNControl		    
															 ,@in_vchLocalID			= @in_vchLocalID			       
															 ,@out_vchErrorCode		    = @out_vchErrorCode	OUTPUT
															 ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
															 ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS_OVERRIDE;
			RETURN;
		END
	IF @in_vchControlName = 'OVERRIDE_SERIAL_NUMBER'
		BEGIN
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS_OVERRIDE;
			RETURN;
		END
	IF @in_vchControlName = 'OVERRIDE_UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS_OVERRIDE;
			RETURN;
		END 
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END
	
	BEGIN --Save Normal
	SAVE_TRANS:
		DECLARE @v_vchToLPN NVARCHAR(25) = NULL
		IF ISNULL(@in_vchContainerNo,'') = '' 
			SET @v_vchToLPN = @in_vchBoxNumber
		ELSE
			SET @v_vchToLPN = @in_vchContainerNo

		IF @in_vchPickMode = 'BY EACH'
			BEGIN
				SELECT TOP 1 @in_vchUOMPrompt = uom.uom_prompt
				FROM t_wms_item_uom uom
				WHERE uom.item_master_id = @in_vchItemMasterID
				AND uom.primary_uom = 'YES'

				SET @in_fltQuantity = 1
				--Select qty back to display on PDA screen 
				SELECT @in_fltQuantity AS qty
			END

		EXEC usp_outbound_update_pick_item @in_vchApplicationID	 = @in_vchApplicationID	
										  ,@in_vchWarehouse		 = @in_vchWhID		
										  ,@in_vchDeviceID		 = @in_vchDeviceID			
										  ,@in_vchUserID		 = @in_vchUserID			
										  ,@in_vchPicklistNumber = @in_vchOutboundOrderNumber	
										  ,@in_vchFromLocation	 = @in_vchLocation		
										  ,@in_vchForkLift		 = @in_vchForkLocation			
										  ,@in_vchItemNumber	 = @in_vchItemNumber				
										  ,@in_fltQty			 = @in_fltQuantity				
										  ,@in_vchUOMPrompt		 = @in_vchUOMPrompt		
										  ,@in_vchFromParentLPN	 = @in_vchParentLPN	
										  ,@in_vchFromLPN		 = @in_vchLPN			
										  ,@in_vchToParentLPN	 = NULL		
										  ,@in_vchToLPN			 = @v_vchToLPN		
										  ,@in_vchLot			 = @in_vchLotNumber				
										  ,@in_vchExpiryDate	 = @in_vchExpiryDate		
										  ,@in_vchSerialNo		 = @in_vchSerialNumber		
										  ,@in_vchOverPickReason = @in_vchOverPickReasonCode	
										  ,@in_vchAttribute1	 = @in_vchAttribute1		
										  ,@in_vchAttribute2	 = @in_vchAttribute2		
										  ,@in_vchAttribute3	 = @in_vchAttribute3		
										  ,@in_vchAttribute4	 = @in_vchAttribute4		
										  ,@in_vchAttribute5	 = @in_vchAttribute5		
										  ,@in_vchTrackingNo	 = NULL 
										  ,@out_ErrorCode		 = @out_vchErrorCode OUTPUT
										  ,@out_ErrorMessage	 = @out_vchErrorMsg	OUTPUT
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END			
		GOTO CHECK_DISPLAY_FINAL;
	END

	BEGIN --Save Override
	SAVE_TRANS_OVERRIDE:
		IF @in_vchPickMode = 'BY EACH'
			BEGIN
				SELECT TOP 1  @in_vchOverUOMPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchOverItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1;
				
				--Select qty back to display on PDA screen 
				SELECT @in_fltQuantity AS qty
			END
		EXEC usp_outbound_override_update_pick_item @in_vchApplicationID		= @in_vchApplicationID
												   ,@in_vchDeviceID				= @in_vchDeviceID
												   ,@in_vchUserID				= @in_vchUserID
												   ,@in_vchForkLocation			= @in_vchForkLocation
												   ,@in_vchOutboundMasterID		= @in_vchOutboundMasterID
												   ,@in_vchBoxNumber			= @in_vchBoxNumber
												   ,@in_vchLocationID			= @in_vchLocationID
												   ,@in_vchOverrideLocationID	= @in_vchOverLocationID
												   ,@in_vchOverrideLocation		= @in_vchOverLocation
												   ,@in_vchParentLPN			= @in_vchParentLPN
												   ,@in_vchLPN					= @in_vchLPN
												   ,@in_vchOverrideLPN			= @in_vchOverLPN
												   ,@in_vchWhItemMasterID		= @in_vchOverWhItemMasterID
												   ,@in_vchLotNumber			= @in_vchLotNumber
												   ,@in_vchOverrideLotNumber	= @in_vchOverLotNumber
												   ,@in_vchExpiryDate			= @in_vchExpiryDate
												   ,@in_vchOverrideExpiryDate	= @in_vchOverExpiryDate
												   ,@in_vchOverrideAttribute1	= @in_vchOverAttribute1
												   ,@in_vchOverrideAttribute2	= @in_vchOverAttribute2
												   ,@in_vchOverrideAttribute3	= @in_vchOverAttribute3
												   ,@in_vchOverrideAttribute4	= @in_vchOverAttribute4
												   ,@in_vchOverrideAttribute5	= @in_vchOverAttribute5
												   ,@in_vchOverrideSerialNumber	= @in_vchOverSerialNumber
												   ,@in_fltQty					= @in_fltOverQuantity	
												   ,@in_vchUOMPrompt			= @in_vchOverUOMPrompt 
												   ,@out_ErrorCode				= @out_vchErrorCode OUTPUT		
												   ,@out_ErrorMessage			= @out_vchErrorMsg	OUTPUT
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END			
		GOTO CHECK_DISPLAY_FINAL;
	END
	
	CHECK_DISPLAY_FINAL:
		IF @in_vchControlName IN ('SERIAL_NUMBER','OVERRIDE_SERIAL_NUMBER')
			BEGIN
				GOTO FINAL_SCREEN;
			END

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_picking_final_screen @in_vchApplicationID		= @in_vchApplicationID	
 												  ,@in_vchControlName		= @in_vchControlName		
												  ,@in_vchWhMasterID		= @in_vchWhMasterID		
												  ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	
												  ,@in_vchLocationID		= @in_vchLocationID		
												  ,@in_vchParentLPN			= @in_vchParentLPN		
												  ,@in_vchLPN				= @in_vchLPN				
												  ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	
												  ,@in_vchItemMasterID		= @in_vchItemMasterID		
												  ,@in_vchLotNumber			= @in_vchLotNumber		
												  ,@in_vchExpDate			= @in_vchExpiryDate
												  ,@in_vchSerialNumber		= @in_vchSerialNumber		
												  ,@in_vchLocalID			= @in_vchLocalID			
												  ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT	
												  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT	
												  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
END	
GO
