												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2Control  	= @in_vchAttribute2Control 
												   ,@in_vchAttribute3Control  	= @in_vchAttribute3Control 
												   ,@in_vchAttribute4Control  	= @in_vchAttribute4Control 
												   ,@in_vchAttribute5Control  	= @in_vchAttribute5Control 
												   ,@in_vchSerialControl	  	= @in_vchSNControl	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_unpick_attribute2 @in_vchApplicationID	    = @in_vchApplicationID	 
												   ,@in_vchLocalID			 	= @in_vchLocalID			 
												   ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
												   ,@in_vchOutboundMasterID	  	= @in_vchOutboundMasterID	 
												   ,@in_vchOwnerID			  	= @in_vchOwnerID			 
												   ,@in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2			= @in_vchAttribute2 
												   ,@in_vchAttribute3Control  	= @in_vchAttribute3Control 
												   ,@in_vchAttribute4Control  	= @in_vchAttribute4Control 
												   ,@in_vchAttribute5Control  	= @in_vchAttribute5Control 
												   ,@in_vchSerialControl	  	= @in_vchSNControl	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_unpick_attribute3 @in_vchApplicationID	    = @in_vchApplicationID	 
												   ,@in_vchLocalID			 	= @in_vchLocalID			 
												   ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
												   ,@in_vchOutboundMasterID	  	= @in_vchOutboundMasterID	 
												   ,@in_vchOwnerID			  	= @in_vchOwnerID			 
												   ,@in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2			= @in_vchAttribute2 
												   ,@in_vchAttribute3  			= @in_vchAttribute3 
												   ,@in_vchAttribute4Control  	= @in_vchAttribute4Control 
												   ,@in_vchAttribute5Control  	= @in_vchAttribute5Control 
												   ,@in_vchSerialControl	  	= @in_vchSNControl	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_unpick_attribute4 @in_vchApplicationID	    = @in_vchApplicationID	 
												   ,@in_vchLocalID			 	= @in_vchLocalID			 
												   ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
												   ,@in_vchOutboundMasterID	  	= @in_vchOutboundMasterID	 
												   ,@in_vchOwnerID			  	= @in_vchOwnerID			 
												   ,@in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2			= @in_vchAttribute2 
												   ,@in_vchAttribute3  			= @in_vchAttribute3 
												   ,@in_vchAttribute4		  	= @in_vchAttribute4 
												   ,@in_vchAttribute5Control  	= @in_vchAttribute5Control 
												   ,@in_vchSerialControl	  	= @in_vchSNControl	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_unpick_attribute5 @in_vchApplicationID	    = @in_vchApplicationID	 
												   ,@in_vchLocalID			 	= @in_vchLocalID			 
												   ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
												   ,@in_vchOutboundMasterID	  	= @in_vchOutboundMasterID	 
												   ,@in_vchOwnerID			  	= @in_vchOwnerID			 
												   ,@in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2			= @in_vchAttribute2 
												   ,@in_vchAttribute3  			= @in_vchAttribute3 
												   ,@in_vchAttribute4		  	= @in_vchAttribute4 
												   ,@in_vchAttribute5			= @in_vchAttribute5 
												   ,@in_vchSerialControl	  	= @in_vchSNControl	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			RETURN;
		END  
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			EXEC usp_api_validate_unpick_serial_number @in_vchApplicationID	    = @in_vchApplicationID	 
												   ,@in_vchLocalID			 	= @in_vchLocalID			 
												   ,@in_vchWhMasterID		 	= @in_vchWhMasterID		 
												   ,@in_vchOutboundMasterID	  	= @in_vchOutboundMasterID	 
												   ,@in_vchOwnerID			  	= @in_vchOwnerID			 
												   ,@in_vchOutboundPickMasterID	= @in_vchOutboundPickMasterID
												   ,@in_vchSTGLocationID	  	= @in_vchStgLocationID	 
												   ,@in_vchSTGParentLPN		  	= @in_vchStgParentLPN		 
												   ,@in_vchStagingLPN		  	= @in_vchStgLPN		 
												   ,@in_vchWhItemMasterID	  	= @in_vchWhItemMasterID	 
												   ,@in_vchLotNumber		  	= @in_vchLotNumber		 
												   ,@in_vchExpDate			  	= @in_vchExpiryDate			 
												   ,@in_vchAttribute1		  	= @in_vchAttribute1		 
												   ,@in_vchAttribute2			= @in_vchAttribute2 
												   ,@in_vchAttribute3  			= @in_vchAttribute3 
												   ,@in_vchAttribute4		  	= @in_vchAttribute4 
												   ,@in_vchAttribute5			= @in_vchAttribute5 
												   ,@in_vchSerialNumber	  		= @in_vchSerialNumber	 
												   ,@out_vchErrorCode		    = @out_vchErrorCode OUTPUT
												   ,@out_vchErrorMsg		    = @out_vchErrorMsg OUTPUT
												   ,@out_vchNextScreen		    = @out_vchNextScreen OUTPUT	
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN
			GOTO FINAL_SCREEN;
		END
	
	 
	SAVE_TRANS:
		DECLARE @v_vchUOM	NVARCHAR(20) = 1
		SELECT @v_vchUOM = uom FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUOMPrompt AND is_active = 'YES'
		EXEC usp_outbound_unpick @in_vchApplicationID		= @in_vchApplicationID		
								,@in_vchWarehouse			= @in_vchWhID			
								,@in_vchDeviceID			= @in_vchDeviceID					
								,@in_vchUserID				= @in_vchUserID				
								,@in_vchOutboundOrderNumber	= @in_vchOutboundOrderNumber	
								,@in_vchOwner				= @in_vchOwnerCode
								,@in_vchStgLocation			= @in_vchStgLocation			
								,@in_vchStgParentLPN		= @in_vchStgParentLPN					
								,@in_vchStgLPN				= @in_vchStgLPN
								,@in_vchItemNumber			= @in_vchItemNumber			
								,@in_vchLotNumber			= @in_vchLotNumber			
								,@in_vchExpiryDate			= @in_vchExpiryDate			
								,@in_vchSerialNumber		= @in_vchSerialNumber				
								,@in_vchAttribute1			= @in_vchAttribute1			
								,@in_vchAttribute2			= @in_vchAttribute2			
								,@in_vchAttribute3			= @in_vchAttribute3			
								,@in_vchAttribute4			= @in_vchAttribute4			
								,@in_vchAttribute5			= @in_vchAttribute5			
								,@in_fltQuantity			= @in_fltQuantity					
								,@in_vchUOM					= @v_vchUOM					
								,@out_ErrorCode				= @out_vchErrorCode OUTPUT		
								,@out_ErrorMessage			= @out_vchErrorMsg	OUTPUT								
								
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		IF @in_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;	
	  
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_unpick_final_screen  @in_vchApplicationID		   = @in_vchApplicationID	 	
 												  ,@in_vchLocalID			   = @in_vchLocalID			 
												  ,@in_vchControlName		   = @in_vchControlName		 
												  ,@in_vchWhMasterID		   = @in_vchWhMasterID		 
												  ,@in_vchOutboundMasterID	   = @in_vchOutboundMasterID	 
												  ,@in_vchOwnerID			   = @in_vchOwnerID			 
												  ,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID
												  ,@in_vchSTGLocationID	 	   = @in_vchStgLocationID	 
												  ,@in_vchSTGParentLPN		   = @in_vchStgParentLPN		 
												  ,@in_vchStagingLPN		   = @in_vchStgLPN		 
												  ,@in_vchWhItemMasterID	   = @in_vchWhItemMasterID	 
												  ,@out_vchErrorCode		   = @out_vchErrorCode OUTPUT	 
												  ,@out_vchErrorMsg		 	   = @out_vchErrorMsg OUTPUT
												  ,@out_vchNextScreen		   = @out_vchNextScreen	OUTPUT
END	
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_user_pick_load]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_user_pick_load]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),	
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchForkID				UNIQUEIDENTIFIER,
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),  
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchItemStatus			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT,
	@in_vchLotControl			VARCHAR(5) = NULL,	
	@in_vchExpDateControl		VARCHAR(5) = NULL,	
	@in_vchSNControl			VARCHAR(5) = NULL,
	@in_vchAttribute1Control	VARCHAR(5) = NULL,
	@in_vchAttribute2Control	VARCHAR(5) = NULL,
	@in_vchAttribute3Control	VARCHAR(5) = NULL,
	@in_vchAttribute4Control	VARCHAR(5) = NULL,
	@in_vchAttribute5Control	VARCHAR(5) = NULL, 
	@in_vchStgLocation			NVARCHAR(50) = NULL,	
	@in_vchPickRule				NVARCHAR(50) = '',
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'LOAD_ID'
		BEGIN
			EXEC usp_api_validate_user_pick_load_load_id @in_vchApplicationID	= @in_vchApplicationID
														,@in_vchWhMasterID		= @in_vchWhMasterID
														,@in_vchLoadID			= @in_vchLoadID
														,@in_vchLocalID			= @in_vchLocalID
														,@in_vchUserID			= @in_vchUserID
														,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_load_box_number @in_vchApplicationID = @in_vchApplicationID
														   ,@in_vchWhMasterID	= @in_vchWhMasterID
														   ,@in_vchLoadID		= @in_vchLoadID
														   ,@in_vchBoxNumber	= @in_vchBoxNumber
														   ,@in_vchFork			= @in_vchForkLocation
														   ,@in_vchLocalID		= @in_vchLocalID
														   ,@out_vchErrorCode	= @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg	= @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_user_pick_load_location @in_vchApplicationID	= @in_vchApplicationID	 
														 ,@in_vchWhMasterID		= @in_vchWhMasterID		 
														 ,@in_vchLoadID			= @in_vchLoadID	 
														 ,@in_vchOwnerID		= @in_vchOwnerID			 
														 ,@in_vchLocation		= @in_vchLocation			 
														 ,@in_vchLocalID		= @in_vchLocalID			 
														 ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT		 
														 ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														 ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT		 
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			EXEC usp_api_validate_user_pick_load_parent_lpn @in_vchApplicationID	= @in_vchApplicationID	
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		
														   ,@in_vchLoadID			= @in_vchLoadID 
														   ,@in_vchOwnerID			= @in_vchOwnerID			  
														   ,@in_vchLocationID		= @in_vchLocationID		
														   ,@in_vchParentLPN		= @in_vchParentLPN		
														   ,@in_vchLocalID			= @in_vchLocalID			
														   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN 
			EXEC usp_api_validate_user_pick_load_lpn @in_vchApplicationID	= @in_vchApplicationID	
												    ,@in_vchWhMasterID		= @in_vchWhMasterID		
												    ,@in_vchLoadID			= @in_vchLoadID	
												    ,@in_vchOwnerID			= @in_vchOwnerID			
												    ,@in_vchLocationID		= @in_vchLocationID		
												    ,@in_vchLocation		= @in_vchLocation			
												    ,@in_vchParentLPN		= @in_vchParentLPN		
												    ,@in_vchLPN				= @in_vchLPN				
												    ,@in_vchLocalID			= @in_vchLocalID			
												    ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
												    ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
												    ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_load_item_number @in_vchApplicationID	= @in_vchApplicationID
															,@in_vchWhMasterID		= @in_vchWhMasterID
															,@in_vchWarehouse		= @in_vchWhID
															,@in_vchLoadID			= @in_vchLoadID
															,@in_vchOwnerID			= @in_vchOwnerID
															,@in_vchLocationID		= @in_vchLocationID
															,@in_vchParentLPN		= @in_vchParentLPN
															,@in_vchLPN				= @in_vchLPN
															,@in_vchItemNumber		= @in_vchItemNumber
															,@in_vchLocalID			= @in_vchLocalID
															,@out_vchInvStatus		= @in_vchItemStatus OUTPUT
															,@out_vchItemMasterID   = @in_vchItemMasterID OUTPUT
															,@out_vchWhItemMasterID = @in_vchWhItemMasterID OUTPUT
															,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
															,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
															,@out_vchNextScreen	   	= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_user_pick_load_item_status @in_vchApplicationID	= @in_vchApplicationID	 
													        ,@in_vchWhMasterID		= @in_vchWhMasterID
															,@in_vchWarehouse		= @in_vchWhID  
													        ,@in_vchLoadID			= @in_vchLoadID 		  
													        ,@in_vchOwnerID			= @in_vchOwnerID			  
													        ,@in_vchLocationID		= @in_vchLocationID		  
													        ,@in_vchParentLPN		= @in_vchParentLPN		  
													        ,@in_vchLPN				= @in_vchLPN				 
													        ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	  
													        ,@in_vchItemStatus		= @in_vchItemStatus
													        ,@in_vchLotControl		= @in_vchLotControl
													        ,@in_vchSNControl		= @in_vchSNControl
													        ,@in_vchExpiryDateControl = @in_vchExpDateControl
													        ,@in_vchAttribute1Control = @in_vchAttribute1Control
													        ,@in_vchAttribute2Control = @in_vchAttribute2Control
													        ,@in_vchAttribute3Control = @in_vchAttribute3Control
													        ,@in_vchAttribute4Control = @in_vchAttribute4Control
													        ,@in_vchAttribute5Control = @in_vchAttribute5Control
													        ,@in_vchLocalID			= @in_vchLocalID
													        ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT	 
													        ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT  
													        ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT								    
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'LOT_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_load_lot_number @in_vchApplicationID	= @in_vchApplicationID	 
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		 
														   ,@in_vchWarehouse		= @in_vchWhID	 
														   ,@in_vchLoadID			= @in_vchLoadID	  
														   ,@in_vchOwnerID			= @in_vchOwnerID			 
														   ,@in_vchLocationID		= @in_vchLocationID		 
														   ,@in_vchParentLPN		= @in_vchParentLPN		 
														   ,@in_vchLPN				= @in_vchLPN				 
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	 
														   ,@in_vchItemStatus		= @in_vchItemStatus		 
														   ,@in_vchPickRule			= @in_vchPickRule			 
														   ,@in_vchLotNumber		= @in_vchLotNumber		 
														   ,@in_vchSNControl		= @in_vchSNControl		 
														   ,@in_vchExpiryDateControl= @in_vchExpDateControl 
														   ,@in_vchAttribute1Control= @in_vchAttribute1Control 
														   ,@in_vchAttribute2Control= @in_vchAttribute2Control 
														   ,@in_vchAttribute3Control= @in_vchAttribute3Control 
														   ,@in_vchAttribute4Control= @in_vchAttribute4Control 
														   ,@in_vchAttribute5Control= @in_vchAttribute5Control 
														   ,@in_vchLocalID			= @in_vchLocalID			 
														   ,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT	 
														   ,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT	 
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'EXPIRY_DATE'
		BEGIN
			EXEC usp_api_validate_user_pick_load_expiry_date @in_vchApplicationID	= @in_vchApplicationID	 
															,@in_vchWhMasterID		= @in_vchWhMasterID
															,@in_vchWarehouse		= @in_vchWhID
															,@in_vchLoadID			= @in_vchLoadID
															,@in_vchOwnerID			= @in_vchOwnerID			 
															,@in_vchLocationID		= @in_vchLocationID		 
															,@in_vchParentLPN		= @in_vchParentLPN		 
															,@in_vchLPN				= @in_vchLPN				 
															,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	 
															,@in_vchItemStatus		= @in_vchItemStatus		 
															,@in_vchPickRule		= @in_vchPickRule			 
															,@in_vchLotNumber		= @in_vchLotNumber		 
															,@in_vchExpDate			= @in_vchExpiryDate			 
															,@in_vchSNControl		= @in_vchSNControl		 
															,@in_vchAttribute1Control = @in_vchAttribute1Control 
															,@in_vchAttribute2Control = @in_vchAttribute2Control 
															,@in_vchAttribute3Control = @in_vchAttribute3Control 
															,@in_vchAttribute4Control = @in_vchAttribute4Control 
															,@in_vchAttribute5Control = @in_vchAttribute5Control 
															,@in_vchLocalID			= @in_vchLocalID			 
															,@out_vchErrorCode		= @out_vchErrorCode  OUTPUT 
															,@out_vchErrorMsg		= @out_vchErrorMsg	  OUTPUT
															,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE1'
		BEGIN
			EXEC usp_api_validate_user_pick_load_attribute1 @in_vchApplicationID	= @in_vchApplicationID	    
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		  
														   ,@in_vchWarehouse		= @in_vchWhID
														   ,@in_vchLoadID			= @in_vchLoadID	
														   ,@in_vchOwnerID			= @in_vchOwnerID			
														   ,@in_vchLocationID		= @in_vchLocationID		  
														   ,@in_vchParentLPN		= @in_vchParentLPN		 
														   ,@in_vchLPN				= @in_vchLPN				
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	   
														   ,@in_vchItemStatus		= @in_vchItemStatus		  
														   ,@in_vchPickRule			= @in_vchPickRule			
														   ,@in_vchLotNumber		= @in_vchLotNumber		 
														   ,@in_vchExpDate			= @in_vchExpiryDate			
														   ,@in_vchAttribute1		= @in_vchAttribute1		  
														   ,@in_vchSNControl		= @in_vchSNControl		 
														   ,@in_vchAttribute2Control = @in_vchAttribute2Control 
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control 
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control 
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control  
														   ,@in_vchLocalID			= @in_vchLocalID			
														   ,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT	
														   ,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT	
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE2'
		BEGIN
			EXEC usp_api_validate_user_pick_load_attribute2 @in_vchApplicationID	= @in_vchApplicationID
														   ,@in_vchWhMasterID		= @in_vchWhMasterID
														   ,@in_vchWarehouse		= @in_vchWhID
														   ,@in_vchLoadID			= @in_vchLoadID
														   ,@in_vchOwnerID			= @in_vchOwnerID
														   ,@in_vchLocationID		= @in_vchLocationID
														   ,@in_vchParentLPN		= @in_vchParentLPN
														   ,@in_vchLPN				= @in_vchLPN
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID
														   ,@in_vchItemStatus		= @in_vchItemStatus
														   ,@in_vchPickRule			= @in_vchPickRule
														   ,@in_vchLotNumber		= @in_vchLotNumber
														   ,@in_vchExpDate			= @in_vchExpiryDate
														   ,@in_vchAttribute1		= @in_vchAttribute1
														   ,@in_vchAttribute2		= @in_vchAttribute2
														   ,@in_vchSNControl		= @in_vchSNControl
														   ,@in_vchAttribute3Control = @in_vchAttribute3Control
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@in_vchLocalID			= @in_vchLocalID
														   ,@out_vchErrorCode		= @out_vchErrorCode	 OUTPUT
														   ,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE3'
		BEGIN
			EXEC usp_api_validate_user_pick_load_attribute3 @in_vchApplicationID	= @in_vchApplicationID
														   ,@in_vchWhMasterID		= @in_vchWhMasterID
														   ,@in_vchWarehouse		= @in_vchWhID
														   ,@in_vchLoadID			= @in_vchLoadID
														   ,@in_vchOwnerID			= @in_vchOwnerID
														   ,@in_vchLocationID		= @in_vchLocationID
														   ,@in_vchParentLPN		= @in_vchParentLPN
														   ,@in_vchLPN				= @in_vchLPN
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID
														   ,@in_vchItemStatus		= @in_vchItemStatus
														   ,@in_vchPickRule			= @in_vchPickRule
														   ,@in_vchLotNumber		= @in_vchLotNumber
														   ,@in_vchExpDate			= @in_vchExpiryDate
														   ,@in_vchAttribute1		= @in_vchAttribute1
														   ,@in_vchAttribute2		= @in_vchAttribute2
														   ,@in_vchAttribute3		= @in_vchAttribute3
														   ,@in_vchSNControl		= @in_vchSNControl
														   ,@in_vchAttribute4Control = @in_vchAttribute4Control
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control
														   ,@in_vchLocalID			= @in_vchLocalID
														   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE4'
		BEGIN
			EXEC usp_api_validate_user_pick_load_attribute4 @in_vchApplicationID	= @in_vchApplicationID
														   ,@in_vchWhMasterID		= @in_vchWhMasterID
														   ,@in_vchWarehouse		= @in_vchWhID
														   ,@in_vchLoadID			= @in_vchLoadID
														   ,@in_vchOwnerID			= @in_vchOwnerID
														   ,@in_vchLocationID		= @in_vchLocationID
														   ,@in_vchParentLPN		= @in_vchParentLPN
														   ,@in_vchLPN				= @in_vchLPN
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID
														   ,@in_vchItemStatus		= @in_vchItemStatus
														   ,@in_vchPickRule			= @in_vchPickRule
														   ,@in_vchLotNumber		= @in_vchLotNumber
														   ,@in_vchExpDate			= @in_vchExpiryDate
														   ,@in_vchAttribute1		= @in_vchAttribute1
														   ,@in_vchAttribute2		= @in_vchAttribute2
														   ,@in_vchAttribute3		= @in_vchAttribute3
														   ,@in_vchAttribute4		= @in_vchAttribute4
														   ,@in_vchSNControl		= @in_vchSNControl
														   ,@in_vchAttribute5Control = @in_vchAttribute5Control	
														   ,@in_vchLocalID			= @in_vchLocalID
														   ,@out_vchErrorCode		= @out_vchErrorCode  OUTPUT		
														   ,@out_vchErrorMsg		= @out_vchErrorMsg	 OUTPUT		
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT		
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ATTRIBUTE5'
		BEGIN
			EXEC usp_api_validate_user_pick_load_attribute5 @in_vchApplicationID	= @in_vchApplicationID	 
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		 
														   ,@in_vchWarehouse		= @in_vchWhID		 
														   ,@in_vchLoadID			= @in_vchLoadID	 	  
														   ,@in_vchOwnerID			= @in_vchOwnerID			 
														   ,@in_vchLocationID		= @in_vchLocationID		 
														   ,@in_vchParentLPN		= @in_vchParentLPN		 
														   ,@in_vchLPN				= @in_vchLPN				 
														   ,@in_vchWhItemMasterID	= @in_vchWhItemMasterID	 
														   ,@in_vchItemStatus		= @in_vchItemStatus		 
														   ,@in_vchPickRule			= @in_vchPickRule			 
														   ,@in_vchLotNumber		= @in_vchLotNumber		 
														   ,@in_vchExpDate			= @in_vchExpiryDate
														   ,@in_vchAttribute1		= @in_vchAttribute1
														   ,@in_vchAttribute2		= @in_vchAttribute2
														   ,@in_vchAttribute3		= @in_vchAttribute3
														   ,@in_vchAttribute4		= @in_vchAttribute4
														   ,@in_vchAttribute5		= @in_vchAttribute5
														   ,@in_vchSNControl		= @in_vchSNControl
														   ,@in_vchLocalID			= @in_vchLocalID
														   ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT	 
														   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT	 
														   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	 
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'STAGING_LOCATION'
		BEGIN
			EXEC usp_outbound_update_pickto_staging_by_load @in_vchApplicationID	= @in_vchApplicationID	
														   ,@in_vchDeviceID			= @in_vchDeviceID			
														   ,@in_vchUserID			= @in_vchUserID			
														   ,@in_vchWhMasterID		= @in_vchWhMasterID		
														   ,@in_vchLoadID			= @in_vchLoadID			
														   ,@in_vchForklift			= @in_vchForkLocation
														   ,@in_vchStagingLocation	= @in_vchStgLocation	
														   ,@out_ErrorCode			= @out_vchErrorCode OUTPUT			
														   ,@out_ErrorMessage		= @out_vchErrorMsg OUTPUT	

			IF ISNULL(@out_vchErrorCode,'') = '0'
				BEGIN
					SET @out_vchNextScreen = 'LOAD_ID'
				END 
			RETURN; 
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			SET @in_fltQuantity = 1;
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'UOM_QTY'
		BEGIN
			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		DECLARE @v_vchToLPN NVARCHAR(25) = NULL
		DECLARE @v_vchItemUOMID UNIQUEIDENTIFIER = NULL 

		IF ISNULL(@in_vchContainerNo,'') = '' 
			SET @v_vchToLPN = @in_vchBoxNumber
		ELSE
			SET @v_vchToLPN = @in_vchContainerNo
		
		--GET UOM ID
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id
					,@in_vchUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1;

				--Select qty back to display on PDA screen 
				SELECT @in_fltQuantity AS qty
			END
		ELSE
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUomPrompt AND is_active = 'YES'
			END
			 
		EXEC usp_outbound_generate_user_pick_by_load  @in_vchApplicationID    = @in_vchApplicationID		
													 ,@in_vchLocalID		  = @in_vchLocalID			
													 ,@in_vchDeviceID		  = @in_vchDeviceID			
													 ,@in_vchUserID			  = @in_vchUserID			
													 ,@in_vchForkLocationID	  = @in_vchForkID	
													 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
													 ,@in_vchLoadID			  = @in_vchLoadID	
													 ,@in_vchOwnerID		  = @in_vchOwnerID			
													 ,@in_vchBoxNumber		  = @in_vchBoxNumber		
													 ,@in_vchLocationID		  = @in_vchLocationID		
													 ,@in_vchParentLPN		  = @in_vchParentLPN		
													 ,@in_vchLPN			  = @in_vchLPN				
													 ,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	
													 ,@in_vchItemStatus		  = @in_vchItemStatus		
													 ,@in_fltQuantity		  = @in_fltQuantity			
													 ,@in_vchItemUOMID		  = @v_vchItemUOMID		
													 ,@in_vchLotNumber		  = @in_vchLotNumber		
													 ,@in_vchExpiryDate		  = @in_vchExpiryDate		
													 ,@in_vchSerialNumber	  = @in_vchSerialNumber		
													 ,@in_vchAttribute1		  = @in_vchAttribute1		
													 ,@in_vchAttribute2		  = @in_vchAttribute2		
													 ,@in_vchAttribute3		  = @in_vchAttribute3		
													 ,@in_vchAttribute4		  = @in_vchAttribute4		
													 ,@in_vchAttribute5		  = @in_vchAttribute5		
													 ,@out_ErrorCode		  = @out_vchErrorCode output	
													 ,@out_ErrorMessage		  = @out_vchErrorMsg output	

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		IF @in_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_user_pick_load_final_screen @in_vchApplicationID	 = @in_vchApplicationID
														 ,@in_vchDeviceID		 = @in_vchDeviceID
														 ,@in_vchUserID			 = @in_vchUserID
														 ,@in_vchWhMasterID		 = @in_vchWhMasterID
														 ,@in_vchLoadID			 = @in_vchLoadID
														 ,@in_vchLocationID		 = @in_vchLocationID
														 ,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID
														 ,@in_vchLocalID		 = @in_vchLocalID
														 ,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
														 ,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
														 ,@out_vchNextScreen	 = @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_next_validate_user_pick_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_next_validate_user_pick_order]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),	
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchForkID				UNIQUEIDENTIFIER,
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),  
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchItemStatus			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT,
	@in_vchLotControl			VARCHAR(5) = NULL,	
	@in_vchExpDateControl		VARCHAR(5) = NULL,	
	@in_vchSNControl			VARCHAR(5) = NULL,
	@in_vchAttribute1Control	VARCHAR(5) = NULL,
	@in_vchAttribute2Control	VARCHAR(5) = NULL,
	@in_vchAttribute3Control	VARCHAR(5) = NULL,
	@in_vchAttribute4Control	VARCHAR(5) = NULL,
	@in_vchAttribute5Control	VARCHAR(5) = NULL, 
	@in_vchStgLocation			NVARCHAR(50) = NULL,	
	@in_vchPickRule				NVARCHAR(50) = '',
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	IF @in_vchControlName = 'ORDER_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_order_number @in_vchApplicationID	= @in_vchApplicationID
														,@in_vchWhMasterID		= @in_vchWhMasterID
														,@in_vchOrderNumber		= @in_vchOutboundOrderNumber
														,@in_vchLocalID			= @in_vchLocalID
														,@in_vchUserID			= @in_vchUserID
														,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
														,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'BOX_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_box_number @in_vchApplicationID = @in_vchApplicationID
													  ,@in_vchWhMasterID	= @in_vchWhMasterID
													  ,@in_vchOrderNumber	= @in_vchOutboundOrderNumber
													  ,@in_vchBoxNumber		= @in_vchBoxNumber
													  ,@in_vchFork			= @in_vchForkLocation
													  ,@in_vchLocalID		= @in_vchLocalID
													  ,@out_vchErrorCode	= @out_vchErrorCode OUTPUT
													  ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
													  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
			RETURN;
		END
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			EXEC usp_api_validate_user_pick_location @in_vchApplicationID	 = @in_vchApplicationID	 
													,@in_vchWhMasterID		 = @in_vchWhMasterID		 
													,@in_vchOutboundMasterID = @in_vchOutboundMasterID	 
													,@in_vchOwnerID			 = @in_vchOwnerID			 
													,@in_vchLocation		 = @in_vchLocation			 
													,@in_vchLocalID			 = @in_vchLocalID			 
													,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT		 
													,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT		 
			RETURN;
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			EXEC usp_api_validate_user_pick_parent_lpn @in_vchApplicationID		= @in_vchApplicationID	
													  ,@in_vchWhMasterID		= @in_vchWhMasterID		
													  ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID 
													  ,@in_vchOwnerID			= @in_vchOwnerID			  
													  ,@in_vchLocationID		= @in_vchLocationID		
													  ,@in_vchParentLPN			= @in_vchParentLPN		
													  ,@in_vchLocalID			= @in_vchLocalID			
													  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
													  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
													  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT	
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN 
			EXEC usp_api_validate_user_pick_lpn @in_vchApplicationID	= @in_vchApplicationID	
											   ,@in_vchWhMasterID		= @in_vchWhMasterID		
											   ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	
											   ,@in_vchOwnerID			= @in_vchOwnerID			
											   ,@in_vchLocationID		= @in_vchLocationID		
											   ,@in_vchLocation			= @in_vchLocation			
											   ,@in_vchParentLPN		= @in_vchParentLPN		
											   ,@in_vchLPN				= @in_vchLPN				
											   ,@in_vchLocalID			= @in_vchLocalID			
											   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
											   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
											   ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
			RETURN;
		END 
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			EXEC usp_api_validate_user_pick_item_number @in_vchApplicationID	= @in_vchApplicationID
													   ,@in_vchWhMasterID		= @in_vchWhMasterID
													   ,@in_vchWarehouse		= @in_vchWhID
													   ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID
													   ,@in_vchOwnerID			= @in_vchOwnerID
													   ,@in_vchLocationID		= @in_vchLocationID
													   ,@in_vchParentLPN		= @in_vchParentLPN
													   ,@in_vchLPN				= @in_vchLPN
													   ,@in_vchItemNumber		= @in_vchItemNumber
													   ,@in_vchLocalID			= @in_vchLocalID
													   ,@out_vchInvStatus		= @in_vchItemStatus OUTPUT
													   ,@out_vchItemMasterID	= @in_vchItemMasterID OUTPUT
													   ,@out_vchWhItemMasterID	= @in_vchWhItemMasterID OUTPUT
													   ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT
													   ,@out_vchErrorMsg		= @out_vchErrorMsg OUTPUT
													   ,@out_vchNextScreen	   	= @out_vchNextScreen OUTPUT
			IF @out_vchNextScreen = 'FINAL_SCREEN'
				GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'ITEM_STATUS'
		BEGIN
			EXEC usp_api_validate_user_pick_item_status @in_vchApplicationID	 = @in_vchApplicationID	 
													   ,@in_vchWhMasterID		 = @in_vchWhMasterID		  
													   ,@in_vchOutboundMasterID	 = @in_vchOutboundMasterID	 		  
