			GOTO SAVE_TRANS;
			RETURN;
		END
	IF @in_vchControlName = 'FINAL_SCREEN'
		BEGIN 
			GOTO FINAL_SCREEN;
		END

	SAVE_TRANS:
		DECLARE @v_vchToLPN NVARCHAR(25) = NULL
		DECLARE @v_vchItemUOMID UNIQUEIDENTIFIER = NULL 

		IF ISNULL(@in_vchContainerNo,'') = '' 
			SET @v_vchToLPN = @in_vchBoxNumber
		ELSE
			SET @v_vchToLPN = @in_vchContainerNo
		
		--GET UOM ID
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id
					,@in_vchUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @in_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @in_fltQuantity = 1;

				--Select qty back to display on PDA screen 
				SELECT @in_fltQuantity AS qty
			END
		ELSE
			BEGIN
				SELECT TOP 1 @v_vchItemUOMID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUomPrompt AND is_active = 'YES'
			END
			 
		EXEC usp_outbound_generate_user_pick_by_order @in_vchApplicationID    = @in_vchApplicationID		
													 ,@in_vchLocalID		  = @in_vchLocalID			
													 ,@in_vchDeviceID		  = @in_vchDeviceID			
													 ,@in_vchUserID			  = @in_vchUserID			
													 ,@in_vchForkLocationID	  = @in_vchForkID	
													 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
													 ,@in_vchOutboundMasterID = @in_vchOutboundMasterID	
													 ,@in_vchOwnerID		  = @in_vchOwnerID			
													 ,@in_vchBoxNumber		  = @in_vchBoxNumber		
													 ,@in_vchLocationID		  = @in_vchLocationID		
													 ,@in_vchParentLPN		  = @in_vchParentLPN		
													 ,@in_vchLPN			  = @in_vchLPN				
													 ,@in_vchWhItemMasterID	  = @in_vchWhItemMasterID	
													 ,@in_vchItemStatus		  = @in_vchItemStatus		
													 ,@in_fltQuantity		  = @in_fltQuantity			
													 ,@in_vchItemUOMID		  = @v_vchItemUOMID		
													 ,@in_vchLotNumber		  = @in_vchLotNumber		
													 ,@in_vchExpiryDate		  = @in_vchExpiryDate		
													 ,@in_vchSerialNumber	  = @in_vchSerialNumber		
													 ,@in_vchAttribute1		  = @in_vchAttribute1		
													 ,@in_vchAttribute2		  = @in_vchAttribute2		
													 ,@in_vchAttribute3		  = @in_vchAttribute3		
													 ,@in_vchAttribute4		  = @in_vchAttribute4		
													 ,@in_vchAttribute5		  = @in_vchAttribute5		
													 ,@out_ErrorCode		  = @out_vchErrorCode output	
													 ,@out_ErrorMessage		  = @out_vchErrorMsg output	

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
					
		IF @in_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;
							
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_user_pick_final_screen @in_vchApplicationID	 = @in_vchApplicationID
													,@in_vchDeviceID		 = @in_vchDeviceID
													,@in_vchUserID			 = @in_vchUserID
													,@in_vchWhMasterID		 = @in_vchWhMasterID
													,@in_vchOutboundMasterID = @in_vchOutboundMasterID
													,@in_vchLocationID		 = @in_vchLocationID
													,@in_vchWhItemMasterID	 = @in_vchWhItemMasterID
													,@in_vchSNControl		 = @in_vchSNControl
													,@in_vchLocalID			 = @in_vchLocalID
													,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
													,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_blind_pick_confirm_ship]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_blind_pick_confirm_ship]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundOrderNumber		VARCHAR(50), 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOrderStatus  NVARCHAR(10)
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @in_vchOutboundOrderNumber
	AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF @v_vchOrderStatus = 'SHIP'
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_IS_SHIP'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
		
	EXEC usp_outbound_ship_confirm @in_vchApplicationID		= @in_vchApplicationID
									, @in_vchWhMasterID		= @in_vchWhMasterID
									, @in_vchDeviceID		= @in_vchDeviceID
									, @in_vchUserID			= @in_vchUserID
									, @in_vchOutboundMasterID = @v_vchOutboundMasterID
									, @in_vchCarrierID		= NULL
									, @in_vchTruckType		= NULL
									, @in_vchTruckNumber	= NULL
									, @in_vchDriverLicense	= NULL
									, @in_vchContainerNo	= NULL
									, @in_vchSealNumber		= NULL
									, @in_vchPostingDate	= NULL
									, @in_dtShipDateActual  = NULL
									, @out_ErrorCode	    = @out_vchErrorCode	OUTPUT
									, @out_ErrorMessage	    = @out_vchErrorMsg OUTPUT


	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'ORDER_NUMBER'
		END

	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50) = NULL
	--Clear ค่าใน Dropdown ของ outbound หลังจากก Confirm Ship แล้ว 
	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
		BEGIN
			PRINT 'NO PICK'
			----------------------------------------------------------
			-- Binding Outbound Order Number
			-- กรณีที่ไม่ให้ช่วยกันหยิบ
			----------------------------------------------------------
			SELECT outbound_order_master_id	 AS value_member
				,outbound_order_number		 AS display_member
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN ('SHIP','CLOSE','CANCEL'))	--(SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID 
			AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
			ORDER BY outbound_order_number
		END
	ELSE
		BEGIN
			----------------------------------------------------------
			-- Binding Outbound Order Number
			----------------------------------------------------------
			SELECT outbound_order_master_id	 AS value_member
				,outbound_order_number		 AS display_member
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN ('SHIP','CLOSE','CANCEL'))	--(SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			ORDER BY outbound_order_number
		END
	SELECT ISNULL(@v_vchOutboundOrderNumber,'') AS outbound_order_number
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_blind_pick_new_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_blind_pick_new_order]
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchWhID			 NVARCHAR(25),
	@in_vchOwnerID		 UNIQUEIDENTIFIER, 
	@in_vchOwnerCode	 NVARCHAR(40),
	@in_vchCustomerID	 UNIQUEIDENTIFIER = NULL,
	@in_vchToWarehouse	 NVARCHAR(25) = NULL,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
AS
BEGIN
	
	DECLARE @v_intRunningID		INT,
			@v_dtpDateNow		Datetime,
			@v_vchYear			VARCHAR(40),
			@v_vchMonth			NVARCHAR(2),
			@v_vchDay			NVARCHAR(2),

			@v_vchPrefix		NVARCHAR(5),
			@v_vchSuffix		NVARCHAR(5),
			@v_vchFormat		NVARCHAR(10),
			@v_intRunning		INT,
			@v_vchRunningID		VARCHAR(40),
			@v_vchOutboundOrderNumber NVARCHAR(50), 
			@v_vchOutboundMasterID UNIQUEIDENTIFIER,
			@v_vchOrderType		NVARCHAR(30)			

	SET @v_dtpDateNow = GETDATE();
	
	-- Add the T-SQL statements to compute the return value here
	SELECT @v_vchYear = DATEPART(YYYY,@v_dtpDateNow)
	SELECT @v_vchMonth = DATEPART(MM,@v_dtpDateNow)
	SELECT @v_vchDay = DATEPART(DD,@v_dtpDateNow)

	SELECT @v_vchPrefix = ISNULL(value,'') FROM t_wms_rule WHERE rule_code = 'PREFIX_OUTBOUND_ORDER_FOR_RUNNING'
	SELECT @v_vchSuffix = ISNULL(value,'') FROM t_wms_rule WHERE rule_code = 'SUFFIX_OUTBOUND_ORDER_FOR_RUNNING'
	SELECT @v_vchFormat = ISNULL(value,'0') FROM t_wms_rule WHERE rule_code = 'FORMAT_OUTBOUND_ORDER_FOR_RUNNING'

	SELECT @v_vchRunningID = running_id
		,@v_intRunning = running 
	FROM t_wms_running_outbound_order 
	WHERE [year] = @v_vchYear 
	AND [month] = @v_vchMonth 
	AND [day] = @v_vchDay

	IF (@v_intRunning is null)
		BEGIN
			SET @v_intRunning = 0;
		END

	SET @v_intRunning = @v_intRunning + 1;
	SET @v_vchOutboundOrderNumber = @v_vchPrefix + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
	IF (@v_vchRunningID IS NULL)
		BEGIN
			SET @v_vchRunningID = NEWID();
			INSERT INTO t_wms_running_outbound_order(year, month, day, running, prefix, sufix)
			VALUES(@v_vchYear,@v_vchMonth,@v_vchDay,@v_intRunning,@v_vchPrefix,@v_vchSuffix)
		END
	ELSE
		BEGIN
			UPDATE t_wms_running_outbound_order set running = @v_intRunning where running_id = @v_vchRunningID
		END
		 
	SET @v_vchOutboundMasterID = NULL
	SELECT @v_vchOutboundMasterID = outbound_order_master_id 
	FROM t_wms_outbound_master
	WHERE wh_master_id = @in_vchWhMasterID
	AND outbound_order_number = @v_vchOutboundOrderNumber
	IF (@v_vchOutboundMasterID IS NULL)
	BEGIN
		DECLARE @v_vchCustomerCode	NVARCHAR(50) = NULL,
				@v_vchCustomerName	NVARCHAR(200) = NULL,
				@v_vchCustomerDesc	NVARCHAR(200) = NULL,
				@v_vchAddrLine1		NVARCHAR(300) = NULL,
				@v_vchAddrLine2		NVARCHAR(300) = NULL,
				@v_vchAddrLine3		NVARCHAR(300) = NULL,
				@v_vchCustCity		NVARCHAR(50) = NULL,
				@v_vchCustProvince	NVARCHAR(50) = NULL,
				@v_vchPostalCode	NVARCHAR(10) = NULL,
				@v_vchCountryCode	NVARCHAR(10) = NULL,
				@v_vchCountryName	NVARCHAR(50) = NULL,
				@v_vchContact		NVARCHAR(200) = NULL,
				@v_vchPhone			NVARCHAR(50) = NULL,
				@v_vchFax			NVARCHAR(50) = NULL,
				@v_vchEmail			NVARCHAR(50) = NULL,
				@v_vchToWarehouseID UNIQUEIDENTIFIER = NULL

		SELECT TOP 1 @v_vchOrderType = value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'
		IF ((@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_INBOUND' AND is_active = 'YES')) AND ISNULL(@in_vchToWarehouse,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'INFO-TO-WAREHOUSE-NOT-FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			RETURN;
		END
			
		IF ISNULL(@in_vchToWarehouse,'') <> ''
			BEGIN
				SELECT TOP 1 @v_vchToWarehouseID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchToWarehouse
			END

		SELECT TOP 1 @v_vchCustomerCode = customer_code
			, @v_vchCustomerName = customer_name
			, @v_vchCustomerDesc = description
			, @v_vchAddrLine1 = addr_line_1
			, @v_vchAddrLine2 = addr_line_2
			, @v_vchAddrLine3 = addr_line_3
			, @v_vchCustCity = city
			, @v_vchCustProvince = province
			, @v_vchPostalCode = postal_code
			, @v_vchCountryCode = country_code
			, @v_vchCountryName = country_name
			, @v_vchPhone = phone
			, @v_vchContact = contact
			, @v_vchFax = fax
			, @v_vchEmail = email
		FROM t_wms_customer
		WHERE owner_id = @in_vchOwnerID
		AND customer_id = @in_vchCustomerID
		AND is_active = 'YES'

		SET @v_vchOutboundMasterID = NEWID()
		INSERT INTO [dbo].[t_wms_outbound_master]
			([outbound_order_master_id]
			,[wh_master_id]
			,[outbound_order_number]
			,[owner_id]
			,[order_type]
			,[order_status]
			,[order_date]
			,[ship_date_plan]
			,[department]
			,[customer_id]
			,[customer_code]
			,[customer_name]
			,[cus_description]
			,[cus_addr_line_1]
			,[cus_addr_line_2]
			,[cus_addr_line_3]
			,[cus_city]
			,[cus_province]
			,[cus_postal_code]
			,[cus_country_code]
			,[cus_country_name]
			,[cus_contact]
			,[cus_phone]
			,[cus_fax]
			,[cus_email]         
			,[create_by]
			,[create_date]
			,[pick_type]
			,[wh_id]
			,[owner_code]
			)
		VALUES
			(@v_vchOutboundMasterID
			,@in_vchWhMasterID
			,@v_vchOutboundOrderNumber
			,@in_vchOwnerID
			,@v_vchOrderType
			,'OPEN'
			,GETDATE()
			,GETDATE()
			,(CASE WHEN ISNULL(@in_vchToWarehouse,'') <> '' THEN @v_vchToWarehouseID ELSE NULL END)
			,@in_vchCustomerID
			,@v_vchCustomerCode
			,@v_vchCustomerName
			,@v_vchCustomerDesc
			,@v_vchAddrLine1
			,@v_vchAddrLine2
			,@v_vchAddrLine3
			,@v_vchCustCity
			,@v_vchCustProvince
			,@v_vchPostalCode
			,@v_vchCountryCode
			,@v_vchCountryName
			,@v_vchContact
			,@v_vchPhone
			,@v_vchFax
			,@v_vchEmail
			,@in_vchUserID
			,GETDATE()
			,'BLIND PICK'
			,@in_vchWhID
			,@in_vchOwnerCode
			)
	END 

	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus			NVARCHAR(50)
	------------------------------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------------------------------
	IF (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			-------------------------------------------------------------
			-- Check Rule 'select item status'
			-------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'SELECT_ITEM_STATUS_FOR_PICK' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER';
					SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
						,@v_vchInvStatus = inv_status
					FROM t_wms_inventory_status
					WHERE inv_status = (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_STATUS_BLIND_PICK_DEFAULT' AND is_active = 'YES')
					AND is_active = 'YES' 
				END
		END
	
	SELECT @v_vchOutboundMasterID	AS outbound_order_master_id
		, @v_vchOutboundOrderNumber AS outbound_order_number
		, @v_vchInvStatusID			AS inventory_status_id
		, @v_vchInvStatus			AS inv_status
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_blind_receipt_close_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_blind_receipt_close_order]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchInboundMasterID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOrderStatus	NVARCHAR(10)
	--------------------------------------------------------------------
	-- Check Inbound Order Number in System?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id
		,@v_vchOrderStatus = ibMS.order_status 
	FROM t_wms_inbound_master ibMS 
	WHERE ibMS.inbound_order_number = @in_vchInboundOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF (ISNULL(@v_vchOrderStatus,'') = 'CLOSE')
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-ORDER-STATUS-CLOSE-ALREADY'
			GOTO EXIT_LABEL
		END 

	CLOSE_ORDER:
		--------------------------------------------------------------
		-- Close Order BY Order Number
		--------------------------------------------------------------
		EXEC usp_close_inbound_order @in_vchApplicationID		= @in_vchApplicationID
									, @in_vchWhMasterID			= @in_vchWhMasterID
									, @in_vchInboundMasterID	= @v_vchInboundMasterID 
									, @in_vchCloseRemark		= 'Close Blind Receipt Order From PDA'
									, @in_vchDeviceID			= @in_vchDeviceID	
									, @in_vchUserID				= @in_vchUserID
									, @out_ErrorCode			= @out_vchErrorCode OUTPUT
									, @out_ErrorMessage			= @out_vchErrorMsg OUTPUT
	IF @out_vchErrorCode = '0'
		SET @out_vchNextScreen = 'INBOUND_ORDER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_blind_receipt_new_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_blind_receipt_new_order]
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchWhID			 NVARCHAR(25),
	@in_vchOwnerCode	 NVARCHAR(50), 
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON; 
	DECLARE	@v_vchOwnerID			 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInboundOrderNumber NVARCHAR(50)
	DECLARE @v_vchOrderType			 NVARCHAR(30) = NULL	
	
	BEGIN  --Generate Inbound Number
		DECLARE @v_vchYear			VARCHAR(40)
		DECLARE	@v_vchMonth			VARCHAR(2)
		DECLARE	@v_vchDay			VARCHAR(2) 
		DECLARE	@v_vchPrefix		VARCHAR(5)
		DECLARE	@v_vchSuffix		VARCHAR(5)
		DECLARE	@v_vchFormat		VARCHAR(10)
		DECLARE	@v_intRunning		INT
		DECLARE	@v_vchRunningID		VARCHAR(40)
		DECLARE @v_dtpCreateDate	DATETIME = GETDATE()


		SELECT @v_vchYear = DATEPART(YYYY,@v_dtpCreateDate)
		SELECT @v_vchMonth = DATEPART(MM,@v_dtpCreateDate)
		SELECT @v_vchDay = DATEPART(DD,@v_dtpCreateDate)

		SELECT @v_vchPrefix = ISNULL(VALUE,'')  FROM t_wms_rule WHERE rule_code = 'PREFIX_INBOUND_ORDER_FOR_RUNNING'
		SELECT @v_vchSuffix = ISNULL(VALUE,'')  FROM t_wms_rule WHERE rule_code = 'SUFFIX_INBOUND_ORDER_FOR_RUNNING'
		SELECT @v_vchFormat = ISNULL(VALUE,'0') FROM t_wms_rule WHERE rule_code = 'FORMAT_INBOUND_ORDER_FOR_RUNNING'

		SELECT @v_vchRunningID = running_id,@v_intRunning = running FROM t_wms_running_inbound_order 
		WHERE  [year] = @v_vchYear 
		AND [month] = @v_vchMonth 
		AND [day] = @v_vchDay

		IF (@v_intRunning IS NULL)
			BEGIN
				SET @v_intRunning = 0;
			END

		SET @v_intRunning = @v_intRunning + 1;
		SET @v_vchInboundOrderNumber = ISNULL(@v_vchPrefix,'') + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
		IF (@v_vchRunningID is null)
			BEGIN
				SET @v_vchRunningID = NEWID();
				INSERT INTO t_wms_running_inbound_order(year, month, day, running, prefix, sufix)
				VALUES(@v_vchYear,@v_vchMonth,@v_vchDay,@v_intRunning,@v_vchPrefix,@v_vchSuffix)
			END
		ELSE
			BEGIN
				UPDATE t_wms_running_inbound_order SET running = @v_intRunning WHERE running_id = @v_vchRunningID
			END
	END

	---------------------------------------------
	--INSERT INBOUND MASTER
	---------------------------------------------
	SET @v_vchInboundMasterID = NULL
	SET @v_vchOwnerID = NULL
	SELECT @v_vchInboundMasterID = inbound_order_master_id 
		,@v_vchOwnerID = owner_id
	FROM t_wms_inbound_master 
	WHERE inbound_order_number = @v_vchInboundOrderNumber 
	AND wh_master_id = @in_vchWhMasterID

	IF @v_vchInboundMasterID IS NULL
		BEGIN
			SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwnerCode AND is_active = 'YES'
			IF @v_vchOwnerID IS NULL
				BEGIN
					SELECT TOP 1 @v_vchOwnerID = own.owner_id 
						, @in_vchOwnerCode = own.owner_code
					FROM t_wms_owner_user ownUser
					INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
					WHERE own.is_active = 'YES'
					AND ownUser.user_id = @in_vchUserID
				END

			SELECT TOP 1 @v_vchOrderType =  value from t_wms_rule WHERE rule_code = 'BLIND_RECEIPT_ORDER_TYPE' AND is_active = 'YES'
			SET @v_vchInboundMasterID = NEWID();
			INSERT INTO [dbo].[t_wms_inbound_master]
				([inbound_order_master_id]
				,[wh_master_id]
				,[wh_id]
				,[inbound_order_number]
				,[owner_id]
				,[owner_code]
				,[order_type]
				,[order_status]          
				,[create_by]
				,[create_date])
			VALUES
				(@v_vchInboundMasterID
				,@in_vchWhMasterID
				,@in_vchWhID
				,@v_vchInboundOrderNumber
				,@v_vchOwnerID
				,@in_vchOwnerCode
				,@v_vchOrderType
				,'OPEN'
				,@in_vchUserID
				,GETDATE())
		END
		  
	EXEC usp_api_validate_blind_receipt_order_number @in_vchApplicationID	    = @in_vchApplicationID	    
													,@in_vchLocalID				= @in_vchLocalID		    
													,@in_vchUserID			    = @in_vchUserID			    
													,@in_vchDeviceID		    = @in_vchDeviceID		    
													,@in_vchWhMasterID		    = @in_vchWhMasterID		    
													,@in_vchWhID			    = @in_vchWhID			    
													,@in_vchOwnerID				= @v_vchOwnerID		    
													,@in_vchInboundOrderNumber	= @v_vchInboundOrderNumber	
													,@out_vchErrorCode			= @out_vchErrorCode	OUTPUT
													,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
 
	RETURN; 
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_blind_receipt_view_detail]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_blind_receipt_view_detail]
 	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
AS
BEGIN
	SET @out_vchNextScreen = 'VIEWER_SCREEN_RECEIPT'
	IF @in_vchControlName = 'LPN'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA LPN RECEIPT Screen
			----------------------------------------------------------
			SELECT inbound_order_number
				,owner_code
				,item_number
				,description AS item_description
				,lot_number
				,CONVERT(VARCHAR(10),mfg_date, 103) AS mfg_date
				,CONVERT(VARCHAR(10),expiry_date, 103) AS expiry_date
				,lpn_qty
				,uom_prompt
			FROM dbo.v_wms_receipt_lpn_display 
			WHERE inbound_order_number = @in_vchInboundOrderNumber
			AND wh_master_id = @in_vchWhMasterID
			ORDER BY item_number
		END
	ELSE IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA ITEM NUMBER Screen
			----------------------------------------------------------
			 SELECT ibMS.inbound_order_number
				 ,ibMS.owner_code
				 ,ibDT.item_number
				 ,item.description AS item_description
				 ,ibDT.lot_number
				 ,CONVERT(VARCHAR(10),ibDT.expiry_date, 103) AS expiry_date
				 ,uom.uom_prompt
				 ,SUM(ibDT.quantity_order) AS quantity_order
				 ,SUM(ibDT.quantity_receive) AS quantity_receive
			 FROM t_wms_inbound_master ibMS 
			 INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
			 INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
			 INNER JOIN t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
			 WHERE ibMS.wh_master_id = @in_vchWhMasterID
			 AND ibMS.inbound_order_number = @in_vchInboundOrderNumber
			 GROUP BY ibMS.inbound_order_number
				 ,ibMS.owner_code
				 ,ibDT.item_number
				 ,item.description
				 ,ibDT.lot_number
				 ,CONVERT(VARCHAR(10),ibDT.expiry_date, 103) 
				 ,uom.uom_prompt
			 ORDER BY item_number
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_close_order]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_close_order]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOrderNumber		NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
AS
BEGIN
	DECLARE @v_fltSumQtyOrder	FLOAT
	DECLARE @v_fltSumQtyReceive	FLOAT
	DECLARE @v_vchInboundMasterID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOrderStatus	NVARCHAR(10)

	--------------------------------------------------------------------
	-- Check Inbound Order Number in System?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id
		,@v_vchOrderStatus = ibMS.order_status 
	FROM t_wms_inbound_master ibMS 
	WHERE ibMS.inbound_order_number = @in_vchOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF (ISNULL(@v_vchOrderStatus,'') = 'CLOSE')
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-ORDER-STATUS-CLOSE-ALREADY'
			GOTO EXIT_LABEL
		END

	--------------------------------------------------------------
	-- Check SUM(Qty Receipt) < SUM(Qty Plan)
	--------------------------------------------------------------
	SELECT @v_fltSumQtyOrder = SUM(ISNULL(ibDT.quantity_order,0))	
		,@v_fltSumQtyReceive = SUM(ISNULL(ibDT.quantity_receive,0))	
	FROM t_wms_inbound_detail ibDT 
	WHERE ibDT.inbound_order_master_id = @v_vchInboundMasterID 

	IF (@v_fltSumQtyReceive <= @v_fltSumQtyOrder)
		BEGIN 
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_ALLOW_UNDER_RECEIPT' AND is_active = 'YES') = 'YES'
				BEGIN
					GOTO CLOSE_ORDER;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-INBOUND-UNDER-RECEIPT-NOT-ALLOW'
					GOTO EXIT_LABEL
				END
		END

	CLOSE_ORDER:
		--------------------------------------------------------------
		-- Close Order BY Order Number
		--------------------------------------------------------------
		EXEC usp_close_inbound_order @in_vchApplicationID		= @in_vchApplicationID
									, @in_vchWhMasterID			= @in_vchWhMasterID
									, @in_vchInboundMasterID	= @v_vchInboundMasterID 
									, @in_vchCloseRemark		= 'Close Order From PDA'
									, @in_vchDeviceID			= @in_vchDeviceID	
									, @in_vchUserID				= @in_vchUserID
									, @out_ErrorCode			= @out_vchErrorCode OUTPUT
									, @out_ErrorMessage			= @out_vchErrorMsg OUTPUT
	IF @out_vchErrorCode = '0'
		SET @out_vchNextScreen = 'INBOUND_ORDER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_close_partial_receipt]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_close_partial_receipt]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchReceiptNumber	NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
AS
BEGIN
	DECLARE @v_vchReceiptHeaderID UNIQUEIDENTIFIER,
		   @v_vchReceiptStatus	 NVARCHAR(10)

	--------------------------------------------------------------------
	-- Check Inbound Order Number in System?
	--------------------------------------------------------------------
	IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID and order_status = 'CLOSE')
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-ORDER-STATUS-CLOSE-ALREADY'
			GOTO EXIT_LABEL
		END

	SELECT TOP 1 @v_vchReceiptHeaderID = receipt_header_id
		, @v_vchReceiptStatus = receipt_status
	FROM t_wms_receipt_header
	WHERE inbound_order_master_id = @in_vchInboundMasterID 
	AND receipt_number = @in_vchReceiptNumber

	IF (@v_vchReceiptHeaderID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-NOT-IN-ORDER'
			GOTO EXIT_LABEL
		END

	IF (ISNULL(@v_vchReceiptStatus,'') = 'CLOSE')
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-ORDER-STATUS-CLOSE-ALREADY'
			GOTO EXIT_LABEL
		END
		 
	EXEC usp_close_partial_receive @in_vchApplicationID		= @in_vchApplicationID
								  , @in_vchDevice			= @in_vchDeviceID
								  , @in_vchWhMasterID		= @in_vchWhMasterID
								  , @in_vchInboundMasterID	= @in_vchInboundMasterID	
								  , @in_vchReceiptHeaderID	= @v_vchReceiptHeaderID
								  , @in_vchCloseBy			= @in_vchUserID	
								  , @out_ErrorCode			= @out_vchErrorCode OUTPUT
								  , @out_ErrorMessage		= @out_vchErrorMsg OUTPUT
	IF @out_vchErrorCode = '0'
		SET @out_vchNextScreen = 'INBOUND_ORDER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_confirm_ship]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_confirm_ship]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundOrderNumber		VARCHAR(50), 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOrderStatus  NVARCHAR(10)
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @in_vchOutboundOrderNumber
	AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF @v_vchOrderStatus = 'SHIP'
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_IS_SHIP'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
		
	EXEC usp_outbound_ship_confirm @in_vchApplicationID		= @in_vchApplicationID
									, @in_vchWhMasterID		= @in_vchWhMasterID
									, @in_vchDeviceID		= @in_vchDeviceID
									, @in_vchUserID			= @in_vchUserID
									, @in_vchOutboundMasterID = @v_vchOutboundMasterID
									, @in_vchCarrierID		= NULL
									, @in_vchTruckType		= NULL
									, @in_vchTruckNumber	= NULL
									, @in_vchDriverLicense	= NULL
									, @in_vchContainerNo	= NULL
									, @in_vchSealNumber		= NULL
									, @in_vchPostingDate	= NULL
									, @in_dtShipDateActual  = NULL
									, @out_ErrorCode	    = @out_vchErrorCode	OUTPUT
									, @out_ErrorMessage	    = @out_vchErrorMsg OUTPUT


	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END

	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50) = NULL
	--Clear ค่าใน Dropdown ของ outbound หลังจากก Confirm Ship แล้ว 
	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
		BEGIN
			PRINT 'NO PICK'
			----------------------------------------------------------
			-- Binding Outbound Order Number
			-- กรณีที่ไม่ให้ช่วยกันหยิบ
			----------------------------------------------------------
			SELECT TOP 1 @v_vchOutboundOrderNumber = outbound_order_number 
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			AND pick_type = 'SYSTEM'
			AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
			ORDER BY outbound_order_number
		END
	ELSE
		BEGIN
			----------------------------------------------------------
			-- Binding Outbound Order Number
			----------------------------------------------------------
			SELECT TOP 1 @v_vchOutboundOrderNumber = outbound_order_number 
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			AND pick_type = 'SYSTEM'
			ORDER BY outbound_order_number
		END
	SELECT ISNULL(@v_vchOutboundOrderNumber,'') AS outbound_order_number
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
