/****** Object:  StoredProcedure [dbo].[usp_api_option_new_outbound_pack_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_new_outbound_pack_number]
(
	@in_vchApplicationID  VARCHAR(40),
	@in_vchControlName	  NVARCHAR(50),	--Current Screen
	@in_vchLocalID		  VARCHAR(40),
	@in_vchUserID		  NVARCHAR(25),
	@in_vchWhMasterID	  UNIQUEIDENTIFIER,
 	@in_vchOutboundNumber NVARCHAR(50),
	@out_vchErrorCode	  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER
		DECLARE @v_vchOrderStatus		VARCHAR(25) 
		DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchOwnerCode			NVARCHAR(40) = NULL
		DECLARE @v_vchPackNumber		NVARCHAR(25) = NULL
		DECLARE	@v_fltQuantityPick		FLOAT = 0
		DECLARE @v_fltQuantityPack		FLOAT = 0
		DECLARE @v_intRound INT
		SELECT @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

		SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id  
			, @v_vchOwnerID = obMS.owner_id
			, @v_vchOwnerCode = own.owner_code
			, @v_vchOrderStatus = obMS.order_status
			, @v_fltQuantityPick = SUM(ISNULL(pickDT.quantity_pick,0))
			, @v_fltQuantityPack = SUM(ISNULL(pickDT.quantity_pack,0))
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		LEFT JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
		LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
		WHERE obMS.outbound_order_number = @in_vchOutboundNumber
		AND obMS.wh_master_id = @in_vchWhMasterID
		GROUP BY obMS.outbound_order_master_id,obMS.owner_id,own.owner_code,obMS.order_status

		IF @v_vchOutboundMasterID IS NULL
			BEGIN
				SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundNumber,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		IF (@v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			BEGIN
				--Status ไม่ถูกต้อง
				SET @out_vchErrorCode = 'INFO-OUTBOUND-INVALID-STATUS'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				RETURN;
			END
		IF ROUND(@v_fltQuantityPick - @v_fltQuantityPack,@v_intRound) <= 0
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_ITEM_FOR_PACK'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundNumber,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		EXEC usp_generate_running_outbound_pack_number @in_vchUserID		= @in_vchUserID
													  ,@in_vchOutboundNumber= @in_vchOutboundNumber		
													  ,@out_vchPackNumber	= @v_vchPackNumber OUTPUT		
													  ,@out_ErrorCode		= @out_vchErrorCode OUTPUT		
													  ,@out_ErrorMessage	= @out_vchErrorMsg OUTPUT

	NEXT_SCREEN:
		DECLARE @v_vchLPN NVARCHAR(25) = ''
		DECLARE @v_vchLocationID UNIQUEIDENTIFIER
		DECLARE @v_vchOutboundPickMasterID UNIQUEIDENTIFIER
		
		SELECT TOP 1 @v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
			,@v_vchLocationID = pickDT.staging_location_id
			,@v_vchLPN = pickDT.staging_lpn
		FROM t_wms_outbound_pick_master pickMS
		INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
		WHERE pickMS.outbound_order_master_id = @v_vchOutboundMasterID 

		IF @in_vchControlName <> 'ITEM_NUMBER'
			BEGIN
				IF (SELECT COUNT(DISTINCT pickDT.staging_lpn) FROM t_wms_outbound_pick_master pickMS
					INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
					WHERE pickMS.outbound_order_master_id = @v_vchOutboundMasterID) > 1
					BEGIN
						SET @out_vchNextScreen = 'LPN'
					END
				ELSE
					BEGIN
						SET @out_vchNextScreen = 'ITEM_NUMBER'
					END
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'ITEM_NUMBER'
			END

	SELECT @v_vchOutboundMasterID AS outbound_order_master_id 
		,@v_vchOutboundPickMasterID AS outbound_pick_master_id
		,@v_vchOwnerID AS owner_id
		,@v_vchOwnerCode AS owner_code
		,@v_vchPackNumber AS pack_number
		,@v_vchLocationID AS location_id
		,@v_vchLPN AS lpn
END
 

 /*
declare @in_vchApplicationID   VARCHAR(40)
declare @in_vchLocalID		   VARCHAR(40)
declare @in_vchUserID		   NVARCHAR(25) = 'MAI'
declare @in_vchWhMasterID	   UNIQUEIDENTIFIER = 'B69530D7-C548-457D-A3A3-CE47DC3EE438'
declare @in_vchOutboundNumber  NVARCHAR(50) = '202001220001'
declare @out_vchErrorCode	   VARCHAR(50)
declare @out_vchErrorMsg	   NVARCHAR(500)
declare @out_vchNextScreen	   NVARCHAR(50)

EXEC usp_api_option_new_outbound_pack_number @in_vchApplicationID   = @in_vchApplicationID   
											,@in_vchLocalID		  	= @in_vchLocalID		   
											,@in_vchUserID		  	= @in_vchUserID		   
											,@in_vchWhMasterID	  	= @in_vchWhMasterID	   
											,@in_vchOutboundNumber 	= @in_vchOutboundNumber  
											,@out_vchErrorCode	  	= @out_vchErrorCode	output 
											,@out_vchErrorMsg	  	= @out_vchErrorMsg output  
											,@out_vchNextScreen	  	= @out_vchNextScreen output


select @out_vchErrorCode,@out_vchErrorMsg, @out_vchNextScreen 



