CREATE PROCEDURE [dbo].[usp_api_option_next_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER, 
	@in_vchLocationID		UNIQUEIDENTIFIER, 
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemDesc			NVARCHAR(200) = NULL,
			@v_vchLotControl		VARCHAR(5) = NULL,
			@v_vchSNControl			VARCHAR(5) = NULL,
			@v_vchExpiryDateControl	VARCHAR(5) = NULL,
			@v_vchAttribute1Control	VARCHAR(5) = NULL,
			@v_vchAttribute2Control	VARCHAR(5) = NULL,
			@v_vchAttribute3Control	VARCHAR(5) = NULL,
			@v_vchAttribute4Control	VARCHAR(5) = NULL,
			@v_vchAttribute5Control	VARCHAR(5) = NULL,
			@v_vchUomPrompt			NVARCHAR(40) = NULL

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number และ ใน Cross Ref
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		, @v_vchItemDesc = description
		, @v_vchLotControl = lot_control
		, @v_vchSNControl = sn_control
		, @v_vchExpiryDateControl = expiry_date_control
		, @v_vchAttribute1Control = attribute1_control
		, @v_vchAttribute2Control = attribute2_control
		, @v_vchAttribute3Control = attribute3_control
		, @v_vchAttribute4Control = attribute4_control
		, @v_vchAttribute5Control = attribute5_control
		, @v_vchUomPrompt = uom_prompt
	FROM  t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
	WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
	AND item.owner_id = @in_vchOwnerID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF @v_vchWhItemMasterID IS NULL
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------------------
	--Check Item In Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND location_id = @in_vchLocationID
					AND is_override = 'NO'
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,''))
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------------------------------
	-- Check Rule 'WH RULES REQUIRE REASON CODE FOR NEXT LOCATION'
	------------------------------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REASON_FOR_NEXT_LOC' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'REASON_NEXT_LOCATION'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			--Put Location on Hold and Create cycle count plan to correct the inventory
			EXEC usp_api_validate_picking_reason @in_vchApplicationID = @in_vchApplicationID	
											 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
											 ,@in_vchOutboundMasterID = @in_vchOutboundMasterID
											 ,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID
											 ,@in_vchLocationID		  = @in_vchLocationID
											 ,@in_vchParentLPN		  = @in_vchParentLPN
											 ,@in_vchLpn			  = @in_vchLPN
											 ,@in_vchWhItemMasterID	  = @v_vchWhItemMasterID
											 ,@in_vchItemMasterID	  = @v_vchItemMasterID
											 ,@in_vchItemNumber		  = @in_vchItemNumber
											 ,@in_vchReason			  = NULL
											 ,@in_vchLocalID		  = @in_vchLocalID
											 ,@in_vchDeviceID		  = @in_vchDeviceID
											 ,@in_vchUserID			  = @in_vchUserID
											 ,@out_vchErrorCode		  = @out_vchErrorCode OUTPUT	
											 ,@out_vchErrorMsg		  = @out_vchErrorMsg OUTPUT
											 ,@out_vchNextScreen	  = @out_vchNextScreen OUTPUT	

			IF @out_vchErrorCode = '0'
				BEGIN
					SET @out_vchErrorCode = NULL
					SET @out_vchErrorMsg = NULL
				END 
		END 

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT  @v_vchWhItemMasterID	  AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_pack_confirm_ship]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_pack_confirm_ship]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOrderStatus  NVARCHAR(10)
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @in_vchOutboundNumber
	AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-OUTBOUND-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	IF @v_vchOrderStatus = 'SHIP'
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_IS_SHIP'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
		
	EXEC usp_outbound_ship_confirm @in_vchApplicationID		= @in_vchApplicationID
									, @in_vchWhMasterID		= @in_vchWhMasterID
									, @in_vchDeviceID		= @in_vchDeviceID
									, @in_vchUserID			= @in_vchUserID
									, @in_vchOutboundMasterID = @v_vchOutboundMasterID
									, @in_vchCarrierID		= NULL
									, @in_vchTruckType		= NULL
									, @in_vchTruckNumber	= NULL
									, @in_vchDriverLicense	= NULL
									, @in_vchContainerNo	= NULL
									, @in_vchSealNumber		= NULL
									, @in_vchPostingDate	= NULL
									, @in_dtShipDateActual  = NULL
									, @out_ErrorCode	    = @out_vchErrorCode	OUTPUT
									, @out_ErrorMessage	    = @out_vchErrorMsg OUTPUT


	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END

	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50) = NULL
	SELECT @v_vchOutboundOrderNumber = outbound_order_number
	FROM dbo.t_wms_outbound_master
	WHERE wh_master_id = @in_vchWhMasterID
	AND order_type IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
 	AND order_status IN ('PICK','PICKED','PACK')
	ORDER BY outbound_order_number
	
	SELECT ISNULL(@v_vchOutboundOrderNumber,'') AS outbound_order_number
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
