CREATE PROCEDURE [dbo].[usp_api_option_pack_partial_confirm_ship]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOrderStatus  NVARCHAR(10)
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @in_vchOutboundNumber
	AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-OUTBOUND-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	IF @v_vchOrderStatus = 'SHIP'
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_IS_SHIP'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
		
	EXEC usp_outbound_partial_ship_confirm @in_vchApplicationID	= @in_vchApplicationID 
									, @in_vchOutboundMasterID = @v_vchOutboundMasterID
									, @in_vchDeviceID		= @in_vchDeviceID
									, @in_vchUserID			= @in_vchUserID 
									, @out_ErrorCode	    = @out_vchErrorCode	OUTPUT
									, @out_ErrorMessage	    = @out_vchErrorMsg OUTPUT 

	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END

	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50) = NULL
	--Clear ค่าใน Dropdown ของ outbound หลังจากก Confirm Ship แล้ว 
	SELECT @v_vchOutboundOrderNumber = outbound_order_number
	FROM dbo.t_wms_outbound_master
	WHERE wh_master_id = @in_vchWhMasterID
	AND order_type IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
 	AND order_status IN ('PICK','PICKED','PACK')
	ORDER BY outbound_order_number 
	SELECT ISNULL(@v_vchOutboundOrderNumber,'') AS outbound_order_number
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
