CREATE PROCEDURE [dbo].[usp_api_option_partial_confirm_ship]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOrderNumber		VARCHAR(50), 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOrderStatus  NVARCHAR(10)
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @in_vchOrderNumber
	AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF @v_vchOrderStatus = 'SHIP'
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_IS_SHIP'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
		
	EXEC usp_outbound_partial_ship_confirm @in_vchApplicationID		= @in_vchApplicationID 
									, @in_vchOutboundMasterID = @v_vchOutboundMasterID
									, @in_vchDeviceID		= @in_vchDeviceID
									, @in_vchUserID			= @in_vchUserID 
									, @out_ErrorCode	    = @out_vchErrorCode	OUTPUT
									, @out_ErrorMessage	    = @out_vchErrorMsg OUTPUT 

	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END

	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50) = NULL
	--Clear ค่าใน Dropdown ของ outbound หลังจากก Confirm Ship แล้ว 
	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO')
		BEGIN
			PRINT 'NO PICK'
			----------------------------------------------------------
			-- Binding Outbound Order Number
			-- กรณีที่ไม่ให้ช่วยกันหยิบ
			----------------------------------------------------------
			SELECT TOP 1 @v_vchOutboundOrderNumber = outbound_order_number 
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			AND pick_type = 'SYSTEM'
			AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '')
			ORDER BY outbound_order_number
		END
	ELSE
		BEGIN
			----------------------------------------------------------
			-- Binding Outbound Order Number
			----------------------------------------------------------
			SELECT TOP 1 @v_vchOutboundOrderNumber = outbound_order_number 
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			AND pick_type = 'SYSTEM'
			ORDER BY outbound_order_number
		END
	SELECT ISNULL(@v_vchOutboundOrderNumber,'') AS outbound_order_number
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_picking_override_expiry_date]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_picking_override_expiry_date]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLocation			NVARCHAR(50), 
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_vchItemMasterID		UNIQUEIDENTIFIER,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchLotNumber		NVARCHAR(50),
	@in_vchOverLocationID	UNIQUEIDENTIFIER,
	@in_vchOverLocation		NVARCHAR(50),
	@in_vchOverLPN			NVARCHAR(25), 
	@in_vchOverWhItemMasterID UNIQUEIDENTIFIER,
	@in_vchOverItemMasterID	UNIQUEIDENTIFIER,
	@in_vchOverUOMPrompt	NVARCHAR(40),
	@in_vchOverLotNumber	NVARCHAR(50),
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	IF @in_vchOverLocationID IS NULL
		BEGIN
			SET @in_vchOverLocationID = @in_vchLocationID
			SET @in_vchOverLocation = @in_vchLocation
		END

	IF ISNULL(@in_vchOverLPN,'') = ''
		BEGIN
			SET @in_vchOverLPN = @in_vchLPN
		END

	IF @in_vchOverWhItemMasterID IS NULL
		BEGIN
			SET @in_vchOverWhItemMasterID = @in_vchWhItemMasterID
			SET @in_vchOverItemMasterID = @in_vchItemMasterID
			SET @in_vchOverUOMPrompt = @in_vchUOMPrompt
		END

	IF ISNULL(@in_vchOverLotNumber,'') = ''
		BEGIN
			SET @in_vchOverLotNumber = @in_vchLotNumber
		END

	SET @out_vchNextScreen = 'OVERRIDE_EXPIRY_DATE';
	SELECT @in_vchOverLocationID    AS override_location_id
		, @in_vchOverLocation	    AS override_location
		, @in_vchOverLPN		    AS override_lpn 
		, @in_vchOverWhItemMasterID	AS override_wh_item_master_id
		, @in_vchOverItemMasterID	AS override_item_master_id
		, @in_vchOverUOMPrompt		AS override_uom_prompt
		, @in_vchOverLotNumber		AS override_lot_number
		, NULL as location_id --Clear value ปกติ
		, '' as location    --Clear value ปกติ
		, '' as lpn		    --Clear value ปกติ
		, '' as lot_number  --Clear value ปกติ
		, '' as expiry_date --Clear value ปกติ
		, '' AS uom_prompt	--Clear value ปกติ
		, '' AS qty			--Clear value ปกติ

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_option_picking_override_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_picking_override_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	SET @out_vchNextScreen = 'OVERRIDE_LOCATION';
	SELECT  '' AS location
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
