CREATE PROCEDURE [dbo].[usp_api_option_rerun]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOrderNumber		VARCHAR(50), 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOutboundMasterID UNIQUEIDENTIFIER = NULL
	SELECT @v_vchOutboundMasterID = outbound_order_master_id FROM t_wms_outbound_master WHERE outbound_order_number = @in_vchOrderNumber AND wh_master_id = @in_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			GOTO EXIT_LABEL
		END

	EXEC usp_outbound_release_order @in_vchApplicationID		= @in_vchApplicationID
									,@in_vchDeviceID			= @in_vchDeviceID	
									,@in_vchUserID				= @in_vchUserID
									,@in_vchOutboundMasterID	= @v_vchOutboundMasterID
									,@out_ErrorCode				= @out_vchErrorCode	OUTPUT
									,@out_ErrorMessage			= @out_vchErrorMsg OUTPUT
	
	IF ISNULL(@out_vchErrorCode,'') = '0'
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
END
