/****** Object:  StoredProcedure [dbo].[usp_api_option_view_blind_pick_detail]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_view_blind_pick_detail]
 	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	VARCHAR(50), 
	@in_vchWhItemMasterID   UNIQUEIDENTIFIER = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
AS
BEGIN
	SET @out_vchNextScreen = 'VIEWER_SCREEN_PICK'
	IF @in_vchControlName IN ('ORDER_NUMBER','LPN','ITEM_NUMBER')
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA Pick Detail
			----------------------------------------------------------
			SELECT obMS.wh_id 
				,obMS.owner_code
				,obMS.outbound_order_number 
				,item.item_number
				,item.description	 AS item_description
				,obDT.quantity_order AS quantity_order
				,obDT.quantity_pick  AS quantity_pick
				,obDT.quantity_ship  AS quantity_ship
				,pickDT.count_lpn
				,uom.uom
				,dbo.usf_get_outbound_pick_lpn(obDT.outbound_order_detail_id) as list_lpn
			FROM t_wms_outbound_master obMS
			INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id  
			INNER JOIN t_wms_item item ON obDT.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
			LEFT JOIN (SELECT outbound_order_detail_id
							,COUNT(lpn) as count_lpn
						FROM t_wms_outbound_pick_detail
						WHERE ISNULL(quantity_pick,0) = ISNULL(quantity_plan,0)
						GROUP BY outbound_order_detail_id
					   )pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
			WHERE obMS.outbound_order_number = @in_vchOutboundOrderNumber
			ORDER by item.item_number
		END
END
GO
