/****** Object:  StoredProcedure [dbo].[usp_api_option_view_receipt_detail]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_option_view_receipt_detail]
 	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER,
	@in_vchWhItemMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	    NVARCHAR(50)  = NULL,
	@in_vchExpiryDate	    NVARCHAR(20)  = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
AS
BEGIN
	SET @out_vchNextScreen = 'VIEWER_SCREEN_RECEIPT'
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA LPN RECEIPT Screen
			----------------------------------------------------------
			SELECT ibMS.inbound_order_number
				,ibMS.owner_code
				,ibDT.item_number
				,item.description AS item_description
				,recDT.lot_number
				,CONVERT(VARCHAR(10),recDT.expiry_date, 103) AS expiry_date
				,ibDT.quantity_order AS quantity_order
				,SUM(recDT.quantity_receiveD) AS quantity_receive
				,uom.uom_prompt
			FROM t_wms_inbound_master ibMS 
			INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
			INNER JOIN t_wms_receipt_detail recDT ON ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
			INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
			WHERE ibMS.wh_master_id = @in_vchWhMasterID
			AND ibMS.inbound_order_master_id = @in_vchInboundMasterID
			AND recDT.receipt_header_id = @in_vchReceiptHeaderID
			GROUP BY ibMS.inbound_order_number
				,ibMS.owner_code
				,ibDT.item_number
				,item.description
				,ibDT.quantity_order
				,recDT.lot_number
				,CONVERT(VARCHAR(10),recDT.expiry_date, 103) 
				,uom.uom_prompt
			ORDER BY item_number
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA LPN RECEIPT Screen
			----------------------------------------------------------
			SELECT DISTINCT ibMS.inbound_order_number
				, ibMS.owner_code 
				, item.item_number
				, item.description
				, ibLPN.lot_number
				, CONVERT(VARCHAR(10),ibLPN.expiry_date, 103) AS expiry_date
				, ISNULL(ibLPN.quantity,0)				AS lpn_qty
				, ISNULL(ibLPN.quantity_receive,0)		AS lpn_qty_receive
			FROM t_wms_inbound_master ibMS
			INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id 
			INNER JOIN t_wms_wh_item whItem on ibDT.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom on ibDT.item_uom_id = uom.item_uom_id
			LEFT JOIN t_wms_inbound_lpn_detail ibLPN ON  ibDT.inbound_order_detail_id = ibLPN.inbound_order_detail_id
			WHERE ibMS.wh_master_id = @in_vchWhMasterID
			AND ibMS.inbound_order_master_id = @in_vchInboundMasterID 
			ORDER BY item.item_number
		END
	ELSE IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA ITEM NUMBER Screen
			----------------------------------------------------------
			SELECT ibMS.inbound_order_number
				,ibMS.owner_code
				,ibDT.item_number
				,item.description AS item_description
				,recDT.lot_number
				,CONVERT(VARCHAR(10),recDT.expiry_date, 103) AS expiry_date
				,ibDT.quantity_order AS quantity_order
				,SUM(recDT.quantity_receiveD) AS quantity_receive
				,uom.uom_prompt
			FROM t_wms_inbound_master ibMS 
			INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
			INNER JOIN t_wms_receipt_detail recDT ON ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
			INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
			WHERE ibMS.wh_master_id = @in_vchWhMasterID
			AND ibMS.inbound_order_master_id = @in_vchInboundMasterID
			GROUP BY ibMS.inbound_order_number
				,ibMS.owner_code
				,ibDT.item_number
				,item.description
				,ibDT.quantity_order
				,recDT.lot_number
				,CONVERT(VARCHAR(10),recDT.expiry_date, 103) 
				,uom.uom_prompt
			ORDER BY item_number
		END
	ELSE IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- SHOW DATA ITEM NUMBER Screen
			----------------------------------------------------------
			SELECT ibMS.inbound_order_number
				,ibMS.owner_code
				,ibDT.item_number
				,item.description AS item_description
				,recDT.lot_number
				,CONVERT(VARCHAR(10),recDT.expiry_date, 103) AS expiry_date
				,dbo.usf_find_get_serial_receipt(recDT.receipt_header_id,recDT.wh_item_master_id,recDT.lot_number,recDT.expiry_date,recDT.attribute1,recDT.attribute2,recDT.attribute3,recDT.attribute4,recDT.attribute5) as serial_detail
				,ibDT.quantity_order AS quantity_order
				,SUM(recDT.quantity_received) AS quantity_receive
				,uom.uom_prompt
			FROM t_wms_inbound_master ibMS 
			INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
			INNER JOIN t_wms_receipt_detail recDT ON ibDT.inbound_order_detail_id = recDT.inbound_order_detail_id
			INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
			WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID
			AND recDT.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(recDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')  
			AND ISNULL(recDT.expiry_date,'')= ISNULL(@in_vchExpiryDate,'')    
			AND ISNULL(recDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(recDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(recDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(recDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(recDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			GROUP BY ibMS.inbound_order_number
				,ibMS.owner_code
				,recDT.wh_item_master_id
				,ibDT.item_number
				,item.description
				,recDT.receipt_header_id
				,ibDT.quantity_order 
				,recDT.lot_number
				,recDT.expiry_date 
				,recDT.attribute1
				,recDT.attribute2
				,recDT.attribute3
				,recDT.attribute4
				,recDT.attribute5 
				,uom.uom_prompt
			ORDER BY  ibDT.item_number
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_pick_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_2D]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50) = NULL,
	@in_vchCustomerID			UNIQUEIDENTIFIER = NULL,
	@in_vchCustomerCode			NVARCHAR(50) = NULL,
	@in_vchToWarehouse			NVARCHAR(25)  = NULL,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus			NVARCHAR(50) = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL,
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50)=NULL,
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),	
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT, 
	@in_vchPickRule				NVARCHAR(50) = '',
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round					INT,	
			@v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemDesc			NVARCHAR(200) = NULL,
			@v_vchLotControl		VARCHAR(5) = NULL,
			@v_vchSNControl			VARCHAR(5) = NULL,
			@v_vchExpiryDateControl	VARCHAR(5) = NULL,
			@v_vchAttribute1Control VARCHAR(5) = NULL,
			@v_vchAttribute2Control VARCHAR(5) = NULL,
			@v_vchAttribute3Control VARCHAR(5) = NULL,
			@v_vchAttribute4Control VARCHAR(5) = NULL,
			@v_vchAttribute5Control VARCHAR(5) = NULL,
			@v_vchUomPrompt			NVARCHAR(40) = NULL,
			@v_fltQuantityPlan		FLOAT,
			@v_fltQuantityPick		FLOAT,
			@v_vchPickRule			NVARCHAR(40)  = NULL,
			@v_vchItemIsActive		VARCHAR(3) = NULL
			
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
	 
	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchItemDesc = item.description
		, @v_vchLotControl = item.lot_control
		, @v_vchExpiryDateControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchPickRule = r.rule_code
		, @v_vchUomPrompt = uom.uom_prompt
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_rule r on uom.picking_class = r.rule_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @in_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchWarehouse,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END
	
	--------------------------------------------------
	--Get Location
	--------------------------------------------------
	IF (@in_vchLocationID IS NULL)
		BEGIN
			SELECT TOP 1 @in_vchLocationID = location_id
				,@in_vchLocation = location
				,@in_vchAttribute1 = attribute1
				,@in_vchInvStatusID = inventory_status_id
				,@in_vchInvStatus = inv_status
			FROM v_wms_inventory_for_blind_pick
			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id =  @in_vchOwnerID 
 			AND wh_item_master_id =  @v_vchWhItemMasterID
			--AND inventory_status_id = @in_vchInvStatusID 
 			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')

			IF @in_vchLocationID IS NULL
				BEGIN
					SET @out_vchErrorCode = 'NOT_FOUND_DATA_FOR_PICK'
					GOTO EXIT_LABEL;
				END
		END 

	IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END 

	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		END
	 
	IF @v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END	 

	IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END	 

	IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	 
	IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END
	 
	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	 
	--------------------------------------------------
	-- Validate location
	--------------------------------------------------
	IF (((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION'  AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN 
			----------------------------------------------------
			-- ตรวจสอบว่ามี Item อยู่ใน Location ที่เลือกใน Inventory?
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_blind_pick 
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id =  @in_vchOwnerID 
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND wh_item_master_id =  @v_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID 
							AND location_id = @in_vchLocationID 
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							)
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_FOR_PICK'
				GOTO EXIT_LABEL;
			END
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_blind_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND inventory_status_id = @in_vchInvStatusID
			AND (CASE WHEN @in_vchLocationID IS NULL THEN '' ELSE location_id END) =  (CASE WHEN @in_vchLocationID IS NULL THEN '' ELSE @in_vchLocationID END)	--ถ้า Location เป็นว่างมาแสดงว่า scan 2D ที่หน้าจอ item
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_blind_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID
							AND (CASE WHEN @in_vchLocationID IS NULL THEN '' ELSE location_id END) =  (CASE WHEN @in_vchLocationID IS NULL THEN '' ELSE @in_vchLocationID END)	--ถ้า Location เป็นว่างมาแสดงว่า scan 2D ที่หน้าจอ item
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
				BEGIN
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	IF @in_vchLocationID IS NULL
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
		END
	ELSE
		BEGIN
			IF @v_vchSNControl = 'FULL'
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
				END
		END
	
	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
		SELECT  @v_vchWhItemMasterID	AS wh_item_master_id
			   ,@v_vchItemMasterID		AS item_master_id
			   ,@in_vchItemNumber		AS item_number
			   ,@v_vchItemDesc		    AS item_description
			   ,@v_vchLotControl	    AS lot_control
			   ,@v_vchSNControl		    AS sn_control
			   ,@v_vchExpiryDateControl	AS expiry_date_control
			   ,@v_vchAttribute1Control AS attribute1_control
			   ,@v_vchAttribute2Control AS attribute2_control
			   ,@v_vchAttribute3Control AS attribute3_control
			   ,@v_vchAttribute4Control AS attribute4_control
			   ,@v_vchAttribute5Control AS attribute5_control
			   ,@in_fltQuantity			AS display_default_qty
			   ,@in_fltQuantity			AS qty
			   ,@v_vchUomPrompt		    AS uom_prompt
			   ,@v_vchPickRule			AS pick_rule
			   ,(CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

			   ,@in_vchParentLPN		AS parent_lpn
			   ,@in_vchLPN				AS lpn
			   ,@in_vchLotNumber		AS lot_number
			   ,@in_vchExpiryDate		AS expiry_date
			   ,@in_vchSerialNumber		AS serial_number
			   ,@in_vchAttribute1		AS attribute1
			   ,@in_vchAttribute2		AS attribute2
			   ,@in_vchAttribute3		AS attribute3
			   ,@in_vchAttribute4		AS attribute4
			   ,@in_vchAttribute5		AS attribute5
			   ,@in_vchLocationID		AS location_id
			   ,@in_vchLocation			AS location
			   ,@in_vchInvStatusID		AS inventory_status_id
			   ,@in_vchInvStatus		AS inv_status

	SAVE_TRANS:		
		print 'save'	 
		EXEC usp_outbound_generate_blind_pick @in_vchApplicationID		 = @in_vchApplicationID		
											 ,@in_vchLocalID			 = @in_vchLocalID					
											 ,@in_vchDeviceID			 = @in_vchDeviceID					
											 ,@in_vchUserID				 = @in_vchUserID				
											 ,@in_vchWhMasterID			 = @in_vchWhMasterID			
											 ,@in_vchWarehouse			 = @in_vchWarehouse			
											 ,@in_vchForkLocation		 = @in_vchForkLocation				
											 ,@in_vchCustomerID			 = @in_vchCustomerID			
											 ,@in_vchCustomerCode		 = @in_vchCustomerCode				
											 ,@in_vchToWarehouse		 = @in_vchToWarehouse		
											 ,@in_vchOutboundOrderNumber = @in_vchOutboundOrderNumber		
											 ,@in_vchOwnerID			 = @in_vchOwnerID					
											 ,@in_vchOwnerCode			 = @in_vchOwnerCode			
											 ,@in_vchBoxNumber			 = @in_vchBoxNumber			
											 ,@in_vchLocationID			 = @in_vchLocationID			
											 ,@in_vchLocation			 = @in_vchLocation					
											 ,@in_vchParentLPN			 = @in_vchParentLPN			
											 ,@in_vchLPN				 = @in_vchLPN						
											 ,@in_vchInvStatusID		 = @in_vchInvStatusID				
											 ,@in_vchInvStatus			 = @in_vchInvStatus			
											 ,@in_vchWhItemMasterID		 = @v_vchWhItemMasterID			
											 ,@in_vchItemNumber			 = @in_vchItemNumber			
											 ,@in_vchLotNumber			 = @in_vchLotNumber			
											 ,@in_vchExpiryDate			 = @in_vchExpiryDate			
											 ,@in_vchAttribute1			 = @in_vchAttribute1			
											 ,@in_vchAttribute2			 = @in_vchAttribute2			
											 ,@in_vchAttribute3			 = @in_vchAttribute3			
											 ,@in_vchAttribute4			 = @in_vchAttribute4			
											 ,@in_vchAttribute5			 = @in_vchAttribute5			
											 ,@in_vchSerialNumber		 = @in_vchSerialNumber				
											 ,@in_fltQuantity			 = @in_fltQuantity					
											 ,@in_vchUOMPrompt			 = @in_vchUOMPrompt			
											 ,@out_vchErrorCode			 = @out_vchErrorCode OUTPUT
											 ,@out_vchErrorMsg			 = @out_vchErrorMsg	OUTPUT
											 ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		IF @in_vchControlName = 'SERIAL_NUMBER'
			GOTO FINAL_SCREEN;
									
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_blind_pick_final_screen @in_vchApplicationID		 = @in_vchApplicationID		
													 ,@in_vchDeviceID			 = @in_vchDeviceID			
													 ,@in_vchUserID				 = @in_vchUserID			
													 ,@in_vchWhMasterID			 = @in_vchWhMasterID		
													 ,@in_vchOutboundOrderNumber = @in_vchOutboundOrderNumber
													 ,@in_vchLocationID			 = @in_vchLocationID		
													 ,@in_vchWhItemMasterID		 = @v_vchWhItemMasterID	
													 ,@in_vchItemMasterID		 = @v_vchItemMasterID		
													 ,@in_vchLocalID			 = @in_vchLocalID			
													 ,@out_vchErrorCode			 = @out_vchErrorCode OUTPUT
													 ,@out_vchErrorMsg			 = @out_vchErrorMsg	OUTPUT
													 ,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT


	RETURN;
	
	--------------------------------------------------------
	-- Exit the Process
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_pick_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_attribute1]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchUserID			 NVARCHAR(25) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		 NVARCHAR(25) = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		 NVARCHAR(25) = NULL,
	@in_vchLPN				 NVARCHAR(25) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL, 
	@in_vchAttribute2Control NVARCHAR(10) = NULL,
	@in_vchAttribute3Control NVARCHAR(10) = NULL,
	@in_vchAttribute4Control NVARCHAR(10) = NULL,
	@in_vchAttribute5Control NVARCHAR(10) = NULL,
	@in_vchSNControl		 NVARCHAR(10) = NULL,
	@in_vchLocalID			 VARCHAR(40)  = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	--------------------------------------------------
	-- Validate location
	--------------------------------------------------
	IF (((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION'  AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			----------------------------------------------------
			-- ตรวจสอบว่ามี Item อยู่ใน Location ที่เลือกใน Inventory?
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id
							FROM v_wms_inventory_for_blind_pick 
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id =  @in_vchOwnerID 
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND wh_item_master_id =  @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID 
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_FOR_PICK'
				GOTO EXIT_LABEL;
			END
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_blind_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_blind_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
				BEGIN
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END
		END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- Next Screen
		------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl			= NULL	
										,@in_vchExpiryDateControl	= NULL
										,@in_vchAttribute1Control	= NULL
										,@in_vchAttribute2Control	= @in_vchAttribute2Control
										,@in_vchAttribute3Control	= @in_vchAttribute3Control
										,@in_vchAttribute4Control	= @in_vchAttribute4Control
										,@in_vchAttribute5Control	= @in_vchAttribute5Control
										,@in_vchSNControl			= @in_vchSNControl
										,@in_vchIsCheckLot			= 'NO'
										,@in_vchIsCheckExpiryDate	= 'NO'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'YES'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@out_vchNextScreen	= @out_vchNextScreen OUTPUT	
	
	RETURN;
	---------------------------------------------------
	-- Exit the Process
	---------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
