CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_lpn]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchUserID			 NVARCHAR(25) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		 NVARCHAR(25) = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50) = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		 NVARCHAR(25) = NULL,
	@in_vchLPN				 NVARCHAR(25) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL,
	@in_vchLotControl		 NVARCHAR(10) = NULL,
	@in_vchSNControl		 NVARCHAR(10) = NULL,
	@in_vchExpiryDateControl NVARCHAR(10) = NULL,
	@in_vchAttribute1Control NVARCHAR(10) = NULL,
	@in_vchAttribute2Control NVARCHAR(10) = NULL,
	@in_vchAttribute3Control NVARCHAR(10) = NULL,
	@in_vchAttribute4Control NVARCHAR(10) = NULL,
	@in_vchAttribute5Control NVARCHAR(10) = NULL,
	@in_vchLocalID			 VARCHAR(40)  = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	--------------------------------------------------
	-- Validate location
	--------------------------------------------------
	IF (((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION'  AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			----------------------------------------------------
			-- ตรวจสอบว่ามี Item อยู่ใน Location ที่เลือกใน Inventory?
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id
							FROM v_wms_inventory_for_blind_pick 
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id =  @in_vchOwnerID 
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND wh_item_master_id =  @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID 
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_FOR_PICK'
				GOTO EXIT_LABEL;
			END
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_blind_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_blind_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
				BEGIN
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END
		END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- Next Screen
		------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl			= @in_vchLotControl	
										,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
										,@in_vchAttribute1Control	= @in_vchAttribute1Control
										,@in_vchAttribute2Control	= @in_vchAttribute2Control
										,@in_vchAttribute3Control	= @in_vchAttribute3Control
										,@in_vchAttribute4Control	= @in_vchAttribute4Control
										,@in_vchAttribute5Control	= @in_vchAttribute5Control
										,@in_vchSNControl			= @in_vchSNControl
										,@in_vchIsCheckLot			= 'YES'
										,@in_vchIsCheckExpiryDate	= 'NO'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@out_vchNextScreen	= @out_vchNextScreen OUTPUT	
	
	RETURN;

	---------------------------------------------------
	-- Exit the Process
	---------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_pick_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_order_number]
(
	@in_vchApplicationID	   VARCHAR(40)  = NULL,
	@in_vchUserID			   NVARCHAR(25),
	@in_vchWhMasterID		   UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			   UNIQUEIDENTIFIER = NULL, 
	@in_vchOutboundOrderNumber NVARCHAR(50) = NULL, 
	@in_vchLocalID			   VARCHAR(40)  = NULL,
	@out_vchErrorCode		   VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		   NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		   NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOrderStatus		NVARCHAR(50),
			@v_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus			NVARCHAR(50)

	SELECT @v_vchOutboundMasterID = outbound_order_master_id 
		,@v_vchOrderStatus = order_status
	FROM t_wms_outbound_master
	WHERE wh_master_id = @in_vchWhMasterID
	AND outbound_order_number = @in_vchOutboundOrderNumber
	 
	------------------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL
	------------------------------------------------------------------------------
	--ที่ต้อง where value <> open เนื่องจาก blind pick จะเปิด order ที่ status = open ก่อน แต่ถ้าทำจนถึง confirm qty status จะเป็น pick
	IF EXISTS (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES' AND value <> 'OPEN' AND value = @v_vchOrderStatus)
		BEGIN
			--Order Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-OUTBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END
						
	------------------------------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------------------------------
	IF (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			-------------------------------------------------------------
			-- Check Rule 'select item status'
			-------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'SELECT_ITEM_STATUS_FOR_PICK' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER';
					SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
						,@v_vchInvStatus = inv_status
					FROM t_wms_inventory_status
					WHERE inv_status = (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_STATUS_BLIND_PICK_DEFAULT' AND is_active = 'YES')
					AND is_active = 'YES' 
				END
		END
	
	SELECT @v_vchOutboundMasterID		AS outbound_order_master_id
		, @in_vchOutboundOrderNumber	AS outbound_order_number
		, @v_vchInvStatusID				AS inventory_status_id
		, @v_vchInvStatus				AS inv_status

	RETURN;
	 
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_pick_owner]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_owner]
(
	@in_vchApplicationID VARCHAR(40)   = NULL,
	@in_vchUserID		 NVARCHAR(25),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode	 NVARCHAR(40) = NULL,
	@in_vchLocalID		 VARCHAR(40) = NULL,
	@out_vchErrorCode	 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOwnerID	  UNIQUEIDENTIFIER = NULL

	-----------------------------------------------	
	-- Validate owner master
	-----------------------------------------------
	SELECT @v_vchOwnerID = own.owner_id
		, @in_vchOwnerCode = own.owner_code
	FROM t_wms_owner_user ownUser
	INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
	WHERE own.is_active = 'YES'
	AND own.owner_code = @in_vchOwnerCode
	AND ownUser.user_id = @in_vchUserID

	IF (@v_vchOwnerID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	 IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_BLIND_PICK_SHOW_CUSTOMER' and is_active = 'YES') = 'NO'
		BEGIN
			IF EXISTS (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'
						AND value IN (SELECT value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
				BEGIN
					--สำหรับกรณี Auto Insert Inbound
					SET @out_vchNextScreen = 'TO_WAREHOUSE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ORDER_NUMBER'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'CUSTOMER'
			GOTO NEXT_SCREEN;
		END
	
	NEXT_SCREEN:
	SELECT @v_vchOwnerID AS owner_id
		,@in_vchOwnerCode AS owner_code
	RETURN;
		
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
