CREATE PROCEDURE [dbo].[usp_api_validate_blind_pick_parent_lpn]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		NVARCHAR(25) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL, 
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchPickRule			NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------------
	-- Validate location
	--------------------------------------------------
	IF (((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION'  AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			----------------------------------------------------
			-- ตรวจสอบว่ามี Item อยู่ใน Location ที่เลือกใน Inventory?
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id
							FROM v_wms_inventory_for_blind_pick 
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id =  @in_vchOwnerID 
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND wh_item_master_id =  @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID 
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,''))
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_FOR_PICK'
				GOTO EXIT_LABEL;
			END
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_blind_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @in_vchInvStatusID
			AND location_id = @in_vchLocationID
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_blind_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @in_vchInvStatusID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,''))
				BEGIN
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END
		END
	
	SET @out_vchNextScreen = 'LPN'
	RETURN;
	---------------------------------------------------
	-- Exit the Process
	---------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
