/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchInboundOrderNumber VARCHAR(50)	= NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER	= NULL,
	@in_vchOwnerCode		NVARCHAR(40)= NULL,
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER,
	@in_vchLocationID		UNIQUEIDENTIFIER	= NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchReceiptMode		NVARCHAR(25) = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		NVARCHAR(50) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_dtMFGDate			DATE = NULL, 
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100)= NULL,
	@in_vchAttribute2		NVARCHAR(100)= NULL,
	@in_vchAttribute3		NVARCHAR(100)= NULL,
	@in_vchAttribute4		NVARCHAR(100)= NULL,
	@in_vchAttribute5		NVARCHAR(100)= NULL,
	@in_vchUomPrompt		NVARCHAR(40) = NULL,
	@in_fltQuantity			FLOAT,
 	@in_vchOrderType		NVARCHAR(30) = NULL,
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount			    INT,
			@Round					INT,
			@v_vchLPNControl		NVARCHAR(5) = NULL,
			@v_vchInvLocation	    NVARCHAR(50) = NULL,
			@v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber		NVARCHAR(50)  = NULL,
			@v_vchItemDesc			NVARCHAR(200)= NULL,
			@v_vchBaseUomPrompt		NVARCHAR(40) = NULL,
			@v_fltQuantityReceive	FLOAT = 0,
			@v_intItemShelfLife		INT,
			@v_dtExpDate			DATETIME,
			@v_vchLotControl		VARCHAR(5) = NULL,
			@in_vchExpDateControl	VARCHAR(5) = NULL,
			@v_vchSNControl			VARCHAR(5) = NULL,
			@v_vchAttribute1Control VARCHAR(5) = NULL,
			@v_vchAttribute2Control VARCHAR(5) = NULL,
			@v_vchAttribute3Control VARCHAR(5) = NULL,
			@v_vchAttribute4Control VARCHAR(5) = NULL,
			@v_vchAttribute5Control VARCHAR(5) = NULL,
			@v_vchItemIsActive		VARCHAR(3) = NULL,
			@v_vchGrade				NVARCHAR(50) = NULL

	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	----------------------------------------------------
	-- ถ้าจะใช้ 2D ต้องไม่ให้เลือก Receipt Mode
	----------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchErrorCode = 'INFO-ALLOW-SELECT-RECEIPT-MODE'
			GOTO EXIT_LABEL;
		END

	IF @in_vchLocationID IS NULL
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
			RETURN;
		END 
	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (ISNULL(@in_vchItemNumber,'') = '')
		BEGIN
			--ถ้าไม่ได้ส่ง Item มาต้อง Return ให้ใส่ Item ก่อน
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			RETURN;
		END

	SET @v_vchItemMasterID = NULL
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		 , @v_vchItemNumber = item.item_number
		 , @v_intItemShelfLife = item.days_to_expire
		 , @v_vchItemDesc = item.description
		 , @v_vchLotControl = item.lot_control
		 , @in_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchBaseUomPrompt = uom.uom_prompt
		 , @v_vchItemIsActive = item.is_active
		 , @v_vchGrade = item.grade
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom on item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	----------------------------------------------------
	-- Validate Warehouse Item
	----------------------------------------------------	
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID AND wh_master_id = @in_vchWhMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'WHAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	----------------------------------------------------
	--2023-09-19 CR for AGC : Check Item in Order > 1 Order 1 Item
	----------------------------------------------------
	IF EXISTS (SELECT 1 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id <> @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_SAME_IN_ORDER'
			GOTO EXIT_LABEL;
		END
		
	----------------------------------------------------
	-- Get Qty Order, Receipt, Remain in Plan
	----------------------------------------------------
	SELECT @v_fltQuantityReceive = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round) 
	FROM t_wms_inbound_detail ibDT 
	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.wh_item_master_id = @v_vchWhItemMasterID

	----------------------------------------------------
	-- ถ้าจะใช้ 2D ต้องไม่ให้เลือก ITEM STATUS และต้องกำหนด Status
	----------------------------------------------------
	IF @in_vchInvStatusID IS NULL
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			GOTO NEXT_SCREEN;
		END

	IF (@v_vchLotControl = 'FULL')
		BEGIN
			IF ISNULL(@in_vchLotNumber,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง LOT มาต้อง Return ให้ใส่ LOT ก่อน
					SET @out_vchNextScreen = 'LOT_NUMBER'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN 
			IF @in_vchLotNumber <> ''
				BEGIN
					SET @out_vchErrorCode = 'LOT_NUMBER_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@in_vchExpDateControl = 'FULL')
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง EXPIRY_DATE มาต้อง Return ให้ใส่ EXPIRY_DATE ก่อน
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			IF @in_vchExpiryDate <> ''
				BEGIN
					SET @out_vchErrorCode = 'EXPIRY_DATE_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute1Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute1,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE1 มาต้อง Return ให้ใส่ ATTRIBUTE1 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE1'
					GOTO NEXT_SCREEN;
				END 
		END
	ELSE
		BEGIN
			IF @in_vchAttribute1 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE1_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute2Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute2,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE2 มาต้อง Return ให้ใส่ ATTRIBUTE2 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE2'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute2 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE2_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute3Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute3,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE3 มาต้อง Return ให้ใส่ ATTRIBUTE3 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE3'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute3 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE3_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute4Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute4,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE4 มาต้อง Return ให้ใส่ ATTRIBUTE4 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE4'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute4 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE4_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute5Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute5,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE5 มาต้อง Return ให้ใส่ ATTRIBUTE5 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE5'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN 
			IF @in_vchAttribute5 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE5_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			SET @in_vchSerialNumber = ''
		END

	IF @v_vchSNControl = 'NONE' 
		BEGIN
			IF @in_vchReceiptMode = 'BY EACH' 
				BEGIN
					SET @in_fltQuantity = 1;
					GOTO SAVE_TRANS; 
				END
			ELSE	
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
		END


	--------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchWhItemMasterID		AS wh_item_master_id
		, @v_vchItemMasterID		AS item_master_id
		, @v_vchItemNumber			AS item_number
		, @v_vchItemDesc			AS item_description
		, @v_vchLotControl			AS lot_control
		, @in_vchExpDateControl		AS expiry_date_control
		, @v_vchSNControl			AS sn_control
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control 
		, @in_vchInvStatusID		AS inventory_status_id
		, @in_vchInvStatus			AS inv_status
		, @v_dtExpDate				AS expiry_date
		, @v_vchBaseUomPrompt		AS uom_prompt
		, ISNULL(@v_intItemShelfLife,0) AS item_shelf_life
		, @v_fltQuantityReceive		AS quantity_receive 
		, @in_fltQuantity			AS display_default_qty
		, @in_vchSerialNumber		AS serial_number
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
		, @in_vchInvStatusID		AS inventory_status_id
		, @in_vchInvStatus			AS inv_status
		, @in_vchAttribute1			AS attribute1
	
	RETURN;

SAVE_TRANS:
		--Save Transaction
		EXEC usp_blind_receipt_update_qty @in_vchApplicationID		 = @in_vchApplicationID	  
											,@in_vchDeviceID		 = @in_vchDeviceID					
											,@in_vchUserID			 = @in_vchUserID			 
											,@in_vchWhMasterID		 = @in_vchWhMasterID		 
											,@in_vchInboundMasterID  = @in_vchInboundMasterID		
											,@in_vchReceiptHeaderID  = @in_vchReceiptHeaderID		
											,@in_vchLocationID		 = @in_vchLocationID		 
											,@in_vchParentLPN		 = @in_vchParentLPN		 
											,@in_vchLPN				 = @in_vchLPN					
											,@in_vchInvStatusID		 = @in_vchInvStatusID				
											,@in_vchWhItemMasterID	 = @v_vchWhItemMasterID	 
											,@in_fltQuantity		 = @in_fltQuantity				
											,@in_vchUomPrompt		 = @in_vchUomPrompt		 
											,@in_vchLotNumber		 = @in_vchLotNumber		 
											,@in_vchExpiryDate		 = @in_vchExpiryDate		 
											,@in_vchSerialNumber	 = @in_vchSerialNumber			
											,@in_vchAttribute1		 = @in_vchAttribute1		 
											,@in_vchAttribute2		 = @in_vchAttribute2		 
											,@in_vchAttribute3		 = @in_vchAttribute3		 
											,@in_vchAttribute4		 = @in_vchAttribute4		 
											,@in_vchAttribute5		 = @in_vchAttribute5		 
											,@in_dtMfgDate			 = @in_dtMfgDate			 
											,@out_ErrorCode			 = @out_vchErrorCode OUTPUT
											,@out_ErrorMessage		 = @out_vchErrorMsg OUTPUT											
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
			 
		
		IF @in_vchReceiptMode = 'BY EACH' OR @v_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

		FINAL_SCREEN:
		EXEC usp_api_validate_blind_receipt_final_screen @in_vchWhMasterID		= @in_vchWhMasterID	
														,@in_vchInboundMasterID	= @in_vchInboundMasterID	
														,@in_vchLocationID		= @in_vchLocationID			
														,@in_vchWhItemMasterID	= @V_vchWhItemMasterID
														,@in_vchSNControl       = @v_vchSNControl
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
		RETURN;

	--------------------------------------------------------
	-- Exit the Process
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_attribute1]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchLocalID			 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchReceiptMode		 NVARCHAR(25) = NULL, 
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(20)  = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		 NVARCHAR(100)  = NULL, 
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchSNControl	     VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT 
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			RETURN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END	
	IF (@in_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					RETURN;
				END
		END 

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
