/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_final_screen]
(
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER, 
	@in_vchReceiptMode	    NVARCHAR(25)  = NULL,
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchWhItemMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchSNControl		VARCHAR(5) = NULL,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @v_nCount			INT
	DECLARE @v_fltInvQty		FLOAT
	DECLARE @v_fltPalletSizing	FLOAT	--หมายถึง fifo_window ที่ item master table
	
	--------------------------------------------------------------------
	-- Check Pallet Sizing = fifo_window ที่ Item Master
	--------------------------------------------------------------------
	IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active = 'YES') = 'YES')
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_PALLET_SIZING' AND is_active = 'YES') = 'YES')
				BEGIN
					SELECT TOP 1 @v_fltInvQty = SUM(inv.quantity)
						,@v_fltPalletSizing = ISNULL(item.fifo_window,0)
					FROM t_wms_inventory inv
					INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
					INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id 
					WHERE inv.wh_master_id = @in_vchWhMasterID
					AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
					AND inv.wh_item_master_id = @in_vchWhItemMasterID
					GROUP BY item.fifo_window

					IF (@v_fltPalletSizing = 0 OR @v_fltPalletSizing = '') OR @v_fltInvQty = @v_fltPalletSizing
						BEGIN
							SET @out_vchNextScreen = 'LPN'
							RETURN;
						END
				END 
		END
	IF @in_vchSNControl = 'FULL'
		SET @out_vchNextScreen = 'SERIAL_NUMBER'
	ELSE
		SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_item_number]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLpn		NVARCHAR(25)  = NULL,
	@in_vchLpn				NVARCHAR(25)  = NULL, 
	@in_vchReceiptMode		NVARCHAR(25) = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@out_vchItemMasterID	UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchWhItemMasterID  UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount				INT
	DECLARE @Round					INT
	DECLARE @v_vchItemNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_intItemShelfLife		INT
	DECLARE @v_dtExpDate			DATETIME
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchSnControl			VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL 
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityReceipt	FLOAT = 0 

	SELECT TOP 1 @Round = value from t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'

	----------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	----------------------------------------------------
	SELECT TOP 1 @out_vchItemMasterID = item.item_master_id
		 , @v_vchItemNumber = item.item_number
		 , @v_intItemShelfLife = item.days_to_expire
		 , @v_vchItemDesc = item.description
		 , @v_vchItemUomID = uom.item_uom_id
		 , @v_vchUomPrompt = uom.uom_prompt
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@out_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	----------------------------------------------------
	-- Validate Warehouse Item
	----------------------------------------------------	
	SELECT @out_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @out_vchItemMasterID AND wh_master_id = @in_vchWhMasterID
	IF (@out_vchWhItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'WHAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	----------------------------------------------------
	-- Get Qty Order, Receipt, Remain in Plan
	----------------------------------------------------
	SELECT @v_fltQuantityReceipt = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round) 
	FROM t_wms_inbound_detail ibDT 
	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.wh_item_master_id = @out_vchWhItemMasterID

	----------------------------------------------------
	-- ตรวจสอบ Lot Control
	----------------------------------------------------
	IF (@v_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchExpDateControl = 'FULL')
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'MFG_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES'
						BEGIN
							-----------------------------------------------------
							-- Use mfg date to calculate expiry date
							-----------------------------------------------------
							SELECT @v_dtExpDate = DATEADD(DAY,@V_intItemShelfLife,  GETDATE())
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'EXPIRY_DATE'
							GOTO NEXT_SCREEN;
						END
				END
		END
	IF @v_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END	
	IF (@v_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END 
		END
	
	-----------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------------
	NEXT_SCREEN:
	SELECT @out_vchWhItemMasterID   AS wh_item_master_id
		, @out_vchItemMasterID	  AS item_master_id
		, @v_vchItemNumber		  AS item_number
		, @v_vchItemDesc		  AS item_description
		, @v_dtExpDate			  AS expiry_date
		, @v_vchItemUomID		  AS item_uom_id
		, @v_vchUomPrompt		  AS uom_prompt
		, ISNULL(@v_intItemShelfLife,0) AS item_shelf_life
		, @v_vchLotControl		  AS lot_control
		, @v_vchExpDateControl	  AS expiry_date_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control 
		, @v_fltQuantityReceipt   AS quantity_receive
		, (CASE WHEN @v_vchSNControl = 'FULL' OR @out_vchNextScreen = 'FINAL_SCREEN' THEN 1 ELSE 0 END) AS qty
		 
	RETURN; 
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_item_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_item_status]
(
	@in_vchApplicationID VARCHAR(40)  = NULL,
	@in_vchInvStatus	 NVARCHAR(50) = NULL,	
	@in_vchLocalID		 VARCHAR(40)  = NULL,
	@out_vchErrorCode	 VARCHAR(50)  OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID UNIQUEIDENTIFIER

	SELECT @v_vchInvStatusID = inventory_status_id, @in_vchInvStatus = inv_status 
	FROM t_wms_inventory_status
	WHERE inv_status = @in_vchInvStatus 
	AND is_active = 'YES'
	IF @v_vchInvStatusID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'INFO-ITEM-STATUS-INVALID'
		GOTO EXIT_LABEL;
	END

	-- กำหนดให้ Scan item number ทั้ง by each และ จำนวน แล้วไปแยกกันตอน Validate Serial
	SET @out_vchNextScreen= 'ITEM_NUMBER'
	SELECT @v_vchInvStatusID AS inventory_status_id
		,@in_vchInvStatus AS inv_status
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOrderType		NVARCHAR(30) = NULL,
	@in_vchLocation			NVARCHAR(50)= NULL,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl	VARCHAR(5)
	DECLARE @v_vchInvStatusID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus		NVARCHAR(50)= NULL
	
	--------------------------------------------------------------------
	-- Check Location in master data and loc type = RSTG
	--------------------------------------------------------------------
	SELECT @v_vchLocationID = location_id 
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location
	WHERE location = @in_vchLocation
	AND wh_master_id = @in_vchWhMasterID
	AND is_active = 'YES'
	AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-RSTG-NOT-EXIST'
			GOTO EXIT_LABEL
		END 
	 
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIPT_MODE'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			-------------------------------------------------------------
			-- Check Rule 'select item status'
			------------------------------------------------------------- 
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES' 
				OR (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_ALLOW_DEFAULT_STATUS_BLIND_RECEIPT' AND is_active = 'YES') = 'NO'
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
					GOTO NEXT_SCREEN;
				END

			IF @v_vchInvStatusID IS NULL
				BEGIN
					SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
						,@v_vchInvStatus = inv_status
					FROM t_wms_inventory_status
					WHERE inv_status = (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_STATUS_INBOUND_DEFAULT' AND is_active = 'YES')
					AND is_active = 'YES'
					IF @v_vchInvStatusID IS NULL
						BEGIN
							SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND'
							GOTO EXIT_LABEL;
						END
				END

			SET @out_vchNextScreen = 'ITEM_NUMBER'; 
		END 

	NEXT_SCREEN:
		SELECT @v_vchLocationID AS location_id 
			,@v_vchInvStatusID AS inventory_status_id
			,@v_vchInvStatus AS inv_status
		RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
