/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_lot_number]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchLocalID			 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchReceiptMode		 NVARCHAR(25) = NULL, 
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_intItemShelfLife     INT = 0,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpDateControl    VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchSNControl	     VARCHAR(5) = NULL,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_dtExpDate DATETIME --เมื่อคำนวณ MFG + Item_shelf_life
	IF (@in_vchExpDateControl = 'FULL')
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'MFG_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES'
						BEGIN
							-----------------------------------------------------
							-- Use mfg date to calculate expiry date
							-----------------------------------------------------
							SELECT @v_dtExpDate = DATEADD(DAY,@in_intItemShelfLife,  GETDATE())
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'EXPIRY_DATE'
							GOTO NEXT_SCREEN;
						END
				END
		END
	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END	
	IF (@in_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END 
		END

	NEXT_SCREEN:
		SELECT @v_dtExpDate as expiry_date
	RETURN;
-----------------------------------------------------------------------------------
-- Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF (@out_vchErrorCode IS NOT NULL)
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLpn		NVARCHAR(25)  = NULL,
	@in_vchLpn				NVARCHAR(25)  = NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvLocationID	UNIQUEIDENTIFIER  = NULL
	DECLARE @v_vchInvStatusID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus		NVARCHAR(50)= NULL

	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนไม่มีอยู่ที่ Location อื่น?
	--------------------------------------------------------------------
	SELECT @v_vchInvLocationID = inv.location_id
	FROM t_wms_inventory inv
	WHERE inv.lpn = @in_vchLpn
	AND inv.wh_master_id = @in_vchWhMasterID

	IF (@v_vchInvLocationID IS NOT NULL AND @v_vchInvLocationID <> @in_vchLocationID)
		BEGIN
			--LPN ไม่ได้อยู่ใน Location ที่ Scan
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-LPN-IN-LOCATION'
			GOTO EXIT_LABEL
		END

	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIPT_MODE'
		END
	ELSE
		BEGIN
			-------------------------------------------------------------
			-- Check Rule 'select item status'
			-------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES' 
				OR (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_ALLOW_DEFAULT_STATUS_BLIND_RECEIPT' AND is_active = 'YES') = 'NO'
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
					GOTO NEXT_SCREEN;
				END

			SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
				,@v_vchInvStatus = inv_status
			FROM t_wms_inventory_status
			WHERE inv_status = (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_STATUS_INBOUND_DEFAULT' AND is_active = 'YES')
			AND is_active = 'YES'
			IF @v_vchInvStatusID IS NULL
				BEGIN
					SET @out_vchErrorCode = 'STATUS_NOT_FOUND'
					GOTO EXIT_LABEL;
				END

			SET @out_vchNextScreen = 'ITEM_NUMBER';
		END
	
	NEXT_SCREEN:
		SELECT @v_vchInvStatusID AS inventory_status_id
			,@v_vchInvStatus AS inv_status 

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_mfg_date]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_mfg_date]
(
	@in_vchApplicationID     VARCHAR(40) = NULL,	 
	@in_vchLocalID		     VARCHAR(40) = NULL,	 
	@in_vchInboundMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchReceiptMode		 NVARCHAR(25) = NULL,	 
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_dtMFGDate			 DATE = NULL,
	@in_intItemShelfLife	 INT = 0,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL, 
	@out_vchErrorCode	     VARCHAR(50)  OUTPUT, 
	@out_vchErrorMsg	     NVARCHAR(500)OUTPUT, 
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	 -- This store reference with:  
	 DECLARE @v_dtExpDate DATETIME --เมื่อคำนวณ MFG + Item_shelf_life
	 DECLARE @v_vchExpiryDate VARCHAR(10) = '' 
	  
	--------------------------------------------------------------------
	-- Use Mfg.Date to calculate Exp. Date
	--------------------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'NO'
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'	
			RETURN;
		END 
		 
	--------------------------------------------------------------------
	-- กำหนดค่า MFG Date 
	-- 1. ถ้าไม่ส่ง MFG Date >> GetDate
	--------------------------------------------------------------------
	IF (@in_dtMFGDate IS NULL)
		BEGIN
			SET @in_dtMFGDate = GETDATE()
		END 
		 
	-----------------------------------------------------
	-- Use mfg date to calculate expiry date
	-- ส่งกลับหน้าจอเพื่อให้แทนค่า Expiry Date
	-----------------------------------------------------
	SET @v_vchExpiryDate = CONVERT(VARCHAR(8), DATEADD(DAY,ISNULL(@in_intItemShelfLife,0), @in_dtMFGDate),112)
			
	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END	
	IF (@in_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END 
		END
	
	 NEXT_SCREEN:
	 SELECT @v_vchExpiryDate AS expiry_date

	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_order_number]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchWhID			 NVARCHAR(25),
	@in_vchOwnerID		 UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(40) = NULL,
	@out_vchErrorCode	 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount INT = 0
	DECLARE @v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchReceiptHeaderID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchReceiptNumber		VARCHAR(50) = NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10) = NULL
	DECLARE @v_vchOrderType			NVARCHAR(30) = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(50) = NULL
	IF @in_vchOwnerID IS NULL
		BEGIN
			SELECT TOP 1 @in_vchOwnerID = own.owner_id, @v_vchOwnerCode = own.owner_code
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
		END

	SELECT @v_vchInboundMasterID = inbound_order_master_id 
		, @v_vchOrderStatus = order_status
		, @in_vchOwnerID = owner_id
		, @v_vchOwnerCode = owner_code
	FROM t_wms_inbound_master WITH (NOLOCK)
	WHERE inbound_order_number = @in_vchInboundOrderNumber
	AND wh_master_id = @in_vchWhMasterID
 	IF @v_vchInboundMasterID IS NULL
		BEGIN
			SELECT TOP 1 @v_vchOrderType = value from t_wms_rule WHERE rule_code = 'BLIND_RECEIPT_ORDER_TYPE' AND is_active = 'YES'
			SELECT TOP 1 @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'

			SET @v_vchInboundMasterID = NEWID();
			INSERT INTO [dbo].[t_wms_inbound_master]
				([inbound_order_master_id]
				,[wh_master_id]
				,[wh_id]
				,[inbound_order_number]
				,[owner_id]
				,[owner_code]
				,[order_type]
				,[order_status]          
				,[create_by]
				,[create_date])
			VALUES
				(@v_vchInboundMasterID
				,@in_vchWhMasterID
				,@in_vchWhID
				,@in_vchInboundOrderNumber
				,@in_vchOwnerID
				,@v_vchOwnerCode
				,@v_vchOrderType
				,'OPEN'
				,@in_vchUserID
				,GETDATE()) 			
		END
	ELSE
		BEGIN
			IF @v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
			BEGIN
				--Status ไม่ถูกต้อง
				SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-STATUS'
				GOTO EXIT_LABEL
			END
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @in_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	--------------------------------------------------------------------
	-- Check Partial Receipt Number
	--------------------------------------------------------------------
	SELECT @v_nCount = COUNT(receipt_header_id)
	FROM t_wms_receipt_header 
	WHERE inbound_order_master_id = @v_vchInboundMasterID
	AND receipt_status = 'OPEN'

	IF @v_nCount > 1
		BEGIN
			SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
		END
	ELSE IF @v_nCount = 1
		BEGIN
			SELECT @v_vchReceiptHeaderID = receipt_header_id
				,@v_vchReceiptNumber = receipt_number
			FROM t_wms_receipt_header 
			WHERE inbound_order_master_id = @v_vchInboundMasterID
			AND receipt_status = 'OPEN'

			SET @out_vchNextScreen = 'LOCATION'
		END
	ELSE
		BEGIN 
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_GENERATE_RECEIPT_NUMBER' AND is_active = 'YES') = 'YES'
				BEGIN
					--Create Partial Receipt Number
					EXEC usp_generate_receipt_number @in_vchUserID			    = @in_vchUserID
													 ,@in_vchWhMasterID		    = @in_vchWhMasterID
													 ,@in_vchInboundMasterID	= @v_vchInboundMasterID
													 ,@out_vchReceiptHeaderID	= @v_vchReceiptHeaderID OUTPUT
													 ,@out_vchReceiptNumber	    = @v_vchReceiptNumber OUTPUT
					SET @out_vchNextScreen = 'LOCATION'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
				END
		END
		
	-----------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInboundMasterID AS inbound_order_master_id
		,@in_vchInboundOrderNumber AS inbound_order_number
		,@v_vchReceiptHeaderID	 AS receipt_header_id
		,@v_vchReceiptNumber	 AS receipt_number 
		,@in_vchOwnerID			as owner_id
		,@v_vchOwnerCode		as owner_code
	RETURN;
		
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_owner]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_owner]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40), 
	@in_vchUserID		 NVARCHAR(25), 
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchOwnerCode	 NVARCHAR(40) = NULL,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOwnerID	  UNIQUEIDENTIFIER = NULL
	-----------------------------------------------	
	-- Validate owner master
	-----------------------------------------------
	SELECT @v_vchOwnerID = own.owner_id
		, @in_vchOwnerCode = own.owner_code
	FROM t_wms_owner_user ownUser
	INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
	WHERE own.is_active = 'YES'
	AND own.owner_code = @in_vchOwnerCode
	AND ownUser.user_id = @in_vchUserID

	IF (@v_vchOwnerID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'INBOUND_ORDER'
	SELECT @v_vchOwnerID AS owner_id
		,@in_vchOwnerCode AS owner_code
	RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
