/****** Object:  StoredProcedure [dbo].[usp_api_validate_blind_receipt_parent_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_blind_receipt_parent_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLpn		NVARCHAR(25)  = NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvLocationID	UNIQUEIDENTIFIER

	--------------------------------------------------------------------
	-- ตรวจสอบ PARENT LPN ที่สแกนไม่มีอยู่ที่ Location อื่น?
	--------------------------------------------------------------------
	SELECT @v_vchInvLocationID = inv.location_id
	FROM t_wms_inventory inv 
	WHERE inv.parent_lpn = @in_vchParentLpn
	AND inv.wh_master_id = @in_vchWhMasterID

	IF (@v_vchInvLocationID IS NOT NULL AND @v_vchInvLocationID <> @in_vchLocationID)
		BEGIN
			--PARENT LPN ไม่ได้อยู่ใน Location ที่ Scan
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-PARENT-IN-LOCATION'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LPN'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
