							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,''))
				BEGIN
					-----------------------------------------------
					-- Check Wh rule count new LPN
					-----------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_COUNT_NEW_LPN' AND is_active = 'YES') = 'NO')
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST-IN-INVENTORY'
							GOTO EXIT_LABEL;
						END
				END
