/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_id]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_id]
(
	@in_vchApplicationID VARCHAR(40) = NULL,
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchCountID		 VARCHAR(50) = NULL,
	@in_vchLocalID		 VARCHAR(40) = NULL,
	@in_vchUserID		 NVARCHAR(25),
	@out_vchErrorCode	 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchCountMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchCountStatus	NVARCHAR(10) = NULL,
			@v_vchOwnerID		UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode		NVARCHAR(50) = NULL
			 
	SELECT @v_vchCountMasterID = planMS.count_master_id
		,@v_vchCountStatus = planMS.count_status
		,@v_vchOwnerID = planMS.owner_id
		,@v_vchOwnerCode = own.owner_code
	FROM t_wms_count_plan_master planMS
	INNER JOIN t_wms_owner own ON planMS.owner_id = own.owner_id
	WHERE planMS.count_id = @in_vchCountID
	AND planMS.wh_master_id = @in_vchWhMasterID
	
	IF @v_vchCountMasterID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'INFO-COUNT-ID-NOT-EXIST'
		GOTO EXIT_LABEL;
	END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF @v_vchCountStatus NOT IN ('OPEN','IN PROCESS')
	BEGIN
		SET @out_vchErrorCode = 'COUNT_IS_CLOSE' 
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchCountID,'@param2','@param3','@param4','@param5')
		RETURN;
	END

	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_COUNT_MODE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'COUNT_MODE'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
		END

	SELECT @v_vchCountMasterID AS count_master_id
		, @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code 
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_item_number]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchCountMode		NVARCHAR(50) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40) = NULL,
	@out_vchItemMasterID	UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchWhItemMasterID  UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchErrorCode		VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	
	DECLARE @v_vchItemDesc			NVARCHAR(200)= NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSnControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	-------------------------------------------------------------------- 
	SELECT TOP 1 @out_vchItemMasterID = item.item_master_id
		 , @in_vchItemNumber = item.item_number 
		 , @v_vchItemDesc = item.description
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpiryDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchUomPrompt = uom_prompt
		 , @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@out_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	----------------------------------------------------
	-- Validate Warehouse Item
	----------------------------------------------------
	SET @out_vchWhItemMasterID = NULL
	SELECT @out_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @out_vchItemMasterID AND wh_master_id = @in_vchWhMasterID
	IF @out_vchWhItemMasterID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
		GOTO EXIT_LABEL;
	END 

	----------------------------------------------------------
	-- Check Lot Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl		= @v_vchLotControl	
								,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
								,@in_vchAttribute1Control	= @v_vchAttribute1Control
								,@in_vchAttribute2Control	= @v_vchAttribute2Control
								,@in_vchAttribute3Control	= @v_vchAttribute3Control
								,@in_vchAttribute4Control	= @v_vchAttribute4Control
								,@in_vchAttribute5Control	= @v_vchAttribute5Control
								,@in_vchSNControl			= @v_vchSnControl
								,@in_vchIsCheckLot			= 'YES'
								,@in_vchIsCheckExpiryDate	= 'NO'	
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@in_vchItemMode			= @in_vchCountMode
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
	
	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	SELECT @out_vchWhItemMasterID   AS wh_item_master_id
		, @out_vchItemMasterID	  AS item_master_id
		, @in_vchItemNumber		  AS item_number 
		, @v_vchItemDesc		  AS item_description
		, @v_vchUomPrompt		  AS uom_prompt
		, @v_vchLotControl		  AS lot_control
		, @v_vchExpiryDateControl AS expiry_date_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, (CASE WHEN @v_vchSNControl = 'FULL' OR @out_vchNextScreen = 'FINAL_SCREEN' THEN 1 ELSE 0 END) AS qty
	
	RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_item_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_item_status]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  VARCHAR(40) = NULL,
	@in_vchCountMasterID  UNIQUEIDENTIFIER = NULL, 
	@in_vchLocationID	  UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus	  NVARCHAR(50) = NULL,	
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	IF @in_vchItemStatus NOT IN (SELECT inv_status FROM t_wms_inventory_status WHERE is_active = 'YES')
	BEGIN
		SET @out_vchErrorCode = 'INFO-ITEM-STATUS-INVALID'
		GOTO EXIT_LABEL;
	END

	IF (SELECT TOP 1 lpn_controlled FROM t_wms_location where location_id = @in_vchLocationID AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'LPN'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'
		END
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_location]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchLocation		  NVARCHAR(50) = NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL,
			@v_vchLPNControlled	VARCHAR(3) = NULL,
			@v_vchInvItemStatusID UNIQUEIDENTIFIER= NULL,
			@v_vchInvItemStatus nvarchar(50)


	-----------------------------------------------	
	-- Validate Location in master table
	-----------------------------------------------
	SELECT @v_vchLocationID = location_id
		, @v_vchLPNControlled = lpn_controlled
	FROM t_wms_location
	WHERE wh_master_id = @in_vchWhMasterID
	AND location = @in_vchLocation
	AND is_active = 'YES'
	IF (@v_vchLocationID IS NULL)
	BEGIN
		SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
		GOTO EXIT_LABEL;
	END 
	
	-----------------------------------------------	
	-- Validate Location in count plan
	-- ถ้าเป็น PHYSICAL ไม่ต้อง check location in plan
	-----------------------------------------------
	IF (SELECT TOP 1 count_plan_type FROM t_wms_count_plan_master WHERE wh_master_id = @in_vchWhMasterID AND count_master_id = @in_vchCountMasterID) = 'CYCLE'
		BEGIN
			IF NOT EXISTS (SELECT location_id FROM t_wms_count_plan_detail WHERE count_master_id = @in_vchCountMasterID AND location_id = @v_vchLocationID)
				BEGIN
					SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST-IN-PLAN'
					GOTO EXIT_LABEL;
				END
		END

	IF (SELECT COUNT(DISTINCT inventory_status_id) FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @v_vchLocationID) = 1
		BEGIN
			SELECT TOP 1  @v_vchInvItemStatusID = inv.inventory_status_id
				,@v_vchInvItemStatus = invST.inv_status
			FROM t_wms_inventory inv
			INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
			WHERE inv.wh_master_id = @in_vchWhMasterID 
			AND inv.location_id = @v_vchLocationID
			IF @v_vchLPNControlled = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER'
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'	
		END



	SELECT @v_vchLocationID AS location_id
		,@v_vchInvItemStatusID AS inv_status_id
		,@v_vchInvItemStatus AS item_status

	-----------------------------------------------
	-- Exit the Process
	-----------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_lot_number]
(
	@in_vchApplicationID	 VARCHAR(40)   = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchCountMode		 NVARCHAR(50) = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
 	@in_vchLPN				 NVARCHAR(25)	   = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchLotNumber		 NVARCHAR(50)  = NULL,
	@in_vchExpiryDateControl VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchSnControl		 VARCHAR(5) = NULL,
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@out_vchErrorCode		 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	----------------------------------------------------
	-- Validate in count plan		
	----------------------------------------------------
	IF NOT EXISTS (SELECT lot FROM t_wms_count_plan_detail
					WHERE count_master_id = @in_vchCountMasterID
					AND location_id = @in_vchLocationID
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID 
					AND ISNULL(lot,'') = ISNULL(@in_vchLotNumber,''))
		BEGIN
			----------------------------------------------------
			-- Validate in inventory
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
 							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
				BEGIN
					-----------------------------------------------
					-- Check Wh rule count new LPN
					-----------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_COUNT_NEW_LPN' AND is_active = 'YES') = 'NO')
						BEGIN
							SET @out_vchErrorCode = 'INFO-LOT-NOT-EXIST-IN-INVENTORY'
							GOTO EXIT_LABEL;
						END
				END
		END
		 
	----------------------------------------------------------
	-- Check ExpiryDate Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl		= NULL
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSnControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'YES'	
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@in_vchItemMode			= @in_vchCountMode
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
	RETURN;
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_lpn]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID	  UNIQUEIDENTIFIER = NULL,
	@in_vchLPN			  NVARCHAR(25) = NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @v_nCount	INT

	-----------------------------------------------	
	-- Validate LPN in inventory table
	-----------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND ISNULL(lpn,'') = @in_vchLPN)
		BEGIN
			-----------------------------------------------
			-- Check Wh rule count new LPN
			-----------------------------------------------
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_COUNT_NEW_LPN' AND is_active = 'YES') = 'NO')
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END 

	-----------------------------------------------------------------------
	-- SET Next Screen ถ้าพบ LPN ถ้าไม่พบ LPN (กรณีไม่พบ Rule Count new lpn = yes)
	-----------------------------------------------------------------------
	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;
		 
	-----------------------------------------------
	-- Exit the Process
	-----------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_lpn_count_id]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_lpn_count_id]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountID		  VARCHAR(50) = NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@in_vchUserID		  NVARCHAR(25),
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchCountMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchCountStatus	NVARCHAR(10) = NULL,
			@v_vchOwnerID		UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode		NVARCHAR(50) = NULL
			 
	SELECT @v_vchCountMasterID = planMS.count_master_id
		,@v_vchCountStatus = planMS.count_status
		,@v_vchOwnerID = planMS.owner_id
		,@v_vchOwnerCode = own.owner_code
	FROM t_wms_count_plan_master planMS
	INNER JOIN t_wms_owner own ON planMS.owner_id = own.owner_id
	WHERE planMS.count_id = @in_vchCountID
	AND planMS.wh_master_id = @in_vchWhMasterID
	
	IF @v_vchCountMasterID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'INFO-COUNT-ID-NOT-EXIST'
		GOTO EXIT_LABEL;
	END
	
	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF @v_vchCountStatus NOT IN ('OPEN','IN PROCESS')
	BEGIN
		SET @out_vchErrorCode = 'COUNT_IS_CLOSE' 
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchCountID,'@param2','@param3','@param4','@param5')
		RETURN;
	END
 
	SET @out_vchNextScreen = 'LOCATION'
	SELECT @v_vchCountMasterID AS count_master_id
		, @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code 
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_lpn_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_lpn_final_screen]
(
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID		  UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID	  UNIQUEIDENTIFIER = NULL,
	@in_vchLocation		  NVARCHAR(50)  = NULL,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF EXISTS (SELECT count_plan_detail_id FROM t_wms_count_plan_detail WHERE count_master_id = @in_vchCountMasterID AND ISNULL(count_qty,9) = 0)
		SET @out_vchNextScreen = 'LOCATION';
	ELSE
		SET @out_vchNextScreen = 'COUNT_ID';
END
