CREATE PROCEDURE [dbo].[usp_api_validate_count_mode]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountID		  VARCHAR(50) = NULL,
	@in_vchCountMode	  NVARCHAR(50) = NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 			 
	IF @in_vchCountMode NOT IN (SELECT value_member FROM t_com_combobox_item WHERE group_name = 'count_mode' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-COUNT-MODE-INVALID'
			GOTO EXIT_LABEL;
		END
 
	SET @out_vchNextScreen = 'LOCATION'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_count_serial_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_count_serial_number]
(
	@in_vchApplicationID  VARCHAR(40)   = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchCountMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID		  UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID	  UNIQUEIDENTIFIER = NULL, 
 	@in_vchLPN			  NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID UNIQUEIDENTIFIER = NULL, 
	@in_vchLotNumber	  NVARCHAR(50)  = NULL,
	@in_vchExpiryDate	  NVARCHAR(50)	= NULL,
	@in_vchAttribute1	  NVARCHAR(100)	= NULL,
	@in_vchAttribute2	  NVARCHAR(100)	= NULL,
	@in_vchAttribute3	  NVARCHAR(100) = NULL,
	@in_vchAttribute4	  NVARCHAR(100) = NULL,
	@in_vchAttribute5	  NVARCHAR(100) = NULL,
	@in_vchSerialNumber	  NVARCHAR(50)  = NULL,
	@in_vchLocalID		  VARCHAR(40)   = NULL,
	@out_vchErrorCode	  VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;  
	IF NOT EXISTS (SELECT attribute5 FROM t_wms_count_plan_detail
					WHERE count_master_id = @in_vchCountMasterID
					AND location_id = @in_vchLocationID
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID 
					AND ISNULL(lot,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
		BEGIN
			----------------------------------------------------
			-- Validate in inventory
			----------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
 							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
				BEGIN
					-----------------------------------------------
					-- Check Wh rule count new LPN
					-----------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_COUNT_NEW_LPN' AND is_active = 'YES') = 'NO')
						BEGIN
							SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-INVENTORY'
							GOTO EXIT_LABEL;
						END
				END
		END  

	-------------------------------------------------
	-- Validate QTY and adjust
	-------------------------------------------------
	SET @out_vchNextScreen = 'FINAL_SCREEN'
	SELECT 1 AS qty
	RETURN;
	 
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_inventory_viewer]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_inventory_viewer]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInvViewerMode	NVARCHAR(50),
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchItemNumber		NVARCHAR(50), 
	@in_vchSerialNumber		NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	IF @in_vchControlName = 'LOCATION'
		BEGIN
			---------------------------------------------------- 
			-- Get LOCATION in Inventory						 
			---------------------------------------------------- 
			SELECT location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END) AS expiry_date
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, SUM(quantity) quantity
				, uom_prompt
			FROM v_wms_inventory_api_viewer
			WHERE wh_master_id = @in_vchWhMasterID
			AND location = ISNULL(@in_vchLocation,'')
			GROUP BY location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END)
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, uom_prompt
 			ORDER BY lpn, item_number

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END
	IF @in_vchControlName = 'PARENT_LPN'
		BEGIN
			------------------------------------------------------
			-- Get Parent LPN in Inventory
			------------------------------------------------------
			SELECT location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END) AS expiry_date
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, SUM(quantity) quantity
				, uom_prompt
			FROM v_wms_inventory_api_viewer
			WHERE wh_master_id = @in_vchWhMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			GROUP BY location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END)
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, uom_prompt
 			ORDER BY parent_lpn, lpn, item_number 

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-PARENT-LPN-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
 
			RETURN;
		END
	IF @in_vchControlName = 'LPN'
		BEGIN
			-----------------------------------------------------------------------------------
			-- Get LPN in Inventory
			-----------------------------------------------------------------------------------
			SELECT location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END) AS expiry_date
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, SUM(quantity) quantity
				, uom_prompt
			FROM v_wms_inventory_api_viewer
			WHERE wh_master_id = @in_vchWhMasterID
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			GROUP BY location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END)
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, uom_prompt
 			ORDER BY parent_lpn, lpn, item_number 

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
					GOTO EXIT_LABEL;
				END 
		END
	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			-----------------------------------------------------------------------------------
			-- Get Item Number in Inventory
			-----------------------------------------------------------------------------------
			SELECT inv.location
				, inv.parent_lpn
				, inv.lpn
				, inv.inv_status
				, inv.item_number 
				, inv.item_description
				, inv.owner_code          
				, inv.lot_number
				, (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,inv.expiry_date),103) END) AS expiry_date
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, inv.serial_number
				, SUM(inv.quantity) quantity
				, inv.uom_prompt
			FROM v_wms_inventory_api_viewer inv
			LEFT JOIN t_wms_item_crossref cref ON inv.item_master_id = cref.item_master_id 
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND (inv.item_number = @in_vchItemNumber OR inv.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
			GROUP BY inv.location
				, inv.parent_lpn
				, inv.lpn
				, inv.inv_status
				, inv.item_number 
				, inv.item_description
				, inv.owner_code          
				, inv.lot_number
				, (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,inv.expiry_date),103) END)
				, inv.attribute1
				, inv.attribute2
				, inv.attribute3
				, inv.attribute4
				, inv.attribute5
				, inv.serial_number
				, inv.uom_prompt
 			ORDER BY inv.parent_lpn, inv.lpn, inv.item_number 

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END
	IF @in_vchControlName = 'SERIAL_NUMBER'
		BEGIN
			-----------------------------------------------------------------------------------
			-- Get Serial Number in Inventory
			-----------------------------------------------------------------------------------
			SELECT location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END) AS expiry_date
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, SUM(quantity) quantity
				, uom_prompt
			FROM v_wms_inventory_api_viewer
			WHERE wh_master_id = @in_vchWhMasterID
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			GROUP BY location
				, parent_lpn
				, lpn
				, inv_status
				, item_number 
				, item_description
				, owner_code          
				, lot_number
				, (CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(VARCHAR,CONVERT(DATE,expiry_date),103) END)
				, attribute1
				, attribute2
				, attribute3
				, attribute4
				, attribute5
				, serial_number
				, uom_prompt
 			ORDER BY serial_number
			
			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END
	IF @in_vchControlName = 'SUMMARY_LPN'
		BEGIN
			-----------------------------------------------------------------------------------
			-- Get LPN in Inventory
			-----------------------------------------------------------------------------------
			SELECT loc.location
				, inv.lpn			
				, SUM(inv.quantity) AS summary_quantity 
			FROM t_wms_inventory inv
			inner join t_wms_location loc ON inv.location_id = loc.location_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'') 
			GROUP BY loc.location, inv.lpn

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END
	IF @in_vchControlName = 'SUMMARY_ITEM'
		BEGIN
			-----------------------------------------------------------------------------------
			-- Get LPN in Inventory
			-----------------------------------------------------------------------------------
			SELECT item.item_number
				, item.description AS item_description
				, SUM(inv.quantity) AS summary_quantity 
			FROM t_wms_inventory inv
			INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND item.item_number = @in_vchItemNumber
			GROUP BY item.item_number, item.description

			IF (@@ROWCOUNT > 0)
				BEGIN
					SET @out_vchNextScreen = 'VIEWER_SCREEN_INV'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchErrorCode = 'INFO-ITEM-NOT-EXIST'
					GOTO EXIT_LABEL;
				END
		END

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_inventory_viewer_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_inventory_viewer_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchInvViewerMode	NVARCHAR(50),
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchItemNumber		NVARCHAR(50), 
	@in_vchSerialNumber		NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchControlName,'') =  ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-CONTROL-NOT-EMPTY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	EXEC usp_api_validate_inventory_viewer @in_vchApplicationID	= @in_vchApplicationID	
										  ,@in_vchControlName	= @in_vchControlName			
										  ,@in_vchLocalID		= @in_vchLocalID				
										  ,@in_vchDeviceID		= @in_vchDeviceID				
										  ,@in_vchUserID		= @in_vchUserID				
										  ,@in_vchWhMasterID	= @in_vchWhMasterID			
										  ,@in_vchWhID			= @in_vchWhID					
										  ,@in_vchInvViewerMode	= @in_vchInvViewerMode	
										  ,@in_vchLocation		= @in_vchLocation				
										  ,@in_vchParentLPN		= @in_vchParentLPN		
										  ,@in_vchLPN			= @in_vchLPN					
										  ,@in_vchItemNumber	= @in_vchItemNumber			
										  ,@in_vchSerialNumber	= @in_vchSerialNumber			
										  ,@out_vchErrorCode	= @out_vchErrorCode	OUTPUT		
										  ,@out_vchErrorMsg		= @out_vchErrorMsg	OUTPUT	
										  ,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
	RETURN;	
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_item_control]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_item_control]
(	
	@in_vchLotControl			NVARCHAR(10) = NULL,
	@in_vchExpiryDateControl	NVARCHAR(10) = NULL,
	@in_vchAttribute1Control	NVARCHAR(10) = NULL,
	@in_vchAttribute2Control	NVARCHAR(10) = NULL,
	@in_vchAttribute3Control	NVARCHAR(10) = NULL,
	@in_vchAttribute4Control	NVARCHAR(10) = NULL,
	@in_vchAttribute5Control	NVARCHAR(10) = NULL,
	@in_vchSNControl			NVARCHAR(10) = NULL,

	@in_vchIsCheckLot			NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckExpiryDate	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute1	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute2	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute3	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute4	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute5	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckSN			NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่	
	@in_vchItemMode				NVARCHAR(25) = NULL, --BY EACH, BY QTY >> ถ้ามาจาก BY EACH ให้ Final Screen ได้เลย
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	IF (@in_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'		
			IF @in_vchIsCheckLot = 'YES'
				RETURN;
		END
	
	IF (@in_vchExpiryDateControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute1Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute2Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute3Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute3 = 'YES'
				RETURN;	
		END

	IF (@in_vchAttribute4Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute4 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute5Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute5 = 'YES'
				RETURN;	
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'	
		END
	ELSE
		BEGIN
			IF (@in_vchItemMode = 'BY EACH')
				SET @out_vchNextScreen = 'FINAL_SCREEN'
			ELSE
				SET @out_vchNextScreen = 'UOM_QTY'
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_by_select_location_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_by_select_location_2D]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40),
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		 NVARCHAR(50),
	@in_vchSourceLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	 NVARCHAR(40),
	@in_vchSourceParentLPN	 NVARCHAR(25) = NULL,
	@in_vchSourceLPN		 NVARCHAR(25) = NULL,
	@in_vchItemNumber		 NVARCHAR(50),	
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(50) = NULL,
	@in_vchAttribute2		 NVARCHAR(50) = NULL,
	@in_vchAttribute3		 NVARCHAR(50) = NULL,
	@in_vchAttribute4		 NVARCHAR(50) = NULL,
	@in_vchAttribute5		 NVARCHAR(50) = NULL,
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchUOMPrompt		 NVARCHAR(40),
	@in_fltQuantity			 FLOAT,
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @Round					INT
		DECLARE @v_vchLPNControl		NVARCHAR(3)  = NULL
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL 
		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchSourceLocationID AND is_active = 'YES'
		
		IF (@in_vchOwnerID IS NULL)
			BEGIN
				SELECT TOP 1 @in_vchOwnerID = own.owner_id
					, @in_vchOwnerCode = own.owner_code
				FROM t_wms_owner_user ownUser
				INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
				WHERE own.is_active = 'YES'
				AND ownUser.user_id = @in_vchUserID
			END
		ELSE
			BEGIN
				SELECT TOP 1 @in_vchOwnerID = own.owner_id
					, @in_vchOwnerCode = own.owner_code
				FROM t_wms_owner_user ownUser
				INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
				WHERE own.is_active = 'YES'
				AND ownUser.user_id = @in_vchUserID
				AND own.owner_id = @in_vchOwnerID 
			END

		IF (@in_vchOwnerID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXIST'
				GOTO EXIT_LABEL;
			END

		-------------------------------------------------------
		-- Check LPN Controlled
		-------------------------------------------------------
		IF (@v_vchLPNControl = 'YES')
			BEGIN
				IF ISNULL(@in_vchSourceLPN,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'LPN'
						GOTO NEXT_SCREEN;
					END
				IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
								WHERE wh_master_id = @in_vchWhMasterID
								AND owner_id = @in_vchOwnerID
								AND inventory_status_id = @in_vchInvStatusID
								AND location_id = @in_vchSourceLocationID
								AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
								AND lpn = @in_vchSourceLPN)
					BEGIN
						SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
						GOTO EXIT_LABEL;
					END 
			END
			
		-------------------------------------------------------
		-- Get Item Master ID & Get Item Warehouse Master ID
		-------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchExpiryDateControl = 'FULL' 
			BEGIN
				IF ISNULL(@in_vchExpiryDate,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'EXPIRY_DATE'
						GOTO NEXT_SCREEN;
					END
				SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			END

		IF @v_vchAttribute1Control = 'FULL' AND  ISNULL(@in_vchAttribute1,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				IF ISNULL(@in_vchSerialNumber,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'SERIAL_NUMBER'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						-------------------------------------------------------
						--Check Serial in source location [Inventory Table]
						-------------------------------------------------------
						IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
									WHERE wh_master_id = @in_vchWhMasterID
									AND owner_id = @in_vchOwnerID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
									AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
									AND serial_number = @in_vchSerialNumber)
						BEGIN
							SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-INVENTORY'
							GOTO EXIT_LABEL;
						END
					END
			END
		ELSE
			BEGIN
				-------------------------------------------------------
				--Check data [Inventory Table]
				-------------------------------------------------------
				IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
								WHERE wh_master_id = @in_vchWhMasterID
								AND owner_id = @in_vchOwnerID
								AND wh_item_master_id = @v_vchWhItemMasterID
								AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
								AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
								AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
								AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
								AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
								AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
								AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
				BEGIN
					SET @out_vchErrorCode = 'NOT_FOUND_INVENTORY_DATA'
					GOTO EXIT_LABEL;
				END 
			END

		--Check Status
		IF (SELECT COUNT(DISTINCT inventory_status_id) 
			FROM v_wms_inventory_data_serial_by_id
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID 
			AND wh_item_master_id = @v_vchWhItemMasterID 
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')) > 1 
			BEGIN
				SET @out_vchNextScreen = 'ITEM_STATUS'
				GOTO NEXT_SCREEN;
			END
		ELSE
			BEGIN
				SELECT TOP 1 @in_vchInvStatusID = inv.inventory_status_id 
					,@in_vchInvStatus = invST.inv_status
				FROM v_wms_inventory_data_by_id inv
				INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
				WHERE inv.wh_master_id = @in_vchWhMasterID 
				AND inv.owner_id = @in_vchOwnerID 
				AND inv.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(inv.lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(inv.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(inv.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			END
	
	SET @out_vchNextScreen = 'SOURCE_LOCATION'

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchItemMasterID	  AS item_master_id
		, @v_vchWhItemMasterID	  AS wh_item_master_id 
		, @v_vchItemDesc		  AS item_description
		, @v_vchLotControl	      AS lot_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchExpiryDateControl AS expiry_date_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, @v_vchUomPrompt		  AS uom_prompt
		, @in_fltQuantity		  AS display_default_qty
		, @in_vchInvStatusID	  AS inventory_status_id
		, @in_vchInvStatus		  AS inv_status
		, @in_vchOwnerID		  AS owner_id
		, @in_vchOwnerCode		  AS owner_code

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchSourceParentLPN,@in_vchSourceLPN,@in_vchLotNumber,@in_vchExpiryDate)

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_2D]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchWhID				 NVARCHAR(50),
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchOwnerCode		 NVARCHAR(40),
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		 NVARCHAR(50),
	@in_vchSourceLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	 NVARCHAR(40),
	@in_vchSourceParentLPN	 NVARCHAR(25) = NULL,
	@in_vchSourceLPN		 NVARCHAR(25) = NULL,
	@in_vchItemNumber		 NVARCHAR(50),	
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(50) = NULL,
	@in_vchAttribute2		 NVARCHAR(50) = NULL,
	@in_vchAttribute3		 NVARCHAR(50) = NULL,
	@in_vchAttribute4		 NVARCHAR(50) = NULL,
	@in_vchAttribute5		 NVARCHAR(50) = NULL,
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchUOMPrompt		 NVARCHAR(40),
	@in_fltQuantity			 FLOAT,
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @Round					INT
		DECLARE @v_vchLPNControl		NVARCHAR(3)  = NULL
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL 
		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchSourceLocationID AND is_active = 'YES'

		-------------------------------------------------------
		-- Check LPN Controlled
		-------------------------------------------------------
		IF (@v_vchLPNControl = 'YES')
			BEGIN
				IF ISNULL(@in_vchSourceLPN,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'LPN'
						GOTO NEXT_SCREEN;
					END
				IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
								WHERE wh_master_id = @in_vchWhMasterID
								AND owner_id = @in_vchOwnerID
								AND inventory_status_id = @in_vchInvStatusID
								AND location_id = @in_vchSourceLocationID
								AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
								AND lpn = @in_vchSourceLPN)
					BEGIN
						SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
						GOTO EXIT_LABEL;
					END 
			END
			
		-------------------------------------------------------
		-- Get Item Master ID & Get Item Warehouse Master ID
		-------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END
			 
		-------------------------------------------------------
		--Check item in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchSourceLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
					   AND wh_item_master_id = @v_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchExpiryDateControl = 'FULL' 
			BEGIN
				IF ISNULL(@in_vchExpiryDate,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'EXPIRY_DATE'
						GOTO NEXT_SCREEN;
					END
				SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			END

		IF @v_vchAttribute1Control = 'FULL' AND  ISNULL(@in_vchAttribute1,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				IF ISNULL(@in_vchSerialNumber,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'SERIAL_NUMBER'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						-------------------------------------------------------
						--Check data [Inventory Table]
						-------------------------------------------------------
						IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
										WHERE wh_master_id = @in_vchWhMasterID
										AND location_id = @in_vchSourceLocationID
										AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
										AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
										AND wh_item_master_id = @v_vchWhItemMasterID
										AND owner_id = @in_vchOwnerID
										AND inventory_status_id = @in_vchInvStatusID
										AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
										AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
										AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
										AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
										AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
										AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
										AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
										AND serial_number = @in_vchSerialNumber)
							BEGIN
								SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-INVENTORY'
								GOTO EXIT_LABEL;
							END
						SET @out_vchNextScreen = 'LOCATION_DESTINATION'
					END
			END
		ELSE
			BEGIN
				-------------------------------------------------------
				--Check data [Inventory Table]
				-------------------------------------------------------
				IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
								WHERE wh_master_id = @in_vchWhMasterID
								AND location_id = @in_vchSourceLocationID
								AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
								AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
								AND wh_item_master_id = @v_vchWhItemMasterID
								AND owner_id = @in_vchOwnerID
								AND inventory_status_id = @in_vchInvStatusID
								AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
								AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
								AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
								AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
								AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
								AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
								AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
					BEGIN
						SET @out_vchErrorCode = 'NOT_FOUND_INVENTORY_DATA'
						GOTO EXIT_LABEL;
					END

				SET @out_vchNextScreen = 'UOM_QTY'
				GOTO NEXT_SCREEN;
			END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchItemMasterID	  AS item_master_id
		, @v_vchWhItemMasterID	  AS wh_item_master_id 
		, @v_vchItemDesc		  AS item_description
		, @v_vchLotControl		  AS lot_control
		, @v_vchExpiryDateControl AS expiry_date_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, @v_vchUomPrompt		  AS uom_prompt
		, @in_fltQuantity		  AS display_default_qty
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchSourceParentLPN,@in_vchSourceLPN,@in_vchLotNumber,@in_vchExpiryDate)

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
