CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_serial_number]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	 NVARCHAR(25) = NULL,
	@in_vchSourceLPN		 NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchSerialNumber		 NVARCHAR(100) = NULL,
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;	
		-------------------------------------------------------
		--Check Serial in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND inventory_status_id = @in_vchInvStatusID
					AND location_id = @in_vchSourceLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END))
			BEGIN
				SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END 
		
		--Suggest จะอยู่ที่ current 

		SET @out_vchNextScreen = 'LOCATION_DESTINATION'
		SELECT 1 AS qty
		RETURN;
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchSerialNumber,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_source_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_source_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)	= NULL,
	@out_vchErrorCode		VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchSourceLocationID  UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl		VARCHAR(3) = NULL
	DECLARE @v_vchLocType			NVARCHAR(20) = NULL
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL 
	DECLARE @v_vchOwner				NVARCHAR(40) = NULL 

	IF (@in_vchOwnerID IS NULL)
		BEGIN
			SELECT TOP 1 @in_vchOwnerID = own.owner_id
				, @v_vchOwner = own.owner_code
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
		END
	ELSE
		BEGIN
			SELECT TOP 1 @in_vchOwnerID = own.owner_id
				, @v_vchOwner = own.owner_code
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
			AND own.owner_id = @in_vchOwnerID 
		END

	IF (@in_vchOwnerID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	-------------------------------------------------------
	-- Validate Location Master
	-------------------------------------------------------
	SELECT @v_vchSourceLocationID = location_id
		,@v_vchLocType = loc_type
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location 
	WHERE wh_master_id = @in_vchWhMasterID
	AND location = @in_vchSourceLocation
	AND is_active = 'YES'

	IF (@v_vchSourceLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF EXISTS (SELECT value FROM t_wms_rule WHERE rule_code IN ('LOCATION_TYPE_NOT_MOVE_ITEM') AND value = @v_vchLocType AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-ALLOW-MOVE'
			GOTO EXIT_LABEL
		END

	--Check Status Inventory ถ้ามีมากกว่า 1 Status ให้เลือก Status ก่อน
	SELECT DISTINCT @v_vchInvStatusID = inv.inventory_status_id 
		,@v_vchInvStatus = invST.inv_status
	FROM t_wms_inventory inv
	INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
	WHERE inv.wh_master_id = @in_vchWhMasterID AND inv.owner_id = @in_vchOwnerID AND inv.location_id = @v_vchSourceLocationID 
	IF @@ROWCOUNT > 1
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			------------------------------------------------------------------------------
			-- Check LPN Controlled
			------------------------------------------------------------------------------
			IF (@v_vchLPNControl = 'YES')
				BEGIN
					------------------------------------------------------------------------------
					-- Check Rule Parent LPN
					------------------------------------------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES')
						BEGIN
							SET @out_vchNextScreen = 'PARENT_LPN'
							GOTO NEXT_SCREEN;
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'LPN'
							GOTO NEXT_SCREEN;
						END
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER'
					GOTO NEXT_SCREEN;
				END
		END

	NEXT_SCREEN:
	SELECT @v_vchSourceLocationID AS source_location_id
		, @v_vchInvStatusID AS inventory_status_id
		, @v_vchInvStatus	AS inv_status
		, @in_vchOwnerID	AS owner_id
		, @v_vchOwner		AS owner_code
	RETURN;
	
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_source_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
