CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_source_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25)  = NULL,
	@in_vchSourceLPN		NVARCHAR(25)  = NULL,
	@in_vchLocalID			VARCHAR(40)	  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
				   WHERE wh_master_id = @in_vchWhMasterID
				   AND owner_id = @in_vchOwnerID
				   AND inventory_status_id = @in_vchInvStatusID
				   AND location_id = @in_vchSourceLocationID
				   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
				   AND lpn = @in_vchSourceLPN)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;
	
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_source_parent_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_source_parent_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25)  = NULL,
	@in_vchLocalID			VARCHAR(40)	  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
				   WHERE wh_master_id = @in_vchWhMasterID
				   AND owner_id = @in_vchOwnerID
				   AND inventory_status_id = @in_vchInvStatusID
				   AND location_id = @in_vchSourceLocationID
				   AND parent_lpn = @in_vchSourceParentLPN)
		BEGIN
			SET @out_vchErrorCode = 'INFO-PARENT-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LPN'		
	RETURN;
	
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_status]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER,
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchSourceLocationID  UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		 NVARCHAR(50),
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID UNIQUEIDENTIFIER = NULL
	
	-------------------------------------------------------
	--Check status in master
	-------------------------------------------------------
	SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
		,@in_vchInvStatus = inv_status
	FROM t_wms_inventory_status
	WHERE inv_status = @in_vchInvStatus
	AND is_active = 'YES' 
	IF (@v_vchInvStatusID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------------------------------
	-- Check LPN Controlled
	------------------------------------------------------------------------------
	IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchSourceLocationID) = 'YES')
		BEGIN
			------------------------------------------------------------------------------
			-- Check Rule Parent LPN
			------------------------------------------------------------------------------
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES')
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			GOTO NEXT_SCREEN;
		END

	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInvStatusID AS inventory_status_id
		, @in_vchInvStatus	AS inv_status 
	RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchInvStatus,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_item_qty_uom_qty]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_item_qty_uom_qty]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25) = NULL,
	@in_vchSourceLPN		NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_fltQuantity			FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_fltInvQuantity		FLOAT
		DECLARE @v_fltConversionFactor	FLOAT
		DECLARE @v_fltMoveQuantity		FLOAT
		DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL

		DECLARE @Round INT = 0 
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		--------------------------------------------
		-- UOM ที่รับเข้ามา
		--------------------------------------------
		SELECT @v_vchItemUomID = item_uom_id
			, @v_fltConversionFactor = conversion_factor
		FROM t_wms_item_uom
		WHERE uom_prompt = @in_vchUOMPrompt
		AND item_master_id = @in_vchItemMasterID
		AND is_active = 'YES'
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'INFO-INVALID-UOM'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------
		-- Get Inventory data
		--------------------------------------------
		SELECT @v_fltInvQuantity = SUM(quantity)
		FROM v_wms_inventory_data_serial_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND inventory_status_id = @in_vchInvStatusID
		AND location_id = @in_vchSourceLocationID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		IF (ROUND(ISNULL(@v_fltInvQuantity,0),@Round) = 0)
			BEGIN
				SET @out_vchErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
				GOTO EXIT_LABEL;
			END
		----------------------------------------------
		--คำนวณจำนวนที่ Move จริง qty * conversion factor
		----------------------------------------------
		SET @v_fltMoveQuantity = ROUND((@in_fltQuantity * @v_fltConversionFactor),@Round)
		IF (ROUND(@v_fltMoveQuantity,@Round) > ROUND(@v_fltInvQuantity,@Round))
			BEGIN
				SET @out_vchErrorCode = 'INFO-QTY-MORE-THAN-QTY-INVENTORY'
				GOTO EXIT_LABEL;
			END

		SET @out_vchNextScreen = 'LOCATION_DESTINATION'
		RETURN;
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchSourceLPN,'@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_lpn]
(
	@in_vchApplicationID VARCHAR(40)	= NULL,
	@in_vchLocalID		 VARCHAR(40)	= NULL,
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLPN			 NVARCHAR(25)	= NULL,
	@out_vchErrorCode	 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_fltInvQtyAllocate	FLOAT = 0
	DECLARE @v_vchFromLocationID	UNIQUEIDENTIFIER
	DECLARE @v_vchFromLocation		NVARCHAR(50)
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocType			NVARCHAR(50)
	--------------------------------------------------------------------
	-- Check Location in master data and loc type = RSTG
	--------------------------------------------------------------------
	SELECT @v_vchInventoryID = inv.inventory_id 
		,@v_vchOwnerID = inv.owner_id
		,@v_vchWhItemMasterID = whItem.wh_item_master_id 
		,@v_vchItemNumber = item.item_number
		,@v_vchFromLocationID = inv.location_id
		,@v_vchLocType = loc.loc_type
		,@v_vchFromLocation = loc.location
		,@v_fltInvQtyAllocate = inv.quantity_allocated
	FROM t_wms_inventory inv
	INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
	WHERE inv.wh_master_id = @in_vchWhMasterID 
	AND ISNULL(inv.lpn,'') = ISNULL(@in_vchLPN,'')
	IF (@v_vchInventoryID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
			GOTO EXIT_LABEL
		END	

	IF ISNULL(@v_fltInvQtyAllocate,0) > 0						
		BEGIN
			SET @out_vchErrorCode = 'LPN_HAVE_QTY_ALLOCATE_CANNOT_MOVE'
			GOTO EXIT_LABEL
		END	
	IF @v_vchLocType IN (select value from t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_ITEM' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'CANNOT_MOVE_LPN_FROM_OTHER_LOC_TYPE'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLPN,@v_vchLocType,'@param3','@param4','@param5')	
			RETURN;
		END	

	SET @out_vchNextScreen = 'LOCATION_DESTINATION' 
	SELECT @v_vchFromLocationID	AS from_location_id
		,@v_vchFromLocation		AS from_location
		,@v_vchOwnerID			AS owner_id
		,@v_vchItemNumber		AS item_number
	 

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
