/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_putaway_expiry_date]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_putaway_expiry_date]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	 NVARCHAR(25) = NULL,
	@in_vchSourceLPN		 NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,
	@in_vchSNControl		 VARCHAR(5),
	@in_vchAttribute1Control VARCHAR(5),
	@in_vchAttribute2Control VARCHAR(5),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		-------------------------------------------------------
		--Check Expiry Date in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchSourceLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
					   AND wh_item_master_id = @in_vchWhItemMasterID
					   AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					   AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------------
		-- Check Lot Control
		----------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl		= NULL
									,@in_vchExpiryDateControl	= NULL
									,@in_vchAttribute1Control	= @in_vchAttribute1Control
									,@in_vchAttribute2Control	= @in_vchAttribute2Control
									,@in_vchAttribute3Control	= @in_vchAttribute3Control
									,@in_vchAttribute4Control	= @in_vchAttribute4Control
									,@in_vchAttribute5Control	= @in_vchAttribute5Control
									,@in_vchSNControl			= @in_vchSNControl
									,@in_vchIsCheckLot			= 'NO'
									,@in_vchIsCheckExpiryDate	= 'NO' 
									,@in_vchIsCheckAttribute1	= 'YES'
									,@in_vchIsCheckAttribute2	= 'NO'
									,@in_vchIsCheckAttribute3	= 'NO'
									,@in_vchIsCheckAttribute4	= 'NO'
									,@in_vchIsCheckAttribute5	= 'NO'
									,@in_vchIsCheckSN			= 'NO'
									,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
			
		RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchExpiryDate,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_putaway_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_putaway_item_number]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25) = NULL,
	@in_vchSourceLPN		NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
		
		-------------------------------------------------------
		-- Get Item Master ID & Get Item Warehouse Master ID
		-------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END
 
		-------------------------------------------------------
		--Check item in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchSourceLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
					   AND wh_item_master_id = @v_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------------
		-- Check Lot Control
		----------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl		= @v_vchLotControl
									,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
									,@in_vchAttribute1Control	= @v_vchAttribute1Control
									,@in_vchAttribute2Control	= @v_vchAttribute2Control
									,@in_vchAttribute3Control	= @v_vchAttribute3Control
									,@in_vchAttribute4Control	= @v_vchAttribute4Control
									,@in_vchAttribute5Control	= @v_vchAttribute5Control
									,@in_vchSNControl			= @v_vchSNControl
									,@in_vchIsCheckLot			= 'YES'
									,@in_vchIsCheckExpiryDate	= 'NO' 
									,@in_vchIsCheckAttribute1	= 'NO'
									,@in_vchIsCheckAttribute2	= 'NO'
									,@in_vchIsCheckAttribute3	= 'NO'
									,@in_vchIsCheckAttribute4	= 'NO'
									,@in_vchIsCheckAttribute5	= 'NO'
									,@in_vchIsCheckSN			= 'NO'
									,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	

		------------------------------------------------------
		-- สำหรับนำไปใช้ที่หน้าจอ
		------------------------------------------------------
		SELECT @v_vchWhItemMasterID  AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
			, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
		RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
END
GO
