				   AND location_id = @in_vchSourceLocationID
				   AND parent_lpn = @in_vchSourceParentLPN)
		BEGIN
			SET @out_vchErrorCode = 'INFO-PARENT-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LPN'		
	RETURN;
	
	-----------------------------------------------------------------------------------
