						AND ISNULL(inv.lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(inv.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(inv.attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

						SET @out_vchNextScreen = 'SOURCE_LOCATION'
						GOTO NEXT_SCREEN;
					END
			END

	NEXT_SCREEN:
		SELECT @v_vchInvStatusID	AS inventory_status_id
			, @v_vchInvStatus		AS inv_status

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchAttribute5,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_dest_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_dest_location]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocation	NVARCHAR(50) = NULL,
	@in_vchDestLocation		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40) = NULL,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchDestLocationID  UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchDestLPNControl  NVARCHAR(3) = NULL
	DECLARE @v_vchDestLocType	  NVARCHAR(20) = NULL
	DECLARE @v_vchSourceLocType	  NVARCHAR(20) = NULL

	IF @in_vchSourceLocation = @in_vchDestLocation
	BEGIN
		SET @out_vchErrorCode = 'INFO-SOURCE-LOC-CANNOT-DUP-DEST-LOC'
		GOTO EXIT_LABEL
	END

	-------------------------------------------------------
	-- Validate Destination Location Master
	-------------------------------------------------------
	SELECT @v_vchDestLocationID = location_id
		,@v_vchDestLPNControl = lpn_controlled
		,@v_vchDestLocType = loc_type
	FROM t_wms_location 
	WHERE wh_master_id = @in_vchWhMasterID
	AND location = @in_vchDestLocation
	AND loc_type NOT IN ('STORE','FORK','STG')
	AND is_active = 'YES'

	IF (@v_vchDestLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF @v_vchDestLPNControl = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'LPN_DESTINATION'
		END
	ELSE 
		BEGIN 
			SELECT @v_vchSourceLocType FROM t_wms_location WHERE location_id = @in_vchSourceLocationID
			IF @v_vchSourceLocType = 'MRB' OR @v_vchDestLocType = 'MRB'
				BEGIN
					SET @out_vchNextScreen = 'REASON'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
				END
		END

	SELECT @v_vchDestLocationID AS dest_location_id
	RETURN;
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_dest_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_dest_lpn]
(
	@in_vchApplicationID  VARCHAR(40)  = NULL,
	@in_vchWhMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID   UNIQUEIDENTIFIER = NULL,
	@in_fltQuantity		  FLOAT,
	@in_vchUOMPrompt	  NVARCHAR(40),
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchDestLocationID UNIQUEIDENTIFIER = NULL,
	@in_vchDestLPN		  NVARCHAR(50) = NULL,
	@in_vchLocalID		  VARCHAR(40)  = NULL,
	@out_vchErrorCode	  VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	--------------------------------------------------------
	-- Check LPN in another location
	--------------------------------------------------------
	SELECT TOP 1 @in_fltQuantity = ROUND(@in_fltQuantity * conversion_factor,@Round) FROM t_wms_item_uom WHERE item_master_id = @in_vchItemMasterID AND uom_prompt = @in_vchUOMPrompt AND is_active = 'YES'

	IF((SELECT SUM(quantity) FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id <> @in_vchDestLocationID AND ISNULL(lpn,'') = ISNULL(@in_vchDestLPN,'')) > @in_fltQuantity)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-ANOTHER-LOCATION'
			GOTO EXIT_LABEL;
		END

	DECLARE @v_vchSourceLocType	  NVARCHAR(20) = NULL
	DECLARE @v_vchDestLocType	  NVARCHAR(20) = NULL
	SELECT @v_vchSourceLocType FROM t_wms_location WHERE location_id = @in_vchSourceLocationID
	SELECT @v_vchDestLocType FROM t_wms_location WHERE location_id = @in_vchDestLocationID
	IF @v_vchSourceLocType = 'MRB' OR @v_vchDestLocType = 'MRB'
		BEGIN
			SET @out_vchNextScreen = 'REASON'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'FINAL_SCREEN'
		END
	RETURN;
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_expiry_date]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_expiry_date]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,
	@in_vchSNControl		 VARCHAR(5),
	@in_vchAttribute1Control VARCHAR(5),
	@in_vchAttribute2Control VARCHAR(5),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL

		-------------------------------------------------------
		--Check Expiry Date in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND wh_item_master_id = @in_vchWhItemMasterID
					   AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					   AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------
		-- Next Screen
		----------------------------------------------------  
		IF @in_vchAttribute1Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				RETURN;
			END
		IF @in_vchAttribute2Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				RETURN;
			END
		IF @in_vchAttribute3Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				RETURN;
			END
		IF @in_vchAttribute4Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				RETURN;
			END
		IF @in_vchAttribute5Control = 'FULL'
			BEGIN 
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				RETURN;
			END	
		IF (@in_vchSnControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'SERIAL_NUMBER'
				RETURN;
			END
		ELSE
			BEGIN
				IF (SELECT COUNT(DISTINCT inventory_status_id) 
					FROM v_wms_inventory_data_by_id 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID AND wh_item_master_id = @in_vchWhItemMasterID 
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')) > 1 
					BEGIN
						SET @out_vchNextScreen = 'ITEM_STATUS'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchInvStatusID = inv.inventory_status_id 
							,@v_vchInvStatus = invST.inv_status
						FROM v_wms_inventory_data_by_id inv
						INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
						WHERE inv.wh_master_id = @in_vchWhMasterID 
						AND inv.owner_id = @in_vchOwnerID 
						AND inv.wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(inv.lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(inv.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')

						SET @out_vchNextScreen = 'SOURCE_LOCATION'
						GOTO NEXT_SCREEN;
					END
			END
	NEXT_SCREEN:
		SELECT @v_vchInvStatusID	AS inventory_status_id
			, @v_vchInvStatus		AS inv_status


	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchExpiryDate,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_item_number]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL, 
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOwnerCode			NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL
		
	IF (@in_vchOwnerID IS NULL)
		BEGIN
			SELECT TOP 1 @in_vchOwnerID = own.owner_id
				, @v_vchOwnerCode = own.owner_code
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
		END
	ELSE
		BEGIN
			SELECT TOP 1 @in_vchOwnerID = own.owner_id
				, @v_vchOwnerCode = own.owner_code
			FROM t_wms_owner_user ownUser
			INNER JOIN t_wms_owner own ON ownUser.owner_id = own.owner_id
			WHERE own.is_active = 'YES'
			AND ownUser.user_id = @in_vchUserID
			AND own.owner_id = @in_vchOwnerID 
		END

	IF (@in_vchOwnerID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

		-------------------------------------------------------
		-- Get Item Master ID & Get Item Warehouse Master ID
		-------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END
 
		-------------------------------------------------------
		--Check item in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND wh_item_master_id = @v_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------
		-- ตรวจสอบ Lot Control
		----------------------------------------------------
		IF (@v_vchLotControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END
		IF (@v_vchExpiryDateControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'EXPIRY_DATE'
				GOTO NEXT_SCREEN;
			END
		IF @v_vchAttribute1Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END
		IF @v_vchAttribute2Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END
		IF @v_vchAttribute3Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END
		IF @v_vchAttribute4Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END
		IF @v_vchAttribute5Control = 'FULL'
			BEGIN 
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END	
		IF (@v_vchSnControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'SERIAL_NUMBER'
				GOTO NEXT_SCREEN;
			END
		ELSE
			BEGIN
				IF (SELECT COUNT(DISTINCT inventory_status_id) FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND wh_item_master_id = @v_vchWhItemMasterID) > 1 
					BEGIN
						SET @out_vchNextScreen = 'ITEM_STATUS'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchInvStatusID = inv.inventory_status_id 
							,@v_vchInvStatus = invST.inv_status
						FROM t_wms_inventory inv
						INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
						WHERE inv.wh_master_id = @in_vchWhMasterID 
						AND inv.owner_id = @in_vchOwnerID 
						AND inv.wh_item_master_id = @v_vchWhItemMasterID

						SET @out_vchNextScreen = 'SOURCE_LOCATION'
						GOTO NEXT_SCREEN;
					END
			END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- สำหรับนำไปใช้ที่หน้าจอ
		------------------------------------------------------
		SELECT @v_vchWhItemMasterID   AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
			, @v_vchInvStatusID		  AS inventory_status_id
			, @v_vchInvStatus		  AS inv_status
			, @in_vchOwnerID		  AS owner_id
			, @v_vchOwnerCode		  AS owner_code
		RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_lot_number]
(
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL, 
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDateControl VARCHAR(5),
	@in_vchSNControl		 VARCHAR(5),
	@in_vchAttribute1Control VARCHAR(5),
	@in_vchAttribute2Control VARCHAR(5),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchLocalID			 VARCHAR(40),
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL

		-------------------------------------------------------
		--Check lot number in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND wh_item_master_id = @in_vchWhItemMasterID
					   AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST-IN-INVENTORY'
			GOTO EXIT_LABEL;
		END

		----------------------------------------------------
		-- Next Screen
		---------------------------------------------------- 
		IF (@in_vchExpiryDateControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'EXPIRY_DATE'
				RETURN;
			END
		IF @in_vchAttribute1Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				RETURN;
			END
		IF @in_vchAttribute2Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				RETURN;
			END
		IF @in_vchAttribute3Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				RETURN;
			END
		IF @in_vchAttribute4Control = 'FULL'
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				RETURN;
			END
		IF @in_vchAttribute5Control = 'FULL'
			BEGIN 
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				RETURN;
			END	
		IF (@in_vchSnControl = 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'SERIAL_NUMBER'
				RETURN;
			END
		ELSE
			BEGIN
				IF (SELECT COUNT(DISTINCT inventory_status_id) FROM v_wms_inventory_data_by_id WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND wh_item_master_id = @in_vchWhItemMasterID  AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')) > 1 
					BEGIN
						SET @out_vchNextScreen = 'ITEM_STATUS'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchInvStatusID = inv.inventory_status_id 
							,@v_vchInvStatus = invST.inv_status
						FROM v_wms_inventory_data_by_id inv
						INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
						WHERE inv.wh_master_id = @in_vchWhMasterID 
						AND inv.owner_id = @in_vchOwnerID 
						AND inv.wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(inv.lot_number,'') = ISNULL(@in_vchLotNumber,'')

						SET @out_vchNextScreen = 'SOURCE_LOCATION'
						GOTO NEXT_SCREEN;
					END
			END
		
	NEXT_SCREEN:
		SELECT @v_vchInvStatusID	AS inventory_status_id
			, @v_vchInvStatus		AS inv_status

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLotNumber,'@param2','@param3','@param4','@param5')			

END
