CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_status]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL, 
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchSerialNumber		NVARCHAR(100) = NULL,
	@in_vchInvStatus		NVARCHAR(50),
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID UNIQUEIDENTIFIER = NULL
	
		-------------------------------------------------------
		--Check status in master
		-------------------------------------------------------
		SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
			,@in_vchInvStatus = inv_status
		FROM t_wms_inventory_status
		WHERE inv_status = @in_vchInvStatus
		AND is_active = 'YES' 
		IF (@v_vchInvStatusID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		-------------------------------------------------------
		--Check Serial in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND inventory_status_id = @v_vchInvStatusID)
		BEGIN
			SET @out_vchErrorCode = 'INVENTORY_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'SOURCE_LOCATION'  

	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInvStatusID AS inventory_status_id
		, @in_vchInvStatus	AS inv_status 
	RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
	IF (@out_vchErrorCode IS NOT NULL)
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchInvStatus,'@param2','@param3','@param4','@param5')			

END
