/****** Object:  StoredProcedure [dbo].[usp_api_validate_move_select_location_uom_qty]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_move_select_location_uom_qty]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchSerialNumber		NVARCHAR(100) = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchSourceLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchSourceParentLPN	NVARCHAR(25)  = NULL,
	@in_vchSourceLPN		NVARCHAR(25)  = NULL,
	@in_fltQuantity			FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_fltInvQuantity		FLOAT
		DECLARE @v_fltConversionFactor	FLOAT
		DECLARE @v_fltMoveQuantity		FLOAT
		DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL

		DECLARE @Round INT = 0 
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		--------------------------------------------
		-- UOM ที่รับเข้ามา
		--------------------------------------------
		SELECT @v_vchItemUomID = item_uom_id
			, @v_fltConversionFactor = conversion_factor
		FROM t_wms_item_uom
		WHERE uom_prompt = @in_vchUOMPrompt
		AND item_master_id = @in_vchItemMasterID
		AND is_active = 'YES'
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'INFO-INVALID-UOM'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------
		-- Get Inventory data
		--------------------------------------------
		SELECT @v_fltInvQuantity = SUM(quantity)
		FROM v_wms_inventory_data_serial_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND inventory_status_id = @in_vchInvStatusID
		AND location_id = @in_vchSourceLocationID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchSourceParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchSourceLPN,'')
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		IF (ISNULL(@v_fltInvQuantity,0) = 0)
			BEGIN
				SET @out_vchErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
				GOTO EXIT_LABEL;
			END
		----------------------------------------------
		--คำนวณจำนวนที่ Move จริง qty * conversion factor
		----------------------------------------------
		SET @v_fltMoveQuantity = ROUND((@in_fltQuantity * @v_fltConversionFactor),@Round)
		IF (@v_fltMoveQuantity > @v_fltInvQuantity)
			BEGIN
				SET @out_vchErrorCode = 'INFO-QTY-MORE-THAN-QTY-INVENTORY'
				GOTO EXIT_LABEL;
			END

		SET @out_vchNextScreen = 'LOCATION_DESTINATION'
		RETURN;
	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchSourceLPN,'@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_packing_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_packing_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchPackNumber		NVARCHAR(25),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL, 
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_fltQuantity			FLOAT,
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @Round					INT
		DECLARE @v_vchLPNControl		NVARCHAR(3)  = NULL
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL

		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'

		-------------------------------------------------------
		-- Check LPN Controlled
		-------------------------------------------------------
		IF (@v_vchLPNControl = 'YES')
			BEGIN
				IF ISNULL(@in_vchLPN,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'LPN'
						GOTO NEXT_SCREEN;
					END
				IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID AND staging_location_id = @in_vchLocationID AND staging_lpn = @in_vchLPN)
					BEGIN
						SET @out_vchErrorCode = 'NOT_FOUND_LPN_IN_STG_LOCATION'
						GOTO EXIT_LABEL
					END
			END
			
		--------------------------------------------------------------------
		-- ตรวจสอบ Item Number และ ใน Cross Ref
		--------------------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @in_vchItemNumber = item.item_number
			, @v_vchItemDesc = item.description
			, @v_vchLotControl = item.lot_control
			, @v_vchSNControl = item.sn_control
			, @v_vchExpiryDateControl = item.expiry_date_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
			, @v_vchUomPrompt = uom.uom_prompt
		FROM  t_wms_item item
		INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------------------------------
		--Check Item in pick to staging
		--------------------------------------------------------------------
		IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
						WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
						AND is_override = 'NO'
						AND staging_location_id = @in_vchLocationID
						AND wh_item_master_id = @v_vchWhItemMasterID 
						AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLpn,'')
						AND ISNULL(quantity_pack,0) < ISNULL(quantity_stage,0))
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchExpiryDateControl = 'FULL'
			BEGIN
				IF ISNULL(@in_vchExpiryDate,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'EXPIRY_DATE'
						GOTO NEXT_SCREEN;
					END
				SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			END

		IF @v_vchAttribute1Control = 'FULL' AND  ISNULL(@in_vchAttribute1,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute3Control = 'FULL'  AND ISNULL(@in_vchAttribute3,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END
			 
		IF (@v_vchSNControl = 'FULL') AND ISNULL(@in_vchSerialNumber,'') = ''
			BEGIN 
				SET @out_vchNextScreen = 'SERIAL_NUMBER'
				GOTO NEXT_SCREEN;
			 END
			 
		-------------------------------------------------------
		--Check data [PICK DETAIL]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pack_for_check
						WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
						AND staging_location_id = @in_vchLocationID 
						AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
						AND wh_item_master_id = @v_vchWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						AND is_override = 'NO')
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_IN_STG_LOCATION'
				GOTO EXIT_LABEL;
			END

		SET @out_vchNextScreen = 'UOM_QTY'
		GOTO NEXT_SCREEN;
			 
	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchWhItemMasterID		AS wh_item_master_id
		, @v_vchItemMasterID		AS item_master_id
		, @v_vchItemDesc			AS item_description
		, @v_vchLotControl			AS lot_control
		, @v_vchSNControl		    AS sn_control
		, @v_vchExpiryDateControl	AS expiry_date_control
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control
		, @v_vchUomPrompt			AS uom_prompt
		, @in_fltQuantity			AS display_default_qty

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2',@in_vchLPN,@in_vchLotNumber,@in_vchExpiryDate)
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_packing_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_packing_attribute1]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWhMasterID			UNIQUEIDENTIFIER, 
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchLocationID			UNIQUEIDENTIFIER, 
	@in_vchLPN					NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2Control	VARCHAR(5) = NULL,
	@in_vchAttribute3Control	VARCHAR(5) = NULL,
	@in_vchAttribute4Control	VARCHAR(5) = NULL,
	@in_vchAttribute5Control	VARCHAR(5) = NULL,
	@in_vchSNControl			VARCHAR(5) = NULL, 
	@in_vchLocalID				VARCHAR(40)  = NULL,
	@out_vchErrorCode			VARCHAR(50) OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	----------------------------------------------------------
	-- Validate attribute 1 ที่สแกนใน Pick Detail
	----------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND staging_location_id = @in_vchLocationID 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND is_override = 'NO') 
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-ATTRIBUTE1-IN-PICK-DETAIL'
			GOTO EXIT_LABEL
		END 

	
	----------------------------------------------------------
	-- Check Attribute2 Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl		= NULL	
								,@in_vchExpiryDateControl	= NULL
								,@in_vchAttribute1Control	= NULL
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'NO'	
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'YES'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO' 
								,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
