	@in_vchAttribute4Control    VARCHAR(5),
	@in_vchAttribute5Control    VARCHAR(5),
	@in_vchSNControl		    VARCHAR(5),
	@in_vchLocalID			    VARCHAR(40),
	@out_vchErrorCode		    VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		    NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		    NVARCHAR(50) OUTPUT
)
AS
BEGIN
	----------------------------------------------------------
	-- Validate Lot Number ที่สแกนใน Pick Detail
	----------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND staging_location_id = @in_vchLocationID
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLpn,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND lot_number = @in_vchLotNumber
					AND is_override = 'NO')
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LOT-IN-PICK-DETAIL'
			GOTO EXIT_LABEL
		END

	----------------------------------------------------------
	-- Check Expiry Date Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl	= NULL	
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'YES'	--สำหรับบอกว่ากำลังจะ Check control Exp.
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	RETURN;	

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_packing_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_packing_lpn]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
 	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
 	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	--Check Staging LPN in picklist 
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID AND staging_location_id = @in_vchLocationID AND staging_lpn = @in_vchLPN)
		BEGIN
			SET @out_vchErrorCode = 'NOT_FOUND_LPN_IN_STG_LOCATION'
			GOTO EXIT_LABEL
		END

	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLPN,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_packing_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_packing_order_number]
(
	@in_vchApplicationID	VARCHAR(40) = null,
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = null,
	@in_vchWarehouse		NVARCHAR(25) = null,
	@in_vchOutboundNumber	NVARCHAR(50) = null,
	@in_vchLocalID			VARCHAR(40) = null,
	@in_vchUserID			NVARCHAR(25),
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(40) = NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10) = NULL
	DECLARE @v_vchOrderType			NVARCHAR(30) = NULL
	DECLARE	@v_fltQuantityPick		FLOAT = 0
	DECLARE @v_fltQuantityPack		FLOAT = 0
	DECLARE @v_intRound INT
	SELECT @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id 
		, @v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
		, @v_vchOwnerID = obMS.owner_id
		, @v_vchOwnerCode = own.owner_code
		, @v_vchOrderStatus = obMS.order_status
		, @v_vchOrderType = obMS.order_type
		, @v_fltQuantityPick = SUM(ISNULL(pickDT.quantity_pick,0))
		, @v_fltQuantityPack = SUM(ISNULL(pickDT.quantity_pack,0))
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_master pickMS WITH (NOLOCK)on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_detail pickDT WITH (NOLOCK) ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
	WHERE obMS.outbound_order_number = @in_vchOutboundNumber
	AND obMS.wh_master_id = @in_vchWhMasterID
	GROUP BY obMS.outbound_order_master_id
		,pickMS.outbound_pick_master_id
		,obMS.owner_id
		,own.owner_code
		,obMS.order_status
		,obMS.order_type

	------------------------------------------------------
	-- Vaildate Outbound Order Number in System
	------------------------------------------------------
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	------------------------------------------------------
	-- Vaildate Pick list Number in System
	------------------------------------------------------
	IF (@v_vchOutboundPickMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'PICKLIST_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL
		END

	IF @v_vchOrderType NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INVALID_ORDER_TYPE_FOR_OB_PACKING'
			GOTO EXIT_LABEL
		END

	IF ROUND(@v_fltQuantityPick - @v_fltQuantityPack,@v_intRound) <= 0
		BEGIN
			SET @out_vchErrorCode = 'NOT_FOUND_ITEM_FOR_PACK'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- Validate Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL,'PICKED'
	------------------------------------------------------------------------------
	IF (@v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-OUTBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END
	
	DECLARE @v_vchPackNumber NVARCHAR(25) = ''
	DECLARE @v_vchLocationID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPN NVARCHAR(25) = '' 
	DECLARE @v_nCount INT = 0;
	
	SELECT TOP 1 @v_vchLocationID = pickDT.staging_location_id
		,@v_vchLPN = pickDT.staging_lpn
	FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
	WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID

	SELECT @v_nCount = COUNT(DISTINCT lpn_pack) FROM t_wms_outbound_pack_detail pickDT WHERE outbound_order_master_id = @v_vchOutboundMasterID
	IF (@v_nCount = 0)
		BEGIN	
			IF (SELECT TOP 1 VALUE FROM t_wms_rule WHERE rule_code ='AUTO_GENERATE_PACK_NUMBER' AND is_active = 'YES') = 'YES'
				BEGIN
					EXEC usp_generate_running_outbound_pack_number @in_vchUserID		= @in_vchUserID
																  ,@in_vchOutboundNumber= @in_vchOutboundNumber		
																  ,@out_vchPackNumber	= @v_vchPackNumber OUTPUT		
																  ,@out_ErrorCode		= @out_vchErrorCode OUTPUT		
																  ,@out_ErrorMessage	= @out_vchErrorMsg OUTPUT
					GOTO FIND_SCREEN;
				END
			ELSE
				BEGIN
					--Status ไม่ถูกต้อง
					SET @out_vchErrorCode = 'PLEASE_CREATE_PACK_NUMBER'
					GOTO EXIT_LABEL
				END
		END
	ELSE IF (@v_nCount = 1)
		BEGIN
			SELECT TOP 1 @v_vchPackNumber = lpn_pack FROM t_wms_outbound_pack_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID
			GOTO FIND_SCREEN;
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'PACK_NUMBER'
			GOTO NEXT_SCREEN;
		END

	FIND_SCREEN:
		IF (SELECT COUNT(DISTINCT pickDT.staging_lpn) FROM t_wms_outbound_pick_detail pickDT WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID) > 1
			BEGIN
				SET @out_vchNextScreen = 'LPN'
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'ITEM_NUMBER'
			END

	------------------------------------------------------
	-- For next screen
	------------------------------------------------------
	NEXT_SCREEN: 
	SELECT @v_vchOutboundMasterID AS outbound_order_master_id
		, @v_vchOutboundPickMasterID AS outbound_pick_master_id
		, @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code
		, @v_vchPackNumber AS pack_number
		, @v_vchLocationID as location_id
		, @v_vchLPN AS lpn
	RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_packing_pack_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_packing_pack_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundNumber	NVARCHAR(50)	 = NULL,
	@in_vchOutboundMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchPackNumber		NVARCHAR(25) = NULL, 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLPN NVARCHAR(25) = ''
	DECLARE @v_vchLocationID UNIQUEIDENTIFIER
	SELECT TOP 1 @v_vchLocationID = pickDT.staging_location_id
		,@v_vchLPN = pickDT.staging_lpn
	FROM t_wms_outbound_pick_detail pickDT 
	WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 

 	IF (SELECT COUNT(DISTINCT pickDT.staging_lpn) FROM t_wms_outbound_pick_detail pickDT WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID) > 1
		BEGIN
			SET @out_vchNextScreen = 'LPN'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'
		END
	
	SELECT @v_vchLocationID AS location_id
		, @v_vchLPN AS lpn
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_outbound_unpack_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_outbound_unpack_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID UNIQUEIDENTIFIER,
	@in_vchOutboundNumber	NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchPackNumber		NVARCHAR(25),
	@in_vchItemNumber		NVARCHAR(50) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL, 
	@in_vchExpiryDate		NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_fltQuantity			FLOAT,
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
		DECLARE @v_vchLPNControl		NVARCHAR(3)  = NULL
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
		 
		--------------------------------------------------------------------
		-- ตรวจสอบ Item Number และ ใน Cross Ref
		--------------------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @in_vchItemNumber = item.item_number
			, @v_vchItemDesc = item.description
			, @v_vchLotControl = item.lot_control
			, @v_vchSNControl = item.sn_control
			, @v_vchExpiryDateControl = item.expiry_date_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
			, @v_vchUomPrompt = uom.uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END
		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchExpiryDateControl = 'FULL'
			BEGIN
				IF ISNULL(@in_vchExpiryDate,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'EXPIRY_DATE'
						GOTO NEXT_SCREEN;
					END
				SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			END

		IF @v_vchAttribute1Control = 'FULL' AND  ISNULL(@in_vchAttribute1,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute3Control = 'FULL'  AND ISNULL(@in_vchAttribute3,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END
			 
		IF (@v_vchSNControl = 'FULL') AND ISNULL(@in_vchSerialNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'SERIAL_NUMBER'
				GOTO NEXT_SCREEN;
			 END
		
		--Check Data in Pack No
		IF NOT EXISTS (SELECT outbound_pack_detail_id FROM t_wms_outbound_pack_detail 
					WHERE outbound_order_master_id = @in_vchOutboundMasterID
					ANd lpn_pack = @in_vchPackNumber
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'NOT_FOUND_DATA_IN_PACK_NO'
			GOTO EXIT_LABEL;
		END

		--ถ้าไม่ได้ Control SN
		IF (@v_vchSNControl <> 'FULL')
			BEGIN
				SET @out_vchNextScreen = 'UOM_QTY'
			END
		ELSE
			BEGIN
				SET @in_fltQuantity = 1;
				GOTO SAVE_TRANS;
			END
			 
	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
		SELECT @v_vchWhItemMasterID   AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
			, @in_fltQuantity		  AS display_default_qty
			, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

	RETURN;

	SAVE_TRANS:
		BEGIN 
			EXEC usp_outbound_unpack @in_vchApplicationID	 = @in_vchApplicationID	
									,@in_vchDeviceID		 = @in_vchDeviceID				
									,@in_vchUserID			 = @in_vchUserID			
									,@in_vchWhMasterID		 = @in_vchWhMasterID		
									,@in_vchWarehouse		 = @in_vchWhID		
									,@in_vchOutboundMasterID = @in_vchOutboundMasterID		
									,@in_vchPackNumber		 = @in_vchPackNumber		
									,@in_vchWhItemMasterID	 = @v_vchWhItemMasterID	
									,@in_vchLotNumber		 = @in_vchLotNumber		
									,@in_vchExpiryDate		 = @in_vchExpiryDate		
									,@in_vchSerialNumber	 = @in_vchSerialNumber			
									,@in_vchAttribute1		 = @in_vchAttribute1		
									,@in_vchAttribute2		 = @in_vchAttribute2		
									,@in_vchAttribute3		 = @in_vchAttribute3		
									,@in_vchAttribute4		 = @in_vchAttribute4		
									,@in_vchAttribute5		 = @in_vchAttribute5		
									,@in_fltQuantity		 = @in_fltQuantity				
									,@in_vchUOMPrompt		 = @in_vchUOMPrompt
									,@out_ErrorCode			 = @out_vchErrorCode OUTPUT
									,@out_ErrorMessage		 = @out_vchErrorMsg OUTPUT 

			IF ISNULL(@out_vchErrorCode,'') <> '0'
				BEGIN
					SET @out_vchNextScreen = NULL
					RETURN;
				END
									
			--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
				BEGIN
					GOTO FINAL_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN';
					RETURN;
				END

		FINAL_SCREEN:
			EXEC usp_api_validate_outbound_unpack_final_screen @in_vchApplicationID		= @in_vchApplicationID	
															  ,@in_vchWhMasterID		= @in_vchWhMasterID		
															  ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	
															  ,@in_vchPackNumber		= @in_vchPackNumber		
															  ,@in_vchWhItemMasterID	= @v_vchWhItemMasterID	
															  ,@in_vchItemMasterID		= @v_vchItemMasterID		
															  ,@in_vchLocalID			= @in_vchLocalID			
															  ,@out_vchErrorCode		= @out_vchErrorCode OUTPUT	
															  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT
															  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
	END

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
