CREATE PROCEDURE [dbo].[usp_api_validate_outbound_unpack_pack_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL, 
	@in_vchOutboundMasterID UNIQUEIDENTIFIER = NULL, 
	@in_vchPackNumber		NVARCHAR(25) = NULL, 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLPN NVARCHAR(25) = ''
	DECLARE @v_vchLocationID UNIQUEIDENTIFIER
	IF NOT EXISTS (SELECT outbound_pack_detail_id FROM t_wms_outbound_pack_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND lpn_pack = @in_vchPackNumber)
		BEGIN
			SET @out_vchErrorCode = 'PACK_NO_NOT_FOUND'
			GOTO EXIT_LABEL
		END
	
	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
