								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_final_screen]
(
	@in_vchApplicationID	VARCHAR(40)	= NULL,
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID			NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25)	= NULL,
	@in_vchLPN				NVARCHAR(25)	= NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		NVARCHAR(50)	= NULL,
	@in_vchExpDate			NVARCHAR(50)	= NULL,
	@in_vchSerialNumber		NVARCHAR(100)	= NULL,
	@in_vchLocalID			VARCHAR(40)	= NULL,
	@out_vchErrorCode		VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT 
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_fltQuantityPlan	FLOAT
	DECLARE @v_fltQuantityPick	FLOAT
	DECLARE @v_vchOutboundPickDetailGUID UNIQUEIDENTIFIER

	------------------------------------------------------
	-- Check ทั้ง Order ว่ายังมีรายการที่ยังหยิบไม่ครบหรือไม่
	------------------------------------------------------
	IF NOT EXISTS (SELECT dt.outbound_order_detail_id 
				   FROM t_wms_outbound_detail dt
				   INNER JOIN t_wms_outbound_master ms ON dt.outbound_order_master_id = ms.outbound_order_master_id
				   WHERE ms.wh_master_id = @in_vchWhMasterID
				   AND ms.load_id  = @in_vchLoadID 
				   AND ISNULL(dt.quantity_pick,0) < ISNULL(dt.quantity_order,0))
		BEGIN
			-- Pick ครบทุกรายงานแล้ว 
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES') = 'YES')
				BEGIN
					--ถ้า Auto STG ไม่ต้องไปแสดงหน้า STG Location ให้กลับไปที่หน้า Order เลย
					SET @out_vchNextScreen = 'LOAD_ID'
					RETURN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'STAGING_LOCATION'
					RETURN;
				END
		END
	 
	IF (SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
			RETURN;
		END
	
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			
END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_id]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_id]
(
	@in_vchApplicationID VARCHAR(40) = null,
	@in_vchDeviceID		 NVARCHAR(50) = null,
	@in_vchUserID		 NVARCHAR(25) = null,
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = null,
	@in_vchWarehouse	 NVARCHAR(25) = null,
	@in_vchLoadID		 NVARCHAR(50) = null,
	@in_vchLocalID		 VARCHAR(40) = null,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT TOP 1 outbound_order_master_id FROM t_wms_outbound_master WITH (NOLOCK) WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID AND pick_type = 'SYSTEM_GROUP')
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOAD-ID-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL
	-- สำหรับ PST แสดง Load_id เฉพาะ Order Status IN 'RELEASE','PICK'
	------------------------------------------------------------------------------
	IF EXISTS (SELECT TOP 1 load_id FROM v_wms_outbound_rel_by_load WITH (NOLOCK) WHERE load_id = @in_vchLoadID AND wh_master_id = @in_vchWhMasterID
				AND load_status IN (SELECT value FROM dbo.t_wms_rule  WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-OUTBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------------------------------
	IF (SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
		END

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	DECLARE @v_vchOwnerID	UNIQUEIDENTIFIER = null
	DECLARE @v_vchOwnerCode	NVARCHAR(40)= null

	SELECT TOP 1 @v_vchOwnerID = owner_id
		, @v_vchOwnerCode = owner_code
	FROM t_wms_outbound_master
 	WHERE load_id = @in_vchLoadID
	AND wh_master_id = @in_vchWhMasterID 
	AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
		
	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	SELECT @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code

	RETURN;
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLoadID,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_item_number]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchLoadID		 NVARCHAR(50) = NULL,
	@in_vchLocationID	 UNIQUEIDENTIFIER, 
	@in_vchParentLPN	 NVARCHAR(25),
	@in_vchLPN			 NVARCHAR(25),
	@in_vchItemNumber	 NVARCHAR(50),
	@in_vchLocalID		 VARCHAR(40),
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
		DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchOwnerCode			NVARCHAR(50) = NULL
		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

		SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_outbound_master WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID

		--------------------------------------------------------------------
		-- ตรวจสอบ Item Number และ ใน Cross Ref
		--------------------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @v_vchOwnerID

		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END
		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------------------------------
		--Check Item In Plan
		--------------------------------------------------------------------
		IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
					   WHERE wh_master_id = @in_vchWhMasterID 
					   AND ISNULL(load_id,'') = @in_vchLoadID
					   AND is_override = 'NO'
					   AND location_id = @in_vchLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
					   AND wh_item_master_id = @v_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'OUTBOUND_DETAIL_NOT_FOUND_ITEM'
				GOTO EXIT_LABEL;
			END
		 

		EXEC usp_validate_item_control @in_vchLotControl			= @v_vchLotControl	
										,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
										,@in_vchAttribute1Control	= @v_vchAttribute1Control
										,@in_vchAttribute2Control	= @v_vchAttribute2Control
										,@in_vchAttribute3Control	= @v_vchAttribute3Control
										,@in_vchAttribute4Control	= @v_vchAttribute4Control
										,@in_vchAttribute5Control	= @v_vchAttribute5Control
										,@in_vchSNControl			= @v_vchSNControl
										,@in_vchIsCheckLot			= 'YES'
										,@in_vchIsCheckExpiryDate	= 'NO'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@out_vchNextScreen			= @out_vchNextScreen OUTPUT		 
	
		------------------------------------------------------
		-- สำหรับนำไปใช้ที่หน้าจอ
		------------------------------------------------------
		SELECT @v_vchWhItemMasterID  AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
			, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
		RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_location]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID		 NVARCHAR(50) = NULL,
	@in_vchLocation		 NVARCHAR(40) = NULL,
	@in_vchLocalID		 VARCHAR(40) = NULL,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500)OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLPNControl NVARCHAR(3)
	DECLARE @v_vchLocationID UNIQUEIDENTIFIER = NULL

	-------------------------------------------------------
	-- Validate Location in Pick Detail
	-------------------------------------------------------
	SELECT @v_vchLocationID = location_id
		,@v_vchLPNControl = lpn_controlled
 	FROM v_wms_outbound_pick_detail_by_load
	WHERE wh_master_id = @in_vchWhMasterID 
	AND ISNULL(load_id,'') = @in_vchLoadID
	AND is_override = 'NO'
	AND location = @in_vchLocation

	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIT'
			GOTO EXIT_LABEL
		END

	-------------------------------------------------------
	-- LPN Control and Wh Rule Parent LPN
	-------------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			-------------------------------------------------------
			-- Check Rule Parent LPN
			-------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'
		END

	SELECT @v_vchLocationID AS location_id

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_lot_number]
(
	@in_vchApplicationID	    VARCHAR(40),
	@in_vchWhMasterID		    UNIQUEIDENTIFIER,
	@in_vchLoadID				NVARCHAR(50) = NULL,
	@in_vchLocationID			UNIQUEIDENTIFIER, 
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER,
	@in_vchLotNumber		    NVARCHAR(50),
	@in_vchExpiryDateControl    VARCHAR(5),
	@in_vchSNControl		    VARCHAR(5),
	@in_vchAttribute1Control    VARCHAR(5),
	@in_vchAttribute2Control    VARCHAR(5),
	@in_vchAttribute3Control    VARCHAR(5),
	@in_vchAttribute4Control    VARCHAR(5),
	@in_vchAttribute5Control    VARCHAR(5),
	@in_vchLocalID			    VARCHAR(40),
	@out_vchErrorCode		    VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		    NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		    NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	----------------------------------------------------------
	-- Validate Lot Number ที่สแกนใน Pick Detail
	----------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
					WHERE wh_master_id = @in_vchWhMasterID 
					AND ISNULL(load_id,'') = @in_vchLoadID
					AND is_override = 'NO'
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND lot_number = @in_vchLotNumber)
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LOT-IN-PICK-DETAIL'
			GOTO EXIT_LABEL
		END

	----------------------------------------------------------
	-- Check Expiry Date Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl	= NULL	
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'YES'	--สำหรับบอกว่ากำลังจะ Check control Exp.
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	RETURN;	

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_lpn]
(
	@in_vchApplicationID VARCHAR(40) = NULL,
	@in_vchWhMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID		 NVARCHAR(50) = NULL, 
	@in_vchLocationID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN	 NVARCHAR(25) = NULL, 
	@in_vchLPN			 NVARCHAR(25) = NULL,
	@in_vchLocalID		 VARCHAR(40)  = NULL,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
					WHERE wh_master_id = @in_vchWhMasterID 
					AND ISNULL(load_id,'') = @in_vchLoadID
					AND is_override = 'NO'
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LPN-IN-LOCATION'
			GOTO EXIT_LABEL
		END
	 
	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
