/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_load_serial_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_load_serial_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchLoadID			NVARCHAR(50) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER, 
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(50) = NULL,
	@in_vchAttribute2		NVARCHAR(50) = NULL,
	@in_vchAttribute3		NVARCHAR(50) = NULL,
	@in_vchAttribute4		NVARCHAR(50) = NULL,
	@in_vchAttribute5		NVARCHAR(50) = NULL,
	@in_vchSerialNumber		NVARCHAR(100)= NULL, 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOwnerID UNIQUEIDENTIFIER = NULL
	SELECT TOP 1 @v_vchOwnerID = owner_id FROM t_wms_outbound_master WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID

	IF @in_vchSerialNumber <> 'ALL'
		BEGIN
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @v_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
				BEGIN
					SET @out_vchErrorCode = 'SERIAL_NOT_FOUND_IN_INVENOTY'
					GOTO EXIT_LABEL;
				END

			IF EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
							WHERE wh_master_id = @in_vchWhMasterID 
							AND ISNULL(load_id,'') = @in_vchLoadID
							AND is_override = 'NO'
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
				BEGIN 
					SET @out_vchErrorCode = 'INFO-SN-DUPLICATED'
					GOTO EXIT_LABEL; 
				END
		END
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pick_mode]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pick_mode]
(
	@in_vchApplicationID VARCHAR(40) = NULL,
	@in_vchLocalID		 VARCHAR(40) = NULL,
	@in_vchPickMode		VARCHAR(25) = NULL,
	@out_vchErrorCode	VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	NVARCHAR(50) OUTPUT
)
AS
BEGIN
	IF ISNULL(@in_vchPickMode,'') = ''
		BEGIN
			SET @in_vchPickMode = 'ENTER QTY'
		END

	IF @in_vchPickMode NOT IN (SELECT value_member FROM t_com_combobox_item WHERE group_name = 'PICK_MODE' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-PICK-MODE-INVALID'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LOCATION'
	RETURN;
	
	
	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
