CREATE PROCEDURE [dbo].[usp_api_validate_picking_lot_number]
(
	@in_vchApplicationID	    VARCHAR(40),
	@in_vchWhMasterID		    UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchLocationID		    UNIQUEIDENTIFIER,
	@in_vchParentLPN		    NVARCHAR(25),
	@in_vchLPN				    NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER,
	@in_vchLotNumber		    NVARCHAR(50),
	@in_vchExpiryDateControl    VARCHAR(5),
	@in_vchSNControl		    VARCHAR(5),
	@in_vchAttribute1Control    VARCHAR(5),
	@in_vchAttribute2Control    VARCHAR(5),
	@in_vchAttribute3Control    VARCHAR(5),
	@in_vchAttribute4Control    VARCHAR(5),
	@in_vchAttribute5Control    VARCHAR(5),
	@in_vchPickMode			    NVARCHAR(50), --BY_EACH, BY_QTY or empty
	@in_vchLocalID			    VARCHAR(40),
	@out_vchErrorCode		    VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		    NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		    NVARCHAR(50) OUTPUT
)
AS
BEGIN
	----------------------------------------------------------
	-- Validate Lot Number ที่สแกนใน Pick Detail
	----------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND lot_number = @in_vchLotNumber
					AND is_override = 'NO')
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LOT-IN-PICK-DETAIL'
			GOTO EXIT_LABEL
		END

	----------------------------------------------------------
	-- Check Expiry Date Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl	= NULL	
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'YES'	--สำหรับบอกว่ากำลังจะ Check control Exp.
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@in_vchItemMode			= @in_vchPickMode
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	RETURN;	

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_lpn]
(
	@in_vchApplicationID		VARCHAR(40)  = NULL,
	@in_vchWhMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchWhID					NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOrderNumber			NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwner				NVARCHAR(40),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchParentLPN			NVARCHAR(25) = NULL,
	@in_vchLPN					NVARCHAR(25) = NULL,
	@in_vchLocalID				VARCHAR(40)  = NULL,
	@in_vchDeviceID				NVARCHAR(25) = NULL,
	@in_vchUserID				NVARCHAR(25) = NULL,
	@out_vchErrorCode			VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_intRound INT = 0
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	--จะใช้เมื่อมีการ Override ที่ LPN ใหม่
	DECLARE @v_vchNewLocationID	UNIQUEIDENTIFIER,
			@v_vchNewLocation	NVARCHAR(50),
			@v_vchNewParentLPN 	NVARCHAR(25)

	------------------------------------------------------
	-- Check LPN in Picking Detail
	------------------------------------------------------
	IF NOT EXISTS (SELECT pickDT.lpn FROM t_wms_outbound_pick_detail pickDT
				   WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
				   AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				   AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
				   AND pickDT.is_override = 'NO'
				   AND ROUND(ISNULL(pickDT.quantity_pick,0),@v_intRound) < ROUND(ISNULL(pickDT.quantity_plan,0),@v_intRound))
	BEGIN
		------------------------------------------------------------------------------
		-- Check LPN ใน Inventory
		------------------------------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
				GOTO EXIT_LABEL
			END

		------------------------------------------------------------------------------
		-- กรณีที่ไม่พบ LPN ใน Pick Detail
		-- Check Rule 'WH Rule Allow Override lpn'
		------------------------------------------------------------------------------
		IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_ALLOW_OVERRIDE_LPN' AND is_active = 'YES') = 'YES'
			BEGIN
				-- Override LPN
				EXEC usp_outbound_override_lpn  @in_vchApplicationID	 = @in_vchApplicationID	
												,@in_vchWhMasterID		 = @in_vchWhMasterID		
												,@in_vchWhID			 = @in_vchWhID				
												,@in_vchOutboundMasterID = @in_vchOutboundMasterID		
												,@in_vchOrderNumber		 = @in_vchOrderNumber			
												,@in_vchOwnerID			 = @in_vchOwnerID
												,@in_vchOwner			 = @in_vchOwner
												,@in_vchLPN				 = @in_vchLPN		
												,@in_vchLocalID			 = @in_vchLocalID	
												,@in_vchDeviceID		 = @in_vchDeviceID
												,@in_vchUserID			 = @in_vchUserID	
												,@out_vchLocationID		 = @v_vchNewLocationID OUTPUT
												,@out_vchLocation		 = @v_vchNewLocation OUTPUT
												,@out_vchParentLPN		 = @v_vchNewParentLPN OUTPUT
												,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT	
												,@out_vchErrorMsg 		 = @out_vchErrorMsg OUTPUT	
				IF (@out_vchErrorCode = '0')
					BEGIN
						-- Clear ค่าก่อนส่งเข้า PDA
						SET @out_vchErrorCode = ''
						SET @out_vchErrorMsg = ''
						GOTO RULE_PICK_MODE;
					END
				ELSE
					BEGIN
						--หามีการ Error จาก Store override LPN
						RETURN;
					END
			END
		ELSE
			BEGIN
				SET @out_vchErrorCode = 'INFO-RULE-NOT-ALLOW-OVERRIDE'
				GOTO EXIT_LABEL
			END
	END

	------------------------------------------------------
	-- Check LPN in Scaned Location
	------------------------------------------------------
	IF NOT EXISTS (SELECT pickDT.lpn FROM t_wms_outbound_pick_detail pickDT
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND pickDT.location_id = @in_vchLocationID
					AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
					AND pickDT.is_override = 'NO')
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LPN-IN-LOCATION'
			GOTO EXIT_LABEL
		END
	ELSE
		BEGIN
			GOTO RULE_PICK_MODE;
		END

	-------------------------------------------------- 
	-- Check Rule 'SELECT PICK MODE'				   
	-------------------------------------------------- 
	RULE_PICK_MODE: 
		SET @out_vchNextScreen = 'ITEM_NUMBER'
				
	SELECT @v_vchNewLocationID	AS location_id
		,@v_vchNewLocation		AS location
		,@v_vchNewParentLPN		AS parent_lpn

	RETURN;


	/* Override : Option
	------------------------------------------------------
	-- Check LPN in Scaned Location
	------------------------------------------------------ 
	IF NOT EXISTS (SELECT pickDT.lpn FROM t_wms_outbound_pick_detail pickDT
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND pickDT.location_id = @in_vchLocationID
					AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
					AND pickDT.is_override = 'NO')
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-EXIST-LPN-IN-LOCATION'
			GOTO EXIT_LABEL
		END

	SET @out_vchNextScreen = 'ITEM_NUMBER' 
	RETURN;
	*/

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_lpn_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_lpn_final_screen]
(
	@in_vchApplicationID		VARCHAR(40)  = NULL,
	@in_vchWhMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchWhID					NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER, 
	@in_vchLPN					NVARCHAR(25) = NULL,
	@in_vchLocalID				VARCHAR(40)  = NULL, 
	@in_vchUserID				NVARCHAR(25) = NULL,
	@out_vchErrorCode			VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_intRound INT = 0
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	------------------------------------------------------
	-- Check LPN in Picking Detail
	------------------------------------------------------
	IF NOT EXISTS (SELECT TOP 1 outbound_pick_detail_id FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ROUND(ISNULL(pickDT.quantity_pick,0),@v_intRound) < ROUND(ISNULL(pickDT.quantity_plan,0),@v_intRound)
					AND pickDT.is_override = 'NO'
					AND ISNULL(pickDT.lpn,'') <> '')
		BEGIN 
			SET @out_vchNextScreen = 'LPN' 
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END
				 
	RETURN; 

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_lpn_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_lpn_location]
(
	@in_vchApplicationID		VARCHAR(40)  = NULL,
	@in_vchWhMasterID			UNIQUEIDENTIFIER  = NULL,
	@in_vchWhID					NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50) = NULL,
	@in_vchLocalID				VARCHAR(40)  = NULL, 
	@in_vchUserID				NVARCHAR(25) = NULL,
	@out_vchErrorCode			VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_intRound			INT = 0,
			@v_vchLPNControl	NVARCHAR(3),
			@v_vchLocationID	UNIQUEIDENTIFIER = NULL
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	-------------------------------------------------------
	-- Validate Location in Pick Detail
	-------------------------------------------------------
	SELECT TOP 1 @v_vchLocationID = loc.location_id
		,@v_vchLPNControl = loc.lpn_controlled
	FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
	INNER JOIN t_wms_location loc WITH (NOLOCK) ON pickDT.location_id = loc.location_id
	WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
	AND loc.location = @in_vchLocation 

	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLocation,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
 
	IF @v_vchLPNControl = 'NO'
		BEGIN
			SET @out_vchErrorCode = 'LOCATION_NOT_CONTROL_LPN_CANNOT_PICK'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLocation,'@param2','@param3','@param4','@param5')	
			RETURN;
		END

	SET @out_vchNextScreen = 'LPN'	
	SELECT @v_vchLocationID AS location_id
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
