/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_lpn_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_lpn_order_number]
(
	@in_vchApplicationID		VARCHAR(40) = null,
	@in_vchWhMasterID			UNIQUEIDENTIFIER  = null,
	@in_vchWarehouse			NVARCHAR(25) = null,
	@in_vchDeviceID				NVARCHAR(50) = null,
	@in_vchUserID				NVARCHAR(25) = null,
	@in_vchOutboundOrderNumber	NVARCHAR(50) = null,
	@in_vchLocalID				VARCHAR(40) = null,
	@out_vchErrorCode			VARCHAR(50) OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(40)= NULL,
			@v_vchOrderStatus			NVARCHAR(10)= NULL,
			@v_vchPickBy				NVARCHAR(25)= NULL,
			@v_vchContainerNo			NVARCHAR(50)= NULL,
			@v_intRound					INT = 0

	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id 
		, @v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
		, @v_vchOwnerID = obMS.owner_id
		, @v_vchOwnerCode = own.owner_code
		, @v_vchOrderStatus = obMS.order_status
		, @v_vchPickBy = obMS.pick_by
		, @v_vchContainerNo = obMS.container_no
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	LEFT JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	LEFT JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	WHERE obMS.outbound_order_number = @in_vchOutboundOrderNumber
	AND obMS.wh_master_id = @in_vchWhMasterID
	AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))

	------------------------------------------------------
	-- Vaildate Outbound Order Number in System
	------------------------------------------------------
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END 

	------------------------------------------------------
	-- Vaildate Pick list Number in System
	------------------------------------------------------
	IF (@v_vchOutboundPickMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'PICKLIST_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	------------------------------------------------------------------------------
	-- Validate Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL,'PICKED'
	------------------------------------------------------------------------------
	IF (@v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'OUTBOUND_STATUS_CANNOT_PICK'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOrderStatus,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	-- Validate Multiple user pick
	------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO'
		BEGIN
			IF @v_vchPickBy <> @in_vchUserID
				BEGIN
					SET @out_vchErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')			
					RETURN;
				END 
		END

	--Check picklist have lpn
	IF NOT EXISTS (SELECT 1 FROM t_wms_outbound_pick_detail 
				   WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
				   AND ISNULL(lpn,'') <> ''
				   AND is_override = 'NO'
				   AND ROUND(ISNULL(quantity_pick,0),@v_intRound) < ROUND(ISNULL(quantity_plan,0),@v_intRound))
		BEGIN
			SET @out_vchErrorCode = 'THERE_IS_NO_LPN_TO_PICK'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	SET @out_vchNextScreen = 'LOCATION'

	------------------------------------------------------
	-- for next screen
	------------------------------------------------------
	SELECT @v_vchOutboundMasterID		AS outbound_order_master_id
		, @v_vchOutboundPickMasterID	AS outbound_pick_master_id
		, @v_vchOwnerID					AS owner_id
		, @v_vchOwnerCode				AS owner_code
		, @v_vchContainerNo				AS container_no
	RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_next_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_next_location]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOrderNumber		VARCHAR(50)  = NULL,
	@in_vchLocation			NVARCHAR(40) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLpn				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchItemDesc		NVARCHAR(200) OUTPUT,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE	@v_vchOutboundPickID	UNIQUEIDENTIFIER,
			@v_vchWhItemMasterID	UNIQUEIDENTIFIER   = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER	  = NULL,
			@v_vchItemDesc			NVARCHAR(200) = NULL,
			@v_vchLotControl		NVARCHAR(10)  = NULL,
			@v_vchSNControl			NVARCHAR(10)  = NULL,
			@v_vchExpiryDateControl	NVARCHAR(10)  = NULL,
			@v_vchAttribute1Control	NVARCHAR(10)  = NULL,
			@v_vchAttribute2Control	NVARCHAR(10)  = NULL,
			@v_vchAttribute3Control	NVARCHAR(10)  = NULL,
			@v_vchAttribute4Control	NVARCHAR(10)  = NULL,
			@v_vchAttribute5Control	NVARCHAR(10)  = NULL,
			@v_vchUomPrompt			NVARCHAR(40)  = NULL
		
	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number และ ใน Cross Ref
	--------------------------------------------------------------------
	SELECT @v_vchWhItemMasterID = whItem.wh_item_master_id
		, @v_vchItemMasterID = item.item_master_id
		, @v_vchItemDesc = description
		, @v_vchLotControl = lot_control
		, @v_vchSNControl = sn_control
		, @v_vchExpiryDateControl = expiry_date_control
		, @v_vchAttribute1Control = attribute1_control
		, @v_vchAttribute2Control = attribute2_control
		, @v_vchAttribute3Control = attribute3_control
		, @v_vchAttribute4Control = attribute4_control
		, @v_vchAttribute5Control = attribute5_control
		, @v_vchUomPrompt = uom_prompt
	FROM  t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
	WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
	AND whItem.wh_master_id = @in_vchWhMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	-------------------------------------------------------------
	-- Validate item in pick detail
	-------------------------------------------------------------
	SELECT @v_vchOutboundPickID = outbound_pick_detail_id
		,@out_vchItemDesc = description
	FROM v_wms_outbound_pick_detail_mini
	WHERE wh_master_id = @in_vchWhMasterID
	AND outbound_order_number = @in_vchOrderNumber
	AND location = @in_vchLocation
	AND is_override = 'NO'
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
	AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
	
	IF (ISNULL(@v_vchOutboundPickID,'') = '')
	BEGIN
		SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST'
		GOTO EXIT_LABEL;
	END

	------------------------------------------------------------------------------
	-- Check Rule 'WH RULES REQUIRE REASON CODE FOR NEXT LOCATION'
	------------------------------------------------------------------------------
	IF (SELECT value FROM t_wms_rule where rule_code = 'RULE_REASON_FOR_NEXT_LOC' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'REASON'
			RETURN;
		END
	ELSE
		BEGIN
			--Put Location on Hold and Create cycle count plan to correct the inventory
			EXEC usp_api_validate_picking_reason
					@in_vchApplicationID = @in_vchApplicationID
					, @in_vchWhMasterID	 = @in_vchWhMasterID
					, @in_vchOrderNumber = @in_vchOrderNumber
					, @in_vchLocation	 = @in_vchLocation	
					, @in_vchParentLPN	 = @in_vchParentLPN	
					, @in_vchLpn		 = @in_vchLpn		
					, @in_vchItemNumber	 = @in_vchItemNumber	
					, @in_vchReason		 = null		
					, @in_vchLocalID	 = @in_vchLocalID	
					, @in_vchDeviceID	 = @in_vchDeviceID	
					, @in_vchUserID		 = @in_vchUserID		
					, @out_vchErrorCode	 = @out_vchErrorCode  OUTPUT
					, @out_vchErrorMsg	 = @out_vchErrorMsg	  OUTPUT
					, @out_vchNextScreen = @out_vchNextScreen OUTPUT

			IF @out_vchErrorCode = '0'
				BEGIN
					SET @out_vchErrorCode = NULL
					SET @out_vchErrorMsg = NULL
				END
			RETURN;
		END 

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT  @v_vchWhItemMasterID	  AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemDesc		  AS item_description
			, @v_vchUomPrompt		  AS uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_order_number]
(
	@in_vchApplicationID	VARCHAR(40) = null,
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = null,
	@in_vchWarehouse		NVARCHAR(25) = null,
	@in_vchDeviceID			NVARCHAR(50) = null,
	@in_vchUserID			NVARCHAR(25) = null,
	@in_vchOrderNumber		NVARCHAR(50) = null,
	@in_vchLocalID			VARCHAR(40) = null,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(40)= NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10)= NULL
	DECLARE @v_vchPickBy			NVARCHAR(25)= NULL
	DECLARE @v_vchContainerNo		NVARCHAR(50)= NULL

	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id 
		, @v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
		, @v_vchOwnerID = obMS.owner_id
		, @v_vchOwnerCode = own.owner_code
		, @v_vchOrderStatus = obMS.order_status
		, @v_vchPickBy = obMS.pick_by
		, @v_vchContainerNo = obMS.container_no
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	LEFT JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	LEFT JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	WHERE obMS.outbound_order_number = @in_vchOrderNumber
	AND obMS.wh_master_id = @in_vchWhMasterID
	AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code IN ('RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING','BLIND_PICK_ORDER_TYPE') AND is_active = 'YES'))

	------------------------------------------------------
	-- Vaildate Outbound Order Number in System
	------------------------------------------------------
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END 

	------------------------------------------------------
	-- Vaildate Pick list Number in System
	------------------------------------------------------
	IF (@v_vchOutboundPickMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'PICKLIST_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	------------------------------------------------------------------------------
	-- Validate Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL,'PICKED'
	------------------------------------------------------------------------------
	IF (@v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'OUTBOUND_STATUS_CANNOT_PICK'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOrderStatus,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	-- Validate Multiple user pick
	------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO'
		BEGIN
			IF @v_vchPickBy <> @in_vchUserID
				BEGIN
					SET @out_vchErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')			
					RETURN;
				END 
		END 

	------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------
	IF (SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			IF ((SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_PICK_MODE' AND is_active = 'YES') = 'YES')
				BEGIN
					SET @out_vchNextScreen = 'PICK_MODE'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LOCATION'
				END
		END

	------------------------------------------------------
	-- for next screen
	------------------------------------------------------
	SELECT @v_vchOutboundMasterID AS outbound_order_master_id
		, @v_vchOutboundPickMasterID AS outbound_pick_master_id
		, @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code
		, @v_vchContainerNo AS container_no
	RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_override_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_override_attribute1]
(
	@in_vchApplicationID	  VARCHAR(40),
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID   UNIQUEIDENTIFIER,
	@in_vchOverLocationID	  UNIQUEIDENTIFIER,
	@in_vchOverLPN			  NVARCHAR(25),
	@in_vchOverWhItemMasterID UNIQUEIDENTIFIER, 
	@in_vchOverLotNumber	  NVARCHAR(50), 
	@in_vchOverExpiryDate	  NVARCHAR(50), 
	@in_vchOverAttribute1	  NVARCHAR(100),
	@in_vchAttribute2Control  VARCHAR(5),
	@in_vchAttribute3Control  VARCHAR(5),
	@in_vchAttribute4Control  VARCHAR(5),
	@in_vchAttribute5Control  VARCHAR(5),
	@in_vchSNControl		  VARCHAR(5),  
	@in_vchLocalID			  VARCHAR(40),
	@out_vchErrorCode		  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		  NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------------------------------
	--Check Item In Picklist
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inv.inventory_id FROM v_wms_inventory_data_by_id inv
					INNER JOIN (SELECT pickDT.wh_item_master_id,invST.inventory_status_id
								FROM t_wms_outbound_pick_master pickMS
								INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
								INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
								INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
								WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
								AND is_override = 'NO'
								AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
								) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id
					WHERE inv.location_id = @in_vchOverLocationID
					AND ISNULL(inv.lpn,'') = ISNULL(@in_vchOverLPN,'')
					AND inv.wh_item_master_id = @in_vchOverWhItemMasterID
					AND ISNULL(inv.lot_number,'') = ISNULL(@in_vchOverLotNumber,'')
					AND ISNULL(inv.expiry_date,'') = ISNULL(@in_vchOverExpiryDate,'')
					AND ISNULL(inv.attribute1,'') = ISNULL(@in_vchOverAttribute1,''))
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE1_DOES_NOT_EXIST_IN_INVENTORY'
			GOTO EXIT_LABEL
		END

	IF (@in_vchAttribute2Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE2'		 
			RETURN;
		END
	IF (@in_vchAttribute3Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE3'		 
			RETURN;
		END
	IF (@in_vchAttribute4Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE4'		 
			RETURN;
		END
	IF (@in_vchAttribute5Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE5'		 
			RETURN;
		END
	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_SERIAL_NUMBER'		 
			RETURN;
		END
	ELSE	
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_UOM_QTY'
			RETURN;
		END 

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_override_attribute2]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_override_attribute2]
(
	@in_vchApplicationID	  VARCHAR(40),
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	  UNIQUEIDENTIFIER,
	@in_vchOverLocationID	  UNIQUEIDENTIFIER,
	@in_vchOverLPN			  NVARCHAR(25),
	@in_vchOverWhItemMasterID UNIQUEIDENTIFIER, 
	@in_vchOverLotNumber	  NVARCHAR(50), 
	@in_vchOverExpiryDate	  NVARCHAR(50), 
	@in_vchOverAttribute1	  NVARCHAR(100),
	@in_vchOverAttribute2	  NVARCHAR(100),
	@in_vchAttribute3Control  VARCHAR(5),
	@in_vchAttribute4Control  VARCHAR(5),
	@in_vchAttribute5Control  VARCHAR(5),
