/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_override_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_override_item_number]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchOverLocationID	UNIQUEIDENTIFIER,
	@in_vchOverLPN			NVARCHAR(25),
	@in_vchOverItemNumber	NVARCHAR(50), 
	@in_vchLocalID			VARCHAR(40),
	@out_vchItemMasterID	UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchWhItemMasterID  UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
		
	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number และ ใน Cross Ref
	--------------------------------------------------------------------
	SELECT TOP 1 @out_vchItemMasterID = item.item_master_id
		, @v_vchItemDesc = description
		, @v_vchLotControl = lot_control
		, @v_vchSNControl = sn_control
		, @v_vchExpiryDateControl = expiry_date_control
		, @v_vchAttribute1Control = attribute1_control
		, @v_vchAttribute2Control = attribute2_control
		, @v_vchAttribute3Control = attribute3_control
		, @v_vchAttribute4Control = attribute4_control
		, @v_vchAttribute5Control = attribute5_control
		, @v_vchUomPrompt = uom_prompt
	FROM t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
	WHERE (item.item_number = @in_vchOverItemNumber OR item.dg_code = @in_vchOverItemNumber OR itemRef.alternate_item_number = @in_vchOverItemNumber)
	AND item.owner_id = @in_vchOwnerID
	AND item.is_active = 'YES'
	IF (@out_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT TOP 1 @out_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @out_vchItemMasterID
	IF @out_vchWhItemMasterID IS NULL
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------------------
	--Check Item In Picklist
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
					INNER JOIN (SELECT pickDT.wh_item_master_id,invST.inventory_status_id
								FROM t_wms_outbound_pick_master pickMS
								INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
								INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
								INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
								WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
								AND is_override = 'NO' 
								AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
								) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id
					WHERE inv.location_id = @in_vchOverLocationID
					AND ISNULL(inv.lpn,'') = ISNULL(@in_vchOverLPN,'')
					AND inv.wh_item_master_id = @out_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_DOES_NOT_EXIST_IN_PICKLIST'
			GOTO EXIT_LABEL
		END

	IF (@v_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_LOT_NUMBER'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchExpiryDateControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_EXPIRY_DATE'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchAttribute1Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE1'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchAttribute2Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE2'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchAttribute3Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE3'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchAttribute4Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE4'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchAttribute5Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ATTRIBUTE5'		 
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_SERIAL_NUMBER'		 
			GOTO NEXT_SCREEN;
		END
	ELSE	
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_UOM_QTY'
			GOTO NEXT_SCREEN;
		END 
	
	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
		SELECT @out_vchWhItemMasterID   AS override_wh_item_master_id
			, @out_vchItemMasterID	  AS override_item_master_id
			, @v_vchItemDesc		  AS override_item_description
			, @v_vchUomPrompt		  AS override_uom_prompt
			, @v_vchLotControl		  AS lot_control
			, @v_vchExpiryDateControl AS expiry_date_control
			, @v_vchSNControl		  AS sn_control
			, @v_vchAttribute1Control AS attribute1_control
			, @v_vchAttribute2Control AS attribute2_control
			, @v_vchAttribute3Control AS attribute3_control
			, @v_vchAttribute4Control AS attribute4_control
			, @v_vchAttribute5Control AS attribute5_control
			, (CASE WHEN @v_vchSNControl = 'FULL' OR @out_vchNextScreen = 'FINAL_SCREEN' THEN 1 ELSE 0 END) AS qty
		RETURN;

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOverItemNumber,'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_override_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_override_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOverLocation		NVARCHAR(50),
	@in_vchLocalID			VARCHAR(40)	 = null,
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchOverrideLocationID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl NVARCHAR(3) = NULL

	SELECT @v_vchOverrideLocationID = location_id
		, @v_vchLPNControl = lpn_controlled
	FROM t_wms_location 
	WHERE wh_master_id = @in_vchWhMasterID 
	AND location = @in_vchOverLocation 
	AND is_active = 'YES' 

	IF (@v_vchOverrideLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	--Override เฉพาะ Item ที่อยู่ใน Picklist
	IF NOT EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
					INNER JOIN (SELECT pickDT.wh_item_master_id,invST.inventory_status_id
								FROM t_wms_outbound_pick_master pickMS
								INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
								INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
								INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
								WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
								AND is_override = 'NO' 
								AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
								) tOutbound ON inv.wh_item_master_id = tOutbound.wh_item_master_id AND inv.inventory_status_id = tOutbound.inventory_status_id
					WHERE inv.location_id = @v_vchOverrideLocationID)
		BEGIN
			SET @out_vchErrorCode = 'OVERRIDE_LOCATION_DOES_NOT_EXIST_ITEM'
			GOTO EXIT_LABEL
		END
	
	-------------------------------------------------------
	-- LPN Control and Wh Rule Parent LPN
	-------------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_LPN'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'OVERRIDE_ITEM_NUMBER'
		END
		 
	SELECT @v_vchOverrideLocationID AS override_location_id
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
