/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_reason]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_reason]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL, 
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLpn				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER  = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchReasonCode		NVARCHAR(20) = NULL,--CODE
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	------------------------------------------------------------------------------
	-- Put location on Hold and create cycle count plan to correct the inventory.
	------------------------------------------------------------------------------
	EXEC usp_outbound_pick_next_location  @in_vchApplicationID	   = @in_vchApplicationID	
										, @in_vchDeviceID		   = @in_vchDeviceID			
										, @in_vchUserID			   = @in_vchUserID			
										, @in_vchWhMasterID		   = @in_vchWhMasterID	
										, @in_vchOutboundMasterID  = @in_vchOutboundMasterID
										, @in_vchOutboundPickMasterID= @in_vchOutboundPickMasterID
										, @in_vchLocationID		   = @in_vchLocationID			
										, @in_vchParentLPN		   = @in_vchParentLPN		
										, @in_vchLpn			   = @in_vchLpn				
										, @in_vchWhItemMasterID	   = @in_vchWhItemMasterID	
										, @in_vchItemMasterID	   = @in_vchItemMasterID	
										, @in_vchReasonCode		   = @in_vchReasonCode		
										, @out_ErrorCode		   = @out_vchErrorCode	OUTPUT	
										, @out_ErrorMessage		   = @out_vchErrorMsg	OUTPUT

	IF (@out_vchErrorCode <> '0')
		BEGIN
			RETURN;
		END

	-------------------------------------------------------------
	-- Check another location
	-- Validate item in pick detail
	-------------------------------------------------------------
	IF EXISTS(SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_master pickMS
				LEFT JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_detail_id 
				WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
				AND pickDT.is_override = 'NO'
				AND pickDT.wh_item_master_id = @in_vchWhItemMasterID
				AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0))					
		BEGIN
			--กรณีที่ยังมี item ที่สามารถ หยิบได้อยู่
			SET @out_vchNextScreen = 'LOCATION'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'OUTBOUND_ORDER'
		END
END
 
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_picking_serial_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_picking_serial_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER  = NULL,
	@in_vchFork				NVARCHAR(40) = NULL,
	@in_vchLocation			NVARCHAR(40) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLpn				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(100)= NULL,
	@in_vchExpDate			NVARCHAR(50) = NULL,
	@in_vchSerialNumber		NVARCHAR(100)= NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchAttribute1		NVARCHAR(100)= NULL,
	@in_vchAttribute2		NVARCHAR(100)= NULL,
	@in_vchAttribute3		NVARCHAR(100)= NULL,
	@in_vchAttribute4		NVARCHAR(100)= NULL,
	@in_vchAttribute5		NVARCHAR(100)= NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @v_vchWhItemMasterID		UNIQUEIDENTIFIER	= NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER	= NULL,
			@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER	= NULL,
			@v_vchDefaultItemStatus		NVARCHAR(40)		= NULL,
			@v_vchItemDesc				NVARCHAR(200)		= NULL,
			@v_vchUOMPrompt				NVARCHAR(10)		= NULL,
			@v_fltQuantityEnter			INT,		--สำหรับนับจำนวน Serial Number
			@v_fltQuantityPlan			FLOAT,
			@v_fltQuantityPick			FLOAT,
			@sql_exec					NVARCHAR(1000),
			@ParameterDefinition		NVARCHAR(100)

	SELECT @v_vchItemMasterID = item.item_master_id
		,@v_vchWhItemMasterID = whItem.wh_item_master_id
	FROM t_wms_wh_item whItem
	LEFT JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE whItem.wh_master_id = @in_vchWhMasterID 
	AND (item.item_number = @in_vchItemNumber or item.dg_code = @in_vchItemNumber or cref.alternate_item_number = @in_vchItemNumber)
	AND owner_id = @in_vchOwnerID


	IF @in_vchSerialNumber <> 'ALL'
		BEGIN
			-------------------------------------------------
			-- กรณี Pick เป็น Serial
			-------------------------------------------------
			SELECT DISTINCT @v_vchOutboundPickDetailID = outbound_pick_detail_id
				, @v_vchItemMasterID = item_master_id
				, @v_vchDefaultItemStatus = default_item_status
				, @v_vchItemDesc = description
			FROM v_wms_outbound_pick_detail_mini
			WHERE wh_master_id = @in_vchWhMasterID
			AND outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND owner_id = @in_vchOwnerID
			AND location = @in_vchLocation
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND serial_number = @in_vchSerialNumber
	
			IF (@v_vchOutboundPickDetailID IS NOT NULL)
			BEGIN
				SET @out_vchErrorCode = 'INFO-SN-DUPLICATED'
				GOTO EXIT_LABEL;
			END

			-------------------------------------------------
			-- กรณี Pick เป็น Serial จำนวนที่หยิบคือ 1
			-------------------------------------------------
			SET @v_fltQuantityEnter = 1
		END
	ELSE
		BEGIN
			-------------------------------------------------
			--กรณี Pick All Serial
			--Get quantiy of serial in inventory table
			------------------------------------------------- 
			SELECT @v_fltQuantityEnter = COUNT(DISTINCT inv.serial_number)
			FROM v_wms_inventory_data_by_serial inv							 
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.owner_id = @in_vchOwnerID
			AND inv.wh_item_master_id = @v_vchWhItemMasterID
			AND inv.location = @in_vchLocation
			and (case when ISNULL(@in_vchParentLPN,'') <> '' then inv.parent_lpn  else '' end) = (case when ISNULL(@in_vchParentLPN,'') <> '' then ISNULL(@in_vchParentLPN,'')  else '' end)
			and (case when ISNULL(@in_vchLPN,'') <> '' then inv.lpn  else '' end) = (case when ISNULL(@in_vchLPN,'') <> '' then ISNULL(@in_vchLPN,'')  else '' end)
			and (case when ISNULL(@in_vchLotNumber,'') <> '' then inv.lot_number  else '' end) = (case when ISNULL(@in_vchLotNumber,'') <> '' then ISNULL(@in_vchLotNumber,'')  else '' end)
			and (case when ISNULL(@in_vchExpDate,'') <> '' then inv.expiry_date  else '' end) = (case when ISNULL(@in_vchExpDate,'') <> '' then ISNULL(@in_vchExpDate,'')  else '' end)
			and (case when ISNULL(@in_vchAttribute1,'') <> '' then inv.attribute1  else '' end) = (case when ISNULL(@in_vchAttribute1,'') <> '' then ISNULL(@in_vchAttribute1,'')  else '' end)
			and (case when ISNULL(@in_vchAttribute2,'') <> '' then inv.attribute2  else '' end) = (case when ISNULL(@in_vchAttribute2,'') <> '' then ISNULL(@in_vchAttribute2,'')  else '' end)
			and (case when ISNULL(@in_vchAttribute3,'') <> '' then inv.attribute3  else '' end) = (case when ISNULL(@in_vchAttribute3,'') <> '' then ISNULL(@in_vchAttribute3,'')  else '' end)
			and (case when ISNULL(@in_vchAttribute4,'') <> '' then inv.attribute4  else '' end) = (case when ISNULL(@in_vchAttribute4,'') <> '' then ISNULL(@in_vchAttribute4,'')  else '' end)
			and (case when ISNULL(@in_vchAttribute5,'') <> '' then inv.attribute5  else '' end) = (case when ISNULL(@in_vchAttribute5,'') <> '' then ISNULL(@in_vchAttribute5,'')  else '' end)

		END

 

	------------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------------
	SELECT @v_vchItemDesc		 AS item_description
		,@v_vchDefaultItemStatus AS default_item_status
		,@v_fltQuantityPlan		 AS quantity_plan
		,@v_fltQuantityPick		 AS quantity_pick
		,@v_vchUOMPrompt		 AS uom_prompt

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchOwnerCode		NVARCHAR(40),
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus		NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(40),
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50),	
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(50) = NULL,
	@in_vchAttribute2		NVARCHAR(50) = NULL,
	@in_vchAttribute3		NVARCHAR(50) = NULL,
	@in_vchAttribute4		NVARCHAR(50) = NULL,
	@in_vchAttribute5		NVARCHAR(50) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_fltQuantity			FLOAT,
	@in_vchLocalID			VARCHAR(40),
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @Round					INT
		DECLARE @v_vchLPNControl		NVARCHAR(3)  = NULL
		DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
		DECLARE @v_vchLotControl		VARCHAR(5) = NULL
		DECLARE @v_vchSNControl			VARCHAR(5) = NULL
		DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
		DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
		DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'

		-------------------------------------------------------
		-- Check LPN Controlled
		-------------------------------------------------------
		IF (@v_vchLPNControl = 'YES')
			BEGIN
				IF ISNULL(@in_vchLPN,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'LPN'
						GOTO NEXT_SCREEN;
					END
				IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
								WHERE wh_master_id = @in_vchWhMasterID
								AND owner_id = @in_vchOwnerID
								AND inventory_status_id = @in_vchInvStatusID
								AND location_id = @in_vchLocationID
								AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
								AND lpn = @in_vchLPN)
					BEGIN
						SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
						GOTO EXIT_LABEL;
					END 
			END
			
		-------------------------------------------------------
		-- Get Item Master ID & Get Item Warehouse Master ID
		-------------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
			, @v_vchItemDesc = description
			, @v_vchLotControl = lot_control
			, @v_vchSNControl = sn_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control
			, @v_vchUomPrompt = uom_prompt
			, @v_vchItemIsActive = item.is_active
		FROM  t_wms_item item
		INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 		LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @in_vchOwnerID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				GOTO EXIT_LABEL;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
		IF @v_vchWhItemMasterID IS NULL
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				GOTO EXIT_LABEL;
			END
			 
		-------------------------------------------------------
		--Check item in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					   AND wh_item_master_id = @v_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'LOT_NUMBER'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchExpiryDateControl = 'FULL' 
			BEGIN
				IF ISNULL(@in_vchExpiryDate,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'EXPIRY_DATE'
						GOTO NEXT_SCREEN;
					END
				SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			END

		IF @v_vchAttribute1Control = 'FULL' AND  ISNULL(@in_vchAttribute1,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE1'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE2'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE3'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE4'
				GOTO NEXT_SCREEN;
			END

		IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
			BEGIN
				SET @out_vchNextScreen = 'ATTRIBUTE5'
				GOTO NEXT_SCREEN;
			END

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				IF ISNULL(@in_vchSerialNumber,'') = ''
					BEGIN
						SET @out_vchNextScreen = 'SERIAL_NUMBER'
						GOTO NEXT_SCREEN;
					END
				ELSE
					BEGIN
						-------------------------------------------------------
						--Check data [Inventory Table]
						-------------------------------------------------------
						IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_serial_by_id
										WHERE wh_master_id = @in_vchWhMasterID
										AND location_id = @in_vchLocationID
										AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
										AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
										AND wh_item_master_id = @v_vchWhItemMasterID
										AND owner_id = @in_vchOwnerID
										AND inventory_status_id = @in_vchInvStatusID
										AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
										AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
										AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
										AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
										AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
										AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
										AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
										AND serial_number = @in_vchSerialNumber)
							BEGIN
								SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-INVENTORY'
								GOTO EXIT_LABEL;
							END
					END
			END
		ELSE
			BEGIN
				-------------------------------------------------------
				--Check data [Inventory Table]
				-------------------------------------------------------
				IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
								WHERE wh_master_id = @in_vchWhMasterID
								AND location_id = @in_vchLocationID
								AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
								AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
								AND wh_item_master_id = @v_vchWhItemMasterID
								AND owner_id = @in_vchOwnerID
								AND inventory_status_id = @in_vchInvStatusID
								AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
								AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
								AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
								AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
								AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
								AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
								AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
					BEGIN
						SET @out_vchErrorCode = 'NOT_FOUND_INVENTORY_DATA'
						GOTO EXIT_LABEL;
					END

				SET @out_vchNextScreen = 'UOM_QTY'
				GOTO NEXT_SCREEN;
			END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchItemMasterID		AS item_master_id
		, @v_vchWhItemMasterID		AS wh_item_master_id 
		, @v_vchItemDesc			AS item_description
		, @v_vchLotControl			AS lot_control
		, @v_vchSNControl		    AS sn_control
		, @v_vchExpiryDateControl	AS expiry_date_control
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control
		, @v_vchUomPrompt			AS uom_prompt
		, @in_fltQuantity			AS display_default_qty
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchParentLPN,@in_vchLPN,@in_vchLotNumber,@in_vchExpiryDate)

END

		
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_attribute1]
(
	@in_vchApplicationID     VARCHAR(40),
	@in_vchLocalID		     VARCHAR(40),
	@in_vchWhMasterID	     UNIQUEIDENTIFIER,
	@in_vchOwnerID		     UNIQUEIDENTIFIER,
	@in_vchLocationID	     UNIQUEIDENTIFIER,
	@in_vchInvStatusID	     UNIQUEIDENTIFIER,
	@in_vchParentLPN	     NVARCHAR(25),
	@in_vchLPN			     NVARCHAR(25),
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER,
	@in_vchLotNumber	     NVARCHAR(50),
	@in_vchExpiryDate		 NVARCHAR(20) = NULL, 
	@in_vchAttribute1		 NVARCHAR(100),
	@in_vchAttribute2Control VARCHAR(5),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchSNControl		 VARCHAR(5),
	@out_vchErrorCode		 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)	OUTPUT
)
AS
BEGIN	
SET NOCOUNT ON;
		-------------------------------------------------------
		--Check Expiry Date in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					   AND wh_item_master_id = @in_vchWhItemMasterID
					   AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					   AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					   AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-ATTRIBUTE1-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------------
		-- Check Lot Control
		----------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl		= NULL
									,@in_vchExpiryDateControl	= NULL
									,@in_vchAttribute1Control	= NULL
									,@in_vchAttribute2Control	= @in_vchAttribute2Control
									,@in_vchAttribute3Control	= @in_vchAttribute3Control
									,@in_vchAttribute4Control	= @in_vchAttribute4Control
									,@in_vchAttribute5Control	= @in_vchAttribute5Control
									,@in_vchSNControl			= @in_vchSNControl
									,@in_vchIsCheckLot			= 'NO'
									,@in_vchIsCheckExpiryDate	= 'NO' 
									,@in_vchIsCheckAttribute1	= 'NO'
									,@in_vchIsCheckAttribute2	= 'YES'
									,@in_vchIsCheckAttribute3	= 'NO'
									,@in_vchIsCheckAttribute4	= 'NO'
									,@in_vchIsCheckAttribute5	= 'NO'
									,@in_vchIsCheckSN			= 'NO'
									,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
			
		RETURN;

	-----------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchAttribute1,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_attribute2]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_attribute2]
(
	@in_vchApplicationID     VARCHAR(40),
	@in_vchLocalID		     VARCHAR(40),
	@in_vchWhMasterID	     UNIQUEIDENTIFIER,
	@in_vchOwnerID		     UNIQUEIDENTIFIER,
	@in_vchLocationID	     UNIQUEIDENTIFIER,
	@in_vchInvStatusID	     UNIQUEIDENTIFIER,
	@in_vchParentLPN	     NVARCHAR(25),
	@in_vchLPN			     NVARCHAR(25),
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER,
	@in_vchLotNumber	     NVARCHAR(50),
	@in_vchExpiryDate		 NVARCHAR(20) = NULL, 
	@in_vchAttribute1		 NVARCHAR(100),
	@in_vchAttribute2		 NVARCHAR(100),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchSNControl		 VARCHAR(5),
	@out_vchErrorCode		 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)	OUTPUT
)
AS
BEGIN	
	SET NOCOUNT ON;
		-------------------------------------------------------
		--Check Expiry Date in source location [Inventory Table]
		-------------------------------------------------------
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					   WHERE wh_master_id = @in_vchWhMasterID
					   AND owner_id = @in_vchOwnerID
					   AND inventory_status_id = @in_vchInvStatusID
					   AND location_id = @in_vchLocationID
					   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					   AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					   AND wh_item_master_id = @in_vchWhItemMasterID
					   AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					   AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					   AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					   AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST-IN-INVENTORY'
				GOTO EXIT_LABEL;
			END

		----------------------------------------------------------
		-- Check Lot Control
		----------------------------------------------------------
		EXEC usp_validate_item_control @in_vchLotControl		= NULL
									,@in_vchExpiryDateControl	= NULL
									,@in_vchAttribute1Control	= NULL
									,@in_vchAttribute2Control	= NULL
									,@in_vchAttribute3Control	= @in_vchAttribute3Control
									,@in_vchAttribute4Control	= @in_vchAttribute4Control
									,@in_vchAttribute5Control	= @in_vchAttribute5Control
									,@in_vchSNControl			= @in_vchSNControl
									,@in_vchIsCheckLot			= 'NO'
									,@in_vchIsCheckExpiryDate	= 'NO' 
									,@in_vchIsCheckAttribute1	= 'NO'
									,@in_vchIsCheckAttribute2	= 'NO'
									,@in_vchIsCheckAttribute3	= 'YES'
									,@in_vchIsCheckAttribute4	= 'NO'
									,@in_vchIsCheckAttribute5	= 'NO'
									,@in_vchIsCheckSN			= 'NO'
									,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
			
		RETURN;


	--------------------------------------------------------
	-- Exit the Process to get resource
	--------------------------------------------------------
