	@in_vchOwnerID		 UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus	 NVARCHAR(50) = NULL, 
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchInvStatusID UNIQUEIDENTIFIER = NULL
	
	-------------------------------------------------------
	--Check status in master
	-------------------------------------------------------
	SELECT TOP 1 @v_vchInvStatusID = inventory_status_id
		,@in_vchInvStatus = inv_status
	FROM t_wms_inventory_status
	WHERE inv_status = @in_vchInvStatus
	AND is_active = 'YES' 
	IF (@v_vchInvStatusID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchInvStatus,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND inventory_status_id = @v_vchInvStatusID)
		BEGIN
			SET @out_vchErrorCode = 'INVENTORY_NOT_FOUND'
			GOTO EXIT_LABEL;
		END


	------------------------------------------------------------------------------
	-- Check LPN Controlled
	------------------------------------------------------------------------------
	IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID) = 'YES')
		BEGIN
			------------------------------------------------------------------------------
			-- Check Rule Parent LPN
			------------------------------------------------------------------------------
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES')
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			GOTO NEXT_SCREEN;
		END

	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInvStatusID AS inventory_status_id
		, @in_vchInvStatus	AS inv_status 
	RETURN;

	--------------------------------------------------------
	-- Exit the Process to get resource
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_location]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchOwnerCode	 NVARCHAR(40),
	@in_vchLocation		 NVARCHAR(50),
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOwnerID		UNIQUEIDENTIFIER = NULL 
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl	VARCHAR(3) = NULL
	DECLARE @v_vchLocType		NVARCHAR(20) = NULL
	DECLARE @v_vchInvStatusID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus		NVARCHAR(50) = NULL 

	IF (ISNULL(@in_vchOwnerCode,'') = '')
		BEGIN
			SELECT TOP 1 @v_vchOwnerID = owner_id, @in_vchOwnerCode = owner_code FROM t_wms_owner WHERE is_active = 'YES'
		END
	ELSE
		BEGIN
			SELECT TOP 1 @v_vchOwnerID = owner_id, @in_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @in_vchOwnerCode AND is_active = 'YES'
		END
	
	-------------------------------------------------------
	-- Validate Location Master
	-------------------------------------------------------
	SELECT TOP 1 @v_vchLocationID = location_id
		,@v_vchLocType = loc_type
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location 
	WHERE wh_master_id = @in_vchWhMasterID
	AND location = @in_vchLocation
	AND is_active = 'YES'

	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			GOTO EXIT_LABEL
		END
		 
	IF EXISTS (SELECT value FROM t_wms_rule WHERE rule_code = 'LOCATION_TYPE_NOT_MOVE_ITEM' AND value = @v_vchLocType AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-ALLOW-MOVE'
			GOTO EXIT_LABEL
		END

	--Check Status Inventory ถ้ามีมากกว่า 1 Status ให้เลือก Status ก่อน
	SELECT DISTINCT @v_vchInvStatusID = inv.inventory_status_id 
		,@v_vchInvStatus = invST.inv_status
	FROM t_wms_inventory inv
	INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
	WHERE inv.wh_master_id = @in_vchWhMasterID 
	AND inv.owner_id = @v_vchOwnerID 
	AND inv.location_id = @v_vchLocationID 
	IF @@ROWCOUNT > 1
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			------------------------------------------------------------------------------
			-- Check LPN Controlled
			------------------------------------------------------------------------------
			IF (@v_vchLPNControl = 'YES')
				BEGIN
					------------------------------------------------------------------------------
					-- Check Rule Parent LPN
					------------------------------------------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES')
						BEGIN
							SET @out_vchNextScreen = 'PARENT_LPN'
							GOTO NEXT_SCREEN;
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'LPN'
							GOTO NEXT_SCREEN;
						END
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER'
					GOTO NEXT_SCREEN;
				END
		END
	

	NEXT_SCREEN:
	SELECT @v_vchLocationID AS source_location_id
		, @v_vchInvStatusID AS inventory_status_id
		, @v_vchInvStatus	AS inv_status
		, @v_vchOwnerID		AS owner_id
		, @in_vchOwnerCode	AS owner_code
	RETURN;

	-------------------------------------------------------
	-- Exit the Process to get resource					   
	-------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_lot_number]
(
	@in_vchApplicationID     VARCHAR(40),
	@in_vchLocalID		     VARCHAR(40),
	@in_vchWhMasterID	     UNIQUEIDENTIFIER,
	@in_vchOwnerID		     UNIQUEIDENTIFIER,
	@in_vchLocationID	     UNIQUEIDENTIFIER,
	@in_vchInvStatusID	     UNIQUEIDENTIFIER,
	@in_vchParentLPN	     NVARCHAR(25),
	@in_vchLPN			     NVARCHAR(25),
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER,
	@in_vchLotNumber	     NVARCHAR(50),
	@in_vchExpiryDateControl VARCHAR(5),
	@in_vchAttribute1Control VARCHAR(5),
	@in_vchAttribute2Control VARCHAR(5),
	@in_vchAttribute3Control VARCHAR(5),
	@in_vchAttribute4Control VARCHAR(5),
	@in_vchAttribute5Control VARCHAR(5),
	@in_vchSNControl		 VARCHAR(5),
	@out_vchErrorCode	     VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	     NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	     NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	-------------------------------------------------------
	--Check lot number in source location [Inventory Table]
	-------------------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND inventory_status_id = @in_vchInvStatusID
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
	BEGIN
		SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST-IN-INVENTORY'
		GOTO EXIT_LABEL;
	END

	----------------------------------------------------------
	-- Check Lot Control
	----------------------------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl		= NULL
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'YES' 
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	RETURN;

-----------------------------------------------------
-- Exit the Process
-----------------------------------------------------
EXIT_LABEL:
	IF (@out_vchErrorCode IS NOT NULL)
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLotNumber,'@param2','@param3','@param4','@param5')		
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_lpn]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchOwnerID		 UNIQUEIDENTIFIER,
	@in_vchLocationID	 UNIQUEIDENTIFIER,
	@in_vchInvStatusID	 UNIQUEIDENTIFIER,
	@in_vchParentLPN	 NVARCHAR(25),
	@in_vchLPN			 NVARCHAR(25),
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master
	--------------------------------------------------------------------
	IF EXISTS (SELECT item_number FROM t_wms_item WHERE item_number = @in_vchLPN)
		BEGIN
			--LPN ซ้ำกับ Item Number
			SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE-ITEM-NUMBER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END

	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory 
				   WHERE wh_master_id = @in_vchWhMasterID
				   AND owner_id = @in_vchOwnerID
				   AND inventory_status_id = @in_vchInvStatusID
				   AND location_id = @in_vchLocationID
				   AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				   AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
	
	SET @out_vchNextScreen = 'ITEM_NUMBER'
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
