/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_serial_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_serial_number]
(
	@in_vchApplicationID  VARCHAR(40),
	@in_vchLocalID		  VARCHAR(40),
	@in_vchWhMasterID	  UNIQUEIDENTIFIER,
	@in_vchOwnerID		  UNIQUEIDENTIFIER,
	@in_vchLocationID	  UNIQUEIDENTIFIER,
	@in_vchInvStatusID	  UNIQUEIDENTIFIER,
	@in_vchParentLPN	  NVARCHAR(25),
	@in_vchLPN			  NVARCHAR(25),
	@in_vchWhItemMasterID UNIQUEIDENTIFIER,
	@in_vchItemMasterID	  UNIQUEIDENTIFIER,
	@in_vchLotNumber	  NVARCHAR(50),
	@in_vchExpiryDate	  NVARCHAR(20) = NULL, 
	@in_vchAttribute1	  NVARCHAR(100),
	@in_vchAttribute2	  NVARCHAR(100),
	@in_vchAttribute3	  NVARCHAR(100),
	@in_vchAttribute4	  NVARCHAR(100),
	@in_vchAttribute5	  NVARCHAR(100),
	@in_vchSerialNumber	  NVARCHAR(100),
	@out_vchErrorCode	  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) OUTPUT
)
AS
BEGIN	
	DECLARE @Round				 INT
	DECLARE @v_vchInventoryID	 UNIQUEIDENTIFIER = NULL

	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
	SELECT @v_vchInventoryID = inventory_id FROM v_wms_inventory_data_serial_by_id
	WHERE wh_master_id = @in_vchWhMasterID
	AND owner_id = @in_vchOwnerID
	AND inventory_status_id = @in_vchInvStatusID
	AND location_id = @in_vchLocationID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
	AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
	AND wh_item_master_id = @in_vchWhItemMasterID
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
	
	-------------------------------------------------------
	--Check Serial Number in source location [Inventory Table]
	-------------------------------------------------------
	IF @v_vchInventoryID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
		 
	--------------------------------------------------------
	-- Validate quantity
	--------------------------------------------------------
	IF (SELECT ROUND(quantity - ISNULL(quantity_allocated,0),@Round) FROM t_wms_inventory WHERE inventory_id = @v_vchInventoryID) = 0
		BEGIN 
			SET @out_vchErrorCode =  'INFO-QTY-MORE-THAN-STOCK'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'FINAL_SCREEN'
	RETURN;
	
	-----------------------------------------------------------------------------------
	-- Exit the Process to get resource
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')


END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_pickup_uom_qty]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_pickup_uom_qty]
(
	@in_vchApplicationID  VARCHAR(40),
	@in_vchLocalID		  VARCHAR(40),
	@in_vchWhMasterID	  UNIQUEIDENTIFIER,
	@in_vchOwnerID		  UNIQUEIDENTIFIER,
	@in_vchLocationID	  UNIQUEIDENTIFIER,
	@in_vchInvStatusID	  UNIQUEIDENTIFIER,
	@in_vchParentLPN	  NVARCHAR(25),
	@in_vchLPN			  NVARCHAR(25),
	@in_vchWhItemMasterID UNIQUEIDENTIFIER,
	@in_vchItemMasterID	  UNIQUEIDENTIFIER,
	@in_vchLotNumber	  NVARCHAR(50),
	@in_vchExpiryDate	  NVARCHAR(20) = NULL, 
	@in_vchAttribute1	  NVARCHAR(100),
	@in_vchAttribute2	  NVARCHAR(100),
	@in_vchAttribute3	  NVARCHAR(100),
	@in_vchAttribute4	  NVARCHAR(100),
	@in_vchAttribute5	  NVARCHAR(100),
	@in_fltQuantity		  FLOAT,
	@in_vchUomPrompt	  NVARCHAR(40),
	@out_vchErrorCode	  VARCHAR(50) = NULL OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500) = NULL OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) = NULL OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_fltInvQuantity		FLOAT
		DECLARE @v_fltConversionFactor	FLOAT
		DECLARE @v_fltMoveQuantity		FLOAT
		DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL

		DECLARE @Round INT = 0 
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		--------------------------------------------
		-- UOM ที่รับเข้ามา
		--------------------------------------------
		SELECT @v_vchItemUomID = item_uom_id
			, @v_fltConversionFactor = conversion_factor
		FROM t_wms_item_uom
		WHERE uom_prompt = @in_vchUOMPrompt
		AND item_master_id = @in_vchItemMasterID
		AND is_active = 'YES'
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'INFO-INVALID-UOM'
				GOTO EXIT_LABEL;
			END

		--------------------------------------------
		-- Get Inventory data
		--------------------------------------------
		SELECT @v_fltInvQuantity = SUM(quantity)
		FROM v_wms_inventory_data_serial_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND inventory_status_id = @in_vchInvStatusID
		AND location_id = @in_vchLocationID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		IF (ISNULL(@v_fltInvQuantity,0) = 0)
			BEGIN
				SET @out_vchErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
				GOTO EXIT_LABEL;
			END
		----------------------------------------------
		--คำนวณจำนวนที่ Move จริง qty * conversion factor
		----------------------------------------------
		SET @v_fltMoveQuantity = ROUND((@in_fltQuantity * @v_fltConversionFactor),@Round)
		IF (@v_fltMoveQuantity > @v_fltInvQuantity)
			BEGIN
				SET @out_vchErrorCode = 'INFO-QTY-MORE-THAN-QTY-INVENTORY'
				GOTO EXIT_LABEL;
			END

		SET @out_vchNextScreen = 'FINAL_SCREEN'
		RETURN;
		
	-----------------------------------------------------------------------------------
	-- Exit the Process to get resource
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		VARCHAR(50)	= NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER	= NULL,
	@in_vchOwnerCode		NVARCHAR(40)= NULL,
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER,
	@in_vchLocationID		UNIQUEIDENTIFIER	= NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchReceiptMode		NVARCHAR(25) = NULL,
	@in_vchItemStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_dtMFGDate			DATE = NULL, 
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100)= NULL,
	@in_vchAttribute2		NVARCHAR(100)= NULL,
	@in_vchAttribute3		NVARCHAR(100)= NULL,
	@in_vchAttribute4		NVARCHAR(100)= NULL,
	@in_vchAttribute5		NVARCHAR(100)= NULL,
	@in_vchUomPrompt		NVARCHAR(40) = NULL,
	@in_fltQuantity			FLOAT,
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount			    INT 
	DECLARE @Round					INT
	DECLARE @v_vchIsSaveTran		VARCHAR(3) = 'NO'
	DECLARE @v_vchLPNControl		NVARCHAR(5) = NULL
	DECLARE @v_vchInvLocation	    NVARCHAR(50) = NULL
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber		NVARCHAR(50)  = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200)= NULL
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_fltQuantityOrder		FLOAT = 0
	DECLARE @v_fltQuantityReceive	FLOAT = 0
	DECLARE @v_intItemShelfLife		INT
	DECLARE @v_dtExpDate			DATETIME
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_vchAlternateID		UNIQUEIDENTIFIER = NULL
	DECLARE	@v_vchCrossRefUOMID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCrossRefUomPrompt	NVARCHAR(40) = NULL

	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	
	-- Screen LPN,Receipt Mode, Item Status, Item Number, Lot, Mfg, Exp.
	SELECT TOP 1 @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active = 'YES'
	 
	----------------------------------------------------
	-- Validate LPN
	----------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			-- ถ้าไม่ได้ส่ง LPN มา ถ้า Return ให้ใส่ LPN
			IF (ISNULL(@in_vchLpn,'') = '')
				BEGIN
					SET @out_vchNextScreen = 'LPN'
					RETURN;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
			--------------------------------------------------------------------
			SELECT @v_vchInvLocation = location 
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
			WHERE inv.lpn = @in_vchLpn
			AND inv.wh_master_id = @in_vchWhMasterID

			IF (ISNULL(@v_vchInvLocation,'') = '' AND @v_vchInvLocation <> @in_vchLocation)
				BEGIN
					--LPN ไม่ได้อยู่ใน Location ที่ Scan
					SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-LPN-IN-LOCATION'
					GOTO EXIT_LABEL;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
			--------------------------------------------------------------------
			EXEC usp_validate_duplicate_lpn @in_vchOrderNumber = @in_vchOrderNumber	
									   ,@in_vchLpn			   = @in_vchLpn			
									   ,@in_vchCheckDupItem    = 'YES'
									   ,@in_vchCheckDupOrder   = 'YES'
									   ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT
	
			IF ISNULL(@out_vchErrorCode,'') <> ''
				BEGIN
					GOTO EXIT_LABEL;
				END
		END

	----------------------------------------------------
	-- ถ้าจะใช้ 2D ต้องไม่ให้เลือก Receipt Mode
	----------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchErrorCode = 'INFO-ALLOW-SELECT-RECEIPT-MODE'
			GOTO EXIT_LABEL;
		END
	
	----------------------------------------------------
	-- ถ้าจะใช้ 2D ต้องไม่ให้เลือก ITEM STATUS
	----------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES' AND @in_vchItemStatusID IS NULL
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			RETURN;
		END

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (ISNULL(@in_vchItemNumber,'') = '')
		BEGIN
			--ถ้าไม่ได้ส่ง Item มาต้อง Return ให้ใส่ Item ก่อน
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			RETURN;
		END

	SET @v_vchItemMasterID = NULL
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		 , @v_vchItemNumber = item.item_number
		 , @v_intItemShelfLife = item.days_to_expire
		 , @v_vchItemDesc = item.description
		 , @v_vchBaseUomPrompt = uom.uom_prompt
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchItemIsActive = item.is_active 
		 , @v_vchAlternateID = itemRef.alternate_id
		 , @v_vchCrossRefUOMID = itemRef.item_uom_id
	FROM t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	left join t_wms_category cate ON item.category_id = cate.category_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	----------------------------------------------------
	-- Validate Warehouse Item
	---------------------------------------------------	
	SET @v_vchWhItemMasterID = NULL
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID AND wh_master_id = @in_vchWhMasterID
	IF @v_vchWhItemMasterID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
		GOTO EXIT_LABEL;
	END

	--Get Uom of Item Cross ref เพื่อนำ uom prompt มา default ที่หน้าจอ ตอนใส่ qty
	IF @v_vchAlternateID IS NOT NULL
		BEGIN
			SELECT TOP 1 @v_vchCrossRefUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_uom_id = @v_vchCrossRefUOMID
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WITH (NOLOCK) WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NOT-EXIST-IN-INBOUND-ORDER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	SELECT @v_fltQuantityOrder = ROUND(SUM(ISNULL(ibDT.quantity_order,0)),@round)
		 ,@v_fltQuantityReceive = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round)
	FROM  t_wms_inbound_detail ibDT
	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.wh_item_master_id = @v_vchWhItemMasterID

	--Get Item Status
	IF @in_vchItemStatusID IS NULL
		BEGIN
			------------------------------------------------------------------
			-- GET DEFAULT ITEM STATUS จาก Plan กรณีที่ไม่มีการ Scan item status
			------------------------------------------------------------------
			DECLARE @v_vchItemStatus NVARCHAR(50)
			SELECT TOP 1 @v_vchItemStatus = default_item_status
			FROM t_wms_inbound_detail WITH (NOLOCK)
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @v_vchWhItemMasterID 
			AND ISNULL(lpn,'') = (CASE ISNULL(lpn,'') WHEN '' THEN '' ELSE @in_vchLPN END)
			AND ISNULL(lot_number,'') = (CASE ISNULL(lot_number,'') WHEN '' THEN '' ELSE @in_vchLotNumber END)
			AND ISNULL(expiry_date,'') = (CASE ISNULL(expiry_date,'') WHEN '' THEN '' ELSE @in_vchExpiryDate END)
			AND ISNULL(quantity_receive,0) < ISNULL(quantity_order,0)
			ORDER BY line_number 
			SELECT @in_vchItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchItemStatus AND is_active = 'YES'
		END

	IF (@v_vchLotControl = 'FULL')
		BEGIN
			IF ISNULL(@in_vchLotNumber,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง LOT มาต้อง Return ให้ใส่ LOT ก่อน
					SET @out_vchNextScreen = 'LOT_NUMBER'
					GOTO NEXT_SCREEN;
				END

			--------------------------------------------------------------------
			-- ถ้าไม่มี Lot ที่เป็นค่าว่าง จะต้อง Check ว่า Lot ที่รับเข้ามาตรงกับ Plan หรือไม่?
			-- ถ้ามี Lot ที่เป็นค่าว่าง ไม่ต้อง Check Lot ใน Plan
			--------------------------------------------------------------------
			IF ('') NOT IN (SELECT ISNULL(lot_number,'') FROM t_wms_inbound_detail WITH (NOLOCK)
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												ELSE quantity_order END)) 
				BEGIN
					---------------------------------------------------
					-- Validate lot number in Plan						 
					---------------------------------------------------
					IF @in_vchLotNumber NOT IN (SELECT DISTINCT lot_number FROM t_wms_inbound_detail WITH (NOLOCK)
												WHERE inbound_order_master_id = @in_vchInboundMasterID
												AND wh_item_master_id = @v_vchWhItemMasterID
												AND (ISNULL(lot_number,'') <> ''))
					BEGIN
						SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST';
						GOTO EXIT_LABEL;
					END		
				END
		END
	ELSE
		BEGIN
			IF @in_vchLotNumber <> ''
				BEGIN
					SET @out_vchErrorCode = 'LOT_NUMBER_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchExpDateControl = 'FULL')
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง EXPIRY_DATE มาต้อง Return ให้ใส่ EXPIRY_DATE ก่อน
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END

			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
			--------------------------------------------------------
			-- ถ้าจะใช้ 2D แต่ไม่ได้ใส่ข้อมูล MFG Date ต้องให้ไปใส่ข้อมูลก่อน
			--------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES' AND ISNULL(@in_dtMFGDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'MFG_DATE'
					GOTO NEXT_SCREEN;
				END
			
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES' AND ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					-----------------------------------------------------
					-- Use mfg date to calculate expiry date
					-----------------------------------------------------
					SELECT @v_dtExpDate = DATEADD(DAY,@v_intItemShelfLife, GETDATE())
					SET @in_vchExpiryDate = CONVERT(VARCHAR,@v_dtExpDate,112)
				END
			
			IF ('') not in (SELECT ISNULL(expiry_date,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END))  
					BEGIN
						---------------------------------------------------
						-- Validate lot number in Plan						 
						---------------------------------------------------
						IF @in_vchExpiryDate NOT IN (SELECT DISTINCT expiry_date FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(expiry_date,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST';
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchExpiryDate <> ''
				BEGIN
					SET @out_vchErrorCode = 'EXPIRY_DATE_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute1Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute1,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE1 มาต้อง Return ให้ใส่ ATTRIBUTE1 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE1'
					GOTO NEXT_SCREEN;
				END

			IF ('') not in (SELECT ISNULL(attribute1,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END)) 
					BEGIN
						---------------------------------------------------
						-- Validate attribute1 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute1 NOT IN (SELECT DISTINCT attribute1 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(attribute1,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE1-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute1 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE1_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute2Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute2,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE2 มาต้อง Return ให้ใส่ ATTRIBUTE2 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE2'
					GOTO NEXT_SCREEN;
				END

			IF ('') not in (SELECT ISNULL(attribute2,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END)) 
					BEGIN
						---------------------------------------------------
						-- Validate attribute2 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute2 NOT IN (SELECT DISTINCT attribute2 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(attribute2,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute2 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE2_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute3Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute3,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE3 มาต้อง Return ให้ใส่ ATTRIBUTE3 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE3'
					GOTO NEXT_SCREEN;
				END

			IF ('') not in (SELECT ISNULL(attribute3,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END)) 
					BEGIN
						---------------------------------------------------
						-- Validate attribute3 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute3 NOT IN (SELECT DISTINCT attribute3 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(attribute3,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE3-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute3 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE3_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute4Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute4,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE4 มาต้อง Return ให้ใส่ ATTRIBUTE4 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE4'
					GOTO NEXT_SCREEN;
				END

			IF ('') not in (SELECT ISNULL(attribute4,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END)) 
					BEGIN
						---------------------------------------------------
						-- Validate attribute4 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute4 NOT IN (SELECT DISTINCT attribute4 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(attribute4,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE4-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute4 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE4_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END

	IF (@v_vchAttribute5Control = 'FULL')
		BEGIN
			IF ISNULL(@in_vchAttribute5,'') = ''
				BEGIN
					--ถ้าไม่ได้ส่ง ATTRIBUTE5 มาต้อง Return ให้ใส่ ATTRIBUTE5 ก่อน
					SET @out_vchNextScreen = 'ATTRIBUTE5'
					GOTO NEXT_SCREEN;
				END

			IF ('') not in (SELECT ISNULL(attribute5,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
												 ELSE quantity_order END)) 
					BEGIN
						---------------------------------------------------
						-- Validate attribute5 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute5 NOT IN (SELECT DISTINCT attribute5 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND (ISNULL(attribute5,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE5-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END
		END
	ELSE
		BEGIN
			IF @in_vchAttribute5 <> ''
				BEGIN
					SET @out_vchErrorCode = 'ATTRIBUTE5_NOT_CONTROL'
					GOTO EXIT_LABEL
				END
		END 

	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchSNControl = 'FULL' 
		BEGIN
			IF ISNULL(@in_vchSerialNumber,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @in_vchSerialNumber = ''
		END

	IF @v_vchSNControl = 'NONE' 
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					
					IF @@ROWCOUNT > 1
					BEGIN
						SET @out_vchNextScreen = 'RECEIVE_DATE'
						GOTO NEXT_SCREEN;
					END 
				END
		
			IF @in_vchReceiptMode = 'BY EACH' 
				BEGIN
					SET @in_fltQuantity = 1;
					GOTO SAVE_TRANS; 
				END
			ELSE	
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
		END


	--------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchWhItemMasterID		AS wh_item_master_id
		, @v_vchItemMasterID		AS item_master_id
		, @v_vchItemNumber			AS item_number
		, @v_vchItemDesc			AS item_description
		, @v_vchLotControl			AS lot_control
		, @v_vchSNControl			AS sn_control
		, @v_vchExpDateControl		AS expiry_date_control
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control
		, @in_vchItemStatusID		AS item_status_id
		, @v_dtExpDate				AS expiry_date
		, @v_vchBaseUomPrompt		AS uom_prompt
		, ISNULL(@v_intItemShelfLife,0) AS item_shelf_life
		, @v_fltQuantityOrder		AS quantity_order
		, @v_fltQuantityReceive		AS quantity_receive 
		, ROUND(ISNULL(@v_fltQuantityOrder,0) - ISNULL(@v_fltQuantityReceive,0),@Round) AS quantity_remain_receive
		, @v_dtReceiveDate			AS receive_date
		, @in_fltQuantity			AS display_default_qty
		, @in_vchSerialNumber		AS serial_number
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
		, @v_vchAlternateID			AS alternate_id
		, @v_vchCrossRefUOMID		AS cross_ref_uom_id
		, @v_vchCrossRefUomPrompt	AS cross_ref_uom_prompt

	RETURN;

	SAVE_TRANS:
		--สำหรับแสดงบนหน้าจอ
		SELECT @v_vchWhItemMasterID	  AS wh_item_master_id
			, @v_vchItemMasterID	  AS item_master_id
			, @v_vchItemNumber		AS item_number 
			, @v_vchItemDesc		AS item_description
			, @v_dtExpDate			AS expiry_date
			, @v_vchBaseUomPrompt	AS uom_prompt 
			, @v_fltQuantityOrder	AS quantity_order
			, @v_fltQuantityReceive	AS quantity_receive 
			, ROUND(ISNULL(@v_fltQuantityOrder,0) - ISNULL(@v_fltQuantityReceive,0),@Round) AS quantity_remain_receive 
			, CONVERT(DATE,@in_dtMFGDate) AS mfg_date 
			, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

		DECLARE @v_vchIsSave NVARCHAR(3) = '' 
		DECLARE @v_vchItemUOMID UNIQUEIDENTIFIER = NULL
		SELECT TOP 1 @v_vchItemUOMID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND uom_prompt = @v_vchBaseUomPrompt AND is_active = 'YES'
		EXEC usp_api_validate_receipt_qty_in_plan @in_vchScreenName		  = @in_vchControlName
												 ,@in_vchApplicationID	  = @in_vchApplicationID	
												 ,@in_vchLocalID		  = @in_vchLocalID				
												 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
												 ,@in_vchInboundMasterID  = @in_vchInboundMasterID    
												 ,@in_vchOrderNumber	  = @in_vchOrderNumber			
												 ,@in_vchOwnerID		  = @in_vchOwnerID				
												 ,@in_vchOwnerCode		  = @in_vchOwnerCode			
												 ,@in_vchParentLPN		  = @in_vchParentLPN		
												 ,@in_vchLPN			  = @in_vchLPN					
												 ,@in_vchWhItemMasterID	  = @v_vchWhItemMasterID	
												 ,@in_vchItemMasterID	  = @v_vchItemMasterID			
												 ,@in_vchItemNumber		  = @in_vchItemNumber			
												 ,@in_fltQtyEntered		  = @in_fltQuantity		
												 ,@in_vchItemUOMID		  = @v_vchItemUOMID			
												 ,@in_vchLot			  = @in_vchLotNumber					
												 ,@in_vchExpiryDate		  = @in_vchExpiryDate
												 ,@in_vchAttribute1		  = @in_vchAttribute1		
												 ,@in_vchAttribute2		  = @in_vchAttribute2		
												 ,@in_vchAttribute3		  = @in_vchAttribute3		
												 ,@in_vchAttribute4		  = @in_vchAttribute4		
												 ,@in_vchAttribute5		  = @in_vchAttribute5		
												 ,@in_vchSerialNumber	  = @in_vchSerialNumber	 			
												 ,@out_vchIsSave		  = @v_vchIsSave		OUTPUT		
												 ,@out_vchErrorCode		  = @out_vchErrorCode	OUTPUT	
												 ,@out_vchErrorMsg		  = @out_vchErrorMsg	OUTPUT	
												 ,@out_vchNextScreen	  = @out_vchNextScreen	OUTPUT		

		IF @v_vchIsSave = 'YES' 
			BEGIN
				--Save Transaction
				EXEC usp_inbound_update_receive_qty @in_vchApplicationID	= @in_vchApplicationID	
													,@in_vchDeviceID		= @in_vchDeviceID			
													,@in_vchUserID			= @in_vchUserID			
													,@in_vchWhMasterID		= @in_vchWhMasterID
													,@in_vchInboundMasterID	= @in_vchInboundMasterID	
													,@in_vchReceiptHeaderID	= @in_vchReceiptHeaderID	
													,@in_vchLocationID		= @in_vchLocationID
													,@in_vchInvStatusID		= @in_vchItemStatusID
													,@in_vchWhItemMasterID	= @v_vchWhItemMasterID	
													,@in_fltQuantity		= @in_fltQuantity			
													,@in_vchItemUomID		= @v_vchItemUOMID		
													,@in_vchLot				= @in_vchLotNumber			
													,@in_vchExpiryDate		= @in_vchExpiryDate		
													,@in_vchSerial			= @in_vchSerialNumber		
													,@in_vchParentLPN		= @in_vchParentLPN		
													,@in_vchLPN				= @in_vchLPN				
													,@in_vchReasonCode		= NULL
													,@in_vchAttribute1		= @in_vchAttribute1		
													,@in_vchAttribute2		= @in_vchAttribute2		
													,@in_vchAttribute3		= @in_vchAttribute3		
													,@in_vchAttribute4		= @in_vchAttribute4		
													,@in_vchAttribute5		= @in_vchAttribute5		
													,@in_dtReceiveDate		= @v_dtReceiveDate		
													,@in_dtMfgDate			= @in_dtMfgDate			
													,@out_ErrorCode			= @out_vchErrorCode	OUTPUT	
													,@out_ErrorMessage		= @out_vchErrorMsg	OUTPUT 
				IF ISNULL(@out_vchErrorCode,'') <> '0'
					BEGIN
						SET @out_vchNextScreen = NULL
						RETURN;
					END
			END
		ELSE 
			BEGIN
				RETURN;
			END
		
		IF @in_vchReceiptMode = 'BY EACH' OR @v_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

		FINAL_SCREEN:
			EXEC usp_api_validate_receipt_final_screen @in_vchWhMasterID		= @in_vchWhMasterID	
														,@in_vchInboundMasterID	= @in_vchInboundMasterID	
														,@in_vchLocationID		= @in_vchLocationID		
														,@in_vchReceiptMode	    = @in_vchReceiptMode	
														,@in_vchParentLPN		= @in_vchParentLPN	
														,@in_vchLPN				= @in_vchLPN			
														,@in_vchWhItemMasterID	= @v_vchWhItemMasterID
														,@in_vchSNControl       = @v_vchSNControl
														,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
		
		RETURN;
	--------------------------------------------------------
	-- Exit the Process
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_all_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_all_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchInboundOrderNumber NVARCHAR(50)	= NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER	= NULL,
	@in_vchOwnerCode		NVARCHAR(40)= NULL, 
	@in_vchLocationID		UNIQUEIDENTIFIER	= NULL,
	@in_vchLocation			NVARCHAR(50) = NULL, 
	@in_vchLPN				NVARCHAR(25) = NULL, 
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchLPNControl  VARCHAR(3),
			@v_vchInvLocation NVARCHAR(50)

	-- Screen LPN,Receipt Mode, Item Status, Item Number, Lot, Mfg, Exp.
	SELECT TOP 1 @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active = 'YES'
	 
	----------------------------------------------------
	-- Validate LPN
	----------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
			--------------------------------------------------------------------
			SELECT TOP 1 @v_vchInvLocation = location
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.lpn = @in_vchLPN

			IF (ISNULL(@v_vchInvLocation,'') <> '' AND @v_vchInvLocation <> @in_vchLocation)
				BEGIN
					--LPN ไม่ได้อยู่ใน Location ที่ Scan
					SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLpn,@v_vchInvLocation,'@param3','@param4','@param5')			
					RETURN;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
			--------------------------------------------------------------------
			EXEC usp_validate_duplicate_lpn @in_vchOrderNumber   = @in_vchInboundOrderNumber	
										   ,@in_vchLpn			 = @in_vchLPN			
										   ,@in_vchCheckDupItem  = 'YES'
										   ,@in_vchCheckDupOrder = 'YES'
										   ,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
	
			IF ISNULL(@out_vchErrorCode,'') <> ''
			BEGIN
				GOTO EXIT_LABEL;
			END
			
			SET @out_vchNextScreen = 'FINAL_SCREEN';
		END
	
	RETURN;
	--------------------------------------------------------
	-- Exit the Process
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_all_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_all_final_screen]
( 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	-----------------------------------------------------------
	-- ถ้าไม่มีรายการที่ต้องรับแล้วให้กลับไปที่หน้า Inbound Order
	-----------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
												ELSE quantity_order END))
		BEGIN
			SET @out_vchNextScreen = 'INBOUND_ORDER'
		END
	ELSE
		BEGIN
			IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID) = 'YES')
					SET @out_vchNextScreen = 'LPN'
				ELSE
					SET @out_vchNextScreen = 'LOCATION'
		END
	 
END 
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_all_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_all_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50)= NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl	NVARCHAR(3)
	
	--------------------------------------------------------------------
	-- Check Location in master data and loc type = RSTG
	--------------------------------------------------------------------
	SELECT @v_vchLocationID = location_id 
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location
	WHERE location = @in_vchLocation
	AND wh_master_id = @in_vchWhMasterID
	AND is_active = 'YES'
	AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-RSTG-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- Check LPN Controlled
	------------------------------------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			SET @out_vchNextScreen = 'LPN'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'FINAL_SCREEN'; 
		END

	SELECT @v_vchLocationID AS location_id 

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_all_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_all_lpn]
(
	@in_vchApplicationID	  VARCHAR(40)		= NULL,
	@in_vchLocalID			  VARCHAR(40)		= NULL,
	@in_vchWhMasterID		  UNIQUEIDENTIFIER= NULL,
	@in_vchInboundMasterID	  UNIQUEIDENTIFIER= NULL, 
	@in_vchInboundOrderNumber NVARCHAR(50)	= NULL, 
	@in_vchLocationID		  UNIQUEIDENTIFIER= NULL,
	@in_vchLocation			  NVARCHAR(50)	= NULL, 
	@in_vchLPN				  NVARCHAR(25)	= NULL, 
	@out_vchErrorCode		  VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		  NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		  NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchInvLocation	NVARCHAR(50) = NULL
 
	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInvLocation = location
	FROM t_wms_inventory inv WITH (NOLOCK)
	INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
	WHERE inv.wh_master_id = @in_vchWhMasterID
	AND inv.lpn = @in_vchLPN

	IF (ISNULL(@v_vchInvLocation,'') <> '' AND @v_vchInvLocation <> @in_vchLocation)
		BEGIN
			--LPN ไม่ได้อยู่ใน Location ที่ Scan
			SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLpn,@v_vchInvLocation,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
	--------------------------------------------------------------------
	EXEC usp_validate_duplicate_lpn @in_vchOrderNumber   = @in_vchInboundOrderNumber	
								   ,@in_vchLpn			 = @in_vchLPN			
								   ,@in_vchCheckDupItem  = 'YES'
								   ,@in_vchCheckDupOrder = 'YES'
								   ,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
	
	IF ISNULL(@out_vchErrorCode,'') <> ''
	BEGIN
		GOTO EXIT_LABEL;
	END
			
	SET @out_vchNextScreen = 'FINAL_SCREEN';
 
	 

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_all_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_all_order_number]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),  
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL, 
			@v_vchOwnerID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode			NVARCHAR(40) = NULL,
			@v_vchOrderType			NVARCHAR(40) = NULL,
			@v_vchOrderStatus		NVARCHAR(10) = NULL

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Inbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id
		,@in_vchInboundOrderNumber = ibMS.inbound_order_number
		,@v_vchOwnerID = own.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchOrderType = ibMS.order_type
		,@v_vchOrderStatus = ibMS.order_status
	FROM t_wms_inbound_master ibMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	WHERE ibMS.inbound_order_number = @in_vchInboundOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO_PLEASE_USE_RECEIPT_RETURN_FUNCTION'
			GOTO EXIT_LABEL
		END

	--------------------------------------------
	-- Check the inbound order status
	--------------------------------------------
	IF @v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	SET @out_vchNextScreen = 'LOCATION'
		
	-----------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInboundMasterID AS inbound_order_master_id 
		,@v_vchOwnerID			 AS owner_id 
		,@v_vchOwnerCode		 AS owner_code 
	RETURN;

	-----------------------------------------------
	-- Exit the Process
	-----------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
		BEGIN
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_attribute1]
(
	@in_vchApplicationID     VARCHAR(40)   = NULL,
	@in_vchLocalID		     VARCHAR(40)   = NULL,
	@in_vchWhMasterID	     UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL,	--Add New 22/05/2019
	@in_vchReceiptMode	     NVARCHAR(25)  = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	     NVARCHAR(50)  = NULL,
	@in_vchExpiryDate	     NVARCHAR(20)  = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		 NVARCHAR(100)  = NULL,
	@in_vchSnControl	     VARCHAR(5)  = NULL,	
	@in_vchAttribute1Control VARCHAR(5)  = NULL,
	@in_vchAttribute2Control VARCHAR(5)  = NULL,
	@in_vchAttribute3Control VARCHAR(5)  = NULL,
	@in_vchAttribute4Control VARCHAR(5)  = NULL,
	@in_vchAttribute5Control VARCHAR(5)  = NULL,
	@out_vchErrorCode	     VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	     NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen	     NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @Round INT
	DECLARE @v_dtReceiveDate DATE
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------------------------
	-- ถ้าไม่มี attribute1 ที่เป็นค่าว่าง จะต้อง Check ว่า attribute1 ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี attribute1 ที่เป็นค่าว่าง ไม่ต้อง Check attribute1 ใน Plan
	--------------------------------------------------------------------
	IF ('') not in (SELECT ISNULL(attribute1,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															   ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						---------------------------------------------------
						-- Validate attribute1 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute1 NOT IN (SELECT DISTINCT attribute1 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @in_vchWhItemMasterID
													AND (ISNULL(attribute1,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE1-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END


	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			RETURN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END

	--ถ้า Rule กำหนด Require Receipt Date ก็ให้ไปหน้าจอ Receipt Date
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					
					IF @@ROWCOUNT > 1
					BEGIN
						SET @out_vchNextScreen = 'RECEIVE_DATE'
						GOTO NEXT_SCREEN;
					END 
				END

			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END
		END

	 NEXT_SCREEN:
	 SELECT @v_dtReceiveDate AS receive_date

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
