					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															   ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						---------------------------------------------------
						-- Validate attribute2 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute2 NOT IN (SELECT DISTINCT attribute2 FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @in_vchWhItemMasterID
													AND (ISNULL(attribute2,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST'
							GOTO EXIT_LABEL;
						END		
					END

	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END
	

	--ถ้า Rule กำหนด Require Receipt Date ก็ให้ไปหน้าจอ Receipt Date
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					
