					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END
		END

	 NEXT_SCREEN:
	 SELECT @v_dtReceiveDate AS receive_date


	-----------------------------------------------------------------------------------
