			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END
		END

	 NEXT_SCREEN:
	 SELECT @v_dtReceiveDate AS receive_date
		 
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_final_screen]
( 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER, 
	@in_vchReceiptMode	    NVARCHAR(25)  = NULL,
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL, 
	@in_vchSNControl		VARCHAR(5) = NULL,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'

	-----------------------------------------------------------
	-- ถ้าไม่มีรายการที่ต้องรับแล้วให้กลับไปที่หน้า Inbound Order
	-----------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
												ELSE quantity_order END))
		BEGIN
			SET @out_vchNextScreen = 'INBOUND_ORDER'
		END
	ELSE
		BEGIN
			IF @in_vchSNControl = 'FULL'
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
				END
			ELSE
				BEGIN
					IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID) = 'YES')
						SET @out_vchNextScreen = 'LPN'
					ELSE
						SET @out_vchNextScreen = 'ITEM_NUMBER' 
				END
		END
	 
END 
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_item_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,	--Add New 22/05/2019
	@in_vchOrderNumber		NVARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchReceiptMode		NVARCHAR(25) = NULL,
	@in_vchParentLpn		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@out_vchItemMasterID	UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchWhItemMasterID  UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount	INT = 0
	DECLARE @Round		INT = 0
	DECLARE @v_vchWarehouse				NVARCHAR(25)
	DECLARE @v_vchItemNumber			NVARCHAR(50) = NULL
	DECLARE @v_vchItemDesc				NVARCHAR(200) = NULL
	DECLARE @v_vchItemUomID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchUomPrompt				NVARCHAR(40) = NULL
	DECLARE @v_intItemShelfLife			INT
	DECLARE @v_dtExpDate				DATETIME
	DECLARE @v_vchLotControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl		VARCHAR(5) = NULL
	DECLARE @v_vchSnControl				VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control		VARCHAR(5) = NULL
	DECLARE @v_fltQuantityOrder			FLOAT = 0
	DECLARE @v_fltQuantityReceipt		FLOAT = 0
	DECLARE @v_fltQuantityRemainReceipt FLOAT = 0
	DECLARE @v_dtReceiveDate			DATE
	DECLARE @v_vchItemIsActive			VARCHAR(3) = NULL
	DECLARE @v_vchAlternateID			UNIQUEIDENTIFIER = NULL
	DECLARE	@v_vchCrossRefUOMID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCrossRefUomPrompt		NVARCHAR(40) = NULL

	SELECT @Round = value from t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID
	----------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	----------------------------------------------------
	SELECT TOP 1 @out_vchItemMasterID = item.item_master_id
		 , @v_vchItemNumber = item.item_number
		 , @v_intItemShelfLife = item.days_to_expire
		 , @v_vchItemDesc = item.description
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchItemUomID = uom.item_uom_id
		 , @v_vchUomPrompt = uom.uom_prompt 
		 , @v_vchItemIsActive = item.is_active
		 , @v_vchAlternateID = itemRef.alternate_id
		 , @v_vchCrossRefUOMID = itemRef.item_uom_id
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@out_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @out_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @out_vchItemMasterID
	IF (@out_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchWarehouse,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WITH (NOLOCK) WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @out_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NOT-EXIST-IN-INBOUND-ORDER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	----------------------------------------------------
	-- Get Qty Order, Receipt, Remain in Plan
	----------------------------------------------------
	SELECT @v_fltQuantityOrder = ROUND(SUM(ISNULL(ibDT.quantity_order,0)),@round)
		 ,@v_fltQuantityReceipt = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round)
		 ,@v_fltQuantityRemainReceipt = ROUND(SUM(quantity_order - quantity_receive),@Round)
	FROM t_wms_inbound_detail ibDT
	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.wh_item_master_id = @out_vchWhItemMasterID 

	----------------------------------------------------
	-- ตรวจสอบ Lot Control
	----------------------------------------------------
	IF (@v_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchExpDateControl = 'FULL')
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'MFG_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES'
						BEGIN
							-----------------------------------------------------
							-- Use mfg date to calculate expiry date
							-----------------------------------------------------
							SELECT @v_dtExpDate = DATEADD(DAY,@V_intItemShelfLife,  GETDATE())
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'EXPIRY_DATE'
							GOTO NEXT_SCREEN;
						END
				END
		END
	IF @v_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END
	

	--ถ้า Rule กำหนด Require Receipt Date ก็ให้ไปหน้าจอ Receipt Date
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF (@v_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail 
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @out_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					IF @@ROWCOUNT > 1
					BEGIN
						SET @out_vchNextScreen = 'RECEIVE_DATE'
						GOTO NEXT_SCREEN;
					END 
				END

			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END 
		END
	
	--Get Uom of Item Cross ref เพื่อนำ uom prompt มา default ที่หน้าจอ ตอนใส่ qty
	IF @v_vchAlternateID IS NOT NULL
		BEGIN
			SELECT TOP 1 @v_vchCrossRefUomPrompt = uom_prompt FROM t_wms_item_uom WHERE item_uom_id = @v_vchCrossRefUOMID
		END


	-----------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------------
	NEXT_SCREEN:
	SELECT @out_vchWhItemMasterID   AS wh_item_master_id
		, @out_vchItemMasterID		AS item_master_id
		, @v_vchItemNumber			AS item_number
		, @v_vchItemDesc			AS item_description
		, @v_dtExpDate				AS expiry_date
		, @v_vchItemUomID			AS item_uom_id
		, @v_vchUomPrompt			AS uom_prompt
		, ISNULL(@v_intItemShelfLife,0) AS item_shelf_life
		, @v_vchLotControl			AS lot_control
		, @v_vchExpDateControl		AS expiry_date_control
		, @v_vchSNControl			AS sn_control
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control
		, @v_fltQuantityOrder		AS quantity_order
		, @v_fltQuantityReceipt		AS quantity_receive
		, @v_fltQuantityRemainReceipt  AS quantity_remain_receive 
		, @v_dtReceiveDate			AS receive_date
		, (CASE WHEN @v_vchSNControl = 'FULL' OR @out_vchNextScreen = 'FINAL_SCREEN' THEN 1 ELSE 0 END) AS qty
		, @v_vchAlternateID			AS alternate_id
		, @v_vchCrossRefUOMID		AS cross_ref_uom_id
		, @v_vchCrossRefUomPrompt	AS cross_ref_uom_prompt
		 
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_item_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_item_status]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchItemStatus		NVARCHAR(50) = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN

	DECLARE @v_vchItemStatusID UNIQUEIDENTIFIER = NULL
	SELECT @v_vchItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchItemStatus AND is_active = 'YES'
	
	IF @v_vchItemStatusID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-STATUS-INVALID'
			GOTO EXIT_LABEL;
		END

	-- กำหนดให้ Scan item number ทั้ง by each และ จำนวน แล้วไปแยกกันตอน validate Serial
	SET @out_vchNextScreen= 'ITEM_NUMBER'
	SELECT @v_vchItemStatusID AS item_status_id
	RETURN;


	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END



GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50)= NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl	NVARCHAR(3)
	
	--------------------------------------------------------------------
	-- Check Location in master data and loc type = RSTG
	--------------------------------------------------------------------
	SELECT @v_vchLocationID = location_id 
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location WITH (NOLOCK)
	WHERE location = @in_vchLocation
	AND wh_master_id = @in_vchWhMasterID
	AND is_active = 'YES'
	AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-RSTG-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- Check LPN Controlled
	------------------------------------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			------------------------------------------------------------------------------
			-- Check Rule Parent LPN
			------------------------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
				END
			ELSE
				BEGIN
					IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_RECEIVE_INTERFACE_BY_LPN' AND is_active = 'YES') = 'YES'
						BEGIN
							SET @out_vchNextScreen = 'LPN_RECEIPT'
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'LPN'
						END
				END
		END
	ELSE
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'RECEIPT_MODE'
				END
			ELSE
				BEGIN
					-------------------------------------------------------------
					-- Check Rule 'select item status'
					-------------------------------------------------------------
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES'
						BEGIN
							SET @out_vchNextScreen = 'ITEM_STATUS'
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'ITEM_NUMBER';
						END 
				END 
		END

	SELECT @v_vchLocationID AS location_id 

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_lot_number]
(
	@in_vchApplicationID     VARCHAR(40) = NULL,
	@in_vchLocalID		     VARCHAR(40) = NULL,
	@in_vchWhMasterID	     UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID   UNIQUEIDENTIFIER = NULL, --Add New 22/05/2019
	@in_vchReceiptMode	     NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_intItemShelfLife     INT = 0,
	@in_vchLotNumber	     NVARCHAR(50) = NULL,
	@in_vchExpDateControl    VARCHAR(5) = NULL,
	@in_vchSNControl	     VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode	     VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	     NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen	     NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @Round INT
	DECLARE @v_dtReceiveDate DATE = NULL
	DECLARE @v_dtExpDate DATETIME --เมื่อคำนวณ MFG + Item_shelf_life
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------------------------
	-- ถ้าไม่มี Lot ที่เป็นค่าว่าง จะต้อง Check ว่า Lot ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี Lot ที่เป็นค่าว่าง ไม่ต้อง Check Lot ใน Plan
	--------------------------------------------------------------------
	IF ('') NOT IN (SELECT ISNULL(lot_number,'') FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															   ELSE ROUND(quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate lot number in Plan						 
						---------------------------------------------------
						IF @in_vchLotNumber NOT IN (SELECT DISTINCT lot_number FROM t_wms_inbound_detail WITH (NOLOCK)
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @in_vchWhItemMasterID
													AND (ISNULL(lot_number,'') <> ''))
						BEGIN
							SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST';
							GOTO EXIT_LABEL;
						END		
					END
					 

	IF (@in_vchExpDateControl = 'FULL')
		BEGIN
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'MFG_DATE'
					RETURN;
				END
			ELSE
				BEGIN
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES'
						BEGIN
							-----------------------------------------------------
							-- Use mfg date to calculate expiry date
							-- ส่งกลับหน้าจอเพื่อให้แทนค่า Expiry Date
							-----------------------------------------------------
							SET @v_dtExpDate = CONVERT(VARCHAR,DATEADD(DAY,@in_intItemShelfLife,  GETDATE()),112)
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'EXPIRY_DATE'
							RETURN;
						END
				END
		END
	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END
	
	--ถ้า Rule กำหนด Require Receipt Date ก็ให้ไปหน้าจอ Receipt Date
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					
					IF @@ROWCOUNT > 1
					BEGIN
						SET @out_vchNextScreen = 'RECEIVE_DATE'
						GOTO NEXT_SCREEN;
					END 
				END

			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END
		END
	 
	 NEXT_SCREEN:
	 SELECT @v_dtExpDate as expiry_date, @v_dtReceiveDate AS receive_date

	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END 
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_lpn]
(
	@in_vchApplicationID	VARCHAR(40)		= NULL,
	@in_vchLocalID			VARCHAR(40)		= NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER= NULL,
	@in_vchOrderNumber		VARCHAR(50)		= NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER= NULL,
	@in_vchLocation			NVARCHAR(50)	= NULL,
	@in_vchParentLPN		NVARCHAR(25)	= NULL,
	@in_vchLPN				NVARCHAR(25)	= NULL,
	@in_vchScreenName		VARCHAR(50)		= NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchInvLocation	NVARCHAR(50) = NULL

	IF (@in_vchScreenName = 'LPN')
		BEGIN
			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
			--------------------------------------------------------------------
			SELECT @v_vchInvLocation = location
			FROM t_wms_inventory inv WITH (NOLOCK)
			INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.lpn = @in_vchLPN

			IF (ISNULL(@v_vchInvLocation,'') <> '' AND @v_vchInvLocation <> @in_vchLocation)
				BEGIN
					--LPN ไม่ได้อยู่ใน Location ที่ Scan
					SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLpn,@v_vchInvLocation,'@param3','@param4','@param5')			
					RETURN;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
			--------------------------------------------------------------------
			EXEC usp_validate_duplicate_lpn @in_vchOrderNumber   = @in_vchOrderNumber	
										   ,@in_vchLpn			 = @in_vchLPN			
										   ,@in_vchCheckDupItem  = 'YES'
										   ,@in_vchCheckDupOrder = 'YES'
										   ,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
	
			IF ISNULL(@out_vchErrorCode,'') <> ''
			BEGIN
				GOTO EXIT_LABEL;
			END
			
			------------------------------------------------------------------------------
			-- Check Rule 'select receive mode'
			------------------------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_USER_CAN_SELECT_RECEIPT_MODE' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'RECEIPT_MODE'
				END
			ELSE
				BEGIN
					-------------------------------------------------------------
					-- Check Rule 'select item status'
					-------------------------------------------------------------
					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES'
						BEGIN
							SET @out_vchNextScreen = 'ITEM_STATUS'
						END
					ELSE
						BEGIN
							SET @out_vchNextScreen = 'ITEM_NUMBER';
						END 
				END
		END
	ELSE IF (@in_vchScreenName = 'LPN_RECEIPT')
		BEGIN
			--------------------------------------------------------------------
			-- Check LPN in LPN Inbound detail
			-------------------------------------------------------------------- 
			IF NOT EXISTS (SELECT ibLPN.inbound_lpn_detail_id FROM t_wms_inbound_detail ibDT WITH (NOLOCK)
							LEFT JOIN t_wms_inbound_lpn_detail ibLPN ON  ibDT.inbound_order_detail_id = ibLPN.inbound_order_detail_id
							WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
							AND ibLPN.lpn = @in_vchLpn)
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-DOES-NOT-EXIST-IN-ORDER'
					GOTO EXIT_LABEL
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN Duplicate in Inventory
			-------------------------------------------------------------------- 
			IF EXISTS (SELECT inventory_id FROM t_wms_inventory WITH (NOLOCK) WHERE wh_master_id = @in_vchWhMasterID AND lpn = @in_vchLpn)
				BEGIN
					SET @out_vchErrorCode = 'INFO-DUPLICATE-LPN-IN-INVENTORY'
					SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLpn,@in_vchLocation,@in_vchParentLpn,'@param4','@param5')			
					RETURN;
				END

			--------------------------------------------------------------------
			-- WH Rule "Show LPN Confirm"?
			--------------------------------------------------------------------
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHOW_LPN_CONFIRM' AND is_active = 'YES') = 'YES')
				BEGIN
					SET @in_vchScreenName = 'LPN_CONFIRM'
				END
			ELSE
				BEGIN
					SET @in_vchScreenName = 'LPN_RECEIPT'					
				END
		END

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_mfg_date]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_mfg_date]
(
	@in_vchApplicationID     VARCHAR(40) = NULL,	--Add New 2019-06-28
	@in_vchLocalID		     VARCHAR(40) = NULL, --Add New 2019-06-28
	@in_vchInboundMasterID   UNIQUEIDENTIFIER = NULL, --Add New 22/05/2019
	@in_vchReceiptMode		 NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_dtMFGDate			 DATE = NULL,
	@in_intItemShelfLife	 INT = 0,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL, 
	@out_vchErrorCode	     VARCHAR(50)  OUTPUT, --Add New 2019-06-28
	@out_vchErrorMsg	     NVARCHAR(500)OUTPUT, --Add New 2019-06-28
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	 -- This store reference with:
	 DECLARE @Round INT = 0
	 DECLARE @v_dtReceiveDate DATE
	 DECLARE @v_dtExpDate DATETIME --เมื่อคำนวณ MFG + Item_shelf_life
	 DECLARE @v_vchExpiryDate VARCHAR(10) = '' 
	 
	 SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	
	--------------------------------------------------------------------
	-- Use Mfg.Date to calculate Exp. Date
	--------------------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'NO'
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'	
			RETURN;
		END 
		 
	--------------------------------------------------------------------
	-- กำหนดค่า MFG Date 
	-- 1. ถ้าไม่ส่ง MFG Date >> GetDate
	--------------------------------------------------------------------
	IF (@in_dtMFGDate IS NULL)
		BEGIN
			SET @in_dtMFGDate = GETDATE()
		END 
		 
	-----------------------------------------------------
	-- Use mfg date to calculate expiry date
	-- ส่งกลับหน้าจอเพื่อให้แทนค่า Expiry Date
	-----------------------------------------------------
	SET @v_vchExpiryDate = CONVERT(VARCHAR(8), DATEADD(DAY,ISNULL(@in_intItemShelfLife,0), @in_dtMFGDate),112)
			
	IF ('') NOT IN (SELECT ISNULL(expiry_date,'') FROM t_wms_inbound_detail
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
													WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
													WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
													ELSE ROUND(quantity_order,@Round) END)) 
		BEGIN
			---------------------------------------------------
			-- Validate lot number in Plan						 
			---------------------------------------------------
			IF @v_vchExpiryDate NOT IN (SELECT DISTINCT expiry_date FROM t_wms_inbound_detail
										WHERE inbound_order_master_id = @in_vchInboundMasterID
										AND wh_item_master_id = @in_vchWhItemMasterID
										AND (ISNULL(expiry_date,'') <> ''))
			BEGIN
				SET @out_vchErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST';
				GOTO EXIT_LABEL;
			END		
		END

	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END

	--ถ้า Rule กำหนด Require Receipt Date ก็ให้ไปหน้าจอ Receipt Date
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'REQUIRE_RECEIPT_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			----------------------------------------------------------------------------------------------------------------
			--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
			----------------------------------------------------------------------------------------------------------------
			IF EXISTS (SELECT inbound_order_master_id FROM t_wms_inbound_master WHERE inbound_order_master_id = @in_vchInboundMasterID 
						AND order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES'))
				BEGIN
					SELECT DISTINCT @v_dtReceiveDate = receive_date FROM t_wms_inbound_detail 
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)
					ORDER BY receive_date
					
					IF @@ROWCOUNT > 1
					BEGIN
						SET @out_vchNextScreen = 'RECEIVE_DATE'
						GOTO NEXT_SCREEN;
					END 
				END

			IF ISNULL(@in_vchReceiptMode,'') = '' OR @in_vchReceiptMode = 'ENTER QTY'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN'
					GOTO NEXT_SCREEN;
				END
		END
	
	 NEXT_SCREEN:
	 SELECT @v_vchExpiryDate AS expiry_date, @v_dtReceiveDate AS receive_date
 
	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_order_number]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchOrderNumber	 NVARCHAR(50),  
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_nCount				INT,
			@v_vchReceiptHeaderID	UNIQUEIDENTIFIER = NULL,
			@v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptNumber		NVARCHAR(50) = NULL,
			@v_vchOwnerID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode			NVARCHAR(40) = NULL,
			@v_vchOrderType			NVARCHAR(40) = NULL,
			@v_vchOrderStatus		NVARCHAR(10) = NULL

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Inbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id
		,@in_vchOrderNumber = ibMS.inbound_order_number
		,@v_vchOwnerID = own.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchOrderType = ibMS.order_type
		,@v_vchOrderStatus = ibMS.order_status
	FROM t_wms_inbound_master ibMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	WHERE ibMS.inbound_order_number = @in_vchOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO_PLEASE_USE_RECEIPT_RETURN_FUNCTION'
			GOTO EXIT_LABEL
		END

	--------------------------------------------
	-- Check the inbound order status
	--------------------------------------------
	IF @v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END

		------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	--------------------------------------------------------------------
	-- Check Partial Receipt Number
	--------------------------------------------------------------------
	SELECT @v_nCount = COUNT(receipt_header_id)
	FROM t_wms_receipt_header WITH (NOLOCK)
	WHERE inbound_order_master_id = @v_vchInboundMasterID
	AND receipt_status = 'OPEN'

	IF @v_nCount > 1
		BEGIN
			SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
		END
	ELSE IF @v_nCount = 1
		BEGIN
			SELECT @v_vchReceiptHeaderID = receipt_header_id
				,@v_vchReceiptNumber = receipt_number
			FROM t_wms_receipt_header WITH (NOLOCK)
			WHERE inbound_order_master_id = @v_vchInboundMasterID
			AND receipt_status = 'OPEN'

			SET @out_vchNextScreen = 'LOCATION'
		END
	ELSE
		BEGIN 
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_GENERATE_RECEIPT_NUMBER' AND is_active = 'YES') = 'YES'
				BEGIN
					--Create Partial Receipt Number
					EXEC usp_generate_receipt_number @in_vchUserID			    = @in_vchUserID
													 ,@in_vchWhMasterID		    = @in_vchWhMasterID
													 ,@in_vchInboundMasterID	= @v_vchInboundMasterID
													 ,@out_vchReceiptHeaderID	= @v_vchReceiptHeaderID OUTPUT
													 ,@out_vchReceiptNumber	    = @v_vchReceiptNumber OUTPUT
					SET @out_vchNextScreen = 'LOCATION'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
				END
		END
		
	-----------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInboundMasterID AS inbound_order_master_id 
		,@v_vchOwnerID			 AS owner_id 
		,@v_vchOwnerCode		 AS owner_code
		,@v_vchReceiptHeaderID	 AS receipt_header_id
		,@v_vchReceiptNumber	 AS receipt_number 
	RETURN;

	-----------------------------------------------
	-- Exit the Process
	-----------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
		BEGIN
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_partial_receipt_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_partial_receipt_number]
(	
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		NVARCHAR(40) = NULL,
	@in_vchReceiptNumber	NVARCHAR(50) = NULL, 
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchReceiptHeaderID UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptStatus	  NVARCHAR(25)= NULL
		 
	--------------------------------------------------------------------
	-- ตรวจสอบเลข Receipt Number ว่ามีอยู่ใน Order หรือไม่?
	--------------------------------------------------------------------
	SELECT @v_vchReceiptHeaderID = receipt_header_id
		,@v_vchReceiptStatus = receipt_status
	FROM t_wms_receipt_header WITH (NOLOCK)
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND receipt_number = @in_vchReceiptNumber

	IF (@v_vchReceiptHeaderID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-NOT-IN-ORDER'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Receipt Number > Status = OPEN?
	--------------------------------------------------------------------
	IF (@v_vchReceiptStatus <> 'OPEN')
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-IS-CLOSE'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LOCATION'
	SELECT @v_vchReceiptHeaderID AS receipt_header_id
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchReceiptNumber,'@param2','@param3','@param4','@param5')	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_qty_in_plan]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_qty_in_plan]
(
	@in_vchScreenName		VARCHAR(40)	 = NULL,
	@in_vchApplicationID	VARCHAR(40)	 = NULL,
	@in_vchLocalID			VARCHAR(40)	 = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID  UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		NVARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL, 
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_fltQtyEntered		FLOAT		 = 0,
	@in_vchItemUOMID		UNIQUEIDENTIFIER = NULL, 
	@in_vchLot				NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchSerialNumber		NVARCHAR(50)= NULL, 
	@out_vchIsSave			NVARCHAR(3)	    OUTPUT,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchCurrentScreen		NVARCHAR(50) = NULL,
			@v_nCount				INT,
			@Round					INT, 
			@v_fltInvQty			FLOAT,
			@v_fltPalletSizing		FLOAT,			--หมายถึง UDF7 ที่ item master table
			@out_fltSumQtyPlan		FLOAT = 0,	
			@out_fltSumQtyReceive	FLOAT = 0,
			@v_vchUomPrompt			NVARCHAR(40) = null

	
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	---------------------------------------------------------------------
	-- กรณีที่เป็น Item by each, หรือ serial number จะดึง UOM จากที่เป็น Primary
	---------------------------------------------------------------------
	IF @in_vchItemUOMID IS NULL
		BEGIN
			SELECT TOP 1 @v_vchUomPrompt = uom.uom_prompt 
			FROM t_wms_item_uom uom  
			WHERE uom.item_master_id = @in_vchItemMasterID
			AND uom.primary_uom = 'YES'
			AND uom.is_active = 'YES'
		END
	ELSE
		BEGIN
			SELECT TOP 1 @v_vchUomPrompt = uom.uom_prompt 
			FROM t_wms_item_uom uom  
			WHERE uom.item_master_id = @in_vchItemMasterID
			AND uom.item_uom_id = @in_vchItemUOMID
			AND uom.is_active = 'YES' 
		END
	IF (@in_vchScreenName = 'ITEM_NUMBER_BY_EACH')
		BEGIN
			----------------------------------------------------------
			-- กำหนดค่า Screen ที่ใช้จะวนทำงาน
			----------------------------------------------------------
			SET @v_vchCurrentScreen = 'ITEM_NUMBER_BY_EACH'
		
		END
	ELSE IF (@in_vchScreenName = 'SERIAL_NUMBER')
		BEGIN
			----------------------------------------------------------
			-- กำหนดค่า Screen ที่ใช้จะวนทำงาน
			----------------------------------------------------------
			SET @v_vchCurrentScreen = 'ITEM_NUMBER'

			--------------------------------------------------------------------
			-- Check Duplicate Serial Number in inventory data
			--------------------------------------------------------------------
			SELECT @v_nCount = COUNT(inv.inventory_id)
			FROM t_wms_inventory inv
			LEFT JOIN (SELECT invAttr.inventory_id
							,invAttr.attribute_group_id
							,invAttr.attribute_value	AS serial_number
						FROM t_wms_inventory_attribute_type invType
						INNER JOIN t_wms_inventory_attribute invAttr ON invType.inv_attribute_type_id = invAttr.inv_attribute_type_id
						WHERE invType.inv_attribute_type = 'SERIAL'
					   ) inv1 ON inv1.inventory_id = inv.inventory_id AND inv1.attribute_group_id = inv.attribute_group_id
			WHERE inv.wh_master_id = @in_vchWhMasterID
			AND inv.wh_item_master_id = @in_vchWhItemMasterID
			AND inv1.serial_number = @in_vchSerialNumber
			AND inv.owner_id = @in_vchOwnerID

			IF (@v_nCount > 0)
				BEGIN
					SET @out_vchErrorCode = 'INFO-SN-DUPLICATED'
					SET @out_vchIsSave = 'NO'
					GOTO EXIT_LABEL
				END


			--------------------------------------------------------------------
			-- ถ้าไม่มี SN ที่เป็นค่าว่าง จะต้อง Check ว่า SN ที่รับเข้ามาตรงกับ Plan หรือไม่?
			-- ถ้ามี SN ที่เป็นค่าว่าง ไม่ต้อง Check SN ใน Plan
			--------------------------------------------------------------------
			IF ('') NOT IN (SELECT ISNULL(serial_number,'') FROM t_wms_inbound_detail WITH (NOLOCK)
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
															   WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															   ELSE ROUND(quantity_order,@Round) END))				
				BEGIN
					---------------------------------------------------
					-- Validate serial number in Plan						 
					---------------------------------------------------
					IF @in_vchSerialNumber NOT IN (SELECT DISTINCT serial_number FROM t_wms_inbound_detail WITH (NOLOCK)
												WHERE inbound_order_master_id = @in_vchInboundMasterID
												AND wh_item_master_id = @in_vchWhItemMasterID
												AND (ISNULL(serial_number,'') <> ''))
					BEGIN
						SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
						GOTO EXIT_LABEL;
					END		
				END


			--------------------------------------------------------------------
			-- Check Duplicate Serial Number in Item Master, Item cross ref
			--------------------------------------------------------------------
			IF EXISTS (SELECT item.item_master_id FROM t_wms_item item
						LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
						WHERE (item.item_number = @in_vchSerialNumber OR cref.alternate_item_number = @in_vchSerialNumber))
				BEGIN
					SET @out_vchErrorCode = 'INFO-SN-DUPLICATED-IN-ITEM-MASTER'
					SET @out_vchIsSave = 'NO'
					GOTO EXIT_LABEL
				END
		END
	ELSE
		BEGIN
			----------------------------------------------------------
			-- กรณีของหน้าจอ UOM_QTY เมื่อ Save ให้ไปหา Final Screen เลย
			----------------------------------------------------------
			SET @v_vchCurrentScreen = 'FINAL_SCREEN'
		END

	VALIDATE_QTY_LABEL:
		---------------------------------------------------------------------------
		-- Set Default Value
		---------------------------------------------------------------------------
		SET @out_vchIsSave = 'YES'

		------------------------------------------------------------------
		-- Validate Qty กับ Qty_Plan หรือ Qty_over_receipt
		------------------------------------------------------------------
		EXEC usp_inbound_validate_quantity @in_vchApplicationID			= @in_vchApplicationID
										   ,@in_vchLocalID				= @in_vchLocalID
										   ,@in_vchWarehouseID			= @in_vchWhMasterID
										   ,@in_vchInboundMasterID		= @in_vchInboundMasterID 
										   ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
										   ,@in_vchItemMasterID			= @in_vchItemMasterID
										   ,@in_vchOwnerID				= @in_vchOwnerID
										   ,@in_fltQuantity				= @in_fltQtyEntered
										   ,@in_vchUOMPrompt			= @v_vchUomPrompt
										   ,@in_vchLot					= @in_vchLot
										   ,@in_vchExpiryDate			= @in_vchExpiryDate
										   ,@in_vchSerial				= @in_vchSerialNumber
										   ,@in_vchLPN					= @in_vchLPN
										   ,@out_fltQuantityPlan		= @out_fltSumQtyPlan OUTPUT
										   ,@out_fltQuantityReceive		= @out_fltSumQtyReceive OUTPUT
										   ,@out_ErrorCode				= @out_vchErrorCode OUTPUT
										   ,@out_ErrorMessage			= @out_vchErrorMsg OUTPUT
		
		IF @out_vchErrorCode = '0'
			BEGIN
				---------------------------------------------------
				-- กรณีที่รับแล้ว qty_receive <= qty_plan
				---------------------------------------------------
				IF ((@in_fltQtyEntered + @out_fltSumQtyReceive) = @out_fltSumQtyPlan)
					BEGIN
						SET @out_vchNextScreen = 'FINAL_SCREEN'
					END
				ELSE
					BEGIN
						SET @out_vchNextScreen = @v_vchCurrentScreen
					END

				--Set Error Msg = NULL
				SET @out_vchErrorMsg = NULL
			END
		ELSE IF @out_vchErrorCode = '1'
			BEGIN
				-------------------------------------------------------
				-- กรณีที่รับเกินจากแผน และอนุญาตให้สามารถรับเกินได้ 
				-- Check Rule Require Reason Code for over receipt
				-------------------------------------------------------
				IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REASON_FOR_OVER_RECEIVE' AND is_active = 'YES') = 'YES'
					BEGIN
						SET @out_vchNextScreen = 'REASON_OVER_REC_SN'
						SET @out_vchIsSave = 'NO'
					END
				ELSE
					BEGIN
						SET @out_vchNextScreen = 'FINAL_SCREEN'
					END
			
				--Set Error Msg = NULL
				SET @out_vchErrorMsg = NULL
			END
		ELSE
			BEGIN
				SET @out_vchIsSave = 'NO'
			END
		
		RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
	
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_receipt_mode]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_receipt_mode]
(
	@in_vchApplicationID VARCHAR(40)  = NULL,
	@in_vchLocalID		 VARCHAR(40)  = NULL,
	@in_vchReceiptMode	 VARCHAR(25)  = NULL,
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) = NULL OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF ISNULL(@in_vchReceiptMode,'') = ''
		BEGIN
			SET @in_vchReceiptMode = 'ENTER QTY'
		END 

	IF @in_vchReceiptMode NOT IN (SELECT value_member FROM t_com_combobox_item WHERE group_name = 'receipt_mode' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-MODE-INVALID'
			GOTO EXIT_LABEL;
		END

	-------------------------------------------------------------
	-- Check Rule 'select item status'
	-------------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER';
		END
	
	RETURN;
	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchControlName		NVARCHAR(50),	--Current Screen
	@in_vchLocalID			VARCHAR(40),  
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		VARCHAR(50)	= NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40)= NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_dtMFGDate			DATE = NULL, 
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100)= NULL,
	@in_vchAttribute2		NVARCHAR(100)= NULL,
	@in_vchAttribute3		NVARCHAR(100)= NULL,
	@in_vchAttribute4		NVARCHAR(100)= NULL,
	@in_vchAttribute5		NVARCHAR(100)= NULL,
	@in_dtReceiveDate		DATE = NULL,
	@in_vchUomPrompt		 NVARCHAR(40) = NULL, 
	@in_fltQuantity			 FLOAT,
	@out_vchErrorCode		VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_nCount			    INT 
	DECLARE @Round					INT
	DECLARE @v_vchLPNControl		NVARCHAR(5) = NULL
	DECLARE @v_vchInvLocation	    NVARCHAR(50) = NULL
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL 
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchSnControl			VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityOrder			FLOAT = 0
	DECLARE @v_fltQuantityReceipt		FLOAT = 0
	DECLARE @v_fltQuantityRemainReceipt FLOAT = 0
	DECLARE @v_dtReceiveDate		DATE = NULL
			
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	 
	--------------------------------------------------------------------------
	-- Validate LPN
	-- Screen LPN,Receipt Mode, Item Status, Item Number, Lot, Mfg, Exp.
	--------------------------------------------------------------------------
	SELECT TOP 1 @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active = 'YES'
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			-- ถ้าไม่ได้ส่ง LPN มา ถ้า Return ให้ใส่ LPN
			IF (ISNULL(@in_vchLpn,'') = '')
				BEGIN
					SET @out_vchNextScreen = 'LPN'
					RETURN;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
			--------------------------------------------------------------------
			SELECT @v_vchInvLocation = location
				,@v_vchLPNControl = loc.lpn_controlled
			FROM t_wms_inventory inv
			INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
			WHERE inv.lpn = @in_vchLpn
			AND inv.wh_master_id = @in_vchWhMasterID

			IF (ISNULL(@v_vchInvLocation,'') = '' AND @v_vchInvLocation <> @in_vchLocation)
				BEGIN
					--LPN ไม่ได้อยู่ใน Location ที่ Scan
					SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-LPN-IN-LOCATION'
					GOTO EXIT_LABEL;
				END

			--------------------------------------------------------------------
			-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
			--------------------------------------------------------------------
			EXEC usp_validate_duplicate_lpn @in_vchOrderNumber = @in_vchOrderNumber	
									   ,@in_vchLpn			   = @in_vchLpn			
									   ,@in_vchCheckDupItem    = 'YES'
									   ,@in_vchCheckDupOrder   = 'YES'
									   ,@out_vchErrorCode	   = @out_vchErrorCode OUTPUT
	
			IF ISNULL(@out_vchErrorCode,'') <> ''
				BEGIN
					GOTO EXIT_LABEL;
				END
		END

	----------------------------------------------------
	-- ถ้าจะใช้ 2D ต้องไม่ให้เลือก ITEM STATUS
	----------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES' AND @in_vchItemStatusID IS NULL
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			RETURN;
		END

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (ISNULL(@in_vchItemNumber,'') = '')
		BEGIN
			--ถ้าไม่ได้ส่ง Item มาต้อง Return ให้ใส่ Item ก่อน
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			RETURN;
		END

	SET @v_vchItemMasterID = NULL
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		 , @in_vchItemNumber = item.item_number 
		 , @v_vchItemDesc = item.description
		 , @v_vchBaseUomPrompt = uom.uom_prompt
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	----------------------------------------------------
	-- Validate Warehouse Item
	---------------------------------------------------	
	SET @v_vchWhItemMasterID = NULL
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID AND wh_master_id = @in_vchWhMasterID
	IF @v_vchWhItemMasterID IS NULL
	BEGIN
		SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
		GOTO EXIT_LABEL;
	END

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NOT-EXIST-IN-INBOUND-ORDER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	--  --Get Qty Order, Receipt, Remain in Plan
	--------------------------------------------------------------------
	SELECT @v_fltQuantityOrder = ROUND(SUM(ISNULL(ibDT.quantity_order,0)),@round)
		 ,@v_fltQuantityReceipt = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round)
		 ,@v_fltQuantityRemainReceipt = ROUND(SUM(ibDT.quantity_order - ISNULL(ibDT.quantity_receive,0)),@Round)
	FROM t_wms_inbound_detail ibDT
	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.item_master_id = @v_vchItemMasterID 

	DECLARE @v_vchChkWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchChkRemainQtyReturn float 

	SELECT @v_vchChkWhItemMasterID = wh_item_master_id 
		,@v_vchChkRemainQtyReturn = ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round)
	FROM v_wms_outbound_for_receipt_return
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID
	IF @v_vchChkWhItemMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO_ITEM_NOT_EXIST_IN_OUTBOUND';
			GOTO EXIT_LABEL;
		END
	IF @v_vchChkRemainQtyReturn = 0
		BEGIN
			SET @out_vchErrorCode = 'QTY_MORE_THAN_RETURN_QTY';
 			GOTO EXIT_LABEL;
		END
		 

	IF (@v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง LOT มาต้อง Return ให้ใส่ LOT ก่อน
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN; 
		END 

	IF (@v_vchExpDateControl = 'FULL' AND ISNULL(@in_vchExpiryDate,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง EXPIRY_DATE มาต้อง Return ให้ใส่ EXPIRY_DATE ก่อน
			SET @out_vchNextScreen = 'EXPIRY_DATE'
			GOTO NEXT_SCREEN; 
		END

	IF (@v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง ATTRIBUTE1 มาต้อง Return ให้ใส่ ATTRIBUTE1 ก่อน
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN; 
		END

	IF (@v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง ATTRIBUTE2 มาต้อง Return ให้ใส่ ATTRIBUTE2 ก่อน
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN; 
		END

	IF (@v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง ATTRIBUTE3 มาต้อง Return ให้ใส่ ATTRIBUTE3 ก่อน
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN; 
		END

	IF (@v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง ATTRIBUTE4 มาต้อง Return ให้ใส่ ATTRIBUTE4 ก่อน
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN; 
		END

	IF (@v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = '')
		BEGIN 
			--ถ้าไม่ได้ส่ง ATTRIBUTE5 มาต้อง Return ให้ใส่ ATTRIBUTE5 ก่อน
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN; 
		END

	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	 
	--------------------------------------------------------------------
	-- Validate Data
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO_DATA_NOT_EXIST_FROM_OUTBOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------
	-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
	-- Order Type for check ref outbound number in RULE
	--------------------------------------------------------
	SELECT DISTINCT @v_dtReceiveDate = receive_date
	FROM v_wms_outbound_for_receipt_return
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')		

	IF @@ROWCOUNT > 1
		BEGIN
			SET @out_vchNextScreen = 'RECEIVE_DATE'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			IF @v_vchSnControl = 'NONE'
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'FINAL_SCREEN' 
				END
		END

	--------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------
	NEXT_SCREEN: 
	SELECT @v_vchWhItemMasterID   AS wh_item_master_id
		, @v_vchItemMasterID	  AS item_master_id
		, @in_vchItemNumber		  AS item_number
		, @v_vchItemDesc		  AS item_description
		, @v_vchLotControl	      AS lot_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchExpDateControl AS expiry_date_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, @v_vchItemUomID		  AS item_uom_id
		, @v_vchBaseUomPrompt	  AS uom_prompt
		, @v_fltQuantityOrder	  AS quantity_order
		, @v_fltQuantityReceipt   AS quantity_receive
		, @v_fltQuantityRemainReceipt AS quantity_remain_receive
		, @v_dtReceiveDate		  AS receive_date
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
	RETURN;

	--------------------------------------------------------
	-- Exit the Process
	--------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_attribute1]
(
	@in_vchApplicationID     VARCHAR(40)   = NULL,
	@in_vchLocalID		     VARCHAR(40)   = NULL,
	@in_vchWhMasterID	     UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	     NVARCHAR(50)  = NULL,
	@in_vchExpiryDate	     NVARCHAR(20)  = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		 NVARCHAR(100)  = NULL,
	@in_vchSnControl	     VARCHAR(5)  = NULL,	
	@in_vchAttribute1Control VARCHAR(5)  = NULL,
	@in_vchAttribute2Control VARCHAR(5)  = NULL,
	@in_vchAttribute3Control VARCHAR(5)  = NULL,
	@in_vchAttribute4Control VARCHAR(5)  = NULL,
	@in_vchAttribute5Control VARCHAR(5)  = NULL,
	@out_vchErrorCode	     VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	     NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen	     NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @Round INT
	DECLARE @v_dtReceiveDate DATE = NULL
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------------------------
	-- ถ้าไม่มี attribute1 ที่เป็นค่าว่าง จะต้อง Check ว่า attribute1 ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี attribute1 ที่เป็นค่าว่าง ไม่ต้อง Check attribute1 ใน Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO_ATTRIBUTE1_NOT_EXIST_FROM_OUTBOUND'
			GOTO EXIT_LABEL;
		END

	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			RETURN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END
	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			--------------------------------------------------------
			SELECT DISTINCT @v_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END

	NEXT_SCREEN:
	SELECT @v_dtReceiveDate AS receive_date
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END


GO
