	DECLARE @Round INT
	DECLARE @v_dtReceiveDate DATE = NULL
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------------------------
	-- ถ้าไม่มี attribute3 ที่เป็นค่าว่าง จะต้อง Check ว่า attribute3 ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี attribute3 ที่เป็นค่าว่าง ไม่ต้อง Check attribute3 ใน Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO_ATTRIBUTE3_NOT_EXIST_FROM_OUTBOUND'
			GOTO EXIT_LABEL;
		END

	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END
	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			--------------------------------------------------------
			SELECT DISTINCT @v_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END

	NEXT_SCREEN:
	SELECT @v_dtReceiveDate AS receive_date
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END


