CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_expiry_date]
(
	@in_vchApplicationID	 VARCHAR(40) = NULL,
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL, 
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50) OUTPUT
)
AS
BEGIN 
	SET NOCOUNT ON; 
	DECLARE @Round INT
	DECLARE @v_dtReceiveDate DATE = NULL
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	--------------------------------------------------------------------
	-- ถ้าไม่มี expiry_date ที่เป็นค่าว่าง จะต้อง Check ว่า Lot ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี expiry_date ที่เป็นค่าว่าง ไม่ต้อง Check Lot ใน Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO_EXPIRY_DATE_NOT_EXIST_FROM_OUTBOUND';
			GOTO EXIT_LABEL;
		END

	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			RETURN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			RETURN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END
	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			--------------------------------------------------------
			SELECT DISTINCT @v_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END

	NEXT_SCREEN:
	SELECT @v_dtReceiveDate AS receive_date
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END


