/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_final_screen]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_final_screen]
( 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25), 
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL, 
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round INT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	-----------------------------------------------------------
	-- ถ้าไม่มีรายการที่ต้องรับแล้วให้กลับไปที่หน้า Inbound Order
	-----------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id
					FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
												WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@round)
												ELSE quantity_order END))
		BEGIN
			SET @out_vchNextScreen = 'INBOUND_ORDER'
		END
	ELSE
		BEGIN 
			IF ((SELECT TOP 1 lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID) = 'YES')
				SET @out_vchNextScreen = 'LPN'
			ELSE
				SET @out_vchNextScreen = 'ITEM_NUMBER' 
		END
END 
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_item_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_item_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchParentLpn		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round					INT
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchSnControl			VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityOrder			FLOAT = 0
	DECLARE @v_fltQuantityReceipt		FLOAT = 0
	DECLARE @v_fltQuantityRemainReceipt FLOAT = 0
	DECLARE @v_dtReceiveDate		DATE = NULL

	SELECT @Round = value from t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	-------------------------------------------------------------------- 
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		 , @v_vchItemNumber = item.item_number 
		 , @v_vchItemDesc = item.description
		 , @v_vchLotControl = item.lot_control
		 , @v_vchExpDateControl = item.expiry_date_control
		 , @v_vchSNControl = item.sn_control
		 , @v_vchAttribute1Control = item.attribute1_control
		 , @v_vchAttribute2Control = item.attribute2_control
		 , @v_vchAttribute3Control = item.attribute3_control
		 , @v_vchAttribute4Control = item.attribute4_control
		 , @v_vchAttribute5Control = item.attribute5_control
		 , @v_vchUomPrompt = uom.uom_prompt 
		 , @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id
	WHERE item.owner_id = @in_vchOwnerID 
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)

	----------------------------------------------------
	-- Validate Item Number
	----------------------------------------------------	
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchWarehouse,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NOT-EXIST-IN-INBOUND-ORDER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	--  --Get Qty Order, Receipt, Remain in Plan
	--------------------------------------------------------------------
	SELECT @v_fltQuantityOrder = ROUND(SUM(ISNULL(ibDT.quantity_order,0)),@round)
		 ,@v_fltQuantityReceipt = ROUND(SUM(ISNULL(ibDT.quantity_receive,0)),@round)
		 ,@v_fltQuantityRemainReceipt = ROUND(SUM(quantity_order - quantity_receive),@Round)
	FROM t_wms_inbound_detail ibDT
 	WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
	AND ibDT.wh_item_master_id = @v_vchWhItemMasterID
	
	DECLARE @v_vchChkWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchChkRemainQtyReturn float 

	SELECT @v_vchChkWhItemMasterID = wh_item_master_id 
		,@v_vchChkRemainQtyReturn = ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round)
	FROM v_wms_outbound_for_receipt_return
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID
	IF @v_vchChkWhItemMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO_ITEM_NOT_EXIST_IN_OUTBOUND';
			GOTO EXIT_LABEL;
		END
	IF @v_vchChkRemainQtyReturn = 0
		BEGIN
			SET @out_vchErrorCode = 'QTY_MORE_THAN_RETURN_QTY';
 			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ Lot Control
	--------------------------------------------------------------------
	IF (@v_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END
	IF (@v_vchExpDateControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	IF @v_vchAttribute5Control = 'FULL'
		BEGIN 
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END	
	IF (@v_vchSnControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			-------------------------------------------------------- 
			SELECT DISTINCT @v_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND ISNULL(quantity_ship,0) - ISNULL(quantity_received,0) > 0
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END
	
	--------------------------------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	--------------------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchWhItemMasterID   AS wh_item_master_id
		, @v_vchItemMasterID	  AS item_master_id
		, @v_vchItemDesc		  AS item_description
		, @v_vchItemUomID		  AS item_uom_id
		, @v_vchUomPrompt		  AS uom_prompt 
		, @v_vchLotControl		  AS lot_control
		, @v_vchExpDateControl	  AS expiry_date_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, @v_fltQuantityOrder	  AS quantity_order
		, @v_fltQuantityReceipt   AS quantity_receive
		, @v_fltQuantityRemainReceipt AS quantity_remain_receive
		, @v_dtReceiveDate		  AS receive_date
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
		 
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_item_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_item_status]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchItemStatus		NVARCHAR(50) = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @v_vchItemStatusID UNIQUEIDENTIFIER = NULL
	SELECT @v_vchItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchItemStatus AND is_active = 'YES'
	
	IF @v_vchItemStatusID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-STATUS-INVALID'
			GOTO EXIT_LABEL;
		END

	-- กำหนดให้ Scan item number ทั้ง by each และ จำนวน แล้วไปแยกกันตอน validate Serial
	SET @out_vchNextScreen= 'ITEM_NUMBER'
	SELECT @v_vchItemStatusID AS item_status_id
	RETURN;
	 
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_location]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,	--Add New 22/05/2019
	@in_vchLocation			NVARCHAR(50)= NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchLocationID	UNIQUEIDENTIFIER = NULL,
			@v_vchLPNControl	NVARCHAR(3)
	
	--------------------------------------------------------------------
	-- Check Location in master data and loc type = RSTG
	--------------------------------------------------------------------
	SELECT @v_vchLocationID = location_id 
		,@v_vchLPNControl = lpn_controlled
	FROM t_wms_location
	WHERE location = @in_vchLocation
	AND wh_master_id = @in_vchWhMasterID
	AND is_active = 'YES'
	AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_GET_INBOUND_RECEIPT_LOCATION' AND is_active = 'YES')
	IF (@v_vchLocationID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-RSTG-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- Check LPN Controlled
	------------------------------------------------------------------------------
	IF (@v_vchLPNControl = 'YES')
		BEGIN
			------------------------------------------------------------------------------
			-- Check Rule Parent LPN
			------------------------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
		END
	ELSE
		BEGIN
			-------------------------------------------------------------
			-- Check Rule 'select item status'
			-------------------------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'ITEM_NUMBER';
				END 
		END

	SELECT @v_vchLocationID AS location_id
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_lot_number]
(
	@in_vchApplicationID     VARCHAR(40) = NULL,
	@in_vchLocalID		     VARCHAR(40) = NULL,
	@in_vchWhMasterID	     UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	     NVARCHAR(50) = NULL,
	@in_vchExpDateControl    VARCHAR(5) = NULL,
	@in_vchSNControl	     VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@out_vchErrorCode	     VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg	     NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen	     NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @Round INT	
	DECLARE @v_dtReceiveDate DATE = NULL
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------------------------
	-- ถ้าไม่มี Lot ที่เป็นค่าว่าง จะต้อง Check ว่า Lot ที่รับเข้ามาตรงกับ Plan หรือไม่?
	-- ถ้ามี Lot ที่เป็นค่าว่าง ไม่ต้อง Check Lot ใน Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO_LOT_NUMBER_NOT_EXIST_FROM_OUTBOUND';
			GOTO EXIT_LABEL;
		END

	IF (@in_vchExpDateControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'
			RETURN;
		END
	IF @in_vchAttribute1Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			RETURN;
		END
	IF @in_vchAttribute2Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			RETURN;
		END
	IF @in_vchAttribute3Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			RETURN;
		END
	IF @in_vchAttribute4Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			RETURN;
		END
	IF @in_vchAttribute5Control = 'FULL'
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			RETURN;
		END	
	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			RETURN;
		END
	ELSE
		BEGIN
			--------------------------------------------------------
			-- Order Type Return and Ref Outbound Number จะต้องใส่ข้อมูล Receive Date เดิม
			-- Order Type for check ref outbound number in RULE
			--------------------------------------------------------
			SELECT DISTINCT @v_dtReceiveDate = receive_date
			FROM v_wms_outbound_for_receipt_return
			WHERE inbound_order_master_id = @in_vchInboundMasterID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ROUND(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0),@Round) > 0
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'RECEIVE_DATE'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END
	
	NEXT_SCREEN:
	SELECT @v_dtReceiveDate AS receive_date
	RETURN;

	----------------------------------------------------------------
	-- Exit the Process
	----------------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_lpn]
(
	@in_vchApplicationID	VARCHAR(40)		= NULL,
	@in_vchLocalID			VARCHAR(40)		= NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER= NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER= NULL,
	@in_vchOrderNumber		VARCHAR(50)		= NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER= NULL,
	@in_vchLocation			NVARCHAR(50)	= NULL,
	@in_vchParentLPN		NVARCHAR(25)	= NULL,
	@in_vchLPN				NVARCHAR(25)	= NULL,
	@out_vchErrorCode		VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	DECLARE @v_vchInvLocation	NVARCHAR(50) = NULL
 
	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนตรงกับ LPN ใน Location อื่นที่สแกนหรือไม่?
	--------------------------------------------------------------------
	SELECT @v_vchInvLocation = location
	FROM t_wms_inventory inv
	INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
	WHERE inv.wh_master_id = @in_vchWhMasterID
	AND inv.lpn = @in_vchLPN

	IF (ISNULL(@v_vchInvLocation,'') <> '' AND @v_vchInvLocation <> @in_vchLocation)
		BEGIN
			--LPN ไม่ได้อยู่ใน Location ที่ Scan
			SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchLpn,@v_vchInvLocation,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master และ Order Number
	--------------------------------------------------------------------
	EXEC usp_validate_duplicate_lpn @in_vchOrderNumber   = @in_vchOrderNumber	
									,@in_vchLpn			 = @in_vchLPN			
									,@in_vchCheckDupItem  = 'YES'
									,@in_vchCheckDupOrder = 'YES'
									,@out_vchErrorCode	 = @out_vchErrorCode OUTPUT
	
	IF ISNULL(@out_vchErrorCode,'') <> ''
	BEGIN
		GOTO EXIT_LABEL;
	END
			
	-------------------------------------------------------------
	-- Check Rule 'select item status'
	-------------------------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SELECT_ITEM_STATUS_BEFORE_RECEIPT' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER';
		END 

	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_order_number]
(
	@in_vchApplicationID VARCHAR(40),
	@in_vchLocalID		 VARCHAR(40),
	@in_vchUserID		 NVARCHAR(25),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchWhMasterID	 UNIQUEIDENTIFIER,
	@in_vchOrderNumber	 NVARCHAR(50),  
	@out_vchErrorCode	 VARCHAR(50) OUTPUT,
	@out_vchErrorMsg	 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen	 NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_nCount				INT,
			@v_vchReceiptHeaderID	UNIQUEIDENTIFIER = NULL,
			@v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptNumber		NVARCHAR(50) = NULL,
			@v_vchOwnerID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode			NVARCHAR(40) = NULL,
			@v_vchOrderType			NVARCHAR(40) = NULL,
			@v_vchOrderStatus		NVARCHAR(10) = NULL,
			@v_vchRefOuboundNo		NVARCHAR(50) = NULL

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Inbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id
		,@in_vchOrderNumber = ibMS.inbound_order_number
		,@v_vchOwnerID = own.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchOrderType = ibMS.order_type
		,@v_vchOrderStatus = ibMS.order_status
		,@v_vchRefOuboundNo = ibMS.reference_number
	FROM t_wms_inbound_master ibMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	WHERE ibMS.inbound_order_number = @in_vchOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_REF_OUTBOUND' AND is_active = 'YES') AND ISNULL(@v_vchRefOuboundNo,'') = ''
		BEGIN
			SET @out_vchErrorCode = 'REF_OUTBOUND_NUMBER_NOT_EMPTY'
			GOTO EXIT_LABEL
		END

	--------------------------------------------
	-- Check the inbound order status
	--------------------------------------------
	IF @v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_IB_ORDER_STATUS' AND is_active = 'YES')
		BEGIN
			--Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-STATUS'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	--------------------------------------------------------------------
	-- Check Partial Receipt Number
	--------------------------------------------------------------------
	SELECT @v_nCount = COUNT(receipt_header_id)
	FROM t_wms_receipt_header WITH (NOLOCK)
	WHERE inbound_order_master_id = @v_vchInboundMasterID
	AND receipt_status = 'OPEN'

	IF @v_nCount > 1
		BEGIN
			SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
		END
	ELSE IF @v_nCount = 1
		BEGIN
			SELECT @v_vchReceiptHeaderID = receipt_header_id
				,@v_vchReceiptNumber = receipt_number
			FROM t_wms_receipt_header WITH (NOLOCK)
			WHERE inbound_order_master_id = @v_vchInboundMasterID
			AND receipt_status = 'OPEN'

			SET @out_vchNextScreen = 'LOCATION'
		END
	ELSE
		BEGIN 
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_GENERATE_RECEIPT_NUMBER' AND is_active = 'YES') = 'YES'
				BEGIN
					--Create Partial Receipt Number
					EXEC usp_generate_receipt_number @in_vchUserID			    = @in_vchUserID
													 ,@in_vchWhMasterID		    = @in_vchWhMasterID
													 ,@in_vchInboundMasterID	= @v_vchInboundMasterID
													 ,@out_vchReceiptHeaderID	= @v_vchReceiptHeaderID OUTPUT
													 ,@out_vchReceiptNumber	    = @v_vchReceiptNumber OUTPUT
					SET @out_vchNextScreen = 'LOCATION'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'PARTIAL_RECEIPT_NUMBER'
				END
		END
		
	-----------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchInboundMasterID AS inbound_order_master_id 
		,@v_vchOwnerID			 AS owner_id 
		,@v_vchOwnerCode		 AS owner_code
		,@v_vchReceiptHeaderID	 AS receipt_header_id
		,@v_vchReceiptNumber	 AS receipt_number
		,@v_vchRefOuboundNo		 AS ref_outbound_number
	RETURN;

	-----------------------------------------------
	-- Exit the Process
	-----------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
		BEGIN
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_receipt_return_receipt_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_receipt_return_receipt_number]
(	
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER = NULL,	--Add New 22/05/2019
	@in_vchOrderNumber		NVARCHAR(40) = NULL,
	@in_vchReceiptNumber	NVARCHAR(50) = NULL, 
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchReceiptHeaderID UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptStatus	  NVARCHAR(25)= NULL
		 
	--------------------------------------------------------------------
	-- ตรวจสอบเลข Receipt Number ว่ามีอยู่ใน Order หรือไม่?
	--------------------------------------------------------------------
	SELECT @v_vchReceiptHeaderID = receipt_header_id
		,@v_vchReceiptStatus = receipt_status
	FROM t_wms_receipt_header 
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND receipt_number = @in_vchReceiptNumber

	IF (@v_vchReceiptHeaderID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-NOT-IN-ORDER'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Receipt Number > Status = OPEN?
	--------------------------------------------------------------------
	IF (@v_vchReceiptStatus <> 'OPEN')
		BEGIN
			SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-IS-CLOSE'
			GOTO EXIT_LABEL;
		END

	SET @out_vchNextScreen = 'LOCATION'
	SELECT @v_vchReceiptHeaderID AS receipt_header_id
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchReceiptNumber,'@param2','@param3','@param4','@param5')	
END

GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_system_pick_load_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_system_pick_load_2D]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),  
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchBoxNumber			NVARCHAR(25),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchItemNumber			NVARCHAR(50),  
	@in_vchLotNumber			NVARCHAR(50)= NULL,	
	@in_vchExpiryDate			NVARCHAR(10)= NULL,	
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT, 
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_intRound				INT
	DECLARE @v_vchNewLocationID		UNIQUEIDENTIFIER   = NULL	--จะใช้เมื่อมีการ Override ที่ LPN ใหม่
	DECLARE @v_vchNewLocation		NVARCHAR(50)  = NULL		--จะใช้เมื่อมีการ Override ที่ LPN ใหม่
	DECLARE @v_vchNewParentLPN 		NVARCHAR(25)  = NULL		--จะใช้เมื่อมีการ Override ที่ LPN ใหม่
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityPlan		FLOAT
	DECLARE @v_fltQuantityPick		FLOAT
	DECLARE @v_vchLPNControl		VARCHAR(5)
				
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active= 'YES' 
	SELECT TOP 1 @v_vchLPNControl = lpn_controlled FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active= 'YES'
	
	IF @v_vchLPNControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchLpn,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'LPN'
					RETURN;
				END 
			------------------------------------------------------
			-- Check LPN in Scaned Location
			------------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
							WHERE wh_master_id = @in_vchWhMasterID 
							AND ISNULL(load_id,'') = @in_vchLoadID
							AND is_override = 'NO'
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,''))
				BEGIN
					SET @out_vchErrorCode = 'INFO-NOT-EXIST-LPN-IN-LOCATION'
					GOTO EXIT_LABEL
				END
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number และ ใน Cross Ref
	--------------------------------------------------------------------
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(50) = NULL

	SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_outbound_master WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		, @v_vchItemDesc = description
		, @v_vchLotControl = lot_control
		, @v_vchSNControl = sn_control
		, @v_vchExpiryDateControl = expiry_date_control
		, @v_vchAttribute1Control = attribute1_control
		, @v_vchAttribute2Control = attribute2_control
		, @v_vchAttribute3Control = attribute3_control
		, @v_vchAttribute4Control = attribute4_control
		, @v_vchAttribute5Control = attribute5_control
		, @v_vchUomPrompt = uom_prompt
		, @v_vchItemIsActive = item.is_active
	FROM  t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
	WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
	AND item.owner_id = @v_vchOwnerID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			GOTO EXIT_LABEL;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF @v_vchWhItemMasterID IS NULL
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END
		 
	--------------------------------------------------------------------
	--Check Item In Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
					WHERE wh_master_id = @in_vchWhMasterID 
					AND ISNULL(load_id,'') = @in_vchLoadID
					AND is_override = 'NO'
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
					AND wh_item_master_id = @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_DETAIL_NOT_FOUND_ITEM'
			GOTO EXIT_LABEL;
		END
		 

	IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		END

	IF @v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	IF (@v_vchSNControl = 'FULL')
		BEGIN
			IF ISNULL(@in_vchSerialNumber,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'SERIAL_NUMBER'
					GOTO NEXT_SCREEN;
				END
			ELSE
				BEGIN
					IF @in_vchSerialNumber <> 'ALL'
						BEGIN
							IF NOT EXISTS (SELECT inventory_id
											FROM v_wms_inventory_data_serial_by_id
											WHERE wh_master_id = @in_vchWhMasterID
											AND owner_id = @v_vchOwnerID
											AND location_id = @in_vchLocationID
											AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
											AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
											AND wh_item_master_id = @v_vchWhItemMasterID
											AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
											AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
											AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
											AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
											AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
											AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
											AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
											AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
								BEGIN
									SET @out_vchErrorCode = 'SERIAL_NOT_FOUND_IN_INVENOTY'
									GOTO EXIT_LABEL;
								END

							IF EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
											WHERE wh_master_id = @in_vchWhMasterID 
											AND ISNULL(load_id,'') = @in_vchLoadID
											AND is_override = 'NO'
											AND location_id = @in_vchLocationID
											AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
											AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
											AND wh_item_master_id = @v_vchWhItemMasterID
											AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
											AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
											AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
											AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
											AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
											AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
											AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
											AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
								BEGIN 
									SET @out_vchErrorCode = 'INFO-SN-DUPLICATED'
									GOTO EXIT_LABEL; 
								END
						END
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			----------------------------------------------------------
			-- Validate attribute 1 in Pick Detail
			----------------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_by_load
					WHERE wh_master_id = @in_vchWhMasterID 
					AND ISNULL(load_id,'') = @in_vchLoadID
					AND is_override = 'NO'
					AND location_id = @in_vchLocationID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
				BEGIN 
					SET @out_vchErrorCode = 'INFO-NOT-EXIST-ATTRIBUTE5-IN-PICK-DETAIL'
					GOTO EXIT_LABEL 
				END
			SET @out_vchNextScreen = 'UOM_QTY'
			GOTO NEXT_SCREEN;
		END
		

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT  @v_vchWhItemMasterID  AS wh_item_master_id
		, @v_vchItemMasterID	  AS item_master_id
		, @v_vchItemDesc		  AS item_description
		, @v_vchUomPrompt		  AS uom_prompt
		, @v_vchLotControl		  AS lot_control
		, @v_vchExpiryDateControl AS expiry_date_control
		, @v_vchSNControl		  AS sn_control
		, @v_vchAttribute1Control AS attribute1_control
		, @v_vchAttribute2Control AS attribute2_control
		, @v_vchAttribute3Control AS attribute3_control
		, @v_vchAttribute4Control AS attribute4_control
		, @v_vchAttribute5Control AS attribute5_control
		, @v_vchNewLocationID	  AS location_id
		, @v_vchNewLocation		  AS location
		, @v_vchNewParentLPN	  AS parent_lpn
		, @v_fltQuantityPlan	  AS quantity_plan
		, @v_fltQuantityPick	  AS quantity_pick
		, @in_fltQuantity		  AS display_default_qty
		, (CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty
	RETURN;
	
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')		

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_system_pick_lpn_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_system_pick_lpn_2D]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40), 
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLPN					NVARCHAR(25),  
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_intRound INT = 0
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	------------------------------------------------------
	-- Check LPN in Picking Detail
	------------------------------------------------------
	IF NOT EXISTS (SELECT TOP 1 outbound_pick_detail_id FROM t_wms_outbound_pick_detail WITH (NOLOCK)
				   WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID 
				   AND location_id = @in_vchLocationID
				   AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				   AND is_override = 'NO'
				   AND ROUND(ISNULL(quantity_pick,0),@v_intRound) < ROUND(ISNULL(quantity_plan,0),@v_intRound))
	BEGIN
		SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
		GOTO EXIT_LABEL 
	END

	------------------------------------------------------------------------------
	-- Check LPN ใน Inventory
	------------------------------------------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WITH (NOLOCK) WHERE location_id = @in_vchLocationID AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
			GOTO EXIT_LABEL
		END 

	BEGIN --Save Normal
	SAVE_TRANS:
		EXEC usp_outbound_update_pick_item_by_lpn @in_vchApplicationID		= @in_vchApplicationID		
												 ,@in_vchDeviceID			= @in_vchDeviceID				
												 ,@in_vchUserID				= @in_vchUserID				
												 ,@in_vchWhMasterID			= @in_vchWhMasterID			
												 ,@in_vchWhID				= @in_vchWhID					
												 ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	 			
												 ,@in_vchLPN				= @in_vchLPN
												 ,@in_vchForkLift			= @in_vchForkLocation	
												 ,@out_ErrorCode			= @out_vchErrorCode OUTPUT
												 ,@out_ErrorMessage			= @out_vchErrorMsg	OUTPUT

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
	END
	  
	--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
		BEGIN
			GOTO FINAL_SCREEN; 
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'FINAL_SCREEN';
			RETURN;
		END

	FINAL_SCREEN:
		EXEC usp_api_validate_picking_lpn_final_screen @in_vchApplicationID		    = @in_vchApplicationID		    
 													  ,@in_vchWhMasterID			= @in_vchWhMasterID			 
													  ,@in_vchWhID					= @in_vchWhID					 
													  ,@in_vchOutboundMasterID		= @in_vchOutboundMasterID		 
													  ,@in_vchOutboundPickMasterID  = @in_vchOutboundPickMasterID  
 													  ,@in_vchLPN					= @in_vchLPN					 
													  ,@in_vchLocalID				= @in_vchLocalID				 
													  ,@in_vchUserID				= @in_vchUserID				 
													  ,@out_vchErrorCode			= @out_vchErrorCode	OUTPUT	
													  ,@out_vchErrorMsg				= @out_vchErrorMsg OUTPUT	
													  ,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')		

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_system_pick_order_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_system_pick_order_2D]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40)= NULL,
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchContainerNo			NVARCHAR(50),
	@in_vchPickMode				NVARCHAR(50), --BY EACH, BY QTY or empty
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchOverLocationID		UNIQUEIDENTIFIER,
	@in_vchOverLocation			NVARCHAR(50),
	@in_vchLocation				NVARCHAR(50)= NULL,
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25), 
	@in_vchItemNumber			NVARCHAR(50),  
	@in_vchLotNumber			NVARCHAR(50)= NULL,	
	@in_vchExpiryDate			NVARCHAR(10)= NULL,	
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_intRound				INT
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityPlan		FLOAT
	DECLARE @v_fltQuantityPick		FLOAT
	DECLARE @v_vchLPNControl		VARCHAR(5)

	--For Override
	DECLARE @v_vchOverWhItemMasterID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOverItemMasterID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOverItemNumber	 NVARCHAR(50) 
	DECLARE @v_vchOverItemDesc		 NVARCHAR(200) = NULL
	DECLARE @v_vchOverUomPrompt		 NVARCHAR(40) = NULL
	DECLARE @v_vchOverLPN			 NVARCHAR(25) = NULL
	DECLARE @v_vchOverLotNumber		 NVARCHAR(50) 
	DECLARE @v_vchOverExpiryDate	 NVARCHAR(50) 
	DECLARE @v_vchOverAttribute1	 NVARCHAR(100) 
	DECLARE @v_vchOverAttribute2	 NVARCHAR(100) 
	DECLARE @v_vchOverAttribute3	 NVARCHAR(100) 
	DECLARE @v_vchOverAttribute4	 NVARCHAR(100) 
	DECLARE @v_vchOverAttribute5	 NVARCHAR(100) 
	DECLARE @v_vchOverSerialNumber	 NVARCHAR(100)

	DECLARE @v_vchNewLocationID	UNIQUEIDENTIFIER
	DECLARE @v_vchNewLocation	NVARCHAR(50)
	DECLARE @v_vchNewParentLPN 	NVARCHAR(25)
			
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active= 'YES'
	
	SELECT TOP 1 @v_vchLPNControl = lpn_controlled
	FROM t_wms_location
	WHERE location_id = (CASE WHEN @in_vchLocationID IS NULL THEN @in_vchOverLocationID ELSE @in_vchLocationID END)
	AND is_active = 'YES'
	 
	IF @v_vchLPNControl = 'YES'
		BEGIN 
			------------------------------------------------------
			-- Check LPN in Picking Detail
			------------------------------------------------------
			IF NOT EXISTS (SELECT pickDT.lpn FROM t_wms_outbound_pick_detail pickDT
							WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
							AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
							AND pickDT.is_override = 'NO'
							AND ROUND(ISNULL(pickDT.quantity_plan,0),@v_intRound) <> ROUND(ISNULL(pickDT.quantity_pick,0),@v_intRound))
			BEGIN
				------------------------------------------------------------------------------
				-- Check LPN ใน Inventory
				------------------------------------------------------------------------------
				IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE lpn = @in_vchLpn)
					BEGIN
						SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
						GOTO EXIT_LABEL
					END

				------------------------------------------------------------------------------
				-- กรณีที่ไม่พบ LPN ใน Pick Detail
				-- Check Rule 'WH Rule Allow Override lpn'
				------------------------------------------------------------------------------
				IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_ALLOW_OVERRIDE_LPN' AND is_active = 'YES') = 'YES'
					BEGIN
						-- Override LPN
						EXEC usp_outbound_override_lpn  @in_vchApplicationID	 = @in_vchApplicationID	
														,@in_vchWhMasterID		 = @in_vchWhMasterID		
														,@in_vchWhID			 = @in_vchWhID				
														,@in_vchOutboundMasterID = @in_vchOutboundMasterID		
														,@in_vchOrderNumber		 = @in_vchOutboundOrderNumber			
														,@in_vchOwnerID			 = @in_vchOwnerID
														,@in_vchOwner			 = @in_vchOwnerCode
														,@in_vchLPN				 = @in_vchLPN		
														,@in_vchLocalID			 = @in_vchLocalID	
														,@in_vchDeviceID		 = @in_vchDeviceID
														,@in_vchUserID			 = @in_vchUserID	
														,@out_vchLocationID		 = @v_vchNewLocationID OUTPUT
														,@out_vchLocation		 = @v_vchNewLocation OUTPUT
														,@out_vchParentLPN		 = @v_vchNewParentLPN OUTPUT
														,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT	
														,@out_vchErrorMsg 		 = @out_vchErrorMsg OUTPUT	
						IF (@out_vchErrorCode = '0')
							BEGIN
								IF @v_vchNewLocationID IS NOT NULL
									BEGIN
										SET @in_vchLocationID = @v_vchNewLocationID
										SET @in_vchLocation = @v_vchNewLocation
									END
								-- Clear ค่าก่อนส่งเข้า PDA
								SET @out_vchErrorCode = ''
								SET @out_vchErrorMsg = '' 
							END
						ELSE
							BEGIN
								--หามีการ Error จาก Store override LPN
								RETURN;
							END
					END
			END

			------------------------------------------------------
			-- Check LPN in Scaned Location
			------------------------------------------------------
			IF NOT EXISTS (SELECT pickDT.lpn FROM t_wms_outbound_pick_detail pickDT
							WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
							AND pickDT.location_id = @in_vchLocationID
							AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
							AND pickDT.is_override = 'NO')
				BEGIN
					SET @out_vchErrorCode = 'INFO-NOT-EXIST-LPN-IN-LOCATION'
					GOTO EXIT_LABEL
				END 
		END
	
	--------------------------------------------------------------------
	-- ตรวจสอบ Item Number และ ใน Cross Ref
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		, @v_vchItemDesc = item.description
		, @v_vchLotControl = item.lot_control
		, @v_vchSNControl = item.sn_control
		, @v_vchExpiryDateControl = item.expiry_date_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchUomPrompt = uom.uom_prompt
		, @v_vchItemIsActive = item.is_active
	FROM  t_wms_item item
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
 	LEFT JOIN t_wms_item_crossref itemRef on item.item_master_id = itemRef.item_master_id 
	WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR itemRef.alternate_item_number = @in_vchItemNumber)
	AND item.owner_id = @in_vchOwnerID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF @v_vchWhItemMasterID IS NULL
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			GOTO EXIT_LABEL;
		END 

	--------------------------------------------------------------------
	--Check Item In Plan
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID 
					AND is_override = 'NO'
					AND wh_item_master_id = @v_vchWhItemMasterID)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_DETAIL_NOT_FOUND_ITEM'
			GOTO EXIT_LABEL;
		END
	
	IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		END

	IF @v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	
	IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END
 
 	IF (@v_vchSNControl = 'FULL') AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	 
	------------------------------------------------------
	-- Validate
	------------------------------------------------------
	IF @v_vchSNControl = 'NONE'
		BEGIN
			----------------------------------------------------------
			-- Validate attribute 1 in Pick Detail
			----------------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
							WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							AND is_override = 'NO')
			BEGIN 
				SET @out_vchErrorCode = 'NOT_FOUND_DATA_IN_PICK_DETAIL'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,'@param4','@param5')
				RETURN; 
			END
			IF @in_vchPickMode = 'BY EACH'
				BEGIN
					SET @in_fltQuantity = 1;
					GOTO SAVE_TRANS;	
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'UOM_QTY'
					GOTO NEXT_SCREEN;
				END
		END
	ELSE
		BEGIN
			-------------------------------------------------
			-- Validate Serial Number ที่สแกนใน Pick Detail
			-------------------------------------------------
			select @in_vchOutboundPickMasterID
			IF EXISTS (SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_detail pickDT
						WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
						AND pickDT.location_id = @in_vchLocationID
						AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
						AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
						AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND pickDT.serial_number = @in_vchSerialNumber
						AND ISNULL(pickDT.quantity_pick,0) > 0
						AND pickDT.is_override = 'NO')
				BEGIN
					SET @out_vchErrorCode = 'INFO-SN-DUPLICATED'
					GOTO EXIT_LABEL
				END
					
			-----------------------------------------------------------
			-- Get Qty_Plan, Qty_Pick, uom, conversion_factor ของแผน
			-----------------------------------------------------------
			SELECT @v_fltQuantityPlan  = ROUND(SUM(pickDT.quantity_plan),@v_intRound)
				,@v_fltQuantityPick = ROUND(SUM(pickDT.quantity_pick),@v_intRound)
			FROM t_wms_outbound_pick_detail pickDT					
			WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND pickDT.location_id = @in_vchLocationID
			AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
			AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLpn,'')
			AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')

			--------------------------------------------------------------------------
			-- ถ้า (จำนวนที่สแกน + จำนวนที่ Pick ไปแล้ว) มากกว่า (จำนวนแผน - จำนวนที่ Pick ไปแล้ว)
			--------------------------------------------------------------------------
			IF (ROUND((1 + @v_fltQuantityPick),@v_intRound) > ROUND(@v_fltQuantityPlan,@v_intRound))
				BEGIN
					SET @out_vchErrorCode = 'INFO-QTY-MORE-THAN-QTY-PLAN'
					GOTO EXIT_LABEL;
				END
						 
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
		END	
	 

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
	SELECT @v_vchWhItemMasterID AS wh_item_master_id
		, @v_vchItemMasterID	AS item_master_id
		, @v_vchItemDesc		AS item_description
		, @v_vchUomPrompt		AS uom_prompt
		, @in_vchLPN			AS lpn
		, @in_vchLotNumber		AS lot_number
		, @in_vchExpiryDate		AS expiry_date
		, @in_vchAttribute1		AS attribute1	
		, @in_vchAttribute2		AS attribute2	
		, @in_vchAttribute3		AS attribute3	
		, @in_vchAttribute4		AS attribute4	
		, @in_vchAttribute5		AS attribute5	
		, @in_vchSerialNumber	AS serial_number

		, @v_vchOverWhItemMasterID AS override_wh_item_master_id
		, @v_vchOverItemMasterID   AS override_item_master_id
		, @v_vchOverItemNumber     AS override_item_number
		, @v_vchOverItemDesc	   AS override_item_description 
		, @v_vchOverUomPrompt	   AS override_uom_prompt
		, @v_vchOverLPN			   AS override_lpn
		, @v_vchOverLotNumber	   AS override_lot_number
		, @v_vchOverExpiryDate	   AS override_expiry_date
		, @v_vchOverAttribute1	   AS override_attribute1
		, @v_vchOverAttribute2	   AS override_attribute2
		, @v_vchOverAttribute3	   AS override_attribute3
		, @v_vchOverAttribute4	   AS override_attribute4
		, @v_vchOverAttribute5	   AS override_attribute5
		, @v_vchOverSerialNumber   AS override_serial_number

		, @v_vchNewLocationID	AS location_id
		, @v_vchNewLocation		AS location
		, @v_vchNewParentLPN		AS parent_lpn
		
		--, @v_vchLotControl		AS lot_control
		--, @v_vchExpiryDateControl AS expiry_date_control
		--, @v_vchSNControl			AS sn_control
		--, @v_vchAttribute1Control AS attribute1_control
		--, @v_vchAttribute2Control AS attribute2_control
		--, @v_vchAttribute3Control AS attribute3_control
		--, @v_vchAttribute4Control AS attribute4_control
		--, @v_vchAttribute5Control AS attribute5_control

		, @in_fltQuantity		  AS display_default_qty
		, @in_fltQuantity		  AS qty
	RETURN;

	BEGIN --Save Normal
	SAVE_TRANS:
		DECLARE @v_vchToLPN NVARCHAR(25) = NULL
		IF ISNULL(@in_vchContainerNo,'') = '' 
			SET @v_vchToLPN = @in_vchBoxNumber
		ELSE
			SET @v_vchToLPN = @in_vchContainerNo

		EXEC usp_outbound_update_pick_item @in_vchApplicationID	 = @in_vchApplicationID	
										  ,@in_vchWarehouse		 = @in_vchWhID		
										  ,@in_vchDeviceID		 = @in_vchDeviceID			
										  ,@in_vchUserID		 = @in_vchUserID			
										  ,@in_vchPicklistNumber = @in_vchOutboundOrderNumber	
										  ,@in_vchFromLocation	 = @in_vchLocation		
										  ,@in_vchForkLift		 = @in_vchForkLocation			
										  ,@in_vchItemNumber	 = @in_vchItemNumber				
										  ,@in_fltQty			 = @in_fltQuantity				
										  ,@in_vchUOMPrompt		 = @v_vchUOMPrompt		
										  ,@in_vchFromParentLPN	 = @in_vchParentLPN	
										  ,@in_vchFromLPN		 = @in_vchLPN			
										  ,@in_vchToParentLPN	 = NULL		
										  ,@in_vchToLPN			 = @v_vchToLPN		
										  ,@in_vchLot			 = @in_vchLotNumber				
										  ,@in_vchExpiryDate	 = @in_vchExpiryDate		
										  ,@in_vchSerialNo		 = @in_vchSerialNumber		
										  ,@in_vchOverPickReason = NULL	
										  ,@in_vchAttribute1	 = @in_vchAttribute1		
										  ,@in_vchAttribute2	 = @in_vchAttribute2		
										  ,@in_vchAttribute3	 = @in_vchAttribute3		
										  ,@in_vchAttribute4	 = @in_vchAttribute4		
										  ,@in_vchAttribute5	 = @in_vchAttribute5		
										  ,@in_vchTrackingNo	 = NULL 
										  ,@out_ErrorCode		 = @out_vchErrorCode OUTPUT
										  ,@out_ErrorMessage	 = @out_vchErrorMsg	OUTPUT
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END			
		GOTO CHECK_DISPLAY_FINAL;
	END

	CHECK_DISPLAY_FINAL:
		IF @v_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;

		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				GOTO NEXT_SCREEN;
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_picking_final_screen @in_vchApplicationID		= @in_vchApplicationID	
 												  ,@in_vchControlName		= @in_vchControlName		
												  ,@in_vchWhMasterID		= @in_vchWhMasterID		
												  ,@in_vchOutboundMasterID	= @in_vchOutboundMasterID	
												  ,@in_vchLocationID		= @in_vchLocationID		
												  ,@in_vchParentLPN			= @in_vchParentLPN		
												  ,@in_vchLPN				= @in_vchLPN				
												  ,@in_vchWhItemMasterID	= @v_vchWhItemMasterID	
												  ,@in_vchItemMasterID		= @v_vchItemMasterID		
												  ,@in_vchLotNumber			= @in_vchLotNumber		
												  ,@in_vchExpDate			= @in_vchExpiryDate
												  ,@in_vchSerialNumber		= @in_vchSerialNumber		
												  ,@in_vchLocalID			= @in_vchLocalID			
												  ,@out_vchErrorCode		= @out_vchErrorCode	OUTPUT	
												  ,@out_vchErrorMsg			= @out_vchErrorMsg OUTPUT	
												  ,@out_vchNextScreen		= @out_vchNextScreen OUTPUT
		
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')		

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_unpick_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_unpick_2D]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchControlName			NVARCHAR(50),	--Current Screen
	@in_vchLocalID				VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),  
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWhID					NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40)= NULL,
	@in_vchStgLocationID	    UNIQUEIDENTIFIER = NULL,
	@in_vchStgLocation			NVARCHAR(50)= NULL,
	@in_vchStgParentLPN			NVARCHAR(25),
	@in_vchStgLPN				NVARCHAR(25),
	@in_vchItemNumber			NVARCHAR(50),  
	@in_vchLotNumber			NVARCHAR(50)= NULL,	
	@in_vchExpiryDate			NVARCHAR(10)= NULL,	
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_fltQuantity				FLOAT,
	@out_vchErrorCode			VARCHAR(50)	 OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @v_intRound				INT			
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control VARCHAR(5) = NULL
	DECLARE @v_vchUom				NVARCHAR(20) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_fltQuantityPlan		FLOAT
	DECLARE @v_fltQuantityPick		FLOAT
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
			
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStgLPN,''))
	BEGIN
		SET @out_vchErrorCode = 'NOT_FOUND_LPN_FOR_UNPICK'
		GOTO EXIT_LABEL
	END

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchItemDesc = item.description
		, @v_vchLotControl = item.lot_control
		, @v_vchExpiryDateControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control 
		, @v_vchUomPrompt = uom.uom_prompt
		, @v_vchUOM = uom.uom
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES' 
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @in_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchWhID,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchLotControl = 'NONE'
		BEGIN
			SET @in_vchLotNumber = NULL
		END

	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		END
	ELSE IF @v_vchExpiryDateControl = 'NONE'
		BEGIN
			SET @in_vchExpiryDate = NULL
		END

	IF @v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchAttribute1Control = 'NONE'
		BEGIN
			SET @in_vchAttribute1 = NULL
		END

	IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchAttribute2Control = 'NONE'
		BEGIN
			SET @in_vchAttribute2 = NULL
		END

	IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchAttribute3Control = 'NONE'
		BEGIN
			SET @in_vchAttribute3 = NULL
		END

	IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchAttribute4Control = 'NONE'
		BEGIN
			SET @in_vchAttribute4 = NULL
		END

	IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchAttribute5Control = 'NONE'
		BEGIN
			SET @in_vchAttribute5 = NULL
		END

	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END
	ELSE IF @v_vchSNControl = 'NONE'
		BEGIN
			SET @in_vchSerialNumber = NULL
		END

	--------------------------------------------------
	-- Validate location
	--------------------------------------------------
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
	BEGIN
		SET @out_vchErrorCode = 'INFO_NOT_FOUND_DATA_FOR_UNPICK'
		GOTO EXIT_LABEL
	END 
	 
	IF @v_vchSNControl = 'FULL'
		BEGIN
			GOTO SAVE_TRANS;
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'UOM_QTY'
		END
		 
	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
		SELECT  @v_vchWhItemMasterID	AS wh_item_master_id
			   ,@v_vchItemMasterID		AS item_master_id
			   ,@in_vchItemNumber		AS item_number
			   ,@v_vchItemDesc		    AS item_description
			   ,@v_vchLotControl	    AS lot_control
			   ,@v_vchSNControl		    AS sn_control
			   ,@v_vchExpiryDateControl	AS expiry_date_control
			   ,@v_vchUomPrompt		    AS uom_prompt
			   ,@v_vchAttribute1Control AS attribute1_control
			   ,@v_vchAttribute2Control AS attribute2_control
			   ,@v_vchAttribute3Control AS attribute3_control
			   ,@v_vchAttribute4Control AS attribute4_control
			   ,@v_vchAttribute5Control AS attribute5_control
			   ,@in_fltQuantity			AS display_default_qty
			   ,(CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

	RETURN;

	SAVE_TRANS: 
		SELECT @in_vchItemNumber		AS item_number
			,@v_vchItemDesc		    AS item_description 
			,@v_vchUomPrompt		    AS uom_prompt
			,(CASE WHEN @v_vchSNControl = 'FULL' THEN 1 ELSE 0 END) AS qty

		EXEC usp_outbound_unpick @in_vchApplicationID		= @in_vchApplicationID
								,@in_vchWarehouse			= @in_vchWhID			
								,@in_vchDeviceID			= @in_vchDeviceID					
								,@in_vchUserID				= @in_vchUserID				
								,@in_vchOutboundOrderNumber	= @in_vchOutboundOrderNumber	
								,@in_vchOwner				= @in_vchOwnerCode
								,@in_vchStgLocation			= @in_vchStgLocation			
								,@in_vchStgParentLPN		= @in_vchStgParentLPN					
								,@in_vchStgLPN				= @in_vchStgLPN
								,@in_vchItemNumber			= @in_vchItemNumber			
								,@in_vchLotNumber			= @in_vchLotNumber			
								,@in_vchExpiryDate			= @in_vchExpiryDate			
								,@in_vchSerialNumber		= @in_vchSerialNumber				
								,@in_vchAttribute1			= @in_vchAttribute1			
								,@in_vchAttribute2			= @in_vchAttribute2			
								,@in_vchAttribute3			= @in_vchAttribute3			
								,@in_vchAttribute4			= @in_vchAttribute4			
								,@in_vchAttribute5			= @in_vchAttribute5			
								,@in_fltQuantity			= @in_fltQuantity					
								,@in_vchUOM					= @v_vchUOM					
								,@out_ErrorCode				= @out_vchErrorCode OUTPUT		
								,@out_ErrorMessage			= @out_vchErrorMsg	OUTPUT								
								
		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END

		--IF @v_vchSNControl = 'FULL'
		--	GOTO FINAL_SCREEN;	
	  
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_unpick_final_screen  @in_vchApplicationID		   = @in_vchApplicationID	 	
 												  ,@in_vchLocalID			   = @in_vchLocalID			 
												  ,@in_vchControlName		   = @in_vchControlName		 
												  ,@in_vchWhMasterID		   = @in_vchWhMasterID		 
												  ,@in_vchOutboundMasterID	   = @in_vchOutboundMasterID	 
												  ,@in_vchOwnerID			   = @in_vchOwnerID			 
												  ,@in_vchOutboundPickMasterID = @in_vchOutboundPickMasterID
												  ,@in_vchStgLocationID	 	   = @in_vchStgLocationID	 
												  ,@in_vchStgParentLPN		   = @in_vchStgParentLPN		 
												  ,@in_vchStagingLPN		   = @in_vchStgLPN		 
												  ,@in_vchWhItemMasterID	   = @v_vchWhItemMasterID	 
												  ,@out_vchErrorCode		   = @out_vchErrorCode OUTPUT	 
												  ,@out_vchErrorMsg		 	   = @out_vchErrorMsg OUTPUT
												  ,@out_vchNextScreen		   = @out_vchNextScreen	OUTPUT

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')		

END


GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_unpick_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_unpick_attribute1]
(
	@in_vchApplicationID	 VARCHAR(40) = NULL, 
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchSTGLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSTGParentLPN		 NVARCHAR(25)   = NULL,
	@in_vchStagingLPN		 NVARCHAR(25)   = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50)   = NULL,
	@in_vchExpDate			 NVARCHAR(50)   = NULL,
	@in_vchAttribute1		 NVARCHAR(100)	= NULL,
	@in_vchAttribute2Control NVARCHAR(10)	= NULL,
	@in_vchAttribute3Control NVARCHAR(10)	= NULL,
	@in_vchAttribute4Control NVARCHAR(10)	= NULL,
	@in_vchAttribute5Control NVARCHAR(10)	= NULL,
	@in_vchSerialControl	 NVARCHAR(10)	= NULL,
	@out_vchErrorCode		 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStagingLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
	BEGIN
		SET @out_vchErrorCode = 'INFO_NOT_FOUND_ATTR1_IN_PICK_DETAIL'
		GOTO EXIT_LABEL
	END
	----------------------------------------
	--Next Screen
	----------------------------------------
	EXEC usp_validate_item_control @in_vchLotControl		= NULL	
								,@in_vchExpiryDateControl	= NULL
								,@in_vchAttribute1Control	= NULL
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSerialControl
								,@in_vchIsCheckLot			= 'NO'
								,@in_vchIsCheckExpiryDate	= 'NO'
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'YES'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO' 
								,@out_vchNextScreen	= @out_vchNextScreen OUTPUT
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_unpick_attribute2]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_unpick_attribute2]
(
	@in_vchApplicationID	 VARCHAR(40) = NULL, 
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchSTGLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSTGParentLPN		 NVARCHAR(25)   = NULL,
	@in_vchStagingLPN		 NVARCHAR(25)   = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50)   = NULL,
	@in_vchExpDate			 NVARCHAR(50)   = NULL,
	@in_vchAttribute1		 NVARCHAR(100)	= NULL,
	@in_vchAttribute2		 NVARCHAR(100)	= NULL,
	@in_vchAttribute3Control NVARCHAR(10)	= NULL,
	@in_vchAttribute4Control NVARCHAR(10)	= NULL,
	@in_vchAttribute5Control NVARCHAR(10)	= NULL, 
	@in_vchSerialControl	 NVARCHAR(10)	= NULL,
	@out_vchErrorCode		 VARCHAR(50)	OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStagingLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,''))
	BEGIN
