CREATE PROCEDURE [dbo].[usp_api_validate_unpick_lpn]
(
	@in_vchApplicationID	    VARCHAR(40),
	@in_vchLocalID			    VARCHAR(40),
	@in_vchWhMasterID		    UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	    UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchSTGLocationID	    UNIQUEIDENTIFIER = NULL,
	@in_vchStagingLPN		    NVARCHAR(50) = NULL,
	@out_vchErrorCode		    VARCHAR(50)	  OUTPUT,
	@out_vchErrorMsg		    NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		    NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStagingLPN,''))
	BEGIN
		SET @out_vchErrorCode = 'NOT_FOUND_LPN_FOR_UNPICK'
		GOTO EXIT_LABEL
	END
	
	SET @out_vchNextScreen = 'ITEM_NUMBER'	
	RETURN;

	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_unpick_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_unpick_order_number]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchLocalID				VARCHAR(40),
	@in_vchUserID				NVARCHAR(25),
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundOrderNumber	VARCHAR(50) = NULL,
	@out_vchErrorCode			VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500)	OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchStgLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchStgLocation		NVARCHAR(50) = NULL
	DECLARE @v_vchStgLPN			NVARCHAR(25) = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(40) = NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10) = NULL
	DECLARE @v_nCount				INT = 0

	SELECT TOP 1 @v_vchOutboundMasterID = obMs.outbound_order_master_id
		,@v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
		,@v_vchOwnerID = obMS.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchOrderStatus = obMS.order_status
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	INNER JOIN t_wms_outbound_pick_master pickMS WITH (NOLOCK) ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	WHERE obMS.outbound_order_number = @in_vchOutboundOrderNumber
	AND obMS.wh_master_id = @in_vchWhMasterID

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-OUTBOUND-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@v_vchOrderStatus IN ('OPEN','RELEASE','SHIP','CLOSE'))
		BEGIN
			SET @out_vchErrorCode = 'INFO-OUTBOUND-STATUS-NOT-PICK'
			GOTO EXIT_LABEL
		END

	--GET STG Location
	SELECT @v_vchStgLocationID = pickDT.staging_location_id
		,@v_vchStgLocation = loc.location
		,@v_nCount = COUNT (DISTINCT pickDT.staging_lpn)
	FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
	INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id 
	WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID 
	AND pickDT.staging_location_id IS NOT NULL
	GROUP BY pickDT.staging_location_id, loc.location

	IF @v_vchSTGLocationID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'NOT_FOUND_LOCATION_FOR_UNPICK'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------
	--NEXT SCREEN
	------------------------------------------------------
	IF @v_nCount > 1 
		BEGIN
			SET @out_vchNextScreen = 'LPN'	
		END
	ELSE
		BEGIN
			SELECT TOP 1 @v_vchStgLPN = staging_lpn
			FROM t_wms_outbound_pick_detail WITH (NOLOCK)
			WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
			AND staging_location_id IS NOT NULL
			AND ISNULL(quantity_pick,0) > 0
			SET @out_vchNextScreen = 'ITEM_NUMBER'	
		END
	

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	SELECT @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code
		, @v_vchOutboundMasterID AS outbound_order_master_id
		, @v_vchOutboundPickMasterID as outbound_pick_master_id
		, @v_vchStgLocationID AS staging_location_id
		, @v_vchStgLocation AS staging_location
		, @v_vchStgLPN AS staging_lpn

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_unpick_serial_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_unpick_serial_number]
(
	@in_vchApplicationID	 VARCHAR(40) = NULL, 
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchSTGLocationID	 UNIQUEIDENTIFIER = NULL,
	@in_vchSTGParentLPN		 NVARCHAR(25)   = NULL,
	@in_vchStagingLPN		 NVARCHAR(25)   = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		 NVARCHAR(50)   = NULL,
	@in_vchExpDate			 NVARCHAR(50)   = NULL,
	@in_vchAttribute1		 NVARCHAR(100)	= NULL,
	@in_vchAttribute2		 NVARCHAR(100)	= NULL,
	@in_vchAttribute3		 NVARCHAR(100)	= NULL,
	@in_vchAttribute4		 NVARCHAR(100)	= NULL,
	@in_vchAttribute5		 NVARCHAR(100)	= NULL,
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF NOT EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
					WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
					AND ISNULL(quantity_pick,0) > 0
					AND is_override = 'NO'
					AND staging_location_id = @in_vchSTGLocationID 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStagingLPN,'')
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
	BEGIN
		SET @out_vchErrorCode = 'INFO_NOT_FOUND_SN_IN_PICK_DETAIL'
		GOTO EXIT_LABEL
	END
  
	SET @out_vchNextScreen = 'FINAL_SCREEN'
	RETURN;
	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_attribute1]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_attribute1]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		 NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN		 NVARCHAR(50) = NULL,
	@in_vchLPN				 NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL, 
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpDate			 NVARCHAR(50) = NULL, 
	@in_vchAttribute1		 NVARCHAR(100)= NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchLocalID			 VARCHAR(40)  = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON; 
	--------------------------------------------------
	-- Validate Parent LPN Not default in plan
	--------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			--------------------------------------------
			-- Check Location in Inventory
			--------------------------------------------
			GOTO VALIDATE_INVENTORY;
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
				
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			----------------------------------------------------------------- 
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,''))
				BEGIN
					-- LPN ที่สแกนไม่ตรงตาม Pick Rule ที่กำหนด
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END

			GOTO NEXT_SCREEN;
