CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_expiry_date]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		 NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN		 NVARCHAR(50) = NULL,
	@in_vchLPN				 NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpDate			 NVARCHAR(50) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;  
	--------------------------------------------------
	-- Validate Parent LPN Not default in plan
	--------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			--------------------------------------------
			-- Check Location in Inventory
			--------------------------------------------
			GOTO VALIDATE_INVENTORY;
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 

			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			----------------------------------------------------------------- 
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,''))
				BEGIN
					-- LPN ที่สแกนไม่ตรงตาม Pick Rule ที่กำหนด
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END

			GOTO NEXT_SCREEN;
		END 
	
	VALIDATE_INVENTORY:
		--------------------------------------------
		-- Check Location in Inventory
		-------------------------------------------- 
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick 
						WHERE wh_master_id = @in_vchWhMasterID
						AND owner_id = @in_vchOwnerID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inv_status = @in_vchItemStatus
						AND location_id = @in_vchLocationID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpDate,'')) 
		BEGIN
			SET @out_vchErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- Next Screen
		------------------------------------------------------
		DECLARE @v_vchRulePickByEach	NVARCHAR(10) = NULL
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
			BEGIN
				SET @v_vchRulePickByEach = 'BY EACH'
			END
		EXEC usp_validate_item_control @in_vchLotControl			= NULL	
										,@in_vchExpiryDateControl	= NULL
										,@in_vchAttribute1Control	= @in_vchAttribute1Control
										,@in_vchAttribute2Control	= @in_vchAttribute2Control
										,@in_vchAttribute3Control	= @in_vchAttribute3Control
										,@in_vchAttribute4Control	= @in_vchAttribute4Control
										,@in_vchAttribute5Control	= @in_vchAttribute5Control
										,@in_vchSNControl			= @in_vchSNControl
										,@in_vchIsCheckLot			= 'NO'
										,@in_vchIsCheckExpiryDate	= 'NO'
										,@in_vchIsCheckAttribute1	= 'YES'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@in_vchItemMode			= @v_vchRulePickByEach
										,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	
	RETURN;
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,REPLACE(@in_vchPickRule,'_',' '),'@param2','@param3','@param4','@param5')			
END
