CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_load_item_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		NVARCHAR(25) = NULL,
	@in_vchLoadID			NVARCHAR(50)  = NULL, 
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(50) = NULL,
	@in_vchLPN				NVARCHAR(50) = NULL, 
	@in_vchItemNumber		NVARCHAR(50) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchInvStatus		NVARCHAR(50) OUTPUT,		--By each และ not control จะต้องใช้ id นี้
	@out_vchItemMasterID	UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchWhItemMasterID  UNIQUEIDENTIFIER OUTPUT,	--By each และ not control จะต้องใช้ id นี้
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @Round					INT
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40)= NULL
	DECLARE @v_vchPickRule			NVARCHAR(40)= NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL

	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @out_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchItemDesc = item.description
		, @v_vchLotControl = item.lot_control
		, @v_vchExpDateControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchPickRule = r.rule_code
		, @v_vchUomPrompt = uom.uom_prompt
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_rule r on uom.picking_class = r.rule_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @in_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@out_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @out_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @out_vchItemMasterID
	IF (@out_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchWarehouse,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	-- Check item in plan
	------------------------------------------------------
	IF NOT EXISTS (SELECT obDT.outbound_order_detail_id 
					FROM t_wms_outbound_detail obDT
					INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
					WHERE obMS.wh_master_id = @in_vchWhMasterID
					AND obMS.load_id = @in_vchLoadID
					AND obDT.wh_item_master_id = @out_vchWhItemMasterID 
					AND ROUND(ISNULL(obDT.quantity_order,0),@Round) <> ROUND(ISNULL(obDT.quantity_pick,0),@Round))
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_DETAIL_NOT_FOUND_ITEM'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	--Check Item in inventory
	------------------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id =  @in_vchWhMasterID 
					AND owner_id = @in_vchOwnerID 
					AND location_id =  @in_vchLocationID 
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
					AND wh_item_master_id = @out_vchWhItemMasterID)
	BEGIN
		SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND-IN-INVENTORY'
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
		RETURN;
	END
		 
	------------------------------------------------------
	-- Check Default Item Status
	------------------------------------------------------
	DECLARE @n_count INT = 0
	SELECT @n_count = COUNT(DISTINCT obDT.default_item_status)
	FROM t_wms_outbound_detail obDT
	INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
	WHERE obMS.wh_master_id = @in_vchWhMasterID
	AND obMS.load_id = @in_vchLoadID
	AND obDT.wh_item_master_id = @out_vchWhItemMasterID 
	AND ROUND(ISNULL(obDT.quantity_order,0),@Round) <> ROUND(ISNULL(obDT.quantity_pick,0),@Round)

	IF @n_count > 1
		BEGIN
			SET @out_vchNextScreen = 'ITEM_STATUS'
			GOTO NEXT_SCREEN;
		END
	ELSE
		BEGIN
			DECLARE @v_vchRulePickByEach	VARCHAR(10) = NULL
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @v_vchRulePickByEach = 'BY EACH'
				END

			SELECT TOP 1 @out_vchInvStatus = obDT.default_item_status FROM t_wms_outbound_detail obDT
			INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID 
			AND obDT.wh_item_master_id = @out_vchWhItemMasterID 
			AND ROUND(ISNULL(obDT.quantity_order,0),@Round) <> ROUND(ISNULL(obDT.quantity_pick,0),@Round)
			
			EXEC usp_validate_item_control @in_vchLotControl		= @v_vchLotControl	
										,@in_vchExpiryDateControl	= @v_vchExpDateControl
										,@in_vchAttribute1Control	= @v_vchAttribute1Control
										,@in_vchAttribute2Control	= @v_vchAttribute2Control
										,@in_vchAttribute3Control	= @v_vchAttribute3Control
										,@in_vchAttribute4Control	= @v_vchAttribute4Control
										,@in_vchAttribute5Control	= @v_vchAttribute5Control
										,@in_vchSNControl			= @v_vchSNControl
										,@in_vchIsCheckLot			= 'YES'
										,@in_vchIsCheckExpiryDate	= 'NO'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@in_vchItemMode			= @v_vchRulePickByEach
										,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
		END

	NEXT_SCREEN:
	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	SELECT @out_vchWhItemMasterID	AS wh_item_master_id
		, @out_vchItemMasterID		AS item_master_id
		, @in_vchItemNumber			AS item_number
		, @v_vchItemDesc		    AS item_description
		, @v_vchLotControl			AS lot_control
		, @v_vchSNControl			AS sn_control
		, @v_vchExpDateControl		AS expiry_date_control
		, @v_vchUomPrompt			AS uom_prompt
		, @v_vchPickRule			AS pick_rule
		, @out_vchInvStatus			AS item_status
		, @v_vchAttribute1Control	AS attribute1_control
		, @v_vchAttribute2Control	AS attribute2_control
		, @v_vchAttribute3Control	AS attribute3_control
		, @v_vchAttribute4Control	AS attribute4_control
		, @v_vchAttribute5Control	AS attribute5_control
		, (CASE WHEN @v_vchSNControl = 'FULL' OR @out_vchNextScreen = 'FINAL_SCREEN' THEN 1 ELSE 0 END) AS qty
	RETURN; 
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_load_item_status]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_load_item_status]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		NVARCHAR(25) = NULL,
	@in_vchLoadID			NVARCHAR(50)  = NULL, 
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(50) = NULL,
	@in_vchLPN				NVARCHAR(50) = NULL, 
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchLotControl		 VARCHAR(5) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchExpiryDateControl VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL, 
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @in_vchItemStatus NOT IN (SELECT default_item_status FROM t_wms_outbound_detail obDT
								 INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
								 WHERE obMS.wh_master_id = @in_vchWhMasterID
								 AND obMS.load_id = @in_vchLoadID
								 AND obDT.wh_item_master_id = @in_vchWhItemMasterID 
								 AND ISNULL(obDT.default_item_status,'') <> '')
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-STATUS-NOT-FOUND'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	DECLARE @v_vchRulePickByEach	VARCHAR(10) = NULL
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @v_vchRulePickByEach = 'BY EACH'
		END
			
	EXEC usp_validate_item_control @in_vchLotControl		= @in_vchLotControl	
								,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
								,@in_vchAttribute1Control	= @in_vchAttribute1Control
								,@in_vchAttribute2Control	= @in_vchAttribute2Control
								,@in_vchAttribute3Control	= @in_vchAttribute3Control
								,@in_vchAttribute4Control	= @in_vchAttribute4Control
								,@in_vchAttribute5Control	= @in_vchAttribute5Control
								,@in_vchSNControl			= @in_vchSNControl
								,@in_vchIsCheckLot			= 'YES'
								,@in_vchIsCheckExpiryDate	= 'NO'
								,@in_vchIsCheckAttribute1	= 'NO'
								,@in_vchIsCheckAttribute2	= 'NO'
								,@in_vchIsCheckAttribute3	= 'NO'
								,@in_vchIsCheckAttribute4	= 'NO'
								,@in_vchIsCheckAttribute5	= 'NO'
								,@in_vchIsCheckSN			= 'NO'
								,@in_vchItemMode			= @v_vchRulePickByEach
								,@out_vchNextScreen			= @out_vchNextScreen OUTPUT
	RETURN; 
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_load_load_id]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_load_load_id]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID			NVARCHAR(50)  = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchUserID			NVARCHAR(25),	
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	IF NOT EXISTS (SELECT outbound_order_master_id FROM t_wms_outbound_master WITH (NOLOCK) WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOAD-ID-NOT-EXIST'
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL
	-- สำหรับ PST แสดง Load_id เฉพาะ Order Status IN 'RELEASE','PICK'
	------------------------------------------------------------------------------
	IF EXISTS (SELECT load_id FROM v_wms_outbound_master_load WITH (NOLOCK) WHERE load_id = @in_vchLoadID AND wh_master_id = @in_vchWhMasterID
			AND load_status IN (SELECT value FROM dbo.t_wms_rule  WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
	BEGIN
		--Status ไม่ถูกต้อง
		SET @out_vchErrorCode = 'INFO-OUTBOUND-INVALID-STATUS'
		GOTO EXIT_LABEL
	END

	------------------------------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------------------------------
	IF (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
		END

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	DECLARE @v_vchOwnerID	UNIQUEIDENTIFIER = null
	DECLARE @v_vchOwnerCode	NVARCHAR(40)= null

	SELECT TOP 1 @v_vchOwnerID = owner_id
		, @v_vchOwnerCode = owner_code
	FROM t_wms_outbound_master WITH (NOLOCK)
 	WHERE load_id = @in_vchLoadID
	AND wh_master_id = @in_vchWhMasterID 
	AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
		
	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	SELECT @v_vchOwnerID AS owner_id
		, @v_vchOwnerCode AS owner_code
	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_load_location]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_load_location]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID			 NVARCHAR(50) = NULL, 
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			 NVARCHAR(50) = NULL,
	@in_vchLocalID			 VARCHAR(40)  = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE	@v_vchLocationID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLPNControl VARCHAR(3) = NULL
	DECLARE @v_vchLocType	 NVARCHAR(25) = NULL

	--------------------------------------------------
	-- Check Location Master
	--------------------------------------------------
	SELECT @v_vchLocationID = location_id
		, @v_vchLPNControl = lpn_controlled
		, @v_vchLocType = loc_type
	FROM t_wms_location 
	WHERE wh_master_id = @in_vchWhMasterID 
	AND location = @in_vchLocation 
	AND is_active = 'YES'

	IF @v_vchLocationID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
		
	IF @v_vchLocType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-FOR-PICK'
			GOTO EXIT_LABEL;
		END

	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND location_id = @v_vchLocationID)
		BEGIN
			SET @out_vchErrorCode = 'INFO-NOT-FOUND-ITEM-IN-LOCATION'
			GOTO EXIT_LABEL;
		END

	SELECT obDT.wh_item_master_id
		,obDT.default_item_status
	INTO #tOutbound
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	WHERE wh_master_id = @in_vchWhMasterID
	AND load_id = @in_vchLoadID
	AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0)

	IF NOT EXISTS (SELECT inv.inventory_id
					FROM t_wms_inventory inv
					INNER JOIN t_wms_inventory_status invST on inv.inventory_status_id = invST.inventory_status_id
					INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
					WHERE inv.wh_master_id = @in_vchWhMasterID
					AND inv.owner_id = @in_vchOwnerID
					AND inv.wh_item_master_id IN (SELECT wh_item_master_id FROM #tOutbound)
					AND invST.inv_status IN (SELECT default_item_status FROM #tOutbound) 
					AND loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
					AND loc.location_id = @v_vchLocationID)
		BEGIN
			SET @out_vchErrorCode = 'INFO_NOT_FOUND_ITEM_FOR_PICK_IN_LOCATION'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	IF @v_vchLPNControl = 'YES'
		BEGIN
			-----------------------------------------------
			-- Check Rule Parent LPN
			-----------------------------------------------
			IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
				BEGIN
					SET @out_vchNextScreen = 'PARENT_LPN'
				END
			ELSE
				BEGIN
					SET @out_vchNextScreen = 'LPN'
				END
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'ITEM_NUMBER'		
		END
	
	------------------------------------------------
	-- สำหรับใช้หน้าจอถัดไป จะได้ไม่ต้อง get id ใหม่
	------------------------------------------------
	SELECT @v_vchLocationID AS location_id
	RETURN;
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_load_lot_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_load_lot_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		NVARCHAR(25) = NULL,
	@in_vchLoadID			NVARCHAR(50)  = NULL, 
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(50) = NULL,
	@in_vchLPN				NVARCHAR(50) = NULL, 
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchExpiryDateControl VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	----------------------------------------------
	---- ถ้ากำหนด lot ใน แผนให้เอา lot ในแผน
	----------------------------------------------
	--SELECT DISTINCT obDT.lot_number
	--INTO #tOutbound
	--FROM t_wms_outbound_master obMS
	--INNER JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	--WHERE obMS.wh_master_id = @in_vchWhMasterID
	--AND obMS.load_id = @in_vchLoadID
	--AND obDT.wh_item_master_id = @in_vchWhItemMasterID
	--AND ISNULL(obDT.lot_number,'') <> ''
		
	--IF (SELECT COUNT(*) FROM #tOutbound) > 0 AND @in_vchLotNumber NOT IN (SELECT lot_number FROM #tOutbound)
	--BEGIN
	--	SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-IN-PLAN'
	--	GOTO EXIT_LABEL;
	--END

	--------------------------------------------------
	-- Validate Parent LPN Not default in plan
	--------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			--------------------------------------------
			-- Check Location in Inventory
			--------------------------------------------
			GOTO VALIDATE_INVENTORY;
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						   )
				BEGIN
					-- Lot Number ที่สแกนไม่ตรงตาม Pick Rule ที่กำหนด
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END

			GOTO NEXT_SCREEN;
		END
	
	VALIDATE_INVENTORY:
		--------------------------------------------
		-- Check lot in Inventory
		-------------------------------------------- 
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick 
						WHERE wh_master_id = @in_vchWhMasterID
						AND owner_id = @in_vchOwnerID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inv_status = @in_vchItemStatus
						AND location_id = @in_vchLocationID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- Next Screen
		------------------------------------------------------
		DECLARE @v_vchRulePickByEach	NVARCHAR(10) = NULL
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
			BEGIN
				SET @v_vchRulePickByEach = 'BY EACH'
			END
		EXEC usp_validate_item_control @in_vchLotControl			= NULL	
										,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
										,@in_vchAttribute1Control	= @in_vchAttribute1Control
										,@in_vchAttribute2Control	= @in_vchAttribute2Control
										,@in_vchAttribute3Control	= @in_vchAttribute3Control
										,@in_vchAttribute4Control	= @in_vchAttribute4Control
										,@in_vchAttribute5Control	= @in_vchAttribute5Control
										,@in_vchSNControl			= @in_vchSNControl
										,@in_vchIsCheckLot			= 'NO'
										,@in_vchIsCheckExpiryDate	= 'YES'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@in_vchItemMode			= @v_vchRulePickByEach
										,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	
	RETURN;
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
