CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_lot_number]
(
	@in_vchApplicationID	 VARCHAR(40)  = NULL,
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse		 NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN		 NVARCHAR(50) = NULL,
	@in_vchLPN				 NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		 NVARCHAR(50) = NULL,
	@in_vchPickRule			 NVARCHAR(50) = NULL,
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchSNControl		 VARCHAR(5) = NULL,
	@in_vchExpiryDateControl VARCHAR(5) = NULL,
	@in_vchAttribute1Control VARCHAR(5) = NULL,
	@in_vchAttribute2Control VARCHAR(5) = NULL,
	@in_vchAttribute3Control VARCHAR(5) = NULL,
	@in_vchAttribute4Control VARCHAR(5) = NULL,
	@in_vchAttribute5Control VARCHAR(5) = NULL,
	@in_vchLocalID			 VARCHAR(40) = NULL,
	@out_vchErrorCode		 VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		 NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		 NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	 SET NOCOUNT ON;

	--------------------------------------------------
	-- Validate Parent LPN Not default in plan
	--------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
			AND (@in_vchWarehouse IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			--------------------------------------------
			-- Check Location in Inventory
			--------------------------------------------
			GOTO VALIDATE_INVENTORY;
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
			
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			ORDER BY CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @in_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						   )
				BEGIN
					-- Lot Number ที่สแกนไม่ตรงตาม Pick Rule ที่กำหนด
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END

			GOTO NEXT_SCREEN;
		END
	
	VALIDATE_INVENTORY:
		--------------------------------------------
		-- Check lot in Inventory
		-------------------------------------------- 
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick 
						WHERE wh_master_id = @in_vchWhMasterID
						AND owner_id = @in_vchOwnerID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inv_status = @in_vchItemStatus
						AND location_id = @in_vchLocationID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
	
	NEXT_SCREEN:
		------------------------------------------------------
		-- Next Screen
		------------------------------------------------------
		DECLARE @v_vchRulePickByEach	NVARCHAR(10) = NULL
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES'
			BEGIN
				SET @v_vchRulePickByEach = 'BY EACH'
			END
		EXEC usp_validate_item_control @in_vchLotControl			= NULL	
										,@in_vchExpiryDateControl	= @in_vchExpiryDateControl
										,@in_vchAttribute1Control	= @in_vchAttribute1Control
										,@in_vchAttribute2Control	= @in_vchAttribute2Control
										,@in_vchAttribute3Control	= @in_vchAttribute3Control
										,@in_vchAttribute4Control	= @in_vchAttribute4Control
										,@in_vchAttribute5Control	= @in_vchAttribute5Control
										,@in_vchSNControl			= @in_vchSNControl
										,@in_vchIsCheckLot			= 'NO'
										,@in_vchIsCheckExpiryDate	= 'YES'
										,@in_vchIsCheckAttribute1	= 'NO'
										,@in_vchIsCheckAttribute2	= 'NO'
										,@in_vchIsCheckAttribute3	= 'NO'
										,@in_vchIsCheckAttribute4	= 'NO'
										,@in_vchIsCheckAttribute5	= 'NO'
										,@in_vchIsCheckSN			= 'NO'
										,@in_vchItemMode			= @v_vchRulePickByEach
										,@out_vchNextScreen			= @out_vchNextScreen OUTPUT	
	
	RETURN;
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,REPLACE(@in_vchPickRule,'_',' '),'@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_lpn]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------
	-- Check LPN in Inventory Tabel
	--------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id =  @in_vchWhMasterID 
					AND owner_id =  @in_vchOwnerID 
					AND location_id =  @in_vchLocationID 
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	SET @out_vchNextScreen = 'ITEM_NUMBER'	
	RETURN;
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_order_2D]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_order_2D]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchForkID			UNIQUEIDENTIFIER,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundOrderNumber	NVARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,	
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchBoxNumber		NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL, 
	@in_vchLocation			NVARCHAR(50),	
	@in_vchParentLPN		NVARCHAR(25),	
	@in_vchLPN				NVARCHAR(25),	
	@in_vchItemNumber		NVARCHAR(50), 
	@in_vchItemStatus		NVARCHAR(50),
	@in_vchLotNumber		NVARCHAR(50),	
	@in_vchExpiryDate		NVARCHAR(10),	
	@in_vchSerialNumber		NVARCHAR(50),
	@in_vchAttribute1		NVARCHAR(100),
	@in_vchAttribute2		NVARCHAR(100),
	@in_vchAttribute3		NVARCHAR(100),
	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100),
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_fltQuantity			FLOAT,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_intRound				INT		
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemDesc			NVARCHAR(200) = NULL
	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
	DECLARE @v_vchSNControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control VARCHAR(5) = NULL
	DECLARE @v_vchItemUOMID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_fltQuantityPlan		FLOAT
	DECLARE @v_fltQuantityPick		FLOAT
	DECLARE @v_vchPickRule			NVARCHAR(40)  = NULL
	DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
			
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
	 
	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchItemDesc = item.description
		, @v_vchLotControl = item.lot_control
		, @v_vchExpiryDateControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchPickRule = r.rule_code
		, @v_vchItemUOMID = uom.item_uom_id
		, @v_vchUomPrompt = uom.uom_prompt
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	LEFT JOIN t_wms_rule r on uom.picking_class = r.rule_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @in_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchWhID,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	IF @v_vchLotControl = 'FULL' AND ISNULL(@in_vchLotNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ISNULL(@in_vchExpiryDate,'') = ''
				BEGIN
					SET @out_vchNextScreen = 'EXPIRY_DATE'
					GOTO NEXT_SCREEN;
				END
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		END

	IF @v_vchAttribute1Control = 'FULL' AND ISNULL(@in_vchAttribute1,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'
			GOTO NEXT_SCREEN;
		END	

	IF @v_vchAttribute2Control = 'FULL' AND ISNULL(@in_vchAttribute2,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute3Control = 'FULL' AND ISNULL(@in_vchAttribute3,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			GOTO NEXT_SCREEN;
		END

	IF @v_vchAttribute4Control = 'FULL' AND ISNULL(@in_vchAttribute4,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'
			GOTO NEXT_SCREEN;
		END	

	IF @v_vchAttribute5Control = 'FULL' AND ISNULL(@in_vchAttribute5,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			GOTO NEXT_SCREEN;
		END	

	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') = ''
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			GOTO NEXT_SCREEN;
		END

	IF ISNULL(@in_vchItemStatus,'') = ''
		BEGIN
			------------------------------------------------------
			-- Check Default Item Status
			------------------------------------------------------
			SELECT DISTINCT @in_vchItemStatus = default_item_status FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID AND quantity_order <> ISNULL(quantity_pick,0) 
			IF @@ROWCOUNT > 1
				BEGIN
					SET @out_vchNextScreen = 'ITEM_STATUS'
					GOTO NEXT_SCREEN;
				END
		END
		 
	--------------------------------------------------
	-- Validate Parent LPN Not default in plan
	--------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_LOCATION' AND is_active = 'YES') = 'YES')
			AND (@in_vchWhID IN (SELECT value FROM t_wms_rule where rule_code = 'RULE_WAREHOUSE_OVERRIDE_LOCATION' AND is_active = 'YES')))	
		BEGIN
			--------------------------------------------
			-- Check Location in Inventory Tabel
			--------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick 
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
			BEGIN
				SET @out_vchErrorCode = 'NOT_FOUND_INVENTORY_DATA_NO_DETAIL'
				GOTO EXIT_LABEL;
			END
		END
	ELSE
		BEGIN
			DECLARE @v_vchReceiveDate	VARCHAR(8) = ''
			DECLARE @v_vchExpDate		NVARCHAR(50) = '' 
				
			-----------------------------------------------------------------
			-- ดึงข้อมูล Receive Date/Expiry Date ตาม Pick Rule ที่กำหนด
			-----------------------------------------------------------------
			SELECT TOP 1 @v_vchReceiveDate = CONVERT(VARCHAR(8),receive_date,112)
				, @v_vchExpDate = expiry_date
			FROM v_wms_inventory_for_user_pick
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND location_id	 = @in_vchLocationID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND inv_status = @in_vchItemStatus
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			ORDER BY CASE WHEN @v_vchPickRule = 'RULE_PICK_BY_FEFO' THEN expiry_date END, receive_date, lot_number, pick_sequence, location , ISNULL(parent_lpn,''), ISNULL(lpn,'')

			-----------------------------------------------------------------
			-- Check Location ตาม Pick Rule
			-----------------------------------------------------------------
			IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_for_user_pick
							WHERE wh_master_id = @in_vchWhMasterID 
							AND owner_id = @in_vchOwnerID
							AND location_id = @in_vchLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND inv_status = @in_vchItemStatus
							AND (CASE WHEN @v_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(expiry_date,'') ELSE CONVERT(VARCHAR(8),receive_date,112) END) = (CASE WHEN @v_vchPickRule = 'RULE_PICK_BY_FEFO' THEN ISNULL(@v_vchExpDate,'') ELSE @v_vchReceiveDate END)  --WHERE From Pick Rule
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,''))
				BEGIN
					-- LPN ที่สแกนไม่ตรงตาม Pick Rule ที่กำหนด
					-- หยิบไม่ตรงเงื่อนไข [0] ที่กำหนด, Pick not in condition [0] setup
					SET @out_vchErrorCode = 'INFO-PICK-NOT-IN-CONDITION'
					GOTO EXIT_LABEL;
				END

		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	IF (@v_vchSNControl = 'FULL') OR ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_USER_PICK_BY_EACH' AND is_active = 'YES') = 'YES')
		BEGIN
			SET @in_fltQuantity = 1
			GOTO SAVE_TRANS;
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'UOM_QTY'
		END

	------------------------------------------------------
	-- สำหรับนำไปใช้ที่หน้าจอ
	------------------------------------------------------
	NEXT_SCREEN:
		DECLARE @v_fltQtyPlan		FLOAT
		DECLARE @v_fltQtyPick		FLOAT
		DECLARE @v_fltQtyRemainPick	FLOAT 
		SELECT @v_fltQtyPlan = SUM(quantity_order)
			, @v_fltQtyPick = SUM(ISNULL(quantity_pick,0))
			, @v_fltQtyRemainPick = ROUND(SUM(quantity_order - ISNULL(quantity_pick,0)),@v_intRound)  
		FROM t_wms_outbound_detail
 		WHERE outbound_order_master_id = @in_vchOutboundMasterID 
		AND wh_item_master_id = @v_vchWhItemMasterID 

		SELECT  @v_vchWhItemMasterID	AS wh_item_master_id
			   ,@v_vchItemMasterID		AS item_master_id
			   ,@in_vchItemNumber		AS item_number
			   ,@v_vchItemDesc		    AS item_description
			   ,@v_vchLotControl	    AS lot_control
			   ,@v_vchSNControl		    AS sn_control
			   ,@v_vchExpiryDateControl	AS expiry_date_control
			   ,@v_vchAttribute1Control AS attribute1_control
			   ,@v_vchAttribute2Control AS attribute2_control
			   ,@v_vchAttribute3Control AS attribute3_control
			   ,@v_vchAttribute4Control AS attribute4_control
			   ,@v_vchAttribute5Control AS attribute5_control
			   ,@v_vchPickRule			AS pick_rule
			   ,@in_vchItemStatus		AS item_status
			   ,@in_fltQuantity			AS display_default_qty
			   ,@in_fltQuantity			AS qty
			   ,@v_vchUomPrompt			AS uom_prompt
			   ,@v_fltQtyPlan			AS quantity_plan
			   ,@v_fltQtyPick			AS quantity_pick
			   ,@v_fltQtyRemainPick		AS quantity_remain_pick
		RETURN;
	
	SAVE_TRANS:
		EXEC usp_outbound_generate_user_pick_by_order @in_vchApplicationID	  = @in_vchApplicationID
													 ,@in_vchLocalID		  = @in_vchLocalID			
													 ,@in_vchDeviceID		  = @in_vchDeviceID			
													 ,@in_vchUserID			  = @in_vchUserID			
													 ,@in_vchForkLocationID	  = @in_vchForkID	
													 ,@in_vchWhMasterID		  = @in_vchWhMasterID		
													 ,@in_vchOutboundMasterID = @in_vchOutboundMasterID	
													 ,@in_vchOwnerID		  = @in_vchOwnerID			
													 ,@in_vchBoxNumber		  = @in_vchBoxNumber		
													 ,@in_vchLocationID		  = @in_vchLocationID		
													 ,@in_vchParentLPN		  = @in_vchParentLPN		
													 ,@in_vchLPN			  = @in_vchLPN				
													 ,@in_vchWhItemMasterID	  = @v_vchWhItemMasterID	
													 ,@in_vchItemStatus		  = @in_vchItemStatus		
													 ,@in_fltQuantity		  = @in_fltQuantity			
													 ,@in_vchItemUOMID		  = @v_vchItemUOMID		
													 ,@in_vchLotNumber		  = @in_vchLotNumber		
													 ,@in_vchExpiryDate		  = @in_vchExpiryDate		
													 ,@in_vchSerialNumber	  = @in_vchSerialNumber		
													 ,@in_vchAttribute1		  = @in_vchAttribute1		
													 ,@in_vchAttribute2		  = @in_vchAttribute2		
													 ,@in_vchAttribute3		  = @in_vchAttribute3		
													 ,@in_vchAttribute4		  = @in_vchAttribute4		
													 ,@in_vchAttribute5		  = @in_vchAttribute5		
													 ,@out_ErrorCode		  = @out_vchErrorCode output	
													 ,@out_ErrorMessage		  = @out_vchErrorMsg output	

		IF ISNULL(@out_vchErrorCode,'') <> '0'
			BEGIN
				SET @out_vchNextScreen = NULL
				RETURN;
			END
					
		IF @v_vchSNControl = 'FULL'
			GOTO FINAL_SCREEN;
							
		--Check Rule ว่าต้องการแสดงหน้าจอสุดท้ายแสดง message save success? ถ้า Rule = NO คือไม่แสดง
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_TRANSACTION_LOST_SCREEN' AND is_active = 'YES') = 'NO' 
			BEGIN
				GOTO FINAL_SCREEN; 
			END
		ELSE
			BEGIN
				SET @out_vchNextScreen = 'FINAL_SCREEN';
				GOTO NEXT_SCREEN;
				RETURN;
			END

	FINAL_SCREEN:
		EXEC usp_api_validate_user_pick_final_screen @in_vchApplicationID	 = @in_vchApplicationID
													,@in_vchDeviceID		 = @in_vchDeviceID
													,@in_vchUserID			 = @in_vchUserID
													,@in_vchWhMasterID		 = @in_vchWhMasterID
													,@in_vchOutboundMasterID = @in_vchOutboundMasterID
													,@in_vchLocationID		 = @in_vchLocationID
													,@in_vchWhItemMasterID	 = @v_vchWhItemMasterID
													,@in_vchSNControl		 = @v_vchSNControl
													,@in_vchLocalID			 = @in_vchLocalID
													,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
													,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
													,@out_vchNextScreen		 = @out_vchNextScreen OUTPUT
		RETURN;
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')		

END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_order_number]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_order_number]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		NVARCHAR(50) = NULL, 
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode			NVARCHAR(50)  = NULL,
			@v_vchOrderStatus		NVARCHAR(10)  = NULL

	SELECT @v_vchOutboundMasterID = obMs.outbound_order_master_id 
		,@v_vchOwnerID = obMS.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchOrderStatus = obMS.order_status
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	WHERE obMS.wh_master_id = @in_vchWhMasterID
	AND obMS.outbound_order_number = @in_vchOrderNumber
	AND obMS.pick_type = 'USER'

	--------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number ว่ามีอยู่ในระบบหรือไม่?
	--------------------------------------------------------------------
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchOrderNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	------------------------------------------------------
	--Check User Owner
	------------------------------------------------------
	IF NOT EXISTS (SELECT 1 FROM t_wms_owner_user WHERE user_id = @in_vchUserID AND owner_id = @v_vchOwnerID)
		BEGIN
			SET @out_vchErrorCode = 'USER_NOT_MAPPING_OWNER'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	------------------------------------------------------------------------------
	-- ตรวจสอบเลข Outbound Order Number : Order Status NOT IN 'OPEN','SHIP',CANCEL
	------------------------------------------------------------------------------
	IF @v_vchOrderStatus IN (SELECT value FROM dbo.t_wms_rule  WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES')
		BEGIN
			--Order Status ไม่ถูกต้อง
			SET @out_vchErrorCode = 'OUTBOUND_STATUS_CANNOT_PICK'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchOrderStatus,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
								
	------------------------------------------------------------------------------
	-- Check WH Rule is Pick and Pack
	------------------------------------------------------------------------------
	IF (SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_PICK_PACK'  AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_vchNextScreen = 'BOX_NUMBER'
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'LOCATION'
		END

	SELECT  @v_vchOwnerID	AS owner_id
		   ,@v_vchOwnerCode	AS owner_code
		   ,@v_vchOutboundMasterID AS outbound_order_master_id

	RETURN;

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_api_validate_user_pick_parent_lpn]    Script Date: 08/08/2025 11:11:29 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_api_validate_user_pick_parent_lpn]
(
	@in_vchApplicationID	VARCHAR(40)  = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLocalID			VARCHAR(40)  = NULL,
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	--------------------------------------------
	-- Check Location in Inventory Tabel
	--------------------------------------------
	IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory  WHERE wh_master_id =  @in_vchWhMasterID AND owner_id =  @in_vchOwnerID AND location_id =  @in_vchLocationID AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,''))
		BEGIN
			SET @out_vchErrorCode = 'INFO-PARENT-LPN-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	------------------------------------------------------
	-- Next Screen
	------------------------------------------------------
	SET @out_vchNextScreen = 'LPN'
	RETURN;
	
	------------------------------------------------------
	-- Exit the Process
	------------------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
END
GO
/****** Object:  StoredProcedure [dbo].[usp_blind_receipt_update_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_blind_receipt_update_qty]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER, 
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER = NULL, 
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,  
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER, 
	@in_fltQuantity			FLOAT,
	@in_vchUomPrompt		NVARCHAR(40)	= NULL,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerialNumber		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100),
	@in_vchAttribute2		NVARCHAR(100),
	@in_vchAttribute3		NVARCHAR(100),
	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100),
	@in_dtMfgDate			DATE = NULL,
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(30) = '[usp_blind_receipt_update_qty]', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(100),
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtProcessDateTime		DATETIME = GETDATE(),
			@v_dtStartTranDate			DATETIME = GETDATE(),
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,
			 
			@v_vchWarehouse				NVARCHAR(25) = NULL,
			@v_vchInboundNumber			NVARCHAR(50),
			@v_vchReceiptNumber			NVARCHAR(50),
			@v_vchReceiptStatus			NVARCHAR(25),
			@v_vchOrderStatus			NVARCHAR(25),
			@v_vchOrderType				NVARCHAR(30),
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50),
			@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,

			@v_vchInboundOrderDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber			NVARCHAR(10)= NULL,

			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50),
			@v_fltPrice					FLOAT,
			@v_vchGrade					NVARCHAR(40),
			@v_vchItemIsActive			VARCHAR(3),
			@v_vchLotControl			VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchSerialControl			VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5),
			@v_vchLocation				NVARCHAR(50)= NULL, 
			@v_vchInvStatus				NVARCHAR(50),
			@v_dtReceiveDate			DATE = GETDATE(),
			@v_vchBaseItemUomID			VARCHAR(40),
			@v_vchBaseUOM				NVARCHAR(20),			
			@v_vchBaseUomPrompt			NVARCHAR(40), 
			@v_vchInputUomPrompt		NVARCHAR(40),
			@v_vchIsPrimaryUOM			NVARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว
 			@v_fltAfterInvQuantity		FLOAT

BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		
		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR(8),CONVERT(DATE,@in_vchExpiryDate),112)

		-- Get and check warehouse
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (ISNULL(@v_vchWarehouse,'') = '')
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Get and check location
		SELECT @v_vchLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		IF (ISNULL(@v_vchLocation,'') = '')
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Get and check status
		SELECT @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID AND is_active = 'YES'
		IF (ISNULL(@v_vchInvStatus,'') = '')
			BEGIN
				SET @out_ErrorCode = 'STATUS_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInvStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		SELECT @v_vchInboundNumber = inbound_order_number 
			,@v_vchOrderStatus = order_status
			,@v_vchOrderType = order_type
			,@v_vchOwnerID = owner_id
			,@v_vchOwnerCode = owner_code 
		FROM t_wms_inbound_master 
		WHERE wh_master_id = @in_vchWhMasterID
		AND inbound_order_master_id = @in_vchInboundMasterID 

		IF (@in_vchInboundMasterID IS NULL)
		BEGIN 
			SET @out_ErrorCode = 'INFO-INBOUND-NOT-EXIST';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInvStatus,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

		---------------------------------------------
		-- CHECK ORDER STATUS
		---------------------------------------------
		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC;
			END

		--------------------------------------------------
		-- Get item_master_id
		--------------------------------------------------
		SET @v_vchItemNumber = NULL
		SELECT @v_vchItemMasterID = item.item_master_id
			, @v_vchItemNumber = item.item_number
			, @v_fltPrice = item.price
			, @v_vchGrade = item.grade
			, @v_vchLotControl = item.lot_control
			, @v_vchExpiryDateControl = item.expiry_date_control
			, @v_vchSerialControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
			, @v_vchItemIsActive = item.is_active
		FROM t_wms_item item
 		WHERE owner_id = @v_vchOwnerID
		AND item_master_id = @v_vchItemMasterID
		IF (@v_vchItemNumber IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC;
			END

		IF (@v_vchItemIsActive = 'NO')
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--Get & Check Item UOM
		SET @v_vchBaseItemUomID = NULL
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseuom = uom
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchInputUomPrompt = uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND uom_prompt = @in_vchUomPrompt
		and is_active = 'YES'

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SET @v_vchBaseItemUomID = NULL
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseuom = uom
					,@v_vchBaseUomPrompt = uom_prompt
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
		
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END 

		SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		SET @v_dtReceiveDate = CONVERT(DATE,GETDATE())
		---------------------------------------------
		--INSERT/UPDATE INBOUND DETAIL
		---------------------------------------------
		SET @v_vchInboundOrderDetailID = NULL
		SELECT @v_vchInboundOrderDetailID = inbound_order_detail_id 
		FROM t_wms_inbound_detail 
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND default_item_status = @v_vchInvStatus
			
		IF (@v_vchInboundOrderDetailID IS NULL)
			BEGIN
				DECLARE @v_intLastNumber INT = 0
					
				----------------------------------------
				-- GET Last Line number
				----------------------------------------
				SELECT @v_intLastNumber = MAX(line_number) FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID
					 
				IF(ISNULL(@v_intLastNumber,'') = '')
					BEGIN
						SET @v_intLastNumber = 0
					END
				SET	@v_vchLineNumber = RIGHT('00000'+CONVERT(VARCHAR(20),(@v_intLastNumber + 1)),6)

				SET @v_vchInboundOrderDetailID = NEWID();
				INSERT INTO [dbo].[t_wms_inbound_detail]
						([inbound_order_detail_id]
						,[inbound_order_master_id]
						,[wh_item_master_id]
						,[line_number]
						,[quantity_order]
						,[quantity_receive]
						,[item_uom_id]
						,[item_status]
						,[default_item_status]
						,[price]
						,[grade]
						,[over_receipt_allowed]
						,[over_receipt_percentage]
						,[source_of_record]
						,[create_by]
						,[create_date]
						,[item_master_id]
						,[item_number]
						,[uom])
					VALUES
						(@v_vchInboundOrderDetailID
						,@in_vchInboundMasterID
						,@in_vchWhItemMasterID
						,@v_vchLineNumber
						,@v_fltBaseInputQuantity
						,@v_fltBaseInputQuantity
						,@v_vchBaseItemUomID
						,'NEW'
						,@v_vchInvStatus
						,@v_fltPrice
						,@v_vchGrade
						,'NO'
						,NULL
						,'BLIND RECEIPT'
						,@in_vchUserID
						,GETDATE()
						,@v_vchItemMasterID
						,@v_vchItemNumber
						,@v_vchBaseUOM)
			END
		ELSE
			BEGIN
				UPDATE [dbo].[t_wms_inbound_detail]
					SET [quantity_order] = ROUND(ISNULL(quantity_order,0) + @v_fltBaseInputQuantity,@Round)
						,[quantity_receive] = ROUND(ISNULL(quantity_receive,0) + @v_fltBaseInputQuantity,@Round)
						,[item_status] = 'RECEIVING'
						,[update_by] = @in_vchUserID
						,[update_date] = GETDATE()
					WHERE inbound_order_detail_id = @v_vchInboundOrderDetailID
			END

		SELECT @in_vchReceiptHeaderID = receipt_header_id
			,@v_vchReceiptNumber = receipt_number
			,@v_vchReceiptStatus = receipt_status
		FROM t_wms_receipt_header 
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND receipt_header_id = @in_vchReceiptHeaderID
	
		---------------------------------------------
		-- CHECK RECEIPT STATUS
		---------------------------------------------
		IF (@v_vchReceiptStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_ORDER_IS_CLOSED';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		---------------------------------------------
		--INSERT RECEIPT HEADER
		---------------------------------------------
		IF (@in_vchReceiptHeaderID IS NULL)
			BEGIN
				SET @in_vchReceiptHeaderID = NEWID();
				INSERT INTO [dbo].[t_wms_receipt_header]
						([receipt_header_id]
						,[inbound_order_master_id]
						,[receipt_number]
						,[receipt_status]
						,[create_date]
						,[create_by])
					VALUES
						(@in_vchReceiptHeaderID
						,@in_vchInboundMasterID
						,@v_vchReceiptNumber
						,'OPEN'
						,GETDATE()
						,@in_vchUserID)
			END

		---------------------------------------------
		--INSERT RECEIPT DETAIL
		---------------------------------------------
		INSERT INTO [dbo].[t_wms_receipt_detail]
				([receipt_detail_id]
				,[receipt_header_id]
				,[inbound_order_detail_id]
				,[quantity_received]
				,[item_uom_id]
				,[receipt_item_status]
				,[location_received]
				,[lpn]
				,[parent_lpn]
				,[lot_number]
				,[expiry_date]
				,[serial_number]
				,[attribute1]
				,[attribute2]
				,[attribute3]
				,[attribute4]
				,[attribute5]
				,[item_number]
				,[wh_item_master_id]
				,[inbound_order_number]
				,[inbound_order_master_id]
				,[receive_date]
				,[mfg_date]
				,[create_date]
				,[create_by])
			VALUES
				(NEWID()
				,@in_vchReceiptHeaderID
				,@v_vchInboundOrderDetailID
				,@v_fltBaseInputQuantity
				,@v_vchBaseItemUomID
				,@v_vchInvStatus
				,@v_vchLocation
				,(CASE ISNULL(@in_vchLPN,'') WHEN '' THEN NULL ELSE @in_vchLPN END)	
				,(CASE ISNULL(@in_vchParentLPN,'') WHEN '' THEN NULL ELSE @in_vchParentLPN END)
				,(CASE ISNULL(@in_vchLotNumber,'') WHEN '' THEN NULL ELSE @in_vchLotNumber END)
				,(CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
				,(CASE ISNULL(@in_vchSerialNumber,'') WHEN '' THEN NULL ELSE @in_vchSerialNumber END)
				,(CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END)
				,(CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END)
				,(CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END)
				,(CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END)
				,(CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END)
				,@v_vchItemNumber
				,@in_vchWhItemMasterID
				,@v_vchInboundNumber
				,@in_vchInboundMasterID
				,@v_dtReceiveDate
				,@in_dtMfgDate
				,GETDATE()
				,@in_vchUserID)
			
		---------------------------------------------
		--Manage Inventory
		---------------------------------------------
		EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
									,@in_vchWhMasterID			= @in_vchWhMasterID
									,@in_vchWhID				= @v_vchWarehouse
									,@in_vchOwnerID				= @v_vchOwnerID
									,@in_vchInventoryType		= 'INVENTORY'
									,@in_vchLocationID			= @in_vchLocationID
									,@in_vchParentLPN			= @in_vchParentLPN
									,@in_vchLPN					= @in_vchLPN
									,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
									,@in_vchItemMasterID		= @v_vchItemMasterID
									,@in_vchItemNumber			= @v_vchItemNumber
									,@in_fltQuantity			= @v_fltBaseInputQuantity
									,@in_fltQtyAllocate			= 0
									,@in_fltQtyIncoming			= 0
									,@in_vchPrimaryItemUomID	= @v_vchBaseItemUomID
									,@in_vchInvStatusID			= @in_vchInvStatusID
									,@in_vchLotNumber			= @in_vchLotNumber
									,@in_vchExpiryDate			= @in_vchExpiryDate
									,@in_vchSerialNumber		= @in_vchSerialNumber
									,@in_vchAttribute1			= @in_vchAttribute1
									,@in_vchAttribute2			= @in_vchAttribute2
									,@in_vchAttribute3			= @in_vchAttribute3
									,@in_vchAttribute4			= @in_vchAttribute4
									,@in_vchAttribute5			= @in_vchAttribute5
									,@in_dReceiveDate			= @v_dtReceiveDate
									,@in_dtMFGDate				= @in_dtMfgDate
									,@in_vchDeviceID			= @in_vchDeviceID
									,@in_vchUserID				= @in_vchUserID
									,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
									,@out_ErrorCode				= @out_ErrorCode OUTPUT
									,@out_ErrorMessage			= @out_ErrorMessage OUTPUT
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		---------------------------------------------
		--WRITE TRANSACTION LOG
		---------------------------------------------
		INSERT INTO t_com_tran_log
				(app_id
				, tran_type
				, sub_tran_type
				, [app_name]
				, [description]
				, start_tran_datetime
				, end_tran_datetime
				, to_warehouse
				, to_location
				, to_owner
				, item_number
				, quantity
				, quantity_uom
				, after_quantity
				, after_quantity_uom
				, after_lot_number
				, after_expiry_date
				, serial_number
				, [user_id] 
				, after_parent_lpn
				, after_lpn
				, after_status
				, order_number
				, line_number

				-- Add for attibute
				, [after_attribute1]
				, [after_attribute2]
				, [after_attribute3]
				, [after_attribute4]
				, [after_attribute5] 
				, receive_date
				, mfg_date
				, input_quantity
				, input_uom
				, device
				, create_by)
			VALUES
				( @in_vchApplicationID
				, 'BLIND_RECEIPT'
				, 'RECEIPT'
				, @v_vchApplicationName
				, 'Blind Receive Item'
				, @v_dtStartTranDate
				, GETDATE()
				, @v_vchWarehouse
				, @v_vchLocation
				, @v_vchOwnerCode
				, @v_vchItemNumber
				, @v_fltBaseInputQuantity
				, @v_vchBaseUomPrompt
				, @v_fltAfterInvQuantity
				, @v_vchBaseUomPrompt
				, @in_vchLotNumber
				, @in_vchExpiryDate
				, @in_vchSerialNumber
				, @in_vchUserID
				, @in_vchParentLPN
				, @in_vchLPN
				, @V_vchInvStatus
				, @v_vchInboundNumber
				, @v_vchLineNumber

				-- Add for attibute
				, @in_vchAttribute1
				, @in_vchAttribute2
				, @in_vchAttribute3
				, @in_vchAttribute4
				, @in_vchAttribute5
				, @v_dtReceiveDate
				, @in_dtMfgDate
				, @in_fltQuantity		   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
				, @v_vchInputUomPrompt	   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
				, @in_vchDeviceID
				, @in_vchUserID)

		-- Update Master Order Status 
		UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE wh_master_id = @in_vchWhMasterID and inbound_order_master_id = @in_vchInboundMasterID
		
		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess		= 'IN'
										  ,@in_vchTransType		= 'RECEIVING'
										  ,@in_vchWhMasterID	= @in_vchWhMasterID
										  ,@in_vchOwnerID		= @v_vchOwnerID
										  ,@in_vchOwnerCode		= @v_vchOwnerCode
										  ,@in_vchLocationID	= @in_vchLocationID
										  ,@in_vchItemMasterID	= @v_vchItemMasterID
										  ,@in_vchInvStatusID	= @in_vchInvStatusID
										  ,@in_vchToWhMasterID	= NULL
										  ,@in_vchToLocationID	= NULL
										  ,@in_vchToInvStatusID = NULL
										  ,@in_fltQuantity		= @v_fltBaseInputQuantity
										  ,@in_vchUserID		= @in_vchUserID
		
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;
	------------------------------------------------
	--WRITE PROCESS LOG
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
	------------------------------------------------
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			
			SET @v_dtProcessDateTime = GETDATE();
			SET @v_vchProcessData1 = 'Receipt Number ' + @v_vchReceiptNumber;
			SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
		ROLLBACK TRANSACTION;
			
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData1 = 'Receipt Number ' + @v_vchReceiptNumber;	
	SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
		
	EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchInboundNumber,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
