/****** Object:  StoredProcedure [dbo].[usp_clear_inprocess_status]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_clear_inprocess_status]
AS
BEGIN
	SELECT host_shipment_id
	INTO #tHostShip
	FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'IN PROCESS' AND GETDATE() > DATEADD(MINUTE,30,create_date)
	UPDATE t_host_wms_ship_conf_detail_export SET processing_status = 'PENDING' WHERE host_shipment_id IN (SELECT host_shipment_id FROM #tHostShip)
	UPDATE t_host_wms_ship_conf_header_export SET processing_status = 'PENDING' WHERE host_shipment_id IN (SELECT host_shipment_id FROM #tHostShip)
	DROP TABLE #tHostShip


	SELECT receipt_id
	INTO #tHostReceipt
	FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'IN PROCESS' AND GETDATE() > DATEADD(MINUTE,30,create_date)
	UPDATE t_host_wms_receipt_conf_detail_export SET processing_status = 'PENDING' WHERE receipt_id IN (SELECT receipt_id FROM #tHostReceipt)
	UPDATE t_host_wms_receipt_conf_header_export SET processing_status = 'PENDING' WHERE receipt_id IN (SELECT receipt_id FROM #tHostReceipt)
	DROP TABLE #tHostReceipt

	UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id IN (SELECT host_record_id FROM t_host_wms_trans_export WHERE processing_status = 'IN PROCESS' AND GETDATE() > DATEADD(MINUTE,30,create_date))
END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_count_plan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_count_plan]
(
	@in_vchApplicationID		NVARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchCountPlanID			NVARCHAR(50),
	@in_vchCloseDate			DATETIME ,
	@in_vchCloseBy				NVARCHAR(25),
	@in_vchCloseRemark			NVARCHAR(200)= NULL,
	@in_vchDeviceID				NVARCHAR(50) = NULL,
	@in_vchUserID				NVARCHAR(25) = NULL,
	@out_ErrorCode				NVARCHAR(50) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @v_vchCountMasterID		 VARCHAR(40),
			@v_vchWhMasterID		 VARCHAR(40),
			@v_vchBeginTrans		 BIT,
			
			--Write Log
			@c_vchObjName			nvarchar(50) = 'usp_close_count_plan',
			@v_dtProcessDateTime	DATETIME,
			@v_vchData1				NVARCHAR(1000),
			@v_vchData2				NVARCHAR(1000),

			--For missing
			@v_vchMissCountPlanDetailID VARCHAR(40),
			@v_vchMissLocation			NVARCHAR(50),
			@v_vchMissSerialNumber		NVARCHAR(100)
	
	BEGIN TRY
	BEGIN TRANSACTION
		SET @v_vchBeginTrans = 1;
	
		--Get Warehouse Master ID
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		
		--Get Count MasterID
		SELECT @v_vchCountMasterID = count_master_id FROM t_wms_count_plan_master
		WHERE wh_master_id = @v_vchWhMasterID
		AND count_id = @in_vchCountPlanID

		IF ISNULL(@v_vchCountMasterID,'') = ''
			BEGIN
				SET @out_ErrorCode = 'INFO-COUNT-ID-NOT-FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END
		
		---------------------------------------------
		--Update Status close
		---------------------------------------------
		UPDATE t_wms_count_plan_master
		SET count_status ='CLOSE'
			,close_date	  = @in_vchCloseDate
			,close_by	  = @in_vchCloseBy
			,close_remark = @in_vchCloseRemark
		WHERE count_master_id = @v_vchCountMasterID
		
		COMMIT TRANSACTION;	
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')


-------------------------------------------------------------------------------------------------
--WRITE PROCESS LOG
	WRITE_PROCESSLOG:
-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
			
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchData1 = @out_ErrorMessage;
		SET @v_vchData2 = 'Count ID [' + @in_vchCountPlanID + ']';

		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
-------------------------------------------------------------------------------------------------

	END TRY

	BEGIN CATCH
					
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
		
		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
			
		SET @v_vchData1 = ERROR_PROCEDURE() + ': ' + @out_ErrorMessage 
					+ '. SQL Error ['+ str(ERROR_NUMBER()) + '], '
					+ '. Severity ['+ str(ERROR_SEVERITY()) + '],'
					+ '. State ['+ str(ERROR_STATE()) + '],'
					+ '. Line ['+ str(ERROR_LINE()) + '].'
							
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchData2 = 'Count ID [' + @in_vchCountPlanID + ']';
		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END CATCH
END



GO
