/****** Object:  StoredProcedure [dbo].[usp_close_inbound_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_inbound_order]
(
	@in_vchApplicationID		VARCHAR(40),	
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchInboundMasterID		UNIQUEIDENTIFIER, 
	@in_vchCloseRemark			NVARCHAR(200),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@out_ErrorCode				VARCHAR(50) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchApplicationName	NVARCHAR(100)
	DECLARE @v_vchBeginTrans		BIT = 0
	DECLARE @v_vchReceiptHeaderID	UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOrderType			NVARCHAR(30)
	DECLARE @v_vchHostRecordID		NVARCHAR(50)
	DECLARE @v_vchInboundNumber		NVARCHAR(50)
	DECLARE @v_vchTranType			NVARCHAR(20)
	DECLARE @v_vchSubTranType		NVARCHAR(20)
	DECLARE @v_dtCloseDate			DATETIME = GETDATE()
	
	IF ISNULL(@in_vchCloseRemark,'') = ''
		SET @in_vchCloseRemark = 'Close Inbound Order'
	
	SELECT @v_vchWarehouse = wh_id
		, @v_vchOrderType = order_type
		,@v_vchInboundNumber = inbound_order_number 
	FROM t_wms_inbound_master WITH (NOLOCK)
	WHERE inbound_order_master_id = @in_vchInboundMasterID

	IF (@v_vchOrderType IN (SELECT TOP 1 value from t_wms_rule WHERE rule_code = 'BLIND_RECEIPT_ORDER_TYPE' AND is_active = 'YES'))
	   	BEGIN
			SET @v_vchTranType = 'BLIND_RECEIPT'	
		END
	ELSE
		BEGIN
			SET @v_vchTranType = 'IO_RECEIPT'	
		END

	IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_INBOUND_ORDER_TYPE_FOR_INTERFACE' and is_active = 'YES'))
		BEGIN
			SET @v_vchSubTranType = 'CLOSE_IO_ORDER_ERP'
		END
	ELSE
		BEGIN
			SET @v_vchSubTranType = 'CLOSE_IO_ORDER'
		END

BEGIN TRY
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_CLOSE_RECEIPT' AND is_active = 'YES') = 'YES')
			BEGIN
				NEXT_RECEIPT:
					SET @v_vchReceiptHeaderID = NULL
					SELECT TOP 1 @v_vchReceiptHeaderID = receipt_header_id 
					FROM t_wms_receipt_header WITH (NOLOCK)
					WHERE inbound_order_master_id = @in_vchInboundMasterID 
					AND receipt_status = 'OPEN'
					IF @v_vchReceiptHeaderID IS NOT NULL
						BEGIN
							EXEC usp_close_partial_receive @in_vchApplicationID		= @in_vchApplicationID
														 , @in_vchDevice			= @in_vchDeviceID
														 , @in_vchWhMasterID		= @in_vchWhMasterID
														 , @in_vchInboundMasterID	= @in_vchInboundMasterID
														 , @in_vchReceiptHeaderID	= @v_vchReceiptHeaderID
														 , @in_vchCloseBy			= @in_vchUserID
														 , @out_ErrorCode			= @out_ErrorCode  OUTPUT
														 , @out_ErrorMessage		= @out_ErrorMessage OUTPUT

							IF @out_ErrorCode <> '0'  
								RETURN; 
						END

					IF EXISTS (SELECT receipt_header_id FROM t_wms_receipt_header WHERE inbound_order_master_id = @in_vchInboundMasterID AND receipt_status = 'OPEN')
						BEGIN
							GOTO NEXT_RECEIPT;
						END
			END
		ELSE
			BEGIN
				--------------------------------------------------------------
				-- ต้อง Close All Partial Receipt Number ถึงจะ Close Order ได้
				--------------------------------------------------------------
				IF EXISTS (SELECT receipt_header_id FROM t_wms_receipt_header WHERE inbound_order_master_id = @in_vchInboundMasterID AND receipt_status <> 'CLOSE')
					BEGIN
						SET @out_ErrorCode = 'INFO-PARTIAL-RECEIPT-STATUS-NOT-CLOSE'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')			
						RETURN;
					END
			END
		
	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;

		UPDATE t_wms_inbound_master SET
			order_status = 'CLOSE',
			close_date = @v_dtCloseDate,
			close_by = @in_vchUserID,
			close_remark = @in_vchCloseRemark
		WHERE inbound_order_master_id = @in_vchInboundMasterID 
		
		-----------------------------------------------------------
		-- Write Transaction Log Close inbound order
		-----------------------------------------------------------
		INSERT INTO t_com_tran_log
			(app_id
			, [app_name]
			, tran_type
			, sub_tran_type 
			, [description]
			, start_tran_datetime
			, end_tran_datetime
			, to_warehouse
			, to_location
			, to_owner
			, item_number
			, quantity
			, quantity_uom
			, after_quantity
			, after_quantity_uom
			, after_lot_number
			, after_expiry_date
			, serial_number
			, [user_id] 
			, after_parent_lpn
			, after_lpn
			, after_status
			, order_number
			, line_number

			-- Add for attibute
			, [after_attribute1]
			, [after_attribute2]
			, [after_attribute3]
			, [after_attribute4]
			, [after_attribute5]
			, control_number
			, receive_date
			, mfg_date
			, input_quantity
			, input_uom
			, device
			, create_by)
		SELECT @in_vchApplicationID
			, @v_vchApplicationName
			, @v_vchTranType
			, @v_vchSubTranType 
			, 'Close Inbound Order'
			, GETDATE()
			, GETDATE()
			, ibMS.wh_id
			, recDT.location_received
			, ibMS.owner_code
			, ibDT.item_number
			, recDT.quantity_received
			, uom.uom
			, recDT.quantity_received
			, uom.uom
			, recDT.lot_number
			, CASE WHEN ISNULL(recDT.expiry_date,'') = '' THEN NULL ELSE CONVERT(NVARCHAR,recDT.expiry_date,112) END
			, recDT.serial_number
			, @in_vchUserID
			, recDT.parent_lpn
			, recDT.lpn
			, recDT.receipt_item_status
			, ibMS.inbound_order_number
			, ibDT.line_number

			-- Add for attibute
			, recDT.attribute1
			, recDT.attribute2
			, recDT.attribute3
			, recDT.attribute4
			, recDT.attribute5
			, recHD.receipt_number
			, recDT.receive_date
			, recDT.mfg_date
			, quantity_receive				--Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
			, uom.uom_prompt				--Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
			, @in_vchDeviceID
			, @in_vchUserID
		FROM t_wms_inbound_master ibMS
		INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
		INNER JOIN t_wms_receipt_header recHD ON ibMS.inbound_order_master_id = recHD.inbound_order_master_id
		INNER JOIN t_wms_receipt_detail recDT ON recHD.receipt_header_id = recDT.receipt_header_id AND recDT.inbound_order_detail_id = ibDT.inbound_order_detail_id
		INNER JOIN t_wms_item_uom uom ON ibDT.item_uom_id = uom.item_uom_id
		WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID

		--Check TranType and Sub Tran Type for Interface Data
		IF ((SELECT host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
			BEGIN
				EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT
				
				IF NOT EXISTS(SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE receipt_id = @v_vchHostRecordID)
				BEGIN
					INSERT INTO [dbo].[t_host_wms_receipt_conf_header_export]
						   ([receipt_id]
						   ,[processing_status]
						   ,[wh_id]
						   ,[owner_id]
						   ,[order_type]
						   ,[supplier_code]
						   ,[inbound_order_number]
						   ,[reference_number]
						   ,[close_date]
						   ,[order_status]
						   ,[user_def1]
						   ,[user_def2]
						   ,[user_def3]
						   ,[user_def4]
						   ,[user_def5]
						   ,[user_def6]
						   ,[user_def7]
						   ,[user_def8]
						   ,[user_def9]
						   ,[user_def10]
						   ,[create_by]
						   ,[create_date])
					 SELECT @v_vchHostRecordID
						   ,'PENDING'
						   ,ibMS.wh_id
						   ,ibMS.owner_code
						   ,ibMS.order_type
						   ,(CASE WHEN ISNULL(supp.supplier_code,'') = '' THEN cust.customer_code ELSE supp.supplier_code END)
						   ,ibMS.inbound_order_number
						   ,ibMS.reference_number
						   ,@v_dtCloseDate
						   ,ibMS.order_status
						   ,ibMS.user_def1
						   ,ibMS.user_def2
						   ,ibMS.user_def3
						   ,ibMS.user_def4
						   ,ibMS.user_def5
						   ,ibMS.user_def6
						   ,ibMS.user_def7
						   ,ibMS.user_def8
						   ,ibMS.user_def9
						   ,ibMS.user_def10
						   ,@in_vchUserID
						   ,GETDATE()
						FROM t_wms_inbound_master ibMS
						LEFT JOIN t_wms_supplier supp ON ibMS.supplier_id = supp.supplier_id
						LEFT JOIN t_wms_customer cust ON ibMS.customer_id = cust.customer_id
						WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID
				END

				INSERT INTO [dbo].[t_host_wms_receipt_conf_detail_export]
					   ([receipt_detail_id]
					   ,[receipt_id]
					   ,[processing_status]
					   ,[wh_id]
					   ,[owner_id]
					   ,[inbound_order_number]
					   ,[line_number]
					   ,[item_number]
					   ,[lot_number]
					   ,[expiry_date]
					   ,[serial_number]
					   ,[uom]
					   ,[qty_received]
					   ,[receipt_item_status]
					   ,[receipt_date]
					   ,[lpn]
					   ,[parent_lpn]
					   ,[location]
					   ,[user_def1]
					   ,[user_def2]
					   ,[user_def3]
					   ,[user_def4]
					   ,[user_def5]
					   ,[user_def6]
					   ,[user_def7]
					   ,[user_def8]
					   ,[user_def9]
					   ,[user_def10]
					   ,[attribute1]
					   ,[attribute2]
					   ,[attribute3]
					   ,[attribute4]
					   ,[attribute5]
					   ,[create_by])
				SELECT NEWID()
					,@v_vchHostRecordID
					,'PENDING'
					,ibMS.wh_id
					,ibMS.owner_code
					,ibMS.inbound_order_number
					,ibDT.line_number
					,ibDT.item_number
					,recDT.lot_number
					,CASE WHEN ISNULL(recDT.expiry_date,'') = '' THEN NULL ELSE CONVERT(NVARCHAR,recDT.expiry_date,112) END
					,recDT.serial_number
					,ibDT.uom
					,0
					,recDT.receipt_item_status
					,ibMS.posting_date
					,recDT.lpn
					,recDT.parent_lpn
					,recDT.location_received
					,ibDT.user_def1
					,ibDT.user_def2
					,ibDT.user_def3
					,ibDT.user_def4
					,ibDT.user_def5
					,ibDT.user_def6
					,ibDT.user_def7
					,ibDT.user_def8
					,ibDT.user_def9
					,ibDT.user_def10
					,recDT.attribute1
					,recDT.attribute2
					,recDT.attribute3
					,recDT.attribute4
					,recDT.attribute5
					,@in_vchUserID
				FROM t_wms_inbound_master ibMS
				INNER JOIN t_wms_inbound_detail ibDT ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
				INNER JOIN t_wms_receipt_header recHD ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
				INNER JOIN t_wms_receipt_detail recDT ON recHD.receipt_header_id = recDT.receipt_header_id AND recDT.inbound_order_detail_id = ibDT.inbound_order_detail_id
				WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID
			END
		
	COMMIT TRANSACTION;

	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')			
	RETURN;

END TRY
BEGIN CATCH 
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();

	DECLARE @v_dtProcessDateTime DATETIME = GETDATE(); 
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = 'UNALLOCATE',
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = 'usp_close_inbound_order',
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchInboundNumber,
		@in_vchData2 = NULL,
		@in_vchData3 = @out_ErrorCode,
		@in_vchData4 = @out_ErrorMessage,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
			
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_outbound_consignment]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_outbound_consignment]
(
	@in_vchApplicationID		VARCHAR(40),  
	@in_vchWhMasterID			VARCHAR(40), 
	@in_vchWarehouse			NVARCHAR(25),  
	@in_vchOrderNumber			NVARCHAR(50),
	@in_vchDeviceID				NVARCHAR(50),  
	@in_vchUserID				NVARCHAR(25),
	@in_vchRemark				NVARCHAR(500),
	@in_dateCloseDate			DATETIME,
	@out_ErrorCode				NVARCHAR(200) OUTPUT,  
	@out_ErrorMessage			NVARCHAR(500) OUTPUT  
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
		-- Error handling variables
		@c_vchObjName					NVARCHAR(30) = '[usp_close_outbound_consignment]', -- The name that uniquely tags this object.
		@v_vchApplicationName			NVARCHAR(100),
		@v_vchMessage					NVARCHAR(500)= NULL,
		@v_vchProcessData1				NVARCHAR(1000),
		@v_vchProcessData2				NVARCHAR(1000),
		@v_vchProcessData3				NVARCHAR(1000),
		@v_vchProcessData4				NVARCHAR(1000),
		@v_dtProcessDate				DATETIME,
		@v_dtStartTranDate				DATETIME,
		@v_dtEndTranDate				DATETIME,
		@v_vchTranType					NVARCHAR(50),
		@v_vchSubTranType				NVARCHAR(50),
		@v_vchHostInterfaceID			NVARCHAR(50),
		@v_vchBeginTrans				BIT = 0,
		@Round							INT,

		@v_vchOutboundConsignmentMasterID	VARCHAR(40)  = NULL,
		@v_vchOrderType					NVARCHAR(50) = NULL,
		@v_vchOrderStatus				NVARCHAR(25) = NULL,
		@v_vchOwnerID                   VARCHAR(40), 
		@v_vchOwnerCode                 NVARCHAR(50),
		@v_vchCustomerID				VARCHAR(40)  = NULL,
		@v_vchCustomerCode              NVARCHAR(50),
		@v_vchCustomerName				NVARCHAR(200),
		@v_vchHUDF1						NVARCHAR(50),
		@v_vchHUDF2						NVARCHAR(50),
		@v_vchHUDF3						NVARCHAR(50),
		@v_vchHUDF4						NVARCHAR(50),
		@v_vchHUDF5						NVARCHAR(50),
		@v_vchHUDF6						NVARCHAR(50),
		@v_fltHUDF7						FLOAT,
		@v_fltHUDF8						FLOAT,
		@v_dtpHUDF9						DATETIME,
		@v_dtpHUDF10		            DATETIME,
		@v_dtShipDateActual             DATETIME,
		
		--Detail
		@v_vchOutboundConsignmentDetailID	VARCHAR(40)  = NULL,
		@v_vchShipLocationID            VARCHAR(40),
		@v_vchShipLocation              NVARCHAR(50),
		@v_vchLineNumber				NVARCHAR(10),
		@v_vchItemNumber                NVARCHAR(50),
		@v_vchUOM                       NVARCHAR(10),
		@v_fltQty                       FLOAT,
		@v_fltQuantityOrder				FLOAT,
		@v_vchSerial                    NVARCHAR(50),
		@v_vchLotNumber                 NVARCHAR(50),
		@v_dtExpiryDate                 DATETIME,
		@v_vchExpiryDate				NVARCHAR(50),
		@v_vchAttribute1                NVARCHAR(100),
		@v_vchAttribute2	            NVARCHAR(100),
		@v_vchAttribute3	            NVARCHAR(100),
		@v_vchAttribute4	            NVARCHAR(100),
		@v_vchAttribute5	            NVARCHAR(100),
		@v_vchDefaultItemStatus         NVARCHAR(50),
		@v_vchLotControl				NVARCHAR(10),
	    @v_vchExpiryDateControl			NVARCHAR(10),
	    @v_vchSerialControl				NVARCHAR(10),
	    @v_vchAttribute1Control			NVARCHAR(10),
	    @v_vchAttribute2Control			NVARCHAR(10),
	    @v_vchAttribute3Control			NVARCHAR(10),
	    @v_vchAttribute4Control			NVARCHAR(10),
	    @v_vchAttribute5Control			NVARCHAR(10),
		@v_vchDUDF1						NVARCHAR(50),
		@v_vchDUDF2						NVARCHAR(50),
		@v_vchDUDF3						NVARCHAR(50),
		@v_vchDUDF4						NVARCHAR(50),
		@v_vchDUDF5						NVARCHAR(50),
		@v_vchDUDF6						NVARCHAR(50),
		@v_fltDUDF7						FLOAT,
		@v_fltDUDF8						FLOAT,
		@v_dtpDUDF9						DATETIME,
		@v_dtpDUDF10		            DATETIME

	BEGIN TRY
		SELECT @v_vchOutboundConsignmentMasterID = obMS.outbound_consignment_master_id
			, @v_vchOrderStatus = obMS.order_status
			, @v_vchOrderType = obMS.order_type	                                             
			, @v_vchOrderType = obMS.order_type
			, @v_vchOrderStatus = obMS.order_status
			, @v_vchOwnerID = obMS.owner_id
			, @v_vchOwnerCode = own.owner_code
			, @v_vchCustomerID = obMS.customer_id
			, @v_vchCustomerCode = obMS.customer_code
			, @v_vchCustomerName = obMS.customer_name
			, @v_vchHUDF1 = obMS.user_def1
			, @v_vchHUDF2 = obMS.user_def2
			, @v_vchHUDF3 = obMS.user_def3
			, @v_vchHUDF4 = obMS.user_def4
			, @v_vchHUDF5 = obMS.user_def5
			, @v_vchHUDF6 = obMS.user_def6
			, @v_fltHUDF7 = obMS.user_def7
			, @v_fltHUDF8 = obMS.user_def8
			, @v_dtpHUDF9 = obMS.user_def9
			, @v_dtpHUDF10 = obMS.user_def10
			, @v_dtShipDateActual   = obMS.ship_date_actual
		FROM t_wms_outbound_consignment_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		WHERE obMS.wh_master_id = @in_vchWhMasterID 
		AND obMS.outbound_order_number = @in_vchOrderNumber

		IF(ISNULL(@v_vchOutboundConsignmentMasterID,'') = '')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF(@v_vchOrderStatus <> 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_NOT_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;

			UPDATE t_wms_outbound_consignment_master SET 
				order_status = 'CLOSE'
				,close_by=@in_vchUserID
				,close_date = @in_dateCloseDate
				,close_remark = @in_vchRemark
				,update_by = @in_vchUserID
				,update_date = GETDATE()
			WHERE outbound_consignment_master_id = @v_vchOutboundConsignmentMasterID

			DECLARE CloseConsingmentCURSOR CURSOR FOR
				SELECT conDT.outbound_consignment_detail_id
				    ,conDT.line_number
				    ,conDT.ship_location_id
				    ,conDT.ship_location
				    ,conDT.item_number
				    ,conDT.default_item_status
					,conDT.quantity_order
				    ,ISNULL(conDT.quantity_order,0) - ISNULL(conDT.quantity_ship,0)
				    ,uom.uom
				    ,conDT.lot_number
				    ,conDT.[expiry_date]
				    ,conDT.serial_number
				    ,conDT.attribute1
				    ,conDT.attribute2
				    ,conDT.attribute3
				    ,conDT.attribute4
				    ,conDT.attribute5				   
				    ,item.lot_control
				    ,item.expiry_date_control
				    ,item.sn_control
				    ,item.attribute1_control
				    ,item.attribute2_control
				    ,item.attribute3_control
				    ,item.attribute4_control
				    ,item.attribute5_control
					,conDT.user_def1
					,conDT.user_def2
					,conDT.user_def3
					,conDT.user_def4
					,conDT.user_def5
					,conDT.user_def6
					,conDT.user_def7
					,conDT.user_def8
					,conDT.user_def9
					,conDT.user_def10
				FROM t_wms_outbound_consignment_detail conDT
				INNER JOIN t_wms_item item ON conDT.item_master_id = item.item_master_id
				INNER JOIN t_wms_item_uom uom ON conDT.item_uom_id = uom.item_uom_id
				WHERE outbound_consignment_master_id = @v_vchOutboundConsignmentMasterID
				AND ISNULL(quantity_ship,0) > 0
			OPEN  CloseConsingmentCURSOR
			FETCH NEXT FROM CloseConsingmentCURSOR INTO @v_vchOutboundConsignmentDetailID,@v_vchLineNumber,@v_vchShipLocationID,@v_vchShipLocation,@v_vchItemNumber,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQty,@v_vchUOM					
																,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerial,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
																,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control
																,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10
			EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT

			WHILE @@FETCH_STATUS = 0			
				BEGIN
					SET @v_vchMessage = 'Close order [' + @in_vchOrderNumber + '] [' + @in_vchDeviceID + '] success.';
					EXEC usp_get_application_name @in_vchApplicationID, @v_vchApplicationName output
					SET @v_dtEndTranDate = GETDATE();                        	
						
					IF ISNULL(@v_vchExpiryDate,'') <> ''
						SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate);
					ELSE
						SET @v_dtExpiryDate = NULL
								   
					EXEC usp_LogManager
							 @in_vchApplicationID = @in_vchApplicationID
							,@in_vchAppName = @v_vchApplicationName
							,@in_vchWhID = @in_vchWarehouse
							,@in_vchToWhID = @in_vchWarehouse
							,@in_vchDevice = @in_vchDeviceID
							,@in_vchUserID = @in_vchUserID
							,@in_vchLogType = 'TRANSACTION'
							,@in_vchTranType = @v_vchTranType
							,@in_vchDescription = 'Close Outbound Consignment Order'
							,@in_vchSubTranType = @v_vchSubTranType
							,@in_dtStartTranDate = @v_dtStartTranDate
							,@in_dtEndTranDate = @v_dtEndTranDate
							,@in_vchOwner = @v_vchOwnerCode
							,@in_vchToOwner = NULL
							,@in_vchLocation = @v_vchShipLocation
							,@in_vchToLocation = NULL
							,@in_vchItemNumber = @v_vchItemNumber
							,@in_vchUOM = @v_vchUOM
							,@in_vchBaseUOM = @v_vchUOM
							,@in_fltQuantity = @v_fltQty
							,@in_vchSerialNumber = @v_vchSerial
							,@in_fltAfterQuantity = 0
							,@in_vchAfterUOM = @v_vchUOM
							,@in_vchLotNumber = @v_vchLotNumber
							,@in_vchAfterLotNumber = NULL
							,@in_dtExpiryDate = @v_dtExpiryDate
							,@in_dtAfterExpiryDate = NULL
							,@in_vchAttribute1		= @v_vchAttribute1
							,@in_vchAfterAttribute1	= NULL
							,@in_vchAttribute2		= @v_vchAttribute2
							,@in_vchAfterAttribute2	= NULL
							,@in_vchAttribute3		= @v_vchAttribute3
							,@in_vchAfterAttribute3	= NULL
							,@in_vchAttribute4		= @v_vchAttribute4
							,@in_vchAfterAttribute4	= NULL
							,@in_vchAttribute5		= @v_vchAttribute5
							,@in_vchAfterAttribute5	= NULL
							,@in_vchLPN = NULL
							,@in_vchAfterLPN = NULL
							,@in_vchStatus = @v_vchDefaultItemStatus
							,@in_vchAfterStatus = NULL
							,@in_vchReasonCode = NULL
							,@in_vchReferenceNumber = NULL
							,@in_vchOrderNumber = @in_vchOrderNumber
							,@in_vchOrderStatus = 'CLOSE'
							,@in_vchControlNumber = @v_vchHostInterfaceID
							,@in_vchLineNumber = @v_vchLineNumber
							,@in_vchOrderQuantity = @v_fltQuantityOrder
							,@in_vchShortQuantity = 0
							,@in_vchProcess = @c_vchObjName
							,@in_dtProcessDateTime = @v_dtStartTranDate
							,@in_vchData1 = @v_vchOrderType
							,@in_vchHUDF1 = @v_vchHUDF1
							,@in_vchHUDF2 = @v_vchOrderType
							,@in_vchHUDF3 = @v_vchHUDF3
							,@in_vchHUDF4 = @v_vchHUDF4
							,@in_vchHUDF5 = @v_vchHUDF5
							,@in_vchHUDF6 = @v_vchHUDF6
							,@in_fltHUDF7 = @v_fltHUDF7
							,@in_fltHUDF8 = @v_fltHUDF8
							,@in_dtpHUDF9 = @v_dtpHUDF9
							,@in_dtpHUDF10 = @v_dtpHUDF10
							,@in_vchDUDF1 = @v_vchShipLocation
							,@in_vchDUDF2 = @v_vchDUDF2
							,@in_vchDUDF3 = @v_vchDUDF3
							,@in_vchDUDF4 = @v_vchDUDF4
							,@in_vchDUDF5 = @v_vchDUDF5
							,@in_vchDUDF6 = @v_vchDUDF6
							,@in_fltDUDF7 = @v_fltDUDF7
							,@in_fltDUDF8 = @v_fltDUDF8
							,@in_dtpDUDF9 = @v_dtpDUDF9
							,@in_dtpDUDF10 = @v_dtpDUDF10
							,@in_vchHostRecordID = @v_vchHostInterfaceID
							,@in_vchCustomerCode = @v_vchCustomerCode
							,@in_dtShipDateActual = @v_dtShipDateActual
							,@in_vchErrorCode = @out_ErrorCode OUTPUT
							,@in_vchMessage	= @out_ErrorMessage OUTPUT

					FETCH NEXT FROM CloseConsingmentCURSOR INTO  @v_vchOutboundConsignmentDetailID,@v_vchLineNumber,@v_vchShipLocationID,@v_vchShipLocation,@v_vchItemNumber,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQty,@v_vchUOM					
																,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerial,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
																,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control
																,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10
				END
			CLOSE CloseConsingmentCURSOR
			DEALLOCATE CloseConsingmentCURSOR

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
		RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			SET @v_dtProcessDate = GETDATE();
			IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			IF CURSOR_STATUS('global','CloseConsingmentCURSOR')>=-1
				BEGIN
					CLOSE CloseConsingmentCURSOR;
					DEALLOCATE CloseConsingmentCURSOR;
				END
			
			SET @v_vchProcessData1 = @out_ErrorMessage;
			SET @v_vchProcessData2 = 'Outbound Consignment :['+ @in_vchOrderNumber +']'
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDate,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @in_vchOrderNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
		END
	END TRY
	BEGIN CATCH
		SET @v_dtProcessDate = GETDATE();
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','CloseConsingmentCURSOR')>=-1
			BEGIN
				CLOSE CloseConsingmentCURSOR;
				DEALLOCATE CloseConsingmentCURSOR;
			END
		
		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
				SET @v_vchProcessData1 = 'Outbound Consignment :['+ @in_vchOrderNumber +']'
			END

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDate,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @in_vchOrderNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_outbound_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_outbound_order]
(
	@in_vchApplicationID		VARCHAR(40),  
	@in_vchWarehouse			NVARCHAR(25),  
	@in_vchDeviceID				NVARCHAR(50),  
	@in_vchUserID				NVARCHAR(25),  
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchRemark				NVARCHAR(500),
	@in_dtCloseDate				DATETIME,
	@out_ErrorCode				NVARCHAR(50) OUTPUT,  
	@out_ErrorMessage			NVARCHAR(500) OUTPUT  
)
AS
BEGIN
	DECLARE	@c_vchObjName					NVARCHAR(30) = '[usp_close_outbound_order]', -- The name that uniquely tags this object.
			@v_vchBeginTrans				BIT = 0,
			@Round							INT,
			@v_dtProcessDateTime			DATETIME,
			@v_dtStartTranDate				DATETIME,
			@v_vchTranType					NVARCHAR(20) = '',
			@v_vchSubTranType				NVARCHAR(20) = '',
			@v_vchTranTypeDesc				NVARCHAR(100)= NULL,
			@v_vchHostInterfaceID           NVARCHAR(50) = NULL,

			@v_vchApplicationName			NVARCHAR(100),
			@v_vchWhMasterID				UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundOrderNumber		NVARCHAR(50) = NULL,
			@v_vchOrderType					NVARCHAR(50) = NULL,
			@v_vchOrderStatus				NVARCHAR(25) = NULL,
			@v_vchOwnerID                   UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode                 NVARCHAR(50) = NULL, 
			@v_vchCustomerID				UNIQUEIDENTIFIER = NULL,
			@v_vchCustomerCode              NVARCHAR(50) = NULL,
			@v_vchCustomerName				NVARCHAR(250)= NULL,
			@v_vchCustomerOrderNumber		NVARCHAR(50) = NULL,
			@v_vchTrackingNo	            NVARCHAR(50) = NULL,
			@in_vchSealNumber				NVARCHAR(50) = NULL,
			@in_vchContainerNo				NVARCHAR(50) = NULL,
			@in_vchTruckNumber				NVARCHAR(50) = NULL,
			@v_vchCarrierCode				NVARCHAR(40) = NULL,
			@in_vchTruckType				NVARCHAR(50) = NULL,
			@in_vchDriverLicense			NVARCHAR(50) = NULL,
			@v_vchShipToCode				NVARCHAR(40) = NULL,
			@v_vchShipToName				NVARCHAR(40) = NULL,
			@v_vchShipToAddr1				NVARCHAR(300)= NULL,
			@v_vchShipToAddr2				NVARCHAR(300)= NULL,
			@v_vchShipToAddr3				NVARCHAR(300)= NULL,
			@v_vchShipToCity				NVARCHAR(50) = NULL,
			@v_vchShipToProvince			NVARCHAR(50) = NULL,
			@v_vchShipToPostalCode			NVARCHAR(50) = NULL,
			@v_vchShipToCountry				NVARCHAR(5)	 = NULL,
			@v_vchShipToCountryName         NVARCHAR(50) = NULL,
			@v_vchShipToContactName         NVARCHAR(50) = NULL,
			@v_vchShipToPhoneNumber         NVARCHAR(50) = NULL,
			@v_vchBillToCode				NVARCHAR(40) = NULL,
			@v_vchBillToName				NVARCHAR(40) = NULL,
			@v_vchBillToAddr1				NVARCHAR(300)= NULL,
			@v_vchBillToAddr2				NVARCHAR(300)= NULL,
			@v_vchBillToAddr3				NVARCHAR(300)= NULL,
			@v_vchBillToCity				NVARCHAR(50) = NULL,
			@v_vchBillToProvince			NVARCHAR(50) = NULL,
			@v_vchBillToPostalCode			NVARCHAR(50) = NULL,
			@v_vchBillToCountry				NVARCHAR(5)	 = NULL,
			@v_vchBillToCountryName         NVARCHAR(50) = NULL,
			@v_vchBillToContactName         NVARCHAR(50) = NULL,
			@v_vchBillToPhoneNumber			NVARCHAR(50) = NULL,
			@v_vchHUDF1						NVARCHAR(255),
			@v_vchHUDF2						NVARCHAR(255),
			@v_vchHUDF3						NVARCHAR(2000),
			@v_vchHUDF4						NVARCHAR(255),
			@v_vchHUDF5						NVARCHAR(255),
			@v_vchHUDF6						NVARCHAR(255),
			@v_fltHUDF7						FLOAT,
			@v_fltHUDF8						FLOAT,
			@v_dtpHUDF9						DATETIME,
			@v_dtpHUDF10		            DATETIME,
			@v_dtShipDateActual             DATETIME,
			@v_dtDeliveryDatePlan           DATETIME,
			@v_vchPickType					NVARCHAR(15),

			@v_dtExpiryDate					DATE,
			@v_vchOutboundDetailID          UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID      UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber	            NVARCHAR(10) = NULL,
			@v_vchSTGLocationID		        UNIQUEIDENTIFIER = NULL,
			@v_vchSTGLocation		        NVARCHAR(50) = NULL,
			@v_vchSTGLPN			        NVARCHAR(25) = NULL,
			@v_vchLocationForPick	        NVARCHAR(50) = NULL,
			@v_vchWhItemMasterID	        UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		        UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber		        NVARCHAR(50) = NULL,
			@v_vchDefaultItemStatus	        NVARCHAR(50) = NULL,
			@v_fltQtyOrder			        float,
			@v_fltQtyClose			        float,
			@v_vchItemUOMID			        UNIQUEIDENTIFIER = NULL,
			@v_vchUomPrompt			        NVARCHAR(40) = NULL,
			@v_vchLotNumber			        NVARCHAR(50) = NULL,
			@v_vchExpiryDate	            NVARCHAR(50) = NULL,
			@v_vchSerialNumber              NVARCHAR(50) = NULL,
			@v_vchAttribute1                NVARCHAR(100)= NULL,
			@v_vchAttribute2	            NVARCHAR(100)= NULL,
			@v_vchAttribute3	            NVARCHAR(100)= NULL,
			@v_vchAttribute4	            NVARCHAR(100)= NULL,
			@v_vchAttribute5	            NVARCHAR(100)= NULL,
			@v_vchDUDF1				        NVARCHAR(50),
			@v_vchDUDF2				        NVARCHAR(50),
			@v_vchDUDF3				        NVARCHAR(50),
			@v_vchDUDF4				        NVARCHAR(50),
			@v_vchDUDF5				        NVARCHAR(50),
			@v_vchDUDF6				        NVARCHAR(50),
			@v_fltDUDF7				        FLOAT,
			@v_fltDUDF8				        FLOAT,
			@v_dtpDUDF9				        DATETIME,
			@v_dtpDUDF10		            DATETIME,
			@v_dtReceiveDate		        DATE,
			@v_dtMfgDate                    DATE,
			@v_vchInfPlanUOMID              UNIQUEIDENTIFIER = NULL,
			@v_vchInfPlanUOM		        NVARCHAR(20)

	BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID, @v_vchApplicationName output
		SET @v_dtStartTranDate = GETDATE();
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchOutboundOrderNumber = obMS.outbound_order_number
			, @v_vchOrderStatus = obMS.order_status
			, @v_vchOrderType = obMS.order_type
			, @v_vchOwnerID = obMS.owner_id
			, @v_vchOwnerCode = own.owner_code
			, @v_vchCustomerID = obMS.customer_id
			, @v_vchCustomerCode = obMS.customer_code
			, @v_vchCustomerName = obMS.customer_name
			, @v_vchTrackingNo = obMS.tracking_number
			, @in_vchSealNumber = obMS.seal_no
			, @in_vchContainerNo = obMS.container_no
			, @in_vchTruckNumber = obMS.tracking_number
			, @v_vchCarrierCode = carr.carrier_code
			, @in_vchTruckType = tt.truck_type
			, @in_vchDriverLicense = obMS.driver_license 
			, @v_vchShipToCode = obMS.ship_to_code	
			, @v_vchShipToName = obMS.ship_to_name
			, @v_vchShipToAddr1 = obMS.ship_to_addr_line_1
			, @v_vchShipToAddr2 = obMS.ship_to_addr_line_2
			, @v_vchShipToAddr3 = obMS.ship_to_addr_line_3
			, @v_vchShipToCity = obMS.ship_to_city
			, @v_vchShipToProvince = obMS.ship_to_province
			, @v_vchShipToPostalCode = obMS.ship_to_postal_code
			, @v_vchShipToCountry = obMS.ship_to_country_code
			, @v_vchShipToCountryName = obMS.ship_to_country_name
			, @v_vchShipToContactName = obMS.ship_to_contact
			, @v_vchShipToPhoneNumber = obMS.ship_to_phone
			, @v_vchBillToCode = obMS.bill_to_code
			, @v_vchBillToName = obMS.bill_to_name
			, @v_vchBillToAddr1 = obMS.bill_to_address_line_1
			, @v_vchBillToAddr2 = obMS.bill_to_address_line_2
			, @v_vchBillToAddr3 = obMS.bill_to_address_line_3
			, @v_vchBillToCity = obMS.bill_to_city
			, @v_vchBillToProvince = obMS.bill_to_province
			, @v_vchBillToPostalCode = obMS.bill_to_postal_code
			, @v_vchBillToCountry = obMS.bill_to_country
			, @v_vchBillToCountryName = obMS.bill_to_country_name
			, @v_vchBillToContactName = obMS.bill_to_contact_name
			, @v_vchBillToPhoneNumber = obMS.bill_to_phone_number
			, @v_vchHUDF1 = obMS.user_def1
			, @v_vchHUDF2 = obMS.user_def2
			, @v_vchHUDF3 = obMS.user_def3
			, @v_vchHUDF4 = obMS.user_def4
			, @v_vchHUDF5 = obMS.user_def5
			, @v_vchHUDF6 = obMS.user_def6
			, @v_fltHUDF7 = obMS.user_def7
			, @v_fltHUDF8 = obMS.user_def8
			, @v_dtpHUDF9 = obMS.user_def9
			, @v_dtpHUDF10 = obMS.user_def10  
			, @v_vchCustomerOrderNumber = obMS.customer_order_number
			, @v_dtShipDateActual   = obMS.ship_date_actual
			, @v_dtDeliveryDatePlan  = obMS.delivery_date_plan
			, @v_vchPickType = obMS.pick_type
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		LEFT JOIN t_wms_truck_type tt ON obMS.truck_type_id = tt.truck_type_id
		LEFT JOIN t_wms_carrier carr ON obMS.carrier_id = carr.carrier_id
		WHERE obMS.wh_master_id = @v_vchWhMasterID 
		AND obMS.outbound_order_master_id = @in_vchOutboundMasterID

		IF(@in_vchOutboundMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ALREADY_CLOSE';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchOrderStatus NOT IN ('PICK','PICKED','SHIP'))
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_NOT_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		IF EXISTS (SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_master pickMS
					INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
					WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
					AND (ISNULL(quantity_pick,0) <> ISNULL(quantity_stage,0) OR ISNULL(quantity_stage,0) <> ISNULL(quantity_ship,0)))
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_NOT_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		-------------------------------------------
		-- order type send to interface
		-------------------------------------------
		IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_INTERFACE' AND is_active = 'YES') AND @v_vchOrderType <> 'Other')
			BEGIN
				SET @v_vchSubTranType = 'CLOSE_ORDER_ERP';
			END
		ELSE
			BEGIN
				SET @v_vchSubTranType = 'CLOSE_ORDER';
			END

		IF (@v_vchOrderType = (SELECT TOP 1 value from t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
	   		BEGIN
		        SET @v_vchTranType ='BLIND_PICK'	
			END
		ELSE
		    BEGIN
				SET @v_vchTranType ='OO_SHIP'
			END
			
		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;

			--Update Order Status = Close
			UPDATE t_wms_outbound_master SET 
				order_status = 'CLOSE'
				,close_remark = @in_vchRemark
				,close_by = @in_vchUserID
				,close_date = @in_dtCloseDate
			WHERE outbound_order_master_id = @in_vchOutboundMasterID

			--ถ้า Order Type BO ให้เปลี่ยน Status In transit >> Consignment
			IF (@v_vchOrderType = 'BO')
				BEGIN
					DECLARE @v_vchSourceLocationID	UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchSourceLocation	NVARCHAR(50)
					DECLARE @v_vchLoopSerialNumber	NVARCHAR(50)
					
					SELECT @v_vchSourceLocationID = custLoc.location_id 
						,@v_vchSourceLocation = loc.location
					FROM t_wms_customer_location custLoc 
					INNER JOIN t_wms_location loc ON custLoc.location_id = loc.location_id
					WHERE custLoc.customer_id = @v_vchCustomerID 
					AND custLoc.is_active = 'YES'
					IF (@v_vchSourceLocationID IS NULL)
						BEGIN
							SET @out_ErrorCode = 'INFO-CUSTOMER-LOCATION-NOT-MAP'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;		
						END

					DECLARE CHANGE_STATUS_CURSOR CURSOR FOR
						SELECT pickDT.serial_number
						FROM t_wms_outbound_pick_master pickMS
						INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND ISNULL(pickDT.serial_number,'') <> ''
					OPEN CHANGE_STATUS_CURSOR
					FETCH NEXT FROM CHANGE_STATUS_CURSOR INTO @v_vchLoopSerialNumber
					WHILE @@FETCH_STATUS = 0
						BEGIN
							EXEC usp_wms_change_status_by_serial 
									@in_vchApplicationID	= @in_vchApplicationID,
									@in_vchLocation			= @v_vchSourceLocation,	
									@in_vchSerialNumber		= @v_vchLoopSerialNumber,
									@in_vchDestinationStatus= 'Consignment',
									@in_vchDevice			= @in_vchDeviceID,
									@in_vchUserID			= @in_vchUserID,
									@in_vchTranType			= 'INV_CHANGE',
									@in_vchSubTranType		= 'INV_CHANGE_STATUS',
									@in_vchTranTypeDesc		= 'Change Status Consignment',
									@out_vchErrorCode		= @out_ErrorCode OUTPUT,
									@out_vchErrorMsg		= @out_ErrorMessage OUTPUT

								IF (@out_ErrorCode <> '0')
									GOTO WRITE_PROC;

							SET @v_vchLoopSerialNumber = NULL
							FETCH NEXT FROM CHANGE_STATUS_CURSOR INTO @v_vchLoopSerialNumber	
						END
					CLOSE CHANGE_STATUS_CURSOR                  	
					DEALLOCATE CHANGE_STATUS_CURSOR
				END

				EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT
				DECLARE CloseOutboundCURSOR CURSOR FOR
				SELECT vOutbound.outbound_order_detail_id
					,vOutbound.outbound_pick_detail_id
					,vOutbound.line_number
					,vOutbound.location
					,vOutbound.staging_location_id
					,locStg.location
					,vOutbound.staging_lpn
					,vOutbound.wh_item_master_id
					,vOutbound.item_master_id
					,vOutbound.item_number
					,vOutbound.default_item_status
					,vOutbound.quantity_order
					,ISNULL(vOutbound.quantity_stage,0) - ISNULL(vOutbound.quantity_ship,0)
					,vOutbound.item_uom_id
					,vOutbound.uom_prompt
					,vOutbound.lot_number
					,vOutbound.[expiry_date]
					,vOutbound.serial_number
					,vOutbound.attribute1
					,vOutbound.attribute2
					,vOutbound.attribute3
					,vOutbound.attribute4
					,vOutbound.attribute5
					,vOutbound.user_def1
					,vOutbound.user_def2
					,vOutbound.user_def3
					,vOutbound.user_def4
					,vOutbound.user_def5
					,vOutbound.user_def6
					,vOutbound.user_def7
					,vOutbound.user_def8
					,vOutbound.user_def9
					,vOutbound.user_def10
					,vOutbound.receive_date
					,vOutbound.mfg_date
					,vOutbound.interface_plan_uom_id
				FROM v_wms_outbound_pick_mini vOutbound
				inner join t_wms_location locStg ON vOutbound.staging_location_id = locStg.location_id
				WHERE outbound_order_master_id = @in_vchOutboundMasterID 
				OPEN  CloseOutboundCURSOR
				FETCH NEXT FROM CloseOutboundCURSOR INTO @v_vchOutboundDetailID,@v_vchOutboundPickDetailID,@v_vchLineNumber,@v_vchLocationForPick,@v_vchSTGLocationID,@v_vchSTGLocation,@v_vchSTGLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
									,@v_vchDefaultItemStatus,@v_fltQtyOrder,@v_fltQtyClose,@v_vchItemUOMID,@v_vchUomPrompt,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
									,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10,@v_dtReceiveDate,@v_dtMfgDate,@v_vchInfPlanUOMID
				WHILE @@FETCH_STATUS = 0			
					BEGIN
						IF ISNULL(@v_vchExpiryDate,'') <> ''
							SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate);
						ELSE
							SET @v_dtExpiryDate = NULL
						
						DECLARE @v_fltInfQuantity   FLOAT = NULL
						DECLARE @v_vchInfConFactor  FLOAT = NULL

						SELECT @v_vchInfPlanUom = uom.uom
							,@v_vchInfConFactor = uom.conversion_factor
						FROM t_wms_item_uom uom
						WHERE uom.item_uom_id = @v_vchInfPlanUomID

						IF @v_vchInfPlanUomID IS NOT NULL
							BEGIN
								SET @v_fltInfQuantity = ROUND((@v_fltQtyClose / @v_vchInfConFactor),@Round)
							END
						ELSE
							BEGIN
								SET @v_fltInfQuantity = @v_fltQtyClose
								SET @v_vchInfPlanUom = @v_vchUomPrompt
							END

						SET @v_dtProcessDateTime = GETDATE()
						EXEC usp_LogManager  @in_vchApplicationID = @in_vchApplicationID
											,@in_vchAppName			= @v_vchApplicationName
											,@in_vchDevice			= @in_vchDeviceID
											,@in_vchUserID			= @in_vchUserID
											,@in_vchLogType			= 'TRANSACTION'
											,@in_vchTranType		= @v_vchTranType
											,@in_vchSubTranType		= @v_vchSubTranType
											,@in_vchDescription		= 'Close Outbound Order'
											,@in_dtStartTranDate	= @v_dtStartTranDate
											,@in_dtEndTranDate		= @v_dtProcessDateTime
											,@in_vchWhID			= @in_vchWarehouse
											,@in_vchToWhID			= NULL
											,@in_vchOwner			= @v_vchOwnerCode
											,@in_vchToOwner			= NULL
											,@in_vchLocation		= @v_vchSTGLocation
											,@in_vchToLocation		= NULL
											,@in_vchItemNumber		= @v_vchItemNumber
											,@in_vchUOM				= @v_vchUomPrompt
											,@in_fltQuantity		= @v_fltQtyClose
											,@in_vchSerialNumber	= @v_vchSerialNumber
											,@in_fltAfterQuantity	= 0
											,@in_vchAfterUOM		= @v_vchUomPrompt
											,@in_vchLotNumber		= @v_vchLotNumber
											,@in_vchAfterLotNumber	= NULL
											,@in_dtExpiryDate		= @v_dtExpiryDate
											,@in_dtAfterExpiryDate	= NULL
											,@in_vchAttribute1		= @v_vchAttribute1
											,@in_vchAfterAttribute1	= NULL
											,@in_vchAttribute2		= @v_vchAttribute2
											,@in_vchAfterAttribute2	= NULL
											,@in_vchAttribute3		= @v_vchAttribute3
											,@in_vchAfterAttribute3	= NULL
											,@in_vchAttribute4		= @v_vchAttribute4
											,@in_vchAfterAttribute4	= NULL
											,@in_vchAttribute5		= @v_vchAttribute5
											,@in_vchAfterAttribute5	= NULL
											,@in_vchLPN				= @v_vchSTGLPN
											,@in_vchAfterLPN		= NULL
											,@in_vchStatus			= @v_vchDefaultItemStatus
											,@in_vchAfterStatus		= NULL
											,@in_vchOrderNumber		= @v_vchOutboundOrderNumber
											,@in_vchOrderStatus		= @v_vchOrderStatus
											,@in_vchOrderType		= @v_vchOrderType
											,@in_vchControlNumber	= @v_vchHostInterfaceID
											,@in_vchLineNumber		= @v_vchLineNumber
											,@in_vchOrderQuantity	= @v_fltQtyOrder
											,@in_vchShortQuantity	= 0

											,@in_vchProcess			= @c_vchObjName
											,@in_dtProcessDateTime	= @v_dtProcessDateTime
											,@in_vchTrackingNumber	= @v_vchTrackingNo
											,@in_vchSealNumber		= @in_vchSealNumber
											,@in_vchContainerNo		= @in_vchContainerNo
											,@in_vchTrailerNumber	= @in_vchTruckNumber
											,@in_vchCarrierCode		= @v_vchCarrierCode
											,@in_vchEquipmentType	= @in_vchTruckType
											,@in_vchCDLLicense		= @in_vchDriverLicense

											,@in_vchHUDF1			= @v_vchHUDF1
											,@in_vchHUDF2			= @v_vchHUDF2
											,@in_vchHUDF3			= @v_vchHUDF3
											,@in_vchHUDF4			= @v_vchHUDF4
											,@in_vchHUDF5			= @v_vchHUDF5
											,@in_vchHUDF6			= @v_vchHUDF6
											,@in_fltHUDF7			= @v_fltHUDF7
											,@in_fltHUDF8			= @v_fltHUDF8
											,@in_dtpHUDF9			= @v_dtpHUDF9
											,@in_dtpHUDF10			= @v_dtpHUDF10

											,@in_vchDUDF1			= @v_vchDUDF1
											,@in_vchDUDF2			= @v_vchDUDF2
											,@in_vchDUDF3			= @v_vchDUDF3
											,@in_vchDUDF4			= @v_vchDUDF4
											,@in_vchDUDF5			= @v_vchDUDF5
											,@in_vchDUDF6			= @v_vchInfPlanUom
											,@in_fltDUDF7			= @v_fltInfQuantity  
											,@in_fltDUDF8			= @v_fltDUDF8
											,@in_dtpDUDF9			= @v_dtpDUDF9
											,@in_dtpDUDF10			= @v_dtpDUDF10
											
											,@in_vchPickLocation	= @v_vchLocationForPick
											,@in_vchHostRecordID	= @v_vchHostInterfaceID
											,@in_dtPostingDate		= @v_dtShipDateActual
											,@in_dtReceiveDate		= @v_dtReceiveDate
											,@in_dtProductionDate	= @v_dtMfgDate
											,@in_vchCustomerCode	= @v_vchCustomerCode 
											,@in_dtShipDateActual	= @v_dtShipDateActual
											,@in_dtDeliveryDatePlan = @v_dtDeliveryDatePlan 

											,@in_vchShipToCode			= @v_vchShipToCode		
											,@in_vchShipToName			= @v_vchShipToName		
											,@in_vchShipToAddr1			= @v_vchShipToAddr1		
											,@in_vchShipToAddr2			= @v_vchShipToAddr2		
											,@in_vchShipToAddr3			= @v_vchShipToAddr3		
											,@in_vchShipToCity			= @v_vchShipToCity		
											,@in_vchShipToProvince		= @v_vchShipToProvince	
											,@in_vchShipToPostalCode	= @v_vchShipToPostalCode	
											,@in_vchShipToCountry		= @v_vchShipToCountry		
											,@in_vchShipToCountryName	= @v_vchShipToCountryName 
											,@in_vchShipToContactName	= @v_vchShipToContactName 
											,@in_vchShipToPhoneNumber	= @v_vchShipToPhoneNumber 
											,@in_vchBillToCode			= @v_vchBillToCode		
											,@in_vchBillToName			= @v_vchBillToName		
											,@in_vchBillToAddr1			= @v_vchBillToAddr1		
											,@in_vchBillToAddr2			= @v_vchBillToAddr2		
											,@in_vchBillToAddr3			= @v_vchBillToAddr3		
											,@in_vchBillToCity			= @v_vchBillToCity		
											,@in_vchBillToProvince		= @v_vchBillToProvince	
											,@in_vchBillToPostalCode	= @v_vchBillToPostalCode	
											,@in_vchBillToCountry		= @v_vchBillToCountry		
											,@in_vchBillToCountryName	= @v_vchBillToCountryName 
											,@in_vchBillToContactName	= @v_vchBillToContactName 
											,@in_vchBillToPhoneNumber	= @v_vchBillToPhoneNumber
											,@in_vchComment				= @v_vchOutboundDetailID
											,@in_vchErrorCode			= @out_ErrorCode OUTPUT
											,@in_vchMessage				= @out_ErrorMessage OUTPUT
						IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
							BEGIN
								GOTO WRITE_PROC;
							END

						FETCH NEXT FROM CloseOutboundCURSOR INTO @v_vchOutboundDetailID,@v_vchOutboundPickDetailID,@v_vchLineNumber,@v_vchLocationForPick,@v_vchSTGLocationID,@v_vchSTGLocation,@v_vchSTGLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
									,@v_vchDefaultItemStatus,@v_fltQtyOrder,@v_fltQtyClose,@v_vchItemUOMID,@v_vchUomPrompt,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
									,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10,@v_dtReceiveDate,@v_dtMfgDate,@v_vchInfPlanUOMID
					END
				CLOSE CloseOutboundCURSOR
				DEALLOCATE CloseOutboundCURSOR

			--Unallocate Qty กรณีที่ใช้ Partial Ship และไม่ต้องการหยิบต่อแล้ว 
			IF @v_vchPickType IN ('SYSTEM','SYSTEM_GROUP')
			BEGIN
				DECLARE @v_vchUnLocationID		UNIQUEIDENTIFIER = NULL
				DECLARE @v_vchUnParentLPN		NVARCHAR(25) = NULL
				DECLARE @v_vchUnLPN				NVARCHAR(25) = NULL
				DECLARE @v_vchUnWhItemMasterID	UNIQUEIDENTIFIER = NULL
				DECLARE @v_vchUnLotNumber		NVARCHAR(50)= NULL
				DECLARE @v_vchUnExpiryDate		NVARCHAR(8)= NULL
				DECLARE @v_vchUnSerialNumber	NVARCHAR(100)= NULL
				DECLARE @v_vchUnAttribute1		NVARCHAR(100)= NULL
				DECLARE @v_vchUnAttribute2		NVARCHAR(100)= NULL
				DECLARE @v_vchUnAttribute3		NVARCHAR(100)= NULL
				DECLARE @v_vchUnAttribute4		NVARCHAR(100)= NULL
				DECLARE @v_vchUnAttribute5		NVARCHAR(100)= NULL
				DECLARE @v_dtUnReceiveDate		DATE= NULL
				DECLARE @v_vchUnDefaultStatus	NVARCHAR(50)= NULL
				DECLARE @v_fltUnallocateQty		FLOAT= NULL 

				-----------------------------------------------
				-- Un allocate data
				-----------------------------------------------
				DECLARE cursorOutboundUnAllocate CURSOR FOR
					SELECT pickDT.location_id
						,pickDT.parent_lpn
						,pickDT.lpn
						,pickDT.wh_item_master_id
						,pickDT.lot_number
						,pickDT.[expiry_date] 
						,pickDT.serial_number
						,pickDT.attribute1
						,pickDT.attribute2
						,pickDT.attribute3
						,pickDT.attribute4
						,pickDT.attribute5
						,pickDT.receive_date
						,obDT.default_item_status
						,ROUND((pickDT.quantity_plan - pickDT.quantity_pick),@Round)
					FROM t_wms_outbound_pick_master pickMS
					INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickdt.outbound_pick_master_id
					INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
					WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID		
					AND ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) > 0 
					AND pickDT.is_override = 'NO'
		
				OPEN cursorOutboundUnAllocate;
				FETCH NEXT FROM cursorOutboundUnAllocate INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber	
															,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_dtUnReceiveDate,@v_vchUnDefaultStatus,@v_fltUnallocateQty
				WHILE @@FETCH_STATUS = 0
					BEGIN
						-- un allocate inventory data
						EXEC [usp_inventory_un_allocate] @in_vchApplicationID	  = @in_vchApplicationID
														, @in_vchWarehouseMasterID = @v_vchWhMasterID	
														, @in_vchLocationID		  = @v_vchUnLocationID
														, @in_vchParentLPN		  = @v_vchUnParentLPN	
														, @in_vchLPN			  = @v_vchUnLPN
														, @in_vchWhItemMasterID	  = @v_vchUnWhItemMasterID
														, @in_fltQuantity		  = @v_fltUnallocateQty	
														, @in_vchSerialNumber	  = @v_vchUnSerialNumber	
														, @in_vchLotNumber		  = @v_vchUnLotNumber	
														, @in_vchExpiryDate		  = @v_vchUnExpiryDate
														, @in_vchAttribute1		  = @v_vchUnAttribute1
														, @in_vchAttribute2		  = @v_vchUnAttribute2
														, @in_vchAttribute3		  = @v_vchUnAttribute3
														, @in_vchAttribute4		  = @v_vchUnAttribute4
														, @in_vchAttribute5		  = @v_vchUnAttribute5
														, @in_dtReceiveDate		  = @v_dtUnReceiveDate
														, @in_vchDefaultItemStatus = @v_vchUnDefaultStatus
														, @in_vchUserID			  = @in_vchUserID	
														, @out_ErrorCode		  = @out_ErrorCode	OUTPUT
														, @out_ErrorMessage		  = @out_ErrorMessage OUTPUT							
						IF (@out_ErrorCode <> '0')
							BEGIN 
								GOTO WRITE_PROC; 
							END
						FETCH NEXT FROM cursorOutboundUnAllocate INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber	
															,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_dtUnReceiveDate,@v_vchUnDefaultStatus,@v_fltUnallocateQty
					END
				CLOSE cursorOutboundUnAllocate;
				DEALLOCATE cursorOutboundUnAllocate;
			END

		COMMIT TRANSACTION;

		IF (@v_vchTranType IN ('OO_SHIP','OO_SHIP_CONSIGNMENT','OO_PARTIAL_SHIP') AND @v_vchSubTranType IN ('CONFIRM_TO_ERP','CLOSE_ORDER_ERP'))
			BEGIN
				UPDATE t_host_wms_ship_conf_detail_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
				UPDATE t_host_wms_ship_conf_header_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
	    RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		-----------------------------------------------------------------------------------
		BEGIN
			WRITE_PROC:							
				IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
				
				IF CURSOR_STATUS('global','CloseOutboundCURSOR')>=-1
					BEGIN
						CLOSE CloseOutboundCURSOR;
						DEALLOCATE CloseOutboundCURSOR;
					END
										
				IF CURSOR_STATUS('global','CHANGE_STATUS_CURSOR')>=-1
					BEGIN
						CLOSE CHANGE_STATUS_CURSOR;
						DEALLOCATE CHANGE_STATUS_CURSOR;
					END

				IF CURSOR_STATUS('global','cursorOutboundUnAllocate')>=-1
					BEGIN
						CLOSE cursorOutboundUnAllocate;
						DEALLOCATE cursorOutboundUnAllocate;
					END

				SET @v_dtProcessDateTime = GETDATE(); 
				EXEC usp_LogManager
					@in_vchApplicationID  = @in_vchApplicationID,
					@in_vchWhID           = @in_vchWarehouse,
					@in_vchDevice         = @in_vchDeviceID,
					@in_vchUserID         = @in_vchUserID,
					@in_vchLogType        = 'PROCESS',
					@in_vchProcess        = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1          = @v_vchOutboundOrderNumber,
					@in_vchData2          = @v_vchTranType,
					@in_vchData3          = @v_vchSubTranType,
					@in_vchData4          = NULL,
					@in_vchErrorCode      = @out_ErrorCode,
					@in_vchMessage        = @out_ErrorMessage
		END
	END TRY
	BEGIN CATCH
	
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
								
		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode    = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END

		IF CURSOR_STATUS('global','CloseOutboundCURSOR')>=-1
			BEGIN
				CLOSE CloseOutboundCURSOR;
				DEALLOCATE CloseOutboundCURSOR;
			END
										
		IF CURSOR_STATUS('global','CHANGE_STATUS_CURSOR')>=-1
			BEGIN
				CLOSE CHANGE_STATUS_CURSOR;
				DEALLOCATE CHANGE_STATUS_CURSOR;
			END
		IF CURSOR_STATUS('global','cursorOutboundUnAllocate')>=-1
			BEGIN
				CLOSE cursorOutboundUnAllocate;
				DEALLOCATE cursorOutboundUnAllocate;
			END

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID  = @in_vchApplicationID,
			@in_vchWhID           = @in_vchWarehouse,
			@in_vchDevice         = @in_vchDeviceID,
			@in_vchUserID         = @in_vchUserID,
			@in_vchLogType        = 'PROCESS',
			@in_vchProcess        = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1          = @v_vchOutboundOrderNumber,
			@in_vchData2          = @v_vchTranType,
			@in_vchData3          = @v_vchSubTranType,
			@in_vchData4          = NULL,
			@in_vchErrorCode      = @out_ErrorCode,
			@in_vchMessage        = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		

	END CATCH 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_partial_receive]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_partial_receive]
	@in_vchApplicationID	NVARCHAR(40),
	@in_vchDevice			NVARCHAR(50),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER, 
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER, 
	@in_vchCloseBy			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON; 
	SET XACT_ABORT ON; 
	DECLARE @v_vchApplicationName		NVARCHAR(100),
			@v_vchObjName				NVARCHAR(50) = '[usp_close_partial_receive]',
			@v_dtStartTranDate			DATETIME = GETDATE(),
			@v_dtEndTranDate			DATETIME,
			@v_dtProcessDateTime		DATETIME, 
			@v_vchBeginTrans			BIT = 0,
			@Round						INT, 
			@v_vchHostInterfaceID		NVARCHAR(20),
			@v_vchWarehouse				NVARCHAR(50)= NULL,
			@v_vchInboundOrder			NVARCHAR(50),
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(40),
			@v_vchOrderType				NVARCHAR(30),
			@v_vchOrderStatus			NVARCHAR(10),
			@v_vchReferenceNumber		NVARCHAR(50),
			@v_vchCustomerCode			NVARCHAR(50),
			@v_vchSupplierCode			NVARCHAR(50),
			@v_dtPostingDate			DATE,

			@v_vchReceiveNumber			NVARCHAR(50) = NULL,
			@v_vchIBMSUDF1				NVARCHAR(50),
			@v_vchIBMSUDF2				NVARCHAR(50),
			@v_vchIBMSUDF3				NVARCHAR(50),
			@v_vchIBMSUDF4				NVARCHAR(50),
			@v_vchIBMSUDF5				NVARCHAR(50),
			@v_vchIBMSUDF6				NVARCHAR(50),
			@v_fltIBMSUDF7				FLOAT,
			@v_fltIBMSUDF8				FLOAT,
			@v_dtpIBMSUDF9				DATETIME,
			@v_dtpIBMSUDF10				DATETIME,

			@v_vchInboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber			NVARCHAR(10),
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50),
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_vchReceiveStatus			NVARCHAR(40),
			@v_fltReceiveQuantity		FLOAT,
			@v_vchUOM					NVARCHAR(40), 
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchReceiveLocation		NVARCHAR(50), 
			@v_vchParentLPN				NVARCHAR(25),
			@v_vchLPN					NVARCHAR(25),
			@v_vchLotNumber				NVARCHAR(50),
			@v_dtMfgDate				DATE,
			@v_vchExpiryDate			NVARCHAR(50),
			@v_vchSerialNumber			NVARCHAR(50), 
			@v_vchAttribute1			NVARCHAR(50),
			@v_vchAttribute2			NVARCHAR(50),
			@v_vchAttribute3			NVARCHAR(50),
			@v_vchAttribute4			NVARCHAR(50),
			@v_vchAttribute5			NVARCHAR(50),
			@v_dtReceiveDate			DATE,
			@v_vchDUDF1					NVARCHAR(255),
			@v_vchDUDF2					NVARCHAR(255),
			@v_vchDUDF3					NVARCHAR(255),
			@v_vchDUDF4					NVARCHAR(255),
			@v_vchDUDF5					NVARCHAR(255),
			@v_vchDUDF6					NVARCHAR(255),
			@v_fltDUDF7					FLOAT,
			@v_fltDUDF8					FLOAT,
			@v_dtpDUDF9					DATETIME,
			@v_dtpDUDF10				DATETIME,
			@v_dtExpiryDate				DATE,
			@v_vchTranType				NVARCHAR(20),
			@v_vchSubTranType			NVARCHAR(20) = 'CLOSE_RECEIPT',
			@v_vchERPLocation			NVARCHAR(50),
			@v_fltERPQtyReceived		FLOAT,
			@v_vchERPUOM				NVARCHAR(20)

	EXEC usp_get_application_name @in_vchApplicationID, @v_vchApplicationName OUTPUT
	SELECT TOP 1 @Round = value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	BEGIN TRY 
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM dbo.t_wms_wh WHERE wh_master_id = @in_vchWhMasterID and is_active ='YES'
		IF (@v_vchWarehouse IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchCloseBy)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		-- Select data from inbound master
		SELECT TOP 1 @v_vchInboundOrder	= ibMS.inbound_order_number
			,@v_vchOrderType		= ibMS.order_type
			,@v_vchOrderStatus		= ibMS.order_status
			,@v_vchReferenceNumber	= ibMS.reference_number
			,@v_vchOwnerID			= ibMS.owner_id
			,@v_vchOwnerCode		= ibMS.owner_code
			,@v_vchCustomerCode		= cust.customer_code
			,@v_vchSupplierCode		= supp.supplier_code
			,@v_dtPostingDate		= ibMS.posting_date
			,@v_vchIBMSUDF1			= ibMS.user_def1
			,@v_vchIBMSUDF2			= ibMS.user_def2			
			,@v_vchIBMSUDF3			= ibMS.user_def3
			,@v_vchIBMSUDF4			= ibMS.user_def4
			,@v_vchIBMSUDF5			= ibMS.user_def5
			,@v_vchIBMSUDF6			= ibMS.user_def6
			,@v_fltIBMSUDF7			= ibMS.user_def7
			,@v_fltIBMSUDF8			= ibMS.user_def8
			,@v_dtpIBMSUDF9			= ibMS.user_def9
			,@v_dtpIBMSUDF10		= ibMS.user_def10
		FROM dbo.t_wms_inbound_master ibMS 
		LEFT JOIN dbo.t_wms_customer cust ON ibMS.customer_id = cust.customer_id 
		LEFT JOIN dbo.t_wms_supplier supp ON ibMS.supplier_id = supp.supplier_id 
		WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID 

		IF (SELECT TOP 1 value from dbo.t_wms_rule WHERE rule_code = 'BLIND_RECEIPT_ORDER_TYPE' AND is_active = 'YES') = @v_vchOrderType
	   		BEGIN
				SET @v_vchTranType = 'BLIND_RECEIPT'	
			END
		ELSE
			BEGIN
				SET @v_vchTranType = 'IO_RECEIPT'	
			END

		IF (@v_vchOrderType IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_INBOUND_ORDER_TYPE_FOR_INTERFACE' and is_active = 'YES'))
			BEGIN
				SET @v_vchSubTranType = 'CLOSE_RECEIPT_TO_ERP'
				EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT 
			END
		ELSE
			BEGIN
				SET @v_vchSubTranType = 'CLOSE_RECEIPT'
			END
				 
		IF (@v_dtPostingDate IS NULL)
			SET @v_dtPostingDate = GETDATE();
		 
		BEGIN TRANSACTION
		SET @v_vchBeginTrans = 1;
			DECLARE ReceiveDetailCursor CURSOR FOR 
				SELECT recHD.receipt_number
					,ibDT.inbound_order_detail_id
					,ibDT.line_number
					,ibDT.item_master_id
					,ibDT.item_number
					,invST.inventory_status_id
					,recDT.receipt_item_status
					,ROUND(recDT.quantity_received,@Round) AS quantity_received
					,ibDT.uom
					,loc.location_id
					,loc.location
					,recDT.parent_lpn
					,recDT.lpn
					,recDT.lot_number
					,recDT.mfg_date
					,recDT.expiry_date
					,recDT.serial_number
					,recDT.attribute1
					,recDT.attribute2
					,recDT.attribute3
					,recDT.attribute4
					,recDT.attribute5
					,recDT.receive_date
					,ibDT.user_def1
					,ibDT.user_def2
					,ibDT.user_def3
					,ibDT.user_def4
					,ibDT.user_def5
					,ibDT.user_def6
					,ibDT.user_def7
					,ibDT.user_def8
					,ibDT.user_def9
					,ibDT.user_def10
					,loc.erp_location
					,ROUND(ibDT.quantity_receive,@round)	AS erp_qty
					,ibDT.uom	AS  erp_uom
				FROM (SELECT receipt_header_id 
							,inbound_order_detail_id
							,location_received
							,parent_lpn
							,lpn
							,receipt_item_status 
							,lot_number
							,mfg_date
							,expiry_date
							,serial_number
							,attribute1
							,attribute2
							,attribute3
							,attribute4
							,attribute5
							,receive_date
							,SUM(quantity_received) AS quantity_received
						FROM t_wms_receipt_detail
						WHERE receipt_header_id = @in_vchReceiptHeaderID 
						GROUP BY receipt_header_id 
							,inbound_order_detail_id
							,location_received
							,parent_lpn
							,lpn
							,receipt_item_status 
							,lot_number
							,mfg_date
							,expiry_date
							,serial_number
							,attribute1
							,attribute2
							,attribute3
							,attribute4
							,attribute5
							,receive_date
						) recDT
				INNER JOIN dbo.t_wms_receipt_header recHD ON recDT.receipt_header_id = recHD.receipt_header_id
				INNER JOIN dbo.t_wms_inbound_detail ibDT ON recDT.inbound_order_detail_id = ibDT.inbound_order_detail_id 
				INNER JOIN dbo.t_wms_location loc ON loc.location = recDT.location_received AND loc.wh_master_id = @in_vchWhMasterID
				INNER JOIN dbo.t_wms_inventory_status invST ON recDT.receipt_item_status = invST.inv_status 
				WHERE recHD.receipt_status = 'OPEN'
				ORDER BY ibDT.line_number
			OPEN ReceiveDetailCursor
			FETCH FROM ReceiveDetailCursor INTO @v_vchReceiveNumber,@v_vchInboundDetailID,@v_vchLineNumber,@v_vchItemMasterID,@v_vchItemNumber,@v_vchInvStatusID,@v_vchReceiveStatus,@v_fltReceiveQuantity,@v_vchUOM,@v_vchLocationID,@v_vchReceiveLocation,@v_vchParentLPN,@v_vchLPN
												,@v_vchLotNumber,@v_dtMfgDate,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate
												,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10,@v_vchERPLocation,@v_fltERPQtyReceived,@v_vchERPUOM
			WHILE @@FETCH_STATUS = 0
				BEGIN
					SET @v_dtProcessDateTime = GETDATE()
					SET @v_dtEndTranDate = GETDATE()
					IF ISNULL(@v_vchExpiryDate,'') <> ''
						SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate)

					EXEC usp_LogManager @in_vchApplicationID			= @in_vchApplicationID
										,@in_vchAppName					= @v_vchApplicationName
										,@in_vchDevice					= @in_vchDevice
										,@in_vchUserID					= @in_vchCloseBy
										,@in_vchLogType					= 'TRANSACTION'
										,@in_vchProcess					= @v_vchObjName
										,@in_dtProcessDateTime			= @v_dtProcessDateTime
										,@in_vchTranType				= @v_vchTranType
										,@in_vchSubTranType				= @v_vchSubTranType
										,@in_dtStartTranDate			= @v_dtStartTranDate
										,@in_dtEndTranDate				= @v_dtEndTranDate
										,@in_vchWhID 					= NULL
										,@in_vchToWhID 					= @v_vchWarehouse
										,@in_vchLocation				= NULL
										,@in_vchToLocation				= @v_vchReceiveLocation
										,@in_vchOwner					= NULL
										,@in_vchToOwner					= @v_vchOwnerCode
										,@in_vchItemNumber				= @v_vchItemNumber
										,@in_fltQuantity				= @v_fltReceiveQuantity
										,@in_vchUOM						= @v_vchUOM
										,@in_vchBaseUOM					= @v_vchUOM
										,@in_fltAfterQuantity			= @v_fltReceiveQuantity
										,@in_vchAfterUOM				= @v_vchUOM
										,@in_vchLotNumber				= NULL
										,@in_vchAfterLotNumber			= @v_vchLotNumber
										,@in_dtExpiryDate				= NULL
										,@in_dtAfterExpiryDate			= @v_dtExpiryDate
										,@in_vchAttribute1				= NULL
										,@in_vchAfterAttribute1			= @v_vchAttribute1
										,@in_vchAttribute2				= NULL
										,@in_vchAfterAttribute2			= @v_vchAttribute2
										,@in_vchAttribute3				= NULL
										,@in_vchAfterAttribute3			= @v_vchAttribute3
										,@in_vchAttribute4				= NULL
										,@in_vchAfterAttribute4			= @v_vchAttribute4
										,@in_vchAttribute5				= NULL
										,@in_vchAfterAttribute5			= @v_vchAttribute5
										,@in_vchSerialNumber			= @v_vchSerialNumber
										,@in_dtReceiveDate				= @v_dtReceiveDate
										,@in_dtProductionDate			= @v_dtMfgDate
										,@in_vchLPN						= NULL
										,@in_vchAfterLPN				= @v_vchLPN
										,@in_vchParentLPN				= NULL
										,@in_vchAfterParentLPN			= @v_vchParentLPN
										,@in_vchStatus					= NULL
										,@in_vchAfterStatus				= @v_vchReceiveStatus
										,@in_vchReferenceNumber			= @v_vchHostInterfaceID
										,@in_vchOrderNumber				= @v_vchInboundOrder
										,@in_vchOrderStatus				= @v_vchOrderStatus
										,@in_vchOrderType				= @v_vchOrderType
										,@in_vchLineNumber				= @v_vchLineNumber
										,@in_vchHUDF1					= @v_vchIBMSUDF1	
										,@in_vchHUDF2					= @v_vchIBMSUDF2	
										,@in_vchHUDF3					= @v_vchIBMSUDF3	
										,@in_vchHUDF4					= @v_vchIBMSUDF4	
										,@in_vchHUDF5					= @v_vchIBMSUDF5	
										,@in_vchHUDF6					= @v_vchIBMSUDF6	
										,@in_fltHUDF7					= @v_fltIBMSUDF7	
										,@in_fltHUDF8					= @v_fltIBMSUDF8	
										,@in_dtpHUDF9					= @v_dtpIBMSUDF9	
										,@in_dtpHUDF10					= @v_dtpIBMSUDF10	
										,@in_vchDUDF1					= @v_vchDUDF1
										,@in_vchDUDF2					= @v_vchDUDF2
										,@in_vchDUDF3					= @v_vchDUDF3
										,@in_vchDUDF4					= @v_vchDUDF4
										,@in_vchDUDF5					= @v_vchDUDF5
										,@in_vchDUDF6					= @v_vchDUDF6
										,@in_fltDUDF7					= @v_fltDUDF7
										,@in_fltDUDF8					= @v_fltDUDF8
										,@in_dtpDUDF9					= @v_dtpDUDF9
										,@in_dtpDUDF10					= @v_dtpDUDF10
										,@in_vchControlNumber			= @v_vchReceiveNumber
										,@in_vchControlValue1			= @v_vchReferenceNumber 
										,@in_vchHostRecordID			= @v_vchHostInterfaceID
										,@in_dtPostingDate				= @v_dtPostingDate
										,@in_vchCustomerCode			= @v_vchCustomerCode
										,@in_vchSupplierCode			= @v_vchSupplierCode
										,@in_vchErrorCode				= @out_ErrorCode OUTPUT
										,@in_vchMessage					= @out_ErrorMessage OUTPUT
					IF (@out_ErrorCode <> '0' and @out_ErrorCode <> '')
						BEGIN
							GOTO WRITE_PROC;
						END

					-- For Dashboard 
					EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'IN'
												   ,@in_vchTransType	= 'CLOSE'
												   ,@in_vchWhMasterID	= @in_vchWhMasterID
												   ,@in_vchOwnerID		= @v_vchOwnerID
												   ,@in_vchOwnerCode	= @v_vchOwnerCode
												   ,@in_vchLocationID	= @v_vchLocationID 
												   ,@in_vchItemMasterID	= @v_vchItemMasterID
												   ,@in_vchInvStatusID	= @v_vchInvStatusID
												   ,@in_vchToWhMasterID	= NULL
												   ,@in_vchToLocationID	= NULL
												   ,@in_vchToInvStatusID = NULL
												   ,@in_fltQuantity		= @v_fltReceiveQuantity
												   ,@in_vchUserID		= @in_vchCloseBy

					FETCH NEXT FROM ReceiveDetailCursor INTO @v_vchReceiveNumber,@v_vchInboundDetailID,@v_vchLineNumber,@v_vchItemMasterID,@v_vchItemNumber,@v_vchInvStatusID,@v_vchReceiveStatus,@v_fltReceiveQuantity,@v_vchUOM,@v_vchLocationID,@v_vchReceiveLocation,@v_vchParentLPN,@v_vchLPN
														,@v_vchLotNumber,@v_dtMfgDate,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate
														,@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_vchDUDF5,@v_vchDUDF6,@v_fltDUDF7,@v_fltDUDF8,@v_dtpDUDF9,@v_dtpDUDF10,@v_vchERPLocation,@v_fltERPQtyReceived,@v_vchERPUOM
				END
			CLOSE ReceiveDetailCursor
			DEALLOCATE ReceiveDetailCursor						
		
		CLOSE_ORDER:
			-- Execute bom process
			IF EXISTS (SELECT TOP 1 inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND bom_id IS NOT NULL)
				BEGIN
					EXEC [dbo].[usp_close_partial_receive_bom] @inbound_order_master_id = @in_vchInboundMasterID, @in_vchCloseBy = @in_vchCloseBy
				END

			UPDATE dbo.t_wms_receipt_header SET 
				receipt_status = 'CLOSE', close_by = @in_vchCloseBy, close_date = GETDATE()
			WHERE receipt_header_id = @in_vchReceiptHeaderID
					
		--Update Interfact to PENDING
		IF ISNULL(@v_vchHostInterfaceID,'') <> ''
			BEGIN
				UPDATE dbo.t_host_wms_receipt_conf_detail_export SET processing_status = 'PENDING' WHERE receipt_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
				UPDATE dbo.t_host_wms_receipt_conf_header_export SET processing_status = 'PENDING' WHERE receipt_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchCloseBy)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;
	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION; 

			IF CURSOR_STATUS('global','ReceiveDetailCursor')>=-1
				BEGIN
					CLOSE ReceiveDetailCursor;
					DEALLOCATE ReceiveDetailCursor;
				END
				
			DECLARE @v_vchProcessData1 NVARCHAR(255) = ''
			SET @v_vchProcessData1 = 'Tran Type ['+ @v_vchTranType +'] Sub Tran Type ['+ @v_vchSubTranType +']'
 			SET @v_dtProcessDateTime = GETDATE();
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDevice,
				@in_vchUserID = @in_vchCloseBy,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchInboundOrder,
				@in_vchData2 = @v_vchItemNumber,
				@in_vchData3 = @v_vchReceiveNumber,
				@in_vchData4 = @v_vchProcessData1,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END
	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','ReceiveDetailCursor')>=-1
			BEGIN
				CLOSE ReceiveDetailCursor;
				DEALLOCATE ReceiveDetailCursor;
			END

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		SET @v_dtProcessDateTime = GETDATE()
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchCloseBy,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @v_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchInboundOrder,
			@in_vchData2 = @v_vchItemNumber,
			@in_vchData3 = @v_vchReceiveNumber,
			@in_vchData4 = '',
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchCloseBy)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_partial_receive_bom]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_close_partial_receive_bom] 
	-- Add the parameters for the stored procedure here
	@inbound_order_master_id UNIQUEIDENTIFIER,	
	@in_vchCloseBy			 NVARCHAR(25)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	declare @inbound_order_detail_id UNIQUEIDENTIFIER
	declare @v_old_bom_quantity_receive float
	--declare @v_old_quantity_order float
	declare @v_old_quantity_receive float

	declare @v_bom_id int
	declare @v_bom_id_next int = -1
	declare @v_bom_detail_id int
	declare @v_item_bom_detail_quantity float
	declare @v_wh_item_master_id UNIQUEIDENTIFIER
	declare @v_bom_wh_master_id UNIQUEIDENTIFIER
	declare @v_bom_owner_id UNIQUEIDENTIFIER
	declare @v_bom_wh_item_master_id UNIQUEIDENTIFIER
	declare @v_bom_item_master_id UNIQUEIDENTIFIER
	declare @v_bom_item_number nvarchar(50)
	declare @v_quantity_order float
	declare @v_quantity_receive float
	declare @v_bom_quantity_receive float
	declare @v_bom_mother_quantity float
	declare @v_after_bom_quantity_receive float

	DECLARE CS_INBOUND CURSOR FOR
		SELECT bom_id
			, bom_detail_id
			, item_bom_detail_quantity
			, wh_item_master_id
			, bom_wh_master_id
			, bom_owner_id
			, bom_wh_item_master_id
			, bom_item_master_id
			, bom_item_number
			, quantity_order
			, quantity_receive
			, bom_quantity_receive
			, bom_mother_quantity
			, after_bom_quantity_receive
		FROM v_wms_inbound_calc_bom where inbound_order_master_id = @inbound_order_master_id
		ORDER BY bom_id, bom_detail_id asc
	OPEN CS_INBOUND          
	FETCH NEXT FROM CS_INBOUND
		INTO @v_bom_id
			, @v_bom_detail_id 
			, @v_item_bom_detail_quantity 
			, @v_wh_item_master_id 
			, @v_bom_wh_master_id 
			, @v_bom_owner_id 
			, @v_bom_wh_item_master_id 
			, @v_bom_item_master_id 
			, @v_bom_item_number 
			, @v_quantity_order 
			, @v_quantity_receive 
			, @v_bom_quantity_receive 
			, @v_bom_mother_quantity 
			, @v_after_bom_quantity_receive 
	WHILE @@FETCH_STATUS = 0
	BEGIN    
		-- BEGIN FOR LIST INSTRUCTION SET
		set @inbound_order_detail_id = NULL
		set @v_old_bom_quantity_receive = 0
		if isnull(@v_bom_mother_quantity,0) > 0
		begin
			do_next_line:
			select top 1 @inbound_order_detail_id = inbound_order_detail_id
				, @v_old_bom_quantity_receive = isnull(bom_quantity_receive,0)
				--, @v_old_quantity_order = isnull(quantity_order,0)
				, @v_old_quantity_receive = isnull(quantity_receive,0)
			from t_wms_inbound_detail 
			where inbound_order_master_id = @inbound_order_master_id
			and wh_item_master_id = @v_wh_item_master_id
			and bom_id = @v_bom_id
			and bom_detail_id = @v_bom_detail_id
			-- ดึงรายการที่ยังทำ bom ไม่ครบเท่านั้น
			--and isnull(bom_quantity_receive,0) < quantity_order
			and isnull(bom_quantity_receive,0) <  isnull(quantity_receive,0)
			order by line_number asc			

			-- นำค่าคำนวณ after_bom_quantity_receive + กับ bom qty เก่า ถ้าน้อยกว่าหรือเท่ากับให้ update ได้เลย			
			print 'bom_id '+convert(nvarchar,@v_bom_id)
			--if (@v_old_bom_quantity_receive + @v_after_bom_quantity_receive) <= @v_old_quantity_order
			if (@v_old_bom_quantity_receive + @v_after_bom_quantity_receive) <= @v_old_quantity_receive
			begin				
				if @v_bom_id <>	@v_bom_id_next
				begin
					print 'update t_wms_inventory_bom iA รวมแม่แล้วน้อยกว่าจำนวนที่รับ'
					update t_wms_inventory_bom
					   SET [quantity_receive] = (isnull([quantity_receive],0) + @v_bom_mother_quantity)				  
					 WHERE [wh_master_id] =  @v_bom_wh_master_id and [owner_id] = @v_bom_owner_id and [bom_id] = @v_bom_id		
					 --print 'rows count update '+convert(nvarchar,@@ROWCOUNT)			
					 if @@ROWCOUNT <= 0
					 begin
						INSERT INTO [dbo].[t_wms_inventory_bom]
								   ([wh_master_id]
								   ,[owner_id]
								   ,[bom_id]
								   ,[bom_wh_item_master_id]
								   ,[bom_item_master_id]
								   ,[bom_item_number]
								   ,[quantity_receive]
								   ,[quantity_ship]
								   ,[create_by]
								   ,[create_date])
							 VALUES
								   (@v_bom_wh_master_id --<wh_master_id, varchar(40),>
								   ,@v_bom_owner_id --<owner_id, varchar(40),>
								   ,@v_bom_id --<bom_id, varchar(40),>
								   ,@v_bom_wh_item_master_id --<bom_wh_item_master_id, varchar(40),>
								   ,@v_bom_item_master_id --<bom_item_master_id, varchar(40),>
								   ,@v_bom_item_number --<bom_item_number, nvarchar(50),>
								   ,@v_bom_mother_quantity --<quantity_receive, float,>
								   ,0 --<quantity_ship, float,>
								   ,@in_vchCloseBy --<create_by, nvarchar(25),>
								   ,getdate() --<create_date, datetime,>
								   )
								   print 'insert t_wms_inventory_bom iA รวมแม่แล้วน้อยกว่าจำนวนที่รับ'
					 end 
				end	
				print 'update t_wms_inbound_detail A แม่น้อยกว่าแผน '+convert(nvarchar,(@v_old_bom_quantity_receive + @v_after_bom_quantity_receive))
				update t_wms_inbound_detail
				set [bom_quantity_receive] = (@v_old_bom_quantity_receive + @v_after_bom_quantity_receive)
				where inbound_order_detail_id = @inbound_order_detail_id				
			end
			else
			begin				
				if (@v_old_quantity_receive - @v_old_bom_quantity_receive) <= @v_old_quantity_receive
				begin
					if @v_bom_id <>	@v_bom_id_next
					begin
						print 'update t_wms_inventory_bom iB แม่มากกว่าจำนวนที่รับ ทอนแม่แต่ละ row ที่รับ'
						update t_wms_inventory_bom
						SET [quantity_receive] = (isnull([quantity_receive],0) + @v_bom_mother_quantity)
						WHERE [wh_master_id] =  @v_bom_wh_master_id and [owner_id] = @v_bom_owner_id and [bom_id] = @v_bom_id						 
						 --print 'rows count update '+convert(nvarchar,@@ROWCOUNT)
						 if @@ROWCOUNT <= 0
						 begin
							INSERT INTO [dbo].[t_wms_inventory_bom]
									   ([wh_master_id]
									   ,[owner_id]
									   ,[bom_id]
									   ,[bom_wh_item_master_id]
									   ,[bom_item_master_id]
									   ,[bom_item_number]
									   ,[quantity_receive]
									   ,[quantity_ship]
									   ,[create_by]
									   ,[create_date])
								 VALUES
									   (@v_bom_wh_master_id --<wh_master_id, varchar(40),>
									   ,@v_bom_owner_id --<owner_id, varchar(40),>
									   ,@v_bom_id --<bom_id, varchar(40),>
									   ,@v_bom_wh_item_master_id --<bom_wh_item_master_id, varchar(40),>
									   ,@v_bom_item_master_id --<bom_item_master_id, varchar(40),>
									   ,@v_bom_item_number --<bom_item_number, nvarchar(50),>
									   ,@v_bom_mother_quantity --<quantity_receive, float,>
									   ,0 --<quantity_ship, float,>
									   ,@in_vchCloseBy --<create_by, nvarchar(25),>
									   ,getdate() --<create_date, datetime,>
									   )
									   print 'insert t_wms_inventory_bom iB แม่มากกว่าจำนวนที่รับ ทอนแม่แต่ละ row ที่รับ'
						 end 
					end		
					print 'update t_wms_inbound_detail B แม่มากกว่ากว่าแผน ทอนแม่แต่ละแผน '+convert(nvarchar,@v_old_quantity_receive)		
					update t_wms_inbound_detail					
					set [bom_quantity_receive] = @v_old_quantity_receive
					where inbound_order_detail_id = @inbound_order_detail_id
					-- เก็บค่าที่เหลือเพื่อไปเพิ่มในแถวถัดไปใน item เดียวกัน
					set @v_after_bom_quantity_receive = @v_after_bom_quantity_receive - (@v_old_quantity_receive - @v_old_bom_quantity_receive)
					print '@v_after_bom_quantity_receive B '+convert(nvarchar,@v_after_bom_quantity_receive)	
					set @v_bom_id_next = @v_bom_id
					-- ทำตัวถัดไป
					if @v_after_bom_quantity_receive > 0
					begin
						print 'do_next_line'
						goto do_next_line
					end								
				end
			end		
			set @v_bom_id_next = @v_bom_id	
			print 'Next line----------------------------'
		end		
		-- END FOR LIST INSTRUCTION SET            
		FETCH NEXT FROM CS_INBOUND
			INTO @v_bom_id 
			, @v_bom_detail_id 
			, @v_item_bom_detail_quantity 
			, @v_wh_item_master_id 
			, @v_bom_wh_master_id 
			, @v_bom_owner_id 
			, @v_bom_wh_item_master_id 
			, @v_bom_item_master_id 
			, @v_bom_item_number 
			, @v_quantity_order 
			, @v_quantity_receive 
			, @v_bom_quantity_receive 
			, @v_bom_mother_quantity 
			, @v_after_bom_quantity_receive 
	END
	CLOSE CS_INBOUND    
	DEALLOCATE CS_INBOUND


END
GO
/****** Object:  StoredProcedure [dbo].[usp_close_plan_update_status_for_job]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_close_plan_update_status_for_job]
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchCloseID			 VARCHAR(40)=NULL,
			@v_vchCountMasterID		 VARCHAR(40)=NULL,
			@v_vchUserID			 NVARCHAR(25)=NULL,	

			--For status mismatch
			@v_vchReconcileInvStatus NVARCHAR(50)=NULL,
			@v_vchInvStatus			 NVARCHAR(50)=NULL,
			@v_vchLocation			 NVARCHAR(50)=NULL,
			@v_vchSerialNumber		 NVARCHAR(100)=NULL,

			--For missing
			@v_vchMissCountPlanDetailID VARCHAR(40)=NULL,
			@v_vchMissLocation			NVARCHAR(50)=NULL,
			@v_vchMissSerialNumber		NVARCHAR(100)=NULL

	IF NOT EXISTS (SELECT close_id FROM t_wms_count_external_close_plan WHERE processing_status = 'INPROCESS')
		BEGIN
			PRINT 'NOT IN PROCESS'
			IF EXISTS (SELECT close_id FROM t_wms_count_external_close_plan WHERE processing_status = 'PENDING')
				BEGIN
					SELECT TOP 1 @v_vchCloseID = close_id
						,@v_vchCountMasterID = count_master_id
						,@v_vchUserID = create_by
					FROM t_wms_count_external_close_plan 
					WHERE processing_status = 'PENDING'

					--เริ่มต้น Process
					UPDATE t_wms_count_external_close_plan SET processing_status = 'INPROCESS' WHERE close_id = @v_vchCloseID

					-- 08/03/2016 22.03 : รายละเอียดมาจากพี่หนุ่ม
					-- get ข้อมูลจาก reconcile หาที่ status ไม่ตรงกับ inventory แล้วแก้ inventory ให้ status ตรงกับ reconcile
					-- 02/09/2016 [จากพี่ศิ] : จากการ Put Reconcile มีการปรับ Process ให้ Insert Unknown แต่ว่าไม่ต้องปรับ status ใน inventory 
					-- 05/10/2016 : กรณีตอน create plan = consignment และมีการ put used เมื่อมากเข้าส่วนนี้ทำให้มีการเปลี่ยนจาก used มาเป็น consignment
					BEGIN
						DECLARE reconcile_cursor CURSOR FOR
							SELECT rec.inv_status
								,tInv.inv_status
								,loc.location
								,rec.serial_number
							FROM t_wms_count_reconcile_external rec
							INNER JOIN t_wms_location loc on rec.location_id = loc.location_id
							INNER JOIN (SELECT inv.inventory_id 
											,inv.inventory_status_id
											,invStatus.inv_status
											,inv.location_id
											,invSN.serial_number
										FROM t_wms_inventory inv
										INNER JOIN t_wms_inventory_status invStatus on inv.inventory_status_id = invStatus.inventory_status_id
										LEFT JOIN (SELECT inventory_id
														,attribute_group_id
														,attribute_value AS serial_number
													FROM dbo.t_wms_inventory_attribute
													WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
													) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
										WHERE invStatus.inv_status <> 'Used'	
										) tInv ON rec.serial_number = tInv.serial_number AND rec.location_id = tInv.location_id
							WHERE rec.count_master_id = @v_vchCountMasterID
							AND rec.inv_status <> tInv.inv_status
							AND rec.inv_status <> 'Unknown'
						OPEN reconcile_cursor
						FETCH NEXT FROM reconcile_cursor INTO @v_vchReconcileInvStatus,@v_vchInvStatus,@v_vchLocation,@v_vchSerialNumber
						WHILE @@FETCH_STATUS = 0
							BEGIN
								EXEC usp_wms_change_status_by_serial 
											@in_vchApplicationID	= 'IOS',
											@in_vchLocation			= @v_vchLocation,	
											@in_vchSerialNumber		= @v_vchSerialNumber,
											@in_vchDestinationStatus = @v_vchReconcileInvStatus,
											@in_vchDevice			= 'IOS',
											@in_vchUserID			= @v_vchUserID,
											@in_vchTranType		 	= 'INV_STATUS_CHANGE',
											@in_vchSubTranType	 	= 'EXTERNAL_CHANGE',
											@in_vchTranTypeDesc     = 'Change Status',
											@out_vchErrorCode		= NULL,
											@out_vchErrorMsg		= NULL;	

									SET @v_vchReconcileInvStatus = NULL;
									SET @v_vchInvStatus = NULL;
									SET @v_vchLocation = NULL;
									SET @v_vchSerialNumber = NULL;
								FETCH NEXT FROM reconcile_cursor INTO @v_vchReconcileInvStatus,@v_vchInvStatus,@v_vchLocation,@v_vchSerialNumber
							END
						CLOSE reconcile_cursor                  	
						DEALLOCATE reconcile_cursor
					END

					-- Check ระหว่าง count plan กับ count reconcile ถ้า plan มี แล้ว reconcile ไม่มี ให้เปลี่ยน status เป็น missing แต่ถ้า ใน inventory เป็น used ต้องไม่เปลี่ยน
					BEGIN
						DECLARE missing_cursor CURSOR FOR
							SELECT dt.count_plan_detail_id
								, loc.location
								, dt.serial_number
							FROM t_wms_count_plan_detail_external dt
							LEFT JOIN t_wms_location loc on dt.location_id = loc.location_id
							LEFT JOIN t_wms_count_reconcile_external rec ON dt.count_master_id = rec.count_master_id AND dt.location_id = rec.location_id AND dt.serial_number = rec.serial_number
							LEFT JOIN (SELECT inv.inventory_id
											,invStatus.inv_status
											,inv.location_id
											,invSN.serial_number
										FROM t_wms_inventory inv
										LEFT JOIN t_wms_inventory_status invStatus on inv.inventory_status_id = invStatus.inventory_status_id
										LEFT JOIN (SELECT  inventory_id
														,attribute_group_id
														,attribute_value AS serial_number
													FROM dbo.t_wms_inventory_attribute
													WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
													) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
										) tInv ON dt.serial_number = tInv.serial_number AND dt.location_id = tInv.location_id
							WHERE  dt.count_master_id = @v_vchCountMasterID
							AND rec.count_reconcile_id IS NULL
							AND tInv.inv_status not in ('Used','Missing CSM')
						OPEN missing_cursor
						FETCH NEXT FROM missing_cursor INTO @v_vchMissCountPlanDetailID,@v_vchMissLocation,@v_vchMissSerialNumber		
						WHILE @@FETCH_STATUS = 0
							BEGIN
								EXEC usp_wms_change_status_by_serial 
											@in_vchApplicationID	= 'IOS',
											@in_vchLocation			= @v_vchMissLocation,	
											@in_vchSerialNumber		= @v_vchMissSerialNumber,
											@in_vchDestinationStatus = 'Missing CSM',
											@in_vchDevice			= 'IOS',
											@in_vchUserID			= @v_vchUserID,
											@in_vchTranType		 	= 'INV_STATUS_CHANGE',
											@in_vchSubTranType	 	= 'EXTERNAL_CHANGE',
											@in_vchTranTypeDesc     = 'Change Status',
											@out_vchErrorCode		= NULL,
											@out_vchErrorMsg		= NULL
											
									SET @v_vchMissLocation = NULL;
									SET @v_vchMissSerialNumber = NULL;
								FETCH NEXT FROM missing_cursor INTO @v_vchMissCountPlanDetailID,@v_vchMissLocation,@v_vchMissSerialNumber		
							END
						CLOSE missing_cursor                  	
						DEALLOCATE missing_cursor
					END

					UPDATE t_wms_count_external_close_plan SET processing_status = 'COMPLETE' WHERE close_id = @v_vchCloseID
				END
		END
END
GO
