CREATE PROCEDURE [dbo].[usp_com_control_ins]
(
	@v_vchFunctionID	varchar(40),
	@v_vchControlName	varchar(40),
	@v_vchControlCaption1	varchar(50),
	@v_vchControlCaption2	varchar(50),
	@v_vchControlCaption3	varchar(50),
	@v_vchControlType		varchar(40),
	@v_vchControlMessage	varchar(150),
	@v_vchControlSequence	int,
	@v_vchControlMexLength	int
)
AS
BEGIN

	INSERT INTO [dbo].[t_com_controls]
			   ([control_id]
			   ,[funtion_id]
			   ,[control_name]
			   ,[control_caption1]
			   ,[control_caption2]
			   ,[control_caption3]
			   ,[control_type]
			   ,[control_message]
			   ,[control_sequence]
			   ,[control_mexLength]
			   ,[is_active]
			   ,[create_by]
			   ,[create_date]
			   ,[update_by]
			   ,[update_date])
		 VALUES
			   (NEWID()
			   ,@v_vchFunctionID
			   ,@v_vchControlName
			   ,@v_vchControlCaption1
			   ,@v_vchControlCaption2
			   ,@v_vchControlCaption3
			   ,@v_vchControlType
			   ,@v_vchControlMessage
			   ,@v_vchControlSequence
			   ,@v_vchControlMexLength
			   ,'YES'
			   ,'OGA'
			   ,GETDATE()
			   ,'OGA'
			   ,GETDATE())
END


