/****** Object:  StoredProcedure [dbo].[usp_com_delete_inbound]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_com_delete_inbound]
	-- Add the parameters for the stored procedure here
	@in_vchInboundOrderMasterID		NVARCHaR(40),
	@out_vchCode					NVARCHaR(50) OUTPUT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE	@v_vchInboundMasterID	NVARCHAR(40)

    -- Insert statements for procedure here
	SELECT	@v_vchInboundMasterID = inbound_order_master_id 
	FROM	t_wms_inbound_master  
	WHERE	inbound_order_master_id = @in_vchInboundOrderMasterID
	AND		order_status = 'OPEN'

	if(@@ROWCOUNT > 0)
		BEGIN
			BEGIN TRY
					BEGIN TRANSACTION;

					DELETE FROM t_wms_inbound_comment 
					WHERE inbound_order_master_id = @v_vchInboundMasterID

					DELETE FROM t_wms_inbound_detail 
					WHERE inbound_order_master_id = @v_vchInboundMasterID

					DELETE FROM t_wms_inbound_master 
					WHERE	inbound_order_master_id = @v_vchInboundMasterID
					AND		order_status = 'OPEN'

					SET @out_vchCode = '0';

					COMMIT TRANSACTION;

			END TRY
			BEGIN CATCH
					SET @out_vchCode = '999';
					ROLLBACK TRANSACTION;
			END CATCH
		END

END



GO
