-- =============================================
CREATE PROCEDURE [dbo].[usp_com_delete_outbound]
	-- Add the parameters for the stored procedure here
	@in_vchOutboundOrderMasterID		NVARCHaR(40),
	@out_vchCode						NVARCHaR(50) OUTPUT

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE	@v_vchOutboundMasterID	NVARCHAR(40)

    -- Insert statements for procedure here
	SELECT	@v_vchOutboundMasterID = outbound_order_master_id 
	FROM	t_wms_outbound_master  
	WHERE	outbound_order_master_id = @in_vchOutboundOrderMasterID
	AND		order_status = 'PENDING'

	if(@@ROWCOUNT > 0)
		BEGIN
			BEGIN TRY
					BEGIN TRANSACTION;


					DELETE FROM t_wms_outbound_comment 
					WHERE outbound_order_master_id = @v_vchOutboundMasterID

					DELETE FROM t_wms_outbound_detail 
					WHERE outbound_order_master_id = @v_vchOutboundMasterID

					DELETE FROM t_wms_outbound_master 
					WHERE	outbound_order_master_id = @v_vchOutboundMasterID
					AND		order_status = 'PENDING'

					SET @out_vchCode = '0';

					COMMIT TRANSACTION;

			END TRY
			BEGIN CATCH
					SET @out_vchCode = '999';
					ROLLBACK TRANSACTION;
			END CATCH
		END

END



