/****** Object:  StoredProcedure [dbo].[usp_convert_varchar_to_datetime]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_convert_varchar_to_datetime]
(
	@in_vchApplicationID VARCHAR(40)	= NULL,
	@in_vchDate			NVARCHAR(20)	= NULL,
	@in_vchLocalID		VARCHAR(40)		= NULL,
	@out_dtValue		DATETIME		OUTPUT,
	@out_vchErrorCode	VARCHAR(50)		OUTPUT,
	@out_vchErrorMsg	NVARCHAR(500)	OUTPUT
)
AS
BEGIN

	DECLARE @v_vchFormatDate	VARCHAR(20)

	BEGIN TRY
		SELECT @v_vchFormatDate = value FROM t_wms_rule WHERE rule_code = 'RULE_FORMAT_SCAN_DATE'
		print @v_vchFormatDate
		IF @v_vchFormatDate = 'dd/MM/yy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 3) 
			END
		ELSE IF @v_vchFormatDate = 'dd/MM/yyyy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 103)
			END
		ELSE IF @v_vchFormatDate = 'dd.MM.yy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 4)  
			END
		ELSE IF @v_vchFormatDate = 'dd.MM.yyyy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 104)
			END
		ELSE IF @v_vchFormatDate = 'dd-MM-yy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 5)  
			END
		ELSE IF @v_vchFormatDate = 'dd-MM-yyyy'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 105)
			END
		--ELSE IF @v_vchFormatDate = 'ddMMyyyy'
		--	BEGIN
		--		-- Convert Varchar to datetime
		--		SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 103)
		--	END
		--ELSE IF @v_vchFormatDate = 'ddMMyy'
		--	BEGIN
		--		-- Convert Varchar to datetime
		--		SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 3)  
		--	END
		ELSE IF @v_vchFormatDate = 'yy.MM.dd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 2)  
			END
		ELSE IF @v_vchFormatDate = 'yyyy.MM.dd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 102)
			END
		ELSE IF @v_vchFormatDate = 'yy/MM/dd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 11) 
			END
		ELSE IF @v_vchFormatDate = 'yyyy/MM/dd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 111)
			END
		ELSE IF @v_vchFormatDate = 'yyMMdd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 12) 
			END
		ELSE IF @v_vchFormatDate = 'yyyyMMdd'
			BEGIN
				-- Convert Varchar to datetime
				SELECT @out_dtValue = CONVERT(DATETIME, @in_vchDate, 112)
			END
		ELSE
			BEGIN
				SET @out_vchErrorCode = 'NO-FORMAT'
				GOTO EXIT_LABEL
			END
	END TRY

	BEGIN CATCH
		SET @out_vchErrorCode = 'INVALID-FORMAT-DATE'
		GOTO EXIT_LABEL
	END CATCH

	-----------------------------------------------------------------------------------
	-- Exit the Process
	-----------------------------------------------------------------------------------	
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@v_vchFormatDate,'@param2','@param3','@param4','@param5')
END

GO
