-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_count_external_generate_running_order]
	-- Add the parameters for the stored procedure here
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
Begin Try

		Declare
			@v_vchFormatDate	VARCHAR(40),
			@v_vchFormatRule		NVARCHAR(10),

			@v_intRunning		INT,
			@v_vchRunningID		VARCHAR(40),

			@v_vchCountID VARCHAR(40)


		select @v_vchFormatDate = CONVERT(varchar,GETDATE(),112)
		Select @v_vchFormatRule = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_COUNT_EXTERNAL_ID_FOR_RUNNING'


		select @v_intRunning = CONVERT(int,SUBSTRING(MAX(count_id),9,LEN(MAX(count_id))-8))
		from t_wms_count_plan_master_external
		where LEFT(CONVERT(varchar,count_id,112),8) = @v_vchFormatDate

	 	SET @v_vchRunningID = RIGHT(@v_vchFormatRule+CONVERT(varchar,ISNULL(@v_intRunning,0) + 1),LEN(@v_vchFormatRule));
		SET @v_vchCountID = @v_vchFormatDate + @v_vchRunningID;
		
		Set @out_ErrorMessage = '0';
		Select @v_vchCountID AS count_id

	End Try
	Begin Catch
		SET @out_ErrorMessage = ERROR_MESSAGE();
	End Catch
	
	END


GO
