/****** Object:  StoredProcedure [dbo].[usp_count_lpn_counting]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_count_lpn_counting]
	@in_vchApplicationID  	NVARCHAR(40),  
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchCountMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchCountID			VARCHAR(50) = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		NVARCHAR(40) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL, 
 	@in_vchLocation			NVARCHAR(50) = NULL, 
	@in_fltCountQty			FLOAT = 0, 
	@out_vchErrorCode		NVARCHAR(50) output,
	@out_vchErrorMessage	NVARCHAR(500) output
AS
BEGIN 
	SET NOCOUNT ON; 
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_count_lpn_counting]', -- The name that uniquely tags this object.
			@v_dtProcessDateTime	DATETIME,
			@v_vchApplicationName	NVARCHAR(100),
			@v_vchCountStatus		NVARCHAR(10),
			@v_vchCountMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchBeginTrans		BIT = 0
    
	BEGIN TRY
		-- Check Warehouse
		IF NOT EXISTS (SELECT wh_master_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES')
			BEGIN
				SET @out_vchErrorCode = 'WAREHOUSE_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWhID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END
		
		-- Check Locaiton
		IF NOT EXISTS (SELECT location_id FROM t_wms_location where location_id = @in_vchLocationID AND is_active = 'YES')
			BEGIN
				SET @out_vchErrorCode = 'LOCATION_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLocation,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END  

		-- Check count master id  
		SELECT TOP 1 @v_vchCountMasterID = count_master_id 
			,@v_vchCountStatus = count_status
		FROM t_wms_count_plan_master
		WHERE count_id = @in_vchCountID
		AND wh_master_id = @in_vchWhMasterID
		IF(@v_vchCountMasterID IS NULL)  
			BEGIN
				SET @out_vchErrorCode = 'COUNT_ID_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END
		
		-- Check count status
		IF(@v_vchCountStatus = 'CLOSE')
			BEGIN
				SET @out_vchErrorCode = 'COUNT_IS_CLOSE';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END
		
		-- check count lpn quantity by location,parent lpn,item
		-- 1 count lpn quantity = input quantity.Insert inventory data into t_com_wms_count_reconcile
		-- 2 count lpn quantity <> input quantity.return @out_ErrorCode = 1(scan all lpn)
		IF ((SELECT COUNT (DISTINCT lpn) FROM t_wms_count_plan_detail where count_master_id = @in_vchCountMasterID AND location_id = @in_vchLocationID) <> @in_fltCountQty)
			BEGIN
				SET @out_vchErrorCode = 'QTY_INV_UNEQUAL_QTY_COUNT_PLAN';
				SELECT @out_vchErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
 		
		--Insert into Count Reconcile
		BEGIN
			BEGIN TRANSACTION;
				SET @v_vchBeginTrans = 1;
				SELECT wh_master_id
					, owner_id
					, location_id
					, wh_item_master_id
					, inventory_status_id
					, inv_status
					,(case when isnull(parent_lpn,'')	= '' then null else parent_lpn end) as parent_lpn
					,(case when isnull(lpn,'')			= '' then null else lpn end) as lpn
					,(case when isnull(lot_number,'')	= '' then null else lot_number end) as lot_number
					,(case when isnull(expiry_date,'')	= '' then null else expiry_date end) as expiry_date
					,(case when isnull(serial_number,'')= '' then null else serial_number end) as serial_number
					,(case when isnull(attribute1,'')	= '' then null else attribute1 end) as attribute1
					,(case when isnull(attribute2,'')	= '' then null else attribute2 end) as attribute2
					,(case when isnull(attribute3,'')	= '' then null else attribute3 end) as attribute3
					,(case when isnull(attribute4,'')	= '' then null else attribute4 end) as attribute4
					,(case when isnull(attribute5,'')	= '' then null else attribute5 end) as attribute5
					, SUM(quantity) AS quantity
				INTO #tInventory
				FROM v_wms_inventory_data_by_serial_mini 
				WHERE wh_master_id = @in_vchWhMasterID
				AND location_id = @in_vchLocationID
				GROUP BY wh_master_id, owner_id, location_id, wh_item_master_id, inventory_status_id, inv_status
					,(case when isnull(parent_lpn,'')	= '' then null else parent_lpn end)
					,(case when isnull(lpn,'')			= '' then null else lpn end)
					,(case when isnull(lot_number,'')	= '' then null else lot_number end)
					,(case when isnull(expiry_date,'')	= '' then null else expiry_date end)
					,(case when isnull(serial_number,'')= '' then null else serial_number end)
					,(case when isnull(attribute1,'')	= '' then null else attribute1 end)
					,(case when isnull(attribute2,'')	= '' then null else attribute2 end)
					,(case when isnull(attribute3,'')	= '' then null else attribute3 end)
					,(case when isnull(attribute4,'')	= '' then null else attribute4 end)
					,(case when isnull(attribute5,'')	= '' then null else attribute5 end)
					
				--Update Count Detail
				UPDATE t_wms_count_plan_detail SET count_qty = inv.quantity
				FROM t_wms_count_plan_detail countDT
				INNER JOIN t_wms_count_plan_master countMS ON countDT.count_master_id = countMS.count_master_id
				LEFT JOIN #tInventory inv ON inv.wh_master_id = countMS.wh_master_id
											AND inv.owner_id = countMS.owner_id 
											AND inv.location_id = countDT.location_id 
											AND ISNULL(inv.parent_lpn,'') = ISNULL(countDT.parent_lpn,'') 
											AND ISNULL(inv.lpn,'') = ISNULL(countDT.lpn,'') 
											AND inv.wh_item_master_id = countDT.wh_item_master_id 
											AND ISNULL(inv.lot_number,'') = ISNULL(countDT.lot,'')
											AND ISNULL(inv.[expiry_date],'') = ISNULL(countDT.expiry_date,'')
											AND ISNULL(inv.attribute1,'') = ISNULL(countDT.attribute1,'')
											AND ISNULL(inv.attribute2,'') = ISNULL(countDT.attribute2,'')
											AND ISNULL(inv.attribute3,'') = ISNULL(countDT.attribute3,'')
											AND ISNULL(inv.attribute4,'') = ISNULL(countDT.attribute4,'')
											AND ISNULL(inv.attribute5,'') = ISNULL(countDT.attribute5,'')
											AND ISNULL(inv.serial_number,'') = ISNULL(countDT.serial_number,'')
											AND inv.inv_status = countDT.inv_status 
				WHERE countMS.count_master_id = @v_vchCountMasterID

				--Insert Reconcile
				INSERT INTO [dbo].[t_wms_count_reconcile]
						([count_reconcile_id]
						,[count_master_id]
						,[location_id]
						,[wh_item_master_id]
						,[inv_status]
						,[parent_lpn]
						,[lpn]
						,[lot]
						,[expiry_date]
						,[serial_number]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[expect_qty]
						,[count_qty]
						,[device]
						,[create_date]
						,[create_by])
					SELECT NEWID()
						,@in_vchCountMasterID
						,location_id
						,wh_item_master_id
						,inv_status
						,parent_lpn
						,lpn
						,lot_number
						,expiry_date
						,serial_number
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,quantity
						,quantity 
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID
				FROM #tInventory

				IF OBJECT_ID('tempdb..#tInventory') IS NOT NULL
					DROP TABLE #tInventory

			COMMIT TRANSACTION;
			SET @out_vchErrorCode = '0';
			SELECT @out_vchErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
		 
		-----------------------------------------------------------------------------------
		--Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			
			IF OBJECT_ID('tempdb..#tInventory') IS NOT NULL
				DROP TABLE #tInventory

			SET @v_dtProcessDateTime = GETDATE(); 				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWhID,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @in_vchCountID,
				@in_vchData2 = @in_vchLocation,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMessage
		END 
	END TRY
	
	BEGIN CATCH
		
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
	 
		IF OBJECT_ID('tempdb..#tInventory') IS NOT NULL
			DROP TABLE #tInventory

		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMessage = ERROR_MESSAGE();
		SET @v_dtProcessDateTime = GETDATE(); 				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWhID,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchCountID,
			@in_vchData2 = @in_vchLocation,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_vchErrorCode,
			@in_vchMessage = @out_vchErrorMessage
	END CATCH
END




GO
/****** Object:  StoredProcedure [dbo].[usp_count_lpn_report]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[usp_count_lpn_report]
(
	@v_vchCountID		VARCHAR(50)
)
AS
BEGIN

	DECLARE @v_vchCountMasterID		UNIQUEIDENTIFIER
	SELECT @v_vchCountMasterID = count_master_id FROM t_wms_count_plan_master WHERE CONVERT(VARCHAR(36),count_master_id) = @v_vchCountID


	SELECT countDT.count_master_id
		,countDT.wh_item_master_id
		,loc.location
		,zone.zone
		,countDT.inv_status
		,countDT.parent_lpn
		,countDT.lpn
		,countDT.lot
		,countDT.expiry_date
		,SUM(ISNULL(countDT.stock_qty,0))	AS QTY
	INTO #tempPlan
	FROM t_wms_count_plan_detail countDT 
	LEFT JOIN t_wms_location loc on countDT.location_id = loc.location_id
	LEFT JOIN t_wms_zone_location zoneLoc on loc.location_id = zoneLoc.location_id
	LEFT JOIN t_wms_zone zone on zoneLoc.zone_id = zone.zone_id 
	GROUP BY  countDT.count_master_id
		,countDT.wh_item_master_id
		,loc.location
		,zone.zone
		,countDT.inv_status
		,countDT.parent_lpn
		,countDT.lpn
		,countDT.lot
		,countDT.expiry_date
		
	SELECT 
		 rec.count_master_id
		,rec.wh_item_master_id
		,loc.location
		,zone.zone
		,rec.inv_status
		,rec.parent_lpn
		,rec.lpn
		,rec.lot
		,rec.expiry_date
		,SUM(ISNULL(rec.expect_qty,0)) AS QTY
	INTO #tempRec
	FROM t_wms_count_reconcile rec
	LEFT JOIN t_wms_location loc on rec.location_id = loc.location_id
	LEFT JOIN t_wms_zone_location zoneLoc on  loc.location_id = zoneLoc.location_id
	LEFT JOIN t_wms_zone zone on zoneLoc.zone_id = zone.zone_id
 	GROUP BY
		 rec.count_master_id
		,rec.wh_item_master_id
		,loc.location
		,zone.zone
		,rec.inv_status
		,rec.parent_lpn
		,rec.lpn
		,rec.lot
		,rec.expiry_date

SELECT  t.count_master_id
		,countMS.count_id
		,countMS.count_status
		,countMS.count_plan_type
		,countMS.create_date
		,countMS.create_by
		,wh.wh_id
		,item.item_number
		,item.description
		,t.location
		,t.zone
		,t.inv_status
		,t.parent_lpn
		,t.lpn
		,t.lot
		,t.expiry_date
		,ISNULL(cPlan.QTY,0)		AS Plan_QTY
		,ISNULL(cRec.QTY,0)			AS Rec_QTY
		,ISNULL(cRec.QTY,0) - ISNULL(cPlan.QTY,0) AS diffQTY
		,uom.uom
	FROM (SELECT 
			 countPlan.count_master_id
			,countPlan.wh_item_master_id
			,countPlan.location
			,countPlan.zone
			,countPlan.inv_status
			,countPlan.parent_lpn
			,countPlan.lpn
			,countPlan.lot
			,countPlan.expiry_date
		 FROM #tempPlan countPlan
		 UNION 
		 SELECT 
			 countRec.count_master_id
			,countRec.wh_item_master_id
			,countRec.location
			,countRec.zone
			,countRec.inv_status
			,countRec.parent_lpn
			,countRec.lpn
			,countRec.lot
			,countRec.expiry_date
		 FROM #tempRec countRec) t
	LEFT JOIN t_wms_count_plan_master countMS ON t.count_master_id = countMS.count_master_id
	LEFT JOIN t_wms_wh wh ON countMS.wh_master_id = wh.wh_master_id
	LEFT JOIN t_wms_wh_item whItem ON t.wh_item_master_id = whItem.wh_item_master_id
	LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_uom uom on item.item_master_id = uom.item_master_id AND primary_uom = 'YES'
	LEFT JOIN (SELECT count_master_id
					,wh_item_master_id
					,location
					,zone
					,inv_status
					,parent_lpn
					,lpn
					,lot
					,expiry_date
					,QTY
			   FROM #tempPlan
			  ) cPlan ON t.count_master_id = cPlan.count_master_id
					  AND t.wh_item_master_id = cPlan.wh_item_master_id
					  AND t.location = cPlan.location
					  AND t.zone = cPlan.zone
					  AND t.inv_status = cPlan.inv_status 
					  AND ISNULL(t.parent_lpn,'') = ISNULL(cPlan.parent_lpn,'')
					  AND ISNULL(t.lpn,'') = ISNULL(cPlan.lpn,'')
					  AND ISNULL(t.lot,'') = ISNULL(cPlan.lot,'')
					  AND ISNULL(t.expiry_date,'') = ISNULL(cPlan.expiry_date,'')
	LEFT JOIN (SELECT count_master_id
					,wh_item_master_id
					,location
					,zone
					,inv_status
					,parent_lpn
					,lpn
					,lot
					,expiry_date
					,QTY
			   FROM #tempRec
			  ) cRec ON t.count_master_id = cRec.count_master_id
					  AND t.wh_item_master_id = cRec.wh_item_master_id
					  AND t.location = cRec.location
					  AND t.zone = cRec.zone
					  AND t.inv_status = cRec.inv_status
					  AND ISNULL(t.parent_lpn,'') = ISNULL(cRec.parent_lpn,'')
					  AND ISNULL(t.lpn,'') = ISNULL(cRec.lpn,'')
					  AND ISNULL(t.lot,'') = ISNULL(cRec.lot,'')
					  AND ISNULL(t.expiry_date,'') = ISNULL(cRec.expiry_date,'')
WHERE t.count_master_id = @v_vchCountMasterID 

drop table #tempRec
drop table #tempPlan
END


GO
/****** Object:  StoredProcedure [dbo].[usp_create_count_plan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_create_count_plan]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchCountID			NVARCHAR(50),
	@in_vchCountType		NVARCHAR(50),
	@in_vchDescription		NVARCHAR(200),
	@in_vchUserID			NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
	
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @v_vchWarehouse	NVARCHAR(50) = NULL
	DECLARE @v_vchCountMasterID UNIQUEIDENTIFIER = NULL
	
	BEGIN TRY
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (@v_vchWarehouse IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		IF NOT EXISTS (SELECT owner_id FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES')
			BEGIN
				SET @out_ErrorCode = 'INFO-OWNER-NOT-EXIST';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				RETURN;
			END 

		IF EXISTS(SELECT count_master_id FROM t_wms_count_plan_master WHERE count_id = @in_vchCountID AND wh_master_id = @in_vchWhMasterID)
			BEGIN
				SELECT 'Count ID [' + @in_vchCountID + '] is already exist' AS item_number,'' AS location
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'COUNT_ID_ALREADY_EXIST',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		ELSE
			BEGIN
	
			BEGIN TRANSACTION;
		
				SET @v_vchCountMasterID = NEWID();
				INSERT INTO t_wms_count_plan_master
					(count_master_id
					, wh_master_id
					, count_id
					, owner_id
					, count_status
					, [description]
					, count_generate_method
					, count_plan_type
					, create_date
					, create_by)
				VALUES
					( @v_vchCountMasterID
					, @in_vchWhMasterID
					, @in_vchCountID
					, @in_vchOwnerID
					, 'OPEN'
					, @in_vchDescription
					, 'MANUAL'
					, @in_vchCountType
					, GETDATE()
					, @in_vchUserID)

				;WITH tCount AS
				(
					SELECT wh_item_master_id
						,location_id
						,inv_status
						,(CASE ISNULL(parent_lpn,'') WHEN '' THEN NULL ELSE parent_lpn END) AS parent_lpn
						,(CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END) AS lpn
						,(CASE ISNULL(lot,'') WHEN '' THEN NULL ELSE lot END) AS lot
						,(CASE ISNULL(expiry_date,'') WHEN '' THEN NULL ELSE expiry_date END) AS expiry_date
						,(CASE ISNULL(serial_number,'') WHEN '' THEN NULL ELSE serial_number END) AS serial_number
						,(CASE ISNULL(attribute1,'') WHEN '' THEN NULL ELSE attribute1 END) AS attribute1
						,(CASE ISNULL(attribute2,'') WHEN '' THEN NULL ELSE attribute2 END) AS attribute2
						,(CASE ISNULL(attribute3,'') WHEN '' THEN NULL ELSE attribute3 END) AS attribute3
						,(CASE ISNULL(attribute4,'') WHEN '' THEN NULL ELSE attribute4 END) AS attribute4
						,(CASE ISNULL(attribute5,'') WHEN '' THEN NULL ELSE attribute5 END) AS attribute5
						,stock_qty
						,create_by
					FROM t_wms_count_temporary
					WHERE create_by = @in_vchUserID 
					AND ISNULL(serial_number,'') = ''
					UNION 
					SELECT DISTINCT wh_item_master_id
						,location_id
						,inv_status
						,(CASE ISNULL(parent_lpn,'') WHEN '' THEN NULL ELSE parent_lpn END) AS parent_lpn
						,(CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END) AS lpn
						,(CASE ISNULL(lot,'') WHEN '' THEN NULL ELSE lot END) AS lot
						,(CASE ISNULL(expiry_date,'') WHEN '' THEN NULL ELSE expiry_date END) AS expiry_date
						,(CASE ISNULL(serial_number,'') WHEN '' THEN NULL ELSE serial_number END) AS serial_number
						,(CASE ISNULL(attribute1,'') WHEN '' THEN NULL ELSE attribute1 END) AS attribute1
						,(CASE ISNULL(attribute2,'') WHEN '' THEN NULL ELSE attribute2 END) AS attribute2
						,(CASE ISNULL(attribute3,'') WHEN '' THEN NULL ELSE attribute3 END) AS attribute3
						,(CASE ISNULL(attribute4,'') WHEN '' THEN NULL ELSE attribute4 END) AS attribute4
						,(CASE ISNULL(attribute5,'') WHEN '' THEN NULL ELSE attribute5 END) AS attribute5
						,stock_qty
						,create_by
					FROM t_wms_count_temporary
					WHERE create_by = @in_vchUserID 
					AND ISNULL(serial_number,'') <> ''
				)
				INSERT INTO t_wms_count_plan_detail
					( count_master_id
						,wh_item_master_id
						,location_id
						,inv_status
						,parent_lpn
						,lpn
						,lot
						,expiry_date
						,serial_number
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,stock_qty
						,create_date
						,create_by)
					SELECT @v_vchCountMasterID
						,wh_item_master_id
						,location_id
						,inv_status
						,(CASE ISNULL(parent_lpn,'') WHEN '' THEN NULL ELSE parent_lpn END) 
						,(CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END) 
						,(CASE ISNULL(lot,'') WHEN '' THEN NULL ELSE lot END) 
						,(CASE ISNULL(expiry_date,'') WHEN '' THEN NULL ELSE expiry_date END)
						,(CASE ISNULL(serial_number,'') WHEN '' THEN NULL ELSE serial_number END)
						,(CASE ISNULL(attribute1,'') WHEN '' THEN NULL ELSE attribute1 END) 
						,(CASE ISNULL(attribute2,'') WHEN '' THEN NULL ELSE attribute2 END) 
						,(CASE ISNULL(attribute3,'') WHEN '' THEN NULL ELSE attribute3 END) 
						,(CASE ISNULL(attribute4,'') WHEN '' THEN NULL ELSE attribute4 END) 
						,(CASE ISNULL(attribute5,'') WHEN '' THEN NULL ELSE attribute5 END) 
						,sum(stock_qty)
						,GETDATE()
						,@in_vchUserID 
					FROM t_wms_count_temporary
					WHERE create_by = @in_vchUserID
					GROUP BY wh_item_master_id
						,location_id
						,inv_status
						,(CASE ISNULL(parent_lpn,'') WHEN '' THEN NULL ELSE parent_lpn END) 
						,(CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END) 
						,(CASE ISNULL(lot,'') WHEN '' THEN NULL ELSE lot END) 
						,(CASE ISNULL(expiry_date,'') WHEN '' THEN NULL ELSE expiry_date END)
						,(CASE ISNULL(serial_number,'') WHEN '' THEN NULL ELSE serial_number END)
						,(CASE ISNULL(attribute1,'') WHEN '' THEN NULL ELSE attribute1 END) 
						,(CASE ISNULL(attribute2,'') WHEN '' THEN NULL ELSE attribute2 END) 
						,(CASE ISNULL(attribute3,'') WHEN '' THEN NULL ELSE attribute3 END) 
						,(CASE ISNULL(attribute4,'') WHEN '' THEN NULL ELSE attribute4 END) 
						,(CASE ISNULL(attribute5,'') WHEN '' THEN NULL ELSE attribute5 END) 

				DELETE FROM t_wms_count_temporary WHERE create_by = @in_vchUserID

				SET @out_ErrorCode = '0';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

				COMMIT TRANSACTION
			END
	END TRY
	BEGIN CATCH

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;

		DECLARE @v_dtProcessDateTime DATETIME = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = 'UNALLOCATE',
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = 'usp_create_count_plan',
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchCountID,
			@in_vchData2 = NULL,
			@in_vchData3 = @out_ErrorCode,
			@in_vchData4 = @out_ErrorMessage,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END



GO
/****** Object:  StoredProcedure [dbo].[usp_create_count_plan_by_movement]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_create_count_plan_by_movement]
	@in_vchApplicationID	VARCHAR(40),
	@in_dtFromTranNow		DATE,
	@in_dtToTranNow			DATE, 
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(250) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_vchCountMasterID	VARCHAR(40) = NULL
		DECLARE @v_vchCountID		NVARCHAR(50)= NULL
		DECLARE @v_vchWhMasterID	VARCHAR(40) = NULL
		DECLARE @v_vchOwnerID		VARCHAR(40) = NULL
		DECLARE @v_vchFormatDate	VARCHAR(40) = NULL
		DECLARE @v_vchFormatRule	NVARCHAR(10) = NULL
		DECLARE @v_intRunning		INT = NULL
		DECLARE @v_vchRunningID		VARCHAR(40) = NULL 
		SET @v_vchFormatDate = CONVERT(VARCHAR,GETDATE(),112);
		SELECT @v_vchFormatRule = ISNULL(value,'0') FROM t_wms_rule WHERE rule_code = 'FORMAT_COUNT_ID_FOR_RUNNING' AND is_active = 'YES'
	
	BEGIN TRY
		SELECT tran_type
			,sub_tran_type
			,description
			,warehouse
			,to_warehouse
			,owner
			,to_owner
			,location
			,to_location
			,parent_lpn
			,after_parent_lpn
			,lpn
			,after_lpn
			,item_number
			,quantity
			,quantity_uom
			,lot_number
			,after_lot_number
			,expiry_date
			,after_expiry_date
			,serial_number
			,attribute1
			,after_attribute1
			,attribute2
			,after_attribute2
			,attribute3
			,after_attribute3
			,attribute4
			,after_attribute4
			,attribute5
			,after_attribute5
			,status
			,after_status
			,order_number
			,create_by
			,create_date
		INTO #tLog
		FROM t_com_tran_log
		WHERE tran_type IN ('BLIND_PICK','OO_PICK','BLIND_RECEIPT','IO_RECEIPT','INV_ADJUST','INV_MOVE')
		AND sub_tran_type IN ('SALES_ORDER','RECEIPT','ADJUST_IN','ADJUST_IN_TO_SAP','ADJUST_OUT','ADJUST_OUT_TO_SAP','INV_ADJUST','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_SOURCE')
		AND (CONVERT(DATE,create_date) >= @in_dtFromTranNow AND CONVERT(DATE,create_date) <= @in_dtToTranNow)
 
		;WITH tLogAllCTE AS
			(
				SELECT to_warehouse		AS wh_id
					,to_owner			AS owner_code
					,to_location		AS location
					,after_parent_lpn	AS parent_lpn
					,after_lpn			AS lpn
					,item_number
					,after_lot_number	AS lot_number
					,after_expiry_date	AS expiry_date
					,after_attribute1	AS attribute1
					,after_attribute2	AS attribute2
					,after_attribute3	AS attribute3
					,after_attribute4	AS attribute4
					,after_attribute5	AS attribute5
					,serial_number
					,after_status		AS inv_status
				FROM #tLog
				WHERE tran_type IN ('BLIND_RECEIPT','IO_RECEIPT','INV_ADJUST')
				AND sub_tran_type IN ('RECEIPT','ADJUST_IN','ADJUST_IN_TO_SAP')
			UNION
				SELECT warehouse	AS wh_id
					,owner			AS owner_code
					,location		AS location
					,parent_lpn		AS parent_lpn
					,lpn			AS lpn
					,item_number
					,lot_number		AS lot_number
					,expiry_date	AS expiry_date
					,attribute1		AS attribute1
					,attribute2		AS attribute2
					,attribute3		AS attribute3
					,attribute4		AS attribute4
					,attribute5		AS attribute5
					,serial_number
					,status			AS inv_status
				FROM #tLog
				WHERE tran_type IN ('BLIND_PICK','OO_PICK','INV_ADJUST')
				AND sub_tran_type IN ('SALES_ORDER','ADJUST_OUT','ADJUST_OUT_TO_SAP')
			UNION
				--Location ต้นทาง
				--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
				SELECT warehouse	AS wh_id
					,owner			AS owner_code
					,location		AS location
					,parent_lpn		AS parent_lpn
					,lpn			AS lpn
					,item_number
					,lot_number		AS lot_number
					,expiry_date	AS expiry_date
					,attribute1		AS attribute1
					,attribute2		AS attribute2
					,attribute3		AS attribute3
					,attribute4		AS attribute4
					,attribute5		AS attribute5
					,serial_number
					,status			AS inv_status
				FROM #tLog
				WHERE tran_type IN ('INV_MOVE','OO_PICK','INV_ADJUST')
				AND sub_tran_type IN ('MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_SOURCE')
			UNION
				--Location ปลายทาง
				--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
				SELECT to_warehouse		AS wh_id
					,to_owner			AS owner_code
					,to_location		AS location
					,after_parent_lpn	AS parent_lpn
					,after_lpn			AS lpn
					,item_number
					,after_lot_number	AS lot_number
					,after_expiry_date	AS expiry_date
					,after_attribute1	AS attribute1
					,after_attribute2	AS attribute2
					,after_attribute3	AS attribute3
					,after_attribute4	AS attribute4
					,after_attribute5	AS attribute5
					,serial_number
					,after_status		AS inv_status
				FROM #tLog
				WHERE tran_type IN ('INV_MOVE','OO_PICK','INV_ADJUST')
				AND sub_tran_type IN ('MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_SOURCE')
			)
		, tLog AS 
			(
				SELECT DISTINCT wh.wh_master_id
					,wh.wh_id
					,own.owner_id
					,own.owner_code
					,loc.location_id
					,loc.location
					,ISNULL(t.parent_lpn,'') AS parent_lpn
					,ISNULL((CASE WHEN loc.lpn_controlled = 'NO' THEN NULL ELSE t.lpn END),'') AS lpn
					,whItem.wh_item_master_id
					,item.item_master_id
					,t.item_number
					,ISNULL(t.lot_number,'') AS lot_number
					,(CASE WHEN item.expiry_date_control = 'NONE' THEN NULL ELSE CONVERT(VARCHAR,t.expiry_date,112) END) AS expiry_date
					,ISNULL(t.attribute1,'') AS attribute1
					,ISNULL(t.attribute2,'') AS attribute2
					,ISNULL(t.attribute3,'') AS attribute3
					,ISNULL(t.attribute4,'') AS attribute4
					,ISNULL(t.attribute5,'') AS attribute5
					,ISNULL(t.serial_number,'') AS serial_number
					,invStatus.inventory_status_id
					,invStatus.inv_status 
				FROM tLogAllCTE t
				INNER JOIN t_wms_wh wh ON t.wh_id = wh.wh_id
				INNER JOIN t_wms_owner own ON t.owner_code = own.owner_code
				INNER JOIN t_wms_location loc ON t.location = loc.location AND loc.wh_master_id = wh.wh_master_id
				INNER JOIN t_wms_inventory_status invStatus ON t.inv_status = invStatus.inv_status
				INNER JOIN t_wms_item item ON t.item_number = item.item_number
				INNER JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
			)
		, tInventory AS
			(
				SELECT wh_master_id
					, wh_id 
					, owner_id
					, owner_code 
					, location_id
					, location
					, ISNULL(parent_lpn,'') AS parent_lpn
					, ISNULL(lpn,'') AS lpn
					, wh_item_master_id
					, item_master_id
					, item_number
					, lot_number
					, expiry_date
					, attribute1
					, attribute2
					, attribute3
					, attribute4
					, attribute5
					, serial_number
					, inventory_status_id
					, inv_status
					, SUM(quantity) quantity
				FROM v_wms_inventory_data_by_serial_count_movement
				WHERE loc_type NOT IN ('DOOR','FORK','STG')
				GROUP BY wh_master_id,wh_id,owner_id,owner_code,location_id,location,ISNULL(parent_lpn,''),ISNULL(lpn,''),wh_item_master_id,item_master_id,item_number,lot_number,expiry_date,attribute1,attribute2,attribute3,attribute4,attribute5,serial_number,inventory_status_id,inv_status
			)
			SELECT tPlan.wh_master_id 
				,tPlan.wh_id
				,tPlan.owner_id
				,tPlan.owner_code
				,tPlan.location_id
				,tPlan.location
				,tPlan.parent_lpn
				,tPlan.lpn
				,tPlan.wh_item_master_id
				,tPlan.item_number
				,tPlan.quantity
				,tPlan.lot_number
				,tPlan.expiry_date
				,tPlan.attribute1
				,tPlan.attribute2
				,tPlan.attribute3
				,tPlan.attribute4
				,tPlan.attribute5
				,tPlan.serial_number
				,tPlan.inv_status
				,tPlan.inventory_status_id
			INTO #tCountPlan
			FROM (SELECT  tLog.wh_master_id
						, tLog.wh_id 
						, tLog.owner_id
						, tLog.owner_code 
						, tLog.location_id
						, tLog.location
						, tLog.parent_lpn
						, tLog.lpn
						, tLog.wh_item_master_id
						, tLog.item_master_id
						, tLog.item_number
						, tLog.lot_number
						, tLog.expiry_date
						, tLog.attribute1
						, tLog.attribute2
						, tLog.attribute3
						, tLog.attribute4
						, tLog.attribute5
						, tLog.serial_number
						, tLog.inventory_status_id
						, tLog.inv_status
						, ISNULL(inv.quantity,0) AS quantity
					FROM  tLog
					LEFT JOIN tInventory inv ON inv.wh_master_id = tLog.wh_master_id
											AND inv.owner_id = tLog.owner_id
											AND inv.location_id = tLog.location_id
											AND inv.wh_item_master_id = tLog.wh_item_master_id
											AND ISNULL(inv.parent_lpn,'') = ISNULL(tLog.parent_lpn,'')
											AND ISNULL(inv.lpn,'') = ISNULL(tLog.lpn,'')
											AND ISNULL(inv.lot_number,'') = ISNULL(tLog.lot_number,'')
											AND ISNULL(inv.expiry_date,'') = ISNULL(tLog.expiry_date,'')
											AND ISNULL(inv.attribute1,'') = ISNULL(tLog.attribute1,'')
											AND ISNULL(inv.attribute2,'') = ISNULL(tLog.attribute2,'')
											AND ISNULL(inv.attribute3,'') = ISNULL(tLog.attribute3,'')
											AND ISNULL(inv.attribute4,'') = ISNULL(tLog.attribute4,'')
											AND ISNULL(inv.attribute5,'') = ISNULL(tLog.attribute5,'')
											AND ISNULL(inv.serial_number,'') = ISNULL(tLog.serial_number,'')
											AND ISNULL(inv.inventory_status_id,'') = ISNULL(tLog.inventory_status_id,'')
				  ) tPlan
	
		BEGIN TRANSACTION
			DECLARE CountMS_Cursor CURSOR FOR
				SELECT DISTINCT wh_master_id
					,owner_id
				FROM #tCountPlan 
			OPEN CountMS_Cursor 
			FETCH NEXT FROM CountMS_Cursor INTO @v_vchWhMasterID, @v_vchOwnerID
	
			WHILE @@FETCH_STATUS = 0
			BEGIN 
				SET @v_intRunning = 0;
				SET @v_vchRunningID = ''
				SET @v_vchCountID = ''
		
				--GET MAX COUNT ID
				SELECT @v_intRunning = CONVERT(INT,SUBSTRING(MAX(count_id),9,LEN(MAX(count_id))-8)) 
				FROM t_wms_count_plan_master
				WHERE LEFT(CONVERT(VARCHAR,count_id,112),8) = @v_vchFormatDate

	 			SET @v_vchRunningID = RIGHT(@v_vchFormatRule + CONVERT(VARCHAR,ISNULL(@v_intRunning,0) + 1), LEN(@v_vchFormatRule));
				SET @v_vchCountID = @v_vchFormatDate + @v_vchRunningID;
			
				SET @v_vchCountMasterID = NEWID();
				INSERT INTO [dbo].[t_wms_count_plan_master]
						   ([count_master_id]
						   ,[wh_master_id]
						   ,[count_id]
						   ,[count_status] 
						   ,[description]
						   ,[count_generate_method]
						   ,[count_plan_type]
						   ,[create_date]
						   ,[create_by] 
						   ,[owner_id])
					 VALUES
						   (@v_vchCountMasterID
						   ,@v_vchWhMasterID
						   ,@v_vchCountID
						   ,'OPEN'
						   ,'Count plan from movement.'
						   ,'MANUAL'
						   ,'CYCLE'
						   ,GETDATE()
						   ,@in_vchUserID
						   ,@v_vchOwnerID)
						
				INSERT INTO [dbo].[t_wms_count_plan_detail]
						   ([count_plan_detail_id]
						   ,[count_master_id]
						   ,[location_id]
						   ,[wh_item_master_id]
						   ,[inv_status]
						   ,[parent_lpn]
						   ,[lpn]
						   ,[lot]
						   ,[expiry_date]
						   ,[serial_number]
						   ,[attribute1]
						   ,[attribute2]
						   ,[attribute3]
						   ,[attribute4]
						   ,[attribute5]
						   ,[stock_qty] 
						   ,[create_by]
						   ,[create_date])
					 SELECT NEWID()
						   ,@v_vchCountMasterID
						   ,location_id
						   ,wh_item_master_id 
						   ,inv_status 
						   ,CASE WHEN ISNULL(parent_lpn,'') = '' THEN NULL ELSE  ISNULL(parent_lpn,'') END
						   ,CASE WHEN ISNULL(lpn,'') = '' THEN NULL ELSE  ISNULL(lpn,'') END
						   ,CASE WHEN ISNULL(lot_number,'') = '' THEN NULL ELSE  ISNULL(lot_number,'') END
						   ,CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE  ISNULL(expiry_date,'') END
						   ,CASE WHEN ISNULL(serial_number,'') = '' THEN NULL ELSE  ISNULL(serial_number,'') END 
						   ,CASE WHEN ISNULL(attribute1,'') = '' THEN NULL ELSE  ISNULL(attribute1,'') END
						   ,CASE WHEN ISNULL(attribute2,'') = '' THEN NULL ELSE  ISNULL(attribute2,'') END
						   ,CASE WHEN ISNULL(attribute3,'') = '' THEN NULL ELSE  ISNULL(attribute3,'') END
						   ,CASE WHEN ISNULL(attribute4,'') = '' THEN NULL ELSE  ISNULL(attribute4,'') END
						   ,CASE WHEN ISNULL(attribute5,'') = '' THEN NULL ELSE  ISNULL(attribute5,'') END
						   ,quantity 
						   ,@in_vchUserID
						   ,GETDATE()
					FROM #tCountPlan 
					WHERE wh_master_id = @v_vchWhMasterID
					AND owner_id = @v_vchOwnerID

				FETCH NEXT FROM CountMS_Cursor INTO @v_vchWhMasterID, @v_vchOwnerID
			END	
			CLOSE CountMS_Cursor                  	
			DEALLOCATE CountMS_Cursor
		
		COMMIT TRANSACTION;

		SELECT COUNT(*) FROM #tCountPlan
		IF OBJECT_ID('tempdb..#tCountPlan') IS NOT NULL
			DROP TABLE #tCountPlan
		IF OBJECT_ID('tempdb..#tLog') IS NOT NULL
			DROP TABLE #tLog

		SET @out_ErrorCode = 0;
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

	END TRY
	BEGIN CATCH
		
		ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','CountMS_Cursor')>=-1
			BEGIN
				CLOSE CountMS_Cursor;
				DEALLOCATE CountMS_Cursor;
			END 
		
		IF OBJECT_ID('tempdb..#tCountPlan') IS NOT NULL
			DROP TABLE #tCountPlan
		IF OBJECT_ID('tempdb..#tLog') IS NOT NULL
			DROP TABLE #tLog 
		
		SET @out_ErrorCode =  CONVERT(VARCHAR(50),ERROR_NUMBER())
		SET @out_ErrorMessage = SUBSTRING(ERROR_MESSAGE(),0,250);
		
	END CATCH
END


