/****** Object:  StoredProcedure [dbo].[usp_create_count_plan_by_wh]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_create_count_plan_by_wh]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchCountID			NVARCHAR(50),
	@in_vchCountType		NVARCHAR(50),
	@in_vchDescription		NVARCHAR(200),
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
	
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @in_vchWarehouse	NVARCHAR(50) = NULL
	DECLARE @v_vchCountMasterID UNIQUEIDENTIFIER = NULL
	
	BEGIN TRY 
		SELECT @in_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (@in_vchWarehouse IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		
		IF NOT EXISTS (SELECT owner_id FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES')
			BEGIN
				SET @out_ErrorCode = 'INFO-OWNER-NOT-EXIST';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		IF EXISTS(SELECT count_master_id FROM t_wms_count_plan_master WHERE count_id = @in_vchCountID AND wh_master_id = @in_vchWhMasterID)
			BEGIN
				SELECT 'Count ID [' + @in_vchCountID + '] is already exist' as item_number,'' as location
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'COUNT_ID_ALREADY_EXIST',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		ELSE
			BEGIN

				BEGIN TRANSACTION;
		
					SET @v_vchCountMasterID = NEWID();
					INSERT INTO t_wms_count_plan_master
						(count_master_id
						,wh_master_id
						,count_id
						,owner_id
						,count_status
						,[description]
						,count_generate_method
						,count_plan_type
						,create_date
						,create_by)
					VALUES
						(@v_vchCountMasterID
						,@in_vchWhMasterID
						,@in_vchCountID
						,@in_vchOwnerID
						,'OPEN'
						,@in_vchDescription
						,'MANUAL'
						,@in_vchCountType
						,GETDATE()
						,@in_vchUserID)

					INSERT INTO t_wms_count_plan_detail
						(count_master_id
						 ,wh_item_master_id
						 ,location_id
						 ,inv_status
						 ,parent_lpn
						 ,lpn
						 ,lot
						 ,expiry_date
						 ,serial_number
						 ,attribute1
						 ,attribute2
						 ,attribute3
						 ,attribute4
						 ,attribute5
						 ,stock_qty
						 ,create_date
						 ,create_by)
					SELECT @v_vchCountMasterID
						,inv.wh_item_master_id
						,inv.location_id
						,inv.inv_status
						,(case when isnull(inv.parent_lpn,'')	= '' then null else inv.parent_lpn end)
						,(case when isnull(inv.lpn,'')			= '' then null else inv.lpn end)
						,(case when isnull(inv.lot_number,'')	= '' then null else inv.lot_number end)
						,(case when isnull(inv.expiry_date,'')	= '' then null else inv.expiry_date end)
						,(case when isnull(inv.serial_number,'')= '' then null else inv.serial_number end)
						,(case when isnull(inv.attribute1,'')	= '' then null else inv.attribute1 end)
						,(case when isnull(inv.attribute2,'')	= '' then null else inv.attribute2 end)
						,(case when isnull(inv.attribute3,'')	= '' then null else inv.attribute3 end)
						,(case when isnull(inv.attribute4,'')	= '' then null else inv.attribute4 end)
						,(case when isnull(inv.attribute5,'')	= '' then null else inv.attribute5 end)
						,SUM(inv.quantity)
						,GETDATE()
						,@in_vchUserID 
					FROM v_wms_inventory_data_by_serial_mini inv
					WHERE inv.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_COUNT' AND is_active = 'YES')
					AND inv.wh_master_id = @in_vchWhMasterID
					AND inv.owner_id = @in_vchOwnerID
					GROUP BY inv.wh_item_master_id
						,inv.location_id
						,inv.inv_status
						,(case when isnull(inv.parent_lpn,'')	= '' then null else inv.parent_lpn end)
						,(case when isnull(inv.lpn,'')			= '' then null else inv.lpn end)
						,(case when isnull(inv.lot_number,'')	= '' then null else inv.lot_number end)
						,(case when isnull(inv.expiry_date,'')	= '' then null else inv.expiry_date end)
						,(case when isnull(inv.serial_number,'')= '' then null else inv.serial_number end)
						,(case when isnull(inv.attribute1,'')	= '' then null else inv.attribute1 end)
						,(case when isnull(inv.attribute2,'')	= '' then null else inv.attribute2 end)
						,(case when isnull(inv.attribute3,'')	= '' then null else inv.attribute3 end)
						,(case when isnull(inv.attribute4,'')	= '' then null else inv.attribute4 end)
						,(case when isnull(inv.attribute5,'')	= '' then null else inv.attribute5 end)

					SET @out_ErrorCode = '0';
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
				COMMIT TRANSACTION; 
			END
			
	END TRY
	BEGIN CATCH
		
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;

		DECLARE @v_dtProcessDateTime DATETIME = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = 'UNALLOCATE',
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = 'usp_create_count_plan_by_wh',
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchCountID,
			@in_vchData2 = NULL,
			@in_vchData3 = @out_ErrorCode,
			@in_vchData4 = @out_ErrorMessage,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END



GO
/****** Object:  StoredProcedure [dbo].[usp_create_count_plan_by_wh_external]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_create_count_plan_by_wh_external]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(50),
	@in_vchCountID			NVARCHAR(40),
	@in_vchCountType		NVARCHAR(50),
	@in_vchDescription		NVARCHAR(200),
	@in_vchCustomerID		UNIQUEIDENTIFIER,
	@in_vchCountDatePlan	DATETIME,
	@in_vchUserID			NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
	
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchWhMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchCountMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchCustomerCode	NVARCHAR(50)
	DECLARE @v_vchCustomerName	NVARCHAR(200)
	DECLARE @v_vchOwnerCode		NVARCHAR(40)
	
	BEGIN TRY
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active ='YES'
		SELECT @v_vchCustomerCode = customer_code, @v_vchCustomerName = customer_name FROM t_wms_customer WHERE customer_id = @in_vchCustomerID AND is_active = 'YES'
		SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'
		
		IF ISNULL(@v_vchCustomerCode,'') = ''
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO-CUSTOMER-IS-EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		IF EXISTS (SELECT count_master_id FROM t_wms_count_plan_master_external WHERE count_id = @in_vchCountID AND wh_master_id = @v_vchWhMasterID)
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'COUNT_ID_ALREADY_EXIST',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		  
		BEGIN TRANSACTION
		
		SET @v_vchCountMasterID = NEWID();

		INSERT INTO [dbo].[t_wms_count_plan_master_external]
				([count_master_id]
				,[wh_master_id]
				,[count_id]
				,[owner_code]
				,[count_status]
				,[description]
				,[count_generate_method]
				,[count_plan_type]
				,[customer_id]
				,[customer_code]
				,[customer_name]
				,[count_plan_date]
				,[create_date]
				,[create_by])
			VALUES
				(@v_vchCountMasterID
				,@v_vchWhMasterID
				,@in_vchCountID
				,@v_vchOwnerCode
				,'OPEN'
				,@in_vchDescription
				,'MANUAL'
				,@in_vchCountType
				,@in_vchCustomerID
				,@v_vchCustomerCode
				,@v_vchCustomerName
				,@in_vchCountDatePlan
				,GETDATE()
				,@in_vchUserID)
			
		INSERT INTO [dbo].[t_wms_count_plan_detail_external]
						([count_plan_detail_id]
						,[count_master_id]
						,[location_id]
						,[location]
						,[wh_item_master_id]
						,[item_number]
						,[item_description]
						,[days_to_expire]
						,[inv_status]
						,[parent_lpn]
						,[lpn]
						,[lot_number]
						,[expiry_date]
						,[serial_number]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[stock_qty]
						,[count_plan_date] 
						,[item_category]
						,[item_category_description]
						,[create_by]
						,[create_date])
			SELECT  NEWID()
					,@v_vchCountMasterID
					,inv.location_id
					,inv.location
					,inv.wh_item_master_id
					,inv.item_number
					,inv.description
					,inv.days_to_expire
					,inv.inv_status
					,inv.parent_lpn
					,inv.lpn
					,inv.lot_number
					,inv.expiry_date
					,inv.serial_number
					,inv.attribute1
					,inv.attribute2
					,inv.attribute3
					,inv.attribute4
					,inv.attribute5
					,inv.quantity
					,@in_vchCountDatePlan
					,inv.item_category
					,inv.description
					,@in_vchUserID
					,GETDATE()
			FROM v_wms_inventory_for_count_external inv 
			WHERE inv.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_COUNT_EXTERNAL')
			AND inv.wh_master_id = @v_vchWhMasterID
			AND inv.customer_id = @in_vchCustomerID
			AND inv.owner_id = @in_vchOwnerID 

		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
		COMMIT TRANSACTION;
			 
	END TRY
	BEGIN CATCH
		
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;

	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[usp_create_count_plan_external]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_create_count_plan_external]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(50),
	@in_vchCountID			NVARCHAR(40),
	@in_vchCountType		NVARCHAR(50),
	@in_vchDescription		NVARCHAR(200),
	@in_vchCustomerID		UNIQUEIDENTIFIER,
	@in_vchCountDatePlan	DATETIME,
	@in_vchUserID			NVARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
	
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @v_vchWhMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchCountMasterID UNIQUEIDENTIFIER
	DECLARE @v_vchCustomerCode	NVARCHAR(50)
	DECLARE @v_vchCustomerName	NVARCHAR(200)
	DECLARE @v_vchOwnerCode		NVARCHAR(40)

	BEGIN TRY
		
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active ='YES'
		SELECT @v_vchCustomerCode = customer_code, @v_vchCustomerName = customer_name FROM t_wms_customer WHERE customer_id = @in_vchCustomerID AND is_active = 'YES'
		SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner where owner_id = @in_vchOwnerID AND is_active = 'YES'

		IF ISNULL(@v_vchCustomerCode,'') = ''
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO-CUSTOMER-IS-EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		IF EXISTS (SELECT count_master_id FROM t_wms_count_plan_master_external WHERE count_id = @in_vchCountID AND wh_master_id = @v_vchWhMasterID)
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'COUNT_ID_ALREADY_EXIST',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		 
		BEGIN TRANSACTION
		
		SET @v_vchCountMasterID = NEWID();
				
		INSERT INTO [dbo].[t_wms_count_plan_master_external]
					([count_master_id]
					,[wh_master_id]
					,[count_id]
					,[owner_code]
					,[count_status]
					,[description]
					,[count_generate_method]
					,[count_plan_type]
					,[customer_id]
					,[customer_code]
					,[customer_name]
					,[count_plan_date]
					,[create_date]
					,[create_by])
				VALUES
					(@v_vchCountMasterID
					,@v_vchWhMasterID
					,@in_vchCountID
					,@v_vchOwnerCode
					,'OPEN'
					,@in_vchDescription
					,'MANUAL'
					,@in_vchCountType
					,@in_vchCustomerID
					,@v_vchCustomerCode
					,@v_vchCustomerName
					,@in_vchCountDatePlan
					,GETDATE()
					,@in_vchUserID)
				
		INSERT INTO [dbo].[t_wms_count_plan_detail_external]
					([count_plan_detail_id]
					,[count_master_id]
					,[location_id]
					,[location]
					,[wh_item_master_id]
					,[item_number]
					,[item_description]
					,[days_to_expire]
					,[inv_status]
					,[parent_lpn]
					,[lpn]
					,[lot_number]
					,[expiry_date]
					,[serial_number]
					,[attribute1]
					,[attribute2]
					,[attribute3]
					,[attribute4]
					,[attribute5]
					,[stock_qty]
					,[count_plan_date] 
					,[item_category]
					,[item_category_description]
					,[create_by]
					,[create_date])
				SELECT NEWID()
					,@v_vchCountMasterID
					,temp.location_id
					,loc.location
					,temp.wh_item_master_id
					,item.item_number
					,item.description
					,item.days_to_expire
					,temp.inv_status
					,temp.parent_lpn
					,temp.lpn
					,temp.lot_number
					,(CASE ISNULL(temp.expiry_date,'') WHEN '' THEN NULL ELSE temp.expiry_date END)
					,temp.serial_number
					,temp.attribute1
					,temp.attribute2
					,temp.attribute3
					,temp.attribute4
					,temp.attribute5
					,temp.stock_qty
					,@in_vchCountDatePlan 
					,cate.item_category
					,cate.description
					,@in_vchUserID
					,GETDATE()
				FROM t_wms_count_temporary_external temp
				LEFT JOIN t_wms_location loc ON temp.location_id = loc.location_id
				LEFT JOIN t_wms_wh_item whItem ON temp.wh_item_master_id = whItem.wh_item_master_id
				LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
				LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
				WHERE temp.create_by = @in_vchUserID

		DELETE FROM t_wms_count_temporary_external WHERE create_by = @in_vchUserID

		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		COMMIT TRANSACTION 
			 
	END TRY
	BEGIN CATCH

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;

	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_create_count_plan_external_offline]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_create_count_plan_external_offline]
(
	@in_vchCountID			NVARCHAR(40),
	@in_vchOwnerCode		NVARCHAR(50) = NULL,
	@in_vchCustomerCode		NVARCHAR(50),
	@in_dtCountPlanDate		DATETIME,
	@in_vchItemCategory		NVARCHAR(50),
	@in_vchItemCategoryDesc NVARCHAR(200),
	@in_vchLocation			NVARCHAR(50),
	@in_vchWhItemMasterID	VARCHAR(40),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchItemDescription	NVARCHAR(200),
	@in_vchLotNumber		NVARCHAR(50),
	@in_vchExpiryDate		NVARCHAR(50),
	@in_vchInvStatus		NVARCHAR(50),
	@in_vchSerialNumber		NVARCHAR(100),
	@in_vchDayToExpire		INT = NULL,
	@in_fltStockQty			FLOAT,
	@in_dtDeliveryDate		DATETIME = NULL,
	@in_vchOrderNumber		NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25),
	@in_vchCountPlanType	NVARCHAR(50) = NULL,
	@in_vchDescription		NVARCHAR(500) = NULL,
	@out_ErrorCode			NVARCHAR(100) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	--For IOS Create Count Plan
	SET NOCOUNT ON;	
	DECLARE @v_vchWhMasterID		VARCHAR(40) = NULL,
			@v_vchCountMasterID		VARCHAR(40) = NULL,
			@v_vchOwnerID			VARCHAR(40) = NULL,
			@v_vchCustomerID		VARCHAR(40) = NULL,
			@v_vchCustomerName		NVARCHAR(200)=NULL,
			@v_vchLocationID		NVARCHAR(40)= NULL,
			@v_vchLocation			NVARCHAR(50)= NULL

BEGIN TRY
	--Get Warehouse
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE is_active = 'YES'

	--Get Owner
	IF ISNULL(@in_vchOwnerCode,'') <> ''
		BEGIN
			SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwnerCode AND is_active = 'YES'
		END
	ELSE 
		BEGIN
			SELECT TOP 1  @v_vchOwnerID = owner_id FROM t_wms_owner WHERE is_active = 'YES'
		END

	--Check Item
	IF NOT EXISTS (SELECT item.item_master_id FROM t_wms_item item
					LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id
					WHERE whItem.wh_master_id = @v_vchWhMasterID
					AND item.item_number = @in_vchItemNumber 
					AND item.owner_id = @v_vchOwnerID AND item.is_active = 'YES')
		BEGIN
			SET @out_ErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST';
			SELECT @out_ErrorMessage =  'Item does not exists';

			RETURN;
		END

	--Get Customer
	SELECT @v_vchCustomerID = customer_id
		, @v_vchCustomerName = customer_name
	FROM t_wms_customer 
	WHERE customer_code = @in_vchCustomerCode 
	AND is_active = 'YES'
	AND owner_id = @v_vchOwnerID
	IF (ISNULL(@v_vchCustomerID,'') = '')
		BEGIN
			SET @out_ErrorCode = 'INFO-CUSTOMER-NOT-EXIST';
			SELECT @out_ErrorMessage =  'Customer does not exist';
			RETURN;
		END

	-- Get Customer Location
	SELECT @v_vchLocationID = custLoc.location_id
		, @v_vchLocation = loc.location
	FROM t_wms_customer_location custLoc
	LEFT JOIN t_wms_location loc ON custLoc.location_id = loc.location_id
	WHERE custLoc.customer_id = @v_vchCustomerID 
	AND custLoc.is_active = 'YES'

	BEGIN--Insert Count External
		IF NOT EXISTS (SELECT count_master_id FROM [t_wms_count_plan_master_external] 
						WHERE wh_master_id = @v_vchWhMasterID
						AND count_id = @in_vchCountID)
			BEGIN
				SET @v_vchCountMasterID = NEWID()
				INSERT INTO [dbo].[t_wms_count_plan_master_external]
						   ([count_master_id]
						   ,[wh_master_id]
						   ,[count_id]
						   ,[owner_code]
						   ,[count_status]
						   ,[priority]
						   ,[description]
						   ,[count_generate_method]
						   ,[count_plan_type]
						   ,[customer_id]
						   ,[customer_code]
						   ,[customer_name]
						   ,[count_plan_date]
						   ,[create_date]
						   ,[create_by])
					 VALUES
						   (@v_vchCountMasterID
						   ,@v_vchWhMasterID
						   ,@in_vchCountID
						   ,@in_vchOwnerCode
						   ,'OPEN'
						   ,NULL
						   ,@in_vchDescription
						   ,'MANUAL'
						   ,@in_vchCountPlanType
						   ,@v_vchCustomerID
						   ,@in_vchCustomerCode
						   ,@v_vchCustomerName
						   ,@in_dtCountPlanDate
						   ,GETDATE()
						   ,@in_vchUserID)
			END
		ELSE
			BEGIN
				SELECT @v_vchCountMasterID  = count_master_id FROM [t_wms_count_plan_master_external] 
				WHERE wh_master_id = @v_vchWhMasterID
				AND count_id = @in_vchCountID
			END
			
			--ถ้ามีการ Insert ไปแล้วจะไม่ Insert ซ้ำ
			IF NOT EXISTS (SELECT count_plan_detail_id FROM t_wms_count_plan_detail_external
							WHERE count_master_id = @v_vchCountMasterID
							AND location_id		  = @v_vchLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inv_status		  = @in_vchInvStatus
							AND lot_number		  = @in_vchLotNumber
							AND expiry_date		  = @in_vchExpiryDate
							AND serial_number	  = @in_vchSerialNumber)
				BEGIN
					--Insert Detail
					INSERT INTO [dbo].[t_wms_count_plan_detail_external]
							   ([count_plan_detail_id]
							   ,[count_master_id]
							   ,[location_id]
							   ,[location]
							   ,[wh_item_master_id]
							   ,[item_number]
							   ,[item_description]
							   ,[days_to_expire]
							   ,[inv_status]
							   ,[lot_number]
							   ,[expiry_date]
							   ,[serial_number]
							   ,[stock_qty]
							   ,[count_plan_date]
							   ,[delivery_date]
							   ,[outbound_order_number]
							   ,[item_category]
							   ,[item_category_description]
							   ,[create_by]
							   ,[create_date])
						VALUES
							( NEWID()
								,@v_vchCountMasterID
								,@v_vchLocationID
								,@v_vchLocation
								,@in_vchWhItemMasterID
								,@in_vchItemNumber
								,@in_vchItemDescription
								,CASE ISNULL(@in_vchDayToExpire,0) WHEN 0 THEN NULL ELSE @in_vchDayToExpire END
								,@in_vchInvStatus
								,@in_vchLotNumber
								,@in_vchExpiryDate
								,@in_vchSerialNumber
								,@in_fltStockQty
								,@in_dtCountPlanDate
								,@in_dtDeliveryDate
								,@in_vchOrderNumber
								,@in_vchItemCategory
								,@in_vchItemCategoryDesc
								,@in_vchUserID
								,GETDATE()
							)
				END

		SET @out_ErrorCode = '0';
		SET @out_ErrorMessage = 'SUCCESS';
	END
END TRY
BEGIN CATCH
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
END CATCH
END


