/****** Object:  StoredProcedure [dbo].[usp_cycle_count_get_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai Kokaew.
-- Create date: 2012-06-08
-- Description:	Select item data for create count plan
-- =============================================
CREATE PROCEDURE [dbo].[usp_cycle_count_get_item]
	@in_vchApplicationID	VARCHAR(40) = null,
	@in_vchWarehouse		NVARCHAR(50),
	@in_vchCostOperator		NVARCHAR(1),
	@in_fltCost				FLOAT = null,
	@in_vchPirceOperator	NVARCHAR(1),
	@in_fltPrice			FLOAT = null,
	@in_vchTranType			NVARCHAR(20),
	@in_vchSubTranType		NVARCHAR(20),
	@in_dtpStartDate		DATE,
	@in_dtpEndDate			DATE,
	@in_vchStartLocation	NVARCHAR(50),
	@in_vchToLocation		NVARCHAR(50),
	@in_vchItemCategory		NVARCHAR(50),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchUser				NVARCHAR(50),
	@out_ResultMessage		NVARCHAR(100)= null output
	
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;
	Declare @command		NVARCHAR(MAX) = '',
			@command1		NVARCHAR(MAX) = '',
			@WHMasterID		NVARCHAR(40)
		
	Begin Try
		
		select @WHMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
							
		create Table #TmpStock (
						wh_id	nvarchar(50)
						,owner_id	nvarchar(50)
						,wh_item_master_id nvarchar(40)
						,item_number nvarchar(50)
						,qty_item float
						,location nvarchar(50)
						,location_id nvarchar(40)
						,inv_status nvarchar(50)
						,parent_lpn nvarchar(25)
						,lpn nvarchar(25)
						,LOT nvarchar(50)
						,[EXPIRY_DATE] nvarchar(50)
						,SERIAL_NUMBER nvarchar(50)
						,item_category nvarchar(50)
						,[description] nvarchar(100))

		If (@in_fltCost is not null and @in_fltPrice is not null)
			Begin
				set @command = 'select item_number from t_wms_item where isnull(cost,0) ' + @in_vchCostOperator + ' ' + convert(nvarchar,@in_fltCost) + ' and isnull(price,0) ' + @in_vchPirceOperator + ' ' + convert(nvarchar,@in_fltPrice);
			End
		Else If (@in_fltCost is not null)
			Begin
				set @command = 'select item_number from t_wms_item where isnull(cost,0) ' + @in_vchCostOperator + ' ' + convert(nvarchar,@in_fltCost);
			End
		Else If (@in_fltPrice is not null)
			Begin
				set @command = 'select item_number from t_wms_item where isnull(price,0) ' + @in_vchPirceOperator + ' ' + convert(nvarchar,@in_fltPrice);
			End
		Else If (@in_vchTranType is not null or @in_vchSubTranType is not null or @in_dtpStartDate is not null or @in_dtpEndDate is not null)
			Begin
				set @command = 'select item_number from t_com_tran_log where warehouse = ''' + @in_vchWarehouse + ''' and tran_type = ''' + @in_vchTranType + ''' and isnull(sub_tran_type,''%'') like ''' + isnull(@in_vchSubTranType,'%') + ''' and convert(nvarchar,start_tran_datetime,112) between ' + isnull(convert(nvarchar,@in_dtpStartDate,112),'00010101') + ' and ' + isnull(convert(nvarchar,@in_dtpEndDate,112),'99991231');
			End
		Else If (@in_vchItemCategory is not null)
			Begin
				set @command = 'select item_number from t_wms_item where item_category = ''' + @in_vchItemCategory + '''';
			End
		Else If (@in_vchItemNumber is not null)
			Begin
				set @command = 'select item_number from v_wms_inventory_item where item_number LIKE ''' + @in_vchItemNumber + '%''';
			End

		-- Get inventory by condition
		set @command1 = 'select wh_id,owner_id,wh_item_master_id,item_number,sum(quantity) as qty_item,location,location_id,inv_status,parent_lpn,lpn,LOT,EXPIRY_DATE,SERIAL_NUMBER,item_category,description from v_wms_inventory_data where wh_id = ''' + @in_vchWarehouse + ''' ';
		
		If (isnull(@in_vchStartLocation,'') <> '' and isnull(@in_vchToLocation,'') <> '')
			Begin
				set @command1 = @command1 + ' and location between ''' + @in_vchStartLocation + ''' and ''' + @in_vchToLocation + ''' ';
			End
			
		if (isnull(@command,'') <> '')
			begin
				set @command1 = @command1 +  ' and item_number in (' + @command + ') ';
			end
	
		set @command1 = @command1 + ' group by wh_id,owner_id,wh_item_master_id,item_number,location,location_id,inv_status,parent_lpn,lpn,LOT,EXPIRY_DATE,SERIAL_NUMBER,item_category,description order by location';
				
		insert into #TmpStock exec sp_executesql @command1
		
		select wh_id,owner_id,location,parent_lpn,lpn,item_number,LOT,EXPIRY_DATE,SERIAL_NUMBER,item_category,description from #TmpStock

		set @out_ResultMessage = 'SUCCESS';

	End Try
	Begin Catch
		set @out_ResultMessage = ERROR_MESSAGE();
	End Catch
END


GO
/****** Object:  StoredProcedure [dbo].[usp_cycle_count_get_rowcount]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai Kokaew.
-- Create date: 2012-06-08
-- Description:	Select item data for create count plan
-- =============================================
CREATE PROCEDURE [dbo].[usp_cycle_count_get_rowcount]
	@in_vchApplicationID	VARCHAR(40) = null,
	@in_vchWarehouse		NVARCHAR(50),
	@in_vchCostOperator		NVARCHAR(1),
	@in_fltCost				FLOAT = null,
	@in_vchPirceOperator	NVARCHAR(1),
	@in_fltPrice			FLOAT = null,
	@in_vchTranType			NVARCHAR(20),
	@in_vchSubTranType		NVARCHAR(20),
	@in_dtpStartDate		DATE,
	@in_dtpEndDate			DATE,
	@in_vchStartLocation	NVARCHAR(50),
	@in_vchToLocation		NVARCHAR(50),
	@in_vchItemCategory		NVARCHAR(50),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchUser				NVARCHAR(50),
	@out_fltRowCount		FLOAT OUTPUT,
	@out_ResultMessage		NVARCHAR(100)= null output
	
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;
	Declare @command		NVARCHAR(MAX) = '',
			@command1		NVARCHAR(MAX) = '',
			@WHMasterID		NVARCHAR(40),
			@RowCount		FLOAT
		
	Begin Try
		
		SET @out_fltRowCount = 0;
		select @WHMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		
		If (isnull(@in_fltCost,'') <> '' and isnull(@in_fltPrice,'') <> '')
			Begin
				set @command = 'select distinct item_number from t_wms_item where isnull(cost,0) ' + @in_vchCostOperator + ' ' + convert(nvarchar,@in_fltCost) + ' and isnull(price,0) ' + @in_vchPirceOperator + ' ' + convert(nvarchar,@in_fltPrice);
			End
		If (isnull(@in_fltCost,'') <> '')
			Begin
				If (isnull(@command,'') <> '')
					set @command =  @command + ' union ';
				set @command =  @command + 'select distinct item_number from t_wms_item where isnull(cost,0) ' + @in_vchCostOperator + ' ' + convert(nvarchar,@in_fltCost);
			End
		If (isnull(@in_fltPrice,'') <> '')
			Begin
				If (isnull(@command,'') <> '')
					set @command =  @command + ' union ';
				set @command =  @command + 'select distinct item_number from t_wms_item where isnull(price,0) ' + @in_vchPirceOperator + ' ' + convert(nvarchar,@in_fltPrice);
			End
		If (isnull(@in_vchTranType,'') <> '' or isnull(@in_vchSubTranType,'') <> '' and (@in_dtpStartDate is not null or @in_dtpEndDate is not null))
			Begin
				If (isnull(@command,'') <> '')
					set @command =  @command + ' union ';
				set @command =  @command + 'select distinct item_number from t_com_tran_log where warehouse = ''' + @in_vchWarehouse + ''' and tran_type = ''' + @in_vchTranType + ''' and isnull(sub_tran_type,''%'') like ''' + isnull(@in_vchSubTranType,'%') + ''' and convert(nvarchar,start_tran_datetime,112) between ' + isnull(convert(nvarchar,@in_dtpStartDate,112),'00010101') + ' and ' + isnull(convert(nvarchar,@in_dtpEndDate,112),'99991231');
			End

		If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				If (isnull(@command,'') <> '')
					set @command =  @command + ' union ';
				set @command =  @command + 'select distinct item_number from t_wms_item where item_category = ''' + @in_vchItemCategory + '''';
			End
		If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				If (isnull(@command,'') <> '')
					set @command =  @command + ' union ';
				set @command =  @command + 'select distinct item_number from v_wms_inventory_item where item_number LIKE ''' + @in_vchItemNumber + '%''';
			End
		
		set @command1 = 'select @RowCount = count(*) from v_wms_inventory_item where wh_id = ''' + @in_vchWarehouse + ''' ';
		
		If (isnull(@in_vchStartLocation,'') <> '' and isnull(@in_vchToLocation,'') <> '')
			Begin
				set @command1 = @command1 + ' and location between ''' + @in_vchStartLocation + ''' and ''' + @in_vchToLocation + ''' and inv_status <> ''ReturnOver'' ';
			End
		
		if (isnull(@command,'') <> '')
			begin
				set @command1 = @command1 +  ' and item_number in (' + @command + ') ';
			end
		
		exec sp_executesql @command1,N'@RowCount float output',@RowCount output;
		SET @out_fltRowCount = @RowCount;
		set @out_ResultMessage = 'SUCCESS';

	End Try
	Begin Catch
		set @out_ResultMessage = ERROR_MESSAGE();
	End Catch
END


GO
/****** Object:  StoredProcedure [dbo].[usp_cycle_count_lpn_counting]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-03-08
-- Description:	Cycle Count.LPN Counting
-- =============================================
CREATE PROCEDURE [dbo].[usp_cycle_count_lpn_counting]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	
	@in_vchCycleCountID		NVARCHAR(40),
	@in_vchLocation			NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchItemNumber		NVARCHAR(50),
	
	@in_fltCountQty			FLOAT = 0,
	@in_vchIsConfirm		NVARCHAR(3) = 'NO', -- value is YES / NO
	
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_cycle_count_lpn_counting]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		
		@v_dtProcessDateTime		DATETIME,
		@v_vchApplicationName		NVARCHAR(100),
		
		-- Get GUID
		@v_vchWarehouseMasterID		VARCHAR(40),
		@v_vchCountMasterID			VARCHAR(40),
		@v_vchLocationID			VARCHAR(40),
		@v_vchWareHouseItemMasterID	VARCHAR(40),
		
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(50),
		@v_vchSerialNumber			NVARCHAR(50),
		@v_fltQuantity				FLOAT,
		@v_vchUOM					NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchLPN					NVARCHAR(25),
		
		@v_vchOwnerID				NVARCHAR(50) = 'TUF',
		@v_vchFromLocation			NVARCHAR(50),
		@v_vchToLocation			NVARCHAR(50),
		@v_vchFromParentLPN			NVARCHAR(25),
		@v_vchFromStatus			NVARCHAR(25),
		@v_vchFromLotNumber			NVARCHAR(50),
		@v_vchFromExpiryDate		NVARCHAR(50),
		@v_vchFromSerialNumber		NVARCHAR(50),
		@v_fltMoveQuantity			FLOAT,
		@v_vchInvParentLPN			NVARCHAR(25),
		
		@v_vchDynamicSQL			NVARCHAR(1000),
		@v_cursorInventory			CURSOR,
		
		@v_vchBeginTrans			BIT = 0
    
	Begin Try
		
		select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		select @v_vchCountMasterID = count_master_id from t_wms_count_plan_master where wh_master_id = @v_vchWarehouseMasterID and count_id = @in_vchCycleCountID
		
		--===================== LPN Counting =====================--
		
		-- 1. input lpn quantity
		Begin
			If (isnull(@in_fltCountQty,0) > 0) 
				Begin
					-- check count lpn quantity by location,parent lpn,item
					-- 1 count lpn quantity = input quantity.Insert inventory data into t_com_wms_count_reconcile
					-- 2 count lpn quantity <> input quantity.return @out_ErrorCode = 1(scan all lpn)
					If ((select COUNT (distinct lpn) from v_wms_count_plan_detail where wh_id = @in_vchWarehouse and count_id = @in_vchCycleCountID and location = @in_vchLocation
						and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') 
						--and item_number = @in_vchItemNumber
						) = @in_fltCountQty)
						Begin
							GOTO INSERT_INTO_COUNT_RECONCILE; -- goto 4.
						End
					Else
						Begin
							set @out_ErrorCode = '1';
							select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'QTY_INV_UNEQUAL_QTY_COUNT_PLAN',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCycleCountID,@in_vchParentLPN,@in_vchItemNumber,'@param4','@param5')
							Goto WRITE_PROC;
						End
				End
		End
		
		-- 2. enter lpn
		Begin
			If (isnull(@in_vchLPN,'') <> '')
				Begin
					If Exists(select lpn from t_wms_count_reconcile where count_master_id = @v_vchCountMasterID and lpn = @in_vchLPN)
						Begin
							set @out_ErrorCode = '999';
							select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_EXISTS_IN_COUNT_RECONCILE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLPN,'@param2','@param3','@param4','@param5')
							Goto WRITE_PROC;
						End
					-- 2.6					
					If Exists(select item_number from v_wms_inventory_data where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchLocation and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and lpn = @in_vchLPN )
					--and item_number = @in_vchItemNumber)
						Begin
							Goto INSERT_INTO_COUNT_RECONCILE;
						End
					Else
						Begin
							-- 2.3 Does the Item exists on the Child LPN?
							If Not Exists(select item_number from v_wms_inventory_data where wh_master_id = @v_vchWarehouseMasterID and lpn = @in_vchLPN)
								Begin
									set @out_ErrorCode = '999';
									select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO-LPN-NOT-EXIST',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCycleCountID,@in_vchItemNumber,@in_vchLPN,'@param4','@param5')
									Goto WRITE_PROC;
								End
							-- 2.4 Does the Item exists on the Child LPN?
							If Not Exists(select item_number from v_wms_inventory_data where wh_master_id = @v_vchWarehouseMasterID and lpn = @in_vchLPN and item_number = @in_vchItemNumber)
								Begin
									set @out_ErrorCode = '999';
									select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NOT_EXISTS_IN_LPN',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCycleCountID,@in_vchItemNumber,@in_vchLPN,'@param4','@param5')
									Goto WRITE_PROC;
								End
							-- 2.7 Does the Child LPN exists in Inventory table?
							If Not Exists(select item_number from v_wms_inventory_data where wh_master_id = @v_vchWarehouseMasterID and (location <> @in_vchLocation or parent_lpn <> @in_vchParentLPN) and lpn = @in_vchLPN)
								Begin
									set @out_ErrorCode = '999';
									select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO-LPN-NOT-EXIST',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
									Goto WRITE_PROC;
								End
							Else
								Begin
									select @v_vchInvParentLPN = parent_lpn from t_wms_inventory where wh_master_id = @v_vchWarehouseMasterID and lpn = @in_vchLPN
									set @out_ErrorCode = '2';
									select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_PL',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLPN,@v_vchInvParentLPN,'@param3','@param4','@param5')
									Goto WRITE_PROC;
									--select	@v_vchOwnerID = owner_id,@v_vchFromLocation = location,@v_vchLocationID = location_id,@v_vchFromParentLPN = parent_lpn,
									--		@v_vchLPN = lpn, @v_vchFromStatus = inv_status,@v_vchFromLotNumber = LOT,@v_vchFromExpiryDate = EXPIRY_DATE,
									--		@v_fltMoveQuantity = quantity, @v_vchSerialNumber = SERIAL_NUMBER,@v_vchUOM = uom_prompt,@v_vchWareHouseItemMasterID = wh_item_master_id
									--		from v_wms_inventory_data 
									--where wh_master_id = @v_vchWarehouseMasterID and lpn = @in_vchLPN
									--Goto MOVE_INVENTORY_DATA;
								End
						End
				End
		End
		
		-- 3. confirm done
		Begin
			If Exists(select lpn from t_wms_count_plan_detail where count_master_id = @v_vchCountMasterID and parent_lpn = @in_vchParentLPN and 
			lpn not in (select lpn from t_wms_count_reconcile c where c.count_master_id = @v_vchCountMasterID and c.parent_lpn = @in_vchParentLPN))
				Begin
					set @v_vchFromLocation = @in_vchLocation;
					select @v_vchLocationID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @v_vchFromLocation
					select top 1 @v_vchToLocation = location from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and loc_type = 'QC'
					
					declare cursorLPNCounting cursor for
						select lpn from t_wms_count_plan_detail where count_master_id = @v_vchCountMasterID and parent_lpn = @in_vchParentLPN and location_id = @v_vchLocationID
							and lpn not in (select lpn from t_wms_count_reconcile c where c.count_master_id = @v_vchCountMasterID and c.parent_lpn = @in_vchParentLPN)
					
					Open cursorLPNCounting;
					fetch from cursorLPNCounting into @v_vchLPN;
					
					Begin Transaction
						set @v_vchBeginTrans = 1;
						
						While @@FETCH_STATUS = 0
							Begin
								exec [usp_inventory_control_all_value]
									@in_vchApplicationID	= @in_vchApplicationID,
									@in_vchWarehouse		= @in_vchWarehouse,
									@in_vchDeviceID			= @in_vchDeviceID,
									@in_vchUserID			= @in_vchUserID,
									@in_vchTransactionType	= 'LPN_COUNTING',
									@in_vchSubTranType		= 'LPN_COUNTING',
									@in_vchAllItem			= 'YES',		
									@in_vchFromLocation		= @v_vchFromLocation,
									@in_vchToLocation		= @v_vchToLocation,
									@in_vchFromParentLPN	= @in_vchParentLPN,
									@in_vchFromLPN			= @v_vchLPN,
									@in_vchToParentLPN		= null,
									@in_vchToLPN			= @v_vchLPN,
									@out_ErrorCode			= @out_ErrorCode output,
									@out_ErrorMessage		= @out_ErrorMessage output
								If (@out_ErrorCode <> '0')
									Begin
										Rollback Transaction;
										return;
									End
								
								fetch next from cursorLPNCounting into @v_vchLPN;
							End
					Close cursorLPNCounting;
					Deallocate cursorLPNCounting;
					Commit Transaction
					set @out_ErrorCode = '0';
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					return;
				End
			Else
				Begin
					set @out_ErrorCode = '0';
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					return;
				End
		End
		
		-- 4.Insert into Count Reconcile
		INSERT_INTO_COUNT_RECONCILE:
		Begin
			BEGIN TRANSACTION
				SET @v_vchBeginTrans = 1;
				
				set @v_vchDynamicSQL = 'select wh_item_master_id,quantity,location_id,inv_status,uom_prompt,lpn,lot_number,expiry_date,serial_number from v_wms_inventory_data
					where wh_master_id = ''' + @v_vchWarehouseMasterID + ''' and location = ''' + @in_vchLocation + ''' and isnull(parent_lpn,'''') = ''' + isnull(@in_vchParentLPN,'''') + ''' '
					--and item_number = ''' + @in_vchItemNumber + ''' '
				
				If (isnull(@in_vchLPN,'') <> '')
					set @v_vchDynamicSQL = @v_vchDynamicSQL + ' and isnull(lpn,'''') = ''' + isnull(@in_vchLPN,'') + ''' '
					
				set @v_vchDynamicSQL = ' set @v_cursorInventory = CURSOR FORWARD_ONLY STATIC FOR ' +
							@v_vchDynamicSQL + ' ; OPEN @v_cursorInventory'
					
				exec sp_executesql @v_vchDynamicSQL,N'@v_cursorInventory CURSOR OUTPUT',@v_cursorInventory OUTPUT
				fetch from @v_cursorInventory into @v_vchWareHouseItemMasterID,@v_fltQuantity,@v_vchLocationID,@v_vchInventoryStatus,@v_vchUOM,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
				
				While @@FETCH_STATUS = 0
					Begin
						update t_wms_count_plan_detail set count_qty = @v_fltQuantity
						where count_master_id = @v_vchCountMasterID and wh_item_master_id = @v_vchWareHouseItemMasterID and location_id = @v_vchLocationID and parent_lpn = @in_vchParentLPN and lpn = @v_vchLPN
						
						insert into t_wms_count_reconcile(count_master_id, wh_item_master_id, inv_status, location_id, parent_lpn, lpn, lot, expiry_date, serial_number, expect_qty, count_qty, create_by)
						values(@v_vchCountMasterID,@v_vchWareHouseItemMasterID,@v_vchInventoryStatus,@v_vchLocationID,@in_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_fltQuantity,@v_fltQuantity,@in_vchUserID)
						
						fetch next from @v_cursorInventory into @v_vchWareHouseItemMasterID,@v_fltQuantity,@v_vchLocationID,@v_vchInventoryStatus,@v_vchUOM,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
					End
				
				Close @v_cursorInventory;
				Deallocate @v_cursorInventory;
			COMMIT TRANSACTION
			set @out_ErrorCode = '0';
			select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			return;
		End
		
		-- 5.Move inventory data
		MOVE_INVENTORY_DATA:
		Begin
			BEGIN TRANSACTION
				SET @v_vchBeginTrans = 1;
				
				insert into t_wms_count_reconcile(count_master_id, wh_item_master_id, inv_status, location_id, parent_lpn, lpn, lot, expiry_date, serial_number, expect_qty, count_qty, create_by)
				values(@v_vchCountMasterID,@v_vchWareHouseItemMasterID,@v_vchFromStatus,@v_vchLocationID,@in_vchParentLPN,@v_vchLPN,@v_vchFromLotNumber,@v_vchFromExpiryDate,@v_vchSerialNumber,0,@v_fltMoveQuantity,@in_vchUserID)
						
				--exec[usp_inventory_control] 
				--	@in_vchApplicationID		= @in_vchApplicationID,
				--	@in_vchWarehouse			= @in_vchWarehouse,
				--	@in_vchDevice				= @in_vchDeviceID,
				--	@in_vchTransactionType		= 'LPN_COUNTING',
				--	@in_vchSubTranType			= 'LPN_COUNTING',
				--	@in_vchUserID				= @in_vchUserID,
				--	@in_vchFromLPN				= @v_vchLPN,
				--	@in_vchFromStatus			= @v_vchFromStatus,
				--	@in_vchFromLocation			= @v_vchFromLocation,
				--	@in_vchFromLot				= @v_vchFromLotNumber,
				--	@in_vchFromExpiryDate		= @v_vchFromExpiryDate,
				--	@in_vchItem					= @in_vchItemNumber,
				--	@in_fltQty					= @v_fltMoveQuantity,
				--	@in_fltQtyAllocate			= 0,
				--	@in_vchUOM					= @v_vchUOM,
				--	@in_vchSerialNo				= @v_vchSerialNumber,
				--	@in_vchToLPN				= @v_vchLPN,
				--	@in_vchFromParentLPN		= @v_vchFromParentLPN,
				--	@in_vchToParentLPN			= @in_vchParentLPN,
				--	@in_vchToStatus				= @v_vchFromStatus,
				--	@in_vchToLocation			= @in_vchLocation,
				--	@in_vchToLot				= @v_vchFromLotNumber,
				--	@in_vchToExpiryDate			= @v_vchFromExpiryDate,
				--	@in_vchOrderNumber			= @in_vchCycleCountID,
				--	@in_vchLineNumber			= null,
				--	@in_vchToWarehouse			= @in_vchWarehouse,
				--	@in_vchData1				= 'LPN Counting.Move data to source parent lpn',
				--	@v_vchErrorCode				= @out_ErrorCode output,
				--	@v_vchMessage				= @out_ErrorMessage output
				--If (@out_ErrorCode <> '0')
				--	Begin
				--		Rollback Transaction;
				--		return;
				--	End
			COMMIT TRANSACTION
			set @out_ErrorCode = '0';
			select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			return;
		End
		
		--===================== End Process =====================--

		-----------------------------------------------------------------------------------
		--						Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = getdate();
				
				set @v_vchProcessData2 = 'Item number ' + @in_vchItemNumber;
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchParentLPN = @in_vchParentLPN,
					@in_vchLPN = @in_vchLPN,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchCycleCountID,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		End
		
		-----------------------------------------------------------------------------------
		--						Write transaction log
		Begin
			print ''
		End	
	End Try
	
	Begin Catch
		
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
	
		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
			
		set @v_dtProcessDateTime = GETDATE();
		
		IF EXISTS ( SELECT * FROM sys.procedures
               WHERE schema_id = schema_id('dbo')
                 AND name = N'@v_cursorInventory')
			Begin
				Close @v_cursorInventory;
				Deallocate @v_cursorInventory;
			End

		IF EXISTS ( SELECT * FROM sys.procedures
               WHERE schema_id = schema_id('dbo')
                 AND name = N'cursorLPNCounting')
			Begin
				Close cursorLPNCounting;
				Deallocate cursorLPNCounting;
			End
			
		exec usp_get_application_name @in_vchApplicationID,@v_vchApplicationName output
		exec usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchAppName = @v_vchApplicationName,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchTranType = 'INV_ADJUST',
		@in_vchSubTranType = 'CYCLE_COUNT',
		@in_vchProcess = 'LPN Counting',
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_dtStartTranDate = @v_dtProcessDateTime,
		@in_vchParentLPN = @in_vchParentLPN,
		@in_vchLPN = @in_vchLPN,
		@in_vchItemNumber = @in_vchItemNumber,
		@in_vchLotNumber = @v_vchLotNumber,
		@in_dtExpiryDate = @v_vchExpiryDate,
		@in_vchSerialNumber	= @v_vchSerialNumber,
		@in_vchToLocation = @in_vchLocation,
		@in_fltQuantity = @v_fltQuantity,
		@in_fltAfterQuantity = null,
		@in_vchReferenceNumber = null,
		@in_vchUOM = @v_vchUOM,
		@in_vchAfterUOM = @v_vchUOM,
		@in_vchData1 = 'Update Inbound order receive.',
		@in_vchData2 = @out_ErrorCode,
		@in_vchData3 = @in_vchCycleCountID,
		@in_vchData4 = @in_vchItemNumber,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
	End Catch

END




GO
/****** Object:  StoredProcedure [dbo].[usp_cycle_count_scan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-05-17
-- Description:	Check Item UOM
-- =============================================
CREATE PROCEDURE [dbo].[usp_cycle_count_scan]
	@in_vchApplicationID		NVARCHAR(40),  
	@in_vchWarehouse			NVARCHAR(25),  
	@in_vchDevice				NVARCHAR(50),  
	@in_vchTransactionType		NVARCHAR(20),  
	@in_vchSubTranType			NVARCHAR(20) = null,  
	@in_vchUserID				NVARCHAR(10),  
	@in_vchCountID				NVARCHAR(40),  
	@in_vchItem					NVARCHAR(50),  
	@in_fltQty					FLOAT,  
	@in_vchUOM					NVARCHAR(40),  
	@in_vchParentLPN			NVARCHAR(25) = null,  
	@in_vchLPN					NVARCHAR(25) = null,  
	@in_vchSerialNo				NVARCHAR(50) = null,  
	@in_vchLot					NVARCHAR(50) = null,  
	@in_vchExpiryDate			NVARCHAR(50) = null,  
	@in_vchLocation				NVARCHAR(50) = null,  
	@in_vchStatus				NVARCHAR(50) = null,  
	@in_vchAdjustRemark			NVARCHAR(200) = null,  
	@out_vchErrorCode			NVARCHAR(200) output,  
	@out_vchErrorMessage		NVARCHAR(500) output  
AS  
BEGIN  
 SET NOCOUNT ON;  
  
 DECLARE  
  -- Error handling variables  
	@c_vchObjName			NVARCHAR(30), -- The name that uniquely tags this object.  
	@v_intSqlErrorNumber	INTEGER,  
	@v_intSqlErrorLine		INTEGER,  
	@v_intSqlErrorState		INTEGER,  
	@v_intSqlErrorSeverity  INTEGER,  
	@v_vchSqlErrorMessage	NVARCHAR(1000),  
	@v_vchSqlErrorProcedure	NVARCHAR(200),  
	@v_vchProcessData1		NVARCHAR(1000),  
	@v_vchProcessData2		NVARCHAR(1000),  
	@v_vchProcessData3		NVARCHAR(1000),  
	@v_vchProcessData4		NVARCHAR(1000),  
	@v_nRowCount			INTEGER,  
	@v_nErrorNumber			INTEGER,  
      
	@v_vchItemMasterID		NVARCHAR(40),  
   
	@v_vchFullControl		NVARCHAR(4),  
	@v_vchLotControl		NVARCHAR(3),  
	@v_vchSerialControl		NVARCHAR(6),  
	@v_vchExpiryDateControl	NVARCHAR(15),  
      
	@v_fltUOMConFactor		FLOAT,  
	@v_vchUOMFromUOMPrompt  NVARCHAR(10),  
	@v_fltExpectQuantity	FLOAT = 0,  
      
	@v_vchApplicationName	NVARCHAR(100),  
	@v_vchWarehouseMasterID	NVARCHAR(40),  
	@v_vchLocationID		NVARCHAR(40),  
	@v_vchWarehouseItemMasterID NVARCHAR(40),  
	@v_vchCountMasterID		NVARCHAR(40),  
      
	@v_vchAdjustValue		FLOAT,  
	@v_vchInventoryStatus	NVARCHAR(10),
      
	@v_dtProcessDateTime	DATETIME,  
	@v_WriteLog				NVARCHAR(3),

	@v_vchOwnerCode			NVARCHAR(50),
	@v_vchInventoryID		VARCHAR(40),
	@v_vchAttributeGroupID	VARCHAR(40),
	@v_vchInventoryStatusID	VARCHAR(40),
	@v_vchReceiveDate		DATE
      
 Begin Try  
   
	SET @v_dtProcessDateTime = getdate();  
	SET @v_WriteLog = 'YES';  
	set @c_vchObjName = '[usp_cycle_count_scan]';  
    
	exec usp_get_application_name @in_vchApplicationID,@v_vchApplicationName output
  
	select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse  
	-- check warehouse  
	If(Isnull(@v_vchWarehouseMasterID,'') = '')  
		Begin   
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')  
			Goto WRITE_PROC  
		End  
  
  
	select @v_vchCountMasterID = count_master_id from t_wms_count_plan_master where wh_master_id = @v_vchWarehouseMasterID and count_id = @in_vchCountID  
	-- check count master id  
	If(Isnull(@v_vchCountMasterID,'') = '')  
		Begin   
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'COUNT_ID_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')  
			Goto WRITE_PROC  
		End  
        
	-- check item number and get owner  
	If(Exists(select * from t_wms_item where item_number = @in_vchItem))  
		Begin  
			select @v_vchItemMasterID = item_master_id,  
				@v_vchLotControl = lot_control,  
				@v_vchSerialControl = sn_control,  
				@v_vchExpiryDateControl = expiry_date_control  
			from t_wms_item   
			where item_number = @in_vchItem  
		End 
	Else  
		Begin  
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')  
			Goto WRITE_PROC  
		End  
  
	-- check serial control  
	If(@v_vchSerialControl = @v_vchFullControl)  
		Begin  
			If(isnull(@in_vchSerialNo,'') = '')  
				Begin  
					SET @out_vchErrorCode = '999';  
					select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_NUMBER_ID_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')  
					Return;  
				End  
		End  
  
	-- check lot control  
	If(@v_vchLotControl = @v_vchFullControl)  
		Begin  
			If(isnull(@in_vchLot,'') = '')  
				Begin  
					SET @out_vchErrorCode = '999';  
					select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOT_NUMBER_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')  
					Return;  
				End  
		End   
    
	-- check expiry date control  
	If(@v_vchExpiryDateControl = @v_vchFullControl)  
		Begin  
			If(isnull(@in_vchExpiryDate,'') = '')  
				Begin  
					SET @out_vchErrorCode = '999';  
					select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'EXPIRY_DATE_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')  
					Return;  
				End  
		End		
   
	-- check uom
	If ((select count(*) from t_wms_item_uom where item_master_id = @v_vchItemMasterID and uom_prompt = @in_vchUOM) <= 0)  
		Begin  
			set @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NOT_FOUND_UOM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchUOM,'@param3','@param4','@param5')  
			goto WRITE_PROC;     
		End  
  
	select @v_vchWarehouseItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID  
	-- check warehouse item  
	If(Isnull(@v_vchWarehouseItemMasterID,'') = '')  
		Begin   
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_ITEM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,@in_vchItem,'@param3','@param4','@param5')  
			Goto WRITE_PROC  
		End  
  
	-- check from location  
	If(Isnull(@in_vchLocation,'') <> '')  
		Begin  
			select @v_vchLocationID = location_id  
			from t_wms_location   
			where location = @in_vchLocation and wh_master_id = @v_vchWarehouseMasterID  
     
			If(Isnull(@v_vchLocationID,'') = '')  
				Begin   
					SET @out_vchErrorCode = '999';  
					select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLocation,'@param2','@param3','@param4','@param5')  
					Goto WRITE_PROC  
				End  
		End  
	Else  
		Begin  
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
			Goto WRITE_PROC     
		End  
         
	SET @v_vchFullControl = 'FULL';  
  
-----------------------------------------------------------------------------------  
	-- Check item uom ,conversion factor 
	select @v_fltUOMConFactor = conversion_factor ,  @v_vchUOMFromUOMPrompt = uom  
	from t_wms_item_uom   
	where item_master_id = @v_vchItemMasterID and uom_prompt = @in_vchUOM  
    
	If (Isnull(@v_fltUOMConFactor,'') = '')  
		Begin  
			SET @out_vchErrorCode = '999';  
			select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOM,'@param2','@param3','@param4','@param5')  
			Goto WRITE_PROC  
		End  
	Else  
		Begin  
			set @in_fltQty = @in_fltQty * @v_fltUOMConFactor;  
		End  
     
-----------------------------------------------------------------------------------  
	-- get inventory
	select @v_vchInventoryID = inventory_id,@v_vchAttributeGroupID = attribute_group_id,
	@v_fltExpectQuantity = quantity,@v_vchInventoryStatus = inv_status,@v_vchInventoryStatusID = inventory_status_id
	from v_wms_inventory_data  
	where wh_id = @in_vchWarehouse and  
	item_number = @in_vchItem and  
	location = @in_vchLocation and  
	isnull(serial_number,'') = isnull(@in_vchSerialNo,'') and
	isnull([expiry_date],'') = isnull(@in_vchExpiryDate,'') and
	isnull(lot_number,'') = isnull(@in_vchLot,'') and
	isnull(lpn,'') = isnull(@in_vchLPN,'')
    
	-- check rule for adjust stock  
	if ((select value from t_wms_rule where rule_code = 'RULE_ADJUST_INVENT') = 'YES')  
		Begin  
			
			set @v_vchAdjustValue = @in_fltQty - Isnull(@v_fltExpectQuantity,0);  
     
			Select @v_vchInventoryStatusID = inventory_status_id from t_wms_inventory_status where inv_status = @in_vchStatus or description = @in_vchStatus
					
			If (Isnull(@v_vchReceiveDate,'') = '')
				Begin
					set @v_vchReceiveDate = getdate();
				End

			exec usp_manage_inventory
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
			@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID,
			@in_vchLocationID = @v_vchLocationID,
			@in_vchLocation = @in_vchLocation,
			@in_vchStatusID = @v_vchInventoryStatusID,
			@in_vchLPN = @in_vchLPN,
			@in_vchLotNumber = @in_vchLot,
			@in_vchExpiryDate = @in_vchExpiryDate,
			@in_vchSerialNumber = @in_vchSerialNo,
			@in_fltQty = @v_vchAdjustValue,
			@in_fltQtyAllocate = 0,
			@in_vchOwner = @v_vchOwnerCode,
			@in_vchInventoryType = 'INVENTORY',
			@in_vchPalentLPN = @in_vchParentLPN,
			@in_vchUserID = @in_vchUserID,
			@in_vchReceiveDate = @v_vchReceiveDate,
			@in_vchInventoryID = @v_vchInventoryID output,
			@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
			@in_vchErrorCode = @out_vchErrorCode output,
			@in_vchMessage = @out_vchErrorMessage output
			If (@out_vchErrorCode <> '0')
				Goto WRITE_PROC;
									
			If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
				Begin
					exec usp_manage_inventory_attribute
							@in_vchApplicationID = @in_vchApplicationID,
							@in_vchItem = @in_vchItem,
							@in_vchSerialNo = @in_vchSerialNo,
							@in_vchLot = @in_vchLot,
							@in_vchExpiryDate = @in_vchExpiryDate,
							@in_fltQty = @v_vchAdjustValue,
							@in_fltQtyAllocate = 0,
							@in_vchInventoryID = @v_vchInventoryID,
							@in_vchAttributeGroupID = @v_vchAttributeGroupID,
							@in_vchLotControl = @v_vchLotControl,
							@in_vchSerialNumberControl = @v_vchSerialControl,
							@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
							@in_vchUserID = @in_vchUserID,
							@in_vchErrorCode = @out_vchErrorCode output,
							@in_vchMessage = @out_vchErrorMessage output			
					If(@out_vchErrorCode <> '0')
						Goto WRITE_PROC;
				End
			
			Goto COUNT_RECONCILE;

			--exec [usp_inventory_control]  
			--	@in_vchApplicationID = @in_vchApplicationID,  
			--	@in_vchWarehouse = @in_vchWarehouse,  
			--	@in_vchDevice = @in_vchDevice,  
			--	@in_vchTransactionType = @in_vchTransactionType,  
			--	@in_vchSubTranType = @in_vchSubTranType,  
			--	@in_vchUserID = @in_vchUserID,  
			--	@in_vchItem = @in_vchItem,  
			--	@in_fltQty = @v_vchAdjustValue,  
			--	@in_fltQtyAllocate = 0,  
			--	@in_vchUOM = @in_vchUOM,  
			--	@in_vchToLPN = @in_vchLPN,  
			--	@in_vchSerialNo = @in_vchSerialNo,  
			--	@in_vchToLot = @in_vchLot,  
			--	@in_vchToExpiryDate = @in_vchExpiryDate,  
			--	@in_vchToLocation = @in_vchLocation,  
			--	@in_vchToStatus = @in_vchStatus,  
			--	@in_vchReferenceNumber = @in_vchCountID,  
			--	@v_vchErrorCode = @out_vchErrorCode output,  
			--	@v_vchMessage = @out_vchMessage output  
  
			--If (@out_vchErrorCode <> '0')  
			--	Begin  
			--		set @v_WriteLog = 'YES';  
			--		Goto WRITE_PROC;  
			--	End  
			--Else  
			--	Begin  
			--		set @v_WriteLog = 'NO';  
			--		Goto COUNT_RECONCILE;  
			--	End  
		End  
	Else  
		Begin  
			Goto COUNT_RECONCILE;  
		End   
-----------------------------------------------------------------------------------  
	-- Write process log  
	COUNT_RECONCILE:  
 
	IF (@in_vchExpiryDate = '')
		BEGIN
			SET @in_vchExpiryDate = NULL
		END
  
	update t_wms_count_plan_detail set count_qty = @v_fltExpectQuantity
	where count_master_id = @v_vchCountMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID 
	and location_id = @v_vchLocationID and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchLPN,'')
	and isnull(lot,'') = isnull(@in_vchLot,'') and isnull(serial_number,'') = isnull(@in_vchSerialNo,'') and
	isnull([expiry_date],'') = isnull(@in_vchExpiryDate,'')

	insert into t_wms_count_reconcile(count_master_id, wh_item_master_id,inv_status, location_id,  
	lpn, lot, [expiry_date], serial_number, expect_qty, count_qty, adjusted_qty, adjust_by,  
	adjust_remark, create_by)  
	values(@v_vchCountMasterID,@v_vchWarehouseItemMasterID,@v_vchInventoryStatus,@v_vchLocationID,@in_vchLPN,@in_vchLot,  
	@in_vchExpiryDate,@in_vchSerialNo,isnull(@v_fltExpectQuantity,0),@in_fltQty,null,null,  
	@in_vchAdjustRemark,@in_vchUserID)  
	
	set @out_vchErrorCode = '0';  
	select @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')      
-----------------------------------------------------------------------------------   
    
-----------------------------------------------------------------------------------  
	--       Write process log  
	WRITE_PROC:         
	-----------------------------------------------------------------------------------   
	If (@v_WriteLog = 'YES')  
		Begin  
			SET @v_vchProcessData1 = 'Cycle count';  
			set @v_vchProcessData2 = 'Item number ' + @in_vchItem;  
  
			exec usp_LogManager  
				@in_vchApplicationID = @in_vchApplicationID,  
				@in_vchAppName = @v_vchApplicationName,  
				@in_vchWhID = @in_vchWarehouse,  
				@in_vchDevice = @in_vchDevice,  
				@in_vchUserID = @in_vchUserID,  
				@in_vchLogType = 'TRANSACTION',  
				@in_vchTranType = @in_vchTransactionType,  
				@in_vchSubTranType = @in_vchSubTranType,  
				@in_vchProcess = @c_vchObjName,  
				@in_dtProcessDateTime = @v_dtProcessDateTime,  
				@in_dtStartTranDate = @v_dtProcessDateTime,  
				@in_vchLPN = @in_vchLPN,  
				@in_vchItemNumber = @in_vchItem,  
				@in_vchLotNumber = @in_vchLot,  
				@in_dtExpiryDate = @in_vchExpiryDate,  
				@in_vchSerialNumber = @in_vchSerialNo,  
				@in_vchToLocation = @in_vchLocation,  
				@in_fltQuantity = @v_fltExpectQuantity,  
				@in_fltAfterQuantity = @in_fltQty,  
				@in_vchReferenceNumber = @in_vchCountID,  
				@in_vchUOM = @v_vchUOMFromUOMPrompt,  
				@in_vchAfterUOM = @v_vchUOMFromUOMPrompt,  
				@in_vchData1 = @v_vchProcessData1,  
				@in_vchData2 = @v_vchProcessData2,  
				@in_vchData3 = @v_vchProcessData3,  
				@in_vchData4 = @v_vchProcessData4,  
				@in_vchErrorCode = @out_vchErrorCode,  
				@in_vchMessage = @out_vchErrorMessage
				return;   
		End   
-----------------------------------------------------------------------------------   
   
 End Try  
 Begin Catch  
   
   SELECT   
   @v_intSqlErrorNumber = ERROR_NUMBER(),  
   @v_vchSqlErrorMessage = ERROR_MESSAGE(),  
   @v_intSqlErrorState = ERROR_STATE(),  
   @v_intSqlErrorSeverity = ERROR_SEVERITY(),  
   @v_intSqlErrorLine = ERROR_LINE(),  
   @v_vchSqlErrorProcedure = ERROR_PROCEDURE()  
     
   SET @out_vchErrorMessage = @v_vchSqlErrorProcedure + ': ' + @out_vchErrorMessage   
        + '. SQL Error ['+ str(@v_intSqlErrorNumber) + '], '  
        + '. Severity ['+ str(@v_intSqlErrorSeverity) + '],'  
        + '. State ['+ str(@v_intSqlErrorState) + '],'  
        + '. State ['+ str(@v_intSqlErrorState) + '].'  
   If(isnull(@out_vchErrorMessage,'') = '')  
    SET @out_vchErrorMessage = 'SQL Error';  
  
   SET  @v_vchProcessData1 = @out_vchErrorMessage;  
   SET  @v_vchProcessData2 = @v_vchSqlErrorMessage;  
   SET  @v_vchProcessData3 = 'Cycle count';  
   SET  @v_vchProcessData4 = '';  
     
   SET @out_vchErrorCode = @v_intSqlErrorNumber;  
   SET @out_vchErrorMessage = @v_vchSqlErrorMessage;  
    
  exec usp_LogManager  
   @in_vchApplicationID = @in_vchApplicationID,  
   @in_vchAppName = @v_vchApplicationName,  
   @in_vchWhID = @in_vchWarehouse,  
   @in_vchDevice = @in_vchDevice,  
   @in_vchUserID = @in_vchUserID,  
   @in_vchLogType = 'TRANSACTION',  
   @in_vchTranType = @in_vchTransactionType,  
   @in_vchSubTranType = @in_vchSubTranType,  
   @in_vchProcess = @c_vchObjName,  
   @in_dtProcessDateTime = @v_dtProcessDateTime,  
   @in_dtStartTranDate = @v_dtProcessDateTime,  
   @in_vchLPN = @in_vchLPN,  
   @in_vchItemNumber = @in_vchItem,  
   @in_vchLotNumber = @in_vchLot,  
   @in_dtExpiryDate = @in_vchExpiryDate,  
   @in_vchSerialNumber = @in_vchSerialNo,  
   @in_vchToLocation = @in_vchLocation,  
   @in_fltQuantity = @v_fltExpectQuantity,  
   @in_fltAfterQuantity = @in_fltQty,  
   @in_vchReferenceNumber = @in_vchCountID,  
   @in_vchUOM = @v_vchUOMFromUOMPrompt,  
   @in_vchAfterUOM = @v_vchUOMFromUOMPrompt,  
   @in_vchData1 = @v_vchProcessData1,  
   @in_vchData2 = @v_vchProcessData2,  
   @in_vchData3 = @v_vchProcessData3,  
   @in_vchData4 = @v_vchProcessData4,  
   @in_vchErrorCode = @out_vchErrorCode,  
   @in_vchMessage = @out_vchErrorMessage  
 End Catch  
   
End

GO
/****** Object:  StoredProcedure [dbo].[usp_exec_host_item_job]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_exec_host_item_job]
AS

IF NOT EXISTS (SELECT host_record_id FROM t_host_wms_item_master WHERE processing_status = 'PENDING')
	BEGIN
		UPDATE t_host_wms_item_master set processing_status = 'PENDING' WHERE host_record_id IN (SELECT TOP 40 host_record_id FROM t_host_wms_item_master WHERE processing_status = 'PENDING-T')
		UPDATE t_host_wms_item_uom set processing_status = 'PENDING' WHERE host_record_id IN (SELECT host_record_id FROM t_host_wms_item_master WHERE processing_status = 'PENDING')
		UPDATE t_host_wms_item_crossref set processing_status = 'PENDING' WHERE host_record_id IN (SELECT host_record_id FROM t_host_wms_item_master WHERE processing_status = 'PENDING')


		DECLARE @v_vchApplicationID		VARCHAR(40),
		@v_vchApplicationName	VARCHAR(50)
 
		 SET @v_vchApplicationID = 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'
		 SET @v_vchApplicationName = 'WM3'

		--ITEM_NUMBER
		EXEC usp_ExecuteHostItemMaster @in_vchApplicationID   = @v_vchApplicationID
  									  ,@in_vchApplicationName = @v_vchApplicationName
	END



GO
/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostAdjustment]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ExecuteHostAdjustment]
	@v_vchInterfaceID	NVARCHAR(20)
AS
BEGIN
	DECLARE 
		@v_vchMatDoc		NVARCHAR(10),
		@v_vchHostMsg		NVARCHAR(100)
		
		
	SELECT 
		 @v_vchMatDoc = material_document
		,@v_vchHostMsg = host_message
	FROM t_host_wms_interface_header
	WHERE interface_id = @v_vchInterfaceID

	/*control_number : ใน Table t_com_tran_log คือข้อมูลเดียวกันกับ interface_id ใน Table t_host_wms_interface_header*/
	UPDATE t_com_tran_log SET control_value_1 = @v_vchMatDoc, control_value_2 = @v_vchHostMsg
	WHERE control_number = @v_vchInterfaceID
END


GO
/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostCarrier]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_ExecuteHostCarrier]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchApplicationName			NVARCHAR(100)			--Required
AS 
BEGIN
	DECLARE 
	 @v_vchHostRecordID		VARCHAR(40),
	 @v_vchCarrireCode		NVARCHAR(50),
	 @v_vchDevice			NVARCHAR(50) = 'HOST INTERFACE',
	 @v_vchUserID           NVARCHAR(10) = 'OGA HOST INTERFACE',
	 @v_vchLogType			NVARCHAR(50) = 'ERROR',
	 @v_vchProcess			NVARCHAR(50) = 'HOST MANAGER EXECUTE'

	DECLARE Carrire_Cursor CURSOR FOR
		SELECT host_record_id
			,carrier_code
		FROM t_host_wms_carrier 
		WHERE processing_status = 'PENDING'
	OPEN Carrire_Cursor
	
	FETCH NEXT FROM Carrire_Cursor INTO @v_vchHostRecordID, @v_vchCarrireCode
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--exec sp
		EXECUTE usp_ProcessHostCarrier @in_vchApplicationID, @in_vchApplicationName, @v_vchHostRecordID, @v_vchCarrireCode, @v_vchDevice
							,@v_vchUserID, @v_vchLogType, @v_vchProcess, NULL

		FETCH NEXT FROM Carrire_Cursor INTO @v_vchHostRecordID, @v_vchCarrireCode
	END	  
	       
	CLOSE Carrire_Cursor                  	
	DEALLOCATE Carrire_Cursor
END


