/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostInboundOrder]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_ExecuteHostInboundOrder]
	@in_vchApplicationID	VARCHAR(40),			--Required
	@in_vchApplicationName	NVARCHAR(100),			--Required
	@out_ErrorCode			NVARCHAR(50) OUTPUT 
AS 
BEGIN 
	DECLARE @v_vchHostRecordID	VARCHAR(40) 
	DECLARE @v_vchDevice		NVARCHAR(50) = 'HOST INTERFACE'
	DECLARE @v_vchUserID        VARCHAR(25) = 'HIM'
	 
	DECLARE @v_vchWarehouse		  VARCHAR(25)
	DECLARE @v_vchInboundNumber	  VARCHAR(40)
	DECLARE @v_vchOrderType		  NVARCHAR(30)

	DECLARE @v_fltLastNumber	FLOAT = NULL
	DECLARE @v_fltNextNumber	FLOAT = NULL
	DECLARE @v_vchMaxID			VARCHAR(40) = NULL
	DECLARE @v_vchNewHostRecordID	VARCHAR(40) = NULL
	DECLARE @out_vchErrorMessage NVARCHAR(500)

	DECLARE InboundOrder_Cursor CURSOR FOR
		SELECT host_record_id
			,wh_id
			,order_number
			,type
		FROM t_host_wms_inbound_order 
		WHERE processing_status = 'PENDING'
		ORDER BY insert_date 
	OPEN InboundOrder_Cursor 
	FETCH NEXT FROM InboundOrder_Cursor INTO @v_vchHostRecordID,@v_vchWarehouse,@v_vchInboundNumber,@v_vchOrderType
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'HIM_GENERATE_HOST_RUNNING' AND is_active = 'YES') = 'YES'
			BEGIN
				--Set Running
				SET @v_fltLastNumber = NULL
				SET @v_fltNextNumber = NULL
				SELECT @v_vchMaxID = MAX(host_record_id) FROM t_host_wms_inbound_order WHERE host_record_id LIKE @v_vchHostRecordID + '%'

				IF(ISNULL(@v_vchMaxID,'') = '' OR SUBSTRING(RIGHT(@v_vchMaxID,3),1,1) <> '-')
					BEGIN
						SET @v_fltLastNumber = 0
					END
				ELSE
					BEGIN
						SET @v_fltLastNumber = CONVERT(FLOAT,RIGHT(@v_vchMaxID,2))
					END

				SET @v_fltNextNumber = @v_fltLastNumber + 1;
				SET	@v_vchNewHostRecordID = @v_vchHostRecordID + '-' +  RIGHT('00'+CONVERT(VARCHAR(20),@v_fltNextNumber),2)

				UPDATE t_host_wms_inbound_order			SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING'
				UPDATE t_host_wms_inbound_order_detail	SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING' 
				UPDATE t_host_wms_inbound_order_comment SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING'
			END
		ELSE
			BEGIN
				SET @v_vchNewHostRecordID = @v_vchHostRecordID
			END
		--exec sp
		EXECUTE usp_ProcessHostInboundOrder @in_vchApplicationID = @in_vchApplicationID
									   ,@in_vchApplicationName	= @in_vchApplicationName
									   ,@in_vchHostRecordID		= @v_vchNewHostRecordID
									   ,@in_vchDevice			= @v_vchDevice
									   ,@in_vchUserID			= @v_vchUserID
									   ,@out_vchErrorCode		= @out_ErrorCode OUTPUT
									   ,@out_vchErrorMessage	= @out_vchErrorMessage OUTPUT
		IF @out_ErrorCode = '0'
			BEGIN
				IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'INF_ORDER_TYPE_AUTO_RECEIPT' AND is_active = 'YES')
					BEGIN
						DECLARE @v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL
			
						SELECT @v_vchInboundMasterID = inbound_order_master_id
						FROM t_wms_inbound_master 
						WHERE inbound_order_number = @v_vchInboundNumber 
						AND wh_id = @v_vchWarehouse

						EXEC usp_inbound_volumn_auto_receive_qty @in_vchApplicationID	= @in_vchApplicationID
																,@in_vchInboundMasterID	= @v_vchInboundMasterID
																,@in_vchDeviceID		= @v_vchDevice
																,@in_vchUserID			= @v_vchUserID
																,@out_ErrorCode			= @out_ErrorCode OUTPUT
																,@out_ErrorMessage		= NULL 

					END
			END

		FETCH NEXT FROM InboundOrder_Cursor INTO @v_vchHostRecordID,@v_vchWarehouse,@v_vchInboundNumber,@v_vchOrderType
	END	  
	       
	CLOSE InboundOrder_Cursor                  	
	DEALLOCATE InboundOrder_Cursor
END



/*
DECLARE @out_ErrorCode	 NVARCHAR(50)
EXEC usp_ExecuteHostInboundOrder @in_vchApplicationID	= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'
								,@in_vchApplicationName	= 'WM3'
								,@out_ErrorCode			= @out_ErrorCode output

SELECT @out_ErrorCode	
*/

/*
----SELECT CONVERT(VARCHAR(8),GETDATE(),112)
----+ RIGHT('00'+CONVERT(VARCHAR(2),DATEPART(HOUR,GETDATE())),2)
----+ RIGHT('00'+CONVERT(VARCHAR(2),DATEPART(MINUTE,GETDATE())),2)
----+ RIGHT('00'+CONVERT(VARCHAR(2),DATEPART(SECOND,GETDATE())),2)
----+ LEFT(CONVERT(VARCHAR(6),DATEPART(MICROSECOND,GETDATE())),3)


declare @p3 nvarchar(50)
set @p3=NULL
exec usp_ExecuteHostInboundOrder @in_vchApplicationID='CC3D76CA-71B9-47CB-A933-4B1F1F489AF0',@in_vchApplicationName='WM3',@out_ErrorCode=@p3 output
select @p3
*/
