	DECLARE @v_fltNextNumber	FLOAT = NULL
	DECLARE @v_vchMaxID			VARCHAR(40) = NULL
	DECLARE @v_vchNewHostRecordID	VARCHAR(40) = NULL
	DECLARE @out_vchErrorMessage NVARCHAR(500)

	DECLARE OutboundOrder_Cursor CURSOR FOR
		SELECT host_record_id 
		FROM t_host_wms_outbound_order 
		WHERE processing_status = 'PENDING'
		ORDER BY insert_date
	OPEN OutboundOrder_Cursor
	FETCH NEXT FROM OutboundOrder_Cursor INTO @v_vchHostRecordID
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'HIM_GENERATE_HOST_RUNNING' AND is_active = 'YES') = 'YES'
			BEGIN
				--Set Running
				SET @v_fltLastNumber = NULL
				SET @v_fltNextNumber = NULL
				SELECT @v_vchMaxID = MAX(host_record_id) FROM t_host_wms_outbound_order WHERE host_record_id LIKE @v_vchHostRecordID + '%'

				IF(ISNULL(@v_vchMaxID,'') = '' OR SUBSTRING(RIGHT(@v_vchMaxID,3),1,1) <> '-')
					BEGIN
						SET @v_fltLastNumber = 0
					END
				ELSE
					BEGIN
						SET @v_fltLastNumber = CONVERT(FLOAT,RIGHT(@v_vchMaxID,2))
					END

				SET @v_fltNextNumber = @v_fltLastNumber + 1;
				SET	@v_vchNewHostRecordID = @v_vchHostRecordID + '-' +  RIGHT('00'+CONVERT(VARCHAR(20),@v_fltNextNumber),2)

				UPDATE t_host_wms_outbound_order		 SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING'
				UPDATE t_host_wms_outbound_order_detail  SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING' 
				UPDATE t_host_wms_outbound_order_comment SET host_record_id = @v_vchNewHostRecordID WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'PENDING'
			END
		ELSE
			BEGIN
				SET @v_vchNewHostRecordID = @v_vchHostRecordID
			END

		--exec sp
		EXECUTE usp_ProcessHostOutboundOrder @in_vchApplicationID	= @in_vchApplicationID
										   ,@in_vchApplicationName	= @in_vchApplicationName
										   ,@in_vchHostRecordID		= @v_vchNewHostRecordID
										   ,@in_vchDevice			= @v_vchDevice
										   ,@in_vchUserID			= @v_vchUserID
										   ,@out_vchErrorCode		= @out_ErrorCode OUTPUT
										   ,@out_vchErrorMessage	= @out_vchErrorMessage OUTPUT

		FETCH NEXT FROM OutboundOrder_Cursor INTO @v_vchHostRecordID
	END	  
	       
	CLOSE OutboundOrder_Cursor
	DEALLOCATE OutboundOrder_Cursor
END


/*
--UPDATE t_host_wms_outbound_order SET processing_status = 'PENDING-T' where  processing_status = 'PENDING'
--UPDATE t_host_wms_outbound_order SET processing_status = 'PENDING' 
--where processing_status = 'PENDING-T' AND host_record_id IN (SELECT top 30 host_record_id FROM t_host_wms_outbound_order WHERE processing_status = 'PENDING-T')


DECLARE @out_ErrorCode	 NVARCHAR(50)
EXEC usp_ExecuteHostOutboundOrder @in_vchApplicationID	= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'
								,@in_vchApplicationName	= 'WM3'
								,@out_ErrorCode			= @out_ErrorCode output

SELECT @out_ErrorCode
*/
GO
/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostPurchase]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ExecuteHostPurchase]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchApplicationName			NVARCHAR(100)			--Required
AS 
BEGIN
	DECLARE
	 
	 -- Error handling variables
	@c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
	@v_intLocale			INTEGER, 
	@v_vchTableName			NVARCHAR(50),
	@v_vchLogType			NVARCHAR(50),
	@v_vchDevice			NVARCHAR(50),

	@v_intSqlErrorNumber    INTEGER,
	@v_intSqlErrorLine		INTEGER,
	@v_intSqlErrorState		INTEGER,
	@v_intSqlErrorSeverity	INTEGER,
	@v_vchSqlErrorMessage	NVARCHAR(2048),
	@v_vchSqlErrorProcedure NVARCHAR(200),  
	@v_vchProcessData1		NVARCHAR(100),
	@v_vchProcessData2		NVARCHAR(100),
	@v_vchProcessData3		NVARCHAR(100),
	@v_vchProcessData4		NVARCHAR(100),
	
    --  Log Handling Variables
	@v_intLogLevel          INTEGER = 3,			-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	@v_vchLogAction			NVARCHAR(25) = 'PRINT',  -- PRINT, LOG,
	@v_vchErrorCode			NVARCHAR(200),
	@v_vchMessage           NVARCHAR(500),
	@in_vchRefID			varchar(40)
	--------------------------------------------------------------  
	-- Set Constants and Variables  
	-------------------------------------------------------------- 
	SET @v_intLocale = 1033; -- English
	SET @c_vchObjName = 'usp_ProcessHostPurchase'; 
	SET @v_vchTableName = 't_host_wms_purchase'; 
	SET @v_vchLogType = 'ERROR IMPORT';
	SET @v_vchDevice = 'usp_ProcessHostPurchase' 

BEGIN TRY  
	BEGIN TRANSACTION;
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log      
	SET @in_vchRefID = NEWID()
	SELECT p.[purchase_id]
		 , p.[processing_code]
		 , p.[processing_status]
		 , p.[purchase_number]
		 , item.item_master_id
		 , p.[item_number]
		 , item.description as item_description
		 , p.[purchase_qty]
		 , p.[purchase_uom]
		 , p.[required_date]
		 , p.[requisitioner]
		 , p.[create_by]
	INTO #tPurchasePending
	FROM [dbo].[t_host_wms_purchase] p
	LEFT JOIN t_wms_item item ON p.item_number = item.item_number
	WHERE processing_status = 'PENDING'
	
	IF EXISTS (SELECT purchase_id FROM #tPurchasePending WHERE ISNULL(item_master_id,'') = '')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-IFMAN-015' -- Invalid Item Number
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
			SELECT @v_vchProcessData2 += ' Purchase Number: [' + ISNULL(purchase_number, '') + ']'		
										+ ' Item Number: [' + ISNULL(item_number, '') + ']'
			FROM #tPurchasePending
			WHERE ISNULL(item_master_id,'') = ''

			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END
	
	DELETE FROM [t_wms_purchase] WHERE purchase_number IN (SELECT purchase_number FROM #tPurchasePending)
	INSERT INTO [dbo].[t_wms_purchase]
			([purchase_id]
			,[purchase_number]
			,[item_master_id]
			,[item_number]
			,[item_description]
			,[purchase_qty]
			,[purchase_uom]
			,[required_date]
			,[requisitioner]
			,[create_by]
			,[create_date])
		SELECT NEWID()
			,purchase_number
			,item_master_id
			,item_number
			,item_description
			,purchase_qty
			,purchase_uom
			,required_date
			,requisitioner
			,create_by
			,GETDATE()
		FROM #tPurchasePending

	UPDATE t_host_wms_purchase SET processing_status = 'COMPLETE',interface_complete_date = GETDATE(), ref_id = @in_vchRefID
	WHERE processing_status = 'PENDING'

	DROP TABLE #tPurchasePending
	------------------------------------------------------------  
	--  Finished All. Now Exit SPROC  
	COMMIT TRANSACTION;
	------------------------------------------------------------  
	GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
-- WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:  
	ROLLBACK TRANSACTION  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@in_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@v_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
	END
	 
	INSERT INTO [dbo].[t_com_process_log]
		([app_id]
		,[log_type]
		,[warehouse]
		,[device]
		,[process]
		,[process_datetime]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[message]
		,[create_date]
		,[create_by])
	VALUES
		( LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
		, LEFT(ISNULL('', 'NO WH DEFINED'), 25)
		, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
		, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
		, GETDATE()
		, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
		, LEFT(@v_vchProcessData2, 1000)
		, LEFT(@v_vchProcessData3, 1000)
		, LEFT(@v_vchProcessData4, 1000)
		, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
		, GETDATE()
		, 'OGA')

	
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_purchase SET processing_status = 'ERROR' WHERE processing_status = 'PENDING'

	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	ROLLBACK TRANSACTION
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id]
			   ,[log_type]
			   ,[warehouse]
			   ,[device]
			   ,[process]
			   ,[process_datetime]
			   ,[data_1]
			   ,[data_2]
			   ,[data_3]
			   ,[data_4]
			   ,[message]
			   ,[create_date]
			   ,[create_by])
		 VALUES
		 		(LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
		 		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL('', 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, GETDATE()
				, 'OGA')	
			
		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  

		UPDATE t_host_wms_purchase SET processing_status = 'ERROR' WHERE processing_status = 'PENDING'

END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END


GO
