CREATE PROCEDURE [dbo].[usp_ExecuteHostTransferOrder]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchApplicationName			NVARCHAR(100)			--Required
AS 
BEGIN
	DECLARE 
	 @v_vchHostRecordID		VARCHAR(40),
	 @v_vchOrderNumber		NVARCHAR(50),
	 @v_vchDevice			NVARCHAR(50) = 'HOST INTERFACE',
	 @v_vchUserID           NVARCHAR(10) = 'OGA HOST INTERFACE',
	 @v_vchLogType			NVARCHAR(50) = 'ERROR',
	 @v_vchProcess			NVARCHAR(50) = 'HOST MANAGER EXECUTE',
	 @v_vchErrorCode		INT

	DECLARE TransferOrder_Cursor CURSOR FOR
		SELECT host_record_id
			,order_number
		FROM t_host_wms_transfer_order
		WHERE processing_status = 'PENDING'
		ORDER BY create_date
	
	OPEN TransferOrder_Cursor
	
	FETCH NEXT FROM TransferOrder_Cursor INTO @v_vchHostRecordID, @v_vchOrderNumber
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		
		EXECUTE usp_ProcessHostTransferOrderSinglePlant @in_vchApplicationID, @in_vchApplicationName, @v_vchHostRecordID, @v_vchOrderNumber, @v_vchDevice
							,@v_vchUserID, @v_vchLogType, @v_vchProcess, @v_vchErrorCode OUTPUT

		FETCH NEXT FROM TransferOrder_Cursor INTO @v_vchHostRecordID, @v_vchOrderNumber
		
	END	  
	       
	CLOSE TransferOrder_Cursor                  	
	DEALLOCATE TransferOrder_Cursor
END


