/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostUpdateCostAndStock]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ExecuteHostUpdateCostAndStock]
	@v_vchCountID			NVARCHAR(40)=NULL,
	@v_vchItemNumber		NVARCHAR(50)=NULL,	--item_number
	@v_vchInvStatus			NVARCHAR(50)=NULL,	--inv_status
	@v_flSAPStock			FLOAT=NULL,			--sap_stock
	@v_flCost				FLOAT=NULL,			--cost        
	@v_flSTPRS				FLOAT=NULL			--
AS  
BEGIN  

	UPDATE  t_wms_count_reconcile SET cost = @v_flCost, host_qty = @v_flSAPStock
	WHERE count_reconcile_id in (SELECT count_reconcile_id 
								 FROM v_wms_count_reconcile 
								 WHERE item_number = @v_vchItemNumber
								 AND count_id = @v_vchCountID
								 AND inv_status = @v_vchInvStatus)	
RETURN @@Rowcount
END


