CREATE PROCEDURE [dbo].[usp_ExecuteHostUpdateExpiration]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchApplicationName			NVARCHAR(100)			--Required
AS 
BEGIN
	DECLARE 
	 @v_vchHostRecordID		VARCHAR(40),
	 @v_vchDevice			NVARCHAR(50) = 'HOST INTERFACE',
	 @v_vchUserID           NVARCHAR(10) = 'OGA HOST INTERFACE',
	 @v_vchLogType			NVARCHAR(50) = 'ERROR',
	 @v_vchProcess			NVARCHAR(50) = 'HOST MANAGER EXECUTE',
	 @v_vchErrorCode		INT

	DECLARE UpdateExpiration_Cursor CURSOR FOR
		SELECT host_record_id
		FROM t_host_wms_update_expiration 
		WHERE processing_status = 'PENDING'
		Order by item_number,batch_code,expiry_date
	
	OPEN UpdateExpiration_Cursor
	
	FETCH NEXT FROM UpdateExpiration_Cursor INTO @v_vchHostRecordID
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		
		EXECUTE [usp_ProcessHostUpdateExpiration] @in_vchApplicationID, @in_vchApplicationName, @v_vchHostRecordID, @v_vchDevice
				,@v_vchUserID, @v_vchLogType, @v_vchProcess

		FETCH NEXT FROM UpdateExpiration_Cursor INTO @v_vchHostRecordID
		
	END	  
	       
	CLOSE UpdateExpiration_Cursor                  	
	DEALLOCATE UpdateExpiration_Cursor
END


