/****** Object:  StoredProcedure [dbo].[usp_ExecuteHostUpdateResult]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ExecuteHostUpdateResult]
	@v_vchInterfaceId				VARCHAR(50)
AS
BEGIN
	DECLARE @v_vchOutboundOrderMasterID		VARCHAR(40),
			@v_vchInboundOrderMasterID		VARCHAR(40),
			@v_intCountSeq					INT,
			@v_dtCreateDate					DATETIME,
			@v_vchUserID					VARCHAR(40),
			@v_vchOrderNumber				VARCHAR(50),
			@v_vchProcessingStatus			VARCHAR(10),
			@v_vchResultStatus				VARCHAR(1000),
			@v_vchMaterialDocument			VARCHAR(1000),
			@v_vchDeliveryNumber			VARCHAR(1000),
			@v_vchHostMessage				VARCHAR(1000),
			@v_vchMovementType				VARCHAR(3),
			@v_intCountRowInterface			int
	------------------------------------------------------------------------
	--กรณี Movement Type = SO พี่นึง Map field ผิด เอา delivery number มาใส่ใน Mat doc
	------------------------------------------------------------------------

	--SELECT @v_vchMaterialDocument = material_document
	--FROM t_host_wms_interface_header 
	--WHERE interface_id = @v_vchInterfaceId 
	
	--UPDATE t_host_wms_interface_header SET 
	--	 delivery_number = @v_vchMaterialDocument 
	--	, material_document = NULL
	--WHERE interface_id = @v_vchInterfaceId 
	--AND move_type = 'SO' 

	SELECT 
		 @v_vchOrderNumber = wms_order_no
		,@v_vchProcessingStatus = processing_status
		,@v_vchResultStatus = result_status
		,@v_vchMaterialDocument = material_document
		,@v_vchDeliveryNumber = delivery_number
		,@v_vchHostMessage = host_message
		,@v_dtCreateDate = create_date
		,@v_vchUserID = user_id
	FROM t_host_wms_interface_header 
	WHERE  interface_id = @v_vchInterfaceId
			
	SELECT @v_vchOutboundOrderMasterID = outbound_order_master_id 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @v_vchOrderNumber
	
	IF @v_vchOutboundOrderMasterID <> ''
		BEGIN
			--พบข้อมูลใน Outbound
			SELECT @v_intCountSeq = COUNT(*) + 1  FROM t_wms_outbound_interface_result
			WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
	
			INSERT INTO t_wms_outbound_interface_result
			(
				 outbound_order_master_id
				,result_type
				,order_number
				,sequence
				,interface_id
				,processing_status
				,result_status
				,material_document
				,delivery_number
				,host_message
				,create_date
				,create_by
			)
			VALUES
			(
				 @v_vchOutboundOrderMasterID
				,'InterfaceResult'
				,@v_vchOrderNumber
				,@v_intCountSeq
				,@v_vchInterfaceId
				,@v_vchProcessingStatus
				,@v_vchResultStatus
				,@v_vchMaterialDocument
				,@v_vchDeliveryNumber
				,@v_vchHostMessage
				,@v_dtCreateDate
				,@v_vchUserID
			)
			
			--Insert Data for Delivery Report
			(SELECT @v_intCountRowInterface = COUNT(*) 
			FROM t_wms_outbound_delivery_report 
			WHERE interface_id = @v_vchInterfaceId)
			IF @v_intCountRowInterface = 0
				BEGIN
					INSERT INTO t_wms_outbound_delivery_report 
					(
						interface_id
						,wh_id
						,outbound_order_number
						,ship_date_actual
						,delivery_number
						,customer_code
						,customer_name
						,customer_code_name
						,line_number
						,item_number
						,quantity_ship
						,uom_prompt
						,item_description
						,price
						,grade
						,brand_name
						,total_price
						,outbound_order_master_id
						,sum_total_price
					)
					(SELECT 
						interface_id
						,wh_id
						,outbound_order_number
						,ship_date_actual
						,delivery_number
						,customer_code
						,customer_name
						,customer_code_name
						,line_number
						,item_number
						,quantity_ship
						,uom_prompt
						,item_description
						,price
						,grade
						,brand_name
						,total_price
						,outbound_order_master_id
						,sum_total_price
					FROM v_wms_outbound_temp_delivery_report 
					WHERE interface_id = @v_vchInterfaceId)
				END
		END
	ELSE
		BEGIN
			SELECT @v_vchInboundOrderMasterID = inbound_order_master_id 
			FROM t_wms_inbound_master 
			WHERE inbound_order_number = @v_vchOrderNumber
			
			IF (@v_vchInboundOrderMasterID <> '')
				BEGIN
					--พบข้อมูลใน Inbound
					SELECT @v_intCountSeq = COUNT(*) + 1  FROM t_wms_inbound_interface_result
					WHERE inbound_order_master_id = @v_vchInboundOrderMasterID
			
					INSERT INTO t_wms_inbound_interface_result
					(
						 inbound_order_master_id
						,result_type
						,order_number
						,sequence
						,interface_id
						,processing_status
						,result_status
						,material_document
						,delivery_number
						,host_message
						,create_date
						,create_by
					)
					VALUES
					(
						 @v_vchInboundOrderMasterID
						,'InterfaceResult'
						,@v_vchOrderNumber
						,@v_intCountSeq
						,@v_vchInterfaceId
						,@v_vchProcessingStatus
						,@v_vchResultStatus
						,@v_vchMaterialDocument
						,@v_vchDeliveryNumber
						,@v_vchHostMessage
						,@v_dtCreateDate
						,@v_vchUserID
					)
				END
		END
END	


GO
/****** Object:  StoredProcedure [dbo].[usp_ExecuteOutboundComment]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ExecuteOutboundComment]
	@v_vchOutboundOrderNumber		VARCHAR(50),
	@v_vchInterfaceId				VARCHAR(50),
	@v_vchProcessingStatus			VARCHAR(10),
	@v_vchResultStatus				VARCHAR(1000),
	@v_vchMaterialDocument			VARCHAR(1000),
	@v_vchDeliveryNumber			VARCHAR(1000),
	@v_vchHostMessage				VARCHAR(1000)
AS
BEGIN
	DECLARE @v_vchOutboundOrderMasterID		VARCHAR(40),
			@v_vchInboundOrderMasterID		VARCHAR(40),
			@v_intCountSeq					INT,
			@v_dtCreateDate					DATETIME,
			@v_vchUserID					VARCHAR(40)

	SELECT @v_dtCreateDate = create_date
		,@v_vchUserID = user_id
	FROM t_host_wms_interface_header 
	WHERE  interface_id = @v_vchInterfaceId
			
	SELECT @v_vchOutboundOrderMasterID = outbound_order_master_id 
	FROM t_wms_outbound_master 
	WHERE outbound_order_number = @v_vchOutboundOrderNumber
	
	IF @v_vchOutboundOrderMasterID <> ''
		BEGIN
			--พบข้อมูลใน Outbound
			SELECT @v_intCountSeq = COUNT(*) + 1  FROM t_wms_outbound_comment
			WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
	
			INSERT INTO t_wms_outbound_comment
			(
				 outbound_order_master_id
				,comment_type
				,comment
				,sequence
				,comment_postion
				,comment_detail_line_1
				,comment_detail_line_2
				,comment_detail_line_3
				,comment_detail_line_4
				,comment_detail_line_5
				,comment_detail_line_6
				,create_date
				,create_by
			)
			VALUES
			(
				 @v_vchOutboundOrderMasterID
				,'InterfaceResult'					--comment_type
				,@v_vchOutboundOrderNumber			--comment
				,@v_intCountSeq						--sequence
				,NULL								--comment_postion
				,@v_vchInterfaceId					--comment_detail_line_1
				,@v_vchProcessingStatus				--comment_detail_line_2
				,@v_vchResultStatus					--comment_detail_line_3
				--พี่นึงส่ง field Delivery Number มาที่ Material doc
				,@v_vchDeliveryNumber	--@v_vchMaterialDocument			--comment_detail_line_4
				,@v_vchMaterialDocument	--@v_vchDeliveryNumber				--comment_detail_line_5
				,@v_vchHostMessage					--comment_detail_line_6
				,@v_dtCreateDate					--create_date
				,@v_vchUserID						--create_by
			)
			
			UPDATE t_host_wms_interface_header SET delivery_number = @v_vchMaterialDocument 
			WHERE interface_id = @v_vchInterfaceId
		END
	ELSE
		BEGIN
			SELECT @v_vchInboundOrderMasterID = inbound_order_master_id 
			FROM t_wms_inbound_master 
			WHERE inbound_order_number = @v_vchOutboundOrderNumber
			
			IF (@v_vchInboundOrderMasterID <> '')
				BEGIN
					--พบข้อมูลใน Inbound
					SELECT @v_intCountSeq = COUNT(*) + 1  FROM t_wms_inbound_comment
					WHERE inbound_order_master_id = @v_vchInboundOrderMasterID
			
					INSERT INTO t_wms_inbound_comment
					(
						 inbound_order_master_id
						,comment_type
						,comment
						,sequence
						,comment_detail_line_1
						,comment_detail_line_2
						,comment_detail_line_3
						,comment_detail_line_4
						,comment_detail_line_5
						,comment_detail_line_6
						,create_date
						,create_by
					)
					VALUES
					(
						 @v_vchInboundOrderMasterID
						,'InterfaceResult'
						,@v_vchOutboundOrderNumber
						,@v_intCountSeq
						,@v_vchInterfaceId
						,@v_vchProcessingStatus
						,@v_vchResultStatus
						,@v_vchMaterialDocument
						,@v_vchDeliveryNumber
						,@v_vchHostMessage
						,@v_dtCreateDate
						,@v_vchUserID
					)
				END
		END
END


