/****** Object:  StoredProcedure [dbo].[USP_GENERATE_INVENTORY_DATAS]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-01-17
-- Description:	Stores procedure for generate 
-- inventory data.>For test performance
-- =============================================
CREATE PROCEDURE [dbo].[USP_GENERATE_INVENTORY_DATAS]
	@IN_VCH_WAREHOUSE	NVARCHAR(50),
	@IN_FLT_TOTALRECORD	FLOAT
AS
BEGIN

	SET NOCOUNT ON;

	
	DECLARE 		
			-- ITEM VARIABLE
			@V_VCH_OWNER_ID				VARCHAR(40),
			@V_VCH_WH_ITEM_MASTER_ID	VARCHAR(40),
			@V_VCH_LOT_CONTROL			NVARCHAR(5),
			@V_VCH_EXPIRY_DATE_CONTROL	NVARCHAR(5),
			@V_VCH_SERIAL_CONTROL		NVARCHAR(5),
			@V_VCH_LOT_NUMBER			NVARCHAR(50),
			@V_VCH_EXPIRY_DATE			NVARCHAR(50),
			@V_VCH_SERIAL_NUMBER		NVARCHAR(50),

			@V_FLT_QUANTITY_OF_ITEM		INT,
			@V_FLT_ROW_OF_ITEM			INT,

			-- WAREHOUSE VARIABLE
			@V_VCH_WAREHOUSE_MASTER_ID	VARCHAR(40),
			@V_VCH_PARENT_CONTROL		NVARCHAR(3),
			@V_VCH_PARENT_LPN			NVARCHAR(25),
			@V_VCH_LPN					NVARCHAR(25),
			@V_VCH_PREFIX_PARENT_LPN	NVARCHAR(10) = 'PARENT',
			@V_FLT_RUNNING_PARENT_LPN	FLOAT = 0,
			@V_FLT_QUANTITY_OF_LPN		FLOAT = 5,
			@V_VCH_INVENTORY_STATUS_ID	VARCHAR(40),
			@V_VCH_L_ATTRIBUTE_TYPE_ID	VARCHAR(40),
			@V_VCH_E_ATTRIBUTE_TYPE_ID	VARCHAR(40),
			@V_VCH_S_ATTRIBUTE_TYPE_ID	VARCHAR(40),

			-- LOCATION VARIABLE
			@V_VCH_LOCATION_ID			VARCHAR(40),
			@V_VCH_LPN_CONTROLLED		NVARCHAR(3),
			@V_VCH_MIX_OWNERS			NVARCHAR(3),
			@V_VCH_MIX_ITEMS			NVARCHAR(3),
			@V_VCH_MIX_LOT				NVARCHAR(3),
			@V_VCH_MIX_EXPIRY_DATES		NVARCHAR(3),
			@V_VCH_LOCATION_TYPE		NVARCHAR(25),
			

			@V_FLT_ROUNDING_LPN			FLOAT = 1,
			@V_FLT_ROUNDING				FLOAT = 1,
			@V_FLT_ROUND				FLOAT = 1,
			@V_VCH_INVENTORY_ID			VARCHAR(40),
			@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID	VARCHAR(40)

	BEGIN
		
		BEGIN TRY
			-- SELECT WAREHOUSE MASTER ID
			SELECT @V_VCH_WAREHOUSE_MASTER_ID = WH_MASTER_ID FROM T_WMS_WH WHERE wh_id = @IN_VCH_WAREHOUSE
			-- SELECT INVENTORY STATUS
			SELECT @V_VCH_INVENTORY_STATUS_ID = INVENTORY_STATUS_ID FROM T_WMS_INVENTORY_STATUS WHERE INV_STATUS = 'Available'
			-- SELECT ATTRIBUTE TYPE ID OF LOT TYPE
			SELECT @V_VCH_L_ATTRIBUTE_TYPE_ID = INV_ATTRIBUTE_TYPE_ID FROM T_WMS_INVENTORY_ATTRIBUTE_TYPE WHERE INV_ATTRIBUTE_TYPE = 'LOT'
			-- SELECT ATTRIBUTE TYPE ID OF EXPIRY DATE TYPE
			SELECT @V_VCH_E_ATTRIBUTE_TYPE_ID = INV_ATTRIBUTE_TYPE_ID FROM T_WMS_INVENTORY_ATTRIBUTE_TYPE WHERE INV_ATTRIBUTE_TYPE = 'EXPIRY_DATE'
			-- SELECT ATTRIBUTE TYPE ID OF SERIAL TYPE
			SELECT @V_VCH_S_ATTRIBUTE_TYPE_ID = INV_ATTRIBUTE_TYPE_ID FROM T_WMS_INVENTORY_ATTRIBUTE_TYPE WHERE INV_ATTRIBUTE_TYPE = 'SERIAL'
			-- SELECT QUANTITY OF ITEM
			SELECT	@V_FLT_QUANTITY_OF_ITEM = COUNT(ITEM_NUMBER) FROM T_WMS_ITEM
		
			-- SELECT QUANTITY ROW FOR GENERATE DATA
			SET		@V_FLT_ROW_OF_ITEM = CEILING( @IN_FLT_TOTALRECORD / @V_FLT_QUANTITY_OF_ITEM )
		
			-- CHECK PARENT CONTROL
			SELECT @V_VCH_PARENT_CONTROL = VALUE FROM T_WMS_RULE WHERE RULE_CODE = 'RULE_SCAN_PARENT_LPN'
			IF (@V_VCH_PARENT_CONTROL IS NULL OR @V_VCH_PARENT_CONTROL = 'NO')
				BEGIN
					SET @V_VCH_PARENT_CONTROL = 'NO'
					SET @V_VCH_PARENT_LPN = NULL
				END

			-- CURSOR ITEM
			-- ALL ITEM IN ITEM MASTER
			DECLARE CURSOR_ITEM CURSOR FOR
			SELECT		WH_ITEM_MASTER_ID,LOT_CONTROL,EXPIRY_DATE_CONTROL,SN_CONTROL,OWNER_ID
				FROM	T_WMS_ITEM IT
						INNER JOIN	T_WMS_WH_ITEM WIT ON IT.ITEM_MASTER_ID = WIT.ITEM_MASTER_ID
				WHERE	(0=0)
				-- ADD NEW CONDITION FOR SELECT ITEM.IF YOU WANT
				--WH_ITEM_MASTER_ID NOT IN (SELECT WH_ITEM_MASTER_ID FROM T_WMS_INVENTORY)
			
			OPEN CURSOR_ITEM
			FETCH FROM CURSOR_ITEM INTO @V_VCH_WH_ITEM_MASTER_ID,@V_VCH_LOT_CONTROL,@V_VCH_EXPIRY_DATE_CONTROL,@V_VCH_SERIAL_CONTROL,@V_VCH_OWNER_ID

			BEGIN TRANSACTION
			WHILE @@FETCH_STATUS = 0
				BEGIN

					WHILE (@V_FLT_ROW_OF_ITEM / @V_FLT_QUANTITY_OF_LPN) >= @V_FLT_ROUNDING OR @V_FLT_ROW_OF_ITEM = 1
						BEGIN
							
							-- GET PARENT LPN NUMBER
							IF (@V_VCH_PARENT_CONTROL = 'YES')
								BEGIN
									SET @V_FLT_RUNNING_PARENT_LPN = @V_FLT_RUNNING_PARENT_LPN + 1;
									SET @V_VCH_PARENT_LPN = @V_VCH_PREFIX_PARENT_LPN + '-' + CONVERT(NVARCHAR,RIGHT('00000' + CONVERT(NVARCHAR,@V_FLT_RUNNING_PARENT_LPN),6))
								END
							
							-- GET LOCATION
							GET_NEXT_LOCATION:
							SET @V_VCH_LOCATION_ID = NULL
							SELECT TOP 1	@V_VCH_LOCATION_ID = LOCATION_ID,@V_VCH_LPN_CONTROLLED = LPN_CONTROLLED,@V_VCH_LOCATION_TYPE = LOC_TYPE,
											@V_VCH_MIX_ITEMS = MIX_ITEMS,@V_VCH_MIX_LOT = MIX_LOT,@V_VCH_MIX_EXPIRY_DATES = MIX_EXPIRY_DATES,@V_VCH_MIX_OWNERS = MIX_OWNERS
							FROM T_WMS_LOCATION 
							WHERE LOCATION_ID NOT IN (SELECT LOCATION_ID FROM T_WMS_INVENTORY) AND ISNULL(LOCATION_ID,'') <> ISNULL(@V_VCH_LOCATION_ID,'') ORDER BY NEWID()
							IF (@V_VCH_LOCATION_ID IS NULL)
								BEGIN
									SELECT TOP 1	@V_VCH_LOCATION_ID = LOCATION_ID,@V_VCH_LPN_CONTROLLED = LPN_CONTROLLED,@V_VCH_LOCATION_TYPE = LOC_TYPE,
												@V_VCH_MIX_ITEMS = MIX_ITEMS,@V_VCH_MIX_LOT = MIX_LOT,@V_VCH_MIX_EXPIRY_DATES = MIX_EXPIRY_DATES,@V_VCH_MIX_OWNERS = MIX_OWNERS
									FROM T_WMS_LOCATION 
									WHERE MIX_OWNERS = 'YES' AND MIX_ITEMS = 'YES' AND ISNULL(LOCATION_ID,'') <> ISNULL(@V_VCH_LOCATION_ID,'') --OR MIX_LOT = 'YES' OR MIX_EXPIRY_DATES = 'YES' 
									ORDER BY NEWID()
								END
							IF (@V_VCH_LOCATION_ID IS NULL)
								GOTO NEXT_ITEM;

							WHILE @V_FLT_QUANTITY_OF_LPN >= @V_FLT_ROUNDING_LPN
								BEGIN

									-- GENERATE LOT NUMBER
									IF (@V_VCH_LOT_CONTROL = 'FULL')
										BEGIN
											GENERATE_LOT_NUMBER:
											SELECT @V_VCH_LOT_NUMBER = CONVERT(NVARCHAR, DATEADD(D, ROUND(DATEDIFF(D, DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()) + 1, -1)) * RAND(), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0)),112)
										END
									-- GENERATE EXPIRY DTE
									IF (@V_VCH_EXPIRY_DATE_CONTROL = 'FULL')
										BEGIN
											GENERATE_EXPIRY_DATE:
											SELECT @V_VCH_EXPIRY_DATE = CONVERT(NVARCHAR, DATEADD(D, ROUND(DATEDIFF(D, DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0), DATEADD(MM,12,DATEADD(YY, DATEDIFF(YY,0,GETDATE()) + 1, -1))) * RAND(), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0)),112)
										END

									IF EXISTS(SELECT INVENTORY_ID FROM T_WMS_INVENTORY WHERE LOCATION_ID = @V_VCH_LOCATION_ID)
										BEGIN
											IF (@V_VCH_LOCATION_TYPE <> 'FORK')
												BEGIN
													IF (@V_VCH_MIX_ITEMS = 'NO')
														BEGIN
															GET_NEXT_NEW_LOCATION:
															SELECT TOP 1	@V_VCH_LOCATION_ID = LOCATION_ID,@V_VCH_LPN_CONTROLLED = LPN_CONTROLLED,@V_VCH_LOCATION_TYPE = LOC_TYPE,
																			@V_VCH_MIX_ITEMS = MIX_ITEMS,@V_VCH_MIX_LOT = MIX_LOT,@V_VCH_MIX_EXPIRY_DATES = MIX_EXPIRY_DATES,@V_VCH_MIX_OWNERS = MIX_OWNERS
															FROM T_WMS_LOCATION 
															WHERE LOCATION_ID NOT IN (SELECT LOCATION_ID FROM T_WMS_INVENTORY) ORDER BY NEWID()
															IF EXISTS(SELECT INVENTORY_ID FROM T_WMS_INVENTORY WHERE LOCATION_ID = @V_VCH_LOCATION_ID AND WH_ITEM_MASTER_ID <> @V_VCH_WH_ITEM_MASTER_ID)
																BEGIN
																	PRINT 'GET_NEXT_NEW_LOCATION'
																	GOTO GET_NEXT_NEW_LOCATION
																END
														END
													IF (@V_VCH_MIX_LOT = 'NO' AND @V_VCH_LOT_CONTROL = 'FULL')
														BEGIN
															GENERATE_NEW_LOT_NUMBER:
															SELECT @V_VCH_LOT_NUMBER = CONVERT(NVARCHAR, DATEADD(D, ROUND(DATEDIFF(D, DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()) + 1, -1)) * RAND(), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0)),112)
															IF EXISTS(SELECT INVENTORY_ID FROM V_WMS_INVENTORY_DATA WHERE LOCATION_ID = @V_VCH_LOCATION_ID AND WH_ITEM_MASTER_ID = @V_VCH_WH_ITEM_MASTER_ID AND LOT_NUMBER <> @V_VCH_LOT_NUMBER)
																BEGIN
																	PRINT 'GENERATE_NEW_LOT_NUMBER ' + @V_VCH_LOT_NUMBER
																	GOTO GENERATE_NEW_LOT_NUMBER
																END
														END
													IF (@V_VCH_MIX_EXPIRY_DATES = 'NO' AND @V_VCH_EXPIRY_DATE_CONTROL = 'FULL')
														BEGIN
															GENERATE_NEW_EXPIRY_DATE:
															SELECT @V_VCH_EXPIRY_DATE = CONVERT(NVARCHAR, DATEADD(D, ROUND(DATEDIFF(D, DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0), DATEADD(MM,12,DATEADD(YY, DATEDIFF(YY,0,GETDATE()) + 1, -1))) * RAND(), 0), DATEADD(YY, DATEDIFF(YY,0,GETDATE()), 0)),112)
															IF EXISTS(SELECT INVENTORY_ID FROM V_WMS_INVENTORY_DATA WHERE LOCATION_ID = @V_VCH_LOCATION_ID AND WH_ITEM_MASTER_ID = @V_VCH_WH_ITEM_MASTER_ID AND EXPIRY_DATE <> @V_VCH_EXPIRY_DATE)
																BEGIN
																	PRINT 'GENERATE_NEW_EXPIRY_DATE ' + @V_VCH_EXPIRY_DATE
																	GOTO GENERATE_NEW_EXPIRY_DATE
																END
														END
													IF (@V_VCH_MIX_OWNERS = 'NO')
														BEGIN
															IF EXISTS(SELECT INVENTORY_ID FROM T_WMS_INVENTORY WHERE LOCATION_ID = @V_VCH_LOCATION_ID AND OWNER_ID <> @V_VCH_OWNER_ID)
																BEGIN
																	PRINT 'GET_NEXT_LOCATION ' + @V_VCH_LOCATION_ID
																	GOTO GET_NEXT_LOCATION
																END
														END
												END
										END
																	
									SET @V_VCH_LPN = NULL
									IF (@V_VCH_LPN_CONTROLLED = 'YES')
										BEGIN
											SELECT @V_VCH_LPN = SUBSTRING(CONVERT(VARCHAR(255), NEWID()), 0, 6)
										END

									SET @V_VCH_INVENTORY_ID = NULL
									SET @V_VCH_INVENTORY_ATTRIBUTEGROUP_ID = NULL
									SELECT	@V_VCH_INVENTORY_ID = INVENTORY_ID,
											@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID = ATTRIBUTE_GROUP_ID
									FROM	V_WMS_INVENTORY_DATA 
									WHERE	LOCATION_ID = @V_VCH_LOCATION_ID AND WH_ITEM_MASTER_ID = @V_VCH_WH_ITEM_MASTER_ID 
											AND ISNULL(PARENT_LPN,'') = ISNULL(@V_VCH_PARENT_LPN,'') AND ISNULL(LPN,'') = ISNULL(@V_VCH_LPN,'')
											AND ISNULL(LOT_NUMBER,'') = ISNULL(@V_VCH_LOT_NUMBER,'') AND ISNULL(EXPIRY_DATE,'') = ISNULL(@V_VCH_EXPIRY_DATE,'')
									
									IF (@V_VCH_INVENTORY_ID IS NULL)
										BEGIN
											SET @V_VCH_INVENTORY_ID = NEWID()
											SET @V_VCH_INVENTORY_ATTRIBUTEGROUP_ID = NEWID()
											
											IF (@V_VCH_SERIAL_CONTROL = 'FULL')
												INSERT INTO T_WMS_INVENTORY(inventory_id, wh_master_id, owner_id, wh_item_master_id, location_id, inventory_status_id, inv_type, attribute_group_id, quantity, quantity_allocated, lpn, parent_lpn, receive_date, create_by)
												VALUES(@V_VCH_INVENTORY_ID,@V_VCH_WAREHOUSE_MASTER_ID,@V_VCH_OWNER_ID,@V_VCH_WH_ITEM_MASTER_ID,@V_VCH_LOCATION_ID,@V_VCH_INVENTORY_STATUS_ID,'INVENTORY',@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID,10,0,@V_VCH_LPN,@V_VCH_PARENT_LPN,CONVERT(DATE,GETDATE()),'GENERATE')
											ELSE
												INSERT INTO T_WMS_INVENTORY(inventory_id, wh_master_id, owner_id, wh_item_master_id, location_id, inventory_status_id, inv_type, attribute_group_id, quantity, quantity_allocated, lpn, parent_lpn, receive_date, create_by)
												VALUES(@V_VCH_INVENTORY_ID,@V_VCH_WAREHOUSE_MASTER_ID,@V_VCH_OWNER_ID,@V_VCH_WH_ITEM_MASTER_ID,@V_VCH_LOCATION_ID,@V_VCH_INVENTORY_STATUS_ID,'INVENTORY',@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID,10,0,@V_VCH_LPN,@V_VCH_PARENT_LPN,CONVERT(DATE,GETDATE()),'GENERATE')
											
											IF (@V_VCH_LOT_CONTROL = 'FULL')
												INSERT INTO t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_by)
												VALUES(NEWID(),@V_VCH_INVENTORY_ID,@V_VCH_L_ATTRIBUTE_TYPE_ID,@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID,@V_VCH_LOT_NUMBER,10,0,'GENERATE')
											
											IF (@V_VCH_EXPIRY_DATE_CONTROL = 'FULL')
												INSERT INTO t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_by)
												VALUES(NEWID(),@V_VCH_INVENTORY_ID,@V_VCH_E_ATTRIBUTE_TYPE_ID,@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID,@V_VCH_EXPIRY_DATE,10,0,'GENERATE')
											
											-- GENERATE SERIAL
											IF (@V_VCH_SERIAL_CONTROL = 'FULL')
												BEGIN
													DECLARE @ROW INT = 1
													WHILE @ROW <= 10
														BEGIN
															GENERATE_SERIAL_NUMBER:
															SELECT @V_VCH_SERIAL_NUMBER = SUBSTRING(CONVERT(VARCHAR(255), NEWID()), 0, 9)
															IF EXISTS(SELECT * FROM V_WMS_INVENTORY_DATA_BY_SERIAL WHERE SERIAL_NUMBER = @V_VCH_SERIAL_NUMBER)
																BEGIN
																	GOTO GENERATE_SERIAL_NUMBER
																END
															INSERT INTO t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_by)
															VALUES(NEWID(),@V_VCH_INVENTORY_ID,@V_VCH_S_ATTRIBUTE_TYPE_ID,@V_VCH_INVENTORY_ATTRIBUTEGROUP_ID,@V_VCH_SERIAL_NUMBER,1,0,'GENERATE')
															SET @ROW += 1
														END
												END

										END

									SET @V_FLT_ROUNDING_LPN += 1

									PRINT @V_FLT_ROUND--'RECORD : ' + CONVERT(NVARCHAR,@V_FLT_ROUND) + ' INSERTED.'
									SET @V_FLT_ROUND += 1
								END

							SET @V_FLT_ROUNDING += 1
							SET @V_FLT_ROUNDING_LPN = 1

							IF (@V_FLT_ROW_OF_ITEM = 1)
								BREAK;
						END

					SET @V_FLT_ROUNDING = 1
					SET @V_FLT_ROUNDING_LPN = 1

					NEXT_ITEM:
					FETCH NEXT FROM CURSOR_ITEM INTO @V_VCH_WH_ITEM_MASTER_ID,@V_VCH_LOT_CONTROL,@V_VCH_EXPIRY_DATE_CONTROL,@V_VCH_SERIAL_CONTROL,@V_VCH_OWNER_ID
				END

			CLOSE CURSOR_ITEM
			DEALLOCATE CURSOR_ITEM
			COMMIT TRANSACTION

		END TRY
		BEGIN CATCH
			CLOSE CURSOR_ITEM
			DEALLOCATE CURSOR_ITEM
			ROLLBACK TRANSACTION
			PRINT ERROR_NUMBER()
			PRINT ERROR_MESSAGE()
		END CATCH
	END

END


GO
/****** Object:  StoredProcedure [dbo].[usp_generate_receipt_number]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_generate_receipt_number]
	@in_vchUserID			  NVARCHAR(40),
	@in_vchWhMasterID		  UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	  UNIQUEIDENTIFIER,
	@out_vchReceiptHeaderID	  UNIQUEIDENTIFIER OUTPUT,
	@out_vchReceiptNumber	  NVARCHAR(50) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;

	DECLARE	@v_vchLastReceiptNumber	 NVARCHAR(50)
	DECLARE @v_vchInboundOrderNumber NVARCHAR(50)
	DECLARE @v_fltLastNumber		 FLOAT
	DECLARE @v_fltNextNumber		 FLOAT

	SELECT @in_vchInboundMasterID = inbound_order_master_id 
		,@v_vchInboundOrderNumber = inbound_order_number
	FROM t_wms_inbound_master WITH (NOLOCK)
	WHERE inbound_order_master_id = @in_vchInboundMasterID

    -- Insert statements for procedure here 
	IF (@in_vchInboundMasterID IS NOT NULL)
		BEGIN
			--GET LAST Receipt Number
			SELECT @v_fltLastNumber = CONVERT(FLOAT,RIGHT((MAX(receipt_number)),3)) 
			FROM t_wms_receipt_header WITH (NOLOCK)
			WHERE inbound_order_master_id = @in_vchInboundMasterID 
			IF(@v_fltLastNumber IS NULL)
				BEGIN
					SET @v_fltLastNumber = 0
				END

			SET @v_fltNextNumber = @v_fltLastNumber + 1;
			SET	@out_vchReceiptNumber = @v_vchInboundOrderNumber + '-' +  RIGHT('000'+CONVERT(VARCHAR(20),@v_fltNextNumber),3)

			BEGIN TRY
				BEGIN TRANSACTION
					SET @out_vchReceiptHeaderID = NEWID()
					INSERT INTO t_wms_receipt_header (receipt_header_id, inbound_order_master_id, receipt_number, receipt_status, create_by, create_date)
					VALUES (@out_vchReceiptHeaderID, @in_vchInboundMasterID, @out_vchReceiptNumber, 'OPEN', @in_vchUserID, GETDATE())
			
				COMMIT TRANSACTION
			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION
				SET @out_vchReceiptNumber = ''
			END CATCH
		END
	ELSE
		BEGIN
			SET @out_vchReceiptNumber = ''
		END
END




