/****** Object:  StoredProcedure [dbo].[usp_generate_running_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-04-02
-- Description:	Generate running lpn
-- =============================================
CREATE PROCEDURE [dbo].[usp_generate_running_lpn]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouseCode	NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchPrefix			NVARCHAR(10) = null,
	@in_vchSuffix			NVARCHAR(10) = null,
	@in_fltQtySerial		INT = 0,
	@in_vchGenerateType		NVARCHAR(3) = null, -- GET = get lpn running ,SET = update running number
	@in_vchLPN				NVARCHAR(25) output,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;

	Begin Try
		
		Declare
			@v_vchWarehouseMasterID	VARCHAR(40),
			@v_vchWarehouseName		NVARCHAR(250),
			@v_vchFormat			NVARCHAR(10),
			@v_intRunning			INT,
			@v_vchRunningID			VARCHAR(40),
			@v_vchUpdateBy			Date,
			@v_intRunningTotal		INT

		
		Select @v_vchWarehouseMasterID = wh_master_id,@v_vchWarehouseName = wh_name from t_wms_wh where wh_id = @in_vchWarehouseCode
		Select @v_vchFormat = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_LPN_RUNNING'

		Select @v_vchRunningID = running_id,@v_intRunning = running_value ,@v_vchUpdateBy = CONVERT(DATE,update_date)
		from t_com_print_barcode where wh_master_id = @v_vchWarehouseMasterID

		If (@v_intRunning is null)
			Begin
				Set @v_intRunning = 0;
			End

	 --   -- == Modify by bank 08-May-2014 ==
		--If(@v_vchUpdateBy <> CONVERT(DATE,GETDATE()))
		--	Begin
		--		Set @v_intRunning = 0;
		--	End
		----===================================

		Set @v_intRunningTotal = @v_intRunning + @in_fltQtySerial;

		Set @v_intRunning = @v_intRunning + 1;
		Set @in_vchLPN = @in_vchPrefix + RIGHT(CONVERT(nvarchar,getdate(),112),6) + @v_vchWarehouseName + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @in_vchSuffix;

		If (@in_vchGenerateType = 'SET')
			Begin
				If (@v_vchRunningID is null)
					Begin
						Insert into t_com_print_barcode(wh_master_id, running_value, prefix, suffix, create_by,update_by,update_date)-- Add update_by updatedate
						Values(@v_vchWarehouseMasterID,@in_fltQtySerial,@in_vchPrefix,@in_vchSuffix,@in_vchUserID,@in_vchUserID,GETDATE())
						Set @out_ErrorCode = '0';
						Set @out_ErrorMessage = 'Update lpn running success';
					End
				Else
					Begin
						--update t_com_print_barcode set running_value += @in_fltQtySerial ,update_by = @in_vchUserID,update_date = GETDATE()
						update t_com_print_barcode set running_value = @v_intRunningTotal ,update_by = @in_vchUserID,update_date = GETDATE()
						where running_id = @v_vchRunningID
						Set @out_ErrorCode = '0';
						Set @out_ErrorMessage = 'Update lpn running success';
					End
			End
		Else
			Begin
				Set @out_ErrorCode = '0';
				Set @out_ErrorMessage = 'Get lpn success';
			End
	End Try
	Begin Catch
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch
END



GO
/****** Object:  StoredProcedure [dbo].[usp_generate_running_outbound_pack_number]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_generate_running_outbound_pack_number]
	@in_vchUserID			NVARCHAR(25),
	@in_vchOutboundNumber	NVARCHAR(50),
	@out_vchPackNumber		NVARCHAR(25) output,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;

	Begin Try 
		-------------------------------------------------
		--GENERATE PACK NUMBER
		-------------------------------------------------
		DECLARE @v_vchPrefix		NVARCHAR(20) = ''
		DECLARE @v_vchFormat		NVARCHAR(10) = '00000'
		DECLARE @v_intRunning		INT
		DECLARE @v_vchRunningID		UNIQUEIDENTIFIER
		DECLARE @v_dtCreateDate		DATE = GETDATE() 
		
		SELECT @v_vchPrefix = LEFT(@in_vchOutboundNumber,20)
		SELECT @v_vchRunningID = running_id, @v_intRunning = running FROM t_wms_running_outbound_pack_number WHERE prefix = @v_vchPrefix
		IF (@v_intRunning IS NULL)
			BEGIN
				SET @v_intRunning = 0;
			END

		SET @v_intRunning = @v_intRunning + 1;
		SET @out_vchPackNumber = @v_vchPrefix +'-'+ RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat));
		 
		IF (@v_vchRunningID IS NULL)
			BEGIN
				SET @v_vchRunningID = NEWID();
				INSERT INTO [dbo].[t_wms_running_outbound_pack_number]
					   ([running_id]
					   ,[running]
					   ,[prefix]
					   ,[create_by]
					   ,[create_date])
				 VALUES
					   (@v_vchRunningID
					   ,@v_intRunning
					   ,@v_vchPrefix
					   ,@in_vchUserID
					   ,GETDATE())
			End
		ELSE
			BEGIN
				UPDATE t_wms_running_outbound_pack_number SET running = @v_intRunning, update_by = @in_vchUserID, update_date = GETDATE() WHERE running_id = @v_vchRunningID
			END
	End Try
	Begin Catch
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch
END



