SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Chatchai L.
-- Create date: 2016-01-18
-- Description:	Generate running serial
-- =============================================
CREATE PROCEDURE [dbo].[usp_generate_running_serial]
	@in_vchUserID			NVARCHAR(10),
	@in_vchPrefix			NVARCHAR(10) = null,
	@in_vchSuffix			NVARCHAR(10) = null,
	@in_fltQtySerial		INT = 0,
	@in_vchGenerateType		NVARCHAR(3) = null, -- GET = get lpn running ,SET = update running number
	@in_vchSerial_INT		NVARCHAR(25) output,
	@in_vchSerial			NVARCHAR(25) output,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;

	Begin Try
		
		Declare
			@v_vchFormat			NVARCHAR(50),
			@v_intRunning			INT,
			@v_vchRunningID			VARCHAR(40),
			@v_vchUpdateBy			Date,
			@v_intRunningTotal		INT

		
		Select @v_vchFormat = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_SERIAL_RUNNING'

		Select @v_vchRunningID = running_id,@v_intRunning = running_value ,@v_vchUpdateBy = CONVERT(DATE,update_date)
		from t_com_print_barcode_serial 

		If (@v_intRunning is null)
			Begin
				Set @v_intRunning = 0;
			End


		Set @v_intRunningTotal = @v_intRunning + @in_fltQtySerial;

		Set @v_intRunning = @v_intRunning + 1;
		Set @in_vchSerial = @in_vchPrefix + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @in_vchSuffix;
		SET @in_vchSerial_INT = Convert(nvarchar,@v_intRunning);

		If (@in_vchGenerateType = 'SET')
			Begin
				If (@v_vchRunningID is null)
					Begin
						Insert into t_com_print_barcode_serial(running_value, prefix, suffix, create_by,update_by,update_date)-- Add update_by updatedate
						Values(@in_fltQtySerial,@in_vchPrefix,@in_vchSuffix,@in_vchUserID,@in_vchUserID,GETDATE())
						Set @out_ErrorCode = '0';
						Set @out_ErrorMessage = 'Update lpn running success';
					End
				Else
					Begin
						update t_com_print_barcode_serial set running_value = @v_intRunningTotal ,update_by = @in_vchUserID,update_date = GETDATE()
						where running_id = @v_vchRunningID
						Set @out_ErrorCode = '0';
						Set @out_ErrorMessage = 'Update lpn running success';
					End
			End
		Else
			Begin
				Set @out_ErrorCode = '0';
				Set @out_ErrorMessage = 'Get lpn success';
			End
	End Try
	Begin Catch
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch
END



