/****** Object:  StoredProcedure [dbo].[usp_generate_textfile_for_vocollect]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_generate_textfile_for_vocollect]
(
		@in_vchOutboundMasterID		VARCHAR(40),
		@in_vchOrderNumber			NVARCHAR(50)
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @MySpecialTempTable		NVARCHAR(255) = '',
			@RESULT					INT,
			@Unicode				INT,
			@v_vchQueryString		NVARCHAR(3000) = '',
			@v_vchCommand			NVARCHAR(4000) = '',
			@v_vchDateTime			NVARCHAR(20) = '',
			@v_vchFileName			NVARCHAR(100) = '',
			@v_vchPathFile			NVARCHAR(255) = ''

	SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE()))
	SET @v_vchFileName = 'ap-' + @in_vchOrderNumber + '_' + @v_vchDateTime + '.dat'
	SET @v_vchPathFile = 'C:\Vocollect\PickList\' + @v_vchFileName

	SELECT @MySpecialTempTable = '##temp' + CONVERT(VARCHAR(12), CONVERT(INT, RAND() * 1000000))

	SET @v_vchQueryString = 'SELECT (LEFT(ISNULL(obMS.outbound_order_number,'''') + REPLICATE('' '',18),18)
							+ CONVERT(VARCHAR(8),obMS.order_date,112)
							+ LEFT(''5'' + REPLICATE('' '',9),9)
							+ LEFT(''5'' + REPLICATE('' '',50),50)
							+ LEFT(ISNULL(obMS.customer_code,'''') + REPLICATE('' '',50),50)
							+ LEFT(ISNULL(obMS.customer_name,'''') + REPLICATE('' '',50),50)
							+ REPLICATE('' '',50)
							+ LEFT(''9'' + REPLICATE('' '',10),10)
							+ LEFT(CONVERT(VARCHAR,CONVERT(INT,pickDT.pick_line_number)) + REPLICATE('' '',9),9)
							+ LEFT(CONVERT(VARCHAR,pickDT.quantity_plan) + REPLICATE('' '',9),9)
							+ LEFT(ISNULL(item.item_number,'''') + REPLICATE('' '',50),50)
							+ ''0''
							+ ''0''
							+ LEFT(ISNULL(loc.location,'''') + REPLICATE('' '',50),50)
							+ ''0''
							+ LEFT(''1'' + REPLICATE('' '',9),9)
							+ ''0''
							+ REPLICATE('' '',5)
							+ REPLICATE('' '',50)
							+ LEFT(ISNULL(uom.uom_prompt,'''') + REPLICATE('' '',50),50)
							+ LEFT(RIGHT(REPLICATE('' '',6) + ISNULL(obMS.outbound_order_number,''''),6) + REPLICATE('' '',18),18)
							+ REPLICATE('' '',2)
							+ REPLICATE('' '',250)
							+ REPLICATE('' '',14)
							+ REPLICATE('' '',9)) AS BulkCol
						INTO ' + @MySpecialTempTable + ' 
						FROM  WM3.dbo.t_wms_outbound_master obMS
						INNER JOIN WM3.dbo.t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
						INNER JOIN WM3.dbo.t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
						INNER JOIN WM3.dbo.t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
																				AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
						INNER JOIN WM3.dbo.t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
						INNER JOIN WM3.dbo.t_wms_item item ON whItem.item_master_id = item.item_master_id
						INNER JOIN WM3.dbo.t_wms_location loc ON pickDT.location_id = loc.location_id
						INNER JOIN WM3.dbo.t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
						WHERE obDT.outbound_order_master_id ='''+@in_vchOutboundMasterID+''''

	EXECUTE sp_ExecuteSQL @v_vchQueryString

	SET @Unicode  = 0
	SELECT  @v_vchCommand = N'bcp "USE WM3 SELECT BulkCol FROM [' + @MySpecialTempTable + ']'
				+ '" queryout '
				+ ' "'+@v_vchPathFile + '" '
				+ CASE WHEN @Unicode=0 THEN '-c' ELSE '-w -t' END
				+ ' -T -S' + '10.10.60.188' --@@servername
	SELECT @v_vchCommand

	EXECUTE @RESULT= MASTER..xp_cmdshell @v_vchCommand 
	EXECUTE ( 'DROP TABLE ' + @MySpecialTempTable )
	SELECT @result
END
GO
