-- =============================================
CREATE PROCEDURE [dbo].[usp_get_check_serial]
(
	@in_vchSerialNumber NVARCHAR(50)
)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT      location, item_number, description, lot_number, expiry_date, quantity
	FROM		v_wms_inventory_data
	WHERE		serial_number = @in_vchSerialNumber
END



