CREATE PROCEDURE [dbo].[usp_get_control]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchFunction		varchar(40),
	@in_vchLocaleID		varchar(40)
)
AS
BEGIN
	SELECT control_id
		, function_id
