/****** Object:  StoredProcedure [dbo].[usp_get_count_plan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_get_count_plan]
(
	@in_vchHospital		NVARCHAR(50),
	@in_vchPlanID		NVARCHAR(50),
	@in_intStartRecord	INT,
	@in_intStopRecord	INT,
	@in_vchStatus		NVARCHAR(50) = NULL
)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    --16/08/2016:Mai ปรับแก้ไข จากเดิมที่ join sub cate ด้วย category_id กับ t_wms_category ให้เปลี่ยนเป็น join sub_category_id ที่ t_wms_item แทน

	IF ISNULL(@in_vchStatus,'') = ''
		BEGIN
			WITH count_plan AS
			(
				SELECT	b.location
					, b.item_number
					, b.item_description
					, b.lot_number
					, b.expiry_date
					, b.serial_number
					, b.delivery_date
					, b.outbound_order_number
					, a.count_status
					, e.item_category
					, e.description
					, f.owner_code
					, b.inv_status
					, b.stock_qty
					, ROW_NUMBER() OVER (ORDER BY a.customer_code) AS RowNumber
					, sub_cate.sub_category
					, sub_cate.description AS sub_category_desc
				FROM t_wms_count_plan_master_external AS a 
				INNER JOIN t_wms_count_plan_detail_external AS b ON a.count_master_id = b.count_master_id 
				INNER JOIN t_wms_wh_item AS c ON b.wh_item_master_id = c.wh_item_master_id 
				INNER JOIN t_wms_item AS d ON c.item_master_id = d.item_master_id 
				INNER JOIN t_wms_category AS e ON d.category_id = e.category_id 
				INNER JOIN t_wms_owner AS f ON d.owner_id = f.owner_id
				LEFT JOIN t_wms_sub_category AS sub_cate ON d.sub_category_id = sub_cate.sub_category_id
				WHERE a.count_id = @in_vchPlanID
				AND a.customer_code = @in_vchHospital
				AND a.count_status = 'OPEN'
			)
			SELECT  location
				, item_number
				, item_description
				, lot_number
				, expiry_date
				, serial_number
				, delivery_date
				, outbound_order_number
				, count_status
				, item_category
				, description AS item_category_desc
				, owner_code 
				, inv_status
				, stock_qty
				, sub_category
				, sub_category_desc
			FROM count_plan 
			--WHERE RowNumber BETWEEN @in_intStartRecord AND @in_intStopRecord
		END
	ELSE IF @in_vchStatus = 'CLOSE'
		BEGIN
		WITH count_plan AS
			(
				SELECT  a.count_id
					, b.location
					, b.item_number
					, b.item_description
					, b.lot_number
					, b.expiry_date
					, b.serial_number
					, b.delivery_date
					, b.outbound_order_number
					, a.count_status
					, e.item_category
					, e.description
					, f.owner_code
					, b.inv_status
					, b.stock_qty
					, ROW_NUMBER() OVER (ORDER BY a.customer_code) AS RowNumber
					, sub_cate.sub_category
					, sub_cate.description AS sub_category_desc
				FROM t_wms_count_plan_master_external AS a 
				INNER JOIN t_wms_count_plan_detail_external AS b ON a.count_master_id = b.count_master_id
				INNER JOIN t_wms_wh_item AS c ON b.wh_item_master_id = c.wh_item_master_id 
				INNER JOIN t_wms_item AS d ON c.item_master_id = d.item_master_id 
				INNER JOIN t_wms_category AS e ON d.category_id = e.category_id 
				INNER JOIN t_wms_owner AS f ON d.owner_id = f.owner_id  
				LEFT JOIN t_wms_sub_category AS sub_cate ON d.sub_category_id = sub_cate.sub_category_id
				WHERE a.count_id  = @in_vchPlanID
				AND a.customer_code = @in_vchHospital
				AND a.count_status = 'CLOSE'	
			)
			SELECT count_id
				, location
				, item_number
				, item_description
				, lot_number
				, expiry_date
				, serial_number
				, delivery_date
				, outbound_order_number
				, count_status
				, item_category
				, description AS item_category_desc
				, owner_code
				, inv_status
				, stock_qty
				, sub_category
				, sub_category_desc
			FROM count_plan 
			--WHERE RowNumber BETWEEN @in_intStartRecord AND @in_intStopRecord
			ORDER BY count_id	
		END	
END



GO
/****** Object:  StoredProcedure [dbo].[usp_get_count_reconcile]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_count_reconcile]
(
	@in_vchHospital		NVARCHAR(50),
	@in_vchPlanID		NVARCHAR(50),
	@in_intStartRecord	INT,
	@in_intStopRecord	INT,
	@in_vchStatus		NVARCHAR(50) = NULL
)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	IF ISNULL(@in_vchStatus,'') = ''
		BEGIN
			WITH count_reconcile AS
			(
				SELECT      a.serial_number, b.count_status,
							ROW_NUMBER() OVER (ORDER BY b.customer_code) AS RowNumber
				FROM        t_wms_count_reconcile_external AS a INNER JOIN
							t_wms_count_plan_master_external AS b ON a.count_master_id = b.count_master_id
				Where		b.count_id = @in_vchPlanID
				AND			b.customer_code = @in_vchHospital
				AND			b.count_status = 'OPEN'
			)
			SELECT  serial_number, count_status
			FROM count_reconcile --WHERE RowNumber BETWEEN @in_intStartRecord AND @in_intStopRecord
		END
	ELSE IF @in_vchStatus = 'CLOSE'
		BEGIN
			WITH count_reconcile AS
			(
			--Remove Top(3)
				SELECT      a.serial_number, b.count_status,
							ROW_NUMBER() OVER (ORDER BY b.customer_code) AS RowNumber
				FROM        t_wms_count_reconcile_external AS a INNER JOIN
							t_wms_count_plan_master_external AS b ON a.count_master_id = b.count_master_id
				Where		b.count_id = @in_vchPlanID
				AND			b.customer_code = @in_vchHospital
				AND			b.count_status = 'CLOSE'
				--ORDER BY	b.close_date
			)
			SELECT  serial_number, count_status
			FROM count_reconcile --WHERE RowNumber BETWEEN @in_intStartRecord AND @in_intStopRecord
		END
END


