/****** Object:  StoredProcedure [dbo].[usp_get_hospital_plan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_get_hospital_plan]
(
	@in_vchHospital NVARCHAR(50)
)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	SELECT countMS.count_id
		, countMS.count_status
		, COUNT(countDT.count_plan_detail_id) AS total_record
		, countMS.count_plan_date
		, countMS.close_date
		, countMS.close_by 
		, countMS.close_remark
		, countMS.count_plan_type
		, countMS.description
		, cate.item_category AS category
		, cate.description AS category_desc
		, subCate.sub_category
		, subCate.description AS sub_category_desc
	FROM t_wms_count_plan_master_external countMS
	LEFT JOIN t_wms_count_plan_detail_external countDT ON countMS.count_master_id = countDT.count_master_id
	LEFT JOIN t_wms_customer cust ON countMS.customer_id = cust.customer_id
	LEFT JOIN t_wms_wh_item whItem ON countDT.wh_item_master_id = whItem.wh_item_master_id
	LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
	LEFT JOIN t_wms_sub_category subCate ON item.sub_category_id = subCate.sub_category_id
	WHERE cust.customer_code = @in_vchHospital
	GROUP BY countMS.count_id
		, countMS.count_status
		, countMS.count_plan_date
		, countMS.close_date
		, countMS.close_by 
		, countMS.close_remark
		, countMS.count_plan_type
		, countMS.description
		, cate.item_category
		, cate.description
		, subCate.sub_category
		, subCate.description
END



