/****** Object:  StoredProcedure [dbo].[usp_get_HostInterfaceID]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-09-20
-- Description:	Get Hostinterface id
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_HostInterfaceID]
	@v_vchHostInterfaceID	NVARCHAR(20) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE 
			@v_intRunningID			INT,
			@v_dtpDateNow			NVARCHAR(6)

	SET @v_dtpDateNow = LEFT(convert(nvarchar,GETDATE(),112),6);
	
	-- Add the T-SQL statements to compute the return value here
	select @v_vchHostInterfaceID = max(CONVERT(decimal,working_date)),@v_intRunningID = last_running from t_com_interface_running
	where working_date = @v_dtpDateNow group by working_date,last_running
	
	If (@v_vchHostInterfaceID is null)
		Begin
			set @v_vchHostInterfaceID = @v_dtpDateNow + '0000001';
			insert into t_com_interface_running(working_date, last_running) values(@v_dtpDateNow,1)
		End
	Else
		Begin
			set @v_vchHostInterfaceID = @v_vchHostInterfaceID + convert(nvarchar,RIGHT('0000000' + convert(nvarchar,@v_intRunningID + 1),7))
			update t_com_interface_running set last_running = last_running + 1 where working_date = @v_dtpDateNow
		End
		
END


