/****** Object:  StoredProcedure [dbo].[usp_get_inventory_aging]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-05-28
-- Description:	Get Inventory data
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_inventory_aging]
	@in_vchWarehouse	NVARCHAR(50) = null,
	@in_vchLocation		NVARCHAR(50) = null,
	@in_vchItemNumber	NVARCHAR(50) = null,
	@in_vchParentLPN	NVARCHAR(25) = null,
	@in_vchLPN			NVARCHAR(25) = null,
	@in_vchItemCategory	NVARCHAR(50) = null,
	@in_vchLotNumber	NVARCHAR(50) = null,
	@in_vchSerialNumber	NVARCHAR(50) = null,
	@in_vchReceiveDate	NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode		NVARCHAR(50) = null,
	@in_vchZone			NVARCHAR(50) = null,
	@in_vchAgingSymbol	NVARCHAR(5),
	@in_vchAgingValue	INT,
	@in_vchOwner		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;
	
	Begin Try
	
		Declare @v_vchSQLCommand NVARCHAR(4000)
		
		Create Table #TmpInventory(
			owner_code nvarchar(50),
			owner_id nvarchar(50),
			wh_id nvarchar(25),
			location nvarchar(50),
			item_category nvarchar(50),
			inventory_type nvarchar(40),
			item_number nvarchar(50),
			qty_item float,
			qty_item_allocated float,
			inv_status nvarchar(50),
			receive_date date,
			lpn nvarchar(25),
			parent_lpn nvarchar(25),
			wh_master_id varchar(40),
			wh_item_master_id varchar(40),
			location_id varchar(40),
			inventory_status_id varchar(40),
			inv_type nvarchar(50),
			item_master_id varchar(40),
			receive_date_filter nvarchar(20),
			loc_type nvarchar(20),
			pick_sequence int,
			[description] nvarchar(200),
			uom nvarchar(10),
			uom_prompt nvarchar(40),
			price float,
			dg_code nvarchar(50),
			grade nvarchar(40),
			aging int,
			zone nvarchar(50),
			Lot_number nvarchar(50),
			Expiry_date nvarchar(50),
			RemainAging Float
			)

		SET @v_vchSQLCommand = '
		SELECT t_wms_owner.owner_code,t_wms_owner.owner_id , t_wms_wh.wh_id, location, t_wms_category.item_category, t_wms_item.inventory_type, 
				t_wms_item.item_number, SUM(t_wms_inventory.quantity) AS qty_item,SUM(t_wms_inventory.quantity_allocated) AS qty_item_allocated,
				t_wms_inventory_status.inv_status, t_wms_inventory.receive_date, t_wms_inventory.lpn, t_wms_inventory.parent_lpn, 
				t_wms_inventory.wh_master_id, t_wms_inventory.wh_item_master_id, t_wms_inventory.location_id, t_wms_inventory.inventory_status_id, 
				t_wms_inventory.inv_type, t_wms_item.item_master_id, CONVERT(nvarchar, dbo.t_wms_inventory.receive_date, 112) AS receive_date_filter,
				t_wms_location.loc_type, t_wms_location.pick_sequence, t_wms_item.description, 
				t_wms_item_uom.uom, t_wms_item_uom.uom_prompt, t_wms_item.price, t_wms_item.dg_code, 
				t_wms_item.grade, DATEDIFF(DAY, receive_date, GETDATE()) AS aging,t_wms_zone.zone,
				(select attribute_value from t_wms_inventory_attribute inva where inva.inventory_id = t_wms_inventory.inventory_id
				and inva.attribute_group_id = t_wms_inventory.attribute_group_id and inv_attribute_type_id = ''CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'') As Lot_number,
				(select attribute_value from t_wms_inventory_attribute inva where inva.inventory_id = t_wms_inventory.inventory_id
				and inva.attribute_group_id = t_wms_inventory.attribute_group_id and inv_attribute_type_id = ''D468B603-02DE-4391-90D6-658862AEE248'') As Expiry_date,
				(select DATEDIFF(dd,getdate(),convert(date,attribute_value)) from t_wms_inventory_attribute inva where inva.inventory_id = t_wms_inventory.inventory_id
				and inva.attribute_group_id = t_wms_inventory.attribute_group_id and inv_attribute_type_id = ''D468B603-02DE-4391-90D6-658862AEE248'') As RemainAging
		FROM    dbo.t_wms_item_uom INNER JOIN
				dbo.t_wms_item ON dbo.t_wms_item_uom.item_master_id = dbo.t_wms_item.item_master_id INNER JOIN
				dbo.t_wms_item_crossref ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_crossref.item_master_id INNER JOIN
				dbo.t_wms_wh_item INNER JOIN
				dbo.t_wms_inventory INNER JOIN
				dbo.t_wms_wh ON dbo.t_wms_inventory.wh_master_id = dbo.t_wms_wh.wh_master_id INNER JOIN
				dbo.t_wms_inventory_status ON dbo.t_wms_inventory.inventory_status_id = dbo.t_wms_inventory_status.inventory_status_id INNER JOIN
				dbo.t_wms_location ON dbo.t_wms_inventory.location_id = dbo.t_wms_location.location_id INNER JOIN
				dbo.t_wms_owner ON dbo.t_wms_inventory.owner_id = dbo.t_wms_owner.owner_id ON 
				dbo.t_wms_wh_item.wh_item_master_id = dbo.t_wms_inventory.wh_item_master_id ON 
				dbo.t_wms_item.item_master_id = dbo.t_wms_wh_item.item_master_id INNER JOIN
				dbo.t_wms_category ON dbo.t_wms_item.item_category = dbo.t_wms_category.category_id LEFT OUTER JOIN
				dbo.t_wms_zone_location RIGHT OUTER JOIN
				dbo.t_wms_zone ON dbo.t_wms_zone_location.zone_id = dbo.t_wms_zone.zone_id ON 
				dbo.t_wms_location.location_id = dbo.t_wms_zone_location.location_id
		WHERE (0=0) and t_wms_item_uom.primary_uom = ''YES'' '

		If (isnull(@in_vchWarehouse,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_wh.wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
			End
		If (isnull(@in_vchLocation,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and location like ''%' + isnull(@in_vchLocation,'') + '%'' ';
			End
		If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_item.item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
			End
		If (isnull(@in_vchParentLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(parent_lpn,'''') like ''%' + isnull(@in_vchParentLPN,'') + '%'' ';
			End
		If (isnull(@in_vchLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(lpn,'''') like ''%' + isnull(@in_vchLPN,'') + '%'' ';
			End
		If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(t_wms_category.item_category,'''') like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
			End
		If (isnull(@in_vchReceiveDate,'') <> '')
			Begin
					SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,dbo.t_wms_inventory.receive_date,112) between ' + @in_vchReceiveDate  + ' AND '+ @in_vchReceiveDateTo + ' ';
			End
		If (isnull(@in_vchInventoryStatus,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and inv_status like ''%' + isnull(@in_vchInventoryStatus,'') + '%'' ';
			End
		If (isnull(@in_vchGrade,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(t_wms_item.grade,'''') like ''%' + isnull(@in_vchGrade,'') + '%'' ';
			End
		If (isnull(@in_vchDGCode,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(t_wms_item.dg_code,'''') like ''%' + isnull(@in_vchDGCode,'') + '%'' ';
			End
		If (isnull(@in_vchZone,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(t_wms_zone.zone,'''') like ''%' + isnull(@in_vchZone,'') + '%'' ';
			End
		If (isnull(@in_vchAgingSymbol,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and DATEDIFF(DAY, receive_date, GETDATE()) ' + @in_vchAgingSymbol + '' + convert(nvarchar,@in_vchAgingValue) + ' ';
			End
		If (isnull(@in_vchOwner,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(dbo.t_wms_owner.owner_code,'''') like ''%' + isnull(@in_vchOwner,'') + '%'' ';
			End	
		SET @v_vchSQLCommand = @v_vchSQLCommand + '		
		GROUP BY t_wms_owner.owner_code,t_wms_owner.owner_id , t_wms_wh.wh_id, location, t_wms_category.item_category, t_wms_item.inventory_type, 
				t_wms_item.item_number,
				t_wms_inventory_status.inv_status, t_wms_inventory.receive_date, t_wms_inventory.lpn, t_wms_inventory.parent_lpn, 
				t_wms_inventory.wh_master_id, t_wms_inventory.wh_item_master_id, t_wms_inventory.location_id, t_wms_inventory.inventory_status_id, 
				t_wms_inventory.inv_type, t_wms_item.item_master_id, CONVERT(nvarchar, dbo.t_wms_inventory.receive_date, 112),
				t_wms_location.loc_type, t_wms_location.pick_sequence, t_wms_item.description, 
				t_wms_item_uom.uom, t_wms_item_uom.uom_prompt, t_wms_item.price, t_wms_item.dg_code, 
				t_wms_item.grade, DATEDIFF(DAY, receive_date, GETDATE()),t_wms_zone.zone,t_wms_inventory.inventory_id,t_wms_inventory.attribute_group_id'
				print @v_vchSQLCommand
		Insert Into #TmpInventory exec sp_executesql @v_vchSQLCommand
		
		Select owner_code,owner_id,wh_id,location,item_category,inventory_type,item_number,qty_item,qty_item_allocated,
				inv_status,receive_date,lpn,parent_lpn,wh_master_id ,wh_item_master_id,location_id,
				inventory_status_id,inv_type,item_master_id,receive_date_filter,loc_type,pick_sequence,
				[description],uom,uom_prompt,price,dg_code,grade,aging,zone,Lot_number,Expiry_date,RemainAging From #TmpInventory
	
	End Try
	Begin Catch
		print ERROR_NUMBER();
		print ERROR_MESSAGE();
	End Catch	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_get_inventory_count_rows]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-05-28
-- Description:	Get Inventory data for PC Viewer
--
-- Modifed Date    Who     What
-------------------------------------------------------------------------------------------
-- 9 Aug 2013		Mark	Changed query to be a duplicate of the Select for the Data Grid
--							Added Zone as a paramater.
-- =============================================

-- =============================================
CREATE PROCEDURE [dbo].[usp_get_inventory_count_rows]
	@in_vchWarehouse	NVARCHAR(50) = null,
	@in_vchLocation		NVARCHAR(50) = null,
	@in_vchItemNumber	NVARCHAR(50) = null,
	@in_vchParentLPN	NVARCHAR(25) = null,
	@in_vchLPN			NVARCHAR(25) = null,
	@in_vchItemCategory	NVARCHAR(50) = null,
	@in_vchLotNumber	NVARCHAR(50) = null,
	@in_vchExpiryDate	NVARCHAR(50) = null,
	@in_vchSerialNumber	NVARCHAR(50) = null,
	@in_vchReceiveDate	NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode		NVARCHAR(50) = null,
	@in_vchZone			NVARCHAR(50) = null,
	@in_vchOwner		NVARCHAR(50) = null,
	@out_intCountRows	FLOAT OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	Declare @SQLCommand NVARCHAR(MAX)
	
	set @SQLCommand = 'select @out_intCountRows = COUNT(*) from v_wms_inventory_data where (0=0) '
	
	If (isnull(@in_vchWarehouse,'') <> '')
		set @SQLCommand = @SQLCommand + ' and wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
	If (isnull(@in_vchLocation,'') <> '')
		set @SQLCommand = @SQLCommand + ' and location like ''%' + isnull(@in_vchLocation,'') + '%'' ';
	If (isnull(@in_vchItemNumber,'') <> '')
		set @SQLCommand = @SQLCommand + ' and item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
	If (isnull(@in_vchParentLPN,'') <> '')
		set @SQLCommand = @SQLCommand + ' and parent_lpn like ''%' + isnull(@in_vchParentLPN,'') + '%'' ';
	If (isnull(@in_vchLPN,'') <> '')
		set @SQLCommand = @SQLCommand + ' and lpn like ''%' + isnull(@in_vchLPN,'') + '%'' ';
	If (isnull(@in_vchItemCategory,'') <> '')
		set @SQLCommand = @SQLCommand + ' and item_category like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
	If (isnull(@in_vchReceiveDate,'') <> '')
		set @SQLCommand = @SQLCommand + ' and CONVERT(nvarchar, receive_date, 112) like ''%' + isnull(@in_vchReceiveDate,'') + '%'' ';
	If (isnull(@in_vchInventoryStatus,'') <> '')
		set @SQLCommand = @SQLCommand + ' and inv_status like ''%' + isnull(@in_vchInventoryStatus,'') + '%'' ';
	If (isnull(@in_vchGrade,'') <> '')
		set @SQLCommand = @SQLCommand + ' and grade like ''%' + isnull(@in_vchGrade,'') + '%'' ';
	If (isnull(@in_vchDGCode,'') <> '')
		set @SQLCommand = @SQLCommand + ' and dg_code like ''%' + isnull(@in_vchDGCode,'') + '%'' ';
	If (isnull(@in_vchZone,'') <> '')
		set @SQLCommand = @SQLCommand + ' and zone like ''%' + isnull(@in_vchZone,'') + '%'' ';
	If (isnull(@in_vchOwner,'') <> '')
		set @SQLCommand = @SQLCommand + ' and owner_id like ''%' + isnull(@in_vchOwner,'') + '%'' ';
	If (isnull(@in_vchLotNumber,'') <> '')
		set @SQLCommand = @SQLCommand + ' and LOT like ''%' + isnull(@in_vchLotNumber,'') + '%'' ';
	If (isnull(@in_vchExpiryDate,'') <> '')
		set @SQLCommand = @SQLCommand + ' and EXPIRY_DATE like ''%' + isnull(@in_vchExpiryDate,'') + '%'' ';
	If (isnull(@in_vchSerialNumber,'') <> '')
		set @SQLCommand = @SQLCommand + ' and SERIAL_NUMBER like ''%' + isnull(@in_vchSerialNumber,'') + '%'' ';
	
	exec sp_executesql @SQLCommand,N'@out_intCountRows float output',@out_intCountRows output;
END

GO
/****** Object:  StoredProcedure [dbo].[usp_get_inventory_data_by_service]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_get_inventory_data_by_service]
	-- Add the parameters for the stored procedure here
	@in_vchCustomerCode  NVARCHAR(50) = NULL,
	@in_vchOwnerCode		NVARCHAR(50) = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @v_vchWhMasterID	varchar(40)

	SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE is_active = 'YES'

    -- Insert statements for procedure here
	SELECT inventory_id
		,location_id
		,location				
		,owner_id				
		,owner_code
		,wh_item_master_id		
		,item_number			
		,description AS item_description
		,inv_status		
		,lot_number		
		,expiry_date	
		,serial_number	
		,quantity
		,ISNULL(delivery_date,'') AS delivery_date
		,ISNULL(delivery_number,'') AS outbound_order_number
		,ISNULL(item_category,'') AS item_category
		,ISNULL(item_category_desc,'') AS item_category_desc
		,ISNULL(customer_code,'') AS customer_code	
		,ISNULL(customer_name,'') AS customer_name	
		,days_to_expire
		,create_date
		,create_by
		,sub_category
		,sub_category_desc
	FROM v_wms_inventory_count_external_order
	WHERE wh_master_id = @v_vchWhMasterID 
	AND customer_code = @in_vchCustomerCode
	AND owner_code = @in_vchOwnerCode
	AND inv_status	in ('Consignment','Missing CSM')
END

