/****** Object:  StoredProcedure [dbo].[usp_get_inventory_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-05-28
-- Description:	Get Inventory data
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_inventory_item]
	@in_vchWarehouse		NVARCHAR(50) = null,
	@in_vchLocation			NVARCHAR(50) = null,
	@in_vchItemNumber		NVARCHAR(50) = null,
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItemCategory		NVARCHAR(50) = null,
	@in_vchLotNumber		NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNumber		NVARCHAR(50) = null,
	@in_vchReceiveDate		NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode			NVARCHAR(50) = null,
	@in_vchOwner			NVARCHAR(50) = null,
	@in_vchExpiryDateTo		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;

	Begin Try
	
		Declare @v_vchSQLCommand NVARCHAR(4000)

		Create Table #TmpInventory(
		    owner_id nvarchar(50),
		    owner_code nvarchar(50),
			wh_id nvarchar(25),
			location nvarchar(50),
			item_category nvarchar(50),
			inventory_type nvarchar(40),
			item_number nvarchar(50),
			qty_item float,
			qty_item_allocated float,
			inv_status nvarchar(50),
			receive_date date,
			lpn nvarchar(25),
			parent_lpn nvarchar(25),
			inventory_id nvarchar(40),
			wh_master_id varchar(40),
			wh_item_master_id varchar(40),
			location_id varchar(40),
			inventory_status_id varchar(40),
			inv_type nvarchar(50),
			attribute_group_id nvarchar(50),
			item_master_id varchar(40),
			receive_date_filter nvarchar(20),
			loc_type nvarchar(20),
			pick_sequence int,
			[description] nvarchar(200),
			Checked bit,
			adjust_tran int,
			uom nvarchar(10),
			uom_prompt nvarchar(40),
			brand_name_long_text nvarchar(50),
			grade  nvarchar(40),
			price float,
			inv_status_show nvarchar(40),
			brand_name nvarchar(40),
			dg_code nvarchar(50),
			alternate_item_number nvarchar(40),
			lot_control nvarchar(20),
			expiry_date_control nvarchar(20),
			sn_control nvarchar(20),
			lpn_controlled nvarchar(20),
			days_to_expire int,
			zone_id nvarchar(40),
			zone nvarchar(50),
			capacity_qty float,
			adjust_qty float,
			SERIAL_NUMBER nvarchar(40),
			LOT nvarchar(40),
			[EXPIRY_DATE] nvarchar(40)
			)

			SET @v_vchSQLCommand = '
	SELECT     *
	FROM (SELECT TOP (100) PERCENT invtype.inv_attribute_type, atr.attribute_value, dbo.t_wms_inventory.owner_id,_owner.owner_code, dbo.t_wms_wh.wh_id, dbo.t_wms_location.location, 
          dbo.v_wms_item_by_wh.item_category, dbo.v_wms_item_by_wh.inventory_type, dbo.v_wms_item_by_wh.item_number, dbo.t_wms_inventory.quantity AS qty_item, 
          dbo.t_wms_inventory.quantity_allocated AS qty_item_allocated, dbo.t_wms_inventory_status.inv_status, dbo.t_wms_inventory.receive_date, dbo.t_wms_inventory.lpn, 
          dbo.t_wms_inventory.parent_lpn, dbo.t_wms_inventory.inventory_id, dbo.t_wms_inventory.wh_master_id, dbo.t_wms_inventory.wh_item_master_id, dbo.t_wms_inventory.location_id, 
          dbo.t_wms_inventory.inventory_status_id, dbo.t_wms_inventory.inv_type, dbo.t_wms_inventory.attribute_group_id, dbo.v_wms_item_by_wh.item_master_id, CONVERT(nvarchar(15), 
          dbo.t_wms_inventory.receive_date, 112) AS receive_date_filter, dbo.t_wms_location.loc_type, dbo.t_wms_location.pick_sequence, dbo.v_wms_item_by_wh.description, CAST(0 AS bit) 
          AS Checked, 0 AS adjust_tran, dbo.v_wms_item_by_wh.uom_prompt, dbo.v_wms_item_by_wh.uom, dbo.v_wms_item_by_wh.user_def2 AS brand_name_long_text, 
          dbo.v_wms_item_by_wh.grade, dbo.v_wms_item_by_wh.price, dbo.t_wms_inventory_status.description AS inv_status_show, dbo.v_wms_item_by_wh.item_category AS brand_name, 
          dbo.v_wms_item_by_wh.dg_code, dbo.v_wms_item_by_wh.alternate_item_number, dbo.t_wms_item.lot_control, dbo.t_wms_item.expiry_date_control, dbo.t_wms_item.sn_control, 
          dbo.t_wms_location.lpn_controlled, dbo.t_wms_item.days_to_expire, t_wms_zone.zone_id, t_wms_zone.zone, dbo.t_wms_location.capacity_qty, cast(0 AS decimal(18, 3)) 
          AS adjust_qty
     FROM dbo.t_wms_zone_location RIGHT OUTER JOIN
          dbo.t_wms_zone ON dbo.t_wms_zone_location.zone_id = dbo.t_wms_zone.zone_id RIGHT OUTER JOIN
          dbo.t_wms_inventory LEFT OUTER JOIN
          t_wms_inventory_attribute AS atr ON t_wms_inventory.inventory_id = atr.inventory_id AND t_wms_inventory.attribute_group_id = atr.attribute_group_id LEFT OUTER JOIN
          t_wms_inventory_attribute_type AS invtype ON atr.inv_attribute_type_id = invtype.inv_attribute_type_id INNER JOIN
          dbo.t_wms_wh ON dbo.t_wms_inventory.wh_master_id = dbo.t_wms_wh.wh_master_id INNER JOIN
          dbo.v_wms_item_by_wh ON dbo.t_wms_inventory.wh_item_master_id = dbo.v_wms_item_by_wh.wh_item_master_id INNER JOIN
          dbo.t_wms_inventory_status ON dbo.t_wms_inventory.inventory_status_id = dbo.t_wms_inventory_status.inventory_status_id INNER JOIN
          dbo.t_wms_location ON dbo.t_wms_inventory.location_id = dbo.t_wms_location.location_id INNER JOIN
          dbo.t_wms_item ON dbo.v_wms_item_by_wh.item_master_id = dbo.t_wms_item.item_master_id ON dbo.t_wms_zone_location.location_id = dbo.t_wms_location.location_id
		  INNER JOIN t_wms_owner AS _owner on t_wms_inventory.owner_id = _owner.owner_id
     WHERE (0=0)'
		If (isnull(@in_vchWarehouse,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_wh.wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
			End
		If (isnull(@in_vchLocation,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and location like ''%' + isnull(@in_vchLocation,'') + '%'' ';
			End
		If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and v_wms_item_by_wh.item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
			End	
		If (isnull(@in_vchParentLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and parent_lpn like ''%' + isnull(@in_vchParentLPN,'') + '%'' ';
			End
		If (isnull(@in_vchLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and lpn like ''%' + isnull(@in_vchLPN,'') + '%'' ';
			End		
		If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and v_wms_item_by_wh.item_category like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
			End		
		If (isnull(@in_vchReceiveDate,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,dbo.t_wms_inventory.receive_date,112) between ' + @in_vchReceiveDate  + ' AND '+ @in_vchReceiveDateTo + ' ';
			End
		If (isnull(@in_vchInventoryStatus,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and inv_status like ''%' + isnull(@in_vchInventoryStatus,'') + '%'' ';
			End		
		If (isnull(@in_vchGrade,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and v_wms_item_by_wh.grade like ''%' + isnull(@in_vchGrade,'') + '%'' ';
			End		
		If (isnull(@in_vchDGCode,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and v_wms_item_by_wh.dg_code like ''%' + isnull(@in_vchDGCode,'') + '%'' ';
			End		
		If (isnull(@in_vchOwner,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and dbo.t_wms_inventory.owner_id like ''%' + isnull(@in_vchOwner,'') + '%'' ';
			End		
		
		SET @v_vchSQLCommand = @v_vchSQLCommand + '			
			
			
		 ORDER BY dbo.t_wms_wh.wh_id) p PIVOT (max(attribute_value) FOR inv_attribute_type IN ([SERIAL_NUMBER], [LOT], [EXPIRY_DATE])) AS InventoryData
		 Where  isnull(LOT,'''') LIKE ''%' + isnull(@in_vchLotNumber,'') + '%''
				and isnull(SERIAL_NUMBER,'''') LIKE ''%' + isnull(@in_vchSerialNumber,'') + '%'''

		If (isnull(@in_vchExpiryDate,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,EXPIRY_DATE,112) between ' + @in_vchExpiryDate  + ' AND '+ @in_vchExpiryDateTo + ' ';
			End	

			print @v_vchSQLCommand
	
		Insert Into #TmpInventory exec sp_executesql @v_vchSQLCommand

		Select owner_code,
			owner_id ,
			wh_id ,
			location ,
			item_category ,
			inventory_type,
			item_number,
			qty_item,
			qty_item_allocated ,
			inv_status ,
			receive_date,
			lpn,
			parent_lpn ,
			inventory_id ,
			wh_master_id ,
			wh_item_master_id ,
			location_id ,
			inventory_status_id ,
			inv_type,
			attribute_group_id ,
			item_master_id,
			receive_date_filter,
			loc_type ,
			pick_sequence ,
			[description] ,
			Checked ,
			adjust_tran ,
			uom ,
			uom_prompt ,
			brand_name_long_text ,
			grade  ,
			price ,
			inv_status_show ,
			brand_name ,
			dg_code ,
			alternate_item_number,
			lot_control ,
			expiry_date_control ,
			sn_control,
			lpn_controlled ,
			days_to_expire ,
			zone_id ,
			zone ,
			capacity_qty ,
			adjust_qty,
			SERIAL_NUMBER,
			LOT ,
			[EXPIRY_DATE]

		From #TmpInventory
		
		Drop table #TmpInventory
    
	End Try
	Begin Catch
		print ERROR_NUMBER();
		print ERROR_MESSAGE();
	End Catch	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_get_inventory_item_viewer]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
