-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-05-28
-- Description:	Get Inventory data for PC Viewer
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_inventory_item_viewer]
	@in_vchWarehouse		NVARCHAR(50) = null,
	@in_vchLocation			NVARCHAR(50) = null,
	@in_vchItemNumber		NVARCHAR(50) = null,
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItemCategory		NVARCHAR(50) = null,
	@in_vchLotNumber		NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNumber		NVARCHAR(50) = null,
	@in_vchReceiveDate		NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode			NVARCHAR(50) = null,
	@in_vchZone				NVARCHAR(50) = null,
	@in_vchOwner			NVARCHAR(50) = null,
	@in_vchExpiryDateTo		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;
	Begin Try
	
		Declare @v_vchSQLCommand NVARCHAR(4000)

		Create Table #TmpInventory(
			inventory_id	varchar(40),
			wh_id			nvarchar(25),
			location		nvarchar(50),
			item_category	nvarchar(50),
			item_number		nvarchar(50),
			qty_item		float,
			qty_item_allocated float,
			inv_status		nvarchar(50),
			receive_date	date,
			lpn				nvarchar(25),
			parent_lpn		nvarchar(25),
			receive_date_filter nvarchar(20),
			[description]	nvarchar(200),
			uom_prompt		nvarchar(40),
			uom				nvarchar(10),
			brand_name_long_text nvarchar(50),
			grade			nvarchar(40),
			price			float,
			inv_status_show nvarchar(40),
			brand_name		nvarchar(40),
			dg_code			nvarchar(50),
			days_to_expire	int,
			zone			nvarchar(50),
			owner_id		nvarchar(50),
			item_max_qty	float,
			item_min_qty	float,
			SERIAL_NUMBER	nvarchar(40),
			LOT				nvarchar(40),
			[EXPIRY_DATE]	nvarchar(40)
			)
SET @v_vchSQLCommand = '
		SELECT     *
		FROM (SELECT TOP (100) PERCENT invtype.inv_attribute_type
		, atr.attribute_value
		, t_wms_inventory.inventory_id
		, dbo.t_wms_wh.wh_id
		, dbo.t_wms_location.location
		, dbo.t_wms_category.item_category
		, dbo.t_wms_item.item_number
		, dbo.t_wms_inventory.quantity AS qty_item
		, dbo.t_wms_inventory.quantity_allocated AS qty_item_allocated
		, dbo.t_wms_inventory_status.inv_status
		, dbo.t_wms_inventory.receive_date
		, dbo.t_wms_inventory.lpn, dbo.t_wms_inventory.parent_lpn
		, CONVERT(nvarchar(15), dbo.t_wms_inventory.receive_date, 112) AS receive_date_filter
		, dbo.t_wms_item.description
		, dbo.t_wms_item_uom.uom_prompt
		, dbo.t_wms_item_uom.uom
		, dbo.t_wms_item.user_def2 AS brand_name_long_text
		, dbo.t_wms_item.grade
		, dbo.t_wms_item.price
		, dbo.t_wms_inventory_status.description AS inv_status_show
		, dbo.t_wms_category.item_category AS brand_name
		, dbo.t_wms_item.dg_code
		, dbo.t_wms_item.days_to_expire
		, dbo.t_wms_zone.zone
		, t_wms_owner.owner_code	AS owner_id
		, dbo.t_wms_item.max_qty	AS item_max_qty
		, dbo.t_wms_item.min_qty	AS item_min_qty
		FROM dbo.t_wms_zone_location 
		RIGHT OUTER JOIN dbo.t_wms_zone ON dbo.t_wms_zone_location.zone_id = dbo.t_wms_zone.zone_id 
		RIGHT OUTER JOIN dbo.t_wms_inventory 
		LEFT OUTER JOIN dbo.t_wms_inventory_attribute AS atr ON dbo.t_wms_inventory.inventory_id = atr.inventory_id 
														     AND dbo.t_wms_inventory.attribute_group_id = atr.attribute_group_id 
		LEFT OUTER JOIN dbo.t_wms_inventory_attribute_type AS invtype ON atr.inv_attribute_type_id = invtype.inv_attribute_type_id 
		INNER JOIN dbo.t_wms_wh ON dbo.t_wms_inventory.wh_master_id = dbo.t_wms_wh.wh_master_id 
		INNER JOIN dbo.t_wms_wh_item ON dbo.t_wms_inventory.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
		INNER JOIN dbo.t_wms_inventory_status ON dbo.t_wms_inventory.inventory_status_id = dbo.t_wms_inventory_status.inventory_status_id 
		INNER JOIN dbo.t_wms_location ON dbo.t_wms_inventory.location_id = dbo.t_wms_location.location_id 
		INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
								  ON dbo.t_wms_zone_location.location_id = dbo.t_wms_location.location_id
		INNER JOIN t_wms_owner on t_wms_inventory.owner_id = t_wms_owner.owner_id 
		INNER JOIN t_wms_item_uom on t_wms_item.item_master_id = t_wms_item_uom.item_master_id  AND t_wms_item_uom.primary_uom = ''YES''
		INNER JOIN t_wms_category on t_wms_item.category_id = t_wms_category.category_id
		WHERE (0=0)'

		If (isnull(@in_vchWarehouse,'') <> '')
			Begin
			    SELECT TOP 1  @in_vchWarehouse = part FROM [dbo].[SplitString] (@in_vchWarehouse,':')
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_wh.wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
			End
		If (isnull(@in_vchLocation,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and location like ''%' + isnull(@in_vchLocation,'') + '%'' ';
			End
		If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_item.item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
			End	
		If (isnull(@in_vchParentLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and parent_lpn like ''%' + isnull(@in_vchParentLPN,'') + '%'' ';
			End
		If (isnull(@in_vchLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and lpn like ''%' + isnull(@in_vchLPN,'') + '%'' ';
			End		
		If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_category.item_category like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
			End		
		If (isnull(@in_vchReceiveDate,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,dbo.t_wms_inventory.receive_date,112) between ' + @in_vchReceiveDate  + ' AND '+ @in_vchReceiveDateTo + ' ';
			End
		If (isnull(@in_vchInventoryStatus,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and inv_status like ''%' + isnull(@in_vchInventoryStatus,'') + '%'' ';
			End		
		If (isnull(@in_vchGrade,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_item.grade like ''%' + isnull(@in_vchGrade,'') + '%'' ';
			End		
		If (isnull(@in_vchDGCode,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_item.dg_code like ''%' + isnull(@in_vchDGCode,'') + '%'' ';
			End
		If (isnull(@in_vchZone,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_zone.zone like ''%' + isnull(@in_vchZone,'') + '%'' ';
			End			
		If (isnull(@in_vchOwner,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and dbo.t_wms_inventory.owner_id like ''%' + isnull(@in_vchOwner,'') + '%'' ';
			End	
				
		SET @v_vchSQLCommand = @v_vchSQLCommand + '	
		
		 ORDER BY dbo.t_wms_wh.wh_id) p PIVOT (max(attribute_value) FOR inv_attribute_type IN ([SERIAL_NUMBER], [LOT], [EXPIRY_DATE])) AS InventoryData
		 Where  (0=0) '

		If (isnull(@in_vchExpiryDate,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,EXPIRY_DATE,112) between ' + @in_vchExpiryDate  + ' AND '+ @in_vchExpiryDateTo + ' ';
			End
		If (isnull(@in_vchLotNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and LOT like ''%' + isnull(@in_vchLotNumber,'') + '%'' ';
			End	
		If (isnull(@in_vchSerialNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and SERIAL_NUMBER like ''%' + isnull(@in_vchSerialNumber,'') + '%'' ';
			End	
		Insert Into #TmpInventory exec sp_executesql @v_vchSQLCommand

		SELECT
			wh_id
			, location
			, item_category
			, item_number
			, qty_item 
			, qty_item_allocated 
			, inv_status
			, receive_date 
			, lpn
			, parent_lpn 
			, receive_date_filter 
			, [description] 
			, uom_prompt
			, uom 
			, brand_name_long_text 
			, grade 
			, price 
			, inv_status_show 
			, brand_name
			, dg_code
			, days_to_expire 
			, zone
			, owner_id 
			, SERIAL_NUMBER
			, LOT
			, [EXPIRY_DATE]
			, item_max_qty
			, item_min_qty
		From #TmpInventory 
		Drop table #TmpInventory

    End Try
	Begin Catch
		print ERROR_NUMBER();
		print ERROR_MESSAGE();
	End Catch	  
END

GO
/****** Object:  StoredProcedure [dbo].[usp_get_inventory_sum_by_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-05-28
-- Description:	Get Inventory data
-- =============================================

CREATE PROCEDURE [dbo].[usp_get_inventory_sum_by_item]
	@in_vchWarehouse		NVARCHAR(50) = null,
	@in_vchLocation			NVARCHAR(50) = null,
	@in_vchItemNumber		NVARCHAR(50) = null,
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItemCategory		NVARCHAR(50) = null,
	@in_vchLotNumber		NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNumber		NVARCHAR(50) = null,
	@in_vchReceiveDate		NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode			NVARCHAR(50) = null,
	@in_vchZone				NVARCHAR(50) = null,
	@in_vchOwner			NVARCHAR(50) = null,
	@in_vchExpiryDateTo		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null
AS
BEGIN
	SET NOCOUNT ON;
	SET FMTONLY OFF;

	Begin Try
	
		Declare @v_vchSQLCommand NVARCHAR(4000)

		CREATE TABLE #TmpInventory(
			wh_id			NVARCHAR(25),
			qty_item		FLOAT,
			inv_status		NVARCHAR(50),
			owner_code		NVARCHAR(40),
			owner_name		NVARCHAR(100),
			item_number		NVARCHAR(50),
			[description]	NVARCHAR(200),
			dg_code			NVARCHAR(50),
			price			FLOAT,
			grade			NVARCHAR(40),
			item_min_qty	FLOAT,
			item_max_qty	FLOAT,
			category_id		NVARCHAR(40),
			item_category	NVARCHAR(50),
			uom				NVARCHAR(10),
			uom_prompt		NVARCHAR(40)			
			)

			SET @v_vchSQLCommand = '
				SELECT wh.wh_id
					, SUM(inv.quantity) AS qty_item
					, invStatus.inv_status
					, own.owner_code
					, own.owner_name
					, tItem.item_number
					, tItem.description
					, tItem.dg_code
					, tItem.price
					, tItem.grade
					, tItem.min_qty
					, tItem.max_qty
					, tItem.category_id
					, tItem.item_category
					, tItem.uom
					, tItem.uom_prompt
				FROM t_wms_inventory inv
				INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
				INNER JOIN t_wms_wh wh ON inv.wh_master_id = wh.wh_master_id
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				LEFT JOIN t_wms_zone_location zl on loc.location_id = zl.location_id
				LEFT JOIN t_wms_zone z on zl.zone_id = z.zone_id
				INNER JOIN t_wms_owner own ON inv.owner_id = own.owner_id
				INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
				INNER JOIN (SELECT item.item_master_id
								,item.item_number
								,item.description
								,item.dg_code
								,item.price
								,item.grade
								,item.min_qty
								,item.max_qty
								,cate.category_id
								,cate.item_category
								,uom.uom
								,uom.uom_prompt
							FROM t_wms_item item
							LEFT JOIN t_wms_item_uom uom on item.item_master_id = uom.item_master_id AND uom.primary_uom = ''YES''
							LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
							) tItem ON whItem.item_master_id = tItem.item_master_id
			WHERE (0=0) '

	 If (isnull(@in_vchWarehouse,'') <> '')
			Begin
				SELECT TOP 1  @in_vchWarehouse = part FROM [dbo].[SplitString] (@in_vchWarehouse,':')
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and wh.wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
			End
	If (isnull(@in_vchLocation,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and loc.location like ''%' + isnull(@in_vchLocation,'') + '%'' ';
			End
	If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and tItem.item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
			End	
	If (isnull(@in_vchParentLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(inv.parent_lpn,'''') ''%' + isnull(@in_vchParentLPN,'') + '%'' ';
			End
	If (isnull(@in_vchLPN,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(inv.lpn,'''') like ''%' + isnull(@in_vchLPN,'') + '%'' ';
			End		
	If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(tItem.item_category,'''') like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
			End		
	If (isnull(@in_vchReceiveDate,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and CONVERT(NVARCHAR,inv.receive_date,112) between ' + @in_vchReceiveDate  + ' AND '+ @in_vchReceiveDateTo + ' ';
			End
	If (isnull(@in_vchInventoryStatus,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and invStatus.inv_status like ''%' + isnull(@in_vchInventoryStatus,'') + '%'' ';
			End		
	If (isnull(@in_vchGrade,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(tItem.grade,'''') like ''%' + isnull(@in_vchGrade,'') + '%'' ';
			End		
	If (isnull(@in_vchDGCode,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(tItem.dg_code,'''') like ''%' + isnull(@in_vchDGCode,'') + '%'' ';
			End
	If (isnull(@in_vchZone,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(z.zone,'''') like ''%' + isnull(@in_vchZone,'') + '%'' ';
			End
					
	If (isnull(@in_vchOwner,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and isnull(own.owner_id,'''') like ''%' + isnull(@in_vchOwner,'') + '%'' ';
			End		
	SET @v_vchSQLCommand = @v_vchSQLCommand + '	
	GROUP BY wh.wh_id
		 , invStatus.inv_status
		 , own.owner_code
		 , own.owner_name
		 , tItem.item_number
		 , tItem.description
		 , tItem.dg_code
		 , tItem.price
		 , tItem.grade
		 , tItem.min_qty
		 , tItem.max_qty
		 , tItem.category_id
		 , tItem.item_category
		 , tItem.uom
		 , tItem.uom_prompt'
	
	INSERT INTO #TmpInventory exec sp_executesql @v_vchSQLCommand
			SELECT wh_id	
				, qty_item
				, inv_status
				, owner_code
				, owner_name
				, item_number
				, [description]	
				, dg_code
				, price
				, grade
				, item_min_qty	
				, item_max_qty	
				, category_id	
				, item_category	
				, uom
				, uom_prompt
			From #TmpInventory
      END TRY
	BEGIN CATCH
		PRINT ERROR_NUMBER();
		PRINT ERROR_MESSAGE();
	END CATCH	
END






GO
/****** Object:  StoredProcedure [dbo].[usp_get_Inventory_sum_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[usp_get_Inventory_sum_qty] 
	@in_vchWarehouse	NVARCHAR(50) = null,
	@in_vchItemNumber	NVARCHAR(50) = null,
	@in_vchItemCategory	NVARCHAR(50) = null,
	@in_vchOwner	NVARCHAR(50) = null
AS
BEGIN
SET NOCOUNT ON;
	SET FMTONLY OFF;
	Begin Try
	
		Declare @v_vchSQLCommand NVARCHAR(4000)

		Create Table #TmpInventory(
		    item_number nvarchar(50),
			[description] nvarchar(200),
			owner_id nvarchar(50),
			uom nvarchar(120),
			inv_status nvarchar(50),
			item_category nvarchar(50),
			wh_id nvarchar(50),
			sum_qty float,
			diff float
			)

		SET @v_vchSQLCommand = '

		SELECT     dbo.t_wms_item.item_number, dbo.t_wms_item.description, dbo.t_wms_owner.owner_code AS owner_id, dbo.t_wms_item_uom.uom, 
                      dbo.t_wms_inventory_status.inv_status, dbo.t_wms_item.item_category, dbo.t_wms_wh.wh_id, 
                      SUM(DISTINCT dbo.t_wms_inventory.quantity - dbo.t_wms_inventory.quantity_allocated) AS sum_qty, 
                      SUM(DISTINCT dbo.t_wms_inventory.quantity - dbo.t_wms_inventory.quantity_allocated - dbo.t_wms_outbound_detail.quantity_order) AS diff
FROM         dbo.t_wms_outbound_master INNER JOIN
                      dbo.t_wms_outbound_detail ON dbo.t_wms_outbound_master.outbound_order_master_id = dbo.t_wms_outbound_detail.outbound_order_master_id LEFT OUTER JOIN
                      dbo.t_wms_inventory INNER JOIN
                      dbo.t_wms_wh_item ON dbo.t_wms_inventory.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id INNER JOIN
                      dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id INNER JOIN
                      dbo.t_wms_item_uom ON dbo.t_wms_item.item_master_id = dbo.t_wms_item_uom.item_master_id INNER JOIN
                      dbo.t_wms_inventory_status ON dbo.t_wms_inventory.inventory_status_id = dbo.t_wms_inventory_status.inventory_status_id INNER JOIN
                      dbo.t_wms_wh ON dbo.t_wms_inventory.wh_master_id = dbo.t_wms_wh.wh_master_id INNER JOIN
                      dbo.t_wms_owner ON dbo.t_wms_inventory.owner_id = dbo.t_wms_owner.owner_id ON 
                      dbo.t_wms_outbound_detail.wh_item_master_id = dbo.t_wms_inventory.wh_item_master_id
WHERE        (0 = 0) AND (dbo.t_wms_item_uom.primary_uom = ''YES'') AND (dbo.t_wms_inventory_status.inv_status = ''Normal'') AND (dbo.t_wms_outbound_master.order_status = ''PENDING'') '

		If (isnull(@in_vchWarehouse,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and t_wms_wh.wh_id like ''%' + isnull(@in_vchWarehouse,'') + '%'' ';
			End
		If (isnull(@in_vchItemNumber,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and dbo.t_wms_item.item_number like ''%' + isnull(@in_vchItemNumber,'') + '%'' ';
			End
		If (isnull(@in_vchItemCategory,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and dbo.t_wms_item.item_category like ''%' + isnull(@in_vchItemCategory,'') + '%'' ';
			End
	    If (isnull(@in_vchOwner,'') <> '')
			Begin
				SET @v_vchSQLCommand = @v_vchSQLCommand + ' and dbo.t_wms_item.owner_id like ''%' + isnull(@in_vchOwner,'') + '%'' ';
			End	
		SET @v_vchSQLCommand = @v_vchSQLCommand +'

			GROUP BY dbo.t_wms_item.item_number, dbo.t_wms_item.description, dbo.t_wms_owner.owner_code, dbo.t_wms_item_uom.uom, dbo.t_wms_inventory_status.inv_status, 
                      dbo.t_wms_item.item_category, dbo.t_wms_wh.wh_id, dbo.t_wms_wh.wh_id
'
		
		print @v_vchSQLCommand
		Insert Into #TmpInventory exec sp_executesql @v_vchSQLCommand

		SELECT 
		  item_number ,
			[description] ,
			owner_id,
			uom ,
			inv_status ,
			item_category ,
			wh_id ,
			sum_qty ,
			diff
		From #TmpInventory 
		 End Try
	Begin Catch
		print ERROR_NUMBER();
		print ERROR_MESSAGE();
	End Catch
END




GO
/****** Object:  StoredProcedure [dbo].[usp_get_inventory_view]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/******************* Script for update inventory viewer **************************************/
CREATE PROCEDURE[dbo].[usp_get_inventory_view]
(
	@mode as varchar(40) = NULL,
	@value as varchar(40) =  NULL,
	@wh_id as varchar(40) = NULL
)
AS
BEGIN

	DECLARE @in_locationID	VARCHAR(40)

	IF @mode = 'LOCATION'
		BEGIN
			SELECT TOP 1 @in_locationID = location_id
			FROM t_wms_location loc
			LEFT JOIN t_wms_wh wh on loc.wh_master_id = wh.wh_master_id
			WHERE location = @value
			AND wh_id = @wh_id

			SELECT 
				 ISNULL(inv.parent_lpn,'')		AS Parent_LPN
				,ISNULL(item.item_number,'')	AS Match
				,ISNULL(item.description,'')	AS Match_Description
				,COUNT(inv.lpn)					AS Count_LPN
				,'' AS Batch
				,'' AS LPN
				,'' AS Location
			FROM t_wms_inventory inv
			LEFT JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			WHERE inv.location_id = @in_locationID
			GROUP BY inv.parent_lpn, item.item_number,item.description
			ORDER BY item.item_number
		END
	ELSE IF @mode = 'PARENT'
		BEGIN
			SELECT
				 ISNULL(item.item_number,'')	AS Match
				,ISNULL(item.description,'')	AS Match_Description
				,ISNULL(atr.attribute_value,'')	AS Batch
				,COUNT(inv.lpn)					AS Count_LPN
				, '' AS Parent_LPN
				, '' AS LPN
				, loc.location AS Location
			FROM t_wms_inventory inv
			LEFT JOIN t_wms_inventory_attribute AS atr ON inv.inventory_id = atr.inventory_id AND inv.attribute_group_id = atr.attribute_group_id 
			LEFT JOIN t_wms_inventory_attribute_type AS attrType ON atr.inv_attribute_type_id = attrType.inv_attribute_type_id 
			LEFT JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			LEFT JOIN t_wms_location loc ON inv.location_id = loc.location_id
			WHERE attrType.inv_attribute_type = 'LOT'
			AND inv.parent_lpn = @value
			GROUP BY item.item_number
			,item.description
			,atr.attribute_value
			,loc.location
			ORDER BY item.item_number
		END
	ELSE IF @mode = 'ITEM'
		BEGIN
			SELECT
				inv.lpn AS LPN
				,ISNULL(atr.attribute_value,'')	AS Batch
				,inv.parent_lpn AS Parent_LPN
				,loc.location AS Location
				,'' AS Match
				,'' AS Match_Description
				,NULL AS Count_LPN
			FROM t_wms_inventory inv
			LEFT JOIN t_wms_inventory_attribute AS atr ON inv.inventory_id = atr.inventory_id AND inv.attribute_group_id = atr.attribute_group_id 
			LEFT JOIN t_wms_inventory_attribute_type AS attrType ON atr.inv_attribute_type_id = attrType.inv_attribute_type_id 
			LEFT JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
			LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			LEFT JOIN t_wms_location loc ON inv.location_id = loc.location_id
			WHERE attrType.inv_attribute_type = 'LOT'
			AND item.item_number = @value
			ORDER BY item.item_number
		END

END

/***********************************************************

exec [usp_get_inventory_view] @mode = 'PARENT', @value = '2A9', @wh_id = '1311'

************************************************************/



GO
/****** Object:  StoredProcedure [dbo].[usp_get_invetory_last_update]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_get_invetory_last_update]
(
	@in_vchCustomerCode	    NVARCHAR(50),
	@out_vchInvLastUpdate	DATETIME OUTPUT
)
AS
BEGIN
	DECLARE @v_vchlocationID	NVARCHAR(40)
	DECLARE @v_locationUpdateDate	DATETIME
	
	--Get customer Location
	SELECT @v_vchlocationID = loc.location_id
	FROM t_wms_customer_location loc
	LEFT JOIN t_wms_customer cust ON loc.customer_id = cust.customer_id
	WHERE cust.customer_code = @in_vchCustomerCode
	
	--Get Inventory Last Update
	--SELECT TOP 1 @out_vchInvLastUpdate = create_date 
	--FROM t_wms_inventory 
	--WHERE location_id = @v_vchlocationID
	--ORDER BY [rowversion] DESC

	SELECT @out_vchInvLastUpdate = MAX(inv_att.create_date) 
	FROM [dbo].[t_wms_inventory_attribute] inv_att
	WHERE inv_att.inventory_id IN(
		SELECT inventory_id 
		FROM t_wms_inventory 
		WHERE location_id = @v_vchlocationID
	)

	SELECT TOP 1 @v_locationUpdateDate = [update_date] FROM [dbo].[t_wms_location]
	WHERE [location_id] = @v_vchlocationID
	IF @v_locationUpdateDate IS NOT NULL
	BEGIN
		IF @v_locationUpdateDate > @out_vchInvLastUpdate
		BEGIN
			SET @out_vchInvLastUpdate = @v_locationUpdateDate
		END
	END


END
