/****** Object:  StoredProcedure [dbo].[usp_get_ReferenceID]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_get_ReferenceID]
	@v_vchReferenceID	NVARCHAR(50) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE 
			@v_intRunningID			INT,
			@v_dtpDateNow			NVARCHAR(6)

	SET @v_dtpDateNow = LEFT(CONVERT(NVARCHAR,GETDATE(),112),6);
	
	-- Add the T-SQL statements to compute the return value here
	SELECT @v_vchReferenceID = MAX(CONVERT(DECIMAL,working_date)),@v_intRunningID = last_running FROM t_com_reference_running
	WHERE working_date = @v_dtpDateNow 
	GROUP BY working_date,last_running
	
	IF (@v_vchReferenceID IS NULL)
		BEGIN
			SET @v_vchReferenceID = 'REF-'+ @v_dtpDateNow + '0000001';
			INSERT INTO t_com_reference_running(record_id,working_date, last_running) VALUES (NEWID(),@v_dtpDateNow,1)
		END
	ELSE
		BEGIN
			SET @v_vchReferenceID = 'REF-'+ @v_vchReferenceID + CONVERT(NVARCHAR,RIGHT('0000000' + CONVERT(NVARCHAR,@v_intRunningID + 1),7))
			UPDATE t_com_reference_running SET last_running = last_running + 1 WHERE working_date = @v_dtpDateNow
		END		
END
