/****** Object:  StoredProcedure [dbo].[usp_get_resouce_value]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012/08/21
-- Description:	Get resource
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_resouce_value]
	@in_vchApplicationID	NVARCHAR(40),
	@in_vchResourceName		NVARCHAR(50),
	@in_intLocaleID			INT,
	@in_vchParam1			NVARCHAR(50),
	@in_vchParam2			NVARCHAR(50),
	@in_vchParam3			NVARCHAR(50) = null,
	@in_vchParam4			NVARCHAR(50) = null,
	@in_vchParam5			NVARCHAR(50) = null,
	@out_vchTextValue		NVARCHAR(250) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	Declare @v_vchTextValue NVARCHAR(250)
	
    -------------------------------------------------------------------------  
 --  Set Resource based on detail in the Resource Detail table  
 -------------------------------------------------------------------------  
    SELECT @v_vchTextValue = RSD.value  
	 FROM t_com_resource_detail RSD, t_com_resource_master RSM  
	 WHERE RSM.resource_master_id = RSD.resource_master_id  
	 AND RSM.resource_name = @in_vchResourceName  
	 AND RSD.locale_id = @in_intLocaleID  
	 AND RSM.app_id = @in_vchApplicationID  
   
 -------------------------------------------------------------------------  
 --  No Detail Records so set by Default in Master Record  
 -------------------------------------------------------------------------  
 IF @v_vchTextValue IS NULL  
 BEGIN  
	SELECT @v_vchTextValue = default_value  
	FROM t_com_resource_master RSM  
	WHERE RSM.resource_name = @in_vchResourceName  
 END  
   
 -------------------------------------------------------------------------  
 --  No Value in Master Record or No Master so Set a Default   
 -------------------------------------------------------------------------  
 IF @v_vchTextValue IS NULL  
 BEGIN  
	SELECT @v_vchTextValue = 'NO RESOURCE CONFIGURED'  
 END  
  
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------  
EXIT_LABEL:  
	
	set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param1',@in_vchParam1);
	set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param2',@in_vchParam2);
	set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param3',@in_vchParam3);
	set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param4',@in_vchParam4);
	set @v_vchTextValue = REPLACE(@v_vchTextValue,'@param5',@in_vchParam5);
	
    -- Always leave from here.  
    select @v_vchTextValue AS value
	
END


