/****** Object:  StoredProcedure [dbo].[usp_get_zone_location]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_get_zone_location]
	@in_vchZone		NVARCHAR(50),
	@in_vchLocation	NVARCHAR(50) = NULL,
	@in_vchLocationType	NVARCHAR(50) = NULL
AS
BEGIN

	SET NOCOUNT ON;
	SET FMTONLY OFF;
	
	Create Table #ZoneLocation
	(
		is_select Bit,
		Location_ID	VARCHAR(40),
		Location NvarChar(50),
		Location_Type	NVARCHAR(50),
		Is_Active	NvarChar(30)
	)
	Declare @v_vchSQLCommand NVARCHAR(MAX) = ''
	
	SET @v_vchSQLCommand = '
	SELECT	TOP (100) PERCENT case zone when ''' + @in_vchZone + ''' then 1 else 0 End AS is_select, 
	dbo.t_wms_location.location_id,dbo.t_wms_location.location,dbo.t_wms_location.loc_type, 
	case dbo.t_wms_zone_location.is_active WHEN ''YES'' then ''true'' else ''false'' End as is_active
	FROM    dbo.t_wms_zone INNER JOIN
			dbo.t_wms_zone_location ON dbo.t_wms_zone.zone_id = dbo.t_wms_zone_location.zone_id RIGHT OUTER JOIN
			dbo.t_wms_location ON dbo.t_wms_zone_location.location_id = dbo.t_wms_location.location_id
	WHERE (0=0) 
	'
	IF (isnull(@in_vchLocation,'') <> '')
		SET @v_vchSQLCommand = @v_vchSQLCommand + ' and  location like ''%' + @in_vchLocation + '%'' ';

	IF (isnull(@in_vchLocationType,'') <> '')
		SET @v_vchSQLCommand = @v_vchSQLCommand + ' and  loc_type like ''%' + @in_vchLocationType + '%'' ';
					
	SET @v_vchSQLCommand = @v_vchSQLCommand + ' ORDER BY dbo.t_wms_zone.zone ,t_wms_location.location';
	
	Insert Into #ZoneLocation exec sp_executesql @v_vchSQLCommand
	Select is_select,Location_ID,Location,Location_Type,Is_Active from #ZoneLocation
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_GetNextValue]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_GetNextValue]
(
    @in_vchRuleCode NVARCHAR(40),
    @in_vchWarehouseID NVARCHAR(50),
    @in_vchRuleType NVARCHAR(40) = 'WH_CONTROL'
    )
AS
BEGIN
    DECLARE
    -- Local Variables
    @v_intNextValue	INTEGER,
    @v_intCurrentValue	INTEGER,
    @v_vchRuleID	varchar(40),
    @v_vchValue NVARCHAR(30)
    
    SELECT @v_intCurrentValue = CONVERT(INT, value), @v_vchRuleID = rule_id 
	FROM v_wms_wh_rule
	WHERE rule_code = @in_vchRuleCode
	AND wh_id = @in_vchWarehouseID
	AND type = @in_vchRuleType
	
	IF @v_intCurrentValue < 1 SET @v_intCurrentValue = 1
	SET  @v_intNextValue = @v_intCurrentValue + 1
	SET @v_vchValue = CONVERT(NVARCHAR(10), @v_intNextValue) 
	
	UPDATE t_wms_rule set [value] = @v_vchValue WHERE rule_id = @v_vchRuleID	
	
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:
    -- Always leave from here.
    RETURN @v_intNextValue 
END


GO
/****** Object:  StoredProcedure [dbo].[usp_GetSchemaChooseColumn]    Script Date: 08/08/2025 11:11:30 ******/
