GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_GetSchemaChooseColumn]
(
	@in_vchTableName	VARCHAR(250),
	@in_vchProcessSub	VARCHAR(50),
	@in_vchActionCode	VARCHAR(50)
)
AS
BEGIN
	SELECT dt.field_name
		,type
		,lenght
		,is_default
		,default_value
		,is_require
		,is_running
		,format_running
		,lenght_running
		,column_reference
	FROM t_interface_datamap_header hd
	LEFT JOIN t_interface_datamap_detail dt on hd.datamap_name = dt.datamap_name
	WHERE hd.process_sub = @in_vchProcessSub
	AND hd.action_code = @in_vchActionCode
	AND dt.field_name NOT IN (SELECT req.field_name FROM t_interface_datamap_require req
						      WHERE req.process_sub = @in_vchProcessSub)
	ORDER BY dt.position
END




