CREATE PROCEDURE [dbo].[usp_GetSchemaNotChooseColumn]
(
	@in_vchTableName	VARCHAR(250),
	@in_vchProcessSub	VARCHAR(50),
	@in_vchActionCode	VARCHAR(50)
)
AS
BEGIN
	SELECT 
		TABLE_CATALOG		AS DatabaseName,
		TABLE_NAME			AS TableName,
		COLUMN_NAME			AS ColumnName,
		ORDINAL_POSITION	AS Position,
		COLUMN_DEFAULT		AS ColumnDefault,
		CASE IS_NULLABLE WHEN 'NO' THEN 'YES' ELSE 'NO' END	 AS NotAllowNull,
		DATA_TYPE					AS DataType,
		CHARACTER_MAXIMUM_LENGTH	AS Length
	FROM INFORMATION_SCHEMA.COLUMNS 
	WHERE TABLE_Name = @in_vchTableName
	AND COLUMN_NAME <> 'rowversion'
	AND COLUMN_NAME NOT IN (SELECT dt.field_name FROM t_interface_datamap_header hd
							LEFT JOIN t_interface_datamap_detail dt ON hd.datamap_name = dt.datamap_name
							WHERE hd.process_sub = @in_vchProcessSub
							AND hd.action_code = @in_vchActionCode
							UNION ALL 
							SELECT req.field_name FROM t_interface_datamap_require req
							WHERE req.process_sub = @in_vchProcessSub
						   )

END




