CREATE PROCEDURE [dbo].[usp_host_wms_insert_inventory_adjust]
(
	@in_vchHostRecordID		VARCHAR(50),
	@in_vchLocation			NVARCHAR(50),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchLotNumber		NVARCHAR(50),
	@in_fltQuantity			INT,
	@in_vchUserID			NVARCHAR(25),
	@out_vchErrorCode		NVARCHAR(25)  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchErrorMsgDetail	NVARCHAR(1000) OUTPUT,
	@out_vchErrorType		NVARCHAR(50) OUTPUT
)
AS
BEGIN	
	DECLARE @v_vchApplicationID	 VARCHAR(40),
			@v_vchHostRecordID	 NVARCHAR(50)
		
	SELECT TOP 1 @v_vchHostRecordID = host_record_id FROM t_host_wms_inventory_compare ORDER BY create_date DESC

	SET @v_vchApplicationID = '2A14C878-2292-44B0-9CE6-F791C7E9870A'
	SET @out_vchErrorType = 'FILE_ERROR'

	SELECT invCompare.location
		,invCompare.item_number	
		,invCompare.lot_number
	INTO #tempInvExport
	FROM (SELECT location,item_number,lot_number FROM t_host_wms_inventory_compare WHERE host_record_id = @v_vchHostRecordID AND location LIKE '1%'
			UNION
			SELECT location,item_number,lot_number FROM v_wms_inventory_data_by_serial WHERE location LIKE '1%'
		  ) invCompare

	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE location = @in_vchLocation)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Location[' + ISNULL(@in_vchLocation,'') + '] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END
	
	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE item_number = @in_vchItemNumber)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Item Number[' + ISNULL(@in_vchItemNumber,'') + '] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END
	
	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE lot_number = @in_vchLotNumber)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Lot Number[' + ISNULL(@in_vchLotNumber,'') + '] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END

	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE location = @in_vchLocation AND item_number = @in_vchItemNumber)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Location[' + ISNULL(@in_vchLocation,'') + '] and Item Number [' + @in_vchItemNumber + '] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END

	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE location = @in_vchLocation AND lot_number = @in_vchLotNumber)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Location[' + ISNULL(@in_vchLocation,'') + '] and Lot Number ['+@in_vchLotNumber+'] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END

	IF NOT EXISTS (SELECT * FROM #tempInvExport WHERE location = @in_vchLocation AND item_number = @in_vchItemNumber AND lot_number = @in_vchLotNumber)	
		BEGIN
			SET @out_vchErrorCode = 'ERROR-HIM-028'
			SET @out_vchErrorMsgDetail = 'Detail : Location[' + ISNULL(@in_vchLocation,'') + '] and Item Number ['+ @in_vchItemNumber + '] and Lot Number ['+@in_vchLotNumber+'] not found.'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchLocation,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
			RETURN;
		END
	
	DROP TABLE #tempInvExport
	
	BEGIN
		INSERT INTO [dbo].[t_host_wms_inventory_adjust]
				([inventory_adjust_id]
				,[host_record_id]
				,[location]
				,[item_number]
				,[lot_number]
				,[quantity]
				,[create_by]
				,[create_date])
			VALUES
				(NEWID()
				,@in_vchHostRecordID
				,@in_vchLocation
				,@in_vchItemNumber
				,@in_vchLotNumber
				,@in_fltQuantity
				,@in_vchUserID
				,GETDATE())
		SET @out_vchErrorCode = '0'
		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,'SAVE_SUCCESS','1033','@param1','@param2','@param3','@param4','@param5')
	END
END
GO
