CREATE PROCEDURE [dbo].[usp_host_wms_insert_inventory_compare]
(
	 @in_vchHostRecordID			VARCHAR(40),
     @in_vchPlant					NVARCHAR(50),
     @in_vchItemNumber				NVARCHAR(50),
     @in_vchDescription				NVARCHAR(200),
     @in_vchLocation				NVARCHAR(50),
     @in_vchLotNumber				NVARCHAR(50),
     @in_vchExpiryDate				DATETIME= NULL,
     @in_vchUnrestrictedQuantity	INT= NULL,
     @in_vchQuarantineInspect		INT= NULL,
     @in_vchBlockedStock			INT= NULL,
     @in_vchUom						NVARCHAR(10),
     @in_vchAvailDate				DATETIME = NULL,
     @in_vchPom						NVARCHAR(50),
     @in_vchStorageBin				NVARCHAR(50),
     @in_vchPgc						INT= NULL,	
     @in_vchPurchGroupName			NVARCHAR(100),
     @in_vchTc						NVARCHAR(50),
     @in_vchTempConditionsDesc		NVARCHAR(200),
     @in_vchEan						NVARCHAR(50),
     @in_vchCtg						NVARCHAR(50),
     @in_vchProductHierarchy		NVARCHAR(200),
     @in_vchDv						NVARCHAR(50),
	 @in_vchCreateDate				DATETIME= NULL,
	 @in_vchCreateBy				NVARCHAR(25),
	 @out_vchErrorCode				NVARCHAR(25)  OUTPUT,
	 @out_vchErrorMsg				NVARCHAR(500) OUTPUT,
	 @out_vchErrorType				NVARCHAR(50) OUTPUT
)
AS
BEGIN
	DECLARE @v_vchItemMasterID		VARCHAR(50),
			@v_vchApplicationID		VARCHAR(40) = '2A14C878-2292-44B0-9CE6-F791C7E9870A'
	SET @out_vchErrorType = 'FILE_ERROR'
	--Check Item Master
	SELECT @v_vchItemMasterID = item_master_id FROM t_wms_item WHERE item_number = @in_vchItemNumber AND is_active = 'YES'
	--IF (ISNULL(@v_vchItemMasterID,'') = '')
	--	BEGIN
	--		SET @out_vchErrorCode = 'ERROR-HIM-024'
	--		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
	--	END

	----Check Item UOM
	--IF NOT EXISTS(SELECT item_uom_id FROM t_wms_item_uom WHERE item_master_id = @in_vchItemNumber AND uom = @in_vchUom AND primary_uom = 'YES' AND is_active = 'YES')
	--	BEGIN
	--		SET @out_vchErrorCode = 'ERROR-HIM-025'
	--		SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchUom,'@param2','@param3','@param4','@param5')	
	--	END
	
	INSERT INTO [dbo].[t_host_wms_inventory_compare]
			   ([inventory_compare_id]
			   ,[host_record_id]
			   ,[plant]
			   ,[item_number]
			   ,[description]
			   ,[location]
			   ,[lot_number]
			   ,[expiry_date]
			   ,[unrestricted_quantity]
			   ,[quarantine_inspect]
			   ,[blocked_stock]
			   ,[uom]
			   ,[avail_date]
			   ,[pom]
			   ,[storage_bin]
			   ,[pgc]
			   ,[purch_group_name]
			   ,[tc]
			   ,[temp_conditions_desc]
			   ,[ean]
			   ,[ctg]
			   ,[product_hierarchy]
			   ,[dv]
			   ,[create_date]
			   ,[create_by])
		 VALUES
			   (NEWID()
			   ,@in_vchHostRecordID
			   ,@in_vchPlant
			   ,@in_vchItemNumber
			   ,@in_vchDescription
			   ,@in_vchLocation
			   ,@in_vchLotNumber
			   ,@in_vchExpiryDate
			   ,@in_vchUnrestrictedQuantity
			   ,@in_vchQuarantineInspect
			   ,@in_vchBlockedStock
			   ,@in_vchUom
			   ,@in_vchAvailDate
			   ,@in_vchPom
			   ,@in_vchStorageBin
			   ,@in_vchPgc
			   ,@in_vchPurchGroupName
			   ,@in_vchTc
			   ,@in_vchTempConditionsDesc
			   ,@in_vchEan
			   ,@in_vchCtg
			   ,@in_vchProductHierarchy
			   ,@in_vchDv
			  ,@in_vchCreateDate
			  ,@in_vchCreateBy)

	SET @out_vchErrorCode = '0'
	SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,'SAVE_SUCCESS','1033','@param1','@param2','@param3','@param4','@param5')	
END
