	@in_dtCloseDate					DATETIME		= NULL, -- ใช้สำหรับ Partial Receipt Close Date
	@out_vchErrorCode				NVARCHAR(200) = NULL OUTPUT,
	@out_vchErrorMessage			NVARCHAR(500) = NULL OUTPUT

AS
BEGIN
	DECLARE 
    --Error handling variables
    @c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
    @v_intSqlErrorNumber    INTEGER,
    @v_intSqlErrorLine		INTEGER,
    @v_intSqlErrorState		INTEGER,
    @v_intSqlErrorSeverity	INTEGER,
    @v_vchSqlErrorMessage	NVARCHAR(2048),
    @v_vchSqlErrorProcedure NVARCHAR(200),  
    @v_vchProcessData1		NVARCHAR(1000),
    @v_vchProcessData2		NVARCHAR(1000),
    @v_vchProcessData3		NVARCHAR(1000),
    @v_vchProcessData4		NVARCHAR(1000),
	--  Log Handling Variables
	@v_intLocale			INTEGER = 1033, 
    @v_intLogLevel          INTEGER = 0,  -- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
    @v_vchLogAction			NVARCHAR(25) = 'PRINT', --- PRINT, LOG,
	@v_vchLogType			NVARCHAR(50),
	@v_vchErrorCode			NVARCHAR(200),
	@v_vchMessage           NVARCHAR(250),
	-- Local Variables
    @v_vchProcessingCode    NVARCHAR(40) = 'ADD', -- Required
    @v_vchProcessingStatus  NVARCHAR(40) = 'OPEN' , -- Required
	@v_intNextValue			INTEGER,
	@v_fltBeforeQuantity	FLOAT,
	@out_vchDBName			NVARCHAR(100)
    
    SET NOCOUNT ON;

    -- Set Constants
    SET @c_vchObjName = 'usp_HostInterfaceManager'; 
	SET @v_vchLogType = 'EXPORT ERROR';
	IF (@in_fltAfterQuantity IS NULL)
		SET @in_fltAfterQuantity = 0;

    
    BEGIN TRY
   		------------------------------------------------------------
		--  Check Required Field and Set Defaults
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Initial Required Fields'
		-- Future, Add a Log action for inserting into the Process Log	
		
		IF @in_vchWhID IS NULL
			BEGIN
				SET @in_vchWhID = @in_vchToWhID
			END

		------------------------------------------------------------
		--  Warehouse cannot be NULL.  Set to a Default WH ID
		------------------------------------------------------------
	    IF @in_vchWhID IS NULL AND @in_vchToWhID IS NULL
			BEGIN
				SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Missing required Fields
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				SET @v_vchProcessData1 = @in_vchOrderNumber
				GOTO WRITE_PROCESS_LOG
			END
			
		------------------------------------------------------------
		--  User ID cannot be NULL.  Set to a Default to 'OGA'
		------------------------------------------------------------
		IF @in_vchUserID IS NULL
			BEGIN
				SET @in_vchUserID = 'SYSTEM'
			END
		
		------------------------------------------------------------
		--  Quantity cannot be NULL.  Set to a Zero (0)
		------------------------------------------------------------
		IF @in_fltQuantity IS NULL 
			SET @in_fltQuantity = 0
		
   		------------------------------------------------------------
		--  Insert into Transaction Export Log
		------------------------------------------------------------
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Into Transaction Log'
		-- Future, Add a Log action for inserting into the Process Log	
		
		----------------------------------------------------------
		--  Check for Required Fields for Transaction Log Export
		------------------------------------------------------------
		IF	@in_vchHostRecordID IS NULL 
			OR @in_vchApplicationID IS NULL 
			OR @v_vchProcessingCode IS NULL 
			OR @v_vchProcessingStatus IS NULL
			OR @in_vchTranType IS NULL
			OR @in_vchUserID IS NULL 
			OR @in_vchDevice IS NULL 
			OR @in_dtStartTranDate IS NULL
			OR (@in_vchWhID IS NULL AND @in_vchToWhID IS NULL)
		BEGIN
			------------------------------------------------------------
			--  Missing required Fields so Log into the Process Log
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Data in Transaction Export'
			-- Future, Add a Log action for inserting into the Process Log
			
			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
				BEGIN
					select 'Field List1 :' + 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '') +']'
										 + 'App ID: ['+ISNULL(@in_vchApplicationID, '') +']'
										 + 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +']'
										 + 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +']'
										 + 'Transaction Type: ['+ISNULL(@in_vchTranType, '')  +']'
										 + 'Device ID: ['+ISNULL(@in_vchDevice, '') +']'
									 
									 
					select 'Field List 2 :' +'Location: ['+ISNULL(@in_vchLocation, '')  +']'
										 + 'Warehouse ID: ['+ISNULL(@in_vchWhID, '')  +']'
										 + 'Item Number: ['+ISNULL(@in_vchItemNumber, '')  +']'
										 + 'Start Tran Date: ['+ISNULL(convert(varchar(12), @in_dtStartTranDate), '') +']'
										 + 'Quantity: ['+ISNULL(str(@in_fltQuantity, 12), '') +']'
										 + 'User ID: ['+ISNULL(@in_vchUserID, '') + ']' 
				END
			
			SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Missing required Fields
			SET @v_vchLogType =  'LOG MANAGER ERROR'
			SET @v_vchProcessData1 = 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
									+ 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '''')+ ']'
									+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
									+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
									+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
									+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
									+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
			SET @v_vchProcessData2 = 'Warehouse ID: ['+ISNULL(@in_vchWhID, '')+ ']'
									+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
									+ 'Tran Type: ['+ISNULL(@in_vchTranType, '')+ ']'
									+ 'Location: ['+ISNULL(@in_vchLocation, '')+ ']'
									+ 'Item Number: ['+ISNULL(@in_vchItemNumber, '')+ ']'
									+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltQuantity), '''')+ ']'
			SET @v_vchProcessData3 = 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '''') + ']'
			SET @v_vchProcessData4 = NULL
			SET @out_vchErrorCode = '003';
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + ']. Record ID:['+ isnull(@in_vchHostRecordID,'') + ']'
			SET @out_vchErrorMessage = @v_vchMessage;
			GOTO WRITE_PROCESS_LOG
		END
			
		------------------------------------------------------------
		--  Insert into t_host_wms_trans_export
		--  Champ Add 18-10-2017
		------------------------------------------------------------ 
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check for Inserting Record into Trans Confirmation'
		-- Future, Add a Log action for inserting into the Process Log
		
		IF @in_vchTranType IN ('BLIND_RECEIPT','BLIND_PICK') AND @in_vchSubTranType in ('CLOSE_RECEIPT','CONFIRM_TO_ERP')
		BEGIN
			----------------------------------------------------------
			--  Check for Required Fields for Receipt Confirmation
			------------------------------------------------------------
			IF	@in_vchHostRecordID IS NULL 
				OR @in_vchApplicationID IS NULL 
				OR @v_vchProcessingCode IS NULL 
				OR @v_vchProcessingStatus IS NULL
				OR @in_vchTranType IS NULL 
				OR @in_vchToWhID IS NULL
				OR @in_vchToOwner IS NULL 
				OR @in_vchOrderNumber IS NULL	
				OR @in_dtStartTranDate IS NULL
				OR @in_vchUserID IS NULL 
				OR @in_vchDevice IS NULL
			BEGIN
				------------------------------------------------------------
				--  Missing required Fields so Log into the Process Log
				------------------------------------------------------------
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Data in Transaction Trans Export'
				-- Future, Add a Log action for inserting into the Process Log
				
				IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
					BEGIN
						select 'Field List1 :' + 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
											+ 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '''')+ ']'
											+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
											+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
											+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
											+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
											+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
										 
						select 'Field List 2 :'+ 'To Warehouse ID: ['+ISNULL(@in_vchToWhID, '')+ ']'
											+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
											+ 'Order Number: ['+ISNULL(@in_vchOrderNumber, '')+ ']'
											+ 'Order Status: ['+ISNULL(@in_vchAfterStatus, '')+ ']'
											+ 'Item Number: ['+ISNULL(@in_vchTranType, '')+ ']'
											+ 'Line Number: ['+ISNULL(@in_vchLineNumber, '')+ ']'
											+ 'UOM: ['+ISNULL(@in_vchAfterUOM, '')+ ']'
											+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltAfterQuantity), '')+ ']'
										
						select 'Field List 3 :' + 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '') + ']'
					END
				
				SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Required Fields Missing
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				
				SET @v_vchProcessData1 = 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
										+ 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '''')+ ']'
										+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
										+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
										+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
										+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
				SET @v_vchProcessData2 = 'To Warehouse ID: ['+ISNULL(@in_vchToWhID, '')+ ']'
										+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
										+ 'Order Number: ['+ISNULL(@in_vchOrderNumber, '')+ ']'
										+ 'Order Status: ['+ISNULL(@in_vchAfterStatus, '')+ ']'
										+ 'Item Number: ['+ISNULL(@in_vchItemNumber, '')+ ']'
										+ 'Line Number: ['+ISNULL(@in_vchLineNumber, '')+ ']'
										+ 'UOM: ['+ISNULL(@in_vchAfterUOM, '')+ ']'
										+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltAfterQuantity), '')+ ']'
				SET @v_vchProcessData3 = 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '') + ']'
				SET @v_vchProcessData4 = NULL
				SET @out_vchErrorCode = '003';
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + ']. Record ID:['+@in_vchHostRecordID+ ']'
				SET @out_vchErrorMessage = @v_vchMessage;
				GOTO WRITE_PROCESS_LOG
			END


			--if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Record into t_host_wms_receipt_export completed'
			-- Future, Add a Log action for inserting into the Process Log

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inserting Record  t_host_wms_trans_export '
				
			INSERT INTO [dbo].[t_host_wms_trans_export]
                        ([record_id]
                        ,[host_record_id]
                        ,[processing_code]
