                        ,[user_def7]
                        ,[user_def8]
                        ,[user_def9]
                        ,[user_def10]
                        ,[device]
                        ,[create_date]
                        ,[create_by]
						,[posting_date])
                VALUES
                        (NEWID()						
                        ,@in_vchHostRecordID			
                        ,@v_vchProcessingCode			
                        ,@v_vchProcessingStatus			
                        ,@in_vchApplicationID			
                        ,@in_vchAppName					
                        ,@in_vchTranType				
                        ,@in_vchSubTranType				
                        ,@in_vchDescription				
                        ,@in_dtStartTranDate			
                        ,@in_dtEndTranDate				
                        ,@in_vchWhID					
                        ,@in_vchToWhID					
                        ,@in_vchLocation				
                        ,@in_vchToLocation				
                        ,@in_vchOwner					
                        ,@in_vchToOwner					
                        ,@in_vchItemNumber				
                        ,@in_fltQuantity				
                        ,@in_vchUOM						
                        ,@in_fltAfterQuantity			
                        ,@in_vchUOM						
                        ,@in_vchLotNumber				
                        ,@in_vchAfterLotNumber			
                        ,@in_dtExpiryDate				
                        ,@in_dtAfterExpiryDate			
                        ,@in_vchSerialNumber			
                        ,@in_vchAttribute1				
                        ,@in_vchAfterAttribute1			
                        ,@in_vchAttribute2				
                        ,@in_vchAfterAttribute2			
                        ,@in_vchAttribute3				
                        ,@in_vchAfterAttribute3			
                        ,@in_vchAttribute4				
                        ,@in_vchAfterAttribute4			
                        ,@in_vchAttribute5				
                        ,@in_vchAfterAttribute5			
                        ,@in_vchUserID					
                        ,@in_vchReferenceNumber			
                        ,@in_vchControlNumber			
                        ,@in_vchLPN						
                        ,@in_vchAfterLPN				
                        ,@in_vchStatus					
                        ,@in_vchAfterStatus				
                        ,@in_vchZone					
                        ,@in_vchOrderNumber				
                        ,@in_vchLineNumber				
                        ,@in_vchControlValue1			
                        ,@in_vchControlValue2			
                        ,@in_vchReasonCode				
                        ,@in_vchHUDF1					
                        ,@in_vchHUDF2					
                        ,@in_vchDUDF3					
                        ,@in_vchDUDF4					
                        ,@in_vchDUDF5					
                        ,@in_vchDUDF6					
                        ,@in_fltDUDF7					
                        ,@in_fltDUDF8					
                        ,@in_dtpDUDF9					
                        ,@in_dtpDUDF10					
                        ,@in_vchDevice					
                        ,GETDATE()						
                        ,@in_vchUserID
						,@in_dtPostingDate)					
				
		    IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Insert Record into t_host_wms_trans_export completed'
			
			SET @out_vchErrorCode = '0';        
			GOTO EXIT_LABEL
		END

		------------------------------------------------------------
		--  Insert into t_host_wms_receipt_export
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check for Inserting Record into Receipt Confirmation'
		-- Future, Add a Log action for inserting into the Process Log
		
		IF (@in_vchTranType = 'IO_RECEIPT')
		BEGIN
			----------------------------------------------------------
			--  Check for Required Fields for Receipt Confirmation
			------------------------------------------------------------
			IF	@in_vchHostRecordID IS NULL 
				OR @in_vchApplicationID IS NULL 
				OR @v_vchProcessingCode IS NULL 
				OR @v_vchProcessingStatus IS NULL
				OR @in_vchTranType IS NULL 
				OR @in_vchToWhID IS NULL
				OR @in_vchToOwner IS NULL 
				OR @in_vchOrderNumber IS NULL
				OR @in_vchAfterStatus IS NULL 
				OR @in_vchItemNumber IS NULL
				OR @in_vchLineNumber IS NULL 
				OR @in_vchAfterUOM IS NULL
				OR @in_fltAfterQuantity IS NULL 
				OR @in_dtStartTranDate IS NULL
				OR @in_vchUserID IS NULL 
				OR @in_vchDevice IS NULL
			BEGIN
				------------------------------------------------------------
				--  Missing required Fields so Log into the Process Log
				------------------------------------------------------------
				if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Data in Transaction Export'
				-- Future, Add a Log action for inserting into the Process Log
				
				if @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
					BEGIN
						select 'Field List1 :' + 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
											+ 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '''')+ ']'
											+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
											+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
											+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
											+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
											+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
										 
						select 'Field List 2 :'+ 'To Warehouse ID: ['+ISNULL(@in_vchToWhID, '')+ ']'
											+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
											+ 'Order Number: ['+ISNULL(@in_vchOrderNumber, '')+ ']'
											+ 'Order Status: ['+ISNULL(@in_vchAfterStatus, '')+ ']'
											+ 'Item Number: ['+ISNULL(@in_vchTranType, '')+ ']'
											+ 'Line Number: ['+ISNULL(@in_vchLineNumber, '')+ ']'
											+ 'UOM: ['+ISNULL(@in_vchAfterUOM, '')+ ']'
											+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltAfterQuantity), '')+ ']'
										
						select 'Field List 3 :' + 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '') + ']'
					END
				
				SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Required Fields Missing
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				
				SET @v_vchProcessData1 = 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
										+ 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '''')+ ']'
										+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
										+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
										+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
										+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
				SET @v_vchProcessData2 = 'To Warehouse ID: ['+ISNULL(@in_vchToWhID, '')+ ']'
										+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
										+ 'Order Number: ['+ISNULL(@in_vchOrderNumber, '')+ ']'
										+ 'Order Status: ['+ISNULL(@in_vchAfterStatus, '')+ ']'
										+ 'Item Number: ['+ISNULL(@in_vchItemNumber, '')+ ']'
										+ 'Line Number: ['+ISNULL(@in_vchLineNumber, '')+ ']'
										+ 'UOM: ['+ISNULL(@in_vchAfterUOM, '')+ ']'
										+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltAfterQuantity), '')+ ']'
				SET @v_vchProcessData3 = 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '') + ']'
				SET @v_vchProcessData4 = NULL
				SET @out_vchErrorCode = '003';
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + ']. Record ID:['+@in_vchHostRecordID+ ']'
				SET @out_vchErrorMessage = @v_vchMessage;
				GOTO WRITE_PROCESS_LOG
			END

			--if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Record into t_host_wms_receipt_export completed'
			-- Future, Add a Log action for inserting into the Process Log

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inserting Record  t_host_wms_receipt_conf_header_export '
			
			IF NOT EXISTS(SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE receipt_id = @in_vchHostRecordID)
