		-- Future, Add a Log action for inserting into the Process Log

		-- Detail
		IF (@in_vchTranType IN ('OO_SHIP','OO_SHIP_CONSIGNMENT','OO_PARTIAL_SHIP') AND @in_vchSubTranType IN ('CONFIRM_TO_ERP','CLOSE_ORDER_ERP')) 
			OR (@in_vchTranType = 'BLIND_PICK' AND @in_vchSubTranType = 'CLOSE_ORDER_ERP')
		BEGIN
			----------------------------------------------------------
			--  Check for Required Fields for Ship Confirmation Detail
			------------------------------------------------------------
			IF	@in_vchHostRecordID IS NULL 
				OR @in_vchWhID IS NULL
				OR @in_vchOwner IS NULL
				OR @in_vchOrderNumber IS NULL
				OR @in_vchItemNumber IS NULL
				OR @in_vchLineNumber IS NULL 
				OR @in_vchUOM IS NULL
				OR @in_fltAfterQuantity IS NULL 
				OR @in_fltOrderQuantity IS NULL
				OR @in_fltShortQuantity IS NULL
			BEGIN
				------------------------------------------------------------
				--  Missing required Fields so Log into the Process Log
				------------------------------------------------------------
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Data in Transaction Export'
				-- Future, Add a Log action for inserting into the Process Log
				
				IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
					BEGIN
						SELECT 'Field List1 :' + 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')
											 + '] App ID: ['+ISNULL(@in_vchApplicationID, '')
											 + '] Processing Code: ['+ISNULL(@v_vchProcessingCode, '')
											 + '] Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')
											 + '] Transaction Type: ['+ISNULL(@in_vchTranType, '') 
											 + '] Sub Transaction Type: ['+ISNULL(@in_vchSubTranType, '') 
											 + '] Device ID: ['+ISNULL(@in_vchDevice, '') 
											 + ']'
										 
						SELECT 'Field List 2 :' +'] Warehouse ID: ['+ISNULL(@in_vchWhID, '') 
											 + '] Owner ID: ['+ISNULL(@in_vchToOwner, '') 
											 + '] Customer ID: ['+ISNULL(@in_vchReferenceNumber, '') 
											 + '] Order Number: ['+ISNULL(@in_vchToOwner, '') 
											 + '] Order Status: ['+ISNULL(@in_vchStatus, '') 
											 + ']' 
										 
						SELECT 'Field List 3 :' + 'UOM: ['+ISNULL(@in_vchAfterUOM, '')
											 +'] Start Tran Date: ['+ISNULL(convert(varchar(12), @in_dtStartTranDate), '')
											 + '] User ID: ['+ISNULL(@in_vchUserID, '') 
											 + ']'
	
					END
				
				SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Required Fields Missing
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				SET @v_vchProcessData1 = 'App ID: ['+ISNULL(@in_vchApplicationID, '''') + ']'
										+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '''')+ ']'
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '''')+ ']'
										+ 'Transaction Type: ['+ISNULL(@in_vchTranType, '''')+ ']'
										+ 'User ID: ['+ISNULL(@in_vchUserID, '''')+ ']'
										+ 'Device ID: ['+ISNULL(@in_vchDevice, '''')+ ']'
										
				SET @v_vchProcessData2 = 'Warehouse ID: ['+ISNULL(@in_vchWhID, '')+ ']'
										+ 'To Owner ID: ['+ISNULL(@in_vchToOwner, '')+ ']'
										+ 'Customer Number: ['+ISNULL(@in_vchReferenceNumber, '')+ ']'
										+ 'Tran Type: ['+ISNULL(@in_vchTranType, '')+ ']'
										+ 'Sub Tran Type: ['+ISNULL(@in_vchSubTranType, '')+ ']'
										+ 'Order Number: ['+ISNULL(@in_vchLocation, '')+ ']'
										+ 'Order Status: ['+ISNULL(@in_vchLocation, '')+ ']'
										+ 'Item Number: ['+ISNULL(@in_vchItemNumber, '')+ ']'
										+ 'Line Number: ['+ISNULL(@in_vchLineNumber, '')+ ']'
										+ 'Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltQuantity), '''')+ ']'
										+ 'Order Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltOrderQuantity), '''')+ ']'
										+ 'Short Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltShortQuantity), '''')+ ']'
				SET @v_vchProcessData3 = 'Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '''') + ']'
										+ 'UOM: ['+ISNULL(@in_vchTranType, '')+ ']'
				SET @v_vchProcessData4 = NULL
				SET @out_vchErrorCode = '003';
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + ']. Record ID:['+@in_vchHostRecordID+ ']'
				SET @out_vchErrorMessage = @v_vchMessage;
				GOTO WRITE_PROCESS_LOG
			END
			----------------------------------------------------------
			--  Perform Insert into t_host_wms_ship_conf_detail_export
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inserting Record t_host_wms_ship_conf_detail_export'
			-- Future, Add a Log action for inserting into the Process Log

			INSERT INTO [dbo].[t_host_wms_ship_conf_detail_export]
				   ([host_shipment_id]
				   ,[processing_code]
				   ,[processing_status]
				   ,[wh_id]
				   ,[owner_id]
				   ,[order_number]
				   ,[line_number]
				   ,[item_number]
				   ,[lot_number]
				   ,[expiry_date]
				   ,[serial_number]
				   ,[uom]
				   ,[order_quantity]
				   ,[quantity]
				   ,[short_quantity]
				   ,[status]
				   ,[reason_code]
				   ,[lpn]
				   ,[location]
				   ,[user_id]
				   ,[price]
				   ,[user_def1]
				   ,[user_def2]
				   ,[user_def3]
				   ,[user_def4]
				   ,[user_def5]
				   ,[user_def6]
				   ,[user_def7]
				   ,[user_def8]
				   ,[user_def9]
				   ,[user_def10]
				   ,[attribute1]
				   ,[attribute2]
				   ,[attribute3]
				   ,[attribute4]
				   ,[attribute5]
				   ,[create_date]
				   ,[create_by]
				   ,[interface_plan_uom]
				   ,[interface_quantity]
				   )
			 VALUES
				   (@in_vchHostRecordID
				   ,@v_vchProcessingCode	
				   ,@v_vchProcessingStatus	
				   ,@in_vchWhID	
				   ,@in_vchOwner	
				   ,@in_vchOrderNumber
				   ,@in_vchLineNumber
				   ,@in_vchItemNumber
				   ,@in_vchLotNumber
				   ,@in_dtExpiryDate
				   ,@in_vchSerialNumber
				   ,@in_vchUOM
				   ,@in_fltOrderQuantity
				   ,@in_fltQuantity
				   ,@in_fltShortQuantity
				   ,@in_vchStatus
				   ,@in_vchReasonCode
				   ,@in_vchLPN
				   ,@in_vchControlValue1 --EPR Location
				   ,@in_vchUserID
				   ,@in_fltPrice
				   ,@in_vchDUDF1		
				   ,@in_vchDUDF2
				   ,@in_vchDUDF3
				   ,@in_vchDUDF4		-- location สุดท้ายก่อน ship
				   ,@in_vchDUDF5
				   ,@in_vchDUDF6
				   ,@in_fltDUDF7
				   ,@in_fltDUDF8
				   ,@in_dtpDUDF9
				   ,@in_dtpDUDF10
				   ,@in_vchAttribute1
				   ,@in_vchAttribute2
				   ,@in_vchAttribute3
				   ,@in_vchAttribute4
				   ,@in_vchAttribute5
				   ,GETDATE()
				   ,@in_vchUserID
				   ,@in_vchDUDF6
				   ,@in_fltDUDF7 
				   )
		END
		
		SET @out_vchErrorCode = '0';
		GOTO EXIT_LABEL;
		
		-----------------------------------------------------------------------------------
		--  After setting the message variables now write to the Process Log
		-----------------------------------------------------------------------------------
		WRITE_PROCESS_LOG:
		
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
	
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT	'Field List 1 :' +'App ID: ['+ISNULL(@in_vchApplicationID, '')+']'
						+'Log Type: ['+ISNULL(@v_vchMessage, '')+']'
						+'Warehouse: ['+ISNULL(@in_vchWHID, '') +']'
						+'Device: ['+ISNULL(@in_vchDevice, '')+']'
						+'Object Name: ['+ISNULL(@c_vchObjName, '')+']'
						+'Data1: ['+ISNULL(@v_vchProcessData1, '')+']'
				SELECT	'Field List 2 :' 		+'Data2: ['+ISNULL(@v_vchProcessData2, '')+']'
						+'Data3: ['+ISNULL(@v_vchProcessData3, '')+']'
						+'Data4: ['+ISNULL(@v_vchProcessData4, '')+']'
						+'Message: ['+ISNULL(@v_vchMessage, '')+']'
						+'User ID: ['+ISNULL(@in_vchUserID, '') + ']' 
			END
		
		IF @v_intLogLevel >= 5 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field Length: App ID: ['+str(len(@in_vchApplicationID),10) +']'
			select	'Field Length: Log Type: ['+STR(len(@v_vchLogType), 10) +']'
			select	'Field Length: Warehouse: ['+ str( len(@in_vchWhID),10) +']'
			select	'Field Length: Device: ['+ str(len(@in_vchDevice) ,10) +']'
			select	'Field Length: Object Name: ['+ str(len(@c_vchObjName) ,10) +']'
			select	'Field Length: Data1: ['+ str(len (@v_vchProcessData1) ,10) +']'
			select	'Field Length: Data2: ['+ str(len (@v_vchProcessData2) ,10) +']'
			select	'Field Length: Data3: ['+ str(len (@v_vchProcessData3) ,10) +']'
			select	'Field Length: Data4: ['+ str(len (@v_vchProcessData4) ,10) +']'
			select	'Field Length: Message: ['+ str(len(@v_vchMessage) ,10) +']'
			select	'Field Length: User ID: ['+ str( len(@in_vchUserID),10) +']'
		END
		
		INSERT INTO [dbo].[t_com_process_log]
			([app_id],[log_type],[warehouse]
			,[device],[process]
			,[process_datetime],[data_1]
			,[data_2],[data_3],[data_4]
			,[message],[create_date],[create_by])
		VALUES
			(left(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40), left(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
			, left(ISNULL(@in_vchWHID, 'NO WH DEFINED'), 25), left(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
			, left(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
			, getdate(),ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA 1')
			, left(@v_vchProcessData2, 1000),left(@v_vchProcessData3, 1000),left(@v_vchProcessData4, 1000)
			, left(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100), getdate(), ISNULL(left(@in_vchUserID, 10), 'OGA'))			
			
		--Print 'Done with Insert Error into Process Log'
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Finished with Writing to the Process Log Now goto Exit Label'
		-- Future, Add a Log action for inserting into the Process Log	

		GOTO EXIT_LABEL;
		
    END TRY
        
-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
    BEGIN CATCH    
	-- Insert a message into the Process log about the Error
	-- Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
		
		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMessage = @v_vchSqlErrorMessage;
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		if @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			select 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			select 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			select 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			select 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			select 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			select 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END	
		
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id],[log_type],[warehouse]
			   ,[device],[process]
			   ,[process_datetime],[data_1]
			   ,[data_2],[data_3],[data_4]
			   ,[message],[create_date],[create_by])
		 VALUES
		 		(left(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40), left(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, left(ISNULL(@in_vchWHID, 'NO WH DEFINED'), 25), left(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
				, left(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, getdate(),ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA')
				, left(@v_vchProcessData2, 1000),left(@v_vchProcessData3, 1000),left(@v_vchProcessData4, 1000)
				,left(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, getdate(), ISNULL(@in_vchUserID,'OGA'))

		--SET @out_vchErrorCode = 'CONTACT_ADMIN';
		--SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

	END CATCH
	
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Exiting Sproc'
		-- Future, Add a Log action for inserting into the Process Log		
END
GO
/****** Object:  StoredProcedure [dbo].[usp_HostInterfaceSAPManager]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================  
-- Author:  <Author,,Name>  
-- Create date: <Create Date,,>  
-- Description: <Description,,>  
-- =============================================  
CREATE PROCEDURE [dbo].[usp_HostInterfaceSAPManager]  
	@in_vchApplicationID   VARCHAR(40),  
	@in_vchWhID      NVARCHAR(25),  
	@in_vchDevice     NVARCHAR(50),  
	@in_vchUserID     NVARCHAR(10),  
	  
	--  Tran Log Variables  
	@in_vchTranType     NVARCHAR(20)= NULL,  
	@in_vchSubTranType    NVARCHAR(20)= NULL,  
	@in_vchAppName     NVARCHAR(100) = NULL,  
	@in_vchDescription    NVARCHAR(100) = NULL,  
	@in_dtStartTranDate    DATETIME = NULL,  
	@in_dtEndTranDate    DATETIME = NULL,  
	@in_vchToWhID      NVARCHAR(25) = NULL,  
	@in_vchLocation     NVARCHAR(50) = NULL,  
	@in_vchToLocation    NVARCHAR(50) = NULL,  
	@in_vchOwner     NVARCHAR(50) = NULL,  
	@in_vchToOwner     NVARCHAR(50) = NULL,  
	@in_vchItemNumber    NVARCHAR(50) = NULL,  
	@in_fltQuantity     FLOAT = NULL,  
	@in_vchUOM      NVARCHAR(10) = NULL,
	@in_vchBaseUOM	NVARCHAR(10) = NULL,  
	@in_fltAfterQuantity   FLOAT = NULL,  
	@in_vchAfterUOM     NVARCHAR(10) = NULL,  
	@in_vchLotNumber    NVARCHAR(50) = NULL,  
	@in_vchAfterLotNumber   NVARCHAR(50) = NULL,  
	@in_dtExpiryDate    DATETIME = NULL,  
	@in_dtAfterExpiryDate   DATETIME = NULL,  
	@in_vchSerialNumber    NVARCHAR(50) = NULL,  
	@in_vchReferenceNumber   NVARCHAR(50) = NULL,  
	@in_vchControlNumber   NVARCHAR(50) = NULL,  
	@in_vchLPN      NVARCHAR(25) = NULL,  
	@in_vchAfterLPN     NVARCHAR(25) = NULL,  
	@in_vchStatus     NVARCHAR(15) = NULL,  
	@in_vchAfterStatus    NVARCHAR(15) = NULL,  
	@in_vchZone      NVARCHAR(50) = NULL,  
	@in_vchOrderNumber    NVARCHAR(40) = NULL,  
	@in_vchLineNumber    NVARCHAR(10) = NULL,  
	@in_vchControlValue1   NVARCHAR(100) = NULL,  
	@in_vchControlValue2   NVARCHAR(100) = NULL,  
	@in_vchReasonCode    NVARCHAR(20) = NULL,  
	@in_vchData1     NVARCHAR(1000) = NULL, -- movement type  
	@in_vchUDF1      NVARCHAR(100) = NULL, -- order type  
	@in_vchUDF2      NVARCHAR(100) = NULL,   
	@in_vchUDF3      NVARCHAR(100) = NULL,-- cost center  
	@in_vchUDF4      NVARCHAR(100) = NULL,  
	@in_vchUDFdatetime1		DATETIME = NULL,  
	@in_vchUDFdatetime2		DATETIME = NULL,  
	@in_vchUDFdatetime3		DATETIME = NULL,  
	@in_fltOrderQuantity	FLOAT = NULL,  
	@in_fltShortQuantity	FLOAT = NULL,  
	@in_vchHostRecordID		NVARCHAR(40)= NULL,
	@in_vchToMat			NVARCHAR(50) = NULL,
	@in_vchFromPlant		NVARCHAR(50) = NULL,
	@in_vchToPlant			NVARCHAR(50) = NULL,
	@in_dtPostingDate		DATE = NULL,
	@in_dtProductionDate	DATE = NULL,
	@in_vchCustomerCode		NVARCHAR(50) = NULL,
	@in_vchGLAccount		NVARCHAR(10) = NULL,
	
	@out_vchErrorCode		NVARCHAR(200) = NULL OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) = NULL OUTPUT
	
AS  
BEGIN  
	SET NOCOUNT ON; 
   
	  Declare 
			@v_vchDate   NVARCHAR(10),  
			@v_vchDeliverDate NVARCHAR(10),  
			@v_vchProcessingStatus  NVARCHAR(50),  
			@v_vchGMCode  NVARCHAR(10),   
			@v_vchMvtInd  NVARCHAR(1),  
			@v_vchOrderID  NVARCHAR(50),  
			@v_vchShippingPoint NVARCHAR(50),
			
			@v_vchDocYear	NVARCHAR(4),
			@v_vchDocItem	NVARCHAR(10),
			@v_vchMatDoc	NVARCHAR(10),
			@v_vchInboundOrderNumber	NVARCHAR(50),
			@v_vchMovementType	NVARCHAR(30),
			@v_vchReceiptNumber	NVARCHAR(50)
			
	SET @out_vchErrorCode = '0';
	
	If (LEFT(@in_vchOrderNumber,3) = '531')
		set @in_vchOrderNumber = RIGHT(@in_vchOrderNumber,(LEN(@in_vchOrderNumber)-3))
	
	If (@in_vchTranType = 'INV_ADJUST')
		set @in_fltQuantity = @in_fltAfterQuantity
	
	-- ตอนแรกรับเข้า QI แล้วทำการเปลี่ยน status เป็น UR แล้ว interface ขึ้น SAP
	-- order type 101 ,655 จะรับเข้าเป็น QI ต้องเปลี่ยน status => UR แต่จะต้องได้ Mat Doc แล้วเท่านั้น
	If (@in_vchTranType = 'INV_STATUS_CHANGE' and @in_vchStatus = 'QI')
		Begin
		
			select top 1 @v_vchInboundOrderNumber = inbound_order_number,
			@v_vchMovementType = order_type,@v_vchDocItem =line_number ,@v_vchReceiptNumber = receipt_number
			from v_wms_receipt_lpn_detail where lpn = @in_vchLPN
			If (@v_vchMovementType not in ('101','655','301','311','531','951'))
				Begin
					set @out_vchErrorCode = '0';
					return;
				End
				
			set @in_vchLineNumber = @v_vchDocItem;
			--select TOP 1 @v_vchMatDoc = material_document,@v_vchDocYear = doc_year from t_host_wms_interface_header 
			--where wms_order_no = @v_vchInboundOrderNumber and result_status = 'COMPLETED' and order_type in ('101','655')
			
			select top 1 @v_vchMatDoc = h.material_document,@v_vchDocYear = h.doc_year 
			from t_host_wms_interface_header h inner join t_host_wms_interface_detail d
			on h.interface_id = d.interface_id where wms_order_no = @v_vchInboundOrderNumber and ref_doc_no = @v_vchReceiptNumber
			
			If (@v_vchMatDoc is null and @v_vchMovementType not in ('655','301','311'))
				Begin
					set @out_vchErrorCode = '999';
					set @out_vchErrorMessage = 'ไม่พบ Material Document ไม่สามารถทำการเปลี่ยนสถานะได้';
					return;
				End
			Else If (@v_vchMovementType in ('655','301','311'))
				Begin
					set @in_vchOrderNumber = @v_vchInboundOrderNumber;
					set @v_vchDeliverDate  = '';
				End
			Else If (@in_vchData1 in ('321','350')) --  and @v_vchMovementType <> '655' 655 จะไม่มี MatDoc and Doc year
				Begin
					set @in_vchOrderNumber = @v_vchMatDoc;
					set @v_vchDeliverDate  = @v_vchDocYear;
				End
		End

	If Not Exists(select * from t_host_wms_interface_header where interface_id = @in_vchControlNumber)  
		Begin  
			insert into t_host_wms_interface_header
			(
			interface_id
			,parent_interface_id
			,move_type
			,wh_id
			,wms_order_no
			,order_type
			,material_document
			,doc_year
			,[user_id]
			)  
			values
			(
			@in_vchControlNumber
			,@in_vchUDF2
			,@in_vchData1
			,@in_vchWhID
			,@in_vchOrderNumber
			,@in_vchUDF1
			,null
			,null
			,@in_vchUserID
			)  
	   End  
    
	select @v_vchDate = convert(nvarchar,getdate(),104)
	
	If (@in_dtPostingDate is null)
		set @in_dtPostingDate = getdate();
	
	If (@in_vchUDFdatetime1 is not null)  
		Begin  
			SET @v_vchDeliverDate = convert(nvarchar,@in_vchUDFdatetime1,104) 
		End  
    
	insert into t_host_wms_interface_detail(  
		interface_id,   
		pstng_date,   
		doc_date,  
		 move_type,   
		ref_doc_no,  
		header_text,   
		gm_code,   
		material,   
		plant,   
		stge_loc,   
		entry_qnt,   
		entry_uom,   
		po_number,   
		po_item,   
		mvt_ind,   
		quantity,   
		base_uom,   
		costcenter,   
		orderid,
		batch,   
		move_mat,   
		move_plant,   
		move_stloc,   
		shipping_point,   
		delivery_date,   
		sale_order,  
		actual_gi_date,
		pd_dat,
		[text],
		customer,
		gl_account,
		goods_recipient)  
	values(  
		@in_vchControlNumber,    --interface_id  
		convert(nvarchar,@in_dtPostingDate,104),        --pstng_date  
		@v_vchDate,        --doc_date  
		@in_vchData1,       --move_type  
		@in_vchReferenceNumber,  --ref_doc_no  
		'',       --header_text  
		@v_vchGMCode,    --gm_code  
		@in_vchItemNumber,       --material  
		@in_vchFromPlant,   --plant  
		@in_vchWhID,    --stge_loc  
		@in_fltQuantity,         --entry_qnt  
		@in_vchUOM,     --entry_uom  
		@in_vchOrderNumber,      --po_number  
		@in_vchLineNumber,       --po_item  
		@v_vchMvtInd,    --mvt_ind  
		@in_fltQuantity,         --quantity  
		@in_vchBaseUOM,      --base_uom  
		@in_vchUDF3,    --costcenter  
		@v_vchOrderID,    --orderid
		@in_vchLotNumber, -- batch  
		@in_vchToMat,         --move_mat  
		@in_vchToPlant,      --move_plant  
		@in_vchToWhID,      --move_stloc  
		@v_vchShippingPoint,   --shipping_point  
		@v_vchDeliverDate,   --delivery_date  
		@in_vchOrderNumber,      --sale_order  
		@v_vchDate,		--actual_gi_date
		convert(nvarchar,@in_dtProductionDate,104),-- production date 
		@in_vchReasonCode, 
		@in_vchCustomerCode,
		@in_vchGLAccount,
		@in_vchUserID)            
   
END


GO
/****** Object:  StoredProcedure [dbo].[usp_import_change_location]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_import_change_location] 
(
	@in_vchApplicationID		NVARCHAR(40),							
	@in_vchDevice				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchSessingID			VARCHAR(40),		--SessionID 
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(4000) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
	 -- Error handling variables
    @c_vchObjName				NVARCHAR(30), -- The name that uniquely tags this object.
	@v_vchTransactionType		NVARCHAR(20),
	@v_vchSubTranType			NVARCHAR(20),
    @v_intSqlErrorNumber		INTEGER,
    @v_intSqlErrorState			INTEGER,
    @v_intSqlErrorSeverity		INTEGER,
    @v_vchSqlErrorMessage		NVARCHAR(1000),
    @v_vchSqlErrorProcedure		NVARCHAR(200),
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
	@v_dtProcessDateTime		DATETIME,
	--@v_dtStartTranDate			DATETIME,
	@v_dtEndTranDate			DATETIME,
	@v_vchLocal					NVARCHAR(5),
	@v_vchBeginTran				BIT = 0,
	@Round						INT,
	@v_vchInventoryType			NVARCHAR(20),
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchHostRecordID			VARCHAR(40),
	@v_vchTransID				VARCHAR(40),

	--Import Excel
	@v_vchRecordID				VARCHAR(40),
	@v_vchRowNo					INT,
	@v_vchItemNumber			NVARCHAR(50),
	@v_vchDescription			NVARCHAR(200),
	@v_fltQuantity				FLOAT,
	@v_vchSourceLocation		NVARCHAR(50),
	@v_vchDestinationLocation	NVARCHAR(50),
	@v_vchAXSourceLocation		NVARCHAR(50),
	@v_vchAXDestinationLocation	NVARCHAR(50),
	@v_vchPO					NVARCHAR(100),	--User_def1
	@v_vchSO					NVARCHAR(40),	--Order Number
	@v_vchRemark				NVARCHAR(2000),	--User_def2
	@v_dtTranDate				DATETIME,		--start_tran_datetime

	--Inventory Move
	@v_vchWhMasterID			VARCHAR(40),
	@v_vchWarehouse				NVARCHAR(25),
	@v_vchOwnerID				VARCHAR(40),
	@v_vchOwner					NVARCHAR(40),
	@v_vchStatusID				VARCHAR(40),
	@v_vchFromLocationID		VARCHAR(40),
	@v_vchToLocationID			VARCHAR(40),
	@v_vchLocType				NVARCHAR(20),

	@v_vchParentLPN				NVARCHAR(25) = NULL,
	@v_vchLPN					NVARCHAR(25) = NULL,
	@v_vchStatus				NVARCHAR(50),
	@v_vchLot					NVARCHAR(50) = NULL,
	@v_vchExpiryDate			NVARCHAR(50) = NULL,
	@v_vchSerialNumber			NVARCHAR(50) = NULL,
	@v_vchAttribute1			NVARCHAR(100) = NULL,
	@v_vchAttribute2			NVARCHAR(100) = NULL,
	@v_vchAttribute3			NVARCHAR(100) = NULL,
	@v_vchAttribute4			NVARCHAR(100) = NULL,
	@v_vchAttribute5			NVARCHAR(100) = NULL,
	@v_dtReceiveDate			DATE,
	@v_vchBaseItemUomID			VARCHAR(40),
	@v_vchBaseUomPrompt			NVARCHAR(25),
	@v_vchItemMasterID			VARCHAR(40),
	@v_vchWhItemMasterID		VARCHAR(40),
	@v_vchLotControl			NVARCHAR(10),
    @v_vchSNControl				NVARCHAR(10),
    @v_vchExpiryDateControl		NVARCHAR(10),
	@v_vchAttribute1Control		NVARCHAR(10),
	@v_vchAttribute2Control		NVARCHAR(10),
	@v_vchAttribute3Control		NVARCHAR(10),
	@v_vchAttribute4Control		NVARCHAR(10),
	@v_vchAttribute5Control		NVARCHAR(10),

	@v_vchInventoryID			VARCHAR(40),
	@v_vchAttributeGroupID		VARCHAR(40),
	@v_fltInvQuantity			FLOAT,
	@v_fltInvQtyAllocate		FLOAT,
	@v_fltAfterQty				FLOAT,		--For Write Log
	@v_fltAfterInvQuantity		FLOAT,
	@v_fltQtyMove				FLOAT,

	@v_fltWidth					FLOAT = 0,
	@v_fltLength				FLOAT = 0,
	@v_fltHeight				FLOAT = 0,
	@v_fltGrossWeight			FLOAT = 0,
	@v_intPercentTolerance		FLOAT = 0,
	@v_intPercenToleranceWeight FLOAT = 0,
	@v_fltVolumn				FLOAT = 0,	--item
	@v_fltTotalWeight			FLOAT = 0,	--item

	@v_vchReferenceNumber		NVARCHAR(50),
	@v_vchErrorMessage			NVARCHAR(4000) = ''

-----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    --BEGIN TRY
		-- Set Constants and Variables
		SET @c_vchObjName = 'usp_import_change_location';
		SET @v_vchInventoryType = 'INVENTORY';
		
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id, @v_vchWarehouse = wh_id FROM t_wms_wh WHERE is_active = 'YES'	
		SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwner = owner_code FROM t_wms_owner WHERE is_active = 'YES'
		SET @v_vchTransactionType	= 'INV_MOVE'
		
	-----------------------------------------------------------------------------------
	-- Processing
	-----------------------------------------------------------------------------------
	EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT
	SET @v_vchHostRecordID = @v_vchReferenceNumber
	--IF ((SELECT host_interface_manager FROM t_com_transaction WHERE (wh_id = @v_vchWarehouse) AND app_id = @in_vchApplicationID AND tran_type = @v_vchTransactionType AND sub_tran_type = @v_vchSubTranType)= 'YES')
	--	BEGIN
	--		--EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT
	--	END
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;

	IMPORT_EXCEL:
		SET @v_vchRecordID		 = NULL
		SET @v_vchRowNo			 = 0
		SET @v_vchItemNumber	 = NULL
		SET @v_vchDescription	 = NULL
		SET @v_fltQuantity		 = NULL
		SET @v_vchSourceLocation = NULL
		SET @v_vchDestinationLocation	= NULL
		SET @v_vchAXSourceLocation = NULL
		SET @v_vchAXDestinationLocation	= NULL
		SET @v_vchPO			 = NULL
		SET @v_vchSO			 = NULL
		SET @v_vchRemark		 = NULL

		SELECT TOP 1 @v_vchRecordID		= [record_id]
			,@v_vchRowNo				= [row_no]
			,@v_vchItemNumber			= [item_number]
			,@v_vchDescription			= [description]
			,@v_fltQuantity				= [quantity]
			,@v_vchSourceLocation		= [source_location]
			,@v_vchDestinationLocation	= [destination_location]
			,@v_vchPO					= [po]		--Udf1
			,@v_vchSO					= [so]		--OrderNumber
			,@v_vchRemark				= [remark]	--Udf2
			,@v_dtTranDate				= [tran_date]
		FROM [dbo].[t_wms_import_change_location]
		WHERE session_id = @in_vchSessingID
		AND process_status = 'PENDING'
		ORDER BY row_no desc

		IF ISNULL(@v_vchRecordID,'') <> ''
			BEGIN
				SET @v_fltQuantity = ROUND(@v_fltQuantity,@Round)

				BEGIN-- Check master data
					-- Check from location
					SET @v_vchFromLocationID = NULL
					SET @v_vchAXSourceLocation = NULL
					SET @v_vchLocType = NULL
					SELECT @v_vchFromLocationID = loc.location_id 
						,@v_vchSourceLocation = loc.location
						,@v_vchAXSourceLocation = locMap.ax_location
						,@v_vchLocType = loc.loc_type
					FROM t_wms_location loc
					LEFT JOIN t_wms_location_mapping locMap ON loc.location = locMap.wms_location
					WHERE loc.location = @v_vchSourceLocation 
					AND loc.wh_master_id = @v_vchWhMasterID 
					AND loc.is_active = 'YES'
					IF(ISNULL(@v_vchFromLocationID,'') = '')
						BEGIN
							SET @out_ErrorCode = '904';
							SELECT @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',@v_vchLocal,@v_vchSourceLocation,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC
						END

					-- check to location
					SET @v_vchToLocationID = NULL
					SET @v_vchAXDestinationLocation = NULL
					SELECT @v_vchToLocationID = loc.location_id 
						,@v_vchDestinationLocation = loc.location
						,@v_vchAXDestinationLocation = locMap.ax_location
					FROM t_wms_location loc
					LEFT JOIN t_wms_location_mapping locMap ON loc.location = locMap.wms_location
					WHERE loc.location = @v_vchDestinationLocation 
					AND loc.wh_master_id = @v_vchWhMasterID 
					AND loc.is_active = 'YES'
					IF(ISNULL(@v_vchToLocationID,'') = '')
						BEGIN
							SET @out_ErrorCode = '904';
							SELECT @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',@v_vchLocal,@v_vchDestinationLocation,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC
						END

					--Master Kool ถ้า AX location ต้นทางกับปลายทางตรงกันไม่ต้อง interface 
					IF ISNULL(@v_vchAXSourceLocation,'') = ISNULL(@v_vchAXDestinationLocation,'') OR @v_vchLocType = 'UNPICK'
						BEGIN
							SET @v_vchSubTranType = 'MOVE_ON_PC_NO_ERP'
						END
					ELSE
						BEGIN
							SET @v_vchSubTranType = 'MOVE_ON_PC'
							
						END
							
					-- check item number and item crossref and get owner
					SET @v_vchItemMasterID = NULL
					SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
						,@v_vchItemNumber			= item.item_number
						,@v_vchLotControl			= item.lot_control
						,@v_vchSNControl			= item.sn_control
						,@v_vchExpiryDateControl	= item.expiry_date_control
						,@v_vchAttribute1Control	= item.attribute1_control
						,@v_vchAttribute2Control	= item.attribute2_control
						,@v_vchAttribute3Control	= item.attribute3_control
						,@v_vchAttribute4Control	= item.attribute4_control
						,@v_vchAttribute5Control	= item.attribute5_control
					FROM t_wms_item item
					LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
					WHERE (item.item_number = @v_vchItemNumber OR item.dg_code = @v_vchItemNumber OR cref.alternate_item_number = @v_vchItemNumber) 
					AND item.owner_id = @v_vchOwnerID
					IF (ISNULL(@v_vchItemMasterID,'') = '')
						BEGIN
							SET @out_ErrorCode = '902';
							SELECT @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					-- check warehouse item master id
					SET @v_vchWhItemMasterID = NULL
					SELECT @v_vchWhItemMasterID = wh_item_master_id 
					FROM t_wms_wh_item 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND item_master_id = @v_vchItemMasterID
					IF(ISNULL(@v_vchWhItemMasterID,'') = '')
						BEGIN
							SET @out_ErrorCode = '903';
							SELECT @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_ITEM_NOT_FOUND',@v_vchLocal,@v_vchWarehouse,@v_vchItemNumber,'@param3','@param4','@param5')
							GOTO WRITE_PROC
						END
			
					--Get & Check Item UOM
					SET @v_vchBaseItemUomID = NULL
					SELECT @v_vchBaseItemUomID = item_uom_id
						,@v_vchBaseUomPrompt = uom_prompt
						,@v_fltWidth = ISNULL(width,0)
						,@v_fltLength = ISNULL(length,0)
						,@v_fltHeight = ISNULL(height,0)
						,@v_fltGrossWeight = ISNULL(gross_weight,0)
						,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
						,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
					FROM t_wms_item_uom 
					WHERE item_master_id = @v_vchItemMasterID 
					AND primary_uom = 'YES'		
					IF (ISNULL(@v_vchBaseItemUomID,'') = '')
						BEGIN
							SET @out_ErrorCode = '107';
							SELECT @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC
						END

					IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
						BEGIN
							SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQuantity,2)
							SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQuantity,2)
						END
				END
			
				-- Check Data in Inventory
				IF NOT EXISTS(SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND owner_id = @v_vchOwnerID AND wh_item_master_id = @v_vchWhItemMasterID AND location_id = @v_vchFromLocationID)
					BEGIN
						SET @out_ErrorCode = '989';
						SELECT @out_ErrorMessage = 'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',@v_vchLocal,@v_vchSourceLocation,@v_vchItemNumber,@v_vchLPN,'@param4','@param5')
						GOTO WRITE_PROC;
					END
					
				-- Quantity not enough
				IF (SELECT SUM(quantity) - SUM(ISNULL(quantity_allocated,0)) FROM t_wms_inventory 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND owner_id = @v_vchOwnerID
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND location_id = @v_vchFromLocationID) < @v_fltQuantity
					BEGIN
						SET @out_ErrorCode = '989';
						SELECT @out_ErrorMessage = 'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' +dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',@v_vchLocal,@v_vchItemNumber,@v_vchSourceLocation,'@param3','@param4','@param5')
						GOTO WRITE_PROC;							
					END
					
				INVENTORY_MOVE:
					--Get Data
					SET @v_vchInventoryID	 =  NULL
					SET @v_vchStatusID		 =  NULL
					SET @v_vchStatus		 =  NULL
					SET @v_fltInvQuantity	 =  NULL
					SET @v_fltInvQtyAllocate =  NULL
					SET @v_vchParentLPN		 =  NULL
					SET @v_vchLPN			 =  NULL
					SET @v_vchLot			 =  NULL
					SET @v_vchExpiryDate	 =  NULL
					SET @v_vchSerialNumber	 =  NULL
					SET @v_vchAttribute1	 =  NULL
					SET @v_vchAttribute2	 =  NULL
					SET @v_vchAttribute3	 =  NULL
					SET @v_vchAttribute4	 =  NULL
					SET @v_vchAttribute5	 =  NULL
					SET @v_dtReceiveDate	 =  NULL

					SELECT TOP 1 @v_vchInventoryID = inventory_id
						,@v_vchAttributeGroupID = attribute_group_id
						,@v_vchStatusID = inventory_status_id
						,@v_vchStatus = inv_status
						,@v_fltInvQuantity = quantity
						,@v_fltInvQtyAllocate = quantity_allocated
						,@v_vchParentLPN = parent_lpn
						,@v_vchLPN = lpn
						,@v_vchLot = lot_number
						,@v_vchExpiryDate = expiry_date
						,@v_vchSerialNumber = serial_number
						,@v_vchAttribute1 = attribute1
						,@v_vchAttribute2 = attribute2
						,@v_vchAttribute3 = attribute3
						,@v_vchAttribute4 = attribute4
						,@v_vchAttribute5 = attribute5
						,@v_dtReceiveDate = receive_date
					FROM v_wms_inventory_data_by_serial
					WHERE wh_master_id = @v_vchWhMasterID 
					AND wh_item_master_id = @v_vchWhItemMasterID 
					AND location_id = @v_vchFromLocationID
					ORDER BY receive_date

					---------------------------------------
					-- Check Inventory
					---------------------------------------
					IF (ISNULL(@v_vchInventoryID,'') = '')
						BEGIN
							SET @out_ErrorCode = '989';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_INVENTORY_DATA_NO_DETAIL',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchSourceLocation,@v_vchItemNumber,'@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					IF (@v_fltInvQuantity - @v_fltInvQtyAllocate) < @v_fltQuantity
						BEGIN 
							SET @v_fltQtyMove = (@v_fltInvQuantity - @v_fltInvQtyAllocate)
						END
					ELSE
						BEGIN
							SET @v_fltQtyMove = @v_fltQuantity
						END 

					IF (@v_fltInvQuantity - @v_fltInvQtyAllocate) < @v_fltQtyMove
						BEGIN
							SET @out_ErrorCode = '989';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',@v_vchLocal,@v_vchItemNumber,@v_vchSourceLocation,'@param3','@param4','@param5')
							GOTO WRITE_PROC;	
						END

					--------------------------------------------
					--Manage source inventory
					--------------------------------------------
					UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyMove,@Round) 
						,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
						,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID

					IF (@v_vchSNControl = 'FULL')
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyMove,@Round) 
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID 
							AND attribute_value = @v_vchSerialNumber												
						END

					--Inventory attribute
					IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyMove,@Round) 
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
						END

					DELETE FROM t_wms_inventory WHERE quantity <= 0 --and quantity_allocated = 0
					DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 --and quantity_allocated = 0

					--Update Volumn & Weight in from location
					IF @v_vchFromLocationID IS NOT NULL
						BEGIN
							UPDATE [dbo].[t_wms_location]
							   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
								, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
								, update_date = GETDATE()  
								, [update_by] = @in_vchUserID   
							 WHERE [location_id] = @v_vchFromLocationID
						END

					--------------------------------------------
					--Manage Destination inventory
					--------------------------------------------
					EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
											 ,@in_vchWhMasterID			= @v_vchWhMasterID
											 ,@in_vchWhID				= @v_vchWarehouse
											 ,@in_vchOwnerID			= @v_vchOwnerID
											 ,@in_vchInventoryType		= 'INVENTORY'
											 ,@in_vchLocationID			= @v_vchToLocationID
											 ,@in_vchParentLPN			= @v_vchParentLPN
											 ,@in_vchLPN				= @v_vchLPN
											 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
											 ,@in_vchItemMasterID		= @v_vchItemMasterID
											 ,@in_vchItemNumber			= @v_vchItemNumber
											 ,@in_fltQuantity			= @v_fltQtyMove
											 ,@in_fltQtyAllocate		= 0
											 ,@in_fltQtyIncoming		= 0
											 ,@in_vchPrimaryItemUomID	= @v_vchBaseItemUomID
											 ,@in_vchInvStatusID		= @v_vchStatusID
											 ,@in_vchLotNumber			= @v_vchLot
											 ,@in_vchExpiryDate			= @v_vchExpiryDate
											 ,@in_vchSerialNumber		= @v_vchSerialNumber
											 ,@in_vchAttribute1			= @v_vchAttribute1
											 ,@in_vchAttribute2			= @v_vchAttribute2
											 ,@in_vchAttribute3			= @v_vchAttribute3
											 ,@in_vchAttribute4			= @v_vchAttribute4
											 ,@in_vchAttribute5			= @v_vchAttribute5
											 ,@in_dReceiveDate			= @v_dtReceiveDate
											 ,@in_vchDeviceID			= @in_vchDevice
											 ,@in_vchUserID				= @in_vchUserID
											 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
											 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
											 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

					IF (@out_ErrorCode <> '0')
						GOTO WRITE_PROC;

					-----------------------------------------------------------------------------------
					-- Write transaction log
					BEGIN
						WRITE_TRANS:							
					-----------------------------------------------------------------------------------	
						SET @v_vchTransID = NEWID();
						SET @v_dtEndTranDate = GETDATE();
						SET @v_vchProcessData1 = @out_ErrorMessage;
						SET @v_dtProcessDateTime = GETDATE();

						-- Set quantity after update
						SELECT @v_fltAfterQty = ROUND(ISNULL(@v_fltInvQuantity,0) - @v_fltQtyMove,@Round);						
						EXEC usp_LogManager
							@in_vchApplicationID		= @in_vchApplicationID
							, @in_vchAppName			= @v_vchApplicationName
							, @in_vchDevice				= @in_vchDevice
							, @in_vchUserID				= @in_vchUserID
							, @in_vchLogType			= 'TRANSACTION'
							, @in_vchProcess			= @c_vchObjName
							, @in_dtProcessDateTime		= @v_dtProcessDateTime
							, @in_vchTranType			= @v_vchTransactionType
							, @in_vchSubTranType		= @v_vchSubTranType
							, @in_dtStartTranDate		= @v_dtTranDate
							, @in_dtEndTranDate			= @v_dtEndTranDate
							, @in_vchWhID 				= @v_vchWarehouse
							, @in_vchToWhID 			= @v_vchWarehouse
							, @in_vchLocation			= @v_vchSourceLocation
							, @in_vchToLocation			= @v_vchDestinationLocation
							, @in_vchOwner				= @v_vchOwner
							, @in_vchToOwner			= @v_vchOwner
							, @in_vchItemNumber			= @v_vchItemNumber
							, @in_fltQuantity			= @v_fltQtyMove
							, @in_vchUOM				= @v_vchBaseUomPrompt
							, @in_fltAfterQuantity		= @v_fltAfterQty
							, @in_vchAfterUOM			= @v_vchBaseUomPrompt
							, @in_vchLotNumber			= @v_vchLot
							, @in_vchAfterLotNumber		= @v_vchLot
							, @in_dtExpiryDate			= @v_vchExpiryDate
							, @in_dtAfterExpiryDate		= @v_vchExpiryDate
							, @in_vchAttribute1			= @v_vchAttribute1	
							, @in_vchAfterAttribute1	= @v_vchAttribute1
							, @in_vchAttribute2			= @v_vchAttribute2
							, @in_vchAfterAttribute2	= @v_vchAttribute2		
							, @in_vchAttribute3			= @v_vchAttribute3	
							, @in_vchAfterAttribute3	= @v_vchAttribute3			
							, @in_vchAttribute4			= @v_vchAttribute4
							, @in_vchAfterAttribute4	= @v_vchAttribute4		
							, @in_vchAttribute5			= @v_vchAttribute5
							, @in_vchAfterAttribute5	= @v_vchAttribute5		
							, @in_vchSerialNumber		= @v_vchSerialNumber
							, @in_vchReferenceNumber	= @v_vchReferenceNumber
							, @in_vchControlNumber		= @in_vchSessingID
							, @in_vchLPN				= @v_vchLPN
							, @in_vchAfterLPN			= @v_vchLPN
							, @in_vchParentLPN			= @v_vchParentLPN
							, @in_vchAfterParentLPN		= @v_vchParentLPN
							, @in_vchStatus				= @v_vchStatus
							, @in_vchAfterStatus		= @v_vchStatus
							, @in_vchOrderNumber		= @v_vchSO
							, @in_vchReasonCode			= NULL
							, @in_vchShortQuantity		= 0
							, @in_vchHUDF1				= @v_vchPO
							, @in_vchHUDF2				= @v_vchRemark
							, @in_vchDUDF1				= @v_vchPO
							, @in_vchDUDF2				= @v_vchRemark
							, @in_vchHostRecordID		= @v_vchHostRecordID
							, @in_vchControlValue1		= @v_vchAXSourceLocation
							, @in_vchControlValue2		= @v_vchAXDestinationLocation
							, @in_vchErrorCode			= @out_ErrorCode OUTPUT
							, @in_vchMessage			= @out_ErrorMessage   OUTPUT

						IF (@out_ErrorCode <> '0')
							GOTO WRITE_PROC;
					END

					-- update for get last update inventory
					IF @v_vchToLocationID IS NOT NULL
					BEGIN
						UPDATE [dbo].[t_wms_location] SET
							[update_date] = GETDATE()    
							, [update_by] = @in_vchUserID 
						WHERE [location_id] = @v_vchToLocationID
					END

					SET @v_fltQuantity = @v_fltQuantity - @v_fltQtyMove
					IF @v_fltQuantity <> 0
						GOTO INVENTORY_MOVE;

					UPDATE t_wms_import_change_location SET process_status = 'COMPLETE' WHERE record_id = @v_vchRecordID

				NEXT_ROW:
					IF EXISTS (SELECT record_id FROM t_wms_import_change_location WHERE session_id = @in_vchSessingID AND process_status = 'PENDING')
						GOTO IMPORT_EXCEL;
			END
		
		IF ISNULL(@v_vchErrorMessage,'') <> ''
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage = @v_vchErrorMessage;
				IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
					ROLLBACK TRANSACTION;
			END
		ELSE
			BEGIN
				SET @out_ErrorCode = '0';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				COMMIT TRANSACTION;
			END

	DELETE t_wms_import_change_location where session_id = @in_vchSessingID
	
	--Update Host Shipment = PENDING
	IF (@v_vchTransactionType = 'INV_MOVE' AND @v_vchSubTranType = 'MOVE_ON_PC')
		BEGIN
			UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id = @v_vchHostRecordID AND processing_status = 'OPEN'
		END


	RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			--IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			--	ROLLBACK TRANSACTION;
					
			UPDATE t_wms_import_change_location SET process_status = 'ERROR' WHERE record_id = @v_vchRecordID
			SET @v_vchErrorMessage = @v_vchErrorMessage + ISNULL(@out_ErrorMessage,'') +'<BR/>'
			GOTO NEXT_ROW;
	END	   
	---------------------------------------------------------------------------------	
	--END TRY
    
	-------------------------------------------------------------------------------------
	---- Error Handling
	-------------------------------------------------------------------------------------    
 --   BEGIN CATCH
	--	IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
	--		ROLLBACK TRANSACTION;
		
	--	--UPDATE t_wms_import_change_location SET process_status = 'ERROR' WHERE record_id = @v_vchRecordID
	--	--SET @v_vchErrorMessage = @v_vchErrorMessage + ISNULL(@out_ErrorMessage,'')
	--	DELETE t_wms_import_change_location where session_id = @in_vchSessingID

	--	SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
	--	       @v_vchSqlErrorMessage = ERROR_MESSAGE(),
	--	       @v_intSqlErrorState = ERROR_STATE(),
	--		   @v_intSqlErrorSeverity = ERROR_SEVERITY(),
	--		   @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
	--	SET @out_ErrorMessage = @v_vchSqlErrorProcedure + ': ' + @out_ErrorMessage 
	--						+ '. SQL Error ['+ str(@v_intSqlErrorNumber) + '], '
	--						+ '. Severity ['+ str(@v_intSqlErrorSeverity) + '],'
	--						+ '. State ['+ str(@v_intSqlErrorState) + ']'

	--	IF(ISNULL(@out_ErrorMessage,'') = '')
	--		SET @out_ErrorMessage = 'SQL Error';

	--	SET @out_ErrorMessage =  'Row :'+'['+ CONVERT(VARCHAR,@v_vchRowNo) +']' +' Item :'+'['+ CONVERT(VARCHAR,@v_vchItemNumber) +']' + @out_ErrorMessage

	--	SET  @v_vchProcessData1 = @out_ErrorMessage;
	--	SET  @v_vchProcessData2 = @v_vchSqlErrorMessage;
	--	SET  @v_vchProcessData3 = 'Item number ' + @v_vchItemNumber;
	--	SET  @v_vchProcessData4 = 'To Location ' + @v_vchDestinationLocation;
		
	--	SET @out_ErrorCode = @v_intSqlErrorNumber;
	--	SET @out_ErrorMessage = @v_vchSqlErrorMessage;
		
	--	SET @v_dtProcessDateTime = GETDATE();
	--	SET @v_vchSqlErrorMessage = SUBSTRING(@v_vchSqlErrorMessage,0,100);
		
	--	EXEC usp_LogManager
	--		@in_vchApplicationID = @in_vchApplicationID,
	--		@in_vchWhID = @v_vchWarehouse,
	--		@in_vchDevice = @in_vchDevice,
	--		@in_vchUserID = @in_vchUserID,
	--		@in_vchLogType = 'PROCESS',
	--		@in_vchProcess = @c_vchObjName,
	--		@in_dtProcessDateTime = @v_dtProcessDateTime,
	--		@in_vchData1 = @v_vchProcessData1,
	--		@in_vchData2 = @v_vchProcessData2,
	--		@in_vchData3 = @v_vchProcessData3,
	--		@in_vchData4 = @v_vchProcessData4,
	--		@in_vchErrorCode = @v_intSqlErrorNumber,
	--		@in_vchMessage = @v_vchSqlErrorMessage
		
 --   END CATCH
END

