/****** Object:  StoredProcedure [dbo].[usp_import_inventory_conversion_volumn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_import_inventory_conversion_volumn]
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_vchBeginTrans			BIT = 0,
				@v_vchAppID					VARCHAR(40)='CC3D76CA-71B9-47CB-A933-4B1F1F489AF0',
				@v_vchAppName				NVARCHAR(50),
				@out_vchErrorCode			NVARCHAR(50),
				@out_vchErrorMsg			NVARCHAR(250),

				@v_vchHostInvImportID		VARCHAR (40),
				@v_vchProcessingCode		NVARCHAR(40),
				@v_vchProcessingStatus		NVARCHAR(40),
				@v_vchWhID					NVARCHAR(25),
				@v_vchOwner					NVARCHAR(50),
				@v_vchZone					NVARCHAR(50),
				@v_vchLocation				NVARCHAR(50),
				@v_vchItemNumber			NVARCHAR(50),
				@v_vchInventoryStatus		NVARCHAR(50),
				@v_vchQuantity				FLOAT,
				@v_vchUom					NVARCHAR(20),
				@v_vchLpn					NVARCHAR(25),
				@v_vchParentLpn				NVARCHAR(25),
				@v_vchLotNumber				NVARCHAR(50),
				@v_vchExpiryDate			NVARCHAR(50),
				@v_vchSerialNumber			NVARCHAR(50) ,
				@v_vchAttribute1			NVARCHAR(100),
				@v_vchAttribute2			NVARCHAR(100),
				@v_vchAttribute3			NVARCHAR(100),
				@v_vchAttribute4			NVARCHAR(100),
				@v_vchAttribute5			NVARCHAR(100),
				@v_dtReceiveDate			DATE,
				@v_dtMfgDate				DATE,
				@v_dtStartDate				DATETIME,
				@v_vchReferenceNumber		VARCHAR(50) = ''	
	 
		SET @v_dtStartDate = GETDATE();
		EXEC usp_get_application_name @v_vchAppID,@v_vchAppName OUTPUT
		EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT
	BEGIN TRY
		DECLARE cursorIMInventoryConversion CURSOR FOR

				SELECT [host_inv_import_id]
				  ,[processing_code]
				  ,[processing_status]
				  ,[wh_id]
				  ,[owner]
				  ,[zone]
				  ,(CASE ISNULL([location],'') WHEN '' THEN (SELECT TOP 1 loc.location
															FROM t_wms_zone_location zloc
															INNER JOIN t_wms_zone z on zloc.zone_id = z.zone_id
															INNER JOIN t_wms_location loc on zloc.location_id = loc.location_id
															INNER JOIN t_wms_wh wh ON z.wh_master_id = wh.wh_master_id
															WHERE wh.wh_id = [t_host_wms_inventory_conversion].wh_id 
															AND z.zone = [t_host_wms_inventory_conversion].zone 
															AND loc.loc_type = 'PICK') ELSE [location] END)
				  ,[item_number]
				  ,[inventory_status]
				  ,[quantity]
				  ,(CASE ISNULL([uom],'') WHEN '' THEN (SELECT TOP 1 u.uom_prompt
														FROM t_wms_item it
														INNER JOIN t_wms_item_uom u ON it.item_master_id = u.item_master_id
														WHERE it.item_number = [t_host_wms_inventory_conversion].item_number
														AND u.primary_uom = 'YES'
														AND u.is_active = 'YES') ELSE uom END)
				  ,[lpn]
				  ,[parent_lpn]
				  ,[lot_number]
				  ,CONVERT(NVARCHAR,expiry_date,112)
				  ,[serial_number]
				  ,[attribute1]
				  ,[attribute2]
				  ,[attribute3]
				  ,[attribute4]
				  ,[attribute5]
				  ,(CASE ISNULL([receive_date],'') WHEN '' THEN GETDATE() ELSE receive_date END)
				  ,[mfg_date]
			  FROM [dbo].[t_host_wms_inventory_conversion]
			  WHERE processing_status = 'PENDING'
		
		OPEN cursorIMInventoryConversion;
		FETCH FROM cursorIMInventoryConversion INTO @v_vchHostInvImportID,@v_vchProcessingCode,@v_vchProcessingStatus,@v_vchWhID,@v_vchOwner,@v_vchZone,@v_vchLocation,@v_vchItemNumber,@v_vchInventoryStatus,@v_vchQuantity
													,@v_vchUom,@v_vchLpn,@v_vchParentLpn,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate,@v_dtMfgDate
		WHILE @@FETCH_STATUS = 0
			BEGIN 
					DECLARE @v_vchWhMasterID	 UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchOwnerID		 UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchInvStatusID	 UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchLocationID	 UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchWhItemMasterID UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchItemMasterID	 UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchItemUomID		 UNIQUEIDENTIFIER = NULL
					DECLARE @v_intItemShelfLife	 INT
					DECLARE @v_vchLotControl		VARCHAR(5) = NULL
					DECLARE @v_vchExpDateControl	VARCHAR(5) = NULL
					DECLARE @v_vchSnControl			VARCHAR(5) = NULL
					DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
					DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
					DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
					DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
					DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL

					SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @v_vchWhID and is_active = 'YES'
					IF @v_vchWhMasterID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'WAREHOUSE NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END

					IF (SELECT COUNT(*) FROM t_wms_owner where  is_active = 'YES') = 1 AND ISNULL(@v_vchOwner,'') = ''
						BEGIN
							SELECT top 1 @v_vchOwnerID = owner_id, @v_vchOwner = owner_code FROM t_wms_owner WHERE is_active = 'YES'
						END
					ELSE
						BEGIN
							SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchOwner and is_active = 'YES'
							IF @v_vchOwnerID is null
							BEGIN
								UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'OWNER NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
								GOTO NEXT_VALUE
							END
						END

					SELECT @v_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchInventoryStatus and is_active = 'YES'
					IF @v_vchInvStatusID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'INVENTORY STATUS NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END

					SELECT @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID and location = @v_vchLocation and is_active = 'YES'
					IF @v_vchLocationID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'LOCATION NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END

					SELECT @v_vchWhItemMasterID = whItem.wh_item_master_id
						,@v_vchItemMasterID = item.item_master_id 
						,@v_intItemShelfLife = item.days_to_expire
						,@v_vchLotControl = item.lot_control
						,@v_vchExpDateControl = item.expiry_date_control
						,@v_vchSNControl = item.sn_control
						,@v_vchAttribute1Control = item.attribute1_control
						,@v_vchAttribute2Control = item.attribute2_control
						,@v_vchAttribute3Control = item.attribute3_control
						,@v_vchAttribute4Control = item.attribute4_control
						,@v_vchAttribute5Control = item.attribute5_control
					FROM t_wms_wh_item whItem
					LEFT JOIN t_wms_item item on item.item_master_id = whItem.item_master_id
					WHERE item.item_number = @v_vchItemNumber
					and item.owner_id = @v_vchOwnerID
					and whItem.wh_master_id = @v_vchWhMasterID
					and item.is_active = 'YES'
					IF @v_vchWhItemMasterID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'WAREHOUSE ITEM NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END

					IF @v_vchItemMasterID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'ITEM MASTER NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END
					
					SELECT @v_vchItemUomID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND uom = @v_vchUom and is_active = 'YES'
					IF @v_vchItemUomID is null
					BEGIN
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR',[error_message] = 'UOM NOT FOUND' WHERE host_inv_import_id = @v_vchHostInvImportID
						GOTO NEXT_VALUE
					END

					IF @v_vchLotControl = 'NONE'
					BEGIN
						SET @v_vchLotNumber = NULL
					END
					IF @v_vchExpDateControl = 'NONE'
					BEGIN
						SET @v_vchExpiryDate = NULL
					END
					IF @v_vchSNControl = 'NONE'
					BEGIN
						SET @v_vchSerialNumber = NULL
					END
					IF @v_vchAttribute1Control = 'NONE'
						BEGIN
							SET @v_vchAttribute1 = NULL
						END
					IF @v_vchAttribute2Control = 'NONE'
						BEGIN
							SET @v_vchAttribute2 = NULL
						END
					IF @v_vchAttribute3Control = 'NONE'
						BEGIN
							SET @v_vchAttribute3 = NULL
						END
					IF @v_vchAttribute4Control = 'NONE'
						BEGIN
							SET @v_vchAttribute4 = NULL
						END
					IF @v_vchAttribute5Control = 'NONE'
						BEGIN
							SET @v_vchAttribute5 = NULL
						END

					IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MFG_CAL_EXPDATE' AND is_active = 'YES') = 'YES' AND @v_vchExpDateControl = 'FULL'
					BEGIN
						SET @v_vchExpiryDate = CONVERT(VARCHAR, DATEADD(DAY,@v_intItemShelfLife, GETDATE()),112)
					END  
				   
					EXEC usp_inventory_adjust_in @in_vchApplicationID	 = @v_vchAppID
												, @in_vchDevice			 = 'INITIAL STOCK'
												, @in_vchUserID			 = 'SYSTEM'
												, @in_vchTransactionType = 'INV_ADJUST'	
												, @in_vchSubTranType	 = 'ADJUST_IN_NOT_ERP'	
												, @in_vchWhMasterID		 = @v_vchWhMasterID
												, @in_vchOwnerID		 = @v_vchOwnerID
												, @in_vchInvStatusID	 = @v_vchInvStatusID
												, @in_vchLocationID		 = @v_vchLocationID
												, @in_vchWhItemMasterID	 = @v_vchWhItemMasterID
												, @in_vchParentLPN		 = @v_vchParentLpn
												, @in_vchLPN			 = @v_vchLpn
												, @in_vchLotNumber		 = @v_vchLotNumber
												, @in_vchExpiryDate		 = @v_vchExpiryDate
												, @in_vchAttribute1		 = @v_vchAttribute1
												, @in_vchAttribute2		 = @v_vchAttribute2
												, @in_vchAttribute3		 = @v_vchAttribute3
												, @in_vchAttribute4		 = @v_vchAttribute4
												, @in_vchAttribute5		 = @v_vchAttribute5
												, @in_vchSerialNumber	 = @v_vchSerialNumber
												, @in_fltQty			 = @v_vchQuantity
												, @in_vchItemUomID		 = @v_vchItemUomID
												, @in_vchReasonID		 = NULL
												, @in_dtReceiveDate		 = @v_dtReceiveDate
												, @in_dtMfgDate			 = @v_dtMfgDate
												, @in_vchReferenceNumber = @v_vchReferenceNumber
												, @out_ErrorCode		 = @out_vchErrorCode	OUTPUT	
												, @out_ErrorMessage		 = @out_vchErrorMsg		OUTPUT
												
					--Write Status
					if @out_vchErrorCode = '0'
						UPDATE t_host_wms_inventory_conversion set processing_status = 'COMPLETE' WHERE host_inv_import_id = @v_vchHostInvImportID
					else	
						UPDATE t_host_wms_inventory_conversion set processing_status = 'ERROR', [error_message] = @out_vchErrorMsg WHERE host_inv_import_id = @v_vchHostInvImportID

					NEXT_VALUE: 
				FETCH FROM cursorIMInventoryConversion INTO @v_vchHostInvImportID,@v_vchProcessingCode,@v_vchProcessingStatus,@v_vchWhID,@v_vchOwner,@v_vchZone,@v_vchLocation,@v_vchItemNumber,@v_vchInventoryStatus,@v_vchQuantity
										,@v_vchUom,@v_vchLpn,@v_vchParentLpn,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate,@v_dtMfgDate
			END
		Close cursorIMInventoryConversion;
		Deallocate cursorIMInventoryConversion;
		PRINT 'SAVE'
	END TRY
	BEGIN CATCH
		PRINT ERROR_MESSAGE()
		
		IF CURSOR_STATUS('global','cursorIMInventoryConversion') >= -1
			BEGIN
				CLOSE cursorIMInventoryConversion;
				DEALLOCATE cursorIMInventoryConversion;
			END
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_import_location_delete_by_sessionID]    Script Date: 08/08/2025 11:11:30 ******/
