GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_import_location_delete_by_sessionID]
( 
	@in_vchSessingID VARCHAR(40) 
)
AS
BEGIN
	DELETE FROM [dbo].[t_wms_import_change_location] WHERE session_id = @in_vchSessingID
END
