/****** Object:  StoredProcedure [dbo].[usp_inbound_edit_receive]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_edit_receive]
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchInboundDetailID	UNIQUEIDENTIFIER, 
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER, 
	@in_vchReciptDetailID	UNIQUEIDENTIFIER,
	@in_fltNewReceiptQty	FLOAT,
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inbound_edit_receive]' -- The name that uniquely tags this object.
	DECLARE @v_vchApplicationName	NVARCHAR(100)
	DECLARE @v_vchProcessData1		NVARCHAR(1000)
	DECLARE @v_vchProcessData2		NVARCHAR(1000)
	DECLARE @v_vchProcessData3		NVARCHAR(1000)
	DECLARE @v_vchProcessData4		NVARCHAR(1000)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_vchBeginTrans		BIT = 0
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @Round					INT
	DECLARE @v_vchTransactionType	NVARCHAR(20) = 'INV_ADJUST'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'ADJUST_OUT_RECEIPT'
	DECLARE @v_vchInboundNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10) = NULL
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWarehouse			NVARCHAR(25) = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(50) = NULL
	DECLARE @v_fltOldReceiptQty		FLOAT = NULL
	DECLARE @v_vchReceiptNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchReceiptStatus		NVARCHAR(10) = NULL
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLocation			NVARCHAR(50) = NULL
	DECLARE @v_vchParentLPN			NVARCHAR(25) = NULL
	DECLARE @v_vchLPN				NVARCHAR(25) = NULL
	DECLARE @v_vchLotNumber			NVARCHAR(50) = NULL
	DECLARE @v_vchExpiryDate		NVARCHAR(50) = NULL
	DECLARE @v_vchAttribute1		NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute2		NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute3		NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute4		NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute5		NVARCHAR(100) = NULL 
	DECLARE @v_vchSerialNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL
	DECLARE @v_dtReceiveDate		DATE = NULL
	DECLARE @v_dtMFGDate			DATE = NULL 

	DECLARE @v_vchLotControl		VARCHAR(5) = NULL
    DECLARE @v_vchSNControl			VARCHAR(5) = NULL
    DECLARE @v_vchExpiryDateControl	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control	VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control	VARCHAR(5) = NULL

	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_vchBaseUom			NVARCHAR(20) = NULL
		
	DECLARE @v_vchInventoryID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL 
	DECLARE @v_fltAfterQty				FLOAT = 0		--For Write Log
	DECLARE @v_fltAllocatedQty			FLOAT = 0 

	DECLARE @v_fltWidth					FLOAT = 0
	DECLARE @v_fltLength				FLOAT = 0
	DECLARE @v_fltHeight				FLOAT = 0
	DECLARE @v_fltGrossWeight			FLOAT = 0
	DECLARE @v_intPercentTolerance		FLOAT = 0
	DECLARE @v_intPercenToleranceWeight FLOAT = 0
	DECLARE @v_fltVolumn				FLOAT = 0
	DECLARE @v_fltTotalWeight			FLOAT = 0
	DECLARE @v_vchERPSourceLocation		NVARCHAR(50)
	DECLARE @v_vchHostRecordID			NVARCHAR(40)

	BEGIN TRY 
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SET @in_fltNewReceiptQty = ROUND(@in_fltNewReceiptQty,@Round)
 
		--Get Data
		SELECT @v_vchInboundNumber = ibMS.inbound_order_number
			,@v_vchOrderStatus = ibMS.order_status
			,@v_vchWhMasterID = ibMS.wh_master_id
			,@v_vchWarehouse = wh.wh_id
			,@v_vchOwnerID = ibMS.owner_id
			,@v_vchOwnerCode = own.owner_code
			,@v_vchReceiptNumber = recHD.receipt_number
			,@v_vchReceiptStatus = recHD.receipt_status
			,@v_vchWhItemMasterID = recDT.wh_item_master_id
			,@v_vchItemMasterID = item.item_master_id
			,@v_vchItemNumber = item.item_number
			,@v_vchLocationID = loc.location_id
			,@v_vchLocation = recDT.location_received
			,@v_vchParentLPN = recDT.parent_lpn
			,@v_vchLPN = recDT.lpn
			,@v_vchLotNumber = recDT.lot_number
			,@v_vchExpiryDate = recDT.expiry_date
			,@v_vchAttribute1 = recDT.attribute1
			,@v_vchAttribute2 = recDT.attribute2
			,@v_vchAttribute3 = recDT.attribute3
			,@v_vchAttribute4 = recDT.attribute4
			,@v_vchAttribute5 = recDT.attribute5
			,@v_vchSerialNumber = recDT.serial_number
			,@v_vchInvStatusID = invST.inventory_status_id
			,@v_vchInvStatus = recDT.receipt_item_status
			,@v_dtReceiveDate = recDT.receive_date
			,@v_dtMFGDate = recDT.mfg_date
			,@v_vchLotControl = item.lot_control 
			,@v_vchSNControl = item.sn_control
			,@v_vchExpiryDateControl = item.expiry_date_control
			,@v_vchAttribute1Control = item.attribute1_control
			,@v_vchAttribute2Control = item.attribute2_control
			,@v_vchAttribute3Control = item.attribute3_control
			,@v_vchAttribute4Control = item.attribute4_control
			,@v_vchAttribute5Control = item.attribute5_control
			,@v_vchBaseItemUomID = uom.item_uom_id
			,@v_vchBaseUomPrompt = uom.uom_prompt
			,@v_vchBaseUom = uom.uom
			,@v_fltWidth = ISNULL(uom.width,0)
			,@v_fltLength = ISNULL(uom.length,0)
			,@v_fltHeight = ISNULL(uom.height,0)
			,@v_fltGrossWeight = ISNULL(uom.gross_weight,0)
			,@v_intPercentTolerance = ISNULL(uom.percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(uom.percent_tolerance_weight,0)
			,@v_vchERPSourceLocation = loc.erp_location
			,@v_fltOldReceiptQty = recDT.quantity_received
		FROM t_wms_inbound_master ibMS 
		INNER JOIN t_wms_receipt_header recHD ON recHD.inbound_order_master_id = ibMS.inbound_order_master_id
		INNER JOIN t_wms_receipt_detail recDT ON recHD.receipt_header_id = recDT.receipt_header_id
		INNER JOIN t_wms_wh wh ON ibMS.wh_master_id = wh.wh_master_id
		INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
		INNER JOIN t_wms_wh_item whItem ON recDT.wh_item_master_id = whItem.wh_item_master_id
		INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
		INNER JOIN t_wms_item_uom uom ON uom.item_master_id = item.item_master_id AND uom.primary_uom = 'YES'
		INNER JOIN t_wms_inventory_status invST on recDT.receipt_item_status = invST.inv_status
		INNER JOIN t_wms_location loc ON recDT.location_received = loc.location AND loc.wh_master_id = ibMS.wh_master_id
		WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID
		AND recDT.receipt_detail_id = @in_vchReciptDetailID

		-- Get and check receipt status
		IF (@v_vchReceiptStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_NUMBER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		-- Get and check order status
		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		-- Check Receipt Detail
		IF NOT EXISTS (SELECT receipt_detail_id FROM t_wms_receipt_detail WHERE receipt_detail_id = @in_vchReciptDetailID)
			BEGIN
				SET @out_ErrorCode = 'NOT_FOUND_RECEIPT_DETAIL_FOR_EDIT';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END
			 
		-- Check Qty Edit ต้องน้อยกว่า ค่าเดิม
		IF ROUND(ISNULL(@in_fltNewReceiptQty,0),@Round) > ROUND(ISNULL(@v_fltOldReceiptQty,0),@Round)
			BEGIN
				SET @out_ErrorCode = 'CANNOT_EDIT_QTY_MORE_THAN_OLD_QTY';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Check Inventory
		IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
			BEGIN
				SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * ROUND(@v_fltOldReceiptQty - @in_fltNewReceiptQty,@Round),2)
				SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * ROUND(@v_fltOldReceiptQty - @in_fltNewReceiptQty,@Round),2)
			END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;

		--Adjust Out inventory
		DECLARE @v_fltReceiptAdjustQty	FLOAT = 0;
		SET @v_fltReceiptAdjustQty = ROUND(@in_fltNewReceiptQty - @v_fltOldReceiptQty,@Round)

		SET @v_vchInventoryID = NULL;
		SET @v_vchAttributeGroupID = NULL;

		SELECT @v_vchInventoryID = inventory_id
			,@v_vchAttributeGroupID = attribute_group_id
			,@v_dtMfgDate = mfg_date
			,@v_fltAfterQty = quantity
			,@v_fltAllocatedQty = quantity_allocated
		FROM v_wms_inventory_data_serial_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND wh_item_master_id = @v_vchWhItemMasterID 
		AND location_id = @v_vchLocationID 
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'') 
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
		AND ISNULL([expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
		AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
						
		IF (@v_vchInventoryID IS NULL)
			BEGIN
				SET @out_ErrorCode = '989';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,@v_vchItemNumber,@v_vchLPN,'@param4','@param5')
				GOTO WRITE_PROC;
			END
							
		-- Quantity not enough
		-- ค่าที่ส่งมาสำหรับ Adjust out จะเป็นค่าติดลบ ดังนั้นตอน Check กับ Inventory ให้เอาไป * -1 เพื่อให้ค่าเป็น +
		IF ((ISNULL(@v_fltAfterQty,0) - ISNULL(@v_fltAllocatedQty,0)) < (@v_fltReceiptAdjustQty * -1))
			BEGIN
				SET @out_ErrorCode = '989';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ADJUST_QTY_MOVE_THEN_INVENTORY',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END

		--------------------------------------------
		--Manage source inventory
		--Qty ที่ส่งมาจะ (ติดลบ)
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity + @v_fltReceiptAdjustQty,@Round)
			,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
			,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity + @v_fltReceiptAdjustQty,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID 
				AND attribute_value = @v_vchSerialNumber												
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity + @v_fltReceiptAdjustQty,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		----Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id = @v_vchInventoryID

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 --and quantity_allocated = 0
		DELETE FROM t_wms_inventory WHERE quantity <= 0 --and quantity_allocated = 0
 
		--Update Volumn & Weight in from location
		IF @v_vchLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location]
					SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
					, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
					, update_date = GETDATE()  
					, [update_by] = @in_vchUserID   
					WHERE [location_id] = @v_vchLocationID
			END

		-- Set quantity after update
		SELECT @v_fltAfterQty = ROUND(ISNULL(@v_fltAfterQty,0) + @v_fltReceiptAdjustQty,@Round);

		--Update new receipt quantity
		UPDATE [dbo].[t_wms_receipt_detail] SET
			quantity_received = ROUND((quantity_received + @v_fltReceiptAdjustQty),@Round)
		WHERE receipt_detail_id = @in_vchReciptDetailID
		AND receipt_header_id = @in_vchReceiptHeaderID

		UPDATE t_wms_inbound_detail SET 
			quantity_receive = ROUND((quantity_receive + @v_fltReceiptAdjustQty),@Round)
			,update_by = @in_vchUserID
			,update_date = GETDATE()
		WHERE inbound_order_detail_id = @in_vchInboundDetailID
		AND inbound_order_master_id = @in_vchInboundMasterID

		DELETE [t_wms_receipt_detail] WHERE receipt_detail_id = @in_vchReciptDetailID AND receipt_header_id = @in_vchReceiptHeaderID AND [quantity_received] = 0
		
		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTransactionType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
				END
							
			SET @v_dtProcessDateTime = GETDATE()
			EXEC usp_LogManager
				@in_vchApplicationID		= @in_vchApplicationID
				, @in_vchAppName			= @v_vchApplicationName
				, @in_vchDevice				= @in_vchDeviceID
				, @in_vchUserID				= @in_vchUserID
				, @in_vchLogType			= 'TRANSACTION'
				, @in_vchProcess			= @c_vchObjName
				, @in_dtProcessDateTime		= @v_dtProcessDateTime
				, @in_vchTranType			= @v_vchTransactionType
				, @in_vchSubTranType		= @v_vchSubTranType
				, @in_dtStartTranDate		= @v_dtStartTranDate
				, @in_dtEndTranDate			= @v_dtProcessDateTime
				, @in_vchWhID 				= @v_vchWarehouse
				, @in_vchToWhID 			= NULL
				, @in_vchLocation			= @v_vchLocation
				, @in_vchToLocation			= NULL
				, @in_vchOwner				= @v_vchOwnerCode
				, @in_vchToOwner			= NULL
				, @in_vchItemNumber			= @v_vchItemNumber
				, @in_fltQuantity			= @v_fltReceiptAdjustQty
				, @in_vchUOM				= @v_vchBaseUom
				, @in_fltAfterQuantity		= @v_fltAfterQty
				, @in_vchAfterUOM			= @v_vchBaseUom
				, @in_vchLotNumber			= @v_vchLotNumber
				, @in_vchAfterLotNumber		= NULL
				, @in_dtExpiryDate			= @v_vchExpiryDate
				, @in_dtAfterExpiryDate		= NULL
				, @in_vchAttribute1			= @v_vchAttribute1	
				, @in_vchAfterAttribute1	= NULL
				, @in_vchAttribute2			= @v_vchAttribute2
				, @in_vchAfterAttribute2	= NULL	
				, @in_vchAttribute3			= @v_vchAttribute3	
				, @in_vchAfterAttribute3	= NULL		
				, @in_vchAttribute4			= @v_vchAttribute4
				, @in_vchAfterAttribute4	= NULL	
				, @in_vchAttribute5			= @v_vchAttribute5
				, @in_vchAfterAttribute5	= NULL		
				, @in_vchSerialNumber		= @v_vchSerialNumber
				, @in_vchLPN				= @v_vchLPN
				, @in_vchAfterLPN			= NULL
				, @in_vchParentLPN			= @v_vchParentLPN
				, @in_vchAfterParentLPN		= NULL
				, @in_vchStatus				= @v_vchInvStatus
				, @in_vchAfterStatus		= NULL 
				, @in_dtReceiveDate			= @v_dtReceiveDate
				, @in_dtProductionDate		= @v_dtMfgDate 
				, @in_vchHostRecordID		= @v_vchHostRecordID
				, @in_vchOrderNumber		= @v_vchInboundNumber
				, @in_vchControlValue1		= @v_vchERPSourceLocation
				, @in_vchErrorCode			= @out_ErrorCode OUTPUT
				, @in_vchMessage			= @out_ErrorMessage OUTPUT

			IF (@out_ErrorCode <> '0')
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					BEGIN
						ROLLBACK TRANSACTION;
						RETURN;
					END
		END

		-- For Dashboard
		EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT'
											,@in_vchTransType	 = 'ADJUST'
											,@in_vchWhMasterID	 = @v_vchWhMasterID
											,@in_vchOwnerID		 = @v_vchOwnerID
											,@in_vchOwnerCode	 = @v_vchOwnerCode
											,@in_vchLocationID	 = @v_vchLocationID
											,@in_vchItemMasterID = @v_vchItemMasterID
											,@in_vchInvStatusID	 = @v_vchInvStatusID
											,@in_vchToWhMasterID = NULL
											,@in_vchToLocationID = NULL
											,@in_vchToInvStatusID = NULL
											,@in_fltQuantity	 = @v_fltReceiptAdjustQty
											,@in_vchUserID		 = @in_vchUserID

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;
	 
	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			
			SET @v_dtProcessDateTime = GETDATE();
			SET @v_vchProcessData1 = 'Receipt Number ' + @v_vchReceiptNumber;
			SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END

    END TRY
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION;

		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
			
		SET @v_dtProcessDateTime = GETDATE();

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_generate_running_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_inbound_generate_running_order]
	@in_dtpCreateDate			DATETIME,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	Begin Try
		Declare @v_vchYear			VARCHAR(40)
		Declare	@v_vchMonth			NVARCHAR(2)
		Declare	@v_vchDay			NVARCHAR(2) 
		Declare	@v_vchPrefix		NVARCHAR(5)
		Declare	@v_vchSuffix		NVARCHAR(5)
		Declare	@v_vchFormat		NVARCHAR(10)
		Declare	@v_intRunning		INT
		Declare	@v_vchRunningID		VARCHAR(40)
		Declare	@v_vchInboundOrderNumber	NVARCHAR(50)

		IF @in_dtpCreateDate is null
			set @in_dtpCreateDate = GETDATE()

		Select @v_vchYear = DATEPART(YYYY,@in_dtpCreateDate)
		Select @v_vchMonth = DATEPART(MM,@in_dtpCreateDate)
		Select @v_vchDay = DATEPART(DD,@in_dtpCreateDate)

		Select @v_vchPrefix = ISNULL(value,'') from t_wms_rule where rule_code = 'PREFIX_INBOUND_ORDER_FOR_RUNNING'
		Select @v_vchSuffix = ISNULL(value,'') from t_wms_rule where rule_code = 'SUFFIX_INBOUND_ORDER_FOR_RUNNING'
		Select @v_vchFormat = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_INBOUND_ORDER_FOR_RUNNING'

		Select @v_vchRunningID = running_id,@v_intRunning = running from t_wms_running_inbound_order where [year] = @v_vchYear and [month] = @v_vchMonth and [day] = @v_vchDay

		If (@v_intRunning is null)
			Begin
				Set @v_intRunning = 0;
			End

		Set @v_intRunning = @v_intRunning + 1;
		SET @v_vchInboundOrderNumber = ISNULL(@v_vchPrefix,'') + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
		If (@v_vchRunningID is null)
			Begin
				Set @v_vchRunningID = NEWID();
				Insert into t_wms_running_inbound_order(year, month, day, running, prefix, sufix)
				Values(@v_vchYear,@v_vchMonth,@v_vchDay,@v_intRunning,@v_vchPrefix,@v_vchSuffix)
			End
		Else
			Begin
				Update t_wms_running_inbound_order set running = @v_intRunning where running_id = @v_vchRunningID
			End

		Set @out_ErrorMessage = '0';
		Select @v_vchInboundOrderNumber AS inbound_order_number

	End Try
	Begin Catch
		SET @out_ErrorMessage = ERROR_MESSAGE();
	End Catch

END


GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_get_po_detail]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-11-20
-- Description:	Select inbound po detail for
--				create new inbound order
-- =============================================
CREATE PROCEDURE [dbo].[usp_inbound_get_po_detail]

	@inbound_order_master_id			NVARCHAR(500) 
AS
BEGIN
	
SELECT 
t_wms_inbound_po_master.inbound_order_number+'|'+t_wms_inbound_po_detail.line_number+'|'+t_wms_item.item_number as KeyID
,t_wms_inbound_po_detail.line_number
,t_wms_inbound_po_detail.default_item_status
,t_wms_item.item_number
,t_wms_item.[description]
,t_wms_inbound_po_detail.[expiry_date]
,t_wms_inbound_po_detail.lot_number
,t_wms_inbound_po_detail.quantity_order
,t_wms_inbound_po_detail.quantity_order - isnull((
select 
sum(case when t_wms_inbound_master.order_status = 'CLOSE' 
then t_wms_inbound_detail.quantity_receive 
else t_wms_inbound_detail.quantity_order 
end)
from t_wms_inbound_master 
inner join t_wms_inbound_detail on t_wms_inbound_master.inbound_order_master_id = t_wms_inbound_detail.inbound_order_master_id
where 
t_wms_inbound_master.reference_number = t_wms_inbound_po_master.inbound_order_number
and t_wms_inbound_detail.line_number = t_wms_inbound_po_detail.line_number
and t_wms_inbound_detail.wh_item_master_id = t_wms_inbound_po_detail.wh_item_master_id
group by  
t_wms_inbound_detail.line_number
,t_wms_inbound_detail.wh_item_master_id
),0) as remain_quantity
,0 as create_qty
,t_wms_item_uom.uom
,t_wms_inbound_po_detail.over_receipt_allowed
,t_wms_inbound_po_detail.over_receipt_percentage
,t_wms_inbound_po_detail.price
,t_wms_category.item_category
,t_wms_inbound_po_detail.grade
,t_wms_inbound_po_detail.wh_item_master_id
FROM t_wms_inbound_po_detail
INNER JOIN t_wms_inbound_po_master on t_wms_inbound_po_detail.inbound_order_master_id = t_wms_inbound_po_master.inbound_order_master_id
INNER JOIN t_wms_wh_item on t_wms_inbound_po_detail.wh_item_master_id = t_wms_wh_item.wh_item_master_id
INNER JOIN t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
INNER JOIN t_wms_item_uom on t_wms_inbound_po_detail.item_uom_id = t_wms_item_uom.item_uom_id
INNER JOIN t_wms_category on t_wms_item.category_id = t_wms_category.category_id
WHERE 
t_wms_inbound_po_master.inbound_order_master_id = @inbound_order_master_id
ORDER By t_wms_inbound_po_detail.line_number
END


GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_insert_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_insert_order]
(
	@in_vchApplicationID	VARCHAR(40)   = NULL,
	@in_vchDeviceID			NVARCHAR(50)  = NULL,
	@in_vchUserID			NVARCHAR(10)  = NULL,
	@in_vchWhMasterID		VARCHAR(40)   = NULL,
	@in_vchOrderNumber		VARCHAR(50)   = NULL,
	@in_vchLocation			NVARCHAR(50)  = NULL,
	@in_vchParentLPN		NVARCHAR(25)  = NULL,
	@in_vchLPN				NVARCHAR(25)  = NULL,	
	@in_vchItemNumber		NVARCHAR(50)  = NULL,
	@in_vchLotNumber		NVARCHAR(50)  = NULL,
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchSerialNumber		NVARCHAR(25)  = NULL,	-- ALL หรือส่งค่ามา
	@in_fltQuantity			FLOAT		  = NULL,
	@in_vchUOMPrompt		NVARCHAR(40)  = NULL,
	@in_vchDefaultItemStatus NVARCHAR(40) = NULL,	-- มาจาก Plan
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@out_vchErrorCode		NVARCHAR(50)  OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	DECLARE @v_nCount				INT,
			@Round					INT,
			@v_vchOutboundMasterID	VARCHAR(40)  = NULL,
			@v_vchOwnerID			VARCHAR(40)  = NULL,
			@v_vchOrderType			NVARCHAR(30) = NULL,
			@v_vchToWhMasterID		VARCHAR(40)  = NULL,
			@v_vchInboundMasterID	VARCHAR(40)  = NULL,
			@v_vchInboundDetailID	VARCHAR(40)  = NULL,
			@v_vchToWhItemMasterID	VARCHAR(40)  = NULL,
			@v_vchToItemUomID		VARCHAR(40)  = NULL,
			@v_vchToUOMPrompt		NVARCHAR(40) = NULL,
			@v_vchToLocation		NVARCHAR(50) = NULL,
			@v_vchReceiptNumber		NVARCHAR(50) = NULL,
			@v_vchReceiptStatus		NVARCHAR(10) = NULL,
			@v_vchLineNumber		NVARCHAR(10) = NULL,
			@v_vchGrade				NVARCHAR(40) = NULL,
			@v_fltPrice				FLOAT,
			@v_fltConversionQuantity	FLOAT,
			@v_vchIBOrderType		NVARCHAR(30) = NULL,
			@v_vchIBOrderNumber		NVARCHAR(50) = NULL,	

			-- From
			@v_vchItemMasterID		VARCHAR(40)  = NULL,
			@v_vchPrimaryUOMPrompt	NVARCHAR(40) = NULL,
			@v_vchPrimaryConversion	FLOAT		 = NULL,
			@v_vchLPNControl		NVARCHAR(3)  = NULL

	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SET @v_vchIBOrderNumber = 'IB' + @in_vchOrderNumber

	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderType = order_type
		,@v_vchOwnerID = owner_id
		,@v_vchToWhMasterID = department
	FROM t_wms_outbound_master 
	WHERE wh_master_id = @in_vchWhMasterID 
	AND outbound_order_number = @in_vchOrderNumber

	--------------------------------------------------------
	-- Check Rule Order Type ฝั่ง Outbound ที่ใช้สำหรับ Insert IB
	--------------------------------------------------------
	IF (@v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_INBOUND' and is_active = 'YES'))
	BEGIN
		RETURN;
	END

	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-ORDER-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END
	
	--------------------------------------------------------
	-- Get Order Type ที่จำให้กำหนดในฝั่ง Inbound
	--------------------------------------------------------
	SELECT TOP 1 @v_vchIBOrderType = value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_INBOUND_SET_ORDERTYPE' AND is_active = 'YES'

	IF @v_vchIBOrderType NOT IN (SELECT value_member FROM dbo.t_com_combobox_item WHERE group_name = 'inbound_order_type' AND is_active = 'YES')  
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-INVALID-ORDERTYPE'
			GOTO EXIT_LABEL;
		END

	----------------------------------------------------------
	-- Check To wh_master_id โดยมาจาก Column department
	-- จะมีค่าเมื่อต้องการ auto create plan receipt from pick item
	----------------------------------------------------------	
	IF ISNULL(@v_vchToWhMasterID,'') = ''
		BEGIN
			SET @out_vchErrorCode = 'INFO-TO-WAREHOUSE-NOT-FOUND'
			GOTO EXIT_LABEL;
		END

	--------------------------------------------------
	-- Check From Location  Control LPN
	--------------------------------------------------
	SELECT @v_vchLPNControl = lpn_controlled FROM t_wms_location 
	WHERE location = @in_vchLocation 
	AND wh_master_id = @in_vchWhMasterID
	AND is_active = 'YES' 

	IF (@v_vchLPNControl = 'NO')
	BEGIN
		SET @in_vchLPN = NULL
	END

	--------------------------------------------------
	-- Get Primary UOM และ คำนวนจำนวนให้อยู่หน่วยที่เล็กที่สุด
	-- From Warehouse
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id
		,@v_vchPrimaryUOMPrompt = uom.uom_prompt
		,@v_vchPrimaryConversion = uom.conversion_factor
	FROM t_wms_wh_item whItem
	LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	LEFT JOIn t_wms_item_uom uom ON (item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES' AND uom.is_active = 'YES')
	WHERE whItem.wh_master_id = @in_vchWhMasterID
	AND owner_id = @v_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF @in_vchUOMPrompt <> @v_vchPrimaryUOMPrompt
		BEGIN
			-- กรณีที่ไม่ได้จ่ายเป็นหน่วยที่เล็กที่สุด ต้องคำนวณ จำนวนที่จ่ายให้เป็นหน่วยที่เล็กที่สุด
			SELECT @v_fltConversionQuantity = ROUND(@in_fltQuantity * conversion_factor,@Round)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND uom_prompt = @in_vchUOMPrompt
			AND is_active = 'YES'
		END
	ELSE
		BEGIN
			--กรณีที่จ่ายมาเป็นหน่วยที่เล็กที่สุดแล้วไม่ต้องแปลง
			SET @v_fltConversionQuantity = ROUND(@in_fltQuantity,@Round)
		END
	
	---------------------------------------------
	-- Insert Inbound Master
	---------------------------------------------
	SELECT @v_vchInboundMasterID = inbound_order_master_id FROM t_wms_inbound_master 
	WHERE inbound_order_number = @v_vchIBOrderNumber 
	AND wh_master_id = @v_vchToWhMasterID

	IF @v_vchInboundMasterID IS NULL
		BEGIN
			SET @v_vchInboundMasterID = NEWID()
			INSERT INTO [dbo].[t_wms_inbound_master]
				   ([inbound_order_master_id]
				   ,[wh_master_id]
				   ,[inbound_order_number]
				   ,[owner_id]
				   ,[order_type]
				   ,[order_status]
				   ,[create_by]
				   ,[create_date]) 
			 VALUES
				   (@v_vchInboundMasterID
				   ,@v_vchToWhMasterID
				   ,@v_vchIBOrderNumber
				   ,@v_vchOwnerID
				   ,@v_vchIBOrderType
				   ,'OPEN'
				   ,@in_vchUserID
				   ,GETDATE())
		END
	
	---------------------------------------------
	--Get To wh item master id
	---------------------------------------------
	SELECT DISTINCT  @v_vchToWhItemMasterID = whItem.wh_item_master_id 
		,@v_vchToItemUomID = uom.item_uom_id
		,@v_vchToUOMPrompt = uom.uom_prompt
		,@v_vchGrade = item.grade
		,@v_fltPrice = item.price
	FROM t_wms_wh_item whItem
	LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	LEFT JOIn t_wms_item_uom uom ON (item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES')
	WHERE whItem.wh_master_id = @v_vchToWhMasterID
	AND owner_id = @v_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	
	IF (@v_vchToWhItemMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-ITEM-NUMBER-NOT-EXIST'
			GOTO EXIT_LABEL;
		END

	---------------------------------------------
	-- Insert/Update Inbound Detail
	---------------------------------------------
	SELECT @v_vchInboundDetailID = inbound_order_detail_id
	FROM t_wms_inbound_detail 
	WHERE inbound_order_master_id = @v_vchInboundMasterID
	AND wh_item_master_id = @v_vchToWhItemMasterID
	AND default_item_status = @in_vchDefaultItemStatus
	AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	
	IF (@v_vchInboundDetailID IS NULL)
		BEGIN
			-----------------------------------------
			--Get Line number
			-----------------------------------------
			SELECT @v_vchLineNumber = max(line_number) FROM t_wms_inbound_detail 
			WHERE inbound_order_master_id = @v_vchInboundMasterID
			If (@v_vchLineNumber IS NULL)
				BEGIN SET @v_vchLineNumber = '00001'; END
			ELSE
				BEGIN SET @v_vchLineNumber = Right('0000' + Convert(NVARCHAR,@v_vchLineNumber + 1),5); END	

			SET @v_vchInboundDetailID = NEWID()
			INSERT INTO [dbo].[t_wms_inbound_detail]
				   ([inbound_order_detail_id]
				   ,[inbound_order_master_id]
				   ,[wh_item_master_id]
				   ,[line_number]
				   ,[quantity_order]
				   ,[quantity_receive]
				   ,[item_uom_id]
				   ,[item_status]
				   ,[lpn]
				   ,[default_item_status]
				   ,[price]
				   ,[grade]
				   ,[over_receipt_allowed]
				   ,[source_of_record]
				   ,[lot_number]
				   ,[expiry_date]
				   ,[serial_number]
				   ,[attribute1]
				   ,[attribute2]
				   ,[attribute3]
				   ,[attribute4]
				   ,[attribute5]
				   ,[create_by]
				   ,[create_date])
			 VALUES
				   (@v_vchInboundDetailID
				   ,@v_vchInboundMasterID
				   ,@v_vchToWhItemMasterID
				   ,@v_vchLineNumber
				   ,ROUND(@v_fltConversionQuantity,@Round)
				   ,0
				   ,@v_vchToItemUomID
				   ,'NEW'
				   ,@in_vchLPN
				   ,@in_vchDefaultItemStatus
				   ,@v_fltPrice
				   ,(CASE ISNULL(@v_vchGrade,'') WHEN '' THEN NULL ELSE @v_vchGrade END)
				   ,'NO'
				   ,'AUTO_INSERT_IB'
				   ,(CASE ISNULL(@in_vchLotNumber,'') WHEN '' THEN  NULL ELSE @in_vchLotNumber END)
				   ,(CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
				   ,(CASE ISNULL(@in_vchSerialNumber,'') WHEN '' THEN NULL ELSE @in_vchSerialNumber END)
				   ,(CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END)
				   ,(CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END)
				   ,(CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END)
				   ,(CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END)
				   ,(CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END)
				   ,@in_vchUserID
				   ,GETDATE())
		END
	ELSE
		BEGIN
			UPDATE t_wms_inbound_detail SET quantity_order = ROUND(quantity_order + @in_fltQuantity,@Round)
				,update_by = @in_vchUserID
				,update_date = GETDATE()
			WHERE inbound_order_detail_id = @v_vchInboundDetailID
		END

	----Comment ไม่ต้อง Auto รับ
	------------------------------------------------------
	---- Get Partial Receipt Number
	------------------------------------------------------
	--SELECT @v_nCount = COUNT(receipt_header_id)
	--FROM t_wms_receipt_header 
	--WHERE inbound_order_master_id = @v_vchInboundMasterID
	--AND receipt_status = 'OPEN'

	--IF @v_nCount = 0
	--	BEGIN
	--		IF (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_GENERATE_RECEIPT_NUMBER') = 'YES'
	--			BEGIN
	--				EXEC usp_pda_inbound_generate_receipt_number @in_vchOrderNumber,@v_vchToWhMasterID,@in_vchUserID,@v_vchReceiptNumber OUTPUT
	--			END
	--		ELSE
	--			BEGIN
	--				SET @out_vchErrorCode = 'INFO-RECEIPT-NUMBER-NOT-EXIST'
	--				GOTO EXIT_LABEL;
	--			END
	--	END
	--ELSE
	--	BEGIN
	--		SELECT TOP 1 @v_vchReceiptNumber = receipt_number
	--		FROM t_wms_receipt_header 
	--		WHERE inbound_order_master_id = @v_vchInboundMasterID
	--		AND receipt_status = 'OPEN'
	--	END

	------------------------------------------------------
	---- Get Location Receipt
	------------------------------------------------------
	--SELECT top 1 @v_vchToLocation = location FROM t_wms_location 
	--WHERE loc_type = 'RSTG' 
	--AND wh_master_id = @v_vchToWhMasterID 
	--AND is_active = 'YES'
	--AND lpn_controlled = @v_vchLPNControl

	------------------------------------------------------
	---- Receipt Item
	------------------------------------------------------
	--EXEC usp_inbound_update_receive_qty @in_vchApplicationID  = @in_vchApplicationID
	--							  , @in_vchWarehouse		  = @v_vchToWhID
	--							  , @in_vchDeviceID		      = @in_vchDeviceID	
	--							  , @in_vchUserID			  = @in_vchUserID	
	--							  , @in_vchOrderNumber		  = @in_vchOrderNumber
	--							  , @in_vchItemNumber		  = @in_vchItemNumber
	--							  , @in_fltQuantity		      = @v_fltConversionQuantity
	--							  , @in_vchUOMPrompt		  = @v_vchToUOMPrompt
	--							  , @in_vchLocation           = @v_vchToLocation
	--							  , @in_vchLot				  = @in_vchLotNumber
	--							  , @in_vchExpiryDate		  = @in_vchExpiryDate
	--							  , @in_vchSerial			  = @in_vchSerialNumber
	--							  , @in_vchParentLPN		  = @in_vchParentLPN
	--							  , @in_vchLPN				  = @in_vchLPN
	--							  , @in_vchReasonCode		  = NULL
	--							  , @in_vchReceiptNumber	  = @v_vchReceiptNumber
	--							  , @in_vchReceiptItemStatus  = @in_vchDefaultItemStatus
	--							  , @out_ErrorCode			  = @out_vchErrorCode  OUTPUT
	--							  , @out_ErrorMessage		  = @out_vchErrorMsg   OUTPUT
		
	RETURN;

	---------------------------------------------
	-- Exit the Process to get resource
	---------------------------------------------
	EXIT_LABEL:
		IF (@out_vchErrorCode IS NOT NULL)
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')			

END


