/****** Object:  StoredProcedure [dbo].[usp_inbound_save_image]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_save_image]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundOrderNumber NVARCHAR(50),
	@in_byteImage			Image,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
AS
BEGIN 
	DECLARE @v_vchInboundMasterID UNIQUEIDENTIFIER = NULL 

	--------------------------------------------------------------------
	-- Check Inbound Order Number in System?
	--------------------------------------------------------------------
	SELECT TOP 1 @v_vchInboundMasterID = ibMS.inbound_order_master_id 
	FROM t_wms_inbound_master ibMS 
	WHERE ibMS.inbound_order_number = @in_vchInboundOrderNumber
	AND ibMS.wh_master_id = @in_vchWhMasterID
	IF (@v_vchInboundMasterID IS NULL)
		BEGIN
			SET @out_vchErrorCode = 'INFO-INBOUND-NOT-EXIST'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			RETURN
		END
	 
	INSERT INTO [dbo].[t_wms_inbound_image]
           ([image_id]
           ,[inbound_order_master_id]
           ,[image]
           ,[create_by]
           ,[create_date])
     VALUES
           (NEWID()
           ,@v_vchInboundMasterID
           ,@in_byteImage
           ,@in_vchUserID
           ,GETDATE())

	SET @out_vchNextScreen = 'INBOUND_ORDER'
	RETURN;

END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_update_packing_receipt_pack_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_update_packing_receipt_pack_qty]
	@in_vchApplicationID     VARCHAR(40) = NULL,
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25),
	@in_vchWhMasterID	     UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID   UNIQUEIDENTIFIER = NULL,
	@in_vchInboundPackMasterID UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID    UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber	     NVARCHAR(50) = NULL, 
	@in_dtMfgDate			 DATE = NULL,
	@in_vchExpiryDate		 NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd
	@in_vchAttribute1		 NVARCHAR(100) = NULL,
	@in_vchAttribute2		 NVARCHAR(100) = NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchSerialNumber		 NVARCHAR(100) = NULL,	
	@in_fltQuantity			 FLOAT,
	@in_vchItemUomID		 UNIQUEIDENTIFIER,
	@out_ErrorCode			 NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		 NVARCHAR(500) OUTPUT 
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON; 
	DECLARE @c_vchObjName				NVARCHAR(50) = 'usp_inbound_packing_update_pack_qty', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(100),
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtProcessDateTime		DATETIME, 
			@v_vchBeginTrans			BIT = 0,
			@v_dtStartTranDate			DATETIME = GETDATE(),
			@Round						INT,
			@v_nCount					INT = 0,

			@v_vchWarehouse				NVARCHAR(25),
			@v_vchInboundNumber			NVARCHAR(50), 
			@v_vchOrderStatus			NVARCHAR(25),
			@v_vchOrderType				NVARCHAR(25),
			@v_vchPackListNumber		NVARCHAR(50),
			@v_vchPackListStatus		NVARCHAR(10),
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50),
			@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50),
			@v_vchLotControl			VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchSerialControl			VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5),
		 
			@v_vchInboundOrderDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber			NVARCHAR(10),
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchInputUomPrompt		NVARCHAR(40),
			@v_vchIsPrimaryUOM			NVARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltOrderQty				FLOAT,
			@v_fltPackQty				FLOAT,
			@v_fltQtyOverReceipt		FLOAT,		--จำนวนที่สามารถรับเกินได้
			@v_fltBaseInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว
			@v_fltCalInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว (สำหรับในลูป)
			@v_fltCalQuantity			FLOAT,		--จำนวนที่จะนำไป Save ในแต่ละ Line Detail
			
			@v_fltAfterInvQuantity		FLOAT,
			@v_vchOverRecAllowed		VARCHAR(3) = 'NO',
			@v_fltOverRecPercentage		FLOAT

	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SET @in_fltQuantity = ROUND(@in_fltQuantity,@Round)

	BEGIN TRY
		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR(8),CONVERT(DATE,@in_vchExpiryDate),112)
		ELSE
			SET @in_vchExpiryDate = NULL

		-- Get and check warehouse
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (@v_vchWarehouse IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-- Get and check order status
		SELECT TOP 1 @v_vchInboundNumber = ibMS.inbound_order_number
			,@v_vchOrderStatus = ibMS.order_status
			,@v_vchOrderType = ibMS.order_type
			,@v_vchOwnerID = ibMS.owner_id
			,@v_vchOwnerCode = own.owner_code 
			,@v_vchCustomerID = ibMS.customer_id 
		FROM t_wms_inbound_master ibMS
		INNER JOIN t_wms_owner own on ibMS.owner_id = own.owner_id
		WHERE ibMS.wh_master_id = @in_vchWhMasterID 
		AND ibMS.inbound_order_master_id = @in_vchInboundMasterID
		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		--Get wh_item_master_id
		SET @v_vchItemMasterID = NULL
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-- Get and check item
		SELECT TOP 1 @v_vchItemMasterID = it.item_master_id
			, @v_vchItemNumber = it.item_number
			, @v_vchLotControl = it.lot_control
			, @v_vchExpiryDateControl = it.expiry_date_control
			, @v_vchSerialControl = it.sn_control
			, @v_vchAttribute1Control = it.attribute1_control
			, @v_vchAttribute2Control = it.attribute2_control
			, @v_vchAttribute3Control = it.attribute3_control
			, @v_vchAttribute4Control = it.attribute4_control
			, @v_vchAttribute5Control = it.attribute5_control
		FROM t_wms_item it
		WHERE it.item_master_id = @v_vchItemMasterID
		AND it.owner_id = @v_vchOwnerID
		AND it.is_active = 'YES'

		--Check Item in Plan
		IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @IN_vchWhItemMasterID)
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchSerialNumber)
				GOTO WRITE_PROC;
			END

		--Check กรณีที่มีการกำหนด Lot ใน Plan
		IF @v_vchLotControl = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.lot_number,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		   ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate lot number in Plan						 
						---------------------------------------------------
						IF @in_vchLotNumber NOT IN (SELECT DISTINCT lot_number FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(lot_number,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchLotNumber = NULL
			END

		--Check กรณีที่มีการกำหนด Exp. ใน Plan
		IF @v_vchExpiryDateControl = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.expiry_date,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																						WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																						WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																						ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Expiry Date in Plan						 
						---------------------------------------------------
						IF @in_vchExpiryDate NOT IN (SELECT DISTINCT expiry_date FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(expiry_date,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END

				--ถ้าวันที่ MFG Date กำหนดมา ต้องตรวจสอบใน Inventory ถ้าของ เดียวกัน exp เดียวกัน mfg date ต้องตรงกัน
				IF @in_dtMfgDate IS NOT NULL
					BEGIN
						DECLARE @v_dtCheckMfgDate DATE = NULL
						SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @in_vchWhMasterID 
						AND owner_id = @v_vchOwnerID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
						
						IF @in_dtMfgDate <> @v_dtCheckMfgDate
							BEGIN
								SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
			END
		ELSE
			BEGIN
				SET @in_vchExpiryDate = NULL
			END

		--Check กรณีที่มีการกำหนด Attr1. ใน Plan
		IF @v_vchAttribute1Control = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.attribute1,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																			WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																			WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																			ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Attribute1 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute1 NOT IN (SELECT DISTINCT attribute1 FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(attribute1,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-ATTRIBUTE1-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute1 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr2. ใน Plan
		IF @v_vchAttribute2Control = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.attribute2,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		   ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Attribute2 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute2 NOT IN (SELECT DISTINCT attribute2 FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(attribute2,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute2 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr3. ใน Plan
		IF @v_vchAttribute3Control = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.attribute3,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		   ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Attribute3 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute3 NOT IN (SELECT DISTINCT attribute3 FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(attribute3,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-ATTRIBUTE3-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute3 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr4. ใน Plan
		IF @v_vchAttribute4Control = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.attribute4,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		   ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Attribute4 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute4 NOT IN (SELECT DISTINCT attribute4 FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(attribute4,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-ATTRIBUTE4-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute4 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr5. ใน Plan
		IF @v_vchAttribute5Control = 'FULL'
			BEGIN
				IF ('') NOT IN (SELECT ISNULL(ibDT.attribute5,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																					     WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																					     WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																					     ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate Attribute5 in Plan
						---------------------------------------------------
						IF @in_vchAttribute5 NOT IN (SELECT DISTINCT attribute5 FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(attribute5,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-ATTRIBUTE5-NOT-EXIST';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute5 = NULL
			END
		
		--Check Serial
		IF @v_vchSerialControl = 'FULL'
			BEGIN
				--------------------------------------------------------------------
				-- Check Duplicate Serial Number in inventory data
				-------------------------------------------------------------------- 
				IF EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
							LEFT JOIN (SELECT invAttr.inventory_id
											,invAttr.attribute_group_id
											,invAttr.attribute_value	AS serial_number
										FROM t_wms_inventory_attribute_type invType
										INNER JOIN t_wms_inventory_attribute invAttr ON invType.inv_attribute_type_id = invAttr.inv_attribute_type_id
										WHERE invType.inv_attribute_type = 'SERIAL'
									   ) invSN ON invSN.inventory_id = inv.inventory_id AND invSN.attribute_group_id = inv.attribute_group_id
							WHERE inv.wh_master_id = @in_vchWhMasterID
							AND inv.wh_item_master_id = @in_vchWhItemMasterID
							AND invSN.serial_number = @in_vchSerialNumber
							AND inv.owner_id = @v_vchOwnerID)
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				-------------------------------------------------------------------- 
				--Check serial number in plan
				-------------------------------------------------------------------- 
				IF ('') NOT IN (SELECT ISNULL(ibDT.serial_number,'') FROM t_wms_inbound_detail ibDT
								LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id					
								WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID 
								AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
								AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		   WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		   ELSE ROUND(ibDT.quantity_order,@Round) END)) 
					BEGIN
						---------------------------------------------------
						-- Validate serial number in Plan
						---------------------------------------------------
						IF @in_vchSerialNumber NOT IN (SELECT DISTINCT serial_number FROM t_wms_inbound_detail 
													WHERE inbound_order_master_id = @in_vchInboundMasterID 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND (ISNULL(serial_number,'') <> ''))
							BEGIN
								SET @out_ErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END		
					END 

				--------------------------------------------------------------------
				-- Check Duplicate Serial Number in Item Master, Item cross ref
				--------------------------------------------------------------------
				IF EXISTS (SELECT item.item_master_id FROM t_wms_item item
							LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
							WHERE (item.item_number = @in_vchSerialNumber OR cref.alternate_item_number = @in_vchSerialNumber))
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-ITEM-MASTER'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		ELSE
			BEGIN
				SET @in_vchSerialNumber = NULL
			END
	
		--------------------------------------------------------------
		-- ตรวจสอบแผน ดึงค่าข้อมูลจากแผน กรณีกำหนด Lot_number, Expiry_date
		-- NONE = Where Lot Exp. = ค่าว่าง
		-- LOT = Where เฉพาะ Lot
		-- LOT_EXP = Where ทั้ง Lot Exp.
		--------------------------------------------------------------
		SET @v_nCount = 0
		SELECT @v_nCount = COUNT(ibDT.inbound_order_detail_id)
			,@v_fltOrderQty = SUM(ibDT.quantity_order)
			,@v_fltPackQty = SUM(packDT.quantity_pack)
			,@v_fltQtyOverReceipt = SUM((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0)/100)) 
		FROM t_wms_inbound_detail ibDT
		LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id
		WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
 		AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(ibDT.lot_number,'') = ISNULL(@in_vchLotNumber,'') 
		AND ISNULL(ibDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		-- iKritt add for attribute check 
		AND ISNULL(ibDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(ibDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(ibDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(ibDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(ibDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
		AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) <= (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(ibDT.quantity_order,@Round) END)
		IF (@v_nCount = 0)
			BEGIN
				SELECT @v_fltOrderQty = SUM(ibDT.quantity_order)
					,@v_fltPackQty = SUM(packDT.quantity_pack)
					,@v_fltQtyOverReceipt = SUM((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0)/100)) 
				FROM t_wms_inbound_detail ibDT
				LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id
				WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
				AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
				AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) <= (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																			WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																			WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																			ELSE ROUND(ibDT.quantity_order,@Round) END)
 			END

		--Get & Check Item UOM
		SET @v_vchBaseItemUomID = NULL
		SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchInputUomPrompt = uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUomID
		and is_active = 'YES'		
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC
			End

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt 
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END

		SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
		SET @v_fltCalInputQuantity  = @v_fltBaseInputQuantity;

		-- ถ้าจำนวน Receipt + input qty > จำนวนที่แผน + จำนวน Over receipt
		IF EXISTS (SELECT TOP 1 inbound_order_detail_id FROM t_wms_inbound_detail  WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0)
			BEGIN
				--ถ้ามี Over receipt และไม่กำหนด % ไม่ต้อง check qty plan
				GOTO NEXT_STEP;
			END

		IF ((@v_fltPackQty + @v_fltBaseInputQuantity) > (@v_fltOrderQty + @v_fltQtyOverReceipt))
			BEGIN
				SET @out_ErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

NEXT_STEP:
	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		
		-- Check Pack list number
		SELECT TOP 1 @v_vchPackListNumber = pack_list_number
			,@v_vchPackListStatus = pack_list_status
		FROM t_wms_inbound_pack_master 
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND inbound_pack_master_id = @in_vchInboundPackMasterID
		IF (ISNULL(@v_vchPackListNumber,'') = '')
			BEGIN
				SET @out_ErrorCode = 'NOT_FOUND_PACK_LIST_NUMBER';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchPackListNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		---------------------------------------------------------------
		-- ตรวจสอบเลข Pack list Number > Status = OPEN?
		---------------------------------------------------------------
		IF (@v_vchPackListStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'PACK_LIST_NUMBER_IS_CLOSE'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchPackListNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
 
		IF (@in_vchInboundPackMasterID IS NULL)
			BEGIN
				SET @in_vchInboundPackMasterID = NEWID()
				INSERT INTO [dbo].[t_wms_inbound_pack_master]
						([inbound_pack_master_id]
						,[inbound_order_master_id]
						,[pack_list_number]
						,[pack_list_status]
						,[create_by]
						,[create_date] )
					VALUES
						(@in_vchInboundPackMasterID
						,@in_vchInboundMasterID
						,@v_vchPackListNumber
						,'OPEN'
						,@in_vchUserID
						,GETDATE())
			END

		--SET ให้เป็น Qty ก่อน receive
		SET @v_fltAfterInvQuantity = (@v_fltAfterInvQuantity - @in_fltQuantity) 
		IF (@v_nCount = 0)
			BEGIN
				DECLARE cursorInboundDetail CURSOR FOR
				SELECT ibDT.inbound_order_detail_id
					,ROUND((ibDT.quantity_order + (ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0)/100)),@Round)
					,packDT.quantity_pack
					,ibDT.line_number
					,ibDT.over_receipt_allowed
					,ibDT.over_receipt_percentage
				FROM t_wms_inbound_detail ibDT
				LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id
				WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
 				AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
				AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		ELSE ROUND(ibDT.quantity_order,@Round) END)
				ORDER BY ibDT.line_number
			END
		ELSE
			BEGIN
				DECLARE cursorInboundDetail CURSOR FOR
				SELECT ibDT.inbound_order_detail_id
					,ROUND((ibDT.quantity_order + (ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0)/100)),@Round)
					,packDT.quantity_pack
					,ibDT.line_number
					,ibDT.over_receipt_allowed
					,ibDT.over_receipt_percentage
				FROM t_wms_inbound_detail ibDT
				LEFT JOIN (SELECT inbound_order_detail_id, SUM(quantity_pack) AS quantity_pack FROM t_wms_inbound_pack_detail GROUP BY inbound_order_detail_id) packDT on ibDT.inbound_order_detail_id = packDT.inbound_order_detail_id
				WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
 				AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
				AND ISNULL(ibDT.lot_number,'') = ISNULL(@in_vchLotNumber,'') 
				AND ISNULL(ibDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				-- iKritt add for attribute check 
				AND ISNULL(ibDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(ibDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(ibDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(ibDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(ibDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND ROUND(ISNULL(packDT.quantity_pack,0),@Round) < (CASE WHEN ibDT.over_receipt_allowed = 'NO' THEN ROUND(ibDT.quantity_order,@Round)
																		WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(packDT.quantity_pack,0) + 1,@Round)	--unlimit receipt
																		WHEN ibDT.over_receipt_allowed = 'YES' AND ISNULL(ibDT.over_receipt_percentage,0) > 0 THEN ROUND(ibDT.quantity_order + ((ibDT.quantity_order * ISNULL(ibDT.over_receipt_percentage,0))/100),@Round)
																		ELSE ROUND(ibDT.quantity_order,@Round) END)
				ORDER BY ibDT.line_number
			END

		OPEN cursorInboundDetail;
		FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltPackQty, @v_vchLineNumber,@v_vchOverRecAllowed,@v_fltOverRecPercentage
		WHILE @@FETCH_STATUS = 0
			BEGIN
				--คำนวณยอดที่สามารถรับได้ในแต่ละ Line Inbound Detail
				IF @v_vchOverRecAllowed = 'YES' AND ISNULL(@v_fltOverRecPercentage,0) = 0
					BEGIN
						SET @v_fltCalQuantity = @v_fltCalInputQuantity
					END
				ELSE	
					BEGIN
						IF ROUND(@v_fltOrderQty - @v_fltPackQty,@Round) <= @v_fltCalInputQuantity
							BEGIN
								SET @v_fltCalQuantity = ROUND(@v_fltOrderQty - @v_fltPackQty,@round)
							END
						ELSE
							BEGIN
								SET @v_fltCalQuantity = @v_fltCalInputQuantity
							END
					END

				--เนื่องจากเป็น multi line item และเวลา receive และรับพร้อม 2 line จะต้องคำนวณ after qty ใหม่ เพราะ inv qty คือสิ่งที่รวมทั้งหมดมาแล้ว
				SET @v_fltAfterInvQuantity = @v_fltAfterInvQuantity + @v_fltCalQuantity 

				INSERT INTO [dbo].[t_wms_inbound_pack_detail]
						   ([inbound_pack_detail_id]
						   ,[inbound_pack_master_id]
						   ,[inbound_order_detail_id]
						   ,[wh_item_master_id]
						   ,[quantity_pack]
						   ,[item_uom_id]
						   ,[lot_number]
						   ,[expiry_date]
						   ,[serial_number]
						   ,[attribute1]
						   ,[attribute2]
						   ,[attribute3]
						   ,[attribute4]
						   ,[attribute5]
						   ,[mfg_date]
						   ,[pack_date]
						   ,[create_by]
						   ,[create_date] )
					 VALUES
						   (NEWID()
						   ,@in_vchInboundPackMasterID
						   ,@v_vchInboundOrderDetailID
						   ,@in_vchWhItemMasterID
						   ,ROUND(@v_fltCalQuantity,@Round)
						   ,@v_vchBaseItemUomID
						   , CASE ISNULL(@in_vchLotNumber,'') WHEN '' THEN NULL ELSE @in_vchLotNumber END
						   , CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END
						   , CASE ISNULL(@in_vchSerialNumber,'') WHEN '' THEN NULL ELSE @in_vchSerialNumber END
						   , CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END
						   , CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END
						   , CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END
						   , CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END
						   , CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END
						   ,@in_dtMfgDate
						   ,GETDATE()
						   ,@in_vchUserID
						   ,GETDATE()) 
				 
				-----------------------------------------------------------
				-- Write Transaction Log Receipt Detail
				-----------------------------------------------------------
				INSERT INTO t_com_tran_log
					(app_id
					, tran_type
					, sub_tran_type
					, [app_name]
					, [description]
					, start_tran_datetime
					, end_tran_datetime
					, to_warehouse
					, to_location
					, to_owner
					, item_number
					, quantity
					, quantity_uom
					, after_quantity
					, after_quantity_uom
					, after_lot_number
					, after_expiry_date
					, serial_number
					, [user_id]
					, order_number
					, line_number

					-- Add for attibute
					, [after_attribute1]
					, [after_attribute2]
					, [after_attribute3]
					, [after_attribute4]
					, [after_attribute5]
					, control_number 
					, mfg_date
					, input_quantity
					, input_uom
					, device
					, create_by)
				VALUES
					( @in_vchApplicationID
					, 'IO_PACKING'
					, 'INBOUND_PACK'
					, @v_vchApplicationName
					, 'Inbound Packing'
					, @v_dtStartTranDate
					, GETDATE()
					, @v_vchWarehouse
					, NULL
					, @v_vchOwnerCode
					, @v_vchItemNumber
					, @v_fltCalQuantity
					, @v_vchBaseUomPrompt
					, @v_fltAfterInvQuantity
					, @v_vchBaseUomPrompt
					, @in_vchLotNumber
					, @in_vchExpiryDate
					, @in_vchSerialNumber
					, @in_vchUserID 
					, @v_vchInboundNumber
					, @v_vchLineNumber

					-- Add for attibute
					, @in_vchAttribute1
					, @in_vchAttribute2
					, @in_vchAttribute3
					, @in_vchAttribute4
					, @in_vchAttribute5
					, @v_vchPackListNumber
					, @in_dtMfgDate
					, @in_fltQuantity		   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @v_vchInputUomPrompt	   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @in_vchDeviceID
					, @in_vchUserID)

				SET @v_fltCalInputQuantity = @v_fltCalInputQuantity - @v_fltCalQuantity
				IF @v_fltCalInputQuantity = 0
					BREAK;
				FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltPackQty, @v_vchLineNumber,@v_vchOverRecAllowed,@v_fltOverRecPercentage
			END
		CLOSE cursorInboundDetail;
		DEALLOCATE cursorInboundDetail;
  

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;

			IF CURSOR_STATUS('global','cursorInboundDetail')>=-1
			BEGIN
				CLOSE cursorInboundDetail;
				DEALLOCATE cursorInboundDetail;
			END
			
			SET @v_dtProcessDateTime = GETDATE();
			SET @v_vchProcessData1 = 'Inbound Number ' + @v_vchInboundNumber;
			SET @v_vchProcessData2 = 'Pack list number ' + @v_vchPackListNumber;
			SET @v_vchProcessData3 = 'Item number ' + @v_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END

    END TRY
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION;
			
		IF CURSOR_STATUS('global','cursorInboundDetail')>=-1
			BEGIN
				CLOSE cursorInboundDetail;
				DEALLOCATE cursorInboundDetail;
			END

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData1 = 'Inbound Number ' + @v_vchInboundNumber;
		SET @v_vchProcessData2 = 'Pack list number ' + @v_vchPackListNumber;
		SET @v_vchProcessData3 = 'Item number ' + @v_vchItemNumber;

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
    END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_update_receive_all]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_update_receive_all]
(
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchLocationID		UNIQUEIDENTIFIER,		--Receive location
	@in_vchLPN				NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON; 
	DECLARE @Round					 INT,
			@v_vchBeginTrans		 BIT = 0, 
			@v_vchApplicationName	 NVARCHAR(100),
			@v_vchStartTime			 DATETIME = GETDATE(),
			@v_dtProcessDateTime	 DATETIME,
			@c_vchObjName			 NVARCHAR(50) = '[usp_inbound_update_receive_all]',
			@v_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
			@v_vchWarehouse			 NVARCHAR(25) = NULL,
			@v_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode			 NVARCHAR(50),
			@v_vchInboundOrderNumber NVARCHAR(50) = NULL,
			@v_vchOrderStatus		 NVARCHAR(10) = NULL,
			@v_vchOrderType			 NVARCHAR(30) = NULL,
			@v_vchCustomerID		 UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptHeaderID	 UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptNumber		 NVARCHAR(50) = NULL, 
			@v_vchLocation			 NVARCHAR(50) = NULL,
			@v_vchLPNControl		 NVARCHAR(3)  = NULL,

			@v_vchInboundDetailID	 UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber		 NVARCHAR(10),
			@v_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber         NVARCHAR(50) = NULL, 
			@v_vchItemUomID			 UNIQUEIDENTIFIER,
			@v_vchBaseUom			 NVARCHAR(20),
			@v_fltQtyReceive		 FLOAT = NULL,
			@v_vchLPN				 NVARCHAR(25) = NULL,
			@v_vchLotNumber			 NVARCHAR(50) = NULL,
			@v_vchExpiryDate		 NVARCHAR(50) = NULL,
			@v_vchSerialNumber		 NVARCHAR(50) = NULL,
			@v_vchAttribute1		 NVARCHAR(100) = NULL,
			@v_vchAttribute2		 NVARCHAR(100) = NULL,
			@v_vchAttribute3		 NVARCHAR(100) = NULL,
			@v_vchAttribute4		 NVARCHAR(100) = NULL,
			@v_vchAttribute5		 NVARCHAR(100) = NULL,
			@v_vchInvStatusID		 UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus			 NVARCHAR(50) = NULL,
			@v_dtReceiveDate		 DATE = GETDATE(),
			@v_dtMfgDate			 DATE = NULL,
			@v_fltAfterInvQuantity	 FLOAT = 0

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT

	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_REQUIRE_MFG_DATE' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @v_dtMfgDate = GETDATE()
		END
	ELSE
		BEGIN
			SET @v_dtMfgDate = NULL
		END

	----------------------------------------------
	--Check Parent LPN Control
	----------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_ErrorCode = 'AUTO_RECEIPT_CANNOT_CONTROL_PARENT_LPN';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	----------------------------------------------
	--Check Inbound Order
	----------------------------------------------
	SELECT TOP 1 @v_vchInboundOrderNumber = ibMS.inbound_order_number
		,@v_vchWhMasterID = ibMS.wh_master_id
		,@v_vchWarehouse = ibMS.wh_id
		,@v_vchOrderStatus = ibMS.order_status
		,@v_vchOrderType = ibMS.order_type
		,@v_vchOwnerID = own.owner_id
		,@v_vchOwnerCode = own.owner_code
		,@v_vchCustomerID = ibMS.customer_id 
	FROM t_wms_inbound_master ibMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID

	IF (ISNULL(@v_vchInboundOrderNumber,'') = '')
		BEGIN
			SET @out_ErrorCode = 'INBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	IF (@v_vchOrderStatus = 'CLOSE')
		BEGIN
			SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;				
		END

PRINT 'CHECK LOCATION'
		----------------------------------------------
		--Check Location
		----------------------------------------------
		SELECT TOP 1 @v_vchLocation = location
			, @v_vchLPNControl = lpn_controlled
		FROM t_wms_location WITH (NOLOCK)
		WHERE location_id = @in_vchLocationID
		AND is_active = 'YES'

		IF ISNULL(@v_vchLocation,'') = ''
		BEGIN 
			SET @out_ErrorCode = 'INFO-LOCATION-NOT-EXIST';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

		IF @v_vchLPNControl = 'YES' AND ISNULL(@in_vchLPN,'') = ''
		BEGIN
			SET @out_ErrorCode = 'LPN_IS_EMPTY';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

PRINT 'CHECK ITEM CONTROL IN ORDER'
		-------------------------------------------------------------------------------
		--Validate Check Data
		--Auto Receipt จะต้องกำหนดข้อมูล lot,exp,sn,attr1-5 ให้ครบ ถ้า item นั้น control
		-------------------------------------------------------------------------------
		IF EXISTS (SELECT inbound_order_detail_id
				   FROM (SELECT ibDT.inbound_order_detail_id
							,ibDT.lpn
							,ibDT.lot_number
							,ibDT.expiry_date
							,ibDT.serial_number
							,ibDT.attribute1
							,ibDT.attribute2
							,ibDT.attribute3
							,ibDT.attribute4
							,ibDT.attribute5
							,(CASE WHEN (item.lot_control = 'FULL' AND ISNULL(ibDT.lot_number,'') = '')
									  OR (item.expiry_date_control = 'FULL' AND ISNULL(ibDT.expiry_date,'') = '')	
									  OR (item.sn_control = 'FULL' AND ISNULL(ibDT.serial_number,'') = '')
									  OR (item.attribute1_control = 'FULL' AND ISNULL(ibDT.attribute1,'') = '')
									  OR (item.attribute2_control = 'FULL' AND ISNULL(ibDT.attribute2,'') = '')
									  OR (item.attribute3_control = 'FULL' AND ISNULL(ibDT.attribute3,'') = '')
									  OR (item.attribute4_control = 'FULL' AND ISNULL(ibDT.attribute4,'') = '')
									  OR (item.attribute5_control = 'FULL' AND ISNULL(ibDT.attribute5,'') = '')
								   THEN 'ERROR' ELSE 'NORMAL' END) AS data_status
						 FROM t_wms_inbound_detail ibDT WITH (NOLOCK)
						 LEFT JOIN t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
						 LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
						 WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
					    ) InboundDT
					WHERE data_status = 'ERROR')
				BEGIN
					--Auto Receipt จะต้องกำหนดข้อมูลให้ครบจึงจะสามารถรับได้
					SET @out_ErrorCode = 'INBOUND_DATA_NOT_COMPLETE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;

	------------------------------------------------
	--SET Receipt Number
	------------------------------------------------
	SET @v_vchReceiptHeaderID = NULL
	SELECT TOP 1 @v_vchReceiptHeaderID = receipt_header_id 
	FROM t_wms_receipt_header WITH (NOLOCK)
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND receipt_status = 'OPEN'
	ORDER BY receipt_number DESC

	IF @v_vchReceiptHeaderID IS NULL
		BEGIN
			DECLARE	@v_vchLastReceiptNumber	 NVARCHAR(50) = NULL
			DECLARE @v_fltLastNumber		 FLOAT= 0
			DECLARE @v_fltNextNumber		 FLOAT= 0

			--GET LAST Receipt Number
			SELECT @v_fltLastNumber = CONVERT(FLOAT,RIGHT((MAX(receipt_number)),3)) FROM t_wms_receipt_header WITH (NOLOCK) WHERE inbound_order_master_id = @in_vchInboundMasterID 
			IF(@v_fltLastNumber IS NULL)
				BEGIN
					SET @v_fltLastNumber = 0
				END

			SET @v_fltNextNumber = @v_fltLastNumber + 1;
			SET	@v_vchReceiptNumber = @v_vchInboundOrderNumber + '-' +  RIGHT('000'+CONVERT(VARCHAR(20),@v_fltNextNumber),3)
			 
			SET @v_vchReceiptHeaderID = NEWID();
			--Insert Receipt Header
			INSERT INTO [dbo].[t_wms_receipt_header]
						([receipt_header_id]
						,[inbound_order_master_id]
						,[receipt_number]
						,[receipt_status]
						,[create_date]
						,[create_by])
					VALUES
						(@v_vchReceiptHeaderID
						,@in_vchInboundMasterID
						,@v_vchReceiptNumber
						,'OPEN'
						,GETDATE()
						,@in_vchUserID)
			 
		END
		 
	NEXT_RECEIPT_ITEM:
		SET @v_vchInboundDetailID = NULL
		SET @v_vchLineNumber = NULL
		SET @v_vchWhItemMasterID = NULL
		SET @v_vchItemMasterID = NULL
		SET @v_vchItemNumber    = NULL
		SET	@v_vchItemUomID    = NULL 	
		SET @v_vchBaseUom      = NULL
		SET @v_fltQtyReceive   = NULL
		SET @v_vchLPN		   = NULL
		SET @v_vchLotNumber	   = NULL
		SET @v_vchExpiryDate   = NULL
		SET @v_vchSerialNumber = NULL
		SET @v_vchAttribute1   = NULL
		SET @v_vchAttribute2   = NULL
		SET @v_vchAttribute3   = NULL
		SET @v_vchAttribute4   = NULL
		SET @v_vchAttribute5   = NULL
		SET @v_vchInvStatusID = NULL
		SET @v_vchInvStatus = NULL
		SET @v_fltAfterInvQuantity = 0

		SELECT TOP 1 @v_vchInboundDetailID = ibDT.inbound_order_detail_id
			,@v_vchLineNumber = ibDT.line_number
			,@v_vchWhItemMasterID = ibDT.wh_item_master_id
			,@v_vchItemMasterID = item.item_master_id
			,@v_vchItemNumber   = item.item_number
			,@v_fltQtyReceive	= ibDT.qty_for_receive
			,@v_vchItemUomID	= uom.item_uom_id
			,@v_vchBaseUom		= uom.uom
			,@v_vchLpn			= ibDT.lpn
			,@v_vchLotNumber	= ibDT.lot_number
			,@v_vchExpiryDate	= ibDT.expiry_date
			,@v_vchSerialNumber	= ibDT.serial_number
			,@v_vchAttribute1	= ibDT.attribute1
			,@v_vchAttribute2	= ibDT.attribute2
			,@v_vchAttribute3	= ibDT.attribute3
			,@v_vchAttribute4	= ibDT.attribute4
			,@v_vchAttribute5	= ibDT.attribute5
			,@v_vchInvStatusID = invST.inventory_status_id
			,@v_vchInvStatus   = invST.inv_status
		FROM (SELECT inbound_order_master_id
					,inbound_order_detail_id
					,line_number
					,wh_item_master_id
					,item_master_id
					,ROUND(ISNULL(quantity_order,0) - ISNULL(quantity_receive,0),@Round) AS qty_for_receive
					,lpn
					,lot_number
					,expiry_date
					,serial_number
					,attribute1
					,attribute2
					,attribute3
					,attribute4
					,attribute5
					,default_item_status
					,create_date
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND ISNULL(quantity_order,0) - ISNULL(quantity_receive,0) > 0
			   ) ibDT
		INNER JOIN t_wms_inventory_status invST on ibDT.default_item_status = invST.inv_status
		INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
		INNER JOIN (SELECT item_master_id
						,item_uom_id
						,uom
					 FROM t_wms_item_uom 
					 WHERE primary_uom = 'YES'
					 AND is_active = 'YES'
					) uom ON item.item_master_id = uom.item_master_id 
		ORDER BY ibDT.line_number
		IF @v_vchInboundDetailID IS NOT NULL
			BEGIN
				PRINT 'SAVE'
				
				--2024-09-27 : เพิ่มกรณีที่ Order Type in Rule จะให้รับเข้าด้วย Status Hold
				IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_RECEIVE_HOLD' AND is_active = 'YES') 
					BEGIN
						SELECT TOP 1 @v_vchInvStatus = inv_status 
							,@v_vchInvStatusID = inventory_status_id
						FROM t_wms_inventory_status 
						WHERE inv_status = 'HOLD'
						AND is_active = 'YES'
						IF (@v_vchInvStatus IS NULL)
							BEGIN
								SET @out_ErrorCode = 'STATUS_NOT_FOUND';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END

				--Manage Inventory
				EXEC usp_manage_inventory_control @in_vchApplicationID		= @in_vchApplicationID
												 ,@in_vchWhMasterID			= @v_vchWhMasterID
												 ,@in_vchWhID				= @v_vchWarehouse
												 ,@in_vchOwnerID			= @v_vchOwnerID
												 ,@in_vchInventoryType		= 'INVENTORY'
												 ,@in_vchLocationID			= @in_vchLocationID
												 ,@in_vchParentLPN			= NULL
												 ,@in_vchLPN				= @in_vchLPN
												 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
												 ,@in_vchItemMasterID		= @v_vchItemMasterID
												 ,@in_vchItemNumber			= @v_vchItemNumber
												 ,@in_fltQuantity			= @v_fltQtyReceive
												 ,@in_fltQtyAllocate		= 0
												 ,@in_fltQtyIncoming		= 0
												 ,@in_vchPrimaryItemUomID	= @v_vchItemUomID
												 ,@in_vchInvStatusID		= @v_vchInvStatusID
												 ,@in_vchLotNumber			= @v_vchLotNumber
												 ,@in_vchExpiryDate			= @v_vchExpiryDate
												 ,@in_vchSerialNumber		= @v_vchSerialNumber
												 ,@in_vchAttribute1			= @v_vchAttribute1
												 ,@in_vchAttribute2			= @v_vchAttribute2
												 ,@in_vchAttribute3			= @v_vchAttribute3
												 ,@in_vchAttribute4			= @v_vchAttribute4
												 ,@in_vchAttribute5			= @v_vchAttribute5
												 ,@in_dReceiveDate			= @v_dtReceiveDate
												 ,@in_dtMFGDate				= @v_dtMfgDate
												 ,@in_vchDeviceID			= @in_vchDeviceID
												 ,@in_vchUserID				= @in_vchUserID
												 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
												 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
												 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

				IF (@out_ErrorCode <> '0')
					GOTO WRITE_PROC;

				--UPDATE Quantity receipt >> t_wms_inbound_detail
				UPDATE t_wms_inbound_detail SET quantity_receive = ROUND(quantity_receive + @v_fltQtyReceive,@Round)
					,item_status = 'RECEIVING' 
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE inbound_order_detail_id = @v_vchInboundDetailID

				INSERT INTO t_wms_receipt_detail
				( receipt_header_id
					, inbound_order_detail_id
					, quantity_received
					, item_uom_id
					, receipt_item_status
					, location_received
					, lpn
					, parent_lpn
					, lot_number
					, expiry_date
					, serial_number
					, attribute1
					, attribute2
					, attribute3
					, attribute4
					, attribute5 
					, item_number
					, wh_item_master_id
					, inbound_order_number
					, inbound_order_master_id
					, receive_date
					, mfg_date
					, create_by)
				VALUES(@v_vchReceiptHeaderID
					, @v_vchInboundDetailID
					, ROUND(@v_fltQtyReceive,@Round)
					, @v_vchItemUomID
					, @V_vchInvStatus
					, @v_vchLocation
					, CASE ISNULL(@in_vchLPN,'') WHEN '' THEN NULL ELSE @in_vchLPN END
					, NULL
					, CASE ISNULL(@v_vchLotNumber,'') WHEN '' THEN NULL ELSE @v_vchLotNumber END
					, CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN NULL ELSE @v_vchExpiryDate END
					, CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN NULL ELSE @v_vchSerialNumber END
					, CASE ISNULL(@v_vchAttribute1,'') WHEN '' THEN NULL ELSE @v_vchAttribute1 END
					, CASE ISNULL(@v_vchAttribute2,'') WHEN '' THEN NULL ELSE @v_vchAttribute2 END
					, CASE ISNULL(@v_vchAttribute3,'') WHEN '' THEN NULL ELSE @v_vchAttribute3 END
					, CASE ISNULL(@v_vchAttribute4,'') WHEN '' THEN NULL ELSE @v_vchAttribute4 END
					, CASE ISNULL(@v_vchAttribute5,'') WHEN '' THEN NULL ELSE @v_vchAttribute5 END
					, @v_vchItemNumber
					, @v_vchWhItemMasterID
					, @v_vchInboundOrderNumber
					, @in_vchInboundMasterID
					, @v_dtReceiveDate
					, @v_dtMfgDate
					, @in_vchUserID)

				-- Insert to t_wms_return_lot for Modern Trade 2014-09-02
				IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RETURN_MODERN_TRADE' AND is_active = 'YES'))
					BEGIN
						IF NOT EXISTS(SELECT return_id FROM t_wms_return_lot 
										WHERE inbound_order_number = @v_vchInboundOrderNumber
										AND customer_id = @v_vchCustomerID 
										AND owner_id = @v_vchOwnerID 
										AND item_number = @v_vchItemNumber 
										AND lot_number = @v_vchLotNumber
										AND expiry_date = @v_vchExpiryDate)
							BEGIN
								INSERT INTO dbo.t_wms_return_lot
									(inbound_order_number
									, line_number
									, customer_id
									, owner_id
									, item_number
									, lot_number
									, expiry_date
									, create_by)
								VALUES
									(@v_vchInboundOrderNumber
									,@v_vchLineNumber
									,@v_vchCustomerID
									,@v_vchOwnerID
									,@v_vchItemNumber
									,@v_vchLotNumber
									,@v_vchExpiryDate
									,@in_vchUserID)
							END
					END

				-----------------------------------------------------------
				-- Write Transaction Log Receipt Detail
				-----------------------------------------------------------
				INSERT INTO t_com_tran_log
					(app_id
					, tran_type
					, sub_tran_type
					, [app_name]
					, [description]
					, start_tran_datetime
					, end_tran_datetime
					, to_warehouse
					, to_location
					, to_owner
					, item_number
					, quantity
					, quantity_uom
					, after_quantity
					, after_quantity_uom
					, after_lot_number
					, after_expiry_date
					, serial_number
					, [user_id] 
					, after_parent_lpn
					, after_lpn
					, after_status
					, order_number
					, line_number

					-- Add for attibute
					, [after_attribute1]
					, [after_attribute2]
					, [after_attribute3]
					, [after_attribute4]
					, [after_attribute5]
					, control_number
					, receive_date
					, mfg_date
					, input_quantity
					, input_uom
					, device
					, create_by)
				VALUES
					( @in_vchApplicationID
					, 'IO_RECEIPT'
					, 'RECEIPT'
					, @v_vchApplicationName
					, 'Receive item (Receipt All)'
					, @v_vchStartTime
					, GETDATE()
					, @v_vchWarehouse
					, @v_vchLocation
					, @v_vchOwnerCode
					, @v_vchItemNumber
					, @v_fltQtyReceive
					, @v_vchBaseUom
					, @v_fltAfterInvQuantity
					, @v_vchBaseUom
					, @v_vchLotNumber
					, @v_vchExpiryDate
					, @v_vchSerialNumber
					, @in_vchUserID
					, NULL
					, @in_vchLPN
					, @V_vchInvStatus
					, @v_vchInboundOrderNumber
					, @v_vchLineNumber

					-- Add for attibute
					, @v_vchAttribute1
					, @v_vchAttribute2
					, @v_vchAttribute3
					, @v_vchAttribute4
					, @v_vchAttribute5
					, @v_vchReceiptNumber
					, @v_dtReceiveDate
					, @v_dtMfgDate
					, @v_fltQtyReceive		   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @v_vchBaseUom			   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @in_vchDeviceID
					, @in_vchUserID)

				-----------------------------------------------------------
				-- add new 2014-02-10 check warranty
				-----------------------------------------------------------
				IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_WARRANTY' AND is_active = 'YES'))
					BEGIN
						IF (ISNULL(@v_vchSerialNumber,'') <> '')
							DECLARE @v_vchWarrantyID	VARCHAR(40)
							(SELECT TOP 1 @v_vchWarrantyID = warranty_id FROM t_mod_warranty WHERE wh_item_master_id = @v_vchWhItemMasterID AND serial_number = @@CONNECTIONS)
							IF (ISNULL(@v_vchWarrantyID,'') <> '')
								BEGIN
									UPDATE t_mod_warranty SET processing_status = 'Pending', warranty_status = 'Cancel' WHERE warranty_id = @v_vchWarrantyID
								END
					END

				EXEC usp_wms_dashboard_transaction @in_vchProcess		= 'IN'
												   ,@in_vchTransType	= 'RECEIVING'
												   ,@in_vchWhMasterID	= @v_vchWhMasterID
												   ,@in_vchOwnerID		= @v_vchOwnerID
												   ,@in_vchOwnerCode	= @v_vchOwnerCode
												   ,@in_vchLocationID	= @in_vchLocationID
												   ,@in_vchItemMasterID	= @v_vchItemMasterID
												   ,@in_vchInvStatusID	= @v_vchInvStatusID
												   ,@in_vchToWhMasterID = NULL
												   ,@in_vchToLocationID	= NULL
												   ,@in_vchToInvStatusID = NULL
												   ,@in_fltQuantity		= @v_fltQtyReceive
												   ,@in_vchUserID		= @in_vchUserID

				--ถ้ายังมีข้อมูลให้ทำการรับให้วนกลับไปรับต่อ
				IF EXISTS (SELECT ibDT.inbound_order_detail_id FROM t_wms_inbound_detail ibDT WHERE inbound_order_master_id = @in_vchInboundMasterID AND ISNULL(quantity_order,0) - ISNULL(quantity_receive,0) > 0)
					BEGIN
						GOTO NEXT_RECEIPT_ITEM;
					END
			END		

		-- Update Master Order Status 
		UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE inbound_order_master_id = @in_vchInboundMasterID

		COMMIT TRANSACTION;

		--เนื่องจากเป็น Receive All ดังนั้นจำนวนจะถูกรับทั้งหมด ไม่ต้อง check qty ซ้ำอีก
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_RECEIVE' AND is_active = 'YES') = 'NO')
			BEGIN
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_CLOSE_RECEIPT' AND is_active = 'YES') = 'YES')
					BEGIN
						DECLARE @v_vchCloseReceiptHeaderID UNIQUEIDENTIFIER = NULL
						DECLARE partial_cursor CURSOR FOR
							SELECT receipt_header_id FROM t_wms_receipt_header
							WHERE inbound_order_master_id = @in_vchInboundMasterID
							AND receipt_status = 'OPEN'
						OPEN partial_cursor
						FETCH NEXT FROM partial_cursor INTO @v_vchCloseReceiptHeaderID
				
						WHILE @@FETCH_STATUS = 0
							BEGIN
								EXEC [usp_close_partial_receive]
										@in_vchApplicationID	= @in_vchApplicationID,
										@in_vchDevice			= @in_vchDeviceID,
										@in_vchWhMasterID		= @v_vchWhMasterID,
										@in_vchInboundMasterID	= @in_vchInboundMasterID,
										@in_vchReceiptHeaderID	= @v_vchReceiptHeaderID,
										@in_vchCloseBy			= @in_vchUserID,
										@out_ErrorCode			= @out_ErrorCode output,
										@out_ErrorMessage		= @out_ErrorMessage output
								IF (@out_ErrorCode <> '0')
									BEGIN
										GOTO WRITE_PROC;
									END 

								FETCH NEXT FROM partial_cursor INTO @v_vchCloseReceiptHeaderID
							END
						CLOSE partial_cursor                  	
						DEALLOCATE partial_cursor 

						UPDATE t_wms_inbound_master SET order_status = 'CLOSE'
							, close_by = @in_vchUserID
							, close_date = GETDATE()
							, close_remark = 'Auto Close Order' 
						WHERE inbound_order_master_id = @in_vchInboundMasterID
					END
			END

		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
		RETURN;

	WRITE_PROC:
		BEGIN
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
															
			SET @v_dtProcessDateTime = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @out_ErrorCode,
				@in_vchData2 = @out_ErrorMessage,
				@in_vchData3 = @v_vchInboundOrderNumber,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage 
		END
END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
			
	IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	SET @v_dtProcessDateTime = GETDATE();
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @out_ErrorCode,
		@in_vchData2 = @out_ErrorMessage,
		@in_vchData3 = @v_vchInboundOrderNumber,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_update_receive_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_update_receive_qty]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchReceiptHeaderID	UNIQUEIDENTIFIER = NULL, 
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,  
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_fltQuantity			FLOAT,
	@in_vchItemUomID		UNIQUEIDENTIFIER, 
	@in_vchLot				NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerial			NVARCHAR(50) = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchReasonCode		NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100),
	@in_vchAttribute2		NVARCHAR(100),
	@in_vchAttribute3		NVARCHAR(100),
	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100), 
	@in_dtReceiveDate		DATE = NULL,
	@in_dtMfgDate			DATE = NULL,
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET XACT_ABORT ON; 
	SET NOCOUNT ON;
	
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(50) = '[usp_inbound_update_receive_qty]', -- The name that uniquely tags this object.
		@v_vchApplicationName		NVARCHAR(100),
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME, 
		@v_vchBeginTrans			BIT = 0,
		@v_dtStartTranDate			DATETIME,
		@Round						INT,
		@v_nCount					INT = 0, 
		@v_vchRuleCheckItemStatus	VARCHAR(3) = 'YES',
		@v_vchWarehouse				NVARCHAR(25) = NULL,
		@v_vchInboundNumber			NVARCHAR(50),
		@v_vchOrderStatus			NVARCHAR(25),
		@v_vchOrderType				NVARCHAR(25),
		@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,
		@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
		@v_vchItemNumber			NVARCHAR(50),
		@v_vchLotControl			VARCHAR(5),
		@v_vchExpiryDateControl		VARCHAR(5),
		@v_vchSerialControl			VARCHAR(5),
		@v_vchAttribute1Control		VARCHAR(5),
		@v_vchAttribute2Control		VARCHAR(5),
		@v_vchAttribute3Control		VARCHAR(5),
		@v_vchAttribute4Control		VARCHAR(5),
		@v_vchAttribute5Control		VARCHAR(5),
		@v_vchItemIsActive			VARCHAR(3),
		@v_vchLocation				NVARCHAR(50)= NULL, 
		@V_vchInvStatus				NVARCHAR(50),  -- เพิ่มใหม่
		
		@v_vchInboundOrderDetailID	UNIQUEIDENTIFIER = NULL,
		@v_vchLineNumber			NVARCHAR(10),

		@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
		@v_vchBaseUom				NVARCHAR(20),
		@v_vchBaseUomPrompt			NVARCHAR(40),
		@v_vchInputUomPrompt		NVARCHAR(40),
		@v_vchIsPrimaryUOM			NVARCHAR(5),
		@v_fltConversionFactor		FLOAT,
		@v_fltOrderQty				FLOAT,
		@v_fltReceivedQty			FLOAT,
		@v_fltQtyOverReceipt		FLOAT,		--จำนวนที่สามารถรับเกินได้
		@v_fltBaseInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว
		@v_fltCalInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว (สำหรับในลูป)
		@v_fltCalQuantity			FLOAT,		--จำนวนที่จะนำไป Save ในแต่ละ Line Detail
		
		@v_vchItemUomID				UNIQUEIDENTIFIER = NULL,
		@v_vchReceiptNumber			NVARCHAR(50),
		@v_vchReceiptStatus			NVARCHAR(25),
		@v_fltAfterInvQuantity		FLOAT,
		@v_vchOverRecAllowed		VARCHAR(3) = 'NO',
		@v_fltOverRecPercentage		FLOAT

	DECLARE @v_vchIsCheckLot		VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckExp		VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckSN			VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckAttribute1	VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckAttribute2	VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckAttribute3	VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckAttribute4	VARCHAR(3) = 'NO'
	DECLARE @v_vchIsCheckAttribute5	VARCHAR(3) = 'NO'
	
	BEGIN TRY 
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchRuleCheckItemStatus = value FROM t_wms_rule WHERE rule_code = 'IB_CHECK_ITEM_STATUS_IN_PLAN' AND is_active = 'YES'
		SET @v_dtStartTranDate = GETDATE();
		SET @in_fltQuantity = ROUND(@in_fltQuantity,@Round)
		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR(8),CONVERT(DATE,@in_vchExpiryDate),112)
		ELSE
			SET @in_vchExpiryDate = NULL

		-- Get and check warehouse
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (@v_vchWarehouse IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Get and check location
		SELECT @v_vchLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		IF (@v_vchLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-- Get and check order status
		SET @v_vchInboundNumber = NULL
		SELECT @v_vchInboundNumber = ibMS.inbound_order_number
			,@v_vchOrderStatus = ibMS.order_status
			,@v_vchOrderType = ibMS.order_type
			,@v_vchOwnerID = ibMS.owner_id
			,@v_vchOwnerCode = own.owner_code 
			,@v_vchCustomerID = ibMS.customer_id 
		FROM t_wms_inbound_master ibMS
		INNER JOIN t_wms_owner own on ibMS.owner_id = own.owner_id
		WHERE ibMS.wh_master_id = @in_vchWhMasterID 
		AND ibMS.inbound_order_master_id = @in_vchInboundMasterID

		IF ISNULL(@v_vchInboundNumber,'') = ''
			BEGIN
				SET @out_ErrorCode = 'INFO-INBOUND-NOT-EXIST'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		--Get wh_item_master_id
		SET @v_vchItemMasterID = NULL
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item  WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-- Get and check item, dgcode, 885
		SELECT @v_vchItemMasterID = it.item_master_id
			, @v_vchItemNumber = it.item_number
			, @v_vchLotControl = it.lot_control
			, @v_vchExpiryDateControl = it.expiry_date_control
			, @v_vchSerialControl = it.sn_control
			, @v_vchAttribute1Control = it.attribute1_control
			, @v_vchAttribute2Control = it.attribute2_control
			, @v_vchAttribute3Control = it.attribute3_control
			, @v_vchAttribute4Control = it.attribute4_control
			, @v_vchAttribute5Control = it.attribute5_control
			, @v_vchItemIsActive = it.is_active
		FROM t_wms_item it
		WHERE it.item_master_id = @v_vchItemMasterID
		AND it.owner_id = @v_vchOwnerID

		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN 
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
			END


		--2024-09-27 : เพิ่มกรณีที่ Order Type in Rule จะให้รับเข้าด้วย Status Hold
		IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_RECEIVE_HOLD' AND is_active = 'YES') 
			BEGIN
				SELECT TOP 1 @v_vchInvStatus = inv_status 
					,@in_vchInvStatusID = inventory_status_id
				FROM t_wms_inventory_status 
				WHERE inv_status = 'HOLD'
				AND is_active = 'YES'
				IF (@v_vchInvStatus IS NULL)
					BEGIN
						SET @out_ErrorCode = 'STATUS_NOT_FOUND';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		ELSE
			BEGIN
				--Get and check status : ถ้าหากมาจาก PDA Status อาจมีค่าเป็น null ให้ get จาก plan
				IF @in_vchInvStatusID IS NULL
					BEGIN
 						SELECT TOP 1 @v_vchInvStatus = ibDT.default_item_status
						FROM t_wms_inbound_detail ibDT 
						WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
						AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(ibDT.lpn,'') = (CASE ISNULL(ibDT.lpn,'') WHEN '' THEN '' ELSE ISNULL(@in_vchLPN,'') END)
						AND ISNULL(ibDT.lot_number,'') = (CASE ISNULL(ibDT.lot_number,'') WHEN '' THEN '' ELSE ISNULL(@in_vchLot,'') END)
						AND ISNULL(ibDT.expiry_date,'') = (CASE ISNULL(ibDT.expiry_date,'') WHEN '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END)
						AND ROUND(quantity_receive,@Round) <= (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																	WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
																	WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																	ELSE ROUND(quantity_order,@Round) END)
						ORDER BY ibDT.line_number
						SELECT @in_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchInvStatus AND is_active = 'YES'
						IF (@v_vchInvStatus IS NULL)
							BEGIN
								SET @out_ErrorCode = 'STATUS_NOT_FOUND';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
				ELSE
					BEGIN
						SELECT @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID AND is_active = 'YES'
						IF (@v_vchInvStatus IS NULL)
							BEGIN
								SET @out_ErrorCode = 'STATUS_NOT_FOUND';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
			END

		--Check Item in Plan
		--Siemens 2018-07-16 : ไม่ต้อง check status plan
		IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @IN_vchWhItemMasterID
						AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END))
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,@v_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchSerial)
				Goto WRITE_PROC;
			END

		-- ถ้าไม่มี Record ที่คงเหลือยอดรับแล้วให้แจ้งว่ารับครบแล้ว
		IF NOT EXISTS (SELECT ISNULL(lot_number,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END))
			BEGIN
				SET @out_ErrorCode = 'ITEM_HAS_BEEN_RECEIVED';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		--Check กรณีที่มีการกำหนด Lot ใน Plan
		IF @v_vchLotControl = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(lot_number,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END)) 					
					BEGIN
						SET @v_vchIsCheckLot = 'YES'
						---------------------------------------------------
						-- Validate lot number in Plan						 
						---------------------------------------------------
						IF @in_vchLot NOT IN (SELECT lot_number FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(lot_number,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-LOT-NUMBER-NOT-EXIST';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchLot = NULL
			END

		--Check กรณีที่มีการกำหนด Exp. ใน Plan
		IF @v_vchExpiryDateControl = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(expiry_date,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckExp= 'YES'
						---------------------------------------------------
						-- Validate Expiry date in Plan						 
						---------------------------------------------------
						IF @in_vchExpiryDate NOT IN (SELECT expiry_date FROM t_wms_inbound_detail
													WHERE inbound_order_master_id = @in_vchInboundMasterID
													AND wh_item_master_id = @in_vchWhItemMasterID
													AND (ISNULL(expiry_date,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-EXPIRY-DATE-NOT-EXIST';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
					END
				
				--ถ้าวันที่ MFG Date กำหนดมา ต้องตรวจสอบใน Inventory ถ้าของ เดียวกัน exp เดียวกัน mfg date ต้องตรงกัน
				IF @in_dtMfgDate IS NOT NULL
					BEGIN
						DECLARE @v_dtCheckMfgDate DATE = NULL
						SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @in_vchWhMasterID 
						AND owner_id = @v_vchOwnerID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
						AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
						
						IF @in_dtMfgDate <> @v_dtCheckMfgDate
							BEGIN
								SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
			END
		ELSE
			BEGIN
				SET @in_vchExpiryDate = NULL
			END

		--Check กรณีที่มีการกำหนด Attr1. ใน Plan
		IF @v_vchAttribute1Control = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(attribute1,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckAttribute1 = 'YES'
						---------------------------------------------------
						-- Validate attribute1 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute1 NOT IN (SELECT attribute1 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(attribute1,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-ATTRIBUTE1-NOT-EXIST'
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute1 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr2. ใน Plan
		IF @v_vchAttribute2Control = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(attribute2,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckAttribute2 = 'YES'
						---------------------------------------------------
						-- Validate attribute2 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute2 NOT IN (SELECT attribute2 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(attribute2,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-ATTRIBUTE2-NOT-EXIST'
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute2 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr3. ใน Plan
		IF @v_vchAttribute3Control = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(attribute3,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckAttribute3 = 'YES'
						---------------------------------------------------
						-- Validate attribute3 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute3 NOT IN (SELECT attribute3 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(attribute3,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-ATTRIBUTE3-NOT-EXIST'
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute3 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr4. ใน Plan
		IF @v_vchAttribute4Control = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(attribute4,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckAttribute4 = 'YES'
						---------------------------------------------------
						-- Validate attribute4 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute4 NOT IN (SELECT attribute4 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(attribute4,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-ATTRIBUTE4-NOT-EXIST'
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute4 = NULL
			END

		--Check กรณีที่มีการกำหนด Attr5. ใน Plan
		IF @v_vchAttribute5Control = 'FULL'
			BEGIN
				IF ('') not in (SELECT ISNULL(attribute5,'') FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN isnull(quantity_receive,0) + 1	--unlimit receipt
																WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																ELSE ROUND(quantity_order,@Round) END))
					BEGIN
						SET @v_vchIsCheckAttribute5 = 'YES'
						---------------------------------------------------
						-- Validate attribute5 in Plan						 
						---------------------------------------------------
						IF @in_vchAttribute5 NOT IN (SELECT attribute5 FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(attribute5,'') <> ''))
						BEGIN
							SET @out_ErrorCode = 'INFO-ATTRIBUTE5-NOT-EXIST'
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END		
					END
			END
		ELSE
			BEGIN
				SET @in_vchAttribute5 = NULL
			END

		IF @v_vchSerialControl = 'FULL'
			BEGIN
				SET @in_fltQuantity = 1
				--------------------------------------------------------------------
				-- Check Duplicate Serial Number in inventory data
				--------------------------------------------------------------------
				SELECT @v_nCount = COUNT(inv.inventory_id)
				FROM t_wms_inventory inv
				LEFT JOIN (SELECT invAttr.inventory_id
								,invAttr.attribute_group_id
								,invAttr.attribute_value AS serial_number
							FROM t_wms_inventory_attribute_type invType
							INNER JOIN t_wms_inventory_attribute invAttr ON invType.inv_attribute_type_id = invAttr.inv_attribute_type_id
							WHERE invType.inv_attribute_type = 'SERIAL'
						   ) invSN ON invSN.inventory_id = inv.inventory_id AND invSN.attribute_group_id = inv.attribute_group_id
				WHERE inv.wh_master_id = @in_vchWhMasterID
				AND inv.wh_item_master_id = @in_vchWhItemMasterID
				AND invSN.serial_number = @in_vchSerial
				AND inv.owner_id = @v_vchOwnerID

				IF (@v_nCount > 0)
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				IF EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(serial_number,'') = @in_vchSerial))
					BEGIN
						SET @v_vchIsCheckSN = 'YES'
					END
				ELSE
					BEGIN
						IF ('') NOT IN (SELECT ISNULL(serial_number,'') FROM t_wms_inbound_detail
							WHERE inbound_order_master_id = @in_vchInboundMasterID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																		WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
																		WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																		ELSE ROUND(quantity_order,@Round) END))
							BEGIN
								SET @v_vchIsCheckSN = 'YES'
								---------------------------------------------------
								-- Validate serial number in Plan						 
								---------------------------------------------------
								IF @in_vchSerial NOT IN (SELECT serial_number FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID AND (ISNULL(serial_number,'') <> ''))
								BEGIN
									SET @out_ErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
									GOTO WRITE_PROC;
								END		
							END
					END

				--------------------------------------------------------------------
				-- Check Duplicate Serial Number in Item Master, Item cross ref
				--------------------------------------------------------------------
				IF EXISTS (SELECT item.item_master_id FROM t_wms_item item
							LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
							WHERE (item.item_number = @in_vchSerial OR cref.alternate_item_number = @in_vchSerial))
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-ITEM-MASTER'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		ELSE
			BEGIN
				SET @in_vchSerial = NULL
			END
	
		----------------------------------------------------------------------------------------------------------------
		--กรณีเป็น Inbound Plan จาก Outbound จะ Check Receipt Date ถ้ามีมีกว่า 1 จะต้องแสดงหน้า Receipt Date ให้เลือก เนื่องจากต้องรับคืนด้วย Receive Date เดิม
		----------------------------------------------------------------------------------------------------------------
		IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_INBOUND_RETURN' AND is_active = 'YES')
			BEGIN
				IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail 
								WHERE inbound_order_master_id = @in_vchInboundMasterID 
								AND wh_item_master_id = @in_vchWhItemMasterID
								AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
								AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
								AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
								AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
								AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
								AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
								AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
								AND ISNULL(serial_number,'') = ISNULL(@in_vchSerial,'')
								AND ROUND(quantity_receive,@Round) <= (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
																			WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ROUND(ISNULL(quantity_receive,0) + 1,@Round)	--unlimit receipt
																			WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
																			ELSE ROUND(quantity_order,@Round) END)			 
								AND receive_date = @in_dtReceiveDate)
					BEGIN
						SET @out_ErrorCode = 'NOT_FOUND_RECEIVE_DATE_IN_PLAN'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-----------------------------------------------------------------------
		-- ตรวจสอบแผน ดึงค่าข้อมูลจากแผน กรณีกำหนด Lot_number, Expiry_date
		-- NONE = Where Lot Exp. = ค่าว่าง
		-- LOT = Where เฉพาะ Lot
		-- LOT_EXP = Where ทั้ง Lot Exp.
		-----------------------------------------------------------------------
		IF @v_vchSerialControl = 'FULL' AND @v_vchIsCheckSN = 'NO'
			BEGIN
				SET @v_nCount = 0
				SELECT @v_nCount = COUNT(inbound_order_detail_id)
					,@v_fltOrderQty = SUM(quantity_order)
					,@v_fltReceivedQty = SUM(quantity_receive)
					,@v_fltQtyOverReceipt = SUM((quantity_order * ISNULL(over_receipt_percentage,0)/100)) 
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END)	  = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(lot_number,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(@in_vchLot,'')			ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(expiry_date,'') ELSE '' END)   = (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(@in_vchExpiryDate,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(attribute1,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(@in_vchAttribute1,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(attribute2,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(@in_vchAttribute2,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(attribute3,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(@in_vchAttribute3,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(attribute4,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(@in_vchAttribute4,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(attribute5,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(@in_vchAttribute5,'')	ELSE '' END)
				AND ISNULL(serial_number,'') = ''
			END
		ELSE
			BEGIN
				SET @v_nCount = 0
				SELECT @v_nCount = COUNT(inbound_order_detail_id)
					,@v_fltOrderQty = SUM(quantity_order)
					,@v_fltReceivedQty = SUM(quantity_receive)
					,@v_fltQtyOverReceipt = SUM((quantity_order * ISNULL(over_receipt_percentage,0)/100)) 
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END)	  = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(lot_number,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(@in_vchLot,'')			ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(expiry_date,'') ELSE '' END)   = (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(@in_vchExpiryDate,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(attribute1,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(@in_vchAttribute1,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(attribute2,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(@in_vchAttribute2,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(attribute3,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(@in_vchAttribute3,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(attribute4,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(@in_vchAttribute4,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(attribute5,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(@in_vchAttribute5,'')	ELSE '' END)
				AND (CASE WHEN @v_vchIsCheckSN = 'YES'		   THEN ISNULL(serial_number,'') ELSE '' END) = (CASE WHEN @v_vchIsCheckSN = 'YES'		   THEN ISNULL(@in_vchSerial,'')		ELSE '' END)
			END

		--AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
		--							 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
		--							 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100)
		--							 ELSE quantity_order END)
		/*
		IF (@v_nCount = 0)
			BEGIN
				SELECT @v_fltOrderQty = SUM(quantity_order)
					,@v_fltReceivedQty = SUM(quantity_receive)
					,@v_fltQtyOverReceipt = SUM((quantity_order * ISNULL(over_receipt_percentage,0)/100)) 
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
			END
		*/

		--Get & Check Item UOM
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchBaseUom = uom
			,@v_vchInputUomPrompt = uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUomID
		and is_active = 'YES'		

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SET @v_vchBaseItemUomID = NULL
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt
					,@v_vchBaseUom = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC
			End

		SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
		SET @v_fltCalInputQuantity  = @v_fltBaseInputQuantity;

		-- ถ้าจำนวน Receipt + input qty > จำนวนที่แผน + จำนวน Over receipt
		IF EXISTS (SELECT TOP 1 inbound_order_detail_id FROM t_wms_inbound_detail
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND over_receipt_allowed = 'YES'
					AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END)	  = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(lot_number,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(@in_vchLot,'')			ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(expiry_date,'') ELSE '' END)   = (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(@in_vchExpiryDate,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(attribute1,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(@in_vchAttribute1,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(attribute2,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(@in_vchAttribute2,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(attribute3,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(@in_vchAttribute3,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(attribute4,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(@in_vchAttribute4,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(attribute5,'')  ELSE '' END)   = (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(@in_vchAttribute5,'')	ELSE '' END)
					AND (CASE WHEN @v_vchIsCheckSN = 'YES'		   THEN ISNULL(serial_number,'') ELSE '' END) = (CASE WHEN @v_vchIsCheckSN = 'YES'		   THEN ISNULL(@in_vchSerial,'')		ELSE '' END)

					AND ISNULL(over_receipt_percentage,0) = 0)
			BEGIN
				--ถ้ามี Over receipt และไม่กำหนด % ไม่ต้อง check qty plan
				GOTO NEXT_STEP;
			END

		IF (ROUND((@v_fltReceivedQty + @v_fltBaseInputQuantity),@Round) > ROUND((@v_fltOrderQty + @v_fltQtyOverReceipt),@Round))
			BEGIN
				SET @out_ErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END		

NEXT_STEP:
	--DECLARE @v_vchTranNumber NVARCHAR(50)
	--EXEC usp_get_ReferenceID @v_vchTranNumber OUTPUT
	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		
		--Set Receive Date
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_RECEIVE_DATE' AND is_active = 'YES') = 'NO') AND @in_dtReceiveDate IS NULL
		BEGIN
			SET @in_dtReceiveDate = CONVERT(DATE,GETDATE())
		END
		
		-- Get/New Receipt Header
		SELECT @v_vchReceiptNumber = receipt_number 
			,@v_vchReceiptStatus = receipt_status
		FROM t_wms_receipt_header 
		WHERE receipt_header_id = @in_vchReceiptHeaderID

		IF ISNULL(@v_vchReceiptNumber,'') = ''
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_NUMBER_CANNOT_BE_EMPTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchReceiptStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_ORDER_IS_CLOSED';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@in_vchReceiptHeaderID IS NULL)
			BEGIN
				SET @in_vchReceiptHeaderID = NEWID();
				INSERT INTO t_wms_receipt_header(receipt_header_id,inbound_order_master_id,receipt_number,create_by)
				VALUES(@in_vchReceiptHeaderID,@in_vchInboundMasterID,@v_vchReceiptNumber,@in_vchUserID)
			END

		 
		/*
		IF (@v_nCount = 0)
		BEGIN
			DECLARE cursorInboundDetail CURSOR FOR
			SELECT inbound_order_detail_id
					,ROUND((quantity_order + (quantity_order * ISNULL(over_receipt_percentage,0)/100)),@Round)
					,quantity_receive
					,line_number
					,over_receipt_allowed
					,over_receipt_percentage
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
				AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
											 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
											 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
											 ELSE quantity_order END)
		END
		ELSE
		BEGIN
			DECLARE cursorInboundDetail CURSOR FOR
			SELECT inbound_order_detail_id
					,ROUND((quantity_order + (quantity_order * ISNULL(over_receipt_percentage,0)/100)),@Round)
					,quantity_receive
					,line_number
					,over_receipt_allowed
					,over_receipt_percentage
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
				AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')			
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')						
				AND quantity_receive < (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
											WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
											WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
											ELSE quantity_order END)
		END
		*/

		DECLARE cursorInboundDetail CURSOR FOR
			SELECT inbound_order_detail_id
					,ROUND((quantity_order + (quantity_order * ISNULL(over_receipt_percentage,0)/100)),@Round)
					,quantity_receive
					,line_number
					,over_receipt_allowed
					,over_receipt_percentage
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
				AND ISNULL(lot_number,'')  = (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(@in_vchLot,'')			ELSE '' END)
				AND ISNULL(expiry_date,'') = (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(@in_vchExpiryDate,'')	ELSE '' END)
				AND ISNULL(attribute1,'')  = (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(@in_vchAttribute1,'')	ELSE '' END)
				AND ISNULL(attribute2,'')  = (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(@in_vchAttribute2,'')	ELSE '' END)
				AND ISNULL(attribute3,'')  = (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(@in_vchAttribute3,'')	ELSE '' END)
				AND ISNULL(attribute4,'')  = (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(@in_vchAttribute4,'')	ELSE '' END)
				AND ISNULL(attribute5,'')  = (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(@in_vchAttribute5,'')	ELSE '' END)
				AND ISNULL(serial_number,'')  = (CASE WHEN @v_vchIsCheckSN = 'YES'		THEN ISNULL(@in_vchSerial,'')		ELSE '' END)
				AND ROUND(quantity_receive,@Round) < (CASE WHEN over_receipt_allowed = 'NO' THEN ROUND(quantity_order,@Round)
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
															WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
															ELSE ROUND(quantity_order,@Round) END)
		OPEN cursorInboundDetail;
		FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltReceivedQty, @v_vchLineNumber,@v_vchOverRecAllowed,@v_fltOverRecPercentage
		IF (@@ROWCOUNT > 0)
			BEGIN
				WHILE @@FETCH_STATUS = 0
					BEGIN
						--คำนวณยอดที่สามารถรับได้ในแต่ละ Line Inbound Detail
						IF @v_vchOverRecAllowed = 'YES' AND ISNULL(@v_fltOverRecPercentage,0) = 0
							BEGIN
								SET @v_fltCalQuantity = @v_fltCalInputQuantity
							END
						ELSE	
							BEGIN
								IF ROUND(@v_fltOrderQty - @v_fltReceivedQty,@Round) <= @v_fltCalInputQuantity
									BEGIN
										SET @v_fltCalQuantity = ROUND(@v_fltOrderQty - @v_fltReceivedQty,@round)
									END
								ELSE
									BEGIN
										SET @v_fltCalQuantity = @v_fltCalInputQuantity
									END
							END

						--Manage Inventory
						EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
													 ,@in_vchWhMasterID			= @in_vchWhMasterID
													 ,@in_vchWhID				= @v_vchWarehouse
													 ,@in_vchOwnerID			= @v_vchOwnerID
													 ,@in_vchInventoryType		= 'INVENTORY'
													 ,@in_vchLocationID			= @in_vchLocationID
													 ,@in_vchParentLPN			= @in_vchParentLPN
													 ,@in_vchLPN				= @in_vchLPN
													 ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
													 ,@in_vchItemMasterID		= @v_vchItemMasterID
													 ,@in_vchItemNumber			= @v_vchItemNumber
													 ,@in_fltQuantity			= @v_fltCalQuantity
													 ,@in_fltQtyAllocate		= 0
													 ,@in_fltQtyIncoming		= 0
													 ,@in_vchPrimaryItemUomID	= @v_vchBaseItemUomID
													 ,@in_vchInvStatusID		= @in_vchInvStatusID
													 ,@in_vchLotNumber			= @in_vchLot
													 ,@in_vchExpiryDate			= @in_vchExpiryDate
													 ,@in_vchSerialNumber		= @in_vchSerial
													 ,@in_vchAttribute1			= @in_vchAttribute1
													 ,@in_vchAttribute2			= @in_vchAttribute2
													 ,@in_vchAttribute3			= @in_vchAttribute3
													 ,@in_vchAttribute4			= @in_vchAttribute4
													 ,@in_vchAttribute5			= @in_vchAttribute5
													 ,@in_dReceiveDate			= @in_dtReceiveDate
													 ,@in_dtMFGDate				= @in_dtMfgDate
													 ,@in_vchDeviceID			= @in_vchDeviceID
													 ,@in_vchUserID				= @in_vchUserID
													 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
													 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
													 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

						IF (@out_ErrorCode <> '0')
							GOTO WRITE_PROC;
						--UPDATE Quantity receipt >> t_wms_inbound_detail
						UPDATE t_wms_inbound_detail SET quantity_receive = ROUND(quantity_receive + @v_fltCalQuantity,@Round)
							,item_status = 'RECEIVING' 
						WHERE inbound_order_detail_id = @v_vchInboundOrderDetailID

						-- บันทึกข้อมูล => receive detail
						IF (@in_vchReceiptHeaderID IS NOT NULL)
							BEGIN
								INSERT INTO t_wms_receipt_detail
								( receipt_header_id
									, inbound_order_detail_id
									, quantity_received
									, item_uom_id
									, receipt_item_status
									, location_received
									, lpn
									, parent_lpn
									, lot_number
									, expiry_date
									, serial_number
									, attribute1
									, attribute2
									, attribute3
									, attribute4
									, attribute5 
									, item_number
									, wh_item_master_id
									, inbound_order_number
									, inbound_order_master_id
									, receive_date
									, mfg_date
									, create_by)
								VALUES(@in_vchReceiptHeaderID
									, @v_vchInboundOrderDetailID
									, ROUND(@v_fltCalQuantity,@Round)
									, @v_vchBaseItemUomID
									, @V_vchInvStatus
									, @v_vchLocation
									, CASE ISNULL(@in_vchLPN,'') WHEN '' THEN NULL ELSE @in_vchLPN END
									, CASE ISNULL(@in_vchParentLPN,'') WHEN '' THEN NULL ELSE @in_vchParentLPN END
									, CASE ISNULL(@in_vchLot,'') WHEN '' THEN NULL ELSE @in_vchLot END
									, CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END
									, CASE ISNULL(@in_vchSerial,'') WHEN '' THEN NULL ELSE @in_vchSerial END
									, CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END
									, CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END
									, CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END
									, CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END
									, CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END
									, @v_vchItemNumber
									, @in_vchWhItemMasterID
									, @v_vchInboundNumber
									, @in_vchInboundMasterID
									, @in_dtReceiveDate
									, @in_dtMfgDate
									, @in_vchUserID)
							END
						ELSE
							BEGIN
								SET @out_ErrorCode = 'NOT_FOUND_RECEIPT_HEADER_ID';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						-- Insert to t_wms_return_lot for Modern Trade 2014-09-02
						IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RETURN_MODERN_TRADE' AND is_active = 'YES'))
							BEGIN 
								IF NOT EXISTS(SELECT return_id FROM t_wms_return_lot 
											  WHERE inbound_order_master_id = @in_vchInboundMasterID
											  AND customer_id = @v_vchCustomerID 
											  AND owner_id = @v_vchOwnerID
											  AND wh_item_master_id = @in_vchWhItemMasterID 
											  AND lot_number = @in_vchLot
											  AND expiry_date = @in_vchExpiryDate)
									BEGIN
										INSERT INTO dbo.t_wms_return_lot
											(inbound_order_master_id
											, inbound_order_number
											, line_number
											, customer_id
											, owner_id
											, wh_item_master_id
											, item_master_id
											, item_number
											, lot_number
											, expiry_date
											, create_by)
										VALUES
											(@in_vchInboundMasterID
											,@v_vchInboundNumber
											,@v_vchLineNumber
											,@v_vchCustomerID
											,@v_vchOwnerID
											,@in_vchWhItemMasterID
											,@v_vchItemMasterID
											,@v_vchItemNumber
											,@in_vchLot
											,@in_vchExpiryDate
											,@in_vchUserID)
									END
							END

						-----------------------------------------------------------
						-- Write Transaction Log Receipt Detail
						-----------------------------------------------------------
						INSERT INTO t_com_tran_log
							(app_id
							, tran_type
							, sub_tran_type
							, [app_name]
							, [description]
							, start_tran_datetime
							, end_tran_datetime
							, to_warehouse
							, to_location
							, to_owner
							, item_number
							, quantity
							, quantity_uom
							, after_quantity
							, after_quantity_uom
							, after_lot_number
							, after_expiry_date
							, serial_number
							, [user_id] 
							, after_parent_lpn
							, after_lpn
							, after_status
							, order_number
							, line_number

							-- Add for attibute
							, [after_attribute1]
							, [after_attribute2]
							, [after_attribute3]
							, [after_attribute4]
							, [after_attribute5]
							, control_number
							, receive_date
							, mfg_date
							, input_quantity
							, input_uom
							, device
							, create_by)
						VALUES
							( @in_vchApplicationID
							, 'IO_RECEIPT'
							, 'RECEIPT'
							, @v_vchApplicationName
							, 'Receive item'
							, @v_dtStartTranDate
							, GETDATE()
							, @v_vchWarehouse
							, @v_vchLocation
							, @v_vchOwnerCode
							, @v_vchItemNumber
							, @v_fltCalQuantity
							, @v_vchBaseUom
							, @v_fltAfterInvQuantity
							, @v_vchBaseUom
							, @in_vchLot
							, @in_vchExpiryDate
							, @in_vchSerial
							, @in_vchUserID
							, @in_vchParentLPN
							, @in_vchLPN
							, @V_vchInvStatus
							, @v_vchInboundNumber
							, @v_vchLineNumber

							-- Add for attibute
							, @in_vchAttribute1
							, @in_vchAttribute2
							, @in_vchAttribute3
							, @in_vchAttribute4
							, @in_vchAttribute5
							, @v_vchReceiptNumber
							, @in_dtReceiveDate
							, @in_dtMfgDate
							, @in_fltQuantity		   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
							, @v_vchInputUomPrompt	   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
							, @in_vchDeviceID
							, @in_vchUserID)

						SET @v_fltCalInputQuantity = @v_fltCalInputQuantity - @v_fltCalQuantity
						IF @v_fltCalInputQuantity = 0
							BREAK;
						FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltReceivedQty, @v_vchLineNumber,@v_vchOverRecAllowed,@v_fltOverRecPercentage
					END
			END
		ELSE
			BEGIN
				SET @out_ErrorCode = 'NOT_FOUND_PLAN_FOR_RECEIPT';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		CLOSE cursorInboundDetail;
		DEALLOCATE cursorInboundDetail;

		-----------------------------------------------------------
		-- add new 2014-02-10 check warranty
		-----------------------------------------------------------
		IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_WARRANTY' AND is_active = 'YES'))
			BEGIN
				IF (ISNULL(@in_vchSerial,'') <> '')
					DECLARE @v_vchWarrantyID	VARCHAR(40)
					(SELECT @v_vchWarrantyID = warranty_id FROM t_mod_warranty WHERE wh_item_master_id = @in_vchWhItemMasterID AND serial_number = @in_vchSerial)
					IF (ISNULL(@v_vchWarrantyID,'') <> '')
						BEGIN
							UPDATE t_mod_warranty SET processing_status = 'Pending', warranty_status = 'Cancel' WHERE warranty_id = @v_vchWarrantyID
						END
			END

		-- Update Master Order Status 
		UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE wh_master_id = @in_vchWhMasterID and inbound_order_master_id = @in_vchInboundMasterID
		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'IN'
									   ,@in_vchTransType	= 'RECEIVING'
									   ,@in_vchWhMasterID	= @in_vchWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwnerCode
									   ,@in_vchLocationID	= @in_vchLocationID
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @in_vchInvStatusID
									   ,@in_vchToWhMasterID = NULL
									   ,@in_vchToLocationID	= NULL
									   ,@in_vchToInvStatusID = NULL
									   ,@in_fltQuantity		= @v_fltBaseInputQuantity
									   ,@in_vchUserID		= @in_vchUserID

		COMMIT TRANSACTION; 
		 
		--------------------------------------------------------------------
		-- Close Partial Receipt
		-- เมื่อทำการรับครบแล้ว และ กฏไม่ยอมให้รับเกิน จะทำการปิดเอกสารให้โดยอัตโนมัติ
		--------------------------------------------------------------------
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_RECEIVE' AND is_active = 'YES') = 'NO')
			BEGIN
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_CLOSE_RECEIPT' AND is_active = 'YES') = 'YES')
					BEGIN
						DECLARE @v_fltQtyOrder		FLOAT,
								@v_fltQtyReceive	FLOAT

						SELECT @v_fltQtyOrder = SUM(quantity_order + (quantity_order * (ISNULL(over_receipt_percentage,0)/100)))
							,@v_fltQtyReceive = SUM(quantity_receive)
						FROM t_wms_inbound_detail 
						WHERE inbound_order_master_id = @in_vchInboundMasterID
							
						IF (@v_fltQtyOrder <= @v_fltQtyReceive)
							BEGIN
								SET @out_ErrorCode = '';
								SET @out_ErrorMessage = '';
								DECLARE @v_vchReceiptHeaderID UNIQUEIDENTIFIER = NULL
								DECLARE partial_cursor CURSOR FOR
									SELECT receipt_header_id FROM t_wms_receipt_header
									WHERE inbound_order_master_id = @in_vchInboundMasterID
									AND receipt_status = 'OPEN'
								OPEN partial_cursor
								FETCH NEXT FROM partial_cursor INTO @v_vchReceiptHeaderID
				
								WHILE @@FETCH_STATUS = 0
									BEGIN
										EXEC [usp_close_partial_receive]
												@in_vchApplicationID	= @in_vchApplicationID,
												@in_vchDevice			= @in_vchDeviceID,
												@in_vchWhMasterID		= @in_vchWhMasterID,
												@in_vchInboundMasterID	= @in_vchInboundMasterID,
												@in_vchReceiptHeaderID	= @v_vchReceiptHeaderID,
												@in_vchCloseBy			= @in_vchUserID,
												@out_ErrorCode			= @out_ErrorCode output,
												@out_ErrorMessage		= @out_ErrorMessage output
										IF (@out_ErrorCode <> '0')
											BEGIN
												GOTO WRITE_PROC;
											END 

										FETCH NEXT FROM partial_cursor INTO @v_vchReceiptHeaderID
									END
								CLOSE partial_cursor                  	
								DEALLOCATE partial_cursor 
								UPDATE t_wms_inbound_master SET order_status = 'CLOSE', close_by = @in_vchUserID, close_date = getdate(), close_remark = 'Auto Close Order' WHERE inbound_order_master_id = @in_vchInboundMasterID
							END
					END
			END

		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;

			IF CURSOR_STATUS('global','cursorInboundDetail')>=-1
			BEGIN
				CLOSE cursorInboundDetail;
				DEALLOCATE cursorInboundDetail;
			END
			
			SET @v_dtProcessDateTime = GETDATE();
			SET @v_vchProcessData1 = 'Receipt Number ' + @v_vchReceiptNumber;	
			SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END

    END TRY
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION;
			
		IF CURSOR_STATUS('global','cursorInboundDetail')>=-1
			BEGIN
				CLOSE cursorInboundDetail;
				DEALLOCATE cursorInboundDetail;
			END

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData1 = 'Receipt Number ' + @v_vchReceiptNumber;	
		SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchInboundNumber,
				@in_vchData4 = @out_ErrorMessage,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_update_receive_return_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_update_receive_return_qty]
	@in_vchApplicationID	 VARCHAR(40),
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER, 
	@in_vchOwnerID			 UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	 UNIQUEIDENTIFIER,
	@in_vchReceiptHeaderID	 UNIQUEIDENTIFIER,
	@in_vchLocationID		 UNIQUEIDENTIFIER,
	@in_vchParentLpn		 NVARCHAR(25),
	@in_vchLpn				 NVARCHAR(25),
	@in_vchInvStatusID		 UNIQUEIDENTIFIER,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER, 
	@in_fltQuantity			 FLOAT,
	@in_vchItemUomID		 UNIQUEIDENTIFIER, 
	@in_vchLotNumber		 NVARCHAR(50) = NULL,
	@in_vchExpiryDate		 NVARCHAR(10) = NULL,
	@in_vchSerialNumber		 NVARCHAR(50) = NULL,
	@in_vchAttribute1		 NVARCHAR(100)= NULL,
	@in_vchAttribute2		 NVARCHAR(100)= NULL,
	@in_vchAttribute3		 NVARCHAR(100)= NULL,
	@in_vchAttribute4		 NVARCHAR(100)= NULL,
	@in_vchAttribute5		 NVARCHAR(100)= NULL,
	@in_dtReceiveDate		 DATE,
	@out_ErrorCode			 NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		 NVARCHAR(500) OUTPUT
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_inbound_update_receive_return_qty]', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(100),
			@v_dtProcessDateTime		DATETIME,
			@v_dtStartTranDate			DATETIME,
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,
			@v_vchRuleCheckItemStatus	VARCHAR(3) = 'YES',
			@v_vchWarehouse				NVARCHAR(25) = NULL,
			@v_vchOwnerCode				NVARCHAR(50) = NULL,
			@v_vchInboundNumber			NVARCHAR(50) = NULL,
			@v_vchOrderStatus			NVARCHAR(10) = NULL,
			@v_vchReferenceNumber		NVARCHAR(50) = NULL,
			@v_vchReceiptNumber			NVARCHAR(50) = NULL,
			@v_vchReceiptStatus			nvarchar(10) = NULL,
			@v_vchLocation				NVARCHAR(50) = NULL,
			@v_vchInboundOrderDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchLotControl			VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchSerialControl			VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5), 
			@v_vchLineNumber			NVARCHAR(10),
			@v_vchInvStatus				VARCHAR(50),
			@v_dtMfgDate				DATE = NULL,
			@v_vchBaseItemUomID			VARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20),
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchInputUomPrompt		NVARCHAR(40),
			@v_vchIsPrimaryUOM			NVARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว
			@v_fltRemainReturnQuantity	FLOAT,
			@v_fltOrderQty				FLOAT,
			@v_fltReceivedQty			FLOAT,
			@v_fltAfterInvQuantity		FLOAT,
			@v_fltCalInputQuantity		FLOAT,		--จำนวนที่รับเข้ามา ที่คำนวณให้อยู่ในรูปแบบของหน่วยที่เล็กที่สุดแล้ว (สำหรับในลูป)
			@v_fltCalQuantity			FLOAT,		--จำนวนที่จะนำไป Save ในแต่ละ Line Detail
			@v_vchOrderType				NVARCHAR(25)

	BEGIN TRY
		SET @v_dtStartTranDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchRuleCheckItemStatus = value FROM t_wms_rule WHERE rule_code = 'IB_CHECK_ITEM_STATUS_IN_PLAN' AND is_active = 'YES'
		SET @in_fltQuantity = ROUND(@in_fltQuantity,@Round)
		
		--Get and check location
		SELECT @v_vchLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		IF (@v_vchLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Check Inbound Order
		SELECT @v_vchInboundNumber = inbound_order_number
			,@v_vchOrderStatus = order_status
			,@v_vchReferenceNumber = reference_number
			,@v_vchOwnerCode = owner_code
			,@v_vchOrderType = order_type
		FROM t_wms_inbound_master
		WHERE wh_master_id = @in_vchWhMasterID
		AND inbound_order_master_id = @in_vchInboundMasterID
		IF ISNULL(@v_vchInboundNumber,'') = ''
			BEGIN
				SET @out_ErrorCode = 'INFO-INBOUND-ORDER-INVALID';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
			 
		-- CHECK ORDER STATUS
		IF (@v_vchOrderStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;				
			END

		--Check Warehouse Item Master 
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param2','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Check Item Master 
		SELECT @v_vchItemMasterID = item_master_id
			, @v_vchItemNumber = item_number
			, @v_vchLotControl = lot_control
			, @v_vchExpiryDateControl = expiry_date_control
			, @v_vchSerialControl = sn_control
			, @v_vchAttribute1Control = attribute1_control
			, @v_vchAttribute2Control = attribute2_control
			, @v_vchAttribute3Control = attribute3_control
			, @v_vchAttribute4Control = attribute4_control
			, @v_vchAttribute5Control = attribute5_control 
		FROM t_wms_item
		WHERE item_master_id = @v_vchItemMasterID
		AND owner_id = @in_vchOwnerID 
		AND is_active = 'YES'
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF @v_vchLotControl = 'NONE'
			BEGIN
				SET @in_vchLotNumber = NULL
			END
		IF @v_vchExpiryDateControl = 'NONE'
			BEGIN
				SET @in_vchExpiryDate = NULL
			END
		ELSE
			BEGIN
				SET @in_vchExpiryDate = (CASE WHEN ISNULL(@in_vchExpiryDate,'') <> '' THEN CONVERT(VARCHAR(8),CONVERT(DATE,@in_vchExpiryDate),112) ELSE NULL END)
			END
		IF @v_vchAttribute1Control = 'NONE'
			BEGIN
				SET @in_vchAttribute1 = NULL
			END
		IF @v_vchAttribute2Control = 'NONE'
			BEGIN
				SET @in_vchAttribute2 = NULL
			END
		IF @v_vchAttribute3Control = 'NONE'
			BEGIN
				SET @in_vchAttribute3 = NULL
			END
		IF @v_vchAttribute4Control = 'NONE'
			BEGIN
				SET @in_vchAttribute4 = NULL
			END
		IF @v_vchAttribute5Control = 'NONE'
			BEGIN
				SET @in_vchAttribute5 = NULL
			END
		IF @v_vchSerialControl = 'NONE'
			BEGIN
				SET @in_vchSerialNumber = NULL
			END
		ELSE
			BEGIN
				SET @in_fltQuantity = 1
			END

		--2024-09-27 : เพิ่มกรณีที่ Order Type in Rule จะให้รับเข้าด้วย Status Hold
		IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_RECEIVE_HOLD' AND is_active = 'YES') 
			BEGIN
				SELECT TOP 1 @v_vchInvStatus = inv_status 
					,@in_vchInvStatusID = inventory_status_id
				FROM t_wms_inventory_status 
				WHERE inv_status = 'HOLD'
				AND is_active = 'YES'
				IF (@v_vchInvStatus IS NULL)
					BEGIN
						SET @out_ErrorCode = 'STATUS_NOT_FOUND';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		ELSE
			BEGIN
				--Get and check status : ถ้าหากมาจาก PDA Status อาจมีค่าเป็น null ให้ get จาก plan
				IF @in_vchInvStatusID IS NULL
					BEGIN
 						SELECT TOP 1 @v_vchInvStatus = ibDT.default_item_status
						FROM t_wms_inbound_detail ibDT 
						WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
						AND ibDT.wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(ibDT.lpn,'') = (CASE ISNULL(ibDT.lpn,'') WHEN '' THEN '' ELSE ISNULL(@in_vchLPN,'') END)
						AND ISNULL(ibDT.lot_number,'') = (CASE ISNULL(ibDT.lot_number,'') WHEN '' THEN '' ELSE ISNULL(@in_vchLotNumber,'') END)
						AND ISNULL(ibDT.expiry_date,'') = (CASE ISNULL(ibDT.expiry_date,'') WHEN '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END)
						AND quantity_receive <= (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
														WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
														ELSE quantity_order END)
						ORDER BY ibDT.line_number
						SELECT @in_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchInvStatus AND is_active = 'YES'
					END
				ELSE
					BEGIN
						SELECT @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID AND is_active = 'YES'
						IF (@v_vchInvStatus IS NULL)
							BEGIN
								SET @out_ErrorCode = 'STATUS_NOT_FOUND';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@V_vchInvStatus,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
			END
		
		--Check Data have in outbound
		IF NOT EXISTS (SELECT wh_item_master_id FROM v_wms_outbound_for_receipt_return
						WHERE inbound_order_master_id = @in_vchInboundMasterID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						AND receive_date = @in_dtReceiveDate)
		BEGIN
			SET @out_ErrorCode = 'NOT_FOUND_DATA_IN_OUTBOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

		--Check Item in Plan 
		IF NOT EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @in_vchInboundMasterID AND wh_item_master_id = @IN_vchWhItemMasterID
						AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END))
			BEGIN
				SET @out_ErrorCode = 'INBOUND_ORDER_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchSerialNumber)
				Goto WRITE_PROC;
			END

		--Check Item จะต้องเคยจ่ายออกไปแล้ว จึงจะสามารถ Return กลับมาได้
		SET @v_fltRemainReturnQuantity = 0
		SELECT @v_fltRemainReturnQuantity = ROUND(SUM(ISNULL(quantity_ship,0) - ISNULL(quantity_received,0)),@Round)
			,@v_dtMfgDate = mfg_date
		FROM v_wms_outbound_for_receipt_return
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'') 
		AND receive_date = @in_dtReceiveDate
		GROUP BY mfg_date
		IF @v_fltRemainReturnQuantity = 0
			BEGIN
				SET @out_ErrorCode = 'INFO-NOT-FOUND-ITEM-NUMBER-FOR-RETURN';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		SELECT @v_fltOrderQty = SUM(quantity_order)
			,@v_fltReceivedQty = SUM(quantity_receive)
		FROM t_wms_inbound_detail
		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND wh_item_master_id = @in_vchWhItemMasterID

		--Get & Check Item UOM
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUom = uom
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchInputUomPrompt = uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUomID
		AND is_active = 'YES'		
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC
			End

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt
					,@v_vchBaseUom = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
	 
		SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
		SET @v_fltCalInputQuantity  = @v_fltBaseInputQuantity;

		IF ((@v_fltReceivedQty + @v_fltBaseInputQuantity) > @v_fltOrderQty)
			BEGIN
				SET @out_ErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		-- ถ้าจำนวน input qty > จำนวนที่สามารถ Return ได้
		IF (@v_fltBaseInputQuantity > @v_fltRemainReturnQuantity)
			BEGIN
				SET @out_ErrorCode = 'QTY_MORE_THAN_RETURN_QTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		--ถ้าวันที่ MFG Date กำหนดมา ต้องตรวจสอบใน Inventory ถ้าของ เดียวกัน exp เดียวกัน mfg date ต้องตรงกัน
		IF @v_vchExpiryDateControl = 'FULL' AND @v_dtMfgDate IS NOT NULL
		BEGIN
			DECLARE @v_dtCheckMfgDate DATE = NULL
			SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
			FROM v_wms_inventory_data_serial_by_id
			WHERE wh_master_id = @in_vchWhMasterID 
			AND owner_id = @in_vchOwnerID
			AND wh_item_master_id = @in_vchWhItemMasterID 
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						
			IF @v_dtMfgDate <> @v_dtCheckMfgDate
				BEGIN
					SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
		END

	--DECLARE @v_vchTranNumber NVARCHAR(50) 
	--EXEC usp_get_ReferenceID @v_vchTranNumber OUTPUT	
	
	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		
		-- Get/New Receipt Header
		SELECT @v_vchReceiptNumber = receipt_number 
			,@v_vchReceiptStatus = receipt_status
		FROM t_wms_receipt_header 
		WHERE receipt_header_id = @in_vchReceiptHeaderID

		IF ISNULL(@v_vchReceiptNumber,'') = ''
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_NUMBER_CANNOT_BE_EMPTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchReceiptStatus = 'CLOSE')
			BEGIN
				SET @out_ErrorCode = 'RECEIPT_ORDER_IS_CLOSED';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchReceiptNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@in_vchReceiptHeaderID IS NULL)
			BEGIN
				SET @in_vchReceiptHeaderID = NEWID();
				INSERT INTO t_wms_receipt_header(receipt_header_id,inbound_order_master_id,receipt_number,create_by)
				VALUES(@in_vchReceiptHeaderID,@in_vchInboundMasterID,@v_vchReceiptNumber,@in_vchUserID)
			END

		DECLARE cursorInboundDetail CURSOR FOR
			SELECT inbound_order_detail_id
					,ROUND(quantity_order,@Round)
					,quantity_receive 
					,line_number
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN default_item_status ELSE '' END) = (CASE WHEN @v_vchRuleCheckItemStatus = 'YES' THEN @v_vchInvStatus ELSE '' END)
		OPEN cursorInboundDetail;
		FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltReceivedQty,@v_vchLineNumber
		WHILE @@FETCH_STATUS = 0
			BEGIN
				--คำนวณยอดที่สามารถรับได้ในแต่ละ Line Inbound Detail
				IF ROUND(@v_fltOrderQty - @v_fltReceivedQty,@Round) <= @v_fltCalInputQuantity
					BEGIN
						SET @v_fltCalQuantity = ROUND(@v_fltOrderQty - @v_fltReceivedQty,@round)
					END
				ELSE
					BEGIN
						SET @v_fltCalQuantity = @v_fltCalInputQuantity
					END

				--Manage Inventory
				EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
											 ,@in_vchWhMasterID			= @in_vchWhMasterID
											 ,@in_vchWhID				= @v_vchWarehouse
											 ,@in_vchOwnerID			= @in_vchOwnerID
											 ,@in_vchInventoryType		= 'INVENTORY'
											 ,@in_vchLocationID			= @in_vchLocationID
											 ,@in_vchParentLPN			= @in_vchParentLPN
											 ,@in_vchLPN				= @in_vchLPN
											 ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
											 ,@in_vchItemMasterID		= @v_vchItemMasterID
											 ,@in_vchItemNumber			= @v_vchItemNumber
											 ,@in_fltQuantity			= @v_fltCalQuantity
											 ,@in_fltQtyAllocate		= 0
											 ,@in_fltQtyIncoming		= 0
											 ,@in_vchPrimaryItemUomID	= @v_vchBaseItemUomID
											 ,@in_vchInvStatusID		= @in_vchInvStatusID
											 ,@in_vchLotNumber			= @in_vchLotNumber
											 ,@in_vchExpiryDate			= @in_vchExpiryDate
											 ,@in_vchSerialNumber		= @in_vchSerialNumber
											 ,@in_vchAttribute1			= @in_vchAttribute1
											 ,@in_vchAttribute2			= @in_vchAttribute2
											 ,@in_vchAttribute3			= @in_vchAttribute3
											 ,@in_vchAttribute4			= @in_vchAttribute4
											 ,@in_vchAttribute5			= @in_vchAttribute5
											 ,@in_dReceiveDate			= @in_dtReceiveDate
											 ,@in_dtMFGDate				= @v_dtMfgDate
											 ,@in_vchDeviceID			= @in_vchDeviceID
											 ,@in_vchUserID				= @in_vchUserID
											 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
											 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
											 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

				IF (@out_ErrorCode <> '0')
					GOTO WRITE_PROC;

				--UPDATE Quantity receipt >> t_wms_inbound_detail
				UPDATE t_wms_inbound_detail SET quantity_receive = ROUND(quantity_receive + @v_fltCalQuantity,@Round)
					,item_status = 'RECEIVING' 
				WHERE inbound_order_detail_id = @v_vchInboundOrderDetailID

				-- บันทึกข้อมูล => receive detail
				IF (@in_vchReceiptHeaderID IS NOT NULL)
					BEGIN
						INSERT INTO t_wms_receipt_detail
						( receipt_header_id
							, inbound_order_detail_id
							, quantity_received
							, item_uom_id
							, receipt_item_status
							, location_received
							, lpn
							, parent_lpn
							, lot_number
							, expiry_date
							, serial_number
							, attribute1
							, attribute2
							, attribute3
							, attribute4
							, attribute5 
							, item_number
							, wh_item_master_id
							, inbound_order_number
							, inbound_order_master_id
							, receive_date
							, mfg_date
							, create_by)
						VALUES(@in_vchReceiptHeaderID
							, @v_vchInboundOrderDetailID
							, ROUND(@v_fltCalQuantity,@Round)
							, @v_vchBaseItemUomID
							, @V_vchInvStatus
							, @v_vchLocation
							, CASE ISNULL(@in_vchLPN,'') WHEN '' THEN NULL ELSE @in_vchLPN END
							, CASE ISNULL(@in_vchParentLPN,'') WHEN '' THEN NULL ELSE @in_vchParentLPN END
							, CASE ISNULL(@in_vchLotNumber,'') WHEN '' THEN NULL ELSE @in_vchLotNumber END
							, CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END
							, CASE ISNULL(@in_vchSerialNumber,'') WHEN '' THEN NULL ELSE @in_vchSerialNumber END
							, CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END
							, CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END
							, CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END
							, CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END
							, CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END
							, @v_vchItemNumber
							, @in_vchWhItemMasterID
							, @v_vchInboundNumber
							, @in_vchInboundMasterID
							, @in_dtReceiveDate
							, @v_dtMfgDate
							, @in_vchUserID)
					END
				ELSE
					BEGIN
						SET @out_ErrorCode = 'NOT_FOUND_RECEIPT_HEADER_ID';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
					 
				-----------------------------------------------------------
				-- Write Transaction Log Receipt Detail
				-----------------------------------------------------------
				INSERT INTO t_com_tran_log
					(app_id
					, tran_type
					, sub_tran_type
					, [app_name]
					, [description]
					, start_tran_datetime
					, end_tran_datetime
					, to_warehouse
					, to_location
					, to_owner
					, item_number
					, quantity
					, quantity_uom
					, after_quantity
					, after_quantity_uom
					, after_lot_number
					, after_expiry_date
					, serial_number
					, [user_id] 
					, after_parent_lpn
					, after_lpn
					, after_status
					, order_number
					, line_number

					-- Add for attibute
					, [after_attribute1]
					, [after_attribute2]
					, [after_attribute3]
					, [after_attribute4]
					, [after_attribute5] 
					, control_number
					, receive_date
					, mfg_date
					, input_quantity
					, input_uom
					, reference_number
					, device
					, create_by)
				VALUES
					( @in_vchApplicationID
					, 'IO_RECEIPT'
					, 'RECEIPT'
					, @v_vchApplicationName
					, 'Receive item by Return.'
					, @v_dtStartTranDate
					, GETDATE()
					, @v_vchWarehouse
					, @v_vchLocation
					, @v_vchOwnerCode
					, @v_vchItemNumber
					, @v_fltCalQuantity
					, @v_vchBaseUom
					, @v_fltAfterInvQuantity
					, @v_vchBaseUom
					, @in_vchLotNumber
					, @in_vchExpiryDate
					, @in_vchSerialNumber
					, @in_vchUserID
					, @in_vchParentLPN
					, @in_vchLPN
					, @V_vchInvStatus
					, @v_vchInboundNumber
					, @v_vchLineNumber

					-- Add for attibute
					, @in_vchAttribute1
					, @in_vchAttribute2
					, @in_vchAttribute3
					, @in_vchAttribute4
					, @in_vchAttribute5
					, @v_vchReceiptNumber
					, @in_dtReceiveDate
					, @v_dtMfgDate
					, @in_fltQuantity		   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @v_vchInputUomPrompt	   --Value input from screen if inbound_detail same item 3 records same data in 3 inbound_detail [multi item]
					, @v_vchReferenceNumber	   --Value is outbound order number for reference data return
					, @in_vchDeviceID
					, @in_vchUserID)

				SET @v_fltCalInputQuantity = @v_fltCalInputQuantity - @v_fltCalQuantity
				IF @v_fltCalInputQuantity = 0
					BREAK;
				FETCH FROM cursorInboundDetail INTO @v_vchInboundOrderDetailID, @v_fltOrderQty, @v_fltReceivedQty,@v_vchLineNumber
			END
		CLOSE cursorInboundDetail;
		DEALLOCATE cursorInboundDetail;

		-- Update Master Order Status 
		UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE wh_master_id = @in_vchWhMasterID and inbound_order_master_id = @in_vchInboundMasterID
		
		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'IN'
									   ,@in_vchTransType	= 'RECEIVING'
									   ,@in_vchWhMasterID	= @in_vchWhMasterID 
									   ,@in_vchOwnerID		= @in_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwnerCode
									   ,@in_vchLocationID	= @in_vchLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @in_vchInvStatusID
									   ,@in_vchToWhMasterID	= NULL
									   ,@in_vchToLocationID	= NULL
									   ,@in_vchToInvStatusID = NULL
									   ,@in_fltQuantity		= @v_fltBaseInputQuantity
									   ,@in_vchUserID		= @in_vchUserID

		COMMIT TRANSACTION;
		
		--------------------------------------------------------------------
		-- Close Partial Receipt
		-- เมื่อทำการรับครบแล้ว และ กฏไม่ยอมให้รับเกิน จะทำการปิดเอกสารให้โดยอัตโนมัติ
		--------------------------------------------------------------------
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_RECEIVE' AND is_active = 'YES') = 'NO')
			BEGIN
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_CLOSE_RECEIPT') = 'YES')
					BEGIN
						DECLARE @v_fltQtyOrder		FLOAT,
								@v_fltQtyReceive	FLOAT

						SELECT @v_fltQtyOrder = SUM(quantity_order + (quantity_order * (ISNULL(over_receipt_percentage,0)/100)))
							,@v_fltQtyReceive = SUM(quantity_receive)
						FROM t_wms_inbound_detail 
						WHERE inbound_order_master_id = @in_vchInboundMasterID
							
						IF (@v_fltQtyOrder <= @v_fltQtyReceive)
							BEGIN
								SET @out_ErrorCode = '';
								SET @out_ErrorMessage = '';
									
								EXEC [usp_close_partial_receive]
										@in_vchApplicationID	= @in_vchApplicationID,
										@in_vchDevice			= @in_vchDeviceID,
										@in_vchWhMasterID		= @in_vchWhMasterID,
										@in_vchInboundMasterID	= @in_vchInboundMasterID,
										@in_vchReceiptHeaderID	= @in_vchReceiptHeaderID,
										@in_vchCloseBy			= @in_vchUserID,
										@out_ErrorCode			= @out_ErrorCode output,
										@out_ErrorMessage		= @out_ErrorMessage output
								IF (@out_ErrorCode <> '0')
									BEGIN
										GOTO WRITE_PROC;
									END

								UPDATE t_wms_inbound_master SET order_status = 'CLOSE', close_by = @in_vchUserID, close_date = getdate(), close_remark = 'Auto Close Order' WHERE inbound_order_master_id = @in_vchInboundMasterID
							END
					END
			END
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
	WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
					
		IF CURSOR_STATUS('global','cursorInboundDetail')>=-1
			BEGIN
				CLOSE cursorInboundDetail;
				DEALLOCATE cursorInboundDetail;
			END
			
		SET @v_dtProcessDateTime = GETDATE();
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchInboundNumber,
			@in_vchData2 = @v_vchReceiptNumber,
			@in_vchData3 = @v_vchLocation,
			@in_vchData4 = @v_vchItemNumber,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END

    END TRY
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION; 

		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
			
		SET @v_dtProcessDateTime = GETDATE();
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchInboundNumber,
			@in_vchData2 = @v_vchReceiptNumber,
			@in_vchData3 = @v_vchLocation,
			@in_vchData4 = @v_vchItemNumber,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_validate_quantity]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-12-13
-- Description:	Validation quantity
-- 29/05/2014 : ปรับตอน Print QTY กำหนดให้ขนาด varchar(10) เป็น 30
-- 14/12/2015 : เพิ่ม Check dup lpn
-- =============================================
CREATE PROCEDURE [dbo].[usp_inbound_validate_quantity]
	@in_vchApplicationID	VARCHAR(40)	  = NULL,
	@in_vchLocalID			VARCHAR(40)	  = NULL,
	@in_vchWarehouseID		UNIQUEIDENTIFIER,
	@in_vchInboundMasterID	UNIQUEIDENTIFIER, 
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_vchItemMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_fltQuantity			FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchLot				NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(10) = NULL,
	@in_vchSerial			NVARCHAR(50) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@out_fltQuantityPlan	FLOAT = 0 OUTPUT,
	@out_fltQuantityReceive	FLOAT = 0 OUTPUT,
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round					INT,
		@v_nCount					INT,
		@v_fltBaseInputQuantity		FLOAT = 0,
		@v_fltOrderQty				FLOAT = 0,
		@v_fltReceivedQty			FLOAT = 0,
		@v_fltQtyOverReceipt		FLOAT = 0,
		@v_fltOverRecPercentage		FLOAT = 0,
		@v_vchItemUomID				UNIQUEIDENTIFIER,
		@v_fltConversionFactor		FLOAT = 0,
		@v_vchIsPrimaryUOM			NVARCHAR(3) 
	
	--Set digit
	SELECT @Round = value FROM t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	BEGIN TRY
		-----------------------------------------------------------------------
		-- ตรวจสอบแผน ดึงค่าข้อมูลจากแผน กรณีกำหนด Lot_number, Expiry_date, Serial
		-----------------------------------------------------------------------
		SET @v_nCount = 0
		SELECT @v_nCount = COUNT(inbound_order_detail_id)
			,@v_fltOrderQty = SUM(quantity_order)
			,@v_fltReceivedQty = SUM(quantity_receive)
			,@v_fltQtyOverReceipt = SUM((quantity_order * ISNULL(over_receipt_percentage,0)/100))
		FROM t_wms_inbound_detail
		WHERE inbound_order_master_id = @in_vchInboundMasterID 
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(serial_number,'') = ISNULL(@in_vchSerial,'')
		AND quantity_receive <= (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
									 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
									 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
									 ELSE quantity_order END)
		IF (@v_nCount = 0)
			BEGIN
				SELECT @v_fltOrderQty = SUM(quantity_order)
					,@v_fltReceivedQty = SUM(quantity_receive)
					,@v_fltQtyOverReceipt = SUM((quantity_order * ISNULL(over_receipt_percentage,0)/100))
					,@v_fltOverRecPercentage = SUM(isnull(over_receipt_percentage,0))
				FROM t_wms_inbound_detail
				WHERE inbound_order_master_id = @in_vchInboundMasterID
				AND wh_item_master_id = @in_vchWhItemMasterID			
				AND quantity_receive <= (CASE WHEN over_receipt_allowed = 'NO' THEN quantity_order
											 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) = 0 THEN ISNULL(quantity_receive,0) + 1	--unlimit receipt
											 WHEN over_receipt_allowed = 'YES' AND ISNULL(over_receipt_percentage,0) > 0 THEN ROUND(quantity_order + ((quantity_order * ISNULL(over_receipt_percentage,0))/100),@Round)
											 ELSE quantity_order END)
			END

		--Get & Check Item UOM
		SET @v_vchItemUomID = NULL
		SELECT @v_vchItemUomID = item_uom_id
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @in_vchItemMasterID 
		AND uom_prompt = @in_vchUOMPrompt			
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				RETURN;
			End

		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
			END
		ELSE
			BEGIN
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity,@Round);
			END
		 
		-- ถ้าจำนวน Receipt + input qty > จำนวนที่แผน + จำนวน Over receipt
		IF EXISTS (SELECT TOP 1 inbound_order_detail_id FROM t_wms_inbound_detail 
					WHERE inbound_order_master_id = @in_vchInboundMasterID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND over_receipt_allowed = 'YES'
					AND ISNULL(over_receipt_percentage,0) = 0)
			BEGIN
				--if unlimit over receipt (over_receipt_allowed = Yes and over_receipt_percentage = 0) not check qty plan and qty receive
				SET @out_ErrorCode = '0'
				RETURN;
			END

		IF ((@v_fltReceivedQty + @v_fltBaseInputQuantity) > (@v_fltOrderQty + @v_fltQtyOverReceipt))
			BEGIN
				SET @out_ErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				RETURN;
			END
		SET @out_ErrorCode = '0'
	END TRY
	BEGIN CATCH
		SET @out_ErrorCode = convert(varchar,ERROR_NUMBER())
		SET @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inbound_volumn_auto_receive_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inbound_volumn_auto_receive_qty]
(
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchInboundMasterID	UNIQUEIDENTIFIER,
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON; 
	DECLARE @v_vchBeginTrans		 BIT = 0
	DECLARE @Round					 INT
	DECLARE @v_vchStartTime			 DATETIME = GETDATE()
	DECLARE @v_dtProcessDateTime	 DATETIME
	DECLARE @c_vchObjName			 NVARCHAR(50) = '[usp_inbound_volumn_auto_receive_qty]'
	DECLARE @v_vchWhMasterID		 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWarehouse			 NVARCHAR(25) = NULL
	DECLARE @v_vchInboundOrderNumber NVARCHAR(50) = NULL 
	DECLARE @v_vchOrderStatus		 NVARCHAR(10) = NULL
	DECLARE @v_vchOrderType			 NVARCHAR(30) = NULL 
	DECLARE @v_vchReceiptHeaderID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchReceiptNumber		 NVARCHAR(50) = NULL 
	DECLARE @v_vchLocationID		 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLocation			 NVARCHAR(50) = NULL
	DECLARE @v_vchLPNControl		 NVARCHAR(3)  = NULL

	DECLARE @v_vchInboundDetailID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWhItemMasterID	 UNIQUEIDENTIFIER
	DECLARE @v_vchItemUomID			 UNIQUEIDENTIFIER  
	DECLARE @v_fltQtyReceive		 FLOAT = NULL 
	DECLARE @v_vchLPN				 NVARCHAR(25) = NULL
	DECLARE @v_vchLotNumber			 NVARCHAR(50) = NULL
	DECLARE @v_vchExpiryDate		 NVARCHAR(50) = NULL
	DECLARE @v_vchSerialNumber		 NVARCHAR(50) = NULL
	DECLARE @v_vchAttribute1		 NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute2		 NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute3		 NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute4		 NVARCHAR(100) = NULL
	DECLARE @v_vchAttribute5		 NVARCHAR(100) = NULL
	DECLARE @in_vchInvStatusID		 UNIQUEIDENTIFIER = NULL
	DECLARE @v_dtReceiveDate		 DATE = GETDATE()

BEGIN TRY 
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	----------------------------------------------
	--Check Parent LPN Control
	----------------------------------------------
	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN' AND is_active = 'YES') = 'YES'
		BEGIN
			SET @out_ErrorCode = 'AUTO_RECEIPT_CANNOT_CONTROL_PARENT_LPN';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END
	----------------------------------------------
	--Check Inbound Order
	----------------------------------------------
	SELECT TOP 1 @v_vchInboundOrderNumber = ibMS.inbound_order_number
		,@v_vchWhMasterID = ibMS.wh_master_id
		,@v_vchWarehouse = ibMS.wh_id
		,@v_vchOrderStatus = ibMS.order_status
		,@v_vchOrderType = ibMS.order_type
	FROM t_wms_inbound_master ibMS
	INNER JOIN t_wms_owner own ON ibMS.owner_id = own.owner_id
	WHERE ibMS.inbound_order_master_id = @in_vchInboundMasterID

	IF (ISNULL(@v_vchInboundOrderNumber,'') = '')
		BEGIN
			SET @out_ErrorCode = 'INBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	IF (@v_vchOrderStatus = 'CLOSE')
		BEGIN
			SET @out_ErrorCode = 'INBOUND_ORDER_STATUS_IS_CLOSED';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;				
		END

PRINT 'CHECK RSTG LOCATION'
		----------------------------------------------
		--Check Location
		----------------------------------------------
		SELECT TOP 1 @v_vchLocationID = location_id
			, @v_vchLocation = location
			, @v_vchLPNControl = lpn_controlled
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWhMasterID
		AND loc_type = 'RSTG' 
		AND is_active = 'YES'

		IF @v_vchLocationID is null
		BEGIN
			--Auto Receipt จะต้องกำหนดข้อมูลให้ครบจึงจะสามารถรับได้
			SET @out_ErrorCode = 'NOT_FOUND_RECEIPT_STAGING';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

PRINT 'CHECK ITEM CONTROL IN ORDER'
		-------------------------------------------------------------------------------
		--Validate Check Data
		--Auto Receipt จะต้องกำหนดข้อมูล lot,exp,sn,attr1-5 ให้ครบ ถ้า item นั้น control
		--Arm storng : คำนวณ expiry date from create date
		-------------------------------------------------------------------------------
		IF EXISTS (SELECT inbound_order_detail_id 
				   FROM (SELECT ibDT.inbound_order_detail_id
							,ibDT.lpn
							,ibDT.lot_number
							,ibDT.expiry_date
							,ibDT.serial_number
							,ibDT.attribute1
							,ibDT.attribute2
							,ibDT.attribute3
							,ibDT.attribute4
							,ibDT.attribute5
							,(CASE WHEN (item.lot_control = 'FULL' AND ISNULL(ibDT.lot_number,'') = '')
									  --OR (item.expiry_date_control = 'FULL' AND ISNULL(ibDT.expiry_date,'') = '')	
									  OR (item.sn_control = 'FULL' AND ISNULL(ibDT.serial_number,'') = '')
									  OR (item.attribute1_control = 'FULL' AND ISNULL(ibDT.attribute1,'') = '')
									  OR (item.attribute2_control = 'FULL' AND ISNULL(ibDT.attribute2,'') = '')
									  OR (item.attribute3_control = 'FULL' AND ISNULL(ibDT.attribute3,'') = '')
									  OR (item.attribute4_control = 'FULL' AND ISNULL(ibDT.attribute4,'') = '')
									  OR (item.attribute5_control = 'FULL' AND ISNULL(ibDT.attribute5,'') = '')
									  OR (@v_vchLPNControl = 'YES' AND ISNULL(ibDT.lpn,'') = '')
								   THEN 'ERROR' ELSE 'NORMAL' END) AS data_status
						 FROM t_wms_inbound_detail ibDT
						 LEFT JOIN t_wms_wh_item whItem ON ibDT.wh_item_master_id = whItem.wh_item_master_id
						 LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
						 WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
					    ) InboundDT
					WHERE data_status = 'ERROR')
				BEGIN
					--Auto Receipt จะต้องกำหนดข้อมูลให้ครบจึงจะสามารถรับได้
					SET @out_ErrorCode = 'INBOUND_DATA_NOT_COMPLETE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

	BEGIN TRANSACTION TRAN_AUTO_RECEIPT;
	SET @v_vchBeginTrans = 1;

		------------------------------------------------
		--SET Receipt Number
		------------------------------------------------
		SET	@v_vchReceiptNumber = @v_vchInboundOrderNumber + '-001'
		SELECT @v_vchReceiptHeaderID = receipt_header_id FROM t_wms_receipt_header WHERE inbound_order_master_id = @in_vchInboundMasterID AND receipt_number = @v_vchReceiptNumber
		IF @v_vchReceiptHeaderID is null
			BEGIN
				SET @v_vchReceiptHeaderID = NEWID();
				--Insert Receipt Header
				INSERT INTO [dbo].[t_wms_receipt_header]
						   ([receipt_header_id]
						   ,[inbound_order_master_id]
						   ,[receipt_number]
						   ,[receipt_status]
						   ,[create_date]
						   ,[create_by])
					 VALUES
						   (@v_vchReceiptHeaderID
						   ,@in_vchInboundMasterID
						   ,@v_vchReceiptNumber
						   ,'OPEN'
						   ,GETDATE()
						   ,@in_vchUserID)
			END

	NEXT_RECEIPT_ITEM:
		SET @v_vchInboundDetailID = NULL
		SET @v_vchWhItemMasterID = NULL
		SET	@v_vchItemUomID    = NULL 	
		SET @v_fltQtyReceive   = NULL
		SET @v_vchLPN		   = NULL
		SET @v_vchLotNumber	   = NULL
		SET @v_vchExpiryDate   = NULL
		SET @v_vchSerialNumber = NULL
		SET @v_vchAttribute1   = NULL
		SET @v_vchAttribute2   = NULL
		SET @v_vchAttribute3   = NULL
		SET @v_vchAttribute4   = NULL
		SET @v_vchAttribute5   = NULL
		SET @in_vchInvStatusID = NULL

		SELECT TOP 1 @v_vchInboundDetailID = ibDT.inbound_order_detail_id
			,@v_vchWhItemMasterID = ibDT.wh_item_master_id
			,@v_fltQtyReceive	= ROUND(ISNULL(ibDT.quantity_order,0),@Round) - ROUND(ISNULL(ibDT.quantity_receive,0),@Round)
			,@v_vchItemUomID	= ibDT.item_uom_id
			,@v_vchLpn			= ibDT.lpn
			,@v_vchLotNumber	= ibDT.lot_number
			,@v_vchExpiryDate	= (CASE WHEN item.expiry_date_control = 'FULL' THEN CONVERT(VARCHAR(8),DATEADD(DAY,ISNULL(item.days_to_expire,0), ibDT.create_date),112) ELSE NULL END)
			,@v_vchSerialNumber	= ibDT.serial_number
			,@v_vchAttribute1	= ibDT.attribute1
			,@v_vchAttribute2	= ibDT.attribute2
			,@v_vchAttribute3	= ibDT.attribute3
			,@v_vchAttribute4	= ibDT.attribute4
			,@v_vchAttribute5	= ibDT.attribute5
			,@in_vchInvStatusID = invST.inventory_status_id
		FROM t_wms_inbound_detail ibDT
		INNER JOIN t_wms_inventory_status invST on ibDT.default_item_status = invST.inv_status
		INNER JOIN t_wms_item item ON ibDT.item_master_id = item.item_master_id
 		WHERE inbound_order_master_id = @in_vchInboundMasterID
		AND ISNULL(quantity_order,0) - ISNULL(quantity_receive,0) > 0
		ORDER BY ibDT.line_number
		IF @v_vchInboundDetailID IS NOT NULL
			BEGIN
				print 'SAVE'
				EXEC usp_inbound_update_receive_qty @in_vchApplicationID	= @in_vchApplicationID
													,@in_vchDeviceID		= 'AUTO_RECEIPT'
													,@in_vchUserID			= @in_vchUserID
													,@in_vchWhMasterID		= @v_vchWhMasterID
													,@in_vchInboundMasterID	= @in_vchInboundMasterID
													,@in_vchReceiptHeaderID	= @v_vchReceiptHeaderID
													,@in_vchLocationID		= @v_vchLocationID
													,@in_vchInvStatusID		= @in_vchInvStatusID
													,@in_vchWhItemMasterID	= @v_vchWhItemMasterID
													,@in_fltQuantity		= @v_fltQtyReceive
													,@in_vchItemUomID		= @v_vchItemUomID
													,@in_vchLot				= @v_vchLotNumber
													,@in_vchExpiryDate		= @v_vchExpiryDate
													,@in_vchSerial			= @v_vchSerialNumber
													,@in_vchParentLPN		= NULL
													,@in_vchLPN				= @v_vchLpn
													,@in_vchReasonCode		= NULL
													,@in_vchAttribute1		= @v_vchAttribute1
													,@in_vchAttribute2		= @v_vchAttribute2
													,@in_vchAttribute3		= @v_vchAttribute3
													,@in_vchAttribute4		= @v_vchAttribute4
													,@in_vchAttribute5		= @v_vchAttribute5
													,@in_dtReceiveDate		= @v_dtReceiveDate
													,@in_dtMfgDate			= NULL
													,@out_ErrorCode			= @out_ErrorCode OUTPUT
													,@out_ErrorMessage		= @out_ErrorMessage OUTPUT

				IF @out_ErrorCode <> '0'
					BEGIN
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInboundOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				--ถ้ายังมีข้อมูลให้ทำการรับให้วนกลับไปรับต่อ
				IF EXISTS (SELECT ibDT.inbound_order_detail_id FROM t_wms_inbound_detail ibDT WHERE inbound_order_master_id = @in_vchInboundMasterID AND ISNULL(quantity_order,0) - ISNULL(quantity_receive,0) > 0)
					BEGIN
						GOTO NEXT_RECEIPT_ITEM;
					END
			END

		COMMIT TRANSACTION TRAN_AUTO_RECEIPT;
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
		RETURN;

	WRITE_PROC:
		BEGIN
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION TRAN_AUTO_RECEIPT;
															
			SET @v_dtProcessDateTime = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @out_ErrorCode,
				@in_vchData2 = @out_ErrorMessage,
				@in_vchData3 = @v_vchInboundOrderNumber,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage 
		END
END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 0)
		ROLLBACK TRANSACTION TRAN_AUTO_RECEIPT;
			
	IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	SET @v_dtProcessDateTime = GETDATE();
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @out_ErrorCode,
		@in_vchData2 = @out_ErrorMessage,
		@in_vchData3 = @v_vchInboundOrderNumber,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_insert_dock_door_stg]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_insert_dock_door_stg]
(
	@v_vchWhID			varchar(50),
	@v_vchLocation		varchar(50),
	@v_vchDockDoor		varchar(50)
)
AS
begin declare @v_vchLocationID	varchar(40),
	@v_vchDockDoorID	varchar(40),
	@v_vchWhMasterID	varchar(40),
	@v_vchMessage		nvarchar(500)

select @v_vchWhMasterID = wh_master_id from t_wms_wh where wh_id = @v_vchWhID
	 
select @v_vchLocationID = location_id from t_wms_location where location = @v_vchLocation and loc_type = 'STG' and wh_master_id = @v_vchWhMasterID
select @v_vchDockDoorID = location_id from t_wms_location where location = @v_vchDockDoor and loc_type = 'door' and wh_master_id = @v_vchWhMasterID

IF ISNULL(@v_vchLocationID,'') = ''
BEGIN
	SET @v_vchMessage = 'Location STG ไม่ถูกต้อง'
	return;
END


IF ISNULL(@v_vchDockDoorID,'') = ''
BEGIN
	SET @v_vchMessage = 'Location Dock Door ไม่ถูกต้อง'
	return;
END

IF NOT EXISTS (SELECT stage_dock_door_id FROM t_wms_dock_door_staging 
				WHERE staging_location_id = @v_vchLocationID AND dock_door_location_id = @v_vchDockDoorID)
	BEGIN
		INSERT INTO t_wms_dock_door_staging
		(
			stage_dock_door_id
			,dock_door_location_id
			,staging_location_id
			,description
			,is_active
			,create_by
			,create_date
		)
		VALUES
		(
			NEWID()
			,@v_vchDockDoorID
			,@v_vchLocationID
			,NULL
			,'YES'
			,'USER'
			,GETDATE()
		)
	END
ELSE
	BEGIN
		SET @v_vchMessage = 'มีข้อมูล LOCATION ['+@v_vchLocation+'] และ Dock Door ['+@v_vchDockDoor+'] นี้แล้ว'
	END
END

GO
/****** Object:  StoredProcedure [dbo].[usp_insert_json_logs]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Thawatchai
-- Create date: 14 Nov 2024
-- Description:	Insert Json Logs
-- =============================================
CREATE PROCEDURE [dbo].[usp_insert_json_logs] 
	-- Add the parameters for the stored procedure here
	@in_vchWhId nvarchar(25) = '',
	@in_vchPlantCode varchar(4) = '',
	@in_vchActionKey uniqueidentifier = null ,
	@in_vchOrderNumber nvarchar(30) = '',
	@in_vchFunctionName varchar(50) = '',
	@in_vchFromApp varchar(20) = '',
	@in_vchActionType varchar(30) = '',
	@in_vchJsonString nvarchar(MAX) = '',
	@in_vchXmlString nvarchar(MAX) = '',
	@in_vchMessageLog nvarchar(MAX) = '',
	@in_vchSqlCommand nvarchar(MAX) = '',
	@in_vchUrl varchar(800) = '',
	@in_vchCreateBy nvarchar(50) = '',
	@out_vchErrorCode			NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	BEGIN TRY
		INSERT INTO dbo.t_com_json_log 
		(wh_id,
		plant_code,
		action_key,
		order_number,
		function_name,
		from_app,
		action_type,
		json_string,
		xml_string,
		message_log,
		sql_command,
		url,
		create_by)
		VALUES
		(@in_vchWhId,
		@in_vchPlantCode,
		@in_vchActionKey,
		@in_vchOrderNumber,
		@in_vchFunctionName,
		@in_vchFromApp,
		@in_vchActionType,
		@in_vchJsonString,
		@in_vchXmlString,
		@in_vchMessageLog,
		@in_vchSqlCommand,
		@in_vchUrl,
		@in_vchCreateBy)
		SET @out_vchErrorCode = '000'
		SET @out_vchErrorMessage = 'SUCCESS'
	END TRY
	BEGIN CATCH
		SET @out_vchErrorCode = '900'
		SET @out_vchErrorMessage = 'Insert json logs faild'
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_insert_transaction]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_insert_transaction]
AS
	BEGIN
		DECLARE @v_vchWhID					NVARCHAR(50),
				@v_vchTranType				NVARCHAR(20),
				@v_vchSubTranType			NVARCHAR(20),
				@v_vchDesctiption			NVARCHAR(250),
				@v_vchTranLog				NVARCHAR(3),
				@v_vchProcessLog			NVARCHAR(3),
				@v_vchWinEventViewer		NVARCHAR(3),
				@v_vchHostInterfaceManager	NVARCHAR(3),
				@v_vchInterfaceImmediate	NVARCHAR(3),
				@in_vchApplication			VARCHAR(40)		= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'
		---------------------------------------------------------------
		--update ข้อมุลที่อยุ่ตอนนี้ทั้งหมด เพื่อเวลา Insert Recorde ใหม่จะได้ลบข้อมูลถูก
		UPDATE t_com_transaction SET create_by = 'delete'
		---------------------------------------------------------------
		declare @v_vchTranWh nvarchar(25) = ''
		select top 1 @v_vchTranWh = wh_id from t_com_transaction
		DECLARE WH_CURSOR CURSOR FOR
			SELECT wh_id FROM t_wms_wh WHERE is_active = 'YES' 
		OPEN WH_CURSOR
		FETCH NEXT FROM WH_CURSOR INTO @v_vchWhID
		WHILE @@FETCH_STATUS = 0 
			BEGIN
				--
				DECLARE TRANTYPE_CURSOR CURSOR FOR
					SELECT DISTINCT tran_type
						, sub_tran_type
						, description
						, tran_log
						, process_log
						, win_event_viewer
						, host_interface_manager
						, interface_immediate 
					FROM t_com_transaction 
					--WHERe wh_id = @v_vchTranWh
				OPEN TRANTYPE_CURSOR
				FETCH NEXT FROM TRANTYPE_CURSOR INTO @v_vchTranType,@v_vchSubTranType,@v_vchDesctiption,@v_vchTranLog,@v_vchProcessLog,@v_vchWinEventViewer,@v_vchHostInterfaceManager,@v_vchInterfaceImmediate	
				WHILE @@FETCH_STATUS = 0
					BEGIN 
						INSERT INTO [dbo].[t_com_transaction]
							   ([transaction_id]
							   ,[app_id]
							   ,[wh_id]
							   ,[tran_type]
							   ,[sub_tran_type]
							   ,[description]
							   ,[tran_log]
							   ,[process_log]
							   ,[win_event_viewer]
							   ,[host_interface_manager]
							   ,[interface_immediate]
							   ,[interface_when_tran]
							   ,[is_active]
							   ,[create_date]
							   ,[create_by])
						 VALUES
							   (NEWID()
							   ,@in_vchApplication
							   ,@v_vchWhID
							   ,@v_vchTranType
							   ,@v_vchSubTranType
							   ,@v_vchDesctiption
							   ,@v_vchTranLog
							   ,@v_vchProcessLog
							   ,@v_vchWinEventViewer
							   ,@v_vchHostInterfaceManager
							   ,@v_vchInterfaceImmediate
							   ,NULL
							   ,'YES'
							   ,GETDATE()
							   ,'SYSTEM')
						FETCH NEXT FROM TRANTYPE_CURSOR INTO @v_vchTranType,@v_vchSubTranType,@v_vchDesctiption,@v_vchTranLog,@v_vchProcessLog,@v_vchWinEventViewer,@v_vchHostInterfaceManager,@v_vchInterfaceImmediate	
					END
				CLOSE TRANTYPE_CURSOR
				DEALLOCATE TRANTYPE_CURSOR
				FETCH NEXT FROM WH_CURSOR INTO @v_vchWhID
			END
		CLOSE WH_CURSOR
		DEALLOCATE WH_CURSOR

		---------------------------------------------------------------
		--delete ข้อมูลเดิมออกทั้งหมด
		DELETE t_com_transaction WHERE create_by = 'delete'
		---------------------------------------------------------------
	END

	--select * from t_com_transaction
/*
EXEC usp_insert_transaction
*/ 
GO
/****** Object:  StoredProcedure [dbo].[usp_InsertHostItemCrossRef]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_InsertHostItemCrossRef]
(
	@v_vchHostRecordID		VARCHAR(40),
	@v_vchHostRecordType	NVARCHAR(10) = 'MASTER',
	@v_vchProcessCode		NVARCHAR(40) = 'ADD',
	@v_vchProcessStatus 	NVARCHAR(40) = 'PENDING',
	@v_vchItemNumber        NVARCHAR(50),
	@v_vchOwnerID			NVARCHAR(40),
	@altItemID				NVARCHAR(40),
	@IsActive				NVARCHAR(3),
	@v_vchUserID            NVARCHAR(10) = 'OGA-Mai'
)
AS
BEGIN
	INSERT INTO t_host_wms_item_crossref
	(
		host_record_id
		,record_type
		,processing_code
		,processing_status
		,item_number
		,owner_id
		,alternate_item_number
		,is_active
		,create_date
		,create_by
	)
	VALUES
