/****** Object:  StoredProcedure [dbo].[usp_interface_movement_issue_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_interface_movement_issue_export]
AS
BEGIN
	DECLARE @v_vchHostRecordID	VARCHAR(40),
			@v_vchDateTime		VARCHAR(20) = '',
			@v_vchFileName		NVARCHAR(100) = '',
			@v_vchPath			NVARCHAR(100) = '',
			@v_vchPathFile		NVARCHAR(255) = '',
			@v_vchServerName		VARCHAR(25),-- '10.10.60.199', 
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50),
			@v_vchTranType			NVARCHAR(25) = NULL,	
	        @v_vchCompleteFileName	NVARCHAR(100) = ''

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder
	
	--กำหนด Permission
	--SET @PermissionWriteFile = 'net use I: '+ @v_vchPath + ' ' + @WindowPassword + ' /user:' + @WindowLogin + ' /persistent:yes'
	
	IF EXISTS (SELECT record_id FROM t_host_wms_trans_export WHERE processing_status = 'PENDING' AND tran_type IN ('BLIND_PICK','INV_ADJUST') AND sub_tran_type IN ('CONFIRM_SHIP','ADJUST_OUT_TO_SAP','CONFIRM_TO_ERP'))
		BEGIN
			BEGIN TRY
			ISSUE_EXPORT:  

				--Blind Pick ที่จะ Export	
				SET @v_vchHostRecordID = NULL			
				SET @v_vchTranType = NULL
				SELECT TOP 1 @v_vchHostRecordID = host_record_id, @v_vchTranType = tran_type FROM t_host_wms_trans_export WHERE processing_status = 'PENDING' AND tran_type IN ('BLIND_PICK','INV_ADJUST') AND sub_tran_type IN ('CONFIRM_SHIP','ADJUST_OUT_TO_SAP','CONFIRM_TO_ERP') ORDER BY create_date
				IF ISNULL(@v_vchHostRecordID,'') <> ''
					BEGIN
						UPDATE t_host_wms_trans_export set processing_status = 'IN PROCESS' WHERE host_record_id = @v_vchHostRecordID
					
						SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
						SET @v_vchFileName = 'ADJ_' + @v_vchDateTime + '_' + @v_vchHostRecordID + '.txt'
						SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName

						-- Write file
						DECLARE @BulkCol	 NVARCHAR(2500) = '' 
						DECLARE @TextWrite	 NVARCHAR(MAX) = ''

						--เตรียมข้อมูลสำหรับ Export
						IF @v_vchTranType = 'BLIND_PICK'
							BEGIN
								--กรณีที่เป็น Blind Pick ให้เอา Location จาก UDf1 มา Join แทน
								SELECT 'TRAN-ADD'
								+'|'+ ISNULL(tExport.host_record_id,'')
								+'|'+ ISNULL(tExport.processing_code,'')
								+'|'+ 'PENDING'
								+'|'+ (CASE WHEN tExport.posting_date IS NULL THEN '' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,tExport.posting_date),'MMddyyyy')) END) 
								+'|'+ ISNULL(locMap.ax_location,'')
								+'|'+ ISNULL(tExport.item_number,'')
								+'|'+ CONVERT(VARCHAR,ISNULL(tExport.quantity,''))
								+'|'+ ISNULL(tExport.quantity_uom,'')
								+'|'+ ISNULL(tExport.user_def1,'')
								+'|'+ ISNULL(tExport.user_def2,'')
								+'|'+ '1' AS BulkCol
								INTO  #tHostInterfaceBlind 
								FROM t_host_wms_trans_export tExport
								LEFT JOIN t_wms_location_mapping locMap ON tExport.user_def4 = locMap.wms_location 
								WHERE tExport.host_record_id = ISNULL(@v_vchHostRecordID,'')

								DECLARE InterfaceCursor CURSOR FOR
									SELECT BulkCol FROM #tHostInterfaceBlind 
								OPEN InterfaceCursor 
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
								WHILE @@FETCH_STATUS = 0
									BEGIN
										-- begin for list instruction set
										SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
										-- end for list instruction set         
										FETCH NEXT FROM InterfaceCursor INTO @BulkCol
									END
								CLOSE InterfaceCursor   
								DEALLOCATE InterfaceCursor 	
								
								IF OBJECT_ID('tempdb..#tHostInterfaceBlind') IS NOT NULL
									DROP TABLE #tHostInterfaceBlind	
							END
						ELSE
							BEGIN
								SELECT 'TRAN-ADD'
								+'|'+ ISNULL(tExport.host_record_id,'')
								+'|'+ ISNULL(tExport.processing_code,'')
								+'|'+ 'PENDING'
								+'|'+ (CASE WHEN tExport.start_tran_datetime IS NULL THEN '' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,tExport.start_tran_datetime),'MMddyyyy')) END) 
								+'|'+ ISNULL(locMap.ax_location,'')
								+'|'+ ISNULL(tExport.item_number,'')
								+'|'+ CONVERT(VARCHAR,ISNULL(tExport.quantity,''))
								+'|'+ ISNULL(tExport.quantity_uom,'')
								+'|'+ 'IIO'
								+'|'+ ISNULL(tExport.reference_number,'')
								+'|'+ ISNULL(tExport.user_def2,'')
								+'|'+ '1' AS BulkCol
								INTO #tHostInterface
								FROM t_host_wms_trans_export tExport
								LEFT JOIN t_wms_location_mapping locMap ON tExport.location = locMap.wms_location 
								WHERE tExport.host_record_id = ISNULL(@v_vchHostRecordID,'')	

								DECLARE InterfaceCursor CURSOR FOR
									SELECT BulkCol FROM #tHostInterface 
								OPEN InterfaceCursor 
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
								WHILE @@FETCH_STATUS = 0
									BEGIN
										-- begin for list instruction set
										SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
										-- end for list instruction set         
										FETCH NEXT FROM InterfaceCursor INTO @BulkCol
									END
								CLOSE InterfaceCursor   
								DEALLOCATE InterfaceCursor 

								IF OBJECT_ID('tempdb..#tHostInterface') IS NOT NULL
									DROP TABLE #tHostInterface
							END
						
						--print @TextWrite
						SET @v_vchCompleteFileName = ''
						IF ISNULL(@TextWrite,'') <> '' 
							BEGIN
								EXEC [dbo].[sp_create_text] @File = @v_vchPathFile,@Text = @TextWrite
								SET @v_vchCompleteFileName = @v_vchFileName
								UPDATE t_host_wms_trans_export set processing_status = 'COMPLETE',file_name_export = @v_vchFileName WHERE host_record_id = @v_vchHostRecordID
							END
						ELSE
							BEGIN
								UPDATE t_host_wms_trans_export set processing_status = 'ERROR-NO DATA' WHERE host_record_id = @v_vchHostRecordID
							END 
					END

				IF EXISTS (SELECT record_id	 FROM t_host_wms_trans_export WHERE processing_status = 'PENDING' AND tran_type IN ('BLIND_PICK','INV_ADJUST') AND sub_tran_type IN ('CONFIRM_SHIP','ADJUST_OUT_TO_SAP'))
					GOTO ISSUE_EXPORT;
				ELSE	
					RETURN;
			END TRY
			BEGIN CATCH
				DECLARE @error NVARCHAR(500)
				SET @error = ERROR_MESSAGE()
				UPDATE t_host_wms_trans_export set processing_status = 'ERROR', user_def6 = LEFT(@error,100),file_name_export = @v_vchCompleteFileName WHERE host_record_id = @v_vchHostRecordID
			END CATCH
		END
END
GO
