/****** Object:  StoredProcedure [dbo].[usp_interface_movement_tranfer_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_movement_tranfer_export] 
AS
BEGIN
	DECLARE @v_vchHostRecordID	VARCHAR(40),
			@v_vchDateTime		VARCHAR(20) = '',
			@v_vchFileName		NVARCHAR(100) = '',
			@v_vchPath			NVARCHAR(100) = '',
			@v_vchPathFile		NVARCHAR(255) = '',
			@v_vchServerName	VARCHAR(25), -- = '10.60.10.103',
			@PermissionWriteFile	NVARCHAR(250),
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50),	
	        @v_vchCompleteFileName	NVARCHAR(100) = ''
			

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder

	IF EXISTS (SELECT record_id FROM t_host_wms_trans_export WHERE tran_type = 'INV_MOVE' AND sub_tran_type IN ('MOVE_ON_PC','MOVE_DEST','MOVE_SOURCE') AND processing_status = 'PENDING')
		BEGIN
			BEGIN TRY
			TRANFER_EXPORT: 

				--Movement ID ที่จะ Export
				SET @v_vchHostRecordID = NULL
				SELECT TOP 1 @v_vchHostRecordID = host_record_id FROM t_host_wms_trans_export WHERE tran_type = 'INV_MOVE' AND sub_tran_type IN ('MOVE_ON_PC','MOVE_DEST','MOVE_SOURCE') AND processing_status = 'PENDING' ORDER BY create_date
				IF ISNULL(@v_vchHostRecordID,'') <> ''
					BEGIN
						UPDATE t_host_wms_trans_export SET processing_status = 'IN PROCESS' WHERE host_record_id = @v_vchHostRecordID			
				
						SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
						SET @v_vchFileName = 'TRF_' + @v_vchDateTime + '_' + @v_vchHostRecordID + '.txt'
						SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName
						
						--เตรียมข้อมูลสำหรับ Export
						SELECT 'TRAN-ADD'
						+'|'+ ISNULL(tTran.host_record_id,'')
						+'|'+ ISNULL(tTran.processing_code,'')
						+'|'+ 'PENDING'
						+'|'+ (CASE WHEN tTran.start_tran_datetime IS NULL THEN '' ELSE CONVERT(VARCHAR, CONVERT(NVARCHAR, FORMAT(tTran.start_tran_datetime,'MMddyyyy'))) END)
						+'|'+ ISNULL(locMap.ax_location,'')
						+'|'+ ISNULL(locToMap.ax_location,'')
						+'|'+ ISNULL(tTran.item_number,'')
						+'|'+ (CASE WHEN ISNULL(tTran.interface_plan_uom,'') = '' THEN CONVERT(VARCHAR,ISNULL(tTran.quantity,'')) ELSE CONVERT(VARCHAR,ISNULL(tTran.interface_quantity,'')) END)
						+'|'+ (CASE WHEN ISNULL(tTran.interface_plan_uom,'') = '' THEN ISNULL(tTran.quantity_uom,'') ELSE ISNULL(tTran.interface_plan_uom,'') END)
						+'|'+ 'ITF'
						+'|'+ ISNULL(tTran.user_def2,'') AS BulkCol
						INTO #tHostInterface
						FROM t_host_wms_trans_export tTran
						LEFT JOIN t_wms_location_mapping locMap ON tTran.location = locMap.wms_location 
						LEFT JOIN t_wms_location_mapping locToMap ON tTran.to_location = locToMap.wms_location 
						WHERE tTran.host_record_id =  ISNULL(@v_vchHostRecordID,'') 				
					
						-- Write file
						DECLARE @BulkCol	 NVARCHAR(2500) = '' 
						DECLARE @TextWrite	 NVARCHAR(MAX) = ''
						 
						DECLARE InterfaceCursor CURSOR FOR
							SELECT BulkCol FROM #tHostInterface 
						OPEN InterfaceCursor 
						FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
						WHILE @@FETCH_STATUS = 0
							BEGIN
								-- begin for list instruction set
								SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
								-- end for list instruction set         
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol
							END
						CLOSE InterfaceCursor   
						DEALLOCATE InterfaceCursor

						IF OBJECT_ID('tempdb..#tHostInterface') IS NOT NULL
							DROP TABLE #tHostInterface

						--print @TextWrite
						SET @v_vchCompleteFileName = ''
						IF ISNULL(@TextWrite,'') <> ''
							BEGIN
								EXEC [dbo].[sp_create_text] @File = @v_vchPathFile,@Text = @TextWrite
								SET @v_vchCompleteFileName = @v_vchFileName
								UPDATE t_host_wms_trans_export set processing_status = 'COMPLETE',file_name_export = @v_vchFileName WHERE host_record_id = @v_vchHostRecordID
							END
						ELSE
							BEGIN
								UPDATE t_host_wms_trans_export set processing_status = 'ERROR-NO DATA' WHERE host_record_id = @v_vchHostRecordID
							END 
					END

				IF EXISTS (SELECT record_id FROM t_host_wms_trans_export WHERE tran_type = 'INV_MOVE' AND sub_tran_type IN ('MOVE_ON_PC','MOVE_DEST','MOVE_SOURCE') AND processing_status = 'PENDING')
					GOTO TRANFER_EXPORT;
				ELSE	
					RETURN;
			END TRY
			BEGIN CATCH
				DECLARE @error NVARCHAR(500)
				SET @error = ERROR_MESSAGE()
				UPDATE t_host_wms_trans_export set processing_status = 'ERROR', user_def6 = LEFT(@error,100) WHERE host_record_id = @v_vchHostRecordID
			END CATCH
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_interface_process_log]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_process_log]
(
	@in_vchDevice		NVARCHAR(50) ='',
	@in_vchLogType		VARCHAR(25) = '',
	@in_vchProcessType	NVARCHAR(50) ='',
	@in_vchResultStatus	NVARCHAR(50) ='',
	@in_vchFileName		NVARCHAR(250)='',
	@in_vchPathFile		NVARCHAR(1000)='',
	@in_vchErrorCode	NVARCHAR(1000)='',
	@in_vchErrorMessage	NVARCHAR(1000)='',
	@in_vchRecordNumber NVARCHAR(50) = '', 
	@in_vchErrorType	NVARCHAR(50) = ''	--SP_ERROR,FILE_ERROR
)
AS
BEGIN
	INSERT INTO [dbo].[t_interface_process_log_result]
			([log_result_id]
			,[log_type]
			,[interface_process]
			,[result_status]
			,[error_code]
			,[error_msg]
			,[description]
			,[file_name]
			,[path_file]
			,[device]
			,[create_date])
		VALUES
			(NEWID()
			,@in_vchLogType
			,@in_vchProcessType
			,@in_vchResultStatus
			,@in_vchErrorCode
			,ISNULL(dbo.usf_get_locale_text_value(@in_vchErrorCode, '1033'), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			,@in_vchErrorMessage 
			,@in_vchFileName
			,@in_vchPathFile
			,@in_vchDevice
			,GETDATE())
END	
GO
/****** Object:  StoredProcedure [dbo].[usp_interface_receipt_confirm_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_receipt_confirm_export]
AS
BEGIN
	DECLARE @v_vchReceiptID		VARCHAR(40),
			@v_vchDateTime		VARCHAR(20) = '',
			@v_vchFileName		NVARCHAR(100) = '',
			@v_vchPath			NVARCHAR(100) = '',
			@v_vchPathFile		NVARCHAR(255) = '',
			@v_vchServerName		VARCHAR(25),-- '10.10.60.199',
			@PermissionWriteFile	NVARCHAR(250),
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50),	
	        @v_vchCompleteFileName	NVARCHAR(100) = ''	

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder
	
	--กำหนด Permission
	--SET @PermissionWriteFile = 'net use I: '+ @v_vchPath + ' ' + @WindowPassword + ' /user:' + @WindowLogin + ' /persistent:yes'

	IF EXISTS (SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING' AND order_type <> 'OTHER' AND order_status = 'RECEIVING')
		BEGIN
			BEGIN TRY
			RECEIPT_EXPORT:
				
				--Receipt ID ที่จะ Export
				SET @v_vchReceiptID = NULL
				SELECT TOP 1 @v_vchReceiptID = receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING' AND order_type <> 'OTHER' AND order_status = 'RECEIVING' ORDER BY create_date
				
				IF ISNULL(@v_vchReceiptID,'') <> ''
					BEGIN
						UPDATE t_host_wms_receipt_conf_header_export set processing_status = 'IN PROCESS' WHERE receipt_id = @v_vchReceiptID
						UPDATE t_host_wms_receipt_conf_detail_export set processing_status = 'IN PROCESS' WHERE receipt_id = @v_vchReceiptID
				
						SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
						SET @v_vchFileName = 'REC_' + @v_vchDateTime + '_' + ISNULL(@v_vchReceiptID,'') + '.txt'
						SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName

						--เตรียมข้อมูลสำหรับ Export
						SELECT BulkCol INTO #tHostInterface
						FROM (SELECT 'IBD-HEADER-ADD'
							+'|'+ISNULL(receipt_id,'')
							+'|'+ISNULL(processing_code,'')
							+'|'+'PENDING'
							+'|'+ISNULL(owner_id,'')
							+'|'+ISNULL(order_type,'')
							+'|'+ISNULL(supplier_code,'')
							+'|'+ISNULL(inbound_order_number,'')
							+'|'+ISNULL(reference_number,'')
							+'|'+CASE WHEN ISNULL(order_status,'') = 'RECEIVING' THEN 'OPEN'
										WHEN ISNULL(order_status,'') = 'CLOSE' THEN 'CLOSED' ELSE ISNULL(order_status,'') END
							+'|'+(CASE WHEN close_date IS NULL THEN '' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,close_date),'MMddyyyy')) END) AS BulkCol
							FROM t_host_wms_receipt_conf_header_export
							WHERE receipt_id = ISNULL(@v_vchReceiptID,'')
						UNION ALL
							SELECT 'IBD-DETAIL-ADD'
							+'|'+ISNULL(dt.receipt_id,'')
							+'|'+ISNULL(dt.processing_code,'')
							+'|'+'PENDING'
							+'|'+ISNULL(dt.owner_id,'')
							+'|'+ISNULL(dt.inbound_order_number,'')
							+'|'+ISNULL(dt.item_number,'')
							+'|'+ISNULL(dt.uom,'')
							+'|'+CONVERT(VARCHAR,ISNULL(SUM(dt.qty_received),''))
							+'|'+ISNULL(locMap.ax_location,'')
							+'|'+ISNULL(dt.user_def2,'') AS BulkCol
							FROM t_host_wms_receipt_conf_detail_export dt
							LEFT JOIN t_wms_location_mapping locMap ON dt.location = locMap.wms_location
							WHERE dt.receipt_id = ISNULL(@v_vchReceiptID,'')
							GROUP BY dt.receipt_id,dt.processing_code,dt.owner_id,dt.inbound_order_number,dt.item_number,dt.uom,locMap.ax_location,dt.user_def2) AS tExport						
						
						-- Write file
						DECLARE @BulkCol	 NVARCHAR(2500) = '' 
						DECLARE @TextWrite	 NVARCHAR(MAX) = ''
						 
						DECLARE InterfaceCursor CURSOR FOR
							SELECT BulkCol FROM #tHostInterface 
						OPEN InterfaceCursor 
						FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
						WHILE @@FETCH_STATUS = 0
							BEGIN
								-- begin for list instruction set
								SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
								-- end for list instruction set         
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol
							END
						CLOSE InterfaceCursor   
						DEALLOCATE InterfaceCursor

						IF OBJECT_ID('tempdb..#tHostInterface') IS NOT NULL
							DROP TABLE #tHostInterface

						--print @v_vchPathFile
						--print @TextWrite
						SET @v_vchCompleteFileName = ''
						IF ISNULL(@TextWrite,'') <> '' 
							BEGIN
								EXEC [dbo].[sp_create_text] @File = @v_vchPathFile,@Text = @TextWrite
								SET @v_vchCompleteFileName = @v_vchFileName
								UPDATE t_host_wms_receipt_conf_header_export set processing_status = 'COMPLETE',file_name_export = @v_vchFileName WHERE receipt_id = @v_vchReceiptID
								UPDATE t_host_wms_receipt_conf_detail_export set processing_status = 'COMPLETE' WHERE receipt_id = @v_vchReceiptID
							END
						ELSE
							BEGIN
								UPDATE t_host_wms_receipt_conf_header_export set processing_status = 'ERROR-NO DATA' WHERE receipt_id = @v_vchReceiptID
								UPDATE t_host_wms_receipt_conf_detail_export set processing_status = 'ERROR-NO DATA' WHERE receipt_id = @v_vchReceiptID
							END				
					END
				IF EXISTS (SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING' AND order_type <> 'OTHER' AND order_status = 'RECEIVING')
					GOTO RECEIPT_EXPORT;
				ELSE	
					RETURN;
			END TRY
			BEGIN CATCH
				DECLARE @error NVARCHAR(500)
				SET @error = ERROR_MESSAGE()
				UPDATE t_host_wms_receipt_conf_detail_export set processing_status = 'ERROR' WHERE receipt_id = @v_vchReceiptID
				UPDATE t_host_wms_receipt_conf_header_export set processing_status = 'ERROR',user_def6 = LEFT(@error,50)  WHERE receipt_id = @v_vchReceiptID
			END CATCH
		END
END

GO
/****** Object:  StoredProcedure [dbo].[usp_interface_return_receipt_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_return_receipt_export]
AS
BEGIN
	DECLARE @v_vchReceiptID		VARCHAR(40),
			@v_vchDateTime		VARCHAR(20) = '',
			@v_vchFileName		NVARCHAR(100) = '',
			@v_vchPath			NVARCHAR(100) = '',
			@v_vchPathFile		NVARCHAR(255) = '',
			@MySpecialTempTable	NVARCHAR(255) = '',
			@v_vchQueryString	NVARCHAR(4000) = '',
			@v_vchCommand		NVARCHAR(4000) = '',
			@RESULT				INT,
			@Unicode			INT,
			@v_vchServerName		VARCHAR(25),-- '10.10.60.199',
			@PermissionWriteFile	NVARCHAR(250),
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50) 

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder
	
	--กำหนด Permission
	SET @PermissionWriteFile = 'net use I: '+ @v_vchPath + ' ' + @WindowPassword + ' /user:' + @WindowLogin + ' /persistent:yes'

	IF EXISTS (SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING')
		BEGIN
			RECEIPT_EXPORT:
				--Execute Permission
				EXEC XP_CMDSHELL @PermissionWriteFile

				SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
				SET @v_vchFileName = 'REC_' + @v_vchDateTime + '.txt'
				SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName
				SELECT @MySpecialTempTable = '##temp' + CONVERT(VARCHAR(12), CONVERT(INT, RAND() * 1000000))
				
				--Receipt ID ที่จะ Export
				SET @v_vchReceiptID = NULL
				SELECT TOP 1 @v_vchReceiptID = receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING' ORDER BY create_date
				IF ISNULL(@v_vchReceiptID,'') <> ''
					BEGIN
						UPDATE t_host_wms_receipt_conf_header_export set processing_status = 'COMPLETE' WHERE receipt_id = @v_vchReceiptID
						UPDATE t_host_wms_receipt_conf_detail_export set processing_status = 'COMPLETE' WHERE receipt_id = @v_vchReceiptID
				
--เตรียมข้อมูลสำหรับ Export
SET @v_vchQueryString ='SELECT BulkCol INTO ' + @MySpecialTempTable + ' FROM (SELECT ''IBD-HEADER-ADD''
+''|''+ISNULL(receipt_id,'''')
+''|''+ISNULL(processing_code,'''')
+''|''+''PENDING''
+''|''+ISNULL(owner_id,'''')
+''|''+ISNULL(order_type,'''')
+''|''+ISNULL(supplier_code,'''')
+''|''+ISNULL(inbound_order_number,'''')
+''|''+ISNULL(reference_number,'''')
+''|''+CASE WHEN ISNULL(order_status,'''') = ''RECEIVING'' THEN ''OPEN''
			WHEN ISNULL(order_status,'''') = ''CLOSE'' THEN ''CLOSED'' ELSE ISNULL(order_status,'''') END
+''|''+(CASE WHEN create_date IS NULL THEN '''' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,create_date),''MMddyyyy'')) END) AS BulkCol
FROM WM3.dbo.t_host_wms_receipt_conf_header_export
WHERE receipt_id = ''' + @v_vchReceiptID + '''
UNION ALL
SELECT ''IBD-DETAIL-ADD''
+''|''+ISNULL(receipt_id,'''')
+''|''+ISNULL(processing_code,'''')
+''|''+''PENDING''
+''|''+ISNULL(owner_id,'''')
+''|''+ISNULL(inbound_order_number,'''')
+''|''+ISNULL(item_number,'''')
+''|''+ISNULL(uom,'''')
+''|''+CONVERT(VARCHAR,ISNULL(qty_received,''''))
+''|''+''Available''
+''|''+ISNULL(location,'''')
+''|''+ISNULL(user_def2,'''') AS BulkCol
FROM WM3.dbo.t_host_wms_receipt_conf_detail_export
WHERE receipt_id = ''' + @v_vchReceiptID + ''') AS tExport'

						--SELECT 'LEN : ' + CONVERT(VARCHAR,LEN(@v_vchQueryString))
						EXECUTE sp_ExecuteSQL @v_vchQueryString
						SET @Unicode = 1
						SELECT  @v_vchCommand = N'bcp "SELECT BulkCol FROM [' + @MySpecialTempTable + ']'
							+ '" queryout '
							+ ' "'+ @v_vchPathFile + '" '
							+ CASE WHEN @Unicode=0 THEN '-c' ELSE '-w -t' END
							+ ' -T -S' + @v_vchServerName--'dolphinmaii' --@@servername
						SELECT @v_vchCommand

						EXECUTE @RESULT = MASTER..xp_cmdshell @v_vchCommand
						--EXECUTE MASTER..xp_cmdshell @v_vchCommand, NO_OUTPUT
						EXECUTE ('DROP TABLE ' + @MySpecialTempTable )
				
						--Delete Permission
						EXEC XP_CMDSHELL 'net use I: /delete'
					END

				IF EXISTS (SELECT receipt_id FROM t_host_wms_receipt_conf_header_export WHERE processing_status = 'PENDING')
					GOTO RECEIPT_EXPORT;
				ELSE	
					RETURN;
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_interface_return_ship_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--2018-12-26 : พี่หนุ่มให้แก้ไข HD เปลี่ยนเป็น UDf4 และเปลี่ยนจาก Ship เป็น Open
CREATE PROCEDURE [dbo].[usp_interface_return_ship_export]
AS
BEGIN
	DECLARE @v_vchHostShipmentID	VARCHAR(40),
			@v_vchDateTime			VARCHAR(20) = '',
			@v_vchFileName			NVARCHAR(100) = '',
			@v_vchPath				NVARCHAR(100) = '',
			@v_vchPathFile			NVARCHAR(255) = '',
			@v_vchServerName		VARCHAR(25),-- '10.10.60.199',
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50),	
	        @v_vchCompleteFileName	NVARCHAR(100) = ''

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder
	
	--กำหนด Permission
	--SET @PermissionWriteFile = 'net use I: '+ @v_vchPath + ' ' + @WindowPassword + ' /user:' + @WindowLogin + ' /persistent:yes'

	IF EXISTS (SELECT host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type = 'Purchase Order' AND order_status = 'SHIP')
		BEGIN
			BEGIN TRY
			SHIPMENT_EXPORT:
				 
				--Shipment ID ที่จะ Export
				SET @v_vchHostShipmentID = NULL;
				SELECT TOP 1 @v_vchHostShipmentID = host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type = 'Purchase Order' AND order_status = 'SHIP' ORDER BY create_date
				
				IF ISNULL(@v_vchHostShipmentID,'') <> ''
					BEGIN
						UPDATE t_host_wms_ship_conf_header_export set processing_status = 'IN PROCESS' WHERE host_shipment_id = @v_vchHostShipmentID
						UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'IN PROCESS' WHERE host_shipment_id = @v_vchHostShipmentID
				
						SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
						SET @v_vchFileName = 'SHP_' + @v_vchDateTime + '_' + ISNULL(@v_vchHostShipmentID,'') + '.txt'
						SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName 

						--เตรียมข้อมูลสำหรับ Export
						SELECT BulkCol INTO #tHostInterface 
						FROM (SELECT 'OBD-HEADER-ADD'
								+'|'+ISNULL(host_shipment_id,'')
								+'|'+ISNULL(processing_code,'')
								+'|'+'PENDING'
								--+'|'+ISNULL(user_def6,'')
								+'|'+ISNULL(user_def4,'')
								+'|'+ISNULL(owner_id,'')
								+'|'+ISNULL(order_number,'')
								--+'|'+ISNULL(order_status,'')
								+'|'+ISNULL('OPEN','')
								+'|'+ISNULL(order_type,'')
								+'|'+ISNULL(user_def1,'')
								+'|'+CASE WHEN ISNULL(ship_date_actual,'') = '' THEN '' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,ship_date_actual),'MMddyyyy')) END AS BulkCol 
							FROM t_host_wms_ship_conf_header_export 
						WHERE host_shipment_id = ISNULL(@v_vchHostShipmentID,'')
						UNION ALL 
							SELECT 'OBD-DETAIL-ADD'
								+'|'+ISNULL(dt.host_shipment_id,'')
								+'|'+ISNULL(dt.processing_code,'')
								+'|'+'PENDING'
								+'|'+ISNULL(dt.owner_id,'')
								+'|'+ISNULL(dt.order_number,'')
								+'|'+ISNULL(dt.item_number,'')
								+'|'+(CASE WHEN ISNULL(dt.interface_plan_uom,'') = '' THEN ISNULL(dt.uom,'') ELSE ISNULL(dt.interface_plan_uom,'') END)
								+'|'+(CASE WHEN ISNULL(dt.interface_plan_uom,'') = '' THEN CONVERT(VARCHAR,ISNULL(dt.quantity,'')) ELSE CONVERT(VARCHAR,ISNULL(dt.interface_quantity,'')) END)
								+'|'+'Available'
								+'|'+ISNULL(locMap.ax_location,'')
								+'|'+ISNULL(dt.user_def2,'') AS BulkCol 
							FROM t_host_wms_ship_conf_detail_export dt
							LEFT JOIN t_wms_location_mapping locMap ON dt.location = locMap.wms_location
							WHERE dt.host_shipment_id = ISNULL(@v_vchHostShipmentID,'')) AS tExport				
						
						
						-- Write file
						DECLARE @BulkCol	 NVARCHAR(2500) = '' 
						DECLARE @TextWrite	 NVARCHAR(MAX) = ''
						 
						DECLARE InterfaceCursor CURSOR FOR
							SELECT BulkCol FROM #tHostInterface 
						OPEN InterfaceCursor 
						FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
						WHILE @@FETCH_STATUS = 0
							BEGIN
								-- begin for list instruction set
								SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
								-- end for list instruction set         
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol
							END
						CLOSE InterfaceCursor   
						DEALLOCATE InterfaceCursor

						IF OBJECT_ID('tempdb..#tHostInterface') IS NOT NULL
							DROP TABLE #tHostInterface

						--print @TextWrite
						SET @v_vchCompleteFileName = ''
						IF ISNULL(@TextWrite,'') <> ''
							BEGIN
								EXEC [dbo].[sp_create_text] @File = @v_vchPathFile,@Text = @TextWrite
								SET @v_vchCompleteFileName = @v_vchFileName
								UPDATE t_host_wms_ship_conf_header_export set processing_status = 'COMPLETE',file_name_export = @v_vchFileName WHERE host_shipment_id = @v_vchHostShipmentID
								UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'COMPLETE' WHERE host_shipment_id = @v_vchHostShipmentID
							END
						ELSE
							BEGIN
								UPDATE t_host_wms_ship_conf_header_export set processing_status = 'ERROR-NO DATA' WHERE host_shipment_id = @v_vchHostShipmentID
								UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'ERROR-NO DATA' WHERE host_shipment_id = @v_vchHostShipmentID
							END 
					END

				IF EXISTS (SELECT host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type = 'Purchase Order' AND order_status = 'SHIP')
					GOTO SHIPMENT_EXPORT;
				ELSE	
					RETURN;
			END TRY
			BEGIN CATCH
				DECLARE @error NVARCHAR(500)
				SET @error = ERROR_MESSAGE()
				UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'ERROR' WHERE host_shipment_id = @v_vchHostShipmentID
				UPDATE t_host_wms_ship_conf_header_export set processing_status = 'ERROR',department = LEFT(@error,50) WHERE host_shipment_id = @v_vchHostShipmentID
			END CATCH
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_interface_running]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_running]
(
	@in_vchDatamapName			VARCHAR(50),
	@in_vchFieldName			VARCHAR(50),
	@in_vchLastRunningNumber	NVARCHAR(40)
)
AS
BEGIN
	DECLARE @v_vchRunningIDGUID		VARCHAR(40) = NULL
	SELECT @v_vchRunningIDGUID = inf_running_id 
	FROM t_interface_running_number
	WHERE datamap_name = @in_vchDatamapName
	AND field_name = @in_vchFieldName
	
	IF (@v_vchRunningIDGUID IS NULL)
		BEGIN
			INSERT INTO t_interface_running_number
			(  inf_running_id
			  ,datamap_name
			  ,field_name
			  ,last_running_number
			  ,create_date
			  ,create_by
			)
			VALUES
			( NEWID()
			  ,@in_vchDatamapName
			  ,@in_vchFieldName
			  ,@in_vchLastRunningNumber
			  ,GETDATE()
			  ,'INTERFACE'
			)
		END
	ELSE
		BEGIN
			UPDATE t_interface_running_number SET
				datamap_name = @in_vchDatamapName
				,field_name = @in_vchFieldName
				,last_running_number = @in_vchLastRunningNumber
			WHERE inf_running_id = @v_vchRunningIDGUID
		END
END


GO
/****** Object:  StoredProcedure [dbo].[usp_interface_ship_confirm_export]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_interface_ship_confirm_export]
AS
BEGIN
	DECLARE @v_vchHostShipmentID	VARCHAR(40),
			@v_vchDateTime			VARCHAR(20) = '',
			@v_vchFileName			NVARCHAR(100) = '',
			@v_vchPath				NVARCHAR(100) = '',
			@v_vchPathFile			NVARCHAR(255) = '',
			@v_vchServerName		VARCHAR(25),-- '10.10.60.199',
			@WindowLogin			NVARCHAR(50),
			@WindowPassword			NVARCHAR(50),	
	        @v_vchCompleteFileName	NVARCHAR(100) = ''

	SELECT TOP 1 @v_vchPath = export_folder
		, @v_vchServerName = export_server_name
		, @WindowLogin = export_window_user
		, @WindowPassword = export_window_password
	FROM t_interface_folder
	

	IF EXISTS (SELECT host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type <> 'Purchase Order' AND order_status = 'SHIP')
		BEGIN
			BEGIN TRY
			SHIPMENT_EXPORT:
			  
				--Shipment ID ที่จะ Export
				SET @v_vchHostShipmentID = NULL
				SELECT TOP 1 @v_vchHostShipmentID = host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type not in ('Purchase Order', 'Other') AND order_status = 'SHIP' ORDER BY create_date
				
				IF ISNULL(@v_vchHostShipmentID,'') <> ''
					BEGIN
						UPDATE t_host_wms_ship_conf_header_export set processing_status = 'IN PROCESS' WHERE host_shipment_id = @v_vchHostShipmentID
						UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'IN PROCESS' WHERE host_shipment_id = @v_vchHostShipmentID
				
						SET @v_vchDateTime = CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))
						SET @v_vchFileName = 'SHP_' + @v_vchDateTime + '_' + ISNULL(@v_vchHostShipmentID,'') + '.txt'
						SET @v_vchPathFile = @v_vchPath +'\'+ @v_vchFileName

						--เตรียมข้อมูลสำหรับ Export
						SELECT BulkCol INTO #tHostInterface 
						FROM (SELECT 'OBD-HEADER-ADD'
								+'|'+ISNULL(host_shipment_id,'')
								+'|'+ISNULL(processing_code,'')
								+'|'+'PENDING'
								+'|'+ISNULL(customer_id,'')
								+'|'+ISNULL(owner_id,'')
								+'|'+ISNULL(order_number,'')
								+'|'+CASE WHEN ISNULL(order_status,'') = 'SHIP' THEN 'OPEN'
										  WHEN ISNULL(order_status,'') = 'CLOSE' THEN 'CLOSED' ELSE ISNULL(order_status,'') END
								+'|'+ISNULL(order_type,'')
								+'|'+''
								+'|'+CASE WHEN ISNULL(ship_date_actual,'') = '' THEN '' ELSE CONVERT(VARCHAR,FORMAT(CONVERT(DATE,ship_date_actual),'MMddyyyy')) END AS BulkCol 
							FROM t_host_wms_ship_conf_header_export 
							WHERE host_shipment_id = ISNULL(@v_vchHostShipmentID,'')
						UNION ALL 
							SELECT 'OBD-DETAIL-ADD'
								+'|'+ISNULL(dt.host_shipment_id,'')
								+'|'+ISNULL(dt.processing_code,'')
								+'|'+'PENDING'
								+'|'+ISNULL(dt.owner_id,'')
								+'|'+ISNULL(dt.order_number,'')
								+'|'+ISNULL(dt.item_number,'')
								+'|'+(CASE WHEN ISNULL(dt.interface_plan_uom,'') = '' THEN ISNULL(dt.uom,'') ELSE ISNULL(dt.interface_plan_uom,'') END)
								+'|'+(CASE WHEN ISNULL(dt.interface_plan_uom,'') = '' THEN CONVERT(VARCHAR,ISNULL(dt.quantity,'')) ELSE CONVERT(VARCHAR,ISNULL(dt.interface_quantity,'')) END)
								+'|'+ISNULL(dt.status,'')
								+'|'+ISNULL(locMap.ax_location,'')
								+'|'+ISNULL(dt.user_def2,'') AS BulkCol 
							FROM t_host_wms_ship_conf_detail_export dt
							LEFT JOIN t_wms_location_mapping locMap ON dt.location = locMap.wms_location
							WHERE dt.host_shipment_id = ISNULL(@v_vchHostShipmentID,'')) AS tExport		
						
						-- Write file
						DECLARE @BulkCol	 NVARCHAR(2500) = '' 
						DECLARE @TextWrite	 NVARCHAR(MAX) = ''
						 
						DECLARE InterfaceCursor CURSOR FOR
							SELECT BulkCol FROM #tHostInterface 
						OPEN InterfaceCursor 
						FETCH NEXT FROM InterfaceCursor INTO @BulkCol						
						WHILE @@FETCH_STATUS = 0
							BEGIN
								-- begin for list instruction set
								SET @TextWrite = @TextWrite + (@BulkCol+ CHAR(13)+CHAR(10))
								-- end for list instruction set         
								FETCH NEXT FROM InterfaceCursor INTO @BulkCol
							END
						CLOSE InterfaceCursor   
						DEALLOCATE InterfaceCursor

						IF OBJECT_ID('tempdb..#tHostInterface') IS NOT NULL
							DROP TABLE #tHostInterface
						
						SET @v_vchCompleteFileName = ''
						IF ISNULL(@TextWrite,'') <> ''
							BEGIN
								EXEC [dbo].[sp_create_text] @File = @v_vchPathFile,@Text = @TextWrite
								SET @v_vchCompleteFileName = @v_vchFileName
								UPDATE t_host_wms_ship_conf_header_export set processing_status = 'COMPLETE',file_name_export = @v_vchFileName WHERE host_shipment_id = @v_vchHostShipmentID
								UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'COMPLETE' WHERE host_shipment_id = @v_vchHostShipmentID
							END
						ELSE
							BEGIN
								UPDATE t_host_wms_ship_conf_header_export set processing_status = 'ERROR-NO DATA' WHERE host_shipment_id = @v_vchHostShipmentID
								UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'ERROR-NO DATA' WHERE host_shipment_id = @v_vchHostShipmentID
							END
					END

				IF EXISTS (SELECT host_shipment_id FROM t_host_wms_ship_conf_header_export WHERE processing_status = 'PENDING' AND order_type <> 'Purchase Order' AND order_status = 'SHIP')
					GOTO SHIPMENT_EXPORT;
				ELSE	
					RETURN;
			END TRY
			BEGIN CATCH
				DECLARE @error NVARCHAR(500)
				SET @error = ERROR_MESSAGE()
				UPDATE t_host_wms_ship_conf_detail_export set processing_status = 'ERROR' WHERE host_shipment_id = @v_vchHostShipmentID
				UPDATE t_host_wms_ship_conf_header_export set processing_status = 'ERROR',department = LEFT(@error,50)  WHERE host_shipment_id = @v_vchHostShipmentID
			END CATCH
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_adjust_in]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_adjust_in] 
	@in_vchApplicationID		NVARCHAR(40),		
	@in_vchDevice				NVARCHAR(50),		
	@in_vchUserID				NVARCHAR(25),
	@in_vchTransactionType		NVARCHAR(20) = NULL,
	@in_vchSubTranType			NVARCHAR(20) = NULL,
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID				UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID			UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN			NVARCHAR(25)  = NULL,
	@in_vchLPN					NVARCHAR(25)  = NULL,
	@in_vchLotNumber			NVARCHAR(50)  = NULL,
	@in_vchExpiryDate			NVARCHAR(50)  = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL,
	@in_vchSerialNumber			NVARCHAR(100) = NULL,
	@in_fltQty					FLOAT = 0,
	@in_vchItemUomID			UNIQUEIDENTIFIER = NULL,
	@in_vchReasonID				UNIQUEIDENTIFIER = NULL,
	@in_dtReceiveDate			DATE,
	@in_dtMfgDate				DATE,
	@in_vchReferenceNumber		NVARCHAR(50),
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT			
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_inventory_adjust_in]', 
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtStartTranDate			DATETIME,
			@v_dtProcessDateTime		DATETIME,
			@Round						INT,
			@v_vchBeginTran				BIT = 0,
			@v_vchLocal					NVARCHAR(5),

			@v_vchApplicationName		NVARCHAR(100),
			@v_vchHostRecordID			VARCHAR(40),
			@v_vchItemMasterID			UNIQUEIDENTIFIER,
			@v_vchItemNumber			NVARCHAR(50),
			@v_vchWarehouse				NVARCHAR(25),
			@v_vchOwnerCode				NVARCHAR(40),
			@v_vchLocation				NVARCHAR(50),
			@v_vchInvStatus				NVARCHAR(50),
			@v_vchExpiryDateControl		VARCHAR(5), 

			@v_vchInputUomPrompt		NVARCHAR(40),
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20),
			@v_vchIsPrimaryUOM			NVARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,
			@v_fltAfterInvQuantity		FLOAT,
			@v_vchERPDestLocation		NVARCHAR(50)

		DECLARE @v_vchItemIsActive		VARCHAR(3) = NULL
    BEGIN TRY
		SET @v_dtStartTranDate = GETDATE();
		IF @in_vchSubTranType IN ('TO_ERP','NOT_ERP')
		BEGIN
			SET @in_vchSubTranType = 'ADJUST_IN_' + @in_vchSubTranType
		END

		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SET @in_fltQty = ROUND(@in_fltQty,@Round)

		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		ELSE
			SET @in_vchExpiryDate = NULL

		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				SET @out_ErrorCode = 'INFO-QUANTITY-CANNOT-EQUAL-ZERO';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		-- Get & check warehouse
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF(ISNULL(@v_vchWarehouse,'') = '')
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END
			
		-- Get & check owner	
		SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'
		IF(ISNULL(@v_vchOwnerCode,'') = '')
			BEGIN
				SET @out_ErrorCode = 'OWNER_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Get and check location
		SELECT @v_vchLocation = location, @v_vchERPDestLocation = erp_location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		IF (ISNULL(@v_vchLocation,'') = '')
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
				print @out_ErrorMessage
				GOTO WRITE_PROC;
			END

		--Get and check status
		SELECT @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID AND is_active = 'YES'
		IF (ISNULL(@v_vchInvStatus,'') = '')
			BEGIN
				SET @out_ErrorCode = 'STATUS_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInvStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Get wh_item_master_id
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID AND wh_master_id = @in_vchWhMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-- Get and check item, dgcode, 885
		DECLARE @v_vchCheckItemMasterID	UNIQUEIDENTIFIER = NULL
		SELECT @v_vchCheckItemMasterID = it.item_master_id
			, @v_vchItemNumber = it.item_number 
			, @v_vchExpiryDateControl = it.expiry_date_control
			, @v_vchItemIsActive = it.is_active
		FROM t_wms_item it
 		WHERE item_master_id = @v_vchItemMasterID
		AND it.owner_id = @in_vchOwnerID
		IF (@v_vchCheckItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = '106';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC;
			END

		--กรณีที่มีการเก็บ MFG Date เวลา Save ต้อง MFG Date มา ถ้าไม่ส่งมา จะ get inventory เดิมไป  
		IF @v_vchExpiryDateControl = 'FULL'
			BEGIN
				DECLARE @v_dtCheckMfgDate DATE = NULL
				SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
				FROM v_wms_inventory_data_by_id
				WHERE wh_master_id = @in_vchWhMasterID 
				AND owner_id = @in_vchOwnerID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
		
				IF @in_dtMfgDate <> @v_dtCheckMfgDate
					BEGIN
						SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY_PARAM';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_dtMfgDate,@v_dtCheckMfgDate,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--Get & Check Item UOM
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUomPrompt  = uom_prompt
			,@v_vchInputUomPrompt = uom_prompt
			,@v_vchBaseUom = uom
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUomID

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchBaseUom = uom
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END
		
		IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_ErrorCode = '107';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
			Goto WRITE_PROC
		END

		SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);
		
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
		BEGIN TRANSACTION
		SET @v_vchBeginTran = 1;
			
		--Manage Inventory
		EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
								 ,@in_vchWhMasterID			= @in_vchWhMasterID
								 ,@in_vchWhID				= @v_vchWarehouse
								 ,@in_vchOwnerID			= @in_vchOwnerID
								 ,@in_vchInventoryType		= 'INVENTORY'
								 ,@in_vchLocationID			= @in_vchLocationID
								 ,@in_vchParentLPN			= @in_vchParentLPN
								 ,@in_vchLPN				= @in_vchLPN
								 ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
								 ,@in_vchItemMasterID		= @v_vchItemMasterID
								 ,@in_vchItemNumber			= @v_vchItemNumber
								 ,@in_fltQuantity			= @v_fltBaseInputQuantity
								 ,@in_fltQtyAllocate		= 0
								 ,@in_fltQtyIncoming		= 0
								 ,@in_vchPrimaryItemUomID	= @v_vchBaseItemUomID
								 ,@in_vchInvStatusID		= @in_vchInvStatusID
								 ,@in_vchLotNumber			= @in_vchLotNumber
								 ,@in_vchExpiryDate			= @in_vchExpiryDate
								 ,@in_vchSerialNumber		= @in_vchSerialNumber
								 ,@in_vchAttribute1			= @in_vchAttribute1
								 ,@in_vchAttribute2			= @in_vchAttribute2
								 ,@in_vchAttribute3			= @in_vchAttribute3
								 ,@in_vchAttribute4			= @in_vchAttribute4
								 ,@in_vchAttribute5			= @in_vchAttribute5
								 ,@in_dReceiveDate			= @in_dtReceiveDate		--กรณี Adjust in จากของที่มีอยู่
								 ,@in_dtMfgDate				= @in_dtMfgDate
								 ,@in_vchDeviceID			= @in_vchDevice
								 ,@in_vchUserID				= @in_vchUserID
								 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
								 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
								 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------					
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @in_vchTransactionType and sub_tran_type = @in_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT
				END
			DECLARE @v_vchReasonCode		NVARCHAR(50)
			--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''
			SELECT @v_vchReasonCode = reason_code
				--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
			FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'

			SET @v_dtProcessDateTime = GETDATE()			
			EXEC usp_LogManager
				@in_vchApplicationID		= @in_vchApplicationID
				, @in_vchAppName			= @v_vchApplicationName
				, @in_vchDevice				= @in_vchDevice
				, @in_vchUserID				= @in_vchUserID
				, @in_vchLogType			= 'TRANSACTION'
				, @in_vchProcess			= @c_vchObjName
				, @in_dtProcessDateTime		= @v_dtProcessDateTime
				, @in_vchData1				= NULL
				, @in_vchTranType			= @in_vchTransactionType
				, @in_vchSubTranType		= @in_vchSubTranType
				, @in_dtStartTranDate		= @v_dtStartTranDate
				, @in_dtEndTranDate			= @v_dtProcessDateTime
				, @in_vchWhID 				= NULL
				, @in_vchToWhID 			= @v_vchWarehouse
				, @in_vchLocation			= NULL
				, @in_vchToLocation			= @v_vchLocation
				, @in_vchOwner				= NULL
				, @in_vchToOwner			= @v_vchOwnerCode
				, @in_vchItemNumber			= @v_vchItemNumber
				, @in_fltQuantity			= @v_fltBaseInputQuantity
				, @in_vchUOM				= @v_vchBaseUomPrompt
				, @in_fltAfterQuantity		= @v_fltAfterInvQuantity
				, @in_vchAfterUOM			= @v_vchBaseUomPrompt
				, @in_vchLotNumber			= NULL
				, @in_vchAfterLotNumber		= @in_vchLotNumber
				, @in_dtExpiryDate			= NULL
				, @in_dtAfterExpiryDate		= @in_vchExpiryDate
				, @in_vchAttribute1			= NULL	
				, @in_vchAfterAttribute1	= @in_vchAttribute1
				, @in_vchAttribute2			= NULL
				, @in_vchAfterAttribute2	= @in_vchAttribute2		
				, @in_vchAttribute3			= NULL	
				, @in_vchAfterAttribute3	= @in_vchAttribute3			
				, @in_vchAttribute4			= NULL
				, @in_vchAfterAttribute4	= @in_vchAttribute4		
				, @in_vchAttribute5			= NULL
				, @in_vchAfterAttribute5	= @in_vchAttribute5		
				, @in_vchSerialNumber		= @in_vchSerialNumber
				, @in_vchReferenceNumber	= @in_vchReferenceNumber
				, @in_vchLPN				= NULL
				, @in_vchAfterLPN			= @in_vchLPN
				, @in_vchParentLPN			= NULL
				, @in_vchAfterParentLPN		= @in_vchParentLPN
				, @in_vchStatus				= NULL
				, @in_vchAfterStatus		= @v_vchInvStatus
				, @in_vchReasonCode			= @v_vchReasonCode
				, @in_vchShortQuantity		= 0 
				, @in_vchHostRecordID		= @v_vchHostRecordID
				, @in_vchControlValue2		= @v_vchERPDestLocation
				, @in_dtReceiveDate			= @in_dtReceiveDate
				, @in_dtProductionDate		= @in_dtMfgDate
				, @in_vchInputQuantity		= @in_fltQty
				, @in_vchInputUOM			= @v_vchInputUomPrompt
				, @in_vchErrorCode			= @out_ErrorCode OUTPUT
				, @in_vchMessage			= @out_ErrorMessage   OUTPUT

			IF (@out_ErrorCode <> '0')
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
					BEGIN
						ROLLBACK TRANSACTION;
						RETURN;
					END
		END	

		-- For Dashboard
		EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'IN'
										,@in_vchTransType	 = 'ADJUST'
										,@in_vchWhMasterID	 = @in_vchWhMasterID
										,@in_vchOwnerID		 = @in_vchOwnerID
										,@in_vchOwnerCode	 = @v_vchOwnerCode
										,@in_vchLocationID	 = @in_vchLocationID
										,@in_vchItemMasterID = @v_vchItemMasterID
										,@in_vchInvStatusID	 = @in_vchInvStatusID
										,@in_vchToWhMasterID = NULL
										,@in_vchToLocationID = NULL
										,@in_vchToInvStatusID = NULL
										,@in_fltQuantity	 = @v_fltBaseInputQuantity
										,@in_vchUserID		 = @in_vchUserID
		
		--20160701:Kritsada: update for get last update inventory
		IF @in_vchLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @in_vchLocationID
		END

		COMMIT TRANSACTION;		
			 
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;
		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
					ROLLBACK TRANSACTION;
				
				SET @v_dtProcessDateTime = GETDATE();
				SET  @v_vchProcessData1 = 'Tran Type ['+ @in_vchTransactionType +'] Sub Tran Type ['+ @in_vchSubTranType +']'
				SET  @v_vchProcessData2 = 'Location [' + ISNULL(@v_vchLocation,'') + '] Item number [' + ISNULL(@v_vchItemNumber,'') +']'
				SET  @v_vchProcessData3 = 'Lot ['+ ISNULL(@in_vchLotNumber,'') +'] Expiry Date ['+ ISNULL(CONVERT(VARCHAR,@in_vchExpiryDate),'') +'] Quantity ['+ CONVERT(VARCHAR,@in_fltQty) +'] UOM ['+ ISNULL(@v_vchBaseUomPrompt,'') +']'
				SET  @v_vchProcessData4 = 'Host Record ID ['+ ISNULL(@v_vchHostRecordID,'') +'] Ref ID ['+ ISNULL(@in_vchReferenceNumber,'') +']'
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWarehouse,
					@in_vchDevice = @in_vchDevice,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchProcessData3,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END
    END TRY
	-----------------------------------------------------------------------------------
	-- Error Handling
	-----------------------------------------------------------------------------------    
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;

		DECLARE @v_intSqlErrorNumber		INTEGER
		DECLARE @v_intSqlErrorLine			INTEGER
		DECLARE @v_intSqlErrorState			INTEGER
		DECLARE @v_intSqlErrorSeverity		INTEGER
		DECLARE @v_vchSqlErrorMessage		NVARCHAR(1000)
		DECLARE @v_vchSqlErrorProcedure		NVARCHAR(200)

		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @out_ErrorMessage = @v_vchSqlErrorProcedure + ': ' + @out_ErrorMessage 
							+ '. SQL Error ['+ str(@v_intSqlErrorNumber) + '], '
							+ '. Severity ['+ str(@v_intSqlErrorSeverity) + '],'
							+ '. State ['+ str(@v_intSqlErrorState) + '],'
							+ '. State ['+ str(@v_intSqlErrorState) + '].'
		IF(ISNULL(@out_ErrorMessage,'') = '')
			SET @out_ErrorMessage = 'SQL Error';

		SET  @v_vchProcessData1 = 'Tran Type ['+ @in_vchTransactionType +'] Sub Tran Type ['+ @in_vchSubTranType +']'
		SET  @v_vchProcessData2 = 'Location [' + ISNULL(@v_vchLocation,'') + '] Item number [' + ISNULL(@v_vchItemNumber,'') +']'
		SET  @v_vchProcessData3 = 'Lot ['+ ISNULL(@in_vchLotNumber,'') +'] Expiry Date ['+ ISNULL(CONVERT(VARCHAR,@in_vchExpiryDate),'') +'] Quantity ['+ CONVERT(VARCHAR,@in_fltQty) +'] UOM ['+ ISNULL(@v_vchBaseUomPrompt,'') +']'
		SET  @v_vchProcessData4 = 'Host Record ID ['+ ISNULL(@v_vchHostRecordID,'') +'] Ref ID ['+ ISNULL(@in_vchReferenceNumber,'') +']'
		SET @out_ErrorCode = @v_intSqlErrorNumber;
		SET @out_ErrorMessage = SUBSTRING(@v_vchSqlErrorMessage,0,100);
		
		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

    END CATCH 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_adjust_out]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_adjust_out] 
	@in_vchApplicationID	NVARCHAR(40),							
	@in_vchDevice			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchTransactionType	NVARCHAR(20) = NULL,
	@in_vchSubTranType		NVARCHAR(20) = NULL, 
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL, 
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL, 
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchSerialNumber		NVARCHAR(100) = NULL,
	@in_fltQty				FLOAT = 0,
	@in_vchItemUomID		UNIQUEIDENTIFIER = NULL,
	@in_vchReasonID			UNIQUEIDENTIFIER = NULL,
	@in_dtReceiveDate		DATE,
	@in_vchReferenceNumber	NVARCHAR(50), 
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT					
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	
	DECLARE @c_vchObjName		NVARCHAR(40) = '[usp_inventory_adjust_out]',
	 
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
	@v_dtStartTranDate			DATETIME, 
	@v_dtProcessDateTime		DATETIME,
	@Round						INT,
	@v_vchBeginTran				BIT = 0,
	@v_vchLocal					NVARCHAR(5),
	 
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchHostRecordID			VARCHAR(40), 
	@v_vchWarehouse				NVARCHAR(25),
	
	@v_vchOwnerCode				NVARCHAR(40),
	@v_vchLocation				NVARCHAR(50),
	@v_vchInvStatus				NVARCHAR(50),
	@v_vchItemMasterID			VARCHAR(40),
	@v_vchItemNumber			NVARCHAR(50),
	
	@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
	@v_vchBaseUomPrompt			NVARCHAR(40),
	@v_vchBaseUom				NVARCHAR(20),
	@v_vchInputUomPrompt		NVARCHAR(40),
	@v_vchIsPrimaryUOM			NVARCHAR(5),
	@v_fltConversionFactor		FLOAT,
	@v_fltBaseInputQuantity		FLOAT,
	@v_fltAfterInvQuantity		FLOAT,

	@v_vchLotControl			VARCHAR(5),
    @v_vchSNControl				VARCHAR(5),
    @v_vchExpiryDateControl		VARCHAR(5),
	@v_vchAttribute1Control		VARCHAR(5),
	@v_vchAttribute2Control		VARCHAR(5),
	@v_vchAttribute3Control		VARCHAR(5),
	@v_vchAttribute4Control		VARCHAR(5),
	@v_vchAttribute5Control		VARCHAR(5),

	@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
	@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
	@v_dtMfgDate				DATE = NULL, 
	@v_fltAfterQty				FLOAT = 0,		--For Write Log
	@v_fltAllocatedQty			FLOAT = 0, 

	@v_fltWidth					FLOAT = 0,
	@v_fltLength				FLOAT = 0,
	@v_fltHeight				FLOAT = 0,
	@v_fltGrossWeight			FLOAT = 0,
	@v_intPercentTolerance		FLOAT = 0,
	@v_intPercenToleranceWeight FLOAT = 0,
	@v_fltVolumn				FLOAT = 0,	--item
	@v_fltTotalWeight			FLOAT = 0,	--item 
	@v_vchERPSourceLocation		NVARCHAR(50)

 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		SET @v_dtStartTranDate = GETDATE();
		IF @in_vchSubTranType IN ('TO_ERP','NOT_ERP')
		BEGIN
			SET @in_vchSubTranType = 'ADJUST_OUT_' + @in_vchSubTranType
		END

		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SET @in_fltQty = ROUND(@in_fltQty,@Round)

		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		ELSE
			SET @in_vchExpiryDate = NULL

		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				SET @out_ErrorCode = 'INFO-QUANTITY-CANNOT-EQUAL-ZERO';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

-----------------------------------------------------------------------------------
-- Validate data
-----------------------------------------------------------------------------------		
		BEGIN-- Check and Initial Data	
			IF (ISNULL(@in_vchParentLPN,'') = N'')
				SET @in_vchParentLPN = NULL;
			
			IF (ISNULL(@in_vchLPN,'') = N'')
				SET @in_vchLPN = NULL;
		
			IF (ISNULL(@in_vchLotNumber,'') = N'') 
				SET @in_vchLotNumber = NULL;
						
			IF (ISNULL(@in_vchExpiryDate,'') = N'') 
				SET @in_vchExpiryDate = NULL;

			IF (ISNULL(@in_vchAttribute1,'') = N'') 
				SET @in_vchAttribute1 = NULL;
			
			IF (ISNULL(@in_vchAttribute2,'') = N'') 
				SET @in_vchAttribute2 = NULL;
		
			IF (ISNULL(@in_vchAttribute3,'') = N'') 
				SET @in_vchAttribute3 = NULL;
			
			IF (ISNULL(@in_vchAttribute4,'') = N'') 
				SET @in_vchAttribute4 = NULL;
			
			IF (ISNULL(@in_vchAttribute5,'') = N'') 
				SET @in_vchAttribute5 = NULL;
			
			IF (ISNULL(@in_vchSerialNumber,'') = N'') 
				SET @in_vchSerialNumber = NULL;
		END
	
		BEGIN-- Check master data
			-- get id warehouse and to warehouse 
			SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
			IF(ISNULL(@v_vchWarehouse,'') = '')
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_NOT_FOUND',@v_vchLocal,@v_vchWarehouse,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
				
			-- Get & check owner	
			SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'
			IF(ISNULL(@v_vchOwnerCode,'') = '')
				BEGIN
					SET @out_ErrorCode = 'OWNER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchOwnerCode,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

			--Get and check location
			SELECT @v_vchLocation = location, @v_vchERPSourceLocation = erp_location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
			IF (ISNULL(@v_vchLocation,'') = '')
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,'@param2','@param3','@param4','@param5')
					print @out_ErrorMessage
					GOTO WRITE_PROC;
				END

			-- Check from status
			SELECT @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID AND is_active = 'YES'
			IF (ISNULL(@v_vchInvStatus,'') = '')
				BEGIN
					SET @out_ErrorCode = 'STATUS_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInvStatus,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
			
			--Get wh_item_master_id
			SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID AND wh_master_id = @in_vchWhMasterID
			IF (@v_vchItemMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

			-- check item number and item crossref and get owner
			SELECT TOP 1 @v_vchItemMasterID = item_master_id
				,@v_vchItemNumber		 = item_number
				,@v_vchLotControl		 = lot_control
				,@v_vchSNControl		 = sn_control
				,@v_vchExpiryDateControl = expiry_date_control
				,@v_vchAttribute1Control = attribute1_control
				,@v_vchAttribute2Control = attribute2_control
				,@v_vchAttribute3Control = attribute3_control
				,@v_vchAttribute4Control = attribute4_control
				,@v_vchAttribute5Control = attribute5_control
			FROM t_wms_item item
			 WHERE item_master_id = @v_vchItemMasterID
			AND owner_id = @in_vchOwnerID
			AND is_active = 'YES' 
			IF (@v_vchItemMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END 
			
			--Get & Check Item UOM
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchInputUomPrompt = uom_prompt
				,@v_fltConversionFactor = conversion_factor
				,@v_vchIsPrimaryUOM = primary_uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND item_uom_id = @in_vchItemUomID
			IF (@v_vchBaseItemUomID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'UOM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
					Goto WRITE_PROC
				End

			--Get Primary Uom
			IF @v_vchIsPrimaryUOM = 'NO'
				BEGIN
					SELECT @v_vchBaseItemUomID = item_uom_id
						,@v_vchBaseUomPrompt = uom_prompt
						,@v_fltWidth = ISNULL(width,0)
						,@v_fltLength = ISNULL(length,0)
						,@v_fltHeight = ISNULL(height,0)
						,@v_fltGrossWeight = ISNULL(gross_weight,0)
						,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
						,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
					FROM t_wms_item_uom 
					WHERE item_master_id = @v_vchItemMasterID 
					AND primary_uom = 'YES' 
					AND is_active = 'YES'
				END

			SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);

			IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
				BEGIN
					SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltBaseInputQuantity,2)
					SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltBaseInputQuantity,2)
				END
		END

-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
		BEGIN TRANSACTION
		SET @v_vchBeginTran = 1;
			SET @v_vchInventoryID = NULL;
			SET @v_vchAttributeGroupID = NULL;

			SELECT @v_vchInventoryID = inventory_id
				,@v_vchAttributeGroupID = attribute_group_id
				,@v_dtMfgDate = mfg_date
				,@v_fltAfterQty = quantity
				,@v_fltAllocatedQty = quantity_allocated
			FROM v_wms_inventory_data_serial_by_id
			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND wh_item_master_id = @in_vchWhItemMasterID 
			AND location_id = @in_vchLocationID 
			AND inventory_status_id = @in_vchInvStatusID
			AND receive_date = @in_dtReceiveDate
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						
			IF (@v_vchInventoryID IS NULL)
				BEGIN
					SET @out_ErrorCode = '989';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',@v_vchLocal,@v_vchLocation,@v_vchItemNumber,@in_vchLPN,'@param4','@param5')
					GOTO WRITE_PROC;
				END
							
			-- Quantity not enough
			-- ค่าที่ส่งมาสำหรับ Adjust out จะเป็นค่าติดลบ ดังนั้นตอน Check กับ Inventory ให้เอาไป * -1 เพื่อให้ค่าเป็น +
			IF ((ISNULL(@v_fltAfterQty,0) - ISNULL(@v_fltAllocatedQty,0)) < (@v_fltBaseInputQuantity*-1))
				BEGIN
					SET @out_ErrorCode = '989';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ADJUST_QTY_MOVE_THEN_INVENTORY',@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
					GOTO WRITE_PROC;							
				END

			--------------------------------------------
			--Manage source inventory
			--Qty ที่ส่งมาจะ (ติดลบ)
			--------------------------------------------
			UPDATE t_wms_inventory SET quantity = ROUND(quantity + @v_fltBaseInputQuantity,@Round) 
				,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID

			IF (@v_vchSNControl = 'FULL')
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity + @v_fltBaseInputQuantity,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID 
					AND attribute_value = @in_vchSerialNumber												
				END

			--Inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity + @v_fltBaseInputQuantity,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END

			----Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
			DELETE t_wms_inventory_remark
			FROM t_wms_inventory_remark invRemark
			LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
			WHERE inv.inventory_id = @v_vchInventoryID

			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
			DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
 
			--Update Volumn & Weight in from location
			IF @in_vchLocationID IS NOT NULL
				BEGIN
					UPDATE [dbo].[t_wms_location]
						SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
						, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
						, update_date = GETDATE()  
						, [update_by] = @in_vchUserID   
						WHERE [location_id] = @in_vchLocationID
				END

			-- Set quantity after update
			SELECT @v_fltAfterQty = ROUND(ISNULL(@v_fltAfterQty,0) + @v_fltBaseInputQuantity,@Round);
				
			-----------------------------------------------------------------------------------
			-- Write transaction log
			BEGIN
				WRITE_TRANS:							
			-----------------------------------------------------------------------------------	
				IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @in_vchTransactionType and sub_tran_type = @in_vchSubTranType) = 'YES')
					BEGIN
						EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT
						--EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT
					END
				DECLARE @v_vchReasonCode		NVARCHAR(50)
				--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''
				SELECT @v_vchReasonCode = reason_code
					--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
				FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
							
				SET @v_dtProcessDateTime = GETDATE()
				EXEC usp_LogManager
					@in_vchApplicationID		= @in_vchApplicationID
					, @in_vchAppName			= @v_vchApplicationName
					, @in_vchDevice				= @in_vchDevice
					, @in_vchUserID				= @in_vchUserID
					, @in_vchLogType			= 'TRANSACTION'
					, @in_vchProcess			= @c_vchObjName
					, @in_dtProcessDateTime		= @v_dtProcessDateTime
					, @in_vchTranType			= @in_vchTransactionType
					, @in_vchSubTranType		= @in_vchSubTranType
					, @in_dtStartTranDate		= @v_dtStartTranDate
					, @in_dtEndTranDate			= @v_dtProcessDateTime
					, @in_vchWhID 				= @v_vchWarehouse
					, @in_vchToWhID 			= NULL
					, @in_vchLocation			= @v_vchLocation
					, @in_vchToLocation			= NULL
					, @in_vchOwner				= @v_vchOwnerCode
					, @in_vchToOwner			= NULL
					, @in_vchItemNumber			= @v_vchItemNumber
					, @in_fltQuantity			= @v_fltBaseInputQuantity
					, @in_vchUOM				= @v_vchBaseUomPrompt
					, @in_fltAfterQuantity		= @v_fltAfterQty
					, @in_vchAfterUOM			= @v_vchBaseUomPrompt
					, @in_vchLotNumber			= @in_vchLotNumber
					, @in_vchAfterLotNumber		= NULL
					, @in_dtExpiryDate			= @in_vchExpiryDate
					, @in_dtAfterExpiryDate		= NULL
					, @in_vchAttribute1			= @in_vchAttribute1	
					, @in_vchAfterAttribute1	= NULL
					, @in_vchAttribute2			= @in_vchAttribute2
					, @in_vchAfterAttribute2	= NULL	
					, @in_vchAttribute3			= @in_vchAttribute3	
					, @in_vchAfterAttribute3	= NULL		
					, @in_vchAttribute4			= @in_vchAttribute4
					, @in_vchAfterAttribute4	= NULL	
					, @in_vchAttribute5			= @in_vchAttribute5
					, @in_vchAfterAttribute5	= NULL		
					, @in_vchSerialNumber		= @in_vchSerialNumber
					, @in_vchLPN				= @in_vchLPN
					, @in_vchAfterLPN			= NULL
					, @in_vchParentLPN			= @in_vchParentLPN
					, @in_vchAfterParentLPN		= NULL
					, @in_vchStatus				= @v_vchInvStatus
					, @in_vchAfterStatus		= NULL
					, @in_vchReasonCode			= @v_vchReasonCode
					, @in_dtReceiveDate			= @in_dtReceiveDate
					, @in_dtProductionDate		= @v_dtMfgDate
					, @in_vchReferenceNumber	= @in_vchReferenceNumber
					, @in_vchHostRecordID		= @v_vchHostRecordID
					, @in_vchControlValue1		= @v_vchERPSourceLocation
					, @in_vchInputQuantity		= @in_fltQty
					, @in_vchInputUOM			= @v_vchInputUomPrompt
					, @in_vchErrorCode			= @out_ErrorCode OUTPUT
					, @in_vchMessage			= @out_ErrorMessage OUTPUT

				IF (@out_ErrorCode <> '0')
					IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
						BEGIN
							ROLLBACK TRANSACTION;
							RETURN;
						END
			END

			-- For Dashboard
			EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT'
												,@in_vchTransType	 = 'ADJUST'
												,@in_vchWhMasterID	 = @in_vchWhMasterID
												,@in_vchOwnerID		 = @in_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwnerCode
												,@in_vchLocationID	 = @in_vchLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @in_vchInvStatusID
												,@in_vchToWhMasterID = NULL
												,@in_vchToLocationID = NULL
												,@in_vchToInvStatusID = NULL
												,@in_fltQuantity	 = @v_fltBaseInputQuantity
												,@in_vchUserID		 = @in_vchUserID
		
		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;
		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
					ROLLBACK TRANSACTION;
				
				SET @v_dtProcessDateTime = GETDATE();
				SET  @v_vchProcessData1 = 'Tran Type ['+ @in_vchTransactionType +'] Sub Tran Type ['+ @in_vchSubTranType +']'
				SET  @v_vchProcessData2 = 'Location [' + ISNULL(@v_vchLocation,'') + '] Item number [' + ISNULL(@v_vchItemNumber,'') +']'
				SET  @v_vchProcessData3 = 'Lot ['+ ISNULL(@in_vchLotNumber,'') +'] Expiry Date ['+ ISNULL(CONVERT(VARCHAR,@in_vchExpiryDate),'') +'] Quantity ['+ CONVERT(VARCHAR,@in_fltQty) +'] UOM ['+ ISNULL(@v_vchBaseUomPrompt,'') +']'
				SET  @v_vchProcessData4 = 'Host Record ID ['+ ISNULL(@v_vchHostRecordID,'') +'] Ref ID ['+ ISNULL(@in_vchReferenceNumber,'') +']'
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWarehouse,
					@in_vchDevice = @in_vchDevice,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchProcessData3,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END
    END TRY
	-----------------------------------------------------------------------------------
	-- Error Handling
	-----------------------------------------------------------------------------------    
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;

		DECLARE @v_intSqlErrorNumber		INTEGER
		DECLARE @v_intSqlErrorLine			INTEGER
		DECLARE @v_intSqlErrorState			INTEGER
		DECLARE @v_intSqlErrorSeverity		INTEGER
		DECLARE @v_vchSqlErrorMessage		NVARCHAR(1000)
		DECLARE @v_vchSqlErrorProcedure		NVARCHAR(200)

		SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @out_ErrorMessage = @v_vchSqlErrorProcedure + ': ' + @out_ErrorMessage 
							+ '. SQL Error ['+ str(@v_intSqlErrorNumber) + '], '
							+ '. Severity ['+ str(@v_intSqlErrorSeverity) + '],'
							+ '. State ['+ str(@v_intSqlErrorState) + '],'
							+ '. State ['+ str(@v_intSqlErrorState) + '].'
		IF(ISNULL(@out_ErrorMessage,'') = '')
			SET @out_ErrorMessage = 'SQL Error';

		SET  @v_vchProcessData1 = 'Tran Type ['+ @in_vchTransactionType +'] Sub Tran Type ['+ @in_vchSubTranType +']'
		SET  @v_vchProcessData2 = 'Location [' + ISNULL(@v_vchLocation,'') + '] Item number [' + ISNULL(@v_vchItemNumber,'') +']'
		SET  @v_vchProcessData3 = 'Lot ['+ ISNULL(@in_vchLotNumber,'') +'] Expiry Date ['+ ISNULL(CONVERT(VARCHAR,@in_vchExpiryDate),'') +'] Quantity ['+ CONVERT(VARCHAR,@in_fltQty) +'] UOM ['+ ISNULL(@v_vchBaseUomPrompt,'') +']'
		SET  @v_vchProcessData4 = 'Host Record ID ['+ ISNULL(@v_vchHostRecordID,'') +'] Ref ID ['+ ISNULL(@in_vchReferenceNumber,'') +']'
		SET @out_ErrorCode = @v_intSqlErrorNumber;
		SET @out_ErrorMessage = SUBSTRING(@v_vchSqlErrorMessage,0,100);
		
		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
    END CATCH 
    
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_expiry_date]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_expiry_date] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_dtToMfgDate			DATE,
	@in_vchToExpiryDate		NVARCHAR(50),
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_expiry_date]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5)
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_EXPDATE'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchLPNControl		VARCHAR(5)
	DECLARE @v_vchLocType			NVARCHAR(20)
 
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER
	DECLARE @v_vchInvStatus			NVARCHAR(50)
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtFromMfgDate		DATE
	DECLARE @v_vchFromExpiryDate	NVARCHAR(50)
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchReasonCode = reason_code
			--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchWhMasterID	     = wh_master_id
			,@v_vchWarehouse	     = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchLocationID		 = location_id
			,@v_vchLocation			 = location
			,@v_vchLocType			 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchLPNControl		 = lpn_controlled
			,@v_vchParentLPN		 = parent_lpn
			,@v_vchLPN				 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchBaseUomPrompt	 = uom_prompt
			,@v_vchInvStatusID		 = inventory_status_id
			,@v_vchInvStatus		 = inv_status
			,@v_vchLotNumber		 = lot_number
			,@v_vchFromExpiryDate	 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtFromMfgDate		 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_item 
		WHERE inventory_id = @in_vchInventoryID
		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		----ถ้า Item ที่ต้องการ Move Control Serial จะต้อง Move เต็มจำนวนเท่านั้น
		--IF @v_vchSNControl = 'FULL' AND ISNULL(@in_fltQty,0) > 0 
		--	BEGIN
		--		SET @out_ErrorCode = 'CONTROL_SN_CANNOT_MOVE_THIS_FUNCTION';
		--		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
		--		GOTO WRITE_PROC
		--	END

		--For Insert Serial to temp
		IF @v_vchSNControl = 'FULL'
			BEGIN
				SET @in_fltQty = 0
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE inventory_id = @in_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				ORDER BY serial_number
			END

		--Qty Input = 0 or Null >> Get Qty from inventory
		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				--Move all qty
				SET @v_fltQtyUpdate = @v_vchInvQuantity
			END
		ELSE	
			BEGIN
				SET @v_fltQtyUpdate = @in_fltQty
			END
			 
		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END 

		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
		DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
	
		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		-- check location is mix expiry date?
		DECLARE @v_vchMixExpiryDate	VARCHAR(5) = ''
		SELECT @v_vchMixExpiryDate = mix_expiry_dates FROM t_wms_location WHERE location_id = @v_vchLocationID	
		IF EXISTS (SELECT inv.inventory_id FROM  t_wms_inventory inv 
					LEFT JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date FROM dbo.t_wms_inventory_attribute
								WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')
								) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
					WHERE inv.wh_master_id = @v_vchWhMasterID 
					AND inv.location_id = @v_vchLocationID
					AND inv.wh_item_master_id = @v_vchWhItemMasterID 
					AND ISNULL(invAttr.expiry_date,'') <> ISNULL(@in_vchToExpiryDate,''))
			AND @v_vchExpControl = 'FULL'
			AND @v_vchMixExpiryDate = 'NO'
		BEGIN
			SET	@out_ErrorCode = 'LOCATION_NOT_MIX_EXPIRY_DATE';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		END

		------------------------------------------------------------------------------
		--กรณีที่มีการเก็บ MFG Date เวลา Save ต้อง MFG Date มา ถ้าไม่ส่งมา จะ get inventory เดิมไป  
		--Check To MFG Date ที่ต้องการแก้ไข จะต้องเท่ากับปลายทางที่มีอยู่
		------------------------------------------------------------------------------
		IF @v_vchExpControl = 'FULL'
			BEGIN
				DECLARE @v_dtCheckMfgDate DATE = NULL
				SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
				FROM v_wms_inventory_data_by_id
				WHERE wh_master_id = @V_vchWhMasterID 
				AND owner_id = @V_vchOwnerID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
				AND ISNULL([expiry_date],'') = ISNULL(@in_vchToExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'') 
		
				IF @in_dtToMfgDate <> @v_dtCheckMfgDate
					BEGIN
						SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchToExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
								, @in_vchLocationID			= @v_vchLocationID
								, @in_vchStatusID			= @v_vchInvStatusID
								, @in_vchPalentLPN			= @v_vchParentLPN
								, @in_vchLPN				= @v_vchLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @in_dtToMfgDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber 
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @v_vchLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @in_vchToExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END

				--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN 
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number IN (SELECT SerialNumber FROM @tInventorySerial) 

						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,@v_vchDestInventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL
				
		IF @v_vchLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchLocationID
		END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE();
					IF @v_vchSNControl = 'NONE'
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type] 
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status] 
									,[control_value_1]
									,[control_value_2]
									,[receive_date]
									,[mfg_date]
									,[reason_code]
									--,[user_def1] 
									,[device]
									,[create_date]
									,[create_by])
								VALUES
									(NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType 
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,@v_vchWarehouse
									,@v_vchWarehouse	
									,@v_vchLocation
									,@v_vchLocation
									,@v_vchOwner
									,@v_vchOwner
									,@v_vchItemNumber
									,@v_fltQtyUpdate
									,@v_vchBaseUomPrompt
									,@v_fltAfterQty
									,@v_vchBaseUomPrompt
									,@v_vchLotNumber
									,@v_vchLotNumber
									,(CASE WHEN ISNULL(@v_vchFromExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchFromExpiryDate) END)
									,(CASE WHEN ISNULL(@in_vchToExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchToExpiryDate) END)
									,NULL
									,@v_vchAttribute1
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute4
									,@v_vchAttribute5
									,@v_vchAttribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,@v_vchLPN
									,@v_vchLPN
									,@v_vchInvStatus
									,@v_vchInvStatus 
									,@v_vchERPSourceLocation
									,@v_vchERPDestLocation
									,@v_dtReceiveDate
									,@v_dtFromMfgDate
									,@v_vchReasonCode
									--,@v_vchReasonDescription 
									,@in_vchDeviceID
									,GETDATE()
									,@in_vchUserID)
						END
					ELSE
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
								([record_id]
								,[host_record_id]
								,[processing_code]
								,[processing_status]
								,[app_id]
								,[app_name]
								,[tran_type]
								,[sub_tran_type] 
								,[start_tran_datetime]
								,[end_tran_datetime]
								,[warehouse]
								,[to_warehouse]
								,[location]
								,[to_location]
								,[owner]
								,[to_owner]
								,[item_number]
								,[quantity]
								,[quantity_uom]
								,[after_quantity]
								,[after_quantity_uom]
								,[lot_number]
								,[after_lot_number]
								,[expiry_date]
								,[after_expiry_date]
								,[serial_number]
								,[attribute1]
								,[after_attribute1]
								,[attribute2]
								,[after_attribute2]
								,[attribute3]
								,[after_attribute3]
								,[attribute4]
								,[after_attribute4]
								,[attribute5]
								,[after_attribute5]
								,[user_id]
								,[reference_number]
								,[lpn]
								,[after_lpn]
								,[status]
								,[after_status] 
								,[control_value_1]
								,[control_value_2]
								,[receive_date]
								,[mfg_date]
								,[reason_code]
								--,[user_def1] 
								,[device]
								,[create_date]
								,[create_by])
							SELECT NEWID()
								,@v_vchHostRecordID
								,'ADD'  
								,'PENDING'
								,@in_vchApplicationID
								,@v_vchApplicationName
								,@v_vchTranType
								,@v_vchSubTranType 
								,@v_dtStartTranDate
								,@v_dtProcessDateTime
								,@v_vchWarehouse
								,@v_vchWarehouse	
								,@v_vchLocation
								,@v_vchLocation
								,@v_vchOwner
								,@v_vchOwner
								,@v_vchItemNumber
								,@v_fltQtyUpdate
								,@v_vchBaseUomPrompt
								,@v_vchInvQuantity - RowNumber
								,@v_vchBaseUomPrompt
								,@v_vchLotNumber
								,@v_vchLotNumber
								,(CASE WHEN ISNULL(@v_vchFromExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchFromExpiryDate) END)
								,(CASE WHEN ISNULL(@in_vchToExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchToExpiryDate) END)
								,SerialNumber
								,@v_vchAttribute1
								,@v_vchAttribute1
								,@v_vchAttribute2
								,@v_vchAttribute2
								,@v_vchAttribute3
								,@v_vchAttribute3
								,@v_vchAttribute4
								,@v_vchAttribute4
								,@v_vchAttribute5
								,@v_vchAttribute5
								,@in_vchUserID
								,@in_vchReferenceNumber 
								,@v_vchLPN
								,@v_vchLPN
								,@v_vchInvStatus
								,@v_vchInvStatus 
								,@v_vchERPSourceLocation
								,@v_vchERPDestLocation
								,@v_dtReceiveDate
								,@v_dtFromMfgDate
								,@v_vchReasonCode
								--,@v_vchReasonDescription 
								,@in_vchDeviceID
								,GETDATE()
								,@in_vchUserID
							FROM @tInventorySerial 
							ORDER BY RowNumber
						END
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE(); 
			IF @v_vchSNControl = 'NONE'
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[reason_code]
						,[udf_1] 
						,[receive_date]
						,[mfg_date]
						,[input_quantity]
						,[input_uom]
						,[device]
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType
						,'Change Expiry Date'
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,@v_vchWarehouse
						,@v_vchWarehouse
						,@v_vchLocation
						,@v_vchLocation
						,@v_vchOwner
						,@v_vchOwner
						,@v_vchItemNumber
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@v_fltAfterQty
						,@v_vchBaseUomPrompt
						,@v_vchLotNumber
						,@v_vchLotNumber
						,(CASE WHEN ISNULL(@v_vchFromExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchFromExpiryDate) END)
						,(CASE WHEN ISNULL(@in_vchToExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchToExpiryDate) END)
						,NULL
						,@v_vchAttribute1
						,@v_vchAttribute1
						,@v_vchAttribute2
						,@v_vchAttribute2
						,@v_vchAttribute3
						,@v_vchAttribute3
						,@v_vchAttribute4
						,@v_vchAttribute4
						,@v_vchAttribute5
						,@v_vchAttribute5
						,@in_vchUserID
						,@in_vchReferenceNumber
						,@v_vchHostRecordID
						,@v_vchLPN
						,@v_vchLPN
						,@v_vchParentLPN
						,@v_vchParentLPN
						,@v_vchInvStatus
						,@v_vchInvStatus 
						,@v_vchERPSourceLocation
						,@v_vchERPDestLocation
						,@v_vchReasonCode
						,@in_vchRemark  
						,@v_dtReceiveDate
						,@v_dtFromMfgDate
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt 
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID) 
				END
			ELSE
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
					   ([tran_id]
					   ,[app_id]
					   ,[app_name]
					   ,[tran_type]
					   ,[sub_tran_type]
					   ,[description]
					   ,[start_tran_datetime]
					   ,[end_tran_datetime]
					   ,[warehouse]
					   ,[to_warehouse]
					   ,[location]
					   ,[to_location]
					   ,[owner]
					   ,[to_owner]
					   ,[item_number]
					   ,[quantity]
					   ,[quantity_uom]
					   ,[after_quantity]
					   ,[after_quantity_uom]
					   ,[lot_number]
					   ,[after_lot_number]
					   ,[expiry_date]
					   ,[after_expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[after_attribute1]
					   ,[attribute2]
					   ,[after_attribute2]
					   ,[attribute3]
					   ,[after_attribute3]
					   ,[attribute4]
					   ,[after_attribute4]
					   ,[attribute5]
					   ,[after_attribute5]
					   ,[user_id]
					   ,[reference_number]
					   ,[control_number]
					   ,[lpn]
					   ,[after_lpn]
					   ,[parent_lpn]
					   ,[after_parent_lpn]
					   ,[status]
					   ,[after_status] 
					   ,[control_value_1]
					   ,[control_value_2]
					   ,[reason_code]
					   ,[udf_1] 
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom]
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 SELECT NEWID()
					   ,@in_vchApplicationID
					   ,@v_vchApplicationName
					   ,@v_vchTranType
					   ,@v_vchSubTranType
					   ,'Change Expiry Date'
					   ,@v_dtStartTranDate
					   ,@v_dtProcessDateTime
					   ,@v_vchWarehouse
					   ,@v_vchWarehouse
					   ,@v_vchLocation
					   ,@v_vchLocation
					   ,@v_vchOwner
					   ,@v_vchOwner
					   ,@v_vchItemNumber
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@v_vchInvQuantity - RowNumber
					   ,@v_vchBaseUomPrompt
					   ,@v_vchLotNumber
					   ,@v_vchLotNumber
					   ,(CASE WHEN ISNULL(@v_vchFromExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchFromExpiryDate) END)
					   ,(CASE WHEN ISNULL(@in_vchToExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchToExpiryDate) END)
					   ,SerialNumber
					   ,@v_vchAttribute1
					   ,@v_vchAttribute1
					   ,@v_vchAttribute2
					   ,@v_vchAttribute2
					   ,@v_vchAttribute3
					   ,@v_vchAttribute3
					   ,@v_vchAttribute4
					   ,@v_vchAttribute4
					   ,@v_vchAttribute5
					   ,@v_vchAttribute5
					   ,@in_vchUserID
					   ,@in_vchReferenceNumber
					   ,@v_vchHostRecordID
					   ,@v_vchLPN
					   ,@v_vchLPN
					   ,@v_vchParentLPN
					   ,@v_vchParentLPN
					   ,@v_vchInvStatus
					   ,@v_vchInvStatus 
					   ,@v_vchERPSourceLocation
					   ,@v_vchERPDestLocation
					   ,@v_vchReasonCode
					   ,@in_vchRemark  
					   ,@v_dtReceiveDate
					   ,@v_dtFromMfgDate
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@in_vchDeviceID
					   ,GETDATE()
					   ,@in_vchUserID
					FROM @tInventorySerial
					ORDER BY RowNumber
				END
		END 

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + ']'
		SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchFromExpiryDate,'')  + '] To Exp: [' + ISNULL(@in_vchToExpiryDate,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + ']'
	SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchFromExpiryDate,'')  + '] To Exp: [' + ISNULL(@in_vchToExpiryDate,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage		
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_location]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_location] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchToWhMasterID		UNIQUEIDENTIFIER,
	@in_vchToLocationID		UNIQUEIDENTIFIER,
	@in_vchToParentLPN		NVARCHAR(25),
	@in_vchToLPN			NVARCHAR(25),
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON; 
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_location]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5)
	DECLARE @RuleCheckFullLPN		VARCHAR(3)
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_MOVE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = ''
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchFromWhMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchFromWarehouse		NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchFromLocationID	UNIQUEIDENTIFIER
	DECLARE @v_vchFromLocation		NVARCHAR(50)
	DECLARE @v_vchFromLPNControl	VARCHAR(5)
	DECLARE @v_vchFromLocType		NVARCHAR(20)
 
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER
	DECLARE @v_vchInvStatus			NVARCHAR(50)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchFromParentLPN		NVARCHAR(25)
	DECLARE @v_vchFromLPN			NVARCHAR(25)
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate	    NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)
	DECLARE @v_fltConversionFactor		FLOAT
	DECLARE @v_fltWidth					FLOAT = 0
	DECLARE @v_fltLength				FLOAT = 0
	DECLARE @v_fltHeight				FLOAT = 0
	DECLARE @v_fltGrossWeight			FLOAT = 0
	DECLARE @v_intPercentTolerance		FLOAT = 0
	DECLARE @v_intPercenToleranceWeight FLOAT = 0
	DECLARE @v_fltVolumn				FLOAT = 0	--item
	DECLARE @v_fltTotalWeight			FLOAT = 0	--item

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0
	
	--Destination
	DECLARE @v_vchToWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchToWarehouse		NVARCHAR(25)
	DECLARE @v_vchToLocation		NVARCHAR(50)
	DECLARE @v_vchToLPNControl		VARCHAR(5)
	DECLARE @v_fltLocTotalVolumn	FLOAT = 0
	DECLARE @v_fltLocTotalWeight	FLOAT = 0
	DECLARE @v_fltLocWidth			FLOAT = 0
	DECLARE @v_fltLocLength			FLOAT = 0
	DECLARE @v_fltLocHeight			FLOAT = 0
	DECLARE @v_fltLocGrossWeight	FLOAT = 0
	DECLARE @v_fltLocVolumn			FLOAT = 0


	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RuleCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT @v_vchReasonCode = reason_code
			--, @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		SELECT @v_vchToWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchToWhMasterID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchFromWhMasterID	 = wh_master_id
			,@v_vchFromWarehouse	 = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchFromLocationID	 = location_id
			,@v_vchFromLocation		 = location
			,@v_vchFromLocType		 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchFromLPNControl	 = lpn_controlled
			,@v_vchFromParentLPN	 = parent_lpn
			,@v_vchFromLPN			 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchInvStatusID		 = inventory_status_id
			,@v_vchInvStatus		 = inv_status
			,@v_vchLotNumber		 = lot_number
			,@v_vchExpiryDate		 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtMfgDate			 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_item
		WHERE inventory_id = @in_vchInventoryID

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		 

		----ถ้า Item ที่ต้องการ Move Control Serial จะต้อง Move เต็มจำนวนเท่านั้น
		--IF @v_vchSNControl = 'FULL' AND ISNULL(@in_fltQty,0) > 0 
		--	BEGIN
		--		SET @out_ErrorCode = 'CONTROL_SN_CANNOT_MOVE_THIS_FUNCTION';
		--		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
		--		GOTO WRITE_PROC
		--	END
			
		--For Insert Serial to temp
		IF @v_vchSNControl = 'FULL'
			BEGIN
				SET @in_fltQty = 0
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE inventory_id = @in_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				ORDER BY serial_number
			END

		--Qty Input = 0 or Null >> Get Qty from inventory
		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				--Move all qty
				SET @v_fltQtyUpdate = @v_vchInvQuantity
			END
		ELSE	
			BEGIN
				SET @v_fltQtyUpdate = @in_fltQty
			END

		--Set To Parent LPN = From Parent ถ้าไม่ได้ส่งค่ามา
		IF ISNULL(@in_vchToParentLPN,'') = ''
			BEGIN
				SET @in_vchToParentLPN = @v_vchFromParentLPN
			END

		--LPN Input = NULL and lpn Control >> get LPN from inventory
		IF @v_vchFromLPNControl = 'YES' AND ISNULL(@in_vchToLPN,'') = ''
			BEGIN
				SET @in_vchToLPN = @v_vchFromLPN
			END 

		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchFromLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END

		--Get & Check Source Item UOM  : Calculate Volumn & Weight of items
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID
		AND item_uom_id = @v_vchBaseItemUomID
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC 
			END
			
		SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyUpdate,2)
		SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyUpdate,2)

		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
			,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
			,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
		DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
					
		--Update Volumn & Weight in from location
		IF @v_vchFromLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location]
					SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
					, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
					, update_date = GETDATE()  
					, [update_by] = @in_vchUserID   
				WHERE [location_id] = @v_vchFromLocationID
			END

	--------------------------------------------
	--Validate Destination Location
	--------------------------------------------
		--Check to location
		SET @v_vchToLocation = NULL
		SELECT @v_vchToLocation = location
			, @v_vchERPDestLocation = erp_location
			, @v_vchToLPNControl = lpn_controlled
			, @v_fltLocWidth = ISNULL(width,0)
			, @v_fltLocLength = ISNULL(length,0)
			, @v_fltLocHeight = ISNULL(height,0)
			, @v_fltLocGrossWeight = ISNULL(gross_weight,0)
			, @v_fltLocTotalWeight = ISNULL(total_weight,0)
			, @v_fltLocTotalVolumn = ISNULL(total_volumn,0)
		FROM t_wms_location 
		WHERE wh_master_id = @in_vchToWhMasterID 
		AND location_id = @in_vchToLocationID
		AND is_active = 'YES'
		IF(@v_vchToLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Check Location ต้นทางปลายทาง
		IF @v_vchFromLocationID = @in_vchToLocationID
			BEGIN
				SET @out_ErrorCode = 'INFO-SOURCE-LOC-CANNOT-DUP-DEST-LOC'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Validate To LPN
		IF @v_vchToLPNControl = 'YES' AND ISNULL(@in_vchToLPN,'') = '' AND ISNULL(@in_fltQty,0) > 0 
			BEGIN
				SET @out_ErrorCode = 'TO_LPN_CANNOT_BE_EMPTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
				
		-- Check to warehouse item master id
		IF (@v_vchFromWhMasterID <> @in_vchToWhMasterID)
			BEGIN
				SET @v_vchToWhItemMasterID = NULL
				SELECT @v_vchToWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchToWhMasterID AND item_master_id = @v_vchItemMasterID

				-- check warehouse item
				IF(@v_vchToWhItemMasterID IS NULL)
				BEGIN 
					SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToWarehouse,@v_vchItemNumber,'@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END
		ELSE
			BEGIN
				SET @v_vchToWhItemMasterID = @v_vchWhItemMasterID 
			END
			
		-- Check duplicate parent lpn.
		IF (ISNULL(@in_vchToParentLPN,'') <> '')
			BEGIN
				DECLARE @v_vchDubLocation	NVARCHAR(50) = NULL

				SELECT TOP 1 @v_vchDubLocation = loc.location
				FROM t_wms_inventory inv
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				WHERE inv.wh_master_id = @in_vchToWhMasterID 
				AND ISNULL(inv.location_id,'') <> ISNULL(@in_vchToLocationID,'')
				AND inv.parent_lpn = @in_vchToParentLPN
				
				IF (ISNULL(@v_vchDubLocation,'') <> '')
					BEGIN
						SET @out_ErrorCode = 'PARENT_LPN_DUPPLICATE';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		
		--Calculate volumn & weight of LPN
		IF (@RuleCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
			BEGIN
				DECLARE @v_fltPalletID			UNIQUEIDENTIFIER = NULL,
						@v_fltPLGrossWeight		FLOAT = 0,
						@v_fltPLVolumn			FLOAT = 0,
						@v_fltInvVolumnByLPN	FLOAT = 0,
						@v_fltInvWeightByLPN	FLOAT = 0

				--Calculate Volumn & Weight of pallet
				SELECT @v_fltPalletID = pallet_id
					,@v_fltPLVolumn = ROUND(ISNULL(width,0) * ISNULL(length,0) * ISNULL(height,0),@Round)
					,@v_fltPLGrossWeight = ISNULL(gross_weight,0)
				FROM t_wms_pallet_type 
				WHERE is_active = 'YES'
				
				IF (@v_fltPalletID IS NULL)
					BEGIN
						SET @out_ErrorCode = 'PALLET_TYPE_CANNOT_BE_EMPTY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_fltInvVolumnByLPN = SUM(ISNULL(volumn_by_lpn,0))
					,@v_fltInvWeightByLPN = SUM(ISNULL(weight_by_lpn,0))
				FROM t_wms_inventory
				WHERE lpn = @in_vchToLPN

				--Volumn of qty input + volumn in inventory เทียบกับ volumn ที่กำหนด
				IF (@v_fltVolumn + ISNULL(@v_fltInvVolumnByLPN,0)) > @v_fltPLVolumn
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				IF (@v_fltTotalWeight + ISNULL(@v_fltInvWeightByLPN,0)) > @v_fltPLGrossWeight
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		IF (@v_vchToLPNControl = 'NO')
			BEGIN
				SET @in_vchToLPN = NULL
			END

		--Calculate Volumn & Weight of Location
		IF (@v_fltLocWidth > 0 AND @v_fltLocLength > 0 AND @v_fltLocHeight > 0 AND @v_fltLocGrossWeight > 0)
			BEGIN
				--Calculate Volumn
				SET @v_fltLocVolumn = (@v_fltLocWidth * @v_fltLocLength * @v_fltLocHeight)
		
				--Check volumn and weight
				IF @v_fltVolumn > (@v_fltLocVolumn - @v_fltLocTotalVolumn)
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				IF @v_fltTotalWeight > (@v_fltLocGrossWeight - @v_fltLocTotalWeight)
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				UPDATE t_wms_location SET 
						total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
					,total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE location_id = @in_vchToLocationID
			END

		--Check Location & Duplicate LPN & Check Capacity
		EXEC usp_location_validation_all @in_vchApplicationID		= @in_vchApplicationID	
										,@in_vchUserID				= @in_vchUserID
										,@in_vchWarehouseID			= @in_vchToWhMasterID		
										,@in_vchLocationID			= @in_vchToLocationID
										,@in_vchParentLPN			= @in_vchToParentLPN
										,@in_vchLPN					= @in_vchToLPN
										,@in_vchWhItemMasterID		= @v_vchToWhItemMasterID
										,@in_vchItemNumber			= @v_vchItemNumber
										,@in_vchOwnerID				= @v_vchOwnerID
										,@in_vchInventoryStatusID	= @v_vchInvStatusID
										,@in_vchLotNumber			= @v_vchLotNumber
										,@in_vchExpiryDate			= @v_vchExpiryDate
										,@in_vchSerialNo			= 'ALL'	--ส่ง All เนื่องจาก Move ทั้งหมด
										,@in_vchAttribute1			= @v_vchAttribute1
										,@in_vchAttribute2			= @v_vchAttribute2
										,@in_vchAttribute3			= @v_vchAttribute3
										,@in_vchAttribute4			= @v_vchAttribute4
										,@in_vchAttribute5			= @v_vchAttribute5
										,@in_vchLotControl			= @v_vchLotControl			
										,@in_vchExpiryDateControl	= @v_vchExpControl
										,@in_vchSNControl			= @v_vchSNControl			
										,@in_vchAttribute1Control	= @v_vchAttribute1Control
										,@in_vchAttribute2Control	= @v_vchAttribute2Control
										,@in_vchAttribute3Control	= @v_vchAttribute3Control
										,@in_vchAttribute4Control	= @v_vchAttribute4Control
										,@in_vchAttribute5Control	= @v_vchAttribute5Control
										,@in_ReceiveDate			= @v_dtReceiveDate		
										,@out_vchErrorCode			= @out_ErrorCode OUTPUT
										,@out_vchMessage		 	= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchToWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @in_vchToLocationID
		AND wh_item_master_id = @v_vchToWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchToWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchToWhItemMasterID
								, @in_vchLocationID			= @in_vchToLocationID
								, @in_vchStatusID			= @v_vchInvStatusID
								, @in_vchPalentLPN			= @in_vchToParentLPN
								, @in_vchLPN				= @in_vchToLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMFGDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber 
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @v_vchLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @v_vchExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END

		IF (@RuleCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
		BEGIN
			--update volumn & weight ของ LPN
			UPDATE t_wms_inventory SET 
					volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchDestInventoryID
			AND attribute_group_id = @v_vchDestAttributeGroupID		
		END

		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number IN (SELECT SerialNumber FROM @tInventorySerial) 

						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,@v_vchDestInventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL
				
		IF @in_vchToLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @in_vchToLocationID
		END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--กรณี Change Location ให้ตรวจสอบ ERP Location ต้นทางกับปลายทางตรงกันหรือไม่ถ้าตรงกันไม่ต้อง interface 
			IF  (ISNULL(@v_vchERPSourceLocation,'') = ISNULL(@v_vchERPDestLocation,'')) OR @v_vchFromLocType = 'UNPICK'
				BEGIN 
					SET @v_vchSubTranType = 'MOVE_ON_PC_NO_ERP'
				END
			ELSE
				BEGIN
					SET @v_vchSubTranType = 'MOVE_ON_PC'
				END 

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchFromWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE();
					IF @v_vchSNControl = 'NONE'
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type] 
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status] 
									,[control_value_1]
									,[control_value_2]
									,[receive_date]
									,[mfg_date]
									,[reason_code]
									--,[user_def1] 
									,[device]
									,[create_date]
									,[create_by])
								VALUES
									(NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType 
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,@v_vchFromWarehouse
									,@v_vchToWarehouse	
									,@v_vchFromLocation
									,@v_vchToLocation
									,@v_vchOwner
									,@v_vchOwner
									,@v_vchItemNumber
									,@v_fltQtyUpdate
									,@v_vchBaseUomPrompt
									,@v_fltAfterQty
									,@v_vchBaseUomPrompt
									,@v_vchLotNumber
									,@v_vchLotNumber
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,NULL
									,@v_vchAttribute1
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute4
									,@v_vchAttribute5
									,@v_vchAttribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,@v_vchFromLPN
									,@in_vchToLpn
									,@v_vchInvStatus
									,@v_vchInvStatus 
									,@v_vchERPSourceLocation
									,@v_vchERPDestLocation
									,@v_dtReceiveDate
									,@v_dtMfgDate
									,@v_vchReasonCode
									--,@v_vchReasonDescription 
									,@in_vchDeviceID
									,GETDATE()
									,@in_vchUserID)
						END
					ELSE
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
								([record_id]
								,[host_record_id]
								,[processing_code]
								,[processing_status]
								,[app_id]
								,[app_name]
								,[tran_type]
								,[sub_tran_type] 
								,[start_tran_datetime]
								,[end_tran_datetime]
								,[warehouse]
								,[to_warehouse]
								,[location]
								,[to_location]
								,[owner]
								,[to_owner]
								,[item_number]
								,[quantity]
								,[quantity_uom]
								,[after_quantity]
								,[after_quantity_uom]
								,[lot_number]
								,[after_lot_number]
								,[expiry_date]
								,[after_expiry_date]
								,[serial_number]
								,[attribute1]
								,[after_attribute1]
								,[attribute2]
								,[after_attribute2]
								,[attribute3]
								,[after_attribute3]
								,[attribute4]
								,[after_attribute4]
								,[attribute5]
								,[after_attribute5]
								,[user_id]
								,[reference_number]
								,[lpn]
								,[after_lpn]
								,[status]
								,[after_status] 
								,[control_value_1]
								,[control_value_2]
								,[receive_date]
								,[mfg_date]
								,[reason_code]
								--,[user_def1] 
								,[device]
								,[create_date]
								,[create_by])
							SELECT NEWID()
								,@v_vchHostRecordID
								,'ADD'  
								,'PENDING'
								,@in_vchApplicationID
								,@v_vchApplicationName
								,@v_vchTranType
								,@v_vchSubTranType 
								,@v_dtStartTranDate
								,@v_dtProcessDateTime
								,@v_vchFromWarehouse
								,@v_vchToWarehouse	
								,@v_vchFromLocation
								,@v_vchToLocation
								,@v_vchOwner
								,@v_vchOwner
								,@v_vchItemNumber
								,@v_fltQtyUpdate
								,@v_vchBaseUomPrompt
								,@v_vchInvQuantity - RowNumber
								,@v_vchBaseUomPrompt
								,@v_vchLotNumber
								,@v_vchLotNumber
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,SerialNumber
								,@v_vchAttribute1
								,@v_vchAttribute1
								,@v_vchAttribute2
								,@v_vchAttribute2
								,@v_vchAttribute3
								,@v_vchAttribute3
								,@v_vchAttribute4
								,@v_vchAttribute4
								,@v_vchAttribute5
								,@v_vchAttribute5
								,@in_vchUserID
								,@in_vchReferenceNumber 
								,@v_vchFromLPN
								,@in_vchToLpn
								,@v_vchInvStatus
								,@v_vchInvStatus 
								,@v_vchERPSourceLocation
								,@v_vchERPDestLocation
								,@v_dtReceiveDate
								,@v_dtMfgDate
								,@v_vchReasonCode
								--,@v_vchReasonDescription 
								,@in_vchDeviceID
								,GETDATE()
								,@in_vchUserID
							FROM @tInventorySerial 
							ORDER BY RowNumber
						END
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE(); 
			IF @v_vchSNControl = 'NONE'
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[reason_code]
						,[udf_1] 
						,[receive_date]
						,[mfg_date]
						,[input_quantity]
						,[input_uom]
						,[device]
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType
						,'Change Location'
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,@v_vchFromWarehouse
						,@v_vchToWarehouse
						,@v_vchFromLocation
						,@v_vchToLocation
						,@v_vchOwner
						,@v_vchOwner
						,@v_vchItemNumber
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@v_fltAfterQty
						,@v_vchBaseUomPrompt
						,@v_vchLotNumber
						,@v_vchLotNumber
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,NULL
						,@v_vchAttribute1
						,@v_vchAttribute1
						,@v_vchAttribute2
						,@v_vchAttribute2
						,@v_vchAttribute3
						,@v_vchAttribute3
						,@v_vchAttribute4
						,@v_vchAttribute4
						,@v_vchAttribute5
						,@v_vchAttribute5
						,@in_vchUserID
						,@in_vchReferenceNumber
						,@v_vchHostRecordID
						,@v_vchFromLPN
						,@in_vchToLpn
						,@v_vchFromParentLPN
						,@in_vchToParentLpn
						,@v_vchInvStatus
						,@v_vchInvStatus 
						,@v_vchERPSourceLocation
						,@v_vchERPDestLocation
						,@v_vchReasonCode
						,@in_vchRemark
						,@v_dtReceiveDate
						,@v_dtMfgDate
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID) 
				END
			ELSE
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
					   ([tran_id]
					   ,[app_id]
					   ,[app_name]
					   ,[tran_type]
					   ,[sub_tran_type]
					   ,[description]
					   ,[start_tran_datetime]
					   ,[end_tran_datetime]
					   ,[warehouse]
					   ,[to_warehouse]
					   ,[location]
					   ,[to_location]
					   ,[owner]
					   ,[to_owner]
					   ,[item_number]
					   ,[quantity]
					   ,[quantity_uom]
					   ,[after_quantity]
					   ,[after_quantity_uom]
					   ,[lot_number]
					   ,[after_lot_number]
					   ,[expiry_date]
					   ,[after_expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[after_attribute1]
					   ,[attribute2]
					   ,[after_attribute2]
					   ,[attribute3]
					   ,[after_attribute3]
					   ,[attribute4]
					   ,[after_attribute4]
					   ,[attribute5]
					   ,[after_attribute5]
					   ,[user_id]
					   ,[reference_number]
					   ,[control_number]
					   ,[lpn]
					   ,[after_lpn]
					   ,[parent_lpn]
					   ,[after_parent_lpn]
					   ,[status]
					   ,[after_status] 
					   ,[control_value_1]
					   ,[control_value_2]
					   ,[reason_code]
					   ,[udf_1] 
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom]
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 SELECT NEWID()
					   ,@in_vchApplicationID
					   ,@v_vchApplicationName
					   ,@v_vchTranType
					   ,@v_vchSubTranType
					   ,'Change Location'
					   ,@v_dtStartTranDate
					   ,@v_dtProcessDateTime
					   ,@v_vchFromWarehouse
					   ,@v_vchToWarehouse
					   ,@v_vchFromLocation
					   ,@v_vchToLocation
					   ,@v_vchOwner
					   ,@v_vchOwner
					   ,@v_vchItemNumber
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@v_vchInvQuantity - RowNumber
					   ,@v_vchBaseUomPrompt
					   ,@v_vchLotNumber
					   ,@v_vchLotNumber
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,SerialNumber
					   ,@v_vchAttribute1
					   ,@v_vchAttribute1
					   ,@v_vchAttribute2
					   ,@v_vchAttribute2
					   ,@v_vchAttribute3
					   ,@v_vchAttribute3
					   ,@v_vchAttribute4
					   ,@v_vchAttribute4
					   ,@v_vchAttribute5
					   ,@v_vchAttribute5
					   ,@in_vchUserID
					   ,@in_vchReferenceNumber
					   ,@v_vchHostRecordID
					   ,@v_vchFromLPN
					   ,@in_vchToLpn
					   ,@v_vchFromParentLPN
					   ,@in_vchToParentLpn
					   ,@v_vchInvStatus
					   ,@v_vchInvStatus 
					   ,@v_vchERPSourceLocation
					   ,@v_vchERPDestLocation
					   ,@v_vchReasonCode
					   ,@in_vchRemark  
					   ,@v_dtReceiveDate
					   ,@v_dtMfgDate
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt 
					   ,@in_vchDeviceID
					   ,GETDATE()
					   ,@in_vchUserID
					FROM @tInventorySerial
					ORDER BY RowNumber
				END
		END

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'MOVE'
									   ,@in_vchWhMasterID	= @v_vchFromWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwner
									   ,@in_vchLocationID	= @v_vchFromLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchInvStatusID
									   ,@in_vchToWhMasterID	= @in_vchToWhMasterID
									   ,@in_vchToLocationID	= @in_vchToLocationID
									   ,@in_vchToInvStatusID = @v_vchInvStatusID
									   ,@in_fltQuantity		= @v_fltQtyUpdate
									   ,@in_vchUserID		= @in_vchUserID

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchFromLocation,'') + '] To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
		SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET  @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + ']'
		SET  @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchFromWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchFromLocation,'') + '] To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
	SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET  @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] ' + 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
	 
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchFromWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @out_ErrorMessage,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_location_by_serial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_location_by_serial] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchToWhMasterID		UNIQUEIDENTIFIER,
	@in_vchToLocationID		UNIQUEIDENTIFIER,
	@in_vchToParentLPN		NVARCHAR(25),
	@in_vchToLPN			NVARCHAR(25),
	@in_vchSerialNumber		NVARCHAR(50),
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_location_by_serial]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5)
	DECLARE @RultCheckFullLPN		VARCHAR(3)
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_MOVE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = ''
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchFromWhMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchFromWarehouse		NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchFromLocationID	UNIQUEIDENTIFIER
	DECLARE @v_vchFromLocation		NVARCHAR(50)
	DECLARE @v_vchFromLPNControl	VARCHAR(5)
	DECLARE @v_vchFromLocType		NVARCHAR(20)
 
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER
	DECLARE @v_vchInvStatus			NVARCHAR(50)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchFromParentLPN		NVARCHAR(25)
	DECLARE @v_vchFromLPN			NVARCHAR(25)
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate	    NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)
	DECLARE @v_fltConversionFactor		FLOAT
	DECLARE @v_fltWidth					FLOAT = 0
	DECLARE @v_fltLength				FLOAT = 0
	DECLARE @v_fltHeight				FLOAT = 0
	DECLARE @v_fltGrossWeight			FLOAT = 0
	DECLARE @v_intPercentTolerance		FLOAT = 0
	DECLARE @v_intPercenToleranceWeight FLOAT = 0
	DECLARE @v_fltVolumn				FLOAT = 0	--item
	DECLARE @v_fltTotalWeight			FLOAT = 0	--item

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0
	
	--Destination
	DECLARE @v_vchToWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchToWarehouse		NVARCHAR(25)
	DECLARE @v_vchToLocation		NVARCHAR(50)
	DECLARE @v_vchToLPNControl		VARCHAR(5)
	DECLARE @v_fltLocTotalVolumn	FLOAT = 0
	DECLARE @v_fltLocTotalWeight	FLOAT = 0
	DECLARE @v_fltLocWidth			FLOAT = 0
	DECLARE @v_fltLocLength			FLOAT = 0
	DECLARE @v_fltLocHeight			FLOAT = 0
	DECLARE @v_fltLocGrossWeight	FLOAT = 0
	DECLARE @v_fltLocVolumn			FLOAT = 0


	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RultCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT @v_vchReasonCode = reason_code
			--, @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		SELECT @v_vchToWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchToWhMasterID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		 
		--GET From Location
		SELECT TOP 1 @v_vchInventoryID	= tInv.inventory_id
			,@v_vchAttributeGroupID		= tInv.attribute_group_id
			,@v_vchFromWhMasterID		= tInv.wh_master_id
			,@v_vchFromWarehouse		= wh.wh_id
			,@v_vchOwnerID				= tInv.owner_id
			,@v_vchOwner				= own.owner_code
			,@v_vchFromLocationID		= tInv.location_id
			,@v_vchFromLocation			= loc.location
			,@v_vchFromLocType			= loc.loc_type
			,@v_vchERPSourceLocation	= loc.erp_location
			,@v_vchFromLPNControl		= loc.lpn_controlled
			,@v_vchFromParentLPN		= tInv.parent_lpn
			,@v_vchFromLPN				= tInv.lpn
			,@v_vchWhItemMasterID		= tInv.wh_item_master_id
			,@v_vchItemMasterID			= item.item_master_id
			,@v_vchItemNumber			= item_number
			,@v_vchInvQuantity			= tInv.quantity
			,@v_vchInvQtyAllocate		= tInv.quantity_allocated
			,@v_vchBaseItemUomID		= uom.item_uom_id 
			,@v_vchBaseUomPrompt		= uom.uom_prompt
			,@v_fltConversionFactor		= uom.conversion_factor
			,@v_fltWidth				= ISNULL(uom.width,0)
			,@v_fltLength				= ISNULL(uom.length,0)
			,@v_fltHeight				= ISNULL(uom.height,0)
			,@v_fltGrossWeight			= ISNULL(uom.gross_weight,0)
			,@v_intPercentTolerance		= ISNULL(uom.percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(uom.percent_tolerance_weight,0)
			,@v_vchInvStatusID			= tInv.inventory_status_id
			,@v_vchInvStatus			= invST.inv_status
			,@v_vchLotNumber			= invLot.lot_number
			,@v_vchExpiryDate			= invExp.expiry_date
			,@v_vchAttribute1			= invAttribute1.attribute1
			,@v_vchAttribute2			= invAttribute2.attribute2
			,@v_vchAttribute3			= invAttribute3.attribute3
			,@v_vchAttribute4			= invAttribute4.attribute4
			,@v_vchAttribute5			= invAttribute5.attribute5
			,@v_dtReceiveDate			= tInv.receive_date
			,@v_dtMfgDate				= tInv.mfg_date
			,@v_vchLotControl			= item.lot_control
			,@v_vchExpControl			= item.expiry_date_control
			,@v_vchSNControl			= item.sn_control
			,@v_vchAttribute1Control	= item.attribute1_control
			,@v_vchAttribute2Control	= item.attribute2_control
			,@v_vchAttribute3Control	= item.attribute3_control
			,@v_vchAttribute4Control	= item.attribute4_control
			,@v_vchAttribute5Control	= item.attribute5_control
		FROM (SELECT inventory_id 
				,attribute_group_id
				,wh_master_id
				,owner_id
				,location_id
				,parent_lpn
				,lpn
				,wh_item_master_id
				,quantity
				,quantity_allocated
				,inventory_status_id
				,receive_date
				,mfg_date
			  FROM dbo.t_wms_inventory
			  WHERE inventory_id = @in_vchInventoryID
			  ) tInv
		INNER JOIN dbo.t_wms_wh wh ON wh.wh_master_id = tInv.wh_master_id
		INNER JOIN dbo.t_wms_owner own ON own.owner_id = tInv.owner_id
		INNER JOIN dbo.t_wms_location loc ON tInv.location_id = loc.location_id
		INNER JOIN dbo.t_wms_inventory_status invST ON tInv.inventory_status_id = invST.inventory_status_id
		INNER JOIN dbo.t_wms_wh_item whItem ON tInv.wh_item_master_id = whItem.wh_item_master_id
		INNER JOIN dbo.t_wms_item item ON whItem.item_master_id = item.item_master_id
		INNER JOIN dbo.t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
						FROM dbo.t_wms_inventory_attribute
						WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON tInv.inventory_id = invLot.inventory_id AND tInv.attribute_group_id = invLot.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_6
						WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON tInv.inventory_id = invExp.inventory_id AND tInv.attribute_group_id = invExp.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_5
						WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttribute1 ON tInv.inventory_id = invAttribute1.inventory_id AND tInv.attribute_group_id = invAttribute1.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_4
						WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttribute2 ON tInv.inventory_id = invAttribute2.inventory_id AND tInv.attribute_group_id = invAttribute2.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_3
						WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttribute3 ON tInv.inventory_id = invAttribute3.inventory_id AND tInv.attribute_group_id = invAttribute3.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_2
						WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttribute4 ON tInv.inventory_id = invAttribute4.inventory_id AND tInv.attribute_group_id = invAttribute4.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_1
						WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttribute5 ON tInv.inventory_id = invAttribute5.inventory_id AND tInv.attribute_group_id = invAttribute5.attribute_group_id 

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
			
		--For Insert Serial to temp
		IF @v_vchSNControl = 'FULL'
			BEGIN
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY attribute_value) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,attribute_value
				FROM t_wms_inventory_attribute
				WHERE inventory_id = @in_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
				AND attribute_value = @in_vchSerialNumber 
			END

		--Qty Input = 0 or Null >> Get Qty from inventory
		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				--Move all qty
				SET @v_fltQtyUpdate = @v_vchInvQuantity
			END
		ELSE	
			BEGIN
				SET @v_fltQtyUpdate = @in_fltQty
			END

		--Set To Parent LPN = From Parent ถ้าไม่ได้ส่งค่ามา
		IF ISNULL(@in_vchToParentLPN,'') = ''
			BEGIN
				SET @in_vchToParentLPN = @v_vchFromParentLPN
			END

		--LPN Input = NULL and lpn Control >> get LPN from inventory
		IF @v_vchFromLPNControl = 'YES' AND ISNULL(@in_vchToLPN,'') = ''
			BEGIN
				SET @in_vchToLPN = @v_vchFromLPN
			END 

		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchFromLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END

		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchBaseUomPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC 
			END
			
		SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyUpdate,2)
		SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyUpdate,2)

		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
			,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
			,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
		DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
					
		--Update Volumn & Weight in from location
		IF @v_vchFromLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location]
					SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
					, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
					, update_date = GETDATE()  
					, [update_by] = @in_vchUserID   
				WHERE [location_id] = @v_vchFromLocationID
			END

	--------------------------------------------
	--Validate Destination Location
	--------------------------------------------
		--Check to location
		SET @v_vchToLocation = NULL
		SELECT @v_vchToLocation = location
			, @v_vchERPDestLocation = erp_location
			, @v_vchToLPNControl = lpn_controlled
			, @v_fltLocWidth = ISNULL(width,0)
			, @v_fltLocLength = ISNULL(length,0)
			, @v_fltLocHeight = ISNULL(height,0)
			, @v_fltLocGrossWeight = ISNULL(gross_weight,0)
			, @v_fltLocTotalWeight = ISNULL(total_weight,0)
			, @v_fltLocTotalVolumn = ISNULL(total_volumn,0)
		FROM t_wms_location 
		WHERE wh_master_id = @in_vchToWhMasterID 
		AND location_id = @in_vchToLocationID
		AND is_active = 'YES'
		IF(@v_vchToLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Check Location ต้นทางปลายทาง
		IF @v_vchFromLocationID = @in_vchToLocationID
			BEGIN
				SET @out_ErrorCode = 'INFO-SOURCE-LOC-CANNOT-DUP-DEST-LOC'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Validate To LPN
		IF @v_vchToLPNControl = 'YES' AND ISNULL(@in_vchToLPN,'') = '' AND ISNULL(@in_fltQty,0) > 0 
			BEGIN
				SET @out_ErrorCode = 'TO_LPN_CANNOT_BE_EMPTY';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
				
		-- Check to warehouse item master id
		IF (@v_vchFromWhMasterID <> @in_vchToWhMasterID)
			BEGIN
				SET @v_vchToWhItemMasterID = NULL
				SELECT @v_vchToWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchToWhMasterID AND item_master_id = @v_vchItemMasterID

				-- check warehouse item
				IF(@v_vchToWhItemMasterID IS NULL)
				BEGIN 
					SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToWarehouse,@v_vchItemNumber,'@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END
		ELSE
			BEGIN
				SET @v_vchToWhItemMasterID = @v_vchWhItemMasterID 
			END
			
		-- Check duplicate parent lpn.
		IF (ISNULL(@in_vchToParentLPN,'') <> '')
			BEGIN
				DECLARE @v_vchDubLocation	NVARCHAR(50) = NULL

				SELECT TOP 1 @v_vchDubLocation = loc.location
				FROM t_wms_inventory inv
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				WHERE inv.wh_master_id = @in_vchToWhMasterID 
				AND ISNULL(inv.location_id,'') <> ISNULL(@in_vchToLocationID,'')
				AND inv.parent_lpn = @in_vchToParentLPN
				
				IF (ISNULL(@v_vchDubLocation,'') <> '')
					BEGIN
						SET @out_ErrorCode = 'PARENT_LPN_DUPPLICATE';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		
		--Calculate volumn & weight of LPN
		IF (@RultCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
			BEGIN
				DECLARE @v_fltPalletID			UNIQUEIDENTIFIER = NULL,
						@v_fltPLGrossWeight		FLOAT = 0,
						@v_fltPLVolumn			FLOAT = 0,
						@v_fltInvVolumnByLPN	FLOAT = 0,
						@v_fltInvWeightByLPN	FLOAT = 0

				--Calculate Volumn & Weight of pallet
				SELECT @v_fltPalletID = pallet_id
					,@v_fltPLVolumn = ROUND(ISNULL(width,0) * ISNULL(length,0) * ISNULL(height,0),@Round)
					,@v_fltPLGrossWeight = ISNULL(gross_weight,0)
				FROM t_wms_pallet_type 
				WHERE is_active = 'YES'
				
				IF (@v_fltPalletID IS NULL)
					BEGIN
						SET @out_ErrorCode = 'PALLET_TYPE_CANNOT_BE_EMPTY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_fltInvVolumnByLPN = SUM(ISNULL(volumn_by_lpn,0))
					,@v_fltInvWeightByLPN = SUM(ISNULL(weight_by_lpn,0))
				FROM t_wms_inventory
				WHERE lpn = @in_vchToLPN

				--Volumn of qty input + volumn in inventory เทียบกับ volumn ที่กำหนด
				IF (@v_fltVolumn + ISNULL(@v_fltInvVolumnByLPN,0)) > @v_fltPLVolumn
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				IF (@v_fltTotalWeight + ISNULL(@v_fltInvWeightByLPN,0)) > @v_fltPLGrossWeight
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		IF (@v_vchToLPNControl = 'NO')
			BEGIN
				SET @in_vchToLPN = NULL
			END

		--Calculate Volumn & Weight of Location
		IF (@v_fltLocWidth > 0 AND @v_fltLocLength > 0 AND @v_fltLocHeight > 0 AND @v_fltLocGrossWeight > 0)
			BEGIN
				--Calculate Volumn
				SET @v_fltLocVolumn = (@v_fltLocWidth * @v_fltLocLength * @v_fltLocHeight)
		
				--Check volumn and weight
				IF @v_fltVolumn > (@v_fltLocVolumn - @v_fltLocTotalVolumn)
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				IF @v_fltTotalWeight > (@v_fltLocGrossWeight - @v_fltLocTotalWeight)
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				UPDATE t_wms_location SET 
						total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
					,total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE location_id = @in_vchToLocationID
			END

		--Check Location & Duplicate LPN & Check Capacity
		EXEC usp_location_validation_all @in_vchApplicationID		= @in_vchApplicationID	
										,@in_vchUserID				= @in_vchUserID
										,@in_vchWarehouseID			= @in_vchToWhMasterID		
										,@in_vchLocationID			= @in_vchToLocationID
										,@in_vchParentLPN			= @in_vchToParentLPN
										,@in_vchLPN					= @in_vchToLPN
										,@in_vchWhItemMasterID		= @v_vchToWhItemMasterID
										,@in_vchItemNumber			= @v_vchItemNumber
										,@in_vchOwnerID				= @v_vchOwnerID
										,@in_vchInventoryStatusID	= @v_vchInvStatusID
										,@in_vchLotNumber			= @v_vchLotNumber
										,@in_vchExpiryDate			= @v_vchExpiryDate
										,@in_vchSerialNo			= 'ALL'	--ส่ง All เนื่องจาก Move ทั้งหมด
										,@in_vchAttribute1			= @v_vchAttribute1
										,@in_vchAttribute2			= @v_vchAttribute2
										,@in_vchAttribute3			= @v_vchAttribute3
										,@in_vchAttribute4			= @v_vchAttribute4
										,@in_vchAttribute5			= @v_vchAttribute5
										,@in_vchLotControl			= @v_vchLotControl			
										,@in_vchExpiryDateControl	= @v_vchExpControl
										,@in_vchSNControl			= @v_vchSNControl			
										,@in_vchAttribute1Control	= @v_vchAttribute1Control
										,@in_vchAttribute2Control	= @v_vchAttribute2Control
										,@in_vchAttribute3Control	= @v_vchAttribute3Control
										,@in_vchAttribute4Control	= @v_vchAttribute4Control
										,@in_vchAttribute5Control	= @v_vchAttribute5Control
										,@in_ReceiveDate			= @v_dtReceiveDate		
										,@out_vchErrorCode			= @out_ErrorCode OUTPUT
										,@out_vchMessage		 	= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchToWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @in_vchToLocationID
		AND wh_item_master_id = @v_vchToWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchToWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchToWhItemMasterID
								, @in_vchLocationID			= @in_vchToLocationID
								, @in_vchStatusID			= @v_vchInvStatusID
								, @in_vchPalentLPN			= @in_vchToParentLPN
								, @in_vchLPN				= @in_vchToLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMFGDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber 
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @v_vchLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @v_vchExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END

		IF (@RultCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
		BEGIN
			--update volumn & weight ของ LPN
			UPDATE t_wms_inventory SET 
					volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchDestInventoryID
			AND attribute_group_id = @v_vchDestAttributeGroupID		
		END

		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number IN (SELECT SerialNumber FROM @tInventorySerial) 

						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,@v_vchDestInventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL
				
		IF @in_vchToLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @in_vchToLocationID
		END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--กรณี Change Location ให้ตรวจสอบ ERP Location ต้นทางกับปลายทางตรงกันหรือไม่ถ้าตรงกันไม่ต้อง interface 
			IF  (ISNULL(@v_vchERPSourceLocation,'') = ISNULL(@v_vchERPDestLocation,'')) OR @v_vchFromLocType = 'UNPICK'
				BEGIN 
					SET @v_vchSubTranType = 'MOVE_ON_PC_NO_ERP'
				END
			ELSE
				BEGIN
					SET @v_vchSubTranType = 'MOVE_ON_PC'
				END 

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchFromWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT  
				END

			--Write Tran Log
			DECLARE @v_dtExpiryDate DATE = NULL
			IF ISNULL(@v_vchExpiryDate,'') = '' 
				BEGIN
					SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate)
				END

			SET @v_dtProcessDateTime = GETDATE();
			EXEC usp_LogManager
				@in_vchApplicationID		= @in_vchApplicationID
				, @in_vchAppName			= @v_vchApplicationName
				, @in_vchDevice				= @in_vchDeviceID
				, @in_vchUserID				= @in_vchUserID
				, @in_vchLogType			= 'TRANSACTION'
				, @in_vchProcess			= @c_vchObjName
				, @in_dtProcessDateTime		= @v_dtProcessDateTime
				, @in_vchTranType			= @v_vchTranType
				, @in_vchSubTranType		= @v_vchSubTranType
				, @in_vchDescription		= 'Change Location by serial'
				, @in_dtStartTranDate		= @v_dtStartTranDate
				, @in_dtEndTranDate			= @v_dtProcessDateTime
				, @in_vchWhID 				= @v_vchFromWarehouse
				, @in_vchToWhID 			= @v_vchToWarehouse
				, @in_vchLocation			= @v_vchFromLocation
				, @in_vchToLocation			= @v_vchToLocation
				, @in_vchOwner				= @v_vchOwner
				, @in_vchToOwner			= @v_vchOwner
				, @in_vchItemNumber			= @v_vchItemNumber
				, @in_fltQuantity			= @v_fltQtyUpdate
				, @in_vchUOM				= @v_vchBaseUomPrompt
				, @in_fltAfterQuantity		= @v_fltAfterQty
				, @in_vchAfterUOM			= @v_vchBaseUomPrompt
				, @in_vchLotNumber			= @v_vchLotNumber
				, @in_vchAfterLotNumber		= @v_vchLotNumber
				, @in_dtExpiryDate			= @v_dtExpiryDate
				, @in_dtAfterExpiryDate		= @v_dtExpiryDate
				, @in_vchAttribute1			= @v_vchAttribute1	
				, @in_vchAfterAttribute1	= @v_vchAttribute1
				, @in_vchAttribute2			= @v_vchAttribute2
				, @in_vchAfterAttribute2	= @v_vchAttribute2
				, @in_vchAttribute3			= @v_vchAttribute3
				, @in_vchAfterAttribute3	= @v_vchAttribute3	
				, @in_vchAttribute4			= @v_vchAttribute4
				, @in_vchAfterAttribute4	= @v_vchAttribute4
				, @in_vchAttribute5			= @v_vchAttribute5
				, @in_vchAfterAttribute5	= @v_vchAttribute5
				, @in_vchSerialNumber		= @in_vchSerialNumber
				, @in_vchReferenceNumber	= @in_vchReferenceNumber
				, @in_vchLPN				= @v_vchFromLPN
				, @in_vchAfterLPN			= @in_vchToLpn
				, @in_vchParentLPN			= @v_vchFromParentLPN
				, @in_vchAfterParentLPN		= @in_vchToParentLpn
				, @in_vchStatus				= @v_vchInvStatus
				, @in_vchAfterStatus		= @v_vchInvStatus
				, @in_dtReceiveDate			= @v_dtReceiveDate
				, @in_dtProductionDate		= @v_dtMFGDate
				, @in_vchReasonCode			= @v_vchReasonCode 
				, @in_vchHostRecordID		= @v_vchHostRecordID	--ใช้ Interface
				, @in_vchControlNumber		= @v_vchHostRecordID	--ใช้ Write Log
				, @in_vchControlValue1		= @v_vchERPSourceLocation
				, @in_vchControlValue2		= @v_vchERPDestLocation
				, @in_vchInputQuantity		= @v_fltQtyUpdate
				, @in_vchInputUOM			= @v_vchBaseUomPrompt
				, @in_vchHUDF1				= @in_vchRemark
				, @in_vchErrorCode			= @out_ErrorCode OUTPUT
				, @in_vchMessage			= @out_ErrorMessage OUTPUT

			IF (@out_ErrorCode <> '0')
				BEGIN
					GOTO WRITE_PROC;
				END

		END

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'MOVE'
									   ,@in_vchWhMasterID	= @v_vchFromWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwner
									   ,@in_vchLocationID	= @v_vchFromLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchInvStatusID
									   ,@in_vchToWhMasterID	= @in_vchToWhMasterID
									   ,@in_vchToLocationID	= @in_vchToLocationID
									   ,@in_vchToInvStatusID = @v_vchInvStatusID
									   ,@in_fltQuantity		= @v_fltQtyUpdate
									   ,@in_vchUserID		= @in_vchUserID

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchFromLocation,'') + '] To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
		SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET  @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + ']'
		SET  @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchFromWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchFromLocation,'') + '] To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
	SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET  @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + ']'
	SET  @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchFromWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_lot]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_lot] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchToLotNumber		NVARCHAR(100),
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_lot]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_LOT'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchLPNControl		VARCHAR(5)
	DECLARE @v_vchLocType			NVARCHAR(20)
 
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER
	DECLARE @v_vchInvStatus			NVARCHAR(50)
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchFromLotNumber		NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchReasonCode = reason_code
			--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'')
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchWhMasterID	     = wh_master_id
			,@v_vchWarehouse	     = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchLocationID		 = location_id
			,@v_vchLocation			 = location
			,@v_vchLocType			 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchLPNControl		 = lpn_controlled
			,@v_vchParentLPN		 = parent_lpn
			,@v_vchLPN				 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchBaseUomPrompt	 = uom_prompt
			,@v_vchInvStatusID		 = inventory_status_id
			,@v_vchInvStatus		 = inv_status
			,@v_vchFromLotNumber	 = lot_number
			,@v_vchExpiryDate		 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtMfgDate			 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_item 
		WHERE inventory_id = @in_vchInventoryID

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		----ถ้า Item ที่ต้องการ Move Control Serial จะต้อง Move เต็มจำนวนเท่านั้น
		--IF @v_vchSNControl = 'FULL' AND ISNULL(@in_fltQty,0) > 0 
		--	BEGIN
		--		SET @out_ErrorCode = 'CONTROL_SN_CANNOT_MOVE_THIS_FUNCTION';
		--		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
		--		GOTO WRITE_PROC
		--	END
			 

		--For Insert Serial to temp
		IF @v_vchSNControl = 'FULL'
			BEGIN
				SET @in_fltQty = 0
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE inventory_id = @in_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				ORDER BY serial_number
			END

		--Qty Input = 0 or Null >> Get Qty from inventory
		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				--Move all qty
				SET @v_fltQtyUpdate = @v_vchInvQuantity
			END
		ELSE	
			BEGIN
				SET @v_fltQtyUpdate = @in_fltQty
			END
			 
		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END
			 
		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID
		DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID
	
		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		-- check location is mix lot?
		DECLARE @v_vchMixLot VARCHAR(5) = ''
		SELECT @v_vchMixLot = mix_lot FROM t_wms_location WHERE location_id = @v_vchLocationID
		IF EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
					LEFT JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number FROM dbo.t_wms_inventory_attribute
								WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'LOT' AND is_active = 'YES')
								) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
					WHERE inv.wh_master_id = @v_vchWhMasterID 
					AND inv.location_id = @v_vchLocationID
					AND inv.wh_item_master_id = @v_vchWhItemMasterID 
					AND ISNULL(invAttr.lot_number,'') <> ISNULL(@in_vchToLotNumber,''))
			AND @v_vchLotControl = 'FULL' 
			AND @v_vchMixLot = 'NO'
		BEGIN
			SET	@out_ErrorCode = 'LOCATION_NOT_MIX_LOT';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END 

		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchToLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
								, @in_vchLocationID			= @v_vchLocationID
								, @in_vchStatusID			= @v_vchInvStatusID
								, @in_vchPalentLPN			= @v_vchParentLPN
								, @in_vchLPN				= @v_vchLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMFGDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber 
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @in_vchToLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @v_vchExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END 
					
		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN 
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number IN (SELECT SerialNumber FROM @tInventorySerial)

						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,@v_vchDestInventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END

		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		IF @v_vchLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchLocationID
		END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE();
					IF @v_vchSNControl = 'NONE'
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type] 
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status] 
									,[control_value_1]
									,[control_value_2]
									,[receive_date]
									,[mfg_date]
									,[reason_code]
									,[device]
									,[create_date]
									,[create_by])
								VALUES
									(NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType 
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,@v_vchWarehouse
									,@v_vchWarehouse	
									,@v_vchLocation
									,@v_vchLocation
									,@v_vchOwner
									,@v_vchOwner
									,@v_vchItemNumber
									,@v_fltQtyUpdate
									,@v_vchBaseUomPrompt
									,@v_fltAfterQty
									,@v_vchBaseUomPrompt
									,@v_vchFromLotNumber
									,@in_vchToLotNumber
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,NULL
									,@v_vchAttribute1
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute4
									,@v_vchAttribute5
									,@v_vchAttribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,@v_vchLPN
									,@v_vchLPN
									,@v_vchInvStatus
									,@v_vchInvStatus 
									,@v_vchERPSourceLocation
									,@v_vchERPDestLocation
									,@v_dtReceiveDate
									,@v_dtMfgDate
									,@v_vchReasonCode 
									,@in_vchDeviceID
									,GETDATE()
									,@in_vchUserID)
						END
					ELSE
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
								([record_id]
								,[host_record_id]
								,[processing_code]
								,[processing_status]
								,[app_id]
								,[app_name]
								,[tran_type]
								,[sub_tran_type] 
								,[start_tran_datetime]
								,[end_tran_datetime]
								,[warehouse]
								,[to_warehouse]
								,[location]
								,[to_location]
								,[owner]
								,[to_owner]
								,[item_number]
								,[quantity]
								,[quantity_uom]
								,[after_quantity]
								,[after_quantity_uom]
								,[lot_number]
								,[after_lot_number]
								,[expiry_date]
								,[after_expiry_date]
								,[serial_number]
								,[attribute1]
								,[after_attribute1]
								,[attribute2]
								,[after_attribute2]
								,[attribute3]
								,[after_attribute3]
								,[attribute4]
								,[after_attribute4]
								,[attribute5]
								,[after_attribute5]
								,[user_id]
								,[reference_number]
								,[lpn]
								,[after_lpn]
								,[status]
								,[after_status] 
								,[control_value_1]
								,[control_value_2]
								,[receive_date]
								,[mfg_date]
								,[reason_code] 
								,[device]
								,[create_date]
								,[create_by])
							SELECT NEWID()
								,@v_vchHostRecordID
								,'ADD'  
								,'PENDING'
								,@in_vchApplicationID
								,@v_vchApplicationName
								,@v_vchTranType
								,@v_vchSubTranType 
								,@v_dtStartTranDate
								,@v_dtProcessDateTime
								,@v_vchWarehouse
								,@v_vchWarehouse	
								,@v_vchLocation
								,@v_vchLocation
								,@v_vchOwner
								,@v_vchOwner
								,@v_vchItemNumber
								,@v_fltQtyUpdate
								,@v_vchBaseUomPrompt
								,@v_vchInvQuantity - RowNumber
								,@v_vchBaseUomPrompt
								,@v_vchFromLotNumber
								,@in_vchToLotNumber
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,SerialNumber
								,@v_vchAttribute1
								,@v_vchAttribute1
								,@v_vchAttribute2
								,@v_vchAttribute2
								,@v_vchAttribute3
								,@v_vchAttribute3
								,@v_vchAttribute4
								,@v_vchAttribute4
								,@v_vchAttribute5
								,@v_vchAttribute5
								,@in_vchUserID
								,@in_vchReferenceNumber 
								,@v_vchLPN
								,@v_vchLPN
								,@v_vchInvStatus
								,@v_vchInvStatus 
								,@v_vchERPSourceLocation
								,@v_vchERPDestLocation
								,@v_dtReceiveDate
								,@v_dtMfgDate
								,@v_vchReasonCode 
								,@in_vchDeviceID
								,GETDATE()
								,@in_vchUserID
							FROM @tInventorySerial 
							ORDER BY RowNumber
						END
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE(); 
			IF @v_vchSNControl = 'NONE'
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[reason_code]
						,[udf_1]
						,[receive_date]
						,[mfg_date]
						,[input_quantity]
						,[input_uom]
						,[device]
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType
						,'Change Lot Number'
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,@v_vchWarehouse
						,@v_vchWarehouse
						,@v_vchLocation
						,@v_vchLocation
						,@v_vchOwner
						,@v_vchOwner
						,@v_vchItemNumber
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@v_fltAfterQty
						,@v_vchBaseUomPrompt
						,@v_vchFromLotNumber
						,@in_vchToLotNumber
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,NULL
						,@v_vchAttribute1
						,@v_vchAttribute1
						,@v_vchAttribute2
						,@v_vchAttribute2
						,@v_vchAttribute3
						,@v_vchAttribute3
						,@v_vchAttribute4
						,@v_vchAttribute4
						,@v_vchAttribute5
						,@v_vchAttribute5
						,@in_vchUserID
						,@in_vchReferenceNumber
						,@v_vchHostRecordID
						,@v_vchLPN
						,@v_vchLPN
						,@v_vchParentLPN
						,@v_vchParentLPN
						,@v_vchInvStatus
						,@v_vchInvStatus 
						,@v_vchERPSourceLocation
						,@v_vchERPDestLocation
						,@v_vchReasonCode
						,@in_vchRemark
						,@v_dtReceiveDate
						,@v_dtMfgDate
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID) 
				END
			ELSE
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
					   ([tran_id]
					   ,[app_id]
					   ,[app_name]
					   ,[tran_type]
					   ,[sub_tran_type]
					   ,[description]
					   ,[start_tran_datetime]
					   ,[end_tran_datetime]
					   ,[warehouse]
					   ,[to_warehouse]
					   ,[location]
					   ,[to_location]
					   ,[owner]
					   ,[to_owner]
					   ,[item_number]
					   ,[quantity]
					   ,[quantity_uom]
					   ,[after_quantity]
					   ,[after_quantity_uom]
					   ,[lot_number]
					   ,[after_lot_number]
					   ,[expiry_date]
					   ,[after_expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[after_attribute1]
					   ,[attribute2]
					   ,[after_attribute2]
					   ,[attribute3]
					   ,[after_attribute3]
					   ,[attribute4]
					   ,[after_attribute4]
					   ,[attribute5]
					   ,[after_attribute5]
					   ,[user_id]
					   ,[reference_number]
					   ,[control_number]
					   ,[lpn]
					   ,[after_lpn]
					   ,[parent_lpn]
					   ,[after_parent_lpn]
					   ,[status]
					   ,[after_status] 
					   ,[control_value_1]
					   ,[control_value_2]
					   ,[reason_code]
					   ,[udf_1]
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom] 
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 SELECT NEWID()
					   ,@in_vchApplicationID
					   ,@v_vchApplicationName
					   ,@v_vchTranType
					   ,@v_vchSubTranType
					   ,'Change Lot Number'
					   ,@v_dtStartTranDate
					   ,@v_dtProcessDateTime
					   ,@v_vchWarehouse
					   ,@v_vchWarehouse
					   ,@v_vchLocation
					   ,@v_vchLocation
					   ,@v_vchOwner
					   ,@v_vchOwner
					   ,@v_vchItemNumber
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@v_vchInvQuantity - RowNumber
					   ,@v_vchBaseUomPrompt
					   ,@v_vchFromLotNumber
					   ,@in_vchToLotNumber
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,SerialNumber
					   ,@v_vchAttribute1
					   ,@v_vchAttribute1
					   ,@v_vchAttribute2
					   ,@v_vchAttribute2
					   ,@v_vchAttribute3
					   ,@v_vchAttribute3
					   ,@v_vchAttribute4
					   ,@v_vchAttribute4
					   ,@v_vchAttribute5
					   ,@v_vchAttribute5
					   ,@in_vchUserID
					   ,@in_vchReferenceNumber
					   ,@v_vchHostRecordID
					   ,@v_vchLPN
					   ,@v_vchLPN
					   ,@v_vchParentLPN
					   ,@v_vchParentLPN
					   ,@v_vchInvStatus
					   ,@v_vchInvStatus 
					   ,@v_vchERPSourceLocation
					   ,@v_vchERPDestLocation
					   ,@v_vchReasonCode
					   ,@in_vchRemark
					   ,@v_dtReceiveDate
					   ,@v_dtMfgDate
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@in_vchDeviceID
					   ,GETDATE()
					   ,@in_vchUserID
					FROM @tInventorySerial
					ORDER BY RowNumber
				END
		END 

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchFromLotNumber,'') + '] To Lot: [' + ISNULL(@in_vchToLotNumber,'') + ']'
		SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchFromLotNumber,'') + '] To Lot: [' + ISNULL(@in_vchToLotNumber,'') + ']'
	SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchExpiryDate,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_lot_exp_by_serial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_lot_exp_by_serial] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchSerialNumber		NVARCHAR(50),
	@in_dtToMfgDate			DATE,
	@in_vchToExpiryDate		NVARCHAR(50),
	@in_vchToLotNumber		NVARCHAR(100), 
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_lot_exp_by_serial]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchLPNControl		VARCHAR(5)
	DECLARE @v_vchLocType			NVARCHAR(20)
 
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL 
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)
	 
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchReasonCode = reason_code
 		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchWhMasterID	     = wh_master_id
			,@v_vchWarehouse	     = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchLocationID		 = location_id
			,@v_vchLocation			 = location
			,@v_vchLocType			 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchLPNControl		 = lpn_controlled
			,@v_vchParentLPN		 = parent_lpn
			,@v_vchLPN				 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchBaseUomPrompt	 = uom_prompt
			,@v_vchInvStatusID		 = inventory_status_id
			,@v_vchInvStatus		 = inv_status
			,@v_vchLotNumber		 = lot_number
			,@v_vchExpiryDate		 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtMfgDate			 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_by_serial_item 
		WHERE inventory_id = @in_vchInventoryID
		AND serial_number = @in_vchSerialNumber

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		
		SET @v_fltQtyUpdate = 1
			 
		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END
			 
		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND invAttr.attribute_value = @in_vchSerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
		DELETE FROM t_wms_inventory WHERE quantity <= 0
	
		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		--Check Location & Duplicate LPN & Check Capacity
		EXEC usp_location_validation_all @in_vchApplicationID		= @in_vchApplicationID	
										,@in_vchUserID				= @in_vchUserID
										,@in_vchWarehouseID			= @v_vchWhMasterID		
										,@in_vchLocationID			= @v_vchLocationID
										,@in_vchParentLPN			= @v_vchParentLPN
										,@in_vchLPN					= @v_vchLPN
										,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
										,@in_vchItemNumber			= @v_vchItemNumber
										,@in_vchOwnerID				= @v_vchOwnerID
										,@in_vchInventoryStatusID	= @v_vchInvStatusID
										,@in_vchLotNumber			= @in_vchToLotNumber
										,@in_vchExpiryDate			= @in_vchToExpiryDate
										,@in_vchSerialNo			= @in_vchSerialNumber
										,@in_vchAttribute1			= @v_vchAttribute1
										,@in_vchAttribute2			= @v_vchAttribute2
										,@in_vchAttribute3			= @v_vchAttribute3
										,@in_vchAttribute4			= @v_vchAttribute4
										,@in_vchAttribute5			= @v_vchAttribute5
										,@in_vchLotControl			= @v_vchLotControl			
										,@in_vchExpiryDateControl	= @v_vchExpControl
										,@in_vchSNControl			= @v_vchSNControl			
										,@in_vchAttribute1Control	= @v_vchAttribute1Control
										,@in_vchAttribute2Control	= @v_vchAttribute2Control
										,@in_vchAttribute3Control	= @v_vchAttribute3Control
										,@in_vchAttribute4Control	= @v_vchAttribute4Control
										,@in_vchAttribute5Control	= @v_vchAttribute5Control
										,@in_ReceiveDate			= @v_dtReceiveDate		
										,@out_vchErrorCode			= @out_ErrorCode OUTPUT
										,@out_vchMessage		 	= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		------------------------------------------------------------------------------
		--กรณีที่มีการเก็บ MFG Date เวลา Save ต้อง MFG Date มา ถ้าไม่ส่งมา จะ get inventory เดิมไป  
		--Check To MFG Date ที่ต้องการแก้ไข จะต้องเท่ากับปลายทางที่มีอยู่
		------------------------------------------------------------------------------
		IF @v_vchExpControl = 'FULL'
			BEGIN
				DECLARE @v_dtCheckMfgDate DATE = NULL
				SELECT TOP 1 @v_dtCheckMfgDate = mfg_date
				FROM v_wms_inventory_data_by_id
				WHERE wh_master_id = @V_vchWhMasterID 
				AND owner_id = @V_vchOwnerID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchToLotNumber,'')
				AND ISNULL([expiry_date],'') = ISNULL(@in_vchToExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'') 
		
				IF @in_dtToMfgDate <> @v_dtCheckMfgDate
					BEGIN
						SET @out_ErrorCode = 'MFG_DATE_NOT_MATCH_IN_INVENTORY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		

		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchToLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchToExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
								, @in_vchLocationID			= @v_vchLocationID
								, @in_vchStatusID			= @v_vchInvStatusID
								, @in_vchPalentLPN			= @v_vchParentLPN
								, @in_vchLPN				= @v_vchLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @in_dtToMfgDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value = @in_vchSerialNumber
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							(NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, @in_vchSerialNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							(NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, @in_vchSerialNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @in_vchToLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @in_vchToExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END 

		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number = @in_vchSerialNumber

						INSERT INTO [dbo].[t_wms_inventory_remark]
							([inventory_remark_id]
							,[inventory_id]
							,[serial_number]
							,[reason_id]
							,[remark]
							,[create_by]
							,[create_date] )
						VALUES
							( NEWID()
							,@v_vchDestInventoryID
							,@in_vchSerialNumber
							,@in_vchReasonID
							,@in_vchRemark
							,@in_vchUserID
							,GETDATE())
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		IF @v_vchLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchLocationID
			END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT  
				END

			--Write Tran Log
			DECLARE @v_dtExpiryDate DATE = NULL
			DECLARE @v_dtToExpiryDate DATE = NULL
			IF ISNULL(@v_vchExpiryDate,'') = '' 
				BEGIN
					SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate)
				END
			
			IF ISNULL(@in_vchToExpiryDate,'') = '' 
				BEGIN
					SET @v_dtToExpiryDate = CONVERT(DATE,@in_vchToExpiryDate)
				END

			SET @v_dtProcessDateTime = GETDATE();
			EXEC usp_LogManager
				@in_vchApplicationID		= @in_vchApplicationID
				, @in_vchAppName			= @v_vchApplicationName
				, @in_vchDevice				= @in_vchDeviceID
				, @in_vchUserID				= @in_vchUserID
				, @in_vchLogType			= 'TRANSACTION'
				, @in_vchProcess			= @c_vchObjName
				, @in_dtProcessDateTime		= @v_dtProcessDateTime
				, @in_vchTranType			= @v_vchTranType
				, @in_vchSubTranType		= @v_vchSubTranType
				, @in_vchDescription		= 'Change Inventory Lot Exp. by serial'
				, @in_dtStartTranDate		= @v_dtStartTranDate
				, @in_dtEndTranDate			= @v_dtProcessDateTime
				, @in_vchWhID 				= @v_vchWarehouse
				, @in_vchToWhID 			= @v_vchWarehouse
				, @in_vchLocation			= @v_vchLocation
				, @in_vchToLocation			= @v_vchLocation
				, @in_vchOwner				= @v_vchOwner
				, @in_vchToOwner			= @v_vchOwner
				, @in_vchItemNumber			= @v_vchItemNumber
				, @in_fltQuantity			= @v_fltQtyUpdate
				, @in_vchUOM				= @v_vchBaseUomPrompt
				, @in_fltAfterQuantity		= @v_fltAfterQty
				, @in_vchAfterUOM			= @v_vchBaseUomPrompt
				, @in_vchLotNumber			= @v_vchLotNumber
				, @in_vchAfterLotNumber		= @in_vchToLotNumber
				, @in_dtExpiryDate			= @v_dtExpiryDate
				, @in_dtAfterExpiryDate		= @v_dtToExpiryDate
				, @in_vchAttribute1			= @v_vchAttribute1	
				, @in_vchAfterAttribute1	= @v_vchAttribute1
				, @in_vchAttribute2			= @v_vchAttribute2
				, @in_vchAfterAttribute2	= @v_vchAttribute2
				, @in_vchAttribute3			= @v_vchAttribute3
				, @in_vchAfterAttribute3	= @v_vchAttribute3	
				, @in_vchAttribute4			= @v_vchAttribute4
				, @in_vchAfterAttribute4	= @v_vchAttribute4
				, @in_vchAttribute5			= @v_vchAttribute5
				, @in_vchAfterAttribute5	= @v_vchAttribute5
				, @in_vchSerialNumber		= @in_vchSerialNumber
				, @in_vchReferenceNumber	= @in_vchReferenceNumber
				, @in_vchLPN				= @v_vchLPN
				, @in_vchAfterLPN			= @v_vchLPN
				, @in_vchParentLPN			= @v_vchParentLPN
				, @in_vchAfterParentLPN		= @v_vchParentLPN
				, @in_vchStatus				= @v_vchInvStatus
				, @in_vchAfterStatus		= @v_vchInvStatus
				, @in_dtReceiveDate			= @v_dtReceiveDate
				, @in_dtProductionDate		= @v_dtToExpiryDate
				, @in_vchReasonCode			= @v_vchReasonCode 
				, @in_vchHostRecordID		= @v_vchHostRecordID	--ใช้ Interface
				, @in_vchControlNumber		= @v_vchHostRecordID	--ใช้ Write Log
				, @in_vchControlValue1		= @v_vchERPSourceLocation
				, @in_vchControlValue2		= @v_vchERPDestLocation
				, @in_vchInputQuantity		= @v_fltQtyUpdate
				, @in_vchInputUOM			= @v_vchBaseUomPrompt
				, @in_vchHUDF1				= @in_vchRemark
				, @in_vchErrorCode			= @out_ErrorCode OUTPUT
				, @in_vchMessage			= @out_ErrorMessage OUTPUT

			IF (@out_ErrorCode <> '0')
				BEGIN
					GOTO WRITE_PROC;
				END

		END

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'CHANGE_STATUS'
									   ,@in_vchWhMasterID	= @v_vchWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwner
									   ,@in_vchLocationID	= @v_vchLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchInvStatusID
									   ,@in_vchToWhMasterID	= @v_vchWhMasterID
									   ,@in_vchToLocationID	= @v_vchLocationID
									   ,@in_vchToInvStatusID = @v_vchInvStatusID
									   ,@in_fltQuantity		= @v_fltQtyUpdate
									   ,@in_vchUserID		= @in_vchUserID
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] To Lot: [' + ISNULL(@in_vchToLotNumber,'') + ']'
		SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchLotNumber,'') + '] To Exp: [' + ISNULL(@in_vchToExpiryDate,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] To Lot: [' + ISNULL(@in_vchToLotNumber,'') + ']'
	SET @v_vchProcessData4 = 'Exp: ['+ ISNULL(@v_vchLotNumber,'') + '] To Exp: [' + ISNULL(@in_vchToExpiryDate,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage		

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_mfg_date]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_mfg_date] 
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25)  = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_vchItemNumber		NVARCHAR(50)  = NULL,
	@in_vchLotNumber		NVARCHAR(50)  = NULL,
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_dtToMfgDate			DATE = NULL,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON; 
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_mfg_date]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5)
	DECLARE @RuleCheckFullLPN		VARCHAR(3)
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_MFG'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	 
	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RuleCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT @v_vchReasonCode = reason_code FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		SELECT inventory_id
			,attribute_group_id
			,wh_master_id
			,wh_id
			,owner_id
			,owner_code
			,location_id
			,location
			,loc_type
			,erp_location
			,lpn_controlled
			,parent_lpn
			,lpn
			,wh_item_master_id
			,item_master_id
			,item_number
			,quantity
			,quantity_allocated
			,item_uom_id
			,uom
			,inventory_status_id
			,inv_status
			,lot_number
			,expiry_date
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5
			,receive_date
			,mfg_date
			,sn_control
		INTO #tInventory
		FROM v_wms_inventory_data_item
		WHERE wh_master_id = @in_vchWhMasterID		
		AND owner_id = @in_vchOwnerID			
		AND wh_item_master_id = @in_vchWhItemMasterID	
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')		
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')	
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')	
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')	
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')	
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

		IF NOT EXISTS (SELECT inventory_id FROM #tInventory)
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		  
		IF EXISTS (SELECT inventory_id FROM #tInventory WHERE loc_type = 'STG')
			BEGIN
				SET @out_ErrorCode = 'HAVE_DATA_ON_STG';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		  
		IF EXISTS (SELECT inventory_id FROM #tInventory WHERE quantity_allocated > 0)
			BEGIN
				SET @out_ErrorCode = 'INV_HAVE_ALLOCATE_CANNOT_CHANGE_MFG';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		
		--Insert Serial in Inventory
		IF EXISTS (SELECT * FROM #tInventory WHERE sn_control = 'FULL')
		BEGIN
			INSERT INTO @tInventorySerial
			SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
				,inventory_id
				,attribute_group_id
				,quantity
				,serial_number
			FROM v_wms_inventory_data_serial_by_id
			WHERE inventory_id IN (SELECT inventory_id FROM #tInventory)
			AND ISNULL(serial_number,'') <> ''
			ORDER BY serial_number
		END

		--Update Inventory
		UPDATE t_wms_inventory SET mfg_date = @in_dtToMfgDate
		from t_wms_inventory inv 
		INNER JOIN #tInventory ON inv.inventory_id = #tInventory.inventory_id
		 
		
		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF EXISTS (SELECT inventory_id FROM #tInventory WHERE sn_control = 'FULL')
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						FROM t_wms_inventory_remark tRemark
						INNER JOIN @tInventorySerial tInvSN ON tRemark.inventory_id = tInvSN.InventoryID AND tRemark.serial_number = tInvSN.SerialNumber
						  
						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,InventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						UPDATE t_wms_inventory_remark SET 
							 reason_id = @in_vchReasonID
							,remark = @in_vchRemark
							,update_by = @in_vchUserID
							,update_date = GETDATE()
						FROM t_wms_inventory_remark tRemark
						INNER JOIN #tInventory tInv ON tRemark.inventory_id = tInv.inventory_id

						INSERT INTO [dbo].[t_wms_inventory_remark]
							([inventory_remark_id]
							,[inventory_id]
							,[serial_number]
							,[reason_id]
							,[remark]
							,[create_by]
							,[create_date] )
						SELECT NEWID()
							,inventory_id	
							,NULL
							,@in_vchReasonID
							,@in_vchRemark
							,@in_vchUserID
							,GETDATE()
						FROM #tInventory
						WHERE inventory_id NOT IN (SELECT inventory_id FROM t_wms_inventory_remark)
						ORDER BY inventory_id
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL 
		
 
		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	  
			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @in_vchWhID AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE();
					IF EXISTS (SELECT inventory_id FROM #tInventory WHERE sn_control = 'FULL')
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type] 
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status]
									,[receive_date]
									,[mfg_date]
									,[reason_code]
									,[user_def2] 
									,[device]
									,[create_date]
									,[create_by])
								SELECT NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType 
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,inv.wh_id
									,inv.wh_id	
									,inv.location
									,inv.location
									,inv.owner_code
									,inv.owner_code
									,inv.item_number
									,invSN.quantity
									,inv.uom
									,0
									,inv.uom
									,inv.lot_number
									,inv.lot_number
									,(CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,inv.expiry_date) END)
									,(CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,inv.expiry_date) END)
									,SerialNumber
									,inv.attribute1
									,inv.attribute1
									,inv.attribute2
									,inv.attribute2
									,inv.attribute3
									,inv.attribute3
									,inv.attribute4
									,inv.attribute4
									,inv.attribute5
									,inv.attribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,inv.lpn
									,inv.lpn
									,inv.inv_status
									,inv.inv_status 
									,inv.receive_date
									,inv.mfg_date
									,@v_vchReasonCode
									,'To MFG: ' + CONVERT(VARCHAR(10),@in_dtToMfgDate )
									,@in_vchDeviceID
									,GETDATE()
									,@in_vchUserID
								FROM #tInventory inv
								INNER JOIN @tInventorySerial invSN ON inv.inventory_id = invSN.InventoryID
								ORDER BY invSN.RowNumber
						END
					ELSE
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
								([record_id]
								,[host_record_id]
								,[processing_code]
								,[processing_status]
								,[app_id]
								,[app_name]
								,[tran_type]
								,[sub_tran_type] 
								,[start_tran_datetime]
								,[end_tran_datetime]
								,[warehouse]
								,[to_warehouse]
								,[location]
								,[to_location]
								,[owner]
								,[to_owner]
								,[item_number]
								,[quantity]
								,[quantity_uom]
								,[after_quantity]
								,[after_quantity_uom]
								,[lot_number]
								,[after_lot_number]
								,[expiry_date]
								,[after_expiry_date]
								,[serial_number]
								,[attribute1]
								,[after_attribute1]
								,[attribute2]
								,[after_attribute2]
								,[attribute3]
								,[after_attribute3]
								,[attribute4]
								,[after_attribute4]
								,[attribute5]
								,[after_attribute5]
								,[user_id]
								,[reference_number]
								,[lpn]
								,[after_lpn]
								,[status]
								,[after_status]
								,[receive_date]
								,[mfg_date]
								,[reason_code]
								,[user_def2] 
								,[device]
								,[create_date]
								,[create_by])
							SELECT NEWID()			
								,@v_vchHostRecordID
								,'ADD'  
								,'PENDING'
								,@in_vchApplicationID
								,@v_vchApplicationName
								,@v_vchTranType
								,@v_vchSubTranType 
								,@v_dtStartTranDate
								,@v_dtProcessDateTime
								,wh_id
								,wh_id	
								,location
								,location
								,owner_code
								,owner_code
								,item_number
								,quantity
								,uom
								,0
								,uom
								,lot_number
								,lot_number
								,(CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,expiry_date) END)
								,(CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,expiry_date) END)
								,NULL
								,attribute1
								,attribute1
								,attribute2
								,attribute2
								,attribute3
								,attribute3
								,attribute4
								,attribute4
								,attribute5
								,attribute5
								,@in_vchUserID
								,@in_vchReferenceNumber 
								,lpn
								,lpn
								,inv_status
								,inv_status  
								,receive_date
								,mfg_date
								,@v_vchReasonCode
								,'To MFG: ' + CONVERT(VARCHAR(10),@in_dtToMfgDate )
								,@in_vchDeviceID
								,GETDATE()
								,@in_vchUserID
							FROM #tInventory
						END
				END 
			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE(); 
			IF EXISTS (SELECT inventory_id FROM #tInventory WHERE sn_control = 'FULL')
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
					   ([tran_id]
					   ,[app_id]
					   ,[app_name]
					   ,[tran_type]
					   ,[sub_tran_type]
					   ,[description]
					   ,[start_tran_datetime]
					   ,[end_tran_datetime]
					   ,[warehouse]
					   ,[to_warehouse]
					   ,[location]
					   ,[to_location]
					   ,[owner]
					   ,[to_owner]
					   ,[item_number]
					   ,[quantity]
					   ,[quantity_uom]
					   ,[after_quantity]
					   ,[after_quantity_uom]
					   ,[lot_number]
					   ,[after_lot_number]
					   ,[expiry_date]
					   ,[after_expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[after_attribute1]
					   ,[attribute2]
					   ,[after_attribute2]
					   ,[attribute3]
					   ,[after_attribute3]
					   ,[attribute4]
					   ,[after_attribute4]
					   ,[attribute5]
					   ,[after_attribute5]
					   ,[user_id]
					   ,[reference_number]
					   ,[control_number]
					   ,[lpn]
					   ,[after_lpn]
					   ,[parent_lpn]
					   ,[after_parent_lpn]
					   ,[status]
					   ,[after_status]
					   ,[reason_code]
					   ,[udf_1]
					   ,[udf_2]
					   ,[receive_date]
					   ,[mfg_date]
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 SELECT NEWID()
					   ,@in_vchApplicationID
					   ,@v_vchApplicationName
					   ,@v_vchTranType
					   ,@v_vchSubTranType
					   ,'Change Mfg Date'
					   ,@v_dtStartTranDate
					   ,@v_dtProcessDateTime
					   ,inv.wh_id
					   ,inv.wh_id
					   ,inv.location
					   ,inv.location
					   ,inv.owner_code
					   ,inv.owner_code
					   ,inv.item_number
					   ,invSN.quantity
					   ,inv.uom
					   ,0
					   ,inv.uom
					   ,inv.lot_number
					   ,inv.lot_number
					   ,(CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,inv.expiry_date) END)
					   ,(CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,inv.expiry_date) END)
					   ,invSN.SerialNumber
					   ,inv.attribute1
					   ,inv.attribute1
					   ,inv.attribute2
					   ,inv.attribute2
					   ,inv.attribute3
					   ,inv.attribute3
					   ,inv.attribute4
					   ,inv.attribute4
					   ,inv.attribute5
					   ,inv.attribute5
					   ,@in_vchUserID
					   ,@in_vchReferenceNumber
					   ,@v_vchHostRecordID
					   ,inv.lpn
					   ,inv.lpn
					   ,inv.parent_lpn
					   ,inv.parent_lpn
					   ,inv.inv_status
					   ,inv.inv_status 
					   ,@v_vchReasonCode
					   ,@in_vchRemark  
					   ,'To MFG: ' + CONVERT(VARCHAR(10),@in_dtToMfgDate) 
					   ,inv.receive_date
					   ,inv.mfg_date 
					   ,@in_vchDeviceID
					   ,GETDATE()
					   ,@in_vchUserID
					FROM #tInventory inv
					INNER JOIN @tInventorySerial invSN ON inv.inventory_id = invSN.InventoryID
					ORDER BY invSN.RowNumber
				END
			ELSE 
				BEGIN
					print 'log'
					INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status]
						,[reason_code]
						,[udf_1]
						,[udf_2]
						,[receive_date]
						,[mfg_date]
						,[device]
						,[create_date]
						,[create_by])
					SELECT NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType
						,'Change MFG Date'
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,wh_id
						,wh_id
						,location
						,location
						,owner_code
						,owner_code
						,item_number
						,quantity
						,uom
						,0
						,uom
						,lot_number
						,lot_number
						,(CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,expiry_date) END)
						,(CASE WHEN ISNULL(expiry_date,'') = '' THEN NULL ELSE CONVERT(DATE,expiry_date) END)
						,NULL
						,attribute1
						,attribute1
						,attribute2
						,attribute2
						,attribute3
						,attribute3
						,attribute4
						,attribute4
						,attribute5
						,attribute5
						,@in_vchUserID
						,@in_vchReferenceNumber
						,@v_vchHostRecordID
						,lpn
						,lpn
						,parent_lpn
						,parent_lpn
						,inv_status
						,inv_status
						,@v_vchReasonCode
						,@in_vchRemark
						,'To MFG: ' + CONVERT(VARCHAR(10),@in_dtToMfgDate)
						,receive_date
						,mfg_date 
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID
					FROM #tInventory
				END 
		END

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Item Number ' + @in_vchItemNumber
		SET @v_vchProcessData2 = 'Lot: ['+ ISNULL(@in_vchLotNumber,'') + ']'
		SET @v_vchProcessData3 = 'Exp: ['+ ISNULL(@in_vchExpiryDate,'') + ']' 
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWhID,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'Item Number ' + @in_vchItemNumber
	SET @v_vchProcessData2 = 'Lot: ['+ ISNULL(@in_vchLotNumber,'') + ']'
	SET @v_vchProcessData3 = 'Exp: ['+ ISNULL(@in_vchExpiryDate,'') + ']' 
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWhID,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
		
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_serial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_serial]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchOldSerialNumber	NVARCHAR(100) = NULL,
	@in_vchNewSerialNumber	NVARCHAR(100) = NULL,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_serial]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5)
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_SERIAL' 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''
	
	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchSNControl			VARCHAR(5)



BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
	SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
	SELECT @v_vchReasonCode = reason_code 
		--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
	FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'

	--GET From Location
	SELECT @v_vchInventoryID	 = inventory_id
		,@v_vchAttributeGroupID	 = attribute_group_id
		,@v_vchWhMasterID	     = wh_master_id
		,@v_vchWarehouse	     = wh_id
		,@v_vchOwnerID			 = owner_id
		,@v_vchOwner			 = owner_code
		,@v_vchLocationID		 = location_id
		,@v_vchLocation			 = location
		,@v_vchERPSourceLocation = erp_location
		,@v_vchParentLPN		 = parent_lpn
		,@v_vchLPN				 = lpn
		,@v_vchWhItemMasterID	 = wh_item_master_id
		,@v_vchItemMasterID		 = item_master_id
		,@v_vchItemNumber		 = item_number
		,@v_vchInvQuantity		 = quantity
		,@v_vchInvQtyAllocate	 = quantity_allocated
		,@v_vchBaseItemUomID	 = item_uom_id
		,@v_vchBaseUomPrompt	 = uom_prompt
		,@v_vchInvStatusID		 = inventory_status_id
		,@v_vchInvStatus		 = inv_status
		,@v_vchLotNumber		 = lot_number
		,@v_vchExpiryDate		 = expiry_date
		,@v_vchAttribute1		 = attribute1
		,@v_vchAttribute2		 = attribute2
		,@v_vchAttribute3		 = attribute3
		,@v_vchAttribute4		 = attribute4
		,@v_vchAttribute5		 = attribute5
		,@v_dtReceiveDate		 = receive_date
		,@v_dtMfgDate			 = mfg_date
		,@v_vchSNControl		 = sn_control 
	FROM v_wms_inventory_data_by_serial_item
	WHERE inventory_id = @in_vchInventoryID
	AND serial_number = @in_vchOldSerialNumber

	IF @v_vchInventoryID IS NULL
		BEGIN
			SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END

	IF @v_vchSNControl = 'NONE'
		BEGIN
			SET @out_ErrorCode = 'ITEM_NOT_CONTROL_SERIAL';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END

	--Check SN Duplicate
	IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
				WHERE inventory_id = @in_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND attribute_value = @in_vchNewSerialNumber
				AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
		BEGIN
			SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchNewSerialNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END
	
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1

	IF (@v_vchSNControl = 'FULL')
		BEGIN
			UPDATE t_wms_inventory_attribute SET attribute_value = @in_vchNewSerialNumber
			WHERE inventory_id = @in_vchInventoryID
			AND attribute_group_id = @v_vchAttributeGroupID
			AND attribute_value = @in_vchOldSerialNumber
			AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES')
		END

	--Insert Remark
	IF ISNULL(@in_vchRemark,'') <> ''
		BEGIN 
			DELETE FROM t_wms_inventory_remark  WHERE inventory_id = @in_vchInventoryID AND serial_number = @in_vchOldSerialNumber

			UPDATE t_wms_inventory_remark SET
				 serial_number = @in_vchNewSerialNumber
				,reason_id = @in_vchReasonID
				,remark = @in_vchRemark
				,update_by = @in_vchUserID
				,update_date = GETDATE()
			WHERE inventory_id = @in_vchInventoryID
			AND serial_number = @in_vchOldSerialNumber
		END
				
	--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
	DELETE t_wms_inventory_remark
	FROM t_wms_inventory_remark invRemark
	LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
	WHERE inv.inventory_id IS NULL

	INSERT INTO [dbo].[t_com_tran_log]
			([tran_id]
			,[app_id]
			,[app_name]
			,[tran_type]
			,[sub_tran_type]
			,[description]
			,[start_tran_datetime]
			,[end_tran_datetime]
			,[warehouse]
			,[to_warehouse]
			,[location]
			,[to_location]
			,[owner]
			,[to_owner]
			,[item_number]
			,[quantity]
			,[quantity_uom]
			,[after_quantity]
			,[after_quantity_uom]
			,[lot_number]
			,[after_lot_number]
			,[expiry_date]
			,[after_expiry_date]
			,[serial_number]
			,[attribute1]
			,[after_attribute1]
			,[attribute2]
			,[after_attribute2]
			,[attribute3]
			,[after_attribute3]
			,[attribute4]
			,[after_attribute4]
			,[attribute5]
			,[after_attribute5]
			,[user_id]
			,[reference_number]
			,[control_number]
			,[lpn]
			,[after_lpn]
			,[parent_lpn]
			,[after_parent_lpn]
			,[status]
			,[after_status] 
			,[control_value_1]
			,[control_value_2]
			,[reason_code]
			,[udf_1]
			,[udf_2]
			,[receive_date]
			,[mfg_date]
			,[input_quantity]
			,[input_uom]
			,[device]
			,[create_date]
			,[create_by])
		VALUES
			(NEWID()
			,@in_vchApplicationID
			,@v_vchApplicationName
			,@v_vchTranType
			,@v_vchSubTranType
			,'Change Serial Number'
			,@v_dtStartTranDate
			,@v_dtProcessDateTime
			,@v_vchWarehouse
			,@v_vchWarehouse
			,@v_vchLocation
			,@v_vchLocation
			,@v_vchOwner
			,@v_vchOwner
			,@v_vchItemNumber
			,1
			,@v_vchBaseUomPrompt
			,1
			,@v_vchBaseUomPrompt
			,@v_vchLotNumber
			,@v_vchLotNumber
			,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
			,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
			,@in_vchOldSerialNumber
			,@v_vchAttribute1
			,@v_vchAttribute1
			,@v_vchAttribute2
			,@v_vchAttribute2
			,@v_vchAttribute3
			,@v_vchAttribute3
			,@v_vchAttribute4
			,@v_vchAttribute4
			,@v_vchAttribute5
			,@v_vchAttribute5
			,@in_vchUserID
			,@in_vchReferenceNumber
			,@v_vchHostRecordID
			,@v_vchLPN
			,@v_vchLPN
			,@v_vchParentLPN
			,@v_vchParentLPN
			,@v_vchInvStatus
			,@v_vchInvStatus 
			,@v_vchERPSourceLocation
			,@v_vchERPSourceLocation
			,@v_vchReasonCode
			,@in_vchRemark
			,'New SN :' + @in_vchNewSerialNumber
			,@v_dtReceiveDate
			,@v_dtMfgDate
			,1
			,@v_vchBaseUomPrompt
			,@in_vchDeviceID
			,GETDATE()
			,@in_vchUserID) 

	COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
		SET @v_vchProcessData4 = 'Serial: ['+ ISNULL(@in_vchOldSerialNumber,'') + '] To Status: [' + ISNULL(@in_vchNewSerialNumber,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
	SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
	SET @v_vchProcessData4 = 'Serial: ['+ ISNULL(@in_vchOldSerialNumber,'') + '] To Status: [' + ISNULL(@in_vchNewSerialNumber,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
		
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_status]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_status] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchToInvStatusID	UNIQUEIDENTIFIER,
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_status]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_STATUS'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchLPNControl		VARCHAR(5)
	DECLARE @v_vchLocType			NVARCHAR(20)
 
	DECLARE @v_vchFromInvStatusID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchFromInvStatus		NVARCHAR(50) = NULL
	DECLARE @v_vchToInvStatus		NVARCHAR(50) = NULL
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchReasonCode = reason_code
			--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchWhMasterID	     = wh_master_id
			,@v_vchWarehouse	     = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchLocationID		 = location_id
			,@v_vchLocation			 = location
			,@v_vchLocType			 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchLPNControl		 = lpn_controlled
			,@v_vchParentLPN		 = parent_lpn
			,@v_vchLPN				 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchBaseUomPrompt	 = uom_prompt
			,@v_vchFromInvStatusID	 = inventory_status_id
			,@v_vchFromInvStatus	 = inv_status
			,@v_vchLotNumber		 = lot_number
			,@v_vchExpiryDate		 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtMfgDate			 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_item 
		WHERE inventory_id = @in_vchInventoryID

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		--ถ้า Item ที่ต้องการ Move Control Serial จะต้อง Move เต็มจำนวนเท่านั้น
		--IF @v_vchSNControl = 'FULL' AND ISNULL(@in_fltQty,0) > 0 
		--	BEGIN
		--		SET @out_ErrorCode = 'CONTROL_SN_CANNOT_MOVE_THIS_FUNCTION';
		--		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
		--		GOTO WRITE_PROC
		--	END

		--For Insert Serial to temp
		IF @v_vchSNControl = 'FULL'
			BEGIN
				SET @in_fltQty = 0
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE inventory_id = @in_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				ORDER BY serial_number
			END

		--Qty Input = 0 or Null >> Get Qty from inventory
		IF ISNULL(@in_fltQty,0) = 0
			BEGIN
				--Move all qty
				SET @v_fltQtyUpdate = @v_vchInvQuantity
			END
		ELSE	
			BEGIN
				SET @v_fltQtyUpdate = @in_fltQty
			END
			 
		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END
			 
		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
		DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
	
		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		-- Check to status
		SELECT @v_vchToInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchToInvStatusID AND is_active = 'YES'
		IF(@v_vchToInvStatus IS NULL)
			BEGIN 
				SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToInvStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		-- check location is mix Status?
		DECLARE @v_vchMixStatus VARCHAR(5) = ''
		SELECT @v_vchMixStatus = mix_status FROM t_wms_location WHERE location_id = @v_vchLocationID
		IF EXISTS(SELECT inventory_status_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchLocationID AND inventory_status_id <> @in_vchToInvStatusID) AND @v_vchMixStatus = 'NO'
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_MIX_STATUS';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @in_vchToInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
								, @in_vchLocationID			= @v_vchLocationID
								, @in_vchStatusID			= @in_vchToInvStatusID
								, @in_vchPalentLPN			= @v_vchParentLPN
								, @in_vchLPN				= @v_vchLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMFGDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber 
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						SELECT NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, SerialNumber
							, 1
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID
						FROM @tInventorySerial
						ORDER BY SerialNumber
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @v_vchLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @v_vchExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END 

		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number IN (SELECT SerialNumber FROM @tInventorySerial) 

						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,@v_vchDestInventoryID
								   ,SerialNumber
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM @tInventorySerial
							ORDER BY SerialNumber
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		IF @v_vchLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchLocationID
			END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE();
					IF @v_vchSNControl = 'NONE'
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type] 
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status] 
									,[control_value_1]
									,[control_value_2]
									,[receive_date]
									,[mfg_date]
									,[reason_code] 
									,[device]
									,[create_date]
									,[create_by])
								VALUES
									(NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType 
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,@v_vchWarehouse
									,@v_vchWarehouse	
									,@v_vchLocation
									,@v_vchLocation
									,@v_vchOwner
									,@v_vchOwner
									,@v_vchItemNumber
									,@v_fltQtyUpdate
									,@v_vchBaseUomPrompt
									,@v_fltAfterQty
									,@v_vchBaseUomPrompt
									,@v_vchLotNumber
									,@v_vchLotNumber
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
									,NULL
									,@v_vchAttribute1
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute4
									,@v_vchAttribute5
									,@v_vchAttribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,@v_vchLPN
									,@v_vchLPN
									,@v_vchFromInvStatus
									,@v_vchToInvStatus 
									,@v_vchERPSourceLocation
									,@v_vchERPDestLocation
									,@v_dtReceiveDate
									,@v_dtMfgDate
									,@v_vchReasonCode 
									,@in_vchDeviceID
									,GETDATE()
									,@in_vchUserID)
						END
					ELSE
						BEGIN
							INSERT INTO [dbo].[t_host_wms_trans_export]
								([record_id]
								,[host_record_id]
								,[processing_code]
								,[processing_status]
								,[app_id]
								,[app_name]
								,[tran_type]
								,[sub_tran_type] 
								,[start_tran_datetime]
								,[end_tran_datetime]
								,[warehouse]
								,[to_warehouse]
								,[location]
								,[to_location]
								,[owner]
								,[to_owner]
								,[item_number]
								,[quantity]
								,[quantity_uom]
								,[after_quantity]
								,[after_quantity_uom]
								,[lot_number]
								,[after_lot_number]
								,[expiry_date]
								,[after_expiry_date]
								,[serial_number]
								,[attribute1]
								,[after_attribute1]
								,[attribute2]
								,[after_attribute2]
								,[attribute3]
								,[after_attribute3]
								,[attribute4]
								,[after_attribute4]
								,[attribute5]
								,[after_attribute5]
								,[user_id]
								,[reference_number]
								,[lpn]
								,[after_lpn]
								,[status]
								,[after_status] 
								,[control_value_1]
								,[control_value_2]
								,[receive_date]
								,[mfg_date]
								,[reason_code] 
								,[device]
								,[create_date]
								,[create_by])
							SELECT NEWID()
								,@v_vchHostRecordID
								,'ADD'  
								,'PENDING'
								,@in_vchApplicationID
								,@v_vchApplicationName
								,@v_vchTranType
								,@v_vchSubTranType 
								,@v_dtStartTranDate
								,@v_dtProcessDateTime
								,@v_vchWarehouse
								,@v_vchWarehouse	
								,@v_vchLocation
								,@v_vchLocation
								,@v_vchOwner
								,@v_vchOwner
								,@v_vchItemNumber
								,@v_fltQtyUpdate
								,@v_vchBaseUomPrompt
								,@v_vchInvQuantity - RowNumber
								,@v_vchBaseUomPrompt
								,@v_vchLotNumber
								,@v_vchLotNumber
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
								,SerialNumber
								,@v_vchAttribute1
								,@v_vchAttribute1
								,@v_vchAttribute2
								,@v_vchAttribute2
								,@v_vchAttribute3
								,@v_vchAttribute3
								,@v_vchAttribute4
								,@v_vchAttribute4
								,@v_vchAttribute5
								,@v_vchAttribute5
								,@in_vchUserID
								,@in_vchReferenceNumber 
								,@v_vchLPN
								,@v_vchLPN
								,@v_vchFromInvStatus
								,@v_vchToInvStatus 
								,@v_vchERPSourceLocation
								,@v_vchERPDestLocation
								,@v_dtReceiveDate
								,@v_dtMfgDate
								,@v_vchReasonCode 
								,@in_vchDeviceID
								,GETDATE()
								,@in_vchUserID
							FROM @tInventorySerial 
							ORDER BY RowNumber
						END
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE(); 
			IF @v_vchSNControl = 'NONE'
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[reason_code]
						,[udf_1]
						,[receive_date]
						,[mfg_date]
						,[input_quantity]
						,[input_uom]
						,[device]
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType
						,'Change Inventory Status'
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,@v_vchWarehouse
						,@v_vchWarehouse
						,@v_vchLocation
						,@v_vchLocation
						,@v_vchOwner
						,@v_vchOwner
						,@v_vchItemNumber
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@v_fltAfterQty
						,@v_vchBaseUomPrompt
						,@v_vchLotNumber
						,@v_vchLotNumber
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						,NULL
						,@v_vchAttribute1
						,@v_vchAttribute1
						,@v_vchAttribute2
						,@v_vchAttribute2
						,@v_vchAttribute3
						,@v_vchAttribute3
						,@v_vchAttribute4
						,@v_vchAttribute4
						,@v_vchAttribute5
						,@v_vchAttribute5
						,@in_vchUserID
						,@in_vchReferenceNumber
						,@v_vchHostRecordID
						,@v_vchLPN
						,@v_vchLPN
						,@v_vchParentLPN
						,@v_vchParentLPN
						,@v_vchFromInvStatus
						,@v_vchToInvStatus 
						,@v_vchERPSourceLocation
						,@v_vchERPDestLocation
						,@v_vchReasonCode
						,@in_vchRemark
						,@v_dtReceiveDate
						,@v_dtMfgDate
						,@v_fltQtyUpdate
						,@v_vchBaseUomPrompt
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID) 
				END
			ELSE
				BEGIN
					INSERT INTO [dbo].[t_com_tran_log]
					   ([tran_id]
					   ,[app_id]
					   ,[app_name]
					   ,[tran_type]
					   ,[sub_tran_type]
					   ,[description]
					   ,[start_tran_datetime]
					   ,[end_tran_datetime]
					   ,[warehouse]
					   ,[to_warehouse]
					   ,[location]
					   ,[to_location]
					   ,[owner]
					   ,[to_owner]
					   ,[item_number]
					   ,[quantity]
					   ,[quantity_uom]
					   ,[after_quantity]
					   ,[after_quantity_uom]
					   ,[lot_number]
					   ,[after_lot_number]
					   ,[expiry_date]
					   ,[after_expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[after_attribute1]
					   ,[attribute2]
					   ,[after_attribute2]
					   ,[attribute3]
					   ,[after_attribute3]
					   ,[attribute4]
					   ,[after_attribute4]
					   ,[attribute5]
					   ,[after_attribute5]
					   ,[user_id]
					   ,[reference_number]
					   ,[control_number]
					   ,[lpn]
					   ,[after_lpn]
					   ,[parent_lpn]
					   ,[after_parent_lpn]
					   ,[status]
					   ,[after_status] 
					   ,[control_value_1]
					   ,[control_value_2]
					   ,[reason_code] 
					   ,[udf_1]
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom] 
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 SELECT NEWID()
					   ,@in_vchApplicationID
					   ,@v_vchApplicationName
					   ,@v_vchTranType
					   ,@v_vchSubTranType
					   ,'Change Inventory Status'
					   ,@v_dtStartTranDate
					   ,@v_dtProcessDateTime
					   ,@v_vchWarehouse
					   ,@v_vchWarehouse
					   ,@v_vchLocation
					   ,@v_vchLocation
					   ,@v_vchOwner
					   ,@v_vchOwner
					   ,@v_vchItemNumber
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@v_vchInvQuantity - RowNumber
					   ,@v_vchBaseUomPrompt
					   ,@v_vchLotNumber
					   ,@v_vchLotNumber
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
					   ,SerialNumber
					   ,@v_vchAttribute1
					   ,@v_vchAttribute1
					   ,@v_vchAttribute2
					   ,@v_vchAttribute2
					   ,@v_vchAttribute3
					   ,@v_vchAttribute3
					   ,@v_vchAttribute4
					   ,@v_vchAttribute4
					   ,@v_vchAttribute5
					   ,@v_vchAttribute5
					   ,@in_vchUserID
					   ,@in_vchReferenceNumber
					   ,@v_vchHostRecordID
					   ,@v_vchLPN
					   ,@v_vchLPN
					   ,@v_vchParentLPN
					   ,@v_vchParentLPN
					   ,@v_vchFromInvStatus
					   ,@v_vchToInvStatus 
					   ,@v_vchERPSourceLocation
					   ,@v_vchERPDestLocation
					   ,@v_vchReasonCode
					   ,@in_vchRemark
					   ,@v_dtReceiveDate
					   ,@v_dtMfgDate
					   ,@v_fltQtyUpdate
					   ,@v_vchBaseUomPrompt
					   ,@in_vchDeviceID
					   ,GETDATE()
					   ,@in_vchUserID
					FROM @tInventorySerial
					ORDER BY RowNumber
				END
		END

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'CHANGE_STATUS'
									   ,@in_vchWhMasterID	= @v_vchWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwner
									   ,@in_vchLocationID	= @v_vchLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchFromInvStatusID
									   ,@in_vchToWhMasterID	= @v_vchWhMasterID
									   ,@in_vchToLocationID	= @v_vchLocationID
									   ,@in_vchToInvStatusID = @in_vchToInvStatusID
									   ,@in_fltQuantity		= @v_fltQtyUpdate
									   ,@in_vchUserID		= @in_vchUserID
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
		SET @v_vchProcessData4 = 'Status: ['+ ISNULL(@v_vchFromInvStatus,'') + '] To Status: [' + ISNULL(@v_vchToInvStatus,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
		SET @v_vchProcessData4 = 'Status: ['+ ISNULL(@v_vchFromInvStatus,'') + '] To Status: [' + ISNULL(@v_vchToInvStatus,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
		
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_status_by_lot]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_status_by_lot] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchToInvStatusID	UNIQUEIDENTIFIER,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_status_by_lot]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_STATUS'
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50) = NULL
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWarehouse			NVARCHAR(25) = NULL
	DECLARE @v_vchOwner				NVARCHAR(40) = NULL
	DECLARE @v_vchToInvStatus		NVARCHAR(50) = NULL
 
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT TOP 1 @v_vchReasonCode = reason_code 
			--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID  AND is_active = 'YES'
		SELECT TOP 1 @v_vchOwner = owner_code FROM t_wms_owner where owner_id = @in_vchOwnerID  AND is_active = 'YES'
		 
		--Check Inventory
		IF NOT EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lot_number = @in_vchLotNumber)
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--Check Allocate Qty
		IF EXISTS (SELECT inventory_id FROM v_wms_inventory_data_by_id WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lot_number = @in_vchLotNumber AND ISNULL(quantity_allocated,0) > 0)
			BEGIN
				SET @out_ErrorCode = 'INV_HAVE_ALLOCATE_CANNOT_CHANGE_STATUS';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--Check Status
		SELECT TOP 1 @v_vchToInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchToInvStatusID AND is_active = 'YES'
		IF(@v_vchToInvStatus IS NULL)
			BEGIN 
				SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToInvStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		-- check location is mix Status?
		IF (SELECT COUNT(DISTINCT inventory_status_id)
			FROM dbo.t_wms_inventory AS inv
			INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
			LEFT JOIN (SELECT inventory_id
							,attribute_group_id
							,attribute_value AS lot_number
						FROM dbo.t_wms_inventory_attribute
						WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
						) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
			WHERE inv.wh_master_id = @in_vchWhMasterID 
			AND inv.owner_id = @in_vchOwnerID 
			AND invLot.lot_number = @in_vchLotNumber
			AND loc.mix_status = 'NO') > 1
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_MIX_STATUS';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
			 
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		SELECT inventory_id
			  , attribute_group_id
			  , wh_master_id
			  , wh_id
			  , owner_id
			  , owner_code
			  , location_id
			  , location
			  , loc_type
			  , erp_location
			  , lpn_controlled
			  , parent_lpn
			  , lpn
			  , wh_item_master_id
			  , item_master_id
			  , item_number
			  , quantity
			  , quantity_allocated
			  , item_uom_id
			  , uom_prompt
			  , inventory_status_id
			  , inv_status
			  , lot_number
			  , expiry_date
			  , serial_number
			  , attribute1
			  , attribute2
			  , attribute3
			  , attribute4
			  , attribute5
			  , receive_date
			  , mfg_date
			  , ROW_NUMBER() OVER(ORDER BY serial_number, inventory_id) AS RowNumber
		INTO #tInventory
		FROM v_wms_inventory_data_by_serial_item
		WHERE wh_master_id = @in_vchWhMasterID 
		AND owner_id = @in_vchOwnerID 
		AND lot_number = @in_vchLotNumber
	 
		UPDATE t_wms_inventory SET inventory_status_id = @in_vchToInvStatusID
		FROM t_wms_inventory inv
		INNER JOIN #tInventory ON inv.inventory_id = #tInventory.inventory_id
		
		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				--Insert Remark for Serial 
				IF EXISTS (SELECT inventory_id FROM #tInventory WHERE ISNULL(serial_number,'') <> '')
					BEGIN
						DELETE invRemark 
						FROM t_wms_inventory_remark invRemark
						INNER JOIN #tInventory on invRemark.inventory_id = #tInventory.inventory_id
						WHERE ISNULL(#tInventory.serial_number,'') <> ''
						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,inventory_id
								   ,serial_number
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM #tInventory
							WHERE ISNULL(serial_number,'') <> ''
							ORDER BY serial_number
					END
			
				--Update Remark for Other 
				UPDATE t_wms_inventory_remark SET 
					 reason_id = @in_vchReasonID
					,remark = @in_vchRemark
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				FROM t_wms_inventory_remark invRemark 
				INNER JOIN #tInventory inv on invRemark.inventory_id = inv.inventory_id
				WHERE ISNULL(inv.serial_number,'') = ''

				--Insert Remark for Other 
				INSERT INTO [dbo].[t_wms_inventory_remark]
					([inventory_remark_id]
					,[inventory_id]
					,[serial_number]
					,[reason_id]
					,[remark]
					,[create_by]
					,[create_date])
				SELECT NEWID()
					,inventory_id
					,NULL
					,@in_vchReasonID
					,@in_vchRemark
					,@in_vchUserID
					,GETDATE()
				FROM #tInventory
				WHERE inventory_id NOT IN (SELECT inventory_id FROM t_wms_inventory_remark)
				AND ISNULL(serial_number,'') = ''
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] IN (SELECT location_id FROM #tInventory)
				
		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1  host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE(); 
					INSERT INTO [dbo].[t_host_wms_trans_export]
						([record_id]
						,[host_record_id]
						,[processing_code]
						,[processing_status]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type] 
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[lpn]
						,[after_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[receive_date]
						,[mfg_date]
						,[reason_code] 
						,[device]
						,[create_date]
						,[create_by])
					SELECT NEWID()
						,@v_vchHostRecordID
						,'ADD'  
						,'PENDING'
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType 
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,wh_id
						,wh_id	
						,location
						,location
						,owner_code
						,owner_code
						,item_number
						,quantity
						,uom_prompt
						,0
						,uom_prompt
						,lot_number
						,lot_number
						,expiry_date
						,expiry_date
						,serial_number
						,attribute1
						,attribute1
						,attribute2
						,attribute2
						,attribute3
						,attribute3
						,attribute4
						,attribute4
						,attribute5
						,attribute5
						,@in_vchUserID
						,@in_vchReferenceNumber 
						,lpn
						,lpn
						,inv_status
						,@v_vchToInvStatus 
						,erp_location
						,erp_location
						,receive_date
						,mfg_date
						,@v_vchReasonCode 
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID
					FROM #tInventory 
					ORDER BY RowNumber
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE();
			INSERT INTO [dbo].[t_com_tran_log]
				([tran_id]
				,[app_id]
				,[app_name]
				,[tran_type]
				,[sub_tran_type]
				,[description]
				,[start_tran_datetime]
				,[end_tran_datetime]
				,[warehouse]
				,[to_warehouse]
				,[location]
				,[to_location]
				,[owner]
				,[to_owner]
				,[item_number]
				,[quantity]
				,[quantity_uom]
				,[after_quantity]
				,[after_quantity_uom]
				,[lot_number]
				,[after_lot_number]
				,[expiry_date]
				,[after_expiry_date]
				,[serial_number]
				,[attribute1]
				,[after_attribute1]
				,[attribute2]
				,[after_attribute2]
				,[attribute3]
				,[after_attribute3]
				,[attribute4]
				,[after_attribute4]
				,[attribute5]
				,[after_attribute5]
				,[user_id]
				,[reference_number]
				,[control_number]
				,[lpn]
				,[after_lpn]
				,[parent_lpn]
				,[after_parent_lpn]
				,[status]
				,[after_status] 
				,[control_value_1]
				,[control_value_2]
				,[reason_code]
				,[udf_1]
				,[receive_date]
				,[mfg_date]
				,[input_quantity]
				,[input_uom] 
				,[device]
				,[create_date]
				,[create_by])
			SELECT NEWID()
				,@in_vchApplicationID
				,@v_vchApplicationName
				,@v_vchTranType
				,@v_vchSubTranType
				,'Change Inventory Status'
				,@v_dtStartTranDate
				,@v_dtProcessDateTime
				,wh_id
				,wh_id
				,location
				,location
				,owner_code
				,owner_code
				,item_number
				,quantity
				,uom_prompt
				,0
				,uom_prompt
				,lot_number
				,lot_number
				,expiry_date
				,expiry_date
				,serial_number
				,attribute1
				,attribute1
				,attribute2
				,attribute2
				,attribute3
				,attribute3
				,attribute4
				,attribute4
				,attribute5
				,attribute5
				,@in_vchUserID
				,@in_vchReferenceNumber
				,@v_vchHostRecordID
				,lpn
				,lpn
				,parent_lpn
				,parent_lpn
				,inv_status
				,@v_vchToInvStatus 
				,erp_location
				,erp_location
				,@v_vchReasonCode
				,@in_vchRemark
				,receive_date
				,mfg_date
				,quantity
				,uom_prompt
				,@in_vchDeviceID
				,GETDATE()
				,@in_vchUserID
			FROM #tInventory
			ORDER BY RowNumber 
		END

		-----------------------------------------------------------------------------------
		--Insert Dashboard 
		BEGIN
			--Change Status : from is out, to is in 
			INSERT INTO [dbo].[t_wms_dashboard_trans_out]
						([trans_id]
						,[trans_date]
						,[trans_type]
						,[wh_master_id]
						,[wh_id]
						,[owner_id]
						,[owner_code]
						,[location_id]
						,[location]
						,[item_master_id]
						,[item_number]
						,[item_description]
						,[category_id]
						,[item_category]
						,[quantity]
						,[inventory_status_id]
						,[inv_status]
						,[create_by]
						,[create_date])
			SELECT NEWID()
				,GETDATE()
				,'CHANGE_STATUS'
				,wh_master_id
				,wh_id
				,inv.owner_id
				,inv.owner_code
				,inv.location_id
				,inv.location
				,inv.item_master_id
				,inv.item_number
				,item.description
				,cate.category_id
				,cate.item_category
				,SUM(quantity)
				,inv.inventory_status_id
				,inv.inv_status
				,@in_vchUserID
				,GETDATE()
			FROM #tInventory inv 
			INNER JOIN t_wms_item item ON inv.item_master_id = item.item_master_id
			INNER JOIN t_wms_category cate ON cate.category_id = item.category_id
			GROUP BY wh_master_id,wh_id,inv.owner_id,inv.owner_code,inv.location_id,inv.location,inv.item_master_id,inv.item_number,item.description,cate.category_id,cate.item_category,inv.inventory_status_id,inv.inv_status

			INSERT INTO [dbo].[t_wms_dashboard_trans_in]
						([trans_id]
						,[trans_date]
						,[trans_type]
						,[wh_master_id]
						,[wh_id]
						,[owner_id]
						,[owner_code]
						,[location_id]
						,[location]
						,[item_master_id]
						,[item_number]
						,[item_description]
						,[category_id]
						,[item_category]
						,[quantity]
						,[inventory_status_id]
						,[inv_status]
						,[create_by]
						,[create_date])
			SELECT NEWID()
				,GETDATE()
				,'CHANGE_STATUS'
				,wh_master_id
				,wh_id
				,inv.owner_id
				,inv.owner_code
				,inv.location_id
				,inv.location
				,inv.item_master_id
				,inv.item_number
				,item.description
				,cate.category_id
				,cate.item_category
				,SUM(quantity)
				,@in_vchToInvStatusID
				,@v_vchToInvStatus
				,@in_vchUserID
				,GETDATE()
			FROM #tInventory inv 
			INNER JOIN t_wms_item item ON inv.item_master_id = item.item_master_id
			INNER JOIN t_wms_category cate ON cate.category_id = item.category_id
			GROUP BY wh_master_id,wh_id,inv.owner_id,inv.owner_code,inv.location_id,inv.location,inv.item_master_id,inv.item_number,item.description,cate.category_id,cate.item_category,inv.inventory_status_id,inv.inv_status
		END

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] '
		SET @v_vchProcessData2 = 'Owner: ' + @v_vchOwner
		SET @v_vchProcessData3 = 'Lot Number: ['+ ISNULL(@in_vchLotNumber,'') + '] '
		SET @v_vchProcessData4 = 'To Status: [' + ISNULL(@v_vchToInvStatus,'') + '] '
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END

	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] '
	SET @v_vchProcessData2 = 'Owner: ' + @v_vchOwner
	SET @v_vchProcessData3 = 'Lot Number: ['+ ISNULL(@in_vchLotNumber,'') + '] '
	SET @v_vchProcessData4 = 'To Status: [' + ISNULL(@v_vchToInvStatus,'') + '] '
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage			

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_change_status_by_serial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_change_status_by_serial] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchInventoryID		UNIQUEIDENTIFIER,
	@in_vchSerialNumber		NVARCHAR(50),
	@in_vchToInvStatusID	UNIQUEIDENTIFIER,
	@in_fltQty				FLOAT = 0,
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_change_status_by_serial]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_CHANGE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'INV_CHANGE_STATUS'
	DECLARE @v_fltQtyUpdate			FLOAT = 0
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50)
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER
	DECLARE @v_vchOwner				NVARCHAR(40)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER
	DECLARE @v_vchItemNumber		NVARCHAR(50)
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchLocation			NVARCHAR(50)
	DECLARE @v_vchLPNControl		VARCHAR(5)
	DECLARE @v_vchLocType			NVARCHAR(20)
 
	DECLARE @v_vchFromInvStatusID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchFromInvStatus		NVARCHAR(50) = NULL
	DECLARE @v_vchToInvStatus		NVARCHAR(50) = NULL
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_dtMfgDate			DATE
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchAttribute1	    NVARCHAR(100)
	DECLARE @v_vchAttribute2	    NVARCHAR(100)
	DECLARE @v_vchAttribute3	    NVARCHAR(100)
	DECLARE @v_vchAttribute4	    NVARCHAR(100)
	DECLARE @v_vchAttribute5	    NVARCHAR(100)

	--UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)

	DECLARE @v_vchLotControl		VARCHAR(5)
	DECLARE @v_vchSNControl			VARCHAR(5)
	DECLARE @v_vchExpControl		VARCHAR(5)
	DECLARE @v_vchAttribute1Control	VARCHAR(5)
	DECLARE @v_vchAttribute2Control	VARCHAR(5)
	DECLARE @v_vchAttribute3Control	VARCHAR(5)
	DECLARE @v_vchAttribute4Control	VARCHAR(5)
	DECLARE @v_vchAttribute5Control	VARCHAR(5)

	DECLARE @v_vchInventoryID		UNIQUEIDENTIFIER
	DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER
	DECLARE @v_vchInvQuantity		FLOAT = 0
	DECLARE @v_vchInvQtyAllocate	FLOAT = 0

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)

	----For Serial
	--DECLARE @tInventorySerial TABLE
	--(
	--	[RowNumber] [INT] NOT NULL,
	--	[InventoryID] [varchar] (40) NOT NULL,
	--	[AttributeGroupID] [varchar] (40) NOT NULL,
	--	[quantity] [float] NOT NULL,
	--	[SerialNumber] [nvarchar] (50) NOT NULL
	--)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchReasonCode = reason_code
			--,  @v_vchReasonDescription = reason_code + ':' + ISNULL(description,'') 
		FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		 
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		--GET From Location
		SELECT @v_vchInventoryID	 = inventory_id
			,@v_vchAttributeGroupID	 = attribute_group_id
			,@v_vchWhMasterID	     = wh_master_id
			,@v_vchWarehouse	     = wh_id
			,@v_vchOwnerID			 = owner_id
			,@v_vchOwner			 = owner_code
			,@v_vchLocationID		 = location_id
			,@v_vchLocation			 = location
			,@v_vchLocType			 = loc_type
			,@v_vchERPSourceLocation = erp_location
			,@v_vchLPNControl		 = lpn_controlled
			,@v_vchParentLPN		 = parent_lpn
			,@v_vchLPN				 = lpn
			,@v_vchWhItemMasterID	 = wh_item_master_id
			,@v_vchItemMasterID		 = item_master_id
			,@v_vchItemNumber		 = item_number
			,@v_vchInvQuantity		 = quantity
			,@v_vchInvQtyAllocate	 = quantity_allocated
			,@v_vchBaseItemUomID	 = item_uom_id
			,@v_vchBaseUomPrompt	 = uom_prompt
			,@v_vchFromInvStatusID	 = inventory_status_id
			,@v_vchFromInvStatus	 = inv_status
			,@v_vchLotNumber		 = lot_number
			,@v_vchExpiryDate		 = expiry_date
			,@v_vchAttribute1		 = attribute1
			,@v_vchAttribute2		 = attribute2
			,@v_vchAttribute3		 = attribute3
			,@v_vchAttribute4		 = attribute4
			,@v_vchAttribute5		 = attribute5
			,@v_dtReceiveDate		 = receive_date
			,@v_dtMfgDate			 = mfg_date
			,@v_vchLotControl		 = lot_control
			,@v_vchExpControl	     = expiry_date_control
			,@v_vchSNControl		 = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_inventory_data_by_serial_item 
		WHERE inventory_id = @in_vchInventoryID
		AND serial_number = @in_vchSerialNumber

		IF @v_vchInventoryID IS NULL
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END
		
		SET @v_fltQtyUpdate = 1
			 
		-- Quantity not enough
		IF ((ISNULL(@v_vchInvQuantity,0) - ISNULL(@v_vchInvQtyAllocate,0)) < @v_fltQtyUpdate)
			BEGIN
				IF ISNULL(@v_vchInvQtyAllocate,0) > 0 
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END
			 
		--------------------------------------------
		--Manage source inventory
		--------------------------------------------
		UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round)
		WHERE inventory_id = @v_vchInventoryID 
		AND attribute_group_id = @v_vchAttributeGroupID 

		IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND invAttr.attribute_value = @in_vchSerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		--Inventory attribute
		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyUpdate,@Round) 
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID
				AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
		DELETE FROM t_wms_inventory WHERE quantity <= 0
	
		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		-- Check to status
		SELECT @v_vchToInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchToInvStatusID AND is_active = 'YES'
		IF(@v_vchToInvStatus IS NULL)
			BEGIN 
				SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToInvStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		-- check location is mix Status?
		DECLARE @v_vchMixStatus VARCHAR(5) = ''
		SELECT @v_vchMixStatus = mix_status FROM t_wms_location WHERE location_id = @v_vchLocationID
		IF EXISTS(SELECT inventory_status_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchLocationID AND inventory_status_id <> @in_vchToInvStatusID) AND @v_vchMixStatus = 'NO'
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_MIX_STATUS';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
		DECLARE @v_fltDestInvQty FLOAT = 0
		SELECT @v_vchDestInventoryID = inventory_id
			,@v_vchDestAttributeGroupID = attribute_group_id
			,@v_fltDestInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @in_vchToInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
								, @in_vchOwnerID			= @v_vchOwnerID
								, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
								, @in_vchLocationID			= @v_vchLocationID
								, @in_vchStatusID			= @in_vchToInvStatusID
								, @in_vchPalentLPN			= @v_vchParentLPN
								, @in_vchLPN				= @v_vchLPN
								, @in_fltQty				= @v_fltQtyUpdate
								, @in_fltQtyAllocate		= 0
								, @in_fltQtyIncoming		= 0
								, @in_vchInventoryType		= 'INVENTORY'
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMFGDate
								, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
				  
		--Insert/Update Attribute
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
			BEGIN --Update 
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
									WHERE inventory_id = @v_vchDestInventoryID 
									AND attribute_group_id = @v_vchDestAttributeGroupID
									AND attribute_value = @in_vchSerialNumber
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
							BEGIN
								SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END

						--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							(NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, @in_vchSerialNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
				
				IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
								quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round) 
						WHERE inventory_id = @v_vchDestInventoryID 
						AND attribute_group_id = @v_vchDestAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN --Insert
				-- insert new serial
				IF(@v_vchSNControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							(NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @v_vchDestAttributeGroupID
							, @in_vchSerialNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
							
				--Insert New Lot Number
				IF(@v_vchLotControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @v_vchDestAttributeGroupID
							, @v_vchLotNumber
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Expiry Date
				IF(@v_vchExpControl = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @v_vchDestAttributeGroupID
							, @v_vchExpiryDate
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute1
				IF(@v_vchAttribute1Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute1
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute2
				IF(@v_vchAttribute2Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute2
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute3
				IF(@v_vchAttribute3Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute3
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute4
				IF(@v_vchAttribute4Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute4
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Attribute5
				IF(@v_vchAttribute5Control = 'FULL')
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @v_vchDestInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @v_vchDestAttributeGroupID
							, @v_vchAttribute5
							, ROUND(@v_fltQtyUpdate,@Round)
							, 0
							, 0
							, GETDATE()
							, @in_vchUserID)
					END
			END 

		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				IF @v_vchSNControl = 'FULL'
					BEGIN
						DELETE FROM t_wms_inventory_remark 
						WHERE inventory_id = @v_vchDestInventoryID
						AND serial_number = @in_vchSerialNumber

						INSERT INTO [dbo].[t_wms_inventory_remark]
							([inventory_remark_id]
							,[inventory_id]
							,[serial_number]
							,[reason_id]
							,[remark]
							,[create_by]
							,[create_date] )
						VALUES
							( NEWID()
							,@v_vchDestInventoryID
							,@in_vchSerialNumber
							,@in_vchReasonID
							,@in_vchRemark
							,@in_vchUserID
							,GETDATE())
					END
				ELSE
					BEGIN
						IF NOT EXISTS (SELECT inventory_remark_id FROM t_wms_inventory_remark WHERE inventory_id = @v_vchDestInventoryID)
							BEGIN
								INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date])
							 VALUES (NEWID()
								   ,@v_vchDestInventoryID
								   ,NULL
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE())
							END
						ELSE
							BEGIN
								UPDATE t_wms_inventory_remark SET 
									 reason_id = @in_vchReasonID
									,remark = @in_vchRemark
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE inventory_id = @v_vchDestInventoryID
							END
					END
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		IF @v_vchLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchLocationID
			END

		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			DECLARE @v_fltAfterQty FLOAT = 0
			SET @v_fltAfterQty =  ROUND(@v_vchInvQuantity - @v_fltQtyUpdate,@Round)

			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT  
				END

			--Write Tran Log
			DECLARE @v_dtExpiryDate DATE = NULL
			IF ISNULL(@v_vchExpiryDate,'') = '' 
				BEGIN
					SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate)
				END

			SET @v_dtProcessDateTime = GETDATE();
			EXEC usp_LogManager
				@in_vchApplicationID		= @in_vchApplicationID
				, @in_vchAppName			= @v_vchApplicationName
				, @in_vchDevice				= @in_vchDeviceID
				, @in_vchUserID				= @in_vchUserID
				, @in_vchLogType			= 'TRANSACTION'
				, @in_vchProcess			= @c_vchObjName
				, @in_dtProcessDateTime		= @v_dtProcessDateTime
				, @in_vchTranType			= @v_vchTranType
				, @in_vchSubTranType		= @v_vchSubTranType
				, @in_vchDescription		= 'Change Inventory Status by serial'
				, @in_dtStartTranDate		= @v_dtStartTranDate
				, @in_dtEndTranDate			= @v_dtProcessDateTime
				, @in_vchWhID 				= @v_vchWarehouse
				, @in_vchToWhID 			= @v_vchWarehouse
				, @in_vchLocation			= @v_vchLocation
				, @in_vchToLocation			= @v_vchLocation
				, @in_vchOwner				= @v_vchOwner
				, @in_vchToOwner			= @v_vchOwner
				, @in_vchItemNumber			= @v_vchItemNumber
				, @in_fltQuantity			= @v_fltQtyUpdate
				, @in_vchUOM				= @v_vchBaseUomPrompt
				, @in_fltAfterQuantity		= @v_fltAfterQty
				, @in_vchAfterUOM			= @v_vchBaseUomPrompt
				, @in_vchLotNumber			= @v_vchLotNumber
				, @in_vchAfterLotNumber		= @v_vchLotNumber
				, @in_dtExpiryDate			= @v_dtExpiryDate
				, @in_dtAfterExpiryDate		= @v_dtExpiryDate
				, @in_vchAttribute1			= @v_vchAttribute1	
				, @in_vchAfterAttribute1	= @v_vchAttribute1
				, @in_vchAttribute2			= @v_vchAttribute2
				, @in_vchAfterAttribute2	= @v_vchAttribute2
				, @in_vchAttribute3			= @v_vchAttribute3
				, @in_vchAfterAttribute3	= @v_vchAttribute3	
				, @in_vchAttribute4			= @v_vchAttribute4
				, @in_vchAfterAttribute4	= @v_vchAttribute4
				, @in_vchAttribute5			= @v_vchAttribute5
				, @in_vchAfterAttribute5	= @v_vchAttribute5
				, @in_vchSerialNumber		= @in_vchSerialNumber
				, @in_vchReferenceNumber	= @in_vchReferenceNumber
				, @in_vchLPN				= @v_vchLPN
				, @in_vchAfterLPN			= @v_vchLPN
				, @in_vchParentLPN			= @v_vchParentLPN
				, @in_vchAfterParentLPN		= @v_vchParentLPN
				, @in_vchStatus				= @v_vchFromInvStatus
				, @in_vchAfterStatus		= @v_vchToInvStatus
				, @in_dtReceiveDate			= @v_dtReceiveDate
				, @in_dtProductionDate		= @v_dtMFGDate
				, @in_vchReasonCode			= @v_vchReasonCode 
				, @in_vchHostRecordID		= @v_vchHostRecordID	--ใช้ Interface
				, @in_vchControlNumber		= @v_vchHostRecordID	--ใช้ Write Log
				, @in_vchControlValue1		= @v_vchERPSourceLocation
				, @in_vchControlValue2		= @v_vchERPDestLocation
				, @in_vchInputQuantity		= @v_fltQtyUpdate
				, @in_vchInputUOM			= @v_vchBaseUomPrompt
				, @in_vchHUDF1				= @in_vchRemark
				, @in_vchErrorCode			= @out_ErrorCode OUTPUT
				, @in_vchMessage			= @out_ErrorMessage OUTPUT

			IF (@out_ErrorCode <> '0')
				BEGIN
					GOTO WRITE_PROC;
				END

		END

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'CHANGE_STATUS'
									   ,@in_vchWhMasterID	= @v_vchWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @v_vchOwner
									   ,@in_vchLocationID	= @v_vchLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchFromInvStatusID
									   ,@in_vchToWhMasterID	= @v_vchWhMasterID
									   ,@in_vchToLocationID	= @v_vchLocationID
									   ,@in_vchToInvStatusID = @in_vchToInvStatusID
									   ,@in_fltQuantity		= @v_fltQtyUpdate
									   ,@in_vchUserID		= @in_vchUserID
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
		SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
		SET @v_vchProcessData4 = 'Status: ['+ ISNULL(@v_vchFromInvStatus,'') + '] To Status: [' + ISNULL(@v_vchToInvStatus,'') + ']'
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END	   
	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'From Location: ['+ ISNULL(@v_vchLocation,'') + ']'
	SET @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET @v_vchProcessData3 = 'Lot: ['+ ISNULL(@v_vchLotNumber,'') + '] Exp: [' + ISNULL(@v_vchExpiryDate,'') + ']'
		SET @v_vchProcessData4 = 'Status: ['+ ISNULL(@v_vchFromInvStatus,'') + '] To Status: [' + ISNULL(@v_vchToInvStatus,'') + ']'
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
		
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_control_all_value]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-06-26
-- Description:	Update inventory status
-- =============================================
CREATE PROCEDURE [dbo].[usp_inventory_control_all_value]
	@in_vchApplicationID	VARCHAR(40)	  = NULL,	
	@in_vchWarehouse		NVARCHAR(25)  = NULL,	
	@in_vchDeviceID			NVARCHAR(50)  = NULL,	
	@in_vchUserID			NVARCHAR(25)  = NULL,	
	@in_vchTransactionType	NVARCHAR(20)  = NULL,	
	@in_vchSubTranType		NVARCHAR(20)  = NULL,	
	@in_vchAllParentLPN		NVARCHAR(3)	  = NULL,	
	@in_vchAllLPN			NVARCHAR(3)	  = NULL,	
	@in_vchAllItem			NVARCHAR(3)	  = NULL,	
	@in_vchAllLot			NVARCHAR(3)	  = NULL,	
	@in_vchAllExpiryDate	NVARCHAR(3)	  = NULL,	
	@in_vchAllSerial		NVARCHAR(3)	  = NULL,	
	@in_vchAllLocation		NVARCHAR(3)	  = NULL,	
	@in_vchFromLocation		NVARCHAR(50)  = NULL,	
	@in_vchToLocation		NVARCHAR(50)  = NULL,	
	@in_vchFromParentLPN	NVARCHAR(25)  = NULL,	
	@in_vchFromLPN			NVARCHAR(25)  = NULL,	
	@in_vchToParentLPN		NVARCHAR(25)  = NULL,	
	@in_vchToLPN			NVARCHAR(25)  = NULL,	
	@in_vchItem				NVARCHAR(50)  = NULL,	
	@in_vchLotNumber		NVARCHAR(50)  = NULL,	
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchAttribute1		NVARCHAR(50)  = NULL,
	@in_vchAttribute2		NVARCHAR(50)  = NULL,
	@in_vchAttribute3		NVARCHAR(50)  = NULL,
	@in_vchAttribute4		NVARCHAR(50)  = NULL,
	@in_vchAttribute5		NVARCHAR(50)  = NULL,
	@in_vchFromStatus		NVARCHAR(50)  = NULL,	
	@in_vchToStatus			NVARCHAR(50)  = NULL,	
	@in_vchOwner			NVARCHAR(50)  = NULL,	
	@in_vchReasonCode		NVARCHAR(20)  = NULL,	
	@out_ErrorCode			NVARCHAR(200) OUTPUT,	
	@out_ErrorMessage		NVARCHAR(500) OUTPUT	 
AS
BEGIN
	SET NOCOUNT ON;
   
	DECLARE
	-- Error handling variables
    @c_vchObjName				NVARCHAR(30) = '[usp_inventory_control_all_value]', -- The name that uniquely tags this object.
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
    @v_dtProcessDateTime		DATETIME,
    
	@v_vchWarehouseID			NVARCHAR(40),
	@v_vchLocationID			NVARCHAR(40),
	@v_vchToLocationID			NVARCHAR(40),
	@v_vchInventoryID			NVARCHAR(40),
	@v_vchAttributeGroupID		NVARCHAR(40),
	@v_vchInventoryFromStatusID	NVARCHAR(40),
	@v_vchInventoryToStatusID	NVARCHAR(40),
	@v_vchInvAttributeID		NVARCHAR(40),
	
	@v_fltQuantity				FLOAT,
	@v_fltQuntityAllocate		FLOAT,
	
	@v_vchWHItemMasterID		NVARCHAR(40),
	@v_vchItemMasterID			NVARCHAR(40),
	@v_vchItemNumber			NVARCHAR(50),
	@v_vchItemUOM				NVARCHAR(25),
	@v_vchParentLPN				NVARCHAR(25),
	@v_vchLPN					NVARCHAR(25),
	@v_vchToLPN					NVARCHAR(25),
	@v_vchFromInvStatusID		NVARCHAR(50),
	@v_vchToInvStatusID			NVARCHAR(50),
	@v_vchLocation				NVARCHAR(50),

	@cursorInventory			CURSOR,
	@dynamicSQL					NVARCHAR(MAX) = '',
	@ConditionSQL				NVARCHAR(MAX) = '',
	@v_vchChkReceiveDateSQL		NVARCHAR(MAX) = '',
	@v_vchHostInterfaceID		VARCHAR(40),
	@v_vchReceiveDate			DATE,
	@v_vchLocationType			NVARCHAR(25),
	@v_vchLPNControl			NVARCHAR(3),
	@v_vchMixItem				NVARCHAR(3),
	@v_vchMixLot				NVARCHAR(3),
    @v_vchMixExpiryDate			NVARCHAR(3),
	@v_vchMixAttribute1			NVARCHAR(3),
	@v_vchMixAttribute2			NVARCHAR(3),
	@v_vchMixAttribute3			NVARCHAR(3),
	@v_vchMixAttribute4			NVARCHAR(3),
	@v_vchMixAttribute5			NVARCHAR(3),
    @v_vchMixOwner				NVARCHAR(3),
	@v_vchMixStatus				NVARCHAR(3),
	@v_vchOverrideReceiveDate	NVARCHAR(3),
	@v_vchApplicationName		NVARCHAR(100),
	@v_dtDateNow				NVARCHAR(10),
	@v_vchDescription			NVARCHAR(100),
	
	@v_vchLot_Number			NVARCHAR(50),
	@v_vchExpiry_Date			NVARCHAR(8),
	@v_vchSerial_Number			NVARCHAR(50),
	@v_vchAttribute1			NVARCHAR(100),
	@v_vchAttribute2			NVARCHAR(100),
	@v_vchAttribute3			NVARCHAR(100),
	@v_vchAttribute4			NVARCHAR(100),
	@v_vchAttribute5			NVARCHAR(100),

	@v_vchLotControl			NVARCHAR(10),
	@v_vchExpiryDateControl		NVARCHAR(10),
	@v_vchSerialControl			NVARCHAR(10),
	@v_vchAttribute1Control		NVARCHAR(10),
	@v_vchAttribute2Control		NVARCHAR(10),
	@v_vchAttribute3Control		NVARCHAR(10),
	@v_vchAttribute4Control		NVARCHAR(10),
	@v_vchAttribute5Control		NVARCHAR(10),

	@Round						INT,
	@v_vchMovementType			NVARCHAR(10),
	@v_vchFromPlant				NVARCHAR(50),
	
	@v_vchDubLocation			NVARCHAR(50),
    @v_vchDubParentLPN			NVARCHAR(25),
    @v_vchOldLPN				NVARCHAR(25),
    @v_vchOldInventoryStatusID	VARCHAR(40),
    @v_vchChkReceiveDate		DATE,
	@v_vchBeginTrans			BIT = 0,
	@v_vchOwnerID				VARCHAR(40),
	@v_vchOwnerCode				NVARCHAR(50),
	@v_vchOldItem				NVARCHAR(50),
	@v_vchOldWHItemMasterID		VARCHAR(40),

	-- 2013-10-04 check capacity location
	@v_fltCapacity				FLOAT = 0,
	@v_fltLPNQtyFromLocation	FLOAT = 0,
	@v_fltLPNQtyToLocation		FLOAT = 0,
	@v_vchLocal					NVARCHAR(10)

	
	IF (@in_vchToParentLPN = '')
		SET @in_vchToParentLPN = NULL;
	IF (@in_vchToLPN = '')
		SET @in_vchToLPN = NULL;
	IF (@in_vchItem = '')
		SET @in_vchItem = NULL;
	IF (@in_vchLotNumber = '')
		SET @in_vchLotNumber = NULL;
	IF (@in_vchFromStatus = '')
		SET @in_vchFromStatus = NULL;
	IF (@in_vchToStatus = '')
		SET @in_vchToStatus = NULL;
		
	BEGIN TRY
		
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT

		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)		 
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchWarehouseID = wh_master_id,@v_vchFromPlant = wh_group FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
		SELECT @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWarehouseID AND location = @in_vchFromLocation
	
		SELECT @v_vchToLocationID = location_id
			, @v_vchLocationType = loc_type
			, @v_vchLPNControl = lpn_controlled
			, @v_vchMixItem = mix_items
			, @v_vchMixLot = mix_lot
			, @v_vchMixExpiryDate = mix_expiry_dates
			, @v_vchMixOwner = mix_owners
			, @v_vchMixStatus = mix_status
			, @v_vchMixAttribute1 = mix_attribute1
			, @v_vchMixAttribute2 = mix_attribute2
			, @v_vchMixAttribute3 = mix_attribute3
			, @v_vchMixAttribute4 = mix_attribute4
			, @v_vchMixAttribute5 = mix_attribute5
			, @v_vchOverrideReceiveDate = override_receive_date
			, @v_fltCapacity = ISNULL(capacity_qty,0)
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWarehouseID 
		AND location = @in_vchToLocation
		
		IF (@v_vchToLocationID IS NULL)
			BEGIN
				SET @out_ErrorCode = '905';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		-- Check duplicate parent lpn.
		IF (ISNULL(@in_vchToParentLPN,'') <> '')
			BEGIN
				SELECT TOP 1 @v_vchDubLocation = location_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWarehouseID AND (location_id <> @v_vchLocationID AND location_id <> @v_vchToLocationID) AND parent_lpn = @in_vchToParentLPN
				IF (ISNULL(@v_vchDubLocation,'') <> '')
					BEGIN
						SELECT @v_vchDubLocation = location FROM t_wms_location WHERE location_id = @v_vchDubLocation
						SET @out_ErrorCode = '901';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_LPN_DUPLICATE',@v_vchLocal,@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
			END

		-- Check duplicate lpn.
		IF (ISNULL(@in_vchToLPN,'') <> '')
			BEGIN
				IF (ISNULL(@in_vchFromParentLPN,'') <> '' OR ISNULL(@in_vchToParentLPN,'') <> '')
					BEGIN
						SELECT TOP 1 @v_vchDubParentLPN = parent_lpn FROM t_wms_inventory 
						WHERE wh_master_id = @v_vchWarehouseID 
						AND (ISNULL(parent_lpn,'') <> ISNULL(@in_vchFromParentLPN,'') 
						AND ISNULL(parent_lpn,'') <> ISNULL(@in_vchToParentLPN,'')) 
						AND lpn = @in_vchToLPN

						IF (ISNULL(@v_vchDubParentLPN,'') <> '')
							BEGIN
								SET @out_ErrorCode = '901';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_PL',@v_vchLocal,@in_vchToLPN,@v_vchDubParentLPN,'@param3','@param4','@param5')
								GOTO WRITE_PROC
							END
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchDubLocation = location_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWarehouseID AND (location_id <> @v_vchLocationID AND location_id <> @v_vchToLocationID) AND lpn = @in_vchToLPN
						IF (ISNULL(@v_vchDubLocation,'') <> '')
							BEGIN
								SELECT @v_vchDubLocation = location FROM t_wms_location WHERE location_id = @v_vchDubLocation
								SET @out_ErrorCode = '901';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_LOCATION',@v_vchLocal,@in_vchToLPN,@v_vchDubLocation,'@param3','@param4','@param5')
								GOTO WRITE_PROC
							END
					END
			END
		
		IF (ISNULL(@in_vchItem,'') <> '')
			BEGIN
				SET @v_vchItemNumber = @in_vchItem;
				
				------------------------------------------------------
				-- mai 28/02/2014 : เพิ่ม join item crossref
				------------------------------------------------------
				SELECT @v_vchItemMasterID = item.item_master_id
					,@in_vchItem = item.item_number
					,@v_vchLotControl = item.lot_control
					,@v_vchExpiryDateControl = item.expiry_date_control
					,@v_vchSerialControl = item.sn_control 
					,@v_vchAttribute1Control = item.attribute1_control
					,@v_vchAttribute2Control = item.attribute2_control
					,@v_vchAttribute3Control = item.attribute3_control
					,@v_vchAttribute4Control = item.attribute4_control
					,@v_vchAttribute5Control = item.attribute5_control
				FROM t_wms_item item
				LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
				WHERE (item.item_number = @in_vchItem OR item.dg_code = @in_vchItem OR cref.alternate_item_number = @in_vchItem)
				AND item.owner_id = @v_vchOwnerID

				IF (ISNULL(@v_vchItemMasterID,'') = '')
					BEGIN
						SET @out_ErrorCode = '902';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',@v_vchLocal,@in_vchItem,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END

				SELECT @v_vchWHItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseID and item_master_id = @v_vchItemMasterID
			END
			
		SELECT @v_vchFromInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchFromStatus AND is_active = 'YES';

--------------------------------------------------------------------------------------------------	
		-- Add condition value
		IF (ISNULL(@v_vchOwnerID,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND owner_id = ''' + @v_vchOwnerID + ''' ';
			END
		IF (ISNULL(@in_vchFromStatus,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND inventory_status_id = ''' + @v_vchFromInvStatusID + ''' ';
			END
		IF (ISNULL(@in_vchItem,'') <> '')
			BEGIN
				IF (ISNULL(@in_vchAllItem,'') = 'YES')
					BEGIN
						SET @in_vchItem = NULL;
					END
				SET @ConditionSQL = @ConditionSQL + ' AND wh_item_master_id = ''' + @v_vchWHItemMasterID + ''' ';
			End
		IF (ISNULL(@in_vchFromParentLPN,'') <> '' AND ISNULL(@in_vchAllParentLPN,'') <> 'YES')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND parent_lpn = ''' + @in_vchFromParentLPN + ''' ';
			END
		IF (ISNULL(@in_vchFromLPN,'') <> '' AND ISNULL(@in_vchAllLPN,'') <> 'YES')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND lpn = ''' + @in_vchFromLPN + ''' ';
			END	
		IF (ISNULL(@in_vchAttribute1,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND attribute1 = ''' + @in_vchAttribute1 + ''' ';
			END	
		IF (ISNULL(@in_vchAttribute2,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND attribute2 = ''' + @in_vchAttribute2 + ''' ';
			END
		IF (ISNULL(@in_vchAttribute3,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND attribute3 = ''' + @in_vchAttribute3 + ''' ';
			END	
		IF (ISNULL(@in_vchAttribute4,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND attribute4 = ''' + @in_vchAttribute4 + ''' ';
			END	
		IF (ISNULL(@in_vchAttribute5,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND attribute5 = ''' + @in_vchAttribute5 + ''' ';
			END
		
		-- check inventory quantity allocated
		SET @dynamicSQL = ' SELECT TOP 1 @v_fltQuntityAllocate = quantity_allocated FROM v_wms_inventory_data
							WHERE wh_master_id = ''' + @v_vchWarehouseID  + '''
							AND location_id = ''' + @v_vchLocationID + ''' 
							AND quantity_allocated > 0 '
		
		SET @v_vchDescription = 'Inventory Control All';
		SET @dynamicSQL = @dynamicSQL + @ConditionSQL;
		EXEC sp_executesql @dynamicSQL,N'@v_fltQuntityAllocate FLOAT OUTPUT',@v_fltQuntityAllocate OUTPUT;
		IF (@v_fltQuntityAllocate IS NOT NULL)
			BEGIN
				SET @out_ErrorCode = '999';
				
				IF (@in_vchAllLPN = 'YES')
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_HAVE_QUANITY_ALLOCATE',@v_vchLocal,@in_vchFromLocation,@in_vchFromParentLPN,'@param3','@param4','@param5')
				ELSE
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_HAVE_QUANITY_ALLOCATE',@v_vchLocal,@in_vchFromLocation,@in_vchFromParentLPN,@in_vchFromLPN,@in_vchItem,'@param5')
				
				GOTO WRITE_PROC;
			END
		
		--  check lpn capacity in to location 2013-10-04
		IF (@v_fltCapacity > 0)
			BEGIN
				SET @dynamicSQL = '';
				SET @dynamicSQL = ' SELECT @v_fltLPNQtyFromLocation = COUNT(DISTINCT lpn) 
									FROM t_wms_inventory
									WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' 
									AND location_id = ''' + @v_vchLocationID + ''' ';
				SET @dynamicSQL = @dynamicSQL + @ConditionSQL;
				EXEC sp_executesql @dynamicSQL,N'@v_fltLPNQtyFromLocation FLOAT OUTPUT',@v_fltLPNQtyFromLocation OUTPUT;

				SET @dynamicSQL = '';
				SET @dynamicSQL = ' SELECT @v_fltLPNQtyToLocation = COUNT(DISTINCT lpn) 
									FROM t_wms_inventory
									WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' 
									AND location_id = ''' + @v_vchToLocationID + ''' 
									AND ISNULL(lpn,'''') NOT IN ( ''' + ISNULL(@in_vchToLPN,'') + ''' ) ';

				EXEC sp_executesql @dynamicSQL,N'@v_fltLPNQtyToLocation float output',@v_fltLPNQtyToLocation OUTPUT;

				IF (ISNULL(@v_fltLPNQtyFromLocation,0) + ISNULL(@v_fltLPNQtyToLocation,0) > @v_fltCapacity)
					BEGIN
						SET @out_ErrorCode = '989';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_IS_FULL_CAPACITY',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-- === Get Inventory Data for move == --
		SET @dynamicSQL	= '';
		
		-- ************ select inventory data *************
		IF(@v_vchSerialControl = 'FULL' OR @in_vchAllSerial = 'YES')
			BEGIN
				SET @dynamicSQL = '	 SELECT inventory_id
										,attribute_group_id
										,wh_item_master_id
										,owner_id
										,location_id
										,parent_lpn
										,lpn
										,lot_number
										,expiry_date
										,serial_number
										,quantity
										,inventory_status_id
										,receive_date
										,owner_code
										,attribute1
										,attribute2
										,attribute3
										,attribute4
										,attribute5
									 FROM v_wms_inventory_data_by_serial ';
			END
		ELSE
			BEGIN
				SET @dynamicSQL = ' SELECT inventory_id
									  ,attribute_group_id
									  ,wh_item_master_id
									  ,owner_id
									  ,location_id
									  ,parent_lpn
									  ,lpn
									  ,lot_number
									  ,expiry_date
									  ,serial_number
									  ,quantity
									  ,inventory_status_id
									  ,receive_date
									  ,owner_code
									  ,attribute1
									  ,attribute2
									  ,attribute3
									  ,attribute4
									  ,attribute5
								   FROM v_wms_inventory_data ';
			END

		IF (ISNULL(@in_vchAllParentLPN,'') = 'YES') -- All lpn in parent lpn
			BEGIN
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' ';
				SET @v_vchDescription = 'MOVE ALL PARENTLPN';
			END						 
		ELSE IF (ISNULL(@in_vchAllLPN,'') = 'YES') -- ALL LPN
			BEGIN
				SET @in_vchToLPN = null;
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' ';
				SET @v_vchDescription = 'MOVE ALL LPN';
			END
		ELSE IF (ISNULL(@in_vchAllItem,'') = 'YES') -- ALL ITEM
			BEGIN
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' ';
				SET @v_vchDescription = 'MOVE ALL ITEM';
			END
		ELSE IF (ISNULL(@in_vchAllSerial,'') = 'YES') -- ALL Serial
			BEGIN
				--set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and serial_number IS NOT NULL '
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' AND serial_number IS NOT NULL '
				SET @v_vchDescription = 'MOVE ALL Serial';
			END				
		ELSE IF (ISNULL(@in_vchAllLot,'') = 'YES') -- ALL Lot
			BEGIN
				--SEt @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and lot_number IS NOT NULL '
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' AND lot_number IS NOT NULL '
				SET @v_vchDescription = 'MOVE ALL LOT';
			END
		ELSE IF (ISNULL(@in_vchAllExpiryDate,'') = 'YES') -- ALL Expiry date
			BEGIN
				--set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and expiry_date IS NOT NULL '
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchLocationID + ''' AND expiry_date IS NOT NULL '
				IF (ISNULL(@in_vchLotNumber,'') <> '')
					BEGIN
						SET @ConditionSQL = @ConditionSQL + ' AND lot_number = ''' + @in_vchLotNumber + ''' ';
					END
				SET @v_vchDescription = 'MOVE ALL Expiry Date';						
			END				
		ELSE IF (ISNULL(@in_vchAllLocation,'') = 'YES') -- ALL in Location
			BEGIN
				SET @dynamicSQL = @dynamicSQL + ' WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' ';
				SET @v_vchDescription = 'MOVE ALL LOCATION';								
			END
				
		SET @dynamicSQL = @dynamicSQL + ISNULL(@ConditionSQL,'');

		IF (@v_vchLocationType <> 'FORK')
			BEGIN
				IF (@v_vchOverrideReceiveDate = 'NO')
					BEGIN
						IF ((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_MIX_RECEIVE_DATE') = 'NO')
							BEGIN
								IF EXISTS(SELECT receive_date FROM t_wms_inventory WHERE wh_master_id = @v_vchWarehouseID AND location_id = @v_vchToLocationID)
									BEGIN
										SET @v_vchChkReceiveDateSQL = 'SELECT TOP 1 @v_vchChkReceiveDate = receive_date 
											FROM t_wms_inventory
											WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' 
											AND location_id = ''' + @v_vchLocationID + ''' ' + ISNULL(@ConditionSQL,'') + ' 
											AND receive_date NOT IN (SELECT receive_date FROM t_wms_inventory WHERE wh_master_id = ''' + @v_vchWarehouseID + ''' AND location_id = ''' + @v_vchToLocationID + ''') '
										EXEC sp_executesql @v_vchChkReceiveDateSQL,N'@v_vchChkReceiveDate DATE OUTPUT',@v_vchChkReceiveDate OUTPUT;
										IF (ISNULL(@v_vchChkReceiveDate,'') <> '')
											BEGIN
												SET @out_ErrorCode = '914';
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CAN_NOT_MIXED_RECEIVE_DATE',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;
											END
									END
							END
						--Else
						--	Begin
						--		select top 1 @v_vchReceiveDate = receive_date from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID
						--	End
					END
				ELSE
					BEGIN
						IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_NEW_RECEIVE_DATE') = 'OLD')
							BEGIN
								SELECT TOP 1 @v_vchReceiveDate = receive_date FROM t_wms_inventory 
								WHERE wh_master_id = @v_vchWarehouseID 
								AND location_id = @v_vchLocationID
							END
						ELSE
							BEGIN
								SELECT TOP 1 @v_vchReceiveDate = receive_date FROM t_wms_inventory WHERE wh_master_id = @v_vchWarehouseID AND location_id = @v_vchLocationID
								
								UPDATE t_wms_inventory SET receive_date = @v_vchReceiveDate
								WHERE wh_master_id = @v_vchWarehouseID 
								AND location_id = @v_vchToLocationID
							END
					END
			END
			
		SET @dynamicSQL = '	 SET @cursorInventory = CURSOR FORWARD_ONLY STATIC FOR ' + @dynamicSQL + ' ; OPEN @cursorInventory'								

		EXEC sp_executesql @dynamicSQL, N'@cursorInventory CURSOR OUTPUT',@cursorInventory OUTPUT
		
		FETCH @cursorInventory INTO @v_vchInventoryID
									,@v_vchAttributeGroupID
									,@v_vchWHItemMasterID
									,@v_vchOwnerID
									,@v_vchLocationID
									,@v_vchParentLPN
									,@v_vchLPN
									,@v_vchLot_Number
									,@v_vchExpiry_Date
									,@v_vchSerial_Number
									,@v_fltQuantity
									,@v_vchFromInvStatusID
									,@v_vchReceiveDate
									,@v_vchOwnerCode
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute5
--------------------------------------------------------------------------------------------------		

		IF (@v_vchInventoryID IS NULL)
			BEGIN
				CLOSE @cursorInventory;
				DEALLOCATE @cursorInventory;
				SET @out_ErrorCode = '999'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
			
		--If (@in_vchTransactionType = 'INV_STATUS_CHANGE' and @in_vchSubTranType = 'INV_STATUS_CHANGE')
		--	Begin
		--		exec usp_get_HostInterfaceID @v_vchHostInterfaceID output
		--	End
		
		IF (@v_vchMixStatus = 'NO')
			IF EXISTS(SELECT TOP 1 inventory_status_id FROM t_wms_inventory 
					  WHERE inventory_status_id <> @v_vchToInvStatusID 
					  AND wh_master_id = @v_vchWarehouseID 
					  AND location_id = @v_vchToLocationID)
				BEGIN
					SET @out_ErrorCode = '999';
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_STATUS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
					CLOSE @cursorInventory;
					DEALLOCATE @cursorInventory;
					GOTO WRITE_PROC;
				END
		
		SET @v_dtDateNow = SUBSTRING(CONVERT(NVARCHAR,GETDATE(),126),0,11);
			
		IF (ISNULL(@in_vchToLPN,@v_vchLPN) = '' AND @v_vchLPNControl = 'YES')
			BEGIN 
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
				CLOSE @cursorInventory;
				DEALLOCATE @cursorInventory;
				GOTO WRITE_PROC;
			END
		
		IF (@in_vchTransactionType = 'INV_STATUS_CHANGE' AND @in_vchSubTranType = 'INV_STATUS_CHANGE')
			BEGIN
				IF (@in_vchFromStatus = 'Blocked' AND @in_vchToStatus = 'Unrestricted')
					SET @v_vchMovementType = '343';
				ELSE IF (@in_vchFromStatus = 'Unrestricted' AND @in_vchToStatus = 'Blocked')
					SET @v_vchMovementType = '344';
				ELSE IF (@in_vchFromStatus = 'Blocked' AND @in_vchToStatus = 'QI')
					SET @v_vchMovementType = '349';
				ELSE IF (@in_vchFromStatus = 'QI' AND @in_vchToStatus = 'Blocked')
					SET @v_vchMovementType = '350';
				ELSE IF (@in_vchFromStatus = 'QI' AND @in_vchToStatus = 'Unrestricted')
					SET @v_vchMovementType = '321';
				ELSE IF (@in_vchFromStatus = 'Unrestricted' AND @in_vchToStatus = 'QI')
					SET @v_vchMovementType = '322';	
				ELSE
					SET @v_vchMovementType = NULL
					
				EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT
															
			END
			
		BEGIN TRANSACTION

			SET @v_vchBeginTrans = 1;

			WHILE @@FETCH_STATUS = 0
				BEGIN
					IF (ISNULL(@in_vchFromStatus,'') = '' OR @v_vchOldInventoryStatusID <> @v_vchFromInvStatusID)
						BEGIN
							--select top 1 @in_vchFromStatus = inv_status,@v_vchFromInvStatusID = inventory_status_id 
							--from v_wms_inventory_item where location = @in_vchFromLocation
							--and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and lpn = @v_vchLPN

							SELECT TOP 1 @in_vchFromStatus = inv_status
							FROM t_wms_inventory_status 
							WHERE inventory_status_id = @v_vchFromInvStatusID
						END
			
					IF (ISNULL(@in_vchToStatus,'') = '')
						BEGIN
							SET @in_vchToStatus = @in_vchFromStatus;
							SET @v_vchToInvStatusID = @v_vchFromInvStatusID;
						END
					ELSE IF (@in_vchFromStatus <> @in_vchToStatus)
						BEGIN
							SELECT @in_vchToStatus = inv_status,@v_vchToInvStatusID = inventory_status_id 
							FROM t_wms_inventory_status 
							WHERE inv_status = @in_vchToStatus
						END
					ELSE
						BEGIN
							SET @v_vchToInvStatusID = @v_vchFromInvStatusID;
						END
			
					IF (ISNULL(@in_vchAllItem,'') = 'YES') -- ALL ITEM
						BEGIN
							SET @v_vchParentLPN = NULL;
							IF (ISNULL(@in_vchToLPN,'') <> '')
								SET @v_vchLPN = @in_vchToLPN
						END
					ELSE IF (ISNULL(@in_vchAllSerial,'') = 'YES') -- ALL Serial
						BEGIN
							SET @v_vchParentLPN = NULL;
							SET @v_vchLPN = NULL;
							IF (ISNULL(@in_vchToLPN,'') <> '')
								SET @v_vchLPN = @in_vchToLPN
						END				
					ELSE IF (ISNULL(@in_vchAllLot,'') = 'YES') -- ALL Lot
						BEGIN
							SET @v_vchParentLPN = null;
							IF ((SELECT COUNT(DISTINCT wh_item_master_id) FROM t_wms_inventory WHERE wh_master_id = @v_vchWarehouseID AND location_id = @v_vchLocationID AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'') AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')) > 1)
								BEGIN
									SET @v_vchLPN = null;
								END
							IF (ISNULL(@in_vchToLPN,'') <> '')
								SET @v_vchLPN = @in_vchToLPN
						END
					ELSE IF (ISNULL(@in_vchAllExpiryDate,'') = 'YES') -- ALL Expiry date
						BEGIN
							SET @v_vchParentLPN = NULL;
							IF ((SELECT COUNT(DISTINCT lot_number) FROM v_wms_inventory_data WHERE wh_master_id = @v_vchWarehouseID AND location_id = @v_vchLocationID AND isnull(parent_lpn,'') = isnull(@in_vchFromParentLPN,'') and isnull(lpn,'') = isnull(@in_vchFromLPN,'') and lot_number = @v_vchLot_Number) > 1)
								BEGIN
									SET @v_vchLPN = NULL;
								END
							IF (ISNULL(@in_vchToLPN,'') <> '')
								SET @v_vchLPN = @in_vchToLPN
						END
					
					IF (@v_vchLPNControl = 'YES')
						IF(ISNULL(@v_vchLPN,'') = '')
							BEGIN
								SET @out_ErrorCode = '913';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					
					-- check location is mix owner?
					IF (@v_vchLocationType <> 'FORK' and @v_vchMixOwner = 'NO')
						IF((SELECT COUNT(inventory_id) FROM t_wms_inventory 
							WHERE wh_master_id = @v_vchWarehouseID 
							AND location_id = @v_vchToLocationID 
							AND owner_id <> @v_vchOwnerID) > 0)
							BEGIN
								SET @out_ErrorCode = '918';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_OWNER',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
				
					-- check location is mix item?
					IF (@v_vchLocationType <> 'FORK' and @v_vchMixItem = 'NO')
						IF((SELECT COUNT(inventory_id) FROM t_wms_inventory 
							WHERE wh_master_id = @v_vchWarehouseID 
							AND location_id = @v_vchToLocationID 
							AND wh_item_master_id <> @v_vchWHItemMasterID) > 0)
							BEGIN
								SET @out_ErrorCode = '915';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ITEM',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
								
					-- check location is mix lot?
					IF (@v_vchLocationType <> 'FORK' and @v_vchMixLot = 'NO')
						IF((SELECT COUNT(inv.inventory_id) FROM t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS lot_number
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'LOT' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id)
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchToLocationID 
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.lot_number <> @v_vchLot_Number) > 0)
							BEGIN
								SET @out_ErrorCode = '916';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_LOT',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					
					-- check location is mix expiry date
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixExpiryDate = 'NO')
						IF((SELECT COUNT(inv.inventory_id) FROM t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS expiry_date
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchToLocationID 
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.[EXPIRY_DATE] <> @v_vchExpiry_Date) > 0)
							BEGIN
								SET @out_ErrorCode = '917';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_EXPIRY_DATE',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					
					-- check location is mix attribute1
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixAttribute1 = 'NO')
						IF ((SELECT COUNT(inv.inventory_id) FROM  t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS attribute1
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE1' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchLocationID
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.attribute1 <> @v_vchAttribute1) > 0)
							BEGIN
								SET	@out_ErrorCode = '918';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ATTRIBUTE1',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								RETURN;
							END

					-- check location is mix attribute2
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixAttribute1 = 'NO')
						IF ((SELECT COUNT(inv.inventory_id) FROM  t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS attribute2
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE2' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchLocationID
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.attribute2 <> @v_vchAttribute2) > 0)
							BEGIN
								SET	@out_ErrorCode = '919';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ATTRIBUTE2',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								RETURN;
							END

					-- check location is mix attribute3
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixAttribute1 = 'NO')
						IF ((SELECT COUNT(inv.inventory_id) FROM  t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS attribute3
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE3' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchLocationID
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.attribute3 <> @v_vchAttribute3) > 0)
							BEGIN
								SET	@out_ErrorCode = '920';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ATTRIBUTE3',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								RETURN;
							END

					-- check location is mix attribute4
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixAttribute1 = 'NO')
						IF ((SELECT COUNT(inv.inventory_id) FROM  t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS attribute4
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE4' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchLocationID
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.attribute4 <> @v_vchAttribute4) > 0)
							BEGIN
								SET	@out_ErrorCode = '921';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ATTRIBUTE4',@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
								RETURN;
							END

					-- check location is mix attribute5
					IF (@v_vchLocationType <> 'FORK' AND @v_vchMixAttribute1 = 'NO')
						IF ((SELECT COUNT(inv.inventory_id) FROM  t_wms_inventory inv 
							LEFT JOIN (SELECT inventory_id
											,attribute_group_id
											,attribute_value AS attribute5
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE5' AND is_active = 'YES')
										) AS invAttr ON (inv.inventory_id = invAttr.inventory_id) AND (inv.attribute_group_id = invAttr.attribute_group_id) 
							WHERE inv.wh_master_id = @v_vchWarehouseID 
							AND inv.location_id = @v_vchLocationID
							AND inv.wh_item_master_id = @v_vchWHItemMasterID 
							AND invAttr.attribute5 <> @v_vchAttribute5) > 0)
							BEGIN
								SET	@out_ErrorCode = '922';
