												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
												, @v_vchAttributeGroupID
												, @v_vchAttribute5
												, ROUND(@v_fltQuantity,@Round)
												, 0
												, GETDATE()
												, @in_vchUserID)		
										END
								END
						
							INSERT INTO t_com_tran_log
								(app_id
								, tran_type
								, sub_tran_type
								, [app_name]
								, [description]
								, start_tran_datetime
								, end_tran_datetime
								, warehouse
								, to_warehouse
								, location
								, to_location
								, [owner]
								, to_owner
								, item_number
								, quantity
								, quantity_uom
								, after_quantity
								, after_quantity_uom
								, lot_number
								, after_lot_number
								, [expiry_date]
								, after_expiry_date
								, serial_number
								, [attribute1]
								, [after_attribute1]
								, [attribute2]
								, [after_attribute2]
								, [attribute3]
								, [after_attribute3]
								, [attribute4]
								, [after_attribute4]
								, [attribute5]
								, [after_attribute5]
								, [user_id]
								, reference_number
								, control_number
								, lpn
								, after_lpn
								, parent_lpn
								, after_parent_lpn
								, [status]
								, after_status
								, zone
								, order_number
								, line_number
								, device
								, create_by)
							VALUES
								( @in_vchApplicationID
								, @in_vchTransactionType
								, @in_vchSubTranType
								, @v_vchApplicationName
								, @v_vchDescription
								, GETDATE()
								, GETDATE()
								, @in_vchWarehouse
								, @in_vchWarehouse
								, @in_vchFromLocation
								, @in_vchToLocation
								, @v_vchOwnerCode
								, @v_vchOwnerCode
								, @v_vchItemNumber
								, @v_fltQuantity
								, @v_vchItemUOM
								, 0
								, NULL
								, (CASE @v_vchLot_Number  WHEN '' THEN NULL ELSE @v_vchLot_Number END)
								, (CASE @v_vchLot_Number  WHEN '' THEN NULL ELSE @v_vchLot_Number END)
								, (CASE @v_vchExpiry_Date WHEN '' THEN NULL ELSE @v_vchExpiry_Date END)
								, (CASE @v_vchExpiry_Date WHEN '' THEN NULL ELSE @v_vchExpiry_Date END)
								, @v_vchSerial_Number
								, (CASE @v_vchAttribute1 WHEN '' THEN NULL ELSE @v_vchAttribute1 END)
								, (CASE @v_vchAttribute1 WHEN '' THEN NULL ELSE @v_vchAttribute1 END)
								, (CASE @v_vchAttribute2 WHEN '' THEN NULL ELSE @v_vchAttribute2 END)
								, (CASE @v_vchAttribute2 WHEN '' THEN NULL ELSE @v_vchAttribute2 END)
								, (CASE @v_vchAttribute3 WHEN '' THEN NULL ELSE @v_vchAttribute3 END)
								, (CASE @v_vchAttribute3 WHEN '' THEN NULL ELSE @v_vchAttribute3 END)
								, (CASE @v_vchAttribute4 WHEN '' THEN NULL ELSE @v_vchAttribute4 END)
								, (CASE @v_vchAttribute4 WHEN '' THEN NULL ELSE @v_vchAttribute4 END)
								, (CASE @v_vchAttribute5 WHEN '' THEN NULL ELSE @v_vchAttribute5 END)
								, (CASE @v_vchAttribute5 WHEN '' THEN NULL ELSE @v_vchAttribute5 END)
								, @in_vchUserID
								, null
								, null
								, @v_vchLPN
								, isnull(@in_vchToLPN,@v_vchLPN)
								, isnull(@in_vchFromParentLPN,@v_vchParentLPN)
								, @v_vchParentLPN
								, @in_vchFromStatus
								, @in_vchToStatus
								, null
								, null
								, null
								, @in_vchDeviceID
								, @in_vchUserID)
						END

					IF (@in_vchTransactionType = 'INV_STATUS_CHANGE' AND @in_vchSubTranType = 'INV_STATUS_CHANGE' AND @v_vchMovementType IS NOT NULL)
						BEGIN
							INSERT INTO t_host_wms_interface_detail
								(interface_id
								, pstng_date
								, doc_date
								, move_type
								, material
								, plant
								, stge_loc
								, entry_qnt
								, entry_uom
								, quantity
								, base_uom
								, move_stloc)
							VALUES
								(@v_vchHostInterfaceID
								,@v_dtDateNow
								,@v_dtDateNow
								,@v_vchMovementType
								,@v_vchItemNumber
								,@v_vchFromPlant
								,@in_vchWarehouse
								,@v_fltQuantity
								,@v_vchItemUOM
								,@v_fltQuantity
								,@v_vchItemUOM
								,@in_vchWarehouse)
						END
					
					SET @v_vchOldLPN = @v_vchLPN;
					SET @v_vchOldInventoryStatusID = @v_vchFromInvStatusID;
					SET @v_vchOldItem = @v_vchItemNumber;
					SET @v_vchOldWHItemMasterID = @v_vchWHItemMasterID;

					FETCH NEXT FROM @cursorInventory into @v_vchInventoryID
														,@v_vchAttributeGroupID
														,@v_vchWHItemMasterID
														,@v_vchOwnerID
														,@v_vchLocationID
														,@v_vchParentLPN
														,@v_vchLPN
														,@v_vchLot_Number
														,@v_vchExpiry_Date
														,@v_vchSerial_Number
														,@v_fltQuantity
														,@v_vchFromInvStatusID
														,@v_vchReceiveDate
														,@v_vchOwnerCode
														,@v_vchAttribute1
														,@v_vchAttribute2
														,@v_vchAttribute3
														,@v_vchAttribute4
														,@v_vchAttribute5

				END
		
			IF (@in_vchTransactionType = 'INV_STATUS_CHANGE' AND @in_vchSubTranType = 'INV_STATUS_CHANGE' AND @v_vchMovementType IS NOT NULL)
				BEGIN
					INSERT INTO t_host_wms_interface_header(interface_id, wh_id, move_type, processing_status, user_id)
					VALUES(@v_vchHostInterfaceID,@in_vchWarehouse,@v_vchMovementType,'PENDING',@in_vchUserID)
				END
			
			CLOSE @cursorInventory;
			DEALLOCATE @cursorInventory;
			SET @out_ErrorCode = '0';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		
		COMMIT TRANSACTION

		DELETE FROM t_wms_inventory WHERE quantity <= 0 --and quantity_allocated = 0
		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
		RETURN;
		
		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = GETDATE();
				
				IF CURSOR_STATUS('global','@cursorInventory') >= -1
					BEGIN
						CLOSE @cursorInventory;
						DEALLOCATE @cursorInventory;
					END

				IF CURSOR_STATUS('global','cursorInventoryData') >= -1
					BEGIN
						CLOSE cursorInventoryData;
						DEALLOCATE cursorInventoryData;
					END

				SET @v_vchProcessData2 = 'Item number ' + @in_vchItem;
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchDescription,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
				
				RETURN;
		END	
	END TRY
	BEGIN CATCH
		IF(@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;
		IF CURSOR_STATUS('global','@cursorInventory') >= -1
			BEGIN
				CLOSE @cursorInventory;
				DEALLOCATE @cursorInventory;
			END

		IF CURSOR_STATUS('global','cursorInventoryData') >= -1
			BEGIN
				CLOSE cursorInventoryData;
				DEALLOCATE cursorInventoryData;
			END
			
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_control_for_move_back_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_control_for_move_back_order] 
	@in_vchApplicationID		NVARCHAR(40),							
	@in_vchDevice				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchTranDescription		NVARCHAR(100), 
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchOwner				NVARCHAR(40),
	@in_vchForkLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchFromLocation			NVARCHAR(50),
	@in_vchFromParentLPN		NVARCHAR(25) = NULL,
	@in_vchFromLPN				NVARCHAR(25) = NULL,
	@in_vchStatus				NVARCHAR(50) = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL, 
	@in_vchToLocation			NVARCHAR(50),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_fltQty					FLOAT = 0,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchReferenceNumber		NVARCHAR(50) = NULL,
	@in_vchReasonCode			NVARCHAR(25) = NULL,
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
						
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_inventory_control_for_move_back_order]', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(100),
			@v_vchBeginTran				BIT = 0,
			@v_vchTranType				NVARCHAR(20) = 'INV_MOVE',
			@v_vchSubTranType			NVARCHAR(20) = NULL,
			@v_vchProcessData1			NVARCHAR(255),
			@v_vchProcessData2			NVARCHAR(255),
			@v_vchProcessData3			NVARCHAR(255),
			@v_vchProcessData4			NVARCHAR(255),
			@v_dtProcessDateTime		DATETIME,
			@v_dtStartTranDate			DATETIME = GETDATE(),
			@v_dtEndTranDate			DATETIME,
			@Round						INT,
			@RulePickPack				VARCHAR(3) = NULL,

			@v_vchInventoryType			NVARCHAR(20) = 'INVENTORY',
			@v_vchHostRecordID			VARCHAR(40),
			@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL, 
			@v_vchFromLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchToLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchFromLocType			NVARCHAR(20),
			@v_vchToLPNControl			VARCHAR(5),

			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
			@v_vchBaseUOM				NVARCHAR(20), 
			@v_vchIsPrimaryUOM			NVARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,
			@v_vchLotControl			VARCHAR(5),
			@v_vchSNControl				VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5),

			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
			@v_fltInvQty				FLOAT,		--For Write Log
			@v_fltAllocatedQty			FLOAT,
			@v_fltInvQtyRemain			FLOAT = 0,
			@v_fltAfterInvQuantity		FLOAT,
			@v_fltQtyMove				FLOAT,
			@v_fltBaseTotalQtyMove		FLOAT,
			@v_dtMFGDate				DATE = NULL,
			@v_dtReceiveDate			DATE = NULL,
	
			--Item
			@v_fltWidth					FLOAT = 0,
			@v_fltLength				FLOAT = 0,
			@v_fltHeight				FLOAT = 0,
			@v_fltGrossWeight			FLOAT = 0,
			@v_intPercentTolerance		FLOAT = 0,
			@v_intPercenToleranceWeight FLOAT = 0,
			@v_fltVolumn				FLOAT = 0,	--item
			@v_fltTotalWeight			FLOAT = 0,	--item	 

			--For Interface Only
			@v_vchERPSourceLocation		NVARCHAR(50),
			@v_vchERPDestLocation		NVARCHAR(50),
			
			--For Outbound
			@v_vchOutboundOrderMasterID	UNIQUEIDENTIFIER,
			@v_vchOutboundOrderDetailID	UNIQUEIDENTIFIER,
			@v_vchOutboundOrderNumber	NVARCHAR(50),
			@v_vchLineNumber			NVARCHAR(10),
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
			@v_fltQtyRemainPlan			FLOAT,
			@v_fltQtyCanPick			FLOAT,
			@v_fltQtyBackOrder			FLOAT,
			@v_fltDisplayQtyBackOrder	FLOAT,

			@v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchStagingLocation		NVARCHAR(50) = NULL,
			@v_fltQuantityStage			FLOAT,
			@v_vchStagingParentLPN		NVARCHAR(25) = NULL,
			@v_vchStagingLPN			NVARCHAR(25) = NULL,

			@v_vchIsCheckLot			VARCHAR(3) = 'NO',
			@v_vchIsCheckExp			VARCHAR(3) = 'NO',
			@v_vchIsCheckSN				VARCHAR(3) = 'NO',
			@v_vchIsCheckAttribute1		VARCHAR(3) = 'NO',
			@v_vchIsCheckAttribute2		VARCHAR(3) = 'NO',
			@v_vchIsCheckAttribute3		VARCHAR(3) = 'NO',
			@v_vchIsCheckAttribute4		VARCHAR(3) = 'NO',
			@v_vchIsCheckAttribute5		VARCHAR(3) = 'NO',
	
			@v_fltLocTotalVolumn		FLOAT = 0,
			@v_fltLocTotalWeight		FLOAT = 0,
			@v_fltLocWidth				FLOAT = 0,
			@v_fltLocLength				FLOAT = 0,
			@v_fltLocHeight				FLOAT = 0,
			@v_fltLocGrossWeight		FLOAT = 0,
			@v_fltLocVolumn				FLOAT = 0

	-- For Serial Case ALL
	DECLARE @v_intStartIndexSN	INT  = 1
	DECLARE @v_intEndIndexSN	INT  = 0
	DECLARE @v_intInvCheck		FLOAT = 0
	DECLARE @tInventorySerial	TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] UNIQUEIDENTIFIER NOT NULL,
		[AttributeGroupID] UNIQUEIDENTIFIER NOT NULL,
		[quantity] [float] NOT NULL,
		[ReceiveDate] DATE NOT NULL,
		[MfgDate] DATE NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)

 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		-- Set Constants and Variables 
		EXEC usp_get_application_name @in_vchApplicationID, @v_vchApplicationName OUTPUT
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'

-----------------------------------------------------------------------------------
-- Validate data
-----------------------------------------------------------------------------------		
		BEGIN-- Check and Initial Data
			IF (ISNULL(@in_vchFromParentLPN,'') = N'')
				SET @in_vchFromParentLPN = NULL; 
			IF (ISNULL(@in_vchFromLPN,'') = N'')
				SET @in_vchFromLPN = NULL; 
			IF (ISNULL(@in_vchLotNumber,'') = N'') 
				SET @in_vchLotNumber = NULL;
			IF (ISNULL(@in_vchExpiryDate,'') = N'') 
				SET @in_vchExpiryDate = NULL;
			IF (ISNULL(@in_vchAttribute1,'') = N'') 
				SET @in_vchAttribute1 = NULL;
			IF (ISNULL(@in_vchAttribute2,'') = N'') 
				SET @in_vchAttribute2 = NULL;
			IF (ISNULL(@in_vchAttribute3,'') = N'')
				SET @in_vchAttribute3 = NULL; 
			IF (ISNULL(@in_vchAttribute4,'') = N'') 
				SET @in_vchAttribute4 = NULL;
			IF (ISNULL(@in_vchAttribute5,'') = N'')
				SET @in_vchAttribute5 = NULL;
			IF (ISNULL(@in_vchSerialNumber,'') = N'') 
				SET @in_vchSerialNumber = NULL; 
		END
	
		BEGIN-- Check master data
			-- get id warehouse and to warehouse
			SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
			IF(@v_vchWhMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END 
				
			-- get id owner and to owner
			SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
			IF(@v_vchOwnerID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'OWNER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOwner,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END 
						
			-- Check from location
			SELECT TOP 1 @v_vchFromLocationID = loc.location_id
				,@v_vchERPSourceLocation = loc.erp_location
				,@v_vchFromLocType = loc.loc_type
			FROM t_wms_location loc 
			WHERE loc.location = @in_vchFromLocation 
			AND loc.wh_master_id = @v_vchWhMasterID 
			AND loc.is_active = 'YES'
			IF(@v_vchFromLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

			-- Check from status
			SELECT TOP 1 @v_vchInvStatusID = inventory_status_id, @in_vchStatus = inv_status FROM t_wms_inventory_status WHERE inv_status = @in_vchStatus AND is_active = 'YES'
			IF(@v_vchInvStatusID IS NULL)
				BEGIN 
					SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchStatus,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			
			-- check warehouse item master id
			SELECT TOP 1 @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID
			IF(@v_vchItemMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

			-- check item number and item crossref and get owner
			SELECT TOP 1 @v_vchItemNumber	= item.item_number
				,@v_vchLotControl			= item.lot_control
				,@v_vchSNControl			= item.sn_control
				,@v_vchExpiryDateControl	= item.expiry_date_control
				,@v_vchAttribute1Control	= item.attribute1_control
				,@v_vchAttribute2Control	= item.attribute2_control
				,@v_vchAttribute3Control	= item.attribute3_control
				,@v_vchAttribute4Control	= item.attribute4_control
				,@v_vchAttribute5Control	= item.attribute5_control
			FROM t_wms_item item
 			WHERE item.item_master_id = @v_vchItemMasterID
			AND item.owner_id = @v_vchOwnerID
			IF (@v_vchItemNumber IS NULL)
				BEGIN
					SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
			
			--Get & Check Item UOM 
			SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUOM = uom 
				,@v_fltConversionFactor = conversion_factor
				,@v_vchIsPrimaryUOM = primary_uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND uom_prompt = @in_vchUOMPrompt	
			AND is_active = 'YES'	
			IF (@v_vchBaseItemUomID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'UOM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
					Goto WRITE_PROC
				End

			--Get Primary Uom
			IF @v_vchIsPrimaryUOM = 'NO'
				BEGIN
					SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
						,@v_vchBaseUOM = uom
						,@v_fltWidth = ISNULL(width,0)
						,@v_fltLength = ISNULL(length,0)
						,@v_fltHeight = ISNULL(height,0)
						,@v_fltGrossWeight = ISNULL(gross_weight,0)
						,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
						,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
					FROM t_wms_item_uom 
					WHERE item_master_id = @v_vchItemMasterID 
					AND primary_uom = 'YES' 
					AND is_active = 'YES'
				END
			 
			--Check SN in inventory
			IF @v_vchSNControl = 'FULL'
				BEGIN
					--Insert Serial in Inventory
					INSERT INTO @tInventorySerial
					SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
						,inventory_id
						,attribute_group_id
						,quantity
						,receive_date
						,mfg_date
						,serial_number
					FROM v_wms_inventory_data_serial_by_id WITH (NOLOCK)
					WHERE wh_master_id = @v_vchWhMasterID
					AND owner_id = @v_vchOwnerID
					AND location_id = @v_vchFromLocationID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) =  (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
					ORDER BY serial_number

					SET @v_intInvCheck = 0
					SELECT @v_intInvCheck = MAX(RowNumber) FROM @tInventorySerial
					IF ISNULL(@v_intInvCheck,0) = 0
						BEGIN
							-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
							SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
							RETURN;
						END

					--------------------------------------------------
					--Set Input Base Qty 
					-- จะต้องกำหนดจำนวน SN ทีจะจ่าย เท่ากับจำนวน Serial ทั้งหมดที่ generate ตาม SN from - To
					--------------------------------------------------
					SET @in_fltQty = @v_intInvCheck
					SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round); 
				END
			ELSE
				BEGIN
					--------------------------------------------------
					--Set Input Base Qty 
					--------------------------------------------------
					SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round); 
				END			

			-- Check to location
			SELECT @v_vchToLocationID = location_id
				,@v_vchToLPNControl = lpn_controlled
				,@v_vchERPDestLocation = erp_location
				,@v_fltLocWidth = ISNULL(width,0)
				,@v_fltLocLength = ISNULL(length,0)
				,@v_fltLocHeight = ISNULL(height,0)
				,@v_fltLocGrossWeight = ISNULL(gross_weight,0)
				,@v_fltLocTotalWeight = ISNULL(total_weight,0)
				,@v_fltLocTotalVolumn = ISNULL(total_volumn,0)
			FROM t_wms_location
			WHERE location = @in_vchToLocation
			AND wh_master_id = @v_vchWhMasterID
			AND is_active = 'YES'
			IF(@v_vchToLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END 
		END

		-------------------------------------------------
		-- GET Data From Inventory Not Control Serial
		-------------------------------------------------
		SET @v_fltInvQtyRemain	= 0 
		SET @v_fltAllocatedQty	= 0
		SET @v_fltInvQty		= 0
		SELECT @v_fltInvQty = SUM(quantity)
			,@v_fltAllocatedQty = SUM(quantity_allocated)
			,@v_fltInvQtyRemain = ROUND(SUM(quantity - ISNULL(quantity_allocated,0)),@ROUND)
		FROM v_wms_inventory_data_by_id WITH (NOLOCK)
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND location_id = @v_vchFromLocationID
		AND inventory_status_id = @v_vchInvStatusID 
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') =  ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') =  ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') =  ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') =  ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') =  ISNULL(@in_vchAttribute5,'')

		-- Quantity not enough
		IF (ROUND(@v_fltInvQtyRemain,@Round) < ROUND(@v_fltBaseInputQuantity,@Round))
			BEGIN
				IF ISNULL(@v_fltAllocatedQty,0) > 0
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
				ELSE
					SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';

				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchFromLocation,'@param3','@param4','@param5')
				GOTO WRITE_PROC;							
			END

BEGIN TRANSACTION
SET @v_vchBeginTran = 1;

	/*
	--Get Outbound Back order
	--1. ดูรายการที่ outbound detail มีการกำหนด lot, exp.  >> drop table #tOutbound
	--2. ถ้าไม่มี outbound ที่กำหนด plan ให้เอา item ตรงกัน  order by obDT.create_date 
	--3. เช็คจำนวนที่ Input จะต้องน้อยกว่าหรือเท่ากับยอดที่สามารถหยิบได้เท่านั้น เพราะมันย้ายไป outbound STG
	--4. user pick by back order
	--5. Manage inventory
	*/
	SELECT obMS.outbound_order_master_id
		,obMS.outbound_order_number
		,obDT.outbound_order_detail_id
		,obDT.line_number
		,obDT.wh_item_master_id
		,obDT.lot_number
		,obDT.expiry_date
		,obDT.serial_number
		,obDT.attribute1
		,obDT.attribute2
		,obDT.attribute3
		,obDT.attribute4
		,obDT.attribute5
		,obDT.default_item_status
		,obDT.quantity_order
		,obDT.quantity_pick
		,pickDT.quantity_plan
		,obMS.create_date 
	INTO #tOutbound
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
	LEFT JOIN (SELECT outbound_order_detail_id
					, SUM(quantity_plan) AS quantity_plan
				FROM t_wms_outbound_pick_detail WITH (NOLOCK)
				GROUP BY outbound_order_detail_id
				) pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
	WHERE obMS.wh_master_id = @v_vchWhMasterID
	AND obMS.is_back_order = 'YES'
	AND obMS.order_status NOT IN ('OPEN','SHIP','CLOSE')
	AND ROUND(obDT.quantity_ship,@Round) < ROUND(obDT.quantity_order,@Round)
	AND ROUND((obDT.quantity_order - ISNULL(pickDT.quantity_plan,0)),@Round) > 0
	AND obDT.wh_item_master_id = @in_vchWhItemMasterID
	AND obDT.default_item_status = @in_vchStatus
	
	--Check Order for Back Order
	IF NOT EXISTS (SELECT 1 FROM #tOutbound)
		BEGIN
			SET @out_ErrorCode = 'NOT_FOUND_ORDER_FOR_BACK_ORDER';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	--Get sum qty BackOrder
	SELECT @v_fltQtyBackOrder = SUM(quantity_order - ISNULL(quantity_plan,0)) FROM #tOutbound

	----Check Input Qty <> Outbound Qty จะต้อง Error
	--IF ROUND(@v_fltBaseInputQuantity,@Round) <> (SELECT ROUND(SUM(ROUND((obDT.quantity_order - ISNULL(pickDT.quantity_plan,0)),@Round)),@Round) FROM #tOutbound)
	--	BEGIN
	--		SET @out_ErrorCode = 'QTY_MORE_THAN_BACK_ORDER_QTY';
	--		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	--		GOTO WRITE_PROC;
	--	END
	
	IF @v_vchLotControl = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(lot_number,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckLot = 'YES'
				END
		END
	IF @v_vchExpiryDateControl = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(expiry_date,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckExp = 'YES'
				END
		END
	IF @v_vchAttribute1Control = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(attribute1,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckAttribute1 = 'YES'
				END
		END
	IF @v_vchAttribute2Control = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(attribute2,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckAttribute2 = 'YES'
				END
		END
	IF @v_vchAttribute3Control = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(attribute3,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckAttribute3 = 'YES'
				END
		END
	IF @v_vchAttribute4Control = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(attribute4,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckAttribute4 = 'YES'
				END
		END
	IF @v_vchAttribute5Control = 'FULL'
		BEGIN
			IF ('') NOT IN (SELECT ISNULL(attribute5,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckAttribute5 = 'YES'
				END
		END
	IF @v_vchSNControl = 'FULL'
		BEGIN
			IF EXISTS (SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_master pickMS
						INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						WHERE pickMS.outbound_order_master_id = @v_vchOutboundOrderMasterID
						AND pickDT.serial_number IN (SELECT [SerialNumber] FROM @tInventorySerial))
				BEGIN
					SET @out_ErrorCode = 'INFO-SN-DUPLICATED'
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
					RETURN;
				END

			IF ('') NOT IN (SELECT ISNULL(serial_number,'') FROM #tOutbound)		
				BEGIN
					SET @v_vchIsCheckSN = 'YES'
				END
		END

	--Check outbound plan ถ้ามีการระบุ lot, exp.
	NEXT_OUTBOUND:
		SET @v_vchOutboundOrderMasterID = NULL
		SET @v_vchOutboundOrderDetailID = NULL
		SET @v_vchOutboundOrderNumber	= NULL
		SET @v_vchLineNumber			= NULL
		SET @v_vchWhItemMasterID		= NULL
		SET @v_fltQtyRemainPlan			= NULL

		SELECT TOP 1 @v_vchOutboundOrderMasterID = obMS.outbound_order_master_id
			  ,@v_vchOutboundOrderDetailID = obDT.outbound_order_detail_id
			  ,@v_vchOutboundOrderNumber   = obMS.outbound_order_number
			  ,@v_vchLineNumber			   = obDT.line_number
			  ,@v_vchWhItemMasterID	       = obDT.wh_item_master_id
			  ,@v_fltQtyRemainPlan	       = ROUND((obDT.quantity_order - ISNULL(pickDT.quantity_plan,0)),@Round)
		FROM t_wms_outbound_master obMS WITH (NOLOCK)
		INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
		LEFT JOIN (SELECT outbound_order_detail_id
						, SUM(quantity_plan) AS quantity_plan
					FROM t_wms_outbound_pick_detail WITH (NOLOCK)
					GROUP BY outbound_order_detail_id
					) pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
		WHERE obMS.wh_master_id = @v_vchWhMasterID
		AND obMS.is_back_order = 'YES'
		AND obMS.order_status NOT IN ('OPEN','SHIP','CLOSE')
		AND ROUND(obDT.quantity_ship,@Round) < ROUND(obDT.quantity_order,@Round)
		AND ROUND((obDT.quantity_order - ISNULL(pickDT.quantity_plan,0)),@Round) > 0
		AND obDT.wh_item_master_id = @in_vchWhItemMasterID
		AND obDT.default_item_status = @in_vchStatus 
		AND ISNULL(obDT.lot_number,'')  = (CASE WHEN @v_vchIsCheckLot = 'YES'        THEN ISNULL(@in_vchLotNumber,'')	ELSE '' END)
		AND ISNULL(obDT.expiry_date,'') = (CASE WHEN @v_vchIsCheckExp = 'YES'        THEN ISNULL(@in_vchExpiryDate,'')	ELSE '' END)
		AND ISNULL(obDT.attribute1,'')  = (CASE WHEN @v_vchIsCheckAttribute1 = 'YES' THEN ISNULL(@in_vchAttribute1,'')	ELSE '' END)
		AND ISNULL(obDT.attribute2,'')  = (CASE WHEN @v_vchIsCheckAttribute2 = 'YES' THEN ISNULL(@in_vchAttribute2,'')	ELSE '' END)
		AND ISNULL(obDT.attribute3,'')  = (CASE WHEN @v_vchIsCheckAttribute3 = 'YES' THEN ISNULL(@in_vchAttribute3,'')	ELSE '' END)
		AND ISNULL(obDT.attribute4,'')  = (CASE WHEN @v_vchIsCheckAttribute4 = 'YES' THEN ISNULL(@in_vchAttribute4,'')	ELSE '' END)
		AND ISNULL(obDT.attribute5,'')  = (CASE WHEN @v_vchIsCheckAttribute5 = 'YES' THEN ISNULL(@in_vchAttribute5,'')	ELSE '' END)
		AND ISNULL(obDT.serial_number,'')  = (CASE WHEN @v_vchIsCheckSN = 'YES'		THEN ISNULL(@in_vchSerialNumber,'')	ELSE '' END)
		AND obMS.outbound_order_master_id IN (SELECT outbound_order_master_id FROM #tOutbound)
		ORDER BY obMS.outbound_order_number, obDT.line_number

		--------------------------------------------------------
		-- Validate Auto Staging Location
		-- ถ้า Outbound Order นั้นมีการวาง STG แล้วให้ยึด STG ตาม Plan แต่ถ้ายังไม่ได้มีการหยิบเลยให้ยึด STG ตาม Destination Location ที่เลือกจากหน้าจอ
		-------------------------------------------------------- 
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE pickMS.outbound_order_master_id = @v_vchOutboundOrderMasterID
			AND pickDT.staging_location_id IS NOT NULL
				
			IF @v_vchStagingLocationID IS NULL
				BEGIN
					SELECT TOP 1 @v_vchStagingLocationID = location_id
						,@v_vchStagingLocation = location 
					FROM t_wms_location 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND location = @in_vchToLocation			--Where destination location
					AND loc_type = 'STG' 
					AND is_active = 'YES' 
					IF (@v_vchStagingLocationID IS NULL)
						BEGIN
							SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC
						END
				END
		END
			 
		-- Update Outbound Master
		UPDATE t_wms_outbound_master SET
			pick_by = @in_vchUserID
			, order_status = 'PICK'
			, update_by = @in_vchUserID
			, update_date = GETDATE() 
		WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID

		-------------------------------------------------------------------------------
		-- Get Pick Master ID
		-------------------------------------------------------------------------------
		DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
		SET @v_vchOutboundPickMasterID = NULL
		SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
		IF @v_vchOutboundPickMasterID IS NULL
			BEGIN
				SET @v_vchOutboundPickMasterID = NEWID()
				INSERT INTO [dbo].[t_wms_outbound_pick_master]
						([outbound_pick_master_id]
						,[wh_master_id]
						,[outbound_order_master_id]
						,[outbound_order_number]
						,[pick_list_number]
						,[pick_list_status]
						,[create_date]
						,[create_by])
					VALUES
						(@v_vchOutboundPickMasterID
						,@v_vchWhMasterID
						,@v_vchOutboundOrderMasterID
						,@v_vchOutboundOrderNumber
						,@v_vchOutboundOrderNumber
						,'PICK' 
						,GETDATE()
						,@in_vchUserID)
			END

		DECLARE @v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchPickLineNumber		NVARCHAR(5)	 = NULL
		DECLARE @v_fltSummaryInvPick 		FLOAT = 0

		--Set จำนวนที่สามารถหยิบได้ของ Order นั้น
		IF (@v_fltQtyRemainPlan > @v_fltBaseInputQuantity)
			SET @v_fltQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
		ELSE
			SET @v_fltQtyCanPick = ROUND(@v_fltQtyRemainPlan,@Round)

		------------------------------------------------------------
		-- SET pick_to_lpn
		-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
		------------------------------------------------------------
		IF (@v_fltQtyCanPick = @v_fltInvQty AND @v_fltAllocatedQty = 0 AND ISNULL(@in_vchFromLPN,'') <> '')
			BEGIN
				SET @v_vchStagingLPN = @in_vchFromLPN
			END
		ELSE
			BEGIN
				SET @v_vchStagingLPN = @v_vchOutboundOrderNumber
			END

		IF @v_vchSNControl = 'FULL'
			BEGIN
				SET @v_fltSummaryInvPick = 0;
				--Index for get serial from - to : ต้องกำหนดเนื่องจากกันกรณีที่เป็น item เดียวกัน 2 line จะต้องแบ่งจำนวน serial 
				SET @v_intEndIndexSN = (@v_fltQtyCanPick + @v_intStartIndexSN) - 1

				--------------------------------------------------------
				-- Validate Staging Location and set value staging
				-------------------------------------------------------- 
				--Update Outbound Detail
				UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyCanPick,@Round)
					,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQtyCanPick,@Round)
					,item_status = 'PICK'
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID 
				AND outbound_order_detail_id = @v_vchOutboundOrderDetailID 
				AND wh_item_master_id = @in_vchWhItemMasterID 
				AND line_number = @v_vchLineNumber

				--SET Value Staging
				SET @v_fltQuantityStage = 1			 
				 
				IF OBJECT_ID('tempdb..#tSourceInventory') IS NOT NULL
					DROP TABLE #tSourceInventory
					
				SELECT RowNumber
					,InventoryID
					,AttributeGroupID
					,quantity
					,ReceiveDate
					,MfgDate
					,SerialNumber
				INTO #tSourceInventory
				FROM @tInventorySerial
				WHERE RowNumber BETWEEN @v_intStartIndexSN AND @v_intEndIndexSN
					
				--Set Start Index for next loop
				SET @v_intStartIndexSN = @v_intEndIndexSN + 1
					
				--Check duplicate serail in pick detail
				IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND wh_item_master_id = @in_vchWhItemMasterID AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
					BEGIN
						SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
						SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
				IF (@v_vchPickLineNumber IS NULL)
					BEGIN
						SET @v_vchPickLineNumber = '00000'; 
					END

				INSERT INTO [dbo].[t_wms_outbound_pick_detail]
						([outbound_pick_detail_id]
						,[outbound_pick_master_id]
						,[outbound_order_detail_id]
						,[pick_line_number]
						,[location_id]
						,[pick_location_id]
						,[pick_to_lpn]
						,[pick_to_parent_lpn]
						,[wh_item_master_id]
						,[quantity_plan]
						,[quantity_pick]
						,[quantity_stage]
						,[quantity_pack]
						,[quantity_load]
						,[quantity_ship]
						,[parent_lpn]
						,[lpn]
						,[lot_number]
						,[expiry_date]
						,[serial_number]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[staging_location_id]
						,[staging_parent_lpn]
						,[staging_lpn] 
						,[pick_status]
						,[load_status]
						,[ship_status]
						,[inventory_id]
						,[pack_status]
						,[pick_generate_method]
						,[is_allocate]
						,[is_override] 
						,[receive_date]
						,[mfg_date]
						,[is_active]
						,[start_date_time]
						,[end_date_time]
						,[create_date]
						,[create_by])
					SELECT NEWID()
						,@v_vchOutboundPickMasterID
						,@v_vchOutboundOrderDetailID
						, RIGHT('0000' + CONVERT(NVARCHAR,ISNULL(@v_vchPickLineNumber,0) +  ROW_NUMBER() OVER(ORDER BY SerialNumber)),5) 
						,@v_vchFromLocationID				--[location_id]
						,@v_vchStagingLocationID			--[pick_location_id]
						,@v_vchStagingLPN					--[pick_to_lpn]
						,NULL								--[pick_to_parent_lpn]
						,@in_vchWhItemMasterID
						,1	--[quantity_plan]
						,1	--[quantity_pick]
						,1	--[quantity_stage]
						,(CASE WHEN @RulePickPack = 'YES' THEN 1 ELSE 0 END)	--[quantity_pack]
						,0									--[quantity_load]
						,0									--[quantity_ship]
						,@in_vchFromParentLPN				--[parent_lpn]
						,@in_vchFromlpn						--[lpn]
						,@in_vchLotNumber					--[lot_number]
						,(CASE WHEN @in_vchExpiryDate = '' THEN NULL ELSE @in_vchExpiryDate END) --[expiry_date]
						,SerialNumber
						,@in_vchAttribute1				
						,@in_vchAttribute2
						,@in_vchAttribute3
						,@in_vchAttribute4
						,@in_vchAttribute5
						,@v_vchStagingLocationID			--[staging_location_id]
						,@v_vchStagingParentLPN				--[staging_parent_lpn]
						,@v_vchStagingLPN					--[staging_lpn]
						,'YES'								--[pick_status]
						,'NO'								--[load_status]
						,'NO'								--[ship_status]
						,InventoryID						--[inventory_id]
						,'NO'								--[pack_status]
						,'USER_PICK_ORDER'					--[pick_generate_method]
						,'YES'								--[is_allocate]
						,'NO'								--[is_override] 
						,ReceiveDate
						,MfgDate
						,'YES'								--[is_active]
						,GETDATE()							--[start_date_time]
						,GETDATE()							--[end_date_time]
						,GETDATE()							--[create_date]
						,@in_vchUserID						--[create_by])
					FROM #tSourceInventory
					ORDER BY RowNumber

				---------------------------------------------------
				--Insert/Update Pack Detail
				---------------------------------------------------
				IF @RulePickPack = 'YES'
					BEGIN
						---------------------------------------------------
						--Insert/Update Pack Detail
						---------------------------------------------------
						PRINT 'Pick and Pack' 
						IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pack_detail 
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID 
									AND pack_location_id = @in_vchForkLocationID
									AND lpn_pack = @v_vchStagingLPN 
									AND wh_item_master_id = @in_vchWhItemMasterID 
									AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
						BEGIN
							SET @out_ErrorCode = 'SERIAL_IS_PACK_COMPLETE';
							SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
								 
						INSERT INTO t_wms_outbound_pack_detail
						(     outbound_order_master_id
							, outbound_pick_detail_id
							, lpn_pack
							, pack_location_id
							, wh_item_master_id
							, quantity_pack
							, quantity_stage
							, lot_number
							, expiry_date
							, serial_number
							, [attribute1]
							, [attribute2]
							, [attribute3]
							, [attribute4]
							, [attribute5]
							, item_uom_id
							, staging_parent_lpn
							, staging_lpn
							, staging_location_id
							, create_by
							, create_date
						)
						SELECT @v_vchOutboundOrderMasterID
							, @v_vchOutboundPickDetailID
							, @v_vchStagingLPN
							, @in_vchForkLocationID
							, @in_vchWhItemMasterID
							, 1
							, @v_fltQuantityStage
							, @in_vchLotNumber
							, CASE WHEN @in_vchExpiryDate = '' THEN NULL ELSE @in_vchExpiryDate END
							, SerialNumber
							, @in_vchAttribute1
							, @in_vchAttribute2
							, @in_vchAttribute3
							, @in_vchAttribute4
							, @in_vchAttribute5
							, @v_vchBaseItemUomID
							, @v_vchStagingParentLPN
							, @v_vchStagingLPN
							, @v_vchStagingLocationID
							, @in_vchUserID
							, GETDATE()						--[create_date]
						FROM #tSourceInventory
						ORDER BY RowNumber
					END
				
				---------------------------------------------------
				--Calculate Volumn & Weight
				---------------------------------------------------
				IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
					BEGIN
						SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyCanPick,2)
						SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyCanPick,2)
					END

				--------------------------------------------
				--Manage source inventory
				--------------------------------------------
				BEGIN
					--Update Volumn & Weight in from location
					IF @v_vchFromLocationID IS NOT NULL
						BEGIN
							UPDATE [dbo].[t_wms_location]
								SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
								, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
								, update_date = GETDATE()  
								, [update_by] = @in_vchUserID   
								WHERE [location_id] = @v_vchFromLocationID
						END

					UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(inv.quantity,0) - ISNULL(tSourceInv.qty_for_pick,0),@Round)
						,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
						,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
					FROM t_wms_inventory inv
					INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON inv.inventory_id = tSourceInv.InventoryID
					WHERE inv.inventory_id = tSourceInv.InventoryID 
		
					--Inventory attribute for serial
					IF @v_vchSNControl = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT * FROM #tSourceInventory) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = tSourceInv.SerialNumber
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
						END

					--Inventory attribute for lot
					IF @v_vchLotControl = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchLotNumber
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'LOT' AND is_active = 'YES')
						END

					--Inventory attribute for EXP
					IF @v_vchExpiryDateControl = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchExpiryDate
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')
						END

					--Inventory attribute for Attribute 1
					IF @v_vchAttribute1Control = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchAttribute1
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE1' AND is_active = 'YES')
						END

					--Inventory attribute for Attribute 2
					IF @v_vchAttribute2Control = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchAttribute2
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE2' AND is_active = 'YES')
						END

					--Inventory attribute for Attribute 3
					IF @v_vchAttribute3Control = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchAttribute3
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE3' AND is_active = 'YES')
						END

					--Inventory attribute for Attribute 4
					IF @v_vchAttribute4Control = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchAttribute4
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE4' AND is_active = 'YES')
						END

					--Inventory attribute for Attribute 5
					IF @v_vchAttribute5Control = 'FULL'
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							FROM t_wms_inventory_attribute invAttr
							INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
							WHERE invAttr.inventory_id = tSourceInv.InventoryID
							AND invAttr.attribute_value = @in_vchAttribute5
							AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE5' AND is_active = 'YES')
						END
						
					DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
					DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
				END
					
				---------------------------------------------------
				--Manage destination location data
				--2019-08-19 : STG ไม่ได้คำนวณ Volumn ตอนตัดเลยไม่ได้ update volumn
				---------------------------------------------------	
				DECLARE @v_dtLoopReceiveDate		DATE = NULL
				DECLARE @v_dtLoopMfgDate			DATE = NULL
				DECLARE @v_fltLoopQtyPick			FLOAT = NULL
				DECLARE @v_vchLoopInventoryID		uniqueidentifier = NULL
				DECLARE @v_vchLoopAttributeGroupID	uniqueidentifier = NULL 
				DECLARE @v_vchLoopToLocationID		uniqueidentifier = NULL
				DECLARE @v_vchLoopToParentLPN		NVARCHAR(25) = NULL
				DECLARE @v_vchLoopToLPN				NVARCHAR(25) = NULL
				
				SET @v_vchLoopToLocationID = @v_vchStagingLocationID
				SET @v_vchLoopToParentLPN = @v_vchStagingParentLPN
				SET @v_vchLoopToLPN = @v_vchStagingLPN

				DECLARE InventoryDest_Cursor CURSOR FOR
					SELECT ReceiveDate
						,MfgDate
						,SUM(quantity)
					FROM #tSourceInventory
					GROUP BY ReceiveDate,MfgDate
				OPEN InventoryDest_Cursor
					
				FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate,@v_dtLoopMfgDate, @v_fltLoopQtyPick
	
				WHILE @@FETCH_STATUS = 0
					BEGIN 
						SET @v_vchLoopInventoryID = NULL
						SET @v_vchLoopAttributeGroupID = NULL 
						SELECT @v_vchLoopInventoryID = inventory_id
							,@v_vchLoopAttributeGroupID = attribute_group_id 
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @v_vchWhMasterID
						AND owner_id = @v_vchOwnerID
						AND location_id = @v_vchLoopToLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inventory_status_id = @v_vchInvStatusID
						and receive_date = @v_dtLoopReceiveDate
						AND ISNULL(parent_lpn,'') = ISNULL(@v_vchLoopToParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@v_vchLoopToLPN ,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
												, @in_vchOwnerID			= @v_vchOwnerID
												, @in_vchWhItemMasterID		= @in_vchWhItemMasterID
												, @in_vchLocationID			= @v_vchLoopToLocationID
												, @in_vchStatusID			= @v_vchInvStatusID
												, @in_vchPalentLPN			= @v_vchLoopToParentLPN
												, @in_vchLPN				= @v_vchLoopToLPN
												, @in_fltQty				= @v_fltLoopQtyPick
												, @in_fltQtyAllocate		= 0
												, @in_fltQtyIncoming		= 0
												, @in_vchInventoryType		= @v_vchOutboundOrderNumber
												, @in_vchUserID				= @in_vchUserID
												, @in_vchReceiveDate		= @v_dtLoopReceiveDate	
												, @in_dtMFGDate				= @v_dtLoopMfgDate
												, @in_vchInventoryID		= @v_vchLoopInventoryID OUTPUT
												, @in_vchAttributeGroupID	= @v_vchLoopAttributeGroupID OUTPUT	
												, @in_vchErrorCode			= @out_ErrorCode OUTPUT
												, @in_vchMessage			= @out_ErrorMessage OUTPUT	
						IF (@out_ErrorCode <> '0')
							GOTO WRITE_PROC;

						--Insert/Update Attribute
						IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchLoopInventoryID AND attribute_group_id = @v_vchLoopAttributeGroupID)
							BEGIN --Update 
								IF(@v_vchSNControl = 'FULL')
									BEGIN
										IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
													WHERE inventory_id = @v_vchLoopInventoryID 
													AND attribute_group_id = @v_vchLoopAttributeGroupID
													AND attribute_value IN (SELECT SerialNumber FROM #tSourceInventory WHERE ReceiveDate = @v_dtLoopReceiveDate)
													AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
											BEGIN
												SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;
											END

										--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										SELECT NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
											, @v_vchLoopAttributeGroupID
											, SerialNumber
											, 1
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID
										FROM #tSourceInventory
										WHERE ReceiveDate = @v_dtLoopReceiveDate
										ORDER BY SerialNumber 
									END
				
								IF('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN
										UPDATE t_wms_inventory_attribute SET 
												quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltLoopQtyPick,@Round),@Round) 
										WHERE inventory_id = @v_vchLoopInventoryID 
										AND attribute_group_id = @v_vchLoopAttributeGroupID
										AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
									END
							END
						ELSE
							BEGIN --Insert
								-- insert new serial
								IF(@v_vchSNControl = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											(inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										SELECT NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
											, @v_vchLoopAttributeGroupID
											, SerialNumber
											, 1
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID
										FROM #tSourceInventory
										where ReceiveDate = @v_dtLoopReceiveDate
										ORDER BY SerialNumber
									END
							
								--Insert New Lot Number
								IF(@v_vchLotControl = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
											, @v_vchLoopAttributeGroupID
											, @in_vchLotNumber
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)				
									END

								--Insert New Expiry Date
								IF(@v_vchExpiryDateControl = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
											, @v_vchLoopAttributeGroupID
											, @in_vchExpiryDate
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END

								--Insert New Attribute1
								IF(@v_vchAttribute1Control = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
											, @v_vchLoopAttributeGroupID
											, @in_vchAttribute1
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END

								--Insert New Attribute2
								IF(@v_vchAttribute2Control = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
											, @v_vchLoopAttributeGroupID
											, @in_vchAttribute2
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END

								--Insert New Attribute3
								IF(@v_vchAttribute3Control = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
											, @v_vchLoopAttributeGroupID
											, @in_vchAttribute3
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END

								--Insert New Attribute4
								IF(@v_vchAttribute4Control = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
											, @v_vchLoopAttributeGroupID
											, @in_vchAttribute4
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END

								--Insert New Attribute5
								IF(@v_vchAttribute5Control = 'FULL')
									BEGIN
										INSERT INTO t_wms_inventory_attribute
											( inv_attribute_id
											, inventory_id
											, inv_attribute_type_id
											, attribute_group_id
											, attribute_value
											, quantity
											, quantity_allocated
											, quantity_incoming
											, create_date
											, create_by)
										VALUES
											( NEWID()
											, @v_vchLoopInventoryID
											, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
											, @v_vchLoopAttributeGroupID
											, @in_vchAttribute5
											, ROUND(@v_fltLoopQtyPick,@Round)
											, 0
											, 0
											, GETDATE()
											, @in_vchUserID)
									END
							END
						 
					FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate, @v_dtLoopMfgDate, @v_fltLoopQtyPick
					END
				CLOSE InventoryDest_Cursor                  	
				DEALLOCATE InventoryDest_Cursor

				---------------------------------------------------		
				--Write Tran Log
				---------------------------------------------------	 
				INSERT INTO t_com_tran_log
					( app_id
					, [app_name]
					, tran_type
					, sub_tran_type 
					, [description]
					, start_tran_datetime
					, end_tran_datetime
					, warehouse
					, to_warehouse
					, location
					, to_location
					, [owner]
					, to_owner
					, item_number
					, quantity
					, quantity_uom
					, after_quantity
					, after_quantity_uom
					, lot_number
					, after_lot_number
					, [expiry_date]
					, after_expiry_date
					, serial_number
					, [attribute1]
					, [after_attribute1]
					, [attribute2]
					, [after_attribute2]
					, [attribute3]
					, [after_attribute3]
					, [attribute4]
					, [after_attribute4]
					, [attribute5]
					, [after_attribute5]
					, [user_id]
					, parent_lpn
					, after_parent_lpn
					, lpn
					, after_lpn
					, [status]
					, after_status
					, order_number
					, line_number
					, receive_date
					, mfg_date
					, device
					, create_by
					, create_date
					, pick_location
					, input_quantity
					, input_uom
				)
				SELECT @in_vchApplicationID
					, @v_vchApplicationName
					, 'OO_PICK'
					, 'MOVE_DEST'
					, 'Pick by Back Order (Putaway)'
					, GETDATE()
					, GETDATE()
					, @in_vchWarehouse
					, @in_vchWarehouse
					, @in_vchFromLocation
					, @v_vchStagingLocation
					, @in_vchOwner
					, @in_vchOwner
					, @v_vchItemNumber
					, 1
					, @v_vchBaseUom 
					, 0
					, @v_vchBaseUom
					, @in_vchLotNumber
					, @in_vchLotNumber
					, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
					, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
					, SerialNumber
					, @in_vchAttribute1
					, @in_vchAttribute1
					, @in_vchAttribute2
					, @in_vchAttribute2
					, @in_vchAttribute3
					, @in_vchAttribute3
					, @in_vchAttribute4
					, @in_vchAttribute4
					, @in_vchAttribute5
					, @in_vchAttribute5
					, @in_vchUserID 
					, @in_vchFromParentLPN
					, @v_vchStagingParentLPN
					, @in_vchFromLPN
					, @v_vchStagingLPN
					, @in_vchStatus
					, @in_vchStatus
					, @v_vchOutboundOrderNumber
					, @v_vchLineNumber
					, ReceiveDate
					, MfgDate
					, @in_vchDevice
					, @in_vchUserID
					, DATEADD(MILLISECOND,RowNumber * 10,GETDATE())	--[create_date]
					, @in_vchFromLocation
					, 1
					, @v_vchBaseUom
				from #tSourceInventory
				ORDER BY RowNumber

				SET @v_fltSummaryInvPick = @v_fltQtyCanPick

				--------------------------------------------------
				--Insert For Checker RFID : เฉพาะที่ AUTO STG
				--------------------------------------------------
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
					BEGIN
						IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID AND serial_number IN (SELECT SerialNumber FROM #tSourceInventory))
							BEGIN
								INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
									([checker_rfid_id]
									,[processing_status]
									,[outbound_order_master_id]
									,[serial_number]
									,[user_id]
									,[device]
									,[create_by]
									,[create_date])
								SELECT NEWID()
									,'PENDING'
									,@v_vchOutboundOrderMasterID
									,SerialNumber
									,@in_vchUserID
									,@in_vchDevice
									,@in_vchUserID
									,GETDATE()
								FROM #tSourceInventory
							END
					END
			END
		ELSE
			BEGIN
				--------------------------------------------------
				-- Inventory รายการของสินค้าจากที่หยิบมา
				--------------------------------------------------
				DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
				DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
				DECLARE @v_dtInvReceiveDate		DATE = NULL
				DECLARE @v_dtInvMfgDate			DATE = NULL
				DECLARE @v_fltInvQuantity		FLOAT = NULL
				DECLARE @v_fltInvQuantityPick	FLOAT = NULL
				SET @v_fltSummaryInvPick = 0;

				INVENTORY_NEXT:
					SET @v_vchInvID				= NULL;
					SET @v_vchInvAttrGroupID	= NULL;
					SET @v_dtInvReceiveDate	    = NULL; 
					SET @v_dtInvMfgDate		    = NULL;
					SET @v_fltInvQuantity		= NULL;
					SET @v_fltInvQuantityPick	= NULL;
				
					SELECT TOP 1 @v_vchInvID = inventory_id
						,@v_vchInvAttrGroupID = attribute_group_id
						,@v_dtInvReceiveDate = receive_date  
						,@v_dtInvMfgDate = mfg_date
						,@v_fltInvQuantity = ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round)
					FROM v_wms_inventory_data_by_id
					WHERE wh_master_id = @v_vchWhMasterID
					AND owner_id = @v_vchOwnerID
					AND location_id = @v_vchFromLocationID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round) > 0
					ORDER BY receive_date
					IF @v_vchInvID IS NULL
						BEGIN
							-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
							SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
							GOTO WRITE_PROC;
						END
			
					--Check จำนวนใน Inventory กับจำนวนที่ Pick ถ้าใน Inventory Record นี้จำนวนน้อยกว่า จำนวนที่ Pick = จำนวน Inventory
					IF (@v_fltQtyCanPick > @v_fltInvQuantity)
						BEGIN
							SET @v_fltInvQuantityPick = @v_fltInvQuantity
						END
					ELSE
						BEGIN
							SET @v_fltInvQuantityPick = @v_fltQtyCanPick
						END

					---------------------------------------------------
					-- Get Pick Detail ID
					---------------------------------------------------
					SET @v_vchOutboundPickDetailID = NULL
					SELECT @v_vchOutboundPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
					WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
					AND outbound_order_detail_id = @v_vchOutboundOrderDetailID
					AND location_id = @v_vchFromLocationID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND receive_date = @v_dtInvReceiveDate
					AND pick_location_id = @v_vchStagingLocationID
					AND ISNULL(pick_to_parent_lpn,'') = ISNULL(@v_vchStagingParentLPN,'')
					AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchStagingLPN,'')
					

					--------------------------------------------------------
					-- Validate Staging Location and set value staging
					-------------------------------------------------------- 
					UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltInvQuantityPick,@Round)
						,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltInvQuantityPick,@Round)
						,item_status = 'PICK'
						,update_by = @in_vchUserID
						,update_date = GETDATE()
					WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID 
					AND outbound_order_detail_id = @v_vchOutboundOrderDetailID 
					AND wh_item_master_id = @in_vchWhItemMasterID 
					AND line_number = @v_vchLineNumber

					--SET Value Staging
					SET @v_fltQuantityStage = ROUND(@v_fltInvQuantityPick,@Round) 						 
					 
					-----------------------------------------------------
					-- Insert/Update Pick Detail
					-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ RW to WIP
					-----------------------------------------------------
					IF @v_vchOutboundPickDetailID IS NULL
						BEGIN
							SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
							IF (@v_vchPickLineNumber IS NULL)
								BEGIN 
									SET @v_vchPickLineNumber = '00001'; 
								END
							ELSE
								BEGIN 
									SET @v_vchPickLineNumber = Right('0000' + Convert(NVARCHAR,@v_vchPickLineNumber + 1),5); 
								END				
			
							SET @v_vchOutboundPickDetailID = NEWID()
							INSERT INTO [dbo].[t_wms_outbound_pick_detail]
									([outbound_pick_detail_id]
									,[outbound_pick_master_id]
									,[outbound_order_detail_id]
									,[pick_line_number]
									,[location_id]
									,[pick_location_id]
									,[pick_to_lpn]
									,[pick_to_parent_lpn]
									,[wh_item_master_id]
									,[quantity_plan]
									,[quantity_pick] 
									,[quantity_stage]
									,[quantity_pack]
									,[quantity_load]
									,[quantity_ship] 
									,[parent_lpn]
									,[lpn]
									,[lot_number]
									,[expiry_date]
									,[serial_number]
									,[attribute1]
									,[attribute2]
									,[attribute3]
									,[attribute4]
									,[attribute5] 
									,[staging_location_id]
									,[staging_parent_lpn]
									,[staging_lpn] 
									,[pick_status]
									,[load_status]
									,[ship_status]
									,[inventory_id]
									,[pack_status]
									,[pick_generate_method]
									,[is_allocate]
									,[is_override]
									,[receive_date]
									,[mfg_date]
									,[is_active]
									,[start_date_time]
									,[end_date_time]
									,[create_date]
									,[create_by])
								VALUES
									(@v_vchOutboundPickDetailID
									,@v_vchOutboundPickMasterID
									,@v_vchOutboundOrderDetailID
									,@v_vchPickLineNumber					--[pick_line_number]
									,@v_vchFromLocationID					--[location_id]
									,@v_vchStagingLocationID				--[pick_location_id]
									,@v_vchStagingLPN						--[pick_to_lpn]
									,@v_vchStagingParentLPN					--[pick_to_parent_lpn]
									,@in_vchWhItemMasterID
									,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_plan]
									,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_pick] 
									,ROUND(@v_fltQuantityStage,@Round)		--[quantity_stage]
									,0										--[quantity_pack]
									,0										--[quantity_load]
									,0										--[quantity_ship] 
									,@in_vchFromParentLPN					--[parent_lpn]
									,@in_vchFromlpn							--[lpn]
									,@in_vchLotNumber						--[lot_number]
									,CASE WHEN @in_vchExpiryDate = '' THEN NULL ELSE @in_vchExpiryDate END	--[expiry_date]
									,NULL
									,@in_vchAttribute1				
									,@in_vchAttribute2
									,@in_vchAttribute3
									,@in_vchAttribute4
									,@in_vchAttribute5 
									,@v_vchStagingLocationID			--[staging_location_id]
									,@v_vchStagingParentLPN				--[staging_parent_lpn]
									,@v_vchStagingLPN					--[staging_lpn] 
									,'YES'								--[pick_status]
									,'NO'								--[load_status]
									,'NO'								--[ship_status]
									,@v_vchInvID						--[inventory_id]
									,'NO'								--[pack_status]
									,'USER_PICK_ORDER'					--[pick_generate_method]
									,'YES'								--[is_allocate]
									,'NO'								--[is_override] 
									,@v_dtInvReceiveDate
									,@v_dtInvMfgDate
									,'YES'								--[is_active]
									,GETDATE()							--[start_date_time]
									,GETDATE()							--[end_date_time]
									,GETDATE()							--[create_date]
									,@in_vchUserID)						--[create_by])
						END
					ELSE
						BEGIN
							UPDATE t_wms_outbound_pick_detail SET 
  									quantity_plan		 = ROUND((ISNULL(quantity_plan,0) +  @v_fltInvQuantityPick),@Round) 
								, quantity_pick		 = ROUND((ISNULL(quantity_pick,0) +  @v_fltInvQuantityPick),@Round) 
								, quantity_stage	 = ROUND((ISNULL(quantity_stage,0) + @v_fltQuantityStage),@Round)
								, pick_location_id   = @in_vchForkLocationID
								, pick_to_parent_lpn = @v_vchStagingParentLPN
								, pick_to_lpn		 = @v_vchStagingLPN
								, pick_status        = 'YES'
								, start_date_time	 = ISNULL(start_date_time,GETDATE())
								, end_date_time		 = GETDATE()
							WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
						END

					---------------------------------------------------
					--Insert/Update Pack Detail
					---------------------------------------------------
					IF @RulePickPack = 'YES'
						BEGIN
							UPDATE t_wms_outbound_pick_detail SET 
									quantity_pack = ROUND((ISNULL(quantity_pack,0) + @v_fltInvQuantityPick),@Round)
								, end_date_time = GETDATE()
							WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

							---------------------------------------------------
							--Insert/Update Pack Detail
							---------------------------------------------------
							PRINT 'Pick and Pack'
							IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
												WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
												AND pack_location_id = @in_vchForkLocationID
												AND lpn_pack = @v_vchStagingLPN 
												AND wh_item_master_id = @in_vchWhItemMasterID 
												AND outbound_pick_detail_id = @v_vchOutboundPickDetailID)
								BEGIN
									UPDATE t_wms_outbound_pack_detail SET 
											quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltInvQuantityPick,@Round)
										,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
									WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID 
									AND pack_location_id = @in_vchForkLocationID
									AND lpn_pack = @v_vchStagingLPN 
									AND wh_item_master_id = @in_vchWhItemMasterID 
									AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
								END
							ELSE
								BEGIN
									INSERT INTO t_wms_outbound_pack_detail
									(     outbound_order_master_id
										, outbound_pick_detail_id
										, lpn_pack
										, pack_location_id
										, wh_item_master_id
										, quantity_pack
										, quantity_stage
										, lot_number
										, expiry_date
										, serial_number
										, [attribute1]
										, [attribute2]
										, [attribute3]
										, [attribute4]
										, [attribute5]
										, item_uom_id
										, staging_parent_lpn
										, staging_lpn
										, staging_location_id
										, create_by
									)
									VALUES
									(     @v_vchOutboundOrderMasterID
										, @v_vchOutboundPickDetailID
										, @v_vchStagingLPN
										, @in_vchForkLocationID
										, @in_vchWhItemMasterID
										, ROUND(@v_fltInvQuantityPick,@Round)
										, @v_fltQuantityStage
										, @in_vchLotNumber
										, case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end
										, NULL
										, @in_vchAttribute1
										, @in_vchAttribute2
										, @in_vchAttribute3
										, @in_vchAttribute4
										, @in_vchAttribute5
										, @v_vchBaseItemUomID
										, @v_vchStagingParentLPN
										, @v_vchStagingLPN
										, @v_vchStagingLocationID
										, @in_vchUserID
									)
								END
						END
				
					---------------------------------------------------
					--Calculate Volumn & Weight
					---------------------------------------------------
					IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
					BEGIN
						SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltInvQuantityPick,2)
						SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltInvQuantityPick,2)
					END

					---------------------------------------------------
					-- Manage source location data
					---------------------------------------------------
					BEGIN
						--Update Volumn & Weight in from location
						IF @v_vchFromLocationID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location] SET
										total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
								WHERE [location_id] = @v_vchFromLocationID
							END

						UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
							,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
							,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
						WHERE inventory_id = @v_vchInvID 
						AND attribute_group_id = @v_vchInvAttrGroupID

						IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID
								AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END
					END

					------------------------------------------------
					-- Clear Inventory ที่หยิบของหมดแล้ว
					------------------------------------------------
					DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInvID 
					DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInvID 

					---------------------------------------------------
					-- Manage destination location data
					---------------------------------------------------			
					BEGIN
						SET @v_vchInvID = NULL
						SET @v_vchInvAttrGroupID = NULL 
						DECLARE @v_vchDestLocationID UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchDestParentLPN  NVARCHAR(25) = NULL
						DECLARE @v_vchDestLPN		 NVARCHAR(25) = NULL
						SET @v_vchDestLocationID = @v_vchStagingLocationID
						SET @v_vchDestParentLPN  = @v_vchStagingParentLPN
						SET @v_vchDestLPN		 = @v_vchStagingLPN

						SELECT @v_vchInvID = inventory_id
							,@v_vchInvAttrGroupID = attribute_group_id 
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @v_vchWhMasterID
						AND owner_id = @v_vchOwnerID
						AND location_id = @v_vchDestLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inventory_status_id = @v_vchInvStatusID
						and receive_date = @v_dtInvReceiveDate
						AND ISNULL(parent_lpn,'') = ISNULL(@v_vchDestParentLPN,'')
						AND ISNULL(lpn,'')		  = ISNULL(@v_vchDestLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

						EXEC usp_manage_inventory @in_vchWhMasterID		  = @v_vchWhMasterID
												, @in_vchOwnerID		  = @v_vchOwnerID
												, @in_vchWhItemMasterID	  = @in_vchWhItemMasterID
												, @in_vchLocationID		  = @v_vchDestLocationID 
												, @in_vchStatusID		  = @v_vchInvStatusID
												, @in_vchPalentLPN		  = @v_vchDestParentLPN
												, @in_vchLPN			  = @v_vchDestLPN 
												, @in_fltQty			  = @v_fltInvQuantityPick
												, @in_fltQtyAllocate	  = 0
												, @in_fltQtyIncoming	  = 0
												, @in_vchInventoryType	  = @v_vchOutboundOrderNumber
												, @in_vchUserID			  = @in_vchUserID
												, @in_vchReceiveDate	  = @v_dtInvReceiveDate	
												, @in_dtMfgDate			  = @v_dtInvMfgDate
												, @in_vchInventoryID	  = @v_vchInvID OUTPUT
												, @in_vchAttributeGroupID = @v_vchInvAttrGroupID OUTPUT	
												, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
												, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

						IF (@out_ErrorCode <> '0')
							GOTO WRITE_PROC;

						--Update Volumn & Weight in from location
						IF @v_vchDestLocationID IS NOT NULL  
							BEGIN
								UPDATE [dbo].[t_wms_location] SET 
										total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
									, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID 
								WHERE [location_id] = @v_vchDestLocationID
							END

						--update volumn & weight ของ LPN
						UPDATE t_wms_inventory SET 
							volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
							,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
						WHERE inventory_id = @v_vchInvID
						AND attribute_group_id = @v_vchInvAttrGroupID	

						IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
							BEGIN
								EXEC usp_manage_inventory_attribute 
										@in_vchLot				= @in_vchLotNumber
									, @in_vchExpiryDate			= @in_vchExpiryDate
									, @in_vchSerialNo			= NULL
									, @in_vchAttribute1			= @in_vchAttribute1
									, @in_vchAttribute2			= @in_vchAttribute2
									, @in_vchAttribute3			= @in_vchAttribute3
									, @in_vchAttribute4			= @in_vchAttribute4
									, @in_vchAttribute5			= @in_vchAttribute5
									, @in_fltQty				= @v_fltInvQuantityPick
									, @in_fltQtyAllocate		= 0
									, @in_fltQtyIncoming		= 0
									, @in_vchInventoryID		= @v_vchInvID
									, @in_vchAttributeGroupID	= @v_vchInvAttrGroupID
									, @in_vchLotControl			= @v_vchLotControl
									, @in_vchSNControl			= @v_vchSNControl
									, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
									, @in_vchAttribute1Control	= @v_vchAttribute1Control
									, @in_vchAttribute2Control	= @v_vchAttribute2Control
									, @in_vchAttribute3Control	= @v_vchAttribute3Control
									, @in_vchAttribute4Control	= @v_vchAttribute4Control
									, @in_vchAttribute5Control	= @v_vchAttribute5Control
									, @in_vchUserID				= @in_vchUserID
									, @in_vchErrorCode			= @out_ErrorCode OUTPUT
									, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
								IF(@out_ErrorCode <> '0')
									GOTO WRITE_PROC;
							END
					END

					---------------------------------------------------		
					--Write Tran Log OO_PICK To Staging
					---------------------------------------------------	 
					INSERT INTO t_com_tran_log
						( app_id
						, [app_name]
						, tran_type
						, sub_tran_type 
						, [description]
						, start_tran_datetime
						, end_tran_datetime
						, warehouse
						, to_warehouse
						, location
						, to_location
						, [owner]
						, to_owner
						, item_number
						, quantity
						, quantity_uom
						, after_quantity
						, after_quantity_uom
						, lot_number
						, after_lot_number
						, [expiry_date]
						, after_expiry_date
						, serial_number
						, [attribute1]
						, [after_attribute1]
						, [attribute2]
						, [after_attribute2]
						, [attribute3]
						, [after_attribute3]
						, [attribute4]
						, [after_attribute4]
						, [attribute5]
						, [after_attribute5]
						, [user_id]
						, parent_lpn
						, after_parent_lpn
						, lpn
						, after_lpn
						, [status]
						, after_status
						, order_number
						, line_number
						, receive_date
						, mfg_date
						, device
						, create_by
						, create_date
						, pick_location
						, input_quantity
						, input_uom
					)
					VALUES
					(  @in_vchApplicationID
						, @v_vchApplicationName
						, 'OO_PICK'
						, 'MOVE_DEST' 
						, 'Pick by Back Order (Putaway)'
						, GETDATE()
						, DATEADD(MILLISECOND,2,GETDATE())
						, @in_vchWarehouse
						, @in_vchWarehouse
						, @in_vchFromLocation
						, @v_vchStagingLocation
						, @in_vchOwner
						, @in_vchOwner
						, @v_vchItemNumber
						, @v_fltInvQuantityPick
						, @v_vchBaseUom
						, @v_fltInvQuantity - @v_fltInvQuantityPick
						, @v_vchBaseUom
						, @in_vchLotNumber
						, @in_vchLotNumber
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, NULL
						, @in_vchAttribute1
						, @in_vchAttribute1
						, @in_vchAttribute2
						, @in_vchAttribute2
						, @in_vchAttribute3
						, @in_vchAttribute3
						, @in_vchAttribute4
						, @in_vchAttribute4
						, @in_vchAttribute5
						, @in_vchAttribute5
						, @in_vchUserID 
						, @in_vchFromParentLPN
						, @v_vchStagingParentLPN
						, @in_vchFromLPN
						, @v_vchStagingLPN
						, @in_vchStatus
						, @in_vchStatus
						, @v_vchOutboundOrderNumber
						, @v_vchLineNumber
						, @v_dtInvReceiveDate
						, @v_dtInvMfgDate
						, @in_vchDevice
						, @in_vchUserID
						, GETDATE()	--[create_date]
						, @in_vchFromLocation
						, @v_fltInvQuantityPick
						, @v_vchBaseUom
					)
					 

				--สำหรับรวมจำนวนที่ pick ของจาก inventory ในแต่ละรอบ
				SET @v_fltSummaryInvPick = @v_fltSummaryInvPick + @v_fltInvQuantityPick

				--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
				SET @v_fltQtyCanPick = @v_fltQtyCanPick - @v_fltInvQuantityPick

				--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
				IF @v_fltQtyCanPick > 0
					GOTO INVENTORY_NEXT;
			END

		-- For Dashboard
		BEGIN 
			EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
											,@in_vchTransType	 = 'PICK'
											,@in_vchWhMasterID	 = @v_vchWhMasterID
											,@in_vchOwnerID		 = @v_vchOwnerID
											,@in_vchOwnerCode	 = @in_vchOwner
											,@in_vchLocationID	 = @v_vchFromLocationID
											,@in_vchItemMasterID = @v_vchItemMasterID
											,@in_vchInvStatusID	 = @v_vchInvStatusID
											,@in_vchToWhMasterID = @v_vchWhMasterID
											,@in_vchToLocationID = @v_vchStagingLocationID
											,@in_vchToInvStatusID = @v_vchInvStatusID
											,@in_fltQuantity	 = @v_fltSummaryInvPick
											,@in_vchUserID		 = @in_vchUserID
		END

		--For Display On screen
		SET @v_fltDisplayQtyBackOrder = ISNULL(@v_fltDisplayQtyBackOrder,0) + ISNULL(@v_fltSummaryInvPick,0)

		-------------------------------------------------------------------------------
		-- ตรวจสอบยยอดรวมที่สามารถทำ Back Order ได้
		-------------------------------------------------------------------------------
		SET @v_fltQtyBackOrder = @v_fltQtyBackOrder - @v_fltSummaryInvPick

		-------------------------------------------------------------------------------
		-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
		-------------------------------------------------------------------------------
		SET @v_fltBaseInputQuantity = @v_fltBaseInputQuantity - @v_fltSummaryInvPick
		IF ROUND(@v_fltBaseInputQuantity,@Round) > 0 AND ROUND(@v_fltQtyBackOrder,@Round) > 0
			GOTO NEXT_OUTBOUND;
			 
		COMMIT TRANSACTION;
		
		--For display on screen
		SELECT @v_fltDisplayQtyBackOrder AS backorder_qty
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS_BACKORDER',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_fltDisplayQtyBackOrder,'@param2','@param3','@param4','@param5')
		RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
				ROLLBACK TRANSACTION;
					
			SET @v_dtProcessDateTime = GETDATE(); 
			SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@in_vchFromLocation,'') + '] To Location: [' + ISNULL(@in_vchToLocation,'') + ']'
			SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
			SET  @v_vchProcessData3 = 'From Lot: ['+ ISNULL(@in_vchLotNumber,'') + '] '
			SET  @v_vchProcessData4 = 'From Exp: ['+ ISNULL(@in_vchExpiryDate,'') + '] '
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDevice,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
		END	   
		-----------------------------------------------------------------------------------	
    END TRY
    
	-----------------------------------------------------------------------------------
	-- Error Handling
	-----------------------------------------------------------------------------------    
    BEGIN CATCH
		If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
 
		SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@in_vchFromLocation,'') + '] To Location: [' + ISNULL(@in_vchToLocation,'') + ']'
		SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET  @v_vchProcessData3 = 'From Lot: ['+ ISNULL(@in_vchLotNumber,'') + '] '
		SET  @v_vchProcessData4 = 'From Exp: ['+ ISNULL(@in_vchExpiryDate,'') + '] '
		
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();	
		SET @v_dtProcessDateTime = GETDATE(); 
		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

    END CATCH
    
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_control_for_pda]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_control_for_pda] 
	@in_vchApplicationID		NVARCHAR(40),							
	@in_vchDevice				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchTranDescription		NVARCHAR(100), 
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchOwner				NVARCHAR(40),
	@in_vchFromLocation			NVARCHAR(50),
	@in_vchFromParentLPN		NVARCHAR(25) = NULL,
	@in_vchFromLPN				NVARCHAR(25) = NULL,
	@in_vchStatus				NVARCHAR(50),
	@in_vchLot					NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100) = NULL,
	@in_vchAttribute2			NVARCHAR(100) = NULL,
	@in_vchAttribute3			NVARCHAR(100) = NULL,
	@in_vchAttribute4			NVARCHAR(100) = NULL,
	@in_vchAttribute5			NVARCHAR(100) = NULL, 
	@in_vchToLocation			NVARCHAR(50),
	@in_vchToParentLPN			NVARCHAR(25) = NULL,
	@in_vchToLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_fltQty					FLOAT = 0,
	@in_vchUOMPrompt			NVARCHAR(40),
	@in_vchSerialNumber			NVARCHAR(50) = NULL,
	@in_vchReferenceNumber		NVARCHAR(50) = NULL,
	@in_vchReasonCode			NVARCHAR(25) = NULL,
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
						
AS
BEGIN
	SET XACT_ABORT ON;
	SET NOCOUNT ON;
	
	DECLARE
	 -- Error handling variables
    @c_vchObjName				NVARCHAR(50) = '[usp_inventory_control_for_pda]', -- The name that uniquely tags this object.
	@v_vchTranType				NVARCHAR(20) = 'INV_MOVE',
	@v_vchSubTranType			NVARCHAR(20) = NULL,
    @v_vchProcessData1			NVARCHAR(255),
    @v_vchProcessData2			NVARCHAR(255),
    @v_vchProcessData3			NVARCHAR(255),
    @v_vchProcessData4			NVARCHAR(255),
	@v_dtProcessDateTime		DATETIME,
	@v_dtStartTranDate			DATETIME,
	@v_dtEndTranDate			DATETIME,
    @v_vchLocal					NVARCHAR(5),
	@RuleCheckFullLPN			VARCHAR(3),
	@Round						INT,
	@v_vchBeginTran				BIT = 0,
	@v_vchInventoryType			NVARCHAR(20),
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchHostRecordID			VARCHAR(40), 

	@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
	@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL, 
	@v_vchFromLocationID		UNIQUEIDENTIFIER = NULL,
	@v_vchToLocationID			UNIQUEIDENTIFIER = NULL,
	@v_vchFromLocType			NVARCHAR(20),
	@v_vchToLPNControl			VARCHAR(5),

	@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
	@v_vchItemNumber			NVARCHAR(50) = NULL,
	@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
	@v_vchBaseUOM				NVARCHAR(20), 
	@v_vchIsPrimaryUOM			NVARCHAR(5),
	@v_fltConversionFactor		FLOAT,
	@v_fltBaseInputQuantity		FLOAT,
	@v_vchLotControl			VARCHAR(5),
    @v_vchSNControl				VARCHAR(5),
    @v_vchExpiryDateControl		VARCHAR(5),
	@v_vchAttribute1Control		VARCHAR(5),
	@v_vchAttribute2Control		VARCHAR(5),
	@v_vchAttribute3Control		VARCHAR(5),
	@v_vchAttribute4Control		VARCHAR(5),
	@v_vchAttribute5Control		VARCHAR(5),

	@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
	@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
	@v_fltInvQty				FLOAT,		--For Write Log
	@v_fltAllocatedQty			FLOAT,
	@v_fltAfterInvQuantity		FLOAT,
	@v_fltQtyMove				FLOAT,
	@v_fltBaseTotalQtyMove		FLOAT,
	@v_dtMFGDate				DATE = NULL,
	@v_dtReceiveDate			DATE = NULL,
	
	--Item
	@v_fltWidth					FLOAT = 0,
	@v_fltLength				FLOAT = 0,
	@v_fltHeight				FLOAT = 0,
	@v_fltGrossWeight			FLOAT = 0,
	@v_intPercentTolerance		FLOAT = 0,
	@v_intPercenToleranceWeight FLOAT = 0,
	@v_fltVolumn				FLOAT = 0,	--item
	@v_fltTotalWeight			FLOAT = 0,	--item	 

	--For Interface Only
	@v_vchERPSourceLocation		NVARCHAR(50),
	@v_vchERPDestLocation		NVARCHAR(50)
	
	DECLARE @v_fltLocTotalVolumn	FLOAT = 0
	DECLARE @v_fltLocTotalWeight	FLOAT = 0
	DECLARE @v_fltLocWidth			FLOAT = 0
	DECLARE @v_fltLocLength			FLOAT = 0
	DECLARE @v_fltLocHeight			FLOAT = 0
	DECLARE @v_fltLocGrossWeight	FLOAT = 0
	DECLARE @v_fltLocVolumn			FLOAT = 0

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)

 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		-- Set Constants and Variables 
		SET @v_vchInventoryType = 'INVENTORY';
		SET @v_dtStartTranDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RuleCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SET @in_fltQty = ROUND(@in_fltQty,@Round)

-----------------------------------------------------------------------------------
-- Validate data
-----------------------------------------------------------------------------------		
		BEGIN-- Check and Initial Data
			IF (ISNULL(@in_vchFromParentLPN,'') = N'')
				SET @in_vchFromParentLPN = NULL;
			IF (ISNULL(@in_vchToParentLPN,'') = N'')
				SET @in_vchToParentLPN = NULL;

			IF (ISNULL(@in_vchFromLPN,'') = N'')
				SET @in_vchFromLPN = NULL;
			IF (ISNULL(@in_vchToLPN,'') = N'')
				SET @in_vchToLPN = NULL;

			IF (ISNULL(@in_vchLot,'') = N'') 
				SET @in_vchLot = NULL;
			IF (ISNULL(@in_vchExpiryDate,'') = N'') 
				SET @in_vchExpiryDate = NULL;
			IF (ISNULL(@in_vchAttribute1,'') = N'') 
				SET @in_vchAttribute1 = NULL;
			IF (ISNULL(@in_vchAttribute2,'') = N'') 
				SET @in_vchAttribute2 = NULL;
			IF (ISNULL(@in_vchAttribute3,'') = N'')
				SET @in_vchAttribute3 = NULL; 
			IF (ISNULL(@in_vchAttribute4,'') = N'') 
				SET @in_vchAttribute4 = NULL;
			IF (ISNULL(@in_vchAttribute5,'') = N'')
				SET @in_vchAttribute5 = NULL;

			IF (ISNULL(@in_vchSerialNumber,'') = N'') 
				SET @in_vchSerialNumber = NULL;

			IF (ISNULL(@in_vchReasonCode,'') = N'')
				SET @in_vchReasonCode = NULL;
		END
	
		BEGIN-- Check master data
			-- get id warehouse and to warehouse
			SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
			IF(@v_vchWhMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchWarehouse,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END 
				
			-- get id owner and to owner
			SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
			IF(@v_vchOwnerID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'OWNER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchOwner,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END 
						
			-- Check from location
			SELECT @v_vchFromLocationID = loc.location_id
				,@v_vchERPSourceLocation = loc.erp_location
				,@v_vchFromLocType = loc.loc_type
			FROM t_wms_location loc 
			WHERE loc.location = @in_vchFromLocation 
			AND loc.wh_master_id = @v_vchWhMasterID 
			AND loc.is_active = 'YES'
			IF(@v_vchFromLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchFromLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

			-- Check from status
			SELECT @v_vchInvStatusID = inventory_status_id, @in_vchStatus = inv_status FROM t_wms_inventory_status WHERE inv_status = @in_vchStatus AND is_active = 'YES'
			IF(@v_vchInvStatusID IS NULL)
				BEGIN 
					SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchStatus,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			
			-- check warehouse item master id
			SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID
			IF(@v_vchItemMasterID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchWarehouse,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
							
			-- check item number and item crossref and get owner
			SELECT TOP 1 @v_vchItemNumber	= item.item_number
				,@v_vchLotControl			= item.lot_control
				,@v_vchSNControl			= item.sn_control
				,@v_vchExpiryDateControl	= item.expiry_date_control
				,@v_vchAttribute1Control	= item.attribute1_control
				,@v_vchAttribute2Control	= item.attribute2_control
				,@v_vchAttribute3Control	= item.attribute3_control
				,@v_vchAttribute4Control	= item.attribute4_control
				,@v_vchAttribute5Control	= item.attribute5_control
			FROM t_wms_item item
 			WHERE item.item_master_id = @v_vchItemMasterID
			AND item.owner_id = @v_vchOwnerID
			IF (@v_vchItemNumber IS NULL)
				BEGIN
					SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
			
			--Get & Check Item UOM 
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUOM = uom 
				,@v_fltConversionFactor = conversion_factor
				,@v_vchIsPrimaryUOM = primary_uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND uom_prompt = @in_vchUOMPrompt	
			AND is_active = 'YES'	
			IF (@v_vchBaseItemUomID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'UOM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
					Goto WRITE_PROC
				End

			--Get Primary Uom
			IF @v_vchIsPrimaryUOM = 'NO'
				BEGIN
					SELECT @v_vchBaseItemUomID = item_uom_id
						,@v_vchBaseUOM = uom
						,@v_fltWidth = ISNULL(width,0)
						,@v_fltLength = ISNULL(length,0)
						,@v_fltHeight = ISNULL(height,0)
						,@v_fltGrossWeight = ISNULL(gross_weight,0)
						,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
						,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
					FROM t_wms_item_uom 
					WHERE item_master_id = @v_vchItemMasterID 
					AND primary_uom = 'YES' 
					AND is_active = 'YES'
				END
			 
			--Get inventory quantity
			SELECT @v_fltInvQty = SUM(quantity)
				,@v_fltAllocatedQty = SUM(quantity_allocated)
			FROM v_wms_inventory_data_serial_by_id
			WHERE wh_master_id = @v_vchWhMasterID
			AND owner_id = @v_vchOwnerID
			AND wh_item_master_id = @in_vchWhItemMasterID 
			AND location_id = @v_vchFromLocationID 
			AND inventory_status_id = @v_vchInvStatusID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'') 
			AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) =  (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
			
			--Set Qty ให้ item ที่ Control serial และเลือก All
			IF @v_vchSNControl = 'FULL'
				BEGIN
					SET @in_fltQty = @v_fltInvQty
				END

			SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);
			SET @v_fltBaseTotalQtyMove = @v_fltBaseInputQuantity; 
			
			-- Quantity not enough
			IF (ROUND((ISNULL(@v_fltInvQty,0) - ISNULL(@v_fltAllocatedQty,0)),@Round) < ROUND(@v_fltBaseInputQuantity,@Round))
				BEGIN
					IF ISNULL(@v_fltAllocatedQty,0) > 0
						SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH_HAVE_ALLOCATE';
					ELSE
						SET @out_ErrorCode = 'QUANTITY_NOT_ENOUGH';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,@in_vchFromLocation,'@param3','@param4','@param5')
					GOTO WRITE_PROC;							
				END

			-- Check to location
			SELECT @v_vchToLocationID = loc.location_id
				,@v_vchToLPNControl = loc.lpn_controlled
				,@v_vchERPDestLocation = loc.erp_location
				,@v_fltLocWidth = ISNULL(width,0)
				,@v_fltLocLength = ISNULL(length,0)
				,@v_fltLocHeight = ISNULL(height,0)
				,@v_fltLocGrossWeight = ISNULL(gross_weight,0)
				,@v_fltLocTotalWeight = ISNULL(total_weight,0)
				,@v_fltLocTotalVolumn = ISNULL(total_volumn,0)
			FROM t_wms_location loc
			WHERE loc.location = @in_vchToLocation
			AND loc.wh_master_id = @v_vchWhMasterID
			AND loc.is_active = 'YES'
			IF(@v_vchToLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			
			--Validate To LPN
			IF @v_vchToLPNControl = 'YES' AND ISNULL(@in_vchToLPN,'') = '' AND ISNULL(@in_fltQty,0) > 0 
				BEGIN
					SET @out_ErrorCode = 'TO_LPN_CANNOT_BE_EMPTY';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;	
				END	 
				
			-- Check duplicate to parent lpn.
			IF (ISNULL(@in_vchToParentLPN,'') <> '')
				BEGIN
					DECLARE @v_vchDubLocation	NVARCHAR(50) = NULL

					SELECT TOP 1 @v_vchDubLocation = loc.location
					FROM t_wms_inventory inv
					INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
					WHERE inv.wh_master_id = @v_vchWhMasterID 
					AND ISNULL(inv.location_id,'') <> ISNULL(@v_vchToLocationID,'')
					AND inv.parent_lpn = @in_vchToParentLPN
				
					IF (ISNULL(@v_vchDubLocation,'') <> '')
						BEGIN
							SET @out_ErrorCode = 'PARENT_LPN_DUPPLICATE';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
				END
		END
-----------------------------------------------------------------------------------
-- Processing
-----------------------------------------------------------------------------------
		BEGIN TRANSACTION
		SET @v_vchBeginTran = 1;
			 
		INVENTORY_NEXT:
			SET @v_vchInventoryID = NULL
			SET @v_vchAttributeGroupID = NULL
			SET @v_fltInvQty = NULL
			SET @v_fltAllocatedQty = NULL
			SET @v_dtReceiveDate = NULL
			SET @v_dtMFGDate = NULL

			SELECT TOP 1 @v_vchInventoryID = inventory_id
				,@v_vchAttributeGroupID = attribute_group_id
				,@v_fltInvQty = quantity
				,@v_fltAllocatedQty = quantity_allocated
				,@v_dtReceiveDate = receive_date
				,@v_dtMFGDate = mfg_date
			FROM v_wms_inventory_data_by_id
			WHERE wh_master_id = @v_vchWhMasterID
			AND owner_id = @v_vchOwnerID
			AND wh_item_master_id = @in_vchWhItemMasterID 
			AND location_id = @v_vchFromLocationID 
			AND inventory_status_id = @v_vchInvStatusID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'') 
			AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
			AND ISNULL([expiry_date],'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')	
			ORDER BY receive_date
			
			IF @v_vchSNControl = 'FULL'
			BEGIN
				--Insert Serial in Inventory
				DELETE @tInventorySerial
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE inventory_id = @v_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID
				AND (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) =  (CASE WHEN ISNULL(@in_vchSerialNumber,'') = 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
				ORDER BY serial_number
			END

			IF @v_fltBaseInputQuantity > @v_fltInvQty
				SET @v_fltQtyMove = @v_fltInvQty
			ELSE
				SET @v_fltQtyMove = @v_fltBaseInputQuantity

			SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyMove,2)
			SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyMove,2)

			--------------------------------------------
			--Manage source inventory
			--------------------------------------------
			UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQtyMove,@Round) 
				,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID

			IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

			--Inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQtyMove,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END

			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
			DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
					
			--Update Volumn & Weight in from location
			IF @v_vchFromLocationID IS NOT NULL
				BEGIN
					UPDATE [dbo].[t_wms_location]
						SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
						, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
						, update_date = GETDATE()  
						, [update_by] = @in_vchUserID   
					WHERE [location_id] = @v_vchFromLocationID
				END

			--------------------------------------------
			--Check Destination Location
			--------------------------------------------
			--------------------------------------------
			-- Check LPN in another location
			--------------------------------------------
			IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id <> @v_vchToLocationID AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')) AND @v_vchToLPNControl = 'YES'
				BEGIN
					SET @out_ErrorCode = 'INFO-LPN-ANOTHER-LOCATION'
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

			--Calculate volumn & weight of LPN
			IF (@RuleCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
				BEGIN
					DECLARE @v_fltPalletID			UNIQUEIDENTIFIER = NULL
					DECLARE @v_fltPLGrossWeight		FLOAT = 0
					DECLARE @v_fltPLVolumn			FLOAT = 0
					DECLARE @v_fltInvVolumnByLPN	FLOAT = 0
					DECLARE @v_fltInvWeightByLPN	FLOAT = 0

					--Calculate Volumn & Weight of pallet
					SELECT @v_fltPalletID = pallet_id
						,@v_fltPLVolumn = ROUND(ISNULL(width,0) * ISNULL(length,0) * ISNULL(height,0),@Round)
						,@v_fltPLGrossWeight = ISNULL(gross_weight,0)
					FROM t_wms_pallet_type 
					WHERE is_active = 'YES'
				
					IF (@v_fltPalletID IS NULL)
						BEGIN
							SET @out_ErrorCode = 'PALLET_TYPE_CANNOT_BE_EMPTY';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					SELECT @v_fltInvVolumnByLPN = SUM(ISNULL(volumn_by_lpn,0))
						,@v_fltInvWeightByLPN = SUM(ISNULL(weight_by_lpn,0))
					FROM t_wms_inventory
					WHERE lpn = @in_vchToLPN

					--Volumn of qty input + volumn in inventory เทียบกับ volumn ที่กำหนด
					IF (@v_fltVolumn + ISNULL(@v_fltInvVolumnByLPN,0)) > @v_fltPLVolumn
						BEGIN
							SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LPN';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					IF (@v_fltTotalWeight + ISNULL(@v_fltInvWeightByLPN,0)) > @v_fltPLGrossWeight
						BEGIN
							SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LPN';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchToLPN,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
				END

			IF (@v_vchToLPNControl = 'NO')
				BEGIN
					SET @in_vchToLPN = NULL
				END

			--Calculate Volumn & Weight of Location
			IF (@v_fltLocWidth > 0 AND @v_fltLocLength > 0 AND @v_fltLocHeight > 0 AND @v_fltLocGrossWeight > 0)
				BEGIN
					--Calculate Volumn
					SET @v_fltLocVolumn = (@v_fltLocWidth * @v_fltLocLength * @v_fltLocHeight)
		
					--Check volumn and weight
					IF @v_fltVolumn > (@v_fltLocVolumn - @v_fltLocTotalVolumn)
						BEGIN
							SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LOCATION';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
					IF @v_fltTotalWeight > (@v_fltLocGrossWeight - @v_fltLocTotalWeight)
						BEGIN
							SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LOCATION';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
					UPDATE t_wms_location SET 
						total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
						,total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
						,update_by = @in_vchUserID
						,update_date = GETDATE()
					WHERE location_id = @v_vchToLocationID
				END

			--Check Location & Duplicate LPN & Check Capacity
			EXEC usp_location_validation_all @in_vchApplicationID		= @in_vchApplicationID
											,@in_vchUserID				= @in_vchUserID
											,@in_vchWarehouseID			= @v_vchWhMasterID		
											,@in_vchLocationID			= @v_vchToLocationID
											,@in_vchParentLPN			= @in_vchToParentLPN
											,@in_vchLPN					= @in_vchToLPN
											,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
											,@in_vchItemNumber			= @v_vchItemNumber
											,@in_vchOwnerID				= @v_vchOwnerID
											,@in_vchInventoryStatusID	= @v_vchInvStatusID
											,@in_vchLotNumber			= @in_vchLot
											,@in_vchExpiryDate			= @in_vchExpiryDate
											,@in_vchSerialNo			= 'ALL'	--ส่ง All เนื่องจาก Move ทั้งหมด
											,@in_vchAttribute1			= @in_vchAttribute1
											,@in_vchAttribute2			= @in_vchAttribute2
											,@in_vchAttribute3			= @in_vchAttribute3
											,@in_vchAttribute4			= @in_vchAttribute4
											,@in_vchAttribute5			= @in_vchAttribute5
											,@in_vchLotControl			= @v_vchLotControl			
											,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
											,@in_vchSNControl			= @v_vchSNControl			
											,@in_vchAttribute1Control	= @v_vchAttribute1Control
											,@in_vchAttribute2Control	= @v_vchAttribute2Control
											,@in_vchAttribute3Control	= @v_vchAttribute3Control
											,@in_vchAttribute4Control	= @v_vchAttribute4Control
											,@in_vchAttribute5Control	= @v_vchAttribute5Control
											,@in_ReceiveDate			= @v_dtReceiveDate		
											,@out_vchErrorCode			= @out_ErrorCode OUTPUT
											,@out_vchMessage		 	= @out_ErrorMessage OUTPUT	
			IF (@out_ErrorCode <> '0')
				GOTO WRITE_PROC;

			--------------------------------------------
			--Manage Destination inventory
			--------------------------------------------
			DECLARE @v_vchDestInventoryID UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchDestAttributeGroupID UNIQUEIDENTIFIER = NULL
			DECLARE @v_fltDestInvQty FLOAT = 0
			SELECT @v_vchDestInventoryID = inventory_id
				,@v_vchDestAttributeGroupID = attribute_group_id
				,@v_fltDestInvQty = quantity
			FROM v_wms_inventory_data_by_id
			WHERE wh_master_id = @v_vchWhMasterID
			AND owner_id = @v_vchOwnerID
			AND location_id = @v_vchToLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND inventory_status_id = @v_vchInvStatusID
			AND receive_date = @v_dtReceiveDate
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
			AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
									, @in_vchOwnerID			= @v_vchOwnerID
									, @in_vchWhItemMasterID		= @in_vchWhItemMasterID
									, @in_vchLocationID			= @v_vchToLocationID
									, @in_vchStatusID			= @v_vchInvStatusID
									, @in_vchPalentLPN			= @in_vchToParentLPN
									, @in_vchLPN				= @in_vchToLPN
									, @in_fltQty				= @v_fltQtyMove
									, @in_fltQtyAllocate		= 0
									, @in_fltQtyIncoming		= 0
									, @in_vchInventoryType		= 'INVENTORY'
									, @in_vchUserID				= @in_vchUserID
									, @in_vchReceiveDate		= @v_dtReceiveDate
									, @in_dtMFGDate				= @v_dtMFGDate
									, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
									, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
									, @in_vchErrorCode			= @out_ErrorCode OUTPUT
									, @in_vchMessage			= @out_ErrorMessage OUTPUT	
			IF (@out_ErrorCode <> '0')
				GOTO WRITE_PROC;
				  
			--Insert/Update Attribute
			IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
				BEGIN --Update 
					IF(@v_vchSNControl = 'FULL')
						BEGIN
							IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
										WHERE inventory_id = @v_vchDestInventoryID 
										AND attribute_group_id = @v_vchDestAttributeGroupID
										AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
								BEGIN
									SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
									GOTO WRITE_PROC;
								END

							--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							SELECT NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
								, @v_vchDestAttributeGroupID
								, SerialNumber
								, 1
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID
							FROM @tInventorySerial
							ORDER BY SerialNumber 
						END
				
					IF('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET 
									quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQtyMove,@Round),@Round) 
							WHERE inventory_id = @v_vchDestInventoryID 
							AND attribute_group_id = @v_vchDestAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
						END
				END
			ELSE
				BEGIN --Insert
					-- insert new serial
					IF(@v_vchSNControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								(inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							SELECT NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
								, @v_vchDestAttributeGroupID
								, SerialNumber
								, 1
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID
							FROM @tInventorySerial
							ORDER BY SerialNumber
						END
							
					--Insert New Lot Number
					IF(@v_vchLotControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
								, @v_vchDestAttributeGroupID
								, @in_vchLot
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)				
						END

					--Insert New Expiry Date
					IF(@v_vchExpiryDateControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
								, @v_vchDestAttributeGroupID
								, @in_vchExpiryDate
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute1
					IF(@v_vchAttribute1Control = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
								, @v_vchDestAttributeGroupID
								, @in_vchAttribute1
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute2
					IF(@v_vchAttribute2Control = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
								, @v_vchDestAttributeGroupID
								, @in_vchAttribute2
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute3
					IF(@v_vchAttribute3Control = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
								, @v_vchDestAttributeGroupID
								, @in_vchAttribute3
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute4
					IF(@v_vchAttribute4Control = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
								, @v_vchDestAttributeGroupID
								, @in_vchAttribute4
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute5
					IF(@v_vchAttribute5Control = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
								, @v_vchDestAttributeGroupID
								, @in_vchAttribute5
								, ROUND(@v_fltQtyMove,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END
				END

			IF (@RuleCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
			BEGIN
				--update volumn & weight ของ LPN
				UPDATE t_wms_inventory SET 
						volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
					,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
				WHERE inventory_id = @v_vchDestInventoryID
				AND attribute_group_id = @v_vchDestAttributeGroupID		
			END

			--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
			DELETE t_wms_inventory_remark
			FROM t_wms_inventory_remark invRemark
			LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
			WHERE inv.inventory_id IS NULL
				
			IF @v_vchToLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchToLocationID
			END

			-----------------------------------------------------------------------------------
			-- Write transaction log
			BEGIN
				WRITE_TRANS:							
			-----------------------------------------------------------------------------------	 
				DECLARE @v_fltAfterQty FLOAT = 0
				SET @v_fltAfterQty =  ROUND(@v_fltInvQty - @v_fltQtyMove,@Round)

				--กรณี Change Location ให้ตรวจสอบ ERP Location ต้นทางกับปลายทางตรงกันหรือไม่ถ้าตรงกันไม่ต้อง interface
				IF (ISNULL(@v_vchERPSourceLocation,'') = ISNULL(@v_vchERPDestLocation,'')) OR @v_vchFromLocType = 'UNPICK'
					BEGIN 
						SET @v_vchSubTranType = 'MOVE_ON_PC_NO_ERP'
					END
				ELSE
					BEGIN
						SET @v_vchSubTranType = 'MOVE_ON_PC'
					END 

				--Check TranType and Sub Tran Type for Interface Data
				IF ((SELECT TOP 1 host_interface_manager FROM t_com_transaction WHERE wh_id = @in_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
					BEGIN
						EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
						SET @v_dtProcessDateTime = GETDATE();
						IF @v_vchSNControl = 'NONE'
							BEGIN
								INSERT INTO [dbo].[t_host_wms_trans_export]
										([record_id]
										,[host_record_id]
										,[processing_code]
										,[processing_status]
										,[app_id]
										,[app_name]
										,[tran_type]
										,[sub_tran_type]
										,[description]
										,[start_tran_datetime]
										,[end_tran_datetime]
										,[warehouse]
										,[to_warehouse]
										,[location]
										,[to_location]
										,[owner]
										,[to_owner]
										,[item_number]
										,[quantity]
										,[quantity_uom]
										,[after_quantity]
										,[after_quantity_uom]
										,[lot_number]
										,[after_lot_number]
										,[expiry_date]
										,[after_expiry_date]
										,[serial_number]
										,[attribute1]
										,[after_attribute1]
										,[attribute2]
										,[after_attribute2]
										,[attribute3]
										,[after_attribute3]
										,[attribute4]
										,[after_attribute4]
										,[attribute5]
										,[after_attribute5]
										,[user_id]
										,[reference_number]
										,[lpn]
										,[after_lpn]
										,[status]
										,[after_status] 
										,[control_value_1]
										,[control_value_2]
										,[receive_date]
										,[mfg_date]
										,[reason_code]
										--,[user_def1] 
										,[device]
										,[create_date]
										,[create_by])
									VALUES
										(NEWID()
										,@v_vchHostRecordID
										,'ADD'  
										,'PENDING'
										,@in_vchApplicationID
										,@v_vchApplicationName
										,@v_vchTranType
										,@v_vchSubTranType
										,@in_vchTranDescription
										,@v_dtStartTranDate
										,@v_dtProcessDateTime
										,@in_vchWarehouse
										,@in_vchWarehouse	
										,@in_vchFromLocation
										,@in_vchToLocation
										,@in_vchOwner
										,@in_vchOwner
										,@v_vchItemNumber
										,@v_fltQtyMove
										,@v_vchBaseUOM
										,@v_fltAfterQty
										,@v_vchBaseUOM
										,@in_vchLot
										,@in_vchLot
										,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
										,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
										,NULL		--[serial_number]
										,@in_vchAttribute1
										,@in_vchAttribute1
										,@in_vchAttribute2
										,@in_vchAttribute2
										,@in_vchAttribute3
										,@in_vchAttribute3
										,@in_vchAttribute4
										,@in_vchAttribute4
										,@in_vchAttribute5
										,@in_vchAttribute5
										,@in_vchUserID
										,@in_vchReferenceNumber 
										,@in_vchFromLPN
										,@in_vchToLpn
										,@in_vchStatus
										,@in_vchStatus 
										,@v_vchERPSourceLocation
										,@v_vchERPDestLocation
										,@v_dtReceiveDate
										,@v_dtMfgDate
										,@in_vchReasonCode
										--,@v_vchReasonDescription 
										,@in_vchDevice
										,GETDATE()
										,@in_vchUserID)
							END
						ELSE
							BEGIN
								INSERT INTO [dbo].[t_host_wms_trans_export]
									([record_id]
									,[host_record_id]
									,[processing_code]
									,[processing_status]
									,[app_id]
									,[app_name]
									,[tran_type]
									,[sub_tran_type]
									,[description]
									,[start_tran_datetime]
									,[end_tran_datetime]
									,[warehouse]
									,[to_warehouse]
									,[location]
									,[to_location]
									,[owner]
									,[to_owner]
									,[item_number]
									,[quantity]
									,[quantity_uom]
									,[after_quantity]
									,[after_quantity_uom]
									,[lot_number]
									,[after_lot_number]
									,[expiry_date]
									,[after_expiry_date]
									,[serial_number]
									,[attribute1]
									,[after_attribute1]
									,[attribute2]
									,[after_attribute2]
									,[attribute3]
									,[after_attribute3]
									,[attribute4]
									,[after_attribute4]
									,[attribute5]
									,[after_attribute5]
									,[user_id]
									,[reference_number]
									,[lpn]
									,[after_lpn]
									,[status]
									,[after_status] 
									,[control_value_1]
									,[control_value_2]
									,[receive_date]
									,[mfg_date]
									,[reason_code]
									--,[user_def1] 
									,[device]
									,[create_date]
									,[create_by])
								SELECT NEWID()
									,@v_vchHostRecordID
									,'ADD'  
									,'PENDING'
									,@in_vchApplicationID
									,@v_vchApplicationName
									,@v_vchTranType
									,@v_vchSubTranType
									,@in_vchTranDescription
									,@v_dtStartTranDate
									,@v_dtProcessDateTime
									,@in_vchWarehouse
									,@in_vchWarehouse	
									,@in_vchFromLocation
									,@in_vchToLocation
									,@in_vchOwner
									,@in_vchOwner
									,@v_vchItemNumber
									,@v_fltQtyMove
									,@v_vchBaseUOM
									,@v_fltInvQty - RowNumber
									,@v_vchBaseUOM
									,@in_vchLot
									,@in_vchLot
									,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
									,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
									,SerialNumber
									,@in_vchAttribute1
									,@in_vchAttribute1
									,@in_vchAttribute2
									,@in_vchAttribute2
									,@in_vchAttribute3
									,@in_vchAttribute3
									,@in_vchAttribute4
									,@in_vchAttribute4
									,@in_vchAttribute5
									,@in_vchAttribute5
									,@in_vchUserID
									,@in_vchReferenceNumber 
									,@in_vchFromLPN
									,@in_vchToLpn
									,@in_vchStatus
									,@in_vchStatus 
									,@v_vchERPSourceLocation
									,@v_vchERPDestLocation
									,@v_dtReceiveDate
									,@v_dtMfgDate
									,@in_vchReasonCode
									--,@v_vchReasonDescription 
									,@in_vchDevice
									,GETDATE()
									,@in_vchUserID
								FROM @tInventorySerial 
								ORDER BY RowNumber
							END
					END

				--Write Tran Log
				SET @v_dtProcessDateTime = GETDATE(); 
				IF @v_vchSNControl = 'NONE'
					BEGIN
						INSERT INTO [dbo].[t_com_tran_log]
							([tran_id]
							,[app_id]
							,[app_name]
							,[tran_type]
							,[sub_tran_type]
							,[description]
							,[start_tran_datetime]
							,[end_tran_datetime]
							,[warehouse]
							,[to_warehouse]
							,[location]
							,[to_location]
							,[owner]
							,[to_owner]
							,[item_number]
							,[quantity]
							,[quantity_uom]
							,[after_quantity]
							,[after_quantity_uom]
							,[lot_number]
							,[after_lot_number]
							,[expiry_date]
							,[after_expiry_date]
							,[serial_number]
							,[attribute1]
							,[after_attribute1]
							,[attribute2]
							,[after_attribute2]
							,[attribute3]
							,[after_attribute3]
							,[attribute4]
							,[after_attribute4]
							,[attribute5]
							,[after_attribute5]
							,[user_id]
							,[reference_number]
							,[control_number]
							,[lpn]
							,[after_lpn]
							,[parent_lpn]
							,[after_parent_lpn]
							,[status]
							,[after_status] 
							,[control_value_1]
							,[control_value_2]
							,[reason_code] 
							,[receive_date]
							,[mfg_date]
							,[input_quantity]
							,[input_uom]
							,[device]
							,[create_date]
							,[create_by])
						VALUES
							(NEWID()
							,@in_vchApplicationID
							,@v_vchApplicationName
							,@v_vchTranType
							,@v_vchSubTranType
							,@in_vchTranDescription
							,@v_dtStartTranDate
							,@v_dtProcessDateTime
							,@in_vchWarehouse
							,@in_vchWarehouse
							,@in_vchFromLocation
							,@in_vchToLocation
							,@in_vchOwner
							,@in_vchOwner
							,@v_vchItemNumber
							,@v_fltQtyMove
							,@v_vchBaseUOM
							,@v_fltAfterQty
							,@v_vchBaseUOM
							,@in_vchLot
							,@in_vchLot
							,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
							,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
							,NULL
							,@in_vchAttribute1
							,@in_vchAttribute1
							,@in_vchAttribute2
							,@in_vchAttribute2
							,@in_vchAttribute3
							,@in_vchAttribute3
							,@in_vchAttribute4
							,@in_vchAttribute4
							,@in_vchAttribute5
							,@in_vchAttribute5
							,@in_vchUserID
							,@in_vchReferenceNumber
							,@v_vchHostRecordID
							,@in_vchFromLPN
							,@in_vchToLpn
							,@in_vchFromParentLPN
							,@in_vchToParentLpn
							,@in_vchStatus
							,@in_vchStatus 
							,@v_vchERPSourceLocation
							,@v_vchERPDestLocation
							,@in_vchReasonCode 
							,@v_dtReceiveDate
							,@v_dtMfgDate
							,@in_fltQty
							,@v_vchBaseUOM
							,@in_vchDevice
							,GETDATE()
							,@in_vchUserID) 
					END
				ELSE
					BEGIN
						INSERT INTO [dbo].[t_com_tran_log]
						   ([tran_id]
						   ,[app_id]
						   ,[app_name]
						   ,[tran_type]
						   ,[sub_tran_type]
						   ,[description]
						   ,[start_tran_datetime]
						   ,[end_tran_datetime]
						   ,[warehouse]
						   ,[to_warehouse]
						   ,[location]
						   ,[to_location]
						   ,[owner]
						   ,[to_owner]
						   ,[item_number]
						   ,[quantity]
						   ,[quantity_uom]
						   ,[after_quantity]
						   ,[after_quantity_uom]
						   ,[lot_number]
						   ,[after_lot_number]
						   ,[expiry_date]
						   ,[after_expiry_date]
						   ,[serial_number]
						   ,[attribute1]
						   ,[after_attribute1]
						   ,[attribute2]
						   ,[after_attribute2]
						   ,[attribute3]
						   ,[after_attribute3]
						   ,[attribute4]
						   ,[after_attribute4]
						   ,[attribute5]
						   ,[after_attribute5]
						   ,[user_id]
						   ,[reference_number]
						   ,[control_number]
						   ,[lpn]
						   ,[after_lpn]
						   ,[parent_lpn]
						   ,[after_parent_lpn]
						   ,[status]
						   ,[after_status] 
						   ,[control_value_1]
						   ,[control_value_2]
						   ,[reason_code] 
						   ,[receive_date]
						   ,[mfg_date]
						   ,[input_quantity]
						   ,[input_uom]
						   ,[device]
						   ,[create_date]
						   ,[create_by])
					 SELECT NEWID()
						   ,@in_vchApplicationID
						   ,@v_vchApplicationName
						   ,@v_vchTranType
						   ,@v_vchSubTranType
						   ,@in_vchTranDescription
						   ,@v_dtStartTranDate
						   ,@v_dtProcessDateTime
						   ,@in_vchWarehouse
						   ,@in_vchWarehouse
						   ,@in_vchFromLocation
						   ,@in_vchToLocation
						   ,@in_vchOwner
						   ,@in_vchOwner
						   ,@v_vchItemNumber
						   ,@v_fltQtyMove
						   ,@v_vchBaseUOM
						   ,@v_fltInvQty - RowNumber
						   ,@v_vchBaseUOM
						   ,@in_vchLot
						   ,@in_vchLot
						   ,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
						   ,(CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@in_vchExpiryDate) END)
						   ,SerialNumber
						   ,@in_vchAttribute1
						   ,@in_vchAttribute1
						   ,@in_vchAttribute2
						   ,@in_vchAttribute2
						   ,@in_vchAttribute3
						   ,@in_vchAttribute3
						   ,@in_vchAttribute4
						   ,@in_vchAttribute4
						   ,@in_vchAttribute5
						   ,@in_vchAttribute5
						   ,@in_vchUserID
						   ,@in_vchReferenceNumber
						   ,@v_vchHostRecordID
						   ,@in_vchFromLPN
						   ,@in_vchToLpn
						   ,@in_vchFromParentLPN
						   ,@in_vchToParentLpn
						   ,@in_vchStatus
						   ,@in_vchStatus
						   ,@v_vchERPSourceLocation
						   ,@v_vchERPDestLocation
						   ,@in_vchReasonCode 
						   ,@v_dtReceiveDate
						   ,@v_dtMfgDate
						   ,@in_fltQty
						   ,@v_vchBaseUOM 
						   ,@in_vchDevice
						   ,GETDATE()
						   ,@in_vchUserID
						FROM @tInventorySerial
						ORDER BY RowNumber
					END
			END	
		
		--ถ้ายังไม่ครบจำนวนที่ move ให้วนกลับไป move ที่ receipt date record ถัดไป
		SET @v_fltBaseInputQuantity = @v_fltBaseInputQuantity - @v_fltQtyMove
		IF @v_fltBaseInputQuantity > 0
			GOTO INVENTORY_NEXT;

		-- For Dashboard 
		EXEC usp_wms_dashboard_transaction @in_vchProcess	= 'OUT_IN'
									   ,@in_vchTransType	= 'MOVE'
									   ,@in_vchWhMasterID	= @v_vchWhMasterID
									   ,@in_vchOwnerID		= @v_vchOwnerID
									   ,@in_vchOwnerCode	= @in_vchOwner
									   ,@in_vchLocationID	= @v_vchFromLocationID 
									   ,@in_vchItemMasterID	= @v_vchItemMasterID
									   ,@in_vchInvStatusID	= @v_vchInvStatusID
									   ,@in_vchToWhMasterID	= @v_vchWhMasterID
									   ,@in_vchToLocationID	= @v_vchToLocationID
									   ,@in_vchToInvStatusID = @v_vchInvStatusID
									   ,@in_fltQuantity		= @v_fltBaseTotalQtyMove
									   ,@in_vchUserID		= @in_vchUserID
		 
		--20160701:Kritsada: update for get last update inventory 
		IF @v_vchToLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @v_vchToLocationID
			END

		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
				ROLLBACK TRANSACTION;
					
			SET @v_dtProcessDateTime = GETDATE(); 
			SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@in_vchFromLocation,'') + '] To Location: [' + ISNULL(@in_vchToLocation,'') + ']'
			SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
			SET  @v_vchProcessData3 = 'From Lot: ['+ ISNULL(@in_vchLot,'') + '] '
			SET  @v_vchProcessData4 = 'From Exp: ['+ ISNULL(@in_vchExpiryDate,'') + '] '
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDevice,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
		END	   
		-----------------------------------------------------------------------------------	
    END TRY
    
	-----------------------------------------------------------------------------------
	-- Error Handling
	-----------------------------------------------------------------------------------    
    BEGIN CATCH
		If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
 
		SET  @v_vchProcessData1 = 'From Location: ['+ ISNULL(@in_vchFromLocation,'') + '] To Location: [' + ISNULL(@in_vchToLocation,'') + ']'
		SET  @v_vchProcessData2 = 'Item Number ' + @v_vchItemNumber
		SET  @v_vchProcessData3 = 'From Lot: ['+ ISNULL(@in_vchLot,'') + '] '
		SET  @v_vchProcessData4 = 'From Exp: ['+ ISNULL(@in_vchExpiryDate,'') + '] '
		
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();	
		SET @v_dtProcessDateTime = GETDATE(); 
		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

    END CATCH
    
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_for_move_all]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_for_move_all]
	@in_vchApplicationID		NVARCHAR(40),							
	@in_vchDevice				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchTransactionType		NVARCHAR(20),
	@in_vchSubTranType			NVARCHAR(20) = NULL,
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchOwner				NVARCHAR(40),
	@in_vchAllParentLPN			NVARCHAR(3)	  = NULL,	
	@in_vchAllLPN				NVARCHAR(3)	  = NULL,	
	@in_vchAllItem				NVARCHAR(3)	  = NULL,	
	@in_vchAllLot				NVARCHAR(3)	  = NULL,	
	@in_vchAllExpiryDate		NVARCHAR(3)	  = NULL,	
	@in_vchAllSerial			NVARCHAR(3)	  = NULL,	
	@in_vchFromLocation			NVARCHAR(50)  = NULL,	
	@in_vchToLocation			NVARCHAR(50)  = NULL,	
	@in_vchFromParentLPN		NVARCHAR(25)  = NULL,	
	@in_vchToParentLPN			NVARCHAR(25)  = NULL,	
	@in_vchFromLPN				NVARCHAR(25)  = NULL,	
	@in_vchToLPN				NVARCHAR(25)  = NULL,	
	@in_vchFromStatus			NVARCHAR(50)  = NULL,	
	@in_vchToStatus				NVARCHAR(50)  = NULL,	
	@in_vchItemNumber			NVARCHAR(50)  = NULL,	
	@in_vchLotNumber			NVARCHAR(50)  = NULL,	
	@in_vchExpiryDate			NVARCHAR(50)  = NULL,
	@in_vchAttribute1			NVARCHAR(100)  = NULL,
	@in_vchAttribute2			NVARCHAR(100)  = NULL,
	@in_vchAttribute3			NVARCHAR(100)  = NULL,
	@in_vchAttribute4			NVARCHAR(100)  = NULL,
	@in_vchAttribute5			NVARCHAR(100)  = NULL,
	@in_vchSerialNumber			NVARCHAR(100)  = NULL,
	@in_vchReasonCode			NVARCHAR(20)  = NULL,	
	@out_ErrorCode				NVARCHAR(200) OUTPUT,	
	@out_ErrorMessage			NVARCHAR(500) OUTPUT	 
AS
BEGIN
	SET NOCOUNT ON;
   
	DECLARE
	 -- Error handling variables
    @c_vchObjName				NVARCHAR(30), -- The name that uniquely tags this object.
    @v_intSqlErrorNumber		INTEGER,
    @v_intSqlErrorState			INTEGER,
    @v_intSqlErrorSeverity		INTEGER,
    @v_vchSqlErrorMessage		NVARCHAR(1000),
    @v_vchSqlErrorProcedure		NVARCHAR(200),
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
	@v_dtProcessDateTime		DATETIME,
	@Round						INT,
	@v_vchBeginTran				BIT = 0,
	@v_vchLocal					VARCHAR(10),
	@v_vchInventoryID			VARCHAR(40),
	@v_vchFromLocation			NVARCHAR(50),
	@v_vchFromParentLPN			NVARCHAR(25),
	@v_vchFromLPN				NVARCHAR(25),
	@v_vchFromStatus			NVARCHAR(50),
	@v_vchItemNumber			NVARCHAR(50),
	@v_vchLotNumber				NVARCHAR(50) = NULL,
	@v_vchExpiryDate			NVARCHAR(50) = NULL,
	@v_vchAttribute1			NVARCHAR(100)= NULL,
	@v_vchAttribute2			NVARCHAR(100)= NULL,
	@v_vchAttribute3			NVARCHAR(100)= NULL,
	@v_vchAttribute4			NVARCHAR(100)= NULL,
	@v_vchAttribute5			NVARCHAR(100)= NULL,
	@v_vchSerialNumber			NVARCHAR(100),
	@v_vchReceiveDate			DATE,
	@v_fltQty					FLOAT = 0,
	@v_vchUOMPrompt				NVARCHAR(40),
	
	@v_vchWhMasterID			varchar(40),
	@v_vchOwnerID				varchar(40),
	@v_vchFromStatusID			varchar(40),			
	@v_vchFromLocationID		varchar(40)

	-----------------------------------------------------------------------------------	
	-- Begin
	-----------------------------------------------------------------------------------	   
    BEGIN TRY
		-- Set Constants and Variables
		SET @c_vchObjName = 'usp_inventory_for_move';
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
		SELECT @v_vchFromStatusID = inventory_status_id from t_wms_inventory_status where inv_status = @in_vchFromStatus AND is_active = 'YES'
		SELECT @v_vchFromLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchFromLocation AND is_active = 'YES'
		IF @in_vchToParentLPN = '' 
			SET @in_vchToParentLPN = NULL
		IF @in_vchToLPN = '' 
			SET @in_vchToLPN = NULL
		
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;

		DECLARE InventoryCursor CURSOR FOR
		--Get inventory
		SELECT inventory_id  
			,location
			,parent_lpn
			,lpn
			,inv_status
			,item_number
			,quantity
			,uom_prompt
			,lot_number
			,expiry_date
			,attribute1
			,attribute2
			,attribute3
			,attribute4
			,attribute5
			,serial_number
			,receive_date
		FROM v_wms_inventory_data_by_serial
		WHERE wh_master_id = @v_vchWhMasterID 
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchFromLocationID 
		AND inventory_status_id = @v_vchFromStatusID
		AND (CASE ISNULL(@in_vchAllParentLPN,'') WHEN 'ALL' THEN '' ELSE ISNULL(parent_lpn,'') END) = (CASE ISNULL(@in_vchAllParentLPN,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchAllParentLPN,'') END)
		AND (CASE ISNULL(@in_vchAllLPN,'') WHEN 'ALL' THEN '' ELSE ISNULL(lpn,'') END) = (CASE ISNULL(@in_vchAllLPN,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchFromLPN,'') END)
		AND (CASE ISNULL(@in_vchAllItem,'') WHEN 'ALL' THEN '' ELSE ISNULL(item_number,'') END) = (CASE ISNULL(@in_vchAllItem,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchItemNumber,'') END)
		AND (CASE ISNULL(@in_vchAllLot,'') WHEN 'ALL' THEN '' ELSE ISNULL(lot_number,'') END) = (CASE ISNULL(@in_vchAllLot,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchLotNumber,'') END)
		AND (CASE ISNULL(@in_vchAllExpiryDate,'') WHEN 'ALL' THEN '' ELSE ISNULL(expiry_date,'') END) = (CASE ISNULL(@in_vchAllExpiryDate,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END)
		AND (CASE ISNULL(@in_vchAllSerial,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@in_vchAllSerial,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		OPEN InventoryCursor
		FETCH NEXT FROM InventoryCursor INTO @v_vchInventoryID,@v_vchFromLocation,@v_vchFromParentLPN,@v_vchFromLPN,@v_vchFromStatus,@v_vchItemNumber,@v_fltQty,@v_vchUOMPrompt,
											@v_vchLotNumber,@v_vchExpiryDate,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_vchSerialNumber,@v_vchReceiveDate
		WHILE @@FETCH_STATUS = 0
		BEGIN
			EXEC usp_inventory_for_move @in_vchApplicationID		= @in_vchApplicationID
									   ,@in_vchDevice				= @in_vchDevice
									   ,@in_vchUserID				= @in_vchUserID
									   ,@in_vchTransactionType		= @in_vchTransactionType	
									   ,@in_vchSubTranType			= @in_vchSubTranType		
									   ,@in_vchWarehouse			= @in_vchWarehouse
									   ,@in_vchOwner				= @in_vchOwner
									   ,@in_vchFromLocation			= @v_vchFromLocation
									   ,@in_vchFromParentLPN		= @v_vchFromParentLPN
									   ,@in_vchFromLPN				= @v_vchFromLPN
									   ,@in_vchFromStatus			= @v_vchFromStatus
									   ,@in_vchFromLot				= @v_vchLotNumber
									   ,@in_vchFromExpiryDate		= @v_vchExpiryDate
									   ,@in_vchFromAttribute1		= @v_vchAttribute1
									   ,@in_vchFromAttribute2		= @v_vchAttribute2
									   ,@in_vchFromAttribute3		= @v_vchAttribute3
									   ,@in_vchFromAttribute4		= @v_vchAttribute4
									   ,@in_vchFromAttribute5		= @v_vchAttribute5
									   ,@in_vchFromReceiveDate		= @v_vchReceiveDate
									   ,@in_vchToWarehouse			= @in_vchWarehouse
									   ,@in_vchToOwner				= @in_vchOwner
									   ,@in_vchToLocation			= @in_vchToLocation
									   ,@in_vchToParentLPN			= @in_vchToParentLPN
									   ,@in_vchToLPN				= @in_vchToLPN
									   ,@in_vchToStatus				= @in_vchToStatus
									   ,@in_vchToLot				= @v_vchLotNumber
									   ,@in_vchToExpiryDate			= @v_vchExpiryDate
									   ,@in_vchToAttribute1			= @v_vchAttribute1
									   ,@in_vchToAttribute2			= @v_vchAttribute2
									   ,@in_vchToAttribute3			= @v_vchAttribute3
									   ,@in_vchToAttribute4			= @v_vchAttribute4
									   ,@in_vchToAttribute5			= @v_vchAttribute5
									   ,@in_vchItemNumber			= @v_vchItemNumber
									   ,@in_fltQty					= @v_fltQty
									   ,@in_vchUOMPrompt			= @v_vchUOMPrompt
									   ,@in_vchSerialNumber			= @v_vchSerialNumber
									   ,@in_vchReasonCode			= @in_vchReasonCode
									   ,@out_ErrorCode				= @out_ErrorCode    OUTPUT
									   ,@out_ErrorMessage			= @out_ErrorMessage	OUTPUT
			IF (@out_ErrorCode <> '0')
				GOTO WRITE_PROC;

			FETCH NEXT FROM InventoryCursor INTO @v_vchInventoryID,@v_vchFromLocation,@v_vchFromParentLPN,@v_vchFromLPN,@v_vchFromStatus,@v_vchItemNumber,@v_fltQty,@v_vchUOMPrompt,
											@v_vchLotNumber,@v_vchExpiryDate,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_vchSerialNumber,@v_vchReceiveDate
		END	  
	       
		CLOSE InventoryCursor                  	
		DEALLOCATE InventoryCursor
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')

		COMMIT TRANSACTION;
		RETURN;

	---------------------------------------------------------------------------
	-- Write process log
	---------------------------------------------------------------------------
	BEGIN
		WRITE_PROC:							
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
				ROLLBACK TRANSACTION;

			IF CURSOR_STATUS('global','InventoryCursor')>=-1
			BEGIN
				CLOSE InventoryCursor;
				DEALLOCATE InventoryCursor;
			END

			SET @v_vchProcessData1 = @out_ErrorMessage;
			SET @v_dtProcessDateTime = GETDATE();
			SET @v_vchProcessData2 = 'Item number ' + @in_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDevice,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END
	END TRY
	-----------------------------------------------------------------------------------
	-- Error Handling
	-----------------------------------------------------------------------------------    
    BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
			
		IF CURSOR_STATUS('global','InventoryCursor')>=-1
			BEGIN
				CLOSE InventoryCursor;
				DEALLOCATE InventoryCursor;
			END

		SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
		       @v_vchSqlErrorMessage = ERROR_MESSAGE(),
		       @v_intSqlErrorState = ERROR_STATE(),
			   @v_intSqlErrorSeverity = ERROR_SEVERITY(),
			   @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @out_ErrorMessage = @v_vchSqlErrorProcedure + ': ' + @out_ErrorMessage 
							+ '. SQL Error ['+ str(@v_intSqlErrorNumber) + '], '
							+ '. Severity ['+ str(@v_intSqlErrorSeverity) + '],'
							+ '. State ['+ str(@v_intSqlErrorState) + ']'

		IF(ISNULL(@out_ErrorMessage,'') = '')
			SET @out_ErrorMessage = 'SQL Error';

		SET  @v_vchProcessData1 = @out_ErrorMessage;
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage;
		SET  @v_vchProcessData3 = 'Item number ' + @in_vchItemNumber;
		SET  @v_vchProcessData4 = 'To Location ' + @in_vchToLocation;
		
		SET @out_ErrorCode = @v_intSqlErrorNumber;
		SET @out_ErrorMessage = @v_vchSqlErrorMessage;
		
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchSqlErrorMessage = SUBSTRING(@v_vchSqlErrorMessage,0,100);
		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDevice,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @v_intSqlErrorNumber,
			@in_vchMessage = @v_vchSqlErrorMessage
			
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_for_move_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_for_move_lpn] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchLPN				NVARCHAR(25),
	@in_vchToLocationID		UNIQUEIDENTIFIER,
	@in_vchToParentLPN		NVARCHAR(25),
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_for_move_lpn]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_bitBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_MOVE'
	DECLARE @v_vchSubTranType		NVARCHAR(20)
	DECLARE @v_vchRuleCheckFullLPN	VARCHAR(50) = NULL
	DECLARE @v_vchReasonCode		NVARCHAR(50) = NULL 

	DECLARE @v_vchWarehouse			NVARCHAR(25) = NULL,
			@v_vchOwner				NVARCHAR(40) = NULL,
			@v_vchToLocation		NVARCHAR(50),
			@v_vchToLPNControl		VARCHAR(5),
			@v_fltToCapacity		FLOAT = 0,
			@v_vchToMixOwners		VARCHAR(3),
			@v_vchToMixStatus		VARCHAR(3),
			@v_vchToMixItems		VARCHAR(3),
			@v_vchToMixLot			VARCHAR(3),
			@v_vchToMixExpiryDates	VARCHAR(3),
			@v_vchToMixAttribute1	VARCHAR(3),
			@v_vchToMixAttribute2	VARCHAR(3),
			@v_vchToMixAttribute3	VARCHAR(3),
			@v_vchToMixAttribute4	VARCHAR(3),
			@v_vchToMixAttribute5	VARCHAR(3),
			@v_vchERPDestLocation	NVARCHAR(50),
			@v_vchToLPN				NVARCHAR(25)

	--For Loop
	DECLARE @v_vchInventoryID			UNIQUEIDENTIFIER,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER, 
			@v_vchSourceLocationID		UNIQUEIDENTIFIER,
			@v_vchSourceLocation		NVARCHAR(50),
			@v_vchSourceLocType			NVARCHAR(20),
			@v_vchERPSourceLocation		NVARCHAR(50),
			@v_vchParentLPN				NVARCHAR(25),
			@v_vchLpn					NVARCHAR(25),
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
			@v_vchItemMasterID			UNIQUEIDENTIFIER,
			@v_vchItemNumber			NVARCHAR(50),
			@v_fltQuantity				FLOAT, 
			@v_vchInventoryStatusID		UNIQUEIDENTIFIER,
			@v_vchInvStatus				NVARCHAR(50),
			@v_vchLotNumber				NVARCHAR(50),
			@v_vchExpiryDate 			NVARCHAR(50),
			@v_vchAttribute1			NVARCHAR(100),
			@v_vchAttribute2			NVARCHAR(100),
			@v_vchAttribute3			NVARCHAR(100),
			@v_vchAttribute4			NVARCHAR(100),
			@v_vchAttribute5			NVARCHAR(100),
			@v_dtReceiveDate			DATE,
			@v_dtMfgDate				DATE,
			@v_vchLotControl			VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchSNControl				VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5),

			--Item
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUOM				NVARCHAR(20),
			@v_fltWidth					FLOAT = 0,
			@v_fltLength				FLOAT = 0,
			@v_fltHeight				FLOAT = 0,
			@v_fltGrossWeight			FLOAT = 0,
			@v_intPercentTolerance		FLOAT = 0,
			@v_intPercenToleranceWeight FLOAT = 0,
			@v_fltVolumn				FLOAT = 0,	--item
			@v_fltTotalWeight			FLOAT = 0	--item	 

	--Location
	DECLARE @v_fltLocTotalVolumn		FLOAT = 0,
			@v_fltLocTotalWeight		FLOAT = 0,
			@v_fltLocWidth				FLOAT = 0,
			@v_fltLocLength				FLOAT = 0,
			@v_fltLocHeight				FLOAT = 0,
			@v_fltLocGrossWeight		FLOAT = 0,
			@v_fltLocVolumn				FLOAT = 0

	--For Serial
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] [varchar] (40) NOT NULL,
		[AttributeGroupID] [varchar] (40) NOT NULL,
		[quantity] [float] NOT NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchRuleCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT TOP 1 @v_vchReasonCode = reason_code FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID  AND is_active = 'YES'
		SELECT TOP 1 @v_vchOwner = owner_code FROM t_wms_owner where owner_id = @in_vchOwnerID  AND is_active = 'YES'
		 
		--Check Inventory
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lpn = @in_vchLPN)
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--Check Allocate Qty
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lpn = @in_vchLPN AND ISNULL(quantity_allocated,0) > 0)
			BEGIN
				SET @out_ErrorCode = 'INV_HAVE_ALLOCATE_CANNOT_CHANGE';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--------------------------------------------
		--Validate Destination Location
		--------------------------------------------
		SET @v_vchToLocation = NULL
		SELECT @v_vchToLocation = location
			, @v_vchERPDestLocation = erp_location
			, @v_vchToLPNControl = lpn_controlled
			, @v_vchToMixOwners = mix_owners
			, @v_vchToMixStatus = mix_status
			, @v_vchToMixItems = mix_items
			, @v_vchToMixLot = mix_lot 
			, @v_vchToMixExpiryDates = mix_expiry_dates 
			, @v_vchToMixAttribute1	= mix_attribute1
			, @v_vchToMixAttribute2	= mix_attribute2
			, @v_vchToMixAttribute3	= mix_attribute3
			, @v_vchToMixAttribute4	= mix_attribute4
			, @v_vchToMixAttribute5	= mix_attribute5
			, @v_fltToCapacity = capacity_qty
			, @v_fltLocWidth = ISNULL(width,0)
			, @v_fltLocLength = ISNULL(length,0)
			, @v_fltLocHeight = ISNULL(height,0)
			, @v_fltLocGrossWeight = ISNULL(gross_weight,0)
			, @v_fltLocTotalWeight = ISNULL(total_weight,0)
			, @v_fltLocTotalVolumn = ISNULL(total_volumn,0)
		FROM t_wms_location 
		WHERE wh_master_id = @in_vchWhMasterID 
		AND location_id = @in_vchToLocationID
		AND is_active = 'YES'
		IF(@v_vchToLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Check Mix of Source Location and Destination Location : ถ้าปลายทางมีของถึงจะ Check 
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND owner_id = @in_vchOwnerID)
			BEGIN
				IF OBJECT_ID('tempdb..#tempInv') IS NOT NULL
					DROP TABLE #tempInv
				SELECT * 
				INTO #tempInv
				FROM (SELECT tInv.wh_master_id
							,tInv.owner_id
							,tInv.location_id
							,tInv.wh_item_master_id
							,tInv.inventory_status_id
							,invLot.lot_number
							,invExp.expiry_date
							,invAttribute1.attribute1
							,invAttribute2.attribute2
							,invAttribute3.attribute3
							,invAttribute4.attribute4
							,invAttribute5.attribute5
							,invSN.serial_number
						FROM (SELECT inventory_id
								,attribute_group_id
								,wh_master_id
								,owner_id
								,location_id
								,wh_item_master_id
								,inventory_status_id
							  FROM t_wms_inventory --v_wms_inventory_data_serial_by_id
							  WHERE wh_master_id = @in_vchWhMasterID 
							  AND owner_id = @in_vchOwnerID 
							  AND lpn = @in_vchLPN 
							  ) tInv
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70') AS invLot ON tInv.inventory_id = invLot.inventory_id AND tInv.attribute_group_id = invLot.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248') AS invExp ON tInv.inventory_id = invExp.inventory_id AND tInv.attribute_group_id = invExp.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714') AS invAttribute1 ON tInv.inventory_id = invAttribute1.inventory_id AND tInv.attribute_group_id = invAttribute1.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A') AS invAttribute2 ON tInv.inventory_id = invAttribute2.inventory_id AND tInv.attribute_group_id = invAttribute2.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526') AS invAttribute3 ON tInv.inventory_id = invAttribute3.inventory_id AND tInv.attribute_group_id = invAttribute3.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580') AS invAttribute4 ON tInv.inventory_id = invAttribute4.inventory_id AND tInv.attribute_group_id = invAttribute4.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE') AS invAttribute5 ON tInv.inventory_id = invAttribute5.inventory_id AND tInv.attribute_group_id = invAttribute5.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id,attribute_group_id,attribute_value AS serial_number 
									    FROM dbo.t_wms_inventory_attribute
									    WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8') AS invSN ON tInv.inventory_id = invSN.inventory_id AND tInv.attribute_group_id = invSN.attribute_group_id

						UNION  
						SELECT	tInv.wh_master_id				--wh_master_id
							, tInv.owner_id						--owner_id
							, tInv.location_id					--location_id
							, tInv.wh_item_master_id			--wh_item_master_id
							, tInv.inventory_status_id			--inventory_status_id
							, invLot.lot_number					--lot_number
							, invExp.expiry_date				--expiry_date
							, invAttribute1.attribute1			--attribute1
							, invAttribute2.attribute2			--attribute2
							, invAttribute3.attribute3			--attribute3
							, invAttribute4.attribute4			--attribute4
							, invAttribute5.attribute5			--attribute5
							, invSN.serial_number				--serial_number
						FROM (SELECT inventory_id
								,attribute_group_id
								,wh_master_id
								,owner_id
								,location_id
								,wh_item_master_id
								,inventory_status_id
							   FROM dbo.t_wms_inventory	--v_wms_inventory_data_serial_by_id
							   WHERE wh_master_id = @in_vchWhMasterID
							   AND location_id = @in_vchToLocationID
							  ) tInv
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70') AS invLot ON tInv.inventory_id = invLot.inventory_id AND tInv.attribute_group_id = invLot.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248') AS invExp ON tInv.inventory_id = invExp.inventory_id AND tInv.attribute_group_id = invExp.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714') AS invAttribute1 ON tInv.inventory_id = invAttribute1.inventory_id AND tInv.attribute_group_id = invAttribute1.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A') AS invAttribute2 ON tInv.inventory_id = invAttribute2.inventory_id AND tInv.attribute_group_id = invAttribute2.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526') AS invAttribute3 ON tInv.inventory_id = invAttribute3.inventory_id AND tInv.attribute_group_id = invAttribute3.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580') AS invAttribute4 ON tInv.inventory_id = invAttribute4.inventory_id AND tInv.attribute_group_id = invAttribute4.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
										FROM dbo.t_wms_inventory_attribute
										WHERE inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE') AS invAttribute5 ON tInv.inventory_id = invAttribute5.inventory_id AND tInv.attribute_group_id = invAttribute5.attribute_group_id 
						LEFT OUTER JOIN (SELECT inventory_id,attribute_group_id,attribute_value AS serial_number 
									    FROM dbo.t_wms_inventory_attribute
									    WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8') AS invSN ON tInv.inventory_id = invSN.inventory_id AND tInv.attribute_group_id = invSN.attribute_group_id

					) t

				-- Check to location is mix owner?
				IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND owner_id <> @in_vchOwnerID) AND (@v_vchToMixOwners = 'NO')
					BEGIN
						SET @out_ErrorCode = 'LOCATION_NOT_MIX_OWNER';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
		
				-- check to location is mix item?
				IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND wh_item_master_id NOT IN (SELECT wh_item_master_id FROM #tempInv)) AND @v_vchToMixItems = 'NO'
					BEGIN
						SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ITEM';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END

				-- check location is mix Status?
				IF EXISTS(SELECT inventory_status_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND inventory_status_id NOT IN (SELECT inventory_status_id FROM #tempInv)) AND @v_vchToMixStatus = 'NO'
					BEGIN
						SET @out_ErrorCode = 'LOCATION_NOT_MIX_STATUS';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
	 
				-- check to location is mix lot?
				IF @v_vchToMixLot = 'NO' AND ((SELECT COUNT(DISTINCT lot_number) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_LOT';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix expiry date?
				IF @v_vchToMixExpiryDates = 'NO' AND ((SELECT COUNT(DISTINCT [expiry_date]) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_EXPIRY_DATE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute1?
				IF @v_vchToMixAttribute1 = 'NO' AND ((SELECT COUNT(DISTINCT attribute1) FROM #tempInv) > 1) 
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE1';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
		 
				-- check location is mix attribute2?
				IF @v_vchToMixAttribute2 = 'NO' AND ((SELECT COUNT(DISTINCT attribute2) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE2';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute3?
				IF @v_vchToMixAttribute3 = 'NO' AND ((SELECT COUNT(DISTINCT attribute3) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE3';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute4?
				IF @v_vchToMixAttribute4 = 'NO' AND ((SELECT COUNT(DISTINCT attribute4) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE4';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute5?
				IF @v_vchToMixAttribute5 = 'NO'AND ((SELECT COUNT(DISTINCT attribute5) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE5';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END

		-- check capacity
		IF (@v_fltToCapacity > 0)
			BEGIN
				IF ((SELECT COUNT(DISTINCT lpn) + 1 FROM t_wms_inventory WHERE location_id = @in_vchToLocationID AND (lpn <> @in_vchLPN AND ISNULL(lpn,'') <> '')) > @v_fltToCapacity)
					BEGIN
						SET @out_ErrorCode = 'LOCATION_IS_FULL_CAPACITY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						RETURN;
					END
			END
		
	BEGIN TRANSACTION
	SET @v_bitBeginTran = 1;
	
	DECLARE Inventory_Cursor CURSOR FOR
		SELECT inv.inventory_id
			  , inv.attribute_group_id 
			  , inv.location_id
			  , loc.location
			  , loc.loc_type
			  , loc.erp_location
			  , inv.parent_lpn
			  , inv.lpn
			  , inv.wh_item_master_id
			  , item.item_master_id
			  , item.item_number
			  , inv.quantity 
			  , inv.inventory_status_id
			  , invStatus.inv_status
			  , invLot.lot_number
			  , invExp.expiry_date 
			  , invAttribute1.attribute1
			  , invAttribute2.attribute2
			  , invAttribute3.attribute3
			  , invAttribute4.attribute4
			  , invAttribute5.attribute5
			  , inv.receive_date
			  , inv.mfg_date
			  , item.lot_control
			  , item.expiry_date_control
			  , item.sn_control
			  , item.attribute1_control
			  , item.attribute2_control
			  , item.attribute3_control
			  , item.attribute4_control
			  , item.attribute5_control
		FROM (SELECT inventory_id
				  , attribute_group_id 
				  , location_id
				  , parent_lpn
				  ,	lpn
				  ,	wh_item_master_id
				  , quantity 
				  , inventory_status_id
				  , receive_date
				  , mfg_date
			  FROM dbo.t_wms_inventory
			  WHERE wh_master_id = @in_vchWhMasterID 
			  AND owner_id = @in_vchOwnerID 
			  AND lpn = @in_vchLPN
			  ) AS inv 
		INNER JOIN dbo.t_wms_inventory_status AS invStatus ON inv.inventory_status_id = invStatus.inventory_status_id 
 		INNER JOIN dbo.t_wms_wh_item AS whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
		INNER JOIN dbo.t_wms_item AS item ON whItem.item_master_id = item.item_master_id 
 		INNER JOIN dbo.t_wms_location AS loc ON inv.location_id = loc.location_id 
		LEFT OUTER JOIN  (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number
						FROM dbo.t_wms_inventory_attribute
						WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_6
						WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_5
						WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttribute1 ON inv.inventory_id = invAttribute1.inventory_id AND inv.attribute_group_id = invAttribute1.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_4
						WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttribute2 ON inv.inventory_id = invAttribute2.inventory_id AND inv.attribute_group_id = invAttribute2.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_3
						WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttribute3 ON inv.inventory_id = invAttribute3.inventory_id AND inv.attribute_group_id = invAttribute3.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_2
						WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttribute4 ON inv.inventory_id = invAttribute4.inventory_id AND inv.attribute_group_id = invAttribute4.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5
						FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_1
						WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttribute5 ON inv.inventory_id = invAttribute5.inventory_id AND inv.attribute_group_id = invAttribute5.attribute_group_id 
	OPEN Inventory_Cursor
	FETCH NEXT FROM Inventory_Cursor INTO @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchSourceLocationID,@v_vchSourceLocation,@v_vchSourceLocType,@v_vchERPSourceLocation,@v_vchParentLPN,@v_vchLpn
										,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_fltQuantity,@v_vchInventoryStatusID,@v_vchInvStatus			
										,@v_vchLotNumber,@v_vchExpiryDate,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate,@v_dtMfgDate			
										,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control
	WHILE @@FETCH_STATUS = 0
	BEGIN
			IF @v_vchSNControl = 'FULL'
				BEGIN
					--Insert Serial in Inventory
					DELETE @tInventorySerial
					INSERT INTO @tInventorySerial
					SELECT ROW_NUMBER() OVER(ORDER BY attribute_value) AS RowNumber
						,inventory_id
						,attribute_group_id
						,quantity
						,attribute_value
					FROM t_wms_inventory_attribute
					WHERE inventory_id = @v_vchInventoryID
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
 					ORDER BY attribute_value
				END

			--Get & Check Item UOM 
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUOM = uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES'
			AND is_active = 'YES'	
			IF (@v_vchBaseItemUomID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'UOM_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUOM,'@param2','@param3','@param4','@param5')
					Goto WRITE_PROC
				END

			SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQuantity,2)
			SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQuantity,2)
		
			--------------------------------------------
			--Manage source inventory
			--------------------------------------------
			UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQuantity,@Round) 
				,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID

			IF (@v_vchSNControl = 'FULL')
			BEGIN
				UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
				FROM t_wms_inventory_attribute invAttr
				INNER JOIN @tInventorySerial tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
				WHERE invAttr.inventory_id = tSourceInv.InventoryID
				AND invAttr.attribute_value = tSourceInv.SerialNumber
				AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
			END

			--Inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQuantity,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END

			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
			DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
					
			--Update Volumn & Weight in from location
			IF @v_vchSourceLocationID IS NOT NULL
				BEGIN
					UPDATE [dbo].[t_wms_location]
						SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
						, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
						, update_date = GETDATE()  
						, [update_by] = @in_vchUserID   
					WHERE [location_id] = @v_vchSourceLocationID
				END
			
			--------------------------------------------
			--Check Destination Location
			--------------------------------------------
			--Calculate volumn & weight of LPN
			IF (@v_vchRuleCheckFullLPN = 'YES' AND @v_vchToLPNControl = 'YES')
				BEGIN
					DECLARE @v_fltPalletID			UNIQUEIDENTIFIER = NULL
					DECLARE @v_fltPLGrossWeight		FLOAT = 0
					DECLARE @v_fltPLVolumn			FLOAT = 0
					DECLARE @v_fltInvVolumnByLPN	FLOAT = 0
					DECLARE @v_fltInvWeightByLPN	FLOAT = 0

					--Calculate Volumn & Weight of pallet
					SELECT @v_fltPalletID = pallet_id
						,@v_fltPLVolumn = ROUND(ISNULL(width,0) * ISNULL(length,0) * ISNULL(height,0),@Round)
						,@v_fltPLGrossWeight = ISNULL(gross_weight,0)
					FROM t_wms_pallet_type 
					WHERE is_active = 'YES'
				
					IF (@v_fltPalletID IS NULL)
						BEGIN
							SET @out_ErrorCode = 'PALLET_TYPE_CANNOT_BE_EMPTY';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLpn,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					SELECT @v_fltInvVolumnByLPN = SUM(ISNULL(volumn_by_lpn,0))
						,@v_fltInvWeightByLPN = SUM(ISNULL(weight_by_lpn,0))
					FROM t_wms_inventory
					WHERE lpn = @v_vchLpn

					--Volumn of qty input + volumn in inventory เทียบกับ volumn ที่กำหนด
					IF (@v_fltVolumn + ISNULL(@v_fltInvVolumnByLPN,0)) > @v_fltPLVolumn
						BEGIN
							SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LPN';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLpn,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					IF (@v_fltTotalWeight + ISNULL(@v_fltInvWeightByLPN,0)) > @v_fltPLGrossWeight
						BEGIN
							SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LPN';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchLpn,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
				END

			IF (@v_vchToLPNControl = 'NO')
				BEGIN
					SET @v_vchToLPN = NULL
				END
			ELSE
				BEGIN
					SET @v_vchToLPN = @v_vchLpn 
				END 

			--Calculate Volumn & Weight of Location
			IF (@v_fltLocWidth > 0 AND @v_fltLocLength > 0 AND @v_fltLocHeight > 0 AND @v_fltLocGrossWeight > 0)
				BEGIN
				--Calculate Volumn
				SET @v_fltLocVolumn = (@v_fltLocWidth * @v_fltLocLength * @v_fltLocHeight)
		
				--Check volumn and weight
				IF @v_fltVolumn > (@v_fltLocVolumn - @v_fltLocTotalVolumn)
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				IF @v_fltTotalWeight > (@v_fltLocGrossWeight - @v_fltLocTotalWeight)
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				UPDATE t_wms_location SET 
					total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
					,total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE location_id = @in_vchToLocationID
			END
			
			--------------------------------------------
			--Manage Destination inventory
			--------------------------------------------
			DECLARE @v_vchDestInventoryID		UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchDestAttributeGroupID	UNIQUEIDENTIFIER = NULL
			DECLARE @v_fltDestInvQty			FLOAT = 0
			SELECT @v_vchDestInventoryID = inventory_id
				,@v_vchDestAttributeGroupID = attribute_group_id
				,@v_fltDestInvQty = quantity
			FROM v_wms_inventory_data_by_id
			WHERE wh_master_id = @in_vchWhMasterID
			AND owner_id = @in_vchOwnerID
			AND location_id = @in_vchToLocationID
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND inventory_status_id = @v_vchInventoryStatusID
			AND receive_date = @v_dtReceiveDate
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@v_vchToLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
			AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
			EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchWhMasterID
									, @in_vchOwnerID			= @in_vchOwnerID
									, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
									, @in_vchLocationID			= @in_vchToLocationID
									, @in_vchStatusID			= @v_vchInventoryStatusID
									, @in_vchPalentLPN			= @in_vchToParentLPN
									, @in_vchLPN				= @v_vchToLPN
									, @in_fltQty				= @v_fltQuantity
									, @in_fltQtyAllocate		= 0
									, @in_fltQtyIncoming		= 0
									, @in_vchInventoryType		= 'INVENTORY'
									, @in_vchUserID				= @in_vchUserID
									, @in_vchReceiveDate		= @v_dtReceiveDate
									, @in_dtMFGDate				= @v_dtMFGDate
									, @in_vchInventoryID		= @v_vchDestInventoryID OUTPUT
									, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID OUTPUT	
									, @in_vchErrorCode			= @out_ErrorCode OUTPUT
									, @in_vchMessage			= @out_ErrorMessage OUTPUT	
			IF (@out_ErrorCode <> '0')
				GOTO WRITE_PROC;
				  
			--Insert/Update Attribute
			IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchDestInventoryID AND attribute_group_id = @v_vchDestAttributeGroupID)
				BEGIN --Update
					IF(@v_vchSNControl = 'FULL')
						BEGIN
							IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
										WHERE inventory_id = @v_vchDestInventoryID 
										AND attribute_group_id = @v_vchDestAttributeGroupID
										AND attribute_value IN (SELECT SerialNumber FROM @tInventorySerial)
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
								BEGIN
									SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
									GOTO WRITE_PROC;
								END

							--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							SELECT NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
								, @v_vchDestAttributeGroupID
								, SerialNumber
								, 1
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID
							FROM @tInventorySerial
							ORDER BY SerialNumber 
						END
				
					IF('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET 
									quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltQuantity,@Round),@Round) 
							WHERE inventory_id = @v_vchDestInventoryID 
							AND attribute_group_id = @v_vchDestAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
						END
				END
			ELSE
				BEGIN --Insert
					-- insert new serial
					IF(@v_vchSNControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								(inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							SELECT NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
								, @v_vchDestAttributeGroupID
								, SerialNumber
								, 1
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID
							FROM @tInventorySerial
							ORDER BY SerialNumber
						END
							
					--Insert New Lot Number
					IF(@v_vchLotControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
								( inv_attribute_id
								, inventory_id
								, inv_attribute_type_id
								, attribute_group_id
								, attribute_value
								, quantity
								, quantity_allocated
								, quantity_incoming
								, create_date
								, create_by)
							VALUES
								( NEWID()
								, @v_vchDestInventoryID
								, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
								, @v_vchDestAttributeGroupID
								, @v_vchLotNumber
								, ROUND(@v_fltQuantity,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)				
						END

					--Insert New Expiry Date
					IF(@v_vchExpiryDateControl = 'FULL')
						BEGIN
							INSERT INTO t_wms_inventory_attribute
