								, @v_vchDestAttributeGroupID
								, @v_vchExpiryDate
								, ROUND(@v_fltQuantity,@Round)
								, 0
								, 0
								, GETDATE()
								, @in_vchUserID)
						END

					--Insert New Attribute1
