						   ,@v_vchLotNumber
						   ,@v_vchLotNumber
						   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						   ,(CASE WHEN ISNULL(@v_vchExpiryDate,'') = '' THEN NULL ELSE CONVERT(DATE,@v_vchExpiryDate) END)
						   ,SerialNumber
						   ,@v_vchAttribute1
						   ,@v_vchAttribute1
						   ,@v_vchAttribute2
						   ,@v_vchAttribute2
						   ,@v_vchAttribute3
						   ,@v_vchAttribute3
						   ,@v_vchAttribute4
						   ,@v_vchAttribute4
						   ,@v_vchAttribute5
						   ,@v_vchAttribute5
						   ,@in_vchUserID
						   ,@in_vchReferenceNumber
						   ,@v_vchHostRecordID
						   ,@v_vchLPN
						   ,@v_vchToLpn
						   ,@v_vchParentLPN
						   ,@in_vchToParentLpn
						   ,@v_vchInvStatus
						   ,@v_vchInvStatus
						   ,@v_vchERPSourceLocation
						   ,@v_vchERPDestLocation
						   ,@v_vchReasonCode 
						   ,@v_dtReceiveDate
						   ,@v_dtMfgDate
						   ,@v_fltQuantity
						   ,@v_vchBaseUOM 
						   ,@in_vchDeviceID
						   ,GETDATE()
						   ,@in_vchUserID
						FROM @tInventorySerial
						ORDER BY RowNumber
					END
			END


			-- For Dashboard 
			EXEC usp_wms_dashboard_transaction @in_vchProcess		= 'OUT_IN'
											  ,@in_vchTransType		= 'MOVE'
											  ,@in_vchWhMasterID	= @in_vchWhMasterID
											  ,@in_vchOwnerID		= @in_vchOwnerID
											  ,@in_vchOwnerCode		= @v_vchOwner
											  ,@in_vchLocationID	= @v_vchSourceLocationID 
											  ,@in_vchItemMasterID	= @v_vchItemMasterID
											  ,@in_vchInvStatusID	= @v_vchInventoryStatusID
											  ,@in_vchToWhMasterID	= @in_vchWhMasterID
											  ,@in_vchToLocationID	= @in_vchToLocationID
											  ,@in_vchToInvStatusID = @v_vchInventoryStatusID
											  ,@in_fltQuantity		= @v_fltQuantity
											  ,@in_vchUserID		= @in_vchUserID
		  
		FETCH NEXT FROM Inventory_Cursor INTO @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchSourceLocationID,@v_vchSourceLocation,@v_vchSourceLocType,@v_vchERPSourceLocation,@v_vchParentLPN,@v_vchLpn
										,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_fltQuantity,@v_vchInventoryStatusID,@v_vchInvStatus			
										,@v_vchLotNumber,@v_vchExpiryDate,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_dtReceiveDate,@v_dtMfgDate				
										,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control
	END
	CLOSE Inventory_Cursor                  	
	DEALLOCATE Inventory_Cursor



	--20160701:Kritsada: update for get last update inventory 
	IF @in_vchToLocationID IS NOT NULL
		BEGIN
			UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] = @in_vchToLocationID
		END
	 
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_bitBeginTran = 1)
			ROLLBACK TRANSACTION;
			
		IF CURSOR_STATUS('global','Inventory_Cursor')>=-1
			BEGIN
				CLOSE Inventory_Cursor;
				DEALLOCATE Inventory_Cursor;
			END

		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] Owner: [' + @v_vchOwner + '] '
		SET @v_vchProcessData2 = 'To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
		SET @v_vchProcessData3 = 'LPN: ['+ ISNULL(@in_vchLPN,'') + '] ' 
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END

	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	IF (@@TRANCOUNT > 0 AND @v_bitBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	IF CURSOR_STATUS('global','Inventory_Cursor')>=-1
		BEGIN
			CLOSE Inventory_Cursor;
			DEALLOCATE Inventory_Cursor;
		END

	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] Owner: [' + @v_vchOwner + '] '
	SET @v_vchProcessData2 = 'To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
	SET @v_vchProcessData3 = 'LPN: ['+ ISNULL(@in_vchLPN,'') + '] ' 
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_for_move_lpn_to_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_for_move_lpn_to_lpn] 
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchLPN				NVARCHAR(25),
	@in_vchToLocationID		UNIQUEIDENTIFIER,
	@in_vchToParentLPN		NVARCHAR(25),
	@in_vchReasonID			UNIQUEIDENTIFIER,
	@in_vchRemark			NVARCHAR(255)= NULL,
	@in_vchReferenceNumber	NVARCHAR(50) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_ErrorCode			VARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT						
AS
BEGIN
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_inventory_for_move_lpn_to_lpn]'
	DECLARE @v_vchApplicationName	NVARCHAR(50)
	DECLARE @v_vchProcessData1		NVARCHAR(255)
    DECLARE @v_vchProcessData2		NVARCHAR(255)
    DECLARE @v_vchProcessData3		NVARCHAR(255)
    DECLARE @v_vchProcessData4		NVARCHAR(255)
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_dtStartTranDate		DATETIME = GETDATE()
	DECLARE @v_vchBeginTran			BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_vchLocal				VARCHAR(5) 
	DECLARE @v_vchHostRecordID		VARCHAR(40)
	DECLARE @v_vchTranType			NVARCHAR(20) = 'INV_MOVE'
	DECLARE @v_vchSubTranType		NVARCHAR(20) = 'MOVE_LPN'
	 
	DECLARE @v_vchReasonCode		NVARCHAR(50) = NULL
	--DECLARE @v_vchReasonDescription	NVARCHAR(100) = ''

	DECLARE @v_vchWarehouse			NVARCHAR(25) = NULL
	DECLARE @v_vchOwner				NVARCHAR(40) = NULL
	DECLARE @v_vchToLocation		NVARCHAR(50)
	DECLARE @v_vchToLPNControl		VARCHAR(5)
	DECLARE @v_fltToCapacity		FLOAT = 0
	DECLARE @v_vchToMixOwners		VARCHAR(3)
	DECLARE @v_vchToMixStatus		VARCHAR(3)
	DECLARE @v_vchToMixItems		VARCHAR(3)
	DECLARE @v_vchToMixLot			VARCHAR(3)
	DECLARE @v_vchToMixExpiryDates	VARCHAR(3)
	DECLARE @v_vchToMixAttribute1	VARCHAR(3)
	DECLARE @v_vchToMixAttribute2	VARCHAR(3)
	DECLARE @v_vchToMixAttribute3	VARCHAR(3)
	DECLARE @v_vchToMixAttribute4	VARCHAR(3)
	DECLARE @v_vchToMixAttribute5	VARCHAR(3)

	--For Interface Only
	DECLARE @v_vchERPSourceLocation	NVARCHAR(50)
	DECLARE @v_vchERPDestLocation	NVARCHAR(50)
 -----------------------------------------------------------------------------------	
 -- Begin
 -----------------------------------------------------------------------------------	   
    BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID) 		
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT TOP 1 @v_vchReasonCode = reason_code FROM t_wms_reason WHERE reason_id = @in_vchReasonID AND is_active = 'YES'
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID  AND is_active = 'YES'
		SELECT TOP 1 @v_vchOwner = owner_code FROM t_wms_owner where owner_id = @in_vchOwnerID  AND is_active = 'YES'
		 
		--Check Inventory
		IF NOT EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lpn = @in_vchLPN)
			BEGIN
				SET @out_ErrorCode = 'INVENTORY_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--Check Allocate Qty
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND owner_id = @in_vchOwnerID AND lpn = @in_vchLPN AND ISNULL(quantity_allocated,0) > 0)
			BEGIN
				SET @out_ErrorCode = 'INV_HAVE_ALLOCATE_CANNOT_CHANGE';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		--------------------------------------------
		--Validate Destination Location
		--------------------------------------------
		SET @v_vchToLocation = NULL
		SELECT @v_vchToLocation = location
			, @v_vchERPDestLocation = erp_location
			, @v_vchToLPNControl = lpn_controlled
			, @v_vchToMixOwners = mix_owners
			, @v_vchToMixStatus = mix_status
			, @v_vchToMixItems = mix_items
			, @v_vchToMixLot = mix_lot 
			, @v_vchToMixExpiryDates = mix_expiry_dates 
			, @v_vchToMixAttribute1	= mix_attribute1
			, @v_vchToMixAttribute2	= mix_attribute2
			, @v_vchToMixAttribute3	= mix_attribute3
			, @v_vchToMixAttribute4	= mix_attribute4
			, @v_vchToMixAttribute5	= mix_attribute5
			, @v_fltToCapacity = capacity_qty
		FROM t_wms_location 
		WHERE wh_master_id = @in_vchWhMasterID 
		AND location_id = @in_vchToLocationID
		AND is_active = 'YES'
		IF(@v_vchToLocation IS NULL)
			BEGIN
				SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END
		
		IF @v_vchToLPNControl = 'NO'
			BEGIN  
				SET @out_ErrorCode = 'TO_LOCATION_NOT_CONTROL_LPN';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--Check Mix of Source Location and Destination Location : ถ้าปลายทางมีของถึงจะ Check 
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND owner_id = @in_vchOwnerID)
			BEGIN 
				IF OBJECT_ID('tempdb..#tempInv') IS NOT NULL
					DROP TABLE #tempInv
				SELECT * INTO #tempInv
				FROM (SELECT wh_master_id
							,owner_id
							,location_id
							,wh_item_master_id
							,inventory_status_id
							,lot_number
							,expiry_date
							,attribute1
							,attribute2
							,attribute3
							,attribute4
							,attribute5
							,serial_number
						FROM v_wms_inventory_data_serial_by_id
						WHERE wh_master_id = @in_vchWhMasterID 
						AND owner_id = @in_vchOwnerID 
						AND lpn = @in_vchLPN 
						UNION  
						SELECT wh_master_id
							,owner_id
							,location_id
							,wh_item_master_id
							,inventory_status_id
							,lot_number
							,expiry_date
							,attribute1
							,attribute2
							,attribute3
							,attribute4
							,attribute5
							,serial_number
						FROM v_wms_inventory_data_serial_by_id
						WHERE wh_master_id = @in_vchWhMasterID
						AND location_id = @in_vchToLocationID
					) t

				-- Check to location is mix owner?
				IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND owner_id <> @in_vchOwnerID) AND (@v_vchToMixOwners = 'NO')
					BEGIN
						SET @out_ErrorCode = 'LOCATION_NOT_MIX_OWNER';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
		
				-- check to location is mix item?
				IF EXISTS (SELECT inventory_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND wh_item_master_id NOT IN (SELECT wh_item_master_id FROM #tempInv)) AND @v_vchToMixItems = 'NO'
					BEGIN
						SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ITEM';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END

				-- check location is mix Status?
				IF EXISTS(SELECT inventory_status_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchToLocationID AND inventory_status_id NOT IN (SELECT inventory_status_id FROM #tempInv)) AND @v_vchToMixStatus = 'NO'
					BEGIN
						SET @out_ErrorCode = 'LOCATION_NOT_MIX_STATUS';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
	 
				-- check to location is mix lot?
				IF @v_vchToMixLot = 'NO' AND ((SELECT COUNT(DISTINCT lot_number) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_LOT';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix expiry date?
				IF @v_vchToMixExpiryDates = 'NO' AND ((SELECT COUNT(DISTINCT [expiry_date]) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_EXPIRY_DATE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute1?
				IF @v_vchToMixAttribute1 = 'NO' AND ((SELECT COUNT(DISTINCT attribute1) FROM #tempInv) > 1) 
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE1';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
		 
				-- check location is mix attribute2?
				IF @v_vchToMixAttribute2 = 'NO' AND ((SELECT COUNT(DISTINCT attribute2) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE2';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute3?
				IF @v_vchToMixAttribute3 = 'NO' AND ((SELECT COUNT(DISTINCT attribute3) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE3';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute4?
				IF @v_vchToMixAttribute4 = 'NO' AND ((SELECT COUNT(DISTINCT attribute4) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE4';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END

				-- check location is mix attribute5?
				IF @v_vchToMixAttribute5 = 'NO'AND ((SELECT COUNT(DISTINCT attribute5) FROM #tempInv) > 1)
				BEGIN
					SET	@out_ErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE5';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END

		-- check capacity
		IF (@v_fltToCapacity > 0)
			BEGIN
				IF ((SELECT COUNT(DISTINCT lpn) + 1 FROM t_wms_inventory WHERE location_id = @in_vchToLocationID AND (lpn <> @in_vchLPN AND ISNULL(lpn,'') <> '')) > @v_fltToCapacity)
					BEGIN
						SET @out_ErrorCode = 'LOCATION_IS_FULL_CAPACITY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@v_vchToLocation,'@param2','@param3','@param4','@param5')
						RETURN;
					END
			END
		
	BEGIN TRANSACTION
	SET @v_vchBeginTran = 1;
		SELECT inventory_id
			  , attribute_group_id
			  , wh_master_id
			  , wh_id
			  , owner_id
			  , owner_code
			  , location_id
			  , location
			  , loc_type
			  , erp_location
			  , lpn_controlled
			  , parent_lpn
			  , lpn
			  , wh_item_master_id
			  , item_master_id
			  , item_number
			  , quantity
			  , quantity_allocated
			  , item_uom_id
			  , uom_prompt
			  , inventory_status_id
			  , inv_status
			  , lot_number
			  , expiry_date
			  , serial_number
			  , attribute1
			  , attribute2
			  , attribute3
			  , attribute4
			  , attribute5
			  , receive_date
			  , mfg_date
			  , ROW_NUMBER() OVER(ORDER BY serial_number, inventory_id) AS RowNumber
		INTO #tInventory
		FROM v_wms_inventory_data_by_serial_item
		WHERE wh_master_id = @in_vchWhMasterID 
		AND owner_id = @in_vchOwnerID 
		AND lpn = @in_vchLPN
	 
		UPDATE t_wms_inventory SET location_id = @in_vchToLocationID
		FROM t_wms_inventory inv
		INNER JOIN #tInventory ON inv.inventory_id = #tInventory.inventory_id
		
		--Insert Remark
		IF ISNULL(@in_vchRemark,'') <> ''
			BEGIN
				--Insert Remark for Serial 
				IF EXISTS (SELECT inventory_id FROM #tInventory WHERE ISNULL(serial_number,'') <> '')
					BEGIN
						DELETE invRemark 
						FROM t_wms_inventory_remark invRemark
						INNER JOIN #tInventory on invRemark.inventory_id = #tInventory.inventory_id
						WHERE ISNULL(#tInventory.serial_number,'') <> ''
						INSERT INTO [dbo].[t_wms_inventory_remark]
								   ([inventory_remark_id]
								   ,[inventory_id]
								   ,[serial_number]
								   ,[reason_id]
								   ,[remark]
								   ,[create_by]
								   ,[create_date] )
							 SELECT NEWID()
								   ,inventory_id
								   ,serial_number
								   ,@in_vchReasonID
								   ,@in_vchRemark
								   ,@in_vchUserID
								   ,GETDATE()
							FROM #tInventory
							WHERE ISNULL(serial_number,'') <> ''
							ORDER BY serial_number
					END
			
				--Update Remark for Other 
				UPDATE t_wms_inventory_remark SET 
					 reason_id = @in_vchReasonID
					,remark = @in_vchRemark
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				FROM t_wms_inventory_remark invRemark 
				INNER JOIN #tInventory inv on invRemark.inventory_id = inv.inventory_id
				WHERE ISNULL(inv.serial_number,'') = ''

				--Insert Remark for Other 
				INSERT INTO [dbo].[t_wms_inventory_remark]
					([inventory_remark_id]
					,[inventory_id]
					,[serial_number]
					,[reason_id]
					,[remark]
					,[create_by]
					,[create_date])
				SELECT NEWID()
					,inventory_id
					,NULL
					,@in_vchReasonID
					,@in_vchRemark
					,@in_vchUserID
					,GETDATE()
				FROM #tInventory
				WHERE inventory_id NOT IN (SELECT inventory_id FROM t_wms_inventory_remark)
				AND ISNULL(serial_number,'') = ''
			END
				
		--Clear Inventory Remark : หากมี Record Remark จะต้อง Clear ก่อน ถึงจะลบ inventory ได้
		DELETE t_wms_inventory_remark
		FROM t_wms_inventory_remark invRemark
		LEFT JOIN t_wms_inventory inv on invRemark.inventory_id = inv.inventory_id
		WHERE inv.inventory_id IS NULL

		UPDATE [dbo].[t_wms_location] SET [update_date] = GETDATE(), [update_by] = @in_vchUserID WHERE [location_id] IN (SELECT location_id FROM #tInventory)
				
		-----------------------------------------------------------------------------------
		-- Write transaction log
		BEGIN
			WRITE_TRANS:							
		-----------------------------------------------------------------------------------	 
			--Check TranType and Sub Tran Type for Interface Data
			IF ((SELECT host_interface_manager FROM t_com_transaction WHERE wh_id = @v_vchWarehouse AND app_id = @in_vchApplicationID AND tran_type = @v_vchTranType and sub_tran_type = @v_vchSubTranType) = 'YES')
				BEGIN
					EXEC usp_get_HostInterfaceID @v_vchHostRecordID OUTPUT 
					SET @v_dtProcessDateTime = GETDATE(); 
					INSERT INTO [dbo].[t_host_wms_trans_export]
						([record_id]
						,[host_record_id]
						,[processing_code]
						,[processing_status]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type] 
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[lpn]
						,[after_lpn]
						,[status]
						,[after_status] 
						,[control_value_1]
						,[control_value_2]
						,[receive_date]
						,[mfg_date]
						,[reason_code]
						,[device]
						,[create_date]
						,[create_by])
					SELECT NEWID()
						,@v_vchHostRecordID
						,'ADD'  
						,'PENDING'
						,@in_vchApplicationID
						,@v_vchApplicationName
						,@v_vchTranType
						,@v_vchSubTranType 
						,@v_dtStartTranDate
						,@v_dtProcessDateTime
						,wh_id
						,wh_id	
						,location
						,@v_vchToLocation
						,owner_code
						,owner_code
						,item_number
						,quantity
						,uom_prompt
						,0
						,uom_prompt
						,lot_number
						,lot_number
						,expiry_date
						,expiry_date
						,serial_number
						,attribute1
						,attribute1
						,attribute2
						,attribute2
						,attribute3
						,attribute3
						,attribute4
						,attribute4
						,attribute5
						,attribute5
						,@in_vchUserID
						,@in_vchReferenceNumber 
						,lpn
						,lpn
						,inv_status
						,inv_status 
						,erp_location
						,@v_vchERPDestLocation
						,receive_date
						,mfg_date
						,@v_vchReasonCode
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID
					FROM #tInventory 
					ORDER BY RowNumber
				END

			--Write Tran Log
			SET @v_dtProcessDateTime = GETDATE();
			INSERT INTO [dbo].[t_com_tran_log]
				([tran_id]
				,[app_id]
				,[app_name]
				,[tran_type]
				,[sub_tran_type]
				,[description]
				,[start_tran_datetime]
				,[end_tran_datetime]
				,[warehouse]
				,[to_warehouse]
				,[location]
				,[to_location]
				,[owner]
				,[to_owner]
				,[item_number]
				,[quantity]
				,[quantity_uom]
				,[after_quantity]
				,[after_quantity_uom]
				,[lot_number]
				,[after_lot_number]
				,[expiry_date]
				,[after_expiry_date]
				,[serial_number]
				,[attribute1]
				,[after_attribute1]
				,[attribute2]
				,[after_attribute2]
				,[attribute3]
				,[after_attribute3]
				,[attribute4]
				,[after_attribute4]
				,[attribute5]
				,[after_attribute5]
				,[user_id]
				,[reference_number]
				,[control_number]
				,[lpn]
				,[after_lpn]
				,[parent_lpn]
				,[after_parent_lpn]
				,[status]
				,[after_status] 
				,[control_value_1]
				,[control_value_2]
				,[reason_code] 
				,[receive_date]
				,[mfg_date]
				,[udf_1]
				,[input_quantity]
				,[input_uom]
				,[device]
				,[create_date]
				,[create_by])
			SELECT NEWID()
				,@in_vchApplicationID
				,@v_vchApplicationName
				,@v_vchTranType
				,@v_vchSubTranType
				,'Move LPN'
				,@v_dtStartTranDate
				,@v_dtProcessDateTime
				,wh_id
				,wh_id
				,location
				,@v_vchToLocation
				,owner_code
				,owner_code
				,item_number
				,quantity
				,uom_prompt
				,0
				,uom_prompt
				,lot_number
				,lot_number
				,expiry_date
				,expiry_date
				,serial_number
				,attribute1
				,attribute1
				,attribute2
				,attribute2
				,attribute3
				,attribute3
				,attribute4
				,attribute4
				,attribute5
				,attribute5
				,@in_vchUserID
				,@in_vchReferenceNumber
				,@v_vchHostRecordID
				,lpn
				,lpn
				,parent_lpn
				,parent_lpn
				,inv_status
				,inv_status 
				,erp_location
				,@v_vchERPDestLocation
				,@v_vchReasonCode 
				,receive_date
				,mfg_date
				,@in_vchRemark
				,quantity
				,uom_prompt
				,@in_vchDeviceID
				,GETDATE()
				,@in_vchUserID
			FROM #tInventory
			ORDER BY RowNumber 
		END

		-----------------------------------------------------------------------------------
		--Insert Dashboard 
		BEGIN
			--Change Status : from is out, to is in 
			INSERT INTO [dbo].[t_wms_dashboard_trans_out]
						([trans_id]
						,[trans_date]
						,[trans_type]
						,[wh_master_id]
						,[wh_id]
						,[owner_id]
						,[owner_code]
						,[location_id]
						,[location]
						,[item_master_id]
						,[item_number]
						,[item_description]
						,[category_id]
						,[item_category]
						,[quantity]
						,[inventory_status_id]
						,[inv_status]
						,[create_by]
						,[create_date])
				SELECT NEWID()
					,GETDATE()
					,'MOVE'
					,wh_master_id
					,wh_id
					,inv.owner_id
					,inv.owner_code
					,inv.location_id
					,inv.location
					,inv.item_master_id
					,inv.item_number
					,item.description
					,cate.category_id
					,cate.item_category
					,SUM(quantity)
					,inv.inventory_status_id
					,inv.inv_status
					,@in_vchUserID
					,GETDATE()
				FROM #tInventory inv 
				INNER JOIN t_wms_item item ON inv.item_master_id = item.item_master_id
				INNER JOIN t_wms_category cate ON cate.category_id = item.category_id
				GROUP BY wh_master_id,wh_id,inv.owner_id,inv.owner_code,inv.location_id,inv.location,inv.item_master_id,inv.item_number,item.description,cate.category_id,cate.item_category,inv.inventory_status_id,inv.inv_status

			INSERT INTO [dbo].[t_wms_dashboard_trans_in]
						([trans_id]
						,[trans_date]
						,[trans_type]
						,[wh_master_id]
						,[wh_id]
						,[owner_id]
						,[owner_code]
						,[location_id]
						,[location]
						,[item_master_id]
						,[item_number]
						,[item_description]
						,[category_id]
						,[item_category]
						,[quantity]
						,[inventory_status_id]
						,[inv_status]
						,[create_by]
						,[create_date])
				SELECT NEWID()
					,GETDATE()
					,'MOVE'
					,wh_master_id
					,wh_id
					,inv.owner_id
					,inv.owner_code
					,@in_vchToLocationID
					,@v_vchToLocation
					,inv.item_master_id
					,inv.item_number
					,item.description
					,cate.category_id
					,cate.item_category
					,SUM(quantity)
					,inv.inventory_status_id
					,inv.inv_status
					,@in_vchUserID
					,GETDATE()
				FROM #tInventory inv 
				INNER JOIN t_wms_item item ON inv.item_master_id = item.item_master_id
				INNER JOIN t_wms_category cate ON cate.category_id = item.category_id
				GROUP BY wh_master_id,wh_id,inv.owner_id,inv.owner_code,inv.location_id,inv.location,inv.item_master_id,inv.item_number,item.description,cate.category_id,cate.item_category,inv.inventory_status_id,inv.inv_status
		END

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
		RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTran = 1)
			ROLLBACK TRANSACTION;
					
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] Owner: [' + @v_vchOwner + '] '
		SET @v_vchProcessData2 = 'To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
		SET @v_vchProcessData3 = 'LPN: ['+ ISNULL(@in_vchLPN,'') + '] ' 
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END

	-----------------------------------------------------------------------------------	
END TRY
    
-----------------------------------------------------------------------------------
-- Error Handling
-----------------------------------------------------------------------------------    
BEGIN CATCH
	If (@@TRANCOUNT > 0 AND @v_vchBeginTran = 1)
		ROLLBACK TRANSACTION;
  	
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE(); 
	SET @v_vchProcessData1 = 'Warehouse: ['+ ISNULL(@v_vchWarehouse,'') + '] Owner: [' + @v_vchOwner + '] '
	SET @v_vchProcessData2 = 'To Location: [' + ISNULL(@v_vchToLocation,'') + ']'
	SET @v_vchProcessData3 = 'LPN: ['+ ISNULL(@in_vchLPN,'') + '] ' 
				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchProcessData1,
		@in_vchData2 = @v_vchProcessData2,
		@in_vchData3 = @v_vchProcessData3,
		@in_vchData4 = @v_vchProcessData4,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage			
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_move_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_move_item]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchTransactionType	NVARCHAR(20),
	@in_vchSubTranType		NVARCHAR(20),
	@in_vchAllParentLPN		NVARCHAR(3)		= null,
	@in_vchAllLPN			NVARCHAR(3)		= null,
	@in_vchAllItem			NVARCHAR(3)		= null,
	@in_vchAllLot			NVARCHAR(3)		= null,
	@in_vchAllExpiryDate	NVARCHAR(3)		= null,
	@in_vchAllSerial		NVARCHAR(3)		= null,
	@in_vchAllLocation		NVARCHAR(3)		= null,
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchToLocation		NVARCHAR(50)	= null,
	@in_vchFromParentLPN	NVARCHAR(25)	= null,
	@in_vchFromLPN			NVARCHAR(25)	= null,
	@in_vchToParentLPN		NVARCHAR(25)	= null,
	@in_vchToLPN			NVARCHAR(25)	= null,
	@in_vchItem				NVARCHAR(50)	= null,
	@in_vchLotNumber		NVARCHAR(50)	= null,
	@in_vchFromStatus		NVARCHAR(50)	= null,
	@in_vchToStatus			NVARCHAR(50)	= null,
	@in_vchOwner			NVARCHAR(50)	= null,
	@in_vchReasonCode		NVARCHAR(20)	= null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
   
	DECLARE
	-- Error handling variables
    @c_vchObjName				NVARCHAR(30) = '[usp_inventory_control_all_value]', -- The name that uniquely tags this object.
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
    @v_dtProcessDateTime		DATETIME,
    
	@v_vchWarehouseID			NVARCHAR(40),
	@v_vchLocationID			NVARCHAR(40),
	@v_vchToLocationID			NVARCHAR(40),
	@v_vchInventoryID			NVARCHAR(40),
	@v_vchAttributeGroupID		NVARCHAR(40),
	@v_vchInventoryFromStatusID	NVARCHAR(40),
	@v_vchInventoryToStatusID	NVARCHAR(40),
	@v_vchInvAttributeID		NVARCHAR(40),
	
	@v_vchOwner					NVARCHAR(40),
	@v_fltQuantity				FLOAT,
	@v_fltQuntityAllocate		FLOAT,
	
	@v_vchWHItemMasterID		NVARCHAR(40),
	@v_vchItemMasterID			NVARCHAR(40),
	@v_vchItem					NVARCHAR(50),
	@v_vchItemUOM				NVARCHAR(25),
	@v_vchParentLPN				NVARCHAR(25),
	@v_vchLPN					NVARCHAR(25),
	@v_vchToLPN					NVARCHAR(25),
	@v_vchFromInvStatusID		NVARCHAR(50),
	@v_vchToInvStatusID			NVARCHAR(50),
	@v_vchLocation				NVARCHAR(50),

	@cursorInventory			CURSOR,
	@dynamicSQL					NVARCHAR(1000) = '',
	@ConditionSQL				NVARCHAR(500) = '',
	@v_vchChkReceiveDateSQL		NVARCHAR(1500) = '',
	@v_vchHostInterfaceID		VARCHAR(40),
	@v_vchReceiveDate			DATE,
	@v_vchLocationType			NVARCHAR(25),
	@v_vchLPNControl			NVARCHAR(3),
	@v_vchMixItem				NVARCHAR(3),
	@v_vchMixLot				NVARCHAR(3),
    @v_vchMixExpiryDate			NVARCHAR(3),
    @v_vchMixOwner				NVARCHAR(3),
	@v_vchMixStatus				NVARCHAR(3),
	@v_vchOverrideReceiveDate	NVARCHAR(3),
	@v_vchApplicationName		NVARCHAR(100),
	@v_dtDateNow				NVARCHAR(10),
	@v_vchDescription			NVARCHAR(100),
	
	@v_vchLot_Number			NVARCHAR(50),
	@v_vchExpiry_Date			NVARCHAR(8),
	@v_vchSerial_Number			NVARCHAR(50),
	@v_vchLotControl			NVARCHAR(10),
	@v_vchExpiryDateControl		NVARCHAR(10),
	@v_vchSerialControl			NVARCHAR(10),
	@Round						INT,
	@v_vchMovementType			NVARCHAR(10),
	@v_vchFromPlant				NVARCHAR(50),
	
	@v_vchDubLocation			NVARCHAR(50),
    @v_vchDubParentLPN			NVARCHAR(25),
    @v_vchOldLPN				NVARCHAR(25),
    @v_vchOldInventoryStatusID	VARCHAR(40),
    @v_vchChkReceiveDate		DATE,
	@v_vchBeginTrans			BIT = 0,
	@v_vchOwnerID				VARCHAR(40),
	@v_vchOwnerCode				NVARCHAR(50),
	@v_vchOldItem				NVARCHAR(50),
	@v_vchOldWHItemMasterID		VARCHAR(40),
	-- 2013-10-04 check capacity location
	@v_fltCapacity				FLOAT = 0,
	@v_fltLPNQtyFromLocation	FLOAT = 0,
	@v_fltLPNQtyToLocation		FLOAT = 0
	
	IF (@in_vchToParentLPN = '')
		SET @in_vchToParentLPN = NULL;
	IF (@in_vchToLPN = '')
		SET @in_vchToLPN = NULL;
	IF (@in_vchItem = '')
		SET @in_vchItem = NULL;
	IF (@in_vchLotNumber = '')
		SET @in_vchLotNumber = NULL;
	IF (@in_vchFromStatus = '')
		SET @in_vchFromStatus = NULL;
	IF (@in_vchToStatus = '')
		SET @in_vchToStatus = NULL;
		
	BEGIN TRY
								 
		SELECT @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchWarehouseID = wh_master_id,@v_vchFromPlant = wh_group FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWarehouseID AND location = @in_vchFromLocation AND is_active = 'YES'
	
		SELECT @v_vchToLocationID = location_id
			, @v_vchLocationType = loc_type
			, @v_vchLPNControl = lpn_controlled
			, @v_vchMixItem = mix_items
			, @v_vchMixLot = mix_lot
			, @v_vchMixExpiryDate = mix_expiry_dates
			, @v_vchMixOwner = mix_owners
			, @v_vchOverrideReceiveDate = override_receive_date
			, @v_fltCapacity = ISNULL(capacity_qty,0)
			, @v_vchMixStatus = mix_status
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWarehouseID 
		AND location = @in_vchToLocation
		AND is_active = 'YES'
		If (@v_vchToLocationID is null)
			Begin
				SET @out_ErrorCode = '905';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC
			End

		-- Check duplicate parent lpn.
		If (isnull(@in_vchToParentLPN,'') <> '')
			Begin
				select top 1 @v_vchDubLocation = location_id from t_wms_inventory where wh_master_id = @v_vchWarehouseID and (location_id <> @v_vchLocationID and location_id <> @v_vchToLocationID) and parent_lpn = @in_vchToParentLPN
				If (isnull(@v_vchDubLocation,'') <> '')
					Begin
						Select @v_vchDubLocation = location from t_wms_location where location_id = @v_vchDubLocation
						SET @out_ErrorCode = '901';
						select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_LPN_DUPLICATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
						Goto WRITE_PROC
					End
			End

		-- Check duplicate lpn.
		IF (@v_vchLPNControl = 'YES')
			BEGIN
				-- Check duplicate lpn.
				IF (ISNULL(@in_vchToLPN,'') <> '' AND ISNULL(@in_vchFromLPN,'') = '')
					BEGIN
						IF (ISNULL(@in_vchFromParentLPN,'') <> '' OR ISNULL(@in_vchToParentLPN,'') <> '')
							BEGIN
								SELECT TOP 1 @v_vchDubParentLPN = parent_lpn FROM t_wms_inventory 
								WHERE wh_master_id = @v_vchWarehouseID 
								AND (ISNULL(parent_lpn,'') <> ISNULL(@in_vchFromParentLPN,'') 
								AND ISNULL(parent_lpn,'') <> ISNULL(@in_vchToParentLPN,'')) 
								AND lpn = @in_vchToLPN
								IF (ISNULL(@v_vchDubParentLPN,'') <> '')
									BEGIN
										SET @out_ErrorCode = '901';
										SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_PL',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLPN,@v_vchDubParentLPN,'@param3','@param4','@param5')
										Goto WRITE_PROC
									END
							END
						ELSE
							BEGIN
								SET @v_vchDubLocation = NULL;
								SELECT @v_vchDubLocation = location FROM t_wms_inventory inv
								INNER JOIN t_wms_location loc on inv.location_id = loc.location_id
								WHERE inv.lpn = @in_vchToLPN AND inv.wh_master_id = @v_vchWarehouseID
								IF (@v_vchDubLocation IS NOT NULL AND @v_vchDubLocation <> @in_vchToLocation)
									BEGIN
										--LPN ไม่ได้อยู่ใน Location ที่ Scan
										SET @out_ErrorCode = 'FOUND_LPN_IN_OTHER_LOCATION'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLPN,@v_vchDubLocation,'@param3','@param4','@param5')			
										GOTO WRITE_PROC
									END
							END
					END
			END

		IF (ISNULL(@in_vchItem,'') <> '')
			BEGIN
				SET @v_vchItem = @in_vchItem;
				
				------------------------------------------------------
				--mai 28/02/2014 : เพิ่ม join item crossref
				------------------------------------------------------
				SELECT @v_vchItemMasterID = item.item_master_id
					,@in_vchItem = item.item_number
					,@v_vchLotControl = item.lot_control
					,@v_vchExpiryDateControl = item.expiry_date_control
					,@v_vchSerialControl = item.sn_control 
				FROM t_wms_item item
				INNER JOIN t_wms_owner own on item.owner_id = own.owner_id 
				LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
				WHERE (item.item_number = @in_vchItem OR item.dg_code = @in_vchItem OR cref.alternate_item_number = @in_vchItem)
				AND own.owner_code = @in_vchOwner

				IF (ISNULL(@v_vchItemMasterID,'') = '')
					BEGIN
						SET @out_ErrorCode = '902';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END

				SELECT @v_vchWHItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @v_vchWarehouseID AND item_master_id = @v_vchItemMasterID
			END
			
		SELECT @v_vchFromInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchFromStatus AND is_active = 'YES'
		-- Add condition value
		IF (ISNULL(@in_vchFromStatus,'') <> '')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' and inventory_status_id = ''' + @v_vchFromInvStatusID + ''' ';
			END
		IF (ISNULL(@in_vchItem,'') <> '')
			BEGIN
				IF (ISNULL(@in_vchAllItem,'') = 'YES')
					BEGIN
						SET @in_vchItem = null;
					END
				--Else
				--	Begin
						SET @ConditionSQL = @ConditionSQL + ' AND wh_item_master_id = ''' + @v_vchWHItemMasterID + ''' ';
				--End
			END
		IF (ISNULL(@in_vchFromParentLPN,'') <> '' AND ISNULL(@in_vchAllParentLPN,'') <> 'YES')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND parent_lpn = ''' + @in_vchFromParentLPN + ''' ';
			END
		IF (ISNULL(@in_vchFromLPN,'') <> '' AND ISNULL(@in_vchAllLPN,'') <> 'YES')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND lpn = ''' + @in_vchFromLPN + ''' ';
			END	

		
		-- check inventory quantity allocated
		SET @dynamicSQL = ' select top 1 @v_fltQuntityAllocate = quantity_allocated from v_wms_inventory_data
							where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and quantity_allocated > 0 '
		
		set @v_vchDescription = 'Inventory Control All';
		set @dynamicSQL = @dynamicSQL + @ConditionSQL;
		EXEC sp_executesql @dynamicSQL,N'@v_fltQuntityAllocate float output',@v_fltQuntityAllocate output;
		If (@v_fltQuntityAllocate is not null)
			Begin
				set @out_ErrorCode = '999';
				
				If (@in_vchAllLPN = 'YES')
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_HAVE_QUANITY_ALLOCATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchFromParentLPN,'@param3','@param4','@param5')
				Else
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_HAVE_QUANITY_ALLOCATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchFromParentLPN,@in_vchFromLPN,@in_vchItem,'@param5')
				
				Goto WRITE_PROC;
			End
		
		--  check lpn capacity in to location 2013-10-04
		If (@v_fltCapacity > 0)
			Begin
				SET @dynamicSQL = '';
				SET @dynamicSQL = ' select @v_fltLPNQtyFromLocation = count(distinct lpn) from t_wms_inventory
									where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' ';
				set @dynamicSQL = @dynamicSQL + @ConditionSQL;
				EXEC sp_executesql @dynamicSQL,N'@v_fltLPNQtyFromLocation float output',@v_fltLPNQtyFromLocation output;

				SET @dynamicSQL = '';
				SET @dynamicSQL = ' select @v_fltLPNQtyToLocation = count(distinct lpn) from t_wms_inventory
									where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchToLocationID + ''' 
									and isnull(lpn,'''') not in ( ''' + isnull(@in_vchToLPN,'') + ''' ) ';

				EXEC sp_executesql @dynamicSQL,N'@v_fltLPNQtyToLocation float output',@v_fltLPNQtyToLocation output;

				If (isnull(@v_fltLPNQtyFromLocation,0) + isnull(@v_fltLPNQtyToLocation,0) > @v_fltCapacity)
					Begin
						set @out_ErrorCode = '989';
						select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_IS_FULL_CAPACITY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						Goto WRITE_PROC;
					End
			End

		-- === Get Inventory Data for move == --
		set @dynamicSQL	= '';
		-- ************ select inventory data ************* ---------------------------------------------
		If(@v_vchSerialControl = 'FULL' AND @in_vchAllSerial = 'YES')
			Begin
				set @dynamicSQL = '	 select inventory_id,attribute_group_id,wh_item_master_id,owner_id,location_id,parent_lpn,lpn,lot_number,expiry_date,serial_number,quantity,inventory_status_id,receive_date,owner_code
									 from v_wms_inventory_data_by_serial ';
			End
		Else
			Begin
				set @dynamicSQL = '	 select inventory_id,attribute_group_id,wh_item_master_id,owner_id,location_id,parent_lpn,lpn,lot_number,expiry_date,serial_number,quantity,inventory_status_id,receive_date,owner_code
									 from v_wms_inventory_data ';
			End

		If (isnull(@in_vchAllParentLPN,'') = 'YES') -- All lpn in parent lpn
			Begin
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' ';
				set @v_vchDescription = 'MOVE ALL PARENTLPN';
			End						 
		Else If (Isnull(@in_vchAllLPN,'') = 'YES') -- ALL LPN
			Begin
				set @in_vchToLPN = null;
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' ';
				set @v_vchDescription = 'MOVE ALL LPN';
			End
		Else If (Isnull(@in_vchAllItem,'') = 'YES') -- ALL ITEM
			Begin
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' ';
				set @v_vchDescription = 'MOVE ALL ITEM';
			End
		Else If (Isnull(@in_vchAllSerial,'') = 'YES') -- ALL Serial
			Begin
				--set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and serial_number IS NOT NULL '
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and serial_number IS NOT NULL '
				set @v_vchDescription = 'MOVE ALL Serial';
			End				
		Else If (Isnull(@in_vchAllLot,'') = 'YES') -- ALL Lot
			Begin
				--set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and lot_number IS NOT NULL '
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and lot_number IS NOT NULL '
				set @v_vchDescription = 'MOVE ALL LOT';
			End
		Else If (Isnull(@in_vchAllExpiryDate,'') = 'YES') -- ALL Expiry date
			Begin
				--set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and item_number = ''' + @in_vchItem + ''' and expiry_date IS NOT NULL '
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' and expiry_date IS NOT NULL '
				If (Isnull(@in_vchLotNumber,'') <> '')
					Begin
						set @ConditionSQL = @ConditionSQL + ' and lot_number = ''' + @in_vchLotNumber + ''' ';
					End
				set @v_vchDescription = 'MOVE ALL Expiry Date';						
			End				
		Else If (Isnull(@in_vchAllLocation,'') = 'YES') -- ALL in Location
			Begin
				set @dynamicSQL = @dynamicSQL + ' where wh_master_id = ''' + @v_vchWarehouseID + ''' ';
				set @v_vchDescription = 'MOVE ALL LOCATION';								
			End
				
		set @dynamicSQL = @dynamicSQL + isnull(@ConditionSQL,'');

		If (@v_vchLocationType <> 'FORK')
			Begin	
				If (@v_vchOverrideReceiveDate = 'NO')
					Begin
						If ((select value from t_wms_rule where rule_code = 'RULE_MIX_RECEIVE_DATE') = 'NO')
							Begin
								If Exists(select receive_date from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchToLocationID)
									Begin
										set @v_vchChkReceiveDateSQL = 'select top 1 @v_vchChkReceiveDate = receive_date from t_wms_inventory where (0=0) ' + ' and wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchLocationID + ''' ' +
										 + isnull(@ConditionSQL,'') + ' and receive_date not in (select receive_date from t_wms_inventory where wh_master_id = ''' + @v_vchWarehouseID + ''' and location_id = ''' + @v_vchToLocationID + ''') '
										EXEC sp_executesql @v_vchChkReceiveDateSQL,N'@v_vchChkReceiveDate date output',@v_vchChkReceiveDate output;
										If (isnull(@v_vchChkReceiveDate,'') <> '')
											Begin
												set @out_ErrorCode = '914';
												select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CAN_NOT_MIXED_RECEIVE_DATE',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
												Goto WRITE_PROC;
											End
									End
							End
						--Else
						--	Begin
						--		select top 1 @v_vchReceiveDate = receive_date from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID
						--	End
					End
				Else
					Begin
						If ((select top 1 value from t_wms_rule where rule_code = 'RULE_OVERRIDE_NEW_RECEIVE_DATE') = 'OLD')
							Begin
								select top 1 @v_vchReceiveDate = receive_date from t_wms_inventory 
								where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID
							End
						Else
							Begin
								select top 1 @v_vchReceiveDate = receive_date from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID
								
								Update t_wms_inventory set receive_date = @v_vchReceiveDate
								where wh_master_id = @v_vchWarehouseID and location_id = @v_vchToLocationID
							End
					End
			End
			
		set @dynamicSQL = '	 set @cursorInventory = CURSOR FORWARD_ONLY STATIC FOR ' +
							 @dynamicSQL + ' ; OPEN @cursorInventory'								

		exec sp_executesql @dynamicSQL,N'@cursorInventory CURSOR OUTPUT',@cursorInventory OUTPUT
		
		fetch @cursorInventory into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchWHItemMasterID,@v_vchOwner,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchSerial_Number,@v_fltQuantity,@v_vchFromInvStatusID,@v_vchReceiveDate,@v_vchOwnerCode
--------------------------------------------------------------------------------------------------		

		If (@v_vchInventoryID is null)
			Begin
				close @cursorInventory;
				deallocate @cursorInventory;
				set  @out_ErrorCode = '999'
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
			
		--If (@in_vchTransactionType = 'INV_STATUS_CHANGE' and @in_vchSubTranType = 'INV_STATUS_CHANGE')
		--	Begin
		--		exec usp_get_HostInterfaceID @v_vchHostInterfaceID output
		--	End
		
		--(select value from t_wms_rule where rule_code = 'RULE_LOCATION_MIX_STATUS')
		If (@v_vchMixStatus = 'NO')
			If Exists(select top 1 inventory_status_id from t_wms_inventory where inventory_status_id <> @v_vchToInvStatusID and wh_master_id = @v_vchWarehouseID 
					 and location_id = @v_vchToLocationID)
				Begin
					set @out_ErrorCode = '999';
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_STATUS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					close @cursorInventory;
					deallocate @cursorInventory;
					Goto WRITE_PROC;
				End
		
		set @v_dtDateNow = substring( convert(nvarchar,getdate(),126),0,11);
			
		If (isnull(@in_vchToLPN,@v_vchLPN) = '' and @v_vchLPNControl = 'YES')
			Begin 
				set @out_ErrorCode = '999';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
				close @cursorInventory;
				deallocate @cursorInventory;
				Goto WRITE_PROC;
			End
		
		If (@in_vchTransactionType = 'INV_STATUS_CHANGE' and @in_vchSubTranType = 'INV_STATUS_CHANGE')
			Begin
				If (@in_vchFromStatus = 'Blocked' and @in_vchToStatus = 'Unrestricted')
					set @v_vchMovementType = '343';
				Else If (@in_vchFromStatus = 'Unrestricted' and @in_vchToStatus = 'Blocked')
					set @v_vchMovementType = '344';
				Else If (@in_vchFromStatus = 'Blocked' and @in_vchToStatus = 'QI')
					set @v_vchMovementType = '349';
				Else If (@in_vchFromStatus = 'QI' and @in_vchToStatus = 'Blocked')
					set @v_vchMovementType = '350';
				Else If (@in_vchFromStatus = 'QI' and @in_vchToStatus = 'Unrestricted')
					set @v_vchMovementType = '321';
				Else If (@in_vchFromStatus = 'Unrestricted' and @in_vchToStatus = 'QI')
					set @v_vchMovementType = '322';	
				Else
					set @v_vchMovementType = null
					
				exec usp_get_HostInterfaceID @v_vchHostInterfaceID output
															
			End
			
		Begin Transaction

			set @v_vchBeginTrans = 1;

			While @@FETCH_STATUS = 0
				Begin
					
					If (isnull(@in_vchFromStatus,'') = '' or @v_vchOldInventoryStatusID <> @v_vchFromInvStatusID)
						Begin
							--select top 1 @in_vchFromStatus = inv_status,@v_vchFromInvStatusID = inventory_status_id 
							--from v_wms_inventory_item where location = @in_vchFromLocation
							--and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and lpn = @v_vchLPN

							select top 1 @in_vchFromStatus = inv_status
							from t_wms_inventory_status where inventory_status_id = @v_vchFromInvStatusID
							
						End
			
					If (isnull(@in_vchToStatus,'') = '')
						Begin
							set @in_vchToStatus = @in_vchFromStatus;
							set @v_vchToInvStatusID = @v_vchFromInvStatusID;
						End
					Else If (@in_vchFromStatus <> @in_vchToStatus)
						Begin
							select @in_vchToStatus = inv_status,@v_vchToInvStatusID = inventory_status_id from t_wms_inventory_status where inv_status = @in_vchToStatus or description = @in_vchToStatus;
						End
					Else
						Begin
							set @v_vchToInvStatusID = @v_vchFromInvStatusID;
						End
			
					If (Isnull(@in_vchAllItem,'') = 'YES') -- ALL ITEM
						Begin
							set @v_vchParentLPN = null;
							If (isnull(@in_vchToLPN,'') <> '')
								set @v_vchLPN = @in_vchToLPN
						End
					Else If (Isnull(@in_vchAllSerial,'') = 'YES') -- ALL Serial
						Begin
							set @v_vchParentLPN = null;
							set @v_vchLPN = null;
							If (isnull(@in_vchToLPN,'') <> '')
								set @v_vchLPN = @in_vchToLPN
						End				
					Else If (Isnull(@in_vchAllLot,'') = 'YES') -- ALL Lot
						Begin
							set @v_vchParentLPN = null;
							If ((select count(distinct wh_item_master_id) from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID and isnull(parent_lpn,'') = isnull(@in_vchFromParentLPN,'') and isnull(lpn,'') = isnull(@in_vchFromLPN,'')) > 1)
								Begin
									set @v_vchLPN = null;
								End
							If (isnull(@in_vchToLPN,'') <> '')
								set @v_vchLPN = @in_vchToLPN
						End
					Else If (Isnull(@in_vchAllExpiryDate,'') = 'YES') -- ALL Expiry date
						Begin
							set @v_vchParentLPN = null;
							If ((select count(distinct lot_number) from v_wms_inventory_data where wh_master_id = @v_vchWarehouseID and location_id = @v_vchLocationID and isnull(parent_lpn,'') = isnull(@in_vchFromParentLPN,'') and isnull(lpn,'') = isnull(@in_vchFromLPN,'') and lot_number = @v_vchLot_Number) > 1)
								Begin
									set @v_vchLPN = null;
								End
							If (isnull(@in_vchToLPN,'') <> '')
								set @v_vchLPN = @in_vchToLPN
						End
					
					If (@v_vchLPNControl = 'YES')
						If(Isnull(@v_vchLPN,'') = '')
							Begin
								set @out_ErrorCode = '913';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
								Goto WRITE_PROC;
							End
					
					-- check location is mix owner?
					If (@v_vchLocationType <> 'FORK' and @v_vchMixOwner = 'NO')
						If((select COUNT(*) from t_wms_inventory 
						    inner join t_wms_owner on t_wms_inventory.owner_id = t_wms_owner.owner_id 
						    where wh_master_id = @v_vchWarehouseID 
						    and location_id = @v_vchToLocationID 
						    and t_wms_owner.owner_code <> @v_vchOwnerCode) > 0)
							Begin
								set @out_ErrorCode = '918';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_OWNER',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
								Goto WRITE_PROC;
							End
				
					-- check location is mix item?
					If (@v_vchLocationType <> 'FORK' and @v_vchMixItem = 'NO')
						If((select COUNT(*) from t_wms_inventory where wh_master_id = @v_vchWarehouseID and location_id = @v_vchToLocationID and wh_item_master_id <> @v_vchWHItemMasterID) > 0)
							Begin
								set @out_ErrorCode = '915';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
								Goto WRITE_PROC;
							End
								
					-- check location is mix lot?
					If (@v_vchLocationType <> 'FORK' and @v_vchMixLot = 'NO')
						If((select COUNT(*) from  v_wms_inventory_data where wh_master_id = @v_vchWarehouseID and location_id = @v_vchToLocationID and wh_item_master_id = @v_vchWHItemMasterID and lot_number <> @v_vchLot_Number) > 0)
							Begin
								set @out_ErrorCode = '916';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_LOT',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
								Goto WRITE_PROC;
							End
					
					-- check location is mix expiry date
					If (@v_vchLocationType <> 'FORK' and @v_vchMixExpiryDate = 'NO')
						If((select COUNT(*) from v_wms_inventory_data where wh_master_id = @v_vchWarehouseID and location_id = @v_vchToLocationID and wh_item_master_id = @v_vchWHItemMasterID and [EXPIRY_DATE] <> @v_vchExpiry_Date) > 0)
							Begin
								set @out_ErrorCode = '917';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_EXPIRY_DATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
								Goto WRITE_PROC;
							End
						
					If (isnull(@in_vchToParentLPN,'') <> '')
						set @v_vchParentLPN = @in_vchToParentLPN;
					
					--If (isnull(@v_vchItem,'') = '' or (@v_vchOldItem <> @v_vchItem))
					--	begin
					--		select @v_vchItem = item_number from v_wms_wh_item where wh_item_master_id = @v_vchWHItemMasterID
					--	end

					If (isnull(@v_vchOldWHItemMasterID,'') <> isnull(@v_vchWHItemMasterID,''))
						begin
							set @v_vchSerialControl = 'NONE';
							select @v_vchItem = item_number from t_wms_wh_item inner join t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
							 where wh_item_master_id = @v_vchWHItemMasterID

							select @v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control
							from t_wms_item inner join t_wms_owner on t_wms_item.owner_id = t_wms_owner.owner_id
							where item_number = @v_vchItem and owner_code = @v_vchOwnerCode

							select @v_vchItemUOM = uom_prompt from t_wms_item inner join t_wms_item_uom on t_wms_item.item_master_id = t_wms_item_uom.item_master_id
							 where item_number = @v_vchItem and primary_uom = 'YES'
						end

					If (@v_vchSerialControl = 'FULL' and isnull(@in_vchItem,'') = '')
						Begin-- serial control.But work case in all paren lpn,all lpn or all item
							Declare cursorInventoryData cursor for
								select	inventory_id,attribute_group_id,wh_item_master_id,owner_id,location_id,parent_lpn,lpn,lot_number,
										expiry_date,serial_number,quantity,inventory_status_id,receive_date,owner_code
								from	v_wms_inventory_data_by_serial 
								where	inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
							Open cursorInventoryData
							Fetch from cursorInventoryData Into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchWHItemMasterID,@v_vchOwner,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchSerial_Number,@v_fltQuantity,@v_vchFromInvStatusID,@v_vchReceiveDate,@v_vchOwnerCode
							While @@FETCH_STATUS = 0
								Begin
									-- manage source
									update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
									where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
					
									If(@v_vchSerialControl = 'FULL')
										Begin
											update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
											where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID and attribute_value = @v_vchSerial_Number
										End
									Else
										Begin
											update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
											where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
										End
					
									set @v_vchInventoryID = null;
									set @v_vchAttributeGroupID = null;
					
									If (@v_vchLPNControl = 'NO' and @v_vchLocationType <> 'FORK')
										Begin
											set @v_vchLPN = null;
											set @in_vchToLPN = null;
										End
									Else If (@v_vchLPN is null and @v_vchLocationType <> 'FORK')
										Begin
											set @out_ErrorCode = '913';
											select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
											Rollback Transaction;
											return;
										End

									-- manage destination
									select @v_vchInventoryID =  inventory_id,@v_vchAttributeGroupID = attribute_group_id from v_wms_inventory_data
									where wh_master_id = @v_vchWarehouseID 
									and location_id = @v_vchToLocationID and wh_item_master_id = @v_vchWHItemMasterID 
									and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,isnull(@v_vchLPN,'')) 
									and isnull(lot_number,'') = isnull(@v_vchLot_Number,'') and isnull(EXPIRY_DATE,'') = isnull(@v_vchExpiry_Date,'')
									--and isnull(SERIAL_NUMBER,'') = isnull(@v_vchSerial_Number,'')
									and inventory_status_id = @v_vchToInvStatusID

									If (isnull(@v_vchInventoryID,'') <> '')
										Begin
											update t_wms_inventory set quantity = round(round(quantity,@Round) + round(@v_fltQuantity,@Round),@Round)
											where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
							
											If(@v_vchSerialControl = 'FULL')
												Begin
													insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
													values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('SERIAL')),
													@v_vchAttributeGroupID,@v_vchSerial_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)
												End
											Else
												Begin
													update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) + round(@v_fltQuantity,@Round),@Round)
													where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
												End
										End
									Else
										Begin
											SET @v_vchInventoryID = NEWID();
											SET @v_vchAttributeGroupID  = NEWID();
							
											--
							
											select @v_vchOwnerID = owner_id from t_wms_owner where owner_code = @v_vchOwnerCode
									
											insert into t_wms_inventory(inventory_id,wh_master_id, owner_id, wh_item_master_id, location_id, inventory_status_id, inv_type, attribute_group_id, quantity, quantity_allocated,parent_lpn, lpn, receive_date, create_by)
											values(@v_vchInventoryID,@v_vchWarehouseID,@v_vchOwnerID,@v_vchWHItemMasterID,@v_vchToLocationID,@v_vchToInvStatusID,'INVENTORY',@v_vchAttributeGroupID,@v_fltQuantity,0,@v_vchParentLPN,isnull(@in_vchToLPN,@v_vchLPN),@v_vchReceiveDate,@in_vchUserID)
							
											-- insert new attribute value
											If(@v_vchSerialControl = 'FULL')
												Begin
													insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
													values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('SERIAL')),
													@v_vchAttributeGroupID,@v_vchSerial_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)
												End
											If(@v_vchLotControl = 'FULL')
												Begin
													insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
													values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('LOT')),
													@v_vchAttributeGroupID,@v_vchLot_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)				
												End
											If(@v_vchExpiryDateControl = 'FULL')
												Begin
													insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
													values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE')),
													@v_vchAttributeGroupID,@v_vchExpiry_Date,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)				
												End
										End
						
									insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
									start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
									[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
									lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
									reference_number, control_number, lpn, after_lpn,parent_lpn,after_parent_lpn, [status], after_status, zone, order_number, 
									line_number, device, create_by)
									values(@in_vchApplicationID,@in_vchTransactionType,@in_vchSubTranType,@v_vchApplicationName,@v_vchDescription,
									GETDATE(),GETDATE(),@in_vchWarehouse,@in_vchWarehouse,@in_vchFromLocation,@in_vchToLocation,
									@v_vchOwnerCode,@v_vchOwnerCode, @v_vchItem,@v_fltQuantity,@v_vchItemUOM,0,null,
									@v_vchLot_Number,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchExpiry_Date,@v_vchSerial_Number,@in_vchUserID,
									null,null,@v_vchLPN,isnull(@in_vchToLPN,@v_vchLPN),isnull(@in_vchFromParentLPN,@v_vchParentLPN),@v_vchParentLPN,@in_vchFromStatus,@in_vchToStatus,
									null,null,null,@in_vchDeviceID,@in_vchUserID)

									Fetch next from cursorInventoryData Into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchWHItemMasterID,@v_vchOwner,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchSerial_Number,@v_fltQuantity,@v_vchFromInvStatusID,@v_vchReceiveDate,@v_vchOwnerCode
								End

							Close cursorInventoryData
							Deallocate cursorInventoryData
						End
					Else
						Begin
							-- manage source
							update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
							where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
					
							If(@v_vchSerialControl = 'FULL')
								Begin
									update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
									where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID and attribute_value = @v_vchSerial_Number
								End
							Else
								Begin
									update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltQuantity,@Round),@Round)
									where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
								End
					
							set @v_vchInventoryID = null;
							set @v_vchAttributeGroupID = null;
					
							If (@v_vchLPNControl = 'NO' and @v_vchLocationType <> 'FORK')
								Begin
									set @v_vchLPN = null;
									set @in_vchToLPN = null;
								End
							Else If (@v_vchLPN is null and @v_vchLocationType <> 'FORK')
								Begin
									set @out_ErrorCode = '913';
									select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
									Rollback Transaction;
									return;
								End

							-- manage destination
							select @v_vchInventoryID =  inventory_id,@v_vchAttributeGroupID = attribute_group_id 
							from v_wms_inventory_data
							where wh_master_id = @v_vchWarehouseID 
							and location_id = @v_vchToLocationID and wh_item_master_id = @v_vchWHItemMasterID 
							and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,isnull(@v_vchLPN,'')) 
							and isnull(lot_number,'') = isnull(@v_vchLot_Number,'') and isnull(EXPIRY_DATE,'') = isnull(@v_vchExpiry_Date,'')
							and inventory_status_id = @v_vchToInvStatusID

							If (isnull(@v_vchInventoryID,'') <> '')
								Begin
									update t_wms_inventory set quantity = round(round(quantity,@Round) + round(@v_fltQuantity,@Round),@Round)
									where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
							
									If(@v_vchSerialControl = 'FULL')
										Begin
											insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
											values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('SERIAL')),
											@v_vchAttributeGroupID,@v_vchSerial_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)
										End
									Else
										Begin
											update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) + round(@v_fltQuantity,@Round),@Round)
											where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
										End
								End
							Else
								Begin
									SET @v_vchInventoryID = NEWID();
									SET @v_vchAttributeGroupID  = NEWID();
							
									--
							
									select @v_vchOwnerID = owner_id from t_wms_owner where owner_code = @v_vchOwnerCode
									
									insert into t_wms_inventory(inventory_id,wh_master_id, owner_id, wh_item_master_id, location_id, inventory_status_id, inv_type, attribute_group_id, quantity, quantity_allocated,parent_lpn, lpn, receive_date, create_by)
									values(@v_vchInventoryID,@v_vchWarehouseID,@v_vchOwnerID,@v_vchWHItemMasterID,@v_vchToLocationID,@v_vchToInvStatusID,'INVENTORY',@v_vchAttributeGroupID,@v_fltQuantity,0,@v_vchParentLPN,isnull(@in_vchToLPN,@v_vchLPN),@v_vchReceiveDate,@in_vchUserID)
							
									-- insert new attribute value
									If(@v_vchSerialControl = 'FULL')
										Begin
											insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
											values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('SERIAL')),
											@v_vchAttributeGroupID,@v_vchSerial_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)
										End
									If(@v_vchLotControl = 'FULL')
										Begin
											insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
											values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('LOT')),
											@v_vchAttributeGroupID,@v_vchLot_Number,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)				
										End
									If(@v_vchExpiryDateControl = 'FULL')
										Begin
											insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
											values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE')),
											@v_vchAttributeGroupID,@v_vchExpiry_Date,round(@v_fltQuantity,@Round),0,getdate(),@in_vchUserID)				
										End
								End
						
							insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
							start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
							[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
							lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
							reference_number, control_number, lpn, after_lpn,parent_lpn,after_parent_lpn, [status], after_status, zone, order_number, 
							line_number, device, create_by)
							values(@in_vchApplicationID,@in_vchTransactionType,@in_vchSubTranType,@v_vchApplicationName,@v_vchDescription,
							GETDATE(),GETDATE(),@in_vchWarehouse,@in_vchWarehouse,@in_vchFromLocation,@in_vchToLocation,
							@v_vchOwnerCode,@v_vchOwnerCode, @v_vchItem,@v_fltQuantity,@v_vchItemUOM,0,null,
							@v_vchLot_Number,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchExpiry_Date,@v_vchSerial_Number,@in_vchUserID,
							null,null,@v_vchLPN,isnull(@in_vchToLPN,@v_vchLPN),isnull(@in_vchFromParentLPN,@v_vchParentLPN),@v_vchParentLPN,@in_vchFromStatus,@in_vchToStatus,
							null,null,null,@in_vchDeviceID,@in_vchUserID)
						End

					If (@in_vchTransactionType = 'INV_STATUS_CHANGE' and @in_vchSubTranType = 'INV_STATUS_CHANGE' and @v_vchMovementType is not null)
						Begin
							insert into t_host_wms_interface_detail(interface_id, pstng_date, doc_date, move_type, material, plant, stge_loc, entry_qnt, entry_uom, quantity, base_uom, move_stloc)
							values(@v_vchHostInterfaceID,@v_dtDateNow,@v_dtDateNow,@v_vchMovementType,@v_vchItem,@v_vchFromPlant,@in_vchWarehouse,@v_fltQuantity,@v_vchItemUOM,@v_fltQuantity,@v_vchItemUOM,@in_vchWarehouse)
						End
					
					Set @v_vchOldLPN = @v_vchLPN;
					Set @v_vchOldInventoryStatusID = @v_vchFromInvStatusID;
					SET @v_vchOldItem = @v_vchItem;
					Set @v_vchOldWHItemMasterID = @v_vchWHItemMasterID;

					fetch next from @cursorInventory into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchWHItemMasterID,@v_vchOwner,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLot_Number,@v_vchExpiry_Date,@v_vchSerial_Number,@v_fltQuantity,@v_vchFromInvStatusID,@v_vchReceiveDate,@v_vchOwnerCode

				End
		
			If (@in_vchTransactionType = 'INV_STATUS_CHANGE' and @in_vchSubTranType = 'INV_STATUS_CHANGE' and @v_vchMovementType is not null)
				Begin
					insert into t_host_wms_interface_header(interface_id, wh_id, move_type, processing_status, user_id)
					values(@v_vchHostInterfaceID,@in_vchWarehouse,@v_vchMovementType,'PENDING',@in_vchUserID)
				End
			
			Close @cursorInventory;
			Deallocate @cursorInventory;
			set @out_ErrorCode = '0';
			select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
		Commit Transaction

		delete from t_wms_inventory where quantity <= 0 --and quantity_allocated = 0
		delete from t_wms_inventory_attribute where quantity <= 0
		Return;
		
		-----------------------------------------------------------------------------------
		--		Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = getdate();
				
				IF CURSOR_STATUS('global','@cursorInventory') >= -1
					Begin
						Close @cursorInventory;
						Deallocate @cursorInventory;
					End

				IF CURSOR_STATUS('global','cursorInventoryData') >= -1
					Begin
						Close cursorInventoryData;
						Deallocate cursorInventoryData;
					End

				set @v_vchProcessData2 = 'Item number ' + @in_vchItem;
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchDescription,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
				
				return;
		End	
	End Try
	Begin Catch
		If(@@TRANCOUNT > 0)
			Rollback Transaction
		IF CURSOR_STATUS('global','@cursorInventory') >= -1
			Begin
				Close @cursorInventory;
				Deallocate @cursorInventory;
			End

		IF CURSOR_STATUS('global','cursorInventoryData') >= -1
			Begin
				Close cursorInventoryData;
				Deallocate cursorInventoryData;
			End
			
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch	
END
