	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100),
	@in_fltMoveQty			FLOAT,
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
   
	DECLARE
	-- Error handling variables
    @c_vchObjName				NVARCHAR(30) = '[usp_inventory_move_by_sn]', -- The name that uniquely tags this object.
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
	@v_dtStartDateTime			DATETIME = GETDATE(),
    @v_dtProcessDateTime		DATETIME,
    @Round						INT,
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchBeginTrans			BIT = 0,

	@v_vchWhMasterID			VARCHAR(40),
	@v_vchWhGroup				NVARCHAR(50),
	@v_vchOwnerID				VARCHAR(40),
	@v_vchFromLocationID		VARCHAR(40),
	@v_vchWhItemMasterID		VARCHAR(40),
	@v_vchItemMasterID			VARCHAR(40),
	@v_vchInvStatus				NVARCHAR(50),
	@v_vchInvStatusID			VARCHAR(40),

	--ToLocation
	@v_vchToLocationID			VARCHAR(40),
	@v_vchLocationType			NVARCHAR(25),
	@v_vchLPNControl			NVARCHAR(3),
	@v_vchMixItem				NVARCHAR(3),
	@v_vchMixLot				NVARCHAR(3),
    @v_vchMixExpiryDate			NVARCHAR(3),
    @v_vchMixOwner				NVARCHAR(3),
	@v_vchMixStatus				NVARCHAR(3),
	@v_vchMixAttribute1			NVARCHAR(3),
	@v_vchMixAttribute2			NVARCHAR(3),
	@v_vchMixAttribute3			NVARCHAR(3),
	@v_vchMixAttribute4			NVARCHAR(3),
	@v_vchMixAttribute5			NVARCHAR(3),
	@v_vchOverrideReceiveDate	NVARCHAR(3),
	@v_fltCapacity				FLOAT = 0,	--For Check Capacity 2013-10-04
	@v_fltLPNQtyFromLocation	INT,		--For Check Capacity 2013-10-04
	@v_fltLPNQtyToLocation		INT,		--For Check Capacity 2013-10-04

	--Item Number
	@v_vchLotControl			NVARCHAR(10),
	@v_vchExpiryDateControl		NVARCHAR(10),
	@v_vchSerialControl			NVARCHAR(10),
	@v_vchAttribute1Control		NVARCHAR(10),
	@v_vchAttribute2Control		NVARCHAR(10),
	@v_vchAttribute3Control		NVARCHAR(10),
	@v_vchAttribute4Control		NVARCHAR(10),
	@v_vchAttribute5Control		NVARCHAR(10),
	@v_vchUOMPrompt				NVARCHAR(50),

	--Inventory
	@v_vchInventoryID			VARCHAR(40),
	@v_vchAttributeGroupID		NVARCHAR(40),
	@v_vchInvAttributeID		NVARCHAR(40),
	@v_vchInvAllocateQty		FLOAT,
	@v_vchInvQuantity			FLOAT,
	@v_vchInvReceiveDate		DATE

	BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT						 
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
		SELECT @v_vchWhMasterID = wh_master_id, @v_vchWhGroup = wh_group FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwnerCode AND is_active = 'YES'
		SELECT @v_vchFromLocationID = location_id 
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWhMasterID 
		AND location = @in_vchFromLocation
		AND is_active = 'YES'
	
		--------------------------------------------
		--Validate To location
		--------------------------------------------
		SELECT @v_vchToLocationID = location_id
			,@v_vchLocationType = loc_type
			,@v_vchLPNControl = lpn_controlled
			,@v_vchMixItem = mix_items
			,@v_vchMixLot = mix_lot
			,@v_vchMixExpiryDate = mix_expiry_dates
			,@v_vchMixOwner = mix_owners
			,@v_vchOverrideReceiveDate = override_receive_date
			,@v_fltCapacity = ISNULL(capacity_qty,0)
			,@v_vchMixStatus = mix_status
			,@v_vchMixAttribute1 = mix_attribute1
			,@v_vchMixAttribute2 = mix_attribute2
			,@v_vchMixAttribute3 = mix_attribute3
			,@v_vchMixAttribute4 = mix_attribute4
			,@v_vchMixAttribute5 = mix_attribute5
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWhMasterID 
		AND location = @in_vchToLocation
		AND loc_type <> 'STORE'		--Move LFAsia äÁèËéÒÁä»ÇÒ§·Õè location store
		AND is_active = 'YES'

		IF (ISNULL(@v_vchToLocationID,'') = '')
			BEGIN
				SET @out_ErrorCode = '905';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--------------------------------------------
		-- Check duplicate parent lpn.
		--------------------------------------------
		IF (ISNULL(@in_vchToParentLPN,'') <> '')
			BEGIN
				IF EXISTS(SELECT location_id FROM t_wms_inventory
						   WHERE wh_master_id = @v_vchWhMasterID 
						   AND (location_id <> @v_vchFromLocationID 
						   AND location_id <> @v_vchToLocationID) 
						   AND parent_lpn = @in_vchToParentLPN)
					BEGIN
						SET @out_ErrorCode = '901';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_LPN_DUPLICATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToParentLPN,'@param2','@param3','@param4','@param5')
						Goto WRITE_PROC;
					END
			END

		--------------------------------------------
		-- Check duplicate lpn.
		--------------------------------------------
		IF (ISNULL(@in_vchToLPN,'') <> '')
			BEGIN
				DECLARE @v_vchDubParentLPN	NVARCHAR(50),
						@v_vchDubLocation	NVARCHAR(50)
					
				IF (ISNULL(@in_vchFromParentLPN,'') <> '' OR ISNULL(@in_vchToParentLPN,'') <> '')
					BEGIN
						SELECT TOP 1 @v_vchDubParentLPN = parent_lpn FROM t_wms_inventory 
									WHERE wh_master_id = @v_vchWhMasterID 
									AND (ISNULL(parent_lpn,'') <> ISNULL(@in_vchFromParentLPN,'') 
									AND ISNULL(parent_lpn,'') <> ISNULL(@in_vchToParentLPN,'')) 
									AND lpn = @in_vchToLPN
						IF (ISNULL(@v_vchDubParentLPN,'') <> '')
							BEGIN
								SET @out_ErrorCode = '901';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_PL',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLPN,@v_vchDubParentLPN,'@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchDubLocation = location_id FROM t_wms_inventory 
						WHERE wh_master_id = @v_vchWhMasterID 
						AND (location_id <> @v_vchFromLocationID AND location_id <> @v_vchToLocationID)
						AND lpn = @in_vchToLPN
						IF (ISNULL(@v_vchDubLocation,'') <> '')
							BEGIN
								SELECT @v_vchDubLocation = location from t_wms_location where location_id = @v_vchDubLocation
								SET @out_ErrorCode = '901';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'FOUND_LPN_IN_OTHER_LOCATION',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLPN,@v_vchDubLocation,'@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
			END

		--------------------------------------------
		-- Validate Item Number
		--------------------------------------------
		IF (ISNULL(@in_vchItemNumber,'') <> '')
			BEGIN
				SELECT @v_vchItemMasterID = item.item_master_id
					,@v_vchLotControl = item.lot_control
					,@v_vchExpiryDateControl = item.expiry_date_control
					,@v_vchSerialControl = item.sn_control 
					,@v_vchAttribute1Control = item.attribute1_control
					,@v_vchAttribute2Control = item.attribute2_control
					,@v_vchAttribute3Control = item.attribute3_control
					,@v_vchAttribute4Control = item.attribute4_control
					,@v_vchAttribute5Control = item.attribute5_control
				FROM t_wms_item item
				LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
				WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
				AND item.owner_id = @v_vchOwnerID

				IF (ISNULL(@v_vchItemMasterID,'') = '')
					BEGIN
						SET @out_ErrorCode = '902';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				------------------------------------------
				--Get Primary UOM
				------------------------------------------
				SELECT @v_vchUOMPrompt = uom_prompt FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND primary_uom = 'YES' AND is_active = 'YES'

				------------------------------------------
				-- Wh item master id
				------------------------------------------
				SELECT @v_vchWhItemMasterID = wh_item_master_id 
				FROM t_wms_wh_item 
				WHERE wh_master_id = @v_vchWhMasterID 
				AND item_master_id = @v_vchItemMasterID
			END
		
		IF @v_vchSerialControl = 'FULL'
			BEGIN
				SET @in_fltMoveQty = 1;
			END

		------------------------------------------------
		-- Get Expiry Date, Inv status
		-- LFAsia >> äÁèÁÕ¡ÒÃÊè§ Expiry Date ÁÒã¹ Barcode 2D
		------------------------------------------------
		SELECT @in_vchExpiryDate = expiry_date
			,@v_vchInvStatusID = inventory_status_id
			,@v_vchInvStatus = inv_status
		FROM v_wms_inventory_data_by_serial_mini
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND location_id = @v_vchFromLocationID
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

		------------------------------------------------
		-- Valdate Get Allocate Qty
		------------------------------------------------
		SELECT @v_vchInvAllocateQty = quantity_allocated
		FROM v_wms_inventory_data_mini
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND location_id = @v_vchFromLocationID
		AND inv_status = @v_vchInvStatus
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		IF (@v_vchInvAllocateQty > 0)
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_HAVE_QUANITY_ALLOCATE',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchItemNumber,'@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		-------------------------------------------------
		-- Check lpn capacity in to location 2013-10-04
		-------------------------------------------------
		IF (@v_fltCapacity > 0)
			BEGIN
				-- Count LPN From Source Location
				SELECT COUNT (DISTINCT lpn) FROM t_wms_inventory 
				WHERE wh_master_id = @v_vchWhMasterID
				AND location_id = @v_vchFromLocationID
				AND inventory_status_id = @v_vchInvStatusID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')

				-- Count LPN From Destination Location
				SELECT COUNT (DISTINCT lpn) FROM t_wms_inventory 
				WHERE wh_master_id = @v_vchWhMasterID
				AND location_id = @v_vchToLocationID
				AND inventory_status_id = @v_vchInvStatusID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')

				--¢Í§·ÕèÂéÒÂÁÒ + ¢Í§à´ÔÁ·ÕèÍÂÙèã¹ Location ¶éÒÁÒ¡¡ÇèÒµéÍ§ Error
				IF (ISNULL(@v_fltLPNQtyFromLocation,0) + ISNULL(@v_fltLPNQtyToLocation,0) > @v_fltCapacity)
					BEGIN
						SET @out_ErrorCode = '989';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_IS_FULL_CAPACITY',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-------------------------------------------------
		-- Check Receive Date
		-------------------------------------------------
		IF (@v_vchLocationType <> 'FORK')
			BEGIN
				IF (@v_vchOverrideReceiveDate = 'NO')
					BEGIN
						IF ((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_MIX_RECEIVE_DATE' AND is_active = 'YES') = 'NO')
							BEGIN
								IF EXISTS(SELECT receive_date FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchToLocationID)
									BEGIN
										DECLARE @v_vchChkReceiveDate DATE
										SELECT @v_vchChkReceiveDate = receive_date FROM t_wms_inventory
										WHERE wh_master_id = @v_vchWhMasterID
										AND inventory_status_id = @v_vchInvStatusID
										AND wh_item_master_id = @v_vchWhItemMasterID
										AND parent_lpn = @in_vchFromParentLPN
										AND lpn = @in_vchFromLPN
										AND location_id = @v_vchFromLocationID
										AND receive_date NOT IN (SELECT receive_date FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchToLocationID)

										IF (ISNULL(@v_vchChkReceiveDate,'') <> '')
											BEGIN
												SET @out_ErrorCode = '914';
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CAN_NOT_MIXED_RECEIVE_DATE',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;
											END
									END
							END
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchInvReceiveDate = receive_date FROM t_wms_inventory 
						WHERE wh_master_id = @v_vchWhMasterID 
						AND location_id = @v_vchFromLocationID
						IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_NEW_RECEIVE_DATE') <> 'OLD')
							BEGIN
								UPDATE t_wms_inventory SET receive_date = @v_vchInvReceiveDate
								WHERE wh_master_id = @v_vchWhMasterID 
								AND location_id = @v_vchToLocationID
							END
					End
			END
			
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;

		-------------------------------------------
		-- Check LPN is empty
		-------------------------------------------
		IF (ISNULL(@in_vchToLPN,ISNULL(@in_vchFromLPN,'')) = '' AND @v_vchLPNControl = 'YES')
			BEGIN 
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_EMPTY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-------------------------------------------
		-- Check Mix Status
		-------------------------------------------
		IF (@v_vchMixStatus = 'NO')
			BEGIN
				IF EXISTS(SELECT TOP 1 inventory_status_id FROM t_wms_inventory WHERE inventory_status_id <> @v_vchInvStatusID AND wh_master_id = @v_vchWhMasterID 
						 AND location_id = @v_vchToLocationID)
					BEGIN
						SET @out_ErrorCode = '999';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_STATUS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
						Goto WRITE_PROC;
					END
			END
		-------------------------------------------
		-- Check location is mix owner?
		-------------------------------------------
		IF (@v_vchLocationType <> 'FORK' AND @v_vchMixOwner = 'NO')
			BEGIN
				If EXISTS (SELECT inventory_id FROM t_wms_inventory 
							WHERE wh_master_id = @v_vchWhMasterID 
							AND location_id = @v_vchToLocationID 
							AND owner_id <> @v_vchOwnerID)
					BEGIN
						SET @out_ErrorCode = '918';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_OWNER',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
				
		-------------------------------------------
		-- check location is mix item?
		-------------------------------------------
		IF (@v_vchLocationType <> 'FORK' AND @v_vchMixItem = 'NO')
			BEGIN
				IF EXISTS(SELECT inventory_id FROM t_wms_inventory 
						  WHERE wh_master_id = @v_vchWhMasterID 
						  AND location_id = @v_vchToLocationID 
						  AND wh_item_master_id <> @v_vchWhItemMasterID)
					BEGIN
						SET @out_ErrorCode = '915';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-------------------------------------------	
		-- check location is mix lot?
		-------------------------------------------
		IF (@v_vchLocationType <> 'FORK' and @v_vchMixLot = 'NO')
			BEGIN
				IF EXISTS(SELECT inv.inventory_id FROM t_wms_inventory inv
						  LEFT JOIN (SELECT inventory_id
										,attribute_group_id
										,attribute_value AS lot_number
									 FROM dbo.t_wms_inventory_attribute
									 WHERE inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70'
									 ) AS invLot ON (inv.inventory_id = invLot.inventory_id) AND (inv.attribute_group_id = invLot.attribute_group_id) 
						  WHERE inv.wh_master_id = @v_vchWhMasterID 
						  AND inv.location_id = @v_vchToLocationID 
						  AND inv.wh_item_master_id = @v_vchWhItemMasterID
						  AND invLot.lot_number <> @in_vchLotNumber)
					BEGIN
						SET @out_ErrorCode = '916';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_LOT',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-------------------------------------------	
		-- check location is mix expiry date
		-------------------------------------------
		IF (@v_vchLocationType <> 'FORK' and @v_vchMixExpiryDate = 'NO')
			BEGIN
				IF EXISTS(SELECT inv.inventory_id FROM t_wms_inventory inv
						  LEFT JOIN (SELECT inventory_id
						  				,attribute_group_id
						  				,attribute_value AS expiry_date
						  		   FROM dbo.t_wms_inventory_attribute
						  		   WHERE inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248'
						  		   ) AS invExp ON (inv.inventory_id = invExp.inventory_id) AND (inv.attribute_group_id = invExp.attribute_group_id) 
						  WHERE inv.wh_master_id = @v_vchWhMasterID 
						  AND inv.location_id = @v_vchToLocationID 
						  AND inv.wh_item_master_id = @v_vchWhItemMasterID
						  AND invExp.expiry_date <> @in_vchExpiryDate)
					BEGIN
						SET @out_ErrorCode = '917';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_MIX_EXPIRY_DATE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		----------------------------------------
		-- Manage source
		----------------------------------------
		BEGIN
			SET @v_vchInventoryID = NULL;
			SET @v_vchAttributeGroupID = NULL;
			SET @v_vchInvReceiveDate = NULL;
			SET @v_vchInvQuantity = NULL;
			SELECT @v_vchInventoryID = inventory_id
				  , @v_vchAttributeGroupID = attribute_group_id
				  , @v_vchInvReceiveDate = receive_date
				  , @v_vchInvQuantity = quantity
			FROM v_wms_inventory_data_by_serial
			WHERE wh_master_id = @v_vchWhMasterID
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND location_id = @v_vchFromLocationID
			AND inventory_status_id = @v_vchInvStatusID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			--AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

			IF (ISNULL(@v_vchInventoryID,'') = '')
				BEGIN
					SET  @out_ErrorCode = '999'
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

			--Inventory
			UPDATE t_wms_inventory set quantity = ROUND(ROUND(quantity,@Round) - ROUND(@in_fltMoveQty,@Round),@Round)
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID
					
			--Inventory attribute for serial number
			IF (@v_vchSerialControl = 'FULL')
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@in_fltMoveQty,@Round),@Round)
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND attribute_value = @in_vchSerialNumber
				END

			--Inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@in_fltMoveQty,@Round),@Round)
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END
		END
		----------------------------------------
		-- Manage Destination
		----------------------------------------
		BEGIN
			SET @v_vchInventoryID = NULL;
			SET @v_vchAttributeGroupID = NULL;
			SELECT	@v_vchInventoryID = inventory_id
				,@v_vchAttributeGroupID = attribute_group_id
			FROM v_wms_inventory_data_mini
			WHERE wh_master_id = @v_vchWhMasterID 
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND location_id = @v_vchToLocationID
			AND inventory_status_id = @v_vchInvStatusID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchToLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			

			EXEC usp_manage_inventory
				@in_vchApplicationID			= @in_vchApplicationID
				,@in_vchWarehouseMasterID		= @v_vchWhMasterID
				,@in_vchWarehouseItemMasterID	= @v_vchWhItemMasterID
				,@in_vchLocationID				= @v_vchToLocationID
				,@in_vchLocation				= @in_vchToLocation
				,@in_vchStatusID				= @v_vchInvStatusID
				,@in_vchLPN						= NULL
				,@in_vchLotNumber				= @in_vchLotNumber
				,@in_vchExpiryDate				= @in_vchExpiryDate
				,@in_vchSerialNumber			= @in_vchSerialNumber
				,@in_fltQty						= @in_fltMoveQty
				,@in_fltQtyAllocate				= 0
				,@in_fltQtyIncoming				= 0
				,@in_vchOwner					= @in_vchOwnerCode
				,@in_vchInventoryType			= 'INVENTORY'
				,@in_vchPalentLPN				= NULL
				,@in_vchUserID					= @in_vchUserID
				,@in_vchReceiveDate				= @v_vchInvReceiveDate
				,@in_vchInventoryID				= @v_vchInventoryID		 OUTPUT
				,@in_vchAttributeGroupID		= @v_vchAttributeGroupID OUTPUT
				,@in_vchErrorCode				= @out_ErrorCode		 OUTPUT
				,@in_vchMessage					= @out_ErrorMessage		 OUTPUT
														
			IF (@out_ErrorCode <> '0')
				GOTO WRITE_PROC;
							
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					EXEC usp_manage_inventory_attribute
						@in_vchApplicationID		= @in_vchApplicationID
						,@in_vchItem				= @in_vchItemNumber
						,@in_vchSerialNo			= @in_vchSerialNumber 	
						,@in_vchLot					= @in_vchLotNumber
						,@in_vchExpiryDate			= @in_vchExpiryDate
						,@in_vchAttribute1			= @in_vchAttribute1
						,@in_vchAttribute2			= @in_vchAttribute2
						,@in_vchAttribute3			= @in_vchAttribute3
						,@in_vchAttribute4			= @in_vchAttribute4
						,@in_vchAttribute5			= @in_vchAttribute5
						,@in_fltQty					= @in_fltMoveQty
						,@in_fltQtyAllocate			= 0
						,@in_fltQtyIncoming			= 0
						,@in_vchInventoryID			= @v_vchInventoryID
						,@in_vchAttributeGroupID	= @v_vchAttributeGroupID
						,@in_vchLotControl			= @v_vchLotControl
						,@in_vchSNControl			= @v_vchSerialControl
						,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
						,@in_vchAttribute1Control	= @v_vchAttribute1Control
						,@in_vchAttribute2Control	= @v_vchAttribute2Control
						,@in_vchAttribute3Control	= @v_vchAttribute3Control
						,@in_vchAttribute4Control	= @v_vchAttribute4Control
						,@in_vchAttribute5Control	= @v_vchAttribute5Control
						,@in_vchUserID				= @in_vchUserID
						,@in_vchErrorCode			= @out_ErrorCode    OUTPUT
						,@in_vchMessage				= @out_ErrorMessage	OUTPUT
																		
					IF(@out_ErrorCode <> '0')
					BEGIN
						GOTO WRITE_PROC;
					END
				END
		END

		IF (ISNULL(@in_vchLotNumber,'') = '')
			BEGIN
				SET @in_vchLotNumber = NULL
			END
		IF (ISNULL(@in_vchExpiryDate,'') = '')
			BEGIN
				SET @in_vchExpiryDate = NULL
			END
		IF (ISNULL(@in_vchAttribute1,'') = '')
			BEGIN
				SET @in_vchAttribute1 = NULL
			END
		IF (ISNULL(@in_vchAttribute2,'') = '')
			BEGIN
				SET @in_vchAttribute2 = NULL
			END
		IF (ISNULL(@in_vchAttribute3,'') = '')
			BEGIN
				SET @in_vchAttribute3 = NULL
			END
		IF (ISNULL(@in_vchAttribute4,'') = '')
			BEGIN
				SET @in_vchAttribute4 = NULL
			END
		IF (ISNULL(@in_vchAttribute5,'') = '')
			BEGIN
				SET @in_vchAttribute5 = NULL
			END
		IF (ISNULL(@in_vchFromParentLPN,'') = '')
			BEGIN
				SET @in_vchFromParentLPN = NULL
			END
		IF (ISNULL(@in_vchToParentLPN,'') = '')
			BEGIN
				SET @in_vchToParentLPN = NULL
			END
		IF (ISNULL(@in_vchFromLPN,'') = '')
			BEGIN
				SET @in_vchFromLPN = NULL
			END
		IF (ISNULL(@in_vchToLPN,'') = '')
			BEGIN
				SET @in_vchToLPN = NULL
			END


		INSERT INTO t_com_tran_log
				(app_id
				, tran_type
				, sub_tran_type
				, [app_name]
				, [description]
				, start_tran_datetime
				, end_tran_datetime
				, warehouse
				, to_warehouse
				, location
				, to_location
				, [owner]
				, to_owner
				, item_number
				, quantity
				, quantity_uom
				, after_quantity
				, after_quantity_uom
				, lot_number
				, after_lot_number
				, [expiry_date]
				, after_expiry_date
				, serial_number
				, [attribute1]
				, [after_attribute1]
				, [attribute2]
				, [after_attribute2]
				, [attribute3]
				, [after_attribute3]
				, [attribute4]
				, [after_attribute4]
				, [attribute5]
				, [after_attribute5]
				, [user_id]
				, reference_number
				, control_number
				, parent_lpn
				, after_parent_lpn
				, lpn, after_lpn
				, [status]
				, after_status
				, zone
				, order_number
				, line_number
				, device
				, create_by)
			VALUES
				(@in_vchApplicationID
				,'INV_MOVE'
				,'MOVE_SN_DEST'
				,@v_vchApplicationName
				,'Putaway item by serial number'
				,@v_dtStartDateTime
				,GETDATE()
				,@in_vchWarehouse
				,@in_vchWarehouse
				,@in_vchFromLocation
				,@in_vchToLocation
				,@in_vchOwnerCode
				,@in_vchOwnerCode
				,@in_vchItemNumber
				,@in_fltMoveQty
				,@v_vchUOMPrompt
				,ROUND(@in_fltMoveQty - @v_vchInvQuantity,@Round)
				,@v_vchUOMPrompt
				,@in_vchLotNumber
				,@in_vchLotNumber
				,@in_vchExpiryDate
				,@in_vchExpiryDate
				,@in_vchSerialNumber
				,@in_vchAttribute1
				,@in_vchAttribute1
				,@in_vchAttribute2
				,@in_vchAttribute2
				,@in_vchAttribute3
				,@in_vchAttribute3
				,@in_vchAttribute4
				,@in_vchAttribute4
				,@in_vchAttribute5
				,@in_vchAttribute5
				,@in_vchUserID
				,NULL
				,NULL
				,@in_vchFromParentLPN
				,@in_vchToParentLPN
				,@in_vchFromLPN
				,@in_vchToLPN
				,@v_vchInvStatus
				,@v_vchInvStatus
				,NULL
				,NULL
				,NULL
				,@in_vchDeviceID
				,@in_vchUserID)
						
		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		DELETE FROM t_wms_inventory WHERE quantity <= 0
		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
		RETURN;
		
		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
				SET @v_dtProcessDateTime = GETDATE();	
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_vchProcessData2 = 'Item number ' + @in_vchItemNumber;
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchProcessData3,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
				RETURN;
		END	
	END TRY
	BEGIN CATCH
		IF(@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH	
END


/*FOR TEST

DECLARE @v_vchErrorCode		nvarchar(50),
		@v_vchErrorMsg		nvarchar(500)

