/****** Object:  StoredProcedure [dbo].[usp_inventory_snapshot]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Kritsada Baothong
-- Create date: 2016-02-27
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_inventory_snapshot]
	-- Add the parameters for the stored procedure here	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE @data_to_write NVARCHAR(MAX) = ''
	DECLARE @file_name_path NVARCHAR(100) = '\\Wms_db\wms2ax\SOH_'+CONVERT(VARCHAR(8), GETDATE(), 112) + CONVERT(VARCHAR,DATEPART(hh,GETDATE())) + CONVERT(VARCHAR,DATEPART(MINUTE,GETDATE())) + CONVERT(VARCHAR,DATEPART(ss,GETDATE())) +  CONVERT(VARCHAR,DATEPART(MILLISECOND,GETDATE()))+'.txt'
	--DECLARE @RS_zone NVARCHAR(50)
	DECLARE @RS_location NVARCHAR(50)
	DECLARE @RS_item_number NVARCHAR(50)
	--DECLARE @RS_description NVARCHAR(200)
	--DECLARE @RS_lot_number NVARCHAR(100)
	--DECLARE @RS_expiry_date NVARCHAR(100)
	--DECLARE @RS_serial_number NVARCHAR(100)
	DECLARE @RS_quantity FLOAT
	--DECLARE @RS_inv_status NVARCHAR(50)	

    DECLARE CS_INV CURSOR FOR		
		select R1.location, R1.item_number, R1.quantity from (
			-- ดึง Item ที่มีอยู่ใน Inventory
			select 
				-- ถ้า ax_location เป็น null แสดงว่าอยู่ใน STG
				loc.erp_location as [location]
				, inv.location_id
				, item.item_number
				, sum(inv.quantity) as quantity	
			from t_wms_wh_item wh_item
			left join t_wms_item item on item.item_master_id = wh_item.item_master_id
			left join t_wms_inventory inv on inv.wh_item_master_id = wh_item.wh_item_master_id
			left join t_wms_location loc on loc.location_id = inv.location_id
			where inv.location_id is not null
			group by loc.erp_location , inv.location_id, item.item_number

			union

			-- ดึง Item ที่ไม่มีอยู่ใน Inventory แต่มีอยู่ใน Log
			-- ถ้าไม่มีแสดงว่า item นั้นไม่มีการ Movement มีแต่ข้อมุลใน item master 
			-- อย่างเดียวจะไม่แสดง
			select 
				wms_log.erp_location as [location]
				, inv.location_id
				, item.item_number
				, 0 as quantity	
			from t_wms_wh_item wh_item
			left join t_wms_item item on item.item_master_id = wh_item.item_master_id
			left join t_wms_inventory inv on inv.wh_item_master_id = wh_item.wh_item_master_id
			left join (
				SELECT 
					loc_map.erp_location
					, t_com_tran_log.item_number
					,ROW_NUMBER() OVER(PARTITION BY t_com_tran_log.item_number ORDER BY t_com_tran_log.create_date DESC) AS is_max
				FROM t_com_tran_log
				left join t_wms_location loc_map on loc_map.location = t_com_tran_log.[location]
				WHERE t_com_tran_log.tran_type = 'OO_PICK'
			) wms_log ON wms_log.item_number = item.item_number and wms_log.is_max = 1
			where inv.location_id is null and wms_log.erp_location is not null
			group by wms_log.erp_location, inv.location_id, item.item_number
		)R1
		order by R1.location, R1.item_number asc
    OPEN CS_INV          
    FETCH NEXT FROM CS_INV
        INTO @RS_location, @RS_item_number, @RS_quantity
    WHILE @@FETCH_STATUS = 0
    BEGIN    
        -- BEGIN FOR LIST INSTRUCTION SET
		SET @data_to_write = @data_to_write	+ (
				--ISNULL(REPLACE(@RS_zone,CHAR(13)+CHAR(10),''),'') + '|'
				ISNULL(@RS_location,'') + '|'
				+ ISNULL(@RS_item_number,'') + '|'
				--+ ISNULL(@RS_description,'') + '|'
				--+ ISNULL(@RS_lot_number,'') + '|'
				--+ ISNULL(@RS_expiry_date,'') + '|'
				--+ ISNULL(@RS_serial_number,'') + '|'
				+ ISNULL(CONVERT(NVARCHAR,@RS_quantity),'')
				--+ ISNULL(@RS_inv_status,'')
				+ CHAR(13)+CHAR(10)
			)
			--print  REPLACE(@RS_zone,CHAR(13)+CHAR(10),'')+','
        -- END FOR LIST INSTRUCTION SET            
        FETCH NEXT FROM CS_INV
            INTO @RS_location, @RS_item_number, @RS_quantity
    END
    CLOSE CS_INV    
    DEALLOCATE CS_INV

	--PRINT @file_name_path
	--PRINT @data_to_write
	
	--EXEC	[dbo].[usp_printing_save_text_tofile]
	--		@TheString = @data_to_write,
	--		@Filename = @file_name_path,
	--		@Unicode = 1

	EXEC	[dbo].[sp_create_text]
	@File = @file_name_path,
	@Text = @data_to_write
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_inventory_un_allocate]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_inventory_un_allocate]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouseMasterID	UNIQUEIDENTIFIER,
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchParentLPN			NVARCHAR(25) = NULL,
	@in_vchLPN					NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER,
	@in_fltQuantity				FLOAT,
	@in_vchSerialNumber			NVARCHAR(100),
	@in_vchLotNumber			NVARCHAR(100),
	@in_vchExpiryDate			NVARCHAR(100),
	@in_vchAttribute1			NVARCHAR(100),
	@in_vchAttribute2			NVARCHAR(100),
	@in_vchAttribute3			NVARCHAR(100),
	@in_vchAttribute4			NVARCHAR(100),
	@in_vchAttribute5			NVARCHAR(100),
	@in_dtReceiveDate			DATE,
	@in_vchDefaultItemStatus	NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round					INT,
			@v_fltStockQty			FLOAT,
			@v_fltStockQtyAllocate	FLOAT,
			@v_vchInventoryID		UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID	UNIQUEIDENTIFIER = NULL,
			@v_vchInventoryStatusID	UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber		NVARCHAR(50) = NULL,
			@v_vchLotControl		VARCHAR(5) = NULL,
			@v_vchSNControl			VARCHAR(5) = NULL,
			@v_vchExpiryDateControl	VARCHAR(5) = NULL,
			@v_vchAttribute1Control	VARCHAR(5) = NULL,
			@v_vchAttribute2Control	VARCHAR(5) = NULL,
			@v_vchAttribute3Control	VARCHAR(5) = NULL,
			@v_vchAttribute4Control	VARCHAR(5) = NULL,
			@v_vchAttribute5Control	VARCHAR(5) = NULL,
			@v_vchWhID				NVARCHAR(25) = NULL

	BEGIN TRY
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT @v_vchInventoryStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchDefaultItemStatus AND is_active = 'YES'
		SELECT @v_vchWhID = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWarehouseMasterID
		SELECT @v_vchItemMasterID = item.item_master_id 
			,@v_vchItemNumber = item.item_number
			,@v_vchLotControl = item.lot_control
			,@v_vchExpiryDateControl = item.expiry_date_control
			,@v_vchSNControl = item.sn_control
			,@v_vchAttribute1Control = item.attribute1_control
			,@v_vchAttribute2Control = item.attribute2_control
			,@v_vchAttribute3Control = item.attribute3_control
			,@v_vchAttribute4Control = item.attribute4_control
			,@v_vchAttribute5Control = item.attribute5_control
		FROM t_wms_wh_item whItem
		INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
		WHERE wh_item_master_id = @in_vchWHItemMasterID

		SELECT @v_vchInventoryID = inventory_id
			,@v_vchAttributeGroupID = attribute_group_id
			,@v_fltStockQty = quantity
			,@v_fltStockQtyAllocate = quantity_allocated 
		FROM v_wms_inventory_data_by_id 
		WHERE wh_master_id = @in_vchWarehouseMasterID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWHItemMasterID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND ISNULL(lot_number,'')  = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'')  = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'')  = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'')  = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'')  = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'')  = ISNULL(@in_vchAttribute5,'')
		AND inventory_status_id = @v_vchInventoryStatusID
		AND receive_date = @in_dtReceiveDate
		
		IF (ROUND(@in_fltQuantity,@Round) > ROUND(@v_fltStockQtyAllocate,@Round))
			BEGIN
				SET @in_fltQuantity = ROUND(@v_fltStockQtyAllocate,@Round);
			END

		BEGIN
			-- update quantity allocate in inventory
			UPDATE t_wms_inventory SET quantity_allocated = ROUND((ISNULL(quantity_allocated,0) - @in_fltQuantity),@Round)
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID
			
			-- update quantity allocate in inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((ISNULL(quantity_allocated,0) - @in_fltQuantity),@Round)
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END
			SET @out_ErrorCode = '0';
		END
	END TRY
	BEGIN CATCH
		IF (ISNULL(@out_ErrorCode,'') = '')
			SET @out_ErrorCode = ERROR_NUMBER();
		IF (ISNULL(@out_ErrorMessage,'') = '')
			SET @out_ErrorMessage = ERROR_MESSAGE();

		DECLARE @v_dtProcessDateTime DATETIME = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWhID,
			@in_vchDevice = 'UNALLOCATE',
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = 'usp_inventory_un_allocate',
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchItemNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = @out_ErrorCode,
			@in_vchData4 = @out_ErrorMessage,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_InventorySnapshot]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_InventorySnapshot]
@in_vchWhID 	NVARCHAR(25) = NULL,
@in_vchCountID	NVARCHAR(40) = NULL,
@in_vchUserID	NVARCHAR(10) = NULL,
@in_vchDevice	NVARCHAR(50)			--Required

AS

BEGIN
	DECLARE 
    -- Error handling variables
    @c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
    @v_intSqlErrorNumber    INTEGER,
    @v_intSqlErrorLine		INTEGER,
    @v_intSqlErrorState		INTEGER,
    @v_intSqlErrorSeverity	INTEGER,
    @v_vchSqlErrorMessage	NVARCHAR(2048),
    @v_vchSqlErrorProcedure NVARCHAR(200),  
    @v_vchProcessData1		NVARCHAR(1000),
    @v_vchProcessData2		NVARCHAR(1000),
    @v_vchProcessData3		NVARCHAR(1000),
    @v_vchProcessData4		NVARCHAR(1000),
    @v_nRowCount            INTEGER,
    @v_vchMessage           NVARCHAR(100),
    @v_nReturn              INTEGER,
    @v_vchWhID				NVARCHAR(25),
    @v_vchErrorNumber       NVARCHAR(25),
    @v_vchErrorCode			NVARCHAR(200),
    @v_vchUserID			NVARCHAR(10), 
    @v_vchApplicationID		NVARCHAR(40),
    @v_intLocale			INTEGER = 1033, 
    @v_vchStatus			NVARCHAR(200),
    @v_vchLogType			NVARCHAR(50),
    
    --  Log Handling Variables
    @v_intLogLevel          INTEGER = 5,  -- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
    @v_vchLogAction       NVARCHAR(25) = 'PRINT', --- PRINT, LOG, 
    
    -- Local Variables
    @v_nCount               INTEGER,
    @v_chStatus             NCHAR(1),
    @v_vchItem              NVARCHAR(30),
    @v_nSeq                 INTEGER,
    @v_vchHostRecordID		varchar(40),
    
    -- Table Variables
    @v_vchCountID				NVARCHAR(40),
    @v_vchTranType				NVARCHAR(10),
    @v_vchSubType				NVARCHAR(10),
    @v_vchTranLog				NVARCHAR(3),
    @v_vchProcessLog			NVARCHAR(3),
    @v_vchWinEventViewer		NVARCHAR(3),
    @v_vchHostInterfaceManager	NVARCHAR(3),
    @v_vchIsActive				NVARCHAR(3)
    
    
    -- Output Variables
    SET NOCOUNT ON
    
    -- Set Constants
    SET @c_vchObjName = 'usp_InventorySnapshot'; 
    SET @v_vchLogType = 'EXPORT_ERROR';
    SET @v_vchWhID = @in_vchWhID;
    SET @v_vchTranType = ISNULL(@v_vchCountID, CONVERT(NVARCHAR(12), GETDATE()));
        
    BEGIN TRY
   		------------------------------------------------------------
		--  Check Required Field and Set Defaults
		------------------------------------------------------------
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Initial Required Fields'
		-- Future, Add a Log action for inserting into the Process Log	
		
		-----------------------------------------------------------
		--  User ID cannot be NULL.  Set to a Default to 'OGA'
		------------------------------------------------------------
		IF @in_vchUserID IS NULL
		BEGIN
			if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Setting Default User ID = OGA'
			-- Future, Add a Log action for inserting into the Process Log
		
			SET @v_vchUserID = 'SYSTEM'
		END
		ELSE
		BEGIN
			if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Setting User ID =:['+@in_vchUserID+']'
			-- Future, Add a Log action for inserting into the Process Log

			SET @v_vchUserID = @in_vchUserID
		END

   			    
   		------------------------------------------------------------
		--  Insert into Inventory Export Table
		------------------------------------------------------------
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Into the Inventory Export Table'
			-- Future, Add a Log action for inserting into the Process Log
			
		--------------------------------------------------------------
		----  Insert into Inventory Export Table for a ALL Warehouses
		--------------------------------------------------------------			
		if @v_vchWHID IS NULL
		BEGIN	
			INSERT INTO t_host_wms_inventory_export
           ([tran_code]
           ,[processing_code]
           ,[processing_status]
           ,[wh_id]
           ,[owner_id]
           ,[item_number]
           ,[uom]
           ,[location]
           ,[quantity_sign]
           ,[quantity]
           ,[inventory_status]
           ,[inventory_type]
           ,[lot_number]
           ,[expiry_date]
           ,[serial_number]
		   ,[parent_lpn]
           ,[lpn]
		   --,[user_def1]
		   --,[user_def2]
		   --,[user_def3]
		   --,[user_def4]
		   --,[user_def5]
		   --,[user_def6]
		   --,[user_def7]
		   --,[user_def8]
		   --,[user_def9]
		   --,[user_def10]
           ,[create_date]
           ,[create_by]
           )
		  select @v_vchTranType
			,'ADD'
			,'PENDING'
			,wh_id
			,owner_code
			,item_number
			,uom
			,location
			,'+'
			,SUM(quantity)
			,inv_status
			,inv_type
			,lot_number
			,EXPIRY_DATE
			,SERIAL_NUMBER
			,parent_lpn
			,lpn
			,GETDATE()
			,@v_vchUserID
		from v_wms_inventory_data
		GROUP BY wh_id, owner_code,location, item_number, inv_status, inv_type,uom,lot_number,EXPIRY_DATE,SERIAL_NUMBER,parent_lpn,lpn
		END
	
		------------------------------------------------------------
		--  Insert into Inventory Export Table for a specific Warehouse
		------------------------------------------------------------
		IF @v_vchWHID IS NOT NULL
		BEGIN
			INSERT INTO t_host_wms_inventory_export
           ([tran_code]
           ,[processing_code]
           ,[processing_status]
           ,[wh_id]
           ,[owner_id]
           ,[item_number]
           ,[uom]
           ,[location]
           ,[quantity_sign]
           ,[quantity]
           ,[inventory_status]
           ,[inventory_type]
           ,[lot_number]
           ,[expiry_date]
           ,[serial_number]
		   ,[parent_lpn]
           ,[lpn]
           ,[create_date]
           ,[create_by]
           )
		  select @v_vchTranType
			,'ADD'
			,'PENDING'
			,wh_id
			,owner_code
			,item_number
			,uom
			,location
			,'+'
			,SUM(quantity)
			,inv_status
			,inv_type
			,lot_number
			,EXPIRY_DATE
			,SERIAL_NUMBER
			,parent_lpn
			,lpn
			,GETDATE()
			,@v_vchUserID
		from v_wms_inventory_data
		where wh_id = @v_vchWHID
		GROUP BY wh_id, owner_code,location, item_number, inv_status, inv_type,uom,lot_number,EXPIRY_DATE,SERIAL_NUMBER,parent_lpn,lpn
		END
		
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Into the Inventory Export Table Completed'
		-- Future, Add a Log action for inserting into the Process Log	
							
		------------------------------------------------------------
		--  GOTO Exit becuase we are completed with SPROC
		------------------------------------------------------------
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Finished with Processing Now goto Exit Label'
		-- Future, Add a Log action for inserting into the Process Log		


   		GOTO EXIT_LABEL

	-----------------------------------------------------------------------------------
	--  After setting the message variables now write to the Process Log
	--  To make this more generic, we should use the Log Manager Stored Procedure
	-----------------------------------------------------------------------------------
		WRITE_PROCESS_LOG:
		
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
		
		if @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field List 1 :' +'App ID: ['+ISNULL(@v_vchApplicationID, '')+']'
					+'Log Type: ['+ISNULL(@v_vchMessage, '')+']'
					+'Warehouse: ['+ISNULL(@in_vchWhID, '') +']'
					+'Device: ['+ISNULL(@in_vchDevice, '')+']'
					+'Object Name: ['+ISNULL(@c_vchObjName, '')+']'
					+'Data1: ['+ISNULL(@v_vchProcessData1, '')+']'
			select	'Field List 2 :' 		+'Data2: ['+ISNULL(@v_vchProcessData2, '')+']'
					+'Data3: ['+ISNULL(@v_vchProcessData3, '')+']'
					+'Data4: ['+ISNULL(@v_vchProcessData4, '')+']'
					+'Message: ['+ISNULL(@v_vchMessage, '')+']'
					+'User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		END
		
		if @v_intLogLevel >= 5 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field Length: App ID: ['+str(len(@v_vchApplicationID),10) +']'
			select	'Field Length: Log Type: ['+STR(len(@v_vchLogType), 10) +']'
			select	'Field Length: Warehouse: ['+ str( len(@in_vchWhID),10) +']'
			select	'Field Length: Device: ['+ str(len(@in_vchDevice) ,10) +']'
			select	'Field Length: Object Name: ['+ str(len(@c_vchObjName) ,10) +']'
			select	'Field Length: Data1: ['+ str(len (@v_vchProcessData1) ,10) +']'
			select	'Field Length: Data2: ['+ str(len (@v_vchProcessData2) ,10) +']'
			select	'Field Length: Data3: ['+ str(len (@v_vchProcessData3) ,10) +']'
			select	'Field Length: Data4: ['+ str(len (@v_vchProcessData4) ,10) +']'
			select	'Field Length: Message: ['+ str(len(@v_vchMessage) ,10) +']'
			select	'Field Length: User ID: ['+ str( len(@v_vchUserID),10) +']'
		END
		
		INSERT INTO [dbo].[t_com_process_log]
			([app_id],[log_type],[warehouse]
			,[device],[process]
			,[process_datetime],[data_1]
			,[data_2],[data_3],[data_4]
			,[message],[create_date],[create_by])
		VALUES
		(left(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40), left(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
		, left(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25), left(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
		, left(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
		, getdate(),ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA')
		, left(@v_vchProcessData2, 1000),left(@v_vchProcessData3, 1000),left(@v_vchProcessData4, 1000)
		, left(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100), getdate(), ISNULL(left(@v_vchUserID, 10), 'OGA'))
			
		--Print 'Done with Insert Error into Process Log'
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Finished with Writing to the Process Log Now goto Exit Label'
		-- Future, Add a Log action for inserting into the Process Log	

		SET @v_vchStatus = 'FAIL'
		GOTO EXIT_LABEL
		
    END TRY
        
-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
    BEGIN CATCH
    
	-- Insert a message into the Process log about the Error
	-- Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		SET @v_vchStatus = 'FAIL'
		
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		if @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			select 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			select 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			select 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			select 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			select 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			select 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id],[log_type],[warehouse],[device],[process]
			   ,[process_datetime],[data_1],[data_2],[data_3],[data_4]
			   ,[message],[create_date],[create_by])
		 VALUES
		 		(left(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40), left(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, left(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25), left(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
				, left(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, getdate(),ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, left(@v_vchProcessData2, 1000),left(@v_vchProcessData3, 1000),left(@v_vchProcessData4, 1000)
				,left(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, getdate(), ISNULL(@v_vchUserID,'OGA'))		
	END CATCH
	
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Exiting Sproc'
		-- Future, Add a Log action for inserting into the Process Log		
    
END



GO
/****** Object:  StoredProcedure [dbo].[usp_job_snap_stock_card_daily]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_job_snap_stock_card_daily]
AS
BEGIN
	SET NOCOUNT ON;

	--SNAP in 08.00 น.
	DECLARE @v_dtRealSnapDate DATE = CONVERT(DATE, GETDATE() - 1)
	--DECLARE @in_dtSnapDate DATE  
	--SET @in_dtSnapDate = CONVERT(DATE, GETDATE())
	
	--Clare Snap Inventory เดิมออกก่อน
	DELETE t_wms_snap_inventory_for_stock_card WHERE snap_date < DATEADD(DAY,-10,@v_dtRealSnapDate)	
	DELETE t_wms_snap_inventory_for_stock_card WHERE snap_date = @v_dtRealSnapDate	
	INSERT INTO [dbo].[t_wms_snap_inventory_for_stock_card]
			   ([log_inv_id]
			   ,[snap_date]
			   ,[wh_master_id]
			   ,[owner_id]
			   ,[wh_item_master_id]
 			   ,[zone_id]
			   ,[zone]
			   ,[location_id]
			   ,[location]
			   ,[close_inv_qty]
			   ,[inv_type]
			   ,[lot_number]
			   ,[expiry_date]
			   ,[attribute1]
			   ,[attribute2]
			   ,[attribute3]
			   ,[attribute4]
			   ,[attribute5]
			   ,[inventory_status_id]
			   ,[inv_status]
			   ,[grade_code]
			   ,[grade_description]
			   ,[create_date]
			   ,[create_by])
		SELECT NEWID()
			   ,@v_dtRealSnapDate
			   ,inv.wh_master_id
			   ,inv.owner_id
			   ,inv.wh_item_master_id
 			   ,z.zone_id
			   ,z.zone
			   ,inv.location_id
			   ,loc.location
			   ,SUM(inv.quantity) AS quantity
			   ,inv.inv_type
			   ,invLot.lot_number
			   ,invExp.expiry_date
			   ,invAttr1.attribute1
			   ,invAttr2.attribute2
			   ,invAttr3.attribute3
			   ,invAttr4.attribute4
			   ,invAttr5.attribute5
			   ,inv.inventory_status_id
			   ,invST.inv_status
			   ,CASE WHEN ISNULL(grade.grade_code,'') = '' THEN 'UNDECIDE' ELSE ISNULL(grade.grade_code,'') END
			   ,CASE WHEN ISNULL(grade.description,'') = '' THEN 'UNDECIDE' ELSE ISNULL(grade.description,'') END 
			   ,GETDATE()
			   ,'JOB-SCHEDULE' 
		FROM t_wms_inventory inv
 		INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
		INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number FROM dbo.t_wms_inventory_attribute
						WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_6
						WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_5
						WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttr1 ON inv.inventory_id = invAttr1.inventory_id AND inv.attribute_group_id = invAttr1.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_4
						WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttr2 ON inv.inventory_id = invAttr2.inventory_id AND inv.attribute_group_id = invAttr2.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_3
						WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttr3 ON inv.inventory_id = invAttr3.inventory_id AND inv.attribute_group_id = invAttr3.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_2
						WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttr4 ON inv.inventory_id = invAttr4.inventory_id AND inv.attribute_group_id = invAttr4.attribute_group_id 
		LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_1
						WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttr5 ON inv.inventory_id = invAttr5.inventory_id AND inv.attribute_group_id = invAttr5.attribute_group_id 
 		LEFT JOIN t_wms_inventory_detail invGrade on inv.inventory_id = invGrade.inventory_id
		LEFT JOIN t_wms_grade grade on grade.grade_id = invGrade.grade_id 
		LEFT JOIN t_wms_zone_location zloc ON loc.location_id = zloc.location_id
		LEFT JOIN t_wms_zone z ON z.zone_id= zloc.zone_id
		GROUP BY inv.wh_master_id
			   ,inv.owner_id  
			   ,inv.wh_item_master_id
 			   ,z.zone_id
			   ,z.zone
			   ,inv.location_id
			   ,loc.location
			   ,inv.inv_type
			   ,invLot.lot_number
			   ,invExp.expiry_date
			   ,invAttr1.attribute1
			   ,invAttr2.attribute2
			   ,invAttr3.attribute3
			   ,invAttr4.attribute4
			   ,invAttr5.attribute5
			   ,inv.inventory_status_id
			   ,invST.inv_status
			   ,grade.grade_code
			   ,grade.description

	--Snap Every 08.00 ดังนั้นค่าที่ดึงของ Log คือ today - 1 ถึง to day 08.00
	DECLARE @v_dtGetDate DATETIME
	DECLARE @v_dtReportDate DATETIME
	DECLARE @v_dtReportDateTo DATETIME
	SET @v_dtGetDate = CONVERT(DATE, GETDATE()) 
	SET @v_dtReportDate = DATEADD(HOUR,8,DATEADD(DAY,-1,@v_dtGetDate))	--Yesterday 08.00 -
	SET @v_dtReportDateTo = DATEADD(HOUR,8,@v_dtGetDate)				--Today 08.00
	 
	--Clear Snap tran log stock card
	DELETE t_wms_snap_stock_card_report WHERE snap_date = @v_dtRealSnapDate	

	SELECT tLog.log_type
		,wh.wh_master_id
		,own.owner_id
		,whItem.wh_item_master_id
		,item.item_master_id
		,tLog.quantity
		,tLog.inv_status
	INTO #tLog
	FROM (SELECT to_warehouse AS warehouse
			,to_owner AS owner_code
			,item_number
			,after_status as inv_status
			,SUM(quantity) AS quantity
			,'RECEIPT' AS log_type 
		FROM t_com_tran_log 
		WHERE tran_type = 'IO_RECEIPT'
		AND sub_tran_type = 'RECEIPT'
		AND (create_date >= @v_dtReportDate AND create_date <= @v_dtReportDateTo)
		GROUP BY to_warehouse,to_owner,item_number,after_status
		UNION ALL 
		SELECT warehouse AS warehouse
			,owner AS owner_code
			,item_number
			,status as inv_status
			,SUM(quantity) AS quantity
			,'SHIP'	AS log_type 
		FROM t_com_tran_log
		WHERE tran_type = 'OO_SHIP'
		AND sub_tran_type = 'CONFIRM_SHIP'
		AND (create_date >= @v_dtReportDate AND create_date <= @v_dtReportDateTo)
		GROUP BY warehouse,owner,item_number,status
		) tLog
	LEFT JOIN t_wms_wh wh ON tLog.warehouse = wh.wh_id
	LEFT JOIN t_wms_owner own ON tLog.owner_code = own.owner_code
	LEFT JOIN t_wms_item item ON tLog.item_number = item.item_number AND item.owner_id = own.owner_id
	LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND wh.wh_master_id = whItem.wh_master_id

	;WITH tInv AS
	(	
		--Close ปัจจุบัน
		SELECT wh_item_master_id
			,inv_status
			,inventory_status_id
			,SUM(close_inv_qty) AS close_inv_qty
		FROM t_wms_snap_inventory_for_stock_card
		WHERE snap_date = @v_dtRealSnapDate
		GROUP BY wh_item_master_id,inv_status,inventory_status_id
	)
	,tInvClose AS
	(	
		--Close วันก่อนหน้า
		SELECT wh_item_master_id
			,inv_status
			,inventory_status_id
			,SUM(close_inv_qty) AS close_inv_qty
		FROM t_wms_snap_inventory_for_stock_card
		WHERE snap_date = DATEADD(DAY,-1,@v_dtRealSnapDate)
		GROUP BY wh_item_master_id,inv_status,inventory_status_id
	)
	INSERT INTO [dbo].[t_wms_snap_stock_card_report]
           ([snap_log_id]
           ,[snap_date]
           ,[wh_master_id]
           ,[wh_id]
           ,[owner_id]
           ,[owner_code]
           ,[category_id]
           ,[item_category]
           ,[category_desc]
           ,[wh_item_master_id]
           ,[item_master_id]
           ,[item_number]
           ,[item_desc]
           ,[size]
           ,[item_user_def7]
           ,[item_user_def8]
		   ,[inv_status]
           ,[close_inv_qty]
           ,[receipt_qty]
           ,[ship_qty]
           ,[full_inv_qty]
           ,[full_receipt_qty]
           ,[full_ship_qty]
           ,[full_total_remain_qty]
           ,[mod_inv_qty]
           ,[mod_receipt_qty]
           ,[mod_ship_qty]
           ,[mod_total_remain_qty]
           ,[create_by]
           ,[create_date])
	 SELECT newid()
		,@v_dtRealSnapDate
		,wh.wh_master_id
		,wh.wh_id
		,item.owner_id
		,own.owner_code
		,cate.category_id
		,cate.item_category
		,cate.description AS category_description
		,whItem.wh_item_master_id
		,item.item_master_id
		,item.item_number
		,item.description AS item_description
		,item.size
		,item.user_def7	--KG
		,item.user_def8	--Carton
		,tInv.inv_status
		,ISNULL(tInvClose.close_inv_qty,0) AS close_inv_qty
		,ISNULL(tReceipt.quantity,0) AS receipt_qty
		,ISNULL(tShip.quantity,0) AS ship_qty

		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tInvClose.close_inv_qty,0)) / CONVERT(INT,ISNULL(item.user_def8,0)) END) AS full_inv_qty
		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tReceipt.quantity,0)) / CONVERT(INT,ISNULL(item.user_def8,0))  END) AS full_receipt_qty
		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tShip.quantity,0)) / CONVERT(INT,ISNULL(item.user_def8,0))     END) AS full_ship_qty
		,((CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tInvClose.close_inv_qty,0)) / CONVERT(INT,ISNULL(item.user_def8,0)) END)
			+ (CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tReceipt.quantity,0)) / CONVERT(INT,ISNULL(item.user_def8,0))END)
			- (CASE WHEN ISNULL(item.user_def8,0) = 0 THEN 0 ELSE CONVERT(INT,ISNULL(tShip.quantity,0)) / CONVERT(INT,ISNULL(item.user_def8,0))   END))  AS full_total_remain_qty

		--,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tInv.close_inv_qty,0) ELSE CONVERT(INT,ISNULL(tInv.close_inv_qty,0)) % CONVERT(INT,ISNULL(item.user_def8,0)) END) AS mod_inv_qty
		--,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tReceipt.quantity,0)  ELSE CONVERT(INT,ISNULL(tReceipt.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0))  END) AS mod_receipt_qty
		--,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tShip.quantity,0)     ELSE CONVERT(INT,ISNULL(tShip.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0))     END) AS mod_ship_qty
		
		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tInvClose.close_inv_qty,0) ELSE CONVERT(INT,ISNULL(tInvClose.close_inv_qty,0)) % CONVERT(INT,ISNULL(item.user_def8,0)) END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0)  END) AS mod_inv_qty
		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tReceipt.quantity,0)  ELSE CONVERT(INT,ISNULL(tReceipt.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0))  END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0)  END) AS mod_receipt_qty		
		,(CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tShip.quantity,0)     ELSE CONVERT(INT,ISNULL(tShip.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0))     END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0)  END) AS mod_ship_qty
		
		,((CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tInvClose.close_inv_qty,0) ELSE CONVERT(INT,ISNULL(tInvClose.close_inv_qty,0)) % CONVERT(INT,ISNULL(item.user_def8,0)) END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0) END)
			+ (CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tReceipt.quantity,0)  ELSE CONVERT(INT,ISNULL(tReceipt.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0)) END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0) END)
			- (CASE WHEN ISNULL(item.user_def8,0) = 0 THEN ISNULL(tShip.quantity,0)     ELSE CONVERT(INT,ISNULL(tShip.quantity,0)) % CONVERT(INT,ISNULL(item.user_def8,0))    END) * (CASE WHEN ISNULL(item.user_def7,0) = 0 THEN 1 ELSE ISNULL(item.user_def7,0) END)) AS mod_total_remain_qty
		,'JOB-SCHEDULE'
		,GETDATE()
	FROM t_wms_wh_item whItem
	INNER JOIN t_wms_wh wh ON whItem.wh_master_id = wh.wh_master_id
	INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	INNER JOIN t_wms_owner own ON item.owner_id = own.owner_id
	INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
	LEFT JOIN tInv ON whItem.wh_item_master_id = tInv.wh_item_master_id
	LEFT JOIN tInvClose ON whItem.wh_item_master_id = tInvClose.wh_item_master_id AND tInv.inv_status = tInvClose.inv_status
	LEFT JOIN (SELECT wh_item_master_id,quantity,inv_status
			   FROM #tLog
			   WHERE log_type = 'RECEIPT'
			  ) tReceipt ON tReceipt.wh_item_master_id = whItem.wh_item_master_id AND tInv.inv_status = tReceipt.inv_status
	LEFT JOIN (SELECT wh_item_master_id,quantity,inv_status
			   FROM #tLog
			   WHERE log_type = 'SHIP'
			  ) tShip ON tShip.wh_item_master_id = whItem.wh_item_master_id AND tInv.inv_status = tShip.inv_status

	DROP TABLE #tLog
END

 
GO
/****** Object:  StoredProcedure [dbo].[usp_job_snap_tran_log_daily]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_job_snap_tran_log_daily]
AS
BEGIN
	SET NOCOUNT ON;
	--SNAP at 23.59 น.
	DECLARE @in_dtSnapDate DATE 
	SET @in_dtSnapDate =  CONVERT(DATE, GETDATE()) 

	--EXEC usp_job_snap_tran_log_daily

	--Clare Snap Transaction เดิมออกก่อน
	DELETE t_wms_snap_tran_log WHERE snap_date = @in_dtSnapDate	
	DELETE t_wms_snap_inventory_for_stock_card WHERE snap_date = @in_dtSnapDate	
	
	INSERT INTO [dbo].[t_wms_snap_inventory_for_stock_card]
		([log_inv_id]
		,[snap_date]
		,[wh_item_master_id]
		,[item_master_id]
		,[lot_number]
		,[expiry_date]
		,[attribute1]
		,[attribute2]
		,[attribute3]
		,[attribute4]
		,[attribute5]
		,[zone_id]
		,[zone]
		,[erp_location]
		,[wms_location]
		,[wms_location_id]
		,[close_inv_qty]
		,[inv_type]
		,[inventory_status_id]
		,[inv_status]
		,[create_date]
		,[create_by])
	SELECT NEWID()
		,@in_dtSnapDate 
		,inv.wh_item_master_id
		,item.item_master_id
		,invLot.lot_number
		,invExp.expiry_date
		,invAttr1.attribute1
		,invAttr2.attribute2
		,invAttr3.attribute3
		,invAttr4.attribute4
		,invAttr5.attribute5
		,z.zone_id
		,z.zone
		,ISNULL(loc.erp_location,'') AS erp_location
		,loc.location
		,inv.location_id 
		,SUM(inv.quantity) AS inventory_qty
		,inv.inv_type
		,inv.inventory_status_id
		,invST.inv_status
		,GETDATE()
		,'JOB-SCHEDULE'
	FROM t_wms_inventory inv
	INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item item ON item.item_master_id = whItem.item_master_id
	INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
	INNER JOIN t_wms_inventory_status invST ON inv.inventory_status_id = invST.inventory_status_id
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS lot_number FROM dbo.t_wms_inventory_attribute
					WHERE (inv_attribute_type_id = 'CA582043-C7F5-43E3-8A6F-EE51B4FCCB70')) AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS expiry_date FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_6
					WHERE (inv_attribute_type_id = 'D468B603-02DE-4391-90D6-658862AEE248')) AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute1 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_5
					WHERE (inv_attribute_type_id = '34903416-58B0-46AC-8DAF-6804ABB0A714')) AS invAttr1 ON inv.inventory_id = invAttr1.inventory_id AND inv.attribute_group_id = invAttr1.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute2 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_4
					WHERE (inv_attribute_type_id = '4A0505DE-B485-4658-A4E8-42133210B79A')) AS invAttr2 ON inv.inventory_id = invAttr2.inventory_id AND inv.attribute_group_id = invAttr2.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute3 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_3
					WHERE (inv_attribute_type_id = 'B5278D5A-4492-45FF-8DD6-24EF309DF526')) AS invAttr3 ON inv.inventory_id = invAttr3.inventory_id AND inv.attribute_group_id = invAttr3.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute4 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_2
					WHERE (inv_attribute_type_id = '89AA8946-0EF4-4C5D-9121-413EC8460580')) AS invAttr4 ON inv.inventory_id = invAttr4.inventory_id AND inv.attribute_group_id = invAttr4.attribute_group_id 
	LEFT OUTER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS attribute5 FROM dbo.t_wms_inventory_attribute AS t_wms_inventory_attribute_1
					WHERE (inv_attribute_type_id = '79A64D9F-A1B8-4479-A85D-0A4CB00405FE')) AS invAttr5 ON inv.inventory_id = invAttr5.inventory_id AND inv.attribute_group_id = invAttr5.attribute_group_id 
 	LEFT JOIN t_wms_zone_location zloc ON loc.location_id = zloc.location_id
	LEFT JOIN t_wms_zone z ON z.zone_id= zloc.zone_id
	GROUP BY inv.wh_item_master_id,item.item_master_id,invLot.lot_number,invExp.expiry_date,invAttr1.attribute1,invAttr2.attribute2,invAttr3.attribute3,invAttr4.attribute4,invAttr5.attribute5,z.zone_id,z.zone, loc.erp_location,loc.location,inv.location_id,inv.inv_type,inv.inventory_status_id,invST.inv_status

	SELECT tran_id
		,tran_type
		,sub_tran_type
		,description
		,warehouse
		,to_warehouse
		,owner
		,to_owner
		,location
		,to_location
		,parent_lpn
		,after_parent_lpn
		,lpn
		,after_lpn
		,item_number
		,quantity
		,quantity_uom
		,lot_number
		,after_lot_number
		,expiry_date
		,after_expiry_date
		,serial_number
		,attribute1
		,after_attribute1
		,attribute2
		,after_attribute2
		,attribute3
		,after_attribute3
		,attribute4
		,after_attribute4
		,attribute5
		,after_attribute5
		,status
		,after_status
		,order_number
		,reference_number
		,create_by		AS trans_create_by
		,create_date 
		,pick_location
		,receive_date
	INTO #tLog
	FROM t_com_tran_log
	WHERE tran_type IN ('IO_RECEIPT','BLIND_RECEIPT','OO_SHIP','OO_PARTIAL_SHIP','INV_ADJUST','INV_MOVE')
	AND sub_tran_type IN ('RECEIPT','CONFIRM_SHIP','CONFIRM_TO_ERP','MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','ADJUST_IN_TO_ERP','ADJUST_IN_NOT_ERP','ADJUST_OUT_TO_ERP','ADJUST_OUT_NOT_ERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY')
	AND CONVERT(DATE,create_date) = @in_dtSnapDate
 
	;WITH tLogAllCTE AS
		(
			--IN อย่างเดียว
			SELECT tran_id 
				,tran_type
				,sub_tran_type
				,'IN'				AS [type]
				,to_warehouse		AS wh_id
				,to_owner			AS owner_code
				,to_location		AS location
				,after_parent_lpn	AS parent_lpn
				,after_lpn			AS lpn
				,item_number
				,quantity
				,quantity_uom
				,after_lot_number	AS lot_number
				,after_expiry_date	AS expiry_date
				,after_attribute1	AS attribute1
				,after_attribute2	AS attribute2
				,after_attribute3	AS attribute3
				,after_attribute4	AS attribute4
				,after_attribute5	AS attribute5
				,serial_number
				,after_status		AS inv_status
				,trans_create_by
				,create_date
				,CASE WHEN ISNULL(order_number,'') = '' THEN reference_number ELSE order_number END AS order_number
				,ISNULL(receive_date,create_date) AS receive_date 
			FROM #tLog
			WHERE tran_type IN ('IO_RECEIPT','BLIND_RECEIPT','INV_ADJUST')
			AND sub_tran_type IN ('RECEIPT','ADJUST_IN_TO_ERP','ADJUST_IN_NOT_ERP')
		UNION
			--OUT อย่างเดียว
			SELECT tran_id
				,tran_type
				,sub_tran_type
				,'OUT'			AS [type] 
				,warehouse		AS wh_id
				,owner			AS owner_code
				,(CASE WHEN (tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP') AND sub_tran_type IN ('CONFIRM_SHIP','CONFIRM_TO_ERP')) THEN pick_location ELSE location END) AS location
				,parent_lpn		AS parent_lpn
				,lpn			AS lpn
				,item_number
				,quantity
				,quantity_uom
				,lot_number		AS lot_number
				,expiry_date	AS expiry_date
				,attribute1		AS attribute1
				,attribute2		AS attribute2
				,attribute3		AS attribute3
				,attribute4		AS attribute4
				,attribute5		AS attribute5
				,serial_number
				,status			AS inv_status
				,trans_create_by
				,create_date
				,CASE WHEN ISNULL(order_number,'') = '' THEN ISNULL(reference_number,'') ELSE order_number END AS order_number
				,receive_date 
			FROM #tLog
			WHERE tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP','INV_ADJUST')
			AND sub_tran_type IN ('CONFIRM_SHIP','CONFIRM_TO_ERP','ADJUST_OUT_TO_ERP','ADJUST_OUT_NOT_ERP')		 
		UNION
			--Location ต้นทาง OUT
			--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
			SELECT tran_id
				,tran_type
				,sub_tran_type
				,'OUT'			AS [type]
				,warehouse		AS wh_id
				,owner			AS owner_code
				,(CASE WHEN (tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP') AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP')) THEN pick_location ELSE location END) AS location
				,parent_lpn		AS parent_lpn
				,lpn			AS lpn
				,item_number
				,quantity
				,quantity_uom
				,lot_number		AS lot_number
				,expiry_date	AS expiry_date
				,attribute1		AS attribute1
				,attribute2		AS attribute2
				,attribute3		AS attribute3
				,attribute4		AS attribute4
				,attribute5		AS attribute5
				,serial_number
				,status			AS inv_status
				,trans_create_by
				,create_date
				,CASE WHEN ISNULL(order_number,'') = '' THEN reference_number ELSE order_number END AS order_number
				,receive_date 
			FROM #tLog
			WHERE tran_type IN ('INV_MOVE','OO_SHIP','OO_PARTIAL_SHIP')
			AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY')
		UNION
			--Location ปลายทาง IN
			--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
			SELECT tran_id
				,tran_type
				,sub_tran_type
				,'IN'				AS [type]
				,to_warehouse		AS wh_id
				,to_owner			AS owner_code
				,to_location		AS location
				,after_parent_lpn	AS parent_lpn
				,after_lpn			AS lpn
				,item_number
				,quantity
				,quantity_uom
				,after_lot_number	AS lot_number
				,after_expiry_date	AS expiry_date
				,after_attribute1	AS attribute1
				,after_attribute2	AS attribute2
				,after_attribute3	AS attribute3
				,after_attribute4	AS attribute4
				,after_attribute5	AS attribute5
				,serial_number
				,after_status		AS inv_status
				,trans_create_by
				,DATEADD(MILLISECOND,2,create_date)
				,CASE WHEN ISNULL(order_number,'') = '' THEN reference_number ELSE order_number END AS order_number
				,receive_date 
			FROM #tLog
			WHERE tran_type IN ('INV_MOVE','OO_SHIP','OO_PARTIAL_SHIP')
			AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY')
		)
	INSERT INTO [dbo].[t_wms_snap_tran_log]
           ([snap_tran_id]					
           ,[snap_date]
           ,[tran_id]
           ,[tran_type]
           ,[sub_tran_type]
           ,[type]
           ,[wh_master_id]
           ,[wh_id]
           ,[owner_id]
           ,[owner_code]
           ,[location_id]
           ,[location]
           ,[parent_lpn]
           ,[lpn]
           ,[wh_item_master_id]
           ,[item_master_id]
           ,[item_number]
		   ,[item_description]
		   ,[min_qty]
		   ,[max_qty]
           ,[quantity]
           ,[quantity_uom]
           ,[lot_number]
           ,[expiry_date]
           ,[attribute1]
           ,[attribute2]
           ,[attribute3]
           ,[attribute4]
           ,[attribute5]
           ,[serial_number]
           ,[inventory_status_id]
           ,[inv_status]
           ,[tran_datetime]
           ,[zone_id]
           ,[zone]
		   ,[order_number]
		   ,[receive_date]
		   ,[erp_location]
		   ,[trans_create_by] 
           ,[create_by]
           ,[create_date])
     SELECT NEWID()
			,@in_dtSnapDate AS snap_date 
			,t.tran_id
			,t.tran_type
			,t.sub_tran_type
			,t.[type]
			,wh.wh_master_id
			,wh.wh_id
			,own.owner_id
			,own.owner_code
			,loc.location_id
			,loc.location
			,ISNULL(t.parent_lpn,'') AS parent_lpn
			,ISNULL((CASE WHEN loc.lpn_controlled = 'NO' THEN NULL ELSE t.lpn END),'') AS lpn
			,whItem.wh_item_master_id
			,item.item_master_id
			,item.item_number
			,item.description
			,item.min_qty
			,item.max_qty
			,quantity
			,quantity_uom
			,ISNULL(t.lot_number,'') AS lot_number
			,(CASE WHEN item.expiry_date_control = 'NONE' THEN NULL ELSE CONVERT(VARCHAR,t.expiry_date,112) END) AS expiry_date
			,ISNULL(t.attribute1,'') AS attribute1
			,ISNULL(t.attribute2,'') AS attribute2
			,ISNULL(t.attribute3,'') AS attribute3
			,ISNULL(t.attribute4,'') AS attribute4
			,ISNULL(t.attribute5,'') AS attribute5
			,ISNULL(t.serial_number,'') AS serial_number
			,invStatus.inventory_status_id
			,invStatus.inv_status 
			,t.create_date
			,z.zone_id
			,z.zone
			,order_number
			,t.receive_date
			,loc.erp_location
			,trans_create_by
			,'JOB-SCHEDULE'
			,GETDATE()
		FROM tLogAllCTE t
		INNER JOIN t_wms_wh wh ON t.wh_id = wh.wh_id
		INNER JOIN t_wms_owner own ON t.owner_code = own.owner_code
		INNER JOIN t_wms_location loc ON t.location = loc.location AND loc.wh_master_id = wh.wh_master_id
		INNER JOIN t_wms_inventory_status invStatus ON t.inv_status = invStatus.inv_status
		INNER JOIN t_wms_item item ON t.item_number = item.item_number and own.owner_id = item.owner_id
		INNER JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
		LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
		LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id

	IF OBJECT_ID('tempdb..#tLog') IS NOT NULL
		DROP TABLE #tLog
END

 
GO
/****** Object:  StoredProcedure [dbo].[usp_location_validation_all]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_location_validation_all]
	@in_vchApplicationID		NVARCHAR(40)=NULL,
	@in_vchUserID				NVARCHAR(25)=NULL,
	@in_vchWarehouseID			UNIQUEIDENTIFIER=NULL,
	@in_vchLocationID			UNIQUEIDENTIFIER=NULL,
	@in_vchParentLPN			NVARCHAR(25)=NULL,
	@in_vchLPN					NVARCHAR(25)=NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER=NULL,
	@in_vchItemNumber			NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER=NULL,
	@in_vchInventoryStatusID	UNIQUEIDENTIFIER=NULL,
    @in_vchLotNumber			NVARCHAR(100)=NULL,
	@in_vchExpiryDate			NVARCHAR(100)=NULL,
	@in_vchSerialNo				NVARCHAR(100)=NULL,
	@in_vchAttribute1			NVARCHAR(100)=NULL,
	@in_vchAttribute2			NVARCHAR(100)=NULL,
	@in_vchAttribute3			NVARCHAR(100)=NULL,
	@in_vchAttribute4			NVARCHAR(100)=NULL,
	@in_vchAttribute5			NVARCHAR(100)=NULL,
	@in_vchLotControl			VARCHAR(5),
	@in_vchExpiryDateControl	VARCHAR(5),
	@in_vchSNControl			VARCHAR(5),
	@in_vchAttribute1Control	VARCHAR(5),
	@in_vchAttribute2Control	VARCHAR(5),
	@in_vchAttribute3Control	VARCHAR(5),
	@in_vchAttribute4Control	VARCHAR(5),
	@in_vchAttribute5Control	VARCHAR(5),
    @in_ReceiveDate				DATE,
	@out_vchErrorCode			NVARCHAR(200) OUTPUT,
    @out_vchMessage				NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @v_vchFullControl			NVARCHAR(4),
			@v_vchLocal					NVARCHAR(10),
			@v_vchLocType				NVARCHAR(20),
			@v_vchLocation				NVARCHAR(50),	
			@v_vchLPNControl			VARCHAR(5),
			@v_vchOverrideReceiveDate	VARCHAR(3), 
			@v_vchMixOwners				VARCHAR(3),
			@v_vchMixStatus				VARCHAR(3),
			@v_vchMixItems				VARCHAR(3),
			@v_vchMixLot				VARCHAR(3),
			@v_vchMixExpiryDate			VARCHAR(3),
			@v_vchMixAttribute1			VARCHAR(3),
			@v_vchMixAttribute2			VARCHAR(3),
			@v_vchMixAttribute3			VARCHAR(3),
			@v_vchMixAttribute4			VARCHAR(3),
			@v_vchMixAttribute5			VARCHAR(3),
			@v_vchCapacity				FLOAT

	SET	@v_vchFullControl = 'FULL';
	SET	@out_vchErrorCode = '0';
	SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)

	SELECT @v_vchLocType = loc_type
		  ,@v_vchLocation = location
		  ,@v_vchOverrideReceiveDate = override_receive_date	
		  ,@v_vchLPNControl	= lpn_controlled
		  ,@v_vchMixOwners = mix_owners
		  ,@v_vchMixStatus = mix_status
		  ,@v_vchMixItems = mix_items			
		  ,@v_vchMixLot = mix_lot
		  ,@v_vchMixExpiryDate = mix_expiry_dates		
		  ,@v_vchMixAttribute1 = mix_attribute1
		  ,@v_vchMixAttribute2 = mix_attribute2		
		  ,@v_vchMixAttribute3 = mix_attribute3		
		  ,@v_vchMixAttribute4 = mix_attribute4		
		  ,@v_vchMixAttribute5 = mix_attribute5	
		  ,@v_vchCapacity = capacity_qty	
	FROM dbo.t_wms_location 
	WHERE wh_master_id = @in_vchWarehouseID 
	AND location_id = @in_vchLocationID 
	AND is_active = 'YES'

	IF (@v_vchLPNControl = 'YES')
	BEGIN
		IF(ISNULL(@in_vchLPN,'') = '')
			BEGIN
				SET @out_vchErrorCode = 'LPN_IS_EMPTY';
				SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		ELSE 
			BEGIN
				-- Check duplicate lpn.
				IF (ISNULL(@in_vchParentLPN,'') <> '')
					BEGIN
						DECLARE @v_vchDubParentLPN	NVARCHAR(50)
						SELECT TOP 1 @v_vchDubParentLPN = parent_lpn FROM dbo.t_wms_inventory 
						WHERE wh_master_id = @in_vchWarehouseID 
						AND ISNULL(parent_lpn,'') <> ISNULL(@in_vchParentLPN,'') 
						AND lpn = @in_vchLPN
						IF (ISNULL(@v_vchDubParentLPN,'') <> '')
							BEGIN
								SET @out_vchErrorCode = 'FOUND_LPN_IN_OTHER_PL';
								SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchLPN,@v_vchDubParentLPN,'@param3','@param4','@param5')
								RETURN;
							END
					END
				ELSE
					BEGIN
						DECLARE @v_vchDupLocation   NVARCHAR(50) = NULL,
								@v_vchDupLocationID	UNIQUEIDENTIFIER = NULL
						SELECT @v_vchDupLocationID = inv.location_id
						FROM dbo.t_wms_inventory inv 
						WHERE inv.wh_master_id = @in_vchWarehouseID
						AND inv.lpn = @in_vchLPN

						IF (@v_vchDupLocationID IS NOT NULL AND ISNULL(CONVERT(VARCHAR(36),@v_vchDupLocationID),'') <> ISNULL(CONVERT(VARCHAR(36),@in_vchLocationID),''))
							BEGIN
								SELECT TOP 1 @v_vchDupLocation = location FROM dbo.t_wms_location WHERE location_id = @v_vchDupLocationID
								--LPN ไม่ได้อยู่ใน Location ที่ Scan
								SET @out_vchErrorCode = 'FOUND_LPN_IN_OTHER_LOCATION'
								SELECT @out_vchMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchLPN,@v_vchDupLocation,'@param3','@param4','@param5')			
								RETURN;
							END
					END
			END
	END

	IF (@in_vchLotControl = @v_vchFullControl AND ISNULL(@in_vchLotNumber,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'LOT_NUMBER_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END 
	
	IF (@in_vchSNControl = @v_vchFullControl AND ISNULL(@in_vchSerialNo,'') = '')
		BEGIN
			SET	@out_vchErrorCode = 'SERIAL_NUMBER_ID_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END	

	IF (@in_vchExpiryDateControl = @v_vchFullControl AND ISNULL(@in_vchExpiryDate,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'EXPIRY_DATE_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@in_vchAttribute1Control = @v_vchFullControl AND ISNULL(@in_vchAttribute1,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE1_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@in_vchAttribute2Control = @v_vchFullControl AND ISNULL(@in_vchAttribute2,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE2_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@in_vchAttribute3Control = @v_vchFullControl AND ISNULL(@in_vchAttribute3,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE3_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF (@in_vchAttribute4Control = @v_vchFullControl AND ISNULL(@in_vchAttribute4,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE4_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	IF (@in_vchAttribute5Control = @v_vchFullControl AND ISNULL(@in_vchAttribute5,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'ATTRIBUTE5_IS_EMPTY';
			SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	-- Check receive date for item lpn
	IF (@v_vchOverrideReceiveDate = 'NO')
	BEGIN
		IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_MIX_RECEIVE_DATE' AND is_active = 'YES') = 'NO')
			BEGIN
				IF EXISTS (SELECT inventory_id FROM dbo.t_wms_inventory 
							WHERE wh_master_id = @in_vchWarehouseID 
							AND location_id = @in_vchLocationID 
							AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
							AND inventory_status_id = @in_vchInventoryStatusID 
							AND receive_date <> @in_ReceiveDate)
					BEGIN
						SET @out_vchErrorCode = 'CAN_NOT_MIXED_RECEIVE_DATE';
						SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						RETURN;
					END
			END
	END

	IF (@v_vchLocType <> 'FORK')
	BEGIN
		-- Check location is mix owner?
		IF EXISTS (SELECT inventory_id FROM dbo.t_wms_inventory WHERE wh_master_id = @in_vchWarehouseID AND location_id = @in_vchLocationID AND owner_id <> @in_vchOwnerID) AND (@v_vchMixOwners = 'NO')
			BEGIN
				SET @out_vchErrorCode = 'LOCATION_NOT_MIX_OWNER';
				SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				RETURN;
			END
		
		-- check location is mix item?
		IF EXISTS (SELECT inventory_id FROM dbo.t_wms_inventory WHERE wh_master_id = @in_vchWarehouseID AND location_id = @IN_vchLocationID AND wh_item_master_id <> @in_vchWhItemMasterID) AND @v_vchMixItems = 'NO'
			BEGIN
				SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ITEM';
				SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		DECLARE @v_vchChkInvID	 UNIQUEIDENTIFIER = NULL
		SELECT @v_vchChkInvID = inventory_id 
		FROM t_wms_inventory
		WHERE wh_master_id = @in_vchWarehouseID 
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID  

		-- check location is mix lot?
		IF (@in_vchLotControl = @v_vchFullControl AND @v_vchMixLot = 'NO')
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
						   WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'LOT' AND is_active = 'YES')
						   AND inventory_id = @v_vchChkInvID		
						   AND ISNULL(attribute_value,'') <> ISNULL(@in_vchLotNumber,''))
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_LOT';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;	
				END 
			END

		-- check location is mix expiry date?
		IF (@in_vchExpiryDateControl = @v_vchFullControl AND @v_vchMixExpiryDate = 'NO')
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
						   WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')	
						   AND inventory_id = @v_vchChkInvID
						   AND ISNULL(attribute_value,'') <> ISNULL(@in_vchExpiryDate,'')) 
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_EXPIRY_DATE';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END

		-- check location is mix attribute1?
		IF (@v_vchMixAttribute1 = 'NO' AND @in_vchAttribute1Control = @v_vchFullControl)
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
							WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE1' AND is_active = 'YES')
							AND inventory_id = @v_vchChkInvID
							AND ISNULL(attribute_value,'') <> ISNULL(@in_vchAttribute1,'')) 
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE1';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END
		 
		-- check location is mix attribute2?
		IF (@v_vchMixAttribute2 = 'NO' AND @in_vchAttribute2Control = @v_vchFullControl)
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
							WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE2' AND is_active = 'YES')
							AND inventory_id = @v_vchChkInvID
							AND ISNULL(attribute_value,'') <> ISNULL(@in_vchAttribute2,''))
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE2';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END

		-- check location is mix attribute3?
		IF (@v_vchMixAttribute3 = 'NO' AND @in_vchAttribute3Control = @v_vchFullControl)
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
							WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE3' AND is_active = 'YES')
							AND inventory_id = @v_vchChkInvID
							AND ISNULL(attribute_value,'') <> ISNULL(@in_vchAttribute3,''))
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE3';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END

		-- check location is mix attribute4?
		IF (@v_vchMixAttribute4 = 'NO' AND @in_vchAttribute4Control = @v_vchFullControl)
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
							WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE4' AND is_active = 'YES')
							AND inventory_id = @v_vchChkInvID
							AND ISNULL(attribute_value,'') <> ISNULL(@in_vchAttribute4,''))
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE4';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END

		-- check location is mix attribute5?
		IF (@v_vchMixAttribute5 = 'NO' AND @in_vchAttribute5Control = @v_vchFullControl)
			BEGIN
				IF EXISTS (SELECT inv_attribute_id FROM dbo.t_wms_inventory_attribute
							WHERE inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'ATTRIBUTE5' AND is_active = 'YES')
							AND inventory_id = @v_vchChkInvID
							AND ISNULL(attribute_value,'') <> ISNULL(@in_vchAttribute5,''))
				BEGIN
					SET	@out_vchErrorCode = 'LOCATION_NOT_MIX_ATTRIBUTE5';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
			END
		
		-- check location is mix Status?
		IF EXISTS(SELECT inventory_status_id FROM t_wms_inventory WHERE wh_master_id = @in_vchWarehouseID AND location_id = @in_vchLocationID AND inventory_status_id <> @in_vchInventoryStatusID) AND @v_vchMixStatus = 'NO'
			BEGIN
				SET @out_vchErrorCode = 'LOCATION_NOT_MIX_STATUS';
				SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
				RETURN;
			END
	END
	 
	--Check capacity
	IF (@v_vchCapacity > 0)
		BEGIN
			IF ((SELECT COUNT(DISTINCT lpn) + 1 FROM t_wms_inventory WHERE location_id = @in_vchLocationID AND (lpn <> @in_vchLPN AND ISNULL(lpn,'') <> '')) > @v_vchCapacity)
				BEGIN
					SET @out_vchErrorCode = 'LOCATION_IS_FULL_CAPACITY';
					SELECT @out_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@v_vchLocal,@v_vchLocation,'@param2','@param3','@param4','@param5')
					RETURN;
				END
					
		END

END
GO
/****** Object:  StoredProcedure [dbo].[usp_LogManager]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--2021-01-06 : ปรับเพิ่ม Parameter Department (SHIP)
CREATE PROCEDURE [dbo].[usp_LogManager]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchAppName					NVARCHAR(100)	= NULL,
	@in_vchDevice					NVARCHAR(50),			--Required
	@in_vchUserID					NVARCHAR(25),			--Required
	@in_vchLogType					NVARCHAR(50),			--Required
	--  Process Log Variables
	@in_vchProcess					NVARCHAR(50)	= NULL,	--Required
	@in_dtProcessDateTime			DATETIME		= NULL,	--Required
	@in_vchData1					NVARCHAR(1000)	= NULL,	--Required
	@in_vchData2					NVARCHAR(1000)	= NULL,
	@in_vchData3					NVARCHAR(1000)	= NULL,
	@in_vchData4					NVARCHAR(1000)	= NULL,
	--  Tran Log Variables
	@in_vchTranType					NVARCHAR(20)	= NULL,	--Required
	@in_vchSubTranType				NVARCHAR(20)	= NULL,
	@in_vchDescription				NVARCHAR(100)	= NULL,
	@in_dtStartTranDate				DATETIME		= NULL,	--Required
	@in_dtEndTranDate				DATETIME		= NULL,
	@in_vchWhID 					NVARCHAR(25)	= NULL,	--Required
	@in_vchToWhID 					NVARCHAR(25)	= NULL,
	@in_vchLocation					NVARCHAR(50)	= NULL,	--Required
	@in_vchToLocation				NVARCHAR(50)	= NULL,
	@in_vchOwner					NVARCHAR(50)	= NULL,
	@in_vchToOwner					NVARCHAR(50)	= NULL,
	@in_vchItemNumber				NVARCHAR(50)	= NULL,
	@in_fltQuantity					FLOAT			= NULL,	--Required
	@in_vchUOM						NVARCHAR(40)	= NULL,
	@in_vchBaseUOM					NVARCHAR(40)	= NULL,
	@in_fltAfterQuantity			FLOAT			= NULL,
	@in_vchAfterUOM					NVARCHAR(40)	= NULL,
	@in_vchLotNumber				NVARCHAR(100)	= NULL,
	@in_vchAfterLotNumber			NVARCHAR(100)	= NULL,
	@in_dtExpiryDate				DATETIME		= NULL,
	@in_dtAfterExpiryDate			DATETIME		= NULL,

	@in_vchAttribute1				NVARCHAR(100)	= NULL,
	@in_vchAfterAttribute1			NVARCHAR(100)	= NULL,
	@in_vchAttribute2				NVARCHAR(100)	= NULL,
	@in_vchAfterAttribute2			NVARCHAR(100)	= NULL,
	@in_vchAttribute3				NVARCHAR(100)	= NULL,
	@in_vchAfterAttribute3			NVARCHAR(100)	= NULL,
	@in_vchAttribute4				NVARCHAR(100)	= NULL,
	@in_vchAfterAttribute4			NVARCHAR(100)	= NULL,
	@in_vchAttribute5				NVARCHAR(100)	= NULL,
	@in_vchAfterAttribute5			NVARCHAR(100)	= NULL,

	@in_vchSerialNumber				NVARCHAR(50)	= NULL,
	@in_vchReferenceNumber			NVARCHAR(50)	= NULL,
	@in_vchControlNumber			NVARCHAR(50)	= NULL,
	@in_vchLPN						NVARCHAR(25)	= NULL,
	@in_vchAfterLPN					NVARCHAR(25)	= NULL,
	@in_vchParentLPN				NVARCHAR(25)	= NULL,
	@in_vchAfterParentLPN			NVARCHAR(25)	= NULL,
	@in_vchStatus					NVARCHAR(15)	= NULL,
	@in_vchAfterStatus				NVARCHAR(15)	= NULL,
	@in_vchZone						NVARCHAR(50)	= NULL,
	@in_vchOrderNumber				NVARCHAR(40)	= NULL,
	@in_vchOrderStatus				NVARCHAR(25)	= NULL,
	@in_vchOrderType				NVARCHAR(25)	= NULL,
	@in_vchLineNumber				NVARCHAR(10)	= NULL,
	@in_vchControlValue1			NVARCHAR(100)	= NULL,
	@in_vchControlValue2			NVARCHAR(100)	= NULL,
	@in_vchReasonCode				NVARCHAR(20)	= NULL,
	-- Add for outbound ship confirm
	@in_vchTrackingNumber			NVARCHAR(50)	= NULL,
	@in_vchSealNumber				NVARCHAR(50)	= NULL,
	@in_vchContainerNo				NVARCHAR(50)	= NULL,
	@in_vchTrailerNumber			NVARCHAR(50)	= NULL,
	@in_vchCarrierCode				NVARCHAR(50)	= NULL,
	@in_vchEquipmentType			NVARCHAR(50)	= NULL,
	@in_vchCDLLicense				NVARCHAR(50)	= NULL,
	-- User define field for header
	@in_vchHUDF1					NVARCHAR(255)	= NULL,
	@in_vchHUDF2					NVARCHAR(255)	= NULL,
	@in_vchHUDF3					NVARCHAR(255)	= NULL,
	@in_vchHUDF4					NVARCHAR(255)	= NULL,
	@in_vchHUDF5					NVARCHAR(255)	= NULL,
	@in_vchHUDF6					NVARCHAR(255)	= NULL,
	@in_fltHUDF7					FLOAT			= NULL,
	@in_fltHUDF8					FLOAT			= NULL,
	@in_dtpHUDF9					DATETIME		= NULL,
	@in_dtpHUDF10					DATETIME		= NULL,
	-- User define field for detail
	@in_vchDUDF1					NVARCHAR(255)	= NULL,
	@in_vchDUDF2					NVARCHAR(255)	= NULL,
	@in_vchDUDF3					NVARCHAR(255)	= NULL,
	@in_vchDUDF4					NVARCHAR(255)	= NULL,
	@in_vchDUDF5					NVARCHAR(255)	= NULL,
	@in_vchDUDF6					NVARCHAR(255)	= NULL,
	@in_fltDUDF7					FLOAT			= NULL,
	@in_fltDUDF8					FLOAT			= NULL,
	@in_dtpDUDF9					DATETIME		= NULL,
	@in_dtpDUDF10					DATETIME		= NULL,
	
	-- User define field for Tran log
	@in_dtUDFdatetime1				DATETIME = NULL,
	@in_dtUDFdatetime2				DATETIME = NULL,
	@in_dtUDFdatetime3				DATETIME = NULL,

	@in_vchOrderQuantity			FLOAT = NULL,
	@in_vchShortQuantity			FLOAT = NULL,
	@in_vchHostRecordID				VARCHAR(40) = NULL,
	@in_dtPostingDate				DATE = NULL,
	@in_dtReceiveDate				DATE = NULL, 
	@in_dtProductionDate			DATE = NULL,	--For Mfg Date
	@in_vchCustomerCode				NVARCHAR(50) = NULL,
	@in_vchSupplierCode				NVARCHAR(50) = NULL,

	--Mai [12/09/2013] เพิ่มคอลัมน์ที่ Insert ลง Host Ship Confirm
	@in_dtShipDateActual			DATE = NULL,
	@in_dtDeliveryDatePlan			DATE = NULL,
	@in_fltPrice					FLOAT = NULL,

	--Add new 2014-03-13 add ship to and bill to for ship confirm
	@in_vchDepartment				NVARCHAR(50)	= NULL,  
	@in_vchShipToCode				NVARCHAR(40)	= NULL,  
	@in_vchShipToName				NVARCHAR(300)	= NULL,  
	@in_vchShipToAddr1				NVARCHAR(300)	= NULL,  
	@in_vchShipToAddr2				NVARCHAR(300)	= NULL,  
	@in_vchShipToAddr3				NVARCHAR(300)	= NULL,  
	@in_vchShipToCity				NVARCHAR(50)	= NULL,  
	@in_vchShipToProvince			NVARCHAR(50)	= NULL,  
	@in_vchShipToPostalCode			NVARCHAR(50)	= NULL,  
	@in_vchShipToCountry			NVARCHAR(5)		= NULL,  
	@in_vchShipToCountryName 		NVARCHAR(50)	= NULL,  
	@in_vchShipToContactName 		NVARCHAR(50)	= NULL,  
	@in_vchShipToPhoneNumber 		NVARCHAR(50)	= NULL,  
	@in_vchBillToCode				NVARCHAR(40)	= NULL,  
	@in_vchBillToName				NVARCHAR(300)	= NULL,  
	@in_vchBillToAddr1				NVARCHAR(300)	= NULL,  
	@in_vchBillToAddr2				NVARCHAR(300)	= NULL,  
	@in_vchBillToAddr3				NVARCHAR(300)	= NULL,  
	@in_vchBillToCity				NVARCHAR(50)	= NULL,  
	@in_vchBillToProvince			NVARCHAR(50)	= NULL,  
	@in_vchBillToPostalCode			NVARCHAR(50)	= NULL,  
	@in_vchBillToCountry			NVARCHAR(5)		= NULL,  
	@in_vchBillToCountryName 		NVARCHAR(50)	= NULL,  
	@in_vchBillToContactName 		NVARCHAR(50)	= NULL,  
	@in_vchBillToPhoneNumber 		NVARCHAR(50)	= NULL,
	@in_vchComment					NVARCHAR(40)	= NULL,
	@in_dtCloseDate					DATETIME		= NULL, -- ใช้สำหรับ Partial Receipt Close Date 
	@in_vchPickLocation				NVARCHAR(50)	= NULL,
	@in_vchInputQuantity			FLOAT = NULL,
	@in_vchInputUOM					NVARCHAR(40)	= NULL,
	@in_vchErrorCode				NVARCHAR(200) = NULL OUTPUT,	--Required
	@in_vchMessage					NVARCHAR(100) = NULL OUTPUT	--Required
AS

BEGIN
	DECLARE 
    -- Error handling variables
    @c_vchObjName				NVARCHAR(50) = '[usp_LogManager]', -- The name that uniquely tags this object.
    @v_intSqlErrorNumber		INTEGER,
    @v_intSqlErrorLine			INTEGER,
    @v_intSqlErrorState			INTEGER,
    @v_intSqlErrorSeverity		INTEGER,
    @v_vchSqlErrorMessage		NVARCHAR(2048),
    @v_vchSqlErrorProcedure		NVARCHAR(200),  
    @v_vchProcessData1			NVARCHAR(1000),
    @v_vchProcessData2			NVARCHAR(1000),
    @v_vchProcessData3			NVARCHAR(1000),
    @v_vchProcessData4			NVARCHAR(1000),
    --  Log Handling Variables
    @v_intLogLevel				INTEGER = 0,  -- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
    @v_vchLogAction				NVARCHAR(25) = 'PRINT', --- PRINT, LOG, 
	@v_vchLogType				NVARCHAR(50),
	@v_vchTranLog				NVARCHAR(3),
	@v_vchProcessLog			NVARCHAR(3),
	@v_vchWinEventViewer		NVARCHAR(3),
	@v_vchHostInterfaceManager	NVARCHAR(3),
	@v_vchIsActive				NVARCHAR(3),
	@v_intLocale				INTEGER = 1033,
    @v_vchErrorCode				NVARCHAR(200),
	@v_vchMessage				NVARCHAR(250),
	@v_vchHostRecordID			VARCHAR(40),
	@v_vchDescription			NVARCHAR(100)	= NULL,
	
	-- Check Move between warehouse for TUF,
	@v_vchMovePlant				BIT -- 0 = in warehouse,1 = between warehouse
    
    SET NOCOUNT ON;
	    
    -- Set Constants  @in_vchProcess
	IF ISNULL(@in_vchProcess,'') <> ''
		SET @c_vchObjName = @in_vchProcess;

    SET @v_vchLogType = 'ERROR';
    ------------------------------------------------------------
	--  User ID cannot be NULL.  Set to a Default to 'SYSTEM'
	------------------------------------------------------------
	IF ISNULL(@in_vchUserID,'') = ''
		BEGIN
			SET @in_vchUserID = 'SYSTEM'
		END
    
    BEGIN TRY
		------------------------------------------------------------
		--  Check if this is only for logging to the Process Log 
		------------------------------------------------------------
	    IF @in_vchLogType = 'PROCESS' OR @in_vchLogType = 'IMPORT ERROR'
			BEGIN
				SET @v_vchProcessLog = 'YES'
				GOTO PROCESS_LOG_LABEL;
			END
		
		IF @in_vchLogType = 'WINDOWS_EVENT'
			BEGIN
				SET @v_vchWinEventViewer = 'YES'
				GOTO WINDOWS_EVENT_LABEL;
			END
			
		------------------------------------------------------------
		--  Quantity cannot be NULL.  Set to a Zero (0)
		------------------------------------------------------------
		IF @in_fltQuantity IS NULL
			SET @in_fltQuantity = 0
			
   		------------------------------------------------------------
		--  Check the Transaction Table
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Transaction Table Fields'
		-- Future, Add a Log action for inserting into the Process Log	
		
		------------------------------------------------------------
		--  Check with No Warehouse and No Sub Tran Type
		------------------------------------------------------------
		IF NOT EXISTS (SELECT transaction_id FROM [dbo].[t_com_transaction] 
						WHERE app_id = @in_vchApplicationID 
						AND tran_type = @in_vchTranType
						AND sub_tran_type = @in_vchSubTranType
						AND wh_id = (CASE WHEN ISNULL(@in_vchWhID,'') = '' THEN ISNULL(@in_vchToWhID,'') ELSE ISNULL(@in_vchWhID,'') END))
			BEGIN
				------------------------------------------------------------
				--  Write an Error to Process Log that no Transaction record Exists
				------------------------------------------------------------
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'No Transaction in t_transaction'
				-- Future, Add a Log action for inserting into the Process Log	
				
				SET @v_vchErrorCode = 'ERROR-LOGMAN-002'  -- Transaction Does Not Exist
				SET @v_vchLogType = 'LOG MANAGER ERROR'
				SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale) + '. Error Code ['+@v_vchErrorCode + '].'
				SET @v_vchProcessData2 = 'In Tran Type: '+@in_vchTranType +']'
				SET @v_vchProcessData3 = @in_vchWhID
				SET @v_vchProcessData4 = 'User ID: '+@in_vchUserID + ' App ID: '+@in_vchApplicationID
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale) + '. Error Code ['+@v_vchErrorCode + '].'
				GOTO WRITE_PROCESS_LOG
			END
		ELSE
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Get Transaction from Transaction Table'
				-- Future, Add a Log action for inserting into the Process Log	
		
				SELECT @v_vchDescription = [description]
					, @v_vchTranLog = tran_log
					, @v_vchProcessLog = process_log 
					, @v_vchWinEventViewer = win_event_viewer
					, @v_vchHostInterfaceManager = host_interface_manager
					, @v_vchIsActive = is_active
				FROM [dbo].[t_com_transaction]
				WHERE app_id = @in_vchApplicationID 
				AND tran_type = @in_vchTranType
				AND sub_tran_type = @in_vchSubTranType 
				AND wh_id = (CASE WHEN ISNULL(@in_vchWhID,'') = '' THEN ISNULL(@in_vchToWhID,'') ELSE ISNULL(@in_vchWhID,'') END)
						
				IF ISNULL(@in_vchDescription,'') = '' 
					SET @in_vchDescription = @v_vchDescription
			END
		
	   	------------------------------------------------------------
		--  Check for Active Transactions
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check is Transaction Active.  Transaction is:'+ @in_vchTranType
			-- Future, Add a Log action for inserting into the Process Log	
			
		IF @v_vchIsActive = 'NO' -- Transaction is NOT Active
			BEGIN
				If @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Transaction is NOT Active.  Transaction is:'+ @in_vchTranType
					-- Future, Add a Log action for inserting into the Process Log	
			
		
				SET @v_vchErrorCode = 'ERROR-LOGMAN-001' -- Invalid Record Type
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
				SET @v_vchProcessData2 = 'Tran Type: '+ @in_vchTranType + ' Sub Tran Type: '+ @in_vchSubTranType
				SET @v_vchProcessData3 = 'Active: '+ @v_vchIsActive
				SET @v_vchProcessData4 = 'User ID: '+ @in_vchUserID + ' App ID: '+@in_vchApplicationID
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
			
				GOTO WRITE_PROCESS_LOG
			END  
		
	    IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Transaction Active.  Transaction is:' + @in_vchTranType
			-- Future, Add a Log action for inserting into the Process Log	
		
   		------------------------------------------------------------
		--  Insert into Tranaction Log
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert If Tran Log = YES.  Tran Log Variable is:' + ISNULL(@v_vchTranLog, 'NULL')
			-- Future, Add a Log action for inserting into the Process Log
			
		IF @v_vchTranLog = 'YES'
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Insert Into Transaction Log'
			-- Future, Add a Log action for inserting into the Process Log
			
			----------------------------------------------------------
			--  Check for Required Fields
			--  log_type, warehouse, tran code, start tran date, location, quantity 
			-- 	app_id, device, user id, error_code
			------------------------------------------------------------
			IF @in_vchApplicationID IS NULL 
				OR @in_vchUserID IS NULL 
				OR @in_vchDevice IS NULL
				OR @in_vchTranType IS NULL 
				OR @in_vchSubTranType IS NULL
				OR @in_vchLogType IS NULL 
				OR @in_fltQuantity IS NULL
				BEGIN
					------------------------------------------------------------
					--  Missing required Fields so Log into the Process Log
					------------------------------------------------------------
					SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Invalid Record Type 
					SET @v_vchLogType =  'LOG MANAGER ERROR'
					SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
					SET @v_vchProcessData2 = 'Tran Type: ['+ISNULL(@in_vchTranType, '')+ '] Log Type: ['+ISNULL(@in_vchLogType, '') + '] Warehouse ID: ['+ISNULL(@in_vchWhID, '') + '] Device ID: ['+ISNULL(@in_vchDevice, '') + ']' 
					SET @v_vchProcessData3 = 'Location: ['+ISNULL(left(@in_vchLocation,50), '''') + '] Message ['+ISNULL(left(@in_vchMessage,50), '''') + ']'
					SET @v_vchProcessData4 = 'User ID: ['+ISNULL(@in_vchUserID, '''') + '] App ID: ['+ISNULL(@in_vchApplicationID, '''') + '] Quantity ['+ISNULL(CONVERT(NVARCHAR(10), @in_fltQuantity), '''') + '] Start Tran Date ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtStartTranDate), '''') + ']'
					SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
			
					GOTO WRITE_PROCESS_LOG
				END
			ELSE
				BEGIN
					SET @v_vchHostRecordID = NEWID()

					INSERT INTO t_com_tran_log 
					  (tran_id
						,[app_id]
						,[tran_type]
						,[sub_tran_type]
						,[app_name]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[control_number]
						,[lpn]
						,[after_lpn]
						,[parent_lpn]
						,[after_parent_lpn]
						,[status]
						,[after_status]
						,[zone]
						,[order_number]
						,[line_number]
						,[control_value_1]
						,[control_value_2]
						,[reason_code]
						,[receive_date]
						,[mfg_date]
						,[pick_location]
						,[input_quantity]
						,[input_uom]
						,[udf_1]
						,[udf_2]
						,[udf_3]
						,[udf_4]
						,[udf_datetime_1]
						,[udf_datetime_2]
						,[udf_datetime_3]
						,[create_by]
						,[device]
						)
					VALUES(@v_vchHostRecordID
						,@in_vchApplicationID			
						,@in_vchTranType				
						,@in_vchSubTranType				
						,@in_vchAppName					
						,@in_vchDescription				
						,@in_dtStartTranDate			
						,@in_dtEndTranDate				
						,@in_vchWhID					
						,@in_vchToWhID					
						,@in_vchLocation				
						,@in_vchToLocation				
						,@in_vchOwner					
						,@in_vchToOwner					
						,@in_vchItemNumber				
						,@in_fltQuantity				
						,@in_vchUOM						
						,@in_fltAfterQuantity			
						,@in_vchAfterUOM				
						,@in_vchLotNumber				
						,@in_vchAfterLotNumber			
						,@in_dtExpiryDate				
						,@in_dtAfterExpiryDate			
						,@in_vchSerialNumber	
						,@in_vchAttribute1
						,@in_vchAfterAttribute1
						,@in_vchAttribute2
						,@in_vchAfterAttribute2
						,@in_vchAttribute3
						,@in_vchAfterAttribute3
						,@in_vchAttribute4
						,@in_vchAfterAttribute4
						,@in_vchAttribute5
						,@in_vchAfterAttribute5	
						,@in_vchUserID					
						,@in_vchReferenceNumber			
						,@in_vchControlNumber			
						,@in_vchLPN						
						,@in_vchAfterLPN				
						,@in_vchParentLPN				
						,@in_vchAfterParentLPN			
						,@in_vchStatus					
						,@in_vchAfterStatus				
						,@in_vchZone					
						,@in_vchOrderNumber				
						,@in_vchLineNumber				
						,@in_vchControlValue1			
						,@in_vchControlValue2			
						,@in_vchReasonCode
						,@in_dtReceiveDate	
						,@in_dtProductionDate
						,@in_vchPickLocation
						,@in_vchInputQuantity
						,@in_vchInputUOM			
						,@in_vchHUDF1					
						,@in_vchHUDF2					
						,@in_vchHUDF3					
						,@in_vchHUDF4					
						,@in_dtUDFdatetime1				
						,@in_dtUDFdatetime2				
						,@in_dtUDFdatetime3				
						,@in_vchUserID					
						,@in_vchDevice
						)
				END
		END
		
		------------------------------------------------------------
		--  Call Host Interface Manager
		------------------------------------------------------------
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Host Interface Manager = ' + ISNULL(@v_vchHostInterfaceManager, 'NULL')
			-- Future, Add a Log action for inserting into the Process Log
			 
		IF @v_vchHostInterfaceManager = 'YES' OR @v_vchMovePlant = 1
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Calling Host Interface Manager'
			-- Future, Add a Log action for inserting into the Process Log
			
				EXEC usp_HostInterfaceManager @in_vchApplicationID		= @in_vchApplicationID		
											 ,@in_vchAppName			= @in_vchAppName			
											 ,@in_vchDevice				= @in_vchDevice				
											 ,@in_vchUserID				= @in_vchUserID				
											 ,@in_vchTranType			= @in_vchTranType			
											 ,@in_vchSubTranType		= @in_vchSubTranType		
