											 ,@in_vchShipToPhoneNumber 	= @in_vchShipToPhoneNumber 	
											 ,@in_vchBillToCode			= @in_vchBillToCode			
											 ,@in_vchBillToName			= @in_vchBillToName			
											 ,@in_vchBillToAddr1		= @in_vchBillToAddr1		
											 ,@in_vchBillToAddr2		= @in_vchBillToAddr2		
											 ,@in_vchBillToAddr3		= @in_vchBillToAddr3		
											 ,@in_vchBillToCity			= @in_vchBillToCity			
											 ,@in_vchBillToProvince		= @in_vchBillToProvince		
											 ,@in_vchBillToPostalCode	= @in_vchBillToPostalCode	
											 ,@in_vchBillToCountry		= @in_vchBillToCountry		
											 ,@in_vchBillToCountryName 	= @in_vchBillToCountryName 	
											 ,@in_vchBillToContactName 	= @in_vchBillToContactName 	
											 ,@in_vchBillToPhoneNumber	= @in_vchBillToPhoneNumber	
											 ,@in_vchComment			= @in_vchComment			
