											 ,@out_vchErrorMessage		= @in_vchMessage OUTPUT
				IF (@in_vchErrorCode <> '0')
					RETURN;

			GOTO PROCESS_LOG_LABEL;
		END
		
		PROCESS_LOG_LABEL:
   		------------------------------------------------------------
		--  Insert into Process Log
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT' SELECT 'Check Process Log: Variable is:' + ISNULL(@v_vchProcessLog, 'NULL')
		-- Future, Add a Log action for inserting into the Process Log
		
		IF (@v_vchProcessLog = 'YES' AND (ISNULL(@in_vchErrorCode,'') NOT IN ('0','')))
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT' SELECT 'Starting Process = YES'
			-- Future, Add a Log action for inserting into the Process Log
		 
			----------------------------------------------------------
			--  Check for Required Fields
			--  log_type, warehouse, tran code, start tran date, location, quantity 
			-- 	app_id, device, user id, error_code
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Required Fields for Process Log'
			-- Future, Add a Log action for inserting into the Process Log		
			IF ISNULL(@in_vchData1,'') = ''
				SET @in_vchData1 = @in_vchErrorCode
			IF @in_vchApplicationID IS NULL OR @in_vchUserID IS NULL OR @in_vchDevice IS NULL
				OR @in_vchErrorCode IS NULL OR @in_vchLogType IS NULL OR @in_vchData1 IS NULL
				OR @in_vchMessage IS NULL OR @in_vchProcess IS NULL OR @in_dtProcessDateTime IS NULL
			BEGIN
				------------------------------------------------------------
				--  Missing Required Fields 
				------------------------------------------------------------
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'
				
				IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  SELECT 'Field List:' +'App ID: ['+ISNULL(@in_vchApplicationID, '')+ '] Device ID: ['+ISNULL(@in_vchDevice, '')
																	  + '] Error Code: ['+ISNULL(@in_vchErrorCode, '') + '] Log Type: ['+ISNULL(@in_vchLogType, '') 
																	  + '] Data 1: ['+ISNULL(@in_vchData1, '')+ '] User ID: ['+ISNULL(@in_vchUserID, '')+ '] Message: ['+ISNULL(@in_vchMessage, '') 
																	  + '] Process: ['+ISNULL(@in_vchProcess, '')+ '] Process Date: ['+ISNULL(CONVERT(varchar(10), @in_dtProcessDateTime), '')+ '] Message: ['+ISNULL(@in_vchMessage, '') + ']' 
				
				-- Future, Add a Log action for inserting into the Process Log
				SET @v_vchErrorCode = 'ERROR-LOGMAN-003' -- Missing Required Fields
				SET @v_vchLogType =  'LOG MANAGER ERROR'
				SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
				SET @v_vchProcessData2 = 'Error Code: ['+ISNULL(@in_vchErrorCode, '')+ '] Log Type: ['+ISNULL(@in_vchLogType, '') + '] Warehouse ID: ['+ISNULL(@in_vchWhID, '') + '] Device ID: ['+ISNULL(@in_vchDevice, '') + ']' 
				SET @v_vchProcessData3 = 'Data1: ['+ISNULL(left(@in_vchData1,1000), '') + '] Message ['+ISNULL(left(@in_vchMessage,100), '') + ']'
				SET @v_vchProcessData4 = 'User ID: ['+ISNULL(@in_vchUserID, '') + '] App ID: ['+ISNULL(@in_vchApplicationID, '') + '] Process ['+ISNULL(@in_vchProcess, '') + '] Process Date Time ['+ISNULL(CONVERT(NVARCHAR(10), @in_dtProcessDateTime), '') + ']'
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
				GOTO WRITE_PROCESS_LOG;
			END
			
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Writing into Process Log'
			-- Future, Add a Log action for inserting into the Process Log		
		
			SET @v_vchErrorCode = @in_vchErrorCode
			SET @v_vchLogType =  @in_vchLogType
			
			SET @v_vchProcessData1 = ISNULL(@in_vchData1, dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].')
			SET @v_vchProcessData2 = ISNULL(@in_vchData2, 'Tran Type: '+ @in_vchTranType + ' Sub Tran Type: '+ @in_vchSubTranType)
			SET @v_vchProcessData3 = ISNULL(@in_vchData3, 'Active: ' + @v_vchIsActive)
			SET @v_vchProcessData4 = ISNULL(@in_vchData4, 'User ID: '+@in_vchUserID + ' App ID: ' + @in_vchApplicationID)
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '].'
			
			IF (@v_vchMessage LIKE '%NO RESOURCE CONFIGURED%')
				BEGIN
					SET @v_vchMessage = @in_vchMessage;
				END
				
			INSERT INTO [dbo].[t_com_process_log]
				   ([app_id]
				   ,[log_type]
				   ,[warehouse]
				   ,[device]
				   ,[process]
				   ,[process_datetime]
				   ,[data_1]
				   ,[data_2]
				   ,[data_3]
				   ,[data_4]
				   ,[message]
				   ,[create_date]
				   ,[create_by])
			 VALUES
				(LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
				, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL(@in_vchWhID, 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
				, GETDATE()
				, ISNULL(LEFT(@in_vchUserID, 25), 'SYSTEM'))
		
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Writing into Process Log Complete'
			-- Future, Add a Log action for inserting into the Process Log		
		END
		
		------------------------------------------------------------
		-- Check to see if we should log to the Windows Event Viewer
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Event Viewer Variable'
			-- Future, Add a Log action for inserting into the Process Log		
			
		IF @v_vchWinEventViewer IS NULL OR @v_vchWinEventViewer = 'NO'
			GOTO EXIT_LABEL;


		WINDOWS_EVENT_LABEL:
   		------------------------------------------------------------
		--  Insert into Windows Event Viewer Log
		------------------------------------------------------------
		IF @v_vchWinEventViewer = 'YES'
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing for Event Viewer'
				-- Future, Add a Log action for inserting into the Process Log		

				--  Insert into the Windows Event Viewer
				-- ???  
				SELECT ''
			END

		------------------------------------------------------------
		--  GOTO Exit becuase we are completed with SPROC
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Finished with Processing Now goto Exit Label'
		-- Future, Add a Log action for inserting into the Process Log		

   		GOTO EXIT_LABEL;
  
	-----------------------------------------------------------------------------------
	--  After setting the message variables now write to the Process Log
	--  To make this more generic, we should use the Log Manager Stored Procedure
	-----------------------------------------------------------------------------------
		WRITE_PROCESS_LOG:
		
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
		
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field List 1 :' +'App ID: ['+ISNULL(@in_vchApplicationID, '')+']'
					+'Log Type: ['+ISNULL(@v_vchMessage, '')+']'
					+'Warehouse: ['+ISNULL(@in_vchWhID, '') +']'
					+'Device: ['+ISNULL(@in_vchDevice, '')+']'
					+'Object Name: ['+ISNULL(@c_vchObjName, '')+']'
					+'Data1: ['+ISNULL(@v_vchProcessData1, '')+']'
			SELECT	'Field List 2 :' 		+'Data2: ['+ISNULL(@v_vchProcessData2, '')+']'
					+'Data3: ['+ISNULL(@v_vchProcessData3, '')+']'
					+'Data4: ['+ISNULL(@v_vchProcessData4, '')+']'
					+'Message: ['+ISNULL(@v_vchMessage, '')+']'
					+'User ID: ['+ISNULL(@in_vchUserID, '') + ']' 
		END
		
		IF @v_intLogLevel >= 5 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field Length: App ID: ['+str(len(@in_vchApplicationID),10) +']'
			SELECT	'Field Length: Log Type: ['+STR(len(@v_vchLogType), 10) +']'
			SELECT	'Field Length: Warehouse: ['+ str( len(@in_vchWhID),10) +']'
			SELECT	'Field Length: Device: ['+ str(len(@in_vchDevice) ,10) +']'
			SELECT	'Field Length: Object Name: ['+ str(len(@c_vchObjName) ,10) +']'
			SELECT	'Field Length: Data1: ['+ str(len (@v_vchProcessData1) ,10) +']'
			SELECT	'Field Length: Data2: ['+ str(len (@v_vchProcessData2) ,10) +']'
			SELECT	'Field Length: Data3: ['+ str(len (@v_vchProcessData3) ,10) +']'
			SELECT	'Field Length: Data4: ['+ str(len (@v_vchProcessData4) ,10) +']'
			SELECT	'Field Length: Message: ['+ str(len(@v_vchMessage) ,10) +']'
			SELECT	'Field Length: User ID: ['+ str( len(@in_vchUserID),10) +']'
		END
		
		INSERT INTO [dbo].[t_com_process_log]
			([app_id]
			,[log_type]
			,[warehouse]
			,[device]
			,[process]
			,[process_datetime]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[message]
			,[create_date]
			,[create_by])
		VALUES
			(LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
			, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
			, LEFT(ISNULL(@in_vchWhID, 'NO WH DEFINED'), 25)
			, LEFT(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
			, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
			, GETDATE()
			, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
			, LEFT(@v_vchProcessData2, 1000)
			, LEFT(@v_vchProcessData3, 1000)
			, LEFT(@v_vchProcessData4, 1000)
			, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
			, GETDATE()
			, ISNULL(LEFT(@in_vchUserID, 25), 'SYSTEM'))
			
		--Print 'Done with Insert Error into Process Log'
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Finished with Writing to the Process Log Now goto Exit Label'
		-- Future, Add a Log action for inserting into the Process Log	

		SET @in_vchErrorCode = @v_vchErrorCode
		SET @in_vchMessage = @v_vchMessage
		GOTO EXIT_LABEL;
		
    END TRY
        
-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
    BEGIN CATCH 
		-- Insert a message into the Process log about the Error
		-- Use the following functions to gather as much information as possible and load into the Process Log
		-- ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
		-- ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
		-- ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
		-- ERROR_STATE: returns the state number of the error.
		-- ERROR_LINE: returns the line number where the error occurred.
		-- ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
			-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
		
		If (@in_vchErrorCode = '0' or @in_vchErrorCode = '')
			SET @in_vchErrorCode = ERROR_NUMBER();

		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET @v_vchProcessData3 = ''
		SET @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		SET @in_vchErrorCode = @v_vchErrorCode
		SET @in_vchMessage = @v_vchMessage
		
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		if @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			select	'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			select 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			select 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			select 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			select 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			select 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			select 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id]
			   ,[log_type]
			   ,[warehouse]
			   ,[device]
			   ,[process]
			   ,[process_datetime]
			   ,[data_1]
			   ,[data_2]
			   ,[data_3]
			   ,[data_4]
			   ,[message]
			   ,[create_date]
			   ,[create_by])
		 VALUES
		 		(LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
				, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL(@in_vchWhID, 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, GETDATE()
				, ISNULL(@in_vchUserID,'SYSTEM'))	
				
		--SET @in_vchErrorCode = 'CONTACT_ADMIN';
		--SELECT @in_vchMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@in_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				
	END CATCH
	
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------
EXIT_LABEL:
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Exiting Sproc'
		-- Future, Add a Log action for inserting into the Process Log		
    
END
