/****** Object:  StoredProcedure [dbo].[usp_manage_inventory]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_manage_inventory]
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchStatusID			UNIQUEIDENTIFIER,
	@in_vchPalentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_fltQty				FLOAT,
	@in_fltQtyAllocate		FLOAT = NULL,
	@in_fltQtyIncoming		FLOAT = NULL,
	@in_vchInventoryType	NVARCHAR(20),
	@in_vchUserID			NVARCHAR(25),
	@in_vchReceiveDate		DATE,
	@in_dtMFGDate			DATE, 
	@in_vchInventoryID		UNIQUEIDENTIFIER OUTPUT,
    @in_vchAttributeGroupID	UNIQUEIDENTIFIER OUTPUT,
    @in_vchErrorCode		NVARCHAR(50) OUTPUT,
    @in_vchMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
		
		DECLARE @Round	INT
		SET @in_vchErrorCode = '0';
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		
		BEGIN TRY
			IF (@in_vchInventoryID IS NOT NULL) 
				BEGIN
					UPDATE t_wms_inventory SET
						quantity = ROUND((quantity + @in_fltQty),@Round)
						,quantity_allocated = ROUND((quantity_allocated + @in_fltQtyAllocate),@Round)
						,quantity_incoming =  ROUND((quantity_incoming + @in_fltQtyIncoming),@Round)
						,receive_date = @in_vchReceiveDate
						,mfg_date = @in_dtMFGDate
					WHERE inventory_id = @in_vchInventoryID
				END
			ELSE
				BEGIN
					SET @in_vchInventoryID = NEWID();
					SET @in_vchAttributeGroupID = NEWID();
					
					INSERT INTO t_wms_inventory(inventory_id
						, wh_master_id
						, owner_id
						, wh_item_master_id
						, location_id
						, inventory_status_id
						, inv_type
						, attribute_group_id
						, quantity
						, quantity_allocated
						, quantity_incoming
						, lpn
						, parent_lpn
						, receive_date
						, mfg_date
						, create_date
						, create_by)
					VALUES (@in_vchInventoryID
						,@in_vchWhMasterID
						,@in_vchOwnerID
						,@in_vchWhItemMasterID
						,@in_vchLocationID
						,@in_vchStatusID
						,@in_vchInventoryType
						,@in_vchAttributeGroupID
						,ROUND(@in_fltQty,@Round)
						,ROUND(@in_fltQtyAllocate,@Round)
						,ROUND(@in_fltQtyIncoming,@Round)
						,@in_vchLPN
						,@in_vchPalentLPN
						,@in_vchReceiveDate 
						,@in_dtMFGDate
						,GETDATE()
						,@in_vchUserID)					
				END
		END TRY
		BEGIN CATCH
			SET @in_vchErrorCode = ERROR_NUMBER();
			SET @in_vchMessage = ERROR_MESSAGE();
		END CATCH	
END

GO
