CREATE PROCEDURE [dbo].[usp_manage_inventory_attribute]
	@in_vchLot					NVARCHAR(100),
	@in_vchExpiryDate			NVARCHAR(100),
	@in_vchSerialNo				NVARCHAR(100),
	@in_vchAttribute1			NVARCHAR(100),
	@in_vchAttribute2			NVARCHAR(100),
	@in_vchAttribute3			NVARCHAR(100),
	@in_vchAttribute4			NVARCHAR(100),
	@in_vchAttribute5			NVARCHAR(100),
	@in_fltQty					FLOAT,
	@in_fltQtyAllocate			FLOAT = NULL,
	@in_fltQtyIncoming			FLOAT = NULL,
	@in_vchInventoryID			UNIQUEIDENTIFIER,
	@in_vchAttributeGroupID		UNIQUEIDENTIFIER,
	@in_vchLotControl			VARCHAR(5),
    @in_vchSNControl			VARCHAR(5),
    @in_vchExpiryDateControl	VARCHAR(5),
	@in_vchAttribute1Control	VARCHAR(5),
	@in_vchAttribute2Control	VARCHAR(5),
	@in_vchAttribute3Control	VARCHAR(5),
	@in_vchAttribute4Control	VARCHAR(5),
	@in_vchAttribute5Control	VARCHAR(5),
    @in_vchUserID				NVARCHAR(25),
	@in_vchErrorCode			NVARCHAR(50) OUTPUT,
    @in_vchMessage				NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @v_vchFullControl	VARCHAR(4)
	DECLARE @Round				INT
    
	SET @v_vchFullControl = 'FULL';
	SET @in_fltQty = ISNULL(@in_fltQty,0)
	SET @in_fltQtyAllocate = ISNULL(@in_fltQtyAllocate,0)
	SET @in_fltQtyIncoming = ISNULL(@in_fltQtyIncoming,0)

	SET @in_vchErrorCode	= '0';
    SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
    
    BEGIN TRY
		IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @in_vchInventoryID AND attribute_group_id = @in_vchAttributeGroupID)
			BEGIN
				IF(@in_vchSNControl = @v_vchFullControl)
					BEGIN
						IF NOT EXISTS (SELECT inv_attribute_id FROM t_wms_inventory_attribute 
										WHERE inventory_id = @in_vchInventoryID 
										AND attribute_group_id = @in_vchAttributeGroupID 
										AND attribute_value = @in_vchSerialNo
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
								BEGIN
									INSERT INTO t_wms_inventory_attribute
										( inv_attribute_id
										, inventory_id
										, inv_attribute_type_id
										, attribute_group_id
										, attribute_value
										, quantity
										, quantity_allocated
										, quantity_incoming
										, create_date
										, create_by)
									VALUES
										( NEWID()
										, @in_vchInventoryID
										, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
										, @in_vchAttributeGroupID
										, @in_vchSerialNo
										, ROUND(@in_fltQty,@Round)
										, ROUND(@in_fltQtyAllocate,@Round)
										, ROUND(@in_fltQtyIncoming,@Round)
										, GETDATE()
										, @in_vchUserID)
								END
					END
				
				IF(@v_vchFullControl IN (@in_vchLotControl,@in_vchExpiryDateControl,@in_vchAttribute1Control,@in_vchAttribute2Control,@in_vchAttribute3Control,@in_vchAttribute4Control,@in_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET 
							 quantity = ROUND(ROUND(quantity,@Round) + ROUND(@in_fltQty,@Round),@Round)
							,quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) + ROUND(@in_fltQtyAllocate,@Round),@Round)
							,quantity_incoming  = ROUND(ROUND(quantity_incoming,@Round) + ROUND(@in_fltQtyIncoming,@Round),@Round)
						WHERE inventory_id = @in_vchInventoryID 
						AND attribute_group_id = @in_vchAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
					END
			END
		ELSE
			BEGIN
				-- insert new serial
				IF(@in_vchSNControl = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							(inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
							, @in_vchAttributeGroupID
							, @in_vchSerialNo
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)
					END

				--Insert New Lot
				IF(@in_vchLotControl = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
						    ( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
							, @in_vchAttributeGroupID
							, @in_vchLot
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END
				
				--Insert New Expiry Date
				IF(@in_vchExpiryDateControl = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
							, @in_vchAttributeGroupID
							, @in_vchExpiryDate
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Attribute1
				IF(@in_vchAttribute1Control = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
							, @in_vchAttributeGroupID
							, @in_vchAttribute1
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Attribute2
				IF(@in_vchAttribute2Control = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
							, @in_vchAttributeGroupID
							, @in_vchAttribute2
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Attribute3
				IF(@in_vchAttribute3Control = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
							, @in_vchAttributeGroupID
							, @in_vchAttribute3
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Attribute4
				IF(@in_vchAttribute4Control = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
							, @in_vchAttributeGroupID
							, @in_vchAttribute4
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END

				--Insert New Attribute5
				IF(@in_vchAttribute5Control = @v_vchFullControl)
					BEGIN
						INSERT INTO t_wms_inventory_attribute
							( inv_attribute_id
							, inventory_id
							, inv_attribute_type_id
							, attribute_group_id
							, attribute_value
							, quantity
							, quantity_allocated
							, quantity_incoming
							, create_date
							, create_by)
						VALUES
							( NEWID()
							, @in_vchInventoryID
							, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
							, @in_vchAttributeGroupID
							, @in_vchAttribute5
							, ROUND(@in_fltQty,@Round)
							, ROUND(@in_fltQtyAllocate,@Round)
							, ROUND(@in_fltQtyIncoming,@Round)
							, GETDATE()
							, @in_vchUserID)				
					END
			END
	END TRY
	BEGIN CATCH
		SET @in_vchErrorCode = ERROR_NUMBER();
		SET @in_vchMessage = ERROR_MESSAGE();
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[usp_manage_inventory_control]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_manage_inventory_control]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchInventoryType	NVARCHAR(50),
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		NVARCHAR(50),
	@in_fltQuantity			FLOAT,
	@in_fltQtyAllocate		FLOAT,
	@in_fltQtyIncoming		FLOAT,
	@in_vchPrimaryItemUomID	UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatusID		UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		NVARCHAR(100),
	@in_vchExpiryDate		NVARCHAR(100),
	@in_vchSerialNumber		NVARCHAR(100),
	@in_vchAttribute1		NVARCHAR(100),
	@in_vchAttribute2		NVARCHAR(100),
	@in_vchAttribute3		NVARCHAR(100),
	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100),
	@in_dReceiveDate		DATE = NULL,	--กรณีที่ move จะต้องเอา receive data เดิมมาใส่
	@in_dtMFGDate			DATE = NULL,	--กรณีที่ Control Expiry Date และต้องการใส่ MFG DATE ต้องส่งค่ามา
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@out_fltAfterInvQuantity FLOAT OUTPUT,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS 
BEGIN
	SET NOCOUNT ON; 
	DECLARE @Round						INT = 0,
			@v_vchData1					NVARCHAR(255),
			@v_vchData2					NVARCHAR(255),
			@v_vchData3					NVARCHAR(255),
			@v_vchData4					NVARCHAR(255),
			@v_dtProcessDateTime		DATETIME,
			@v_vchLocal					VARCHAR(10),
			@v_vchInventoryID			UNIQUEIDENTIFIER,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER,
			@v_vchLotControl			VARCHAR(5),
			@v_vchExpiryDateControl		VARCHAR(5),
			@v_vchSNControl				VARCHAR(5),
			@v_vchAttribute1Control		VARCHAR(5),
			@v_vchAttribute2Control		VARCHAR(5),
			@v_vchAttribute3Control		VARCHAR(5),
			@v_vchAttribute4Control		VARCHAR(5),
			@v_vchAttribute5Control		VARCHAR(5),
			@v_vchLPNControl			VARCHAR(3),
			@v_dtReceiveDate			DATE = NULL,
			@v_dtMfgDate				DATE = NULL,
			@v_fltWidth					FLOAT = 0,
			@v_fltLength				FLOAT = 0,
			@v_fltHeight				FLOAT = 0,
			@v_fltGrossWeight			FLOAT = 0,
			@v_intPercentTolerance		FLOAT = 0,
			@v_intPercenToleranceWeight FLOAT = 0,
			@v_fltVolumn				FLOAT = 0,	--item
			@v_fltTotalWeight			FLOAT = 0,	--item
			@v_fltLocTotalVolumn		FLOAT = 0,
			@v_fltLocTotalWeight		FLOAT = 0,
			@v_fltLocWidth				FLOAT = 0,
			@v_fltLocLength				FLOAT = 0,
			@v_fltLocHeight				FLOAT = 0,
			@v_fltLocGrossWeight		FLOAT = 0,
			@v_fltLocVolumn				FLOAT = 0,
			@v_rultCheckFullLPN			VARCHAR(3) = 'NO',
			@v_fltInvQty				FLOAT,
			
			@v_vchRemark				NVARCHAR(255) = NULL

	BEGIN TRY
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_rultCheckFullLPN = value FROM t_wms_rule WHERE rule_code = 'RULE_CHECK_FULL_LPN' AND is_active = 'YES'
		SELECT @v_vchLocal = dbo.usf_get_locale_id(@in_vchUserID)
		SET @in_fltQuantity = ROUND(@in_fltQuantity,@Round)
		
		IF ISNULL(@in_vchExpiryDate,'') <> ''
			SET @in_vchExpiryDate = CONVERT(VARCHAR,CONVERT(DATE,@in_vchExpiryDate),112)
		ELSE
			SET @in_vchExpiryDate = NULL

		SELECT @in_vchItemMasterID = item_master_id
			,@v_vchLotControl	= lot_control
			,@v_vchExpiryDateControl = expiry_date_control
			,@v_vchSNControl = sn_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM t_wms_item 
		WHERE item_master_id = @in_vchItemMasterID 
		AND owner_id = @in_vchOwnerID 
		AND is_active = 'YES'

		IF (@in_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--Check Item Control
		IF @v_vchLotControl = 'NONE'
			SET @in_vchLotNumber = NULL
		IF @v_vchExpiryDateControl = 'NONE'
			SET @in_vchExpiryDate = NULL
		IF @v_vchSNControl = 'NONE'
			SET @in_vchSerialNumber = NULL
		IF @v_vchAttribute1Control = 'NONE'
			SET @in_vchAttribute1 = NULL
		IF @v_vchAttribute2Control = 'NONE'
			SET @in_vchAttribute2 = NULL
		IF @v_vchAttribute3Control = 'NONE'
			SET @in_vchAttribute3 = NULL
		IF @v_vchAttribute4Control = 'NONE'
			SET @in_vchAttribute4 = NULL
		IF @v_vchAttribute5Control = 'NONE'
			SET @in_vchAttribute5 = NULL 

		--Check Serial Duplicate
		IF (@v_vchSNControl = 'FULL')
			BEGIN
				SET @in_fltQuantity = 1
				IF EXISTS(SELECT inv.inventory_id FROM t_wms_inventory inv
						  INNER JOIN (SELECT inventory_id, attribute_group_id, attribute_value AS serial_number
						  			  FROM dbo.t_wms_inventory_attribute
						  			  WHERE inv_attribute_type_id = '7D534998-B76A-421C-9C33-EFA174765BB8'
						  			  ) AS invSN ON (inv.inventory_id = invSN.inventory_id) AND (inv.attribute_group_id = invSN.attribute_group_id) 
						  WHERE inv.wh_item_master_id = @in_vchWhItemMasterID 
						  AND serial_number = @in_vchSerialNumber)
					BEGIN
						SET @out_ErrorCode = 'SERIAL_IS_ALREADY_EXISTS';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchSerialNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-- Check duplicate parent lpn.
		IF (ISNULL(@in_vchParentLPN,'') <> '')
			BEGIN
				DECLARE @v_vchDubLocation	NVARCHAR(50) = NULL

				SELECT TOP 1 @v_vchDubLocation = loc.location
				FROM t_wms_inventory inv
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				WHERE inv.wh_master_id = @in_vchWhMasterID 
				AND ISNULL(inv.location_id,'') <> ISNULL(@in_vchLocationID,'')
				AND inv.parent_lpn = @in_vchParentLPN
				
				IF (ISNULL(@v_vchDubLocation,'') <> '')
					BEGIN
						SET @out_ErrorCode = 'PARENT_LPN_DUPPLICATE';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--Calculate Volumn & Weight of items
		SELECT @v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom 
		WHERE item_master_id = @in_vchItemMasterID 
		AND item_uom_id = @in_vchPrimaryItemUomID
		
		SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @in_fltQuantity,2)
		SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @in_fltQuantity,2)

		--Get data for calculate volumn
		SELECT @v_fltLocWidth = ISNULL(width,0)
			,@v_fltLocLength = ISNULL(length,0)
			,@v_fltLocHeight = ISNULL(height,0)
			,@v_fltLocGrossWeight = ISNULL(gross_weight,0)
			,@v_fltLocTotalWeight = ISNULL(total_weight,0)
			,@v_fltLocTotalVolumn = ISNULL(total_volumn,0)
			,@v_vchLPNControl = lpn_controlled
		FROM t_wms_location 
		WHERE wh_master_id = @in_vchWhMasterID 
		AND location_id = @in_vchLocationID 
		AND is_active = 'YES'
		
		--Calculate volumn & weight of LPN
		IF (@v_rultCheckFullLPN = 'YES' AND @v_vchLPNControl = 'YES')
			BEGIN
				DECLARE @v_fltPalletID			UNIQUEIDENTIFIER = NULL,
						@v_fltPLGrossWeight		FLOAT = 0,
						@v_fltPLVolumn			FLOAT = 0,
						@v_fltInvVolumnByLPN	FLOAT = 0,
						@v_fltInvWeightByLPN	FLOAT = 0

				--Calculate Volumn & Weight of pallet
				SELECT @v_fltPalletID = pallet_id
					,@v_fltPLVolumn = ROUND(ISNULL(width,0) * ISNULL(length,0) * ISNULL(height,0),@Round)
					,@v_fltPLGrossWeight = ISNULL(gross_weight,0)
				FROM t_wms_pallet_type 
				WHERE is_active = 'YES'
				
				IF (@v_fltPalletID IS NULL)
					BEGIN
						SET @out_ErrorCode = 'PALLET_TYPE_CANNOT_BE_EMPTY';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_fltInvVolumnByLPN = SUM(ISNULL(volumn_by_lpn,0))
					,@v_fltInvWeightByLPN = SUM(ISNULL(weight_by_lpn,0))
				FROM t_wms_inventory
				WHERE lpn = @in_vchLPN

				--Volumn of qty input + volumn in inventory เทียบกับ volumn ที่กำหนด
				IF (@v_fltVolumn + ISNULL(@v_fltInvVolumnByLPN,0)) > @v_fltPLVolumn
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				IF (@v_fltTotalWeight + ISNULL(@v_fltInvWeightByLPN,0)) > @v_fltPLGrossWeight
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LPN';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,@in_vchLPN,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		IF (@v_vchLPNControl = 'NO')
			BEGIN
				SET @in_vchLPN = NULL
			END

		--Calculate Volumn & Weight of Location
		IF (@v_fltLocWidth > 0 AND @v_fltLocLength > 0 AND @v_fltLocHeight > 0 AND @v_fltLocGrossWeight > 0)
			BEGIN
				--Calculate Volumn
				SET @v_fltLocVolumn = (@v_fltLocWidth * @v_fltLocLength * @v_fltLocHeight)
		
				--Check volumn and weight
				IF @v_fltVolumn > (@v_fltLocVolumn - @v_fltLocTotalVolumn)
					BEGIN
						SET @out_ErrorCode = 'VOLUMN_MORE_THAN_VOLUMN_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				IF @v_fltTotalWeight > (@v_fltLocGrossWeight - @v_fltLocTotalWeight)
					BEGIN
						SET @out_ErrorCode = 'WEIGHT_MORE_THAN_WEIGHT_LOCATION';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocal,'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				UPDATE t_wms_location SET 
					 total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
					,total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE location_id = @in_vchLocationID
			END

		--Get Inventory
		SET @v_dtReceiveDate = GETDATE()
		SELECT TOP 1 @v_vchInventoryID = inventory_id
			,@v_vchAttributeGroupID = attribute_group_id
			,@v_dtReceiveDate = receive_date
			,@v_dtMfgDate = mfg_date
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND inventory_status_id = @in_vchInvStatusID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

		IF @in_dReceiveDate IS NOT NULL
			BEGIN
				--กรณีที่เป็นการ Move item จะต้องเอา receive date เดิมมาด้วย
				SET @v_dtReceiveDate = @in_dReceiveDate
			END
		ELSE 
			BEGIN
				--Set Receive Date
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_RECEIVE_DATE' AND is_active = 'YES') = 'NO')
					BEGIN
						SET @v_dtReceiveDate = CONVERT(DATE,GETDATE())
					END
			END

		--กรณีที่มีการเก็บ MFG Date เวลา Save ต้อง MFG Date มา ถ้าไม่ส่งมา จะ get inventory เดิมไป  
		IF @in_dtMFGDate IS NOT NULL
			SET @v_dtMfgDate = @in_dtMFGDate
	 
		--Check Location & Duplicate LPN & Check Capacity
		EXEC usp_location_validation_all @in_vchApplicationID	= @in_vchApplicationID	
									 ,@in_vchUserID				= @in_vchUserID
									 ,@in_vchWarehouseID		= @in_vchWhMasterID		
									 ,@in_vchLocationID			= @in_vchLocationID
									 ,@in_vchParentLPN			= @in_vchParentLPN
									 ,@in_vchLPN				= @in_vchLPN
									 ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID
									 ,@in_vchItemNumber			= @in_vchItemNumber
									 ,@in_vchOwnerID			= @in_vchOwnerID
									 ,@in_vchInventoryStatusID	= @in_vchInvStatusID
									 ,@in_vchLotNumber			= @in_vchLotNumber
									 ,@in_vchExpiryDate			= @in_vchExpiryDate
									 ,@in_vchSerialNo			= @in_vchSerialNumber
									 ,@in_vchAttribute1			= @in_vchAttribute1
									 ,@in_vchAttribute2			= @in_vchAttribute2
									 ,@in_vchAttribute3			= @in_vchAttribute3
									 ,@in_vchAttribute4			= @in_vchAttribute4
									 ,@in_vchAttribute5			= @in_vchAttribute5
									 ,@in_vchLotControl			= @v_vchLotControl			
									 ,@in_vchExpiryDateControl	= @v_vchExpiryDateControl
									 ,@in_vchSNControl			= @v_vchSNControl			
									 ,@in_vchAttribute1Control	= @v_vchAttribute1Control
									 ,@in_vchAttribute2Control	= @v_vchAttribute2Control
									 ,@in_vchAttribute3Control	= @v_vchAttribute3Control
									 ,@in_vchAttribute4Control	= @v_vchAttribute4Control
									 ,@in_vchAttribute5Control	= @v_vchAttribute5Control
									 ,@in_ReceiveDate			= @v_dtReceiveDate		
									 ,@out_vchErrorCode			= @out_ErrorCode OUTPUT
									 ,@out_vchMessage			= @out_ErrorMessage OUTPUT	
		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;
		
		SET @v_vchInventoryID = NULL
		SET @v_vchAttributeGroupID = NULL
		SELECT @v_vchInventoryID = inventory_id
			,@v_vchAttributeGroupID = attribute_group_id
			,@v_fltInvQty = quantity
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND inventory_status_id = @in_vchInvStatusID
		AND receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchWhMasterID
								, @in_vchOwnerID			= @in_vchOwnerID
								, @in_vchWhItemMasterID		= @in_vchWhItemMasterID
								, @in_vchLocationID			= @in_vchLocationID
								, @in_vchStatusID			= @in_vchInvStatusID
								, @in_vchPalentLPN			= @in_vchParentLPN
								, @in_vchLPN				= @in_vchLPN
								, @in_fltQty				= @in_fltQuantity
								, @in_fltQtyAllocate		= @in_fltQtyAllocate
								, @in_fltQtyIncoming		= @in_fltQtyIncoming
								, @in_vchInventoryType		= @in_vchInventoryType
								, @in_vchUserID				= @in_vchUserID
								, @in_vchReceiveDate		= @v_dtReceiveDate
								, @in_dtMFGDate				= @v_dtMfgDate
								, @in_vchInventoryID		= @v_vchInventoryID OUTPUT
								, @in_vchAttributeGroupID	= @v_vchAttributeGroupID OUTPUT	
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage OUTPUT	

		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				EXEC usp_manage_inventory_attribute 
					  @in_vchLot				= @in_vchLotNumber
					, @in_vchExpiryDate			= @in_vchExpiryDate
					, @in_vchSerialNo			= @in_vchSerialNumber
					, @in_vchAttribute1			= @in_vchAttribute1
					, @in_vchAttribute2			= @in_vchAttribute2
					, @in_vchAttribute3			= @in_vchAttribute3
					, @in_vchAttribute4			= @in_vchAttribute4
					, @in_vchAttribute5			= @in_vchAttribute5
					, @in_fltQty				= @in_fltQuantity
					, @in_fltQtyAllocate		= @in_fltQtyAllocate
					, @in_fltQtyIncoming		= @in_fltQtyIncoming
					, @in_vchInventoryID		= @v_vchInventoryID
					, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
					, @in_vchLotControl			= @v_vchLotControl
					, @in_vchSNControl			= @v_vchSNControl
					, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
					, @in_vchAttribute1Control	= @v_vchAttribute1Control
					, @in_vchAttribute2Control	= @v_vchAttribute2Control
					, @in_vchAttribute3Control	= @v_vchAttribute3Control
					, @in_vchAttribute4Control	= @v_vchAttribute4Control
					, @in_vchAttribute5Control	= @v_vchAttribute5Control
					, @in_vchUserID				= @in_vchUserID
					, @in_vchErrorCode			= @out_ErrorCode OUTPUT
					, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
				IF(@out_ErrorCode <> '0')
					GOTO WRITE_PROC;
			END	

		IF (@v_rultCheckFullLPN = 'YES' AND @v_vchLPNControl = 'YES')
			BEGIN
				--update volumn & weight ของ LPN
				UPDATE t_wms_inventory SET 
					 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
					,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
				WHERE inventory_id = @v_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID		
			END	

		SET @out_fltAfterInvQuantity = ISNULL(@v_fltInvQty,0) + @in_fltQuantity;
		SET @out_ErrorCode = '0'
		SET @out_ErrorMessage = 'Save Success'
		RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------				
				SET @v_dtProcessDateTime = GETDATE();
				SET @v_vchData1 = 'Warehouse ['+ CONVERT(VARCHAR(40),@in_vchWhID) +']'
				SET @v_vchData2 = 'Location ID ['+ CONVERT(VARCHAR(36),@in_vchLocationID) +']'
				SET @v_vchData3 = 'Item Number ['+ ISNULL(@in_vchItemNumber,'') +']'
				SET @v_vchData4 = 'Lot Number ['+ ISNULL(@in_vchLotNumber,'') +']'
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWhID,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = 'usp_manage_inventory_control',
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchData1,
					@in_vchData2 = @v_vchData2,
					@in_vchData3 = @v_vchData3,
					@in_vchData4 = @v_vchData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END	   
 	END TRY
	BEGIN CATCH   
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchData1 = 'Warehouse ['+ CONVERT(VARCHAR(40),@in_vchWhID) +']'
		SET @v_vchData2 = 'Location ID ['+ CONVERT(VARCHAR(36),@in_vchLocationID) +']'
		SET @v_vchData3 = 'Item Number ['+ ISNULL(@in_vchItemNumber,'') +']'
		SET @v_vchData4 = 'Lot Number ['+ ISNULL(@in_vchLotNumber,'') +']'
		SET @out_ErrorCode = ERROR_NUMBER()
		SET @out_ErrorMessage = ERROR_MESSAGE()

		EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWhID,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = 'usp_manage_inventory_control',
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchData1,
					@in_vchData2 = @v_vchData2,
					@in_vchData3 = @v_vchData3,
					@in_vchData4 = @v_vchData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
					
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_mapping_customer_location]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 
CREATE PROCEDURE [dbo].[usp_mapping_customer_location]
	@in_startRowIndex			INT,
	@in_maximumRows				INT,
	@in_vchCondition			NVARCHAR(1000) = '',
	@in_vchSort					NVARCHAR(1000) = '',
	@in_switchType				NVARCHAR(10),
	@out_rowCount				INT = 0 OUTPUT,

	@customer_id				uniqueidentifier,
	@wh_master_id				uniqueidentifier

-----------------------------------------------------
AS
BEGIN

DECLARE @str_query			NVARCHAR(MAX);
DECLARE @v_Condition		NVARCHAR(1000)	=	'';
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

--select @v_cur_date
IF @in_vchCondition != ''
BEGIN
	SET @v_Condition = 'WHERE ' + @in_vchCondition
END
-----------------------------------------------------

Declare @str_customer_id  NVARCHAR(50) = convert(nvarchar(50),@customer_id);
Declare @str_wh_master_id  NVARCHAR(50) = convert(nvarchar(50),@wh_master_id);

SET		@str_query = '(select convert(nvarchar(50),l.location_id) as key_id,
l.location_id,
l.location,
wh.wh_id,
wh.wh_master_id,
case when c_loc.customer_location_id  is not null then ''YES'' else ''NO'' end  as map_status,
cast(case when c_loc.customer_location_id  is not null then 1 else 0 end as bit) as is_active
from t_wms_location as l
inner join t_wms_wh as wh on l.wh_master_id = wh.wh_master_id
left join t_wms_customer_location as c_loc on c_loc.location_id = l.location_id
where l.is_active = ''YES'' and l.loc_type = ''STORE'' and l.wh_master_id = '''+ @str_wh_master_id +'''
and l.location_id not in (select cus_loc.location_id from t_wms_customer_location as cus_loc where cus_loc.customer_id  <> '''+@str_customer_id+''')) as qry '+ @v_Condition 
--print @str_query

EXEC [dbo].[_usp_string_query_paging] @in_startRowIndex,@in_maximumRows,@str_query,@in_vchSort,@in_switchType, @out_rowCount OUTPUT


END


GO
/****** Object:  StoredProcedure [dbo].[usp_mapping_customer_location_save]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[usp_mapping_customer_location_save]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_xmlLocationItemInsert XML,
	@in_xmlLocationItemDelete XML,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans	BIT = 0
	DECLARE @c_vchObjName		VARCHAR(50) = 'usp_wms_mapping_customer_location'
	DECLARE @v_dtProcessDateTime DATETIME = GETDATE()
	DECLARE @v_vchWarehouse		VARCHAR(40)
	DECLARE @DocHandle			INT = NULL
	
BEGIN TRY
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1
 	
	IF @in_xmlLocationItemDelete IS NOT NULL
	BEGIN --DELETE 
		EXEC sp_xml_preparedocument @DocHandle OUTPUT, @in_xmlLocationItemDelete
		DECLARE @tDelLocItem AS TABLE
		( 
			customer_key_id	VARCHAR(100)
		)
		INSERT INTO @tDelLocItem
		SELECT customer_key_id
		FROM OpenXML(@DocHandle,'UnSelect/key_id',2)
		WITH 
		( 
			customer_key_id	 [varchar](100) 
		)
		EXEC sp_xml_removedocument @DocHandle

		DELETE t_wms_customer_location WHERE CONVERT(VARCHAR(36),location_id)+'_' +CONVERT(VARCHAR(36),customer_id) IN (SELECT customer_key_id FROM @tDelLocItem)
	END
 
 	IF @in_xmlLocationItemInsert IS NOT NULL
	BEGIN --INSERT 
		SET @DocHandle = NULL;
		EXEC sp_xml_preparedocument @DocHandle OUTPUT, @in_xmlLocationItemInsert
		DECLARE @tInsLocItem AS TABLE
		( 
			location_id		VARCHAR(40),			
			customer_id	VARCHAR(40)
		)

		INSERT INTO @tInsLocItem
		SELECT [location_id], [customer_id]
		FROM OpenXML(@DocHandle,'Select/key_id',2)
		WITH 
		( 
			[location_id]	 [varchar](40),
			[customer_id] [varchar](40) 
		)
		EXEC sp_xml_removedocument @DocHandle
	
		INSERT INTO [dbo].[t_wms_customer_location]
			([customer_location_id]
			,[customer_id]
			,[location_id]
			,[is_active]
			,[create_date]
			,[create_by])
		SELECT NEWID()
			,customer_id
			,location_id
			,'YES'
			,GETDATE()
			,@in_vchUserID
		FROM @tInsLocItem
	END
	
	COMMIT TRANSACTION;

	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;
		
	-------------------------------------------------
	-- Write process log
	-------------------------------------------------
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = 'Location Item Mapping',
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END
		
END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans <> 0)
		ROLLBACK TRANSACTION;
 
	IF (ISNULL(@out_ErrorCode,'') = '' OR @out_ErrorCode = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	SET @v_dtProcessDateTime = GETDATE(); 
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @out_ErrorCode,
		@in_vchData2 = @out_ErrorMessage,
		@in_vchData3 = NULL,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
			
END CATCH	
END
 
