/****** Object:  StoredProcedure [dbo].[usp_mapping_location_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_mapping_location_item]
	@in_startRowIndex			INT,
	@in_maximumRows				INT,
	@in_vchCondition			NVARCHAR(1000) = '',
	@in_vchSort					NVARCHAR(1000) = '',
	@in_switchType				NVARCHAR(10),
	@out_rowCount				INT = 0 OUTPUT,

	@location_id				uniqueidentifier

-----------------------------------------------------
AS
BEGIN

DECLARE @str_query			NVARCHAR(MAX);
DECLARE @v_Condition		NVARCHAR(1000)	=	'';
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

--select @v_cur_date
IF @in_vchCondition != ''
BEGIN
	SET @v_Condition = 'WHERE ' + @in_vchCondition
END
-----------------------------------------------------

Declare @str_location_id  NVARCHAR(50) = convert(nvarchar(50),@location_id);

SET		@str_query = '(SELECT tmp2.*,
case when tmp2.is_active = 1 then ''YES'' else ''NO'' end as map_status
 FROM
(
	SELECT 
	convert(nvarchar(50),tmp.location_id) + ''_'' + convert(nvarchar(50),tmp.item_master_id) as key_id
	,tmp.wh_id
	,tmp.wh_master_id
	,tmp.location
	,tmp.location_id
	,tmp.item_number
	,tmp.item_master_id
	,cast(case when loc_i.item_location_id  is not null then 1 else 0 end as bit) as is_active
	,loc_i.create_by
	,loc_i.create_date
	,tmp.loc_type
	FROM
	(
		SELECT loc.location
			,loc.location_id
			,itm.item_number
			,itm.item_master_id
			,loc.wh_id
			,loc.wh_master_id
			,loc.loc_type
		FROM t_wms_item as itm
		, (SELECT l.location_id,l.location,l.loc_type,l.wh_master_id, wh.wh_id FROM t_wms_location as l
		   INNER JOIN t_wms_wh as wh on l.wh_master_id = wh.wh_master_id
		   WHERE l.location_id = '''+ @str_location_id +'''
		   ) as loc
	) as tmp
	INNER JOIN t_wms_wh_item as wh_itm ON wh_itm.wh_master_id = tmp.wh_master_id AND wh_itm.item_master_id = tmp.item_master_id
	LEFT JOIN t_wms_location_item as loc_i ON loc_i.item_master_id = tmp.item_master_id AND loc_i.location_id = tmp.location_id
) as tmp2
) as qry '+ @v_Condition 
--print @str_query

EXEC [dbo].[_usp_string_query_paging] @in_startRowIndex,@in_maximumRows,@str_query,@in_vchSort,@in_switchType, @out_rowCount OUTPUT


END
GO
/****** Object:  StoredProcedure [dbo].[usp_mapping_location_item_save]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_mapping_location_item_save]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_xmlLocationItemInsert XML,
	@in_xmlLocationItemDelete XML,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans	BIT = 0
	DECLARE @c_vchObjName		VARCHAR(50) = 'usp_wms_mapping_location_item'
	DECLARE @v_dtProcessDateTime DATETIME = GETDATE()
	DECLARE @v_vchWarehouse		VARCHAR(40)
	DECLARE @DocHandle			INT = NULL
	
BEGIN TRY
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1
 	
	IF @in_xmlLocationItemDelete IS NOT NULL
	BEGIN --DELETE 
		EXEC sp_xml_preparedocument @DocHandle OUTPUT, @in_xmlLocationItemDelete
		DECLARE @tDelLocItem AS TABLE
		( 
			item_key_id	VARCHAR(100)
		)
		INSERT INTO @tDelLocItem
		SELECT item_key_id
		FROM OpenXML(@DocHandle,'UnSelect/key_id',2)
		WITH 
		( 
			item_key_id	 [varchar](100) 
		)
		EXEC sp_xml_removedocument @DocHandle

		DELETE t_wms_location_item WHERE CONVERT(VARCHAR(36),location_id)+'_' +CONVERT(VARCHAR(36),item_master_id) IN (SELECT item_key_id FROM @tDelLocItem)
	END
 
 	IF @in_xmlLocationItemInsert IS NOT NULL
	BEGIN --INSERT 
		SET @DocHandle = NULL;
		EXEC sp_xml_preparedocument @DocHandle OUTPUT, @in_xmlLocationItemInsert
		DECLARE @tInsLocItem AS TABLE
		( 
			location_id		VARCHAR(40),			
			item_master_id	VARCHAR(40)
		)

		INSERT INTO @tInsLocItem
		SELECT [location_id], [item_master_id]
		FROM OpenXML(@DocHandle,'Select/key_id',2)
		WITH 
		( 
			[location_id]	 [varchar](40),
			[item_master_id] [varchar](40) 
		)
		EXEC sp_xml_removedocument @DocHandle
	
		INSERT INTO [dbo].[t_wms_location_item]
			([item_location_id]
			,[item_master_id]
			,[location_id]
			,[is_active]
			,[create_date]
			,[create_by])
		SELECT NEWID()
			,item_master_id
			,location_id
			,'YES'
			,GETDATE()
			,@in_vchUserID
		FROM @tInsLocItem
	END
	
	COMMIT TRANSACTION;

	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;
		
	-------------------------------------------------
	-- Write process log
	-------------------------------------------------
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = 'Location Item Mapping',
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	END
		
END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans <> 0)
		ROLLBACK TRANSACTION;
 
	IF (ISNULL(@out_ErrorCode,'') = '' OR @out_ErrorCode = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	SET @v_dtProcessDateTime = GETDATE(); 
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @out_ErrorCode,
		@in_vchData2 = @out_ErrorMessage,
		@in_vchData3 = NULL,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
			
END CATCH	
END
 
GO
/****** Object:  StoredProcedure [dbo].[usp_move_serial_return]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_move_serial_return]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchSerialNumber		NVARCHAR(100),
	@in_vchDestLocation		NVARCHAR(50),
	@out_vchErrorCode		VARCHAR(50)   OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50)  OUTPUT
)
AS
BEGIN
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_move_serial_return]', -- The name that uniquely tags this object.
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtStartDateTime			DATETIME = GETDATE(),
			@v_dtProcessDateTime		DATETIME,
			@Round						INT,
			@v_vchApplicationName		NVARCHAR(100),
			@v_vchBeginTrans			BIT = 0,

			@v_vchWhID					NVARCHAR(50),
			@v_vchOutboundOrderNumber	NVARCHAR(50),
			@v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50),
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchMixItem				NVARCHAR(3),
			@v_vchMixLot				NVARCHAR(3),
			@v_vchMixOwner				NVARCHAR(3),
			@v_vchMixExpiryDate			NVARCHAR(3),
			@v_vchMixStatus				NVARCHAR(3),
			@v_vchLPNControl			NVARCHAR(5),

			@v_vchParentLPN				NVARCHAR(25) = NULL,
			@v_vchLPN					NVARCHAR(25) = NULL,
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_vchExpiryDate			NVARCHAR(50) = NULL,
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL,
			@v_vchDestItemStatus		NVARCHAR(40) = NULL,
			@v_vchDestInvStatusID		UNIQUEIDENTIFIER = NULL,

			--Item Number
			@v_vchLotControl			NVARCHAR(10) = NULL,
			@v_vchExpiryDateControl		NVARCHAR(10) = NULL,
			@v_vchSerialControl			NVARCHAR(10) = NULL,
			@v_vchAttribute1Control		NVARCHAR(10) = NULL,
			@v_vchAttribute2Control		NVARCHAR(10) = NULL,
			@v_vchAttribute3Control		NVARCHAR(10) = NULL,
			@v_vchAttribute4Control		NVARCHAR(10) = NULL,
			@v_vchAttribute5Control		NVARCHAR(10) = NULL,
			@v_vchItemUOMID				UNIQUEIDENTIFIER = NULL,
			@v_vchUOMPrompt				NVARCHAR(50) = NULL,

			--Inventory
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
			@v_vchInvAttributeID		UNIQUEIDENTIFIER = NULL,
			@v_fltAfterInvQuantity		FLOAT,
			@v_vchInvAllocateQty		FLOAT,
			@v_vchInvQuantity			FLOAT,
			@v_vchInvReceiveDate		DATE,
			@v_vchInvLocation			NVARCHAR(50) = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL,
			@v_vchOrderType				NVARCHAR(50) = NULL,
			@v_vchLocType				NVARCHAR(25) = NULL,
			@v_dtMFGDate				DATE = NULL

	BEGIN TRY
		
		SET @v_vchInvReceiveDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'

		---------------------------------------------------
		--Get date from outbound
		--Order type BO
		--14/09/2016 : ไม่ต้อง Where Order Type
		---------------------------------------------------
		SELECT @v_vchOutboundMasterID = outbound_order_master_id
			,@v_vchOutboundOrderNumber = outbound_order_number
			,@v_vchOrderType = order_type
			,@v_vchOwnerID = owner_id
			,@v_vchWhID = wh_id
			,@v_vchItemNumber = item_number
			,@v_vchWhItemMasterID = wh_item_master_id
			,@v_vchItemUOMID = item_uom_id
			,@v_vchUOMPrompt = uom_prompt
			,@v_vchParentLPN = parent_lpn
			,@v_vchLPN = lpn
			,@v_vchLotNumber = lot_number
			,@v_vchExpiryDate = expiry_date
			,@v_vchAttribute1 = attribute1
			,@v_vchAttribute2 = attribute2
			,@v_vchAttribute3 = attribute3
			,@v_vchAttribute4 = attribute4
			,@v_vchAttribute5 = attribute5
			,@v_vchLotControl =lot_control
			,@v_vchSerialControl = sn_control
			,@v_vchExpiryDateControl = expiry_date_control
			,@v_vchAttribute1Control = attribute1_control
			,@v_vchAttribute2Control = attribute2_control
			,@v_vchAttribute3Control = attribute3_control
			,@v_vchAttribute4Control = attribute4_control
			,@v_vchAttribute5Control = attribute5_control
		FROM v_wms_outbound_pick_or_pack
		WHERE wh_master_id = @in_vchWhMasterID
		AND serial_number = @in_vchSerialNumber
		
		IF (@v_vchOutboundMasterID is null)
			BEGIN
				SELECT @v_vchInventoryID = inventory_id
					,@v_vchAttributeGroupID = attribute_group_id
					,@v_vchWhID = wh_id
					,@v_vchOwnerID = owner_id
					,@v_vchItemNumber = item_number
					,@v_vchWhItemMasterID = wh_item_master_id
					,@v_vchUOMPrompt = uom_prompt
					,@v_vchInvLocation = location
					,@v_vchParentLPN = parent_lpn
					,@v_vchLPN = lpn
					,@v_vchInvStatus = inv_status
					,@v_vchLotNumber = lot_number
					,@v_vchExpiryDate = expiry_date
					,@v_vchAttribute1 = attribute1
					,@v_vchAttribute2 = attribute2
					,@v_vchAttribute3 = attribute3
					,@v_vchAttribute4 = attribute4
					,@v_vchAttribute5 = attribute5
					,@v_vchLotControl =lot_control
					,@v_vchSerialControl = sn_control
					,@v_vchExpiryDateControl = expiry_date_control
					,@v_vchAttribute1Control = attribute1_control
					,@v_vchAttribute2Control = attribute2_control
					,@v_vchAttribute3Control = attribute3_control
					,@v_vchAttribute4Control = attribute4_control
					,@v_vchAttribute5Control = attribute5_control
					,@v_vchInvReceiveDate = receive_date
					,@v_dtMFGDate = mfg_date
				FROM v_wms_inventory_data_by_serial_item
				WHERE wh_master_id = @in_vchWhMasterID
				AND serial_number = @in_vchSerialNumber
				AND loc_type = 'STORE'
				
				IF @v_vchInventoryID IS NULL
					BEGIN
						SET @out_vchErrorCode = 'NOT_FOUND_DATA';
						SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
		ELSE
			BEGIN
				SET @v_vchInventoryID = NULL
				SELECT @v_vchInventoryID = inventory_id 
					,@v_vchAttributeGroupID = attribute_group_id
					,@v_vchInvStatus = inv_status
					,@v_vchInvLocation = location
					,@v_vchLocType = loc_type
					,@v_vchInvReceiveDate = receive_date
					,@v_dtMFGDate = mfg_date
				FROM v_wms_inventory_data_by_serial_item
				WHERE wh_master_id = @in_vchWhMasterID
				AND serial_number = @in_vchSerialNumber
			END

		IF @v_vchInventoryID IS NOT NULL
			BEGIN
				--Check status Consignment and loc type = Store
				IF @v_vchInvStatus <> 'Consignment'
					BEGIN
						SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-INVALID-STATUS';
						SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchSerialNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
				IF @v_vchLocType <> 'STORE'
					BEGIN
						SET @out_vchErrorCode = 'INFO-LOCATION-INVALID-STATUS';
						SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchSerialNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--02/08/2016 : Change Status = Hold
		SET @v_vchDestItemStatus = 'Hold'
		SELECT @v_vchDestInvStatusID = inventory_status_id FROM t_wms_inventory_status where inv_status = @v_vchDestItemStatus AND is_active = 'YES'
		IF  @v_vchDestInvStatusID IS NULL
			BEGIN
				SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchDestItemStatus,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		---------------------------------------------
		--Get Owner Code
		---------------------------------------------
		SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @v_vchOwnerID AND is_active = 'YES'	

		---------------------------------------------------
		--Check Destination Location 
		---------------------------------------------------
		SELECT @v_vchLocationID = loc.location_id
			,@v_vchMixItem = mix_items
			,@v_vchMixLot = mix_lot
			,@v_vchMixExpiryDate = mix_expiry_dates
			,@v_vchMixOwner = mix_owners
			,@v_vchLPNControl = lpn_controlled 
			,@v_vchMixStatus = mix_status
		FROM t_wms_location loc
		LEFT JOIN t_wms_zone_location zoneLoc ON loc.location_id = zoneLoc.location_id
		LEFT JOIN t_wms_zone z on zoneLoc.zone_id = z.zone_id
		WHERE loc.wh_master_id = @in_vchWhMasterID
		AND z.zone = 'QUAR'
		AND loc.is_active = 'YES'
		AND loc.location = @in_vchDestLocation

		IF @v_vchLocationID IS NULL
			BEGIN
				SET @out_vchErrorCode = 'LOCATION_NOT_FOUND_IN_ZONE_QUAR';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END 
	
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;
		---------------------------------------------------------
		--Manage Source Inventory : Inventory
		---------------------------------------------------------
		IF @v_vchInventoryID <> ''
			BEGIN
				--------------------------------------------
				--Manage source inventory
				--------------------------------------------
				UPDATE t_wms_inventory SET quantity = ROUND(quantity - 1,@Round)
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchAttributeGroupID

				IF (@v_vchSerialControl = 'FULL')
					BEGIN
						UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - 1,@Round) 
						WHERE inventory_id = @v_vchInventoryID 
						AND attribute_group_id = @v_vchAttributeGroupID 
						AND attribute_value = @in_vchSerialNumber												
					END

				--Inventory attribute
				IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - 1,@Round) 
						WHERE inventory_id = @v_vchInventoryID 
						AND attribute_group_id = @v_vchAttributeGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
					END

				DELETE FROM t_wms_inventory WHERE quantity <= 0 --and quantity_allocated = 0
				DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 --and quantity_allocated = 0
			END

		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
									,@in_vchWhMasterID			= @in_vchWhMasterID
									,@in_vchWhID				= @v_vchWhID
									,@in_vchOwnerID				= @v_vchOwnerID
									,@in_vchInventoryType		= 'INVENTORY'
									,@in_vchLocationID			= @v_vchLocationID
									,@in_vchParentLPN			= null
									,@in_vchLPN					= @v_vchLPN
									,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
									,@in_vchItemMasterID		= @v_vchItemMasterID
									,@in_vchItemNumber			= @v_vchItemNumber
									,@in_fltQuantity			= 1
									,@in_fltQtyAllocate			= 0
									,@in_fltQtyIncoming			= 0
									,@in_vchPrimaryItemUomID	= @v_vchItemUOMID
									,@in_vchInvStatusID			= @v_vchDestInvStatusID
									,@in_vchLotNumber			= @v_vchLotNumber
									,@in_vchExpiryDate			= @v_vchExpiryDate
									,@in_vchSerialNumber		= @in_vchSerialNumber
									,@in_vchAttribute1			= @v_vchAttribute1
									,@in_vchAttribute2			= @v_vchAttribute2
									,@in_vchAttribute3			= @v_vchAttribute3
									,@in_vchAttribute4			= @v_vchAttribute4
									,@in_vchAttribute5			= @v_vchAttribute5
									,@in_dReceiveDate			= @v_vchInvReceiveDate
									,@in_dtMFGDate				= @v_dtMFGDate
									,@in_vchDeviceID			= @in_vchDeviceID
									,@in_vchUserID				= @in_vchUserID
									,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
									,@out_ErrorCode				= @out_vchErrorCode OUTPUT
									,@out_ErrorMessage			= @out_vchErrorMsg OUTPUT

		IF (@out_vchErrorCode <> '0')
			GOTO WRITE_PROC; 

		---------------------------------------------------		
		--Write Tran Log INV_MOVE TO Staging
		---------------------------------------------------		
		INSERT INTO t_com_tran_log
			( app_id
			, tran_type
			, sub_tran_type
			, [app_name]
			, [description]
			, start_tran_datetime
			, end_tran_datetime
			, warehouse
			, to_warehouse
			, location
			, to_location
			, [owner]
			, to_owner
			, item_number
			, quantity
			, quantity_uom
			, after_quantity
			, after_quantity_uom
			, lot_number
			, after_lot_number
			, [expiry_date]
			, after_expiry_date
			, serial_number
			, [attribute1]
			, [after_attribute1]
			, [attribute2]
			, [after_attribute2]
			, [attribute3]
			, [after_attribute3]
			, [attribute4]
			, [after_attribute4]
			, [attribute5]
			, [after_attribute5]
			, [user_id] 
			, parent_lpn
			, after_parent_lpn
			, lpn
			, after_lpn
			, [status]
			, after_status 
			, order_number
			, line_number
			, device
			, create_by
		)
		VALUES
		(     @in_vchApplicationID
			, 'INV_RETURN'
			, 'INV_RETURN_SERIAL'
			, @v_vchApplicationName
			, 'Return Serial'
			, @v_dtStartDateTime
			, DATEADD(millisecond,2,GETDATE())
			, @v_vchWhID
			, @v_vchWhID
			, @v_vchInvLocation
			, @in_vchDestLocation
			, @v_vchOwnerCode
			, @v_vchOwnerCode
			, @v_vchItemNumber
			, 1
			, @v_vchUOMPrompt
			, ISNULL(@v_vchInvQuantity,0) + 1
			, @v_vchUOMPrompt
			, @v_vchLotNumber
			, @v_vchLotNumber
			, (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN NULL ELSE @v_vchExpiryDate END)
			, (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN NULL ELSE @v_vchExpiryDate END)
			, @in_vchSerialNumber
			, @v_vchAttribute1
			, @v_vchAttribute1
			, @v_vchAttribute2
			, @v_vchAttribute2
			, @v_vchAttribute3
			, @v_vchAttribute3
			, @v_vchAttribute4
			, @v_vchAttribute4
			, @v_vchAttribute5
			, @v_vchAttribute5
			, @in_vchUserID 
			, @v_vchParentLPN
			, @v_vchParentLPN
			, @v_vchLPN
			, @v_vchLPN
			, @v_vchInvStatus
			, @v_vchDestItemStatus 
			, @v_vchOutboundOrderNumber
			, NULL
			, @in_vchDeviceID
			, @in_vchUserID
		)

		DELETE FROM t_wms_inventory WHERE quantity <= 0
		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0

		COMMIT TRANSACTION;
		SET @out_vchErrorCode = '0';
		SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;

		-----------------------------------------------------------
		-- Write process log
		-----------------------------------------------------------
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
				SET @v_dtProcessDateTime = GETDATE();	
				SET @v_vchProcessData1 = @out_vchErrorMsg;
				SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWhID,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @v_vchProcessData3,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_vchErrorCode,
					@in_vchMessage = @out_vchErrorMsg
				RETURN;
		END	
	END TRY
	BEGIN CATCH
		IF(@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;
		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMsg = ERROR_MESSAGE();
	END CATCH	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_boxnumber_picking]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_boxnumber_picking]
	-- Add the parameters for the stored procedure here
	@in_vchBoxNumber	        VARCHAR(40),
	@in_vchLocalID				VARCHAR(40),
	@in_vchWareHouseMasterID    VARCHAR(40),
	@out_ErrorMessage			VARCHAR(max) output
AS
BEGIN
	DECLARE @v_nCount		int = null, 
			@out_ErroCode	VARCHAR(100)

	SELECT @v_nCount = count(CODE)
	FROM Picking.v_wms_combo_box_number
	WHERE CODE = @in_vchBoxNumber
	AND wh_master_id = @in_vchWareHouseMasterID

	IF (@v_nCount = 0)
		BEGIN
			SET @out_ErroCode = 'INFO-BOXNUMBER-NOT-EXIST'
		END
	Else
		BEGIN
			SET @out_ErroCode = ''
		END
		SELECT @out_ErrorMessage = dbo.fn_get_resource(@in_vchLocalID,@out_ErroCode)
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_cancel_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_cancel_order]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchCancelRemark			NVARCHAR(200),
	@out_ErrorCode				NVARCHAR(50) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON; 
	Declare @c_vchObjName			NVARCHAR(30) = '[usp_outbound_cancel_order]',
		@v_dtProcessDateTime		DATETIME,
		@Round						INT,
		@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchPickType				NVARCHAR(15), 
		@v_vchOrderStatus			NVARCHAR(10), 
		@v_vchBeginTrans			BIT = 0 
			
	BEGIN TRY
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		IF (@v_vchWhMasterID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END
			 
		SELECT TOP 1 @v_vchOutboundOrderNumber = outbound_order_number
			,@v_vchOrderStatus = order_status 
			,@v_vchPickType = pick_type
		FROM t_wms_outbound_master 
		WHERE outbound_order_master_id = @in_vchOutboundMasterID 
		IF(@v_vchOrderStatus NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_STATUS_FOR_CANCEL' AND is_active = 'YES'))
			BEGIN
				set @out_ErrorCode = 'CANNOT_CANCEL_ORDER';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROCESSLOG;
			End
	
	Begin Transaction
	Set @v_vchBeginTrans = 1;

		IF @v_vchPickType = 'SYSTEM' AND @v_vchOrderStatus <> 'OPEN'
			BEGIN
				BEGIN
					DECLARE @v_vchOutboundPickMasterID UNIQUEIDENTIFIER = NULL
					SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @in_vchOutboundMasterID
					IF @v_vchOutboundPickMasterID IS NOT NULL
						BEGIN 
							DECLARE @v_vchUnLocationID		  UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchUnParentLPN		  NVARCHAR(25) = NULL
							DECLARE @v_vchUnLPN				  NVARCHAR(25) = NULL
							DECLARE @v_vchUnWhItemMasterID	  UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchUnLotNumber		  NVARCHAR(50) = NULL
							DECLARE @v_vchUnExpiryDate		  NVARCHAR(50) = NULL
							DECLARE @v_vchUnSerialNumber	  NVARCHAR(50) = NULL
							DECLARE @v_vchUnAttribute1		  NVARCHAR(100) = NULL
							DECLARE @v_vchUnAttribute2		  NVARCHAR(100) = NULL
							DECLARE @v_vchUnAttribute3		  NVARCHAR(100) = NULL
							DECLARE @v_vchUnAttribute4		  NVARCHAR(100) = NULL
							DECLARE @v_vchUnAttribute5		  NVARCHAR(100) = NULL
							DECLARE @v_fltUnRemainPickQTY	  FLOAT = NULL
							DECLARE @v_dtUnReceiveDate		  DATE = NULL
							DECLARE @v_vchUnDefaultItemStatus NVARCHAR(50) = NULL
							DECLARE OutboundUnAllocateCURSOR CURSOR FOR
								SELECT pickDT.location_id
									,pickDT.parent_lpn
									,pickDT.lpn
									,pickDT.wh_item_master_id
									,pickDT.lot_number
									,pickDT.expiry_date
									,pickDT.serial_number
									,pickDT.attribute1
									,pickDT.attribute2
									,pickDT.attribute3
									,pickDT.attribute4
									,pickDT.attribute5
									,ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) AS quantity_remain_pick
									,pickDT.receive_date
									,obDT.default_item_status
								FROM t_wms_outbound_pick_master pickMS
								INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
								INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
								WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID 
								AND ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) > 0 
								AND pickDT.is_override = 'NO'	
							OPEN OutboundUnAllocateCURSOR;
							FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
																	,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
								WHILE @@FETCH_STATUS = 0
									BEGIN
										-- un allocate inventory data
										EXEC [usp_inventory_un_allocate]  @in_vchApplicationID		= @in_vchApplicationID	
																		, @in_vchWarehouseMasterID	= @v_vchWhMasterID	
																		, @in_vchLocationID			= @v_vchUnLocationID
																		, @in_vchParentLPN			= @v_vchUnParentLPN	
																		, @in_vchLPN				= @v_vchUnLPN
																		, @in_vchWhItemMasterID		= @v_vchUnWhItemMasterID
																		, @in_fltQuantity			= @v_fltUnRemainPickQTY	
																		, @in_vchSerialNumber		= @v_vchUnSerialNumber	
																		, @in_vchLotNumber			= @v_vchUnLotNumber	
																		, @in_vchExpiryDate			= @v_vchUnExpiryDate
																		, @in_vchAttribute1			= @v_vchUnAttribute1
																		, @in_vchAttribute2			= @v_vchUnAttribute2
																		, @in_vchAttribute3			= @v_vchUnAttribute3
																		, @in_vchAttribute4			= @v_vchUnAttribute4
																		, @in_vchAttribute5			= @v_vchUnAttribute5
																		, @in_dtReceiveDate			= @v_dtUnReceiveDate
																		, @in_vchDefaultItemStatus	= @v_vchUnDefaultItemStatus
																		, @in_vchUserID				= @in_vchUserID	
																		, @out_ErrorCode			= @out_ErrorCode	OUTPUT
																		, @out_ErrorMessage			= @out_ErrorMessage OUTPUT
										IF (@out_ErrorCode <> '0')
											BEGIN 
												GOTO WRITE_PROCESSLOG;
											END 
										FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
																	,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
									END
							CLOSE OutboundUnAllocateCURSOR;
							DEALLOCATE OutboundUnAllocateCURSOR;
					
							-- delete row not pick
							DELETE FROM t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) = 0
							-- update row pick.set quantity plan = quantity pick
							UPDATE t_wms_outbound_pick_detail SET quantity_plan = quantity_pick WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) > 0
						END
				END
			END

		UPDATE t_wms_outbound_master SET order_status = 'CANCEL', cancel_by = @in_vchUserID, cancel_date = GETDATE(), cancel_remark = @in_vchCancelRemark
		WHERE outbound_order_master_id = @in_vchOutboundMasterID
		
		COMMIT TRANSACTION; 
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CANCEL_ORDER_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
		RETURN;
		-------------------------------------------------------------------------------------------------
		--						WRITE PROCESS LOG
		WRITE_PROCESSLOG:
		-------------------------------------------------------------------------------------------------

		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			Begin
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			End
			
		SET @v_dtProcessDateTime = getdate();
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = @v_vchPickType,
			@in_vchData3 = @v_vchOrderStatus,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
		-------------------------------------------------------------------------------------------------
	End Try
	Begin Catch
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			Begin
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			End
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();		
		SET @v_dtProcessDateTime = getdate();
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = @v_vchPickType,
			@in_vchData3 = @v_vchOrderStatus,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	End Catch
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_cancel_order_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-01-22
-- Description:	Cancel order by load id
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_cancel_order_by_group]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(10),
	@in_vchLoadID				NVARCHAR(50),
	@in_vchCancelRemark			NVARCHAR(200),
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;
	
	Declare
		@v_dtProcessDateTime		DATETIME,
		@c_vchObjName				NVARCHAR(20) = 'usp_outbound_cancel_order_by_group',
		@v_vchWarehouseMasterID		VARCHAR(40),
		@v_vchData1					NVARCHAR(1000),
		@v_vchData2					NVARCHAR(1000),
		@v_vchOutboundOrderMasterID	VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOrderStatus			NVARCHAR(10),
		
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(50),
		@v_vchWarehouseItemMasterID	NVARCHAR(40),
		@v_vchItemNumber			NVARCHAR(50),
		@v_fltQtyPickPlan			FLOAT,
		@v_vchLocationMasterID		VARCHAR(40),
		@v_vchBeginTrans			BIT = 0,
		@v_vchSerialControl			NVARCHAR(5)
			
	Begin Try
		
		select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		If (ISNULL(@v_vchWarehouseMasterID,'') = '')
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			End
			
		--select @v_vchOutboundOrderMasterID = outbound_order_master_id,@v_vchOrderStatus = order_status from t_wms_outbound_master where load_id = @in_vchLoadID
		
		If Exists(Select order_status from t_wms_outbound_master where load_id = @in_vchLoadID and order_status not in('RELEASE','OPEN'))
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_CANCEL_LOAD_ID',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROCESSLOG;
			End
			
		declare cursorOutboundUnAllocate scroll cursor for
			select parent_lpn,lpn,lot_number,[expiry_date],item_number,(sum(quantity_plan - quantity_pick) *
				(select top 1 conversion_factor from t_wms_item_uom where t_wms_item_uom.item_uom_id = v_wms_outbound_pick_detail.item_uom_id))
				,serial_number,location_id,wh_item_master_id,sn_control--,outbound_order_master_id,order_status,outbound_pick_master_id
			from v_wms_outbound_pick_detail
			where wh_id = @in_vchWarehouse and load_id = @in_vchLoadID
			group by parent_lpn,lpn,lot_number,[expiry_date],item_number,serial_number,location_id,
			wh_item_master_id,sn_control,v_wms_outbound_pick_detail.item_uom_id
		
		Open cursorOutboundUnAllocate;
		fetch from cursorOutboundUnAllocate into @v_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchItemNumber,@v_fltQtyPickPlan,@v_vchSerialNumber,@v_vchLocationMasterID,@v_vchWarehouseItemMasterID,@v_vchSerialControl--,@v_vchOutboundOrderMasterID,@v_vchOrderStatus,@v_vchOutboundPickMasterID
		
		Begin Transaction
		Set @v_vchBeginTrans = 1;
		
		Delete from t_wms_outbound_pick_detail where outbound_pick_master_id in (select outbound_pick_master_id from t_wms_outbound_pick_master where pick_list_number = @in_vchLoadID) and isnull(quantity_pick,0) = 0
		Delete from t_wms_outbound_pick_master where pick_list_number = @in_vchLoadID
		update t_wms_outbound_master set order_status = 'OPEN',load_id = null,dock_door_id = null where wh_master_id = @v_vchWarehouseMasterID and load_id = @in_vchLoadID

		While @@FETCH_STATUS = 0
			Begin
			
				-- un allocate inventory data
				exec [usp_inventory_un_allocate]
					@in_vchApplicationID		= @in_vchApplicationID,
					@in_vchWarehouseMasterID	= @v_vchWarehouseMasterID,
					@in_vchLocationID			= @v_vchLocationMasterID,
					@in_vchParentLPN			= @v_vchParentLPN,
					@in_vchLPN					= @v_vchLPN,
					@in_vchItemNumber			= @v_vchItemNumber,
					@in_vchWHItemMasterID		= @v_vchWarehouseItemMasterID,
					@in_fltQuantity				= @v_fltQtyPickPlan,
					@in_vchSerialValue			= @v_vchSerialNumber,
					@in_vchLotValue				= @v_vchLotNumber,
					@in_vchExpiryDateValue		= @v_vchExpiryDate,
					@in_vchSerialControl		= @v_vchSerialControl,	
					@in_vchUserID				= @in_vchUserID,
					@out_ErrorCode				= @out_ErrorCode output,
					@out_ErrorMessage			= @out_ErrorMessage output
				If (@out_ErrorCode <> '0')
					Begin GOTO WRITE_PROCESSLOG; End
				
				fetch next from cursorOutboundUnAllocate into @v_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchItemNumber,@v_fltQtyPickPlan,@v_vchSerialNumber,@v_vchLocationMasterID,@v_vchWarehouseItemMasterID,@v_vchSerialControl--,@v_vchOutboundOrderMasterID,@v_vchOrderStatus,@v_vchOutboundPickMasterID
			End

		Close cursorOutboundUnAllocate;
		Deallocate cursorOutboundUnAllocate;
		
		Commit Transaction;
		
		set @out_ErrorCode = '0';
		select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CANCEL_ORDER_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
		-------------------------------------------------------------------------------------------------
		--						WRITE PROCESS LOG
		WRITE_PROCESSLOG:
		-------------------------------------------------------------------------------------------------

		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			Rollback transaction;
		
		IF CURSOR_STATUS('global','cursorOutboundUnAllocate') >= -1
			Begin
				Close cursorOutboundUnAllocate;
				Deallocate cursorOutboundUnAllocate;
			End
			
		SET @v_dtProcessDateTime = getdate();
		set @v_vchData1 = @out_ErrorMessage;
		set @v_vchData2 = 'Outbound order [' + @in_vchLoadID + ']';

		exec usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		Return;
		-------------------------------------------------------------------------------------------------
	End Try
	Begin Catch
	
		SET @v_dtProcessDateTime = getdate();
		set @v_vchData2 = 'Outbound order [' + @in_vchLoadID + ']';
		
		IF CURSOR_STATUS('global','cursorOutboundUnAllocate') >= -1
			Begin
				Close cursorOutboundUnAllocate;
				Deallocate cursorOutboundUnAllocate;
			End
						
		exec usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	End Catch
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_check_picklist_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_check_picklist_item]
	@in_vchApplicationID	NVARCHAR(40),
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchUserID			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
SET NOCOUNT ON; 

BEGIN TRY
---------------------------------------------
-- Begin Store procedure
---------------------------------------------
	DECLARE @Round INT
	DECLARE @v_vchRuleAllowExpired VARCHAR(10) = 'NO'
	SELECT TOP 1 @v_vchRuleAllowExpired = value FROM t_wms_rule WHERE rule_code = 'ALLOW_ALLOCATE_ITEM_HAS_EXPIRED' and is_active = 'YES'
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	IF NOT EXISTS (SELECT outbound_order_detail_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(lpn,'') <> '')
		BEGIN
			;With tOutbound AS
			(
				SELECT ms.outbound_order_master_id
					,ms.wh_master_id
					,ms.owner_id 
					,dt.wh_item_master_id 
					,dt.item_master_id
					,dt.default_item_status
					,dt.item_uom_id
					,ISNULL(dt.lot_number ,'') AS lot_number
					,ISNULL(dt.expiry_date,'') AS expiry_date
					,ISNULL(dt.attribute1 ,'') AS attribute1
					,ISNULL(dt.attribute2 ,'') AS attribute2
					,ISNULL(dt.attribute3 ,'') AS attribute3
					,ISNULL(dt.attribute4 ,'') AS attribute4
					,ISNULL(dt.attribute5 ,'') AS attribute5 
      				,SUM(dt.quantity_order - ISNULL(pickDT.quantity_plan,0)) AS planqty 
				FROM t_wms_outbound_master ms 
				INNER JOIN t_wms_outbound_detail dt ON ms.outbound_order_master_id = dt.outbound_order_master_id 
				LEFT JOIN (SELECT outbound_order_detail_id
								,SUM(quantity_plan) AS quantity_plan
							FROM t_wms_outbound_pick_detail
							WHERE is_override = 'NO'
							GROUP BY outbound_order_detail_id
							) pickDT ON dt.outbound_order_detail_id = pickdT.outbound_order_detail_id
				WHERE ms.outbound_order_master_id = @in_vchOutboundMasterID
				GROUP BY ms.outbound_order_master_id,ms.wh_master_id,ms.owner_id,dt.wh_item_master_id,dt.item_master_id,dt.default_item_status,dt.item_uom_id,ISNULL(dt.lot_number ,''),ISNULL(dt.expiry_date,'')
				,ISNULL(dt.attribute1 ,''),ISNULL(dt.attribute2 ,''),ISNULL(dt.attribute3 ,''),ISNULL(dt.attribute4 ,''),ISNULL(dt.attribute5 ,'')
			)
			, tInventory AS
			(	SELECT inv.wh_master_id
					,inv.owner_id
					,inv.wh_item_master_id
					,invStatus.inv_status
					,ISNULL(inv.lot_number,'')	AS lot_number
					,ISNULL(inv.expiry_date,'')	AS expiry_date
					,ISNULL(inv.attribute1,'')  AS attribute1
					,ISNULL(inv.attribute2,'')  AS attribute2
					,ISNULL(inv.attribute3,'')  AS attribute3
					,ISNULL(inv.attribute4,'')  AS attribute4
					,ISNULL(inv.attribute5,'')  AS attribute5
					,loc.location_id
					,loc.location
					,SUM(inv.quantity - ISNULL(inv.quantity_allocated,0)) AS quantity
				FROM v_wms_inventory_data_by_id inv 
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
				WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES') 
				AND (CASE WHEN (ISNULL(inv.expiry_date,'') = '') OR (ISNULL(inv.expiry_date,'') <> '' AND @v_vchRuleAllowExpired = 'YES' ) THEN '1' ELSE ISNULL(inv.expiry_date,'') END) 
						> (CASE WHEN (ISNULL(inv.expiry_date,'') = '')  OR (ISNULL(inv.expiry_date,'') <> '' AND @v_vchRuleAllowExpired = 'YES' ) THEN '0' ELSE CONVERT(VARCHAR(8),GETDATE(),112) END)
				GROUP BY inv.wh_master_id,inv.owner_id,inv.wh_item_master_id,invStatus.inv_status,ISNULL(inv.lot_number,''),ISNULL(inv.expiry_date,''),ISNULL(inv.attribute1,''),ISNULL(inv.attribute2,''),ISNULL(inv.attribute3,''),ISNULL(inv.attribute4,''),ISNULL(inv.attribute5,''),loc.location_id,loc.location
			)
			SELECT item.item_number
				,item.description AS item_description
				,item.grade
				,item.price
				,uom.uom
				,ROUND(t.planqty,@Round) AS planqty
				,ROUND(t.quantity,@Round) as quantity
				,t.inventory_status
			FROM (SELECT tOutbound.wh_item_master_id
						,tOutbound.item_master_id
						,tOutbound.item_uom_id
						,ISNULL(tOutbound.default_item_status,'') AS inventory_status 
						,tOutbound.planqty
						,SUM(ISNULL(tInv.quantity,0)) AS quantity 
					FROM tOutbound
					LEFT JOIN tInventory tInv ON tOutbound.wh_master_id = tInv.wh_master_id
											 AND tOutbound.owner_id = tInv.owner_id
											 AND tOutbound.wh_item_master_id = tInv.wh_item_master_id
											 AND tOutbound.default_item_status = tInv.inv_status
											 AND (ISNULL(tInv.lot_number,'') = ISNULL(tOutbound.lot_number,'') OR ISNULL(tOutbound.lot_number,'') = '') 
											 AND (ISNULL(tInv.expiry_date,'') = ISNULL(tOutbound.expiry_date,'') OR ISNULL(tOutbound.expiry_date,'') = '') 
											 AND (ISNULL(tInv.attribute1,'') = ISNULL(tOutbound.attribute1,'') OR ISNULL(tOutbound.attribute1,'') = '') 
											 AND (ISNULL(tInv.attribute2,'') = ISNULL(tOutbound.attribute2,'') OR ISNULL(tOutbound.attribute2,'') = '') 
											 AND (ISNULL(tInv.attribute3,'') = ISNULL(tOutbound.attribute3,'') OR ISNULL(tOutbound.attribute3,'') = '') 
											 AND (ISNULL(tInv.attribute4,'') = ISNULL(tOutbound.attribute4,'') OR ISNULL(tOutbound.attribute4,'') = '') 
											 AND (ISNULL(tInv.attribute5,'') = ISNULL(tOutbound.attribute5,'') OR ISNULL(tOutbound.attribute5,'') = '')  
					GROUP BY tOutbound.wh_item_master_id,tOutbound.item_master_id,tOutbound.item_uom_id,ISNULL(tOutbound.default_item_status,'') ,tOutbound.planqty
					) t
				INNER JOIN t_wms_item item ON t.item_master_id = item.item_master_id
				INNER JOIN t_wms_item_uom uom ON t.item_uom_id = uom.item_uom_id
				WHERE ROUND(ISNULL(t.planqty,0),@Round) > ROUND(ISNULL(t.quantity,0),@Round)

			IF (@@ROWCOUNT > 0)
				SET @out_ErrorCode = '999';
			ELSE
				SET @out_ErrorCode = '0';
		END
	ELSE
		BEGIN
			;With tOutbound AS
			(
				SELECT ms.outbound_order_master_id
					,ms.wh_master_id
					,ms.owner_id 
					,dt.wh_item_master_id 
					,dt.item_master_id
					,dt.default_item_status
					,dt.item_uom_id
					,ISNULL(dt.lpn ,'') AS lpn
					,ISNULL(dt.lot_number ,'') AS lot_number
					,ISNULL(dt.expiry_date,'') AS expiry_date
					,ISNULL(dt.attribute1 ,'') AS attribute1
					,ISNULL(dt.attribute2 ,'') AS attribute2
					,ISNULL(dt.attribute3 ,'') AS attribute3
					,ISNULL(dt.attribute4 ,'') AS attribute4
					,ISNULL(dt.attribute5 ,'') AS attribute5 
      				,SUM(dt.quantity_order - ISNULL(pickDT.quantity_plan,0)) AS planqty 
				FROM t_wms_outbound_master ms 
				INNER JOIN t_wms_outbound_detail dt ON ms.outbound_order_master_id = dt.outbound_order_master_id  
				LEFT JOIN (SELECT outbound_order_detail_id
								,SUM(quantity_plan) AS quantity_plan
							FROM t_wms_outbound_pick_detail
							WHERE is_override = 'NO'
							GROUP BY outbound_order_detail_id
							) pickDT ON dt.outbound_order_detail_id = pickdT.outbound_order_detail_id
				WHERE ms.outbound_order_master_id = @in_vchOutboundMasterID
				GROUP BY ms.outbound_order_master_id,ms.wh_master_id,ms.owner_id,dt.wh_item_master_id,dt.item_master_id,dt.default_item_status,dt.item_uom_id,ISNULL(dt.lpn ,''),ISNULL(dt.lot_number ,''),ISNULL(dt.expiry_date,'')
				,ISNULL(dt.attribute1 ,''),ISNULL(dt.attribute2 ,''),ISNULL(dt.attribute3 ,''),ISNULL(dt.attribute4 ,''),ISNULL(dt.attribute5 ,'')
			)
			, tInventory AS
			(	SELECT inv.wh_master_id
					,inv.owner_id
					,inv.wh_item_master_id
					,invStatus.inv_status
					,ISNULL(inv.lpn,'')			as lpn
					,ISNULL(inv.lot_number,'')	AS lot_number
					,ISNULL(inv.expiry_date,'')	AS expiry_date
					,ISNULL(inv.attribute1,'')  AS attribute1
					,ISNULL(inv.attribute2,'')  AS attribute2
					,ISNULL(inv.attribute3,'')  AS attribute3
					,ISNULL(inv.attribute4,'')  AS attribute4
					,ISNULL(inv.attribute5,'')  AS attribute5
					,loc.location_id
					,loc.location
					,SUM(inv.quantity - ISNULL(inv.quantity_allocated,0)) AS quantity
				FROM v_wms_inventory_data_by_id inv 
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
				WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES') 
				AND (CASE WHEN (ISNULL(inv.expiry_date,'') = '') OR (ISNULL(inv.expiry_date,'') <> '' AND @v_vchRuleAllowExpired = 'YES' ) THEN '1' ELSE ISNULL(inv.expiry_date,'') END) 
						> (CASE WHEN (ISNULL(inv.expiry_date,'') = '')  OR (ISNULL(inv.expiry_date,'') <> '' AND @v_vchRuleAllowExpired = 'YES' ) THEN '0' ELSE CONVERT(VARCHAR(8),GETDATE(),112) END)
				GROUP BY inv.wh_master_id,inv.owner_id,inv.wh_item_master_id,invStatus.inv_status,ISNULL(inv.lpn,''),ISNULL(inv.lot_number,''),ISNULL(inv.expiry_date,''),ISNULL(inv.attribute1,''),ISNULL(inv.attribute2,''),ISNULL(inv.attribute3,''),ISNULL(inv.attribute4,''),ISNULL(inv.attribute5,''),loc.location_id,loc.location
			)
			SELECT item.item_number
				,item.description AS item_description
				,item.grade
				,item.price
				,uom.uom
				,ROUND(t.planqty,@Round) as planqty
				,ROUND(t.quantity,@Round) as quantity
				,t.inventory_status
			FROM (SELECT tOutbound.wh_item_master_id
					,tOutbound.item_master_id
					,tOutbound.item_uom_id
					,ISNULL(tOutbound.default_item_status,'') AS inventory_status 
					,tOutbound.planqty
					,SUM(ISNULL(tInv.quantity,0)) AS quantity 
				  FROM tOutbound
				  LEFT JOIN tInventory tInv ON tOutbound.wh_master_id = tInv.wh_master_id
				  						AND tOutbound.owner_id = tInv.owner_id
				  						AND tOutbound.wh_item_master_id = tInv.wh_item_master_id
				  						AND tOutbound.default_item_status = tInv.inv_status
				  						AND (ISNULL(tInv.lot_number,'') = ISNULL(tOutbound.lot_number,'') OR ISNULL(tOutbound.lot_number,'') = '') 
				  						AND (ISNULL(tInv.expiry_date,'') = ISNULL(tOutbound.expiry_date,'') OR ISNULL(tOutbound.expiry_date,'') = '') 
				  						AND (ISNULL(tInv.attribute1,'') = ISNULL(tOutbound.attribute1,'') OR ISNULL(tOutbound.attribute1,'') = '') 
				  						AND (ISNULL(tInv.attribute2,'') = ISNULL(tOutbound.attribute2,'') OR ISNULL(tOutbound.attribute2,'') = '') 
				  						AND (ISNULL(tInv.attribute3,'') = ISNULL(tOutbound.attribute3,'') OR ISNULL(tOutbound.attribute3,'') = '') 
				  						AND (ISNULL(tInv.attribute4,'') = ISNULL(tOutbound.attribute4,'') OR ISNULL(tOutbound.attribute4,'') = '') 
				  						AND (ISNULL(tInv.attribute5,'') = ISNULL(tOutbound.attribute5,'') OR ISNULL(tOutbound.attribute5,'') = '') 
				  						AND (ISNULL(tInv.lpn,'') = ISNULL(tOutbound.lpn,'') OR ISNULL(tOutbound.lpn,'') = '') 
				  GROUP BY tOutbound.wh_item_master_id,tOutbound.item_master_id,tOutbound.item_uom_id,ISNULL(tOutbound.default_item_status,''),tOutbound.planqty
				) t
			INNER JOIN t_wms_item item ON t.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON t.item_uom_id = uom.item_uom_id
			WHERE ROUND(ISNULL(t.planqty,0),@Round) > ROUND(ISNULL(t.quantity,0),@Round)
			
			IF (@@ROWCOUNT > 0)
				SET @out_ErrorCode = '999';
			ELSE
				SET  @out_ErrorCode = '0';
		END
END TRY
BEGIN CATCH
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_check_picklist_item_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_check_picklist_item_by_group]
	@in_vchApplicationID	NVARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchLoadID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON; 
BEGIN TRY 
---------------------------------------------
-- Begin Store procedure
---------------------------------------------
		IF NOT EXISTS (SELECT outbound_order_detail_id FROM t_wms_outbound_detail obDT
						INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
						WHERE obMS.load_id = @in_vchLoadID AND ISNULL(obDT.lpn,'') <> '')
		BEGIN
			;With tOutbound AS
			(
				SELECT ms.wh_master_id
					,ms.owner_id 
					,dt.wh_item_master_id 
					,dt.item_master_id
					,dt.default_item_status
					,dt.item_uom_id
					,ISNULL(dt.lot_number ,'') AS lot_number
					,ISNULL(dt.expiry_date,'') AS expiry_date
					,ISNULL(dt.attribute1 ,'') AS attribute1
					,ISNULL(dt.attribute2 ,'') AS attribute2
					,ISNULL(dt.attribute3 ,'') AS attribute3
					,ISNULL(dt.attribute4 ,'') AS attribute4
					,ISNULL(dt.attribute5 ,'') AS attribute5
      				,SUM(dt.quantity_order - ISNULL(pickDT.quantity_plan,0)) AS planqty 
				FROM t_wms_outbound_master ms 
				INNER JOIN t_wms_outbound_detail dt ON ms.outbound_order_master_id = dt.outbound_order_master_id
				LEFT JOIN (SELECT outbound_order_detail_id
								,SUM(quantity_plan) AS quantity_plan
							FROM t_wms_outbound_pick_detail
							WHERE is_override = 'NO'
							GROUP BY outbound_order_detail_id
							) pickDT ON dt.outbound_order_detail_id = pickdT.outbound_order_detail_id 
				WHERE ms.load_id = @in_vchLoadID
				AND ms.wh_master_id = @in_vchWhMasterID
				GROUP BY ms.wh_master_id,ms.owner_id,dt.wh_item_master_id,dt.item_master_id,dt.default_item_status,dt.item_uom_id,ISNULL(dt.lot_number ,''),ISNULL(dt.expiry_date,''),ISNULL(dt.attribute1 ,''),ISNULL(dt.attribute2 ,''),ISNULL(dt.attribute3 ,''),ISNULL(dt.attribute4 ,''),ISNULL(dt.attribute5 ,'')		
			)
			, tInventory AS
			(	SELECT inv.wh_master_id
					,inv.owner_id
					,inv.wh_item_master_id
					,invStatus.inv_status
					,ISNULL(inv.lot_number,'')	AS lot_number
					,ISNULL(inv.expiry_date,'')	AS expiry_date
					,ISNULL(inv.attribute1,'')  AS attribute1
					,ISNULL(inv.attribute2,'')  AS attribute2
					,ISNULL(inv.attribute3,'')  AS attribute3
					,ISNULL(inv.attribute4,'')  AS attribute4
					,ISNULL(inv.attribute5,'')  AS attribute5
					,SUM(inv.quantity - ISNULL(inv.quantity_allocated,0)) AS quantity
				FROM v_wms_inventory_data_by_id inv 
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
				WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES') 
				AND (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN 1 ELSE ISNULL(inv.expiry_date,'') END) > (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN 0 ELSE CONVERT(VARCHAR(8),GETDATE(),112) END)
				GROUP BY inv.wh_master_id,inv.owner_id,inv.wh_item_master_id,invStatus.inv_status,ISNULL(inv.lot_number,''),ISNULL(inv.expiry_date,''),ISNULL(inv.attribute1,''),ISNULL(inv.attribute2,''),ISNULL(inv.attribute3,''),ISNULL(inv.attribute4,''),ISNULL(inv.attribute5,'')
			)
			SELECT item.item_number
				,item.description AS item_description
				,item.grade
				,item.price
				,uom.uom
				,t.planqty
				,t.quantity
				,t.inventory_status
			FROM (SELECT tOutbound.wh_item_master_id
						,tOutbound.item_master_id
						,tOutbound.item_uom_id
						,ISNULL(tOutbound.default_item_status,'') AS inventory_status 
						,tOutbound.planqty
						,SUM(ISNULL(tInv.quantity,0)) AS quantity 
					FROM tOutbound
					LEFT JOIN tInventory tInv ON tOutbound.wh_master_id = tInv.wh_master_id
											 AND tOutbound.owner_id = tInv.owner_id
											 AND tOutbound.wh_item_master_id = tInv.wh_item_master_id
											 AND tOutbound.default_item_status = tInv.inv_status
											 AND (ISNULL(tInv.lot_number,'') = ISNULL(tOutbound.lot_number,'') OR ISNULL(tOutbound.lot_number,'') = '') 
											 AND (ISNULL(tInv.expiry_date,'') = ISNULL(tOutbound.expiry_date,'') OR ISNULL(tOutbound.expiry_date,'') = '') 
											 AND (ISNULL(tInv.attribute1,'') = ISNULL(tOutbound.attribute1,'') OR ISNULL(tOutbound.attribute1,'') = '') 
											 AND (ISNULL(tInv.attribute2,'') = ISNULL(tOutbound.attribute2,'') OR ISNULL(tOutbound.attribute2,'') = '') 
											 AND (ISNULL(tInv.attribute3,'') = ISNULL(tOutbound.attribute3,'') OR ISNULL(tOutbound.attribute3,'') = '') 
											 AND (ISNULL(tInv.attribute4,'') = ISNULL(tOutbound.attribute4,'') OR ISNULL(tOutbound.attribute4,'') = '') 
											 AND (ISNULL(tInv.attribute5,'') = ISNULL(tOutbound.attribute5,'') OR ISNULL(tOutbound.attribute5,'') = '') 
					GROUP BY tOutbound.wh_item_master_id,tOutbound.item_master_id,tOutbound.item_uom_id,ISNULL(tOutbound.default_item_status,'') ,tOutbound.planqty
					) t
				INNER JOIN t_wms_item item ON t.item_master_id = item.item_master_id
				INNER JOIN t_wms_item_uom uom ON t.item_uom_id = uom.item_uom_id
				WHERE ISNULL(t.planqty,0) > ISNULL(t.quantity,0)

			IF (@@ROWCOUNT > 0)
				SET @out_ErrorCode = '999';
			ELSE
				SET @out_ErrorCode = '0';
		END
	ELSE
		BEGIN
			;With tOutbound AS
			(
				SELECT ms.wh_master_id
					,ms.owner_id 
					,dt.wh_item_master_id 
					,dt.item_master_id
					,dt.default_item_status
					,dt.item_uom_id
					,ISNULL(dt.lpn ,'') AS lpn
					,ISNULL(dt.lot_number ,'') AS lot_number
					,ISNULL(dt.expiry_date,'') AS expiry_date
					,ISNULL(dt.attribute1 ,'') AS attribute1
					,ISNULL(dt.attribute2 ,'') AS attribute2
					,ISNULL(dt.attribute3 ,'') AS attribute3
					,ISNULL(dt.attribute4 ,'') AS attribute4
					,ISNULL(dt.attribute5 ,'') AS attribute5
      				,SUM(dt.quantity_order - ISNULL(pickDT.quantity_plan,0)) AS planqty 
				FROM t_wms_outbound_master ms 
				INNER JOIN t_wms_outbound_detail dt ON ms.outbound_order_master_id = dt.outbound_order_master_id
				LEFT JOIN (SELECT outbound_order_detail_id
								,SUM(quantity_plan) AS quantity_plan
							FROM t_wms_outbound_pick_detail
							WHERE is_override = 'NO'
							GROUP BY outbound_order_detail_id
							) pickDT ON dt.outbound_order_detail_id = pickdT.outbound_order_detail_id 
				WHERE ms.load_id = @in_vchLoadID
				AND ms.wh_master_id = @in_vchWhMasterID
				GROUP BY ms.wh_master_id,ms.owner_id,dt.wh_item_master_id,dt.item_master_id,dt.default_item_status,dt.item_uom_id,ISNULL(dt.lpn ,''),ISNULL(dt.lot_number ,''),ISNULL(dt.expiry_date,''),ISNULL(dt.attribute1 ,''),ISNULL(dt.attribute2 ,''),ISNULL(dt.attribute3 ,''),ISNULL(dt.attribute4 ,''),ISNULL(dt.attribute5 ,'')
			)
			, tInventory AS
			(	SELECT inv.wh_master_id
					,inv.owner_id
					,inv.wh_item_master_id
					,invStatus.inv_status
					,ISNULL(inv.lpn,'')			as lpn
					,ISNULL(inv.lot_number,'')	AS lot_number
					,ISNULL(inv.expiry_date,'')	AS expiry_date
					,ISNULL(inv.attribute1,'')  AS attribute1
					,ISNULL(inv.attribute2,'')  AS attribute2
					,ISNULL(inv.attribute3,'')  AS attribute3
					,ISNULL(inv.attribute4,'')  AS attribute4
					,ISNULL(inv.attribute5,'')  AS attribute5
					,SUM(inv.quantity - ISNULL(inv.quantity_allocated,0)) AS quantity
				FROM v_wms_inventory_data_by_id inv 
				INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
				INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
				WHERE loc.loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_LOCATION_TYPE_FOR_PICK' AND is_active = 'YES')
				AND (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN 1 ELSE ISNULL(inv.expiry_date,'') END) > (CASE WHEN ISNULL(inv.expiry_date,'') = '' THEN 0 ELSE CONVERT(VARCHAR(8),GETDATE(),112) END)
				GROUP BY inv.wh_master_id,inv.owner_id,inv.wh_item_master_id,invStatus.inv_status,ISNULL(inv.lpn,''),ISNULL(inv.lot_number,''),ISNULL(inv.expiry_date,''),ISNULL(inv.attribute1,''),ISNULL(inv.attribute2,''),ISNULL(inv.attribute3,''),ISNULL(inv.attribute4,''),ISNULL(inv.attribute5,'')
			)
			SELECT item.item_number
				,item.description AS item_description
				,item.grade
				,item.price
				,uom.uom
				,t.planqty
				,t.quantity
				,t.inventory_status
			FROM (SELECT tOutbound.wh_item_master_id
					,tOutbound.item_master_id
					,tOutbound.item_uom_id
					,ISNULL(tOutbound.default_item_status,'') AS inventory_status 
					,tOutbound.planqty
					,SUM(ISNULL(tInv.quantity,0)) AS quantity 
				  FROM tOutbound
				  LEFT JOIN tInventory tInv ON tOutbound.wh_master_id = tInv.wh_master_id
				  						AND tOutbound.owner_id = tInv.owner_id
				  						AND tOutbound.wh_item_master_id = tInv.wh_item_master_id
				  						AND tOutbound.default_item_status = tInv.inv_status
				  						AND (ISNULL(tInv.lot_number,'') = ISNULL(tOutbound.lot_number,'') OR ISNULL(tOutbound.lot_number,'') = '') 
				  						AND (ISNULL(tInv.expiry_date,'') = ISNULL(tOutbound.expiry_date,'') OR ISNULL(tOutbound.expiry_date,'') = '') 
				  						AND (ISNULL(tInv.attribute1,'') = ISNULL(tOutbound.attribute1,'') OR ISNULL(tOutbound.attribute1,'') = '') 
				  						AND (ISNULL(tInv.attribute2,'') = ISNULL(tOutbound.attribute2,'') OR ISNULL(tOutbound.attribute2,'') = '') 
				  						AND (ISNULL(tInv.attribute3,'') = ISNULL(tOutbound.attribute3,'') OR ISNULL(tOutbound.attribute3,'') = '') 
				  						AND (ISNULL(tInv.attribute4,'') = ISNULL(tOutbound.attribute4,'') OR ISNULL(tOutbound.attribute4,'') = '') 
				  						AND (ISNULL(tInv.attribute5,'') = ISNULL(tOutbound.attribute5,'') OR ISNULL(tOutbound.attribute5,'') = '') 
				  						AND (ISNULL(tInv.lpn,'') = ISNULL(tOutbound.lpn,'') OR ISNULL(tOutbound.lpn,'') = '')
				  GROUP BY tOutbound.wh_item_master_id,tOutbound.item_master_id,tOutbound.item_uom_id,ISNULL(tOutbound.default_item_status,''),tOutbound.planqty
				) t
			INNER JOIN t_wms_item item ON t.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON t.item_uom_id = uom.item_uom_id
			WHERE ISNULL(t.planqty,0) > ISNULL(t.quantity,0) 
			
			IF (@@ROWCOUNT > 0)
				SET @out_ErrorCode = '999';
			ELSE
				SET  @out_ErrorCode = '0';
		END
END TRY
BEGIN CATCH
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_close_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		JANG
-- Create date: 29/8/2013
-- Description:	Confilm deliver
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_close_confirm] 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID UNIQUEIDENTIFIER,
	@in_vchCarrierID		UNIQUEIDENTIFIER,
	@in_vchTruckTypeID		UNIQUEIDENTIFIER,  
	@in_vchTruckNumber		NVARCHAR(50) = null,
	@in_vchDriverLicense	NVARCHAR(50) = null,
	@in_vchContainerNo		NVARCHAR(50) = null, 
	@in_vchSealNumber		NVARCHAR(50) = null,
	@in_vchPostingDate		DATETIME
AS
BEGIN
	
	SET NOCOUNT ON; 
	UPDATE t_wms_outbound_master SET order_status = 'CLOSE'
		,carrier_id = @in_vchCarrierID
		,truck_type_id = @in_vchTruckTypeID
		,truck_no = @in_vchTruckNumber  
		,driver_license = @in_vchDriverLicense
		,ship_date_actual = @in_vchPostingDate  
		,seal_no = @in_vchSealNumber
		,container_no = @in_vchContainerNo
	WHERE outbound_order_master_id = @in_vchOutboundMasterID
END
