/****** Object:  StoredProcedure [dbo].[usp_outbound_consignment_check_quantity]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_outbound_consignment_check_quantity]
	@in_vchApplicationID			VARCHAR(40),
	@in_vchOutboundConsignmentMSID	UNIQUEIDENTIFIER,
	@out_ErrorCode					NVARCHAR(200) OUTPUT,
	@out_ErrorMessage				NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	declare @round int
	SELECT @round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	BEGIN TRY
		SELECT tOutbound.outbound_consignment_master_id
			,tOutbound.outbound_order_number
			,tOutbound.wh_item_master_id
			,tOutbound.item_master_id
			,tOutbound.item_number	 
			,ROUND(ISNULL(tOutbound.quantity_order,0),@round) AS quantity_order
			,ROUND(ISNULL(tInv.quantity_inventory,0),@round)  AS quantity_inventory
		FROM (
				SELECT obMS.outbound_consignment_master_id
					,obMS.outbound_order_number 
					,obDT.wh_item_master_id
					,obDT.item_master_id
					,obDT.item_number
					,custLoc.location_id
					,SUM(obDT.quantity_order) as quantity_order
				FROM t_wms_outbound_consignment_master obMS
				INNER JOIN t_wms_outbound_consignment_detail obDT ON obMS.outbound_consignment_master_id = obDT.outbound_consignment_master_id
				LEFT JOIN t_wms_customer_location custLoc ON obMS.customer_id = custLoc.customer_id
				LEFT JOIN t_wms_location loc ON custLoc.location_id = loc.location_id
				WHERE loc.wh_master_id = obMS.wh_master_id
				GROUP BY obMS.outbound_consignment_master_id
					,obMS.outbound_order_number 
					,obDT.wh_item_master_id
					,obDT.item_master_id
					,obDT.item_number
					,custLoc.location_id
			 ) tOutbound
		LEFT JOIN (SELECT wh_item_master_id
						,location_id
						,SUM(quantity)	quantity_inventory
					FROM t_wms_inventory
					GROUP BY wh_item_master_id,location_id
				   ) tInv ON tOutbound.wh_item_master_id = tInv.wh_item_master_id AND tOutbound.location_id = tInv.location_id
		WHERE tOutbound.outbound_consignment_master_id = @in_vchOutboundConsignmentMSID
		AND ROUND(ISNULL(tInv.quantity_inventory,0),@round) < ROUND(ISNULL(tOutbound.quantity_order,0),@round)
		
		IF (@@ROWCOUNT > 0)
			SET @out_ErrorCode = '999';
		ELSE
			SET  @out_ErrorCode = '0';
	END TRY
	BEGIN CATCH
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();	
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_consignment_generate_running]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_consignment_generate_running]
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY

		DECLARE
			@v_vchYear			VARCHAR(40),
			@v_vchMonth			NVARCHAR(2),
			@v_vchDay			NVARCHAR(2),

			@v_vchPrefix		NVARCHAR(5),
			@v_vchSuffix		NVARCHAR(5),
			@v_vchFormat		NVARCHAR(10),
			@v_intRunning		INT,
			@v_vchRunningID		VARCHAR(40),

			@v_vchOrderNumber	NVARCHAR(50)

		SELECT @v_vchYear = DATEPART(YYYY,GETDATE())
		SELECT @v_vchMonth = DATEPART(MM,GETDATE())
		SELECT @v_vchDay = DATEPART(DD,GETDATE())

		SELECT @v_vchPrefix = ISNULL(value,'') FROM t_wms_rule WHERE rule_code = 'PREFIX_OUTBOUND_ORDER_FOR_RUNNING'
		SELECT @v_vchSuffix = ISNULL(value,'') FROM t_wms_rule WHERE rule_code = 'SUFFIX_OUTBOUND_ORDER_FOR_RUNNING'
		SELECT @v_vchFormat = ISNULL(value,'0') FROM t_wms_rule WHERE rule_code = 'FORMAT_OUTBOUND_ORDER_FOR_RUNNING'

		SELECT @v_vchRunningID = running_id,@v_intRunning = running FROM t_wms_running_outbound_consignment WHERE [year] = @v_vchYear and [month] = @v_vchMonth and [day] = @v_vchDay

		IF (@v_intRunning IS NULL)
			BEGIN
				SET @v_intRunning = 0;
			END

		SET @v_intRunning = @v_intRunning + 1;
		SET @v_vchOrderNumber = @v_vchPrefix + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
		IF (@v_vchRunningID IS NULL)
			BEGIN
				SET @v_vchRunningID = NEWID();
				INSERT INTO t_wms_running_outbound_consignment(year, month, day, running, prefix, sufix)
				VALUES(@v_vchYear,@v_vchMonth,@v_vchDay,@v_intRunning,@v_vchPrefix,@v_vchSuffix)
			END
		ELSE
			BEGIN
				UPDATE t_wms_running_outbound_consignment SET running = @v_intRunning WHERE running_id = @v_vchRunningID
			END

		SET @out_ErrorMessage = '0';
		SELECT @v_vchOrderNumber AS outbound_order_number

	END TRY
	BEGIN CATCH
		SET @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH

END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_consignment_ship_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_consignment_ship_confirm]
	@in_vchApplicationID	VARCHAR(40),  
	@in_vchWhMasterID		UNIQUEIDENTIFIER, 
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchOrderNumber		NVARCHAR(50),
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(25),
	@in_dtShipDateActual	DATETIME,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
		DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(50) = '[usp_outbound_consignment_ship_confirm]', -- The name that uniquely tags this object.
		@v_vchApplicationName		NVARCHAR(100), 
		@v_dtProcessDate			DATETIME,
		@v_dtStartTranDate			DATETIME,
		@v_dtEndTranDate			DATETIME,
		@v_vchTranType				NVARCHAR(50) = 'OO_SHIP_CONSIGNMENT',
		@v_vchSubTranType			NVARCHAR(50),
		@v_vchHostInterfaceID		NVARCHAR(50),
		@v_vchBeginTrans			BIT = 0,
		@Round						INT,
		
		@v_vchOBConsignmentMasterID	UNIQUEIDENTIFIER,
		@v_vchOwnerID				UNIQUEIDENTIFIER,
		@v_vchOwnerCode				NVARCHAR(40),
		@v_vchOrderStatus			VARCHAR(10),
		@v_vchOrderType				NVARCHAR(30),
		@v_vchCustomerID			UNIQUEIDENTIFIER,
		@v_vchCustomerCode			NVARCHAR(50),
		@v_vchHDUdf1				NVARCHAR(50),
		@v_vchHDUdf2				NVARCHAR(50),
		@v_vchHDUdf3				NVARCHAR(50),
		@v_vchHDUdf4				NVARCHAR(50),
		@v_vchHDUdf5				NVARCHAR(50),
		@v_vchHDUdf6				NVARCHAR(50),
		@v_fltHDUdf7				FLOAT,
		@v_fltHDUdf8				FLOAT,
		@v_dtHDUdf9					DATETIME,
		@v_dtHDUdf10				DATETIME, 
		
		@v_vchOBConsignmentDetailID	UNIQUEIDENTIFIER,
		@v_vchLineNumber			NVARCHAR(10),
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
		@v_vchItemMasterID			UNIQUEIDENTIFIER,
		@v_vchItemNumber			NVARCHAR(50),
		@v_fltQuantityOrder			FLOAT,
		@v_vchItemUOMID				UNIQUEIDENTIFIER,
		@v_vchUOM					NVARCHAR(10),
		@v_vchLpn					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(50),
		@v_vchSerialNumber			NVARCHAR(50),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchDefaultItemStatus		NVARCHAR(40),
		@v_vchDTUdf1				NVARCHAR(50),
		@v_vchDTUdf2				NVARCHAR(50),
		@v_vchDTUdf3				NVARCHAR(50),
		@v_vchDTUdf4				NVARCHAR(50),
		@v_vchDTUdf5				NVARCHAR(50),
		@v_vchDTUdf6				NVARCHAR(50),
		@v_fltDTUdf7				FLOAT,
		@v_fltDTUdf8				FLOAT,
		@v_dtDTUdf9					DATETIME,
		@v_dtDTUdf10				DATETIME,
		@v_vchLotControl			VARCHAR(10),
		@v_vchExpiryDateControl		VARCHAR(10),
		@v_vchSerialControl			VARCHAR(10),
		@v_vchAttribute1Control		VARCHAR(10),
		@v_vchAttribute2Control		VARCHAR(10),
		@v_vchAttribute3Control		VARCHAR(10),
		@v_vchAttribute4Control		VARCHAR(10),
		@v_vchAttribute5Control		VARCHAR(10),

		--Inventory
		@v_vchInventoryID			UNIQUEIDENTIFIER,
		@v_vchAttributeGroupID		UNIQUEIDENTIFIER,
		@v_fltInventoryQty			FLOAT,
		@v_fltRemainQtyCanShip		FLOAT,
		@v_fltQtyCanShip			FLOAT,
		@v_vchInvParentLpn			NVARCHAR(25),
		@v_vchInvLpn				NVARCHAR(25),
		@v_vchInvLotNumber			NVARCHAR(50),
		@v_vchInvExpiryDate			NVARCHAR(50),
		@v_dtInvExpiryDate			DATETIME,
		@v_vchInvSerialNumber		NVARCHAR(50),
		@v_vchInvAttribute1			NVARCHAR(100),
		@v_vchInvAttribute2			NVARCHAR(100),
		@v_vchInvAttribute3			NVARCHAR(100),
		@v_vchInvAttribute4			NVARCHAR(100),
		@v_vchInvAttribute5			NVARCHAR(100),
		@v_dtInvReceiveDate			DATE,
		@v_dtInvMfgDate				DATE,

		--Customer Location
		@v_vchLocationID			UNIQUEIDENTIFIER,
		@v_vchLocation				NVARCHAR(50),

		--Calculate Volumn & Weight
		@v_fltWidth					FLOAT = 0,
		@v_fltLength				FLOAT = 0,
		@v_fltHeight				FLOAT = 0,
		@v_fltGrossWeight			FLOAT = 0,
		@v_intPercentTolerance		FLOAT = 0,
		@v_intPercenToleranceWeight FLOAT = 0,
		@v_fltVolumn				FLOAT = 0,	--item
		@v_fltTotalWeight			FLOAT = 0,	--item

		@v_vchInfPlanUomID			UNIQUEIDENTIFIER = NULL
	
	BEGIN TRY
		EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	
		SELECT @v_vchOBConsignmentMasterID = conMS.outbound_consignment_master_id
			,@v_vchOwnerID = conMS.owner_id
			,@v_vchOwnerCode = own.owner_code
			,@v_vchOrderStatus = conMS.order_status
			,@v_vchCustomerID = conMS.customer_id
			,@v_vchCustomerCode = conMS.customer_code
			,@v_vchHDUdf1	 = conMS.user_def1	
			,@v_vchHDUdf2	 = conMS.user_def2	
			,@v_vchHDUdf3	 = conMS.user_def3	
			,@v_vchHDUdf4	 = conMS.user_def4	
			,@v_vchHDUdf5	 = conMS.user_def5	
			,@v_vchHDUdf6	 = conMS.user_def6	
			,@v_fltHDUdf7	 = conMS.user_def7	
			,@v_fltHDUdf8	 = conMS.user_def8	
			,@v_dtHDUdf9	 = conMS.user_def9	
			,@v_dtHDUdf10	 = conMS.user_def10
			,@v_vchOrderType = conMS.order_type
		FROM t_wms_outbound_consignment_master conMS
		INNER JOIN t_wms_owner own ON conMS.owner_id = own.owner_id
		WHERE conMS.wh_master_id = @in_vchWhMasterID
		AND conMS.outbound_order_number = @in_vchOrderNumber

		IF(@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		SELECT TOP 1 @v_vchLocationID = loc.location_id
			,@v_vchLocation = loc.location
		FROM t_wms_customer_location custLoc
		INNER JOIN t_wms_location loc ON custLoc.location_id = loc.location_id
		WHERE custLoc.customer_id = @v_vchCustomerID
		AND loc.wh_master_id = @in_vchWhMasterID
		IF @v_vchLocationID IS NULL
			BEGIN
				SET @out_ErrorCode = 'CUSTOMER_LOCATION_NOT_FOUND';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
			 
		-------------------------------------------
		-- order type send to interface
		-------------------------------------------
		IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_INTERFACE' AND is_active = 'YES'))
			BEGIN
				SET @v_vchSubTranType = 'CONFIRM_TO_ERP';
			END
		ELSE
			BEGIN
				SET @v_vchSubTranType = 'CONFIRM_SHIP';
			END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;

		UPDATE t_wms_outbound_consignment_master SET 
			 order_status = 'SHIP'
			,ship_date_actual = @in_dtShipDateActual 
			,update_by = @in_vchUserID
			,update_date = GETDATE()
		WHERE outbound_consignment_master_id = @v_vchOBConsignmentMasterID

		DECLARE OutboundCursor CURSOR FOR 
			SELECT conDT.outbound_consignment_detail_id
				,conDT.line_number
				,conDT.wh_item_master_id
				,conDT.item_master_id
				,conDT.item_number
				,ROUND(conDT.quantity_order,@Round)
				,conDT.item_uom_id
				,conDT.default_item_status
				,conDT.lpn
				,conDT.lot_number
				,conDT.expiry_date
				,conDT.serial_number
				,conDT.attribute1
				,conDT.attribute2
				,conDT.attribute3
				,conDT.attribute4
				,conDT.attribute5
				,conDT.user_def1
				,conDT.user_def2
				,conDT.user_def3
				,conDT.user_def4
				,conDT.user_def5
				,conDT.user_def6
				,conDT.user_def7
				,conDT.user_def8
				,conDT.user_def9
				,conDT.user_def10
				,item.lot_control
				,item.expiry_date_control
				,item.sn_control
				,item.attribute1_control
				,item.attribute2_control
				,item.attribute3_control
				,item.attribute4_control
				,item.attribute5_control
				,conDT.interface_plan_uom_id
			FROM t_wms_outbound_consignment_detail conDT
			INNER JOIN t_wms_item item on conDT.item_master_id = item.item_master_id
			WHERE outbound_consignment_master_id = @v_vchOBConsignmentMasterID
			and ISNULL(quantity_ship,0) = 0
		OPEN OutboundCursor
		FETCH NEXT FROM OutboundCursor INTO @v_vchOBConsignmentDetailID, @v_vchLineNumber, @v_vchWhItemMasterID, @v_vchItemMasterID, @v_vchItemNumber, @v_fltQuantityOrder,@v_vchItemUOMID, @v_vchDefaultItemStatus
											, @v_vchLpn, @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5				
											, @v_vchDTUdf1, @v_vchDTUdf2, @v_vchDTUdf3, @v_vchDTUdf4, @v_vchDTUdf5, @v_vchDTUdf6, @v_fltDTUdf7, @v_fltDTUdf8, @v_dtDTUdf9, @v_dtDTUdf10				
											, @v_vchLotControl, @v_vchExpiryDateControl, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control,@v_vchInfPlanUomID
		WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @v_fltRemainQtyCanShip = @v_fltQuantityOrder

				--สำหรับปริมาตร
				SELECT @v_vchUOM = uom
					,@v_fltWidth = ISNULL(width,0)
					,@v_fltLength = ISNULL(length,0)
					,@v_fltHeight = ISNULL(height,0)
					,@v_fltGrossWeight = ISNULL(gross_weight,0)
					,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
					,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
				FROM t_wms_item_uom 
				WHERE item_uom_id = @v_vchItemUOMID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'

				NEXT_INVENTORY:
				--ต้องวนลูป Inventory เพื่อกรณีที่มีหลาย Receive Date
				SET @v_vchInventoryID		= NULL
				SET @v_vchAttributeGroupID 	= NULL
				SET @v_fltInventoryQty		= NULL
				SET @v_vchInvParentLpn		= NULL
				SET @v_vchInvLpn			= NULL
				SET @v_vchInvLotNumber		= NULL
				SET @v_vchInvExpiryDate		= NULL
				SET @v_vchInvSerialNumber	= NULL
				SET @v_vchInvAttribute1		= NULL
				SET @v_vchInvAttribute2		= NULL
				SET @v_vchInvAttribute3		= NULL
				SET @v_vchInvAttribute4		= NULL
				SET @v_vchInvAttribute5		= NULL
				SET @v_dtInvReceiveDate		= NULL
				SET @v_dtInvMfgDate			= NULL
				
				SELECT @v_vchInventoryID	=  inventory_id
					,@v_vchAttributeGroupID = attribute_group_id
					,@v_fltInventoryQty		= ROUND(quantity,@round)
					,@v_vchInvParentLpn		= parent_lpn		
					,@v_vchInvLpn			= lpn				
					,@v_vchInvLotNumber		= lot_number		
					,@v_vchInvExpiryDate	= expiry_date		
					,@v_vchInvSerialNumber	= serial_number		
					,@v_vchInvAttribute1	= attribute1		
					,@v_vchInvAttribute2	= attribute2		
					,@v_vchInvAttribute3	= attribute3		
					,@v_vchInvAttribute4	= attribute4		
					,@v_vchInvAttribute5	= attribute5		
					,@v_dtInvReceiveDate	= receive_date
					,@v_dtInvMfgDate		= mfg_date
				FROM v_wms_inventory_data_by_serial_mini
				WHERE wh_master_id = @in_vchWhMasterID 
				AND owner_id = @v_vchOwnerID
				AND location_id = @v_vchLocationID 
				AND wh_item_master_id = @v_vchWhItemMasterID 
				AND inv_status = @v_vchDefaultItemStatus
				AND (CASE ISNULL(@v_vchLPN,'') WHEN '' THEN '' ELSE ISNULL(lpn,'') END) = (CASE ISNULL(@v_vchLPN,'') WHEN '' THEN '' ELSE ISNULL(@v_vchLPN,'') END)
				AND (CASE ISNULL(@v_vchLotNumber,'') WHEN '' THEN '' ELSE ISNULL(lot_number,'') END) = (CASE ISNULL(@v_vchLotNumber,'') WHEN '' THEN '' ELSE ISNULL(@v_vchLotNumber,'') END)
				AND (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN '' ELSE ISNULL(expiry_date,'') END) = (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN '' ELSE ISNULL(@v_vchExpiryDate,'') END)
				AND (CASE ISNULL(@v_vchAttribute1,'') WHEN '' THEN '' ELSE ISNULL(attribute1,'') END) = (CASE ISNULL(@v_vchAttribute1,'') WHEN '' THEN '' ELSE ISNULL(@v_vchAttribute1,'') END)
				AND (CASE ISNULL(@v_vchAttribute2,'') WHEN '' THEN '' ELSE ISNULL(attribute2,'') END) = (CASE ISNULL(@v_vchAttribute2,'') WHEN '' THEN '' ELSE ISNULL(@v_vchAttribute2,'') END)
				AND (CASE ISNULL(@v_vchAttribute3,'') WHEN '' THEN '' ELSE ISNULL(attribute3,'') END) = (CASE ISNULL(@v_vchAttribute3,'') WHEN '' THEN '' ELSE ISNULL(@v_vchAttribute3,'') END)
				AND (CASE ISNULL(@v_vchAttribute4,'') WHEN '' THEN '' ELSE ISNULL(attribute4,'') END) = (CASE ISNULL(@v_vchAttribute4,'') WHEN '' THEN '' ELSE ISNULL(@v_vchAttribute4,'') END)
				AND (CASE ISNULL(@v_vchAttribute5,'') WHEN '' THEN '' ELSE ISNULL(attribute5,'') END) = (CASE ISNULL(@v_vchAttribute5,'') WHEN '' THEN '' ELSE ISNULL(@v_vchAttribute5,'') END)
				AND (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(@v_vchSerialNumber,'') END)
				ORDER BY receive_date
				---------------------------------------
				-- Check Inventory
				---------------------------------------
				IF @v_vchInventoryID IS NULL
					BEGIN
						SET @out_ErrorCode = '989';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_INVENTORY_DATA_NO_DETAIL',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,@v_vchItemNumber,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
		
				IF (@v_fltRemainQtyCanShip > 0 AND @v_vchInventoryID IS NOT NULL)
					BEGIN
						SET @v_dtStartTranDate = GETDATE();
						---------------------------------------------------
						-- Check จำนวนที่สามารถ Ship ได้จริง ของ Inventory record นั้นๆ
						---------------------------------------------------
						IF (ROUND(ISNULL(@v_fltInventoryQty,0),@Round) < ROUND(ISNULL(@v_fltRemainQtyCanShip,0),@Round))
							SET @v_fltQtyCanShip = @v_fltInventoryQty
						ELSE
							SET @v_fltQtyCanShip = @v_fltRemainQtyCanShip
							
						--คำนวณปริมาตร
						IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyCanShip,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyCanShip,2)
							END

						--------------------------------------------
						--Manage source inventory
						--------------------------------------------
						UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyCanShip,@Round) 
							,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
							,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
						WHERE inventory_id = @v_vchInventoryID 
						AND attribute_group_id = @v_vchAttributeGroupID

						IF (@v_vchSerialControl = 'FULL')
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyCanShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID 
								AND attribute_value = @v_vchSerialNumber											
							END

						--Inventory attribute
						IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyCanShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID
								AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END

						DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
						DELETE FROM t_wms_inventory WHERE quantity <= 0

						--Update Volumn & Weight in from location
						IF @v_vchLocationID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location]
									SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
									WHERE [location_id] = @v_vchLocationID
							END

						UPDATE t_wms_outbound_consignment_detail SET 
							item_status = 'SHIP'
							,quantity_ship = ROUND(ISNULL(quantity_ship,0) + @v_fltQtyCanShip,@Round)  
							,ship_location_id = @v_vchLocationID
							,ship_location = @v_vchLocation
						WHERE outbound_consignment_detail_id = @v_vchOBConsignmentDetailID

						IF ISNULL(@v_vchInvExpiryDate,'') <> ''
							SET @v_dtInvExpiryDate = CONVERT(DATE,@v_vchInvExpiryDate);
						ELSE
							SET @v_dtInvExpiryDate = NULL

						--คำนวณหน่วยส่งกลับ interface
						DECLARE @v_vchInfPlanUom    VARCHAR(20) = NULL
						DECLARE @v_fltInfQuantity   FLOAT = NULL
						DECLARE @v_vchInfConFactor  FLOAT = NULL

						SELECT TOP 1 @v_vchInfPlanUomID = uom.item_uom_id
							,@v_vchInfPlanUom = uom.uom
							,@v_vchInfConFactor = uom.conversion_factor
						FROM t_wms_item_uom uom
						WHERE uom.item_uom_id = @v_vchInfPlanUomID

						IF @v_vchInfPlanUomID IS NOT NULL
							BEGIN
								SET @v_fltInfQuantity = ROUND((@v_fltQtyCanShip / @v_vchInfConFactor),@Round)
							END
						ELSE
							BEGIN
								SET @v_fltInfQuantity = @v_fltQtyCanShip
								SET @v_vchInfPlanUom = @v_vchUOM
							END

						--For After Qty
						DECLARE @v_fltInvAfterQty	FLOAT = 0;
						SET @v_fltInvAfterQty = ROUND((@v_fltInventoryQty - @v_fltQtyCanShip),@Round)
						SET @v_dtEndTranDate = GETDATE()
						EXEC usp_LogManager
								@in_vchApplicationID		= @in_vchApplicationID
								, @in_vchAppName			= @v_vchApplicationName
								, @in_vchDevice				= @in_vchDeviceID
								, @in_vchUserID				= @in_vchUserID
								, @in_vchLogType			= 'TRANSACTION'
								, @in_vchProcess			= @c_vchObjName
								, @in_dtProcessDateTime		= @v_dtStartTranDate
								, @in_vchData1				= @v_vchOrderType
								, @in_vchTranType			= @v_vchTranType
								, @in_vchSubTranType		= @v_vchSubTranType
								, @in_dtStartTranDate		= @v_dtStartTranDate
								, @in_dtEndTranDate			= @v_dtEndTranDate
								, @in_vchWhID 				= @in_vchWarehouse
								, @in_vchToWhID 			= NULL
								, @in_vchLocation			= @v_vchLocation
								, @in_vchToLocation			= NULL
								, @in_vchOwner				= @v_vchOwnerCode
								, @in_vchToOwner			= NULL
								, @in_vchItemNumber			= @v_vchItemNumber
								, @in_fltQuantity			= @v_fltQtyCanShip
								, @in_vchUOM				= @v_vchUom
								, @in_fltAfterQuantity		= @v_fltInvAfterQty
								, @in_vchAfterUOM			= @v_vchUom
								, @in_vchLotNumber			= @v_vchInvLotNumber
								, @in_vchAfterLotNumber		= NULL
								, @in_dtExpiryDate			= @v_dtInvExpiryDate
								, @in_dtAfterExpiryDate		= NULL
								, @in_vchAttribute1			= @v_vchInvAttribute1	
								, @in_vchAfterAttribute1	= NULL
								, @in_vchAttribute2			= @v_vchInvAttribute2
								, @in_vchAfterAttribute2	= NULL		
								, @in_vchAttribute3			= @v_vchInvAttribute3	
								, @in_vchAfterAttribute3	= NULL			
								, @in_vchAttribute4			= @v_vchInvAttribute4
								, @in_vchAfterAttribute4	= NULL		
								, @in_vchAttribute5			= @v_vchInvAttribute5
								, @in_vchAfterAttribute5	= NULL		
								, @in_vchSerialNumber		= @v_vchInvSerialNumber
								, @in_vchReferenceNumber	= NULL
								, @in_vchLPN				= @v_vchInvLpn
								, @in_vchAfterLPN			= NULL
								, @in_vchParentLPN			= @v_vchInvParentLpn
								, @in_vchAfterParentLPN		= NULL
								, @in_vchStatus				= @v_vchDefaultItemStatus
								, @in_vchAfterStatus		= NULL
								, @in_vchReasonCode			= NULL
								, @in_vchOrderNumber		= @in_vchOrderNumber
								, @in_vchOrderStatus		= 'SHIP'--@v_vchOrderStatus
								, @in_vchControlNumber		= @v_vchHostInterfaceID
								, @in_vchLineNumber			= @v_vchLineNumber
								, @in_vchOrderQuantity		= @v_fltQuantityOrder
								, @in_vchShortQuantity		= 0
								, @in_vchHUDF1				= @v_vchHDUdf1
								, @in_vchHUDF2				= @v_vchHDUdf2
								, @in_vchHUDF3				= @v_vchHDUdf3
								, @in_vchHUDF4				= @v_vchHDUdf4
								, @in_vchHUDF5				= @v_vchHDUdf5
								, @in_vchHUDF6				= @v_vchHDUdf6
								, @in_fltHUDF7				= @v_fltHDUdf7
								, @in_fltHUDF8				= @v_fltHDUdf8
								, @in_dtpHUDF9				= @v_dtHDUdf9
								, @in_dtpHUDF10				= @v_dtHDUdf10
								  
								, @in_vchDUDF1				= @v_vchDTUdf1
								, @in_vchDUDF2				= @v_vchDTUdf2
								, @in_vchDUDF3				= @v_vchDTUdf3
								, @in_vchDUDF4				= @v_vchLocation
								, @in_vchDUDF5				= @v_vchDTUdf5
								, @in_vchDUDF6				= @v_vchInfPlanUom
								, @in_fltDUDF7				= @v_fltInfQuantity
								, @in_fltDUDF8				= @v_fltDTUdf8
								, @in_dtpDUDF9				= @v_dtDTUdf9
								, @in_dtpDUDF10				= @v_dtDTUdf10
								, @in_vchCustomerCode		= @v_vchCustomerCode
								, @in_dtShipDateActual		= @in_dtShipDateActual
								, @in_vchComment			= @v_vchOBConsignmentDetailID
								, @in_vchHostRecordID		= @v_vchHostInterfaceID
								, @in_dtReceiveDate			= @v_dtInvReceiveDate	
								, @in_dtProductionDate		= @v_dtInvMfgDate		 
								, @in_vchErrorCode			= @out_ErrorCode OUTPUT
								, @in_vchMessage			= @out_ErrorMessage   OUTPUT

						IF (@out_ErrorCode <> '0' and @out_ErrorCode <> '')
							BEGIN
								GOTO WRITE_PROC;
							END

						SET @v_fltRemainQtyCanShip = ROUND(ROUND(@v_fltRemainQtyCanShip,2) - ROUND(@v_fltQtyCanShip,2),2)

						IF @v_fltRemainQtyCanShip > 0
							GOTO NEXT_INVENTORY;

					END

				FETCH NEXT FROM OutboundCursor INTO @v_vchOBConsignmentDetailID, @v_vchLineNumber, @v_vchWhItemMasterID, @v_vchItemMasterID, @v_vchItemNumber, @v_fltQuantityOrder,@v_vchItemUOMID , @v_vchDefaultItemStatus
											, @v_vchLpn, @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5				
											, @v_vchDTUdf1, @v_vchDTUdf2, @v_vchDTUdf3, @v_vchDTUdf4, @v_vchDTUdf5, @v_vchDTUdf6, @v_fltDTUdf7, @v_fltDTUdf8, @v_dtDTUdf9, @v_dtDTUdf10				
											, @v_vchLotControl, @v_vchExpiryDateControl, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control,@v_vchInfPlanUomID
			END
		CLOSE OutboundCursor;  
		DEALLOCATE OutboundCursor;
		
		COMMIT TRANSACTION;
		
		--Update Host Shipment = PENDING
		IF (@v_vchTranType = 'OO_SHIP_CONSIGNMENT' AND @v_vchSubTranType = 'CONFIRM_TO_ERP')
			BEGIN
				UPDATE t_host_wms_ship_conf_detail_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
				UPDATE t_host_wms_ship_conf_header_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
		RETURN;

		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			IF CURSOR_STATUS('global','OutboundCursor')>=-1
				BEGIN
					CLOSE OutboundCursor;
					DEALLOCATE OutboundCursor;
				END
			SET @v_dtProcessDate = GETDATE();					
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDate,
				@in_vchData1 = @in_vchOrderNumber,
				@in_vchData2 = @v_vchHostInterfaceID,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage

		END
	END TRY
	BEGIN CATCH
		
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
		IF CURSOR_STATUS('global','OutboundCursor')>=-1
			BEGIN
				CLOSE OutboundCursor;
				DEALLOCATE OutboundCursor;
			END
		
		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END

		SET @v_dtProcessDate = GETDATE();
		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDate,
				@in_vchData1 = @in_vchOrderNumber,
				@in_vchData2 = @v_vchHostInterfaceID,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
					
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')


	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_deliver_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		JANG
-- Create date: 29/8/2013
-- Description:	Confilm deliver
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_deliver_confirm] 
	@in_vchWarehouse		NVARCHAR(25),
	@v_vchOutboundOrderNumber NVARCHAR(25)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE
	@v_vchWarehouseMasterID		VARCHAR(40)

	SELECT @v_vchWarehouseMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse

	UPDATE t_wms_outbound_master
	SET order_status = 'DELIVER'
	WHERE outbound_order_number = @v_vchOutboundOrderNumber AND wh_master_id = @v_vchWarehouseMasterID
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_blind_pick]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_generate_blind_pick]
(
	@in_vchApplicationID		VARCHAR(40)  = NULL,
	@in_vchLocalID				VARCHAR(40)  = NULL,
	@in_vchDeviceID				NVARCHAR(50) = NULL,
	@in_vchUserID				NVARCHAR(25) = NULL,
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50) = NULL,
	@in_vchCustomerID			UNIQUEIDENTIFIER = NULL,
	@in_vchCustomerCode			NVARCHAR(50) = NULL,
	@in_vchToWarehouse			NVARCHAR(25)  = NULL,	 --สำหรับ กรณีที่ Order Type กำหนดให้ Insert Inbound Auto จะต้องใส่ข้อมูล Towarehouse มาด้วย หรือก็คือ column Department ใน outbound master
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwnerID				UNIQUEIDENTIFIER,
	@in_vchOwnerCode			NVARCHAR(40),	 
	@in_vchBoxNumber			NVARCHAR(25) = NULL, 
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchLocation				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25),
	@in_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
	@in_vchInvStatus			NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber			NVARCHAR(50) = NULL, 
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL, 
	@in_vchSerialNumber			NVARCHAR(25) = NULL,	-- ALL หรือส่งค่ามา
	@in_fltQuantity				FLOAT		 = NULL,
	@in_vchUOMPrompt			NVARCHAR(40) = NULL,  
	@out_vchErrorCode			NVARCHAR(50)  OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)  OUTPUT  
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @Round						INT,
			@c_vchObjName				NVARCHAR(50) = '[usp_outbound_generate_blind_pick]',
			@v_vchApplicationName		NVARCHAR(50)= NULL,
			@v_vchBeginTrans			BIT = 0,
			@v_dtProcessDateTime		DATETIME, 
			@v_dtStartDate				DATETIME, 
			@RulePickPack				NVARCHAR(3) = 'NO',
			@RuleAutoStaging			NVARCHAR(3) = 'NO',
			
			@v_nCount					INT = 0,
			@v_vchOrderType				NVARCHAR(20) = NULL,
			@v_vchForkLocationID		UNIQUEIDENTIFIER = NULL, 
			@v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchOrderStatus			NVARCHAR(10) = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL,
			@v_vchPickLineNumber		NVARCHAR(5)	 = NULL,
			 
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemDesc				NVARCHAR(200) = NULL,
			@v_vchGrade					NVARCHAR(40) = NULL,
			@v_fltPrice					FLOAT = NULL,
			@v_vchLotControl			VARCHAR(10) = NULL,
			@v_vchExpControl			VARCHAR(10) = NULL,
			@v_vchSNControl				VARCHAR(10) = NULL,
			@v_vchAttribute1Control		VARCHAR(10) = NULL,
			@v_vchAttribute2Control		VARCHAR(10) = NULL,
			@v_vchAttribute3Control		VARCHAR(10) = NULL,
			@v_vchAttribute4Control		VARCHAR(10) = NULL,
			@v_vchAttribute5Control		VARCHAR(10) = NULL,
			@v_vchItemIsActive			VARCHAR(3) = NULL,

			-- Item UOM
			@v_vchItemUomID				UNIQUEIDENTIFIER,
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20),
			@v_vchIsPrimaryUOM			VARCHAR(5),
			@v_fltConversionFactor		FLOAT = 0,
			@v_fltBaseQuantity			FLOAT = 0,
			@v_fltWidth					FLOAT = 0,  --item Uom
			@v_fltLength				FLOAT = 0,  --item Uom
			@v_fltHeight				FLOAT = 0,  --item Uom
			@v_fltGrossWeight			FLOAT = 0,  --item Uom
			@v_intPercentTolerance		FLOAT = 0,  --item Uom
			@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
			@v_fltVolumn				FLOAT = 0,	--item Uom
			@v_fltTotalWeight			FLOAT = 0,	--item Uom

			--@v_vchPickLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchPickToLPN				NVARCHAR(25) = NULL,

			--Inventory 
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_fltInvQty				FLOAT,
			@v_fltInvQtyAllocate		FLOAT,
			@v_fltInvQtyRemain			FLOAT, --จำนวนคงเหลือใน Inventory ที่สามารถหยิบได้ 
			@v_fltInvQtyForUpdateLog	FLOAT,
			
			-- STG MOD For CBD
			@v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchStagingLocation		NVARCHAR(50), 
			@v_fltQuantityStage			FLOAT,
			@v_vchStagingParentLPN		NVARCHAR(25) = NULL,
			@v_vchStagingLPN			NVARCHAR(25) = NULL, 
			@v_fltSummaryInvPick		FLOAT = 0

BEGIN TRY
	SET @v_dtStartDate = GETDATE();
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT @RuleAutoStaging = VALUE FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
	SELECT @v_vchForkLocationID = location_id FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location = @in_vchForkLocation AND is_active = 'YES'
	 
	-------------------------------------------------
	-- SET Box Number
	-------------------------------------------------
	IF ISNULL(@in_vchBoxNumber,'') = ''
		BEGIN
			SET @in_vchBoxNumber = @in_vchOutboundOrderNumber
		END

	IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_BLIND_PICK_SHOW_CUSTOMER' and is_active = 'YES') = 'NO'
		BEGIN
			SELECT TOP 1 @in_vchCustomerCode = customer_code FROM t_wms_customer WHERE is_active = 'YES'
		END 

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SET @in_vchItemNumber = NULL
	SELECT @v_vchItemMasterID = item.item_master_id
		, @in_vchItemNumber = item.item_number
		, @v_vchLotControl = item.lot_control
		, @v_vchExpControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchItemIsActive = item.is_active
		, @v_fltPrice = item.price
		, @v_vchGrade = item.grade
	FROM t_wms_item item
 	WHERE owner_id = @in_vchOwnerID
	AND item_master_id = @v_vchItemMasterID
	IF (@in_vchItemNumber IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_vchErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END 

	--------------------------------------------------
	--Get & Check Item UOM
	--------------------------------------------------
	SELECT @v_vchBaseItemUomID = item_uom_id
		,@v_vchBaseUomPrompt = uom_prompt 
		,@v_vchBaseUom = uom
		,@v_fltConversionFactor = conversion_factor
		,@v_vchIsPrimaryUOM = primary_uom
		,@v_fltWidth = ISNULL(width,0)
		,@v_fltLength = ISNULL(length,0)
		,@v_fltHeight = ISNULL(height,0)
		,@v_fltGrossWeight = ISNULL(gross_weight,0)
		,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
		,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt		
	AND is_active = 'YES'
	IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_vchErrorCode = '107';
			SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		END

	--------------------------------------------------
	--Get Primary Uom
	--------------------------------------------------
	IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt 
				,@v_vchBaseUom = uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END
	
	--------------------------------------------------
	--Set Input Base Qty 
	--------------------------------------------------
	SET @v_fltBaseQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);

BEGIN TRANSACTION;
SET @v_vchBeginTrans = 1;

	-------------------------------------------------
	-- GET Data From Inventory
	-------------------------------------------------
	SET @v_nCount = 0;
	SELECT @v_nCount = COUNT(inventory_id)
		,@v_fltInvQty = SUM(quantity)
		,@v_fltInvQtyAllocate = SUM(quantity_allocated)
		,@v_fltInvQtyRemain = SUM(quantity - quantity_allocated)
	FROM v_wms_inventory_data_serial_by_id
	WHERE wh_master_id = @in_vchWhMasterID
	AND wh_item_master_id = @in_vchWhItemMasterID
	AND location_id = @in_vchLocationID
	AND inventory_status_id = @in_vchInvStatusID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
	AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
	
	IF @v_nCount = 0
		BEGIN
			-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
			SET @out_vchErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
			GOTO WRITE_PROC;
		END

	--------------------------------------------------
	-- Check จำนวนใน Inventory กับจำนวนที่จะ Pick
	-- ถ้าจำนวนที่จะ Pick > จำนวนใน Inventory = ERROR
	--------------------------------------------------
	IF (@in_vchSerialNumber = 'ALL')
		BEGIN
			SET @v_fltBaseQuantity = ROUND(@v_fltInvQty,@Round)
		END

	IF ROUND(@v_fltBaseQuantity,@Round) > ROUND(@v_fltInvQtyRemain,@Round)
		BEGIN
			-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
			SET @out_vchErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
			GOTO WRITE_PROC;
		END

	------------------------------------------------------------
	-- SET pick_to_lpn
	-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
	------------------------------------------------------------
	IF (ROUND(@v_fltBaseQuantity,@Round) = ROUND(@v_fltInvQty,@Round) AND ROUND(@v_fltInvQtyAllocate,@Round) = 0 AND ISNULL(@in_vchLPN,'') <> '')
		BEGIN
			SET @v_vchPickToLPN = @in_vchLPN
		END
	ELSE
		BEGIN
			SET @v_vchPickToLPN = @in_vchBoxNumber
		END
 
	-------------------------------------------------------
	--INSERT OUTBOUND MASTER
	-------------------------------------------------------
	SET @v_vchOutboundMasterID = NULL
	SELECT @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchOrderStatus = order_status
	FROM t_wms_outbound_master
	WHERE wh_master_id = @in_vchWhMasterID
	AND outbound_order_number = @in_vchOutboundOrderNumber
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			DECLARE @v_vchCustomerName	NVARCHAR(200) = NULL
			DECLARE @v_vchCustomerDesc	NVARCHAR(200) = NULL
			DECLARE @v_vchAddrLine1		NVARCHAR(300) = NULL
			DECLARE @v_vchAddrLine2		NVARCHAR(300) = NULL
			DECLARE @v_vchAddrLine3		NVARCHAR(300) = NULL
			DECLARE @v_vchCustCity		NVARCHAR(50) = NULL
			DECLARE @v_vchCustProvince	NVARCHAR(50) = NULL
			DECLARE @v_vchPostalCode	NVARCHAR(10) = NULL
			DECLARE @v_vchCountryCode	NVARCHAR(10) = NULL
			DECLARE @v_vchCountryName	NVARCHAR(50) = NULL
			DECLARE @v_vchContact		NVARCHAR(200) = NULL
			DECLARE @v_vchPhone			NVARCHAR(50) = NULL
			DECLARE @v_vchFax			NVARCHAR(50) = NULL
			DECLARE @v_vchEmail			NVARCHAR(50) = NULL

			SELECT TOP 1 @v_vchOrderType = value FROM t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'
			IF ((@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_INBOUND' AND is_active = 'YES')) AND ISNULL(@in_vchToWarehouse,'') = '')
			BEGIN
				SET @out_vchErrorCode = 'INFO-TO-WAREHOUSE-NOT-FOUND'
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC;
			END

			SELECT TOP 1 @v_vchCustomerName = customer_name
				, @v_vchCustomerDesc = description
				, @v_vchAddrLine1 = addr_line_1
				, @v_vchAddrLine2 = addr_line_2
				, @v_vchAddrLine3 = addr_line_3
				, @v_vchCustCity = city
				, @v_vchCustProvince = province
				, @v_vchPostalCode = postal_code
				, @v_vchCountryCode = country_code
				, @v_vchCountryName = country_name
				, @v_vchPhone = phone
				, @v_vchContact = contact
				, @v_vchFax = fax
				, @v_vchEmail = email
			FROM t_wms_customer
			WHERE owner_id = @in_vchOwnerID
			AND customer_id = @in_vchCustomerID
			AND is_active = 'YES'

			SET @v_vchOutboundMasterID = NEWID()
			INSERT INTO [dbo].[t_wms_outbound_master]
			   ([outbound_order_master_id]
			   ,[wh_master_id]
			   ,[outbound_order_number]
			   ,[owner_id]
			   ,[order_type]
			   ,[order_status]
			   ,[order_date]
			   ,[ship_date_plan]
			   ,[department]
			   ,[customer_id]
			   ,[customer_code]
			   ,[customer_name]
			   ,[cus_description]
			   ,[cus_addr_line_1]
			   ,[cus_addr_line_2]
			   ,[cus_addr_line_3]
			   ,[cus_city]
			   ,[cus_province]
			   ,[cus_postal_code]
			   ,[cus_country_code]
			   ,[cus_country_name]
			   ,[cus_contact]
			   ,[cus_phone]
			   ,[cus_fax]
			   ,[cus_email]         
			   ,[create_by]
			   ,[create_date]
			   ,[pick_type]
			   ,[wh_id]
			   ,[owner_code]
			   )
		 VALUES
			   (@v_vchOutboundMasterID
			   ,@in_vchWhMasterID
			   ,@in_vchOutboundOrderNumber
			   ,@in_vchOwnerID
			   ,@v_vchOrderType
			   ,'PICK'
			   ,GETDATE()
			   ,GETDATE()
			   ,@in_vchToWarehouse
			   ,@in_vchCustomerID
			   ,@in_vchCustomerCode
			   ,@v_vchCustomerName
			   ,@v_vchCustomerDesc
			   ,@v_vchAddrLine1
			   ,@v_vchAddrLine2
			   ,@v_vchAddrLine3
			   ,@v_vchCustCity
			   ,@v_vchCustProvince
			   ,@v_vchPostalCode
			   ,@v_vchCountryCode
			   ,@v_vchCountryName
			   ,@v_vchContact
			   ,@v_vchPhone
			   ,@v_vchFax
			   ,@v_vchEmail
			   ,@in_vchUserID
			   ,GETDATE()
			   ,'BLIND PICK'
			   ,@in_vchWarehouse
			   ,@in_vchOwnerCode
			   )
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PICK', update_by = @in_vchUserID, update_date = GETDATE()
			WHERE outbound_order_master_id = @v_vchOutboundMasterID
		END 

	-------------------------------------------------------
	--INSERT PICK MASTER
	-------------------------------------------------------
	SET @v_vchOutboundPickMasterID = NULL
	SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @v_vchOutboundMasterID
	IF (@v_vchOutboundPickMasterID IS NULL)
		BEGIN
			SET @v_vchOutboundPickMasterID = NEWID();
			INSERT INTO [dbo].[t_wms_outbound_pick_master]
				   ([outbound_pick_master_id]
				   ,[wh_master_id]
				   ,[outbound_order_master_id]
				   ,[outbound_order_number]
				   ,[pick_list_number]
				   ,[pick_list_status]
				   ,[create_date]
				   ,[create_by])
			 VALUES
				   (@v_vchOutboundPickMasterID
				   ,@in_vchWhMasterID
				   ,@v_vchOutboundMasterID
				   ,@in_vchOutboundOrderNumber
				   ,@in_vchOutboundOrderNumber
				   ,'PICK'
				   ,GETDATE()
				   ,@in_vchUserID)
		END
		 
	--------------------------------------------------------
	-- Validate Staging Location
	--------------------------------------------------------
	IF (@RuleAutoStaging = 'YES')
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE pickMS.outbound_order_master_id = @v_vchOutboundMasterID
			AND pickDT.staging_location_id IS NOT NULL
				
			IF @v_vchStagingLocationID IS NULL
			BEGIN
				SELECT TOP 1 @v_vchStagingLocationID = location_id
					,@v_vchStagingLocation = location 
				FROM t_wms_location 
				WHERE wh_master_id = @in_vchWhMasterID 
				AND loc_type = 'STG' AND is_active = 'YES'
				IF (@v_vchStagingLocationID IS NULL)
				BEGIN
					SET @out_vchErrorCode = 'STG_LOCATION_NOT_FOUND';
					SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END 
		END

	--Set value
	BEGIN
		IF (@in_vchParentLPN = '')
			SET @in_vchParentLPN = NULL;
		IF (@in_vchLPN = '')
			SET @in_vchLPN = NULL;
		IF (@in_vchLotNumber = '')
			SET @in_vchLotNumber = NULL;
		IF (@in_vchExpiryDate = '')
			SET @in_vchExpiryDate = NULL;
		IF (@in_vchAttribute1 = '')
			SET @in_vchAttribute1 = NULL;
		IF (@in_vchAttribute2 = '')
			SET @in_vchAttribute2 = NULL;
		IF (@in_vchAttribute3 = '')
			SET @in_vchAttribute3 = NULL;
		IF (@in_vchAttribute4 = '')
			SET @in_vchAttribute4 = NULL;
		IF (@in_vchAttribute5 = '')
			SET @in_vchAttribute5 = NULL;
	END

	--------------------------------------------------
	-- Inventory รายการของสินค้าจากที่หยิบมา
	--------------------------------------------------
	DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_dtInvReceiveDate		DATE = NULL
	DECLARE @v_dtInvMfgDate			DATE = NULL
	DECLARE @v_vchInvStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatus			NVARCHAR(50) = NULL
	DECLARE @v_vchInvSerialNumber	NVARCHAR(100) = NULL
	DECLARE @v_fltInvQuantity		FLOAT = NULL
	DECLARE @v_fltInvQuantityPick	FLOAT = NULL
	
	DECLARE InventoryCursor CURSOR FOR	
		SELECT inventory_id
			,attribute_group_id
			,receive_date
			,mfg_date
			,inventory_status_id
			,inv_status
			,serial_number
			,quantity
		FROM v_wms_inventory_data_by_serial_mini
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND inventory_status_id = @in_vchInvStatusID
		AND ISNULL(parent_lpn,'') =  ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'') 
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
		AND ISNULL(expiry_date,'') =ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
		ORDER BY receive_date,serial_number
	OPEN InventoryCursor
	FETCH NEXT FROM InventoryCursor INTO @v_vchInvID, @v_vchInvAttrGroupID,@v_dtInvReceiveDate,@v_dtInvMfgDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchInvSerialNumber,@v_fltInvQuantity
	WHILE @@FETCH_STATUS = 0
		BEGIN
			--Check จำนวนใน Inventory กับจำนวนที่ Pick ถ้าใน Inventory Record นี้จำนวนน้อยกว่า จำนวนที่ Pick = จำนวน Inventory
			IF (@v_fltBaseQuantity > @v_fltInvQuantity)
				BEGIN
					SET @v_fltInvQuantityPick = @v_fltInvQuantity
				END
			ELSE
				BEGIN
					SET @v_fltInvQuantityPick = @v_fltBaseQuantity
				END

			-------------------------------------------------------
			-- Validate Staging Location and set value staging
			-------------------------------------------------------
			IF (@RuleAutoStaging = 'YES')
				BEGIN
					--SET Value Staging
					SET @v_fltQuantityStage = ROUND(@v_fltInvQuantityPick,@Round)
					SET @v_vchStagingParentLPN = @in_vchParentLPN	
					SET @v_vchStagingLPN = @v_vchPickToLPN
				END
			ELSE
				BEGIN
					SET @v_vchStagingLocationID = NULL
					SET @v_vchStagingLocation = NULL
					SET @v_fltQuantityStage = 0	
					SET @v_vchStagingParentLPN = NULL	
					SET @v_vchStagingLPN = NULL
				END

			---------------------------------------------------
			--INSERT/UPDATE OUTBOUND DETAIL
			---------------------------------------------------
			SET @v_vchOutboundDetailID = NULL
			SET @v_vchLineNumber = NULL
			SELECT @v_vchOutboundDetailID = outbound_order_detail_id, @v_vchLineNumber = line_number FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID AND wh_item_master_id = @in_vchWhItemMasterID
			IF (@v_vchOutboundDetailID IS NULL)
				BEGIN
					--Set Line Number
					SELECT @v_vchLineNumber = MAX(line_number) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID
					
					SET @v_vchOutboundDetailID = NEWID();
					IF (@v_vchLineNumber IS NULL)
						BEGIN 
							SET @v_vchLineNumber = '00001'; 
						END
					ELSE
						BEGIN 
							SET @v_vchLineNumber = RIGHT('0000' + CONVERT(NVARCHAR,@v_vchLineNumber + 1),5); 
						END
							
					INSERT INTO [dbo].[t_wms_outbound_detail]
					   ([outbound_order_detail_id]
					   ,[outbound_order_master_id]
					   ,[wh_item_master_id]
					   ,[line_number]
					   ,[quantity_order]					   
					   ,[quantity_pick]
					   ,[quantity_stage]
					   ,[item_uom_id]
					   ,[item_status]
					   ,[item_description]
					   ,[price]
					   ,[grade]
					   ,[default_item_status]
					   ,[create_by]
					   ,[create_date]
					   ,[item_master_id]
					   ,[item_number]
					   ,[uom]
					   )
					VALUES
					   (@v_vchOutboundDetailID
					   ,@v_vchOutboundMasterID
					   ,@in_vchWhItemMasterID
					   ,@v_vchLineNumber
					   ,@v_fltInvQuantityPick					   
					   ,@v_fltInvQuantityPick
					   ,@v_fltQuantityStage
					   ,@v_vchBaseItemUomID
					   ,'PICKED'
					   ,@v_vchItemDesc
					   ,@v_fltPrice
					   ,@v_vchGrade
					   ,@in_vchInvStatus
					   ,@in_vchUserID
					   ,GETDATE()
					   ,@v_vchItemMasterID
					   ,@in_vchItemNumber
					   ,@v_vchBaseUom
					   )
				END
			ELSE
				BEGIN
					UPDATE t_wms_outbound_detail SET 
						 quantity_order = ROUND(ISNULL(quantity_order,0) + @v_fltInvQuantityPick,@Round)
						,quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltInvQuantityPick,@Round)
						,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
					WHERE outbound_order_detail_id = @v_vchOutboundDetailID
				END

			---------------------------------------------------
			-- Get Pick Detail ID
			---------------------------------------------------
			SET @v_vchOutboundPickDetailID = NULL
			SELECT @v_vchOutboundPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
			WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
			AND outbound_order_detail_id = @v_vchOutboundDetailID
			AND location_id = @in_vchLocationID
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
			AND receive_date = @v_dtInvReceiveDate
			AND pick_location_id = @v_vchForkLocationID
			AND ISNULL(pick_to_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
			AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')

			IF (@v_vchSNControl = 'FULL')
				BEGIN
					IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND serial_number = @v_vchInvSerialNumber)
						BEGIN
							SET @out_vchErrorCode = '435';
							SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_IS_PICK_COMPLETE',@in_vchLocalID,@in_vchItemNumber,@v_vchInvSerialNumber,'@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
				END

			-----------------------------------------------------
			-- Insert/Update Pick Detail
			-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ RW to WIP
			-----------------------------------------------------
			IF @v_vchOutboundPickDetailID IS NULL
				BEGIN
					SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
					If (@v_vchPickLineNumber IS NULL)
						BEGIN SET @v_vchPickLineNumber = '00001'; END
					ELSE
						BEGIN SET @v_vchPickLineNumber = RIGHT('0000' + Convert(NVARCHAR,@v_vchPickLineNumber + 1),5); END				
			
					SET @v_vchOutboundPickDetailID = NEWID()
					INSERT INTO [dbo].[t_wms_outbound_pick_detail]
							([outbound_pick_detail_id]
							,[outbound_pick_master_id]
							,[outbound_order_detail_id]
							,[pick_line_number]
							,[location_id]
							,[pick_location_id]
							,[pick_to_lpn]
							,[pick_to_parent_lpn]
							,[wh_item_master_id]
							,[quantity_plan]
							,[quantity_pick] 
							,[quantity_stage]
							,[quantity_pack]
							,[quantity_load]
							,[quantity_ship] 
							,[parent_lpn]
							,[lpn]
							,[lot_number]
							,[expiry_date]
							,[serial_number]
							,[attribute1]
							,[attribute2]
							,[attribute3]
							,[attribute4]
							,[attribute5]
							,[user_assign]
							,[staging_location_id]
							,[staging_parent_lpn]
							,[staging_lpn] 
							,[pick_status]
							,[load_status]
							,[ship_status]
							,[inventory_id]
							,[pack_status]
							,[pick_generate_method]
							,[is_allocate]
							,[is_override] 
							,[is_active]
							,[receive_date]
							,[mfg_date]
							,[start_date_time]
							,[end_date_time]
							,[create_date]
							,[create_by])
						VALUES
							(@v_vchOutboundPickDetailID
							,@v_vchOutboundPickMasterID
							,@v_vchOutboundDetailID
							,@v_vchPickLineNumber
							,@in_vchLocationID
							,@v_vchForkLocationID
							,@v_vchPickToLPN
							,@in_vchParentLPN
							,@in_vchWhItemMasterID
							,ROUND(@v_fltInvQuantityPick,@Round)  --[quantity_plan]
							,ROUND(@v_fltInvQuantityPick,@Round)  --[quantity_pick] 
							,ROUND(@v_fltQuantityStage,@Round) --[quantity_stage]
							,0							 --[quantity_pack]
							,0							 --[quantity_load]
							,0							 --[quantity_ship] 
							,@in_vchParentLPN			 --[parent_lpn]
							,@in_vchlpn					 --[lpn]
							,@in_vchLotNumber			 --[lot_number]
							,@in_vchExpiryDate			--[expiry_date]
							,(CASE @v_vchInvSerialNumber WHEN '' THEN NULL ELSE @v_vchInvSerialNumber END)	--[serial_number]
							,@in_vchAttribute1
							,@in_vchAttribute2
							,@in_vchAttribute3
							,@in_vchAttribute4
							,@in_vchAttribute5
							,NULL						 --[user_assign]
							,@v_vchStagingLocationID	 --[staging_location_id]
							,@v_vchStagingParentLPN		 --[staging_parent_lpn]
							,@v_vchStagingLPN			 --[staging_lpn] 
							,'YES'						 --[pick_status]
							,'NO'						 --[load_status]
							,'NO'						 --[ship_status]
							,@v_vchInvID				 --[inventory_id]
							,'NO'						 --[pack_status]
							,'BLIND_PICK'				 --[pick_generate_method]
							,'YES'						 --[is_allocate]
							,'NO'						 --[is_override] 
							,'YES'						 --[is_active]
							,@v_dtInvReceiveDate
							,@v_dtInvMfgDate
							,@v_dtStartDate				 --[start_date_time]
							,GETDATE()					 --[end_date_time]
							,GETDATE()					 --[create_date]
							,@in_vchUserID)				 --[create_by])
				END
			ELSE
				BEGIN
					UPDATE t_wms_outbound_pick_detail SET 
  						  quantity_plan		 = ROUND(ISNULL(quantity_plan,0) + @v_fltInvQuantityPick,@Round)
						, quantity_pick		 = ROUND(ISNULL(quantity_pick,0) + @v_fltInvQuantityPick,@Round)
						, quantity_stage	 = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
						, pick_location_id   = @v_vchForkLocationID
						, pick_to_parent_lpn = @in_vchParentLPN
						, pick_to_lpn		 = @v_vchPickToLPN
						, pick_status        = 'YES'
						, end_date_time		 = GETDATE()
					WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
				END

			---------------------------------------------------
			--Insert/Update Pack Detail
			---------------------------------------------------
			IF @RulePickPack = 'YES'
				BEGIN
					UPDATE t_wms_outbound_pick_detail SET quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltInvQuantityPick,@Round)
						, end_date_time = GETDATE()
					WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

					---------------------------------------------------
					--Insert/Update Pack Detail
					---------------------------------------------------
					PRINT 'Pick and Pack'
					IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
										WHERE outbound_order_master_id = @v_vchOutboundMasterID
										AND pack_location_id = @v_vchForkLocationID
										AND lpn_pack = @v_vchPickToLPN 
										AND wh_item_master_id = @in_vchWhItemMasterID 
										AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
										AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
						BEGIN
							UPDATE t_wms_outbound_pack_detail SET 
								 quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltInvQuantityPick,@Round)
								,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
							WHERE outbound_order_master_id = @v_vchOutboundMasterID 
							AND pack_location_id = @v_vchForkLocationID
							AND lpn_pack = @v_vchPickToLPN 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
							AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
						END
					ELSE
						BEGIN
							INSERT INTO t_wms_outbound_pack_detail
							(     outbound_order_master_id
								, outbound_pick_detail_id
								, lpn_pack
								, pack_location_id
								, wh_item_master_id
								, quantity_pack
								, quantity_stage
								, lot_number
								, expiry_date
								, serial_number
								, attribute1
								, attribute2
								, attribute3
								, attribute4
								, attribute5
								, item_uom_id
								, staging_parent_lpn
								, staging_lpn
								, staging_location_id
								, create_by
							)
							VALUES
							(     @v_vchOutboundMasterID
								, @v_vchOutboundPickDetailID
								, @v_vchPickToLPN
								, @v_vchForkLocationID
								, @in_vchWhItemMasterID
								, ROUND(@v_fltInvQuantityPick,@Round)
								, ROUND(@v_fltQuantityStage,@Round)
								, @in_vchLotNumber
								, @in_vchExpiryDate
								, @v_vchInvSerialNumber
								, @in_vchAttribute1
								, @in_vchAttribute2
								, @in_vchAttribute3
								, @in_vchAttribute4
								, @in_vchAttribute5
								, @v_vchBaseItemUomID
								, @v_vchStagingParentLPN
								, @v_vchStagingLPN
								, @v_vchStagingLocationID
								, @in_vchUserID
							)
						END
				END
				
			---------------------------------------------------
			--Calculate Volumn & Weight
			---------------------------------------------------
			IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
				BEGIN
					SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltInvQuantityPick,2)
					SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltInvQuantityPick,2)
				END

			---------------------------------------------------
			-- Manage source location data
			---------------------------------------------------
			BEGIN
				--Update Volumn & Weight in from location
				IF @in_vchLocationID IS NOT NULL
					BEGIN
						UPDATE [dbo].[t_wms_location]
							SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
							, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
							, update_date = GETDATE()  
							, [update_by] = @in_vchUserID   
							WHERE [location_id] = @in_vchLocationID
					END

				UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltInvQuantityPick,@Round),@Round)
					,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
					,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
				WHERE inventory_id = @v_vchInvID 
				AND attribute_group_id = @v_vchInvAttrGroupID

				IF (@v_vchSNControl = 'FULL')
					BEGIN
						UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltInvQuantityPick,@Round),@Round) 
						WHERE inventory_id = @v_vchInvID 
						AND attribute_group_id = @v_vchInvAttrGroupID 
						AND attribute_value = @v_vchInvSerialNumber
					END

				IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltInvQuantityPick,@Round),@Round)
						WHERE inventory_id = @v_vchInvID 
						AND attribute_group_id = @v_vchInvAttrGroupID
						AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
					END
			END
			------------------------------------------------
			-- Clear Inventory ที่หยิบของหมดแล้ว
			------------------------------------------------
			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 and inventory_id = @v_vchInvID 
			DELETE FROM t_wms_inventory WHERE quantity <= 0 and inventory_id = @v_vchInvID 
			

			--------------------------------------------
			--Manage Destination inventory
			--------------------------------------------
			SET @v_vchInventoryID = NULL
			SET @v_vchInvAttrGroupID = NULL
			SET @v_fltInvQtyForUpdateLog = 0
			IF (@RuleAutoStaging = 'YES')
				BEGIN
					SELECT @v_vchInventoryID = inventory_id
						,@v_vchInvAttrGroupID = attribute_group_id
						,@v_fltInvQtyForUpdateLog = quantity
					FROM v_wms_inventory_data_by_id
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND location_id = @v_vchStagingLocationID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					and receive_date = @v_dtInvReceiveDate
					AND ISNULL(parent_lpn,'') = ISNULL(@v_vchStagingParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@v_vchStagingLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

					EXEC usp_manage_inventory @in_vchWhMasterID		  = @in_vchWhMasterID
											, @in_vchOwnerID		  = @in_vchOwnerID
											, @in_vchWhItemMasterID	  = @in_vchWhItemMasterID
											, @in_vchLocationID		  = @v_vchStagingLocationID
											, @in_vchStatusID		  = @v_vchInvStatusID
											, @in_vchPalentLPN		  = @v_vchStagingParentLPN
											, @in_vchLPN			  = @v_vchStagingLPN
											, @in_fltQty			  = @v_fltInvQuantityPick
											, @in_fltQtyAllocate	  = 0
											, @in_fltQtyIncoming	  = 0
											, @in_vchInventoryType	  = @in_vchOutboundOrderNumber
											, @in_vchUserID			  = @in_vchUserID
											, @in_vchReceiveDate	  = @v_dtInvReceiveDate
											, @in_dtMFGDate			  = @v_dtInvMfgDate
											, @in_vchInventoryID	  = @v_vchInventoryID OUTPUT
											, @in_vchAttributeGroupID = @v_vchInvAttrGroupID OUTPUT	
											, @in_vchErrorCode		  = @out_vchErrorCode OUTPUT
											, @in_vchMessage		  = @out_vchErrorMsg OUTPUT	

					IF (@out_vchErrorCode <> '0')
						GOTO WRITE_PROC;

					--Update Volumn & Weight in from location
					IF @v_vchStagingLocationID IS NOT NULL
						BEGIN
							UPDATE [dbo].[t_wms_location]
								SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
								, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
								, update_date = GETDATE()  
								, [update_by] = @in_vchUserID   
								WHERE [location_id] = @v_vchStagingLocationID
						END
				END
			ELSE
				BEGIN
					SELECT @v_vchInventoryID = inventory_id
						,@v_vchInvAttrGroupID = attribute_group_id
					FROM v_wms_inventory_data_by_id
					WHERE wh_master_id = @in_vchWhMasterID
					AND owner_id = @in_vchOwnerID
					AND location_id = @v_vchForkLocationID
					AND wh_item_master_id = @in_vchWhItemMasterID
					AND inventory_status_id = @v_vchInvStatusID
					and receive_date = @v_dtInvReceiveDate
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

					EXEC usp_manage_inventory @in_vchWhMasterID		  = @in_vchWhMasterID
											, @in_vchOwnerID		  = @in_vchOwnerID
											, @in_vchWhItemMasterID	  = @in_vchWhItemMasterID
											, @in_vchLocationID		  = @v_vchForkLocationID
											, @in_vchStatusID		  = @v_vchInvStatusID
											, @in_vchPalentLPN		  = @in_vchParentLPN
											, @in_vchLPN			  = @v_vchPickToLPN
											, @in_fltQty			  = @v_fltInvQuantityPick
											, @in_fltQtyAllocate	  = 0
											, @in_fltQtyIncoming	  = 0
											, @in_vchInventoryType	  = @in_vchOutboundOrderNumber
											, @in_vchUserID			  = @in_vchUserID
											, @in_vchReceiveDate	  = @v_dtInvReceiveDate
											, @in_dtMFGDate			  = @v_dtInvMfgDate
											, @in_vchInventoryID	  = @v_vchInventoryID OUTPUT
											, @in_vchAttributeGroupID = @v_vchInvAttrGroupID OUTPUT	
											, @in_vchErrorCode		  = @out_vchErrorCode OUTPUT
											, @in_vchMessage		  = @out_vchErrorMsg OUTPUT	

					IF (@out_vchErrorCode <> '0')
						GOTO WRITE_PROC;

					--Update Volumn & Weight in from location
					IF @v_vchForkLocationID IS NOT NULL
						BEGIN
							UPDATE [dbo].[t_wms_location]
								SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
								, total_weight =  ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
								, update_date = GETDATE()  
								, [update_by] = @in_vchUserID   
								WHERE [location_id] = @v_vchForkLocationID
						END
				END

			--update volumn & weight ของ LPN
			UPDATE t_wms_inventory SET
				 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchInventoryID
			AND attribute_group_id = @v_vchInvAttrGroupID	

			IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					EXEC usp_manage_inventory_attribute 
						  @in_vchLot				= @in_vchLotNumber
						, @in_vchExpiryDate			= @in_vchExpiryDate
						, @in_vchSerialNo			= @v_vchInvSerialNumber
						, @in_vchAttribute1			= @in_vchAttribute1
						, @in_vchAttribute2			= @in_vchAttribute2
						, @in_vchAttribute3			= @in_vchAttribute3
						, @in_vchAttribute4			= @in_vchAttribute4
						, @in_vchAttribute5			= @in_vchAttribute5
						, @in_fltQty				= @v_fltInvQuantityPick
						, @in_fltQtyAllocate		= 0
						, @in_fltQtyIncoming		= 0
						, @in_vchInventoryID		= @v_vchInventoryID
						, @in_vchAttributeGroupID	= @v_vchInvAttrGroupID
						, @in_vchLotControl			= @v_vchLotControl
						, @in_vchSNControl			= @v_vchSNControl
						, @in_vchExpiryDateControl	= @v_vchExpControl
						, @in_vchAttribute1Control	= @v_vchAttribute1Control
						, @in_vchAttribute2Control	= @v_vchAttribute2Control
						, @in_vchAttribute3Control	= @v_vchAttribute3Control
						, @in_vchAttribute4Control	= @v_vchAttribute4Control
						, @in_vchAttribute5Control	= @v_vchAttribute5Control
						, @in_vchUserID				= @in_vchUserID
						, @in_vchErrorCode			= @out_vchErrorCode OUTPUT
						, @in_vchMessage			= @out_vchErrorMsg OUTPUT
	
					IF(@out_vchErrorCode <> '0')
						GOTO WRITE_PROC;
				END
	 
			---------------------------------------------------		
			--Write Tran Log OO_PICK
			--Write Tran Log INV_MOVE TO Staging
			---------------------------------------------------	 
			DECLARE @v_dtDate DATETIME = GETDATE();
			INSERT INTO t_com_tran_log
				( app_id
				, [app_name]
				, tran_type
				, sub_tran_type
				, [description]
				, start_tran_datetime
				, end_tran_datetime
				, warehouse
				, to_warehouse
				, location
				, to_location
				, [owner]
				, to_owner
				, item_number
				, quantity
				, quantity_uom
				, after_quantity
				, after_quantity_uom
				, lot_number
				, after_lot_number
				, [expiry_date]
				, after_expiry_date
				, serial_number
				, [attribute1]
				, [after_attribute1]
				, [attribute2]
				, [after_attribute2]
				, [attribute3]
				, [after_attribute3]
				, [attribute4]
				, [after_attribute4]
				, [attribute5]
				, [after_attribute5]
				, [user_id]
				, reference_number
				, control_number
				, parent_lpn
				, after_parent_lpn
				, lpn
				, after_lpn
				, [status]
				, after_status
				, zone
				, order_number
				, line_number
				, receive_date
				, mfg_date
				, device
				, create_by
				, create_date
			)
			VALUES
			(     @in_vchApplicationID																									
				, @v_vchApplicationName																									
				, 'BLIND_PICK'																											
				, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'MOVE_DEST' ELSE 'SALES_ORDER' END) 											
				, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'Blind Pick by Order [Auto to Staging]' ELSE 'User Picking by Order' END) 	
				, @v_dtDate																												
				, DATEADD(millisecond,2,GETDATE())																						
				, @in_vchWarehouse																										
				, @in_vchWarehouse 																										
				, @in_vchLocation
				, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocation ELSE @in_vchForkLocation END) 							
				, @in_vchOwnerCode																										
				, @in_vchOwnerCode																										
				, @in_vchItemNumber																										
				, ROUND(@v_fltInvQuantityPick,@Round)																					
				, @v_vchBaseUomPrompt																									
				, ROUND(@v_fltInvQtyForUpdateLog + @v_fltInvQuantityPick,@Round)														
				, @v_vchBaseUomPrompt																									
				, @in_vchLotNumber																										
				, @in_vchLotNumber																										
				, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)										
				, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)										
				, @v_vchInvSerialNumber																									
				, @in_vchAttribute1																										
				, @in_vchAttribute1																										
				, @in_vchAttribute2																										
				, @in_vchAttribute2																										
				, @in_vchAttribute3																										
				, @in_vchAttribute3																										
				, @in_vchAttribute4																										
				, @in_vchAttribute4																										
				, @in_vchAttribute5																										
				, @in_vchAttribute5																										
				, @in_vchUserID																											
				, NULL					--reference_number																				
				, NULL					--control_number																				
				, @in_vchParentLPN																										
				, @in_vchParentLPN																										
				, @in_vchLPN																											
				, @v_vchStagingLPN																										
				, @in_vchInvStatus																										
				, @in_vchInvStatus																										
				, NULL					--zone																							
				, @in_vchOutboundOrderNumber																							
				, @v_vchLineNumber																										
				, @v_dtInvReceiveDate																									
				, @v_dtInvMfgDate																										
				, @in_vchDeviceID																										
				, @in_vchUserID																											
				, GETDATE()																												
			) 

			--สำหรับรวมจำนวนที่ pick ของจาก inventory ในแต่ละรอบ
			SET @v_fltSummaryInvPick = @v_fltSummaryInvPick + @v_fltInvQuantityPick

			--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
			SET @v_fltBaseQuantity = @v_fltBaseQuantity - @v_fltInvQuantityPick
			
			--Check จำนวนที่จะ Pick ครบแล้วให้ออก
			IF @v_fltBaseQuantity = 0
				BREAK;

			FETCH NEXT FROM InventoryCursor INTO @v_vchInvID, @v_vchInvAttrGroupID,@v_dtInvReceiveDate,@v_dtInvMfgDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchInvSerialNumber,@v_fltInvQuantity
		END
	CLOSE InventoryCursor
	DEALLOCATE InventoryCursor


	---------------------------------------------------------
	-- Auto Create Inbound Plan and Receipt
	---------------------------------------------------------
	EXEC usp_inbound_insert_order @in_vchApplicationID	     = @in_vchApplicationID
									,@in_vchDeviceID		 = @in_vchDeviceID	
									,@in_vchUserID			 = @in_vchUserID	
									,@in_vchWhMasterID		 = @in_vchWhMasterID
									,@in_vchOrderNumber		 = @in_vchOutboundOrderNumber
									,@in_vchLocation		 = @in_vchLocation
									,@in_vchParentLPN		 = @in_vchParentLPN
									,@in_vchLPN				 = @v_vchPickToLPN
									,@in_vchItemNumber		 = @in_vchItemNumber
									,@in_vchLotNumber		 = @in_vchLotNumber
									,@in_vchExpiryDate		 = @in_vchExpiryDate
									,@in_vchSerialNumber	 = @in_vchSerialNumber
									,@in_fltQuantity		 = @in_fltQuantity
									,@in_vchUOMPrompt		 = @in_vchUOMPrompt
									,@in_vchDefaultItemStatus = @in_vchInvStatus
									,@in_vchAttribute1		 = @in_vchAttribute1
									,@in_vchAttribute2		 = @in_vchAttribute2
									,@in_vchAttribute3		 = @in_vchAttribute3
									,@in_vchAttribute4		 = @in_vchAttribute4
									,@in_vchAttribute5 		 = @in_vchAttribute5
									,@out_vchErrorCode		 = @out_vchErrorCode OUTPUT
									,@out_vchErrorMsg		 = @out_vchErrorMsg OUTPUT
	
	IF (@out_vchErrorCode <> 0)
		BEGIN
			GOTO WRITE_PROC;
		END
	
	SET @out_vchErrorCode = '0';
	SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

	COMMIT TRANSACTION;
	RETURN;
	
---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:					
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
			 
		IF CURSOR_STATUS('global','InventoryCursor') >= -1
			BEGIN
				CLOSE InventoryCursor;
				DEALLOCATE InventoryCursor;
			END
	
		SET @v_dtProcessDateTime = GETDATE()
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchOutboundOrderNumber,
			@in_vchData2 = @in_vchItemNumber,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_vchErrorCode,
			@in_vchMessage = @out_vchErrorMsg
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','InventoryCursor') >= -1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END

	SET @v_dtProcessDateTime = GETDATE()
	SET @out_vchErrorCode = ERROR_NUMBER();
	SET @out_vchErrorMsg = ERROR_MESSAGE();
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchOutboundOrderNumber,
		@in_vchData2 = @in_vchItemNumber,
		@in_vchData3 = NULL,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_vchErrorCode,
		@in_vchMessage = @out_vchErrorMsg
		
	SET @out_vchErrorCode = 'CONTACT_ADMIN';
	SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH

END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_picklist]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
--2020-09-15 : เพื่อ Check Rule ALLOW_ALLOCATE_ITEM_HAS_EXPIRED if value = 'YES' can allocate items has expired
--2021-09-21 : Return lot processing for Modern Trade ปรับ Where Owner เพิ่ม เพราะ Item อาจมีหลาย owner
--2021-11-16 : ปรับเพิ่มเช็ค เรื่อง lot allow in order ของ Modern Trade
*/
CREATE PROCEDURE [dbo].[usp_outbound_generate_picklist]
	@in_vchApplicationID			VARCHAR(40),
	@in_vchReleaseDesc				VARCHAR(50),
	@in_vchWarehouseMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID			UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundOrderDetailID	UNIQUEIDENTIFIER,		
	@in_vchOwnerID					UNIQUEIDENTIFIER = NULL,
	@in_vchWhItemMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID				UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber				NVARCHAR(50) = NULL,
	@in_vchLocationID				UNIQUEIDENTIFIER = NULL,
	@in_vchOldLocation				NVARCHAR(50) = NULL,
	@in_vchParentLPNIsOverride		NVARCHAR(25) = NULL,
	@in_vchParentLPN				NVARCHAR(25) = NULL,
	@in_vchLPN						NVARCHAR(25) = NULL,
	@in_fltQuantity					FLOAT,
	@in_vchUOMPrompt				NVARCHAR(40),
	@in_vchDefaultItemStatus		NVARCHAR(50) = NULL,
	@in_vchSerialNumber				NVARCHAR(100)= NULL,
	@in_vchExpiryDate				NVARCHAR(50)= NULL,
	@in_vchLotNumber				NVARCHAR(100)= NULL,
	@in_vchAttribute1				NVARCHAR(100) = NULL,
	@in_vchAttribute2				NVARCHAR(100) = NULL,
	@in_vchAttribute3				NVARCHAR(100) = NULL,
	@in_vchAttribute4				NVARCHAR(100) = NULL,
	@in_vchAttribute5				NVARCHAR(100) = NULL,
	@in_vchPickRule					NVARCHAR(50) = NULL,
	@in_vchAllowShortPick			VARCHAR(3) = NULL,
	@in_vchCustomerID				UNIQUEIDENTIFIER = NULL,
	@in_vchCustomerCode				NVARCHAR(50) = NULL,
	@in_dtpShipDatePlan				DATETIME = NULL,
	@in_vchZone						NVARCHAR(50) = NULL,
	@in_vchLineNumber				NVARCHAR(10),
	@in_vchDeviceID					NVARCHAR(50),
	@in_vchUserID					NVARCHAR(25),
	@in_vchLoadID					NVARCHAR(50),
	@out_ErrorCode					NVARCHAR(50) OUTPUT,
	@out_ErrorMessage				NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @Round				INT, 
		@v_dtStartDateTime			DATETIME,
		@v_vchApplicationName		NVARCHAR(50) = NULL,
		@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
		@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL, 
		@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
		@v_vchLocation				NVARCHAR(50),
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_vchLineNumber			NVARCHAR(5),
		@v_vchSerialValue			NVARCHAR(100),
		@v_vchLotValue				NVARCHAR(100),
		@v_vchExpiryDateValue		NVARCHAR(100),
		@v_vchAttribute1Value		NVARCHAR(100),
		@v_vchAttribute2Value		NVARCHAR(100),
		@v_vchAttribute3Value		NVARCHAR(100),
		@v_vchAttribute4Value		NVARCHAR(100),
		@v_vchAttribute5Value		NVARCHAR(100),	
		@v_dtReceiveDate			DATE,
		@v_dtMfgDate				DATE,

		@v_vchWhID					NVARCHAR(25),
		@v_vchOwnerCode				NVARCHAR(40),

		--Item Master
		@v_vchLotControl			VARCHAR(5),
		@v_vchSNControl				VARCHAR(5),
		@v_vchExpiryDateControl		VARCHAR(5),
		@v_vchAttribute1Control		VARCHAR(5),
		@v_vchAttribute2Control		VARCHAR(5),
		@v_vchAttribute3Control		VARCHAR(5),
		@v_vchAttribute4Control		VARCHAR(5),
		@v_vchAttribute5Control		VARCHAR(5),

		@cursorInventoryUnfull		CURSOR,
		@cursorInventoryFull		CURSOR,
		@cursorReplenishment		CURSOR,

		@viewName					NVARCHAR(50) = '',
		@dynamicSQL					NVARCHAR(MAX) = '',
		@checkQtySQL				NVARCHAR(MAX) = '',
		@ConditionSQL				NVARCHAR(MAX) = '',
		@DynamicConditionSQL		NVARCHAR(MAX) = '',
		@OrderBySQL					NVARCHAR(200) = '',
		@GroupBySQL					NVARCHAR(500) = '',
		@ConditionPalletFull		NVARCHAR(130),
		@ConditionPalletUnfull		NVARCHAR(130),
		@v_fltInventoryQty			FLOAT = 0,
		@v_fltInvRemainQuantity		FLOAT = 0,
		
		--Outbound
		@v_vchRefOrderNumber		NVARCHAR(50),
		@v_vchOrderType				NVARCHAR(30) = '',
		@v_vchDepartment			NVARCHAR(50) = '',

		-- Modern trade 
		@v_vchAllowMixLot			VARCHAR(3) = 'YES',
		@v_intLotAllowOrder			INT = 9999,
		@v_fltLotCount				INT = 0,
		@v_vchOldLotNumber			NVARCHAR(100)= 'LOT',
		@v_vchControlShelfLife		VARCHAR(3) = 'NO',
		@v_vchCustomerShelfLife		VARCHAR(3) = 'NO',
		@v_vchItemShelfLife			VARCHAR(3) = 'NO',
		@v_fltCustomerShelfLifeDay	INT = 0,
		@v_fltItemShelfLifeDay		INT = 0,
		@v_vchControlNoBackDate		VARCHAR(3) = 'NO',
		@v_vchControlReturnLot		VARCHAR(3) = 'NO',
		@v_vchLastExpiryDate		NVARCHAR(50),
		
		-- For Pallet 
		@v_fltConversionFactor			 FLOAT,
		@v_fltConversionFactorFullPallet FLOAT,
		@v_vchHaveFullPallet		NVARCHAR(30),	--สำหรับบอกว่า Item นี้มีการกำหนด UOM ที่เป็น Full pallet หรือไม่ ไว้ใช้ตอนคำนวนด้วยตอนที่บอกว่าเป็น full หรือไม่เป็น full

		-- สำหรับวนรอบของ Serial ตอน Generate Picklist
		@iLoop						INT = 1,
		@rowCount					INT = 1,  --สำหรับกำหนดรอบที่จะวน ถ้า Serial วนรอบเท่ากับจำนวนที่ release
		@qtyPlan					FLOAT,		

		-- Check จำนวน Full/Unfull Pallet
		@v_fltQtyFull				FLOAT,
		@v_fltQtyUnfull				FLOAT,
		@v_fltInvQtyFull			FLOAT,
		@v_fltInvQtyUnFull			FLOAT,
		@v_fltRemainQtyFull			FLOAT,
		@v_fltRemainQtyUnfull		FLOAT,

		-- Replenishment
		@v_vchDestinationParentLPN	NVARCHAR(25)

BEGIN TRY
	SET @v_dtStartDateTime = GETDATE();
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @v_vchWhID = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWarehouseMasterID
	SELECT TOP 1 @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID
	
	--Get Outbound Order Number, Department 
	SELECT @v_vchRefOrderNumber = outbound_order_number
		, @v_vchDepartment = department
		, @v_vchOrderType = order_type 
	FROM t_wms_outbound_master 
	WHERE outbound_order_master_id = @in_vchOutboundMasterID

	--Get For Modern Trade
	SELECT @v_vchAllowMixLot = allow_mixed_lots_in_order_shipment
		, @v_intLotAllowOrder = lot_allow_order
		, @v_vchControlShelfLife = control_shelf_life
		, @v_vchCustomerShelfLife = customer_shelf_life
		, @v_vchItemShelfLife = item_shelf_life
		, @v_fltCustomerShelfLifeDay = shelf_life_day_remaining
		, @v_vchControlNoBackDate = control_no_back_date
		, @v_vchControlReturnLot = control_returned_lot_processing
	FROM t_wms_customer 
	WHERE customer_id = @in_vchCustomerID
	 
	--Get Item Master ID
	SELECT @v_vchSNControl = sn_control
		,@v_vchLotControl = lot_control
		,@v_vchExpiryDateControl = expiry_date_control
		,@v_vchAttribute1Control = attribute1_control
		,@v_vchAttribute2Control = attribute2_control
		,@v_vchAttribute3Control = attribute3_control
		,@v_vchAttribute4Control = attribute4_control
		,@v_vchAttribute5Control = attribute5_control
	FROM t_wms_item 
	WHERE item_master_id = @in_vchItemMasterID
	AND is_active = 'YES'

	--Get ConversionFactore ของหน่วยที่รับเข้ามา **หาก Plan ไม่ได้กำหนดมาเป็นหน่วยที่เล็กที่สุด
	SELECT @v_fltConversionFactor = conversion_factor 
	FROM t_wms_item_uom  
	WHERE item_master_id = @in_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt
	AND is_active = 'YES'

	--Get conversion factor for full pallet : BOX is unit full pallet
	SET @v_fltConversionFactorFullPallet = NULL
	SELECT @v_fltConversionFactorFullPallet = conversion_factor
	FROM t_wms_item_uom
	WHERE item_master_id = @in_vchItemMasterID 
	AND uom_prompt = (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_FULL_PALLET_UOM' AND is_active = 'YES')
	AND is_active = 'YES'

	IF (@v_fltConversionFactorFullPallet IS NULL)
		BEGIN
			SET @v_fltConversionFactorFullPallet = 1;
			SET @v_vchHaveFullPallet = 'NO'
		END
	ELSE
		BEGIN
			SET @v_vchHaveFullPallet = 'YES'
		END

	--SET จำนวนที่จะรับเข้ามาให้เป็นหน่วยที่เล็กที่สุด
	SET @in_fltQuantity = ROUND((@in_fltQuantity * @v_fltConversionFactor),@Round)

	-- Validate parameter is require?
	IF (ISNULL(@in_vchDefaultItemStatus,'') = '')
		BEGIN
			SET @out_ErrorCode = '301';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'DEFAULT_ITEM_STATUS_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END

	SET @ConditionSQL = ' WHERE wh_master_id = ''' + CAST(@in_vchWarehouseMasterID AS NVARCHAR(36)) + ''''
					  + ' AND wh_item_master_id = ''' + CAST(@in_vchWHItemMasterID AS NVARCHAR(36)) + ''''
					  + ' AND inv_status = ''' + @in_vchDefaultItemStatus + ''''
					  + ' AND owner_id = ''' + CAST(@in_vchOwnerID AS NVARCHAR(36)) + '''';
	
	-- Set condition quantity not 0
	SET @ConditionSQL = @ConditionSQL + ' AND ((quantity + quantity_incoming) - quantity_allocated) > 0 '
	
	-- Set condition for sale item is not expire when rule set allow = 'YES'
	IF @v_vchExpiryDateControl = 'FULL'
	BEGIN
		--2024-10-02 : ยกเลิกการใช้ Rule YES/No ใช้เป็นการ Set Order Type แทน
		----IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'ALLOW_ALLOCATE_ITEM_HAS_EXPIRED' and is_active = 'YES') = 'NO' 

		--2024-10-02 : ถ้า Order Type Not in Rule จะไม่สามารถจ่ายของที่หมดอายุได้
		IF  @v_vchOrderType NOT IN (SELECT VALUE FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_ALLOW_ISSUE_EXPIRED_ITEM' AND is_active = 'YES')
			BEGIN
				SET @ConditionSQL = @ConditionSQL + ' AND ISNULL(EXPIRY_DATE,CONVERT(NVARCHAR,DATEADD(yy,1, getdate()),112)) > CONVERT(NVARCHAR,getdate(),112) '
			END
	END

	--PICK BY LOCATION
	IF @in_vchLocationID IS NOT NULL
		SET @ConditionSQL = @ConditionSQL + ' AND location_id = ''' + CAST(@in_vchLocationID AS NVARCHAR(36)) + ''' ';
	
	-- Next location
	IF (ISNULL(@in_vchOldLocation,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND location <> ''' + @in_vchOldLocation + ''' ';
	
	-- Check and set condition for parent lpn
	IF (ISNULL(@in_vchParentLPNIsOverride,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND parent_lpn <> ''' + @in_vchParentLPNIsOverride + ''' ';

	-- Check and set condition for parent lpn
	IF (ISNULL(@in_vchParentLPN,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND parent_lpn = ''' + @in_vchParentLPN + ''' ';
	
	-- Check and set condition for lpn
	IF (ISNULL(@in_vchLPN,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND lpn = ''' + @in_vchLPN + '''';	

	-- Check and set condition for lot number
	IF (ISNULL(@in_vchLotNumber,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND lot_number =''' + @in_vchLotNumber + '''';

	-- Check and set condition for expiry date
	IF (ISNULL(@in_vchExpiryDate,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND expiry_date =''' + @in_vchExpiryDate + '''';

	-- Check and set condition for serial serial
	IF (ISNULL(@in_vchSerialNumber,'') <> '')
	begin
		SET @ConditionSQL = @ConditionSQL + ' AND serial_number =''' + @in_vchSerialNumber + '''';

		--ถ้าระบุ Serial ต้องเช็คว่ามี picklist อื่นที่มีการจอง SN เดียวกันหรือไม่ ที่ยังไม่ได้หยิบ
		IF EXISTS (SELECT 1 FROM t_wms_outbound_pick_detail WHERE wh_item_master_id = @in_vchWhItemMasterID AND ISNULL(quantity_pick,0) = 0 AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,''))
			BEGIN
				SET @out_ErrorCode = 'ALREADY_ALLOCATED_IN_ANOTHER_ORDER';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
				RETURN;
			END
	END 

	-- Check and set condition for attribute1
	IF (ISNULL(@in_vchAttribute1,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND attribute1 =''' + @in_vchAttribute1 + '''';

	-- Check and set condition for attribute2
	IF (ISNULL(@in_vchAttribute2,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND attribute2 =''' + @in_vchAttribute2 + '''';

	-- Check and set condition for attribute3
	IF (ISNULL(@in_vchAttribute3,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND attribute3 =''' + @in_vchAttribute3 + '''';

	-- Check and set condition for attribute4
	IF (ISNULL(@in_vchAttribute4,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND attribute4 =''' + @in_vchAttribute4 + '''';

	-- Check and set condition for attribute5
	IF (ISNULL(@in_vchAttribute5,'') <> '')
		SET @ConditionSQL = @ConditionSQL + ' AND attribute5 =''' + @in_vchAttribute5 + '''';
	
	-- Modern Trade
	IF (@v_vchItemShelfLife = 'YES')
		BEGIN
			SELECT @v_fltItemShelfLifeDay = shelf_life_day_remaining FROM t_wms_shelf_life WHERE customer_id = @in_vchCustomerID AND item_master_id = @in_vchItemMasterID
		END

	-- Control Shelf life	
	IF @v_vchExpiryDateControl = 'FULL'
	BEGIN
		If (@v_vchControlShelfLife = 'YES')
			BEGIN
				IF (ISNULL(@in_dtpShipDatePlan,'') = '')
					SET @in_dtpShipDatePlan = GETDATE();
				IF (@v_vchCustomerShelfLife = 'YES')
					BEGIN
						--Select DATEADD(d,@v_fltCustomerShelfLifeDay, @in_dtpShipDatePlan)
						SET @ConditionSQL = @ConditionSQL + ' AND EXPIRY_DATE >=''' + CONVERT(NVARCHAR,DATEADD(d,ISNULL(@v_fltCustomerShelfLifeDay,0), @in_dtpShipDatePlan),112) + ''' ';	
					END
				ELSE
					BEGIN
						SET @ConditionSQL = @ConditionSQL + ' AND EXPIRY_DATE >=''' + CONVERT(NVARCHAR,DATEADD(d,ISNULL(@v_fltItemShelfLifeDay,0), @in_dtpShipDatePlan),112) + ''' ';	
					END
			END

		-- Control no back date
		IF (@v_vchControlNoBackDate = 'YES')
			BEGIN
				SELECT @v_vchLastExpiryDate = MAX(last_expiry_date_shipped) FROM t_wms_shelf_life_tran WHERE customer_id = @in_vchCustomerID AND item_master_id = @in_vchItemMasterID and owner_id = @in_vchOwnerID
				IF (ISNULL(@v_vchLastExpiryDate,'') <> '')
					BEGIN 
						SET @ConditionSQL = @ConditionSQL + ' AND EXPIRY_DATE >''' + @v_vchLastExpiryDate + ''' '; 
					END
			END
	END

	-- Control return lot processing
	IF @v_vchLotControl = 'FULL'
	BEGIN
		IF (@v_vchControlReturnLot = 'YES')
			BEGIN
				IF (ISNULL(@in_vchLotNumber,'') <> '')
					BEGIN
						IF EXISTS(SELECT return_id FROM t_wms_return_lot WHERE customer_id = @in_vchCustomerID AND owner_id = @in_vchOwnerID AND item_number = @in_vchItemNumber AND lot_number = @in_vchLotNumber)
							BEGIN
								SET @out_ErrorCode = '302';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CTR_RETURN_LOT_PROCESSING',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCustomerCode,@in_vchItemNumber,@in_vchLotNumber,'@param4','@param5')
								RETURN;
							END
					END
				ELSE
					BEGIN
						DECLARE @SQL NVARCHAR(200)
						IF EXISTS(SELECT TOP 1 lot_number from t_wms_return_lot WHERE customer_id = @in_vchCustomerID AND item_number = @in_vchItemNumber)
							BEGIN
								SET @SQL = ' SELECT lot_number FROM t_wms_return_lot WHERE customer_id = ''' + CAST(@in_vchCustomerID AS NVARCHAR(36)) + ''' AND item_number = ''' + @in_vchItemNumber + ''' AND owner_id = '''+ CAST(@in_vchOwnerID AS NVARCHAR(36))  +'''';
								SET @ConditionSQL = @ConditionSQL + ' AND lot_number NOT IN (' + @SQL + ') ';	
							END
					END
			END
	END
		
	-- SET Order by Pick Rule
	-- 02/09/2015 : ปรับ FEFO ให้ Order by expiry_date ก่อน (เดิม lot,exp.)
	IF (@in_vchPickRule = 'RULE_PICK_BY_PICK_LOCATION')
		SET @OrderBySQL = ' ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';
	IF (@in_vchPickRule = 'RULE_PICK_BY_FIFO')
		SET @OrderBySQL = ' ORDER BY receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';
	IF (@in_vchPickRule = 'RULE_PICK_BY_FEFO')
		SET @OrderBySQL = ' ORDER BY expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';

	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_CONTROL_PICKFACE' AND is_active = 'YES') = 'YES')
		BEGIN
			--ตัวแปลสำหรับ Replenishment
			DECLARE @v_vchRpmInventoryID		UNIQUEIDENTIFIER = null,
					@v_vchRpmAttributeGroupID   UNIQUEIDENTIFIER = null,
					@v_vchRpmInvStatusID		UNIQUEIDENTIFIER = null,
					@v_vchRpmOwnerID			UNIQUEIDENTIFIER = null,
					@v_vchRpmInvType			NVARCHAR(50),   
					@v_vchRpmLocationID		    UNIQUEIDENTIFIER = null,
					@v_vchRpmLocType			NVARCHAR(20),
					@v_vchRpmLPNControl		    NVARCHAR(3),
					@v_vchRpmParentLPN		    NVARCHAR(25),
					@v_vchRpmLPN			    NVARCHAR(25),
					@v_vchRpmItemNumber		    NVARCHAR(100),
					@v_vchRpmLotNumber		    NVARCHAR(100),
					@v_vchRpmExpiryDate		    NVARCHAR(100),
					@v_vchRpmAttribute1		    NVARCHAR(100),
					@v_vchRpmAttribute2		    NVARCHAR(100),
					@v_vchRpmAttribute3		    NVARCHAR(100),
					@v_vchRpmAttribute4		    NVARCHAR(100),
					@v_vchRpmAttribute5		    NVARCHAR(100),
					@v_dtRpmReceiptDate			DATE,
					@v_dtRpmMfgDate				DATE,
					@v_fltRpmInvQuantity	    FLOAT,		--ยอดคงเหลือใน Inventory
					@v_fltQtyCanReplen			FLOAT,		--ยอดทั้งหมดที่จะ release ของ Item
					@v_fltQtyRemainCanReplen	FLOAT,		--ยอดคงเหลือที่จะ release ของ Item
							
					--Item Pickface
					@v_vchDestinationLocationID	UNIQUEIDENTIFIER = null,
					@v_fltMax					FLOAT,
							
					--Destination Inventory
					@v_vchDestInventoryID		UNIQUEIDENTIFIER = null,
					@v_vchDestAttributeGroupID	VARCHAR(40)

			--Get Item Pickface
			SELECT @v_vchDestinationLocationID = location_id
				,@v_fltMax = [max]
			FROM t_wms_item_pickface
			WHERE wh_item_master_id = @in_vchWHItemMasterID

			IF @v_vchDestinationLocationID IS NULL
				BEGIN
					SET @out_ErrorCode = 'INFO-LOCATION-PICKFACE-NOT-FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
					RETURN;
				END

			-- Check ยอดใน Inventory ของ Location [Pickface] ว่ามีของพอที่จะ Generate Pick list หรือไม่?
			SET @v_fltInvRemainQuantity = 0;
			SET @DynamicConditionSQL = ' AND loc_type = ''PICKFACE'''
			SET @dynamicSQL = 'SELECT TOP 1 @v_fltInvRemainQuantity = ((SUM(quantity) + SUM(quantity_incoming)) - SUM(quantity_allocated))
									,@v_vchDestinationParentLPN = ISNULL(parent_lpn,'''')
							   FROM v_wms_inventory_data_for_release '
			SET @GroupBySQL = ' GROUP BY ISNULL(parent_lpn,'''')
							    ORDER BY ((SUM(quantity) + SUM(quantity_incoming)) - SUM(quantity_allocated)) DESC'

			SET @dynamicSQL = @dynamicSQL + @ConditionSQL + @DynamicConditionSQL + @GroupBySQL
							
			EXEC sp_executesql @dynamicSQL,N'@v_fltInvRemainQuantity FLOAT OUTPUT, @v_vchDestinationParentLPN NVARCHAR(25) OUTPUT'
										  ,@v_fltInvRemainQuantity OUTPUT
										  ,@v_vchDestinationParentLPN OUTPUT;

			--ถ้าจำนวน qty_order > qty_max ให้ Error
			IF (@in_fltQuantity > @v_fltMax)
				BEGIN
					SET @out_ErrorCode = 'INFO-CANNOT-RELEASE-PICKFACE-FULL';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')
					RETURN;
				END

			--ถ้าจำนวนของใน Inventory Location Pickface มีไม่พอ ต้อง Create Job Replenishment
			IF (@v_fltInvRemainQuantity < @in_fltQuantity)
				BEGIN
					--SET ยอดที่จะทำ Replenishment
					SET @v_fltQtyRemainCanReplen = @in_fltQuantity

					--เตรียมของใน Inventory เพื่อใช้ Generate Pick List
					--1. Get ของใน Inventory ตาม loc_type ที่สามารถ Pick ได้ (RULE_LOCATION_TYPE_FOR_PICK)
					SET @DynamicConditionSQL = ' AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = ''RULE_LOCATION_TYPE_FOR_PICK'' AND is_active = ''YES'')'

					--Get Source Inventory
					SET @dynamicSQL = 'SELECT inventory_id
										  , attribute_group_id
										  , owner_id
										  , inv_type
										  , location_id
										  , loc_type
										  , lpn_controlled
										  , parent_lpn
										  , lpn
										  , item_number
										  , lot_number
										  , expiry_date
										  , attribute1
										  , attribute2
										  , attribute3
										  , attribute4
										  , attribute5
										  , receive_date
										  , mfg_date
										  , (quantity + quantity_incoming) - quantity_allocated
										  , inventory_status_id
										FROM v_wms_inventory_data_for_release '

					SET @dynamicSQL = @dynamicSQL + @ConditionSQL + @DynamicConditionSQL + @OrderBySQL
					
					SET @DynamicSQL = '	SET @cursorReplenishment = CURSOR FOR ' + @DynamicSQL + ' ; OPEN @cursorReplenishment'
					EXEC sp_executesql @DynamicSQL, N'@cursorReplenishment CURSOR OUTPUT', @cursorReplenishment OUTPUT

					FETCH FROM @cursorReplenishment INTO @v_vchRpmInventoryID
														  , @v_vchRpmAttributeGroupID
														  , @v_vchRpmOwnerID
														  , @v_vchRpmInvType   
														  , @v_vchRpmLocationID 
														  , @v_vchRpmLocType    
														  , @v_vchRpmLPNControl      
														  , @v_vchRpmParentLPN 
														  , @v_vchRpmLPN
														  , @v_vchRpmItemNumber 
														  , @v_vchRpmLotNumber       
														  , @v_vchRpmExpiryDate
														  , @v_vchRpmAttribute1
														  , @v_vchRpmAttribute2
														  , @v_vchRpmAttribute3
														  , @v_vchRpmAttribute4
														  , @v_vchRpmAttribute5
														  , @v_dtRpmReceiptDate
														  , @v_dtRpmMfgDate
														  , @v_fltRpmInvQuantity
														  , @v_vchRpmInvStatusID
														  			
					WHILE @@FETCH_STATUS = 0
						BEGIN
							IF (@v_vchRpmLPNControl = 'YES')
								BEGIN
									--ถ้า Location Control LPN ให้ยกไปทั้ง LPN
									SET @v_fltQtyCanReplen = ROUND(@v_fltRpmInvQuantity,@Round)
								END
							ELSE
								BEGIN
									--ถ้า Location ไม่ Control LPN ให้ยกของไปเท่าที่จะ Release
									IF (@v_fltQtyRemainCanReplen >= @v_fltRpmInvQuantity)
										SET @v_fltQtyCanReplen = ROUND(@v_fltRpmInvQuantity,@Round)
									ELSE
										SET @v_fltQtyCanReplen = ROUND(@v_fltQtyRemainCanReplen,@Round)
								END
							
							--2. Insert replenishment
							--กรณีที่ของใน Pickface ไม่พอ ต้องสร้าง Job Replenishment เพื่อให้นำมาเติมที่ Pickface
							INSERT INTO [dbo].[t_wms_replenishment]
								([replenishment_id]
								,[replenishment_status]
								,[wh_master_id]
								,[owner_id]
								,[ref_order_number]
								,[inventory_status_id]
								,[source_location_id]
								,[destination_location_id]
								,[source_parent_lpn]
								,[destination_parent_lpn]
								,[lpn]
								,[wh_item_master_id]
								,[lot_number]
								,[expiry_date]
								,[attribute1]
								,[attribute2]
								,[attribute3]
								,[attribute4]
								,[attribute5]
								,[quantity_plan]
								,[quantity_move]
								,[create_by]
								,[create_date])
							 VALUES
								(NEWID()
								,'OPEN'
								,@in_vchWarehouseMasterID
								,@in_vchOwnerID
								,@v_vchRefOrderNumber
								,@v_vchRpmInvStatusID
								,@v_vchRpmLocationID		  --source_location_id
								,CASE ISNULL(@v_vchDestinationLocationID,'') WHEN '' THEN NULL ELSE @v_vchDestinationLocationID END  --destination_location_id
								,@v_vchRpmParentLPN			  --source_parent_lpn
								,@v_vchDestinationParentLPN	  --destination_parent_lpn
								,@v_vchRpmLPN
								,@in_vchWHItemMasterID
								,@v_vchRpmLotNumber
								,@v_vchRpmExpiryDate
								,@v_vchRpmAttribute1
								,@v_vchRpmAttribute2
								,@v_vchRpmAttribute3
								,@v_vchRpmAttribute4
								,@v_vchRpmAttribute5
								,@v_fltQtyCanReplen
								,0
								,@in_vchUserID
								,GETDATE())
					
							--3. Insert ของใน Inventory Order by rule
							--3.1 Update qty allocate ของ Inventory ที่จะหยิบของมา
							--Update Source Inventory
							UPDATE t_wms_inventory set quantity_allocated = ROUND((quantity_allocated + @v_fltQtyCanReplen),@Round)
							WHERE inventory_id = @v_vchRpmInventoryID
							AND attribute_group_id = @v_vchRpmAttributeGroupID

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated + @v_fltQtyCanReplen),@Round)
									WHERE inventory_id = @v_vchRpmInventoryID 
									AND attribute_group_id = @v_vchRpmAttributeGroupID
									AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END

							--3.2 Insert Inventory ของ Location Pick Face ยอด quantity_incoming
							--Insert Destination Inventory
							SET @v_vchDestInventoryID = NULL
							SET @v_vchDestAttributeGroupID = NULL
							SELECT @v_vchDestInventoryID = inventory_id
								,@v_vchDestAttributeGroupID = attribute_group_id
							FROM v_wms_inventory_data_mini
							WHERE wh_master_id = @in_vchWarehouseMasterID 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND location_id = @v_vchDestinationLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@v_vchDestinationParentLPN,'') 
							AND ISNULL(lpn,'') = ISNULL(@v_vchRpmLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@v_vchRpmLotNumber,'') 
							AND ISNULL(expiry_date,'') = ISNULL(@v_vchRpmExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@v_vchRpmAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@v_vchRpmAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@v_vchRpmAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@v_vchRpmAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@v_vchRpmAttribute5,'')

							EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchWarehouseMasterID		
													 ,@in_vchOwnerID			= @in_vchOwnerID			
													 ,@in_vchWhItemMasterID		= @in_vchWhItemMasterID	
													 ,@in_vchLocationID			= @v_vchDestinationLocationID		
													 ,@in_vchStatusID			= @v_vchRpmInvStatusID			
													 ,@in_vchPalentLPN			= @v_vchDestinationParentLPN		
													 ,@in_vchLPN				= @v_vchRpmLPN				
													 ,@in_fltQty				= 0				
													 ,@in_fltQtyAllocate		= 0		
													 ,@in_fltQtyIncoming		= @v_fltQtyCanReplen
													 ,@in_vchInventoryType		= @v_vchRpmInvType	
													 ,@in_vchUserID				= @in_vchUserID			
													 ,@in_vchReceiveDate		= @v_dtRpmReceiptDate		
													 ,@in_dtMFGDate				= @v_dtRpmMfgDate			
													 ,@in_vchInventoryID		= @v_vchDestAttributeGroupID OUTPUT
													 ,@in_vchAttributeGroupID	= @v_vchRpmAttributeGroupID OUTPUT
													 ,@in_vchErrorCode			= @out_ErrorCode OUTPUT
													 ,@in_vchMessage			= @out_ErrorMessage OUTPUT 
							IF (@out_ErrorCode <> '0')
								RETURN;	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
										  @in_vchLot				= @v_vchRpmLotNumber
										, @in_vchExpiryDate			= @v_vchRpmExpiryDate
										, @in_vchSerialNo			= NULL --Release  ไม่มี SN 
										, @in_vchAttribute1			= @v_vchRpmAttribute1
										, @in_vchAttribute2			= @v_vchRpmAttribute2
										, @in_vchAttribute3			= @v_vchRpmAttribute3
										, @in_vchAttribute4			= @v_vchRpmAttribute4
										, @in_vchAttribute5			= @v_vchRpmAttribute5
										, @in_fltQty				= 0
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= @v_fltQtyCanReplen
										, @in_vchInventoryID		= @v_vchDestInventoryID
										, @in_vchAttributeGroupID	= @v_vchDestAttributeGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										RETURN;
								END

							--SET ยอดคงเหลือที่จะสามารถ Release ได้อีก
							SET @v_fltQtyRemainCanReplen = @v_fltQtyRemainCanReplen - @v_fltQtyCanReplen

							--Check จำนวนที่สามารถ Release ถ้าครบแล้วก็ไม่ต้องทำต่อ เพื่อไป Create PickList
							--ต้อง Check <= เพราะ กรณีที่ยกไปทั้ง LPN อาจจะเกินยอดที่ต้องการ Release จริง
							IF (@v_fltQtyRemainCanReplen <= 0)
								break;

						FETCH FROM @cursorReplenishment INTO @v_vchRpmInventoryID
														  , @v_vchRpmAttributeGroupID
														  , @v_vchRpmOwnerID
														  , @v_vchRpmInvType   
														  , @v_vchRpmLocationID 
														  , @v_vchRpmLocType    
														  , @v_vchRpmLPNControl      
														  , @v_vchRpmParentLPN 
														  , @v_vchRpmLPN
														  , @v_vchRpmItemNumber 
														  , @v_vchRpmLotNumber       
														  , @v_vchRpmExpiryDate
														  , @v_vchRpmAttribute1
														  , @v_vchRpmAttribute2
														  , @v_vchRpmAttribute3
														  , @v_vchRpmAttribute4
														  , @v_vchRpmAttribute5
														  , @v_dtRpmReceiptDate
														  , @v_dtRpmMfgDate
														  , @v_fltRpmInvQuantity
														  , @v_vchRpmInvStatusID
						END
					CLOSE @cursorReplenishment
					DEALLOCATE @cursorReplenishment

					--Set ค่าอีกครั้งสำหรับไป Generate Picklist
					SET @DynamicConditionSQL = ' AND loc_type = ''PICKFACE'''
				END
		END
	ELSE
		BEGIN
			SET @DynamicConditionSQL = ' AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = ''RULE_LOCATION_TYPE_FOR_PICK'' AND is_active = ''YES'')'
		END
------------------------------------------------------------------------------------------------------
	 
	IF @v_vchSNControl = 'FULL' AND ISNULL(@in_vchSerialNumber,'') <> ''
		BEGIN
			--ถ้า Control Serial และ ระบุ Serial
			SET @viewName = ' v_wms_inventory_data_for_release_by_serial '
		END
	ELSE
		BEGIN
			SET @viewName = ' v_wms_inventory_data_for_release '
		END
	
	IF @v_vchAllowMixLot = 'YES'
		BEGIN
			DECLARE @v_vchStrQueryModernTrade NVARCHAR(MAX) = ''
			DECLARE @v_vchLotString			  NVARCHAR(MAX) = ''
			SET @v_vchStrQueryModernTrade = 'SELECT wh_master_id,owner_id,wh_item_master_id,expiry_date,receive_date,lot_number,pick_sequence,location,ISNULL(parent_lpn,'''') AS parent_lpn, ISNULL(lpn,'''') AS lpn,((quantity + quantity_incoming) - quantity_allocated) AS quantity FROM ' + @viewName + @ConditionSQL + @DynamicConditionSQL
	
			EXEC usp_outbound_modern_trade_allow_mix_lot  @in_vchQueryString	= @v_vchStrQueryModernTrade
														 ,@in_vchPickRule		= @in_vchPickRule
														 ,@in_fltQuantity		= @in_fltQuantity
														 ,@in_intLotAllowOrder	= @v_intLotAllowOrder
														 ,@out_vchLotString		= @v_vchLotString OUTPUT
			

			--ถ้าไม่อนุญาตให้ Short Pick แล้วไม่ได้ lot กลับมาถือว่า Error ไม่พบ Lot ที่จะสามารถจองตามเงื่อนไขได้
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO' OR @in_vchAllowShortPick = 'NO') AND ISNULL(@v_vchLotString,'') = ''
				BEGIN
					SET @out_ErrorCode = 'MODERN_TRADE_NOT_FOUND_LOT_FOR_RELEASE';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
					RETURN;
				END

			IF ISNULL(@v_vchLotString,'') <> ''
				BEGIN
					SET @DynamicConditionSQL = @DynamicConditionSQL + ' AND ISNULL(lot_number,'''') IN (' + @v_vchLotString + ') '
				END 
		END

	SET @checkQtySQL = 'SELECT @v_fltInvRemainQuantity = ISNULL(SUM((quantity + quantity_incoming) - quantity_allocated),0) FROM ' + @viewName;			
	SET @checkQtySQL = @checkQtySQL + @ConditionSQL + @DynamicConditionSQL;
	EXEC sp_executesql @checkQtySQL,N'@v_fltInvRemainQuantity FLOAT OUTPUT',@v_fltInvRemainQuantity OUTPUT;
			
	-- Check short pick rule
	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO' OR @in_vchAllowShortPick = 'NO')
		BEGIN
			IF (ROUND(@v_fltInvRemainQuantity,@Round) < @in_fltQuantity)
				BEGIN
					SET @out_ErrorCode = '303';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_QUANTITY_NOT_ENOUGH',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
					RETURN;
				END
		END
	
	----Get Receive Date
	--BEGIN
	--	DECLARE @v_dtInvReceiveDate			DATE = NULL
	--	DECLARE @v_fltSumInvByReceiveDate	FLOAT = 0

	--	--หาวันที่ Receive Date แรกที่จะจอง
	--	SET @checkQtySQL = 'SELECT TOP 1 @v_dtInvReceiveDate = receive_date FROM ' + @viewName;
	--	SET @checkQtySQL = @checkQtySQL + @ConditionSQL + @DynamicConditionSQL + @OrderBySQL;
	--	EXEC sp_executesql @checkQtySQL,N'@v_dtInvReceiveDate DATE OUTPUT',@v_dtInvReceiveDate OUTPUT;
		
	--	--หายอดรวมในวันที่แรกว่ามีพอหรือไม่
	--	SET @checkQtySQL = 'SELECT @v_fltSumInvByReceiveDate = ISNULL(SUM((quantity + quantity_incoming) - quantity_allocated),0) FROM ' + @viewName;
	--	SET @checkQtySQL = @checkQtySQL + @ConditionSQL + @DynamicConditionSQL + ' AND receive_date = ''' + CONVERT(VARCHAR(12),@v_dtInvReceiveDate) + '''';
	--	EXEC sp_executesql @checkQtySQL,N'@v_fltSumInvByReceiveDate FLOAT OUTPUT',@v_fltSumInvByReceiveDate OUTPUT;
		
	--	--ถ้าของวันที่ Receive มีพอจะต้อง where receive date เพิ่ม เพื่อให้หยิบวันเดียวกัน
	--	IF ROUND(@v_fltSumInvByReceiveDate,@Round) >= ROUND(@in_fltQuantity,@Round)
	--		BEGIN
	--			SET @DynamicConditionSQL = @DynamicConditionSQL + ' AND receive_date = ''' + CONVERT(VARCHAR(12),@v_dtInvReceiveDate) + '''';
	--		END
	--END

	SET @ConditionPalletFull = ' AND ((quantity + quantity_incoming) - quantity_allocated) / ' + CONVERT(NVARCHAR,@v_fltConversionFactorFullPallet) + ' = (CASE '''+ @v_vchHaveFullPallet+''' WHEN ''NO'' THEN 0 ELSE 1 END)';
	SET @ConditionPalletUnfull = ' AND ((quantity + quantity_incoming) - quantity_allocated) / ' + CONVERT(NVARCHAR,@v_fltConversionFactorFullPallet) + ' <> (CASE '''+ @v_vchHaveFullPallet +''' WHEN ''NO'' THEN 0 ELSE 1 END)';

	-- Get Quantity Inventory Full Pallet
	SET @checkQtySQL = 'SELECT @v_fltInvQtyFull = ISNULL(SUM((quantity + quantity_incoming) - quantity_allocated),0) FROM ' + @viewName;	
	SET @checkQtySQL = @checkQtySQL + @ConditionSQL + @ConditionPalletFull + @DynamicConditionSQL
	EXEC sp_executesql @checkQtySQL,N'@v_fltInvQtyFull FLOAT OUTPUT',@v_fltInvQtyFull OUTPUT;

	-- Get Quantity Inventory Unfull Pallet
	SET @checkQtySQL = 'SELECT @v_fltInvQtyUnFull = ISNULL(SUM((quantity + quantity_incoming) - quantity_allocated),0) FROM ' + @viewName;
	SET @checkQtySQL = @checkQtySQL + @ConditionSQL + @ConditionPalletUnfull + @DynamicConditionSQL
	EXEC sp_executesql @checkQtySQL,N'@v_fltInvQtyUnFull FLOAT OUTPUT',@v_fltInvQtyUnFull OUTPUT;

	--SET Qty_Release
	IF @in_fltQuantity < @v_fltConversionFactorFullPallet
		BEGIN
			SET @v_fltQtyFull = 0
			SET @v_fltQtyUnfull = @in_fltQuantity
		END
	ELSE
		BEGIN
			SET @v_fltQtyFull = FLOOR(@in_fltQuantity / @v_fltConversionFactorFullPallet) * @v_fltConversionFactorFullPallet
			SET @v_fltQtyUnfull = ROUND(@in_fltQuantity - @v_fltQtyFull,@Round)
		END
	
	--Set Remain Qty for release
	IF  @v_fltInvQtyFull >= @v_fltQtyFull AND @v_fltInvQtyUnFull >= @v_fltQtyUnfull
		BEGIN
			SET @v_fltRemainQtyFull = @v_fltQtyFull
			SET @v_fltRemainQtyUnfull = @v_fltQtyUnfull
		END
	ELSE IF @v_fltInvQtyFull >= @v_fltQtyFull AND @v_fltInvQtyUnFull < @v_fltQtyUnfull
		BEGIN
			SET @v_fltRemainQtyUnfull = @v_fltInvQtyUnFull
			SET @v_fltRemainQtyFull = (@v_fltQtyFull + (@v_fltQtyUnfull - @v_fltInvQtyUnFull))
		END
	ELSE IF @v_fltInvQtyFull < @v_fltQtyFull AND @v_fltInvQtyUnFull >= @v_fltQtyUnfull
		BEGIN
			SET @v_fltRemainQtyFull	= @v_fltInvQtyFull
			SET @v_fltRemainQtyUnfull = (@v_fltQtyUnfull + (@v_fltQtyFull - @v_fltInvQtyFull))
		END
	ELSE
		BEGIN
			SET @v_fltRemainQtyFull = @v_fltInvQtyFull
			SET @v_fltRemainQtyUnfull = @v_fltInvQtyUnFull
		END

	--Loop Unfull Pallet
	SET @dynamicSQL = 'SELECT location_id
						,location
						,((quantity + quantity_incoming) - quantity_allocated)
						,parent_lpn
						,lpn
						,serial_number
						,lot_number
						,expiry_date
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,inventory_id
						,attribute_group_id
						,receive_date
						,mfg_date
					   FROM ' + @viewName;
	SET @dynamicSQL = @dynamicSQL + @ConditionSQL + @ConditionPalletUnfull + @DynamicConditionSQL + @OrderBySQL;
							
	SET @dynamicSQL = '	SET @cursorInventoryUnfull = CURSOR STATIC FOR ' + @dynamicSQL + ' ; OPEN @cursorInventoryUnfull'
	EXEC sp_executesql @dynamicSQL,N'@cursorInventoryUnfull CURSOR OUTPUT',@cursorInventoryUnfull OUTPUT
	
	FETCH FROM @cursorInventoryUnfull INTO @v_vchLocationID
										  ,@v_vchLocation
										  ,@v_fltInvRemainQuantity
										  ,@v_vchParentLPN
										  ,@v_vchLPN
										  ,@v_vchSerialValue
										  ,@v_vchLotValue
										  ,@v_vchExpiryDateValue
										  ,@v_vchAttribute1Value
										  ,@v_vchAttribute2Value
										  ,@v_vchAttribute3Value
										  ,@v_vchAttribute4Value
										  ,@v_vchAttribute5Value
										  ,@v_vchInventoryID
										  ,@v_vchAttributeGroupID
										  ,@v_dtReceiveDate
										  ,@v_dtMfgDate
	-- cursor for select inventory data un full pallet
	While @@FETCH_STATUS = 0
		BEGIN
			IF (@v_fltRemainQtyUnfull > 0)
				BEGIN
					-- Modern trade
					-- Allowed Mixed lots in order/shipment
					IF (@v_vchAllowMixLot = 'Yes')
						BEGIN
							IF (@v_intLotAllowOrder < @v_fltLotCount + 1)
								BEGIN
									--Maii 2021-11-04 : ปรับเพิ่มถ้า allow mix lot ของ Modern trade ถ้าไม่ allow ให้ short Pick และของยัง release ไม่ครบต้องมี message แจ้งเตือน
									IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO' OR @in_vchAllowShortPick = 'NO')
										BEGIN
										IF ISNULL(@v_fltRemainQtyUnfull,0) <> 0 
											BEGIN
												SET @out_ErrorCode = '303';
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_QUANTITY_NOT_ENOUGH',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
												RETURN;
											END
										END

									SET @out_ErrorCode = '0'
									CLOSE @cursorInventoryUnfull;
									DEALLOCATE @cursorInventoryUnfull;
									RETURN;
								END
							IF (@v_vchOldLotNumber <> @v_vchLotValue)
								SET @v_fltLotCount = @v_fltLotCount + 1;
						END

					-- check stock qty and plan qty
					IF (@v_fltInvRemainQuantity > ROUND(@v_fltRemainQtyUnfull,@Round))
						BEGIN
							SET @v_fltInvRemainQuantity = ROUND(@v_fltRemainQtyUnfull,@Round);
						END

					--ถ้า control serial จะต้องวน insert pick detail ตามจำนวนที่สั่งซื้อ
					SET @iLoop = 1;
					SET @rowCount = 1;
					IF @v_vchSNControl = 'FULL'
						BEGIN
							SET @rowCount = @v_fltInvRemainQuantity;
							SET @qtyPlan = 1;
						END
					ELSE
						BEGIN
							SET @qtyPlan = @v_fltInvRemainQuantity;
						END

					While (@iLoop <= @rowCount)
						BEGIN
							-- select line
							SELECT @v_vchLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
							IF (@v_vchLineNumber IS NULL)
								BEGIN SET @v_vchLineNumber = '00001'; END
							ELSE
								BEGIN SET @v_vchLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchLineNumber + 1),5); END
								
							INSERT INTO t_wms_outbound_pick_detail
								(outbound_pick_master_id
								,outbound_order_detail_id
								,pick_line_number
								,location_id
								,wh_item_master_id
								,quantity_plan
								,parent_lpn
								,lpn
								,serial_number
								,lot_number
								,[expiry_date]
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,inventory_id
								,pick_generate_method
								,receive_date
								,mfg_date
								,create_by)
							VALUES
								(@in_vchOutboundPickMasterID
								,@in_vchOutboundOrderDetailID
								,@v_vchLineNumber
								,@v_vchLocationID
								,@in_vchWHItemMasterID
								,ROUND(@qtyPlan,@Round)
								,@v_vchParentLPN
								,@v_vchLPN
								,(CASE WHEN @in_vchSerialNumber <> '' THEN @v_vchSerialValue ELSE NULL END)
								,@v_vchLotValue
								,@v_vchExpiryDateValue
								,@v_vchAttribute1Value
								,@v_vchAttribute2Value
								,@v_vchAttribute3Value
								,@v_vchAttribute4Value
								,@v_vchAttribute5Value
								,@v_vchInventoryID
								,'SYSTEM_DIRECT'
								,@v_dtReceiveDate
								,@v_dtMfgDate
								,@in_vchUserID)

							-- update quantity allocate in inventory
							UPDATE t_wms_inventory set quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) + ROUND(@qtyPlan,@Round),@Round)
							WHERE inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
								
							-- update quantity allocate in inventory attribute 
							-- สำหรับ Serial นั้นไม่จอง
							UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) + ROUND(@qtyPlan,@Round),@Round)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							SET @iLoop = @iLoop + 1
							SET @v_fltRemainQtyUnfull = ROUND((@v_fltRemainQtyUnfull - @qtyPlan),@Round)

							-----------------------------------------------------------
							-- Write Transaction Log Release Order
							-----------------------------------------------------------
							INSERT INTO t_com_tran_log
								(app_id
								, tran_type
								, sub_tran_type
								, [app_name]
								, [description]
								, start_tran_datetime
								, end_tran_datetime
								, warehouse
								, location
								, owner
								, item_number
								, quantity
								, quantity_uom
								, after_quantity
								, after_quantity_uom
								, lot_number
								, expiry_date
								, serial_number
								, [user_id] 
								, parent_lpn
								, lpn
								, status
								, order_number
								, line_number
								, control_value_1

								-- Add for attibute
								, [after_attribute1]
								, [after_attribute2]
								, [after_attribute3]
								, [after_attribute4]
								, [after_attribute5] 
								, receive_date
								, mfg_date 
								, device
								, create_by)
							VALUES
								( @in_vchApplicationID
								, 'OO_RELEASE'
								, 'RELEASE_ORDER'
								, @v_vchApplicationName
								, @in_vchReleaseDesc + ' (Unfull Loop)'
								, @v_dtStartDateTime
								, GETDATE()
								, @v_vchWhID
								, @v_vchLocation
								, @v_vchOwnerCode
								, @in_vchItemNumber
								, ROUND(@qtyPlan,@Round)
								, @in_vchUOMPrompt
								, ROUND(@qtyPlan,@Round)
								, @in_vchUOMPrompt
								, @v_vchLotValue
								, @v_vchExpiryDateValue
								, (CASE WHEN @in_vchSerialNumber <> '' THEN @v_vchSerialValue ELSE NULL END)
								, @in_vchUserID
								, @v_vchParentLPN
								, @v_vchLPN
								, @in_vchDefaultItemStatus
								, @v_vchRefOrderNumber 
								, @in_vchLineNumber
								, @in_vchOutboundOrderDetailID	--outbound_order_detail_id

								-- Add for attibute
								, @v_vchAttribute1Value
								, @v_vchAttribute2Value
								, @v_vchAttribute3Value
								, @v_vchAttribute4Value
								, @v_vchAttribute5Value
								, @v_dtReceiveDate
								, @v_dtMfgDate
								, @in_vchDeviceID
								, @in_vchUserID)
						END

					if (@v_fltRemainQtyUnfull = 0)
						break;
					SET @v_vchOldLotNumber = @v_vchLotValue;
					FETCH NEXT FROM @cursorInventoryUnfull INTO @v_vchLocationID
															  ,@v_vchLocation
															  ,@v_fltInvRemainQuantity
															  ,@v_vchParentLPN
															  ,@v_vchLPN
															  ,@v_vchSerialValue
															  ,@v_vchLotValue
															  ,@v_vchExpiryDateValue
															  ,@v_vchAttribute1Value
															  ,@v_vchAttribute2Value
															  ,@v_vchAttribute3Value
															  ,@v_vchAttribute4Value
															  ,@v_vchAttribute5Value
															  ,@v_vchInventoryID
															  ,@v_vchAttributeGroupID
															  ,@v_dtReceiveDate
															  ,@v_dtMfgDate
				END
			ELSE
				BREAK;
		END
	CLOSE @cursorInventoryUnfull;
	DEALLOCATE @cursorInventoryUnfull;

	--Loop full Pallet
	SET @dynamicSQL = 'SELECT location_id
						,location
						,((quantity + quantity_incoming) - quantity_allocated)
						,parent_lpn
						,lpn
						,serial_number
						,lot_number
						,expiry_date
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,inventory_id
						,attribute_group_id 
						,receive_date
						,mfg_date
					  FROM ' + @viewName;
	SET @dynamicSQL = @dynamicSQL + @ConditionSQL + @ConditionPalletFull + @DynamicConditionSQL + @OrderBySQL;
							
	SET @dynamicSQL = '	SET @cursorInventoryFull = CURSOR STATIC FOR ' + @dynamicSQL + ' ; OPEN @cursorInventoryFull'
	EXEC sp_executesql @dynamicSQL,N'@cursorInventoryFull CURSOR OUTPUT',@cursorInventoryFull OUTPUT
	
	FETCH FROM @cursorInventoryFull INTO @v_vchLocationID
										  ,@v_vchLocation
										  ,@v_fltInvRemainQuantity
										  ,@v_vchParentLPN
										  ,@v_vchLPN
										  ,@v_vchSerialValue
										  ,@v_vchLotValue
										  ,@v_vchExpiryDateValue
										  ,@v_vchAttribute1Value
										  ,@v_vchAttribute2Value
										  ,@v_vchAttribute3Value
										  ,@v_vchAttribute4Value
										  ,@v_vchAttribute5Value
										  ,@v_vchInventoryID
										  ,@v_vchAttributeGroupID
										  ,@v_dtReceiveDate
										  ,@v_dtMfgDate
	-- cursor for select inventory data full pallet
	WHILE @@FETCH_STATUS = 0
		BEGIN
			IF (@v_fltRemainQtyfull > 0)
				BEGIN
					-- Modern trade
					-- Allowed Mixed lots in order/shipment
					IF (@v_vchAllowMixLot = 'Yes')
						BEGIN
							IF (@v_intLotAllowOrder < @v_fltLotCount + 1)
								BEGIN 
									--Maii 2021-11-04 : ปรับเพิ่มถ้า allow mix lot ของ Modern trade ถ้าไม่ allow ให้ short Pick และของยัง release ไม่ครบต้องมี message แจ้งเตือน
									IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO' OR @in_vchAllowShortPick = 'NO')
										BEGIN
										IF ISNULL(@v_fltRemainQtyfull,0) <> 0 
											BEGIN
												SET @out_ErrorCode = '303';
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO_QUANTITY_NOT_ENOUGH',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,@in_vchSerialNumber,@in_vchExpiryDate,@in_vchLotNumber,@in_vchLPN)
												RETURN;
											END
										END 

									SET @out_ErrorCode = '0'
									CLOSE @cursorInventoryFull;
									DEALLOCATE @cursorInventoryFull;
									RETURN;
								END
							IF (@v_vchOldLotNumber <> @v_vchLotValue)
								SET @v_fltLotCount = @v_fltLotCount + 1;
						END

					-- check stock qty and plan qty
					IF (@v_fltInvRemainQuantity > ROUND(@v_fltRemainQtyfull,@Round))
						BEGIN
							SET @v_fltInvRemainQuantity = ROUND(@v_fltRemainQtyfull,@Round);
						END

					--ถ้า control serial จะต้องวน insert pick detail ตามจำนวนที่สั่งซื้อ
					SET @iLoop = 1;
					SET @rowCount = 1;  --สำหรับกำหนดรอบที่จะวน ถ้า Serial วนรอบเท่ากับจำนวนที่ release
					IF @v_vchSNControl = 'FULL'
						BEGIN
							SET @rowCount = @v_fltInvRemainQuantity
							SET @qtyPlan = 1;
						END
					ELSE
						BEGIN
							SET @qtyPlan = @v_fltInvRemainQuantity;
						END

					While (@iLoop <= @rowCount)
						BEGIN
							-- select line
							SELECT @v_vchLineNumber = max(pick_line_number) FROM t_wms_outbound_pick_detail  WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
							IF (@v_vchLineNumber IS NULL)
								BEGIN SET @v_vchLineNumber = '00001'; END
							ELSE
								BEGIN SET @v_vchLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchLineNumber + 1),5); END
								
							INSERT INTO t_wms_outbound_pick_detail
								(outbound_pick_master_id
								,outbound_order_detail_id
								,pick_line_number
								,location_id
								,wh_item_master_id
								,quantity_plan
								,parent_lpn
								,lpn,serial_number
								,lot_number
								,[expiry_date]
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,inventory_id
								,pick_generate_method
								,receive_date
								,mfg_date
								,create_by)
							VALUES
								(@in_vchOutboundPickMasterID
								,@in_vchOutboundOrderDetailID
								,@v_vchLineNumber
								,@v_vchLocationID
								,@in_vchWHItemMasterID
								,ROUND(@qtyPlan,@Round)
								,@v_vchParentLPN
								,@v_vchLPN
								,(CASE WHEN @in_vchSerialNumber <> '' THEN @v_vchSerialValue ELSE NULL END)
								,@v_vchLotValue
								,@v_vchExpiryDateValue
								,@v_vchAttribute1Value
								,@v_vchAttribute2Value
								,@v_vchAttribute3Value
								,@v_vchAttribute4Value
								,@v_vchAttribute5Value
								,@v_vchInventoryID
								,'SYSTEM_DIRECT'
								,@v_dtReceiveDate
								,@v_dtMfgDate
								,@in_vchUserID)

							-- update quantity allocate in inventory
							UPDATE t_wms_inventory set quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) + ROUND(@qtyPlan,@Round),@Round)
							WHERE inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
								
							-- update quantity allocate in inventory attribute
							-- สำหรับ Serial นั้นไม่ต้อง จอง
							UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) + ROUND(@qtyPlan,@Round),@Round)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							SET @iLoop = @iLoop + 1
							SET @v_fltRemainQtyfull = @v_fltRemainQtyfull - @qtyPlan

							-----------------------------------------------------------
							-- Write Transaction Log Release Order
							-----------------------------------------------------------
							INSERT INTO t_com_tran_log
								(app_id
								, tran_type
								, sub_tran_type
								, [app_name]
								, [description]
								, start_tran_datetime
								, end_tran_datetime
								, warehouse
								, location
								, owner
								, item_number
								, quantity
								, quantity_uom
								, after_quantity
								, after_quantity_uom
								, lot_number
								, expiry_date
								, serial_number
								, [user_id] 
								, parent_lpn
								, lpn
								, status
								, order_number
								, line_number
								, control_value_1

								-- Add for attibute
								, [after_attribute1]
								, [after_attribute2]
								, [after_attribute3]
								, [after_attribute4]
								, [after_attribute5] 
								, receive_date
								, mfg_date 
								, device
								, create_by)
							VALUES
								( @in_vchApplicationID
								, 'OO_RELEASE'
								, 'RELEASE_ORDER'
								, @v_vchApplicationName
								, @in_vchReleaseDesc + ' (Full Loop)'
								, @v_dtStartDateTime
								, GETDATE()
								, @v_vchWhID
								, @v_vchLocation
								, @v_vchOwnerCode
								, @in_vchItemNumber
								, ROUND(@qtyPlan,@Round)
								, @in_vchUOMPrompt
								, ROUND(@qtyPlan,@Round)
								, @in_vchUOMPrompt
								, @v_vchLotValue
								, @v_vchExpiryDateValue
								, (CASE WHEN @in_vchSerialNumber <> '' THEN @v_vchSerialValue ELSE NULL END)
								, @in_vchUserID
								, @v_vchParentLPN
								, @v_vchLPN
								, @in_vchDefaultItemStatus
								, @v_vchRefOrderNumber 
								, @in_vchLineNumber
								, @in_vchOutboundOrderDetailID	--outbound_order_detail_id

								-- Add for attibute
								, @v_vchAttribute1Value
								, @v_vchAttribute2Value
								, @v_vchAttribute3Value
								, @v_vchAttribute4Value
								, @v_vchAttribute5Value
								, @v_dtReceiveDate
								, @v_dtMfgDate
								, @in_vchDeviceID
								, @in_vchUserID)
						END

					IF (@v_fltRemainQtyfull = 0)
						break;
					SET @v_vchOldLotNumber = @v_vchLotValue;
					FETCH NEXT FROM @cursorInventoryFull INTO  @v_vchLocationID
															  ,@v_vchLocation
															  ,@v_fltInvRemainQuantity
															  ,@v_vchParentLPN
															  ,@v_vchLPN
															  ,@v_vchSerialValue
															  ,@v_vchLotValue
															  ,@v_vchExpiryDateValue
															  ,@v_vchAttribute1Value
															  ,@v_vchAttribute2Value
															  ,@v_vchAttribute3Value
															  ,@v_vchAttribute4Value
															  ,@v_vchAttribute5Value
															  ,@v_vchInventoryID
															  ,@v_vchAttributeGroupID
															  ,@v_dtReceiveDate
															  ,@v_dtMfgDate
				END
			ELSE
				BREAK;
		END
	CLOSE @cursorInventoryFull;
	DEALLOCATE @cursorInventoryFull;

	SET @out_ErrorCode = '0';
	
END TRY
BEGIN CATCH
	IF CURSOR_STATUS('global','@@cursorInventoryUnfull') >= -1
		BEGIN
			CLOSE @cursorInventoryUnfull;
			DEALLOCATE @cursorInventoryUnfull;
		END

	IF CURSOR_STATUS('global','@@cursorInventoryFull') >= -1
		BEGIN
			CLOSE @cursorInventoryFull;
			DEALLOCATE @cursorInventoryFull;
		END

	IF CURSOR_STATUS('global','@cursorReplenishment') >= -1
		BEGIN
			CLOSE @cursorReplenishment
			DEALLOCATE @cursorReplenishment
		END

	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();	 
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_running_load_id]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_generate_running_load_id] 
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN 
	SET NOCOUNT ON; 
	BEGIN TRY
		DECLARE @v_dtCreateDate DATETIME = GETDATE()
		DECLARE @v_vchYear		VARCHAR(4)
		DECLARE @v_vchMonth		VARCHAR(2)
		DECLARE @v_vchDay		VARCHAR(2) 
		DECLARE @v_vchPrefix	NVARCHAR(5)
		DECLARE @v_vchSuffix	NVARCHAR(5)
		DECLARE @v_vchFormat	NVARCHAR(10)
		DECLARE @v_intRunning	INT
		DECLARE @v_vchRunningID	VARCHAR(40) 
		DECLARE @v_vchLoadID	NVARCHAR(50)

		Select @v_vchYear = RIGHT(DATEPART(YYYY,@v_dtCreateDate),2)
		Select @v_vchMonth = DATEPART(MM,@v_dtCreateDate)
		Select @v_vchDay = DATEPART(DD,@v_dtCreateDate)

		Select @v_vchPrefix = ISNULL(value,'') from t_wms_rule where rule_code = 'PREFIX_OUTBOUND_LOAD_FOR_RUNNING'
		Select @v_vchSuffix = ISNULL(value,'') from t_wms_rule where rule_code = 'SUFFIX_OUTBOUND_LOAD_FOR_RUNNING'
		Select @v_vchFormat = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_OUTBOUND_LOAD_FOR_RUNNING'

		SELECT @v_vchRunningID = running_id
			, @v_intRunning = running 
		FROM t_wms_running_outbound_load 
		WHERE [year] = @v_vchYear 
		AND [month] = @v_vchMonth 
		AND [day] = @v_vchDay

		If (@v_intRunning is null)
			Begin
				Set @v_intRunning = 0;
			End
			
		SET @v_intRunning = @v_intRunning + 1;
		SET @v_vchLoadID = @v_vchPrefix + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
		If (@v_vchRunningID is null)
			Begin
				Set @v_vchRunningID = NEWID();
				INSERT INTO t_wms_running_outbound_load
					(year
					, month
					, day
					, running
					, prefix
					, sufix)
				VALUES
					(@v_vchYear
					,@v_vchMonth
					,@v_vchDay
					,@v_intRunning
					,@v_vchPrefix
					,@v_vchSuffix)
			END
		ELSE
			BEGIN
				UPDATE t_wms_running_outbound_load SET running = @v_intRunning 
				WHERE running_id = @v_vchRunningID
			END

		SET @out_ErrorMessage = '0';
		SELECT @v_vchLoadID AS load_id

	END TRY
	BEGIN CATCH
		SET @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH

END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_running_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-11-27
-- Description:	Generate running Outbound order
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_generate_running_order]
	@in_dtpCreateDate			DATETIME,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN

	SET NOCOUNT ON;

	Begin Try

		Declare
			@v_vchYear			VARCHAR(40),
			@v_vchMonth			NVARCHAR(2),
			@v_vchDay			NVARCHAR(2),

			@v_vchPrefix		NVARCHAR(5),
			@v_vchSuffix		NVARCHAR(5),
			@v_vchFormat		NVARCHAR(10),
			@v_intRunning		INT,
			@v_vchRunningID		VARCHAR(40),

			@v_vchOutboundOrderNumber	NVARCHAR(50)

		Select @v_vchYear = DATEPART(YYYY,@in_dtpCreateDate)
		Select @v_vchMonth = DATEPART(MM,@in_dtpCreateDate)
		Select @v_vchDay = DATEPART(DD,@in_dtpCreateDate)

		Select @v_vchPrefix = ISNULL(value,'') from t_wms_rule where rule_code = 'PREFIX_OUTBOUND_ORDER_FOR_RUNNING'
		Select @v_vchSuffix = ISNULL(value,'') from t_wms_rule where rule_code = 'SUFFIX_OUTBOUND_ORDER_FOR_RUNNING'
		Select @v_vchFormat = ISNULL(value,'0') from t_wms_rule where rule_code = 'FORMAT_OUTBOUND_ORDER_FOR_RUNNING'

		Select @v_vchRunningID = running_id,@v_intRunning = running from t_wms_running_outbound_order where [year] = @v_vchYear and [month] = @v_vchMonth and [day] = @v_vchDay

		If (@v_intRunning is null)
			Begin
				Set @v_intRunning = 0;
			End

		Set @v_intRunning = @v_intRunning + 1;
		SET @v_vchOutboundOrderNumber = @v_vchPrefix + @v_vchYear + RIGHT('00' + @v_vchMonth,2) + RIGHT('00' + @v_vchDay,2) + RIGHT(@v_vchFormat + CONVERT(NVARCHAR,@v_intRunning),LEN(@v_vchFormat)) + @v_vchSuffix;
		
		If (@v_vchRunningID is null)
			Begin
				Set @v_vchRunningID = NEWID();
				Insert into t_wms_running_outbound_order(year, month, day, running, prefix, sufix)
				Values(@v_vchYear,@v_vchMonth,@v_vchDay,@v_intRunning,@v_vchPrefix,@v_vchSuffix)
			End
		Else
			Begin
				Update t_wms_running_outbound_order set running = @v_intRunning where running_id = @v_vchRunningID
			End

		Set @out_ErrorMessage = '0';
		Select @v_vchOutboundOrderNumber as outbound_order_number

	End Try
	Begin Catch
		SET @out_ErrorMessage = ERROR_MESSAGE();
	End Catch

END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_serial_kitting]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-02-20
-- Description:	Generate serial for kitting
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_generate_serial_kitting]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchItemCode			NVARCHAR(50),
	@in_vchWeight			NVARCHAR(50),
	@out_vchSerailNumber	NVARCHAR(50) output,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;

	Declare 
			@v_vchWarehouseMasterID	VARCHAR(40),
			@v_vchOwnerID			VARCHAR(40),
			@v_vchOwnerCode			NVARCHAR(50),
			@v_vchKitWarehouseItemMasterID	VARCHAR(40),-- new kit item for formula
			@v_vchOutboundKitDetailID	VARCHAR(40),
			@v_vchKitItemCode		NVARCHAR(50),
			@v_vchSerialControl		NVARCHAR(5),
			@v_vchLotControl		NVARCHAR(5),
			@v_vchExpiryDateControl	NVARCHAR(5),
			@v_vchKitMasterID		VARCHAR(40),
			@v_vchWeight			NVARCHAR(25),
			@v_vchPrefix			NVARCHAR(10),
			@v_vchRunningCode		NVARCHAR(6),
			@v_fltRunningValue		INT,
			@v_vchSerialNumber		NVARCHAR(50),

			@v_vchItemNumber		NVARCHAR(50),
			@v_fltQuantityPick		FLOAT,
			@v_vchItemUOMID			VARCHAR(40),
			@v_vchUOMPrompt			NVARCHAR(25),
			@v_vchWarehouseItemMasterID	VARCHAR(40),
			@v_vchLocationID		VARCHAR(40),
			@v_vchLocation			NVARCHAR(50),
			@v_vchParentLPN			NVARCHAR(25),
			@v_vchLPN				NVARCHAR(25),
			@v_vchLotNumber			NVARCHAR(50),
			@v_vchExpiryDate		NVARCHAR(50),

			@v_vchInventoryID		VARCHAR(40),
			@v_vchAttributeGroupID	VARCHAR(40),
			@v_vchInventoryStatus	NVARCHAR(50),
			@v_vchInventoryStatusID	VARCHAR(40),
			@v_fltInventoryQuantity	FLOAT,
			@v_vchPrimaryUOM		NVARCHAR(3),
			@v_fltConversionFactor	FLOAT,
			@v_vchReceiveDate		DATE,
			@v_dtProcessDateTime	DATETIME,
			@Round					INT,

			@rowversion  			TIMESTAMP
		

	Begin Try

		select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'

		set @v_vchReceiveDate = convert(char(10), getdate(),126);
		-- Get Warehouse master id
		Select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		-- Get kit master id
		Select @v_vchKitMasterID = kit_master_id,@v_vchKitWarehouseItemMasterID = t_wms_kit_master.wh_item_master_id,
		@v_vchOwnerID = t_wms_kit_master.owner_id,@v_vchWeight = [weight],@v_vchOwnerCode = owner_code
		from t_wms_kit_master inner join t_wms_wh_item on t_wms_kit_master.wh_item_master_id = t_wms_wh_item.wh_item_master_id
		inner join t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
		inner join t_wms_owner on t_wms_kit_master.owner_id = t_wms_owner.owner_id
		where t_wms_kit_master.wh_master_id = @v_vchWarehouseMasterID and item_number = @in_vchItemCode and [weight] = @in_vchWeight

		BEGIN-- 1.Check item maching in formula and item is scaned (by user id(in serial number is null))
			If Exists(
					SELECT dbo.t_wms_item.category_id
					FROM dbo.t_wms_kit_detail 
					INNER JOIN dbo.t_wms_wh_item ON dbo.t_wms_kit_detail.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
					INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id
					WHERE (dbo.t_wms_kit_detail.kit_master_id = @v_vchKitMasterID) 
					AND (dbo.t_wms_item.category_id NOT IN (SELECT t_wms_item_1.category_id
															FROM dbo.t_wms_kit_outbound_detail 
															INNER JOIN dbo.t_wms_wh_item AS t_wms_wh_item_1 ON dbo.t_wms_kit_outbound_detail.wh_item_master_id = t_wms_wh_item_1.wh_item_master_id 
															INNER JOIN dbo.t_wms_item AS t_wms_item_1 ON t_wms_wh_item_1.item_master_id = t_wms_item_1.item_master_id 
															INNER JOIN dbo.t_wms_kit_detail AS t_wms_kit_detail_1 ON dbo.t_wms_kit_outbound_detail.kit_detail_id = t_wms_kit_detail_1.kit_detail_id
															WHERE (dbo.t_wms_kit_outbound_detail.lpn_serial IS NULL) 
															AND (dbo.t_wms_kit_outbound_detail.create_by = @in_vchUserID) 
															AND (dbo.t_wms_kit_detail.kit_master_id = @v_vchKitMasterID)))
					)
				Begin
					set @out_ErrorCode = '101';
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SOME_ITEM_DID_NOT_PICK',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemCode,'@param2','@param3','@param4','@param5')
					return;
				End
			Else-- generate serial for formala
				Begin

					-- Get item information data
					Select	@v_vchKitItemCode = item_number
					 , @v_vchLotControl = lot_control
					 , @v_vchSerialControl = sn_control
					 , @v_vchExpiryDateControl = expiry_date_control
					From t_wms_item 
					inner join t_wms_wh_item on t_wms_item.item_master_id = t_wms_wh_item.item_master_id
					where	wh_item_master_id = @v_vchKitWarehouseItemMasterID
					
					-- [2014-06-20:KRITSADA, Change sequence step with do not insert and update first 
					--Begin Transaction
					--Select
					--	@v_vchPrefix = prefix,
					--	@v_vchRunningCode = running_code,
					--	@v_fltRunningValue = running_value 
					--from t_com_serial_running
					--where prefix = left(@v_vchWeight,1) and running_code = right(convert(nvarchar,getdate(),112),6)
					--If (@v_vchPrefix is null)
					--	Begin
					--		set @v_vchPrefix = left(@v_vchWeight,1)
					--		set @v_vchRunningCode = right(convert(nvarchar,getdate(),112),6)
					--		set @v_fltRunningValue = 0
					--		insert into t_com_serial_running(prefix,running_code, running_value, create_by)
					--		values(@v_vchPrefix,@v_vchRunningCode,@v_fltRunningValue + 1,@in_vchUserID)
					--	End
					--Else
					--	Begin
					--		update t_com_serial_running 
					--		set running_value += 1
					--		where prefix = @v_vchPrefix and running_code = @v_vchRunningCode
					--	End
					--Commit Transaction
					---- serial number is mean lpn in inventory
					--Set @v_vchSerialNumber = @v_vchPrefix + @v_vchRunningCode + right('000' + convert(nvarchar,@v_fltRunningValue + 1),4)
					---- Set SERIAL NUMBER OUTPUT PARAMETER
					--Set @out_vchSerailNumber = @v_vchSerialNumber				

					-- Get inventory status from t_wms_rule
					Select top 1 @v_vchInventoryStatus = value from t_wms_rule where rule_code = 'INVENTORY_STATUS_FOR_KITTING' and is_active = 'YES'
					Select top 1 @v_vchInventoryStatusID = inventory_status_id from t_wms_inventory_status where inv_status = @v_vchInventoryStatus
					
					Declare @loop_count Int = 0
					Declare cursorKitDetail cursor for
						Select	item_number,quantity_pick,t_wms_kit_detail.item_uom_id,t_wms_kit_outbound_detail.wh_item_master_id,
								location_id,parent_lpn,lpn,lot_number,expiry_date,uom_prompt,outbound_kit_detail_id
						from	t_wms_kit_detail 
						INNER JOIN t_wms_kit_outbound_detail on t_wms_kit_detail.kit_detail_id = t_wms_kit_outbound_detail.kit_detail_id
						INNER JOIN t_wms_wh_item on t_wms_kit_outbound_detail.wh_item_master_id = t_wms_wh_item.wh_item_master_id
						INNER JOIN t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
						INNER JOIN t_wms_item_uom on t_wms_kit_detail.item_uom_id = t_wms_item_uom.item_uom_id
						where t_wms_kit_detail.kit_master_id = @v_vchKitMasterID and t_wms_kit_outbound_detail.create_by = @in_vchUserID and lpn_serial is null
					Open cursorKitDetail
					Fetch from cursorKitDetail into @v_vchItemNumber,@v_fltQuantityPick,@v_vchItemUOMID,@v_vchWarehouseItemMasterID
												   ,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate
												   ,@v_vchUOMPrompt,@v_vchOutboundKitDetailID
					
					--Get Location
					Select @v_vchLocation = location from t_wms_location where location_id = @v_vchLocationID
					Begin Transaction
						While @@FETCH_STATUS = 0
							Begin
							    --Get Lpn serial
								-- [2014-06-20:KRITSADA, Change sequence step with inner this begin transaction for able to rollback 
							    If @loop_count = 0
								Begin
									--
									Declare @v_SelectWeight nvarchar(10)

									If left(@v_vchWeight,1) = 'L'
									Begin
										set @v_SelectWeight = convert(nvarchar,left(@v_vchWeight,1)) + convert(nvarchar,right(@v_vchWeight,1))
									End
									Else
									Begin
										set @v_SelectWeight = left(@v_vchWeight,1)
									End

									Select
										@v_vchPrefix = prefix,
										@v_vchRunningCode = running_code,
										@v_fltRunningValue = running_value,
										@rowversion = [rowversion]
									from t_com_serial_running
									where prefix = @v_SelectWeight and running_code = right(convert(nvarchar,getdate(),112),6)
									If (@v_vchPrefix is null)
										Begin
											set @v_vchPrefix = @v_SelectWeight
											set @v_vchRunningCode = right(convert(nvarchar,getdate(),112),6)
											set @v_fltRunningValue = 0
											IF (Select												
													COUNT(*)
												from t_com_serial_running
												where prefix = @v_SelectWeight 
												and running_code = right(convert(nvarchar,getdate(),112),6)
												and running_value = @v_fltRunningValue + 1
												) > 0
												BEGIN
													set @out_ErrorCode = '100';													
													SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERVER_UNAVAILABLE_TRY_AGAIN',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
													goto WRITE_PROC;
												END
												ELSE
												BEGIN
													insert into t_com_serial_running(prefix,running_code, running_value, create_by)
													values(@v_vchPrefix,@v_vchRunningCode,@v_fltRunningValue + 1,@in_vchUserID)
												END										
										End
									Else
										Begin												
											IF @rowversion = (
												Select												
													[rowversion]
												from t_com_serial_running
												where prefix = @v_SelectWeight and running_code = right(convert(nvarchar,getdate(),112),6)
											)	
											BEGIN
												update t_com_serial_running 
												set running_value += 1
												where prefix = @v_vchPrefix and running_code = @v_vchRunningCode and [rowversion] = @rowversion
												IF @@ROWCOUNT = 0
												BEGIN
													set @out_ErrorCode = '100';													
													SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERVER_UNAVAILABLE_TRY_AGAIN',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
													goto WRITE_PROC;
												END
											END
											ELSE
											BEGIN
												set @out_ErrorCode = '100';													
												SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERVER_UNAVAILABLE_TRY_AGAIN',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
												goto WRITE_PROC;
											END										
										End								
									-- serial number is mean lpn in inventory
									Set @v_vchSerialNumber = @v_vchPrefix + @v_vchRunningCode + right('000' + convert(nvarchar,@v_fltRunningValue + 1),4)
									-- Set SERIAL NUMBER OUTPUT PARAMETER
									Set @out_vchSerailNumber = @v_vchSerialNumber
								End
								Set @loop_count = @loop_count + 1
								---
								Set @v_vchInventoryID = null;
								Set @v_vchAttributeGroupID = null;
								Select	@v_vchInventoryID = inventory_id
									, @v_vchAttributeGroupID = attribute_group_id
									, @v_fltInventoryQuantity = quantity
								From v_wms_inventory_data
								where wh_item_master_id = @v_vchWarehouseItemMasterID 
								and location_id = @v_vchLocationID 
								and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'')
								and isnull(lpn,'') = isnull(@v_vchLPN,'') 
								and isnull(lot_number,'') = isnull(@v_vchLotNumber,'') 
								and isnull(expiry_date,'') = isnull(@v_vchExpiryDate,'')
								If (@v_vchInventoryID is null)
									Begin
										set @out_ErrorCode = '102';
										select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_INVENTORY_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemCode,@v_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate)
										goto WRITE_PROC;
									End
								Else-- update source inventory and insert new kit into inventory
									Begin

										-- Check primary uom
										Select @v_vchPrimaryUOM = primary_uom,@v_fltConversionFactor = conversion_factor 
										from t_wms_item_uom where item_uom_id = @v_vchItemUOMID
										If ((@v_vchPrimaryUOM) <> 'YES')
											Begin-- convert to primary uom
												Set @v_fltQuantityPick = @v_fltQuantityPick * @v_fltConversionFactor
											End
										If (@v_fltInventoryQuantity < @v_fltQuantityPick)
											Begin
												set @out_ErrorCode = '103';
												select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLocation,'@param3','@param4','@param5')
												goto WRITE_PROC;
											End

										-- Manage source inventory
										update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltQuantityPick,@Round),@Round)
										--,quantity_allocated -= @v_fltQuantityPick
										where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID

										update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltQuantityPick,@Round),@Round)
										--,quantity_allocated -= @v_fltQuantityPick
										where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID										

										-- Manage destination
										-- Kitting case.Destination inventory not have data.
										Set @v_vchInventoryID = newid();
										Set @v_vchAttributeGroupID = newid();
										insert into t_wms_inventory(inventory_id,wh_master_id, owner_id, wh_item_master_id, location_id, inventory_status_id, inv_type, attribute_group_id, quantity, quantity_allocated,parent_lpn, lpn, receive_date, create_by)
										values(@v_vchInventoryID,@v_vchWarehouseMasterID,@v_vchOwnerID,@v_vchWarehouseItemMasterID,@v_vchLocationID,@v_vchInventoryStatusID,'INVENTORY',@v_vchAttributeGroupID,@v_fltQuantityPick,0,@v_vchParentLPN,@v_vchSerialNumber,@v_vchReceiveDate,@in_vchUserID)
										-- insert new attribute value
										If(@v_vchSerialControl = 'FULL')
											Begin
												insert into t_wms_inventory_attribute(inv_attribute_id, inventory_id, inv_attribute_type_id, attribute_group_id, attribute_value, quantity, quantity_allocated, create_date, create_by)
												values(NewID(),@v_vchInventoryID,(select dbo.usf_get_wms_inventory_attribute_type('SERIAL')),
												@v_vchAttributeGroupID,@v_vchSerialNumber,1,0,getdate(),@in_vchUserID)
											End
										If(@v_vchLotControl = 'FULL')
											Begin
												insert into t_wms_inventory_attribute(inv_attribute_id
													, inventory_id
													, inv_attribute_type_id
													, attribute_group_id
													, attribute_value
													, quantity, quantity_allocated
													, create_date
													, create_by)
												values(NewID()
													,@v_vchInventoryID
													,(select dbo.usf_get_wms_inventory_attribute_type('LOT'))
													, @v_vchAttributeGroupID
													, @v_vchLotNumber   --,convert(nvarchar,getdate(),112) Mai:25/07/2014 ปรับให้ Lot เป็น lot ที่แท้จริง
													,@v_fltQuantityPick
													,0
													,getdate()
													,@in_vchUserID)				
											End
										If(@v_vchExpiryDateControl = 'FULL')
											Begin
												INSERT INTO t_wms_inventory_attribute(inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, create_date
												, create_by)
												VALUES(NewID()
												, @v_vchInventoryID
												, (select dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
												, @v_vchAttributeGroupID
												, CONVERT(NVARCHAR,GETDATE(),112)
												, @v_fltQuantityPick
												, 0
												, GETDATE()
												, @in_vchUserID)				
											End

										-- update serial in kit outbound detail
										update	t_wms_kit_outbound_detail 
										set		lpn_serial = @v_vchSerialNumber,update_by = @in_vchUserID,update_date = getdate()
										where	outbound_kit_detail_id = @v_vchOutboundKitDetailID

										-- insert transaction log
										insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
										start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
										[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
										lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
										reference_number, control_number, lpn, after_lpn,parent_lpn,after_parent_lpn, [status], after_status, zone, order_number, 
										line_number, device, create_by)
										values(@in_vchApplicationID,'OUTBOUND_KITTING','OUTBOUND_KITTING',null,'Kitting',
										GETDATE(),GETDATE(),@in_vchWarehouse,@in_vchWarehouse,@v_vchLocation,@v_vchLocation,
										@v_vchOwnerCode,@v_vchOwnerCode, @v_vchItemNumber,@v_fltQuantityPick,@v_vchUOMPrompt,0,null,
										@v_vchLotNumber,null,@v_vchExpiryDate,null,@v_vchSerialNumber,@in_vchUserID,
										null,null,@v_vchLPN,@v_vchSerialNumber,@v_vchParentLPN,null,@v_vchInventoryStatus,@v_vchInventoryStatus,
										null,null,null,@in_vchDeviceID,@in_vchUserID)

										Fetch next from cursorKitDetail into @v_vchItemNumber,@v_fltQuantityPick,@v_vchItemUOMID,@v_vchWarehouseItemMasterID,@v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchUOMPrompt,@v_vchOutboundKitDetailID
									End
							End

					Close cursorKitDetail
					Deallocate cursorKitDetail
					Commit Transaction
					delete from t_wms_inventory where quantity <= 0 and quantity_allocated <=0
					delete from t_wms_inventory_attribute where quantity <= 0 and quantity_allocated <=0
					set @out_ErrorCode = '0';
					select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

					return;
				End

			Begin -- Write Process Log
			WRITE_PROC:							
			-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0)
					Rollback Transaction;
					
				SET @v_dtProcessDateTime = getdate();

				IF CURSOR_STATUS('global','cursorKitDetail') >= -1
					Begin
						Close cursorKitDetail;
						Deallocate cursorKitDetail;
					End
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = 'usp_outbound_generate_serial_kitting',
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @out_ErrorMessage,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
			End	
		END

	End Try
	Begin Catch
		Begin-- Error
			If (@@TRANCOUNT > 0)
				Rollback Transaction;

			IF CURSOR_STATUS('global','cursorKitDetail') >= -1
				Begin
					Close cursorKitDetail;
					Deallocate cursorKitDetail;
				End

			If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
				Begin
					set @out_ErrorCode = ERROR_NUMBER();
					set @out_ErrorMessage = ERROR_MESSAGE();
				End
		End
	End Catch	
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_user_pick_by_load]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_generate_user_pick_by_load]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,							
	@in_vchLocalID			VARCHAR(40) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@in_vchForkLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchLoadID			NVARCHAR(50)  = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchBoxNumber		NVARCHAR(25) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchItemStatus		NVARCHAR(40) = NULL,	-- มาจาก Plan
	@in_fltQuantity			FLOAT = NULL,
	@in_vchItemUOMID		UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		NVARCHAR(100) = NULL,
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchSerialNumber		NVARCHAR(100) = NULL,	-- ALL หรือส่งค่ามา
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@out_ErrorCode			NVARCHAR(50)  OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_generate_user_pick_by_load]'
	DECLARE @v_vchProcessData			NVARCHAR(500)
	DECLARE @v_dtProcessDateTime		DATETIME
	DECLARE @v_vchApplicationName		NVARCHAR(50)= NULL
	DECLARE @v_vchBeginTrans			BIT = 0
	DECLARE @v_dtStartDate				DATETIME
	DECLARE @RulePickPack				VARCHAR(3) = NULL
	DECLARE @RuleAutoStaging			VARCHAR(3) = NULL
	DECLARE @Round						INT = 0
	DECLARE @v_nCount					INT = 0
	DECLARE @v_vchForkLocation			NVARCHAR(50) = NULL
	
	DECLARE @v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOutboundOrderNumber	NVARCHAR(50) = NULL
	DECLARE @v_vchOrderStatus			NVARCHAR(30) = NULL
	DECLARE @v_vchOrderType				NVARCHAR(30) = NULL
	DECLARE @v_vchPickBy				NVARCHAR(25) = NULL
	DECLARE @v_vchWarehouse				NVARCHAR(25) = NULL
	DECLARE @v_vchOwnerCode				NVARCHAR(50) = NULL
	DECLARE @v_vchLocation				NVARCHAR(50) = NULL

	--Item Master
	DECLARE @v_vchItemMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber			NVARCHAR(50)  = NULL 
	DECLARE @v_vchLotControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpControl			VARCHAR(5) = NULL
	DECLARE @v_vchSNControl				VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control		VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive			VARCHAR(3) = NULL
	DECLARE @v_vchDefaultItemStatusID	UNIQUEIDENTIFIER = NULL

	-- Item UOM 
	DECLARE @v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseUomPrompt			NVARCHAR(40) = NULL
	DECLARE @v_vchInputUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_vchIsPrimaryUOM			NVARCHAR(5)
	DECLARE @v_fltConversionFactor		FLOAT = 0
	DECLARE @v_fltBaseInputQuantity		FLOAT = 0
	DECLARE @v_fltWidth					FLOAT = 0   --item Uom
	DECLARE @v_fltLength				FLOAT = 0   --item Uom
	DECLARE @v_fltHeight				FLOAT = 0   --item Uom
	DECLARE @v_fltGrossWeight			FLOAT = 0   --item Uom
	DECLARE @v_intPercentTolerance		FLOAT = 0   --item Uom
	DECLARE @v_intPercenToleranceWeight FLOAT = 0   --item Uom
	DECLARE @v_fltVolumn				FLOAT = 0 	--item Uom
	DECLARE @v_fltTotalWeight			FLOAT = 0 	--item Uom
			
	-- Inventory
	DECLARE @v_fltChkInvQty				FLOAT
	DECLARE @v_fltChkInvQtyAllocate		FLOAT
	DECLARE @v_fltChkInvQtyRemain		FLOAT --จำนวนคงเหลือใน Inventory ที่สามารถหยิบได้ 
	DECLARE @v_fltChkSumPlanRemainPick	FLOAT --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Load ใน item ที่ scan 	

	-- Outbound Detail 
	DECLARE @v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLineNumber			NVARCHAR(10) = NULL
	DECLARE @v_fltQuantityOrder			FLOAT = 0
	DECLARE @v_fltQuantityPick			FLOAT = 0
	DECLARE	@v_vchPickToLPN				NVARCHAR(25) = NULL

	-- AUTO STG MOD For CBD
	DECLARE @v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchStagingLocation		NVARCHAR(50) = NULL
	DECLARE @v_fltQuantityStage			FLOAT
	DECLARE @v_vchStagingParentLPN		NVARCHAR(25) = NULL
	DECLARE @v_vchStagingLPN			NVARCHAR(25) = NULL

	-- For Serial Case ALL
	DECLARE @v_intStartIndexSN INT = 1
	DECLARE @v_intEndIndexSN   INT = 0
	DECLARE @v_intInvCheck	   FLOAT = 0
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] UNIQUEIDENTIFIER NOT NULL,
		[AttributeGroupID] UNIQUEIDENTIFIER NOT NULL,
		[quantity] [float] NOT NULL,
		[ReceiveDate] DATE NOT NULL,
		[MfgDate] DATE NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)

	BEGIN TRY
		SET @v_dtStartDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
		SELECT TOP 1 @RuleAutoStaging = VALUE FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
		SELECT TOP 1 @v_vchForkLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchForkLocationID AND is_active = 'YES'
		SELECT TOP 1 @v_vchLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		SELECT TOP 1 @v_vchDefaultItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchItemStatus AND is_active = 'YES'
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		
		--ถ้าเป็นการ Pick จาก WEB จะถือว่าเป็นการ Auto STG อัตโนมัติ เนื่องจากใน Para @in_vchForkLocationID จะส่ง location id ของ STG มา
		IF(SELECT loc_type FROM t_wms_location WHERE location_id = @in_vchForkLocationID) = 'STG'
			BEGIN
				SET @RuleAutoStaging = 'YES'
			END 

		-------------------------------------------------
		-- SET Box Number
		-------------------------------------------------
		IF ISNULL(@in_vchBoxNumber,'') = ''
			BEGIN
				SET @in_vchBoxNumber = @in_vchLoadID
			END

		--------------------------------------------------------
		-- Validate Staging Location
		--------------------------------------------------------
		IF (@RuleAutoStaging = 'YES')
			BEGIN
				--Check Old STG = New STG
				SET @v_vchStagingLocationID = NULL
				SET @v_vchStagingLocation = NULL
				SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
					, @v_vchStagingLocation = loc.location 
				FROM t_wms_outbound_pick_detail pickDT
				INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
				INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
				INNER JOIN t_wms_outbound_master obMS ON pickMS.outbound_order_master_id = obMS.outbound_order_master_id
				WHERE obMS.load_id = @in_vchLoadID 
				AND obMS.wh_master_id = @in_vchWhMasterID
				AND pickDT.staging_location_id IS NOT NULL
				
				IF @v_vchStagingLocationID IS NULL
				BEGIN
					SELECT TOP 1 @v_vchStagingLocationID = location_id
						,@v_vchStagingLocation = location 
					FROM t_wms_location
					WHERE wh_master_id = @in_vchWhMasterID 
					AND loc_type = 'STG' AND is_active = 'YES'
					IF (@v_vchStagingLocationID IS NULL)
					BEGIN
						SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
				END 
			END

		------------------------------------------------------
		-- ตรวจสอบ Multiple user pick
		------------------------------------------------------
		IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO') AND (@v_vchPickBy <> @in_vchUserID))
			BEGIN
				--Multi User
				SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get item_master_id
		--------------------------------------------------
		SET @v_vchItemNumber = NULL
		SELECT @v_vchItemMasterID = item.item_master_id
			, @v_vchItemNumber = item.item_number
			, @v_vchLotControl = item.lot_control
			, @v_vchExpControl = item.expiry_date_control
			, @v_vchSNControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
			, @v_vchItemIsActive = item.is_active
		FROM t_wms_item item
 		WHERE owner_id = @in_vchOwnerID
		AND item_master_id = @v_vchItemMasterID
		IF (@v_vchItemNumber IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

			--Check SN หากรับเข้ามาด้วย Tag RFID
		IF @v_vchSNControl = 'FULL'
			BEGIN
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,receive_date
					,mfg_date
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND owner_id = @in_vchOwnerID
				AND location_id = @in_vchLocationID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND inventory_status_id = @v_vchDefaultItemStatusID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) =  (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
				ORDER BY serial_number

				SET @v_intInvCheck = 0
				SELECT @v_intInvCheck = MAX(RowNumber) FROM @tInventorySerial
				IF ISNULL(@v_intInvCheck,0) = 0
					BEGIN
						-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
						SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
						RETURN;
					END
				
				IF EXISTS (SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_master pickMS
							INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
							INNER JOIN t_wms_outbound_master obMS ON pickMS.outbound_order_master_id = obMS.outbound_order_master_id
							WHERE obMS.wh_master_id = @in_vchWhMasterID
							AND obMS.load_id = @in_vchLoadID
							AND pickDT.serial_number IN (SELECT [SerialNumber] FROM @tInventorySerial))
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
						RETURN;
					END
			END

		--------------------------------------------------
		--Get & Check Item UOM
		--------------------------------------------------
		SELECT @v_vchBaseItemUomID	= item_uom_id
			,@v_vchBaseUomPrompt	= uom_prompt
			,@v_vchInputUomPrompt	= uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
			,@v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUOMID		
		AND is_active = 'YES'	
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInputUomPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		--Get Primary Uom
		--------------------------------------------------
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt
					,@v_fltWidth = ISNULL(width,0)
					,@v_fltLength = ISNULL(length,0)
					,@v_fltHeight = ISNULL(height,0)
					,@v_fltGrossWeight = ISNULL(gross_weight,0)
					,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
					,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
	
		--กรณีที่เป็น Serial จะนับจำนวน Serial ทั้งหมด มาตรวจสอบจำนวน
		IF @v_vchSNControl = 'FULL'
			BEGIN
				--------------------------------------------------
				--Set Input Base Qty 
				-- จะต้องกำหนดจำนวน SN ทีจะจ่าย เท่ากับจำนวน Serial ทั้งหมดที่ generate ตาม SN from - To
				--------------------------------------------------
				SET @in_fltQuantity = @v_intInvCheck
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round); 
			END
		ELSE
			BEGIN
				--------------------------------------------------
				--Set Input Base Qty 
				--------------------------------------------------
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
				
				-------------------------------------------------
				-- GET Data From Inventory Not Control Serial
				-------------------------------------------------
				DECLARE @v_fltInvQtyRemain FLOAT = 0 
				SET @v_nCount = 0;
				SELECT @v_nCount = COUNT(inventory_id)
					,@v_fltInvQtyRemain = ROUND(SUM(quantity - ISNULL(quantity_allocated,0)),@ROUND)
				FROM v_wms_inventory_data_by_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND owner_id = @in_vchOwnerID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND location_id = @in_vchLocationID
				AND inventory_status_id = @v_vchDefaultItemStatusID 
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') =  ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') =  ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') =  ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') =  ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') =  ISNULL(@in_vchAttribute5,'')

				IF ISNULL(@v_nCount,0) = 0
					BEGIN
						-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
						SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
						RETURN;
					END

				IF @v_fltBaseInputQuantity > @v_fltInvQtyRemain
					BEGIN
						-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
						SET @out_ErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
						RETURN;
					END
			END
		
		------------------------------------------------------------------------------
		-- เงื่อนไข Plan outbound detail 
		-- ใช้สำหรับตรวจสอบรายการที่จะ pick ว่าตรงกับ Plan หรือไม่กรณีที่มีการกำหนด lpn,lot,exp.
		-- ใช้สำหรับวนลูปเพื่อ Insert/Update Pick List
		-- สำหรับ User Pick ไม่ต้องกำหนด LPN,Lot,Exp ใน plan
		------------------------------------------------------------------------------
		SET @v_nCount = 0;
		SET @v_fltChkSumPlanRemainPick = 0;
		SELECT @v_fltChkSumPlanRemainPick = ROUND(SUM(ISNULL(obDT.quantity_order,0) - ISNULL(obDT.quantity_pick,0)),@ROUND)
			,@v_nCount = COUNT(obdt.outbound_order_detail_id) 
		FROM t_wms_outbound_detail obDT
		inner join t_wms_outbound_master obMS ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
		WHERE obMS.wh_master_id = @in_vchWhMasterID
		AND obMS.load_id = @in_vchLoadID
		AND obDT.wh_item_master_id = @in_vchWhItemMasterID
		AND obDT.default_item_status = @in_vchItemStatus

		--------------------------------------------------
		-- ถ้าไม่พบ Recode ใน OBDT แสดงว่าข้อมูลผิด
		--------------------------------------------------
		IF @v_nCount = 0
			BEGIN
				-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
				SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศูนย์ = ERROR
		--------------------------------------------------
		IF @v_fltChkSumPlanRemainPick = 0
			BEGIN
				-- รายการสินค้า [] หยิบครบแล้ว
				SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- ถ้าจำนวนที่หยิบ > จำนวนคงเหลือที่สามารถหยิบได้ = ERROR
		--------------------------------------------------
		IF @v_fltBaseInputQuantity > @v_fltChkSumPlanRemainPick
			BEGIN
				-- รายการสินค้า [] ไม่สามารถหยิบเกินได้
				SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Check Inventory Qty - Allocate Qty >= Qty Pick
		-------------------------------------------------- 				
		SELECT @v_fltChkInvQty = SUM(quantity)
			,@v_fltChkInvQtyAllocate = SUM(ISNULL(quantity_allocated,0))
			,@v_fltChkInvQtyRemain = ROUND(SUM(ISNULL(quantity,0) - ISNULL(quantity_allocated,0)),@round)
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND inventory_status_id = @v_vchDefaultItemStatusID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		IF @v_fltInvQtyRemain < @v_fltBaseInputQuantity
			BEGIN
				-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
				SET @out_ErrorCode = 'INFO-QTY-MORE-THAN-STOCK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC;
			END

		------------------------------------------------------------
		-- SET pick_to_lpn
		-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
		------------------------------------------------------------
		IF (@v_fltBaseInputQuantity = @v_fltChkInvQty AND @v_fltChkInvQtyAllocate = 0 AND ISNULL(@in_vchLPN,'') <> '')
			BEGIN
				SET @v_vchPickToLPN = @in_vchLPN
			END
		ELSE
			BEGIN
				SET @v_vchPickToLPN = @in_vchBoxNumber
			END

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;

		DECLARE OutboundDetail_Cursor CURSOR FOR
			-------------------------------------------------
			-- Generate Pick Detail
			-- เอาเฉพาะรายการของ outbound detail ที่ยังหยิบไม่ครบ
			-------------------------------------------------
			SELECT obMS.outbound_order_master_id
				,obMS.outbound_order_number
				,obMS.order_type
				,own.owner_code
				,obDT.outbound_order_detail_id
				,obDT.line_number
				,ISNULL(obDT.quantity_order,0)
				,ISNULL(obDT.quantity_pick,0)
			FROM t_wms_outbound_master obMS
			INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
			INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
			WHERE obMS.wh_master_id = @in_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID
			AND obDT.wh_item_master_id = @in_vchWhItemMasterID
			AND obDT.default_item_status = @in_vchItemStatus
			AND ISNULL(obDT.quantity_pick,0) < ISNULL(obDT.quantity_order,0)
			ORDER BY obMS.outbound_order_number, CONVERT(INT,obDT.line_number)
		OPEN OutboundDetail_Cursor
		FETCH NEXT FROM OutboundDetail_Cursor INTO @v_vchOutboundMasterID,@v_vchOutboundOrderNumber,@v_vchOrderType,@v_vchOwnerCode,@v_vchOutboundDetailID,@v_vchLineNumber,@v_fltQuantityOrder,@v_fltQuantityPick
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
			DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchPickLineNumber		NVARCHAR(5)	 = NULL
			DECLARE @v_fltQtyCanPick			FLOAT = 0
			DECLARE @v_fltSummaryInvPick 		FLOAT = 0

			-- Update Outbound Master
			UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID, order_status = 'PICK',update_by = @in_vchUserID, update_date = GETDATE() WHERE outbound_order_master_id = @v_vchOutboundMasterID

			---------------------------------------------------
			-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ
			---------------------------------------------------
			IF ((@v_fltQuantityOrder - @v_fltQuantityPick) > @v_fltBaseInputQuantity)
				SET @v_fltQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
			ELSE
				SET @v_fltQtyCanPick = ROUND((@v_fltQuantityOrder - @v_fltQuantityPick),@Round)

			---------------------------------------------------
			-- Get Pick Master ID
			---------------------------------------------------
			SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @v_vchOutboundMasterID
			IF @v_vchOutboundPickMasterID IS NULL
				BEGIN
					SET @v_vchOutboundPickMasterID = NEWID()
					INSERT INTO [dbo].[t_wms_outbound_pick_master]
						   ([outbound_pick_master_id]
						   ,[wh_master_id]
						   ,[outbound_order_master_id]
						   ,[outbound_order_number]
						   ,[pick_list_number]
						   ,[pick_list_status]
						   ,[create_date]
						   ,[create_by])
					 VALUES
						   (@v_vchOutboundPickMasterID
						   ,@in_vchWhMasterID
						   ,@v_vchOutboundMasterID
						   ,@v_vchOutboundOrderNumber
						   ,@v_vchOutboundOrderNumber
						   ,'PICK' 
						   ,GETDATE()
						   ,@in_vchUserID)
				END
				
			IF @v_vchSNControl = 'FULL'
				BEGIN
					SET @v_fltSummaryInvPick = 0;
					--Index for get serial from - to : ต้องกำหนดเนื่องจากกันกรณีที่เป็น item เดียวกัน 2 line จะต้องแบ่งจำนวน serial 
					SET @v_intEndIndexSN = (@v_fltQtyCanPick + @v_intStartIndexSN) - 1

					--------------------------------------------------------
					-- Validate Staging Location and set value staging
					--------------------------------------------------------
					IF (@RuleAutoStaging = 'YES')
						BEGIN
							--Update Outbound Detail
							UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyCanPick,@Round)
								,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQtyCanPick,@Round)
								,item_status = 'PICK'
								,update_by = @in_vchUserID
								,update_date = GETDATE()
							WHERE outbound_order_master_id = @v_vchOutboundMasterID 
							AND outbound_order_detail_id = @v_vchOutboundDetailID 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND line_number = @v_vchLineNumber

							--SET Value Staging
							SET @v_fltQuantityStage = 1
							SET @v_vchStagingParentLPN = NULL
							SET @v_vchStagingLPN = @v_vchPickToLPN
						END
					ELSE
						BEGIN
							SET @v_vchStagingLocationID = NULL
							SET @v_vchStagingLocation = NULL
							SET @v_fltQuantityStage = 0	
							SET @v_vchStagingParentLPN = NULL	
							SET @v_vchStagingLPN = NULL

							--Update Outbound Detail
							UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltQtyCanPick,@Round),@Round)
								,item_status = 'PICK'
								,update_by = @in_vchUserID
								,update_date = GETDATE()
							WHERE outbound_order_master_id = @v_vchOutboundMasterID 
							AND outbound_order_detail_id = @v_vchOutboundDetailID 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND line_number = @v_vchLineNumber
						END

					IF OBJECT_ID('tempdb..#tSourceInventory') IS NOT NULL
						DROP TABLE #tSourceInventory
					
					SELECT RowNumber
						,InventoryID
						,AttributeGroupID
						,quantity
						,ReceiveDate
						,MfgDate
						,SerialNumber
					INTO #tSourceInventory
					FROM @tInventorySerial
					WHERE RowNumber BETWEEN @v_intStartIndexSN AND @v_intEndIndexSN

					--Set Start Index for next loop
					SET @v_intStartIndexSN = @v_intEndIndexSN + 1

					--Check duplicate serail in pick detail
					IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND wh_item_master_id = @in_vchWhItemMasterID AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
						BEGIN
							SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
							SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
					IF (@v_vchPickLineNumber IS NULL)
						BEGIN
							SET @v_vchPickLineNumber = '00000'; 
						END

					INSERT INTO [dbo].[t_wms_outbound_pick_detail]
							([outbound_pick_detail_id]
							,[outbound_pick_master_id]
							,[outbound_order_detail_id]
							,[pick_line_number]
							,[location_id]
							,[pick_location_id]
							,[pick_to_lpn]
							,[pick_to_parent_lpn]
							,[wh_item_master_id]
							,[quantity_plan]
							,[quantity_pick]
							,[quantity_stage]
							,[quantity_pack]
							,[quantity_load]
							,[quantity_ship]
							,[parent_lpn]
							,[lpn]
							,[lot_number]
							,[expiry_date]
							,[serial_number]
							,[attribute1]
							,[attribute2]
							,[attribute3]
							,[attribute4]
							,[attribute5]
							,[staging_location_id]
							,[staging_parent_lpn]
							,[staging_lpn] 
							,[pick_status]
							,[load_status]
							,[ship_status]
							,[inventory_id]
							,[pack_status]
							,[pick_generate_method]
							,[is_allocate]
							,[is_override] 
							,[receive_date]
							,[mfg_date]
							,[is_active]
							,[start_date_time]
							,[end_date_time]
							,[create_date]
							,[create_by])
						SELECT NEWID()
							,@v_vchOutboundPickMasterID
							,@v_vchOutboundDetailID
							, RIGHT('0000' + CONVERT(NVARCHAR,ISNULL(@v_vchPickLineNumber,0) +  ROW_NUMBER() OVER(ORDER BY SerialNumber)),5) 
							,@in_vchLocationID
							,@in_vchForkLocationID
							,@v_vchPickToLPN
							,@in_vchParentLPN
							,@in_vchWhItemMasterID
							,1	--[quantity_plan]
							,1	--[quantity_pick]
							,(CASE WHEN @RuleAutoStaging = 'YES' THEN 1 ELSE 0 END)	--[quantity_stage]
							,(CASE WHEN @RulePickPack = 'YES' THEN 1 ELSE 0 END)	--[quantity_pack]
							,0										--[quantity_load]
							,0										--[quantity_ship]
							,@in_vchParentLPN						--[parent_lpn]
							,@in_vchlpn								--[lpn]
							,@in_vchLotNumber						--[lot_number]
							,(CASE WHEN @in_vchExpiryDate = '' THEN NULL ELSE @in_vchExpiryDate END) --[expiry_date]
							,SerialNumber
							,@in_vchAttribute1				
							,@in_vchAttribute2
							,@in_vchAttribute3
							,@in_vchAttribute4
							,@in_vchAttribute5
							,@v_vchStagingLocationID			--[staging_location_id]
							,@v_vchStagingParentLPN				--[staging_parent_lpn]
							,@v_vchStagingLPN					--[staging_lpn]
							,'YES'								--[pick_status]
							,'NO'								--[load_status]
							,'NO'								--[ship_status]
							,InventoryID						--[inventory_id]
							,'NO'								--[pack_status]
							,'USER_PICK_LOAD'					--[pick_generate_method]
							,'YES'								--[is_allocate]
							,'NO'								--[is_override] 
							,ReceiveDate
							,MfgDate
							,'YES'								--[is_active]
							,GETDATE()							--[start_date_time]
							,DATEADD(MILLISECOND,RowNumber * 10,GETDATE())						--[end_date_time]
							,DATEADD(MILLISECOND,RowNumber * 10,GETDATE())						--[create_date]
							,@in_vchUserID						--[create_by])
						FROM #tSourceInventory
						ORDER BY RowNumber

					---------------------------------------------------
					--Insert/Update Pack Detail
					---------------------------------------------------
					IF @RulePickPack = 'YES'
						BEGIN
							---------------------------------------------------
							--Insert/Update Pack Detail
							---------------------------------------------------
							PRINT 'Pick and Pack' 
							IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pack_detail 
										WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID 
										AND pack_location_id = @in_vchForkLocationID
										AND lpn_pack = @v_vchPickToLPN 
										AND wh_item_master_id = @in_vchWhItemMasterID 
										AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
							BEGIN
								SET @out_ErrorCode = 'SERIAL_IS_PACK_COMPLETE';
								SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
								 
							INSERT INTO t_wms_outbound_pack_detail
							(     outbound_order_master_id
								, outbound_pick_detail_id
								, lpn_pack
								, pack_location_id
								, wh_item_master_id
								, quantity_pack
								, quantity_stage
								, lot_number
								, expiry_date
								, serial_number
								, [attribute1]
								, [attribute2]
								, [attribute3]
								, [attribute4]
								, [attribute5]
								, item_uom_id
								, staging_parent_lpn
								, staging_lpn
								, staging_location_id
								, create_by
								, create_date
							)
							SELECT @v_vchOutboundMasterID
								, @v_vchOutboundPickDetailID
								, @v_vchPickToLPN
								, @in_vchForkLocationID
								, @in_vchWhItemMasterID
								, 1
								, @v_fltQuantityStage
								, @in_vchLotNumber
								, case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end
								, SerialNumber
								, @in_vchAttribute1
								, @in_vchAttribute2
								, @in_vchAttribute3
								, @in_vchAttribute4
								, @in_vchAttribute5
								, @v_vchBaseItemUomID
								, @v_vchStagingParentLPN
								, @v_vchStagingLPN
								, @v_vchStagingLocationID
								, @in_vchUserID
								, DATEADD(MILLISECOND,RowNumber *10,GETDATE())						--[create_date]
							FROM #tSourceInventory
							ORDER BY RowNumber
						END
				
					---------------------------------------------------
					--Calculate Volumn & Weight
					---------------------------------------------------
					IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
						BEGIN
							SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyCanPick,2)
							SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyCanPick,2)
						END

					--------------------------------------------
					--Manage source inventory
					--------------------------------------------
					BEGIN
						--Update Volumn & Weight in from location
						IF @in_vchLocationID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location]
									SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
									WHERE [location_id] = @in_vchLocationID
							END

						UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(inv.quantity,0) - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
							,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
						FROM t_wms_inventory inv
						INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON inv.inventory_id = tSourceInv.InventoryID
						WHERE inv.inventory_id = tSourceInv.InventoryID 
		
						--Inventory attribute for serial
						IF @v_vchSNControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT * FROM #tSourceInventory) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = tSourceInv.SerialNumber
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END

						--Inventory attribute for lot
						IF @v_vchLotControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchLotNumber
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'LOT' AND is_active = 'YES')
							END

						--Inventory attribute for EXP
						IF @v_vchExpControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchExpiryDate
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 1
						IF @v_vchAttribute1Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute1
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE1' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 2
						IF @v_vchAttribute2Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute2
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE2' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 3
						IF @v_vchAttribute3Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute3
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE3' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 4
						IF @v_vchAttribute4Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute4
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE4' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 5
						IF @v_vchAttribute5Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute5
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE5' AND is_active = 'YES')
							END
						
						DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
						DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
					END
					
					---------------------------------------------------
					--Manage destination location data
					--2019-08-19 : STG ไม่ได้คำนวณ Volumn ตอนตัดเลยไม่ได้ update volumn
					---------------------------------------------------	
					DECLARE @v_dtLoopReceiveDate		DATE = NULL
					DECLARE @v_dtLoopMfgDate			DATE = NULL
					DECLARE @v_fltLoopQtyPick			FLOAT = NULL
					DECLARE @v_vchLoopInventoryID		uniqueidentifier = NULL
					DECLARE @v_vchLoopAttributeGroupID	uniqueidentifier = NULL 
					DECLARE @v_vchLoopToLocationID		uniqueidentifier = NULL
					DECLARE @v_vchLoopToParentLPN		NVARCHAR(25) = NULL
					DECLARE @v_vchLoopToLPN				NVARCHAR(25) = NULL
					IF @RuleAutoStaging = 'YES' 
						BEGIN
							SET @v_vchLoopToLocationID = @v_vchStagingLocationID
							SET @v_vchLoopToParentLPN = @v_vchStagingParentLPN
							SET @v_vchLoopToLPN = @v_vchStagingLPN
						END
					ELSE
						BEGIN
							SET @v_vchLoopToLocationID = @in_vchForkLocationID
							SET @v_vchLoopToParentLPN = NULL
							SET @v_vchLoopToLPN = @v_vchPickToLPN
						END

					DECLARE InventoryDest_Cursor CURSOR FOR
						SELECT ReceiveDate
							,MfgDate
							,SUM(quantity)
						FROM #tSourceInventory
						GROUP BY ReceiveDate,MfgDate
					OPEN InventoryDest_Cursor
					FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate,@v_dtLoopMfgDate, @v_fltLoopQtyPick
	
					WHILE @@FETCH_STATUS = 0
						BEGIN 
							SET @v_vchLoopInventoryID = NULL
							SET @v_vchLoopAttributeGroupID = NULL 
							SELECT @v_vchLoopInventoryID = inventory_id
								,@v_vchLoopAttributeGroupID = attribute_group_id 
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @v_vchLoopToLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @v_vchDefaultItemStatusID
							and receive_date = @v_dtLoopReceiveDate
							AND ISNULL(parent_lpn,'') = ISNULL(@v_vchLoopToParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@v_vchLoopToLPN ,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchWhMasterID
													, @in_vchOwnerID			= @in_vchOwnerID
													, @in_vchWhItemMasterID		= @in_vchWhItemMasterID
													, @in_vchLocationID			= @v_vchLoopToLocationID
													, @in_vchStatusID			= @v_vchDefaultItemStatusID
													, @in_vchPalentLPN			= @v_vchLoopToParentLPN
													, @in_vchLPN				= @v_vchLoopToLPN
													, @in_fltQty				= @v_fltLoopQtyPick
													, @in_fltQtyAllocate		= 0
													, @in_fltQtyIncoming		= 0
													, @in_vchInventoryType		= @v_vchOutboundOrderNumber
													, @in_vchUserID				= @in_vchUserID
													, @in_vchReceiveDate		= @v_dtLoopReceiveDate	
													, @in_dtMFGDate				= @v_dtLoopMfgDate
													, @in_vchInventoryID		= @v_vchLoopInventoryID OUTPUT
													, @in_vchAttributeGroupID	= @v_vchLoopAttributeGroupID OUTPUT	
													, @in_vchErrorCode			= @out_ErrorCode OUTPUT
													, @in_vchMessage			= @out_ErrorMessage OUTPUT	
							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;

							--Insert/Update Attribute
							IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchLoopInventoryID AND attribute_group_id = @v_vchLoopAttributeGroupID)
								BEGIN --Update 
									IF(@v_vchSNControl = 'FULL')
										BEGIN
											IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
														WHERE inventory_id = @v_vchLoopInventoryID 
														AND attribute_group_id = @v_vchLoopAttributeGroupID
														AND attribute_value IN (SELECT SerialNumber FROM #tSourceInventory WHERE ReceiveDate = @v_dtLoopReceiveDate)
														AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
												BEGIN
													SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
													SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
													GOTO WRITE_PROC;
												END

											--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											SELECT NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
												, @v_vchLoopAttributeGroupID
												, SerialNumber
												, 1
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID
											FROM #tSourceInventory
											WHERE ReceiveDate = @v_dtLoopReceiveDate
											ORDER BY SerialNumber 
										END
				
									IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
										BEGIN
											UPDATE t_wms_inventory_attribute SET 
												 quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltLoopQtyPick,@Round),@Round) 
											WHERE inventory_id = @v_vchLoopInventoryID 
											AND attribute_group_id = @v_vchLoopAttributeGroupID
											AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
										END
								END
							ELSE
								BEGIN --Insert
									-- insert new serial
									IF(@v_vchSNControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												(inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											SELECT NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
												, @v_vchLoopAttributeGroupID
												, SerialNumber
												, 1
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID
											FROM #tSourceInventory
											where ReceiveDate = @v_dtLoopReceiveDate
											ORDER BY SerialNumber
										END
							
									--Insert New Lot Number
									IF(@v_vchLotControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
												, @v_vchLoopAttributeGroupID
												, @in_vchLotNumber
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)				
										END

									--Insert New Expiry Date
									IF(@v_vchExpControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
												, @v_vchLoopAttributeGroupID
												, @in_vchExpiryDate
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute1
									IF(@v_vchAttribute1Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute1
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute2
									IF(@v_vchAttribute2Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute2
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute3
									IF(@v_vchAttribute3Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute3
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute4
									IF(@v_vchAttribute4Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute4
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute5
									IF(@v_vchAttribute5Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute5
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END
								END
						 
						FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate, @v_dtLoopMfgDate, @v_fltLoopQtyPick
					END
					CLOSE InventoryDest_Cursor                  	
					DEALLOCATE InventoryDest_Cursor

					---------------------------------------------------		
					--Write Tran Log
					---------------------------------------------------	 
					INSERT INTO t_com_tran_log
						( app_id
						, [app_name]
						, tran_type
						, sub_tran_type 
						, [description]
						, start_tran_datetime
						, end_tran_datetime
						, warehouse
						, to_warehouse
						, location
						, to_location
						, [owner]
						, to_owner
						, item_number
						, quantity
						, quantity_uom
						, after_quantity
						, after_quantity_uom
						, lot_number
						, after_lot_number
						, [expiry_date]
						, after_expiry_date
						, serial_number
						, [attribute1]
						, [after_attribute1]
						, [attribute2]
						, [after_attribute2]
						, [attribute3]
						, [after_attribute3]
						, [attribute4]
						, [after_attribute4]
						, [attribute5]
						, [after_attribute5]
						, [user_id]
						, parent_lpn
						, after_parent_lpn
						, lpn
						, after_lpn
						, [status]
						, after_status
						, order_number
						, line_number
						, receive_date
						, mfg_date
						, device
						, create_by
						, create_date
						, pick_location
						, input_quantity
						, input_uom
					)
					SELECT @in_vchApplicationID
						, @v_vchApplicationName
						, 'OO_PICK'
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'MOVE_DEST' ELSE 'SALES_ORDER' END) 
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'User Picking by Load [Auto to Staging]' ELSE 'User Picking by Load' END) 
						, @v_dtStartDate
						, DATEADD(MILLISECOND,2,GETDATE())
						, @v_vchWarehouse
						, @v_vchWarehouse
						, @v_vchLocation
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocation ELSE @v_vchForkLocation END) 
						, @v_vchOwnerCode
						, @v_vchOwnerCode
						, @v_vchItemNumber
						, 1
						, @v_vchBaseUomPrompt
						, 0
						, @v_vchBaseUomPrompt
						, @in_vchLotNumber
						, @in_vchLotNumber
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, SerialNumber
						, @in_vchAttribute1
						, @in_vchAttribute1
						, @in_vchAttribute2
						, @in_vchAttribute2
						, @in_vchAttribute3
						, @in_vchAttribute3
						, @in_vchAttribute4
						, @in_vchAttribute4
						, @in_vchAttribute5
						, @in_vchAttribute5
						, @in_vchUserID 
						, @in_vchParentLPN
						, @v_vchStagingParentLPN
						, @in_vchLPN
						, @v_vchStagingLPN
						, @in_vchItemStatus
						, @in_vchItemStatus
						, @v_vchOutboundOrderNumber
						, @v_vchLineNumber
						, ReceiveDate
						, MfgDate
						, @in_vchDeviceID
						, @in_vchUserID
						, DATEADD(MILLISECOND,RowNumber * 10,GETDATE())	--[create_date]
						, @v_vchLocation
						, @in_fltQuantity
						, @v_vchInputUomPrompt
					from #tSourceInventory
					ORDER BY RowNumber

					SET @v_fltSummaryInvPick = @v_fltQtyCanPick
					--------------------------------------------------
					--Insert For Checker RFID : เฉพาะที่ AUTO STG
					--------------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES') AND @RuleAutoStaging = 'YES'
						BEGIN
							IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @v_vchOutboundMasterID AND serial_number IN (SELECT SerialNumber FROM #tSourceInventory))
								BEGIN
									INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
										([checker_rfid_id]
										,[processing_status]
										,[outbound_order_master_id]
										,[serial_number]
										,[user_id]
										,[device]
										,[create_by]
										,[create_date])
									SELECT NEWID()
										,'PENDING'
										,@v_vchOutboundMasterID
										,SerialNumber
										,@in_vchUserID
										,@in_vchDeviceID
										,@in_vchUserID
										,GETDATE()
									FROM #tSourceInventory
								END
						END
				END
			ELSE
				BEGIN
					--------------------------------------------------
					-- Inventory รายการของสินค้าจากที่หยิบมา
					--------------------------------------------------
					DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
					DECLARE @v_dtInvReceiveDate		DATE = NULL
					DECLARE @v_dtInvMfgDate			DATE = NULL
					DECLARE @v_fltInvQuantity		FLOAT = NULL
					DECLARE @v_fltInvQuantityPick	FLOAT = NULL
					SET @v_fltSummaryInvPick = 0;

					INVENTORY_NEXT:
						SET @v_vchInvID				= NULL;
						SET @v_vchInvAttrGroupID	= NULL;
						SET @v_dtInvReceiveDate	    = NULL; 
						SET @v_dtInvMfgDate		    = NULL;
						SET @v_fltInvQuantity		= NULL;
						SET @v_fltInvQuantityPick	= NULL;
				
						SELECT TOP 1 @v_vchInvID = inventory_id
							,@v_vchInvAttrGroupID = attribute_group_id
							,@v_dtInvReceiveDate = receive_date  
							,@v_dtInvMfgDate = mfg_date
							,@v_fltInvQuantity = ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round)
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @in_vchWhMasterID
						AND owner_id = @in_vchOwnerID
						AND location_id = @in_vchLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inventory_status_id = @v_vchDefaultItemStatusID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round) > 0
						ORDER BY receive_date
						IF @v_vchInvID IS NULL
							BEGIN
								-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
								SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
								SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
								GOTO WRITE_PROC;
							END
			
						--Check จำนวนใน Inventory กับจำนวนที่ Pick ถ้าใน Inventory Record นี้จำนวนน้อยกว่า จำนวนที่ Pick = จำนวน Inventory
						IF (@v_fltQtyCanPick > @v_fltInvQuantity)
							BEGIN
								SET @v_fltInvQuantityPick = @v_fltInvQuantity
							END
						ELSE
							BEGIN
								SET @v_fltInvQuantityPick = @v_fltQtyCanPick
							END

						---------------------------------------------------
						-- Get Pick Detail ID
						---------------------------------------------------
						SET @v_vchOutboundPickDetailID = NULL
						SELECT @v_vchOutboundPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
						WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
						AND outbound_order_detail_id = @v_vchOutboundDetailID
						AND location_id = @in_vchLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
						AND pick_location_id = @in_vchForkLocationID
						AND ISNULL(pick_to_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
						AND receive_date = @v_dtInvReceiveDate

						--------------------------------------------------------
						-- Validate Staging Location and set value staging
						--------------------------------------------------------
						IF (@RuleAutoStaging = 'YES')
							BEGIN
								--Update Outbound Detail
								UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltInvQuantityPick,@Round)
									,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltInvQuantityPick,@Round)
									,item_status = 'PICK'
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE outbound_order_master_id = @v_vchOutboundMasterID 
								AND outbound_order_detail_id = @v_vchOutboundDetailID 
								AND wh_item_master_id = @in_vchWhItemMasterID 
								AND line_number = @v_vchLineNumber

								--SET Value Staging
								SET @v_fltQuantityStage = ROUND(@v_fltInvQuantityPick,@Round)
								SET @v_vchStagingParentLPN = NULL
								SET @v_vchStagingLPN = @v_vchPickToLPN
							END
						ELSE
							BEGIN
								SET @v_vchStagingLocationID = NULL
								SET @v_vchStagingLocation = NULL
								SET @v_fltQuantityStage = 0	
								SET @v_vchStagingParentLPN = NULL	
								SET @v_vchStagingLPN = NULL
								--Update Outbound Detail
								UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltInvQuantityPick,@Round),@Round)
									,item_status = 'PICK'
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE outbound_order_master_id = @v_vchOutboundMasterID 
								AND outbound_order_detail_id = @v_vchOutboundDetailID 
								AND wh_item_master_id = @in_vchWhItemMasterID 
								AND line_number = @v_vchLineNumber
							END

						-----------------------------------------------------
						-- Insert/Update Pick Detail
						-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ RW to WIP
						-----------------------------------------------------
						IF @v_vchOutboundPickDetailID IS NULL
							BEGIN
								BEGIN--Set Value
									IF (@in_vchParentLPN = '')
										SET @in_vchParentLPN = NULL;
									IF (@in_vchlpn = '')
										SET @in_vchlpn = NULL;
									IF (@in_vchExpiryDate = '')
										SET @in_vchExpiryDate = NULL;
									IF (@in_vchAttribute1 = '')
										SET @in_vchAttribute1 = NULL;
									IF (@in_vchAttribute2 = '')
										SET @in_vchAttribute2 = NULL;
									IF (@in_vchAttribute3 = '')
										SET @in_vchAttribute3 = NULL;
									IF (@in_vchAttribute4 = '')
										SET @in_vchAttribute4 = NULL;
									IF (@in_vchAttribute5 = '')
										SET @in_vchAttribute5 = NULL;
								END

								SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
								IF (@v_vchPickLineNumber IS NULL)
									BEGIN 
										SET @v_vchPickLineNumber = '00001'; 
									END
								ELSE
									BEGIN 
										SET @v_vchPickLineNumber = Right('0000' + Convert(NVARCHAR,@v_vchPickLineNumber + 1),5); 
									END				
			
								SET @v_vchOutboundPickDetailID = NEWID()
								INSERT INTO [dbo].[t_wms_outbound_pick_detail]
										([outbound_pick_detail_id]
										,[outbound_pick_master_id]
										,[outbound_order_detail_id]
										,[pick_line_number]
										,[location_id]
										,[pick_location_id]
										,[pick_to_lpn]
										,[pick_to_parent_lpn]
										,[wh_item_master_id]
										,[quantity_plan]
										,[quantity_pick] 
										,[quantity_stage]
										,[quantity_pack]
										,[quantity_load]
										,[quantity_ship] 
										,[parent_lpn]
										,[lpn]
										,[lot_number]
										,[expiry_date]
										,[serial_number]
										,[attribute1]
										,[attribute2]
										,[attribute3]
										,[attribute4]
										,[attribute5] 
										,[staging_location_id]
										,[staging_parent_lpn]
										,[staging_lpn] 
										,[pick_status]
										,[load_status]
										,[ship_status]
										,[inventory_id]
										,[pack_status]
										,[pick_generate_method]
										,[is_allocate]
										,[is_override]
										,[receive_date]
										,[mfg_date]
										,[is_active]
										,[start_date_time]
										,[end_date_time]
										,[create_date]
										,[create_by])
									VALUES
										(@v_vchOutboundPickDetailID
										,@v_vchOutboundPickMasterID
										,@v_vchOutboundDetailID
										,@v_vchPickLineNumber
										,@in_vchLocationID
										,@in_vchForkLocationID
										,@v_vchPickToLPN
										,@in_vchParentLPN
										,@in_vchWhItemMasterID
										,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_plan]
										,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_pick] 
										,ROUND(@v_fltQuantityStage,@Round)		--[quantity_stage]
										,0										--[quantity_pack]
										,0										--[quantity_load]
										,0										--[quantity_ship] 
										,@in_vchParentLPN						--[parent_lpn]
										,@in_vchlpn								--[lpn]
										,@in_vchLotNumber						--[lot_number]
										,case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end	--[expiry_date]
										,NULL
										,@in_vchAttribute1				
										,@in_vchAttribute2
										,@in_vchAttribute3
										,@in_vchAttribute4
										,@in_vchAttribute5 
										,@v_vchStagingLocationID			--[staging_location_id]
										,@v_vchStagingParentLPN				--[staging_parent_lpn]
										,@v_vchStagingLPN					--[staging_lpn] 
										,'YES'								--[pick_status]
										,'NO'								--[load_status]
										,'NO'								--[ship_status]
										,@v_vchInvID						--[inventory_id]
										,'NO'								--[pack_status]
										,'USER_PICK_ORDER'					--[pick_generate_method]
										,'YES'								--[is_allocate]
										,'NO'								--[is_override] 
										,@v_dtInvReceiveDate
										,@v_dtInvMfgDate
										,'YES'								--[is_active]
										,GETDATE()							--[start_date_time]
										,GETDATE()							--[end_date_time]
										,GETDATE()							--[create_date]
										,@in_vchUserID)						--[create_by])
							END
						ELSE
							BEGIN
								UPDATE t_wms_outbound_pick_detail SET 
  									  quantity_plan		 = ROUND((ISNULL(quantity_plan,0) +  @v_fltInvQuantityPick),@Round) 
									, quantity_pick		 = ROUND((ISNULL(quantity_pick,0) +  @v_fltInvQuantityPick),@Round) 
									, quantity_stage	 = ROUND((ISNULL(quantity_stage,0) + @v_fltQuantityStage),@Round)
									, pick_location_id   = @in_vchForkLocationID
									, pick_to_parent_lpn = @in_vchParentLPN
									, pick_to_lpn		 = @v_vchPickToLPN
									, pick_status        = 'YES'
									, start_date_time	 = ISNULL(start_date_time,GETDATE())
									, end_date_time		 = GETDATE()
								WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
							END

						---------------------------------------------------
						--Insert/Update Pack Detail
						---------------------------------------------------
						IF @RulePickPack = 'YES'
							BEGIN
								UPDATE t_wms_outbound_pick_detail SET 
									  quantity_pack = ROUND((ISNULL(quantity_pack,0) + @v_fltInvQuantityPick),@Round)
									, end_date_time = GETDATE()
								WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

								---------------------------------------------------
								--Insert/Update Pack Detail
								---------------------------------------------------
								PRINT 'Pick and Pack'
								IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
													WHERE outbound_order_master_id = @v_vchOutboundMasterID
													AND pack_location_id = @in_vchForkLocationID
													AND lpn_pack = @v_vchPickToLPN 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND outbound_pick_detail_id = @v_vchOutboundPickDetailID)
									BEGIN
										UPDATE t_wms_outbound_pack_detail SET 
											 quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltInvQuantityPick,@Round)
											,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
										WHERE outbound_order_master_id = @v_vchOutboundMasterID 
										AND pack_location_id = @in_vchForkLocationID
										AND lpn_pack = @v_vchPickToLPN 
										AND wh_item_master_id = @in_vchWhItemMasterID 
										AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
									END
								ELSE
									BEGIN
										INSERT INTO t_wms_outbound_pack_detail
										(     outbound_order_master_id
											, outbound_pick_detail_id
											, lpn_pack
											, pack_location_id
											, wh_item_master_id
											, quantity_pack
											, quantity_stage
											, lot_number
											, expiry_date
											, serial_number
											, [attribute1]
											, [attribute2]
											, [attribute3]
											, [attribute4]
											, [attribute5]
											, item_uom_id
											, staging_parent_lpn
											, staging_lpn
											, staging_location_id
											, create_by
										)
										VALUES
										(     @v_vchOutboundMasterID
											, @v_vchOutboundPickDetailID
											, @v_vchPickToLPN
											, @in_vchForkLocationID
											, @in_vchWhItemMasterID
											, ROUND(@v_fltInvQuantityPick,@Round)
											, @v_fltQuantityStage
											, @in_vchLotNumber
											, case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end
											, NULL
											, @in_vchAttribute1
											, @in_vchAttribute2
											, @in_vchAttribute3
											, @in_vchAttribute4
											, @in_vchAttribute5
											, @v_vchBaseItemUomID
											, @v_vchStagingParentLPN
											, @v_vchStagingLPN
											, @v_vchStagingLocationID
											, @in_vchUserID
										)
									END
							END
				
						---------------------------------------------------
						--Calculate Volumn & Weight
						---------------------------------------------------
						IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
						BEGIN
							SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltInvQuantityPick,2)
							SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltInvQuantityPick,2)
						END

						---------------------------------------------------
						-- Manage source location data
						---------------------------------------------------
						BEGIN
							--Update Volumn & Weight in from location
							IF @in_vchLocationID IS NOT NULL
								BEGIN
									UPDATE [dbo].[t_wms_location] SET
									      total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
										, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID   
									WHERE [location_id] = @in_vchLocationID
								END

							UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
								,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInvID 
							AND attribute_group_id = @v_vchInvAttrGroupID

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
									WHERE inventory_id = @v_vchInvID 
									AND attribute_group_id = @v_vchInvAttrGroupID
									AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END
						END

						------------------------------------------------
						-- Clear Inventory ที่หยิบของหมดแล้ว
						------------------------------------------------
						DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInvID 
						DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInvID 

						---------------------------------------------------
						-- Manage destination location data
						---------------------------------------------------			
						BEGIN
							SET @v_vchInvID = NULL
							SET @v_vchInvAttrGroupID = NULL 
							DECLARE @v_vchDestLocationID UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchDestParentLPN  NVARCHAR(25) = NULL
							DECLARE @v_vchDestLPN		 NVARCHAR(25) = NULL
							SET @v_vchDestLocationID = (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocationID ELSE @in_vchForkLocationID END)
							SET @v_vchDestParentLPN  = (CASE WHEN @RuleAutoStaging = 'YES' THEN ISNULL(@v_vchStagingParentLPN,'') ELSE '' END)
							SET @v_vchDestLPN		 = (CASE WHEN @RuleAutoStaging = 'YES' THEN ISNULL(@v_vchStagingLPN,'') ELSE ISNULL(@v_vchPickToLPN,'') END)

							SELECT @v_vchInvID = inventory_id
								,@v_vchInvAttrGroupID = attribute_group_id 
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @v_vchDestLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @v_vchDefaultItemStatusID
							and receive_date = @v_dtInvReceiveDate
							AND ISNULL(parent_lpn,'') = @v_vchDestParentLPN
							AND ISNULL(lpn,'')		  = @v_vchDestLPN
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

							EXEC usp_manage_inventory @in_vchWhMasterID		  = @in_vchWhMasterID
													, @in_vchOwnerID		  = @in_vchOwnerID
													, @in_vchWhItemMasterID	  = @in_vchWhItemMasterID
													, @in_vchLocationID		  = @v_vchDestLocationID 
													, @in_vchStatusID		  = @v_vchDefaultItemStatusID
													, @in_vchPalentLPN		  = @v_vchDestParentLPN
													, @in_vchLPN			  = @v_vchDestLPN 
													, @in_fltQty			  = @v_fltInvQuantityPick
													, @in_fltQtyAllocate	  = 0
													, @in_fltQtyIncoming	  = 0
													, @in_vchInventoryType	  = @v_vchOutboundOrderNumber
													, @in_vchUserID			  = @in_vchUserID
													, @in_vchReceiveDate	  = @v_dtInvReceiveDate	
													, @in_dtMfgDate			  = @v_dtInvMfgDate
													, @in_vchInventoryID	  = @v_vchInvID OUTPUT
													, @in_vchAttributeGroupID = @v_vchInvAttrGroupID OUTPUT	
													, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
													, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;

							--Update Volumn & Weight in from location
							IF @v_vchDestLocationID IS NOT NULL  
								BEGIN
									UPDATE [dbo].[t_wms_location] SET 
										  total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
										, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID 
									WHERE [location_id] = @v_vchDestLocationID
								END

							--update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET 
								volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInvID
							AND attribute_group_id = @v_vchInvAttrGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
										  @in_vchLot				= @in_vchLotNumber
										, @in_vchExpiryDate			= @in_vchExpiryDate
										, @in_vchSerialNo			= NULL
										, @in_vchAttribute1			= @in_vchAttribute1
										, @in_vchAttribute2			= @in_vchAttribute2
										, @in_vchAttribute3			= @in_vchAttribute3
										, @in_vchAttribute4			= @in_vchAttribute4
										, @in_vchAttribute5			= @in_vchAttribute5
										, @in_fltQty				= @v_fltInvQuantityPick
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInvID
										, @in_vchAttributeGroupID	= @v_vchInvAttrGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END
						END

						---------------------------------------------------		
						--Write Tran Log OO_PICK To Staging
						---------------------------------------------------	 
						INSERT INTO t_com_tran_log
							( app_id
							, [app_name]
							, tran_type
							, sub_tran_type 
							, [description]
							, start_tran_datetime
							, end_tran_datetime
							, warehouse
							, to_warehouse
							, location
							, to_location
							, [owner]
							, to_owner
							, item_number
							, quantity
							, quantity_uom
							, after_quantity
							, after_quantity_uom
							, lot_number
							, after_lot_number
							, [expiry_date]
							, after_expiry_date
							, serial_number
							, [attribute1]
							, [after_attribute1]
							, [attribute2]
							, [after_attribute2]
							, [attribute3]
							, [after_attribute3]
							, [attribute4]
							, [after_attribute4]
							, [attribute5]
							, [after_attribute5]
							, [user_id]
							, parent_lpn
							, after_parent_lpn
							, lpn
							, after_lpn
							, [status]
							, after_status
							, order_number
							, line_number
							, receive_date
							, mfg_date
							, device
							, create_by
							, create_date
							, pick_location
							, input_quantity
							, input_uom
						)
						VALUES
						(  @in_vchApplicationID
							, @v_vchApplicationName
							, 'OO_PICK'
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'MOVE_DEST' ELSE 'SALES_ORDER' END) 
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'User Picking by Load [Auto to Staging]' ELSE 'User Picking by Load' END) 
							, @v_dtStartDate
							, DATEADD(MILLISECOND,2,GETDATE())
							, @v_vchWarehouse
							, @v_vchWarehouse
							, @v_vchLocation
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocation ELSE @v_vchForkLocation END) 
							, @v_vchOwnerCode
							, @v_vchOwnerCode
							, @v_vchItemNumber
							, @v_fltInvQuantityPick
							, @v_vchBaseUomPrompt
							, @v_fltInvQuantity - @v_fltInvQuantityPick
							, @v_vchBaseUomPrompt
							, @in_vchLotNumber
							, @in_vchLotNumber
							, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
							, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
							, NULL
							, @in_vchAttribute1
							, @in_vchAttribute1
							, @in_vchAttribute2
							, @in_vchAttribute2
							, @in_vchAttribute3
							, @in_vchAttribute3
							, @in_vchAttribute4
							, @in_vchAttribute4
							, @in_vchAttribute5
							, @in_vchAttribute5
							, @in_vchUserID 
							, @in_vchParentLPN
							, @v_vchStagingParentLPN
							, @in_vchLPN
							, @v_vchStagingLPN
							, @in_vchItemStatus
							, @in_vchItemStatus
							, @v_vchOutboundOrderNumber
							, @v_vchLineNumber
							, @v_dtInvReceiveDate
							, @v_dtInvMfgDate
							, @in_vchDeviceID
							, @in_vchUserID
							, GETDATE()	--[create_date]
							, @v_vchLocation
							, @in_fltQuantity
							, @v_vchInputUomPrompt
						)
					 

					--สำหรับรวมจำนวนที่ pick ของจาก inventory ในแต่ละรอบ
					SET @v_fltSummaryInvPick = @v_fltSummaryInvPick + @v_fltInvQuantityPick

					--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
					SET @v_fltQtyCanPick = @v_fltQtyCanPick - @v_fltInvQuantityPick

					--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
					IF @v_fltQtyCanPick > 0
						GOTO INVENTORY_NEXT;
				END  

			-- For Dashboard
			BEGIN
				DECLARE @v_vchDSToLocationID UNIQUEIDENTIFIER = NULL 
				IF @RuleAutoStaging = 'YES'
					BEGIN
						SET @v_vchDSToLocationID = @v_vchStagingLocationID 
					END
				ELSE
					BEGIN  
						SET @v_vchDSToLocationID = @in_vchForkLocationID 
					END
				EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
												,@in_vchTransType	 = 'PICK'
												,@in_vchWhMasterID	 = @in_vchWhMasterID
												,@in_vchOwnerID		 = @in_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwnerCode
												,@in_vchLocationID	 = @in_vchLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
												,@in_vchToWhMasterID = @in_vchWhMasterID
												,@in_vchToLocationID = @v_vchDSToLocationID
												,@in_vchToInvStatusID = @v_vchDefaultItemStatusID
												,@in_fltQuantity	 = @v_fltSummaryInvPick
												,@in_vchUserID		 = @in_vchUserID
			END

			-------------------------------------------------------------------------------
			-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
			-------------------------------------------------------------------------------
			SET @v_fltBaseInputQuantity = @v_fltBaseInputQuantity - @v_fltSummaryInvPick
			IF @v_fltBaseInputQuantity = 0
				BREAK;
	
			FETCH NEXT FROM OutboundDetail_Cursor INTO @v_vchOutboundMasterID,@v_vchOutboundOrderNumber,@v_vchOrderType,@v_vchOwnerCode,@v_vchOutboundDetailID,@v_vchLineNumber,@v_fltQuantityOrder,@v_fltQuantityPick
		END
		CLOSE OutboundDetail_Cursor
		DEALLOCATE OutboundDetail_Cursor

		------------------------------------------------
		-- Update Order Status ถ้า Pick ครบแล้ว
		------------------------------------------------
		IF ((SELECT SUM(quantity_order) - SUM(quantity_pick) FROM t_wms_outbound_detail obDT WHERE outbound_order_master_id = @v_vchOutboundMasterID) = 0)
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @v_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
			END

		---------------------------------------------------------
		-- Auto Create Inbound Plan and Receipt
		---------------------------------------------------------
		EXEC usp_inbound_insert_order @in_vchApplicationID	     = @in_vchApplicationID
										,@in_vchDeviceID		 = @in_vchDeviceID	
										,@in_vchUserID			 = @in_vchUserID	
										,@in_vchWhMasterID		 = @in_vchWhMasterID
										,@in_vchOrderNumber		 = @v_vchOutboundOrderNumber
										,@in_vchLocation		 = @v_vchLocation
										,@in_vchParentLPN		 = @in_vchParentLPN
										,@in_vchLPN				 = @v_vchPickToLPN
										,@in_vchItemNumber		 = @v_vchItemNumber
										,@in_vchLotNumber		 = @in_vchLotNumber
										,@in_vchExpiryDate		 = @in_vchExpiryDate
										,@in_vchSerialNumber	 = @in_vchSerialNumber
										,@in_fltQuantity		 = @v_fltBaseInputQuantity
										,@in_vchUOMPrompt		 = @v_vchBaseUomPrompt
										,@in_vchDefaultItemStatus = @in_vchItemStatus
										,@in_vchAttribute1		 = @in_vchAttribute1
										,@in_vchAttribute2		 = @in_vchAttribute2
										,@in_vchAttribute3		 = @in_vchAttribute3
										,@in_vchAttribute4		 = @in_vchAttribute4
										,@in_vchAttribute5		 = @in_vchAttribute5
										,@out_vchErrorCode		 = @out_ErrorCode OUTPUT
										,@out_vchErrorMsg		 = @out_ErrorMessage OUTPUT
		IF (@out_ErrorCode <> 0)
			BEGIN
				GOTO WRITE_PROC;
			END

		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = 0;
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5') 
		RETURN;
	
---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','OutboundDetail_Cursor')>=-1
		BEGIN
			CLOSE OutboundDetail_Cursor;
			DEALLOCATE OutboundDetail_Cursor;
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQuantity) + ' ' + @v_vchInputUomPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @v_vchLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','OutboundDetail_Cursor')>=-1
		BEGIN
			CLOSE OutboundDetail_Cursor;
			DEALLOCATE OutboundDetail_Cursor;
		END

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();

	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQuantity) + ' ' + @v_vchInputUomPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @v_vchLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_generate_user_pick_by_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_generate_user_pick_by_order]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,							
	@in_vchLocalID			VARCHAR(40) = NULL,
	@in_vchDeviceID			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@in_vchForkLocationID	UNIQUEIDENTIFIER = NULL,
	@in_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			UNIQUEIDENTIFIER = NULL,
	@in_vchBoxNumber		NVARCHAR(25) = NULL,
	@in_vchLocationID		UNIQUEIDENTIFIER = NULL,
	@in_vchParentLPN		NVARCHAR(25) = NULL,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL, 
	@in_vchItemStatus		NVARCHAR(40) = NULL,	-- มาจาก Plan
	@in_fltQuantity			FLOAT = NULL,
	@in_vchItemUOMID		UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber		NVARCHAR(100) = NULL,
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchSerialNumber		NVARCHAR(100) = NULL,	-- ALL หรือส่งค่ามา
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@out_ErrorCode			NVARCHAR(50)  OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_generate_user_pick_by_order]'
	DECLARE @v_vchProcessData			NVARCHAR(500)
	DECLARE @v_dtProcessDateTime		DATETIME
	DECLARE @v_vchApplicationName		NVARCHAR(50)= NULL
	DECLARE @v_vchBeginTrans			BIT = 0
	DECLARE @v_dtStartDate				DATETIME
	DECLARE @RulePickPack				VARCHAR(3) = NULL
	DECLARE @RuleAutoStaging			VARCHAR(3) = NULL
	DECLARE @Round						INT = 0
	DECLARE @v_nCount					INT = 0
	DECLARE @v_vchForkLocation			NVARCHAR(50) = NULL
	
	DECLARE @v_vchOutboundOrderNumber	NVARCHAR(50) = NULL
	DECLARE @v_vchOrderStatus			NVARCHAR(30) = NULL
	DECLARE @v_vchOrderType				NVARCHAR(30) = NULL
	DECLARE @v_vchPickBy				NVARCHAR(25) = NULL
	DECLARE @v_vchWarehouse				NVARCHAR(25) = NULL
	DECLARE @v_vchOwner					NVARCHAR(50) = NULL
	DECLARE @v_vchLocation				NVARCHAR(50) = NULL

	--Item Master
	DECLARE @v_vchItemMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber			NVARCHAR(50)  = NULL 
	DECLARE @v_vchLotControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpControl			VARCHAR(5) = NULL
	DECLARE @v_vchSNControl				VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control		VARCHAR(5) = NULL
	DECLARE @v_vchItemIsActive			VARCHAR(3) = NULL
	DECLARE @v_vchDefaultItemStatusID	UNIQUEIDENTIFIER = NULL

	-- Item UOM 
	DECLARE @v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL 
	DECLARE @v_vchBaseUom				NVARCHAR(20) = NULL
	DECLARE @v_vchInputUomPrompt		NVARCHAR(40) = NULL
	DECLARE @v_vchIsPrimaryUOM			NVARCHAR(5)
	DECLARE @v_fltConversionFactor		FLOAT = 0
	DECLARE @v_fltBaseInputQuantity		FLOAT = 0
	DECLARE @v_fltWidth					FLOAT = 0   --item Uom
	DECLARE @v_fltLength				FLOAT = 0   --item Uom
	DECLARE @v_fltHeight				FLOAT = 0   --item Uom
	DECLARE @v_fltGrossWeight			FLOAT = 0   --item Uom
	DECLARE @v_intPercentTolerance		FLOAT = 0   --item Uom
	DECLARE @v_intPercenToleranceWeight FLOAT = 0   --item Uom
	DECLARE @v_fltVolumn				FLOAT = 0 	--item Uom
	DECLARE @v_fltTotalWeight			FLOAT = 0 	--item Uom
			
	-- Inventory
	DECLARE @v_fltChkInvQty				FLOAT
	DECLARE @v_fltChkInvQtyAllocate		FLOAT
	DECLARE @v_fltChkInvQtyRemain		FLOAT --จำนวนคงเหลือใน Inventory ที่สามารถหยิบได้ 
	DECLARE @v_fltChkSumPlanRemainPick	FLOAT --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Load ใน item ที่ scan 	

	-- Outbound Detail 
	DECLARE @v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchLineNumber			NVARCHAR(10) = NULL
	DECLARE @v_fltQuantityOrder			FLOAT = 0
	DECLARE @v_fltQuantityPick			FLOAT = 0
	DECLARE	@v_vchPickToLPN				NVARCHAR(25) = NULL

	-- AUTO STG MOD For CBD
	DECLARE @v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchStagingLocation		NVARCHAR(50) = NULL
	DECLARE @v_fltQuantityStage			FLOAT
	DECLARE @v_vchStagingParentLPN		NVARCHAR(25) = NULL
	DECLARE @v_vchStagingLPN			NVARCHAR(25) = NULL

	-- For Serial Case ALL
	DECLARE @v_intStartIndexSN	INT  = 1
	DECLARE @v_intEndIndexSN	INT  = 0
	DECLARE @v_intInvCheck		FLOAT = 0
	DECLARE @tInventorySerial TABLE
	(
		[RowNumber] [INT] NOT NULL,
		[InventoryID] UNIQUEIDENTIFIER NOT NULL,
		[AttributeGroupID] UNIQUEIDENTIFIER NOT NULL,
		[quantity] [float] NOT NULL,
		[ReceiveDate] DATE NOT NULL,
		[MfgDate] DATE NULL,
		[SerialNumber] [nvarchar] (50) NOT NULL
	)

	BEGIN TRY
		SET @v_dtStartDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
		SELECT TOP 1 @RuleAutoStaging = VALUE FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
		SELECT TOP 1 @v_vchForkLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchForkLocationID AND is_active = 'YES'
		SELECT TOP 1 @v_vchLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @in_vchLocationID AND is_active = 'YES'
		SELECT TOP 1 @v_vchDefaultItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchItemStatus AND is_active = 'YES'

		--ถ้าเป็นการ Pick จาก WEB จะถือว่าเป็นการ Auto STG อัตโนมัติ เนื่องจากใน Para @in_vchForkLocationID จะส่ง location id ของ STG มา
		IF(SELECT loc_type FROM t_wms_location WHERE location_id = @in_vchForkLocationID) = 'STG'
			BEGIN
				SET @RuleAutoStaging = 'YES'
			END

		--------------------------------------------------
		-- Get Data in Outbound Master
		--------------------------------------------------
		SELECT TOP 1 @v_vchOutboundOrderNumber = obMS.outbound_order_number
			,@v_vchOrderStatus = obMS.order_status
			,@v_vchOrderType = obMS.order_type
			,@v_vchPickBy = obMS.pick_by
			,@v_vchWarehouse = obMS.wh_id
			,@v_vchOwner = obMS.owner_code
		FROM t_wms_outbound_master obMS 
		WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID
		AND obMS.wh_master_id = @in_vchWhMasterID
		IF(@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
			
		-------------------------------------------------
		-- SET Box Number
		-------------------------------------------------
		IF ISNULL(@in_vchBoxNumber,'') = ''
			BEGIN
				SET @in_vchBoxNumber = @v_vchOutboundOrderNumber
			END

		--------------------------------------------------------
		-- Validate Staging Location
		--------------------------------------------------------
		IF (@RuleAutoStaging = 'YES')
			BEGIN
				--Check Old STG = New STG
				SET @v_vchStagingLocationID = NULL
				SET @v_vchStagingLocation = NULL
				SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
					, @v_vchStagingLocation = loc.location 
				FROM t_wms_outbound_pick_detail pickDT
				INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
				INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
				WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
				AND pickDT.staging_location_id IS NOT NULL
				
				IF @v_vchStagingLocationID IS NULL
				BEGIN
					SELECT TOP 1 @v_vchStagingLocationID = location_id
						,@v_vchStagingLocation = location 
					FROM t_wms_location 
					WHERE wh_master_id = @in_vchWhMasterID 
					AND loc_type = 'STG' AND is_active = 'YES'
					IF (@v_vchStagingLocationID IS NULL)
					BEGIN
						SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC
					END
				END 
			END

		------------------------------------------------------
		-- ตรวจสอบ Multiple user pick
		------------------------------------------------------
		IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO') AND (@v_vchPickBy <> @in_vchUserID))
			BEGIN
				--Multi User
				SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;	
			END

		--------------------------------------------------
		-- Get wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Get item_master_id
		--------------------------------------------------
		SET @v_vchItemNumber = NULL
		SELECT @v_vchItemMasterID = item.item_master_id
			, @v_vchItemNumber = item.item_number
			, @v_vchLotControl = item.lot_control
			, @v_vchExpControl = item.expiry_date_control
			, @v_vchSNControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
			, @v_vchItemIsActive = item.is_active
		FROM t_wms_item item
 		WHERE owner_id = @in_vchOwnerID
		AND item_master_id = @v_vchItemMasterID
		IF (@v_vchItemNumber IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		IF (@v_vchItemIsActive <> 'YES')
			BEGIN
				SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

			--Check SN หากรับเข้ามาด้วย Tag RFID
		IF @v_vchSNControl = 'FULL'
			BEGIN
				--Insert Serial in Inventory
				INSERT INTO @tInventorySerial
				SELECT ROW_NUMBER() OVER(ORDER BY serial_number) AS RowNumber
					,inventory_id
					,attribute_group_id
					,quantity
					,receive_date
					,mfg_date
					,serial_number
				FROM v_wms_inventory_data_serial_by_id
				WHERE wh_master_id = @in_vchWhMasterID
				AND owner_id = @in_vchOwnerID
				AND location_id = @in_vchLocationID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND inventory_status_id = @v_vchDefaultItemStatusID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) =  (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
				ORDER BY serial_number

				SET @v_intInvCheck = 0
				SELECT @v_intInvCheck = MAX(RowNumber) FROM @tInventorySerial
				IF ISNULL(@v_intInvCheck,0) = 0
					BEGIN
						-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
						SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
						RETURN;
					END
				
				IF EXISTS (SELECT pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_master pickMS
							INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
							WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
							AND pickDT.serial_number IN (SELECT [SerialNumber] FROM @tInventorySerial))
					BEGIN
						SET @out_ErrorCode = 'INFO-SN-DUPLICATED'
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
						RETURN;
					END
			END

		--------------------------------------------------
		--Get & Check Item UOM
		--------------------------------------------------
		SELECT @v_vchBaseItemUomID	= item_uom_id
			,@v_vchBaseUom	 = uom
			,@v_vchInputUomPrompt	= uom_prompt
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
			,@v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND item_uom_id = @in_vchItemUOMID		
		AND is_active = 'YES'	
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInputUomPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		--Get Primary Uom
		--------------------------------------------------
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUom	 = uom
					,@v_fltWidth = ISNULL(width,0)
					,@v_fltLength = ISNULL(length,0)
					,@v_fltHeight = ISNULL(height,0)
					,@v_fltGrossWeight = ISNULL(gross_weight,0)
					,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
					,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
	
		--กรณีที่เป็น Serial จะนับจำนวน Serial ทั้งหมด มาตรวจสอบจำนวน
		IF @v_vchSNControl = 'FULL'
			BEGIN
				--------------------------------------------------
				--Set Input Base Qty 
				-- จะต้องกำหนดจำนวน SN ทีจะจ่าย เท่ากับจำนวน Serial ทั้งหมดที่ generate ตาม SN from - To
				--------------------------------------------------
				SET @in_fltQuantity = @v_intInvCheck
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round); 
			END
		ELSE
			BEGIN
				--------------------------------------------------
				--Set Input Base Qty 
				--------------------------------------------------
				SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
			END
		
		------------------------------------------------------------------------------
		-- เงื่อนไข Plan outbound detail 
		-- ใช้สำหรับตรวจสอบรายการที่จะ pick ว่าตรงกับ Plan หรือไม่กรณีที่มีการกำหนด lpn,lot,exp.
		-- ใช้สำหรับวนลูปเพื่อ Insert/Update Pick List
		-- สำหรับ User Pick ไม่ต้องกำหนด LPN,Lot,Exp ใน plan
		------------------------------------------------------------------------------
		SET @v_nCount = 0;
		SET @v_fltChkSumPlanRemainPick = 0;
		SELECT @v_fltChkSumPlanRemainPick = ROUND(SUM(ISNULL(obDT.quantity_order,0) - ISNULL(obDT.quantity_pick,0)),@ROUND)
			,@v_nCount = COUNT(obdt.outbound_order_detail_id) 
		FROM t_wms_outbound_detail obDT
		WHERE obDT.outbound_order_master_id = @in_vchOutboundMasterID
		AND obDT.wh_item_master_id = @in_vchWhItemMasterID
		AND obDT.default_item_status = @in_vchItemStatus

		--------------------------------------------------
		-- ถ้าไม่พบ Recode ใน OBDT แสดงว่าข้อมูลผิด
		--------------------------------------------------
		IF @v_nCount = 0
			BEGIN
				-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
				SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศูนย์ = ERROR
		--------------------------------------------------
		IF @v_fltChkSumPlanRemainPick = 0
			BEGIN
				-- รายการสินค้า [] หยิบครบแล้ว
				SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- ถ้าจำนวนที่หยิบ > จำนวนคงเหลือที่สามารถหยิบได้ = ERROR
		--------------------------------------------------
		IF @v_fltBaseInputQuantity > @v_fltChkSumPlanRemainPick
			BEGIN
				-- รายการสินค้า [] ไม่สามารถหยิบเกินได้
				SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- Check Inventory Qty - Allocate Qty >= Qty Pick
		-------------------------------------------------- 	
		SET @v_nCount = 0
		SET @v_fltChkInvQty = 0
		SET @v_fltChkInvQtyAllocate = 0
		SET @v_fltChkInvQtyRemain = 0
		SELECT @v_nCount = COUNT(inventory_id) 
			,@v_fltChkInvQty = SUM(quantity)
			,@v_fltChkInvQtyAllocate = SUM(ISNULL(quantity_allocated,0))
			,@v_fltChkInvQtyRemain = ROUND(SUM(ISNULL(quantity,0) - ISNULL(quantity_allocated,0)),@round)
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @in_vchOwnerID
		AND location_id = @in_vchLocationID
		AND wh_item_master_id = @in_vchWhItemMasterID
		AND inventory_status_id = @v_vchDefaultItemStatusID
		AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
		
		IF ISNULL(@v_nCount,0) = 0
			BEGIN
				-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
				SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				RETURN;
			END
		
		IF @v_fltChkInvQtyRemain < @v_fltBaseInputQuantity
			BEGIN
				-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
				SET @out_ErrorCode = 'INFO-QTY-MORE-THAN-STOCK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC;
			END

		------------------------------------------------------------
		-- SET pick_to_lpn
		-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
		------------------------------------------------------------
		IF (@v_fltBaseInputQuantity = @v_fltChkInvQty AND @v_fltChkInvQtyAllocate = 0 AND ISNULL(@in_vchLPN,'') <> '')
			BEGIN
				SET @v_vchPickToLPN = @in_vchLPN
			END
		ELSE
			BEGIN
				SET @v_vchPickToLPN = @in_vchBoxNumber
			END

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		
		-- Update Outbound Master
		UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID, order_status = 'PICK',update_by = @in_vchUserID, update_date = GETDATE() WHERE outbound_order_master_id = @in_vchOutboundMasterID

		---------------------------------------------------
		-- Get Pick Master ID
		---------------------------------------------------
		DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
		SET @v_vchOutboundPickMasterID = NULL
		SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @in_vchOutboundMasterID
		IF @v_vchOutboundPickMasterID IS NULL
			BEGIN
				SET @v_vchOutboundPickMasterID = NEWID()
				INSERT INTO [dbo].[t_wms_outbound_pick_master]
						([outbound_pick_master_id]
						,[wh_master_id]
						,[outbound_order_master_id]
						,[outbound_order_number]
						,[pick_list_number]
						,[pick_list_status]
						,[create_date]
						,[create_by])
					VALUES
						(@v_vchOutboundPickMasterID
						,@in_vchWhMasterID
						,@in_vchOutboundMasterID
						,@v_vchOutboundOrderNumber
						,@v_vchOutboundOrderNumber
						,'PICK' 
						,GETDATE()
						,@in_vchUserID)
			END

		DECLARE OutboundDetail_Cursor CURSOR FOR
			-------------------------------------------------
			-- Generate Pick Detail
			-- เอาเฉพาะรายการของ outbound detail ที่ยังหยิบไม่ครบ
			-------------------------------------------------
			SELECT obDT.outbound_order_detail_id
				,obDT.line_number
				,ISNULL(obDT.quantity_order,0)
				,ISNULL(obDT.quantity_pick,0)
			FROM t_wms_outbound_detail obDT
			WHERE obDT.outbound_order_master_id = @in_vchOutboundMasterID
			AND obDT.wh_item_master_id = @in_vchWhItemMasterID
			AND obDT.default_item_status = @in_vchItemStatus
			AND ISNULL(obDT.quantity_pick,0) < ISNULL(obDT.quantity_order,0)
			ORDER BY CONVERT(INT,obDT.line_number)
		OPEN OutboundDetail_Cursor
		FETCH NEXT FROM OutboundDetail_Cursor INTO  @v_vchOutboundDetailID,@v_vchLineNumber,@v_fltQuantityOrder,@v_fltQuantityPick
	
		WHILE @@FETCH_STATUS = 0
		BEGIN 
			DECLARE @v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL
			DECLARE @v_vchPickLineNumber		NVARCHAR(5)	 = NULL
			DECLARE @v_fltQtyCanPick			FLOAT = 0
			DECLARE @v_fltSummaryInvPick 		FLOAT = 0

			---------------------------------------------------
			-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ
			---------------------------------------------------
			IF ((@v_fltQuantityOrder - @v_fltQuantityPick) > @v_fltBaseInputQuantity)
				SET @v_fltQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
			ELSE
				SET @v_fltQtyCanPick = ROUND((@v_fltQuantityOrder - @v_fltQuantityPick),@Round)

			IF @v_vchSNControl = 'FULL'
				BEGIN
					SET @v_fltSummaryInvPick = 0;
					--Index for get serial from - to : ต้องกำหนดเนื่องจากกันกรณีที่เป็น item เดียวกัน 2 line จะต้องแบ่งจำนวน serial 
					SET @v_intEndIndexSN = (@v_fltQtyCanPick + @v_intStartIndexSN) - 1

					--------------------------------------------------------
					-- Validate Staging Location and set value staging
					--------------------------------------------------------
					IF (@RuleAutoStaging = 'YES')
						BEGIN
							--Update Outbound Detail
							UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyCanPick,@Round)
								,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQtyCanPick,@Round)
								,item_status = 'PICK'
								,update_by = @in_vchUserID
								,update_date = GETDATE()
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND outbound_order_detail_id = @v_vchOutboundDetailID 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND line_number = @v_vchLineNumber

							--SET Value Staging
							SET @v_fltQuantityStage = 1
							SET @v_vchStagingParentLPN = NULL
							SET @v_vchStagingLPN = @v_vchPickToLPN
						END
					ELSE
						BEGIN
							SET @v_vchStagingLocationID = NULL
							SET @v_vchStagingLocation = NULL
							SET @v_fltQuantityStage = 0	
							SET @v_vchStagingParentLPN = NULL	
							SET @v_vchStagingLPN = NULL

							--Update Outbound Detail
							UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltQtyCanPick,@Round),@Round)
								,item_status = 'PICK'
								,update_by = @in_vchUserID
								,update_date = GETDATE()
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND outbound_order_detail_id = @v_vchOutboundDetailID 
							AND wh_item_master_id = @in_vchWhItemMasterID 
							AND line_number = @v_vchLineNumber
						END

					IF OBJECT_ID('tempdb..#tSourceInventory') IS NOT NULL
						DROP TABLE #tSourceInventory
					
					SELECT RowNumber
						,InventoryID
						,AttributeGroupID
						,quantity
						,ReceiveDate
						,MfgDate
						,SerialNumber
					INTO #tSourceInventory
					FROM @tInventorySerial
					WHERE RowNumber BETWEEN @v_intStartIndexSN AND @v_intEndIndexSN
					
					--Set Start Index for next loop
					SET @v_intStartIndexSN = @v_intEndIndexSN + 1
					
					--Check duplicate serail in pick detail
					IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND wh_item_master_id = @in_vchWhItemMasterID AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
						BEGIN
							SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
							SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END

					SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
					IF (@v_vchPickLineNumber IS NULL)
						BEGIN
							SET @v_vchPickLineNumber = '00000'; 
						END

					INSERT INTO [dbo].[t_wms_outbound_pick_detail]
							([outbound_pick_detail_id]
							,[outbound_pick_master_id]
							,[outbound_order_detail_id]
							,[pick_line_number]
							,[location_id]
							,[pick_location_id]
							,[pick_to_lpn]
							,[pick_to_parent_lpn]
							,[wh_item_master_id]
							,[quantity_plan]
							,[quantity_pick]
							,[quantity_stage]
							,[quantity_pack]
							,[quantity_load]
							,[quantity_ship]
							,[parent_lpn]
							,[lpn]
							,[lot_number]
							,[expiry_date]
							,[serial_number]
							,[attribute1]
							,[attribute2]
							,[attribute3]
							,[attribute4]
							,[attribute5]
							,[staging_location_id]
							,[staging_parent_lpn]
							,[staging_lpn] 
							,[pick_status]
							,[load_status]
							,[ship_status]
							,[inventory_id]
							,[pack_status]
							,[pick_generate_method]
							,[is_allocate]
							,[is_override] 
							,[receive_date]
							,[mfg_date]
							,[is_active]
							,[start_date_time]
							,[end_date_time]
							,[create_date]
							,[create_by])
						SELECT NEWID()
							,@v_vchOutboundPickMasterID
							,@v_vchOutboundDetailID
							, RIGHT('0000' + CONVERT(NVARCHAR,ISNULL(@v_vchPickLineNumber,0) +  ROW_NUMBER() OVER(ORDER BY SerialNumber)),5) 
							,@in_vchLocationID
							,@in_vchForkLocationID
							,@v_vchPickToLPN
							,@in_vchParentLPN
							,@in_vchWhItemMasterID
							,1	--[quantity_plan]
							,1	--[quantity_pick]
							,(CASE WHEN @RuleAutoStaging = 'YES' THEN 1 ELSE 0 END)	--[quantity_stage]
							,(CASE WHEN @RulePickPack = 'YES' THEN 1 ELSE 0 END)	--[quantity_pack]
							,0										--[quantity_load]
							,0										--[quantity_ship]
							,@in_vchParentLPN						--[parent_lpn]
							,@in_vchlpn								--[lpn]
							,@in_vchLotNumber						--[lot_number]
							,(CASE WHEN @in_vchExpiryDate = '' THEN NULL ELSE @in_vchExpiryDate END) --[expiry_date]
							,SerialNumber
							,@in_vchAttribute1				
							,@in_vchAttribute2
							,@in_vchAttribute3
							,@in_vchAttribute4
							,@in_vchAttribute5
							,@v_vchStagingLocationID			--[staging_location_id]
							,@v_vchStagingParentLPN				--[staging_parent_lpn]
							,@v_vchStagingLPN					--[staging_lpn]
							,'YES'								--[pick_status]
							,'NO'								--[load_status]
							,'NO'								--[ship_status]
							,InventoryID						--[inventory_id]
							,'NO'								--[pack_status]
							,'USER_PICK_ORDER'					--[pick_generate_method]
							,'YES'								--[is_allocate]
							,'NO'								--[is_override] 
							,ReceiveDate
							,MfgDate
							,'YES'								--[is_active]
							,GETDATE()							--[start_date_time]
							,DATEADD(MILLISECOND,RowNumber * 10,GETDATE())						--[end_date_time]
							,DATEADD(MILLISECOND,RowNumber * 10,GETDATE())						--[create_date]
							,@in_vchUserID						--[create_by])
						FROM #tSourceInventory
						ORDER BY RowNumber

					---------------------------------------------------
					--Insert/Update Pack Detail
					---------------------------------------------------
					IF @RulePickPack = 'YES'
						BEGIN
							---------------------------------------------------
							--Insert/Update Pack Detail
							---------------------------------------------------
							PRINT 'Pick and Pack' 
							IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pack_detail 
										WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID 
										AND pack_location_id = @in_vchForkLocationID
										AND lpn_pack = @v_vchPickToLPN 
										AND wh_item_master_id = @in_vchWhItemMasterID 
										AND serial_number IN (SELECT serial_number FROM #tSourceInventory))
							BEGIN
								SET @out_ErrorCode = 'SERIAL_IS_PACK_COMPLETE';
								SELECT @out_ErrorMessage= dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@in_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
								 
							INSERT INTO t_wms_outbound_pack_detail
							(     outbound_order_master_id
								, outbound_pick_detail_id
								, lpn_pack
								, pack_location_id
								, wh_item_master_id
								, quantity_pack
								, quantity_stage
								, lot_number
								, expiry_date
								, serial_number
								, [attribute1]
								, [attribute2]
								, [attribute3]
								, [attribute4]
								, [attribute5]
								, item_uom_id
								, staging_parent_lpn
								, staging_lpn
								, staging_location_id
								, create_by
								, create_date
							)
							SELECT @in_vchOutboundMasterID
								, @v_vchOutboundPickDetailID
								, @v_vchPickToLPN
								, @in_vchForkLocationID
								, @in_vchWhItemMasterID
								, 1
								, @v_fltQuantityStage
								, @in_vchLotNumber
								, case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end
								, SerialNumber
								, @in_vchAttribute1
								, @in_vchAttribute2
								, @in_vchAttribute3
								, @in_vchAttribute4
								, @in_vchAttribute5
								, @v_vchBaseItemUomID
								, @v_vchStagingParentLPN
								, @v_vchStagingLPN
								, @v_vchStagingLocationID
								, @in_vchUserID
								, DATEADD(MILLISECOND,RowNumber *10,GETDATE())						--[create_date]
							FROM #tSourceInventory
							ORDER BY RowNumber
						END
				
					---------------------------------------------------
					--Calculate Volumn & Weight
					---------------------------------------------------
					IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
						BEGIN
							SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyCanPick,2)
							SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyCanPick,2)
						END

					--------------------------------------------
					--Manage source inventory
					--------------------------------------------
					BEGIN
						--Update Volumn & Weight in from location
						IF @in_vchLocationID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location]
									SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
									WHERE [location_id] = @in_vchLocationID
							END

						UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(inv.quantity,0) - ISNULL(tSourceInv.qty_for_pick,0),@Round)
							,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
							,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
						FROM t_wms_inventory inv
						INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON inv.inventory_id = tSourceInv.InventoryID
						WHERE inv.inventory_id = tSourceInv.InventoryID 
		
						--Inventory attribute for serial
						IF @v_vchSNControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - 1,@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT * FROM #tSourceInventory) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = tSourceInv.SerialNumber
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END

						--Inventory attribute for lot
						IF @v_vchLotControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchLotNumber
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'LOT' AND is_active = 'YES')
							END

						--Inventory attribute for EXP
						IF @v_vchExpControl = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchExpiryDate
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'EXPIRY_DATE' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 1
						IF @v_vchAttribute1Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute1
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE1' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 2
						IF @v_vchAttribute2Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute2
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE2' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 3
						IF @v_vchAttribute3Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute3
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE3' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 4
						IF @v_vchAttribute4Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute4
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE4' AND is_active = 'YES')
							END

						--Inventory attribute for Attribute 5
						IF @v_vchAttribute5Control = 'FULL'
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(invAttr.quantity - ISNULL(tSourceInv.qty_for_pick,0),@Round)
								FROM t_wms_inventory_attribute invAttr
								INNER JOIN (SELECT InventoryID, SUM(quantity) AS qty_for_pick FROM #tSourceInventory GROUP BY InventoryID) tSourceInv ON invAttr.inventory_id = tSourceInv.InventoryID
								WHERE invAttr.inventory_id = tSourceInv.InventoryID
								AND invAttr.attribute_value = @in_vchAttribute5
								AND invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'ATTRIBUTE5' AND is_active = 'YES')
							END
						
						DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
						DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id IN (SELECT InventoryID FROM #tSourceInventory)
					END
					
					---------------------------------------------------
					--Manage destination location data
					--2019-08-19 : STG ไม่ได้คำนวณ Volumn ตอนตัดเลยไม่ได้ update volumn
					---------------------------------------------------	
					DECLARE @v_dtLoopReceiveDate		DATE = NULL
					DECLARE @v_dtLoopMfgDate			DATE = NULL
					DECLARE @v_fltLoopQtyPick			FLOAT = NULL
					DECLARE @v_vchLoopInventoryID		uniqueidentifier = NULL
					DECLARE @v_vchLoopAttributeGroupID	uniqueidentifier = NULL 
					DECLARE @v_vchLoopToLocationID		uniqueidentifier = NULL
					DECLARE @v_vchLoopToParentLPN		NVARCHAR(25) = NULL
					DECLARE @v_vchLoopToLPN				NVARCHAR(25) = NULL
					IF @RuleAutoStaging = 'YES' 
						BEGIN
							SET @v_vchLoopToLocationID = @v_vchStagingLocationID
							SET @v_vchLoopToParentLPN = @v_vchStagingParentLPN
							SET @v_vchLoopToLPN = @v_vchStagingLPN
						END
					ELSE
						BEGIN
							SET @v_vchLoopToLocationID = @in_vchForkLocationID
							SET @v_vchLoopToParentLPN = NULL
							SET @v_vchLoopToLPN = @v_vchPickToLPN
						END

					DECLARE InventoryDest_Cursor CURSOR FOR
						SELECT ReceiveDate
							,MfgDate
							,SUM(quantity)
						FROM #tSourceInventory
						GROUP BY ReceiveDate,MfgDate
					OPEN InventoryDest_Cursor
					
					FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate,@v_dtLoopMfgDate, @v_fltLoopQtyPick
	
					WHILE @@FETCH_STATUS = 0
						BEGIN 
							SET @v_vchLoopInventoryID = NULL
							SET @v_vchLoopAttributeGroupID = NULL 
							SELECT @v_vchLoopInventoryID = inventory_id
								,@v_vchLoopAttributeGroupID = attribute_group_id 
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @v_vchLoopToLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @v_vchDefaultItemStatusID
							and receive_date = @v_dtLoopReceiveDate
							AND ISNULL(parent_lpn,'') = ISNULL(@v_vchLoopToParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@v_vchLoopToLPN ,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							EXEC usp_manage_inventory @in_vchWhMasterID			= @in_vchWhMasterID
													, @in_vchOwnerID			= @in_vchOwnerID
													, @in_vchWhItemMasterID		= @in_vchWhItemMasterID
													, @in_vchLocationID			= @v_vchLoopToLocationID
													, @in_vchStatusID			= @v_vchDefaultItemStatusID
													, @in_vchPalentLPN			= @v_vchLoopToParentLPN
													, @in_vchLPN				= @v_vchLoopToLPN
													, @in_fltQty				= @v_fltLoopQtyPick
													, @in_fltQtyAllocate		= 0
													, @in_fltQtyIncoming		= 0
													, @in_vchInventoryType		= @v_vchOutboundOrderNumber
													, @in_vchUserID				= @in_vchUserID
													, @in_vchReceiveDate		= @v_dtLoopReceiveDate	
													, @in_dtMFGDate				= @v_dtLoopMfgDate
													, @in_vchInventoryID		= @v_vchLoopInventoryID OUTPUT
													, @in_vchAttributeGroupID	= @v_vchLoopAttributeGroupID OUTPUT	
													, @in_vchErrorCode			= @out_ErrorCode OUTPUT
													, @in_vchMessage			= @out_ErrorMessage OUTPUT	
							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;

							--Insert/Update Attribute
							IF EXISTS (SELECT inventory_id FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchLoopInventoryID AND attribute_group_id = @v_vchLoopAttributeGroupID)
								BEGIN --Update 
									IF(@v_vchSNControl = 'FULL')
										BEGIN
											IF EXISTS (SELECT attribute_value  FROM t_wms_inventory_attribute 
														WHERE inventory_id = @v_vchLoopInventoryID 
														AND attribute_group_id = @v_vchLoopAttributeGroupID
														AND attribute_value IN (SELECT SerialNumber FROM #tSourceInventory WHERE ReceiveDate = @v_dtLoopReceiveDate)
														AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' AND is_active = 'YES'))
												BEGIN
													SET @out_ErrorCode = 'INFO-SN-DUPLICATED-IN-INVENTORY'
													SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
													GOTO WRITE_PROC;
												END

											--Insert เฉพาะ Serial ที่ไม่มีอยู่ใน Inventory
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											SELECT NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
												, @v_vchLoopAttributeGroupID
												, SerialNumber
												, 1
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID
											FROM #tSourceInventory
											WHERE ReceiveDate = @v_dtLoopReceiveDate
											ORDER BY SerialNumber 
										END
				
									IF('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
										BEGIN
											UPDATE t_wms_inventory_attribute SET 
												 quantity = ROUND(ROUND(quantity,@Round) + ROUND(@v_fltLoopQtyPick,@Round),@Round) 
											WHERE inventory_id = @v_vchLoopInventoryID 
											AND attribute_group_id = @v_vchLoopAttributeGroupID
											AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL' and is_active = 'YES')
										END
								END
							ELSE
								BEGIN --Insert
									-- insert new serial
									IF(@v_vchSNControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												(inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											SELECT NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('SERIAL'))
												, @v_vchLoopAttributeGroupID
												, SerialNumber
												, 1
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID
											FROM #tSourceInventory
											where ReceiveDate = @v_dtLoopReceiveDate
											ORDER BY SerialNumber
										END
							
									--Insert New Lot Number
									IF(@v_vchLotControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('LOT'))
												, @v_vchLoopAttributeGroupID
												, @in_vchLotNumber
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)				
										END

									--Insert New Expiry Date
									IF(@v_vchExpControl = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('EXPIRY_DATE'))
												, @v_vchLoopAttributeGroupID
												, @in_vchExpiryDate
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute1
									IF(@v_vchAttribute1Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE1'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute1
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute2
									IF(@v_vchAttribute2Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE2'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute2
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute3
									IF(@v_vchAttribute3Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE3'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute3
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute4
									IF(@v_vchAttribute4Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE4'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute4
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END

									--Insert New Attribute5
									IF(@v_vchAttribute5Control = 'FULL')
										BEGIN
											INSERT INTO t_wms_inventory_attribute
												( inv_attribute_id
												, inventory_id
												, inv_attribute_type_id
												, attribute_group_id
												, attribute_value
												, quantity
												, quantity_allocated
												, quantity_incoming
												, create_date
												, create_by)
											VALUES
												( NEWID()
												, @v_vchLoopInventoryID
												, (SELECT dbo.usf_get_wms_inventory_attribute_type('ATTRIBUTE5'))
												, @v_vchLoopAttributeGroupID
												, @in_vchAttribute5
												, ROUND(@v_fltLoopQtyPick,@Round)
												, 0
												, 0
												, GETDATE()
												, @in_vchUserID)
										END
								END
						 
						FETCH NEXT FROM InventoryDest_Cursor INTO @v_dtLoopReceiveDate, @v_dtLoopMfgDate, @v_fltLoopQtyPick
					END
					CLOSE InventoryDest_Cursor                  	
					DEALLOCATE InventoryDest_Cursor

					---------------------------------------------------		
					--Write Tran Log
					---------------------------------------------------	 
					INSERT INTO t_com_tran_log
						( app_id
						, [app_name]
						, tran_type
						, sub_tran_type 
						, [description]
						, start_tran_datetime
						, end_tran_datetime
						, warehouse
						, to_warehouse
						, location
						, to_location
						, [owner]
						, to_owner
						, item_number
						, quantity
						, quantity_uom
						, after_quantity
						, after_quantity_uom
						, lot_number
						, after_lot_number
						, [expiry_date]
						, after_expiry_date
						, serial_number
						, [attribute1]
						, [after_attribute1]
						, [attribute2]
						, [after_attribute2]
						, [attribute3]
						, [after_attribute3]
						, [attribute4]
						, [after_attribute4]
						, [attribute5]
						, [after_attribute5]
						, [user_id]
						, parent_lpn
						, after_parent_lpn
						, lpn
						, after_lpn
						, [status]
						, after_status
						, order_number
						, line_number
						, receive_date
						, mfg_date
						, device
						, create_by
						, create_date
						, pick_location
						, input_quantity
						, input_uom
					)
					SELECT @in_vchApplicationID
						, @v_vchApplicationName
						, 'OO_PICK'
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'MOVE_DEST' ELSE 'SALES_ORDER' END) 
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'User Picking by Order [Auto to Staging]' ELSE 'User Picking by Order' END) 
						, @v_dtStartDate
						, DATEADD(MILLISECOND,2,GETDATE())
						, @v_vchWarehouse
						, @v_vchWarehouse
						, @v_vchLocation
						, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocation ELSE @v_vchForkLocation END) 
						, @v_vchOwner
						, @v_vchOwner
						, @v_vchItemNumber
						, 1
						, @v_vchBaseUom 
						, 0
						, @v_vchBaseUom
						, @in_vchLotNumber
						, @in_vchLotNumber
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						, SerialNumber
						, @in_vchAttribute1
						, @in_vchAttribute1
						, @in_vchAttribute2
						, @in_vchAttribute2
						, @in_vchAttribute3
						, @in_vchAttribute3
						, @in_vchAttribute4
						, @in_vchAttribute4
						, @in_vchAttribute5
						, @in_vchAttribute5
						, @in_vchUserID 
						, @in_vchParentLPN
						, @v_vchStagingParentLPN
						, @in_vchLPN
						, @v_vchStagingLPN
						, @in_vchItemStatus
						, @in_vchItemStatus
						, @v_vchOutboundOrderNumber
						, @v_vchLineNumber
						, ReceiveDate
						, MfgDate
						, @in_vchDeviceID
						, @in_vchUserID
						, DATEADD(MILLISECOND,RowNumber * 10,GETDATE())	--[create_date]
						, @v_vchLocation
						, @in_fltQuantity
						, @v_vchInputUomPrompt
					from #tSourceInventory
					ORDER BY RowNumber

					SET @v_fltSummaryInvPick = @v_fltQtyCanPick
					--------------------------------------------------
					--Insert For Checker RFID : เฉพาะที่ AUTO STG
					--------------------------------------------------
					IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES') AND @RuleAutoStaging = 'YES'
						BEGIN
							IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @in_vchOutboundMasterID AND serial_number IN (SELECT SerialNumber FROM #tSourceInventory))
								BEGIN
									INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
										([checker_rfid_id]
										,[processing_status]
										,[outbound_order_master_id]
										,[serial_number]
										,[user_id]
										,[device]
										,[create_by]
										,[create_date])
									SELECT NEWID()
										,'PENDING'
										,@in_vchOutboundMasterID
										,SerialNumber
										,@in_vchUserID
										,@in_vchDeviceID
										,@in_vchUserID
										,GETDATE()
									FROM #tSourceInventory
								END
						END
				END
			ELSE
				BEGIN
					--------------------------------------------------
					-- Inventory รายการของสินค้าจากที่หยิบมา
					--------------------------------------------------
					DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
					DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
					DECLARE @v_dtInvReceiveDate		DATE = NULL
					DECLARE @v_dtInvMfgDate			DATE = NULL
					DECLARE @v_fltInvQuantity		FLOAT = NULL
					DECLARE @v_fltInvQuantityPick	FLOAT = NULL
					SET @v_fltSummaryInvPick = 0;

					INVENTORY_NEXT:
						SET @v_vchInvID				= NULL;
						SET @v_vchInvAttrGroupID	= NULL;
						SET @v_dtInvReceiveDate	    = NULL; 
						SET @v_dtInvMfgDate		    = NULL;
						SET @v_fltInvQuantity		= NULL;
						SET @v_fltInvQuantityPick	= NULL;
				
						SELECT TOP 1 @v_vchInvID = inventory_id
							,@v_vchInvAttrGroupID = attribute_group_id
							,@v_dtInvReceiveDate = receive_date  
							,@v_dtInvMfgDate = mfg_date
							,@v_fltInvQuantity = ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round)
						FROM v_wms_inventory_data_by_id
						WHERE wh_master_id = @in_vchWhMasterID
						AND owner_id = @in_vchOwnerID
						AND location_id = @in_vchLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND inventory_status_id = @v_vchDefaultItemStatusID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND ROUND(ISNULL(quantity,0) - ISNULL(quantity_allocated,0),@Round) > 0
						ORDER BY receive_date
						IF @v_vchInvID IS NULL
							BEGIN
								-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
								SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
								SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
								GOTO WRITE_PROC;
							END
			
						--Check จำนวนใน Inventory กับจำนวนที่ Pick ถ้าใน Inventory Record นี้จำนวนน้อยกว่า จำนวนที่ Pick = จำนวน Inventory
						IF (@v_fltQtyCanPick > @v_fltInvQuantity)
							BEGIN
								SET @v_fltInvQuantityPick = @v_fltInvQuantity
							END
						ELSE
							BEGIN
								SET @v_fltInvQuantityPick = @v_fltQtyCanPick
							END

						---------------------------------------------------
						-- Get Pick Detail ID
						---------------------------------------------------
						SET @v_vchOutboundPickDetailID = NULL
						SELECT @v_vchOutboundPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
						WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
						AND outbound_order_detail_id = @v_vchOutboundDetailID
						AND location_id = @in_vchLocationID
						AND wh_item_master_id = @in_vchWhItemMasterID
						AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
						AND pick_location_id = @in_vchForkLocationID
						AND ISNULL(pick_to_parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
						AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
						AND receive_date = @v_dtInvReceiveDate

						--------------------------------------------------------
						-- Validate Staging Location and set value staging
						--------------------------------------------------------
						IF (@RuleAutoStaging = 'YES')
							BEGIN
								--Update Outbound Detail
								UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltInvQuantityPick,@Round)
									,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltInvQuantityPick,@Round)
									,item_status = 'PICK'
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE outbound_order_master_id = @in_vchOutboundMasterID 
								AND outbound_order_detail_id = @v_vchOutboundDetailID 
								AND wh_item_master_id = @in_vchWhItemMasterID 
								AND line_number = @v_vchLineNumber

								--SET Value Staging
								SET @v_fltQuantityStage = ROUND(@v_fltInvQuantityPick,@Round)
								SET @v_vchStagingParentLPN = NULL
								SET @v_vchStagingLPN = @v_vchPickToLPN
							END
						ELSE
							BEGIN
								SET @v_vchStagingLocationID = NULL
								SET @v_vchStagingLocation = NULL
								SET @v_fltQuantityStage = 0	
								SET @v_vchStagingParentLPN = NULL	
								SET @v_vchStagingLPN = NULL
								--Update Outbound Detail
								UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltInvQuantityPick,@Round),@Round)
									,item_status = 'PICK'
									,update_by = @in_vchUserID
									,update_date = GETDATE()
								WHERE outbound_order_master_id = @in_vchOutboundMasterID 
								AND outbound_order_detail_id = @v_vchOutboundDetailID 
								AND wh_item_master_id = @in_vchWhItemMasterID 
								AND line_number = @v_vchLineNumber
							END

						-----------------------------------------------------
						-- Insert/Update Pick Detail
						-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ RW to WIP
						-----------------------------------------------------
						IF @v_vchOutboundPickDetailID IS NULL
							BEGIN
								BEGIN--Set Value
									IF (@in_vchParentLPN = '')
										SET @in_vchParentLPN = NULL;
									IF (@in_vchlpn = '')
										SET @in_vchlpn = NULL;
									IF (@in_vchExpiryDate = '')
										SET @in_vchExpiryDate = NULL;
									IF (@in_vchAttribute1 = '')
										SET @in_vchAttribute1 = NULL;
									IF (@in_vchAttribute2 = '')
										SET @in_vchAttribute2 = NULL;
									IF (@in_vchAttribute3 = '')
										SET @in_vchAttribute3 = NULL;
									IF (@in_vchAttribute4 = '')
										SET @in_vchAttribute4 = NULL;
									IF (@in_vchAttribute5 = '')
										SET @in_vchAttribute5 = NULL;
								END

								SELECT @v_vchPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
								IF (@v_vchPickLineNumber IS NULL)
									BEGIN 
										SET @v_vchPickLineNumber = '00001'; 
									END
								ELSE
									BEGIN 
										SET @v_vchPickLineNumber = Right('0000' + Convert(NVARCHAR,@v_vchPickLineNumber + 1),5); 
									END				
			
								SET @v_vchOutboundPickDetailID = NEWID()
								INSERT INTO [dbo].[t_wms_outbound_pick_detail]
										([outbound_pick_detail_id]
										,[outbound_pick_master_id]
										,[outbound_order_detail_id]
										,[pick_line_number]
										,[location_id]
										,[pick_location_id]
										,[pick_to_lpn]
										,[pick_to_parent_lpn]
										,[wh_item_master_id]
										,[quantity_plan]
										,[quantity_pick] 
										,[quantity_stage]
										,[quantity_pack]
										,[quantity_load]
										,[quantity_ship] 
										,[parent_lpn]
										,[lpn]
										,[lot_number]
										,[expiry_date]
										,[serial_number]
										,[attribute1]
										,[attribute2]
										,[attribute3]
										,[attribute4]
										,[attribute5] 
										,[staging_location_id]
										,[staging_parent_lpn]
										,[staging_lpn] 
										,[pick_status]
										,[load_status]
										,[ship_status]
										,[inventory_id]
										,[pack_status]
										,[pick_generate_method]
										,[is_allocate]
										,[is_override]
										,[receive_date]
										,[mfg_date]
										,[is_active]
										,[start_date_time]
										,[end_date_time]
										,[create_date]
										,[create_by])
									VALUES
										(@v_vchOutboundPickDetailID
										,@v_vchOutboundPickMasterID
										,@v_vchOutboundDetailID
										,@v_vchPickLineNumber
										,@in_vchLocationID
										,@in_vchForkLocationID
										,@v_vchPickToLPN
										,@in_vchParentLPN
										,@in_vchWhItemMasterID
										,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_plan]
										,ROUND(@v_fltInvQuantityPick,@Round)	--[quantity_pick] 
										,ROUND(@v_fltQuantityStage,@Round)		--[quantity_stage]
										,0										--[quantity_pack]
										,0										--[quantity_load]
										,0										--[quantity_ship] 
										,@in_vchParentLPN						--[parent_lpn]
										,@in_vchlpn								--[lpn]
										,@in_vchLotNumber						--[lot_number]
										,case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end	--[expiry_date]
										,NULL
										,@in_vchAttribute1				
										,@in_vchAttribute2
										,@in_vchAttribute3
										,@in_vchAttribute4
										,@in_vchAttribute5 
										,@v_vchStagingLocationID			--[staging_location_id]
										,@v_vchStagingParentLPN				--[staging_parent_lpn]
										,@v_vchStagingLPN					--[staging_lpn] 
										,'YES'								--[pick_status]
										,'NO'								--[load_status]
										,'NO'								--[ship_status]
										,@v_vchInvID						--[inventory_id]
										,'NO'								--[pack_status]
										,'USER_PICK_ORDER'					--[pick_generate_method]
										,'YES'								--[is_allocate]
										,'NO'								--[is_override] 
										,@v_dtInvReceiveDate
										,@v_dtInvMfgDate
										,'YES'								--[is_active]
										,GETDATE()							--[start_date_time]
										,GETDATE()							--[end_date_time]
										,GETDATE()							--[create_date]
										,@in_vchUserID)						--[create_by])
							END
						ELSE
							BEGIN
								UPDATE t_wms_outbound_pick_detail SET 
  									  quantity_plan		 = ROUND((ISNULL(quantity_plan,0) +  @v_fltInvQuantityPick),@Round) 
									, quantity_pick		 = ROUND((ISNULL(quantity_pick,0) +  @v_fltInvQuantityPick),@Round) 
									, quantity_stage	 = ROUND((ISNULL(quantity_stage,0) + @v_fltQuantityStage),@Round)
									, pick_location_id   = @in_vchForkLocationID
									, pick_to_parent_lpn = @in_vchParentLPN
									, pick_to_lpn		 = @v_vchPickToLPN
									, pick_status        = 'YES'
									, start_date_time	 = ISNULL(start_date_time,GETDATE())
									, end_date_time		 = GETDATE()
								WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
							END

						---------------------------------------------------
						--Insert/Update Pack Detail
						---------------------------------------------------
						IF @RulePickPack = 'YES'
							BEGIN
								UPDATE t_wms_outbound_pick_detail SET 
									  quantity_pack = ROUND((ISNULL(quantity_pack,0) + @v_fltInvQuantityPick),@Round)
									, end_date_time = GETDATE()
								WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

								---------------------------------------------------
								--Insert/Update Pack Detail
								---------------------------------------------------
								PRINT 'Pick and Pack'
								IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
													WHERE outbound_order_master_id = @in_vchOutboundMasterID
													AND pack_location_id = @in_vchForkLocationID
													AND lpn_pack = @v_vchPickToLPN 
													AND wh_item_master_id = @in_vchWhItemMasterID 
													AND outbound_pick_detail_id = @v_vchOutboundPickDetailID)
									BEGIN
										UPDATE t_wms_outbound_pack_detail SET 
											 quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltInvQuantityPick,@Round)
											,quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
										WHERE outbound_order_master_id = @in_vchOutboundMasterID 
										AND pack_location_id = @in_vchForkLocationID
										AND lpn_pack = @v_vchPickToLPN 
										AND wh_item_master_id = @in_vchWhItemMasterID 
										AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
									END
								ELSE
									BEGIN
										INSERT INTO t_wms_outbound_pack_detail
										(     outbound_order_master_id
											, outbound_pick_detail_id
											, lpn_pack
											, pack_location_id
											, wh_item_master_id
											, quantity_pack
											, quantity_stage
											, lot_number
											, expiry_date
											, serial_number
											, [attribute1]
											, [attribute2]
											, [attribute3]
											, [attribute4]
											, [attribute5]
											, item_uom_id
											, staging_parent_lpn
											, staging_lpn
											, staging_location_id
											, create_by
										)
										VALUES
										(     @in_vchOutboundMasterID
											, @v_vchOutboundPickDetailID
											, @v_vchPickToLPN
											, @in_vchForkLocationID
											, @in_vchWhItemMasterID
											, ROUND(@v_fltInvQuantityPick,@Round)
											, @v_fltQuantityStage
											, @in_vchLotNumber
											, case when @in_vchExpiryDate = '' then NULL else @in_vchExpiryDate end
											, NULL
											, @in_vchAttribute1
											, @in_vchAttribute2
											, @in_vchAttribute3
											, @in_vchAttribute4
											, @in_vchAttribute5
											, @v_vchBaseItemUomID
											, @v_vchStagingParentLPN
											, @v_vchStagingLPN
											, @v_vchStagingLocationID
											, @in_vchUserID
										)
									END
							END
				
						---------------------------------------------------
						--Calculate Volumn & Weight
						---------------------------------------------------
						IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
						BEGIN
							SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltInvQuantityPick,2)
							SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltInvQuantityPick,2)
						END

						---------------------------------------------------
						-- Manage source location data
						---------------------------------------------------
						BEGIN
							--Update Volumn & Weight in from location
							IF @in_vchLocationID IS NOT NULL
								BEGIN
									UPDATE [dbo].[t_wms_location] SET
									      total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
										, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID   
									WHERE [location_id] = @in_vchLocationID
								END

							UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
								,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInvID 
							AND attribute_group_id = @v_vchInvAttrGroupID

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltInvQuantityPick,@Round)
									WHERE inventory_id = @v_vchInvID 
									AND attribute_group_id = @v_vchInvAttrGroupID
									AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END
						END

						------------------------------------------------
						-- Clear Inventory ที่หยิบของหมดแล้ว
						------------------------------------------------
						DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInvID 
						DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInvID 

						---------------------------------------------------
						-- Manage destination location data
						---------------------------------------------------			
						BEGIN
							SET @v_vchInvID = NULL
							SET @v_vchInvAttrGroupID = NULL 
							DECLARE @v_vchDestLocationID UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchDestParentLPN  NVARCHAR(25) = NULL
							DECLARE @v_vchDestLPN		 NVARCHAR(25) = NULL
							SET @v_vchDestLocationID = (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocationID ELSE @in_vchForkLocationID END)
							SET @v_vchDestParentLPN  = (CASE WHEN @RuleAutoStaging = 'YES' THEN ISNULL(@v_vchStagingParentLPN,'') ELSE '' END)
							SET @v_vchDestLPN		 = (CASE WHEN @RuleAutoStaging = 'YES' THEN ISNULL(@v_vchStagingLPN,'') ELSE ISNULL(@v_vchPickToLPN,'') END)

							SELECT @v_vchInvID = inventory_id
								,@v_vchInvAttrGroupID = attribute_group_id 
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @in_vchWhMasterID
							AND owner_id = @in_vchOwnerID
							AND location_id = @v_vchDestLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @v_vchDefaultItemStatusID
							and receive_date = @v_dtInvReceiveDate
							AND ISNULL(parent_lpn,'') = @v_vchDestParentLPN
							AND ISNULL(lpn,'')		  = @v_vchDestLPN
							AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

							EXEC usp_manage_inventory @in_vchWhMasterID		  = @in_vchWhMasterID
													, @in_vchOwnerID		  = @in_vchOwnerID
													, @in_vchWhItemMasterID	  = @in_vchWhItemMasterID
													, @in_vchLocationID		  = @v_vchDestLocationID 
													, @in_vchStatusID		  = @v_vchDefaultItemStatusID
													, @in_vchPalentLPN		  = @v_vchDestParentLPN
													, @in_vchLPN			  = @v_vchDestLPN 
													, @in_fltQty			  = @v_fltInvQuantityPick
													, @in_fltQtyAllocate	  = 0
													, @in_fltQtyIncoming	  = 0
													, @in_vchInventoryType	  = @v_vchOutboundOrderNumber
													, @in_vchUserID			  = @in_vchUserID
													, @in_vchReceiveDate	  = @v_dtInvReceiveDate	
													, @in_dtMfgDate			  = @v_dtInvMfgDate
													, @in_vchInventoryID	  = @v_vchInvID OUTPUT
													, @in_vchAttributeGroupID = @v_vchInvAttrGroupID OUTPUT	
													, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
													, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;

							--Update Volumn & Weight in from location
							IF @v_vchDestLocationID IS NOT NULL  
								BEGIN
									UPDATE [dbo].[t_wms_location] SET 
										  total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
										, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID 
									WHERE [location_id] = @v_vchDestLocationID
								END

							--update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET 
								volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInvID
							AND attribute_group_id = @v_vchInvAttrGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
										  @in_vchLot				= @in_vchLotNumber
										, @in_vchExpiryDate			= @in_vchExpiryDate
										, @in_vchSerialNo			= NULL
										, @in_vchAttribute1			= @in_vchAttribute1
										, @in_vchAttribute2			= @in_vchAttribute2
										, @in_vchAttribute3			= @in_vchAttribute3
										, @in_vchAttribute4			= @in_vchAttribute4
										, @in_vchAttribute5			= @in_vchAttribute5
										, @in_fltQty				= @v_fltInvQuantityPick
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInvID
										, @in_vchAttributeGroupID	= @v_vchInvAttrGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END
						END

						---------------------------------------------------		
						--Write Tran Log OO_PICK To Staging
						---------------------------------------------------	 
						INSERT INTO t_com_tran_log
							( app_id
							, [app_name]
							, tran_type
							, sub_tran_type 
							, [description]
							, start_tran_datetime
							, end_tran_datetime
							, warehouse
							, to_warehouse
							, location
							, to_location
							, [owner]
							, to_owner
							, item_number
							, quantity
							, quantity_uom
							, after_quantity
							, after_quantity_uom
							, lot_number
							, after_lot_number
							, [expiry_date]
							, after_expiry_date
							, serial_number
							, [attribute1]
							, [after_attribute1]
							, [attribute2]
							, [after_attribute2]
							, [attribute3]
							, [after_attribute3]
							, [attribute4]
							, [after_attribute4]
							, [attribute5]
							, [after_attribute5]
							, [user_id]
							, parent_lpn
							, after_parent_lpn
							, lpn
							, after_lpn
							, [status]
							, after_status
							, order_number
							, line_number
							, receive_date
							, mfg_date
							, device
							, create_by
							, create_date
							, pick_location
							, input_quantity
							, input_uom
						)
						VALUES
						(  @in_vchApplicationID
							, @v_vchApplicationName
							, 'OO_PICK'
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'MOVE_DEST' ELSE 'SALES_ORDER' END) 
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN 'User Picking by Order [Auto to Staging]' ELSE 'User Picking by Order' END) 
							, @v_dtStartDate
							, DATEADD(MILLISECOND,2,GETDATE())
							, @v_vchWarehouse
							, @v_vchWarehouse
							, @v_vchLocation
							, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocation ELSE @v_vchForkLocation END) 
							, @v_vchOwner
							, @v_vchOwner
							, @v_vchItemNumber
							, @v_fltInvQuantityPick
							, @v_vchBaseUom
							, @v_fltInvQuantity - @v_fltInvQuantityPick
							, @v_vchBaseUom
							, @in_vchLotNumber
							, @in_vchLotNumber
							, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
							, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
							, NULL
							, @in_vchAttribute1
							, @in_vchAttribute1
							, @in_vchAttribute2
							, @in_vchAttribute2
							, @in_vchAttribute3
							, @in_vchAttribute3
							, @in_vchAttribute4
							, @in_vchAttribute4
							, @in_vchAttribute5
							, @in_vchAttribute5
							, @in_vchUserID 
							, @in_vchParentLPN
							, @v_vchStagingParentLPN
							, @in_vchLPN
							, @v_vchStagingLPN
							, @in_vchItemStatus
							, @in_vchItemStatus
							, @v_vchOutboundOrderNumber
							, @v_vchLineNumber
							, @v_dtInvReceiveDate
							, @v_dtInvMfgDate
							, @in_vchDeviceID
							, @in_vchUserID
							, GETDATE()	--[create_date]
							, @v_vchLocation
							, @in_fltQuantity
							, @v_vchInputUomPrompt
						)
					 

					--สำหรับรวมจำนวนที่ pick ของจาก inventory ในแต่ละรอบ
					SET @v_fltSummaryInvPick = @v_fltSummaryInvPick + @v_fltInvQuantityPick

					--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
					SET @v_fltQtyCanPick = @v_fltQtyCanPick - @v_fltInvQuantityPick

					--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
					IF @v_fltQtyCanPick > 0
						GOTO INVENTORY_NEXT;
				END

			-- For Dashboard
			BEGIN
				DECLARE @v_vchDSToLocationID UNIQUEIDENTIFIER = NULL 
				IF @RuleAutoStaging = 'YES'
					BEGIN
						SET @v_vchDSToLocationID = @v_vchStagingLocationID 
					END
				ELSE
					BEGIN  
						SET @v_vchDSToLocationID = @in_vchForkLocationID 
					END
				EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
												,@in_vchTransType	 = 'PICK'
												,@in_vchWhMasterID	 = @in_vchWhMasterID
												,@in_vchOwnerID		 = @in_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwner
												,@in_vchLocationID	 = @in_vchLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
												,@in_vchToWhMasterID = @in_vchWhMasterID
												,@in_vchToLocationID = @v_vchDSToLocationID
												,@in_vchToInvStatusID = @v_vchDefaultItemStatusID
												,@in_fltQuantity	 = @v_fltSummaryInvPick
												,@in_vchUserID		 = @in_vchUserID
			END

			-------------------------------------------------------------------------------
			-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
			-------------------------------------------------------------------------------
			SET @v_fltBaseInputQuantity = @v_fltBaseInputQuantity - @v_fltSummaryInvPick
			IF @v_fltBaseInputQuantity = 0
				BREAK;
	
			FETCH NEXT FROM OutboundDetail_Cursor INTO @v_vchOutboundDetailID,@v_vchLineNumber,@v_fltQuantityOrder,@v_fltQuantityPick
		END
		CLOSE OutboundDetail_Cursor
		DEALLOCATE OutboundDetail_Cursor

		------------------------------------------------
		-- Update Order Status ถ้า Pick ครบแล้ว
		------------------------------------------------
		IF ((SELECT SUM(quantity_order) - SUM(quantity_pick) FROM t_wms_outbound_detail obDT WHERE outbound_order_master_id = @in_vchOutboundMasterID) = 0)
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @in_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
			END

		---------------------------------------------------------
		-- Auto Create Inbound Plan and Receipt
		---------------------------------------------------------
		EXEC usp_inbound_insert_order @in_vchApplicationID	     = @in_vchApplicationID
										,@in_vchDeviceID		 = @in_vchDeviceID	
										,@in_vchUserID			 = @in_vchUserID	
										,@in_vchWhMasterID		 = @in_vchWhMasterID
										,@in_vchOrderNumber		 = @v_vchOutboundOrderNumber
										,@in_vchLocation		 = @v_vchLocation
										,@in_vchParentLPN		 = @in_vchParentLPN
										,@in_vchLPN				 = @v_vchPickToLPN
										,@in_vchItemNumber		 = @v_vchItemNumber
										,@in_vchLotNumber		 = @in_vchLotNumber
										,@in_vchExpiryDate		 = @in_vchExpiryDate
										,@in_vchSerialNumber	 = @in_vchSerialNumber
										,@in_fltQuantity		 = @v_fltBaseInputQuantity
										,@in_vchUOMPrompt		 = @v_vchBaseUom
										,@in_vchDefaultItemStatus = @in_vchItemStatus
										,@in_vchAttribute1		 = @in_vchAttribute1
										,@in_vchAttribute2		 = @in_vchAttribute2
										,@in_vchAttribute3		 = @in_vchAttribute3
										,@in_vchAttribute4		 = @in_vchAttribute4
										,@in_vchAttribute5		 = @in_vchAttribute5
										,@out_vchErrorCode		 = @out_ErrorCode OUTPUT
										,@out_vchErrorMsg		 = @out_ErrorMessage OUTPUT
		IF (@out_ErrorCode <> 0)
			BEGIN
				GOTO WRITE_PROC;
			END

		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = 0;
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5') 
		RETURN;
	
---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','OutboundDetail_Cursor')>=-1
		BEGIN
			CLOSE OutboundDetail_Cursor;
			DEALLOCATE OutboundDetail_Cursor;
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQuantity) + ' ' + @v_vchInputUomPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @v_vchLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','OutboundDetail_Cursor')>=-1
		BEGIN
			CLOSE OutboundDetail_Cursor;
			DEALLOCATE OutboundDetail_Cursor;
		END

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();

	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQuantity) + ' ' + @v_vchInputUomPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @v_vchLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_loading]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-02-05
-- Description:	Loading lpn to dock door
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_loading]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(10),
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchLocation				NVARCHAR(50),
	@in_vchDockDoor				NVARCHAR(50),
	@in_dtContainerOpenDateTime	DATETIME,
	@in_vchParentLPN			NVARCHAR(25) = null,
	@in_vchLPN					NVARCHAR(25) = null,
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_loading]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
		
		@v_vchOutboundMasterID		VARCHAR(40),
		@v_vchOutboundDetailID		VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	VARCHAR(40),
		@v_vchOutboundPackDetailID	VARCHAR(40),
		@v_vchOrderStatus			NVARCHAR(10),
		@v_fltQtyStaging			FLOAT,
		@v_vchLineNumber			NVARCHAR(5),
		@v_vchItemNumber			NVARCHAR(50),
		@v_vchUomPrompt				NVARCHAR(25),
		
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(50),
		@v_vchSerialNumber			NVARCHAR(50),
		
		@v_vchWarehouseMasterID		VARCHAR(40),
		@v_vchStagingLocationID		VARCHAR(40),
		@v_vchDockDoorID			VARCHAR(40),
		@v_vchLoadStatus			NVARCHAR(10),
		
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchWarehouseItemMasterID	VARCHAR(40),
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchReceiveDate			DATE,
		@v_fltBaseQuantity			FLOAT,
		@v_fltSStockQuantity		FLOAT = 0,
		@v_fltDStockQuantity		FLOAT = 0,
		--@v_vchTLocationMasterID		NVARCHAR(40),
		@v_vchInventoryType			NVARCHAR(25) = 'INVENTORY',
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchOwner					NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		-- add new 2014-01-13
		@v_vchPickPack				NVARCHAR(3),
		@cursorOutboundPickDetail	CURSOR,
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(max) = ''
	
	select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
	
	BEGIN TRY
		If (isnull(@in_vchParentLPN,'') = '')
			Begin
				select TOP 1 @in_vchParentLPN = parent_lpn from t_wms_inventory where wh_master_id = @v_vchWarehouseMasterID and lpn = @in_vchLPN
			End

		select @v_vchPickPack = value from t_wms_rule where rule_code = 'RULE_PICK_PACK'
		If ((@v_vchPickPack) = 'YES')
			Begin
				set @v_vchDynamicSQL =
						'
						select	order_status,quantity_pack,line_number,outbound_order_master_id,outbound_pick_master_id,
								outbound_order_detail_id,outbound_pick_detail_id,item_number,lot_number,[expiry_date],uom_prompt,load_status,
								outbound_pack_detail_id,owner_id
						from	v_wms_outbound_pack_detail
						where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber and staging_location = @in_vchLocation
						and isnull(staging_parent_lpn,'''') = isnull(@in_vchParentLPN,'''') and lpn_pack = @in_vchLPN
						';
			End
		Else
			Begin
				set @v_vchDynamicSQL =
						'
						select	order_status,quantity_pack,line_number,outbound_order_master_id,outbound_pick_master_id,
								outbound_order_detail_id,outbound_pick_detail_id,item_number,lot_number,[expiry_date],uom_prompt,load_status,
								'' as outbound_pack_detail_id,owner_id
						from	v_wms_outbound_pick_detail
						where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber and staging_location = @in_vchLocation
								and isnull(staging_parent_lpn,'''') = isnull(@in_vchParentLPN,'''') and isnull(staging_lpn,'''') = isnull(@in_vchLPN,'''')
						';
			End

		set @v_vchDynamicSQL = ' set @cursorOutboundPickDetail = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @cursorOutboundPickDetail'								
		set @v_vchParameterDefinition = '@in_vchWarehouse nvarchar(25),@in_vchOutboundOrderNumber nvarchar(50),@in_vchLocation nvarchar(50),@in_vchParentLPN nvarchar(50),@in_vchLPN nvarchar(50),@cursorOutboundPickDetail CURSOR OUTPUT';
		Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@in_vchWarehouse,@in_vchOutboundOrderNumber,@in_vchLocation,@in_vchParentLPN,@in_vchLPN,@cursorOutboundPickDetail OUTPUT

		fetch @cursorOutboundPickDetail into @v_vchOrderStatus,@v_fltQtyStaging,@v_vchLineNumber,@v_vchOutboundMasterID,
						@v_vchOutboundPickMasterID,@v_vchOutboundDetailID,@v_vchOutboundPickDetailID,
						@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_vchUomPrompt,@v_vchLoadStatus,@v_vchOutboundPackDetailID,@v_vchOwnerID

		--If ((select value from t_wms_rule where rule_code = 'RULE_PICK_PACK') = 'YES')
		--	Begin
		--		select	@v_vchOrderStatus = order_status,@v_fltQtyStaging = quantity_pack,@v_vchLineNumber = line_number,
		--				@v_vchOutboundMasterID = outbound_order_master_id,@v_vchOutboundPickMasterID = outbound_pick_master_id,
		--				@v_vchOutboundDetailID = outbound_order_detail_id,@v_vchOutboundPickDetailID = outbound_pick_detail_id,
		--				@v_vchItemNumber = item_number,@v_vchLotNumber = lot_number,@v_vchExpiryDate = [expiry_date],@v_vchUomPrompt = uom_prompt,@v_vchLoadStatus = load_status
		--		from	v_wms_outbound_pack_detail
		--		where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber and staging_location = @in_vchLocation
		--				and isnull(staging_parent_lpn,'') = isnull(@in_vchParentLPN,'') and lpn_pack = @in_vchLPN
		--	End
		--Else
		--	Begin
		--		select	@v_vchOrderStatus = order_status,@v_fltQtyStaging = quantity_pack,@v_vchLineNumber = line_number,
		--				@v_vchOutboundMasterID = outbound_order_master_id,@v_vchOutboundPickMasterID = outbound_pick_master_id,
		--				@v_vchOutboundDetailID = outbound_order_detail_id,@v_vchOutboundPickDetailID = outbound_pick_detail_id,
		--				@v_vchItemNumber = item_number,@v_vchLotNumber = lot_number,@v_vchExpiryDate = [expiry_date],@v_vchUomPrompt = uom_prompt,@v_vchLoadStatus = load_status
		--		from	v_wms_outbound_pick_detail
		--		where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber and staging_location = @in_vchLocation
		--				and isnull(staging_parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(staging_lpn,'') = isnull(@in_vchLPN,'')
		--	End

		If (@v_vchOrderStatus is null)
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,@in_vchLocation,@in_vchParentLPN,@in_vchLPN,'@param5')
				Goto WRITE_PROC;
			End
		Else If(@v_vchOrderStatus = 'SHIP')
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		Else If (@v_vchLoadStatus = 'YES')
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_LOADED',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLPN,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		Else
			Begin

				select @v_vchStagingLocationID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchLocation
				select @v_vchDockDoorID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchDockDoor
				
				BEGIN TRANSACTION
				While @@FETCH_STATUS = 0
					Begin
					SET @v_vchBeginTrans = 1;

					select	@v_vchItemNumber = item_number,@v_vchLotNumber = lot_number,@v_vchExpiryDate = [EXPIRY_DATE],@v_vchSerialNumber = SERIAL_NUMBER ,
							@v_vchWarehouseItemMasterID = wh_item_master_id,@v_vchInventoryStatus = inv_status,@v_vchInventoryID = inventory_id,@v_vchAttributeGroupID = attribute_group_id,
							@v_vchToInventoryStatusID = inventory_status_id,@v_vchOwner = owner_id,@v_vchReceiveDate = receive_date,@v_fltSStockQuantity = quantity
					from	v_wms_inventory_data 
					where	wh_master_id = @v_vchWarehouseMasterID and location = @in_vchLocation 
							and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and lpn = @in_vchLPN and isnull(lot_number,'') = isnull(@v_vchLotNumber,'') and isnull(expiry_date,'') = isnull(@v_vchExpiryDate,'')
					
					---- not have inventory data
					If (@v_vchInventoryID is null)
						Begin
							set @out_ErrorCode = '989';
							select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_MOVE_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLocation,@v_vchItemNumber,@in_vchLPN,'@param4','@param5')
							Goto WRITE_PROC;
						End
					
					select @v_vchItemMasterID = item_master_id,@v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control from t_wms_item where item_number = @v_vchItemNumber and owner_id = @v_vchOwnerID
							
					select @v_fltBaseQuantity = @v_fltQtyStaging * conversion_factor from t_wms_item_uom where item_master_id = @v_vchItemMasterID and (uom = @v_vchUOMPrompt or uom_prompt = @v_vchUOMPrompt) 
					
					-- Quantity not enough
					If ((@v_fltSStockQuantity < @v_fltBaseQuantity))
						Begin
							set @out_ErrorCode = '989';
							select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchLocation,'@param3','@param4','@param5')
							Goto WRITE_PROC;							
						End
				
					-- add new 2014-01-10 ตรวจสอบ serial ว่ามีครบ
					If (@v_vchSerialControl = 'FULL')
						Begin
							If Exists(
								select serial_number from t_wms_outbound_pick_serial_detail where outbound_pick_detail_id = @v_vchOutboundPickDetailID
										and (staging_location_id = @v_vchStagingLocationID)
										and (isnull(staging_parent_lpn,'') = isnull(@in_vchParentLPN,'')) and (isnull(staging_lpn,'') = isnull(@in_vchLPN,''))
								and serial_number not in
								(select serial_number from v_wms_inventory_data_by_serial where location_id = @v_vchStagingLocationID
								and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchLPN,''))
								)
								Begin
									set @out_ErrorCode = '999';
									select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_PICK_NOT_MATCH_ON_INVENTORY',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchParentLPN,@in_vchLPN,'@param3','@param4','@param5')
									Goto WRITE_PROC;
								End
						End

					---- manage source location data
					--update t_wms_inventory set quantity = quantity - @v_fltBaseQuantity where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
					--update t_wms_inventory_attribute set quantity = quantity - @v_fltBaseQuantity where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID

					---- manage destination location data
					--Begin
					--	set @v_vchInventoryID = null;
					--	set @v_vchAttributeGroupID = null;
					--	set @v_fltDStockQuantity = 0;
						
					--	--select @v_vchTLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchDockDoor
						
					--	select	@v_vchInventoryID = inventory_id,
					--			@v_vchAttributeGroupID = attribute_group_id,
					--			@v_fltDStockQuantity = quantity
					--	from	v_wms_inventory_data
					--	where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID 
					--			and location_id = @v_vchDockDoorID and isnull(lpn,'') = isnull(@in_vchLPN,'')
					--			and isnull(lot_number,'') = isnull(@v_vchLOTNumber,'') and isnull([EXPIRY_DATE],'') = isnull(@v_vchExpiryDate,'')
					--			and isnull(SERIAL_NUMBER,'') = isnull(@v_vchSerialNumber,'')
							
					--	exec usp_manage_inventory
					--			@in_vchApplicationID = @in_vchApplicationID,
					--			@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
					--			@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID,
					--			@in_vchLocationID = @v_vchDockDoorID,
					--			@in_vchLocation = @in_vchDockDoor,
					--			@in_vchStatusID = @v_vchToInventoryStatusID,
					--			@in_vchLPN = @in_vchLPN,
					--			@in_vchLotNumber = @v_vchLOTNumber,
					--			@in_vchExpiryDate = @v_vchExpiryDate,
					--			@in_vchSerialNumber = @@CONNECTIONS,
					--			@in_fltQty = @v_fltBaseQuantity,
					--			@in_fltQtyAllocate = 0,
					--			@in_vchOwner = @v_vchOwner,
					--			@in_vchInventoryType = @v_vchInventoryType,
					--			@in_vchPalentLPN = null,
					--			@in_vchUserID = @in_vchUserID,
					--			@in_vchReceiveDate = @v_vchReceiveDate,
					--			@in_vchInventoryID = @v_vchInventoryID output,
					--			@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
					--			@in_vchErrorCode = @out_ErrorCode output,
					--			@in_vchMessage = @out_ErrorMessage output
					--	If (@out_ErrorCode <> '0')
					--		Goto WRITE_PROC;
							
					--	If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
					--		Begin
					--			exec usp_manage_inventory_attribute
					--					@in_vchApplicationID = @in_vchApplicationID,
					--					@in_vchItem = @v_vchItemNumber,
					--					@in_vchSerialNo = @v_vchSerialNumber,
					--					@in_vchLot = @v_vchLOTNumber,
					--					@in_vchExpiryDate = @v_vchExpiryDate,
					--					@in_fltQty = @v_fltBaseQuantity,
					--					@in_fltQtyAllocate = 0,
					--					@in_vchInventoryID = @v_vchInventoryID,
					--					@in_vchAttributeGroupID = @v_vchAttributeGroupID,
					--					@in_vchLotControl = @v_vchLotControl,
					--					@in_vchSerialNumberControl = @v_vchSerialControl,
					--					@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
					--					@in_vchUserID = @in_vchUserID,
					--					@in_vchErrorCode = @out_ErrorCode output,
					--					@in_vchMessage = @out_ErrorMessage output			
					--			If(@out_ErrorCode <> '0')
					--				Goto WRITE_PROC;
					--		End			
					--End
					
					update t_wms_inventory set location_id = @v_vchDockDoorID
					where wh_master_id = @v_vchWarehouseMasterID and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchLPN,'')
					and wh_item_master_id = @v_vchWarehouseItemMasterID and location_id = @v_vchStagingLocationID

					insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
					start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
					[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
					lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
					reference_number, control_number,parent_lpn,after_parent_lpn, lpn, after_lpn, [status], after_status, zone, order_number, 
					line_number, device, create_by)
					values(@in_vchApplicationID,'OO_LOAD','SALES_ORDER',null,'Loading lpn to Dock door.',
					GETDATE(),GETDATE(),@in_vchWarehouse,null,@in_vchLocation,@in_vchDockDoor,
					@v_vchOwner,null, @v_vchItemNumber,@v_fltQtyStaging,@v_vchUomPrompt,@v_fltBaseQuantity - @v_fltSStockQuantity,@v_vchUomPrompt,
					@v_vchLotNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_vchExpiryDate,@v_vchSerialNumber,@in_vchUserID,null,null,@in_vchParentLPN,null,@in_vchLPN,@in_vchLPN,@v_vchInventoryStatus,@v_vchInventoryStatus,
					null,@in_vchOutboundOrderNumber,@v_vchLineNumber,@in_vchDeviceID,@in_vchUserID)
					
					-- End add inventory not call Inventory Control
					
					If ((@v_vchPickPack) = 'YES')
						Begin
							update t_wms_outbound_pack_detail
							set dock_door_id = @v_vchDockDoorID,dock_door_parent_lpn = null,dock_door_lpn = @in_vchLPN,load_status = 'YES'
							where outbound_pack_detail_id = @v_vchOutboundPackDetailID
						End
									
					update t_wms_outbound_pick_detail set quantity_load = quantity_load + @v_fltQtyStaging,dock_door_id = @v_vchDockDoorID
					,dock_door_lpn = @in_vchLPN,load_status = 'YES'
					where outbound_pick_master_id = @v_vchOutboundPickMasterID and outbound_pick_detail_id = @v_vchOutboundPickDetailID
					
					update t_wms_outbound_detail set quantity_load = quantity_load + @v_fltQtyStaging,item_status = 'LOAD'
					where outbound_order_master_id = @v_vchOutboundMasterID and outbound_order_detail_id = @v_vchOutboundDetailID
					
					If (@v_vchSerialControl = 'FULL')
						Begin
							update t_wms_outbound_pick_serial_detail set quantity_load = 1,dock_door_id = @v_vchDockDoorID,
							dock_door_parent_lpn = null,dock_door_lpn = @in_vchLPN,load_status = 'YES'
							where outbound_pick_detail_id = @v_vchOutboundPickDetailID and isnull(staging_parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(staging_lpn,'') = isnull(@in_vchLPN,'')
						End

					If (@v_vchOrderStatus <> 'LOAD')
						Begin
							update t_wms_outbound_master set order_status = 'LOAD' ,loading_date_actual = @in_dtContainerOpenDateTime
							where wh_master_id = @v_vchWarehouseMasterID and outbound_order_master_id = @v_vchOutboundMasterID
						End
					
					fetch @cursorOutboundPickDetail into @v_vchOrderStatus,@v_fltQtyStaging,@v_vchLineNumber,@v_vchOutboundMasterID,
						@v_vchOutboundPickMasterID,@v_vchOutboundDetailID,@v_vchOutboundPickDetailID,@v_vchItemNumber,
						@v_vchLotNumber,@v_vchExpiryDate,@v_vchUomPrompt,@v_vchLoadStatus,@v_vchOutboundPackDetailID,@v_vchOwnerID
					End-- end while

				Close @cursorOutboundPickDetail
				Deallocate @cursorOutboundPickDetail

				COMMIT TRANSACTION

				set @out_ErrorCode = '0';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				
				delete from t_wms_inventory where quantity = 0 and quantity_allocated = 0
				delete from t_wms_inventory_attribute where quantity = 0 and quantity_allocated = 0

				RETURN;
			End
	
		-----------------------------------------------------------------------------------
		--							Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
				
				IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
				BEGIN
					Close @cursorOutboundPickDetail;
					Deallocate @cursorOutboundPickDetail;
				END

				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = getdate();
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchOutboundOrderNumber,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		End
	
	END TRY
	BEGIN CATCH
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;

		IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
			BEGIN
				Close @cursorOutboundPickDetail;
				Deallocate @cursorOutboundPickDetail;
			END

		If (isnull(@out_ErrorCode,'') = '')
			set @out_ErrorCode = ERROR_NUMBER();
		If (isnull(@out_ErrorMessage,'') = '')
			set @out_ErrorMessage = ERROR_MESSAGE();
	END CATCH
END



