/****** Object:  StoredProcedure [dbo].[usp_outbound_location_picking]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_location_picking] 
	-- Add the parameters for the stored procedure here
	@in_vchOutboundOrderCode	VARCHAR(40),
	@in_vchLocalID				VARCHAR(40),
	@in_vchWareHouseMasterID	VARCHAR(40),
	@in_vchLocationID			VARCHAR(40),
	@out_RuleValue				NVARCHAR(3) output,
	@out_ErrorMessage			VARCHAR(max) output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	DECLARE @v_nCount			int = null, 
			@in_pick_location	VARCHAR(40) = null,
			@in_code			varchar(40) = null,
			@v_ErroCode			VARCHAR(100),
			@v_vchlocation		VARCHAR(50)

    -- Insert statements for procedure here
	SELECT TOP(1) @v_vchlocation = location
	FROM dbo.v_wms_outbound_pick_detail
	WHERE outbound_order_number = @in_vchOutboundOrderCode
	AND wh_master_id = @in_vchWareHouseMasterID
	AND location = @in_vchLocationID
	
	IF(@@ROWCOUNT = 0)	
	    BEGIN
			SET @v_ErroCode = 'INVALID_LOCATION'
		END
	Else
		BEGIN
			SELECT TOP(1) @in_pick_location = pick_location
	        FROM dbo.v_wms_outbound_pick_detail
			WHERE outbound_order_number = @in_vchOutboundOrderCode
			AND wh_master_id = @in_vchWareHouseMasterID
			AND location = @in_vchLocationID
			
			IF(@in_pick_location  IS NULL)
				BEGIN
					SET @in_code = '1'
				END
			Else
				BEGIN
					SELECT @out_RuleValue = value FROM t_wms_rule WHERE rule_code = 'RULE_SCAN_PARENT_LPN'
				END
		END
		SELECT @out_ErrorMessage = dbo.fn_get_resource(@in_vchLocalID,@v_ErroCode)
END


