/****** Object:  StoredProcedure [dbo].[usp_outbound_modern_trade_allow_mix_lot]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_modern_trade_allow_mix_lot]
	@in_vchQueryString			NVARCHAR(4000),
	@in_vchPickRule				VARCHAR(20), -- RULE_PICK_BY_PICK_LOCATION, RULE_PICK_BY_FIFO, RULE_PICK_BY_FEFO
	@in_fltQuantity				FLOAT,
	@in_intLotAllowOrder		INT, 
	@out_vchLotString			NVARCHAR(MAX) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchExecQuery		NVARCHAR(4000) = ''
	DECLARE @OrderBySQL			NVARCHAR(1000) = ''

	CREATE TABLE #Temp (
		lot_number	NVARCHAR(200), 
		quantity	INT, 
		weight		INT
	)

	IF (@in_vchPickRule = 'RULE_PICK_BY_PICK_LOCATION')
		SET @OrderBySQL = 'receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';
	IF (@in_vchPickRule = 'RULE_PICK_BY_FIFO')
		SET @OrderBySQL = 'receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';
	IF (@in_vchPickRule = 'RULE_PICK_BY_FEFO')
	  SET @OrderBySQL = 'expiry_date,receive_date,lot_number,pick_sequence,location,parent_lpn,lpn';

	SET @v_vchExecQuery = '
		SELECT  lot_number,
				SUM(quantity) AS quantity,
				POWER(ROW_NUMBER() OVER (ORDER BY '+ @OrderBySQL +'),2) AS weight
		FROM (
			SELECT	'+ @OrderBySQL +', quantity			
			FROM (
				'+ @in_vchQueryString +'
			)T
		)T2
		GROUP BY ' + @OrderBySQL + ' ORDER BY '+ @OrderBySQL

	----PRINT @v_vchExecQuery

	----IF	@in_vchPickRule = 'RULE_PICK_BY_PICK_LOCATION' BEGIN
	----	SET @v_vchExecQuery = '
	----	SELECT  expiry_date,receive_date,lot_number,
	----			SUM(quantity) AS quantity,
	----			POWER(ROW_NUMBER() OVER (ORDER BY '+ @OrderBySQL +'),2) AS weight
	----	FROM (
	----		SELECT	expiry_date, receive_date, lot_number, quantity			
	----		FROM (
	----			'+ @in_vchQueryString +'
	----		)T
	----	)T2
	----	GROUP BY ' + @OrderBySQL
	----END
	----ELSE IF	@in_vchPickRule = 'RULE_PICK_BY_FEFO' BEGIN
	----	SET @v_vchExecQuery = '
	----	SELECT  expiry_date,receive_date,lot_number,
	----			SUM(quantity) AS quantity,
	----			POWER(ROW_NUMBER() OVER (ORDER BY '+ @OrderBySQL +'),2) AS weight
	----	FROM (
	----		SELECT	expiry_date, receive_date, lot_number, quantity			
	----		FROM (
	----			'+ @in_vchQueryString +'
	----		)T
	----	)T2
	----	GROUP BY ' + @OrderBySQL
	----END
	----ELSE IF @in_vchPickRule = 'RULE_PICK_BY_FIFO' BEGIN
	----	SET @v_vchExecQuery = '
	----	SELECT  NULL as expiry_date,receive_date,lot_number,
	----			SUM(quantity) AS quantity,
	----			POWER(ROW_NUMBER() OVER (ORDER BY '+ @OrderBySQL +'),2) AS weight
	----	FROM (
	----		SELECT	expiry_date, receive_date, lot_number, quantity			
	----		FROM (
	----			'+ @in_vchQueryString +'
	----		)T
	----	)T2
	----	GROUP BY ' + @OrderBySQL
	----END
		
	DELETE FROM #Temp
	INSERT INTO #Temp (lot_number,quantity,weight)
	EXEC sp_executesql @v_vchExecQuery

	SELECT	*
	FROM	#Temp

	SET @out_vchLotString = ''

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 8 BEGIN
		PRINT 'LOT8';
		;WITH cte8lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
		
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		'''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + ''','
						+ '''' + c4.lot_number + ''','
						+ '''' + c5.lot_number + ''','
						+ '''' + c6.lot_number + ''','
						+ '''' + c7.lot_number + ''','
						+ '''' + c8.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight + c4.weight + c5.weight + c6.weight + c7.weight + c8.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity + c7.quantity + c8.quantity AS sum_qty
			FROM		cte8lot c1
			CROSS JOIN	cte8lot c2
			CROSS JOIN	cte8lot c3
			CROSS JOIN	cte8lot c4
			CROSS JOIN	cte8lot c5
			CROSS JOIN	cte8lot c6
			CROSS JOIN	cte8lot c7
			CROSS JOIN	cte8lot c8
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c3.lot_number < c4.lot_number
			AND			c4.lot_number < c5.lot_number
			AND			c5.lot_number < c6.lot_number
			AND			c6.lot_number < c7.lot_number
			AND			c7.lot_number < c8.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity + c7.quantity + c8.quantity >= @in_fltQuantity
		)T
		ORDER BY sum_weight
		
	END

	IF @out_vchLotString = 'NoData' AND @in_intLotAllowOrder >= 7 BEGIN
		PRINT 'LOT7';
		;WITH cte7lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
		
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		'''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + ''','
						+ '''' + c4.lot_number + ''','
						+ '''' + c5.lot_number + ''','
						+ '''' + c6.lot_number + ''','
						+ '''' + c7.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight + c4.weight + c5.weight + c6.weight + c7.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity + c7.quantity AS sum_qty
			FROM		cte7lot c1
			CROSS JOIN	cte7lot c2
			CROSS JOIN	cte7lot c3
			CROSS JOIN	cte7lot c4
			CROSS JOIN	cte7lot c5
			CROSS JOIN	cte7lot c6
			CROSS JOIN	cte7lot c7
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c3.lot_number < c4.lot_number
			AND			c4.lot_number < c5.lot_number
			AND			c5.lot_number < c6.lot_number
			AND			c6.lot_number < c7.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity + c7.quantity >= @in_fltQuantity
		)T
		ORDER BY sum_weight
	END

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 6 BEGIN
		PRINT 'LOT6';
		;WITH cte6lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
		
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		'''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + ''','
						+ '''' + c4.lot_number + ''','
						+ '''' + c5.lot_number + ''','
						+ '''' + c6.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight + c4.weight + c5.weight + c6.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity  AS sum_qty
			FROM		cte6lot c1
			CROSS JOIN	cte6lot c2
			CROSS JOIN	cte6lot c3
			CROSS JOIN	cte6lot c4
			CROSS JOIN	cte6lot c5
			CROSS JOIN	cte6lot c6
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c3.lot_number < c4.lot_number
			AND			c4.lot_number < c5.lot_number
			AND			c5.lot_number < c6.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity + c6.quantity >= @in_fltQuantity
		)T
		ORDER BY sum_weight
	END

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 5 BEGIN
		PRINT 'LOT5';
		;WITH cte5lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
		
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		'''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + ''','
						+ '''' + c4.lot_number + ''','
						+ '''' + c5.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight + c4.weight + c5.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity AS sum_qty
			FROM		cte5lot c1
			CROSS JOIN	cte5lot c2
			CROSS JOIN	cte5lot c3
			CROSS JOIN	cte5lot c4
			CROSS JOIN	cte5lot c5
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c3.lot_number < c4.lot_number
			AND			c4.lot_number < c5.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity + c4.quantity + c5.quantity >= @in_fltQuantity
		)T
		ORDER BY sum_weight
	END
	
	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 4 BEGIN
		PRINT 'LOT4';
		;WITH cte4lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
		
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		'''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + ''','
						+ '''' + c4.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight + c4.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity + c4.quantity AS sum_qty
			FROM		cte4lot c1
			CROSS JOIN	cte4lot c2
			CROSS JOIN	cte4lot c3
			CROSS JOIN	cte4lot c4
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c3.lot_number < c4.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity + c4.quantity >= @in_fltQuantity
		)T
		ORDER BY sum_weight
		PRINT 'Out: ' +  @out_vchLotString;
	END

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 3 BEGIN
		PRINT 'LOT3';
		;WITH cte3lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
			
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		  '''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''','
						+ '''' + c3.lot_number + '''' AS string_return,
						c1.weight + c2.weight + c3.weight AS sum_weight,
						c1.quantity + c2.quantity + c3.quantity AS sum_qty
			FROM		cte3lot c1
			CROSS JOIN	cte3lot c2
			CROSS JOIN	cte3lot c3
			WHERE		c1.lot_number < c2.lot_number
			AND			c2.lot_number < c3.lot_number
			AND			c1.quantity + c2.quantity + c3.quantity >= @in_fltQuantity
		)T 
		ORDER BY sum_weight
	END

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 2 BEGIN
		PRINT 'LOT2';
		;WITH cte2lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
			UNION
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
			
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		  '''' + c1.lot_number + ''','
						+ '''' + c2.lot_number + ''''AS string_return,
						c1.weight + c2.weight  AS sum_weight,
						c1.quantity + c2.quantity AS sum_qty
			FROM		cte2lot c1
			CROSS JOIN	cte2lot c2
			WHERE		c1.lot_number < c2.lot_number
			AND			c1.quantity + c2.quantity >= @in_fltQuantity
		)T 
		ORDER BY sum_weight
	END

	IF @out_vchLotString = '' AND @in_intLotAllowOrder >= 1 BEGIN
		PRINT 'LOT1';
		;WITH cte1lot AS (
			SELECT	lot_number,quantity,weight
			FROM	#Temp
		)
			
		SELECT		TOP 1 @out_vchLotString = string_return
		FROM		(
			SELECT		  '''' + c1.lot_number + '''' AS string_return,
						c1.weight AS sum_weight,
						c1.quantity AS sum_qty
			FROM		cte1lot c1
			WHERE		c1.quantity >= @in_fltQuantity
		)T 
		ORDER BY sum_weight
	END

	IF @out_vchLotString = '' BEGIN
		SET @out_vchLotString = NULL;
	END

/*

DECLARE	@return_value int,@out_vchLotString nvarchar(max)

EXEC	@return_value = [dbo].[usp_outbound_modern_trade_allow_mix_lot]
	@in_vchQueryString = '
		SELECT wh_master_id, owner_id, wh_item_master_id, expiry_date, receive_date, lot_number, pick_sequence, location, parent_lpn, lpn, ((quantity + quantity_incoming) - quantity_allocated) AS quantity 
		FROM v_wms_inventory_data_for_release 
		WHERE wh_master_id = ''68C8FBD9-3DF9-4152-8D9F-83BDCA468658'' AND wh_item_master_id = ''61A74678-9939-4A4B-B844-75CB70DE30D2'' AND inv_status = ''Available'' AND owner_id = ''5A14F372-3FE1-4EEF-BBAB-A1E412CD5E7E'' AND ((quantity + quantity_incoming) - quantity_allocated) > 0  AND ISNULL(EXPIRY_DATE,CONVERT(NVARCHAR,DATEADD(yy,1, getdate()),112)) > CONVERT(NVARCHAR,getdate(),112) 
		AND loc_type IN (SELECT value FROM t_wms_rule WHERE rule_code = ''RULE_LOCATION_TYPE_FOR_PICK'' AND is_active = ''YES'')
	',
	@in_vchPickRule = N'RULE_PICK_BY_FIFO',
	@in_fltQuantity = 25,
	@in_intLotAllowOrder = 4,
