/****** Object:  StoredProcedure [dbo].[usp_outbound_order_cheker]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-02-17
-- Description:	Checker
-- 21/11/2014 : หากต้องการใช้ Warranty ต้องนำของ Panasonic มา Modify ใหม่ เนื่องจากเปลี่ยน concept Tabel ที่เก็บ Serial Number
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_order_cheker]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchStagingLocation	NVARCHAR(50),
	@in_vchLoadNumber		NVARCHAR(50),
	@in_vchOutboundOrder	NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25),
	@in_vchLPN				NVARCHAR(25),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchLotNumber		NVARCHAR(50),
	@in_vchExpiryDate		NVARCHAR(50),
	@in_vchSerialNumber		NVARCHAR(50),
	@in_vchAttribute1		NVARCHAR(100),
	@in_vchAttribute2		NVARCHAR(100),
	@in_vchAttribute3		NVARCHAR(100),
	@in_vchAttribute4		NVARCHAR(100),
	@in_vchAttribute5		NVARCHAR(100),
	@in_fltQuantity			FLOAT,
	@in_vchUom				NVARCHAR(25),
	@in_vchAllSerial		NVARCHAR(3),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_order_cheker]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(250),
		@v_vchProcessData2			NVARCHAR(250),
		@v_vchProcessData3			NVARCHAR(250),
		@v_vchProcessData4			NVARCHAR(250),
		@v_dtProcessDateTime		DATETIME,

		--@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		--@v_vchParameterDefinition	NVARCHAR(MAX) = '',
		--@v_vchDynamicSQLCondition	NVARCHAR(MAX) = '',
		--@cursorOutboundPickDetail	CURSOR,

		@v_vchWhMasterID			VARCHAR(40),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchOwnerCode				NVARCHAR(50),
		@v_fltQuantityOrder			FLOAT,
		@v_fltQuantityPick			FLOAT,
		@v_fltQuantityStage			FLOAT,
		@v_fltQuantityLoad			FLOAT,
		@v_fltSQuantityLoad			FLOAT,
		@v_fltSQuantityOrder		FLOAT,
		@v_fltChkQtyPlanUnit		FLOAT,
		@v_vchPickPackAuto			NVARCHAR(3),
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchOutboundOrderMasterID	VARCHAR(40),
		@v_vchOutboundDetailID		VARCHAR(40),
		@v_vchOutboundPickDetailID	VARCHAR(40),
		@v_vchOutboundPackDetailID	VARCHAR(40),
		
		@v_vchLineNumber			NVARCHAR(10),
		@v_fltQuantityRemainCheck	FLOAT,
		@v_fltQuantityCheck			FLOAT,
		@v_vchStagingLocationID		VARCHAR(40),
		@v_vchSerialNumber			NVARCHAR(50),
		
		--ใช้ของ Warranty Panasonic
		--@v_vchUDF2				NVARCHAR(50),
		--@v_vchUDF3				NVARCHAR(50),
		--@v_vchUDF4				NVARCHAR(50),
		--@v_vchUDF5				NVARCHAR(50),
		--@v_fltWarrantyPeriod		INT,
		--@v_dtWarrantyDate			DATE,

		@v_vchWhItemMasterID	 VARCHAR(40),
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchSerialControl			NVARCHAR(10),
		@v_vchPrimaryUOMPrompt		NVARCHAR(25),
		@Round						FLOAT,
		
		--For Transportation
		@v_vchDockDoorID			varchar(40) = NULL,
		@v_vchLoadNumber			NVARCHAR(50)= NULL,	--ใช้กับ Transport กรณีที่หน้าจอไม่ได้ scan load_id ต้อง get load_id จาก Master
		@v_vchLoadMasterID			VARCHAR(40) = NULL,
		@v_vchLoadDetailID			VARCHAR(40) = NULL,
		@v_vchCustomerID			VARCHAR(40) = NULL,
		@v_fltVolumn				FLOAT,
		@v_fltWeight				FLOAT,
		@v_fltSumVolumn				FLOAT,		--Sum By LoadMasterID
		@v_fltSumWeight				FLOAT,		--Sum By LoadMasterID
		@v_vchTruckTypeID			VARCHAR(40),
		@v_fltTransportQty			FLOAT,
		@v_vchTransportUomPrompt	NVARCHAR(25)

	BEGIN TRY

		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
		SELECT @v_vchPickPackAuto = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK'
		SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT @v_vchStagingLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchStagingLocation


		-------------------------------------------------
		-- Get owner id
		-------------------------------------------------
		IF (ISNULL(@in_vchLoadNumber,'') <> '')
			BEGIN
				SELECT TOP 1 @v_vchOwnerID = owner_id 
					,@v_vchDockDoorID = dock_door_id
					,@v_vchLoadNumber = load_id
				FROM t_wms_outbound_master 
				WHERE load_id = @in_vchLoadNumber 
				AND wh_master_id = @v_vchWhMasterID
			END
		ELSE
			BEGIN
				SELECT TOP 1 @v_vchOwnerID = owner_id 
					,@v_vchDockDoorID = dock_door_id
					,@v_vchLoadNumber = load_id
				FROM t_wms_outbound_master 
				WHERE outbound_order_number = @in_vchOutboundOrder AND wh_master_id = @v_vchWhMasterID
			END

		--------------------------------------------------
		--Get Owner Code
		--------------------------------------------------
		SELECT @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_id = @v_vchOwnerID AND is_active = 'YES'
		
		--------------------------------------------------
		--Check Dock Door
		--------------------------------------------------
		IF (ISNULL(@v_vchDockDoorID,'') = '')
			BEGIN
				SET @out_ErrorCode = 'DOCK-DOOR-NOT-MAP'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END
		
		--------------------------------------------------
		-- Get item_master_id
		--------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id 
			,@in_vchItemNumber = item.item_number
			,@v_vchSerialControl = item.sn_control
		FROM t_wms_item item
		LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
		WHERE owner_id = @v_vchOwnerID
		AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
				RETURN;
			END

		--------------------------------------------------
		-- GET wh_item_master_id
		--------------------------------------------------
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item 
		WHERE item_master_id = @v_vchItemMasterID 
		AND wh_master_id = @v_vchWhMasterID

		--------------------------------------------------
		-- Get Primary UOM และ คำนวนจำนวนให้อยู่หน่วยที่เล็กที่สุด
		--------------------------------------------------
		SELECT @v_vchPrimaryUOMPrompt = uom_prompt
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND primary_uom = 'YES'
		AND is_active = 'YES'

		IF @in_vchUom <> @v_vchPrimaryUOMPrompt
			BEGIN
				-- กรณีที่ไม่ได้จ่ายเป็นหน่วยที่เล็กที่สุด ต้องคำนวณ จำนวนที่จ่ายให้เป็นหน่วยที่เล็กที่สุด
				SELECT @v_fltChkQtyPlanUnit = ROUND((@in_fltQuantity * conversion_factor),@Round)
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND uom_prompt = @in_vchUom
				AND is_active = 'YES'
			END
		ELSE
			BEGIN
				--กรณีที่จ่ายมาเป็นหน่วยที่เล็กที่สุดแล้วไม่ต้องแปลง
				SET @v_fltChkQtyPlanUnit = ROUND(@in_fltQuantity,@Round)
			END

		BEGIN-- 1.Check check quantity and pick quantity
			IF (@v_vchPickPackAuto = 'YES')
				BEGIN
					SELECT TOP 1 @v_fltQuantityOrder = Sum(quantity_order)
						,@v_fltQuantityPick = Sum(quantity_pack)
						,@v_fltQuantityStage = Sum(quantity_stage)
						,@v_fltQuantityLoad = Sum(quantity_load)
					FROM v_wms_outbound_pack_detail 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
					AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
					AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
					AND item_number = ISNULL(@in_vchItemNumber,'') 
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'') 
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
					AND is_override = 'NO'
				END
			ELSE
				BEGIN
					SELECT TOP 1 @v_fltQuantityOrder = Sum(quantity_order)
						,@v_fltQuantityPick = Sum(quantity_pack)
						,@v_fltQuantityStage = Sum(quantity_stage)
						,@v_fltQuantityLoad = Sum(quantity_load)
					FROM v_wms_outbound_pick_or_pack 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
					AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
					AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
					AND item_number = ISNULL(@in_vchItemNumber,'') 
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'') 
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
					AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
					AND is_override = 'NO'
				END

			IF (@v_fltQuantityOrder IS NULL)
				BEGIN
					SET @out_ErrorCode = '988';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_PICK_DETAIL',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END

			-- Get Count serial in inventory
			IF (@in_vchAllSerial = 'YES')
				BEGIN
					SELECT @v_fltChkQtyPlanUnit = COUNT(serial_number) FROM v_wms_inventory_data_by_serial_mini 
					WHERE wh_master_id = @v_vchWhMasterID 
					AND location_id = @v_vchStagingLocationID 
					AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
					AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'') 
					AND wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				END		

			-- check in_qty <= remain load qty
			IF (ROUND(@v_fltChkQtyPlanUnit,@Round) > ROUND((@v_fltQuantityStage - @v_fltQuantityLoad),@Round))
				BEGIN
					SET @out_ErrorCode = '989';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QTY_CHECK_MORE_THAN_QTY_PICK',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
		End

		----------------------------------------
		--INSERT LOAD MASTER FOR TRANSPORTATION
		----------------------------------------
		SELECT @v_vchLoadMasterID = load_master_id FROM t_wms_load_master WHERE load_number = @v_vchLoadNumber AND wh_master_id = @v_vchWhMasterID
		IF (ISNULL(@v_vchLoadMasterID,'') = '')
			BEGIN
				SET @v_vchLoadMasterID = NEWID()
				INSERT INTO [dbo].[t_wms_load_master]
						([load_master_id]
						,[load_number]
						,[wh_master_id]
						,[truck_id]
						,[dock_door_id]
						,[load_status]
						,[create_by]
						,[create_date])
					VALUES
						(@v_vchLoadMasterID
						,@v_vchLoadNumber
						,@v_vchWhMasterID
						,NULL		--truck_id ไว้ใส่หลังจาก ship แล้ว
						,@v_vchDockDoorID
						,'PENDING'
						,@in_vchUserID
						,GETDATE())
			END

		BEGIN TRANSACTION
		BEGIN-- 2. loop for update check quantity	
			CHECKER_PROCESS:
				IF (@v_vchPickPackAuto = 'YES')
					BEGIN
						SELECT TOP 1 @v_vchOutboundOrderMasterID = outbound_order_master_id
							,@v_vchOutboundOrderNumber = outbound_order_number
							,@v_vchCustomerID = customer_id
							,@v_vchOutboundDetailID = outbound_order_detail_id
							,@v_vchOutboundPickDetailID = outbound_pick_detail_id
							,@v_vchOutboundPackDetailID = outbound_pack_detail_id
							,@v_vchLineNumber = line_number
							,@v_vchWhItemMasterID = wh_item_master_id
							,@v_fltQuantityRemainCheck = (quantity_stage - quantity_load)
							,@v_vchSerialNumber = serial_number
						FROM v_wms_outbound_pack_detail 
						WHERE wh_master_id = @v_vchWhMasterID 
						AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
						AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
						AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
						AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
						AND item_number = ISNULL(@in_vchItemNumber,'') 
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'') 
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
						AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						AND is_override = 'NO'
						AND quantity_stage - quantity_load > 0
					END
				ELSE
					BEGIN
						SELECT TOP 1 @v_vchOutboundOrderMasterID = outbound_order_master_id
							,@v_vchOutboundOrderNumber = outbound_order_number
							,@v_vchCustomerID = customer_id
							,@v_vchOutboundDetailID = outbound_order_detail_id
							,@v_vchOutboundPickDetailID = outbound_pick_detail_id
							,@v_vchOutboundPackDetailID = outbound_pack_detail_id
							,@v_vchLineNumber = line_number
							,@v_vchWhItemMasterID = wh_item_master_id
							,@v_fltQuantityRemainCheck = (quantity_stage - quantity_load)
							,@v_vchSerialNumber = serial_number
						FROM v_wms_outbound_pick_or_pack 
						WHERE wh_master_id = @v_vchWhMasterID 
						AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
						AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
						AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
						AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
						AND item_number = ISNULL(@in_vchItemNumber,'') 
						AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
						AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
						AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
						AND is_override = 'NO'
						AND quantity_stage - quantity_load > 0	
					END

				--ถ้าไม่มีของให้ทำ checker แล้วก็ออกได้เลย
				IF (@@ROWCOUNT = 0)
					BEGIN
						GOTO CHECK_STATUS_QUANTITY;
					END

				-----------------------------------------
				--คำนวน Volumn, Weight ของทั้ง Order 
				-----------------------------------------
				IF (@in_vchAllSerial = 'YES')
					BEGIN
						--กรณีที่เป็น All Serial ต้องส่งจำนวน Serial ทั้งหมดที่จะ Checker และหน่วยเป็นหน่วยที่เล็กที่สุด
						SELECT @v_fltVolumn = volume, @v_fltWeight = [weight] FROM dbo.fn_calculator_volume(@v_vchItemMasterID,@v_fltChkQtyPlanUnit,@v_vchPrimaryUOMPrompt)
					END
				ELSE
					BEGIN
						--กรณีปกติคำนวนตามจำนวน และหน่วยจากค่าที่ส่งมา
						SELECT @v_fltVolumn = volume, @v_fltWeight = [weight] FROM dbo.fn_calculator_volume(@v_vchItemMasterID,@in_fltQuantity,@in_vchUom)
					END

				------------------------------------------------
				--INSERT/UPDATE LOAD DETAIL FOR TRANSPORTATION
				------------------------------------------------
				SET @v_vchLoadDetailID = NULL
				SELECT @v_vchLoadDetailID = load_detail_id 
				FROM t_wms_load_detail 
				WHERE load_master_id = @v_vchLoadMasterID 
				AND outbound_order_number = @v_vchOutboundOrderNumber
				IF (ISNULL(@v_vchLoadDetailID,'') = '')
					BEGIN
						INSERT INTO [dbo].[t_wms_load_detail]
								([load_detail_id]
								,[load_master_id]
								,[outbound_order_number]
								,[customer_id]
								,[volumn]
								,[weight]
								,[ship_date]
								,[create_by]
								,[create_date])
							VALUES
								(NEWID()
								,@v_vchLoadMasterID
								,@v_vchOutboundOrderNumber
								,@v_vchCustomerID
								,@v_fltVolumn
								,@v_fltWeight
								,NULL
								,@in_vchUserID
								,GETDATE())
					END
				ELSE
					BEGIN
						UPDATE [dbo].[t_wms_load_detail]
						SET [volumn] = [volumn] + @v_fltVolumn
							,[weight] = [weight] + @v_fltWeight
							,[update_by] = @in_vchUserID
							,[update_date] = GETDATE()
						WHERE load_detail_id = @v_vchLoadDetailID
					END
			
				------------------------------------------------
				--SET จำนวนที่สามารถ qty_load ได้จริง
				------------------------------------------------
				IF (@v_fltChkQtyPlanUnit < @v_fltQuantityRemainCheck)
					SET @v_fltQuantityCheck = @v_fltChkQtyPlanUnit
				ELSE
					SET @v_fltQuantityCheck = @v_fltQuantityRemainCheck

				------------------------------------------------
				-- Update Qty Load [Pick Detail]
				------------------------------------------------
				UPDATE t_wms_outbound_pick_detail SET quantity_load = ROUND(ROUND(ISNULL(quantity_load,0),@Round) + ROUND(@v_fltQuantityCheck,@Round),@Round)
							,load_status = 'YES'
					WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

				-----------------------------------------------------------
				--ถ้ามีข้อมูล Pack Detail ต้อง Update Qty_load ที่ Pack Detail ด้วย
				-----------------------------------------------------------
				IF (ISNULL(@v_vchOutboundPackDetailID,'') <> '')
					BEGIN -- Update Qty Load [Pack Detail]
						UPDATE t_wms_outbound_pack_detail SET quantity_load = ROUND(ROUND(ISNULL(quantity_load,0),@Round) + ROUND(@v_fltQuantityCheck,@Round),@Round)
								,load_status = 'YES'
						WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID
					END

				UPDATE t_wms_outbound_detail SET 
					quantity_load = ROUND(ROUND(ISNULL(quantity_load,0),@Round) + ROUND(@v_fltQuantityCheck,@Round),@Round)
					,item_status = 'CHECKED'
				WHERE outbound_order_detail_id = @v_vchOutboundDetailID

				-----------------------------------------------------------
				--Check จำนวนทั้งหมดของ Order กับจำนวนที่ Load ทั้งหมดของ Order
				-----------------------------------------------------------
				SELECT @v_fltSQuantityOrder = SUM(quantity_order)
					, @v_fltSQuantityLoad = SUM(quantity_load) 
				FROM t_wms_outbound_detail
				WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID

				/*
				--SELECT @v_fltSQuantityOrder = SUM(pickDT.quantity_plan)
				--	,@v_fltSQuantityLoad = SUM(pickDT.quantity_load)
				--FROM t_wms_outbound_pick_master pickMS
				--LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				--WHERE pickMS.outbound_order_master_id = @v_vchOutboundOrderMasterID
				*/

				IF (@v_fltSQuantityOrder = @v_fltSQuantityLoad)
					BEGIN --Load ครบทั้งหมด
						UPDATE t_wms_outbound_master SET order_status = 'LOADED' WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID

						-----------------------------------------------------
						--Suggest truck type for transportation
						-----------------------------------------------------
						SELECT @v_fltSumVolumn = SUM(ISNULL(volumn,0))
							,@v_fltSumWeight = SUM(ISNULL([weight],0))
						FROM t_wms_load_detail 
						WHERE load_master_id = @v_vchLoadMasterID

						SELECT @v_vchTruckTypeID = truck_type_id FROM t_wms_truck_type 
						WHERE volume <= @v_fltSumVolumn
						AND weight <= @v_fltWeight
						UPDATE t_wms_load_master SET truck_type_id = @v_vchTruckTypeID WHERE load_master_id = @v_vchLoadMasterID
					END
				ELSE 
					BEGIN --Load ยังไม่ครบ
						UPDATE t_wms_outbound_master set order_status = 'LOADING' WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
					END

				INSERT INTO t_com_tran_log
				(	app_id
					, tran_type
					, sub_tran_type
					, [app_name]
					, [description]
					, start_tran_datetime
					, end_tran_datetime
					, warehouse
					, to_warehouse
					, location
					, to_location
					, [owner]
					, to_owner
					, item_number
					, quantity
					, quantity_uom
					, after_quantity
					, after_quantity_uom
					, lot_number
					, after_lot_number
					, [expiry_date]
					, after_expiry_date
					, serial_number
					, [attribute1]
				    , [after_attribute1]
				    , [attribute2]
				    , [after_attribute2]
				    , [attribute3]
				    , [after_attribute3]
				    , [attribute4]
				    , [after_attribute4]
				    , [attribute5]
				    , [after_attribute5]
					, [user_id]
					, reference_number
					, control_number
					, parent_lpn
					, after_parent_lpn
					, lpn
					, after_lpn
					, [status]
					, after_status
					, zone
					, order_number
					, line_number
					, device
					, create_by)
				VALUES
					(@in_vchApplicationID
					,'OO_LOAD'
					,'LOAD_ORDER'
					,NULL
					,'Load Item.'
					,GETDATE()
					,GETDATE()
					,@in_vchWarehouse
					,NULL
					,@in_vchStagingLocation
					,NULL
					,@v_vchOwnerCode
					,@v_vchOwnerCode
					,@in_vchItemNumber
					,@v_fltQuantityCheck
					,@v_vchPrimaryUOMPrompt		--@in_vchUom : เนื่องจาก Qty ที่ใช้งานคำนวณให้เป็นหน่วยที่เล็กที่สุดแล้ว จึงไม่สามารถใช้ UOM ที่รับมาจากหน้าจอได้เพราะจะงง
					,NULL
					,NULL
					,@in_vchLotNumber
					,@in_vchLotNumber
					,@in_vchExpiryDate
					,@in_vchExpiryDate
					,@v_vchSerialNumber
					,@in_vchAttribute1
					,@in_vchAttribute1
					,@in_vchAttribute2
					,@in_vchAttribute2
					,@in_vchAttribute3
					,@in_vchAttribute3
					,@in_vchAttribute4
					,@in_vchAttribute4
					,@in_vchAttribute5
					,@in_vchAttribute5
					,@in_vchUserID
					,NULL
					,NULL
					,@in_vchParentLPN
					,@in_vchParentLPN
					,@in_vchLPN
					,@in_vchLPN
					,NULL
					,NULL
					,NULL
					,@v_vchOutboundOrderNumber
					,@v_vchLineNumber
					,@in_vchDeviceID
					,@in_vchUserID)

				SET @v_fltChkQtyPlanUnit -= @v_fltQuantityCheck

				------------------------------------------------
				-- ถ้าของครบแล้วจบการทำงานของ loop ได้เลย
				------------------------------------------------
				IF (@v_fltChkQtyPlanUnit = 0)
					BEGIN
						GOTO CHECK_STATUS_QUANTITY;
					END

				-----------------------------------------------------------------
				-- ถ้าจำนวนที่ Check ยังไม่ครบ ให้ทำการวน pick line ถัดไป เพื่อทำ checker 
				-----------------------------------------------------------------
				IF (@v_vchPickPackAuto = 'YES')
					BEGIN
						IF EXISTS (SELECT outbound_pick_detail_id
									FROM v_wms_outbound_pack_detail 
									WHERE wh_master_id = @v_vchWhMasterID 
									AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
									AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
									AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
									AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
									AND item_number = ISNULL(@in_vchItemNumber,'') 
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
									AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'') 
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
									AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
									AND is_override = 'NO'
									AND quantity_stage - quantity_load > 0)
							BEGIN
								GOTO CHECKER_PROCESS;
							END
					END
				ELSE
					BEGIN
						IF EXISTS (SELECT outbound_pick_detail_id
									FROM v_wms_outbound_pick_or_pack 
									WHERE wh_master_id = @v_vchWhMasterID 
									AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
									AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
									AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
									AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'') 
									AND item_number = ISNULL(@in_vchItemNumber,'') 
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
									AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'') 
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
									AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
									AND is_override = 'NO'
									AND quantity_stage - quantity_load > 0)
							BEGIN
								GOTO CHECKER_PROCESS;
							END
					END
		END

	CHECK_STATUS_QUANTITY:
		BEGIN-- 3. Get Quantity for check load quantity and staging quantity	
			IF (@v_vchPickPackAuto = 'YES')
				BEGIN
					SELECT @v_fltQuantityOrder = Sum(quantity_order)
						,@v_fltQuantityPick = Sum(quantity_pack)
						,@v_fltQuantityStage = Sum(quantity_stage)
						,@v_fltQuantityLoad = Sum(quantity_load)
					FROM v_wms_outbound_pack_detail 
					WHERE wh_master_id = @v_vchWhMasterID
					AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
					AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
					AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
					AND item_number = ISNULL(@in_vchItemNumber,'') 
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
					AND is_override = 'NO'
				END
			ELSE
				BEGIN
					SELECT @v_fltQuantityOrder = Sum(quantity_order)
						,@v_fltQuantityPick = Sum(quantity_pack)
						,@v_fltQuantityStage = Sum(quantity_stage)
						,@v_fltQuantityLoad = Sum(quantity_load)
					FROM v_wms_outbound_pick_or_pack 
					WHERE wh_master_id = @v_vchWhMasterID
					AND (CASE ISNULL(@in_vchLoadNumber,'') WHEN '' THEN '' ELSE load_id END ) =  ISNULL(@in_vchLoadNumber,'')
					AND (CASE ISNULL(@in_vchOutboundOrder,'') WHEN '' THEN '' ELSE outbound_order_number END) = ISNULL(@in_vchOutboundOrder,'')
					AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchParentLPN,'') 
					AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
					AND item_number = ISNULL(@in_vchItemNumber,'') 
					AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
					AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'') 
					AND is_override = 'NO'
				END
			
			IF (@v_fltQuantityLoad = @v_fltQuantityStage)
				BEGIN-- 5.7 return error code = 2. for check new item
					SET @out_ErrorCode = '2';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'THIS_ITEM_IS_CHECKED',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')
				END
			ELSE
				BEGIN-- 5.6 (result =>No)return error code = 1. for check old item
					SET @out_ErrorCode = '1';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'THIS_ITEM_NOT_CHECKED',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')
				END
		END

		COMMIT TRANSACTION;
		RETURN;

	BEGIN--Write process log
		WRITE_PROC:
			If (@@TRANCOUNT > 0)
				ROLLBACK TRANSACTION;

			IF ISNULL(@in_vchLoadNumber,'') <>''
				BEGIN
					SET @v_vchProcessData1 = 'Load number [' + @in_vchLoadNumber +'] ';
				END

			SET @v_dtProcessDateTime = getdate();
			SET @v_vchProcessData1 = @v_vchProcessData1 + 'Order number [' + @in_vchOutboundOrder + ']';
			SET @v_vchProcessData2 = 'Item number ' + @in_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'CHECKER',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @in_vchOutboundOrder,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END

	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;

		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
	END CATCH
END


