/****** Object:  StoredProcedure [dbo].[usp_outbound_order_warranty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-02-18
-- Description:	Checker and Warranty
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_order_warranty]
	@in_vchUserID					NVARCHAR(10),
	@in_vchWarehouseMasterID		VARCHAR(40),
	@in_vchLoadNumber				NVARCHAR(50),
	@in_vchOutboundOrder			NVARCHAR(50),
	@in_vchOwnerID					VARCHAR(40),
	@in_vchLocationID				VARCHAR(40),
	@in_vchOutboundOrderMasterID	VARCHAR(40),
	@in_vchOutboundDetailID			VARCHAR(40),
	@in_vchWarehouseItemMasterID	VARCHAR(40),
	@in_vchLineNumber				NVARCHAR(10),
	@in_vchSerialNumber				NVARCHAR(50),
	@in_vchUDF2						NVARCHAR(50),
	@in_vchUDF3						NVARCHAR(50),
	@in_vchUDF4						NVARCHAR(50),
	@in_fltWarrantyPeriod			INT,
	@in_dtWarrantyDate				DATE,
	@out_ErrorCode					NVARCHAR(200) output,
	@out_ErrorMessage				NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;
	Declare 
			@v_vchWarrantyID			VARCHAR(40),
			@v_vchPrintStatus			NVARCHAR(20)

	Begin Try
		
		select	@v_vchWarrantyID = warranty_id,@v_vchPrintStatus = print_status from t_mod_warranty where wh_master_id = @in_vchWarehouseMasterID
				and outbound_order_master_id = @in_vchOutboundOrderMasterID
				and wh_item_master_id = @in_vchWarehouseItemMasterID
				and serial_number = @in_vchSerialNumber

		If (@v_vchWarrantyID is not null)
			Begin-- update warranty.Warranty value = last day of Period + Month
				-- if @v_vchPrintStatus = 'WAITING' it mean serial is checked warranty
				-- 
				update t_mod_warranty set print_status = 'WAITING',processing_status = 'PENDING',warranty_status = 'ACTIVE',
				warranty_period = @in_fltWarrantyPeriod,warranty_expire = @in_dtWarrantyDate,order_line_id = @in_vchUDF2
				where warranty_id = @v_vchWarrantyID
			End
		Else If (isnull(@in_vchUDF3,'') = '1' and @v_vchWarrantyID is null)
			Begin-- insert warranty.Warranty value = last day of Period + Month
				insert into t_mod_warranty(record_type, processing_code, processing_status, wh_master_id, owner_id, reason_id, location_id, warranty_number, warranty_period, warranty_expire, warranty_status, outbound_order_master_id, outbound_order_number, outbound_order_detail_id, line_number, serial_number, wh_item_master_id, load_number,order_line_id, print_status, create_by)
				values('MASTER','ADD','PENDING',@in_vchWarehouseMasterID,@in_vchOwnerID,null,@in_vchLocationID,null,@in_fltWarrantyPeriod,@in_dtWarrantyDate,'ACTIVE',@in_vchOutboundOrderMasterID,@in_vchOutboundOrder,@in_vchOutboundDetailID,@in_vchLineNumber,@in_vchSerialNumber,@in_vchWarehouseItemMasterID,@in_vchLoadNumber,@in_vchUDF2,'WAITING',@in_vchUserID)
			End
		Else If (isnull(@in_vchUDF3,'') <> '1' and @v_vchWarrantyID is null)
			Begin-- insert warranty.Warranty value is null
				insert into t_mod_warranty(record_type, processing_code, processing_status, wh_master_id, owner_id, reason_id, location_id, warranty_number, warranty_period, warranty_expire, warranty_status, outbound_order_master_id, outbound_order_number, outbound_order_detail_id, line_number, serial_number, wh_item_master_id, load_number,order_line_id, print_status, create_by)
				values('MASTER','ADD','PENDING',@in_vchWarehouseMasterID,@in_vchOwnerID,null,@in_vchLocationID,null,@in_fltWarrantyPeriod,@in_dtWarrantyDate,'N/A',@in_vchOutboundOrderMasterID,@in_vchOutboundOrder,@in_vchOutboundDetailID,@in_vchLineNumber,@in_vchSerialNumber,@in_vchWarehouseItemMasterID,@in_vchLoadNumber,@in_vchUDF2,'PENDING',@in_vchUserID)
			End
		SET @out_ErrorCode = '0'
	End Try
	Begin Catch
		SET @out_ErrorCode = ERROR_NUMBER()
		SET @out_ErrorMessage = ERROR_MESSAGE()
	End Catch

END


