/****** Object:  StoredProcedure [dbo].[usp_outbound_override_auto]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_override_auto]
	@in_vchApplicationID	VARCHAR(40),	
	@in_vchWarehouse		NVARCHAR(25),
	@v_vchWarehouseMasterID	VARCHAR(40),
	@v_vchOutboundOrderMasterID	VARCHAR(40),
	@v_vchOutboundPickMasterID VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchPicklistNumber	NVARCHAR(40),
	@in_vchFromLocation		NVARCHAR(50),
	@v_vchFLocationMasterID	VARCHAR(40),
	@in_vchForkLift			NVARCHAR(50),
	@v_vchTLocationMasterID	VARCHAR(40),
	@in_vchItem				NVARCHAR(50),
	@in_vchWarehouseItemMasterID VARCHAR(40),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vhcUOMID			VARCHAR(40),
	@in_vchFromParentLPN	NVARCHAR(25) = null,
	@in_vchFromLPN			NVARCHAR(25) = null,
	@in_vchToParentLPN		NVARCHAR(25) = null,
	@in_vchToLPN			NVARCHAR(25) = null,
	@in_vchLot				NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNo			NVARCHAR(50) = null,
	@in_vchOverPickReason	NVARCHAR(20) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;
	
	Declare
		@v_vchOutboundPickDetailID	VARCHAR(40),
		@v_vchOutboundOrderDetailID	VARCHAR(40),
		@v_vchLocationMasterID		VARCHAR(40),
		@v_vchPickLineNumber		NVARCHAR(5),
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_fltBaseQty				FLOAT,
		
		@v_vchReceiveDate			DATE,
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_fltStockQuantity			FLOAT = 0,
		@v_vchInventoryType			NVARCHAR(25) = 'INVENTORY',
		@v_vchDubLocation			NVARCHAR(50),
		@v_vchDubParentLPN			NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchOwner					NVARCHAR(50),
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchPickPack				NVARCHAR(3),
		@Round						INT
		
	Begin Try

		select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'
		Select @v_vchPickPack = value from t_wms_rule where rule_code = 'RULE_PICK_PACK'

		Select top 1 @v_vchOutboundPickDetailID = outbound_pick_detail_id,@v_vchOutboundOrderDetailID = outbound_order_detail_id,
				@v_vchPickLineNumber = pick_line_number,@v_vchLocationMasterID = location_id,@v_vchParentLPN = parent_lpn,@v_vchLPN = lpn
		from	t_wms_outbound_pick_detail
		Where	outbound_pick_master_id = @v_vchOutboundPickMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID
				and quantity_plan = @in_fltQty and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull(expiry_date,'') = isnull(@in_vchExpiryDate,'')
				and isnull(serial_number,'') = isnull(@in_vchSerialNo,'') and quantity_pick = 0 and is_override = 'NO'
		
		If (@v_vchOutboundPickDetailID is null)
			Begin
				Set @out_ErrorCode = '999';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_ITEM_IN_PICKING_LIST',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchPicklistNumber,'@param3','@param4','@param5')
				Return;
			End
		Else
			Begin
				Select @v_fltBaseQty = @in_fltQty * conversion_factor from t_wms_item inner join t_wms_item_uom
				on t_wms_item.item_master_id = t_wms_item_uom.item_master_id where item_number = @in_vchItem and item_uom_id = @in_vhcUOMID
				
				If Not Exists(Select inventory_id from v_wms_inventory_data
				Where wh_item_master_id = @in_vchWarehouseItemMasterID and location_id = @v_vchFLocationMasterID and lpn = @in_vchFromLPN
				and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull(EXPIRY_DATE,'') = isnull(@in_vchExpiryDate,'')
				and isnull(serial_number,'') = isnull(@in_vchSerialNo,'') and quantity - quantity_allocated = @v_fltBaseQty)
					Begin
						set @out_ErrorCode = '999';
						select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'INVENTORY_NOT_FOUND_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLPN,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo)
						return;
					End
				
				-- Un allowcate inventory
				exec [usp_inventory_un_allocate]
					@in_vchApplicationID		= @in_vchApplicationID,
					@in_vchWarehouseMasterID	= @v_vchWarehouseMasterID,
					@in_vchLocationID			= @v_vchLocationMasterID,
					@in_vchParentLPN			= @v_vchParentLPN,
					@in_vchLPN					= @v_vchLPN,
					@in_vchItemNumber			= @in_vchItem,
					@in_vchWHItemMasterID		= @in_vchWarehouseItemMasterID,
					@in_fltQuantity				= @v_fltBaseQty,
					@in_vchSerialValue			= @in_vchSerialNo,
					@in_vchLotValue				= @in_vchLot,
					@in_vchExpiryDateValue		= @in_vchExpiryDate,	
					@in_vchUserID				= @in_vchUserID,
					@out_ErrorCode				= @out_ErrorCode output,
					@out_ErrorMessage			= @out_ErrorMessage output
				If (@out_ErrorCode <> '0')
					Return;
				
				set @v_vchInventoryID = null;
				set @v_vchAttributeGroupID = null;
				set @v_fltStockQuantity = 0;
				
				select	@v_vchInventoryID = inventory_id,
						@v_vchAttributeGroupID = attribute_group_id
				from	v_wms_inventory_data
				where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID 
						and location_id = @v_vchLocationMasterID
						and isnull(parent_lpn,'') = isnull(@in_vchFromParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
						and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
						and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
				
				if (@v_vchInventoryID is null) -- กรณีที่อยู่ต่างกรงกัน
					Begin
						select	@v_vchInventoryID = inventory_id,
								@v_vchAttributeGroupID = attribute_group_id,
								@in_vchFromParentLPN = parent_lpn
						from	v_wms_inventory_data
						where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID
								and location_id = @v_vchLocationMasterID
								and isnull(lpn,'') = isnull(@in_vchToLPN,'') and isnull(lot_number,'') = isnull(@in_vchLot,'')
								and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
								and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
						If (@v_vchInventoryID is null)
							Begin
								set @out_ErrorCode = '999';
								select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'INVENTORY_NOT_FOUND_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLPN,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo)
								return;
							End
					End
				
				exec[usp_inventory_control] 
					@in_vchApplicationID		= @in_vchApplicationID,
					@in_vchWarehouse			= @in_vchWarehouse,
					@in_vchDevice				= @in_vchDeviceID,
					@in_vchTransactionType		= 'OO_PICK',
					@in_vchSubTranType			= 'SALES_ORDER',
					@in_vchUserID				= @in_vchUserID,
					@in_vchFromLPN				= @in_vchFromLPN,
					@in_vchFromStatus			= NULL,
					@in_vchFromLocation			= @in_vchFromLocation,
					@in_vchFromLot				= @in_vchLot,
					@in_vchFromExpiryDate		= @in_vchExpiryDate,
					@in_vchItem					= @in_vchItem,
					@in_fltQty					= @in_fltQty,
					@in_fltQtyAllocate			= 0,
					@in_vchUOM					= @in_vchUOMPrompt,
					@in_vchSerialNo				= @in_vchSerialNo,
					@in_vchToLPN				= @in_vchToLPN,
					@in_vchFromParentLPN		= @in_vchFromParentLPN,
					@in_vchToParentLPN			= @in_vchToParentLPN,
					@in_vchToStatus				= NULL,
					@in_vchToLocation			= @in_vchForkLift,
					@in_vchToLot				= @in_vchLot,
					@in_vchToExpiryDate			= @in_vchExpiryDate,
					@in_vchOrderNumber			= @in_vchPicklistNumber,
					@in_vchLineNumber			= @v_vchPickLineNumber,
					@in_vchToWarehouse			= @in_vchWarehouse,
					@in_vchData1				= 'Update pick from picking list.',
					@v_vchErrorCode				= @out_ErrorCode output,
					@v_vchMessage				= @out_ErrorMessage output
					If (@out_ErrorCode <> 0)
						Begin
							return;
						End
				
				--select	@v_vchInventoryID = inventory_id,
				--		@v_vchAttributeGroupID = attribute_group_id,
				--		@v_vchOwner = owner_id,
				--		@v_fltStockQuantity = quantity,
				--		@v_vchReceiveDate = receive_date,
				--		@v_vchToInventoryStatusID = inventory_status_id,
				--		@v_vchInventoryStatus = inv_status
				--from	v_wms_inventory_data
				--where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID 
				--		and location_id = @v_vchLocationMasterID
				--		and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and isnull(lpn,'') = isnull(@v_vchLPN,'')
				--		and isnull(LOT,'') = isnull(@in_vchLot,'') and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
				--		and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
				
				---- not have inventory data
				--If (@v_vchInventoryID is null)
				--	Begin
				--		set @out_ErrorCode = '989';
				--		select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_MOVE_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchForklift,'@param2','@param3','@param4','@param5')
				--		return;
				--	End

				---- manage source location data
				--update t_wms_inventory set quantity_allocated = quantity_allocated - @v_fltBaseQty where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
				--update t_wms_inventory_attribute set quantity_allocated = quantity_allocated - @v_fltBaseQty where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID

				-- manage destination location data
				
