				--			@v_vchAttributeGroupID = attribute_group_id,
				--			@v_fltStockQuantity = quantity,
				--			@v_vchOwner = owner_id
				--	from	v_wms_inventory_data
				--	where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID 
				--			and location_id = @v_vchLocationMasterID
				--			and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
				--			and isnull(LOT,'') = isnull(@in_vchLot,'') and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
				--			and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
					
				--	if (@v_vchInventoryID is not null) -- กรณีที่อยู่ กรง เดียวกัน
				--		Begin
				--			update t_wms_inventory set quantity = quantity - @v_fltBaseQty where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
				--			update t_wms_inventory_attribute set quantity = quantity - @v_fltBaseQty where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
				--		End
