				--					update t_wms_inventory_attribute set quantity = quantity - @v_fltBaseQty where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
				--				End
				--		End
					
				--	set @v_vchInventoryID = null;
				--	set @v_vchAttributeGroupID = null;
					
