				--	where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID 
				--			and location_id = @v_vchTLocationMasterID
				--			and isnull(parent_lpn,'') = isnull(@in_vchToParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
				--			and isnull(LOT,'') = isnull(@in_vchLot,'') and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
				--			and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
					
				--	if (@v_vchInventoryID is null) -- กรณีที่อยู่ต่างกรงกัน
				--		Begin
				--			select	@v_vchInventoryID = inventory_id,
				--					@v_vchAttributeGroupID = attribute_group_id,
				--					@v_fltStockQuantity = quantity,
				--					@v_vchOwner = owner_id,
				--					@v_vchToInventoryStatusID = inventory_status_id,
				--					@v_vchReceiveDate = receive_date,
				--					@in_vchToParentLPN = parent_lpn
				--			from	v_wms_inventory_data
				--			where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID 
				--					and location_id = @v_vchLocationMasterID and isnull(lpn,'') = isnull(@in_vchToLPN,'')
				--					and isnull(LOT,'') = isnull(@in_vchLot,'') and isnull([EXPIRY_DATE],'') = isnull(@in_vchExpiryDate,'')
				--					and isnull(SERIAL_NUMBER,'') = isnull(@in_vchSerialNo,'')
				--		End
						
				--	exec usp_manage_inventory
				--			@in_vchApplicationID = @in_vchApplicationID,
				--			@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
				--			@in_vchWarehouseItemMasterID = @in_vchWarehouseItemMasterID,
				--			@in_vchLocationID = @v_vchTLocationMasterID,
				--			@in_vchLocation = @in_vchForkLift,
				--			@in_vchStatusID = @v_vchToInventoryStatusID,
				--			@in_vchLPN = @in_vchToLPN,
				--			@in_vchLotNumber = @in_vchLot,
				--			@in_vchExpiryDate = @in_vchExpiryDate,
				--			@in_vchSerialNumber = @in_vchSerialNo,
				--			@in_fltQty = @v_fltBaseQty,
				--			@in_fltQtyAllocate = 0,
				--			@in_vchOwner = @v_vchOwner,
				--			@in_vchInventoryType = @v_vchInventoryType,
				--			@in_vchPalentLPN = @in_vchToParentLPN,
				--			@in_vchUserID = @in_vchUserID,
				--			@in_vchReceiveDate = @v_vchReceiveDate,
				--			@in_vchInventoryID = @v_vchInventoryID output,
				--			@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
				--			@in_vchErrorCode = @out_ErrorCode output,
				--			@in_vchMessage = @out_ErrorMessage output
				--	If (@out_ErrorCode <> '0')
				--		return;
					
				--	select @v_vchLotControl = lot_control,
				--	@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control
				--	from t_wms_item where item_number = @in_vchItem
								
				--	If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
				--		Begin
				--			exec usp_manage_inventory_attribute
				--					@in_vchApplicationID = @in_vchApplicationID,
				--					@in_vchItem = @in_vchItem,
				--					@in_vchSerialNo = @in_vchSerialNo,
				--					@in_vchLot = @in_vchLot,
				--					@in_vchExpiryDate = @in_vchExpiryDate,
				--					@in_fltQty = @v_fltBaseQty,
				--					@in_fltQtyAllocate = 0,
				--					@in_vchInventoryID = @v_vchInventoryID,
				--					@in_vchAttributeGroupID = @v_vchAttributeGroupID,
				--					@in_vchLotControl = @v_vchLotControl,
				--					@in_vchSerialNumberControl = @v_vchSerialControl,
				--					@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
				--					@in_vchUserID = @in_vchUserID,
				--					@in_vchErrorCode = @out_ErrorCode output,
				--					@in_vchMessage = @out_ErrorMessage output			
				--			If(@out_ErrorCode <> '0')
				--				return;
				--		End			
				--End
				
				--insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
				--start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location_id, to_location_id, 
				--[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
				--lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
				--reference_number, control_number,parent_lpn,after_parent_lpn, lpn, after_lpn, [status], after_status, zone, order_number, 
				--line_number, device, create_by)
				--values(@in_vchApplicationID,'OO_PICK','SALES_ORDER',null,'Override LPN',
				--GETDATE(),GETDATE(),@in_vchWarehouse,null,@in_vchForklift,@in_vchForkLift,
				--@v_vchOwner,null, @in_vchItem,@v_fltBaseQty,@in_vchUOMPrompt,@v_fltBaseQty + @v_fltStockQuantity,@in_vchUOMPrompt,
				--@in_vchLot,@in_vchLot,@in_vchExpiryDate,@in_vchExpiryDate,@in_vchSerialNo,@in_vchUserID,null,null,@v_vchParentLPN,@in_vchToParentLPN,@v_vchLPN,@in_vchToLPN,@v_vchInventoryStatus,@v_vchInventoryStatus,
				--null,@in_vchPicklistNumber,@v_vchPickLineNumber,@in_vchDeviceID,@in_vchUserID)
				
				-- Update is owerride with t_wms_outbound_pick_detail
				Update t_wms_outbound_pick_detail
				Set is_override = 'YES',is_active = 'NO' Where outbound_pick_detail_id = @v_vchOutboundPickDetailID
				-- Insert new data in t_wms_outbound_pick_detail
				Set @v_vchOutboundPickDetailID = NEWID();
				Insert Into t_wms_outbound_pick_detail(outbound_pick_detail_id,outbound_pick_master_id, outbound_order_detail_id, pick_line_number,location_id,pick_location_id,parent_lpn, pick_to_parent_lpn,lpn, wh_item_master_id, quantity_plan, quantity_pick,quantity_pack,lot_number, expiry_date, serial_number, pick_status, pick_generate_method, create_by)
				Values(@v_vchOutboundPickDetailID,@v_vchOutboundPickMasterID,@v_vchOutboundOrderDetailID,@v_vchPickLineNumber,@v_vchFLocationMasterID,@v_vchTLocationMasterID,@in_vchFromParentLPN,@in_vchToParentLPN,@in_vchToLPN,@in_vchWarehouseItemMasterID,@in_fltQty,@in_fltQty,@in_fltQty,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo,'YES','OVERRIDE',@in_vchUserID)
				-- Insert data in t_wms_outbound_pack_detail
				If (@v_vchPickPack = 'YES')
					Begin
						Insert Into t_wms_outbound_pack_detail(outbound_order_master_id, outbound_pick_detail_id, parent_lpn_pack, lpn_pack, pack_location_id, wh_item_master_id, quantity_pack, lot_number, expiry_date, serial_number, item_uom_id, create_by)
						Values(@v_vchOutboundOrderMasterID,@v_vchOutboundPickDetailID,@in_vchToParentLPN,@in_vchToLPN,@v_vchTLocationMasterID,@in_vchWarehouseItemMasterID,@in_fltQty,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo,@in_vhcUOMID,@in_vchUserID)
					End

				update t_wms_outbound_master
				set order_status = 'PICK'
				where outbound_order_number = @in_vchPicklistNumber

				update t_wms_outbound_detail
				set quantity_pick = round(round(isnull(quantity_pick,0),@Round) + round(@in_fltQty,@Round),@Round),item_status = 'PICK'
				where outbound_order_master_id = @v_vchOutboundOrderMasterID and wh_item_master_id = @in_vchWarehouseItemMasterID and lot_number = @in_vchLot
				
				delete from t_wms_inventory where quantity = 0 and quantity_allocated = 0
				delete from t_wms_inventory_attribute where quantity = 0 and quantity_allocated = 0
				
				Set @out_ErrorCode = '0';
				set @out_ErrorMessage = 'NO';
			End
		
	End Try
	Begin Catch
		If (@@TRANCOUNT > 0 )
			Rollback Transaction;
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_override_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_outbound_override_lpn]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchWhID				NVARCHAR(25),
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOrderNumber		VARCHAR(50),
	@in_vchOwnerID			UNIQUEIDENTIFIER,	
	@in_vchOwner			NVARCHAR(40),
	@in_vchLPN				NVARCHAR(25),
	@in_vchLocalID			VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(25),
	@in_vchUserID			NVARCHAR(25),
	@out_vchLocationID		NVARCHAR(40) OUTPUT,
	@out_vchLocation		NVARCHAR(40) OUTPUT,
	@out_vchParentLPN		NVARCHAR(25) OUTPUT,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg 		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchIsReRunOtherOrder	NVARCHAR(3) = 'NO',
			@v_vchApplicationName	VARCHAR(255),
			@Round					INT,

			--สำหรับ Inventory
			@v_vchInventoryID		UNIQUEIDENTIFIER = NULL,
			@v_vchInvWhID			NVARCHAR(25)  = NULL,
			@v_vchInvLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchInvLocation		NVARCHAR(50)  = NULL,
			@v_vchInvWhItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchInvItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchInvItemNumber		NVARCHAR(50)  = NULL,
			@v_vchInvParentLPN		NVARCHAR(25)  = NULL,
			@v_vchInvLotNumber		NVARCHAR(100) = NULL,
			@v_vchInvExpiryDate		NVARCHAR(100) = NULL,
			@v_vchInvAttribute1		NVARCHAR(100) = NULL,
			@v_vchInvAttribute2		NVARCHAR(100) = NULL,
			@v_vchInvAttribute3		NVARCHAR(100) = NULL,
			@v_vchInvAttribute4		NVARCHAR(100) = NULL,
			@v_vchInvAttribute5		NVARCHAR(100) = NULL,
			@v_fltInvQty			FLOAT,
			@v_fltInvQtyAllocated	FLOAT,
			@v_vchInvStatus			NVARCHAR(50)  = NULL,
			@v_vchInvSNControl		VARCHAR(5) = NULL,
			@v_vchInvBaseUOM		NVARCHAR(10) = NULL, 
			@v_vchInvBaseUOMPrompt	NVARCHAR(40) = NULL, 
			@v_vchInvQtyConvert		FLOAT,	--Qty_Inv ที่ convert เป็นหน่วยของแผน
			@v_vchInvQtyOverride	FLOAT,	--Qty_Inv ที่ Override ไป

			----สำหรับ Picking List
			@v_fltSumReminQtyPlan	FLOAT,
			@v_fltQtyCanAllocated	FLOAT,
			@v_fltAfterQty			FLOAT,
			
			--LOOP OBPICK
			@v_vchOBPickDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchLocation			NVARCHAR(50) = NULL,
			@v_vchParentLPN			NVARCHAR(25) = NULL,
			@v_vchLPN				NVARCHAR(25) = NULL,
			@v_fltConvertQtyPlan	FLOAT,
			@v_fltConvertQtyPick	FLOAT,
			@v_vchSNControl			VARCHAR(5) = NULL,
			@v_dtReceiveDate		DATE = NULL,
			@v_vchOverrideCase		VARCHAR(10) = NULL
	
	DECLARE @tInventory TABLE
	( 
		[inventory_id] [UNIQUEIDENTIFIER] NOT NULL, 
		[qty_update] [float] NOT NULL
	)

	-------------------------------------------------------------------
	-- Create Temp Table เก็บ Order เพื่อนำไป Rerun ใหม่เมื่อ ทำ override เสร็จแล้ว
	-------------------------------------------------------------------
	IF OBJECT_ID('tempdb..#tempOtherOrder') IS NOT NULL
		DROP TABLE #tempOtherOrder
	CREATE TABLE #tempOtherOrder 
	(
		outbound_order_master_id	UNIQUEIDENTIFIER
		,outbound_order_number		NVARCHAR(50)
	)

	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 

	BEGIN TRY
	BEGIN TRANSACTION 
		--------------------------------------------------------------
		-- ตรวจสอบใน Inventory ว่ามี LPN ที่ Scan จากหน้าจอหรือไม่?
		-- โดยเงือนไข Override จะต้องมี item, lot, expiry date เดียวเท่านั้น
		--------------------------------------------------------------
		SELECT TOP 1 @v_vchInventoryID = inventory_id
			, @v_vchInvWhID = wh_id
			, @v_vchInvLocationID = location_id
			, @v_vchInvLocation = location
			, @v_vchInvWhItemMasterID = wh_item_master_id
			, @v_vchInvItemMasterID = item_master_id
			, @v_vchInvItemNumber = item_number
			, @v_vchInvParentLPN = ISNULL(parent_lpn,'')
			, @v_vchInvLotNumber = ISNULL(lot_number,'')
			, @v_vchInvExpiryDate = ISNULL(expiry_date,'')
			, @v_vchInvAttribute1 = attribute1
			, @v_vchInvAttribute2 = attribute2
			, @v_vchInvAttribute3 = attribute3
			, @v_vchInvAttribute4 = attribute4
			, @v_vchInvAttribute5 = attribute5
			, @v_fltInvQty = ROUND(quantity,@Round)
			, @v_fltInvQtyAllocated = ROUND(quantity_allocated,@Round)
			, @v_vchInvStatus = inv_status
			, @v_vchInvSNControl = sn_control
			, @v_vchInvBaseUOM = uom
			, @v_vchInvBaseUOMPrompt = uom_prompt
		FROM v_wms_inventory_data_item
		WHERE ISNULL(lpn,'') = ISNULL(@in_vchLpn,'')
		AND owner_id = @in_vchOwnerID
	
		IF (@@ROWCOUNT = 1)
			BEGIN
				--------------------------------------------------------------------------
				-- ตรวจสอบว่ามีรายการที่ต้องการ Override ที่ Item,lot,exp,status ตรงกับ LPN ที่ Scan
				--------------------------------------------------------------------------
				IF EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pick_detail_mini
							WHERE wh_master_id = @in_vchWhMasterID
							AND outbound_order_master_id = @in_vchOutboundMasterID
							AND wh_item_master_id = @v_vchInvWhItemMasterID
							AND ISNULL(lot_number,'') = ISNULL(@v_vchInvLotNumber,'')             
							AND ISNULL(expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
							AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
							AND default_item_status = @v_vchInvStatus
							AND is_override = 'NO')
					BEGIN
						----------------------------------------------------------------------
						-- Check Wh Rule กรณีที่มีของจองอยู่ ว่าอนุญาตให้ Override ของที่จองหรือไม่?
						-- Check Rule 'WH Rule allow override LPN allocate LPN?'
						----------------------------------------------------------------------
						IF (@v_fltInvQtyAllocated > 0)
							BEGIN
								IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_ALLOW_OVERRIDE_LPN_ALLOCATE_LPN') = 'NO'
									BEGIN
										--ERROR : ไม่อนุญาตให้ Override ของที่จอง'
										SET @out_vchErrorCode = 'INFO-RULE-NOT-ALLOW-ALLOCATE'
										GOTO EXIT_LABEL;
									END
								ELSE
									BEGIN
										-------------------------------------------------------------------
										-- Create Temp Table เก็บ Order เพื่อนำไป Rerun ใหม่เมื่อ ทำ override เสร็จแล้ว
										-------------------------------------------------------------------
										DECLARE @v_vchOutboundOrderMasterID	UNIQUEIDENTIFIER = NULL
										DECLARE @v_vchOutboundOrderNumber	NVARCHAR(50) = NULL
										DECLARE @v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL
										DECLARE @v_fltRemainQtyPlan			FLOAT
										DECLARE @v_fltQuantityPlan			FLOAT
										DECLARE @v_fltQuantityPick			FLOAT

										-------------------------------------------------------------------
										-- ปรับ is_override = 'YES' ของ Order อื่นที่ไปเราไป Override มา
										-- เป็นลูปสำหรับ Order อื่นที่เราไปเอาของมา
										-------------------------------------------------------------------
										DECLARE OutboundOther_Cursor CURSOR FOR
											SELECT outbound_order_master_id
												 ,outbound_order_number
												 ,outbound_pick_detail_id
												 ,ROUND(((quantity_plan - ISNULL(quantity_pick,0)) * conversion_factor),@Round) AS remain_quantity_plan
												 ,quantity_plan
												 ,quantity_pick
											FROM v_wms_outbound_pick_detail_mini
											WHERE order_status NOT IN ('OPEN','SHIP','CANCEL')
											AND wh_item_master_id = @v_vchInvWhItemMasterID
											AND ISNULL(lot_number,'') = ISNULL(@v_vchInvLotNumber,'')
											AND ISNULL(expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
											AND ISNULL(attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
											AND ISNULL(attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
											AND ISNULL(attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
											AND ISNULL(attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
											AND ISNULL(attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
											AND default_item_status = @v_vchInvStatus
											AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
											AND ROUND(ISNULL(quantity_pick,0),@Round) < ROUND(ISNULL(quantity_plan,0),@Round)
											AND is_override = 'NO'
										OPEN OutboundOther_Cursor	
										FETCH NEXT FROM OutboundOther_Cursor INTO @v_vchOutboundOrderMasterID, @v_vchOutboundOrderNumber, @v_vchOutboundPickDetailID, @v_fltRemainQtyPlan, @v_fltQuantityPlan,@v_fltQuantityPick
										WHILE @@FETCH_STATUS = 0
											BEGIN
												----------------------------------------------------------
												-- Update ข้อมูลใน Pick List ของ Order ที่เราจะไปหยิบมา
												-- ถ้า มีการ Pick ไปแล้วไม่ต้องปรับ is_override
												----------------------------------------------------------
												IF @v_fltQuantityPick = 0
													BEGIN
														UPDATE t_wms_outbound_pick_detail SET is_override = 'YES' WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
													END
												ELSE
													BEGIN
														UPDATE t_wms_outbound_pick_detail  SET quantity_plan = quantity_pick WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
													END

												----------------------------------------------------------
												-- ปรับยอดจองใน Inventory
												----------------------------------------------------------
												UPDATE t_wms_inventory SET quantity_allocated = ROUND((quantity_allocated - @v_fltRemainQtyPlan),@Round) WHERE inventory_id = @v_vchInventoryID
											
												--ถ้าไม่ได้ Control Serial จะต้อง Update ยอดจองใน table inventory attribute ด้วย
												IF (@v_vchInvSNControl = 'NONE')
													BEGIN
														UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated - @v_fltRemainQtyPlan),@Round) WHERE inventory_id = @v_vchInventoryID
													END

												-------------------------------------------------------------------------------------------
												-- เนื่องจากตอนที่ Gen PickList ตัวใหม่ให้กับ Order ที่ Scan จะต้องกลับมา Rerun Order อื่นที่เราไป Override มา
												-------------------------------------------------------------------------------------------
												SET @v_vchIsReRunOtherOrder = 'YES'

												--------------------------------------------------------------
												-- Insert Order number ไว้ใช้ตอน ReRun
												--------------------------------------------------------------
												INSERT INTO #tempOtherOrder(outbound_order_master_id,outbound_order_number) VALUES (@v_vchOutboundOrderMasterID,@v_vchOutboundOrderNumber)
												FETCH NEXT FROM OutboundOther_Cursor INTO @v_vchOutboundOrderMasterID, @v_vchOutboundOrderNumber, @v_vchOutboundPickDetailID, @v_fltRemainQtyPlan, @v_fltQuantityPlan, @v_fltQuantityPick
											END
										CLOSE OutboundOther_Cursor                  	
										DEALLOCATE OutboundOther_Cursor
									END
							END
						ELSE
							BEGIN
								--เนื่องจากไม่มีรายการของ Order อื่นที่เราไปหยิบมา เมื่อถึงส่วนที่ต้อง re-run Order อื่นได้ไม่ต้องทำ
								SET @v_vchIsReRunOtherOrder	= 'NO'
							END

						/*
						----------------------------------------------------------------------------------
						-- Generate Pick List ของ Order ที่ Scan มาใหม่ เพื่อให้ตรงกับ lpn ใหม่ที่ไป Override มา
						-- วนลูป item ใน Pick list
						------------------------------------------------------------------------------------
						*/			
						--สำหรับเก็บจำนวนรวมของ Order
						SELECT @v_fltSumReminQtyPlan = ROUND(SUM(quantity_plan - ISNULL(quantity_pick,0)),@Round)
						FROM t_wms_outbound_pick_master pickMS
						INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
						WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
						AND pickDT.wh_item_master_id = @v_vchInvWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@v_vchInvLotNumber,'')           
						AND ISNULL(expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
						AND pickDT.is_override = 'NO' 

						-- เนื่องจากจำนวนใน Inventory อาจมีน้อยกว่าจำนวนใน order จึงต้องเช็คเพื่อบอกให้รู้ว่าเมื่อไหร่ที่ครบจำนวนใน inv หรือ ครบจำนวนใน order แล้วก็ออกจาก ลูป
						IF @v_fltInvQty >= @v_fltSumReminQtyPlan
							BEGIN
								SET @v_vchInvQtyOverride = @v_fltSumReminQtyPlan
								SET @v_fltQtyCanAllocated = @v_fltSumReminQtyPlan
							END
						ELSE
							BEGIN
								SET @v_vchInvQtyOverride = @v_fltInvQty
								SET @v_fltQtyCanAllocated = @v_fltInvQty
							END

						DECLARE OBPick_Cursor CURSOR FOR
							SELECT outbound_pick_detail_id 
								,location
								,parent_lpn
								,lpn
								,ROUND(quantity_plan,@Round)
								,ROUND(quantity_pick,@Round)
								,sn_control
								,receive_date
							FROM v_wms_outbound_pick_detail_mini
							WHERE wh_master_id = @in_vchWhMasterID
							AND outbound_order_master_id = @in_vchOutboundMasterID 
							AND wh_item_master_id = @v_vchInvWhItemMasterID
							AND ISNULL(lot_number,'') = ISNULL(@v_vchInvLotNumber,'')           
							AND ISNULL(expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
							AND default_item_status = @v_vchInvStatus
							AND ROUND(ISNULL(quantity_pick,0),@Round) < ROUND(ISNULL(quantity_plan,0),@Round)
							AND is_override = 'NO'
							ORDER BY pick_line_number
						OPEN OBPick_Cursor	
						FETCH NEXT FROM OBPick_Cursor INTO @v_vchOBPickDetailID,@v_vchLocation,@v_vchParentLPN,@v_vchLPN, @v_fltConvertQtyPlan, @v_fltConvertQtyPick,@v_vchSNControl,@v_dtReceiveDate
						WHILE @@FETCH_STATUS = 0
							BEGIN
								-- มองเป็นหน่วยที่เล็กทีสุด
								IF (@v_fltConvertQtyPick = 0 AND @v_fltQtyCanAllocated >= @v_fltConvertQtyPlan)
									BEGIN
										PRINT 'CASE 1'
										SET @v_vchOverrideCase = 'CASE 1'
										--กรณีที่ 1 จำนวน Pick = 0 และ จำนวนที่จอง >= จำนวนแผน
										--Update data in pick list
										UPDATE t_wms_outbound_pick_detail SET is_override = 'YES' WHERE outbound_pick_detail_id = @v_vchOBPickDetailID

										--Inventory and qty for Update
										DELETE FROM @tInventory
										INSERT INTO @tInventory
										SELECT inventory_id
											,ISNULL(ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round),0) AS qty_update 
										FROM (SELECT vInv.inventory_id  
													,vInv.quantity
													,@v_fltConvertQtyPlan - SUM(vInv.quantity) OVER (ORDER BY vInv.receive_date ROWS UNBOUNDED PRECEDING) AS QtyPlanUpdate 
												FROM v_wms_inventory_data_by_id vInv
												WHERE vInv.wh_master_id = @in_vchWhMasterID
												AND vInv.owner_id = @in_vchOwnerID
												AND vInv.wh_item_master_id = @v_vchInvWhItemMasterID
												AND ISNULL(vInv.lpn,'') = ISNULL(@v_vchLPN,'')
												AND vInv.receive_date = @v_dtReceiveDate
												AND ISNULL(vInv.lot_number,'') = ISNULL(@v_vchInvLotNumber,'')
												AND ISNULL(vInv.expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
												AND ISNULL(vInv.attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
												AND ISNULL(vInv.attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
												AND ISNULL(vInv.attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
												AND ISNULL(vInv.attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
												AND ISNULL(vInv.attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
												) tInventory
										WHERE ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) > 0

										-- Update qty_allocated in t_wms_inventory ที่ item lpn lot expiry ของ row ที่กำลังวนอยู่
										-- qty ตอนนี้มองเป็นหน่วยที่เล็กที่สุด [จำนวนที่จอง - จำนวนที่ Override]
										UPDATE t_wms_inventory SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
										FROM t_wms_inventory inv
										INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id 

										IF @v_vchSNControl <> 'FULL'
											BEGIN
												UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
												FROM t_wms_inventory_attribute inv
												INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id
											END 
									
										--สำหรับ Write Log
										SET @v_fltAfterQty = @v_fltConvertQtyPlan 

										--ลบจำนวนรวมของแผนออก เพื่อให้รู้ว่าตอนนี้ยังเหลือในแผนอีกเท่าไหร่
										SET @v_fltQtyCanAllocated = ROUND((@v_fltQtyCanAllocated - @v_fltConvertQtyPlan),@Round)

									END
								ELSE IF (@v_fltConvertQtyPick = 0 AND @v_fltQtyCanAllocated < @v_fltConvertQtyPlan)
									BEGIN
										PRINT 'CASE 2'
										SET @v_vchOverrideCase = 'CASE 2'
										--กรณีที่ 2 จำนวน Pick = 0 และ จำนวนที่จอง <= จำนวนแผน
										--Update data in pick list
										UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND((@v_fltConvertQtyPlan - @v_fltQtyCanAllocated),@Round) 
										WHERE outbound_pick_detail_id = @v_vchOBPickDetailID
										
										DELETE FROM @tInventory
										INSERT INTO @tInventory
										SELECT inventory_id
											,ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) AS qty_update 
										FROM (SELECT vInv.inventory_id  
													,vInv.quantity
													,@v_fltQtyCanAllocated - SUM(vInv.quantity) OVER (ORDER BY vInv.receive_date ROWS UNBOUNDED PRECEDING) AS QtyPlanUpdate 
												FROM v_wms_inventory_data_by_id vInv
												WHERE vInv.wh_master_id = @in_vchWhMasterID
												AND vInv.owner_id = @in_vchOwnerID
												AND vInv.wh_item_master_id = @v_vchInvWhItemMasterID
												AND ISNULL(vInv.lpn,'') = ISNULL(@v_vchLPN,'')
												AND vInv.receive_date = @v_dtReceiveDate
												AND ISNULL(vInv.lot_number,'') = ISNULL(@v_vchInvLotNumber,'')
												AND ISNULL(vInv.expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
												AND ISNULL(vInv.attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
												AND ISNULL(vInv.attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
												AND ISNULL(vInv.attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
												AND ISNULL(vInv.attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
												AND ISNULL(vInv.attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
												) tInventory
										WHERE ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) > 0

										-- Update qty_allocated in t_wms_inventory ที่ item lpn lot expiry ของ row ที่กำลังวนอยู่
										-- qty ตอนนี้มองเป็นหน่วยที่เล็กที่สุด
										UPDATE t_wms_inventory SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
										FROM t_wms_inventory inv
										INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id

										IF (@v_vchSNControl <> 'FULL')
										BEGIN
											UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
											FROM t_wms_inventory_attribute inv
											INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id
										END

										--สำหรับ Write Log
										SET @v_fltAfterQty = @v_fltQtyCanAllocated

										--ลบจำนวนรวมของแผนออก เพื่อให้รู้ว่าตอนนี้ยังเหลือในแผนอีกเท่าไหร่
										SET @v_fltQtyCanAllocated = ROUND((@v_fltQtyCanAllocated - @v_fltQtyCanAllocated),@Round)
									END
								ELSE IF (@v_fltConvertQtyPick > 0 AND @v_fltQtyCanAllocated >= ROUND((@v_fltConvertQtyPlan - @v_fltConvertQtyPick),@Round))
									BEGIN
										PRINT 'CASE 3'
										SET @v_vchOverrideCase = 'CASE 3'
										--กรณีที่ 3 มีจำนวนการ Pick ไปแล้วบางส่วน
										--Update data in pick list
										UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(@v_fltConvertQtyPick,@Round)  WHERE outbound_pick_detail_id = @v_vchOBPickDetailID

										--Inventory and qty for Update
										DELETE FROM @tInventory
										INSERT INTO @tInventory
										SELECT inventory_id
											,ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) AS qty_update 
										FROM (SELECT vInv.inventory_id  
													,vInv.quantity
													,(@v_fltConvertQtyPlan - @v_fltConvertQtyPick) - SUM(vInv.quantity) OVER (ORDER BY vInv.receive_date ROWS UNBOUNDED PRECEDING) AS QtyPlanUpdate 
												FROM v_wms_inventory_data_by_id vInv
												WHERE vInv.wh_master_id = @in_vchWhMasterID
												AND vInv.owner_id = @in_vchOwnerID
												AND vInv.wh_item_master_id = @v_vchInvWhItemMasterID
												AND ISNULL(vInv.lpn,'') = ISNULL(@v_vchLPN,'')
												AND vInv.receive_date = @v_dtReceiveDate
												AND ISNULL(vInv.lot_number,'') = ISNULL(@v_vchInvLotNumber,'')
												AND ISNULL(vInv.expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
												AND ISNULL(vInv.attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
												AND ISNULL(vInv.attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
												AND ISNULL(vInv.attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
												AND ISNULL(vInv.attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
												AND ISNULL(vInv.attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
												) tInventory
										WHERE ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) > 0

										-- Update qty_allocated in t_wms_inventory ที่ item lpn lot expiry ของ row ที่กำลังวนอยู่
										-- qty ตอนนี้มองเป็นหน่วยที่เล็กที่สุด
										UPDATE t_wms_inventory SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
										FROM t_wms_inventory inv
										INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id

										IF (@v_vchSNControl <> 'FULL')
										BEGIN
											UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
											FROM t_wms_inventory_attribute inv
											INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id
										END
									
										--สำหรับ Write Log
										SET @v_fltAfterQty = ROUND((@v_fltConvertQtyPlan - @v_fltConvertQtyPick),@Round)
										
										--ลบจำนวนรวมของแผนออก เพื่อให้รู้ว่าตอนนี้ยังเหลือในแผนอีกเท่าไหร่
										SET @v_fltQtyCanAllocated = ROUND((@v_fltQtyCanAllocated - (@v_fltConvertQtyPlan - @v_fltConvertQtyPick)),@Round)
									END
								ELSE IF (@v_fltConvertQtyPick > 0 AND @v_fltQtyCanAllocated < ROUND((@v_fltConvertQtyPlan - @v_fltConvertQtyPick),@Round))
									BEGIN
										PRINT 'CASE 4'
										SET @v_vchOverrideCase = 'CASE 4'
										--กรณีที่ 4 มีจำนวนการ Pick ไปแล้วบางส่วน จำนวนที่ Override มีน้อยกว่าแผน
										--Update data in pick list
										UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND((@v_fltConvertQtyPlan - @v_fltQtyCanAllocated),@Round)
										WHERE outbound_pick_detail_id = @v_vchOBPickDetailID

										--Inventory and qty for Update
										DELETE FROM @tInventory
										INSERT INTO @tInventory
										SELECT inventory_id
											,ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) AS qty_update 
										FROM (SELECT vInv.inventory_id  
													,vInv.quantity
													,@v_fltQtyCanAllocated - SUM(vInv.quantity) OVER (ORDER BY vInv.receive_date ROWS UNBOUNDED PRECEDING) AS QtyPlanUpdate 
												FROM v_wms_inventory_data_by_id vInv
												WHERE vInv.wh_master_id = @in_vchWhMasterID
												AND vInv.owner_id = @in_vchOwnerID
												AND vInv.wh_item_master_id = @v_vchInvWhItemMasterID
												AND ISNULL(vInv.lpn,'') = ISNULL(@v_vchLPN,'')
												AND vInv.receive_date = @v_dtReceiveDate
												AND ISNULL(vInv.lot_number,'') = ISNULL(@v_vchInvLotNumber,'')
												AND ISNULL(vInv.expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
												AND ISNULL(vInv.attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
												AND ISNULL(vInv.attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
												AND ISNULL(vInv.attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
												AND ISNULL(vInv.attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
												AND ISNULL(vInv.attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
												) tInventory
										WHERE ROUND((quantity - (CASE WHEN QtyPlanUpdate > 0 THEN 0 ELSE (QtyPlanUpdate * -1) END)),@Round) > 0

										-- Update qty_allocated in t_wms_inventory ที่ item lpn lot expiry ของ row ที่กำลังวนอยู่
										-- qty ตอนนี้มองเป็นหน่วยที่เล็กที่สุด
										UPDATE t_wms_inventory SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
										FROM t_wms_inventory inv
										INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id

										IF (@v_vchSNControl <> 'FULL')
										BEGIN
											UPDATE t_wms_inventory_attribute SET quantity_allocated = ROUND((quantity_allocated - tInv.qty_update),@Round)
											FROM t_wms_inventory_attribute inv
											INNER JOIN @tInventory tInv ON inv.inventory_id = tInv.inventory_id
										END
									
										--สำหรับ Write Log
										SET @v_fltAfterQty = ROUND((@v_fltConvertQtyPlan - @v_fltQtyCanAllocated),@Round)

										--ลบจำนวนรวมของแผนออก เพื่อให้รู้ว่าตอนนี้ยังเหลือในแผนอีกเท่าไหร่
										SET @v_fltQtyCanAllocated = ROUND((@v_fltQtyCanAllocated - @v_fltQtyCanAllocated),@Round)
									END

								--Write Log
								INSERT INTO [dbo].[t_com_tran_log]
											([tran_id]
											,[app_id]
											,[tran_type]
											,[sub_tran_type]
											,[app_name]
											,[description]
											,[start_tran_datetime]
											,[end_tran_datetime]
											,[warehouse]
											,[to_warehouse]
											,[location]
											,[to_location]
											,[owner]
											,[to_owner]
											,[item_number]
											,[quantity]
											,[quantity_uom]
											,[after_quantity]
											,[after_quantity_uom]
											,[lot_number]
											,[after_lot_number]
											,[expiry_date]
											,[after_expiry_date]
											,[serial_number]
											,[attribute1]
											,[after_attribute1]
											,[attribute2]
											,[after_attribute2]
											,[attribute3]
											,[after_attribute3]
											,[attribute4]
											,[after_attribute4]
											,[attribute5]
											,[after_attribute5]
											,[user_id]
											,[lpn]
											,[after_lpn]
											,[parent_lpn]
											,[after_parent_lpn]
											,[status]
											,[after_status] 
											,[order_number]
											,[receive_date]
											,[udf_1]
											,[device]
											,[create_date]
											,[create_by])
										VALUES
											(NEWID()
											,@in_vchApplicationID
											,'OO_PICK'
											,'OVERRIDE_LPN'
											,@v_vchApplicationName
											,'Override LPN [Pick by Order]'
											,GETDATE()
											,GETDATE()
											,@v_vchInvWhID
											,@v_vchInvWhID
											,@v_vchLocation
											,@v_vchInvLocation
											,@in_vchOwner
											,@in_vchOwner
											,@v_vchInvItemNumber
											,(@v_fltConvertQtyPlan - @v_fltConvertQtyPick)
											,@v_vchInvBaseUOM
											,@v_fltAfterQty
											,@v_vchInvBaseUOM
											,(CASE @v_vchInvLotNumber  WHEN '' THEN NULL ELSE @v_vchInvLotNumber  END)
											,(CASE @v_vchInvLotNumber  WHEN '' THEN NULL ELSE @v_vchInvLotNumber  END)
											,(CASE @v_vchInvExpiryDate WHEN '' THEN NULL ELSE @v_vchInvExpiryDate END)
											,(CASE @v_vchInvExpiryDate WHEN '' THEN NULL ELSE @v_vchInvExpiryDate END)
											,NULL
											,(CASE @v_vchInvAttribute1 WHEN '' THEN NULL ELSE @v_vchInvAttribute1 END)
											,(CASE @v_vchInvAttribute1 WHEN '' THEN NULL ELSE @v_vchInvAttribute1 END)
											,(CASE @v_vchInvAttribute2 WHEN '' THEN NULL ELSE @v_vchInvAttribute2 END)
											,(CASE @v_vchInvAttribute2 WHEN '' THEN NULL ELSE @v_vchInvAttribute2 END)
											,(CASE @v_vchInvAttribute3 WHEN '' THEN NULL ELSE @v_vchInvAttribute3 END)
											,(CASE @v_vchInvAttribute3 WHEN '' THEN NULL ELSE @v_vchInvAttribute3 END)
											,(CASE @v_vchInvAttribute4 WHEN '' THEN NULL ELSE @v_vchInvAttribute4 END)
											,(CASE @v_vchInvAttribute4 WHEN '' THEN NULL ELSE @v_vchInvAttribute4 END)
											,(CASE @v_vchInvAttribute5 WHEN '' THEN NULL ELSE @v_vchInvAttribute5 END)
											,(CASE @v_vchInvAttribute5 WHEN '' THEN NULL ELSE @v_vchInvAttribute5 END)
											,@in_vchUserID
											,@v_vchLPN
											,@in_vchLPN
											,@v_vchParentLPN
											,@v_vchInvParentLPN
											,@v_vchInvStatus
											,@v_vchInvStatus 
											,@in_vchOrderNumber --หมายถึงเลข Order number
											,@v_dtReceiveDate
											,@v_vchOverrideCase
											,@in_vchDeviceID
											,GETDATE()
											,@in_vchUserID)

								IF (@v_fltQtyCanAllocated = 0)
									BREAK;

								FETCH NEXT FROM OBPick_Cursor INTO @v_vchOBPickDetailID,@v_vchLocation,@v_vchParentLPN,@v_vchLPN, @v_fltConvertQtyPlan, @v_fltConvertQtyPick,@v_vchSNControl,@v_dtReceiveDate
							END
						CLOSE OBPick_Cursor                  	
						DEALLOCATE OBPick_Cursor

						---------------------------------------------------------------
						-- Get ค่าสำหรับส่งให้กับ Store Generate Pick List : Record ใหม่ของ LPN อันใหม่
						---------------------------------------------------------------
						DECLARE @v_vchAllowShortPick		NVARCHAR(3)
						DECLARE @v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchPickDetailID			UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchCustomerID			UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchCustomerCode			NVARCHAR(50)
						DECLARE @v_dtShipDatePlan			DATETIME
						DECLARE @v_vchOrderType				NVARCHAR(30)
						DECLARE @v_vchRuleCode				NVARCHAR(40)
						DECLARE @v_vchLineNumber			NVARCHAR(10)

						SELECT TOP 1 @v_vchOutboundDetailID = obDT.outbound_order_detail_id
							,@v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
							,@v_vchPickDetailID = pickDT.outbound_pick_detail_id
							,@v_vchCustomerID = obMS.customer_id
							,@v_vchCustomerCode = obMS.customer_code
							,@v_dtShipDatePlan = obMS.ship_date_plan
							,@v_vchOrderType = obMS.order_type
							,@v_vchRuleCode = tRule.rule_code
							,@v_vchLineNumber = obDT.line_number
						FROM t_wms_outbound_master obMS
						INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
						INNER JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
						INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id 
																	AND pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
						INNER JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
 						INNER JOIN dbo.t_wms_item_uom AS uom ON obDT.item_uom_id = uom.item_uom_id 
						LEFT JOIN t_wms_rule tRule ON uom.picking_class = tRule.rule_id
						WHERE obDT.outbound_order_master_id = @in_vchOutboundMasterID
						AND pickDT.wh_item_master_id = @v_vchInvWhItemMasterID
						AND ISNULL(pickDT.lot_number,'') = ISNULL(@v_vchInvLotNumber,'')             
						AND ISNULL(pickDT.expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
						AND ISNULL(pickDT.attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
						AND ISNULL(pickDT.attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
						AND ISNULL(pickDT.attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
						AND ISNULL(pickDT.attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
						AND ISNULL(pickDT.attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
						AND obDT.default_item_status = @v_vchInvStatus
						AND ROUND(ISNULL(obDT.quantity_order,0) - ISNULL(obDT.quantity_pick,0),@Round) > 0

						IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
							BEGIN
								SET @v_vchAllowShortPick = 'YES'
							END
						ELSE
							BEGIN
								SET @v_vchAllowShortPick = 'NO'
							END

						SET @v_vchInvQtyOverride =  ROUND(@v_vchInvQtyOverride,@Round) 
						----------------------------------------------------------------
						-- เมื่อ Update จำนวนเรียบร้อยทั้งหมด ทำการ Generate Pick List ใหม่
						----------------------------------------------------------------
						EXEC usp_outbound_generate_picklist 
								 @in_vchApplicationID			= @in_vchApplicationID
								,@in_vchReleaseDesc				= 'Release by Override'
								,@in_vchWarehouseMasterID		= @in_vchWhMasterID
								,@in_vchOutboundMasterID		= @in_vchOutboundMasterID
								,@in_vchOutboundPickMasterID	= @v_vchOutboundPickMasterID
								,@in_vchOutboundOrderDetailID	= @v_vchOutboundDetailID
								,@in_vchOwnerID					= @in_vchOwnerID
								,@in_vchWhItemMasterID			= @v_vchInvWhItemMasterID
								,@in_vchItemMasterID			= @v_vchInvItemMasterID
								,@in_vchItemNumber				= @v_vchInvItemNumber 
								,@in_vchLocationID				= @v_vchInvLocationID
								,@in_vchOldLocation				= NULL
								,@in_vchParentLPNIsOverride		= NULL
								,@in_vchParentLPN				= @v_vchInvParentLPN
								,@in_vchLPN						= @in_vchLpn
								,@in_fltQuantity				= @v_vchInvQtyOverride		--'qty inven convert'
								,@in_vchUOMPrompt				= @v_vchInvBaseUOMPrompt
								,@in_vchDefaultItemStatus		= @v_vchInvStatus
								,@in_vchSerialNumber			= NULL -- Serial Number
								,@in_vchExpiryDate				= @v_vchInvExpiryDate
								,@in_vchLotNumber				= @v_vchInvLotNumber
								,@in_vchAttribute1				= @v_vchInvAttribute1
								,@in_vchAttribute2				= @v_vchInvAttribute2
								,@in_vchAttribute3				= @v_vchInvAttribute3
								,@in_vchAttribute4				= @v_vchInvAttribute4
								,@in_vchAttribute5				= @v_vchInvAttribute5
								,@in_vchPickRule				= @v_vchRuleCode
								,@in_vchAllowShortPick			= @v_vchAllowShortPick
								,@in_vchCustomerID			 	= @v_vchCustomerID
								,@in_vchCustomerCode			= @v_vchCustomerCode	
								,@in_dtpShipDatePlan			= @v_dtShipDatePlan	
								,@in_vchZone					= NULL
								,@in_vchLineNumber				= @v_vchLineNumber
								,@in_vchDeviceID				= @in_vchDeviceID
								,@in_vchUserID					= @in_vchUserID
								,@in_vchLoadID					= NULL
								,@out_ErrorCode					= @out_vchErrorCode OUTPUT
								,@out_ErrorMessage				= @out_vchErrorMsg  OUTPUT

						IF (@out_vchErrorCode <> 0)
						BEGIN
							--ถ้ามี Error จาก Store พี่วุฒิ ให้ออกจากการทำงานเลย
							GOTO EXIT_LABEL;
						END

						--CLEAR Record OVERRIDE
						DELETE t_wms_outbound_pick_detail 
						WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
						AND wh_item_master_id = @v_vchInvWhItemMasterID
						AND ISNULL(lot_number,'') = ISNULL(@v_vchInvLotNumber,'')             
						AND ISNULL(expiry_date,'') = ISNULL(@v_vchInvExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@v_vchInvAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@v_vchInvAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@v_vchInvAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@v_vchInvAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@v_vchInvAttribute5,'')
						AND is_override = 'YES'
						AND ISNULL(quantity_pick,0) = 0

						---------------------------------------------------------------
						-- ทำการ Re-Run ของ Order ที่เราไปหยิบมา
						---------------------------------------------------------------
						IF (@v_vchIsReRunOtherOrder = 'YES')
							BEGIN
								DECLARE @v_vchReRunOrderNumberID UNIQUEIDENTIFIER
								DECLARE ReRun_Cursor CURSOR FOR
									SELECT outbound_order_master_id FROM #tempOtherOrder
								OPEN ReRun_Cursor	
								FETCH NEXT FROM ReRun_Cursor INTO @v_vchReRunOrderNumberID
								WHILE @@FETCH_STATUS = 0
									BEGIN
									
										--RERUN
										EXEC usp_outbound_release_order @in_vchApplicationID	= @in_vchApplicationID			
																	   ,@in_vchOutboundMasterID	= @v_vchReRunOrderNumberID
																	   ,@in_vchDeviceID			= @in_vchDeviceID				
																	   ,@in_vchUserID			= @in_vchUserID				
																	   ,@out_ErrorCode			= @out_vchErrorCode	OUTPUT	
																	   ,@out_ErrorMessage		= @out_vchErrorMsg OUTPUT

										IF @out_vchErrorCode <> 0 
											BEGIN
												--หากมี Error จาก Store Re-Run
												GOTO EXIT_LABEL;
											END

										FETCH NEXT FROM ReRun_Cursor INTO @v_vchReRunOrderNumberID
									END	  
	       
								CLOSE ReRun_Cursor                  	
								DEALLOCATE ReRun_Cursor
							END

						
					END
				ELSE
					BEGIN
						--ERROR : รายการ [item, lot_number, expiry_date, item_status] ที่ต้องการของ LPN ใหม่ที่ Scan ไม่ตรงกับใน Pick list
						SET @out_vchErrorCode = 'INFO-ITEM-NOT-FOUND'
						GOTO EXIT_LABEL;
					END

				-----------------------------------------------------------------------------
				-- สำหรับส่งค่าไปที่หน้าจอใหม่ เนื่องจากหากมีการ Override ที่ location หรือ parent lpn อื่น 
				-- จะต้องส่งข้อมูลใหม่ไป assign ตัวแปลที่หน้าจอ
				-----------------------------------------------------------------------------
				SET @out_vchLocationID = @v_vchInvLocationID
				SET @out_vchLocation = @v_vchInvLocation
				SET @out_vchParentLPN = @v_vchInvParentLPN

			END
		ELSE IF (@@ROWCOUNT > 1)
			BEGIN
				--ERROR : พบรายการใน Inventory ที่ LPN และ Owner ที่ต้องการมากกว่า 1 รายการ
				SET @out_vchErrorCode = 'INFO-LPN-OWNER-MORE-RECORD'
				GOTO EXIT_LABEL;
			END
		ELSE
			BEGIN
				--ERROR : ไม่รายการ LPN และ owner ที่ต้องการใน Inventory
				SET @out_vchErrorCode = 'INFO-LPN-OWNER-NOT-FOUND'
				GOTO EXIT_LABEL;
			END
			
		--เมื่อทำงานได้ครบทุก Process
		COMMIT TRANSACTION;
		SET @out_vchErrorCode = '0';
		SET @out_vchErrorMsg = 'SAVE SUCCESS'
		RETURN;
	----------------------------------------------------
	-- Exit the Process
	----------------------------------------------------	
	EXIT_LABEL:
		ROLLBACK TRANSACTION;
		IF (@out_vchErrorCode IS NOT NULL AND ISNULL(@out_vchErrorMsg,'') = '')
			BEGIN
				SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
			END
		RETURN;
	END TRY
		BEGIN CATCH
			ROLLBACK TRANSACTION;
			SET @out_vchErrorCode = ERROR_NUMBER();
			SET @out_vchErrorMsg = ERROR_MESSAGE();	

			DECLARE @v_dtProcessDateTime DATETIME = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @in_vchWhID,
				@in_vchDevice = 'UNALLOCATE',
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = 'usp_outbound_override_lpn',
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @in_vchOrderNumber,
				@in_vchData2 = NULL,
				@in_vchData3 = @out_vchErrorCode,
				@in_vchData4 = @out_vchErrorMsg,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
			
			SET @out_vchErrorCode = 'CONTACT_ADMIN';
			SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
		END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_override_update_pick_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_override_update_pick_item]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchForkLocation			NVARCHAR(50),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchBoxNumber			NVARCHAR(50),
	@in_vchLocationID			UNIQUEIDENTIFIER,
	@in_vchOverrideLocationID	UNIQUEIDENTIFIER,
	@in_vchOverrideLocation		NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25),
	@in_vchLPN					NVARCHAR(25), 
	@in_vchOverrideLPN			NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER,
	@in_vchLotNumber			NVARCHAR(50),
	@in_vchOverrideLotNumber	NVARCHAR(50),
	@in_vchExpiryDate			NVARCHAR(50),
	@in_vchOverrideExpiryDate	NVARCHAR(50),
	@in_vchOverrideAttribute1	NVARCHAR(100),
	@in_vchOverrideAttribute2	NVARCHAR(100),
	@in_vchOverrideAttribute3	NVARCHAR(100),
	@in_vchOverrideAttribute4	NVARCHAR(100),
	@in_vchOverrideAttribute5	NVARCHAR(100),
	@in_vchOverrideSerialNumber	NVARCHAR(100),
	@in_fltQty					FLOAT,
	@in_vchUOMPrompt			NVARCHAR(40),
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_override_update_pick_item]' -- The name that uniquely tags this object.
	DECLARE @v_vchProcessData			NVARCHAR(255)= NULL
	DECLARE @v_dtProcessDateTime		DATETIME = NULL
	DECLARE @v_dtStartTime				DATETIME = NULL
	DECLARE @v_vchApplicationName		NVARCHAR(50)= NULL
	DECLARE @v_vchLocalID				VARCHAR(10) = NULL
	DECLARE @v_vchBeginTrans			BIT = 0
	DECLARE @Round						INT
	DECLARE @v_nCount					INT
	DECLARE @RuleOverPick				NVARCHAR(3) = 'NO'
	DECLARE @RulePickPack				NVARCHAR(3) = 'NO'
	DECLARE @RuleAutoStaging			NVARCHAR(3) = 'NO'
	DECLARE @v_vchForkLocationID		UNIQUEIDENTIFIER = NULL

	DECLARE @v_vchOutboundNumber		NVARCHAR(50) = NULL
	DECLARE @v_vchWhMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWarehouse				NVARCHAR(25) = NULL
	DECLARE @v_vchOrderStatus			NVARCHAR(30) = NULL
	DECLARE @v_vchOrderType				NVARCHAR(30) = NULL
	DECLARE @v_vchOwnerID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode				NVARCHAR(50) = NULL
	DECLARE @v_vchPickBy				NVARCHAR(25) = NULL 

	--Item Master
	DECLARE @v_vchItemMasterID			UNIQUEIDENTIFIER  = NULL
	DECLARE @v_vchItemNumber			NVARCHAR(50) = NULL
	DECLARE @v_vchLotControl			VARCHAR(5) = NULL
	DECLARE @v_vchExpControl			VARCHAR(5) = NULL
	DECLARE @v_vchSNControl				VARCHAR(5) = NULL
	DECLARE @v_vchAttribute1Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute2Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute3Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute4Control		VARCHAR(5) = NULL
	DECLARE @v_vchAttribute5Control		VARCHAR(5) = NULL

	-- Item UOM
	DECLARE @v_vchBaseItemUomID			UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt			NVARCHAR(40)
	DECLARE @v_vchBaseUom				NVARCHAR(20)
	DECLARE @v_vchIsPrimaryUOM			VARCHAR(5)
	DECLARE @v_fltConversionFactor		FLOAT
	DECLARE @v_fltBaseInputQuantity		FLOAT
	DECLARE @v_fltWidth					FLOAT = 0   --item Uom
	DECLARE @v_fltLength				FLOAT = 0   --item Uom
	DECLARE @v_fltHeight				FLOAT = 0   --item Uom
	DECLARE @v_fltGrossWeight			FLOAT = 0   --item Uom
	DECLARE @v_intPercentTolerance		FLOAT = 0   --item Uom
	DECLARE @v_intPercenToleranceWeight FLOAT = 0   --item Uom
	DECLARE @v_fltVolumn				FLOAT = 0	--item Uom
	DECLARE @v_fltTotalWeight			FLOAT = 0	--item Uom
			
	DECLARE @v_fltSumRemainPick			FLOAT --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Order ใน item ที่ scan
	DECLARE @v_vchPickToLPN				NVARCHAR(25) = NULL

	----Outbound Loop
	DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL		
 
	---- Auto STG
	DECLARE @v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchStagingLocation		NVARCHAR(50)

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @RuleOverPick = value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_PICK' AND is_active = 'YES'
	SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT TOP 1 @RuleAutoStaging = value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
	
	--Override Location
	/* 
		1.Find picklist for override
		2.validate input qty <= all qty plan in picklist
		3.unrelease record ที่ต้องการ override ตามจำนวนที่ pick order by desc
		4.update current picklist qty plan = (qty plan - input qty pick)
		5.delete current picklist if qty plan = 0
		6.insert new picklist		
	*/
	
	--------------------------------------------------
	-- Get Data in Outbound Master
	--------------------------------------------------
	SELECT TOP 1 @v_vchOutboundNumber = obMS.outbound_order_number
		,@v_vchOrderStatus = obMS.order_status
		,@v_vchOrderType = obMS.order_type
		,@v_vchWhMasterID = obMS.wh_master_id
		,@v_vchWarehouse = obMS.wh_id
		,@v_vchOwnerID = obMS.owner_id 
		,@v_vchOwnerCode = obMS.owner_code
		,@v_vchPickBy = obMS.pick_by
	FROM t_wms_outbound_master obMS
 	WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID
	IF ISNULL(@v_vchOutboundNumber,'') = ''
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchOutboundNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END
	IF(@v_vchOrderStatus = 'SHIP')
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchOutboundNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	------------------------------------------------------
	-- Get Data in Outbound Pick Master
	------------------------------------------------------
	SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @in_vchOutboundMasterID
	IF @v_vchOutboundPickMasterID IS NULL
	BEGIN
		SET @out_ErrorCode = 'PICKLIST_NOT_FOUND';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchOutboundNumber,'@param2','@param3','@param4','@param5')
		GOTO WRITE_PROC;
	END

	SELECT TOP 1 @v_vchForkLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchForkLocation and is_active = 'YES'
	IF @v_vchForkLocationID IS NULL
	BEGIN
		SET @out_ErrorCode = 'FORK_NOT_FOUND';
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchForkLocation,'@param2','@param3','@param4','@param5')
		GOTO WRITE_PROC;
	END

	------------------------------------------------------
	-- ตรวจสอบ Multiple user pick
	------------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO') AND (@v_vchPickBy <> @in_vchUserID))
		BEGIN
			--Multi User
			SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END

	--------------------------------------------------------
	-- Validate Staging Location
	--------------------------------------------------------
	IF (@RuleAutoStaging = 'YES')
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND pickDT.staging_location_id IS NOT NULL
			AND pickDT.is_override = 'NO'
				
			IF @v_vchStagingLocationID IS NULL
			BEGIN
				SELECT TOP 1 @v_vchStagingLocationID = location_id
					,@v_vchStagingLocation = location 
				FROM t_wms_location 
				WHERE wh_master_id = @v_vchWhMasterID 
				AND loc_type = 'STG' AND is_active = 'YES'
				IF (@v_vchStagingLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END 
		END
	
	--------------------------------------------------------
	-- Validate Item Master
	--------------------------------------------------------
	SELECT TOP 1 @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID
	IF @v_vchItemMasterID IS NULL
		BEGIN
			SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		END

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id 
		, @v_vchItemNumber = item.item_number
		, @v_vchLotControl = item.lot_control
		, @v_vchExpControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
	FROM t_wms_item item
	WHERE owner_id = @v_vchOwnerID
	AND item.item_master_id = @v_vchItemMasterID
	IF (ISNULL(@v_vchItemNumber,'') = '')
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
			GOTO WRITE_PROC
		END

	--------------------------------------------------
	--Get & Check Item UOM
	--------------------------------------------------
	SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
		,@v_vchBaseUomPrompt = uom_prompt
		,@v_vchBaseUom = uom
		,@v_fltConversionFactor = conversion_factor
		,@v_vchIsPrimaryUOM = primary_uom
		,@v_fltWidth = ISNULL(width,0)
		,@v_fltLength = ISNULL(length,0)
		,@v_fltHeight = ISNULL(height,0)
		,@v_fltGrossWeight = ISNULL(gross_weight,0)
		,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
		,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt		
	AND is_active = 'YES'	
	IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_ErrorCode = '107';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		End

	--------------------------------------------------
	--Get Primary Uom
	--------------------------------------------------
	IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchBaseUom = uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END

	--------------------------------------------------
	--Set Input Base Qty 
	--------------------------------------------------
	SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);

	--------------------------------------------------
	--GET PICK OUTBOUND DETAIL
	--Location, LPN, Lot Number, Expiry Date >> ถ้ามีค่าถึงจะ Where แสดงว่าไม่ได้ override มา
	--Attribute ไม่ where คือสิ่งที่ override มาแล้ว
	--------------------------------------------------
	SELECT *
	INTO #tOutboundPickDetail
	FROM t_wms_outbound_pick_detail
	WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
	AND ISNULL(quantity_pick,0) < ISNULL(quantity_plan,0)
	AND is_override = 'NO'
	AND wh_item_master_id = @in_vchWhItemMasterID
	--AND (CASE WHEN ISNULL(CONVERT(VARCHAR(36),@in_vchLocationID),'') = '' THEN '' ELSE ISNULL(CONVERT(VARCHAR(36),location_id),'') END) = (CASE WHEN ISNULL(CONVERT(VARCHAR(36),@in_vchLocationID),'') = '' THEN '' ELSE ISNULL(CONVERT(VARCHAR(36),@in_vchLocationID),'') END)
	--AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
	--AND (CASE WHEN ISNULL(@in_vchLPN,'') = '' THEN '' ELSE ISNULL(lpn,'') END) = (CASE WHEN ISNULL(@in_vchLPN,'') = '' THEN '' ELSE ISNULL(@in_vchLPN,'') END)
	--AND (CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(lot_number,'') END) = (CASE WHEN ISNULL(@in_vchLotNumber,'') = '' THEN '' ELSE ISNULL(@in_vchLotNumber,'') END)
	--AND (CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(expiry_date,'') END) = (CASE WHEN ISNULL(@in_vchExpiryDate,'') = '' THEN '' ELSE ISNULL(@in_vchExpiryDate,'') END)
	IF NOT EXISTS (SELECT * FROM #tOutboundPickDetail)
		BEGIN
			-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
			SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
			GOTO WRITE_PROC
		END

	--------------------------------------------------
	-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศุนย์ >> ERROR
	--------------------------------------------------
	SELECT @v_fltSumRemainPick = ROUND(SUM(ISNULL(quantity_plan,0) - ISNULL(quantity_pick,0)),@Round) FROM #tOutboundPickDetail
	IF @v_fltSumRemainPick = 0
		BEGIN
			-- รายการสินค้า [] หยิบครบแล้ว
			SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
			GOTO WRITE_PROC
		END

	--------------------------------------------------
	--Check Inventory กับสิ่งที่ Override
	--------------------------------------------------
	DECLARE @v_fltChkInvQty FLOAT = 0
	DECLARE @v_fltChkInvQtyAllocate FLOAT = 0
	SELECT @v_nCount = COUNT(inventory_id)
		,@v_fltChkInvQty = SUM(quantity)
		,@v_fltChkInvQtyAllocate = SUM(quantity_allocated)
	FROM v_wms_inventory_data_serial_by_id
	WHERE wh_master_id = @v_vchWhMasterID
	AND location_id = @in_vchOverrideLocationID
	AND wh_item_master_id = @in_vchWhItemMasterID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
	AND ISNULL(lpn,'') = ISNULL(@in_vchOverrideLPN,'')
	AND ISNULL(lot_number,'') = ISNULL(@in_vchOverrideLotNumber,'')
	AND ISNULL(expiry_date,'')= ISNULL(@in_vchOverrideExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchOverrideAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchOverrideAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchOverrideAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchOverrideAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchOverrideAttribute5,'')
	AND inventory_status_id IN (SELECT invST.inventory_status_id FROM #tOutboundPickDetail pickDT
								    INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
									INNER JOIN t_wms_inventory_status invST ON obDT.default_item_status = invST.inv_status)
	AND (CASE @in_vchOverrideSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE @in_vchOverrideSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchOverrideSerialNumber,'') END)
	IF ISNULL(@v_nCount,0) = 0
	BEGIN
		-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
		SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchOverrideLotNumber,@in_vchOverrideExpiryDate,@in_vchOverrideLPN,'@param5')			
		GOTO WRITE_PROC
	END

	--------------------------------------------------
	-- Check จำนวนใน Inventory กับจำนวนที่จะจ่าย
	-- จำนวนที่จะ Pick > จำนวนใน Inventory
	--------------------------------------------------
	IF (@in_vchOverrideSerialNumber = 'ALL' AND @v_vchSNControl = 'FULL')
	BEGIN
		SET @v_fltBaseInputQuantity = ROUND(@v_fltChkInvQty,@Round)
	END

	--------------------------------------------------
	--IF Over pick = 'YES' not check in order
	-- ถ้าจำนวนที่หยิบ มากกว่า จำนวนคงเหลือที่สามารถหยิบได้ >> ERROR
	--------------------------------------------------
	IF @RuleOverPick = 'NO' AND (@v_fltBaseInputQuantity > @v_fltSumRemainPick)
	BEGIN
 		SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
		GOTO WRITE_PROC
 	END

	--------------------------------------------------
	-- ถ้าจำนวนใน Inventory มีไม่พอ
	--------------------------------------------------
	IF ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltChkInvQty,@Round)
	BEGIN
		-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
		SET @out_ErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchLotNumber,@in_vchExpiryDate,@in_vchLPN,'@param5')			
		RETURN;
	END

	------------------------------------------------------------
	-- SET pick_to_lpn
	-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
	------------------------------------------------------------
	IF (@v_fltBaseInputQuantity = @v_fltChkInvQty AND ISNULL(@in_vchLPN,'') <> '')
		BEGIN
			SET @v_vchPickToLPN = @in_vchLPN
		END
	ELSE
		BEGIN
			SET @v_vchPickToLPN = (CASE WHEN ISNULL(@in_vchBoxNumber,'') = '' THEN @v_vchOutboundNumber ELSE @in_vchBoxNumber END)
		END

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;

	------------------------------------------------------------
	-- ลบยอด Plan ของ Picklist เดิม & Unallocate ของ
	------------------------------------------------------------
	DECLARE @v_vchPickOBPickDetailID UNIQUEIDENTIFIER
	DECLARE @v_vchPickLocationID	 UNIQUEIDENTIFIER
	DECLARE @v_vchPickParentLPN		 NVARCHAR(25)
	DECLARE @v_vchPickLPN			 NVARCHAR(25) 
	DECLARE @v_vchPickWhItemMasterID UNIQUEIDENTIFIER
	DECLARE @v_vchPickLotNumber		 NVARCHAR(50)
	DECLARE @v_vchPickExpiryDate	 NVARCHAR(50)
	DECLARE @v_vchPickSerialNumber	 NVARCHAR(100)
	DECLARE @v_vchPickAttribute1	 NVARCHAR(100)
	DECLARE @v_vchPickAttribute2	 NVARCHAR(100)
	DECLARE @v_vchPickAttribute3	 NVARCHAR(100)
	DECLARE @v_vchPickAttribute4	 NVARCHAR(100)
	DECLARE @v_vchPickAttribute5	 NVARCHAR(100)
	DECLARE @v_fltPickQtyRemainPick	 FLOAT
	DECLARE @v_dtPickReceiptDate	 DATE
	DECLARE @v_vchPickItemStatus	 NVARCHAR(50)
	DECLARE @v_fltQtyInputUpdate	 FLOAT	--ยอดจำนวน Input มา
	DECLARE @v_fltQtyPickUpdate		 FLOAT	--ยอดจำนวนที่จะ Unallocate และ update plan qty

	SET @v_fltQtyInputUpdate = @v_fltBaseInputQuantity
	DECLARE PickDetailCursor CURSOR FOR
		SELECT pickDT.outbound_pick_detail_id
			,pickDT.location_id
			,pickDT.parent_lpn
			,pickDT.lpn
			,pickDT.wh_item_master_id
			,pickDT.lot_number
			,pickDT.expiry_date
			,pickDT.serial_number
			,pickDT.attribute1
			,pickDT.attribute2
			,pickDT.attribute3
			,pickDT.attribute4
			,pickDT.attribute5
			,ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) AS quantity_remain_pick
			,pickDT.receive_date
			,obDT.default_item_status
		FROM #tOutboundPickDetail pickDT
		INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
		INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
		INNER JOIN t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
		LEFT JOIN t_wms_rule tRule ON uom.picking_class = tRule.rule_id
		ORDER BY CASE WHEN tRule.rule_code = 'RULE_PICK_BY_FEFO' THEN pickDT.expiry_date END DESC,pickDT.receive_date DESC, pickDT.lot_number DESC,loc.pick_sequence DESC,loc.location DESC,pickDT.parent_lpn DESC, pickDT.lpn DESC
	OPEN PickDetailCursor
	FETCH NEXT FROM PickDetailCursor INTO @v_vchPickOBPickDetailID,@v_vchPickLocationID,@v_vchPickParentLPN,@v_vchPickLPN,@v_vchPickWhItemMasterID,@v_vchPickLotNumber,@v_vchPickExpiryDate,@v_vchPickSerialNumber
										,@v_vchPickAttribute1,@v_vchPickAttribute2,@v_vchPickAttribute3,@v_vchPickAttribute4,@v_vchPickAttribute5,@v_fltPickQtyRemainPick,@v_dtPickReceiptDate,@v_vchPickItemStatus
	WHILE @@FETCH_STATUS = 0
		BEGIN
			-- หา ยอดที่ต้อง unallocate  qty input < remain = qty input else remain qty
			IF @v_fltQtyInputUpdate < @v_fltPickQtyRemainPick
				SET @v_fltQtyPickUpdate = @v_fltQtyInputUpdate
			ELSE
				SET	@v_fltQtyPickUpdate = @v_fltPickQtyRemainPick

			-- Update pick detail
			UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyPickUpdate,@Round)
			WHERE outbound_pick_detail_id = @v_vchPickOBPickDetailID

			-- un allocate inventory data
			EXEC [usp_inventory_un_allocate]  @in_vchApplicationID		= @in_vchApplicationID	
											, @in_vchWarehouseMasterID	= @v_vchWhMasterID	
											, @in_vchLocationID			= @v_vchPickLocationID
											, @in_vchParentLPN			= @v_vchPickParentLPN	
											, @in_vchLPN				= @v_vchPickLPN
											, @in_vchWhItemMasterID		= @v_vchPickWhItemMasterID
											, @in_fltQuantity			= @v_fltQtyPickUpdate	
											, @in_vchSerialNumber		= @v_vchPickSerialNumber	
											, @in_vchLotNumber			= @v_vchPickLotNumber	
											, @in_vchExpiryDate			= @v_vchPickExpiryDate
											, @in_vchAttribute1			= @v_vchPickAttribute1
											, @in_vchAttribute2			= @v_vchPickAttribute2
											, @in_vchAttribute3			= @v_vchPickAttribute3
											, @in_vchAttribute4			= @v_vchPickAttribute4
											, @in_vchAttribute5			= @v_vchPickAttribute5
											, @in_dtReceiveDate			= @v_dtPickReceiptDate
											, @in_vchDefaultItemStatus	= @v_vchPickItemStatus
											, @in_vchUserID				= @in_vchUserID	
											, @out_ErrorCode			= @out_ErrorCode	OUTPUT
											, @out_ErrorMessage			= @out_ErrorMessage OUTPUT
			IF (@out_ErrorCode <> '0')
				BEGIN 
					GOTO WRITE_PROC;
				END
			
			SET @v_fltQtyInputUpdate = @v_fltQtyInputUpdate - @v_fltQtyPickUpdate
			IF ISNULL(@v_fltQtyPickUpdate,0) = 0
				BREAK;
			
			FETCH NEXT FROM PickDetailCursor INTO  @v_vchPickOBPickDetailID,@v_vchPickLocationID,@v_vchPickParentLPN,@v_vchPickLPN,@v_vchPickWhItemMasterID,@v_vchPickLotNumber,@v_vchPickExpiryDate,@v_vchPickSerialNumber
										,@v_vchPickAttribute1,@v_vchPickAttribute2,@v_vchPickAttribute3,@v_vchPickAttribute4,@v_vchPickAttribute5,@v_fltPickQtyRemainPick,@v_dtPickReceiptDate,@v_vchPickItemStatus
		END
	CLOSE PickDetailCursor                  	
	DEALLOCATE PickDetailCursor

	------------------------------------------------------------
	--Clear Pick Detail ที่ Plan Qty = 0
	------------------------------------------------------------
	DELETE t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_plan,0) = 0

	------------------------------------------------------------
	-- Outbound detail ที่ยังไม่มี picklist หรือจำนวน plan ยังไม่ครบ
	-- เอาเฉพาะ Outbound Detail ตรงตามเงื่อนไขก่อน override
	------------------------------------------------------------
	DECLARE @v_vchOutboundDetailID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_fltRemainQtyOrder	FLOAT
	DECLARE @v_vchLineNumber		NVARCHAR(10)
	DECLARE @v_vchItemStatusID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemStatus		NVARCHAR(50)
	DECLARE @v_fltQtyCanPick		FLOAT
	DECLARE @v_fltRemainQtyCanPick	FLOAT
	DECLARE @v_fltQtyPick			FLOAT

	---------------------------------------------------------------
	--Get Inventory รายการของสินค้าจากที่หยิบมา					
	---------------------------------------------------------------
	DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvSerialNumber	NVARCHAR(100)= NULL
	DECLARE @v_fltInvQuantity		FLOAT
	DECLARE @v_dtInvReceiveDate		DATE
	DECLARE @v_dtInvMfgDate			DATE
	declare @v_vchOutboundPickDetailID UNIQUEIDENTIFIER = NULL

	DECLARE OutboundDetailCursor CURSOR FOR
		SELECT obDT.outbound_order_detail_id
			,ROUND(ISNULL(obDT.quantity_order,0) - ISNULL(pickDT.quantity_plan,0),@Round) AS remain_qty_order
			,invST.inventory_status_id
			,obDT.default_item_status
			,obDT.line_number
		FROM t_wms_outbound_detail obDT
		LEFT JOIN (SELECT outbound_order_detail_id, SUM(quantity_plan) AS quantity_plan
				   FROM t_wms_outbound_pick_detail
				   WHERE is_override = 'NO'
				   GROUP BY outbound_order_detail_id
				   ) pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
		LEFT JOIN t_wms_inventory_status invST ON obDT.default_item_status = invST.inv_status
		WHERE obDT.outbound_order_master_id = @in_vchOutboundMasterID
		AND obDT.outbound_order_detail_id IN (SELECT outbound_order_detail_id FROM #tOutboundPickDetail)
		ORDER BY obDT.line_number
	OPEN OutboundDetailCursor
	FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_fltRemainQtyOrder,@v_vchItemStatusID,@v_vchItemStatus,@v_vchLineNumber
	WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @v_fltQtyCanPick = 0
 			SET @v_dtStartTime = GETDATE();

			---------------------------------------------------------------
			-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ				
			---------------------------------------------------------------
			IF (ROUND(@v_fltRemainQtyOrder,@Round) > ROUND(@v_fltBaseInputQuantity,@Round))
				SET @v_fltQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
			ELSE
				SET @v_fltQtyCanPick = ROUND(@v_fltRemainQtyOrder,@Round)
		
			---------------------------------------------------------------
			-- สำหรับใช้กรณีของ Serial เนื่องจากต้องมีการ วน serail case all 
			-- โดยที่ @v_fltQtyCanPick ยังต้องคงค่าไว้ เพื่อจะได้รู้ว่า เหลือจำนวนเท่าไหร่ที่ต้องวน
			---------------------------------------------------------------
			SET @v_fltRemainQtyCanPick = ROUND(@v_fltQtyCanPick,@Round)
  
			DECLARE InventoryCursor CURSOR FOR
				SELECT inventory_id
					,attribute_group_id
					,serial_number
					,quantity - ISNULL(quantity_allocated,0)
					,receive_date
					,mfg_date
				FROM v_wms_inventory_data_serial_by_id
				WHERE wh_master_id = @v_vchWhMasterID
				AND location_id = @in_vchOverrideLocationID
				AND wh_item_master_id = @in_vchWhItemMasterID
				AND inventory_status_id = @v_vchItemStatusID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchOverrideLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@in_vchOverrideLotNumber,'')
				AND ISNULL(expiry_date,'')= ISNULL(@in_vchOverrideExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchOverrideAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchOverrideAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchOverrideAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchOverrideAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchOverrideAttribute5,'')
				AND (CASE @in_vchOverrideSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE @in_vchOverrideSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchOverrideSerialNumber,'') END)
				ORDER BY receive_date, serial_number
			OPEN InventoryCursor
			FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_fltInvQuantity,@v_dtInvReceiveDate,@v_dtInvMfgDate
			IF(@@ROWCOUNT > 0)
				BEGIN
					WHILE @@FETCH_STATUS = 0
						BEGIN
							--------------------------------------------------------------
							-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ				
							---------------------------------------------------------------
							IF (@v_fltQtyCanPick > @v_fltInvQuantity)
								SET @v_fltQtyPick = @v_fltInvQuantity
							ELSE
								SET @v_fltQtyPick = @v_fltQtyCanPick

							-----------------------------------------------------
							-- Validate Duplicate Serial Number ใน Pick Detail
							-----------------------------------------------------
							IF (@v_vchSNControl = 'FULL')
								BEGIN
									SET @v_fltInvQuantity = 1
									SET @v_fltQtyPick = 1   -- กรณีของ Serial Qty Pick = 1
									IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND serial_number = @v_vchInvSerialNumber AND is_override = 'NO')
										BEGIN
											SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
											SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchInvSerialNumber,@v_vchItemNumber,'@param3','@param4','@param5')
											GOTO WRITE_PROC;
										END
								END

							---------------------------------------------------		
							--Update Outbound Detail
							---------------------------------------------------		
							UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
								,quantity_stage = CASE WHEN @RuleAutoStaging = 'YES' THEN ROUND(ISNULL(quantity_stage,0) + @v_fltQtyPick,@Round) ELSE quantity_stage END
								,item_status = 'PICK'
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND outbound_order_detail_id = @v_vchOutboundDetailID 
							AND wh_item_master_id = @in_vchWhItemMasterID

							---------------------------------------------------	
							--Check ว่ามี recode picklist เดิมหรือไม่ ถ้ามีให้ทำการ update
							---------------------------------------------------	
							SET @v_vchOutboundPickDetailID = NULL
							SELECT @v_vchOutboundPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
							WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
							AND outbound_order_detail_id = @v_vchOutboundDetailID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND location_id = @in_vchOverrideLocationID
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@in_vchOverrideLPN,'') 
							AND ISNULL(lot_number,'') = ISNULL(@in_vchOverrideLotNumber,'') 
							AND ISNULL(expiry_date,'') =  ISNULL(@in_vchOverrideExpiryDate,'')
							AND ISNULL(serial_number,'') =  ISNULL(@v_vchInvSerialNumber,'')
							AND ISNULL(attribute1,'') =  ISNULL(@in_vchOverrideAttribute1,'')
							AND ISNULL(attribute2,'') =  ISNULL(@in_vchOverrideAttribute2,'')
							AND ISNULL(attribute3,'') =  ISNULL(@in_vchOverrideAttribute3,'')
							AND ISNULL(attribute4,'') =  ISNULL(@in_vchOverrideAttribute4,'')
							AND ISNULL(attribute5,'') =  ISNULL(@in_vchOverrideAttribute5,'')
							AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
							ANd pick_location_id = @v_vchForkLocationID
							AND receive_date = @v_dtInvReceiveDate
							AND is_override = 'NO'

							IF @v_vchOutboundPickDetailID IS NULL
								BEGIN
									--Insert Pick list
									DECLARE @v_vchNewPickLineNumber NVARCHAR(10) = ''
									SET @v_vchOutboundPickDetailID = NEWID()
									SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
									IF (@v_vchNewPickLineNumber IS NULL)
										BEGIN SET @v_vchNewPickLineNumber = '00001'; END
									ELSE
										BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

									INSERT INTO [dbo].[t_wms_outbound_pick_detail]
											([outbound_pick_detail_id]
											,[outbound_pick_master_id]
											,[outbound_order_detail_id]
											,[pick_line_number]
											,[location_id]
											,[pick_location_id]
											,[pick_to_lpn]
											,[pick_to_parent_lpn]
											,[wh_item_master_id]
											,[quantity_plan]
											,[quantity_pick] 
											,[quantity_stage]
											,[quantity_pack]
											,[quantity_load]
											,[quantity_ship] 
											,[parent_lpn]
											,[lpn]
											,[lot_number]
											,[expiry_date]
											,[serial_number]
											,[attribute1]
											,[attribute2]
											,[attribute3]
											,[attribute4]
											,[attribute5]
											,[user_assign]
											,[staging_location_id]
											,[staging_parent_lpn]
											,[staging_lpn] 
											,[pick_status] 
											,[inventory_id] 
											,[pick_generate_method]
											,[is_allocate]
											,[is_override]
											,[pick_override_reason]
											,[receive_date]
											,[mfg_date]
											,[is_active]
											,[start_date_time]
											,[end_date_time]
											,[create_date]
											,[create_by])
									VALUES (@v_vchOutboundPickDetailID	
											, @v_vchOutboundPickMasterID						 
											, @v_vchOutboundDetailID							 
											, @v_vchNewPickLineNumber							 
											, @in_vchOverrideLocationID							 
											, @v_vchForkLocationID								 
											, @v_vchPickToLPN									 
											, @in_vchParentLPN									 
											, @in_vchWhItemMasterID								 
											, ROUND(@v_fltQtyPick,@Round)	--quantity_plan		 
											, ROUND(@v_fltQtyPick,@Round)	--quantity_pick		 
											, CASE WHEN @RuleAutoStaging = 'YES' THEN ROUND(@v_fltQtyPick,@Round) ELSE 0 END 	--quantity_stage	 
											, CASE WHEN @RulePickPack = 'YES' THEN ROUND(@v_fltQtyPick,@Round) ELSE 0 END		--quantity_pack
											, 0		--[quantity_load]								 
											, 0		--[quantity_ship] 								 
											, CASE WHEN ISNULL(@in_vchParentLPN,'') = '' then NULL ELSE ISNULL(@in_vchParentLPN,'') END
											, CASE WHEN ISNULL(@in_vchOverrideLPN,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLPN,'') END
											, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END
											, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END
											, CASE WHEN ISNULL(@v_vchInvSerialNumber,'') = '' then NULL ELSE ISNULL(@v_vchInvSerialNumber,'') END
											, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END
											, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END
											, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END
											, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END
											, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END
											, NULL		--[user_assign]
											, CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocationID ELSE NULL END
											, CASE WHEN @RuleAutoStaging = 'YES' THEN @in_vchParentLPN ELSE NULL END
											, CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchPickToLPN ELSE NULL END
											, 'YES'
											, @v_vchInvID
											, 'SYSTEM_DIRECT'
											, 'NO'
											, 'NO'
											, 'OVERRIDE'
											, @v_dtInvReceiveDate
											, @v_dtInvMfgDate
											, 'YES'
											, GETDATE()
											, GETDATE()
											, GETDATE()
											, @in_vchUserID
										)														 
								END
							ELSE
								BEGIN
									--Update Pick list
									UPDATE t_wms_outbound_pick_detail SET 
										 quantity_plan		  = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyPick,@Round)
										, quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
										, quantity_stage	  = CASE WHEN @RuleAutoStaging = 'YES' THEN ROUND(ISNULL(quantity_stage,0) + @v_fltQtyPick,@Round) ELSE quantity_stage END
										, quantity_pack		  = CASE WHEN @RulePickPack = 'YES' THEN ROUND(ISNULL(quantity_pack,0) + @v_fltQtyPick,@Round) ELSE quantity_pack END
										, pick_location_id    = @v_vchForkLocationID
										, pick_to_parent_lpn  = @in_vchParentLPN
										, pick_to_lpn		  = @v_vchPickToLPN
										, staging_location_id = CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocationID ELSE staging_location_id END
										, staging_parent_lpn  = CASE WHEN @RuleAutoStaging = 'YES' THEN @in_vchParentLPN ELSE staging_parent_lpn END
										, staging_lpn		  = CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchPickToLPN  ELSE staging_lpn END
										, pick_status         = 'YES'
										, start_date_time	  = ISNULL(start_date_time,GETDATE())
										, end_date_time		  = GETDATE()
										, serial_number		  = @v_vchInvSerialNumber
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
								END
 
							---------------------------------------------------
							-- Insert/Update Pack Detail
							---------------------------------------------------
							IF (@RulePickPack = 'YES')
								BEGIN
									---------------------------------------------------
									--Insert/Update Pack Detail
									---------------------------------------------------
									PRINT 'Pick and Pack'
									IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
												WHERE outbound_order_master_id = @in_vchOutboundMasterID
												AND pack_location_id = @v_vchForkLocationID
												AND lpn_pack = @v_vchPickToLPN 
												AND wh_item_master_id = @in_vchWhItemMasterID 
												AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
												AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
										BEGIN
											UPDATE t_wms_outbound_pack_detail SET 
												 quantity_pack = ROUND(quantity_pack + @v_fltQtyPick,@Round)
												,quantity_stage = CASE WHEN @RuleAutoStaging = 'YES' THEN ROUND(ISNULL(quantity_stage,0) + @v_fltQtyPick,@Round) ELSE quantity_stage END
											WHERE outbound_order_master_id = @in_vchOutboundMasterID 
											AND pack_location_id = @v_vchForkLocationID
											AND lpn_pack = @v_vchPickToLPN 
											AND wh_item_master_id = @in_vchWhItemMasterID 
											AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
											AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
										END
									ELSE
										BEGIN
											INSERT INTO t_wms_outbound_pack_detail
											(     outbound_order_master_id
												, outbound_pick_detail_id
												, lpn_pack
												, pack_location_id
												, wh_item_master_id
												, quantity_pack
												, quantity_stage
												, lot_number
												, expiry_date
												, serial_number
												, [attribute1]
												, [attribute2]
												, [attribute3]
												, [attribute4]
												, [attribute5]
												, item_uom_id
												, [staging_location_id]
												, [staging_parent_lpn]
												, [staging_lpn]
												, create_by
											)
											VALUES
											(     @in_vchOutboundMasterID
												, @v_vchOutboundPickDetailID
												, @v_vchPickToLPN
												, @v_vchForkLocationID
												, @in_vchWhItemMasterID
												, ROUND(@v_fltQtyPick,@Round)
												, (CASE WHEN @RuleAutoStaging = 'YES' THEN ROUND(@v_fltQtyPick,@Round) ELSE 0 END)
												, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END
												, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END
												, CASE WHEN ISNULL(@v_vchInvSerialNumber,'') = '' then NULL ELSE ISNULL(@v_vchInvSerialNumber,'') END
												, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END
												, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END
												, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END
												, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END
												, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END
												, @v_vchBaseItemUomID
												, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchStagingLocationID ELSE NULL END)
												, (CASE WHEN @RuleAutoStaging = 'YES' THEN @in_vchParentLPN ELSE NULL END)
												, (CASE WHEN @RuleAutoStaging = 'YES' THEN @v_vchPickToLPN ELSE NULL END)
												, @in_vchUserID
											)
										END
								END

							---------------------------------------------------
							--Calculate Volumn & Weight
							---------------------------------------------------
							IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyPick,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyPick,2)
							END

							---------------------------------------------------
							-- Manage source location data
							---------------------------------------------------
							BEGIN
								--Update Volumn & Weight in from location
								IF @in_vchOverrideLocationID IS NOT NULL
									BEGIN
										UPDATE [dbo].[t_wms_location]
										   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
											, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
											, update_date = GETDATE()  
											, [update_by] = @in_vchUserID   
										 WHERE [location_id] = @in_vchOverrideLocationID
									END

								--Case Overrride ไม่ต้อง Clear ยอด Allocate เนื่องจากเป็นการ override มามันไม่ใช่ของที่จองไว้
								UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
									,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
									,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID

								IF (@v_vchSNControl = 'FULL')
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round) 
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID 
										AND attribute_value = @v_vchInvSerialNumber
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END

								IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID
										AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END
							END

							------------------------------------------------
							-- Clear Inventory ที่หยิบของหมดแล้ว
							------------------------------------------------
							DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
							DELETE FROM t_wms_inventory WHERE quantity <= 0 

							--------------------------------------------
							--Manage Destination inventory
							--------------------------------------------
							DECLARE @v_vchInventoryID UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchAttributeGroupID UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchDestLocationID UNIQUEIDENTIFIER = NULL
							IF (@RuleAutoStaging = 'YES')
								BEGIN
									SET @v_vchDestLocationID = @v_vchStagingLocationID
								END
							ELSE
								BEGIN
									SET @v_vchDestLocationID = @v_vchForkLocationID
								END

							SELECT @v_vchInventoryID = inventory_id
								,@v_vchAttributeGroupID = attribute_group_id
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @v_vchWhMasterID
							AND owner_id = @v_vchOwnerID
							AND location_id = @v_vchDestLocationID
							AND wh_item_master_id = @in_vchWhItemMasterID
							AND inventory_status_id = @v_vchItemStatusID
							and receive_date = @v_dtInvReceiveDate
							AND ISNULL(parent_lpn,'') = ISNULL(@in_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@in_vchOverrideLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@in_vchOverrideExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@in_vchOverrideAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@in_vchOverrideAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@in_vchOverrideAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@in_vchOverrideAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@in_vchOverrideAttribute5,'')

							EXEC usp_manage_inventory @in_vchWHMasterID		= @v_vchWhMasterID
													, @in_vchOwnerID		= @v_vchOwnerID
													, @in_vchWHItemMasterID	= @in_vchWhItemMasterID
													, @in_vchLocationID		= @v_vchDestLocationID
													, @in_vchStatusID		= @v_vchItemStatusID
													, @in_vchPalentLPN		= @in_vchParentLPN
													, @in_vchLPN			= @v_vchPickToLPN
													, @in_fltQty			= @v_fltQtyPick
													, @in_fltQtyAllocate	= 0
													, @in_fltQtyIncoming	= 0
													, @in_vchInventoryType	= @v_vchOutboundNumber
													, @in_vchUserID			= @in_vchUserID
													, @in_vchReceiveDate	= @v_dtInvReceiveDate
													, @in_dtMFGDate			= @v_dtInvMfgDate
													, @in_vchInventoryID	= @v_vchInventoryID OUTPUT
													, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
													, @in_vchErrorCode		= @out_ErrorCode OUTPUT
													, @in_vchMessage		= @out_ErrorMessage OUTPUT	
							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;

							--Update Volumn & Weight in from location
							IF @v_vchDestLocationID IS NOT NULL
								BEGIN
									UPDATE [dbo].[t_wms_location]
										SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
										, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID   
									WHERE [location_id] = @v_vchDestLocationID
								END
								 
							--update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET
								 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttributeGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
										  @in_vchLot				= @in_vchOverrideLotNumber
										, @in_vchExpiryDate			= @in_vchOverrideExpiryDate
										, @in_vchSerialNo			= @v_vchInvSerialNumber
										, @in_vchAttribute1			= @in_vchOverrideAttribute1
										, @in_vchAttribute2			= @in_vchOverrideAttribute2
										, @in_vchAttribute3			= @in_vchOverrideAttribute3
										, @in_vchAttribute4			= @in_vchOverrideAttribute4
										, @in_vchAttribute5			= @in_vchOverrideAttribute5
										, @in_fltQty				= @v_fltQtyPick
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInventoryID
										, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END	
					
							---------------------------------------------------		
							-- Write Tran Log  
							---------------------------------------------------		
							IF (@RuleAutoStaging = 'YES')
							BEGIN
								--Write Lot Pick to STG
								INSERT INTO t_com_tran_log
									( app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, line_number 
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'MOVE_DEST'
									, @v_vchApplicationName
									, 'Override - Update pick to staging [Auto to Staging]'
									, @v_dtStartTime
									, DATEADD(millisecond,2,GETDATE())
									, @v_vchWarehouse
									, @v_vchWarehouse
									, @in_vchOverrideLocation
									, @v_vchStagingLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @v_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, @v_fltInvQuantity - @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END
									, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END
									, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END
									, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END 
									, CASE WHEN ISNULL(@v_vchInvSerialNumber,'') = '' then NULL ELSE ISNULL(@v_vchInvSerialNumber,'') END			
									, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END 
									, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END 
									, @in_vchUserID 
									, CASE WHEN ISNULL(@in_vchParentLPN,'') = '' then NULL ELSE ISNULL(@in_vchParentLPN,'') END  
									, CASE WHEN ISNULL(@in_vchParentLPN,'') = '' then NULL ELSE ISNULL(@in_vchParentLPN,'') END  
									, @in_vchOverrideLPN
									, @v_vchPickToLPN
									, @v_vchItemStatus
									, @v_vchItemStatus 
									, @v_vchOutboundNumber
									, @v_vchLineNumber  
									, @in_vchDeviceID
									, @in_vchUserID
									, DATEADD(millisecond,2,GETDATE())
									, @in_vchOverrideLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)

								----------------------------------------
								--Insert For Checker RFID
								--ต้องทำตอน วาง STG
								----------------------------------------
								IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
									BEGIN
										IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @in_vchOutboundMasterID AND serial_number = @v_vchInvSerialNumber)
											BEGIN
												INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
														([checker_rfid_id]
														,[processing_status]
														,[outbound_order_master_id]
														,[serial_number]
														,[user_id]
														,[device]
														,[create_by]
														,[create_date])
													VALUES
														(NEWID()
														,'PENDING'
														,@in_vchOutboundMasterID
														,@v_vchInvSerialNumber
														,@in_vchUserID
														,@in_vchDeviceID
														,@in_vchUserID
														,GETDATE())
											END
									END
							END
							ELSE
							BEGIN
								--Write Log Pick to Fork
								INSERT INTO t_com_tran_log
								(     app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, line_number 
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'SALES_ORDER'
									, @v_vchApplicationName
									, 'Override - System Directed Picking'
									, @v_dtStartTime
									, GETDATE()
									, @v_vchWarehouse
									, @v_vchWarehouse
									, @in_vchOverrideLocation
									, @in_vchForkLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @v_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, @v_fltInvQuantity - @v_fltQtyPick 
									, @v_vchBaseUomPrompt
									, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END
									, CASE WHEN ISNULL(@in_vchOverrideLotNumber,'') = '' then NULL ELSE ISNULL(@in_vchOverrideLotNumber,'') END	
									, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END
									, CASE WHEN ISNULL(@in_vchOverrideExpiryDate,'') = '' then NULL ELSE ISNULL(@in_vchOverrideExpiryDate,'') END
									, CASE WHEN ISNULL(@v_vchInvSerialNumber,'') = '' then NULL ELSE ISNULL(@v_vchInvSerialNumber,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute1,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute1,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute2,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute2,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute3,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute3,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute4,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute4,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END
									, CASE WHEN ISNULL(@in_vchOverrideAttribute5,'') = '' then NULL ELSE ISNULL(@in_vchOverrideAttribute5,'') END
									, @in_vchUserID
									, CASE WHEN ISNULL(@in_vchParentLPN,'') = '' then NULL ELSE ISNULL(@in_vchParentLPN,'') END 
									, CASE WHEN ISNULL(@in_vchParentLPN,'') = '' then NULL ELSE ISNULL(@in_vchParentLPN,'') END 
									, @in_vchOverrideLPN
									, @v_vchPickToLPN
									, @v_vchItemStatus
									, @v_vchItemStatus
									, @v_vchOutboundNumber
									, @v_vchLineNumber 
									, @in_vchDeviceID	
									, @in_vchUserID		
									, GETDATE()
									, @in_vchOverrideLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)
							END

							--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
							SET @v_fltQtyCanPick = @v_fltQtyCanPick - @v_fltQtyPick

							--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
							IF @v_fltQtyCanPick = 0
								BREAK;

							FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_fltInvQuantity,@v_dtInvMfgDate
						END
				END
			ELSE
				BEGIN
					-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
					SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,@in_vchOverrideLotNumber,@in_vchExpiryDate,@in_vchOverrideLPN,'@param5')			
					GOTO WRITE_PROC;
				END
			CLOSE InventoryCursor
			DEALLOCATE InventoryCursor
			 
			-- For Dashboard
			BEGIN
				DECLARE @v_vchDSToLocationID UNIQUEIDENTIFIER = NULL 
				IF @RuleAutoStaging = 'YES'
					BEGIN
						SET @v_vchDSToLocationID = @v_vchStagingLocationID 
					END
				ELSE
					BEGIN  
						SET @v_vchDSToLocationID = @v_vchForkLocationID 
					END
				EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
												,@in_vchTransType	 = 'PICK'
												,@in_vchWhMasterID	 = @v_vchWhMasterID
												,@in_vchOwnerID		 = @v_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwnerCode
												,@in_vchLocationID	 = @in_vchOverrideLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @v_vchItemStatusID
												,@in_vchToWhMasterID = @v_vchWhMasterID
												,@in_vchToLocationID = @v_vchDSToLocationID
												,@in_vchToInvStatusID = @v_vchItemStatusID
												,@in_fltQuantity	 = @v_fltQtyCanPick
												,@in_vchUserID		 = @in_vchUserID
			END

			SET @v_fltBaseInputQuantity = @v_fltBaseInputQuantity - @v_fltQtyCanPick
			IF @v_fltQtyCanPick = 0
				BREAK;

			FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_fltRemainQtyOrder,@v_vchItemStatusID,@v_vchItemStatus,@v_vchLineNumber
		END
	CLOSE OutboundDetailCursor
	DEALLOCATE OutboundDetailCursor

	------------------------------------------------
	-- Update Order Status ถ้า Pick ครบแล้ว
	------------------------------------------------
	IF ((SELECT SUM(quantity_order - ISNULL(quantity_pick,0)) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID) = 0)
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PICKED',update_by = @in_vchUserID, update_date = GETDATE()
			WHERE outbound_order_master_id = @in_vchOutboundMasterID 
			AND order_status NOT IN ('LOADING','LOADED')
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID, order_status = 'PICK',update_by = @in_vchUserID, update_date = GETDATE()
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
		END
	
	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','PickDetailCursor')>=-1
		BEGIN
			CLOSE PickDetailCursor;
			DEALLOCATE PickDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END	
				  
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData = 'Qty: ' + convert(varchar,@in_fltQty) + ' ' + @in_vchUOMPrompt;
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundNumber,
			@in_vchData2 = @in_vchOverrideLocation,
			@in_vchData3 = @v_vchItemNumber,
			@in_vchData4 = @v_vchProcessData,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
	
	IF CURSOR_STATUS('global','PickDetailCursor')>=-1
		BEGIN
			CLOSE PickDetailCursor;
			DEALLOCATE PickDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQty) + ' ' + @in_vchUOMPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundNumber,
		@in_vchData2 = @in_vchOverrideLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
				
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_pack_all]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-05-21
-- Description:	Check stock quantity
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_pack_all]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchOrderNumber		NVARCHAR(50),
	@in_vchLPNPack			NVARCHAR(25),
	@in_vchPackLocation		NVARCHAR(50),
	@in_vchPackData			NVARCHAR(MAX),
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE
	@DocHandle					Int,
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchOutboundOrderMasterID	NVARCHAR(40),
	@v_vchOutboundPickDetailID	NVARCHAR(40),
	@v_vchWHMasterID			NVARCHAR(40),
	@v_vchWHItemMasterID		NVARCHAR(40),
	@v_vchItemMasterID			NVARCHAR(40),
	@v_vchLocationID			NVARCHAR(40),
	@v_vchUOMID					NVARCHAR(40),
	@v_dtProcessDateTime		DATETIME,
	@c_vchObjName				NVARCHAR(20),
	@v_vchData1					NVARCHAR(1000),
	@v_vchData2					NVARCHAR(1000),
	@v_fltStageQuantity			FLOAT,
	@v_fltPackQuantity			FLOAT,
	@v_vchLPN					NVARCHAR(25),
	@v_vchLot					NVARCHAR(50),
	@v_vchExpiryDate			NVARCHAR(8),
	@v_vchItem					NVARCHAR(50),
	@v_fltQty					FLOAT,
	@v_vchUOM					NVARCHAR(10),
	@v_vchSerial				NVARCHAR(50),
	@v_vchLineNumber			NVARCHAR(5),
	@v_vchFromLocation			NVARCHAR(50),
	@v_vchOutboundOrderDetailID	NVARCHAR(40),
	@v_vchOutboundOrderNumber	NVARCHAR(50)
	
	Begin Try
		Begin Transaction
		set @c_vchObjName = '[usp_outbound_pack_all]';
		
		Exec sp_xml_preparedocument @DocHandle Output,@in_vchPackData
		
		select @v_vchWHMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		--select @v_vchApplicationName = application_name from t_com_application where app_id = @in_vchApplicationID
		
		exec usp_get_application_name @in_vchApplicationID,@v_vchApplicationName output
		
		select @v_vchLocationID = location_id  from t_wms_location where location = @in_vchPackLocation
		select @v_vchOutboundOrderMasterID = outbound_order_master_id from t_wms_outbound_master where outbound_order_number = @in_vchOrderNumber and wh_master_id = @v_vchWHMasterID;

		declare cursorOutboundPackDetail scroll cursor for
			Select wh_item_master_id,item_number,quantity_confrim_pack,uom_prompt,lot_number,[expiry_date],serial_number,line_number,outbound_pick_detail_id,outbound_order_detail_id
			From OpenXML(@DocHandle,'ConfirmPack/ConfirmPack',2)
			With(wh_item_master_id nvarchar(40),item_number nvarchar(50),quantity_confrim_pack float,uom_prompt nvarchar(10),lot_number nvarchar(50),[expiry_date] nvarchar(8),serial_number nvarchar(50),line_number nvarchar(5),outbound_pick_detail_id varchar(40),outbound_order_detail_id nvarchar(40))

		open cursorOutboundPackDetail;
		fetch cursorOutboundPackDetail into @v_vchWHItemMasterID,@v_vchItem,@v_fltQty,@v_vchUOM,@v_vchLot,@v_vchExpiryDate,@v_vchSerial,@v_vchLineNumber,@v_vchOutboundPickDetailID,@v_vchOutboundOrderDetailID
					
			While @@FETCH_STATUS = 0
				Begin
					If (@v_fltQty > 0)
						Begin
							select @v_vchItemMasterID = item_master_id from t_wms_item  where item_number = @v_vchItem
							select @v_vchUOMID = item_uom_id from t_wms_item_uom where item_master_id = @v_vchItemMasterID and uom_prompt = @v_vchUOM
							
							insert into t_wms_outbound_pack_detail(outbound_order_master_id, lpn_pack, pack_location_id, wh_item_master_id, quantity_pack, lot_number, [expiry_date], serial_number, item_uom_id, create_by)
							values(@v_vchOutboundOrderMasterID,@in_vchLPNPack,@v_vchLocationID,@v_vchWHItemMasterID,@v_fltQty,@v_vchLot,@v_vchExpiryDate,@v_vchSerial,@v_vchUOMID,@in_vchUserID)
							
							If (ISNULL(@v_vchOutboundPickDetailID,'') <> '')
								Begin
									select @v_fltStageQuantity = quantity_stage,@v_fltPackQuantity = quantity_pack from t_wms_outbound_pick_detail where outbound_pick_detail_id = @v_vchOutboundPickDetailID
									If(@v_fltPackQuantity + @v_fltQty > @v_fltStageQuantity)
										Begin
											set @out_ErrorCode = '999';
											--set @out_ErrorMessage = 'Quantity Pack must less than Quantity Staging.Please check data again.';
											select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QTY_PACK_MUST_LESS_THAN_QTY_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
											Rollback Transaction;
											return;						
										End
									Else
										Begin
											update t_wms_outbound_pick_detail set quantity_pack = quantity_pack + @v_fltQty
											where outbound_pick_detail_id = @v_vchOutboundPickDetailID
											
											update t_wms_outbound_master set order_status = 'PACK'
											where  outbound_order_master_id = @v_vchOutboundOrderMasterID  
										End
								End
							Else
								Begin
									set @out_ErrorCode = '999';
									--set @out_ErrorMessage = 'Data pick detail not found!';
									select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'DATA_PICK_DETAIL_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
									Rollback Transaction;
									return;
								End
						End
					
					fetch next from cursorOutboundPackDetail into @v_vchWHItemMasterID,@v_vchItem,@v_fltQty,@v_vchUOM,@v_vchLot,@v_vchExpiryDate,@v_vchSerial,@v_vchLineNumber,@v_vchOutboundPickDetailID,@v_vchOutboundOrderDetailID
				End
		
		exec sp_xml_removedocument @DocHandle;
		close cursorOutboundPackDetail;
		deallocate cursorOutboundPackDetail;
		set @v_dtProcessDateTime = GETDATE();	
		set @out_ErrorCode = '0';
		--set @out_ErrorMessage = 'SAVE SUCCESS';
		select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			
		exec usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchAppName = @v_vchApplicationName,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'TRANSACTION',
		@in_vchTranType = 'OO_PACK',
		@in_vchSubTranType = '',
		@in_vchProcess = 'Pack',
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_dtStartTranDate = @v_dtProcessDateTime,
		@in_vchLPN = @in_vchLPNPack,
		@in_vchItemNumber = @v_vchItem,
		@in_vchLotNumber = @v_vchLot,
		@in_dtExpiryDate = @v_vchExpiryDate,
		@in_vchSerialNumber	= @v_vchSerial,
		@in_vchToLocation = @in_vchPackLocation,
		@in_fltQuantity = @v_fltQty,
		@in_fltAfterQuantity = null,
		@in_vchReferenceNumber = null,
		@in_vchUOM = @v_vchUOM,
		@in_vchAfterUOM = @v_vchUOM,
		@in_vchData1 = 'Pack.',
		@in_vchData2 = null,
		@in_vchData3 = null,
		@in_vchData4 = null,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
		
		Commit Transaction
	End Try
	Begin Catch
		close cursorOutboundPackDetail;
		deallocate cursorOutboundPackDetail;
		Rollback Transaction;
		set @out_ErrorCode = @out_ErrorCode + '-' + ERROR_NUMBER();
		set @out_ErrorMessage = substring(@out_ErrorMessage + ERROR_MESSAGE(),0,100);
		
		SET @v_vchData1 = ERROR_PROCEDURE() + ': ' + @out_ErrorMessage 
					+ '. SQL Error ['+ str(ERROR_NUMBER()) + '], '
					+ '. Severity ['+ str(ERROR_SEVERITY()) + '],'
					+ '. State ['+ str(ERROR_STATE()) + '],'
					+ '. Line ['+ str(ERROR_LINE()) + '].'
							
		SET @v_dtProcessDateTime = getdate();
		set @v_vchData2 = 'Order number [' + @in_vchOrderNumber + ']';
		
		exec usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	End Catch
END


GO
