/****** Object:  StoredProcedure [dbo].[usp_outbound_pack_item_pda]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_pack_item_pda]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchItem				NVARCHAR(50),
	@in_vchOrderNumber		NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vchFromParentLPN	NVARCHAR(25) = null,
	@in_vchFromLPN			NVARCHAR(25) = null,
	@in_vchToParentLPN		NVARCHAR(25) = null,
	@in_vchToLPN			NVARCHAR(25) = null,
	@in_vchLot				NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNo			NVARCHAR(50) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_pack_item_pda]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
    
		@v_vchOutboundOrderMasterID	VARCHAR(40),
		@v_vchOutboundOrderDetailID	VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	NVARCHAR(40),
		@v_vchOutboundPackDetailID	NVARCHAR(40),
		@v_vchWarehouseMasterID		NVARCHAR(40),
		@v_vchWarehouseItemMasterID	VARCHAR(40),
		@v_vchFLocationMasterID		NVARCHAR(40),
		@v_vchTLocationMasterID		NVARCHAR(40),
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchLineNumber			NVARCHAR(10),
		@v_vhcUOMID					VARCHAR(40),
		@v_vchItemUOMID				VARCHAR(40),
		@Round						INT,
		@v_fltQuantity				FLOAT,
		@v_fltQuantityRemainPack	FLOAT,
		@v_vchOrderStatus			NVARCHAR(10),
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchMixItem				NVARCHAR(3),
		@v_vchMixLot				NVARCHAR(3),
		@v_vchMixOwner				NVARCHAR(3),
		@v_vchMixExpiryDate			NVARCHAR(3),
		@v_vchLPNControl			NVARCHAR(5),
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_fltSStockQuantity		FLOAT = 0,
		@v_fltDStockQuantity		FLOAT = 0,
		@v_fltBaseQuantity			FLOAT,
		@v_vchInventoryType			NVARCHAR(25),
		@v_vchDubLocation			NVARCHAR(50),
		@v_vchDubParentLPN			NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchOverride				NVARCHAR(3),
		-- Add new 2013-11-06 outbound multiline
		@v_vchAllowMulltiLineItem	NVARCHAR(3) = 'NO',
		@v_fltQtyUpdate				FLOAT = 0,
		@v_fltSumQuantityOrder		FLOAT,
		@v_fltSumQuantityPack		FLOAT,
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(MAX) = '',
		@v_vchDynamicSQLCondition	NVARCHAR(MAX) = '',
		@v_vchSerialNumber			NVARCHAR(50),
		@v_vchReceiveDate			DATE,
		@v_curInventoryData			CURSOR
   
	set @out_ErrorCode = '0';
	set @out_ErrorMessage = 'NO';
	select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'

	Begin Try
		
		set @in_fltQty = round(@in_fltQty,@Round)

		select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		select @v_vchFLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchFromLocation
		select @v_vchTLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchFromLocation
		select @v_vchOutboundOrderMasterID = outbound_order_master_id,@v_vchOrderStatus = order_status,@v_vchOwnerID = owner_id from t_wms_outbound_master where outbound_order_number = @in_vchOrderNumber

		-- Check item from t_wms_item, 885 and crossref	
		select	@in_vchItem = item_number,@v_vchItemMasterID = it.item_master_id,@v_vhcUOMID = iu.item_uom_id,
				@v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control
		from	t_wms_item it left outer join t_wms_item_crossref ic on it.item_master_id = ic.item_master_id
				left outer join t_wms_item_uom iu on it.item_master_id = iu.item_master_id 
		where	uom_prompt = @in_vchUOMPrompt and (item_number = @in_vchItem or dg_code = @in_vchItem 
				or alternate_item_number = @in_vchItem)
		If (isnull(@v_vchItemMasterID,'') = '')
			Begin
				set @out_ErrorCode = '403';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
				--Goto WRITE_PROC;
				RETURN;
			End
			
		-- Get Warehouse item id	
		select @v_vchWarehouseItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID
		
		-- ดึงข้อมูลแผนจ่าย ตาม item ,lot ,expiry date , lpn
		select TOP 1
				@v_fltQuantityRemainPack = sum(quantity_stage) - sum(quantity_pack),
				@v_vchItemUOMID = item_uom_id
		from v_wms_outbound_Pack_detail
		where wh_id = @in_vchWarehouse 
				and outbound_order_number = @in_vchOrderNumber 
				and staging_location = @in_vchFromLocation and item_number = @in_vchItem
				and Isnull(staging_parent_lpn,'') = Isnull(@in_vchFromParentLPN,'')
				and Isnull(staging_lpn,'') = Isnull(@in_vchFromLPN,'')
				and Isnull(lot_number,'') = Isnull(@in_vchLot,'')
				and Isnull([expiry_date],'') = Isnull(@in_vchExpiryDate,'')
				and Isnull(serial_number,'') = Isnull(@in_vchSerialNo,'')
				and quantity_stage - quantity_pack > 0
		group by wh_item_master_id,item_uom_id,uom_prompt
		--,Isnull(parent_lpn,''),Isnull(lpn,''),Isnull(lot_number,''),Isnull([expiry_date],'')
		If (@v_vhcUOMID <> @v_vchItemUOMID)
			Begin
				select @v_fltQuantity = @in_fltQty * conversion_factor from t_wms_item_uom where item_uom_id = @v_vhcUOMID

				select @v_fltQuantity = @v_fltQuantity / conversion_factor from t_wms_item_uom where item_uom_id = @v_vchItemUOMID
			End
		Else
			Begin
				set @v_fltQuantity = @in_fltQty;
			End
		
		set @v_vchDynamicSQL =
							'
							SELECT	inventory_id,
									attribute_group_id,
									owner_code,
									quantity,
									receive_date,
									inventory_status_id,
									inv_status,
									serial_number,
									item_master_id
							';
		set @v_vchDynamicSQLCondition = 
							'	WHERE	wh_master_id = @v_vchWarehouseMasterID 
										AND location_id = @v_vchFLocationMasterID
										AND wh_item_master_id = @v_vchWarehouseItemMasterID
										AND ISNULL(parent_lpn,'''') = ISNULL(@in_vchFromParentLPN,'''')
										AND ISNULL(lpn,'''') = ISNULL(@in_vchFromLPN,'''')
										AND ISNULL(lot_number,'''') = ISNULL(@in_vchLot,'''') AND ISNULL(expiry_date,'''') = ISNULL(@in_vchExpiryDate,'''')
							';	

		If (isnull(@in_vchSerialNo,'') = 'ALL')
			Begin--get inventory by all serial
				set @v_vchDynamicSQL += ' FROM	v_wms_inventory_data_by_serial ';
			End
		Else If (@v_vchSerialControl = 'FULL')
			Begin-- get inventory by serial
				set @v_vchDynamicSQL += ' FROM	v_wms_inventory_data_by_serial ';
				set @v_vchDynamicSQLCondition += 
							'
							AND ISNULL(serial_number,'''') = ISNULL(@in_vchSerialNo,'''')
							';
			End
		ELse
			Begin-- get inventory none serial
				set @v_vchDynamicSQL += ' from	v_wms_inventory_data ';
			End
					
		Set @v_vchDynamicSQL = @v_vchDynamicSQL + @v_vchDynamicSQLCondition;
		Set @v_vchDynamicSQL = ' set @v_curInventoryData = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @v_curInventoryData';
		Set @v_vchParameterDefinition = '@v_vchWarehouseMasterID varchar(40),@v_vchWarehouseItemMasterID varchar(40),@v_vchFLocationMasterID varchar(40),
											@in_vchFromParentLPN nvarchar(25),@in_vchFromLPN nvarchar(25),@in_vchLot nvarchar(50),@in_vchExpiryDate nvarchar(50),
											@in_vchSerialNo nvarchar(50),@v_curInventoryData cursor OUTPUT';

		Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@v_vchWarehouseMasterID,@v_vchWarehouseItemMasterID,@v_vchFLocationMasterID,
											@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,
											@in_vchSerialNo,@v_curInventoryData OUTPUT
		Fetch from @v_curInventoryData into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchOwnerCode,@v_fltSStockQuantity,@v_vchReceiveDate,@v_vchToInventoryStatusID,@v_vchInventoryStatus,@v_vchSerialNumber,@v_vchItemMasterID
					
		-- not have inventory data
		If (@v_vchInventoryID is null)
			Begin
				set @out_ErrorCode = '407';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_PACK_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchItem,@in_vchFromLPN,'@param4','@param5')
				--Goto WRITE_PROC;
				RETURN;
			End

		Begin Transaction;

			SET @v_vchBeginTrans = 1;
			
				Begin
					
					While @@FETCH_STATUS = 0
					Begin
							
						SELECT @v_fltBaseQuantity = @v_fltQuantity * conversion_factor 
						FROM t_wms_item_uom 
						WHERE item_master_id = @v_vchItemMasterID and (uom = @in_vchUOMPrompt or uom_prompt = @in_vchUOMPrompt) 
					
						-- Quantity not enough
						If ((@v_fltSStockQuantity < @v_fltBaseQuantity))
							Begin
								set @out_ErrorCode = '408';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchFromLocation,'@param3','@param4','@param5')
								--Goto WRITE_PROC;			
								RETURN;				
							End
						

						-- Manage source LPN data
						update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
						where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
						If (@v_vchSerialControl = 'FULL')
							Begin
								UPDATE	t_wms_inventory_attribute 
								SET		quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round) 
								WHERE	inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID and attribute_value = @v_vchSerialNumber
							End
						Else
							Begin
								UPDATE	t_wms_inventory_attribute 
								SET		quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
								WHERE	inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
							End
						-- manage destination location data
						Begin 
							set @v_vchInventoryID = null;
							set @v_vchAttributeGroupID = null;
							set @v_fltDStockQuantity = 0;
						
							select	@v_vchInventoryID = inventory_id,
									@v_vchAttributeGroupID = attribute_group_id,
									@v_fltDStockQuantity = quantity
							from	v_wms_inventory_data
							where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID 
									and location_id = @v_vchTLocationMasterID
									and isnull(parent_lpn,'') = isnull(@in_vchToParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
									and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull(expiry_date,'') = isnull(@in_vchExpiryDate,'')
									--and isnull(serial_number,'') = isnull(@in_vchSerialNo,'')
							
							exec usp_manage_inventory
									@in_vchApplicationID = @in_vchApplicationID,
									@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
									@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID,
									@in_vchLocationID = @v_vchTLocationMasterID,
									@in_vchLocation = @in_vchFromLocation,
									@in_vchStatusID = @v_vchToInventoryStatusID,
									@in_vchLPN = @in_vchToLPN,
									@in_vchLotNumber = @in_vchLot,
									@in_vchExpiryDate = @in_vchExpiryDate,
									@in_vchSerialNumber = @v_vchSerialNumber,
									@in_fltQty = @v_fltBaseQuantity,
									@in_fltQtyAllocate = 0,
									@in_vchOwner = @v_vchOwnerCode,
									@in_vchInventoryType = @v_vchInventoryType,
									@in_vchPalentLPN = @in_vchToParentLPN,
									@in_vchUserID = @in_vchUserID,
									@in_vchReceiveDate = @v_vchReceiveDate,
									@in_vchInventoryID = @v_vchInventoryID output,
									@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
									@in_vchErrorCode = @out_ErrorCode output,
									@in_vchMessage = @out_ErrorMessage output
							If (@out_ErrorCode <> '0')
								--Goto WRITE_PROC;
							RETURN;
							If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
								Begin
									exec usp_manage_inventory_attribute
											@in_vchApplicationID = @in_vchApplicationID,
											@in_vchItem = @in_vchItem,
											@in_vchSerialNo = @v_vchSerialNumber,
											@in_vchLot = @in_vchLot,
											@in_vchExpiryDate = @in_vchExpiryDate,
											@in_fltQty = @v_fltBaseQuantity,
											@in_fltQtyAllocate = 0,
											@in_vchInventoryID = @v_vchInventoryID,
											@in_vchAttributeGroupID = @v_vchAttributeGroupID,
											@in_vchLotControl = @v_vchLotControl,
											@in_vchSerialNumberControl = @v_vchSerialControl,
											@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
											@in_vchUserID = @in_vchUserID,
											@in_vchErrorCode = @out_ErrorCode output,
											@in_vchMessage = @out_ErrorMessage output			
									If(@out_ErrorCode <> '0')
									RETURN;
										--Goto WRITE_PROC;
								End			
						End
						----- Insert Tralog
						INSERT INTO t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
						start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
						[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
						lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
						reference_number, control_number,parent_lpn,after_parent_lpn, lpn, after_lpn, [status], after_status, zone, order_number, 
						line_number, device, create_by)
						values(@in_vchApplicationID,'OO_PACK','SALES_ORDER',NULL,'Update pack from picking list.',
						GETDATE(),GETDATE(),@in_vchWarehouse,@in_vchWarehouse,@in_vchFromLocation,@in_vchFromLocation,
						@v_vchOwnerCode,@v_vchOwnerCode, @in_vchItem,@v_fltBaseQuantity,@in_vchUOMPrompt,@v_fltSStockQuantity - @v_fltBaseQuantity ,@in_vchUOMPrompt,
						@in_vchLot,@in_vchLot,@in_vchExpiryDate,@in_vchExpiryDate,@v_vchSerialNumber,@in_vchUserID,
						null,null,@in_vchFromParentLPN,@in_vchToParentLPN,@in_vchFromLPN,@in_vchToLPN,@v_vchInventoryStatus,@v_vchInventoryStatus,NULL,@in_vchOrderNumber
						,@v_vchLineNumber,@in_vchDeviceID,@in_vchUserID)
						-- End add inventory not call Inventory Control
					
						BEGIN -- Outbound Processing .Support multiline item and all serial
						DECLARE cursorOutboundPickDetail cursor for
							SELECT
									 outbound_order_detail_id,
									 outbound_pick_master_id,
									 outbound_pick_detail_id,
									 (quantity_stage) - (quantity_Pack),
									 line_number,
									 item_uom_id,
									 uom_prompt
							FROM	v_wms_outbound_Pick_detail
							WHERE	wh_id = @in_vchWarehouse 
									and outbound_order_number = @in_vchOrderNumber 
									and staging_location = @in_vchFromLocation and item_number = @in_vchItem 
									and Isnull(staging_lpn,'') = Isnull(@in_vchFromLPN,'')
									and Isnull(lot_number,'') = Isnull(@in_vchLot,'')
									and Isnull([expiry_date],'') = Isnull(@in_vchExpiryDate,'')
									and quantity_stage - quantity_pack > 0

						OPEN		cursorOutboundPickDetail;
						FETCH FROM cursorOutboundPickDetail INTO @v_vchOutboundOrderDetailID,@v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_fltQuantityRemainPack,@v_vchLineNumber,@v_vchItemUOMID,@in_vchUOMPrompt
						----- Get Qty Packed and Qty STG
						SELECT	@v_fltSumQuantityPack = ISNULL(SUM(quantity_pack),0)
						FROM	t_wms_outbound_pack_detail 
						WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID 
						SELECT	@v_fltSumQuantityOrder = ISNULL(quantity_stage,0)
						FROM	t_wms_outbound_pick_detail 
						WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID 

						Set @v_fltQtyUpdate = @v_fltQuantity;
						While @@FETCH_STATUS = 0
							Begin
								If (@v_fltQtyUpdate > 0)
									Begin
										If (@v_fltQuantityRemainPack > @v_fltQuantity)
											Set @v_fltQtyUpdate = @v_fltQuantity;
										Else 
											Set @v_fltQtyUpdate = @v_fltQuantityRemainPack;

										Set @v_fltQuantity = @v_fltQuantity - @v_fltQtyUpdate;
					
										UPDATE	t_wms_outbound_pick_detail 
										SET		quantity_pack = round(round(@v_fltSumQuantityPack,@Round) + round(@v_fltQtyUpdate,@Round),@Round)
										WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID

										if Exists(
													SELECT		lpn_pack FROM t_wms_outbound_pack_detail 
													WHERE		outbound_order_master_id = @v_vchOutboundOrderMasterID
													AND			pack_location_id = @v_vchTLocationMasterID
													AND			lpn_pack = @in_vchToLPN 
													AND			wh_item_master_id = @v_vchWarehouseItemMasterID 
													AND			outbound_pick_detail_id = @v_vchOutboundPickDetailID
													AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
													)
											Begin
												UPDATE	t_wms_outbound_pack_detail 
												SET		quantity_pack = ROUND(ROUND(quantity_pack,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round)
														,quantity_stage =@v_fltSumQuantityOrder 
												WHERE	outbound_order_master_id = @v_vchOutboundOrderMasterID 
												AND lpn_pack = @in_vchToLPN 
												AND wh_item_master_id = @v_vchWarehouseItemMasterID 
												AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
											End
										Else
											Begin
												INSERT INTO [t_wms_outbound_pack_detail]
											   ([outbound_order_master_id]
											   ,[outbound_pick_detail_id]
											   ,[parent_lpn_pack]
											   ,[lpn_pack]
											   ,[pack_location_id]
											   ,[wh_item_master_id]
											   ,[quantity_pack]
											   ,[lot_number]
											   ,[expiry_date]
											   ,[serial_number]
											   ,[item_uom_id]
											   ,[staging_location_id]
											   ,[staging_parent_lpn]
											   ,[staging_lpn]
											   ,[create_by]
											   ,[quantity_stage])
										 VALUES
												(@v_vchOutboundOrderMasterID
												,@v_vchOutboundPickDetailID
												,@in_vchToParentLPN
												,@in_vchToLPN
												,@v_vchTLocationMasterID
												,@v_vchWarehouseItemMasterID
												,ROUND(@v_fltQtyUpdate,@Round)
												,@in_vchLot
												,@in_vchExpiryDate
												,@v_vchSerialNumber
												,@v_vchItemUOMID
												,@v_vchTLocationMasterID
												,@in_vchFromParentLPN
												,@in_vchFromLPN
												,@in_vchUserID
												,ROUND(@v_fltQtyUpdate,@Round))
											End

										If (@v_fltQuantity = 0)
											Break;

										FETCH FROM cursorOutboundPickDetail into @v_vchOutboundOrderDetailID,@v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_fltQuantityRemainPack,@v_vchLineNumber,@v_vchItemUOMID
									End
							End

							Close cursorOutboundPickDetail;
							Deallocate cursorOutboundPickDetail;
						End

						If (isnull(@in_vchSerialNo,'') = 'ALL')
							set @v_fltQuantity = 1;

						Fetch next from @v_curInventoryData into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchOwnerCode,@v_fltSStockQuantity,@v_vchReceiveDate,@v_vchToInventoryStatusID,@v_vchInventoryStatus,@v_vchSerialNumber
					End

					Close @v_curInventoryData;
					Deallocate @v_curInventoryData;
				End
			

		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		DELETE FROM t_wms_inventory WHERE quantity <= 0 
		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 


		Commit Transaction;
		RETURN;
	
	End Try
	Begin Catch
	
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;

		IF CURSOR_STATUS('global','@v_curInventoryData') >= -1
					Begin
						Close @v_curInventoryData;
						Deallocate @v_curInventoryData;
					End

		IF CURSOR_STATUS('global','cursorOutboundPickDetail') >= -1
			Begin
				Close cursorOutboundPickDetail;
				Deallocate cursorOutboundPickDetail;
			End

		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
			
	End Catch	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_pack_item_pda_new]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_pack_item_pda_new]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchItem				NVARCHAR(50),
	@in_vchOrderNumber		NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vchFromParentLPN	NVARCHAR(25) = null,
	@in_vchFromLPN			NVARCHAR(25) = null,
	@in_vchToParentLPN		NVARCHAR(25) = null,
	@in_vchToLPN			NVARCHAR(25) = null,
	@in_vchLot				NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNo			NVARCHAR(50) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_pack_item_pda]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
    
		@v_vchOutboundOrderMasterID	VARCHAR(40),
		@v_vchOutboundOrderDetailID	VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	NVARCHAR(40),
		@v_vchOutboundPackDetailID	NVARCHAR(40),
		@v_vchWarehouseMasterID		NVARCHAR(40),
		@v_vchWarehouseItemMasterID	VARCHAR(40),
		@v_vchFLocationMasterID		NVARCHAR(40),
		@v_vchTLocationMasterID		NVARCHAR(40),
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchLineNumber			NVARCHAR(10),
		@v_vhcUOMID					VARCHAR(40),
		@v_vchItemUOMID				VARCHAR(40),
		@Round						INT,
		@v_fltQuantity				FLOAT,
		@v_fltQuantityRemainPack	FLOAT,
		@v_vchOrderStatus			NVARCHAR(10),
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchMixItem				NVARCHAR(3),
		@v_vchMixLot				NVARCHAR(3),
		@v_vchMixOwner				NVARCHAR(3),
		@v_vchMixExpiryDate			NVARCHAR(3),
		@v_vchLPNControl			NVARCHAR(5),
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_fltSStockQuantity		FLOAT = 0,
		@v_fltDStockQuantity		FLOAT = 0,
		@v_fltBaseQuantity			FLOAT,
		@v_vchInventoryType			NVARCHAR(25),
		@v_vchDubLocation			NVARCHAR(50),
		@v_vchDubParentLPN			NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchOverride				NVARCHAR(3),
		-- Add new 2013-11-06 outbound multiline
		@v_vchAllowMulltiLineItem	NVARCHAR(3) = 'NO',
		@v_fltQtyUpdate				FLOAT = 0,
		@v_fltSumQuantityOrder		FLOAT,
		@v_fltSumQuantityPack		FLOAT,
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(MAX) = '',
		@v_vchDynamicSQLCondition	NVARCHAR(MAX) = '',
		@v_vchSerialNumber			NVARCHAR(50),
		@v_vchReceiveDate			DATE,
		@cursorOutboundPickDetail	CURSOR,
		@v_curInventoryData			CURSOR
   
	set @out_ErrorCode = '0';
	set @out_ErrorMessage = 'NO';
	select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'

	Begin Try
		
		SET @in_fltQty = round(@in_fltQty,@Round)
		SELECT @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_name = @in_vchWarehouse
		SELECT @v_vchFLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchFromLocation
		SELECT @v_vchOutboundOrderMasterID = outbound_order_master_id,@v_vchOrderStatus = order_status,@v_vchOwnerID = owner_id from t_wms_outbound_master where outbound_order_number = @in_vchOrderNumber

		-- Check item from t_wms_item, 885 and crossref	
		select	@in_vchItem = item_number,@v_vchItemMasterID = it.item_master_id,@v_vhcUOMID = iu.item_uom_id,
				@v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control
		from	t_wms_item it left outer join t_wms_item_crossref ic on it.item_master_id = ic.item_master_id
				left outer join t_wms_item_uom iu on it.item_master_id = iu.item_master_id 
		where	uom_prompt = @in_vchUOMPrompt and (item_number = @in_vchItem or dg_code = @in_vchItem 
				or alternate_item_number = @in_vchItem)
		If (isnull(@v_vchItemMasterID,'') = '')
			Begin
				set @out_ErrorCode = '403';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
			
		-- Get Warehouse item id	
		select @v_vchWarehouseItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID
		


		Begin Transaction;
		SET @v_vchBeginTrans = 1;
		-- Outbound Processing .Support multiline item and all serial
		BEGIN 
		--DECLARE @cursorOutboundPickDetail cursor for
		SET @v_vchDynamicSQL ='SELECT 
									pickDt.outbound_order_detail_id,
									pickDt.outbound_pick_detail_id,
									SUM(pickDt.quantity_stage)  -	SUM(pickDt.quantity_pack) AS QuantityRemainPack,
									pickDt.pick_line_number,
									item_uom_id,
									serial_number
								From t_wms_outbound_pick_detail AS pickDt
								INNER JOIN (select outbound_pick_master_id,outbound_order_number 
											from t_wms_outbound_pick_master
											where outbound_order_number = @in_vchOrderNumber
											) AS pickMs
							ON pickDt.outbound_pick_master_id = pickMs.outbound_pick_master_id
							INNER JOIN (SELECT outbound_order_detail_id, item_uom_id from t_wms_outbound_detail
										)AS outDt 
							ON pickDt.outbound_order_detail_id = outDt.outbound_order_detail_id
							';
		SET @v_vchDynamicSQLCondition +='
							WHERE staging_location_id = @v_vchFLocationMasterID
							AND  wh_item_master_id = @v_vchWarehouseItemMasterID
							AND ISNULL(staging_parent_lpn,'''') = ISNULL(@in_vchFromParentLPN,'''')
							AND ISNULL(staging_lpn,'''') = ISNULL(@in_vchFromLPN,'''')
							AND ISNULL (lot_number,'''') = ISNULL (@in_vchLot,'''')
							AND ISNULL (expiry_date,'''') = ISNULL(@in_vchExpiryDate,'''')
							AND pickDt.quantity_stage  >	pickDt.quantity_pack
												';
		If	@v_vchSerialControl ='FULL'
		BEGIN
			IF ISNULL(@in_vchSerialNo,'') <> 'ALL'
			BEGIN
					set @v_vchDynamicSQLCondition += '	AND ISNULL (serial_number,'''') = ISNULL(@in_vchSerialNo,'''')';
			END
		END
		SET @v_vchDynamicSQLCondition += '	GROUP BY pickDt.outbound_pick_master_id,pickDt.outbound_pick_detail_id,pickDt.outbound_order_detail_id,pick_line_number,item_uom_id,serial_number'

		SET @v_vchDynamicSQL = @v_vchDynamicSQL + @v_vchDynamicSQLCondition;
		SET @v_vchDynamicSQL = ' SET @cursorOutboundPickDetail = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @cursorOutboundPickDetail';
		SET @v_vchParameterDefinition = '@in_vchOrderNumber nvarchar(25),@v_vchFLocationMasterID varchar(40),@v_vchWarehouseItemMasterID varchar(40),
											@in_vchFromParentLPN nvarchar(25),@in_vchFromLPN nvarchar(25),@in_vchLot nvarchar(50),@in_vchExpiryDate nvarchar(50),
											@in_vchSerialNo nvarchar(50),@cursorOutboundPickDetail cursor OUTPUT';

		Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@in_vchOrderNumber,@v_vchFLocationMasterID,@v_vchWarehouseItemMasterID,
									@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,
									@in_vchSerialNo,@cursorOutboundPickDetail OUTPUT
		FETCH FROM @cursorOutboundPickDetail INTO 
										@v_vchOutboundOrderDetailID,
										@v_vchOutboundPickDetailID,
										@v_fltQuantityRemainPack,
										@v_vchLineNumber,
										@v_vchItemUOMID,
										@v_vchSerialNumber
		While @@FETCH_STATUS = 0
			Begin
			IF @in_vchSerialNo = 'ALL'
			BEGIN
				
				SET @in_fltQty = 1
			END 
			SET @v_vchTLocationMasterID = @v_vchFLocationMasterID
			If (@v_vhcUOMID <> @v_vchItemUOMID)
				Begin
					select @v_fltQuantity = @in_fltQty * conversion_factor from t_wms_item_uom where item_uom_id = @v_vhcUOMID
					select @v_fltQuantity = @v_fltQuantity / conversion_factor from t_wms_item_uom where item_uom_id = @v_vchItemUOMID
				End
			Else
				Begin
					set @v_fltQuantity = @in_fltQty;
				End

			If (@v_fltQuantityRemainPack < @v_fltQuantity)
			BEGIN
					SET		@out_ErrorCode = '408';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'INFO-QTY-MORE-THAN-QTY-PLAN',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchFromLocation,'@param3','@param4','@param5')		
					GOTO WRITE_PROC;
			END

			Set @v_fltQtyUpdate = @v_fltQuantity;
			If (@v_fltQtyUpdate > 0)

				SELECT	@v_fltSumQuantityPack = ISNULL(SUM(quantity_pack),0)
				FROM	t_wms_outbound_pack_detail 
				WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID 
				SELECT	@v_fltSumQuantityOrder = ISNULL(quantity_stage,0)
				FROM	t_wms_outbound_pick_detail 
				WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID 
				Begin
					If (@v_fltQuantityRemainPack > @v_fltQuantity)
						Set @v_fltQtyUpdate = @v_fltQuantity;
					Else 
						Set @v_fltQtyUpdate = @v_fltQuantityRemainPack;

					Set @v_fltQuantity = @v_fltQuantity - @v_fltQtyUpdate;
					
					UPDATE	t_wms_outbound_pick_detail 
					SET		quantity_pack = round(round(@v_fltSumQuantityPack,@Round) + round(@v_fltQtyUpdate,@Round),@Round)
					WHERE	outbound_pick_detail_id = @v_vchOutboundPickDetailID

					if Exists(
								SELECT		lpn_pack FROM t_wms_outbound_pack_detail 
								WHERE		outbound_order_master_id = @v_vchOutboundOrderMasterID
								AND			pack_location_id = @v_vchTLocationMasterID
								AND			ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
								AND			staging_lpn = @in_vchToLPN 
								AND			wh_item_master_id = @v_vchWarehouseItemMasterID 
								AND			outbound_pick_detail_id = @v_vchOutboundPickDetailID
								AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
							)
						Begin
							UPDATE	t_wms_outbound_pack_detail 
							SET		quantity_pack = ROUND(ROUND(quantity_pack,@Round) + ROUND(@v_fltQtyUpdate,@Round),@Round)
									,quantity_stage =@v_fltSumQuantityOrder 
							WHERE	outbound_order_master_id = @v_vchOutboundOrderMasterID 
							AND lpn_pack = @in_vchToLPN 
							AND wh_item_master_id = @v_vchWarehouseItemMasterID 
							AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
						End
					Else
						Begin
							INSERT INTO [t_wms_outbound_pack_detail]
							([outbound_order_master_id]
							,[outbound_pick_detail_id]
							,[parent_lpn_pack]
							,[lpn_pack]
							,[pack_location_id]
							,[wh_item_master_id]
							,[quantity_pack]
							,[lot_number]
							,[expiry_date]
							,[serial_number]
							,[item_uom_id]
							,[staging_location_id]
							,[staging_parent_lpn]
							,[staging_lpn]
							,[create_by]
							,[quantity_stage])
						VALUES
							(@v_vchOutboundOrderMasterID
							,@v_vchOutboundPickDetailID
							,@in_vchToParentLPN
							,@in_vchToLPN
							,@v_vchFLocationMasterID
							,@v_vchWarehouseItemMasterID
							,ROUND(@v_fltQtyUpdate,@Round)
							,@in_vchLot
							,@in_vchExpiryDate
							,@v_vchSerialNumber
							,@v_vchItemUOMID
							,@v_vchFLocationMasterID
							,@in_vchToParentLPN
							,@in_vchToLPN
							,@in_vchUserID
							,ROUND(@v_fltQtyUpdate,@Round))
						End

					----------------------- Begin Inventory---------------------------------------------------------------------
										
						set @v_vchDynamicSQL =
											'
											SELECT	inventory_id,
													attribute_group_id,
													owner_code,
													quantity,
													receive_date,
													inventory_status_id,
													inv_status,
													serial_number,
													item_master_id,
													inv_type
											';
						set @v_vchDynamicSQLCondition = 
											'	WHERE	wh_master_id = @v_vchWarehouseMasterID 
														AND location_id = @v_vchFLocationMasterID
														AND wh_item_master_id = @v_vchWarehouseItemMasterID
														AND ISNULL(parent_lpn,'''') = ISNULL(@in_vchFromParentLPN,'''')
														AND ISNULL(lpn,'''') = ISNULL(@in_vchFromLPN,'''')
														AND ISNULL(lot_number,'''') = ISNULL(@in_vchLot,'''') AND ISNULL(expiry_date,'''') = ISNULL(@in_vchExpiryDate,'''')
											';	

						--If (isnull(@in_vchSerialNo,'') = 'ALL')
						--	Begin--get inventory by all serial
						--		set @v_vchDynamicSQL += ' FROM	v_wms_inventory_data_by_serial ';
						--	End
						If (@v_vchSerialControl = 'FULL')
							Begin-- get inventory by serial
								set @v_vchDynamicSQL += ' FROM	v_wms_inventory_data_by_serial ';
								set @v_vchDynamicSQLCondition += 
											'
											AND ISNULL(serial_number,'''') = ISNULL(@v_vchSerialNumber,'''')
											';
							End
						ELse
							Begin-- get inventory none serial
								set @v_vchDynamicSQL += ' from	v_wms_inventory_data ';
							End
					
						Set @v_vchDynamicSQL = @v_vchDynamicSQL + @v_vchDynamicSQLCondition;
						Set @v_vchDynamicSQL = ' set @v_curInventoryData = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @v_curInventoryData';
						Set @v_vchParameterDefinition = '@v_vchWarehouseMasterID varchar(40),@v_vchWarehouseItemMasterID varchar(40),@v_vchFLocationMasterID varchar(40),
															@in_vchFromParentLPN nvarchar(25),@in_vchFromLPN nvarchar(25),@in_vchLot nvarchar(50),@in_vchExpiryDate nvarchar(50),
															@v_vchSerialNumber nvarchar(50),@v_curInventoryData cursor OUTPUT';

						Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@v_vchWarehouseMasterID,@v_vchWarehouseItemMasterID,@v_vchFLocationMasterID,
															@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,
															@v_vchSerialNumber,@v_curInventoryData OUTPUT
						FETCH FROM @v_curInventoryData into @v_vchInventoryID,
															@v_vchAttributeGroupID,
															@v_vchOwnerCode,
															@v_fltSStockQuantity,
															@v_vchReceiveDate,
															@v_vchToInventoryStatusID,
															@v_vchInventoryStatus,
															@v_vchSerialNumber,
															@v_vchItemMasterID,
															@v_vchInventoryType
					
						-- not have inventory data
						If (@v_vchInventoryID is null)
							Begin
								set @out_ErrorCode = '407';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_PACK_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchItem,@in_vchFromLPN,'@param4','@param5')
								Goto WRITE_PROC;
							End

								Begin
					
									While @@FETCH_STATUS = 0
									Begin
							
										SELECT @v_fltBaseQuantity = @v_fltQtyUpdate -- @v_fltQuantity * conversion_factor 
										FROM T_wms_item_uom 
										WHERE item_master_id = @v_vchItemMasterID and (uom = @in_vchUOMPrompt or uom_prompt = @in_vchUOMPrompt) 
					
										-- Quantity not enough
										If ((@v_fltSStockQuantity < @v_fltBaseQuantity))
											Begin
												set @out_ErrorCode = '408';
												select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchFromLocation,'@param3','@param4','@param5')
												Goto WRITE_PROC;			
																
											End
						

										-- Manage source LPN data
										update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
										where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
										If (@v_vchSerialControl = 'FULL')
											Begin
												UPDATE	t_wms_inventory_attribute 
												SET		quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round) 
												WHERE	inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID and attribute_value = @v_vchSerialNumber
											End
										Else
											Begin
												UPDATE	t_wms_inventory_attribute 
												SET		quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
												WHERE	inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
											End
										-- manage destination location data
										Begin 
											set @v_vchInventoryID = null;
											set @v_vchAttributeGroupID = null;
											set @v_fltDStockQuantity = 0;
						
											select	@v_vchInventoryID = inventory_id,
													@v_vchAttributeGroupID = attribute_group_id,
													@v_fltDStockQuantity = quantity
											from	v_wms_inventory_data
											where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID 
													and location_id = @v_vchTLocationMasterID
													and isnull(parent_lpn,'') = isnull(@in_vchToParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
													and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull(expiry_date,'') = isnull(@in_vchExpiryDate,'')
													--and isnull(serial_number,'') = isnull(@in_vchSerialNo,'')
							
											exec usp_manage_inventory
													@in_vchApplicationID = @in_vchApplicationID,
													@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
													@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID,
													@in_vchLocationID = @v_vchTLocationMasterID,
													@in_vchLocation = @in_vchFromLocation,
													@in_vchStatusID = @v_vchToInventoryStatusID,
													@in_vchLPN = @in_vchToLPN,
													@in_vchLotNumber = @in_vchLot,
													@in_vchExpiryDate = @in_vchExpiryDate,
													@in_vchSerialNumber = @v_vchSerialNumber,
													@in_fltQty = @v_fltBaseQuantity,
													@in_fltQtyAllocate = 0,
													@in_vchOwner = @v_vchOwnerCode,
													@in_vchInventoryType = @v_vchInventoryType,
													@in_vchPalentLPN = @in_vchToParentLPN,
													@in_vchUserID = @in_vchUserID,
													@in_vchReceiveDate = @v_vchReceiveDate,
													@in_vchInventoryID = @v_vchInventoryID output,
													@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
													@in_vchErrorCode = @out_ErrorCode output,
													@in_vchMessage = @out_ErrorMessage output
											If (@out_ErrorCode <> '0')
											Goto WRITE_PROC;
											If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
												Begin
													exec usp_manage_inventory_attribute
															@in_vchApplicationID = @in_vchApplicationID,
															@in_vchItem = @in_vchItem,
															@in_vchSerialNo = @v_vchSerialNumber,
															@in_vchLot = @in_vchLot,
															@in_vchExpiryDate = @in_vchExpiryDate,
															@in_fltQty = @v_fltBaseQuantity,
															@in_fltQtyAllocate = 0,
															@in_vchInventoryID = @v_vchInventoryID,
															@in_vchAttributeGroupID = @v_vchAttributeGroupID,
															@in_vchLotControl = @v_vchLotControl,
															@in_vchSerialNumberControl = @v_vchSerialControl,
															@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
															@in_vchUserID = @in_vchUserID,
															@in_vchErrorCode = @out_ErrorCode output,
															@in_vchMessage = @out_ErrorMessage output			
													If(@out_ErrorCode <> '0')
														Goto WRITE_PROC;
												End			
										End
										----- Insert Tralog
										INSERT INTO t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
										start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
										[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
										lot_number, after_lot_number, 
										[expiry_date], after_expiry_date, serial_number, [user_id], 
										reference_number, control_number,parent_lpn,after_parent_lpn, lpn, after_lpn, [status], after_status, zone, order_number, 
										line_number, device, create_by)
										values(@in_vchApplicationID,'OO_PACK','PACK_DETAIL',NULL,'Update pack from picking list.',
										GETDATE(),GETDATE(),@in_vchWarehouse,@in_vchWarehouse,@in_vchFromLocation,@in_vchFromLocation,
										@v_vchOwnerCode,@v_vchOwnerCode, @in_vchItem,@v_fltBaseQuantity,@in_vchUOMPrompt,@v_fltSStockQuantity - @v_fltBaseQuantity ,@in_vchUOMPrompt,
										@in_vchLot,@in_vchLot,CASE @in_vchExpiryDate WHEN '' THEN NULL ELSE @in_vchExpiryDate END ,CASE @in_vchExpiryDate WHEN '' THEN NULL ELSE @in_vchExpiryDate END,@v_vchSerialNumber,@in_vchUserID,
										null,null,@in_vchFromParentLPN,@in_vchToParentLPN,@in_vchFromLPN,@in_vchToLPN,@v_vchInventoryStatus,@v_vchInventoryStatus,NULL,@in_vchOrderNumber
										,@v_vchLineNumber,@in_vchDeviceID,@in_vchUserID)
										-- End add inventory not call Inventory Control
					

										--If (isnull(@in_vchSerialNo,'') = 'ALL')
										--	set @v_fltQuantity = 1;

										FETCH NEXT from @v_curInventoryData into 
																				@v_vchInventoryID,
																				@v_vchAttributeGroupID,
																				@v_vchOwnerCode,
																				@v_fltSStockQuantity,
																				@v_vchReceiveDate,
																				@v_vchToInventoryStatusID,
																				@v_vchInventoryStatus,
																				@v_vchSerialNumber,
																				@v_vchItemMasterID,
																				@v_vchInventoryType
									End

									Close @v_curInventoryData;
									Deallocate @v_curInventoryData;
								End
			

					-----------------------End Inventory--------------
					FETCH NEXT FROM @cursorOutboundPickDetail into 
															@v_vchOutboundOrderDetailID,
															@v_vchOutboundPickDetailID,
															@v_fltQuantityRemainPack,
															@v_vchLineNumber,
															@v_vchItemUOMID,
															@v_vchSerialNumber
				End
			End

			Close @cursorOutboundPickDetail;
			Deallocate @cursorOutboundPickDetail;
		End


		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		DELETE FROM t_wms_inventory WHERE quantity <= 0 
		DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 


		Commit Transaction;
		RETURN;
	
	
		-----------------------------------------------------------------------------------
		--							Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;

		IF CURSOR_STATUS('global','@v_curInventoryData') >= -1
					Begin
						Close @v_curInventoryData;
						Deallocate @v_curInventoryData;
					End

		IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
			Begin
				Close @cursorOutboundPickDetail;
				Deallocate @cursorOutboundPickDetail;
			End

		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
		End	
	End Try
	Begin Catch
	
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;

		IF CURSOR_STATUS('global','@v_curInventoryData') >= -1
					Begin
						Close @v_curInventoryData;
						Deallocate @v_curInventoryData;
					End

		IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
			Begin
				Close @cursorOutboundPickDetail;
				Deallocate @cursorOutboundPickDetail;
			End

		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
			
	End Catch	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_pack_scan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-05-21
-- Description:	Check stock quantity
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_pack_scan]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchOrderNumber		NVARCHAR(50),
	@in_vchLPNPack			NVARCHAR(25),
	@in_vchItemNumber		NVARCHAR(50),
	@in_vchPackLocation		NVARCHAR(50),
	@in_fltQuantity			FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vchLot				NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNo			NVARCHAR(50) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE
	@v_vchApplicationName		NVARCHAR(100),
	@v_vchOutboundOrderMasterID	NVARCHAR(40),
	@v_vchOutboundPickMasterID	NVARCHAR(40),
	@v_vchOutboundPickDetailID	NVARCHAR(40),
	@v_vchWarehouseMasterID		NVARCHAR(40),
	@v_vchItemMasterID			NVARCHAR(40),
	@v_vchWHItemMasterID		NVARCHAR(40),
	@v_vchLocationID			NVARCHAR(40),
	@v_vchUOMID					NVARCHAR(40),
	@v_dtProcessDateTime		DATETIME,
	@c_vchObjName				NVARCHAR(20),
	@v_vchData1					NVARCHAR(1000),
	@v_vchData2					NVARCHAR(1000),
	@v_fltStageQuantity			FLOAT,
	@v_fltPackQuantity			FLOAT,
	@v_fltUpdateQuantity		FLOAT,
	@v_fltUOMConFactor			FLOAT,
	@Round						INT
	
	Begin Try
	
		set @c_vchObjName = '[usp_outbound_pack_scan]';
		select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'
		
		select @v_vchApplicationName = application_name from t_com_application where app_id = @in_vchApplicationID
		select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		select @v_vchItemMasterID = item_master_id from t_wms_item where item_number = @in_vchItemNumber
		select @v_vchWHItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID
		select @v_vchLocationID = location_id  from t_wms_location where location = @in_vchPackLocation
		select @v_vchUOMID = item_uom_id from t_wms_item_uom where uom_prompt = @in_vchUOMPrompt
		select @v_vchOutboundOrderMasterID = outbound_order_master_id from t_wms_outbound_master where outbound_order_number = @in_vchOrderNumber

-----------------------------------------------------------------------------------
--							   Check item uom
-----------------------------------------------------------------------------------

		select	@v_fltUOMConFactor = conversion_factor
		from t_wms_item_uom 
		where item_master_id = @v_vchItemMasterID and uom_prompt = @in_vchUOMPrompt
		 
		If (Isnull(@v_fltUOMConFactor,'') = '')
			Begin
				SET @out_ErrorCode = '908';
				--SET @out_ErrorMessage = 'UOM [' + isnull(@in_vchUOMPrompt,'uom is null') + '] not found!';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
				return;
			End
		Else
			Begin
				set @in_fltQuantity = @in_fltQuantity * @v_fltUOMConFactor;
			End
					
		Begin Transaction
			select @v_vchOutboundPickMasterID = outbound_pick_master_id from t_wms_outbound_pick_master where outbound_order_master_id = @v_vchOutboundOrderMasterID
			
			If ((select sum(quantity_stage - quantity_pack) from t_wms_outbound_pick_detail 
			where wh_item_master_id = @v_vchWHItemMasterID and outbound_pick_master_id = @v_vchOutboundPickMasterID) < @in_fltQuantity)
				Begin
					close cursorOutboundPickDetail;
					deallocate cursorOutboundPickDetail;
					set @out_ErrorCode = '999';
					--set @out_ErrorMessage = 'Quantity Pack must less than Quantity Staging.Please check data again.';
					select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QTY_PACK_MUST_LESS_THAN_QTY_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					Rollback Transaction;
					return;
				End
				
			insert into t_wms_outbound_pack_detail(outbound_order_master_id, lpn_pack, pack_location_id, wh_item_master_id, quantity_pack, lot_number, [expiry_date], serial_number, item_uom_id, create_by)
			values(@v_vchOutboundOrderMasterID,@in_vchLPNPack,@v_vchLocationID,@v_vchWHItemMasterID,@in_fltQuantity,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo,@v_vchUOMID,@in_vchUserID)
			
			declare cursorOutboundPickDetail cursor for
				select outbound_pick_detail_id from t_wms_outbound_pick_detail 
				where wh_item_master_id = @v_vchWHItemMasterID and outbound_pick_master_id = @v_vchOutboundPickMasterID
			--and isnull(lpn,'') = isnull(@in_vchLPNPack,'') and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull([expiry_date],'') = isnull(@in_vchExpiryDate,'') and isnull(serial_number,'') = isnull(@in_vchSerialNo,'')
			
			open cursorOutboundPickDetail;
			Fetch from cursorOutboundPickDetail into @v_vchOutboundPickDetailID;
			
			While @@FETCH_STATUS = 0
				Begin
					If (@in_fltQuantity = 0)
						Begin
							GOTO COMMIT_TRANS;
						End
					If (ISNULL(@v_vchOutboundPickDetailID,'') <> '')
						Begin
							select @v_fltStageQuantity = quantity_stage,@v_fltPackQuantity = quantity_pack from t_wms_outbound_pick_detail where outbound_pick_detail_id = @v_vchOutboundPickDetailID
							If(@v_fltPackQuantity + @in_fltQuantity > (@v_fltStageQuantity - @v_fltPackQuantity))
								Begin
									set @v_fltUpdateQuantity = @v_fltStageQuantity - @v_fltPackQuantity;
									set @in_fltQuantity = @in_fltQuantity - (@v_fltStageQuantity - @v_fltPackQuantity);
								End
							Else
								Begin
									set @v_fltUpdateQuantity = @in_fltQuantity;
									set @in_fltQuantity = 0;
								End
							
							update t_wms_outbound_pick_detail set quantity_pack = round(round(quantity_pack,@Round) + round(@v_fltUpdateQuantity,@Round),@Round)
							where outbound_pick_detail_id = @v_vchOutboundPickDetailID
							
							update t_wms_outbound_master set order_status = 'PACK'
							where  outbound_order_master_id = @v_vchOutboundOrderMasterID 
									
						End
					Else
						Begin
							close cursorOutboundPickDetail;
							deallocate cursorOutboundPickDetail;
							set @out_ErrorCode = '999';
							--set @out_ErrorMessage = 'Data pick detail not found!';
							select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'DATA_PICK_DETAIL_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
							Rollback Transaction;
							return;
						End
						
					Fetch next from cursorOutboundPickDetail into @v_vchOutboundPickDetailID;
				End
		
		COMMIT_TRANS:		
		close cursorOutboundPickDetail;
		deallocate cursorOutboundPickDetail;		
		set @v_dtProcessDateTime = GETDATE();	
		set @out_ErrorCode = '0';
		--set @out_ErrorMessage = 'SAVE SUCCESS';
		select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			
		exec usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchAppName = @v_vchApplicationName,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'TRANSACTION',
		@in_vchTranType = 'OO_PACK',
		@in_vchSubTranType = NULL,
		@in_vchProcess = 'Pack',
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_dtStartTranDate = @v_dtProcessDateTime,
		@in_vchLPN = @in_vchLPNPack,
		@in_vchItemNumber = @in_vchItemNumber,
		@in_vchLotNumber = @in_vchLot,
		@in_dtExpiryDate = @in_vchExpiryDate,
		@in_vchSerialNumber	= @in_vchSerialNo,
		@in_vchToLocation = @in_vchPackLocation,
		@in_fltQuantity = @in_fltQuantity,
		@in_fltAfterQuantity = null,
		@in_vchReferenceNumber = null,
		@in_vchUOM = @in_vchUOMPrompt,
		@in_vchAfterUOM = @in_vchUOMPrompt,
		@in_vchData1 = 'Pack.',
		@in_vchData2 = null,
		@in_vchData3 = null,
		@in_vchData4 = null,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
		
		Commit Transaction
	End Try
	Begin Catch
		close cursorOutboundPickDetail;
		deallocate cursorOutboundPickDetail;	
		Rollback Transaction;
		set @out_ErrorCode = @out_ErrorCode + '-' + ERROR_NUMBER();
		set @out_ErrorMessage = substring(@out_ErrorMessage + ERROR_MESSAGE(),0,100);
		
		SET @v_vchData1 = ERROR_PROCEDURE() + ': ' + @out_ErrorMessage 
					+ '. SQL Error ['+ str(ERROR_NUMBER()) + '], '
					+ '. Severity ['+ str(ERROR_SEVERITY()) + '],'
					+ '. State ['+ str(ERROR_STATE()) + '],'
					+ '. Line ['+ str(ERROR_LINE()) + '].'
							
		SET @v_dtProcessDateTime = getdate();
		set @v_vchData2 = 'Order number [' + @in_vchOrderNumber + ']';
		
		exec usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	End Catch
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_partial_ship_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 /*
	2022-07-15 : กำหนดให้เมื่อ auto สร้าง inbound order กำหนดให้ reference number (ibMS) = outbound order number (obMS)
*/
CREATE PROCEDURE [dbo].[usp_outbound_partial_ship_confirm]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(25),   
	@out_ErrorCode			NVARCHAR(200) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
    --Partial Ship ไม่ต้อง unallocate
	DECLARE
		-- Error handling variables
		@c_vchObjName			NVARCHAR(50) = '[usp_outbound_partial_ship_confirm]', -- The name that uniquely tags this object.
		@v_vchApplicationName	NVARCHAR(100),
		@v_dtProcessDateTime	DATETIME,
		@v_dtStartTranDate		DATETIME,
		@v_dtEndTranDate		DATETIME,
		@v_vchBeginTrans		BIT = 0,
		@Round					INT,
		@RulePickPack			VARCHAR(3)= 'NO',
		@RulePOD				VARCHAR(3)= 'NO',
		@RuleIsBorrow			VARCHAR(3)= 'NO',
		@v_intDueDate			INT,

		--Interface
		@v_vchHostInterfaceID	NVARCHAR(50),
		@v_dtShipDateActual		DATETIME,

		@v_vchWhMasterID		UNIQUEIDENTIFIER, 
		@v_vchWarehouse			NVARCHAR(25),

		--Outbound
		@v_vchOutboundOrderNumber NVARCHAR(50),
		@v_vchOwnerID			UNIQUEIDENTIFIER,
		@v_vchOwnerCode			NVARCHAR(50),
		@v_vchOrderType			NVARCHAR(30),
		@v_vchOrderStatus		NVARCHAR(10),
		@v_vchCustomerID		UNIQUEIDENTIFIER,
		@v_vchCustomerCode		NVARCHAR(50),
		@v_vchCustomerName		NVARCHAR(300),
		@v_vchShipToCode		NVARCHAR(40)	= NULL,  
		@v_vchShipToName		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr1		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr2		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr3		NVARCHAR(300)	= NULL,  
		@v_vchShipToCity		NVARCHAR(50)	= NULL,  
		@v_vchShipToProvince	NVARCHAR(50)	= NULL,  
		@v_vchShipToPostalCode	NVARCHAR(50)	= NULL,  
		@v_vchShipToCountry		NVARCHAR(5)		= NULL,  
		@v_vchShipToCountryName NVARCHAR(50)	= NULL,  
		@v_vchShipToContactName NVARCHAR(50)	= NULL,  
		@v_vchShipToPhoneNumber NVARCHAR(50)	= NULL,  
		@v_vchBillToCode		NVARCHAR(40)	= NULL,  
		@v_vchBillToName		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr1		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr2		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr3		NVARCHAR(300)	= NULL,  
		@v_vchBillToCity		NVARCHAR(50)	= NULL,  
		@v_vchBillToProvince	NVARCHAR(50)	= NULL,  
		@v_vchBillToPostalCode	NVARCHAR(50)	= NULL,  
		@v_vchBillToCountry		NVARCHAR(5)		= NULL,  
		@v_vchBillToCountryName NVARCHAR(50)	= NULL,  
		@v_vchBillToContactName NVARCHAR(50)	= NULL,  
		@v_vchBillToPhoneNumber	NVARCHAR(50)	= NULL,
		@v_vchTrackingNo		NVARCHAR(50)	= NULL,
		@v_vchToWarehouseID		NVARCHAR(50)	= NULL,
		@v_vchCustomerOrderNumber NVARCHAR(50)	= NULL,
		@v_vchLoadID			NVARCHAR(50)	= NULL,
		@v_dtDeliveryDatePlan	DATETIME,
		@v_dtShipDatePlan		DATETIME = NULL,
		@v_vchPickType			NVARCHAR(15),
		@v_vchHUDF1				NVARCHAR(255),
		@v_vchHUDF2				NVARCHAR(255),
		@v_vchHUDF3				NVARCHAR(255),
		@v_vchHUDF4				NVARCHAR(255),
		@v_vchHUDF5				NVARCHAR(255),
		@v_vchHUDF6				NVARCHAR(255),
		@v_fltHUDF7				FLOAT,
		@v_fltHUDF8				FLOAT,
		@v_dtpHUDF9				DATETIME,
		@v_dtpHUDF10			DATETIME,

		@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundBorrowMasterID UNIQUEIDENTIFIER = NULL,

		--Cursor Loop
		@v_vchOutboundOrderDetailID UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundPackDetailID	UNIQUEIDENTIFIER = NULL,
		@v_vchLineNumber			NVARCHAR(10),  
		@v_vchLocationMasterID		UNIQUEIDENTIFIER,  
		@v_vchLocationForPick		NVARCHAR(50) = NULL,
		@v_vchERPLocationForPick	NVARCHAR(50) = NULL,
		@v_vchZone					NVARCHAR(50) = NULL,
		@v_vchLPN					NVARCHAR(25),  
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
		@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL, 
		@v_vchItemNumber			NVARCHAR(50),  
		@v_vchDefaultItemStatus		NVARCHAR(50)	= NULL,
		@v_fltQuantityOrder			FLOAT,
		@v_fltQuantityShip			FLOAT,
		@v_vchItemUOMID				UNIQUEIDENTIFIER = NULL, 
		@v_vchUOM					NVARCHAR(20),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(50),  
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchLotControl			VARCHAR(5),
		@v_vchExpiryDateControl		VARCHAR(5),
		@v_vchSerialControl			VARCHAR(5),
		@v_vchAttribute1Control		VARCHAR(5),
		@v_vchAttribute2Control		VARCHAR(5),
		@v_vchAttribute3Control		VARCHAR(5),
		@v_vchAttribute4Control		VARCHAR(5),
		@v_vchAttribute5Control		VARCHAR(5),
		@v_dtReceiveDate			DATE,
		
		--Calculate Volumn & Weight
		@v_fltWidth					FLOAT = 0,
		@v_fltLength				FLOAT = 0,
		@v_fltHeight				FLOAT = 0,
		@v_fltGrossWeight			FLOAT = 0,
		@v_intPercentTolerance		FLOAT = 0,
		@v_intPercenToleranceWeight FLOAT = 0,
		@v_fltVolumn				FLOAT = 0,	--item
		@v_fltTotalWeight			FLOAT = 0,	--item

		--Customer for POD
		@v_vchRouteCode			NVARCHAR(50),
		@v_vchRouteName			NVARCHAR(255),
		@v_vchCustUdf1			NVARCHAR(50),
		
		@v_vchTranType			NVARCHAR(50),
		@v_vchSubTranType		NVARCHAR(20)= NULL,
		@v_vchMoveSubTranType	NVARCHAR(20)= NULL, 
		@v_vchMoveToLocationID	UNIQUEIDENTIFIER = NULL,
		@v_vchMoveToLocation	NVARCHAR(50) = NULL,
		@v_vchMoveToInvStatusID	UNIQUEIDENTIFIER = NULL,
		@v_vchMoveToInvStatus	NVARCHAR(50) = NULL

	BEGIN TRY
		SET @v_dtStartTranDate = GETDATE();
		SET @v_dtShipDateActual = GETDATE()
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
		SELECT TOP 1 @RulePOD = value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_POD' AND is_active = 'YES'
   
		--Get Outbound
		SELECT TOP 1 @v_vchOutboundOrderNumber = obMS.outbound_order_number
			, @v_vchWhMasterID			= obMS.wh_master_id
			, @v_vchWarehouse			= obMS.wh_id
			, @v_vchOrderType			= obMS.order_type
			, @v_vchOrderStatus			= obMS.order_status
			, @v_vchOwnerID				= obMS.owner_id
			, @v_vchOwnerCode			= own.owner_code
			, @v_vchCustomerID			= obMS.customer_id
			, @v_vchCustomerCode		= obMS.customer_code
			, @v_vchCustomerName		= obMS.customer_name
			, @v_vchShipToCode			= obMS.ship_to_code	
			, @v_vchShipToName			= obMS.ship_to_name
			, @v_vchShipToAddr1			= obMS.ship_to_addr_line_1
			, @v_vchShipToAddr2			= obMS.ship_to_addr_line_2
			, @v_vchShipToAddr3			= obMS.ship_to_addr_line_3
			, @v_vchShipToCity			= obMS.ship_to_city
			, @v_vchShipToProvince		= obMS.ship_to_province
			, @v_vchShipToPostalCode	= obMS.ship_to_postal_code
			, @v_vchShipToCountry		= obMS.ship_to_country_code
			, @v_vchShipToCountryName	= obMS.ship_to_country_name
			, @v_vchShipToContactName	= obMS.ship_to_contact
			, @v_vchShipToPhoneNumber	= obMS.ship_to_phone
			, @v_vchBillToCode			= obMS.bill_to_code
			, @v_vchBillToName			= obMS.bill_to_name
			, @v_vchBillToAddr1			= obMS.bill_to_address_line_1
			, @v_vchBillToAddr2			= obMS.bill_to_address_line_2
			, @v_vchBillToAddr3			= obMS.bill_to_address_line_3
			, @v_vchBillToCity			= obMS.bill_to_city
			, @v_vchBillToProvince		= obMS.bill_to_province
			, @v_vchBillToPostalCode	= obMS.bill_to_postal_code
			, @v_vchBillToCountry		= obMS.bill_to_country
			, @v_vchBillToCountryName	= obMS.bill_to_country_name
			, @v_vchBillToContactName	= obMS.bill_to_contact_name
			, @v_vchBillToPhoneNumber	= obMS.bill_to_phone_number
			, @v_vchTrackingNo			= obMS.tracking_number
			, @v_vchToWarehouseID		= CONVERT(NVARCHAR(50),obMS.department)			--Warehouse สำหรับ Auto Insert Inbound
			, @v_vchCustomerOrderNumber = obMS.customer_order_number
			, @v_vchLoadID				= obMS.load_id 
			, @v_dtDeliveryDatePlan		= CONVERT(DATE,obMS.delivery_date_plan)
			, @v_dtShipDatePlan			= obMS.ship_date_plan
			, @v_vchPickType			= obMS.pick_type
			, @v_vchHUDF1				= obMS.user_def1
			, @v_vchHUDF2				= obMS.user_def2
			, @v_vchHUDF3				= obMS.user_def3
			, @v_vchHUDF4				= obMS.user_def4
			, @v_vchHUDF5				= obMS.user_def5
			, @v_vchHUDF6				= obMS.user_def6
			, @v_fltHUDF7				= obMS.user_def7
			, @v_fltHUDF8				= obMS.user_def8
			, @v_dtpHUDF9				= obMS.user_def9
			, @v_dtpHUDF10				= obMS.user_def10 
		FROM dbo.t_wms_outbound_master obMS
		INNER JOIN dbo.t_wms_owner own ON obMS.owner_id = own.owner_id
		WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID
		
		IF(@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF @v_vchOrderType IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
			BEGIN
				--ถ้าจะ Ship Qty Pick = Qty Pack = Qty DO ถึงจะยอม
				--Check Qty Pick <> Qty Pack
				IF EXISTS (SELECT pickDT.outbound_pick_detail_id
							FROM t_wms_outbound_pick_master pickMS 
							LEFT JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id 
							WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
							AND ISNULL(pickDT.quantity_pack,0) < ISNULL(pickDT.quantity_pick,0))
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHIP_QTYPICK_NOT_EQUAL_QTYPACK';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--For POD
		IF (@RulePOD = 'YES')
			BEGIN
				SELECT @v_vchRouteCode = route_code
					, @v_vchRouteName = route_name
					, @v_vchCustUdf1 = user_def1	--Pallet Type
				FROM dbo.t_wms_customer 
				WHERE customer_id = @v_vchCustomerID
				AND owner_id = @v_vchOwnerID
				AND is_active = 'YES'
				IF ISNULL(@v_vchRouteCode,'') = ''
					BEGIN
						SET @out_ErrorCode = 'ROUTE_CODE_EMPTY';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--------------------------------------------------
		-- Set Tran Type
		--------------------------------------------------
		IF (SELECT TOP 1 value from dbo.t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES') = @v_vchOrderType
	   		BEGIN
		        SET @v_vchTranType ='BLIND_PICK'	
			END
		ELSE
		    BEGIN
				SET @v_vchTranType ='OO_SHIP'
			END

		--------------------------------------------------
		-- Set Sub Tran Type
		--------------------------------------------------
		IF (@v_vchOrderType IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_INTERFACE' AND is_active = 'YES'))
			BEGIN
				SET @v_vchSubTranType = 'CONFIRM_TO_ERP';
			END
		ELSE
			BEGIN
				SET @v_vchSubTranType = 'CONFIRM_SHIP';
			END

		--------------------------------------------------
		--Get Outbound Pick MasterID
		--------------------------------------------------
		SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM dbo.t_wms_outbound_pick_master WHERE outbound_order_master_id = @in_vchOutboundMasterID

		--------------------------------------------------
		-- Check Staging before ship
		--------------------------------------------------
		IF EXISTS (SELECT outbound_pick_detail_id FROM dbo.t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) <> ISNULL(quantity_stage,0) AND is_override = 'NO')
		BEGIN
			SET @out_ErrorCode = 'INFO-NOT-PUT-ON-STAGING';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

		--------------------------------------------------
		-- Check allow shot ship or not allow shot ship
		--------------------------------------------------
		IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO'
			 AND @v_vchOrderType NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
			BEGIN
				--ห้าม short ship
				DECLARE @v_fltChkQtyForShip  FLOAT = 0
				DECLARE @v_fltChkSumQtyOrder FLOAT = 0
				IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_SHIP_ON_DOCK_DOOR' AND is_active = 'YES') = 'YES' 
					 AND @v_vchOrderType NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_MVT_IS_SHIP_ON_STAG' AND is_active = 'YES'))
					BEGIN
						SELECT @v_fltChkQtyForShip = SUM(quantity_load)
							,@v_fltChkSumQtyOrder = SUM(quantity_order)
						FROM dbo.t_wms_outbound_detail  
						WHERE outbound_order_master_id = @in_vchOutboundMasterID  
					END
				ELSE
					BEGIN
						SELECT @v_fltChkQtyForShip = SUM(quantity_pick)
							,@v_fltChkSumQtyOrder = SUM(quantity_order)
						FROM dbo.t_wms_outbound_detail  
						WHERE outbound_order_master_id = @in_vchOutboundMasterID  
					END
				IF (@v_fltChkQtyForShip < @v_fltChkSumQtyOrder)
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHOT_PICK_AND_SHIP'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				----------------------------------------------
				-- Check Checker (Load) Quantity Plan = Quantity Load
				----------------------------------------------
				IF @v_vchWarehouse IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_CHECKER_WAREHOUSE' AND is_active = 'YES')
					BEGIN
						IF (@v_vchOrderType NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_CHECKER_ORDER_TYPE' AND is_active = 'YES'))
							BEGIN
								DECLARE @v_fltCheckQtyPlan FLOAT = 0;
								DECLARE @v_fltCheckQtyLoad FLOAT = 0;
								SELECT @v_fltCheckQtyPlan = ROUND(SUM(pickDT.quantity_plan),@Round)
									, @v_fltCheckQtyLoad = ROUND(SUM(pickDT.quantity_load),@Round)
								FROM dbo.t_wms_outbound_pick_detail pickDT
								WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID
								AND is_override = 'NO'
								IF (@v_fltCheckQtyPlan <> @v_fltCheckQtyLoad)
									BEGIN
										SET @out_ErrorCode = 'ORDER_NOT_LOADED_CANNOT_SHIP';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END
					END
			END
		ELSE
			BEGIN
				--Short Ship ได้
				--Check Checker (Load) Quantity stage = Quantity Load
				IF @v_vchWarehouse IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_CHECKER_WAREHOUSE' AND is_active = 'YES')
					BEGIN
						IF (@v_vchOrderType NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_CHECKER_ORDER_TYPE' AND is_active = 'YES'))
							BEGIN
								DECLARE @v_fltChkQtyStage FLOAT = 0;
								DECLARE @v_fltChkQtyLoad  FLOAT = 0;
								SELECT @v_fltChkQtyStage = ROUND(SUM(pickDT.quantity_stage),@Round)
									, @v_fltChkQtyLoad = ROUND(SUM(pickDT.quantity_load),@Round)
								FROM dbo.t_wms_outbound_pick_detail pickDT
								WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID
								AND is_override = 'NO'

								IF (@v_fltChkQtyStage <> @v_fltChkQtyLoad)
									BEGIN
										SET @out_ErrorCode = 'ORDER_NOT_LOADED_CANNOT_SHIP';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END
					END
			END

		-- 2014-01-29 get location for order type borrow
		IF (@v_vchOrderType IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_BORROW' AND is_active = 'YES'))
			BEGIN
				SET @RuleIsBorrow = 'YES'
				SELECT TOP 1 @v_intDueDate = value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_BORROW_DUEDATE' AND is_active = 'YES'
				IF (ISNULL(@v_intDueDate,0) = 0)
					SET @v_intDueDate = 15;
			END
		
		--Get Host ID
		EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT

	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;

		/*---------------Auto Insert Inbound Master----------------*/
		DECLARE @v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchInboundOrderNumber NVARCHAR(50) = NULL 
		DECLARE @v_vchToWarehouseGUID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchToWarehouse		varchar(40) = NULL
		DECLARE @v_fltLastNumber		INT = 0
		DECLARE @v_fltNextNumber		INT = 0
		DECLARE @v_vchMaxOrderNo		NVARCHAR(50) = NULL
		IF ((SELECT TOP 1 value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_AUTO_INSERT_INBOUND' AND is_active = 'YES') = 'YES' 
			AND @v_vchOrderType IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'))
			BEGIN
				DECLARE @v_vchInboundOrderType NVARCHAR(25) = NULL
				SELECT TOP 1 @v_vchInboundOrderType = value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_INSERT_INBOUND' AND is_active = 'YES'

				SET @v_vchInboundOrderNumber = 'TRF' + @v_vchOutboundOrderNumber
				SELECT @v_vchMaxOrderNo = MAX(REPLACE(inbound_order_number,@v_vchInboundOrderNumber,''))
				FROM t_wms_inbound_master
				WHERE REPLACE(inbound_order_number,REPLACE(inbound_order_number,@v_vchInboundOrderNumber,''),'') = @v_vchInboundOrderNumber

				IF LEN(ISNULL(@v_vchMaxOrderNo,'')) = 4 AND SUBSTRING(ISNULL(@v_vchMaxOrderNo,''),1,1) = '-'
					BEGIN
						SET @v_fltLastNumber = CONVERT(INT,RIGHT(ISNULL(@v_vchMaxOrderNo,''),3))
					END
				ELSE
					BEGIN
						SET @v_fltLastNumber = 0
					END

				SET @v_fltNextNumber = @v_fltLastNumber + 1;
				SET	@v_vchInboundOrderNumber = @v_vchInboundOrderNumber + '-' +  RIGHT('000' + CONVERT(VARCHAR(20),@v_fltNextNumber),3)

				SELECT @v_vchToWarehouseGUID = wh_master_id
					,@v_vchToWarehouse = wh_id
				FROM t_wms_wh 
				WHERE CONVERT(VARCHAR(40), wh_master_id) = @v_vchToWarehouseID
				AND is_active = 'YES'
				IF @v_vchToWarehouseGUID IS NULL
					BEGIN
						SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchToWarehouse,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_vchInboundMasterID = inbound_order_master_id FROM t_wms_inbound_master WHERE wh_master_id = @v_vchToWarehouseGUID AND inbound_order_number = @v_vchInboundOrderNumber
				IF @v_vchInboundMasterID IS NULL
				BEGIN
					SET @v_vchInboundMasterID = NEWID();
					--Insert Master
					INSERT INTO [dbo].[t_wms_inbound_master]
							([inbound_order_master_id]
							,[wh_master_id]
							,[inbound_order_number]
							,[owner_id]
							,[order_type]
							,[order_status]
							,[wh_id]
							,[owner_code]
							,[reference_number]
							,[bom_inbound_order_master_id]
							,[create_by]
							,[create_date])
						VALUES
							(@v_vchInboundMasterID
							,@v_vchToWarehouseGUID
							,@v_vchInboundOrderNumber
							,@v_vchOwnerID
							,@v_vchInboundOrderType
							,'OPEN'
							,@v_vchToWarehouse
							,@v_vchOwnerCode
							,@v_vchOutboundOrderNumber
							,NULL
							,@in_vchUserID
							,GETDATE())
				END
			END

		--Update Ship Confrim
		IF ((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHIP_ON_DOCK_DOOR' AND is_active = 'YES') = 'YES'
		     AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_MVT_IS_SHIP_ON_STAG' AND is_active = 'YES'))
			BEGIN -- SHIP ON DOCK DOOR
				IF (@RulePickPack = 'YES')
					BEGIN
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,outbound_pack_detail_id
								,line_number
								,dock_door_id
								,location
								,dock_door_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_load,0) - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pack_detail  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_load,0) - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
							AND load_status = 'YES'
							AND dock_door_id IS NOT NULL
					END
				ELSE
					BEGIN
						--หากไม่ได้เปิด rule pick_pack แต่มีการ pack ต้องข้อมูลที่ pack ในการ 
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,NULL
								,line_number
								,dock_door_id
								,location
								,dock_door_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_load,0)  - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pick_mini  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_load,0)  - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
							AND load_status = 'YES'
							AND dock_door_id IS NOT NULL
					END
			End
		ELSE
			BEGIN -- SHIP ON STAGING
				IF (@RulePickPack = 'YES')
					BEGIN
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,outbound_pack_detail_id
								,line_number
								,staging_location_id
								,location
								,staging_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pack_detail  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
					END
				ELSE
					BEGIN
						--หากไม่ได้เปิด rule pick_pack แต่มีการ pack ต้องข้อมูลที่ pack ในการ ship
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,NULL
								,line_number
								,staging_location_id
								,location
								,staging_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_stage,0)  - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pick_mini  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_stage,0)  - ISNULL(quantity_ship,0) > 0 
							AND is_override = 'NO'
							AND pick_status = 'YES'
					END
			END
	    
		OPEN OutboundPickDetail_CURSOR
		FETCH NEXT FROM OutboundPickDetail_CURSOR INTO @v_vchOutboundOrderDetailID,@v_vchOutboundPickDetailID,@v_vchOutboundPackDetailID,@v_vchLineNumber,@v_vchLocationMasterID,@v_vchLocationForPick,@v_vchLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
													,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityShip,@v_vchItemUOMID,@v_vchUOM,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
													,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control,@v_dtReceiveDate,@v_vchERPLocationForPick,@v_vchZone
		IF (@@ROWCOUNT > 0)
			BEGIN
				IF (@RuleIsBorrow = 'YES')
					BEGIN-- Insert into outbound borrow master
						SET @v_vchOutboundBorrowMasterID = NEWID()
						INSERT INTO t_wms_outbound_borrow_master
							(outbound_borrow_master_id
								, wh_master_id
								, outbound_borrow_number
								, owner_id, order_type
								, order_status
								, order_date
								, description
								, department
								, customer_id
								, customer_code
								, customer_name
								, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
								, create_by)
							SELECT @v_vchOutboundBorrowMasterID
								, wh_master_id
								, outbound_order_number
								, owner_id
								, order_type
								, order_status
								, order_date
								, description
								, department
								, customer_id
								, customer_code
								, customer_name
								, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
								, @in_vchUserID 
							FROM t_wms_outbound_master 
							WHERE outbound_order_master_id = @in_vchOutboundMasterID
					END

				WHILE @@FETCH_STATUS = 0  
					BEGIN-- Ship Confirm.Update Inventory data
						BEGIN --Parameter
							DECLARE @v_dtExpiryDate		DATE = NULL
							DECLARE @v_vchFromLocation	NVARCHAR(50) = NULL
							DECLARE @v_vchInfPlanUomID  UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchInfPlanUom    VARCHAR(40) = NULL
							DECLARE @v_fltInfQuantity   FLOAT = NULL
							DECLARE @v_vchInfConFactor  FLOAT = NULL
							DECLARE @v_vchInventoryID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchInventoryStatusID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_fltInventoryQty	FLOAT = NULL
							DECLARE @v_fltAfterInvQuantity FLOAT = NULL
							DECLARE @v_dtMfgDate DATE = NULL
						
							--For Interface
							DECLARE @v_vchDUDF1  NVARCHAR(255)
							DECLARE @v_vchDUDF2  NVARCHAR(255)
							DECLARE @v_vchDUDF3  NVARCHAR(255)
							DECLARE @v_vchDUDF4  NVARCHAR(255)
							DECLARE @v_vchDUDF5  NVARCHAR(255)
							DECLARE @v_vchDUDF6  NVARCHAR(255)
							DECLARE @v_fltDUDF7  FLOAT
							DECLARE @v_fltDUDF8  FLOAT
							DECLARE @v_dtpDUDF9  DATETIME
							DECLARE @v_dtpDUDF10 DATETIME
						END

						IF ISNULL(@v_vchExpiryDate,'') <> ''
							SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate);
						SET @v_fltQuantityShip = ROUND(@v_fltQuantityShip,@Round) 
						 
						SELECT @v_vchDUDF1 = dt.user_def1
							,@v_vchDUDF2 = dt.user_def2
							,@v_vchDUDF3 = dt.user_def3
							,@v_vchDUDF4 = dt.user_def4
							,@v_vchDUDF5 = dt.user_def5
							,@v_vchDUDF6 = dt.user_def6
							,@v_fltDUDF7 = dt.user_def7
							,@v_fltDUDF8 = dt.user_def8
							,@v_dtpDUDF9 = dt.user_def9
							,@v_dtpDUDF10 = dt.user_def10
							,@v_vchLineNumber = dt.line_number
							,@v_fltQuantityOrder = dt.quantity_order
							,@v_vchInfPlanUomID = uom.item_uom_id
							,@v_vchInfPlanUom = uom.uom
							,@v_vchInfConFactor = uom.conversion_factor
						FROM t_wms_outbound_detail dt
						LEFT JOIN t_wms_item_uom uom ON dt.interface_plan_uom_id = uom.item_uom_id
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID

						IF @v_vchOutboundOrderDetailID IS NOT NULL
							BEGIN
								SET @v_fltInfQuantity = ROUND((@v_fltQuantityShip / @v_vchInfConFactor),@Round)
							END
						ELSE
							BEGIN
								SET @v_fltInfQuantity = @v_fltQuantityShip
								SET @v_vchInfPlanUom = @v_vchUOM
							END

						-- 1 Order มี 1 Dock Door
						SELECT @v_vchFromLocation = location FROM dbo.t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchLocationMasterID

						-------------------------------------------------
						--Plan เก็บเป็นหน่วย Base อยู่แล้ว
						--Get data for calculate volumn & weight
						-------------------------------------------------
						SELECT @v_fltWidth = ISNULL(width,0)
							,@v_fltLength = ISNULL(length,0)
							,@v_fltHeight = ISNULL(height,0)
							,@v_fltGrossWeight = ISNULL(gross_weight,0)
							,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
							,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
						FROM dbo.t_wms_item_uom 
						WHERE item_uom_id = @v_vchItemUOMID 
						AND primary_uom = 'YES' 
						AND is_active = 'YES'

						IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQuantityShip,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQuantityShip,2)
							END

						-------------------------------------------------------
						-- check ว่า serial ที่ลานจ่าย หรือ dock door มีของครบหรือป่าว
						-------------------------------------------------------
						IF (@v_vchSerialControl = 'FULL')
							BEGIN
								-- check ว่า serial ที่ลานจ่าย หรือ dock door มีของครบหรือป่าว
								IF NOT EXISTS(SELECT invAttr.attribute_value FROM t_wms_inventory inv 
											INNER JOIN t_wms_inventory_attribute invAttr ON inv.inventory_id = invAttr.inventory_id
											WHERE invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL')
											AND inv.location_id = @v_vchLocationMasterID
											AND ISNULL(inv.lpn,'') = ISNULL(@v_vchLPN,'')
											AND ISNULL(invAttr.attribute_value,'') = ISNULL(@v_vchSerialNumber,''))
									BEGIN
										SET @out_ErrorCode = '999';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_PICK_NOT_MATCH_ON_INVENTORY',(select dbo.usf_get_locale_id(@in_vchUserID)),null,@v_vchLPN,'@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END

						
						DECLARE @v_vchDefaultItemStatusID	uniqueidentifier = null
						SELECT @v_vchDefaultItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchDefaultItemStatus

						SELECT @v_vchInventoryID = inventory_id
							,@v_vchAttributeGroupID = attribute_group_id
							,@v_vchInventoryStatusID = inventory_status_id
							,@v_fltInventoryQty = quantity
							,@v_dtMfgDate = mfg_date
						FROM v_wms_inventory_data_serial_by_id
						WHERE wh_master_id = @v_vchWhMasterID 
						AND owner_id = @v_vchOwnerID
						AND location_id = @v_vchLocationMasterID 
						AND wh_item_master_id = @v_vchWhItemMasterID 
						AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'') 
						AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
						AND ISNULL([expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
						AND (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(@v_vchSerialNumber,'') END)
						AND inventory_status_id = @v_vchDefaultItemStatusID
						AND receive_date = @v_dtReceiveDate
						AND ISNULL(quantity,0) > 0 
						
						---------------------------------------
						-- Check Inventory
						---------------------------------------
						IF (@v_vchInventoryID IS NULL)
						BEGIN
							SET @out_ErrorCode = '999'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,@v_vchFromLocation,'@param3',@v_vchLPN,'@param5')
							GOTO WRITE_PROC;
						END
						
						---------------------------------------
						-- Check Quantity
						---------------------------------------
						IF (@v_fltInventoryQty < @v_fltQuantityShip)
						BEGIN
							SET @out_ErrorCode = '999'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchFromLocation,'@param3','@param4','@param5')
							GOTO WRITE_PROC;					
						END
							
						--------------------------------------------
						--Manage source inventory
						--------------------------------------------
						BEGIN
							--Inventory
							UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							
							--Inventory attribute for serial
							IF (@v_vchSerialControl = 'FULL')
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID 
								AND attribute_value = @v_vchSerialNumber
								AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')											
							END

							--Inventory attribute
							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID
								AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END

							DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
							DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
						
							--Update Volumn & Weight in from location
							IF @v_vchLocationMasterID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location]
									SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
									WHERE [location_id] = @v_vchLocationMasterID
							END

							
						END
																
						IF (@RuleIsBorrow = 'YES')
							BEGIN-- ship confirm of borrow type
								DECLARE @v_vchHoldInventoryStatusID UNIQUEIDENTIFIER = NULL
								DECLARE @v_vchLocationBorrowID UNIQUEIDENTIFIER = NULL
								DECLARE @v_vchLocationBorrow NVARCHAR(50) = NULL 

								-- select location from item detail
								SELECT @v_vchHoldInventoryStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = 'Hold' AND is_active = 'YES'
								SELECT @v_vchLocationBorrow = user_def1 FROM t_wms_item WHERE item_master_id = @v_vchItemMasterID
								IF (ISNULL(@v_vchLocationBorrow,'') <> '')
									BEGIN
										SELECT @v_vchLocationBorrowID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @v_vchLocationBorrow AND is_active = 'YES'
									END
								ELSE
									BEGIN
										SELECT TOP 1 @v_vchLocationBorrow = location, @v_vchLocationBorrowID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND loc_type = 'BORROW' AND is_active = 'YES'
									END

								IF (@v_vchLocationBorrow IS NULL)
									BEGIN
										SET @out_ErrorCode = '999'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_BORROW_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							 
								-- Manage Inventory Move to Borrow Location
								BEGIN
									EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
															 ,@in_vchWhMasterID			= @v_vchWhMasterID
															 ,@in_vchWhID				= @v_vchWarehouse
															 ,@in_vchOwnerID			= @v_vchOwnerID
															 ,@in_vchInventoryType		= 'INVENTORY'
															 ,@in_vchLocationID			= @v_vchLocationBorrowID
															 ,@in_vchParentLPN			= NULL
															 ,@in_vchLPN				= @v_vchLPN
															 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
															 ,@in_vchItemMasterID		= @v_vchItemMasterID
															 ,@in_vchItemNumber			= @v_vchItemNumber
															 ,@in_fltQuantity			= @v_fltQuantityShip
															 ,@in_fltQtyAllocate		= 0
															 ,@in_fltQtyIncoming		= 0
															 ,@in_vchPrimaryItemUomID	= @v_vchItemUOMID
															 ,@in_vchInvStatusID		= @v_vchHoldInventoryStatusID
															 ,@in_vchLotNumber			= @v_vchLotNumber
															 ,@in_vchExpiryDate			= @v_vchExpiryDate
															 ,@in_vchSerialNumber		= @v_vchSerialNumber
															 ,@in_vchAttribute1			= @v_vchAttribute1
															 ,@in_vchAttribute2			= @v_vchAttribute2
															 ,@in_vchAttribute3			= @v_vchAttribute3
															 ,@in_vchAttribute4			= @v_vchAttribute4
															 ,@in_vchAttribute5			= @v_vchAttribute5
															 ,@in_dReceiveDate			= @v_dtReceiveDate
															 ,@in_dtMfgDate				= @v_dtMfgDate
															 ,@in_vchDeviceID			= @in_vchDeviceID
															 ,@in_vchUserID				= @in_vchUserID
															 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
															 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
															 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END

								-- insert into outbound borrow detail
								IF NOT EXISTS(SELECT outbound_borrow_detail_id from t_wms_outbound_borrow_detail 
												WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID 
												AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
												AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpiryDate,'')
												AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
												AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
												AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
												AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
												AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
												AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,''))
									BEGIN -- NOT SAME DATA
										INSERT INTO t_wms_outbound_borrow_detail
											(outbound_borrow_detail_id
											, outbound_borrow_master_id
											, outbound_order_detail_id
											, wh_item_master_id
											, line_number
											, customer_id
											, customer_code
											, customer_name
											, quantity_order
											, quantity_return
											, due_date
											, item_uom_id
											, item_status
											, location_id
											, parent_lpn
											, lpn
											, lot_number
											, expiry_date
											, serial_number
											, [attribute1]
											, [attribute2]
											, [attribute3]
											, [attribute4]
											, [attribute5]
											, remark
											, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
											, create_by)
										SELECT NEWID()
											, @v_vchOutboundBorrowMasterID
											, @v_vchOutboundOrderDetailID
											, @v_vchWhItemMasterID
											, @v_vchLineNumber
											, @v_vchCustomerID
											, @v_vchCustomerCode
											, @v_vchCustomerName
											, @v_fltQuantityShip
											, 0
											, DATEADD(dd,@v_intDueDate,GETDATE())
											, item_uom_id
											, 'Borrow'
											, @v_vchLocationBorrowID
											, null --[parent_lpn]
											, null --[lpn]
											, @v_vchLotNumber
											, @v_vchExpiryDate
											, @v_vchSerialNumber
											, @v_vchAttribute1
											, @v_vchAttribute2
											, @v_vchAttribute3
											, @v_vchAttribute4
											, @v_vchAttribute5
											, null --[remark]
											, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
											, @in_vchUserID
										FROM t_wms_outbound_detail 
										WHERE outbound_order_master_id = @in_vchOutboundMasterID 
										AND outbound_order_detail_id = @v_vchOutboundOrderDetailID
									END
								ELSE
									BEGIN
										UPDATE t_wms_outbound_borrow_detail SET quantity_order = ROUND(ISNULL(quantity_order,0) + @v_fltQuantityShip,@Round)
										WHERE outbound_borrow_master_id = @v_vchOutboundBorrowMasterID 
										AND outbound_order_detail_id = @v_vchOutboundOrderDetailID
									END

								--Write Log Move to Borrow Location
								SET @v_dtEndTranDate = GETDATE();
								EXEC usp_LogManager
										 @in_vchApplicationID = @in_vchApplicationID
										,@in_vchAppName = @v_vchApplicationName
										,@in_vchDevice = @in_vchDeviceID
										,@in_vchUserID = @in_vchUserID
										,@in_vchLogType = 'TRANSACTION'
										,@in_vchTranType = 'OO_SHIP'
										,@in_vchSubTranType = 'MOVE_BORROW'
										,@in_vchDescription = 'Move for Borrow (Partial Ship)'
										,@in_dtStartTranDate = @v_dtStartTranDate
										,@in_dtEndTranDate = @v_dtEndTranDate
										,@in_vchWhID = @v_vchWarehouse
										,@in_vchToWhID = @v_vchWarehouse
										,@in_vchOwner = @v_vchOwnerCode
										,@in_vchToOwner = @v_vchOwnerCode
										,@in_vchLocation = @v_vchLocationForPick
										,@in_vchToLocation = @v_vchLocationBorrow
										,@in_vchItemNumber = @v_vchItemNumber
										,@in_vchUOM = @v_vchUOM
										,@in_vchBaseUOM = @v_vchUOM
										,@in_fltQuantity = @v_fltQuantityShip
										,@in_fltAfterQuantity = 0
										,@in_vchAfterUOM = @v_vchUOM
										,@in_vchLotNumber = @v_vchLotNumber
										,@in_vchAfterLotNumber = @v_vchLotNumber
										,@in_dtExpiryDate = @v_dtExpiryDate
										,@in_dtAfterExpiryDate = @v_dtExpiryDate
										,@in_vchAttribute1		= @v_vchAttribute1
										,@in_vchAfterAttribute1	= @v_vchAttribute1
										,@in_vchAttribute2		= @v_vchAttribute2
										,@in_vchAfterAttribute2	= @v_vchAttribute2
										,@in_vchAttribute3		= @v_vchAttribute3
										,@in_vchAfterAttribute3	= @v_vchAttribute3
										,@in_vchAttribute4		= @v_vchAttribute4
										,@in_vchAfterAttribute4	= @v_vchAttribute4
										,@in_vchAttribute5		= @v_vchAttribute5
										,@in_vchAfterAttribute5	= @v_vchAttribute5
										,@in_vchSerialNumber = @v_vchSerialNumber

										,@in_vchLPN = @v_vchLPN
										,@in_vchAfterLPN = @v_vchLPN
										,@in_vchStatus = @v_vchDefaultItemStatus
										,@in_vchAfterStatus = @v_vchDefaultItemStatus

										,@in_vchOrderNumber = @v_vchOutboundOrderNumber
										,@in_vchOrderStatus = 'SHIP'
										,@in_vchOrderType = @v_vchOrderType
										,@in_vchControlNumber = @v_vchHostInterfaceID
										,@in_vchLineNumber = @v_vchLineNumber
										,@in_vchOrderQuantity = @v_fltQuantityOrder
										,@in_vchShortQuantity = 0

										,@in_vchProcess = @c_vchObjName
										,@in_dtProcessDateTime = @v_dtProcessDateTime 
										,@in_vchTrackingNumber = @v_vchTrackingNo
										 
										,@in_vchHUDF1  = @v_vchHUDF1	--Master Kool
										,@in_vchHUDF2  = @v_vchHUDF2
										,@in_vchHUDF3  = @v_vchHUDF3
										,@in_vchHUDF4  = @v_vchHUDF4
										,@in_vchHUDF5  = @v_vchHUDF5
										,@in_vchHUDF6  = @v_vchHUDF6
										,@in_fltHUDF7  = @v_fltHUDF7
										,@in_fltHUDF8  = @v_fltHUDF8
										,@in_dtpHUDF9  = @v_dtpHUDF9
										,@in_dtpHUDF10 = @v_dtpHUDF10

										,@in_vchDUDF1  = @v_vchDUDF1
										,@in_vchDUDF2  = @v_vchDUDF2
										,@in_vchDUDF3  = @v_vchDUDF3
										,@in_vchDUDF4  = @v_vchDUDF4
										,@in_vchDUDF5  = @v_vchDUDF5
										,@in_vchDUDF6  = @v_vchInfPlanUom	--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
										,@in_fltDUDF7  = @v_fltInfQuantity	--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
										,@in_fltDUDF8  = @v_fltDUDF8
										,@in_dtpDUDF9  = @v_dtpDUDF9
										,@in_dtpDUDF10 = @v_dtpDUDF10  
										,@in_vchHostRecordID	= @v_vchHostInterfaceID
										,@in_dtPostingDate		= @v_dtShipDateActual
										,@in_dtReceiveDate		= @v_dtReceiveDate
										,@in_dtProductionDate	= @v_dtMfgDate
										,@in_vchCustomerCode	= @v_vchCustomerCode 
										,@in_dtShipDateActual	= @v_dtShipDateActual
										,@in_dtDeliveryDatePlan	= @v_dtDeliveryDatePlan

										,@in_vchShipToCode		= @v_vchShipToCode		
										,@in_vchShipToName		= @v_vchShipToName		
										,@in_vchShipToAddr1		= @v_vchShipToAddr1		
										,@in_vchShipToAddr2		= @v_vchShipToAddr2		
										,@in_vchShipToAddr3		= @v_vchShipToAddr3		
										,@in_vchShipToCity		= @v_vchShipToCity		
										,@in_vchShipToProvince	= @v_vchShipToProvince	
										,@in_vchShipToPostalCode  = @v_vchShipToPostalCode	
										,@in_vchShipToCountry	  = @v_vchShipToCountry		
										,@in_vchShipToCountryName = @v_vchShipToCountryName 
										,@in_vchShipToContactName = @v_vchShipToContactName 
										,@in_vchShipToPhoneNumber = @v_vchShipToPhoneNumber 
										,@in_vchBillToCode		  = @v_vchBillToCode		
										,@in_vchBillToName		  = @v_vchBillToName		
										,@in_vchBillToAddr1		  = @v_vchBillToAddr1		
										,@in_vchBillToAddr2		  = @v_vchBillToAddr2		
										,@in_vchBillToAddr3		  = @v_vchBillToAddr3		
										,@in_vchBillToCity		  = @v_vchBillToCity		
										,@in_vchBillToProvince	  = @v_vchBillToProvince	
										,@in_vchBillToPostalCode  = @v_vchBillToPostalCode	
										,@in_vchBillToCountry	  = @v_vchBillToCountry		
										,@in_vchBillToCountryName = @v_vchBillToCountryName 
										,@in_vchBillToContactName = @v_vchBillToContactName 
										,@in_vchBillToPhoneNumber = @v_vchBillToPhoneNumber
										,@in_vchErrorCode		  = @out_ErrorCode OUTPUT
										,@in_vchMessage			  = @out_ErrorMessage OUTPUT
								IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
									BEGIN
										GOTO WRITE_PROC;
									END

								-- For Dashboard Borrow
								EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
																,@in_vchTransType	 = 'SHIP'
																,@in_vchWhMasterID	 = @v_vchWhMasterID
																,@in_vchOwnerID		 = @v_vchOwnerID
																,@in_vchOwnerCode	 = @v_vchOwnerCode
																,@in_vchLocationID	 = @v_vchLocationMasterID
																,@in_vchItemMasterID = @v_vchItemMasterID
																,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
																,@in_vchToWhMasterID = @v_vchWhMasterID
																,@in_vchToLocationID = @v_vchLocationBorrowID
																,@in_vchToInvStatusID = @v_vchHoldInventoryStatusID
																,@in_fltQuantity	 = @v_fltQuantityShip
																,@in_vchUserID		 = @in_vchUserID
							END
						ELSE
							BEGIN --ship confirm of normal type
								IF @v_vchOrderType IN (SELECT value FROM t_wms_rule where rule_code = 'ORDER_TYPE_OUTBOUND_CONSIGNMENT' AND is_active = 'YES')
									BEGIN --Write Log for ship to customer location (move) 
										DECLARE @v_vchERPDestLocation	NVARCHAR(50) = NULL
										DECLARE @v_vchERPSourceLocation	NVARCHAR(50) = NULL
										DECLARE @v_vchFromLocationID	UNIQUEIDENTIFIER = NULL
										DECLARE @v_vchLocType			NVARCHAR(25) = NULL
										DECLARE @v_vchMoveToLPNControl	VARCHAR(5) = NULL
										SET @v_vchMoveSubTranType = NULL
										SET @v_vchMoveToLocationID	= NULL
										SET @v_vchMoveToLocation	= NULL
										SET @v_vchMoveToInvStatusID	= NULL
										SET @v_vchMoveToInvStatus = @v_vchDefaultItemStatus
										SELECT @v_vchMoveToInvStatusID = inventory_status_id FROM t_wms_inventory_status  WHERE inv_status = @v_vchMoveToInvStatus AND is_active = 'YES'
										IF @v_vchMoveToInvStatusID IS NULL
											BEGIN
												SET @out_ErrorCode = 'INVENTORY_STATUS_NOT_FOUND'
												SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchMoveToInvStatus,'@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;		
											END
										
										-- Check from location
										SELECT @v_vchFromLocationID = loc.location_id 
											,@v_vchERPSourceLocation = loc.erp_location
											,@v_vchLocType = loc.loc_type
										FROM t_wms_location loc
 										WHERE loc.location = @v_vchLocationForPick 
										AND loc.wh_master_id = @v_vchWhMasterID 
										AND loc.is_active = 'YES'
										IF(@v_vchFromLocationID IS NULL)
											BEGIN
												SET @out_ErrorCode = 'LOCATION_NOT_FOUND'
												SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;
											END

										-- Check to location
										SELECT @v_vchMoveToLocationID = custLoc.location_id 
											,@v_vchMoveToLocation = loc.location
											,@v_vchERPDestLocation = loc.erp_location
											,@v_vchMoveToLPNControl = loc.lpn_controlled
										FROM t_wms_customer_location custLoc 
										INNER JOIN t_wms_location loc ON custLoc.location_id = loc.location_id 
										WHERE custLoc.customer_id = @v_vchCustomerID
										AND loc.wh_master_id = @v_vchWhMasterID
										AND custLoc.is_active = 'YES'
										AND loc.loc_type = 'STORE'
										IF (@v_vchMoveToLocationID IS NULL)
											BEGIN
												SET @out_ErrorCode = 'INFO-CUSTOMER-LOCATION-NOT-MAP'
												SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;		
											END

										--Master Kool
										--กรณี Move Location ให้ตรวจสอบ ERP Location ต้นทางกับปลายทางตรงกันหรือไม่ถ้าตรงกันไม่ต้อง interface 
										IF ((@v_vchERPSourceLocation = @v_vchERPDestLocation) OR @v_vchLocType = 'UNPICK')
											BEGIN
												SET @v_vchMoveSubTranType = 'MOVE_CONSIGN_NOERP'
											END
										ELSE
											BEGIN
												SET @v_vchMoveSubTranType = 'MOVE_CONSIGN'
											END

										IF @v_vchMoveToLPNControl = 'NO' AND ISNULL(@v_vchLPN,'') <> ''
										BEGIN
											SET @v_vchLPN = NULL
										END 

										--------------------------------------------
										--Manage Inventory
										-------------------------------------------- 
										BEGIN --ย้ายของไปที่ customer location
											EXEC usp_manage_inventory_control @in_vchApplicationID		= @in_vchApplicationID
																			 ,@in_vchWhMasterID			= @v_vchWhMasterID
																			 ,@in_vchWhID				= @v_vchWarehouse
																			 ,@in_vchOwnerID			= @v_vchOwnerID
																			 ,@in_vchInventoryType		= 'INVENTORY'
																			 ,@in_vchLocationID			= @v_vchMoveToLocationID
																			 ,@in_vchParentLPN			= NULL
																			 ,@in_vchLPN				= @v_vchLPN
																			 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
																			 ,@in_vchItemMasterID		= @v_vchItemMasterID
																			 ,@in_vchItemNumber			= @v_vchItemNumber
																			 ,@in_fltQuantity			= @v_fltQuantityShip
																			 ,@in_fltQtyAllocate		= 0
																			 ,@in_fltQtyIncoming		= 0
																			 ,@in_vchPrimaryItemUomID	= @v_vchItemUOMID
																			 ,@in_vchInvStatusID		= @v_vchMoveToInvStatusID
																			 ,@in_vchLotNumber			= @v_vchLotNumber
																			 ,@in_vchExpiryDate			= @v_vchExpiryDate
																			 ,@in_vchSerialNumber		= @v_vchSerialNumber
																			 ,@in_vchAttribute1			= @v_vchAttribute1
																			 ,@in_vchAttribute2			= @v_vchAttribute2
																			 ,@in_vchAttribute3			= @v_vchAttribute3
																			 ,@in_vchAttribute4			= @v_vchAttribute4
																			 ,@in_vchAttribute5			= @v_vchAttribute5
																			 ,@in_dReceiveDate			= @v_dtReceiveDate
																			 ,@in_dtMfgDate				= @v_dtMfgDate
																			 ,@in_vchDeviceID			= @in_vchDeviceID
																			 ,@in_vchUserID				= @in_vchUserID
																			 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
																			 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
																			 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

											IF (@out_ErrorCode <> '0')
												GOTO WRITE_PROC; 
										END

										--Write Log
										SET @v_dtEndTranDate = GETDATE();
										EXEC usp_LogManager
												@in_vchApplicationID = @in_vchApplicationID
											,@in_vchAppName = @v_vchApplicationName
											,@in_vchDevice = @in_vchDeviceID
											,@in_vchUserID = @in_vchUserID
											,@in_vchLogType = 'TRANSACTION'
											,@in_vchTranType = 'OO_SHIP'
											,@in_vchSubTranType = @v_vchMoveSubTranType
											,@in_vchDescription = 'Move for Outbound Consignment (Partial Ship)'
											,@in_dtStartTranDate = @v_dtStartTranDate
											,@in_dtEndTranDate = @v_dtEndTranDate
											,@in_vchWhID = @v_vchWarehouse
											,@in_vchToWhID = @v_vchWarehouse
											,@in_vchOwner = @v_vchOwnerCode
											,@in_vchToOwner = @v_vchOwnerCode
											,@in_vchLocation = @v_vchLocationForPick
											,@in_vchToLocation = @v_vchMoveToLocation
											,@in_vchItemNumber = @v_vchItemNumber
											,@in_vchUOM = @v_vchUOM
											,@in_vchBaseUOM = @v_vchUOM
											,@in_fltQuantity = @v_fltQuantityShip 
											,@in_fltAfterQuantity = 0
											,@in_vchAfterUOM = @v_vchUOM
											,@in_vchLotNumber = @v_vchLotNumber
											,@in_vchAfterLotNumber = @v_vchLotNumber
											,@in_dtExpiryDate = @v_dtExpiryDate
											,@in_dtAfterExpiryDate = @v_dtExpiryDate
											,@in_vchAttribute1		= @v_vchAttribute1
											,@in_vchAfterAttribute1	= @v_vchAttribute1
											,@in_vchAttribute2		= @v_vchAttribute2
											,@in_vchAfterAttribute2	= @v_vchAttribute2
											,@in_vchAttribute3		= @v_vchAttribute3
											,@in_vchAfterAttribute3	= @v_vchAttribute3
											,@in_vchAttribute4		= @v_vchAttribute4
											,@in_vchAfterAttribute4	= @v_vchAttribute4
											,@in_vchAttribute5		= @v_vchAttribute5
											,@in_vchAfterAttribute5	= @v_vchAttribute5
											,@in_vchSerialNumber = @v_vchSerialNumber
											,@in_vchLPN = @v_vchLPN
											,@in_vchAfterLPN = @v_vchLPN
											,@in_vchStatus = @v_vchDefaultItemStatus
											,@in_vchAfterStatus = @v_vchMoveToInvStatus 
											,@in_vchOrderNumber = @v_vchOutboundOrderNumber
											,@in_vchOrderStatus = @v_vchOrderStatus
											,@in_vchOrderType = @v_vchOrderType
											,@in_vchControlNumber = @v_vchHostInterfaceID
											,@in_vchLineNumber = @v_vchLineNumber
											,@in_vchOrderQuantity = @v_fltQuantityOrder
											,@in_vchShortQuantity = 0

											,@in_vchProcess = @c_vchObjName
											,@in_dtProcessDateTime = @v_dtProcessDateTime 
											,@in_vchTrackingNumber = @v_vchTrackingNo 

											,@in_vchHUDF1 = @v_vchHUDF1
											,@in_vchHUDF2 = @v_vchHUDF2
											,@in_vchHUDF3 = @v_vchHUDF3
											,@in_vchHUDF4 = @v_vchHUDF4
											,@in_vchHUDF5 = @v_vchHUDF5
											,@in_vchHUDF6 = @v_vchHUDF6
											,@in_fltHUDF7 = @v_fltHUDF7
											,@in_fltHUDF8 = @v_fltHUDF8
											,@in_dtpHUDF9 = @v_dtpHUDF9
											,@in_dtpHUDF10 = @v_dtpHUDF10

											,@in_vchDUDF1 = @v_vchLocationForPick
											,@in_vchDUDF2 = @v_vchHUDF2
											,@in_vchDUDF3 = @v_vchDUDF3
											,@in_vchDUDF4 = @v_vchDUDF4
											,@in_vchDUDF5 = @v_vchDUDF5
											,@in_vchDUDF6 = @v_vchInfPlanUom
											,@in_fltDUDF7 = @v_fltInfQuantity
											,@in_fltDUDF8 = @v_fltDUDF8
											,@in_dtpDUDF9 = @v_dtpDUDF9
											,@in_dtpDUDF10 = @v_dtpDUDF10
												 
											,@in_vchHostRecordID	= @v_vchHostInterfaceID
											,@in_dtPostingDate		= @v_dtShipDateActual
											,@in_dtReceiveDate		= @v_dtReceiveDate
											,@in_dtProductionDate	= @v_dtMfgDate

											,@in_vchCustomerCode	= @v_vchCustomerCode
											,@in_vchSupplierCode	= NULL
											,@in_dtShipDateActual	= @v_dtShipDateActual
											,@in_dtDeliveryDatePlan	= @v_dtDeliveryDatePlan 

											,@in_vchShipToCode			= @v_vchShipToCode		
											,@in_vchShipToName			= @v_vchShipToName		
											,@in_vchShipToAddr1			= @v_vchShipToAddr1		
											,@in_vchShipToAddr2			= @v_vchShipToAddr2		
											,@in_vchShipToAddr3			= @v_vchShipToAddr3		
											,@in_vchShipToCity			= @v_vchShipToCity		
											,@in_vchShipToProvince		= @v_vchShipToProvince	
											,@in_vchShipToPostalCode	= @v_vchShipToPostalCode	
											,@in_vchShipToCountry		= @v_vchShipToCountry		
											,@in_vchShipToCountryName	= @v_vchShipToCountryName 
											,@in_vchShipToContactName	= @v_vchShipToContactName 
											,@in_vchShipToPhoneNumber	= @v_vchShipToPhoneNumber 
											,@in_vchBillToCode			= @v_vchBillToCode		
											,@in_vchBillToName			= @v_vchBillToName		
											,@in_vchBillToAddr1			= @v_vchBillToAddr1		
											,@in_vchBillToAddr2			= @v_vchBillToAddr2		
											,@in_vchBillToAddr3			= @v_vchBillToAddr3		
											,@in_vchBillToCity			= @v_vchBillToCity		
											,@in_vchBillToProvince		= @v_vchBillToProvince	
											,@in_vchBillToPostalCode	= @v_vchBillToPostalCode	
											,@in_vchBillToCountry		= @v_vchBillToCountry		
											,@in_vchBillToCountryName	= @v_vchBillToCountryName 
											,@in_vchBillToContactName	= @v_vchBillToContactName 
											,@in_vchBillToPhoneNumber	= @v_vchBillToPhoneNumber
											,@in_vchComment				= @v_vchOutboundOrderDetailID
											,@in_vchControlValue1		= @v_vchERPSourceLocation
											,@in_vchControlValue2		= @v_vchERPDestLocation
											,@in_vchErrorCode = @out_ErrorCode OUTPUT
											,@in_vchMessage	= @out_ErrorMessage OUTPUT
										IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
											BEGIN
												GOTO WRITE_PROC;
											END

										-- For Dashboard Consignment
										EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
																		,@in_vchTransType	 = 'SHIP'
																		,@in_vchWhMasterID	 = @v_vchWhMasterID
																		,@in_vchOwnerID		 = @v_vchOwnerID
																		,@in_vchOwnerCode	 = @v_vchOwnerCode
																		,@in_vchLocationID	 = @v_vchLocationMasterID
																		,@in_vchItemMasterID = @v_vchItemMasterID
																		,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
																		,@in_vchToWhMasterID = @v_vchWhMasterID
																		,@in_vchToLocationID = @v_vchMoveToLocationID
																		,@in_vchToInvStatusID = @v_vchMoveToInvStatusID
																		,@in_fltQuantity	 = @v_fltQuantityShip
																		,@in_vchUserID		 = @in_vchUserID
										
									END
								ELSE
									BEGIN --Write Log of normal type (ship out)
										SET @v_dtEndTranDate = GETDATE();
										EXEC usp_LogManager 
											@in_vchApplicationID = @in_vchApplicationID
											,@in_vchAppName			= @v_vchApplicationName
											,@in_vchDevice			= @in_vchDeviceID
											,@in_vchUserID			= @in_vchUserID
											,@in_vchLogType			= 'TRANSACTION'
											,@in_vchTranType		= @v_vchTranType
											,@in_vchSubTranType		= @v_vchSubTranType
											,@in_vchDescription		= 'Partial comfirm ship'
											,@in_dtStartTranDate	= @v_dtStartTranDate
											,@in_dtEndTranDate		= @v_dtEndTranDate
											,@in_vchWhID			= @v_vchWarehouse
											,@in_vchToWhID			= NULL
											,@in_vchOwner			= @v_vchOwnerCode
											,@in_vchToOwner			= NULL
											,@in_vchLocation		= @v_vchFromLocation
											,@in_vchToLocation		= NULL
											,@in_vchItemNumber		= @v_vchItemNumber
											,@in_vchUOM				= @v_vchUOM
											,@in_vchBaseUOM			= @v_vchUOM
											,@in_fltQuantity		= @v_fltQuantityShip
											,@in_vchSerialNumber	= @v_vchSerialNumber
											,@in_fltAfterQuantity	= 0
											,@in_vchAfterUOM		= @v_vchUOM
											,@in_vchLotNumber		= @v_vchLotNumber
											,@in_vchAfterLotNumber	= NULL
											,@in_dtExpiryDate		= @v_dtExpiryDate
											,@in_dtAfterExpiryDate	= NULL
											,@in_vchAttribute1		= @v_vchAttribute1
											,@in_vchAfterAttribute1	= NULL
											,@in_vchAttribute2		= @v_vchAttribute2
											,@in_vchAfterAttribute2	= NULL
											,@in_vchAttribute3		= @v_vchAttribute3
											,@in_vchAfterAttribute3	= NULL
											,@in_vchAttribute4		= @v_vchAttribute4
											,@in_vchAfterAttribute4	= NULL
											,@in_vchAttribute5		= @v_vchAttribute5
											,@in_vchAfterAttribute5	= NULL
											,@in_vchLPN				= @v_vchLPN
											,@in_vchAfterLPN		= NULL
											,@in_vchStatus			= @v_vchDefaultItemStatus
											,@in_vchAfterStatus		= NULL
											,@in_vchOrderNumber		= @v_vchOutboundOrderNumber
											,@in_vchOrderStatus		= 'SHIP'
											,@in_vchOrderType		= @v_vchOrderType
											,@in_vchControlNumber	= @v_vchHostInterfaceID
											,@in_vchLineNumber		= @v_vchLineNumber
											,@in_vchOrderQuantity	= @v_fltQuantityOrder
											,@in_vchShortQuantity	= 0

											,@in_vchProcess			= @c_vchObjName
											,@in_dtProcessDateTime	= @v_dtProcessDateTime
											,@in_vchTrackingNumber	= @v_vchTrackingNo

											,@in_vchHUDF1			= @v_vchHUDF1
											,@in_vchHUDF2			= @v_vchHUDF2
											,@in_vchHUDF3			= @v_vchHUDF3
											,@in_vchHUDF4			= @v_vchHUDF4
											,@in_vchHUDF5			= @v_vchHUDF5
											,@in_vchHUDF6			= @v_vchHUDF6
											,@in_fltHUDF7			= @v_fltHUDF7
											,@in_fltHUDF8			= @v_fltHUDF8
											,@in_dtpHUDF9			= @v_dtpHUDF9
											,@in_dtpHUDF10			= @v_dtpHUDF10

											,@in_vchDUDF1			= @v_vchDUDF1
											,@in_vchDUDF2			= @v_vchDUDF2
											,@in_vchDUDF3			= @v_vchDUDF3
											,@in_vchDUDF4			= @v_vchDUDF4
											,@in_vchDUDF5			= @v_vchDUDF5
											,@in_vchDUDF6			= @v_vchInfPlanUom		--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
											,@in_fltDUDF7			= @v_fltInfQuantity		--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
											,@in_fltDUDF8			= @v_fltDUDF8
											,@in_dtpDUDF9			= @v_dtpDUDF9
											,@in_dtpDUDF10			= @v_dtpDUDF10
											
											,@in_vchZone			= @v_vchZone
											,@in_vchPickLocation	= @v_vchLocationForPick
											,@in_vchControlValue1   = @v_vchERPLocationForPick
											,@in_vchHostRecordID	= @v_vchHostInterfaceID
											,@in_dtPostingDate		= @v_dtShipDateActual
											,@in_dtReceiveDate		= @v_dtReceiveDate
											,@in_dtProductionDate	= @v_dtMfgDate
											,@in_vchCustomerCode	= @v_vchCustomerCode 
											,@in_dtShipDateActual	= @v_dtShipDateActual
											,@in_dtDeliveryDatePlan = @v_dtDeliveryDatePlan 

											,@in_vchShipToCode			= @v_vchShipToCode		
											,@in_vchShipToName			= @v_vchShipToName		
											,@in_vchShipToAddr1			= @v_vchShipToAddr1		
											,@in_vchShipToAddr2			= @v_vchShipToAddr2		
											,@in_vchShipToAddr3			= @v_vchShipToAddr3		
											,@in_vchShipToCity			= @v_vchShipToCity		
											,@in_vchShipToProvince		= @v_vchShipToProvince	
											,@in_vchShipToPostalCode	= @v_vchShipToPostalCode	
											,@in_vchShipToCountry		= @v_vchShipToCountry		
											,@in_vchShipToCountryName	= @v_vchShipToCountryName 
											,@in_vchShipToContactName	= @v_vchShipToContactName 
											,@in_vchShipToPhoneNumber	= @v_vchShipToPhoneNumber 
											,@in_vchBillToCode			= @v_vchBillToCode		
											,@in_vchBillToName			= @v_vchBillToName		
											,@in_vchBillToAddr1			= @v_vchBillToAddr1		
											,@in_vchBillToAddr2			= @v_vchBillToAddr2		
											,@in_vchBillToAddr3			= @v_vchBillToAddr3		
											,@in_vchBillToCity			= @v_vchBillToCity		
											,@in_vchBillToProvince		= @v_vchBillToProvince	
											,@in_vchBillToPostalCode	= @v_vchBillToPostalCode	
											,@in_vchBillToCountry		= @v_vchBillToCountry		
											,@in_vchBillToCountryName	= @v_vchBillToCountryName 
											,@in_vchBillToContactName	= @v_vchBillToContactName 
											,@in_vchBillToPhoneNumber	= @v_vchBillToPhoneNumber
											,@in_vchComment				= @v_vchOutboundOrderDetailID
											,@in_vchErrorCode			= @out_ErrorCode OUTPUT
											,@in_vchMessage				= @out_ErrorMessage OUTPUT

										IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
											BEGIN
												GOTO WRITE_PROC;
											END

										-- For Dashboard
										EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT'
																		,@in_vchTransType	 = 'SHIP'
																		,@in_vchWhMasterID	 = @v_vchWhMasterID
																		,@in_vchOwnerID		 = @v_vchOwnerID
																		,@in_vchOwnerCode	 = @v_vchOwnerCode
																		,@in_vchLocationID	 = @v_vchLocationMasterID
																		,@in_vchItemMasterID = @v_vchItemMasterID
																		,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
																		,@in_vchToWhMasterID = NULL
																		,@in_vchToLocationID = NULL
																		,@in_vchToInvStatusID = NULL
																		,@in_fltQuantity	 = @v_fltQuantityShip
																		,@in_vchUserID		 = @in_vchUserID
									END
							END

						UPDATE t_wms_outbound_detail SET 
							item_status = 'SHIP'
							,quantity_ship = ROUND(ROUND(quantity_ship,@Round) + ROUND(@v_fltQuantityShip,@Round),@Round)  
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID
					          
						UPDATE t_wms_outbound_pick_detail SET 
							ship_status = 'YES' 
							,quantity_ship = ROUND(ROUND(quantity_ship,@Round) + ROUND(@v_fltQuantityShip,@Round),@Round) 
							,user_def1 = @v_vchOutboundOrderNumber
							,user_def9 = @v_dtShipDatePlan
						WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

						/*---------------Insert Inbound Detail----------------*/
						IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_INSERT_INBOUND' AND is_active = 'YES') = 'YES' 
							AND @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'))
							BEGIN
								
								DECLARE @v_vchItemGUID			UNIQUEIDENTIFIER = NULL		-- item master id ของ wh เดิม
								DECLARE @v_vchWhItemGUID		UNIQUEIDENTIFIER = NULL		-- wh item master id ของ wh ใหม่
								DECLARE @v_vchIBItemNumber		NVARCHAR(50) = NULL
								DECLARE @v_vchGrade				NVARCHAR(40) = NULL
								DECLARE @v_vchPrice				FLOAT = NULL
								DECLARE @v_vchIBUom				VARCHAR(20) = NULL
								DECLARE @v_intLine				INT = 0
								DECLARE @v_vchIBLineNumber		VARCHAR(10) = NULL
									
								--Get item number of old warehouse
								SELECT @v_vchItemGUID = item_master_id FROM t_wms_wh_item  WHERE wh_item_master_id = @v_vchWhItemMasterID	

								--Get data wh item master id in new warehouse
								SELECT @v_vchGrade = item.grade
									,@v_vchPrice = item.price
									,@v_vchItemGUID = item.item_master_id
									,@v_vchWhItemGUID = whItem.wh_item_master_id
									,@v_vchIBItemNumber = item.item_number
									,@v_vchItemUOMID = uom.item_uom_id
									,@v_vchIBUom = uom.uom
								FROM t_wms_wh_item whItem
								INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
								INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
								WHERE item.item_master_id = @v_vchItemGUID
								AND whItem.wh_master_id = @v_vchToWarehouseGUID
								AND item.is_active = 'YES'

								IF @v_vchWhItemGUID IS NULL
									BEGIN
										SET @out_ErrorCode = 'NOT_FOUND_ITEM_MASTER'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END

								SELECT @v_intLine = CONVERT(INT,MAX(line_number)) FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID
								SET @v_vchIBLineNumber = RIGHT('000000'+CONVERT(VARCHAR(20),ISNULL(@v_intLine,0) + 1),6)

								--Insert Detail
								INSERT INTO [dbo].[t_wms_inbound_detail]
											([inbound_order_master_id]
											,[wh_item_master_id]
											,[line_number]
											,[quantity_order]
											,[item_uom_id]
											,[item_status]
											,[default_item_status]
											,[price]
											,[grade]
											,[over_receipt_allowed]
											,[lot_number]
											,[expiry_date]
											,[serial_number]
											,[attribute1]
											,[attribute2]
											,[attribute3]
											,[attribute4]
											,[attribute5]
											,[item_master_id]
											,[item_number]
											,[uom]
											,[create_by]
											,[create_date])
										VALUES
											(@v_vchInboundMasterID			
											,@v_vchWhItemGUID
											,@v_vchIBLineNumber
											,ROUND(@v_fltQuantityShip,@Round)
											,@v_vchItemUOMID
											,'NEW' 
											,@v_vchDefaultItemStatus
											,@v_vchPrice
											,@v_vchGrade
											,'NO'
											,@v_vchLotNumber
											,@v_vchExpiryDate
											,@v_vchSerialNumber
											,@v_vchAttribute1
											,@v_vchAttribute2
											,@v_vchAttribute3
											,@v_vchAttribute4
											,@v_vchAttribute5
											,@v_vchItemGUID
											,@v_vchIBItemNumber
											,@v_vchIBUom
											,@in_vchUserID
											,GETDATE())
							END

						---------------------------------------------------
						-- Modern Trade : Insert into t_wms_shelf_life_tran
						---------------------------------------------------
						IF EXISTS(SELECT TOP 1 control_shelf_life FROM t_wms_customer WHERE customer_id = @v_vchCustomerID AND ISNULL(control_no_back_date,'NO') = 'YES')
							BEGIN
								IF NOT EXISTS(SELECT shelf_life_id FROM t_wms_shelf_life_tran WHERE customer_id = @v_vchCustomerID AND owner_id = @v_vchOwnerID AND item_master_id = @v_vchItemMasterID AND last_expiry_date_shipped = @v_vchExpiryDate)
									BEGIN
										INSERT INTO t_wms_shelf_life_tran(customer_id, item_master_id, owner_id, last_expiry_date_shipped, create_by)
										VALUES(@v_vchCustomerID,@v_vchItemMasterID,@v_vchOwnerID,@v_vchExpiryDate,@in_vchUserID)
									END
							END

					FETCH NEXT FROM OutboundPickDetail_CURSOR INTO @v_vchOutboundOrderDetailID,@v_vchOutboundPickDetailID,@v_vchOutboundPackDetailID,@v_vchLineNumber,@v_vchLocationMasterID,@v_vchLocationForPick,@v_vchLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
															,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityShip,@v_vchItemUOMID,@v_vchUOM,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
															,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control,@v_dtReceiveDate,@v_vchERPLocationForPick,@v_vchZone
							
					END

				--ถ้ามีรายการที่ qty order <> qty_stg แสดงว่ายัง pick ไม่ครบ แต่ถ้าครบแล้วแสดงว่าเป็นการ ship ครั้งสุดท้าย
				IF NOT EXISTS (SELECT outbound_order_detail_id FROM  t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_pick,0) < ISNULL(quantity_order,0))
					BEGIN
						UPDATE t_wms_outbound_pick_master SET pick_list_status = 'SHIP' WHERE outbound_order_master_id = @in_vchOutboundMasterID
						UPDATE t_wms_outbound_master SET ship_date_actual = @v_dtShipDateActual, order_status = 'SHIP' WHERE outbound_order_master_id = @in_vchOutboundMasterID
					END 
			END
		ELSE
			BEGIN
				SET @out_ErrorCode = '999';
				SET @out_ErrorMessage = 'Not found data for ship';
				GOTO WRITE_PROC;
			END
		
		CLOSE OutboundPickDetail_CURSOR;  
		DEALLOCATE OutboundPickDetail_CURSOR;

		-----------------------------------------------
		--Insert Bom Quantity Ship
		-----------------------------------------------
		EXEC usp_wms_calculate_outbound_bom @in_vchWhMasterID	    = @v_vchWhMasterID
											,@in_vchOwnerID		    = @v_vchOwnerID
											,@in_vchOutboundMasterID = @in_vchOutboundMasterID
											,@in_vchUserID			= @in_vchUserID
											,@out_ErrorCode			= @out_ErrorCode OUTPUT
											,@out_ErrorMessage		= @out_ErrorMessage OUTPUT
		IF (@out_ErrorCode <> '0')
			BEGIN 
				GOTO WRITE_PROC; 
			END

		-----------------------------------------------
		--Insert POD
		-----------------------------------------------
		IF (@RulePOD = 'YES')
		BEGIN
			INSERT INTO [dbo].[t_wms_pod]
				([outbound_order_master_id]
				,[route_code]
				,[route_name]
				,[order_status]
				,[pod_date_plan]
				,[create_by]
				,[create_date])
			VALUES
				(@in_vchOutboundMasterID
				,@v_vchRouteCode
				,@v_vchRouteName
				,'PENDING'
				,@v_dtShipDateActual
				,@in_vchUserID
				,GETDATE())
		END
	
			
		--For Interface
		IF @v_vchMoveSubTranType = 'MOVE_ON_PC'
			BEGIN
				UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		--Update Host Shipment = PENDING
		IF (@v_vchTranType = 'BLIND_PICK' AND @v_vchSubTranType = 'CONFIRM_TO_ERP')
			BEGIN
				UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END
		ELSE IF @v_vchTranType IN ('OO_SHIP','OO_SHIP_CONSIGNMENT','OO_PARTIAL_SHIP') AND @v_vchSubTranType IN ('CONFIRM_TO_ERP')
			BEGIN
				UPDATE t_host_wms_ship_conf_detail_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
				UPDATE t_host_wms_ship_conf_header_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
	    RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;

			IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
				BEGIN
					CLOSE OutboundPickDetail_CURSOR;
					DEALLOCATE OutboundPickDetail_CURSOR;
				END 
							 
			SET @v_dtProcessDateTime = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchOutboundOrderNumber,
				@in_vchData2 = NULL,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END
		   
	END TRY
	BEGIN CATCH
	
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
			BEGIN
				CLOSE OutboundPickDetail_CURSOR;
				DEALLOCATE OutboundPickDetail_CURSOR;
			END
								
		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END 

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH   
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_partial_ship_confirm_by_load_id]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_partial_ship_confirm_by_load_id]  
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(25),  
	@in_vchLoadID			NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
	
	DECLARE @c_vchObjName			NVARCHAR(50) = 'usp_outbound_partial_ship_confirm_by_load_id' 
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchOrderNumber		NVARCHAR(50)
	DECLARE @v_vchWarehouse			NVARCHAR(25) 
	SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
 
	BEGIN TRY  
		SELECT outbound_order_master_id
			,outbound_order_number
			,order_type
			,order_status
		INTO #tAllOutboundLoad
		FROM t_wms_outbound_master
		WHERE wh_master_id = @in_vchWhMasterID
		AND load_id = @in_vchLoadID

		-------------------------------------------
		--CONFIRM SHIP BY LOAD ID
		-------------------------------------------
		DECLARE Outbound_Cursor CURSOR FOR 
			SELECT outbound_order_master_id
				,outbound_order_number
			FROM #tAllOutboundLoad
			WHERE order_status NOT IN ('SHIP','CLOSE')
			ORDER BY outbound_order_number
		OPEN Outbound_Cursor 
		FETCH NEXT FROM Outbound_Cursor INTO @v_vchOutboundMasterID ,@v_vchOrderNumber
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
			-----------------------------------------
			--SHIP LOAD BY ORDER
			-----------------------------------------
			EXEC usp_outbound_partial_ship_confirm @in_vchApplicationID			= @in_vchApplicationID
													, @in_vchOutboundMasterID	= @v_vchOutboundMasterID
													, @in_vchDeviceID			= @in_vchDeviceID
													, @in_vchUserID				= @in_vchUserID
													, @out_ErrorCode			= @out_ErrorCode OUTPUT
													, @out_ErrorMessage			= @out_ErrorMessage OUTPUT		   
			IF (@out_ErrorCode <> '0')
			BEGIN 
				GOTO WRITE_PROC; 
			END

			FETCH NEXT FROM Outbound_Cursor INTO @v_vchOutboundMasterID ,@v_vchOrderNumber 
		END
		CLOSE Outbound_Cursor                  	
		DEALLOCATE Outbound_Cursor
		 
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
	    IF OBJECT_ID('tempdb..#tAllOutboundLoad') IS NOT NULL
			DROP TABLE #tAllOutboundLoad
		RETURN;

		-------------------------------------------
		-- Write process log
		-------------------------------------------
		BEGIN
			WRITE_PROC:	
				IF CURSOR_STATUS('global','Outbound_Cursor')>=-1
					BEGIN
						CLOSE Outbound_Cursor;
						DEALLOCATE Outbound_Cursor;
					END
				SET @v_dtProcessDateTime = GETDATE(); 
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @in_vchLoadID,
					@in_vchData2 = @v_vchOrderNumber,
					@in_vchData3 = NULL,
					@in_vchData4 = NULL,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END
		   
	END TRY
	BEGIN CATCH 	
		IF CURSOR_STATUS('global','Outbound_Cursor')>=-1
			BEGIN
				CLOSE Outbound_Cursor;
				DEALLOCATE Outbound_Cursor;
			END			
		IF (ISNULL(@out_ErrorCode,'') = '' or ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = @v_vchOrderNumber,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH   
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_pick_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_pick_confirm]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchOutboundPickData		NVARCHAR(MAX),
	@in_vchToLocationID			UNIQUEIDENTIFIER,
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_pick_confirm]', -- The name that uniquely tags this object.
		@v_vchApplicationName		NVARCHAR(50)= NULL,
		@v_dtProcessDateTime		DATETIME,
		@Round						INT,
		@DocHandle					INT,
		@v_vchBeginTrans			BIT = 0,
		@v_vchInventoryType			NVARCHAR(25) = 'INVENTORY',
		@v_dtStartDate				DATETIME,
		@RuleOverPick				NVARCHAR(3) = 'NO',

		@v_vchWhMasterID			UNIQUEIDENTIFIER,
		@v_vchWarehouse				NVARCHAR(25),
		@v_vchToLocation			NVARCHAR(50),
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchOwnerID			    UNIQUEIDENTIFIER,
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOrderStatus			NVARCHAR(30) = NULL,
		@v_vchOrderType				NVARCHAR(30) = NULL,

		@v_vchOutboundDetailID		UNIQUEIDENTIFIER,
		@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER,
		@v_vchLocationID			UNIQUEIDENTIFIER,
		@v_vchLocation				NVARCHAR(50),
		@v_vchLineNumber			NVARCHAR(10),
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
		@v_vchItemMasterID			UNIQUEIDENTIFIER,
		@v_vchItemNumber			NVARCHAR(50),
		@v_fltQtyPlan				FLOAT,
		@v_fltQtyConfirmPick		FLOAT,
		@v_vchUom					NVARCHAR(20),
		@v_vchUomPrompt				NVARCHAR(40),
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchexpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(50),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchReceiveDate			VARCHAR(10),
		@v_vchDefaultItemStatus		NVARCHAR(40),

		@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
		@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
		@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
		@v_fltInvQuantity			FLOAT,
		@v_dtMfgDate				DATE,
		
		@v_vchItemUOMID				UNIQUEIDENTIFIER = NULL,
		@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
		@v_vchBaseUom				NVARCHAR(20),
		@v_vchBaseUomPrompt			NVARCHAR(40),
		@v_vchIsPrimaryUOM			NVARCHAR(5),
		@v_fltConversionFactor		FLOAT,
		@v_fltBaseInputQuantity		FLOAT,
		@v_fltWidth					FLOAT = 0,  --item Uom
		@v_fltLength				FLOAT = 0,  --item Uom
		@v_fltHeight				FLOAT = 0,  --item Uom
		@v_fltGrossWeight			FLOAT = 0,  --item Uom
		@v_intPercentTolerance		FLOAT = 0,  --item Uom
		@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
		@v_fltVolumn				FLOAT = 0,	--item Uom
		@v_fltTotalWeight			FLOAT = 0,	--item Uom

		@v_vchLotControl			NVARCHAR(10),
		@v_vchExpiryDateControl		NVARCHAR(10),
		@v_vchSNControl				NVARCHAR(10),
		@v_vchAttribute1Control		NVARCHAR(10),
		@v_vchAttribute2Control		NVARCHAR(10),
		@v_vchAttribute3Control		NVARCHAR(10),
		@v_vchAttribute4Control		NVARCHAR(10),
		@v_vchAttribute5Control		NVARCHAR(10),

		@v_vchBoxNumber				NVARCHAR(25),
		@v_vchOldItemNumber			NVARCHAR(50)

	BEGIN TRY
		EXEC sp_xml_preparedocument @DocHandle OUTPUT,@in_vchOutboundPickData
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RuleOverPick = value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_PICK' AND is_active = 'YES'
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
		SET @v_dtStartDate = GETDATE()
		
		--Get Order and Warehouse
		SELECT @v_vchOutboundOrderNumber = obMS.outbound_order_number 
			,@v_vchWhMasterID = obMS.wh_master_id
			,@v_vchWarehouse = obMS.wh_id
			,@v_vchOwnerID = obMS.owner_id
			,@v_vchOwnerCode = own.owner_code
			,@v_vchOrderType = obMS.order_type
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID 
		
		--Get STG ID
		SELECT TOP 1 @v_vchToLocation = location FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location_id = @in_vchToLocationID AND is_active = 'YES'
		 
		DECLARE @v_vchOldStgLocationID  UNIQUEIDENTIFIER = NULL
		SELECT TOP 1 @v_vchOldStgLocationID = pickDT.staging_location_id 
		FROM t_wms_outbound_pick_detail pickDT
		INNER JOIN t_wms_outbound_pick_master pickMS ON pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
		WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
		AND (pickDT.staging_location_id <> @in_vchToLocationID AND pickDT.staging_location_id IS NOT NULL)

		IF @v_vchOldStgLocationID IS NOT NULL
			BEGIN-- 1 OUTBOUND ORDER 1 STAGING LOCATION
				IF (@v_vchOldStgLocationID <> @in_vchToLocationID)
					BEGIN 
						SET @out_ErrorCode = '999';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PICK_TO_OLD_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchToLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		IF @RuleOverPick = 'YES' AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_OVER_PICK' AND is_active = 'YES')
		BEGIN
			SET @RuleOverPick = 'NO'
		END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;

			DECLARE OutboundPickCursor SCROLL CURSOR FOR
				SELECT outbound_order_detail_id
					,outbound_pick_detail_id
					,location_id
					,location
					,line_number
					,wh_item_master_id
					,item_master_id
					,item_number
					,quantity_plan
					,quantity_confirm_pick
					,uom_prompt
					,parent_lpn
					,lpn
					,lot_number
					,[expiry_date]
					,serial_number
					,attribute1
					,attribute2
					,attribute3
					,attribute4
					,attribute5
					,receive_date
					,default_item_status
				FROM OpenXML(@DocHandle,'ConfirmPick/ConfirmPick',2)
				WITH(outbound_order_detail_id	UNIQUEIDENTIFIER
					,outbound_pick_detail_id	UNIQUEIDENTIFIER
					,location_id				UNIQUEIDENTIFIER
					,location					NVARCHAR(50)
					,line_number				NVARCHAR(10)
					,wh_item_master_id			UNIQUEIDENTIFIER
					,item_master_id				UNIQUEIDENTIFIER
					,item_number				NVARCHAR(50)
					,quantity_plan				FLOAT
					,quantity_confirm_pick		FLOAT
					,uom_prompt					NVARCHAR(40)
					,parent_lpn					NVARCHAR(25)
					,lpn						NVARCHAR(25)
					,lot_number					NVARCHAR(50)
					,[expiry_date]				NVARCHAR(8)
					,serial_number				NVARCHAR(50)
					,attribute1					NVARCHAR(100)
					,attribute2					NVARCHAR(100)
					,attribute3					NVARCHAR(100)
					,attribute4					NVARCHAR(100)
					,attribute5					NVARCHAR(100)
					,receive_date				VARCHAR(30)
					,default_item_status		NVARCHAR(40))
			OPEN OutboundPickCursor;
			FETCH OutboundPickCursor INTO @v_vchOutboundDetailID
											   ,@v_vchOutboundPickDetailID	
											   ,@v_vchLocationID			
											   ,@v_vchLocation				
											   ,@v_vchLineNumber			
											   ,@v_vchWhItemMasterID		
											   ,@v_vchItemMasterID			
											   ,@v_vchItemNumber			
											   ,@v_fltQtyPlan				
											   ,@v_fltQtyConfirmPick		
											   ,@v_vchUomPrompt				
											   ,@v_vchParentLPN				
											   ,@v_vchLPN					
											   ,@v_vchLotNumber				
											   ,@v_vchexpiryDate			
											   ,@v_vchSerialNumber			
											   ,@v_vchAttribute1			
											   ,@v_vchAttribute2			
											   ,@v_vchAttribute3			
											   ,@v_vchAttribute4			
											   ,@v_vchAttribute5			
											   ,@v_vchReceiveDate			
											   ,@v_vchDefaultItemStatus		
			EXEC sp_xml_removedocument @DocHandle;

				WHILE @@FETCH_STATUS = 0
					BEGIN
						SET @v_fltQtyConfirmPick = ROUND(@v_fltQtyConfirmPick,@Round)

						IF (@v_fltQtyConfirmPick > 0)
							BEGIN
								DECLARE @v_dtReceiveDate DATE 
								SET @v_dtReceiveDate = CONVERT(DATE,@v_vchReceiveDate)
								--Check Item
								IF @v_vchItemNumber <> @v_vchOldItemNumber OR ISNULL(@v_vchOldItemNumber,'') = ''
									BEGIN
										BEGIN --Clear Value
											SET @v_vchItemUOMID = NULL
											SET @v_vchLotControl = NULL
											SET @v_vchExpiryDateControl = NULL
											SET @v_vchSNControl = NULL
											SET @v_vchAttribute1Control = NULL
											SET @v_vchAttribute2Control = NULL
											SET @v_vchAttribute3Control = NULL
											SET @v_vchAttribute4Control = NULL
											SET @v_vchAttribute5Control = NULL
											SET @v_vchIsPrimaryUOM = NULL
											SET @v_fltConversionFactor = NULL
											SET @v_fltWidth = NULL
											SET @v_fltLength = NULL
											SET @v_fltHeight = NULL
											SET @v_fltGrossWeight = NULL
											SET @v_intPercentTolerance = NULL
											SET @v_intPercenToleranceWeight = NULL
										END

										SELECT @v_vchItemMasterID = it.item_master_id
											,@v_vchLotControl = it.lot_control
											,@v_vchExpiryDateControl = it.expiry_date_control
											,@v_vchSNControl = it.sn_control
											,@v_vchAttribute1Control = it.attribute1_control
											,@v_vchAttribute2Control = it.attribute2_control
											,@v_vchAttribute3Control = it.attribute3_control
											,@v_vchAttribute4Control = it.attribute4_control
											,@v_vchAttribute5Control = it.attribute5_control
											,@v_vchItemUOMID = uom.item_uom_id
											,@v_vchUom = uom.uom
											,@v_fltConversionFactor = uom.conversion_factor
											,@v_vchIsPrimaryUOM = uom.primary_uom
											,@v_fltWidth = ISNULL(uom.width,0)
											,@v_fltLength = ISNULL(uom.length,0)
											,@v_fltHeight = ISNULL(uom.height,0)
											,@v_fltGrossWeight = ISNULL(uom.gross_weight,0)
											,@v_intPercentTolerance = ISNULL(uom.percent_tolerance,0)
											,@v_intPercenToleranceWeight = ISNULL(uom.percent_tolerance_weight,0)
										FROM t_wms_item it 
										INNER JOIN t_wms_item_uom uom on it.item_master_id = uom.item_master_id 
										WHERE it.item_master_id = @v_vchItemMasterID
										AND it.owner_id = @v_vchOwnerID
										AND uom.uom_prompt = @v_vchUOMPrompt
										IF (@v_vchItemMasterID IS NULL)
											BEGIN
												SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND';
												SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC;
											END

										--------------------------------------------------
										--Check Item UOM
										--------------------------------------------------			
										IF (@v_vchItemUomID IS NULL)
											BEGIN
												SET @out_ErrorCode = '107';
												SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchUOMPrompt,'@param2','@param3','@param4','@param5')
												GOTO WRITE_PROC
											End

										--------------------------------------------------
										--Get Primary Uom
										--------------------------------------------------
										IF @v_vchIsPrimaryUOM = 'NO'
											BEGIN
												SELECT @v_vchBaseItemUomID = item_uom_id
													,@v_vchBaseUomPrompt = uom_prompt
													,@v_vchBaseUom	= uom
													,@v_fltConversionFactor = conversion_factor
													,@v_fltWidth = ISNULL(width,0)
													,@v_fltLength = ISNULL(length,0)
													,@v_fltHeight = ISNULL(height,0)
													,@v_fltGrossWeight = ISNULL(gross_weight,0)
													,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
													,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
												FROM t_wms_item_uom 
												WHERE item_master_id = @v_vchItemMasterID 
												AND primary_uom = 'YES' 
												AND is_active = 'YES'
											END
										ELSE	
											BEGIN
												SET @v_vchBaseItemUomID = @v_vchItemUomID
												SET @v_vchBaseUomPrompt = @v_vchUOMPrompt
												SET @v_vchBaseUom = @v_vchUom
											END
									END 

								--Check Wh Item Master ID
								IF (@v_vchWhItemMasterID IS NULL)
									BEGIN
										SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
								
								--------------------------------------------------
								--Set Input Base Qty 
								--------------------------------------------------
								SET @v_fltBaseInputQuantity = ROUND(@v_fltQtyConfirmPick * @v_fltConversionFactor,@Round);
								
								--Check Quatity
								DECLARE @v_fltChkQtyPick		FLOAT = 0
								DECLARE @v_fltChkQtyPlan		FLOAT = 0
								DECLARE @v_fltDiffQtyOverPick	FLOAT = 0
								 
								--ถ้า Pick + qty > plan = error
								SELECT @v_fltChkQtyPick = ISNULL(quantity_pick ,0)
									, @v_fltChkQtyPlan = ISNULL(quantity_plan,0)
								FROM t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

								IF (ROUND(@v_fltChkQtyPick + @v_fltQtyConfirmPick,@Round)) > @v_fltChkQtyPlan AND @RuleOverPick = 'NO'
									BEGIN
										SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN';
										SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,@v_vchItemNumber,@v_vchLPN,'@param4','@param5')
										GOTO WRITE_PROC;
									END
								
								-- ถ้ากำหนด over pick ให้หายอด diff ของส่วนที่หยิบเกิน เพื่อไว้ pick ให้กับ row สุดท้ายของ pick detail และยอดที่หยิบ มากกว่า ยอดคงเหลือ ถึงจะถือว่ามันหยิบเกินจริงๆ
								IF @RuleOverPick = 'YES' AND ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltChkQtyPlan - @v_fltChkQtyPick,@Round)
									BEGIN
										SET @v_fltDiffQtyOverPick = ROUND(@v_fltBaseInputQuantity,@Round) - ROUND(@v_fltChkQtyPlan - @v_fltChkQtyPick,@Round)
									END

								--หา LPN ปลายทาง
								--กรณีที่ไม่ได้ control LPN ก็จะให้ STG LPN = order 
								IF ISNULL(@v_vchLPN,'') <> ''
									BEGIN
										IF ((SELECT SUM(quantity) FROM t_wms_inventory WHERE wh_master_id = @v_vchWhMasterID AND location_id = @v_vchLocationID AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')) = @v_fltBaseInputQuantity)
											BEGIN-- ย้ายทั้งกล่อง
												SET @v_vchBoxNumber = @v_vchLPN;
											END
										ELSE 
											BEGIN
												SET @v_vchBoxNumber = @v_vchOutboundOrderNumber
											END
									END
								ELSE
									BEGIN
										SET @v_vchBoxNumber = @v_vchOutboundOrderNumber
									END

								--------------------------------------------------
								--Manage Source Location
								--------------------------------------------------
								SET @v_vchInventoryID = NULL;
								SET @v_vchAttributeGroupID = NULL;
								SET @v_fltInvQuantity = 0;
								SET @v_dtMfgDate = NULL
								SELECT @v_vchInventoryID = inventory_id
									,@v_vchAttributeGroupID = attribute_group_id
									,@v_fltInvQuantity = quantity
									,@v_vchInvStatusID = inventory_status_id
									,@v_dtMfgDate = mfg_date
								FROM v_wms_inventory_data_by_serial_mini
								WHERE wh_master_id = @v_vchWhMasterID 
								AND wh_item_master_id = @v_vchWhItemMasterID 
								AND location_id = @v_vchLocationID
								AND inv_status = @v_vchDefaultItemStatus
								AND receive_date = @v_dtReceiveDate
								AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'') 
								AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
								AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
								AND ISNULL([expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
								AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
								AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
								AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
								AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
								AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
								AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
								
								IF (@v_vchInventoryID IS NULL)
									BEGIN
										SET @out_ErrorCode = 'CANNOT_PICK_ITEM';
										SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchLocation,@v_vchItemNumber,@v_vchLPN,'@param4','@param5')
										GOTO WRITE_PROC;
									END

								IF ROUND(ISNULL(@v_fltInvQuantity,0),@Round) < ROUND(ISNULL(@v_fltBaseInputQuantity,0),@Round)
									BEGIN
										-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
										SET @out_ErrorCode = 'INV_QUANTITY_NOT_ENOUGH'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,'@param4','@param5')			
										GOTO WRITE_PROC;
									END
					
								---------------------------------------------------
								--Calculate Volumn & Weight
								---------------------------------------------------
								IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
									BEGIN
										SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltBaseInputQuantity,2)
										SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltBaseInputQuantity,2)
									END

								---------------------------------------------------
								-- Manage source location data
								---------------------------------------------------
								BEGIN
									--Update Volumn & Weight in from location
									IF @v_vchLocationID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
												, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @v_vchLocationID
										END
									
									--ถ้าหยิบเกิน ตัดยอดจอง เท่ากับยอดที่จองจริง ค่า qty allocate จะได้ไม่ติดลบ
									UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltBaseInputQuantity,@Round),@Round)
										,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - ROUND(@v_fltBaseInputQuantity - ISNULL(@v_fltDiffQtyOverPick,0),@Round),@Round)
										,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
										,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
									WHERE inventory_id = @v_vchInventoryID 
									AND attribute_group_id = @v_vchAttributeGroupID

									IF (@v_vchSNControl = 'FULL')
										BEGIN
											UPDATE t_wms_inventory_attribute SET  quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltBaseInputQuantity,@Round),@Round) 
											WHERE inventory_id = @v_vchInventoryID 
											AND attribute_group_id = @v_vchAttributeGroupID 
											AND attribute_value = @v_vchSerialNumber
											AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
										END

									IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
										BEGIN
											UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - ROUND(@v_fltBaseInputQuantity,@Round),@Round)
												,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - ROUND(@v_fltBaseInputQuantity - ISNULL(@v_fltDiffQtyOverPick,0),@Round),@Round)
											WHERE inventory_id = @v_vchInventoryID 
											AND attribute_group_id = @v_vchAttributeGroupID
											AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
										END
								END
							
								------------------------------------------------
								-- Clear Inventory ที่หยิบของหมดแล้ว
								------------------------------------------------
								DELETE FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchInventoryID AND quantity <= 0
								DELETE FROM t_wms_inventory WHERE inventory_id = @v_vchInventoryID AND quantity <= 0 

								---------------------------------------------------
								-- Manage destination location data
								---------------------------------------------------
								BEGIN
									SET @v_vchInventoryID = null;
									SET @v_vchAttributeGroupID = null;
									
									SELECT @v_vchInventoryID = inventory_id
										,@v_vchAttributeGroupID = attribute_group_id
									FROM v_wms_inventory_data_mini
									WHERE wh_master_id = @v_vchWhMasterID
									AND owner_id = @v_vchOwnerID
									AND location_id = @in_vchToLocationID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND inv_status = @v_vchDefaultItemStatus
									AND receive_date = @v_dtReceiveDate
									AND ISNULL(parent_lpn,'') = ISNULL(NULL,'')
									AND ISNULL(lpn,'') = ISNULL(@v_vchBoxNumber,'')
									AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
									AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

									EXEC usp_manage_inventory @in_vchWhMasterID			= @v_vchWhMasterID
															, @in_vchOwnerID			= @v_vchOwnerID
															, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
															, @in_vchLocationID			= @in_vchToLocationID
															, @in_vchStatusID			= @v_vchInvStatusID
															, @in_vchPalentLPN			= NULL
															, @in_vchLPN				= @v_vchBoxNumber
															, @in_fltQty				= @v_fltBaseInputQuantity
															, @in_fltQtyAllocate		= 0
															, @in_fltQtyIncoming		= 0
															, @in_vchInventoryType		= @v_vchOutboundOrderNumber
															, @in_vchUserID				= @in_vchUserID
															, @in_vchReceiveDate		= @v_dtReceiveDate
															, @in_dtMFGDate				= @v_dtMfgDate
															, @in_vchInventoryID		= @v_vchInventoryID OUTPUT
															, @in_vchAttributeGroupID	= @v_vchAttributeGroupID OUTPUT	
															, @in_vchErrorCode			= @out_ErrorCode OUTPUT
															, @in_vchMessage			= @out_ErrorMessage OUTPUT	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;

									--Update Volumn & Weight in from location
									IF @in_vchToLocationID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
												, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @in_vchToLocationID
										END
										
									--update volumn & weight ของ LPN
									UPDATE t_wms_inventory SET 
										 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
										,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
									WHERE inventory_id = @v_vchInventoryID
									AND attribute_group_id = @v_vchAttributeGroupID	

									IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
										BEGIN
											EXEC usp_manage_inventory_attribute 
												  @in_vchLot				= @v_vchLotNumber
												, @in_vchExpiryDate			= @v_vchExpiryDate
												, @in_vchSerialNo			= @v_vchSerialNumber
												, @in_vchAttribute1			= @v_vchAttribute1
												, @in_vchAttribute2			= @v_vchAttribute2
												, @in_vchAttribute3			= @v_vchAttribute3
												, @in_vchAttribute4			= @v_vchAttribute4
												, @in_vchAttribute5			= @v_vchAttribute5
												, @in_fltQty				= @v_fltBaseInputQuantity
												, @in_fltQtyAllocate		= 0
												, @in_fltQtyIncoming		= 0
												, @in_vchInventoryID		= @v_vchInventoryID
												, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
												, @in_vchLotControl			= @v_vchLotControl
												, @in_vchSNControl			= @v_vchSNControl
												, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
												, @in_vchAttribute1Control	= @v_vchAttribute1Control
												, @in_vchAttribute2Control	= @v_vchAttribute2Control
												, @in_vchAttribute3Control	= @v_vchAttribute3Control
												, @in_vchAttribute4Control	= @v_vchAttribute4Control
												, @in_vchAttribute5Control	= @v_vchAttribute5Control
												, @in_vchUserID				= @in_vchUserID
												, @in_vchErrorCode			= @out_ErrorCode OUTPUT
												, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
											IF(@out_ErrorCode <> '0')
												GOTO WRITE_PROC;
										END	
								END
 
								INSERT INTO t_com_tran_log
									( [app_id]
									, [tran_type]
									, [sub_tran_type]
									, [app_name]
									, [description]
									, [start_tran_datetime]
									, [end_tran_datetime]
									, [warehouse]
									, [to_warehouse]
									, [location]
									, [to_location]
									, [owner]
									, [to_owner]
									, [item_number]
									, [quantity]
									, [quantity_uom]
									, [after_quantity]
									, [after_quantity_uom]
									, [lot_number]
									, [after_lot_number]
									, [expiry_date]
									, [after_expiry_date]
									, [serial_number]
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, [parent_lpn]
									, [after_parent_lpn]
									, [lpn]
									, [after_lpn]
									, [status]
									, [after_status]
									, [order_number]
									, [line_number]
									, [device]
									, [create_by]
									, [create_date]
									, [pick_location]
									, [receive_date]
									, [mfg_date]
									, [input_quantity]
									, [input_uom]
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'MOVE_DEST'
									, @v_vchApplicationName
									, 'Update pick PC to staging.'
									, @v_dtStartDate
									, DATEADD(millisecond,2,GETDATE())
									, @v_vchWarehouse
									, @v_vchWarehouse
									, @v_vchLocation
									, @v_vchToLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @v_vchItemNumber
									, @v_fltBaseInputQuantity
									, @v_vchBaseUom
									, @v_fltInvQuantity - @v_fltBaseInputQuantity
									, @v_vchBaseUom
									, @v_vchLotNumber
									, @v_vchLotNumber
									, @v_vchExpiryDate
									, @v_vchExpiryDate
									, @v_vchSerialNumber
									, @v_vchAttribute1
									, @v_vchAttribute1
									, @v_vchAttribute2
									, @v_vchAttribute2
									, @v_vchAttribute3
									, @v_vchAttribute3
									, @v_vchAttribute4
									, @v_vchAttribute4
									, @v_vchAttribute5
									, @v_vchAttribute5
									, @in_vchUserID
									, @v_vchParentLPN
									, NULL
									, @v_vchLPN
									, @v_vchBoxNumber
									, @v_vchDefaultItemStatus
									, @v_vchDefaultItemStatus 
									, @v_vchOutboundOrderNumber
									, @v_vchLineNumber
									, @in_vchDeviceID
									, @in_vchUserID
									, DATEADD(millisecond,2,GETDATE())
									, @v_vchLocation
									, @v_dtReceiveDate
									, @v_dtMfgDate
									, @v_fltQtyConfirmPick
									, @v_vchUomPrompt
								)								
															
								UPDATE t_wms_outbound_detail SET 
									item_status = 'PICK'
									,quantity_pick = ROUND(ISNULL(quantity_pick,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round)
									,quantity_stage = ROUND(ISNULL(quantity_stage,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round) 
								WHERE outbound_order_detail_id = @v_vchOutboundDetailID
								
								UPDATE t_wms_outbound_pick_detail
								SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round)
									,quantity_stage = ROUND(ISNULL(quantity_stage,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round)
									,quantity_comfirm_pick_pc = ROUND(ISNULL(quantity_plan,0) - ISNULL(quantity_pick,0),@Round) - ROUND(@v_fltBaseInputQuantity,@Round)
									,staging_location_id = @in_vchToLocationID  
									,staging_parent_lpn = NULL
									,staging_lpn = @v_vchBoxNumber
									,pick_status = 'YES'
									,pick_to_lpn = @v_vchBoxNumber
									,pick_location_id = @in_vchToLocationID
									,serial_number = CASE WHEN ISNULL(@v_vchSerialNumber,'') <> '' THEN @v_vchSerialNumber ELSE NULL END
								WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
								
								IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES') = 'YES')
									BEGIN
										UPDATE t_wms_outbound_pick_detail SET 
											  quantity_pack = ROUND(ISNULL(quantity_pack,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round) 
											, end_date_time = GETDATE()
										WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

										IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
												 WHERE outbound_order_master_id = @in_vchOutboundMasterID 
												  AND pack_location_id = @in_vchToLocationID
												  AND lpn_pack = @v_vchBoxNumber 
												  AND wh_item_master_id = @v_vchWhItemMasterID 
												  AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
												  AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,''))
											BEGIN
												UPDATE t_wms_outbound_pack_detail SET 
													 quantity_pack = ROUND(ISNULL(quantity_pack,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round)
													,quantity_stage = ROUND(ISNULL(quantity_stage,0) + ROUND(@v_fltBaseInputQuantity,@Round),@Round)
												WHERE outbound_order_master_id = @in_vchOutboundMasterID 
												AND pack_location_id = @in_vchToLocationID
												AND lpn_pack = @v_vchBoxNumber 
												AND wh_item_master_id = @v_vchWhItemMasterID 
												AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
												AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
											END
										ELSE
											BEGIN
												INSERT INTO t_wms_outbound_pack_detail(outbound_order_master_id
													, outbound_pick_detail_id
													, staging_location_id
													, staging_parent_lpn
													, staging_lpn
													, lpn_pack
													, pack_location_id
													, wh_item_master_id
													, quantity_pack
													, quantity_stage
													, lot_number 
													, expiry_date
													, serial_number
													, [attribute1]
													, [attribute2]
													, [attribute3]
													, [attribute4]
													, [attribute5]
													, item_uom_id
													, create_by)
												VALUES(@in_vchOutboundMasterID
													,@v_vchOutboundPickDetailID
													,@in_vchToLocationID
													,NULL
													,@v_vchBoxNumber
													,@v_vchBoxNumber
													,@in_vchToLocationID
													,@v_vchWhItemMasterID
													,ROUND(@v_fltBaseInputQuantity,@Round)
													,ROUND(@v_fltBaseInputQuantity,@Round)
													,@v_vchLotNumber
													,@v_vchExpiryDate
													,@v_vchSerialNumber
													,@v_vchAttribute1
													,@v_vchAttribute2
													,@v_vchAttribute3
													,@v_vchAttribute4
													,@v_vchAttribute5
													,@v_vchItemUOMID
													,@in_vchUserID)
											END
									END

								-- For Dashboard
								EXEC usp_wms_dashboard_transaction @in_vchProcess = 'OUT_IN'
																,@in_vchTransType	 = 'PICK'
																,@in_vchWhMasterID	 = @v_vchWhMasterID
																,@in_vchOwnerID		 = @v_vchOwnerID
																,@in_vchOwnerCode	 = @v_vchOwnerCode
																,@in_vchLocationID	 = @v_vchLocationID
																,@in_vchItemMasterID = @v_vchItemMasterID
																,@in_vchInvStatusID	 = @v_vchInvStatusID
																,@in_vchToWhMasterID = @v_vchWhMasterID
																,@in_vchToLocationID = @in_vchToLocationID
																,@in_vchToInvStatusID = @v_vchInvStatusID
																,@in_fltQuantity	 = @v_fltBaseInputQuantity
																,@in_vchUserID		 = @in_vchUserID
							END
						
						SET @v_vchOldItemNumber = @v_vchItemNumber;
						FETCH NEXT FROM OutboundPickCursor INTO @v_vchOutboundDetailID
											   ,@v_vchOutboundPickDetailID	
											   ,@v_vchLocationID			
											   ,@v_vchLocation				
											   ,@v_vchLineNumber			
											   ,@v_vchWhItemMasterID		
											   ,@v_vchItemMasterID			
											   ,@v_vchItemNumber			
											   ,@v_fltQtyPlan				
											   ,@v_fltQtyConfirmPick		
											   ,@v_vchUomPrompt				
											   ,@v_vchParentLPN				
											   ,@v_vchLPN					
											   ,@v_vchLotNumber				
											   ,@v_vchexpiryDate			
											   ,@v_vchSerialNumber			
											   ,@v_vchAttribute1			
											   ,@v_vchAttribute2			
											   ,@v_vchAttribute3			
											   ,@v_vchAttribute4			
											   ,@v_vchAttribute5			
											   ,@v_vchReceiveDate			
											   ,@v_vchDefaultItemStatus		
					END
		CLOSE OutboundPickCursor;
		DEALLOCATE OutboundPickCursor;
			
		UPDATE t_wms_outbound_pick_master SET pick_list_status = 'PICK' WHERE  outbound_order_master_id = @in_vchOutboundMasterID

		IF ((SELECT SUM(quantity_order - ISNULL(quantity_pick,0)) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID) = 0)
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @in_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
			END
		ELSE
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = 'PICK' WHERE outbound_order_master_id = @in_vchOutboundMasterID
			END

		COMMIT TRANSACTION;

		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;
		
		-------------------------------------------------
		-- Write process log
		-------------------------------------------------
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
			IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			
			IF CURSOR_STATUS('global','OutboundPickCursor')>=-1
			BEGIN
				CLOSE OutboundPickCursor;
				DEALLOCATE OutboundPickCursor;
			END

			SET @v_dtProcessDateTime = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchOutboundOrderNumber,
				@in_vchData2 = NULL,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
		END
		
	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans <> 0)
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','OutboundPickCursor')>=-1
			BEGIN
				CLOSE OutboundPickCursor;
				DEALLOCATE OutboundPickCursor;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' OR @out_ErrorCode = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = @out_ErrorCode,
			@in_vchData4 = @out_ErrorMessage,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH	
END
GO
