/****** Object:  StoredProcedure [dbo].[usp_outbound_pick_next_location_by_load]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2012-05-21
-- Description:	Check stock quantity
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_pick_next_location_by_load]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchLoadNumber		NVARCHAR(50),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItem				NVARCHAR(50) = null,
	@in_vchReasonCode		NVARCHAR(20) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchOutboundPickMasterID	NVARCHAR(40),
		@v_vchOutboundOrderDetailID	NVARCHAR(40),
		@v_vchWarehouseMasterID		NVARCHAR(40),
		@v_vchFLocationMasterID		NVARCHAR(40),
		@v_vchWarehouseItemMasterID	NVARCHAR(40),
		@v_vchItemMasterID			NVARCHAR(40),
		@v_vchYearRunning			NVARCHAR(25),
		@v_vchValuesRunning			NVARCHAR(50),
		@v_fltStockQty				FLOAT,
		
		@v_fltRemainPickQty			FLOAT,
		@v_dtProcessDateTime		DATETIME,
		@c_vchObjName				NVARCHAR(20),
		@v_vchData1					NVARCHAR(1000),
		@v_vchData2					NVARCHAR(1000),
		
		@v_vchOrderType				NVARCHAR(10),
		@v_vchAlloShortPick			NVARCHAR(3),
		@v_vchRuleCode				NVARCHAR(40),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(50),

		-- add new 2014-01-14
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchUOM					NVARCHAR(25),
		@v_vchDefaultItemStatus		NVARCHAR(25),
		@v_vchCustomerCode			NVARCHAR(50),
		@v_dtpShipDatePlan			DATETIME
		  
	set @out_ErrorCode = '0';
	set @out_ErrorMessage = 'NO';
	set @c_vchObjName = 'usp_outbound_pick_next_location';

	Begin Try	

			select	@v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
			select	@v_vchFLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchFromLocation
			
			select top 1 @v_vchOrderType = order_type,@v_vchOwnerID = t_wms_owner.owner_id,@v_vchOwnerCode = t_wms_owner.owner_code
			from t_wms_outbound_master inner join t_wms_owner on t_wms_outbound_master.owner_id = t_wms_owner.owner_id
			where load_id = @in_vchLoadNumber and wh_master_id = @v_vchWarehouseMasterID
			
			select	@v_vchItemMasterID = item_master_id,@v_vchSerialControl = sn_control 
			from t_wms_item inner join t_wms_owner on t_wms_item.owner_id = t_wms_owner.owner_id
			where	item_number = @in_vchItem and t_wms_item.owner_id = @v_vchOwnerID

			-- get inventory data
			If (@v_vchSerialControl = 'FULL')
				Begin
					declare cursorInventory cursor for
					select	wh_item_master_id,lot_number,expiry_date,serial_number,quantity
					from	v_wms_inventory_data_by_serial 
					where	wh_id = @in_vchWarehouse and location = @in_vchFromLocation and item_number = @in_vchItem and
							isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(lpn,'') = isnull(@in_vchLPN,'')
				End
			Else
				Begin
					declare cursorInventory cursor for
					select	wh_item_master_id,lot_number,expiry_date,serial_number,quantity
					from	v_wms_inventory_data
					where	wh_id = @in_vchWarehouse and location = @in_vchFromLocation 
							and item_number = @in_vchItem
							and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') 
							and isnull(lpn,'') = isnull(@in_vchLPN,'')
				End
			
			-- Create count plan
			If Exists(select * from t_wms_count_plan_master where count_status = 'OPEN' and count_generate_method = 'SYSTEM')
				Begin
					select top 1 @v_vchValuesRunning = count_master_id from t_wms_count_plan_master where count_status = 'OPEN' and count_generate_method = 'SYSTEM'
				End
			Else
				Begin
					select @v_vchYearRunning = value_member,@v_vchValuesRunning = display_member from t_com_combobox_item where group_name = 'running_count_id'
					If (@v_vchYearRunning = DATEPART(yyyy,getdate()))
						Begin
							set @v_vchValuesRunning = @v_vchYearRunning + '-' + RIGHT('0000' + (@v_vchValuesRunning + 1),5);
						End
					Else
						Begin
							update t_com_combobox_item
							set value_member = DATEPART(yyyy,getdate())
							where group_name = 'running_count_id'
							set @v_vchYearRunning = DATEPART(yyyy,getdate());
							set @v_vchValuesRunning = @v_vchYearRunning + '-' + RIGHT('0000' + (@v_vchValuesRunning + 1),5);
						End
					
					insert into t_wms_count_plan_master(wh_master_id, count_id, count_status, [description], count_generate_method, count_plan_type, create_by)
					values(@v_vchWarehouseMasterID,@v_vchValuesRunning,'OPEN','Create when click next location on picking process.','SYSTEM','CYCLE',@in_vchUserID)
				End
			
			Open cursorInventory
			Fetch from cursorInventory into @v_vchWarehouseItemMasterID,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_fltStockQty
			If (@@CURSOR_ROWS > 0)
				Begin
					While @@FETCH_STATUS = 0
						Begin
							insert into t_wms_count_plan_detail(count_master_id, wh_item_master_id, location_id,parent_lpn, lpn,lot,expiry_date,serial_number, stock_qty, create_by)
							values(@v_vchValuesRunning,@v_vchWarehouseItemMasterID,@v_vchFLocationMasterID,@in_vchParentLPN,@in_vchLPN,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_fltStockQty,@in_vchUserID)
							Fetch next from cursorInventory into @v_vchWarehouseItemMasterID,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_fltStockQty
						End
				End
			Else
				Begin
					select	@v_vchWarehouseItemMasterID = wh_item_master_id
					from	t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID

					insert into t_wms_count_plan_detail(count_master_id, wh_item_master_id, location_id, lpn, stock_qty, create_by)
					values(@v_vchValuesRunning,@v_vchWarehouseItemMasterID,@v_vchFLocationMasterID,@in_vchLPN,@v_fltStockQty,@in_vchUserID)
				End
			
			Close cursorInventory;
			Deallocate cursorInventory;

			Declare cursorOutboundDetail cursor for
				select	 outbound_order_detail_id, serial_number,
						 lot_number, expiry_date, quantity_order - quantity_pick,
						 uom_prompt, default_item_status, customer_code, ship_date_plan,outbound_order_number
				from	v_wms_outbound_detail
				where	wh_id = @in_vchWarehouse and load_id = @in_vchLoadNumber and item_number = @in_vchItem

			Open cursorOutboundDetail
			Fetch from cursorOutboundDetail Into @v_vchOutboundOrderDetailID,@v_vchSerialNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_fltRemainPickQty,
						@v_vchUOM,@v_vchDefaultItemStatus,@v_vchCustomerCode,@v_dtpShipDatePlan,@v_vchOutboundOrderNumber

			BEGIN TRANSACTION
				
				While @@FETCH_STATUS = 0

					Begin

						select @v_vchAlloShortPick = value from t_wms_rule where rule_code = 'RULE_SHORT_PICK_ORDER_TYPE_' + @v_vchOrderType

						select	@v_vchRuleCode = r.rule_code from t_wms_item_uom iu inner join t_wms_rule r on iu.picking_class = r.rule_id where iu.item_master_id = @v_vchItemMasterID
						If (@v_vchRuleCode is null)
							Begin
								set @out_ErrorCode = '802';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PLEASE_SET_PICKING_RULE',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROCESSLOG;
							End

						select	@v_vchOutboundPickMasterID = outbound_pick_master_id from t_wms_outbound_pick_master 
						where outbound_order_number = @v_vchOutboundOrderNumber and wh_master_id = @v_vchWarehouseMasterID

						-- delete row not pick
						delete from t_wms_outbound_pick_detail 
						where outbound_pick_master_id = @v_vchOutboundPickMasterID 
						and location_id = @v_vchFLocationMasterID
						and wh_item_master_id = @v_vchWarehouseItemMasterID
						and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') 
						and isnull(lpn,'') = isnull(@in_vchLPN,'')
						and quantity_pick = 0

						-- update row pick.set quantity plan = quantity pick
						update t_wms_outbound_pick_detail 
						set quantity_plan = quantity_pick--,is_override = 'YES'
						where outbound_pick_master_id = @v_vchOutboundPickMasterID 
						and location_id = @v_vchFLocationMasterID 
						and wh_item_master_id = @v_vchWarehouseItemMasterID
						and isnull(parent_lpn,'') = isnull(@in_vchParentLPN,'') 
						and isnull(lpn,'') = isnull(@in_vchLPN,'')
						--and quantity_pick <> 0	

						-- release order by old item ,location		
						exec [usp_outbound_generate_picklist]
							@in_vchApplicationID			= @in_vchApplicationID,
							@in_vchWarehouseMasterID		= @v_vchWarehouseMasterID,
							@in_vchOutboundPickMasterID		= @v_vchOutboundPickMasterID,
							@in_vchOutboundOrderDetailID	= @v_vchOutboundOrderDetailID,
							@in_vchItemNumber				= @in_vchItem,
							@in_vchWHItemMasterID			= @v_vchWarehouseItemMasterID,
							@in_vchLocationID				= null,--@in_vchFromLocation,
							@in_vchOldLocation				= @in_vchFromLocation,
							@in_vchParentLPN				= null,
							@in_vchLPN						= null,
							@in_fltQuantity					= @v_fltRemainPickQty output,
							@in_vchUOM						= @v_vchUOM,
							@in_vchSerial					= @v_vchSerialNumber,
							@in_vchExpiryDate				= @v_vchExpiryDate,
							@in_vchLot						= @v_vchLotNumber,
							@in_vchSerialControl			= @v_vchSerialControl,
							@in_vchDefaultItemStatus		= @v_vchDefaultItemStatus,
							@in_vchPickRule					= @v_vchRuleCode,
							@in_vchAlloShortPick			= @v_vchAlloShortPick,
							@in_vchOwner					= @v_vchOwnerCode,
							@in_vchCustomerCode				= @v_vchCustomerCode,
							@in_dtpShipDatePlan				= @v_dtpShipDatePlan,
							@in_vchUserID					= @in_vchUserID,
							@out_ErrorCode					= @out_ErrorCode output,
							@out_ErrorMessage				= @out_ErrorMessage output
						If (@out_ErrorCode <> '0')
							Begin GOTO WRITE_PROCESSLOG; End
				
						-- un allocate inventory data
						exec [usp_inventory_un_allocate]
							@in_vchApplicationID		= @in_vchApplicationID,
							@in_vchWarehouseMasterID	= @v_vchWarehouseMasterID,
							@in_vchLocationID			= @v_vchFLocationMasterID,
							@in_vchParentLPN			= null,
							@in_vchLPN					= @in_vchLPN,
							@in_vchItemNumber			= @in_vchItem,
							@in_vchWHItemMasterID		= @v_vchWarehouseItemMasterID,
							@in_fltQuantity				= @v_fltRemainPickQty,
							@in_vchSerialValue			= @v_vchSerialNumber,
							@in_vchLotValue				= @v_vchLotNumber,
							@in_vchExpiryDateValue		= @v_vchExpiryDate,
							@in_vchSerialControl		= @v_vchSerialControl,
							@in_vchUserID				= @in_vchUserID,
							@out_ErrorCode				= @out_ErrorCode output,
							@out_ErrorMessage			= @out_ErrorMessage output
						If (@out_ErrorCode <> '0')
							Begin GOTO WRITE_PROCESSLOG; End

						Fetch next from cursorOutboundDetail Into @v_vchOutboundOrderDetailID,@v_vchSerialNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_fltRemainPickQty,
										@v_vchUOM,@v_vchDefaultItemStatus,@v_vchCustomerCode,@v_dtpShipDatePlan,@v_vchOutboundOrderNumber
					End
			Close cursorOutboundDetail;
			Deallocate cursorOutboundDetail;

			COMMIT TRANSACTION

			set @out_ErrorCode = '0';
			select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			return;
-------------------------------------------------------------------------------------------------
--								WRITE PROCESS LOG
	WRITE_PROCESSLOG:
-------------------------------------------------------------------------------------------------
	If (@@TRANCOUNT > 0)
		ROLLBACK TRANSACTION;
	
	IF CURSOR_STATUS('global','cursorInventory') >= -1
		Begin
			Close cursorInventory;
			Deallocate cursorInventory;
		End
	IF CURSOR_STATUS('global','cursorOutboundDetail') >= -1
		Begin
			Close cursorOutboundDetail;
			Deallocate cursorOutboundDetail;
		End
										
	SET @v_dtProcessDateTime = getdate();
	set @v_vchData1 = @out_ErrorMessage;
	set @v_vchData2 = 'Outbound order [' + @in_vchLoadNumber + ']';

	exec usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchData1,
		@in_vchData2 = @v_vchData2,
		@in_vchData3 = null,
		@in_vchData4 = null,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
		
	return;
	
	End Try
	Begin Catch
		If (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','cursorInventory') >= -1
		Begin
			Close cursorInventory;
			Deallocate cursorInventory;
		End
		IF CURSOR_STATUS('global','cursorOutboundDetail') >= -1
		Begin
			Close cursorOutboundDetail;
			Deallocate cursorOutboundDetail;
		End
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End Catch	
END



GO
