/****** Object:  StoredProcedure [dbo].[usp_outbound_release_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_release_order]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER, 
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
SET NOCOUNT ON;
	
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_release_order]',
		@v_vchBeginTrans			BIT = 0, 
		@v_dtProcessDateTime		DATETIME,
		@Round						INT,
		@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
		@v_vchWarehouse				NVARCHAR(25),
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
		@v_vchOrderType				NVARCHAR(30),
		@v_vchOrderStatus			NVARCHAR(10),
		@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
		@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,
		@v_vchCustomerCode			NVARCHAR(50),
		@v_dtpShipDatePlan			DATETIME,

		@v_vchAllowShortPick		NVARCHAR(3),
		@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
		@v_vchLineNumber			NVARCHAR(10),
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
		@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
		@v_vchItemNumber			NVARCHAR(50),
		@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
		@v_vchLPN					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(100),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(100),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchDefaultItemStatus		NVARCHAR(50), 
		@v_fltQuantityOrder			FLOAT,
		@v_fltQuantityPick			FLOAT,
		@v_fltQuantityRemain		FLOAT,
		@v_vchRuleCode				NVARCHAR(40),
		@v_vchUOMPrompt				NVARCHAR(50)

BEGIN TRY
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
	--Get outbound order master id & order type
	SELECT @v_vchOutboundOrderNumber = outbound_order_number
		, @v_vchWhMasterID = wh_master_id
		, @v_vchOrderType = order_type
		, @v_vchOrderStatus = order_status
		, @v_vchOwnerID = owner_id
		, @v_vchCustomerID = customer_id
		, @v_vchCustomerCode = customer_code
		, @v_dtpShipDatePlan = ship_date_plan 
	FROM t_wms_outbound_master 
	WHERE outbound_order_master_id = @in_vchOutboundMasterID
	IF(@v_vchOutboundOrderNumber IS NULL)
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END
	
	IF @v_vchOrderStatus NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_STATUS_FOR_RELEASE' AND is_active = 'YES')
		BEGIN
			SET @out_ErrorCode = 'STATUS_CANNOT_RELEASE_ORDER';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,@v_vchOrderStatus,'@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END

	--Check Wh Master ID
	SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @v_vchWhMasterID AND is_active = 'YES'
	IF (@v_vchWhMasterID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END

	IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
		BEGIN
			SET @v_vchAllowShortPick = 'YES'
		END
	ELSE
		BEGIN
			SET @v_vchAllowShortPick = 'NO'
		END

BEGIN TRANSACTION;
SET @v_vchBeginTrans = 1; 

		/*--CBD: Release Production Order >> Order type นี้ไม่ต้องจองของใน inventory
		IF (@v_vchOrderType = 'Production Order' AND @v_vchOrderStatus = 'OPEN')
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = (CASE order_status WHEN 'OPEN' THEN 'RELEASE' ELSE order_status END)
					, pick_type = 'SYSTEM'
					, update_by = @in_vchUserID
					, update_date = GETDATE()
				WHERE outbound_order_master_id = @in_vchOutboundMasterID 
				SET @out_ErrorCode = '0';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				RETURN;
			END
		*/

		--Check outbound pick master
		SET @v_vchOutboundPickMasterID = NULL;
		SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @in_vchOutboundMasterID
		IF (@v_vchOutboundPickMasterID IS NULL)
			BEGIN
				SET @v_vchOutboundPickMasterID = NEWID();
				INSERT INTO t_wms_outbound_pick_master
					( outbound_pick_master_id
					, wh_master_id
					, outbound_order_master_id
					, outbound_order_number
					, pick_list_number
					, create_date
					, create_by)
				VALUES
					( @v_vchOutboundPickMasterID
					, @v_vchWhMasterID
					, @in_vchOutboundMasterID
					, @v_vchOutboundOrderNumber
					, @v_vchOutboundOrderNumber
					, GETDATE()
					, @in_vchUserID)
			END
		ELSE
			BEGIN
				DECLARE @v_vchUnLocationID		  UNIQUEIDENTIFIER = NULL
				DECLARE @v_vchUnParentLPN		  NVARCHAR(25) = NULL
				DECLARE @v_vchUnLPN				  NVARCHAR(25) = NULL
				DECLARE @v_vchUnWhItemMasterID	  UNIQUEIDENTIFIER = NULL
				DECLARE @v_vchUnLotNumber		  NVARCHAR(50) = NULL
				DECLARE @v_vchUnExpiryDate		  NVARCHAR(50) = NULL
				DECLARE @v_vchUnSerialNumber	  NVARCHAR(50) = NULL
				DECLARE @v_vchUnAttribute1		  NVARCHAR(100) = NULL
				DECLARE @v_vchUnAttribute2		  NVARCHAR(100) = NULL
				DECLARE @v_vchUnAttribute3		  NVARCHAR(100) = NULL
				DECLARE @v_vchUnAttribute4		  NVARCHAR(100) = NULL
				DECLARE @v_vchUnAttribute5		  NVARCHAR(100) = NULL
				DECLARE @v_fltUnRemainPickQTY	  FLOAT = NULL
				DECLARE @v_dtUnReceiveDate		  DATE = NULL
				DECLARE @v_vchUnDefaultItemStatus NVARCHAR(50) = NULL
				 
				DECLARE OutboundUnAllocateCURSOR CURSOR FOR
					SELECT pickDT.location_id
						,pickDT.parent_lpn
						,pickDT.lpn
						,pickDT.wh_item_master_id
						,pickDT.lot_number
						,pickDT.expiry_date
						,pickDT.serial_number
						,pickDT.attribute1
						,pickDT.attribute2
						,pickDT.attribute3
						,pickDT.attribute4
						,pickDT.attribute5
						,ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) AS quantity_remain_pick
						,pickDT.receive_date
						,obDT.default_item_status
					FROM t_wms_outbound_pick_master pickMS
					INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
					INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
					WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID 
					AND ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) > 0 
					AND pickDT.is_override = 'NO'	
				OPEN OutboundUnAllocateCURSOR;
				FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
														,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
					WHILE @@FETCH_STATUS = 0
						BEGIN
							-- un allocate inventory data
							EXEC [usp_inventory_un_allocate]  @in_vchApplicationID		= @in_vchApplicationID	
															, @in_vchWarehouseMasterID	= @v_vchWhMasterID	
															, @in_vchLocationID			= @v_vchUnLocationID
															, @in_vchParentLPN			= @v_vchUnParentLPN	
															, @in_vchLPN				= @v_vchUnLPN
															, @in_vchWhItemMasterID		= @v_vchUnWhItemMasterID
															, @in_fltQuantity			= @v_fltUnRemainPickQTY	
															, @in_vchSerialNumber		= @v_vchUnSerialNumber	
															, @in_vchLotNumber			= @v_vchUnLotNumber	
															, @in_vchExpiryDate			= @v_vchUnExpiryDate
															, @in_vchAttribute1			= @v_vchUnAttribute1
															, @in_vchAttribute2			= @v_vchUnAttribute2
															, @in_vchAttribute3			= @v_vchUnAttribute3
															, @in_vchAttribute4			= @v_vchUnAttribute4
															, @in_vchAttribute5			= @v_vchUnAttribute5
															, @in_dtReceiveDate			= @v_dtUnReceiveDate
															, @in_vchDefaultItemStatus	= @v_vchUnDefaultItemStatus
															, @in_vchUserID				= @in_vchUserID	
															, @out_ErrorCode			= @out_ErrorCode	OUTPUT
															, @out_ErrorMessage			= @out_ErrorMessage OUTPUT
							IF (@out_ErrorCode <> '0')
								BEGIN 
									GOTO WRITE_PROCESSLOG;
								END 
							FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
														,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
						END

				CLOSE OutboundUnAllocateCURSOR;
				DEALLOCATE OutboundUnAllocateCURSOR;
					
				-- delete row not pick
				DELETE FROM t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) = 0
				-- update row pick.set quantity plan = quantity pick
				UPDATE t_wms_outbound_pick_detail SET quantity_plan = quantity_pick WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) > 0
			END
		
		-- Release and Re-Run	
		DECLARE OutboundDetailCursor CURSOR FOR
			SELECT obDT.outbound_order_detail_id
				, obDT.line_number
				, obDT.wh_item_master_id
				, item.item_master_id
				, item.item_number
				, obDT.location_id AS location_id		/*ไม่ต้อง Where เนื่องจาก 1 Zone มีมากกว่า 1 Location*/
				, obDT.lpn
				, obDT.lot_number
				, obDT.expiry_date
				, obDT.serial_number
				, obDT.attribute1
				, obDT.attribute2
				, obDT.attribute3
				, obDT.attribute4
				, obDT.attribute5
				, obDT.default_item_status
				, obDT.quantity_order
				, obDT.quantity_pick 
				, tRule.rule_code
				, uom.uom_prompt
			FROM t_wms_outbound_detail obDT
			INNER JOIN t_wms_wh_item whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id
			INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
			INNER JOIN t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
			LEFT JOIN t_wms_rule tRule ON uom.picking_class = tRule.rule_id
			WHERE obDT.outbound_order_master_id = @in_vchOutboundMasterID
			AND ISNULL(obDT.quantity_order,0) > ISNULL(obDT.quantity_pick,0)
			ORDER BY CONVERT(INT,obDT.line_number)
		OPEN OutboundDetailCursor;
		FETCH OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_vchLineNumber,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_vchLocationID,@v_vchLPN
										,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
										,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityPick,@v_vchRuleCode,@v_vchUOMPrompt
		 
			WHILE @@FETCH_STATUS = 0
				BEGIN
					SET @v_fltQuantityRemain = ROUND(ISNULL(@v_fltQuantityOrder,0) - ISNULL(@v_fltQuantityPick,0),@ROUND)
					
					IF (@v_vchRuleCode IS NULL)
						BEGIN
							SET @out_ErrorCode = '203';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PLEASE_SET_PICKING_RULE',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROCESSLOG;
						END
					IF (@v_vchRuleCode = 'RULE_PICK_BY_PICK_LOCATION' AND @v_vchLocationID IS NULL)
						BEGIN
							SET @out_ErrorCode = '204';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PLEASE_DEFINE_PICK_LOCATION',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROCESSLOG; 
						END
					
					EXEC [usp_outbound_generate_picklist]
							@in_vchApplicationID			= @in_vchApplicationID
						   ,@in_vchReleaseDesc				= 'Release by Order'
						   ,@in_vchWarehouseMasterID		= @v_vchWhMasterID
						   ,@in_vchOutboundMasterID			= @in_vchOutboundMasterID
						   ,@in_vchOutboundPickMasterID		= @v_vchOutboundPickMasterID
						   ,@in_vchOutboundOrderDetailID	= @v_vchOutboundDetailID
						   ,@in_vchOwnerID					= @v_vchOwnerID			
						   ,@in_vchWhItemMasterID			= @v_vchWhItemMasterID
						   ,@in_vchItemMasterID				= @v_vchItemMasterID
						   ,@in_vchItemNumber				= @v_vchItemNumber						   
						   ,@in_vchLocationID				= @v_vchLocationID
						   ,@in_vchOldLocation				= NULL
						   ,@in_vchParentLPNIsOverride		= NULL
						   ,@in_vchParentLPN				= NULL
						   ,@in_vchLPN						= @v_vchLPN
						   ,@in_fltQuantity					= @v_fltQuantityRemain
						   ,@in_vchUOMPrompt				= @v_vchUOMPrompt
						   ,@in_vchDefaultItemStatus		= @v_vchDefaultItemStatus
						   ,@in_vchSerialNumber				= @v_vchSerialNumber
						   ,@in_vchExpiryDate				= @v_vchExpiryDate
						   ,@in_vchLotNumber				= @v_vchLotNumber
						   ,@in_vchAttribute1				= @v_vchAttribute1
						   ,@in_vchAttribute2				= @v_vchAttribute2
						   ,@in_vchAttribute3				= @v_vchAttribute3
						   ,@in_vchAttribute4				= @v_vchAttribute4
						   ,@in_vchAttribute5				= @v_vchAttribute5
						   ,@in_vchPickRule					= @v_vchRuleCode
						   ,@in_vchAllowShortPick			= @v_vchAllowShortPick
						   ,@in_vchCustomerID			 	= @v_vchCustomerID
						   ,@in_vchCustomerCode				= @v_vchCustomerCode
						   ,@in_dtpShipDatePlan				= @v_dtpShipDatePlan
						   ,@in_vchZone						= NULL
						   ,@in_vchLineNumber				= @v_vchLineNumber
						   ,@in_vchDeviceID					= @in_vchDeviceID
						   ,@in_vchUserID					= @in_vchUserID
						   ,@in_vchLoadID					= NULL
						   ,@out_ErrorCode					= @out_ErrorCode	OUTPUT
						   ,@out_ErrorMessage				= @out_ErrorMessage OUTPUT
						    
					IF (@out_ErrorCode <> '0')
						BEGIN 
							GOTO WRITE_PROCESSLOG; 
						END 
					FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_vchLineNumber,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_vchLocationID,@v_vchLPN
										,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
										,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityPick,@v_vchRuleCode,@v_vchUOMPrompt
				END 	
			CLOSE OutboundDetailCursor;
			DEALLOCATE OutboundDetailCursor;

		IF ((SELECT TOP 1 order_status FROM t_wms_outbound_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @in_vchOutboundMasterID) = 'OPEN')
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = (CASE order_status WHEN 'OPEN' THEN 'RELEASE' ELSE order_status END)
					, pick_type = 'SYSTEM'
					, pick_by = (CASE WHEN order_status IN ('OPEN','RELEASE') THEN NULL ELSE pick_by END)
					, release_by = @in_vchUserID
					, release_date = GETDATE()
					, update_by =  @in_vchUserID
					, update_date = GETDATE()
				WHERE outbound_order_master_id = @in_vchOutboundMasterID
			END

		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		COMMIT TRANSACTION;	
		RETURN;	
-------------------------------------------------------------------------------------------------
--Write Log
	WRITE_PROCESSLOG:
-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundDetailCursor') >= -1
			BEGIN
				Close OutboundDetailCursor;
				Deallocate OutboundDetailCursor;
			END
			
		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			END

		SET @v_dtProcessDateTime = GETDATE();  
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID			 = @v_vchWarehouse,
			@in_vchDevice		 = @in_vchDeviceID,
			@in_vchUserID		 = @in_vchUserID,
			@in_vchLogType		 = 'PROCESS',
			@in_vchProcess		 = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1		= @v_vchOutboundOrderNumber,
			@in_vchData2		= @v_vchOrderStatus,
			@in_vchData3		= @v_vchOrderType,
			@in_vchData4		= @out_ErrorMessage,
			@in_vchErrorCode	= @out_ErrorCode,
			@in_vchMessage		= @out_ErrorMessage	
			
		RETURN;
-------------------------------------------------------------------------------------------------
	END TRY

	BEGIN CATCH 
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundDetailCursor') >= -1
			BEGIN
				Close OutboundDetailCursor;
				Deallocate OutboundDetailCursor;
			END

		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			END
			 
		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE(); 
		
		SET @v_dtProcessDateTime = GETDATE();  
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID			= @v_vchWarehouse,
			@in_vchDevice		= @in_vchDeviceID,
			@in_vchUserID		= @in_vchUserID,
			@in_vchLogType		= 'PROCESS',
			@in_vchProcess		= @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1		= @v_vchOutboundOrderNumber,
			@in_vchData2		= @v_vchOrderStatus,
			@in_vchData3		= @v_vchOrderType,
			@in_vchData4		= null,
			@in_vchErrorCode	= @out_ErrorCode,
			@in_vchMessage		= @out_ErrorMessage	

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_release_order_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_release_order_by_group]
	@in_vchApplicationID VARCHAR(40),
	@in_vchWarehouse	 NVARCHAR(25),
	@in_vchLoadID		 NVARCHAR(50),
	@in_vchDeviceID		 NVARCHAR(50),
	@in_vchUserID		 NVARCHAR(25), 
	@out_ErrorCode		 NVARCHAR(200) OUTPUT,
	@out_ErrorMessage	 NVARCHAR(500) OUTPUT
AS
BEGIN
SET NOCOUNT ON;
	
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_release_order_by_group]',
		@v_vchBeginTrans			BIT = 0, 
		@v_dtProcessDateTime		DATETIME,
		@Round						INT,
		@v_vchWhMasterID			UNIQUEIDENTIFIER,
		@v_vchOutboundMasterID		UNIQUEIDENTIFIER, 
		@v_vchOutboundOrderNumber	NVARCHAR(50),
		@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
		@v_vchOrderType				NVARCHAR(30),
		@v_vchOrderStatus			NVARCHAR(10),
		@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
		@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,
		@v_vchCustomerCode			NVARCHAR(50),
		@v_dtpShipDatePlan			DATETIME,
		@v_vchAllowShortPick		NVARCHAR(3),
		@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
		@v_vchLineNumber			NVARCHAR(5),
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
		@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
		@v_vchItemNumber			NVARCHAR(50),
		@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
		@v_vchLPN					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(100),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(100),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchDefaultItemStatus		NVARCHAR(50), 
		@v_fltQuantityOrder			FLOAT,
		@v_fltQuantityPick			FLOAT,
		@v_fltQuantityRemain		FLOAT,
		@v_vchRuleCode				NVARCHAR(40),
		@v_vchUOMPrompt				NVARCHAR(50)

	BEGIN TRY
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1; 

		-- Release and Re-Run by order
		DECLARE OutboundMasterCursor CURSOR FOR
			SELECT outbound_order_master_id
				, outbound_order_number
				, wh_id
				, order_type
				, order_status
				, owner_id
				, customer_id
				, customer_code
				, ship_date_plan 
			FROM t_wms_outbound_master 
			WHERE load_id = @in_vchLoadID
			AND wh_master_id = @v_vchWhMasterID
			AND order_status IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_STATUS_FOR_RELEASE' AND is_active = 'YES')
		OPEN OutboundMasterCursor
		FETCH OutboundMasterCursor INTO @v_vchOutboundMasterID, @v_vchOutboundOrderNumber, @in_vchWarehouse, @v_vchOrderType, @v_vchOrderStatus, @v_vchOwnerID, @v_vchCustomerID, @v_vchCustomerCode, @v_dtpShipDatePlan
		WHILE @@FETCH_STATUS = 0
			BEGIN
				IF(@v_vchOutboundOrderNumber IS NULL)
					BEGIN
						SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROCESSLOG;
					END	
	
				IF @v_vchOrderStatus NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_STATUS_FOR_RELEASE' AND is_active = 'YES')
					BEGIN
						SET @out_ErrorCode = 'STATUS_CANNOT_RELEASE_ORDER';
						SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,@v_vchOrderStatus,'@param3','@param4','@param5')
						GOTO WRITE_PROCESSLOG;
					END

				IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
					BEGIN
						SET @v_vchAllowShortPick = 'YES'
					END
				ELSE
					BEGIN
						SET @v_vchAllowShortPick = 'NO'
					END

				--Check outbound pick master / un allocate
				SET @v_vchOutboundPickMasterID = NULL;
				SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @v_vchOutboundMasterID
				IF (@v_vchOutboundPickMasterID IS NULL)
					BEGIN
						SET @v_vchOutboundPickMasterID = NEWID();
						INSERT INTO t_wms_outbound_pick_master
							( outbound_pick_master_id
							, wh_master_id
							, outbound_order_master_id
							, outbound_order_number
							, pick_list_number
							, create_date
							, create_by)
						VALUES
							( @v_vchOutboundPickMasterID
							, @v_vchWhMasterID
							, @v_vchOutboundMasterID
							, @v_vchOutboundOrderNumber
							, @v_vchOutboundOrderNumber
							, GETDATE()
							, @in_vchUserID)
					END
				ELSE
					BEGIN
						DECLARE @v_vchUnLocationID		  UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchUnParentLPN		  NVARCHAR(25) = NULL
						DECLARE @v_vchUnLPN				  NVARCHAR(25) = NULL
						DECLARE @v_vchUnWhItemMasterID	  UNIQUEIDENTIFIER = NULL
						DECLARE @v_vchUnLotNumber		  NVARCHAR(50) = NULL
						DECLARE @v_vchUnExpiryDate		  NVARCHAR(50) = NULL
						DECLARE @v_vchUnSerialNumber	  NVARCHAR(50) = NULL
						DECLARE @v_vchUnAttribute1		  NVARCHAR(100) = NULL
						DECLARE @v_vchUnAttribute2		  NVARCHAR(100) = NULL
						DECLARE @v_vchUnAttribute3		  NVARCHAR(100) = NULL
						DECLARE @v_vchUnAttribute4		  NVARCHAR(100) = NULL
						DECLARE @v_vchUnAttribute5		  NVARCHAR(100) = NULL
						DECLARE @v_fltUnRemainPickQTY	  FLOAT = NULL
						DECLARE @v_dtUnReceiveDate		  DATE = NULL
						DECLARE @v_vchUnDefaultItemStatus NVARCHAR(50) = NULL
				 
						DECLARE OutboundUnAllocateCURSOR CURSOR FOR
							SELECT pickDT.location_id
								,pickDT.parent_lpn
								,pickDT.lpn
								,pickDT.wh_item_master_id
								,pickDT.lot_number
								,pickDT.expiry_date
								,pickDT.serial_number
								,pickDT.attribute1
								,pickDT.attribute2
								,pickDT.attribute3
								,pickDT.attribute4
								,pickDT.attribute5
								,ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) AS quantity_remain_pick
								,pickDT.receive_date
								,obDT.default_item_status
							FROM t_wms_outbound_pick_master pickMS
							INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
							INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
							WHERE pickMS.outbound_order_master_id = @v_vchOutboundMasterID 
							AND ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) > 0 
							AND pickDT.is_override = 'NO'	
						OPEN OutboundUnAllocateCURSOR;
						FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
																,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
							WHILE @@FETCH_STATUS = 0
								BEGIN
									-- un allocate inventory data
									EXEC [usp_inventory_un_allocate]  @in_vchApplicationID		= @in_vchApplicationID	
																	, @in_vchWarehouseMasterID	= @v_vchWhMasterID	
																	, @in_vchLocationID			= @v_vchUnLocationID
																	, @in_vchParentLPN			= @v_vchUnParentLPN	
																	, @in_vchLPN				= @v_vchUnLPN
																	, @in_vchWhItemMasterID		= @v_vchUnWhItemMasterID
																	, @in_fltQuantity			= @v_fltUnRemainPickQTY	
																	, @in_vchSerialNumber		= @v_vchUnSerialNumber	
																	, @in_vchLotNumber			= @v_vchUnLotNumber	
																	, @in_vchExpiryDate			= @v_vchUnExpiryDate
																	, @in_vchAttribute1			= @v_vchUnAttribute1
																	, @in_vchAttribute2			= @v_vchUnAttribute2
																	, @in_vchAttribute3			= @v_vchUnAttribute3
																	, @in_vchAttribute4			= @v_vchUnAttribute4
																	, @in_vchAttribute5			= @v_vchUnAttribute5
																	, @in_dtReceiveDate			= @v_dtUnReceiveDate
																	, @in_vchDefaultItemStatus	= @v_vchUnDefaultItemStatus
																	, @in_vchUserID				= @in_vchUserID	
																	, @out_ErrorCode			= @out_ErrorCode	OUTPUT
																	, @out_ErrorMessage			= @out_ErrorMessage OUTPUT
									IF (@out_ErrorCode <> '0')
										BEGIN 
											GOTO WRITE_PROCESSLOG;
										END 
									FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber
																,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_fltUnRemainPickQTY,@v_dtUnReceiveDate,@v_vchUnDefaultItemStatus
								END

						CLOSE OutboundUnAllocateCURSOR;
						DEALLOCATE OutboundUnAllocateCURSOR;
					
						-- delete row not pick
						DELETE FROM t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) = 0
						-- update row pick.set quantity plan = quantity pick
						UPDATE t_wms_outbound_pick_detail SET quantity_plan = quantity_pick WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) > 0
					END
		
				-- Release and Re-Run	
				DECLARE OutboundDetailCursor CURSOR FOR
					SELECT obDT.outbound_order_detail_id
						, obDT.line_number
						, obDT.wh_item_master_id
						, item.item_master_id
						, item.item_number
						, NULL AS location_id		/*ไม่ต้อง Where เนื่องจาก 1 Zone มีมากกว่า 1 Location*/
						, obDT.lpn
						, obDT.lot_number
						, obDT.expiry_date
						, obDT.serial_number
						, obDT.attribute1
						, obDT.attribute2
						, obDT.attribute3
						, obDT.attribute4
						, obDT.attribute5
						, obDT.default_item_status
						, obDT.quantity_order
						, obDT.quantity_pick 
						, tRule.rule_code
						, uom.uom_prompt
					FROM t_wms_outbound_detail obDT
					INNER JOIN t_wms_wh_item whItem ON obDT.wh_item_master_id = whItem.wh_item_master_id
					INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
					INNER JOIN t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
					LEFT JOIN t_wms_rule tRule ON uom.picking_class = tRule.rule_id
					WHERE obDT.outbound_order_master_id = @v_vchOutboundMasterID
					AND ISNULL(obDT.quantity_order,0) > ISNULL(obDT.quantity_pick,0)
					ORDER BY CONVERT(INT,obDT.line_number)
				OPEN OutboundDetailCursor;
				FETCH OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_vchLineNumber,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_vchLocationID,@v_vchLPN
												,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
												,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityPick,@v_vchRuleCode,@v_vchUOMPrompt
				WHILE @@FETCH_STATUS = 0
					BEGIN
						SET @v_fltQuantityRemain = ROUND(ISNULL(@v_fltQuantityOrder,0) - ISNULL(@v_fltQuantityPick,0),@ROUND)
					
						IF (@v_vchRuleCode IS NULL)
							BEGIN
								SET @out_ErrorCode = '203';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PLEASE_SET_PICKING_RULE',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROCESSLOG;
							END
						IF (@v_vchRuleCode = 'RULE_PICK_BY_PICK_LOCATION' AND @v_vchLocationID IS NULL)
							BEGIN
								SET @out_ErrorCode = '204';
								SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PLEASE_DEFINE_PICK_LOCATION',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROCESSLOG; 
							END
					
						EXEC [usp_outbound_generate_picklist]
								@in_vchApplicationID			= @in_vchApplicationID
								,@in_vchReleaseDesc				= 'Release by Group'
								,@in_vchWarehouseMasterID		= @v_vchWhMasterID
								,@in_vchOutboundMasterID		= @v_vchOutboundMasterID
								,@in_vchOutboundPickMasterID	= @v_vchOutboundPickMasterID
								,@in_vchOutboundOrderDetailID	= @v_vchOutboundDetailID
								,@in_vchOwnerID					= @v_vchOwnerID			
								,@in_vchWhItemMasterID			= @v_vchWhItemMasterID
								,@in_vchItemMasterID			= @v_vchItemMasterID
								,@in_vchItemNumber				= @v_vchItemNumber						   
								,@in_vchLocationID				= @v_vchLocationID
								,@in_vchOldLocation				= NULL
								,@in_vchParentLPNIsOverride		= NULL
								,@in_vchParentLPN				= NULL
								,@in_vchLPN						= @v_vchLPN
								,@in_fltQuantity				= @v_fltQuantityRemain
								,@in_vchUOMPrompt				= @v_vchUOMPrompt
								,@in_vchDefaultItemStatus		= @v_vchDefaultItemStatus
								,@in_vchSerialNumber			= @v_vchSerialNumber
								,@in_vchExpiryDate				= @v_vchExpiryDate
								,@in_vchLotNumber				= @v_vchLotNumber
								,@in_vchAttribute1				= @v_vchAttribute1
								,@in_vchAttribute2				= @v_vchAttribute2
								,@in_vchAttribute3				= @v_vchAttribute3
								,@in_vchAttribute4				= @v_vchAttribute4
								,@in_vchAttribute5				= @v_vchAttribute5
								,@in_vchPickRule				= @v_vchRuleCode
								,@in_vchAllowShortPick			= @v_vchAllowShortPick
								,@in_vchCustomerID			 	= @v_vchCustomerID
								,@in_vchCustomerCode			= @v_vchCustomerCode
								,@in_dtpShipDatePlan			= @v_dtpShipDatePlan
								,@in_vchZone					= NULL
								,@in_vchLineNumber				= @v_vchLineNumber
								,@in_vchDeviceID				= @in_vchDeviceID
								,@in_vchUserID					= @in_vchUserID
								,@in_vchLoadID					= @in_vchLoadID		
								,@out_ErrorCode					= @out_ErrorCode	OUTPUT
								,@out_ErrorMessage				= @out_ErrorMessage OUTPUT
						    
						IF (@out_ErrorCode <> '0')
							BEGIN 
								GOTO WRITE_PROCESSLOG; 
							END 
						FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundDetailID,@v_vchLineNumber,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber,@v_vchLocationID,@v_vchLPN
											,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
											,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityPick,@v_vchRuleCode,@v_vchUOMPrompt
					END 	
				CLOSE OutboundDetailCursor;
				DEALLOCATE OutboundDetailCursor;

				IF ((SELECT TOP 1 order_status FROM t_wms_outbound_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @v_vchOutboundMasterID) = 'OPEN')
					BEGIN
						UPDATE t_wms_outbound_master SET order_status = (CASE order_status WHEN 'OPEN' THEN 'RELEASE' ELSE order_status END)
							, pick_type = 'SYSTEM_GROUP'
							, release_by = @in_vchUserID
							, release_date = GETDATE()
							, update_by =  @in_vchUserID
							, update_date = GETDATE()
						WHERE outbound_order_master_id = @v_vchOutboundMasterID
					END 

				FETCH OutboundMasterCursor INTO @v_vchOutboundMasterID, @v_vchOutboundOrderNumber, @in_vchWarehouse, @v_vchOrderType, @v_vchOrderStatus, @v_vchOwnerID, @v_vchCustomerID, @v_vchCustomerCode, @v_dtpShipDatePlan
			END
		CLOSE OutboundMasterCursor;
		DEALLOCATE OutboundMasterCursor; 


		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		COMMIT TRANSACTION;	
		RETURN;	
	-------------------------------------------------------------------------------------------------
	--Write Log
	WRITE_PROCESSLOG:
	-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundMasterCursor') >= -1
			BEGIN
				Close OutboundMasterCursor;
				Deallocate OutboundMasterCursor;
			END

		IF CURSOR_STATUS('global','OutboundDetailCursor') >= -1
			BEGIN
				Close OutboundDetailCursor;
				Deallocate OutboundDetailCursor;
			END
			
		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			END

		SET @v_dtProcessDateTime = GETDATE();  
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = @v_vchOrderStatus,
			@in_vchData3 = @v_vchOrderType,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
	-------------------------------------------------------------------------------------------------
	END TRY

	BEGIN CATCH 
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundMasterCursor') >= -1
			BEGIN
				Close OutboundMasterCursor;
				Deallocate OutboundMasterCursor;
			END

		IF CURSOR_STATUS('global','OutboundDetailCursor') >= -1
			BEGIN
				Close OutboundDetailCursor;
				Deallocate OutboundDetailCursor;
			END

		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				Close OutboundUnAllocateCURSOR;
				Deallocate OutboundUnAllocateCURSOR;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
		
		SET @v_dtProcessDateTime = GETDATE();  
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = @v_vchOrderStatus,
			@in_vchData3 = @v_vchOrderType,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_release_order_user_pick]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_outbound_release_order_user_pick]
(
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@out_ErrorCode				NVARCHAR(50) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_release_order_user_pick]',
			@v_dtProcessDateTime	DATETIME,
			@v_vchWhMasterID		UNIQUEIDENTIFIER,
			@v_vchOutboundMasterID	UNIQUEIDENTIFIER,
			@v_vchOrderType			NVARCHAR(30),
			@v_vchAllowShortPick	VARCHAR(3)

	SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
	IF (@v_vchWhMasterID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWarehouse,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END

	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id 
		,@v_vchOrderType = obMS.order_type
	FROM t_wms_outbound_master obMS
	WHERE obMS.wh_master_id = @v_vchWhMasterID 
	AND obMS.outbound_order_number = @in_vchOutboundOrderNumber
	IF (@v_vchOutboundMasterID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROCESSLOG;
		END

	IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
		BEGIN
			SET @v_vchAllowShortPick = 'YES'
		END
	ELSE
		BEGIN
			SET @v_vchAllowShortPick = 'NO'
		END

	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK') = 'YES' OR @v_vchAllowShortPick = 'YES')
		BEGIN
			GOTO UPDATE_STATUS;
		END

	--Check Inventory
	EXEC usp_outbound_check_picklist_item @in_vchApplicationID	  = @in_vchApplicationID	 			
										 ,@in_vchOutboundMasterID = @v_vchOutboundMasterID			
										 ,@in_vchUserID			  = @in_vchUserID					
										 ,@out_ErrorCode		  = @out_ErrorCode OUTPUT				
										 ,@out_ErrorMessage		  = @out_ErrorMessage OUTPUT
	IF @out_ErrorCode <> '0'
	BEGIN
		GOTO WRITE_PROCESSLOG;
	END
		
	UPDATE_STATUS:
		UPDATE t_wms_outbound_master set order_status = (CASE order_status WHEN 'OPEN' THEN 'RELEASE' ELSE order_status END)
			, pick_type = 'USER'
			, release_by = @in_vchUserID
			, release_date = GETDATE()
			, update_by =  @in_vchUserID
			, update_date = GETDATE()
		WHERE outbound_order_master_id = @v_vchOutboundMasterID
						
	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;

-------------------------------------------------------------
-- WRITE PROCESS LOG
	WRITE_PROCESSLOG:
-------------------------------------------------------------	
	IF CURSOR_STATUS('global','Outbound_Cursor') >= -1
		BEGIN
			CLOSE Outbound_Cursor;
			DEALLOCATE Outbound_Cursor;
		END

	SET @v_dtProcessDateTime = getdate(); 
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchOutboundOrderNumber,
		@in_vchData2 = NULL,
		@in_vchData3 = NULL,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage	
		Return;
END




GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_ship_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
	2022-07-15 : กำหนดให้เมื่อ auto สร้าง inbound order กำหนดให้ reference number (ibMS) = outbound order number (obMS)
*/
CREATE PROCEDURE [dbo].[usp_outbound_ship_confirm]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWhMasterID		UNIQUEIDENTIFIER, 
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(25), 
	@in_vchOutboundMasterID UNIQUEIDENTIFIER, 
	@in_vchCarrierID		UNIQUEIDENTIFIER,	--CarrierID
	@in_vchTruckType		NVARCHAR(40),		--TruckTypeCode
	@in_vchTruckNumber		NVARCHAR(50) = NULL,  
	@in_vchDriverLicense	NVARCHAR(50) = NULL,
	@in_vchContainerNo		NVARCHAR(50) = NULL, 
	@in_vchSealNumber		NVARCHAR(50) = NULL,
	@in_vchPostingDate		DATETIME = NULL,
	@in_dtShipDateActual	DATETIME = NULL, 
	@out_ErrorCode			NVARCHAR(50) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
     
	DECLARE
		-- Error handling variables
		@c_vchObjName			NVARCHAR(50) = '[usp_outbound_ship_confirm]', -- The name that uniquely tags this object.
		@v_vchApplicationName	NVARCHAR(100),
		@v_dtProcessDateTime	DATETIME,
		@v_dtStartTranDate		DATETIME,
		@v_dtEndTranDate		DATETIME,
		@v_vchBeginTrans		BIT = 0,
		@Round					INT,
		@RulePickPack			VARCHAR(3)= 'NO',
		@RulePOD				VARCHAR(3)= 'NO',
		@RuleIsBorrow			VARCHAR(3)= 'NO',
		@v_intDueDate			INT,

		--Interface
		@v_vchHostInterfaceID	NVARCHAR(50),

		@v_vchWarehouse			NVARCHAR(25),
		@v_vchTruckTypeID		UNIQUEIDENTIFIER, 
		@v_vchCarrierCode		NVARCHAR(40),

		--Outbound
		@v_vchOrderNumber		NVARCHAR(50),
		@v_vchOwnerID			UNIQUEIDENTIFIER,
		@v_vchOwnerCode			NVARCHAR(50),
		@v_vchOrderType			NVARCHAR(30),
		@v_vchOrderStatus		NVARCHAR(10),
		@v_vchCustomerID		UNIQUEIDENTIFIER,
		@v_vchCustomerCode		NVARCHAR(50),
		@v_vchCustomerName		NVARCHAR(300),
		@v_vchShipToCode		NVARCHAR(40)	= NULL,  
		@v_vchShipToName		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr1		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr2		NVARCHAR(300)	= NULL,  
		@v_vchShipToAddr3		NVARCHAR(300)	= NULL,  
		@v_vchShipToCity		NVARCHAR(50)	= NULL,  
		@v_vchShipToProvince	NVARCHAR(50)	= NULL,  
		@v_vchShipToPostalCode	NVARCHAR(50)	= NULL,  
		@v_vchShipToCountry		NVARCHAR(5)		= NULL,  
		@v_vchShipToCountryName NVARCHAR(50)	= NULL,  
		@v_vchShipToContactName NVARCHAR(50)	= NULL,  
		@v_vchShipToPhoneNumber NVARCHAR(50)	= NULL,  
		@v_vchBillToCode		NVARCHAR(40)	= NULL,  
		@v_vchBillToName		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr1		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr2		NVARCHAR(300)	= NULL,  
		@v_vchBillToAddr3		NVARCHAR(300)	= NULL,  
		@v_vchBillToCity		NVARCHAR(50)	= NULL,  
		@v_vchBillToProvince	NVARCHAR(50)	= NULL,  
		@v_vchBillToPostalCode	NVARCHAR(50)	= NULL,  
		@v_vchBillToCountry		NVARCHAR(5)		= NULL,  
		@v_vchBillToCountryName NVARCHAR(50)	= NULL,  
		@v_vchBillToContactName NVARCHAR(50)	= NULL,  
		@v_vchBillToPhoneNumber	NVARCHAR(50)	= NULL,
		@v_vchTrackingNo		NVARCHAR(50)	= NULL,
		@v_vchToWarehouseID		NVARCHAR(50)	= NULL,
		@v_vchCustomerOrderNumber NVARCHAR(50)	= NULL,
		@v_vchLoadID			NVARCHAR(50)	= NULL,
		@v_dtDeliveryDatePlan	DATETIME,
		@v_dtShipDatePlan		DATETIME = NULL,
		@v_vchPickType			NVARCHAR(15),
		@v_vchHUDF1				NVARCHAR(255),
		@v_vchHUDF2				NVARCHAR(255),
		@v_vchHUDF3				NVARCHAR(255),
		@v_vchHUDF4				NVARCHAR(255),
		@v_vchHUDF5				NVARCHAR(255),
		@v_vchHUDF6				NVARCHAR(255),
		@v_fltHUDF7				FLOAT,
		@v_fltHUDF8				FLOAT,
		@v_dtpHUDF9				DATETIME,
		@v_dtpHUDF10			DATETIME,

		@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundBorrowMasterID UNIQUEIDENTIFIER = NULL,

		--Cursor Loop
		@v_vchOutboundOrderDetailID UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,
		@v_vchOutboundPackDetailID	UNIQUEIDENTIFIER = NULL,
		@v_vchLineNumber			NVARCHAR(10),  
		@v_vchLocationMasterID		UNIQUEIDENTIFIER,  
		@v_vchLocationForPick		NVARCHAR(50) = NULL,
		@v_vchZone					NVARCHAR(50) = NULL,
		@v_vchERPLocationForPick	NVARCHAR(50) = NULL,
		@v_vchLPN					NVARCHAR(25),  
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
		@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL, 
		@v_vchItemNumber			NVARCHAR(50),  
		@v_vchDefaultItemStatus		NVARCHAR(50)	= NULL,
		@v_fltQuantityOrder			FLOAT,
		@v_fltQuantityShip			FLOAT,
		@v_vchItemUOMID				UNIQUEIDENTIFIER = NULL, 
		@v_vchUOM					NVARCHAR(20),
		@v_vchLotNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(50),  
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchLotControl			VARCHAR(5),
		@v_vchExpiryDateControl		VARCHAR(5),
		@v_vchSerialControl			VARCHAR(5),
		@v_vchAttribute1Control		VARCHAR(5),
		@v_vchAttribute2Control		VARCHAR(5),
		@v_vchAttribute3Control		VARCHAR(5),
		@v_vchAttribute4Control		VARCHAR(5),
		@v_vchAttribute5Control		VARCHAR(5),
		@v_dtReceiveDate			DATE,
		
		--Calculate Volumn & Weight
		@v_fltWidth					FLOAT = 0,
		@v_fltLength				FLOAT = 0,
		@v_fltHeight				FLOAT = 0,
		@v_fltGrossWeight			FLOAT = 0,
		@v_intPercentTolerance		FLOAT = 0,
		@v_intPercenToleranceWeight FLOAT = 0,
		@v_fltVolumn				FLOAT = 0,	--item
		@v_fltTotalWeight			FLOAT = 0,	--item

		--Customer for POD
		@v_vchRouteCode			NVARCHAR(50),
		@v_vchRouteName			NVARCHAR(255),
		@v_vchCustUdf1			NVARCHAR(50),
		
		@v_vchTranType			NVARCHAR(50),
		@v_vchSubTranType		NVARCHAR(20)= NULL,
		@v_vchMoveSubTranType	NVARCHAR(20)= NULL, 
		@v_vchMoveToLocationID	UNIQUEIDENTIFIER = NULL,
		@v_vchMoveToLocation	NVARCHAR(50) = NULL,
		@v_vchMoveToInvStatusID	UNIQUEIDENTIFIER = NULL,
		@v_vchMoveToInvStatus	NVARCHAR(50) = NULL

	BEGIN TRY
		SET @v_dtStartTranDate = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
		SELECT TOP 1 @RulePOD = value FROM t_wms_rule WHERE rule_code = 'RULE_INSERT_POD' AND is_active = 'YES'
		SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		SELECT TOP 1 @v_vchCarrierCode = carrier_code FROM t_wms_carrier WHERE carrier_id = @in_vchCarrierID AND is_active = 'YES' 
		SELECT TOP 1 @v_vchTruckTypeID = truck_type_id FROM t_wms_truck_type WHERE truck_type = @in_vchTruckType AND is_active = 'YES'
 
		IF @in_dtShipDateActual IS NULL
			BEGIN
				SET @in_dtShipDateActual = GETDATE()
			END

		--Get Outbound
		SELECT TOP 1 @v_vchOrderNumber = obMS.outbound_order_number	
			, @v_vchOrderType = obMS.order_type
			, @v_vchOrderStatus = obMS.order_status
			, @v_vchOwnerID = obMS.owner_id
			, @v_vchOwnerCode = own.owner_code
			, @v_vchCustomerID = obMS.customer_id
			, @v_vchCustomerCode = obMS.customer_code
			, @v_vchCustomerName = obMS.customer_name
			, @v_vchShipToCode = obMS.ship_to_code	
			, @v_vchShipToName = obMS.ship_to_name
			, @v_vchShipToAddr1 = obMS.ship_to_addr_line_1
			, @v_vchShipToAddr2 = obMS.ship_to_addr_line_2
			, @v_vchShipToAddr3 = obMS.ship_to_addr_line_3
			, @v_vchShipToCity = obMS.ship_to_city
			, @v_vchShipToProvince = obMS.ship_to_province
			, @v_vchShipToPostalCode = obMS.ship_to_postal_code
			, @v_vchShipToCountry = obMS.ship_to_country_code
			, @v_vchShipToCountryName = obMS.ship_to_country_name
			, @v_vchShipToContactName = obMS.ship_to_contact
			, @v_vchShipToPhoneNumber = obMS.ship_to_phone
			, @v_vchBillToCode = obMS.bill_to_code
			, @v_vchBillToName = obMS.bill_to_name
			, @v_vchBillToAddr1 = obMS.bill_to_address_line_1
			, @v_vchBillToAddr2 = obMS.bill_to_address_line_2
			, @v_vchBillToAddr3 = obMS.bill_to_address_line_3
			, @v_vchBillToCity = obMS.bill_to_city
			, @v_vchBillToProvince = obMS.bill_to_province
			, @v_vchBillToPostalCode = obMS.bill_to_postal_code
			, @v_vchBillToCountry = obMS.bill_to_country
			, @v_vchBillToCountryName = obMS.bill_to_country_name
			, @v_vchBillToContactName = obMS.bill_to_contact_name
			, @v_vchBillToPhoneNumber = obMS.bill_to_phone_number
			, @v_vchTrackingNo = obMS.tracking_number
			, @v_vchToWarehouseID = CONVERT(NVARCHAR(50),obMS.department)		--Warehouse สำหรับ Auto Insert Inbound
			, @v_vchCustomerOrderNumber = obMS.customer_order_number
			, @v_vchLoadID = obMS.load_id 
			, @v_dtDeliveryDatePlan = CONVERT(DATE,obMS.delivery_date_plan)
			, @v_dtShipDatePlan = obMS.ship_date_plan
			, @v_vchPickType = obMS.pick_type
			, @v_vchHUDF1 = obMS.user_def1
			, @v_vchHUDF2 = obMS.user_def2
			, @v_vchHUDF3 = obMS.user_def3
			, @v_vchHUDF4 = obMS.user_def4
			, @v_vchHUDF5 = obMS.user_def5
			, @v_vchHUDF6 = obMS.user_def6
			, @v_fltHUDF7 = obMS.user_def7
			, @v_fltHUDF8 = obMS.user_def8
			, @v_dtpHUDF9 = obMS.user_def9
			, @v_dtpHUDF10 = obMS.user_def10 
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		WHERE obMS.wh_master_id = @in_vchWhMasterID 
		AND obMS.outbound_order_master_id = @in_vchOutboundMasterID
		
		IF @in_vchOutboundMasterID IS NULL 
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF(@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'CHECK_FULL_SHIP' AND is_active = 'YES') = 'YES'
			BEGIN
				IF EXISTS (SELECT outbound_order_detail_id FROM t_wms_outbound_detail WHERE ISNULL(quantity_stage,0) < ISNULL(quantity_order,0) AND outbound_order_master_id = @in_vchOutboundMasterID)
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHIP_QTYORDER_NOT_EQUAL_QTYPICK';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		IF @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_OUTBOUND_PACKING' AND is_active = 'YES')
			BEGIN
				--ถ้าจะ Ship Qty Pick = Qty Pack = Qty DO ถึงจะยอม
				--Check Qty Pick <> Qty Pack
				IF EXISTS (SELECT pickDT.outbound_pick_detail_id
							FROM t_wms_outbound_pick_master pickMS 
							LEFT JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id 
							WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID
							AND ISNULL(pickDT.quantity_pack,0) < ISNULL(pickDT.quantity_pick,0))
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHIP_QTYPICK_NOT_EQUAL_QTYPACK';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--For POD
		IF (@RulePOD = 'YES')
			BEGIN
				SELECT @v_vchRouteCode = route_code
					, @v_vchRouteName = route_name
					, @v_vchCustUdf1 = user_def1	--Pallet Type
				FROM t_wms_customer 
				WHERE customer_id = @v_vchCustomerID
				AND owner_id = @v_vchOwnerID
				AND is_active = 'YES'
				IF ISNULL(@v_vchRouteCode,'') = ''
					BEGIN
						SET @out_ErrorCode = 'ROUTE_CODE_EMPTY';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		--------------------------------------------------
		-- Set Tran Type
		--------------------------------------------------
		IF (@v_vchOrderType  IN (SELECT TOP 1 value from t_wms_rule WHERE rule_code = 'BLIND_PICK_ORDER_TYPE' AND is_active = 'YES'))
	   		BEGIN
		        SET @v_vchTranType ='BLIND_PICK'	
			END
		ELSE
		    BEGIN
				SET @v_vchTranType ='OO_SHIP'
			END

		--------------------------------------------------
		-- Set Sub Tran Type
		--------------------------------------------------
		IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_INTERFACE' AND is_active = 'YES'))
			BEGIN
				--Get Host ID
				EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT
				SET @v_vchSubTranType = 'CONFIRM_TO_ERP';
			END
		ELSE
			BEGIN
				SET @v_vchSubTranType = 'CONFIRM_SHIP';
			END

		--------------------------------------------------
		--Get Outbound Pick MasterID
		--------------------------------------------------
		SELECT TOP 1 @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @in_vchOutboundMasterID

		--------------------------------------------------
		-- Check Staging before ship
		--------------------------------------------------
		IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) <> ISNULL(quantity_stage,0) AND is_override = 'NO')
		BEGIN
			SET @out_ErrorCode = 'INFO-NOT-PUT-ON-STAGING';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

		--------------------------------------------------
		-- Check allow shot ship or not allow shot ship
		--------------------------------------------------
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK' AND is_active = 'YES') = 'NO'
			 AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHORT_PICK_BY_ORDER_TYPE' AND is_active = 'YES'))
			BEGIN
				--ห้าม short ship
				DECLARE @v_fltChkQtyForShip  FLOAT = 0
				DECLARE @v_fltChkSumQtyOrder FLOAT = 0
				IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_SHIP_ON_DOCK_DOOR' AND is_active = 'YES') = 'YES' 
					 AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_MVT_IS_SHIP_ON_STAG' AND is_active = 'YES'))
					BEGIN
						SELECT @v_fltChkQtyForShip = SUM(quantity_load)
							,@v_fltChkSumQtyOrder = SUM(quantity_order)
						FROM t_wms_outbound_detail  
						WHERE outbound_order_master_id = @in_vchOutboundMasterID  
					END
				ELSE
					BEGIN
						SELECT @v_fltChkQtyForShip = SUM(quantity_pick)
							,@v_fltChkSumQtyOrder = SUM(quantity_order)
						FROM t_wms_outbound_detail  
						WHERE outbound_order_master_id = @in_vchOutboundMasterID  
					END
				IF (ROUND(@v_fltChkQtyForShip,@Round) < ROUND(@v_fltChkSumQtyOrder,@Round))
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHOT_PICK_AND_SHIP'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				----------------------------------------------
				-- Check Checker (Load) Quantity Plan = Quantity Load
				----------------------------------------------
				IF @v_vchWarehouse IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_CHECKER_WAREHOUSE' AND is_active = 'YES')
					BEGIN
						IF (@v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_CHECKER_ORDER_TYPE' AND is_active = 'YES'))
							BEGIN
								DECLARE @v_fltCheckQtyPlan FLOAT = 0;
								DECLARE @v_fltCheckQtyLoad FLOAT = 0;
								SELECT @v_fltCheckQtyPlan = ROUND(SUM(pickDT.quantity_plan),@Round)
									, @v_fltCheckQtyLoad = ROUND(SUM(pickDT.quantity_load),@Round)
								FROM t_wms_outbound_pick_detail pickDT
								WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID
								AND is_override = 'NO'
								IF (ROUND(@v_fltCheckQtyPlan,@Round) <> ROUND(@v_fltCheckQtyLoad,@Round))
									BEGIN
										SET @out_ErrorCode = 'ORDER_NOT_LOADED_CANNOT_SHIP';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END
					END
			END
		ELSE
			BEGIN
				--Short Ship ได้
				--Check Checker (Load) Quantity stage = Quantity Load
				IF @v_vchWarehouse IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_CHECKER_WAREHOUSE' AND is_active = 'YES')
					BEGIN
						IF (@v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_CHECKER_ORDER_TYPE' AND is_active = 'YES'))
							BEGIN
								DECLARE @v_fltChkQtyStage FLOAT = 0;
								DECLARE @v_fltChkQtyLoad  FLOAT = 0;
								SELECT @v_fltChkQtyStage = ROUND(SUM(pickDT.quantity_stage),@Round)
									, @v_fltChkQtyLoad = ROUND(SUM(pickDT.quantity_load),@Round)
								FROM t_wms_outbound_pick_detail pickDT
								WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID
								AND is_override = 'NO'

								IF (ROUND(@v_fltChkQtyStage,@Round) <> ROUND(@v_fltChkQtyLoad,@Round))
									BEGIN
										SET @out_ErrorCode = 'ORDER_NOT_LOADED_CANNOT_SHIP';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END
					END
			END

		-- 2014-01-29 get location for order type borrow
		IF (@v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_ORDER_TYPE_FOR_BORROW' AND is_active = 'YES'))
			BEGIN
				SET @RuleIsBorrow = 'YES'
				SELECT TOP 1 @v_intDueDate = value FROM t_wms_rule WHERE rule_code = 'RULE_OUTBOUND_BORROW_DUEDATE' AND is_active = 'YES'
				IF (ISNULL(@v_intDueDate,0) = 0)
					SET @v_intDueDate = 15;
			END		

	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;
		
		UPDATE t_wms_outbound_pick_master SET pick_list_status = 'SHIP' WHERE outbound_order_master_id = @in_vchOutboundMasterID

		UPDATE t_wms_outbound_master
		SET order_status = 'SHIP'
			,carrier_id = @in_vchCarrierID
			,truck_type_id = @v_vchTruckTypeID
			,truck_no = @in_vchTruckNumber  
			,driver_license = @in_vchDriverLicense
			,ship_date_actual = @in_dtShipDateActual  --Mai[2013-09-12] เอา Ship Date Actual ตัวเดียวกับที่ส่ง Interface
			,seal_no = @in_vchSealNumber
			,container_no = @in_vchContainerNo
		WHERE outbound_order_master_id = @in_vchOutboundMasterID
		AND wh_master_id = @in_vchWhMasterID

		/*---------------Auto Insert Inbound Master----------------*/
		DECLARE @v_vchInboundMasterID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchInboundOrderNumber NVARCHAR(50) = NULL 
		DECLARE @v_vchToWarehouseGUID	UNIQUEIDENTIFIER = NULL
		DECLARE @v_vchToWarehouse		VARCHAR(40) = NULL
		DECLARE @v_fltLastNumber		INT = 0
		DECLARE @v_fltNextNumber		INT = 0
		DECLARE @v_vchMaxOrderNo		NVARCHAR(50) = NULL
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_INSERT_INBOUND' AND is_active = 'YES') = 'YES' 
			AND @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'))
			BEGIN
				SET @v_vchInboundOrderNumber = 'TRF' + @v_vchOrderNumber
				SELECT @v_vchMaxOrderNo = MAX(REPLACE(inbound_order_number,@v_vchInboundOrderNumber,''))
				FROM t_wms_inbound_master
				WHERE REPLACE(inbound_order_number,REPLACE(inbound_order_number,@v_vchInboundOrderNumber,''),'') = @v_vchInboundOrderNumber

				IF LEN(ISNULL(@v_vchMaxOrderNo,'')) = 4 AND SUBSTRING(ISNULL(@v_vchMaxOrderNo,''),1,1) = '-'
					BEGIN
						SET @v_fltLastNumber = CONVERT(INT,RIGHT(ISNULL(@v_vchMaxOrderNo,''),3))
					END
				ELSE
					BEGIN
						SET @v_fltLastNumber = 0
					END

				SET @v_fltNextNumber = @v_fltLastNumber + 1;
				SET	@v_vchInboundOrderNumber = @v_vchInboundOrderNumber + '-' +  RIGHT('000' + CONVERT(VARCHAR(20),@v_fltNextNumber),3)

				SELECT @v_vchToWarehouseGUID = wh_master_id
					,@v_vchToWarehouse = wh_id
				FROM t_wms_wh 
				WHERE CONVERT(VARCHAR(40), wh_master_id) = @v_vchToWarehouseID
				AND is_active = 'YES'
				IF @v_vchToWarehouseGUID IS NULL
					BEGIN
						SET @out_ErrorCode = 'WAREHOUSE_NOT_FOUND'
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchToWarehouse,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END

				SELECT @v_vchInboundMasterID = inbound_order_master_id FROM t_wms_inbound_master WHERE wh_master_id = @v_vchToWarehouseGUID AND inbound_order_number = @v_vchInboundOrderNumber
				IF @v_vchInboundMasterID IS NULL
				BEGIN
					DECLARE @v_vchInboundOrderType NVARCHAR(25) = NULL
					SELECT TOP 1 @v_vchInboundOrderType = value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_FOR_INSERT_INBOUND' AND is_active = 'YES'

					SET @v_vchInboundMasterID = NEWID();
					--Insert Master
					INSERT INTO [dbo].[t_wms_inbound_master]
							([inbound_order_master_id]
							,[wh_master_id]
							,[inbound_order_number]
							,[owner_id]
							,[order_type]
							,[order_status]
							,[wh_id]
							,[owner_code]
							,[reference_number]
							,[bom_inbound_order_master_id]
							,[create_by]
							,[create_date])
						VALUES
							(@v_vchInboundMasterID
							,@v_vchToWarehouseGUID
							,@v_vchInboundOrderNumber
							,@v_vchOwnerID
							,@v_vchInboundOrderType
							,'OPEN'
							,@v_vchToWarehouse
							,@v_vchOwnerCode
							,@v_vchOrderNumber
							,NULL
							,@in_vchUserID
							,GETDATE())
				END
		END

		--Update Ship Confrim
		IF ((SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_SHIP_ON_DOCK_DOOR' AND is_active = 'YES') = 'YES'
		     AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_MVT_IS_SHIP_ON_STAG' AND is_active = 'YES'))
			BEGIN -- SHIP ON DOCK DOOR
				IF (@RulePickPack = 'YES')
					BEGIN
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,outbound_pack_detail_id
								,line_number
								,dock_door_id
								,location
								,dock_door_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_load,0) - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pack_detail 
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_load,0) - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
							AND load_status = 'YES'
							AND dock_door_id IS NOT NULL
					END
				ELSE
					BEGIN
						--หากไม่ได้เปิด rule pick_pack แต่มีการ pack ต้องข้อมูลที่ pack ในการ 
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,NULL
								,line_number
								,dock_door_id
								,location
								,dock_door_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_load,0)  - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pick_mini  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_load,0)  - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
							AND load_status = 'YES'
							AND dock_door_id IS NOT NULL
					END
			End
		ELSE
			BEGIN -- SHIP ON STAGING
				IF (@RulePickPack = 'YES')
					BEGIN
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,outbound_pack_detail_id
								,line_number
								,staging_location_id
								,location
								,staging_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom_prompt
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone
							FROM v_wms_outbound_pack_detail  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID
							AND ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
					END
				ELSE
					BEGIN
						--หากไม่ได้เปิด rule pick_pack แต่มีการ pack ต้องข้อมูลที่ pack ในการ ship
						DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
							SELECT outbound_order_detail_id
								,outbound_pick_detail_id
								,NULL
								,line_number
								,staging_location_id
								,location
								,staging_lpn
								,wh_item_master_id
								,item_master_id
								,item_number
								,default_item_status
								,quantity_order
								,ISNULL(quantity_stage,0)  - ISNULL(quantity_ship,0)
								,item_uom_id
								,uom
								,lot_number
								,[expiry_date]
								,serial_number
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,lot_control
								,expiry_date_control
								,sn_control
								,attribute1_control
								,attribute2_control
								,attribute3_control
								,attribute4_control
								,attribute5_control
								,receive_date
								,erp_location
								,zone 
							FROM v_wms_outbound_pick_mini  
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND ISNULL(quantity_stage,0)  - ISNULL(quantity_ship,0) > 0
							AND is_override = 'NO'
							AND pick_status = 'YES'
					END
			End
	    
		OPEN OutboundPickDetail_CURSOR
		FETCH NEXT FROM OutboundPickDetail_CURSOR INTO @v_vchOutboundOrderDetailID,@v_vchOutboundPickDetailID,@v_vchOutboundPackDetailID,@v_vchLineNumber,@v_vchLocationMasterID,@v_vchLocationForPick,@v_vchLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
													,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityShip,@v_vchItemUOMID,@v_vchUOM,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
													,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control,@v_dtReceiveDate ,@v_vchERPLocationForPick,@v_vchZone
		IF (@@ROWCOUNT > 0)
			BEGIN
				IF (@RuleIsBorrow = 'YES')
					BEGIN-- Insert into outbound borrow master
						SET @v_vchOutboundBorrowMasterID = NEWID()
						INSERT INTO t_wms_outbound_borrow_master
							(outbound_borrow_master_id
								, wh_master_id
								, outbound_borrow_number
								, owner_id, order_type
								, order_status
								, order_date
								, description
								, department
								, customer_id
								, customer_code
								, customer_name
								, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
								, create_by)
							SELECT @v_vchOutboundBorrowMasterID
								, wh_master_id
								, outbound_order_number
								, owner_id
								, order_type
								, order_status
								, order_date
								, description
								, department
								, customer_id
								, customer_code
								, customer_name
								, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
								, @in_vchUserID 
							FROM t_wms_outbound_master 
							WHERE outbound_order_master_id = @in_vchOutboundMasterID
					END

				WHILE @@FETCH_STATUS = 0  
					BEGIN-- Ship Confirm.Update Inventory data
						BEGIN --Parameter
							DECLARE @v_dtExpiryDate		DATE = NULL
							DECLARE @v_vchFromLocation	NVARCHAR(50) = NULL
							DECLARE @v_vchInfPlanUomID  UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchInfPlanUom    VARCHAR(40) = NULL
							DECLARE @v_fltInfQuantity   FLOAT = NULL
							DECLARE @v_vchInfConFactor  FLOAT = NULL
							DECLARE @v_vchInventoryID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchAttributeGroupID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_vchInventoryStatusID	UNIQUEIDENTIFIER = NULL
							DECLARE @v_fltInventoryQty	FLOAT = NULL
							DECLARE @v_fltAfterInvQuantity FLOAT = NULL
							DECLARE @v_dtMfgDate DATE = NULL
						
							--For Interface
							DECLARE @v_vchDUDF1  NVARCHAR(255)
							DECLARE @v_vchDUDF2  NVARCHAR(255)
							DECLARE @v_vchDUDF3  NVARCHAR(255)
							DECLARE @v_vchDUDF4  NVARCHAR(255)
							DECLARE @v_vchDUDF5  NVARCHAR(255)
							DECLARE @v_vchDUDF6  NVARCHAR(255)
							DECLARE @v_fltDUDF7  FLOAT
							DECLARE @v_fltDUDF8  FLOAT
							DECLARE @v_dtpDUDF9  DATETIME
							DECLARE @v_dtpDUDF10 DATETIME
						END
						IF ISNULL(@v_vchExpiryDate,'') <> ''
							SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate);
						SET @v_fltQuantityShip = ROUND(@v_fltQuantityShip,@Round) 
						 
						SELECT @v_vchDUDF1 = dt.user_def1
							,@v_vchDUDF2 = dt.user_def2
							,@v_vchDUDF3 = dt.user_def3
							,@v_vchDUDF4 = dt.user_def4
							,@v_vchDUDF5 = dt.user_def5
							,@v_vchDUDF6 = dt.user_def6
							,@v_fltDUDF7 = dt.user_def7
							,@v_fltDUDF8 = dt.user_def8
							,@v_dtpDUDF9 = dt.user_def9
							,@v_dtpDUDF10 = dt.user_def10
							,@v_vchLineNumber = dt.line_number
							,@v_fltQuantityOrder = dt.quantity_order
							,@v_vchInfPlanUomID = uom.item_uom_id
							,@v_vchInfPlanUom = uom.uom
							,@v_vchInfConFactor = uom.conversion_factor
						FROM t_wms_outbound_detail dt
						LEFT JOIN t_wms_item_uom uom ON dt.interface_plan_uom_id = uom.item_uom_id
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID

						IF @v_vchOutboundOrderDetailID IS NOT NULL
							BEGIN
								SET @v_fltInfQuantity = ROUND((@v_fltQuantityShip / @v_vchInfConFactor),@Round)
							END
						ELSE
							BEGIN
								SET @v_fltInfQuantity = @v_fltQuantityShip
								SET @v_vchInfPlanUom = @v_vchUOM
							END

						-- 1 Order มี 1 Dock Door
						SELECT @v_vchFromLocation = location FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location_id = @v_vchLocationMasterID

						-------------------------------------------------
						--Plan เก็บเป็นหน่วย Base อยู่แล้ว
						--Get data for calculate volumn & weight
						-------------------------------------------------
						SELECT @v_fltWidth = ISNULL(width,0)
							,@v_fltLength = ISNULL(length,0)
							,@v_fltHeight = ISNULL(height,0)
							,@v_fltGrossWeight = ISNULL(gross_weight,0)
							,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
							,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
						FROM t_wms_item_uom 
						WHERE item_uom_id = @v_vchItemUOMID 
						AND primary_uom = 'YES' 
						AND is_active = 'YES'

						IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQuantityShip,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQuantityShip,2)
							END

						-------------------------------------------------------
						-- check ว่า serial ที่ลานจ่าย หรือ dock door มีของครบหรือป่าว
						-------------------------------------------------------
						IF (@v_vchSerialControl = 'FULL')
							BEGIN
								-- check ว่า serial ที่ลานจ่าย หรือ dock door มีของครบหรือป่าว
								IF NOT EXISTS(SELECT invAttr.attribute_value FROM t_wms_inventory inv 
											INNER JOIN t_wms_inventory_attribute invAttr ON inv.inventory_id = invAttr.inventory_id
											WHERE invAttr.inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type WHERE inv_attribute_type = 'SERIAL')
											AND inv.location_id = @v_vchLocationMasterID
											AND ISNULL(inv.lpn,'') = ISNULL(@v_vchLPN,'')
											AND ISNULL(invAttr.attribute_value,'') = ISNULL(@v_vchSerialNumber,''))
									BEGIN
										SET @out_ErrorCode = '999';
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_PICK_NOT_MATCH_ON_INVENTORY',(select dbo.usf_get_locale_id(@in_vchUserID)),null,@v_vchLPN,'@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							END

						DECLARE @v_vchDefaultItemStatusID	uniqueidentifier = null
						SELECT @v_vchDefaultItemStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchDefaultItemStatus
						SELECT @v_vchInventoryID = inventory_id
							,@v_vchAttributeGroupID = attribute_group_id
							,@v_vchInventoryStatusID = inventory_status_id
							,@v_fltInventoryQty = quantity
							,@v_dtMfgDate = mfg_date
						FROM v_wms_inventory_data_serial_by_id
						WHERE wh_master_id = @in_vchWhMasterID 
						AND owner_id = @v_vchOwnerID
						AND location_id = @v_vchLocationMasterID 
						AND wh_item_master_id = @v_vchWhItemMasterID 
						AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'') 
						AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
						AND ISNULL([expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
						AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
						AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
						AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
						AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
						AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
						AND (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(@v_vchSerialNumber,'') END)
						AND inventory_status_id = @v_vchDefaultItemStatusID
						AND receive_date = @v_dtReceiveDate
						AND ISNULL(quantity,0) > 0 
						
						---------------------------------------
						-- Check Inventory
						---------------------------------------
						IF (@v_vchInventoryID IS NULL)
						BEGIN
							SET @out_ErrorCode = '999'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,@v_vchFromLocation,'@param3',@v_vchLPN,'@param5')
							GOTO WRITE_PROC;
						END
						
						---------------------------------------
						-- Check Quantity
						---------------------------------------
						IF (@v_fltInventoryQty < @v_fltQuantityShip)
						BEGIN
							SET @out_ErrorCode = '999'
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchFromLocation,'@param3','@param4','@param5')
							GOTO WRITE_PROC;					
						END
							
						--------------------------------------------
						--Manage source inventory
						--------------------------------------------
						BEGIN
							--Inventory
							UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							
							--Inventory attribute for serial
							IF (@v_vchSerialControl = 'FULL')
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID 
								AND attribute_value = @v_vchSerialNumber
								AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')												
							END

							--Inventory attribute
							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
							BEGIN
								UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQuantityShip,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID
								AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
							END
						
							DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 
							DELETE FROM t_wms_inventory WHERE quantity <= 0 AND inventory_id = @v_vchInventoryID 

							--Update Volumn & Weight in from location
							IF @v_vchLocationMasterID IS NOT NULL
							BEGIN
								UPDATE [dbo].[t_wms_location]
									SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
									, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
									, update_date = GETDATE()  
									, [update_by] = @in_vchUserID   
									WHERE [location_id] = @v_vchLocationMasterID
							END

							
						END
																
						IF (@RuleIsBorrow = 'YES')
							BEGIN-- ship confirm of borrow type
								DECLARE @v_vchHoldInventoryStatusID UNIQUEIDENTIFIER = NULL
								DECLARE @v_vchLocationBorrowID UNIQUEIDENTIFIER = NULL
								DECLARE @v_vchLocationBorrow NVARCHAR(50) = NULL 

								-- select location from item detail
								SELECT @v_vchHoldInventoryStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = 'Hold' AND is_active = 'YES'
								SELECT @v_vchLocationBorrow = user_def1 FROM t_wms_item WHERE item_master_id = @v_vchItemMasterID
								IF (ISNULL(@v_vchLocationBorrow,'') <> '')
									BEGIN
										SELECT @v_vchLocationBorrowID = location_id FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location = @v_vchLocationBorrow AND is_active = 'YES'
									END
								ELSE
									BEGIN
										SELECT TOP 1 @v_vchLocationBorrow = location, @v_vchLocationBorrowID = location_id FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND loc_type = 'BORROW' AND is_active = 'YES'
									END

								IF (@v_vchLocationBorrow IS NULL)
									BEGIN
										SET @out_ErrorCode = '999'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_BORROW_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END
							 
								-- Manage Inventory Move to Borrow Location
								BEGIN 
									EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
															 ,@in_vchWhMasterID			= @in_vchWhMasterID
															 ,@in_vchWhID				= @v_vchWarehouse
															 ,@in_vchOwnerID			= @v_vchOwnerID
															 ,@in_vchInventoryType		= 'INVENTORY'
															 ,@in_vchLocationID			= @v_vchLocationBorrowID
															 ,@in_vchParentLPN			= NULL
															 ,@in_vchLPN				= @v_vchLPN
															 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
															 ,@in_vchItemMasterID		= @v_vchItemMasterID
															 ,@in_vchItemNumber			= @v_vchItemNumber
															 ,@in_fltQuantity			= @v_fltQuantityShip
															 ,@in_fltQtyAllocate		= 0
															 ,@in_fltQtyIncoming		= 0
															 ,@in_vchPrimaryItemUomID	= @v_vchItemUOMID
															 ,@in_vchInvStatusID		= @v_vchHoldInventoryStatusID
															 ,@in_vchLotNumber			= @v_vchLotNumber
															 ,@in_vchExpiryDate			= @v_vchExpiryDate
															 ,@in_vchSerialNumber		= @v_vchSerialNumber
															 ,@in_vchAttribute1			= @v_vchAttribute1
															 ,@in_vchAttribute2			= @v_vchAttribute2
															 ,@in_vchAttribute3			= @v_vchAttribute3
															 ,@in_vchAttribute4			= @v_vchAttribute4
															 ,@in_vchAttribute5			= @v_vchAttribute5
															 ,@in_dReceiveDate			= @v_dtReceiveDate
															 ,@in_dtMfgDate				= @v_dtMfgDate
															 ,@in_vchDeviceID			= @in_vchDeviceID
															 ,@in_vchUserID				= @in_vchUserID
															 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
															 ,@out_ErrorCode			= @out_ErrorCode OUTPUT
															 ,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END

								-- insert into outbound borrow detail
								IF NOT EXISTS(SELECT outbound_borrow_detail_id from t_wms_outbound_borrow_detail 
												WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID 
												AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
												AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpiryDate,'')
												AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
												AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
												AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
												AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
												AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
												AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,''))
									BEGIN -- NOT SAME DATA
										INSERT INTO t_wms_outbound_borrow_detail
											(outbound_borrow_detail_id
											, outbound_borrow_master_id
											, outbound_order_detail_id
											, wh_item_master_id
											, line_number
											, customer_id
											, customer_code
											, customer_name
											, quantity_order
											, quantity_return
											, due_date
											, item_uom_id
											, item_status
											, location_id
											, parent_lpn
											, lpn
											, lot_number
											, expiry_date
											, serial_number
											, [attribute1]
											, [attribute2]
											, [attribute3]
											, [attribute4]
											, [attribute5]
											, remark
											, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
											, create_by)
										SELECT NEWID()
											, @v_vchOutboundBorrowMasterID
											, @v_vchOutboundOrderDetailID
											, @v_vchWhItemMasterID
											, @v_vchLineNumber
											, @v_vchCustomerID
											, @v_vchCustomerCode
											, @v_vchCustomerName
											, @v_fltQuantityShip
											, 0
											, DATEADD(dd,@v_intDueDate,GETDATE())
											, item_uom_id
											, 'Borrow'
											, @v_vchLocationBorrowID
											, null --[parent_lpn]
											, null --[lpn]
											, @v_vchLotNumber
											, @v_vchExpiryDate
											, @v_vchSerialNumber
											, @v_vchAttribute1
											, @v_vchAttribute2
											, @v_vchAttribute3
											, @v_vchAttribute4
											, @v_vchAttribute5
											, null --[remark]
											, user_def1, user_def2, user_def3, user_def4, user_def5, user_def6, user_def7, user_def8, user_def9, user_def10
											, @in_vchUserID
										FROM t_wms_outbound_detail 
										WHERE outbound_order_master_id = @in_vchOutboundMasterID 
										AND outbound_order_detail_id = @v_vchOutboundOrderDetailID
									END
								ELSE
									BEGIN
										UPDATE t_wms_outbound_borrow_detail SET quantity_order = ROUND(ISNULL(quantity_order,0) + @v_fltQuantityShip,@Round)
										WHERE outbound_borrow_master_id = @v_vchOutboundBorrowMasterID 
										AND outbound_order_detail_id = @v_vchOutboundOrderDetailID
									END

								--Write Log Move to Borrow Location
								SET @v_dtEndTranDate = GETDATE();
								EXEC usp_LogManager
										 @in_vchApplicationID = @in_vchApplicationID
										,@in_vchAppName = @v_vchApplicationName
										,@in_vchDevice = @in_vchDeviceID
										,@in_vchUserID = @in_vchUserID
										,@in_vchLogType = 'TRANSACTION'
										,@in_vchTranType = 'OO_SHIP'
										,@in_vchSubTranType = 'MOVE_BORROW'
										,@in_dtStartTranDate = @v_dtStartTranDate
										,@in_dtEndTranDate = @v_dtEndTranDate
										,@in_vchWhID = @v_vchWarehouse
										,@in_vchToWhID = @v_vchWarehouse
										,@in_vchOwner = @v_vchOwnerCode
										,@in_vchToOwner = @v_vchOwnerCode
										,@in_vchLocation = @v_vchLocationForPick
										,@in_vchToLocation = @v_vchLocationBorrow
										,@in_vchItemNumber = @v_vchItemNumber
