												,@in_vchCustomerCode		= @v_vchCustomerCode
												,@in_vchSupplierCode		= NULL
												,@in_dtShipDateActual		= @in_dtShipDateActual
												,@in_dtDeliveryDatePlan		= @v_dtDeliveryDatePlan 

												,@in_vchShipToCode			= @v_vchShipToCode		
												,@in_vchShipToName			= @v_vchShipToName		
												,@in_vchShipToAddr1			= @v_vchShipToAddr1		
												,@in_vchShipToAddr2			= @v_vchShipToAddr2		
												,@in_vchShipToAddr3			= @v_vchShipToAddr3		
												,@in_vchShipToCity			= @v_vchShipToCity		
												,@in_vchShipToProvince		= @v_vchShipToProvince	
												,@in_vchShipToPostalCode	= @v_vchShipToPostalCode	
												,@in_vchShipToCountry		= @v_vchShipToCountry		
												,@in_vchShipToCountryName	= @v_vchShipToCountryName 
												,@in_vchShipToContactName	= @v_vchShipToContactName 
												,@in_vchShipToPhoneNumber	= @v_vchShipToPhoneNumber 
												,@in_vchBillToCode			= @v_vchBillToCode		
												,@in_vchBillToName			= @v_vchBillToName		
												,@in_vchBillToAddr1			= @v_vchBillToAddr1		
												,@in_vchBillToAddr2			= @v_vchBillToAddr2		
												,@in_vchBillToAddr3			= @v_vchBillToAddr3		
												,@in_vchBillToCity			= @v_vchBillToCity		
												,@in_vchBillToProvince		= @v_vchBillToProvince	
												,@in_vchBillToPostalCode	= @v_vchBillToPostalCode	
												,@in_vchBillToCountry		= @v_vchBillToCountry		
												,@in_vchBillToCountryName	= @v_vchBillToCountryName 
												,@in_vchBillToContactName	= @v_vchBillToContactName 
												,@in_vchBillToPhoneNumber	= @v_vchBillToPhoneNumber
												,@in_vchComment				= @v_vchOutboundOrderDetailID
												,@in_vchControlValue1		= @v_vchERPSourceLocation
												,@in_vchControlValue2		= @v_vchERPDestLocation
												,@in_vchErrorCode = @out_ErrorCode OUTPUT
												,@in_vchMessage	= @out_ErrorMessage OUTPUT
										IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
											BEGIN
												GOTO WRITE_PROC;
											END

										-- For Dashboard Consignment
										EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
																		,@in_vchTransType	 = 'SHIP'
																		,@in_vchWhMasterID	 = @in_vchWhMasterID
																		,@in_vchOwnerID		 = @v_vchOwnerID
																		,@in_vchOwnerCode	 = @v_vchOwnerCode
																		,@in_vchLocationID	 = @v_vchLocationMasterID
																		,@in_vchItemMasterID = @v_vchItemMasterID
																		,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
																		,@in_vchToWhMasterID = @in_vchWhMasterID
																		,@in_vchToLocationID = @v_vchMoveToLocationID
																		,@in_vchToInvStatusID = @v_vchMoveToInvStatusID
																		,@in_fltQuantity	 = @v_fltQuantityShip
																		,@in_vchUserID		 = @in_vchUserID
										
									END
								ELSE
									BEGIN --Write Log of normal type (ship out)
										SET @v_dtEndTranDate = GETDATE();
										EXEC usp_LogManager 
											@in_vchApplicationID = @in_vchApplicationID
											,@in_vchAppName			= @v_vchApplicationName
											,@in_vchDevice			= @in_vchDeviceID
											,@in_vchUserID			= @in_vchUserID
											,@in_vchLogType			= 'TRANSACTION'
											,@in_vchTranType		= @v_vchTranType
											,@in_vchSubTranType		= @v_vchSubTranType
											,@in_vchDescription		= 'Comfirm ship'
											,@in_dtStartTranDate	= @v_dtStartTranDate
											,@in_dtEndTranDate		= @v_dtEndTranDate
											,@in_vchWhID			= @v_vchWarehouse
											,@in_vchToWhID			= NULL
											,@in_vchOwner			= @v_vchOwnerCode
											,@in_vchToOwner			= NULL
											,@in_vchLocation		= @v_vchFromLocation
											,@in_vchToLocation		= NULL
											,@in_vchItemNumber		= @v_vchItemNumber
											,@in_vchUOM				= @v_vchUOM
											,@in_vchBaseUOM			= @v_vchUOM
											,@in_fltQuantity		= @v_fltQuantityShip
											,@in_vchSerialNumber	= @v_vchSerialNumber
											,@in_fltAfterQuantity	= 0
											,@in_vchAfterUOM		= @v_vchUOM
											,@in_vchLotNumber		= @v_vchLotNumber
											,@in_vchAfterLotNumber	= NULL
											,@in_dtExpiryDate		= @v_dtExpiryDate
											,@in_dtAfterExpiryDate	= NULL
											,@in_vchAttribute1		= @v_vchAttribute1
											,@in_vchAfterAttribute1	= NULL
											,@in_vchAttribute2		= @v_vchAttribute2
											,@in_vchAfterAttribute2	= NULL
											,@in_vchAttribute3		= @v_vchAttribute3
											,@in_vchAfterAttribute3	= NULL
											,@in_vchAttribute4		= @v_vchAttribute4
											,@in_vchAfterAttribute4	= NULL
											,@in_vchAttribute5		= @v_vchAttribute5
											,@in_vchAfterAttribute5	= NULL
											,@in_vchLPN				= @v_vchLPN
											,@in_vchAfterLPN		= NULL
											,@in_vchStatus			= @v_vchDefaultItemStatus
											,@in_vchAfterStatus		= NULL
											,@in_vchOrderNumber		= @v_vchOrderNumber
											,@in_vchOrderStatus		= 'SHIP'
											,@in_vchOrderType		= @v_vchOrderType
											,@in_vchControlNumber	= @v_vchHostInterfaceID
											,@in_vchLineNumber		= @v_vchLineNumber
											,@in_vchOrderQuantity	= @v_fltQuantityOrder
											,@in_vchShortQuantity	= 0

											,@in_vchProcess			= @c_vchObjName
											,@in_dtProcessDateTime	= @v_dtProcessDateTime
											,@in_vchTrackingNumber	= @v_vchTrackingNo
											,@in_vchSealNumber		= @in_vchSealNumber
											,@in_vchContainerNo		= @in_vchContainerNo
											,@in_vchTrailerNumber	= @in_vchTruckNumber
											,@in_vchCarrierCode		= @v_vchCarrierCode
											,@in_vchEquipmentType	= @in_vchTruckType
											,@in_vchCDLLicense		= @in_vchDriverLicense

											,@in_vchHUDF1			= @v_vchHUDF1
											,@in_vchHUDF2			= @v_vchHUDF2
											,@in_vchHUDF3			= @v_vchHUDF3
											,@in_vchHUDF4			= @v_vchHUDF4
											,@in_vchHUDF5			= @v_vchHUDF5
											,@in_vchHUDF6			= @v_vchHUDF6
											,@in_fltHUDF7			= @v_fltHUDF7
											,@in_fltHUDF8			= @v_fltHUDF8
											,@in_dtpHUDF9			= @v_dtpHUDF9
											,@in_dtpHUDF10			= @v_dtpHUDF10

											,@in_vchDUDF1			= @v_vchDUDF1
											,@in_vchDUDF2			= @v_vchDUDF2
											,@in_vchDUDF3			= @v_vchDUDF3
											,@in_vchDUDF4			= @v_vchDUDF4
											,@in_vchDUDF5			= @v_vchDUDF5
											,@in_vchDUDF6			= @v_vchDUDF6		--@v_vchInfPlanUom		--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
											,@in_fltDUDF7			= @v_fltDUDF7		--@v_fltInfQuantity		--For Master Kool ส่งกลับหน่วยเดิมที่แผนส่งมา
											,@in_fltDUDF8			= @v_fltDUDF8
											,@in_dtpDUDF9			= @v_dtpDUDF9
											,@in_dtpDUDF10			= @v_dtpDUDF10
											,@in_vchZone			= @v_vchZone
											,@in_vchPickLocation	= @v_vchLocationForPick
											,@in_vchControlValue1   = @v_vchERPLocationForPick
											,@in_vchHostRecordID	= @v_vchHostInterfaceID
											,@in_dtPostingDate		= @in_dtShipDateActual
											,@in_dtReceiveDate		= @v_dtReceiveDate
											,@in_dtProductionDate	= @v_dtMfgDate
											,@in_vchCustomerCode	= @v_vchCustomerCode 
											,@in_dtShipDateActual	= @in_dtShipDateActual
											,@in_dtDeliveryDatePlan = @v_dtDeliveryDatePlan 

											,@in_vchShipToCode			= @v_vchShipToCode		
											,@in_vchShipToName			= @v_vchShipToName		
											,@in_vchShipToAddr1			= @v_vchShipToAddr1		
											,@in_vchShipToAddr2			= @v_vchShipToAddr2		
											,@in_vchShipToAddr3			= @v_vchShipToAddr3		
											,@in_vchShipToCity			= @v_vchShipToCity		
											,@in_vchShipToProvince		= @v_vchShipToProvince	
											,@in_vchShipToPostalCode	= @v_vchShipToPostalCode	
											,@in_vchShipToCountry		= @v_vchShipToCountry		
											,@in_vchShipToCountryName	= @v_vchShipToCountryName 
											,@in_vchShipToContactName	= @v_vchShipToContactName 
											,@in_vchShipToPhoneNumber	= @v_vchShipToPhoneNumber 
											,@in_vchBillToCode			= @v_vchBillToCode		
											,@in_vchBillToName			= @v_vchBillToName		
											,@in_vchBillToAddr1			= @v_vchBillToAddr1		
											,@in_vchBillToAddr2			= @v_vchBillToAddr2		
											,@in_vchBillToAddr3			= @v_vchBillToAddr3		
											,@in_vchBillToCity			= @v_vchBillToCity		
											,@in_vchBillToProvince		= @v_vchBillToProvince	
											,@in_vchBillToPostalCode	= @v_vchBillToPostalCode	
											,@in_vchBillToCountry		= @v_vchBillToCountry		
											,@in_vchBillToCountryName	= @v_vchBillToCountryName 
											,@in_vchBillToContactName	= @v_vchBillToContactName 
											,@in_vchBillToPhoneNumber	= @v_vchBillToPhoneNumber
											,@in_vchComment				= @v_vchOutboundOrderDetailID
											,@in_vchErrorCode			= @out_ErrorCode OUTPUT
											,@in_vchMessage				= @out_ErrorMessage OUTPUT
										IF (@out_ErrorCode <> '0' AND @out_ErrorCode <> '')
											BEGIN
												GOTO WRITE_PROC;
											END

										-- For Dashboard
										EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT'
																		,@in_vchTransType	 = 'SHIP'
																		,@in_vchWhMasterID	 = @in_vchWhMasterID
																		,@in_vchOwnerID		 = @v_vchOwnerID
																		,@in_vchOwnerCode	 = @v_vchOwnerCode
																		,@in_vchLocationID	 = @v_vchLocationMasterID
																		,@in_vchItemMasterID = @v_vchItemMasterID
																		,@in_vchInvStatusID	 = @v_vchDefaultItemStatusID
																		,@in_vchToWhMasterID = NULL
																		,@in_vchToLocationID = NULL
																		,@in_vchToInvStatusID = NULL
																		,@in_fltQuantity	 = @v_fltQuantityShip
																		,@in_vchUserID		 = @in_vchUserID
									END
							END

						UPDATE t_wms_outbound_detail SET 
							item_status = 'SHIP'
							,quantity_ship = ROUND(ROUND(quantity_ship,@Round) + ROUND(@v_fltQuantityShip,@Round),@Round)  
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID
					          
						UPDATE t_wms_outbound_pick_detail SET 
							ship_status = 'YES' 
							,quantity_ship = ROUND(ROUND(quantity_ship,@Round) + ROUND(@v_fltQuantityShip,@Round),@Round) 
							,user_def1 = @v_vchOrderNumber
							,user_def9 = @v_dtShipDatePlan
						WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

						/*---------------Insert Inbound Detail----------------*/
						IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_INSERT_INBOUND' AND is_active = 'YES') = 'YES' 
							AND @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'))
							BEGIN
								DECLARE @v_vchItemGUID			UNIQUEIDENTIFIER = NULL		-- item master id ของ wh เดิม
								DECLARE @v_vchWhItemGUID		UNIQUEIDENTIFIER = NULL		-- wh item master id ของ wh ใหม่
								DECLARE @v_vchIBItemNumber		NVARCHAR(50) = NULL
								DECLARE @v_vchGrade				NVARCHAR(40) = NULL
								DECLARE @v_vchPrice				FLOAT = NULL
								DECLARE @v_vchIBUom				VARCHAR(20) = NULL
								DECLARE @v_intLine				INT = 0
								DECLARE @v_vchIBLineNumber		VARCHAR(10) = NULL
									
								--Get item number of old warehouse
								SELECT @v_vchItemGUID = item_master_id FROM t_wms_wh_item  WHERE wh_item_master_id = @v_vchWhItemMasterID	

								--Get data wh item master id in new warehouse
								SELECT @v_vchGrade = item.grade
									,@v_vchPrice = item.price
									,@v_vchItemGUID = item.item_master_id
									,@v_vchWhItemGUID = whItem.wh_item_master_id
									,@v_vchIBItemNumber = item.item_number
									,@v_vchItemUOMID = uom.item_uom_id
									,@v_vchIBUom = uom.uom
								FROM t_wms_wh_item whItem
								INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
								INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
								WHERE item.item_master_id = @v_vchItemGUID
								AND whItem.wh_master_id = @v_vchToWarehouseGUID
								AND item.is_active = 'YES'

								IF @v_vchWhItemGUID IS NULL
									BEGIN
										SET @out_ErrorCode = 'NOT_FOUND_ITEM_MASTER'
										SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')
										GOTO WRITE_PROC;
									END

								SELECT @v_intLine = CONVERT(INT,MAX(line_number)) FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID
								SET @v_vchIBLineNumber = RIGHT('000000'+CONVERT(VARCHAR(20),ISNULL(@v_intLine,0) + 1),6)

								--Insert Detail
								INSERT INTO [dbo].[t_wms_inbound_detail]
											([inbound_order_master_id]
											,[wh_item_master_id]
											,[item_master_id]
											,[item_uom_id]
											,[item_number]
											,[line_number]
											,[quantity_order]
											,[quantity_receive]
											,[uom]
											,[item_status]
											,[default_item_status]
											,[price]
											,[grade]
											,[over_receipt_allowed]
											,[lot_number]
											,[expiry_date]
											,[serial_number]
											,[attribute1]
											,[attribute2]
											,[attribute3]
											,[attribute4]
											,[attribute5] 
											,[create_by]
											,[create_date])
										VALUES
											(@v_vchInboundMasterID		
											,@v_vchWhItemGUID
											,@v_vchItemGUID
											,@v_vchItemUOMID
											,@v_vchIBItemNumber
											,@v_vchIBLineNumber
											,ROUND(@v_fltQuantityShip,@Round)
											,0			--[quantity_receive]
											,@v_vchIBUom
											,'NEW'		--[item_status]
											,@v_vchDefaultItemStatus
											,@v_vchPrice
											,@v_vchGrade
											,'NO'		--[over_receipt_allowed]
											,@v_vchLotNumber
											,@v_vchExpiryDate
											,@v_vchSerialNumber
											,@v_vchAttribute1
											,@v_vchAttribute2
											,@v_vchAttribute3
											,@v_vchAttribute4
											,@v_vchAttribute5 
											,@in_vchUserID
											,GETDATE())
							END

						---------------------------------------------------
						-- Modern Trade : Insert into t_wms_shelf_life_tran
						---------------------------------------------------
						IF EXISTS(SELECT TOP 1 control_shelf_life FROM t_wms_customer WHERE customer_id = @v_vchCustomerID AND ISNULL(control_no_back_date,'NO') = 'YES')
							BEGIN
								IF NOT EXISTS(SELECT shelf_life_id FROM t_wms_shelf_life_tran WHERE customer_id = @v_vchCustomerID AND owner_id = @v_vchOwnerID AND item_master_id = @v_vchItemMasterID AND last_expiry_date_shipped = @v_vchExpiryDate)
									BEGIN
										INSERT INTO t_wms_shelf_life_tran(customer_id, item_master_id, owner_id, last_expiry_date_shipped, create_by)
										VALUES(@v_vchCustomerID,@v_vchItemMasterID,@v_vchOwnerID,@v_vchExpiryDate,@in_vchUserID)
									END
							END

					FETCH NEXT FROM OutboundPickDetail_CURSOR INTO @v_vchOutboundOrderDetailID,@v_vchOutboundPickDetailID,@v_vchOutboundPackDetailID,@v_vchLineNumber,@v_vchLocationMasterID,@v_vchLocationForPick,@v_vchLPN,@v_vchWhItemMasterID,@v_vchItemMasterID,@v_vchItemNumber
															,@v_vchDefaultItemStatus,@v_fltQuantityOrder,@v_fltQuantityShip,@v_vchItemUOMID,@v_vchUOM,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5
															,@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control,@v_dtReceiveDate,@v_vchERPLocationForPick,@v_vchZone
							
					END
			END
		ELSE
			BEGIN
				SET @out_ErrorCode = '999';
				SET @out_ErrorMessage = 'Not found data for ship';
				GOTO WRITE_PROC;
			END
		
		CLOSE OutboundPickDetail_CURSOR;  
		DEALLOCATE OutboundPickDetail_CURSOR; 
				
		-----------------------------------------------
		--Insert Bom Quantity Ship
		-----------------------------------------------
		EXEC usp_wms_calculate_outbound_bom @in_vchWhMasterID	    = @in_vchWhMasterID
											,@in_vchOwnerID		    = @v_vchOwnerID
											,@in_vchOutboundMasterID = @in_vchOutboundMasterID
											,@in_vchUserID			= @in_vchUserID
											,@out_ErrorCode			= @out_ErrorCode OUTPUT
											,@out_ErrorMessage		= @out_ErrorMessage OUTPUT
		IF (@out_ErrorCode <> '0')
			BEGIN 
				GOTO WRITE_PROC; 
			END

		-----------------------------------------------
		--Insert POD
		-----------------------------------------------
		IF (@RulePOD = 'YES')
		BEGIN
			INSERT INTO [dbo].[t_wms_pod]
				([outbound_order_master_id]
				,[route_code]
				,[route_name]
				,[order_status]
				,[pod_date_plan]
				,[create_by]
				,[create_date])
			VALUES
				(@in_vchOutboundMasterID
				,@v_vchRouteCode
				,@v_vchRouteName
				,'PENDING'
				,@in_dtShipDateActual
				,@in_vchUserID
				,GETDATE())
		END
		
		--Unallocate Qty
		IF @v_vchPickType = 'SYSTEM'
		BEGIN
			DECLARE @v_vchUnLocationID		UNIQUEIDENTIFIER = NULL,
					@v_vchUnParentLPN		NVARCHAR(25) = NULL,
					@v_vchUnLPN				NVARCHAR(25) = NULL, 
					@v_vchUnWhItemMasterID	UNIQUEIDENTIFIER = NULL, 
					@v_vchUnLotNumber		NVARCHAR(50)= NULL,  
					@v_vchUnExpiryDate		NVARCHAR(8)= NULL, 
					@v_vchUnSerialNumber	NVARCHAR(100)= NULL, 
					@v_vchUnAttribute1		NVARCHAR(100)= NULL, 
					@v_vchUnAttribute2		NVARCHAR(100)= NULL, 
					@v_vchUnAttribute3		NVARCHAR(100)= NULL, 
					@v_vchUnAttribute4		NVARCHAR(100)= NULL, 
					@v_vchUnAttribute5		NVARCHAR(100)= NULL, 
					@v_dtUnReceiveDate		DATE= NULL, 
					@v_vchUnDefaultStatus	NVARCHAR(50)= NULL, 
					@v_fltUnallocateQty		FLOAT= NULL 

			-----------------------------------------------
			-- Un allocate data
			-----------------------------------------------
			DECLARE cursorOutboundUnAllocate CURSOR FOR
				SELECT pickDT.location_id
					,pickDT.parent_lpn
					,pickDT.lpn
					,pickDT.wh_item_master_id
					,pickDT.lot_number
					,pickDT.[expiry_date] 
					,pickDT.serial_number
					,pickDT.attribute1
					,pickDT.attribute2
					,pickDT.attribute3
					,pickDT.attribute4
					,pickDT.attribute5
					,pickDT.receive_date
					,obDT.default_item_status
					,ROUND((pickDT.quantity_plan - pickDT.quantity_pick),@Round)
				FROM t_wms_outbound_pick_master pickMS
				INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickdt.outbound_pick_master_id
				INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
				WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID		
				AND (pickDT.quantity_plan - pickDT.quantity_pick) > 0 
				AND pickDT.is_override = 'NO'
		
			OPEN cursorOutboundUnAllocate;
			FETCH NEXT FROM cursorOutboundUnAllocate INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber	
														,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_dtUnReceiveDate,@v_vchUnDefaultStatus,@v_fltUnallocateQty
			WHILE @@FETCH_STATUS = 0
				BEGIN
					-- un allocate inventory data
					EXEC [usp_inventory_un_allocate] @in_vchApplicationID	  = @in_vchApplicationID
													, @in_vchWarehouseMasterID = @in_vchWhMasterID	
													, @in_vchLocationID		  = @v_vchUnLocationID
													, @in_vchParentLPN		  = @v_vchUnParentLPN	
													, @in_vchLPN			  = @v_vchUnLPN
													, @in_vchWhItemMasterID	  = @v_vchUnWhItemMasterID
													, @in_fltQuantity		  = @v_fltUnallocateQty	
													, @in_vchSerialNumber	  = @v_vchUnSerialNumber	
													, @in_vchLotNumber		  = @v_vchUnLotNumber	
													, @in_vchExpiryDate		  = @v_vchUnExpiryDate
													, @in_vchAttribute1		  = @v_vchUnAttribute1
													, @in_vchAttribute2		  = @v_vchUnAttribute2
													, @in_vchAttribute3		  = @v_vchUnAttribute3
													, @in_vchAttribute4		  = @v_vchUnAttribute4
													, @in_vchAttribute5		  = @v_vchUnAttribute5
													, @in_dtReceiveDate		  = @v_dtUnReceiveDate
													, @in_vchDefaultItemStatus = @v_vchUnDefaultStatus
													, @in_vchUserID			  = @in_vchUserID	
													, @out_ErrorCode		  = @out_ErrorCode	OUTPUT
													, @out_ErrorMessage		  = @out_ErrorMessage OUTPUT							
					IF (@out_ErrorCode <> '0')
						BEGIN 
							GOTO WRITE_PROC; 
						END
							
					FETCH NEXT FROM cursorOutboundUnAllocate INTO @v_vchUnLocationID,@v_vchUnParentLPN,@v_vchUnLPN,@v_vchUnWhItemMasterID,@v_vchUnLotNumber,@v_vchUnExpiryDate,@v_vchUnSerialNumber	
														,@v_vchUnAttribute1,@v_vchUnAttribute2,@v_vchUnAttribute3,@v_vchUnAttribute4,@v_vchUnAttribute5,@v_dtUnReceiveDate,@v_vchUnDefaultStatus,@v_fltUnallocateQty
				END
						
			CLOSE cursorOutboundUnAllocate;
			DEALLOCATE cursorOutboundUnAllocate;
		END

		COMMIT TRANSACTION;

		--For Interface
		IF @v_vchMoveSubTranType = 'MOVE_ON_PC'
			BEGIN
				UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END

		--Update Host Shipment = PENDING
		IF (@v_vchTranType = 'BLIND_PICK' AND @v_vchSubTranType = 'CONFIRM_TO_ERP')
			BEGIN
				UPDATE t_host_wms_trans_export SET processing_status = 'PENDING' WHERE host_record_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END
		ELSE IF @v_vchTranType IN ('OO_SHIP','OO_SHIP_CONSIGNMENT','OO_PARTIAL_SHIP') AND @v_vchSubTranType IN ('CONFIRM_TO_ERP')
			BEGIN
				UPDATE t_host_wms_ship_conf_detail_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
				UPDATE t_host_wms_ship_conf_header_export SET processing_status = 'PENDING' WHERE host_shipment_id = @v_vchHostInterfaceID AND processing_status = 'OPEN'
			END
		
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
	    RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
			If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;

			IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
				BEGIN
					CLOSE OutboundPickDetail_CURSOR;
					DEALLOCATE OutboundPickDetail_CURSOR;
				END
			IF CURSOR_STATUS('global','cursorOutboundUnAllocate')>=-1
				BEGIN
					CLOSE cursorOutboundUnAllocate;
					DEALLOCATE cursorOutboundUnAllocate;
				END 
							 
			SET @v_dtProcessDateTime = GETDATE(); 
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @c_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchOrderNumber,
				@in_vchData2 = NULL,
				@in_vchData3 = NULL,
				@in_vchData4 = NULL,
				@in_vchErrorCode = @out_ErrorCode,
				@in_vchMessage = @out_ErrorMessage
	END
		   
	END TRY
	BEGIN CATCH
	
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
			BEGIN
				CLOSE OutboundPickDetail_CURSOR;
				DEALLOCATE OutboundPickDetail_CURSOR;
			END
		IF CURSOR_STATUS('global','cursorOutboundUnAllocate')>=-1
			BEGIN
				CLOSE cursorOutboundUnAllocate;
				DEALLOCATE cursorOutboundUnAllocate;
			END
								
		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END 

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOrderNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = @out_ErrorCode,
			@in_vchData4 = @out_ErrorMessage,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH   
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_ship_confirm_by_load_id]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_ship_confirm_by_load_id]  
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(25),  
	@in_vchLoadID			NVARCHAR(50),  
	@in_vchCarrierID		UNIQUEIDENTIFIER,	--Carrier ID
	@in_vchTruckType		NVARCHAR(40),		--TruckTypeCode
	@in_vchTruckNumber		NVARCHAR(50) = NULL,  
	@in_vchDriverLicense	NVARCHAR(50) = NULL,
	@in_vchContainerNo		NVARCHAR(50) = NULL, 
	@in_vchSealNumber		NVARCHAR(50) = NULL,
	@in_vchPostingDate		DATETIME = NULL,
	@in_dtShipDateActual	DATETIME = NULL, 
	@out_ErrorCode			NVARCHAR(200) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
     
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_ship_confirm_by_load_id]'
	DECLARE @v_vchBeginTrans		BIT = 0
	DECLARE @v_dtProcessDateTime	DATETIME
	DECLARE @v_vchOutboundMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchOrderNumber		NVARCHAR(50)
	DECLARE @v_vchWarehouse			NVARCHAR(25) 
	SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
 
	BEGIN TRY 
		SELECT outbound_order_master_id
			,outbound_order_number
			,order_type
			,order_status
		INTO #tAllOutboundLoad
		FROM t_wms_outbound_master
		WHERE wh_master_id = @in_vchWhMasterID
		AND load_id = @in_vchLoadID

		--Check order Type and Status can ship
		IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'CHECK_FULL_SHIP' AND is_active = 'YES') = 'YES'
			BEGIN
				IF EXISTS (SELECT outbound_order_detail_id FROM t_wms_outbound_detail 
						   WHERE  ISNULL(quantity_stage,0) < ISNULL(quantity_order,0)
						   AND outbound_order_master_id IN (SELECT outbound_order_master_id FROM #tAllOutboundLoad))
					BEGIN
						SET @out_ErrorCode = 'CANNOT_SHIP_QTYORDER_NOT_EQUAL_QTYPICK';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOrderNumber,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END

		-------------------------------------------
		--CONFIRM SHIP BY LOAD ID
		-------------------------------------------
		DECLARE Outbound_Cursor CURSOR FOR
			SELECT outbound_order_master_id
				, outbound_order_number
			FROM #tAllOutboundLoad
			WHERE order_status NOT IN ('SHIP','CLOSE')
			ORDER BY outbound_order_number
		OPEN Outbound_Cursor 
		FETCH NEXT FROM Outbound_Cursor INTO @v_vchOutboundMasterID ,@v_vchOrderNumber
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
			-----------------------------------------
			--SHIP LOAD BY ORDER
			-----------------------------------------
			EXEC usp_outbound_ship_confirm @in_vchApplicationID	 = @in_vchApplicationID
											,@in_vchWhMasterID	 = @in_vchWhMasterID
											,@in_vchDeviceID		 = @in_vchDeviceID	
											,@in_vchUserID		 = @in_vchUserID	
											,@in_vchOutboundMasterID	= @v_vchOutboundMasterID	
											,@in_vchCarrierID	 = @in_vchCarrierID	
											,@in_vchTruckType	 = @in_vchTruckType
											,@in_vchTruckNumber	 = @in_vchTruckNumber	
											,@in_vchDriverLicense = @in_vchDriverLicense
											,@in_vchContainerNo	 = @in_vchContainerNo	
											,@in_vchSealNumber	 = @in_vchSealNumber	
											,@in_vchPostingDate	 = @in_vchPostingDate
											,@in_dtShipDateActual = @in_dtShipDateActual
											,@out_ErrorCode		 = @out_ErrorCode output
											,@out_ErrorMessage	 = @out_ErrorMessage output
			IF (@out_ErrorCode <> '0')
			BEGIN 
				GOTO WRITE_PROC; 
			END

			FETCH NEXT FROM Outbound_Cursor INTO @v_vchOutboundMasterID ,@v_vchOrderNumber 
		END
		CLOSE Outbound_Cursor                  	
		DEALLOCATE Outbound_Cursor 

		 
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
		
		IF OBJECT_ID('tempdb..#tAllOutboundLoad') IS NOT NULL
			DROP TABLE #tAllOutboundLoad
	    RETURN;

		-------------------------------------------
		-- Write process log
		-------------------------------------------
		BEGIN
			WRITE_PROC:	  
				IF CURSOR_STATUS('global','Outbound_Cursor')>=-1
					BEGIN
						CLOSE Outbound_Cursor;
						DEALLOCATE Outbound_Cursor;
					END		 
				SET @v_dtProcessDateTime = GETDATE(); 
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @in_vchLoadID,
					@in_vchData2 = @v_vchOrderNumber,
					@in_vchData3 = NULL,
					@in_vchData4 = NULL,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END
		   
	END TRY
	BEGIN CATCH 
		IF CURSOR_STATUS('global','Outbound_Cursor')>=-1
			BEGIN
				CLOSE Outbound_Cursor;
				DEALLOCATE Outbound_Cursor;
			END					
		IF (ISNULL(@out_ErrorCode,'') = '' or ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = @v_vchOrderNumber,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage 

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH   
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_ship_confirm_grouping]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_ship_confirm_grouping]  
	@in_vchApplicationID	VARCHAR(40),  
	@in_vchWarehouse		NVARCHAR(25),  
	@in_vchDeviceID			NVARCHAR(50),  
	@in_vchUserID			NVARCHAR(10),  
	@in_vchGroupingNo		NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(200) output,  
	@out_ErrorMessage		NVARCHAR(500) output  
AS  
BEGIN  
	SET NOCOUNT ON;
     
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_ship_confirm_grouping]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
		@v_dtSartTranDate			DATETIME,
		@v_dtEndTranDate			DATETIME,
		 
		@v_vchApplicationName			NVARCHAR(100),
		@v_vchParentLPN					NVARCHAR(25),
		@v_vchLPN						NVARCHAR(25),  
		@v_vchLot						NVARCHAR(50),  
		@v_vchExpiryDate				NVARCHAR(8),
		@v_dtExpiryDate					DATE,
		@v_vchItem						NVARCHAR(50),  
		@v_fltQty						FLOAT,
		@v_fltQtyShip					FLOAT,
		@v_vchUOM						NVARCHAR(10),  
		@v_vchSerial					NVARCHAR(50),  
		@v_vchLineNumber				NVARCHAR(10),  
		@v_vchFromLocation				NVARCHAR(50),  
		@v_vchOutboundOrderDetailID		NVARCHAR(40), 
		@v_dtpDeliveryDate				DATETIME, 
		
		@v_vchPlant						NVARCHAR(50),
		@v_vchWarehouseMasterID			NVARCHAR(40),  
		@v_vchWarehouseItemMasterID		VARCHAR(40),  
		@v_vchLocationMasterID			NVARCHAR(40),  
		@v_vchOLocationMasterID			NVARCHAR(40),  
		@v_dtpStartTranDate				DATETIME,  
		@v_vchCarrierID					NVARCHAR(40), 
		@v_vchCustomerID				VARCHAR(40),
		@v_vchCustomerCode				NVARCHAR(40),  
		@v_vchOrderType					NVARCHAR(30),
		@v_vchOrderStatus				NVARCHAR(10),
		@v_vchStatus					VARCHAR(50),
		@v_intLocation					INT,
		@v_vchInventoryID				VARCHAR(40),
		@v_vchAttributeGroupID			VARCHAR(40),
		@v_fltStockQty					FLOAT,
		@v_vchHostInterfaceID			NVARCHAR(50),
		@v_vchOwnerID					NVARCHAR(50),
		@v_vchOwnerCode					NVARCHAR(50),
		@v_vchItemUOMID					VARCHAR(40),
		@v_vchOrderTypeForMove			NVARCHAR(50),
		@v_vchCostCenter				NVARCHAR(10),
		@v_vchBeginTrans				BIT = 0,
		@v_vchMoveBatch					NVARCHAR(50),
		@v_vchLineNo					NVARCHAR(10),
		@v_fltQuantityOrder				FLOAT,
		@v_vchTrackingNo				NVARCHAR(50),
		@v_vchSealNo					NVARCHAR(50),
		@v_vchTruckNo					NVARCHAR(50),
		@v_vchCarrierCode				NVARCHAR(50),
		@v_vchTruckType					NVARCHAR(50),
		@v_vchDriverLicense				NVARCHAR(50),

		@v_vchHUDF1						NVARCHAR(50),
		@v_vchHUDF2						NVARCHAR(50),
		@v_vchHUDF3						NVARCHAR(50),
		@v_vchHUDF4						NVARCHAR(50),
		@v_fltHUDF5						FLOAT,
		@v_fltHUDF6						FLOAT,
		@v_dtpHUDF7						DATETIME,

		@v_vchDUDF1						NVARCHAR(50),
		@v_vchDUDF2						NVARCHAR(50),
		@v_vchDUDF3						NVARCHAR(50),
		@v_vchDUDF4						NVARCHAR(50),
		@v_fltDUDF5						FLOAT,
		@v_fltDUDF6						FLOAT,
		@v_dtpDUDF7						DATETIME,

		--Mai 12/09/2013
		@v_dtShipDateActual				DATETIME,
		@v_dtDeliveryDatePlan			DATETIME,
		@v_fltDPrice					FLOAT,

		@v_vchSubTranType				NVARCHAR(50),
		@v_vchGroupMasterID				VARCHAR(40)

   
	BEGIN TRY  
    
	    SET @v_dtSartTranDate = GETDATE();

		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT

		SELECT @v_vchWarehouseMasterID = wh_master_id,@v_vchPlant = wh_group FROM t_wms_wh WHERE wh_id = @in_vchWarehouse  
		--SELECT @v_vchCarrierID = carrier_id FROM t_wms_carrier WHERE carrier_name = @in_vchCarrier  
		
		SELECT 
			@v_vchGroupMasterID = grouping_master_id
			,@v_vchOrderType = order_type
			,@v_vchOrderStatus = order_status
			,@v_vchOwnerCode = owner_code 
			,@v_vchCustomerCode = customer_code
			,@v_vchOwnerID = t_wms_owner.owner_id
			,@v_vchTrackingNo = tracking_number
			,@v_vchSealNo = seal_no
			,@v_vchTruckNo = truck_no
			,@v_vchCarrierID = carrier_id
			,@v_vchTruckType = truck_type
			,@v_vchDriverLicense = driver_license
			,@v_vchHUDF1 = user_def1
			,@v_vchHUDF2 = user_def2
			,@v_vchHUDF3 = user_def3
			,@v_vchHUDF4 = user_def4
			,@v_fltHUDF5 = user_def5
			,@v_fltHUDF6 = user_def6
			,@v_dtpHUDF7 = user_def7

			--Mai [12/09/2013] เพิ่ม ship_date_actual, delivery_date_actual
			,@v_dtShipDateActual = GETDATE()--ship_date_actual
			,@v_dtDeliveryDatePlan = delivery_date_plan
		FROM t_wms_outbound_grouping
		INNER JOIN t_wms_owner ON t_wms_outbound_grouping.owner_id = t_wms_owner.owner_id
		WHERE wh_master_id = @v_vchWarehouseMasterID 
		AND grouping_no = @in_vchGroupingNo  

		--Mai [12/09/2013] เพิ่ม ship_date_actual, delivery_date_actual DataType = DATE
		SET @v_dtShipDateActual = CONVERT(DATE,@v_dtShipDateActual);
		SET @v_dtDeliveryDatePlan = CONVERT(DATE,@v_dtDeliveryDatePlan);

		SELECT @v_vchCustomerID = customer_id FROM t_wms_customer WHERE customer_code = @v_vchCustomerCode

		SET @v_vchSubTranType = 'CONFIRM_TO_ERP';

		DECLARE cursorOutboundPickDetail SCROLL CURSOR FOR
		SELECT	lpn
				,lot_number
				,[expiry_date]
				,quantity_ship
				,serial_number
				,line_number
				,wh_item_master_id
				,item_uom_id
				,quantity_order
				--Mai [12/09/2013] :เพิ่ม Price
				,price
				,user_def1
				,user_def2
				,user_def3
				,user_def4
				,user_def5
				,user_def6
				,user_def7
		FROM t_wms_outbound_grouping_detail  
		WHERE grouping_master_id = @v_vchGroupMasterID
	    
		OPEN cursorOutboundPickDetail;  
		FETCH cursorOutboundPickDetail INTO @v_vchLPN,@v_vchLot,@v_vchExpiryDate,@v_fltQty,@v_vchSerial,@v_vchLineNumber,@v_vchWarehouseItemMasterID,@v_vchItemUOMID,@v_fltQuantityOrder,@v_fltDPrice,
		@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_fltDUDF5,@v_fltDUDF6,@v_dtpDUDF7

		SELECT @v_vchFromLocation = location FROM t_wms_location WHERE wh_master_id = @v_vchWarehouseMasterID AND location_id = @v_vchLocationMasterID
		
		SELECT @v_vchCarrierCode = carrier_code FROM t_wms_carrier WHERE carrier_id = @v_vchCarrierID

		If (@@CURSOR_ROWS > 0)
			BEGIN
				EXEC usp_get_HostInterfaceID @v_vchHostInterfaceID OUTPUT
				BEGIN TRANSACTION
					SET @v_vchBeginTrans = 1;
					-- Ship Confirm.Update Inventory data
					WHILE @@FETCH_STATUS = 0  
						BEGIN
							
							SET @v_dtExpiryDate = CONVERT(DATE,@v_vchExpiryDate);

							IF (@v_vchLocationMasterID <> @v_vchOLocationMasterID)
								SELECT @v_vchFromLocation = location FROM t_wms_location WHERE wh_master_id = @v_vchWarehouseMasterID AND location_id = @v_vchLocationMasterID
							
							SET @v_dtpStartTranDate = GETDATE();
							
							set @v_vchStatus = 'Normal'
							
							SET @v_dtEndTranDate = getdate();
							
							select top 1 @v_vchItem = item_number from t_wms_wh_item inner join t_wms_item
							on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
							where wh_item_master_id = @v_vchWarehouseItemMasterID

							select @v_vchUOM = uom_prompt from t_wms_item_uom where item_uom_id = @v_vchItemUOMID

							SET @v_vchOrderStatus = 'SHIP';

							EXEC usp_LogManager
								@in_vchApplicationID = @in_vchApplicationID,
								@in_vchAppName = @v_vchApplicationName,
								@in_vchWhID = @in_vchWarehouse,
								@in_vchToWhID = @in_vchWarehouse,
								
								@in_vchDevice = @in_vchDeviceID,
								@in_vchUserID = @in_vchUserID,
								@in_vchLogType = 'TRANSACTION',

								@in_vchTranType = 'OO_SHIP',
								@in_vchSubTranType = @v_vchSubTranType,
								@in_dtStartTranDate = @v_dtSartTranDate,
								@in_dtEndTranDate = @v_dtEndTranDate,
								@in_vchOwner = @v_vchOwnerCode,
								@in_vchToOwner = @v_vchOwnerCode,
								@in_vchLocation = @v_vchFromLocation,
								@in_vchToLocation = NULL,
								@in_vchItemNumber = @v_vchItem,
								@in_vchUOM = @v_vchUOM,
								@in_vchBaseUOM = @v_vchUOM,
								@in_fltQuantity = @v_fltQty,
								@in_vchSerialNumber = @v_vchSerial,
								@in_fltAfterQuantity = 0,
								@in_vchAfterUOM = @v_vchUOM,
								@in_vchLotNumber = @v_vchLot,
								@in_vchAfterLotNumber = NULL,
								@in_dtExpiryDate = @v_dtExpiryDate,
								@in_dtAfterExpiryDate = NULL,
								@in_vchLPN = @v_vchLPN,
								@in_vchAfterLPN = NULL,
								@in_vchStatus = @v_vchStatus,
								@in_vchAfterStatus = @v_vchStatus,
								@in_vchReasonCode = NULL,
								@in_vchReferenceNumber = NULL,
								@in_vchOrderNumber = @in_vchGroupingNo,
								@in_vchOrderStatus = @v_vchOrderStatus,
								@in_vchControlNumber = @v_vchHostInterfaceID,
								@in_vchLineNumber = @v_vchLineNumber,
								@in_vchOrderQuantity = @v_fltQuantityOrder,
								@in_vchShortQuantity = 0,

								@in_vchProcess = @c_vchObjName,
								@in_dtProcessDateTime = @v_dtProcessDateTime,
								@in_vchData1 = @v_vchOrderType,

								@in_vchTrackingNumber = @v_vchTrackingNo,
								@in_vchSealNumber = @v_vchSealNo,
								@in_vchTrailerNumber = @v_vchTruckNO,
								@in_vchCarrierCode = @v_vchCarrierCode,
								@in_vchEquipmentType = @v_vchTruckType,
								@in_vchCDLLicense = @v_vchDriverLicense,

								@in_vchHUDF1 = @v_vchHUDF1,
								@in_vchHUDF2 = @v_vchHUDF2,
								@in_vchHUDF3 = @v_vchHUDF3,
								@in_vchHUDF4 = @v_vchHUDF4,
								@in_fltHUDF5 = @v_fltHUDF5,
								@in_fltHUDF6 = @v_fltHUDF6,

								@in_vchDUDF1 = @v_vchDUDF1,
								@in_vchDUDF2 = @v_vchDUDF2,
								@in_vchDUDF3 = @v_vchDUDF3,
								@in_vchDUDF4 = @v_vchDUDF4,
								@in_fltDUDF5 = @v_fltDUDF5,
								@in_fltDUDF6 = @v_fltDUDF6,

								@in_dtUDFdatetime1 = @v_dtpHUDF7,
								@in_dtUDFdatetime2 = @v_dtpDUDF7,
								@in_dtUDFdatetime3 = @v_dtpDeliveryDate,
								@in_vchHostRecordID = @v_vchHostInterfaceID,
								@in_vchFromPlant = null,
								@in_vchToPlant = null,
								@in_dtPostingDate = null,
								@in_dtProductionDate = null,
								@in_vchCustomerCode = @v_vchCustomerCode,
								@in_vchSupplierCode = NULL,
								@in_dtShipDateActual =	@v_dtShipDateActual,
								@in_dtDeliveryDatePlan = @v_dtDeliveryDatePlan,
								@in_fltPrice = @v_fltDPrice,
								@in_vchErrorCode = @out_ErrorCode output,
								@in_vchMessage	= @out_ErrorMessage output
								IF (@out_ErrorCode <> '0' and @out_ErrorCode <> '')
									BEGIN
										IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
											ROLLBACK TRANSACTION;
										RETURN;
									END

				          
							SET @v_vchOLocationMasterID = @v_vchLocationMasterID;
							FETCH cursorOutboundPickDetail INTO @v_vchLPN,@v_vchLot,@v_vchExpiryDate,@v_fltQty,@v_vchSerial,@v_vchLineNumber,@v_vchWarehouseItemMasterID,@v_vchItemUOMID,@v_fltQuantityOrder,@v_fltDPrice,
							@v_vchDUDF1,@v_vchDUDF2,@v_vchDUDF3,@v_vchDUDF4,@v_fltDUDF5,@v_fltDUDF6,@v_dtpDUDF7
				    
						END  
				
					Close cursorOutboundPickDetail;  
					--Deallocate cursorOutboundPickDetail; 
			       
					
				DEALLOCATE cursorOutboundPickDetail;	
				COMMIT TRANSACTION
			END
		ELSE
			BEGIN
				SET @out_ErrorCode = '999';
				SET @out_ErrorMessage = 'Not found data for ship';
				GOTO WRITE_PROC;
			END
			
		SET @out_ErrorCode = '0';  
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')  
	    RETURN;
		-----------------------------------------------------------------------------------
		--							Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
				
				IF CURSOR_STATUS('global','cursorOutboundPickDetail') >= -1
					Begin
						Close cursorOutboundPickDetail;
						Deallocate cursorOutboundPickDetail;
					End
					
				IF CURSOR_STATUS('global','cursorOutboundUnAllocate') >= -1
					Begin
						Close cursorOutboundUnAllocate;
						Deallocate cursorOutboundUnAllocate;
					End
																	
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_vchProcessData2 = 'Item [' + @v_vchItem + ']';
				SET @v_dtProcessDateTime = getdate();
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchGroupingNo,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		End
		   
	End Try
	Begin Catch
	
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','cursorOutboundPickDetail') >= -1
			Begin
				Close cursorOutboundPickDetail;
				Deallocate cursorOutboundPickDetail;
			End
			
		IF CURSOR_STATUS('global','cursorOutboundUnAllocate') >= -1
			Begin
				Close cursorOutboundUnAllocate;
				Deallocate cursorOutboundUnAllocate;
			End

		IF CURSOR_STATUS('global','cursorOutboundDetail') >= -1
			Begin
				Close cursorOutboundDetail;
				Deallocate cursorOutboundDetail;
			End
								
		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End 

	End Catch   
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_suggest_truck_type]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_suggest_truck_type]
(
	@in_vchLoadNumber	NVARCHAR(50) = NULL,
	@in_vchWhMasterID	VARCHAR(40)  = NULL,
	@out_vchTruckTypeID	VARCHAR(40)  OUTPUT,
	@out_vchTruckType	NVARCHAR(50) OUTPUT
)		
AS
BEGIN
	DECLARE @v_fltVolumn		FLOAT = 0,
			@v_fltWeight		FLOAT = 0

	SET @out_vchTruckTypeID	= NULL
	SET @out_vchTruckType	= NULL

	SELECT @v_fltVolumn = SUM(loadDT.volumn)
		, @v_fltWeight = SUM(loadDT.weight)
	FROM t_wms_load_master loadMS
	LEFT JOIN t_wms_load_detail loadDT ON loadMS.load_master_id = loadDT.load_master_id
	WHERE wh_master_id = @in_vchWhMasterID
	AND load_number = @in_vchLoadNumber

	IF (@v_fltVolumn <> 0 OR @v_fltWeight <> 0)
		BEGIN
			--if ถ้ากำหนด Volume หรือ Weight หรือมีการคำนวณทั้ง 2 ค่า จะต้อง defualt truck type ก่อน Confirm ship
			--else ถ้าไม่ได้มีการคำนวณ volume, weight ไม่ต้อง default truck type ส่ง null
			SELECT TOP 1 @out_vchTruckTypeID = truck_type_id
				, @out_vchTruckType = truck_type
			FROM t_wms_truck_type WHERE volume >= @v_fltVolumn AND weight >= @v_fltWeight
			ORDER BY volume, weight
		END
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_sum_qty_by_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_sum_qty_by_item]
(
	@v_dtDeliveryDatePlan		VARCHAR(15),
	@v_dtDeliveryDatePlanTo		VARCHAR(15)
)
AS
BEGIN

	DECLARE @sqlExec NVARCHAR (MAX)
	SET @sqlExec = 'SELECT 
						  obHD.owner_id
						, own.owner_code
						, obHD.wh_master_id
						, wh.wh_id
						, obDT.wh_item_master_id
						, item.item_number
						, item.category_id
						, cate.item_category
						, item.description	AS item_description
						, SUM(ISNULL(obDT.quantity_order,0))	AS quantity_order
						, uom.uom
					FROM t_wms_outbound_master obHD
					INNER JOIN t_wms_outbound_detail obDT ON obHD.outbound_order_master_id = obDT.outbound_order_master_id
					LEFT JOIN t_wms_wh_item whItem ON whItem.wh_item_master_id = obDT.wh_item_master_id
					LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
					LEFT JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = ''YES''
					LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
					LEFT JOIN t_wms_wh wh ON obHD.wh_master_id = wh.wh_master_id
					LEFT JOIN t_wms_owner own ON obHD.owner_id = own.owner_id
					WHERE obHD.order_status = ''OPEN'''

	IF (@v_dtDeliveryDatePlan <> '' AND @v_dtDeliveryDatePlanTo <> '')
	BEGIN 
		SET @sqlExec = @sqlExec + ' AND  (CONVERT(NVARCHAR(8), obHD.delivery_date_plan, 112) >= '''+ @v_dtDeliveryDatePlan + ''' AND CONVERT(nvarchar(8), obHD.delivery_date_plan, 112) <= '''+@v_dtDeliveryDatePlanTo+''')'
	END
	ELSE IF  (@v_dtDeliveryDatePlan <> '' AND @v_dtDeliveryDatePlanTo = '')
	BEGIN 
		SET @sqlExec = @sqlExec + ' AND CONVERT(NVARCHAR(8), obHD.delivery_date_plan, 112) = '''+ @v_dtDeliveryDatePlan + ''''
	END
	ELSE IF  (@v_dtDeliveryDatePlan = '' AND @v_dtDeliveryDatePlanTo <> '')
	BEGIN 
		SET @sqlExec = @sqlExec + ' AND CONVERT(NVARCHAR(8), obHD.delivery_date_plan, 112) = '''+ @v_dtDeliveryDatePlanTo + ''''
	END
	SET @sqlExec = @sqlExec+' GROUP BY obHD.owner_id
								, own.owner_code
								, obHD.wh_master_id
								, wh.wh_id
								, obDT.wh_item_master_id
								, item.item_number
								, item.category_id  
								, cate.item_category
								, item.description
								, uom.uom'
	EXEC sp_executesql @sqlExec
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unallocate_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unallocate_order]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWhMasterID			UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER,
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
SET NOCOUNT ON;	
	DECLARE @v_vchBeginTrans		BIT = 0
	DECLARE @v_dtProcessDateTime	DATETIME = GETDATE()
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_unallocate_order]'
	DECLARE @v_vchData1				NVARCHAR(1000)
	DECLARE @v_vchData2				NVARCHAR(1000)

	DECLARE @v_vchWarehouse			NVARCHAR(50)
	DECLARE @v_vchOutboundOrderNumber NVARCHAR(50)
	DECLARE @v_vchOrderStatus		NVARCHAR(10)
	DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER
	DECLARE @v_vchParentLPN			NVARCHAR(25)
	DECLARE @v_vchLPN				NVARCHAR(25)
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER
	DECLARE @v_vchLotNumber			NVARCHAR(50)
	DECLARE @v_vchExpiryDate		NVARCHAR(50)
	DECLARE @v_vchSerialNumber		NVARCHAR(100)
	DECLARE @v_vchAttribute1		NVARCHAR(100)
	DECLARE @v_vchAttribute2		NVARCHAR(100)
	DECLARE @v_vchAttribute3		NVARCHAR(100)
	DECLARE @v_vchAttribute4		NVARCHAR(100)
	DECLARE @v_vchAttribute5		NVARCHAR(100)
	DECLARE @v_fltRemainPickQTY		FLOAT
	DECLARE @v_dtReceiveDate		DATE
	DECLARE @v_vchDefaultItemStatus	NVARCHAR(50)

	BEGIN TRY	 
		SELECT @v_vchOutboundOrderNumber = outbound_order_number
			,@v_vchOrderStatus  = order_status
			,@v_vchWarehouse = wh_id
		FROM t_wms_outbound_master 
		WHERE outbound_order_master_id = @in_vchOutboundMasterID
		
		IF @v_vchOrderStatus IN ('OPEN','RELEASE','SHIP','CLOSE')
			BEGIN
				SET @out_ErrorCode = 'INFO_OUTBOUND_ORDER_CANNOT_UNALLOCATE';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,@v_vchOrderStatus,'@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END


		SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_order_master_id = @in_vchOutboundMasterID
	
		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1; 
			-- un allocate inventory by pick detail
			DECLARE Unallocate_Order SCROLL CURSOR FOR
				SELECT pickDT.location_id
					,pickDT.parent_lpn
					,pickDT.lpn
					,pickDT.wh_item_master_id
					,pickDT.lot_number
					,pickDT.expiry_date
					,pickDT.serial_number
					,pickDT.attribute1
					,pickDT.attribute2
					,pickDT.attribute3
					,pickDT.attribute4
					,pickDT.attribute5
					,(ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)) AS quantity_remain_pick
					,pickDT.receive_date
					,obDT.default_item_status
				FROM t_wms_outbound_pick_master pickMS
				INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
				WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID 
				AND (ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)) > 0 
				AND pickDT.is_override = 'NO'
			OPEN Unallocate_Order;
			FETCH FROM Unallocate_Order INTO @v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchWhItemMasterID ,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
											,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltRemainPickQTY,@v_dtReceiveDate,@v_vchDefaultItemStatus
			WHILE @@FETCH_STATUS = 0
				BEGIN
					-- un allocate inventory data
					EXEC [usp_inventory_un_allocate] @in_vchApplicationID	  = @in_vchApplicationID
													, @in_vchWarehouseMasterID = @in_vchWhMasterID	
													, @in_vchLocationID		  = @v_vchLocationID
													, @in_vchParentLPN		  = @v_vchParentLPN	
													, @in_vchLPN			  = @v_vchLPN
													, @in_vchWhItemMasterID	  = @v_vchWhItemMasterID
													, @in_fltQuantity		  = @v_fltRemainPickQTY	
													, @in_vchSerialNumber	  = @v_vchSerialNumber	
													, @in_vchLotNumber		  = @v_vchLotNumber	
													, @in_vchExpiryDate		  = @v_vchExpiryDate
													, @in_vchAttribute1		  = @v_vchAttribute1
													, @in_vchAttribute2		  = @v_vchAttribute2
													, @in_vchAttribute3		  = @v_vchAttribute3
													, @in_vchAttribute4		  = @v_vchAttribute4
													, @in_vchAttribute5		  = @v_vchAttribute5
													, @in_dtReceiveDate		  = @v_dtReceiveDate
													, @in_vchDefaultItemStatus = @v_vchDefaultItemStatus
													, @in_vchUserID			  = @in_vchUserID	
													, @out_ErrorCode		  = @out_ErrorCode OUTPUT
													, @out_ErrorMessage		  = @out_ErrorMessage OUTPUT

					IF (@out_ErrorCode <> '0')
						BEGIN 
							GOTO WRITE_PROCESSLOG; 
						END
							
					FETCH FROM Unallocate_Order INTO @v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchWhItemMasterID ,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
													,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltRemainPickQTY,@v_dtReceiveDate,@v_vchDefaultItemStatus
				END
			CLOSE Unallocate_Order;
			DEALLOCATE Unallocate_Order;
					
			-- delete row not pick
			DELETE FROM t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) = 0
			-- update row pick.set quantity plan = quantity pick
			UPDATE t_wms_outbound_pick_detail SET quantity_plan = quantity_pick WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) > 0	
		 
		SET @out_ErrorCode = 0;
		SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		COMMIT TRANSACTION;	
		RETURN;	
-------------------------------------------------------------------------------------------------
--Write Log
	WRITE_PROCESSLOG:
-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','Unallocate_Order') >= -1
			BEGIN
				Close Unallocate_Order;
				Deallocate Unallocate_Order;
			END
			
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchData1 = @out_ErrorMessage;
		SET @v_vchData2 = 'Outbound order [' + @v_vchOutboundOrderNumber + ']';

		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
	END TRY
	BEGIN CATCH					
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','Unallocate_Order') >= -1
			BEGIN
				Close Unallocate_Order;
				Deallocate Unallocate_Order;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END
			
		SET @v_vchData1 = ERROR_PROCEDURE() + ': ' + @out_ErrorMessage 
					+ '. SQL Error ['+ str(ERROR_NUMBER()) + '], '
					+ '. Severity ['+ str(ERROR_SEVERITY()) + '],'
					+ '. State ['+ str(ERROR_STATE()) + '],'
					+ '. Line ['+ str(ERROR_LINE()) + '].'
							
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchData2 = 'Outbound order [' + @v_vchOutboundOrderNumber + ']';
		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchData1,
			@in_vchData2 = @v_vchData2,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
			
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unload]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2013-02-05
-- Description:	Unload lpn from dock door
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_unload]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(10),
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchLocation				NVARCHAR(50),
	@in_vchDockDoor				NVARCHAR(50),
	@in_vchParentLPN			NVARCHAR(25) = null,
	@in_vchLPN					NVARCHAR(25) = null,
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_unload]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
		
		@v_vchOutboundMasterID		VARCHAR(40),
		@v_vchOutboundDetailID		VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	VARCHAR(40),
		@v_vchOrderStatus			NVARCHAR(10),
		@v_fltQtyLoad				FLOAT,
		@v_vchLineNumber			NVARCHAR(5),
		@v_vchItemNumber			NVARCHAR(50),
		@v_vchUomPrompt				NVARCHAR(25),
		
		@v_vchLOTNumber				NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(50),
		@v_vchSerialNumber			NVARCHAR(50),
		
		@v_vchWarehouseMasterID		VARCHAR(40),
		@v_vchDockDoorID			VARCHAR(40),
		@v_vchLoadStatus			NVARCHAR(10),
		--@v_vchDockDoor				NVARCHAR(25),
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchInventoryID			VARCHAR(40),
		@v_vchAttributeGroupID		VARCHAR(40),
		@v_vchUNLoadToLocationID	VARCHAR(40),
		-- add new 2014-01-13
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchOutboundPackDetailID	VARCHAR(40),
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchPickPack				NVARCHAR(3),
		@cursorOutboundPickDetail	CURSOR,
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(max) = '',
		@Round						INT
		
		select @Round = value from t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
	
	select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
	
	BEGIN TRY
	
		If(Isnull(@in_vchLocation,'') = '')
			Begin 
				SET @out_ErrorCode = '905';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLocation,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC
			End
		-- GET dock door location id
		select @v_vchDockDoorID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchDockDoor

		select @v_vchPickPack = value from t_wms_rule where rule_code = 'RULE_PICK_PACK'
		If ((@v_vchPickPack) = 'YES')
			Begin
				set @v_vchDynamicSQL =
						'
						select	order_status,quantity_load,line_number,outbound_order_master_id,outbound_pick_master_id,
								outbound_order_detail_id,outbound_pick_detail_id,item_number,lot_number,expiry_date,uom_prompt,
								load_status,dock_door_id,outbound_pack_detail_id,owner_id
						from	v_wms_outbound_pack_detail
						where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber
								and dock_door_lpn = @in_vchLPN and dock_door_id = @v_vchDockDoorID 
						';
			End
		Else
			Begin
				set @v_vchDynamicSQL =
						'
						select	order_status,quantity_load,line_number,outbound_order_master_id,outbound_pick_master_id,
								outbound_order_detail_id,outbound_pick_detail_id,item_number,lot_number,expiry_date,uom_prompt,
								load_status,dock_door_id,'' as outbound_pack_detail_id,owner_id
						from	v_wms_outbound_pick_detail
						where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber
								and dock_door_lpn = @in_vchLPN and dock_door_id = @v_vchDockDoorID 
						';
			End

		--select	@v_vchOrderStatus = order_status,@v_fltQtyLoad = quantity_load,@v_vchLineNumber = line_number,
		--		@v_vchOutboundMasterID = outbound_order_master_id,@v_vchOutboundPickMasterID = outbound_pick_master_id,
		--		@v_vchOutboundDetailID = outbound_order_detail_id,@v_vchOutboundPickDetailID = outbound_pick_detail_id,
		--		@v_vchItemNumber = item_number,@v_vchUomPrompt = uom_prompt,@v_vchLoadStatus = load_status,@v_vchDockDoorID = dock_door_id
		--from	v_wms_outbound_pick_detail
		--where	wh_id = @in_vchWarehouse and outbound_order_number = @in_vchOutboundOrderNumber --and staging_location = @in_vchLocation
		--		and dock_door_lpn = @in_vchLPN and dock_door_id = @v_vchDockDoorID 
		
		set @v_vchDynamicSQL = ' set @cursorOutboundPickDetail = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @cursorOutboundPickDetail'								
		set @v_vchParameterDefinition = '@in_vchWarehouse nvarchar(25),@in_vchOutboundOrderNumber nvarchar(50),@in_vchLPN nvarchar(50),@v_vchDockDoorID varchar(40),@cursorOutboundPickDetail CURSOR OUTPUT';
		Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@in_vchWarehouse,@in_vchOutboundOrderNumber,@in_vchLPN,@v_vchDockDoorID,@cursorOutboundPickDetail OUTPUT

		fetch @cursorOutboundPickDetail into @v_vchOrderStatus,@v_fltQtyLoad,@v_vchLineNumber,@v_vchOutboundMasterID,
						@v_vchOutboundPickMasterID,@v_vchOutboundDetailID,@v_vchOutboundPickDetailID,
						@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_vchUomPrompt,@v_vchLoadStatus,@v_vchDockDoorID,@v_vchOutboundPackDetailID,@v_vchOwnerID

		If (@v_vchOrderStatus is null)
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,@in_vchDockDoor,@in_vchParentLPN,@in_vchLPN,'@param5')
				Goto WRITE_PROC;
			End
		Else If(@v_vchOrderStatus = 'SHIP')
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		Else If (@v_vchLoadStatus = 'NO')
			Begin
				set @out_ErrorCode = '999';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'LPN_IS_NOT_LOADED',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		Else
			Begin
				
				BEGIN TRANSACTION
				While @@FETCH_STATUS = 0
					Begin
					SET @v_vchBeginTrans = 1;
					
					select @v_vchInventoryID = inventory_id,@v_vchAttributeGroupID = attribute_group_id,@v_vchItemNumber = item_number,@v_vchLOTNumber = lot_number,@v_vchExpiryDate = [expiry_date],@v_vchSerialNumber = serial_number 
					from v_wms_inventory_data 
					where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchDockDoor and isnull(lpn,'') = isnull(@in_vchLPN,'')
					
					select @v_vchUNLoadToLocationID = location_id from t_wms_location where location = @in_vchLocation
					update t_wms_inventory set location_id = @v_vchUNLoadToLocationID
					where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
						
					update t_wms_outbound_pick_detail set quantity_load = round(round(quantity_load,@Round) - round(@v_fltQtyLoad,@Round),@Round),dock_door_id = null
					,dock_door_lpn = null,load_status = 'NO'
					where outbound_pick_master_id = @v_vchOutboundPickMasterID and outbound_pick_detail_id = @v_vchOutboundPickDetailID

					update t_wms_outbound_detail set quantity_load = round(round(quantity_load,@Round) - round(@v_fltQtyLoad,@Round),@Round),item_status = 'PICK'
					where outbound_order_master_id = @v_vchOutboundMasterID and outbound_order_detail_id = @v_vchOutboundDetailID
					
					select @v_vchItemMasterID = item_master_id,@v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,
					@v_vchSerialControl = sn_control from t_wms_item where item_number = @v_vchItemNumber and owner_id = @v_vchOwnerID

					If ((@v_vchPickPack) = 'YES')
						Begin
							update t_wms_outbound_pack_detail
							set dock_door_id = null,dock_door_parent_lpn = null,dock_door_lpn = null,load_status = 'NO'
							where outbound_pack_detail_id = @v_vchOutboundPackDetailID
						End
					If (@v_vchSerialControl = 'FULL')
						Begin
							update t_wms_outbound_pick_serial_detail set quantity_load = 0,dock_door_id = NULL,
							dock_door_parent_lpn = null,dock_door_lpn = NULL,load_status = 'NO'
							where outbound_pick_detail_id = @v_vchOutboundPickDetailID and isnull(dock_door_parent_lpn,'') = isnull(@in_vchParentLPN,'') and isnull(dock_door_lpn,'') = isnull(@in_vchLPN,'')
						End

					If ((select SUM(quantity_load) from t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID) <=0 )
						Begin
							update t_wms_outbound_master
							set order_status = 'PICK'
							where wh_master_id = @v_vchWarehouseMasterID and outbound_order_number = @in_vchOutboundOrderNumber
						End
					
					fetch @cursorOutboundPickDetail into @v_vchOrderStatus,@v_fltQtyLoad,@v_vchLineNumber,@v_vchOutboundMasterID,
						@v_vchOutboundPickMasterID,@v_vchOutboundDetailID,@v_vchOutboundPickDetailID,
						@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@v_vchUomPrompt,@v_vchLoadStatus,@v_vchDockDoorID,@v_vchOutboundPackDetailID,@v_vchOwnerID

					End	
				COMMIT TRANSACTION

				set @out_ErrorCode = '0';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

				RETURN;
			End
	
		-----------------------------------------------------------------------------------
		--							Write process log
		Begin
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = getdate();
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchOutboundOrderNumber,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		End
	
	END TRY
	BEGIN CATCH
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;
		
		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unpack]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unpack]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchPackNumber			NVARCHAR(25),
	@in_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchSerialNumber			NVARCHAR(50) = NULL,		
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL,
	@in_fltQuantity				FLOAT,
	@in_vchUOMPrompt			NVARCHAR(40),
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_unpack]', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(50) = NULL, 
			@v_dtProcessDateTime		DATETIME,
			@v_vchStartTrans			DATETIME = GETDATE(),
			@v_vchBeginTrans			BIT = 0,
			@Round						INT = 0,
			@v_nCount					INT = 0,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(40) = NULL, 

			@v_vchOutboundOrderNumber	NVARCHAR(50) = NULL,
			@v_vchOrderStatus			NVARCHAR(10) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_fltQtyConversion			FLOAT,	--คือจำนวนที่รับเข้ามาแล้วมาคำนวณให้เป็นหน่วยที่เล็กที่สุด
			@v_fltSummaryQtyPack		FLOAT = 0,
			@v_fltSummaryQtyShip		FLOAT = 0,
			@v_fltQuantityUnpack		FLOAT = 0,
						 
			--Item Master
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchLotControl			VARCHAR(5)= NULL,
			@v_vchSNControl				VARCHAR(5)= NULL, 
			@v_vchExpiryDateControl		VARCHAR(5)= NULL,
			@v_vchAttribute1Control		VARCHAR(5)= NULL,
			@v_vchAttribute2Control		VARCHAR(5)= NULL,
			@v_vchAttribute3Control		VARCHAR(5)= NULL,
			@v_vchAttribute4Control		VARCHAR(5)= NULL,
			@v_vchAttribute5Control		VARCHAR(5)= NULL,

			-- Item UOM
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
			@v_vchBaseUomPrompt			NVARCHAR(25),
			@v_vchBaseUOM				VARCHAR(20),
			@v_vchIsPrimaryUOM			VARCHAR(5),
			@v_fltConversionFactor		FLOAT = 0,

			--Loop
			@v_vchOutboundPackDetailID  UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID  UNIQUEIDENTIFIER = NULL, 
			@v_fltQtyPack				FLOAT = NULL,
			@v_vchPackLocation			NVARCHAR(50) = NULL,
			@v_dtReceiveDate			DATE = NULL,
			@v_dtMfgDate				DATE = NULL,
			@v_vchDefaultItemStatus		NVARCHAR(50) = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL
	
BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

		SELECT @v_vchOutboundOrderNumber = obMS.outbound_order_number
			,@v_vchOwnerID = obMS.owner_id
			,@v_vchOwnerCode = obMS.owner_code
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
		WHERE obMS.wh_master_id = @in_vchWhMasterID 
		AND obMS.outbound_order_master_id = @in_vchOutboundMasterID

		IF(@v_vchOutboundOrderNumber IS NULL)
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		IF(@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_IS_SHIP';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--------------------------------------------------
		-- Check wh_item_master_id
		--------------------------------------------------
		SELECT TOP 1 @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC;
			END

		--------------------------------------------------
		-- Check item_master_id
		--------------------------------------------------
		SET @v_vchItemNumber = NULL
		SELECT @v_vchItemNumber = item.item_number
		FROM t_wms_item item
		WHERE item.owner_id = @v_vchOwnerID
		AND item.item_master_id = @v_vchItemMasterID
		IF (@v_vchItemNumber IS NULL)
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC;
			END

		--------------------------------------------------
		--Get & Check Item UOM
		--------------------------------------------------
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_fltConversionFactor = conversion_factor
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchBaseUOM = uom
			,@v_vchIsPrimaryUOM = primary_uom 
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND uom_prompt = @in_vchUOMPrompt		
		AND is_active = 'YES'	
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = '107';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		--------------------------------------------------
		--Get Primary Uom
		--------------------------------------------------
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt
					,@v_vchBaseUOM = uom 
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END
	
		--------------------------------------------------
		--Set Input Base Qty 
		--------------------------------------------------
		SET @v_fltQtyConversion = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);

		-------------------------------------------------------------
		-- Get Qty_Pack
		-------------------------------------------------------------
		SET @v_fltSummaryQtyPack = 0
		SET @v_nCount = 0
		SELECT @v_fltSummaryQtyPack = SUM(quantity_pack)
			,@v_fltSummaryQtyShip = SUM(quantity_ship)
		FROM (SELECT packDT.outbound_pick_detail_id
					,SUM(packDT.quantity_pack) quantity_pack
				FROM t_wms_outbound_pack_detail packDT
				WHERE packDT.outbound_order_master_id = @in_vchOutboundMasterID
				AND packDT.lpn_pack = @in_vchPackNumber
				AND packDT.wh_item_master_id = @in_vchWhItemMasterID
				AND ISNULL(packDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(packDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(packDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(packDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(packDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(packDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(packDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND ISNULL(packDT.serial_number,'') = ISNULL(@in_vchSerialNumber,'')
				GROUP BY packDT.outbound_pick_detail_id
				) packDT
		LEFT JOIN (SELECT outbound_pick_detail_id
				  		,SUM(quantity_ship) AS quantity_ship
				   FROM t_wms_outbound_pick_detail
				   GROUP BY outbound_pick_detail_id
				   ) pickDT on packDT.outbound_pick_detail_id = pickDT.outbound_pick_detail_id

		IF (ROUND(ISNULL(@v_fltSummaryQtyPack,0) - ISNULL(@v_fltSummaryQtyShip,0),@Round) = 0)
			BEGIN
				SET @out_ErrorCode = 'NOT_FOUND_DATA_FOR_UNPACK'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,@in_vchPackNumber,@v_vchItemNumber,'@param4','@param5')
				GOTO WRITE_PROC;
			END

		--------------------------------------------------------------------------
		-- ถ้า (จำนวนที่สแกน) มากกว่า (จำนวนที่ Pack ไปแล้ว - Qty Ship)
		--------------------------------------------------------------------------
		IF (ROUND(@v_fltQtyConversion,@Round) > ROUND(ISNULL(@v_fltSummaryQtyPack,0) - ISNULL(@v_fltSummaryQtyShip,0),@Round))
			BEGIN
				SET @out_ErrorCode = 'INFO_QTY_MORE_THAN_QTY_PACK'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END 

	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;
	
	-------------------------------------------------
	-- Update Qty Unpack pick detail, pack detail
	-------------------------------------------------
	BEGIN
		DECLARE UnpackCursor CURSOR FOR
			SELECT packDT.outbound_pack_detail_id
				,packDT.outbound_pick_detail_id
				,packDT.quantity_pack
				,loc.location
				,packDT.receive_date
				,packDT.mfg_date
				,tPickDT.default_item_status
				,tPickDT.line_number
			FROM t_wms_outbound_pack_detail packDT
			LEFT JOIN (SELECT pickDT.outbound_pick_detail_id
						,pickDT.outbound_order_detail_id
						,obDT.default_item_status
						,obDT.line_number
						,pickDT.quantity_pack
				  		,pickDT.quantity_ship
				   FROM t_wms_outbound_pick_detail pickDT
				   INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id 
 				   ) tPickDT on packDT.outbound_pick_detail_id = tPickDT.outbound_pick_detail_id
			INNER JOIN t_wms_location loc ON packDT.pack_location_id = loc.location_id
			WHERE packDT.outbound_order_master_id = @in_vchOutboundMasterID
			AND packDT.lpn_pack = @in_vchPackNumber
			AND packDT.wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(packDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(packDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(packDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(packDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(packDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(packDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(packDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(packDT.serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			AND (ROUND(ISNULL(tPickDT.quantity_pack,0) - ISNULL(tPickDT.quantity_ship,0),@Round) > 0)
			ORDER BY packDT.create_date DESC
		OPEN UnpackCursor
		FETCH NEXT FROM UnpackCursor INTO @v_vchOutboundPackDetailID,@v_vchOutboundPickDetailID,@v_fltQtyPack,@v_vchPackLocation,@v_dtReceiveDate,@v_dtMfgDate,@v_vchDefaultItemStatus,@v_vchLineNumber
		WHILE @@FETCH_STATUS = 0
			BEGIN
				-------------------------------------------------
				-- Check Qty can unpack
				-------------------------------------------------
				IF (ROUND(@v_fltQtyConversion,@Round) > ROUND(@v_fltQtyPack,@Round))
					BEGIN
						SET @v_fltQuantityUnpack = ROUND(@v_fltQtyPack,@Round)
					END
				ELSE
					BEGIN
						SET @v_fltQuantityUnpack = ROUND(@v_fltQtyConversion,@Round)
					END

				------------------------------------------------
				-- Update ข้อมูล Unpack
				------------------------------------------------
				UPDATE t_wms_outbound_pack_detail SET 
					 quantity_pack = ROUND((quantity_pack - @v_fltQuantityUnpack),@Round) 
				WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID
				
				UPDATE t_wms_outbound_pick_detail SET  
					quantity_pack = ROUND((quantity_pack - @v_fltQuantityUnpack),@Round)
				WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

				--หากจำนวนเป็น 0 ให้ Delete Row ทิ้ง
				DELETE t_wms_outbound_pack_detail WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID AND ISNULL(quantity_pack,0) = 0
				
				--------------------------------------------
				--tran type		>> OO_PACK
				--sub tran type >> UNPACK
				--------------------------------------------
				INSERT INTO [dbo].[t_com_tran_log]
					   ([app_id]				
					   ,[tran_type]				
					   ,[sub_tran_type]			
					   ,[app_name]				
					   ,[description]			
					   ,[start_tran_datetime]	
					   ,[end_tran_datetime]		
					   ,[warehouse]				
					   ,[to_warehouse]			
					   ,[location]				
					   ,[to_location]			
					   ,[owner]					
					   ,[to_owner]				
					   ,[item_number]			
					   ,[quantity]				
					   ,[quantity_uom]			
					   ,[after_quantity]		
					   ,[after_quantity_uom]	
					   ,[lot_number]			
					   ,[after_lot_number]		
					   ,[expiry_date]			
					   ,[after_expiry_date]		
					   ,[serial_number]			
					   ,[attribute1]			
					   ,[after_attribute1]		
					   ,[attribute2]			
					   ,[after_attribute2]		
					   ,[attribute3]			
					   ,[after_attribute3]		
					   ,[attribute4]			
					   ,[after_attribute4]		
					   ,[attribute5]			
					   ,[after_attribute5]		
					   ,[user_id]	
					   ,[lpn]					
					   ,[after_lpn] 	
					   ,[status]				
					   ,[after_status]		
					   ,[order_number]
					   ,[line_number]
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom]
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 VALUES
					   (@in_vchApplicationID					
					   ,'OO_PACK'		
					   ,'UNPACK'	
					   ,@v_vchApplicationName				
					   ,'Outbound unpack'				
					   ,@v_vchStartTrans				
					   ,GETDATE()						
					   ,@in_vchWarehouse				
					   ,@in_vchWarehouse				
					   ,@v_vchPackLocation				
					   ,@v_vchPackLocation				
					   ,@v_vchOwnerCode				
					   ,@v_vchOwnerCode					
					   ,@v_vchItemNumber			
					   ,@v_fltQuantityUnpack							
					   ,@v_vchBaseUOM				
					   ,(@v_fltQtyPack - @v_fltQuantityUnpack)				
					   ,@v_vchBaseUOM					
					   ,@in_vchLotNumber				
					   ,@in_vchLotNumber				
					   ,@in_vchExpiryDate			
					   ,@in_vchExpiryDate			
					   ,@in_vchSerialNumber				
					   ,@in_vchAttribute1			
					   ,@in_vchAttribute1			
					   ,@in_vchAttribute2			
					   ,@in_vchAttribute2			
					   ,@in_vchAttribute3			
					   ,@in_vchAttribute3			
					   ,@in_vchAttribute4			
					   ,@in_vchAttribute4			
					   ,@in_vchAttribute5			
					   ,@in_vchAttribute5			
					   ,@in_vchUserID						
					   ,@in_vchPackNumber					
					   ,@in_vchPackNumber			
					   ,@v_vchDefaultItemStatus		
					   ,@v_vchDefaultItemStatus	 
					   ,@v_vchOutboundOrderNumber
					   ,@v_vchLineNumber
					   ,@v_dtReceiveDate
					   ,@v_dtMFGDate
					   ,@in_fltQuantity	
					   ,@in_vchUOMPrompt	
					   ,@in_vchDeviceID
					   ,GETDATE()	
					   ,@in_vchUserID) 
				
				------------------------------------------------
				--จำนวน Unpack คงเหลือ
				------------------------------------------------
				SET @v_fltQtyConversion = ROUND((@v_fltQtyConversion - @v_fltQuantityUnpack),@Round)
				IF @v_fltQtyConversion = 0
					BREAK;

			FETCH NEXT FROM UnpackCursor INTO @v_vchOutboundPackDetailID,@v_vchOutboundPickDetailID,@v_fltQtyPack,@v_vchPackLocation,@v_dtReceiveDate,@v_dtMfgDate,@v_vchDefaultItemStatus,@v_vchLineNumber
			END
		CLOSE UnpackCursor
		DEALLOCATE UnpackCursor
	END
	
	IF NOT EXISTS (SELECT outbound_pack_detail_id FROM t_wms_outbound_pack_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID)
		BEGIN
			IF EXISTS(SELECT outbound_order_detail_id FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID AND ISNULL(quantity_order,0) - ISNULL(quantity_pick,0) <> 0) 
				BEGIN
					UPDATE t_wms_outbound_master set order_status = 'PICK' WHERE outbound_order_master_id = @in_vchOutboundMasterID
				END
			ELSE
				BEGIN
					UPDATE t_wms_outbound_master set order_status = 'PICKED' WHERE outbound_order_master_id = @in_vchOutboundMasterID
				END
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master set order_status = 'PACK' WHERE outbound_order_master_id = @in_vchOutboundMasterID
		END

	COMMIT TRANSACTION;
	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;

	------------------------------------------
	--Write process log
	------------------------------------------
	BEGIN
	WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','UnpackCursor')>=-1
			BEGIN
				CLOSE UnpackCursor;
				DEALLOCATE UnpackCursor;
			END

		SET @v_dtProcessDateTime = GETDATE();		
		EXEC usp_LogManager
		   @in_vchApplicationID = @in_vchApplicationID,
		   @in_vchWhID = @in_vchWarehouse,
		   @in_vchDevice = @in_vchDeviceID,
		   @in_vchUserID = @in_vchUserID,
		   @in_vchLogType = 'PROCESS',
		   @in_vchProcess = @c_vchObjName,
		   @in_dtProcessDateTime = @v_dtProcessDateTime,
		   @in_vchData1 = @v_vchOutboundOrderNumber,
		   @in_vchData2 = @in_vchPackNumber,
		   @in_vchData3 = @v_vchItemNumber,
		   @in_vchData4 = @in_fltQuantity,
		   @in_vchErrorCode = @out_ErrorCode,
		   @in_vchMessage = @out_ErrorMessage
	END
END TRY

BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
		 
	IF CURSOR_STATUS('global','UnpackCursor')>=-1
		BEGIN
			CLOSE UnpackCursor;
			DEALLOCATE UnpackCursor;
		END

	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE();	
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @in_vchPackNumber,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @in_fltQuantity,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
		 
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unpick]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unpick]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWarehouse			NVARCHAR(25),
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchOutboundOrderNumber	NVARCHAR(50),
	@in_vchOwner				NVARCHAR(50),
	@in_vchStgLocation			NVARCHAR(50),			
	@in_vchStgParentLPN			NVARCHAR(25) = NULL,	
	@in_vchStgLPN				NVARCHAR(25) = NULL,	
	@in_vchItemNumber			NVARCHAR(50),
	@in_vchLotNumber			NVARCHAR(50) = NULL,
	@in_vchExpiryDate			NVARCHAR(50) = NULL,
	@in_vchSerialNumber			NVARCHAR(50) = NULL,		
	@in_vchAttribute1			NVARCHAR(100)= NULL,
	@in_vchAttribute2			NVARCHAR(100)= NULL,
	@in_vchAttribute3			NVARCHAR(100)= NULL,
	@in_vchAttribute4			NVARCHAR(100)= NULL,
	@in_vchAttribute5			NVARCHAR(100)= NULL,
	@in_fltQuantity				FLOAT,
	@in_vchUOM					NVARCHAR(25),
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(30) = '[usp_outbound_unpick]', -- The name that uniquely tags this object.
			@v_vchApplicationName		NVARCHAR(50) = NULL,
			@v_vchLocalID				VARCHAR(40) = NULL, 
			@v_dtProcessDateTime		DATETIME,
			@v_vchStartTrans			DATETIME = GETDATE(),
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,
			@v_vchRulePickPack			VARCHAR(3),
			@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchStgLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundOrderMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundOrderDetailID	UNIQUEIDENTIFIER = NULL, 
			@v_vchOutboundPickDetailID  UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPackDetailID  UNIQUEIDENTIFIER = NULL,
			@v_vchDefaultStatusID		UNIQUEIDENTIFIER = NULL,
			@v_vchDefaultStatus			NVARCHAR(50),
			@v_vchLineNumber			NVARCHAR(10),	

			--Unpick
			@v_vchUnpickLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchUnpickLocation		NVARCHAR(50),
			@v_vchLPNControlUnPick		NVARCHAR(3),
			@v_fltCheckQtyUnpick		FLOAT,
			@v_vchAfterLPN				NVARCHAR(25),
			@v_vchSerialNumber			NVARCHAR(50),
			@v_fltQuantityPick			FLOAT,
			@v_fltQuantityRemain		FLOAT,
			@v_fltQuantityLoad			FLOAT,
			@v_fltQuantityUnPick		FLOAT,
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
			@v_fltInvQuantity			FLOAT,
			@v_dtReceiveDate			DATE,
			@v_dtMfgDate				DATE,

			--Item Master
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchLotControl			VARCHAR(5)= NULL,
			@v_vchSNControl				VARCHAR(5)= NULL, 
			@v_vchExpiryDateControl		VARCHAR(5)= NULL,
			@v_vchAttribute1Control		VARCHAR(5)= NULL,
			@v_vchAttribute2Control		VARCHAR(5)= NULL,
			@v_vchAttribute3Control		VARCHAR(5)= NULL,
			@v_vchAttribute4Control		VARCHAR(5)= NULL,
			@v_vchAttribute5Control		VARCHAR(5)= NULL,

			-- Item UOM
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER = NULL,
			@v_vchBaseUomPrompt			NVARCHAR(25),
			@v_vchBaseUOM				VARCHAR(20),
			@v_vchIsPrimaryUOM			VARCHAR(5),
			@v_fltConversionFactor		FLOAT = 0,
			@v_fltWidth					FLOAT = 0,  --item Uom
			@v_fltLength				FLOAT = 0,  --item Uom
			@v_fltHeight				FLOAT = 0,  --item Uom
			@v_fltGrossWeight			FLOAT = 0,  --item Uom
			@v_intPercentTolerance		FLOAT = 0,  --item Uom
			@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
			@v_fltVolumn				FLOAT = 0,	--item Uom
			@v_fltTotalWeight			FLOAT = 0,	--item Uom

			@v_fltRemainUnpick			FLOAT,
			@v_fltQtyConversion			FLOAT,	--คือจำนวนที่รับเข้ามาแล้วมาคำนวณให้เป็นหน่วยที่เล็กที่สุด
			@v_vchPickType				NVARCHAR(25) --กรณีที่เป็น User ไม่ต้อง Release แบบจองของ
		
BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
		SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchRulePickPack = value from t_wms_rule where rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT TOP 1 @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
		SELECT TOP 1 @v_vchStgLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchStgLocation AND is_active = 'YES'
		SET @in_fltQuantity = ROUND(@in_fltQuantity,@Round)

		SELECT @v_vchOutboundOrderMasterID = outbound_order_master_id
			,@v_vchPickType = pick_type
		FROM t_wms_outbound_master 
		WHERE wh_master_id = @v_vchWhMasterID 
		AND outbound_order_number = @in_vchOutboundOrderNumber
		IF(@v_vchOutboundOrderMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END

		--------------------------------------------------
		--Get Location for Unpick
		--------------------------------------------------
		SELECT TOP 1 @v_vchUnpickLocationID = location_id
			,@v_vchUnpickLocation = location
			,@v_vchLPNControlUnPick = lpn_controlled
		FROM t_wms_location 
		WHERE wh_master_id = @v_vchWhMasterID 
		AND loc_type = 'UNPICK' 
		AND is_active = 'YES' 
		IF (@v_vchUnpickLocationID IS NULL)
			BEGIN
				SET @v_vchLPNControlUnPick = 'YES'
				SET @v_vchUnpickLocationID = NEWID()
				SET @v_vchUnpickLocation = 'UNPICK_'+ ISNULL(@in_vchWarehouse,'')
				INSERT INTO [dbo].[t_wms_location]
						([location_id]					
						,[wh_master_id]
						,[location]
						,[loc_type]
						,[lpn_controlled]
						,[mix_owners]
						,[mix_status]
						,[mix_items]
						,[mix_lot]
						,[mix_expiry_dates]
						,[override_receive_date] 
						,[mix_attribute1]
						,[mix_attribute2]
						,[mix_attribute3]
						,[mix_attribute4]
						,[mix_attribute5]
						,[is_active]
						,[create_by]
						,[create_date])
					VALUES
						(@v_vchUnpickLocationID
						,@v_vchWhMasterID
						,@v_vchUnpickLocation
						,'UNPICK'		--[loc_type]	
						,@v_vchLPNControlUnPick	--[lpn_controlled]	
						,'YES'			--[mix_owners]
						,'YES'			--[mix_status]
						,'YES'			--[mix_items]
						,'YES'			--[mix_lot]
						,'YES'			--[mix_expiry_dates]
						,'NO'			--[override_receive_date] 
						,'YES'			--[mix_attribute1]
						,'NO'			--[mix_attribute2]
						,'NO'			--[mix_attribute3]
						,'NO'			--[mix_attribute4]
						,'NO'			--[mix_attribute5]
						,'YES'			--[is_active]
						,@in_vchUserID	--[create_by]
						,GETDATE())		--[create_date]
				--SET @out_ErrorCode = 'INFO-LOCATION-UNPICK-NOT-FOUND';
				--SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				--GOTO WRITE_PROCESSLOG;
			END

		--สำหรับกรณีที่อาจจะ Scan Item จาก Item Cross Ref ต้อง check ก่อนว่า Item นั้นมีอยู่ในระบบจริงหรือไม่
		SELECT @v_vchItemMasterID = item.item_master_id
			,@in_vchItemNumber = item.item_number
			,@v_vchLotControl = item.lot_control
			,@v_vchSNControl = item.sn_control
			,@v_vchExpiryDateControl = item.expiry_date_control
			,@v_vchAttribute1Control = item.attribute1_control
			,@v_vchAttribute2Control = item.attribute2_control
			,@v_vchAttribute3Control = item.attribute3_control
			,@v_vchAttribute4Control = item.attribute4_control
			,@v_vchAttribute5Control = item.attribute5_control
		FROM t_wms_item item
		LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
		WHERE (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
		AND owner_id = @v_vchOwnerID		
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'INFO-ITEM-NOT-FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END

		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @v_vchWhMasterID AND item_master_id = @v_vchItemMasterID AND is_active = 'YES'
		IF (@v_vchWhItemMasterID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchOutboundOrderNumber,@in_vchItemNumber,'@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END

		--------------------------------------------------
		--Get & Check Item UOM
		--------------------------------------------------
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_fltConversionFactor = conversion_factor
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchBaseUOM = uom
			,@v_vchIsPrimaryUOM = primary_uom
			,@v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND uom = @in_vchUOM		
		AND is_active = 'YES'	
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = '107';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UOM_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOM,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG
			End

		--------------------------------------------------
		--Get Primary Uom
		--------------------------------------------------
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchBaseItemUomID = item_uom_id
					,@v_vchBaseUomPrompt = uom_prompt
					,@v_vchBaseUOM = uom
					,@v_fltWidth = ISNULL(width,0)
					,@v_fltLength = ISNULL(length,0)
					,@v_fltHeight = ISNULL(height,0)
					,@v_fltGrossWeight = ISNULL(gross_weight,0)
					,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
					,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END 
	
		--------------------------------------------------
		--Set Input Base Qty 
		--------------------------------------------------
		SET @v_fltQtyConversion = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);

		-------------------------------------------------------------
		-- Get Qty_Plan, Qty_Pick, uom, conversion_factor ของแผน
		-- Unpick Qty = STG Qty - Qty Pack (if have pack)
		-------------------------------------------------------------
		SET @v_fltCheckQtyUnpick = NULL
		IF (@v_vchRulePickPack = 'YES')
			BEGIN
				--PRINT 'PICK AND PACK'
				SELECT @v_fltCheckQtyUnpick = ROUND(SUM(ISNULL(tPack.quantity_stage,0) -
															(CASE WHEN ISNULL(tPack.quantity_load,0) > 0 AND ISNULL(tPack.quantity_load,0) > ISNULL(pickDT.quantity_ship,0) AND ISNULL(tPack.quantity_load,0) > ISNULL(tPack.quantity_pack,0) THEN ISNULL(tPack.quantity_load,0)
																  WHEN ISNULL(tPack.quantity_pack,0) > 0 AND ISNULL(tPack.quantity_pack,0) > ISNULL(pickDT.quantity_ship,0) AND ISNULL(tPack.quantity_pack,0) > ISNULL(tPack.quantity_load,0) THEN ISNULL(tPack.quantity_pack,0)
																  ELSE ISNULL(pickDT.quantity_ship,0) END)),@Round)
				FROM t_wms_outbound_pick_master pickMS
				INNER JOIN t_wms_outbound_pick_detail pickDT on pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				INNER JOIN t_wms_outbound_pack_detail tPack ON tPack.outbound_pick_detail_id = pickDT.outbound_pick_detail_id
				WHERE pickMS.outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND pickMS.wh_master_id = @v_vchWhMasterID
				AND ISNULL(pickDT.quantity_pick,0) > 0
				AND pickDT.is_override = 'NO'
				AND tPack.staging_location_id = @v_vchStgLocationID
				AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(tPack.staging_parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(tPack.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
				AND ISNULL(tPack.lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(tPack.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(tPack.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(tPack.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(tPack.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(tPack.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(tPack.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(tPack.serial_number,'') END) = (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
			END
		ELSE
			BEGIN
				--PRINT 'PICK'
				SELECT @v_fltCheckQtyUnpick = ROUND(SUM(ISNULL(pickDT.quantity_stage,0) -
															(CASE WHEN ISNULL(pickDT.quantity_load,0) > 0 AND ISNULL(pickDT.quantity_load,0) > ISNULL(pickDT.quantity_ship,0) AND ISNULL(pickDT.quantity_load,0) > ISNULL(pickDT.quantity_pack,0) THEN ISNULL(pickDT.quantity_load,0)
																  WHEN ISNULL(pickDT.quantity_pack,0) > 0 AND ISNULL(pickDT.quantity_pack,0) > ISNULL(pickDT.quantity_ship,0) AND ISNULL(pickDT.quantity_pack,0) > ISNULL(pickDT.quantity_load,0) THEN ISNULL(pickDT.quantity_pack,0)
																  ELSE ISNULL(pickDT.quantity_ship,0) END)),@Round)
				FROM t_wms_outbound_pick_master pickMS 
				INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				WHERE pickMS.outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND pickMS.wh_master_id = @v_vchWhMasterID
				AND ISNULL(pickDT.quantity_pick,0) > 0
				AND pickDT.is_override = 'NO'
				AND pickDT.staging_location_id = @v_vchStgLocationID
				AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(pickDT.staging_parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(pickDT.staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
				AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(pickDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(pickDT.serial_number,'') END) = (CASE @in_vchSerialNumber WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
			END	
			
		IF (@v_fltCheckQtyUnpick IS NULL)
			BEGIN
				SET @out_ErrorCode = 'INFO_NOT_FOUND_DATA_FOR_UNPICK'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchOutboundOrderNumber,@in_vchItemNumber,'@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END

		--------------------------------------------------------------------------
		-- ถ้า (จำนวนที่สแกน) มากกว่า (จำนวนที่ Pick ไปแล้ว)
		--------------------------------------------------------------------------
		IF (ROUND(@v_fltQtyConversion,@Round) > ROUND(ISNULL(@v_fltCheckQtyUnpick,0),@Round))
			BEGIN
				SET @out_ErrorCode = 'INFO-QTY-MORE-THAN-QTY-PICK'
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchOutboundOrderNumber,@in_vchItemNumber,'@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END

-------------------------------------------------
-- 1. Unpick
-- 3. Release Order
-- **ถ้า Load แล้ว Unpick ไม่ได้
-------------------------------------------------
BEGIN TRANSACTION
SET @v_vchBeginTrans = 1;
	
	-------------------------------------------------
	-- 1.Unpick
	-------------------------------------------------
	BEGIN
		IF @v_vchRulePickPack = 'YES'
			BEGIN
				DECLARE UnpickCursor CURSOR FOR
				SELECT outbound_order_detail_id
					, outbound_pick_detail_id
					, outbound_pack_detail_id
					, line_number
					, ROUND(ISNULL(quantity_pick,0),@Round)
					, ROUND(ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0),@Round)
					, CASE WHEN ISNULL(quantity_load,0) > ISNULL(quantity_pack,0) THEN ISNULL(quantity_load,0) ELSE ISNULL(quantity_pack,0) END
					, serial_number
					, default_item_status
					, receive_date
				FROM v_wms_outbound_pack_detail_mini 
				WHERE wh_master_id = @v_vchWhMasterID
				AND outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND staging_location_id = @v_vchStgLocationID
				AND is_override = 'NO'
				AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'') =  ISNULL(@in_vchExpiryDate,'') 
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
				AND ISNULL(quantity_stage,0) > 0 
				AND ROUND((ISNULL(quantity_stage,0) - (CASE WHEN ISNULL(quantity_load,0) > 0 AND ISNULL(quantity_load,0) > ISNULL(quantity_ship,0) AND ISNULL(quantity_load,0) > ISNULL(quantity_pack,0) THEN ISNULL(quantity_load,0)
															WHEN ISNULL(quantity_pack,0) > 0 AND ISNULL(quantity_pack,0) > ISNULL(quantity_ship,0) AND ISNULL(quantity_pack,0) > ISNULL(quantity_load,0) THEN ISNULL(quantity_pack,0)
															ELSE ISNULL(quantity_ship,0) END)),@Round) > 0
			END
		ELSE
			BEGIN
				DECLARE UnpickCursor CURSOR FOR
				SELECT outbound_order_detail_id
					, outbound_pick_detail_id
					, NULL		--Pick อย่างเดียวจึงไม่มี outbound_pack_detail_id
					, line_number
					, ROUND(ISNULL(quantity_pick,0),@Round)
					, ROUND(ISNULL(quantity_stage,0) - ISNULL(quantity_ship,0),@Round)	--เนื่องจากมี Partial Ship
					, CASE WHEN ISNULL(quantity_load,0) > ISNULL(quantity_pack,0) THEN ISNULL(quantity_load,0) ELSE ISNULL(quantity_pack,0) END
					, serial_number
					, default_item_status
					, receive_date
				FROM v_wms_outbound_pick_detail_id
				WHERE wh_master_id = @v_vchWhMasterID
				AND outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND staging_location_id = @v_vchStgLocationID
				AND is_override = 'NO'
				AND ISNULL(staging_parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(staging_lpn,'') = ISNULL(@in_vchStgLPN,'')
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'') =  ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@in_vchSerialNumber,'') WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNumber,'') END)
				AND ISNULL(quantity_stage,0) > 0
				AND ROUND((ISNULL(quantity_stage,0) - (CASE WHEN ISNULL(quantity_load,0) > 0 AND ISNULL(quantity_load,0) > ISNULL(quantity_ship,0) AND ISNULL(quantity_load,0) > ISNULL(quantity_pack,0) THEN ISNULL(quantity_load,0)
															WHEN ISNULL(quantity_pack,0) > 0 AND ISNULL(quantity_pack,0) > ISNULL(quantity_ship,0) AND ISNULL(quantity_pack,0) > ISNULL(quantity_load,0) THEN ISNULL(quantity_pack,0)
															ELSE ISNULL(quantity_ship,0) END)),@Round) > 0
			END
		OPEN UnpickCursor
		FETCH NEXT FROM UnpickCursor INTO @v_vchOutboundOrderDetailID, @v_vchOutboundPickDetailID, @v_vchOutboundPackDetailID, @v_vchLineNumber, @v_fltQuantityPick, @v_fltQuantityRemain, @v_fltQuantityLoad, @v_vchSerialNumber, @v_vchDefaultStatus,@v_dtReceiveDate
		WHILE @@FETCH_STATUS = 0
			BEGIN
				--2023-07-19 : ถ้า STG LPN = Order Number แสดงว่าเป็น LPN ไม่แท้ จะต้อง set LPN ใหม่ ใช้ตัวเดียวกับ stg ไม่ได้ เพราะว่าจะทำให้ LPN ซ้ำกันกับ location  
				IF @in_vchStgLPN = @in_vchOutboundOrderNumber
					BEGIN
						SET @v_vchAfterLPN = 'UNPICK_' + ISNULL(@in_vchStgLPN,'')
					END
				ELSE
					BEGIN 
						SET @v_vchAfterLPN = @in_vchStgLPN
					END
 
				-------------------------------------------------
				-- 2. Unpick : จะ Unpick ได้เฉพาะ ส่วนที่ยังไม่ได้ load และยังไม่ได้ pack
				-------------------------------------------------
				SET @v_fltRemainUnpick = (CASE WHEN ROUND(@v_fltQuantityLoad,@Round) > 0 THEN ROUND(@v_fltQuantityPick - @v_fltQuantityLoad,@Round) ELSE ROUND(@v_fltQuantityRemain,@Round) END)
				
				IF (@v_fltQtyConversion > ROUND(@v_fltRemainUnpick,@Round))
					BEGIN
						SET @v_fltQuantityUnpick = ROUND(@v_fltRemainUnpick,@Round)
					END
				ELSE
					BEGIN
						SET @v_fltQuantityUnpick = @v_fltQtyConversion
					END

				------------------------------------------------
				-- Update ข้อมูล Unpick Unpack Unstage
				-- If auto pick pack will be unpick and unpack 
				-- else update unpick only
				------------------------------------------------
				IF @v_vchRulePickPack = 'YES'
					BEGIN
						UPDATE t_wms_outbound_pack_detail SET 
							 quantity_pack = ROUND((quantity_pack - @v_fltQuantityUnpick),@Round)
							,quantity_stage = ROUND((quantity_stage - @v_fltQuantityUnpick),@Round)
						WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID
				
						UPDATE t_wms_outbound_pick_detail SET 
							quantity_plan = ROUND((quantity_plan - @v_fltQuantityUnpick ),@Round)
							,quantity_pick = ROUND((quantity_pick - @v_fltQuantityUnpick ),@Round)
							,quantity_pack = (CASE ISNULL(quantity_pack,0) WHEN 0 THEN 0 ELSE ROUND((quantity_pack - @v_fltQuantityUnpick),@Round) END)
							,quantity_stage = ROUND((quantity_stage - @v_fltQuantityUnpick),@Round) 
						WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

						--ถ้า Unpick ทั้งหมดจะ ลบ record ออกไม่งั้นยอด allocate จะผิด
						DELETE t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND ISNULL(quantity_plan,0) = 0

						UPDATE t_wms_outbound_detail SET 
							quantity_pick = ROUND((ISNULL(quantity_pick,0) - @v_fltQuantityUnpick),@Round)
							,quantity_stage = ROUND((ISNULL(quantity_stage,0) - @v_fltQuantityUnpick),@Round)
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID

						--หากจำนวนเป็น 0 ให้ Delete Row ทิ้ง
						DELETE t_wms_outbound_pack_detail WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID AND quantity_pack = 0 AND quantity_stage = 0
					END
				ELSE
					BEGIN
						UPDATE t_wms_outbound_pick_detail SET 
							quantity_plan = ROUND((quantity_plan - @v_fltQuantityUnpick ),@Round)
							,quantity_pick = ROUND((quantity_pick - @v_fltQuantityUnpick ),@Round) 
							,quantity_stage = ROUND((quantity_stage - @v_fltQuantityUnpick),@Round) 
						WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

						--ถ้า Unpick ทั้งหมดจะ ลบ record ออกไม่งั้นยอด allocate จะผิด
						DELETE t_wms_outbound_pick_detail WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID AND ISNULL(quantity_plan,0) = 0

						UPDATE t_wms_outbound_detail SET 
							 quantity_pick = ROUND((ISNULL(quantity_pick,0) - @v_fltQuantityUnpick),@Round)
							,quantity_stage = ROUND((ISNULL(quantity_stage,0) - @v_fltQuantityUnpick),@Round)
						WHERE outbound_order_detail_id = @v_vchOutboundOrderDetailID
					END


				IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
					BEGIN
						SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQuantityUnpick,2)
						SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQuantityUnpick,2)
					END

				------------------------------------------------
				--ย้ายของไปอยู่ Location Unpick
				--Manage Source inventory
				------------------------------------------------
				SET @v_vchInventoryID = NULL;
				SET @v_vchAttributeGroupID = NULL;
				SET @v_vchDefaultStatusID = NULL;
				SET @v_dtMfgDate = NULL;
				SELECT @v_vchDefaultStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @v_vchDefaultStatus AND is_active = 'YES'
				SELECT @v_vchInventoryID = inventory_id
					, @v_vchAttributeGroupID = attribute_group_id
					, @v_fltInvQuantity = quantity
					, @v_dtMfgDate = mfg_date
				FROM v_wms_inventory_data_serial_by_id
				WHERE wh_master_id  = @v_vchWhMasterID
				AND location_id = @v_vchStgLocationID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchStgLPN,'')
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND inventory_status_id = @v_vchDefaultStatusID
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
				AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(serial_number,'') = ISNULL(@v_vchSerialNumber,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND receive_date = @v_dtReceiveDate

				---------------------------------------
				-- Check Inventory
				---------------------------------------
				IF (@v_vchInventoryID IS NULL)
				BEGIN
					SET @out_ErrorCode = '999'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchOutboundOrderNumber,@in_vchStgLocation,'@param3',@in_vchStgLPN,'@param5')
					GOTO WRITE_PROCESSLOG;
				END

				---------------------------------------------------
				-- Manage source location data
				---------------------------------------------------
				BEGIN
					--Update Volumn & Weight in from location
					IF @v_vchStgLocationID IS NOT NULL
						BEGIN
							UPDATE [dbo].[t_wms_location]
								SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
								, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
								, update_date = GETDATE()  
								, [update_by] = @in_vchUserID   
								WHERE [location_id] = @v_vchStgLocationID
						END

					UPDATE t_wms_inventory SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQuantityUnpick,@Round),@Round) 
						,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
						,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID

					IF (@v_vchSNControl = 'FULL')
						BEGIN
							UPDATE t_wms_inventory_attribute SET  quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQuantityUnpick,@Round),@Round) 
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID 
							AND attribute_value = @v_vchSerialNumber
						END

					IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQuantityUnpick,@Round),@Round)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
						END
				END

				------------------------------------------------
				-- Clear Inventory ที่หยิบของหมดแล้ว
				------------------------------------------------
				DELETE t_wms_inventory_attribute WHERE inventory_id = @v_vchInventoryID AND quantity <= 0
				DELETE t_wms_inventory WHERE inventory_id = @v_vchInventoryID AND quantity <= 0
				
				IF @v_vchLPNControlUnPick = 'NO'
					BEGIN
						SET @v_vchAfterLPN = ''
					END

				--------------------------------------------
				--Manage Destination inventory
				--------------------------------------------
				SET @v_vchInventoryID = NULL;
				SET @v_vchAttributeGroupID = NULL;
				SELECT @v_vchInventoryID = inventory_id
					, @v_vchAttributeGroupID = attribute_group_id
				FROM v_wms_inventory_data_mini
				WHERE wh_master_id = @v_vchWhMasterID 
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND location_id = @v_vchUnpickLocationID
				AND inventory_status_id = @v_vchDefaultStatusID
				AND ISNULL(parent_lpn,'') = ISNULL(@in_vchStgParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@v_vchAfterLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'') 
				AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND receive_date = @v_dtReceiveDate

				EXEC usp_manage_inventory @in_vchWhMasterID		  = @v_vchWhMasterID
										, @in_vchOwnerID		  = @v_vchOwnerID
										, @in_vchWhItemMasterID	  = @v_vchWhItemMasterID
										, @in_vchLocationID		  = @v_vchUnpickLocationID
										, @in_vchStatusID		  = @v_vchDefaultStatusID
										, @in_vchPalentLPN		  = @in_vchStgParentLPN
										, @in_vchLPN			  = @v_vchAfterLPN
										, @in_fltQty			  = @v_fltQuantityUnpick
										, @in_fltQtyAllocate	  = 0
										, @in_fltQtyIncoming	  = 0
										, @in_vchInventoryType	  = 'INVENTORY'
										, @in_vchUserID			  = @in_vchUserID
										, @in_vchReceiveDate	  = @v_dtReceiveDate
										, @in_dtMFGDate			  = @v_dtMFGDate
										, @in_vchInventoryID	  = @v_vchInventoryID OUTPUT
										, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
										, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
										, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

				IF (@out_ErrorCode <> '0')
					GOTO WRITE_PROCESSLOG;
					
				--Update Volumn & Weight in from location
				IF @v_vchUnpickLocationID IS NOT NULL
					BEGIN
						UPDATE [dbo].[t_wms_location]
							SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
							, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
							, update_date = GETDATE()  
							, [update_by] = @in_vchUserID   
							WHERE [location_id] = @v_vchUnpickLocationID
					END
				
				--update volumn & weight ของ LPN
				UPDATE t_wms_inventory SET 
					 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
					,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
				WHERE inventory_id = @v_vchInventoryID
				AND attribute_group_id = @v_vchAttributeGroupID	

				IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						EXEC usp_manage_inventory_attribute 
							  @in_vchLot				= @in_vchLotNumber
							, @in_vchExpiryDate			= @in_vchExpiryDate
							, @in_vchSerialNo			= @v_vchSerialNumber
							, @in_vchAttribute1			= @in_vchAttribute1
							, @in_vchAttribute2			= @in_vchAttribute2
							, @in_vchAttribute3			= @in_vchAttribute3
							, @in_vchAttribute4			= @in_vchAttribute4
							, @in_vchAttribute5			= @in_vchAttribute5
							, @in_fltQty				= @v_fltQuantityUnpick
							, @in_fltQtyAllocate		= 0
							, @in_fltQtyIncoming		= 0
							, @in_vchInventoryID		= @v_vchInventoryID
							, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
							, @in_vchLotControl			= @v_vchLotControl
							, @in_vchSNControl			= @v_vchSNControl
							, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
							, @in_vchAttribute1Control	= @v_vchAttribute1Control
							, @in_vchAttribute2Control	= @v_vchAttribute2Control
							, @in_vchAttribute3Control	= @v_vchAttribute3Control
							, @in_vchAttribute4Control	= @v_vchAttribute4Control
							, @in_vchAttribute5Control	= @v_vchAttribute5Control
							, @in_vchUserID				= @in_vchUserID
							, @in_vchErrorCode			= @out_ErrorCode OUTPUT
							, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
						IF(@out_ErrorCode <> '0')
							GOTO WRITE_PROCESSLOG;
					END	
				
				--------------------------------------------
				--tran type		>> INV_MOVE	   
				--sub tran type >> MOVE_UNPICK		   
				--------------------------------------------
				INSERT INTO [dbo].[t_com_tran_log]
					   ([app_id]				
					   ,[tran_type]				
					   ,[sub_tran_type]			
					   ,[app_name]				
					   ,[description]			
					   ,[start_tran_datetime]	
					   ,[end_tran_datetime]		
					   ,[warehouse]				
					   ,[to_warehouse]			
					   ,[location]				
					   ,[to_location]			
					   ,[owner]					
					   ,[to_owner]				
					   ,[item_number]			
					   ,[quantity]				
					   ,[quantity_uom]			
					   ,[after_quantity]		
					   ,[after_quantity_uom]	
					   ,[lot_number]			
					   ,[after_lot_number]		
					   ,[expiry_date]			
					   ,[after_expiry_date]		
					   ,[serial_number]			
					   ,[attribute1]			
					   ,[after_attribute1]		
					   ,[attribute2]			
					   ,[after_attribute2]		
					   ,[attribute3]			
					   ,[after_attribute3]		
					   ,[attribute4]			
					   ,[after_attribute4]		
					   ,[attribute5]			
					   ,[after_attribute5]		
					   ,[user_id]	
					   ,[lpn]					
					   ,[after_lpn]				
					   ,[parent_lpn]			
					   ,[after_parent_lpn]		
					   ,[status]				
					   ,[after_status]		
					   ,[order_number]			
					   ,[line_number]
					   ,[receive_date]
					   ,[mfg_date]
					   ,[input_quantity]
					   ,[input_uom]
					   ,[device]
					   ,[create_date]
					   ,[create_by])
				 VALUES
					   (@in_vchApplicationID					
					   ,'INV_MOVE'		
					   ,'MOVE_UNPICK'	
					   ,@v_vchApplicationName				
					   ,'Move item to unpick'				
					   ,@v_vchStartTrans				
					   ,GETDATE()						
					   ,@in_vchWarehouse				
					   ,@in_vchWarehouse				
					   ,@in_vchStgLocation				
					   ,@v_vchUnpickLocation				
					   ,@in_vchOwner					
					   ,@in_vchOwner					
					   ,@in_vchItemNumber			
					   ,@v_fltQuantityUnpick							
					   ,@v_vchBaseUomPrompt				
					   ,(@v_fltInvQuantity - @v_fltQuantityUnpick)				
					   ,@v_vchBaseUomPrompt					
					   ,@in_vchLotNumber				
					   ,@in_vchLotNumber				
					   ,@in_vchExpiryDate			
					   ,@in_vchExpiryDate			
					   ,@in_vchSerialNumber				
					   ,@in_vchAttribute1			
					   ,@in_vchAttribute1			
					   ,@in_vchAttribute2			
					   ,@in_vchAttribute2			
					   ,@in_vchAttribute3			
					   ,@in_vchAttribute3			
					   ,@in_vchAttribute4			
					   ,@in_vchAttribute4			
					   ,@in_vchAttribute5			
					   ,@in_vchAttribute5			
					   ,@in_vchUserID						
					   ,@in_vchStgLPN					
					   ,@v_vchAfterLPN					
					   ,@in_vchStgParentLPN				
					   ,@in_vchStgParentLPN				
					   ,@v_vchDefaultStatus		
					   ,@v_vchDefaultStatus	 
					   ,@in_vchOutboundOrderNumber		
					   ,@v_vchLineNumber
					   ,@v_dtReceiveDate
					   ,@v_dtMFGDate
					   ,@v_fltQuantityUnpick
					   ,@in_vchUOM	
					   ,@in_vchDeviceID
					   ,GETDATE()	
					   ,@in_vchUserID) 
				
				------------------------------------------------
				--จำนวน Unpick คงเหลือ
				------------------------------------------------
				SET @v_fltQtyConversion = ROUND((@v_fltQtyConversion - @v_fltQuantityUnpick),@Round)
				IF @v_fltQtyConversion = 0
					BREAK;

			FETCH NEXT FROM UnpickCursor INTO @v_vchOutboundOrderDetailID, @v_vchOutboundPickDetailID, @v_vchOutboundPackDetailID, @v_vchLineNumber, @v_fltQuantityPick, @v_fltQuantityRemain, @v_fltQuantityLoad, @v_vchSerialNumber, @v_vchDefaultStatus,@v_dtReceiveDate
			END
		CLOSE UnpickCursor
		DEALLOCATE UnpickCursor
		--UPDATE t_wms_outbound_master set order_status = 'PICK' WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
	END

	--IF Release/Rerun แล้วไม่มีของหยิบให้กลับไปเป็น Release แต่ถ้ายังมีของหยิบเป็น 
	DECLARE @v_vchUpdateOrderStatus VARCHAR(20) = NULL
	IF EXISTS (SELECT * FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID AND ISNULL(quantity_pick,0) > 0)
		BEGIN
			SET @v_vchUpdateOrderStatus = 'PICK'
		END
	ELSE
		BEGIN
			SET @v_vchUpdateOrderStatus = 'RELEASE'
		END

	UPDATE t_wms_outbound_master SET order_status = @v_vchUpdateOrderStatus
		, pick_type = @v_vchPickType
		, pick_by = (CASE WHEN @v_vchUpdateOrderStatus = 'RELEASE' THEN NULL ELSE pick_by END)
	WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID

	COMMIT TRANSACTION;

	-------------------------------------------------	
	-- 2.Release Order
	-------------------------------------------------
	BEGIN
		IF @v_vchPickType = 'SYSTEM'
		BEGIN
			DECLARE @v_vchErrorRelease NVARCHAR(255)
			EXEC usp_outbound_release_order @in_vchApplicationID		= @in_vchApplicationID		
										   ,@in_vchOutboundMasterID		= @v_vchOutboundOrderMasterID	
										   ,@in_vchDeviceID				= @in_vchDeviceID				
										   ,@in_vchUserID				= @in_vchUserID	
										   ,@out_ErrorCode				= @out_ErrorCode output
										   ,@out_ErrorMessage			= @v_vchErrorRelease output
			IF @out_ErrorCode <> '0'
				BEGIN 					 
					SET @out_ErrorCode = '0';
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'UNPICK_SUCCESS_CANNOT_RELEASE',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5') + '' + @v_vchErrorRelease
					RETURN;
				END
		END
	END
 
	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;

	------------------------------------------
	--Write process log
	------------------------------------------
	BEGIN
	WRITE_PROCESSLOG:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','UnpickCursor')>=-1
			BEGIN
				CLOSE UnpickCursor;
				DEALLOCATE UnpickCursor;
			END

		SET @v_dtProcessDateTime = GETDATE();		
		EXEC usp_LogManager
		   @in_vchApplicationID = @in_vchApplicationID,
		   @in_vchWhID = @in_vchWarehouse,
		   @in_vchDevice = @in_vchDeviceID,
		   @in_vchUserID = @in_vchUserID,
		   @in_vchLogType = 'PROCESS',
		   @in_vchProcess = @c_vchObjName,
		   @in_dtProcessDateTime = @v_dtProcessDateTime,
		   @in_vchData1 = @in_vchOutboundOrderNumber,
		   @in_vchData2 = @in_vchStgLocation,
		   @in_vchData3 = @in_vchItemNumber,
		   @in_vchData4 = @in_fltQuantity,
		   @in_vchErrorCode = @out_ErrorCode,
		   @in_vchMessage = @out_ErrorMessage
	END
END TRY

BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
		 
	IF CURSOR_STATUS('global','UnpickCursor')>=-1
		BEGIN
			CLOSE UnpickCursor;
			DEALLOCATE UnpickCursor;
		END
		 
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	SET @v_dtProcessDateTime = GETDATE();	
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchOutboundOrderNumber,
		@in_vchData2 = @in_vchStgLocation,
		@in_vchData3 = @in_vchItemNumber,
		@in_vchData4 = @in_fltQuantity,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage
		 
	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unrelease]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unrelease]
	@in_vchApplicationID		VARCHAR(40), 
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25), 
	@in_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
	@out_ErrorCode				NVARCHAR(200) OUTPUT,
	@out_ErrorMessage			NVARCHAR(500) OUTPUT
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE @c_vchObjName			NVARCHAR(30) = '[usp_outbound_unrelease]',
			@v_dtProcessDateTime	DATETIME,
			@v_vchBeginTrans		BIT = 0,
			@Round					INT,

			@v_vchWhMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchWarehouse			NVARCHAR(25),
			@v_vchOutboundOrderNumber NVARCHAR(50) = NULL,
			@v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchOrderStatus		NVARCHAR(10), 
			@v_vchParentLPN			NVARCHAR(25),
			@v_vchLPN				NVARCHAR(25),
			@v_vchDefaultItemStatus	NVARCHAR(50),
			@v_vchLotNumber			NVARCHAR(50),
			@v_vchExpiryDate		NVARCHAR(8),
			@v_vchSerialNumber		NVARCHAR(100),
			@v_vchAttribute1		NVARCHAR(100),
			@v_vchAttribute2		NVARCHAR(100),
			@v_vchAttribute3		NVARCHAR(100),
			@v_vchAttribute4		NVARCHAR(100),
			@v_vchAttribute5		NVARCHAR(100),
			@v_dtReceiveDate		DATE,
			@v_fltRemainPickQTY		FLOAT
			
	BEGIN TRY
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES' 
		SELECT @v_vchOutboundOrderNumber = outbound_order_number
			,@v_vchWhMasterID = wh_master_id
			,@v_vchWarehouse = wh_id
			,@v_vchOrderStatus = order_status 
		FROM t_wms_outbound_master 
		WHERE outbound_order_master_id = @in_vchOutboundMasterID
		IF(@v_vchOrderStatus NOT IN ('RELEASE','OPEN','PICK'))
			BEGIN
				SET @out_ErrorCode = 'CANNOT_UNRELEASE_ORDER';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
		
		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1;
			
		--Check Rule Control Pickface ถ้า Control ต้อง Check ว่ามีการ Create Job Replenishment หรือไม่ 
		--ถ้ามี ต้อง Clear Job ที่ Replenishment ด้วย
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_CONTROL_PICKFACE' AND is_active = 'YES') = 'YES')
			BEGIN
				DECLARE @v_vchReplenishmentID	   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnWhMasterID		   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnOwnerID		   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnSourceLocationID  UNIQUEIDENTIFIER = NULL,
						@v_vchRpnDestLocationID	   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnInvStatusID	   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnSourceParentLPN   NVARCHAR(25),
						@v_vchRpnDestParentLPN	   NVARCHAR(25),
						@v_vchRpnLPN			   NVARCHAR(25),
						@v_vchRpnWhItemMasterID	   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnLotNumber		   NVARCHAR(100),
						@v_vchRpnExpiryDate		   NVARCHAR(100),
						@v_vchRpnAttribute1		   NVARCHAR(100),
						@v_vchRpnAttribute2		   NVARCHAR(100),
						@v_vchRpnAttribute3		   NVARCHAR(100),
						@v_vchRpnAttribute4		   NVARCHAR(100),
						@v_vchRpnAttribute5		   NVARCHAR(100),
						@v_fltRpnQuantityPlan	   FLOAT,
						@v_vchInventoryID		   UNIQUEIDENTIFIER = NULL,
						@v_vchAttrGroupID		   UNIQUEIDENTIFIER = NULL,
						@v_vchRpnLotControl		   VARCHAR(5),
						@v_vchRpnExpControl		   VARCHAR(5),
						@v_vchRpnAttribute1Control VARCHAR(5),
						@v_vchRpnAttribute2Control VARCHAR(5),
						@v_vchRpnAttribute3Control VARCHAR(5),
						@v_vchRpnAttribute4Control VARCHAR(5),
						@v_vchRpnAttribute5Control VARCHAR(5)

				--Delete Job
				DECLARE Replenishment_Cursor CURSOR FOR
				SELECT rpn.replenishment_id
					,rpn.wh_master_id
					,rpn.owner_id
					,rpn.inventory_status_id
					,rpn.source_location_id
					,rpn.destination_location_id
					,rpn.source_parent_lpn
					,rpn.destination_parent_lpn
					,rpn.lpn
					,rpn.wh_item_master_id
					,rpn.lot_number
					,rpn.expiry_date
					,rpn.attribute1
					,rpn.attribute2
					,rpn.attribute3
					,rpn.attribute4
					,rpn.attribute5
					,rpn.quantity_plan
					,item.lot_control
					,item.expiry_date_control
					,item.attribute1_control
					,item.attribute2_control
					,item.attribute3_control
					,item.attribute4_control
					,item.attribute5_control
				FROM t_wms_replenishment rpn
				LEFT JOIN t_wms_wh_item whItem ON rpn.wh_item_master_id = whItem.wh_item_master_id
				LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
				WHERE rpn.ref_order_number = @v_vchOutboundOrderNumber
				AND rpn.wh_master_id = @v_vchWhMasterID 
				AND rpn.replenishment_status = 'OPEN'
					
				OPEN Replenishment_Cursor 
				FETCH NEXT FROM Replenishment_Cursor INTO @v_vchReplenishmentID, @v_vchRpnWhMasterID, @v_vchRpnOwnerID, @v_vchRpnInvStatusID, @v_vchRpnSourceLocationID	
														, @v_vchRpnDestLocationID, @v_vchRpnSourceParentLPN, @v_vchRpnDestParentLPN, @v_vchRpnLPN, @v_vchRpnWhItemMasterID
														, @v_vchRpnLotNumber, @v_vchRpnExpiryDate, @v_vchRpnAttribute1, @v_vchRpnAttribute2, @v_vchRpnAttribute3
														, @v_vchRpnAttribute4, @v_vchRpnAttribute5, @v_fltRpnQuantityPlan, @v_vchRpnLotControl, @v_vchRpnExpControl	
														, @v_vchRpnAttribute1Control, @v_vchRpnAttribute2Control, @v_vchRpnAttribute3Control, @v_vchRpnAttribute4Control
														, @v_vchRpnAttribute5Control

				BEGIN
					--คืนยอด Allocate ใน inventory ของ Source Location
					SET @v_vchInventoryID = NULL
					SET @v_vchAttrGroupID = NULL
					SELECT @v_vchInventoryID = inventory_id
						,@v_vchAttrGroupID = attribute_group_id
					FROM v_wms_inventory_data_mini
					WHERE wh_master_id = @v_vchRpnWhMasterID
					AND owner_id = @v_vchRpnOwnerID
					AND location_id = @v_vchRpnSourceLocationID
					AND inventory_status_id = @v_vchRpnInvStatusID
					AND wh_item_master_id = @v_vchRpnWhItemMasterID
					AND ISNULL(parent_lpn,'') = ISNULL(@v_vchRpnSourceParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@v_vchRpnLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@v_vchRpnLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchRpnExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@v_vchRpnAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@v_vchRpnAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@v_vchRpnAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@v_vchRpnAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@v_vchRpnAttribute5,'')

					UPDATE t_wms_inventory SET 
						quantity_allocated = ROUND((ISNULL(quantity_allocated,0) - @v_fltRpnQuantityPlan),@Round)
					WHERE inventory_id = @v_vchInventoryID
					AND attribute_group_id = @v_vchAttrGroupID

					IF ('FULL' IN (@v_vchRpnLotControl, @v_vchRpnExpControl,@v_vchRpnAttribute1Control,@v_vchRpnAttribute2Control,@v_vchRpnAttribute3Control,@v_vchRpnAttribute4Control,@v_vchRpnAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET
								quantity_allocated = ROUND((ISNULL(quantity_allocated,0) - @v_fltRpnQuantityPlan),@Round)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttrGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
						END

					DELETE t_wms_inventory_attribute WHERE quantity <= 0 and inventory_id = @v_vchInventoryID
					DELETE t_wms_inventory WHERE quantity <= 0 and inventory_id = @v_vchInventoryID

																   	
					--ลบยอด Incoming ใน inventory ของ Destination Location
					SET @v_vchInventoryID = NULL
					SET @v_vchAttrGroupID = NULL
					SELECT @v_vchInventoryID = inventory_id
						,@v_vchAttrGroupID = attribute_group_id
					FROM v_wms_inventory_data_mini
					WHERE wh_master_id = @v_vchRpnWhMasterID
					AND owner_id = @v_vchRpnOwnerID
					AND location_id = @v_vchRpnDestLocationID
					AND inventory_status_id = @v_vchRpnInvStatusID
					AND wh_item_master_id = @v_vchRpnWhItemMasterID
					AND ISNULL(parent_lpn,'') = ISNULL(@v_vchRpnDestParentLPN,'')
					AND ISNULL(lpn,'') = ISNULL(@v_vchRpnLPN,'')
					AND ISNULL(lot_number,'') = ISNULL(@v_vchRpnLotNumber,'')
					AND ISNULL(expiry_date,'') = ISNULL(@v_vchRpnExpiryDate,'')
					AND ISNULL(attribute1,'') = ISNULL(@v_vchRpnAttribute1,'')
					AND ISNULL(attribute2,'') = ISNULL(@v_vchRpnAttribute2,'')
					AND ISNULL(attribute3,'') = ISNULL(@v_vchRpnAttribute3,'')
					AND ISNULL(attribute4,'') = ISNULL(@v_vchRpnAttribute4,'')
					AND ISNULL(attribute5,'') = ISNULL(@v_vchRpnAttribute5,'')

					UPDATE t_wms_inventory SET 
						quantity_incoming = ROUND((ISNULL(quantity_incoming,0) - @v_fltRpnQuantityPlan),@Round)
					WHERE inventory_id = @v_vchInventoryID
					AND attribute_group_id = @v_vchAttrGroupID

					IF ('FULL' IN (@v_vchRpnLotControl, @v_vchRpnExpControl,@v_vchRpnAttribute1Control,@v_vchRpnAttribute2Control,@v_vchRpnAttribute3Control,@v_vchRpnAttribute4Control,@v_vchRpnAttribute5Control))
						BEGIN
							UPDATE t_wms_inventory_attribute SET
								quantity_incoming = ROUND((ISNULL(quantity_incoming,0) - @v_fltRpnQuantityPlan),@Round)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttrGroupID
							AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
						END
					
					--Update Replenishment status = cancel
					UPDATE t_wms_replenishment SET replenishment_status = 'CANCEL' WHERE replenishment_id = @v_vchReplenishmentID
						
					FETCH NEXT FROM Replenishment_Cursor INTO @v_vchReplenishmentID, @v_vchRpnWhMasterID, @v_vchRpnOwnerID, @v_vchRpnInvStatusID, @v_vchRpnSourceLocationID	
														, @v_vchRpnDestLocationID, @v_vchRpnSourceParentLPN, @v_vchRpnDestParentLPN, @v_vchRpnLPN, @v_vchRpnWhItemMasterID
														, @v_vchRpnLotNumber, @v_vchRpnExpiryDate, @v_vchRpnAttribute1, @v_vchRpnAttribute2, @v_vchRpnAttribute3
														, @v_vchRpnAttribute4, @v_vchRpnAttribute5, @v_fltRpnQuantityPlan, @v_vchRpnLotControl, @v_vchRpnExpControl	
														, @v_vchRpnAttribute1Control, @v_vchRpnAttribute2Control, @v_vchRpnAttribute3Control, @v_vchRpnAttribute4Control
														, @v_vchRpnAttribute5Control	
				END

				CLOSE Replenishment_Cursor
				DEALLOCATE Replenishment_Cursor				
			END

		DECLARE OutboundUnAllocateCURSOR CURSOR FOR
			SELECT pickDT.location_id
				,pickDT.parent_lpn
				,pickDT.lpn
				,pickDT.wh_item_master_id
				,pickDT.lot_number
				,pickDT.expiry_date
				,pickDT.serial_number
				,pickDT.attribute1
				,pickDT.attribute2
				,pickDT.attribute3
				,pickDT.attribute4
				,pickDT.attribute5
				,ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) AS quantity_remain_pick
				,pickDT.receive_date
				,obDT.default_item_status
			FROM t_wms_outbound_pick_master pickMS
			INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
			INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
			WHERE pickMS.outbound_order_master_id = @in_vchOutboundMasterID 
			AND ROUND((ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0)),@Round) > 0 
			AND pickDT.is_override = 'NO'	
		OPEN OutboundUnAllocateCURSOR;
		FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchWhItemMasterID,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
												,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltRemainPickQTY,@v_dtReceiveDate,@v_vchDefaultItemStatus
			WHILE @@FETCH_STATUS = 0
				BEGIN
					-- un allocate inventory data
					EXEC [usp_inventory_un_allocate]  @in_vchApplicationID		= @in_vchApplicationID	
													, @in_vchWarehouseMasterID	= @v_vchWhMasterID	
													, @in_vchLocationID			= @v_vchLocationID
													, @in_vchParentLPN			= @v_vchParentLPN	
													, @in_vchLPN				= @v_vchLPN
													, @in_vchWhItemMasterID		= @v_vchWhItemMasterID
													, @in_fltQuantity			= @v_fltRemainPickQTY	
													, @in_vchSerialNumber		= @v_vchSerialNumber	
													, @in_vchLotNumber			= @v_vchLotNumber	
													, @in_vchExpiryDate			= @v_vchExpiryDate
													, @in_vchAttribute1			= @v_vchAttribute1
													, @in_vchAttribute2			= @v_vchAttribute2
													, @in_vchAttribute3			= @v_vchAttribute3
													, @in_vchAttribute4			= @v_vchAttribute4
													, @in_vchAttribute5			= @v_vchAttribute5
													, @in_dtReceiveDate			= @v_dtReceiveDate
													, @in_vchDefaultItemStatus	= @v_vchDefaultItemStatus
													, @in_vchUserID				= @in_vchUserID	
													, @out_ErrorCode			= @out_ErrorCode	OUTPUT
													, @out_ErrorMessage			= @out_ErrorMessage OUTPUT
					IF (@out_ErrorCode <> '0')
						BEGIN 
							GOTO WRITE_PROC;
						END
				
					FETCH FROM OutboundUnAllocateCURSOR INTO @v_vchLocationID,@v_vchParentLPN,@v_vchLPN,@v_vchWhItemMasterID,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber
															,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltRemainPickQTY,@v_dtReceiveDate,@v_vchDefaultItemStatus
				END

		CLOSE OutboundUnAllocateCURSOR;
		DEALLOCATE OutboundUnAllocateCURSOR;
		
		DECLARE @v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL
		SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE wh_master_id = @v_vchWhMasterID AND outbound_order_master_id = @in_vchOutboundMasterID

		-- Delete row pick
		DELETE FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND ISNULL(quantity_pick,0) = 0 
		IF NOT EXISTS (SELECT * FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID)
			BEGIN 
				DELETE FROM t_wms_outbound_pick_master WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
			END

		--ถ้ายังมียอดค้าง Pick อยู่ใน Unallocate เฉยๆ 
		IF NOT EXISTS (SELECT outbound_pick_master_id FROM t_wms_outbound_pick_master WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID)
			BEGIN
				UPDATE t_wms_outbound_master SET order_status = 'OPEN', pick_type = NULL,load_id = NULL WHERE outbound_order_master_id = @in_vchOutboundMasterID
			END

		COMMIT TRANSACTION;
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UNRELEASE_ORDER_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
		RETURN;
		-------------------------------------------------------------------------------------------------
		-- WRITE PROCESS LOG
		WRITE_PROC:
		-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','Replenishment_Cursor') >= -1
			BEGIN
				CLOSE Replenishment_Cursor;
				DEALLOCATE Replenishment_Cursor;
			END

		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				CLOSE OutboundUnAllocateCURSOR;
				DEALLOCATE OutboundUnAllocateCURSOR;
			END

		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
		RETURN;
		-------------------------------------------------------------------------------------------------
	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','Replenishment_Cursor') >= -1
			BEGIN
				CLOSE Replenishment_Cursor;
				DEALLOCATE Replenishment_Cursor;
			END

		IF CURSOR_STATUS('global','OutboundUnAllocateCURSOR') >= -1
			BEGIN
				CLOSE OutboundUnAllocateCURSOR;
				DEALLOCATE OutboundUnAllocateCURSOR;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END 
		
		SET @v_dtProcessDateTime = GETDATE();		
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unrelease_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unrelease_by_group]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_dtProcessDateTime		DATETIME
	DECLARE @c_vchObjName				NVARCHAR(30) = '[usp_outbound_unrelease_by_group]'
	--DECLARE @v_vchBeginTrans			BIT = 0
	DECLARE @v_vchWarehouse				NVARCHAR(25)
	DECLARE @v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOutboundOrderNumber	NVARCHAR(50)
			
	BEGIN TRY
		
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (ISNULL(@v_vchWarehouse,'') = '')
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_NOT_FOUND',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END
					
		IF EXISTS(SELECT order_status FROM t_wms_outbound_master WHERE load_id = @in_vchLoadID AND order_status NOT IN ('RELEASE','OPEN'))
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_UNRELEASE_LOAD_ID',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END
			
	--BEGIN TRANSACTION;
	--SET @v_vchBeginTrans = 1; 
		DECLARE OutboundLoad CURSOR FOR
			SELECT outbound_order_master_id 
				, outbound_order_number 
			FROM t_wms_outbound_master 
			WHERE load_id = @in_vchLoadID 
			AND wh_master_id = @in_vchWhMasterID
		OPEN OutboundLoad;
		FETCH FROM OutboundLoad INTO @v_vchOutboundMasterID, @v_vchOutboundOrderNumber

		WHILE @@FETCH_STATUS = 0
			BEGIN
				EXEC usp_outbound_unrelease  @in_vchApplicationID		= @in_vchApplicationID 
											,@in_vchDeviceID			= @in_vchDeviceID	
											,@in_vchUserID				= @in_vchUserID	
											,@in_vchOutboundMasterID	= @v_vchOutboundMasterID
											,@out_ErrorCode				= @out_ErrorCode OUTPUT
											,@out_ErrorMessage			= @out_ErrorMessage OUTPUT

				IF (@out_ErrorCode <> '0')
					BEGIN 
						GOTO WRITE_PROCESSLOG;
					END
				
				FETCH NEXT FROM OutboundLoad INTO @v_vchOutboundMasterID, @v_vchOutboundOrderNumber
			END

		CLOSE OutboundLoad;
		DEALLOCATE OutboundLoad;

		--COMMIT TRANSACTION;
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UNRELEASE_ORDER_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
		RETURN;
		-------------------------------------------------------------------------------------------------
		--WRITE PROCESS LOG
		WRITE_PROCESSLOG:
		-------------------------------------------------------------------------------------------------

		--IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
		--	ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','OutboundLoad') >= -1
			BEGIN
				CLOSE OutboundLoad;
				DEALLOCATE OutboundLoad;
			END
			
		SET @v_dtProcessDateTime = getdate(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = @v_vchOutboundOrderNumber,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
		-------------------------------------------------------------------------------------------------
	END TRY
	BEGIN CATCH		
		--IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
		--	ROLLBACK TRANSACTION;
		
		IF CURSOR_STATUS('global','OutboundLoad') >= -1
			BEGIN
				CLOSE OutboundLoad;
				DEALLOCATE OutboundLoad;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END 

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = @v_vchOutboundOrderNumber,
			@in_vchData3 = null,
			@in_vchData4 = null,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_unrelease_user_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_unrelease_user_by_group]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
	@in_vchDeviceID				NVARCHAR(50),
	@in_vchUserID				NVARCHAR(25),
	@in_vchLoadID				NVARCHAR(50),
	@out_ErrorCode				NVARCHAR(200) output,
	@out_ErrorMessage			NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_dtProcessDateTime		DATETIME
	DECLARE @v_vchBeginTrans			BIT = 0 
	DECLARE @c_vchObjName				NVARCHAR(30) = '[usp_outbound_unrelease_user_by_group]'
	DECLARE @v_vchWarehouse				NVARCHAR(25) 
			
	BEGIN TRY 
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		IF (ISNULL(@v_vchWarehouse,'') = '')
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'WAREHOUSE_NOT_FOUND',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@v_vchWarehouse,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END
					
		IF EXISTS(SELECT order_status FROM t_wms_outbound_master WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID AND order_status NOT IN ('RELEASE','OPEN'))
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_UNRELEASE_LOAD_ID',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROCESSLOG;
			END
			
		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1; 
		 
		UPDATE t_wms_outbound_master SET order_status = 'OPEN', pick_type = NULL WHERE wh_master_id = @in_vchWhMasterID AND load_id = @in_vchLoadID
		COMMIT TRANSACTION;
		
		SET @out_ErrorCode = '0';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'UNRELEASE_ORDER_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,'@param2','@param3','@param4','@param5')
		RETURN;

		-------------------------------------------------------------------------------------------------
		--WRITE PROCESS LOG
		WRITE_PROCESSLOG:
		-------------------------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION;
			
		SET @v_dtProcessDateTime = getdate(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage	
			
		RETURN;
		-------------------------------------------------------------------------------------------------
	END TRY
	BEGIN CATCH		
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1) 
			ROLLBACK TRANSACTION; 

		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END 

		SET @v_dtProcessDateTime = GETDATE(); 
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @v_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = NULL,
			@in_vchData3 = NULL,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_packing]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--Outbound Packing : can used pack function when put item to staging location
CREATE PROCEDURE [dbo].[usp_outbound_update_packing]
(
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER, 
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchPackNumber		NVARCHAR(25),
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLPN				NVARCHAR(25),
	@in_vchWhItemMasterID	UNIQUEIDENTIFIER,
	@in_vchLotNumber		NVARCHAR(50) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL, 
	@in_vchSerialNumber		NVARCHAR(100) = NULL,
	@in_fltQuantity			FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40), 
 	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;	
	DECLARE @c_vchObjName			NVARCHAR(50) = '[usp_outbound_update_packing]' -- The name that uniquely tags this object.
	DECLARE @v_vchProcessData		NVARCHAR(255)= NULL
	DECLARE @v_dtProcessDateTime	DATETIME = GETDATE()
	DECLARE @v_dtStartTime			DATETIME = GETDATE()
	DECLARE @v_vchApplicationName	NVARCHAR(50)= NULL
	DECLARE @v_vchLocalID			VARCHAR(10) = NULL
	DECLARE @v_vchBeginTrans		BIT = 0
	DECLARE @Round					INT = 0
	DECLARE @v_nCount				INT = 0

	--Outbound
	DECLARE @v_vchOutboundNumber	NVARCHAR(50)= NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerCode			NVARCHAR(50) = NULL
	DECLARE @v_vchOrderStatus		NVARCHAR(10) = NULL
	DECLARE @v_vchOrderType			NVARCHAR(30) = NULL
	
	--Item Master
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemNumber		NVARCHAR(50) = NULL 
	DECLARE @v_vchLocation			NVARCHAR(50) = NULL 
	 -- Item UOM
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER
	DECLARE @v_vchBaseUomPrompt		NVARCHAR(40)
	DECLARE @v_vchBaseUom			NVARCHAR(10)
	DECLARE @v_vchIsPrimaryUOM		VARCHAR(5)
	DECLARE @v_fltConversionFactor	FLOAT
	DECLARE @v_fltBaseInputQuantity	FLOAT

	--CheckQtyPack
	DECLARE @v_fltChkQtyStage		FLOAT = 0
	DECLARE @v_fltChkQtyPack		FLOAT = 0
 
BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @v_vchLocation = location FROM t_wms_location WHERE location_id = @in_vchLocationID AND is_active = 'YES'
	--------------------------------------------------
	-- Get Data in Outbound Master
	--------------------------------------------------
	SELECT TOP 1 @v_vchOutboundNumber = obMS.outbound_order_number
		,@v_vchOrderStatus = obMS.order_status
		,@v_vchOrderType = obMS.order_type
		,@v_vchOwnerID = obMS.owner_id 
		,@v_vchOwnerCode = own.owner_code 
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_owner own on obMS.owner_id = own.owner_id
	WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID
	AND obMS.wh_master_id = @in_vchWhMasterID
	IF(@v_vchOrderStatus = 'SHIP')
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchOutboundNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	--------------------------------------------------
	-- Check wh_item_master_id
	--------------------------------------------------
	SELECT TOP 1 @v_vchItemMasterID = item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND wh_item_master_id = @in_vchWhItemMasterID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			RETURN;
		END
		
	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT TOP 1 @v_vchItemNumber = item.item_number  
	FROM t_wms_item item
	WHERE item.owner_id = @v_vchOwnerID
	AND item.item_master_id = @v_vchItemMasterID
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	--Get & Check Item UOM
	--------------------------------------------------
	SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
		,@v_vchBaseUomPrompt = uom_prompt
		,@v_vchBaseUom = uom
		,@v_fltConversionFactor = conversion_factor
		,@v_vchIsPrimaryUOM = primary_uom 
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt		
	AND is_active = 'YES'	
	IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'UOM_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		End

	--------------------------------------------------
	--Get Primary Uom
	--------------------------------------------------
	IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchBaseUom = uom
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END
	
	--------------------------------------------------
	--Set Input Base Qty 
	--------------------------------------------------
	SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);

	--------------------------------------------------
	--Get Pick Detail
	--------------------------------------------------
	SELECT @v_nCount = COUNT(outbound_pick_detail_id)
		,@v_fltChkQtyStage	= SUM(ISNULL(quantity_stage,0))
	    ,@v_fltChkQtyPack	= SUM(ISNULL(quantity_pack,0))
	FROM v_wms_outbound_pack_for_check
	WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
	AND staging_location_id = @in_vchLocationID 
	AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
	AND wh_item_master_id = @in_vchWhItemMasterID
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
	AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
	AND is_override = 'NO'
	
	-----------------------------------------------------
	--Check Data Scan in pick detail and put to staging
	-----------------------------------------------------
	IF @v_nCount = 0
		BEGIN
			SET @out_ErrorCode = 'NOT_FOUND_DATA_IN_STG_LOCATION';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		END 
	
	-----------------------------------------------------
	--Check @v_fltBaseInputQuantity > (qty stg - qty pack) >> Error qty pack more than pick to stg
	-----------------------------------------------------
	IF @v_fltBaseInputQuantity > ROUND(ISNULL(@v_fltChkQtyStage,0) - ISNULL(@v_fltChkQtyPack,0),@Round) 
		BEGIN
			SET @out_ErrorCode = 'QTY_MORE_THAN_QTY_REMAIN_PACK';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		END
	
	DECLARE @v_vchPickDetailID	UNIQUEIDENTIFIER
	DECLARE @v_fltRemainQtyPack	FLOAT
	DECLARE @v_fltQtyCanPack	FLOAT
	DECLARE @v_dtReceiveDate	DATE
	DECLARE @v_dtMfgDate		DATE
	DECLARE @v_vchItemStatus	NVARCHAR(50)
	DECLARE @v_vchOBDTLineNumber NVARCHAR(10)
	--DECLARE @v_fltTotalQtyInput FLOAT = 0
	--SET @v_fltTotalQtyInput = @v_fltBaseInputQuantity

	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1

		DECLARE PickDetailCursor CURSOR FOR
			SELECT outbound_pick_detail_id
				,ROUND(ISNULL(quantity_stage,0) - ISNULL(quantity_pack,0),@Round)
				,receive_date
				,mfg_date
				,default_item_status
				,line_number
			FROM v_wms_outbound_pack_for_check
			WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
			AND staging_location_id = @in_vchLocationID 
			AND ISNULL(staging_lpn,'') = ISNULL(@in_vchLPN,'')
			AND wh_item_master_id = @in_vchWhItemMasterID
			AND ISNULL(lot_number,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(serial_number,'') = ISNULL(@in_vchSerialNumber,'')
			AND is_override = 'NO'
			AND ROUND(ISNULL(quantity_stage,0) - ISNULL(quantity_pack,0),@Round) > 0
			ORDER BY pick_line_number
		OPEN PickDetailCursor
		FETCH NEXT FROM PickDetailCursor INTO @v_vchPickDetailID, @v_fltRemainQtyPack, @v_dtReceiveDate, @v_dtMfgDate,@v_vchItemStatus,@v_vchOBDTLineNumber
		WHILE @@FETCH_STATUS = 0
			BEGIN
				IF @v_fltBaseInputQuantity > @v_fltRemainQtyPack
					SET @v_fltQtyCanPack = @v_fltRemainQtyPack
				ELSE
					SET @v_fltQtyCanPack = @v_fltBaseInputQuantity

				--Update Qty pack in pick detail
				UPDATE t_wms_outbound_pick_detail SET 
						quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltQtyCanPack,@round)
					,pack_status = 'PACK'
				WHERE outbound_pick_detail_id = @v_vchPickDetailID

				--Insert pact detail
				INSERT INTO [dbo].[t_wms_outbound_pack_detail]
						([outbound_pack_detail_id]
						,[outbound_order_master_id]
						,[outbound_pick_detail_id]
						,[parent_lpn_pack]
						,[lpn_pack]
						,[pack_location_id]
						,[wh_item_master_id]
						,[quantity_pack]
						,[item_uom_id]
						,[lot_number]
						,[expiry_date]
						,[serial_number]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[receive_date]
						,[mfg_date] 
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()	
						,@in_vchOutboundMasterID
						,@v_vchPickDetailID
						,NULL
						,@in_vchPackNumber
						,@in_vchLocationID
						,@in_vchWhItemMasterID
						,@v_fltQtyCanPack
						,@v_vchBaseItemUomID
						,@in_vchLotNumber
						,@in_vchExpiryDate
						,@in_vchSerialNumber
						,@in_vchAttribute1
						,@in_vchAttribute2
						,@in_vchAttribute3
						,@in_vchAttribute4
						,@in_vchAttribute5
						,@v_dtReceiveDate
						,@v_dtMfgDate 
						,GETDATE()
						,@in_vchUserID)

				--Write log : OO_PACK, PACKING
				INSERT INTO [dbo].[t_com_tran_log]
						([tran_id]
						,[app_id]
						,[app_name]
						,[tran_type]
						,[sub_tran_type]
						,[description]
						,[start_tran_datetime]
						,[end_tran_datetime]
						,[warehouse]
						,[to_warehouse]
						,[location]
						,[to_location]
						,[owner]
						,[to_owner]
						,[item_number]
						,[quantity]
						,[quantity_uom]
						,[after_quantity]
						,[after_quantity_uom]
						,[lot_number]
						,[after_lot_number]
						,[expiry_date]
						,[after_expiry_date]
						,[serial_number]
						,[attribute1]
						,[after_attribute1]
						,[attribute2]
						,[after_attribute2]
						,[attribute3]
						,[after_attribute3]
						,[attribute4]
						,[after_attribute4]
						,[attribute5]
						,[after_attribute5]
						,[user_id]
						,[reference_number]
						,[lpn]
						,[after_lpn] 
						,[status]
						,[after_status]
						,[order_number]
						,[line_number]
						,[control_value_1]
						,[receive_date]
						,[mfg_date]
						,[device]
						,[create_date]
						,[create_by]
						,[input_quantity]
						,[input_uom])
					VALUES
						(NEWID()
						,@in_vchApplicationID
						,@v_vchApplicationName
						,'OO_PACK'
						,'PACKING'
						,'Outbound Packing'
						,@v_dtStartTime
						,GETDATE()
						,@in_vchWarehouse
						,@in_vchWarehouse
						,@v_vchLocation
						,@v_vchLocation
						,@v_vchOwnerCode
						,@v_vchOwnerCode
						,@v_vchItemNumber
						,@v_fltQtyCanPack
						,@v_vchBaseUomPrompt
						,0
						,@v_vchBaseUomPrompt
						,@in_vchLotNumber
						,@in_vchLotNumber
						,@in_vchExpiryDate
						,@in_vchExpiryDate
						,@in_vchSerialNumber
						,@in_vchAttribute1
						,@in_vchAttribute1
						,@in_vchAttribute2
						,@in_vchAttribute2
						,@in_vchAttribute3
						,@in_vchAttribute3
						,@in_vchAttribute4
						,@in_vchAttribute4
						,@in_vchAttribute5
						,@in_vchAttribute5
						,@in_vchUserID
						,@in_vchPackNumber 
						,@in_vchLPN
						,@in_vchLPN
						,@v_vchItemStatus
						,@v_vchItemStatus 
						,@v_vchOutboundNumber
						,@v_vchOBDTLineNumber
						,@v_vchPickDetailID		--[control_value_1]
						,@v_dtReceiveDate
						,@v_dtMfgDate 
						,@in_vchDeviceID
						,GETDATE()
						,@in_vchUserID
						,@in_fltQuantity
						,@in_vchUOMPrompt)

				SET @v_fltBaseInputQuantity = ROUND(@v_fltBaseInputQuantity - @v_fltQtyCanPack,@ROUND)
				IF @v_fltBaseInputQuantity = 0
					BREAK;
			
				FETCH NEXT FROM PickDetailCursor INTO @v_vchPickDetailID, @v_fltRemainQtyPack, @v_dtReceiveDate, @v_dtMfgDate,@v_vchItemStatus,@v_vchOBDTLineNumber
			END
		CLOSE PickDetailCursor
		DEALLOCATE PickDetailCursor

	--CHECK ว่า PACK ครบแล้วหรือไม่ ถ้าครบแล้วเป็น Packed
	IF EXISTS (SELECT outbound_pick_detail_id FROM v_wms_outbound_pack_for_check
				WHERE outbound_pick_master_id = @in_vchOutboundPickMasterID
				AND is_override = 'NO'
				AND ISNULL(quantity_stage,0) - ISNULL(quantity_pack,0) > 0)
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PACK',update_by = @in_vchUserID, update_date = GETDATE() WHERE outbound_order_master_id = @in_vchOutboundMasterID
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PACKED',update_by = @in_vchUserID, update_date = GETDATE() WHERE outbound_order_master_id = @in_vchOutboundMasterID
		END

	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','PickDetailCursor')>=-1
			BEGIN
				CLOSE PickDetailCursor;
				DEALLOCATE PickDetailCursor;
			END
  
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData = 'Qty: ' + convert(varchar,@in_fltQuantity) + ' ' + @in_vchUOMPrompt;
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundNumber,
			@in_vchData2 = @in_vchPackNumber,
			@in_vchData3 = @v_vchItemNumber,
			@in_vchData4 = @v_vchProcessData,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
	
	IF CURSOR_STATUS('global','PickDetailCursor')>=-1
		BEGIN
			CLOSE PickDetailCursor;
			DEALLOCATE PickDetailCursor;
		END 

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + convert(varchar,@in_fltQuantity) + ' ' + @in_vchUOMPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundNumber,
		@in_vchData2 = @in_vchPackNumber,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

		SET @out_ErrorCode = 'CONTACT_ADMIN';
		SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pick_item]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchPicklistNumber	NVARCHAR(40),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchForkLift			NVARCHAR(50),
	@in_vchItemNumber		NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchFromParentLPN	NVARCHAR(25) = NULL,
	@in_vchFromLPN			NVARCHAR(25) = NULL,
	@in_vchToParentLPN		NVARCHAR(25) = NULL,
	@in_vchToLPN			NVARCHAR(25) = NULL,
	@in_vchLot				NVARCHAR(100) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchSerialNo			NVARCHAR(100) = NULL,
	@in_vchOverPickReason	NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchTrackingNo		NVARCHAR(50)  = NULL,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_update_pick_item]', -- The name that uniquely tags this object.
			@v_vchProcessData			NVARCHAR(255)= NULL,
			@v_dtProcessDateTime		DATETIME = NULL, 
			@v_dtStartTime				DATETIME = NULL, 
			@v_vchApplicationName		NVARCHAR(50)= NULL,
			@v_vchLocalID				VARCHAR(10) = NULL,
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,
			@v_nOutboundCursorRow		INT = 0,
			@RulePickPack				NVARCHAR(3) = 'NO',
			@RuleAutoStaging			NVARCHAR(3) = 'NO',
			@RuleOverPick				NVARCHAR(3) = 'NO',

			@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchForkID				UNIQUEIDENTIFIER = NULL,

			--Outbound
			@v_vchOutboundMasterID		UNIQUEIDENTIFIER  = NULL,
			@v_vchOrderStatus			NVARCHAR(30) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50) = NULL,

			----Inventory 
			@v_vchInventoryID			UNIQUEIDENTIFIER  = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER  = NULL,
			@v_fltChkInvQty				FLOAT,

			--Item Master
			@v_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
			@v_vchLotControl			VARCHAR(5) = NULL,
			@v_vchExpControl			VARCHAR(5) = NULL,
			@v_vchSNControl				VARCHAR(5) = NULL,
			@v_vchAttribute1Control		VARCHAR(5) = NULL,
			@v_vchAttribute2Control		VARCHAR(5) = NULL,
			@v_vchAttribute3Control		VARCHAR(5) = NULL,
			@v_vchAttribute4Control		VARCHAR(5) = NULL,
			@v_vchAttribute5Control		VARCHAR(5) = NULL,
			@v_vchItemIsActive			VARCHAR(3) = NULL,


			-- Item UOM
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20),
			@v_vchIsPrimaryUOM			VARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,
			@v_fltWidth					FLOAT = 0,  --item Uom
			@v_fltLength				FLOAT = 0,  --item Uom
			@v_fltHeight				FLOAT = 0,  --item Uom
			@v_fltGrossWeight			FLOAT = 0,  --item Uom
			@v_intPercentTolerance		FLOAT = 0,  --item Uom
			@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
			@v_fltVolumn				FLOAT = 0,	--item Uom
			@v_fltTotalWeight			FLOAT = 0,	--item Uom
			
			@v_fltSumRemainPick			FLOAT, --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Order ใน item ที่ scan
			@v_vchPickToLPN				NVARCHAR(25) = NULL,

			--Outbound Loop
			@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,			
			@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL, -- Outbound Detail
			@v_vchPickLineNumber		NVARCHAR(10) = NULL, -- Outbound Pick Detail
			@v_fltQuantityPlan			FLOAT,
			@v_fltQuantityPick			FLOAT,
			@v_dtReceiveDate			DATE,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL,
			
			--จำนวนที่ใช้ในการจ่ายจริง หลังแปลงเป็นหน่วยที่เล็กที่สุด [primary_uom = 'YES']
			@v_fltSumQtyCanPick			FLOAT,
			@v_fltDiffQtyOverPick		FLOAT,	--สำหรับ เก็บส่วนต่างที่หยิบเกิน
			@v_fltAllocateQtyOverPick	FLOAT,	--สำหรับ เก็บส่วนต่างที่หยิบเกิน

			-- Auto STG
			@v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchStagingLocation		NVARCHAR(50),
			@v_fltQuantityStage			FLOAT,
			@v_vchStagingParentLPN		NVARCHAR(25) = NULL,
			@v_vchStagingLPN			NVARCHAR(25) = NULL,

			@v_vchOutboundNewPickDetailID UNIQUEIDENTIFIER = NULL, --สำหรับกรณีที่ช่วยกันหยิบ
			@v_vchNewPickLineNumber		NVARCHAR(40) = NULL,
			@v_vchPickBy				NVARCHAR(25),
			@v_vchPickLocation			NVARCHAR(50) -- Location ที่ Pick ของมา

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @RuleOverPick = value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_PICK' AND is_active = 'YES'
	SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT TOP 1 @RuleAutoStaging = value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
	SELECT TOP 1 @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchFromLocation AND is_active = 'YES'
	SELECT TOP 1 @v_vchForkID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchForkLift AND is_active = 'YES'
	SET @in_fltQty = ROUND(@in_fltQty,@Round)

	-------------------------------------------------
	-- SET Box Number
	-------------------------------------------------
	IF ISNULL(@in_vchToLPN,'') = ''
		BEGIN
			SET @in_vchToLPN = @in_vchPicklistNumber
		END

	--------------------------------------------------
	-- Get Data in Outbound Master
	--------------------------------------------------
	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id
		,@v_vchOrderStatus = obMS.order_status
		,@v_vchOrderType = obMS.order_type
		,@v_vchOwnerID = obMS.owner_id 
		,@v_vchOwnerCode = own.owner_code
		,@v_vchPickBy = obMS.pick_by
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_owner own on obMS.owner_id = own.owner_id
	WHERE obMS.outbound_order_number = @in_vchPicklistNumber
	AND obMS.wh_master_id = @v_vchWhMasterID
	IF @v_vchOutboundMasterID IS NULL
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchPicklistNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	IF(@v_vchOrderStatus = 'SHIP')
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchPicklistNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	IF @RuleOverPick = 'YES' AND @v_vchOrderType NOT IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_OVER_PICK' AND is_active = 'YES')
		BEGIN
			SET @RuleOverPick = 'NO'
		END

	------------------------------------------------------
	-- ตรวจสอบ Multiple user pick
	------------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO') AND (@v_vchPickBy <> @in_vchUserID))
		BEGIN
			--Multi User
			SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END

	--------------------------------------------------------
	-- Validate Staging Location
	--------------------------------------------------------
	IF (@RuleAutoStaging = 'YES')
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE outbound_order_master_id = @v_vchOutboundMasterID
			AND pickDT.staging_location_id IS NOT NULL
			AND pickDT.is_override = 'NO'
				
			IF @v_vchStagingLocationID IS NULL
			BEGIN
				SELECT TOP 1 @v_vchStagingLocationID = location_id
					,@v_vchStagingLocation = location 
				FROM t_wms_location 
				WHERE wh_master_id = @v_vchWhMasterID 
				AND loc_type = 'STG' AND is_active = 'YES'
				IF (@v_vchStagingLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END 
		END

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchLotControl = item.lot_control
		, @v_vchExpControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @v_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @v_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchWarehouse,@in_vchItemNumber,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	--Get & Check Item UOM
	--------------------------------------------------
	SELECT @v_vchBaseItemUomID = item_uom_id
		,@v_vchBaseUomPrompt = uom_prompt
		,@v_vchBaseUom = uom
		,@v_fltConversionFactor = conversion_factor
		,@v_vchIsPrimaryUOM = primary_uom
		,@v_fltWidth = ISNULL(width,0)
		,@v_fltLength = ISNULL(length,0)
		,@v_fltHeight = ISNULL(height,0)
		,@v_fltGrossWeight = ISNULL(gross_weight,0)
		,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
		,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt		
	AND is_active = 'YES'	
	IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'UOM_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		End

	--------------------------------------------------
	--Get Primary Uom
	--------------------------------------------------
	IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchBaseUom = uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END
	
	--------------------------------------------------
	--Set Input Base Qty 
	--------------------------------------------------
	SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);

	--------------------------------------------------
	--Get Inventory to Temp table
	--------------------------------------------------
	SELECT inventory_id
		,attribute_group_id
		,inventory_status_id
		,quantity
		,quantity_allocated
		,mfg_date
		,receive_date
		,serial_number
	INTO #tInventory
	FROM v_wms_inventory_data_serial_by_id
	WHERE wh_master_id = @v_vchWhMasterID
	AND location_id = @v_vchLocationID
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
	AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
	AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND (CASE @in_vchSerialNo WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE @in_vchSerialNo WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNo,'') END)

	--------------------------------------------------
	--Check Inventory
	--------------------------------------------------
	 IF NOT EXISTS (SELECT inventory_id FROM #tInventory)
		BEGIN
			-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
			SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	--Check Serial ต้องไม่ได้จองที่ order อื่น
	--------------------------------------------------
	IF EXISTS (SELECT pickDT.outbound_pick_detail_id
				FROM t_wms_outbound_pick_master pickMS 
				INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				WHERE pickMS.outbound_order_master_id <> @v_vchOutboundMasterID
				AND pickDT.is_override = 'NO'
				AND pickDT.location_id = @v_vchLocationID
				AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
				AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchFromLPN,'')
				AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLot,'')
				AND ISNULL(pickDT.expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND ISNULL(pickDT.serial_number,'') = ISNULL(@in_vchSerialNo,'')
				AND ISNULL(pickDT.quantity_pick,0) = 0) AND @v_vchSNControl = 'FULL'
		BEGIN
			-- Serial นี้ถูกจองโดย Outbound Order อื่นแล้ว
			SET @out_ErrorCode = 'INFO_SERIAL_IS_ALLOCATE_BY_ANOTHER_ORDER'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchSerialNo,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Check จำนวนใน Inventory กับจำนวนที่จะจ่าย
	-- จำนวนที่จะ Pick > จำนวนใน Inventory
	--------------------------------------------------
	SELECT @v_fltChkInvQty = SUM(quantity) FROM #tInventory
	IF (@in_vchSerialNo = 'ALL')
		BEGIN
			SET @v_fltBaseInputQuantity = ROUND(@v_fltChkInvQty,@Round)
		END
	
	--------------------------------------------------
	--Get Pick Detail to Temp
	--------------------------------------------------
	SELECT pickMS.outbound_order_master_id
		, obMS.outbound_order_number
		, pickMS.outbound_pick_master_id
		, pickDT.outbound_pick_detail_id
		, pickDT.outbound_order_detail_id
		, obDT.line_number
		, pickDT.pick_line_number
		, ISNULL(pickDT.quantity_plan,0) AS quantity_plan
		, ISNULL(pickDT.quantity_pick,0) AS quantity_pick
		, pickDT.receive_date
		, invST.inventory_status_id
		, obDT.default_item_status		
		, pickDT.location_id
		, loc.location
		, pickDT.serial_number
	INTO #tPickAllDetail
	FROM t_wms_outbound_pick_master pickMS
	INNER JOIN t_wms_outbound_master obMS ON pickMS.outbound_order_master_id = obMS.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
	INNER JOIN t_wms_outbound_detail obDT on pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
	INNER JOIN t_wms_location loc ON loc.location_id = pickDT.location_id
	INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
	WHERE pickMS.outbound_order_master_id = @v_vchOutboundMasterID
	AND pickDT.is_override = 'NO'
	AND pickDT.location_id = @v_vchLocationID
	AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
	AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
	AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchFromLPN,'')
	AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLot,'')
	AND ISNULL(pickDT.expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
	
	DECLARE @tPickDetail AS TABLE
	(
		outbound_order_master_id	UNIQUEIDENTIFIER,
		outbound_order_number		NVARCHAR(50),
		outbound_pick_master_id		UNIQUEIDENTIFIER,
		outbound_pick_detail_id		UNIQUEIDENTIFIER,
		outbound_order_detail_id	UNIQUEIDENTIFIER,
		line_number					NVARCHAR(10),
		pick_line_number			NVARCHAR(5),
		quantity_plan				FLOAT,
		quantity_pick				FLOAT,
		receive_date				DATE, 
		inventory_status_id			UNIQUEIDENTIFIER,
		default_item_status			NVARCHAR(50),
		location_id					UNIQUEIDENTIFIER,
		location					NVARCHAR(50)
	)

	--Check Picklist ถ้า Control Serial และระบุ Serial ต้อง update pick ของ record นั้น
	IF (@v_vchSNControl = 'FULL')
		BEGIN
			--Case Serial
			IF EXISTS (SELECT outbound_pick_detail_id FROM #tPickAllDetail WHERE ISNULL(serial_number,'') = ISNULL(@in_vchSerialNo,''))
				BEGIN
					--ถ้า Serial ที่ pick ตรงกับ Picklist ที่มีการระบุไว้ที่ plan
					DELETE @tPickDetail
					INSERT INTO @tPickDetail
					(
						outbound_order_master_id	
					   ,outbound_order_number		
					   ,outbound_pick_master_id		
					   ,outbound_pick_detail_id		
					   ,outbound_order_detail_id	
					   ,line_number					
					   ,pick_line_number			
					   ,quantity_plan				
					   ,quantity_pick				
					   ,receive_date				
					   ,inventory_status_id			
					   ,default_item_status			
					   ,location_id					
					   ,location					
					)
					SELECT outbound_order_master_id
						, outbound_order_number
						, outbound_pick_master_id
						, outbound_pick_detail_id
						, outbound_order_detail_id
						, line_number
						, pick_line_number
						, ISNULL(quantity_plan,0) AS quantity_plan
						, ISNULL(quantity_pick,0) AS quantity_pick
						, receive_date
						, inventory_status_id
						, default_item_status		
						, location_id
						, location
					FROM #tPickAllDetail
					WHERE ISNULL(serial_number,'') = ISNULL(@in_vchSerialNo,'')
					AND ISNULL(quantity_pick,0) = 0
				END
			ELSE
				BEGIN
					--สำหรับ plan ที่ไม่ได้ระบุ serial
					DELETE @tPickDetail
					INSERT INTO @tPickDetail
					(
						outbound_order_master_id	
					   ,outbound_order_number		
					   ,outbound_pick_master_id		
					   ,outbound_pick_detail_id		
					   ,outbound_order_detail_id	
					   ,line_number					
					   ,pick_line_number			
					   ,quantity_plan				
					   ,quantity_pick				
					   ,receive_date				
					   ,inventory_status_id			
					   ,default_item_status			
					   ,location_id					
					   ,location					
					)
					SELECT outbound_order_master_id
						, outbound_order_number
						, outbound_pick_master_id
						, outbound_pick_detail_id
						, outbound_order_detail_id
						, line_number
						, pick_line_number
						, ISNULL(quantity_plan,0) AS quantity_plan
						, ISNULL(quantity_pick,0) AS quantity_pick
						, receive_date
						, inventory_status_id
						, default_item_status		
						, location_id
						, location
					FROM #tPickAllDetail
					WHERE ISNULL(serial_number,'') = ''
					AND ISNULL(quantity_pick,0) = 0
				END

			--------------------------------------------------
			-- ถ้าไม่พบ Recode ใน PickList แสดงว่าข้อมูลผิด
			--------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM @tPickDetail)
				BEGIN
					-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
					SET @out_ErrorCode = 'INFO_NOT_FOUND_DATA_SN_IN_PICK_LIST'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo,'@param5')			
					RETURN;
				END
		END
	ELSE 
		BEGIN
			--Case ปกติ
			DELETE @tPickDetail
			INSERT INTO @tPickDetail
			(
				outbound_order_master_id	
			   ,outbound_order_number		
			   ,outbound_pick_master_id		
			   ,outbound_pick_detail_id		
			   ,outbound_order_detail_id	
			   ,line_number					
			   ,pick_line_number			
			   ,quantity_plan				
			   ,quantity_pick				
			   ,receive_date				
			   ,inventory_status_id			
			   ,default_item_status			
			   ,location_id					
			   ,location					
			)
			SELECT outbound_order_master_id
				, outbound_order_number
				, outbound_pick_master_id
				, outbound_pick_detail_id
				, outbound_order_detail_id
				, line_number
				, pick_line_number
				, ISNULL(quantity_plan,0) AS quantity_plan
				, ISNULL(quantity_pick,0) AS quantity_pick
				, receive_date
				, inventory_status_id
				, default_item_status
				, location_id
				, location
			FROM #tPickAllDetail
			--------------------------------------------------
			-- ถ้าไม่พบ Recode ใน PickList แสดงว่าข้อมูลผิด
			--------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM @tPickDetail)
				BEGIN
					-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
					SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
					RETURN;
				END
		END 
 	
	--------------------------------------------------
	-- Check Remain pick
	-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศุนย์ >> ERROR
	--------------------------------------------------
	SELECT @v_fltSumRemainPick = SUM(quantity_plan - quantity_pick) FROM @tPickDetail pickMS
	IF ROUND(@v_fltSumRemainPick,@Round) <= 0
		BEGIN
			-- รายการสินค้า [] หยิบครบแล้ว
			SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END
	
	--------------------------------------------------
	-- ถ้าจำนวนใน Inventory มีไม่พอ
	--------------------------------------------------
	IF ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltChkInvQty,@Round)
		BEGIN
			-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
			SET @out_ErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- ถ้าจำนวนที่หยิบ มากกว่า จำนวนคงเหลือที่สามารถหยิบได้ >> ERROR
	-- ถ้า Rule Over Pick = NO ต้อง Check Qty ที่หยิบ
	-- ถ้า Rule Over Pick = YES ไม่ต้อง Check Qty
	--------------------------------------------------
	IF ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltSumRemainPick,@Round) AND @RuleOverPick = 'NO'
		BEGIN
			-- รายการสินค้า [] ไม่สามารถหยิบเกินได้
			SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			RETURN;
		END

	-- ถ้ากำหนด over pick ให้หายอด diff ของส่วนที่หยิบเกิน เพื่อไว้ pick ให้กับ row สุดท้ายของ pick detail และยอดที่หยิบ มากกว่า ยอดคงเหลือ ถึงจะถือว่ามันหยิบเกินจริงๆ
	IF @RuleOverPick = 'YES' AND ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltSumRemainPick,@Round)
		BEGIN
			SET @v_fltDiffQtyOverPick = ROUND(@v_fltBaseInputQuantity,@Round) - ROUND(@v_fltSumRemainPick,@Round)
		END
	 
	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้ทั้งหมด เทียบกับ inventory
	-- หายอดเทียบระหว่างคงเหลือ กับ ยอด inventoy ว่าจะเป็นตัวไหน เพื่อไปเทียบกับ input qty อีกที
	-------------------------------------------------
	IF (ROUND(@v_fltSumRemainPick,@Round) > ROUND(@v_fltChkInvQty,@Round))
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltChkInvQty,@Round)
		END
	ELSE
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltSumRemainPick,@Round)
		END
	
	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้จริง กับจำนวนที่หยิบจริง
	-------------------------------------------------
	IF ROUND(@v_fltSumQtyCanPick,@Round) > ROUND(@v_fltBaseInputQuantity,@Round)
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
		END

	------------------------------------------------------------
	-- SET pick_to_lpn
	-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
	------------------------------------------------------------
	SET @v_fltChkInvQty = 0
	SELECT @v_fltChkInvQty = SUM(quantity) FROM t_wms_inventory where wh_master_id = @v_vchWhMasterID AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
	IF (@v_fltBaseInputQuantity = @v_fltChkInvQty AND ISNULL(@in_vchFromLPN,'') <> '')
		BEGIN
			SET @v_vchPickToLPN = @in_vchFromLPN
		END
	ELSE
		BEGIN
			SET @v_vchPickToLPN = @in_vchToLPN
		END

BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
	SET @v_nOutboundCursorRow = 1;
	SET @v_fltAllocateQtyOverPick = 0
	DECLARE @v_nLoopCheck INT = 0

	DECLARE @v_fltQtyCanPick		FLOAT
	DECLARE @v_fltRemainQtyCanPick	FLOAT
	DECLARE @v_fltQtyPick			FLOAT
	---------------------------------------------------------------
	--Get Inventory รายการของสินค้าจากที่หยิบมา					
	---------------------------------------------------------------
	DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvSerialNumber	NVARCHAR(100)= NULL
	DECLARE @v_fltInvQuantity		FLOAT
	DECLARE @v_dtInvMfgDate			DATE
	DECLARE @v_dtInvReceiveDate		DATE

	DECLARE OutboundDetailCursor CURSOR STATIC FOR
		SELECT outbound_pick_master_id
			, outbound_pick_detail_id
			, outbound_order_detail_id
			, line_number
			, pick_line_number
			, quantity_plan
			, quantity_pick
			, receive_date
			, inventory_status_id
			, default_item_status
			, location
		FROM @tPickDetail
		WHERE ROUND(quantity_pick,@Round) < ROUND(quantity_plan,@Round)
		ORDER BY outbound_order_number,receive_date,line_number,pick_line_number
	OPEN OutboundDetailCursor
	FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_vchOutboundDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_dtReceiveDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchPickLocation
	SET @v_nLoopCheck = @@CURSOR_ROWS 
	WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @v_fltQtyCanPick		= 0
			SET @v_fltRemainQtyCanPick	= 0
			SET	@v_fltQtyPick			= 0
			SET @v_vchInvID				= NULL
			SET	@v_vchInvAttrGroupID	= NULL
			SET	@v_vchInvSerialNumber	= NULL
			SET	@v_fltInvQuantity		= 0
			SET	@v_dtInvMfgDate			= NULL
			SET @v_dtInvReceiveDate		= NULL

 			SET @v_dtStartTime = GETDATE();
			
			---------------------------------------------------------------
			-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ				
			---------------------------------------------------------------
			IF @v_nOutboundCursorRow = @v_nLoopCheck
				BEGIN
					Print 'over pick'
					--กรณี Over pick check last record ของ outbound ให้ + ยอดที่ pick เกินจาก plan
					SET @v_fltSumQtyCanPick = ROUND(@v_fltSumQtyCanPick + ISNULL(@v_fltDiffQtyOverPick,0),@Round)
					SET @v_fltQtyCanPick = ROUND(@v_fltSumQtyCanPick,@Round)
					SET @v_fltAllocateQtyOverPick = ROUND(ISNULL(@v_fltDiffQtyOverPick,0),@Round)
					--select 'over pick last row',@v_fltSumQtyCanPick as SumQtyCanPick,@v_fltQtyCanPick as QtyCanPick,@v_fltAllocateQtyOverPick as AllocateQtyOverPick
				END
			ELSE
				BEGIN
					--กรณี case ปกติ หยิบตาม plan
					IF (ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round) > ROUND(@v_fltSumQtyCanPick,@Round))
						SET @v_fltQtyCanPick = ROUND(@v_fltSumQtyCanPick,@Round)
					ELSE
						SET @v_fltQtyCanPick = ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round)
					--select 'Not over pick',@v_fltSumQtyCanPick as SumQtyCanPick,@v_fltQtyCanPick as QtyCanPick,@v_fltAllocateQtyOverPick as AllocateQtyOverPick
				END
				
			---------------------------------------------------------------
			-- สำหรับใช้กรณีของ Serial เนื่องจากต้องมีการ วน serial case all 
			-- โดยที่ @v_fltQtyCanPick ยังต้องคงค่าไว้ เพื่อจะได้รู้ว่า เหลือจำนวนเท่าไหร่ที่ต้องวน
			---------------------------------------------------------------
			SET @v_fltRemainQtyCanPick = ROUND(@v_fltQtyCanPick,@Round)
			--SET @v_fltQtyPick = ROUND(@v_fltQtyCanPick,@Round)

			DECLARE InventoryCursor CURSOR STATIC FOR
				SELECT inventory_id
					,attribute_group_id
					,serial_number
					,mfg_date
					,receive_date
				FROM #tInventory
				WHERE inventory_status_id = @v_vchInvStatusID
				AND (CASE WHEN @RuleOverPick = 'NO' THEN CONVERT(VARCHAR(8),receive_date,112) ELSE '' END) = (CASE WHEN @RuleOverPick = 'NO' THEN CONVERT(VARCHAR(8),@v_dtReceiveDate,112) ELSE '' END)
				ORDER BY receive_date, serial_number
			OPEN InventoryCursor
			FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_dtInvMfgDate,@v_dtInvReceiveDate
			IF(@@CURSOR_ROWS > 0)
				BEGIN
					WHILE @@FETCH_STATUS = 0
						BEGIN
							SET @v_fltInvQuantity = 0
							SELECT @v_fltInvQuantity = quantity FROM t_wms_inventory WHERE inventory_id = @v_vchInvID and attribute_group_id = @v_vchInvAttrGroupID
							
							IF ROUND(@v_fltRemainQtyCanPick,@Round) >= ROUND(@v_fltInvQuantity,@Round)
								SET @v_fltQtyPick = ROUND(@v_fltInvQuantity,@Round)
							ELSE 
								SET @v_fltQtyPick = ROUND(@v_fltRemainQtyCanPick,@Round)

							-----------------------------------------------------
							-- Validate Duplicate Serial Number ใน Pick Detail
							-----------------------------------------------------
							IF (@v_vchSNControl = 'FULL')
								BEGIN
									SET @v_fltInvQuantity = 1
									SET @v_fltQtyPick = 1   -- กรณีของ Serial Qty Pick = 1
									IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
												WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
												AND wh_item_master_id = @v_vchWhItemMasterID 
												AND serial_number = @v_vchInvSerialNumber
												AND ISNULL(quantity_pick,0) > 0
												AND is_override = 'NO')
										BEGIN
											SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
											SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchInvSerialNumber,@in_vchItemNumber,'@param3','@param4','@param5')
											GOTO WRITE_PROC;
										END
								END

							-------------------------------------------------------------------
							-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP กำหนดจาก Rule
							-------------------------------------------------------------------
							IF (@v_nOutboundCursorRow = @v_nLoopCheck AND @v_dtReceiveDate <> @v_dtInvReceiveDate)
								BEGIN --กรณีที่เป็น Pick Detail Record สุดท้ายและมีการ Over Pick ข้าม Receipt Date กัน จะต้อง Insert Pick Detail Line ใหม่
									IF @RuleAutoStaging = 'YES'
										BEGIN
											----------------------------------------
											--SET Value Staging
											----------------------------------------
											SET @v_fltQuantityStage = ROUND(@v_fltQtyPick,@Round)
											SET @v_vchStagingParentLPN = @in_vchToParentLPN
											SET @v_vchStagingLPN = @v_vchPickToLPN

											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(ISNULL(quantity_pick,0) + @v_fltQuantityStage,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber
									
											--Insert Pick Detail Record ใหม่ เนื่องจากเป็นการ OverPick
											GOTO NEW_PICK_DETAIL_AUTO_STG;
										END
									ELSE
										BEGIN
											SET @v_vchStagingLocationID = NULL
											SET @v_vchStagingLocation = NULL
											SET @v_fltQuantityStage = 0	
											SET @v_vchStagingParentLPN = NULL	
											SET @v_vchStagingLPN = NULL
											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											--Insert Pick Detail Record ใหม่ เนื่องจากเป็นการ OverPick
											GOTO NEW_PICK_DETAIL;
										END
								END
							ELSE
								BEGIN --Normal case
									IF (@RuleAutoStaging = 'YES')
										BEGIN
											----------------------------------------
											--SET Value Staging
											----------------------------------------
											SET @v_fltQuantityStage = ROUND(@v_fltQtyPick,@Round)
											SET @v_vchStagingParentLPN = @in_vchToParentLPN
											SET @v_vchStagingLPN = @v_vchPickToLPN

											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(ISNULL(quantity_pick,0) + @v_fltQuantityStage,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											----------------------------------------------------------------
											-- แบบวาง STG Auto
											-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP
											----------------------------------------------------------------
											IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
														WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND is_override = 'NO'
														AND receive_date = @v_dtInvReceiveDate
														AND (CASE WHEN quantity_pick > 0 THEN ISNULL(pick_to_lpn,'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN @v_vchPickToLPN ELSE '' END)
														AND (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),pick_location_id),'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),@v_vchForkID),'') ELSE '' END)) OR @v_vchSNControl = 'FULL'
												BEGIN
													--กรณีที่ใช้ fork เดิม Update ค่าได้เลย
													UPDATE t_wms_outbound_pick_detail SET 
														  quantity_pick		 = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
														, quantity_stage	 = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round) 
														, pick_location_id   = @v_vchForkID
														, pick_to_parent_lpn = @in_vchToParentLPN
														, pick_to_lpn		 = @v_vchPickToLPN
														, staging_location_id = @v_vchStagingLocationID
														, staging_parent_lpn = @v_vchStagingParentLPN
														, staging_lpn		 = @v_vchStagingLPN 
														, pick_status        = 'YES'
														, start_date_time	 = ISNULL(start_date_time,GETDATE())
														, end_date_time		 = GETDATE()
														, serial_number		 = @v_vchInvSerialNumber
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
												END
											ELSE
												BEGIN
													--Insert New Pick Detail
													--1. ลบยอดจำนวนจากรายการเดิม
													UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyPick,@Round)
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

													NEW_PICK_DETAIL_AUTO_STG:
													--Check ว่ามี recode เดิมหรือไม่ ถ้ามีให้ทำการ update
													SET @v_vchOutboundNewPickDetailID = NULL
													SELECT @v_vchOutboundNewPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
													WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
													AND outbound_order_detail_id = @v_vchOutboundDetailID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND location_id = @v_vchLocationID
													AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
													AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
													AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
													AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
													AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
													AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
													AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
													AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
													AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
													AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
													AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
													AND pick_location_id = @v_vchForkID
													AND receive_date = @v_dtInvReceiveDate
													AND is_override = 'NO'
													IF (@v_vchOutboundNewPickDetailID IS NOT NULL)
														BEGIN
															UPDATE t_wms_outbound_pick_detail SET 
																  quantity_plan		  = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyPick,@Round)
																, quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
																, quantity_stage	  = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
																, pick_location_id    = @v_vchForkID
																, pick_to_parent_lpn  = @in_vchToParentLPN
																, pick_to_lpn		  = @v_vchPickToLPN
																, staging_location_id = @v_vchStagingLocationID
																, staging_parent_lpn  = @v_vchStagingParentLPN
																, staging_lpn		  = @v_vchStagingLPN 
																, pick_status         = 'YES'
																, start_date_time	  = ISNULL(start_date_time,GETDATE())
																, end_date_time		  = GETDATE()
																, serial_number		  = @v_vchInvSerialNumber
															WHERE outbound_pick_detail_id = @v_vchOutboundNewPickDetailID
														END
													ELSE
														BEGIN
															--2. new record ใหม่
															SET @v_vchOutboundNewPickDetailID = NEWID()
															SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail 
															WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
															IF (@v_vchNewPickLineNumber IS NULL)
																BEGIN SET @v_vchNewPickLineNumber = '00001'; END
															ELSE
																BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

															INSERT INTO [dbo].[t_wms_outbound_pick_detail]
																	([outbound_pick_detail_id]
																	,[outbound_pick_master_id]
																	,[outbound_order_detail_id]
																	,[pick_line_number]
																	,[location_id]
																	,[pick_location_id]
																	,[pick_to_lpn]
																	,[pick_to_parent_lpn]
																	,[wh_item_master_id]
																	,[quantity_plan]
																	,[quantity_pick] 
																	,[quantity_stage]
																	,[quantity_pack]
																	,[quantity_load]
																	,[quantity_ship]
																	,[short_pick_reason_id]
																	,[parent_lpn]
																	,[lpn]
																	,[lot_number]
																	,[expiry_date]
																	,[serial_number]
																	,[attribute1]
																	,[attribute2]
																	,[attribute3]
																	,[attribute4]
																	,[attribute5]
																	,[user_assign]
																	,[staging_location_id]
																	,[staging_parent_lpn]
																	,[staging_lpn]
																	,[next_location_reason_id]
																	,[over_pick_reason_id]
																	,[dock_door_id]
																	,[dock_door_parent_lpn]
																	,[dock_door_lpn]
																	,[pick_status]
																	,[load_status]
																	,[ship_status]
																	,[inventory_id]
																	,[pack_status]
																	,[pick_generate_method]
																	,[is_allocate]
																	,[is_override]
																	,[pick_override_reason]
																	,[receive_date]
																	,[mfg_date]
																	,[is_active]
																	,[start_date_time]
																	,[end_date_time]
																	,[create_date]
																	,[create_by])
															(SELECT TOP 1 @v_vchOutboundNewPickDetailID
																	, outbound_pick_master_id
																	, outbound_order_detail_id
																	, @v_vchNewPickLineNumber
																	, location_id
																	, @v_vchForkID
																	, @v_vchPickToLPN
																	, @in_vchToParentLPN
																	, wh_item_master_id
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_plan
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_pick
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_stage
																	, 0
																	, 0
																	, 0
																	, short_pick_reason_id
																	, parent_lpn
																	, lpn
																	, lot_number
																	, expiry_date
																	, serial_number
																	, attribute1
																	, attribute2
																	, attribute3
																	, attribute4
																	, attribute5
																	, user_assign
																	, @v_vchStagingLocationID
																	, @v_vchStagingParentLPN
																	, @v_vchStagingLPN
																	, next_location_reason_id
																	, over_pick_reason_id
																	, dock_door_id
																	, dock_door_parent_lpn
																	, dock_door_lpn
																	, 'YES'
																	, 'NO'
																	, 'NO'
																	, inventory_id
																	, pack_status
																	, pick_generate_method
																	, is_allocate
																	, 'NO'
																	, pick_override_reason
																	, @v_dtInvReceiveDate
																	, mfg_date
																	, is_active
																	, GETDATE()
																	, GETDATE()
																	, GETDATE()
																	, @in_vchUserID
																FROM t_wms_outbound_pick_detail
																WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID)
														END

													--นำ ID ของ Record ใหม่ไปใช้แทน ID เก่า
													SET @v_vchOutboundPickDetailID = @v_vchOutboundNewPickDetailID
												END
										END
									ELSE
										BEGIN
											SET @v_vchStagingLocationID = NULL
											SET @v_vchStagingLocation = NULL
											SET @v_fltQuantityStage = 0	
											SET @v_vchStagingParentLPN = NULL	
											SET @v_vchStagingLPN = NULL
											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											-----------------------------------------------
											-- แบบปกติ ไม่ต้องวาง STG
											-----------------------------------------------
											IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
														WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND is_override = 'NO'
														AND receive_date = @v_dtInvReceiveDate
														AND (CASE WHEN quantity_pick > 0 THEN pick_to_lpn ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN @v_vchPickToLPN ELSE '' END)
														AND (CASE WHEN quantity_pick > 0 THEN CONVERT(VARCHAR(36),pick_location_id) ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN CONVERT(VARCHAR(36),@v_vchForkID) ELSE '' END)) OR @v_vchSNControl = 'FULL'
												BEGIN
													UPDATE t_wms_outbound_pick_detail SET 
														  quantity_pick		 = ROUND(ISNULL(quantity_pick,0)+ @v_fltQtyPick,@Round)
														, pick_location_id   = @v_vchForkID
														, pick_to_parent_lpn = @in_vchToParentLPN
														, pick_to_lpn		 = @v_vchPickToLPN
														, pick_status        = 'YES'
														, start_date_time	 = ISNULL(start_date_time,GETDATE())
														, end_date_time		 = GETDATE()
														, serial_number		 = @v_vchInvSerialNumber
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
												END
											ELSE
												BEGIN
													--Insert New Pick Detail
													--1. ลบยอดจำนวนจากรายการเดิม
													UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyPick,@Round)
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
											
													NEW_PICK_DETAIL:
													--Check ว่ามี recode เดิมหรือไม่ ถ้ามีให้ทำการ update
													SET @v_vchOutboundNewPickDetailID = NULL
													SELECT @v_vchOutboundNewPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
													WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
													AND outbound_order_detail_id = @v_vchOutboundDetailID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND location_id = @v_vchLocationID
													AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
													AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'') 
													AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
													AND ISNULL(expiry_date,'') =  ISNULL(@in_vchExpiryDate,'')
													AND ISNULL(serial_number,'') =  ISNULL(@v_vchInvSerialNumber,'')
													AND ISNULL(attribute1,'') =  ISNULL(@in_vchAttribute1,'')
													AND ISNULL(attribute2,'') =  ISNULL(@in_vchAttribute2,'')
													AND ISNULL(attribute3,'') =  ISNULL(@in_vchAttribute3,'')
													AND ISNULL(attribute4,'') =  ISNULL(@in_vchAttribute4,'')
													AND ISNULL(attribute5,'') =  ISNULL(@in_vchAttribute5,'')
													AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
													ANd pick_location_id = @v_vchForkID
													AND receive_date = @v_dtInvReceiveDate
													AND is_override = 'NO'

													IF (@v_vchOutboundNewPickDetailID IS NOT NULL)
														BEGIN
															UPDATE t_wms_outbound_pick_detail SET 
																  quantity_plan		 = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyPick,@Round)
																, quantity_pick		 = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
																, pick_location_id   = @v_vchForkID
																, pick_to_parent_lpn = @in_vchToParentLPN
																, pick_to_lpn		 = @v_vchPickToLPN
																, pick_status        = 'YES'
																, start_date_time	 = ISNULL(start_date_time,GETDATE())
																, end_date_time		 = GETDATE()
																, serial_number		 = @v_vchInvSerialNumber
															WHERE outbound_pick_detail_id = @v_vchOutboundNewPickDetailID
														END
													ELSE
														BEGIN
															--2. new record ใหม่
															SET @v_vchOutboundNewPickDetailID = NEWID()
															SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail 
															WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
															IF (@v_vchNewPickLineNumber IS NULL)
																BEGIN SET @v_vchNewPickLineNumber = '00001'; END
															ELSE
																BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

															INSERT INTO [dbo].[t_wms_outbound_pick_detail]
																	([outbound_pick_detail_id]
																	,[outbound_pick_master_id]
																	,[outbound_order_detail_id]
																	,[pick_line_number]
																	,[location_id]
																	,[pick_location_id]
																	,[pick_to_lpn]
																	,[pick_to_parent_lpn]
																	,[wh_item_master_id]
																	,[quantity_plan]
																	,[quantity_pick] 
																	,[quantity_stage]
																	,[quantity_pack]
																	,[quantity_load]
																	,[quantity_ship]
																	,[short_pick_reason_id]
																	,[parent_lpn]
																	,[lpn]
																	,[lot_number]
																	,[expiry_date]
																	,[serial_number]
																	,[attribute1]
																	,[attribute2]
																	,[attribute3]
																	,[attribute4]
																	,[attribute5]
																	,[user_assign]
																	,[staging_location_id]
																	,[staging_parent_lpn]
																	,[staging_lpn]
																	,[next_location_reason_id]
																	,[over_pick_reason_id]
																	,[dock_door_id]
																	,[dock_door_parent_lpn]
																	,[dock_door_lpn]
																	,[pick_status]
																	,[load_status]
																	,[ship_status]
																	,[inventory_id]
																	,[pack_status]
																	,[pick_generate_method]
																	,[is_allocate]
																	,[is_override]
																	,[pick_override_reason]
																	,[receive_date]
																	,[mfg_date]
																	,[is_active]
																	,[start_date_time]
																	,[end_date_time]
																	,[create_date]
																	,[create_by])
															(SELECT TOP 1 @v_vchOutboundNewPickDetailID
																	, outbound_pick_master_id
																	, outbound_order_detail_id
																	, @v_vchNewPickLineNumber
																	, location_id
																	, @v_vchForkID
																	, @v_vchPickToLPN
																	, @in_vchToParentLPN
																	, wh_item_master_id
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_plan
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_pick 
																	, 0
																	, 0
																	, 0
																	, 0
																	, short_pick_reason_id
																	, parent_lpn
																	, lpn
																	, lot_number
																	, expiry_date
																	, serial_number
																	, attribute1
																	, attribute2
																	, attribute3
																	, attribute4
																	, attribute5
																	, user_assign
																	, @v_vchStagingLocationID
																	, @v_vchStagingParentLPN
																	, @v_vchStagingLPN
																	, next_location_reason_id
																	, over_pick_reason_id
																	, dock_door_id
																	, dock_door_parent_lpn
																	, dock_door_lpn
																	, 'YES'
																	, 'NO'
																	, 'NO'
																	, inventory_id
																	, pack_status
																	, pick_generate_method
																	, is_allocate
																	, 'NO'
																	, pick_override_reason
																	, @v_dtInvReceiveDate
																	, mfg_date
																	, is_active
																	, GETDATE()
																	, GETDATE()
																	, GETDATE()
																	, @in_vchUserID
																FROM t_wms_outbound_pick_detail
																WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID)	
														END
													--นำ ID ของ Record ใหม่ไปใช้แทน ID เก่า
													SET @v_vchOutboundPickDetailID = @v_vchOutboundNewPickDetailID
												END
										END
								END

							---------------------------------------------------
							-- Insert/Update Pack Detail
							---------------------------------------------------
							IF (@RulePickPack = 'YES')
								BEGIN
									UPDATE t_wms_outbound_pick_detail SET 
										  quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltQtyPick,@Round)
										, end_date_time = GETDATE()
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

									---------------------------------------------------
									--Insert/Update Pack Detail
									---------------------------------------------------
									PRINT 'Pick and Pack'
									IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
														WHERE outbound_order_master_id = @v_vchOutboundMasterID
														AND pack_location_id = @v_vchForkID
														AND lpn_pack = @v_vchPickToLPN 
														AND wh_item_master_id = @v_vchWhItemMasterID 
														AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
										BEGIN
											UPDATE t_wms_outbound_pack_detail SET 
												 quantity_pack = ROUND(quantity_pack + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(quantity_stage + @v_fltQuantityStage,@Round)
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND pack_location_id = @v_vchForkID
											AND lpn_pack = @v_vchPickToLPN 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
											AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
										END
									ELSE
										BEGIN
											INSERT INTO t_wms_outbound_pack_detail
											(     outbound_order_master_id
												, outbound_pick_detail_id
												, lpn_pack
												, pack_location_id
												, wh_item_master_id
												, quantity_pack
												, quantity_stage
												, lot_number
												, expiry_date
												, serial_number
												, [attribute1]
												, [attribute2]
												, [attribute3]
												, [attribute4]
												, [attribute5]
												, item_uom_id
												, [staging_location_id]
												, [staging_parent_lpn]
												, [staging_lpn]
												, create_by
											)
											VALUES
											(     @v_vchOutboundMasterID
												, @v_vchOutboundPickDetailID
												, @v_vchPickToLPN
												, @v_vchForkID
												, @v_vchWhItemMasterID
												, ROUND(@v_fltQtyPick,@Round)
												, @v_fltQuantityStage
												, @in_vchLot
												, @in_vchExpiryDate
												, @v_vchInvSerialNumber
												, @in_vchAttribute1
												, @in_vchAttribute2
												, @in_vchAttribute3
												, @in_vchAttribute4
												, @in_vchAttribute5
												, @v_vchBaseItemUomID
												, @v_vchStagingLocationID
												, @v_vchStagingParentLPN
												, @v_vchStagingLPN
												, @in_vchUserID
											)
										END
								END

							---------------------------------------------------
							--Calculate Volumn & Weight
							---------------------------------------------------
							IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyPick,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyPick,2)
							END

							---------------------------------------------------
							-- Manage source location data
							---------------------------------------------------
							BEGIN
								--Update Volumn & Weight in from location
								IF @v_vchLocationID IS NOT NULL
									BEGIN
										UPDATE [dbo].[t_wms_location]
										   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
											, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
											, update_date = GETDATE()  
											, [update_by] = @in_vchUserID   
										 WHERE [location_id] = @v_vchLocationID
									END

								UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
									,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - (@v_fltQtyPick - @v_fltAllocateQtyOverPick),@Round)
									,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
									,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID

								UPDATE #tInventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID

								IF (@v_vchSNControl = 'FULL')
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round) 
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID 
										AND attribute_value = @v_vchInvSerialNumber
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END

								IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
											,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - (@v_fltQtyPick - @v_fltAllocateQtyOverPick),@Round)
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID
										AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END
							END

							------------------------------------------------
							-- Clear Inventory ที่หยิบของหมดแล้ว
							------------------------------------------------
							DELETE FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchInvID AND quantity <= 0
							DELETE FROM t_wms_inventory WHERE inventory_id = @v_vchInvID AND quantity <= 0 
							DELETE FROM #tInventory WHERE inventory_id = @v_vchInvID AND quantity <= 0

							--------------------------------------------
							--Manage Destination inventory
							--------------------------------------------
							SET @v_vchInventoryID = NULL
							SET @v_vchAttributeGroupID = NULL
							IF (@RuleAutoStaging = 'YES')
								BEGIN
									SELECT @v_vchInventoryID = inventory_id
										,@v_vchAttributeGroupID = attribute_group_id
									FROM v_wms_inventory_data_by_id
									WHERE wh_master_id = @v_vchWhMasterID
									AND owner_id = @v_vchOwnerID
									AND location_id = @v_vchStagingLocationID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND inventory_status_id = @v_vchInvStatusID
									and receive_date = @v_dtInvReceiveDate
									AND ISNULL(parent_lpn,'') = ISNULL(@v_vchStagingParentLPN,'')
									AND ISNULL(lpn,'') = ISNULL(@v_vchStagingLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
									AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

									EXEC usp_manage_inventory @in_vchWhMasterID		= @v_vchWhMasterID
															, @in_vchOwnerID		= @v_vchOwnerID
															, @in_vchWHItemMasterID	= @v_vchWhItemMasterID
															, @in_vchLocationID		= @v_vchStagingLocationID
															, @in_vchStatusID		= @v_vchInvStatusID
															, @in_vchPalentLPN		= @v_vchStagingParentLPN
															, @in_vchLPN			= @v_vchStagingLPN
															, @in_fltQty			= @v_fltQtyPick
															, @in_fltQtyAllocate	= 0
															, @in_fltQtyIncoming	= 0
															, @in_vchInventoryType	= @in_vchPicklistNumber
															, @in_vchUserID			= @in_vchUserID
															, @in_vchReceiveDate	= @v_dtInvReceiveDate
															, @in_dtMFGDate			= @v_dtInvMfgDate
															, @in_vchInventoryID	= @v_vchInventoryID OUTPUT
															, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
															, @in_vchErrorCode		= @out_ErrorCode OUTPUT
															, @in_vchMessage		= @out_ErrorMessage OUTPUT	

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;

									--Update Volumn & Weight in from location
									IF @v_vchStagingLocationID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
												, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @v_vchStagingLocationID
										END
								END
							ELSE
								BEGIN
									SELECT @v_vchInventoryID = inventory_id
										,@v_vchAttributeGroupID = attribute_group_id
									FROM v_wms_inventory_data_by_id
									WHERE wh_master_id = @v_vchWhMasterID
									AND owner_id = @v_vchOwnerID
									AND location_id = @v_vchForkID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND inventory_status_id = @v_vchInvStatusID
									and receive_date = @v_dtInvReceiveDate
									AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
									AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
									AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

									EXEC usp_manage_inventory @in_vchWhMasterID		  = @v_vchWhMasterID
															, @in_vchOwnerID		  = @v_vchOwnerID
															, @in_vchWhItemMasterID   = @v_vchWhItemMasterID
															, @in_vchLocationID		  = @v_vchForkID
															, @in_vchStatusID		  = @v_vchInvStatusID
															, @in_vchPalentLPN		  = @in_vchToParentLPN
															, @in_vchLPN			  = @v_vchPickToLPN
															, @in_fltQty			  = @v_fltQtyPick
															, @in_fltQtyAllocate	  = 0
															, @in_fltQtyIncoming	  = 0
															, @in_vchInventoryType	  = @in_vchPicklistNumber
															, @in_vchUserID			  = @in_vchUserID
															, @in_vchReceiveDate	  = @v_dtInvReceiveDate
															, @in_dtMFGDate			  = @v_dtInvMfgDate	
															, @in_vchInventoryID	  = @v_vchInventoryID OUTPUT
															, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
															, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
															, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;

									--Update Volumn & Weight in from location
									IF @v_vchForkID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
												, total_weight =  ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @v_vchForkID
										END
								END
								
							--update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET
								 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttributeGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
											@in_vchLot				= @in_vchLot
										, @in_vchExpiryDate			= @in_vchExpiryDate
										, @in_vchSerialNo			= @in_vchSerialNo
										, @in_vchAttribute1			= @in_vchAttribute1
										, @in_vchAttribute2			= @in_vchAttribute2
										, @in_vchAttribute3			= @in_vchAttribute3
										, @in_vchAttribute4			= @in_vchAttribute4
										, @in_vchAttribute5			= @in_vchAttribute5
										, @in_fltQty				= @v_fltQtyPick
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInventoryID
										, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END	
						
							--Set ค่าว่าง = NULL
							BEGIN
							IF (ISNULL(@in_vchLot,'') = '')
								BEGIN
									SET @in_vchLot = NULL
								END
							IF (ISNULL(@in_vchExpiryDate,'') = '')
								BEGIN
									SET @in_vchExpiryDate = NULL
								END
							IF (ISNULL(@in_vchAttribute1,'') = '')
								BEGIN
									SET @in_vchAttribute1 = NULL
								END
							IF (ISNULL(@in_vchAttribute2,'') = '')
								BEGIN
									SET @in_vchAttribute2 = NULL
								END
							IF (ISNULL(@in_vchAttribute3,'') = '')
								BEGIN
									SET @in_vchAttribute3 = NULL
								END
							IF (ISNULL(@in_vchAttribute4,'') = '')
								BEGIN
									SET @in_vchAttribute4 = NULL
								END
							IF (ISNULL(@in_vchAttribute5,'') = '')
								BEGIN
									SET @in_vchAttribute5 = NULL
								END
							IF (ISNULL(@in_vchFromParentLPN,'') = '')
								BEGIN
									SET @in_vchFromParentLPN = NULL
								END
							IF (ISNULL(@in_vchToParentLPN,'') = '')
								BEGIN
									SET @in_vchToParentLPN = NULL
								END
							IF (ISNULL(@in_vchFromLPN,'') = '')
								BEGIN
									SET @in_vchFromLPN = NULL
								END
							IF (ISNULL(@v_vchPickToLPN,'') = '')
								BEGIN
									SET @v_vchPickToLPN = NULL
								END
							END

							---------------------------------------------------		
							-- Write Tran Log  
							---------------------------------------------------		
							IF (@RuleAutoStaging = 'YES')
							BEGIN
								--Write Lot Pick to STG
								INSERT INTO t_com_tran_log
									( app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, line_number
									, udf_1
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'MOVE_DEST'
									, @v_vchApplicationName
									, 'Update pick to staging [Auto to Staging]'
									, @v_dtStartTime
									, DATEADD(millisecond,2,GETDATE())
									, @in_vchWarehouse
									, @in_vchWarehouse
									, @v_vchPickLocation
									, @v_vchStagingLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @in_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUom
									, @v_fltInvQuantity - @v_fltQtyPick 
									, @v_vchBaseUom
									, @in_vchLot
									, @in_vchLot
									, @in_vchExpiryDate
									, @in_vchExpiryDate
									, @v_vchInvSerialNumber
									, @in_vchAttribute1
									, @in_vchAttribute1
									, @in_vchAttribute2
									, @in_vchAttribute2
									, @in_vchAttribute3
									, @in_vchAttribute3
									, @in_vchAttribute4
									, @in_vchAttribute4
									, @in_vchAttribute5
									, @in_vchAttribute5
									, @in_vchUserID 
									, @in_vchFromParentLPN
									, @in_vchToParentLPN
									, @in_vchFromLPN
									, @v_vchPickToLPN
									, @v_vchInvstatus
									, @v_vchInvstatus 
									, @in_vchPicklistNumber
									, @v_vchPickLineNumber
									, @in_vchTrackingNo 
									, @in_vchDeviceID
									, @in_vchUserID
									, DATEADD(millisecond,2,GETDATE())
									, @v_vchPickLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)

								----------------------------------------
								--Insert For Checker RFID
								--ต้องทำตอน วาง STG
								----------------------------------------
								IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
									BEGIN
										IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @v_vchOutboundMasterID AND serial_number = @v_vchInvSerialNumber)
											BEGIN
												INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
														([checker_rfid_id]
														,[processing_status]
														,[outbound_order_master_id]
														,[serial_number]
														,[user_id]
														,[device]
														,[create_by]
														,[create_date])
													VALUES
														(NEWID()
														,'PENDING'
														,@v_vchOutboundMasterID
														,@v_vchInvSerialNumber
														,@in_vchUserID
														,@in_vchDeviceID
														,@in_vchUserID
														,GETDATE())
											END
									END
							END
							ELSE
							BEGIN
								--Write Log Pick to Fork
								INSERT INTO t_com_tran_log
								(     app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, line_number 
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'SALES_ORDER'
									, @v_vchApplicationName
									, 'System Directed Picking'
									, @v_dtStartTime
									, GETDATE()
									, @in_vchWarehouse
									, @in_vchWarehouse
									, @in_vchFromLocation
									, @in_vchForkLift
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @in_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUom
									, @v_fltInvQuantity - @v_fltQtyPick 
									, @v_vchBaseUom
									, @in_vchLot
									, @in_vchLot
									, @in_vchExpiryDate
									, @in_vchExpiryDate
									, @v_vchInvSerialNumber
									, @in_vchAttribute1
									, @in_vchAttribute1
									, @in_vchAttribute2
									, @in_vchAttribute2
									, @in_vchAttribute3
									, @in_vchAttribute3
									, @in_vchAttribute4
									, @in_vchAttribute4
									, @in_vchAttribute5
									, @in_vchAttribute5
									, @in_vchUserID
									, @in_vchFromParentLPN
									, @in_vchToParentLPN
									, @in_vchFromLPN
									, @v_vchPickToLPN
									, @v_vchInvstatus
									, @v_vchInvstatus
									, @in_vchPicklistNumber
									, @v_vchPickLineNumber 
									, @in_vchDeviceID	
									, @in_vchUserID		
									, GETDATE()
									, @v_vchPickLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)
							END

							--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
							SET @v_fltRemainQtyCanPick = @v_fltRemainQtyCanPick - @v_fltQtyPick

							--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
							IF @v_fltRemainQtyCanPick = 0
								BREAK;

							FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_dtInvMfgDate,@v_dtInvReceiveDate
						END
				END
			ELSE
				BEGIN
					-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
					SET @out_ErrorCode = 'NOT_FOUND_ITEM_IN_PICKING_LIST'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
					GOTO WRITE_PROC;
				END
			CLOSE InventoryCursor
			DEALLOCATE InventoryCursor
			 
			-- For Dashboard
			BEGIN
				DECLARE @v_vchDSToLocationID UNIQUEIDENTIFIER = NULL 
				IF @RuleAutoStaging = 'YES'
					BEGIN
						SET @v_vchDSToLocationID = @v_vchStagingLocationID 
					END
				ELSE
					BEGIN  
						SET @v_vchDSToLocationID = @v_vchForkID 
					END
				EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
												,@in_vchTransType	 = 'PICK'
												,@in_vchWhMasterID	 = @v_vchWhMasterID
												,@in_vchOwnerID		 = @v_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwnerCode
												,@in_vchLocationID	 = @v_vchLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @v_vchInvStatusID
												,@in_vchToWhMasterID = @v_vchWhMasterID
												,@in_vchToLocationID = @v_vchDSToLocationID
												,@in_vchToInvStatusID = @v_vchInvStatusID
												,@in_fltQuantity	 = @v_fltQtyCanPick
												,@in_vchUserID		 = @in_vchUserID
			END

			-------------------------------------------------------------------------------
			-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
			-------------------------------------------------------------------------------
			SET @v_fltSumQtyCanPick = ROUND((@v_fltSumQtyCanPick - @v_fltQtyCanPick),@Round)
			IF @v_fltSumQtyCanPick = 0
				BREAK;

			FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_vchOutboundDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_dtReceiveDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchPickLocation
			SET @v_nOutboundCursorRow = @v_nOutboundCursorRow + 1	--สำหรับ check record สุดท้ายของ loop เพื่อกรณีที่เป็น over pick จะให้ over pick ของ record สุดท้าย ที่ loop
		END	       
	CLOSE OutboundDetailCursor
	DEALLOCATE OutboundDetailCursor

	------------------------------------------------
	-- Update Order Status ถ้า Pick ครบแล้ว
	------------------------------------------------
	IF ((SELECT SUM(quantity_order - ISNULL(quantity_pick,0)) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID) <= 0)	--น้อยกว่าหรือเท่าศูนย์ เพราะมีกรณี over pick
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @v_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID
				, order_status = 'PICK'
				, update_by = @in_vchUserID
				, update_date = getdate()
			WHERE outbound_order_master_id = @v_vchOutboundMasterID
		END
	
	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundDetailCursor')>=-1
		BEGIN
			CLOSE OutboundDetailCursor;
			DEALLOCATE OutboundDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END	
				  
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData = 'Qty: ' + convert(varchar,@in_fltQty) + ' ' + @in_vchUOMPrompt;
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchPicklistNumber,
			@in_vchData2 = @in_vchFromLocation,
			@in_vchData3 = @in_vchItemNumber,
			@in_vchData4 = @v_vchProcessData,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
	
	IF CURSOR_STATUS('global','OutboundDetailCursor')>=-1
		BEGIN
			CLOSE OutboundDetailCursor;
			DEALLOCATE OutboundDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQty) + ' ' + @in_vchUOMPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchPicklistNumber,
		@in_vchData2 = @in_vchFromLocation,
		@in_vchData3 = @in_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_item_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_outbound_update_pick_item_by_group]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchLoadID			NVARCHAR(40),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchForkLift			NVARCHAR(50),
	@in_vchItem				NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vchFromParentLPN	NVARCHAR(25)  = NULL,
	@in_vchFromLPN			NVARCHAR(25)  = NULL,
	@in_vchToParentLPN		NVARCHAR(25)  = NULL,
	@in_vchToLPN			NVARCHAR(25)  = NULL,
	@in_vchLot				NVARCHAR(100) = NULL,
	@in_vchExpiryDate		NVARCHAR(50)  = NULL,
	@in_vchSerialNo			NVARCHAR(100) = NULL,
	@in_vchOverPickReason	NVARCHAR(20)  = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @DynamicSQL					NVARCHAR(MAX) = '',
			@ConditionSQL				NVARCHAR(MAX) = '',
			@ParameterDefinition		NVARCHAR(200) = NULL,
			@OBDetail_CURSOR			CURSOR,
			@Inventory_CURSOR			CURSOR,
			@v_vchBeginTrans			BIT = 0,

			@RulePickPack				NVARCHAR(3)  = NULL,
			@Round						INT,
			@v_nCount					INT,
			@v_vchLocalID				VARCHAR(40)  = NULL,

			@v_vchWhMasterID			VARCHAR(40),
			@v_vchLocationID			VARCHAR(40),
			@v_vchForkID				VARCHAR(40)  = NULL,

			--Outbound
			@v_vchOutboundOrderMasterID	VARCHAR(40)  = NULL, 
			@v_vchOutboundOrderNumber	NVARCHAR(50) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchOwnerID				VARCHAR(40)  = NULL,
			@v_vchOwnerCode				NVARCHAR(50) = NULL,
			@v_vchOutboundDetailID		VARCHAR(40)  = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL, -- Outbound Detail
			@v_vchPickLineNumber		NVARCHAR(10) = NULL, -- Outbound Pick Detail
			@v_vchItemMasterID			VARCHAR(40)  = NULL,
			@v_vchWhItemMasterID		VARCHAR(40)  = NULL,
			@v_vchLotControl			NVARCHAR(10) = NULL,
			@v_vchExpControl			NVARCHAR(10) = NULL,
			@v_vchSNControl				NVARCHAR(10) = NULL,

			@v_vchAttribute1Control		NVARCHAR(10) = NULL,
			@v_vchAttribute2Control		NVARCHAR(10) = NULL,
			@v_vchAttribute3Control		NVARCHAR(10) = NULL,
			@v_vchAttribute4Control		NVARCHAR(10) = NULL,
			@v_vchAttribute5Control		NVARCHAR(10) = NULL,

			@v_vchPrimaryUOMPrompt		NVARCHAR(40) = NULL,
			@v_vchPrimaryConversion		FLOAT		 = NULL,
			@v_vchPickToLPN				NVARCHAR(25) = NULL,
			@v_fltQuantityPlan			FLOAT,
			@v_fltQuantityPick			FLOAT,
			@v_vchItemUomID				VARCHAR(40),
			@v_vchDefaultItemStatus		NVARCHAR(40)= NULL,	-- มาจาก Plan

			--Pick
			@v_vchOutboundPickMasterID	VARCHAR(40)  = NULL,
			@v_vchOutboundPickDetailID	VARCHAR(40)  = NULL,			

			--จำนวนที่ใช้ในการจ่ายจริง หลังแปลงเป็นหน่วยที่เล็กที่สุด [primary_uom = 'YES']
			@v_fltConversionQuantity	FLOAT,
			@v_fltSumQtyCanPick			FLOAT,
			@v_fltSumPlanRemainPick		FLOAT, --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Order ใน item ที่ scan

			--Inventory 
			@v_vchInventoryID			VARCHAR(40)  = NULL,
			@v_fltInvQty				FLOAT,
			@v_fltInvQtyAllocate		FLOAT,
			@v_fltInvQtyForCheck		FLOAT,  --สำหรับ Check จำนวนที่หยิบ กับจำนวนใน inventory เพื่อ Set pick_to_lpn ถ้าหยิบทั้ง LPN

			-- STG MOD For CBD
			@v_vchStagingLocation		NVARCHAR(50),
			@v_vchStagingLocationID		VARCHAR(40),
			@v_vchOldStagingLocationID	VARCHAR(40),
			@v_vchOldStagingLocation	NVARCHAR(50),
			@v_fltQuantityStage			FLOAT,
			@v_vchStagingParentLPN		NVARCHAR(25) = NULL,
			@v_vchStagingLPN			NVARCHAR(25) = NULL,
			@v_vchPickAndSTG			NVARCHAR(3) = 'NO'

BEGIN TRY

	SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
	SELECT @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchFromLocation AND is_active = 'YES'
	SELECT @v_vchForkID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchForkLift AND is_active = 'YES'
	
	SET @in_fltQty = ROUND(@in_fltQty,@Round)

	--------------------------------------------------
	-- Get Owner in Outbound [Top 1]
	--------------------------------------------------
	SELECT TOP 1 @v_vchOwnerID = obMS.owner_id
		, @v_vchOwnerCode = own.owner_code
	FROM t_wms_outbound_master obMS
	LEFT JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	WHERE wh_master_id = @v_vchWhMasterID
	AND load_id = @in_vchLoadID

	-------------------------------------------------
	-- SET Box Number
	-------------------------------------------------
	IF ISNULL(@in_vchToLPN,'') = ''
		BEGIN
			SET @in_vchToLPN = @in_vchLoadID
		END

	-------------------------------------------------
	-- Check ถ้ามีบาง Order ที่ Ship ไปแล้วจะ pick ต่อไม่ได้
	-------------------------------------------------
	IF EXISTS (SELECT outbound_order_master_id FROM t_wms_outbound_master 
			   WHERE load_id = @in_vchLoadID 
			   AND wh_master_id = @v_vchWhMasterID
			   AND order_status = 'SHIP')
		BEGIN
			SET @out_ErrorCode = '401';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK',@v_vchLocalID,@in_vchLoadID,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END
	
	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItem = item.item_number
		, @v_vchLotControl = item.lot_control
		, @v_vchExpControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
	FROM t_wms_item item
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @v_vchOwnerID
	AND (item.item_number = @in_vchItem OR item.dg_code = @in_vchItem OR cref.alternate_item_number = @in_vchItem)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @v_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Check input uom ที่รับเข้ามาว่ามีอยู่ใน Master หรือไม่
	--------------------------------------------------
	IF NOT EXISTS (SELECT item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND uom_prompt = @in_vchUOMPrompt AND is_active = 'YES')
		BEGIN
			SET @out_ErrorCode = 'INFO-INVALID-UOM'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,@in_vchUOMPrompt,'@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Get Primary UOM และ คำนวนจำนวนให้อยู่หน่วยที่เล็กที่สุด
	--------------------------------------------------
	SELECT @v_vchPrimaryUOMPrompt = uom_prompt
		,@v_vchPrimaryConversion = conversion_factor
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND primary_uom = 'YES'
	AND is_active = 'YES'

	IF @in_vchUOMPrompt <> @v_vchPrimaryUOMPrompt
		BEGIN
			-- กรณีที่ไม่ได้จ่ายเป็นหน่วยที่เล็กที่สุด ต้องคำนวณ จำนวนที่จ่ายให้เป็นหน่วยที่เล็กที่สุด
			SELECT @v_fltConversionQuantity = ROUND((@in_fltQty * conversion_factor),@Round)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND uom_prompt = @in_vchUOMPrompt
			AND is_active = 'YES'
		END
	ELSE
		BEGIN
			--กรณีที่จ่ายมาเป็นหน่วยที่เล็กที่สุดแล้วไม่ต้องแปลง
			SET @v_fltConversionQuantity = ROUND(@in_fltQty,@Round)
		END
	
	-------------------------------------------------
	-- GET Data From Inventory
	-- Check จำนวนใน Inventory 
	-------------------------------------------------
	SET @DynamicSQL = 'SELECT TOP 1 @v_vchInventoryID = inventory_id
		,@v_fltInvQty = quantity
		,@v_fltInvQtyAllocate = quantity_allocated'
	
	IF (@in_vchSerialNo = 'ALL' OR ISNULL(@in_vchSerialNo,'') = '')
		SET @DynamicSQL = @DynamicSQL + ' FROM v_wms_inventory_data WHERE (0=0)'
	ELSE
		SET @DynamicSQL = @DynamicSQL + ' FROM v_wms_inventory_data_by_serial WHERE serial_number = ''' + @in_vchSerialNo + ''''
		
	SET @DynamicSQL = @DynamicSQL + ' AND wh_master_id = ''' + @v_vchWhMasterID + '''
	AND wh_item_master_id = ''' + @v_vchWhItemMasterID + '''
	AND location_id = ''' + @v_vchLocationID+ ''''

	IF (ISNULL(@in_vchFromParentLPN,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(parent_lpn,'''') = ''' + ISNULL(@in_vchFromParentLPN,'') + '''' 
		END
	IF (ISNULL(@in_vchFromLPN,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(lpn,'''') = '''+ ISNULL(@in_vchFromLPN,'') + ''''
		END
	IF (ISNULL(@in_vchLot,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(lot_number,'''') = ''' + ISNULL(@in_vchLot,'') + ''''
		END
	IF (ISNULL( @in_vchExpiryDate,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(expiry_date,'''') = ''' + ISNULL(@in_vchExpiryDate,'') + ''''
		END
	IF (ISNULL(@in_vchAttribute1,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(attribute1,'''') = ''' + ISNULL(@in_vchAttribute1,'') + ''''
		END
	IF (ISNULL(@in_vchAttribute2,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(attribute2,'''') = ''' + ISNULL(@in_vchAttribute2,'') + ''''
		END
	IF (ISNULL(@in_vchAttribute3,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(attribute3,'''') = ''' + ISNULL(@in_vchAttribute3,'') + ''''
		END
	IF (ISNULL(@in_vchAttribute4,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(attribute4,'''') = ''' + ISNULL(@in_vchAttribute4,'') + ''''
		END
	IF (ISNULL(@in_vchAttribute5,'') <> '')
		BEGIN
			SET @DynamicSQL = @DynamicSQL + ' AND ISNULL(attribute5,'''') = ''' + ISNULL(@in_vchAttribute5,'') + ''''
		END


	SET @ParameterDefinition = '@v_vchInventoryID VARCHAR(40) OUTPUT, @v_fltInvQty FLOAT OUTPUT, @v_fltInvQtyAllocate FLOAT OUTPUT';
	EXEC sp_executesql @DynamicSQL, @ParameterDefinition, @v_vchInventoryID OUTPUT
														, @v_fltInvQty OUTPUT
														, @v_fltInvQtyAllocate OUTPUT
	
	IF @v_vchInventoryID IS NULL
		BEGIN
			-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
			SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Check จำนวนใน Inventory กับจำนวนที่จะจ่าย
	-- จำนวนที่จะ Pick > จำนวนใน Inventory
	--------------------------------------------------
	IF (@in_vchSerialNo = 'ALL')
		BEGIN 
			SET @v_fltConversionQuantity = ROUND(@v_fltInvQty,@Round)
		END
		
	IF ROUND(@v_fltConversionQuantity,@Round) > ROUND(@v_fltInvQty,@Round)
		BEGIN
			-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
			SET @out_ErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	------------------------------------------------------------------------------
	-- เงื่อนไข Plan Pick detail 
	-- ใช้สำหรับตรวจสอบรายการที่จะ pick ว่าตรงกับ Plan ที่ release order มา
	-- ใช้สำหรับวนลูปเพื่อ Insert/Update Pick List
	------------------------------------------------------------------------------
	SET @ConditionSQL = ' WHERE obMS.load_id = ''' + @in_vchLoadID + '''
	AND pickDT.is_override = ''NO''
	AND pickDT.location_id = ''' + @v_vchLocationID + '''
	AND pickDT.wh_item_master_id = ''' + @v_vchWhItemMasterID + '''
	AND ISNULL(pickDT.parent_lpn,'''') = ''' + ISNULL(@in_vchFromParentLPN,'') + '''
	AND ISNULL(pickDT.lpn,'''') = ''' + ISNULL(@in_vchFromLPN,'') + '''
	AND ISNULL(pickDT.lot_number,'''') = ''' + ISNULL(@in_vchLot,'') + '''
	AND ISNULL(pickDT.expiry_date,'''') = ''' + ISNULL(@in_vchExpiryDate,'') + '''
	AND ISNULL(pickDT.attribute1,'''') = ''' + ISNULL(@in_vchAttribute1,'') + '''
	AND ISNULL(pickDT.attribute2,'''') = ''' + ISNULL(@in_vchAttribute2,'') + '''
	AND ISNULL(pickDT.attribute3,'''') = ''' + ISNULL(@in_vchAttribute3,'') + '''
	AND ISNULL(pickDT.attribute4,'''') = ''' + ISNULL(@in_vchAttribute4,'') + '''
	AND ISNULL(pickDT.attribute5,'''') = ''' + ISNULL(@in_vchAttribute5,'') + ''''

	--------------------------------------------------
	-- ตรวจสอบว่ามีรายการใน Plan หรือไม่
	-- จำนวนคงเหลือใน plan ที่สามารถหยิบได้
	--------------------------------------------------
	SET @DynamicSQL = 'SELECT @v_fltSumPlanRemainPick = SUM(pickDT.quantity_plan) - SUM(pickDT.quantity_pick)
		,@v_nCount = count(pickDT.outbound_pick_detail_id) 
	FROM t_wms_outbound_master obMS
	LEFT JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id'
	
	SET @ParameterDefinition = '@v_fltSumPlanRemainPick FLOAT OUTPUT, @v_nCount INT OUTPUT';
	SET @DynamicSQL =  @DynamicSQL + @ConditionSQL
	EXEC sp_executesql @DynamicSQL, @ParameterDefinition,@v_fltSumPlanRemainPick output, @v_nCount output
	
	--------------------------------------------------
	-- ถ้าไม่พบ Recode ใน PickList แสดงว่าข้อมูลผิด
	--------------------------------------------------
	IF @v_nCount = 0
		BEGIN
			-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
			SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศุนย์ >> ERROR
	--------------------------------------------------
	IF ROUND(@v_fltSumPlanRemainPick,@Round) = 0
		BEGIN
			-- รายการสินค้า [] หยิบครบแล้ว
			SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItem,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- ถ้าจำนวนที่หยิบ มากกว่า จำนวนคงเหลือที่สามารถหยิบได้ >> ERROR
	--------------------------------------------------
	IF (ROUND(@v_fltConversionQuantity,@Round) > ROUND(@v_fltSumPlanRemainPick,@Round))
		BEGIN
			-- รายการสินค้า [] ไม่สามารถหยิบเกินได้
			SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			RETURN;
		END

	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้ทั้งหมด (รวมทุก Order ใน Load)
	-------------------------------------------------
	IF (ROUND(@v_fltSumPlanRemainPick,@Round) > ROUND(@v_fltInvQty,@Round))
		BEGIN 
			SET @v_fltSumQtyCanPick = ROUND(@v_fltInvQty,@Round)
		END
	ELSE
		BEGIN 
			SET @v_fltSumQtyCanPick = ROUND(@v_fltSumPlanRemainPick,@Round)
		END
	
	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้จริง กับจำนวนหยิบจริง
	-- Check จำนวนที่ Key จำนวนจำนวนที่สามารถหยิบได้จริง
	-------------------------------------------------
	IF (ROUND(@v_fltSumQtyCanPick,@Round) > ROUND(@v_fltConversionQuantity,@Round))
		BEGIN 
			SET @v_fltSumQtyCanPick = ROUND(@v_fltConversionQuantity,@Round)
		END
	
	------------------------------------------------------------
	-- SET pick_to_lpn
	-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
	------------------------------------------------------------
	SELECT @v_fltInvQtyForCheck = quantity FROM t_wms_inventory WHERE inventory_id = @v_vchInventoryID
	IF (@v_fltConversionQuantity = @v_fltInvQtyForCheck AND ISNULL(@in_vchFromLPN,'') <> '')
		BEGIN
			SET @v_vchPickToLPN = @in_vchFromLPN
		END
	ELSE
		BEGIN
			SET @v_vchPickToLPN = @in_vchToLPN
		END
	
	
BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;

	-------------------------------------------------
	-- Generate Pick Detail
	-- เอาเฉพาะรายการของ outbound detail ที่ยังหยิบไม่ครบ
	-------------------------------------------------
	SET @DynamicSQL = 'SELECT obMS.outbound_order_master_id
		, obMS.outbound_order_number
		, obMS.order_type
		, pickMS.outbound_pick_master_id
		, pickDT.outbound_order_detail_id
		, pickDT.outbound_pick_detail_id
		, obDT.line_number
		, pickDT.pick_line_number
		, pickDT.quantity_plan
		, pickDT.quantity_pick
		, obDT.item_uom_id
		, obDT.default_item_status
	FROM t_wms_outbound_master obMS
	LEFT JOIN t_wms_outbound_detail obDT on obMS.outbound_order_master_id = obDT.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
												AND obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id'

	SET @ConditionSQL = @ConditionSQL + ' AND  pickDT.quantity_plan <> pickDT.quantity_pick '
	SET @DynamicSQL = @DynamicSQL + @ConditionSQL

	SET @DynamicSQL = '	SET @OBDetail_CURSOR = CURSOR FOR ' + @DynamicSQL + '; OPEN @OBDetail_CURSOR'
	EXEC sp_executesql @DynamicSQL, N'@OBDetail_CURSOR CURSOR OUTPUT', @OBDetail_CURSOR OUTPUT
	FETCH NEXT FROM @OBDetail_CURSOR INTO @v_vchOutboundOrderMasterID, @v_vchOutboundOrderNumber, @v_vchOrderType, @v_vchOutboundPickMasterID, @v_vchOutboundDetailID, @v_vchOutboundPickDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_vchItemUomID,@v_vchDefaultItemStatus
		
		WHILE @@FETCH_STATUS = 0
		BEGIN

			DECLARE @v_fltQtyCanPick		FLOAT,
					@v_fltRemainQtyCanPick	FLOAT,
					@v_fltQtyPick			FLOAT

					-------------------------------------------------------
					-- Check Rule Auto Stg
					-- [MOD CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP
					-------------------------------------------------------
					SELECT @v_vchPickAndSTG = VALUE FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'

					------------------------------------------------------------
					-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ
					------------------------------------------------------------
					IF (ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round) > ROUND(@v_fltSumQtyCanPick,@Round))
						SET @v_fltQtyCanPick = ROUND(@v_fltSumQtyCanPick,@Round)
					ELSE
						SET @v_fltQtyCanPick = ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round)
		
					---------------------------------------------------------------
					-- สำหรับใช้กรณีของ Serial เนื่องจากต้องมีการ วน serail case all 
					-- โดยที่ @v_fltQtyCanPick ยังต้องคงค่าไว้ เพื่อจะได้รู้ว่า เหลือจำนวนเท่าไหร่ที่ต้องวน
					---------------------------------------------------------------
					SET @v_fltRemainQtyCanPick = ROUND(@v_fltQtyCanPick,@Round)
					SET @v_fltQtyPick = ROUND(@v_fltQtyCanPick,@Round)

					--------------------------------------------------
					-- Inventory รายการของสินค้าจากที่หยิบมา
					--------------------------------------------------
					DECLARE @v_vchInvID				VARCHAR(40)	 =NULL,
							@v_vchInvAttrGroupID	VARCHAR(40)	 =NULL,
							@v_vchInvReceiveDate	DATE		 =NULL,
							@v_vchInvStatusID		VARCHAR(40)	 =NULL,
							@v_vchInvstatus			NVARCHAR(50) =NULL,
							@v_vchInvSerialNumber	NVARCHAR(100)=NULL,
							@v_vchInvOwner			NVARCHAR(40) =NULL,
							@v_fltInvQuantity		FLOAT

					SET @DynamicSQL = ''
					SET @ConditionSQL = ''
					SET @DynamicSQL = 'SELECT inventory_id
						,attribute_group_id
						,receive_date
						,owner_code
						,inventory_status_id
						,inv_status
						,serial_number
						,quantity'
		
					SET @ConditionSQL = ' WHERE wh_master_id = ''' + @v_vchWhMasterID + '''
						AND location_id = ''' + @v_vchLocationID + '''
						AND wh_item_master_id = ''' + @v_vchWhItemMasterID + '''
						AND inv_status = '''+ @v_vchDefaultItemStatus +'''
						AND ISNULL(parent_lpn,'''') = ''' + ISNULL(@in_vchFromParentLPN,'') + '''	
						AND ISNULL(lpn,'''') = ''' + ISNULL(@in_vchFromLPN,'') + '''		
						AND ISNULL(lot_number,'''') = ''' + ISNULL(@in_vchLot,'') + '''	
						AND ISNULL(expiry_date,'''') = ''' + ISNULL(@in_vchExpiryDate,'') + '''
						AND ISNULL(attribute1,'''') = ''' + ISNULL(@in_vchAttribute1,'') + '''
						AND ISNULL(attribute2,'''') = ''' + ISNULL(@in_vchAttribute2,'') + '''
						AND ISNULL(attribute3,'''') = ''' + ISNULL(@in_vchAttribute3,'') + '''
						AND ISNULL(attribute4,'''') = ''' + ISNULL(@in_vchAttribute4,'') + '''
						AND ISNULL(attribute5,'''') = ''' + ISNULL(@in_vchAttribute5,'') + ''''

					IF @v_vchSNControl = 'FULL'
						BEGIN
							SET @DynamicSQL = @DynamicSQL + ' FROM v_wms_inventory_data_by_serial'
							IF @in_vchSerialNo <> 'ALL'
							BEGIN
								SET @ConditionSQL = @ConditionSQL + ' AND ISNULL(serial_number,'''') = ''' + ISNULL(@in_vchSerialNo,'') + ''''
							END
						END
					ELSE
						BEGIN
							SET @DynamicSQL = @DynamicSQL + ' FROM v_wms_inventory_data'
						END

					SET @ConditionSQL = @ConditionSQL + ' ORDER BY serial_number'
					SET @DynamicSQL = @DynamicSQL + @ConditionSQL
					SET @DynamicSQL = '	SET @Inventory_CURSOR = CURSOR FOR ' + @DynamicSQL + '; OPEN @Inventory_CURSOR'
					EXEC sp_executesql @DynamicSQL, N'@Inventory_CURSOR CURSOR OUTPUT', @Inventory_CURSOR OUTPUT
					FETCH NEXT FROM @Inventory_CURSOR INTO @v_vchInvID, @v_vchInvAttrGroupID,@v_vchInvReceiveDate,@v_vchInvOwner,@v_vchInvStatusID,@v_vchInvstatus,@v_vchInvSerialNumber,@v_fltInvQuantity
					WHILE @@FETCH_STATUS = 0
						BEGIN
							-----------------------------------------------------
							-- Validate Duplicate Serial Number ใน Pick Detail
							-----------------------------------------------------
							IF (@v_vchSNControl = 'FULL')
								BEGIN
									SET @v_fltQtyPick = 1   -- กรณีของ Serial Qty Pick = 1
									
									IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
											  WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
											  AND serial_number = @v_vchInvSerialNumber)
										BEGIN
											SET @out_ErrorCode = '435';
											SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SERIAL_IS_PICK_COMPLETE',@v_vchLocalID,@in_vchItem,@v_vchInvSerialNumber,'@param3','@param4','@param5')
											GOTO WRITE_PROC;
										END
								END

							-------------------------------------------------------------------
							-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP กำหนดจาก Rule
							-------------------------------------------------------------------
							IF (@v_vchPickAndSTG = 'YES')
								BEGIN
									-----------------------------------------------------------------
									-- ถ้า CBD: Order Type = PC to WIP กำหนดให้ Pick แล้ววาง STG Location เลย
									-- Get New Staging location id
									-----------------------------------------------------------------
									SELECT TOP 1 @v_vchStagingLocationID = location_id  
										, @v_vchStagingLocation = location
									FROM t_wms_location 
									WHERE wh_master_id = @v_vchWhMasterID 
									AND loc_type = 'STG'

									------------------------------------------------------------------
									-- Check Old STG = New STG : OUTBOUND ORDER 1 STAGING LOCATION
									------------------------------------------------------------------
									SELECT TOP 1 @v_vchOldStagingLocationID = staging_location_id FROM t_wms_outbound_pick_detail 
									WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
									AND (staging_location_id <> @v_vchStagingLocationID AND staging_location_id IS NOT NULL)

									IF (@v_vchOldStagingLocationID IS NOT NULL)
										BEGIN
											IF (@v_vchOldStagingLocationID <> @v_vchStagingLocationID)
												BEGIN
													SELECT @v_vchOldStagingLocation = location from t_wms_location where location_id = @v_vchOldStagingLocationID
													SET @out_ErrorCode = '999';
													SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PICK_TO_OLD_STAGING',@v_vchLocalID,@v_vchOldStagingLocation,'@param2','@param3','@param4','@param5')
													GOTO WRITE_PROC;
												END
										END
									ELSE
										BEGIN
											IF (@v_vchStagingLocationID is null)
												BEGIN
													SET @out_ErrorCode = '904';
													SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',@v_vchLocalID,@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
													GOTO WRITE_PROC
												END
										END

									----------------------------------------
									--SET Value Staging
									----------------------------------------
									SET @v_fltQuantityStage = ROUND(@v_fltQtyPick,@Round)
									SET @v_vchStagingParentLPN = @in_vchToParentLPN
									SET @v_vchStagingLPN = @v_vchPickToLPN


									----------------------------------------------------------------
									-- แบบวาง STG Auto
									-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP
									----------------------------------------------------------------
									UPDATE t_wms_outbound_pick_detail SET 
										 quantity_pick		 = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltQtyPick,@Round),@Round)
										, quantity_stage	 = ROUND(ROUND(ISNULL(quantity_stage,0),@Round) + ROUND(@v_fltQuantityStage,@Round),@Round)
										, pick_location_id   = @v_vchForkID
										, pick_to_parent_lpn = @in_vchToParentLPN
										, pick_to_lpn		 = @v_vchPickToLPN
										, staging_location_id = @v_vchStagingLocationID
										, staging_parent_lpn = @v_vchStagingParentLPN
										, staging_lpn		 = @v_vchStagingLPN 
										, pick_status        = 'YES'
										, start_date_time	 = ISNULL(start_date_time,GETDATE())
										, end_date_time		 = GETDATE()
										, serial_number		 = @v_vchInvSerialNumber
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
								END
							ELSE
								BEGIN
									SET @v_vchStagingLocationID = NULL
									SET @v_vchStagingLocation = NULL
									SET @v_fltQuantityStage = 0	
									SET @v_vchStagingParentLPN = NULL	
									SET @v_vchStagingLPN = NULL

									-----------------------------------------------
									-- แบบปกติ ไม่ต้องวาง STG
									-----------------------------------------------
									UPDATE t_wms_outbound_pick_detail SET 
										  quantity_pick		 = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltQtyPick,@Round),@Round)
										, pick_location_id   = @v_vchForkID
										, pick_to_parent_lpn = @in_vchToParentLPN
										, pick_to_lpn		 = @v_vchPickToLPN
										, pick_status        = 'YES'
										, start_date_time	 = ISNULL(start_date_time,GETDATE())
										, end_date_time		 = GETDATE()
										, serial_number		 = @v_vchInvSerialNumber
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
								END


							---------------------------------------------------
							-- Insert/Update Pack Detail
							---------------------------------------------------
							IF (@RulePickPack = 'YES')
								BEGIN
									UPDATE t_wms_outbound_pick_detail SET 
										  quantity_pack = ROUND(ROUND(ISNULL(quantity_pack,0),@Round) + ROUND(@v_fltQtyPick,@Round),@Round)
										, end_date_time = GETDATE()
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

									---------------------------------------------------
									--Insert/Update Pack Detail
									---------------------------------------------------
									PRINT 'Pick and Pack'
									IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
														WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
														AND pack_location_id = @v_vchForkID
														AND lpn_pack = @v_vchPickToLPN 
														AND wh_item_master_id = @v_vchWhItemMasterID 
														AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
										BEGIN
											UPDATE t_wms_outbound_pack_detail SET 
												 quantity_pack = ROUND(ROUND(quantity_pack,@Round) + ROUND(@v_fltQtyPick,@Round),@Round)
												,quantity_stage = ROUND(ROUND(quantity_stage,@Round) + ROUND(@v_fltQuantityStage,@Round),@Round)
											WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID 
											AND pack_location_id = @v_vchForkID
											AND lpn_pack = @v_vchPickToLPN 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
											AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
										END
									ELSE
										BEGIN
											INSERT INTO t_wms_outbound_pack_detail
												(outbound_order_master_id
												, outbound_pick_detail_id
												, lpn_pack
												, pack_location_id
												, wh_item_master_id
												, quantity_pack
												, quantity_stage
												, lot_number
												, expiry_date
												, serial_number
												, [attribute1]
											    , [attribute2]
											    , [attribute3]
											    , [attribute4]
											    , [attribute5]
												, item_uom_id
												, [staging_location_id]
											    , [staging_parent_lpn]
											    , [staging_lpn]
												, create_by)
											VALUES
												(@v_vchOutboundOrderMasterID
												, @v_vchOutboundPickDetailID
												, @v_vchPickToLPN
												, @v_vchForkID
												, @v_vchWhItemMasterID
												, ROUND(@v_fltQtyPick,@Round)
												, @v_fltQuantityStage
												, @in_vchLot
												, @in_vchExpiryDate
												, @v_vchInvSerialNumber
												, @in_vchAttribute1
												, @in_vchAttribute2
												, @in_vchAttribute3
												, @in_vchAttribute4
												, @in_vchAttribute5
												, @v_vchItemUOMID
												, @v_vchStagingLocationID
												, @v_vchStagingParentLPN
												, @v_vchStagingLPN
												, @in_vchUserID)
										END
								END

							---------------------------------------------------
							-- Manage source location data
							---------------------------------------------------
							UPDATE t_wms_inventory SET
								 quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQtyPick,@Round),@Round)
								,quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) - ROUND(@v_fltQtyPick,@Round),@Round)
							WHERE inventory_id = @v_vchInvID 
							AND attribute_group_id = @v_vchInvAttrGroupID

							IF (@v_vchSNControl = 'FULL')
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQtyPick,@Round),@Round) 
									WHERE inventory_id = @v_vchInvID 
									AND attribute_group_id = @v_vchInvAttrGroupID 
									AND attribute_value = @v_vchInvSerialNumber
								END
							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(ROUND(quantity,@Round) - ROUND(@v_fltQtyPick,@Round),@Round)
										,quantity_allocated = ROUND(ROUND(quantity_allocated,@Round) - ROUND(@v_fltQtyPick,@Round),@Round)
									WHERE inventory_id = @v_vchInvID 
									AND attribute_group_id = @v_vchInvAttrGroupID
									AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END

							---------------------------------------------------
							-- Manage destination location data
							---------------------------------------------------			
							BEGIN
								SET @v_vchInventoryID = null;
								SET @v_vchInvAttrGroupID = null;
								--SET @v_fltInvQuantity = 0;
								IF (@v_vchPickAndSTG = 'YES')
									BEGIN
										--แบบวาง STG
										SELECT	@v_vchInventoryID = inventory_id
												,@v_vchInvAttrGroupID = attribute_group_id
											  --,@v_fltInvQuantity = quantity
										FROM v_wms_inventory_data
										WHERE wh_master_id = @v_vchWhMasterID 
										AND wh_item_master_id = @v_vchWhItemMasterID 
										AND location_id = @v_vchStagingLocationID
										AND ISNULL(parent_lpn,'') = ISNULL(@v_vchStagingParentLPN,'') 
										AND ISNULL(lpn,'') = ISNULL(@v_vchStagingLPN,'')
										AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
										AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
										AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
										AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
										AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
										AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
										AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
							
										EXEC usp_manage_inventory
											 @in_vchApplicationID			= @in_vchApplicationID
											,@in_vchWarehouseMasterID		= @v_vchWhMasterID
											,@in_vchWarehouseItemMasterID	= @v_vchWhItemMasterID
											,@in_vchLocationID				= @v_vchStagingLocationID	--STG Or Fork [Mod FOR CBD order type RW to WIP]
											,@in_vchLocation				= @v_vchStagingLocation		--STG Or Fork [Mod FOR CBD order type RW to WIP]
											,@in_vchStatusID				= @v_vchInvStatusID
											,@in_vchLPN						= @v_vchStagingLPN			--STG Or Fork [Mod FOR CBD order type RW to WIP]
											,@in_vchLotNumber				= @in_vchLot
											,@in_vchExpiryDate				= @in_vchExpiryDate
											,@in_vchSerialNumber			= @v_vchInvSerialNumber
											,@in_fltQty						= @v_fltQtyPick
											,@in_fltQtyAllocate				= 0
											,@in_fltQtyIncoming				= 0
											,@in_vchOwner					= @v_vchInvOwner
											,@in_vchInventoryType			= @v_vchOutboundOrderNumber
											,@in_vchPalentLPN				= @v_vchStagingParentLPN	--STG Or Fork [Mod FOR CBD order type RW to WIP]
											,@in_vchUserID					= @in_vchUserID
											,@in_vchReceiveDate				= @v_vchInvReceiveDate
											,@in_vchInventoryID				= @v_vchInventoryID		OUTPUT
											,@in_vchAttributeGroupID		= @v_vchInvAttrGroupID	OUTPUT
											,@in_vchErrorCode				= @out_ErrorCode		OUTPUT
											,@in_vchMessage					= @out_ErrorMessage		OUTPUT
									END
								ELSE
									BEGIN
										-- แบบปกติ ไม่ต้องวาง STG	
										SELECT	@v_vchInventoryID = inventory_id
												,@v_vchInvAttrGroupID = attribute_group_id
											  --,@v_fltInvQuantity = quantity
										FROM v_wms_inventory_data
										WHERE wh_master_id = @v_vchWhMasterID 
										AND wh_item_master_id = @v_vchWhItemMasterID 
										AND location_id = @v_vchForkID
										AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'') 
										AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
										AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
										AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
										AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
										AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
										AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
										AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
										AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

										EXEC usp_manage_inventory
											 @in_vchApplicationID			= @in_vchApplicationID
											,@in_vchWarehouseMasterID		= @v_vchWhMasterID
											,@in_vchWarehouseItemMasterID	= @v_vchWhItemMasterID
											,@in_vchLocationID				= @v_vchForkID
											,@in_vchLocation				= @in_vchForkLift
											,@in_vchStatusID				= @v_vchInvStatusID
											,@in_vchLPN						= @v_vchPickToLPN
											,@in_vchLotNumber				= @in_vchLot
											,@in_vchExpiryDate				= @in_vchExpiryDate
											,@in_vchSerialNumber			= @v_vchInvSerialNumber
											,@in_fltQty						= @v_fltQtyPick
											,@in_fltQtyAllocate				= 0
											,@in_fltQtyIncoming				= 0
											,@in_vchOwner					= @v_vchInvOwner
											,@in_vchInventoryType			= @v_vchOutboundOrderNumber
											,@in_vchPalentLPN				= @in_vchFromParentLPN
											,@in_vchUserID					= @in_vchUserID
											,@in_vchReceiveDate				= @v_vchInvReceiveDate
											,@in_vchInventoryID				= @v_vchInventoryID		OUTPUT
											,@in_vchAttributeGroupID		= @v_vchInvAttrGroupID	OUTPUT
											,@in_vchErrorCode				= @out_ErrorCode		OUTPUT
											,@in_vchMessage					= @out_ErrorMessage		OUTPUT
									END
					
								IF (@out_ErrorCode <> '0')
									GOTO WRITE_PROC;
							
								IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN
										EXEC usp_manage_inventory_attribute
											 @in_vchApplicationID		= @in_vchApplicationID
											,@in_vchItem				= @in_vchItem
											,@in_vchSerialNo			= @v_vchInvSerialNumber
											,@in_vchLot					= @in_vchLot
											,@in_vchExpiryDate			= @in_vchExpiryDate
											,@in_vchAttribute1			= @in_vchAttribute1
											,@in_vchAttribute2			= @in_vchAttribute2
											,@in_vchAttribute3			= @in_vchAttribute3
											,@in_vchAttribute4			= @in_vchAttribute4
											,@in_vchAttribute5			= @in_vchAttribute5
											,@in_fltQty					= @v_fltQtyPick
											,@in_fltQtyAllocate			= 0
											,@in_fltQtyIncoming			= 0
											,@in_vchInventoryID			= @v_vchInventoryID
											,@in_vchAttributeGroupID	= @v_vchInvAttrGroupID
											,@in_vchLotControl			= @v_vchLotControl
											,@in_vchSNControl			= @v_vchSNControl
											,@in_vchExpiryDateControl	= @v_vchExpControl
											,@in_vchAttribute1Control	= @v_vchAttribute1Control
											,@in_vchAttribute2Control	= @v_vchAttribute2Control
											,@in_vchAttribute3Control	= @v_vchAttribute3Control
											,@in_vchAttribute4Control	= @v_vchAttribute4Control
											,@in_vchAttribute5Control	= @v_vchAttribute5Control
											,@in_vchUserID				= @in_vchUserID
											,@in_vchErrorCode			= @out_ErrorCode	OUTPUT
											,@in_vchMessage				= @out_ErrorMessage	OUTPUT			
										IF(@out_ErrorCode <> '0')
											GOTO WRITE_PROC;
									END
							END
				
							---------------------------------------------------		
							-- Write Tran Log OO_PICK
							---------------------------------------------------		
							INSERT INTO t_com_tran_log
							(     app_id
								, tran_type
								, sub_tran_type
								, [app_name]
								, [description]
								, start_tran_datetime
								, end_tran_datetime
								, warehouse
								, to_warehouse
								, location
								, to_location
								, [owner]
								, to_owner
								, item_number
								, quantity
								, quantity_uom
								, after_quantity
								, after_quantity_uom
								, lot_number
								, after_lot_number
								, [expiry_date]
								, after_expiry_date
								, serial_number
								, [attribute1]
							    , [after_attribute1]
							    , [attribute2]
							    , [after_attribute2]
							    , [attribute3]
							    , [after_attribute3]
							    , [attribute4]
							    , [after_attribute4]
							    , [attribute5]
							    , [after_attribute5]
								, [user_id]
								, reference_number
								, control_number
								, parent_lpn
								, after_parent_lpn
								, lpn
								, after_lpn
								, [status]
								, after_status
								, zone
								, order_number
								, line_number
								, udf_1
								, udf_2
								, device
								, create_by
							)
							VALUES
							(     @in_vchApplicationID
								, 'OO_PICK'
								, 'SALES_ORDER'
								, null
								, 'System Directed Pick Load'
								, GETDATE()
								, GETDATE()
								, @in_vchWarehouse
								, @in_vchWarehouse
								, @in_vchFromLocation
								, @in_vchForkLift
								, @v_vchOwnerCode
								, @v_vchOwnerCode
								, @in_vchItem
								, ROUND(@v_fltQtyPick,@Round)
								, @in_vchUOMPrompt
								, ROUND((@v_fltInvQuantity - @v_fltQtyPick),@Round)
								, @in_vchUOMPrompt
								, @in_vchLot
								, @in_vchLot
								, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
								, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
								, @v_vchInvSerialNumber
								, @in_vchAttribute1
								, @in_vchAttribute1
								, @in_vchAttribute2
								, @in_vchAttribute2
								, @in_vchAttribute3
								, @in_vchAttribute3
								, @in_vchAttribute4
								, @in_vchAttribute4
								, @in_vchAttribute5
								, @in_vchAttribute5
								, @in_vchUserID
								, null
								, null
								, @in_vchToParentLPN
								, @in_vchFromParentLPN
								, @in_vchFromLPN
								, @v_vchPickToLPN
								, @v_vchInvstatus
								, @v_vchInvstatus
								, null
								, @in_vchLoadID
								, @v_vchPickLineNumber
								, @v_vchOutboundOrderNumber
								, @v_vchOrderType
								, @in_vchDeviceID
								, @in_vchUserID
							)

							---------------------------------------------------		
							-- Write Tran Log INV_MOVE TO Staging
							---------------------------------------------------		
							IF (@v_vchPickAndSTG = 'YES')
							BEGIN
								INSERT INTO t_com_tran_log
									( app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id]
									, reference_number
									, control_number
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status
									, zone
									, order_number
									, line_number
									, udf_1
									, udf_2
									, device
									, create_by
								)
								VALUES
								(     @in_vchApplicationID
									, 'INV_MOVE'
									, 'MOVE_DEST'
									, NULL
									, 'Update pick to staging - System pick load [Auto to Staging]'
									, DATEADD(millisecond,2,GETDATE())
									, DATEADD(millisecond,2,GETDATE())
									, @in_vchWarehouse
									, @in_vchWarehouse
									, @in_vchForkLift
									, @v_vchStagingLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @in_vchItem
									, ROUND(@v_fltQtyPick,@Round)
									, @in_vchUOMPrompt
									, ROUND(@v_fltQtyPick,@Round)
									, @in_vchUOMPrompt
									, @in_vchLot
									, @in_vchLot
									, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
									, (CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
									, @v_vchInvSerialNumber
									, @in_vchAttribute1
									, @in_vchAttribute1
									, @in_vchAttribute2
									, @in_vchAttribute2
									, @in_vchAttribute3
									, @in_vchAttribute3
									, @in_vchAttribute4
									, @in_vchAttribute4
									, @in_vchAttribute5
									, @in_vchAttribute5
									, @in_vchUserID
									, NULL
									, NULL
									, @in_vchFromParentLPN
									, @in_vchToParentLPN
									, @in_vchFromLPN
									, @v_vchPickToLPN
									, @v_vchInvstatus
									, @v_vchInvstatus
									, NULL
									, @in_vchLoadID
									, @v_vchPickLineNumber
									, @v_vchOutboundOrderNumber
									, @v_vchOrderType
									, @in_vchDeviceID
									, @in_vchUserID
								)
							END

							--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
							SET @v_fltRemainQtyCanPick = ROUND((@v_fltRemainQtyCanPick - @v_fltQtyPick),@Round)

							--สำหรับใช้ในการ Write Log เพื่อ update after_quantity
							SET @v_fltInvQtyForCheck = ROUND((@v_fltInvQtyForCheck - @v_fltQtyPick),@Round)

							--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
							IF @v_fltRemainQtyCanPick = 0
								break;

							FETCH NEXT FROM @Inventory_CURSOR INTO @v_vchInvID, @v_vchInvAttrGroupID,@v_vchInvReceiveDate,@v_vchInvOwner,@v_vchInvStatusID,@v_vchInvstatus,@v_vchInvSerialNumber,@v_fltInvQuantity
						END
		
					CLOSE @Inventory_CURSOR
					DEALLOCATE @Inventory_CURSOR


					--Update Outbound Detail
					UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ROUND(ISNULL(quantity_pick,0),@Round) + ROUND(@v_fltQtyCanPick,@Round),@Round)
						,item_status = 'PICK'
					WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID 
					AND outbound_order_detail_id = @v_vchOutboundDetailID 
					AND wh_item_master_id = @v_vchWhItemMasterID 
					AND line_number = @v_vchLineNumber


					-- Update Outbound Master
					IF ((SELECT SUM(quantity_order) - SUM(quantity_pick) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID) = 0)
						BEGIN
							UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID AND order_status NOT IN ('LOADING','LOADED')
						END
					ELSE
						BEGIN
							UPDATE t_wms_outbound_master SET order_status = 'PICK' WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
						END

					---------------------------------------------------------
					-- Mod for CBD
					-- Auto Create Inbound Plan and Receipt Item
					---------------------------------------------------------
					EXEC usp_inbound_insert_order @in_vchApplicationID		     = @in_vchApplicationID
													,@in_vchDeviceID			 = @in_vchDeviceID	
													,@in_vchUserID				 = @in_vchUserID	
													,@in_vchWhMasterID			 = @v_vchWhMasterID
													,@in_vchOrderNumber			 = @v_vchOutboundOrderNumber
													,@in_vchLocation			 = @in_vchFromLocation
													,@in_vchParentLPN			 = @in_vchToParentLPN
													,@in_vchLPN					 = @in_vchToLPN
													,@in_vchItemNumber			 = @in_vchItem
													,@in_vchLotNumber			 = @in_vchLot
													,@in_vchExpiryDate			 = @in_vchExpiryDate
													,@in_vchSerialNumber		 = @in_vchSerialNo
													,@in_fltQuantity			 = @in_fltQty	
													,@in_vchUOMPrompt			 = @in_vchUOMPrompt
													,@in_vchDefaultItemStatus	 = @v_vchDefaultItemStatus
													,@in_vchAttribute1			 = @in_vchAttribute1
													,@in_vchAttribute2			 = @in_vchAttribute2
													,@in_vchAttribute3			 = @in_vchAttribute3
													,@in_vchAttribute4			 = @in_vchAttribute4
													,@in_vchAttribute5			 = @in_vchAttribute5
													,@out_vchErrorCode			 = @out_ErrorCode	 OUTPUT
													,@out_vchErrorMsg			 = @out_ErrorMessage OUTPUT
					IF (@out_ErrorCode <> 0)
						BEGIN
							GOTO WRITE_PROC;
						END

					-------------------------------------------------------------------------------
					-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
					-------------------------------------------------------------------------------
					SET @v_fltSumQtyCanPick = ROUND((@v_fltSumQtyCanPick - @v_fltQtyCanPick),@Round)
					IF @v_fltSumQtyCanPick = 0
						BREAK;

					------------------------------------------------
					-- Clear Inventory ที่หยิบของหมดแล้ว
					------------------------------------------------
					DELETE FROM t_wms_inventory WHERE quantity <= 0 
					DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 

			FETCH NEXT FROM @OBDetail_CURSOR INTO @v_vchOutboundOrderMasterID, @v_vchOutboundOrderNumber, @v_vchOrderType, @v_vchOutboundPickMasterID, @v_vchOutboundDetailID, @v_vchOutboundPickDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_vchItemUomID,@v_vchDefaultItemStatus
		END
	CLOSE @OBDetail_CURSOR
	DEALLOCATE @OBDetail_CURSOR
	
	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
			
		DECLARE @c_vchObjName			NVARCHAR(30) = '[usp_outbound_generate_user_pick_by_order]', -- The name that uniquely tags this object.
				@v_vchProcessData1		NVARCHAR(1000),
				@v_vchProcessData2		NVARCHAR(1000),
				@v_vchProcessData3		NVARCHAR(1000),
				@v_vchProcessData4		NVARCHAR(1000),
				@v_dtProcessDateTime	DATETIME

		SET @v_vchProcessData1 = @out_ErrorCode
		SET @v_vchProcessData2 = @out_ErrorMessage;
		SET @v_dtProcessDateTime = getdate();

		IF CURSOR_STATUS('global','@OBDetail_CURSOR') >= -1
			BEGIN
				CLOSE @OBDetail_CURSOR;
				DEALLOCATE @OBDetail_CURSOR;
			END

		IF CURSOR_STATUS('global','@Inventory_CURSOR') >= -1
			BEGIN
				CLOSE @Inventory_CURSOR;
				DEALLOCATE @Inventory_CURSOR;
			End

		SET @v_vchProcessData2 = 'Item number ' + @in_vchItem;
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @in_vchLoadID,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;

	IF CURSOR_STATUS('global','@OBDetail_CURSOR') >= -1
		BEGIN
			CLOSE @OBDetail_CURSOR;
			DEALLOCATE @OBDetail_CURSOR;
		END

	IF CURSOR_STATUS('global','@Inventory_CURSOR') >= -1
		BEGIN
			CLOSE @Inventory_CURSOR;
			DEALLOCATE @Inventory_CURSOR;
		End

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END		
END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_item_by_kitting]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-02-26
-- Description:	Outbound pick item by kitting
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_update_pick_item_by_kitting]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(10),
	@in_vchProductionOrder	NVARCHAR(40),
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchForkLift			NVARCHAR(50),
	@in_vchItem				NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(10),
	@in_vchFromParentLPN	NVARCHAR(25) = null,
	@in_vchFromLPN			NVARCHAR(25) = null,
	@in_vchToParentLPN		NVARCHAR(25) = null,
	@in_vchToLPN			NVARCHAR(25) = null,
	@in_vchLot				NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNo			NVARCHAR(50) = null,
	@in_vchOverPickReason	NVARCHAR(20) = null,
	@in_vchFGLot			NVARCHAR(50) = null,
	@out_ErrorCode			NVARCHAR(200) output,
	@out_ErrorMessage		NVARCHAR(500) output
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
		-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_update_pick_item_by_kitting]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
    
		@v_vchOutboundOrderMasterID	VARCHAR(40),
		@v_vchOutboundOrderDetailID	VARCHAR(40),
		@v_vchOutboundPickMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	NVARCHAR(40),
		@v_vchOutboundPackDetailID	NVARCHAR(40),
		@v_vchWarehouseMasterID		NVARCHAR(40),
		@v_vchWarehouseItemMasterID	VARCHAR(40),
		@v_vchOutboundWarehouseItemMasterID	VARCHAR(40),
		@v_vchFLocationMasterID		NVARCHAR(40),
		@v_vchTLocationMasterID		NVARCHAR(40),
		@v_vchItemMasterID			VARCHAR(40),
		@v_vchLineNumber			NVARCHAR(10),
		@v_vhcUOMID					VARCHAR(40),
		@v_vchItemUOMID				VARCHAR(40),
		@v_vchUOMPrompt				NVARCHAR(50),
		@Round						INT,
		@v_fltQuantity				FLOAT,
		@v_fltQuantityRemainPick	FLOAT,
		@v_vchOrderStatus			NVARCHAR(10),
		@v_vchOverPick				NVARCHAR(3),
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchMixItem				NVARCHAR(3),
		@v_vchMixLot				NVARCHAR(3),
		@v_vchMixOwner				NVARCHAR(3),
		@v_vchMixExpiryDate			NVARCHAR(3),
		@v_vchLPNControl			NVARCHAR(5),
		@v_vchReceiveDate			DATE,
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_fltSStockQuantity		FLOAT = 0,
		@v_fltDStockQuantity		FLOAT = 0,
		@v_fltBaseQuantity			FLOAT,
		@v_vchInventoryType			NVARCHAR(25) = @in_vchProductionOrder,
		@v_vchDubLocation			NVARCHAR(50),
		@v_vchDubParentLPN			NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchOverride				NVARCHAR(3),
		-- Add new 2013-11-06 outbound multiline
		@v_vchAllowMulltiLineItem	NVARCHAR(3) = 'NO',
		@v_fltQtyUpdate				FLOAT = 0,
		@v_fltSumQuantityOrder		FLOAT,
		@v_fltSumQuantityPick		FLOAT,

		-- add new 2014-01-08 case serial
		@v_vchPickPackAuto			NVARCHAR(3),
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(MAX) = '',
		@v_vchDynamicSQLCondition	NVARCHAR(MAX) = '',
		@v_vchSerialNumber			NVARCHAR(50),
		@v_curInventoryData			CURSOR,

		@v_vchItemCategoryID		VARCHAR(40),
		@v_vchItemCategory			NVARCHAR(50),
		@v_vchInboundOrderDetailID	VARCHAR(40),
		@v_vchFormulaItem			NVARCHAR(50),
		@v_vchFormulaItemID			VARCHAR(40),
		@v_vchPickLineNumber		NVARCHAR(10),
		@v_vchLine					NVARCHAR(10),
		@v_fltQuantityPack			FLOAT,
		@v_vchFGItemNumber			NVARCHAR(50)
   
	set @out_ErrorCode = '0';
	set @out_ErrorMessage = 'NO';
	select @Round = value from t_wms_rule where rule_code = 'RULE_DECIMAL_SCALE'

	Begin Try
		
		set @in_fltQty = round(@in_fltQty,@Round)

		select @v_vchWarehouseMasterID = wh_master_id from t_wms_wh where wh_id = @in_vchWarehouse
		select @v_vchFLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchFromLocation
		select @v_vchTLocationMasterID = location_id from t_wms_location where wh_master_id = @v_vchWarehouseMasterID and location = @in_vchForkLift
		
		select @v_vchOutboundOrderMasterID = outbound_order_master_id,@v_vchOrderStatus = order_status,@v_vchOwnerID = owner_id 
		from t_wms_outbound_master 
		where wh_master_id = @v_vchWarehouseMasterID and outbound_order_number = @in_vchProductionOrder

		select @v_vchOverPick = value from t_wms_rule where rule_code = 'RULE_OVER_PICK'
		-- Get Pick and pack auto
		select @v_vchPickPackAuto = value from t_wms_rule where rule_code = 'RULE_PICK_PACK'
		if (@v_vchPickPackAuto = 'NO')
			set @v_fltQuantityPack = 0;
		If(@v_vchOrderStatus = 'SHIP')
			Begin
				set @out_ErrorCode = '401';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchProductionOrder,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		
		-- Check item from t_wms_item, 885 and crossref	
		select	@in_vchItem = item_number,@v_vchItemMasterID = it.item_master_id,@v_vhcUOMID = iu.item_uom_id,
				@v_vchLotControl = lot_control,@v_vchExpiryDateControl = expiry_date_control,@v_vchSerialControl = sn_control,
				@v_vchItemCategory = item_category,@v_vchItemCategoryID = t_wms_category.category_id
		from	t_wms_item it left outer join t_wms_item_crossref ic on it.item_master_id = ic.item_master_id
				left outer join t_wms_item_uom iu on it.item_master_id = iu.item_master_id
				inner join t_wms_category on it.category_id = t_wms_category.category_id
		where	uom_prompt = @in_vchUOMPrompt and (item_number = @in_vchItem or dg_code = @in_vchItem 
				or alternate_item_number = @in_vchItem) and owner_id = @v_vchOwnerID
		If (isnull(@v_vchItemMasterID,'') = '')
			Begin
				set @out_ErrorCode = '403';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'ITEM_NUMBER_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End

		-- Get formular item
		Select top 1 @v_vchInboundOrderDetailID = inbound_order_detail_id, @v_vchFGItemNumber = item_number--@v_vchFormulaItemID = wh_item_master_id
		from v_wms_inbound_detail where inbound_order_number = @in_vchProductionOrder
		If (isnull(@v_vchInboundOrderDetailID,'') = '')
			Begin
				set @out_ErrorCode = '452';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_INBOUND_ORDER_PO',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End
		-- Get formula item from FG item
		select @v_vchFormulaItemID = wh_item_master_id 
		from t_wms_wh_item inner join t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id
		where wh_master_id = @v_vchWarehouseMasterID and item_number = @v_vchFGItemNumber
		If (@v_vchItemCategoryID in (
				select category_id
				from	t_wms_kit_master inner join t_wms_kit_detail on t_wms_kit_master.kit_master_id = t_wms_kit_detail.kit_master_id
						inner join t_wms_wh_item on t_wms_wh_item.wh_item_master_id = t_wms_kit_detail.wh_item_master_id
						inner join t_wms_item on t_wms_wh_item.item_master_id = t_wms_item.item_master_id 
				where	t_wms_kit_master.wh_master_id = @v_vchWarehouseMasterID and t_wms_kit_master.wh_item_master_id = @v_vchFormulaItemID))
			Begin
				set @out_ErrorCode = '451';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_PICK_ITEM_KITTING_FROM_PRODUCTION',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End

		-- Get outbound detail
		select	top 1 @v_vchOutboundOrderDetailID = outbound_order_detail_id,@v_vchItemUOMID = item_uom_id
		from	v_wms_outbound_detail
		where	outbound_order_master_id = @v_vchOutboundOrderMasterID and item_category = @v_vchItemCategory
		If (isnull(@v_vchOutboundOrderDetailID,'') = '')
			Begin
				set @out_ErrorCode = '452';
				select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'OUTBOUND_DETAIL_NOT_FOUND_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,'@param2','@param3','@param4','@param5')
				Goto WRITE_PROC;
			End

		-- Get Warehouse item id	
		select @v_vchWarehouseItemMasterID = wh_item_master_id from t_wms_wh_item where wh_master_id = @v_vchWarehouseMasterID and item_master_id = @v_vchItemMasterID

		If (@v_vhcUOMID <> @v_vchItemUOMID)
			Begin
				select @v_fltQuantity = @in_fltQty * conversion_factor from t_wms_item_uom where item_uom_id = @v_vhcUOMID

				select @v_fltQuantity = @v_fltQuantity / conversion_factor from t_wms_item_uom where item_uom_id = @v_vchItemUOMID
			End
		Else
			Begin
				set @v_fltQuantity = @in_fltQty;
			End

		If (isnull(@in_vchSerialNo,'') = 'ALL')
			set @in_fltQty = 1;

		-- check quantity from inventory for get lpn
		If ((select sum(quantity) from t_wms_inventory 
		where wh_master_id = @v_vchWarehouseMasterID and location_id = @v_vchFLocationMasterID and lpn = @in_vchFromLPN)
			=
			(select @in_fltQty * conversion_factor from t_wms_item_uom where item_uom_id = @v_vhcUOMID))
			Begin
				set @in_vchToLPN = @in_vchFromLPN;
			End

		set @v_vchDynamicSQL =
							'
							select	inventory_id,
									attribute_group_id,
									owner_code,
									quantity,
									receive_date,
									inventory_status_id,
									inv_status,
									serial_number
							';
		set @v_vchDynamicSQLCondition = 
							'	where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID
										and location_id = @v_vchFLocationMasterID
										and isnull(parent_lpn,'''') = isnull(@in_vchFromParentLPN,'''') and isnull(lpn,'''') = isnull(@in_vchFromLPN,'''') 
										and isnull(lot_number,'''') = isnull(@in_vchLot,'''') and isnull(expiry_date,'''') = isnull(@in_vchExpiryDate,'''')
							';		

		If (isnull(@in_vchSerialNo,'') = 'ALL')
			Begin--get inventory by all serial
				set @v_vchDynamicSQL += ' from	v_wms_inventory_data_by_serial ';
			End
		Else If (@v_vchSerialControl = 'FULL')
			Begin-- get inventory by serial
				set @v_vchDynamicSQL += ' from	v_wms_inventory_data_by_serial ';
				set @v_vchDynamicSQLCondition += 
							'
							and isnull(serial_number,'''') = isnull(@in_vchSerialNo,'''')
							';
			End
		ELse
			Begin-- get inventory none serial
				set @v_vchDynamicSQL += ' from	v_wms_inventory_data ';
			End
					
		Set @v_vchDynamicSQL = @v_vchDynamicSQL + @v_vchDynamicSQLCondition;
		Set @v_vchDynamicSQL = ' set @v_curInventoryData = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @v_curInventoryData';
		Set @v_vchParameterDefinition = '@v_vchWarehouseMasterID varchar(40),@v_vchWarehouseItemMasterID varchar(40),@v_vchFLocationMasterID varchar(40),
											@in_vchFromParentLPN nvarchar(25),@in_vchFromLPN nvarchar(25),@in_vchLot nvarchar(50),@in_vchExpiryDate nvarchar(50),
											@in_vchSerialNo nvarchar(50),@v_curInventoryData cursor OUTPUT';

		Exec sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@v_vchWarehouseMasterID,@v_vchWarehouseItemMasterID,@v_vchFLocationMasterID,
											@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,
											@in_vchSerialNo,@v_curInventoryData OUTPUT
		Fetch from @v_curInventoryData into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchOwnerCode,@v_fltSStockQuantity,@v_vchReceiveDate,@v_vchToInventoryStatusID,@v_vchInventoryStatus,@v_vchSerialNumber
					
		-- not have inventory data
		If (@v_vchInventoryID is null)
			Begin
				set @out_ErrorCode = '407';
				select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'CANNOT_PICK_ITEM',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchFromLocation,@in_vchItem,@in_vchFromLPN,'@param4','@param5')
				Goto WRITE_PROC;
			End

		set @v_vchUOMPrompt = @in_vchUOMPrompt;

		Begin Transaction;

			SET @v_vchBeginTrans = 1;
			
				Begin

					-- Check outbound pick master id
					set @v_vchOutboundPickMasterID = null
					select @v_vchOutboundPickMasterID = outbound_pick_master_id from t_wms_outbound_pick_master where outbound_order_master_id = @v_vchOutboundOrderMasterID
					if (@v_vchOutboundPickMasterID is null)
						Begin
							set @v_vchOutboundPickMasterID = newid()
							Insert into t_wms_outbound_pick_master(outbound_pick_master_id, wh_master_id, outbound_order_master_id, outbound_order_number, pick_list_number, pick_list_status, create_by)
							Values(@v_vchOutboundPickMasterID,@v_vchWarehouseMasterID,@v_vchOutboundOrderMasterID,@in_vchProductionOrder,@in_vchProductionOrder,'OPEN',@in_vchUserID)
						End

					-- Get Pick line number
					select @v_vchPickLineNumber = max(pick_line_number) from t_wms_outbound_pick_detail where outbound_pick_master_id = @v_vchOutboundPickMasterID
					If (@v_vchPickLineNumber is null)
						set @v_vchPickLineNumber = '00000'

					While @@FETCH_STATUS = 0
					Begin
						
						-- Primary unit
						select @v_fltBaseQuantity = @v_fltQuantity * conversion_factor from t_wms_item_uom where item_master_id = @v_vchItemMasterID and primary_uom = 'YES'
						-- Pick line number
						set @v_vchPickLineNumber = Right('0000' + Convert(NvarChar,@v_vchPickLineNumber + 1),5)
						-- Quantity not enough
						If ((@v_fltSStockQuantity < @v_fltBaseQuantity))
							Begin
								set @out_ErrorCode = '408';
								select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItem,@in_vchFromLocation,'@param3','@param4','@param5')
								Goto WRITE_PROC;							
							End
						Else If (@v_fltSStockQuantity = @v_fltBaseQuantity)
							Begin
								If (isnull(@in_vchToLPN,'') = '' and @in_vchSerialNo <> 'ALL')
									Begin
										set @in_vchToLPN = @in_vchProductionOrder;
									End
								If (isnull(@in_vchToLPN,'') = '' and @in_vchSerialNo = 'ALL')
									Begin
										set @in_vchToLPN = @in_vchFromLPN;
									End
							End
						Else If (@v_fltBaseQuantity < @v_fltSStockQuantity)
							Begin
								If (isnull(@in_vchToLPN,'') = '')
									Begin
										set @in_vchToLPN = @in_vchProductionOrder;
									End
							End
				
						-- manage source location data
						update t_wms_inventory set quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
						where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
						If (@v_vchSerialControl = 'FULL')
							Begin
								update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round) 
								where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID and attribute_value = @v_vchSerialNumber
							End
						Else
							Begin
								update t_wms_inventory_attribute set quantity = round(round(quantity,@Round) - round(@v_fltBaseQuantity,@Round),@Round)
								where inventory_id = @v_vchInventoryID and attribute_group_id = @v_vchAttributeGroupID
							End

						Begin -- manage destination location data
							set @v_vchInventoryID = null;
							set @v_vchAttributeGroupID = null;
							set @v_fltDStockQuantity = 0;
						
							select	@v_vchInventoryID = inventory_id,
									@v_vchAttributeGroupID = attribute_group_id,
									@v_fltDStockQuantity = quantity
							from	v_wms_inventory_data
							where	wh_master_id = @v_vchWarehouseMasterID and wh_item_master_id = @v_vchWarehouseItemMasterID 
									and location_id = @v_vchTLocationMasterID
									and isnull(parent_lpn,'') = isnull(@in_vchToParentLPN,'') and isnull(lpn,'') = isnull(@in_vchToLPN,'')
									and isnull(lot_number,'') = isnull(@in_vchLot,'') and isnull(expiry_date,'') = isnull(@in_vchExpiryDate,'')
									--and isnull(serial_number,'') = isnull(@in_vchSerialNo,'')
							
							exec usp_manage_inventory
									@in_vchApplicationID = @in_vchApplicationID,
									@in_vchWarehouseMasterID = @v_vchWarehouseMasterID,
									@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID,
									@in_vchLocationID = @v_vchTLocationMasterID,
									@in_vchLocation = @in_vchForkLift,
									@in_vchStatusID = @v_vchToInventoryStatusID,
									@in_vchLPN = @in_vchToLPN,
									@in_vchLotNumber = @in_vchLot,
									@in_vchExpiryDate = @in_vchExpiryDate,
									@in_vchSerialNumber = @v_vchSerialNumber,
									@in_fltQty = @v_fltBaseQuantity,
									@in_fltQtyAllocate = 0,
									@in_vchOwner = @v_vchOwnerCode,
									@in_vchInventoryType = @v_vchInventoryType,
									@in_vchPalentLPN = @in_vchToParentLPN,
									@in_vchUserID = @in_vchUserID,
									@in_vchReceiveDate = @v_vchReceiveDate,
									@in_vchInventoryID = @v_vchInventoryID output,
									@in_vchAttributeGroupID = @v_vchAttributeGroupID output,
									@in_vchErrorCode = @out_ErrorCode output,
									@in_vchMessage = @out_ErrorMessage output
							If (@out_ErrorCode <> '0')
								Goto WRITE_PROC;
							
							If ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl))
								Begin
									exec usp_manage_inventory_attribute
											@in_vchApplicationID = @in_vchApplicationID,
											@in_vchItem = @in_vchItem,
											@in_vchSerialNo = @v_vchSerialNumber,
											@in_vchLot = @in_vchLot,
											@in_vchExpiryDate = @in_vchExpiryDate,
											@in_fltQty = @v_fltBaseQuantity,
											@in_fltQtyAllocate = 0,
											@in_vchInventoryID = @v_vchInventoryID,
											@in_vchAttributeGroupID = @v_vchAttributeGroupID,
											@in_vchLotControl = @v_vchLotControl,
											@in_vchSerialNumberControl = @v_vchSerialControl,
											@in_vchExpiryDateControl = @v_vchExpiryDateControl	,
											@in_vchUserID = @in_vchUserID,
											@in_vchErrorCode = @out_ErrorCode output,
											@in_vchMessage = @out_ErrorMessage output			
									If(@out_ErrorCode <> '0')
										Goto WRITE_PROC;
								End			
						End
							
						insert into t_com_tran_log(app_id, tran_type, sub_tran_type, [app_name], [description], 
						start_tran_datetime, end_tran_datetime, warehouse, to_warehouse, location, to_location, 
						[owner], to_owner, item_number, quantity, quantity_uom, after_quantity, after_quantity_uom, 
						lot_number, after_lot_number, [expiry_date], after_expiry_date, serial_number, [user_id], 
						reference_number, control_number,parent_lpn,after_parent_lpn, lpn, after_lpn, [status], after_status, zone, order_number, 
						line_number, device, create_by)
						values(@in_vchApplicationID,'OO_PICK','KITTING',null,'Update pick item kitting production.',
						GETDATE(),GETDATE(),@in_vchWarehouse,null,@in_vchFromLocation,@in_vchForkLift,
						@v_vchOwnerCode,@v_vchOwnerCode, @in_vchItem,@v_fltBaseQuantity,@in_vchUOMPrompt,@v_fltSStockQuantity - @v_fltBaseQuantity ,@in_vchUOMPrompt,
						@in_vchLot,@in_vchLot,@in_vchExpiryDate,@in_vchExpiryDate,@v_vchSerialNumber,@in_vchUserID,null,null,@in_vchFromParentLPN,@in_vchToParentLPN,@in_vchFromLPN,@in_vchToLPN,@v_vchInventoryStatus,@v_vchInventoryStatus,
						null,@in_vchProductionOrder,@v_vchLineNumber,@in_vchDeviceID,@in_vchUserID)
					
						-- manage outbound
						-- Check outbound detail
						set @v_vchOutboundOrderDetailID = null
						select  @v_vchOutboundOrderDetailID = outbound_order_detail_id
						from	t_wms_outbound_detail where outbound_order_master_id = @v_vchOutboundOrderMasterID
								and wh_item_master_id = @v_vchWarehouseItemMasterID
						If (@v_vchOutboundOrderDetailID is null)
							Begin
								select @v_vchLine = max(line_number) from t_wms_outbound_detail where outbound_order_master_id = @v_vchOutboundOrderMasterID
								set @v_vchLine = right('00000' + convert(nvarchar,@v_vchLine + 1),6)

								set @v_vchOutboundOrderDetailID = newid()
								-- insert outbound detail
								Insert into t_wms_outbound_detail(outbound_order_detail_id, outbound_order_master_id, wh_item_master_id, line_number, quantity_order, quantity_pick, item_uom_id, default_item_status,user_def6,wh_item_fg,create_by)--,user_def6
								Values(@v_vchOutboundOrderDetailID,@v_vchOutboundOrderMasterID,@v_vchWarehouseItemMasterID,@v_vchLine,@v_fltQuantity,@v_fltQuantity,@v_vchItemUOMID,@v_vchInventoryStatus,@in_vchFGLOT,@v_vchFormulaItemID,@in_vchUserID)--,@in_vchFGLOT
							End
						Else
							Begin
								update t_wms_outbound_detail set 
								--quantity_order += @v_fltQuantity,
								quantity_pick += @v_fltQuantity
								,user_def6 = @in_vchFGLOT
								,wh_item_fg = @v_vchFormulaItemID
								where outbound_order_detail_id = @v_vchOutboundOrderDetailID
							End

						-- insert outbound pick detail
						set @v_vchOutboundPickDetailID = null;
						Select @v_vchOutboundPickDetailID = outbound_pick_detail_id 
						from t_wms_outbound_pick_detail
						where outbound_pick_master_id = @v_vchOutboundPickMasterID and outbound_order_detail_id = @v_vchOutboundOrderDetailID
						and location_id = @v_vchFLocationMasterID and isnull(parent_lpn,'') = isnull(@in_vchFromParentLPN,'')
						and isnull(lpn,'') = isnull(@in_vchFromLPN,'') and isnull(lot_number,'') = isnull(@in_vchLot,'') 
						and isnull(expiry_date,'') = isnull(@in_vchExpiryDate,'')
						If (isnull(@v_vchOutboundPickDetailID,'') <> '')
							Begin
								update t_wms_outbound_pick_detail 
								set quantity_pick += @v_fltQuantity,pick_location_id = @v_vchTLocationMasterID,
								pick_to_parent_lpn = @in_vchToParentLPN,pick_to_lpn = @in_vchToLPN
								where outbound_pick_detail_id = @v_vchOutboundPickDetailID
							End
						Else
							Begin
								set @v_vchOutboundPickDetailID = newid()
								If (@v_vchPickPackAuto = 'YES')
									set @v_fltQuantityPack = @v_fltQuantity
								Insert into t_wms_outbound_pick_detail(outbound_pick_detail_id, outbound_pick_master_id, outbound_order_detail_id, pick_line_number, location_id, pick_location_id, pick_to_lpn, pick_to_parent_lpn, wh_item_master_id, quantity_plan, quantity_pick, quantity_stage, quantity_pack, parent_lpn, lpn, lot_number, expiry_date, serial_number, pick_status, inventory_id, pick_generate_method, is_active, start_date_time, end_date_time, create_by)
								Values(@v_vchOutboundPickDetailID,@v_vchOutboundPickMasterID,@v_vchOutboundOrderDetailID,@v_vchPickLineNumber,@v_vchFLocationMasterID,@v_vchTLocationMasterID,@in_vchToLPN,@in_vchToParentLPN,@v_vchWarehouseItemMasterID,@v_fltQuantity,@v_fltQuantity,0,@v_fltQuantityPack,@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,@v_vchSerialNumber,'YES',@v_vchInventoryID,'PICKING_KITTING_PD','YES',getdate(),getdate(),@in_vchUserID)
								If (@v_vchPickPackAuto = 'YES')
									Begin
										Insert into t_wms_outbound_pack_detail(outbound_order_master_id, outbound_pick_detail_id, parent_lpn_pack, lpn_pack, pack_location_id, wh_item_master_id, quantity_pack, lot_number, expiry_date, serial_number, item_uom_id, create_by)
										Values(@v_vchOutboundOrderMasterID,@v_vchOutboundPickDetailID,@in_vchToParentLPN,@in_vchToLPN,@v_vchTLocationMasterID,@v_vchWarehouseItemMasterID,@v_fltQuantity,@in_vchLot,@in_vchExpiryDate,@v_vchSerialNumber,@v_vchItemUOMID,@in_vchUserID)
									End
							End

						If (isnull(@v_vchSerialNumber,'') <> '')
							Begin
								If (@v_vchPickPackAuto = 'YES')
									Begin
										insert into t_wms_outbound_pick_serial_detail(outbound_pick_serial_detail_id, outbound_pick_detail_id,location_id, pick_location_id, pick_to_lpn, pick_to_parent_lpn, quantity_pick, quantity_pack, parent_lpn, lpn, lot_number, expiry_date, serial_number, pick_status, inventory_id, create_by)
										values(newid(),@v_vchOutboundPickDetailID,@v_vchFLocationMasterID,@v_vchTLocationMasterID,@in_vchToLPN,@in_vchToParentLPN,1,1,@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,@v_vchSerialNumber,'YES',@v_vchInventoryID,@in_vchUserID)
									End
								Else
									Begin
										insert into t_wms_outbound_pick_serial_detail(outbound_pick_serial_detail_id, outbound_pick_detail_id,location_id, pick_location_id, pick_to_lpn, pick_to_parent_lpn, quantity_pick, parent_lpn, lpn, lot_number, expiry_date, serial_number, pick_status, inventory_id, create_by)
										values(newid(),@v_vchOutboundPickDetailID,@v_vchFLocationMasterID,@v_vchTLocationMasterID,@in_vchToLPN,@in_vchToParentLPN,1,@in_vchFromParentLPN,@in_vchFromLPN,@in_vchLot,@in_vchExpiryDate,@v_vchSerialNumber,'YES',@v_vchInventoryID,@in_vchUserID)
									End
							End

						set @v_vchSerialNumber = null;
						Fetch next from @v_curInventoryData into @v_vchInventoryID,@v_vchAttributeGroupID,@v_vchOwnerCode,@v_fltSStockQuantity,@v_vchReceiveDate,@v_vchToInventoryStatusID,@v_vchInventoryStatus,@v_vchSerialNumber
					End

					Close @v_curInventoryData;
					Deallocate @v_curInventoryData;
				End
			
		Commit Transaction;

		select @v_fltSumQuantityOrder = sum(quantity_order),@v_fltSumQuantityPick = sum(quantity_pick)
		from t_wms_outbound_detail 
		where outbound_order_master_id = @v_vchOutboundOrderMasterID --and wh_item_master_id = @v_vchWarehouseItemMasterID
		If (@v_fltSumQuantityOrder = @v_fltSumQuantityPick)
			Begin
				update t_wms_outbound_master set order_status = 'PICKED' where outbound_order_master_id = @v_vchOutboundOrderMasterID
			End
		ELSE
			begin
				update t_wms_outbound_master set order_status = 'PICK' where outbound_order_master_id = @v_vchOutboundOrderMasterID
			end

		select @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

		delete from t_wms_inventory where quantity <= 0 --and quantity_allocated = 0
		delete from t_wms_inventory_attribute where quantity <= 0 --and quantity_allocated = 0

		return;
		-----------------------------------------------------------------------------------
		--							Write process log
		Begin -- Write Process Log
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					Rollback Transaction;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = getdate();

				IF CURSOR_STATUS('global','@v_curInventoryData') >= -1
					Begin
						Close @v_curInventoryData;
						Deallocate @v_curInventoryData;
					End

				set @v_vchProcessData2 = 'Item number ' + @in_vchItem;
				
				exec usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchProductionOrder,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		End	
				
	End Try
	Begin Catch
	
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			Rollback Transaction;

		IF CURSOR_STATUS('global','@v_curInventoryData') >= -1
					Begin
						Close @v_curInventoryData;
						Deallocate @v_curInventoryData;
					End

		If (isnull(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			Begin
				set @out_ErrorCode = ERROR_NUMBER();
				set @out_ErrorMessage = ERROR_MESSAGE();
			End
			
	End Catch	
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_item_by_load]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pick_item_by_load]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchLoadID			NVARCHAR(50),
	@in_vchBoxNumber		NVARCHAR(25) = NULL,		--Box Number
	@in_vchFromLocation		NVARCHAR(50),
	@in_vchForkLift			NVARCHAR(50),
	@in_vchItemNumber		NVARCHAR(50),
	@in_fltQty				FLOAT,
	@in_vchUOMPrompt		NVARCHAR(40),
	@in_vchFromParentLPN	NVARCHAR(25) = NULL,
	@in_vchFromLPN			NVARCHAR(25) = NULL,
	@in_vchToParentLPN		NVARCHAR(25) = NULL,
	@in_vchLot				NVARCHAR(100) = NULL,
	@in_vchExpiryDate		NVARCHAR(50) = NULL,
	@in_vchSerialNo			NVARCHAR(100) = NULL,
	@in_vchOverPickReasonCode	NVARCHAR(20) = NULL,
	@in_vchAttribute1		NVARCHAR(100) = NULL,
	@in_vchAttribute2		NVARCHAR(100) = NULL,
	@in_vchAttribute3		NVARCHAR(100) = NULL,
	@in_vchAttribute4		NVARCHAR(100) = NULL,
	@in_vchAttribute5		NVARCHAR(100) = NULL,
	@in_vchTrackingNo		NVARCHAR(50)  = NULL,
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_update_pick_item_by_load]', -- The name that uniquely tags this object.
			@v_vchProcessData			NVARCHAR(255)= NULL,
			@v_dtProcessDateTime		DATETIME = NULL, 
			@v_dtStartTime				DATETIME = NULL, 
			@v_vchApplicationName		NVARCHAR(50)= NULL,
			@v_vchLocalID				VARCHAR(10) = NULL,
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,
			@v_nOutboundCursorRow		INT = 0,
			@RulePickPack				NVARCHAR(3) = 'NO',
			@RuleAutoStaging			NVARCHAR(3) = 'NO',
			@RuleOverPick				NVARCHAR(3) = 'NO',

			@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchForkID				UNIQUEIDENTIFIER = NULL,

			--Outbound
			@v_vchOutboundMasterID		UNIQUEIDENTIFIER  = NULL,
			@v_vchOutboundNumber		NVARCHAR(50) = NULL,
			@v_vchOrderStatus			NVARCHAR(30) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50) = NULL,

			--Inventory 
			@v_vchInventoryID			UNIQUEIDENTIFIER  = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER  = NULL,
			@v_fltChkInvQty				FLOAT,

			--Item Master
			@v_vchItemMasterID			UNIQUEIDENTIFIER  = NULL,
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
			@v_vchLotControl			VARCHAR(5) = NULL,
			@v_vchExpControl			VARCHAR(5) = NULL,
			@v_vchSNControl				VARCHAR(5) = NULL,
			@v_vchAttribute1Control		VARCHAR(5) = NULL,
			@v_vchAttribute2Control		VARCHAR(5) = NULL,
			@v_vchAttribute3Control		VARCHAR(5) = NULL,
			@v_vchAttribute4Control		VARCHAR(5) = NULL,
			@v_vchAttribute5Control		VARCHAR(5) = NULL,
			@v_vchItemIsActive			VARCHAR(3) = NULL,

			--Item UOM
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20),
			@v_vchIsPrimaryUOM			VARCHAR(5),
			@v_fltConversionFactor		FLOAT,
			@v_fltBaseInputQuantity		FLOAT,
			@v_fltWidth					FLOAT = 0,  --item Uom
			@v_fltLength				FLOAT = 0,  --item Uom
			@v_fltHeight				FLOAT = 0,  --item Uom
			@v_fltGrossWeight			FLOAT = 0,  --item Uom
			@v_intPercentTolerance		FLOAT = 0,  --item Uom
			@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
			@v_fltVolumn				FLOAT = 0,	--item Uom
			@v_fltTotalWeight			FLOAT = 0,	--item Uom
			
			@v_fltSumRemainPick			FLOAT, --จำนวนรวมคงเหลือที่ยังไม่ได้หยิบ ของทั้ง Order ใน item ที่ scan
			@v_vchPickToLPN				NVARCHAR(25) = NULL,

			--Outbound Loop
			@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,			
			@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL, -- Outbound Detail
			@v_vchPickLineNumber		NVARCHAR(10) = NULL, -- Outbound Pick Detail
			@v_fltQuantityPlan			FLOAT,
			@v_fltQuantityPick			FLOAT,
			@v_dtReceiveDate			DATE,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL,
			
			--จำนวนที่ใช้ในการจ่ายจริง หลังแปลงเป็นหน่วยที่เล็กที่สุด [primary_uom = 'YES']
			@v_fltSumQtyCanPick			FLOAT,
			--@v_fltInvQtyForCheck		FLOAT,  --สำหรับ Check จำนวนที่หยิบ กับจำนวนใน inventory เพื่อ Set pick_to_lpn ถ้าหยิบทั้ง LPN
			@v_fltDiffQtyOverPick		FLOAT,	--สำหรับ เก็บส่วนต่างที่หยิบเกิน
			@v_fltAllocateQtyOverPick	FLOAT,	--สำหรับ เก็บส่วนต่างที่หยิบเกิน

			-- Auto STG
			@v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchStagingLocation		NVARCHAR(50),
			@v_fltQuantityStage			FLOAT,
			@v_vchStagingParentLPN		NVARCHAR(25) = NULL,
			@v_vchStagingLPN			NVARCHAR(25) = NULL,

			@v_vchOutboundNewPickDetailID UNIQUEIDENTIFIER = NULL, --สำหรับกรณีที่ช่วยกันหยิบ
			@v_vchNewPickLineNumber		NVARCHAR(40) = NULL,
			@v_vchPickBy				NVARCHAR(25),
			@v_vchPickLocation			NVARCHAR(50) -- Location ที่ Pick ของมา

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
	SELECT @v_vchLocalID = (SELECT dbo.usf_get_locale_id(@in_vchUserID))
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @RuleOverPick = value FROM t_wms_rule WHERE rule_code = 'RULE_OVER_PICK' AND is_active = 'YES'
	SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT TOP 1 @RuleAutoStaging = value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
	SELECT TOP 1 @v_vchLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchFromLocation AND is_active = 'YES'
	SELECT TOP 1 @v_vchForkID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchForkLift AND is_active = 'YES'
	SET @in_fltQty = ROUND(@in_fltQty,@Round)

	-------------------------------------------------
	-- SET Box Number
	-------------------------------------------------
	IF ISNULL(@in_vchBoxNumber,'') = ''
		BEGIN
			SET @in_vchBoxNumber = @in_vchLoadID
		END
		
	--------------------------------------------------
	-- Get Data in Outbound Master
	--------------------------------------------------
	SELECT @v_vchOrderStatus = load_status
		,@v_vchOwnerID = owner_id 
		,@v_vchOwnerCode = owner_code 
	FROM v_wms_outbound_master_load
	WHERE load_id = @in_vchLoadID
	AND wh_master_id = @v_vchWhMasterID
	IF(@v_vchOrderStatus = 'SHIP')
		BEGIN
			SET @out_ErrorCode = 'LOAD_IS_SHIP_NOT_LOAD_PICK_UNPICK';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchLoadID,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	--ถ้า SET rule Over pick แต่ใน Load Mix Order Type มา และ ถ้าพบว่ามี 1 Order ที่ Order Type ไม่ได้อยู่ใน Rule ที่กำหนดให้หยิบเกินได้ จะถือว่า ทั้ง Load นั้นไม่ให้หยิบเกิน
	IF @RuleOverPick = 'YES' 
		BEGIN
			IF EXISTS (SELECT over_pick_flag FROM (SELECT (CASE WHEN order_type IN (SELECT value FROM t_wms_rule WHERE rule_code = 'ORDER_TYPE_OVER_PICK' AND is_active = 'YES') THEN 'YES' ELSE 'NO' END) AS over_pick_flag FROM t_wms_outbound_master WHERE load_id = @in_vchLoadID AND wh_master_id = @v_vchWhMasterID) t
						WHERE over_pick_flag = 'NO')
				BEGIN
					SET @RuleOverPick = 'NO'
				END
		END

	------------------------------------------------------
	-- ตรวจสอบ Multiple user pick
	------------------------------------------------------
	IF EXISTS (SELECT outbound_order_master_id FROM t_wms_outbound_master WHERE wh_master_id = @V_VCHWHMASTERID and load_id = @in_vchLoadID AND pick_by <> @in_vchUserID) 
		AND (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO'
		BEGIN
			--Multi User
			SELECT TOP 1 @v_vchPickBy = pick_by FROM t_wms_outbound_master WHERE wh_master_id = @v_vchWhMasterID and load_id = @in_vchLoadID AND pick_by <> @in_vchUserID
			SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchPickBy,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END
	 
	--------------------------------------------------------
	-- Validate Staging Location
	--------------------------------------------------------
	IF (@RuleAutoStaging = 'YES')
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_outbound_master obMS on pickMS.outbound_order_master_id = obMS.outbound_order_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE obMS.load_id = @in_vchLoadID
			AND obMS.wh_master_id = @v_vchWhMasterID
			AND pickDT.staging_location_id IS NOT NULL
			AND pickDT.is_override = 'NO'
				
			IF @v_vchStagingLocationID IS NULL
			BEGIN
				SELECT TOP 1 @v_vchStagingLocationID = location_id
					,@v_vchStagingLocation = location 
				FROM t_wms_location 
				WHERE wh_master_id = @v_vchWhMasterID 
				AND loc_type = 'STG' AND is_active = 'YES'
				IF (@v_vchStagingLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END 
		END

	--------------------------------------------------
	-- Get item_master_id
	--------------------------------------------------
	SELECT @v_vchItemMasterID = item.item_master_id 
		, @in_vchItemNumber = item.item_number
		, @v_vchLotControl = item.lot_control
		, @v_vchExpControl = item.expiry_date_control
		, @v_vchSNControl = item.sn_control
		, @v_vchAttribute1Control = item.attribute1_control
		, @v_vchAttribute2Control = item.attribute2_control
		, @v_vchAttribute3Control = item.attribute3_control
		, @v_vchAttribute4Control = item.attribute4_control
		, @v_vchAttribute5Control = item.attribute5_control
		, @v_vchItemIsActive = item.is_active
	FROM t_wms_item item
	LEFT JOIN t_wms_item_crossref cref ON item.item_master_id = cref.item_master_id
	WHERE owner_id = @v_vchOwnerID
	AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
	IF (@v_vchItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	IF (@v_vchItemIsActive <> 'YES')
		BEGIN
			SET @out_ErrorCode = 'ITEM_NOT_ACTIVE';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END
	--------------------------------------------------
	-- Get wh_item_master_id
	--------------------------------------------------
	SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @v_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	IF (@v_vchWhItemMasterID IS NULL)
		BEGIN
			--ITEM NUMBER [0] NOT EXIST
			SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	--Get & Check Item UOM
	--------------------------------------------------
	SELECT @v_vchBaseItemUomID = item_uom_id
		,@v_vchBaseUomPrompt = uom_prompt
		,@v_vchBaseUom = uom
		,@v_fltConversionFactor = conversion_factor
		,@v_vchIsPrimaryUOM = primary_uom
		,@v_fltWidth = ISNULL(width,0)
		,@v_fltLength = ISNULL(length,0)
		,@v_fltHeight = ISNULL(height,0)
		,@v_fltGrossWeight = ISNULL(gross_weight,0)
		,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
		,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
	FROM t_wms_item_uom 
	WHERE item_master_id = @v_vchItemMasterID 
	AND uom_prompt = @in_vchUOMPrompt		
	AND is_active = 'YES'	
	IF (@v_vchBaseItemUomID IS NULL)
		BEGIN
			SET @out_ErrorCode = 'UOM_NOT_FOUND';
			SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC
		End

	--------------------------------------------------
	--Get Primary Uom
	--------------------------------------------------
	IF @v_vchIsPrimaryUOM = 'NO'
		BEGIN
			SELECT @v_vchBaseItemUomID = item_uom_id
				,@v_vchBaseUomPrompt = uom_prompt
				,@v_vchBaseUom = uom
				,@v_fltWidth = ISNULL(width,0)
				,@v_fltLength = ISNULL(length,0)
				,@v_fltHeight = ISNULL(height,0)
				,@v_fltGrossWeight = ISNULL(gross_weight,0)
				,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
				,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
			FROM t_wms_item_uom 
			WHERE item_master_id = @v_vchItemMasterID 
			AND primary_uom = 'YES' 
			AND is_active = 'YES'
		END
	
	--------------------------------------------------
	--Set Input Base Qty 
	--------------------------------------------------
	SET @v_fltBaseInputQuantity = ROUND(@in_fltQty * @v_fltConversionFactor,@Round);

	--------------------------------------------------
	--Get Inventory to Temp table
	--------------------------------------------------
	SELECT inventory_id
		,attribute_group_id
		,inventory_status_id
		,quantity
		,quantity_allocated
		,mfg_date
		,receive_date
		,serial_number
	INTO #tInventory
	FROM v_wms_inventory_data_serial_by_id
	WHERE wh_master_id = @v_vchWhMasterID
	AND location_id = @v_vchLocationID
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
	AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
	AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
	AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
	AND (CASE @in_vchSerialNo WHEN 'ALL' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE @in_vchSerialNo WHEN 'ALL' THEN '' ELSE ISNULL(@in_vchSerialNo,'') END)

	--------------------------------------------------
	--Check Inventory
	--------------------------------------------------
	 IF NOT EXISTS (SELECT inventory_id FROM #tInventory)
		BEGIN
			-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
			SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	
	--------------------------------------------------
	--Check Serial ต้องไม่ได้จองที่ order อื่น
	--------------------------------------------------
	IF EXISTS (SELECT pickDT.outbound_pick_detail_id
				FROM t_wms_outbound_pick_master pickMS
				INNER JOIN t_wms_outbound_master obMS ON pickMS.outbound_order_master_id = obMS.outbound_order_master_id
				INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
				WHERE obMS.load_id <> @in_vchLoadID
				AND obMS.wh_master_id = @v_vchWhMasterID
				AND pickDT.is_override = 'NO'
				AND pickDT.location_id = @v_vchLocationID
				AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
				AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchFromLPN,'')
				AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLot,'')
				AND ISNULL(pickDT.expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
				AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
				AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
				AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
				AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
				AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
				AND ISNULL(pickDT.serial_number,'') = ISNULL(@in_vchSerialNo,'')
				AND ISNULL(pickDT.quantity_pick,0) = 0) AND @v_vchSNControl = 'FULL'
		BEGIN
			-- Seiral นี้ถูกจองโดย Outbound Order อื่นแล้ว
			SET @out_ErrorCode = 'INFO_SERIAL_IS_ALLOCATE_BY_ANOTHER_ORDER'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchSerialNo,'@param2','@param3','@param4','@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- Check จำนวนใน Inventory กับจำนวนที่จะจ่าย
	-- จำนวนที่จะ Pick > จำนวนใน Inventory
	--------------------------------------------------
	SELECT @v_fltChkInvQty = SUM(quantity) FROM #tInventory
	IF (@in_vchSerialNo = 'ALL')
		BEGIN
			SET @v_fltBaseInputQuantity = ROUND(@v_fltChkInvQty,@Round)
		END

	--------------------------------------------------
	--Get Pick Detail to Temp
	--------------------------------------------------
	SELECT pickMS.outbound_order_master_id
		, obMS.outbound_order_number
		, obMS.order_type
		, pickMS.outbound_pick_master_id
		, pickDT.outbound_pick_detail_id
		, pickDT.outbound_order_detail_id
		, obDT.line_number
		, pickDT.pick_line_number
		, ISNULL(pickDT.quantity_plan,0) AS quantity_plan
		, ISNULL(pickDT.quantity_pick,0) AS quantity_pick
		, pickDT.receive_date
		, invST.inventory_status_id
		, obDT.default_item_status		
		, pickDT.location_id
		, loc.location
		, pickDT.serial_number
	INTO #tPickAllDetail
	FROM t_wms_outbound_pick_master pickMS
	INNER JOIN t_wms_outbound_master obMS ON pickMS.outbound_order_master_id = obMS.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
	INNER JOIN t_wms_outbound_detail obDT on pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
	INNER JOIN t_wms_location loc ON loc.location_id = pickDT.location_id
	INNER JOIN t_wms_inventory_status invST on obDT.default_item_status = invST.inv_status
	WHERE obMS.load_id = @in_vchLoadID
	AND obMS.wh_master_id = @v_vchWhMasterID
	AND pickDT.is_override = 'NO'
	AND pickDT.location_id = @v_vchLocationID
	AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
	AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
	AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchFromLPN,'')
	AND ISNULL(pickDT.lot_number,'') = ISNULL(@in_vchLot,'')
	AND ISNULL(pickDT.expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
	AND ISNULL(pickDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
	AND ISNULL(pickDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
	AND ISNULL(pickDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
	AND ISNULL(pickDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
	AND ISNULL(pickDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
	
	DECLARE @tPickDetail AS TABLE
	(
		outbound_order_master_id	UNIQUEIDENTIFIER,
		outbound_order_number		NVARCHAR(50),
		order_type					NVARCHAR(30),
		outbound_pick_master_id		UNIQUEIDENTIFIER,
		outbound_pick_detail_id		UNIQUEIDENTIFIER,
		outbound_order_detail_id	UNIQUEIDENTIFIER,
		line_number					NVARCHAR(10),
		pick_line_number			NVARCHAR(5),
		quantity_plan				FLOAT,
		quantity_pick				FLOAT,
		receive_date				DATE, 
		inventory_status_id			UNIQUEIDENTIFIER,
		default_item_status			NVARCHAR(50),
		location_id					UNIQUEIDENTIFIER,
		location					NVARCHAR(50)
	)

	--Check Picklist ถ้า Control Serial และระบุ Serial ต้อง update pick ของ record นั้น
	IF (@v_vchSNControl = 'FULL')
		BEGIN
			--Case Serial
			IF EXISTS (SELECT outbound_pick_detail_id FROM #tPickAllDetail WHERE ISNULL(serial_number,'') = ISNULL(@in_vchSerialNo,''))
				BEGIN
					--ถ้า Serial ที่ pick ตรงกับ Picklist ที่มีการระบุไว้ที่ plan
					DELETE @tPickDetail
					INSERT INTO @tPickDetail
					(
						outbound_order_master_id	
					   ,outbound_order_number
					   ,order_type
					   ,outbound_pick_master_id		
					   ,outbound_pick_detail_id		
					   ,outbound_order_detail_id	
					   ,line_number					
					   ,pick_line_number			
					   ,quantity_plan				
					   ,quantity_pick				
					   ,receive_date				
					   ,inventory_status_id			
					   ,default_item_status			
					   ,location_id					
					   ,location					
					)
					SELECT outbound_order_master_id
						, outbound_order_number
						, order_type
						, outbound_pick_master_id
						, outbound_pick_detail_id
						, outbound_order_detail_id
						, line_number
						, pick_line_number
						, ISNULL(quantity_plan,0) AS quantity_plan
						, ISNULL(quantity_pick,0) AS quantity_pick
						, receive_date
						, inventory_status_id
						, default_item_status		
						, location_id
						, location
					FROM #tPickAllDetail
					WHERE ISNULL(serial_number,'') = ISNULL(@in_vchSerialNo,'')
					AND ISNULL(quantity_pick,0) = 0
				END
			ELSE
				BEGIN
					--สำหรับ plan ที่ไม่ได้ระบุ serial
					DELETE @tPickDetail
					INSERT INTO @tPickDetail
					(
						outbound_order_master_id	
					   ,outbound_order_number	
					   ,order_type	
					   ,outbound_pick_master_id		
					   ,outbound_pick_detail_id		
					   ,outbound_order_detail_id	
					   ,line_number					
					   ,pick_line_number			
					   ,quantity_plan				
					   ,quantity_pick				
					   ,receive_date				
					   ,inventory_status_id			
					   ,default_item_status			
					   ,location_id					
					   ,location					
					)
					SELECT outbound_order_master_id
						, outbound_order_number
						, order_type
						, outbound_pick_master_id
						, outbound_pick_detail_id
						, outbound_order_detail_id
						, line_number
						, pick_line_number
						, ISNULL(quantity_plan,0) AS quantity_plan
						, ISNULL(quantity_pick,0) AS quantity_pick
						, receive_date
						, inventory_status_id
						, default_item_status		
						, location_id
						, location
					FROM #tPickAllDetail
					WHERE ISNULL(serial_number,'') = ''
					AND ISNULL(quantity_pick,0) = 0
				END

			--------------------------------------------------
			-- ถ้าไม่พบ Recode ใน PickList แสดงว่าข้อมูลผิด
			--------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM @tPickDetail)
				BEGIN
					-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
					SET @out_ErrorCode = 'INFO_NOT_FOUND_DATA_SN_IN_PICK_LIST'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchSerialNo,'@param5')			
					RETURN;
				END
		END
	ELSE 
		BEGIN
			--Case ปกติ
			DELETE @tPickDetail
			INSERT INTO @tPickDetail
			(
				outbound_order_master_id	
			   ,outbound_order_number
			   ,order_type
			   ,outbound_pick_master_id		
			   ,outbound_pick_detail_id		
			   ,outbound_order_detail_id	
			   ,line_number					
			   ,pick_line_number			
			   ,quantity_plan				
			   ,quantity_pick				
			   ,receive_date				
			   ,inventory_status_id			
			   ,default_item_status			
			   ,location_id					
			   ,location					
			)
			SELECT outbound_order_master_id
				, outbound_order_number
				, order_type
				, outbound_pick_master_id
				, outbound_pick_detail_id
				, outbound_order_detail_id
				, line_number
				, pick_line_number
				, ISNULL(quantity_plan,0) AS quantity_plan
				, ISNULL(quantity_pick,0) AS quantity_pick
				, receive_date
				, inventory_status_id
				, default_item_status		
				, location_id
				, location
			FROM #tPickAllDetail

			--------------------------------------------------
			-- ถ้าไม่พบ Recode ใน PickList แสดงว่าข้อมูลผิด
			--------------------------------------------------
			IF NOT EXISTS (SELECT outbound_pick_detail_id FROM @tPickDetail)
				BEGIN
					-- ไม่มีรายการ item number[] Lot[] exp.[] LPN[] ที่ต้องการ Pick แล้ว
					SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
					RETURN;
				END
		END

	--------------------------------------------------
	--Check Remain pick
	-- ถ้าจำนวนคงเหลือที่สามารถหยิบได้ เท่ากับ ศุนย์ >> ERROR
	--------------------------------------------------
	SELECT @v_fltSumRemainPick = SUM(quantity_plan - quantity_pick) FROM @tPickDetail pickMS
	IF ROUND(@v_fltSumRemainPick,@Round) <= 0
		BEGIN
			-- รายการสินค้า [] หยิบครบแล้ว
			SET @out_ErrorCode = 'INFO-ALREADY-PICKED'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END
	
	--------------------------------------------------
	-- ถ้าจำนวนใน Inventory มีไม่พอ
	--------------------------------------------------
	IF ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltChkInvQty,@Round)
		BEGIN
			-- จำนวนสินค้าใน Inventory ไม่เพียงพอ
			SET @out_ErrorCode = 'INFO-QUANTITY-ITEM-NOT-ENOUGH'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
			RETURN;
		END

	--------------------------------------------------
	-- ถ้าจำนวนที่หยิบ มากกว่า จำนวนคงเหลือที่สามารถหยิบได้ >> ERROR
	-- ถ้า Rule Over Pick = NO ต้อง Check Qty ที่หยิบ
	-- ถ้า Rule Over Pick = YES ไม่ต้อง Check Qty
	--------------------------------------------------
	IF ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltSumRemainPick,@Round) AND @RuleOverPick = 'NO'
		BEGIN
			-- รายการสินค้า [] ไม่สามารถหยิบเกินได้
			SET @out_ErrorCode = 'QTY_PICK_MORE_THAN_QTY_PLAN'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')			
			RETURN;
		END

	-- ถ้ากำหนด over pick ให้หายอด diff ของส่วนที่หยิบเกิน เพื่อไว้ pick ให้กับ row สุดท้ายของ pick detail และยอดที่หยิบ มากกว่า ยอดคงเหลือ ถึงจะถือว่ามันหยิบเกินจริงๆ
	IF @RuleOverPick = 'YES' AND ROUND(@v_fltBaseInputQuantity,@Round) > ROUND(@v_fltSumRemainPick,@Round)
		BEGIN
			SET @v_fltDiffQtyOverPick = ROUND(@v_fltBaseInputQuantity,@Round) - ROUND(@v_fltSumRemainPick,@Round)
		END
	 
	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้ทั้งหมด เทียบกับ inventory
	-- หายอดเทียบระหว่างคงเหลือ กับ ยอด inventoy ว่าจะเป็นตัวไหน เพื่อไปเทียบกับ input qty อีกที
	-------------------------------------------------
	IF (ROUND(@v_fltSumRemainPick,@Round) > ROUND(@v_fltChkInvQty,@Round))
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltChkInvQty,@Round)
		END
	ELSE
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltSumRemainPick,@Round)
		END
	
	-------------------------------------------------
	-- ยอดรวมจำนวนที่สามารถหยิบได้จริง กับจำนวนที่หยิบจริง
	-------------------------------------------------
	IF ROUND(@v_fltSumQtyCanPick,@Round) > ROUND(@v_fltBaseInputQuantity,@Round)
		BEGIN
			SET @v_fltSumQtyCanPick = ROUND(@v_fltBaseInputQuantity,@Round)
		END

	------------------------------------------------------------
	-- SET pick_to_lpn
	-- เงื่อนไข คือ ถ้าจำนวนของที่หยิบ = จำนวนที่มีใน Inventory และไม่มียอด Order อื่นแล้ว ให้ LPN คือ LPN เดิม แต่ถ้ายังมีของอยู่ใน INV ให้เป็นเลข box
	------------------------------------------------------------
	IF (@v_fltBaseInputQuantity = @v_fltChkInvQty AND ISNULL(@in_vchFromLPN,'') <> '')
		BEGIN
			SET @v_vchPickToLPN = @in_vchFromLPN
		END
	ELSE
		BEGIN
			SET @v_vchPickToLPN = @in_vchBoxNumber
		END

BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
	SET @v_nOutboundCursorRow = 1;
	SET @v_fltAllocateQtyOverPick = 0
	DECLARE @v_nLoopCheck int = 0

	DECLARE @v_fltQtyCanPick		FLOAT
	DECLARE @v_fltRemainQtyCanPick	FLOAT
	DECLARE @v_fltQtyPick			FLOAT
	---------------------------------------------------------------
	--Get Inventory รายการของสินค้าจากที่หยิบมา					
	---------------------------------------------------------------
	DECLARE @v_vchInvID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvAttrGroupID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvSerialNumber	NVARCHAR(100)= NULL
	DECLARE @v_fltInvQuantity		FLOAT
	DECLARE @v_dtInvMfgDate			DATE
	DECLARE @v_dtInvReceiveDate		DATE

	DECLARE OutboundDetailCursor CURSOR STATIC FOR
		SELECT outbound_order_master_id
			, outbound_order_number
			, order_type
			, outbound_pick_master_id
			, outbound_pick_detail_id
			, outbound_order_detail_id
			, line_number
			, pick_line_number
			, quantity_plan
			, quantity_pick
			, receive_date
			, inventory_status_id
			, default_item_status
			, location
		FROM @tPickDetail
		WHERE ROUND(quantity_pick,@Round) < ROUND(quantity_plan,@Round)
		ORDER BY receive_date,outbound_order_number,line_number,pick_line_number
	OPEN OutboundDetailCursor
	FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundMasterID,@v_vchOutboundNumber,@v_vchOrderType,@v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_vchOutboundDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_dtReceiveDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchPickLocation
	SET @v_nLoopCheck = @@CURSOR_ROWS 
	WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @v_fltQtyCanPick		= 0
			SET @v_fltRemainQtyCanPick	= 0
			SET	@v_fltQtyPick			= 0
			SET @v_vchInvID				= NULL
			SET	@v_vchInvAttrGroupID	= NULL
			SET	@v_vchInvSerialNumber	= NULL
			SET	@v_fltInvQuantity		= 0
			SET	@v_dtInvMfgDate			= NULL
			SET @v_dtInvReceiveDate		= NULL

 			SET @v_dtStartTime = GETDATE();
			
			---------------------------------------------------------------
			-- Check จำนวนที่สามารถ Pick ได้จริง ของ order นั้นๆ				
			---------------------------------------------------------------
			IF @v_nOutboundCursorRow = @v_nLoopCheck
				BEGIN
					Print 'over pick'
					--กรณี Over pick check last record ของ outbound ให้ + ยอดที่ pick เกินจาก plan
					SET @v_fltSumQtyCanPick = ROUND(@v_fltSumQtyCanPick + ISNULL(@v_fltDiffQtyOverPick,0),@Round)
					SET @v_fltQtyCanPick = ROUND(@v_fltSumQtyCanPick,@Round)
					SET @v_fltAllocateQtyOverPick = ROUND(ISNULL(@v_fltDiffQtyOverPick,0),@Round)
				END
			ELSE
				BEGIN
					--กรณี case ปกติ หยิบตาม plan
					IF (ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round) > ROUND(@v_fltSumQtyCanPick,@Round))
						SET @v_fltQtyCanPick = ROUND(@v_fltSumQtyCanPick,@Round)
					ELSE
						SET @v_fltQtyCanPick = ROUND((@v_fltQuantityPlan - @v_fltQuantityPick),@Round)
				END
		
			---------------------------------------------------------------
			-- สำหรับใช้กรณีของ Serial เนื่องจากต้องมีการ วน serail case all 
			-- โดยที่ @v_fltQtyCanPick ยังต้องคงค่าไว้ เพื่อจะได้รู้ว่า เหลือจำนวนเท่าไหร่ที่ต้องวน
			---------------------------------------------------------------
			SET @v_fltRemainQtyCanPick = ROUND(@v_fltQtyCanPick,@Round)
			--SET @v_fltQtyPick = ROUND(@v_fltQtyCanPick,@Round)

			DECLARE InventoryCursor CURSOR STATIC FOR
				SELECT inventory_id
					,attribute_group_id
					,serial_number
					,mfg_date
					,receive_date
				FROM #tInventory
				WHERE inventory_status_id = @v_vchInvStatusID
				AND (CASE WHEN @RuleOverPick = 'NO' THEN CONVERT(VARCHAR(8),receive_date,112) ELSE '' END) = (CASE WHEN @RuleOverPick = 'NO' THEN CONVERT(VARCHAR(8),@v_dtReceiveDate,112) ELSE '' END)
				ORDER BY receive_date, serial_number
			OPEN InventoryCursor
			FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_dtInvMfgDate,@v_dtInvReceiveDate
			IF(@@CURSOR_ROWS > 0)
				BEGIN
					WHILE @@FETCH_STATUS = 0
						BEGIN
							SET @v_fltInvQuantity = 0
							SELECT @v_fltInvQuantity = quantity FROM t_wms_inventory WHERE inventory_id = @v_vchInvID and attribute_group_id = @v_vchInvAttrGroupID
							
							IF ROUND(@v_fltRemainQtyCanPick,@Round) >= ROUND(@v_fltInvQuantity,@Round)
								SET @v_fltQtyPick = ROUND(@v_fltInvQuantity,@Round)
							ELSE 
								SET @v_fltQtyPick = ROUND(@v_fltRemainQtyCanPick,@Round)

							-----------------------------------------------------
							-- Validate Duplicate Serial Number ใน Pick Detail
							-----------------------------------------------------
							IF (@v_vchSNControl = 'FULL')
								BEGIN
									SET @v_fltInvQuantity = 1
									SET @v_fltQtyPick = 1   -- กรณีของ Serial Qty Pick = 1
									IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
												WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
												AND wh_item_master_id = @v_vchWhItemMasterID 
												AND serial_number = @v_vchInvSerialNumber
												AND ISNULL(quantity_pick,0) > 0
												AND is_override = 'NO')
										BEGIN
											SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
											SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@v_vchInvSerialNumber,@in_vchItemNumber,'@param3','@param4','@param5')
											GOTO WRITE_PROC;
										END
								END

							-------------------------------------------------------------------
							-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP กำหนดจาก Rule
							-------------------------------------------------------------------
							IF (@v_nOutboundCursorRow = @v_nLoopCheck AND @v_dtReceiveDate <> @v_dtInvReceiveDate)
								BEGIN --กรณีที่เป็น Pick Detail Record สุดท้ายและมีการ Over Pick ข้าม Receipt Date กัน จะต้อง Insert Pick Detail Line ใหม่
									IF @RuleAutoStaging = 'YES'
										BEGIN
											----------------------------------------
											--SET Value Staging
											----------------------------------------
											SET @v_fltQuantityStage = ROUND(@v_fltQtyPick,@Round)
											SET @v_vchStagingParentLPN = @in_vchToParentLPN
											SET @v_vchStagingLPN = @v_vchPickToLPN

											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(ISNULL(quantity_pick,0) + @v_fltQuantityStage,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber
									
											--Insert Pick Detail Record ใหม่ เนื่องจากเป็นการ OverPick
											GOTO NEW_PICK_DETAIL_AUTO_STG;
										END
									ELSE
										BEGIN
											SET @v_vchStagingLocationID = NULL
											SET @v_vchStagingLocation = NULL
											SET @v_fltQuantityStage = 0	
											SET @v_vchStagingParentLPN = NULL	
											SET @v_vchStagingLPN = NULL
											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											--Insert Pick Detail Record ใหม่ เนื่องจากเป็นการ OverPick
											GOTO NEW_PICK_DETAIL;
										END
								END
							ELSE
								BEGIN --Normal case
									IF (@RuleAutoStaging = 'YES')
										BEGIN
											----------------------------------------
											--SET Value Staging
											----------------------------------------
											SET @v_fltQuantityStage = ROUND(@v_fltQtyPick,@Round)
											SET @v_vchStagingParentLPN = @in_vchToParentLPN
											SET @v_vchStagingLPN = @v_vchPickToLPN

											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(ISNULL(quantity_pick,0) + @v_fltQuantityStage,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											----------------------------------------------------------------
											-- แบบวาง STG Auto
											-- [CBD 07/07/2014] กำหนดให้วาง STG เลย สำหรับ PC to WIP
											----------------------------------------------------------------
											IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
														WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND is_override = 'NO'
														AND receive_date = @v_dtInvReceiveDate
														AND (CASE WHEN quantity_pick > 0 THEN ISNULL(pick_to_lpn,'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN @v_vchPickToLPN ELSE '' END)
														AND (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),pick_location_id),'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),@v_vchForkID),'') ELSE '' END)) OR @v_vchSNControl = 'FULL'
												BEGIN
													--กรณีที่ใช้ fork เดิม Update ค่าได้เลย
													UPDATE t_wms_outbound_pick_detail SET 
														  quantity_pick		 = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
														, quantity_stage	 = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round) 
														, pick_location_id   = @v_vchForkID
														, pick_to_parent_lpn = @in_vchToParentLPN
														, pick_to_lpn		 = @v_vchPickToLPN
														, staging_location_id = @v_vchStagingLocationID
														, staging_parent_lpn = @v_vchStagingParentLPN
														, staging_lpn		 = @v_vchStagingLPN 
														, pick_status        = 'YES'
														, start_date_time	 = ISNULL(start_date_time,GETDATE())
														, end_date_time		 = GETDATE()
														, serial_number		 = @v_vchInvSerialNumber
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
												END
											ELSE
												BEGIN
													--Insert New Pick Detail
													--1. ลบยอดจำนวนจากรายการเดิม
													UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyPick,@Round)
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

													NEW_PICK_DETAIL_AUTO_STG:
													--Check ว่ามี recode เดิมหรือไม่ ถ้ามีให้ทำการ update
													SET @v_vchOutboundNewPickDetailID = NULL
													SELECT @v_vchOutboundNewPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
													WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
													AND outbound_order_detail_id = @v_vchOutboundDetailID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND location_id = @v_vchLocationID
													AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
													AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'')
													AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
													AND ISNULL(expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
													AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
													AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
													AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
													AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
													AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
													AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')
													AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
													AND pick_location_id = @v_vchForkID
													AND receive_date = @v_dtInvReceiveDate
													AND is_override = 'NO'
													IF (@v_vchOutboundNewPickDetailID IS NOT NULL)
														BEGIN
															UPDATE t_wms_outbound_pick_detail SET 
																  quantity_plan		  = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyPick,@Round)
																, quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
																, quantity_stage	  = ROUND(ISNULL(quantity_stage,0) + @v_fltQuantityStage,@Round)
																, pick_location_id    = @v_vchForkID
																, pick_to_parent_lpn  = @in_vchToParentLPN
																, pick_to_lpn		  = @v_vchPickToLPN
																, staging_location_id = @v_vchStagingLocationID
																, staging_parent_lpn  = @v_vchStagingParentLPN
																, staging_lpn		  = @v_vchStagingLPN 
																, pick_status         = 'YES'
																, start_date_time	  = ISNULL(start_date_time,GETDATE())
																, end_date_time		  = GETDATE()
																, serial_number		  = @v_vchInvSerialNumber
															WHERE outbound_pick_detail_id = @v_vchOutboundNewPickDetailID
														END
													ELSE
														BEGIN
															--2. new record ใหม่
															SET @v_vchOutboundNewPickDetailID = NEWID()
															SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail 
															WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
															IF (@v_vchNewPickLineNumber IS NULL)
																BEGIN SET @v_vchNewPickLineNumber = '00001'; END
															ELSE
																BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

															INSERT INTO [dbo].[t_wms_outbound_pick_detail]
																	([outbound_pick_detail_id]
																	,[outbound_pick_master_id]
																	,[outbound_order_detail_id]
																	,[pick_line_number]
																	,[location_id]
																	,[pick_location_id]
																	,[pick_to_lpn]
																	,[pick_to_parent_lpn]
																	,[wh_item_master_id]
																	,[quantity_plan]
																	,[quantity_pick] 
																	,[quantity_stage]
																	,[quantity_pack]
																	,[quantity_load]
																	,[quantity_ship]
																	,[short_pick_reason_id]
																	,[parent_lpn]
																	,[lpn]
																	,[lot_number]
																	,[expiry_date]
																	,[serial_number]
																	,[attribute1]
																	,[attribute2]
																	,[attribute3]
																	,[attribute4]
																	,[attribute5]
																	,[user_assign]
																	,[staging_location_id]
																	,[staging_parent_lpn]
																	,[staging_lpn]
																	,[next_location_reason_id]
																	,[over_pick_reason_id]
																	,[dock_door_id]
																	,[dock_door_parent_lpn]
																	,[dock_door_lpn]
																	,[pick_status]
																	,[load_status]
																	,[ship_status]
																	,[inventory_id]
																	,[pack_status]
																	,[pick_generate_method]
																	,[is_allocate]
																	,[is_override]
																	,[pick_override_reason]
																	,[receive_date]
																	,[mfg_date]
																	,[is_active]
																	,[start_date_time]
																	,[end_date_time]
																	,[create_date]
																	,[create_by])
															(SELECT TOP 1 @v_vchOutboundNewPickDetailID
																	, outbound_pick_master_id
																	, outbound_order_detail_id
																	, @v_vchNewPickLineNumber
																	, location_id
																	, @v_vchForkID
																	, @v_vchPickToLPN
																	, @in_vchToParentLPN
																	, wh_item_master_id
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_plan
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_pick
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_stage
																	, 0
																	, 0
																	, 0
																	, short_pick_reason_id
																	, parent_lpn
																	, lpn
																	, lot_number
																	, expiry_date
																	, serial_number
																	, attribute1
																	, attribute2
																	, attribute3
																	, attribute4
																	, attribute5
																	, user_assign
																	, @v_vchStagingLocationID
																	, @v_vchStagingParentLPN
																	, @v_vchStagingLPN
																	, next_location_reason_id
																	, over_pick_reason_id
																	, dock_door_id
																	, dock_door_parent_lpn
																	, dock_door_lpn
																	, 'YES'
																	, load_status
																	, ship_status
																	, inventory_id
																	, pack_status
																	, pick_generate_method
																	, is_allocate
																	, is_override
																	, pick_override_reason
																	, @v_dtInvReceiveDate
																	, mfg_date
																	, is_active
																	, GETDATE()
																	, GETDATE()
																	, GETDATE()
																	, @in_vchUserID
																FROM t_wms_outbound_pick_detail
																WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID)
														END

													--นำ ID ของ Record ใหม่ไปใช้แทน ID เก่า
													SET @v_vchOutboundPickDetailID = @v_vchOutboundNewPickDetailID
												END
										END
									ELSE
										BEGIN
											SET @v_vchStagingLocationID = NULL
											SET @v_vchStagingLocation = NULL
											SET @v_fltQuantityStage = 0	
											SET @v_vchStagingParentLPN = NULL	
											SET @v_vchStagingLPN = NULL
											---------------------------------------------------		
											--Update Outbound Detail
											---------------------------------------------------		
											UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
												,item_status = 'PICK'
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND outbound_order_detail_id = @v_vchOutboundDetailID 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND line_number = @v_vchLineNumber

											-----------------------------------------------
											-- แบบปกติ ไม่ต้องวาง STG
											-----------------------------------------------
											IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
														WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND is_override = 'NO'
														AND receive_date = @v_dtInvReceiveDate
														AND (CASE WHEN quantity_pick > 0 THEN pick_to_lpn ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN @v_vchPickToLPN ELSE '' END)
														AND (CASE WHEN quantity_pick > 0 THEN CONVERT(VARCHAR(36),pick_location_id) ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN CONVERT(VARCHAR(36),@v_vchForkID) ELSE '' END)) OR @v_vchSNControl = 'FULL'
												BEGIN
													UPDATE t_wms_outbound_pick_detail SET 
														  quantity_pick		 = ROUND(ISNULL(quantity_pick,0)+ @v_fltQtyPick,@Round)
														, pick_location_id   = @v_vchForkID
														, pick_to_parent_lpn = @in_vchToParentLPN
														, pick_to_lpn		 = @v_vchPickToLPN
														, pick_status        = 'YES'
														, start_date_time	 = ISNULL(start_date_time,GETDATE())
														, end_date_time		 = GETDATE()
														, serial_number		 = @v_vchInvSerialNumber
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
												END
											ELSE
												BEGIN
													--Insert New Pick Detail
													--1. ลบยอดจำนวนจากรายการเดิม
													UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyPick,@Round)
													WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
											
													NEW_PICK_DETAIL:
													--Check ว่ามี recode เดิมหรือไม่ ถ้ามีให้ทำการ update
													SET @v_vchOutboundNewPickDetailID = NULL
													SELECT @v_vchOutboundNewPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
													WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
													AND outbound_order_detail_id = @v_vchOutboundDetailID
													AND wh_item_master_id = @v_vchWhItemMasterID
													AND location_id = @v_vchLocationID
													AND ISNULL(parent_lpn,'') = ISNULL(@in_vchFromParentLPN,'')
													AND ISNULL(lpn,'') = ISNULL(@in_vchFromLPN,'') 
													AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'') 
													AND ISNULL(expiry_date,'') =  ISNULL(@in_vchExpiryDate,'')
													AND ISNULL(serial_number,'') =  ISNULL(@v_vchInvSerialNumber,'')
													AND ISNULL(attribute1,'') =  ISNULL(@in_vchAttribute1,'')
													AND ISNULL(attribute2,'') =  ISNULL(@in_vchAttribute2,'')
													AND ISNULL(attribute3,'') =  ISNULL(@in_vchAttribute3,'')
													AND ISNULL(attribute4,'') =  ISNULL(@in_vchAttribute4,'')
													AND ISNULL(attribute5,'') =  ISNULL(@in_vchAttribute5,'')
													AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'')
													ANd pick_location_id = @v_vchForkID
													AND receive_date = @v_dtInvReceiveDate
													AND is_override = 'NO'

													IF (@v_vchOutboundNewPickDetailID IS NOT NULL)
														BEGIN
															UPDATE t_wms_outbound_pick_detail SET 
																  quantity_plan		 = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyPick,@Round)
																, quantity_pick		 = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyPick,@Round)
																, pick_location_id   = @v_vchForkID
																, pick_to_parent_lpn = @in_vchToParentLPN
																, pick_to_lpn		 = @v_vchPickToLPN
																, pick_status        = 'YES'
																, start_date_time	 = ISNULL(start_date_time,GETDATE())
																, end_date_time		 = GETDATE()
																, serial_number		 = @v_vchInvSerialNumber
															WHERE outbound_pick_detail_id = @v_vchOutboundNewPickDetailID
														END
													ELSE
														BEGIN
															--2. new record ใหม่
															SET @v_vchOutboundNewPickDetailID = NEWID()
															SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail 
															WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
															IF (@v_vchNewPickLineNumber IS NULL)
																BEGIN SET @v_vchNewPickLineNumber = '00001'; END
															ELSE
																BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

															INSERT INTO [dbo].[t_wms_outbound_pick_detail]
																	([outbound_pick_detail_id]
																	,[outbound_pick_master_id]
																	,[outbound_order_detail_id]
																	,[pick_line_number]
																	,[location_id]
																	,[pick_location_id]
																	,[pick_to_lpn]
																	,[pick_to_parent_lpn]
																	,[wh_item_master_id]
																	,[quantity_plan]
																	,[quantity_pick] 
																	,[quantity_stage]
																	,[quantity_pack]
																	,[quantity_load]
																	,[quantity_ship]
																	,[short_pick_reason_id]
																	,[parent_lpn]
																	,[lpn]
																	,[lot_number]
																	,[expiry_date]
																	,[serial_number]
																	,[attribute1]
																	,[attribute2]
																	,[attribute3]
																	,[attribute4]
																	,[attribute5]
																	,[user_assign]
																	,[staging_location_id]
																	,[staging_parent_lpn]
																	,[staging_lpn]
																	,[next_location_reason_id]
																	,[over_pick_reason_id]
																	,[dock_door_id]
																	,[dock_door_parent_lpn]
																	,[dock_door_lpn]
																	,[pick_status]
																	,[load_status]
																	,[ship_status]
																	,[inventory_id]
																	,[pack_status]
																	,[pick_generate_method]
																	,[is_allocate]
																	,[is_override]
																	,[pick_override_reason]
																	,[receive_date]
																	,[mfg_date]
																	,[is_active]
																	,[start_date_time]
																	,[end_date_time]
																	,[create_date]
																	,[create_by])
															(SELECT TOP 1 @v_vchOutboundNewPickDetailID
																	, outbound_pick_master_id
																	, outbound_order_detail_id
																	, @v_vchNewPickLineNumber
																	, location_id
																	, @v_vchForkID
																	, @v_vchPickToLPN
																	, @in_vchToParentLPN
																	, wh_item_master_id
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_plan
																	, ROUND(@v_fltQtyPick,@Round)	--quantity_pick 
																	, 0
																	, 0
																	, 0
																	, 0
																	, short_pick_reason_id
																	, parent_lpn
																	, lpn
																	, lot_number
																	, expiry_date
																	, serial_number
																	, attribute1
																	, attribute2
																	, attribute3
																	, attribute4
																	, attribute5
																	, user_assign
																	, @v_vchStagingLocationID
																	, @v_vchStagingParentLPN
																	, @v_vchStagingLPN
																	, next_location_reason_id
																	, over_pick_reason_id
																	, dock_door_id
																	, dock_door_parent_lpn
																	, dock_door_lpn
																	, 'YES'
																	, load_status
																	, ship_status
																	, inventory_id
																	, pack_status
																	, pick_generate_method
																	, is_allocate
																	, is_override
																	, pick_override_reason
																	, @v_dtInvReceiveDate
																	, mfg_date
																	, is_active
																	, GETDATE()
																	, GETDATE()
																	, GETDATE()
																	, @in_vchUserID
																FROM t_wms_outbound_pick_detail
																WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID)	
														END
													--นำ ID ของ Record ใหม่ไปใช้แทน ID เก่า
													SET @v_vchOutboundPickDetailID = @v_vchOutboundNewPickDetailID
												END
										END
								END

							---------------------------------------------------
							-- Insert/Update Pack Detail
							---------------------------------------------------
							IF (@RulePickPack = 'YES')
								BEGIN
									UPDATE t_wms_outbound_pick_detail SET 
										  quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltQtyPick,@Round)
										, end_date_time = GETDATE()
									WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

									---------------------------------------------------
									--Insert/Update Pack Detail
									---------------------------------------------------
									PRINT 'Pick and Pack'
									IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail 
														WHERE outbound_order_master_id = @v_vchOutboundMasterID
														AND pack_location_id = @v_vchForkID
														AND lpn_pack = @v_vchPickToLPN 
														AND wh_item_master_id = @v_vchWhItemMasterID 
														AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
														AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
										BEGIN
											UPDATE t_wms_outbound_pack_detail SET 
												 quantity_pack = ROUND(quantity_pack + @v_fltQtyPick,@Round)
												,quantity_stage = ROUND(quantity_stage + @v_fltQuantityStage,@Round)
											WHERE outbound_order_master_id = @v_vchOutboundMasterID 
											AND pack_location_id = @v_vchForkID
											AND lpn_pack = @v_vchPickToLPN 
											AND wh_item_master_id = @v_vchWhItemMasterID 
											AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
											AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
										END
									ELSE
										BEGIN
											INSERT INTO t_wms_outbound_pack_detail
											(     outbound_order_master_id
												, outbound_pick_detail_id
												, lpn_pack
												, pack_location_id
												, wh_item_master_id
												, quantity_pack
												, quantity_stage
												, lot_number
												, expiry_date
												, serial_number
												, [attribute1]
												, [attribute2]
												, [attribute3]
												, [attribute4]
												, [attribute5]
												, item_uom_id
												, [staging_location_id]
												, [staging_parent_lpn]
												, [staging_lpn]
												, create_by
											)
											VALUES
											(     @v_vchOutboundMasterID
												, @v_vchOutboundPickDetailID
												, @v_vchPickToLPN
												, @v_vchForkID
												, @v_vchWhItemMasterID
												, ROUND(@v_fltQtyPick,@Round)
												, @v_fltQuantityStage
												, @in_vchLot
												, @in_vchExpiryDate
												, @v_vchInvSerialNumber
												, @in_vchAttribute1
												, @in_vchAttribute2
												, @in_vchAttribute3
												, @in_vchAttribute4
												, @in_vchAttribute5
												, @v_vchBaseItemUomID
												, @v_vchStagingLocationID
												, @v_vchStagingParentLPN
												, @v_vchStagingLPN
												, @in_vchUserID
											)
										END
								END

							---------------------------------------------------
							--Calculate Volumn & Weight
							---------------------------------------------------
							IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
							BEGIN
								SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyPick,2)
								SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyPick,2)
							END

							---------------------------------------------------
							-- Manage source location data
							---------------------------------------------------
							BEGIN
								--Update Volumn & Weight in from location
								IF @v_vchLocationID IS NOT NULL
									BEGIN
										UPDATE [dbo].[t_wms_location]
										   SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
											, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
											, update_date = GETDATE()  
											, [update_by] = @in_vchUserID   
										 WHERE [location_id] = @v_vchLocationID
									END

								UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
									,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - (@v_fltQtyPick - @v_fltAllocateQtyOverPick),@Round)
									,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
									,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID

								UPDATE #tInventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
								WHERE inventory_id = @v_vchInvID 
								AND attribute_group_id = @v_vchInvAttrGroupID

								IF (@v_vchSNControl = 'FULL')
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round) 
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID 
										AND attribute_value = @v_vchInvSerialNumber
										AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END

								IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyPick,@Round)
											,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - (@v_fltQtyPick - @v_fltAllocateQtyOverPick),@Round)
										WHERE inventory_id = @v_vchInvID 
										AND attribute_group_id = @v_vchInvAttrGroupID
										AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END
							END

							------------------------------------------------
							-- Clear Inventory ที่หยิบของหมดแล้ว
							------------------------------------------------
							DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
							DELETE FROM t_wms_inventory WHERE quantity <= 0
							DELETE FROM #tInventory WHERE quantity <= 0 

							--------------------------------------------
							--Manage Destination inventory
							--------------------------------------------
							SET @v_vchInventoryID = NULL
							SET @v_vchAttributeGroupID = NULL
							IF (@RuleAutoStaging = 'YES')
								BEGIN
									SELECT @v_vchInventoryID = inventory_id
										,@v_vchAttributeGroupID = attribute_group_id
									FROM v_wms_inventory_data_by_id
									WHERE wh_master_id = @v_vchWhMasterID
									AND owner_id = @v_vchOwnerID
									AND location_id = @v_vchStagingLocationID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND inventory_status_id = @v_vchInvStatusID
									and receive_date = @v_dtInvReceiveDate
									AND ISNULL(parent_lpn,'') = ISNULL(@v_vchStagingParentLPN,'')
									AND ISNULL(lpn,'') = ISNULL(@v_vchStagingLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
									AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

									EXEC usp_manage_inventory @in_vchWHMasterID		= @v_vchWhMasterID
															, @in_vchOwnerID		= @v_vchOwnerID
															, @in_vchWHItemMasterID	= @v_vchWhItemMasterID
															, @in_vchLocationID		= @v_vchStagingLocationID
															, @in_vchStatusID		= @v_vchInvStatusID
															, @in_vchPalentLPN		= @v_vchStagingParentLPN
															, @in_vchLPN			= @v_vchStagingLPN
															, @in_fltQty			= @v_fltQtyPick
															, @in_fltQtyAllocate	= 0
															, @in_fltQtyIncoming	= 0
															, @in_vchInventoryType	= @v_vchOutboundNumber
															, @in_vchUserID			= @in_vchUserID
															, @in_vchReceiveDate	= @v_dtInvReceiveDate
															, @in_dtMFGDate			= @v_dtInvMfgDate
															, @in_vchInventoryID	= @v_vchInventoryID OUTPUT
															, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
															, @in_vchErrorCode		= @out_ErrorCode OUTPUT
															, @in_vchMessage		= @out_ErrorMessage OUTPUT	

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;

									--Update Volumn & Weight in from location
									IF @v_vchStagingLocationID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
												, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @v_vchStagingLocationID
										END
								END
							ELSE
								BEGIN
									SELECT @v_vchInventoryID = inventory_id
										,@v_vchAttributeGroupID = attribute_group_id
									FROM v_wms_inventory_data_by_id
									WHERE wh_master_id = @v_vchWhMasterID
									AND owner_id = @v_vchOwnerID
									AND location_id = @v_vchForkID
									AND wh_item_master_id = @v_vchWhItemMasterID
									AND inventory_status_id = @v_vchInvStatusID
									and receive_date = @v_dtInvReceiveDate
									AND ISNULL(parent_lpn,'') = ISNULL(@in_vchToParentLPN,'')
									AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@in_vchLot,'')
									AND ISNULL(expiry_date,'')= ISNULL(@in_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@in_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@in_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@in_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@in_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@in_vchAttribute5,'')

									EXEC usp_manage_inventory @in_vchWhMasterID		  = @v_vchWhMasterID
															, @in_vchOwnerID		  = @v_vchOwnerID
															, @in_vchWhItemMasterID   = @v_vchWhItemMasterID
															, @in_vchLocationID		  = @v_vchForkID
															, @in_vchStatusID		  = @v_vchInvStatusID
															, @in_vchPalentLPN		  = @in_vchToParentLPN
															, @in_vchLPN			  = @v_vchPickToLPN
															, @in_fltQty			  = @v_fltQtyPick
															, @in_fltQtyAllocate	  = 0
															, @in_fltQtyIncoming	  = 0
															, @in_vchInventoryType	  = @v_vchOutboundNumber
															, @in_vchUserID			  = @in_vchUserID
															, @in_vchReceiveDate	  = @v_dtInvReceiveDate
															, @in_dtMFGDate			  = @v_dtInvMfgDate	
															, @in_vchInventoryID	  = @v_vchInventoryID OUTPUT
															, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
															, @in_vchErrorCode		  = @out_ErrorCode OUTPUT
															, @in_vchMessage		  = @out_ErrorMessage OUTPUT	

									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;

									--Update Volumn & Weight in from location
									IF @v_vchForkID IS NOT NULL
										BEGIN
											UPDATE [dbo].[t_wms_location]
											   SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
												, total_weight =  ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
												, update_date = GETDATE()  
												, [update_by] = @in_vchUserID   
											 WHERE [location_id] = @v_vchForkID
										END
								END
								
							--update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET
								 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttributeGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
											@in_vchLot				= @in_vchLot
										, @in_vchExpiryDate			= @in_vchExpiryDate
										, @in_vchSerialNo			= @in_vchSerialNo
										, @in_vchAttribute1			= @in_vchAttribute1
										, @in_vchAttribute2			= @in_vchAttribute2
										, @in_vchAttribute3			= @in_vchAttribute3
										, @in_vchAttribute4			= @in_vchAttribute4
										, @in_vchAttribute5			= @in_vchAttribute5
										, @in_fltQty				= @v_fltQtyPick
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInventoryID
										, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSNControl
										, @in_vchExpiryDateControl	= @v_vchExpControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END	
						
							--Set ค่าว่าง = NULL
							BEGIN
							IF (ISNULL(@in_vchLot,'') = '')
								BEGIN
									SET @in_vchLot = NULL
								END
							IF (ISNULL(@in_vchExpiryDate,'') = '')
								BEGIN
									SET @in_vchExpiryDate = NULL
								END
							IF (ISNULL(@in_vchAttribute1,'') = '')
								BEGIN
									SET @in_vchAttribute1 = NULL
								END
							IF (ISNULL(@in_vchAttribute2,'') = '')
								BEGIN
									SET @in_vchAttribute2 = NULL
								END
							IF (ISNULL(@in_vchAttribute3,'') = '')
								BEGIN
									SET @in_vchAttribute3 = NULL
								END
							IF (ISNULL(@in_vchAttribute4,'') = '')
								BEGIN
									SET @in_vchAttribute4 = NULL
								END
							IF (ISNULL(@in_vchAttribute5,'') = '')
								BEGIN
									SET @in_vchAttribute5 = NULL
								END
							IF (ISNULL(@in_vchFromParentLPN,'') = '')
								BEGIN
									SET @in_vchFromParentLPN = NULL
								END
							IF (ISNULL(@in_vchToParentLPN,'') = '')
								BEGIN
									SET @in_vchToParentLPN = NULL
								END
							IF (ISNULL(@in_vchFromLPN,'') = '')
								BEGIN
									SET @in_vchFromLPN = NULL
								END
							IF (ISNULL(@v_vchPickToLPN,'') = '')
								BEGIN
									SET @v_vchPickToLPN = NULL
								END
							END

							---------------------------------------------------		
							-- Write Tran Log  
							---------------------------------------------------		
							IF (@RuleAutoStaging = 'YES')
							BEGIN
								--Write Lot Pick to STG
								INSERT INTO t_com_tran_log
									( app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, control_number
									, line_number
									, udf_1
									, udf_2
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'MOVE_DEST'
									, @v_vchApplicationName
									, 'Update pick to staging by load [Auto to Staging]'
									, @v_dtStartTime
									, DATEADD(millisecond,2,GETDATE())
									, @in_vchWarehouse
									, @in_vchWarehouse
									, @v_vchPickLocation
									, @v_vchStagingLocation
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @in_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, @v_fltInvQuantity - @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, @in_vchLot
									, @in_vchLot
									, @in_vchExpiryDate
									, @in_vchExpiryDate
									, @v_vchInvSerialNumber
									, @in_vchAttribute1
									, @in_vchAttribute1
									, @in_vchAttribute2
									, @in_vchAttribute2
									, @in_vchAttribute3
									, @in_vchAttribute3
									, @in_vchAttribute4
									, @in_vchAttribute4
									, @in_vchAttribute5
									, @in_vchAttribute5
									, @in_vchUserID 
									, @in_vchFromParentLPN
									, @in_vchToParentLPN
									, @in_vchFromLPN
									, @v_vchPickToLPN
									, @v_vchInvstatus
									, @v_vchInvstatus 
									, @v_vchOutboundNumber
									, @in_vchLoadID
									, @v_vchPickLineNumber
									, @in_vchTrackingNo
									, @v_vchOrderType
									, @in_vchDeviceID
									, @in_vchUserID
									, DATEADD(millisecond,2,GETDATE())
									, @v_vchPickLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)

								----------------------------------------
								--Insert For Checker RFID
								--ต้องทำตอน วาง STG
								----------------------------------------
								IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
									BEGIN
										IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @v_vchOutboundMasterID AND serial_number = @v_vchInvSerialNumber)
											BEGIN
												INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
														([checker_rfid_id]
														,[processing_status]
														,[outbound_order_master_id]
														,[serial_number]
														,[user_id]
														,[device]
														,[create_by]
														,[create_date])
													VALUES
														(NEWID()
														,'PENDING'
														,@v_vchOutboundMasterID
														,@v_vchInvSerialNumber
														,@in_vchUserID
														,@in_vchDeviceID
														,@in_vchUserID
														,GETDATE())
											END
									END
							END
							ELSE
							BEGIN
								--Write Log Pick to Fork
								INSERT INTO t_com_tran_log
								(     app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id] 
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status 
									, order_number
									, control_number
									, line_number 
									, device
									, create_by
									, create_date
									, pick_location
									, receive_date
									, mfg_date
									, input_quantity
									, input_uom
								)
								VALUES
								(     @in_vchApplicationID
									, 'OO_PICK'
									, 'SALES_ORDER'
									, @v_vchApplicationName
									, 'System Directed Picking (By Load)'
									, @v_dtStartTime
									, GETDATE()
									, @in_vchWarehouse
									, @in_vchWarehouse
									, @in_vchFromLocation
									, @in_vchForkLift
									, @v_vchOwnerCode
									, @v_vchOwnerCode
									, @in_vchItemNumber
									, @v_fltQtyPick
									, @v_vchBaseUomPrompt
									, @v_fltInvQuantity - @v_fltQtyPick 
									, @v_vchBaseUomPrompt
									, @in_vchLot
									, @in_vchLot
									, @in_vchExpiryDate
									, @in_vchExpiryDate
									, @v_vchInvSerialNumber
									, @in_vchAttribute1
									, @in_vchAttribute1
									, @in_vchAttribute2
									, @in_vchAttribute2
									, @in_vchAttribute3
									, @in_vchAttribute3
									, @in_vchAttribute4
									, @in_vchAttribute4
									, @in_vchAttribute5
									, @in_vchAttribute5
									, @in_vchUserID
									, @in_vchFromParentLPN
									, @in_vchToParentLPN
									, @in_vchFromLPN
									, @v_vchPickToLPN
									, @v_vchInvstatus
									, @v_vchInvstatus
									, @v_vchOutboundNumber
									, @in_vchLoadID
									, @v_vchPickLineNumber 
									, @in_vchDeviceID	
									, @in_vchUserID		
									, GETDATE()
									, @v_vchPickLocation
									, @v_dtInvReceiveDate
									, @v_dtInvMfgDate
									, @in_fltQty
									, @in_vchUOMPrompt
								)
							END

							--สำหรับ Check จำนวนที่สามารถหยิบได้ของ order นี้
							SET @v_fltRemainQtyCanPick = @v_fltRemainQtyCanPick - @v_fltQtyPick

							----สำหรับใช้ในการ Write Log เพื่อ update after_quantity
							--SET @v_fltInvQtyForCheck = @v_fltInvQtyForCheck - @v_fltQtyPick

							--Check จำนวนที่สามารถ Pick ได้ของ Order นี้ ถ้า pick ครบแล้วก็หยุด แล้วก็ทำของ pick order line ใหม่
							IF @v_fltRemainQtyCanPick = 0
								BREAK;

							FETCH NEXT FROM InventoryCursor INTO @v_vchInvID,@v_vchInvAttrGroupID,@v_vchInvSerialNumber,@v_dtInvMfgDate,@v_dtInvReceiveDate
						END
				END
			ELSE
				BEGIN
					-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
					SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,@v_vchLocalID,@in_vchItemNumber,@in_vchLot,@in_vchExpiryDate,@in_vchFromLPN,'@param5')			
					GOTO WRITE_PROC;
				END
			CLOSE InventoryCursor
			DEALLOCATE InventoryCursor
			 
			-- For Dashboard
			BEGIN
				DECLARE @v_vchDSToLocationID UNIQUEIDENTIFIER = NULL 
				IF @RuleAutoStaging = 'YES'
					BEGIN
						SET @v_vchDSToLocationID = @v_vchStagingLocationID 
					END
				ELSE
					BEGIN  
						SET @v_vchDSToLocationID = @v_vchForkID 
					END
				EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
												,@in_vchTransType	 = 'PICK'
												,@in_vchWhMasterID	 = @v_vchWhMasterID
												,@in_vchOwnerID		 = @v_vchOwnerID
												,@in_vchOwnerCode	 = @v_vchOwnerCode
												,@in_vchLocationID	 = @v_vchLocationID
												,@in_vchItemMasterID = @v_vchItemMasterID
												,@in_vchInvStatusID	 = @v_vchInvStatusID
												,@in_vchToWhMasterID = @v_vchWhMasterID
												,@in_vchToLocationID = @v_vchDSToLocationID
												,@in_vchToInvStatusID = @v_vchInvStatusID
												,@in_fltQuantity	 = @v_fltQtyCanPick
												,@in_vchUserID		 = @in_vchUserID
			END

			-------------------------------------------------------------------------------
			-- ตรวจสอบจำนวนรวมที่สามารถหยิบได้ กับจำนวนที่หยิบของ Order ถ้าไม่เหลือให้หยิบแล้วไม่ต้องทำงานต่อ
			-------------------------------------------------------------------------------
			SET @v_fltSumQtyCanPick = ROUND((@v_fltSumQtyCanPick - @v_fltQtyCanPick),@Round)
			IF @v_fltSumQtyCanPick = 0
				BREAK;

			FETCH NEXT FROM OutboundDetailCursor INTO @v_vchOutboundMasterID,@v_vchOutboundNumber,@v_vchOrderType,@v_vchOutboundPickMasterID,@v_vchOutboundPickDetailID,@v_vchOutboundDetailID,@v_vchLineNumber,@v_vchPickLineNumber,@v_fltQuantityPlan,@v_fltQuantityPick,@v_dtReceiveDate,@v_vchInvStatusID,@v_vchInvStatus,@v_vchPickLocation
			SET @v_nOutboundCursorRow = @v_nOutboundCursorRow + 1	--สำหรับ check record สุดท้ายของ loop เพื่อกรณีที่เป็น over pick จะให้ over pick ของ record สุดท้าย ที่ loop
		END	       
	CLOSE OutboundDetailCursor
	DEALLOCATE OutboundDetailCursor

	------------------------------------------------
	-- Update Order Status ถ้า Pick ครบแล้ว
	------------------------------------------------
	IF ((SELECT SUM(quantity_order - ISNULL(quantity_pick,0)) FROM t_wms_outbound_detail obDT
		 INNER JOIN t_wms_outbound_master obMS ON obDT.outbound_order_master_id = obMS.outbound_order_master_id
	     WHERE obMS.wh_master_id = @v_vchWhMasterID
		 AND obMS.load_id = @in_vchLoadID) <= 0)	--น้อยกว่าหรือเท่าศูนย์ เพราะมีกรณี over pick
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE wh_master_id = @v_vchWhMasterID AND load_id = @in_vchLoadID AND order_status NOT IN ('LOADING','LOADED')
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID, order_status = 'PICK', user_def1 = @in_vchTrackingNo 
			FROM t_wms_outbound_master obMS
			INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
			WHERE obMS.wh_master_id = @v_vchWhMasterID
			AND obMS.load_id = @in_vchLoadID
			AND ISNULL(obDT.quantity_pick,0) > 0
		END
	
	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@v_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','OutboundDetailCursor')>=-1
		BEGIN
			CLOSE OutboundDetailCursor;
			DEALLOCATE OutboundDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END	
				  
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData = 'Qty: ' + convert(varchar,@in_fltQty) + ' ' + @in_vchUOMPrompt;
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchLoadID,
			@in_vchData2 = @in_vchFromLocation,
			@in_vchData3 = @in_vchItemNumber,
			@in_vchData4 = @v_vchProcessData,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION;
	
	IF CURSOR_STATUS('global','OutboundDetailCursor')>=-1
		BEGIN
			CLOSE OutboundDetailCursor;
			DEALLOCATE OutboundDetailCursor;
		END

	IF CURSOR_STATUS('global','InventoryCursor')>=-1
		BEGIN
			CLOSE InventoryCursor;
			DEALLOCATE InventoryCursor;
		END

	IF (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@in_fltQty) + ' ' + @in_vchUOMPrompt;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchLoadID,
		@in_vchData2 = @in_vchFromLocation,
		@in_vchData3 = @in_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_item_by_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pick_item_by_lpn]
	@in_vchApplicationID	VARCHAR(40), 
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER  = NULL,
	@in_vchWhID				NVARCHAR(25) = NULL,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER, 
	@in_vchLocationID		UNIQUEIDENTIFIER,
	@in_vchLPN				NVARCHAR(25) = NULL,
	@in_vchForkLift			NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @c_vchObjName				NVARCHAR(50) = '[usp_outbound_update_pick_item]', -- The name that uniquely tags this object.
			@v_dtStartTime				DATETIME = GETDATE(), 
			@v_dtProcessDateTime		DATETIME = NULL, 
			@v_vchProcessData			NVARCHAR(255)= NULL,
			@v_vchApplicationName		NVARCHAR(50)= NULL, 
			@v_vchBeginTrans			BIT = 0,
			@Round						INT,

			@RulePickPack				NVARCHAR(3) = 'NO',
			@RuleAutoStaging			NVARCHAR(3) = 'NO',  
			@v_vchForkID				UNIQUEIDENTIFIER = NULL,

			--Outbound
			@v_vchOutboundOrderNumber	NVARCHAR(50),
			@v_vchOrderStatus			NVARCHAR(30) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerCode				NVARCHAR(50) = NULL,
			@v_vchPickBy				NVARCHAR(25) = NULL,

			--Item Master 
			@v_vchItemNumber			NVARCHAR(50)= NULL, 
			@v_vchLotControl			VARCHAR(5) = NULL,
			@v_vchExpControl			VARCHAR(5) = NULL,
			@v_vchSNControl				VARCHAR(5) = NULL,
			@v_vchAttribute1Control		VARCHAR(5) = NULL,
			@v_vchAttribute2Control		VARCHAR(5) = NULL,
			@v_vchAttribute3Control		VARCHAR(5) = NULL,
			@v_vchAttribute4Control		VARCHAR(5) = NULL,
			@v_vchAttribute5Control		VARCHAR(5) = NULL, 

			-- Item UOM
			@v_vchBaseItemUomID			UNIQUEIDENTIFIER,
			@v_vchBaseUomPrompt			NVARCHAR(40),
			@v_vchBaseUom				NVARCHAR(20), 
			@v_fltWidth					FLOAT = 0,  --item Uom
			@v_fltLength				FLOAT = 0,  --item Uom
			@v_fltHeight				FLOAT = 0,  --item Uom
			@v_fltGrossWeight			FLOAT = 0,  --item Uom
			@v_intPercentTolerance		FLOAT = 0,  --item Uom
			@v_intPercenToleranceWeight FLOAT = 0,  --item Uom
			@v_fltVolumn				FLOAT = 0,	--item Uom
			@v_fltTotalWeight			FLOAT = 0,	--item Uom 

			--Outbound Pick Detail Loop
			@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER = NULL,			
			@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchPickLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchPickLocation			NVARCHAR(50) = NULL,
			@v_vchParentLPN				NVARCHAR(25) = NULL,
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER  = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER  = NULL, 
			@v_vchLineNumber			NVARCHAR(10) = NULL, -- Outbound Detail
			@v_vchPickLineNumber		NVARCHAR(10) = NULL, -- Outbound Pick Detail
			@v_fltQuantityPlan			FLOAT = 0,
			@v_fltQuantityPick			FLOAT = 0,
			@v_fltQtyForPick			FLOAT = 0,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_dtMfgDate				DATE,
			@v_vchExpiryDate			NVARCHAR(50) = NULL, 
			@v_vchSerialNumber			NVARCHAR(100) = NULL, 
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL, 
			@v_dtReceiveDate			DATE,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL, 

			-- Auto STG
			@v_vchStagingLocationID		UNIQUEIDENTIFIER = NULL,
			@v_vchStagingLocation		NVARCHAR(50) = NULL,
			@v_vchPickToLPN				NVARCHAR(25) = NULL,

			--Inventory Source
			@v_vchInvID					UNIQUEIDENTIFIER = NULL,
			@v_vchInvAttrGroupID		UNIQUEIDENTIFIER = NULL ,
			@v_fltInvQuantity			FLOAT = NULL,
			@v_fltInvQtyAllcate			FLOAT = NULL,
			@v_dtInvMfgDate				DATE  = NULL,
			@v_vchInvSerialNumber		NVARCHAR(100)= NULL,
			@v_vchOutboundNewPickDetailID	UNIQUEIDENTIFIER = NULL,
			@v_vchNewPickLineNumber		NVARCHAR(10) = NULL,

			--Inventory Destination
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'
	SELECT TOP 1 @RuleAutoStaging = value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_STAGING' AND is_active = 'YES'	
	SELECT TOP 1 @v_vchForkID = location_id FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location = @in_vchForkLift AND is_active = 'YES'

	--------------------------------------------------
	-- Get Data in Outbound Master
	--------------------------------------------------
	SELECT @v_vchOutboundOrderNumber = obMS.outbound_order_number
		,@v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id
		,@v_vchOrderStatus = obMS.order_status
		,@v_vchOrderType = obMS.order_type
		,@v_vchOwnerID = obMS.owner_id 
		,@v_vchOwnerCode = own.owner_code
		,@v_vchPickBy = obMS.pick_by
	FROM t_wms_outbound_master obMS WITH (NOLOCK)
	INNER JOIN t_wms_owner own on obMS.owner_id = own.owner_id
	INNER JOIN t_wms_outbound_pick_master pickMS on obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	WHERE obMS.outbound_order_master_id = @in_vchOutboundMasterID
	IF ISNULL(@v_vchOutboundOrderNumber,'') = ''
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	IF(@v_vchOrderStatus = 'SHIP')
		BEGIN
			SET @out_ErrorCode = 'OUTBOUND_IS_SHIP_NOT_LOAD_PICK_UNPICK';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOutboundOrderNumber,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;
		END

	------------------------------------------------------
	-- ตรวจสอบ Multiple user pick
	------------------------------------------------------
	IF (((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_MULTI_USER_PICK' AND is_active = 'YES') = 'NO') AND (@v_vchPickBy <> @in_vchUserID))
		BEGIN
			--Multi User
			SET @out_ErrorCode = 'INFO-ANOTHER-USER-ALREADY-PICK'
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchPickBy,'@param2','@param3','@param4','@param5')
			GOTO WRITE_PROC;	
		END

	--------------------------------------------------------
	-- Validate Staging Location
	--------------------------------------------------------
	IF (@RuleAutoStaging = 'YES')
		BEGIN
			--Check Old STG = New STG
			SET @v_vchStagingLocationID = NULL
			SET @v_vchStagingLocation = NULL
			SELECT TOP 1 @v_vchStagingLocationID = pickDT.staging_location_id
				, @v_vchStagingLocation = loc.location 
			FROM t_wms_outbound_pick_detail pickDT
			INNER JOIN t_wms_outbound_pick_master pickMS on pickDT.outbound_pick_master_id = pickMS.outbound_pick_master_id
			INNER JOIN t_wms_location loc ON pickDT.staging_location_id = loc.location_id
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND pickDT.staging_location_id IS NOT NULL
			AND pickDT.is_override = 'NO'
				
			IF @v_vchStagingLocationID IS NULL
			BEGIN
				SELECT TOP 1 @v_vchStagingLocationID = location_id
					,@v_vchStagingLocation = location 
				FROM t_wms_location 
				WHERE wh_master_id = @in_vchWhMasterID 
				AND loc_type = 'STG' 
				AND is_active = 'YES'
				IF (@v_vchStagingLocationID IS NULL)
				BEGIN
					SET @out_ErrorCode = 'STG_LOCATION_NOT_FOUND';
					SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC
				END
			END 
		END


		--Check หยิบเต็ม Pallet หรือไม่
		IF EXISTS (SELECT 1 FROM (SELECT outbound_pick_detail_id
								,outbound_order_detail_id
								,location_id
								,parent_lpn
								,lpn
								,wh_item_master_id
								,lot_number
								,expiry_date
								,attribute1
								,attribute2
								,attribute3
								,attribute4
								,attribute5
								,receive_date 
								,ROUND(ISNULL(quantity_plan,0) - ISNULL(quantity_pick,0),@Round) qty_can_pick
						  FROM t_wms_outbound_pick_detail 
						  WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
						  AND location_id = @in_vchLocationID
						  AND is_override = 'NO'
						  AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'') 
						  ) pickDT
					INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
					INNER JOIN t_wms_inventory_status invST ON obDT.default_item_status = invST.inv_status
					INNER JOIN v_wms_inventory_data_by_id inv ON pickDT.location_id = inv.location_id
															AND ISNULL(pickDT.parent_lpn,'') = ISNULL(inv.parent_lpn,'')
															AND ISNULL(pickDT.lpn,'') = ISNULL(inv.lpn,'')
															AND invST.inventory_status_id = inv.inventory_status_id
															AND pickDT.wh_item_master_id = inv.wh_item_master_id
															AND ISNULL(pickDT.lot_number,'') = ISNULL(inv.lot_number,'') 
															AND ISNULL(pickDT.expiry_date,'')= ISNULL(inv.expiry_date,'')
															AND ISNULL(pickDT.attribute1,'') = ISNULL(inv.attribute1,'') 
															AND ISNULL(pickDT.attribute2,'') = ISNULL(inv.attribute2,'') 
															AND ISNULL(pickDT.attribute3,'') = ISNULL(inv.attribute3,'') 
															AND ISNULL(pickDT.attribute4,'') = ISNULL(inv.attribute4,'') 
															AND ISNULL(pickDT.attribute5,'') = ISNULL(inv.attribute5,'')
															AND ISNULL(pickDT.receive_date,'') = ISNULL(inv.receive_date,'')
					WHERE ISNULL(inv.quantity,0) <> ISNULL(pickDT.qty_can_pick,0))
			BEGIN
				SET @v_vchPickToLPN = @v_vchOutboundOrderNumber
			END
		ELSE	
			BEGIN
				SET @v_vchPickToLPN = @in_vchLPN
			END

BEGIN TRANSACTION;
SET @v_vchBeginTrans = 1;

	NEXT_PICK_LIST:
		BEGIN --Clear Value 
			SET @v_vchOutboundPickDetailID	= NULL
			SET @v_vchOutboundDetailID		= NULL
			SET @v_vchPickLocationID		= NULL
			SET @v_vchPickLocation			= NULL
			SET @v_vchParentLPN				= NULL
			SET @v_vchWhItemMasterID		= NULL
			SET @v_vchItemMasterID			= NULL
			SET @v_vchLineNumber			= NULL
			SET @v_vchPickLineNumber		= NULL
			SET @v_fltQuantityPlan			= NULL
			SET @v_fltQuantityPick			= NULL
			SET @v_fltQtyForPick			= NULL
			SET @v_vchLotNumber				= NULL
			SET @v_dtMfgDate				= NULL
			SET @v_vchExpiryDate			= NULL
			SET @v_vchSerialNumber			= NULL
			SET @v_vchAttribute1			= NULL
			SET @v_vchAttribute2			= NULL
			SET @v_vchAttribute3			= NULL
			SET @v_vchAttribute4			= NULL
			SET @v_vchAttribute5			= NULL
			SET @v_dtReceiveDate			= NULL
			SET @v_vchInvStatusID			= NULL
			SET @v_vchInvStatus				= NULL

			SET @v_vchItemNumber			= NULL
			SET @v_vchLotControl			= NULL
			SET @v_vchExpControl			= NULL
			SET @v_vchSNControl				= NULL
			SET @v_vchAttribute1Control		= NULL
			SET @v_vchAttribute2Control		= NULL
			SET @v_vchAttribute3Control		= NULL
			SET @v_vchAttribute4Control		= NULL
			SET @v_vchAttribute5Control		= NULL

			SET @v_vchBaseItemUomID			= NULL
			SET @v_vchBaseUomPrompt			= NULL
			SET @v_vchBaseUom				= NULL
			SET @v_fltWidth					= NULL
			SET @v_fltLength				= NULL
			SET @v_fltHeight				= NULL
			SET @v_fltGrossWeight			= NULL
			SET @v_intPercentTolerance		= NULL
			SET @v_intPercenToleranceWeight = NULL
			SET @v_fltVolumn				= NULL
			SET @v_fltTotalWeight			= NULL

			SET @v_vchInvID					= NULL
			SET @v_vchInvAttrGroupID		= NULL
			SET @v_fltInvQuantity			= NULL
			SET @v_fltInvQtyAllcate			= NULL
			SET @v_dtInvMfgDate				= NULL
			SET @v_vchInvSerialNumber		= NULL 
		END

		SELECT TOP 1 @v_vchOutboundPickDetailID	= pickDT.outbound_pick_detail_id
			, @v_vchOutboundDetailID		= pickDT.outbound_order_detail_id
			, @v_vchPickLocationID			= pickDT.location_id
			, @v_vchPickLocation			= loc.location
			, @v_vchParentLPN				= pickDT.parent_lpn
			, @v_vchWhItemMasterID			= pickDT.wh_item_master_id
			, @v_vchItemMasterID			= obDT.item_master_id
			, @v_vchLineNumber				= obDT.line_number
			, @v_vchPickLineNumber			= pickDT.pick_line_number
			, @v_fltQuantityPlan			= ISNULL(pickDT.quantity_plan,0)
			, @v_fltQuantityPick			= ISNULL(pickDT.quantity_pick,0)
			, @v_fltQtyForPick				= ROUND(ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0),@Round)
			, @v_vchLotNumber				= pickDT.lot_number
			, @v_dtMfgDate					= pickDT.mfg_date
			, @v_vchExpiryDate				= pickDT.expiry_date
			, @v_vchSerialNumber			= pickDT.serial_number 
			, @v_vchAttribute1				= pickDT.attribute1
			, @v_vchAttribute2				= pickDT.attribute2
			, @v_vchAttribute3				= pickDT.attribute3
			, @v_vchAttribute4				= pickDT.attribute4
			, @v_vchAttribute5				= pickDT.attribute5
			, @v_dtReceiveDate				= pickDT.receive_date
			, @v_vchInvStatusID				= invST.inventory_status_id
			, @v_vchInvStatus				= obDT.default_item_status
		FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)  
		INNER JOIN t_wms_outbound_detail obDT WITH (NOLOCK) ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
		INNER JOIN t_wms_location loc WITH (NOLOCK) ON loc.location_id = pickDT.location_id
		INNER JOIN t_wms_inventory_status invST WITH (NOLOCK) ON obDT.default_item_status = invST.inv_status
		WHERE pickDT.outbound_pick_master_id = @v_vchOutboundPickMasterID
		AND pickDT.is_override = 'NO' 
		AND pickDT.location_id = @in_vchLocationID
		AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'') 
		AND ROUND(ISNULL(pickDT.quantity_plan,0) - ISNULL(pickDT.quantity_pick,0),@Round) > 0
		ORDER BY obDT.line_number, pickDT.pick_line_number

		IF @v_vchOutboundPickDetailID is null
			BEGIN
				SET @out_ErrorCode = 'INFO-NOT-FOUND-PLAN-FOR-PICK'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		-- Get item_master_id
		--------------------------------------------------
		SELECT TOP 1 @v_vchItemNumber = item.item_number
			, @v_vchLotControl = item.lot_control
			, @v_vchExpControl = item.expiry_date_control
			, @v_vchSNControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control 
		FROM t_wms_item item WITH (NOLOCK)
		WHERE item_master_id = @v_vchItemMasterID
		IF (ISNULL(@v_vchItemNumber,'') = '')
			BEGIN
				--ITEM NUMBER [0] NOT EXIST
				SET @out_ErrorCode = 'ITEM_NUMBER_NOT_FOUND'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		--Get & Check Item UOM
		--------------------------------------------------
		SELECT @v_vchBaseItemUomID = item_uom_id
			,@v_vchBaseUomPrompt = uom_prompt
			,@v_vchBaseUom = uom
			,@v_fltWidth = ISNULL(width,0)
			,@v_fltLength = ISNULL(length,0)
			,@v_fltHeight = ISNULL(height,0)
			,@v_fltGrossWeight = ISNULL(gross_weight,0)
			,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
			,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
		FROM t_wms_item_uom WITH (NOLOCK)
		WHERE item_master_id = @v_vchItemMasterID 
		AND primary_uom = 'YES'
		AND is_active = 'YES'	
		IF (@v_vchBaseItemUomID IS NULL)
			BEGIN
				SET @out_ErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchBaseUom,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		--Check Serial ต้องไม่ได้จองที่ order อื่น
		--------------------------------------------------
		IF EXISTS (SELECT TOP 1 pickDT.outbound_pick_detail_id FROM t_wms_outbound_pick_detail pickDT WITH (NOLOCK)
					WHERE pickDT.outbound_pick_master_id <> @v_vchOutboundPickMasterID
					AND pickDT.is_override = 'NO'
					AND pickDT.location_id = @v_vchPickLocationID
					AND pickDT.wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(pickDT.parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
					AND ISNULL(pickDT.lpn,'') = ISNULL(@in_vchLPN,'')
					AND ISNULL(pickDT.lot_number,'') = ISNULL(@v_vchLotNumber,'')
					AND ISNULL(pickDT.expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
					AND ISNULL(pickDT.attribute1,'') = ISNULL(@v_vchAttribute1,'')
					AND ISNULL(pickDT.attribute2,'') = ISNULL(@v_vchAttribute2,'')
					AND ISNULL(pickDT.attribute3,'') = ISNULL(@v_vchAttribute3,'')
					AND ISNULL(pickDT.attribute4,'') = ISNULL(@v_vchAttribute4,'')
					AND ISNULL(pickDT.attribute5,'') = ISNULL(@v_vchAttribute5,'')
					AND ISNULL(pickDT.serial_number,'') = ISNULL(@v_vchSerialNumber,'')
					AND ISNULL(pickDT.quantity_pick,0) = 0) 
					AND @v_vchSNControl = 'FULL'
			BEGIN
				-- Serial นี้ถูกจองโดย Outbound Order อื่นแล้ว
				SET @out_ErrorCode = 'INFO_SERIAL_IS_ALLOCATE_BY_ANOTHER_ORDER'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchSerialNumber,'@param2','@param3','@param4','@param5')			
				GOTO WRITE_PROC
			END
 
		--------------------------------------------------
		--Get Inventory
		--------------------------------------------------
		SELECT @v_vchInvID = inventory_id
			,@v_vchInvAttrGroupID = attribute_group_id 
			,@v_fltInvQuantity = quantity
			,@v_fltInvQtyAllcate = quantity_allocated
			,@v_dtInvMfgDate = mfg_date 
			,@v_vchInvSerialNumber = serial_number
		FROM v_wms_inventory_data_serial_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND location_id = @v_vchPickLocationID 
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
		AND inventory_status_id = @v_vchInvStatusID 
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
		AND receive_date = @v_dtReceiveDate
 
		--------------------------------------------------
		--Check Inventory
		--------------------------------------------------
		 IF @v_vchInvID IS NULL
			BEGIN
				-- ไม่พบข้อมูลสินค้าที่ต้องการ Pick ใน Inventory
				SET @out_ErrorCode = 'INFO-NOT-FOUND-DATA-INVENTORY'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC
			END

		--------------------------------------------------
		--Check qty pick <= qty Inv
		--หยิบตาม LPN ต้องเป็นการหยิบจำนวนทั้งหมดเท่านั้น
		--------------------------------------------------
		IF ROUND(@v_fltInvQuantity,@Round) < ROUND(@v_fltQtyForPick,@Round)
			BEGIN
				SET @out_ErrorCode = 'INV_QTY_NOT_ENOUGH'
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@v_vchLotNumber,@v_vchExpiryDate,@in_vchLPN,'@param5')			
				GOTO WRITE_PROC
			END

		-----------------------------------------------------
		-- Validate Duplicate Serial Number ใน Pick Detail
		-----------------------------------------------------
		IF (@v_vchSNControl = 'FULL')
			BEGIN
				SET @v_fltInvQuantity = 1
				SET @v_fltQtyForPick = 1   -- กรณีของ Serial Qty Pick = 1
				IF EXISTS(SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
							WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
							AND wh_item_master_id = @v_vchWhItemMasterID 
							AND serial_number = @v_vchInvSerialNumber
							AND ISNULL(quantity_pick,0) > 0
							AND is_override = 'NO')
					BEGIN
						SET @out_ErrorCode = 'SERIAL_IS_PICK_COMPLETE';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchInvSerialNumber,@v_vchItemNumber,'@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END
 
		---------------------------------------------------		
		--Update Outbound Detail
		---------------------------------------------------		
		UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyForPick,@Round)
			,quantity_stage = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyForPick,@Round)
			,item_status = 'PICK'
		WHERE outbound_order_master_id = @in_vchOutboundMasterID 
		AND outbound_order_detail_id = @v_vchOutboundDetailID 
		AND wh_item_master_id = @v_vchWhItemMasterID 
		AND line_number = @v_vchLineNumber
 
		----------------------------------------------------------------
		--Insert/Update Outbound Pick Detail
		----------------------------------------------------------------
		IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
					WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
					AND is_override = 'NO'
					AND receive_date = @v_dtReceiveDate
					AND (CASE WHEN quantity_pick > 0 THEN ISNULL(pick_to_lpn,'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN @in_vchLPN ELSE '' END)
					AND (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),pick_location_id),'') ELSE '' END) = (CASE WHEN quantity_pick > 0 THEN ISNULL(CONVERT(VARCHAR(36),@v_vchForkID),'') ELSE '' END)) OR @v_vchSNControl = 'FULL'
			BEGIN
				--กรณีที่ใช้ fork เดิม Update ค่าได้เลย
				UPDATE t_wms_outbound_pick_detail SET 
					  quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyForPick,@Round)
					, quantity_stage	  = ROUND(ISNULL(quantity_stage,0) + @v_fltQtyForPick,@Round) 
					, pick_location_id    = @v_vchForkID
					, pick_to_parent_lpn  = @v_vchParentLPN
					, pick_to_lpn		  = @v_vchPickToLPN
					, staging_location_id = @v_vchStagingLocationID
					, staging_parent_lpn  = @v_vchParentLPN
					, staging_lpn		  = @v_vchPickToLPN 
					, pick_status         = 'YES'
					, start_date_time	  = ISNULL(start_date_time,GETDATE())
					, end_date_time		  = GETDATE()
					, serial_number		  = @v_vchInvSerialNumber
				WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID
			END
		ELSE
			BEGIN
				--Insert New Pick Detail
				--1. ลบยอดจำนวนจากรายการเดิม
				UPDATE t_wms_outbound_pick_detail SET quantity_plan = ROUND(ISNULL(quantity_plan,0) - @v_fltQtyForPick,@Round)
				WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

				NEW_PICK_DETAIL_AUTO_STG:

				--Check ว่ามี recode เดิมหรือไม่ ถ้ามีให้ทำการ update
				SET @v_vchOutboundNewPickDetailID = NULL
				SELECT @v_vchOutboundNewPickDetailID = outbound_pick_detail_id FROM t_wms_outbound_pick_detail
				WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
				AND outbound_order_detail_id = @v_vchOutboundDetailID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND location_id = @v_vchPickLocationID
				AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'')
				AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
				AND ISNULL(expiry_date,'') = ISNULL(@v_vchExpiryDate,'')
				AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
				AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
				AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
				AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
				AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
				AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
				AND pick_location_id = @v_vchForkID
				AND ISNULL(pick_to_lpn,'') = ISNULL(@v_vchPickToLPN,'') 
				AND receive_date = @v_dtReceiveDate
				AND is_override = 'NO'
				IF (@v_vchOutboundNewPickDetailID IS NOT NULL)
					BEGIN
						UPDATE t_wms_outbound_pick_detail SET 
							  quantity_plan		  = ROUND(ISNULL(quantity_plan,0) + @v_fltQtyForPick,@Round)
							, quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @v_fltQtyForPick,@Round)
							, quantity_stage	  = ROUND(ISNULL(quantity_stage,0) + @v_fltQtyForPick,@Round)
							, pick_location_id    = @v_vchForkID
							, pick_to_parent_lpn  = @v_vchParentLPN
							, pick_to_lpn		  = @v_vchPickToLPN
							, staging_location_id = @v_vchStagingLocationID
							, staging_parent_lpn  = @v_vchParentLPN
							, staging_lpn		  = @v_vchPickToLPN 
							, pick_status         = 'YES'
							, start_date_time	  = ISNULL(start_date_time,GETDATE())
							, end_date_time		  = GETDATE()
							, serial_number		  = @v_vchInvSerialNumber
						WHERE outbound_pick_detail_id = @v_vchOutboundNewPickDetailID
					END
				ELSE
					BEGIN
						--2. new record ใหม่
						SET @v_vchOutboundNewPickDetailID = NEWID()
						SELECT @v_vchNewPickLineNumber = MAX(pick_line_number) FROM t_wms_outbound_pick_detail 
						WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
						IF (@v_vchNewPickLineNumber IS NULL)
							BEGIN SET @v_vchNewPickLineNumber = '00001'; END
						ELSE
							BEGIN SET @v_vchNewPickLineNumber = Right('0000' + CONVERT(NVARCHAR,@v_vchNewPickLineNumber + 1),5); END

						INSERT INTO [dbo].[t_wms_outbound_pick_detail]
								([outbound_pick_detail_id]
								,[outbound_pick_master_id]
								,[outbound_order_detail_id]
								,[pick_line_number]
								,[location_id]
								,[pick_location_id]
								,[pick_to_lpn]
								,[pick_to_parent_lpn]
								,[wh_item_master_id]
								,[quantity_plan]
								,[quantity_pick] 
								,[quantity_stage]
								,[quantity_pack]
								,[quantity_load]
								,[quantity_ship]
								,[short_pick_reason_id]
								,[parent_lpn]
								,[lpn]
								,[lot_number]
								,[expiry_date]
								,[serial_number]
								,[attribute1]
								,[attribute2]
								,[attribute3]
								,[attribute4]
								,[attribute5]
								,[user_assign]
								,[staging_location_id]
								,[staging_parent_lpn]
								,[staging_lpn]
								,[next_location_reason_id]
								,[over_pick_reason_id]
								,[dock_door_id]
								,[dock_door_parent_lpn]
								,[dock_door_lpn]
								,[pick_status]
								,[load_status]
								,[ship_status]
								,[inventory_id]
								,[pack_status]
								,[pick_generate_method]
								,[is_allocate]
								,[is_override]
								,[pick_override_reason]
								,[receive_date]
								,[mfg_date]
								,[is_active]
								,[start_date_time]
								,[end_date_time]
								,[create_date]
								,[create_by])
						(SELECT TOP 1 @v_vchOutboundNewPickDetailID							--[outbound_pick_detail_id]
								, outbound_pick_master_id									--[outbound_pick_master_id]
								, outbound_order_detail_id									--[outbound_order_detail_id]
								, @v_vchNewPickLineNumber									--[pick_line_number]
								, location_id												--[location_id]
								, @v_vchForkID												--[pick_location_id]
								, @v_vchPickToLPN											--[pick_to_lpn]
								, @v_vchParentLPN											--[pick_to_parent_lpn]
								, wh_item_master_id											--[wh_item_master_id]
								, ROUND(@v_fltQtyForPick,@Round)	--quantity_plan			--[quantity_plan]
								, ROUND(@v_fltQtyForPick,@Round)	--quantity_pick			--[quantity_pick] 
								, ROUND(@v_fltQtyForPick,@Round)	--quantity_stage		--[quantity_stage]
								, 0															--[quantity_pack]
								, 0															--[quantity_load]
								, 0															--[quantity_ship]
								, short_pick_reason_id										--[short_pick_reason_id]
								, parent_lpn												--[parent_lpn]
								, lpn														--[lpn]
								, lot_number												--[lot_number]
								, expiry_date												--[expiry_date]
								, @v_vchInvSerialNumber										--[serial_number]
								, attribute1												--[attribute1]
								, attribute2												--[attribute2]
								, attribute3												--[attribute3]
								, attribute4												--[attribute4]
								, attribute5												--[attribute5]
								, user_assign												--[user_assign]
								, @v_vchStagingLocationID									--[staging_location_id]
								, @v_vchParentLPN											--[staging_parent_lpn]
								, @v_vchPickToLPN											--[staging_lpn]
								, next_location_reason_id									--[next_location_reason_id]
								, over_pick_reason_id										--[over_pick_reason_id]
								, dock_door_id												--[dock_door_id]
								, dock_door_parent_lpn										--[dock_door_parent_lpn]
								, dock_door_lpn												--[dock_door_lpn]
								, 'YES'														--[pick_status]
								, 'NO'														--[load_status]
								, 'NO'														--[ship_status]
								, inventory_id												--[inventory_id]
								, pack_status												--[pack_status]
								, pick_generate_method										--[pick_generate_method]
								, is_allocate												--[is_allocate]
								, 'NO'														--[is_override]
								, pick_override_reason										--[pick_override_reason]
								, @v_dtReceiveDate											--[receive_date]
								, mfg_date													--[mfg_date]
								, is_active													--[is_active]
								, GETDATE()													--[start_date_time]
								, GETDATE()													--[end_date_time]
								, GETDATE()													--[create_date]
								, @in_vchUserID												--[create_by])
							FROM t_wms_outbound_pick_detail
							WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID)
					END

				--นำ ID ของ Record ใหม่ไปใช้แทน ID เก่า
				SET @v_vchOutboundPickDetailID = @v_vchOutboundNewPickDetailID
			END

		----------------------------------------------------------------
		-- Insert/Update Pack Detail
		----------------------------------------------------------------
		IF (@RulePickPack = 'YES')
			BEGIN
				UPDATE t_wms_outbound_pick_detail SET 
						quantity_pack = ROUND(ISNULL(quantity_pack,0) + @v_fltQtyForPick,@Round)
					, end_date_time = GETDATE()
				WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

				---------------------------------------------------
				--Insert/Update Pack Detail
				---------------------------------------------------
				PRINT 'Pick and Pack'
				IF EXISTS(SELECT lpn_pack FROM t_wms_outbound_pack_detail WITH (NOLOCK)
									WHERE outbound_order_master_id = @in_vchOutboundMasterID
									AND pack_location_id = @v_vchForkID
									AND lpn_pack = @v_vchPickToLPN 
									AND wh_item_master_id = @v_vchWhItemMasterID 
									AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
									AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,''))
					BEGIN
						UPDATE t_wms_outbound_pack_detail SET 
								quantity_pack = ROUND(quantity_pack + @v_fltQtyForPick,@Round)
							,quantity_stage = ROUND(quantity_stage + @v_fltQtyForPick,@Round)
						WHERE outbound_order_master_id = @in_vchOutboundMasterID 
						AND pack_location_id = @v_vchForkID
						AND lpn_pack = @v_vchPickToLPN 
						AND wh_item_master_id = @v_vchWhItemMasterID 
						AND outbound_pick_detail_id = @v_vchOutboundPickDetailID
						AND ISNULL(serial_number,'') = ISNULL(@v_vchInvSerialNumber,'')
					END
				ELSE
					BEGIN
						INSERT INTO t_wms_outbound_pack_detail
						(     outbound_order_master_id
							, outbound_pick_detail_id
							, lpn_pack
							, pack_location_id
							, wh_item_master_id
							, quantity_pack
							, quantity_stage
							, lot_number
							, expiry_date
							, serial_number
							, [attribute1]
							, [attribute2]
							, [attribute3]
							, [attribute4]
							, [attribute5]
							, item_uom_id
							, [staging_location_id]
							, [staging_parent_lpn]
							, [staging_lpn]
							, create_by
						)
						VALUES
						(     @in_vchOutboundMasterID
							, @v_vchOutboundPickDetailID
							, @v_vchPickToLPN
							, @v_vchForkID
							, @v_vchWhItemMasterID
							, ROUND(@v_fltQtyForPick,@Round)
							, ROUND(@v_fltQtyForPick,@Round)
							, @v_vchLotNumber
							, @v_vchExpiryDate
							, @v_vchInvSerialNumber
							, @v_vchAttribute1
							, @v_vchAttribute2
							, @v_vchAttribute3
							, @v_vchAttribute4
							, @v_vchAttribute5
							, @v_vchBaseItemUomID
							, @v_vchStagingLocationID
							, @v_vchParentLPN
							, @in_vchLPN
							, @in_vchUserID
						)
					END
			END
		 
		---------------------------------------------------
		--Calculate Volumn & Weight
		---------------------------------------------------
		IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
		BEGIN
			SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQtyForPick,2)
			SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQtyForPick,2)
		END
		 
		---------------------------------------------------
		-- Manage source Inventory data
		---------------------------------------------------
		BEGIN
			--Update Volumn & Weight in from location
			IF @v_vchPickLocationID IS NOT NULL
				BEGIN
					UPDATE [dbo].[t_wms_location]
						SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
						, total_weight =  ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
						, update_date = GETDATE()  
						, [update_by] = @in_vchUserID   
					WHERE [location_id] = @v_vchPickLocationID
				END

			UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyForPick,@Round)
				,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - @v_fltQtyForPick,@Round)
				,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
				,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
			WHERE inventory_id = @v_vchInvID 
			AND attribute_group_id = @v_vchInvAttrGroupID
			 
			IF (@v_vchSNControl = 'FULL')
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyForPick,@Round) 
					WHERE inventory_id = @v_vchInvID 
					AND attribute_group_id = @v_vchInvAttrGroupID 
					AND attribute_value = @v_vchInvSerialNumber
					AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END

			IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(ISNULL(quantity,0) - @v_fltQtyForPick,@Round)
						,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - @v_fltQtyForPick,@Round)
					WHERE inventory_id = @v_vchInvID 
					AND attribute_group_id = @v_vchInvAttrGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END
		END

		------------------------------------------------
		-- Clear Inventory ที่หยิบของหมดแล้ว
		------------------------------------------------
		DELETE FROM t_wms_inventory_attribute WHERE inventory_id = @v_vchInvID AND quantity <= 0
		DELETE FROM t_wms_inventory WHERE inventory_id = @v_vchInvID AND quantity <= 0  

		--------------------------------------------
		--Manage Destination inventory
		--------------------------------------------
		SET @v_vchInventoryID = NULL
		SET @v_vchAttributeGroupID = NULL
		 
		SELECT @v_vchInventoryID = inventory_id
			,@v_vchAttributeGroupID = attribute_group_id
		FROM v_wms_inventory_data_by_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND location_id = @v_vchStagingLocationID
		AND wh_item_master_id = @v_vchWhItemMasterID
		AND inventory_status_id = @v_vchInvStatusID
		and receive_date = @v_dtReceiveDate
		AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
		AND ISNULL(lpn,'') = ISNULL(@v_vchPickToLPN,'')
		AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
		AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
		AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
		AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
		AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
		AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
		AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

		EXEC usp_manage_inventory @in_vchWhMasterID		= @in_vchWhMasterID
								, @in_vchOwnerID		= @v_vchOwnerID
								, @in_vchWHItemMasterID	= @v_vchWhItemMasterID
								, @in_vchLocationID		= @v_vchStagingLocationID
								, @in_vchStatusID		= @v_vchInvStatusID
								, @in_vchPalentLPN		= @v_vchParentLPN
								, @in_vchLPN			= @v_vchPickToLPN
								, @in_fltQty			= @v_fltQtyForPick
								, @in_fltQtyAllocate	= 0
								, @in_fltQtyIncoming	= 0
								, @in_vchInventoryType	= @v_vchOutboundOrderNumber
								, @in_vchUserID			= @in_vchUserID
								, @in_vchReceiveDate	= @v_dtReceiveDate
								, @in_dtMFGDate			= @v_dtInvMfgDate
								, @in_vchInventoryID	= @v_vchInventoryID OUTPUT
								, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
								, @in_vchErrorCode		= @out_ErrorCode OUTPUT
								, @in_vchMessage		= @out_ErrorMessage OUTPUT	

		IF (@out_ErrorCode <> '0')
			GOTO WRITE_PROC;

		--Update Volumn & Weight in from location
		IF @v_vchStagingLocationID IS NOT NULL
			BEGIN
				UPDATE [dbo].[t_wms_location]
					SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
					, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
					, update_date = GETDATE()  
					, [update_by] = @in_vchUserID   
					WHERE [location_id] = @v_vchStagingLocationID
			END
			 

		--update volumn & weight ของ LPN
		UPDATE t_wms_inventory SET
				volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
			,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
		WHERE inventory_id = @v_vchInventoryID
		AND attribute_group_id = @v_vchAttributeGroupID

		IF ('FULL' IN (@v_vchLotControl,@v_vchExpControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
			BEGIN
				EXEC usp_manage_inventory_attribute 
					  @in_vchLot				= @v_vchLotNumber
					, @in_vchExpiryDate			= @v_vchExpiryDate
					, @in_vchSerialNo			= @v_vchSerialNumber
					, @in_vchAttribute1			= @v_vchAttribute1
					, @in_vchAttribute2			= @v_vchAttribute2
					, @in_vchAttribute3			= @v_vchAttribute3
					, @in_vchAttribute4			= @v_vchAttribute4
					, @in_vchAttribute5			= @v_vchAttribute5
					, @in_fltQty				= @v_fltQtyForPick
					, @in_fltQtyAllocate		= 0
					, @in_fltQtyIncoming		= 0
					, @in_vchInventoryID		= @v_vchInventoryID
					, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
					, @in_vchLotControl			= @v_vchLotControl
					, @in_vchSNControl			= @v_vchSNControl
					, @in_vchExpiryDateControl	= @v_vchExpControl
					, @in_vchAttribute1Control	= @v_vchAttribute1Control
					, @in_vchAttribute2Control	= @v_vchAttribute2Control
					, @in_vchAttribute3Control	= @v_vchAttribute3Control
					, @in_vchAttribute4Control	= @v_vchAttribute4Control
					, @in_vchAttribute5Control	= @v_vchAttribute5Control
					, @in_vchUserID				= @in_vchUserID
					, @in_vchErrorCode			= @out_ErrorCode OUTPUT
					, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
				IF(@out_ErrorCode <> '0')
					GOTO WRITE_PROC;
			END

		---------------------------------------------------		
		-- Write Tran Log  
		---------------------------------------------------
		INSERT INTO t_com_tran_log
			( app_id
			, tran_type
			, sub_tran_type
			, [app_name]
			, [description]
			, start_tran_datetime
			, end_tran_datetime
			, warehouse
			, to_warehouse
			, location
			, to_location
			, [owner]
			, to_owner
			, item_number
			, quantity
			, quantity_uom
			, after_quantity
			, after_quantity_uom
			, lot_number
			, after_lot_number
			, [expiry_date]
			, after_expiry_date
			, serial_number
			, [attribute1]
			, [after_attribute1]
			, [attribute2]
			, [after_attribute2]
			, [attribute3]
			, [after_attribute3]
			, [attribute4]
			, [after_attribute4]
			, [attribute5]
			, [after_attribute5]
			, [user_id] 
			, parent_lpn
			, after_parent_lpn
			, lpn
			, after_lpn
			, [status]
			, after_status 
			, order_number
			, line_number
			, udf_1
			, device
			, create_by
			, create_date
			, pick_location
			, receive_date
			, mfg_date
			, input_quantity
			, input_uom
		)
		VALUES
		(     @in_vchApplicationID
			, 'OO_PICK'
			, 'MOVE_DEST'
			, @v_vchApplicationName
			, 'Update pick LPN to staging [Auto to Staging]'
			, @v_dtStartTime
			, DATEADD(millisecond,2,GETDATE())
			, @in_vchWhID
			, @in_vchWhID
			, @v_vchPickLocation
			, @v_vchStagingLocation
			, @v_vchOwnerCode
			, @v_vchOwnerCode
			, @v_vchItemNumber
			, @v_fltQtyForPick
			, @v_vchBaseUom
			, ROUND(@v_fltInvQuantity - @v_fltQtyForPick,@Round)
			, @v_vchBaseUom
			, @v_vchLotNumber
			, @v_vchLotNumber
			, @v_vchExpiryDate
			, @v_vchExpiryDate
			, @v_vchInvSerialNumber
			, @v_vchAttribute1
			, @v_vchAttribute1
			, @v_vchAttribute2
			, @v_vchAttribute2
			, @v_vchAttribute3
			, @v_vchAttribute3
			, @v_vchAttribute4
			, @v_vchAttribute4
			, @v_vchAttribute5
			, @v_vchAttribute5
			, @in_vchUserID 
			, @v_vchParentLPN
			, @v_vchParentLPN
			, @in_vchLPN
			, @v_vchPickToLPN
			, @v_vchInvstatus
			, @v_vchInvstatus 
			, @v_vchOutboundOrderNumber
			, @v_vchPickLineNumber
			, NULL 
			, @in_vchDeviceID
			, @in_vchUserID
			, DATEADD(millisecond,2,GETDATE())
			, @v_vchPickLocation
			, @v_dtReceiveDate
			, @v_dtInvMfgDate
			, @v_fltQtyForPick
			, @v_vchBaseUomPrompt
		)

		----------------------------------------
		--Insert For Checker RFID
		--ต้องทำตอน วาง STG
		----------------------------------------
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
			BEGIN
				IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid  WHERE outbound_order_master_id = @in_vchOutboundMasterID AND serial_number = @v_vchInvSerialNumber)
					BEGIN
						INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
								([checker_rfid_id]
								,[processing_status]
								,[outbound_order_master_id]
								,[serial_number]
								,[user_id]
								,[device]
								,[create_by]
								,[create_date])
							VALUES
								(NEWID()
								,'PENDING'
								,@in_vchOutboundMasterID
								,@v_vchInvSerialNumber
								,@in_vchUserID
								,@in_vchDeviceID
								,@in_vchUserID
								,GETDATE())
					END
			END
		 
		 EXEC usp_wms_dashboard_transaction @in_vchProcess			= 'OUT_IN'
										   ,@in_vchTransType		= 'PICK'
										   ,@in_vchWhMasterID		= @in_vchWhMasterID
										   ,@in_vchOwnerID			= @v_vchOwnerID
										   ,@in_vchOwnerCode		= @v_vchOwnerCode
										   ,@in_vchLocationID		= @v_vchPickLocationID
										   ,@in_vchItemMasterID		= @v_vchItemMasterID
										   ,@in_vchInvStatusID		= @v_vchInvStatusID
										   ,@in_vchToWhMasterID		= @in_vchWhMasterID
										   ,@in_vchToLocationID		= @v_vchStagingLocationID
										   ,@in_vchToInvStatusID	= @v_vchInvStatusID
										   ,@in_fltQuantity			= @v_fltQtyForPick
										   ,@in_vchUserID			= @in_vchUserID

	IF EXISTS (SELECT TOP 1 outbound_pick_detail_id FROM t_wms_outbound_pick_detail 
				WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID
				AND is_override = 'NO' 
				AND ISNULL(lpn,'') = ISNULL(@in_vchLPN,'') 
				AND ROUND(ISNULL(quantity_plan,0) - ISNULL(quantity_pick,0),@Round) > 0)
		BEGIN
			GOTO NEXT_PICK_LIST;
		END

	------------------------------------------------
	-- Update Order Status ถ้า Pick ครบแล้ว
	------------------------------------------------
	IF ((SELECT SUM(quantity_order - ISNULL(quantity_pick,0)) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @in_vchOutboundMasterID) <= 0)	--น้อยกว่าหรือเท่าศูนย์ เพราะมีกรณี over pick
		BEGIN
			UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @in_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
		END
	ELSE
		BEGIN
			UPDATE t_wms_outbound_master SET pick_by = @in_vchUserID
				, order_status = 'PICK'
				, update_by = @in_vchUserID
				, update_date = getdate()
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
		END
	
	SET @out_ErrorCode = 0;
	SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	COMMIT TRANSACTION;
	RETURN;

---------------------------------------------------
BEGIN -- Write Process Log
	WRITE_PROC:							
---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
				  
		SET @v_dtProcessDateTime = GETDATE();
		SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@v_fltQtyForPick) + ' ' + @v_vchBaseUom;
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWhID,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchOutboundOrderNumber,
			@in_vchData2 = @v_vchPickLocation,
			@in_vchData3 = @v_vchItemNumber,
			@in_vchData4 = @v_vchProcessData,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
END	

END TRY
BEGIN CATCH
	IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		ROLLBACK TRANSACTION; 

	If (ISNULL(@out_ErrorCode,'') = '' OR ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE(); 
		END

	SET @v_dtProcessDateTime = GETDATE();
	SET @v_vchProcessData = 'Qty: ' + CONVERT(VARCHAR,@v_fltQtyForPick) + ' ' + @v_vchBaseUom;
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWhID,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @v_vchOutboundOrderNumber,
		@in_vchData2 = @v_vchPickLocation,
		@in_vchData3 = @v_vchItemNumber,
		@in_vchData4 = @v_vchProcessData,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pick_parent_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pick_parent_lpn] AS
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pickto_staging]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pickto_staging]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchPicklistNumber	NVARCHAR(50),
	@in_vchForklift			NVARCHAR(50),
	@in_vchStagingLocation	NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE
	-- Error handling variables
		@c_vchObjName				NVARCHAR(40) = '[usp_outbound_update_pickto_staging]', -- The name that uniquely tags this object.
		@v_vchApplicationName		NVARCHAR(50)= NULL,
		@v_dtProcessDateTime		DATETIME,
		@v_dtStartDateTime			DATETIME,
		@Round						INT,
		@v_vchBeginTrans			BIT = 0,
		@RulePickPack				VARCHAR(5),

		@v_vchWhMasterID			UNIQUEIDENTIFIER,
		@v_vchForkLocationID		UNIQUEIDENTIFIER,
		@v_vchStgLocationID			UNIQUEIDENTIFIER,
		@v_vchOutboundOrderMasterID	UNIQUEIDENTIFIER,
		@v_vchOutboundDetailID		UNIQUEIDENTIFIER,
		@v_vchOrderStatus			NVARCHAR(25),
		@v_vchOrderType				NVARCHAR(30),
		@v_vchOwnerID				UNIQUEIDENTIFIER,
		@v_vchOwnerCode				NVARCHAR(50),
		
		@v_vchOldStgLocationID		UNIQUEIDENTIFIER,
		@v_vchOldStgLocation		NVARCHAR(50),
		
		@v_vchOutboundPickMasterID	UNIQUEIDENTIFIER,
		@v_vchOutboundPickDetailID	UNIQUEIDENTIFIER,
		@v_vchOutboundPackDetailID	UNIQUEIDENTIFIER,
		@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
		@v_vchItemNumber			NVARCHAR(50),
		@v_fltQty					FLOAT,
		
		@v_vchLineNumber			NVARCHAR(10),
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_vchLotNumber				NVARCHAR(100),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchSerialNumber			NVARCHAR(100),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_dtReceiveDate			DATE, 
		@v_vchDefaultItemStatus		NVARCHAR(50),

		@v_vchLotControl			VARCHAR(5),
		@v_vchExpiryDateControl		VARCHAR(5),
		@v_vchSerialControl			VARCHAR(5),
		@v_vchAttribute1Control		VARCHAR(5),
		@v_vchAttribute2Control		VARCHAR(5),
		@v_vchAttribute3Control		VARCHAR(5),
		@v_vchAttribute4Control		VARCHAR(5),
		@v_vchAttribute5Control		VARCHAR(5),
		@v_vchItemMasterID			UNIQUEIDENTIFIER,
		@v_vchItemUOMID				UNIQUEIDENTIFIER,
		@v_vchBaseUomPrompt			NVARCHAR(40),

		--Calculate Volumn & Weight
		@v_fltWidth					FLOAT = 0,
		@v_fltLength				FLOAT = 0,
		@v_fltHeight				FLOAT = 0,
		@v_fltGrossWeight			FLOAT = 0,
		@v_intPercentTolerance		FLOAT = 0,
		@v_intPercenToleranceWeight FLOAT = 0,
		@v_fltVolumn				FLOAT = 0,	--item
		@v_fltTotalWeight			FLOAT = 0,	--item

		@v_vchInventoryID			UNIQUEIDENTIFIER,
		@v_vchAttributeGroupID		UNIQUEIDENTIFIER,
		@v_vchInventoryStatusID		UNIQUEIDENTIFIER,
		@v_fltInventoryQty			FLOAT,
		@v_dtInvMfgDate				DATE,
		
		@v_vchLoadID				NVARCHAR(50),
		@v_vchPickLocation			NVARCHAR(50)	--Location ที่หยิบสินค้า
		--@v_vchStgLPN				NVARCHAR(50)
		

	BEGIN TRY	   
		SET @v_dtStartDateTime = GETDATE();
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT	
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'	
		SELECT TOP 1 @RulePickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK' AND is_active = 'YES'	
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse AND is_active = 'YES'
		SELECT TOP 1 @v_vchForkLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchForklift AND is_active = 'YES'	
			
		SELECT @v_vchOutboundOrderMasterID = obMS.outbound_order_master_id
			,@v_vchOrderStatus = obMS.order_status
			,@v_vchOrderType = obMS.order_type
			,@v_vchOwnerID = own.owner_id
			,@v_vchOwnerCode = own.owner_code
			,@v_vchLoadID = obMS.load_id
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id 
		WHERE wh_master_id = @v_vchWhMasterID 
		AND outbound_order_number = @in_vchPicklistNumber
		IF (@v_vchOrderStatus = 'SHIP')
			BEGIN
				SET @out_ErrorCode = '999';
				SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'CAN_NOT_PICK_TO_STAGING',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchPicklistNumber,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END

		-----------------------------------------------------------------
		--Check Staging Location in Master
		-----------------------------------------------------------------
		SELECT @v_vchStgLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = @in_vchStagingLocation AND loc_type = 'STG' AND is_active = 'YES'
		IF @v_vchStgLocationID IS NULL
			BEGIN
				SET @out_ErrorCode = '904';
				SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'STG_LOCATION_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchStagingLocation,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC
			END

		SELECT @v_vchOutboundPickMasterID = outbound_pick_master_id FROM t_wms_outbound_pick_master  WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
		SELECT TOP 1 @v_vchOldStgLocationID = staging_location_id FROM t_wms_outbound_pick_detail WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID AND (staging_location_id <> @v_vchStgLocationID AND staging_location_id IS NOT NULL)
		IF (@v_vchOldStgLocationID IS NOT NULL)
			BEGIN-- 1 OUTBOUND ORDER 1 STAGING LOCATION
				IF (@v_vchOldStgLocationID <> @v_vchStgLocationID)
					BEGIN
						SELECT @v_vchOldStgLocation = location FROM t_wms_location WHERE location_id = @v_vchOldStgLocationID
						SET @out_ErrorCode = '999';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PICK_TO_OLD_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchOldStgLocation,'@param2','@param3','@param4','@param5')
						GOTO WRITE_PROC;
					END
			END			
	
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1;

		-- ตรวจสอบว่า pick และ pack เลยหรือป่าว ถ้าใช่ให้ไปดึงข้อมูลจาก pack data แต่ถ้าไม่ให้ดึงจาก pick data
		IF (@RulePickPack = 'YES')
			BEGIN-- PICK AND PACK
				DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
				SELECT outbound_pick_detail_id
					, outbound_pack_detail_id
					, wh_item_master_id
					, item_master_id
					, item_number
					, ISNULL(quantity_pack,0) - ISNULL(quantity_stage,0)
					, item_uom_id
					, uom_prompt
					, line_number  
					, parent_lpn_pack
					, lpn_pack
					, lot_number
					, [expiry_date]
					, serial_number
					, attribute1
					, attribute2
					, attribute3
					, attribute4
					, attribute5
					, receive_date 
					, default_item_status
					, lot_control
					, expiry_date_control
					, sn_control
					, attribute1_control
					, attribute2_control
					, attribute3_control
					, attribute4_control
					, attribute5_control
					, outbound_order_detail_id
					, location
				FROM v_wms_outbound_pack_detail
				WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND (pack_location_id = @v_vchForkLocationID)
				AND (ISNULL(quantity_pack,0) - ISNULL(quantity_stage,0)) > 0  
			END
		ELSE
			BEGIN-- PICK
				DECLARE OutboundPickDetail_CURSOR CURSOR FOR 
				SELECT outbound_pick_detail_id
					, NULL AS outbound_pack_detail_id
					, wh_item_master_id
					, item_master_id
					, item_number
					, ISNULL(quantity_pick,0) - ISNULL(quantity_stage,0)
					, item_uom_id
					, uom_prompt
					, line_number  
					, pick_to_parent_lpn
					, pick_to_lpn
					, lot_number
					, [expiry_date]
					, serial_number
					, attribute1
					, attribute2
					, attribute3
					, attribute4
					, attribute5
					, receive_date
					, default_item_status
					, lot_control
					, expiry_date_control
					, sn_control
					, attribute1_control
					, attribute2_control
					, attribute3_control
					, attribute4_control
					, attribute5_control
					, outbound_order_detail_id
					, location
				FROM v_wms_outbound_pick_mini
				WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID
				AND (pick_location_id = @v_vchForkLocationID)
				AND (ISNULL(quantity_pick,0) - ISNULL(quantity_stage,0)) > 0
			END
		OPEN OutboundPickDetail_CURSOR
		FETCH OutboundPickDetail_CURSOR INTO @v_vchOutboundPickDetailID, @v_vchOutboundPackDetailID, @v_vchWhItemMasterID,@v_vchItemMasterID, @v_vchItemNumber, @v_fltQty, @v_vchItemUOMID, @v_vchBaseUomPrompt, @v_vchLineNumber, @v_vchParentLPN, @v_vchLPN,
											 @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5, @v_dtReceiveDate,@v_vchDefaultItemStatus,
											 @v_vchLotControl, @v_vchExpiryDateControl, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control,@v_vchOutboundDetailID,@v_vchPickLocation
			If (@@ROWCOUNT > 0)
				BEGIN
					WHILE @@FETCH_STATUS = 0
						BEGIN
							SET @v_fltQty = ROUND(@v_fltQty,@Round)

							--IF ISNULL(@v_vchLPN,'') = ''
							--	BEGIN
							--		SET @v_vchStgLPN = @in_vchPicklistNumber
							--	END
							--ELSE
							--	BEGIN
							--		SET @v_vchStgLPN = @v_vchLPN
							--	END
 
							-------------------------------------------------
							--Plan เก็บเป็นหน่วย Base อยู่แล้ว
							--Get data for calculate volumn & weight
							-------------------------------------------------
							SELECT @v_vchBaseUomPrompt = uom_prompt
								,@v_fltWidth = ISNULL(width,0)
								,@v_fltLength = ISNULL(length,0)
								,@v_fltHeight = ISNULL(height,0)
								,@v_fltGrossWeight = ISNULL(gross_weight,0)
								,@v_intPercentTolerance = ISNULL(percent_tolerance,0)
								,@v_intPercenToleranceWeight = ISNULL(percent_tolerance_weight,0)
							FROM t_wms_item_uom 
							WHERE item_uom_id = @v_vchItemUOMID 
							AND primary_uom = 'YES' 
							AND is_active = 'YES'

							IF (@v_fltWidth > 0 AND @v_fltLength > 0 AND @v_fltHeight > 0 AND @v_fltGrossWeight > 0 AND @v_intPercentTolerance > 0 AND @v_intPercenToleranceWeight > 0)
								BEGIN
									SET @v_fltVolumn = ROUND(((@v_fltWidth * @v_fltLength * @v_fltHeight) + ROUND((@v_intPercentTolerance / 100.00),2)) * @v_fltQty,2)
									SET @v_fltTotalWeight = ROUND((@v_fltGrossWeight + ROUND((@v_intPercenToleranceWeight / 100.00),2)) * @v_fltQty,2)
								END
							 
							-- Check Source Data in Inventory
							SET @v_vchInventoryID = NULL
							SET @v_vchAttributeGroupID = NULL
							SET @v_fltInventoryQty = 0
							SET @v_vchInventoryStatusID = NULL
							SET @v_dtInvMfgDate = NULL
							SELECT @v_vchInventoryID = inventory_id
								,@v_vchAttributeGroupID = attribute_group_id
								,@v_fltInventoryQty = quantity
								,@v_vchInventoryStatusID = inventory_status_id
								,@v_dtInvMfgDate = mfg_date
							FROM v_wms_inventory_data_by_serial_mini
							WHERE wh_master_id = @v_vchWhMasterID 
							AND location_id = @v_vchForkLocationID 
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'') 
							AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'') 
							AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
							AND ISNULL([expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
							AND (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(serial_number,'') END) = (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE ISNULL(@v_vchSerialNumber,'') END)
							AND inv_status = @v_vchDefaultItemStatus
							AND receive_date = @v_dtReceiveDate
				
							-- not have inventory data
							IF (@v_vchInventoryID IS NULL)
								BEGIN
									SET @out_ErrorCode = '989';
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_MOVE_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchForklift,@v_vchItemNumber,@v_vchLPN,'@param4','@param5')
									GOTO WRITE_PROC;
								END

							-- Quantity not enough
							IF (@v_fltInventoryQty < @v_fltQty)
								BEGIN
									SET @out_ErrorCode = '989';
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItemNumber,@in_vchForklift,'@param3','@param4','@param5')
									GOTO WRITE_PROC;							
								END

							--------------------------------------------
							--Manage source inventory
							--------------------------------------------
							UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltQty,@Round) 
								,volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) - ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) - ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID 
							AND attribute_group_id = @v_vchAttributeGroupID

							IF (@v_vchSerialControl = 'FULL')
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQty,@Round) 
									WHERE inventory_id = @v_vchInventoryID 
									AND attribute_group_id = @v_vchAttributeGroupID 
									AND attribute_value = @v_vchSerialNumber
									AND inv_attribute_type_id = (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END

							--Inventory attribute
							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltQty,@Round) 
									WHERE inventory_id = @v_vchInventoryID 
									AND attribute_group_id = @v_vchAttributeGroupID
									AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
								END
							
							DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 --and quantity_allocated = 0
							DELETE FROM t_wms_inventory WHERE quantity <= 0 --and quantity_allocated = 0
					
							--Update Volumn & Weight in from location
							IF @v_vchForkLocationID IS NOT NULL
								BEGIN
									UPDATE [dbo].[t_wms_location]
										SET total_volumn = ROUND(ISNULL(total_volumn,0) - ISNULL(@v_fltVolumn,0),2)
										, total_weight = ROUND(ISNULL(total_weight,0) - ISNULL(@v_fltTotalWeight,0),2)
										, update_date = GETDATE()  
										, [update_by] = @in_vchUserID   
										WHERE [location_id] = @v_vchForkLocationID
								END

							--------------------------------------------
							--Manage Destination inventory
							--------------------------------------------
							SET @v_vchInventoryID = NULL
							SET @v_vchAttributeGroupID = NULL
							SELECT @v_vchInventoryID = inventory_id
								,@v_vchAttributeGroupID = attribute_group_id
							FROM v_wms_inventory_data_by_id
							WHERE wh_master_id = @v_vchWhMasterID
							AND owner_id = @v_vchOwnerID
							AND location_id = @v_vchStgLocationID
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND inventory_status_id = @v_vchInventoryStatusID
							and receive_date = @v_dtReceiveDate
							AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
							AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
							AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'')
							AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
							AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
							AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
							AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
							AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
							AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

							EXEC usp_manage_inventory @in_vchWhMasterID		= @v_vchWhMasterID
													, @in_vchOwnerID		= @v_vchOwnerID
													, @in_vchWhItemMasterID	= @v_vchWhItemMasterID
													, @in_vchLocationID		= @v_vchStgLocationID
													, @in_vchStatusID		= @v_vchInventoryStatusID
													, @in_vchPalentLPN		= @v_vchParentLPN
													, @in_vchLPN			= @v_vchLPN
													, @in_fltQty			= @v_fltQty
													, @in_fltQtyAllocate	= 0
													, @in_fltQtyIncoming	= 0
													, @in_vchInventoryType	= @in_vchPicklistNumber
													, @in_vchUserID			= @in_vchUserID
													, @in_vchReceiveDate	= @v_dtReceiveDate
													, @in_dtMFGDate			= @v_dtInvMfgDate
													, @in_vchInventoryID	= @v_vchInventoryID OUTPUT
													, @in_vchAttributeGroupID = @v_vchAttributeGroupID OUTPUT	
													, @in_vchErrorCode		= @out_ErrorCode OUTPUT
													, @in_vchMessage		= @out_ErrorMessage OUTPUT	
							IF (@out_ErrorCode <> '0')
								GOTO WRITE_PROC;
							
							--Update Volumn & Weight in from location
							IF @v_vchStgLocationID IS NOT NULL
								BEGIN
									UPDATE [dbo].[t_wms_location]
										SET total_volumn = ROUND(ISNULL(total_volumn,0) + ISNULL(@v_fltVolumn,0),2)
											, total_weight = ROUND(ISNULL(total_weight,0) + ISNULL(@v_fltTotalWeight,0),2)
											, update_date = GETDATE()  
											, [update_by] = @in_vchUserID   
										WHERE [location_id] = @v_vchStgLocationID
								END
							
							--Update volumn & weight ของ LPN
							UPDATE t_wms_inventory SET 
								 volumn_by_lpn = ROUND(ISNULL(volumn_by_lpn,0) + ISNULL(@v_fltVolumn,0),2)
								,weight_by_lpn = ROUND(ISNULL(weight_by_lpn,0) + ISNULL(@v_fltTotalWeight,0),2)
							WHERE inventory_id = @v_vchInventoryID
							AND attribute_group_id = @v_vchAttributeGroupID	

							IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
								BEGIN
									EXEC usp_manage_inventory_attribute 
										  @in_vchLot				= @v_vchLotNumber
										, @in_vchExpiryDate			= @v_vchExpiryDate
										, @in_vchSerialNo			= @v_vchSerialNumber
										, @in_vchAttribute1			= @v_vchAttribute1
										, @in_vchAttribute2			= @v_vchAttribute2
										, @in_vchAttribute3			= @v_vchAttribute3
										, @in_vchAttribute4			= @v_vchAttribute4
										, @in_vchAttribute5			= @v_vchAttribute5
										, @in_fltQty				= @v_fltQty
										, @in_fltQtyAllocate		= 0
										, @in_fltQtyIncoming		= 0
										, @in_vchInventoryID		= @v_vchInventoryID
										, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
										, @in_vchLotControl			= @v_vchLotControl
										, @in_vchSNControl			= @v_vchSerialControl
										, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
										, @in_vchAttribute1Control	= @v_vchAttribute1Control
										, @in_vchAttribute2Control	= @v_vchAttribute2Control
										, @in_vchAttribute3Control	= @v_vchAttribute3Control
										, @in_vchAttribute4Control	= @v_vchAttribute4Control
										, @in_vchAttribute5Control	= @v_vchAttribute5Control
										, @in_vchUserID				= @in_vchUserID
										, @in_vchErrorCode			= @out_ErrorCode OUTPUT
										, @in_vchMessage			= @out_ErrorMessage OUTPUT
	
									IF(@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
								END	
						
							INSERT INTO t_com_tran_log
							(	 app_id
								, tran_type
								, sub_tran_type
								, [app_name]
								, [description]
								, start_tran_datetime
								, end_tran_datetime
								, warehouse
								, to_warehouse
								, location
								, to_location
								, [owner]
								, to_owner
								, item_number
								, quantity
								, quantity_uom
								, after_quantity
								, after_quantity_uom
								, lot_number
								, after_lot_number
								, [expiry_date]
								, after_expiry_date
								, serial_number
								, [attribute1]
								, [after_attribute1]
								, [attribute2]
								, [after_attribute2]
								, [attribute3]
								, [after_attribute3]
								, [attribute4]
								, [after_attribute4]
								, [attribute5]
								, [after_attribute5]
								, [user_id] 
								, parent_lpn
								, after_parent_lpn
								, lpn
								, after_lpn
								, [status]
								, after_status 
								, order_number
								, control_number
								, line_number 
								, device
								, create_by
								, create_date
								, pick_location
								, receive_date
								, mfg_date
							)
							VALUES
							(     @in_vchApplicationID			
								, 'INV_MOVE'
								, 'MOVE_DEST'
								, @v_vchApplicationName
								, 'Update pick to staging'
								, @v_dtStartDateTime
								, GETDATE()
								, @in_vchWarehouse
								, @in_vchWarehouse
								, @in_vchForkLift
								, @in_vchStagingLocation
								, @v_vchOwnerCode
								, @v_vchOwnerCode
								, @v_vchItemNumber
								, @v_fltQty
								, @v_vchBaseUomPrompt
								, 0 
								, @v_vchBaseUomPrompt
								, @v_vchLotNumber
								, @v_vchLotNumber
								, @v_vchExpiryDate
								, @v_vchExpiryDate
								, @v_vchSerialNumber
								, @v_vchAttribute1
								, @v_vchAttribute1
								, @v_vchAttribute2
								, @v_vchAttribute2
								, @v_vchAttribute3
								, @v_vchAttribute3
								, @v_vchAttribute4
								, @v_vchAttribute4
								, @v_vchAttribute5
								, @v_vchAttribute5
								, @in_vchUserID 
								, @v_vchParentLPN
								, @v_vchParentLPN
								, @v_vchLPN
								, @v_vchLPN --@v_vchStgLPN
								, @v_vchDefaultItemStatus
								, @v_vchDefaultItemStatus 
								, @in_vchPicklistNumber
								, @v_vchLoadID
								, @v_vchLineNumber
								, @in_vchDeviceID
								, @in_vchUserID
								, GETDATE()
								, @v_vchPickLocation
								, @v_dtReceiveDate
								, @v_dtInvMfgDate
							)

						UPDATE t_wms_outbound_detail SET quantity_stage = ROUND(ISNULL(quantity_stage,0)+ @v_fltQty,@Round)
						WHERE outbound_order_detail_id = @v_vchOutboundDetailID
						
						UPDATE t_wms_outbound_pick_detail 
						SET quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQty,@Round)
							,staging_location_id = @v_vchStgLocationID
							,staging_parent_lpn = @v_vchParentLPN
							,staging_lpn = @v_vchLPN
						WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
						AND outbound_pick_detail_id = @v_vchOutboundPickDetailID

						IF (@RulePickPack = 'YES')
							BEGIN
								UPDATE t_wms_outbound_pack_detail
								SET quantity_stage = ROUND(ISNULL(quantity_stage,0) + @v_fltQty,@Round)
									,staging_location_id = @v_vchStgLocationID
									,staging_parent_lpn = @v_vchParentLPN
									,staging_lpn = @v_vchLPN
								WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID
							END

						--Insert For Checker RFID
						IF ((SELECT TOP 1 value FROM T_WMS_RULE WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES') = 'YES')
							BEGIN
								IF NOT EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid WHERE outbound_order_master_id = @v_vchOutboundOrderMasterID AND serial_number = @v_vchSerialNumber)
									BEGIN
										INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
												([checker_rfid_id]
												,[processing_status]
												,[outbound_order_master_id]
												,[serial_number]
												,[user_id]
												,[device]
												,[create_by]
												,[create_date])
											VALUES
												(NEWID()
												,'PENDING'
												,@v_vchOutboundOrderMasterID
												,@v_vchSerialNumber
												,@in_vchUserID
												,@in_vchDeviceID
												,@in_vchUserID
												,GETDATE())
									END
							END

						-- For Dashboard
						BEGIN
							EXEC usp_wms_dashboard_transaction @in_vchProcess	 = 'OUT_IN'
															,@in_vchTransType	 = 'PICK'
															,@in_vchWhMasterID	 = @v_vchWhMasterID
															,@in_vchOwnerID		 = @v_vchOwnerID
															,@in_vchOwnerCode	 = @v_vchOwnerCode
															,@in_vchLocationID	 = @v_vchForkLocationID
															,@in_vchItemMasterID = @v_vchItemMasterID
															,@in_vchInvStatusID	 = @v_vchInventoryStatusID
															,@in_vchToWhMasterID = @v_vchWhMasterID
															,@in_vchToLocationID = @v_vchStgLocationID
															,@in_vchToInvStatusID = @v_vchInventoryStatusID
															,@in_fltQuantity	 = @v_fltQty
															,@in_vchUserID		 = @in_vchUserID
						END

						FETCH NEXT FROM OutboundPickDetail_CURSOR INTO @v_vchOutboundPickDetailID, @v_vchOutboundPackDetailID, @v_vchWhItemMasterID,@v_vchItemMasterID, @v_vchItemNumber, @v_fltQty, @v_vchItemUOMID, @v_vchBaseUomPrompt, @v_vchLineNumber, @v_vchParentLPN, @v_vchLPN,
																	   @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5, @v_dtReceiveDate,@v_vchDefaultItemStatus,
																	   @v_vchLotControl, @v_vchExpiryDateControl, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control,@v_vchOutboundDetailID,@v_vchPickLocation

					END
				END
			ELSE
				BEGIN
					SET @out_ErrorCode = '999';
					SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_INTRANSIT',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchPicklistNumber,@in_vchForklift,'@param3','@param4','@param5')
					GOTO WRITE_PROC;
				END
					
		CLOSE OutboundPickDetail_CURSOR;
		DEALLOCATE OutboundPickDetail_CURSOR;
		
	COMMIT TRANSACTION;
	SET @out_ErrorCode = '0';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
	RETURN;

	-----------------------------------------------------------------------------------
	-- Write process log
	BEGIN
		WRITE_PROC:							
	-----------------------------------------------------------------------------------
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
			 
		IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
			BEGIN
				CLOSE OutboundPickDetail_CURSOR;
				DEALLOCATE OutboundPickDetail_CURSOR;
			END 

		SET @v_dtProcessDateTime = getdate();				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWarehouse,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @in_vchPicklistNumber,
			@in_vchData2 = @in_vchForklift,
			@in_vchData3 = @in_vchStagingLocation,
			@in_vchData4 = NULL,
			@in_vchErrorCode = @out_ErrorCode,
			@in_vchMessage = @out_ErrorMessage
	End
				
End Try
Begin Catch
	
	If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
		Rollback Transaction;

	IF CURSOR_STATUS('global','OutboundPickDetail_CURSOR')>=-1
			BEGIN
				CLOSE OutboundPickDetail_CURSOR;
				DEALLOCATE OutboundPickDetail_CURSOR;
			END 

	IF (ISNULL(@out_ErrorCode,'') = '' or ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	SET @v_dtProcessDateTime = getdate();				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @in_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchPicklistNumber,
		@in_vchData2 = @in_vchForklift,
		@in_vchData3 = @in_vchStagingLocation,
		@in_vchData4 = NULL,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
End Catch	
END

GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pickto_staging_by_group]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Wuttichai K.
-- Create date: 2014-02-13
-- Description:	Pick to staging by group
-- =============================================
CREATE PROCEDURE [dbo].[usp_outbound_update_pickto_staging_by_group]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchWarehouse		NVARCHAR(25),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchLoadID			NVARCHAR(50),
	@in_vchForklift			NVARCHAR(50),
	@in_vchStagingLocation	NVARCHAR(50),
	@in_vchFromParentLPN	NVARCHAR(25),
	@in_vchToParentLPN		NVARCHAR(25),
	@in_vchFromLPN			NVARCHAR(25),
	@in_vchToLPN			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(200) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	--SET XACT_ABORT ON;
	
	DECLARE
	-- Error handling variables
		@c_vchObjName				NVARCHAR(30) = '[usp_outbound_update_pickto_staging]', -- The name that uniquely tags this object.
		@v_vchProcessData1			NVARCHAR(1000),
		@v_vchProcessData2			NVARCHAR(1000),
		@v_vchProcessData3			NVARCHAR(1000),
		@v_vchProcessData4			NVARCHAR(1000),
		@v_dtProcessDateTime		DATETIME,
		@v_dtStartDateTime			DATETIME,
		
		@v_vchParentLPN				NVARCHAR(25),
		@v_vchToParentLPN			NVARCHAR(25),
		@v_vchLPN					NVARCHAR(25),
		@v_vchLot					NVARCHAR(50),
		@v_vchExpiryDate			NVARCHAR(8),
		@v_vchItem					NVARCHAR(50),
		@v_vchItemMasterID			NVARCHAR(40),
		@v_fltQty					FLOAT,
		@v_vchUOM					NVARCHAR(10),
		@v_vchSerial				NVARCHAR(100),
		@v_vchAttribute1			NVARCHAR(100),
		@v_vchAttribute2			NVARCHAR(100),
		@v_vchAttribute3			NVARCHAR(100),
		@v_vchAttribute4			NVARCHAR(100),
		@v_vchAttribute5			NVARCHAR(100),
		@v_vchLineNumber			NVARCHAR(10),
		@v_vchOutBoundOrderMasterID	VARCHAR(40),
		@v_vchOutboundPickDetailID	NVARCHAR(40),
		
		@v_vchWarehouseMasterID		NVARCHAR(40),
		@v_vchWarehouseItemMasterID	NVARCHAR(40),
		@v_vchFromLocationID		NVARCHAR(40),
		@v_vchLocationMasterID		NVARCHAR(40),
		@v_vchStagingStatus			NVARCHAR(20),
		@v_vchAllParentLPN			NVARCHAR(3),
		@v_vchAllLPN				NVARCHAR(3),
		@v_vchLocType				NVARCHAR(25),
		@v_vchOutboundPickMasterID	NVARCHAR(40),
		@Round						INT,

		@v_vchStagingLocation		NVARCHAR(50),
		@v_vchStagingLocationID		VARCHAR(40),
		@v_vchOrderStatus			NVARCHAR(20),
		@v_vchBeginTrans			BIT = 0,
		
		@v_vchLotControl			NVARCHAR(5),
		@v_vchExpiryDateControl		NVARCHAR(5),
		@v_vchSerialControl			NVARCHAR(5),
		@v_vchAttribute1Control		NVARCHAR(5),
		@v_vchAttribute2Control		NVARCHAR(5),
		@v_vchAttribute3Control		NVARCHAR(5),
		@v_vchAttribute4Control		NVARCHAR(5),
		@v_vchAttribute5Control		NVARCHAR(5),
		@v_vchMixItem				NVARCHAR(3),
		@v_vchMixLot				NVARCHAR(3),
		@v_vchMixOwner				NVARCHAR(3),
		@v_vchMixExpiryDate			NVARCHAR(3),
		@v_vchLPNControl			NVARCHAR(5),
		@v_vchReceiveDate			DATE,
		@v_vchInventoryIDForSerial	NVARCHAR(40),
		@v_vchInventoryID			NVARCHAR(40),
		@v_vchAttributeGroupID		NVARCHAR(40),
		@v_vchAttributeGroupIDForSerial		NVARCHAR(40),
		@v_fltStockQuantity			FLOAT = 0,
		@v_fltBaseQuantity			FLOAT,
		@v_vchInventoryType			NVARCHAR(25) = @in_vchLoadID,
		@v_vchDubLocation			NVARCHAR(50),
		@v_vchDubParentLPN			NVARCHAR(25),
		@v_vchInventoryStatus		NVARCHAR(50),
		@v_vchToInventoryStatusID	VARCHAR(40),
		@v_vchOwnerCode				NVARCHAR(50),
		@v_vchOwnerID				VARCHAR(40),
		@v_vchOrderType				NVARCHAR(40),

		@cursorOutboundPickDetail	CURSOR,
		@v_vchDynamicSQL			NVARCHAR(MAX) = '',
		@v_vchParameterDefinition	NVARCHAR(MAX) = '',
		@v_vchOutboundPackDetailID	VARCHAR(40),
		@v_vchPickPack				NVARCHAR(3),
		@v_vchRuleObCheckerRFID		NVARCHAR(5)
   
	SET @out_ErrorCode = '0';
	SET @v_dtStartDateTime = GETDATE();
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
	SELECT @v_vchRuleObCheckerRFID = value FROM T_WMS_RULE WHERE RULE_CODE = 'RULE_OUTBOUND_CHECKER_RFID' AND is_active = 'YES'

	BEGIN TRY
			
			IF (@in_vchFromParentLPN = 'ALL')
				SET @v_vchAllParentLPN = @in_vchFromParentLPN
			IF (@in_vchFromLPN = 'ALL')
				SET @v_vchAllLPN = @in_vchFromLPN;
		
			SELECT @v_vchWarehouseMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @in_vchWarehouse
			SELECT @v_vchFromLocationID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWarehouseMasterID AND location = @in_vchForklift
			SELECT @v_vchLocationMasterID = location_id
				,@v_vchLocType = loc_type
				,@v_vchMixItem = mix_items
				,@v_vchMixLot = mix_lot
				,@v_vchMixExpiryDate = mix_expiry_dates
				,@v_vchMixOwner = mix_owners
				,@v_vchLPNControl = lpn_controlled 
			FROM t_wms_location 
			WHERE wh_master_id = @v_vchWarehouseMasterID 
			AND location = @in_vchStagingLocation

			SELECT TOP 1 @v_vchStagingLocationID = staging_location_id FROM t_wms_outbound_pick_detail 
			WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
			AND (staging_location_id <> @v_vchLocationMasterID 
			AND staging_location_id IS NOT NULL)
			IF (@v_vchStagingLocationID IS NOT NULL)
				BEGIN-- 1 OUTBOUND ORDER 1 STAGING LOCATION
					IF (@v_vchStagingLocationID <> @v_vchLocationMasterID)
						BEGIN
							SELECT @v_vchStagingLocation = location FROM t_wms_location WHERE location_id = @v_vchStagingLocationID
							SET @out_ErrorCode = '999';
							SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'PICK_TO_OLD_STAGING',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchStagingLocation,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC;
						END
				END
			ELSE
				BEGIN
					IF (@v_vchLocationMasterID IS NULL)
						BEGIN
							SET @out_ErrorCode = '904';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'LOCATION_NOT_FOUND',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchStagingLocation,'@param2','@param3','@param4','@param5')
							GOTO WRITE_PROC
						END
				END
			
			-- Check duplicate parent lpn.		
			IF (ISNULL(@in_vchToParentLPN,'') <> '')
				BEGIN-- 1 PARENT LPN 1 LOCATION
					SELECT TOP 1 @v_vchDubLocation = location_id FROM t_wms_inventory 
					WHERE wh_master_id = @v_vchWarehouseMasterID 
					AND (ISNULL(location_id,'') <> ISNULL(@v_vchFromLocationID,'') 
					AND ISNULL(location_id,'') <> ISNULL(@v_vchLocationMasterID,'')) 
					AND parent_lpn = @in_vchToParentLPN
					IF (ISNULL(@v_vchDubLocation,'') <> '')
						BEGIN
							SELECT @v_vchDubLocation = location FROM t_wms_location WHERE location_id = @v_vchDubLocation
							SET @out_ErrorCode = '901';
							SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'PARENT_LPN_DUPPLICATE',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchToParentLPN,@v_vchDubLocation,'@param3','@param4','@param5')
							GOTO WRITE_PROC
						END
				END
	
			SELECT @v_vchPickPack = value FROM t_wms_rule WHERE rule_code = 'RULE_PICK_PACK'
			IF ((@v_vchPickPack) = 'YES')
				BEGIN--PICK AND PACK
					SET @v_vchDynamicSQL = '
											SELECT DISTINCT parent_lpn_pack
												, lpn_pack
												, lot_number
												, [expiry_date]
												, item_number
												, quantity_pack - quantity_stage
												, uom_prompt
												, serial_number
												, line_number
												, outbound_pick_detail_id
												, wh_item_master_id
												, outbound_pack_detail_id
												, outbound_pick_master_id
												, outbound_order_master_id
												, owner_id
												, attribute1
												, attribute2
												, attribute3
												, attribute4
												, attribute5
												, order_type
											FROM v_wms_outbound_pack_detail
											WHERE wh_id = @in_vchWarehouse 
											and load_id = @in_vchLoadID 
											and (pack_location = @in_vchForklift)
											AND quantity_pack - quantity_stage > 0  ';
					IF (ISNULL(@in_vchFromParentLPN,'') <> '' and (ISNULL(@in_vchFromParentLPN,'') <> 'ALL'))
						BEGIN
							SET @v_vchDynamicSQL = @v_vchDynamicSQL + ' AND ISNULL(parent_lpn_pack,'''') = ISNULL(@in_vchFromParentLPN,'''') ';
						END
					IF (ISNULL(@in_vchFromLPN,'') <> '' and (ISNULL(@in_vchFromLPN,'') <> 'ALL'))
						BEGIN
							SET @v_vchDynamicSQL = @v_vchDynamicSQL + ' AND ISNULL(lpn_pack,'''') = ISNULL(@in_vchFromLPN,'''') ';
						END
				END
			ELSE
				BEGIN--PICK
					--Mai 28/02/2014 : แก้จาก null as lpn >> pick_to_lpn as lpn
					SET @v_vchDynamicSQL = '
											SELECT DISTINCT pick_to_parent_lpn
												, pick_to_lpn as lpn
												, lot_number
												, [expiry_date]
												, item_number
												, quantity_pick - quantity_stage
												, uom_prompt
												, serial_number
												, line_number
												, outbound_pick_detail_id
												, wh_item_master_id
												, '''' as outbound_pack_detail_id
												, outbound_pick_master_id
												, outbound_order_master_id
												, owner_id
												, attribute1
												, attribute2
												, attribute3
												, attribute4
												, attribute5
												, order_type
											FROM v_wms_outbound_pick_or_pack
											WHERE wh_id = @in_vchWarehouse 
											and load_id = @in_vchLoadID 
											and (pick_location = @in_vchForklift)
											AND quantity_pick - quantity_stage > 0 ';
					IF (ISNULL(@in_vchFromParentLPN,'') <> '' AND (ISNULL(@in_vchFromParentLPN,'') <> 'ALL'))
						BEGIN
							SET @v_vchDynamicSQL = @v_vchDynamicSQL + ' AND ISNULL(parent_lpn,'''') = ISNULL(@in_vchFromParentLPN,'''') ';
						END
					IF (ISNULL(@in_vchFromLPN,'') <> '' AND (ISNULL(@in_vchFromLPN,'') <> 'ALL'))
						BEGIN
							SET @v_vchDynamicSQL = @v_vchDynamicSQL + ' AND ISNULL(lpn,'''') = ISNULL(@in_vchFromLPN,'''') ';
						END
				END

			SET @v_vchDynamicSQL = ' SET @cursorOutboundPickDetail = CURSOR FORWARD_ONLY STATIC FOR ' + @v_vchDynamicSQL + ' ; OPEN @cursorOutboundPickDetail'								
			SET @v_vchParameterDefinition = '@in_vchWarehouse NVARCHAR(25),@in_vchLoadID NVARCHAR(50),@in_vchForklift NVARCHAR(50),@in_vchFromParentLPN NVARCHAR(25),@in_vchFromLPN NVARCHAR(25),@cursorOutboundPickDetail CURSOR OUTPUT';
			EXEC sp_executesql @v_vchDynamicSQL,@v_vchParameterDefinition,@in_vchWarehouse,@in_vchLoadID,@in_vchForklift,@in_vchFromParentLPN,@in_vchFromLPN,@cursorOutboundPickDetail OUTPUT

			FETCH @cursorOutboundPickDetail INTO @v_vchParentLPN,@v_vchLPN,@v_vchLot,@v_vchExpiryDate,@v_vchItem,@v_fltQty,@v_vchUOM,@v_vchSerial
												,@v_vchLineNumber,@v_vchOutboundPickDetailID,@v_vchWarehouseItemMasterID,@v_vchOutboundPackDetailID
												,@v_vchOutboundPickMasterID,@v_vchOutBoundOrderMasterID,@v_vchOwnerID
												,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_vchOrderType
				
			BEGIN TRANSACTION
				SET @v_vchBeginTrans = 1;
				
				If (@@CURSOR_ROWS > 0)
					BEGIN
						WHILE @@FETCH_STATUS = 0
							BEGIN

							IF (ISNUll(@in_vchToParentLPN,'') <> '')
								SET @v_vchToParentLPN = @in_vchToParentLPN;
							ELSE IF (ISNULL(@in_vchToParentLPN,'') = '' AND @v_vchAllParentLPN IN ('ALL'))
								SET @v_vchToParentLPN = @v_vchParentLPN
							ELSE IF (ISNULL(@in_vchToParentLPN,'') = '' AND @v_vchAllLPN IN ('ALL'))
								SET @v_vchToParentLPN = @v_vchParentLPN
							
							--Get Item Master
							SELECT @v_vchItemMasterID = item.item_master_id
								,@v_vchLotControl = item.lot_control
								,@v_vchExpiryDateControl = item.expiry_date_control
								,@v_vchSerialControl = item.sn_control
								,@v_vchOwnerCode = own.owner_code
								,@v_vchAttribute1Control = item.attribute1_control
								,@v_vchAttribute2Control = item.attribute2_control
								,@v_vchAttribute3Control = item.attribute3_control
								,@v_vchAttribute4Control = item.attribute4_control
								,@v_vchAttribute5Control = item.attribute5_control
							FROM t_wms_item item
							INNER JOIN t_wms_owner own on item.owner_id = own.owner_id 
							WHERE item.item_number = @v_vchItem 
							AND item.owner_id = @v_vchOwnerID

							-- Check Data in Inventory
							If (@v_vchSerialControl = 'FULL')
								BEGIN
									SELECT	@v_vchInventoryID = inventory_id,
											@v_vchAttributeGroupID = attribute_group_id,
											@v_vchOwnerID = owner_id,
											@v_fltStockQuantity = quantity,
											@v_vchReceiveDate = receive_date,
											@v_vchToInventoryStatusID = inventory_status_id,
											@v_vchInventoryStatus = inv_status
									FROM v_wms_inventory_data_by_serial
									WHERE wh_master_id = @v_vchWarehouseMasterID 
									AND wh_item_master_id = @v_vchWarehouseItemMasterID 
									AND location_id = @v_vchFromLocationID
									AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'') 
									AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@v_vchLot,'') 
									AND ISNULL([EXPIRY_DATE],'') = ISNULL(@v_vchExpiryDate,'')
									AND ISNULL(SERIAL_NUMBER,'') = ISNULL(@v_vchSerial,'')
									AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
								END
							ELSE
								BEGIN
									SELECT	@v_vchInventoryID = inventory_id,
											@v_vchAttributeGroupID = attribute_group_id,
											@v_vchOwnerID = owner_id,
											@v_fltStockQuantity = quantity,
											@v_vchReceiveDate = receive_date,
											@v_vchToInventoryStatusID = inventory_status_id,
											@v_vchInventoryStatus = inv_status
									FROM v_wms_inventory_data
									WHERE wh_master_id = @v_vchWarehouseMasterID 
									AND wh_item_master_id = @v_vchWarehouseItemMasterID 
									AND location_id = @v_vchFromLocationID
									AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'') 
									AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@v_vchLot,'') 
									AND ISNULL([EXPIRY_DATE],'') = ISNULL(@v_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
								END
				
							-- Not have inventory data
							If (@v_vchInventoryID is null)
								BEGIN
									SET @out_ErrorCode = '989';
									SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_MOVE_DATA',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchForklift,@v_vchItem,@v_vchLPN,'@param4','@param5')
									GOTO WRITE_PROC;
								END

							-- Conversion Factor
							SELECT @v_fltBaseQuantity = ROUND(@v_fltQty * conversion_factor,@Round)
							FROM t_wms_item_uom 
							WHERE item_master_id = @v_vchItemMasterID 
							AND (uom_prompt = @v_vchUOM)

							-- Quantity not enough
							IF ((@v_fltStockQuantity < @v_fltBaseQuantity))
								Begin
									set @out_ErrorCode = '989';
									select @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'QUANTITY_NOT_ENOUGH',(select dbo.usf_get_locale_id(@in_vchUserID)),@v_vchItem,@in_vchForklift,'@param3','@param4','@param5')
									Goto WRITE_PROC;							
								End
							
							IF (@v_vchPickPack <> 'YES' AND ISNULL(@in_vchToLPN,'') <> '')
								BEGIN
									SET @v_vchLPN = @in_vchToLPN; 
								END

							BEGIN
								-- manage source location data
								UPDATE t_wms_inventory SET quantity = ROUND(quantity - @v_fltBaseQuantity,@Round) 
								WHERE inventory_id = @v_vchInventoryID 
								AND attribute_group_id = @v_vchAttributeGroupID
								IF (@v_vchSerialControl = 'FULL')
									BEGIN
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltBaseQuantity,@Round) 
										WHERE inventory_id = @v_vchInventoryID 
										AND attribute_group_id = @v_vchAttributeGroupID 
										AND attribute_value = @v_vchSerial													
									END
								
								IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
									BEGIN										
										UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - @v_fltBaseQuantity,@Round) 
										WHERE inventory_id = @v_vchInventoryID 
										AND attribute_group_id = @v_vchAttributeGroupID
										AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
									END


								-- manage destination location data
								BEGIN
									SET @v_vchInventoryID = null;
									SET @v_vchAttributeGroupID = null;
									SET @v_fltStockQuantity = 0;
								
									SELECT	@v_vchInventoryID = inventory_id,
											@v_vchAttributeGroupID = attribute_group_id,
											@v_fltStockQuantity = quantity
									FROM v_wms_inventory_data
									WHERE wh_master_id = @v_vchWarehouseMasterID 
									AND wh_item_master_id = @v_vchWarehouseItemMasterID 
									AND location_id = @v_vchLocationMasterID
									AND ISNULL(parent_lpn,'') = ISNULL(@v_vchToParentLPN,'') 
									AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
									AND ISNULL(lot_number,'') = ISNULL(@v_vchLot,'') 
									AND ISNULL([EXPIRY_DATE],'') = ISNULL(@v_vchExpiryDate,'')
									AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
									AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
									AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
									AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
									AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')
									
									EXEC usp_manage_inventory
										 @in_vchApplicationID		  = @in_vchApplicationID
										,@in_vchWarehouseMasterID	  = @v_vchWarehouseMasterID
										,@in_vchWarehouseItemMasterID = @v_vchWarehouseItemMasterID
										,@in_vchLocationID			  = @v_vchLocationMasterID
										,@in_vchLocation			  = @in_vchStagingLocation
										,@in_vchStatusID			  = @v_vchToInventoryStatusID
										,@in_vchLPN					  = @v_vchLPN
										,@in_vchLotNumber			  = @v_vchLot
										,@in_vchExpiryDate			  = @v_vchExpiryDate
										,@in_vchSerialNumber		  = @v_vchSerial
										,@in_fltQty					  = @v_fltBaseQuantity
										,@in_fltQtyAllocate			  = 0
										,@in_fltQtyIncoming			  = 0
										,@in_vchOwner				  = @v_vchOwnerCode
										,@in_vchInventoryType		  = @v_vchInventoryType
										,@in_vchPalentLPN			  = @v_vchToParentLPN
										,@in_vchUserID				  = @in_vchUserID
										,@in_vchReceiveDate			  = @v_vchReceiveDate
										,@in_vchInventoryID			  = @v_vchInventoryID		OUTPUT
										,@in_vchAttributeGroupID	  = @v_vchAttributeGroupID	OUTPUT
										,@in_vchErrorCode			  = @out_ErrorCode			OUTPUT
										,@in_vchMessage				  = @out_ErrorMessage		OUTPUT
									IF (@out_ErrorCode <> '0')
										GOTO WRITE_PROC;
									
									IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSerialControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
										BEGIN
											EXEC usp_manage_inventory_attribute
												@in_vchApplicationID	  = @in_vchApplicationID
												,@in_vchItem			  = @v_vchItem
												,@in_vchSerialNo		  = @v_vchSerial
												,@in_vchLot				  = @v_vchLot
												,@in_vchExpiryDate		  = @v_vchExpiryDate
												,@in_vchAttribute1		  = @v_vchAttribute1
												,@in_vchAttribute2		  = @v_vchAttribute2
												,@in_vchAttribute3		  = @v_vchAttribute3
												,@in_vchAttribute4		  = @v_vchAttribute4
												,@in_vchAttribute5		  = @v_vchAttribute5
												,@in_fltQty				  = @v_fltBaseQuantity
												,@in_fltQtyAllocate		  = 0
												,@in_fltQtyIncoming		  = 0
												,@in_vchInventoryID		  = @v_vchInventoryID
												,@in_vchAttributeGroupID  = @v_vchAttributeGroupID
												,@in_vchLotControl		  = @v_vchLotControl
												,@in_vchSNControl		  = @v_vchSerialControl
												,@in_vchExpiryDateControl = @v_vchExpiryDateControl
												,@in_vchAttribute1Control = @v_vchAttribute1Control
												,@in_vchAttribute2Control = @v_vchAttribute2Control
												,@in_vchAttribute3Control = @v_vchAttribute3Control
												,@in_vchAttribute4Control = @v_vchAttribute4Control
												,@in_vchAttribute5Control = @v_vchAttribute5Control
												,@in_vchUserID			 = @in_vchUserID
												,@in_vchErrorCode		 = @out_ErrorCode    OUTPUT
												,@in_vchMessage			 = @out_ErrorMessage OUTPUT		
													
											IF(@out_ErrorCode <> '0')
												GOTO WRITE_PROC;
										END			
								END
							
								--กรณีย้ายทั้งหมด ไม่สนใจ tran log ว่า serial ไหนไปวางลานจ่ายบ้าง
								--update t_wms_inventory set location_id = @v_vchLocationMasterID
								--where wh_master_id = @v_vchWarehouseMasterID and isnull(parent_lpn,'') = isnull(@v_vchParentLPN,'') and isnull(lpn,'') = isnull(@v_vchLPN,'')
								--and wh_item_master_id = @v_vchWarehouseItemMasterID and location_id = @v_vchFromLocationID

								INSERT INTO t_com_tran_log
									(app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id]
									, reference_number
									, control_number
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status
									, zone
									, order_number
									, line_number
									, udf_2
									, device
									, create_by)
								VALUES
									(@in_vchApplicationID
									, 'INV_MOVE'
									, 'MOVE_DEST'
									, NULL
									, 'Update pick to staging by load'
									, @v_dtStartDateTime
									, GETDATE()
									, @in_vchWarehouse
									, NULL
									, @in_vchForklift
									, @in_vchStagingLocation
									, @v_vchOwnerCode
									, NULL
									, @v_vchItem
									, @v_fltBaseQuantity
									, @v_vchUOM
									, @v_fltStockQuantity + @v_fltBaseQuantity
									, @v_vchUOM
									, @v_vchLot
									, @v_vchLot
									, @v_vchExpiryDate
									, @v_vchExpiryDate
									, @v_vchSerial
									, @v_vchAttribute1
									, @v_vchAttribute1
									, @v_vchAttribute2
									, @v_vchAttribute2
									, @v_vchAttribute3
									, @v_vchAttribute3
									, @v_vchAttribute4
									, @v_vchAttribute4
									, @v_vchAttribute5
									, @v_vchAttribute5
									, @in_vchUserID
									, NULL
									, NULL
									, @v_vchParentLPN
									, @v_vchToParentLPN
									, @v_vchLPN
									, @v_vchLPN
									, @v_vchInventoryStatus
									, @v_vchInventoryStatus
									, NULL
									, @in_vchLoadID
									, @v_vchLineNumber
									, @v_vchOrderType
									, @in_vchDeviceID
									, @in_vchUserID)
							END

							UPDATE t_wms_outbound_detail SET staging_item_status = @v_vchStagingStatus
							WHERE outbound_order_master_id = @v_vchOutBoundOrderMasterID AND wh_item_master_id = @v_vchWarehouseItemMasterID 

							UPDATE t_wms_outbound_pick_detail 
							SET quantity_stage = ROUND(ROUND(@v_fltQty,@Round) + ROUND(quantity_stage,@Round),@Round)
							   ,staging_location_id = @v_vchLocationMasterID
							   ,staging_parent_lpn = @v_vchToParentLPN
							   ,staging_lpn = @v_vchLPN
							WHERE outbound_pick_master_id = @v_vchOutboundPickMasterID 
							AND outbound_pick_detail_id = @v_vchOutboundPickDetailID

							IF ((@v_vchPickPack) = 'YES')
								BEGIN
									UPDATE t_wms_outbound_pack_detail
									SET quantity_stage = ROUND(ROUND(@v_fltQty,@Round) + ROUND(quantity_stage,@Round),@Round)
									  ,staging_location_id = @v_vchLocationMasterID
									  ,staging_parent_lpn = @v_vchToParentLPN
									  ,staging_lpn = @v_vchLPN
									WHERE outbound_pack_detail_id = @v_vchOutboundPackDetailID
								END

							--Insert For Checker RFID
							IF (@v_vchRuleObCheckerRFID = 'YES')
								BEGIN
									INSERT INTO [dbo].[t_wms_outbound_checker_rfid]
										   ([checker_rfid_id]
										   ,[processing_status]
										   ,[outbound_order_master_id]
										   ,[serial_number]
										   ,[user_id]
										   ,[device]
										   ,[create_by]
										   ,[create_date])
									 VALUES
										   (NEWID()
										   ,'PENDING'
										   ,@v_vchOutboundOrderMasterID
										   ,@v_vchSerial
										   ,@in_vchUserID
										   ,@in_vchDeviceID
										   ,@in_vchUserID
										   ,GETDATE())
								END


							FETCH @cursorOutboundPickDetail INTO @v_vchParentLPN,@v_vchLPN,@v_vchLot,@v_vchExpiryDate,@v_vchItem,@v_fltQty,@v_vchUOM,@v_vchSerial
												,@v_vchLineNumber,@v_vchOutboundPickDetailID,@v_vchWarehouseItemMasterID,@v_vchOutboundPackDetailID
												,@v_vchOutboundPickMasterID,@v_vchOutBoundOrderMasterID,@v_vchOwnerID
												,@v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_vchOrderType
						END
					END
				ELSE
					BEGIN
						SET @out_ErrorCode = '999';
						SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'NOT_FOUND_DATA_ON_INTRANSIT',(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLoadID,@in_vchForklift,'@param3','@param4','@param5')
						CLOSE @cursorOutboundPickDetail;
						DEALLOCATE @cursorOutboundPickDetail;
						GOTO WRITE_PROC;
					END
					
				CLOSE @cursorOutboundPickDetail;
				DEALLOCATE @cursorOutboundPickDetail;
				
			COMMIT TRANSACTION;

			SET @out_ErrorCode = '0';
			SELECT @out_ErrorMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

			DELETE FROM t_wms_inventory WHERE quantity = 0 AND quantity_allocated = 0
			DELETE FROM t_wms_inventory_attribute WHERE quantity = 0 AND quantity_allocated = 0

			RETURN;
		-----------------------------------------------------------------------------------
		-- Write process log
		BEGIN
			WRITE_PROC:							
		-----------------------------------------------------------------------------------
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
					
				SET @v_vchProcessData1 = @out_ErrorMessage;
				SET @v_dtProcessDateTime = GETDATE();

				IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
					BEGIN
						Close @cursorOutboundPickDetail;
						Deallocate @cursorOutboundPickDetail;
					END
			
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @in_vchWarehouse,
					@in_vchDevice = @in_vchDeviceID,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = @c_vchObjName,
					@in_dtProcessDateTime = @v_dtProcessDateTime,
					@in_vchData1 = @v_vchProcessData1,
					@in_vchData2 = @v_vchProcessData2,
					@in_vchData3 = @in_vchLoadID,
					@in_vchData4 = @v_vchProcessData4,
					@in_vchErrorCode = @out_ErrorCode,
					@in_vchMessage = @out_ErrorMessage
		END
				
	END TRY
	BEGIN CATCH
	
		If (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','@cursorOutboundPickDetail') >= -1
			BEGIN
				CLOSE @cursorOutboundPickDetail;
				DEALLOCATE @cursorOutboundPickDetail;
			END

		IF (ISNULL(@out_ErrorCode,'') = '' or isnull(@out_ErrorCode,'') = '0')
			BEGIN
				SET @out_ErrorCode = ERROR_NUMBER();
				SET @out_ErrorMessage = ERROR_MESSAGE();
			END	
		
	END CATCH	
END
GO
/****** Object:  StoredProcedure [dbo].[usp_outbound_update_pickto_staging_by_load]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_outbound_update_pickto_staging_by_load]
	@in_vchApplicationID	VARCHAR(40),
	@in_vchDeviceID			NVARCHAR(50),
	@in_vchUserID			NVARCHAR(25),
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchLoadID			NVARCHAR(50),  
	@in_vchForklift			NVARCHAR(50), 
	@in_vchStagingLocation	NVARCHAR(50),
	@out_ErrorCode			NVARCHAR(50) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
	
	DECLARE @c_vchObjName		NVARCHAR(40) = '[usp_outbound_update_pickto_staging_by_load]' -- The name that uniquely tags this object.
	DECLARE @v_vchWarehouse		NVARCHAR(25) = NULL
	DECLARE @v_vchPicklistNumber NVARCHAR(50) = NULL
	DECLARE @v_vchForkliftID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_intRound			INT = 0
	SELECT TOP 1 @v_intRound = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	SELECT TOP 1 @v_vchForkliftID = location_id FROM t_wms_location WHERE wh_master_id = @in_vchWhMasterID AND location = @in_vchForklift AND is_active = 'YES'
BEGIN TRY
	--------------------------------------------
	--CONFIRM SHIP BY LOAD ID
	--------------------------------------------
	DECLARE Outbound_Cursor CURSOR FOR 
		SELECT wh_id
			,outbound_order_number
		FROM t_wms_outbound_master obMS
		INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
		INNER JOIN t_wms_outbound_pick_detail pickDT ON obDT.outbound_order_detail_id = pickDT.outbound_order_detail_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND load_id = @in_vchLoadID
		AND order_status NOT IN ('SHIP','CLOSE')
		AND ROUND(ISNULL(obDT.quantity_pick,0) - ISNULL(obDT.quantity_stage,0),@v_intRound) > 0
		AND pickDT.pick_location_id = @v_vchForkliftID
		ORDER BY outbound_order_number
	OPEN Outbound_Cursor 
	FETCH NEXT FROM Outbound_Cursor INTO @v_vchWarehouse, @v_vchPicklistNumber
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		-----------------------------------------
		--SHIP LOAD BY ORDER
		-----------------------------------------
		EXEC usp_outbound_update_pickto_staging @in_vchApplicationID	= @in_vchApplicationID	
											   ,@in_vchWarehouse		= @v_vchWarehouse		
											   ,@in_vchDeviceID			= @in_vchDeviceID			
											   ,@in_vchUserID			= @in_vchUserID			
											   ,@in_vchPicklistNumber	= @v_vchPicklistNumber	
											   ,@in_vchForklift			= @in_vchForklift			
											   ,@in_vchStagingLocation	= @in_vchStagingLocation	
											   ,@out_ErrorCode			= @out_ErrorCode OUTPUT		
											   ,@out_ErrorMessage		= @out_ErrorMessage	OUTPUT 
		IF (@out_ErrorCode <> '0')
		BEGIN 
			RETURN;
		END

		FETCH NEXT FROM Outbound_Cursor INTO @v_vchWarehouse ,@v_vchPicklistNumber 
	END
	CLOSE Outbound_Cursor                  	
	DEALLOCATE Outbound_Cursor
				
END TRY
BEGIN CATCH

	IF CURSOR_STATUS('global','Outbound_Cursor')>=-1
		BEGIN
			CLOSE Outbound_Cursor;
			DEALLOCATE Outbound_Cursor;
		END 

	IF (ISNULL(@out_ErrorCode,'') = '' or ISNULL(@out_ErrorCode,'') = '0')
		BEGIN
			SET @out_ErrorCode = ERROR_NUMBER();
			SET @out_ErrorMessage = ERROR_MESSAGE();
		END

	DECLARE @v_dtProcessDateTime DATETIME
	SET @v_dtProcessDateTime = GETDATE();				
	EXEC usp_LogManager
		@in_vchApplicationID = @in_vchApplicationID,
		@in_vchWhID = @v_vchWarehouse,
		@in_vchDevice = @in_vchDeviceID,
		@in_vchUserID = @in_vchUserID,
		@in_vchLogType = 'PROCESS',
		@in_vchProcess = @c_vchObjName,
		@in_dtProcessDateTime = @v_dtProcessDateTime,
		@in_vchData1 = @in_vchLoadID,
		@in_vchData2 = @v_vchPicklistNumber,
		@in_vchData3 = @in_vchForklift,
		@in_vchData4 = @in_vchStagingLocation,
		@in_vchErrorCode = @out_ErrorCode,
		@in_vchMessage = @out_ErrorMessage

	SET @out_ErrorCode = 'CONTACT_ADMIN';
	SELECT @out_ErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_ErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
End Catch	
END

GO
/****** Object:  StoredProcedure [dbo].[usp_pda_inbound_generate_receipt_number]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_pda_inbound_generate_receipt_number]
	-- Add the parameters for the stored procedure here
	@in_vchInboundOrderNumber		NVARCHAR(50),
	@in_vchWhMasterID				VARCHAR(40),
	@in_vchUserID					NVARCHAR(40),
	@out_vchReceiptNumber			NVARCHAR(50) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE	@v_vchInboundOrderMasterID		NVARCHaR(50),
			@v_vchLastReceiptNumber			NVARCHAR(50),
			@v_fltLastNumber				FLOAT,
			@v_fltNextNumber				FLOAT,
			@v_vchErrorMessage				NVARCHAR(250)

    -- Insert statements for procedure here
	SELECT @v_vchInboundOrderMasterID = inbound_order_master_id
	FROM t_wms_inbound_master
	WHERE inbound_order_number = @in_vchInboundOrderNumber
	AND wh_master_id = @in_vchWhMasterID
	IF(@@ROWCOUNT > 0)
		BEGIN
			--GET LAST Receipt Number
			SELECT  @v_fltLastNumber = CONVERT(float,RIGHT((MAX(receipt_number)),3)) 
			FROM t_wms_receipt_header 
			WHERE inbound_order_master_id = @v_vchInboundOrderMasterID

			IF(@v_fltLastNumber IS NULL)
				BEGIN
					SET @v_fltLastNumber = 0
				END

			SET @v_fltNextNumber = @v_fltLastNumber + 1;
			SET	@out_vchReceiptNumber = @in_vchInboundOrderNumber + '-' +  RIGHT('000'+CONVERT(VARCHAR(20),@v_fltNextNumber),3)


			BEGIN TRY
				BEGIN TRANSACTION

					INSERT INTO t_wms_receipt_header (receipt_header_id, inbound_order_master_id, receipt_number, receipt_status, create_by, create_date)
					VALUES (NEWID(), @v_vchInboundOrderMasterID, @out_vchReceiptNumber, 'OPEN', @in_vchUserID, GETDATE())
			
				COMMIT TRANSACTION
			END TRY
			BEGIN CATCH
				ROLLBACK TRANSACTION
				SET @out_vchReceiptNumber = ''
				SET @v_vchErrorMessage = ERROR_MESSAGE();
			END CATCH
		END
	ELSE
		BEGIN
			SET @out_vchReceiptNumber = ''
		END
END



GO
/****** Object:  StoredProcedure [dbo].[usp_physical_count]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_physical_count]  
	@in_vchApplicationID	 NVARCHAR(40),  
	@in_vchDeviceID			 NVARCHAR(50),
	@in_vchUserID			 NVARCHAR(25),
	@in_vchWhMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchWhID				 NVARCHAR(25),
	@in_vchCountID			 NVARCHAR(50) = NULL,
	@in_vchOwnerID			 UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerCode		 NVARCHAR(40)  = NULL,
	@in_vchLocationID		 UNIQUEIDENTIFIER = NULL, 
 	@in_vchLocation			 NVARCHAR(50)  = NULL,
	@in_vchLPN				 NVARCHAR(25) = NULL,
	@in_vchItemStatus	     NVARCHAR(50) = NULL,
	@in_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
	@in_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		 NVARCHAR(50)  = NULL,
	@in_vchLotNumber		 NVARCHAR(50)  = NULL,
	@in_vchExpiryDate		 NVARCHAR(50)	= NULL,
	@in_vchAttribute1		 NVARCHAR(100)	= NULL,
	@in_vchAttribute2		 NVARCHAR(100)	= NULL,
	@in_vchAttribute3		 NVARCHAR(100) = NULL,
	@in_vchAttribute4		 NVARCHAR(100) = NULL,
	@in_vchAttribute5		 NVARCHAR(100) = NULL,
	@in_vchSerialNumber		 NVARCHAR(50)  = NULL,
	@in_vchUOMPrompt		 NVARCHAR(40),
	@in_fltQuantity			 FLOAT,
	@out_vchErrorCode		 VARCHAR(50) OUTPUT,
	@out_vchErrorMessage	 NVARCHAR(500) OUTPUT  
AS  
BEGIN  
	SET NOCOUNT ON;
	DECLARE @c_vchObjName			NVARCHAR(30) = '[usp_physical_count]', -- The name that uniquely tags this object.
			@v_vchProcessData1		NVARCHAR(1000) = NULL,
			@v_vchProcessData2		NVARCHAR(1000) = NULL,
			@v_vchProcessData3		NVARCHAR(1000) = NULL,
			@v_vchProcessData4		NVARCHAR(1000) = NULL,
			@v_dtProcessDateTime	DATETIME	   = NULL,
			@Round					INT,
			@v_vchRuleAdjustInv		VARCHAR(5),
			@v_vchBeginTrans		BIT = 0,
			@v_vchCountStatus		NVARCHAR(10),
			@v_vchCountMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchCountDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		UNIQUEIDENTIFIER = NULL,
			
			@v_vchItemUomID			UNIQUEIDENTIFIER = NULL,
			@v_fltConversionFactor	FLOAT,  
			@v_vchIsPrimaryUOM		VARCHAR(3),
			@v_vchUOM				NVARCHAR(20), 
			@v_vchLotControl		VARCHAR(5), 
			@v_vchSNControl			VARCHAR(5), 
			@v_vchExpiryDateControl	VARCHAR(5), 
			@v_vchAttribute1Control VARCHAR(5),
			@v_vchAttribute2Control	VARCHAR(5),
			@v_vchAttribute3Control	VARCHAR(5),
			@v_vchAttribute4Control	VARCHAR(5),
			@v_vchAttribute5Control	VARCHAR(5),
			@v_fltBaseInputQuantity FLOAT,
			@v_fltExpectQty			FLOAT
		
	BEGIN TRY
		SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
		SELECT TOP 1 @v_vchRuleAdjustInv = value FROM t_wms_rule WHERE rule_code = 'RULE_ADJUST_INVENT' AND is_active = 'YES'

		IF (ISNULL(@in_vchItemStatus,'') = '')
			SET @in_vchItemStatus = 'Available' 

		-- Check Warehouse
		IF NOT EXISTS (SELECT wh_master_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES')
			BEGIN
				SET @out_vchErrorCode = 'WAREHOUSE_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWhID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END
		
		-- Check Locaiton
		IF NOT EXISTS (SELECT location_id FROM t_wms_location where location_id = @in_vchLocationID AND is_active = 'YES')
			BEGIN
				SET @out_vchErrorCode = 'LOCATION_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchLocation,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END  

		-- Check count master id  
		SELECT TOP 1 @v_vchCountMasterID = count_master_id 
			,@v_vchCountStatus = count_status
		FROM t_wms_count_plan_master
		WHERE count_id = @in_vchCountID
		AND wh_master_id = @in_vchWhMasterID
		IF(@v_vchCountMasterID IS NULL)  
			BEGIN
				SET @out_vchErrorCode = 'COUNT_ID_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END

		IF(@v_vchCountStatus = 'CLOSE')
			BEGIN
				SET @out_vchErrorCode = 'COUNT_IS_CLOSE';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchCountID,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC  
			END
	
		--------------------------------------------------------------------
		-- ตรวจสอบ Item Number ในแผน และ ใน Cross Ref
		-------------------------------------------------------------------- 
		SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
				, @in_vchItemNumber = item.item_number 
				, @v_vchLotControl = item.lot_control
				, @v_vchExpiryDateControl = item.expiry_date_control
				, @v_vchSNControl = item.sn_control
				, @v_vchAttribute1Control = item.attribute1_control
				, @v_vchAttribute2Control = item.attribute2_control
				, @v_vchAttribute3Control = item.attribute3_control
				, @v_vchAttribute4Control = item.attribute4_control
				, @v_vchAttribute5Control = item.attribute5_control
		FROM t_wms_item item
		WHERE item.item_master_id = @in_vchItemMasterID
		IF @v_vchItemMasterID IS NULL
			BEGIN
				SET @out_vchErrorCode = 'ITEM_NUMBER_NOT_FOUND';
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchItemNumber,'@param2','@param3','@param4','@param5')  
				GOTO WRITE_PROC;
			END
			
		-- Check warehouse item 
		IF NOT EXISTS (SELECT wh_item_master_id FROM t_wms_wh_item WHERE wh_item_master_id = @in_vchWhItemMasterID)
			BEGIN
				SET @out_vchErrorCode = 'WAREHOUSE_ITEM_NOT_FOUND';  
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchWhID,@in_vchItemNumber,'@param3','@param4','@param5')  
				GOTO WRITE_PROC;
			END  

		-- Check item uom ,conversion factor 
		-- Get & Check Item UOM
		SET @v_vchItemUomID = NULL
		SELECT @v_vchItemUomID = item_uom_id
			,@v_fltConversionFactor = conversion_factor
			,@v_vchIsPrimaryUOM = primary_uom
			,@v_vchUOM = uom
		FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID 
		AND uom_prompt = @in_vchUOMPrompt
		AND is_active = 'YES'		
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				SET @out_vchErrorCode = 'UOM_NOT_FOUND';
				SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchUOMPrompt,'@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			End

		--Get Primary Uom
		IF @v_vchIsPrimaryUOM = 'NO'
			BEGIN
				SELECT @v_vchItemUomID = item_uom_id
					,@in_vchUOMPrompt = uom_prompt
					,@v_vchUOM = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES' 
				AND is_active = 'YES'
			END

		SET @v_fltBaseInputQuantity = ROUND(@in_fltQuantity * @v_fltConversionFactor,@Round);
		 
	BEGIN TRANSACTION;
	SET @v_vchBeginTrans = 1;
		BEGIN 
			SELECT @v_vchCountDetailID = countDT.count_plan_detail_id
				, @v_fltExpectQty = countDT.stock_qty
			FROM t_wms_count_plan_master countMS
			INNER JOIN t_wms_count_plan_detail countDT ON countMS.count_master_id = countDT.count_master_id
			WHERE countMS.count_master_id = @v_vchCountMasterID
			AND countMS.owner_id = @in_vchOwnerID
			AND countDT.location_id = @in_vchLocationID
			AND countDT.wh_item_master_id = @in_vchWhItemMasterID
			AND countDT.inv_status = @in_vchItemStatus
			AND ISNULL(countDT.lpn,'') = ISNULL(@in_vchLPN,'')
			AND ISNULL(countDT.lot,'') = ISNULL(@in_vchLotNumber,'')
			AND ISNULL(countDT.expiry_date,'') = ISNULL(@in_vchExpiryDate,'')
			AND ISNULL(countDT.attribute1,'') = ISNULL(@in_vchAttribute1,'')
			AND ISNULL(countDT.attribute2,'') = ISNULL(@in_vchAttribute2,'')
			AND ISNULL(countDT.attribute3,'') = ISNULL(@in_vchAttribute3,'')
			AND ISNULL(countDT.attribute4,'') = ISNULL(@in_vchAttribute4,'')
			AND ISNULL(countDT.attribute5,'') = ISNULL(@in_vchAttribute5,'')
			AND ISNULL(countDT.serial_number,'') = ISNULL(@in_vchSerialNumber,'')

			IF (@v_vchSNControl = 'FULL')
				BEGIN
					 IF EXISTS (SELECT count_reconcile_id FROM t_wms_count_reconcile WHERE count_master_id = @v_vchCountMasterID AND serial_number = @in_vchSerialNumber)
						BEGIN
								COMMIT TRANSACTION;
								SET @out_vchErrorCode = 'INFO-SN-ALREADY-COUNT';  
								SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@in_vchSerialNumber,'@param2','@param3','@param4','@param5');
								RETURN;
						END
				END

			-- Update Count Qty
			IF (@v_vchCountDetailID IS NOT NULL)
				BEGIN
					UPDATE t_wms_count_plan_detail SET count_qty = ROUND(ISNULL(count_qty,0) + @v_fltBaseInputQuantity,@ROUND)
						,count_by = @in_vchUserID
						,count_date = GETDATE()
					WHERE count_plan_detail_id = @v_vchCountDetailID
				END
			
			BEGIN -- Insert Reconcile
				INSERT INTO [dbo].[t_wms_count_reconcile]
						([count_reconcile_id]
						,[count_master_id]
						,[location_id]
						,[wh_item_master_id]
						,[inv_status]
						,[parent_lpn]
						,[lpn]
						,[lot]
						,[expiry_date]
						,[serial_number]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[expect_qty]
						,[count_qty]
						,[adjusted_qty]
						,[adjust_by]
						,[create_date]
						,[create_by])
					VALUES
						(NEWID()
						,@v_vchCountMasterID
						,@in_vchLocationID
						,@in_vchWhItemMasterID
						,@in_vchItemStatus
						,NULL
						,(CASE ISNULL(@in_vchLPN,'') WHEN '' THEN NULL ELSE @in_vchLPN END)
						,(CASE ISNULL(@in_vchLotNumber,'') WHEN '' THEN NULL ELSE @in_vchLotNumber END)
						,(CASE ISNULL(@in_vchExpiryDate,'') WHEN '' THEN NULL ELSE @in_vchExpiryDate END)
						,(CASE ISNULL(@in_vchSerialNumber,'') WHEN '' THEN NULL ELSE @in_vchSerialNumber END)
						,(CASE ISNULL(@in_vchAttribute1,'') WHEN '' THEN NULL ELSE @in_vchAttribute1 END)
						,(CASE ISNULL(@in_vchAttribute2,'') WHEN '' THEN NULL ELSE @in_vchAttribute2 END)
						,(CASE ISNULL(@in_vchAttribute3,'') WHEN '' THEN NULL ELSE @in_vchAttribute3 END)
						,(CASE ISNULL(@in_vchAttribute4,'') WHEN '' THEN NULL ELSE @in_vchAttribute4 END)
						,(CASE ISNULL(@in_vchAttribute5,'') WHEN '' THEN NULL ELSE @in_vchAttribute5 END)
						,@v_fltExpectQty
						,@v_fltBaseInputQuantity
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN @v_fltBaseInputQuantity ELSE NULL END)
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN @in_vchUserID ELSE NULL END)
						,GETDATE()
						,@in_vchUserID
						)
			END

			--Update Count Status
			UPDATE t_wms_count_plan_master SET count_status = 'IN PROCESS' WHERE count_master_id = @v_vchCountMasterID

			IF (@v_vchRuleAdjustInv = 'YES') 
				BEGIN
					DECLARE @v_vchInvStatusID	 UNIQUEIDENTIFIER = NULL
					SELECT @v_vchInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchItemStatus AND is_active = 'YES'
					IF @v_vchInvStatusID IS NULL
					BEGIN
						GOTO WRITE_PROC;
					END

					DECLARE @v_vchReferenceNumber NVARCHAR(50) = NULL
					EXEC usp_get_ReferenceID @v_vchReferenceNumber OUTPUT	
					EXEC usp_inventory_adjust_in @in_vchApplicationID		= @in_vchApplicationID
												, @in_vchDevice				= @in_vchDeviceID
												, @in_vchUserID				= @in_vchUserID
												, @in_vchTransactionType	= 'INV_ADJUST'	
												, @in_vchSubTranType		= 'PHYSICAL_COUNT'	
												, @in_vchWhMasterID			= @in_vchWhMasterID
												, @in_vchOwnerID			= @in_vchOwnerID
												, @in_vchInvStatusID		= @v_vchInvStatusID
												, @in_vchLocationID			= @in_vchLocationID	
											    , @in_vchWhItemMasterID		= @in_vchWhItemMasterID
												, @in_vchParentLPN			= NULL
												, @in_vchLPN				= @in_vchLPN	 
												, @in_vchLotNumber			= @in_vchLotNumber
												, @in_vchExpiryDate			= @in_vchExpiryDate
												, @in_vchAttribute1			= @in_vchAttribute1
												, @in_vchAttribute2			= @in_vchAttribute2
												, @in_vchAttribute3			= @in_vchAttribute3
												, @in_vchAttribute4			= @in_vchAttribute4
												, @in_vchAttribute5			= @in_vchAttribute5 
												, @in_fltQty				= @v_fltBaseInputQuantity	
												, @in_vchItemUomID			= @v_vchItemUomID
												, @in_vchSerialNumber		= @in_vchSerialNumber	
												, @in_vchReasonID			= NULL
												, @in_dtReceiveDate			= NULL	
												, @in_dtMfgDate				= NULL	
												, @in_vchReferenceNumber	= @v_vchReferenceNumber
												, @out_ErrorCode			= @out_vchErrorCode		OUTPUT
												, @out_ErrorMessage			= @out_vchErrorMessage	OUTPUT
  
					IF (@out_vchErrorCode <> '0')  
						BEGIN   
							GOTO WRITE_PROC;  
						END  
				END
		END

	COMMIT TRANSACTION;
	SET @out_vchErrorCode = '0';  
	SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')      
	RETURN;

	---------------------------------------------------
	BEGIN -- Write Process Log
		WRITE_PROC:							
	---------------------------------------------------
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;
		
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Count ID: '+ @in_vchCountID
		SET @v_vchProcessData2 = 'Location: '+ @in_vchLocation
		SET @v_vchProcessData3 = 'Item number: ' + @in_vchItemNumber;
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWhID,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_vchErrorCode,
			@in_vchMessage = @out_vchErrorMessage
	END	

	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMessage = ERROR_MESSAGE();
		SET @v_dtProcessDateTime = GETDATE(); 
		SET @v_vchProcessData1 = 'Count ID: '+ @in_vchCountID
		SET @v_vchProcessData2 = 'Location: '+ @in_vchLocation
		SET @v_vchProcessData3 = 'Item number: ' + @in_vchItemNumber;
				
		EXEC usp_LogManager
			@in_vchApplicationID = @in_vchApplicationID,
			@in_vchWhID = @in_vchWhID,
			@in_vchDevice = @in_vchDeviceID,
			@in_vchUserID = @in_vchUserID,
			@in_vchLogType = 'PROCESS',
			@in_vchProcess = @c_vchObjName,
			@in_dtProcessDateTime = @v_dtProcessDateTime,
			@in_vchData1 = @v_vchProcessData1,
			@in_vchData2 = @v_vchProcessData2,
			@in_vchData3 = @v_vchProcessData3,
			@in_vchData4 = @v_vchProcessData4,
			@in_vchErrorCode = @out_vchErrorCode,
			@in_vchMessage = @out_vchErrorMessage
		SET @out_vchErrorCode = 'CONTACT_ADMIN';
		SELECT @out_vchErrorMessage =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		
		 	
	END CATCH
END
GO
