CREATE PROCEDURE [dbo].[usp_pick_binding_serial_number]
(		
    @in_startRowIndex			INT,
	@in_maximumRows				INT,
	@in_vchCondition			NVARCHAR(1000) = '',
	@in_vchSort					NVARCHAR(1000) = '',
	@in_switchType				NVARCHAR(10),
	@out_rowCount				INT = 0 OUTPUT,

	@in_vchWhMasterID		  NVARCHAR(50),
	@in_vchOutboundPickMasterID NVARCHAR(50),
	@in_vchOwnerID			  NVARCHAR(50),
	@in_vchLocationID		  NVARCHAR(50), 
	@in_vchParentLPN		  NVARCHAR(25),
	@in_vchLPN				  NVARCHAR(25), 
	@in_vchWhItemMasterID	  NVARCHAR(50)  = NULL, 
	@in_vchLotNumber		  NVARCHAR(50) = NULL,  
	@in_vchExpiryDate		  NVARCHAR(20) = NULL,	--Expiry Date ที่ Scan ต้องส่งมา Format yyyyMMdddd 
	@in_ReceiveDate			  Date	,
	@in_vchAttribute1	      NVARCHAR(100) = NULL,
	@in_vchAttribute2	      NVARCHAR(100) = NULL,
	@in_vchAttribute3	      NVARCHAR(100) = NULL,
	@in_vchAttribute4	      NVARCHAR(100) = NULL,
	@in_vchAttribute5	      NVARCHAR(100) = NULL
)
AS
BEGIN

DECLARE @v_vchStrQuery		NVARCHAR(MAX);
DECLARE @v_vchCondition		NVARCHAR(1000)	=	'';

-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

--select @v_cur_date
IF @in_vchCondition != ''
BEGIN
	SET @v_vchCondition = 'WHERE ' + @in_vchCondition
END

	SET @v_vchStrQuery ='(SELECT serial_number 
	FROM v_wms_inventory_data_serial_by_id
	WHERE  wh_master_id = '''+@in_vchWhMasterID+'''
	AND owner_id = '''+@in_vchOwnerID+'''
	AND location_id = '''+@in_vchLocationID+'''
	AND ISNULL(parent_lpn,'''') = ISNULL('''+@in_vchParentLPN+''','''')
	AND ISNULL(lpn,'''') = ISNULL('''+@in_vchLPN+''','''')
	AND wh_item_master_id = '''+@in_vchWhItemMasterID+'''
	AND ISNULL(lot_number,'''') = ISNULL('''+@in_vchLotNumber+''','''')
	AND ISNULL(expiry_date,'''') = ISNULL('''+@in_vchExpiryDate+''','''')
	AND ISNULL(attribute1,'''') = ISNULL('''+@in_vchAttribute1+''','''')
	AND ISNULL(attribute2,'''') = ISNULL('''+@in_vchAttribute2+''','''')
	AND ISNULL(attribute3,'''') = ISNULL('''+@in_vchAttribute3+''','''')
	AND ISNULL(attribute4,'''') = ISNULL('''+@in_vchAttribute4+''','''')
	AND ISNULL(attribute5,'''') = ISNULL('''+@in_vchAttribute5+''','''')
	AND FORMAT(receive_date,''yyyyMMdd'')  = '''+ format(@in_ReceiveDate,'yyyyMMdd') +'''
	AND serial_number NOT IN (SELECT serial_number 
								FROM t_wms_outbound_pick_detail
								WHERE outbound_pick_master_id <> '''+@in_vchOutboundPickMasterID+'''
								AND ISNULL(quantity_pick,0) = 0
								AND is_override = ''NO''
								AND wh_item_master_id = '''+@in_vchWhItemMasterID+'''
								AND ISNULL(serial_number,'''') <> '''')
	AND serial_number NOT IN (SELECT isnull(CASE WHEN ISNULL(serial_number,'''') = '''' THEN confirm_serial_number_pc ELSE serial_number END,'''') AS serial_number
								FROM t_wms_outbound_pick_detail
								WHERE outbound_pick_master_id = '''+ @in_vchOutboundPickMasterID +''')) as qry '+ @v_vchCondition 
 
--print @str_query
EXEC [dbo].[usp_string_query_paging]  @in_startRowIndex = @in_startRowIndex	
									  ,@in_maximumRows	 = @in_maximumRows		
									  ,@in_vchWithQuery	 = ''	
									  ,@in_vchQuery		 = @v_vchStrQuery		
									  ,@in_vchSort		 = @in_vchSort			
									  ,@in_switchType	 = @in_switchType		
									  ,@out_rowCount	 = @out_rowCount OUTPUT	


	
END
