/****** Object:  StoredProcedure [dbo].[usp_pick_qty_more_order_qty]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_pick_qty_more_order_qty]
	-- Add the parameters for the stored procedure here
	@wh_id						NVARCHAR(50),
	@outbound_order_number		NVARCHAR(50),
	@parent_lpn					NVARCHAR(50),
	@lpn						NVARCHAR(50),
	@item_number				NVARCHAR(50),
	@qty_issue					FLOAT,
	@uom_prompt					NVARCHAR(50),
	@resultValue				NVARCHAR(50) OUTPUT
	
AS
BEGIN
	
	
	-- Declare Variable.
	DECLARE @qty_remain_pick					FLOAT,
			@order_uom_prompt					NVARCHAR(50),
			@primary_uom						NVARCHAR(50),
			@issue_conversion_factor			FLOAT,
			@order_conversion_factor			FLOAT
	
	-- Get remain quantity
	SELECT	@qty_remain_pick = quantity_remain_pick,
			@order_uom_prompt = uom_prompt
	FROM	v_wms_outbound_pick_detail
	WHERE	wh_id = @wh_id
	AND		outbound_order_number = @outbound_order_number
	AND		parent_lpn = @parent_lpn
	AND		lpn = @lpn
	AND		item_number = @item_number
	
	
	IF (@uom_prompt = @order_uom_prompt)
	BEGIN
		IF (@qty_remain_pick >= @qty_issue)
		BEGIN
			Set @resultValue = 0;
		END
		ELSE
		BEGIN
			Set @resultValue = 1;
		END
	END
	ELSE
	BEGIN
		
		-- Convert issue qty.
		SELECT	@issue_conversion_factor = conversion_factor
		FROM	v_wms_item_uom
		WHERE	item_number = @item_number
		AND		uom = @uom_prompt
				
		-- Convert order plan qty.
		SELECT	@order_conversion_factor = conversion_factor 
		FROM	v_wms_item_uom
		WHERE	item_number = @item_number
		AND		uom = @order_uom_prompt
		
		IF ((@order_conversion_factor * @qty_remain_pick) >= (@issue_conversion_factor * @qty_issue))
		BEGIN
			Set @resultValue = 0;
		END
		ELSE
		BEGIN
			Set @resultValue = 1;
		END
		
	END
	
	--SELECT @resultValue
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_pick_to_light_binding_system_pick_order]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_pick_to_light_binding_system_pick_order]
( 
	@in_vchControlName	NVARCHAR(50),
	@in_vchUserID		NVARCHAR(25), 
	@in_vchWhMasterID	UNIQUEIDENTIFIER,
	@in_vchOutboundPickMasterID UNIQUEIDENTIFIER,
	@in_vchLocationID	UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT ON;
	IF @in_vchControlName = 'ORDER_NUMBER'
		BEGIN
			----------------------------------------------------------
			-- Binding Outbound Order Number
			-- กรณีที่ไม่ให้ช่วยกันหยิบ
			----------------------------------------------------------
			SELECT outbound_order_master_id	 AS value_member
				,outbound_order_number		 AS display_member
			FROM dbo.t_wms_outbound_master
			WHERE (order_status NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_BY_ORDER_STATUS' AND is_active = 'YES'))
			AND (order_type NOT IN (SELECT value FROM dbo.t_wms_rule WHERE rule_code = 'RULE_GET_OUTBOUND_ORDER_TYPE_FOR_KITTING' AND is_active = 'YES'))
			AND wh_master_id = @in_vchWhMasterID
			AND pick_type = 'SYSTEM'
			AND (pick_by = @in_vchUserID OR ISNULL(pick_by,'') = '') 
			ORDER BY outbound_order_number
			RETURN;
		END

	IF @in_vchControlName = 'LOCATION'
		BEGIN
			----------------------------------------------------------
			-- Binding Location for Picking
			----------------------------------------------------------
			SELECT DISTINCT value_member
				,display_member
			FROM (SELECT pickDT.location_id AS value_member
					,loc.location AS display_member
					,CONVERT(INT,obDT.line_number) AS line_number
					,ROW_NUMBER() OVER(PARTITION BY loc.location ORDER BY loc.pick_sequence,loc.location,CONVERT(INT,obDT.line_number)) AS is_min
				  FROM t_wms_outbound_pick_detail pickDT
				  INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
				  INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
				  WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID
				  AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
				  AND pickDT.is_override = 'NO') outbound
			WHERE outbound.is_min = 1
			RETURN; 
		END

	IF @in_vchControlName = 'ITEM_NUMBER'
		BEGIN
			SELECT item.value_member
				,item.display_member
			FROM (SELECT obDT.item_master_id AS value_member
	  				,obDT.item_number AS display_member
	  				,ROW_NUMBER() OVER(PARTITION BY obDT.item_number ORDER BY CONVERT(INT,obDT.line_number)) AS is_min
	  				,CONVERT(INT,obDT.line_number) AS line_number
					FROM  t_wms_outbound_pick_detail pickDT
					INNER JOIN t_wms_outbound_detail obDT ON pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
					WHERE pickDT.outbound_pick_master_id = @in_vchOutboundPickMasterID 
					AND pickDT.location_id = @in_vchLocationID
					AND ISNULL(pickDT.quantity_pick,0) < ISNULL(pickDT.quantity_plan,0)
					AND pickDT.is_override = 'NO'
					) item
			WHERE item.is_min = 1
			ORDER BY CONVERT(INT,item.line_number)
			RETURN; 
		END
END
GO
