-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_pod_getdetail_byorder]
	-- Add the parameters for the stored procedure here
	@in_order_pod_id  uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @out_order_id uniqueidentifier = null
	Select @out_order_id =  pod.[outbound_order_master_id] From [t_wms_pod] pod   
	where pod.[order_status] = 'PENDING' and pod.[outbound_order_pod_id] = @in_order_pod_id 
    -- Insert statements for procedure here
	SELECT pod.[outbound_order_pod_id]
      ,pod.[outbound_order_master_id]
      ,pod.[route_code]
      ,pod.[route_name]
      ,pod.[order_status]
      ,pod.[pod_date_plan]
      ,pod.[pod_date_actual]
      ,pod.[user_def1]
      ,pod.[user_def2]
      ,pod.[user_def3]
      ,pod.[user_def4]
      ,pod.[user_def5]
      ,pod.[user_def6]
      ,pod.[user_def7]
      ,pod.[user_def8]
      ,pod.[user_def9]
      ,pod.[user_def10]
      ,pod.[customer_image]
      ,pod.[print_time]
      ,pod.[sign_name]
      ,outM.[outbound_order_number]
      ,outM.[order_status]
      ,outM.[order_date]
      ,outM.[description]
      ,outM.[customer_id]
      ,outM.[customer_code]
      ,outM.[customer_name]
      ,outM.[cus_description]
      ,outM.[cus_addr_line_1]
      ,outM.[cus_addr_line_2]
      ,outM.[cus_addr_line_3]
      ,outM.[cus_city]
      ,outM.[cus_province]
      ,outM.[cus_postal_code]
      ,outM.[cus_country_code]
      ,outM.[cus_country_name]
      ,outM.[cus_contact]
      ,outM.[cus_phone]
      ,outM.[cus_fax]
      ,outM.[cus_email]
      ,outM.[ship_to_code]
      ,outM.[ship_to_name]
      ,outM.[ship_to_description]
      ,outM.[ship_to_addr_line_1]
      ,outM.[ship_to_addr_line_2]
      ,outM.[ship_to_addr_line_3]
      ,outM.[ship_to_city]
      ,outM.[ship_to_province]
      ,outM.[ship_to_postal_code]
      ,outM.[ship_to_country_code]
      ,outM.[ship_to_country_name]
      ,outM.[ship_to_contact]
      ,outM.[ship_to_phone]
      ,outM.[ship_to_fax]
      ,outM.[ship_to_email]
  FROM [dbo].[t_wms_pod] pod
  INNER JOIN
  t_wms_outbound_master outM ON pod.outbound_order_master_id = outM.outbound_order_master_id --AND outM.order_status = ''
  where pod.[order_status] = 'PENDING' and pod.[outbound_order_pod_id] = @in_order_pod_id
	
	
	SELECT dt.*,it.item_number,it.item_description,uo.uom,uo.uom_prompt from t_wms_outbound_detail dt
	inner join (select item_master_id,wh_item_master_id from t_wms_wh_item tIt )as wit on dt.wh_item_master_id = wit.wh_item_master_id
	inner join (select item_master_id,item_number,description As item_description from t_wms_item) as it on wit.item_master_id = it.item_master_id
	inner join (select uom,uom_prompt,item_uom_id  from t_wms_item_uom)as uo on dt.item_uom_id = uo.item_uom_id
	where dt.outbound_order_master_id = @out_order_id
END

