-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_pod_update_sign]
	-- Add the parameters for the stored procedure here
	@in_order_pod_id  uniqueidentifier,
	@in_sign_name	nvarchar(50),
	@in_sign_image  image=null,
	@out_ErrorCode int out,
	@out_ErrorMessage nvarchar(255) out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @out_order_id nvarchar(40)
	Begin Try
		update t_wms_pod
		SET [signature] = @in_sign_image
		,sign_name = @in_sign_name
		,print_time = ISNULL(print_time,0) + 1
		,pod_date_actual = GETDATE()
		,order_status = 'CLOSE'
		WHERE outbound_order_pod_id = @in_order_pod_id
		set  @out_ErrorCode =0
		set @out_ErrorMessage = ''
	End Try
	Begin Catch
		set @out_ErrorCode = ERROR_NUMBER();
		set @out_ErrorMessage = ERROR_MESSAGE();
	End catch
END

