CREATE PROCEDURE [dbo].[usp_printing_service]
	-- Add the parameters for the stored procedure here	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE @location_id NVARCHAR(40) 
	DECLARE @printer_sum INT
	DECLARE @group_id NVARCHAR(40) 
	DECLARE @group_name NVARCHAR(50)

	DECLARE @sum_rows INT
	DECLARE @how_many_rows INT
	DECLARE @count_row INT
	DECLARE @count_printer INT
	DECLARE @count_last INT	
	
	DECLARE @count_insert_content INT	
	DECLARE @id VARCHAR(40)
	DECLARE @sequence INT
	DECLARE @group_printer_id VARCHAR(40)
	DECLARE @bartender_data_filepath VARCHAR(255)
	DECLARE @bartender_trigger_filepath VARCHAR(255)
	DECLARE @content NVARCHAR(MAX) 	

	DECLARE @txt_warranty_id NVARCHAR(50) 
	DECLARE @txt_itf_line_number NVARCHAR(50) 
	DECLARE @txt_itf_warranty_number NVARCHAR(50) 
	DECLARE @txt_itf_serial_number NVARCHAR(50) 
	DECLARE @txt_itf_print_date NVARCHAR(50) 
	DECLARE @txt_itf_expire_date NVARCHAR(50) 
	DECLARE @txt_description NVARCHAR(50) 
	DECLARE @txt_item_number NVARCHAR(50) 
	DECLARE @txt_serial_number NVARCHAR(50) 
	DECLARE @txt_warranty_number NVARCHAR(50) 
	DECLARE @txt_warranty_expire NVARCHAR(50) 
	DECLARE @txt_ref NVARCHAR(50) 
	DECLARE @txt_customer_code NVARCHAR(50) 
	DECLARE @txt_customer_name NVARCHAR(50) 
	DECLARE @txt_cus_addr_line_1 NVARCHAR(50) 
	DECLARE @txt_cus_addr_line_2 NVARCHAR(50) 
	DECLARE @txt_cus_addr_line_3 NVARCHAR(50)

	DECLARE @date_print DATETIME

	DECLARE @COUNT_WARRANTY_TODAY INT = 0
	DECLARE @WARRANTY_NUMBER NVARCHAR(13)
	DECLARE @LAST_NVAR_WARRANTY_NUMBER NVARCHAR(13)
	DECLARE @LAST_INT_WARRANTY_NUMBER INT = 0

	DECLARE @txt_server_login NVARCHAR(255) 
	DECLARE @dir_share_path NVARCHAR(255) 
	DECLARE @username NVARCHAR(50) 
	DECLARE @passwd NVARCHAR(50) 			
	
	-- Create temp table
	IF OBJECT_ID('#temp_table_warranty') IS NOT NULL
	BEGIN
		DELETE FROM #temp_table_warranty		
	END
	ELSE
	BEGIN
		CREATE TABLE #temp_table_warranty
		(
			[warranty_id] VARCHAR(40) COLLATE Thai_100_CI_AS NULL		
		)
	END
	IF OBJECT_ID('#temp_table_print_content') IS NOT NULL
	BEGIN
		DELETE FROM #temp_table_print_content		
	END
	ELSE
	BEGIN
		CREATE TABLE #temp_table_print_content
		(
			[id] VARCHAR(40) COLLATE Thai_100_CI_AS NULL,
			[sequence] INT,
			[group_printer_id] VARCHAR(40) COLLATE Thai_100_CI_AS NULL,
			[bartender_data_filepath] NVARCHAR(255) NULL,
			[bartender_trigger_filepath] NVARCHAR(255) NULL,
			[content] NVARCHAR(MAX)  NULL
		)
	END
	

	DECLARE CS_GROUP_PRINTER CURSOR FOR
		SELECT 
			pg.location_id
			, COUNT(*) AS printer_sum 		
		FROM [dbo].[t_com_config_printer_group] pg
			LEFT JOIN [dbo].[t_com_config_printer_group_mapping] pgm ON pg.group_id = pgm.group_id		
		WHERE pg.is_active = 'YES' AND pgm.is_active = 'YES' 
		GROUP BY pg.location_id, pg.group_name
		ORDER BY pg.group_name		
    OPEN CS_GROUP_PRINTER          
    FETCH NEXT FROM CS_GROUP_PRINTER
		INTO @location_id, @printer_sum
    WHILE @@FETCH_STATUS = 0
    BEGIN    
    -- BEGIN FOR LIST INSTRUCTION SET
		IF @printer_sum <> 0
		BEGIN			
			SELECT 
				@group_id = pg.group_id
				, @group_name = pg.group_name 
			FROM [dbo].[t_com_config_printer_group] pg
			WHERE pg.location_id = @location_id
			--PRINT OUTPUT
			SELECT 'location_id : '+@location_id +' group_name : '+@group_name +' printer_sum : '+ CONVERT(NVARCHAR,@printer_sum) 
			AS 'LOOP FOR CS_GROUP_PRINTER----------------------------------------------------------------------------------------'				
			--
			SET @date_print = GETDATE()
			--	
			DELETE FROM #temp_table_warranty
			INSERT INTO #temp_table_warranty ([warranty_id])
			SELECT warr.warranty_id FROM [dbo].[t_mod_warranty] warr
			WHERE warr.location_id = @location_id and warr.print_status = 'WAITING' 
			--
			SELECT @sum_rows = COUNT(*) FROM #temp_table_warranty
			SET @how_many_rows = @sum_rows / @printer_sum
			SET @count_row = 1
			SET @count_printer = 1
			SET @count_last = @how_many_rows
			--PRINT OUTPUT
			SELECT t_warr.warranty_id FROM #temp_table_warranty t_warr
			--
			DELETE FROM #temp_table_print_content
			SET @count_insert_content = 1
			WHILE @count_insert_content <= @printer_sum
			BEGIN
				SELECT TOP(1) 
				  @sequence = sequence
				, @group_printer_id = group_printer_id 
				, @bartender_data_filepath = bartender_data_filepath
				, @bartender_trigger_filepath = bartender_trigger_filepath
				FROM 
					[dbo].[t_com_config_printer_group_mapping] 
				WHERE 
					is_active = 'YES' 
					AND group_id = @group_id
					AND group_printer_id not in (SELECT group_printer_id FROM #temp_table_print_content)
				ORDER BY sequence				
				INSERT INTO #temp_table_print_content
				(
					[id]
					, [sequence]
					, [group_printer_id]
					, [bartender_data_filepath]
					, [bartender_trigger_filepath]
					, [content]
				)
				VALUES
				(
					  @count_insert_content
					, @sequence
					, @group_printer_id
					, @bartender_data_filepath
					, @bartender_trigger_filepath
					, ''
				)
				SET @count_insert_content = @count_insert_content + 1
			END		
			--
			DECLARE CS_WARRANTY CURSOR FOR
				SELECT 
				warr.[warranty_id]
				-----------------------------------------------------------------------------				
				,warr.[line_number]
				,warr.[warranty_number]
				,warr.[serial_number]
				--,GETDATE() AS print_date
				--,warr.warranty_printed AS print_date
				,(REPLACE(SUBSTRING(CONVERT(VARCHAR(24),@date_print,121),1,10),'-','') 
					+ ' ' +SUBSTRING(CONVERT(VARCHAR(24),@date_print,121),12,8)
				) AS print_date				
				--,warr.warranty_expire AS expire_date
				,(REPLACE(SUBSTRING(CONVERT(VARCHAR(24),warr.warranty_expire,121),1,10),'-','') 
					+ ' ' +SUBSTRING(CONVERT(VARCHAR(24),warr.warranty_expire,121),12,8)
				) AS expire_date
				-----------------------------------------------------------------------------
				,(
					SELECT item.[description] FROM t_wms_wh_item whitem
					LEFT JOIN t_wms_item item ON whitem.item_master_id = item.item_master_id	
					WHERE whitem.wh_item_master_id = warr.wh_item_master_id
				 ) AS [description]
				,(
					SELECT item.[item_number] FROM t_wms_wh_item whitem
					LEFT JOIN t_wms_item item ON whitem.item_master_id = item.item_master_id	
					WHERE whitem.wh_item_master_id = warr.wh_item_master_id
				) AS [item_number]
				,warr.serial_number
				,warr.warranty_number
				--,warr.warranty_expire
				, (CASE datepart(mm,warr.warranty_expire) 
				  WHEN 1 THEN 'ม.ค.' 
				  WHEN 2 THEN 'ก.พ.'  
				  WHEN 3 THEN 'มี.ค.' 
				  WHEN 4 THEN 'เม.ย' 
				  WHEN 5 THEN 'พ.ค.' 
				  WHEN 6 THEN 'มิ.ย.' 
				  WHEN 7 THEN 'ก.ค.' 
				  WHEN 8 THEN 'ส.ค.' 
				  WHEN 9 THEN 'ก.ย.' 
				  WHEN 10 THEN 'ต.ค.' 
				  WHEN 11 THEN 'พ.ย.' 
				  WHEN 12 THEN 'ธ.ค.' 
				  ELSE ' ' 
				END)+ ' ' + CONVERT(NVARCHAR,(CONVERT(INT,datepart(YYYY,warr.warranty_expire))+543)) AS [warranty_expire]
				,warr.outbound_order_number+'#'+warr.load_number AS [ref]
				,(SELECT m.customer_code FROM [dbo].[t_wms_outbound_master] m WHERE m.outbound_order_master_id = warr.[outbound_order_master_id]) AS [customer_code]
				,(SELECT m.customer_name FROM [dbo].[t_wms_outbound_master] m WHERE m.outbound_order_master_id = warr.[outbound_order_master_id]) AS [customer_name]
				,(SELECT m.cus_addr_line_1 FROM [dbo].[t_wms_outbound_master] m WHERE m.outbound_order_master_id = warr.[outbound_order_master_id]) AS [cus_addr_line_1]
				,(SELECT m.cus_addr_line_2 FROM [dbo].[t_wms_outbound_master] m WHERE m.outbound_order_master_id = warr.[outbound_order_master_id]) AS [cus_addr_line_2]
				,(SELECT m.cus_addr_line_3 FROM [dbo].[t_wms_outbound_master] m WHERE m.outbound_order_master_id = warr.[outbound_order_master_id]) AS [cus_addr_line_3]
				---------------------------------------------------------------------------
				FROM [dbo].[t_mod_warranty] warr
				WHERE warr.warranty_id IN (SELECT t_warr.warranty_id FROM #temp_table_warranty t_warr)
				ORDER BY warr.create_date ASC	

			OPEN CS_WARRANTY          
			FETCH NEXT FROM CS_WARRANTY
				INTO @txt_warranty_id, @txt_itf_line_number, @txt_itf_warranty_number, @txt_itf_serial_number, @txt_itf_print_date, @txt_itf_expire_date
			, @txt_description, @txt_item_number, @txt_serial_number, @txt_warranty_number, @txt_warranty_expire, @txt_ref
			, @txt_customer_code, @txt_customer_name, @txt_cus_addr_line_1, @txt_cus_addr_line_2, @txt_cus_addr_line_3
			WHILE @@FETCH_STATUS = 0
			BEGIN    
			-- BEGIN FOR LIST INSTRUCTION SET	
				--
				IF @txt_warranty_number IS NULL
				BEGIN
					SELECT @COUNT_WARRANTY_TODAY = COUNT(*) FROM [dbo].[t_mod_warranty]
					WHERE warranty_printed >= SUBSTRING(CONVERT(VARCHAR(24),GETDATE(),121),1,10) --'2014-02-20'
					IF @COUNT_WARRANTY_TODAY > 0
					BEGIN	
						SELECT TOP(1) @LAST_NVAR_WARRANTY_NUMBER = warranty_number FROM [dbo].[t_mod_warranty]
						WHERE warranty_printed >= SUBSTRING(CONVERT(VARCHAR(24),GETDATE(),121),1,10)
						ORDER BY warranty_number DESC
						IF @LAST_NVAR_WARRANTY_NUMBER = '' OR @LAST_NVAR_WARRANTY_NUMBER IS NULL
						BEGIN
							SET @WARRANTY_NUMBER = SUBSTRING(CONVERT(NVARCHAR,(CONVERT(INT,datepart(YYYY,GETDATE()))+543)),3,2)
								+RIGHT('0'+CONVERT(NVARCHAR,(CONVERT(INT,datepart(mm,GETDATE())))),2)
								+RIGHT('000000000'+'1',9)
							PRINT 'C1'
						END
						ELSE
						BEGIN		
							SET @LAST_INT_WARRANTY_NUMBER = CONVERT(INT, RIGHT(@LAST_NVAR_WARRANTY_NUMBER,9)) + 1		 
							SET @WARRANTY_NUMBER = SUBSTRING(CONVERT(NVARCHAR,(CONVERT(INT,datepart(YYYY,GETDATE()))+543)),3,2)
								+RIGHT('0'+CONVERT(NVARCHAR,(CONVERT(INT,datepart(mm,GETDATE())))),2)
								+RIGHT('000000000'+ CONVERT(NVARCHAR,@LAST_INT_WARRANTY_NUMBER),9)
							PRINT 'C2'
						END	
					END
					ELSE
					BEGIN
						SET @WARRANTY_NUMBER = SUBSTRING(CONVERT(NVARCHAR,(CONVERT(INT,datepart(YYYY,GETDATE()))+543)),3,2)
						+RIGHT('0'+CONVERT(NVARCHAR,(CONVERT(INT,datepart(mm,GETDATE())))),2)
						+RIGHT('000000000'+'1',9)
						PRINT 'C3'
					END
					SET @txt_warranty_number = @WARRANTY_NUMBER
					UPDATE [dbo].[t_mod_warranty] 
						SET [print_status] = 'COMPLETED'
							, [warranty_printed] = @date_print
							, [warranty_number] = @txt_warranty_number
						WHERE [warranty_id] = @txt_warranty_id
				END
				ELSE
				BEGIN
					UPDATE [dbo].[t_mod_warranty] 
						SET [print_status] = 'COMPLETED'
							, [warranty_printed] = @date_print
						WHERE [warranty_id] = @txt_warranty_id
				END
				--		
				SELECT @content = content FROM #temp_table_print_content
				WHERE id = @count_printer				
				SET @content = @content + (
											@txt_itf_line_number						--1
											+'|'+ ISNULL(@txt_itf_warranty_number,'')	--2
											+'|'+ ISNULL(@txt_itf_serial_number,'')		--3
											+'|'+ ISNULL(@txt_itf_print_date,'')		--4
											+'|'+ ISNULL(@txt_itf_expire_date,'')		--5
											+'|'+ ISNULL(@txt_description,'')			--6
											+'|'+ ISNULL(@txt_item_number,'')			--7
											+'|'+ ISNULL(@txt_serial_number,'')			--8
											+'|'+ ISNULL(@txt_warranty_number,'')		--9
											+'|'+ ISNULL(@txt_warranty_expire,'')		--10										
											+'|'+ ISNULL(@txt_ref,'')					--11
											+'|'+ ISNULL(@txt_customer_code,'')			--12
											+'|'+ ISNULL(@txt_customer_name,'')			--13
											+'|'+ ISNULL(@txt_cus_addr_line_1,'')		--14
											+'|'+ ISNULL(@txt_cus_addr_line_2,'')		--15
											+'|'+ ISNULL(@txt_cus_addr_line_3,'')		--16
											+CHAR(13)+CHAR(10)
										  )
										  --PRINT @content
				--
				UPDATE #temp_table_print_content 
				SET content = @content
				WHERE id = @count_printer
				--
				IF @count_row <> @sum_rows
				BEGIN
					IF @count_row = @count_last
					BEGIN
						IF @count_printer = @printer_sum
						BEGIN
							SET @count_last = @count_last + (@sum_rows - @count_last)
						END
						ELSE
						BEGIN
							SET @count_last = @count_last + @how_many_rows
							SET @count_printer = @count_printer + 1
						END
					END
				END		
				--				 
				SET @count_row = @count_row + 1
 
			-- END FOR LIST INSTRUCTION SET            
			FETCH NEXT FROM CS_WARRANTY
				INTO @txt_warranty_id, @txt_itf_line_number, @txt_itf_warranty_number, @txt_itf_serial_number, @txt_itf_print_date, @txt_itf_expire_date
			, @txt_description, @txt_item_number, @txt_serial_number, @txt_warranty_number, @txt_warranty_expire, @txt_ref
			, @txt_customer_code, @txt_customer_name, @txt_cus_addr_line_1, @txt_cus_addr_line_2, @txt_cus_addr_line_3
			END
			CLOSE CS_WARRANTY    
			DEALLOCATE CS_WARRANTY

			-- SAVE CONTENT TO FILES	

			--PRINT OUTPUT
			SELECT id, sequence, group_printer_id, bartender_data_filepath, bartender_trigger_filepath, content  FROM #temp_table_print_content		
			--
			DECLARE CS_SAVE_CONNTENT CURSOR FOR
				SELECT id, sequence, group_printer_id, bartender_data_filepath, bartender_trigger_filepath, content  FROM #temp_table_print_content	
			OPEN CS_SAVE_CONNTENT          
			FETCH NEXT FROM CS_SAVE_CONNTENT
				INTO @id, @sequence, @group_printer_id, @bartender_data_filepath, @bartender_trigger_filepath, @content
			WHILE @@FETCH_STATUS = 0
			BEGIN    
			-- BEGIN FOR LIST INSTRUCTION SET
				IF @content <> ''
				BEGIN
					SELECT TOP(1) 		
						@dir_share_path = [dir_share_path]
						, @username = [username]
						, @passwd = [password]					
					FROM [dbo].[t_com_config_printer_server]
					WHERE [is_active] = 'YES'
					IF @dir_share_path IS NOT NULL
					BEGIN
						--SET @txt_server_login = 'NET USE L: \\10.10.60.185\wm_printing badadic /user:KRITSADA /PERSISTENT:YES'
						SET @txt_server_login = 'NET USE L: '+@dir_share_path+' '+@passwd+' /user:'+@username+' /PERSISTENT:YES'
						PRINT @txt_server_login
						EXEC master..xp_cmdshell @txt_server_login, NO_OUTPUT
					END						

					EXEC	[dbo].[usp_printing_save_text_tofile]
							@TheString = @content,
							@Filename = @bartender_data_filepath,
							@Unicode = 1
					EXEC	[dbo].[usp_printing_save_text_tofile]
							@TheString = 'DONE',
							@Filename = @bartender_trigger_filepath,
							@Unicode = 1					

				END
			-- END FOR LIST INSTRUCTION SET            
			FETCH NEXT FROM CS_SAVE_CONNTENT
				INTO @id, @sequence, @group_printer_id, @bartender_data_filepath, @bartender_trigger_filepath, @content
			END
			CLOSE CS_SAVE_CONNTENT    
			DEALLOCATE CS_SAVE_CONNTENT
			
		END 
    -- END FOR LIST INSTRUCTION SET            
    FETCH NEXT FROM CS_GROUP_PRINTER
        INTO @location_id, @printer_sum
    END
    CLOSE CS_GROUP_PRINTER    
    DEALLOCATE CS_GROUP_PRINTER			
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostCarrier]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_ProcessHostCarrier]
	@in_vchApplicationID			VARCHAR(40),			--Required
	@in_vchApplicationName			NVARCHAR(10),			--Required
	@in_vchHostRecordID				VARCHAR(40),			--Required
	@in_vchCarrierCode				NVARCHAR(40),			--Required
	@in_vchDevice					NVARCHAR(50),			--Required
	@in_vchUserID					NVARCHAR(10) = NULL,	--Required
	@in_vchLogType					NVARCHAR(50) = NULL,	--Required
	@in_vchProcess					NVARCHAR(50) = NULL,	--Required
	@out_vchErrorCode				INT OUTPUT
AS
BEGIN
		DECLARE
		-- Error handling variables
		@c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
		@v_intSqlErrorNumber    INTEGER,
		@v_intSqlErrorLine		INTEGER,
		@v_intSqlErrorState		INTEGER,
		@v_intSqlErrorSeverity	INTEGER,
		@v_vchSqlErrorMessage	NVARCHAR(2048),
		@v_vchSqlErrorProcedure NVARCHAR(200),  
		@v_vchProcessData1		NVARCHAR(100),
		@v_vchProcessData2		NVARCHAR(100),
		@v_vchProcessData3		NVARCHAR(100),
		@v_vchProcessData4		NVARCHAR(100),
		@v_nRowCount            INTEGER,
		@v_nErrorNumber			INTEGER,
		@v_vchMessage           NVARCHAR(500),
		@v_nReturn              INTEGER,
		@v_vchLogType			NVARCHAR(50),
		@v_vchWarehouse			NVARCHAR(25),
		@v_vchApplicationID		NVARCHAR(40),
		@v_intLocale			INTEGER, 
		@v_vchErrorNumber       NVARCHAR(25),
	    
		--  Log Handling Variables
		@v_intLogLevel          INTEGER = 3,			-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
		@v_vchLogAction			NVARCHAR(25) = 'PRINT', -- PRINT, LOG, 
	    
	    -- Local Variables
		@v_nCount               INTEGER,		
		@v_vchDevice			NVARCHAR(50),
		@v_vchStatus			NVARCHAR(200),
		@v_vchErrorCode			NVARCHAR(200),
		@v_vchWHID				NVARCHAR(25),
		
		-- Table Variables
		@v_vchTableName			NVARCHAR(50),
		@v_vchProcessingCode    NVARCHAR(40), -- Required
		@v_vchProcessingStatus  NVARCHAR(40), -- Required	
		@v_vchCarrierIDGUID		NVARCHAR(40),
		@v_vchCarrierCode       NVARCHAR(40), -- Required
		@v_vchName              NVARCHAR(200),
		@v_vchDescription       NVARCHAR(200),
		@v_vchAddrLine1			NVARCHAR(300),
		@v_vchAddrLine2			NVARCHAR(300),
		@v_vchAddrLine3			NVARCHAR(300),
		@v_vchCity		        NVARCHAR(50),
		@v_vchProvince			NVARCHAR(50),
		@v_vchPostalCode		NVARCHAR(50),
		@v_vchCountryCode		NVARCHAR(5),
		@v_vchCountryName		NVARCHAR(50),
		@v_vchPhone				NVARCHAR(50),
		@v_vchFax				NVARCHAR(50),
		@v_vchEmail				NVARCHAR(50),
		@v_vchContact			NVARCHAR(50),
		@v_vchCategory			NVARCHAR(50),
		@v_vchPriority			NVARCHAR(10),
		@v_vchIsActive		    NVARCHAR(3),
		@v_vchUserID			NVARCHAR(20)
		
		-- Set Constants and Variables
		SET @v_intLocale = 1033; -- English
		SET @v_vchApplicationID = 'IMPORT INTERFACE (TABLE)';
		SET @c_vchObjName = 'usp_ProcessHostCarrier'; 
		SET @v_vchTableName = 't_wms_carrier'; 
		SET @v_vchLogType = 'ERROR IMPORT';
		SET @v_vchDevice = 'usp_ProcessHostCarrier'
		
		
BEGIN TRY
	------------------------------------------------------------
	--  Get the Table Variables
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'
	
	SELECT 
		@v_vchProcessingCode    = processing_code
		,@v_vchProcessingStatus = processing_status
		,@v_vchCarrierCode      = carrier_code
		,@v_vchName             = name
		,@v_vchDescription		= description
		,@v_vchAddrLine1		= addr_line_1
		,@v_vchAddrLine2		= addr_line_2
		,@v_vchAddrLine3		= addr_line_3
		,@v_vchCity		        = city
		,@v_vchProvince			= province
		,@v_vchPostalCode		= postal_code
		,@v_vchCountryCode		= country_code
		,@v_vchCountryName		= country_name
		,@v_vchPhone			= phone
		,@v_vchFax				= fax
		,@v_vchEmail			= email
		,@v_vchContact			= contact
		,@v_vchCategory			= category
		,@v_vchPriority			= priority
		,@v_vchIsActive		    = ISNULL(@v_vchIsActive, 'YES')
		,@v_vchUserID			= create_by
	FROM t_host_wms_carrier
	WHERE host_record_id = @in_vchHostRecordID
	
	--------------------------------------
	--  Check for Missing Required Fields
	--  ProcessingCode, ProcessingStatus, CarrierCode, IsActive, UserID, Name
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'
		-- Future, Add a Log action for inserting into the Process Log		
		
	IF @v_vchProcessingCode IS NULL 
		OR @v_vchProcessingStatus IS NULL 
		OR @v_vchCarrierCode IS NULL
		OR @v_vchIsActive IS NULL 
		OR @v_vchUserID IS NULL 
		OR @v_vchName IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  SELECT 'Field List:' 
																  + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
																  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
																  + ' Carrier Code: ['+ISNULL(@v_vchCarrierCode, '') + ']' 
																  + ' Carrier Name: ['+ISNULL(@v_vchName, '') + ']' 
																  + ' Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
																  + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
																  
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @v_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
										+ ' Carrier Code: ['+ISNULL(@v_vchCarrierCode, '') + ']'
										+ ' Carrier Name: ['+ISNULL(@v_vchName, '') + ']'
			SELECT @v_vchProcessData3 =   'Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
										+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
			SELECT @v_vchProcessData4 = NULL
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END	
	
	
	------------------------------------------------------------
	--  Check Valid Processing Code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'	
	-- Future, Add a Log action for inserting into the Process Log
		
	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+']'
			-- Future, Add a Log action for inserting into the Process Log

			SET @v_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
										+ ' Carrier Code: ['+ISNULL(@v_vchCarrierCode, '') + ']'
										+ ' Carrier Name: ['+ISNULL(@v_vchName, '') + ']'
			SELECT @v_vchProcessData3 =   'Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
										+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
			SET @v_vchProcessData4 = NULL
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END
	
	
	------------------------------------------------------------
	-- Check Valid Processing Status
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'
	-- Future, Add a Log action for inserting into the Process Log

	IF (@v_vchProcessingStatus <> 'PENDING')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+']'
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @v_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
										+ ' Carrier Code: ['+ISNULL(@v_vchCarrierCode, '') + ']'
										+ ' Carrier Name: ['+ISNULL(@v_vchName, '') + ']'
			SELECT @v_vchProcessData3 =   'Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
										+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
			SET @v_vchProcessData4 = NULL
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END
	
	
	------------------------------------------------------------
	--  Processing for 'DELETE' the Carrier.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete'
			-- Future, Add a Log action for inserting into the Process Log
					
			DELETE FROM t_wms_carrier WHERE carrier_code = @v_vchCarrierCode
			
			---------------------------------------------------	
			-- Update Processing Status in host table = 'ERROR'
			---------------------------------------------------
			UPDATE t_host_wms_carrier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete Carrier Completed'	
			-- Future, Add a Log action for inserting into the Process Log
			
			GOTO EXIT_LABEL
		END	

	-----------------------------------------------------------
	--  Check Processing Code for ADD or UPDATE
	-----------------------------------------------------------
	SELECT @v_nCount = COUNT(carrier_code) FROM t_wms_carrier WHERE carrier_code = @v_vchCarrierCode
	
	IF (@v_nCount > 0 AND @v_vchProcessingCode = 'ADD')
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END
	
	------------------------------------------------------------
	--  Check the Carrier for a ADD duplicate.
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Carrier Code'	
	-- Future, Add a Log action for inserting into the Process Log	
		
	IF @v_vchProcessingCode = 'ADD' and @v_nCount > 0
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Carrier Code:['+@v_vchCarrierCode+']'
				-- Future, Add a Log action for inserting into the Process Log
			
				SET @v_vchErrorCode = 'ERROR-IFMAN-004' -- Duplicate Carrier Code
				SET @v_vchLogType = 'IMPORT WARNING'
				SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
											+ ' Carrier Code: ['+ISNULL(@v_vchCarrierCode, '') + ']'
											+ ' Carrier Name: ['+ISNULL(@v_vchName, '') + ']'
				SELECT @v_vchProcessData3 =   'Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
											+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
				SET @v_vchProcessData4 = NULL
				SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

				GOTO WRITE_PROCESS_LOG
		END

	------------------------------------------------------------
	--  Insert the Carrier data to WMS Table.
	------------------------------------------------------------
	IF @v_vchProcessingCode = 'ADD' and @v_nCount = 0
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD for Carrier:['+@v_vchCarrierCode+']'
			-- Future, Add a Log action for inserting into the Process Log
			INSERT INTO t_wms_carrier (
			      carrier_code 
				, carrier_name
				, description
				, addr_line_1
				, addr_line_2
				, addr_line_3
				, city
				, province
				, postal_code
				, country_code
				, country_name
				, phone
				, fax
				, email
				, contact 
				, category
				, priority
				, is_active
				, create_date
				, create_by)    
			VALUES (
			      @v_vchCarrierCode
				, @v_vchName
				, @v_vchDescription
				, @v_vchAddrLine1
				, @v_vchAddrLine2
				, @v_vchAddrLine3
				, @v_vchCity
				, @v_vchProvince
				, @v_vchPostalCode
				, @v_vchCountryCode
				, @v_vchCountryName
				, @v_vchPhone
				, @v_vchFax
				, @v_vchEmail
				, @v_vchContact
				, @v_vchCategory
				, @v_vchPriority
				, @v_vchIsActive
				, GETDATE()
				, @v_vchUserID)
			
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @v_vchErrorNumber = str(@v_intSqlErrorNumber)
					SET @v_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					
					GOTO WRITE_PROCESS_LOG
				END
				
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @v_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					
					GOTO WRITE_PROCESS_LOG
				END
				
				
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_carrier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID

	
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Carrier Completed'	
			GOTO EXIT_LABEL
		END
		
	------------------------------------------------------------
	--  Update the Carrier data to WMS Table.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'UPDATE' and @v_nCount > 0
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Update of Carrier:['+@v_vchCarrierCode+']'
			-- Future, Add a Log action for inserting into the Process Log
			
			SELECT @v_vchCarrierIDGUID = carrier_id FROM t_wms_carrier WHERE carrier_code = @v_vchCarrierCode
		
			UPDATE t_wms_carrier set 
				  carrier_name = @v_vchName
				, description = @v_vchDescription
				, addr_line_1 = @v_vchAddrLine1
				, addr_line_2 = @v_vchAddrLine2
				, addr_line_3 = @v_vchAddrLine3
				, city =  @v_vchCity
				, province =  @v_vchProvince
				, postal_code = @v_vchPostalCode
				, country_code = @v_vchCountryCode
				, country_name = @v_vchCountryName
				, phone = @v_vchPhone
				, fax = @v_vchFax
				, email= @v_vchEmail
				, contact = @v_vchContact
				, category = @v_vchCategory
				, priority = @v_vchPriority
				, is_active = @v_vchIsActive
			WHERE carrier_id = @v_vchCarrierIDGUID
			
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_carrier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Processing update Carrier Completed'
			GOTO EXIT_LABEL
		END


WRITE_PROCESS_LOG:
	
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
	
	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@v_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
		
	INSERT INTO [dbo].[t_com_process_log]
		([app_id]
		,[log_type]
		,[warehouse]
		,[device]
		,[process]
		,[process_datetime]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[message]
		,[create_date]
		,[create_by])
	VALUES
		( LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
		, LEFT(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25)
		, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
		, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
		, GETDATE()
		, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
		, LEFT(@v_vchProcessData2, 1000)
		, LEFT(@v_vchProcessData3, 1000)
		, LEFT(@v_vchProcessData4, 1000)
		, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
		, GETDATE()
		, ISNULL(LEFT(@v_vchUserID, 10), 'OGA'))

	SET @v_vchStatus = 'FAIL'
	
	---------------------------------------------------	
	-- Update Processing Status in host table = 'ERROR'
	---------------------------------------------------
	UPDATE t_host_wms_carrier SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID
	
	GOTO EXIT_LABEL
	
END TRY

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
	BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		SET @v_vchStatus = 'FAIL'
		
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id]
			   ,[log_type]
			   ,[warehouse]
			   ,[device]
			   ,[process]
			   ,[process_datetime]
			   ,[data_1]
			   ,[data_2]
			   ,[data_3]
			   ,[data_4]
			   ,[message]
			   ,[create_date]
			   ,[create_by])
		 VALUES
		 		(LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
		 		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, GETDATE()
				, ISNULL(@v_vchUserID,'OGA'))	
			
		---------------------------------------------------	
		-- Update Processing Status in host table = 'ERROR'
		---------------------------------------------------
		UPDATE t_host_wms_carrier SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID
			
	END CATCH

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
	-- Future, Add a Log action for inserting into the Process Log		
		
SET @out_vchErrorCode = 0
RETURN (@out_vchErrorCode)
END


GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostCustomer]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostCustomer]
	@in_vchApplicationID	VARCHAR(40),			--Required
	@in_vchApplicationName	NVARCHAR(10),			--Required
	@in_vchHostRecordID		VARCHAR(40),			--Required
	@in_vchDevice			NVARCHAR(50),			--Required
	@in_vchUserID			NVARCHAR(25) = NULL,	--Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS
BEGIN
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostCustomer'
	DECLARE @v_intSqlErrorNumber    INTEGER
	DECLARE @v_intSqlErrorLine		INTEGER
	DECLARE @v_intSqlErrorState		INTEGER
	DECLARE @v_intSqlErrorSeverity	INTEGER
	DECLARE @v_vchSqlErrorMessage	NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure NVARCHAR(200)  
	DECLARE @v_vchProcessData1		NVARCHAR(100)
	DECLARE @v_vchProcessData2		NVARCHAR(100)
	DECLARE @v_vchProcessData3		NVARCHAR(100)
	DECLARE @v_vchProcessData4		NVARCHAR(100)
	DECLARE @v_nErrorNumber			INTEGER
	DECLARE @v_nRowCount            INTEGER
	DECLARE @v_intLocale			INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round					INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel          INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction			NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,   
 	DECLARE @v_vchTableName			NVARCHAR(50)
	
	-- Local Variables
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCustomerID		UNIQUEIDENTIFIER = NULL	
	    
	-- Table Variables 
	DECLARE @v_vchProcessingCode    NVARCHAR(40) -- Required
	DECLARE @v_vchProcessingStatus  NVARCHAR(40) -- Required
	DECLARE @v_vchCustomerCode      NVARCHAR(40) -- Required
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerCode			NVARCHAR(40)
	DECLARE @v_vchCustomerName      NVARCHAR(300) 
	DECLARE @v_vchDescription		NVARCHAR(200) 
	DECLARE @v_vchAddrLine1			NVARCHAR(300) 
	DECLARE @v_vchAddrLine2			NVARCHAR(300) 
	DECLARE @v_vchAddrLine3			NVARCHAR(300) 
	DECLARE @v_vchCity		        NVARCHAR(100)
	DECLARE @v_vchProvince			NVARCHAR(100)
	DECLARE @v_vchPostalCode		NVARCHAR(50) 
	DECLARE @v_vchCountryCode		NVARCHAR(10)
	DECLARE @v_vchCountryName		NVARCHAR(100) 
	DECLARE @v_vchPhone				NVARCHAR(50) 
	DECLARE @v_vchFax				NVARCHAR(50) 
	DECLARE @v_vchEmailAddress		NVARCHAR(200) 
	DECLARE @v_vchContact			NVARCHAR(200) 
	DECLARE @v_vchCategory			NVARCHAR(50) 
	DECLARE @v_vchPriority			NVARCHAR(10) 
	DECLARE @v_vchIsActive		    NVARCHAR(3) 
	DECLARE @v_vchUserID			NVARCHAR(25) 
	DECLARE @v_vchUDF1				NVARCHAR(50)  
	DECLARE @v_vchUDF2				NVARCHAR(50)  
	DECLARE @v_vchUDF3				NVARCHAR(50)  
	DECLARE @v_vchUDF4				NVARCHAR(50)  
	DECLARE @v_vchUDF5				NVARCHAR(50)  
	DECLARE @v_vchUDF6				NVARCHAR(50)  
	DECLARE @v_fltUDF7				FLOAT
	DECLARE @v_fltUDF8				FLOAT
	DECLARE @v_dtUDF9				DATETIME
	DECLARE @v_dtUDF10				DATETIME

BEGIN TRY
	------------------------------------------------------------
	--  Get the Table Variables
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'
	SELECT @v_vchProcessingCode    = processing_code
		,@v_vchProcessingStatus = processing_status		
		,@v_vchCustomerCode     = customer_code
		,@v_vchCustomerName     = name
		,@v_vchWarehouse		= wh_id
		,@v_vchOwnerCode		= owner_id
		,@v_vchDescription		= description
		,@v_vchAddrLine1		= addr_line_1
		,@v_vchAddrLine2		= addr_line_2
		,@v_vchAddrLine3		= addr_line_3
		,@v_vchCity		        = city
		,@v_vchProvince			= province
		,@v_vchPostalCode		= postal_code
		,@v_vchCountryCode		= country_code
		,@v_vchCountryName		= country_name
		,@v_vchPhone			= phone
		,@v_vchFax				= fax
		,@v_vchEmailAddress		= email
		,@v_vchContact			= contact
		,@v_vchCategory			= category
		,@v_vchPriority			= priority
		,@v_vchIsActive		    = CASE WHEN ISNULL(is_active,'') = '' THEN 'YES' ELSE is_active END
		,@v_vchUserID			= create_by
		,@v_vchUDF1				= user_def1
		,@v_vchUDF2				= user_def2
		,@v_vchUDF3				= user_def3
		,@v_vchUDF4				= user_def4
		,@v_vchUDF5				= user_def5
		,@v_vchUDF6				= user_def6
		,@v_fltUDF7				= user_def7
		,@v_fltUDF8				= user_def8
		,@v_dtUDF9				= user_def9
		,@v_dtUDF10				= user_def10
	FROM t_host_wms_customer
	WHERE host_record_id = @in_vchHostRecordID
	AND processing_status	= 'PENDING'
	
	--------------------------------------
	--  Check for Required Fields
	--  log_type, warehouse, tran code, start tran date, location, quantity 
	-- 	app_id, device, user id, error_code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'
		-- Future, Add a Log action for inserting into the Process Log		
		
	IF ISNULL(@v_vchProcessingCode,'') = ''
		OR ISNULL(@v_vchProcessingStatus,'') = ''
		OR ISNULL(@v_vchOwnerCode,'') = ''
		OR ISNULL(@v_vchCustomerCode,'') = ''
		OR ISNULL(@v_vchCustomerName,'') = ''
	    OR ISNULL(@v_vchUserID,'') = '' 
		BEGIN
			------------------------------------------------------------
			--  Missing Required Fields 
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  SELECT 'Field List:' +'Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+ ']' 
																  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']' 
																  + ' Customer Code: ['+ISNULL(@v_vchCustomerCode, '') + ']'
																  + ' Customer Name: ['+ISNULL(@v_vchCustomerName, '') + ']'  
																  + ' Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
																  + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
																  
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			GOTO WRITE_PROCESS_LOG
		END	
	
	------------------------------------------------------------
	--  Check Valid Processing Code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'	
	-- Future, Add a Log action for inserting into the Process Log
		
	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+']'
			-- Future, Add a Log action for inserting into the Process Log

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code
			GOTO WRITE_PROCESS_LOG
		END
	
	------------------------------------------------------------
	-- Check Valid Processing Status
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'
	-- Future, Add a Log action for inserting into the Process Log

	IF (@v_vchProcessingStatus <> 'PENDING')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+']'
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status
			GOTO WRITE_PROCESS_LOG
		END
	
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
			GOTO WRITE_PROCESS_LOG
		END 
	
	
	-----------------------------------------------------------
	--  Get Customer ID
	-----------------------------------------------------------			
	SET @v_vchCustomerID = NULL;		
	SELECT @v_vchCustomerID = customer_id FROM t_wms_customer WHERE customer_code = @v_vchCustomerCode AND owner_id = @v_vchOwnerID
	IF @v_vchCustomerID IS NOT NULL
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END
 
	------------------------------------------------------------
	--  Processing for 'DELETE' the Customer.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN 
			IF @v_vchCustomerID IS NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Supplier is Invalid'  
					-- Future, Add a Log action for inserting into the Process Log    
		  
					SET @out_vchErrorCode = 'ERROR-IFMAN-060' -- Not found customer for delete 
					GOTO WRITE_PROCESS_LOG
				END

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete'
			-- Future, Add a Log action for inserting into the Process Log
			
			DELETE FROM t_wms_customer_user WHERE customer_id = @v_vchCustomerID
			DELETE FROM t_wms_customer WHERE customer_id = @v_vchCustomerID
			
			---------------------------------------------------	
			-- Update Processing Status in host table = 'ERROR'
			---------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status (COMPLETED) in host table'
			-- Future, Add a Log action for inserting into the Process Log
			
			UPDATE t_host_wms_customer SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete Customer Completed'	
			-- Future, Add a Log action for inserting into the Process Log
			
			GOTO COMMIT_TRANS;
		END	
 
	------------------------------------------------------------
	--  Check the Customer for a ADD duplicate.
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Customer Code'	
	-- Future, Add a Log action for inserting into the Process Log	
		
	IF @v_vchProcessingCode = 'ADD' AND @v_vchCustomerID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Customer Code:['+@v_vchCustomerCode+']'
				-- Future, Add a Log action for inserting into the Process Log
			
				SET @out_vchErrorCode = 'ERROR-IFMAN-005' -- Duplicate Customer Code
				GOTO WRITE_PROCESS_LOG
		END
		
	------------------------------------------------------------
	--  Insert the Customer data to WMS Table.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'ADD' AND @v_vchCustomerID IS NULL
		BEGIN
			print 'insert customer'
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD for Customer:['+@v_vchCustomerCode+']'
			-- Future, Add a Log action for inserting into the Process Log
			DECLARE @v_vchNewCustomerID	UNIQUEIDENTIFIER = NEWID()
			INSERT INTO t_wms_customer
			(  customer_id
				, owner_id
				, customer_code 
				, customer_name
				, [description]
				, addr_line_1
				, addr_line_2
				, addr_line_3
				, city
				, province
				, postal_code
				, country_code
				, country_name
				, phone
				, fax
				, email
				, contact 
				, category
				, [priority]
				, user_def1
				, user_def2
				, user_def3
				, user_def4
				, user_def5
				, user_def6
				, user_def7
				, user_def8
				, user_def9
				, user_def10
				, is_active
				, create_date
				, create_by
			)    
			VALUES 
			(  @v_vchNewCustomerID
				, @v_vchOwnerID
				, @v_vchCustomerCode
				, @v_vchCustomerName
				, @v_vchDescription 
				, @v_vchAddrLine1
				, @v_vchAddrLine2
				, @v_vchAddrLine3
				, @v_vchCity
				, @v_vchProvince
				, @v_vchPostalCode
				, @v_vchCountryCode
				, @v_vchCountryName
				, @v_vchPhone
				, @v_vchFax
				, @v_vchEmailAddress
				, @v_vchContact
				, @v_vchCategory
				, @v_vchPriority
				, @v_vchUDF1
				, @v_vchUDF2
				, @v_vchUDF3
				, @v_vchUDF4
				, @v_vchUDF5
				, @v_vchUDF6
				, @v_fltUDF7
				, @v_fltUDF8
				, @v_dtUDF9
				, @v_dtUDF10
				, @v_vchIsActive
				, GETDATE()
				, @v_vchUserID
				)

			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					--							+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
					--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					--SELECT @v_vchProcessData3 =  ' Customer Code: ['+ISNULL(@v_vchCustomerCode, '') + ']'
					--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
					--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
					--SELECT @out_vchErrorMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					--							+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
					--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					--SELECT @v_vchProcessData3 =  ' Customer Code: ['+ISNULL(@v_vchCustomerCode, '') + ']'
					--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
					--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
					--SELECT @out_vchErrorMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END

			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_INTERFACE_INSERT_CUSTOMER_USER' AND is_active = 'YES') = 'YES'
				BEGIN
					print 'insert customer user'
					INSERT INTO [dbo].[t_wms_customer_user]
						   ([user_customer_id]
						   ,[user_id]
						   ,[customer_id]
						   ,[is_active]
						   ,[create_date]
						   ,[create_by])
					 SELECT NEWID()
						   ,[user_id]
						   ,@v_vchNewCustomerID
						   ,'YES'
						   ,GETDATE()
						   ,@v_vchUserID
					FROM v_wms_user
				END
				
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_customer SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
	
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Customer Completed'	
			GOTO COMMIT_TRANS
		END

	------------------------------------------------------------
	--  Update the Customer data to WMS Table.
	------------------------------------------------------------
	IF @v_vchProcessingCode = 'UPDATE' AND  @v_vchCustomerID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Update of Customer:['+@v_vchCustomerCode+']'
		
			UPDATE t_wms_customer SET customer_name = @v_vchCustomerName
				, [description] = @v_vchDescription
				, owner_id = @v_vchOwnerID
				, addr_line_1 = @v_vchAddrLine1
				, addr_line_2 = @v_vchAddrLine2
				, addr_line_3 = @v_vchAddrLine3
				, city =  @v_vchCity
				, province =  @v_vchProvince
				, postal_code = @v_vchPostalCode
				, country_code = @v_vchCountryCode
				, country_name = @v_vchCountryName
				, phone = @v_vchPhone
				, fax = @v_vchFax
				, email= @v_vchEmailAddress
				, contact = @v_vchContact
				, category = @v_vchCategory
				, [priority] = @v_vchPriority
				, is_active = @v_vchIsActive
				, user_def1 = @v_vchUDF1
				, user_def2 = @v_vchUDF2
				, user_def3 = @v_vchUDF3
				, user_def4 = @v_vchUDF4
				, user_def5 = @v_vchUDF5
				, user_def6 = @v_vchUDF6
				, user_def7 = @v_fltUDF7
				, user_def8 = @v_fltUDF8
				, user_def9 = @v_dtUDF9
				, user_def10 = @v_dtUDF10
			WHERE customer_id = @v_vchCustomerID

			IF (SELECT TOP 1 value FROM t_wms_rule where rule_code = 'RULE_INTERFACE_INSERT_CUSTOMER_USER' AND is_active = 'YES') = 'YES'
				BEGIN
					DELETE t_wms_customer_user WHERE customer_id = @v_vchCustomerID

					INSERT INTO [dbo].[t_wms_customer_user]
						   ([user_customer_id]
						   ,[user_id]
						   ,[customer_id]
						   ,[is_active]
						   ,[create_date]
						   ,[create_by])
					 SELECT NEWID()
						   ,[user_id]
						   ,@v_vchCustomerID
						   ,'YES'
						   ,GETDATE()
						   ,@v_vchUserID
					FROM v_wms_user
				END
			
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_customer SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Processing UPDATE Customer Completed'
			GOTO COMMIT_TRANS
		END

	COMMIT_TRANS:
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;

	-----------------------------------------------------------------------------------
	-- WRITE PROCESS LOG
	-----------------------------------------------------------------------------------
	BEGIN
	WRITE_PROCESS_LOG:

		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
	
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
					+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
					+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
					+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
					+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
			SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
					+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
					+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
					+' Message: ['+ISNULL(@out_vchErrorMessage, '') + ']' 
					+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		END

		SET @v_vchLogType = 'IMPORT ERROR'
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')		
		SELECT @v_vchProcessData2 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']' 
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
		SELECT @v_vchProcessData3 =  'Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' Customer Code: ['+ISNULL(@v_vchCustomerCode, '') + ']'
									+ ' Customer Name: ['+ISNULL(@v_vchCustomerName, '') + ']' 
		SELECT @v_vchProcessData4 = ' Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'  
		SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		 
		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'CUSTOMER'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchCustomerCode,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())

		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		
		-- Future, Add a Log action for inserting into the Process Log  
		UPDATE t_host_wms_customer SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID

		GOTO EXIT_LABEL;
	END
END TRY

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
	BEGIN CATCH
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
	-- Future, Add a Log action for inserting into the Process Log
		
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER()
		, @v_vchSqlErrorMessage = ERROR_MESSAGE()
		, @v_intSqlErrorState = ERROR_STATE()
		, @v_intSqlErrorSeverity = ERROR_SEVERITY()
		, @v_intSqlErrorLine = ERROR_LINE()
		, @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
	SET @out_vchErrorMessage = 'SQL Error Message: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '') + ']'
	SELECT @v_vchProcessData3 = 'Customer Code: ['+ISNULL(@v_vchCustomerCode, '') + ']'
								+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
								+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
	SET  @v_vchProcessData4 = @v_vchSqlErrorMessage

	SET @out_vchErrorCode = @v_intSqlErrorNumber 
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage
		
	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@out_vchErrorMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END

		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'CUSTOMER'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchCustomerCode,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())
			
	--INSERT INTO [dbo].[t_com_process_log]
	--		([app_id]
	--		,[log_type]
	--		,[warehouse]
	--		,[device]
	--		,[process]
	--		,[process_datetime]
	--		,[data_1]
	--		,[data_2]
	--		,[data_3]
	--		,[data_4]
	--		,[message]
	--		,[create_date]
	--		,[create_by])
	--	VALUES
	--	 	(LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
	--	 	, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
	--		, LEFT(ISNULL(@v_vchWarehouse, 'NO WH DEFINED'), 25)
	--		, LEFT(ISNULL(@in_vchDevice, 'NO DEVICE'), 50)
	--		, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
	--		, GETDATE()
	--		, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
	--		, LEFT(@v_vchProcessData2, 1000)
	--		, LEFT(@v_vchProcessData3, 1000)
	--		, LEFT(@v_vchProcessData4, 1000)
	--		, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
	--		, GETDATE()
	--		, @v_vchUserID)
				
		---------------------------------------------------	
		-- Update Processing Status in host table = 'ERROR'
		---------------------------------------------------			
		UPDATE t_host_wms_customer SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID

	END CATCH

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END


GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostInboundOrder]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostInboundOrder]  
	@in_vchApplicationID	VARCHAR(40),		 --Required  
	@in_vchApplicationName	NVARCHAR(10),		 --Required  
	@in_vchHostRecordID		VARCHAR(40),		 --Required  
	@in_vchDevice			NVARCHAR(50),		 --Required
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS  
BEGIN
	DECLARE @v_vchApplicationID			NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName				NVARCHAR(50) = 'usp_ProcessHostInboundOrder'
	DECLARE @v_intSqlErrorNumber		INTEGER
	DECLARE @v_intSqlErrorLine			INTEGER
	DECLARE @v_intSqlErrorState			INTEGER
	DECLARE @v_intSqlErrorSeverity		INTEGER
	DECLARE @v_vchSqlErrorMessage		NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure		NVARCHAR(200)  
	DECLARE @v_vchProcessData1			NVARCHAR(100)
	DECLARE @v_vchProcessData2			NVARCHAR(100)
	DECLARE @v_vchProcessData3			NVARCHAR(100)
	DECLARE @v_vchProcessData4			NVARCHAR(100)
	DECLARE @v_nErrorNumber				INTEGER
	--DECLARE @v_vchMessage				  NVARCHAR(500)
	DECLARE @v_nRowCount				INTEGER
	DECLARE @v_intLocale				INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round						INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType				NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel				INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction				NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,  
 	DECLARE @v_vchTableName				NVARCHAR(50)
	DECLARE @v_vchErrorType				NVARCHAR(10) = NULL --MASTER, DETAIL
		
	-- Local Variables
	DECLARE @v_vchWhMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchSupplierID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCustomerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInboundMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInboundDetailID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCurrentOrderStatus	NVARCHAR(10) = NULL	 -- ใช้สำหรับเก็บ Status ของ Order ก่อน Interface
	DECLARE @v_vchCurrentOwnerCode		NVARCHAR(40) = NULL	 -- ใช้สำหรับเก็บค่า Owner ก่อนการ Update ซึ่งถ้าส่งค่าใหม่มาจะไม่สามารถ Update ได้เนื่องจากกระทบข้อมูลใน Detail
   
	-- Table Variables (t_host_wms_inbound_order)  
	DECLARE @v_vchRecordType			NVARCHAR(10) = NULL -- Required  
	DECLARE @v_vchProcessingCode		NVARCHAR(40) = NULL -- Required  
	DECLARE @v_vchProcessingStatus		NVARCHAR(40) = NULL -- Required  
	DECLARE @v_vchWarehouse				NVARCHAR(25) = NULL -- Required
	DECLARE @v_vchOwnerCode				NVARCHAR(40) = NULL -- Required  
	DECLARE @v_vchOrderNumber			NVARCHAR(40) = NULL -- Required  
	DECLARE @v_vchOrderType				NVARCHAR(30) = NULL -- Required  
	DECLARE @v_vchSupplierCode			NVARCHAR(40) = NULL -- Required
	DECLARE @v_vchCustomerCode			NVARCHAR(40) = NULL -- Required  
	DECLARE @v_dtOrderDate				DATETIME	 = NULL -- Required  
	DECLARE @v_vchOrderStatus			NVARCHAR(10) = NULL -- Required ใช้สำหรับ Status ที่ส่งมาตอน Interface
	DECLARE @v_dtExpectDeliveryDate		DATETIME
	DECLARE @v_vchUDF1					NVARCHAR(50)  
	DECLARE @v_vchUDF2					NVARCHAR(50)  
	DECLARE @v_vchUDF3					NVARCHAR(50)  
	DECLARE @v_vchUDF4					NVARCHAR(50)  
	DECLARE @v_vchUDF5					NVARCHAR(50)  
	DECLARE @v_vchUDF6					NVARCHAR(50)  
	DECLARE @v_fltUDF7					FLOAT  
	DECLARE @v_fltUDF8					FLOAT  
	DECLARE @v_dtUDF9					DATETIME		
	DECLARE @v_dtUDF10					DATETIME		
	DECLARE @v_vchUserID				NVARCHAR(25)
	DECLARE @v_vchHostSource			NVARCHAR(20)

	-- Table Variables (t_wms_inbound_detail)
	DECLARE @v_vchHostIBDetailIDGUID	UNIQUEIDENTIFIER -- Required 
	DECLARE @v_vchDTWarehouse			NVARCHAR(25)	-- Required
	DECLARE @v_vchDTOwnerCode			NVARCHAR(40)	-- Required  
	DECLARE @v_vchDTOrderNumber			NVARCHAR(50)	-- Required
	DECLARE @v_vchDTLineNumber			NVARCHAR(10)	-- Required
	DECLARE @v_vchDTItemNumber			NVARCHAR(50)	-- Required
	DECLARE @v_fltDTQuantity			FLOAT			-- Required
	DECLARE @v_vchDTUom					NVARCHAR(20)	-- Required
	DECLARE @v_vchDTLPN					NVARCHAR(25) 
	DECLARE @v_vchDTDefaultItemStatus	NVARCHAR(40)
	DECLARE @v_fltDTPrice				FLOAT 
	DECLARE @v_vchDTOverReceiptAllowed	VARCHAR(3)  
	DECLARE @v_fltDTOverReceiptPercent	FLOAT
	DECLARE @v_vchDTLotNumber			NVARCHAR(50)
	DECLARE @v_vchDTMfgDate				DATE
	DECLARE @v_vchDTExpirydate			NVARCHAR(8)
	DECLARE @v_vchDTSerialNumber		NVARCHAR(50)
	DECLARE @v_vchDTAttribute1			NVARCHAR(100)
	DECLARE @v_vchDTAttribute2			NVARCHAR(100)
	DECLARE @v_vchDTAttribute3			NVARCHAR(100)
	DECLARE @v_vchDTAttribute4			NVARCHAR(100)
	DECLARE @v_vchDTAttribute5			NVARCHAR(100)
	DECLARE @v_vchDTUDF1				NVARCHAR(50)  
	DECLARE @v_vchDTUDF2				NVARCHAR(50)
	DECLARE @v_vchDTUDF3				NVARCHAR(50)  
	DECLARE @v_vchDTUDF4				NVARCHAR(50)  
	DECLARE @v_vchDTUDF5				NVARCHAR(50)  
	DECLARE @v_vchDTUDF6				NVARCHAR(50)  
	DECLARE @v_fltDTUDF7				FLOAT
	DECLARE @v_fltDTUDF8				FLOAT
	DECLARE @v_dtDTUDF9					DATETIME	
	DECLARE @v_dtDTUDF10				DATETIME
	DECLARE @v_vchDTUserID				NVARCHAR(25)	
	 
	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

BEGIN TRY  
	BEGIN TRANSACTION;
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------
	SET @v_vchTableName = 't_host_wms_inbound_order';  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	SELECT TOP 1 @v_vchRecordType = record_type
	   ,@v_vchProcessingCode	= processing_code  
	   ,@v_vchProcessingStatus  = processing_status    
	   ,@v_vchWarehouse			= wh_id	   
	   ,@v_vchOwnerCode			= owner_id  
	   ,@v_vchOrderNumber		= order_number  
	   ,@v_vchOrderType			= [type]  
	   ,@v_vchSupplierCode		= supplier_code  
	   ,@v_vchCustomerCode		= customer_code 
	   ,@v_dtOrderDate			= order_create_date  
	   ,@v_vchOrderStatus		= order_status  
	   ,@v_dtExpectDeliveryDate = CASE CONVERT(NVARCHAR,expected_delivery_date  ,112) WHEN '19000101'  THEN NULL ELSE expected_delivery_date END  
	   ,@v_vchUDF1				= user_def1  
	   ,@v_vchUDF2				= user_def2  
	   ,@v_vchUDF3     			= user_def3  
	   ,@v_vchUDF4     			= user_def4  
	   ,@v_vchUDF5     			= user_def5  
	   ,@v_vchUDF6     			= user_def6  
	   ,@v_fltUDF7     			= user_def7  
	   ,@v_fltUDF8     			= user_def8  
	   ,@v_dtUDF9	   			= CASE CONVERT(NVARCHAR,user_def9,112)  WHEN '19000101' THEN NULL ELSE user_def9 END  
	   ,@v_dtUDF10	   			= CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
	   ,@v_vchHostSource		= host_source
	   ,@v_vchUserID   			= create_by
	FROM t_host_wms_inbound_order  
	WHERE host_record_id = @in_vchHostRecordID
	ORDER BY create_date DESC
   
	------------------------------------------------------------  
	--  If the WH ID was NOT put into the Interface Table   
	--  then try to get it from the Rule Table  
	------------------------------------------------------------  
	IF ISNULL(@v_vchWarehouse,'') = ''
		BEGIN
			SELECT @v_vchWarehouse = [dbo].[usf_GetRuleValue] ('DEFAULT_WH_ID',NULL,'WH_CONTROL')
		END
  
	----------------------------------------------------------------
	--  Check Nulls for Required Fields  
	--  Record Type, Processing Code, Processing Status
	--  Order Number, OwnerID, Order Type,
	--  Order Date, Order Status, User ID
	----------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    
	IF (ISNULL(@v_vchRecordType,'') = ''
		OR ISNULL(@v_vchProcessingCode,'') = ''   
		OR ISNULL(@v_vchProcessingStatus,'') = ''
		OR ISNULL(@v_vchOrderNumber,'') = ''  
		OR ISNULL(@v_vchWarehouse,'') = ''  
		OR ISNULL(@v_vchOwnerCode,'') = ''  
		OR ISNULL(@v_vchOrderType,'') = ''
		OR ISNULL(@v_vchOrderStatus,'') = ''
		OR @v_dtOrderDate IS NULL
		OR ISNULL(@v_vchUserID,'') = '')
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
		SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
							 + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']' 
							 + ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
							 + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
							 + ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
							 + ' Order Status: ['+ISNULL(@v_vchOrderStatus, '') + ']' 
							 + ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderDate, '')) + ']'
							 + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		
		SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
		SET @v_vchErrorType = 'MASTER' 
 		GOTO WRITE_PROCESS_LOG  
	END
	  
	------------------------------------------------------------------------  
	--  Check Valid Warehouse 
	------------------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Warehouse ID GUID'  
	-- Future, Add a Log action for inserting into the Process Log    
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id, @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_id = @v_vchWarehouse AND is_active = 'YES'
	IF @v_vchWhMasterID IS NULL
	BEGIN
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Warehouse ID is invalid.'  
		-- Future, Add a Log action for inserting into the Process Log    
		  
		SET @out_vchErrorCode = 'ERROR-IFMAN-013' -- Invalid Warehouse in Import Data
		SET @v_vchErrorType = 'MASTER' 
		GOTO WRITE_PROCESS_LOG  
	END
   
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner
		SET @v_vchErrorType = 'MASTER' 
		GOTO WRITE_PROCESS_LOG 
	END  
    
	------------------------------------------------------------------------  
	--  Check to make sure that Supplier ID in the Import Data   
	--  is a valid Supplier ID that is in the t_wms_supplier table  
	--  Supplier อาจมีหรือไม่มีก็ได้ กรณีที่เป็น "การสั่งซื้อสินค้า" จะมี Supplier Code 
	------------------------------------------------------------------------  
	IF (ISNULL(@v_vchSupplierCode,'') <> '')  
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Supplier ID'  
		-- Future, Add a Log action for inserting into the Process Log    
		
		SELECT @v_vchSupplierID = supplier_id FROM t_wms_supplier WHERE supplier_code = @v_vchSupplierCode AND owner_id = @v_vchOwnerID AND is_active = 'YES'
		IF @v_vchSupplierID IS NULL
		BEGIN
			
			------------------------------------------------------------------------  
			--  Insert Supplier กรณีที่ไม่พบข้อมูล Supplier ใน WMS  
			------------------------------------------------------------------------  
			SET @v_vchSupplierID = NEWID()   
			INSERT INTO t_wms_supplier  
			(  
				 supplier_id  
				,supplier_code  
				,owner_id
				,supplier_name  
				,create_by
				,create_date
			)  
			VALUES  
			(   
				 @v_vchSupplierID
				,@v_vchSupplierCode  
				,@v_vchOwnerID
				,@v_vchSupplierCode
				,@v_vchUserID
				,GETDATE()
			)  
			
			
			--IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inbound Order is Invalid'  
			---- Future, Add a Log action for inserting into the Process Log    
			  
			--SET @out_vchErrorCode = 'ERROR-IFMAN-037' -- INVALID ORDER MASTER - SUPPLIER CODE DOES NOT EXIST
			--SET @v_vchErrorType = 'MASTER' 
			--GOTO WRITE_PROCESS_LOG 
		END   
	END 
  
	------------------------------------------------------------------------  
	--  Check to make sure that Customer ID in the Import Data   
	--  is a valid Customer ID that is in the t_wms_customer table  
	--  Customer อาจมีหรือไม่มีก็ได้ กรณีที่เป็น "การส่งคืนสินค้า" จะมี Customer Code  
	------------------------------------------------------------------------  
	IF (ISNULL(@v_vchCustomerCode,'') <> '')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Customer ID'  
		-- Future, Add a Log action for inserting into the Process Log    

		SELECT TOP 1 @v_vchCustomerID = customer_id, @v_vchCustomerCode = customer_code FROM t_wms_customer WHERE customer_code = @v_vchCustomerCode AND owner_id = @v_vchOwnerID AND is_active = 'YES'
		IF @v_vchCustomerID IS NULL
		BEGIN
			/*
			------------------------------------------------------------------------  
			--  Insert Customer เลย กรณีที่ไม่พบข้อมูล Customer ใน WMS  
			------------------------------------------------------------------------  
			SET @v_vchCustomerID = NEWID()
			INSERT INTO t_wms_customer  
			(  
				 customer_id  
				,customer_code 
				,owner_id 
				,customer_name  
				,create_by  
				,create_date
			)  
			VALUES  
			(   
				 @v_vchCustomerID
				,@v_vchCustomerCode  
				,@v_vchOwnerID
				,@v_vchCustomerCode  
				,@v_vchUserID
				,GETDATE()
			)  
			*/

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inbound Order is Invalid'  
			-- Future, Add a Log action for inserting into the Process Log    
			  
			SET @out_vchErrorCode = 'ERROR-IFMAN-036' -- INVALID ORDER MASTER - CUSTOMER CODE DOES NOT EXIST
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END    
	END
	
	----------------------------------------------------------  
	--  Check for Inbound Order Master and Get the Master ID  
	--  From the Master Inbound Order  
	---------------------------------------------------------- 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Inbound Order Master'  
	-- Future, Add a Log action for inserting into the Process Log 
	SET @v_vchInboundMasterID = NULL
	SELECT TOP 1 @v_vchInboundMasterID = inbound_order_master_id
		,@v_vchCurrentOrderStatus = order_status
		,@v_vchCurrentOwnerCode = owner_code
	FROM t_wms_inbound_master
 	WHERE inbound_order_number = @v_vchOrderNumber 
	AND wh_master_id = @v_vchWhMasterID
	IF @v_vchInboundMasterID IS NOT NULL
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'  
		END
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END

	-------------------------------------------------------------------------  
	--  Invalid Order Detail in Import Data - No Master Record  
	-------------------------------------------------------------------------  
	IF @v_vchInboundMasterID IS NULL AND @v_vchProcessingCode IN ('DELETE','UPDATE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inbound Order is Invalid'  
			-- Future, Add a Log action for inserting into the Process Log    
		  
			SET @out_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END
 
	--------------------------------------------------------------------------  
	--  Check Valid Record Types  
	--------------------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Record Types'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF (@v_vchRecordType <> 'MASTER')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END  
   
	--------------------------------------------------------------------------  
	--  Check Valid Processing Code  
	--------------------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
		BEGIN
			if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END  
    
	------------------------------------------------------------  
	--  Check Valid Processing Status  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingStatus <> 'PENDING')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  
		  
			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG
		END     
     
	------------------------------------------------------------  
	--  Check Valid Order Type  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Checking for Valid Order Type'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF @v_vchOrderType NOT IN (SELECT value_member FROM dbo.t_com_combobox_item WHERE group_name = 'inbound_order_type' AND is_active = 'YES')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Order Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-014' -- Invalid Order Type
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END
     
	------------------------------------------------------------  
	--  Processing for 'DELETE' the Inbound Order.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingCode = 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Delete Processing for Order:['+@v_vchOrderNumber+']'  
			
			-- Future, Add a Log action for inserting into the Process Log  
			IF (@v_vchCurrentOrderStatus = 'OPEN')
				BEGIN
					DELETE t_wms_receipt_header WHERE inbound_order_master_id = @v_vchInboundMasterID
					DELETE t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID
					DELETE t_wms_inbound_master WHERE inbound_order_master_id = @v_vchInboundMasterID
					--------------------------------------------------------------  
					---- Update Order Status = Cancel กรณีที่ส่งมาเป็น Delete  
					--------------------------------------------------------------
					--UPDATE t_wms_inbound_master SET 
					--	 order_status = 'CANCEL'
					--	,update_by = @v_vchUserID
					--	,update_date = GETDATE()
					--WHERE inbound_order_master_id = @v_vchInboundMasterID				

					------------------------------------------------------------  
					-- Update Process Status = COMPLETED  
					------------------------------------------------------------  
					UPDATE t_host_wms_inbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
					UPDATE t_host_wms_inbound_order_detail SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
					UPDATE t_host_wms_inbound_order_comment SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
					
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Delete Inbound order Complete'  

					GOTO COMMIT_TRANS;
				END
			ELSE  
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Order Status not Available for Change.'   
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-003' -- ORDER STATUS NOT OPEN 
					SET @v_vchErrorType = 'MASTER' 
					GOTO WRITE_PROCESS_LOG 
				END   
		END 

	IF (@v_vchCurrentOrderStatus = 'OPEN' AND @v_vchOrderStatus IN ('CANCELLED','CANCEL','CLOSE'))
		BEGIN
			------------------------------------------------------------  
			-- Update Order Status = Cancel กรณีที่ส่งมาเป็น Delete  
			------------------------------------------------------------
			IF @v_vchOrderStatus = 'CANCELLED'
				SET @v_vchOrderStatus = 'CANCEL'

			UPDATE t_wms_inbound_master SET 
					order_status = @v_vchOrderStatus
				,update_by = @v_vchUserID
				,update_date = GETDATE()
			WHERE inbound_order_master_id = @v_vchInboundMasterID				

			------------------------------------------------------------  
			-- Update Process Status = COMPLETED  
			------------------------------------------------------------  
			UPDATE t_host_wms_inbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			UPDATE t_host_wms_inbound_order_detail SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			UPDATE t_host_wms_inbound_order_comment SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
					
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Delete Inbound order Complete'  

			GOTO COMMIT_TRANS;
		END

	------------------------------------------------------------  
	--  Check the Inbound Order for a ADD duplicate.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicates'   
	-- Future, Add a Log action for inserting into the Process Log   

	IF (@v_vchProcessingCode = 'ADD' AND @v_vchInboundMasterID IS NOT NULL)	-- Check Duplicate Order 
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Found.  Order Number:'+@v_vchOrderNumber+']'  
			SET @out_vchErrorCode = 'ERROR-IFMAN-002' -- Duplicate Order Number 
			SET @v_vchErrorType = 'MASTER' 
			GOTO WRITE_PROCESS_LOG 
		END  
	
	ELSE IF (@v_vchProcessingCode = 'ADD' AND @v_vchInboundMasterID IS NULL)	-- Add Order Master 
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'ADD' the Order .  
			--  This section should be runing for an 'ADD' with no   
			--  duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Processing Add Inbound Order Master'  
			-- Future, Add a Log action for inserting into the Process Log  
			  
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
			BEGIN
				SELECT 'Field List:' +'Order Number: ['+ISNULL(@v_vchOrderNumber, '')+ ']'   
					+' Owner: ['+ISNULL(@v_vchOwnerCode, '')  + ']' 
					+' Warehouse: ['+ISNULL(@v_vchWarehouse, '')  + ']'  
					+' Order Type: ['+ISNULL(@v_vchOrderType, '')  + ']' 
					+' Order Status: ['+ISNULL(@v_vchOrderStatus, '')  + ']' 
					+' Supplier Code: ['+ISNULL(@v_vchSupplierCode, '')  + ']' 
				SELECT ' UDF1: ['+ISNULL(@v_vchUDF1, '')  + ']' 
					+' UDF2: ['+ISNULL(@v_vchUDF2, '')  + ']' 
					+' UDF3: ['+ISNULL(@v_vchUDF3, '')  + ']' 
					+' UDF4: ['+ISNULL(@v_vchUDF4, '')  + ']' 
					+' UDF5: ['+ISNULL(@v_vchUDF5, '')  + ']' 
					+' UDF6: ['+ISNULL(@v_vchUDF6, '')  + ']' 
					+' UDF7: ['+ISNULL(str(@v_fltUDF7, 12), '')  + ']' 
					+' UDF8: ['+ISNULL(str(@v_fltUDF8, 12), '')  + ']' 
					+' UDF9: ['+ISNULL(@v_dtUDF9, '')  + ']' 
					+' UDF10: ['+ISNULL(@v_dtUDF10, '')  + ']' 
					+' Order Create Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderDate, ''))+ ']'   
					+' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
			END  
			 
			INSERT INTO [dbo].[t_wms_inbound_master]
				([inbound_order_master_id]
				,[wh_master_id]
				,[wh_id]
				,[owner_id]
				,[owner_code]
				,[supplier_id]
				,[customer_id]
				,[inbound_order_number]
				,[order_type]
				,[order_status] 
				,[expected_delivery_date]
				,[posting_date]
				,[user_def1]
				,[user_def2]
				,[user_def3]
				,[user_def4]
				,[user_def5]
				,[user_def6]
				,[user_def7]
				,[user_def8]
				,[user_def9]
				,[user_def10]
				,[create_by]
				,[create_date])
			VALUES 
				(NEWID()					--inbound_order_master_id, uniqueidentifier,>
				,@v_vchWhMasterID			--wh_master_id, uniqueidentifier,>
				,@v_vchWarehouse			--wh_id, nvarchar(25),>
				,@v_vchOwnerID				--owner_id, uniqueidentifier,>
				,@v_vchOwnerCode			--owner_code, nvarchar(40),>
				,@v_vchSupplierID			--supplier_id, uniqueidentifier,>
				,@v_vchCustomerID			--customer_id, uniqueidentifier,>
				,@v_vchOrderNumber			--inbound_order_number, nvarchar(50),>
				,@v_vchOrderType			--order_type, nvarchar(30),>
				,@v_vchOrderStatus			--order_status, nvarchar(10),>
				,@v_dtExpectDeliveryDate	--expected_delivery_date, datetime,>
				,GETDATE()					--posting_date, datetime,>
				,@v_vchUDF1					--: เนื่องจาก column นี้จะ Host จะ Map Customer Name มา ดังนั้นตอน Insert Inbound ไม่ต้องเอาค่าลงไป  
				,@v_vchUDF2					--: เนื่องจาก column นี้จะ Host จะ Map Supplier Name มา ดังนั้นตอน Insert Inbound ไม่ต้องเอาค่าลงไป  
				,@v_vchUDF3					--user_def3, nvarchar(50),>
				,@v_vchUDF4					--user_def4, nvarchar(50),>
				,@v_vchUDF5					--user_def5, nvarchar(50),>
				,@v_vchUDF6					--user_def6, nvarchar(50),>
				,@v_fltUDF7					--user_def7, float,>
				,@v_fltUDF8					--user_def8, float,>
				,@v_dtUDF9					--user_def9, datetime,>
				,@v_dtUDF10					--user_def10, datetime,>
				,@v_vchUserID				--create_by, nvarchar(25),>
				,@v_dtOrderDate)			--create_date, datetime,>  

			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					--							+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
					--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					--SELECT @v_vchProcessData3 = 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
					--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
					--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
					--SELECT @out_vchErrorMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SET @v_vchErrorType = 'MASTER' 
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					--							+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
					--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					--SELECT @v_vchProcessData3 = 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
					--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
					--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
					--SELECT @out_vchErrorMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SET @v_vchErrorType = 'MASTER' 
					GOTO WRITE_PROCESS_LOG
				END
      
			------------------------------------------------------------  
			-- Update Process Status = COMPLETED  
			------------------------------------------------------------  
			UPDATE t_host_wms_inbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Inbound Order Master Completed'   
			-- Future, Add a Log action for inserting into the Process Log  
		END  
	
	ELSE IF (@v_vchProcessingCode = 'UPDATE' AND @v_vchInboundMasterID IS NOT NULL)	-- Update Order Master  
		BEGIN
			------------------------------------------------------------  
			--  Check Order Status - No Change if Order Status not OPEN  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Order Status for Update:['+@v_vchOrderStatus+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOrderStatus <> 'OPEN')
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Order Status not Available for Change.'   
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-003' -- ORDER STATUS NOT OPEN  
					SET @v_vchErrorType = 'MASTER' 
					GOTO WRITE_PROCESS_LOG
				END 
  
			------------------------------------------------------------  
			--  Check Owner ต้องเป็นค่าเดิมที่ Interface มาครั้งแรก  
			------------------------------------------------------------ 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Owner for Update:[' + @v_vchOwnerCode + ']' 
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOwnerCode <> @v_vchOwnerCode)
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Owner not available for Change.'
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-032' -- Owner not available for Change 
					SET @v_vchErrorType = 'MASTER' 
					GOTO WRITE_PROCESS_LOG
				END
			
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List:' +'Order Number: ['+ISNULL(@v_vchOrderNumber, '')  + ']'
						+' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
						+' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'  
						+' Order Type: ['+ISNULL(@v_vchOrderType, '')  + ']'
						+' Order Status: ['+ISNULL(@v_vchCurrentOrderStatus, '')  + ']'
						+' Supplier Code: ['+ISNULL(@v_vchSupplierCode, '')  + ']'
						+' Cusotmer Code: ['+ISNULL(@v_vchCustomerCode, '')  + ']'
					SELECT ' UDF1: ['+ISNULL(@v_vchUDF1, '')  + ']'
						+' UDF2: ['+ISNULL(@v_vchUDF2, '')  + ']'
						+' UDF3: ['+ISNULL(@v_vchUDF3, '')  + ']'
						+' UDF4: ['+ISNULL(@v_vchUDF4, '')  + ']'
						+' UDF5: ['+ISNULL(@v_vchUDF5, '')  + ']'
						+' UDF6: ['+ISNULL(@v_vchUDF6, '')  + ']'
						+' UDF7: ['+ISNULL(str(@v_fltUDF7, 12), '')  + ']'
						+' UDF8: ['+ISNULL(str(@v_fltUDF8, 12), '')  + ']'
						+' UDF9: ['+ISNULL(@v_dtUDF9, '')  + ']'
						+' UDF10: ['+ISNULL(@v_dtUDF10, '')  + ']'
						+' Order Create Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderDate, '')) + ']' 
						+' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
				END

			------------------------------------------------------------  
			-- Update ข้อมูล Inbound Order  
			------------------------------------------------------------ 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Update Inbound Order Master:[' + @v_vchOrderNumber + ']' 
			-- Future, Add a Log action for inserting into the Process Log
				BEGIN
					---------------------------------------------------
					--Delete Inbound Detail Before Update
					--------------------------------------------------- 
					DELETE t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID 
					
					---------------------------------------------------
					--Update Inbound Master
					--------------------------------------------------- 
					UPDATE [t_wms_inbound_master] SET
						 [order_type] = @v_vchOrderType
						,[order_status] = @v_vchOrderStatus  
						,[supplier_id] = @v_vchSupplierID 
						,[customer_id] = @v_vchCustomerID
						,[expected_delivery_date] = @v_dtExpectDeliveryDate  
						,[user_def1] = @v_vchUDF1  
						,[user_def2] = @v_vchUDF2  
						,[user_def3] = @v_vchUDF3  
						,[user_def4] = @v_vchUDF4  
						,[user_def5] = @v_vchUDF5  
						,[user_def6] = @v_vchUDF6  
						,[user_def7] = @v_fltUDF7  
						,[user_def8] = @v_fltUDF8  
						,[user_def9] = @v_dtUDF9
						,[user_def10] = @v_dtUDF10
						,[update_by] = @v_vchUserID
						,[update_date] = GETDATE()
					WHERE [inbound_order_master_id] = @v_vchInboundMasterID
					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_inbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Inbound Order Master Complete'  
				END
		END
  
	----------------------------------------------------------------------------  
	--***************************INBOUND ORDER DETAIL***************************  
	----------------------------------------------------------------------------
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseItemUomID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchBaseUOM			NVARCHAR(10) = NULL
	DECLARE @v_vchDTItemUomID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_fltDTConversionFactor FLOAT = NULL
	DECLARE @v_vchPrimaryUOM		VARCHAR(3) = NULL
	DECLARE @v_fltQuantityReceive	FLOAT		--สำหรับตรวจสอบกรณี Delete จะต้อง QTY Receive = 0 ถึงจะลบข้อมูลได้
	DECLARE @v_vchDTGrade			NVARCHAR(40) = NULL

	IF EXISTS (SELECT host_record_id FROM dbo.t_host_wms_inbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')
	BEGIN
		INBOUND_DETAIL_LABEL:
		
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Inbound Order Detail Started' 
        -- Future, Add a Log action for inserting into the Process Log 
		
		SET @v_vchTableName = 't_host_wms_inbound_order_detail'
		SET @v_vchErrorType = 'DETAIL' 
		BEGIN -- Clear Value before set the value to variable
			SET @v_vchHostIBDetailIDGUID	= NULL
			SET @v_vchDTWarehouse			= NULL
			SET @v_vchDTOwnerCode			= NULL
			SET @v_vchDTOrderNumber			= NULL
			SET @v_vchDTLineNumber			= NULL
			SET @v_vchDTItemNumber			= NULL
			SET @v_fltDTQuantity			= NULL
			SET @v_vchDTUom					= NULL
			SET @v_vchDTLPN					= NULL
			SET @v_vchDTDefaultItemStatus	= NULL
			SET @v_fltDTPrice				= NULL
			SET @v_vchDTOverReceiptAllowed	= NULL
			SET @v_fltDTOverReceiptPercent	= NULL
			SET @v_vchDTLotNumber			= NULL
			SET @v_vchDTExpirydate			= NULL
			SET @v_vchDTSerialNumber		= NULL
			SET @v_vchDTAttribute1			= NULL
			SET @v_vchDTAttribute2			= NULL
			SET @v_vchDTAttribute3			= NULL
			SET @v_vchDTAttribute4			= NULL
			SET @v_vchDTAttribute5			= NULL
			SET @v_vchDTUDF1				= NULL
			SET @v_vchDTUDF2				= NULL
			SET @v_vchDTUDF3				= NULL
			SET @v_vchDTUDF4				= NULL
			SET @v_vchDTUDF5				= NULL
			SET @v_vchDTUDF6				= NULL
			SET @v_fltDTUDF7				= NULL
			SET @v_fltDTUDF8				= NULL
			SET @v_dtDTUDF9					= NULL
			SET @v_dtDTUDF10				= NULL
			SET @v_vchDTUserID				= NULL 
			SET @v_vchWhMasterID			= NULL
			SET @v_vchOwnerID				= NULL
			SET @v_vchSupplierID			= NULL
			SET @v_vchCustomerID			= NULL
			SET @v_vchInboundMasterID		= NULL
			SET @v_vchInboundDetailID		= NULL
			SET @v_vchWhItemMasterID		= NULL
			SET @v_vchItemMasterID			= NULL
			SET @v_vchBaseItemUomID			= NULL
			SET @v_vchBaseUOM				= NULL
			SET @v_vchDTItemUomID			= NULL
			SET @v_fltDTConversionFactor	= NULL
			SET @v_vchPrimaryUOM			= NULL
			SET @v_fltQuantityReceive		= NULL
			SET @v_vchDTGrade				= NULL
		END

        -----------------------------------------------------------------------------
		-- Select the data from [t_host_wms_inbound_order_detail] and assign to variable 
		-----------------------------------------------------------------------------
		SELECT TOP 1 @v_vchHostIBDetailIDGUID = inbound_order_detail_id
			,@v_vchRecordType		= record_type    
			,@v_vchProcessingCode	= processing_code  
			,@v_vchProcessingStatus = processing_status  
			,@v_vchDTWarehouse		= wh_id
			,@v_vchDTOwnerCode		= owner_id
			,@v_vchDTOrderNumber	= order_number
			,@v_vchDTLineNumber		= line_number
			,@v_vchDTItemNumber		= item_number
			,@v_fltDTQuantity		= order_quantity
			,@v_vchDTUOM			= uom
			,@v_vchDTLPN			= lpn
			,@v_vchDTLotNumber		= lot_number
			,@v_vchDTExpiryDate		= CASE CONVERT(NVARCHAR,expiry_date,112) WHEN '19000101' THEN NULL ELSE CONVERT(VARCHAR(8),expiry_date,112) END
			,@v_vchDTSerialNumber	= serial_number
			,@v_vchDTAttribute1		= attribute1
			,@v_vchDTAttribute2		= attribute2
			,@v_vchDTAttribute3		= attribute3
			,@v_vchDTAttribute4		= attribute4
			,@v_vchDTAttribute5		= attribute5
			,@v_vchDTDefaultItemStatus = default_item_status
			,@v_vchDTOverReceiptAllowed = (CASE WHEN ISNULL(over_receipt_percentage,0) > 0 THEN 'YES' ELSE 'NO' END)
			,@v_fltDTOverReceiptPercent = ISNULL(over_receipt_percentage,0) 
			,@v_fltDTPrice			= price  
			,@v_vchDTUDF1			= user_def1  
			,@v_vchDTUDF2			= user_def2  
			,@v_vchDTUDF3			= user_def3
			,@v_vchDTUDF4			= user_def4
			,@v_vchDTUDF5			= user_def5
			,@v_vchDTUDF6			= user_def6
			,@v_fltDTUDF7			= user_def7
			,@v_fltDTUDF8			= user_def8
			,@v_dtDTUDF9			= CASE CONVERT(NVARCHAR,user_def9,112) WHEN '19000101' THEN NULL ELSE user_def9 END
			,@v_dtDTUDF10			= CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
			,@v_vchDTUserID			= create_by

		FROM t_host_wms_inbound_order_detail  
		WHERE host_record_id = @in_vchHostRecordID
		AND processing_status = 'PENDING'  
		ORDER BY line_number

		IF (ISNULL(@v_vchDTDefaultItemStatus,'') = '')
			BEGIN
				SET @v_vchDTDefaultItemStatus = [dbo].[usf_GetRuleValue] ('RULE_STATUS_INBOUND_DEFAULT',NULL,'WH_RULE')
			END
		
		----------------------------------------------------------  
		--  Check for Required Fields
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Checking Required Fields'  
		-- Future, Add a Log action for inserting into the Process Log   

		IF (ISNULL(@v_vchRecordType,'') = ''
			OR ISNULL(@v_vchProcessingCode,'') = ''  
			OR ISNULL(@v_vchProcessingStatus,'') = '' 
			OR ISNULL(@v_vchDTWarehouse,'') = ''
			OR ISNULL(@v_vchDTOwnerCode,'') = ''  
			OR ISNULL(@v_vchDTOrderNumber,'') = '' 
			OR ISNULL(@v_vchDTLineNumber,'') = '' 
			OR ISNULL(@v_vchDTItemNumber,'') = ''  
			OR ISNULL(@v_fltDTQuantity,0) = 0
			OR ISNULL(@v_vchDTUOM,'') = ''  
			OR ISNULL(@v_vchDTUserID,'') = '' 
			) 			
		BEGIN
			------------------------------------------------------------  
			--  Missing Required Fields   
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
			SELECT 'Field List:' + ' Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
				+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
				+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
				+ ' Warehouse ID: ['+ISNULL(@v_vchDTWarehouse, '') + ']'   
				+ ' Owner: ['+ISNULL(@v_vchDTOwnerCode, '') + ']'   
				+ ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'   
				+ ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   
				+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'   
				+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']'  
				+ ' UOM: ['+ISNULL(@v_vchDTUOM, '') + ']'   
				+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'     

			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Missing Required Fields  
			SET @v_vchErrorType = 'DETAIL'
			GOTO WRITE_PROCESS_LOG
		END

		----------------------------------------------------------  
		--  Get Warehouse Master ID [wh_master_id]
		--  Check to make sure that Warehouse ID in the Import Data   
		--  is a valid Warehouse ID that is in the t_wms_wh table  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Warehouse ID GUID'  
		-- Future, Add a Log action for inserting into the Process Log    
		SET @v_vchWhMasterID = NULL
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id, @v_vchDTWarehouse = wh_id FROM t_wms_wh WHERE wh_id = @v_vchDTWarehouse AND is_active = 'YES'
		IF (@v_vchWhMasterID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Warehouse ID is Invalid'  
				-- Future, Add a Log action for inserting into the Process Log    
				SET @out_vchErrorCode = 'ERROR-LOGMAN-004' -- Invalid Warehouse in Import Data  
				GOTO WRITE_PROCESS_LOG
			END  

		------------------------------------------------------------  
		-- Check for Valid Owner  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchOwnerID = NULL
		SELECT @v_vchOwnerID = owner_id, @v_vchDTOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchDTOwnerCode AND is_active = 'YES'
		IF (@v_vchOwnerID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
				GOTO WRITE_PROCESS_LOG
			END
      
	  ----------------------------------------------------------  
		--  Check f or Inbound Order Master and Get the Master ID  
		--  from the Master Inbound Order  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Inbound Order Master'  
		-- Future, Add a Log action for inserting into the Process Log  
		
		SET @v_vchInboundMasterID = NULL
		SET @v_vchCurrentOrderStatus = NULL
		SET @v_vchOrderType = NULL
		SELECT TOP 1 @v_vchInboundMasterID = inbound_order_master_id
			,@v_vchCurrentOrderStatus = order_status
			,@v_vchOrderType = order_type
		FROM t_wms_inbound_master 
		WHERE inbound_order_number = @v_vchDTOrderNumber 
		AND wh_master_id = @v_vchWhMasterID
		IF @v_vchInboundMasterID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Inbound Order is Invalid - No Master Record'  
				-- Future, Add a Log action for inserting into the Process Log    

				SET @out_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record  
				GOTO WRITE_PROCESS_LOG
			END   

		------------------------------------------------------------  
		--  Check Valid Record Types  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Record Type'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchRecordType <> 'DETAIL')  
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type: [' + ISNULL(@v_vchRecordType, '') +']'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
				GOTO WRITE_PROCESS_LOG
			END  
  
		------------------------------------------------------------  
		--  Check Valid Processing Code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
		-- Future, Add a Log action for inserting into the Process Log

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE','DELETE') -- Do we want to DELETE JUST a LINE?  , 'DELETE')  
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+']'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
				GOTO WRITE_PROCESS_LOG
			END  
    
		------------------------------------------------------------  
		--  Check Valid Processing Status  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+']'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
				GOTO WRITE_PROCESS_LOG
			END
		
		------------------------------------------------------------
		--  Get Item GUID & Item BASE UOM GUID  
		------------------------------------------------------------
		DECLARE @v_vchLotControl		VARCHAR(5)
		DECLARE @v_vchExpiryDateControl	VARCHAR(5)
		DECLARE @v_vchSnControl			VARCHAR(5)
		DECLARE @v_vchAttribute1Control	VARCHAR(5)
		DECLARE @v_vchAttribute2Control	VARCHAR(5)
		DECLARE @v_vchAttribute3Control	VARCHAR(5)
		DECLARE @v_vchAttribute4Control	VARCHAR(5)
		DECLARE @v_vchAttribute5Control	VARCHAR(5)

		SET @v_vchWhItemMasterID = NULL;
		SET @v_vchItemMasterID = NULL; 
		SELECT TOP 1 @v_vchWhItemMasterID = whItem.wh_item_master_id 
			, @v_vchItemMasterID = item.item_master_id
			, @v_vchDTItemNumber = item.item_number
			, @v_vchDTGrade	= item.grade
			, @v_vchLotControl = item.lot_control
			, @v_vchExpiryDateControl = item.expiry_date_control
			, @v_vchSnControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
		FROM t_wms_item item
		INNER JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id
		WHERE whItem.wh_master_id = @v_vchWhMasterID
		AND item.owner_id = @v_vchOwnerID
		AND item.item_number = @v_vchDTItemNumber
		AND item.is_active = 'YES'

		------------------------------------------------------------  
		--  Check for Valid Item in the Warehouse  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse Item'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchWhItemMasterID IS NULL  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid item in warehouse'  
				-- Future, Add a Log action for inserting into the Process Log    

				SET @out_vchErrorCode = 'ERROR-IFMAN-011' -- Invalid Item in Warehouse  
				GOTO WRITE_PROCESS_LOG
			END
      
		--Check เงื่อนไข Item Control และมีการระบุข้อมูลใน Plan
		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ lot
		IF @v_vchLotControl = 'NONE' AND ISNULL(@v_vchDTLotNumber,'') <> ''
			BEGIN
				SET @v_vchDTLotNumber = NULL
			END 

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Exp.
		IF @v_vchExpiryDateControl = 'NONE' AND ISNULL(@v_vchDTExpirydate,'') <> ''
			BEGIN
				SET @v_vchDTLotNumber = NULL
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Serial.
		IF @v_vchSnControl = 'NONE' AND ISNULL(@v_vchDTSerialNumber,'') <> ''
			BEGIN
				SET @v_vchDTSerialNumber = NULL
			END
		IF @v_vchSnControl = 'FULL' AND ISNULL(@v_vchDTSerialNumber,'') <> ''
			BEGIN
				SET @v_fltDTQuantity = 1
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Attribute 1
		IF @v_vchAttribute1Control = 'NONE' AND ISNULL(@v_vchDTAttribute1,'') <> ''
			BEGIN
				SET @v_vchDTAttribute1 = NULL
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Attribute 2
		IF @v_vchAttribute2Control = 'NONE' AND ISNULL(@v_vchDTAttribute2,'') <> ''
			BEGIN
				SET @v_vchDTAttribute2 = NULL
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Attribute 3
		IF @v_vchAttribute3Control = 'NONE' AND ISNULL(@v_vchDTAttribute3,'') <> ''
			BEGIN
				SET @v_vchDTAttribute3 = NULL
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Attribute 4
		IF @v_vchAttribute4Control = 'NONE' AND ISNULL(@v_vchDTAttribute4,'') <> ''
			BEGIN
				SET @v_vchDTAttribute4 = NULL
			END

		--ถ้าไม่ได้ Control ก็ต้องไม่ต้องระบุ Attribute 5
		IF @v_vchAttribute5Control = 'NONE' AND ISNULL(@v_vchDTAttribute5,'') <> ''
			BEGIN
				SET @v_vchDTAttribute5 = NULL
			END

		-----------------------------------------------------------
		-- Validate Input UOM
		-----------------------------------------------------------
		SET @v_vchDTItemUomID = NULL;
		SELECT TOP 1 @v_vchDTItemUomID = item_uom_id
			, @v_vchDTUom = uom
			, @v_fltDTConversionFactor = conversion_factor
			, @v_vchPrimaryUOM = primary_uom
	    FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID
		AND uom = @v_vchDTUom
		AND is_active = 'YES'
		----------------------------------------------------------  
		--  Check for Valid Item UOM  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Valid Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchDTItemUomID IS NULL  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item UOM is Invalid'  
				-- Future, Add a Log action for inserting into the Process Log    

				SET @out_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid UOM Detail in Import Data - No UOM Record  
				GOTO WRITE_PROCESS_LOG
			END

		-----------------------------------------------------------
		-- Validate Base UOM
		-----------------------------------------------------------
		IF @v_vchPrimaryUOM = 'NO'
			BEGIN
				SET @v_vchBaseItemUomID = NULL
				SET @v_vchBaseUOM = NULL
				SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
					, @v_vchBaseUOM = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				
				IF  @v_vchBaseItemUomID IS NULL  
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item UOM is Invalid'  
						-- Future, Add a Log action for inserting into the Process Log    

						SET @out_vchErrorCode = 'ERROR-IFMAN-057' -- Invalid UOM Detail in Import Data - No Primary UOM Record  
						GOTO WRITE_PROCESS_LOG  
					END
			END
		ELSE
			BEGIN
				SET @v_vchBaseItemUomID = @v_vchDTItemUomID
				SET @v_vchBaseUOM = @v_vchDTUom
			END
		
		-------------------------------------------------------------------
		-- คำนวณ Qty เป็นหน่วย Base
		-------------------------------------------------------------------
        SET @v_fltDTQuantity = ROUND(@v_fltDTQuantity * @v_fltDTConversionFactor,@Round)

		SET @v_vchInboundDetailID = NULL
		SELECT @v_vchInboundDetailID = inbound_order_detail_id
			,@v_fltQuantityReceive = quantity_receive  
		FROM t_wms_inbound_detail  
		WHERE inbound_order_master_id = @v_vchInboundMasterID  
		AND wh_item_master_id = @v_vchWhItemMasterID  
		AND line_number = @v_vchDTLineNumber
       
		-------------------------------------------------------------------------  
		--  ลบข้อมูล โดยที่จะต้องมีเงื่อนไข ดังนี้  
		--  Processing code = Delete  
		--  Quantity Receive = 0  
		--  จะต้องมี Record Order Detail ID ที่ Item Number และ Line Number ตรงกัน  
		-------------------------------------------------------------------------  
		IF (@v_vchProcessingCode = 'DELETE')
			BEGIN
				IF (@v_vchInboundDetailID IS NOT NULL AND ISNULL(@v_fltQuantityReceive,0) = 0)
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Delete Processing for Item Number:['+@v_vchDTItemNumber+']'  
						-- Future, Add a Log action for inserting into the Process Log  

						DELETE t_wms_inbound_detail WHERE inbound_order_detail_id = @v_vchInboundDetailID

						---------------------------------------------------   
						-- Update Process Status = COMPLETED  
						---------------------------------------------------  
						UPDATE t_host_wms_inbound_order_detail SET processing_status = 'COMPLETED' WHERE inbound_order_detail_id = @v_vchHostIBDetailIDGUID  

						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete item number completed. [Inbound Order Detail]'  
						-- Future, Add a Log action for inserting into the Process Log  
						
						------------------------------------------------------------------------------
						-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
						------------------------------------------------------------------------------
						IF  EXISTS (SELECT host_record_id FROM t_host_wms_inbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)
							BEGIN
								GOTO INBOUND_DETAIL_LABEL;
							END
						ELSE
							BEGIN
								GOTO COMMIT_TRANS; 
							END
					END
				ELSE  
					BEGIN
						IF (@v_vchInboundDetailID IS NULL)
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @out_vchErrorCode = 'ERROR-IFMAN-031' --No Detail Data for the delete.
								GOTO WRITE_PROCESS_LOG
							END  
						
						IF ISNULL(@v_fltQuantityReceive,0) > 0
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @out_vchErrorCode = 'ERROR-IFMAN-034' -- Cannot delete item. Because the quantity receive is greater than 0.  
								GOTO WRITE_PROCESS_LOG
							END  
					END  
			END  
       
		-------------------------------------------------------------------
		--  Check Data for Add or Update  
		-------------------------------------------------------------------
		SET @v_vchInboundDetailID = NULL
		SELECT TOP 1 @v_vchInboundDetailID = inbound_order_detail_id 
		FROM t_wms_inbound_detail  
		WHERE inbound_order_master_id = @v_vchInboundMasterID
		AND line_number = @v_vchDTLineNumber
		IF @v_vchInboundDetailID IS NOT NULL
			BEGIN
				SET @v_vchProcessingCode = 'UPDATE'  
			END
		ELSE
			BEGIN
				SET @v_vchProcessingCode = 'ADD'  
			END

		-------------------------------------------------------------------------  
		--  Invalid Order Detail in Import Data - No Master Record  
		-------------------------------------------------------------------------  
		IF @v_vchInboundDetailID IS NULL AND @v_vchProcessingCode IN ('DELETE','UPDATE')
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Inbound Order Detail is Invalid'
				-- Future, Add a Log action for inserting into the Process Log    
		  
				SET @out_vchErrorCode = 'ERROR-IFMAN-010' -- INVALID ORDER DETAIL - NO DETAIL RECORD EXISTS TO UPDATE  
				GOTO WRITE_PROCESS_LOG 
			END

		-------------------------------------------------------------------
		--  Check the Inbound Order for a ADD duplicate.  
		-------------------------------------------------------------------
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Line Number.'   
		-- Future, Add a Log action for inserting into the Process Log   
			      
		IF (@v_vchProcessingCode = 'ADD' AND @v_vchInboundDetailID IS NOT NULL)  -- Duplicate Order Error  
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Found. Order Number:[' + @v_vchDTOrderNumber  +']' 
																			+ ' Line Number:['+@v_vchDTLineNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log
				SET @out_vchErrorCode = 'ERROR-IFMAN-007' -- INVALID ORDER DETAIL - DUPLICATE LINE NUMBER  
				GOTO WRITE_PROCESS_LOG
			END
		ELSE IF (@v_vchProcessingCode = 'ADD' AND @v_vchInboundDetailID IS NULL)  -- ADD Inbound Order Detail  
			BEGIN
				-------------------------------------------------------------------  
				--  ตรวจสอบ RULE ว่ามีการอนุญาตให้มีการบันทึก Item Master ซ้ำหรือไม่   
				--  'YES' = item ซ้ำได้  
				--  'NO' = item ซ้ำไม่ได้  
				-------------------------------------------------------------------
				IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_ALLOW_MULTILINE_ITEM_IO' and is_active = 'YES') = 'NO'
					BEGIN
						-------------------------------------------------------------------  
						-- กรณีที่ไม่ได้กำหนด Rule ไม่สามารถบันทึก Item ซ้ำได้ 
						-- Check Item ที่ใน Order ต้องห้ามซ้ำกัน
						-------------------------------------------------------------------
						IF EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID AND line_number <> @v_vchDTLineNumber)
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check duplicate item:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log  

								SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
								GOTO WRITE_PROCESS_LOG
							END  
					END
				/*
				ELSE
					BEGIN
						-------------------------------------------------------------------  
						-- ตรวจสอบ Order Type ที่อนุญาตให้บันทึก Item Number ซ้ำได้ 
						-- ถ้า Order Type ไม่ตรงกับที่กำหนดไว้ ก็ต้องเช็ค Item Number ห้ามซ้ำเหมือนกัน
						-------------------------------------------------------------------  
						IF NOT EXISTS (SELECT combobox_item_id FROM  t_com_combobox_item WHERE group_name ='inbound_order_type_allow_multiline_item' AND is_active = 'YES' AND value_member = @v_vchOrderType)
							BEGIN
								-------------------------------------------------------------------  
								-- กรณีที่ไม่ได้กำหนด Rule ไม่สามารถบันทึก Item ซ้ำได้ 
								-- Check Item ที่ใน Order ต้องห้ามซ้ำกัน
								-------------------------------------------------------------------
								IF EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID AND line_number <> @v_vchDTLineNumber)
									BEGIN 
										IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check duplicate item:['+@v_vchDTItemNumber+']'  
										-- Future, Add a Log action for inserting into the Process Log  

										SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
										GOTO WRITE_PROCESS_LOG
									END  
							END           
					END
				*/
	        
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Detail Line'  
				-- Future, Add a Log action for inserting into the Process Log  

				IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
					BEGIN
						SELECT 'Field List 1: Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'  
							 + ' Warehose ID: ['+ISNULL(@v_vchDTWarehouse, '') + ']'   
							 + ' Owner: ['+ISNULL(@v_vchDTOwnerCode, '') + ']'   
							 + ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'
						SELECT 'Field List 2: Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'   
							 + ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   
							 + ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'     
							 + ' UOM: ['+ISNULL(@v_vchDTUOM, '') + ']'    
							 + ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']'  
							 + ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'    
					END

				INSERT INTO [dbo].[t_wms_inbound_detail]
				   ([inbound_order_detail_id]				
				   ,[inbound_order_master_id]
				   ,[wh_item_master_id]
				   ,[item_master_id]
				   ,[item_uom_id]
				   ,[item_number]
				   ,[line_number]
				   ,[quantity_order] 
				   ,[uom]
				   ,[item_status]
				   ,[lpn]
				   ,[default_item_status]
				   ,[price]
				   ,[grade]
				   ,[over_receipt_allowed]
				   ,[over_receipt_percentage]
				   ,[source_of_record]
				   ,[lot_number]
				   ,[expiry_date]
				   ,[serial_number]
				   ,[attribute1]
				   ,[attribute2]
				   ,[attribute3]
				   ,[attribute4]
				   ,[attribute5]
				   ,[user_def1]
				   ,[user_def2]
				   ,[user_def3]
				   ,[user_def4]
				   ,[user_def5]
				   ,[user_def6]
				   ,[user_def7]
				   ,[user_def8]
				   ,[user_def9]
				   ,[user_def10] 
				   ,[create_by]
				   ,[create_date])
				VALUES
				   (NEWID()
				   ,@v_vchInboundMasterID
				   ,@v_vchWhItemMasterID
				   ,@v_vchItemMasterID
				   ,@v_vchBaseItemUomID
				   ,@v_vchDTItemNumber
				   ,@v_vchDTLineNumber
				   ,@v_fltDTQuantity
				   ,@v_vchBaseUOM
				   ,'NEW'
				   ,@v_vchDTLPN
				   ,@v_vchDTDefaultItemStatus
				   ,@v_fltDTPrice
				   ,@v_vchDTGrade
				   ,@v_vchDTOverReceiptAllowed
				   ,@v_fltDTOverReceiptPercent
				   ,@v_vchHostSource
				   ,@v_vchDTLotNumber
				   ,@v_vchDTExpirydate
				   ,@v_vchDTSerialNumber
				   ,@v_vchDTAttribute1
				   ,@v_vchDTAttribute2
				   ,@v_vchDTAttribute3
				   ,@v_vchDTAttribute4
				   ,@v_vchDTAttribute5
				   ,@v_vchDTUDF1
				   ,@v_vchDTUDF2
				   ,@v_vchDTUDF3
				   ,@v_vchDTUDF4
				   ,@v_vchDTUDF5
				   ,@v_vchDTUDF6
				   ,@v_fltDTUDF7
				   ,@v_fltDTUDF8
				   ,@v_dtDTUDF9
				   ,@v_dtDTUDF10
				   ,@v_vchDTUserID
				   ,GETDATE())
	               
				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
						--							+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
						--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						--SELECT @v_vchProcessData3 = 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
						--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
						--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
						--SELECT @v_vchProcessData4 = 'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'
						--							+ 'Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']' 
						--SELECT @out_vchErrorMessage= 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END
      
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						--SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						--SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
						--							+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
						--							+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						--SELECT @v_vchProcessData3 = 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
						--							+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
						--							+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
						--SELECT @v_vchProcessData4 = 'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'
						--							+ 'Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'
						--SELECT @out_vchErrorMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END
	       
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_inbound_order_detail SET processing_status = 'COMPLETED' WHERE inbound_order_detail_id = @v_vchHostIBDetailIDGUID  

				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Completed'   
			END
		ELSE IF (@v_vchProcessingCode = 'UPDATE' AND @v_vchInboundDetailID IS NOT NULL) -- UPDATE Inbound Order Detail  
			BEGIN
				------------------------------------------------------------  
				--  Check Order Status - No Change if Order Status not OPEN  
				------------------------------------------------------------
				IF @v_vchCurrentOrderStatus NOT IN ('OPEN')  
					BEGIN
						IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Order Status not Available for Change.'  
									 +' Order Number:[' + @v_vchOrderNumber + ']' 
									 +' Order Status:[' + ISNULL(@v_vchCurrentOrderStatus, '') + ']' 
						
						-- Future, Add a Log action for inserting into the Process Log  

						SET @out_vchErrorCode = 'ERROR-IFMAN-003' -- ORDER STATUS NOT OPEN  
						GOTO WRITE_PROCESS_LOG
					END        

				------------------------------------------------------------  
				--  Check Item Line Detail Status - No Change if Item Status not New  
				------------------------------------------------------------  
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Item Status for Update:['+@v_vchCurrentOrderStatus+']'  
				-- Future, Add a Log action for inserting into the Process Log  
				 
				IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
					BEGIN
						SELECT 'Field List: Current Item Status:['+ISNULL(@v_vchCurrentOrderStatus, '') + ']'  
							+' Order Detail Line Number:['+ISNULL(@v_vchDTLineNumber, '') + ']' 
							+' Item Number:['+ISNULL(@v_vchDTItemNumber, '') + ']'    
					END

				IF (SELECT ISNULL(quantity_receive,0) FROM t_wms_inbound_detail WHERE inbound_order_detail_id = @v_vchInboundDetailID) > 0
					BEGIN
						IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Item Status not Available for Change.]'
						-- Future, Add a Log action for inserting into the Process Log  
						  
						SET @out_vchErrorCode = 'ERROR-IFMAN-009' -- Item Status not Available for Change  
						GOTO WRITE_PROCESS_LOG 
					END
			     
				-------------------------------------------------------------------  
				--  ตรวจสอบ RULE ว่ามีการอนุญาตให้มีการบันทึก Item Master ซ้ำหรือไม่   
				--  'YES' = item ซ้ำได้  
				--  'NO' = item ซ้ำไม่ได้  
				-------------------------------------------------------------------
				IF (SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_ALLOW_MULTILINE_ITEM_IO' and is_active = 'YES') = 'NO'
					BEGIN
						-------------------------------------------------------------------  
						-- กรณีที่ไม่ได้กำหนด Rule ไม่สามารถบันทึก Item ซ้ำได้ 
						-- Check Item ที่ใน Order ต้องห้ามซ้ำกัน
						-------------------------------------------------------------------
						IF EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID AND line_number <> @v_vchDTLineNumber)
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check duplicate item:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log  
							 
								SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
								GOTO WRITE_PROCESS_LOG
							END  
					END
				/*
				--ELSE  
				--	BEGIN
				--		-------------------------------------------------------------------  
				--		-- ตรวจสอบ Order Type ที่อนุญาตให้บันทึก Item Number ซ้ำได้ 
				--		-- ถ้า Order Type ไม่ตรงกับที่กำหนดไว้ ก็ต้องเช็ค Item Number ห้ามซ้ำเหมือนกัน
				--		-------------------------------------------------------------------
						
				--		IF NOT EXISTS (SELECT combobox_item_id FROM  t_com_combobox_item WHERE group_name ='inbound_order_type_allow_multiline_item' AND is_active = 'YES' AND value_member = @v_vchOrderType)
				--			BEGIN
				--				-------------------------------------------------------------------  
				--				-- กรณีที่ไม่ได้กำหนด Rule ไม่สามารถบันทึก Item ซ้ำได้ 
				--				-- Check Item ที่ใน Order ต้องห้ามซ้ำกัน
				--				-------------------------------------------------------------------
				--				IF EXISTS (SELECT inbound_order_detail_id FROM t_wms_inbound_detail WHERE inbound_order_master_id = @v_vchInboundMasterID AND wh_item_master_id = @v_vchWhItemMasterID AND line_number <> @v_vchDTLineNumber)
				--					BEGIN
				--						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check duplicate item:['+@v_vchDTItemNumber+']'  
				--						-- Future, Add a Log action for inserting into the Process Log  

				--						SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
				--						GOTO WRITE_PROCESS_LOG
				--					END  
				--			END
				--	END
				*/
			  
				------------------------------------------------------------  
				--  Processing for 'UPDATE'.        
				--  Update an existing Item in the item Table  
				------------------------------------------------------------  
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Processing Code for Update'  
				-- Future, Add a Log action for inserting into the Process Log  

				IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
					BEGIN
						SELECT 'Field List :' 
							 + ' Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'  
							 + ' Owner: ['+ISNULL(@v_vchDTOwnerCode, '') + ']'    
							 + ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'    
							 + ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'    
							 + ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'    
							 + ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'    
							 + ' UOM: ['+ISNULL(@v_vchDTUOM, '') + ']'   
							 + ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']'   
							 + ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'   
					END  

				UPDATE t_wms_inbound_detail SET 
					  wh_item_master_id = @v_vchWhItemMasterID
					, item_master_id = @v_vchItemMasterID
					, item_number = @v_vchDTItemNumber
					, quantity_order = @v_fltDTQuantity  
					, item_uom_id = @v_vchBaseItemUomID  
					, uom = @v_vchBaseUOM
					, default_item_status = @v_vchDTDefaultItemStatus  
					, price = @v_fltDTPrice
					, lpn = @v_vchDTLPN
					, lot_number = @v_vchDTLotNumber
					, expiry_date = @v_vchDTExpirydate
					, serial_number = @v_vchDTSerialNumber
					, attribute1 = @v_vchDTAttribute1
					, attribute2 = @v_vchDTAttribute2
					, attribute3 = @v_vchDTAttribute3
					, attribute4 = @v_vchDTAttribute4
					, attribute5 = @v_vchDTAttribute5
					, over_receipt_allowed = @v_vchDTOverReceiptAllowed  
					, over_receipt_percentage = @v_fltDTOverReceiptPercent  
					, user_def1 = @v_vchDTUDF1
					, user_def2 = @v_vchDTUDF2
					, user_def3 = @v_vchDTUDF3
					, user_def4 = @v_vchDTUDF4
					, user_def5 = @v_vchDTUDF5
					, user_def6 = @v_vchDTUDF6
					, user_def7 = @v_fltDTUDF7
					, user_def8 = @v_fltDTUDF8
					, user_def9 = @v_dtDTUDF9
					, user_def10 = @v_dtDTUDF10
					, source_of_record = @v_vchHostSource
					, update_by = @v_vchDTUserID
					, update_date = GETDATE()
				WHERE inbound_order_detail_id = @v_vchInboundDetailID 

				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_inbound_order_detail SET processing_status = 'COMPLETED' WHERE inbound_order_detail_id = @v_vchHostIBDetailIDGUID           
			END
	       
		IF EXISTS (SELECT host_record_id FROM t_host_wms_inbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)    
			GOTO INBOUND_DETAIL_LABEL   
	END
	
	COMMIT_TRANS: 
		COMMIT TRANSACTION
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;

	-----------------------------------------------------------------------------------
	-- WRITE PROCESS LOG
	-----------------------------------------------------------------------------------
	BEGIN
	WRITE_PROCESS_LOG:
		ROLLBACK TRANSACTION;
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log

		SET @v_vchLogType = 'IMPORT ERROR'  
		IF @v_vchErrorType = 'MASTER'
			BEGIN
				-- Future, Add a Log action for inserting into the Process Log  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']'
											+ ' Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
											+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
				SELECT @v_vchProcessData4 =   'Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
											+ ' Order Status: ['+ISNULL(@v_vchOrderStatus, '') + ']'
											+ ' Order Date: ['+CONVERT(VARCHAR(30),ISNULL(@v_dtOrderDate, '')) + ']' 
											+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'

				SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

			END
		ELSE IF @v_vchErrorType = 'DETAIL'
			BEGIN
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']'
											+ ' Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'			
				SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'   
											+ ' Warehouse: ['+ISNULL(@v_vchDTWarehouse, '') + ']' 
											+ ' Owner: ['+ISNULL(@v_vchDTOwnerCode, '') + ']'	
											+ ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']' 
											+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
				SELECT @v_vchProcessData4 = 'Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
											+ ' UOM: ['+ISNULL(@v_vchDTUOM, '') + ']'     
											+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'   		
				SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			END
		
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
					+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
					+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
					+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
					+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
			SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
					+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
					+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
					+' Message: ['+ISNULL(@out_vchErrorMessage, '') + ']' 
					+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		END

		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'INBOUND'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchOrderNumber,'NO ORDER'), 50)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 100)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE()) 

		-------------------------------------------------   
		-- SEND EMAIL ERROR  
		-------------------------------------------------    
		--SET @v_vchSubject = 'INTERFACE INBOUND ORDER ERROR'	
		--SET @v_vchMessage = '<BR>'+ @v_vchMessage
		--					+'<BR> Detail 1'+(CASE ISNULL(@v_vchProcessData2,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData2 END)
		--					+'<BR> Detail 2'+(CASE ISNULL(@v_vchProcessData3,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData3 END)
		--					+'<BR> Detail 3'+(CASE ISNULL(@v_vchProcessData4,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData4 END)
		--EXEC usp_send_mail_error_interface @v_vchSubject, @v_vchMessage
  
		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  
		UPDATE t_host_wms_inbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_inbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_inbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  

	GOTO EXIT_LABEL;
	END
END TRY
-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	ROLLBACK TRANSACTION
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT @v_intSqlErrorNumber = ERROR_NUMBER()
			, @v_vchSqlErrorMessage = ERROR_MESSAGE()
			, @v_intSqlErrorState = ERROR_STATE()
			, @v_intSqlErrorSeverity = ERROR_SEVERITY()
			, @v_intSqlErrorLine = ERROR_LINE()
			, @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
		SET @out_vchErrorMessage = 'SQL Error Message: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
								+'SQL Error Line: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
								+'SQL Error State: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
								+'SQL Error Severity: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
								+'SQL Error Procedure: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SELECT @v_vchProcessData3 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']'
								  + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
								  + ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
								  + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
		SET  @v_vchProcessData4 = + ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']' 

		SET @out_vchErrorCode = @v_intSqlErrorNumber
		SET @out_vchErrorMessage = @v_vchSqlErrorMessage

		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@out_vchErrorMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
			
		
		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'INBOUND'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchOrderNumber,'NO ORDER'), 50)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 100)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())
			
		-------------------------------------------------   
		-- SEND EMAIL ERROR  
		-------------------------------------------------    
		--SET @v_vchSubject = 'INTERFACE INBOUND ORDER ERROR'	
		--SET @v_vchMessage = '<BR>'+ @v_vchMessage
		--					+'<BR> Detail 1'+(CASE ISNULL(@v_vchProcessData2,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData2 END)
		--					+'<BR> Detail 2'+(CASE ISNULL(@v_vchProcessData3,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData3 END)
		--					+'<BR> Detail 3'+(CASE ISNULL(@v_vchProcessData4,'') WHEN '' THEN '' ELSE ' ' + @v_vchProcessData4 END)
		--EXEC usp_send_mail_error_interface @v_vchSubject, @v_vchMessage  

		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  

		UPDATE t_host_wms_inbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_inbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_inbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID
 
END CATCH
  
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END


