CREATE PROCEDURE [dbo].[usp_ProcessHostItemBOM]  
	@in_vchApplicationID	VARCHAR(40)  = NULL, --Required  
	@in_vchApplicationName	NVARCHAR(50) = NULL, --Required  
	@in_vchHostRecordID		VARCHAR(40)	 = NULL, --Required
