	@in_vchUserID			NVARCHAR(25) = NULL, --Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS
BEGIN
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostItemBOM'
	DECLARE @v_intSqlErrorNumber	INTEGER
	DECLARE @v_intSqlErrorLine		INTEGER
	DECLARE @v_intSqlErrorState		INTEGER
	DECLARE @v_intSqlErrorSeverity	INTEGER
	DECLARE @v_vchSqlErrorMessage	NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure	NVARCHAR(200)  
	DECLARE @v_vchProcessData1		NVARCHAR(100)
	DECLARE @v_vchProcessData2		NVARCHAR(100)
	DECLARE @v_vchProcessData3		NVARCHAR(100)
	DECLARE @v_vchProcessData4		NVARCHAR(100)
	DECLARE @v_nErrorNumber			INTEGER
	DECLARE @v_vchMessage			NVARCHAR(500)
	DECLARE @v_nRowCount			INTEGER
	DECLARE @v_intLocale			INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round					INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel			INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction			NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,
 	DECLARE @v_vchTableName			NVARCHAR(50)
	
	-- Local Variables
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemUomID			UNIQUEIDENTIFIER
	DECLARE @v_vchBomID				INT
	DECLARE @v_vchBomDetailID		INT

	--Bom Item 
	DECLARE @v_vchBomWhItemMasterID	UNIQUEIDENTIFIER 
	DECLARE @v_vchBomItemMasterID	UNIQUEIDENTIFIER 
	DECLARE @v_vchBomItemUomID		UNIQUEIDENTIFIER

	--Bom Master
	DECLARE @v_vchRecordType		NVARCHAR(10)
	DECLARE @v_vchProcessingCode	NVARCHAR(40)
	DECLARE @v_vchProcessingStatus	NVARCHAR(40)
	DECLARE @v_vchOwnerCode			NVARCHAR(40)
	DECLARE @v_vchWhID				NVARCHAR(25)
	DECLARE @v_vchBomItemNumber		NVARCHAR(50)
	DECLARE @v_vchBomDesc			NVARCHAR(255)
	DECLARE @v_vchUom				NVARCHAR(10)
	DECLARE @v_vchUserDef1			NVARCHAR(50)
	DECLARE @v_vchIsBomItem			NVARCHAR(3)
	DECLARE @v_vchIsActive			NVARCHAR(3)
	DECLARE @v_vchUserID			NVARCHAR(25)
	
	--Bom Detail
	
	DECLARE @v_vchHostBomDetailID	VARCHAR(40)
	DECLARE @v_vchDTBomWarehouse	NVARCHAR(25)
	DECLARE @v_vchDTBomOwner		NVARCHAR(25)
	DECLARE @v_vchDTBomItemNumber	NVARCHAR(50)
	DECLARE @v_vchDTLineNo			NVARCHAR(10)
	DECLARE @v_vchDTItemNumber		NVARCHAR(50)
	DECLARE @v_vchDTDescription		NVARCHAR(255)
	DECLARE @v_vchDTGetDescription	NVARCHAR(255)
	DECLARE @v_fltDTQuantity		float
	DECLARE @v_vchDTUom				NVARCHAR(10)
	DECLARE @v_vchDTUserID			NVARCHAR(25)
	
BEGIN TRY  
	BEGIN TRANSACTION
	
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT TOP 1 @v_vchRecordType	= [record_type]
		  ,@v_vchProcessingCode		= [processing_code]
		  ,@v_vchProcessingStatus	= [processing_status]
		  ,@v_vchOwnerCode			= [owner_code]
		  ,@v_vchWhID				= [wh_id]
		  ,@v_vchBomItemNumber		= [bom_item_number]
		  ,@v_vchBomDesc			= [bom_desc]
		  ,@v_vchUom				= [uom]
		  ,@v_vchUserDef1			= [user_def1]
		  ,@v_vchIsBomItem			= [is_bom_item]
		  ,@v_vchIsActive			= [is_active]
		  ,@v_vchUserID				= [create_by]
	  FROM [dbo].[t_host_wms_item_bom]
	  WHERE host_record_id = @in_vchHostRecordID

	----------------------------------------------------------  
	--  Check Nulls for Required Fields  
	--  Item Number, Owner, Item Category, User ID
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    

	IF @v_vchRecordType IS NULL  
		OR @v_vchProcessingCode IS NULL   
		OR @v_vchProcessingStatus IS NULL
		OR @v_vchWhID IS NULL  
		OR @v_vchBomItemNumber IS NULL  
		OR @v_vchOwnerCode IS NULL
		OR @v_vchUserID IS NULL  
		OR @v_vchUom IS NULL 
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
		SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
							 + ' Warehouse : ['+ISNULL(@v_vchWhID, '') + ']' 
							 + ' BOM Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']' 
							 + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
							 + ' UOM : [' + ISNULL(@v_vchUom,'') + ']' 
							 + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
		                 
		-- Future, Add a Log action for inserting into the Process Log  
		
		SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
		SET @v_vchLogType = 'IMPORT ERROR'   
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
									+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
									+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
		SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
		SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO WRITE_PROCESS_LOG  
	END
    
	------------------------------------------------------------  
	--  Check Valid Record Type Code  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Types'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchRecordType <> 'MASTER')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END
  
	------------------------------------------------------------  
	--  Check Valid Processing Code the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG    
		END
     
	------------------------------------------------------------  
	--  Check Valid Processing Status the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingStatus NOT IN ('PENDING')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
