			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END     
	
	------------------------------------------------------------  
	-- Check for Valid Warehouse  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchWhMasterID = wh_master_id, @v_vchWhID = wh_id FROM t_wms_wh WHERE wh_id = @v_vchWhID AND is_active = 'YES'
	IF (@v_vchWhMasterID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Warehouse'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-013' -- Invalid Warehouse  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END
    
	------------------------------------------------------------  
	-- Check for Valid BOM Item  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM item number'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchBomItemMasterID = item_master_id 
		,@v_vchBomItemNumber = item_number
	FROM t_wms_item 
	WHERE item_number = @v_vchBomItemNumber 
	AND owner_id = @v_vchOwnerID
	AND is_active = 'YES'
	IF (@v_vchBomItemMasterID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item Number not found'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-048' -- Item Number not found  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END
    
	------------------------------------------------------------  
	-- Check for Valid BOM Warehouse Item  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM Warehouse Item'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchBomWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchBomItemMasterID AND wh_master_id = @v_vchWhMasterID
	IF (@v_vchBomWhItemMasterID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Warehouse Item Number not found'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-049' -- Item Number not found  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	-- Check for Valid UOM Item  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM UOM'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchBomItemUomID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchBomItemMasterID AND uom = @v_vchUom AND is_active = 'YES'
	IF (@v_vchBomItemUomID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'BOM UOM not found'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-017' -- Item Number not found  
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	--  Get bom id
	------------------------------------------------------------  
	SET @v_vchBomID = NULL;
    SELECT @v_vchBomID = bom_id
	FROM t_wms_item_bom
	WHERE wh_master_id = @v_vchWhMasterID
	AND owner_id = @v_vchOwnerID 
	AND wh_item_master_id = @v_vchBomWhItemMasterID
	AND item_master_id = @v_vchBomItemMasterID

	------------------------------------------------------------  
	--  Processing for 'DELETE' the Item.  
	------------------------------------------------------------  
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Delete Processing for BOM Item:['+@v_vchBomItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  
			IF @v_vchBomID IS NOT NULL
				BEGIN
					---------------------------------------------------   
					-- DELETE ITEM CROSSREF FROM WMS TABLE
					---------------------------------------------------
					DELETE FROM t_wms_item_bom WHERE bom_id = @v_vchBomID
					 
					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_item_bom SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID    
					 
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete Item UOM Completed'  
					GOTO COMMIT_TRANS;
				END
			ELSE
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid BOM ITEM NUMBER'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-050' --Invalid Valid BOM ITEM NUMBER
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
												+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
												+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
					SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
		END   
    
	-------------------------------------------------------------------------  
	--  Check Data for Add or Update  
	-------------------------------------------------------------------------  
	IF @v_vchBomID IS NOT NULL --AND @v_vchProcessingCode = 'ADD'  
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'  
		END
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END

	------------------------------------------------------------
	--  Check the Item for a ADD duplicate.  
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate BOM Item'  
	-- Future, Add a Log action for inserting into the Process Log
      
	IF @v_vchProcessingCode = 'ADD' AND @v_vchBomID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate BOM Item:['+@v_vchBomItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  
			 
			SET @out_vchErrorCode = 'ERROR-IFMAN-051' -- Duplicate BOM Item Number  
			SET @v_vchLogType = 'IMPORT WARNING'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = + ' Warehouse ID: ['+ISNULL(@v_vchWHID,'') + ']'
										+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
										+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END
	ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchBomID IS NULL
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'ADD' the Item .  
			--  This section should be runing for an 'ADD' with no   
			-- duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Duplicate BOM Item:['+@v_vchBomItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			INSERT INTO [dbo].[t_wms_item_bom]
					   ([owner_id]
					   ,[bom_desc]
					   ,[is_bom_item]
					   ,[is_active]
					   ,[create_by]
					   ,[create_date]
					   ,[owner_code]
					   ,[wh_master_id]
					   ,[wh_id]
					   ,[wh_item_master_id]
					   ,[item_master_id]
					   ,[item_number]
					   ,[item_uom_id]
					   ,[uom])
				 VALUES
					   (@v_vchOwnerID
					   ,@v_vchBomDesc
					   ,@v_vchIsBomItem
					   ,@v_vchIsActive
					   ,@v_vchUserID
					   ,GETDATE()
					   ,@v_vchOwnerCode
					   ,@v_vchWhMasterID
					   ,@v_vchWhID
					   ,@v_vchBomWhItemMasterID
					   ,@v_vchBomItemMasterID
					   ,@v_vchBomItemNumber
					   ,@v_vchBomItemUomID
					   ,@v_vchUom)
			
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 = ' Warehouse: ['+ISNULL(@v_vchWhID, '') + ']'
												+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
												+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG 
				END

			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  ' Warehouse: ['+ISNULL(@v_vchWhID, '') + ']'
												+ ' Item Number: ['+ISNULL(@v_vchBomItemNumber, '') + ']'
												+ ' UOM: ['+ISNULL(@v_vchUom, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')	
					GOTO WRITE_PROCESS_LOG
				END

			---------------------------------------------------   
			-- Update Process Status = COMPLETED  
			---------------------------------------------------  
			UPDATE t_host_wms_item_bom SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing ADD Item Master Completed'   
			-- Future, Add a Log action for inserting into the Process Log  
		END
	ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchBomID IS NOT NULL
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE the Item Master.'  
			
			--Clear ข้อมูล Bom Detail ก่อน
			DELETE t_wms_item_bom_detail WHERE bom_id = @v_vchBomID

			UPDATE [dbo].[t_wms_item_bom]
			   SET [bom_desc] = @v_vchBomDesc
				  ,[uom] = @v_vchUom
				  ,[is_bom_item] = @v_vchIsBomItem
				  ,[is_active] = @v_vchIsActive
				  ,[update_by] = @v_vchUserID
				  ,[update_date] = GETDATE()
			 WHERE bom_id = @v_vchBomID
					
			UPDATE t_host_wms_item_bom SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Update Item Master Complete'  
		END  

	/*************************Finished BOM ITEM MASTER ADD*************************/  

	IF  EXISTS (SELECT bom_detail_id FROM dbo.t_host_wms_item_bom_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
	BEGIN  
		------------------------------------------------------------  
		--  Process the BOM Detail Table  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing BOM Item Detail Started'   
	  
		BOM_DETAIL_LABEL:
		-------------------------------------------------------
		-- Clear Value before set the value to variable
		-------------------------------------------------------
		SET @v_vchTableName = 't_host_wms_item_bom_detail'
		SET @v_vchHostBomDetailID	= NULL
		SET @v_vchRecordType	    = NULL
		SET @v_vchProcessingCode    = NULL
		SET @v_vchProcessingStatus  = NULL
		SET @v_vchDTBomWarehouse	= NULL
		SET @v_vchDTBomOwner	    = NULL
		SET @v_vchDTBomItemNumber   = NULL
		SET @v_vchDTLineNo		    = NULL
		SET @v_vchDTItemNumber	    = NULL
		SET @v_vchDTDescription	    = NULL
		SET @v_fltDTQuantity	    = NULL
		SET @v_vchDTUom			    = NULL
		SET @v_vchDTUserID		    = NULL  

		---------------------------------------------------------------------  
		-- Step 1 Read from the Host UOM TABLE (t_host_wms_item_uom)  
		---------------------------------------------------------------------  		
		SELECT TOP 1 @v_vchHostBomDetailID = [bom_detail_id]
			,@v_vchRecordType = [record_type]								
			,@v_vchProcessingCode = [processing_code]								
			,@v_vchProcessingStatus = [processing_status]						
			,@v_vchDTBomWarehouse = [wh_id]											
			,@v_vchDTBomOwner = [owner_code]									
			,@v_vchDTBomItemNumber = [bom_item_number]								
			--,@v_vchDTLineNo = [line_no]										
			,@v_vchDTItemNumber = [item_number]											
			,@v_vchDTDescription = [description]										
			,@v_fltDTQuantity = [quantity]
			,@v_vchDTUom = [uom]
			,@v_vchDTUserID = [create_by]
		FROM [dbo].[t_host_wms_item_bom_detail]
		WHERE host_record_id = @in_vchHostRecordID 
		AND processing_status = 'PENDING'  
		ORDER BY bom_detail_id      
	 
		----------------------------------------------------------  
		--  Check Nulls for Required Fields  
		--  Item Number, Owner, Item Category, User ID
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
		-- Future, Add a Log action for inserting into the Process Log    

		IF @v_vchRecordType IS NULL
			OR @v_vchProcessingCode IS NULL   
			OR @v_vchProcessingStatus IS NULL
			OR @v_vchDTBomWarehouse IS NULL  
			OR @v_vchDTBomOwner IS NULL  
			OR @v_vchDTBomItemNumber IS NULL
			--OR @v_vchDTLineNo IS NULL  
			OR @v_vchDTItemNumber IS NULL 
			OR @v_vchDTUom IS NULL 
			OR @v_vchDTUserID IS NULL 
		BEGIN
			------------------------------------------------------------  
			--  Missing Required Fields   
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
			SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
								 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
								 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
								 + ' Warehouse : ['+ISNULL(@v_vchDTBomWarehouse, '') + ']' 
								 + ' Owner: ['+ISNULL(@v_vchDTBomOwner, '') + ']'
								 + ' BOM Item Number: ['+ISNULL(@v_vchDTBomItemNumber, '') + ']' 
								 + ' Line No: ['+ISNULL(@v_vchDTLineNo, '') + ']' 
								 + ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']' 
								 + ' UOM : [' + ISNULL(@v_vchUom,'') + ']' 
								 + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
		                 
			-- Future, Add a Log action for inserting into the Process Log  
		
			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			SET @v_vchLogType = 'IMPORT ERROR'  
		
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
										+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
										+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
										+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
			SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
										+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
										+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END
    
		------------------------------------------------------------  
		--  Check Valid Record Type Code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Types'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchRecordType <> 'DETAIL')  
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END  

		------------------------------------------------------------  
		-- Check Valid Processing Code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code the Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END
	 
		------------------------------------------------------------  
		-- Check Valid Processing Status  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status the Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  
			 
				SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END
	  
		------------------------------------------------------------  
		-- Check for Quantity 
		------------------------------------------------------------ 
		IF (ISNULL(@v_fltDTQuantity,0) <= 0)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Quantity cannot zero.'  
