				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-013' -- Invalid Warehouse  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END

		------------------------------------------------------------  
		-- Check for Valid Owner  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchOwnerID = NULL
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchDTBomOwner AND is_active = 'YES'
		IF (@v_vchOwnerID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END
		
		------------------------------------------------------------  
		-- Check for Valid BOM Master ID  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM Master ID'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchBomItemMasterID = NULL
		SELECT @v_vchBomItemMasterID = item_master_id FROM t_wms_item WHERE item_number = @v_vchDTBomItemNumber AND owner_id = @v_vchOwnerID AND is_active = 'YES'
		
		SET @v_vchBomWhItemMasterID = NULL
		SELECT @v_vchBomWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchBomItemMasterID AND wh_master_id = @v_vchWhMasterID

		------------------------------------------------------------  
		--  Get bom id
		------------------------------------------------------------  
		SET @v_vchBomID = NULL;
		SELECT @v_vchBomID = bom_id
		FROM t_wms_item_bom
		WHERE wh_master_id = @v_vchWhMasterID
		AND owner_id = @v_vchOwnerID
		AND wh_item_master_id = @v_vchBomWhItemMasterID
		AND item_master_id = @v_vchBomItemMasterID

		------------------------------------------------------------  
		--  Check for BOM Master Record
		------------------------------------------------------------        
		IF @v_vchBomID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Outbound Order is Invalid Bom Item :['+ @v_vchBomItemNumber +']'  
				-- Future, Add a Log action for inserting into the Process Log

				SET @out_vchErrorCode = 'ERROR-IFMAN-052' -- No BOM Master Record  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =  'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END  

		------------------------------------------------------------  
		-- Check for Valid Item Number 
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM item number'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchItemMasterID = NULL
		SELECT @v_vchItemMasterID = item_master_id 
			,@v_vchDTItemNumber = item_number
			,@v_vchDTGetDescription = description
		FROM t_wms_item WHERE item_number = @v_vchDTItemNumber
		AND is_active = 'YES'
		IF (@v_vchItemMasterID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item Number not found'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-048' -- Item Number not found  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - '+ ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG
			END
    
		IF ISNULL(@v_vchDTDescription,'') = ''
			SET @v_vchDTDescription = @v_vchDTGetDescription

		------------------------------------------------------------  
		-- Check for Valid Warehouse Item Number
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for  Warehouse Item Number'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchWhItemMasterID = NULL
		SELECT @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID AND wh_master_id = @v_vchWhMasterID
		IF (@v_vchWhItemMasterID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Warehouse Item Number not found'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-049' -- Warehouse Item Number not found  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

				GOTO WRITE_PROCESS_LOG
			END

		------------------------------------------------------------  
		-- Check for Valid UOM Item  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for BOM UOM'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchItemUomID = NULL
		SELECT @v_vchItemUomID = item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND uom = @v_vchDTUom AND is_active = 'YES'
		IF (@v_vchItemUomID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'BOM UOM not found'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-017' -- Item Number not found  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' 
									   + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

				GOTO WRITE_PROCESS_LOG
			END

		------------------------------------------------------------  
		--  Get BOM Detail ID
		------------------------------------------------------------  
		SET @v_vchBomDetailID = NULL
		SELECT @v_vchBomDetailID = bom_detail_id
		FROM t_wms_item_bom_detail
		WHERE bom_id = @v_vchBomID
		AND wh_item_master_id = @v_vchWhItemMasterID

		------------------------------------------------------------  
		--  Processing for 'DELETE' the Item UOM.  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing the BOM DETAIL'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode = 'DELETE'  
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Delete Processing for BOM DETAIL:['+@v_vchDTBomItemNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log     
			
				IF @v_vchBomDetailID IS NOT NULL
					BEGIN
						---------------------------------------------------   
						-- DELETE BOM DETAIL FROM WMS TABLE
						---------------------------------------------------
						DELETE FROM t_wms_item_bom_detail  WHERE bom_detail_id = @v_vchBomDetailID
					 
						---------------------------------------------------   
						-- Update Process Status = COMPLETED  
						---------------------------------------------------  
						UPDATE t_host_wms_item_bom_detail SET processing_status = 'COMPLETED' WHERE bom_detail_id = @v_vchHostBomDetailID
					 
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete BOM DETAIL Completed'  
					 
						------------------------------------------------------------------------------
						-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
						------------------------------------------------------------------------------
						IF  EXISTS (SELECT bom_detail_id FROM t_host_wms_item_bom_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')
							BEGIN
								GOTO BOM_DETAIL_LABEL;
							END
						ELSE
							BEGIN
								GOTO COMMIT_TRANS;
							END
					END
				ELSE
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Bom Detail - Item Number Does Not Exist '  
						-- Future, Add a Log action for inserting into the Process Log  

						SET @out_vchErrorCode = 'ERROR-IFMAN-053' -- Invalid Bom Detail - Item Number Does Not Exist  
						SET @v_vchLogType = 'IMPORT ERROR'  
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
													+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
													+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
						SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
													+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
													+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
													+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
						SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
													+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
													+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
													+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG  
					END
			END   
	  
		IF @v_vchBomDetailID IS NOT NULL --AND @v_vchProcessingCode = 'ADD'
			BEGIN  
				SET @v_vchProcessingCode = 'UPDATE'  
			END   
		ELSE
			BEGIN
				SET @v_vchProcessingCode = 'ADD'  
			END
		
		------------------------------------------------------------  
		-- 5. Check for No Duplicate BOM ITEM DETAIL
		------------------------------------------------------------  
		IF @v_vchProcessingCode = 'ADD' AND @v_vchBomDetailID IS NOT NULL
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Duplicate BOM Item:['+@v_vchDTBomItemNumber+']'
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-054' -- Duplicate BOM Item Number
				SET @v_vchLogType = 'IMPORT WARNING'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
											+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
											+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
											+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
				SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
											+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
											+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END  
		ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchBomDetailID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting insert data into the BOM Item Number'  
					
				/*************INSERT DATA INTO [t_host_wms_item_bom_detail]*************/  
				DECLARE @v_intLineNo INT = 0;
				SELECT  @v_intLineNo = CONVERT(INT,ISNULl(MAX(line_no),0)) FROM [t_wms_item_bom_detail] WHERE bom_id = @v_vchBomID
				SET @v_vchDTLineNo = RIGHT('000000' + CONVERT(VARCHAR(10), CONVERT(INT,ISNULL(@v_intLineNo,0))+1), 6)

				INSERT INTO [dbo].[t_wms_item_bom_detail]
						   ([bom_id]
						   ,[line_no]
						   ,[description]
						   ,[quantity]
						   ,[create_by]
						   ,[create_date]
						   ,[wh_item_master_id]
						   ,[item_master_id]
						   ,[item_number]
						   ,[item_uom_id]
						   ,[uom])
					 VALUES
						   (@v_vchBomID
						   ,@v_vchDTLineNo
						   ,@v_vchDTDescription
						   ,@v_fltDTQuantity	
						   ,@v_vchDTUserID
						   ,GETDATE()
						   ,@v_vchWhItemMasterID
						   ,@v_vchItemMasterID
						   ,@v_vchDTItemNumber
						   ,@v_vchItemUomID
						   ,@v_vchDTUom)


				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
													+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
													+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
													+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
						SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
													+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
													+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
													+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END
					
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 = 'Warehouse: [' + ISNULL(@v_vchDTBomWarehouse, '') + ']'
													+ ' Owner: [' + ISNULL(@v_vchDTBomOwner, '') + ']' 
													+ ' BOM Item Number: [' + ISNULL(@v_vchDTBomItemNumber, '') + ']'
													+ ' Line No: [' + ISNULL(@v_vchDTLineNo, '') + ']' 
						SELECT @v_vchProcessData4 = 'Item Number: [' + ISNULL(@v_vchDTItemNumber, '') + ']'
													+ ' UOM: [' + ISNULL(@v_vchDTUom, '') + ']'
													+ ' Quantity: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltDTQuantity),0) + ']'
													+ ' User ID: [' + ISNULL(@v_vchDTUserID,'') + ']'
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END 

				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_bom_detail SET processing_status = 'COMPLETED' WHERE bom_detail_id = @v_vchHostBomDetailID
				     
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD BOM Item Number Completed'   

			END  
		ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchBomDetailID IS NOT NULL
			BEGIN
				/*************UPDATE DATA UOM INTO t_wms_item_uom*************/  
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Check Update of BOM Item Number:['+@v_vchDTItemNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log  
				 
				
				UPDATE [dbo].[t_wms_item_bom_detail]
				   SET [description] = @v_vchDTDescription
					  ,[quantity] = @v_fltDTQuantity
					  ,[item_uom_id] = @v_vchItemUomID
					  ,[uom] = @v_vchUom
					  ,[update_by] = @v_vchDTUserID
					  ,[update_date] = GETDATE()
				 WHERE bom_detail_id = @v_vchBomDetailID
				 
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_bom_detail SET processing_status = 'COMPLETED' WHERE bom_detail_id = @v_vchHostBomDetailID 
				 
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Item UOM Completed'  
			END  
	
		IF  EXISTS (SELECT bom_detail_id FROM t_host_wms_item_bom_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')    
			GOTO BOM_DETAIL_LABEL; 
	END  
    
	/*************************Finished BOM ITEM DETAIL ADD*************************/
	------------------------------------------------------------  
	--  Finished All. Now Exit SPROC   
	------------------------------------------------------------  
	COMMIT_TRANS:
		COMMIT TRANSACTION;
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
--                           WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:   
	ROLLBACK TRANSACTION;

	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  
	
	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
	
	SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'ITEM_BOM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchBomItemNumber,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())
	
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID
	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	ROLLBACK TRANSACTION;
	 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
	-- Future, Add a Log action for inserting into the Process Log
	
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
		@v_vchSqlErrorMessage = ERROR_MESSAGE(),
		@v_intSqlErrorState = ERROR_STATE(),
		@v_intSqlErrorSeverity = ERROR_SEVERITY(),
		@v_intSqlErrorLine = ERROR_LINE(),
		@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
	SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
						+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
						+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
						+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
						+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
	SET  @v_vchProcessData3 = 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '') + ']'
 		
	SET @out_vchErrorCode = @v_intSqlErrorNumber
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage

	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END	
			
	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'ITEM_BOM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchBomItemNumber,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())

	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  

	UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END


GO
