CREATE PROCEDURE [dbo].[usp_ProcessHostItemMaster]  
	@in_vchApplicationID		VARCHAR(40)  = NULL,	--Required  
	@in_vchApplicationName		NVARCHAR(100)= NULL,	--Required  
	@in_vchHostRecordID			VARCHAR(40)	 = NULL,	--Required  
 	@in_vchDevice				NVARCHAR(50) = NULL,	--Required  
	@in_vchUserID				NVARCHAR(25) = NULL,	--Required  
 	@out_vchErrorCode			NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage		NVARCHAR(500) OUTPUT
AS  
BEGIN   
	DECLARE @v_vchApplicationID			NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName				NVARCHAR(30) = 'usp_ProcessHostItemMaster'
	DECLARE @v_intSqlErrorNumber		INTEGER
	DECLARE @v_intSqlErrorLine			INTEGER
	DECLARE @v_intSqlErrorState			INTEGER
	DECLARE @v_intSqlErrorSeverity		INTEGER
	DECLARE @v_vchSqlErrorMessage		NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure		NVARCHAR(200)  
	DECLARE @v_vchProcessData1			NVARCHAR(100)
	DECLARE @v_vchProcessData2			NVARCHAR(100)
	DECLARE @v_vchProcessData3			NVARCHAR(100)
	DECLARE @v_vchProcessData4			NVARCHAR(100)
	DECLARE @v_nErrorNumber				INTEGER
	DECLARE @v_vchMessage				NVARCHAR(500)
	DECLARE @v_nRowCount				INTEGER
	DECLARE @v_intLocale				INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round						INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType				NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel				INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction				NVARCHAR(25) = 'PRINT'	-- PRINT, LOG, 
 	DECLARE @v_vchTableName				NVARCHAR(50)

	-- Local Variables
	DECLARE @v_vchWhMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemUomID				UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemCrossRefID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCategoryID			UNIQUEIDENTIFIER = NULL
 
	-- Table Variables for [t_host_wms_item_master]
	DECLARE @v_vchRecordType			NVARCHAR(10) = NULL   -- Required  
	DECLARE @v_vchProcessingCode		NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchProcessingStatus		NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchItemNumber			NVARCHAR(50) = NULL   -- Required  
	DECLARE @v_vchWarehouse				NVARCHAR(25) = NULL       
	DECLARE @v_vchOwnerCode				NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchDescription			NVARCHAR(200)= NULL   
	DECLARE @v_vchItemCategory			NVARCHAR(50) = NULL   -- Required  
	DECLARE @v_vchLotControl			VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchSNControl				VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchExpiryDateControl		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute1Control		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute2Control		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute3Control		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute4Control		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute5Control		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_intDaysToExpire			INTEGER		 = NULL  	   
	DECLARE @v_intFifoWindow			INTEGER		 = NULL  
	DECLARE @v_fltWHREOrderPoint		FLOAT		 = NULL  
	DECLARE @v_fltWHREOrderQty			FLOAT		 = NULL  
	DECLARE @v_fltCost					FLOAT		 = NULL  
	DECLARE @v_fltPrice					FLOAT		 = NULL  
	DECLARE @v_vchDGCode				NVARCHAR(50) = NULL  
	DECLARE @v_vchInventoryType			NVARCHAR(40) = NULL  
	DECLARE @v_vchIsKit					VARCHAR(3)   = NULL  
	DECLARE @v_vchIsBOM					VARCHAR(3)   = NULL 
	DECLARE @v_vchModel					NVARCHAR(30) = NULL  
	DECLARE @v_vchStyle					NVARCHAR(30) = NULL  
	DECLARE @v_vchColor					NVARCHAR(30) = NULL  
	DECLARE @v_vchSize					NVARCHAR(30) = NULL  
	DECLARE @v_vchCoo					NVARCHAR(30) = NULL
	DECLARE @v_fltMin					FLOAT
	DECLARE	@v_fltMax					FLOAT
	DECLARE @v_vchGrade					NVARCHAR(30) = NULL  
	DECLARE @v_vchUserDef1    			NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef2    			NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef3    			NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef4    			NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef5    			NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef6    			NVARCHAR(50) = NULL  
	DECLARE @v_fltUserDef7    			FLOAT		 = NULL  
	DECLARE @v_fltUserDef8    			FLOAT		 = NULL  
	DECLARE @v_dtUserDef9    			DATETIME	 = NULL  
	DECLARE @v_dtUserDef10    			DATETIME	 = NULL  
	DECLARE @v_vchIsActive    			VARCHAR(3)   = NULL  
	DECLARE @v_vchUserID				NVARCHAR(25) = NULL

	-- Table Variables for [t_host_wms_item_uom]  
	DECLARE @v_vchHostItemUOMIDGUID		UNIQUEIDENTIFIER= NULL
	DECLARE @v_vchUOMItemNumber			NVARCHAR(50)	= NULL -- Required  
	DECLARE @v_vchUOMOwner				NVARCHAR(40)	= NULL -- Required  
	DECLARE @v_vchUOMUom				NVARCHAR(20)	= NULL -- Required
	DECLARE @v_vchUOMPrimaryUom			VARCHAR(3)		= NULL    
	DECLARE @v_fltUOMConversionFactor	FLOAT			= NULL  
	DECLARE @v_vchUOMPicking			VARCHAR(3)		= NULL  
	DECLARE @v_vchUOMShipping			VARCHAR(3)		= NULL  
	DECLARE @v_vchUOMUomPrompt			NVARCHAR(40)	= NULL  
	DECLARE @v_vchUOMDisplayTiHi		VARCHAR(3)		= NULL  
	DECLARE @v_fltUOMTiHiUnitPerLayer	FLOAT			= NULL  
	DECLARE @v_fltUOMTiHiUnitPerUom		FLOAT			= NULL  
	DECLARE @v_vchUOMGtin				NVARCHAR(10)	= NULL  
	DECLARE @v_fltUOMLength				FLOAT			= NULL  
	DECLARE @v_fltUOMWidth				FLOAT			= NULL  
	DECLARE @v_fltUOMHeight				FLOAT			= NULL  
	DECLARE @v_fltUOMWeight				FLOAT			= NULL  
	DECLARE @v_vchUOMIsActive			VARCHAR(3)		= NULL
	DECLARE @v_vchUOMUserID				NVARCHAR(10)	= NULL   
	DECLARE @v_intUOMSequence			INT				= NULL  
	DECLARE @v_vchUOMPickingClass		NVARCHAR(40)	= NULL
	DECLARE @v_vchUOMPutwayClass		NVARCHAR(40)	= NULL
	DECLARE @v_vchUOMPickingClassRuleName NVARCHAR(50)	= NULL
	 
	-- Table Variables for [t_host_wms_item_crossref]
	DECLARE @v_vchHostCrossRefIDGUID	VARCHAR(40)		= NULL    
	DECLARE @v_vchXREFItemNumber		NVARCHAR(50)	= NULL  -- Required  
	DECLARE @v_vchXREFOwner				NVARCHAR(40)	= NULL  -- Required  
	DECLARE @v_vchXREFAltItemNumber		NVARCHAR(50)	= NULL  -- Required  
	DECLARE @v_vchXREFIsActive			VARCHAR(3)		= NULL   
	DECLARE @v_vchXREFUserID			NVARCHAR(10)	= NULL  	  
	
	-- Declare your table column variables here and use them later on in the trigger.      
	DECLARE @v_vchDefaultPickLocationGUID	UNIQUEIDENTIFIER = NULL   
	DECLARE @v_vchDefaultPickRuleGUID		UNIQUEIDENTIFIER = NULL  
	DECLARE @v_vchDefaultPutRuleGUID		UNIQUEIDENTIFIER = NULL  
    
BEGIN TRY  
	BEGIN TRANSACTION
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log  
        
	SELECT @v_vchRecordType = record_type
		, @v_vchProcessingCode = processing_code  
		, @v_vchProcessingStatus = processing_status
		, @v_vchOwnerCode = owner_id
		, @v_vchWarehouse = wh_id
		, @v_vchItemNumber = item_number
		, @v_vchDescription = [description]  
		, @v_vchItemCategory = item_category 
		, @v_vchLotControl		  = ISNULL([lot_control],'NONE')
		, @v_vchSNControl		  = ISNULL([sn_control],'NONE')
		, @v_vchExpiryDateControl = ISNULL([expiry_date_control],'NONE')
		, @v_vchAttribute1Control = ISNULL([attribute1_control],'NONE')
		, @v_vchAttribute2Control = ISNULL([attribute2_control],'NONE')
		, @v_vchAttribute3Control = ISNULL([attribute3_control],'NONE')
		, @v_vchAttribute4Control = ISNULL([attribute4_control],'NONE')
		, @v_vchAttribute5Control = ISNULL([attribute5_control],'NONE')
		, @v_intDaysToExpire = days_to_expire  
		, @v_intFifoWindow = fifo_window  
		, @v_fltWHREOrderPoint = wh_reorder_point  
		, @v_fltWHREOrderQty = wh_reorder_qty  
		, @v_fltCost = cost  
		, @v_fltPrice = price  
		, @v_vchDGCode = dg_code  
		, @v_vchInventoryType = inventory_type  
		, @v_vchIsKit = ISNULL([is_kit],'NO')
		, @v_vchIsBOM = ISNULL([is_bom],'NO')
		, @v_vchModel = model  
		, @v_vchStyle = style  
		, @v_vchColor = color  
		, @v_vchSize = size  
		, @v_vchGrade = grade  
		, @v_vchCoo = coo
		, @v_fltMax = [max]
		, @v_fltMin = [min]
		, @v_vchUserDef1 = user_def1  
		, @v_vchUserDef2 = user_def2  
		, @v_vchUserDef3 = user_def3  
		, @v_vchUserDef4 = user_def4		--Item Class
		, @v_vchUserDef5 = user_def5		--Item Class
		, @v_vchUserDef6 = user_def6		--Item Class
		, @v_fltUserDef7 = user_def7  
		, @v_fltUserDef8 = user_def8  
		, @v_dtUserDef9 = user_def9
		, @v_dtUserDef10 = user_def10
		, @v_vchIsActive = ISNULL(is_active, 'YES')    
		, @v_vchUserID = [create_by]
	FROM t_host_wms_item_master  
	WHERE host_record_id = @in_vchHostRecordID  
	
	------------------------------------------------------------
	-- Set default value
	------------------------------------------------------------
	SELECT @v_vchLotControl		   = CASE WHEN ISNULL(@v_vchLotControl,'') = '' THEN 'NONE' ELSE @v_vchLotControl END
	SELECT @v_vchSNControl		   = CASE WHEN ISNULL(@v_vchSNControl, '') = '' THEN 'NONE' ELSE @v_vchSNControl END
	SELECT @v_vchExpiryDateControl = CASE WHEN ISNULL(@v_vchExpiryDateControl, '') = '' THEN 'NONE' ELSE @v_vchExpiryDateControl END
	SELECT @v_vchAttribute1Control = CASE WHEN ISNULL(@v_vchAttribute1Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute1Control END
	SELECT @v_vchAttribute2Control = CASE WHEN ISNULL(@v_vchAttribute2Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute2Control END
	SELECT @v_vchAttribute3Control = CASE WHEN ISNULL(@v_vchAttribute3Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute3Control END
	SELECT @v_vchAttribute4Control = CASE WHEN ISNULL(@v_vchAttribute4Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute4Control END
	SELECT @v_vchAttribute5Control = CASE WHEN ISNULL(@v_vchAttribute5Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute5Control END
	SELECT @v_vchIsKit			   = CASE WHEN ISNULL(@v_vchIsKit, '') = '' THEN 'NO' ELSE @v_vchIsKit END
	SELECT @v_vchIsBOM			   = CASE WHEN ISNULL(@v_vchIsBOM, '') = '' THEN 'NO' ELSE @v_vchIsBOM END
	SELECT @v_vchIsActive		   = CASE WHEN ISNULL(@v_vchIsActive, '') = '' THEN 'YES' ELSE @v_vchIsActive END

	----------------------------------------------------------  
	--  Check Nulls for Required Fields  
	--  Item Number, Owner, Item Category, User ID
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    

	IF ISNULL(@v_vchRecordType,'') = '' 
		OR ISNULL(@v_vchProcessingCode,'') = ''
		OR ISNULL(@v_vchProcessingStatus,'') = ''
		OR ISNULL(@v_vchItemNumber,'') = ''
		OR ISNULL(@v_vchOwnerCode,'') = ''
		OR ISNULL(@v_vchItemCategory,'') = ''
		OR ISNULL(@v_vchUserID,'') = ''
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
		SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
							 + ' Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']' 
							 + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
							 + ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']'  
							 + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
		                 
		-- Future, Add a Log action for inserting into the Process Log  
		
		SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
		SET @v_vchLogType = 'IMPORT ERROR'  
		
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
									+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
									+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
		SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
		SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO WRITE_PROCESS_LOG  
	END
    
	------------------------------------------------------------  
	--  Check Valid Record Type Code  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Types'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchRecordType <> 'MASTER')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
			GOTO WRITE_PROCESS_LOG  
		END  
  
	------------------------------------------------------------  
	--  Check Valid Processing Code the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END    
     
	------------------------------------------------------------  
	--  Check Valid Processing Status the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingStatus NOT IN ('PENDING')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END     
  
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	-- Check category in master
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Category'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchCategoryID = category_id FROM t_wms_category WHERE item_category = @v_vchItemCategory
	IF (@v_vchCategoryID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Category ID'  
			-- Future, Add a Log action for inserting into the Process Log    

			------------------------------------------------------------------------  
			--  Insert Category เลย กรณีที่ไม่พบข้อมูล Category ใน WMS  
			------------------------------------------------------------------------  
			SET @v_vchCategoryID = NEWID()  
			INSERT INTO t_wms_category
			(  
				 category_id  
				,item_category  
				,create_by  
			)  
			VALUES  
			(   
				 @v_vchCategoryID  
				,@v_vchItemCategory  
				,@v_vchUserID  
			)  
		END
    
	------------------------------------------------------------  
	--  Get item mater id (GUID)
	------------------------------------------------------------  
	SET @v_vchItemMasterID = NULL;
    SELECT @v_vchItemMasterID = item_master_id FROM t_wms_item 
	WHERE item_number = @v_vchItemNumber
	AND owner_id = @v_vchOwnerID

	SET @v_vchWhMasterID = NULL
    SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @v_vchWarehouse

	-------------------------------------------------------------------------  
	--  Check Data for Add or Update  
	-------------------------------------------------------------------------  
	IF  @v_vchItemMasterID IS NOT NULL AND @v_vchProcessingCode = 'ADD'  
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END

	-------------------------------------------------------------------------  
	-- Check Procession code is update but not found item master.
	-------------------------------------------------------------------------  
	IF  @v_vchProcessingCode = 'UPDATE' AND @v_vchItemMasterID IS NULL
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-IFMAN-045' -- Procession code is update but not found item master.
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
									+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
									+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
		SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
		SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
		GOTO WRITE_PROCESS_LOG 
	END

	------------------------------------------------------------  
	--  Processing for 'DELETE' the Item.  
	------------------------------------------------------------  
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_vchItemMasterID IS NOT NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Delete Processing for Item:['+@v_vchItemNumber+']'  
					-- Future, Add a Log action for inserting into the Process Log  
			
					DELETE FROM t_wms_item_crossref WHERE item_master_id = @v_vchItemMasterID
					DELETE FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID        
					DELETE FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID
					DELETE FROM t_wms_item WHERE item_master_id = @v_vchItemMasterID 

					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
					GOTO COMMIT_TRANS;
				END
			ELSE
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Not found item'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-062' -- Not found item for delete
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
												+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
					SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
		END

	------------------------------------------------------------  
	--  Check the Item for a ADD duplicate.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Item'  
	-- Future, Add a Log action for inserting into the Process Log
      
	IF @v_vchProcessingCode = 'ADD' AND @v_vchItemMasterID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Item:['+@v_vchItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  
			 
			SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
			SET @v_vchLogType = 'IMPORT WARNING'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
										+ ' Is Active: ['+ISNULL(@v_vchIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END
	ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchItemMasterID IS NULL
		BEGIN
			------------------------------------------------------------
			-- Processing for 'ADD' the Item .  
			-- This section should be runing for an 'ADD' with no   
			-- duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing ADD for Item:[' + @v_vchItemNumber + ']'  
			-- Future, Add a Log action for inserting into the Process Log  

			SELECT @v_vchItemMasterID = NEWID()
			INSERT INTO t_wms_item
				(   item_master_id   
				  , item_number  
				  , owner_id  
				  , description  
				  , category_id  
				  , lot_control  
				  , sn_control  
				  , expiry_date_control  
				  , attribute1_control
				  , attribute2_control
				  , attribute3_control
				  , attribute4_control
				  , attribute5_control
				  , days_to_expire  
				  , fifo_window  
				  , wh_reorder_point  
				  , wh_reorder_qty  
				  , cost       
				  , price  
				  , dg_code  
				  , inventory_type  
				  , is_kit 
				  , is_bom   
				  , model  
				  , style      
				  , color  
				  , size  
				  , coo
				  , [max_qty]
				  , [min_qty]
				  , grade     
				  , user_def1  
				  , user_def2  
				  , user_def3  
				  , user_def4  
				  , user_def5  
				  , user_def6  
				  , user_def7  
				  , user_def8  
				  , user_def9  
				  , user_def10  
				  , is_active  
				  , create_date  
				  , create_by  
				)  
			VALUES 
				(   @v_vchItemMasterID  
				  , @v_vchItemNumber
				  , @v_vchOwnerID
				  , @v_vchDescription  
				  , @v_vchCategoryID 
				  , @v_vchLotControl  
				  , @v_vchSNControl  
				  , @v_vchExpiryDateControl  
				  , @v_vchAttribute1Control
				  , @v_vchAttribute2Control
				  , @v_vchAttribute3Control
				  , @v_vchAttribute4Control
				  , @v_vchAttribute5Control
				  , @v_intDaysToExpire  
				  , @v_intFifoWindow  
				  , @v_fltWHREOrderPoint  
				  , @v_fltWHREOrderQty  
				  , @v_fltCost  
				  , @v_fltPrice  
				  , @v_vchDGCode  
				  , @v_vchInventoryType  
				  , @v_vchIsKit 
				  , @v_vchIsBOM 
				  , @v_vchModel  
				  , @v_vchStyle  
				  , @v_vchColor  
				  , @v_vchSize
				  , @v_vchCoo  
				  , @v_fltMax
				  , @v_fltMin
				  , @v_vchGrade
				  , @v_vchUserDef1  
				  , @v_vchUserDef2  
				  , @v_vchUserDef3  
				  , @v_vchUserDef4  
				  , @v_vchUserDef5  
				  , @v_vchUserDef6  
				  , @v_fltUserDef7  
				  , @v_fltUserDef8  
				  , @v_dtUserDef9
				  , @v_dtUserDef10
				  , @v_vchIsActive  
				  , GETDATE()  
				  , @v_vchUserID  
				)
			
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
					SELECT @v_vchProcessData4 = 'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
					SELECT @v_vchProcessData4 = 'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END

			---------------------------------------------------   
			-- Update Process Status = COMPLETED  
			---------------------------------------------------  
			UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing ADD Item Master Completed'   
			-- Future, Add a Log action for inserting into the Process Log  

			---------------------------------------------------  
			--  Set into Default Warehouse Table  
			---------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing Default Warehouse Started'   
			-- Future, Add a Log action for inserting into the Process Log  

			-----------------------------------------------------------------------------------  
			--  If no Default Warehouse then set to ALL Warehouses   
			--  If the Warehouse Value sent into the Item Record is NULL then set to ALL Warehouses   
			-----------------------------------------------------------------------------------  
			IF @v_vchWhMasterID IS NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inserting into Warehouse Item Table'   
					IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  select 'Field List'+  
							   +'Item Number:['+ISNULL(@v_vchItemNumber, '')+']'  
							   +'Owner:['+ISNULL(@v_vchOwnerCode, '')+']'  
							   +'Warehouse:['+ISNULL(@v_vchWarehouse, '')+']' 
							   +'Is Active:[' +ISNULL(@v_vchIsActive, '')+']'  
							   +'User ID:['+ISNULL(@v_vchUserID, '')+']'  
							  
					INSERT INTO t_wms_wh_item 
						( wh_master_id
						  , item_master_id
						  , pick_location
						  , interface_to_host
						  , is_active
						  , create_by
						  , create_date
						)					
						SELECT wh_master_id
							, @v_vchItemMasterID
							, (SELECT location_id FROM t_wms_location WHERE t_wms_location.wh_master_id = t_wms_wh.wh_master_id   AND location = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_LOCATION',wh_id,'WH_CONTROL'))  
							, 'YES'  
							, 'YES'
							, @v_vchUserID
							, GETDATE()  
						FROM t_wms_wh
						WHERE is_active = 'YES'
				END  
			ELSE 
				BEGIN
					------------------------------------------------------------  
					--  Only Insert the Single Warehouse  
					------------------------------------------------------------  
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Inserting Item for Warehouse:' + @v_vchWarehouse   
					-- Future, Add a Log action for inserting into the Process Log  

					--------------------------------------------------------------------  
					--  Get the Default Pick Location to insert into the Item WH Table  
					--------------------------------------------------------------------  
					SELECT TOP 1 @v_vchDefaultPickLocationGUID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_LOCATION',@v_vchWarehouse,'WH_CONTROL')
					INSERT INTO t_wms_wh_item 
						( wh_master_id
						  , item_master_id
						  , pick_location
						  , interface_to_host
						  , is_active
						  , create_by
						  , create_date
						)  
						VALUES
						( @v_vchWhMasterID
						  , @v_vchItemMasterID
						  , @v_vchDefaultPickLocationGUID
						  , 'YES'
						  , 'YES'
						  , @v_vchUserID
						  , GETDATE()
						)  
				END

			-----------------------------------------------------------------------------------  
			--  Check UOM Host Table  If no record is found then error 
			-----------------------------------------------------------------------------------  
			IF  NOT EXISTS (SELECT uom_id FROM dbo.t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-43' -- Item with out uom
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
												+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
					SELECT @v_vchProcessData4 = ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
												+ ' Is Active: ['+ISNULL(@v_vchIsActive,'') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG

					/* Comment 23/07/2015 : เนื่องจากต้องแสดง Error แทน กรณีที่ไม่มีการส่ง UOM มา ไม่ต้อง Default UOM ให้
					------------------------------------------------------------  
					--  Enter a Default Record for Item UOM  
					------------------------------------------------------------  
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UOM Default Start'   
					-- Future, Add a Log action for inserting into the Process Log  

					IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  SELECT 'Field List'+  
						 +' Item Number:['+ISNULL(@v_vchItemNumber, '')+']'  
						 +' Owner:['+ISNULL(@v_vchOwner, '')+']'  
						 +' Item Default UOM:['+ISNULL(@v_vchDefaultUOM, '')+']'  
						 +' Primary UOM Flag['+ISNULL(@v_vchDefaultPrimaryUOM, '')+']'  
						 +' Picking UOM Flag['+ISNULL(@v_vchDefaultPickingUOM, '')+']'  
						 +' Shipping UOM Flag['+ISNULL(@v_vchDefaultShippingUOM, '')+']'  
						 +' Is Active:[' +ISNULL(@v_vchIsActive, '')+']'  
						 +' User ID:['+ISNULL(@v_vchUserID, '')+']'  

					------------------------------------------------------------  
					--  Get the Default Picking Class Rule  
					------------------------------------------------------------               
					SELECT @v_vchDefaultPickRuleGUID = rule_id FROM t_wms_rule   
					WHERE rule_code = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_RULE',@v_vchWHID,'WH_CONTROL')
					AND type = 'PICK_RULE'
					
					------------------------------------------------------------  
					--  Get the Default Putaway Class Rule  
					------------------------------------------------------------               
					SELECT @v_vchDefaultPutRuleGUID = rule_id FROM t_wms_rule   
					WHERE rule_code = [dbo].[usf_GetRuleValue] ('DEFAULT_PUT_RULE',@v_vchWHID,'WH_CONTROL')   
					AND type = 'PUTAWAY_RULE'  

					INSERT INTO t_wms_item_uom
					(   item_master_id  
					  , uom  
					  , conversion_factor  
					  , primary_uom  
					  , picking_uom  
					  , uom_prompt  
					  , shipping_uom  
					  , picking_class  
					  , putaway_class  
					  , is_active  
					  , create_by  
					)  
					VALUES
					(   @v_vchItemIDGUID  
					  , @v_vchDefaultUOM  
					  , @v_fltDefaultConversionFactor  
					  , @v_vchDefaultPrimaryUOM  
					  , @v_vchDefaultPickingUOM  
					  , @v_vchDefaultUOMPrompt  
					  , @v_vchDefaultShippingUOM  
					  , 'A8C1C607-9ECB-4108-A9BB-55E2EAF6FEA8'  
					  , @v_vchDefaultPutRuleGUID  
					  , @v_vchIsActive  
					  , @v_vchUserID  
					)
					*/
				END
		END
	ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchItemMasterID IS NOT NULL
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE the Item Master.'  
			------------------------------------------------------------
			--ถ้าพบของใน Inventory จะไม่ Update Item Control ทั้งหมดเพราะมีผลกับ data ใน Inventory
			------------------------------------------------------------
			IF EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
					   INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
					   INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
					   WHERE item.item_master_id = @v_vchItemMasterID)
				BEGIN
					UPDATE t_wms_item SET owner_id = @v_vchOwnerID
						, description = @v_vchDescription  
						, category_id = @v_vchCategoryID
						, days_to_expire = @v_intDaysToExpire  
						, fifo_window = @v_intFifoWindow  
						, wh_reorder_point = @v_fltWHREOrderPoint  
						, wh_reorder_qty = @v_fltWHREOrderQty  
						, cost = @v_fltCost  
						, price = @v_fltPrice  
						, dg_code = @v_vchDGCode  
						, inventory_type = @v_vchInventoryType  
						, is_kit = @v_vchIsKit  
						, is_bom = @v_vchIsBOM
						, model = @v_vchModel  
						, style = @v_vchStyle  
						, color = @v_vchColor  
						, size = @v_vchSize  
						, coo = @v_vchCoo
						, [max_qty] = @v_fltMax
						, [min_qty] = @v_fltMin
						, grade = @v_vchGrade
						, user_def1 = @v_vchUserDef1  
						, user_def2 = @v_vchUserDef2  
						, user_def3 = @v_vchUserDef3  
						, user_def4 = @v_vchUserDef4  
						, user_def5 = @v_vchUserDef5  
						, user_def6 = @v_vchUserDef6  
						, user_def7 = @v_fltUserDef7  
						, user_def8 = @v_fltUserDef8  
						, user_def9 = @v_dtUserDef9  
						, user_def10 = @v_dtUserDef10 
						, is_active = @v_vchIsActive 
						, update_by = @v_vchUserID
						, update_date = GETDATE()
					WHERE item_master_id = @v_vchItemMasterID
				END
			ELSE
				BEGIN
					UPDATE t_wms_item SET owner_id = @v_vchOwnerID
						, description = @v_vchDescription  
						, category_id = @v_vchCategoryID
						, lot_control = @v_vchLotControl  
						, sn_control = @v_vchSNControl  
						, expiry_date_control = @v_vchExpiryDateControl  
						, attribute1_control = @v_vchAttribute1Control
						, attribute2_control = @v_vchAttribute2Control
						, attribute3_control = @v_vchAttribute3Control
						, attribute4_control = @v_vchAttribute4Control
						, attribute5_control = @v_vchAttribute5Control
						, days_to_expire = @v_intDaysToExpire  
						, fifo_window = @v_intFifoWindow  
						, wh_reorder_point = @v_fltWHREOrderPoint  
						, wh_reorder_qty = @v_fltWHREOrderQty  
						, cost = @v_fltCost  
						, price = @v_fltPrice  
						, dg_code = @v_vchDGCode  
						, inventory_type = @v_vchInventoryType  
						, is_kit = @v_vchIsKit  
						, is_bom = @v_vchIsBOM
						, model = @v_vchModel  
						, style = @v_vchStyle  
						, color = @v_vchColor  
						, size = @v_vchSize  
						, coo = @v_vchCoo
						, [max_qty] = @v_fltMax
						, [min_qty] = @v_fltMin
						, grade = @v_vchGrade
						, user_def1 = @v_vchUserDef1  
						, user_def2 = @v_vchUserDef2  
						, user_def3 = @v_vchUserDef3  
						, user_def4 = @v_vchUserDef4  
						, user_def5 = @v_vchUserDef5  
						, user_def6 = @v_vchUserDef6  
						, user_def7 = @v_fltUserDef7  
						, user_def8 = @v_fltUserDef8  
						, user_def9 = @v_dtUserDef9  
						, user_def10 = @v_dtUserDef10 
						, is_active = @v_vchIsActive 
						, update_by = @v_vchUserID
						, update_date = GETDATE()
					WHERE item_master_id = @v_vchItemMasterID
				END 			 

			--  We should put error checking here if the TRY ...Catch does not work or we use this  
			--  trigger on an older version of MS SQL Server  
			UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Update Item Master Complete'  
		END  

	/*************************Finished ITEM MASTER ADD*************************/  
	------------------------------------------------------------  
	--  Process the Item UOM  
	------------------------------------------------------------  
	IF  EXISTS (SELECT uom_id FROM dbo.t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
	BEGIN
		------------------------------------------------------------  
		--  Process the UOM Table  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Item UOM Started'   
	  
		ITEM_UOM_LABEL:
		-------------------------------------------------------
		-- Clear Value before set the value to variable
		-------------------------------------------------------
		SET @v_vchTableName = 't_host_wms_item_uom'
		SET @v_vchRecordType		 = NULL
		SET	@v_vchProcessingCode	 = NULL
		SET	@v_vchProcessingStatus	 = NULL
		SET @v_vchHostItemUOMIDGUID	 = NULL
		SET @v_vchUOMItemNumber		 = NULL
		SET @v_vchUOMOwner			 = NULL
		SET @v_vchUOMUom			 = NULL
		SET @v_vchUOMPrimaryUom		 = NULL
		SET @v_fltUOMConversionFactor= NULL
		SET @v_vchUOMPicking		 = NULL
		SET @v_vchUOMShipping		 = NULL
		SET @v_vchUOMUomPrompt		 = NULL
		SET @v_vchUOMDisplayTiHi	 = NULL
		SET @v_fltUOMTiHiUnitPerLayer= NULL
		SET @v_fltUOMTiHiUnitPerUom	 = NULL
		SET @v_vchUOMGtin			 = NULL
		SET @v_fltUOMLength			 = NULL
		SET @v_fltUOMWidth			 = NULL
		SET @v_fltUOMHeight			 = NULL
		SET @v_fltUOMWeight			 = NULL
		SET @v_vchUOMIsActive		 = NULL
		SET @v_vchUOMUserID			 = NULL
		SET @v_intUOMSequence		 = NULL
		SET @v_vchUOMPickingClass	 = NULL

		------------------------------------------------------------  
		-- Step 1 Read from the Host UOM TABLE (t_host_wms_item_uom)  
		------------------------------------------------------------  		
		SELECT TOP 1 @v_vchHostItemUOMIDGUID = [uom_id]
			,@v_vchRecordType			= [record_type]
			,@v_vchProcessingCode		= [processing_code]
			,@v_vchProcessingStatus		= [processing_status]
			,@v_vchUOMItemNumber		= [item_number]
			,@v_vchUOMOwner				= [owner_id]
			,@v_vchUOMUom				= [uom]
			,@v_vchUOMPrimaryUom		= [primary_uom]
			,@v_fltUOMConversionFactor	= [conversion_factor]
			,@v_vchUOMPicking			= [picking_uom]
			,@v_vchUOMShipping			= [shipping_uom]
			,@v_vchUOMUomPrompt			= [uom_prompt]
			,@v_vchUOMDisplayTiHi		= [display_ti_hi]
			,@v_fltUOMTiHiUnitPerLayer	= [ti_hi_unit_per_layer]
			,@v_fltUOMTiHiUnitPerUom	= [ti_hi_layers_per_uom]
			,@v_vchUOMGtin				= [gtin]
			,@v_fltUOMLength			= [length]
			,@v_fltUOMWidth				= [width]
			,@v_fltUOMHeight			= [height]
			,@v_fltUOMWeight			= [weight]  
			,@v_intUOMSequence			= [sequence]
			,@v_vchUOMIsActive			= [is_active]
			,@v_vchUOMUserID			= [create_by] 
			,@v_vchUOMPickingClass		= [picking_class]
		FROM t_host_wms_item_uom
		WHERE host_record_id = @in_vchHostRecordID 
		AND processing_status = 'PENDING'
		ORDER BY primary_uom,uom_id
	 
		----------------------------------------------------------  
		--  Check Nulls for Required Fields  
		----------------------------------------------------------  
		IF ISNULL(@v_vchRecordType,'') =''  
			OR ISNULL(@v_vchProcessingCode,'') =''  
			OR ISNULL(@v_vchProcessingStatus,'') =''
			OR ISNULL(@v_vchUOMItemNumber,'') =''
			OR ISNULL(@v_vchUOMOwner,'') =''
			OR ISNULL(@v_vchUOMUom,'') =''
			OR ISNULL(@v_vchUOMUomPrompt,'') ='' 
			OR ISNULL(@v_vchUOMUserID,'') =''
			OR ISNULL(@v_fltUOMConversionFactor,0) = 0 
			BEGIN
				------------------------------------------------------------  
				--  Missing Required Fields   
				------------------------------------------------------------  
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
				IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
				SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
									 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
									 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
									 + ' Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']' 
									 + ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']'
									 + ' User ID: ['+ISNULL(@v_vchUOMUserID, '') + ']'   
		                 
				-- Future, Add a Log action for inserting into the Process Log  
		
				SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
				SET @v_vchLogType = 'IMPORT ERROR'  
		
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
				SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: ['+ISNULL(@v_vchUOMUserID, '') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END

		------------------------------------------------------------  
		-- Check Valid Processing Code  
		------------------------------------------------------------  
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code the Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG
			END
	 
		------------------------------------------------------------  
		-- Check Valid Processing Status  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status the Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  
			 
				SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG
			END
	  
		------------------------------------------------------------  
		-- Check for Valid Owner  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner (Item UOM)'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchOwnerID = NULL
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchUOMOwner AND is_active = 'YES'
		IF (@v_vchOwnerID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item UOM)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG 
			END
		
		------------------------------------------------------------  
		--  Get Item UOM ID, Item Master ID
		------------------------------------------------------------
		SET @v_vchItemMasterID       = NULL
		SELECT @v_vchItemMasterID = item.item_master_id
		FROM t_wms_item AS item
 		WHERE item.item_number = @v_vchUOMItemNumber
		AND item.owner_id = @v_vchOwnerID

		------------------------------------------------------------  
		-- Check for Valid Item  
		------------------------------------------------------------
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Item (Item UOM)'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchItemMasterID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-015' -- Invalid Item Number
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG 
			END

		SET @v_vchItemUomID = NULL
		SELECT @v_vchItemUomID = uom.item_uom_id
		FROM  t_wms_item_uom AS uom
		WHERE uom.item_master_id = @v_vchItemMasterID
		AND uom.uom = @v_vchUOMUom
		
		------------------------------------------------------------
		--Check uom can only 1 uom to Primary UOM
		------------------------------------------------------------
		IF EXISTS (SELECT item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND primary_uom = 'YES' AND uom <> @v_vchUOMUom) AND @v_vchUOMPrimaryUom = 'YES'
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'The primary uom has 1 uom only.'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-061' -- The primary uom has 1 uom only.
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code [' + @out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG 
			END

		-------------------------------------------------------------------------  
		--  Check Data for Add or Update  
		-------------------------------------------------------------------------  
		IF @v_vchItemUomID IS NOT NULL AND @v_vchProcessingCode = 'ADD'  
			BEGIN
				SET @v_vchProcessingCode = 'UPDATE'
			END
		
		-------------------------------------------------------------------------  
		-- Check Procession code is update but not found item master.
		-------------------------------------------------------------------------  
		IF  @v_vchProcessingCode = 'UPDATE' AND @v_vchItemUomID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-049' -- Procession code is update but not found UOM master.
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
			GOTO WRITE_PROCESS_LOG 
		END

		------------------------------------------------------------  
		--  Processing for 'DELETE' the Item UOM.  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing the Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode = 'DELETE'  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Delete Processing for UOM:['+@v_vchUOMUom+']'  
			-- Future, Add a Log action for inserting into the Process Log     
			
			IF @v_vchItemUomID IS NOT NULL
				BEGIN
					---------------------------------------------------   
					-- DELETE ITEM CROSSREF FROM WMS TABLE
					---------------------------------------------------
					DELETE FROM t_wms_item_uom WHERE item_uom_id = @v_vchItemUomID
					 
					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
					 
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete Item UOM Completed'  
					 
					------------------------------------------------------------------------------
					-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
					------------------------------------------------------------------------------
					IF  EXISTS (SELECT uom_id FROM t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')
						BEGIN
							GOTO ITEM_UOM_LABEL;
						END
					ELSE
						BEGIN
							GOTO NEXT_CROSS_REF;
						END
				END
			ELSE
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item UOM)'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid Order Detail - Item UOM Does Not Exist  
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
												+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
												+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
												+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
					SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
												+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
												+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
		END
	  
		------------------------------------------------------------  
		--  Get the Default Picking Rule  
		------------------------------------------------------------ 
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Get the default picking rule'  
		-- Future, Add a Log action for inserting into the Process Log  
            
		SET @v_vchUOMPickingClassRuleName = NULL
		IF (@v_vchUOMPickingClass = 'FIFO')
			BEGIN
				SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_FIFO'
			END
		ELSE IF (@v_vchUOMPickingClass = 'FEFO')
			BEGIN
				SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_FEFO'
			END
		ELSE IF (@v_vchUOMPickingClass = 'LOCATION')
			BEGIN
				SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_PICK_LOCATION'
			END
		ELSE
			BEGIN
				SELECT @v_vchUOMPickingClassRuleName = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_RULE',NULL,'WH_CONTROL')   
			END

		SELECT @v_vchDefaultPickRuleGUID = rule_id FROM t_wms_rule WHERE rule_code = @v_vchUOMPickingClassRuleName AND type = 'PICK_RULE'
 
		------------------------------------------------------------  
		--  Get the Default Putaway Rule  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Get the default putaway rule'  
		-- Future, Add a Log action for inserting into the Process Log  
		             
		SELECT @v_vchDefaultPutRuleGUID = rule_id FROM t_wms_rule WHERE rule_code = [dbo].[usf_GetRuleValue] ('DEFAULT_PUT_RULE',NULL,'WH_CONTROL') AND type = 'PUTAWAY_RULE'  

		-------------------------------------------------------------------------  
		--  Check Data for Add or Update  
		-------------------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Check data for processing status ADD or Update'  
		-- Future, Add a Log action for inserting into the Process Log 
		 
		------------------------------------------------------------  
		-- 5. Check for No Duplicate ITEM UOM  
		------------------------------------------------------------  
		IF @v_vchProcessingCode = 'ADD' AND @v_vchItemUomID IS NOT NULL
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Duplicate Item:['+@v_vchUOMItemNumber+']'  
																		   +' UOM:['+ISNULL(@v_vchUOMUom, '')+']'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-024' -- Duplicate Item UOM  
				SET @v_vchLogType = 'IMPORT WARNING'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG 
			END  
		ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchItemUomID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting insert data into the Item UOM'  
					
				/*************INSERT DATA UOM INTO t_wms_item_uom*************/  
				INSERT INTO t_wms_item_uom 
				(   item_master_id  
					,uom  
					,primary_uom  
					,conversion_factor  
					,picking_uom  
					,shipping_uom  
					,uom_prompt  
					,picking_class  
					,putaway_class  
					,display_ti_hi  
					,ti_hi_unit_per_layer  
					,ti_hi_layers_per_uom  
					,gtin  
					,length  
					,width  
					,height  
					,weight  
					,sequence
					,is_active  
					,create_date  
					,create_by  
				)  
				VALUES(  
					@v_vchItemMasterID  
					,@v_vchUOMUom  
					,@v_vchUOMPrimaryUom
					,@v_fltUOMConversionFactor  
					,@v_vchUOMPicking  
					,@v_vchUOMShipping  
					,@v_vchUOMUomPrompt  
					,@v_vchDefaultPickRuleGUID  
					,@v_vchDefaultPutRuleGUID  
					,@v_vchUOMDisplayTiHi  
					,@v_fltUOMTiHiUnitPerLayer  
					,@v_fltUOMTiHiUnitPerUom  
					,@v_vchUOMGtin   
					,@v_fltUOMLength   
					,@v_fltUOMWidth    
					,@v_fltUOMHeight    
					,@v_fltUOMWeight    
					,@v_intUOMSequence
					,@v_vchUOMIsActive  
					,GETDATE()  
					,@v_vchUOMUserID  
				)  
				
				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']' 
						SELECT @v_vchProcessData4 = ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
													+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END
      
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']' 
						SELECT @v_vchProcessData4 =  ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
													+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']'  
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END

				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
				     
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Item UOM Completed'   

			END  
		ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchItemUomID IS NOT NULL
			BEGIN
				/*************UPDATE DATA UOM INTO t_wms_item_uom*************/  
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Check Update of UOM:['+@v_vchUOMUom+']'  
				-- Future, Add a Log action for inserting into the Process Log  
				 
				UPDATE t_wms_item_uom SET
				    primary_uom =  @v_vchUOMPrimaryUom  
				   ,conversion_factor = @v_fltUOMConversionFactor  
				   ,picking_uom = @v_vchUOMPicking   
				   ,shipping_uom = @v_vchUOMShipping    
				   ,uom_prompt = @v_vchUOMUomPrompt  
				   ,picking_class = @v_vchDefaultPickRuleGUID  
				   ,putaway_class = @v_vchDefaultPutRuleGUID  
				   ,display_ti_hi = @v_vchUOMDisplayTiHi  
				   ,ti_hi_unit_per_layer = @v_fltUOMTiHiUnitPerLayer  
				   ,ti_hi_layers_per_uom = @v_fltUOMTiHiUnitPerUom  
				   ,gtin = @v_vchUOMGtin  
				   ,length = @v_fltUOMLength  
				   ,width  = @v_fltUOMWidth  
				   ,height = @v_fltUOMHeight  
				   ,weight = @v_fltUOMWeight  
				   ,sequence = @v_intUOMSequence
				   ,is_active = @v_vchUOMIsActive  
				   ,update_by = @v_vchUOMUserID
				   ,update_date = GETDATE()
				WHERE item_master_id = @v_vchItemMasterID 
				AND item_uom_id = @v_vchItemUomID
				 
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
				 
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Item UOM Completed'  
			END  
	
		IF  EXISTS (SELECT uom_id FROM t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')    
			GOTO ITEM_UOM_LABEL  
	END  
    
	/*************************Finished ITEM UOM ADD*************************/  

	------------------------------------------------------------  
	--  Process the Item Cross Reference  
	------------------------------------------------------------  
	NEXT_CROSS_REF:

	IF  EXISTS (SELECT host_alternate_id FROM t_host_wms_item_crossref WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
	BEGIN  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Item Cross Ref Started'     

		ITEM_CROSS_REF_LABEL:  
		-------------------------------------------------------
		-- Clear Value before set the value to variable
		-------------------------------------------------------
		SET @v_vchTableName = 't_host_wms_item_crossref' 
		SET @v_vchRecordType	     = NULL 
		SET @v_vchProcessingCode	 = NULL
		SET @v_vchProcessingStatus	 = NULL
		SET @v_vchHostCrossRefIDGUID = NULL	
		SET @v_vchXREFItemNumber	 = NULL	
		SET @v_vchXREFOwner			 = NULL	
		SET @v_vchXREFAltItemNumber	 = NULL	
		SET @v_vchXREFIsActive		 = NULL	
		SET @v_vchXREFUserID		 = NULL	
		
		------------------------------------------------------------  
		-- Step 1 Read from the Host UOM TABLE (t_host_wms_item_uom)  
		------------------------------------------------------------  
		SELECT TOP 1 @v_vchHostCrossRefIDGUID = host_alternate_id  
			, @v_vchRecordType = record_type  
			, @v_vchProcessingCode = processing_code  
			, @v_vchProcessingStatus = processing_status  
			, @v_vchXREFItemNumber = item_number   
			, @v_vchXREFOwner = owner_id  
			, @v_vchXREFAltItemNumber = alternate_item_number  
			, @v_vchXREFIsActive = is_active  
			, @v_vchXREFUserID = create_by  
		FROM t_host_wms_item_crossref  
		WHERE host_record_id = @in_vchHostRecordID 
		AND processing_status = 'PENDING'  
		ORDER BY host_alternate_id

		----------------------------------------------------------  
		--  Check Nulls for Required Fields  
		----------------------------------------------------------  
		IF @v_vchRecordType IS NULL  
			OR @v_vchProcessingCode IS NULL   
			OR @v_vchProcessingStatus IS NULL
			OR @v_vchXREFItemNumber IS NULL
			OR @v_vchXREFOwner IS NULL
			OR @v_vchXREFAltItemNumber IS NULL 
			OR @v_vchXREFUserID IS NULL
			BEGIN
				------------------------------------------------------------  
				--  Missing Required Fields   
				------------------------------------------------------------  
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
				IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
				SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
									 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
									 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
									 + ' Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']' 
									 + ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
									 + ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'   
		                 
				-- Future, Add a Log action for inserting into the Process Log  
		
				SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
				SET @v_vchLogType = 'IMPORT ERROR'  
		
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt item number: [' + ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END
		------------------------------------------------------------  
		-- Check Valid Processing Code the Item Cross Ref  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code the Item Cross REF'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
				SET @v_vchLogType = 'IMPORT ERROR'
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END  

		------------------------------------------------------------  
		-- Check Valid Processing Status the Item Cross Ref  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status the Item Cross REF'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG   
			END

		------------------------------------------------------------  
		-- Check for Valid Owner  
		------------------------------------------------------------  
		if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner (Item Cross Ref)'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchOwnerID = NULL
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchUOMOwner AND is_active = 'YES'
		IF (@v_vchOwnerID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item Cross Ref)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END   

		------------------------------------------------------------  
		--  Get alternate_id, Item Master ID
		------------------------------------------------------------
		SET @v_vchItemCrossRefID = NULL
		SET @v_vchItemMasterID = NULL
		SELECT @v_vchItemCrossRefID = crossRef.alternate_id
			, @v_vchItemMasterID = item.item_master_id
		FROM t_wms_item AS item  
		LEFT JOIN t_wms_item_crossref AS crossRef ON item.item_master_id = crossRef.item_master_id
		WHERE item.item_number = @v_vchXREFItemNumber   
		AND item.owner_id = @v_vchOwnerID
		AND crossRef.alternate_item_number = @v_vchXREFAltItemNumber
			
		------------------------------------------------------------  
		-- Check for Valid Item  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Item (Item Cross Ref)'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchItemMasterID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item Cross Ref)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-015' -- Invalid Item Number
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END 
		
		------------------------------------------------------------  
		-- Check duplicate alternate number 
		------------------------------------------------------------  
		IF EXISTS (SELECT cref.alternate_id FROM t_wms_item_crossref AS cref  
					LEFT JOIN t_wms_item AS item ON cref.item_master_id = item.item_master_id
					WHERE item.item_number <> @v_vchXREFItemNumber  
					AND cref.alternate_item_number = @v_vchXREFAltItemNumber 
					AND item.owner_id = @v_vchOwnerID)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item Cross Ref)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-LOGMAN-021' -- Invalid Item Number
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END

		-------------------------------------------------------------------------  
		--  Check Data for Add or Update  
		-------------------------------------------------------------------------  
		IF @v_vchItemCrossRefID IS NOT NULL AND @v_vchProcessingCode = 'ADD'  
			BEGIN
				SET @v_vchProcessingCode = 'UPDATE'
			END

		-------------------------------------------------------------------------  
		-- Check Procession code is update but not found item master.
		-------------------------------------------------------------------------  
		IF  @v_vchProcessingCode = 'UPDATE' AND @v_vchItemCrossRefID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-063' -- Procession code is update but not found Item Cross Ref master.
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
			GOTO WRITE_PROCESS_LOG 
		END

		------------------------------------------------------------  
		--  Processing for 'DELETE' the Item Cross Ref.  
		------------------------------------------------------------  
		IF @v_vchProcessingCode = 'DELETE'  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Delete Processing for Alt Item Number:['+@v_vchXREFAltItemNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log     

				IF @v_vchItemCrossRefID IS NOT NULL
					BEGIN
						---------------------------------------------------   
						-- DELETE ITEM CROSSREF FROM WMS TABLE
						--------------------------------------------------- 
						DELETE FROM t_wms_item_crossref WHERE alternate_id = @v_vchItemCrossRefID 

						---------------------------------------------------   
						-- Update Process Status = COMPLETED  
						---------------------------------------------------  
						UPDATE t_host_wms_item_crossref SET processing_status = 'COMPLETED' WHERE host_alternate_id = @v_vchHostCrossRefIDGUID  

						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'DELETE Item Cross Ref Completed'  
						
						-----------------------------------------------------------------------------
						-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
						------------------------------------------------------------------------------
						IF  EXISTS (SELECT host_alternate_id FROM t_host_wms_item_crossref WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND host_alternate_id > @v_vchHostCrossRefIDGUID)  
							BEGIN
								GOTO ITEM_CROSS_REF_LABEL;
							END
						ELSE
							BEGIN
								GOTO COMMIT_TRANS;
							END
					END
				ELSE
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item Cross Ref)'  
						-- Future, Add a Log action for inserting into the Process Log  

						SET @out_vchErrorCode = 'ERROR-IFMAN-038' -- INVALID DETAIL - ALTERNATE ITEM NUMBER DOES NOT EXIST 
						SET @v_vchLogType = 'IMPORT ERROR'  
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
													+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
													+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
						SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
													+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
						SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
													+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG  
					END
			END

		------------------------------------------------------------  
		-- 5. Check for No Duplicate Alternate Item Numbers  
		------------------------------------------------------------ 
		IF @v_vchProcessingCode = 'ADD' AND @v_vchItemCrossRefID IS NOT NULL
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Duplicate Item:['+@v_vchXREFItemNumber+']'  
																		  + ' Alt Item Number:['+ISNULL(@v_vchXREFAltItemNumber, '')+']'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-26' -- Duplicate Alternate Item Number  
				SET @v_vchLogType = 'IMPORT WARNING'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
											+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
				SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
											+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG  
			END  
		ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchItemCrossRefID IS NULL
			BEGIN
				/********INSERT DATA ITEM CROSS REF INTO t_wms_item_crossref********/   
				SET @v_vchItemUomID = NULL 
				SELECT @v_vchItemUomID = item_uom_id FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID 
				AND primary_uom = 'YES'
				AND is_active = 'YES'

				IF @v_vchItemUomID IS NULL
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item UOM)'  
						-- Future, Add a Log action for inserting into the Process Log  

						SET @out_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid Order Detail - Item UOM Does Not Exist  
						SET @v_vchLogType = 'IMPORT ERROR'  
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
													+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
													+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
						SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']'
													+ ' Alt Item Number: ['+ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
						SELECT @v_vchProcessData4 =   ' User ID: ['+ISNULL(@v_vchXREFUserID, '') + ']'
													+ ' Is Active: ['+ISNULL(@v_vchXREFIsActive,'') + ']'
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG  
					END


				INSERT INTO t_wms_item_crossref
					(  item_master_id  
					  ,alternate_item_number
					  ,item_uom_id
					  ,is_active  
					  ,create_date  
					  ,create_by
					)  
				VALUES
					(  @v_vchItemMasterID
					  ,@v_vchXREFAltItemNumber
					  ,@v_vchItemUomID 
					  ,@v_vchXREFIsActive  
					  ,GETDATE()  
					  ,@v_vchXREFUserID         
					)  

				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']' 
						SELECT @v_vchProcessData4 = ' Alt Item Number: [' + ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
													+ ' Is Active: [' + ISNULL(@v_vchXREFIsActive, '') + ']' 
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END
      
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
													+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
													+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
						SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchXREFItemNumber, '') + ']'
													+ ' Owner: ['+ISNULL(@v_vchXREFOwner, '') + ']' 
						SELECT @v_vchProcessData4 = ' Alt Item Number: [' + ISNULL(@v_vchXREFAltItemNumber, '') + ']' 
													+ ' Is Active: [' + ISNULL(@v_vchXREFIsActive, '') + ']'  
						SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						GOTO WRITE_PROCESS_LOG
					END

				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_crossref SET processing_status = 'COMPLETED' WHERE host_alternate_id = @v_vchHostCrossRefIDGUID  

				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'ADD Item Cross Ref Completed'  
			END  
		ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchItemCrossRefID IS NOT NULL
			BEGIN
				/********UPDATE DATA ITEM CROSS REF INTO t_wms_item_crossref********/  
				 
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Update of Alt Item Number:['+@v_vchXREFItemNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log  

				UPDATE t_wms_item_crossref SET is_active = @v_vchXREFIsActive 
					,update_by = @v_vchXREFUserID
					,update_date = GETDATE()
				WHERE item_master_id = @v_vchItemMasterID   
				AND alternate_id = @v_vchItemCrossRefID  
				 
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_crossref SET processing_status = 'COMPLETED' WHERE host_alternate_id = @v_vchHostCrossRefIDGUID  
				  
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'UPDATE Item Cross Ref Completed'  
			END

		IF  EXISTS (SELECT host_alternate_id FROM t_host_wms_item_crossref WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND host_alternate_id > @v_vchHostCrossRefIDGUID)  
			GOTO ITEM_CROSS_REF_LABEL; 

		--  Write the SQL Statments to Read the Host Cross Reference TABLE  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing Item Cross Ref Completed'   
	END  

	/***********************Finished ITEM CROSS REF ADD***********************/  

	COMMIT_TRANS: 
		COMMIT TRANSACTION
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
--                           WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:  
	ROLLBACK TRANSACTION  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
	 
	SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
	INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'ITEM_AND_UOM'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchItemNumber,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())

	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_item_uom SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID

	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	ROLLBACK TRANSACTION
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''
		
		SET @out_vchErrorCode = @v_intSqlErrorNumber 
		SET @out_vchErrorMessage = @v_vchSqlErrorMessage

		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
		
		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'ITEM_AND_UOM'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchItemNumber,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())

		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  

		UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_item_uom SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID
END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END



GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostItemMasterForInitial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostItemMasterForInitial]  
	 @out_vchErrorCode	VARCHAR(50) OUTPUT,
	 @out_vchErrorMsg	VARCHAR(500) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
		DECLARE @v_vchApplicationID VARCHAR(40) = 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0'
		DECLARE @v_vchLogType		VARCHAR(50) = 'INTERFACE ERROR'
		DECLARE @c_vchObjName		VARCHAR(50) = 'usp_ProcessHostItemMaster'
		DECLARE @v_vchUserID		VARCHAR(10) = 'SYSTEM'
		DECLARE @v_vchDeviceID		NVARCHAR(25) = 'Host Interface'
		DECLARE @in_vchLocalID		VARCHAR(5) = '1033'

		UPDATE t_host_wms_item_master set create_by = @v_vchUserID WHERE ISNULL(LTRIM(create_by),'') = '' and processing_status = 'PENDING'
		UPDATE t_host_wms_item_uom set create_by = @v_vchUserID WHERE ISNULL(LTRIM(create_by),'') = '' and processing_status = 'PENDING'
		UPDATE t_host_wms_item_crossref set create_by = @v_vchUserID WHERE ISNULL(LTRIM(create_by),'') = '' and processing_status = 'PENDING'

		--Get Item is Pending
		SELECT host_record_id
			,item_number
			,ROW_NUMBER() OVER(PARTITION BY item_number ORDER BY create_date asc) AS rownumber
		INTO #tGetHostItemMaster
		FROM t_host_wms_item_master hItem
		WHERE processing_status = 'PENDING'

		UPDATE t_host_wms_item_master SET processing_status = 'INPROCESS' WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)

		--Insert Item for Insert/Update/Delete
		SELECT *
		INTO #tHostItem
		FROM t_host_wms_item_master
		WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)

		--Check Requier Field
		IF EXISTS (SELECT item_master_id FROM #tHostItem WHERE ISNULL(item_number,'') = '' OR ISNULL(owner_id,'') = '' OR ISNULL(item_category,'') = '')
			BEGIN
				UPDATE t_host_wms_item_master SET processing_status = 'ERROR'
				FROM t_host_wms_item_master tItem
				LEFT JOIN #tHostItem temp ON tItem.host_record_id = temp.host_record_id
				WHERE (ISNULL(temp.item_number,'') = '' OR ISNULL(temp.owner_id,'') = '' OR ISNULL(temp.item_category,'') = '')

				UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
				FROM t_host_wms_item_uom tUOM
				LEFT JOIN #tHostItem temp ON tUOM.host_record_id = temp.host_record_id
				WHERE (ISNULL(temp.item_number,'') = '' OR ISNULL(temp.owner_id,'') = '' OR ISNULL(temp.item_category,'') = '')

				UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
				FROM t_host_wms_item_crossref tCref 
				LEFT JOIN #tHostItem temp ON tCref.host_record_id = temp.host_record_id
				WHERE (ISNULL(temp.item_number,'') = '' OR ISNULL(temp.owner_id,'') = '' OR ISNULL(temp.item_category,'') = '')

				SET @out_vchErrorCode = 'INF_ITEM_REQUIER_FIELD_EMPTY' 
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				INSERT INTO [dbo].[t_com_process_log]
					([app_id]
					,[log_type]
					,[warehouse]
					,[device]
					,[process]
					,[process_datetime]
					,[data_1]
					,[data_2]
					,[data_3]
					,[data_4]
					,[message]
					,[create_date]
					,[create_by])
				SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
					, @v_vchLogType
					, ISNULL(wh_id,'')
					, @v_vchDeviceID
					, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
					, GETDATE()
					, host_record_id
					, item_number
					, item_category
					, owner_id
					, @out_vchErrorMsg
					, GETDATE()
					, ISNULL(LEFT(create_by, 25), 'SYSTEM')
				FROM #tHostItem
				WHERE ISNULL(item_number,'') = '' OR ISNULL(owner_id,'') = '' OR ISNULL(item_category,'') = ''
				GOTO EXIT_LABEL;
			END

		/*--Check Warehouse Master
		IF EXISTS (SELECT item_master_id FROM #tHostItem temp
					LEFT JOIN t_wms_wh wh on temp.wh_id = wh.wh_id
					WHERE ISNULL(temp.wh_id,'') <> ''
					AND wh.wh_master_id IS NULL)
			BEGIN
				UPDATE t_host_wms_item_master SET processing_status = 'ERROR'
				FROM t_host_wms_item_master tItem
				LEFT JOIN #tHostItem temp ON tItem.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_wh wh on temp.wh_id = wh.wh_group
				WHERE ISNULL(temp.wh_id,'') <> ''
				AND wh.wh_master_id IS NULL 

				UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
				FROM t_host_wms_item_uom tUOM
				LEFT JOIN #tHostItem temp ON tUOM.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_wh wh on temp.wh_id = wh.wh_group
				WHERE ISNULL(temp.wh_id,'') <> ''
				AND wh.wh_master_id IS NULL

				UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
				FROM t_host_wms_item_crossref tCref
				LEFT JOIN #tHostItem temp ON tCref.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_wh wh on temp.wh_id = wh.wh_group
				WHERE ISNULL(temp.wh_id,'') <> ''
				AND wh.wh_master_id IS NULL

				SET @out_vchErrorCode = 'INF_INVALID_WAREHOUSE' 
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				INSERT INTO [dbo].[t_com_process_log]
					([app_id]
					,[log_type]
					,[warehouse]
					,[device]
					,[process]
					,[process_datetime]
					,[data_1]
					,[data_2]
					,[data_3]
					,[data_4]
					,[message]
					,[create_date]
					,[create_by])
				SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
					, @v_vchLogType
					, temp.wh_id
					, @v_vchDeviceID
					, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
					, GETDATE()
					, temp.host_record_id
					, temp.item_number
					, temp.item_category
					, temp.owner_id
					, @out_vchErrorMsg
					, GETDATE()
					, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
				FROM #tHostItem temp
				LEFT JOIN t_wms_wh wh on temp.wh_id = wh.wh_group
				WHERE ISNULL(temp.wh_id,'') <> ''
				AND wh.wh_master_id IS NULL 

				GOTO EXIT_LABEL;
			END
		*/

		--Check Owner Master
		
		IF EXISTS (SELECT item_master_id FROM #tHostItem temp
					LEFT JOIN t_wms_owner own on temp.owner_id = own.owner_code
					WHERE own.owner_id IS NULL)
			BEGIN
				UPDATE t_host_wms_item_master SET processing_status = 'ERROR'
				FROM t_host_wms_item_master tItem
				LEFT JOIN #tHostItem temp ON tItem.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_owner own on temp.owner_id = own.owner_code
				WHERE own.owner_id IS NULL 

				UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
				FROM t_host_wms_item_uom tUOM
				LEFT JOIN #tHostItem temp ON tUOM.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_owner own on temp.owner_id = own.owner_code
				WHERE own.owner_id IS NULL

				UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
				FROM t_host_wms_item_crossref tCref
				LEFT JOIN #tHostItem temp ON tCref.host_record_id = temp.host_record_id
				LEFT JOIN t_wms_owner own on temp.owner_id = own.owner_code
				WHERE own.owner_id IS NULL

				SET @out_vchErrorCode = 'INF_INVALID_OWNER' 
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				INSERT INTO [dbo].[t_com_process_log]
					([app_id]
					,[log_type]
					,[warehouse]
					,[device]
					,[process]
					,[process_datetime]
					,[data_1]
					,[data_2]
					,[data_3]
					,[data_4]
					,[message]
					,[create_date]
					,[create_by])
				SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
					, @v_vchLogType
					, ISNULL(temp.wh_id,'')
					, @v_vchDeviceID
					, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
					, GETDATE()
					, temp.host_record_id
					, temp.item_number
					, temp.item_category
					, temp.owner_id
					, @out_vchErrorMsg
					, GETDATE()
					, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
				FROM #tHostItem temp
				LEFT JOIN t_wms_owner own on temp.owner_id = own.owner_code
				WHERE own.owner_id IS NULL
				
				GOTO EXIT_LABEL;
			END

		--Check Item Cate Master : if not have insert master data
		IF EXISTS (SELECT item_master_id FROM #tHostItem temp
					LEFT JOIN t_wms_category cate on temp.item_category = cate.item_category
					WHERE cate.category_id IS NULL)
			BEGIN
				INSERT INTO [dbo].[t_wms_category]
					([category_id]
					,[item_category]
					,[description]
					,[is_active]
					,[create_by]
					,[create_date])
				SELECT DISTINCT NEWID()
					,tCate.item_category
					,tCate.item_category
					,'YES'
					,'SYSTEM'
					,GETDATE()
				FROM (SELECT DISTINCT temp.item_category
					  FROM #tHostItem temp
					  LEFT JOIN t_wms_category cate on temp.item_category = cate.item_category
					  WHERE cate.category_id IS NULL
					  ) tCate
			END

		--Check UOM have 1 row
		IF EXISTS (SELECT item_master_id FROM #tHostItem temp
					LEFT JOIN t_host_wms_item_uom hostUom on temp.host_record_id = hostUom.host_record_id AND hostUom.primary_uom = 'YES'
					WHERE hostUom.host_record_id IS NULL)
			BEGIN
				UPDATE t_host_wms_item_master SET processing_status = 'ERROR'
				FROM t_host_wms_item_master tItem
				LEFT JOIN #tHostItem temp ON tItem.host_record_id = temp.host_record_id
				LEFT JOIN t_host_wms_item_uom hostUom ON temp.host_record_id = hostUom.host_record_id AND hostUom.primary_uom = 'YES'
				WHERE hostUom.host_record_id IS NULL

				UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
				FROM #tHostItem temp 
				LEFT JOIN t_host_wms_item_uom tUOM ON tUOM.host_record_id = temp.host_record_id AND tUOM.primary_uom = 'YES'
				WHERE tUOM.host_record_id IS NULL

				UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
				FROM t_host_wms_item_crossref tCref
				LEFT JOIN #tHostItem temp ON tCref.host_record_id = temp.host_record_id
				LEFT JOIN t_host_wms_item_uom hostUom on temp.host_record_id = hostUom.host_record_id AND hostUom.primary_uom = 'YES'
				WHERE hostUom.host_record_id IS NULL

				SET @out_vchErrorCode = 'INF_ITEM_WITH_OUT_UOM' 
				SET @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
				INSERT INTO [dbo].[t_com_process_log]
					([app_id]
					,[log_type]
					,[warehouse]
					,[device]
					,[process]
					,[process_datetime]
					,[data_1]
					,[data_2]
					,[data_3]
					,[data_4]
					,[message]
					,[create_date]
					,[create_by])
				SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
					, @v_vchLogType
					, ISNULL(temp.wh_id,'')
					, @v_vchDeviceID
					, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
					, GETDATE()
					, temp.host_record_id
					, temp.item_number
					, temp.item_category
					, temp.owner_id
					, @out_vchErrorMsg
					, GETDATE()
					, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
				FROM #tHostItem temp
				LEFT JOIN t_host_wms_item_uom hostUom ON temp.host_record_id = hostUom.host_record_id AND hostUom.primary_uom = 'YES'
				WHERE hostUom.host_record_id IS NULL
				
				GOTO EXIT_LABEL;
			END

-------------------------------------------------------------
	--Insert data from host for insert to wms item master
	SELECT tHost.*
		,(case when item.item_master_id is null then newid() else item.item_master_id end) AS item_master_unique_id
		,own.owner_id AS owner_unique_id
		,cate.category_id as category_unique_id
		,(CASE WHEN tHost.processing_code = 'DELETE' THEN 'DELETE' WHEN item.item_master_id IS NOT NULL THEN 'UPDATE' ELSE 'INSERT' END) AS process_status
	INTO #tProcessItem
	FROM t_host_wms_item_master tHost
	LEFT JOIN t_wms_owner own ON tHost.owner_id = own.owner_code
	LEFT JOIN t_wms_item item ON tHost.item_number = item.item_number AND item.owner_id = own.owner_id		
	LEFT JOIN t_wms_category cate on tHost.item_category = cate.item_category 
	WHERE processing_status = 'INPROCESS'
	AND host_record_id in (SELECT host_record_id FROM #tHostItem)

	BEGIN--DELETE ITEM Master
		BEGIN TRY
			DELETE t_wms_wh_item WHERE item_master_id IN (SELECT item_master_unique_id FROM #tProcessItem WHERE process_status = 'DELETE')
			DELETE t_wms_item_uom WHERE item_master_id IN (SELECT item_master_unique_id FROM #tProcessItem WHERE process_status = 'DELETE')
			DELETE t_wms_item_crossref WHERE item_master_id IN (SELECT item_master_unique_id FROM #tProcessItem WHERE process_status = 'DELETE')
			DELETE t_wms_item WHERE item_master_id IN (SELECT item_master_unique_id FROM #tProcessItem WHERE process_status = 'DELETE')
		END TRY
		BEGIN CATCH
			UPDATE t_host_wms_item_master SET processing_status = 'ERROR'
			FROM t_host_wms_item_master tItem
			WHERE tItem.host_record_id IN (SELECT host_record_id FROM #tProcessItem WHERE process_status = 'DELETE')

			UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
			FROM t_host_wms_item_uom tItem
			WHERE tItem.host_record_id IN (SELECT host_record_id FROM #tProcessItem WHERE process_status = 'DELETE')

			UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
			FROM t_host_wms_item_crossref tItem
			WHERE tItem.host_record_id IN (SELECT host_record_id FROM #tProcessItem WHERE process_status = 'DELETE')

			SET @out_vchErrorCode = ERROR_NUMBER()
			SET @out_vchErrorMsg = ERROR_MESSAGE()
			INSERT INTO [dbo].[t_com_process_log]
				([app_id]
				,[log_type]
				,[warehouse]
				,[device]
				,[process]
				,[process_datetime]
				,[data_1]
				,[data_2]
				,[data_3]
				,[data_4]
				,[message]
				,[create_date]
				,[create_by])
			SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
				, @v_vchLogType
				, ISNULL(temp.wh_id,'')
				, @v_vchDeviceID
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, temp.host_record_id
				, temp.item_number
				, temp.item_category
				, temp.owner_id
				, @out_vchErrorMsg
				, GETDATE()
				, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
			FROM #tProcessItem temp
			WHERE process_status = 'DELETE'
				
			GOTO EXIT_LABEL;
		END CATCH
	END

	BEGIN--INSERT ITEM Master & WH Item Master ID 
		INSERT INTO [dbo].[t_wms_item]
           ([item_master_id]
           ,[owner_id]
           ,[category_id]
           ,[item_number]
           ,[description]
           ,[lot_control]
           ,[sn_control]
           ,[expiry_date_control]
           ,[attribute1_control]
           ,[attribute2_control]
           ,[attribute3_control]
           ,[attribute4_control]
           ,[attribute5_control]
           ,[days_to_expire]
           ,[fifo_window]
           ,[wh_reorder_point]
           ,[wh_reorder_qty]
           ,[min_qty]
           ,[max_qty]
           ,[cost]
           ,[price]
           ,[dg_code]
           ,[inventory_type]
           ,[is_kit]
           ,[is_bom]
           ,[model]
           ,[style]
           ,[color]
           ,[size]
           ,[coo]
           ,[grade]
           ,[user_def1]
           ,[user_def2]
           ,[user_def3]
           ,[user_def4]
           ,[user_def5]
           ,[user_def6]
           ,[user_def7]
           ,[user_def8]
           ,[user_def9]
           ,[user_def10]
           ,[is_active]
           ,[create_by]
           ,[create_date] )
		SELECT item_master_unique_id
           ,owner_unique_id
           ,category_unique_id
           ,item_number
           ,description
           ,CASE WHEN ISNULL(lot_control,'') = ''		  OR ISNULL([lot_control],'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE lot_control END 
           ,CASE WHEN ISNULL(sn_control,'') = ''		  OR ISNULL(sn_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE sn_control END
           ,CASE WHEN ISNULL(expiry_date_control,'') = '' OR ISNULL(expiry_date_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE expiry_date_control END 
           ,CASE WHEN ISNULL(attribute1_control,'') = ''  OR ISNULL(attribute1_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE attribute1_control END 
           ,CASE WHEN ISNULL(attribute2_control,'') = ''  OR ISNULL(attribute2_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE attribute2_control END 
           ,CASE WHEN ISNULL(attribute3_control,'') = ''  OR ISNULL(attribute3_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE attribute3_control END 
           ,CASE WHEN ISNULL(attribute4_control,'') = ''  OR ISNULL(attribute4_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE attribute4_control END 
           ,CASE WHEN ISNULL(attribute5_control,'') = ''  OR ISNULL(attribute5_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE attribute5_control END 
           ,ISNULL(days_to_expire,0)
           ,fifo_window
           ,wh_reorder_point
           ,wh_reorder_qty
           ,[min]
           ,[max]
           ,cost
           ,price
           ,dg_code
           ,CASE WHEN ISNULL(inventory_type,'') = '' THEN 'YES' ELSE inventory_type END  
           ,CASE WHEN ISNULL(is_kit,'') = '' THEN 'NO' ELSE is_kit END  
           ,CASE WHEN ISNULL(is_bom,'') = '' THEN 'NO' ELSE is_bom END
           ,model
           ,style
           ,color
           ,size
           ,coo
           ,grade
           ,user_def1
           ,user_def2
           ,user_def3
           ,user_def4
           ,user_def5
           ,user_def6
           ,user_def7
           ,user_def8
           ,user_def9
           ,user_def10
           ,CASE WHEN ISNULL(is_active,'') = '' THEN 'YES' ELSE is_active END 
           ,create_by
           ,GETDATE()
		FROM #tProcessItem
		WHERE process_status = 'INSERT'

		--if input warehouse insert for that warehouse
		INSERT INTO [dbo].[t_wms_wh_item]
			   ([wh_item_master_id]
			   ,[wh_master_id]
			   ,[item_master_id]
			   ,[interface_to_host]
			   ,[is_active]
			   ,[create_date]
			   ,[create_by])
		SELECT NEWID()
			,wh.wh_master_id 
			,item_master_unique_id
			,'YES'
			,'YES'
			,GETDATE()
			,#tProcessItem.create_by
		FROM #tProcessItem
		INNER JOIN t_wms_wh wh ON #tProcessItem.wh_id = wh.wh_id
		WHERE ISNULL(#tProcessItem.wh_id,'') <> ''
		AND process_status = 'INSERT'

		--if not input warehouse insert to all warehouse
		INSERT INTO [dbo].[t_wms_wh_item]
			   ([wh_item_master_id]
			   ,[wh_master_id]
			   ,[item_master_id]
			   ,[interface_to_host]
			   ,[is_active]
			   ,[create_date]
			   ,[create_by])
		SELECT NEWID()
			,wh.wh_master_id 
			,item_master_unique_id
			,'YES'
			,'YES'
			,GETDATE()
			,#tProcessItem.create_by
		FROM #tProcessItem
		CROSS JOIN t_wms_wh wh
		WHERE ISNULL(#tProcessItem.wh_id,'') = ''
		AND process_status = 'INSERT'
	END	

	BEGIN--UPDATE ITEM Master
		UPDATE [dbo].[t_wms_item] SET 
			   [category_id] = tProcess.category_unique_id
			  ,[description] = tProcess.description
			  ,[lot_control] = CASE WHEN ISNULL(tProcess.lot_control,'') = '' OR ISNULL(tProcess.lot_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.lot_control END 
			  ,[sn_control]	= CASE WHEN ISNULL(tProcess.sn_control,'') = '' OR ISNULL(tProcess.sn_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.sn_control END
			  ,[expiry_date_control] =CASE WHEN ISNULL(tProcess.expiry_date_control,'') = '' OR ISNULL(tProcess.expiry_date_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.expiry_date_control END 
			  ,[attribute1_control] = CASE WHEN ISNULL(tProcess.attribute1_control,'') = ''  OR ISNULL(tProcess.attribute1_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.attribute1_control END 
			  ,[attribute2_control] = CASE WHEN ISNULL(tProcess.attribute2_control,'') = ''  OR ISNULL(tProcess.attribute2_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.attribute2_control END 
			  ,[attribute3_control] = CASE WHEN ISNULL(tProcess.attribute3_control,'') = ''  OR ISNULL(tProcess.attribute3_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.attribute3_control END 
			  ,[attribute4_control] = CASE WHEN ISNULL(tProcess.attribute4_control,'') = ''  OR ISNULL(tProcess.attribute4_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.attribute4_control END 
			  ,[attribute5_control] = CASE WHEN ISNULL(tProcess.attribute5_control,'') = ''  OR ISNULL(tProcess.attribute5_control,'') NOT IN ('FULL','NONE') THEN 'NONE' ELSE tProcess.attribute5_control END 
			  ,[days_to_expire] = tProcess.days_to_expire
			  ,[fifo_window] = tProcess.fifo_window
			  ,[wh_reorder_point] = tProcess.wh_reorder_point
			  ,[wh_reorder_qty] = tProcess.wh_reorder_qty
			  ,[min_qty] = tProcess.[min]
			  ,[max_qty] = tProcess.[max]
			  ,[cost] = tProcess.cost
			  ,[price] = tProcess.price
			  ,[dg_code] = tProcess.dg_code
			  ,[inventory_type] = CASE WHEN ISNULL(tProcess.inventory_type,'') = '' THEN 'YES' ELSE tProcess.inventory_type END  
			  ,[is_kit]    =  	  CASE WHEN ISNULL(tProcess.is_kit,'') = '' THEN 'NO' ELSE tProcess.is_kit END  
			  ,[is_bom]    =  	  CASE WHEN ISNULL(tProcess.is_bom,'') = '' THEN 'NO' ELSE tProcess.is_bom END
			  ,[model]     = tProcess.model
			  ,[style]     = tProcess.style
			  ,[color]     = tProcess.color
			  ,[size]      = tProcess.size
			  ,[coo]	   = tProcess.coo
			  ,[grade]	   = tProcess.grade
			  ,[user_def1] = tProcess.user_def1 
			  ,[user_def2] = tProcess.user_def2 
			  ,[user_def3] = tProcess.user_def3 
			  ,[user_def4] = tProcess.user_def4 
			  ,[user_def5] = tProcess.user_def5 
			  ,[user_def6] = tProcess.user_def6 
			  ,[user_def7] = tProcess.user_def7 
			  ,[user_def8] = tProcess.user_def8 
			  ,[user_def9] = tProcess.user_def9 
			  ,[user_def10] = tProcess.user_def10
			  ,[is_active] = CASE WHEN ISNULL(tProcess.is_active,'') = '' THEN 'YES' ELSE tProcess.is_active END 
			  ,[update_by] = tProcess.create_by
			  ,[update_date] = getdate()
		FROM t_wms_item tItem
		INNER JOIN #tProcessItem tProcess ON tItem.item_master_id = tProcess.item_master_unique_id AND tProcess.process_status = 'UPDATE'
		LEFT JOIN t_wms_wh_item whItem ON tItem.item_master_id = whItem.item_master_id
		WHERE whItem.wh_item_master_id NOT IN (SELECT wh_item_master_id FROM t_wms_inventory)
	END
-------------------------------------------------------------
	--Insert data from host for insert to wms uom master
	SELECT tHostUOM.*
		,hItem.wh_id
		,uom.item_uom_id AS item_uom_unique_id
		,hItem.item_master_unique_id
		,hItem.owner_unique_id
		,(CASE WHEN tHostUOM.processing_code = 'DELETE' THEN 'DELETE' WHEN uom.item_uom_id IS NOT NULL THEN 'UPDATE' ELSE 'INSERT' END) AS process_status
	INTO #tProcessItemUOM
	FROM t_host_wms_item_uom tHostUOM
	INNER JOIN #tProcessItem hItem ON tHostUOM.host_record_id = hItem.host_record_id AND hItem.process_status <> 'DELETE'
	LEFT JOIN t_wms_item_uom uom ON hItem.item_master_unique_id = uom.item_master_id AND uom.uom = tHostUOM.uom

	BEGIN--DELETE ITEM UOM Master
		BEGIN TRY 
			DELETE t_wms_item_uom WHERE item_uom_id IN (SELECT item_uom_unique_id FROM #tProcessItemUOM WHERE process_status = 'DELETE')
		END TRY
		BEGIN CATCH 
			UPDATE t_host_wms_item_uom SET processing_status = 'ERROR'
			FROM t_host_wms_item_uom tItem
			WHERE tItem.host_record_id IN (SELECT host_record_id FROM #tProcessItemUOM WHERE process_status = 'DELETE')
			 
			SET @out_vchErrorCode = ERROR_NUMBER()
			SET @out_vchErrorMsg = ERROR_MESSAGE()
			INSERT INTO [dbo].[t_com_process_log]
				([app_id]
				,[log_type]
				,[warehouse]
				,[device]
				,[process]
				,[process_datetime]
				,[data_1]
				,[data_2]
				,[data_3]
				,[data_4]
				,[message]
				,[create_date]
				,[create_by])
			SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
				, @v_vchLogType
				, ISNULL(temp.wh_id,'')
				, @v_vchDeviceID
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, temp.host_record_id
				, temp.item_number
				, temp.owner_unique_id
				, temp.uom
				, @out_vchErrorMsg
				, GETDATE()
				, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
			FROM #tProcessItemUOM temp
			WHERE temp.process_status = 'DELETE'
				
			GOTO EXIT_LABEL;
		END CATCH
	END

	BEGIN--INSERT ITEM UOM Master
		INSERT INTO [dbo].[t_wms_item_uom]
			   ([item_uom_id]
			   ,[item_master_id]
			   ,[uom]
			   ,[primary_uom]
			   ,[conversion_factor]
			   ,[sequence]
			   ,[picking_uom]
			   ,[shipping_uom]
			   ,[uom_prompt]
			   ,[picking_class]
			   ,[putaway_class]
			   ,[display_ti_hi]
			   ,[ti_hi_unit_per_layer]
			   ,[ti_hi_layers_per_uom]
			   ,[gtin]
			   ,[length]
			   ,[width]
			   ,[height]
			   ,[weight]
			   ,[is_active]
			   ,[create_by]
			   ,[create_date] )
		 SELECT NEWID()
			   ,item_master_unique_id
			   ,uom
			   ,primary_uom
			   ,conversion_factor
			   ,sequence
			   ,picking_uom
			   ,shipping_uom
			   ,uom_prompt
			   ,(SELECT TOP 1 rule_id FROM t_wms_rule WHERE rule_code = (CASE picking_class WHEN 'FIFO' THEN 'RULE_PICK_BY_FIFO' 
																							WHEN 'FEFO' THEN 'RULE_PICK_BY_FEFO' 
																							WHEN 'LOCATION' THEN 'RULE_PICK_BY_PICK_LOCATION' 
																		  ELSE [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_RULE',NULL,'WH_CONTROL') END) AND type = 'PICK_RULE')
			   ,(SELECT TOP 1 rule_id FROM t_wms_rule WHERE rule_code = [dbo].[usf_GetRuleValue] ('DEFAULT_PUT_RULE',NULL,'WH_CONTROL') AND type = 'PUTAWAY_RULE')
			   ,CASE WHEN LTRIM(ISNULL(display_ti_hi,'')) = '' THEN 'NO' ELSE display_ti_hi END
			   ,ti_hi_unit_per_layer
			   ,ti_hi_layers_per_uom
			   ,gtin
			   ,length
			   ,width
			   ,height
			   ,weight 
			   ,is_active
			   ,create_by
			   ,GETDATE()
		FROM #tProcessItemUOM
		WHERE process_status = 'INSERT'
	END

	BEGIN--UPDATE ITEM UOM Master
		UPDATE [dbo].[t_wms_item_uom] SET
			  [primary_uom] = tProc.primary_uom
			  ,[conversion_factor] = tProc.conversion_factor 
			  ,[sequence] = tProc.sequence
			  ,[picking_uom] = tProc.picking_uom
			  ,[shipping_uom] = tProc.shipping_uom
			  ,[picking_class] = (SELECT TOP 1 rule_id FROM t_wms_rule 
								  WHERE rule_code = (CASE tProc.picking_class WHEN 'FIFO' THEN 'RULE_PICK_BY_FIFO' 
													 WHEN 'FEFO' THEN 'RULE_PICK_BY_FEFO' 
													 WHEN 'LOCATION' THEN 'RULE_PICK_BY_PICK_LOCATION' 
													 ELSE [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_RULE',NULL,'WH_CONTROL') END) AND type = 'PICK_RULE')
			  ,[display_ti_hi] = tProc.display_ti_hi 
			  ,[ti_hi_unit_per_layer] = tProc.ti_hi_unit_per_layer
			  ,[ti_hi_layers_per_uom] = tProc.ti_hi_layers_per_uom
			  ,[gtin] = tProc.gtin
			  ,[length] = tProc.length
			  ,[width] = tProc.width
			  ,[height] = tProc.height
			  ,[weight] = tProc.weight
			  ,[is_active] = tProc.is_active
			  ,[update_by] = tProc.create_by
			  ,[update_date] = getdate()
		 FROM [t_wms_item_uom] tUOM
		 LEFT JOIN #tProcessItemUOM tProc ON tUOM.item_uom_id = tProc.item_uom_unique_id
		 WHERE tProc.process_status = 'UPDATE'
	END
-------------------------------------------------------------
	--Insert data from host for insert to wms item cross ref master
	SELECT tHostCref.*
		,hItem.wh_id
		,cref.alternate_id AS alternate_unique_id
		,hItem.item_master_unique_id
		,uom.item_uom_id AS base_item_uom_unique_id
		,hItem.owner_unique_id
		,(CASE WHEN tHostCref.processing_code = 'DELETE' THEN 'DELETE' WHEN cref.alternate_id IS NOT NULL THEN 'UPDATE' ELSE 'INSERT' END) AS process_status
	INTO #tProcessItemCref
	FROM t_host_wms_item_crossref tHostCref
	INNER JOIN #tProcessItem hItem ON tHostCref.host_record_id = hItem.host_record_id AND hItem.process_status <> 'DELETE'
	LEFT JOIN t_wms_item_crossref cref ON hItem.item_master_unique_id = cref.item_master_id AND cref.alternate_item_number = tHostCref.alternate_item_number
	LEFT JOIN t_wms_item_uom uom ON hItem.item_master_unique_id = uom.item_master_id AND uom.primary_uom = 'YES'
	WHERE tHostCref.host_record_id IN (SELECT host_record_id FROM #tProcessItem)

	BEGIN--DELETE ITEM Cross REF Master
		BEGIN TRY 
			DELETE t_wms_item_crossref WHERE alternate_id IN (SELECT alternate_unique_id FROM #tProcessItemCref WHERE process_status = 'DELETE')
		END TRY
		BEGIN CATCH 
			UPDATE t_host_wms_item_crossref SET processing_status = 'ERROR'
			FROM t_host_wms_item_crossref
			WHERE host_record_id IN (SELECT host_record_id FROM #tProcessItemCref WHERE process_status = 'DELETE')
			 
			SET @out_vchErrorCode = ERROR_NUMBER()
			SET @out_vchErrorMsg = ERROR_MESSAGE()
			INSERT INTO [dbo].[t_com_process_log]
				([app_id]
				,[log_type]
				,[warehouse]
				,[device]
				,[process]
				,[process_datetime]
				,[data_1]
				,[data_2]
				,[data_3]
				,[data_4]
				,[message]
				,[create_date]
				,[create_by])
			SELECT LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
				, @v_vchLogType
				, ISNULL(temp.wh_id,'')
				, @v_vchDeviceID
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, temp.host_record_id
				, temp.item_number
				, temp.owner_unique_id
				, temp.alternate_item_number
				, @out_vchErrorMsg
				, GETDATE()
				, ISNULL(LEFT(temp.create_by, 25), 'SYSTEM')
			FROM #tProcessItemCref temp
			WHERE temp.process_status = 'DELETE'
			GOTO EXIT_LABEL;
		END CATCH
	END

	BEGIN--INSERT ITEM Cross REF Master
		INSERT INTO [dbo].[t_wms_item_crossref]
			([alternate_id]
			,[item_master_id]
			,[alternate_item_number]
			,[item_uom_id]
			,[is_active]
			,[create_by]
			,[create_date] )
		SELECT NEWID()
			,item_master_unique_id
			,alternate_item_number
			,base_item_uom_unique_id
			,is_active
			,create_by
			,GETDATE()
		FROM #tProcessItemCref
		WHERE process_status = 'INSERT'
	END
------------------------------------------------------------

	--All Success Set to Complete
	UPDATE t_host_wms_item_master SET processing_status = 'COMPLETE' 
	WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)
	AND processing_status = 'INPROCESS'

	UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETE' 
	WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)
	

	UPDATE t_host_wms_item_crossref SET processing_status = 'COMPLETE' 
	WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)



	SET @out_vchErrorCode = '0'
	SET @out_vchErrorMsg = 'Import Success'
	RETURN;

	--Have some error set to Pending again
	EXIT_LABEL:
		--UPDATE PENDING = INPROCESS
		UPDATE t_host_wms_item_master SET processing_status = 'PENDING' 
		WHERE host_record_id IN (SELECT host_record_id FROM #tGetHostItemMaster WHERE rownumber = 1)
		AND processing_status = 'INPROCESS'

		SET @out_vchErrorCode = '99'
		SET @out_vchErrorMsg = 'Import Not Success'

END

/*
declare  @out_vchErrorCode	VARCHAR(50) 
declare  @out_vchErrorMsg	VARCHAR(500)
EXEC usp_ProcessHostItemMasterForInitial @out_vchErrorCode	= @out_vchErrorCode	output
										,@out_vchErrorMsg	= @out_vchErrorMsg	output
select @out_vchErrorCode	
	   ,@out_vchErrorMsg	
*/
GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostItemOnly]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostItemOnly]  
	@in_vchApplicationID	VARCHAR(40)  = NULL, --Required  
	@in_vchApplicationName	NVARCHAR(50) = NULL, --Required  
	@in_vchHostRecordID		VARCHAR(40)	 = NULL, --Required
	@in_vchDevice			NVARCHAR(50) = NULL, --Required
	@in_vchUserID			NVARCHAR(25) = NULL, --Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS  
BEGIN  
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostItemOnly'
	DECLARE @v_intSqlErrorNumber	INTEGER
	DECLARE @v_intSqlErrorLine		INTEGER
	DECLARE @v_intSqlErrorState		INTEGER
	DECLARE @v_intSqlErrorSeverity	INTEGER
	DECLARE @v_vchSqlErrorMessage	NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure	NVARCHAR(200)  
	DECLARE @v_vchProcessData1		NVARCHAR(100)
	DECLARE @v_vchProcessData2		NVARCHAR(100)
	DECLARE @v_vchProcessData3		NVARCHAR(100)
	DECLARE @v_vchProcessData4		NVARCHAR(100)
	DECLARE @v_nErrorNumber			INTEGER
	DECLARE @v_vchMessage			NVARCHAR(500)
	DECLARE @v_nRowCount			INTEGER
	DECLARE @v_intLocale			INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round					INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel			INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction			NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,
 	DECLARE @v_vchTableName			NVARCHAR(50)

	-- Local Variables
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchWhItemMasterID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchCategoryID		UNIQUEIDENTIFIER = NULL
	
	DECLARE @v_vchRecordType		NVARCHAR(10) = NULL   -- Required  
	DECLARE @v_vchProcessingCode	NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchProcessingStatus	NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchItemNumber		NVARCHAR(50) = NULL   -- Required  
	DECLARE @v_vchWarehouse			NVARCHAR(25) = NULL       
	DECLARE @v_vchOwnerCode			NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchDescription		NVARCHAR(200)= NULL   
	DECLARE @v_vchItemCategory		NVARCHAR(50) = NULL   -- Required  
	DECLARE @v_vchLotControl		VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchSNControl			VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchExpiryDateControl	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute1Control	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute2Control	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute3Control	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute4Control	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_vchAttribute5Control	VARCHAR(5)	 = NULL   -- Required  
	DECLARE @v_intDaysToExpire		INTEGER		 = NULL  	   
	DECLARE @v_intFifoWindow		INTEGER		 = NULL  
	DECLARE @v_fltWHREOrderPoint	FLOAT		 = NULL  
	DECLARE @v_fltWHREOrderQty		FLOAT		 = NULL  
	DECLARE @v_fltCost				FLOAT		 = NULL  
	DECLARE @v_fltPrice				FLOAT		 = NULL  
	DECLARE @v_vchDGCode			NVARCHAR(50) = NULL  
	DECLARE @v_vchInventoryType		NVARCHAR(40) = NULL  
	DECLARE @v_vchIsKit				VARCHAR(3)   = NULL  
	DECLARE @v_vchIsBOM				VARCHAR(3)   = NULL 
	DECLARE @v_vchModel				NVARCHAR(30) = NULL  
	DECLARE @v_vchStyle				NVARCHAR(30) = NULL  
	DECLARE @v_vchColor				NVARCHAR(30) = NULL  
	DECLARE @v_vchSize				NVARCHAR(30) = NULL  
	DECLARE @v_vchCoo				NVARCHAR(30) = NULL
	DECLARE @v_fltMin				FLOAT
	DECLARE	@v_fltMax				FLOAT
	DECLARE @v_vchGrade				NVARCHAR(30) = NULL  
	DECLARE @v_vchUserDef1    		NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef2    		NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef3    		NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef4    		NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef5    		NVARCHAR(50) = NULL  
	DECLARE @v_vchUserDef6    		NVARCHAR(50) = NULL  
	DECLARE @v_fltUserDef7    		FLOAT		 = NULL  
	DECLARE @v_fltUserDef8    		FLOAT		 = NULL  
	DECLARE @v_dtUserDef9    		DATETIME	 = NULL  
	DECLARE @v_dtUserDef10    		DATETIME	 = NULL  
	DECLARE @v_vchIsActive    		VARCHAR(3)   = NULL
	DECLARE @v_dtCreateDate			DATETIME
	DECLARE @v_vchUserID			NVARCHAR(25) = NULL
	DECLARE @v_vchDefaultPickLocationGUID	UNIQUEIDENTIFIER = NULL   
	  
BEGIN TRY   
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log  
        
	SELECT @v_vchRecordType		= [record_type]
		,@v_vchProcessingCode	= [processing_code]
		,@v_vchProcessingStatus	= [processing_status]
		,@v_vchOwnerCode		= [owner_id]
		,@v_vchWarehouse		= [wh_id]
		,@v_vchItemCategory		= [item_category]
		,@v_vchItemNumber		= [item_number]
		,@v_vchDescription		= [description]
		,@v_vchLotControl		= ISNULL([lot_control],'NONE')
		,@v_vchSNControl		= ISNULL([sn_control],'NONE')
		,@v_vchExpiryDateControl= ISNULL([expiry_date_control],'NONE')
		,@v_vchAttribute1Control= ISNULL([attribute1_control],'NONE')
		,@v_vchAttribute2Control= ISNULL([attribute2_control],'NONE')
		,@v_vchAttribute3Control= ISNULL([attribute3_control],'NONE')
		,@v_vchAttribute4Control= ISNULL([attribute4_control],'NONE')
		,@v_vchAttribute5Control= ISNULL([attribute5_control],'NONE')
		,@v_intDaysToExpire		= [days_to_expire]
		,@v_intFifoWindow		= [fifo_window]
		,@v_fltWhReorderPoint	= [wh_reorder_point]
		,@v_fltWhReorderQty		= [wh_reorder_qty]
		,@v_fltCost				= [cost]
		,@v_fltPrice			= [price]
		,@v_vchDgCode			= [dg_code]
		,@v_vchInventoryType	= [inventory_type]
		,@v_vchIsKit			= ISNULL([is_kit],'NO')
		,@v_vchIsBom			= ISNULL([is_bom],'NO')
		,@v_vchModel			= [model]
		,@v_vchStyle			= [style]
		,@v_vchColor			= [color]
		,@v_vchSize				= [size]
		,@v_vchGrade			= [grade]
		,@v_vchCoo				= [coo]
		,@v_fltMin				= [min]
		,@v_fltMax				= [max]
		,@v_vchIsActive			= ISNULL([is_active],'YES')
		,@v_vchUserDef1			= [user_def1]
		,@v_vchUserDef2			= [user_def2]
		,@v_vchUserDef3			= [user_def3]
		,@v_vchUserDef4			= [user_def4]
		,@v_vchUserDef5			= [user_def5]
		,@v_vchUserDef6			= [user_def6]
		,@v_fltUserDef7			= [user_def7]
		,@v_fltUserDef8			= [user_def8]
		,@v_dtUserDef9			= [user_def9]
		,@v_dtUserDef10			= [user_def10]
		,@v_dtCreateDate		= [create_date]
		,@v_vchUserID			= [create_by]
	FROM [dbo].[t_host_wms_item_master]
	WHERE host_record_id = @in_vchHostRecordID
	AND processing_status = 'PENDING'

	------------------------------------------------------------
	-- Set default value
	------------------------------------------------------------
	SELECT @v_vchLotControl		   = CASE WHEN ISNULL(@v_vchLotControl,'') = '' THEN 'NONE' ELSE @v_vchLotControl END
	SELECT @v_vchSNControl		   = CASE WHEN ISNULL(@v_vchSNControl, '') = '' THEN 'NONE' ELSE @v_vchSNControl END
	SELECT @v_vchExpiryDateControl = CASE WHEN ISNULL(@v_vchExpiryDateControl, '') = '' THEN 'NONE' ELSE @v_vchExpiryDateControl END
	SELECT @v_vchAttribute1Control = CASE WHEN ISNULL(@v_vchAttribute1Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute1Control END
	SELECT @v_vchAttribute2Control = CASE WHEN ISNULL(@v_vchAttribute2Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute2Control END
	SELECT @v_vchAttribute3Control = CASE WHEN ISNULL(@v_vchAttribute3Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute3Control END
	SELECT @v_vchAttribute4Control = CASE WHEN ISNULL(@v_vchAttribute4Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute4Control END
	SELECT @v_vchAttribute5Control = CASE WHEN ISNULL(@v_vchAttribute5Control, '') = '' THEN 'NONE' ELSE @v_vchAttribute5Control END
	SELECT @v_vchIsKit			   = CASE WHEN ISNULL(@v_vchIsKit, '') = '' THEN 'NO' ELSE @v_vchIsKit END
	SELECT @v_vchIsBOM			   = CASE WHEN ISNULL(@v_vchIsBOM, '') = '' THEN 'NO' ELSE @v_vchIsBOM END
	SELECT @v_vchIsActive		   = CASE WHEN ISNULL(@v_vchIsActive, '') = '' THEN 'YES' ELSE @v_vchIsActive END

	----------------------------------------------------------  
	--  Check Nulls for Required Fields  
	--  Item Number, Owner, Item Category, User ID
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    

	IF @v_vchRecordType IS NULL  
		OR @v_vchProcessingCode IS NULL   
		OR @v_vchProcessingStatus IS NULL
		OR @v_vchItemNumber IS NULL  
		OR @v_vchOwnerCode IS NULL
		OR @v_vchItemCategory IS NULL  
		OR @v_vchUserID IS NULL   
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
		SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
							 + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
							 + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
							 + ' Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']' 
							 + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
							 + ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']'  
							 + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
		                 
		-- Future, Add a Log action for inserting into the Process Log  
		
		SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
		SET @v_vchLogType = 'IMPORT ERROR'  
		
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
									+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
									+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
		SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
		SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO WRITE_PROCESS_LOG  
	END   
   
	------------------------------------------------------------  
	--  Check Valid Record Type Code  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Types'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchRecordType <> 'MASTER')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END  
  
	------------------------------------------------------------  
	--  Check Valid Processing Code the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END    
     
	------------------------------------------------------------  
	--  Check Valid Processing Status the Item Master  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingStatus NOT IN ('PENDING')  
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END     
  
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	-- Check category in master
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Category'  
	-- Future, Add a Log action for inserting into the Process Log  
	SELECT @v_vchCategoryID = category_id FROM t_wms_category WHERE item_category = @v_vchItemCategory
	IF (@v_vchCategoryID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Category ID'  
			-- Future, Add a Log action for inserting into the Process Log    

			------------------------------------------------------------------------  
			--  Insert Category เลย กรณีที่ไม่พบข้อมูล Category ใน WMS  
			------------------------------------------------------------------------  
			SET @v_vchCategoryID = NEWID()  
			INSERT INTO t_wms_category
			(  
				 category_id  
				,item_category  
				,create_by  
			)  
			VALUES  
			(   
				 @v_vchCategoryID  
				,@v_vchItemCategory  
				,@v_vchUserID  
			)  
		END

	------------------------------------------------------------  
	--  Get item mater id (GUID)
	------------------------------------------------------------  
	SET @v_vchItemMasterID = NULL;
    SELECT @v_vchItemMasterID = item_master_id FROM t_wms_item 
	WHERE item_number = @v_vchItemNumber
	AND owner_id = @v_vchOwnerID

	SET @v_vchWhMasterID = NULL
    SELECT @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @v_vchWarehouse
    
	-------------------------------------------------------------------------  
	--  Check Data for Add or Update  
	-------------------------------------------------------------------------  
	IF  @v_vchItemMasterID IS NOT NULL AND @v_vchProcessingCode = 'ADD'  
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END 
	
	------------------------------------------------------------  
	--  Processing for 'DELETE' the Item.  
	------------------------------------------------------------  
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_vchItemMasterID IS NOT NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Delete Processing for Item:['+@v_vchItemNumber+']'  
					-- Future, Add a Log action for inserting into the Process Log  
			
					DELETE FROM t_wms_item_crossref WHERE item_master_id = @v_vchItemMasterID
					DELETE FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID        
					DELETE FROM t_wms_wh_item WHERE item_master_id = @v_vchItemMasterID
					DELETE FROM t_wms_item WHERE item_master_id = @v_vchItemMasterID 

					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
					GOTO COMMIT_TRANS;
				END
			ELSE
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Not found item'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-062' -- Not found item for delete
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
												+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
					SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
		END

	------------------------------------------------------------  
	--  Check the Item for a ADD duplicate.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Item'  
	-- Future, Add a Log action for inserting into the Process Log
      
	IF @v_vchProcessingCode = 'ADD' AND @v_vchItemMasterID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Item:['+@v_vchItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  
			 
			SET @out_vchErrorCode = 'ERROR-0015' -- Duplicate Item Number  
			SET @v_vchLogType = 'IMPORT WARNING'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
										+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
										+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse,'') + ']'
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END
	ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchItemMasterID IS NULL
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'ADD' the Item .  
			--  This section should be runing for an 'ADD' with no   
			-- duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing ADD for Item:['+@v_vchItemNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			SELECT @v_vchItemMasterID = NEWID()
			
			INSERT INTO [dbo].[t_wms_item]
				   ([item_master_id]
				   ,[item_number]
				   ,[owner_id]
				   ,[description]
				   ,[category_id]
				   ,[lot_control]
				   ,[sn_control]
				   ,[expiry_date_control]
				   ,[attribute1_control]
				   ,[attribute2_control]
				   ,[attribute3_control]
				   ,[attribute4_control]
				   ,[attribute5_control]
				   ,[days_to_expire]
				   ,[fifo_window]
				   ,[wh_reorder_point]
				   ,[wh_reorder_qty]
				   ,[min_qty]
				   ,[max_qty]
				   ,[cost]
				   ,[price]
				   ,[dg_code]
				   ,[inventory_type]
				   ,[is_kit]
				   ,[is_bom]
				   ,[model]
				   ,[style]
				   ,[color]
				   ,[size]
				   ,[coo]
				   ,[grade]
				   ,[user_def1]
				   ,[user_def2]
				   ,[user_def3]
				   ,[user_def4]
				   ,[user_def5]
				   ,[user_def6]
				   ,[user_def7]
				   ,[user_def8]
				   ,[user_def9]
				   ,[user_def10]
				   ,[is_active]
				   ,[create_by]
				   ,[create_date])
			 VALUES
				   (@v_vchItemMasterID
				   ,@v_vchItemNumber
				   ,@v_vchOwnerID 
				   ,@v_vchDescription
				   ,@v_vchCategoryID
				   ,@v_vchLotControl		
				   ,@v_vchSNControl		
				   ,@v_vchExpiryDateControl
				   ,@v_vchAttribute1Control
				   ,@v_vchAttribute2Control
				   ,@v_vchAttribute3Control
				   ,@v_vchAttribute4Control
				   ,@v_vchAttribute5Control
				   ,@v_intDaysToExpire			
				   ,@v_intFifoWindow			
				   ,@v_fltWhReorderPoint		
				   ,@v_fltWhReorderQty			
				   ,@v_fltMin	
				   ,@v_fltMax	
				   ,@v_fltCost			
				   ,@v_fltPrice			
				   ,@v_vchDgCode		
				   ,@v_vchInventoryType	
				   ,@v_vchIsKit			
				   ,@v_vchIsBom			
				   ,@v_vchModel			
				   ,@v_vchStyle			
				   ,@v_vchColor			
				   ,@v_vchSize			
				   ,@v_vchCoo
				   ,@v_vchGrade
				   ,@v_vchUserDef1	
				   ,@v_vchUserDef2	
				   ,@v_vchUserDef3	
				   ,@v_vchUserDef4	
				   ,@v_vchUserDef5	
				   ,@v_vchUserDef6	
				   ,@v_fltUserDef7	
				   ,@v_fltUserDef8	
				   ,@v_dtUserDef9	
				   ,@v_dtUserDef10
				   ,@v_vchIsActive
				   ,@v_vchUserID
				   ,GETDATE())
			
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
					SELECT @v_vchProcessData4 = 'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
					SELECT @v_vchProcessData4 = 'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
												+ ' Item Category: ['+ISNULL(@v_vchItemCategory, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END

			---------------------------------------------------   
			-- Update Process Status = COMPLETED  
			---------------------------------------------------  
			UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Processing ADD Item Master Completed'   
			-- Future, Add a Log action for inserting into the Process Log  

			---------------------------------------------------  
			--  Set into Default Warehouse Table  
			---------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing Default Warehouse Started'   
			-- Future, Add a Log action for inserting into the Process Log  

			-----------------------------------------------------------------------------------  
			--  If no Default Warehouse then set to ALL Warehouses   
			--  If the Warehouse Value sent into the Item Record is NULL then set to ALL Warehouses   
			-----------------------------------------------------------------------------------  
			IF @v_vchWhMasterID IS NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Inserting into Warehouse Item Table'   
					IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  select 'Field List'+  
							   +'Item Number:['+ISNULL(@v_vchItemNumber, '')+']'  
							   +'Owner:['+ISNULL(@v_vchOwnerCode, '')+']'  
							   +'Warehouse:['+ISNULL(@v_vchWarehouse, '')+']' 
							   +'Is Active:[' +ISNULL(@v_vchIsActive, '')+']'  
							   +'User ID:['+ISNULL(@v_vchUserID, '')+']'  
							  
					INSERT INTO t_wms_wh_item 
						( wh_master_id
						  , item_master_id
						  , pick_location
						  , interface_to_host
						  , is_active
						  , create_by
						  , create_date
						)					
						SELECT wh_master_id
							, @v_vchItemMasterID
							, (SELECT location_id FROM t_wms_location WHERE t_wms_location.wh_master_id = t_wms_wh.wh_master_id   AND location = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_LOCATION',wh_id,'WH_CONTROL'))  
							, 'YES'  
							, @v_vchIsActive
							, @v_vchUserID
							, GETDATE()  
						FROM t_wms_wh
						WHERE is_active = 'YES'
				END  
			ELSE 
				BEGIN
					------------------------------------------------------------  
					--  Only Insert the Single Warehouse  
					------------------------------------------------------------  
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Inserting Item for Warehouse:' + @v_vchWarehouse   
					-- Future, Add a Log action for inserting into the Process Log  

					--------------------------------------------------------------------  
					--  Get the Default Pick Location to insert into the Item WH Table  
					--------------------------------------------------------------------  

					SELECT TOP 1 @v_vchDefaultPickLocationGUID = location_id FROM t_wms_location WHERE wh_master_id = @v_vchWhMasterID AND location = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_LOCATION',@v_vchWarehouse,'WH_CONTROL')
					INSERT INTO t_wms_wh_item 
						( wh_master_id
						  , item_master_id
						  , pick_location
						  , interface_to_host
						  , is_active
						  , create_by
						  , create_date
						)  
						VALUES
						( @v_vchWhMasterID
						  , @v_vchItemMasterID
						  , @v_vchDefaultPickLocationGUID
						  , 'YES'
						  , @v_vchIsActive
						  , @v_vchUserID
						  , GETDATE()
						)  
				END
		END
	ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchItemMasterID IS NOT NULL
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE the Item Master.'  
			
			------------------------------------------------------------
			--ถ้าพบของใน Inventory จะไม่ Update Item Control ทั้งหมดเพราะมีผลกับ data ใน Inventory
			------------------------------------------------------------
			IF EXISTS (SELECT inv.inventory_id FROM t_wms_inventory inv
					   INNER JOIN t_wms_wh_item whItem ON inv.wh_item_master_id = whItem.wh_item_master_id
					   INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
					   WHERE item.item_master_id = @v_vchItemMasterID)
				BEGIN
					UPDATE t_wms_item SET owner_id = @v_vchOwnerID
						, description = @v_vchDescription  
						, category_id = @v_vchCategoryID
						, days_to_expire = @v_intDaysToExpire  
						, fifo_window = @v_intFifoWindow  
						, wh_reorder_point = @v_fltWHREOrderPoint  
						, wh_reorder_qty = @v_fltWHREOrderQty  
						, cost = @v_fltCost  
						, price = @v_fltPrice  
						, dg_code = @v_vchDGCode  
						, inventory_type = @v_vchInventoryType  
						, is_kit = @v_vchIsKit  
						, is_bom = @v_vchIsBOM
						, model = @v_vchModel  
						, style = @v_vchStyle  
						, color = @v_vchColor  
						, size = @v_vchSize  
						, coo = @v_vchCoo
						, [max_qty] = @v_fltMax
						, [min_qty] = @v_fltMin
						, grade = @v_vchGrade
						, user_def1 = @v_vchUserDef1  
						, user_def2 = @v_vchUserDef2  
						, user_def3 = @v_vchUserDef3  
						, user_def4 = @v_vchUserDef4  
						, user_def5 = @v_vchUserDef5  
						, user_def6 = @v_vchUserDef6  
						, user_def7 = @v_fltUserDef7  
						, user_def8 = @v_fltUserDef8  
						, user_def9 = @v_dtUserDef9  
						, user_def10 = @v_dtUserDef10 
						, is_active = @v_vchIsActive  
					WHERE item_master_id = @v_vchItemMasterID
				END
			ELSE
				BEGIN
					UPDATE t_wms_item SET owner_id = @v_vchOwnerID
						, description = @v_vchDescription  
						, category_id = @v_vchCategoryID
						, lot_control = @v_vchLotControl  
						, sn_control = @v_vchSNControl  
						, expiry_date_control = @v_vchExpiryDateControl  
						, attribute1_control = @v_vchAttribute1Control
						, attribute2_control = @v_vchAttribute2Control
						, attribute3_control = @v_vchAttribute3Control
						, attribute4_control = @v_vchAttribute4Control
						, attribute5_control = @v_vchAttribute5Control
						, days_to_expire = @v_intDaysToExpire  
						, fifo_window = @v_intFifoWindow  
						, wh_reorder_point = @v_fltWHREOrderPoint  
						, wh_reorder_qty = @v_fltWHREOrderQty  
						, cost = @v_fltCost  
						, price = @v_fltPrice  
						, dg_code = @v_vchDGCode  
						, inventory_type = @v_vchInventoryType  
						, is_kit = @v_vchIsKit  
						, is_bom = @v_vchIsBOM
						, model = @v_vchModel  
						, style = @v_vchStyle  
						, color = @v_vchColor  
						, size = @v_vchSize  
						, coo = @v_vchCoo
						, [max_qty] = @v_fltMax
						, [min_qty] = @v_fltMin
						, grade = @v_vchGrade
						, user_def1 = @v_vchUserDef1  
						, user_def2 = @v_vchUserDef2  
						, user_def3 = @v_vchUserDef3  
						, user_def4 = @v_vchUserDef4  
						, user_def5 = @v_vchUserDef5  
						, user_def6 = @v_vchUserDef6  
						, user_def7 = @v_fltUserDef7  
						, user_def8 = @v_fltUserDef8  
						, user_def9 = @v_dtUserDef9  
						, user_def10 = @v_dtUserDef10 
						, is_active = @v_vchIsActive  
					WHERE item_master_id = @v_vchItemMasterID
				END

			UPDATE t_wms_wh_item SET is_active = @v_vchIsActive WHERE item_master_id = @v_vchItemMasterID				 
			UPDATE t_host_wms_item_master SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Update Item Master Complete'  
		END  

	------------------------------------------------------------  
	--  Finished All. Now Exit SPROC   
	------------------------------------------------------------  
	COMMIT_TRANS:
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
--                           WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:   
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
	 
	SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'ITEM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchItemNumber,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())
		
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID
	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
	-- Future, Add a Log action for inserting into the Process Log
		
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER(),
		@v_vchSqlErrorMessage = ERROR_MESSAGE(),
		@v_intSqlErrorState = ERROR_STATE(),
		@v_intSqlErrorSeverity = ERROR_SEVERITY(),
		@v_intSqlErrorLine = ERROR_LINE(),
		@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
	SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
						+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
						+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
						+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
						+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
	SET  @v_vchProcessData3 = 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '') + ']'
	SET  @v_vchProcessData4 = 'Item Number: ['+ISNULL(@v_vchItemNumber, '') + ']'
		
	SET @out_vchErrorCode = @v_intSqlErrorNumber
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage
		
	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END

	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'ITEM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchItemNumber,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())
			
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  

	UPDATE t_host_wms_item_master SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END



GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostItemUOMOnly]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE [dbo].[usp_ProcessHostItemUOMOnly]  
	@in_vchApplicationID	VARCHAR(40)  = NULL, --Required  
	@in_vchApplicationName	NVARCHAR(50) = NULL, --Required  
	@in_vchHostRecordID		VARCHAR(40)  = NULL, --Required
	@in_vchDevice			NVARCHAR(50) = NULL, --Required
	@in_vchUserID			NVARCHAR(25) = NULL, --Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS  
BEGIN  
	DECLARE @v_vchApplicationID			NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName				NVARCHAR(30) = 'usp_ProcessHostItemUOMOnly'
	DECLARE @v_intSqlErrorNumber		INTEGER
	DECLARE @v_intSqlErrorLine			INTEGER
	DECLARE @v_intSqlErrorState			INTEGER
	DECLARE @v_intSqlErrorSeverity		INTEGER
	DECLARE @v_vchSqlErrorMessage		NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure		NVARCHAR(200)  
	DECLARE @v_vchProcessData1			NVARCHAR(100)
	DECLARE @v_vchProcessData2			NVARCHAR(100)
	DECLARE @v_vchProcessData3			NVARCHAR(100)
	DECLARE @v_vchProcessData4			NVARCHAR(100)
	DECLARE @v_nErrorNumber				INTEGER
	DECLARE @v_vchMessage				NVARCHAR(500)
	DECLARE @v_nRowCount				INTEGER
	DECLARE @v_intLocale				INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round						INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType				NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel				INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction				NVARCHAR(25) = 'PRINT'	-- PRINT, LOG, 
 	DECLARE @v_vchTableName				NVARCHAR(50)

	-- Local Variables
	DECLARE @v_vchWhMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID				UNIQUEIDENTIFIER = NULL 
	DECLARE @v_vchItemMasterID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemUomID				UNIQUEIDENTIFIER = NULL

	-- Table Variables for [t_host_wms_item_uom]
	DECLARE @v_vchHostItemUOMIDGUID		VARCHAR(40) = NULL
	DECLARE @v_vchRecordType			NVARCHAR(10) = NULL   -- Required  
	DECLARE @v_vchProcessingCode		NVARCHAR(40) = NULL   -- Required  
	DECLARE @v_vchProcessingStatus		NVARCHAR(40) = NULL   -- Required 
	DECLARE @v_vchUOMItemNumber			NVARCHAR(50)	= NULL -- Required  
	DECLARE @v_vchUOMOwner				NVARCHAR(40)	= NULL -- Required  
	DECLARE @v_vchUOMUom				NVARCHAR(20)	= NULL -- Required
	DECLARE @v_vchUOMPrimaryUom			VARCHAR(3)		= NULL    
	DECLARE @v_fltUOMConversionFactor	FLOAT			= NULL  
	DECLARE @v_vchUOMPicking			VARCHAR(3)		= NULL  
	DECLARE @v_vchUOMShipping			VARCHAR(3)		= NULL  
	DECLARE @v_vchUOMUomPrompt			NVARCHAR(40)	= NULL  
	DECLARE @v_vchUOMDisplayTiHi		VARCHAR(3)		= NULL  
	DECLARE @v_fltUOMTiHiUnitPerLayer	FLOAT			= NULL  
	DECLARE @v_fltUOMTiHiUnitPerUom		FLOAT			= NULL  
	DECLARE @v_vchUOMGtin				NVARCHAR(10)	= NULL  
	DECLARE @v_fltUOMLength				FLOAT			= NULL  
	DECLARE @v_fltUOMWidth				FLOAT			= NULL  
	DECLARE @v_fltUOMHeight				FLOAT			= NULL  
	DECLARE @v_fltUOMWeight				FLOAT			= NULL  
	DECLARE @v_vchUOMIsActive			VARCHAR(3)		= NULL
	DECLARE @v_vchUOMUserID				NVARCHAR(25)	= NULL   
	DECLARE @v_intUOMSequence			INT				= NULL  
	DECLARE @v_vchUOMPickingClass		NVARCHAR(40)	= NULL
	DECLARE @v_vchUOMPutwayClass		NVARCHAR(40)	= NULL
	DECLARE @v_vchUOMPickingClassRuleName NVARCHAR(50)	= NULL
	DECLARE @v_vchDefaultPickRuleGUID		UNIQUEIDENTIFIER = NULL  
	DECLARE @v_vchDefaultPutRuleGUID		UNIQUEIDENTIFIER = NULL  
    
BEGIN TRY
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log  
    ITEM_UOM_LABEL:
	
	SELECT TOP 1 @v_vchHostItemUOMIDGUID = [uom_id]
			,@v_vchRecordType		= [record_type]
			,@v_vchProcessingCode		= [processing_code]
			,@v_vchProcessingStatus		= [processing_status]
			,@v_vchUOMItemNumber		= [item_number]
			,@v_vchUOMOwner				= [owner_id]
			,@v_vchUOMUom				= [uom]
			,@v_vchUOMPrimaryUom		= [primary_uom]
			,@v_fltUOMConversionFactor	= [conversion_factor]
			,@v_vchUOMPicking			= [picking_uom]
			,@v_vchUOMShipping			= [shipping_uom]
			,@v_vchUOMUomPrompt			= [uom_prompt]
			,@v_vchUOMDisplayTiHi		= [display_ti_hi]
			,@v_fltUOMTiHiUnitPerLayer	= [ti_hi_unit_per_layer]
			,@v_fltUOMTiHiUnitPerUom	= [ti_hi_layers_per_uom]
			,@v_vchUOMGtin				= [gtin]
			,@v_fltUOMLength			= [length]
			,@v_fltUOMWidth				= [width]
			,@v_fltUOMHeight			= [height]
			,@v_fltUOMWeight			= [weight]  
			,@v_intUOMSequence			= [sequence]
			,@v_vchUOMIsActive			= [is_active]
			,@v_vchUOMUserID			= [create_by] 
			,@v_vchUOMPickingClass		= [picking_class]
			,@v_vchUOMPutwayClass		= [putaway_class]
		FROM t_host_wms_item_uom
		WHERE host_record_id = @in_vchHostRecordID 
		AND processing_status = 'PENDING'
		ORDER BY uom_id      

	----------------------------------------------------------  
	--  Check Nulls for Required Fields  
	----------------------------------------------------------  
	IF @v_vchRecordType IS NULL  
		OR @v_vchProcessingCode IS NULL   
		OR @v_vchProcessingStatus IS NULL
		OR @v_vchUOMItemNumber IS NULL
		OR @v_vchUOMOwner IS NULL
		OR @v_vchUOMUom IS NULL
		OR @v_vchUOMUomPrompt IS NULL  
		OR @v_vchUOMUserID IS NULL
		OR ISNULL(@v_fltUOMConversionFactor,0) = 0
		BEGIN
			------------------------------------------------------------  
			--  Missing Required Fields   
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
			SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']' 
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']' 
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']' 
									+ ' Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']' 
									+ ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUOMUserID, '') + ']'   
		                 
			-- Future, Add a Log action for inserting into the Process Log  
		
			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			SET @v_vchLogType = 'IMPORT ERROR'  
		
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
			SELECT @v_vchProcessData4 =   ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUOMUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG  
		END

	------------------------------------------------------------  
	-- Check Valid Processing Code  
	------------------------------------------------------------  
	if @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code the Item UOM'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code  
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END
	 
	------------------------------------------------------------  
	-- Check Valid Processing Status  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status the Item UOM'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingStatus <> 'PENDING')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  
			 
			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG
		END
	  
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner (Item UOM)'  
	-- Future, Add a Log action for inserting into the Process Log  
	SET @v_vchOwnerID = NULL
	SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchUOMOwner AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END

	------------------------------------------------------------  
	--  Get Item UOM ID, Item Master ID
	------------------------------------------------------------
	SET @v_vchItemMasterID       = NULL
	SELECT @v_vchItemMasterID = item.item_master_id
	FROM t_wms_item AS item
 	WHERE item.item_number = @v_vchUOMItemNumber
	AND item.owner_id = @v_vchOwnerID

	------------------------------------------------------------  
	-- Check for Valid Item  
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Item (Item UOM)'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchItemMasterID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-015' -- Invalid Item Number
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END

	SET @v_vchItemUomID = NULL
	SELECT @v_vchItemUomID = uom.item_uom_id
	FROM t_wms_item_uom AS uom 
	WHERE uom.item_master_id  = @v_vchItemMasterID 
	AND uom.uom = @v_vchUOMUom

	------------------------------------------------------------
	--Check uom can only 1 uom to Primary UOM
	------------------------------------------------------------
	IF EXISTS (SELECT item_uom_id FROM t_wms_item_uom WHERE item_master_id = @v_vchItemMasterID AND primary_uom = 'YES' AND uom <> @v_vchUOMUom) AND @v_vchUOMPrimaryUom = 'YES'
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'The primary uom has 1 uom only.'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-061' -- The primary uom has 1 uom only.
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code [' + @out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END

	-------------------------------------------------------------------------  
	--  Check Data for Add or Update  
	-------------------------------------------------------------------------  
	IF @v_vchItemUomID IS NOT NULL AND @v_vchProcessingCode = 'ADD'  
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END
		
	------------------------------------------------------------  
	--  Processing for 'DELETE' the Item UOM.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing the Item UOM'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_vchProcessingCode = 'DELETE'  
	BEGIN
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Delete Processing for UOM:['+@v_vchUOMUom+']'  
		-- Future, Add a Log action for inserting into the Process Log     
			
		IF @v_vchItemUomID IS NOT NULL
			BEGIN
				---------------------------------------------------   
				-- DELETE ITEM CROSSREF FROM WMS TABLE
				---------------------------------------------------
				DELETE FROM t_wms_item_uom WHERE item_uom_id = @v_vchItemUomID
					 
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
					 
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete Item UOM Completed'  
					 
				------------------------------------------------------------------------------
				-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
				------------------------------------------------------------------------------
				IF  EXISTS (SELECT uom_id FROM t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')
					BEGIN
						GOTO ITEM_UOM_LABEL;
					END
				ELSE
					BEGIN
						GOTO EXIT_LABEL;
					END
			END
		ELSE
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner (Item UOM)'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid Order Detail - Item UOM Does Not Exist  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
											+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
											+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
											+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
				SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
											+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
											+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				GOTO WRITE_PROCESS_LOG
			END
	END
	  
	------------------------------------------------------------  
	--  Get the Default Picking Rule  
	------------------------------------------------------------ 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Get the default picking rule'  
	-- Future, Add a Log action for inserting into the Process Log  
            
	SET @v_vchUOMPickingClassRuleName = NULL
	IF (@v_vchUOMPickingClass = 'FIFO')
		BEGIN
			SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_FIFO'
		END
	ELSE IF (@v_vchUOMPickingClass = 'FEFO')
		BEGIN
			SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_FEFO'
		END
	ELSE IF (@v_vchUOMPickingClass = 'LOCATION')
		BEGIN
			SET @v_vchUOMPickingClassRuleName = 'RULE_PICK_BY_PICK_LOCATION'
		END
	ELSE
		BEGIN
			SELECT @v_vchUOMPickingClassRuleName = [dbo].[usf_GetRuleValue] ('DEFAULT_PICK_RULE',NULL,'WH_CONTROL')   
		END

	SELECT @v_vchDefaultPickRuleGUID = rule_id FROM t_wms_rule WHERE rule_code = @v_vchUOMPickingClassRuleName AND type = 'PICK_RULE'
 
	------------------------------------------------------------  
	--  Get the Default Putaway Rule  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Get the default putaway rule'  
	-- Future, Add a Log action for inserting into the Process Log  
		             
	SELECT @v_vchDefaultPutRuleGUID = rule_id FROM t_wms_rule WHERE rule_code = [dbo].[usf_GetRuleValue] ('DEFAULT_PUT_RULE',NULL,'WH_CONTROL') AND type = 'PUTAWAY_RULE'  

	-------------------------------------------------------------------------  
	--  Check Data for Add or Update  
	-------------------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Check data for processing status ADD or Update'  
	-- Future, Add a Log action for inserting into the Process Log 
		 
	------------------------------------------------------------  
	-- 5. Check for No Duplicate ITEM UOM  
	------------------------------------------------------------  
	IF @v_vchProcessingCode = 'ADD' AND @v_vchItemUomID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Duplicate Item:['+@v_vchUOMItemNumber+']'  
																		+' UOM:['+ISNULL(@v_vchUOMUom, '')+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-024' -- Duplicate Item UOM  
			SET @v_vchLogType = 'IMPORT WARNING'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - '  + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Item Number: [' + ISNULL(@v_vchUOMItemNumber, '') + ']'
										+ ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
										+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
										+ ' Conversion Factor: [' + ISNULL(CONVERT(VARCHAR(50),@v_fltUOMConversionFactor),0) + ']'
			SELECT @v_vchProcessData4 =   ' Owner: [' + ISNULL(@v_vchUOMOwner, '') + ']'
										+ ' User ID: [' + ISNULL(@v_vchUOMUserID, '') + ']'
										+ ' Is Active: [' + ISNULL(@v_vchUOMIsActive,'') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END  
	ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchItemUomID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting insert data into the Item UOM'  
					
			/*************INSERT DATA UOM INTO t_wms_item_uom*************/  
			INSERT INTO t_wms_item_uom 
			(   item_master_id  
				,uom  
				,primary_uom  
				,conversion_factor  
				,picking_uom  
				,shipping_uom  
				,uom_prompt  
				,picking_class  
				,putaway_class  
				,display_ti_hi  
				,ti_hi_unit_per_layer  
				,ti_hi_layers_per_uom  
				,gtin  
				,length  
				,width  
				,height  
				,weight  
				,sequence
				,is_active  
				,create_date  
				,create_by  
			)  
			VALUES(  
				@v_vchItemMasterID  
				,@v_vchUOMUom  
				,@v_vchUOMPrimaryUom
				,@v_fltUOMConversionFactor  
				,@v_vchUOMPicking  
				,@v_vchUOMShipping  
				,@v_vchUOMUomPrompt  
				,@v_vchDefaultPickRuleGUID  
				,@v_vchDefaultPutRuleGUID  
				,@v_vchUOMDisplayTiHi  
				,@v_fltUOMTiHiUnitPerLayer  
				,@v_fltUOMTiHiUnitPerUom  
				,@v_vchUOMGtin   
				,@v_fltUOMLength   
				,@v_fltUOMWidth    
				,@v_fltUOMHeight    
				,@v_fltUOMWeight    
				,@v_intUOMSequence
				,@v_vchUOMIsActive  
				,GETDATE()  
				,@v_vchUOMUserID  
			)  
				
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']' 
					SELECT @v_vchProcessData4 = ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
												+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_intSqlErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostRecordID, '')+ ']'
					SELECT @v_vchProcessData3 =  'Item Number: ['+ISNULL(@v_vchUOMItemNumber, '') + ']'
												+ ' Owner: ['+ISNULL(@v_vchUOMOwner, '') + ']' 
					SELECT @v_vchProcessData4 =  ' UOM: [' + ISNULL(@v_vchUOMUom, '') + ']' 
												+ ' UOM Prompt: [' + ISNULL(@v_vchUOMUomPrompt, '') + ']'  
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END

			---------------------------------------------------   
			-- Update Process Status = COMPLETED  
			---------------------------------------------------  
			UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
				     
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Item UOM Completed'   

		END  
	ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchItemUomID IS NOT NULL
		BEGIN
			/*************UPDATE DATA UOM INTO t_wms_item_uom*************/  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Check Update of UOM:['+@v_vchUOMUom+']'  
			-- Future, Add a Log action for inserting into the Process Log  
				 
			UPDATE t_wms_item_uom SET
				primary_uom =  @v_vchUOMPrimaryUom  
				,conversion_factor = @v_fltUOMConversionFactor  
				,picking_uom = @v_vchUOMPicking   
				,shipping_uom = @v_vchUOMShipping    
				,uom_prompt = @v_vchUOMUomPrompt  
				,picking_class = @v_vchDefaultPickRuleGUID  
				,putaway_class = @v_vchDefaultPutRuleGUID  
				,display_ti_hi = @v_vchUOMDisplayTiHi  
				,ti_hi_unit_per_layer = @v_fltUOMTiHiUnitPerLayer  
				,ti_hi_layers_per_uom = @v_fltUOMTiHiUnitPerUom  
				,gtin = @v_vchUOMGtin  
				,length = @v_fltUOMLength  
				,width  = @v_fltUOMWidth  
				,height = @v_fltUOMHeight  
				,weight = @v_fltUOMWeight  
				,sequence = @v_intUOMSequence
				,is_active = @v_vchUOMIsActive  
				,update_by = @v_vchUOMUserID
				,update_date = GETDATE()
			WHERE item_master_id = @v_vchItemMasterID 
			AND item_uom_id = @v_vchItemUomID
				 
			---------------------------------------------------   
			-- Update Process Status = COMPLETED  
			---------------------------------------------------  
			UPDATE t_host_wms_item_uom SET processing_status = 'COMPLETED' WHERE uom_id = @v_vchHostItemUOMIDGUID  
				 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Item UOM Completed'  
		END

	IF EXISTS (SELECT uom_id FROM t_host_wms_item_uom WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')
		BEGIN
			GOTO ITEM_UOM_LABEL;
		END

	------------------------------------------------------------  
	--  Finished All. Now Exit SPROC   
	------------------------------------------------------------  
	COMMIT_TRANS:
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
--                           WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:   
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@in_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUOMUserID, '') + ']' 
	END
	
	SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'UOM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchUOMUom,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())
	
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_item_uom SET processing_status = 'ERROR' WHERE uom_id = @v_vchHostItemUOMIDGUID AND host_record_id = @in_vchHostRecordID  
	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
	-- Future, Add a Log action for inserting into the Process Log
		
	SELECT 
		@v_intSqlErrorNumber = ERROR_NUMBER(),
		@v_vchSqlErrorMessage = ERROR_MESSAGE(),
		@v_intSqlErrorState = ERROR_STATE(),
		@v_intSqlErrorSeverity = ERROR_SEVERITY(),
		@v_intSqlErrorLine = ERROR_LINE(),
		@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
	SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
						+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
						+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
						+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
						+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
	SET  @v_vchProcessData3 = ''
	SET  @v_vchProcessData4 = ''
		
	SET @out_vchErrorCode = @v_intSqlErrorNumber 
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage
	
	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END

	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'UOM'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchUOMUom,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())

	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  

	UPDATE t_host_wms_item_uom SET processing_status = 'ERROR' WHERE uom_id = @v_vchHostItemUOMIDGUID AND host_record_id = @in_vchHostRecordID  
END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		

END 
GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostLocation]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostLocation]
	@in_vchApplicationID	VARCHAR(40),	--Required
	@in_vchApplicationName	NVARCHAR(50),	--Required
	@in_vchHostLocationID	VARCHAR(40),	--Required
	@in_vchDevice			NVARCHAR(50),	--Required
	@in_vchUserID			NVARCHAR(25),	--Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS
BEGIN
	
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostLocation'
	DECLARE @v_intSqlErrorNumber    INTEGER
	DECLARE @v_intSqlErrorLine		INTEGER
	DECLARE @v_intSqlErrorState		INTEGER
	DECLARE @v_intSqlErrorSeverity	INTEGER
	DECLARE @v_vchSqlErrorMessage	NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure NVARCHAR(200)  
	DECLARE @v_vchProcessData1		NVARCHAR(100)
	DECLARE @v_vchProcessData2		NVARCHAR(100)
	DECLARE @v_vchProcessData3		NVARCHAR(100)
	DECLARE @v_vchProcessData4		NVARCHAR(100)
	DECLARE @v_nErrorNumber			INTEGER
	DECLARE @v_vchMessage           NVARCHAR(500)
	DECLARE @v_nRowCount            INTEGER
	DECLARE @v_intLocale			INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round					INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel          INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction			NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,
 	DECLARE @v_vchTableName			NVARCHAR(50)
	
	-- Local Variables
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL 
	DECLARE @v_vchLocationID		UNIQUEIDENTIFIER = NULL	
	DECLARE @v_vchZoneID			UNIQUEIDENTIFIER = NULL	

	-- Table Variables
	DECLARE @v_vchProcessingCode		NVARCHAR(40)
	DECLARE @v_vchProcessingStatus		NVARCHAR(40)
	DECLARE @v_vchWarehouse				NVARCHAR(50)
	DECLARE @v_vchPickAreaID			VARCHAR(40)
	DECLARE @v_vchLocation				NVARCHAR(50)
	DECLARE @v_vchDescription			NVARCHAR(200)
	DECLARE @v_vchLocType				NVARCHAR(20)
	DECLARE @v_vchLength				FLOAT
	DECLARE @v_vchWidth					FLOAT
	DECLARE @v_vchHeight				FLOAT
	DECLARE @v_vchGrossWeight			FLOAT
	DECLARE @v_vchCapacityQty			FLOAT
	DECLARE @v_vchLpnControlled			NVARCHAR(3)
	DECLARE @v_vchMixOwners				NVARCHAR(3)
	DECLARE @v_vchMixStatus				NVARCHAR(3)
	DECLARE @v_vchMixItems				NVARCHAR(3)
	DECLARE @v_vchMixLot				NVARCHAR(3)
	DECLARE @v_vchMixExpiryDates		NVARCHAR(3)
	DECLARE @v_vchPutawaySequence		INT
	DECLARE @v_vchPickSequence			INT
	DECLARE @v_vchOverrideReceiveDate	NVARCHAR(3)
	DECLARE @v_vchXCordinate			FLOAT
	DECLARE @v_vchYCordinate			FLOAT
	DECLARE @v_vchLocationLevel			NVARCHAR(10)
	DECLARE @v_vchMixAttribute1			NVARCHAR(3)
	DECLARE @v_vchMixAttribute2			NVARCHAR(3)
	DECLARE @v_vchMixAttribute3			NVARCHAR(3)
	DECLARE @v_vchMixAttribute4			NVARCHAR(3)
	DECLARE @v_vchMixAttribute5			NVARCHAR(3)
	DECLARE @v_vchZone					NVARCHAR(50)
	DECLARE @v_vchUserID				NVARCHAR(25)
	DECLARE @v_vchIsActive				NVARCHAR(3)

BEGIN TRY
	------------------------------------------------------------
	--  Get the Table Variables
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'
	SELECT @v_vchProcessingCode		= processing_code
		, @v_vchProcessingStatus	= processing_status
		, @v_vchWarehouse			= warehouse_id
		, @v_vchPickAreaID			= pick_area_id
		, @v_vchLocation			= location
		, @v_vchDescription			= description
		, @v_vchLocType				= loc_type
		, @v_vchLength				= length
		, @v_vchWidth				= width
		, @v_vchHeight				= height
		, @v_vchGrossWeight			= gross_weight
		, @v_vchCapacityQty			= capacity_qty
		, @v_vchLpnControlled		= lpn_controlled
		, @v_vchMixOwners			= mix_owners
		, @v_vchMixStatus			= mix_status
		, @v_vchMixItems			= mix_items
		, @v_vchMixLot				= mix_lot
		, @v_vchMixExpiryDates		= mix_expiry_dates
		, @v_vchPutawaySequence		= putaway_sequence
		, @v_vchPickSequence		= pick_sequence
		, @v_vchOverrideReceiveDate = override_receive_date
		, @v_vchXCordinate			= x_cordinate
		, @v_vchYCordinate			= y_cordinate
		, @v_vchLocationLevel		= location_level
		, @v_vchMixAttribute1		= mix_attribute1
		, @v_vchMixAttribute2		= mix_attribute2
		, @v_vchMixAttribute3		= mix_attribute3
		, @v_vchMixAttribute4		= mix_attribute4
		, @v_vchMixAttribute5		= mix_attribute5
		, @v_vchZone				= zone
		, @v_vchIsActive			= CASE WHEN ISNULL(is_active,'') = '' THEN 'YES' ELSE is_active END
		, @v_vchUserID				= create_by
	FROM t_host_wms_location
	WHERE processing_status	= 'PENDING'
	AND location_id = @in_vchHostLocationID
	 
	--------------------------------------
	--  Check for Required Fields
	--  log_type, warehouse, tran code, start tran date, location, quantity 
	-- 	app_id, device, user id, error_code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'
		-- Future, Add a Log action for inserting into the Process Log		
		
	IF @v_vchProcessingCode IS NULL OR @v_vchProcessingStatus IS NULL OR @v_vchLocation IS NULL OR @v_vchWarehouse IS NULL
		BEGIN
			------------------------------------------------------------
			--  Missing Required Fields 
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  SELECT 'Field List:' +'Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+'] '
																  + 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+'] '
																  + 'Location Code: ['+ISNULL(@v_vchLocation, '')+'] '
																  + 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			SELECT @v_vchProcessData1 = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
										+ '. Error Code ['+@out_vchErrorCode + '].'
			SELECT @v_vchProcessData2 = 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +'] '
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +'] '
										+ 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
			SELECT @v_vchProcessData3 = 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
			SELECT @v_vchProcessData4 = NULL
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale) + ' Error Code ['+@out_vchErrorCode + '].'
			GOTO WRITE_PROCESS_LOG
		END	
	
	------------------------------------------------------------
	--  Check Valid Processing Code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'	
	-- Future, Add a Log action for inserting into the Process Log
		
	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'
			-- Future, Add a Log action for inserting into the Process Log

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale)
										+ '. Error Code ['+@out_vchErrorCode + '].'
			SELECT @v_vchProcessData2 = 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +'] '
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +'] '
										+ 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
			SELECT @v_vchProcessData3 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] '
										+ 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
			SET @v_vchProcessData4 = NULL
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale) + ' Error Code ['+@out_vchErrorCode + '].'
			
			GOTO WRITE_PROCESS_LOG
		END
	
	------------------------------------------------------------
	-- 2.Check Valid Processing Status
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'
	-- Future, Add a Log action for inserting into the Process Log

	IF @v_vchProcessingStatus NOT IN ('PENDING')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale)
										+ '. Error Code ['+@out_vchErrorCode + '].'
			SELECT @v_vchProcessData2 = 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +'] '
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +'] '
										+ 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
			SELECT @v_vchProcessData3 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] '
										+ 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale) + ' Error Code ['+@out_vchErrorCode + '].'
			GOTO WRITE_PROCESS_LOG
		END

	---------------------------------------------
	--Check Warehouse ID
	---------------------------------------------
	SELECT top 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE wh_id = @v_vchWarehouse AND is_active = 'YES'
	IF @v_vchWhMasterID is null
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Warehouse ID not found:[ '+ISNULL(@v_vchWarehouse, '')+'}'
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-LOGMAN-004' -- Invalid Warehouse  
			SET @v_vchLogType = 'IMPORT ERROR'
			SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale)
										+ '. Error Code ['+@out_vchErrorCode + '].'
			SELECT @v_vchProcessData2 = 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +'] '
										+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +'] '
										+ 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
			SELECT @v_vchProcessData3 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] '
										+ 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale) + ' Error Code ['+@out_vchErrorCode + '].'
			GOTO WRITE_PROCESS_LOG
		END

	------------------------------------------------------------
	--  Processing for 'DELETE' the Supplier.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete'
			-- Future, Add a Log action for inserting into the Process Log
					
			DELETE FROM t_wms_location WHERE location = @v_vchLocation AND wh_master_id = @v_vchWhMasterID
			
			---------------------------------------------------	
			-- Update Processing Status in host table = 'ERROR'
			---------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status (COMPLETED) in host table'
			-- Future, Add a Log action for inserting into the Process Log
			
			UPDATE t_host_wms_location SET processing_status = 'COMPLETED' WHERE location_id = @in_vchHostLocationID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete Location Completed'	
			-- Future, Add a Log action for inserting into the Process Log
			
			GOTO EXIT_LABEL
		END

	------------------------------------------------------------
	--  Check the Supplier for a ADD duplicate.
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Location Code'	
	-- Future, Add a Log action for inserting into the Process Log	
	
	SET @v_vchLocationID = NULL
	SELECT @v_vchLocationID = location_id FROM t_wms_location WHERE location = @v_vchLocation AND wh_master_id = @v_vchWhMasterID
	IF @v_vchLocationID is not null AND @v_vchProcessingCode = 'ADD'
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END


	IF @v_vchProcessingCode = 'ADD' AND @v_vchLocationID is not null
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Location Code:['+ @v_vchLocation +']'
				-- Future, Add a Log action for inserting into the Process Log
			
				SET @out_vchErrorCode = 'ERROR-LOGMAN-020' -- Duplicate Location
				SET @v_vchLogType = 'IMPORT WARNING'
				SELECT @v_vchProcessData1 = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale)
											+ ' Error Code ['+@out_vchErrorCode + '].'
				SELECT @v_vchProcessData2 = 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +'] '
											+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') +'] '
											+ 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
				SELECT @v_vchProcessData3 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] '
											+ 'User ID: ['+ISNULL(@v_vchUserID, '') +'] '
				SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale)
									+ ' Error Code ['+@out_vchErrorCode + '].'

				GOTO WRITE_PROCESS_LOG
		END
	ELSE IF @v_vchProcessingCode = 'ADD' AND @v_vchLocationID is null
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD for Location:['+ @v_vchLocation +']'
			-- Future, Add a Log action for inserting into the Process Log
			SET @v_vchLocationID = NEWID()
			INSERT INTO [dbo].[t_wms_location]
				   ([location_id]
				   ,[wh_master_id]
				   ,[pick_area_id]
				   ,[location]
				   ,[description]
				   ,[loc_type]
				   ,[length]
				   ,[width]
				   ,[height]
				   ,[gross_weight]
				   ,[capacity_qty]
				   ,[lpn_controlled]
				   ,[mix_owners]
				   ,[mix_status]
				   ,[mix_items]
				   ,[mix_lot]
				   ,[mix_expiry_dates]
				   ,[putaway_sequence]
				   ,[pick_sequence]
				   ,[override_receive_date]
				   ,[is_active]
				   ,[create_by]
				   ,[create_date]
				   ,[x_cordinate]
				   ,[y_cordinate]
				   ,[location_level]
				   ,[mix_attribute1]
				   ,[mix_attribute2]
				   ,[mix_attribute3]
				   ,[mix_attribute4]
				   ,[mix_attribute5])
			 VALUES
				   (@v_vchLocationID
				   ,@v_vchWhMasterID
				   ,@v_vchPickAreaID
				   ,@v_vchLocation
				   ,@v_vchDescription
				   ,@v_vchLocType
				   ,@v_vchLength
				   ,@v_vchWidth	
				   ,@v_vchHeight
				   ,@v_vchGrossWeight
				   ,@v_vchCapacityQty
				   ,@v_vchLpnControlled
				   ,@v_vchMixOwners	
				   ,@v_vchMixStatus	
				   ,@v_vchMixItems	
				   ,@v_vchMixLot	
				   ,@v_vchMixExpiryDates
				   ,@v_vchPutawaySequence	
				   ,@v_vchPickSequence		
				   ,@v_vchOverrideReceiveDate
				   ,@v_vchIsActive
				   ,@v_vchUserID
				   ,GETDATE()
				   ,@v_vchXCordinate
				   ,@v_vchYCordinate
				   ,@v_vchLocationLevel	
				   ,@v_vchMixAttribute1	
				   ,@v_vchMixAttribute2	
				   ,@v_vchMixAttribute3	
				   ,@v_vchMixAttribute4	
				   ,@v_vchMixAttribute5)

			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN 
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Error Number: ' + STR(ISNULL(@v_nErrorNumber,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostLocationID, '')+ ']'
					SELECT @v_vchProcessData3 = 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
					SELECT @v_vchProcessData4 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] ' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
				
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN 
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
												+ ' Row Count: ' + STR(ISNULL(@v_nRowCount,0)) + ']'
												+ ' Host Record ID: ['+ISNULL(@in_vchHostLocationID, '')+ ']'
					SELECT @v_vchProcessData3 = 'Location Code: ['+ISNULL(@v_vchLocation, '') +'] '
					SELECT @v_vchProcessData4 = 'Warehouse : ['+ISNULL(@v_vchWarehouse, '') +'] ' 
					SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					GOTO WRITE_PROCESS_LOG
				END
				
			--Insert Zone Location
			SET @v_vchZoneID = null
			IF ISNULL(@v_vchZone,'') <> ''
				BEGIN
					SELECT @v_vchZoneID = zone_id FROM t_wms_zone WHERE wh_master_id = @v_vchWhMasterID AND zone = @v_vchZone
					IF @v_vchZoneID is null
						BEGIN
							SET @v_vchZoneID = NEWID()
							INSERT INTO [dbo].[t_wms_zone]
								([zone_id]
								,[wh_master_id]
								,[zone]
								,[zone_type]
								,[is_active]
								,[create_by]
								,[create_date])
							VALUES
								(@v_vchZoneID
								,@v_vchWhMasterID
								,@v_vchZone
								,(SELECT TOP 1 value_member FROM t_com_combobox_item WHERE group_name = 'mst_zone_type' AND is_active = 'YES')
								,'YES'
								,@v_vchUserID
								,GETDATE())
						END
					INSERT INTO [dbo].[t_wms_zone_location]
							   ([zone_location_id]
							   ,[zone_id]
							   ,[location_id]
							   ,[is_active]
							   ,[create_date]
							   ,[create_by])
						 VALUES
							   (newid()
							   ,@v_vchZoneID
							   ,@v_vchLocationID
							   ,'YES'
							   ,Getdate()
							   ,@v_vchUserID)
				END

			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is completed in host table'
			-- Future, Add a Log action for inserting into the Process Log

			UPDATE t_host_wms_location SET processing_status = 'COMPLETED' WHERE location_id = @in_vchHostLocationID
	
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Location Completed'	
			-- Future, Add a Log action for inserting into the Process Log
			
			GOTO EXIT_LABEL;
		END
	ELSE IF @v_vchProcessingCode = 'UPDATE' AND @v_vchLocationID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Update of Location:['+ @v_vchLocation +']'
			-- Future, Add a Log action for inserting into the Process Log

			UPDATE [dbo].[t_wms_location]
			SET [pick_area_id] = @v_vchPickAreaID
				,[description] = @v_vchDescription
				,[loc_type] = @v_vchLocType
				,[length] = @v_vchLength
				,[width] = @v_vchWidth	
				,[height] = @v_vchHeight
				,[gross_weight] = @v_vchGrossWeight
				,[capacity_qty] = @v_vchCapacityQty
				,[lpn_controlled] = @v_vchLpnControlled
				,[mix_owners] =@v_vchMixOwners	
				,[mix_status] =@v_vchMixStatus	
				,[mix_items] = @v_vchMixItems	
				,[mix_lot] = @v_vchMixLot
				,[mix_expiry_dates] = @v_vchMixExpiryDates
				,[putaway_sequence] = @v_vchPutawaySequence
				,[pick_sequence] = @v_vchPickSequence
				,[override_receive_date] = @v_vchOverrideReceiveDate
				,[is_active] = @v_vchIsActive
				,[update_by] = @v_vchUserID
				,[update_date] = getdate()
				,[x_cordinate] = @v_vchXCordinate
				,[y_cordinate] = @v_vchYCordinate
				,[location_level] = @v_vchLocationLevel	
				,[mix_attribute1] = @v_vchMixAttribute1	
				,[mix_attribute2] = @v_vchMixAttribute2	
				,[mix_attribute3] = @v_vchMixAttribute3	
				,[mix_attribute4] = @v_vchMixAttribute4	
				,[mix_attribute5] = @v_vchMixAttribute5
			WHERE location_id = @v_vchLocationID
			
			--Insert Zone Location
			DELETE t_wms_zone_location where location_id = @v_vchLocationID
			SET @v_vchZoneID = null
			IF ISNULL(@v_vchZone,'') <> ''
				BEGIN
					SELECT @v_vchZoneID = zone_id FROM t_wms_zone WHERE wh_master_id = @v_vchWhMasterID AND zone = @v_vchZone
					
					IF (@v_vchZoneID is null)
						BEGIN
							SET @v_vchZoneID = NEWID()
							INSERT INTO [dbo].[t_wms_zone]
								([zone_id]
								,[wh_master_id]
								,[zone]
								,[zone_type]
								,[is_active]
								,[create_by]
								,[create_date])
							VALUES
								(@v_vchZoneID
								,@v_vchWhMasterID
								,@v_vchZone
								,(SELECT TOP 1 value_member FROM t_com_combobox_item WHERE group_name = 'mst_zone_type' AND is_active = 'YES')
								,'YES'
								,@v_vchUserID
								,GETDATE())
						END
					
					INSERT INTO [dbo].[t_wms_zone_location]
						([zone_location_id]
						,[zone_id]
						,[location_id]
						,[is_active]
						,[create_date]
						,[create_by])
					VALUES
						(newid()
						,@v_vchZoneID
						,@v_vchLocationID
						,'YES'
						,Getdate()
						,@v_vchUserID)
				END

			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is completed in host table'
			-- Future, Add a Log action for inserting into the Process Log

			UPDATE t_host_wms_location SET processing_status = 'COMPLETED' WHERE location_id = @in_vchHostLocationID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Update Location Complete'
			GOTO EXIT_LABEL
		END
	
	COMMIT_TRANS:  
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
		
-----------------------------------------------------------------------------------
-- WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
	
	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@in_vchApplicationID, '')
				+'] Log Type: ['+ISNULL(@v_vchLogType, '')
				+'] Warehouse: ['+ISNULL(@v_vchWarehouse, '') 
				+'] Device: ['+ISNULL(@in_vchDevice, '')
				+'] Object Name: ['+ISNULL(@c_vchObjName, '')
				+'] Data1: ['+ISNULL(@v_vchProcessData1, '')
		SELECT '] Data2: ['+ISNULL(@v_vchProcessData2, '')
				+'] Data3: ['+ISNULL(@v_vchProcessData3, '')
				+'] Data4: ['+ISNULL(@v_vchProcessData4, '')
				+'] Message: ['+ISNULL(@v_vchMessage, '')
				+'] User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
		
	SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
	INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'LOCATION'
			,LEFT(@in_vchHostLocationID, 1000) 
			,LEFT(ISNULL(@v_vchLocation,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())
		
	---------------------------------------------------	
	-- Update Processing Status in host table = 'ERROR'
	---------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'
	-- Future, Add a Log action for inserting into the Process Log
			
	UPDATE t_host_wms_location SET processing_status = 'ERROR' WHERE location_id = @in_vchHostLocationID
	GOTO EXIT_LABEL;
END TRY

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
	BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
			
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER()
		, @v_vchSqlErrorMessage = ERROR_MESSAGE()
		, @v_intSqlErrorState = ERROR_STATE()
		, @v_intSqlErrorSeverity = ERROR_SEVERITY()
		, @v_intSqlErrorLine = ERROR_LINE()
		, @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
	SET @v_vchMessage = 'SQL Error Message: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = 'Host Record ID: ['+ISNULL(@in_vchHostLocationID, '') + ']'
	SELECT @v_vchProcessData3 = ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
								+ ' Location: ['+ISNULL(@v_vchLocation, '') + ']'
	SET  @v_vchProcessData4 = @v_vchSqlErrorMessage
	
	SET @out_vchErrorCode = @v_intSqlErrorNumber 
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage

		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(ERROR_MESSAGE(), '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(ERROR_NUMBER(), 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(ERROR_LINE(),10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(ERROR_STATE(),10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(ERROR_SEVERITY(),10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(ERROR_PROCEDURE(), '')+']' 
			END	
		
		UPDATE t_host_wms_location SET processing_status = 'ERROR' WHERE location_id = @in_vchHostLocationID

		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'LOCATION'
			,LEFT(@in_vchHostLocationID, 1000) 
			,LEFT(ISNULL(@v_vchLocation,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())
	END CATCH

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END


GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostOutboundConsignment]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostOutboundConsignment]  
	@in_vchApplicationID	VARCHAR(40),			--Required  
	@in_vchApplicationName	NVARCHAR(10),			--Required  
	@in_vchHostRecordID		VARCHAR(40),			--Required  
	@in_vchOrderNumber		NVARCHAR(40),			--Required  
	@in_vchDevice			NVARCHAR(50),			--Required  
	@in_vchUserID			NVARCHAR(10) = NULL,	--Required  
	@in_vchLogType			NVARCHAR(50) = NULL,	--Required  
	@in_vchProcess			NVARCHAR(50) = NULL,	--Required  
	@out_vchErrorCode		INT OUTPUT  
AS  
BEGIN
	DECLARE   
    -- Error handling variables
	@c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
	@v_intSqlErrorNumber    INTEGER,
	@v_intSqlErrorLine		INTEGER,
	@v_intSqlErrorState		INTEGER,
	@v_intSqlErrorSeverity	INTEGER,
	@v_vchSqlErrorMessage	NVARCHAR(2048),
	@v_vchSqlErrorProcedure NVARCHAR(200),  
	@v_vchProcessData1		NVARCHAR(100),
	@v_vchProcessData2		NVARCHAR(100),
	@v_vchProcessData3		NVARCHAR(100),
	@v_vchProcessData4		NVARCHAR(100),
	@v_vchMessageSendMail	NVARCHAR(MAX),
	@v_nRowCount            INTEGER,
	@v_nErrorNumber			INTEGER,
	@v_vchMessage           NVARCHAR(500),
	@v_nReturn              INTEGER,
	@v_vchLogType			NVARCHAR(50),
	@v_vchWarehouse			NVARCHAR(25),
	@v_vchApplicationID		NVARCHAR(40),
	@v_intLocale			INTEGER, 
	@v_vchErrorNumber       NVARCHAR(25), 
	@Round					INT,
 
    --  Log Handling Variables
	@v_intLogLevel          INTEGER = 3,			-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	@v_vchLogAction			NVARCHAR(25) = 'PRINT', -- PRINT, LOG,
	--@v_nCount               INTEGER,		
	@v_vchDevice			NVARCHAR(50),
	@v_vchStatus			NVARCHAR(200),
	@v_vchErrorCode			NVARCHAR(200),  
	@v_vchError				NVARCHAR(20),	  -- สำหรับตรวจสอบว่า เป็นการ error จากส่วนใด 1.Master = 'ERROR-MASTER', 2.DETAIL = 'ERROR-DETAIL' 
	@v_vchTableName			NVARCHAR(50),  
	
	-- Local Variables
	@v_vchWHIDGUID				VARCHAR(40)	= NULL,
	@v_vchOrderMasterIDGUID		VARCHAR(40)	= NULL,
	@v_vchOrderDetailIDGUID		VARCHAR(40)	= NULL,
	--@v_vchOrderCommentIDGUID	VARCHAR(40)	= NULL,
	@v_vchWHItemIDGUID			VARCHAR(40)	= NULL,  
	@v_vchItemMasterID			VARCHAR(40) = NULL,
	@v_vchBaseItemUOMIDGUID		VARCHAR(40)	= NULL,  
	@v_vchBaseConversionFactor	FLOAT,
	@v_vchCustomerIDGUID		VARCHAR(40)	= NULL,
	@v_vchOwnerIDGUID			VARCHAR(40)	= NULL,
      
    -- Table Variables (t_wms_outbound_consignment_master)
    @v_vchRecordType			NVARCHAR(10)	= NULL,		-- Required  
    @v_vchProcessingCode    	NVARCHAR(40)	= NULL,		-- Required  
    @v_vchProcessingStatus  	NVARCHAR(40)	= NULL,		-- Required  
    @v_vchWHID					NVARCHAR(25)	= NULL,		-- Required  
    @v_vchOwner					NVARCHAR(40)	= NULL,		-- Required  
    @v_vchOrderNumber			NVARCHAR(40)	= NULL,		-- Required  
    @v_vchOrderType				NVARCHAR(30)	= NULL,		-- Required  
    @v_vchOrderStatus			NVARCHAR(10)	= NULL,		-- Required
    @v_vchCurrentOrderStatus	NVARCHAR(10)	= NULL,		-- ใช้สำหรับเก็บ Status ของ Order ก่อน Interface
	@v_vchCurrentOwner			NVARCHAR(40)	= NULL,		-- ใช้สำหรับเก็บค่า Owner ก่อนการ Update ซึ่งถ้าส่งค่าใหม่มาจะไม่สามารถ Update ได้เนื่องจากกระทบข้อมูลใน Detail
	@v_vchCurrentWHID			NVARCHAR(25)	= NULL,		-- ใช้สำหรับแสดงค่า Warehouse ID ตอน Error
	@v_vchCurrentWHIDGUID		NVARCHAR(40)	= NULL,		-- ใช้สำหรับเก็บค่า Warehouse ID GUID ก่อนการ Update ซึ่งถ้าส่งค่าใหม่มาจะไม่สามารถ Update ได้เนื่องจากกระทบข้อมูลใน Detail
    @v_vchCustOrderNumber		NVARCHAR(40)	= NULL,  
    @v_vchCustPO				NVARCHAR(40)	= NULL, 
	@v_dtOrderCreateDate		DATETIME		= NULL,		-- Required  
    @v_dtOrderDeliveryDatePlan	DATETIME		= NULL,
    @v_dtOrderShipDate			DATETIME		= NULL,		-- Required  

--CUSTOMER
	@v_vchCustomerCode			NVARCHAR(40)	= NULL,  
	@v_vchCustomerName			NVARCHAR(200)	= NULL,
	@v_vchCusDescription		NVARCHAR(200)	= NULL,
	@v_vchCusAddrLine1			NVARCHAR(300)	= NULL,
	@v_vchCusAddrLine2			NVARCHAR(300)	= NULL,
	@v_vchCusAddrLine3			NVARCHAR(300)	= NULL,
	@v_vchCusCity				NVARCHAR(50)	= NULL,
	@v_vchCusProvince			NVARCHAR(50)	= NULL,
	@v_vchCusPostalCode			NVARCHAR(50)	= NULL,
	@v_vchCusCountryCode		NVARCHAR(5)		= NULL,
	@v_vchCusCountryName		NVARCHAR(50)	= NULL,
	@v_vchCusContact			NVARCHAR(50)	= NULL,
	@v_vchCusPhone				NVARCHAR(50)	= NULL,
	@v_vchCusFax				NVARCHAR(50)	= NULL,
	@v_vchCusEmail				NVARCHAR(50)	= NULL,

    @v_vchUDF1					NVARCHAR(50)	= NULL,  
    @v_vchUDF2					NVARCHAR(50)	= NULL,  
    @v_vchUDF3					NVARCHAR(50)	= NULL,  
    @v_vchUDF4					NVARCHAR(50)	= NULL,  
    @v_vchUDF5					NVARCHAR(50)	= NULL,  
	@v_vchUdf6					NVARCHAR(50)	= NULL,  
    @v_fltUDF7					FLOAT			= NULL,  
    @v_fltUDF8					FLOAT			= NULL,  
    @v_dtUDF9					DATETIME		= NULL,
    @v_dtUDF10					DATETIME		= NULL,
    @v_vchUserID				NVARCHAR(10)	= NULL,		
								
    -- Table Variables (t_wms_outbound_consignment_detail)
    @v_vchHostOutboundDetailIDGUID	VARCHAR(40)	= NULL,
    @v_vchDTWHID				NVARCHAR(25)	= NULL,
    @v_vchDTOwner				NVARCHAR(40)	= NULL,	-- Required  
    @v_vchDTOrderNumber			NVARCHAR(40)	= NULL,	-- Required  
    @v_vchDTLineNumber			NVARCHAR(10)	= NULL,	-- Required  
    @v_vchDTItemNumber			NVARCHAR(50)	= NULL,	-- Required  
    @v_fltDTQuantity			FLOAT			= NULL,	-- Required  
    @v_vchPlanDTUOM				NVARCHAR(10)	= NULL,	-- Required  
	@v_vchBaseDTUOM				NVARCHAR(10)	= NULL,	-- Required  
    @v_vchDTLPN					NVARCHAR(25)	= NULL,  
    @v_vchDTLotNumber			NVARCHAR(50)	= NULL,  
    @v_dtDTExpiryDate			DATETIME		= NULL,
    @v_vchDTExpiryDate			VARCHAR(8)		= NULL,  
    @v_vchDTSerialNumber		NVARCHAR(50)	= NULL,  
    @v_vchDTItemDescription		NVARCHAR(100)	= NULL,	  
	@v_fltQuantityShip			FLOAT			= NULL,
    @v_vchDTUDF1				NVARCHAR(50)	= NULL,  
    @v_vchDTUDF2				NVARCHAR(50)	= NULL,	
    @v_vchDTUDF3				NVARCHAR(50)	= NULL,  
    @v_vchDTUDF4				NVARCHAR(50)	= NULL,  
    @v_vchDTUDF5				NVARCHAR(50)	= NULL,  
    @v_vchDTUDF6				NVARCHAR(50)	= NULL,  
    @v_fltDTUDF7				FLOAT			= NULL,  
    @v_fltDTUDF8				FLOAT			= NULL,  
    @v_dtDTUDF9					DATETIME		= NULL, 
    @v_dtDTUDF10				DATETIME		= NULL, 
    @v_vchDTUserID				NVARCHAR(10)	= NULL,	 
    @v_vchDTGrade				NVARCHAR(40)	= NULL,   
    @v_vchDTDefaultItemStatus	NVARCHAR(50)	= NULL,
    @v_vchDTCurrentItemStatus	NVARCHAR(10)	= NULL

	-- Set Constants and Variables
	SET @v_intLocale = 1033; -- English
	SET @v_vchApplicationID = 'IMPORT INTERFACE (TABLE)';
	SET @c_vchObjName = 'usp_ProcessHostOutboundConsignment'; 
	SET @v_vchTableName = 't_host_wms_outbound_order'; 
	SET @v_vchLogType = 'ERROR IMPORT';
	SET @v_vchDevice = 'usp_ProcessHostOutboundConsignment'   

BEGIN TRY  
	--BEGIN TRANSACTION
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY'  
	-- Future, Add a Log action for inserting into the Process Log  
    
	SELECT @v_vchRecordType = record_type
		,@v_vchProcessingCode = processing_code  
		,@v_vchProcessingStatus = processing_status  
		,@v_vchWHID = wh_id
		,@v_vchOwner = owner_id
		,@v_vchOrderNumber = order_number
		,@v_vchOrderType = [type]
		,@v_vchOrderStatus = order_status
		,@v_dtOrderCreateDate = order_create_date 
		,@v_vchCustomerCode = customer_code  
		,@v_vchUDF1 = user_def1
		,@v_vchUDF2 = user_def2
		,@v_vchUDF3 = user_def3
		,@v_vchUDF4 = user_def4
		,@v_vchUDF5 = user_def5
		,@v_vchUdf6 = user_def6
		,@v_fltUDF7 = user_def7
		,@v_fltUDF8 = user_def8
		,@v_dtUDF9 =  CASE CONVERT(NVARCHAR,user_def9,112) WHEN '19000101' THEN NULL ELSE user_def9 END  
		,@v_dtUDF10 = CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
		,@v_vchUserID = create_by  
	FROM t_host_wms_outbound_order  
	WHERE host_record_id = @in_vchHostRecordID  
      
	------------------------------------------------------------------------  
	--  Check to make sure that Customer ID in the Import Data   
	--  is a valid Customer ID that is in the t_wms_customer table  
	--  Customer อาจมีหรือไม่มีก็ได้ กรณีที่เป็น "การส่งคืนสินค้า" จะมี Customer Code  
	--  Master Kool : กรณีที่เป็น Production Order ให้ Customer = MTK
	------------------------------------------------------------------------  
	IF (@v_vchOrderType = 'Production Order')
		BEGIN
			SET @v_vchCustomerCode = 'MTK'
		END

	------------------------------------------------------------  
	--  If the WH ID was NOT put into the Interface Table   
	--  then try to get it from the Rule Table  
	------------------------------------------------------------  
	IF @v_vchWHID IS NULL  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Retrieving Default Warehouse from Rule'  
			-- Future, Add a Log action for inserting into the Process Log  
		  
			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  SELECT 'Field List Warehouse ID:['+ISNULL(@v_vchWHID, 'NULL WAREHOUSE ID') + ']'
		              
			SELECT @v_vchWHID = [dbo].[usf_GetRuleValue] ('DEFAULT_WH_ID',NULL,'WH_CONTROL')
		END
	
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    
    
	IF (ISNULL(@v_vchRecordType,'') = ''
		OR ISNULL(@v_vchProcessingCode,'') = ''   
		OR ISNULL(@v_vchProcessingStatus,'') = ''  
		OR ISNULL(@v_vchWHID,'') = ''   
		OR ISNULL(@v_vchOwner,'') = ''  
		OR ISNULL(@v_vchOrderNumber,'') = '' 
		OR ISNULL(@v_vchOrderType,'') = ''
		OR ISNULL(@v_vchOrderStatus,'') = ''
		OR ISNULL(@v_vchCustomerCode,'') = ''
		OR ISNULL(@v_dtOrderCreateDate,'') = ''
		OR ISNULL(@v_vchUserID,'') = '')
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List 1:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+ ']'  
				+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+ ']'  
				+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']'  
				+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'  
				+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'  
				+ ' Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
			      
			SELECT 'Field List 2: Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'  
				+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'  
				+ ' Order Status: ['+ISNULL(@v_vchOrderStatus, '') + ']'  
				+ ' Order Create Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderCreateDate), '')+ ']'  
				+ ' User ID: ['+ISNULL(@v_vchUserID, '')+ ']'
		END  

		SET @v_vchErrorCode = 'ERROR-IFMAN-001' -- Missing Required Fields  
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
									
		SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

		SET @v_vchError = 'ERROR-MASTER'  
		GOTO WRITE_PROCESS_LOG  
	END    

	------------------------------------------------------------  
	--  Check Valid Warehouse  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse'  
	-- Future, Add a Log action for inserting into the Process Log  

    SELECT @v_vchWHIDGUID = wh_master_id, @v_vchWHID = wh_id FROM t_wms_wh WHERE wh_id = @v_vchWHID AND is_active = 'YES'
	IF (ISNULL(@v_vchWHIDGUID,'') = '')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Warehouse :[ '+ISNULL(@v_vchWHID, '')+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-LOGMAN-004' -- Invalid Warehouse  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		
			SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
										+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
			SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
										+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
		  
			SET @v_vchError = 'ERROR-MASTER'  
