									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
		  
		SET @v_vchError = 'ERROR-ITEM'  
		GOTO WRITE_PROCESS_LOG
	END

	IF (ISNULL(@v_vchCustomerCode,'') <> '')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Customer ID'  
		-- Future, Add a Log action for inserting into the Process Log    
		SET @v_vchCustomerIDGUID = NULL
		SELECT @v_vchCustomerIDGUID = customer_id
			, @v_vchCustomerName	= customer_name
			, @v_vchCusDescription	= description
			, @v_vchCusAddrLine1	= addr_line_1
			, @v_vchCusAddrLine2	= addr_line_2
			, @v_vchCusAddrLine3	= addr_line_3
			, @v_vchCusCity			= city
			, @v_vchCusProvince		= province
			, @v_vchCusPostalCode	= postal_code
			, @v_vchCusCountryCode	= country_code
			, @v_vchCusCountryName	= country_name
			, @v_vchCusContact		= contact
			, @v_vchCusPhone		= phone
			, @v_vchCusFax			= fax
			, @v_vchCusEmail		= email
		FROM t_wms_customer 
		WHERE customer_code = @v_vchCustomerCode  
		AND owner_id = @v_vchOwnerIDGUID
		AND is_active = 'YES'

		IF  @v_vchCustomerIDGUID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Record Type:[ '+ISNULL(@v_vchRecordType, '')+']'    
				-- Future, Add a Log action for inserting into the Process Log  

				SET @v_vchErrorCode = 'ERROR-IFMAN-036' --INVALID ORDER MASTER - CUSTOMER CODE DOES NOT EXIST  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
				SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		
				SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
											+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
											+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
				SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
											+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
											+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
											+ ' Customer Code: ['+ISNULL(@v_vchCustomerCode,'') + ']'
									
				SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
									   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
		  
				SET @v_vchError = 'ERROR-MASTER'  
				GOTO WRITE_PROCESS_LOG  
			END
	END

	------------------------------------------------------------  
	--  Check Valid Record Type  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Record Type'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF (@v_vchRecordType <> 'MASTER')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Record Type:[ '+ISNULL(@v_vchRecordType, '')+']'    
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
		
		SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
		  
		SET @v_vchError = 'ERROR-MASTER'  
		GOTO WRITE_PROCESS_LOG  
	END  
  
	------------------------------------------------------------  
	--  Check Valid Processing Code  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  
  
	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+']'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	

		SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
		  
		SET @v_vchError = 'ERROR-MASTER'  
		GOTO WRITE_PROCESS_LOG  
	END  
    
	------------------------------------------------------------  
	--  Check Valid Processing Status  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingStatus <> 'PENDING')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	

		SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 

		SET @v_vchError = 'ERROR-MASTER'  
		GOTO WRITE_PROCESS_LOG  
	END  
     
	------------------------------------------------------------  
	--  Check Valid Order Type  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Checking for Valid Order Type'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF @v_vchOrderType NOT IN (SELECT value_member FROM dbo.t_com_combobox_item WHERE group_name = 'ob_consignment_order_type' and is_active = 'YES')  
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Order Type'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @v_vchErrorCode = 'ERROR-IFMAN-014' -- Invalid Order Type  
		SET @v_vchLogType = 'IMPORT ERROR'  
		SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
		SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	

		SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
									+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
									+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
									
		SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
									+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
									
		SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
							   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
 
		SET @v_vchError = 'ERROR-MASTER'  
		GOTO WRITE_PROCESS_LOG  
	END

  
	----------------------------------------------------------  
	--  Check for Outbound Order Master and Get the Master ID  
	--  from the Master Outbound Order  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Outbound Order Master'  
	-- Future, Add a Log action for inserting into the Process Log  
	SET @v_vchOrderMasterIDGUID = NULL
	SELECT @v_vchOrderMasterIDGUID = ms.outbound_consignment_master_id
		,@v_vchCurrentOrderStatus = ms.order_status  
		,@v_vchCurrentOwner = ow.owner_code
		,@v_vchCurrentWHIDGUID = ms.wh_master_id
	FROM t_wms_outbound_consignment_master ms
	INNER JOIN t_wms_owner ow on ms.owner_id = ow.owner_id
	WHERE ms.outbound_order_number = @v_vchOrderNumber
	AND ms.wh_master_id = @v_vchWHIDGUID 
	
	IF ISNULL(@v_vchOrderMasterIDGUID,'') <> '' --AND @v_vchProcessingCode = 'ADD'
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END  
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END
	
	------------------------------------------------------------  
	--  Check Processing for 'DELETE' the Outbound Order.
	------------------------------------------------------------  
	IF ISNULL(@v_vchOrderMasterIDGUID,'') = '' AND @v_vchProcessingCode IN ('DELETE','UPDATE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Outbound Order is Invalid'  
			-- Future, Add a Log action for inserting into the Process Log    
		  
			SET @v_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	

			SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
										+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
										+ ' Order Ship Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderShipDate), '') + ']' 
									
			SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
										+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'

			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
 
			SET @v_vchError = 'ERROR-MASTER'  
			GOTO WRITE_PROCESS_LOG  
		END
  
	------------------------------------------------------------  
	--  Processing for 'DELETE' the Outbound Order.   
	--  Update Order Status = 'Cancel'  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingCode = 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update Order Status "CANCEL" Order:['+@v_vchOrderNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOrderStatus = 'OPEN')
				BEGIN  
					------------------------------------------------------------  
					-- Update Order Status = Cancel กรณีที่ส่งมาเป็น Delete  
					------------------------------------------------------------  
					UPDATE t_wms_outbound_consignment_master SET order_status = 'CANCEL' WHERE outbound_consignment_master_id = @v_vchOrderMasterIDGUID  

					------------------------------------------------------------  
					-- Update Process Status = COMPLETED  
					------------------------------------------------------------  
					UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
				 
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Order Status Complete'  

					COMMIT TRANSACTION  
					GOTO EXIT_LABEL  
				END  
			ELSE  
				BEGIN  
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Order Status not Available for Change.'
																				+ ' Order Number:[' + @v_vchOrderNumber  + ']'
																				+ ' Order Status:['+ISNULL(@v_vchCurrentOrderStatus, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @v_vchErrorCode = 'ERROR-IFMAN-003' -- Order Status not Available for Change  
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
												+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
												+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
												+ ' Order Ship Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderShipDate), '') + ']' 
					SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
												+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
										   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
   
					SET @v_vchError = 'ERROR-MASTER'     
					GOTO WRITE_PROCESS_LOG  
				END  
		END
  
	------------------------------------------------------------  
	--  Check the Outbound Order for a ADD duplicate.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Duplicates'   
	-- Future, Add a Log action for inserting into the Process Log   
	IF (@v_vchProcessingCode = 'ADD' and ISNULL(@v_vchOrderMasterIDGUID,'') <> '') -- Duplicate Order Error  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Found.  Order Number:'+@v_vchOrderNumber+']'  
			SET @v_vchErrorCode = 'ERROR-IFMAN-002' -- Duplicate Order Number  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
										+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
										+ ' Order Ship Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderShipDate), '') + ']' 
			SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
										+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
										+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 

			SELECT @v_vchMessage = dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale)+ '. Error Code ['+@v_vchErrorCode + '] Order Number [' + ISNULL(@v_vchOrderNumber,'')+']'  
			------------------------------------------------------------  
			--  We really have 2 options here.   
			--  1. Error out that we are trying to 'ADD" a duplicate item  
			-- 2. Make the 'ADD' into an 'UPDATE'   
			--  Either way we should produce an error to the Process Log  
			------------------------------------------------------------  
			SET @v_vchError = 'ERROR-MASTER'  
			GOTO WRITE_PROCESS_LOG  
		END  
	ELSE IF (@v_vchProcessingCode = 'ADD' AND ISNULL(@v_vchOrderMasterIDGUID,'') = '') -- Add Order Master
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'ADD' the Order .  
			--  This section should be runing for an 'ADD' with no   
			--  duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing add outbound order (Master)'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List: Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
					  + 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
					  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'  
					  + ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'   
					  + ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'   
					  + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'   
					  + ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'   
					  + ' Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '') + ']'  
					  + ' Order Ship Date: ['+ISNULL(convert(nvarchar(12),@v_dtOrderShipDate), '') + ']'   
					  + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
					-- Future, Add a Log action for inserting into the Process Log  
				END  
		
			INSERT INTO [dbo].[t_wms_outbound_consignment_master]
					([outbound_consignment_master_id]
					,[wh_master_id]
					,[outbound_order_number]
					,[owner_id]
					,[order_type]
					,[order_status]
					,[order_date]
					,[customer_id]
					,[customer_code]
					,[customer_name]
					,[cus_description]
					,[cus_addr_line_1]
					,[cus_addr_line_2]
					,[cus_addr_line_3]
					,[cus_city]
					,[cus_province]
					,[cus_postal_code]
					,[cus_country_code]
					,[cus_country_name]
					,[cus_contact]
					,[cus_phone]
					,[cus_fax]
					,[cus_email]
					,[user_def1]
					,[user_def2]
					,[user_def3]
					,[user_def4]
					,[user_def5]
					,[user_def6]
					,[user_def7]
					,[user_def8]
					,[user_def9]
					,[user_def10]
					,[create_by]
					,[create_date])
				VALUES
					(NEWID()
					,@v_vchWHIDGUID
					,@v_vchOrderNumber
					,@v_vchOwnerIDGUID		
					,@v_vchOrderType  		
					,@v_vchOrderStatus		
					,@v_dtOrderCreateDate	
					,@v_vchCustomerIDGUID  
					,@v_vchCustomerCode		
					,@v_vchCustomerName		
					,@v_vchCusDescription	
					,@v_vchCusAddrLine1		
					,@v_vchCusAddrLine2		
					,@v_vchCusAddrLine3		
					,@v_vchCusCity			
					,@v_vchCusProvince		
					,@v_vchCusPostalCode		
					,@v_vchCusCountryCode	
					,@v_vchCusCountryName	
					,@v_vchCusContact		
					,@v_vchCusPhone			
					,@v_vchCusFax			
					,@v_vchCusEmail
					,@v_vchUDF1
					,@v_vchUDF2
					,@v_vchUDF3
					,@v_vchUDF4
					,@v_vchUDF5
					,@v_vchUDF6
					,@v_fltUDF7
					,@v_fltUDF8
					,@v_dtUDF9 
					,@v_dtUDF10
					,@v_vchUserID
					,GETDATE()  
				)

			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @v_vchErrorNumber = str(@v_intSqlErrorNumber)
					SET @v_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SET @v_vchError = 'ERROR-MASTER'	
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @v_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 = 'Table Name: ' + @v_vchTableName + ']'
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SET @v_vchError = 'ERROR-MASTER'	
					GOTO WRITE_PROCESS_LOG
				END

			------------------------------------------------------------  
			-- Update Process Status = COMPLETED  
			------------------------------------------------------------  
			UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing add outbound order Completed'   
			-- Future, Add a Log action for inserting into the Process Log  

		END  
	ELSE IF (@v_vchProcessingCode = 'UPDATE' AND ISNULL(@v_vchOrderMasterIDGUID,'') <> '') -- Update Order Master 
		BEGIN
			------------------------------------------------------------  
			--  Check Order Status - No Change if Order Status not PENDING  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Order Status for Update:['+@v_vchCurrentOrderStatus+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+']'  
						  + 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +']'  
						  + 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+']'  
						  + 'Owner ID: ['+ISNULL(@v_vchOwner, '') +']'  
						  + 'Log Type: ['+ISNULL(@v_vchLogType, '') +']'  
						  + 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') +']'  
						  + 'Order Type: ['+ISNULL(@v_vchOrderType, '') +']'  
						  + 'Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '')+']'  
						  + 'Order Ship Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderShipDate), '')+']'  
						  + 'User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
					-- Future, Add a Log action for inserting into the Process Log  
				END  
		   
			IF (@v_vchCurrentOrderStatus <> 'OPEN')
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Order Status not Available for Change.'
																				+ ' Order Number:['+@v_vchOrderNumber  +']'
																				+ ' Order Status:['+ISNULL(@v_vchCurrentOrderStatus, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @v_vchErrorCode = 'ERROR-IFMAN-003' -- Order Status not Available for Change  
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
					SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
												+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
												+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']' 
												+ ' Order Ship Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderShipDate), '') + ']' 
					SELECT @v_vchProcessData4 =   'Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
												+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
										   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
										   
					SET @v_vchError = 'ERROR-MASTER'     
					GOTO WRITE_PROCESS_LOG  
				END  
			
			------------------------------------------------------------  
			--  Check Owner ID ต้องเป็นค่าเดิมที่ Interface มาครั้งแรก  
			------------------------------------------------------------ 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking owner ID for update:['+@v_vchOwner+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOwner <> @v_vchOwner)
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Owner ID not available for Change.'  
								 +' Order Number:[' + @v_vchOrderNumber + ']' 
								 +' Current Owner ID:[' + ISNULL(@v_vchCurrentOwner, '') + ']' 
								 +' Owner ID:[' + ISNULL(@v_vchOwner, '') + ']'
					-- Future, Add a Log action for inserting into the Process Log  

					SET @v_vchErrorCode = 'ERROR-IFMAN-032' -- Owner ID not available for Change 
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
												
					SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
												+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
												+ ' Current Owner ID: ['+ISNULL(@v_vchCurrentOwner, '') + ']'
												+ ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'
												
					SELECT @v_vchProcessData4 =   ' Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
												+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
												
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
										   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					     
					SET @v_vchError = 'ERROR-MASTER'  
					GOTO WRITE_PROCESS_LOG
				END
			
			------------------------------------------------------------  
			--  Check wh_master_id ต้องเป็นค่าเดิมที่ Interface มาครั้งแรก  
			------------------------------------------------------------ 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking warehouse ID for update:['+@v_vchWHID+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentWHIDGUID <> @v_vchWHIDGUID)
				BEGIN
					SELECT @v_vchCurrentWHID = wh_id FROM t_wms_wh WHERE wh_master_id = @v_vchCurrentWHIDGUID
					
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Warehouse ID not available for Change.'  
								 +' Order Number:[' + @v_vchOrderNumber + ']' 
								 +' Current Warehouse ID:[' + ISNULL(@v_vchCurrentWHID, '') + ']' 
								 +' Warehouse ID:[' + ISNULL(@v_vchWHID, '') + ']'
					-- Future, Add a Log action for inserting into the Process Log  

					SET @v_vchErrorCode = 'ERROR-IFMAN-033' -- Warehouse ID not available for Change.
					SET @v_vchLogType = 'IMPORT ERROR'  
					SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
									+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
									
					SELECT @v_vchProcessData2 =   'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
												+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
												+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
												
					SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
												+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'  
												+ ' Current Warehouse ID: ['+ISNULL(@v_vchCurrentWHID, '') + ']'
												+ ' Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']' 
												
					SELECT @v_vchProcessData4 =   ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']' 
												+ ' Order Date: ['+CONVERT(NVARCHAR,ISNULL(@v_dtOrderCreateDate, '')) + ']'
												+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
					SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
										   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
					     
					SET @v_vchError = 'ERROR-MASTER'  
					GOTO WRITE_PROCESS_LOG
				END
		  
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Processing Code for Update'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+ ']'   
					  + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
					  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']'   
					  + ' Owner ID: ['+ISNULL(@v_vchOwner, '') + ']'   
					  + ' Log Type: ['+ISNULL(@v_vchLogType, '')  + ']'  
					  + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'   
					  + ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'   
					  + ' Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '') + ']'  
					  + ' Order Ship Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderShipDate), '')+ ']'          
					SELECT 'UDF1: ['+ISNULL(@v_vchUDF1, '') + ']'  
						+' UDF2: ['+ISNULL(@v_vchUDF2, '')+ ']' 
						+' UDF3: ['+ISNULL(@v_vchUDF3, '') + ']'  
						+' UDF4: ['+ISNULL(@v_vchUDF4, '') + ']'  
						+' UDF5: ['+ISNULL(@v_vchUDF5, '') + ']'  
						+' UDF6: ['+ISNULL(@v_vchUDF6, '') + ']'  
						+' UDF7: ['+ISNULL(str(@v_fltUDF7, 12), '')+ ']'   
						+' UDF8: ['+ISNULL(str(@v_fltUDF8, 12), '') + ']'  
						+' UDF9: ['+ISNULL(convert(NVARCHAR(12), @v_dtUDF9), '')+ ']'   
						+' UDF10: ['+ISNULL(convert(NVARCHAR(12), @v_dtUDF10), '')+ ']'   
						+' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
				END  
		  
			IF @v_vchProcessingCode = 'UPDATE'  
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Outbound Order Master'  
					-- Future, Add a Log action for inserting into the Process Log 
					
					IF ISNULL(@v_vchOrderMasterIDGUID,'') <> ''
						BEGIN
							IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Updating Order:['+ @v_vchOrderNumber +']'  
							---------------------------------------------------
							--Delete Inbound Detail Before Update
							---------------------------------------------------
							DELETE t_wms_outbound_consignment_detail WHERE outbound_consignment_master_id = @v_vchOrderMasterIDGUID 
            
							UPDATE [dbo].[t_wms_outbound_consignment_master]
							   SET [order_type] = @v_vchOrderType
								  ,[order_date] = @v_dtOrderCreateDate
								  ,[customer_id] = @v_vchCustomerIDGUID
								  ,[customer_code] = @v_vchCustomerCode
								  ,[customer_name] = @v_vchCustomerName  
								  ,[cus_description] = @v_vchCusDescription
								  ,[cus_addr_line_1] = @v_vchCusAddrLine1 
								  ,[cus_addr_line_2] = @v_vchCusAddrLine2
								  ,[cus_addr_line_3] = @v_vchCusAddrLine3 
								  ,[cus_city] = @v_vchCusCity
								  ,[cus_province] = @v_vchCusProvince
								  ,[cus_postal_code] = @v_vchCusPostalCode
								  ,[cus_country_code] = @v_vchCusCountryCode
								  ,[cus_country_name] = @v_vchCusCountryName
								  ,[cus_contact] = @v_vchCusContact	
								  ,[cus_phone] = @v_vchCusPhone		
								  ,[cus_fax] = @v_vchCusFax
								  ,[cus_email] = @v_vchCusEmail
								  ,[user_def1] = @v_vchUDF1
								  ,[user_def2] = @v_vchUDF2
								  ,[user_def3] = @v_vchUDF3
								  ,[user_def4] = @v_vchUDF4
								  ,[user_def5] = @v_vchUDF5
								  ,[user_def6] = @v_vchUDF6
								  ,[user_def7] = @v_fltUDF7
								  ,[user_def8] = @v_fltUDF8
								  ,[user_def9] = @v_dtUDF9 
								  ,[user_def10] = @v_dtUDF10
								  ,[update_by] = @v_vchUserID
								  ,[update_date] = GETDATE()
							 WHERE [outbound_consignment_master_id] = @v_vchOrderMasterIDGUID

							---------------------------------------------------   
							-- Update Process Status = COMPLETED  
							---------------------------------------------------  
							UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

							IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Outbound Order Complete (Master)'  
						END
				END
		END
 
	------------------------------------------------------------  
	--*******************OUTBOUND ORDER DETAIL*******************  
	------------------------------------------------------------  

	IF  EXISTS (SELECT host_record_id FROM dbo.t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
	BEGIN  
		OUTBOUND_DETAIL_LABEL:
		
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Outbound Order Detail Started'   
		-- Future, Add a Log action for inserting into the Process Log 
		
		-------------------------------------------------------
		-- Clear Value before set the value to variable
		-------------------------------------------------------
		SET @v_vchTableName = 't_host_wms_outbound_order_detail'
		SET @v_vchHostOutboundDetailIDGUID = NULL
		SET @v_vchDTDefaultItemStatus = NULL
		SET @v_vchOrderMasterIDGUID = NULL
		SET @v_vchOrderDetailIDGUID = NULL
		SET @v_vchWHIDGUID = NULL
		SET @v_vchWHItemIDGUID = NULL	
		SET @v_vchItemMasterID = NULL
		SET @v_vchBaseItemUOMIDGUID = NULL
		SET @v_vchOwnerIDGUID = NULL
		SET @v_vchDTCurrentItemStatus = NULL
		
		SELECT TOP 1 @v_vchHostOutboundDetailIDGUID = outbound_order_detail_id  
			,@v_vchRecordType = record_type  
			,@v_vchProcessingCode = processing_code  
			,@v_vchProcessingStatus = processing_status  
			,@v_vchDTOwner = owner_id  
			,@v_vchDTWHID = wh_id
			,@v_vchDTOrderNumber = order_number  
			,@v_vchDTLineNumber = line_number  
			,@v_vchDTItemNumber = item_number  
			,@v_fltDTQuantity = order_quantity  
			,@v_vchPlanDTUOM = uom  
			,@v_vchDTLPN = (CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END)
			,@v_vchDTLotNumber = (CASE ISNULL(lot_number,'') WHEN '' THEN NULL ELSE lot_number END)
			,@v_dtDTExpiryDate = expiry_date
			,@v_vchDTExpiryDate = CASE CONVERT(NVARCHAR,EXPIRY_DATE,112) WHEN '19000101' THEN NULL ELSE CONVERT(VARCHAR(8),expiry_date,112) END
			,@v_vchDTSerialNumber = serial_number
			,@v_vchDTItemDescription = item_description  
			,@v_vchDTUDF1 = user_def1  
			,@v_vchDTUDF2 = user_def2 
			,@v_vchDTUDF3 = user_def3
			,@v_vchDTUDF4 = user_def4
			,@v_vchDTUDF5 = user_def5
			,@v_vchDTUDF6 = user_def6
			,@v_fltDTUDF7 = user_def7
			,@v_fltDTUDF8 = user_def8
			,@v_dtDTUDF9  = CASE CONVERT(NVARCHAR,user_def9	,112) WHEN '19000101' THEN NULL ELSE user_def9 END
			,@v_dtDTUDF10  = CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
			,@v_vchDTUserID = create_by
			,@v_vchDTGrade = grade
			,@v_vchDTDefaultItemStatus = default_item_status
		FROM t_host_wms_outbound_order_detail  
		WHERE host_record_id = @in_vchHostRecordID
		AND order_number = @in_vchOrderNumber
		AND processing_status = 'PENDING'
		ORDER BY line_number  
     
  		IF ISNULL(@v_vchDTDefaultItemStatus,'') = ''
			BEGIN
				SET @v_vchDTDefaultItemStatus = 'Available'
			END

		----------------------------------------------------------  
		--  Check for Required Fields  
		--  log_type, warehouse, tran code, start tran date, location, quantity   
		--  app_id, device, user id, error_code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Required Fields'  
		-- Future, Add a Log action for inserting into the Process Log   

		IF ISNULL(@v_vchRecordType,'') = ''  
			OR ISNULL(@v_vchProcessingCode,'') = ''  
			OR ISNULL(@v_vchProcessingStatus,'') = ''  
			OR ISNULL(@v_vchDTOwner,'') = '' 
			OR ISNULL(@v_vchDTOrderNumber,'') = ''
			OR ISNULL(@v_vchDTLineNumber,'') = ''
			OR ISNULL(@v_vchDTItemNumber,'') = ''
			OR ISNULL(@v_fltDTQuantity,'') = '' 
			OR ISNULL(@v_vchPlanDTUOM,'') = '' 
			OR ISNULL(@v_vchDTUserID,'') = '' 
		BEGIN  
			------------------------------------------------------------  
			--  Missing Required Fields   
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Fields'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
			SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') +']'  
				+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+']'  
				+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+']'  
				+ 'Owner ID: ['+ISNULL(@v_vchDTOwner, '') +']'  
				+ 'Log Type: ['+ISNULL(@v_vchLogType, '') +']'  
				+ 'Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') +']'  
				+ 'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') +']'  
				+ 'Item Number: ['+ISNULL(@v_vchDTItemNumber, '') +']'  
				+ 'UOM: ['+ISNULL(@v_vchPlanDTUOM, '')+']'  
				+ 'Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '')+']'  
				+ 'User ID: ['+ISNULL(@v_vchUserID, '') + ']'        
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-IFMAN-001' -- Missing Required Fields  
			SET @v_vchLogType = 'IMPORT ERROR'  

			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
