										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'										 
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']' 
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
