			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
