		-------------------------------------------------------------------------  
		--  Set ข้อมูล outbound_order_master_id  
		-------------------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Valid Outbound Order Master'  
		-- Future, Add a Log action for inserting into the Process Log
		SET @v_vchOrderMasterIDGUID = NULL;
		SET @v_vchCurrentOrderStatus = NULL;
		SET @v_vchOrderType = NULL;
		SELECT @v_vchOrderMasterIDGUID = outbound_consignment_master_id  
			,@v_vchCurrentOrderStatus = order_status
			,@v_vchOrderType = order_type
		FROM t_wms_outbound_consignment_master  
		WHERE outbound_order_number = @v_vchDTOrderNumber   
		AND wh_master_id = @v_vchWHIDGUID  
		AND owner_id = @v_vchOwnerIDGUID  

		------------------------------------------------------------  
		--  Check for Outbound Order Master and Get the Master ID  
		--  from the Master Outbound Order  
		------------------------------------------------------------        
		IF  ISNULL(@v_vchOrderMasterIDGUID,'') = ''
		BEGIN  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Outbound Order is Invalid Order Number:['+ @v_vchOrderNumber +']'  
			-- Future, Add a Log action for inserting into the Process Log   

			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
			BEGIN
				SELECT 'Field List 1:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
				+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'    
				+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'    
				+ ' Warehouse ID: ['+ISNULL(@v_vchWHID, '')+ ']'  
				+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'  
				+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'  
				+ ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'    
				 

				SELECT 'Field List 2: Order Number GUID: ['+ISNULL(@v_vchOrderMasterIDGUID, '') + ']'   
				+ ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   
				+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'   
				+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']'
				+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'  
				+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
			END
			-- Future, Add a Log action for inserting into the Process Log   

			SET @v_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record  
			SET @v_vchLogType = 'IMPORT ERROR'  
			
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'  
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']' 
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')       

			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END  
          
		------------------------------------------------------------  
		--  Check Valid Record Types  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Type'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchRecordType <> 'DETAIL')
		BEGIN  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
			SET @v_vchLogType = 'IMPORT ERROR'  

			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'  
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']' 
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')       

			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END     
     
		------------------------------------------------------------  
		--  Check Valid Processing Code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE','DELETE') -- Do we want to DELETE JUST a LINE?  , 'DELETE')  
		BEGIN  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
			SET @v_vchLogType = 'IMPORT ERROR'  

			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'  
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']' 
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')       
  
			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END  


		------------------------------------------------------------  
		--  Check Valid Processing Status  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Status'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
		BEGIN  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'  
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']' 
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')       

			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END
     
     
		------------------------------------------------------------
		--  Get Item GUID & Item UOM GUID  
		------------------------------------------------------------
		SET @v_vchWHItemIDGUID = NULL
		SET @v_vchItemMasterID = NULL
		SET @v_vchDTItemDescription = NULL 
		SELECT @v_vchWHItemIDGUID = whItem.wh_item_master_id 
			, @v_vchItemMasterID = item.item_master_id
			, @v_vchDTItemDescription = item.description
			, @v_vchDTItemNumber = item.item_number
		FROM t_wms_item item
		LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id
		WHERE item.item_number = @v_vchDTItemNumber
		AND whItem.wh_master_id = @v_vchWHIDGUID
		AND item.owner_id = @v_vchOwnerIDGUID
		AND whItem.is_active = 'YES'
  
		------------------------------------------------------------  
		--  Check for Valid Item in the Warehouse  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse Item'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF  @v_vchWHItemIDGUID IS NULL  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid item in warehouse'  
			-- Future, Add a Log action for inserting into the Process Log    

			SET @v_vchErrorCode = 'ERROR-IFMAN-011' -- Invalid Item in Warehouse  
			SET @v_vchLogType = 'IMPORT ERROR'   
			
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
										
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']' 
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'
										
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END

		----------------------------------------------------------
		--Get Primary UOM
		----------------------------------------------------------
		DECLARE @v_vchPrimaryUOM			VARCHAR(10) = ''
		DECLARE @v_vchPlanItemUOMIDGUID		VARCHAR(40) = ''
		DECLARE @v_vchPlanConversionFactor	VARCHAR(40) = ''
		SET @v_vchBaseItemUOMIDGUID = NULL;
		SET @v_vchBaseDTUOM = NULL;
		SET @v_vchBaseConversionFactor = NULL;

		SELECT @v_vchPlanItemUOMIDGUID = item_uom_id
			, @v_vchPlanConversionFactor = conversion_factor
			, @v_vchPlanDTUOM = uom
			, @v_vchPrimaryUOM = primary_uom
		FROM  t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID
		AND (uom = @v_vchPlanDTUOM)
		AND is_active = 'YES'
		
		-------------------------------------------------------------------
		-- คำนวณ Qty เป็นหน่วย Base
		-------------------------------------------------------------------
		IF @v_vchPrimaryUOM <> 'YES'
			BEGIN
				SELECT @v_vchBaseItemUOMIDGUID = item_uom_id
					, @v_vchBaseConversionFactor = conversion_factor
					, @v_vchBaseDTUOM = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				SET @v_fltDTQuantity = ROUND((@v_fltDTQuantity * @v_vchPlanConversionFactor),@ROUND)
			END
		ELSE
			BEGIN
				--กรณีที่เป็นหน่วยเล็กที่สุดแล้ว
				SET @v_vchBaseItemUOMIDGUID = @v_vchPlanItemUOMIDGUID
				SET @v_vchBaseDTUOM = @v_vchPlanDTUOM
			END

		----------------------------------------------------------
		--  Check for Valid Item UOM  
		----------------------------------------------------------
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Valid Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF  @v_vchBaseItemUOMIDGUID IS NULL  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item UOM is Invalid'  
			-- Future, Add a Log action for inserting into the Process Log    

			SET @v_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid UOM Detail in Import Data - No UOM Record  
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
										+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
			SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
										+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
										+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
										
			SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']' 
										+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
										+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
										+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
			
			SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
										+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
										+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
										+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
										+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'
										
			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
								   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

			SET @v_vchError = 'ERROR-DETAIL'  
			GOTO WRITE_PROCESS_LOG  
		END      
       		
		-------------------------------------------------------------------  
		--  Processing for 'DELETE' the Outbound Order.  
		-------------------------------------------------------------------
		SET @v_vchOrderDetailIDGUID = NULL;
		SELECT @v_vchOrderDetailIDGUID = outbound_consignment_detail_id  
			,@v_fltQuantityShip = quantity_ship  
		FROM t_wms_outbound_consignment_detail  
		WHERE outbound_consignment_master_id = @v_vchOrderMasterIDGUID  
		AND wh_item_master_id = @v_vchWHItemIDGUID  
		AND line_number = @v_vchDTLineNumber
		
       
		-------------------------------------------------------------------------  
		--  ลบข้อมูล โดยที่จะต้องมีเงื่อนไข ดังนี้  
		--  Processing code = Delete  
		--  Quantity Ship = 0
		--  จะต้องมี Record Order Detail ID ที่ Item Number และ Line Number ตรงกัน  
		-------------------------------------------------------------------------  
		IF @v_vchProcessingCode = 'DELETE'  
			BEGIN
				IF ((@v_vchOrderDetailIDGUID IS NOT NULL) AND (ISNULL(@v_fltQuantityShip,0) = 0) AND (@v_vchCurrentOrderStatus <> 'OPEN'))  
					BEGIN  
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Delete Processing for Item Number:['+@v_vchDTItemNumber+']'  
						-- Future, Add a Log action for inserting into the Process Log  

						DELETE t_wms_outbound_consignment_detail WHERE outbound_consignment_detail_id = @v_vchOrderDetailIDGUID  

						---------------------------------------------------   
						-- Update Process Status = COMPLETED  
						---------------------------------------------------  
						UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED'  WHERE outbound_order_detail_id = @v_vchHostOutboundDetailIDGUID  

						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete item number completed. [Outbound Order Detail]'  
						-- Future, Add a Log action for inserting into the Process Log  

						------------------------------------------------------------------------------
						-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
						------------------------------------------------------------------------------
						IF  EXISTS (SELECT * FROM t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)
							BEGIN
								GOTO OUTBOUND_DETAIL_LABEL;   
							END
						ELSE
							BEGIN
								GOTO EXIT_LABEL;
							END
					END  
				ELSE  
					BEGIN  
						IF (@v_vchOrderDetailIDGUID IS NULL) 
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @v_vchErrorCode = 'ERROR-IFMAN-031' --INVALID ORDER DETAIL IN IMPORT DATA - NO DETAIL RECORD.  
								SET @v_vchLogType = 'IMPORT ERROR'  
								SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
															+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
								SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
															+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
															+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
								SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']' 
															+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
															+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
															+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
								SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
															+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
															+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
															+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
															+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'
								SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
													   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
								SET @v_vchError = 'ERROR-DETAIL'  
								GOTO WRITE_PROCESS_LOG 
							END 
							
						IF ISNULL(@v_fltQuantityShip,0) > 0 
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @v_vchErrorCode = 'ERROR-IFMAN-035' -- Cannot delete item. Because the quantity ship is greater than 0.  
								SET @v_vchLogType = 'IMPORT ERROR'  

								SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
								
								SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
															+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
															+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'
															+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
															
								SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']' 
															+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
															+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
															+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'
								
								SELECT @v_vchProcessData4 =  ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
															+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
															+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
															+ ' Quantity Ship: ['+ISNULL(str(@v_fltQuantityShip, 12), '') + ']'
															+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
															
								SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
													   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
								SET @v_vchError = 'ERROR-DETAIL'  
								GOTO WRITE_PROCESS_LOG  
							END
					END  
			END  
      
		-------------------------------------------------------------------------  
		--  Check Data for Add or Update  
		------------------------------------------------------------------------- 
		SET @v_vchOrderDetailIDGUID = NULL    
		SELECT @v_vchOrderDetailIDGUID = outbound_consignment_detail_id  
		FROM t_wms_outbound_consignment_detail  
		WHERE outbound_consignment_master_id = @v_vchOrderMasterIDGUID  
		AND line_number = @v_vchDTLineNumber
		IF ISNULL(@v_vchOrderDetailIDGUID,'') <> '' --AND @v_vchProcessingCode = 'ADD' 
			BEGIN  
				SET @v_vchProcessingCode = 'UPDATE'  
			END 
		ELSE
			BEGIN
				SET @v_vchProcessingCode = 'ADD'  
			END
		
		------------------------------------------------------------  
		--  Check the Outbound Order for a ADD duplicate.  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Lines'   
		-- Future, Add a Log action for inserting into the Process Log		
          
		IF (@v_vchProcessingCode = 'ADD' AND ISNULL(@v_vchOrderDetailIDGUID,'') <> '')  -- Duplicate Order Error  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Found.  Order Number:'+@v_vchDTOrderNumber+'] Line Number:['+@v_vchDTLineNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log   

				SET @v_vchErrorCode = 'ERROR-IFMAN-007' -- Duplicate Line Number  
				SET @v_vchLogType = 'IMPORT ERROR'  
				SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
											+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				
				SELECT @v_vchProcessData2 =   'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: [' + ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: [' + ISNULL(@v_vchProcessingStatus, '') + ']'	
											
				SELECT @v_vchProcessData3 =   ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']' 
											+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') +']'
											+ ' Warehouse ID: ['+ISNULL(@v_vchDTWHID, '') + ']'  
											+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'	
				
				SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
											+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
											+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
											+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'   
											+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']'
											
				SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
									   + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
 
				------------------------------------------------------------  
				--  We really have 2 options here.   
				--  1. Error out that we are trying to 'ADD" a duplicate item  
				-- 2. Make the 'ADD' into an 'UPDATE'   
				--  Either way we should produce an error to the Process Log  
				------------------------------------------------------------  
				SET @v_vchError = 'ERROR-DETAIL'  
				GOTO WRITE_PROCESS_LOG
			END     
    
		ELSE IF (@v_vchProcessingCode = 'ADD' AND ISNULL(@v_vchOrderDetailIDGUID,'') = '')  -- ADD Outbound Order Detail  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Detail Line'  
				-- Future, Add a Log action for inserting into the Process Log  

				IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
					BEGIN
						SELECT 'Field List 1:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
								+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
								+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'  
								+ ' Warehouse ID: ['+ISNULL(@v_vchWHID, '') + ']'   
								+ ' Owner ID: ['+ISNULL(@v_vchDTOwner, '') + ']'  
								+ ' Log Type: ['+ISNULL(@v_vchLogType, '') + ']'  
								+ ' Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'   
						      
						SELECT 'Field List 2: Order Number GUID: ['+ISNULL(@v_vchOrderMasterIDGUID, '') + ']' 
								+ ' Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'  
								+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']'  
								+ ' UOM: ['+ISNULL(@v_vchPlanDTUOM, '') + ']'  
								+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']'  
								+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'         
					END
				
				IF @v_vchOrderType = 'Production Order'
					BEGIN
						DECLARE @v_vchCustID			VARCHAR(40) = NULL,
								@v_vchCustCode			NVARCHAR(40)	= NULL,  
								@v_vchCustName			NVARCHAR(200)	= NULL,
								@v_vchCustDesc			NVARCHAR(200)	= NULL,
								@v_vchCustAddrLine1		NVARCHAR(300)	= NULL,
								@v_vchCustAddrLine2		NVARCHAR(300)	= NULL,
								@v_vchCustAddrLine3		NVARCHAR(300)	= NULL,
								@v_vchCustCity			NVARCHAR(50)	= NULL,
								@v_vchCustProvince		NVARCHAR(50)	= NULL,
								@v_vchCustPostalCode	NVARCHAR(50)	= NULL,
								@v_vchCustCountryCode	NVARCHAR(5)		= NULL,
								@v_vchCustCountryName	NVARCHAR(50)	= NULL,
								@v_vchCustContact		NVARCHAR(50)	= NULL,
								@v_vchCustPhone			NVARCHAR(50)	= NULL,
								@v_vchCustFax			NVARCHAR(50)	= NULL,
								@v_vchCustEmail			NVARCHAR(50)	= NULL

						SELECT @v_vchCustID			= custLoc.customer_id 
							, @v_vchCustCode		= cust.customer_code 
							, @v_vchCustName		= cust.customer_name
							, @v_vchCustDesc		= cust.description
							, @v_vchCustAddrLine1	= cust.addr_line_1
							, @v_vchCustAddrLine2	= cust.addr_line_2
							, @v_vchCustAddrLine3	= cust.addr_line_3
							, @v_vchCustCity		= cust.city
							, @v_vchCustProvince	= cust.province
							, @v_vchCustPostalCode	= cust.postal_code
							, @v_vchCustCountryCode	= cust.country_code
							, @v_vchCustCountryName	= cust.country_name
							, @v_vchCustContact		= cust.contact
							, @v_vchCustPhone		= cust.phone
							, @v_vchCustFax			= cust.fax
							, @v_vchCustEmail		= cust.email
						FROM t_wms_location loc
						INNER JOIN t_wms_customer_location custLoc ON loc.location_id = custLoc.location_id
						INNER JOIN t_wms_customer cust ON custLoc.customer_id = cust.customer_id
						WHERE loc.wh_master_id = @v_vchWHIDGUID
						AND loc.location = @v_vchDTUDF1
						AND cust.is_active = 'YES'
						IF (ISNULL(@v_vchCustID,'') <> '')
							BEGIN
								UPDATE t_wms_outbound_consignment_master SET 
								   [customer_id] = @v_vchCustID
								  ,[customer_code] = @v_vchCustCode
								  ,[customer_name] = @v_vchCustName
								  ,[cus_description] = @v_vchCustDesc
								  ,[cus_addr_line_1] = @v_vchCustAddrLine1
								  ,[cus_addr_line_2] = @v_vchCustAddrLine2
								  ,[cus_addr_line_3] = @v_vchCustAddrLine3
								  ,[cus_city] = @v_vchCustCity
								  ,[cus_province] = @v_vchCustProvince
								  ,[cus_postal_code] = @v_vchCustPostalCode
								  ,[cus_country_code] = @v_vchCustCountryCode
								  ,[cus_country_name] = @v_vchCustCountryName
								  ,[cus_contact] = @v_vchCustContact
								  ,[cus_phone] = @v_vchCustPhone
								  ,[cus_fax] = @v_vchCustFax
								  ,[cus_email] = @v_vchCustEmail
								WHERE outbound_consignment_master_id = @v_vchOrderMasterIDGUID
							END
					END

				--Outbound Detail ของ Order
				INSERT INTO [dbo].[t_wms_outbound_consignment_detail]
					   ([outbound_consignment_detail_id]
					   ,[outbound_consignment_master_id]
					   ,[line_number]
					   ,[wh_item_master_id]
					   ,[item_master_id]
					   ,[item_number]
					   ,[item_description]
					   ,[quantity_order]
					   ,[item_uom_id]
					   ,[item_status]
					   ,[lpn]
					   ,[lot_number]
					   ,[expiry_date]
					   ,[serial_number]
					   ,[default_item_status]
					   ,[user_def1]
					   ,[user_def2]
					   ,[user_def3]
					   ,[user_def4]
					   ,[user_def5]
					   ,[user_def6]
					   ,[user_def7]
					   ,[user_def8]
					   ,[user_def9]
					   ,[user_def10]
					   ,[create_by]
					   ,[create_date]
					   ,[interface_plan_uom_id]
					   ,[interface_plan_uom])
				 VALUES
					   (NEWID()
					   ,@v_vchOrderMasterIDGUID
					   ,@v_vchDTLineNumber
					   ,@v_vchWHItemIDGUID
					   ,@v_vchItemMasterID
					   ,@v_vchDTItemNumber
					   ,@v_vchDTItemDescription
					   ,@v_fltDTQuantity
					   ,@v_vchBaseItemUOMIDGUID
					   ,'NEW'
					   ,@v_vchDTLPN
					   ,@v_vchDTLotNumber
					   ,@v_vchDTExpiryDate
					   ,@v_vchDTSerialNumber
					   ,@v_vchDTDefaultItemStatus
					   ,@v_vchDTUDF1  
					   ,@v_vchDTUDF2  
					   ,@v_vchDTUDF3   
					   ,@v_vchDTUDF4
					   ,@v_vchDTUDF5
					   ,@v_vchDTUDF6
					   ,@v_fltDTUDF7
					   ,@v_fltDTUDF8
					   ,@v_dtDTUDF9
					   ,@v_dtDTUDF10
					   ,@v_vchUserID
					   ,GETDATE()
					   ,@v_vchPlanItemUOMIDGUID
					   ,@v_vchPlanDTUOM)

				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @v_vchErrorNumber = str(@v_intSqlErrorNumber)
						SET @v_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						
						SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
													+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						
						SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SET @v_vchError = 'ERROR-DETAIL'  
						GOTO WRITE_PROCESS_LOG
					END
					
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @v_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' 
													+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						
						SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' 
												+ ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
						SET @v_vchError = 'ERROR-DETAIL'  
						GOTO WRITE_PROCESS_LOG
					END
	        
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED' WHERE outbound_order_detail_id = @v_vchHostOutboundDetailIDGUID  

				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing add outbound detail completed'      
			END
   
		IF  EXISTS (SELECT * FROM t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)    
			GOTO OUTBOUND_DETAIL_LABEL
	END  

	--COMMIT TRANSACTION;
	SET @out_vchErrorCode = 0;
	GOTO EXIT_LABEL  

-----------------------------------------------------------------------------------
-- WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:
	--ROLLBACK TRANSACTION;
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
	-- Future, Add a Log action for inserting into the Process Log
	
	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@v_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
				+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
	END
		
	INSERT INTO [dbo].[t_com_process_log]
		([app_id]
		,[log_type]
		,[warehouse]
		,[device]
		,[process]
		,[process_datetime]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[message]
		,[create_date]
		,[create_by])
	VALUES
		( LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
		, LEFT(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25)
		, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
		, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
		, GETDATE()
		, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
		, LEFT(@v_vchProcessData2, 1000)
		, LEFT(@v_vchProcessData3, 1000)
		, LEFT(@v_vchProcessData4, 1000)
		, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
		, GETDATE()
		, ISNULL(LEFT(@v_vchUserID, 10), 'OGA'))

	SET @v_vchStatus = 'FAIL'
	
	
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  

	UPDATE t_host_wms_outbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_outbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_outbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID

   
 GOTO EXIT_LABEL;
END TRY  

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
	BEGIN CATCH
	--ROLLBACK TRANSACTION;

		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = 'Order Number: ' + @v_vchOrderNumber
		SET  @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		SET @v_vchStatus = 'FAIL'
		
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id]
			   ,[log_type]
			   ,[warehouse]
			   ,[device]
			   ,[process]
			   ,[process_datetime]
			   ,[data_1]
			   ,[data_2]
			   ,[data_3]
			   ,[data_4]
			   ,[message]
			   ,[create_date]
			   ,[create_by])
		 VALUES
		 		(LEFT(ISNULL(@v_vchApplicationID, 'NO APP ID'), 40)
		 		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL(@v_vchWHID, 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, GETDATE()
				, ISNULL(@v_vchUserID,'OGA'))	
			
		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  

		UPDATE t_host_wms_outbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_outbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_outbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  

	END CATCH
  
  
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
		
	SET @out_vchErrorCode = 0
	RETURN (@out_vchErrorCode)
END


