/****** Object:  StoredProcedure [dbo].[usp_ProcessHostOutboundOrder]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostOutboundOrder]  
	@in_vchApplicationID	VARCHAR(40),			--Required  
	@in_vchApplicationName	NVARCHAR(10),			--Required  
	@in_vchHostRecordID		VARCHAR(40),			--Required  
	@in_vchDevice			NVARCHAR(50),			--Required  
	@in_vchUserID			NVARCHAR(25) = NULL,	--Required  
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS  
BEGIN
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)',
			@c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostOutboundOrder',
			@v_intSqlErrorNumber    INTEGER,
			@v_intSqlErrorLine		INTEGER,
			@v_intSqlErrorState		INTEGER,
			@v_intSqlErrorSeverity	INTEGER,
			@v_vchSqlErrorMessage	NVARCHAR(2500),
			@v_vchSqlErrorProcedure NVARCHAR(200),
			@v_vchProcessData1		NVARCHAR(100),
			@v_vchProcessData2		NVARCHAR(100),
			@v_vchProcessData3		NVARCHAR(100),
			@v_vchProcessData4		NVARCHAR(100),
			@v_nErrorNumber			INTEGER,
			@v_vchMessage           NVARCHAR(500),
			@v_nRowCount            INTEGER,
			@v_intLocale			INTEGER	= 1033, -- 1033 : English, 1054 : THAI
			@Round					INT,
			@v_vchErrorType			VARCHAR(25),

			--  Log Handling Variables
			@v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT',
			@v_intLogLevel          INTEGER = 3,				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
			@v_vchLogAction			NVARCHAR(25) = 'PRINT',	-- PRINT, LOG,   
 			@v_vchTableName			NVARCHAR(50),
	
			-- Local Variables
			@v_vchWhMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwnerID				UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchOutboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchCurrentOrderStatus	NVARCHAR(10) = NULL, -- ใช้สำหรับเก็บ Status ของ Order ก่อน Interface
			@v_vchCurrentOwnerCode		NVARCHAR(40) = NULL, -- ใช้สำหรับเก็บค่า Owner ก่อนการ Update ซึ่งถ้าส่งค่าใหม่มาจะไม่สามารถ Update ได้เนื่องจากกระทบข้อมูลใน Detail

			--CUSTOMER
			@v_vchCustomerID			UNIQUEIDENTIFIER = NULL,
			@v_vchCustomerCode			NVARCHAR(40)	= NULL, 
			@v_vchCustomerName			NVARCHAR(300)	= NULL,
			@v_vchCusDescription		NVARCHAR(200)	= NULL,
			@v_vchCusAddrLine1			NVARCHAR(300)	= NULL,
			@v_vchCusAddrLine2			NVARCHAR(300)	= NULL,
			@v_vchCusAddrLine3			NVARCHAR(300)	= NULL,
			@v_vchCusCity				NVARCHAR(100)	= NULL,
			@v_vchCusProvince			NVARCHAR(100)	= NULL,
			@v_vchCusPostalCode			NVARCHAR(50)	= NULL,
			@v_vchCusCountryCode		NVARCHAR(5)		= NULL,
			@v_vchCusCountryName		NVARCHAR(100)	= NULL,
			@v_vchCusContact			NVARCHAR(50)	= NULL,
			@v_vchCusPhone				NVARCHAR(50)	= NULL,
			@v_vchCusFax				NVARCHAR(50)	= NULL,
			@v_vchCusEmail				NVARCHAR(50)	= NULL,
   
			--SHIP TO  
			@v_vchShipToCode			NVARCHAR(40)	= NULL,
			@v_vchShipToName			NVARCHAR(300)	= NULL,
			@v_vchShipToAddr1			NVARCHAR(300)	= NULL,
			@v_vchShipToAddr2			NVARCHAR(300)	= NULL,
			@v_vchShipToAddr3			NVARCHAR(300)	= NULL,
			@v_vchShipToCity			NVARCHAR(100)	= NULL,
			@v_vchShipToProvince		NVARCHAR(100)	= NULL,
			@v_vchShipToPostalCode		NVARCHAR(50)	= NULL,
			@v_vchShipToCountryCode		NVARCHAR(5)		= NULL,
			@v_vchShipToCountryName 	NVARCHAR(100)	= NULL,
			@v_vchShipToContactName 	NVARCHAR(255)	= NULL,
			@v_vchShipToPhone			NVARCHAR(50)	= NULL,
			@v_vchShipToFax				NVARCHAR(50)	= NULL,
			@v_vchShipToEmail			NVARCHAR(50)	= NULL,
	
			--BILL TO 
			@v_vchBillToCode			NVARCHAR(40)	= NULL,
			@v_vchBillToName			NVARCHAR(300)	= NULL,
			@v_vchBillToAddr1			NVARCHAR(300)	= NULL,
			@v_vchBillToAddr2			NVARCHAR(300)	= NULL,
			@v_vchBillToAddr3			NVARCHAR(300)	= NULL,
			@v_vchBillToCity			NVARCHAR(100)	= NULL,
			@v_vchBillToProvince		NVARCHAR(100)	= NULL,
			@v_vchBillToPostalCode		NVARCHAR(50)	= NULL,
			@v_vchBillToCountry			NVARCHAR(5)		= NULL,
			@v_vchBillToCountryName 	NVARCHAR(100)	= NULL,
			@v_vchBillToContactName 	NVARCHAR(50)	= NULL,
			@v_vchBillToPhoneNumber 	NVARCHAR(50)	= NULL, 
    
			@v_vchUDF1					NVARCHAR(255)	= NULL,
			@v_vchUDF2					NVARCHAR(2000)	= NULL,
			@v_vchUDF3					NVARCHAR(2000)	= NULL,
			@v_vchUDF4					NVARCHAR(255)	= NULL,
			@v_vchUDF5					NVARCHAR(255)	= NULL,
			@v_vchUDF6					NVARCHAR(255)	= NULL,
			@v_fltUDF7					FLOAT			= NULL,
			@v_fltUDF8					FLOAT			= NULL,
			@v_dtUDF9					DATETIME		= NULL,
			@v_dtUDF10					DATETIME		= NULL,
			@v_vchUserID				NVARCHAR(25)	= NULL,

			@v_vchDepartment			NVARCHAR(50)	= NULL,		--มันคือ To Warehouse สำหรับใช้กรณีที่ Auto create plan 
			@v_vchToWarehouseID			VARCHAR(40)		= NULL,
			@v_vchLoadID				NVARCHAR(50)	= NULL,  
			@v_intLoadSequence			INTEGER			= NULL,  
			@v_vchTrackingNumber		NVARCHAR(50)	= NULL,  
			@v_vchRushOrder				NVARCHAR(10)	= NULL,  
			@v_vchBackOrderFlag			VARCHAR(3)		= NULL,  

			-- Table Variables (t_wms_outbound_master)
			@v_vchRecordType			NVARCHAR(10)	= NULL,		-- Required  
			@v_vchProcessingCode    	NVARCHAR(40)	= NULL,		-- Required  
			@v_vchProcessingStatus  	NVARCHAR(40)	= NULL,		-- Required  
			@v_vchWarehouse				NVARCHAR(25)	= NULL,		-- Required  
			@v_vchOwnerCode				NVARCHAR(40)	= NULL,		-- Required  
			@v_vchOrderNumber			NVARCHAR(40)	= NULL,		-- Required  
			@v_vchOrderType				NVARCHAR(30)	= NULL,		-- Required  
			@v_vchOrderStatus			NVARCHAR(10)	= NULL,		-- Required
			@v_vchCustOrderNumber		NVARCHAR(40)	= NULL,  
			@v_vchCustPO				NVARCHAR(40)	= NULL, 
			@v_dtOrderCreateDate		DATETIME		= NULL,		-- Required  
			@v_dtOrderDeliveryDatePlan	DATETIME		= NULL,
			@v_dtOrderShipDate			DATETIME		= NULL,		-- Required  
									
			-- Table Variables (t_wms_outbound_detail)
			@v_vchHostOBDetailIDGUID	UNIQUEIDENTIFIER= NULL,		
			@v_vchDTWarehouse			NVARCHAR(25)	= NULL,		
			@v_vchDTOwnerCode			NVARCHAR(40)	= NULL,		-- Required  
			@v_vchDTOrderNumber			NVARCHAR(40)	= NULL,		-- Required  
			@v_vchDTLineNumber			NVARCHAR(10)	= NULL,		-- Required  
			@v_vchDTItemNumber			NVARCHAR(50)	= NULL,		-- Required  
			@v_fltDTQuantity			FLOAT			= NULL,		-- Required  
			@v_vchDTUOM					NVARCHAR(20)	= NULL,		-- Required
			@v_vchDTLPN					NVARCHAR(25)	= NULL,		 
			@v_vchDTLotNumber			NVARCHAR(50)	= NULL,		  
			@v_vchDTExpiryDate			VARCHAR(10)		= NULL,		 
			@v_vchDTSerialNumber		NVARCHAR(50)	= NULL,		 
			@v_vchDTItemDescription		NVARCHAR(100)	= NULL,		  
			@v_vchDTCustomerItemCode	NVARCHAR(50)	= NULL,		 
			@v_vchDTDGGoodsFlag			NVARCHAR(10)	= NULL,		 
			@v_fltDTPrice				FLOAT			= NULL,		
			@v_vchDTUDF1				NVARCHAR(50)	= NULL,		 
			@v_vchDTUDF2				NVARCHAR(50)	= NULL,		
			@v_vchDTUDF3				NVARCHAR(50)	= NULL,		 
			@v_vchDTUDF4				NVARCHAR(50)	= NULL,		 
			@v_vchDTUDF5				NVARCHAR(50)	= NULL,		 
			@v_vchDTUDF6				NVARCHAR(50)	= NULL,		 
			@v_fltDTUDF7				FLOAT			= NULL,		 
			@v_fltDTUDF8				FLOAT			= NULL,		 
			@v_dtDTUDF9					DATETIME		= NULL,		
			@v_dtDTUDF10				DATETIME		= NULL,		
			@v_vchDTUserID				NVARCHAR(10)	= NULL,		 
			@v_vchDTGrade				NVARCHAR(40)	= NULL,		  
			@v_vchDTDefaultItemStatus	NVARCHAR(50)	= NULL

 	SELECT TOP 1 @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

BEGIN TRY  
	BEGIN TRANSACTION

	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY'  
	-- Future, Add a Log action for inserting into the Process Log  
    
	SELECT TOP 1 @v_vchRecordType	= record_type
		,@v_vchProcessingCode		= processing_code  
		,@v_vchProcessingStatus		= processing_status  
		,@v_vchWarehouse			= wh_id 
		,@v_vchOwnerCode			= owner_id  
		,@v_vchOrderNumber			= order_number  
		,@v_vchOrderType			= [type] 
		,@v_vchOrderStatus			= order_status
		,@v_vchCustOrderNumber		= customer_order_number  
		,@v_vchCustomerCode			= customer_code  
		,@v_vchCustPO				= customer_purchase_order  
		,@v_dtOrderCreateDate		= order_create_date 
		,@v_dtOrderDeliveryDatePlan =delivery_date_plan 
		,@v_dtOrderShipDate			= order_ship_date
		,@v_vchDepartment			= department
		,@v_vchLoadID				= load_id  
		,@v_intLoadSequence			= load_sequence_number  
		,@v_vchTrackingNumber		= tracking_number  
		,@v_vchRushOrder			= rush_order  
		,@v_vchBackOrderFlag		= back_order_flag  
		,@v_vchShipToCode			= ship_to_code  
		,@v_vchShipToName			= ship_to_name  
		,@v_vchShipToAddr1			= ship_to_address_line_1  
		,@v_vchShipToAddr2			= ship_to_address_line_2  
		,@v_vchShipToAddr3			= ship_to_address_line_3  
		,@v_vchShipToCity			= ship_to_city  
		,@v_vchShipToProvince		= ship_to_province  
		,@v_vchShipToPostalCode		= ship_to_postal_code  
		,@v_vchShipToCountryCode	= ship_to_country  
		,@v_vchShipToCountryName	= ship_to_country_name  
		,@v_vchShipToContactName	= ship_to_contact_name  
		,@v_vchShipToPhone			= ship_to_phone_number  
		,@v_vchBillToCode			= bill_to_code  
		,@v_vchBillToName			= bill_to_name  
		,@v_vchBillToAddr1			= bill_to_address_line_1  
		,@v_vchBillToAddr2			= bill_to_address_line_2  
		,@v_vchBillToAddr3			= bill_to_address_line_3  
		,@v_vchBillToCity			= bill_to_city  
		,@v_vchBillToProvince		= bill_to_province  
		,@v_vchBillToPostalCode		= bill_to_postal_code  
		,@v_vchBillToCountry		= bill_to_country  
		,@v_vchBillToCountryName	= bill_to_country_name  
		,@v_vchBillToContactName	= bill_to_contact_name  
		,@v_vchBillToPhoneNumber	= bill_to_phone_number
		,@v_vchUDF1					= user_def1
		,@v_vchUDF2					= user_def2
		,@v_vchUDF3					= user_def3
		,@v_vchUDF4					= user_def4
		,@v_vchUDF5					= user_def5
		,@v_vchUDF6					= user_def6
		,@v_fltUDF7					= user_def7
		,@v_fltUDF8					= user_def8
		,@v_dtUDF9					= CASE CONVERT(NVARCHAR,user_def9,112) WHEN '19000101' THEN NULL ELSE user_def9 END  
		,@v_dtUDF10					= CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
		,@v_vchUserID				= create_by  
	FROM t_host_wms_outbound_order  
	WHERE host_record_id = @in_vchHostRecordID      
	
	------------------------------------------------------------  
	--  If the WH ID was NOT put into the Interface Table   
	--  then try to get it from the Rule Table  
	------------------------------------------------------------  
	IF ISNULL(@v_vchWarehouse,'') = ''
		BEGIN
			SELECT @v_vchWarehouse = [dbo].[usf_GetRuleValue] ('DEFAULT_WH_ID',NULL,'WH_CONTROL')
		END
	
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'  
	-- Future, Add a Log action for inserting into the Process Log    
    
	IF (ISNULL(@v_vchRecordType,'') = ''
		OR ISNULL(@v_vchProcessingCode,'') = ''   
		OR ISNULL(@v_vchProcessingStatus,'') = ''  
		OR ISNULL(@v_vchWarehouse,'') = ''   
		OR ISNULL(@v_vchOwnerCode,'') = ''  
		OR ISNULL(@v_vchOrderNumber,'') = '' 
		OR ISNULL(@v_vchOrderType,'') = ''
		OR ISNULL(@v_vchOrderStatus,'') = ''
		OR @v_dtOrderCreateDate IS NULL
		OR @v_dtOrderShipDate IS NULL
		OR ISNULL(@v_vchCustomerCode,'') = ''
		OR ISNULL(@v_vchUserID,'') = '')
	BEGIN
		------------------------------------------------------------  
		--  Missing Required Fields   
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'  
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List 1:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+ ']'  
				+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+ ']'  
				+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']'   
				+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'  
				+ ' Warehouse ID: ['+ISNULL(@v_vchWarehouse, '') + ']' 
			      
			SELECT 'Field List 2: Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'  
				+ ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'  
				+ ' Order Status: ['+ISNULL(@v_vchOrderStatus, '') + ']'  
				+ ' Order Create Date: ['+ISNULL(CONVERT(NVARCHAR(12), @v_dtOrderCreateDate), '')+ ']'  
				+ ' User ID: ['+ISNULL(@v_vchUserID, '')+ ']'
		END  

		SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Missing Required Fields  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG  
	END    

	------------------------------------------------------------
	-- Check Department for Rule Order Type Auto Create Paln Inbound Order
	-- when pick item [for transfer warehouse]
	-- Column Department สำหรับกำหนดเป็น Warehouse ปลายทาง เมื่อต้องสร้างแผน
	------------------------------------------------------------
	IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_AUTO_INSERT_INBOUND' AND is_active = 'YES') = 'YES' 
			AND @v_vchOrderType IN (SELECT value FROM t_wms_rule WHERE rule_code = 'RULE_ORDER_TYPE_INSERT_INBOUND' AND is_active = 'YES'))
		BEGIN
			IF ISNULL(@v_vchDepartment,'') = ''
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Warehouse :[ '+ISNULL(@v_vchWarehouse, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-042' --Department cannot null 
					SET @v_vchErrorType = 'ERROR-MASTER'
					GOTO WRITE_PROCESS_LOG  
				END
			
			SET @v_vchToWarehouseID = NULL
			SELECT TOP 1 @v_vchToWarehouseID = wh_master_id FROM t_wms_wh WHERE wh_id = @v_vchDepartment AND is_active = 'YES'
			IF @v_vchToWarehouseID IS NULL
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Warehouse :[ '+ISNULL(@v_vchWarehouse, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-058' --Invalid to warehouse
					SET @v_vchErrorType = 'ERROR-MASTER' 
					GOTO WRITE_PROCESS_LOG  
				END
			SET @v_vchDepartment = @v_vchToWarehouseID
		END

	------------------------------------------------------------  
	--  Check Valid Warehouse  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse'  
	-- Future, Add a Log action for inserting into the Process Log  
    
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id, @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_id = @v_vchWarehouse AND is_active = 'YES'
	IF @v_vchWhMasterID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Warehouse :[ '+ISNULL(@v_vchWarehouse, '')+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-LOGMAN-004' -- Invalid Warehouse  
			SET @v_vchErrorType = 'ERROR-MASTER'
			GOTO WRITE_PROCESS_LOG
		END  
  	
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  
 
	SELECT TOP 1 @v_vchOwnerID = owner_id, @v_vchOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF @v_vchOwnerID IS NULL
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG
	END

	------------------------------------------------------------  
	-- Check for Valid Customer  
	------------------------------------------------------------  
	IF (ISNULL(@v_vchCustomerCode,'') <> '')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Customer ID'  
		-- Future, Add a Log action for inserting into the Process Log    
		SET @v_vchCustomerID = NULL
		SELECT TOP 1 @v_vchCustomerID = customer_id
			, @v_vchCustomerName	= customer_name
			, @v_vchCusDescription	= description
			, @v_vchCusAddrLine1	= addr_line_1
			, @v_vchCusAddrLine2	= addr_line_2
			, @v_vchCusAddrLine3	= addr_line_3
			, @v_vchCusCity			= city
			, @v_vchCusProvince		= province
			, @v_vchCusPostalCode	= postal_code
			, @v_vchCusCountryCode	= country_code
			, @v_vchCusCountryName	= country_name
			, @v_vchCusContact		= contact
			, @v_vchCusPhone		= phone
			, @v_vchCusFax			= fax
			, @v_vchCusEmail		= email
		FROM t_wms_customer 
		WHERE customer_code = @v_vchCustomerCode  
		AND owner_id = @v_vchOwnerID
		AND is_active = 'YES'

		IF @v_vchCustomerID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Record Type:[ '+ISNULL(@v_vchRecordType, '')+']'    
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-036' --INVALID ORDER MASTER - CUSTOMER CODE DOES NOT EXIST  
				SET @v_vchErrorType = 'ERROR-MASTER'
				GOTO WRITE_PROCESS_LOG
			END
	END

	------------------------------------------------------------  
	--  Check Valid Record Type  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Record Type'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF (@v_vchRecordType <> 'MASTER')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Record Type:[ '+ISNULL(@v_vchRecordType, '')+']'    
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG
	END  
  
	------------------------------------------------------------  
	--  Check Valid Processing Code  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Code'  
	-- Future, Add a Log action for inserting into the Process Log  
  
	IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE', 'DELETE')  
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+']'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG
	END  
    
	------------------------------------------------------------  
	--  Check Valid Processing Status  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingStatus <> 'PENDING')
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG
	END  
     
	------------------------------------------------------------  
	--  Check Valid Order Type  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Checking for Valid Order Type'   
	-- Future, Add a Log action for inserting into the Process Log  
	 
	IF @v_vchOrderType NOT IN (SELECT value_member FROM dbo.t_com_combobox_item WHERE group_name = 'outbound_order_type' and is_active = 'YES')  
	BEGIN
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Order Type'  
		-- Future, Add a Log action for inserting into the Process Log  

		SET @out_vchErrorCode = 'ERROR-IFMAN-014' -- Invalid Order Type  
		SET @v_vchErrorType = 'ERROR-MASTER'
		GOTO WRITE_PROCESS_LOG
	END

	----------------------------------------------------------  
	--  Check for Outbound Order Master and Get the Master ID  
	--  From the Master Inbound Order  
	---------------------------------------------------------- 
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Outbound Order Master'  
	-- Future, Add a Log action for inserting into the Process Log 
	SET @v_vchOutboundMasterID = NULL
	SELECT TOP 1 @v_vchOutboundMasterID = outbound_order_master_id
		,@v_vchCurrentOrderStatus = order_status
		,@v_vchCurrentOwnerCode = owner_code
	FROM t_wms_outbound_master
 	WHERE outbound_order_number = @v_vchOrderNumber 
	AND wh_master_id = @v_vchWhMasterID
	IF @v_vchOutboundMasterID IS NOT NULL
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'  
		END
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END
	
	------------------------------------------------------------  
	--  Check Processing for 'DELETE' the Outbound Order.
	------------------------------------------------------------  
	IF @v_vchOutboundMasterID IS NULL AND @v_vchProcessingCode IN ('DELETE','UPDATE')  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Outbound Order is Invalid'  
			-- Future, Add a Log action for inserting into the Process Log    
		  
			SET @out_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record  
			SET @v_vchErrorType = 'ERROR-MASTER'
			GOTO WRITE_PROCESS_LOG
		END
  
	------------------------------------------------------------  
	--  Processing for 'DELETE' the Outbound Order.   
	--  Update Order Status = 'Cancel'  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Delete Processing'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF (@v_vchProcessingCode = 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update Order Status "CANCEL" Order:['+@v_vchOrderNumber+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOrderStatus = 'OPEN')
				BEGIN
					DELETE t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID
					DELETE t_wms_outbound_master WHERE outbound_order_master_id = @v_vchOutboundMasterID
					--------------------------------------------------------------  
					---- Update Order Status = Cancel กรณีที่ส่งมาเป็น Delete  
					--------------------------------------------------------------  
					--UPDATE t_wms_outbound_master SET order_status = 'CANCEL'
					--	,update_by = @v_vchUserID
					--	,update_date = GETDATE()
					--WHERE outbound_order_master_id = @v_vchOutboundMasterID  

					------------------------------------------------------------  
					-- Update Process Status = COMPLETED  
					------------------------------------------------------------  
					UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
					UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
					UPDATE t_host_wms_outbound_order_comment SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  
				 
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Order Status Complete'  

					GOTO COMMIT_TRANS;
				END  
			ELSE  
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Order Status not Available for Change.'
																				+ ' Order Number:[' + @v_vchOrderNumber  + ']'
																				+ ' Order Status:['+ISNULL(@v_vchCurrentOrderStatus, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log 
					SET @out_vchErrorCode = 'ERROR-IFMAN-003' -- Order Status not Available for Change  
					SET @v_vchErrorType = 'ERROR-MASTER' 
					GOTO WRITE_PROCESS_LOG
				END  
		END

	IF (@v_vchCurrentOrderStatus = 'OPEN' AND @v_vchOrderStatus IN ('CANCELLED','CANCEL','CLOSE'))
		BEGIN
			------------------------------------------------------------  
			-- Update Order Status = Cancel กรณีที่ส่งมาเป็น Delete  
			------------------------------------------------------------
			IF @v_vchOrderStatus = 'CANCELLED'
				SET @v_vchOrderStatus = 'CANCEL'

			UPDATE t_wms_outbound_master SET 
				 order_status = @v_vchOrderStatus
				,update_by = @v_vchUserID
				,update_date = GETDATE()
			WHERE outbound_order_master_id = @v_vchOutboundMasterID				

			------------------------------------------------------------  
			-- Update Process Status = COMPLETED  
			------------------------------------------------------------  
			UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			UPDATE t_host_wms_outbound_order_comment SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
					
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Order Status Complete' 

			GOTO COMMIT_TRANS;
		END

  
	------------------------------------------------------------  
	--  Check the Outbound Order for a ADD duplicate.  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Duplicates'   
	-- Future, Add a Log action for inserting into the Process Log   
	IF (@v_vchProcessingCode = 'ADD' and @v_vchOutboundMasterID IS NOT NULL) -- Duplicate Order Error  
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Found.  Order Number:'+@v_vchOrderNumber+']'  
			SET @out_vchErrorCode = 'ERROR-IFMAN-002' -- Duplicate Order Number  
			SET @v_vchErrorType = 'ERROR-MASTER'
			GOTO WRITE_PROCESS_LOG
		END  
	ELSE IF (@v_vchProcessingCode = 'ADD' AND @v_vchOutboundMasterID IS NULL) -- Add Order Master
		BEGIN
			------------------------------------------------------------  
			--  Processing for 'ADD' the Order .  
			--  This section should be runing for an 'ADD' with no   
			--  duplicates or and 'UPDATE' is no record exists.  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing add outbound order (Master)'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List: Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'  
					  + 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
					  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'  
					  + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']' 
					  + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'   
					  + ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'   
					  + ' Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '') + ']'  
					  + ' Order Ship Date: ['+ISNULL(convert(nvarchar(12),@v_dtOrderShipDate), '') + ']'   
					  + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
					-- Future, Add a Log action for inserting into the Process Log  
				END

			INSERT INTO [t_wms_outbound_master]
			(	
				 wh_master_id  
				,outbound_order_number  
				,owner_id  
				,order_type  
				,order_status
				,order_date
				,delivery_date_plan
				,ship_date_plan       
				,department	
				,load_id  
				,load_sequence_number  
				,tracking_number
				,rush_order  
				,back_order_flag  
				,customer_order_number  
				,customer_purchase_order
				,customer_id
				,customer_code  
				,customer_name  
				,cus_addr_line_1  
				,cus_addr_line_2  
				,cus_addr_line_3  
				,cus_city  
				,cus_province  
				,cus_postal_code  
				,cus_country_code  
				,cus_country_name  
				,cus_contact  
				,cus_phone
				,ship_to_code  
				,ship_to_name  
				,ship_to_addr_line_1  
				,ship_to_addr_line_2  
				,ship_to_addr_line_3  
				,ship_to_city  
				,ship_to_province  
				,ship_to_postal_code  
				,ship_to_country_code  
				,ship_to_country_name  
				,ship_to_contact  
				,ship_to_phone
				,bill_to_code  
				,bill_to_name  
				,bill_to_address_line_1  
				,bill_to_address_line_2  
				,bill_to_address_line_3  
				,bill_to_city  
				,bill_to_province  
				,bill_to_postal_code  
				,bill_to_country  
				,bill_to_country_name  
				,bill_to_contact_name
				,bill_to_phone_number
				,user_def1  
				,user_def2  
				,user_def3  
				,user_def4  
				,user_def5  
				,user_def6  
				,user_def7  
				,user_def8  
				,user_def9  
				,user_def10  
				,wh_id
				,owner_code
				,create_date  
				,create_by           
			)  
			VALUES  
			(    
				 @v_vchWhMasterID										
				,@v_vchOrderNumber  								
				,@v_vchOwnerID									
				,@v_vchOrderType  									
				,@v_vchOrderStatus									
				,@v_dtOrderCreateDate								
				,@v_dtOrderDeliveryDatePlan							
				,@v_dtOrderShipDate  								
				,@v_vchDepartment --@v_vchToWarehouseID		--Department ในระบบหมายถึง To warehouse ใช้กรณีที่ Rule Insert Inbound Auto									
				,@v_vchLoadID  										
				,@v_intLoadSequence  								
				,@v_vchTrackingNumber  								
				,@v_vchRushOrder  									
				,@v_vchBackOrderFlag  								
				,@v_vchCustOrderNumber  							
				,@v_vchCustPO										
				,@v_vchCustomerID								
				,@v_vchCustomerCode									
				,@v_vchCustomerName									
				,@v_vchCusAddrLine1									
				,@v_vchCusAddrLine2									
				,@v_vchCusAddrLine3									
				,@v_vchCusCity										
				,@v_vchCusProvince									
				,@v_vchCusPostalCode								
				,@v_vchCusCountryCode								
				,@v_vchCusCountryName								
				,@v_vchCusContact									
				,@v_vchCusPhone										
				,@v_vchShipToCode  									
				,@v_vchShipToName  									
				,@v_vchShipToAddr1  								
				,@v_vchShipToAddr2  								
				,@v_vchShipToAddr3  								
				,@v_vchShipToCity  									
				,@v_vchShipToProvince  								
				,@v_vchShipToPostalCode  							
				,@v_vchShipToCountryCode								
				,@v_vchShipToCountryName  							
				,@v_vchShipToContactName  							
				,@v_vchShipToPhone							
				,@v_vchBillToCode  									
				,@v_vchBillToName  									
				,@v_vchBillToAddr1  								
				,@v_vchBillToAddr2  								
				,@v_vchBillToAddr3  								
				,@v_vchBillToCity  									
				,@v_vchBillToProvince  								
				,@v_vchBillToPostalCode  							
				,@v_vchBillToCountry								
				,@v_vchBillToCountryName  							
				,@v_vchBillToContactName  							
				,@v_vchBillToPhoneNumber							
				,@v_vchUDF1  										
				,@v_vchUDF2  										
				,@v_vchUDF3  										
				,@v_vchUDF4  										
				,@v_vchUDF5  										
				,@v_vchUDF6  										
				,@v_fltUDF7  										
				,@v_fltUDF8  										
				,@v_dtUDF9  										
				,@v_dtUDF10	
				,@v_vchWarehouse	
				,@v_vchOwnerCode
				,GETDATE()  										
				,@v_vchUserID     									
			)

			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					SET @v_vchErrorType = 'ERROR-MASTER'
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					SET @v_vchErrorType = 'ERROR-MASTER'
					GOTO WRITE_PROCESS_LOG
				END

			------------------------------------------------------------  
			-- Update Process Status = COMPLETED  
			------------------------------------------------------------  
			UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing add outbound order Completed'   
			-- Future, Add a Log action for inserting into the Process Log  
		END  
	ELSE IF (@v_vchProcessingCode = 'UPDATE' AND @v_vchOutboundMasterID IS NOT NULL) -- Update Order Master 
		BEGIN
			------------------------------------------------------------  
			--  Check Order Status - No Change if Order Status not PENDING  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Order Status for Update:['+@v_vchCurrentOrderStatus+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+']'  
						  + 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '') +']'  
						  + 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+']'  
						  + 'Owner: ['+ISNULL(@v_vchOwnerCode, '') +']'  
						  + 'Log Type: ['+ISNULL(@v_vchLogType, '') +']'  
						  + 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') +']'  
						  + 'Order Type: ['+ISNULL(@v_vchOrderType, '') +']'  
						  + 'Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '')+']'  
						  + 'Order Ship Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderShipDate), '')+']'  
						  + 'User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
					-- Future, Add a Log action for inserting into the Process Log  
				END  
		   
			IF (@v_vchCurrentOrderStatus <> 'OPEN')
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Order Status not Available for Change.'
																				+ ' Order Number:['+@v_vchOrderNumber  +']'
																				+ ' Order Status:['+ISNULL(@v_vchCurrentOrderStatus, '')+']'  
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-003' -- Order Status not Available for Change  
					SET @v_vchErrorType = 'ERROR-MASTER'
					GOTO WRITE_PROCESS_LOG
				END  
			
			------------------------------------------------------------  
			--  Check Owner ต้องเป็นค่าเดิมที่ Interface มาครั้งแรก  
			------------------------------------------------------------ 
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking owner ID for update:['+@v_vchOwnerCode+']'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF (@v_vchCurrentOwnerCode <> @v_vchOwnerCode)
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT' SELECT 'Owner not available for Change.'  
								 +' Order Number:[' + @v_vchOrderNumber + ']' 
								 +' Current Owner:[' + ISNULL(@v_vchCurrentOwnerCode, '') + ']' 
								 +' Owner:[' + ISNULL(@v_vchOwnerCode, '') + ']'
					-- Future, Add a Log action for inserting into the Process Log  

					SET @out_vchErrorCode = 'ERROR-IFMAN-032' -- Owner not available for Change 
					SET @v_vchErrorType = 'ERROR-MASTER'
					GOTO WRITE_PROCESS_LOG
				END
		  
			------------------------------------------------------------  
			--  Processing for 'UPDATE'.  
			--  Update an existing Item in the item Table  
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Processing Code for Update'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
				BEGIN
					SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '')+ ']'   
					  + ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'  
					  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']'   
					  + ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'   
					  + ' Log Type: ['+ISNULL(@v_vchLogType, '')  + ']'  
					  + ' Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'   
					  + ' Order Type: ['+ISNULL(@v_vchOrderType, '') + ']'   
					  + ' Order Create Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderCreateDate), '') + ']'  
					  + ' Order Ship Date: ['+ISNULL(convert(nvarchar(12), @v_dtOrderShipDate), '')+ ']'          
					SELECT 'UDF1: ['+ISNULL(@v_vchUDF1, '') + ']'  
						+' UDF2: ['+ISNULL(@v_vchUDF2, '')+ ']' 
						+' UDF3: ['+ISNULL(@v_vchUDF3, '') + ']'  
						+' UDF4: ['+ISNULL(@v_vchUDF4, '') + ']'  
						+' UDF5: ['+ISNULL(@v_vchUDF5, '') + ']'  
						+' UDF6: ['+ISNULL(@v_vchUDF6, '') + ']'  
						+' UDF7: ['+ISNULL(str(@v_fltUDF7, 12), '')+ ']'   
						+' UDF8: ['+ISNULL(str(@v_fltUDF8, 12), '') + ']'  
						+' UDF9: ['+ISNULL(convert(NVARCHAR(12), @v_dtUDF9), '')+ ']'   
						+' UDF10: ['+ISNULL(convert(NVARCHAR(12), @v_dtUDF10), '')+ ']'   
						+' User ID: ['+ISNULL(@v_vchUserID, '') + ']'   
				END  
		  
			IF @v_vchProcessingCode = 'UPDATE'  
				BEGIN
					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Outbound Order Master'  
					-- Future, Add a Log action for inserting into the Process Log 
					
					---------------------------------------------------
					--Delete Inbound Detail Before Update
					---------------------------------------------------
					DELETE t_wms_Outbound_detail WHERE [outbound_order_master_id] = @v_vchOutboundMasterID 
            
					UPDATE [t_wms_outbound_master] SET	
						 [order_type] = @v_vchOrderType 
						,[order_date] = @v_dtOrderCreateDate  
						,[delivery_date_plan] = @v_dtOrderDeliveryDatePlan
						,[ship_date_plan] = @v_dtOrderShipDate  
						,[department] = @v_vchDepartment--@v_vchToWarehouseID  
						,[load_id] = @v_vchLoadID  
						,[load_sequence_number] = @v_intLoadSequence  
						,[tracking_number] = @v_vchTrackingNumber  
						,[rush_order] = @v_vchRushOrder  
						,[back_order_flag] = @v_vchBackOrderFlag  
						,[customer_order_number] = @v_vchCustOrderNumber  
						,[customer_purchase_order] = @v_vchCustPO
						,[customer_id] = @v_vchCustomerID
						,[customer_code] = @v_vchCustomerCode
						,[customer_name] = @v_vchCustomerName  
						,[cus_addr_line_1] = @v_vchCusAddrLine1 
						,[cus_addr_line_2] = @v_vchCusAddrLine2
						,[cus_addr_line_3] = @v_vchCusAddrLine3  
						,[cus_city] = @v_vchCusCity 
						,[cus_province] = @v_vchCusProvince  
						,[cus_postal_code] = @v_vchCusPostalCode  
						,[cus_country_code] = @v_vchCusCountryCode
						,[cus_country_name] = @v_vchCusCountryName  
						,[cus_contact] = @v_vchCusContact  
						,[cus_phone] = @v_vchCusPhone  
						,[ship_to_code] = @v_vchShipToCode  
						,[ship_to_name] = @v_vchShipToName  
						,[ship_to_addr_line_1] = @v_vchShipToAddr1  
						,[ship_to_addr_line_2] = @v_vchShipToAddr2  
						,[ship_to_addr_line_3] = @v_vchShipToAddr3  
						,[ship_to_city] = @v_vchShipToCity  
						,[ship_to_province] = @v_vchShipToProvince  
						,[ship_to_postal_code] = @v_vchShipToPostalCode  
						,[ship_to_country_code] = @v_vchShipToCountryCode
						,[ship_to_country_name] = @v_vchShipToCountryName  
						,[ship_to_contact] = @v_vchShipToContactName  
						,[ship_to_phone] = @v_vchShipToPhone
						,[bill_to_code] = @v_vchBillToCode  
						,[bill_to_name] = @v_vchBillToName  
						,[bill_to_address_line_1] = @v_vchBillToAddr1  
						,[bill_to_address_line_2] = @v_vchBillToAddr2  
						,[bill_to_address_line_3] = @v_vchBillToAddr3  
						,[bill_to_city] = @v_vchBillToCity  
						,[bill_to_province] = @v_vchBillToProvince  
						,[bill_to_postal_code] = @v_vchBillToPostalCode  
						,[bill_to_country] = @v_vchBillToCountry
						,[bill_to_country_name] = @v_vchBillToCountryName  
						,[bill_to_contact_name] = @v_vchBillToContactName  
						,[bill_to_phone_number] = @v_vchBillToPhoneNumber   
						,[user_def1] = @v_vchUDF1  
						,[user_def2] = @v_vchUDF2   
						,[user_def3] = @v_vchUDF3 
						,[user_def4] = @v_vchUDF4  
						,[user_def5] = @v_vchUDF5  
						,[user_def6] = @v_vchUDF6  
						,[user_def7] = @v_fltUDF7
						,[user_def8] = @v_fltUDF8 
						,[user_def9] = @v_dtUDF9
						,[user_def10] = @v_dtUDF10
					WHERE [outbound_order_master_id] = @v_vchOutboundMasterID

					---------------------------------------------------   
					-- Update Process Status = COMPLETED  
					---------------------------------------------------  
					UPDATE t_host_wms_outbound_order SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID  

					IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Update Outbound Order Complete (Master)'  
				END
		END
  
	------------------------------------------------------------  
	--*******************OUTBOUND ORDER DETAIL*******************  
	------------------------------------------------------------  
	DECLARE @v_vchWhItemMasterID	 UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID		 UNIQUEIDENTIFIER = NULL,
			@v_vchBaseItemUomID		 UNIQUEIDENTIFIER = NULL,
			@v_vchBaseUOM			 NVARCHAR(20) = NULL,
			@v_vchDTItemUomID		 UNIQUEIDENTIFIER = NULL,
			@v_fltDTConversionFactor FLOAT = NULL,
			@v_vchPrimaryUOM		 VARCHAR(3) = NULL,
			@v_fltQuantityPick		 FLOAT = 0

	IF EXISTS (SELECT host_record_id FROM dbo.t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING')  
	BEGIN
		OUTBOUND_DETAIL_LABEL:
		
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Outbound Order Detail Started'   
		-- Future, Add a Log action for inserting into the Process Log 
		 
		SET @v_vchTableName = 't_host_wms_outbound_order_detail'
		BEGIN-- Clear Value before set the value to variable 
			SET @v_vchHostOBDetailIDGUID = NULL
			SET @v_vchRecordType		= NULL
			SET @v_vchProcessingCode	= NULL
			SET @v_vchProcessingStatus	= NULL
			SET @v_vchDTWarehouse		 = NULL
			SET @v_vchDTOwnerCode		 = NULL
			SET @v_vchDTOrderNumber		 = NULL
			SET @v_vchDTLineNumber		 = NULL
			SET @v_vchDTItemNumber		 = NULL
			SET @v_fltDTQuantity		 = NULL
			SET @v_vchDTUOM				 = NULL
			SET @v_vchDTLPN				 = NULL
			SET @v_vchDTLotNumber		 = NULL
			SET @v_vchDTExpiryDate		 = NULL
			SET @v_vchDTSerialNumber	 = NULL
			SET @v_vchDTItemDescription	 = NULL
			SET @v_vchDTCustomerItemCode = NULL
			SET @v_vchDTDGGoodsFlag		 = NULL
			SET @v_fltDTPrice			 = NULL
			SET @v_vchDTUDF1			 = NULL
			SET @v_vchDTUDF2			 = NULL
			SET @v_vchDTUDF3			 = NULL
			SET @v_vchDTUDF4			 = NULL
			SET @v_vchDTUDF5			 = NULL
			SET @v_vchDTUDF6			 = NULL
			SET @v_fltDTUDF7			 = NULL
			SET @v_fltDTUDF8			 = NULL
			SET @v_dtDTUDF9				 = NULL
			SET @v_dtDTUDF10			 = NULL
			SET @v_vchDTUserID			 = NULL
			SET @v_vchDTGrade			 = NULL
			SET @v_vchDTDefaultItemStatus= NULL
			SET @v_vchWhItemMasterID	 = NULL
			SET @v_vchItemMasterID		 = NULL
			SET @v_vchBaseItemUomID		 = NULL
			SET @v_vchBaseUOM			 = NULL
			SET @v_vchDTItemUomID		 = NULL
			SET @v_fltDTConversionFactor = NULL
			SET @v_vchPrimaryUOM		 = NULL
		END
		
		SELECT TOP 1 @v_vchHostOBDetailIDGUID = outbound_order_detail_id
			,@v_vchRecordType = record_type  
			,@v_vchProcessingCode = processing_code  
			,@v_vchProcessingStatus = processing_status  
			,@v_vchDTWarehouse= wh_id
			,@v_vchDTOwnerCode = owner_id
			,@v_vchDTOrderNumber = order_number  
			,@v_vchDTLineNumber = line_number  
			,@v_vchDTItemNumber = item_number
			,@v_vchDTItemDescription = item_description  
			,@v_fltDTQuantity = order_quantity  
			,@v_vchDTUOM = uom  
			,@v_vchDTLPN = (CASE ISNULL(lpn,'') WHEN '' THEN NULL ELSE lpn END)
			,@v_vchDTLotNumber = (CASE ISNULL(lot_number,'') WHEN '' THEN NULL ELSE lot_number END)
			,@v_vchDTExpiryDate = CASE CONVERT(NVARCHAR,EXPIRY_DATE,112) WHEN '19000101' THEN NULL ELSE CONVERT(VARCHAR(8),expiry_date,112) END
			,@v_vchDTSerialNumber = serial_number
			,@v_vchDTCustomerItemCode = customer_item_code  
			,@v_vchDTDGGoodsFlag = dangerous_good_flag  
			,@v_fltDTPrice = price
			,@v_vchDTUDF1 = user_def1  
			,@v_vchDTUDF2 = user_def2 
			,@v_vchDTUDF3 = user_def3
			,@v_vchDTUDF4 = user_def4
			,@v_vchDTUDF5 = user_def5
			,@v_vchDTUDF6 = user_def6
			,@v_fltDTUDF7 = user_def7
			,@v_fltDTUDF8 = user_def8
			,@v_dtDTUDF9  = CASE CONVERT(NVARCHAR,user_def9	,112) WHEN '19000101' THEN NULL ELSE user_def9 END
			,@v_dtDTUDF10  = CASE CONVERT(NVARCHAR,user_def10,112) WHEN '19000101' THEN NULL ELSE user_def10 END
			,@v_vchDTGrade = grade
			,@v_vchDTDefaultItemStatus = default_item_status
			,@v_vchDTUserID = create_by
		FROM t_host_wms_outbound_order_detail  
		WHERE host_record_id = @in_vchHostRecordID
		AND processing_status = 'PENDING'
		ORDER BY line_number  
		IF (ISNULL(@v_vchDTDefaultItemStatus,'') = '')
			BEGIN
				SET @v_vchDTDefaultItemStatus = [dbo].[usf_GetRuleValue] ('RULE_STATUS_OUTBOUND_DEFAULT',NULL,'WH_RULE')
			END
			
		----------------------------------------------------------  
		--  Check for Required Fields  
		--  log_type, warehouse, tran code, start tran date, location, quantity   
		--  app_id, device, user id, error_code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Required Fields'  
		-- Future, Add a Log action for inserting into the Process Log   

		IF ISNULL(@v_vchRecordType,'') = ''
			OR ISNULL(@v_vchProcessingCode,'') = ''  
			OR ISNULL(@v_vchProcessingStatus,'') = ''  
			OR ISNULL(@v_vchDTWarehouse,'') = ''
			OR ISNULL(@v_vchDTOwnerCode,'') = '' 
			OR ISNULL(@v_vchDTOrderNumber,'') = ''
			OR ISNULL(@v_vchDTLineNumber,'') = ''
			OR ISNULL(@v_vchDTItemNumber,'') = ''
			OR ISNULL(@v_fltDTQuantity,0) = 0 
			OR ISNULL(@v_vchDTUOM,'') = '' 
			OR ISNULL(@v_vchDTUserID,'') = '' 
		BEGIN
			------------------------------------------------------------  
			--  Missing Required Fields   
			------------------------------------------------------------  
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Missing Required Fields'  
			-- Future, Add a Log action for inserting into the Process Log  

			IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'    
			SELECT 'Field List:' + 'Record Type: ['+ISNULL(@v_vchRecordType, '') +']'  
				+ 'Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+']'  
				+ 'Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+']'  
				+ 'Owner: ['+ISNULL(@v_vchDTOwnerCode, '') +']' 
				+ 'Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') +']'  
				+ 'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') +']'  
				+ 'Item Number: ['+ISNULL(@v_vchDTItemNumber, '') +']'  
				+ 'UOM: ['+ISNULL(@v_vchDTUOM, '')+']'  
				+ 'Quantity: ['+ISNULL(STR(@v_fltDTQuantity, 12), '')+']'  
				+ 'User ID: ['+ISNULL(@v_vchUserID, '') + ']'        
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Missing Required Fields  
			SET @v_vchErrorType = 'ERROR-DETAIL'
			GOTO WRITE_PROCESS_LOG
		END        
   
   
		----------------------------------------------------------  
		--  Get Warehouse Master ID [wh_master_id]
		--  Check to make sure that Warehouse ID in the Import Data   
		--  is a valid Warehouse ID that is in the t_wms_wh table  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Warehouse ID GUID'  
		-- Future, Add a Log action for inserting into the Process Log    
		SET @v_vchWhMasterID = NULL
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id, @v_vchDTWarehouse = wh_id FROM t_wms_wh WHERE wh_id = @v_vchDTWarehouse AND is_active = 'YES'
		IF (@v_vchWhMasterID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Warehouse ID is Invalid'  
				-- Future, Add a Log action for inserting into the Process Log    
				SET @out_vchErrorCode = 'ERROR-LOGMAN-004' -- Invalid Warehouse in Import Data  
			    SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END
   
		------------------------------------------------------------  
		-- Check for Valid Owner
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
		-- Future, Add a Log action for inserting into the Process Log  
		SET @v_vchOwnerID = NULL
		SELECT @v_vchOwnerID = owner_id, @v_vchDTOwnerCode = owner_code FROM t_wms_owner WHERE owner_code = @v_vchDTOwnerCode AND is_active = 'YES'
		IF (@v_vchOwnerID IS NULL)
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-IFMAN-025' -- Invalid Owner  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END
		
		------------------------------------------------------------  
		--  Check for Outbound Order Master and Get the Master ID  
		--  from the Master Outbound Order  
		------------------------------------------------------------        
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking Valid Outbound Order Master'  
		-- Future, Add a Log action for inserting into the Process Log
		
		SET @v_vchOutboundMasterID = NULL;
		SET @v_vchCurrentOrderStatus = NULL;
		SET @v_vchOrderType = NULL;
		SELECT TOP 1 @v_vchOutboundMasterID = outbound_order_master_id  
			,@v_vchCurrentOrderStatus = order_status
			,@v_vchOrderType = order_type
		FROM t_wms_outbound_master  
		WHERE outbound_order_number = @v_vchDTOrderNumber   
		AND wh_master_id = @v_vchWhMasterID
		IF @v_vchOutboundMasterID IS NULL
			BEGIN
				IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  select 'Outbound Order is Invalid - No Master Record'  
				-- Future, Add a Log action for inserting into the Process Log   
			 
				SET @out_vchErrorCode = 'ERROR-IFMAN-006' -- Invalid Order Detail in Import Data - No Master Record  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END  
          
		------------------------------------------------------------  
		--  Check Valid Record Types  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Record Type'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchRecordType <> 'DETAIL')
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Record Type'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0019' -- Invalid Record Type  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END     
     
		------------------------------------------------------------  
		--  Check Valid Processing Code  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchProcessingCode NOT IN ('ADD', 'UPDATE','DELETE') -- Do we want to DELETE JUST a LINE?  , 'DELETE')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processign Code  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END  


		------------------------------------------------------------  
		--  Check Valid Processing Status  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Status'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF (@v_vchProcessingStatus <> 'PENDING')  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+'}'  
				-- Future, Add a Log action for inserting into the Process Log  

				SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END
     
		------------------------------------------------------------
		--  Get Item GUID & Item BASE UOM GUID  
		------------------------------------------------------------
		SET @v_vchWhItemMasterID = NULL;
		SET @v_vchItemMasterID = NULL;
		SELECT TOP 1 @v_vchWhItemMasterID = whItem.wh_item_master_id 
			, @v_vchItemMasterID = item.item_master_id
			, @v_vchDTItemNumber = item.item_number
			, @v_vchDTItemDescription = item.description
		FROM t_wms_item item
		INNER JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id
		WHERE whItem.wh_master_id = @v_vchWhMasterID
		AND item.owner_id = @v_vchOwnerID
		AND item.item_number = @v_vchDTItemNumber
		AND item.is_active = 'YES'
		 
		------------------------------------------------------------  
		--  Check for Valid Item in the Warehouse  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Warehouse Item'   
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchWhItemMasterID IS NULL  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Invalid item in warehouse'  
				-- Future, Add a Log action for inserting into the Process Log    

				SET @out_vchErrorCode = 'ERROR-IFMAN-011' -- Invalid Item in Warehouse  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END

		-----------------------------------------------------------
		-- Validate Input UOM
		-----------------------------------------------------------
		SET @v_vchDTItemUomID = NULL;
		SELECT TOP 1 @v_vchDTItemUomID = item_uom_id
			, @v_vchDTUom = uom
			, @v_fltDTConversionFactor = conversion_factor
			, @v_vchPrimaryUOM = primary_uom
	    FROM t_wms_item_uom 
		WHERE item_master_id = @v_vchItemMasterID
		AND uom = @v_vchDTUom
		AND is_active = 'YES'
		----------------------------------------------------------  
		--  Check for Valid Item UOM  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking Valid Item UOM'  
		-- Future, Add a Log action for inserting into the Process Log  

		IF @v_vchDTItemUomID IS NULL  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item UOM is Invalid'  
				-- Future, Add a Log action for inserting into the Process Log    

				SET @out_vchErrorCode = 'ERROR-IFMAN-008' -- Invalid UOM Detail in Import Data - No UOM Record  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END

		-----------------------------------------------------------
		-- Validate Base UOM
		-----------------------------------------------------------
		IF @v_vchPrimaryUOM = 'NO'
			BEGIN
				SET @v_vchBaseItemUomID = NULL
				SET @v_vchBaseUOM = NULL
				SELECT TOP 1 @v_vchBaseItemUomID = item_uom_id
					, @v_vchBaseUOM = uom
				FROM t_wms_item_uom 
				WHERE item_master_id = @v_vchItemMasterID
				AND primary_uom = 'YES'
				AND is_active = 'YES'
				
				IF  @v_vchBaseItemUomID IS NULL  
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Item UOM is Invalid'  
						-- Future, Add a Log action for inserting into the Process Log    

						SET @out_vchErrorCode = 'ERROR-IFMAN-057' -- Invalid UOM Detail in Import Data - No Primary UOM Record  
						SET @v_vchErrorType = 'ERROR-DETAIL'
						GOTO WRITE_PROCESS_LOG
					END
			END
		ELSE
			BEGIN
				SET @v_vchBaseItemUomID = @v_vchDTItemUomID
				SET @v_vchBaseUOM = @v_vchDTUom
			END
		
		-------------------------------------------------------------------
		-- คำนวณ Qty เป็นหน่วย Base
		-------------------------------------------------------------------
        SET @v_fltDTQuantity = ROUND(@v_fltDTQuantity * @v_fltDTConversionFactor,@Round)

		-------------------------------------------------------------------  
		--  Processing for 'DELETE' the Outbound Order.  
		-------------------------------------------------------------------
		SET @v_vchOutboundDetailID = NULL;
		SET @v_fltQuantityPick = 0;
		SELECT @v_vchOutboundDetailID = outbound_order_detail_id
			,@v_fltQuantityPick = quantity_pick
		FROM t_wms_outbound_detail  
		WHERE outbound_order_master_id = @v_vchOutboundMasterID  
		AND wh_item_master_id = @v_vchWhItemMasterID  
		AND line_number = @v_vchDTLineNumber
		
		-------------------------------------------------------------------------  
		--  ลบข้อมูล โดยที่จะต้องมีเงื่อนไข ดังนี้  
		--  Processing code = Delete  
		--  Quantity Ship = 0
		--  จะต้องมี Record Order Detail ID ที่ Item Number และ Line Number ตรงกัน  
		-------------------------------------------------------------------------  
		IF @v_vchProcessingCode = 'DELETE'  
			BEGIN
				IF ((@v_vchOutboundDetailID IS NOT NULL) AND (ISNULL(@v_fltQuantityPick,0) = 0) AND (@v_vchCurrentOrderStatus <> 'OPEN'))  
					BEGIN
						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Delete Processing for Item Number:['+@v_vchDTItemNumber+']'  
						-- Future, Add a Log action for inserting into the Process Log  

						DELETE t_wms_outbound_detail WHERE outbound_order_detail_id = @v_vchOutboundDetailID  

						---------------------------------------------------   
						-- Update Process Status = COMPLETED  
						---------------------------------------------------  
						UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED' WHERE outbound_order_detail_id = @v_vchHostOBDetailIDGUID  

						IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing delete item number completed. [Outbound Order Detail]'  
						-- Future, Add a Log action for inserting into the Process Log  

						------------------------------------------------------------------------------
						-- ตรวจสอบว่ายังมี Record ที่เป็น Pending อยู่หรือไม่ ถ้ามีให้กลับไปเริ่มต้นทำงานในส่วนของ Detail อีกครั้ง 
						------------------------------------------------------------------------------
						IF  EXISTS (SELECT * FROM t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)
							BEGIN
								GOTO OUTBOUND_DETAIL_LABEL    
							END
						ELSE
							BEGIN
								GOTO COMMIT_TRANS;
							END
					END  
				ELSE  
					BEGIN
						IF (@v_vchOutboundDetailID IS NULL) 
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @out_vchErrorCode = 'ERROR-IFMAN-031' --INVALID ORDER DETAIL IN IMPORT DATA - NO DETAIL RECORD.  
								SET @v_vchErrorType = 'ERROR-DETAIL'
								GOTO WRITE_PROCESS_LOG
							END 
							
						IF ISNULL(@v_fltQuantityPick,0) > 0 
							BEGIN
								IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Cannot Delete Item Number:['+@v_vchDTItemNumber+']'  
								-- Future, Add a Log action for inserting into the Process Log    

								SET @out_vchErrorCode = 'ERROR-IFMAN-035' -- Cannot delete item. Because the quantity pick is greater than 0.  
								SET @v_vchErrorType = 'ERROR-DETAIL'
								GOTO WRITE_PROCESS_LOG
							END
					END  
			END  
      
		-------------------------------------------------------------------------  
		--  Check Data for Add or Update  
		------------------------------------------------------------------------- 
		SET @v_vchOutboundDetailID = NULL    
		SELECT @v_vchOutboundDetailID = outbound_order_detail_id  
		FROM t_wms_outbound_detail  
		WHERE outbound_order_master_id = @v_vchOutboundMasterID  
		AND line_number = @v_vchDTLineNumber
		IF @v_vchOutboundDetailID IS NOT NULL
			BEGIN  
				SET @v_vchProcessingCode = 'UPDATE'  
			END 
		ELSE
			BEGIN
				SET @v_vchProcessingCode = 'ADD'  
			END
		
		------------------------------------------------------------  
		--  Check the Outbound Order for a ADD duplicate.  
		------------------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Lines'   
		-- Future, Add a Log action for inserting into the Process Log		
          
		IF (@v_vchProcessingCode = 'ADD' AND @v_vchOutboundDetailID IS NOT NULL)  -- Duplicate Order Error  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Duplicate Found.  Order Number:'+@v_vchDTOrderNumber+'] Line Number:['+@v_vchDTLineNumber+']'  
				-- Future, Add a Log action for inserting into the Process Log   

				SET @out_vchErrorCode = 'ERROR-IFMAN-007' -- Duplicate Line Number  
				SET @v_vchErrorType = 'ERROR-DETAIL'
				GOTO WRITE_PROCESS_LOG
			END     
    
		ELSE IF (@v_vchProcessingCode = 'ADD' AND @v_vchOutboundDetailID IS NULL)  -- ADD Outbound Order Detail  
			BEGIN
				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Detail Line'				  

				INSERT INTO [t_wms_outbound_detail]
					(    [outbound_order_master_id]  
						,[wh_item_master_id]  
						,[line_number]  
						,[quantity_order]  
						,[item_uom_id]  
						,[lpn]  
						,[lot_number]  
						,[expiry_date]  
						,[serial_number]  
						,[item_description]  
						,[customer_item_code]  
						,[dangerous_good_flag]  
						,[price]  
						,[grade]  
						,[default_item_status]  
						,[user_def1]  
						,[user_def2] 
						,[user_def3] 
						,[user_def4] 
						,[user_def5] 
						,[user_def6] 
						,[user_def7] 
						,[user_def8] 
						,[user_def9] 
						,[user_def10] 
						,[item_master_id]
						,[item_number]
						,[uom] 
						,[interface_plan_uom_id]
						,[interface_plan_uom]	
						,[create_by]
						,[create_date] 
					)  
					VALUES
					(    @v_vchOutboundMasterID   
						,@v_vchWhItemMasterID    
						,@v_vchDTLineNumber    
						,@v_fltDTQuantity    
						,@v_vchBaseItemUomID    
						,@v_vchDTLPN      
						,@v_vchDTLotNumber    
						,@v_vchDTExpiryDate
						,@v_vchDTSerialNumber   
						,@v_vchDTItemDescription   
						,@v_vchDTCustomerItemCode  
						,@v_vchDTDGGoodsFlag  
						,@v_fltDTPrice  
						,@v_vchDTGrade  
						,@v_vchDTDefaultItemStatus  
						,@v_vchDTUDF1  
						,@v_vchDTUDF2  
						,@v_vchDTUDF3                   
						,@v_vchDTUDF4
						,@v_vchDTUDF5
						,@v_vchDTUDF6
						,@v_fltDTUDF7
						,@v_fltDTUDF8
						,@v_dtDTUDF9
						,@v_dtDTUDF10
						,@v_vchItemMasterID
						,@v_vchDTItemNumber
						,@v_vchBaseUOM
						,@v_vchDTItemUomID
						,@v_vchDTUOM
						,@v_vchUserID
						,GETDATE()  
					) 

				SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
				-- Check for any errors. If so, error number will not be equal to zero.
				IF @v_nErrorNumber <> 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
						SET @v_vchErrorType = 'ERROR-DETAIL'
						GOTO WRITE_PROCESS_LOG
					END
      
				-- Check for Number of rows affected.
				IF @v_nRowCount = 0
					BEGIN
						SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
						SET @v_vchErrorType = 'ERROR-DETAIL'
						GOTO WRITE_PROCESS_LOG
					END
	        
				---------------------------------------------------   
				-- Update Process Status = COMPLETED  
				---------------------------------------------------  
				UPDATE t_host_wms_outbound_order_detail SET processing_status = 'COMPLETED' WHERE outbound_order_detail_id = @v_vchHostOBDetailIDGUID  

				IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Processing add outbound detail completed'      
			END

		IF  EXISTS (SELECT * FROM t_host_wms_outbound_order_detail WHERE host_record_id = @in_vchHostRecordID AND processing_status = 'PENDING' AND line_number > @v_vchDTLineNumber)    
			GOTO OUTBOUND_DETAIL_LABEL   
	END  

	COMMIT_TRANS: 
		COMMIT TRANSACTION
		SET @out_vchErrorCode = '0'
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;

	-----------------------------------------------------------------------------------
	-- WRITE PROCESS LOG
	-----------------------------------------------------------------------------------
	BEGIN
	WRITE_PROCESS_LOG:
		ROLLBACK TRANSACTION;
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
		
		SET @v_vchLogType = 'IMPORT ERROR'  
		IF @v_vchErrorType = 'ERROR-MASTER'
			BEGIN 
				SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']'
											+ 'Record Type: [' + ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'	
				SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
											+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
											+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
				SELECT @v_vchProcessData4 =   'Order Type: ['+ISNULL(@v_vchOrderType, '') + ']' 
											+ ' Order Status: ['+ISNULL(@v_vchOrderStatus, '') + ']'
											+ ' Order Date: ['+CONVERT(VARCHAR(30),ISNULL(@v_dtOrderCreateDate, '')) + ']' 
											+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'
				SELECT @v_vchMessage = 'Error Code [' + @out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE') 
			END
		ELSE IF @v_vchErrorType = 'ERROR-DETAIL'
			BEGIN 
				SELECT @v_vchProcessData1 = 'Error Code ['+ @out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
				SELECT @v_vchProcessData2 =  'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']'
											+ 'Record Type: ['+ISNULL(@v_vchRecordType, '') + ']'
											+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
											+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'			
				SELECT @v_vchProcessData3 =   'Order Number: ['+ISNULL(@v_vchDTOrderNumber, '') + ']'   
											+ ' Warehouse: ['+ISNULL(@v_vchDTWarehouse, '') + ']' 
											+ ' Owner: ['+ISNULL(@v_vchDTOwnerCode, '') + ']'										 
				SELECT @v_vchProcessData4 =  'Line Number: ['+ISNULL(@v_vchDTLineNumber, '') + ']'   	
											+ ' Item Number: ['+ISNULL(@v_vchDTItemNumber, '') + ']' 
											+ ' Quantity: ['+ISNULL(str(@v_fltDTQuantity, 12), '') + ']' 
											+ ' UOM: ['+ISNULL(@v_vchDTUOM, '') + ']'   
											+ ' User ID: ['+ISNULL(@v_vchDTUserID, '') + ']' 
				SELECT @v_vchMessage = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			END 
			

		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']'  
					+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
					+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
					+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
			SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
					+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
					+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
					+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
					+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		END
		 
		SET @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'OUTBOUND'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchOrderNumber,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())
 
		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  
		UPDATE t_host_wms_outbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_outbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
		UPDATE t_host_wms_outbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  

	GOTO EXIT_LABEL;
	END
END TRY  

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
ROLLBACK TRANSACTION
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
	-- Future, Add a Log action for inserting into the Process Log
		
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER()
		, @v_vchSqlErrorMessage = ERROR_MESSAGE()
		, @v_intSqlErrorState = ERROR_STATE()
		, @v_intSqlErrorSeverity = ERROR_SEVERITY()
		, @v_intSqlErrorLine = ERROR_LINE()
		, @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
	SET @v_vchMessage = 'SQL Error Message: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
	SELECT @v_vchProcessData3 = 'Order Number: ['+ISNULL(@v_vchOrderNumber, '') + ']'
								+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
								+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
	SET  @v_vchProcessData4 = ''

	SET @out_vchErrorCode = @v_intSqlErrorNumber 
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage

	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END	
			
	INSERT INTO [dbo].[t_interface_process_log_execute]
		([inf_log_id]
		,[process]
		,[host_record_id]
		,[data_number]
		,[error_code]
		,[error_msg]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[create_date])
	VALUES
		(NEWID()
		,'OUTBOUND'
		,LEFT(@in_vchHostRecordID, 1000) 
		,LEFT(ISNULL(@v_vchOrderNumber,'NO ORDER'), 1000)   
		,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
		,LEFT(ISNULL(@v_vchMessage,'NO MESSAGE'), 500)
		,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
		,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
		,GETDATE())

	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  

	UPDATE t_host_wms_outbound_order SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_outbound_order_detail SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID  
	UPDATE t_host_wms_outbound_order_comment SET processing_status= 'ERROR' WHERE host_record_id = @in_vchHostRecordID

END CATCH
   
-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		 
END


/*
EXEC usp_ProcessHostOutboundOrder @in_vchApplicationID	  ='2A14C878-2292-44B0-9CE6-F791C7E9870A'
								 , @in_vchApplicationName ='HIM'
