/****** Object:  StoredProcedure [dbo].[usp_ProcessHostPurchase]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostPurchase]  
	@in_vchApplicationID	VARCHAR(40)  = NULL,	--Required  
	@in_vchApplicationName	NVARCHAR(100)= NULL,	--Required  
	@in_vchRefID			VARCHAR(40)	 = NULL	--Required
	--@in_vchPurchaseID		VARCHAR(40)	 = NULL,	--Required
	--@in_vchHostRecordID		VARCHAR(40)	 = NULL	--Required
AS  
BEGIN
	DECLARE
	 
	 -- Error handling variables
	@c_vchObjName           NVARCHAR(30), -- The name that uniquely tags this object.
	@v_intLocale			INTEGER, 
	@v_vchTableName			NVARCHAR(50),
	@v_vchLogType			NVARCHAR(50),
	@v_vchDevice			NVARCHAR(50),

	@v_intSqlErrorNumber    INTEGER,
	@v_intSqlErrorLine		INTEGER,
	@v_intSqlErrorState		INTEGER,
	@v_intSqlErrorSeverity	INTEGER,
	@v_vchSqlErrorMessage	NVARCHAR(2048),
	@v_vchSqlErrorProcedure NVARCHAR(200),  
	@v_vchProcessData1		NVARCHAR(100),
	@v_vchProcessData2		NVARCHAR(100),
	@v_vchProcessData3		NVARCHAR(100),
	@v_vchProcessData4		NVARCHAR(100),
	
    --  Log Handling Variables
	@v_intLogLevel          INTEGER = 3,			-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	@v_vchLogAction			NVARCHAR(25) = 'PRINT',  -- PRINT, LOG,
	@v_vchErrorCode			NVARCHAR(200),
	@v_vchMessage           NVARCHAR(500)
	
	--------------------------------------------------------------  
	-- Set Constants and Variables  
	-------------------------------------------------------------- 
	SET @v_intLocale = 1033; -- English
	SET @c_vchObjName = 'usp_ProcessHostPurchase'; 
	SET @v_vchTableName = 't_host_wms_purchase'; 
	SET @v_vchLogType = 'ERROR IMPORT';
	SET @v_vchDevice = 'usp_ProcessHostPurchase' 

BEGIN TRY  
	BEGIN TRANSACTION;
	------------------------------------------------------------  
	--  Get the Table Variables  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'  
	-- Future, Add a Log action for inserting into the Process Log      
	select @in_vchRefID
	SELECT p.[purchase_id]
		 , p.[processing_code]
		 , p.[processing_status]
		 , p.[purchase_number]
		 , item.item_master_id
		 , p.[item_number]
		 , item.description as item_description
		 , p.[purchase_qty]
		 , p.[purchase_uom]
		 , p.[required_date]
		 , p.[requisitioner]
		 , p.[create_by]
	INTO #tPurchasePending
	FROM [dbo].[t_host_wms_purchase] p
	LEFT JOIN t_wms_item item ON p.item_number = item.item_number
	WHERE ref_id = @in_vchRefID
	AND processing_code = 'PENDING'
	select * from #tPurchasePending

	IF EXISTS (SELECT purchase_id FROM #tPurchasePending WHERE ISNULL(item_master_id,'') = '')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Item (Item UOM)'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @v_vchErrorCode = 'ERROR-IFMAN-015' -- Invalid Item Number
			SET @v_vchLogType = 'IMPORT ERROR'  
			SELECT @v_vchProcessData1 = 'Error Code ['+@v_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			
			SELECT @v_vchProcessData2 += ' Purchase Number: [' + ISNULL(purchase_number, '') + ']'		
										+ ' Item Number: [' + ISNULL(item_number, '') + ']'
			FROM #tPurchasePending
			WHERE ISNULL(item_master_id,'') = ''

			SELECT @v_vchMessage = 'Error Code ['+@v_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@v_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
			GOTO WRITE_PROCESS_LOG 
		END
	
	DELETE FROM [t_wms_purchase] WHERE purchase_number IN (SELECT purchase_number FROM #tPurchasePending)
	INSERT INTO [dbo].[t_wms_purchase]
			([purchase_id]
			,[purchase_number]
			,[item_master_id]
			,[item_number]
			,[item_description]
			,[purchase_qty]
			,[purchase_uom]
			,[required_date]
			,[requisitioner]
			,[create_by]
			,[create_date])
		SELECT NEWID()
			,purchase_number
			,item_master_id
			,item_number
			,item_description
			,purchase_qty
			,purchase_uom
			,required_date
			,requisitioner
			,create_by
			,GETDATE()
		FROM #tPurchasePending

	UPDATE t_host_wms_purchase SET processing_status = 'COMPLETE',interface_complete_date = GETDATE()
	WHERE ref_id = @in_vchRefID

	DROP TABLE #tPurchasePending
	------------------------------------------------------------  
	--  Finished All. Now Exit SPROC  
	COMMIT TRANSACTION;
	------------------------------------------------------------  
	GOTO EXIT_LABEL;
 
-----------------------------------------------------------------------------------
-- WRITE PROCESS LOG
-----------------------------------------------------------------------------------
WRITE_PROCESS_LOG:  
	ROLLBACK TRANSACTION  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'  
	-- Future, Add a Log action for inserting into the Process Log  

	IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
	BEGIN
		SELECT	'Field List:' +'App ID: ['+ISNULL(@in_vchApplicationID, '') + ']' 
				+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
				+' Device: ['+ISNULL(@v_vchDevice, '') + ']' 
				+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
				+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
		SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
				+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
				+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
				+' Message: ['+ISNULL(@v_vchMessage, '') + ']' 
	END
	 
	INSERT INTO [dbo].[t_com_process_log]
		([app_id]
		,[log_type]
		,[warehouse]
		,[device]
		,[process]
		,[process_datetime]
		,[data_1]
		,[data_2]
		,[data_3]
		,[data_4]
		,[message]
		,[create_date]
		,[create_by])
	VALUES
		( LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
		, LEFT(ISNULL('', 'NO WH DEFINED'), 25)
		, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
		, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
		, GETDATE()
		, ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA')
		, LEFT(@v_vchProcessData2, 1000)
		, LEFT(@v_vchProcessData3, 1000)
		, LEFT(@v_vchProcessData4, 1000)
		, LEFT(ISNULL(@v_vchMessage, 'NO MESSAGE'), 100)
		, GETDATE()
		, 'OGA')

	
	---------------------------------------------------   
	-- Update Processing Status in host table = 'ERROR'  
	---------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
	-- Future, Add a Log action for inserting into the Process Log  
	UPDATE t_host_wms_purchase SET processing_status = 'ERROR' WHERE ref_id = @in_vchRefID

	GOTO EXIT_LABEL  
END TRY   

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
	--  Insert a message into the Process log about the Error
	--  Use the following functions to gather as much information as possible and load into the Process Log
	--  ERROR_NUMBER: returns the error number, and is the same value of @@ERROR.
	--  ERROR_MESSAGE: returns the full message text of the error. The text includes the values supplied for any substitutable parameters, such as lengths, object names, or times.
	--  ERROR_SEVERITY: returns the severity level of the error that invoked the CATCH block.
	--  ERROR_STATE: returns the state number of the error.
	--  ERROR_LINE: returns the line number where the error occurred.
	--  ERROR_PROCEDURE: returns the name of the stored procedure or trigger for which the error occurred.
	
	ROLLBACK TRANSACTION
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
		-- Future, Add a Log action for inserting into the Process Log
		
		SELECT 
			@v_intSqlErrorNumber = ERROR_NUMBER(),
			@v_vchSqlErrorMessage = ERROR_MESSAGE(),
			@v_intSqlErrorState = ERROR_STATE(),
			@v_intSqlErrorSeverity = ERROR_SEVERITY(),
			@v_intSqlErrorLine = ERROR_LINE(),
			@v_vchSqlErrorProcedure = ERROR_PROCEDURE()
			
		SET @v_vchMessage = 'SQL Error Message: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
		SET @v_vchProcessData1 = 'SQL Error Number: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+ltrim(rtrim(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+ltrim(rtrim(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
		SET  @v_vchProcessData2 = @v_vchSqlErrorMessage
		SET  @v_vchProcessData3 = ''
		SET  @v_vchProcessData4 = ''
		
		SET @v_vchErrorCode = @v_intSqlErrorNumber
		---------------------------------------------------------------------------
		-- Print Error Message if the Logging is >= 4
		---------------------------------------------------------------------------
		IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
			BEGIN
				SELECT 'Field List:' +'Error Message: ['+ISNULL(@v_vchMessage, '')+']'  
				SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
				SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
				SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
				SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
				SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
				SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
			END	
			
		INSERT INTO [dbo].[t_com_process_log]
			   ([app_id]
			   ,[log_type]
			   ,[warehouse]
			   ,[device]
			   ,[process]
			   ,[process_datetime]
			   ,[data_1]
			   ,[data_2]
			   ,[data_3]
			   ,[data_4]
			   ,[message]
			   ,[create_date]
			   ,[create_by])
		 VALUES
		 		(LEFT(ISNULL(@in_vchApplicationID, 'NO APP ID'), 40)
		 		, LEFT(ISNULL(@v_vchLogType, 'NO LOG TYPE'), 50)
				, LEFT(ISNULL('', 'NO WH DEFINED'), 25)
				, LEFT(ISNULL(@v_vchDevice, 'NO DEVICE'), 50)
				, LEFT(ISNULL(@c_vchObjName, 'NO PROCESS/OBJECT'), 50)
				, GETDATE()
				, ISNULL(left(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
				, LEFT(@v_vchProcessData2, 1000)
				, LEFT(@v_vchProcessData3, 1000)
				, LEFT(@v_vchProcessData4, 1000)
				, LEFT(ISNULL(@v_vchMessage, 'Part of the SQL Server Message is returning NULL' ), 100)
				, GETDATE()
				, 'OGA')	
			
		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  

		UPDATE t_host_wms_purchase SET processing_status = 'ERROR' WHERE ref_id = @in_vchRefID

END CATCH 
   
-----------------------------------------------------------------------------------  
--                            Exit the Process  
-----------------------------------------------------------------------------------   
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
END



GO
/****** Object:  StoredProcedure [dbo].[usp_ProcessHostSupplier]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_ProcessHostSupplier]
	@in_vchApplicationID	VARCHAR(40),			--Required
	@in_vchApplicationName	NVARCHAR(10),			--Required
	@in_vchHostRecordID		VARCHAR(40),			--Required
	@in_vchDevice			NVARCHAR(50),			--Required
	@in_vchUserID			NVARCHAR(25) = NULL,	--Required 
	@out_vchErrorCode		NVARCHAR(50) OUTPUT,
	@out_vchErrorMessage	NVARCHAR(500) OUTPUT
AS
BEGIN
	DECLARE @v_vchApplicationID		NVARCHAR(40) = 'IMPORT INTERFACE (TABLE)'
	DECLARE @c_vchObjName			NVARCHAR(30) = 'usp_ProcessHostSupplier'
	DECLARE @v_intSqlErrorNumber    INTEGER
	DECLARE @v_intSqlErrorLine		INTEGER
	DECLARE @v_intSqlErrorState		INTEGER
	DECLARE @v_intSqlErrorSeverity	INTEGER
	DECLARE @v_vchSqlErrorMessage	NVARCHAR(2500)
	DECLARE @v_vchSqlErrorProcedure NVARCHAR(200)  
	DECLARE @v_vchProcessData1		NVARCHAR(100)
	DECLARE @v_vchProcessData2		NVARCHAR(100)
	DECLARE @v_vchProcessData3		NVARCHAR(100)
	DECLARE @v_vchProcessData4		NVARCHAR(100)
	DECLARE @v_nErrorNumber			INTEGER
	DECLARE @v_nRowCount            INTEGER
	DECLARE @v_intLocale			INTEGER	= 1033; -- 1033 : English, 1054 : THAI
	DECLARE @Round					INT
	    
	--  Log Handling Variables
	DECLARE @v_vchLogType			NVARCHAR(50) = 'ERROR IMPORT' 
	DECLARE @v_intLogLevel          INTEGER = 3				-- 0, - No Extra Logging, 3 Processing Steps, 4 More detail, 5 - Massive Detail
	DECLARE @v_vchLogAction			NVARCHAR(25) = 'PRINT'	-- PRINT, LOG,  
 	DECLARE @v_vchTableName			NVARCHAR(50)
	
	-- Local Variables
	DECLARE @v_vchWhMasterID		UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchOwnerID			UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchSupplierID		UNIQUEIDENTIFIER = NULL	
 	
	-- Table Variables 
	DECLARE @v_vchProcessingCode    NVARCHAR(40) -- Required
	DECLARE @v_vchProcessingStatus  NVARCHAR(40) -- Required
	DECLARE @v_vchSupplierCode      NVARCHAR(50) -- Required
	DECLARE @v_vchWarehouse			NVARCHAR(25)
	DECLARE @v_vchOwnerCode			NVARCHAR(40)
	DECLARE @v_vchSupplierName      NVARCHAR(300)
	DECLARE @v_vchDescription		NVARCHAR(200) 
	DECLARE @v_vchAddrLine1			NVARCHAR(300)
	DECLARE @v_vchAddrLine2			NVARCHAR(300)
	DECLARE @v_vchAddrLine3			NVARCHAR(300)
	DECLARE @v_vchCity		        NVARCHAR(100)
	DECLARE @v_vchProvince			NVARCHAR(100)
	DECLARE @v_vchPostalCode		NVARCHAR(50)
	DECLARE @v_vchCountryCode		NVARCHAR(10)
	DECLARE @v_vchCountryName		NVARCHAR(100)
	DECLARE @v_vchPhone				NVARCHAR(50)
	DECLARE @v_vchFax				NVARCHAR(50)
	DECLARE @v_vchEmailAddress		NVARCHAR(200)
	DECLARE @v_vchContact			NVARCHAR(200)
	DECLARE @v_vchCategory			NVARCHAR(50)
	DECLARE @v_vchPriority			NVARCHAR(10)
	DECLARE @v_vchIsActive		    NVARCHAR(3)
	DECLARE @v_vchUserID			NVARCHAR(25)
	DECLARE @v_vchUDF1				NVARCHAR(50)  
	DECLARE @v_vchUDF2				NVARCHAR(50)  
	DECLARE @v_vchUDF3				NVARCHAR(50)  
	DECLARE @v_vchUDF4				NVARCHAR(50)
	DECLARE @v_vchUDF5				NVARCHAR(50)
	DECLARE @v_vchUDF6				NVARCHAR(50)
	DECLARE @v_fltUDF7				FLOAT
	DECLARE @v_fltUDF8				FLOAT
	DECLARE @v_dtUDF9				DATETIME
	DECLARE @v_dtUDF10				DATETIME

BEGIN TRY
	------------------------------------------------------------
	--  Get the Table Variables
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Starting the process inside the BEGIN TRY Select rows from INSERTED'
	SELECT TOP 1 @v_vchProcessingCode  = processing_code
		,@v_vchProcessingStatus = processing_status		
		,@v_vchSupplierCode     = supplier_code
		,@v_vchSupplierName     = name
		,@v_vchWarehouse		= wh_id
		,@v_vchOwnerCode		= owner_id
		,@v_vchDescription	    = description
		,@v_vchAddrLine1		= addr_line_1
		,@v_vchAddrLine2		= addr_line_2
		,@v_vchAddrLine3		= addr_line_3
		,@v_vchCity		        = city
		,@v_vchProvince			= province
		,@v_vchPostalCode		= postal_code
		,@v_vchCountryCode		= country_code
		,@v_vchCountryName		= country_name
		,@v_vchPhone			= phone
		,@v_vchFax				= fax
		,@v_vchEmailAddress		= email
		,@v_vchContact			= contact
		,@v_vchCategory			= category
		,@v_vchPriority			= priority
		,@v_vchIsActive		    = CASE WHEN ISNULL(is_active,'') = '' THEN 'YES' ELSE is_active END
		,@v_vchUserID			= create_by
		,@v_vchUDF1				= user_def1
		,@v_vchUDF2				= user_def2
		,@v_vchUDF3				= user_def3
		,@v_vchUDF4				= user_def4
		,@v_vchUDF5				= user_def5
		,@v_vchUDF6				= user_def6
		,@v_fltUDF7				= user_def7
		,@v_fltUDF8				= user_def8
		,@v_dtUDF9				= user_def9
		,@v_dtUDF10				= user_def10
	FROM t_host_wms_supplier
	WHERE host_record_id = @in_vchHostRecordID
	AND processing_status	= 'PENDING'

	------------------------------------------------------------
	--  Check for Required Fields
	--  log_type, warehouse, tran code, start tran date, location, quantity 
	-- 	app_id, device, user id, error_code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking Required Fields'
		-- Future, Add a Log action for inserting into the Process Log		
		
	IF ISNULL(@v_vchProcessingCode,'') = ''
		OR ISNULL(@v_vchProcessingStatus,'') = ''
		OR ISNULL(@v_vchOwnerCode,'') = ''
		OR ISNULL(@v_vchSupplierCode,'') = ''
		OR ISNULL(@v_vchSupplierName,'') = ''
	    OR ISNULL(@v_vchUserID,'') = '' 
		BEGIN
			------------------------------------------------------------
			--  Missing Required Fields 
			------------------------------------------------------------
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Missing Required Fields'
			IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  SELECT 'Field List:' +'Processing Code: ['+ISNULL(@v_vchProcessingCode, '')+ ']' 
																  + ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '')+ ']' 
																  + ' Supplier Code: ['+ISNULL(@v_vchSupplierCode, '') + ']' 
																  + ' Supplier Name: ['+ISNULL(@v_vchSupplierName, '') + ']' 
																  + ' Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
																  + ' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
																  
			-- Future, Add a Log action for inserting into the Process Log
			SET @out_vchErrorCode = 'ERROR-IFMAN-001' -- Required Fields Missing
			GOTO WRITE_PROCESS_LOG
		END	
	
	------------------------------------------------------------
	--  Check Valid Processing Code
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Checking for Valid Processing Code'	
	-- Future, Add a Log action for inserting into the Process Log
		
	IF @v_vchProcessingCode NOT in ('ADD', 'UPDATE', 'DELETE')
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Code:[ '+ISNULL(@v_vchProcessingCode, '')+']'
			-- Future, Add a Log action for inserting into the Process Log

			SET @out_vchErrorCode = 'ERROR-0020' -- Invalid Processing Code
			GOTO WRITE_PROCESS_LOG
		END
	
	------------------------------------------------------------
	-- Check Valid Processing Status
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Processing Status'
	-- Future, Add a Log action for inserting into the Process Log

	IF (@v_vchProcessingStatus <> 'PENDING')
		BEGIN
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Invalid Processing Status:[ '+ISNULL(@v_vchProcessingStatus, '')+']'
			-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-0021' -- Invalid Processign Status
			GOTO WRITE_PROCESS_LOG
		END
	
	------------------------------------------------------------  
	-- Check for Valid Owner  
	------------------------------------------------------------  
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Checking for Valid Owner'  
	-- Future, Add a Log action for inserting into the Process Log  

	SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @v_vchOwnerCode AND is_active = 'YES'
	IF (@v_vchOwnerID IS NULL)
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Invalid Valid Owner'  
			-- Future, Add a Log action for inserting into the Process Log  

			SET @out_vchErrorCode = 'ERROR-IFMAN-25' -- Invalid Owner  
			GOTO WRITE_PROCESS_LOG
		END 	
	
	SET @v_vchSupplierID = NULL
	SELECT @v_vchSupplierID = supplier_id FROM t_wms_supplier WHERE supplier_code = @v_vchSupplierCode AND owner_id = @v_vchOwnerID
	IF @v_vchSupplierID IS NOT NULL
		BEGIN
			SET @v_vchProcessingCode = 'UPDATE'
		END
	ELSE
		BEGIN
			SET @v_vchProcessingCode = 'ADD'  
		END

	------------------------------------------------------------
	--  Processing for 'DELETE' the Supplier.
	------------------------------------------------------------	
	IF @v_vchProcessingCode = 'DELETE'
		BEGIN
			IF @v_vchSupplierID IS NULL
				BEGIN
					IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Supplier is Invalid'  
					-- Future, Add a Log action for inserting into the Process Log    
		  
					SET @out_vchErrorCode = 'ERROR-IFMAN-059' -- Not found supplier for delete 
					GOTO WRITE_PROCESS_LOG
				END

			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete'
			-- Future, Add a Log action for inserting into the Process Log
					
			DELETE FROM t_wms_supplier WHERE supplier_id = @v_vchSupplierID
			UPDATE t_host_wms_supplier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing Delete Supplier Completed'	
			-- Future, Add a Log action for inserting into the Process Log
			
			GOTO COMMIT_TRANS;
		END	
	 
	------------------------------------------------------------
	--  Check the Supplier for a ADD duplicate.
	------------------------------------------------------------
	IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Checking for Duplicate Supplier Code'	
	-- Future, Add a Log action for inserting into the Process Log	
	
	IF @v_vchProcessingCode = 'ADD' and @v_vchSupplierID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Duplicate Supplier Code:['+@v_vchSupplierCode+']'
				-- Future, Add a Log action for inserting into the Process Log
			
			SET @out_vchErrorCode = 'ERROR-IFMAN-016' -- Duplicate Supplier
			GOTO WRITE_PROCESS_LOG
		END
		
	------------------------------------------------------------
	--  Insert the Supplier data to WMS Table.
	------------------------------------------------------------		
	IF @v_vchProcessingCode = 'ADD' and @v_vchSupplierID IS NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD for Supplier:['+@v_vchSupplierCode+']'
			-- Future, Add a Log action for inserting into the Process Log
			INSERT INTO t_wms_supplier(
			      supplier_code 
				, supplier_name
				, [description]
				, owner_id
				, addr_line_1
				, addr_line_2
				, addr_line_3
				, city
				, province
				, postal_code
				, country_code
				, country_name
				, phone
				, fax
				, email
				, contact 
				, category
				, [priority]
				, user_def1
				, user_def2
				, user_def3
				, user_def4
				, user_def5
				, user_def6
				, user_def7
				, user_def8
				, user_def9
				, user_def10
				, is_active
				, create_date
				, create_by
				)   
			VALUES (
			      @v_vchSupplierCode
				, @v_vchSupplierName
				, @v_vchDescription
				, @v_vchOwnerID
				, @v_vchAddrLine1
				, @v_vchAddrLine2
				, @v_vchAddrLine3
				, @v_vchCity
				, @v_vchProvince
				, @v_vchPostalCode
				, @v_vchCountryCode
				, @v_vchCountryName
				, @v_vchPhone
				, @v_vchFax
				, @v_vchEmailAddress
				, @v_vchContact
				, @v_vchCategory
				, @v_vchPriority 
				, @v_vchUDF1
				, @v_vchUDF2
				, @v_vchUDF3
				, @v_vchUDF4
				, @v_vchUDF5
				, @v_vchUDF6
				, @v_fltUDF7
				, @v_fltUDF8
				, @v_dtUDF9
				, @v_dtUDF10
				, @v_vchIsActive
				, GETDATE()
				, @v_vchUserID
				)
			
			SELECT @v_nErrorNumber = @@ERROR, @v_nRowCount = @@ROWCOUNT 
			-- Check for any errors. If so, error number will not be equal to zero.
			IF @v_nErrorNumber <> 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0017' -- Failed to Insert Row into Table
					GOTO WRITE_PROCESS_LOG
				END
      
			-- Check for Number of rows affected.
			IF @v_nRowCount = 0
				BEGIN
					SET @out_vchErrorCode = 'ERROR-0016' -- Failed to Insert Row into Table
					GOTO WRITE_PROCESS_LOG
				END
			
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_supplier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
	
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing ADD Supplier Completed'				
			GOTO COMMIT_TRANS
		END
		
	------------------------------------------------------------
	--  Update the Supplier data to WMS Table.
	------------------------------------------------------------			
	IF @v_vchProcessingCode = 'UPDATE' and @v_vchSupplierID IS NOT NULL
		BEGIN
			IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Check Update of Supplier:['+@v_vchSupplierCode+']'
			-- Future, Add a Log action for inserting into the Process Log
			 
			UPDATE t_wms_supplier SET
				  supplier_name = @v_vchSupplierName
				, [description] = @v_vchDescription
				, owner_id = @v_vchOwnerID
				, addr_line_1 = @v_vchAddrLine1
				, addr_line_2 = @v_vchAddrLine2
				, addr_line_3 = @v_vchAddrLine3
				, city =  @v_vchCity
				, province =  @v_vchProvince
				, postal_code = @v_vchPostalCode
				, country_code = @v_vchCountryCode
				, country_name = @v_vchCountryName
				, phone = @v_vchPhone
				, fax = @v_vchFax
				, email= @v_vchEmailAddress
				, contact = @v_vchContact
				, category = @v_vchCategory
				, [priority] = @v_vchPriority
				, user_def1 = @v_vchUDF1
				, user_def2 = @v_vchUDF2
				, user_def3 = @v_vchUDF3
				, user_def4 = @v_vchUDF4
				, user_def5 = @v_vchUDF5
				, user_def6 = @v_vchUDF6
				, user_def7 = @v_fltUDF7
				, user_def8 = @v_fltUDF8
				, user_def9 = @v_dtUDF9
				, user_def10 = @v_dtUDF10
				, is_active = @v_vchIsActive
				, update_by = @v_vchUserID
				, update_date = GETDATE()
			WHERE supplier_id = @v_vchSupplierID
			
			---------------------------------------------------	
			-- Update Process Status = COMPLETED
			---------------------------------------------------
			UPDATE t_host_wms_supplier SET processing_status = 'COMPLETED' WHERE host_record_id = @in_vchHostRecordID
			
			IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Processing UPDATE Supplier Completed'
			GOTO COMMIT_TRANS
		END
	
	COMMIT_TRANS:  
		SET @out_vchErrorCode = '0'
		SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value('SAVE_SUCCESS', @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')
		GOTO EXIT_LABEL;
	-----------------------------------------------------------------------------------
	-- WRITE PROCESS LOG
	-----------------------------------------------------------------------------------
	BEGIN
	WRITE_PROCESS_LOG: 
		IF @v_intLogLevel >= 3 AND @v_vchLogAction = 'PRINT'  SELECT 'Writing Error to Process Log'
		-- Future, Add a Log action for inserting into the Process Log
	
		IF @v_intLogLevel >= 4 AND @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT	'Field List:' +'App ID: ['+ISNULL(@v_vchApplicationID, '') + ']' 
					+' Log Type: ['+ISNULL(@v_vchLogType, '') + ']' 
					+' Device: ['+ISNULL(@in_vchDevice, '') + ']' 
					+' Object Name: ['+ISNULL(@c_vchObjName, '') + ']' 
					+' Data1: ['+ISNULL(@v_vchProcessData1, '') + ']' 
			SELECT ' Data2: ['+ISNULL(@v_vchProcessData2, '') + ']' 
					+' Data3: ['+ISNULL(@v_vchProcessData3, '') + ']' 
					+' Data4: ['+ISNULL(@v_vchProcessData4, '') + ']' 
					+' Message: ['+ISNULL(@out_vchErrorMessage, '') + ']' 
					+' User ID: ['+ISNULL(@v_vchUserID, '') + ']' 
		END

		SET @v_vchLogType = 'IMPORT ERROR'
		SELECT @v_vchProcessData1 = 'Error Code ['+@out_vchErrorCode + '] - ' + ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')		
		SELECT @v_vchProcessData2 = 'Host ID: [' +ISNULL(@in_vchHostRecordID, '')+ ']' 
									+ ' Processing Code: ['+ISNULL(@v_vchProcessingCode, '') + ']'
									+ ' Processing Status: ['+ISNULL(@v_vchProcessingStatus, '') + ']'
		SELECT @v_vchProcessData3 =  'Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
									+ ' Supplier Code: ['+ISNULL(@v_vchSupplierCode, '') + ']'
									+ ' Supplier Name: ['+ISNULL(@v_vchSupplierName, '') + ']' 
		SELECT @v_vchProcessData4 = ' Is Active: ['+ISNULL(@v_vchIsActive, '') + ']' 
									+ ' User ID: ['+ISNULL(@v_vchUserID, '') + ']'  
		SELECT @out_vchErrorMessage = ISNULL(dbo.usf_get_locale_text_value(@out_vchErrorCode, @v_intLocale), 'NO RESOURCE AVAILABLE FOR MESSAGE')

 		INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'SUPPLIER'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchSupplierCode,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())

		---------------------------------------------------   
		-- Update Processing Status in host table = 'ERROR'  
		---------------------------------------------------  
		IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Update processing status is error in host table'  
		-- Future, Add a Log action for inserting into the Process Log  
		UPDATE t_host_wms_supplier SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID

	GOTO EXIT_LABEL;
	END
END TRY

-----------------------------------------------------------------------------------
--                            Error Handling
-----------------------------------------------------------------------------------
BEGIN CATCH
IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  select 'Error Processing - Start the Begin Catch'	
-- Future, Add a Log action for inserting into the Process Log
		
	SELECT @v_intSqlErrorNumber = ERROR_NUMBER()
		, @v_vchSqlErrorMessage = ERROR_MESSAGE()
		, @v_intSqlErrorState = ERROR_STATE()
		, @v_intSqlErrorSeverity = ERROR_SEVERITY()
		, @v_intSqlErrorLine = ERROR_LINE()
		, @v_vchSqlErrorProcedure = ERROR_PROCEDURE()
	SET @out_vchErrorMessage = 'SQL Error Message: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorMessage, '')))+']'  
	SET @v_vchProcessData1 = 'SQL Error Number: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorNumber, 10), ''))) +']'  
							+'SQL Error Line: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorLine,10), '')))+']' 
							+'SQL Error State: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorState,10), '')))+']' 
							+'SQL Error Severity: ['+LTRIM(RTRIM(ISNULL(STR(@v_intSqlErrorSeverity,10), '')))+']' 
							+'SQL Error Procedure: ['+LTRIM(RTRIM(ISNULL(@v_vchSqlErrorProcedure, '')))+']' 
	SET  @v_vchProcessData2 = 'Host Record ID: ['+ISNULL(@in_vchHostRecordID, '') + ']'
	SELECT @v_vchProcessData3 = 'Supplier Code: ['+ISNULL(@v_vchSupplierCode, '') + ']'
								+ ' Warehouse: ['+ISNULL(@v_vchWarehouse, '') + ']'
								+ ' Owner: ['+ISNULL(@v_vchOwnerCode, '') + ']'
	SET @v_vchProcessData4 = @v_vchSqlErrorMessage
	
	SET @out_vchErrorCode = @v_intSqlErrorNumber
	SET @out_vchErrorMessage = @v_vchSqlErrorMessage

	---------------------------------------------------------------------------
	-- Print Error Message if the Logging is >= 4
	---------------------------------------------------------------------------
	IF @v_intLogLevel >= 4 and @v_vchLogAction = 'PRINT'  
		BEGIN
			SELECT 'Field List:' +'Error Message: ['+ISNULL(@out_vchErrorMessage, '')+']'  
			SELECT 'SQL Error Message: ['+ISNULL(@v_vchSqlErrorMessage, '')+']'  
			SELECT 'SQL Error Number: ['+ISNULL(STR(@v_intSqlErrorNumber, 10), '') +']'  
			SELECT 'SQL Error Line: ['+ISNULL(STR(@v_intSqlErrorLine,10), '')+']' 
			SELECT 'SQL Error State: ['+ISNULL(STR(@v_intSqlErrorState,10), '')+']' 
			SELECT 'SQL Error Severity: ['+ISNULL(STR(@v_intSqlErrorSeverity,10), '')+']' 
			SELECT 'SQL Error Procedure: ['+ISNULL(@v_vchSqlErrorProcedure, '')+']' 
		END

	SELECT @out_vchErrorMessage = @v_vchSqlErrorMessage
	INSERT INTO [dbo].[t_interface_process_log_execute]
			([inf_log_id]
			,[process]
			,[host_record_id]
			,[data_number]
			,[error_code]
			,[error_msg]
			,[data_1]
			,[data_2]
			,[data_3]
			,[data_4]
			,[create_date])
		VALUES
			(NEWID()
			,'SUPPLIER'
			,LEFT(@in_vchHostRecordID, 1000) 
			,LEFT(ISNULL(@v_vchSupplierCode,'NO ORDER'), 1000)   
			,LEFT(ISNULL(@out_vchErrorCode,'NO ERROR CODE'), 1000)   
			,LEFT(ISNULL(@out_vchErrorMessage,'NO MESSAGE'), 500)
			,ISNULL(LEFT(@v_vchProcessData1, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData2, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData3, 1000), 'NO DATA FOR DATA1')
			,ISNULL(LEFT(@v_vchProcessData4, 1000), 'NO DATA FOR DATA1')
			,GETDATE())

	---------------------------------------------------	
	-- Update Processing Status in host table = 'ERROR'
	---------------------------------------------------			
	UPDATE t_host_wms_supplier SET processing_status = 'ERROR' WHERE host_record_id = @in_vchHostRecordID

END CATCH

-----------------------------------------------------------------------------------
--                            Exit the Process
-----------------------------------------------------------------------------------	
EXIT_LABEL:
	IF @v_intLogLevel >= 3 and @v_vchLogAction = 'PRINT'  SELECT 'Exiting Procedure'
		-- Future, Add a Log action for inserting into the Process Log		
		 
END
GO
