/****** Object:  StoredProcedure [dbo].[usp_processLog_Insert]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_processLog_Insert]
(
	@in_vchDevice			NVARCHAR(50)='',
	@in_vchProcess			NVARCHAR(50)='',
	@in_vchFileName			NVARCHAR(1000)='',
	@in_vchErrorCode		NVARCHAR(1000)='',
	@in_vchMessageCode		NVARCHAR(1000)='',
	@in_vchData4			NVARCHAR(1000)='',
	@in_vchErrorType		NVARCHAR(50) = ''	--SP_ERROR,FILE_ERROR
)
AS
BEGIN
	DECLARE @v_vchMessage NVARCHAR(1000) = '',
			@v_vchSubject NVARCHAR(50) = '',
			@v_vchWh      nvarchar(25) = ''
			
	SELECT TOP 1 @v_vchWh = wh_id FROM t_wms_wh WHERE is_active = 'YES'
	SELECT @v_vchMessage = value FROM t_com_resource_detail 
	WHERE locale_id = '1033'
	AND resource_master_id = (SELECT top 1 resource_master_id FROM t_com_resource_master 
							  WHERE resource_name = @in_vchErrorCode)	
	
	IF @in_vchErrorCode <> 'NOT_WRITE_LOG'
		BEGIN
			INSERT INTO t_com_process_log
				(  process_id
				  ,app_id
				  ,log_type
				  ,warehouse
				  ,device
				  ,process
				  ,process_datetime
				  ,data_1
				  ,data_2
				  ,data_3
				  ,data_4
				  ,message
				  ,create_date
				  ,create_by
				)
			VALUES
				( NEWID()
				  ,'2A14C878-2292-44B0-9CE6-F791C7E9870A'	
				  ,'ERROR-INTERFACE'	
				  ,@v_vchWh
				  ,@in_vchDevice	
				  ,@in_vchProcess	
				  ,GETDATE()
				  ,@in_vchFileName
				  ,@in_vchErrorCode	
				  ,@in_vchMessageCode
				  ,@in_vchData4	
				  ,@v_vchMessage	
				  ,GETDATE()
				  ,'INTERFACE'	
				)
		END

	---------------------------------------------------	
	-- SEND EMAIL ERROR
	---------------------------------------------------		
	SET @v_vchSubject = 'Read text file error'
	SET @v_vchMessage =  CASE @in_vchErrorCode WHEN 'NOT_WRITE_LOG' THEN 'IMPORT DATA NOT SUCCESS' ELSE @in_vchErrorCode + '-' + @v_vchMessage END
						+ CASE ISNULL(@in_vchFileName,'') WHEN '' THEN '' ELSE '<BR>' + @in_vchFileName END 
						+ CASE ISNULL(@in_vchMessageCode,'') WHEN '' THEN '' ELSE '<BR>' + @in_vchMessageCode END
						+ CASE ISNULL(@in_vchData4,'') WHEN '' THEN '' ELSE '<BR>' + @in_vchData4 END
						+ '<BR>'

	EXEC usp_send_mail_error_interface @in_vchSubject	= @v_vchSubject
									 , @in_vchMessage	= @v_vchMessage
									 , @in_vchEmailType	= @in_vchErrorType

END	
GO
/****** Object:  StoredProcedure [dbo].[usp_put_count_reconcile]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_put_count_reconcile]
(
	@in_vchHospital			VARCHAR(40) = NULL,
	@in_vchPlanID			VARCHAR(40) = NULL,
	@in_vchSerialNumber		NVARCHAR(100)= NULL,
	@in_vchStatus			VARCHAR(50)  = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchUserID			NVARCHAR(50) = NULL,
	@in_vchCreateDate		DATETIME	= NULL,
	@out_vchResult			NVARCHAR(500)  OUTPUT
)
AS
BEGIN
	DECLARE	@v_vchWhMasterID	   VARCHAR(40) = NULL,
			@v_vchCountMasterID	   VARCHAR(40) = NULL,
			@v_vchCountDetailID	   VARCHAR(40) = NULL,
			@v_vchInventoryID	   VARCHAR(40) = NULL,
			@v_vchLocationID	   VARCHAR(40) = NULL,
			@v_vchLocation		   NVARCHAR(50) = NULL,
			@v_vchPalentLPN		   NVARCHAR(25) = NULL,
			@v_vchLPN			   NVARCHAR(25) = NULL,
			@v_vchWhItemMasterID   VARCHAR(40) = NULL,
			--@v_vchInvStatus		   NVARCHAR(50) = NULL,
			@v_vchLotNumber		   NVARCHAR(100) = NULL,
			@v_vchExpiryDate	   NVARCHAR(100) = NULL,
			@v_vchAttribute1	   NVARCHAR(100) = NULL,
			@v_vchAttribute2	   NVARCHAR(100) = NULL,
			@v_vchAttribute3	   NVARCHAR(100) = NULL,
			@v_vchAttribute4	   NVARCHAR(100) = NULL,
			@v_vchAttribute5	   NVARCHAR(100) = NULL,
			@v_vchItemNumber	   NVARCHAR(50) = NULL,
			@v_vchItemDesc		   NVARCHAR(200) = NULL,
			@v_vchExpectQty		   FLOAT = NULL,
			@v_vchDeliveryDate	   DATETIME = NULL,
			@v_vchOutboundOrderNo  NVARCHAR(50) = NULL,
			@v_vchItemCategory	   NVARCHAR(50) = NULL,
			@v_vchItemCategoryDesc NVARCHAR(200) = NULL,
			@v_vchTransactionID	   VARCHAR(40) = NULL
	
	BEGIN TRY
		-----------------------------------------------
		-- Find wh_master_id
		-----------------------------------------------
		SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE is_active = 'YES'

		-----------------------------------------------
		-- Get Count Master ID
		-----------------------------------------------
		SELECT @v_vchCountMasterID = count_master_id
		FROM t_wms_count_plan_master_external
		WHERE wh_master_id = @v_vchWhMasterID
		AND count_id = @in_vchPlanID

		----------------------------------------------
		-- Check Duplicate SN
		----------------------------------------------
		IF EXISTS(SELECT serial_number FROM t_wms_count_reconcile_external 
					WHERE count_master_id = @v_vchCountMasterID
					AND serial_number = @in_vchSerialNumber)
			BEGIN
				--08/04/2016 : ถ้าเจอซ้ำให้ return กลับไม่ได้ต้อง แจ้ง error
				SET @out_vchResult = 'Success'--'Duplicate SN';
				RETURN;
			END

		-----------------------------------------------	
		--Validate Location Master
		-----------------------------------------------	
		SELECT @v_vchLocationID = a.location_id
			,@v_vchLocation = b.location
		FROM t_wms_customer_location AS a 
		INNER JOIN t_wms_location AS b ON a.location_id = b.location_id
		WHERE b.wh_master_id = @v_vchWhMasterID 
		AND b.location = @in_vchLocation 
		AND b.is_active = 'YES'
		IF ISNULL(@v_vchLocationID,'') = ''
			BEGIN
				SET @out_vchResult = 'Location does not exists'
				RETURN;
			END

		-----------------------------------------------	
		-- Validate serial in count plan external
		-----------------------------------------------
		SELECT @v_vchCountDetailID  = planDT.count_plan_detail_id
			, @v_vchLocationID		= planDT.location_id
			, @v_vchPalentLPN		= planDT.parent_lpn
			, @v_vchLPN				= planDT.lpn
			, @v_vchWhItemMasterID	= planDT.wh_item_master_id
			--, @v_vchInvStatus		= planDT.inv_status
			, @v_vchLotNumber		= planDT.lot_number
			, @v_vchExpiryDate		= planDT.expiry_date
			, @v_vchAttribute1		= planDT.attribute1
			, @v_vchAttribute2		= planDT.attribute2
			, @v_vchAttribute3		= planDT.attribute3
			, @v_vchAttribute4		= planDT.attribute4
			, @v_vchAttribute5	    = planDT.attribute5
			, @v_vchItemNumber		= planDT.item_number
			, @v_vchItemDesc		= planDT.item_description
			, @v_vchExpectQty		= planDT.stock_qty
			, @v_vchDeliveryDate	= planDT.delivery_date
			, @v_vchOutboundOrderNo	= planDT.outbound_order_number
			, @v_vchItemCategory	= planDT.item_category
			, @v_vchItemCategoryDesc= planDT.item_category_description
		FROM t_wms_count_plan_master_external planMS
		LEFT JOIN t_wms_count_plan_detail_external planDT ON planMS.count_master_id = planDT.count_master_id
		WHERE planMS.count_master_id = @v_vchCountMasterID
		AND planDT.location_id = @v_vchLocationID
		AND planDT.serial_number = @in_vchSerialNumber
		AND planMS.customer_code = @in_vchHospital

		IF ISNULL(@v_vchCountDetailID,'') = ''
			BEGIN
				SELECT @v_vchInventoryID	= inventory_id	
					, @v_vchLocationID		= location_id	
					, @v_vchLocation		= location
					, @v_vchPalentLPN		= parent_lpn	
					, @v_vchLPN				= lpn			
					, @v_vchWhItemMasterID	= wh_item_master_id				
					--, @v_vchInvStatus		= inv_status					
					, @v_vchLotNumber		= lot_number					
					, @v_vchExpiryDate		= expiry_date					
					, @v_vchAttribute1		= attribute1					
					, @v_vchAttribute2		= attribute2					
					, @v_vchAttribute3		= attribute3					
					, @v_vchAttribute4		= attribute4					
					, @v_vchAttribute5	    = attribute5					
					, @v_vchItemNumber		= item_number					
					, @v_vchItemDesc		= description					
					, @v_vchExpectQty		= quantity						
					, @v_vchDeliveryDate	= delivery_date					
					, @v_vchOutboundOrderNo	= delivery_number			
					, @v_vchItemCategory	= item_category					
					, @v_vchItemCategoryDesc= item_category_desc
				FROM v_wms_inventory_count_external_order
				WHERE serial_number = @in_vchSerialNumber

				IF (ISNULL(@v_vchInventoryID,'') = '')
					BEGIN
						SELECT TOP 1 @v_vchTransactionID	= tran_id
							 , @v_vchLocationID		= loc.location_id	
							 , @v_vchLocation		= (CASE WHEN ISNULL(tranLog.location,'') = '' THEN tranLog.to_location ELSE tranLog.location END)
							 , @v_vchPalentLPN		= tranLog.parent_lpn	
							 , @v_vchLPN			= tranLog.lpn			
							 , @v_vchWhItemMasterID	= whItem.wh_item_master_id				
							 --, @v_vchInvStatus		= (CASE WHEN ISNULL(tranLog.status,'') = '' THEN tranLog.after_status ELSE tranLog.status END)				
							 , @v_vchLotNumber		= (CASE WHEN ISNULL(tranLog.lot_number,'') = '' THEN tranLog.after_lot_number ELSE tranLog.lot_number END)				
							 , @v_vchExpiryDate		= (CASE WHEN ISNULL(tranLog.expiry_date,'') = '' THEN tranLog.after_expiry_date ELSE tranLog.expiry_date END)					
							 , @v_vchAttribute1		= tranLog.attribute1					
							 , @v_vchAttribute2		= tranLog.attribute2					
							 , @v_vchAttribute3		= tranLog.attribute3					
							 , @v_vchAttribute4		= tranLog.attribute4					
							 , @v_vchAttribute5	    = tranLog.attribute5					
							 , @v_vchItemNumber		= tranLog.item_number					
							 , @v_vchItemDesc		= item.description					
							 , @v_vchExpectQty		= tranLog.quantity						
							 , @v_vchDeliveryDate	= (CASE tran_type WHEN 'OO_SHIP' THEN CONVERT(DATE,end_tran_datetime) ELSE NULL END)
							 , @v_vchOutboundOrderNo = tranLog.order_number			
							 , @v_vchItemCategory	 = cate.item_category					
							 , @v_vchItemCategoryDesc = cate.description 
						FROM t_com_tran_log tranLog
						LEFT JOIN t_wms_wh wh ON (CASE WHEN ISNULL(tranLog.to_warehouse,'') = '' THEN tranLog.warehouse ELSE tranLog.to_warehouse END) = wh.wh_id
						LEFT JOIN t_wms_owner own ON (CASE WHEN ISNULL(tranLog.to_owner,'') = '' THEN tranLog.owner ELSE  tranLog.to_owner END) = own.owner_code
						LEFT JOIN t_wms_location loc ON (CASE WHEN ISNULL(tranLog.location,'') = '' THEN tranLog.to_location ELSE tranLog.location END) = loc.location
						LEFT JOIN t_wms_item item ON tranLog.item_number = item.item_number AND own.owner_id = item.owner_id
						LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
						LEFT JOIN t_wms_category cate ON item.category_id = cate.category_id
						WHERE tranLog.tran_type IN ('OO_SHIP','INV_ADJUST')
						AND tranLog.serial_number = @in_vchSerialNumber
						ORDER BY tranLog.create_date DESC

						IF ISNULL(@v_vchTransactionID,'') = ''
							BEGIN
								SET @out_vchResult = 'Success' --Not found Data!;
								RETURN;
							END
					END

				--02/09/2016 [จากพี่ศิ] : ปรับแก้ไขให้ Insert Reconcile ให้ Status เป็น Unknown ไม่ให้ดึงจาก Inventory หรือ Log 
				SET @in_vchStatus = 'Unknown'
			END

		-----------------------------------------------	
		--INSERT COUNT RECONCILE
		-----------------------------------------------	
		INSERT INTO [dbo].[t_wms_count_reconcile_external]
			   ([count_reconcile_id]
			   ,[count_master_id]
			   ,[location_id]
			   ,[location]
			   ,[wh_item_master_id]
			   ,[inv_status]
			   ,[parent_lpn]
			   ,[lpn]
			   ,[lot]
			   ,[expiry_date]
			   ,[serial_number]
			   ,[attribute1]
			   ,[attribute2]
			   ,[attribute3]
			   ,[attribute4]
			   ,[attribute5]
			   ,[count_qty]
			   ,[create_date]
			   ,[create_by]
			   ,[item_number]
			   ,[item_description]
			   ,[expect_qty]
			   ,[delivery_date]
			   ,[outbound_order_number]
			   ,[item_category]
			   ,[item_category_description]
			)			   
		 VALUES
			   (NEWID()
			   ,@v_vchCountMasterID
			   ,@v_vchLocationID
			   ,@v_vchLocation
			   ,@v_vchWhItemMasterID
			   ,@in_vchStatus
			   ,@v_vchPalentLPN
			   ,@v_vchLPN
			   ,@v_vchLotNumber
			   ,@v_vchExpiryDate
			   ,@in_vchSerialNumber
			   ,@v_vchAttribute1
			   ,@v_vchAttribute2
			   ,@v_vchAttribute3
			   ,@v_vchAttribute4
			   ,@v_vchAttribute5
			   ,1
			   ,@in_vchCreateDate
			   ,@in_vchUserID
			   ,@v_vchItemNumber		
			   ,@v_vchItemDesc		
			   ,@v_vchExpectQty	
			   ,@v_vchDeliveryDate	
			   ,@v_vchOutboundOrderNo	
			   ,@v_vchItemCategory	
			   ,@v_vchItemCategoryDesc
			  )

		UPDATE t_wms_count_plan_detail_external
		SET count_qty = 1
		WHERE count_master_id = @v_vchCountMasterID
		AND count_plan_detail_id = @v_vchCountDetailID
		AND serial_number = @in_vchSerialNumber
		
		--Update Count Status
		UPDATE t_wms_count_plan_master_external SET count_status = 'IN PROCESS' WHERE count_master_id = @v_vchCountMasterID

		SET @out_vchResult = 'Success';
	END TRY		
	BEGIN CATCH
		SET @out_vchResult = ERROR_MESSAGE() ;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_put_count_scan_confirm]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_put_count_scan_confirm]
(
	@in_vchCountPlanID			NVARCHAR(50),
	@in_vchHospital				NVARCHAR(50),
	@in_vchHospitalSignature	NVARCHAR(500)=NULL,
	@in_vchHospitalPosition		NVARCHAR(50),
	@in_vchStaffSignature		NVARCHAR(500)=NULL,
	@in_vchStaffPosition		NVARCHAR(50),
	@in_vchDoctorName			NVARCHAR(50),
	@in_vchStaffName			NVARCHAR(50),
	@in_vchCloseDate			DATETIME	,
	@in_vchCloseBy				NVARCHAR(25),
	@in_vchCloseRemark			NVARCHAR(200)= NULL,
	@out_vchResult				NVARCHAR(500) OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;	
	DECLARE @v_vchCountMasterID		VARCHAR(40),
			@v_vchCountStatus		 NVARCHAR(10)

	BEGIN TRY
		SET @in_vchCloseDate = CONVERT(DATETIME, CONVERT(VARCHAR, CONVERT(DATE, @in_vchCloseDate)) +' ' + CONVERT(VARCHAR,GETDATE(),108))

		--Get Count MasterID
		SELECT @v_vchCountMasterID = count_master_id 
			,@v_vchCountStatus = count_status
		FROM t_wms_count_plan_master_external 
		WHERE count_id = @in_vchCountPlanID
		AND customer_code = @in_vchHospital

		IF ISNULL(@v_vchCountMasterID,'') = ''
			BEGIN
				SET @out_vchResult = 'Count ID ['+ @in_vchCountPlanID +'] not found!';
				RETURN;
			END

		IF @v_vchCountStatus <> 'CLOSE'
			BEGIN
				--เงื่อนไขในการ Close Plan คือ จะต้องมีค่า Hospital Signature และ Staff Signature
				IF (ISNULL(@in_vchHospitalSignature,'') <> '' AND ISNULL(@in_vchStaffSignature,'') <> '')
					BEGIN
						---------------------------------------------
						--Update Status close
						---------------------------------------------
						UPDATE t_wms_count_plan_master_external
						SET count_status ='CLOSE'
							,close_date	  = @in_vchCloseDate
							,close_by	  = @in_vchCloseBy
							,close_remark = @in_vchCloseRemark
							,hospital_signature = @in_vchHospitalSignature
							,hospital_position = @in_vchHospitalPosition
							,staff_signature = @in_vchStaffSignature
							,staff_position = @in_vchStaffPosition
							,doctor_name  = @in_vchDoctorName
							,staff_name   = @in_vchStaffName
						WHERE count_master_id = @v_vchCountMasterID

						---------------------------------------------
						--Insert temp for job
						---------------------------------------------
						INSERT INTO [dbo].[t_wms_count_external_close_plan]
								   ([close_id]
								   ,[count_master_id]
								   ,[processing_status]
								   ,[create_date]
								   ,[create_by])
							 VALUES
								   (NEWID()
								   ,@v_vchCountMasterID
								   ,'PENDING'
								   ,GETDATE()
								   ,@in_vchCloseBy)
					END
			END
			
		SET @out_vchResult = 'Success'
	END TRY
	BEGIN CATCH
		SET @out_vchResult = ERROR_MESSAGE();
	END CATCH
END


GO
