CREATE PROCEDURE [dbo].[usp_put_hospital_detail]
(
	@in_vchHospital NVARCHAR(50),
	@in_vchContact	NVARCHAR(200),
	@in_vchTel		NVARCHAR(50),
	@in_vchEmail	NVARCHAR(200),
	@in_vchFax		NVARCHAR(50),
	@in_vchMemo		NVARCHAR(300),
	@out_vchResult	NVARCHAR(10) OUTPUT
)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	BEGIN TRY
		UPDATE      t_wms_customer
		SET         phone = @in_vchTel, 
					fax =@in_vchFax, 
		            email = @in_vchEmail, 
					contact =@in_vchContact,
					memo =@in_vchMemo, 
					update_by = 'iOS', 
					update_date = GETDATE()
		WHERE		customer_code = @in_vchHospital
		SET @out_vchResult = 'Succes';
	END TRY
	BEGIN CATCH
		SET @out_vchResult = 'Error';
		SELECT ERROR_NUMBER() AS ErrorNumber, ERROR_MESSAGE() AS ErrorMessage;
	END CATCH
END



