/****** Object:  StoredProcedure [dbo].[usp_put_sn_use]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_put_sn_use]
(
	@in_vchCountID			VARCHAR(40) = NULL,
	@in_vchHospital			VARCHAR(40) = NULL,
	@in_vchLocation			NVARCHAR(50) = NULL,
	@in_vchStatus			VARCHAR(50) = NULL,
	@in_vchPatient			VARCHAR(50) = NULL,
	@in_vchDoctorName		NVARCHAR(50)= NULL,
	@in_dtUseDate			DATETIME = NULL,
	@in_vchBudget			NVARCHAR(50)= NULL,
	@in_vchMemo				NVARCHAR(200)= NULL,
	@in_vchSerialNumber		NVARCHAR(50)= NULL,
	@in_vchUserID			NVARCHAR(50)= NULL,
	@out_vchResult			NVARCHAR(500) OUTPUT
)
AS
BEGIN
	DECLARE	@v_vchWhMasterID	 VARCHAR(40) = NULL,
			@v_vchDeliveryNumber VARCHAR(40) = NULL,
			@v_vchDeliveryDate	 DATETIME = NULL,
			@v_vchItemNumer		 VARCHAR(40) = NULL,
			@v_vchPalentLPN		 NVARCHAR(25) = NULL,
			@v_vchLPN			 NVARCHAR(25) = NULL,
			@v_vchDescription	 NVARCHAR(200) = NULL,
			@v_vchLotNumber		 NVARCHAR(100) = NULL,
			@v_vchExpiryDate	 NVARCHAR(100) = NULL,
			@v_vchPickDetailID	 VARCHAR(40) = NULL

	BEGIN TRY
		----------------------------------------------
		-- Check Duplicate SN
		----------------------------------------------
		IF EXISTS(SELECT serial_number FROM t_wms_store_item_status WHERE serial_number = @in_vchSerialNumber AND count_id = @in_vchCountID)
			BEGIN
				--08/04/2016 : update new value
				UPDATE t_wms_store_item_status SET 
					 [user_def1] = @in_vchPatient
					,[user_def2] = @in_vchDoctorName
					,[use_date] = @in_dtUseDate
					,[user_def3] = @in_vchBudget
					,[memo] = @in_vchMemo
					,@in_vchUserID = @in_vchUserID
					,count_id = @in_vchCountID
				WHERE serial_number = @in_vchSerialNumber
				SET @out_vchResult = 'Success';
				RETURN;
			END

		SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE is_active = 'YES'

		-----------------------------------------------
		-- Validate serial in t_com_tran_log
		-----------------------------------------------
		/*
		SELECT @v_vchPickDetailID = pickDT.outbound_pick_detail_id 
			, @v_vchOrderNumber = obMS.outbound_order_number
			, @v_vchPalentLPN = pickDT.parent_lpn
			, @v_vchLPN = pickDT.lpn
			, @v_vchItemNumer = item.item_number
			, @v_vchDescription = item.description
			, @v_vchLotNumber = pickDT.lot_number
			, @v_vchExpiryDate = pickDT.expiry_date
		FROM t_wms_outbound_master obMS
		LEFT JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
		LEFT JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
		LEFT JOIN t_wms_wh_item whItem ON pickDt.wh_item_master_id = whItem.wh_item_master_id
		LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
		WHERE obMS.wh_master_id = @v_vchWhMasterID
		AND obMS.order_status in ('SHIP','CLOSE')
		AND	pickDT.serial_number = @in_vchSerialNumber
		*/

		SELECT @v_vchPickDetailID = inventory_id
			, @v_vchPalentLPN = parent_lpn
			, @v_vchLPN = lpn
			, @v_vchItemNumer = item_number
			, @v_vchDescription = description
			, @v_vchLotNumber = lot_number
			, @v_vchExpiryDate = expiry_date
		FROM v_wms_inventory_data_by_serial
		WHERE wh_master_id = @v_vchWhMasterID
		AND serial_number = @in_vchSerialNumber
		IF (ISNULL(@v_vchPickDetailID,'') = '')
			BEGIN
				SET @out_vchResult = 'Serial number does not exist.'
				RETURN;
			END

		-----------------------------------------------
		--Get Delivery Number and Delivery Date
		-----------------------------------------------
		SELECT @v_vchDeliveryNumber = delivery_number
			,@v_vchDeliveryDate = delivery_date
		FROM t_wms_outbound_delivery 
		WHERE serial_number = @in_vchSerialNumber

		-----------------------------------------------	
		--INSERT t_wms_store_item_status
		-----------------------------------------------
		INSERT INTO [dbo].[t_wms_store_item_status]
				   ([store_item_status_id]
				   ,[wh_master_id]
				   ,[count_id]
				   ,[outbound_order_number]
				   ,[item_number]
				   ,[item_description]
				   ,[location]
				   ,[parent_lpn]
				   ,[lpn]
				   ,[lot]
				   ,[expiry_date]
				   ,[serial_number]
				   ,[memo]
				   ,[inventory_status]
				   ,[user_def1]
				   ,[user_def2]
				   ,[user_def3]
				   ,[delivery_date]
				   ,[use_date]
				   ,[create_date]
				   ,[create_by])
			 VALUES
				   (NEWID(),
				   @v_vchWhMasterID,
				   @in_vchCountID,
				   @v_vchDeliveryNumber,
				   @v_vchItemNumer,
				   @v_vchDescription,
				   @in_vchLocation,
				   @v_vchPalentLPN,
				   @v_vchLPN,
				   @v_vchLotNumber,
				   @v_vchExpiryDate,
				   @in_vchSerialNumber,
				   @in_vchMemo,
				   @in_vchStatus,
				   @in_vchPatient,
				   @in_vchDoctorName,
				   @in_vchBudget,
				   @v_vchDeliveryDate,
				   @in_dtUseDate,
				   GETDATE(),
				   @in_vchUserID)

		EXEC usp_wms_change_status_by_serial 
				@in_vchApplicationID = 'IOS',
				@in_vchLocation		= @in_vchLocation,	
				@in_vchSerialNumber	= @in_vchSerialNumber,
				@in_vchDestinationStatus = 'USED',
				@in_vchDevice		= 'IOS',
				@in_vchUserID		= @in_vchUserID,
				@in_vchTranType		= 'INV_STATUS_CHANGE',
				@in_vchSubTranType	= 'EXTERNAL_CHANGE',
				@in_vchTranTypeDesc	= 'Change Status',
				@out_vchErrorCode	= NULL,
				@out_vchErrorMsg	= NULL;	
						
		SET @out_vchResult = 'Success';
	END TRY		
	BEGIN CATCH
		SET @out_vchResult = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_putaway_rule]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 ----------------------------------------------
-- Putaway rule TIPCO
-- วางตาม Item class
-- วาง location ที่มี จำนวนน้อย
----------------------------------------------
--Putaway LFAsia 
--Check จาก item location ถ้าไม่มี Check ปกติ

/* Putaway STD
1. check location item >> ถ้ากำหนดไว้ให้ใช้ Location นั้น >> หากมีการกำหนด location มากกว่า 1 location ต่อ item จะเช็คเรื่อง capacity อีกที

2. Suggest ตาม Zone Category โดยคำนวณ capacity คงเหลือ ถ้ายังสามารถวางได้จะวางที่ location เดิมก่อน โดยเงื่อนไขคือต้อง item เดียวกัน
3. Suggest ตาม Zone Category ที่ยังไม่ของวางเลย
4. Suggest Location ที่ยังไม่ของวางเลย ตาม Putaway Seq
5. ถ้าไม่มี location ไหนว่าง เอา location ที่มี หากคำนวณ capacity เอาที่เหลือวางได้มา
*/
----------------------------------------------
CREATE PROCEDURE [dbo].[usp_putaway_rule]
	@in_vchWhMasterID		  UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			  UNIQUEIDENTIFIER = NULL,
	@in_vchItemNumber		  NVARCHAR(50),
	@in_vchLocation			  NVARCHAR(50),
	@out_vchSuggestLocationID UNIQUEIDENTIFIER OUTPUT,
	@out_vchSuggestLocation	  NVARCHAR(50) OUTPUT
AS
BEGIN
	SET NOCOUNT ON;
 	DECLARE @v_vchWhItemMasterID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemMasterID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemCategoryID UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchInvStatusID	 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchZoneID		 UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemClass		 NVARCHAR(10) = NULL
	 
	/*	
	--Putaway 1. check location item >> ถ้ากำหนดไว้ให้ใช้ Location นั้น
	--Putaway 2. check zone category >> ถ้า control LPN แล้ว capacity_qty ครบแล้วให้หา location อื่น
	*/
	SELECT TOP 1 @v_vchItemMasterID = item.item_master_id
		, @v_vchItemCategoryID = cate.category_id
		, @v_vchItemClass = cate.item_category
	FROM t_wms_item item
	INNER JOIN t_wms_category cate on item.category_id = cate.category_id
	WHERE item.item_number = @in_vchItemNumber 
	AND item.owner_id = @in_vchOwnerID
	AND item.is_active = 'YES'
	SELECT TOP 1 @v_vchWhItemMasterID = wh_item_master_id FROM t_wms_wh_item WHERE wh_master_id = @in_vchWhMasterID AND item_master_id = @v_vchItemMasterID
	SELECT TOP 1 @v_vchZoneID = zone_id FROM t_wms_zone_category WHERE category_id = @v_vchItemCategoryID
 
	--Suggest ตาม Location Item
	SET @out_vchSuggestLocationID = NULL
	SET @out_vchSuggestLocation = NULL
	SELECT locItem.location_id
		,loc.location
		,loc.capacity_qty
		,loc.putaway_sequence
	INTO #tLocationItem
	FROM t_wms_location_item locItem
	INNER JOIN t_wms_location loc ON locItem.location_id = loc.location_id
	WHERE locItem.item_master_id = @v_vchItemMasterID
	AND loc.wh_master_id = @in_vchWhMasterID
	ANd loc.loc_type NOT IN ('FORK','STG','STORE','RSTG')
	AND locItem.is_active = 'YES'
	AND loc.location <> @in_vchLocation
	ORDER BY loc.putaway_sequence, loc.location
  

	IF EXISTS (SELECT 1 FROM #tLocationItem)
		BEGIN
			SELECT TOP 1 @out_vchSuggestLocationID = tData.location_id 
				,@out_vchSuggestLocation = tData.location
			FROM (SELECT inv.location_id
					, loc.location
					, loc.capacity_qty
					, loc.putaway_sequence
					, SUM(inv.quantity) AS inv_qty
					, (SELECT COUNT(DISTINCT inv.lpn) FROM t_wms_inventory AS inv WHERE inv.location_id = loc.location_id) AS count_lpn
				FROM #tLocationItem loc  
				LEFT JOIN t_wms_inventory inv ON loc.location_id = inv.location_id 
				GROUP BY loc.location,loc.location_id, inv.location_id,loc.capacity_qty,putaway_sequence
				) AS tData
			WHERE tData.inv_qty > 0 
			AND (tData.count_lpn + 1) <= ISNULL(capacity_qty,0)
			ORDER BY tData.putaway_sequence, tData.location
		END

	IF @out_vchSuggestLocationID IS NULL
		BEGIN
			
			--Suggest ตาม Zone Category โดยคำนวณ capacity คงเหลือ ถ้ายังสามารถวางได้จะวางที่ location เดิมก่อน โดยเงื่อนไขคือต้อง item เดียวกัน
			SELECT TOP 1 @out_vchSuggestLocationID = tData.location_id 
				,@out_vchSuggestLocation = tData.location
			FROM (SELECT inv.location_id
					, loc.location
					, loc.capacity_qty
					, loc.putaway_sequence
					, SUM(inv.quantity) AS inv_qty
					, (SELECT COUNT(DISTINCT inv.lpn) FROM t_wms_inventory AS inv WHERE inv.location_id = loc.location_id) AS count_lpn
				FROM t_wms_location loc 
				INNER JOIN t_wms_zone_location zLoc ON zLoc.location_id = loc.location_id 
				LEFT JOIN t_wms_inventory inv ON loc.location_id = inv.location_id
				WHERE loc.wh_master_id = @in_vchWhMasterID
				AND inv.owner_id = @in_vchOwnerID
				AND (inv.wh_item_master_id = @v_vchWHItemMasterID OR inv.wh_item_master_id IS NULL)
				AND loc.loc_type = 'PICK'
				AND loc.is_active = 'YES'
				AND (CASE WHEN @v_vchZoneID IS NULL THEN '' ELSE CONVERT(VARCHAR(36),zLoc.zone_id) END) = (CASE WHEN @v_vchZoneID IS NULL THEN '' ELSE CONVERT(VARCHAR(36),@v_vchZoneID) END)
				AND loc.location <> @in_vchLocation
				GROUP BY loc.location,loc.location_id, inv.location_id,loc.capacity_qty,putaway_sequence
				) AS tData
			WHERE tData.inv_qty > 0 
			AND (tData.count_lpn + 1) <= ISNULL(capacity_qty,0)
			ORDER BY tData.putaway_sequence, tData.location
		
			IF @out_vchSuggestLocationID IS NULL
				BEGIN
					--Suggest ตาม Zone Category ที่ยังไม่ของวางเลย
					SELECT TOP 1 @out_vchSuggestLocationID = loc.location_id
						, @out_vchSuggestLocation = loc.location
					FROM t_wms_zone_location zLoc
					INNER JOIN t_wms_location loc ON zLoc.location_id = loc.location_id
					WHERE loc.wh_master_id = @in_vchWhMasterID
					AND loc.loc_type = 'PICK'
					AND loc.is_active = 'YES'
					AND zLoc.zone_id = @v_vchZoneID 
					AND loc.location_id NOT IN (SELECT location_id FROM t_wms_inventory)
					ORDER BY putaway_sequence, location 

					IF @out_vchSuggestLocationID IS NULL
						BEGIN 
							--Suggest Location ที่ยังไม่ของวางเลย ตาม Putaway Seq
							SELECT TOP 1 @out_vchSuggestLocationID = loc.location_id
								, @out_vchSuggestLocation = loc.location
							FROM t_wms_location loc
							WHERE loc.wh_master_id = @in_vchWhMasterID
							AND loc.loc_type = 'PICK'
							AND loc.is_active = 'YES'
							AND loc.location_id NOT IN (SELECT location_id FROM t_wms_inventory) 
							ORDER BY putaway_sequence, location

							--ถ้าไม่มี location ไหนว่าง เอา location ที่มี หากคำนวณ capacity เอาที่เหลือวางได้มา
							IF @out_vchSuggestLocationID IS NULL
								BEGIN
									SELECT TOP 1 @out_vchSuggestLocationID = tData.location_id 
										,@out_vchSuggestLocation = tData.location
									FROM (SELECT inv.location_id
											, loc.location
											, loc.capacity_qty
											, loc.putaway_sequence
											, SUM(inv.quantity) AS inv_qty
											, (SELECT COUNT(DISTINCT inv.lpn) FROM t_wms_inventory AS inv WHERE inv.location_id = loc.location_id) AS count_lpn
										FROM t_wms_location loc 
										INNER JOIN t_wms_zone_location zLoc ON zLoc.location_id = loc.location_id 
										LEFT JOIN t_wms_inventory inv ON loc.location_id = inv.location_id
										WHERE loc.wh_master_id = @in_vchWhMasterID
										AND inv.owner_id = @in_vchOwnerID
										AND loc.loc_type = 'PICK'
										AND loc.is_active = 'YES'
										AND loc.location <> @in_vchLocation
										AND (CASE WHEN @v_vchZoneID IS NULL THEN '' ELSE CONVERT(VARCHAR(36),zLoc.zone_id) END) = (CASE WHEN @v_vchZoneID IS NULL THEN '' ELSE CONVERT(VARCHAR(36),@v_vchZoneID) END)
										GROUP BY loc.location,loc.location_id, inv.location_id,loc.capacity_qty,putaway_sequence
										) AS tData
									WHERE tData.inv_qty > 0 
									AND (tData.count_lpn + 1) <= (CASE WHEN ISNULL(capacity_qty,0) = 0 THEN (tData.count_lpn + 2) ELSE ISNULL(capacity_qty,0) END)
									ORDER BY tData.putaway_sequence, tData.location
								END 
						END 
				END
		END 

 END
GO
/****** Object:  StoredProcedure [dbo].[usp_report_cate_inbound_order_received_detail]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_report_cate_inbound_order_received_detail]
	-- Add the parameters for the stored procedure here
	@wh_master_id varchar(40)
	, @inbound_order_master_id varchar(40)	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	WITH CategoryTable (category_id, quantity_received)  
	AS  
	(  
		select R1.category_id
		 , sum(R1.quantity_received) as quantity_received
		from (
		select 0 as quantity_received, category_id 
		from t_wms_category
		where is_active = 'YES'

		UNION

		 select 
		  sum(v.quantity_received) as quantity_received
		  , i.category_id
		 from v_wms_inbound_order_receive_detail_report v
		 left join t_wms_item i on v.item_number = i.item_number
		 where convert(varchar(36),v.wh_master_id) = @wh_master_id 
		 AND convert(varchar(36),v.inbound_order_master_id) = @inbound_order_master_id
		 group by 
		  i.category_id
		 )R1
		 group by R1.category_id 
	)
	-- select output
	SELECT [22E7028A-B86F-4BCE-85C7-CFB1518BE669]
		, [85E79126-5BEE-47C1-AF30-5B3E15D4ABE5]
		, [86759915-21D7-4900-B7FA-2E0A553E638E]
		, [94AC20AC-A75C-4BA8-8C61-6D36A05C2D9E]
		, [9A8152B3-984E-4D7C-97FC-60D5ADA6CB25]
		, [9EE56096-A322-4F21-8497-A18742313556]
		, [D899FFAC-93F2-43D8-834F-8C910AD7012E]
		, (SELECT SUM(quantity_received) FROM CategoryTable) AS sum_quantity_received
	FROM
	(
	SELECT category_id, quantity_received FROM CategoryTable  
	) AS SourceTable
	PIVOT
	(
	MAX(quantity_received)
	FOR category_id IN (
		[22E7028A-B86F-4BCE-85C7-CFB1518BE669]
		, [85E79126-5BEE-47C1-AF30-5B3E15D4ABE5]
		, [86759915-21D7-4900-B7FA-2E0A553E638E]
		, [94AC20AC-A75C-4BA8-8C61-6D36A05C2D9E]
		, [9A8152B3-984E-4D7C-97FC-60D5ADA6CB25]
		, [9EE56096-A322-4F21-8497-A18742313556]
		, [D899FFAC-93F2-43D8-834F-8C910AD7012E])
	) AS PivotTable;

END
