/****** Object:  StoredProcedure [dbo].[usp_script_generate_location_coordinate]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Kritsada Baothong
-- Create date: 2014-01-08
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_script_generate_location_coordinate]
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @location_id NVARCHAR(40)
	DECLARE @location NVARCHAR(50)
	DECLARE @ROW INT = 1
	DECLARE @COLUMN INT = 0
	DECLARE @ROW_MAX INT = 0
	DECLARE @COLUMN_MAX INT = 0

	SELECT TOP(1) @ROW_MAX = [x_max], @COLUMN_MAX = [y_max] FROM [dbo].[t_com_location_size]	

    DECLARE CS_LOCATION CURSOR FOR
            SELECT location_id,location FROM [dbo].[t_wms_location]
			ORDER BY location ASC
    OPEN CS_LOCATION          
    FETCH NEXT FROM CS_LOCATION
            INTO @location_id,@location
    WHILE @@FETCH_STATUS = 0
    BEGIN    
            -- BEGIN FOR LIST INSTRUCTION SET  
			IF @COLUMN = 50
			BEGIN
				SET @ROW = @ROW + 1
			END		          
			IF @COLUMN < @ROW_MAX
			BEGIN
				SET @COLUMN = @COLUMN + 1
			END
			ELSE
			BEGIN
				SET @COLUMN = 1
			END
			
			--PRINT @COLUMN
			PRINT @location +' '+ CONVERT(NVARCHAR(10),@ROW) +' '+CONVERT(NVARCHAR(10),@COLUMN)		

			UPDATE [dbo].[t_wms_location]
			   SET [x_cordinate] = CONVERT(NVARCHAR(10),@ROW)
				  ,[y_cordinate] = CONVERT(NVARCHAR(10),@COLUMN)	
				  ,[location_level] = '1'
			 WHERE [location_id] = @location_id   
 
            -- END FOR LIST INSTRUCTION SET            
     FETCH NEXT FROM CS_LOCATION
            INTO @location_id,@location
     END
     CLOSE CS_LOCATION    
     DEALLOCATE CS_LOCATION

END


GO
/****** Object:  StoredProcedure [dbo].[usp_send_mail_error_interface]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_send_mail_error_interface]
	@in_vchSubject	 VARCHAR(255),
	@in_vchMessage	 VARCHAR(3000),
	@in_vchEmailType VARCHAR(50) = ''
AS
BEGIN
	DECLARE @body			VARCHAR(MAX),
			@v_vchEmail		NVARCHAR(200),
			@v_vchSubject	NVARCHAR(200)

	SELECT TOP 1 @v_vchSubject = subject, @v_vchEmail = email_to FROM t_wms_email WHERE type = 'Interface'
	SET @body = '<B>' + @in_vchSubject +'</B><BR><B>Error: </B>' + @in_vchMessage 

	IF @in_vchEmailType = 'SP_ERROR'
		BEGIN
			--23/06/2016 : ถ้าของไม่พอให้เป็น Anonymous
			EXEC msdb.dbo.sp_send_dbmail @profile_name = 'Anonymous'
				, @recipients = @v_vchEmail
				, @subject = @v_vchSubject
				, @body = @body
				, @body_format = 'HTML'
		END
	ELSE 
		BEGIN
			--23/06/2016 : ถ้า error file wm3 interface error
			EXEC msdb.dbo.sp_send_dbmail @profile_name = 'WM3InterfaceError'
				, @recipients = @v_vchEmail
				, @subject = @v_vchSubject
				, @body = @body
				, @body_format = 'HTML'
			
		END
END
GO
