CREATE PROCEDURE [dbo].[usp_start_job_rfid]
AS
BEGIN
	DECLARE @Working_type VARCHAR(20)

	SELECT TOP(1) @Working_type = working_type FROM t_wms_rfid_config
	
	IF(@Working_type='Inbound')
		EXEC usp_validate_update_inbound_receipt_rfid @in_vchReceiveLocation = 'INBOUND'
	ELSE IF(@Working_type='Outbound')	
		EXEC usp_validate_update_outbound_checker_rfid
END

