/****** Object:  StoredProcedure [dbo].[usp_string_query_paging]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_string_query_paging]
(
	@in_startRowIndex	int = NULL,
	@in_maximumRows		int = NULL,
	@in_vchWithQuery	NVARCHAR(MAX) = '',
	@in_vchQuery		NVARCHAR(MAX) = '',
	@in_vchSort			NVARCHAR(2000) = '',
	@in_switchType		NVARCHAR(10) = '',
	@out_rowCount		INT = 0 OUTPUT
)
AS
BEGIN
	DECLARE @DynamicSQL				NVARCHAR(MAX) = '',
			@ParameterDefinition	NVARCHAR(30)= ''

	IF(@in_switchType = '_view')
		BEGIN
			--Execute for count all row
			SET @ParameterDefinition = ' @out_rowCount INT OUTPUT '
			SET @DynamicSQL =  ISNULL(@in_vchWithQuery,'') + ' SELECT @out_rowCount = COUNT(*) FROM ' + @in_vchQuery
			EXEC sp_executesql @DynamicSQL, @ParameterDefinition, @out_rowCount OUTPUT

			IF (ISNULL(@in_vchSort,'') <> '')
			BEGIN
				SET @in_vchSort = ' ORDER BY ' + @in_vchSort;
			END

			--Execute for select data
			SET @DynamicSQL = ISNULL(@in_vchWithQuery,'') + ' SELECT 0 AS RowNum, * FROM '+ @in_vchQuery + @in_vchSort
							 +' OFFSET '+CONVERT(VARCHAR(15),@in_startRowIndex)+' ROWS FETCH NEXT '+ CONVERT(VARCHAR(15),@in_maximumRows)+' ROWS ONLY'

			--PRINT @DynamicSQL
			-- Execute for query view
			EXEC sp_executesql @DynamicSQL
		END
	ELSE IF(@in_switchType = '_export')
		BEGIN

			SET @DynamicSQL = ISNULL(@in_vchWithQuery,'') + ' SELECT * FROM '+ @in_vchQuery

			--print @DynamicSQL
			-- Execute for query export
			EXEC sp_executesql @DynamicSQL
		END
		ELSE IF(@in_switchType = '_schema')
		BEGIN

			SET @DynamicSQL = ISNULL(@in_vchWithQuery,'') + ' SELECT TOP(0) * FROM '+ @in_vchQuery

			--print @DynamicSQL
			-- Execute for query export
			EXEC sp_executesql @DynamicSQL
		END
END

GO
/****** Object:  StoredProcedure [dbo].[usp_transaction_log_master]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_transaction_log_master]
(
	@in_vchApplicationID	VARCHAR(40),
	@in_vchTranType			NVARCHAR(20),
	@in_vchSubTranType		NVARCHAR(20),
	@in_vchUdf1				NVARCHAR(100),
	@in_vchUdf2				NVARCHAR(100),
	@in_vchUdf3				NVARCHAR(100),
	@in_vchUdf4				NVARCHAR(100),
	@in_vchUserID			NVARCHAR(25)
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchStartTime			DATETIME,
			@v_vchLogDescription	NVARCHAR(100),
			@v_vchApplicationName	NVARCHAR(100)

	SET @v_vchStartTime = GETDATE()
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT
	SELECT @v_vchLogDescription = description FROM t_com_transaction WHERE tran_type = @in_vchTranType AND sub_tran_type = @in_vchSubTranType AND is_active = 'YES'
	
	IF (@in_vchUdf1 = '')
		SET @in_vchUdf1 = NULL
	IF (@in_vchUdf2 = '')
		SET @in_vchUdf2 = NULL
	IF (@in_vchUdf3 = '')
		SET @in_vchUdf3 = NULL
	IF (@in_vchUdf4 = '')
		SET @in_vchUdf4 = NULL

	INSERT INTO [dbo].[t_com_tran_log]
           ([tran_id]
           ,[app_id]
           ,[tran_type]
           ,[sub_tran_type]
           ,[app_name]
           ,[description]
           ,[start_tran_datetime]
           ,[end_tran_datetime]
           ,[quantity]
           ,[user_id]
           ,[udf_1]
           ,[udf_2]
		   ,[udf_3]
		   ,[udf_4]
           ,[device]
           ,[create_date]
           ,[create_by])
     VALUES ( NEWID()
			 ,@in_vchApplicationID
			 ,@in_vchTranType
			 ,@in_vchSubTranType
			 ,@v_vchApplicationName
			 ,@v_vchLogDescription
			 ,@v_vchStartTime
			 ,GETDATE()
			 ,0
			 ,@in_vchUserID
			 ,@in_vchUdf1	
			 ,@in_vchUdf2	
			 ,@in_vchUdf3	
			 ,@in_vchUdf4
			 ,NULL
			 ,GETDATE()
			 ,@in_vchUserID
		   )
END
GO
/****** Object:  StoredProcedure [dbo].[usp_update_pallet_return]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_update_pallet_return]
(
	@in_vchApplicationID	VARCHAR(40) = NULL,
	@in_vchWhMasterID		VARCHAR(40) = NULL,
	@in_vchOrderNumber		VARCHAR(50) = NULL,
	@in_vchOwner			VARCHAR(40) = NULL,
	@in_vchCarrierCode		NVARCHAR(40) = NULL,
	@in_vchItemNumber		VARCHAR(50) = NULL,
	@in_fltQtyEnter			FLOAT,
	@in_LicensePlate		NVARCHAR(50) = NULL, --ทะเบียนรถ
	@in_dtReturnDate		DATETIME = NULL,
	@in_vchLocalID			VARCHAR(40) = null,
	@in_vchUserID			NVARCHAR(25) = NULL,
	@out_vchErrorCode		VARCHAR(50) OUTPUT,
	@out_vchErrorMsg		NVARCHAR(500) OUTPUT,
	@out_vchNextScreen		NVARCHAR(50) OUTPUT
)
AS
BEGIN
		DECLARE @v_vchPalletReturnID	VARCHAR(40) = NULL,
				@v_vchCarrierID			VARCHAR(40) = NULL,	
				@v_vchWhItemMasterID	VARCHAR(40) = NULL,
				@v_vchOwnerID			VARCHAR(40) = NULL

		SELECT @v_vchCarrierID = carrier_id FROM t_wms_carrier WHERE carrier_code = @in_vchCarrierCode AND is_active = 'YES'
		SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
	

		SELECT DISTINCT @v_vchWhItemMasterID = whItem.wh_item_master_id
		FROM t_wms_wh_item whItem
		LEFT JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
		LEFT JOIN t_wms_item_crossref cref on item.item_master_id = cref.item_master_id
		WHERE wh_master_id = @in_vchWhMasterID
		AND (item.item_number = @in_vchItemNumber OR item.dg_code = @in_vchItemNumber OR cref.alternate_item_number = @in_vchItemNumber)
		AND item.owner_id = @v_vchOwnerID
	

		-----------------------------------------------------------
		-- ตรวจสอบว่ามี Record Pallet return ก่อนหน้าหรือไม่
		-----------------------------------------------------------
		SELECT @v_vchPalletReturnID = plt.pallet_return_id
		FROM t_mod_cbd_pallet plt
		WHERE plt.wh_master_id = @in_vchWhMasterID
		AND plt.outbound_order_number = @in_vchOrderNumber
		AND plt.owner_id = @v_vchOwnerID	
		AND wh_item_master_id = @v_vchWhItemMasterID

	BEGIN TRY
		IF @v_vchPalletReturnID IS NULL
			BEGIN
				--Insert
				SET @v_vchPalletReturnID = NEWID()
				
				INSERT INTO t_mod_cbd_pallet 
					(
						pallet_return_id
						, wh_master_id
						, owner_id
						, outbound_order_number
						, order_status
						, wh_item_master_id
						, quantity_return
						, license_plate
						, return_date
						, create_by
						, create_date
					)
				VALUES
					(
						 @v_vchPalletReturnID
						, @in_vchWhMasterID
						, @v_vchOwnerID
						, @in_vchOrderNumber
						, 'OPEN'
						, @v_vchWhItemMasterID
						, @in_fltQtyEnter
						, @in_LicensePlate
						, @in_dtReturnDate
						, @in_vchUserID
						, GETDATE()
					)
			END	
		ELSE
			BEGIN
				--Update
				UPDATE t_mod_cbd_pallet SET 
				  	 quantity_return = @in_fltQtyEnter
					,license_plate = @in_LicensePlate
					,return_date = @in_dtReturnDate
					,update_by = @in_vchUserID
					,update_date = GETDATE()
				WHERE pallet_return_id = @v_vchPalletReturnID
			END

		--SET MSG Save Success
		SET @out_vchErrorCode = '0';
		SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')

	END TRY
		BEGIN CATCH
			IF (ISNULL(@out_vchErrorCode,'') = '' or ISNULL(@out_vchErrorCode,'') = '0')
				BEGIN
					SET @out_vchErrorCode = ERROR_NUMBER();
					SET @out_vchErrorMsg = ERROR_MESSAGE();
				END
		END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[usp_UpdatePrice]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_UpdatePrice]
	-- Add the parameters for the stored procedure here
	@v_vchOrder						Varchar(40)
AS
BEGIN
	
	DECLARE 
	 @v_vchItemNumber				VARCHAR(40),	 
	 @v_vchItemMasterPrice			INT,
	 @v_vchDeliveryPrice			INT
	
	DECLARE ItemPrice_Cursor CURSOR FOR
			SELECT Item.item_number,Item.price FROM t_wms_item AS Item
			JOIN t_wms_outbound_delivery_report AS Delivery
			ON Item.item_number = Delivery.item_number
			WHERE Delivery.outbound_order_number = @v_vchOrder AND Item.price <> Delivery.price 
	
	OPEN ItemPrice_Cursor
	
	FETCH NEXT FROM ItemPrice_Cursor INTO @v_vchItemNumber, @v_vchItemMasterPrice
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		
		SELECT @v_vchDeliveryPrice = price FROM t_wms_outbound_delivery_report
		WHERE item_number = @v_vchItemNumber and outbound_order_number = @v_vchOrder
		
		IF(@v_vchItemMasterPrice != @v_vchDeliveryPrice)
		UPDATE t_wms_outbound_delivery_report
		SET price = @v_vchItemMasterPrice
		WHERE item_number = @v_vchItemNumber

		FETCH NEXT FROM ItemPrice_Cursor INTO @v_vchItemNumber, @v_vchItemMasterPrice
		
	END	  
	       
	CLOSE ItemPrice_Cursor                  	
	DEALLOCATE ItemPrice_Cursor
	
END


GO
/****** Object:  StoredProcedure [dbo].[usp_UpdatePriceOutboundDetail]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_UpdatePriceOutboundDetail]

	@v_vchOrder						Varchar(40)
	
AS
BEGIN
	
	DECLARE 
		 @v_vchOutboundMasterID			VARCHAR(100),
		 @v_vchItemNumber				VARCHAR(40),
		 @v_vchItemMasterPrice			INT,
		 @v_vchDeliveryPrice			INT
		 
	SELECT @v_vchOutboundMasterID = outbound_order_master_id FROM t_wms_outbound_master WHERE outbound_order_number = @v_vchOrder
		
	DECLARE ItemPrice_Cursor CURSOR FOR
			SELECT			v_wms_item_by_wh.wh_item_master_id, t_wms_item.price
			FROM			t_wms_item INNER JOIN
							v_wms_item_by_wh ON t_wms_item.item_master_id = v_wms_item_by_wh.item_master_id INNER JOIN
							t_wms_outbound_detail ON v_wms_item_by_wh.wh_item_master_id = t_wms_outbound_detail.wh_item_master_id INNER JOIN
							t_wms_outbound_master ON t_wms_outbound_detail.outbound_order_master_id = t_wms_outbound_master.outbound_order_master_id
			WHERE			t_wms_outbound_master.outbound_order_number = @v_vchOrder
			ORDER BY		t_wms_outbound_master.outbound_order_number, t_wms_item.item_number
	
	OPEN ItemPrice_Cursor
	
	FETCH NEXT FROM ItemPrice_Cursor INTO @v_vchItemNumber, @v_vchItemMasterPrice
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		
		SELECT @v_vchDeliveryPrice = price FROM t_wms_outbound_detail
		WHERE wh_item_master_id = @v_vchItemNumber and outbound_order_master_id = @v_vchOutboundMasterID
		
		IF(@v_vchItemMasterPrice != @v_vchDeliveryPrice)
		UPDATE t_wms_outbound_detail
		SET price = @v_vchItemMasterPrice
		WHERE outbound_order_master_id = @v_vchOutboundMasterID AND wh_item_master_id = @v_vchItemNumber

		FETCH NEXT FROM ItemPrice_Cursor INTO @v_vchItemNumber, @v_vchItemMasterPrice
		
	END	  
	       
	CLOSE ItemPrice_Cursor                 
	 	
	DEALLOCATE ItemPrice_Cursor
	
END


