/****** Object:  StoredProcedure [dbo].[usp_validate_duplicate_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_validate_duplicate_lpn]
(
	@in_vchOrderNumber		VARCHAR(50)	  = NULL,
	@in_vchLpn				NVARCHAR(50)  = NULL,
	@in_vchCheckDupItem		VARCHAR(3)	  = NULL,
	@in_vchCheckDupOrder	VARCHAR(3)	  = NULL,
	@out_vchErrorCode		VARCHAR(50)	  OUTPUT
)
AS
BEGIN
	
	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Item Number ใน Master
	--------------------------------------------------------------------
	IF (@in_vchCheckDupItem = 'YES')
		BEGIN
			IF EXISTS (SELECT item_number FROM t_wms_item WHERE item_number = @in_vchLpn)
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE-ITEM-NUMBER'
					RETURN;
				END
		END

	--------------------------------------------------------------------
	-- ตรวจสอบ LPN ที่สแกนต้องไม่ตรงกับ Order Number
	--------------------------------------------------------------------
	IF (@in_vchCheckDupOrder = 'YES')
		BEGIN 
			IF @in_vchLpn = @in_vchOrderNumber
				BEGIN
					SET @out_vchErrorCode = 'INFO-LPN-DUPLICATE-ORDER-NUMBER'
					RETURN;
				END
		END
END


GO
/****** Object:  StoredProcedure [dbo].[usp_validate_duplicate_tag_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_validate_duplicate_tag_rfid]
(
	@in_vchTagRFID		VARCHAR(50)	  = NULL,
	@in_vchReaderType	VARCHAR(50)	  = NULL,
	@in_vchDevice		VARCHAR(50)	  = NULL
)
AS
BEGIN
	
	--------------------------------------------------------------------
	-- ตรวจสอบ Tag RFID 
	--------------------------------------------------------------------
		IF NOT EXISTS (SELECT tag_id FROM t_tmp_rfid_reader where tag_id = @in_vchTagRFID and working_type = @in_vchReaderType)
			BEGIN
				INSERT INTO t_tmp_rfid_reader(tag_id,working_type,create_date,is_updated,device) VALUES(@in_vchTagRFID,@in_vchReaderType,GETDATE(),'NO',@in_vchDevice)
				RETURN;
			END	
		ELSE
			BEGIN
				IF (@in_vchReaderType = 'INBOUND')
					BEGIN
						IF EXISTS (select serial_number from t_wms_inbound_rfid where serial_number = @in_vchTagRFID AND processing_status = 'ERROR')
							BEGIN
								UPDATE t_wms_inbound_rfid SET processing_status = 'PENDING' WHERE serial_number = @in_vchTagRFID;
							END
					END
				ELSE IF (@in_vchReaderType = 'OUTBOUND')
					BEGIN
						IF EXISTS (select serial_number from t_wms_outbound_checker_rfid where serial_number = @in_vchTagRFID AND processing_status = 'ERROR')
							BEGIN
								UPDATE t_wms_outbound_checker_rfid SET processing_status = 'PENDING' WHERE serial_number = @in_vchTagRFID;
							END
					END

				UPDATE t_tmp_rfid_reader SET is_updated = 'NO', create_date = GETDATE(),device = @in_vchDevice WHERE tag_id = @in_vchTagRFID AND working_type = @in_vchReaderType
				
			END	
END



