CREATE PROCEDURE [dbo].[usp_validate_item_control]
(	
	@in_vchLotControl			NVARCHAR(10) = NULL,
	@in_vchExpiryDateControl	NVARCHAR(10) = NULL,
	@in_vchAttribute1Control	NVARCHAR(10) = NULL,
	@in_vchAttribute2Control	NVARCHAR(10) = NULL,
	@in_vchAttribute3Control	NVARCHAR(10) = NULL,
	@in_vchAttribute4Control	NVARCHAR(10) = NULL,
	@in_vchAttribute5Control	NVARCHAR(10) = NULL,
	@in_vchSNControl			NVARCHAR(10) = NULL,

	@in_vchIsCheckLot			NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckExpiryDate	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute1	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute2	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute3	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute4	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckAttribute5	NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่
	@in_vchIsCheckSN			NVARCHAR(3) = 'NO',	--สำหรับบอกว่าเป็นการ Check ลำดับไหนอยู่	
	@in_vchItemMode				NVARCHAR(25) = NULL, --BY EACH, BY QTY >> ถ้ามาจาก BY EACH ให้ Final Screen ได้เลย
	@out_vchNextScreen			NVARCHAR(50) OUTPUT
)
AS
BEGIN
	IF (@in_vchLotControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'LOT_NUMBER'		
			IF @in_vchIsCheckLot = 'YES'
				RETURN;
		END
	
	IF (@in_vchExpiryDateControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'EXPIRY_DATE'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute1Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE1'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute2Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE2'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute3Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE3'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute3 = 'YES'
				RETURN;	
		END

	IF (@in_vchAttribute4Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE4'	
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute4 = 'YES'
				RETURN;
		END

	IF (@in_vchAttribute5Control = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'ATTRIBUTE5'
			IF @in_vchIsCheckLot = 'YES'
				RETURN; 
			IF @in_vchIsCheckExpiryDate = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute1 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute2 = 'YES'
				RETURN;
			IF @in_vchIsCheckAttribute5 = 'YES'
				RETURN;	
		END

	IF (@in_vchSNControl = 'FULL')
		BEGIN
			SET @out_vchNextScreen = 'SERIAL_NUMBER'	
		END
	ELSE
		BEGIN
			IF (@in_vchItemMode = 'BY EACH')
				SET @out_vchNextScreen = 'FINAL_SCREEN'
			ELSE
				SET @out_vchNextScreen = 'UOM_QTY'
		END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_validate_update_inbound_receipt_rfid]    Script Date: 08/08/2025 11:11:30 ******/
