CREATE PROCEDURE [dbo].[usp_validate_update_inbound_receipt_rfid]
(
	@in_vchReceiveLocation varchar(50) = NULL
)
AS
BEGIN
	DECLARE @WhMasterID	VARCHAR(40),@InboundMasterID VARCHAR(40),@OwnerID VARCHAR(40),@Device VARCHAR(50),@ReceiptBy VARCHAR(25)
	DECLARE @MyCursor CURSOR
	SET @MyCursor = CURSOR FAST_FORWARD
	FOR
	SELECT	wh_master_id,inbound_order_master_id,owner_id,device,receipt_by
	FROM	t_wms_inbound_rfid
	WHERE	processing_status = 'READ'

	OPEN @MyCursor

		FETCH NEXT FROM @MyCursor
		INTO @WhMasterID,@InboundMasterID,@OwnerID,@Device,@ReceiptBy
		WHILE @@FETCH_STATUS = 0
			BEGIN
				EXEC usp_wms_inbound_receipt_rfid @in_vchApplicationID	= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0',
									@in_vchWhMasterID			= @WhMasterID,
									@in_vchInboundMasterID		= @InboundMasterID,
									@in_vchOwnerID				= @OwnerID,
									@in_vchReceiveLocation		= @in_vchReceiveLocation,
									@in_vchUserID				= @ReceiptBy,
									@in_vchDeviceID				= @Device
				FETCH NEXT FROM @MyCursor
					INTO @WhMasterID,@InboundMasterID,@OwnerID,@Device,@ReceiptBy
			END
	CLOSE @MyCursor
	DEALLOCATE @MyCursor
END



