/****** Object:  StoredProcedure [dbo].[usp_validate_update_status_tag_inbound_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_validate_update_status_tag_inbound_rfid]
(
	@out_vchAlert NVARCHAR(10) = NULL OUTPUT
)
AS
BEGIN
	DECLARE @TagID varchar(50),@ReaderType varchar(50),@Device varchar(50)
	DECLARE @MyCursor CURSOR
	SET @MyCursor = CURSOR FAST_FORWARD
	FOR
	SELECT	tag_id,working_type,device
	FROM	t_tmp_rfid_reader
	WHERE	is_updated = 'NO' AND working_type = 'INBOUND' AND SUBSTRING(tag_id,1,3) ='000'

	OPEN @MyCursor

		FETCH NEXT FROM @MyCursor
		INTO @TagID,@ReaderType,@Device
		WHILE @@FETCH_STATUS = 0
			BEGIN
			IF EXISTS (select serial_number from t_wms_inbound_rfid where serial_number = @TagID)
				BEGIN
					UPDATE t_wms_inbound_rfid SET processing_status = 'READ',device = @Device,receipt_by = 'RFID' WHERE serial_number = @TagID AND NOT(processing_status = 'COMPLETE');

					UPDATE t_tmp_rfid_reader SET is_updated = 'YES' WHERE tag_id = @TagID AND working_type = 'INBOUND'
				END
			ELSE
				SET @out_vchAlert = 'YES';

				FETCH NEXT FROM @MyCursor
					INTO @TagID,@ReaderType,@Device
			END
	CLOSE @MyCursor
	DEALLOCATE @MyCursor
END


GO
