/****** Object:  StoredProcedure [dbo].[usp_validate_update_status_tag_return_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_validate_update_status_tag_return_rfid]
(
	@out_vchAlert NVARCHAR(10) = NULL OUTPUT
)
AS
BEGIN
	DECLARE @TagID					varchar(50),
			@ReaderType				varchar(50),
			@Device					varchar(50),
			--@v_vchApplicationID		VARCHAR(40),
			--@v_vchLocalID			VARCHAR(40),
			@v_vchWhMasterID		VARCHAR(40),
			@v_vchDestLocation		NVARCHAR(50),
			@v_vchErrorCode			VARCHAR(50),	
			@v_vchErrorMsg		NVARCHAR(500),
			@v_vchNextScreen		NVARCHAR(50)


	DECLARE @MyCursor CURSOR
	SET @MyCursor = CURSOR FAST_FORWARD
	FOR
	SELECT	tag_id,working_type,device
	FROM	t_tmp_rfid_reader
	WHERE	is_updated = 'NO' AND working_type = 'RETURN' AND SUBSTRING(tag_id,1,3) ='000'
	--AND tag_id = '000000054688'

	Select TOP(1) @v_vchWhMasterID = wh_master_id FROM t_wms_wh

	SELECT TOP(1) @v_vchDestLocation =	location FROM t_wms_rfid_config

	OPEN @MyCursor

		FETCH NEXT FROM @MyCursor
		INTO @TagID,@ReaderType,@Device
		WHILE @@FETCH_STATUS = 0
			BEGIN
				EXEC usp_move_serial_return
				@in_vchApplicationID	= 'CC3D76CA-71B9-47CB-A933-4B1F1F489AF0',
				@in_vchLocalID			= '1033',
				@in_vchDeviceID			= @Device,
				@in_vchUserID			= 'RFID',
				@in_vchWhMasterID		= @v_vchWhMasterID,
				@in_vchSerialNumber		= @TagID,
				@in_vchDestLocation		= @v_vchDestLocation,
				@out_vchErrorCode		= @v_vchErrorCode	 OUTPUT,
				@out_vchErrorMsg		= @v_vchErrorMsg	OUTPUT,
				@out_vchNextScreen		= @v_vchNextScreen	OUTPUT

				IF(@v_vchErrorCode = '0')
					UPDATE t_tmp_rfid_reader SET is_updated = 'YES' WHERE tag_id = @TagID AND working_type = 'RETURN'
				ELSE
					SET @out_vchAlert = 'YES';
					
				
				FETCH NEXT FROM @MyCursor
					INTO @TagID,@ReaderType,@Device
			END
	CLOSE @MyCursor
	DEALLOCATE @MyCursor
END
GO
