CREATE PROCEDURE [dbo].[usp_view_outbound_viewer_slip]	
@invch_outbound_order_number	nvarchar(100)
, @invch_wh_id						nvarchar(100) = NULL
, @invch_owner_code					nvarchar(100) = NULL
AS
BEGIN
	IF @invch_wh_id = '' SET @invch_wh_id = NULL
	IF @invch_owner_code = '' SET @invch_owner_code = NULL

	declare @outbound_order_master_id	varchar(36)
	declare @ship_to_name				nvarchar(100)
	declare @ship_to_addr_line_1		nvarchar(100)
	declare @ship_to_contact			nvarchar(100)
	declare @order_type					nvarchar(50)
	declare @order_status				nvarchar(50)
	declare @order_date					datetime
	declare @ship_date_plan				datetime
	declare @ship_date_actual			datetime
	declare @ship_to_phone				nvarchar(100)
	declare @owner_code					nvarchar(50)
	declare @wh_id						nvarchar(50)
	declare @outbound_order_number		nvarchar(50)
	declare @quantity_ship				float
	declare @model						nvarchar(100)
	declare @item_master_id				varchar(36)
	declare @item_number				nvarchar(50)
	declare @phone						nvarchar(100)
	declare @customer_code				varchar(100)
	declare @customer_name				nvarchar(200)
	declare @description				nvarchar(200)
	declare @addr_line_1				nvarchar(300)
	declare @addr_line_2				nvarchar(300)
	declare @addr_line_3				nvarchar(300)

	create table #tempData
	(
		outbound_order_master_id	varchar(36)
	  , ship_to_name				nvarchar(100)
	  , ship_to_addr_line_1			nvarchar(100)
	  , ship_to_contact				nvarchar(100)
	  , order_type					nvarchar(50)
	  , order_status				nvarchar(50)
	  , order_date					datetime
	  , ship_date_plan				datetime
	  , ship_date_actual			datetime
	  , ship_to_phone				nvarchar(100)
	  , owner_code					nvarchar(50)
	  , wh_id						nvarchar(50)
	  , outbound_order_number		nvarchar(50)
	  , quantity_ship				float
	  , quantity_count				float
	  , model						nvarchar(100)
	  , item_master_id				varchar(36)
	  , item_number					nvarchar(50)
	  , phone						nvarchar(100)
	  , customer_code				varchar(100)
	  , customer_name				nvarchar(200)
	  , description					nvarchar(200)
	  , addr_line_1					nvarchar(300)
	  , addr_line_2					nvarchar(300)
	  , addr_line_3					nvarchar(300)
	)

	declare Iterator CURSOR FORWARD_ONLY FOR
		SELECT dbo.t_wms_outbound_master.outbound_order_master_id
			 , dbo.t_wms_outbound_master.ship_to_name
			 , dbo.t_wms_outbound_master.ship_to_addr_line_1
			 , dbo.t_wms_outbound_master.ship_to_contact
			 , dbo.t_wms_outbound_master.order_type
			 , dbo.t_wms_outbound_master.order_status
			 , dbo.t_wms_outbound_master.order_date
			 , dbo.t_wms_outbound_master.ship_date_plan
			 , dbo.t_wms_outbound_master.ship_date_actual
			 , dbo.t_wms_outbound_master.ship_to_phone
			 , dbo.t_wms_outbound_master.owner_code
			 , dbo.t_wms_outbound_master.wh_id
			 , dbo.t_wms_outbound_master.outbound_order_number
			 , dbo.t_wms_outbound_detail.quantity_ship
			 , dbo.t_wms_item.model
			 , dbo.t_wms_item.item_master_id
			 , dbo.t_wms_item.item_number
			 , dbo.t_wms_customer.phone
			 , dbo.t_wms_customer.customer_code
			 , dbo.t_wms_customer.customer_name
			 , dbo.t_wms_owner.description
			 , dbo.t_wms_owner.addr_line_1
			 , dbo.t_wms_owner.addr_line_2
			 , dbo.t_wms_owner.addr_line_3
		FROM dbo.t_wms_outbound_master 
		INNER JOIN dbo.t_wms_outbound_detail ON dbo.t_wms_outbound_master.outbound_order_master_id = dbo.t_wms_outbound_detail.outbound_order_master_id 
		INNER JOIN dbo.t_wms_wh_item ON dbo.t_wms_outbound_detail.wh_item_master_id = dbo.t_wms_wh_item.wh_item_master_id 
		INNER JOIN dbo.t_wms_item ON dbo.t_wms_wh_item.item_master_id = dbo.t_wms_item.item_master_id 
			   AND dbo.t_wms_outbound_detail.item_master_id = dbo.t_wms_item.item_master_id 
		INNER JOIN dbo.t_wms_customer ON dbo.t_wms_outbound_master.customer_code = dbo.t_wms_customer.customer_code
		INNER JOIN dbo.t_wms_owner ON dbo.t_wms_outbound_master.owner_code = dbo.t_wms_owner.owner_code
		WHERE (dbo.t_wms_outbound_master.outbound_order_number = @invch_outbound_order_number)
		  AND (dbo.t_wms_outbound_master.owner_code = @invch_owner_code OR @invch_owner_code IS NULL)
		  AND (dbo.t_wms_outbound_master.wh_id = @invch_wh_id OR @invch_wh_id IS NULL)

		OPEN Iterator;
			WHILE 1=1
				BEGIN
					FETCH NEXT FROM Iterator INTO @outbound_order_master_id, @ship_to_name,  @ship_to_addr_line_1, @ship_to_contact, @order_type, @order_status, @order_date, @ship_date_plan, @ship_date_actual, @ship_to_phone, @owner_code, @wh_id, @outbound_order_number, @quantity_ship, @model,  @item_master_id, @item_number,  @phone, @customer_code, @customer_name, @description, @addr_line_1, @addr_line_2, @addr_line_3
					IF @@FETCH_STATUS < 0 BREAK;
					declare @intCount float = 0;
					WHILE @intCount < @quantity_ship
						BEGIN
							SET @intCount = @intCount +1
							insert into #tempData
							select @outbound_order_master_id, @ship_to_name,  @ship_to_addr_line_1, @ship_to_contact, @order_type, @order_status, @order_date, @ship_date_plan, @ship_date_actual, @ship_to_phone, @owner_code, @wh_id, @outbound_order_number ,@quantity_ship, @intCount, @model,  @item_master_id, @item_number,  @phone, @customer_code, @customer_name, @description, @addr_line_1, @addr_line_2, @addr_line_3
						END
				END		
		CLOSE Iterator;
	DEALLOCATE Iterator;

	select * from #tempData
	drop table #tempData

END
GO
/****** Object:  StoredProcedure [dbo].[usp_visual_location_map]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Kritsada Baothong
-- Create date: 2013-11-05
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_visual_location_map]
	-- Add the parameters for the stored procedure here
	@wh_master_id NVARCHAR(40)
	, @location_level  NVARCHAR(10)
	, @loc_type NVARCHAR(20)
	, @zone_id NVARCHAR(40)
	, @owner_id NVARCHAR(40)
	, @item_master_id NVARCHAR(40)
	, @category_id NVARCHAR(40)	
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT 
		wh.wh_master_id, wh.wh_id, wh.wh_name,
		lo.location_id, lo.location, lo.location_level, lo.loc_type, lo.x_cordinate, lo.y_cordinate, lo.capacity_qty,
		(ISNULL(lo.capacity_qty,0) - ISNULL(R1.count_lpn,0)) AS available, 	
		(ISNULL(R1.count_lpn,0) * 100)/ISNULL(lo.capacity_qty,1)AS usage,
		ISNULL(z.zone_id,NULL) AS zone_id, z.zone,
		ISNULL(R1.owner_id,NULL) AS owner_id, ISNULL(R1.item_master_id,NULL) AS item_master_id, R1.item_number, ISNULL(R1.category_id,NULL) AS category_id, R1.count_lpn
	FROM		[dbo].[t_wms_location]			AS lo
	LEFT JOIN	[dbo].[t_wms_wh]				AS wh	ON lo.wh_master_id = wh.wh_master_id
	LEFT JOIN	[dbo].[t_wms_zone_location]		AS zl	ON lo.location_id = zl.location_id
	LEFT JOIN	[dbo].[t_wms_zone]				AS z	ON z.zone_id = zl.zone_id
	LEFT JOIN 	
	(
		SELECT 		
			inv.location_id			
			,item.owner_id	
			,item.item_master_id	
			,item.item_number
			,item.category_id		
			--,sum(inv.quantity) qty	
			,count(inv.lpn) count_lpn	
		FROM 
			t_wms_inventory inv
			LEFT JOIN t_wms_wh_item				AS whItem	ON inv.wh_item_master_id = whItem.wh_item_master_id
			LEFT JOIN t_wms_item				AS item		ON whitem.item_master_id = item.item_master_id					
		GROUP BY 			
			inv.location_id			
			,item.owner_id
			,item.item_master_id	
			,item.item_number
			,item.category_id	
	)R1
	ON lo.location_id = R1.location_id
	WHERE 
	wh.wh_master_id = @wh_master_id 
	AND lo.location_level = @location_level
	AND lo.loc_type LIKE '%'+@loc_type+'%'
	AND (z.zone_id IS NULL OR z.zone_id LIKE '%'+@zone_id+'%')
	AND (R1.owner_id IS NULL OR R1.owner_id LIKE '%'+@owner_id+'%')
	AND (R1.category_id IS NULL OR R1.category_id LIKE '%'+@category_id+'%')
	AND (R1.item_master_id IS NULL OR R1.item_master_id LIKE '%'+@item_master_id+'%')

END


GO
/****** Object:  StoredProcedure [dbo].[usp_vocollect_pick_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_vocollect_pick_item]
(
	@in_vchRecordType				NVARCHAR(20),
	@in_dtPickTime					DATETIME,
	@in_vchOriginalAssignmentNumber NVARCHAR(18),
	@in_vchLocation					NVARCHAR(50),
	@in_vchItemNumber				NVARCHAR(50),
	@in_vchUserID					NVARCHAR(25),
	@in_vchPickStatus				NVARCHAR(20),
	@in_intQuantityPicked			INT,
	@in_fltRecordedVariableWeight	FLOAT,
	@in_vchRecordedSerialNumber		NVARCHAR(50),
	@in_vchRecordedLotNumber		NVARCHAR(50),
	@in_intPickSequenceNumber		INT,
	@in_vchFileName					NVARCHAR(50),
	@out_vchErrorCode				NVARCHAR(25)	OUTPUT,
    @out_vchErrorMsg				NVARCHAR(500)	OUTPUT,
    @out_vchErrorMsgDetail			NVARCHAR(1000)	OUTPUT,
	@out_vchLineNumber				NVARCHAR(30)	OUTPUT,
    @out_vchErrorType				NVARCHAR(50)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchApplicationID			VARCHAR(40) = '2A14C878-2292-44B0-9CE6-F791C7E9870A',
			@v_vchApplicationName		NVARCHAR(50),
			@Round						INT,
			@v_dtStartTrans			DATETIME = GETDATE(),
			@v_vchOutboundMasterID		VARCHAR(40),
			@v_vchOutboundDetailID		VARCHAR(40),
			@v_vchOutboundPickMasterID	VARCHAR(40),
			@v_vchOutboundPickDetailID	VARCHAR(40),
			@v_vchStgLocationID			VARCHAR(40),
			@v_vchStgLocation			NVARCHAR(50),
			@v_vchStagingLPN			NVARCHAR(50),
			@v_vchWhMasterID			VARCHAR(40),
			@v_vchWarehouse				NVARCHAR(50),
			@v_vchOwnerID				VARCHAR(40),
			@v_vchOwner					NVARCHAR(50),
			@v_vchInvStatus				NVARCHAR(50),
			@v_vchPickToLPN				NVARCHAR(50),
			@v_vchPickLineNumber		NVARCHAR(10),
			@v_vchWhItemMasterID		VARCHAR(40),
			@v_vchItemNumber			NVARCHAR(50),
			@v_vchItemUomID				VARCHAR(40),
			@v_vchUomPrompt				NVARCHAR(50),
			@v_vchLocationID			VARCHAR(40),
			@v_vchInventoryID			VARCHAR(40)	 = NULL,
			@v_vchInvAttrGroupID		VARCHAR(40)	 = NULL,
			@v_vchInvStatusID			VARCHAR(40)	 = NULL,
			@v_dtInvReceiveDate			DATE,
			@v_fltInvQuantity			FLOAT


	SET @out_vchErrorType = 'FILE_ERROR';
	SET @v_vchPickToLPN = @in_vchOriginalAssignmentNumber;
	SET @v_vchStagingLPN = @v_vchPickToLPN;
	EXEC usp_get_application_name @v_vchApplicationID,@v_vchApplicationName OUTPUT
	SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE' AND is_active = 'YES'

	INSERT INTO [dbo].[t_vocollect_picked]
           ([record_type]
           ,[pick_time]
           ,[original_assignment_number]
           ,[location_id]
           ,[item_number]
           ,[user_id]
           ,[pick_status]
           ,[quantity_picked]
           ,[recorded_variable_weight]
           ,[recorded_serial_number]
           ,[recorded_lot_number]
           ,[pick_sequence_number]
           ,[file_name]
           ,[create_by]
           ,[create_date])
     VALUES
           (@in_vchRecordType				
           ,@in_dtPickTime					
           ,@in_vchOriginalAssignmentNumber 
           ,@in_vchLocation				
           ,@in_vchItemNumber				
           ,@in_vchUserID					
           ,@in_vchPickStatus				
           ,@in_intQuantityPicked			
           ,@in_fltRecordedVariableWeight	
           ,@in_vchRecordedSerialNumber		
           ,@in_vchRecordedLotNumber		
           ,@in_intPickSequenceNumber		
           ,@in_vchFileName
           ,'HIM_VOCOLLECT'
           ,GETDATE())

	SELECT @v_vchOutboundMasterID = obMS.outbound_order_master_id
		,@v_vchWhMasterID = obMS.wh_master_id
		,@v_vchOwnerID = obMS.owner_id
		,@v_vchOwner = own.owner_code
		,@v_vchOutboundPickMasterID = pickMS.outbound_pick_master_id 
		,@v_vchOutboundPickDetailID = pickDT.outbound_pick_detail_id
		,@v_vchOutboundDetailID = obDT.outbound_order_detail_id
		,@v_vchLocationID = pickDT.location_id
		,@v_vchInvStatus = obDT.default_item_status
		,@v_vchWhItemMasterID = pickDT.wh_item_master_id
		,@v_vchItemNumber = item.item_number
		,@v_vchItemUomID = obDT.item_uom_id
		,@v_vchUomPrompt = uom.uom_prompt
		,@v_vchPickLineNumber = pickDT.pick_line_number
	FROM t_wms_outbound_master obMS
	INNER JOIN t_wms_outbound_detail obDT ON obMS.outbound_order_master_id = obDT.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_master pickMS ON obMS.outbound_order_master_id = pickMS.outbound_order_master_id
	INNER JOIN t_wms_outbound_pick_detail pickDT ON pickMS.outbound_pick_master_id = pickDT.outbound_pick_master_id
												AND pickDT.outbound_order_detail_id = obDT.outbound_order_detail_id
	INNER JOIN t_wms_location loc ON pickDT.location_id = loc.location_id
	INNER JOIN t_wms_wh_item whItem ON pickDT.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	INNER JOIN t_wms_item_uom uom ON obDT.item_uom_id = uom.item_uom_id
	INNER JOIN t_wms_owner own ON obMS.owner_id = own.owner_id
	WHERE obMS.outbound_order_number = @in_vchOriginalAssignmentNumber
	AND loc.location = @in_vchLocation
	AND item.item_number = @in_vchItemNumber
	AND CONVERT(INT,pickDT.pick_line_number) = @in_intPickSequenceNumber

	IF (ISNULL(@v_vchOutboundMasterID,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SET @out_vchLineNumber = 'Pick Sequence Number :' + CONVERT(VARCHAR,@in_intPickSequenceNumber);
			SET @out_vchErrorMsgDetail = 'Detail : Order Number [' + ISNULL(@in_vchOriginalAssignmentNumber,'') + '] not found.';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchOriginalAssignmentNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	IF (ISNULL(@v_vchOutboundPickMasterID,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'OUTBOUND_ORDER_NOT_FOUND';
			SET @out_vchLineNumber = 'Pick Sequence Number :' + CONVERT(VARCHAR,@in_intPickSequenceNumber);
			SET @out_vchErrorMsgDetail = 'Detail : Order Number [' + ISNULL(@in_vchOriginalAssignmentNumber,'') + '] not found.';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033',@in_vchOriginalAssignmentNumber,'@param2','@param3','@param4','@param5')
			RETURN;
		END

	SELECT TOP 1 @v_vchStgLocationID = location_id
		, @v_vchStgLocation = location 
	FROM t_wms_location 
	WHERE wh_master_id = @v_vchWhMasterID 
	AND loc_type = 'STG' 
	AND is_active = 'YES'
	ORDER BY pick_sequence
	IF (ISNULL(@v_vchStgLocationID,'') = '')
		BEGIN
			SET @out_vchErrorCode = 'STAGING_LOCATION_NOT_FOUND';
			SET @out_vchLineNumber = 'Pick Sequence Number :' + CONVERT(VARCHAR,@in_intPickSequenceNumber);
			SET @out_vchErrorMsgDetail = 'Detail : Staging Location not found.';
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,@out_vchErrorCode,'1033','@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END

	IF ISNULL(@v_vchOutboundPickDetailID,'') <> ''
		BEGIN
			---------------------------------------------------		
			--Update Outbound Detail
			---------------------------------------------------		
			UPDATE t_wms_outbound_detail SET quantity_pick = ROUND(ISNULL(quantity_pick,0) + @in_intQuantityPicked,@Round)
				,item_status = 'PICK'
			WHERE outbound_order_master_id = @v_vchOutboundMasterID 
			AND outbound_order_detail_id = @v_vchOutboundDetailID 
			AND wh_item_master_id = @v_vchWhItemMasterID

			---------------------------------------------------		
			--Update Outbound Pick Detail
			---------------------------------------------------	
			UPDATE t_wms_outbound_pick_detail SET 
				  quantity_pick		  = ROUND(ISNULL(quantity_pick,0) + @in_intQuantityPicked,@Round)
				, quantity_stage	  = ROUND(ISNULL(quantity_stage,0) + @in_intQuantityPicked,@Round)
				, pick_location_id    = @v_vchStgLocationID
				, pick_to_parent_lpn  = NULL
				, pick_to_lpn		  = @v_vchPickToLPN
				, staging_location_id = @v_vchStgLocationID
				, staging_parent_lpn  = NULL
				, staging_lpn		  = @v_vchStagingLPN 
				, pick_status         = 'YES'
				, start_date_time	  = ISNULL(start_date_time,GETDATE())
				, end_date_time		  = GETDATE()
			WHERE outbound_pick_detail_id = @v_vchOutboundPickDetailID

			---------------------------------------------------	
			--Manage Source
			---------------------------------------------------	
			SELECT @v_vchInventoryID = inventory_id
				,@v_vchInvAttrGroupID = attribute_group_id
				,@v_vchInvStatusID = inventory_status_id
				,@v_dtInvReceiveDate = receive_date
				,@v_fltInvQuantity = quantity
			FROM v_wms_inventory_data_by_serial_mini
			WHERE wh_master_id = @v_vchWhMasterID
			AND owner_id = @v_vchOwnerID
			AND location_id =  @v_vchLocationID 
			AND wh_item_master_id = @v_vchWhItemMasterID 
			AND inv_status = @v_vchInvStatus
			ORDER BY receive_date

			---------------------------------------------------
			-- Manage source location data
			---------------------------------------------------
			BEGIN
				UPDATE t_wms_inventory SET quantity = ROUND(ISNULL(quantity,0) - @in_intQuantityPicked,@Round)
					,quantity_allocated = ROUND(ISNULL(quantity_allocated,0) - @in_intQuantityPicked,@Round)
				WHERE inventory_id = @v_vchInventoryID 
				AND attribute_group_id = @v_vchInvAttrGroupID

				------------------------------------------------
				-- Clear Inventory ที่หยิบของหมดแล้ว
				------------------------------------------------
				DELETE FROM t_wms_inventory WHERE quantity <= 0 
				DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0
			END

			--------------------------------------------
			--Manage Destination inventory
			--------------------------------------------
			SET @v_vchInventoryID = NULL
			SET @v_vchInvAttrGroupID = NULL
			
			SELECT @v_vchInventoryID = inventory_id
				,@v_vchInvAttrGroupID = attribute_group_id
			FROM v_wms_inventory_data_mini
			WHERE wh_master_id = @v_vchWhMasterID
			AND owner_id = @v_vchOwnerID
			AND location_id = @v_vchStgLocationID
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND inventory_status_id = @v_vchInvStatusID
			and receive_date = @v_dtInvReceiveDate
			AND ISNULL(lpn,'') = ISNULL(@v_vchStagingLPN,'')
			
			EXEC usp_manage_inventory @in_vchApplicationID			= @v_vchApplicationID
									 ,@in_vchWarehouseMasterID		= @v_vchWhMasterID
									 ,@in_vchWarehouseItemMasterID	= @v_vchWhItemMasterID
									 ,@in_vchLocationID				= @v_vchStgLocationID	
									 ,@in_vchLocation				= @v_vchStgLocation		
									 ,@in_vchStatusID				= @v_vchInvStatusID
									 ,@in_vchLPN					= @v_vchStagingLPN	
									 ,@in_vchLotNumber				= NULL
									 ,@in_vchExpiryDate				= NULL
									 ,@in_vchSerialNumber			= NULL
									 ,@in_fltQty					= @in_intQuantityPicked
									 ,@in_fltQtyAllocate			= 0
									 ,@in_fltQtyIncoming			= 0
									 ,@in_vchOwner					= @v_vchOwner
									 ,@in_vchInventoryType			= @in_vchOriginalAssignmentNumber
									 ,@in_vchPalentLPN				= NULL	
									 ,@in_vchUserID					= @in_vchUserID
									 ,@in_vchReceiveDate			= @v_dtInvReceiveDate
									 ,@in_vchInventoryID			= @v_vchInventoryID		OUTPUT
									 ,@in_vchAttributeGroupID		= @v_vchInvAttrGroupID	OUTPUT
									 ,@in_vchErrorCode				= @out_vchErrorCode		OUTPUT
									 ,@in_vchMessage				= @out_vchErrorMsg		OUTPUT

			IF (@out_vchErrorCode <> '0')
				BEGIN
					SET @out_vchLineNumber = 'Record Number :' + CONVERT(VARCHAR,@in_intPickSequenceNumber);
					SET @out_vchErrorMsgDetail = 'Detail :' + @out_vchErrorMsg;
					RETURN;
				END


			INSERT INTO t_com_tran_log
				( app_id							
				, tran_type
				, sub_tran_type
				, [app_name]
				, [description]
				, start_tran_datetime
				, end_tran_datetime
				, warehouse
				, to_warehouse
				, location
				, to_location
				, [owner]
				, to_owner
				, item_number
				, quantity
				, quantity_uom
				, after_quantity
				, after_quantity_uom
				, [user_id]
				, lpn
				, after_lpn
				, [status]
				, after_status
				, zone
				, order_number
				, line_number
				, device
				, create_by
				, create_date
			)
			VALUES
			(     @v_vchApplicationID
				, 'INV_MOVE'
				, 'MOVE_DEST'
				, @v_vchApplicationName
				, 'Update pick to staging [Vocollect]'
				, @v_dtStartTrans
				, DATEADD(millisecond,2,GETDATE())
				, @v_vchWarehouse
				, @v_vchWarehouse
				, @in_vchLocation
				, @v_vchStgLocation
				, @v_vchOwner
				, @v_vchOwner
				, @in_vchItemNumber
				, @in_intQuantityPicked
				, @v_vchUomPrompt
				, @v_fltInvQuantity - @in_intQuantityPicked
				, @v_vchUomPrompt
				, @in_vchUserID
				, NULL
				, @v_vchStagingLPN
				, @v_vchInvstatus
				, @v_vchInvstatus
				, NULL
				, @in_vchOriginalAssignmentNumber
				, @v_vchPickLineNumber
				, 'Vocollect'
				, @in_vchUserID
				, GETDATE()
			)

			------------------------------------------------
			-- Update Order Status ถ้า Pick ครบแล้ว
			------------------------------------------------
			IF ((SELECT SUM(quantity_order) - SUM(quantity_pick) FROM t_wms_outbound_detail WHERE outbound_order_master_id = @v_vchOutboundMasterID) = 0)
				BEGIN
					UPDATE t_wms_outbound_master SET order_status = 'PICKED' WHERE outbound_order_master_id = @v_vchOutboundMasterID AND order_status NOT IN ('LOADING','LOADED')
				END

			------------------------------------------------
			-- Clear Inventory ที่หยิบของหมดแล้ว
			------------------------------------------------
			DELETE FROM t_wms_inventory WHERE quantity <= 0 
			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 
	
			SET @out_vchErrorCode = 0;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@v_vchApplicationID,'SAVE_SUCCESS','1033','@param1','@param2','@param3','@param4','@param5')

		END

END

GO
/****** Object:  StoredProcedure [dbo].[usp_wms_calculate_outbound_bom]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_calculate_outbound_bom]
(	
	@in_vchWhMasterID		UNIQUEIDENTIFIER,
	@in_vchOwnerID			UNIQUEIDENTIFIER,
	@in_vchOutboundMasterID	UNIQUEIDENTIFIER,
	@in_vchUserID			NVARCHAR(25),
	@out_ErrorCode			NVARCHAR(50) OUTPUT,  
	@out_ErrorMessage		NVARCHAR(500) OUTPUT 
)
AS
BEGIN
	DECLARE @v_vchBomID					INT,
			@v_intQtyBom				INT,

			@v_vchOutboundDeatilID		UNIQUEIDENTIFIER,
			@v_vchBomWhItemMasterID		UNIQUEIDENTIFIER,
			@v_vchBomItemMasterID		UNIQUEIDENTIFIER,
			@v_vchBomItemNumber			NVARCHAR(50),
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER,
			@v_vchItemNumber			NVARCHAR(50),
			@v_vchItemDescription		NVARCHAR(200),
			@v_vchLPN					NVARCHAR(25),
			@v_vchLotNumber				NVARCHAR(50),
			@v_vchExpiryDate			NVARCHAR(8),
			@v_vchSerialNumber			NVARCHAR(50),
			@v_vchAttribute1			NVARCHAR(100),
			@v_vchAttribute2			NVARCHAR(100),
			@v_vchAttribute3			NVARCHAR(100),
			@v_vchAttribute4			NVARCHAR(100),
			@v_vchAttribute5			NVARCHAR(100),
			@v_fltQuantity				FLOAT,		--qty from bom ms
			@v_fltCalQtyBomDetail		FLOAT,		--qty from bom ms * จำนวนที่สามารถทำเป็น bom
			@v_fltRemainBomQtyShip		FLOAT,		--จำนวนคงเหลือที่สามารถทำ bom ได้ใน obdt record นั้นๆ
			@v_fltBomQtyShip			FLOAT		--สำหรับ update bom qty ship
			

BEGIN TRY
		DECLARE Bom_Cursor CURSOR FOR
			SELECT DISTINCT bom_id 
				,bom_wh_item_master_id
				,bom_item_master_id
				,bom_item_number
			FROM t_wms_outbound_detail 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND quantity_ship > 0
			AND ISNULL(bom_id,'') <> ''
		OPEN Bom_Cursor
		FETCH NEXT FROM Bom_Cursor INTO @v_vchBomID,@v_vchBomWhItemMasterID,@v_vchBomItemMasterID,@v_vchBomItemNumber
		WHILE @@FETCH_STATUS = 0
			BEGIN
				-----------------------------------------------
				-- Get quantity เพื่อคำนวณ bom qty
				-----------------------------------------------
				SELECT bomDT.item_number	AS item_number
					,bomDT.description	AS item_description
					,bomDT.quantity
					,obDT.wh_item_master_id
					,obDT.lpn
					,obDT.lot_number
					,obDT.expiry_date
					,obDT.serial_number
					,obDT.attribute1
					,obDT.attribute2
					,obDT.attribute3
					,obDT.attribute4
					,obDT.attribute5
					,ISNULL(remain_bom_quantity_ship,0) AS remain_bom_quantity_ship
					,ISNULL(remain_bom_quantity_ship,0) / ISNULL(bomDT.quantity,0) AS qty_bom
				INTO #tempBomShip
				FROM t_wms_item_bom_detail bomDT 
				LEFT JOIN (SELECT wh_item_master_id
								,bom_id
								,bom_detail_id
								,bom_wh_item_master_id
								,bom_item_master_id
								,bom_item_number
								,ISNULL(lpn,'')	AS lpn
								,ISNULL(lot_number,'') AS lot_number
								,ISNULL(serial_number,'') AS serial_number
								,ISNULL(expiry_date,'')	AS expiry_date
								,ISNULL(attribute1,'')  AS attribute1
								,ISNULL(attribute2,'')  AS attribute2
								,ISNULL(attribute3,'')  AS attribute3
								,ISNULL(attribute4,'')  AS attribute4
								,ISNULL(attribute5,'')  AS attribute5
								,SUM(ISNULL(quantity_ship,0))	  AS quantity_ship
								,SUM(ISNULL(bom_quantity_ship,0)) AS bom_quantity_ship
								,SUM(ISNULL(quantity_ship,0)) - SUM(ISNULL(bom_quantity_ship,0)) AS remain_bom_quantity_ship
							FROM t_wms_outbound_detail
							WHERE outbound_order_master_id = @in_vchOutboundMasterID
							AND ISNULL(bom_id,'') <> ''
							GROUP BY outbound_order_master_id,wh_item_master_id,bom_id,bom_detail_id,bom_wh_item_master_id,bom_item_master_id,bom_item_number,lpn,lot_number,expiry_date,serial_number
							,attribute1,attribute2,attribute3,attribute4,attribute5
							) obDT ON bomDT.bom_detail_id = obDT.bom_detail_id
				WHERE bomDT.bom_id = @v_vchBomID
				
				-----------------------------------------------
				--ตรวจสอบว่ามี item ที่ไม่สามารถจัด bom ได้หรือไม่
				-----------------------------------------------
				IF EXISTS (SELECT * FROM #tempBomShip WHERE qty_bom = 0)
					BEGIN
						GOTO next_row
						PRINT 'END LOOP'
					END

				-------------------------------------------------------------------------
				--คำนวณจำนวนที่สามารถจัด bom ได้ครบทุก item >> คือค่าน้อยที่สุดในจำนวน item ของ bom นั้น
				-------------------------------------------------------------------------
				SELECT TOP 1 @v_intQtyBom = qty_bom FROM #tempBomShip ORDER BY qty_bom

				-------------------------------------------
				--Insert/Update inventory bom
				-------------------------------------------
				IF EXISTS (SELECT inventory_bom_id FROM t_wms_inventory_bom 
							WHERE wh_master_id = @in_vchWhMasterID 
							AND bom_id = @v_vchBomID
							AND bom_wh_item_master_id = @v_vchBomWhItemMasterID
							AND owner_id = @in_vchOwnerID)
					BEGIN
						UPDATE t_wms_inventory_bom SET quantity_ship = ISNULL(quantity_ship,0) + ISNULL(@v_intQtyBom,0)
						WHERE wh_master_id = @in_vchWhMasterID 
						AND bom_id = @v_vchBomID
						AND bom_wh_item_master_id = @v_vchBomWhItemMasterID
						AND owner_id = @in_vchOwnerID
					END
				ELSE
					BEGIN
						INSERT INTO [dbo].[t_wms_inventory_bom]
								([wh_master_id]
								,[owner_id]
								,[bom_id]
								,[bom_wh_item_master_id]
								,[bom_item_master_id]
								,[bom_item_number]
								,[quantity_ship]
								,[create_by]
								,[create_date])
							VALUES
								(@in_vchWhMasterID
								,@in_vchOwnerID
								,@v_vchBomID
								,@v_vchBomWhItemMasterID
								,@v_vchBomItemMasterID
								,@v_vchBomItemNumber
								,@v_intQtyBom
								,@in_vchUserID
								,GETDATE())
					END

				DECLARE Bom_Detail_Cursor CURSOR FOR
					SELECT wh_item_master_id
						,item_number
						,item_description
						,lpn
						,lot_number
						,expiry_date
						,serial_number
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,quantity
						,quantity * @v_intQtyBom 
					FROM #tempBomShip
					ORDER BY qty_bom
				OPEN Bom_Detail_Cursor
				FETCH NEXT FROM Bom_Detail_Cursor INTO @v_vchWhItemMasterID,@v_vchItemNumber,@v_vchItemDescription,@v_vchLpn,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,
													   @v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltQuantity,@v_fltCalQtyBomDetail
				WHILE @@FETCH_STATUS = 0
					BEGIN
						-------------------------------------------
						--Update row outbound_detail
						-------------------------------------------
						DECLARE OutboundDetail_Cursor CURSOR FOR
							SELECT outbound_order_detail_id
								,(ISNULL(quantity_ship,0) - ISNULL(bom_quantity_ship,0))
							FROM t_wms_outbound_detail 
							WHERE outbound_order_master_id = @in_vchOutboundMasterID 
							AND wh_item_master_id = @v_vchWhItemMasterID
							AND bom_id = @v_vchBomID
							AND bom_wh_item_master_id = @v_vchBomWhItemMasterID
							AND (CASE ISNULL(@v_vchLpn,'') WHEN '' THEN '' ELSE lpn END) = (CASE ISNULL(@v_vchLpn,'') WHEN '' THEN '' ELSE @v_vchLpn END)
							AND (CASE ISNULL(@v_vchLotNumber,'') WHEN '' THEN '' ELSE lot_number END) = (CASE ISNULL(@v_vchLotNumber,'') WHEN '' THEN '' ELSE @v_vchLotNumber END)
							AND (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN '' ELSE expiry_date END) = (CASE ISNULL(@v_vchExpiryDate,'') WHEN '' THEN '' ELSE @v_vchExpiryDate END)
							AND (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE serial_number END) = (CASE ISNULL(@v_vchSerialNumber,'') WHEN '' THEN '' ELSE @v_vchSerialNumber END)
							AND (CASE ISNULL(@v_vchAttribute1,'') WHEN '' THEN '' ELSE attribute1 END) = (CASE ISNULL(@v_vchAttribute1,'') WHEN '' THEN '' ELSE @v_vchAttribute1 END)
							AND (CASE ISNULL(@v_vchAttribute2,'') WHEN '' THEN '' ELSE attribute2 END) = (CASE ISNULL(@v_vchAttribute2,'') WHEN '' THEN '' ELSE @v_vchAttribute2 END)
							AND (CASE ISNULL(@v_vchAttribute3,'') WHEN '' THEN '' ELSE attribute3 END) = (CASE ISNULL(@v_vchAttribute3,'') WHEN '' THEN '' ELSE @v_vchAttribute3 END)
							AND (CASE ISNULL(@v_vchAttribute4,'') WHEN '' THEN '' ELSE attribute4 END) = (CASE ISNULL(@v_vchAttribute4,'') WHEN '' THEN '' ELSE @v_vchAttribute4 END)
							AND (CASE ISNULL(@v_vchAttribute5,'') WHEN '' THEN '' ELSE attribute5 END) = (CASE ISNULL(@v_vchAttribute5,'') WHEN '' THEN '' ELSE @v_vchAttribute5 END)
							AND (ISNULL(quantity_ship,0) - ISNULL(bom_quantity_ship,0)) > 0
							ORDER BY line_number
						OPEN OutboundDetail_Cursor
						FETCH NEXT FROM OutboundDetail_Cursor INTO @v_vchOutboundDeatilID,@v_fltRemainBomQtyShip
						WHILE @@FETCH_STATUS = 0
							BEGIN
								IF @v_fltCalQtyBomDetail > @v_fltRemainBomQtyShip
									SET @v_fltBomQtyShip = @v_fltRemainBomQtyShip
								ELSE
									SET @v_fltBomQtyShip = @v_fltCalQtyBomDetail
									 
								UPDATE t_wms_outbound_detail SET bom_quantity_ship = ISNULL(bom_quantity_ship,0) + ISNULL(@v_fltBomQtyShip,0) WHERE outbound_order_detail_id = @v_vchOutboundDeatilID
								
								SET @v_fltCalQtyBomDetail = @v_fltCalQtyBomDetail - @v_fltBomQtyShip
								IF @v_fltCalQtyBomDetail = 0
									BREAK;
								FETCH NEXT FROM OutboundDetail_Cursor INTO @v_vchOutboundDeatilID,@v_fltRemainBomQtyShip
							END
						CLOSE OutboundDetail_Cursor
						DEALLOCATE OutboundDetail_Cursor
						FETCH NEXT FROM Bom_Detail_Cursor INTO @v_vchWhItemMasterID,@v_vchItemNumber,@v_vchItemDescription,@v_vchLpn,@v_vchLotNumber,@v_vchExpiryDate,@v_vchSerialNumber,
															   @v_vchAttribute1,@v_vchAttribute2,@v_vchAttribute3,@v_vchAttribute4,@v_vchAttribute5,@v_fltQuantity,@v_fltCalQtyBomDetail
					END
				CLOSE Bom_Detail_Cursor
				DEALLOCATE Bom_Detail_Cursor		

				NEXT_ROW:
					PRINT 'NEXT ROW'
					DROP TABLE #tempBomShip
				FETCH NEXT FROM Bom_Cursor INTO @v_vchBomID,@v_vchBomWhItemMasterID,@v_vchBomItemMasterID,@v_vchBomItemNumber
			END
		CLOSE Bom_Cursor
		DEALLOCATE Bom_Cursor
		SET @out_ErrorCode = '0';
		SET @out_ErrorMessage = 'Success';

END TRY
BEGIN CATCH
	SET @out_ErrorCode = ERROR_NUMBER();
	SET @out_ErrorMessage = ERROR_MESSAGE();
	IF CURSOR_STATUS('global','OutboundDetail_Cursor')>=-1
		BEGIN
			CLOSE OutboundDetail_Cursor;
			DEALLOCATE OutboundDetail_Cursor;
		END
	IF CURSOR_STATUS('global','Bom_Detail_Cursor')>=-1
		BEGIN
			CLOSE Bom_Detail_Cursor;
			DEALLOCATE Bom_Detail_Cursor;
		END
	IF CURSOR_STATUS('global','Bom_Cursor')>=-1
		BEGIN
			CLOSE Bom_Cursor;
			DEALLOCATE Bom_Cursor;
		END
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_change_status_by_serial]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_change_status_by_serial]
(
	@in_vchApplicationID		NVARCHAR(50) = NULL,
	@in_vchLocation				NVARCHAR(50),
	@in_vchSerialNumber			NVARCHAR(100),
	@in_vchDestinationStatus	NVARCHAR(50),
	@in_vchDevice				NVARCHAR(50) = NULL,
	@in_vchUserID				NVARCHAR(25),
	@in_vchTranType				NVARCHAR(20),
	@in_vchSubTranType			NVARCHAR(20),
	@in_vchTranTypeDesc			NVARCHAR(100)= NULL,
	@out_vchErrorCode			NVARCHAR(50) = NULL OUTPUT,
	@out_vchErrorMsg			NVARCHAR(250)= NULL OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	BEGIN TRY
		DECLARE @v_vchBeginTrans			INT,
				@v_vchApplicationName		NVARCHAR(50)= NULL,
				@v_vchStartTrans			DATETIME	= NULL,
				@v_vchInventoryID			VARCHAR(40) = NULL,
				@v_vchAttributeGroupID		VARCHAR(40) = NULL,
				@v_vchSourceInvStatus		NVARCHAR(50)= NULL,	
				@v_fltSourceInvQty			FLOAT,
				@v_vchDestInvStatusID		VARCHAR(40) = NULL,
				@v_dtReceiveDate			DATE,
				@v_vchWhMasterID			VARCHAR(40)	= NULL,
				@v_vchWarehouse				NVARCHAR(50)= NULL,
				@v_vchWhItemMasterID		VARCHAR(40)	= NULL,
				@v_vchItemMasterID			VARCHAR(40)	= NULL,
				@v_vchLocationID			VARCHAR(40)	= NULL,
				@v_vchLocation				NVARCHAR(50)= NULL,
				@v_vchOwnerID				VARCHAR(40)	= NULL,
				@v_vchOwner					NVARCHAR(50)= NULL,
				@v_vchParentLPN				NVARCHAR(25)= NULL,
				@v_vchLPN					NVARCHAR(25)= NULL,
				@v_vchLotNumber				NVARCHAR(100)=NULL,
				@v_vchExpiryDate			NVARCHAR(100)=NULL,
				@v_vchAttribute1			NVARCHAR(100)=NULL,
				@v_vchAttribute2			NVARCHAR(100)=NULL,
				@v_vchAttribute3			NVARCHAR(100)=NULL,
				@v_vchAttribute4			NVARCHAR(100)=NULL,
				@v_vchAttribute5			NVARCHAR(100)=NULL,
				@v_vchItemNumber			NVARCHAR(50) =NULL,
				@v_vchPrimaryUOMPrompt		NVARCHAR(50) =NULL,
				@v_vchLotControl			NVARCHAR(10)= NULL,
				@v_vchSNControl				NVARCHAR(10)= NULL,
				@v_vchExpiryDateControl		NVARCHAR(10)= NULL,
				@v_vchAttribute1Control		NVARCHAR(10)= NULL,
				@v_vchAttribute2Control		NVARCHAR(10)= NULL,
				@v_vchAttribute3Control		NVARCHAR(10)= NULL,
				@v_vchAttribute4Control		NVARCHAR(10)= NULL,
				@v_vchAttribute5Control		NVARCHAR(10)= NULL,
				@Round						INT

		SET @v_vchStartTrans = GETDATE();
		SELECT @Round = value FROM t_wms_rule WHERE rule_code = 'RULE_DECIMAL_SCALE'
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT

		IF (ISNULL(@in_vchApplicationID,'') = '')
			BEGIN
				SET @in_vchApplicationID = 'IOS'
				SET @v_vchApplicationName = 'IOS'
			END

		IF (ISNULL(@in_vchDevice,'') = '')
			BEGIN
				SET @in_vchDevice = 'IOS'
			END

		--------------------------------------------
		--Get Status 
		--------------------------------------------
		SELECT @v_vchDestInvStatusID = inventory_status_id FROM t_wms_inventory_status WHERE inv_status = @in_vchDestinationStatus AND is_active = 'YES'
		IF (ISNULL(@v_vchDestInvStatusID,'') = '')
			BEGIN
				SET @out_vchErrorCode = 'INVENTORY_STATUS_NOT_FOUND';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),@in_vchDestinationStatus,'@param2','@param3','@param4','@param5')
				RETURN;
			END

		BEGIN TRANSACTION
			SET @v_vchBeginTrans = 1;

			--------------------------------------------
			--Get Source inventory id
			--------------------------------------------
			SELECT @v_vchInventoryID = inventory_id
				,@v_vchAttributeGroupID = attribute_group_id
				,@v_vchSourceInvStatus = inv_status
				,@v_fltSourceInvQty = quantity
				,@v_dtReceiveDate = receive_date
				,@v_vchWhMasterID = wh_master_id
				,@v_vchWarehouse = wh_id
				,@v_vchWhItemMasterID = wh_item_master_id
				,@v_vchItemMasterID = item_master_id
				,@v_vchItemNumber = item_number
				,@v_vchLocationID = location_id
				,@v_vchLocation = location
				,@v_vchOwnerID = owner_id
				,@v_vchOwner = owner_code
				,@v_vchParentLPN = parent_lpn
				,@v_vchLPN = lpn
				,@v_vchLotNumber = lot_number	
				,@v_vchExpiryDate = expiry_date
				,@v_vchAttribute1 = attribute1
				,@v_vchAttribute2 = attribute2
				,@v_vchAttribute3 = attribute3
				,@v_vchAttribute4 = attribute4
				,@v_vchAttribute5 = attribute5
				,@v_vchPrimaryUOMPrompt = uom_prompt
			FROM v_wms_inventory_data_by_serial
			WHERE serial_number = @in_vchSerialNumber
			AND location = @in_vchLocation
			IF (ISNULL(@v_vchInventoryID,'') = '')
				BEGIN
					SET @out_vchErrorCode = 'INFO-SN-NOT-EXISTS';
					SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					
					IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
						ROLLBACK TRANSACTION;
					RETURN;
				END

			-------------------------------------------
			--Get item control
			-------------------------------------------
			SELECT @v_vchLotControl = lot_control
				  ,@v_vchSNControl = sn_control
				  ,@v_vchExpiryDateControl = expiry_date_control
				  ,@v_vchAttribute1Control = attribute1_control
				  ,@v_vchAttribute2Control = attribute2_control
				  ,@v_vchAttribute3Control = attribute3_control
				  ,@v_vchAttribute4Control = attribute4_control
				  ,@v_vchAttribute5Control = attribute5_control
			FROM t_wms_item 
			WHERE item_master_id = @v_vchItemMasterID

			--------------------------------------------
			--Manage source inventory
			--------------------------------------------
			UPDATE t_wms_inventory SET quantity = ROUND(quantity - 1,@Round) 
			WHERE inventory_id = @v_vchInventoryID 
			AND attribute_group_id = @v_vchAttributeGroupID

			IF (@v_vchSNControl = 'FULL')
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - 1,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID 
					AND attribute_value = @in_vchSerialNumber													
				END

			--Inventory attribute
			IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
				BEGIN
					UPDATE t_wms_inventory_attribute SET quantity = ROUND(quantity - 1,@Round) 
					WHERE inventory_id = @v_vchInventoryID 
					AND attribute_group_id = @v_vchAttributeGroupID
					AND inv_attribute_type_id <> (SELECT TOP 1 inv_attribute_type_id FROM t_wms_inventory_attribute_type where inv_attribute_type = 'SERIAL' AND is_active = 'YES')
				END

			--------------------------------------------
			--Get destination inventory id
			--------------------------------------------
			SET @v_vchInventoryID = NULL;
			SET @v_vchAttributeGroupID = NULL;
			SELECT @v_vchInventoryID = inventory_id
				, @v_vchAttributeGroupID = attribute_group_id
			FROM v_wms_inventory_data_mini
			WHERE wh_master_id = @v_vchWhMasterID 
			AND wh_item_master_id = @v_vchWhItemMasterID
			AND location_id = @v_vchLocationID
			AND inventory_status_id = @v_vchDestInvStatusID
			AND ISNULL(parent_lpn,'') = ISNULL(@v_vchParentLPN,'')
			AND ISNULL(lpn,'') = ISNULL(@v_vchLPN,'')
			AND ISNULL(lot_number,'') = ISNULL(@v_vchLotNumber,'') 
			AND ISNULL(expiry_date,'')= ISNULL(@v_vchExpiryDate,'')
			AND ISNULL(attribute1,'') = ISNULL(@v_vchAttribute1,'')
			AND ISNULL(attribute2,'') = ISNULL(@v_vchAttribute2,'')
			AND ISNULL(attribute3,'') = ISNULL(@v_vchAttribute3,'')
			AND ISNULL(attribute4,'') = ISNULL(@v_vchAttribute4,'')
			AND ISNULL(attribute5,'') = ISNULL(@v_vchAttribute5,'')

			--------------------------------------------
			--Manage destination inventory
			--------------------------------------------
			EXEC usp_manage_inventory @in_vchApplicationID			= @in_vchApplicationID
									,@in_vchWarehouseMasterID		= @v_vchWhMasterID
									,@in_vchWarehouseItemMasterID	= @v_vchWhItemMasterID
									,@in_vchLocationID				= @v_vchLocationID
									,@in_vchLocation				= @v_vchLocation
									,@in_vchStatusID				= @v_vchDestInvStatusID
									,@in_vchLPN						= @v_vchLPN
									,@in_vchLotNumber				= @v_vchLotNumber
									,@in_vchExpiryDate				= @v_vchExpiryDate
									,@in_vchSerialNumber			= @in_vchSerialNumber	
									,@in_fltQty						= 1	
									,@in_fltQtyAllocate				= 0
									,@in_fltQtyIncoming				= 0
									,@in_vchOwner					= @v_vchOwner
									,@in_vchInventoryType			= 'INVENTORY'
									,@in_vchPalentLPN				= @v_vchParentLPN
									,@in_vchUserID					= @in_vchUserID
									,@in_vchReceiveDate				= @v_dtReceiveDate
									,@in_vchInventoryID				= @v_vchInventoryID      OUTPUT
									,@in_vchAttributeGroupID		= @v_vchAttributeGroupID OUTPUT
									,@in_vchErrorCode				= @out_vchErrorCode OUTPUT
									,@in_vchMessage					= @out_vchErrorMsg	OUTPUT
				IF (@out_vchErrorCode <> '0')
					BEGIN
						GOTO WRITE_PROC;
					END
					
				IF ('FULL' IN (@v_vchLotControl,@v_vchExpiryDateControl,@v_vchSNControl,@v_vchAttribute1Control,@v_vchAttribute2Control,@v_vchAttribute3Control,@v_vchAttribute4Control,@v_vchAttribute5Control))
					BEGIN
						EXEC usp_manage_inventory_attribute
							@in_vchApplicationID		= @in_vchApplicationID
							, @in_vchItem				= @v_vchItemNumber
							, @in_vchSerialNo			= @in_vchSerialNumber
							, @in_vchLot				= @v_vchLotNumber
							, @in_vchExpiryDate			= @v_vchExpiryDate
							, @in_vchAttribute1			= @v_vchAttribute1
							, @in_vchAttribute2			= @v_vchAttribute2
							, @in_vchAttribute3			= @v_vchAttribute3
							, @in_vchAttribute4			= @v_vchAttribute4
							, @in_vchAttribute5			= @v_vchAttribute5
							, @in_fltQty				= 1
							, @in_fltQtyAllocate		= 0
							, @in_fltQtyIncoming		= 0
							, @in_vchInventoryID		= @v_vchInventoryID
							, @in_vchAttributeGroupID	= @v_vchAttributeGroupID
							, @in_vchLotControl			= @v_vchLotControl
							, @in_vchSNControl			= @v_vchSNControl
							, @in_vchExpiryDateControl	= @v_vchExpiryDateControl
							, @in_vchAttribute1Control	= @v_vchAttribute1Control
							, @in_vchAttribute2Control	= @v_vchAttribute2Control
							, @in_vchAttribute3Control	= @v_vchAttribute3Control
							, @in_vchAttribute4Control	= @v_vchAttribute4Control
							, @in_vchAttribute5Control	= @v_vchAttribute5Control
							, @in_vchUserID				= @in_vchUserID
							, @in_vchErrorCode			= @out_vchErrorCode OUTPUT
							, @in_vchMessage			= @out_vchErrorMsg   OUTPUT

						IF (@out_vchErrorCode <> '0')
							BEGIN
								GOTO WRITE_PROC;
							END
					END

			--------------------------------------------
			--tran type		>> INV_STATUS_CHANGE	   
			--sub tran type >> EXTERNAL_CHANGE		   
			--------------------------------------------
			INSERT INTO [dbo].[t_com_tran_log]
				   ([app_id]				
				   ,[tran_type]				
				   ,[sub_tran_type]			
				   ,[app_name]				
				   ,[description]			
				   ,[start_tran_datetime]	
				   ,[end_tran_datetime]		
				   ,[warehouse]				
				   ,[to_warehouse]			
				   ,[location]				
				   ,[to_location]			
				   ,[owner]					
				   ,[to_owner]				
				   ,[item_number]			
				   ,[quantity]				
				   ,[quantity_uom]			
				   ,[after_quantity]		
				   ,[after_quantity_uom]	
				   ,[lot_number]			
				   ,[after_lot_number]		
				   ,[expiry_date]			
				   ,[after_expiry_date]		
				   ,[serial_number]			
				   ,[attribute1]			
				   ,[after_attribute1]		
				   ,[attribute2]			
				   ,[after_attribute2]		
				   ,[attribute3]			
				   ,[after_attribute3]		
				   ,[attribute4]			
				   ,[after_attribute4]		
				   ,[attribute5]			
				   ,[after_attribute5]		
				   ,[user_id]				
				   ,[reference_number]		
				   ,[control_number]		
				   ,[lpn]					
				   ,[after_lpn]				
				   ,[parent_lpn]			
				   ,[after_parent_lpn]		
				   ,[status]				
				   ,[after_status]			
				   ,[zone]					
				   ,[to_zone]				
				   ,[order_number]			
				   ,[line_number]			
				   ,[device]
				   ,[create_date]
				   ,[create_by])
			 VALUES
				   (@in_vchApplicationID					
				   ,@in_vchTranType		--'INV_STATUS_CHANGE'				
				   ,@in_vchSubTranType	--'EXTERNAL_CHANGE'				
				   ,@v_vchApplicationName					
				   ,@in_vchTranTypeDesc --'Change Status'				
				   ,@v_vchStartTrans				
				   ,GETDATE()						
				   ,@v_vchWarehouse				
				   ,@v_vchWarehouse				
				   ,@v_vchLocation				
				   ,@v_vchLocation				
				   ,@v_vchOwner					
				   ,@v_vchOwner					
				   ,@v_vchItemNumber			
				   ,1							
				   ,@v_vchPrimaryUOMPrompt				
				   ,(@v_fltSourceInvQty - 1)				
				   ,@v_vchPrimaryUOMPrompt					
				   ,@v_vchLotNumber				
				   ,@v_vchLotNumber				
				   ,@v_vchExpiryDate			
				   ,@v_vchExpiryDate			
				   ,@in_vchSerialNumber				
				   ,@v_vchAttribute1			
				   ,@v_vchAttribute1			
				   ,@v_vchAttribute2			
				   ,@v_vchAttribute2			
				   ,@v_vchAttribute3			
				   ,@v_vchAttribute3			
				   ,@v_vchAttribute4			
				   ,@v_vchAttribute4			
				   ,@v_vchAttribute5			
				   ,@v_vchAttribute5			
				   ,@in_vchUserID				
				   ,NULL						
				   ,NULL						
				   ,@v_vchLPN					
				   ,@v_vchLPN					
				   ,@v_vchParentLPN				
				   ,@v_vchParentLPN				
				   ,@v_vchSourceInvStatus		
				   ,@in_vchDestinationStatus	
				   ,NULL		
				   ,NULL		
				   ,NULL		
				   ,NULL		
				   ,@in_vchDevice --'IOS'		
				   ,GETDATE()	
				   ,@in_vchUserID)


			--------------------------------------------
			-- Clear Inventory
			--------------------------------------------
			DELETE FROM t_wms_inventory WHERE quantity <= 0 
			DELETE FROM t_wms_inventory_attribute WHERE quantity <= 0 
		
		COMMIT TRANSACTION;
		SET @out_vchErrorCode = '0';
		SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
		RETURN;


		-----------------------------------------------
		-- Write process log
		-----------------------------------------------
		BEGIN
			WRITE_PROC:
				IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
				DECLARE @v_dtProcessTime DATETIME = GETDATE();

				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID,
					@in_vchWhID = @v_vchWarehouse,
					@in_vchDevice = @in_vchDevice,
					@in_vchUserID = @in_vchUserID,
					@in_vchLogType = 'PROCESS',
					@in_vchProcess = 'usp_wms_change_status_by_serial',
					@in_dtProcessDateTime = @v_dtProcessTime,
					@in_vchData1 = @out_vchErrorMsg,
					@in_vchData2 = NULL,
					@in_vchData3 = NULL,
					@in_vchData4 = NULL,
					@in_vchErrorCode = @out_vchErrorCode,
					@in_vchMessage = @out_vchErrorMsg
		END	   
		-----------------------------------------------------------------------------------	
	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 and @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF (ISNULL(@out_vchErrorCode,'') = '' OR ISNULL(@out_vchErrorCode,'') = '0')
			BEGIN
				SET @out_vchErrorCode = ERROR_NUMBER();
				SET @out_vchErrorMsg = ERROR_MESSAGE();
			END		
	END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_check_count_plan]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
