-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_check_count_plan]
	-- Add the parameters for the stored procedure here
	@in_vchCountID  VARCHAR(40)  = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT       count_master_id, wh_master_id, count_id, owner_code, count_status, priority, description, count_generate_method, count_plan_type, customer_id, 
                 customer_code, customer_name, count_plan_date, hospital_signature, hospital_position, staff_signature, staff_position, create_date, create_by, close_date, 
                 close_by, close_remark
	FROM         t_wms_count_plan_master_external
	WHERE        (count_id = @in_vchCountID)
	AND          count_status ='CLOSE'
END


