/****** Object:  StoredProcedure [dbo].[usp_wms_count_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_count_rfid]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  VARCHAR(40) = NULL,
	@in_vchCountID		  VARCHAR(50) = NULL,
	@in_vchSerialNumber	  NVARCHAR(100)= NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@in_vchUserID		  NVARCHAR(25) = NULL,
	@in_vchDeviceID		  NVARCHAR(50) = NULL,
	@out_vchErrorCode	  VARCHAR(50)  = NULL OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500)= NULL OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) = NULL OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans			BIT = 0,
			@v_vchObjName				NVARCHAR(30) = 'usp_wms_count_rfid',
			@v_vchApplicationName		NVARCHAR(50),
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtProcessDateTime		DATETIME,
			@v_vchWarehouse				NVARCHAR(50),
			@v_vchAttributeGroupID		VARCHAR(40) = NULL,
			@v_vchCountMasterID			VARCHAR(40) = NULL,
			@v_vchCountDetailID			VARCHAR(40) = NULL,
			@v_vchInventoryID			VARCHAR(40) = NULL,
			@v_vchLocationID			VARCHAR(40) = NULL,
			@v_vchPalentLPN				NVARCHAR(25) = NULL,
			@v_vchLPN					NVARCHAR(25) = NULL,
			@v_vchWhItemMasterID		VARCHAR(40)  = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_vchExpiryDate			NVARCHAR(100) = NULL,
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL,
			@v_vchRuleAdjustInv			NVARCHAR(3) = NULL,
			@v_fltStockQty				FLOAT,
			@v_vchCountQty				FLOAT,
			@v_vchTransactionID			VARCHAR(40) = NULL
	
	BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 
		SELECT @v_vchRuleAdjustInv = value FROM t_wms_rule WHERE rule_code = 'RULE_ADJUST_INVENT' AND is_active = 'YES'
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		
		--Get Count Master ID
		SELECT @v_vchCountMasterID = count_master_id
		FROM t_wms_count_plan_master 
		WHERE wh_master_id = @in_vchWhMasterID
		AND count_id = @in_vchCountID

		SELECT @v_vchCountDetailID   = count_plan_detail_id
			, @v_vchLocationID		= location_id
			, @v_vchPalentLPN		= parent_lpn
			, @v_vchLPN				= lpn
			, @v_vchWhItemMasterID	= wh_item_master_id
			, @v_vchInvStatus		= inv_status
			, @v_vchLotNumber		= lot
			, @v_vchExpiryDate		= expiry_date
			, @v_vchAttribute1		= attribute1
			, @v_vchAttribute2		= attribute2
			, @v_vchAttribute3		= attribute3
			, @v_vchAttribute4		= attribute4
			, @v_vchAttribute5	    = attribute5
		FROM t_wms_count_plan_detail
		WHERE count_master_id = @v_vchCountMasterID
		AND serial_number = @in_vchSerialNumber

		IF (ISNULL(@v_vchCountDetailID,'') = '')
			BEGIN
				--Get data in inventory
				SELECT @v_vchInventoryID = inventory_id
					, @v_vchLocationID		= location_id
					, @v_vchPalentLPN		= parent_lpn
					, @v_vchLPN				= lpn
					, @v_vchWhItemMasterID	= wh_item_master_id
					, @v_vchInvStatus		= inv_status
					, @v_vchLotNumber		= lot_number
					, @v_vchExpiryDate		= expiry_date
					, @v_vchAttribute1		= attribute1
					, @v_vchAttribute2		= attribute2
					, @v_vchAttribute3		= attribute3
					, @v_vchAttribute4		= attribute4
					, @v_vchAttribute5	    = attribute5
				FROM v_wms_inventory_data_by_serial_mini
				WHERE wh_master_id = @in_vchWhMasterID
				AND serial_number = @in_vchSerialNumber

				IF (ISNULL(@v_vchInventoryID,'') = '')
					BEGIN
						SELECT TOP 1 @v_vchTransactionID	= tran_id
							 , @v_vchLocationID		= loc.location_id	
							 , @v_vchPalentLPN		= ISNULL(NULLIF(tranLog.parent_lpn,''),tranLog.after_parent_lpn) 	
							 , @v_vchLPN			= ISNULL(NULLIF(tranLog.lpn,''),tranLog.after_lpn) 			
							 , @v_vchWhItemMasterID	= whItem.wh_item_master_id				
							 , @v_vchInvStatus		= ISNULL(NULLIF(tranLog.status,''),tranLog.after_status)					
							 , @v_vchLotNumber		= ISNULL(NULLIF(tranLog.lot_number,''),tranLog.after_lot_number)		
							 , @v_vchExpiryDate		= ISNULL(NULLIF(tranLog.expiry_date,''),tranLog.after_expiry_date)
							 , @v_vchAttribute1		= ISNULL(NULLIF(tranLog.attribute1,''),tranLog.after_attribute1)  					
							 , @v_vchAttribute2		= ISNULL(NULLIF(tranLog.attribute2,''),tranLog.after_attribute2)  					
							 , @v_vchAttribute3		= ISNULL(NULLIF(tranLog.attribute3,''),tranLog.after_attribute3)  					
							 , @v_vchAttribute4		= ISNULL(NULLIF(tranLog.attribute4,''),tranLog.after_attribute4)  					
							 , @v_vchAttribute5	    = ISNULL(NULLIF(tranLog.attribute5,''),tranLog.after_attribute5)  					
						FROM t_com_tran_log tranLog
						LEFT JOIN t_wms_wh wh ON tranLog.to_warehouse = wh.wh_id
						LEFT JOIN t_wms_owner own ON tranLog.to_owner = own.owner_code
						LEFT JOIN t_wms_item item ON tranLog.item_number = item.item_number AND own.owner_id = item.owner_id
						LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
						LEFT JOIN t_wms_location loc ON ISNULL(NULLIF(tranLog.location,''),tranLog.to_location) = loc.location
						WHERE tranLog.tran_type IN ('IO_RECEIPT','INV_ADJUST')
						AND tranLog.serial_number = @in_vchSerialNumber
						
						IF ISNULL(@v_vchTransactionID,'') = ''
							BEGIN
								SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-PLAN'
								SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchSerialNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
				
				SET @v_vchInvStatus = 'Available'
			END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1

		-----------------------------------------------
		--INSERT COUNT RECONCILE
		-----------------------------------------------
		IF NOT EXISTS(SELECT count_reconcile_id FROM t_wms_count_reconcile WHERE count_master_id = @v_vchCountMasterID AND serial_number = @in_vchSerialNumber)
			BEGIN
				INSERT INTO [dbo].[t_wms_count_reconcile]
						([count_reconcile_id]
						,[count_master_id]
						,[location_id]
						,[wh_item_master_id]
						,[inv_status]
						,[parent_lpn]
						,[lpn]
						,[lot]
						,[expiry_date]
						,[serial_number]
						,[expect_qty]
						,[count_qty]
						,[adjusted_qty]
						,[adjust_by]
						,[create_date]
						,[create_by]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[device])
					VALUES
						(NEWID()
						,@v_vchCountMasterID
						,@v_vchLocationID
						,@v_vchWhItemMasterID
						,@v_vchInvStatus
						,NULLIF(@v_vchPalentLPN,'')		
						,NULLIF(@v_vchLPN,'')			
						,NULLIF(@v_vchLotNumber,'')		
						,NULLIF(@v_vchExpiryDate,'')    
						,NULLIF(@in_vchSerialNumber,'') 
						,1
						,1
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN 1 ELSE NULL END)
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN @in_vchUserID ELSE NULL END)
						,GETDATE()
						,@in_vchUserID
						,NULLIF(@v_vchAttribute1,'')
						,NULLIF(@v_vchAttribute2,'')
						,NULLIF(@v_vchAttribute3,'')
						,NULLIF(@v_vchAttribute4,'')
						,NULLIF(@v_vchAttribute5,'')
						,'Count RFID')

				-- Update Count Detail
				UPDATE t_wms_count_plan_detail SET count_qty = ISNULL(count_qty,0) + 1 WHERE count_plan_detail_id = @v_vchCountDetailID

				--Update Count Status
				UPDATE t_wms_count_plan_master SET count_status = 'IN PROCESS' WHERE count_master_id = @v_vchCountMasterID
			END

		COMMIT TRANSACTION;

		SELECT @v_fltStockQty = SUM(stock_qty)
			  ,@v_vchCountQty = SUM(count_qty)
		FROM t_wms_count_plan_detail WHERE count_master_id = @v_vchCountMasterID

		SELECT @v_fltStockQty AS stock_qty, @v_vchCountQty AS count_qty

		-----------------------------------------------
		--Next Screen
		-----------------------------------------------
		IF @v_fltStockQty <> @v_vchCountQty
			BEGIN
				SET @out_vchErrorCode = 'INFO-DETAIL-QTY-COUNT';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_fltStockQty,@v_vchCountQty,'@param3','@param4','@param5')
			END
		ELSE
			BEGIN
				SET @out_vchErrorCode = 'INFO-COUNT-SUCCESS';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_fltStockQty,@v_vchCountQty,'@param3','@param4','@param5')

			END
		SET @out_vchNextScreen = 'FINAL_SCREEN'
		RETURN;

		------------------------------------------------
		--Write process log
		------------------------------------------------
		BEGIN
			WRITE_PROC:							
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
		
				SET @v_dtProcessDateTime = GETDATE();	
				SET @v_vchProcessData1 = 'Count ID ' + @in_vchCountID;
				SET @v_vchProcessData2 = 'Serial Number ' + @in_vchSerialNumber;
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID
					,@in_vchWhID = @v_vchWarehouse
					,@in_vchDevice = @in_vchDeviceID
					,@in_vchUserID = @in_vchUserID
					,@in_vchLogType = 'PROCESS'
					,@in_vchProcess = @v_vchObjName
					,@in_dtProcessDateTime = @v_dtProcessDateTime
					,@in_vchData1 = @v_vchProcessData1
					,@in_vchData2 = @v_vchProcessData2
					,@in_vchData3 = @in_vchCountID
					,@in_vchData4 = @v_vchProcessData4
					,@in_vchErrorCode = @out_vchErrorCode
					,@in_vchMessage = @out_vchErrorMsg
		END

	END TRY		
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF (ISNULL(@out_vchErrorCode,'') = '' OR ISNULL(@out_vchErrorCode,'') = '0')
			BEGIN
				SET @out_vchErrorCode = ERROR_NUMBER();
				SET @out_vchErrorMsg = ERROR_MESSAGE();
			END
			
		SET @v_dtProcessDateTime = GETDATE();	
		SET @v_vchProcessData1 = 'Count ID ' + @in_vchCountID;
		SET @v_vchProcessData2 = 'Serial Number ' + @in_vchSerialNumber;

		EXEC usp_LogManager
			 @in_vchApplicationID = @in_vchApplicationID
			,@in_vchWhID = @v_vchWarehouse
			,@in_vchDevice = @in_vchDeviceID
			,@in_vchUserID = @in_vchUserID
			,@in_vchLogType = 'PROCESS'
			,@in_vchProcess = @v_vchObjName
			,@in_dtProcessDateTime = @v_dtProcessDateTime
			,@in_vchData1 = @v_vchProcessData1
			,@in_vchData2 = @v_vchProcessData2
			,@in_vchData3 = @in_vchCountID
			,@in_vchData4 = @v_vchProcessData4
			,@in_vchErrorCode = @out_vchErrorCode
			,@in_vchMessage = @out_vchErrorMsg
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_count_serial_number]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_count_serial_number]
(
	@in_vchApplicationID  VARCHAR(40) = NULL,
	@in_vchWhMasterID	  VARCHAR(40) = NULL,
	@in_vchCountID		  VARCHAR(50) = NULL,
	@in_vchSerialNumber	  NVARCHAR(100)= NULL,
	@in_vchLocalID		  VARCHAR(40) = NULL,
	@in_vchUserID		  NVARCHAR(25) = NULL,
	@in_vchDeviceID		  NVARCHAR(50) = NULL,
	@out_vchErrorCode	  VARCHAR(50)  = NULL OUTPUT,
	@out_vchErrorMsg	  NVARCHAR(500)= NULL OUTPUT,
	@out_vchNextScreen	  NVARCHAR(50) = NULL OUTPUT
)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans			BIT = 0,
			@v_vchObjName				NVARCHAR(30) = 'usp_wms_count_serial_number',
			@v_vchApplicationName		NVARCHAR(50),
			@v_vchProcessData1			NVARCHAR(1000),
			@v_vchProcessData2			NVARCHAR(1000),
			@v_vchProcessData3			NVARCHAR(1000),
			@v_vchProcessData4			NVARCHAR(1000),
			@v_dtProcessDateTime		DATETIME,
			@v_vchWarehouse				NVARCHAR(50),
			@v_vchAttributeGroupID		VARCHAR(40) = NULL,
			@v_vchCountMasterID			VARCHAR(40) = NULL,
			@v_vchCountDetailID			VARCHAR(40) = NULL,
			@v_vchInventoryID			VARCHAR(40) = NULL,
			@v_vchLocationID			VARCHAR(40) = NULL,
			@v_vchPalentLPN				NVARCHAR(25) = NULL,
			@v_vchLPN					NVARCHAR(25) = NULL,
			@v_vchWhItemMasterID		VARCHAR(40)  = NULL,
			@v_vchInvStatus				NVARCHAR(50) = NULL,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_vchExpiryDate			NVARCHAR(100) = NULL,
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL,
			@v_vchRuleAdjustInv			NVARCHAR(3) = NULL,
			@v_fltStockQty				FLOAT,
			@v_vchCountQty				FLOAT,
			@v_vchTransactionID			VARCHAR(40) = NULL
	
	BEGIN TRY
		EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 
		SELECT @v_vchRuleAdjustInv = value FROM t_wms_rule WHERE rule_code = 'RULE_ADJUST_INVENT' AND is_active = 'YES'
		SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
		
		--Get Count Master ID
		SELECT @v_vchCountMasterID = count_master_id
		FROM t_wms_count_plan_master 
		WHERE wh_master_id = @in_vchWhMasterID
		AND count_id = @in_vchCountID

		SELECT @v_vchCountDetailID   = count_plan_detail_id
			, @v_vchLocationID		= location_id
			, @v_vchPalentLPN		= parent_lpn
			, @v_vchLPN				= lpn
			, @v_vchWhItemMasterID	= wh_item_master_id
			, @v_vchInvStatus		= inv_status
			, @v_vchLotNumber		= lot
			, @v_vchExpiryDate		= expiry_date
			, @v_vchAttribute1		= attribute1
			, @v_vchAttribute2		= attribute2
			, @v_vchAttribute3		= attribute3
			, @v_vchAttribute4		= attribute4
			, @v_vchAttribute5	    = attribute5
		FROM t_wms_count_plan_detail
		WHERE count_master_id = @v_vchCountMasterID
		AND serial_number = @in_vchSerialNumber

		IF (ISNULL(@v_vchCountDetailID,'') = '')
			BEGIN
				--Get data in inventory
				SELECT @v_vchInventoryID = inventory_id
					, @v_vchLocationID		= location_id
					, @v_vchPalentLPN		= parent_lpn
					, @v_vchLPN				= lpn
					, @v_vchWhItemMasterID	= wh_item_master_id
					, @v_vchInvStatus		= inv_status
					, @v_vchLotNumber		= lot_number
					, @v_vchExpiryDate		= expiry_date
					, @v_vchAttribute1		= attribute1
					, @v_vchAttribute2		= attribute2
					, @v_vchAttribute3		= attribute3
					, @v_vchAttribute4		= attribute4
					, @v_vchAttribute5	    = attribute5
				FROM v_wms_inventory_data_by_serial_mini
				WHERE wh_master_id = @in_vchWhMasterID
				AND serial_number = @in_vchSerialNumber

				IF (ISNULL(@v_vchInventoryID,'') = '')
					BEGIN
						SELECT TOP 1 @v_vchTransactionID	= tran_id
							 , @v_vchLocationID		= loc.location_id	
							 , @v_vchPalentLPN		= ISNULL(NULLIF(tranLog.parent_lpn,''),tranLog.after_parent_lpn) 	
							 , @v_vchLPN			= ISNULL(NULLIF(tranLog.lpn,''),tranLog.after_lpn) 			
							 , @v_vchWhItemMasterID	= whItem.wh_item_master_id				
							 , @v_vchInvStatus		= ISNULL(NULLIF(tranLog.status,''),tranLog.after_status)					
							 , @v_vchLotNumber		= ISNULL(NULLIF(tranLog.lot_number,''),tranLog.after_lot_number)		
							 , @v_vchExpiryDate		= ISNULL(NULLIF(tranLog.expiry_date,''),tranLog.after_expiry_date)
							 , @v_vchAttribute1		= ISNULL(NULLIF(tranLog.attribute1,''),tranLog.after_attribute1)  					
							 , @v_vchAttribute2		= ISNULL(NULLIF(tranLog.attribute2,''),tranLog.after_attribute2)  					
							 , @v_vchAttribute3		= ISNULL(NULLIF(tranLog.attribute3,''),tranLog.after_attribute3)  					
							 , @v_vchAttribute4		= ISNULL(NULLIF(tranLog.attribute4,''),tranLog.after_attribute4)  					
							 , @v_vchAttribute5	    = ISNULL(NULLIF(tranLog.attribute5,''),tranLog.after_attribute5)  					
						FROM t_com_tran_log tranLog
						LEFT JOIN t_wms_wh wh ON tranLog.to_warehouse = wh.wh_id
						LEFT JOIN t_wms_owner own ON tranLog.to_owner = own.owner_code
						LEFT JOIN t_wms_item item ON tranLog.item_number = item.item_number AND own.owner_id = item.owner_id
						LEFT JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
						LEFT JOIN t_wms_location loc ON ISNULL(NULLIF(tranLog.location,''),tranLog.to_location) = loc.location
						WHERE tranLog.tran_type IN ('IO_RECEIPT','INV_ADJUST')
						AND tranLog.serial_number = @in_vchSerialNumber
						
						IF ISNULL(@v_vchTransactionID,'') = ''
							BEGIN
								SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST-IN-PLAN'
								SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,@in_vchLocalID,@in_vchSerialNumber,'@param2','@param3','@param4','@param5')
								GOTO WRITE_PROC;
							END
					END
				
				SET @v_vchInvStatus = 'Available'
			END

		BEGIN TRANSACTION;
		SET @v_vchBeginTrans = 1

		-----------------------------------------------
		--INSERT COUNT RECONCILE
		-----------------------------------------------
		IF NOT EXISTS(SELECT count_reconcile_id FROM t_wms_count_reconcile WHERE count_master_id = @v_vchCountMasterID AND serial_number = @in_vchSerialNumber)
			BEGIN
				INSERT INTO [dbo].[t_wms_count_reconcile]
						([count_reconcile_id]
						,[count_master_id]
						,[location_id]
						,[wh_item_master_id]
						,[inv_status]
						,[parent_lpn]
						,[lpn]
						,[lot]
						,[expiry_date]
						,[serial_number]
						,[expect_qty]
						,[count_qty]
						,[adjusted_qty]
						,[adjust_by]
						,[create_date]
						,[create_by]
						,[attribute1]
						,[attribute2]
						,[attribute3]
						,[attribute4]
						,[attribute5]
						,[device])
					VALUES
						(NEWID()
						,@v_vchCountMasterID
						,@v_vchLocationID
						,@v_vchWhItemMasterID
						,@v_vchInvStatus
						,NULLIF(@v_vchPalentLPN,'')		
						,NULLIF(@v_vchLPN,'')			
						,NULLIF(@v_vchLotNumber,'')		
						,NULLIF(@v_vchExpiryDate,'')    
						,NULLIF(@in_vchSerialNumber,'') 
						,1
						,1
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN 1 ELSE NULL END)
						,(CASE @v_vchRuleAdjustInv WHEN 'YES' THEN @in_vchUserID ELSE NULL END)
						,GETDATE()
						,@in_vchUserID
						,NULLIF(@v_vchAttribute1,'')
						,NULLIF(@v_vchAttribute2,'')
						,NULLIF(@v_vchAttribute3,'')
						,NULLIF(@v_vchAttribute4,'')
						,NULLIF(@v_vchAttribute5,'')
						,'Count SN')

				-- Update Count Detail
				UPDATE t_wms_count_plan_detail SET count_qty = ISNULL(count_qty,0) + 1 WHERE count_plan_detail_id = @v_vchCountDetailID

				--Update Count Status
				UPDATE t_wms_count_plan_master SET count_status = 'IN PROCESS' WHERE count_master_id = @v_vchCountMasterID
			END

		COMMIT TRANSACTION;

		SELECT @v_fltStockQty = SUM(stock_qty)
			  ,@v_vchCountQty = SUM(count_qty)
		FROM t_wms_count_plan_detail WHERE count_master_id = @v_vchCountMasterID

		SELECT @v_fltStockQty AS stock_qty, @v_vchCountQty AS count_qty

		-----------------------------------------------
		--Next Screen
		-----------------------------------------------
		IF @v_fltStockQty <> @v_vchCountQty
			BEGIN
				SET @out_vchErrorCode = 'INFO-DETAIL-QTY-COUNT';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_fltStockQty,@v_vchCountQty,'@param3','@param4','@param5')
			END
		ELSE
			BEGIN
				SET @out_vchErrorCode = 'INFO-COUNT-SUCCESS';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(select dbo.usf_get_locale_id(@in_vchUserID)),@v_fltStockQty,@v_vchCountQty,'@param3','@param4','@param5')

			END
		SET @out_vchNextScreen = 'FINAL_SCREEN'
		RETURN;

		------------------------------------------------
		--Write process log
		------------------------------------------------
		BEGIN
			WRITE_PROC:							
				IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
					ROLLBACK TRANSACTION;
		
				SET @v_dtProcessDateTime = GETDATE();	
				SET @v_vchProcessData1 = 'Count ID ' + @in_vchCountID;
				SET @v_vchProcessData2 = 'Serial Number ' + @in_vchSerialNumber;
				
				EXEC usp_LogManager
					@in_vchApplicationID = @in_vchApplicationID
					,@in_vchWhID = @v_vchWarehouse
					,@in_vchDevice = @in_vchDeviceID
					,@in_vchUserID = @in_vchUserID
					,@in_vchLogType = 'PROCESS'
					,@in_vchProcess = @v_vchObjName
					,@in_dtProcessDateTime = @v_dtProcessDateTime
					,@in_vchData1 = @v_vchProcessData1
					,@in_vchData2 = @v_vchProcessData2
					,@in_vchData3 = @in_vchCountID
					,@in_vchData4 = @v_vchProcessData4
					,@in_vchErrorCode = @out_vchErrorCode
					,@in_vchMessage = @out_vchErrorMsg
		END

	END TRY		
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF (ISNULL(@out_vchErrorCode,'') = '' OR ISNULL(@out_vchErrorCode,'') = '0')
			BEGIN
				SET @out_vchErrorCode = ERROR_NUMBER();
				SET @out_vchErrorMsg = ERROR_MESSAGE();
			END
			
		SET @v_dtProcessDateTime = GETDATE();	
		SET @v_vchProcessData1 = 'Count ID ' + @in_vchCountID;
		SET @v_vchProcessData2 = 'Serial Number ' + @in_vchSerialNumber;

		EXEC usp_LogManager
			 @in_vchApplicationID = @in_vchApplicationID
			,@in_vchWhID = @v_vchWarehouse
			,@in_vchDevice = @in_vchDeviceID
			,@in_vchUserID = @in_vchUserID
			,@in_vchLogType = 'PROCESS'
			,@in_vchProcess = @v_vchObjName
			,@in_dtProcessDateTime = @v_dtProcessDateTime
			,@in_vchData1 = @v_vchProcessData1
			,@in_vchData2 = @v_vchProcessData2
			,@in_vchData3 = @in_vchCountID
			,@in_vchData4 = @v_vchProcessData4
			,@in_vchErrorCode = @out_vchErrorCode
			,@in_vchMessage = @out_vchErrorMsg
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_create_count_plan_external]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_create_count_plan_external]
(
	@in_vchOwner			NVARCHAR(50) = NULL,
	@in_vchCustomerCode		NVARCHAR(50),
	@in_dtCountPlanDate		DATETIME,
	@in_vchItemCategory		NVARCHAR(MAX),
	@in_vchUserID			NVARCHAR(25),
	@out_vchCountID			NVARCHAR(40)  OUTPUT,
	@out_ErrorCode			NVARCHAR(100) OUTPUT,
	@out_ErrorMessage		NVARCHAR(500) OUTPUT
)
AS
BEGIN
	--For IOS Create Count Plan
	SET NOCOUNT ON;	
	DECLARE @v_vchWhMasterID		VARCHAR(40) = NULL,
			@v_vchCountMasterID		VARCHAR(40) = NULL,
			@v_vchOwnerID			VARCHAR(40) = NULL,
			@v_vchCustomerID		VARCHAR(40) = NULL,
			@v_vchCustomerName		NVARCHAR(200)=NULL,
			@v_vchItemDescription	NVARCHAR(200)=NULL,
			@v_vchLocationID		NVARCHAR(40)= NULL,
			@v_vchLocation			NVARCHAR(50)= NULL,
			--For generate count id
			@v_vchPrefix			NVARCHAR(8),
			@v_vchLastOrderNumber	NVARCHAR(50)
BEGIN TRY
	--Get Warehouse
	SELECT TOP 1 @v_vchWhMasterID = wh_master_id FROM t_wms_wh WHERE is_active = 'YES'

	--Get Owner
	IF ISNULL(@in_vchOwner,'') <> ''
		BEGIN
			SELECT @v_vchOwnerID = owner_id FROM t_wms_owner WHERE owner_code = @in_vchOwner AND is_active = 'YES'
		END
	ELSE
		BEGIN
			SELECT TOP 1  @v_vchOwnerID = owner_id FROM t_wms_owner WHERE is_active = 'YES'
		END

	--Get Customer
	SELECT @v_vchCustomerID = customer_id
		, @v_vchCustomerName = customer_name
	FROM t_wms_customer 
	WHERE customer_code = @in_vchCustomerCode 
	AND is_active = 'YES'
	AND owner_id = @v_vchOwnerID

	IF (ISNULL(@v_vchCustomerID,'') = '')
		BEGIN
			SET @out_ErrorCode = 'INFO-CUSTOMER-IS-EMPTY';
			SELECT @out_ErrorMessage =  'Customer cannot be empty.'
			RETURN
		END


	-- Get Customer Location
	SELECT @v_vchLocationID = location_id FROM t_wms_customer_location WHERE customer_id = @v_vchCustomerID AND is_active = 'YES'

	--------------------------------------------------------------
	---- Generate Count ID
	--SET @v_vchPrefix = CONVERT(VARCHAR(8),GETDATE(),112);
	--SELECT @v_vchLastOrderNumber = count_id
	--FROM t_wms_count_plan_master_external
	--WHERE count_id LIKE @v_vchPrefix +'%'
	--SELECT @out_vchCountID = dbo.usf_generate_running_number(@v_vchLastOrderNumber,3,@v_vchPrefix)
	
	SELECT @out_vchCountID =  dbo.usf_count_external_generate_running_order()
	------------------------------------------------------------

	BEGIN
		BEGIN TRANSACTION;
			--Insert Master
			SET @v_vchCountMasterID = NEWID()
			INSERT INTO [dbo].[t_wms_count_plan_master_external]
					   ([count_master_id]
					   ,[wh_master_id]
					   ,[count_id]
					   ,[owner_code]
					   ,[count_status]
					   ,[priority]
					   ,[description]
					   ,[count_generate_method]
					   ,[count_plan_type]
					   ,[customer_id]
					   ,[customer_code]
					   ,[customer_name]
					   ,[count_plan_date]
					   ,[create_date]
					   ,[create_by])
				 VALUES
					   (@v_vchCountMasterID
					   ,@v_vchWhMasterID
					   ,@out_vchCountID
					   ,@in_vchOwner
					   ,'OPEN'
					   ,NULL
					   ,NULL
					   ,'MANUAL'
					   ,'CYCLE'
					   ,@v_vchCustomerID
					   ,@in_vchCustomerCode
					   ,@v_vchCustomerName
					   ,@in_dtCountPlanDate
					   ,GETDATE()
					   ,@in_vchUserID)

			--Insert Detail
			INSERT INTO [dbo].[t_wms_count_plan_detail_external]
					   ([count_plan_detail_id]
					   ,[count_master_id]
					   ,[location_id]
					   ,[location]
					   ,[wh_item_master_id]
					   ,[item_number]
					   ,[item_description]
					   ,[days_to_expire]
					   ,[inv_status]
					   ,[parent_lpn]
					   ,[lpn]
					   ,[lot_number]
					   ,[expiry_date]
					   ,[serial_number]
					   ,[attribute1]
					   ,[attribute2]
					   ,[attribute3]
					   ,[attribute4]
					   ,[attribute5]
					   ,[stock_qty]
					   ,[count_plan_date]
					   ,[delivery_date]
					   ,[outbound_order_number]
					   ,[item_category]
					   ,[item_category_description]
					   ,[create_by]
					   ,[create_date])
					SELECT NEWID()
						,@v_vchCountMasterID
						,inv.location_id
						,inv.location
						,inv.wh_item_master_id
						,inv.item_number
						,inv.description		--Item description
						,inv.days_to_expire
						,inv.inv_status
						,inv.parent_lpn
						,inv.lpn
						,inv.lot_number
						,inv.expiry_date
						,inv.serial_number
						,inv.attribute1
						,inv.attribute2
						,inv.attribute3
						,inv.attribute4
						,inv.attribute5
						,inv.quantity
						,@in_dtCountPlanDate
						,obDV.delivery_date
						,obDV.delivery_number
						,inv.item_category
						,inv.item_category_desc
						,@in_vchUserID
						,GETDATE()
					FROM v_wms_inventory_for_count_external inv
					LEFT JOIN t_wms_outbound_delivery obDV ON inv.serial_number = obDV.serial_number
					WHERE inv.wh_master_id = @v_vchWhMasterID
					AND inv.location_id = @v_vchLocationID
					AND inv.customer_id = @v_vchCustomerID
					AND inv.inv_status = 'Consignment'
					AND inv.item_category IN (SELECT part FROM SplitString(@in_vchItemCategory, ',')) --@in_vchItemCategory
					AND (CASE ISNULL(@v_vchOwnerID,'') WHEN '' THEN '' ELSE inv.owner_id END) = (CASE ISNULL(@v_vchOwnerID,'') WHEN '' THEN '' ELSE @v_vchOwnerID END)

			SET @out_ErrorCode = '0';
			SET @out_ErrorMessage = 'SAVE SUCCESS';

		COMMIT TRANSACTION;
	END
END TRY
BEGIN CATCH

		SET @out_ErrorCode = ERROR_NUMBER();
		SET @out_ErrorMessage = ERROR_MESSAGE();
		IF (@@TRANCOUNT > 0)
			ROLLBACK TRANSACTION;
END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_customer_user]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_customer_user]
(
	@in_vchUsername  NVARCHAR(50) = NULL
 
)
AS
BEGIN 
		SELECT DISTINCT		a.name, a.first_name, a.last_name, a.password, e.customer_code, e.customer_name, 
							e.addr_line_1, e.addr_line_2, e.addr_line_3, e.city, e.province, e.phone, e.fax, 
							e.email, e.contact, e.memo, b.location, 
							f.item_category, f.description, l.owner_code
		FROM				t_wms_owner_user AS k 
		INNER JOIN t_wms_owner AS l ON k.owner_id = l.owner_id 
		INNER JOIN t_wms_item AS h 
		INNER JOIN t_wms_wh_item AS i ON h.item_master_id = i.item_master_id 
		INNER JOIN t_wms_inventory AS j ON i.wh_item_master_id = j.wh_item_master_id 
		INNER JOIN t_wms_location AS b 
		INNER JOIN t_wms_customer_location AS c ON b.location_id = c.location_id 
		INNER JOIN t_wms_customer_user AS d 
		INNER JOIN t_wms_customer AS e ON d.customer_id = e.customer_id ON c.customer_id = e.customer_id 
		INNER JOIN v_wms_user AS a ON a.user_id = d.user_id ON j.location_id = c.location_id 
		INNER JOIN t_wms_category AS f ON h.category_id = f.category_id ON k.user_id = a.user_id
		WHERE				a.name = @in_vchUsername

		 
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_dashboard_item_movement_viewer]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_dashboard_item_movement_viewer]
	@in_vchWhMasterID		UNIQUEIDENTIFIER
AS
BEGIN
	--แสดงข้อมูลการเคลื่อนไหวที่ 90 วัน
	DECLARE @v_dtMovement DATE
	SET @v_dtMovement =  DATEADD(day,-90,GETDATE())
	
	DECLARE @t_tblData TABLE
	(
		[c_count]			[INT] NOT NULL, 
		[item_master_id]	[UNIQUEIDENTIFIER] NOT NULL,
		[item_number]		[NVARCHAR](50) NOT NULL,
		[trans_date]		[DATETIME] NOT NULL,
		[movement_type]		[VARCHAR](20) NOT NULL
	)
	IF @in_vchWhMasterID IS NULL
		BEGIN
			INSERT INTO @t_tblData
			(
				 [c_count]		 
				,[item_master_id]
				,[item_number]	
				,[trans_date]	
				,[movement_type]
			)
			SELECT TOP 10 COUNT(trans_id)	AS c_count
				,item_master_id
				,item_number	
				,MAX(trans_date)	AS trans_date
				,'INBOUND'			AS movement_type
			FROM t_wms_dashboard_trans_in 
			WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
			AND trans_type = 'RECEIVING' 
			GROUP BY item_master_id
				,item_number 
			ORDER BY COUNT(trans_id) DESC ,trans_date DESC
	
			INSERT INTO @t_tblData
			(
				 [c_count]		
				,[item_master_id]
				,[item_number]	
				,[trans_date]	
				,[movement_type]
			)
			SELECT TOP 10 COUNT(trans_id)	AS c_count
				,item_master_id
				,item_number	
				,MAX(trans_date)	AS trans_date
				,'OUTBOUND'			AS movement_type
			FROM t_wms_dashboard_trans_out 
			WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
			AND trans_type = 'PICK'
			GROUP BY item_master_id
				,item_number 
			ORDER BY COUNT(trans_id) DESC ,trans_date DESC
		END
	ELSE
		BEGIN
			INSERT INTO @t_tblData
			(
				 [c_count]			
				,[item_master_id]
				,[item_number]	
				,[trans_date]	
				,[movement_type]
			)
			SELECT TOP 10 COUNT(trans_id)	AS c_count
				,item_master_id
				,item_number	
				,MAX(trans_date)	AS trans_date
				,'INBOUND'			AS movement_type
			FROM t_wms_dashboard_trans_in 
			WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
			AND trans_type = 'RECEIVING'
			AND wh_master_id = @in_vchWhMasterID
			GROUP BY item_master_id
				,item_number 
			ORDER BY COUNT(trans_id) DESC ,trans_date DESC
	
			INSERT INTO @t_tblData
			(
				 [c_count]			
				,[item_master_id]
				,[item_number]	
				,[trans_date]	
				,[movement_type]
			)
			SELECT TOP 10 COUNT(trans_id)	AS c_count
				,item_master_id
				,item_number	
				,MAX(trans_date)	AS trans_date
				,'OUTBOUND'			AS movement_type
			FROM t_wms_dashboard_trans_out 
			WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
			AND trans_type = 'PICK'
			AND wh_master_id = @in_vchWhMasterID
			GROUP BY item_master_id
				,item_number 
			ORDER BY COUNT(trans_id) DESC ,trans_date DESC
		END
   
	SELECT [c_count]
		,[item_master_id]
		,[item_number]
		,[movement_type]
	FROM @t_tblData
END

/*

EXEC usp_wms_dashboard_item_movement_viewer	@in_vchWhMasterID = 'DE233E82-1F9A-47B9-A85B-F5541F9F28EA'

*/
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_dashboard_location_movement_viewer]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_dashboard_location_movement_viewer]
	@in_vchWhMasterID		UNIQUEIDENTIFIER
AS
BEGIN
	--แสดงข้อมูลการเคลื่อนไหวที่ 90 วัน
	DECLARE @v_dtMovement DATE
	SET @v_dtMovement =  DATEADD(day,-90,GETDATE())

	IF @in_vchWhMasterID IS NULL
		BEGIN
			;WITH tData AS
			(
				SELECT trans_id
					,trans_date 
					,location_id
					,location
				FROM t_wms_dashboard_trans_in
				WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
				AND trans_type IN ( 'RECEIVING','MOVE')
				UNION ALL
				SELECT trans_id
					,trans_date 
					,location_id
					,location
				FROM t_wms_dashboard_trans_out
				WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
				AND trans_type IN ( 'PICK','MOVE')
			)
			SELECT TOP 10 COUNT(tData.trans_id)	AS c_count 
				,tData.location_id	
				,tData.location
				,MAX(tData.trans_date)	AS trans_date 
			FROM tData
			LEFT JOIN t_wms_location loc ON tData.location_id = loc.location_id
			WHERE loc.loc_type NOT IN ('RSTG','STG')
			GROUP BY tData.location
				,tData.location_id
			ORDER BY COUNT(trans_id) DESC, trans_date DESC
		END
	ELSE
		BEGIN
			;WITH tData AS
			(
				SELECT trans_id
					,trans_date 
					,location_id
					,location
				FROM t_wms_dashboard_trans_in
				WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
				AND trans_type IN ( 'RECEIVING','MOVE')
				AND wh_master_id = @in_vchWhMasterID
				UNION ALL
				SELECT trans_id
					,trans_date 
					,location_id
					,location
				FROM t_wms_dashboard_trans_out
				WHERE CONVERT(DATE,trans_date) >= @v_dtMovement 
				AND trans_type IN ( 'PICK','MOVE')
				AND wh_master_id = @in_vchWhMasterID
			)
			SELECT TOP 10 COUNT(tData.trans_id)	AS c_count
				,tData.location_id	
				,tData.location
				,MAX(tData.trans_date)	AS trans_date 
			FROM tData
			LEFT JOIN t_wms_location loc ON tData.location_id = loc.location_id
			WHERE loc.loc_type NOT IN ('RSTG','STG')
			GROUP BY tData.location
				,tData.location_id
			ORDER BY COUNT(trans_id) DESC, trans_date DESC
		END
END

/*

EXEC usp_wms_dashboard_location_movement_viewer	@in_vchWhMasterID = 'DE233E82-1F9A-47B9-A85B-F5541F9F28EA'

*/
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_dashboard_transaction]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_dashboard_transaction]
	@in_vchProcess		 VARCHAR(6),			--IN, OUT, IN_OUT
	@in_vchTransType	 VARCHAR(30),		--[OUT]>>PICK, SHIP, MOVE, CHANGE_STATUS,ADJUST ---- [IN]>>RECEIVING, CLOSE, MOVE, CHANGE_STATUS,ADJUST
	@in_vchWhMasterID	 UNIQUEIDENTIFIER, 
	@in_vchOwnerID		 UNIQUEIDENTIFIER,
	@in_vchOwnerCode	 NVARCHAR(40) = NULL,
	@in_vchLocationID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchItemMasterID	 UNIQUEIDENTIFIER = NULL, 
	@in_vchInvStatusID	 UNIQUEIDENTIFIER = NULL,
	@in_vchToWhMasterID	 UNIQUEIDENTIFIER = NULL, --For move, Change status
	@in_vchToLocationID	 UNIQUEIDENTIFIER = NULL, --For move, Change status
	@in_vchToInvStatusID UNIQUEIDENTIFIER = NULL, --For move, Change status
	@in_fltQuantity		 FLOAT = 0,
	@in_vchUserID		 VARCHAR(25)
AS
BEGIN
	SET NOCOUNT ON; 
	DECLARE @v_vchWarehouse		NVARCHAR(25) = NULL
	DECLARE @v_vchItemNumber	NVARCHAR(50) = NULL
	DECLARE @v_vchItemDesc		NVARCHAR(200) = NULL
	DECLARE @v_vchCategoryID	UNIQUEIDENTIFIER = NULL
	DECLARE @v_vchItemCategory	NVARCHAR(50) = NULL
	DECLARE @v_vchInvStatus		NVARCHAR(50) = NULL
	DECLARE @v_vchLocation		NVARCHAR(50) = NULL

	DELETE t_wms_dashboard_trans_in WHERE CONVERT(DATE,trans_date) <= CONVERT(DATE,DATEADD(DAY,-120,GETDATE()))
	DELETE t_wms_dashboard_trans_out WHERE CONVERT(DATE,trans_date) <= CONVERT(DATE,DATEADD(DAY,-120,GETDATE()))

	SELECT TOP 1 @v_vchItemNumber = item.item_number
		, @v_vchItemDesc = item.description
		, @v_vchCategoryID = cate.category_id
		, @v_vchItemCategory = cate.item_category
	FROM t_wms_item item
	INNER JOIN t_wms_category cate ON item.category_id = cate.category_id
	WHERE item.item_master_id = @in_vchItemMasterID
	AND item.owner_id = @in_vchOwnerID
	SELECT TOP 1 @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID
	SELECT TOP 1 @v_vchInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchInvStatusID
	SELECT TOP 1 @v_vchLocation = location FROM t_wms_location WHERE location_id = @in_vchLocationID
	--Insert
	IF @in_vchProcess = 'IN'
	BEGIN
		INSERT INTO [dbo].[t_wms_dashboard_trans_in]
					([trans_id]
					,[trans_date]
					,[trans_type]
					,[wh_master_id]
					,[wh_id]
					,[owner_id]
					,[owner_code]
					,[location_id]
					,[location]
					,[item_master_id]
					,[item_number]
					,[item_description]
					,[category_id]
					,[item_category]
					,[quantity]
					,[inventory_status_id]
					,[inv_status]
					,[create_by]
					,[create_date])
				VALUES
					(NEWID()
					,GETDATE()
					,@in_vchTransType
					,@in_vchWhMasterID
					,@v_vchWarehouse
					,@in_vchOwnerID
					,@in_vchOwnerCode
					,@in_vchLocationID
					,@v_vchLocation
					,@in_vchItemMasterID
					,@v_vchItemNumber
					,@v_vchItemDesc
					,@v_vchCategoryID
					,@v_vchItemCategory
					,@in_fltQuantity
					,@in_vchInvStatusID
					,@v_vchInvStatus
					,@in_vchUserID
					,GETDATE())
	END 
	
	IF @in_vchProcess = 'OUT'
	BEGIN
		INSERT INTO [dbo].[t_wms_dashboard_trans_out]
					([trans_id]
					,[trans_date]
					,[trans_type]
					,[wh_master_id]
					,[wh_id]
					,[owner_id]
					,[owner_code]
					,[location_id]
					,[location]
					,[item_master_id]
					,[item_number]
					,[item_description]
					,[category_id]
					,[item_category]
					,[quantity]
					,[inventory_status_id]
					,[inv_status]
					,[create_by]
					,[create_date])
				VALUES
					(NEWID()
					,GETDATE()
					,@in_vchTransType
					,@in_vchWhMasterID
					,@v_vchWarehouse
					,@in_vchOwnerID
					,@in_vchOwnerCode
					,@in_vchLocationID
					,@v_vchLocation
					,@in_vchItemMasterID
					,@v_vchItemNumber
					,@v_vchItemDesc
					,@v_vchCategoryID
					,@v_vchItemCategory
					,@in_fltQuantity
					,@in_vchInvStatusID
					,@v_vchInvStatus
					,@in_vchUserID
					,GETDATE())
	END

	IF @in_vchProcess = 'OUT_IN'
	BEGIN
		DECLARE @v_vchToWarehouse NVARCHAR(50) = NULL
		DECLARE @v_vchToInvStatus NVARCHAR(50) = NULL
		DECLARE @v_vchToLocation  NVARCHAR(50) = NULL

		SELECT TOP 1 @v_vchToWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchToWhMasterID
		SELECT TOP 1 @v_vchToInvStatus = inv_status FROM t_wms_inventory_status WHERE inventory_status_id = @in_vchToInvStatusID
		SELECT TOP 1 @v_vchToLocation = location FROM t_wms_location WHERE location_id = @in_vchToLocationID
		--Change Status : from is out, to is in
		--Change Location : from is out, to is in
		INSERT INTO [dbo].[t_wms_dashboard_trans_out]
					([trans_id]
					,[trans_date]
					,[trans_type]
					,[wh_master_id]
					,[wh_id]
					,[owner_id]
					,[owner_code]
					,[location_id]
					,[location]
					,[item_master_id]
					,[item_number]
					,[item_description]
					,[category_id]
					,[item_category]
					,[quantity]
					,[inventory_status_id]
					,[inv_status]
					,[create_by]
					,[create_date])
				VALUES
					(NEWID()
					,GETDATE()
					,@in_vchTransType
					,@in_vchWhMasterID
					,@v_vchWarehouse
					,@in_vchOwnerID
					,@in_vchOwnerCode
					,@in_vchLocationID
					,@v_vchLocation
					,@in_vchItemMasterID
					,@v_vchItemNumber
					,@v_vchItemDesc
					,@v_vchCategoryID
					,@v_vchItemCategory
					,@in_fltQuantity
					,@in_vchInvStatusID
					,@v_vchInvStatus
					,@in_vchUserID
					,GETDATE())

		INSERT INTO [dbo].[t_wms_dashboard_trans_in]
					([trans_id]
					,[trans_date]
					,[trans_type]
					,[wh_master_id]
					,[wh_id]
					,[owner_id]
					,[owner_code]
					,[location_id]
					,[location]
					,[item_master_id]
					,[item_number]
					,[item_description]
					,[category_id]
					,[item_category]
					,[quantity]
					,[inventory_status_id]
					,[inv_status]
					,[create_by]
					,[create_date])
				VALUES
					(NEWID()
					,GETDATE()
					,@in_vchTransType
					,@in_vchToWhMasterID
					,@v_vchToWarehouse
					,@in_vchOwnerID
					,@in_vchOwnerCode
					,@in_vchToLocationID
					,@v_vchToLocation
					,@in_vchItemMasterID
					,@v_vchItemNumber
					,@v_vchItemDesc
					,@v_vchCategoryID
					,@v_vchItemCategory
					,@in_fltQuantity
					,@in_vchToInvStatusID
					,@v_vchToInvStatus
					,@in_vchUserID
					,GETDATE())
	END
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_inbound_receipt_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_inbound_receipt_rfid]
(
	@in_vchApplicationID	  VARCHAR(40)   = NULL,	
	@in_vchWhMasterID		  UNIQUEIDENTIFIER = NULL,
	@in_vchInboundMasterID	  UNIQUEIDENTIFIER = NULL,
	@in_vchOwnerID			  UNIQUEIDENTIFIER = NULL,
	@in_vchReceiveLocation	  NVARCHAR(50)  = NULL,
	@in_vchUserID			  NVARCHAR(25)  = NULL,
	@in_vchDeviceID			  NVARCHAR(50)  = NULL,
	@in_vchLocalID			  VARCHAR(40)   = NULL,
	@out_vchErrorCode		  VARCHAR(50)   = NULL OUTPUT,
	@out_vchErrorMsg		  NVARCHAR(500) = NULL OUTPUT,
	@out_vchNextScreen		  NVARCHAR(50)  = NULL OUTPUT
)
AS
BEGIN
SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans			BIT = 0,
			@v_vchObjName				NVARCHAR(30) = 'usp_wms_inbound_receipt_rfid',
			@v_vchApplicationName		NVARCHAR(50) = NULL,
			@v_vchProcessData1			NVARCHAR(1000) = NULL,
			@v_vchProcessData2			NVARCHAR(1000) = NULL,
			@v_vchProcessData3			NVARCHAR(1000) = NULL,
			@v_vchProcessData4			NVARCHAR(1000) = NULL,
			@v_dtProcessDateTime		DATETIME = NULL,

			@v_vchWarehouse				NVARCHAR(50) = NULL,
			@v_vchInboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchInboundOrderNumber	NVARCHAR(50) = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchReceiptHeaderID		UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptNumber			NVARCHAR(50) = NULL,
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwner					NVARCHAR(50) = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL,
			
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchParentLPN				NVARCHAR(25) = NULL,
			@v_vchLPN					NVARCHAR(25) = NULL,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_vchExpiryDate			NVARCHAR(100) = NULL,
			@v_vchSerialNumber			NVARCHAR(100) = NULL,
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL,
			@v_vchItemUomID				UNIQUEIDENTIFIER = NULL,
			@v_vchUomPrompt				NVARCHAR(40) = NULL,
			@v_vchInbound_rfid			UNIQUEIDENTIFIER = NULL,
			@v_vchDefaultItemStatus		NVARCHAR(40) = NULL,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_dtReceiveDate			DATE = NULL,
			@v_vchLotControl			NVARCHAR(5) = NULL,
			@v_vchExpiryDateControl		NVARCHAR(5) = NULL,
			@v_vchSerialControl			NVARCHAR(5) = NULL,
			@v_vchAttribute1Control		NVARCHAR(5) = NULL,
			@v_vchAttribute2Control		NVARCHAR(5) = NULL,
			@v_vchAttribute3Control		NVARCHAR(5) = NULL,
			@v_vchAttribute4Control		NVARCHAR(5) = NULL,
			@v_vchAttribute5Control		NVARCHAR(5) = NULL,
			@v_vchMixItem				NVARCHAR(3) = NULL,
			@v_vchMixLot				NVARCHAR(3) = NULL,
			@v_vchMixOwner				NVARCHAR(3) = NULL,
			@v_vchMixExpiryDate			NVARCHAR(3) = NULL,
			@v_vchLPNControl			NVARCHAR(5) = NULL,
			@v_vchMixStatus				NVARCHAR(3) = NULL,
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
			@v_fltInvQty				FLOAT = NULL,
			@v_fltAfterInvQuantity		FLOAT = NULL,
			@v_fltPlanQty				FLOAT = 0,
			@v_fltReceivedQty			FLOAT = 0,
			@v_fltOverReceiptPercentage FLOAT = 0,
			@v_vchOverReceiptAllower	NVARCHAR(3) = NULL

BEGIN TRY
	SET @v_dtProcessDateTime = GETDATE();
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 
	SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
	SELECT @v_vchOwner = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'
	
	--GET RSTG Location
	SELECT @v_vchLocationID = location_id 
		,@v_vchMixItem = mix_items
		,@v_vchMixLot = mix_lot
		,@v_vchMixExpiryDate = mix_expiry_dates
		,@v_vchMixOwner = mix_owners
		,@v_vchLPNControl = lpn_controlled 
		,@v_vchMixStatus = mix_status
	FROM t_wms_location 
	WHERE location = @in_vchReceiveLocation 
	AND wh_master_id = @in_vchWhMasterID 
	AND is_active = 'YES'

	IF @v_vchLocationID is null
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIT'
			SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	IF @v_vchLPNControl = 'NO'
		BEGIN
			SET @v_vchLPN = NULL
		END
	
	SELECT @v_vchInboundOrderNumber = inbound_order_number FROM t_wms_inbound_master WHERE wh_master_id = @in_vchWhMasterID AND inbound_order_master_id = @in_vchInboundMasterID

BEGIN TRANSACTION
SET @v_vchBeginTrans = 1

	--Get Receipt ID/Number
	SELECT @v_vchReceiptHeaderID = receipt_header_id 
		,@v_vchReceiptNumber = receipt_number 
	FROM t_wms_receipt_header 
	WHERE inbound_order_master_id = @in_vchInboundMasterID
	AND receipt_status <> 'CLOSE'
	IF (@v_vchReceiptHeaderID is null) 
		BEGIN
			EXEC usp_generate_receipt_number @in_vchUserID				= @in_vchUserID
											, @in_vchWhMasterID		  	= @in_vchWhMasterID
											, @in_vchInboundMasterID	= @in_vchInboundMasterID
											, @out_vchReceiptHeaderID	= @v_vchReceiptHeaderID OUTPUT
											, @out_vchReceiptNumber	  	= @v_vchReceiptNumber OUTPUT 
		END
	
	--Get Inbound RFID
	DECLARE InboundRFID_CURSOR CURSOR FOR
		SELECT ib.inbound_rfid_id
			, ib.inbound_order_number
			, ib.wh_item_master_id
			, item.item_master_id
			, ib.order_type
			, item.item_number
			, ib.parent_lpn
			, ib.lpn
			, ib.lot_number
			, ib.expiry_date
			, ib.serial_number
			, ib.attribute1
			, ib.attribute2
			, ib.attribute3
			, ib.attribute4
			, ib.attribute5
			, ib.item_uom_id
			, uom.uom_prompt
			, ib.default_item_status
			, ib.inbound_order_detail_id
			, ib.line_number
			, item.lot_control
			, item.expiry_date_control
			, item.sn_control
			, item.attribute1_control
			, item.attribute2_control
			, item.attribute3_control
			, item.attribute4_control
			, item.attribute5_control
		FROM t_wms_inbound_rfid ib
		LEFT JOIN t_wms_wh_item whItem ON ib.wh_item_master_id = whItem.wh_item_master_id
		LEFT JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
		LEFT JOIN t_wms_item_uom uom ON ib.item_uom_id = uom.item_uom_id
		WHERE ib.wh_master_id = @in_vchWhMasterID
		AND ib.inbound_order_master_id = @in_vchInboundMasterID
		AND ib.processing_status = 'READ'
		ORDER BY ib.create_date
	OPEN InboundRFID_CURSOR
	
	FETCH NEXT FROM InboundRFID_CURSOR INTO @v_vchInbound_rfid, @v_vchInboundOrderNumber, @v_vchWhItemMasterID,@v_vchItemMasterID, @v_vchOrderType, @v_vchItemNumber, @v_vchParentLPN, @v_vchLPN
			, @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5	
			, @v_vchItemUomID, @v_vchUomPrompt, @v_vchDefaultItemStatus, @v_vchInboundDetailID, @v_vchLineNumber, @v_vchLotControl, @v_vchExpiryDateControl
			, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control
	
	WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @v_vchLotControl = 'NONE'
				BEGIN
					SET @v_vchLotNumber = NULL
				END
			IF @v_vchExpiryDateControl = 'NONE'
				BEGIN
					SET @v_vchExpiryDate = NULL
				END
			IF @v_vchSerialControl = 'NONE'
				BEGIN
					SET @v_vchSerialNumber = NULL
				END
			IF @v_vchAttribute1Control = 'NONE'
				BEGIN
					SET @v_vchAttribute1 = NULL
				END
			IF @v_vchAttribute2Control = 'NONE'
				BEGIN
					SET @v_vchAttribute2 = NULL
				END
			IF @v_vchAttribute3Control = 'NONE'
				BEGIN
					SET @v_vchAttribute3 = NULL
				END
			IF @v_vchAttribute4Control = 'NONE'
				BEGIN
					SET @v_vchAttribute4 = NULL
				END
			IF @v_vchAttribute5Control = 'NONE'
				BEGIN
					SET @v_vchAttribute5 = NULL
				END

			-- Get inventory status id from inventory
			SET @v_vchInvStatusID = NULL;
			SELECT  @v_vchInvStatusID = inventory_status_id 
			FROM t_wms_inventory_status
			WHERE inv_status = @v_vchDefaultItemStatus	
			AND is_active = 'YES'

			-------------------------------------------------
			--Check Quantity Order = Quantity Receive
			-------------------------------------------------
			SET @v_fltPlanQty = 0;
			SET @v_fltReceivedQty = 0;
			SET @v_fltOverReceiptPercentage = 0;
			SELECT @v_fltPlanQty = SUM(quantity_order)
				,@v_fltReceivedQty = SUM(quantity_receive)
				,@v_fltOverReceiptPercentage = SUM(Percentage)
			FROM (SELECT DISTINCT ibDT.quantity_order
					,ibDT.quantity_receive
					,(SELECT quantity_order * ((CASE ibDT.over_receipt_allowed WHEN 'YES' THEN ISNULL(over_receipt_percentage,0) ELSE 0 END)/100)
						FROM t_wms_inbound_detail _data2 
						WHERE _data2.inbound_order_detail_id = ibDT.inbound_order_detail_id ) AS Percentage 
					FROM t_wms_inbound_detail ibDT
					WHERE ibDT.inbound_order_master_id = @in_vchInboundMasterID
					AND ibDT.wh_item_master_id = @v_vchWhItemMasterID
					AND ISNULL(ibDT.lot_number,'') = ISNULL(@v_vchLotNumber,'') 
					AND ISNULL(ibDT.[expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
				) AS Data

			IF ((@v_fltReceivedQty + 1) > (@v_fltPlanQty + @v_fltOverReceiptPercentage))
				BEGIN
					SET @out_vchErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
					SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
					GOTO WRITE_PROC;
				ENd

			--Set Receive Date 
			IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_RECEIVE_DATE' AND is_active = 'YES') = 'NO') OR @v_dtReceiveDate IS NULL
				BEGIN
					SET @v_dtReceiveDate = CONVERT(DATE,GETDATE())
				END
		 
			--Manage Inventory
			EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
										 ,@in_vchWhMasterID			= @in_vchWhMasterID
										 ,@in_vchWhID				= @v_vchWarehouse
										 ,@in_vchOwnerID			= @in_vchOwnerID
										 ,@in_vchInventoryType		= 'INVENTORY'
										 ,@in_vchLocationID			= @v_vchLocationID
										 ,@in_vchParentLPN			= @v_vchParentLPN
										 ,@in_vchLPN				= @v_vchLPN
										 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
										 ,@in_vchItemMasterID		= @v_vchItemMasterID
										 ,@in_vchItemNumber			= @v_vchItemNumber
										 ,@in_fltQuantity			= 1
										 ,@in_fltQtyAllocate		= 0
										 ,@in_fltQtyIncoming		= 0
										 ,@in_vchPrimaryItemUomID	= @v_vchItemUomID
										 ,@in_vchInvStatusID		= @v_vchInvStatusID
										 ,@in_vchLotNumber			= @v_vchLotNumber
										 ,@in_vchExpiryDate			= @v_vchExpiryDate
										 ,@in_vchSerialNumber		= @v_vchSerialNumber
										 ,@in_vchAttribute1			= @v_vchAttribute1
										 ,@in_vchAttribute2			= @v_vchAttribute2
										 ,@in_vchAttribute3			= @v_vchAttribute3
										 ,@in_vchAttribute4			= @v_vchAttribute4
										 ,@in_vchAttribute5			= @v_vchAttribute5
										 ,@in_dReceiveDate			= @v_dtReceiveDate
										 ,@in_dtMFGDate				= NULL
										 ,@in_vchDeviceID			= @in_vchDeviceID
										 ,@in_vchUserID				= @in_vchUserID
										 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
										 ,@out_ErrorCode			= @out_vchErrorCode OUTPUT
										 ,@out_ErrorMessage			= @out_vchErrorMsg OUTPUT

			IF (@out_vchErrorCode <> '0')
				GOTO WRITE_PROC;

			--Update Qty Inbound Detail
			UPDATE t_wms_inbound_detail set quantity_receive = quantity_receive + 1 
				,item_status = 'RECEIVING'
			WHERE inbound_order_detail_id = @v_vchInboundDetailID
		
			-- Insert Receipt ID
			INSERT INTO [dbo].[t_wms_receipt_detail]
				   ([receipt_detail_id]
				   ,[receipt_header_id]
				   ,[inbound_order_detail_id]
				   ,[quantity_received]
				   ,[item_uom_id]
				   ,[receipt_item_status]
				   ,[location_received]
				   ,[lpn]
				   ,[parent_lpn]
				   ,[lot_number]
				   ,[expiry_date]
				   ,[serial_number]
				   ,[attribute1]
				   ,[attribute2]
				   ,[attribute3]
				   ,[attribute4]
				   ,[attribute5]
				   ,[posting_date]
				   ,[create_date]
				   ,[create_by])
			 VALUES
				   (NEWID()
				   ,@v_vchReceiptHeaderID
				   ,@v_vchInboundDetailID
				   ,1
				   ,@v_vchItemUomID
				   ,@v_vchDefaultItemStatus
				   ,@in_vchReceiveLocation
				   ,@v_vchLPN
				   ,@v_vchParentLPN
				   ,@v_vchLotNumber
				   ,@v_vchExpiryDate
				   ,@v_vchSerialNumber
				   ,@v_vchAttribute1
				   ,@v_vchAttribute2
				   ,@v_vchAttribute3
				   ,@v_vchAttribute4
				   ,@v_vchAttribute5
				   ,NULL
				   ,GETDATE()
				   ,@in_vchUserID)
		
			-- Update Master Order Status 
			UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE wh_master_id = @in_vchWhMasterID and inbound_order_master_id = @in_vchInboundMasterID

			--Insert Log
		INSERT INTO t_com_tran_log
			(app_id
			, tran_type
			, sub_tran_type
			, [app_name]
			, [description]
			, start_tran_datetime
			, end_tran_datetime
			, to_warehouse
			, to_location
			, to_owner
			, item_number
			, quantity
			, quantity_uom
			, after_quantity
			, after_quantity_uom
			, after_lot_number
			, after_expiry_date
			, serial_number
			, [user_id] 
			, after_parent_lpn
			, after_lpn
			, after_status
			, order_number
			, line_number

			-- Add for attibute
			, [after_attribute1]
			, [after_attribute2]
			, [after_attribute3]
			, [after_attribute4]
			, [after_attribute5] 
			, receive_date
			, mfg_date
			, device
			, create_by)
		VALUES
			( @in_vchApplicationID
			, 'IO_RECEIPT'
			, 'RECEIPT_RFID'
			, @v_vchApplicationName
			, 'Receive Item by RFID'
			, @v_dtProcessDateTime
			, GETDATE()
			, @v_vchWarehouse
			, @in_vchReceiveLocation
			, @v_vchOwner
			, @v_vchItemNumber
			, 1
			, @v_vchUomPrompt
			, @v_fltAfterInvQuantity
			, @v_vchUomPrompt
			, @v_vchLotNumber
			, @v_vchExpiryDate
			, @v_vchSerialNumber
			, @in_vchUserID
			, @v_vchParentLPN
			, @v_vchLPN
			, @v_vchDefaultItemStatus
			, @v_vchInboundOrderNumber
			, @v_vchLineNumber

			-- Add for attibute
			, @v_vchAttribute1
			, @v_vchAttribute2
			, @v_vchAttribute3
			, @v_vchAttribute4
			, @v_vchAttribute5
			, @v_dtReceiveDate
			, NULL
			, @in_vchDeviceID
			, @in_vchUserID)

			 
			--Update Status inbound rfid
			UPDATE t_wms_inbound_rfid SET processing_status = 'COMPLETE' WHERE inbound_rfid_id = @v_vchInbound_rfid
			
			BEGIN --Clear Value
				SET @v_vchInbound_rfid		 = NULL;
				SET @v_vchInboundOrderNumber = NULL;
				SET @v_vchWhItemMasterID	 = NULL;
				SET @v_vchItemMasterID	 = NULL;
				SET @v_vchOrderType			 = NULL;
				SET @v_vchItemNumber		 = NULL;
				SET @v_vchParentLPN			 = NULL;
				SET @v_vchLPN				 = NULL;
				SET @v_vchLotNumber			 = NULL;
				SET @v_vchExpiryDate		 = NULL;
				SET @v_vchSerialNumber		 = NULL;
				SET @v_vchAttribute1		 = NULL;
				SET @v_vchAttribute2		 = NULL;
				SET @v_vchAttribute3		 = NULL;
				SET @v_vchAttribute4		 = NULL;
				SET @v_vchAttribute5		 = NULL;
				SET @v_vchItemUomID			 = NULL;
				SET @v_vchUomPrompt			 = NULL;
				SET @v_vchDefaultItemStatus	 = NULL;
				SET @v_vchInboundDetailID	 = NULL;
				SET @v_vchLineNumber		 = NULL;
				SET @v_vchLotControl		 = NULL;
				SET @v_vchExpiryDateControl	 = NULL;
				SET @v_vchSerialControl		 = NULL;
				SET @v_vchAttribute1Control	 = NULL;
				SET @v_vchAttribute2Control	 = NULL;
				SET @v_vchAttribute3Control	 = NULL;
				SET @v_vchAttribute4Control	 = NULL;
				SET @v_vchAttribute5Control	 = NULL;
			END

			FETCH NEXT FROM InboundRFID_CURSOR INTO @v_vchInbound_rfid, @v_vchInboundOrderNumber, @v_vchWhItemMasterID,@v_vchItemMasterID, @v_vchOrderType, @v_vchItemNumber, @v_vchParentLPN, @v_vchLPN
							, @v_vchLotNumber, @v_vchExpiryDate, @v_vchSerialNumber, @v_vchAttribute1, @v_vchAttribute2, @v_vchAttribute3, @v_vchAttribute4, @v_vchAttribute5	
							, @v_vchItemUomID, @v_vchUomPrompt, @v_vchDefaultItemStatus, @v_vchInboundDetailID, @v_vchLineNumber, @v_vchLotControl, @v_vchExpiryDateControl
							, @v_vchSerialControl, @v_vchAttribute1Control, @v_vchAttribute2Control, @v_vchAttribute3Control, @v_vchAttribute4Control, @v_vchAttribute5Control

		END      
	CLOSE InboundRFID_CURSOR                  	
	DEALLOCATE InboundRFID_CURSOR
	
	COMMIT TRANSACTION;
	DECLARE @v_nCountMiss	INT = 0,
			@v_nCountCMP	INT = 0,
			@v_nCountPlan	INT = 0

	-- Count Plan
	SELECT @v_nCountPlan = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @in_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID

	-- Count Complete
	SELECT @v_nCountCMP = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @in_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID
	AND processing_status = 'COMPLETE'

	-- Count pending,read,error
	SELECT @v_nCountMiss = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @in_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID
	AND processing_status <> 'COMPLETE'

	IF EXISTS (SELECT inbound_rfid_id FROM t_wms_inbound_rfid 
				WHERE wh_master_id = @in_vchWhMasterID 
				AND inbound_order_master_id = @in_vchInboundMasterID
				AND processing_status <> 'COMPLETE')
		BEGIN
			--Missing 
			SET @out_vchNextScreen = 'ITEM_RFID'
			SET @out_vchErrorCode = 999;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'TRANSACTION_INPROCESS',@in_vchLocalID,CONVERT(VARCHAR,@v_nCountPlan),CONVERT(VARCHAR,@v_nCountMiss),CONVERT(VARCHAR,@v_nCountCMP),'@param4','@param5')
		END
	ELSE
		BEGIN
			SET @out_vchNextScreen = 'INBOUND_ORDER'
			--Complete
			SET @out_vchErrorCode = 0;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INBOUND-COMPLETED',@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END

	
	-----------------------------------------------
	-- ÊÓËÃÑºáÊ´§·ÕèË¹éÒ¨Í
	-----------------------------------------------
	SELECT @v_nCountPlan AS qty_plan
		,@v_nCountCMP	 AS qty_complete
		,@v_nCountMiss	 AS qty_miss

	RETURN;

	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			IF CURSOR_STATUS('global','InboundRFID_CURSOR') >= -1
			BEGIN
				CLOSE InboundRFID_CURSOR
				DEALLOCATE InboundRFID_CURSOR
			END
			
			UPDATE t_wms_inbound_rfid SET processing_status = 'ERROR' WHERE inbound_rfid_id = @v_vchInbound_rfid AND processing_status <> 'COMPLETE'
			SET @v_dtProcessDateTime = GETDATE();	
			SET @v_vchProcessData2 = 'Receipt Number ' + @v_vchReceiptNumber;
			SET @v_vchProcessData3 = 'Item Number ' + @v_vchItemNumber;
			SET @v_vchProcessData4 = 'Serial Number ' + @v_vchSerialNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchInboundOrderNumber,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
	END

	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		IF CURSOR_STATUS('global','InboundRFID_CURSOR')>=-1
			BEGIN
				CLOSE InboundRFID_CURSOR
				DEALLOCATE InboundRFID_CURSOR
			END

		UPDATE t_wms_inbound_rfid SET processing_status = 'ERROR' WHERE inbound_rfid_id = @v_vchInbound_rfid AND processing_status <> 'COMPLETE'
		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMsg = ERROR_MESSAGE(); 
		SET @v_dtProcessDateTime = GETDATE();	
		SET @v_vchProcessData2 = 'Receipt Number ' + @v_vchReceiptNumber;
		SET @v_vchProcessData3 = 'Item Number ' + @v_vchItemNumber;
		SET @v_vchProcessData4 = 'Serial Number ' + @v_vchSerialNumber;

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchInboundOrderNumber,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_inbound_receipt_serial_number]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_wms_inbound_receipt_serial_number]
(
	@in_vchApplicationID	  VARCHAR(40)   = NULL,	
	@in_vchWhMasterID		  UNIQUEIDENTIFIER = NULL,
	@in_vchOrderNumber		  NVARCHAR(50)  = NULL,
	@in_vchOwnerID			  UNIQUEIDENTIFIER = NULL,
	@in_vchLocation			  NVARCHAR(50)  = NULL,
	@in_vchItemNumber		  NVARCHAR(50)  = NULL,
	@in_vchSerialNumber		  NVARCHAR(50)  = NULL,
	@in_vchUserID			  NVARCHAR(25)  = NULL,
	@in_vchDeviceID			  NVARCHAR(50)  = NULL,
	@in_vchLocalID			  VARCHAR(40)   = NULL,
	@out_vchErrorCode		  VARCHAR(50)   = NULL OUTPUT,
	@out_vchErrorMsg		  NVARCHAR(500) = NULL OUTPUT,
	@out_vchNextScreen		  NVARCHAR(50)  = NULL OUTPUT
)
AS
BEGIN
SET NOCOUNT ON;
	DECLARE @v_vchBeginTrans			BIT = 0, 
			@v_vchObjName				NVARCHAR(30) = 'usp_wms_inbound_receipt_serial_number',
			@v_vchApplicationName		NVARCHAR(50)   = NULL,
			@v_vchProcessData1			NVARCHAR(1000) = NULL,
			@v_vchProcessData2			NVARCHAR(1000) = NULL,
			@v_vchProcessData3			NVARCHAR(1000) = NULL,
			@v_vchProcessData4			NVARCHAR(1000) = NULL,
			@v_dtProcessDateTime		DATETIME = NULL,

			@v_vchWarehouse				NVARCHAR(50) = NULL,
			@v_vchInboundMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchInboundDetailID		UNIQUEIDENTIFIER = NULL,
			@v_vchOrderType				NVARCHAR(30) = NULL,
			@v_vchReceiptHeaderID		UNIQUEIDENTIFIER = NULL,
			@v_vchReceiptNumber			NVARCHAR(50) = NULL,
			@v_vchLocationID			UNIQUEIDENTIFIER = NULL,
			@v_vchOwner					NVARCHAR(50) = NULL,
			@v_vchLineNumber			NVARCHAR(10) = NULL,
			
			@v_vchWhItemMasterID		UNIQUEIDENTIFIER = NULL,
			@v_vchItemMasterID			UNIQUEIDENTIFIER = NULL,
			@v_vchItemNumber			NVARCHAR(50) = NULL,
			@v_vchParentLPN				NVARCHAR(25) = NULL,
			@v_vchLPN					NVARCHAR(25) = NULL,
			@v_vchLotNumber				NVARCHAR(100) = NULL,
			@v_vchExpiryDate			NVARCHAR(100) = NULL,
			@v_vchSerialNumber			NVARCHAR(100) = NULL,
			@v_vchAttribute1			NVARCHAR(100) = NULL,
			@v_vchAttribute2			NVARCHAR(100) = NULL,
			@v_vchAttribute3			NVARCHAR(100) = NULL,
			@v_vchAttribute4			NVARCHAR(100) = NULL,
			@v_vchAttribute5			NVARCHAR(100) = NULL,
			@v_vchItemUomID				UNIQUEIDENTIFIER = NULL,
			@v_vchUomPrompt				NVARCHAR(40) = NULL,
			@v_vchInbound_rfid			UNIQUEIDENTIFIER = NULL,
			@v_vchDefaultItemStatus		NVARCHAR(40) = NULL,
			@v_vchInvStatusID			UNIQUEIDENTIFIER = NULL,
			@v_dtReceiveDate			DATE,
			@v_vchLotControl			NVARCHAR(5) = NULL,
			@v_vchExpiryDateControl		NVARCHAR(5) = NULL,
			@v_vchSerialControl			NVARCHAR(5) = NULL,
			@v_vchAttribute1Control		NVARCHAR(5) = NULL,
			@v_vchAttribute2Control		NVARCHAR(5) = NULL,
			@v_vchAttribute3Control		NVARCHAR(5) = NULL,
			@v_vchAttribute4Control		NVARCHAR(5) = NULL,
			@v_vchAttribute5Control		NVARCHAR(5) = NULL,
			@v_vchMixItem				NVARCHAR(3) = NULL,
			@v_vchMixLot				NVARCHAR(3) = NULL,
			@v_vchMixOwner				NVARCHAR(3) = NULL,
			@v_vchMixExpiryDate			NVARCHAR(3) = NULL,
			@v_vchLPNControl			NVARCHAR(5) = NULL,
			@v_vchMixStatus				NVARCHAR(3) = NULL,
			@v_vchInventoryID			UNIQUEIDENTIFIER = NULL,
			@v_vchAttributeGroupID		UNIQUEIDENTIFIER = NULL,
			@v_fltInvQty				FLOAT = NULL,
			@v_fltAfterInvQuantity		FLOAT = 0,
			@v_fltPlanQty				FLOAT = 0,
			@v_fltReceivedQty			FLOAT = 0,
			@v_fltOverReceiptPercentage FLOAT = 0,
			@v_vchOverReceiptAllower	NVARCHAR(3) = NULL

BEGIN TRY	
	SET @v_dtProcessDateTime = GETDATE();
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT 
	SELECT @v_vchWarehouse = wh_id FROM t_wms_wh WHERE wh_master_id = @in_vchWhMasterID AND is_active = 'YES'
	SELECT @v_vchOwner = owner_code FROM t_wms_owner WHERE owner_id = @in_vchOwnerID AND is_active = 'YES'
	
	--GET Inbound Master ID
	SELECT @v_vchInboundMasterID = inbound_order_master_id FROM t_wms_inbound_master 
	WHERE inbound_order_number = @in_vchOrderNumber 
	AND wh_master_id = @in_vchWhMasterID

	--GET RSTG Location
	SELECT @v_vchLocationID = location_id 
		,@v_vchMixItem = mix_items
		,@v_vchMixLot = mix_lot
		,@v_vchMixExpiryDate = mix_expiry_dates
		,@v_vchMixOwner = mix_owners
		,@v_vchLPNControl = lpn_controlled 
		,@v_vchMixStatus = mix_status
	FROM t_wms_location 
	WHERE location = @in_vchLocation 
	AND wh_master_id = @in_vchWhMasterID 
	AND is_active = 'YES'

	IF @v_vchLocationID IS NULL
		BEGIN
			SET @out_vchErrorCode = 'INFO-LOCATION-NOT-EXIT'
			SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
			RETURN;
		END
	
	BEGIN TRANSACTION
	SET @v_vchBeginTrans = 1

		--Get Receipt ID/Number
		SELECT @v_vchReceiptHeaderID = receipt_header_id 
			,@v_vchReceiptNumber = receipt_number 
		FROM t_wms_receipt_header 
		WHERE inbound_order_master_id = @v_vchInboundMasterID
		AND receipt_status <> 'CLOSE'
		IF (@v_vchReceiptHeaderID IS NULL) 
			BEGIN
				EXEC usp_generate_receipt_number @in_vchUserID				= @in_vchUserID
												, @in_vchWhMasterID		  	= @in_vchWhMasterID
												, @in_vchInboundMasterID	= @v_vchInboundMasterID
												, @out_vchReceiptHeaderID	= @v_vchReceiptHeaderID OUTPUT
												, @out_vchReceiptNumber	  	= @v_vchReceiptNumber OUTPUT 
			END

		--Get Inbound RFID
		SELECT @v_vchInbound_rfid =  ib.inbound_rfid_id
			, @v_vchWhItemMasterID = ib.wh_item_master_id
			, @v_vchItemMasterID = item.item_master_id
			, @v_vchOrderType = ib.order_type
			, @v_vchItemNumber = item.item_number
			, @v_vchParentLPN = ib.parent_lpn
			, @v_vchLPN = ib.lpn
			, @v_vchLotNumber = ib.lot_number
			, @v_vchExpiryDate = ib.expiry_date
			, @v_vchSerialNumber = ib.serial_number
			, @v_vchAttribute1 = ib.attribute1
			, @v_vchAttribute2 = ib.attribute2
			, @v_vchAttribute3 = ib.attribute3
			, @v_vchAttribute4 = ib.attribute4
			, @v_vchAttribute5	= ib.attribute5
			, @v_vchItemUomID = ib.item_uom_id
			, @v_vchUomPrompt = uom.uom_prompt
			, @v_vchDefaultItemStatus = ib.default_item_status
			, @v_vchInboundDetailID = ib.inbound_order_detail_id
			, @v_vchLineNumber = ib.line_number
			, @v_vchLotControl = item.lot_control
			, @v_vchExpiryDateControl = item.expiry_date_control
			, @v_vchSerialControl = item.sn_control
			, @v_vchAttribute1Control = item.attribute1_control
			, @v_vchAttribute2Control = item.attribute2_control
			, @v_vchAttribute3Control = item.attribute3_control
			, @v_vchAttribute4Control = item.attribute4_control
			, @v_vchAttribute5Control = item.attribute5_control
		FROM t_wms_inbound_rfid ib
		INNER JOIN t_wms_wh_item whItem ON ib.wh_item_master_id = whItem.wh_item_master_id
		INNER JOIN t_wms_item item on whItem.item_master_id = item.item_master_id
		INNER JOIN t_wms_item_uom uom ON ib.item_uom_id = uom.item_uom_id
		WHERE ib.wh_master_id = @in_vchWhMasterID
		AND ib.inbound_order_master_id = @v_vchInboundMasterID
		AND item.item_number = @in_vchItemNumber
		AND ib.serial_number = @in_vchSerialNumber
		AND ib.processing_status = 'READ-SN'
	
		IF @v_vchInbound_rfid IS NULL
			BEGIN
				SET @out_vchErrorCode = 'INFO-NOT-FOUND-DATA';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			END
			 
		IF @v_vchLPNControl = 'NO'
			BEGIN
				SET @v_vchLPN = NULL
			END
		IF @v_vchLotControl = 'NONE'
			BEGIN
				SET @v_vchLotNumber = NULL
			END
		IF @v_vchExpiryDateControl = 'NONE'
			BEGIN
				SET @v_vchExpiryDate = NULL
			END
		IF @v_vchSerialControl = 'NONE'
			BEGIN
				SET @v_vchSerialNumber = NULL
			END
		IF @v_vchAttribute1Control = 'NONE'
			BEGIN
				SET @v_vchAttribute1 = NULL
			END
		IF @v_vchAttribute2Control = 'NONE'
			BEGIN
				SET @v_vchAttribute2 = NULL
			END
		IF @v_vchAttribute3Control = 'NONE'
			BEGIN
				SET @v_vchAttribute3 = NULL
			END
		IF @v_vchAttribute4Control = 'NONE'
			BEGIN
				SET @v_vchAttribute4 = NULL
			END
		IF @v_vchAttribute5Control = 'NONE'
			BEGIN
				SET @v_vchAttribute5 = NULL
			END

		-- Get inventory status id from inventory
		SET @v_vchInvStatusID = NULL;
		SELECT  @v_vchInvStatusID = inventory_status_id 
		FROM t_wms_inventory_status
		WHERE inv_status = @v_vchDefaultItemStatus	
		AND is_active = 'YES' 

		-------------------------------------------------
		--Check Quantity Order = Quantity Receive
		-------------------------------------------------
		SET @v_fltPlanQty = 0;
		SET @v_fltReceivedQty = 0;
		SET @v_fltOverReceiptPercentage = 0;
		SELECT @v_fltPlanQty = SUM(quantity_order)
			,@v_fltReceivedQty = SUM(quantity_receive)
			,@v_fltOverReceiptPercentage = SUM(Percentage)
		FROM (SELECT DISTINCT ibDT.quantity_order
				,ibDT.quantity_receive
				,(SELECT quantity_order * ((CASE ibDT.over_receipt_allowed WHEN 'YES' THEN ISNULL(over_receipt_percentage,0) ELSE 0 END)/100)
					FROM t_wms_inbound_detail _data2 
					WHERE _data2.inbound_order_detail_id = ibDT.inbound_order_detail_id ) AS Percentage 
				FROM t_wms_inbound_detail ibDT
				WHERE ibDT.inbound_order_master_id = @v_vchInboundMasterID
				AND ibDT.wh_item_master_id = @v_vchWhItemMasterID
				AND ISNULL(ibDT.lot_number,'') = ISNULL(@v_vchLotNumber,'') 
				AND ISNULL(ibDT.[expiry_date],'') = ISNULL(@v_vchExpiryDate,'')
			) AS Data

		IF ((@v_fltReceivedQty + 1) > (@v_fltPlanQty + @v_fltOverReceiptPercentage))
			BEGIN
				SET @out_vchErrorCode = 'QTY_MORE_THAN_PLAN_QTY';
				SELECT @out_vchErrorMsg =  dbo.usf_get_resouce_value(@in_vchApplicationID,@out_vchErrorCode,(SELECT dbo.usf_get_locale_id(@in_vchUserID)),'@param1','@param2','@param3','@param4','@param5')
				GOTO WRITE_PROC;
			ENd
 
		--Set Receive Date 
		IF ((SELECT TOP 1 value FROM t_wms_rule WHERE rule_code = 'RULE_OVERRIDE_RECEIVE_DATE' AND is_active = 'YES') = 'NO') OR @v_dtReceiveDate IS NULL
			BEGIN
				SET @v_dtReceiveDate = CONVERT(DATE,GETDATE())
			END
		 
		--Manage Inventory
		EXEC usp_manage_inventory_control @in_vchApplicationID	= @in_vchApplicationID
									 ,@in_vchWhMasterID			= @in_vchWhMasterID
									 ,@in_vchWhID				= @v_vchWarehouse
									 ,@in_vchOwnerID			= @in_vchOwnerID
									 ,@in_vchInventoryType		= 'INVENTORY'
									 ,@in_vchLocationID			= @v_vchLocationID
									 ,@in_vchParentLPN			= @v_vchParentLPN
									 ,@in_vchLPN				= @v_vchLPN
									 ,@in_vchWhItemMasterID		= @v_vchWhItemMasterID
									 ,@in_vchItemMasterID		= @v_vchItemMasterID
									 ,@in_vchItemNumber			= @in_vchItemNumber
									 ,@in_fltQuantity			= 1
									 ,@in_fltQtyAllocate		= 0
									 ,@in_fltQtyIncoming		= 0
									 ,@in_vchPrimaryItemUomID	= @v_vchItemUomID
									 ,@in_vchInvStatusID		= @v_vchInvStatusID
									 ,@in_vchLotNumber			= @v_vchLotNumber
									 ,@in_vchExpiryDate			= @v_vchExpiryDate
									 ,@in_vchSerialNumber		= @v_vchSerialNumber
									 ,@in_vchAttribute1			= @v_vchAttribute1
									 ,@in_vchAttribute2			= @v_vchAttribute2
									 ,@in_vchAttribute3			= @v_vchAttribute3
									 ,@in_vchAttribute4			= @v_vchAttribute4
									 ,@in_vchAttribute5			= @v_vchAttribute5
									 ,@in_dReceiveDate			= @v_dtReceiveDate
									 ,@in_dtMFGDate				= NULL
									 ,@in_vchDeviceID			= @in_vchDeviceID
									 ,@in_vchUserID				= @in_vchUserID
									 ,@out_fltAfterInvQuantity	= @v_fltAfterInvQuantity OUTPUT
									 ,@out_ErrorCode			= @out_vchErrorCode OUTPUT
									 ,@out_ErrorMessage			= @out_vchErrorMsg OUTPUT

		IF (@out_vchErrorCode <> '0')
			GOTO WRITE_PROC;

		--Update Qty Inbound Detail
		UPDATE t_wms_inbound_detail set quantity_receive = quantity_receive + 1 
			,item_status = 'RECEIVING'
		WHERE inbound_order_detail_id = @v_vchInboundDetailID
		
		-- Insert Receipt ID
		INSERT INTO [dbo].[t_wms_receipt_detail]
				([receipt_detail_id]
				,[receipt_header_id]
				,[inbound_order_detail_id]
				,[quantity_received]
				,[item_uom_id]
				,[receipt_item_status]
				,[location_received]
				,[lpn]
				,[parent_lpn]
				,[lot_number]
				,[expiry_date]
				,[serial_number]
				,[attribute1]
				,[attribute2]
				,[attribute3]
				,[attribute4]
				,[attribute5]
				,[posting_date]
				,[create_date]
				,[create_by])
			VALUES
				(NEWID()
				,@v_vchReceiptHeaderID
				,@v_vchInboundDetailID
				,1
				,@v_vchItemUomID
				,@v_vchDefaultItemStatus
				,@in_vchLocation
				,@v_vchLPN
				,@v_vchParentLPN
				,@v_vchLotNumber
				,@v_vchExpiryDate
				,@v_vchSerialNumber
				,@v_vchAttribute1
				,@v_vchAttribute2
				,@v_vchAttribute3
				,@v_vchAttribute4
				,@v_vchAttribute5
				,NULL
				,GETDATE()
				,@in_vchUserID)
		
		-- Update Master Order Status 
		UPDATE t_wms_inbound_master SET order_status = 'RECEIVING' WHERE wh_master_id = @in_vchWhMasterID AND inbound_order_master_id = @v_vchInboundMasterID

		-----------------------------------------------------------
		-- Write Transaction Log Receipt Detail
		-----------------------------------------------------------
		INSERT INTO t_com_tran_log
			(app_id
			, tran_type
			, sub_tran_type
			, [app_name]
			, [description]
			, start_tran_datetime
			, end_tran_datetime
			, to_warehouse
			, to_location
			, to_owner
			, item_number
			, quantity
			, quantity_uom
			, after_quantity
			, after_quantity_uom
			, after_lot_number
			, after_expiry_date
			, serial_number
			, [user_id] 
			, after_parent_lpn
			, after_lpn
			, after_status
			, order_number
			, line_number

			-- Add for attibute
			, [after_attribute1]
			, [after_attribute2]
			, [after_attribute3]
			, [after_attribute4]
			, [after_attribute5] 
			, receive_date
			, mfg_date
			, device
			, create_by)
		VALUES
			( @in_vchApplicationID
			, 'IO_RECEIPT'
			, 'RECEIPT_SN'
			, @v_vchApplicationName
			, 'Receive Item by Serial Number'
			, @v_dtProcessDateTime
			, GETDATE()
			, @v_vchWarehouse
			, @in_vchLocation
			, @v_vchOwner
			, @in_vchItemNumber
			, 1
			, @v_vchUomPrompt
			, @v_fltAfterInvQuantity
			, @v_vchUomPrompt
			, @v_vchLotNumber
			, @v_vchExpiryDate
			, @in_vchSerialNumber
			, @in_vchUserID
			, @v_vchParentLPN
			, @v_vchLPN
			, @v_vchDefaultItemStatus
			, @in_vchOrderNumber
			, @v_vchLineNumber

			-- Add for attibute
			, @v_vchAttribute1
			, @v_vchAttribute2
			, @v_vchAttribute3
			, @v_vchAttribute4
			, @v_vchAttribute5
			, @v_dtReceiveDate
			, NULL
			, @in_vchDeviceID
			, @in_vchUserID)

		--Update Status inbound rfid
		UPDATE t_wms_inbound_rfid SET processing_status = 'COMPLETE' WHERE inbound_rfid_id = @v_vchInbound_rfid
	
	COMMIT TRANSACTION;
	DECLARE @v_nCountMiss	INT = 0,
			@v_nCountCMP	INT = 0,
			@v_nCountPlan	INT = 0

	-- Count Plan
	SELECT @v_nCountPlan = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @v_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID

	-- Count Complete
	SELECT @v_nCountCMP = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @v_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND processing_status = 'COMPLETE'

	-- Count pending,read,error
	SELECT @v_nCountMiss = COUNT(inbound_rfid_id) FROM t_wms_inbound_rfid 
	WHERE inbound_order_master_id = @v_vchInboundMasterID 
	AND wh_master_id = @in_vchWhMasterID
	AND wh_item_master_id = @v_vchWhItemMasterID
	AND processing_status <> 'COMPLETE'


	IF EXISTS (SELECT inbound_rfid_id FROM t_wms_inbound_rfid 
				WHERE wh_master_id = @in_vchWhMasterID 
				AND inbound_order_master_id = @v_vchInboundMasterID
				AND wh_item_master_id = @v_vchWhItemMasterID
				AND processing_status <> 'COMPLETE')
		BEGIN
			--Missing 
			SET @out_vchNextScreen = 'SERIAL_NUMBER'
			SET @out_vchErrorCode = 999;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'TRANSACTION_INPROCESS',@in_vchLocalID,CONVERT(VARCHAR,@v_nCountPlan),CONVERT(VARCHAR,@v_nCountMiss),CONVERT(VARCHAR,@v_nCountCMP),'@param4','@param5')
		END
	ELSE
		BEGIN
			--Complete
			SET @out_vchNextScreen = 'ITEM_NUMBER'
			SET @out_vchErrorCode = 0;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'TRANSACTION_INPROCESS',@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END

	IF NOT EXISTS (SELECT inbound_rfid_id FROM t_wms_inbound_rfid 
				WHERE wh_master_id = @in_vchWhMasterID 
				AND inbound_order_master_id = @v_vchInboundMasterID
				AND processing_status <> 'COMPLETE')
		BEGIN
			SET @out_vchNextScreen = 'INBOUND_ORDER'
			SET @out_vchErrorCode = 0;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'INBOUND-COMPLETED',@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')

		END

	-----------------------------------------------
	--Display 
	-----------------------------------------------
	SELECT @v_nCountPlan AS qty_plan
		,@v_nCountCMP	 AS qty_complete
		,@v_nCountMiss	 AS qty_miss

	RETURN; 
	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
		  
			UPDATE t_wms_inbound_rfid SET processing_status = 'ERROR' WHERE inbound_rfid_id = @v_vchInbound_rfid AND processing_status <> 'COMPLETE'
			SET @v_dtProcessDateTime = GETDATE();	
			SET @v_vchProcessData2 = 'Receipt Number ' + @v_vchReceiptNumber;
			SET @v_vchProcessData3 = 'Item Number ' + @v_vchItemNumber;
			SET @v_vchProcessData4 = 'Serial Number ' + @v_vchSerialNumber;
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @in_vchOrderNumber,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
	END

	END TRY
	BEGIN CATCH
		IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION; 

		UPDATE t_wms_inbound_rfid SET processing_status = 'ERROR' WHERE inbound_rfid_id = @v_vchInbound_rfid AND processing_status <> 'COMPLETE'
		SET @out_vchErrorCode = ERROR_NUMBER();
		SET @out_vchErrorMsg = ERROR_MESSAGE(); 
		SET @v_dtProcessDateTime = GETDATE();	
		SET @v_vchProcessData2 = 'Receipt Number ' + @v_vchReceiptNumber;
		SET @v_vchProcessData3 = 'Item Number ' + @v_vchItemNumber;
		SET @v_vchProcessData4 = 'Serial Number ' + @v_vchSerialNumber;

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @in_vchDeviceID,
				@in_vchUserID = @in_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @in_vchOrderNumber,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchProcessData3,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
    END CATCH
END
GO
