/****** Object:  StoredProcedure [dbo].[usp_wms_move_lpn]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Atiwat Triyansuwan>
-- Create date: <20-09-2013>
-- Description:	<Move LPN>
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_move_lpn]
	@in_vchApplicationID	NVARCHAR(50),
	@in_vchUser				NVARCHAR(50),
	@in_vchWarehouse		NVARCHAR(50),
	@in_vchForklift			NVARCHAR(50),
	@in_vchLPN				NVARCHAR(50),

	@out_vchLocation		NVARCHAR(50) OUTPUT,
	@out_vchCode			NVARCHAR(50) OUTPUT,
	@out_vchMessage			NVARCHAR(50) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE	@v_intQtyAllocate	NVARCHAR(50),
			@v_vchItem			NVARCHAR(50),
			@v_vchOwner			NVARCHAR(50)

    -- Insert statements for procedure here
	SELECT		@v_vchItem = item.item_number,
				@v_vchOwner = [Owner].owner_code,
				@v_intQtyAllocate = Inven.quantity_allocated,
				@out_vchLocation = Location.location

	FROM		t_wms_inventory AS Inven
	JOIN		t_wms_wh AS WH ON Inven.wh_master_id = WH.wh_master_id
	JOIN		t_wms_wh_item AS WH_Item ON Inven.wh_item_master_id = WH_Item.wh_item_master_id
	JOIN		t_wms_location AS Location ON Inven.location_id = Location.location_id
	JOIN		t_wms_item AS Item ON WH_Item.item_master_id = Item.item_master_id
	JOIN		t_wms_owner AS [Owner] ON Inven.owner_id = [Owner].owner_id
	WHERE		Inven.lpn = @in_vchLPN
	ORDER BY	Inven.quantity_allocated DESC
	IF(@@ROWCOUNT  >0)
		BEGIN
			IF(@v_intQtyAllocate > 0)
				BEGIN
					-- Show Error Message.
					-- Cannot move. Item is allocate.
					SET @out_vchCode = '999';					
					SET @out_vchMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,
																		   'INFO-CANNOT-MOVE-SOME-LPN-ALLOCATED',
																		   (select dbo.usf_get_locale_id(@in_vchUser)),
																		   '@param1',
																		   '@param2',
																		   '@param3',
																		   '@param4',
																		   '@param5')
					SELECT NULL AS location, NULL AS location_id
				END
			ELSE
				BEGIN
					EXEC	usp_putaway_rule
							@in_vchWarehouse,
							@v_vchItem,
							@v_vchOwner,
							@in_vchForklift,
							@out_vchCode OUTPUT,
							@out_vchMessage OUTPUT

					SET		@out_vchCode = '0';
					SET		@out_vchMessage = 'Success';					
				END
		END
	ELSE
		BEGIN
			-- Show Error Message.
			-- LPN does not exist.
			SET		@out_vchCode = '999';
			SET		@out_vchMessage = dbo.usf_get_resouce_value(@in_vchApplicationID,
																'INFO-LPN-NOT-EXIST',
																(select dbo.usf_get_locale_id(@in_vchUser)),
																'@param1',
																'@param2',
																'@param3',
																'@param4',
																'@param5')
			
			SELECT NULL AS location, NULL AS location_id
		END
END


GO
/****** Object:  StoredProcedure [dbo].[usp_wms_outbound_checker_rfid]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_wms_outbound_checker_rfid]
	@in_vchApplicationID		VARCHAR(40),
	@in_vchOutboundMasterID		VARCHAR(40),
	@in_vchLocalID				VARCHAR(40)	= NULL,
	@out_vchErrorCode			VARCHAR(50)	  = NULL OUTPUT,
	@out_vchErrorMsg			NVARCHAR(500) = NULL OUTPUT,
	@out_vchNextScreen			NVARCHAR(50)  = NULL OUTPUT
AS
BEGIN
	DECLARE	@v_vchBeginTrans		BIT=0,
			@v_vchObjName			NVARCHAR(30) = 'usp_wms_outbound_checker_rfid',
			@v_vchApplicationName	NVARCHAR(50),
			@v_vchProcessData1		NVARCHAR(1000),
			@v_vchProcessData2		NVARCHAR(1000),
			@v_vchProcessData3		NVARCHAR(1000),
			@v_vchProcessData4		NVARCHAR(1000),
			@v_dtStartTime			DATETIME,
			@v_dtProcessDateTime	DATETIME,

			@v_vchCheckerRFID		VARCHAR(40),
			@v_vchSerialNumber		NVARCHAR(100),
			@v_vchUserID			NVARCHAR(25),
			@v_vchPickDetailID		VARCHAR(40),
			@v_vchPickMasterID		VARCHAR(40),
			@v_vchOutboundDetailID	VARCHAR(40),
			@v_fltSQuantityLoad		FLOAT,
			@v_fltSQuantityOrder	FLOAT,
			@v_vchDeviceID			NVARCHAR(50),

			--Write Log
			@v_vchOutboundOrderNumber NVARCHAR(50),
			@v_vchOrderStatus		NVARCHAR(50),
			@v_vchOrderType			NVARCHAR(30),
			@v_vchWarehouse			NVARCHAR(50),
			@v_vchLocation			NVARCHAR(50),
			@v_vchOwnerID			VARCHAR(40),
			@v_vchOwner				NVARCHAR(50),
			@v_vchLineNumber		NVARCHAR(25),
			@v_vchParentLPN			NVARCHAR(25),
			@v_vchLPN				NVARCHAR(25),
			@v_vchItemNumber		NVARCHAR(50),
			@v_vchLotNumber			NVARCHAR(50),
			@v_vchExpiryDate		NVARCHAR(50),
			@v_vchAttribute1		NVARCHAR(100),
			@v_vchAttribute2		NVARCHAR(100),
			@v_vchAttribute3		NVARCHAR(100),
			@v_vchAttribute4		NVARCHAR(100),
			@v_vchAttribute5		NVARCHAR(100),
			@v_vchUomPrompt			NVARCHAR(50),
			@v_vchItemStatus		NVARCHAR(50),
			@v_fltQuantityLoad		FLOAT

BEGIN TRY
	EXEC usp_get_application_name @in_vchApplicationID,@v_vchApplicationName OUTPUT

	IF EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid WHERE processing_status = 'READ' AND outbound_order_master_id = @in_vchOutboundMasterID)
		BEGIN
			CHECKER_RFID:
				SET @v_vchBeginTrans = 1;
				SET @v_dtStartTime = GETDATE();
				SET @v_vchCheckerRFID = NULL;
				SET @v_vchSerialNumber = NULL;
				SET @v_vchUserID = NULL;
				SET @v_vchDeviceID = NULL;
			
			BEGIN TRANSACTION;
				--Get Checker RFID
				UPDATE t_wms_outbound_checker_rfid SET processing_status = 'READING' WHERE checker_rfid_id = (SELECT TOP 1 checker_rfid_id FROM t_wms_outbound_checker_rfid WHERE processing_status = 'READ' AND outbound_order_master_id = @in_vchOutboundMasterID)

				SELECT @v_vchCheckerRFID = checker_rfid_id
					,@v_vchSerialNumber = serial_number
					,@v_vchUserID = [user_id]
					,@v_vchDeviceID = device
				FROM t_wms_outbound_checker_rfid
				WHERE processing_status = 'READING'
				AND outbound_order_master_id = @in_vchOutboundMasterID
				
				------------------------------------------------
				--Update Status Complete
				------------------------------------------------
				IF (ISNULL(@v_vchCheckerRFID,'') <> '')
					BEGIN
						UPDATE t_wms_outbound_checker_rfid SET processing_status = 'COMPLETE' WHERE checker_rfid_id = @v_vchCheckerRFID 
					END
				ELSE
					BEGIN
						GOTO END_TRANSACTION;
					END
				
				SELECT @v_vchOutboundOrderNumber = outbound_order_number 
					, @v_vchOrderStatus = order_status
					, @v_vchOrderType = order_type
					, @v_vchOutboundDetailID = outbound_order_detail_id
					, @v_vchPickMasterID = outbound_pick_master_id
					, @v_vchPickDetailID = outbound_pick_detail_id
					, @v_vchOwnerID		 = owner_id
					, @v_vchLocation	 = staging_location
					, @v_vchParentLPN	 = staging_parent_lpn
					, @v_vchLPN			 = staging_lpn
					, @v_vchItemNumber	 = item_number
					, @v_vchLotNumber	 = lot_number
					, @v_vchExpiryDate	 = expiry_date
					, @v_vchAttribute1	 = attribute1
					, @v_vchAttribute2	 = attribute2
					, @v_vchAttribute3	 = attribute3
					, @v_vchAttribute4	 = attribute4
					, @v_vchAttribute5	 = attribute5
					, @v_vchWarehouse	 = wh_id
					, @v_vchLineNumber   = pick_line_number
					, @v_vchUomPrompt    = uom_prompt
					, @v_vchItemStatus   = default_item_status
					, @v_fltQuantityLoad = ISNULL(quantity_load,0)
				FROM v_wms_outbound_pick_or_pack
				WHERE outbound_order_master_id = @in_vchOutboundMasterID
				AND serial_number = @v_vchSerialNumber
				AND quantity_load < quantity_stage
				
				IF ISNULL(@v_vchPickDetailID,'') <> ''
					BEGIN
						--Validate Owner
						SELECT @v_vchOwner = owner_code FROM t_wms_owner where owner_id = @v_vchOwnerID AND is_active = 'YES'
						IF (ISNULL(@v_vchOwner,'') = '')
							BEGIN
								SET @out_vchErrorCode = 'INFO-OWNER-NOT-EXISTS'
								SET @out_vchErrorMsg = 'Owner does not exists'
								GOTO WRITE_PROC;
							END

						--Validate Outbound Pick Order
						IF (ISNULL(@v_vchPickDetailID,'') = '')
							BEGIN
								SET @out_vchErrorCode = 'INFO-SERIAL-NUMBER-NOT-EXIST'
								SET @out_vchErrorMsg = 'Serial number does not Exist'
								GOTO WRITE_PROC;
							END

						--Validate Staging Location
						IF (ISNULL(@v_vchLocation,'') = '')
							BEGIN
								SET @out_vchErrorCode = 'NOT-FOUND-SERIAL-NUMBER-ON-STAGING'
								SET @out_vchErrorMsg = 'Not found serial number '+ @v_vchSerialNumber +' on staging location'
								GOTO WRITE_PROC;
							END
		
						------------------------------------------------
						-- Update Qty Load [Pack Detail]
						-- ถ้ามีการทำ Pack จะต้อง Update Pack ด้วย
						------------------------------------------------
						IF EXISTS (SELECT outbound_pack_detail_id FROM t_wms_outbound_pack_detail 
									WHERE outbound_pick_detail_id = @v_vchPickDetailID 
									AND serial_number = @v_vchSerialNumber)
							BEGIN
								UPDATE t_wms_outbound_pack_detail SET quantity_load = quantity_load + 1
									,load_status = 'YES'
								WHERE outbound_pack_detail_id = (SELECT TOP 1 outbound_pack_detail_id FROM t_wms_outbound_pack_detail 
																	WHERE outbound_pick_detail_id = @v_vchPickDetailID 
																	AND serial_number = @v_vchSerialNumber)
							END

						------------------------------------------------
						-- Update Qty Load [Pick Detail]
						------------------------------------------------
						IF EXISTS (SELECT outbound_pick_detail_id FROM t_wms_outbound_pick_detail
									WHERE outbound_pick_detail_id = @v_vchPickDetailID
									And quantity_load < quantity_stage)
							BEGIN
								------------------------------------------------
								-- Update Qty Load [Pick Detail]
								------------------------------------------------
								UPDATE t_wms_outbound_pick_detail SET quantity_load = quantity_load + 1
									,load_status = 'YES'
								WHERE outbound_pick_detail_id = @v_vchPickDetailID

								------------------------------------------------
								-- Update Qty Load [Outbound Detail]
								------------------------------------------------
								UPDATE t_wms_outbound_detail SET quantity_load = quantity_load + 1
									,item_status = 'CHECKED'
								WHERE outbound_order_detail_id = @v_vchOutboundDetailID
							END

						-----------------------------------------------------------
						--Check จำนวนทั้งหมดของ Order กับจำนวนที่ Load ทั้งหมดของ Order
						-----------------------------------------------------------
						SELECT @v_fltSQuantityOrder = SUM(quantity_order)
							, @v_fltSQuantityLoad = SUM(quantity_load) 
						FROM t_wms_outbound_detail
						WHERE outbound_order_master_id = @in_vchOutboundMasterID

						IF (@v_fltSQuantityOrder = @v_fltSQuantityLoad)
							BEGIN --Load ครบทั้งหมด
								UPDATE t_wms_outbound_master SET order_status = 'LOADED',loading_date_actual = GETDATE() WHERE outbound_order_master_id = @in_vchOutboundMasterID
							END
						ELSE
							BEGIN --Load ยังไม่ครบ
								UPDATE t_wms_outbound_master set order_status = 'LOADING' WHERE outbound_order_master_id = @in_vchOutboundMasterID
							END
		
						IF ISNULL(@v_vchParentLPN,'') = ''
							BEGIN
								SET @v_vchParentLPN = NULL
							END
				
						----------------------------------------------
						--Write Log
						----------------------------------------------
						INSERT INTO t_com_tran_log
								(	app_id
									, tran_type
									, sub_tran_type
									, [app_name]
									, [description]
									, start_tran_datetime
									, end_tran_datetime
									, warehouse
									, to_warehouse
									, location
									, to_location
									, [owner]
									, to_owner
									, item_number
									, quantity
									, quantity_uom
									, after_quantity
									, after_quantity_uom
									, lot_number
									, after_lot_number
									, [expiry_date]
									, after_expiry_date
									, serial_number
									, [attribute1]
									, [after_attribute1]
									, [attribute2]
									, [after_attribute2]
									, [attribute3]
									, [after_attribute3]
									, [attribute4]
									, [after_attribute4]
									, [attribute5]
									, [after_attribute5]
									, [user_id]
									, reference_number
									, control_number
									, parent_lpn
									, after_parent_lpn
									, lpn
									, after_lpn
									, [status]
									, after_status
									, zone
									, order_number
									, line_number
									, udf_2
									, device
									, create_by)
								VALUES
									(@in_vchApplicationID
									,'OO_LOAD'
									,'LOAD_ORDER'
									,@v_vchApplicationName
									,'Load Item by RFID'
									,@v_dtStartTime
									,GETDATE()
									,@v_vchWarehouse
									,@v_vchWarehouse
									,@v_vchLocation
									,@v_vchLocation
									,@v_vchOwner
									,@v_vchOwner
									,@v_vchItemNumber
									,1
									,@v_vchUomPrompt
									,@v_fltQuantityLoad + 1
									,@v_vchUomPrompt
									,@v_vchLotNumber
									,@v_vchLotNumber
									,@v_vchExpiryDate
									,@v_vchExpiryDate
									,@v_vchSerialNumber
									,@v_vchAttribute1
									,@v_vchAttribute1
									,@v_vchAttribute2
									,@v_vchAttribute2
									,@v_vchAttribute3
									,@v_vchAttribute3
									,@v_vchAttribute4
									,@v_vchAttribute4
									,@v_vchAttribute5
									,@v_vchAttribute5
									,@v_vchUserID
									,NULL
									,NULL
									,@v_vchParentLPN
									,@v_vchParentLPN
									,@v_vchLPN
									,@v_vchLPN
									,@v_vchItemStatus
									,@v_vchItemStatus
									,NULL
									,@v_vchOutboundOrderNumber
									,@v_vchLineNumber
									,@v_vchOrderType
									,@v_vchDeviceID
									,@v_vchUserID)
				
					END
				
			END_TRANSACTION:
				COMMIT TRANSACTION;

				------------------------------------------------
				--Next Row
				------------------------------------------------
				IF EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid WHERE processing_status = 'READ' AND outbound_order_master_id = @in_vchOutboundMasterID)
					BEGIN
						GOTO CHECKER_RFID;
					END
		END


	DECLARE @v_nCountMiss	INT = 0,
			@v_nCountCMP	INT = 0,
			@v_nCountPlan	INT = 0

	-- Count Plan
	SELECT @v_nCountPlan = COUNT(checker_rfid_id) FROM t_wms_outbound_checker_rfid 
	WHERE outbound_order_master_id = @in_vchOutboundMasterID

	-- Count Complete
	SELECT @v_nCountCMP = COUNT(checker_rfid_id) FROM t_wms_outbound_checker_rfid 
	WHERE outbound_order_master_id = @in_vchOutboundMasterID 
	AND processing_status = 'COMPLETE'

	-- Count pending,read,error
	SELECT @v_nCountMiss = COUNT(checker_rfid_id) FROM t_wms_outbound_checker_rfid 
	WHERE outbound_order_master_id = @in_vchOutboundMasterID 
	AND processing_status <> 'COMPLETE'

	IF EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid 
			WHERE outbound_order_master_id = @in_vchOutboundMasterID
			AND processing_status <> 'COMPLETE')
		BEGIN
			--Missing 
			SET @out_vchNextScreen = 'ITEM_RFID'
			SET @out_vchErrorCode = 999;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'TRANSACTION_INPROCESS',@in_vchLocalID,CONVERT(VARCHAR,@v_nCountPlan),CONVERT(VARCHAR,@v_nCountMiss),CONVERT(VARCHAR,@v_nCountCMP),'@param4','@param5')
		END
	ELSE	
		BEGIN
			--Complete
			SET @out_vchNextScreen = 'LOCATION'
			SET @out_vchErrorCode = 0;
			SELECT @out_vchErrorMsg = dbo.usf_get_resouce_value(@in_vchApplicationID,'SAVE_SUCCESS',@in_vchLocalID,'@param1','@param2','@param3','@param4','@param5')
		END

	
	-----------------------------------------------
	-- สำหรับแสดงที่หน้าจอ
	-----------------------------------------------
	SELECT @v_nCountPlan AS qty_plan
		,@v_nCountCMP	 AS qty_complete
		,@v_nCountMiss	 AS qty_miss

	RETURN;

	------------------------------------------------
	--Write process log
	------------------------------------------------
	BEGIN
		WRITE_PROC:							
			IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
				ROLLBACK TRANSACTION;
			
			UPDATE t_wms_outbound_checker_rfid SET processing_status = 'ERROR' WHERE checker_rfid_id = @v_vchCheckerRFID 
			SET @v_dtProcessDateTime = GETDATE();	
			SET @v_vchProcessData1 = 'Order Number ' + @v_vchOutboundOrderNumber;
			SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;
				
			EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @v_vchDeviceID,
				@in_vchUserID = @v_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchOutboundOrderNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
			------------------------------------------------
			--Next Row
			------------------------------------------------
			IF EXISTS (SELECT checker_rfid_id FROM t_wms_outbound_checker_rfid WHERE processing_status = 'READ' AND outbound_order_master_id = @in_vchOutboundMasterID)
				BEGIN
					GOTO CHECKER_RFID;
				END
	END
END TRY

BEGIN CATCH
	IF (@@TRANCOUNT > 0 AND @v_vchBeginTrans = 1)
			ROLLBACK TRANSACTION;

		UPDATE t_wms_outbound_checker_rfid SET processing_status = 'ERROR' WHERE checker_rfid_id = @v_vchCheckerRFID 
		IF (ISNULL(@out_vchErrorCode,'') = '' OR ISNULL(@out_vchErrorCode,'') = '0')
			BEGIN
				SET @out_vchErrorCode = ERROR_NUMBER();
				SET @out_vchErrorMsg = ERROR_MESSAGE();
			END
			
		SET @v_dtProcessDateTime = GETDATE();	
		SET @v_vchProcessData1 = 'Order Number ' + @v_vchOutboundOrderNumber;
		SET @v_vchProcessData2 = 'Item number ' + @v_vchItemNumber;

		EXEC usp_LogManager
				@in_vchApplicationID = @in_vchApplicationID,
				@in_vchWhID = @v_vchWarehouse,
				@in_vchDevice = @v_vchDeviceID,
				@in_vchUserID = @v_vchUserID,
				@in_vchLogType = 'PROCESS',
				@in_vchProcess = @v_vchObjName,
				@in_dtProcessDateTime = @v_dtProcessDateTime,
				@in_vchData1 = @v_vchProcessData1,
				@in_vchData2 = @v_vchProcessData2,
				@in_vchData3 = @v_vchOutboundOrderNumber,
				@in_vchData4 = @v_vchProcessData4,
				@in_vchErrorCode = @out_vchErrorCode,
				@in_vchMessage = @out_vchErrorMsg
END CATCH

END
GO
