/****** Object:  StoredProcedure [dbo].[usp_wms_report_graph_fast_moving]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_graph_fast_moving]	

	@para_owner nvarchar(30),
	@para_wh nvarchar(30),
	@para_item nvarchar(50),

	@para_date_start nvarchar(10),
	@para_date_end nvarchar(10),
		
	@para_type nvarchar(30)
	
AS
BEGIN


if(@para_type = 'INBOUND')	begin  --INBOUND
	select in_b.item_number as xValue,convert(nvarchar(30),sum(in_b.total)) as iValue ,'' as uom , '' as [description] from (
		select top(20) item_number,tran_type,count(tran_id) as total from t_com_tran_log
		where tran_type in ('IO_RECEIPT','INV_PUTAWAY')
		and isnull([owner],'') like case when @para_owner='-- All owner --' then '%%' else @para_owner end
		and isnull(to_warehouse,'') like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
		and item_number like case when @para_item='' then '%%' else @para_item end  
		and DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
		group by item_number,tran_type
		order by total desc
	) in_b
	group by in_b.item_number
	order by sum(in_b.total) desc

	
end
--outbound
else if(@para_type = 'OUTBOUND')	 begin
	select out_b.item_number as xValue ,convert(nvarchar(30),sum(out_b.total)) as iValue , '' as uom , '' as [description] from (
		select top(20) item_number,tran_type,count(tran_id) as total from t_com_tran_log
		where (tran_type in ('OO_PICK','OO_SHIP','OO_LOAD','OO_UNLOAD','OO_UNPACK','OO_PACK','OO_UNPICK')
		OR (tran_type = 'INV_MOVE' AND sub_tran_type = 'MOVE_DEST' )
		)
		and isnull([owner],'') like case when @para_owner='-- All owner --' then '%%' else @para_owner end
		and isnull(warehouse,'') like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
		and item_number like case when @para_item='' then '%%' else @para_item end  
		and DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
		group by item_number,tran_type
		order by total desc
	) out_b
	group by out_b.item_number
	order by sum(out_b.total) desc
end
else if(@para_type = 'INVEN')	 begin
	select inv.item_number as xValue ,convert(nvarchar(30),sum(inv.total)) as iValue ,'' as uom , '' as [description] from (
		select top(20) item_number,tran_type,count(tran_id) as total from t_com_tran_log
		where (tran_type in ('INV_CHANGE_SERIAL','INV_ADJUST','INV_BORROW','INV_CHANGE_LOT','INV_STATUS_CHANGE','LPN_COUNTING')
		OR (tran_type = 'INV_MOVE' AND sub_tran_type = 'MOVE_ON_PC' )
		)
		and isnull([owner],'') like case when @para_owner='-- All owner --' then '%%' else @para_owner end
		and isnull(warehouse,'') like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
		and item_number like case when @para_item='' then '%%' else @para_item end  
		and DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
		group by item_number,tran_type
		order by total desc
	) inv
	group by inv.item_number
	order by sum(inv.total) desc
end
else if(@para_type = 'ALL')	 begin
	select A.item_number as xValue ,convert(nvarchar(30),sum(A.total)) as iValue , '' as uom , '' as [description] from (
		select top(20) item_number,tran_type,count(tran_id) as total from t_com_tran_log
		where (tran_type in ('INV_CHANGE_SERIAL','INV_ADJUST','INV_BORROW','INV_CHANGE_LOT','INV_STATUS_CHANGE','LPN_COUNTING'
		,'OO_PICK','OO_SHIP','OO_LOAD','OO_UNLOAD','OO_UNPACK','OO_PACK','OO_UNPICK'
		,'IO_RECEIPT','INV_PUTAWAY'
		)
		OR (tran_type = 'INV_MOVE' AND sub_tran_type = 'MOVE_DEST' )
		OR (tran_type = 'INV_MOVE' AND sub_tran_type = 'MOVE_ON_PC' )
		)
		and isnull([owner],'') like case when @para_owner='-- All owner --' then '%%' else @para_owner end
		and isnull(warehouse,'') like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
		and item_number like case when @para_item='' then '%%' else @para_item end  
		and DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
		group by item_number,tran_type
		order by total desc
	) A
	group by A.item_number
	order by sum(A.total) desc
end



END


GO
