/****** Object:  StoredProcedure [dbo].[usp_wms_report_graph_order_status]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_graph_order_status]		
	@para_date_start nvarchar(10),
	@para_date_end nvarchar(10),
	@para_table nvarchar(30),
	@para_wh nvarchar(50),
	@para_owner nvarchar(50)
	
AS
BEGIN
	declare @total decimal(10,2)
	set @total = 0
	
	--inbound
	if(@para_table = 'INBOUND')	begin
		select @total= count(A.inbound_order_master_id) from t_wms_inbound_master A
		inner join t_wms_wh B
		on A.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on A.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, A.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
	

		select b.order_status as xValue,convert(nvarchar(30),isnuLL(a.c,0)) as iValue,'' as uom ,'' as [description] from 
		(
			select convert(int,round((count(M.inbound_order_master_id)*100)/(@total),0)) as c, M.order_status from t_wms_inbound_master M
			inner join t_wms_wh B
			on M.wh_master_id = B.wh_master_id
			inner join t_wms_owner C
			on M.owner_id = C.owner_id
			where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
			and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
			and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
			group by order_status	

		) a inner join 
		(
			select distinct order_status from t_wms_inbound_master 
		) b
		on a.order_status = b.order_status
		order by a.c desc
	end
	--outbound
	else begin
		select @total= count(outbound_order_master_id)from t_wms_outbound_master A
		inner join t_wms_wh B
		on A.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on A.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, A.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	

		
		select b.order_status as xValue,convert(nvarchar(30),isnuLL(a.c,0)) as iValue ,'' as uom ,'' as [description] from (
			select convert(int,round((count(outbound_order_master_id)*100)/(@total),0)) as c, order_status from t_wms_outbound_master M
			inner join t_wms_wh B
			on M.wh_master_id = B.wh_master_id
			inner join t_wms_owner C
			on M.owner_id = C.owner_id
			where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
			and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
			and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end		
			group by order_status	

		) a inner join 
		(
			select distinct order_status from t_wms_outbound_master 
		) b
		on a.order_status = b.order_status
		order by a.c desc
	end
	
	--select convert(int,round((count(inbound_order_master_id)*100)/(@total),0)) as c, order_status from t_wms_inbound_master a
	--where DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
	--group by order_status
	--order by order_status
	
	
END


