/****** Object:  StoredProcedure [dbo].[usp_wms_report_graph_order_type_detail]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_graph_order_type_detail]		
	@para_date_start nvarchar(10),
	@para_date_end nvarchar(10),
	@para_table nvarchar(30),
	@para_wh nvarchar(50),
	@para_owner nvarchar(50),
	@para_order_type nvarchar(100)
	
AS
BEGIN
	--declare @total decimal(10,2)
	--set @total = 0

	--select @total= count(inbound_order_master_id)from t_wms_inbound_master 
	
	--inbound
	if(@para_table = 'INBOUND')	
	begin	
			SELECT TOP(20) * FROM (
			SELECT CONVERT(NVARCHAR(30),ISNULL(SUM(D.quantity_order),0)) AS order_qty
			,CONVERT(NVARCHAR(30),ISNULL(SUM(D.quantity_receive),0)) AS receive_qty
			,D.wh_item_master_id
			,( SELECT TOP 1 item.item_number 
				from t_wms_wh_item wh_item 
				LEFT JOIN t_wms_item item on wh_item.item_master_id = item.item_master_id
				where wh_item.wh_item_master_id = D.wh_item_master_id
				) as item_number
			,SUM(D.quantity_order) as quantity_order
			,SUM(D.quantity_receive) as quantity_receive
			from t_wms_inbound_detail D 
			where inbound_order_master_id in  (	
				SELECT M.inbound_order_master_id AS c 
				FROM t_wms_inbound_master M
				INNER JOIN t_wms_wh B ON M.wh_master_id = B.wh_master_id
				INNER JOIN t_wms_owner C ON M.owner_id = C.owner_id
				WHERE DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
				AND B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
				AND C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
				AND M.order_type = @para_order_type
		
				)
			group by D.wh_item_master_id
			) A
			order by A.quantity_order  desc
			

	end
	--outbound
	else begin
		select top(20) * from (
			select convert(nvarchar(30),isnuLL(sum(D.quantity_order) ,0)) as order_qty,convert(nvarchar(30),isnuLL(sum(D.quantity_pick),0))  as receive_qty
			,D.wh_item_master_id,
			(
			select top 1 item.item_number from t_wms_wh_item wh_item left join t_wms_item item on wh_item.item_master_id = item.item_master_id
			where wh_item.wh_item_master_id = D.wh_item_master_id
			) as item_number
			,SUM(D.quantity_order) as quantity_order
			from t_wms_outbound_detail D where outbound_order_master_id in 
			(
				select M.outbound_order_master_id as c  from t_wms_outbound_master M
				inner join t_wms_wh B
				on M.wh_master_id = B.wh_master_id
				inner join t_wms_owner C
				on M.owner_id = C.owner_id
				where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
				and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
				and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
				and M.order_type =@para_order_type
				
		
			)
			group by D.wh_item_master_id
			) A
			order by A.quantity_order desc
	end
	
	
	
	--select convert(nvarchar(30),isnull(count(inbound_order_master_id),0)) as iValue, order_type as xValue from t_wms_inbound_master a
	--where DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
	--group by order_type
	--order by order_type
END


