/****** Object:  StoredProcedure [dbo].[usp_wms_report_graph_performance]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_graph_performance]		
	@para_date_start nvarchar(10),
	@para_date_end nvarchar(10),
	@para_table nvarchar(30),
	@para_wh nvarchar(50),
	@para_owner nvarchar(50)
	
AS
BEGIN
	--declare @total decimal(10,2)
	--set @total = 0

	--select @total= count(inbound_order_master_id)from t_wms_inbound_master 
	
	--inbound
	if(@para_table = 'INBOUND')	begin	
	   --datable 1
		select order_type as xValue ,convert(nvarchar(30),isnuLL(count(inbound_order_number),0)) as iValue ,'' as uom ,'' as [description] 
		from t_wms_inbound_master M
		inner join t_wms_wh B
		on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on M.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
		group by M.order_type

		-- datatable 2
		select top(20) convert(nvarchar(30),sum(D.quantity_order)) as quantity_order 
		,convert(nvarchar(30),sum(D.quantity_receive)) as quantity_receive
		,D.wh_item_master_id
		,( SELECT TOP 1 item.item_number 
			from t_wms_wh_item wh_item 
			LEFT JOIN t_wms_item item on wh_item.item_master_id = item.item_master_id
			where wh_item.wh_item_master_id = D.wh_item_master_id
		) as item_number
		,'' as uom ,'' as [description] 
		from t_wms_inbound_detail D
		inner join t_wms_inbound_master M on D.inbound_order_master_id =M.inbound_order_master_id
		inner join t_wms_wh B on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C on M.owner_id = C.owner_id

		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end
		group by D.wh_item_master_id 

		-- datatable 3
		select order_type as xValue ,convert(nvarchar(30),isnuLL(count(inbound_order_number),0)) as iValue ,'' as uom ,'' as [description] 
		from t_wms_inbound_master M
		inner join t_wms_wh B
		on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on M.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
		and M.order_status = 'close'
		group by M.order_type
		
	end
	--outbound
	else begin
		   --datable 1
		select order_type as xValue ,convert(nvarchar(30),isnuLL(count(outbound_order_number),0)) as iValue ,'' as uom ,'' as [description] 
		from t_wms_outbound_master M
		inner join t_wms_wh B
		on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on M.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	

		group by M.order_type

		-- datatable 2
		select top(20) convert(nvarchar(30),sum(D.quantity_order)) as quantity_order 
		,convert(nvarchar(30),sum(D.quantity_pick)) as quantity_receive
		,D.wh_item_master_id
		,( SELECT TOP 1 item.item_number 
			from t_wms_wh_item wh_item 
			LEFT JOIN t_wms_item item on wh_item.item_master_id = item.item_master_id
			where wh_item.wh_item_master_id = D.wh_item_master_id
		) as item_number
		,'' as uom ,'' as [description] 
		from t_wms_outbound_detail D
		inner join t_wms_outbound_master M on D.outbound_order_master_id =M.outbound_order_master_id
		inner join t_wms_wh B on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C on M.owner_id = C.owner_id

		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end
		group by D.wh_item_master_id 

		-- datatable 3

		select order_type as xValue ,convert(nvarchar(30),isnuLL(count(outbound_order_number),0)) as iValue ,'' as uom ,'' as [description] 
		from t_wms_outbound_master M
		inner join t_wms_wh B
		on M.wh_master_id = B.wh_master_id
		inner join t_wms_owner C
		on M.owner_id = C.owner_id
		where DATEADD(dd, 0, DATEDIFF(dd, 0, M.create_date)) between @para_date_start and @para_date_end
		and B.wh_id like case when  @para_wh = '' then '%%' else @para_wh end
		and C.owner_code like case when  @para_owner = '' then '%%' else @para_owner end	
		and M.order_status ='close'
		group by M.order_type

	
	end
	
	
	
	--select convert(nvarchar(30),isnull(count(inbound_order_master_id),0)) as iValue, order_type as xValue from t_wms_inbound_master a
	--where DATEADD(dd, 0, DATEDIFF(dd, 0, create_date)) between @para_date_start and @para_date_end
	--group by order_type
	--order by order_type
END


