/****** Object:  StoredProcedure [dbo].[usp_wms_report_graph_top10_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_graph_top10_item]	

	@para_owner nvarchar(30),
	@para_wh nvarchar(30),
	@para_zone nvarchar(30),
	@para_itemtop nvarchar(10),
	
	@para_table nvarchar(30)
	
AS
BEGIN

declare @div int 
set @div = 1000;

if(@para_table = 'INBOUND')	begin
		-- Top 10 
		if(@para_itemtop = '10') begin 
			select top(10) convert(nvarchar(50),convert(decimal(20,2),round(sum(quantity)/1000,2) )) as iValue 
			,sum(quantity) as qty
			,item_number as xValue 
			,uom_prompt as uom
			,[description]
		
			from dbo.v_wms_inventory_data
			where wh_id like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
			and owner_code like case when @para_owner='-- All owner --' then '%%' else @para_owner end
			and isnull(zone,'') like case when @para_zone='-- All zone --' then '%%' else @para_zone end
			group by item_number,uom_prompt ,[description]
			order by qty desc 
		 end

		 --Top 20
		 else if(@para_itemtop = '20') begin 
			select top(20) convert(nvarchar(50),convert(decimal(20,2),round(sum(quantity)/1000,2) )) as iValue 
			,sum(quantity) as qty
			,item_number as xValue 
			,uom_prompt as uom
			,[description]
		
			from dbo.v_wms_inventory_data
			where wh_id like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
			and owner_code like case when @para_owner='-- All owner --' then '%%' else @para_owner end
			and isnull(zone,'') like case when @para_zone='-- All zone --' then '%%' else @para_zone end
			group by item_number,uom_prompt ,[description]
			order by qty desc 
		  
		end

		 --Top 30
		 else if(@para_itemtop = '30') begin 
			select top(30) convert(nvarchar(50),convert(decimal(20,2),round(sum(quantity)/1000,2) )) as iValue 
			,sum(quantity) as qty
			,item_number as xValue 
			,uom_prompt as uom
			,[description]
		
			from dbo.v_wms_inventory_data
			where wh_id like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
			and owner_code like case when @para_owner='-- All owner --' then '%%' else @para_owner end
			and isnull(zone,'') like case when @para_zone='-- All zone --' then '%%' else @para_zone end
			group by item_number,uom_prompt ,[description]
			order by qty desc 
		  
		end

		--Top 40
		 else if(@para_itemtop = '40') begin 
			select top(40) convert(nvarchar(50),convert(decimal(20,2),round(sum(quantity)/1000,2) )) as iValue 
			,sum(quantity) as qty
			,item_number as xValue 
			,uom_prompt as uom
			,[description]
		
			from dbo.v_wms_inventory_data
			where wh_id like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
			and owner_code like case when @para_owner='-- All owner --' then '%%' else @para_owner end
			and isnull(zone,'') like case when @para_zone='-- All zone --' then '%%' else @para_zone end
			group by item_number,uom_prompt ,[description]
			order by qty desc 
		  
		end

		 --Top 50
		 else if(@para_itemtop = '50') begin 
			select top(50) convert(nvarchar(50),convert(decimal(20,2),round(sum(quantity)/1000,2) )) as iValue 
			,sum(quantity) as qty
			,item_number as xValue 
			,uom_prompt as uom
			,[description]
		
			from dbo.v_wms_inventory_data
			where wh_id like case when @para_wh='-- All warehouse --' then '%%' else @para_wh end  
			and owner_code like case when @para_owner='-- All owner --' then '%%' else @para_owner end
			and isnull(zone,'') like case when @para_zone='-- All zone --' then '%%' else @para_zone end
			group by item_number,uom_prompt ,[description]
			order by qty desc 
		  
		end

		
end
--outbound
else begin
	select 1 
end

END


GO
