/****** Object:  StoredProcedure [dbo].[usp_wms_report_inbound_order_list]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: 11/16/2021 4:40:27 PM
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_inbound_order_list]
	-- Add the parameters for the stored procedure here
	@in_vchWarehouse				NVARCHAR(50) = NULL,
	@in_vchOwner					NVARCHAR(50) = NULL,
	@in_vchOrderType				NVARCHAR(50) = NULL,
	@in_vchOrderStatus				NVARCHAR(50) = NULL,
	@in_vchInboundOrderNumber		NVARCHAR(50) = NULL,	
	@in_dtExpectedDeliveryDate		DATETIME = NULL,
	@in_dtExpectedDeliveryDateTo	DATETIME = NULL,
	@in_dtReceiveDate				DATETIME = NULL,
	@in_dtReceiveDateTo				DATETIME = NULL,
	@in_vchSupplierCode				NVARCHAR(50) = NULL,
	@in_vchSupplierName				NVARCHAR(50) = NULL,
	@in_vchCustomer					NVARCHAR(50) = NULL,
	@in_vchCategoryCode				NVARCHAR(50) = NULL,
	@in_vchItemNumber				NVARCHAR(50) = NULL,
	@in_vchUserId					NVARCHAR(50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE	@t_wms_owner	TABLE
	(
		owner_id	UNIQUEIDENTIFIER,
		owner_code	NVARCHAR(40),
		owner_name	NVARCHAR(100)
	)
	DECLARE	@t_wms_wh	table
	(
		wh_master_id	UNIQUEIDENTIFIER,
		wh_id	NVARCHAR(25),
		wh_name	NVARCHAR(50)
	)

	IF @in_vchWarehouse = '' SET @in_vchWarehouse = NULL;
	IF @in_vchOwner = '' SET @in_vchOwner = NULL;
	IF @in_vchOrderType = '' SET @in_vchOrderType = NULL;
	IF @in_vchOrderStatus = '' SET @in_vchOrderStatus = NULL;
	IF @in_vchInboundOrderNumber = '' SET @in_vchInboundOrderNumber = NULL;
	IF @in_dtExpectedDeliveryDate = '' SET @in_dtExpectedDeliveryDate = NULL;
	IF @in_dtExpectedDeliveryDateTo = '' SET @in_dtExpectedDeliveryDateTo = NULL;
	IF @in_dtReceiveDate = '' SET @in_dtReceiveDate = NULL;
	IF @in_dtReceiveDateTo = '' SET @in_dtReceiveDateTo = NULL;
	IF @in_vchSupplierCode = '' SET @in_vchSupplierCode = NULL;
	IF @in_vchSupplierName = '' SET @in_vchSupplierName = NULL;
	IF @in_vchCustomer = '' SET @in_vchCustomer = NULL;
	IF @in_vchCategoryCode = '' SET @in_vchCategoryCode = NULL;
	IF @in_vchItemNumber = '' SET @in_vchItemNumber = NULL;

	IF @in_vchOwner IS NULL
		BEGIN
			INSERT INTO @t_wms_owner
			SELECT t_wms_owner.owner_id, t_wms_owner.owner_code, t_wms_owner.owner_name
			FROM t_wms_owner_user
			INNER JOIN t_wms_owner ON t_wms_owner_user.owner_id = t_wms_owner.owner_id
			WHERE user_id = @in_vchUserId
		END
	ELSE
		BEGIN
			INSERT INTO @t_wms_owner
			SELECT t_wms_owner.owner_id, t_wms_owner.owner_code, t_wms_owner.owner_name
			FROM t_wms_owner_user
			INNER JOIN t_wms_owner ON t_wms_owner_user.owner_id = t_wms_owner.owner_id
			WHERE user_id = @in_vchUserId AND t_wms_owner.owner_code LIKE @in_vchOwner + '%'
		END

	IF @in_vchWarehouse IS NULL
		BEGIN
			INSERT INTO @t_wms_wh
			SELECT t_wms_wh.wh_master_id, t_wms_wh.wh_id, t_wms_wh.wh_name
			FROM t_wms_wh_user
			INNER JOIN t_wms_wh ON t_wms_wh_user.wh_master_id = t_wms_wh.wh_master_id
			WHERE user_id = @in_vchUserId
		END
	ELSE
		BEGIN
			INSERT INTO @t_wms_wh
			SELECT t_wms_wh.wh_master_id, t_wms_wh.wh_id, t_wms_wh.wh_name
			FROM t_wms_wh_user
			INNER JOIN t_wms_wh ON t_wms_wh_user.wh_master_id = t_wms_wh.wh_master_id
			WHERE user_id = @in_vchUserId AND t_wms_wh.wh_id LIKE @in_vchWarehouse + '%'
		END
		
	SELECT ibMS.wh_id
		 , ibMS.inbound_order_number
		 , ibMS.order_type
		 , ibMS.order_status
		 , ibDT.line_number
		 , itm.item_number
		 , itm.description AS item_description
		 , ISNULL(ibDT.quantity_order, 0) AS quantity_order
		 , ISNULL(ibDT.quantity_receive, 0) AS quantity_receive
		 , ISNULL(ibDT.quantity_order, 0) - ISNULL(ibDT.quantity_receive, 0) AS quantity_remain
	FROM t_wms_inbound_master ibMS WITH (NOLOCK)
	INNER JOIN t_wms_inbound_detail ibDT WITH (NOLOCK) ON ibMS.inbound_order_master_id = ibDT.inbound_order_master_id
	INNER JOIN t_wms_item itm ON ibDT.item_master_id = itm.item_master_id
	LEFT JOIN t_wms_receipt_header rcH WITH (NOLOCK) ON ibMS.inbound_order_master_id = rcH.inbound_order_master_id
	LEFT JOIN t_wms_receipt_detail rcD WITH (NOLOCK) ON rcH.receipt_header_id = rcD.receipt_header_id
													AND ibMS.inbound_order_master_id = rcD.inbound_order_master_id
													AND ibDT.item_number = rcD.item_number
	LEFT JOIN t_wms_supplier sup ON ibMS.supplier_id = sup.supplier_id
	LEFT JOIN t_wms_customer cus ON ibMS.customer_id = cus.customer_id
	WHERE 1 = 1
		AND (ibMS.owner_id IN (SELECT owner_id FROM @t_wms_owner))
		AND (ibMS.wh_master_id IN (SELECT wh_master_id FROM @t_wms_wh))
		AND (ibMS.order_type = @in_vchOrderType OR @in_vchOrderType IS NULL)
		AND (ibMS.order_status = @in_vchOrderStatus OR @in_vchOrderStatus IS NULL)
		AND (ibMS.inbound_order_number LIKE @in_vchInboundOrderNumber + '%' OR @in_vchInboundOrderNumber IS NULL)
		AND (CAST(ibMS.expected_delivery_date AS DATE) BETWEEN CAST(@in_dtExpectedDeliveryDate AS DATE) AND CAST(@in_dtExpectedDeliveryDateTo AS DATE) OR @in_dtExpectedDeliveryDate IS NULL OR @in_dtExpectedDeliveryDateTo IS NULL)
		AND (CAST(rcD.receive_date AS DATE) BETWEEN CAST(@in_dtReceiveDate AS DATE) AND CAST(@in_dtReceiveDateTo AS DATE) OR @in_dtReceiveDate IS NULL OR @in_dtReceiveDateTo IS NULL )
		AND (sup.supplier_code LIKE @in_vchSupplierCode + '%' OR @in_vchSupplierCode IS NULL)
		AND (sup.supplier_name LIKE @in_vchSupplierName + '%' OR @in_vchSupplierName IS NULL)
		AND ((cus.customer_code + ' : ' + cus.customer_name) LIKE @in_vchCustomer + '%' OR @in_vchCustomer IS NULL)
		GROUP BY ibMS.wh_id
		 , ibMS.inbound_order_number
		 , ibMS.order_type
		 , ibMS.order_status
		 , ibDT.line_number
		 , itm.item_number
		 , itm.description
		 , ibDT.quantity_order
		 , ibDT.quantity_receive

END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_report_inventory_by_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<WM3,,Report>
-- Create date: <2020-10-21,,>
-- Description:	<stored procedure for report inventory by item ,dupplicate from stored procedure usp_get_inventory_item_viewer,>
-- exec usp_wms_report_inventory_by_item
-- =============================================
--	DATE		Modyfy	Description
--	2020-10-21	NUI		- Create new stored procedure
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_inventory_by_item]
	-- Add the parameters for the stored procedure here
	@in_vchWarehouse		NVARCHAR(50) = null,
	@in_vchLocation			NVARCHAR(50) = null,
	@in_vchItemNumber		NVARCHAR(50) = null,
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItemCategory		NVARCHAR(50) = null,
	@in_vchLotNumber		NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNumber		NVARCHAR(50) = null,
	@in_vchReceiveDate		NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode			NVARCHAR(50) = null,
	@in_vchZone				NVARCHAR(50) = null,
	@in_vchOwner			NVARCHAR(50) = null,
	@in_vchExpiryDateTo		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null,
	@in_vchUserId			NVARCHAR(50) = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from	
	IF @in_vchWarehouse = '' SET @in_vchWarehouse = NULL;
	IF @in_vchLocation = '' SET @in_vchLocation = NULL;
	IF @in_vchItemNumber = '' SET @in_vchItemNumber = NULL;
	IF @in_vchParentLPN = '' SET @in_vchParentLPN = NULL;
	IF @in_vchLPN = '' SET @in_vchLPN = NULL;
	IF @in_vchItemCategory = '' SET @in_vchItemCategory = NULL;
	IF @in_vchLotNumber = '' SET @in_vchLotNumber = NULL;
	IF @in_vchExpiryDate = '' SET @in_vchExpiryDate = NULL;
	IF @in_vchSerialNumber = '' SET @in_vchSerialNumber = NULL;
	IF @in_vchReceiveDate = '' SET @in_vchReceiveDate = NULL;
	IF @in_vchInventoryStatus = '' SET @in_vchInventoryStatus = NULL;
	IF @in_vchGrade = '' SET @in_vchGrade = NULL;
	IF @in_vchDGCode = '' SET @in_vchDGCode = NULL;
	IF @in_vchZone = '' SET @in_vchZone = NULL;
	IF @in_vchOwner = '' SET @in_vchOwner = NULL;
	IF @in_vchExpiryDateTo = '' SET @in_vchExpiryDateTo = NULL;
	IF @in_vchReceiveDateTo = '' SET @in_vchReceiveDateTo = NULL;
	IF @in_vchUserId = '' SET @in_vchUserId = NULL;

	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @v_Owner TABLE
	(
		owner_id	uniqueidentifier,
		owner_code	nvarchar(40),
		owner_name	nvarchar(100)
	)

	DECLARE @v_Warehouse TABLE
	(
		wh_master_id	uniqueidentifier,
		wh_id	nvarchar(40),
		wh_name	nvarchar(100)
	)


	IF @in_vchUserId IS NOT NULL
		BEGIN
			INSERT INTO @v_Owner
			SELECT own.owner_id, own.owner_code, own.owner_name
			FROM t_wms_owner own
			INNER JOIN t_wms_owner_user uown ON own.owner_id = uown.owner_id
			WHERE 1=1 AND uown.is_active = 'YES'
				AND (Convert(nvarchar(50),own.owner_id) = @in_vchOwner OR @in_vchOwner IS NULL)
				AND uown.user_id = @in_vchUserId

			INSERT INTO @v_Warehouse
			SELECT wh.wh_master_id, wh.wh_id, wh.wh_name
			FROM t_wms_wh wh
			INNER JOIN t_wms_wh_user uwh ON wh.wh_master_id = uwh.wh_master_id
			WHERE 1 = 1 AND uwh.is_active = 'YES'
				AND (wh.wh_id LIKE @in_vchWarehouse + '%' OR @in_vchWarehouse IS NULL)
				AND uwh.user_id = @in_vchUserId
		END
	ELSE
		BEGIN
			INSERT INTO @v_Owner
			SELECT own.owner_id, own.owner_code, own.owner_name
			FROM t_wms_owner own
			INNER JOIN t_wms_owner_user uown ON own.owner_id = uown.owner_id
			WHERE 1=1 AND uown.is_active = 'YES'
				AND (Convert(nvarchar(50),own.owner_id) = @in_vchOwner OR @in_vchOwner IS NULL)

			INSERT INTO @v_Warehouse
			SELECT wh.wh_master_id, wh.wh_id, wh.wh_name
			FROM t_wms_wh wh
			INNER JOIN t_wms_wh_user uwh ON wh.wh_master_id = uwh.wh_master_id
			WHERE 1 = 1 AND uwh.is_active = 'YES'
				AND (wh.wh_id LIKE @in_vchWarehouse + '%' OR @in_vchWarehouse IS NULL)
		END



    -- Insert statements for procedure here
	SELECT own.owner_code
		 , own.owner_name
		 , wh.wh_id
		 , wh.wh_name
		 , loc.location
		 , inv.lpn
		 , cate.item_category
		 , itm.item_number
		 , itm.description item_description
		 , itm.min_qty
		 , itm.max_qty
		 , invLot.lot_number
		 , CAST(invExp.expiry_date AS datetime) expiry_date
		 , SUM(CASE WHEN invSN.serial_number IS NULL THEN inv.quantity ELSE invSN.quantity END) quantity
		 , CAST(inv.receive_date AS datetime) receive_date
		 , invstatus.inv_status
	FROM t_wms_inventory inv
	INNER JOIN t_wms_owner own ON inv.owner_id = own.owner_id
	INNER JOIN t_wms_wh wh ON inv.wh_master_id = wh.wh_master_id
	INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
	INNER JOIN t_wms_wh_item whitm ON inv.wh_item_master_id = whitm.wh_item_master_id
	INNER JOIN t_wms_item itm ON whitm.item_master_id = itm.item_master_id
	INNER JOIN t_wms_category cate ON itm.category_id = cate.category_id
	INNER JOIN t_wms_inventory_status invstatus ON inv.inventory_status_id = invstatus.inventory_status_id
	LEFT JOIN t_wms_zone zone
	LEFT JOIN t_wms_zone_location loczone ON zone.zone_id = loczone.zone_id
										  ON inv.location_id = loczone.location_id
	LEFT JOIN (SELECT attr.inventory_id,attr. attribute_group_id, attr.attribute_value AS lot_number, attr.quantity, attr.quantity_allocated
			   FROM t_wms_inventory_attribute attr
			   INNER JOIN t_wms_inventory_attribute_type type ON attr.inv_attribute_type_id = type.inv_attribute_type_id AND type.inv_attribute_type = 'LOT') AS invLot ON inv.inventory_id = invLot.inventory_id AND inv.attribute_group_id = invLot.attribute_group_id
	LEFT JOIN (SELECT attr.inventory_id,attr. attribute_group_id, attr.attribute_value AS expiry_date, attr.quantity, attr.quantity_allocated
			   FROM t_wms_inventory_attribute attr
			   INNER JOIN t_wms_inventory_attribute_type type ON attr.inv_attribute_type_id = type.inv_attribute_type_id AND type.inv_attribute_type = 'EXPIRY_DATE') AS invExp ON inv.inventory_id = invExp.inventory_id AND inv.attribute_group_id = invExp.attribute_group_id
	LEFT JOIN (SELECT attr.inventory_id,attr. attribute_group_id, attr.attribute_value AS serial_number, attr.quantity, attr.quantity_allocated
			   FROM t_wms_inventory_attribute attr
			   INNER JOIN t_wms_inventory_attribute_type type ON attr.inv_attribute_type_id = type.inv_attribute_type_id AND type.inv_attribute_type = 'SERIAL') AS invSN ON inv.inventory_id = invSN.inventory_id AND inv.attribute_group_id = invSN.attribute_group_id
	--WHERE (own.owner_id = @in_vchOwner OR @in_vchOwner IS NULL)
	WHERE (own.owner_id IN (SELECT owner_id FROM @v_Owner))
	  AND (cate.item_category = @in_vchItemCategory OR @in_vchItemCategory IS NULL)
	  AND (itm.item_number = @in_vchItemNumber OR @in_vchItemNumber IS NULL)
	  AND (invstatus.inv_status = @in_vchInventoryStatus OR @in_vchInventoryStatus IS NULL)
	  --AND (wh.wh_id LIKE @in_vchWarehouse + '%' OR @in_vchWarehouse IS NULL)
	   AND (wh.wh_id IN (SELECT wh_id FROM @v_Warehouse))
	  AND (zone.zone LIKE @in_vchZone + '%' OR @in_vchZone IS NULL)
	  AND (loc.location LIKE @in_vchLocation + '%' OR @in_vchLocation IS NULL)  
	  AND (inv.lpn LIKE @in_vchLPN + '%' OR @in_vchLPN IS NULL)
	  --AND (inv.parent_lpn LIKE @in_vchParentLPN + '%' OR @in_vchParentLPN IS NULL)	
	  AND (invLot.lot_number LIKE @in_vchLotNumber + '%' OR @in_vchLotNumber IS NULL)
	  AND (invSN.serial_number LIKE @in_vchSerialNumber + '%' OR @in_vchSerialNumber IS NULL)
	  --AND (itm.grade LIKE @in_vchGrade + '%' OR @in_vchGrade IS NULL)
	  --AND (itm.dg_code LIKE @in_vchDGCode + '%' OR @in_vchDGCode IS NULL)
	  AND (CAST(invExp.expiry_date AS datetime) BETWEEN CAST(@in_vchExpiryDate AS datetime) AND CAST(@in_vchExpiryDateTo AS datetime) OR @in_vchExpiryDate IS NULL OR @in_vchExpiryDateTo IS NULL)
	  AND (CAST(inv.receive_date AS datetime) BETWEEN CAST(@in_vchReceiveDate AS datetime) AND CAST(@in_vchReceiveDateTo AS datetime) OR @in_vchReceiveDate IS NULL OR @in_vchReceiveDateTo IS NULL)
	GROUP BY own.owner_code, own.owner_name, wh.wh_id, wh.wh_name, zone.zone, loc.location, inv.lpn
		   , cate.item_category, itm.item_number, itm.description, itm.min_qty, itm.max_qty, invLot.lot_number, invExp.expiry_date, inv.receive_date, invstatus.inv_status



END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_report_inventory_stock_card]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_wms_report_inventory_stock_card]
	@in_vchWhItemMasterID	VARCHAR(40),
	@in_vchStartDate		VARCHAR(8),
	@in_vchEndDate			VARCHAR(8)
AS
BEGIN
	--DECLARE @in_vchWhItemMasterID	VARCHAR(40) = '4680B83E-017E-4DE2-8D77-45D28030BFCE',
	--		@in_vchStartDate		VARCHAR(8) = '20240220',
	--		@in_vchEndDate			VARCHAR(8) = '20240305'--'20240305','20240224'

--Get Close Inventory
	DECLARE @tCloseInv TABLE
	(
		[close_date] [DATE] NOT NULL,
		[wh_item_master_id] [varchar] (40) NOT NULL, 
		[close_inv_qty] [float] NULL
	)

	DECLARE @tInventory TABLE
	(
		[snap_date] [DATE] NOT NULL,
		[wh_item_master_id] [varchar] (40) NOT NULL, 
		[close_inv_qty] [float] NULL
	)

	IF ISNULL(@in_vchWhItemMasterID,'') = ''
		BEGIN
			INSERT INTO @tCloseInv
			(
				close_date,
				wh_item_master_id,
				close_inv_qty
			)
			SELECT CONVERT(DATE,snap_date)	AS close_date 
				,CONVERT(VARCHAR(36),wh_item_master_id)  AS wh_item_master_id
				,SUM(inv.close_inv_qty)	AS close_inv_qty
			FROM t_wms_snap_inventory_for_stock_card inv 
			WHERE CONVERT(DATE,snap_date) = DATEADD(DAY,-1, CONVERT(DATE,@in_vchStartDate)) 
			GROUP BY wh_item_master_id,CONVERT(DATE,snap_date)

			INSERT INTO @tInventory
			(
				snap_date,
				wh_item_master_id,
				close_inv_qty
			)
			SELECT tInv.snap_date
				,tInv.wh_item_master_id
				,SUM(ISNULL(close_inv_qty,0)) as close_inv_qty 
			FROM t_wms_snap_inventory_for_stock_card tInv
			WHERE CONVERT(VARCHAR,tInv.snap_date,112) = CONVERT(DATE,@in_vchStartDate)
			--WHERE (CONVERT(VARCHAR,tInv.snap_date,112) >= DATEADD(DAY,-1, CONVERT(DATE,@in_vchStartDate))  AND CONVERT(VARCHAR,tInv.snap_date,112) <= @in_vchEndDate)
			GROUP BY tInv.snap_date,tInv.wh_item_master_id--,tInv.zone
		END
	ELSE
		BEGIN
			INSERT INTO @tCloseInv
			(
				close_date,
				wh_item_master_id,
				close_inv_qty
			)
			SELECT CONVERT(DATE,snap_date)	AS close_date 
				,CONVERT(VARCHAR(36),wh_item_master_id)  AS wh_item_master_id
				,SUM(inv.close_inv_qty)	AS close_inv_qty
			FROM t_wms_snap_inventory_for_stock_card inv 
			WHERE CONVERT(DATE,snap_date) = DATEADD(DAY,-1, CONVERT(DATE,@in_vchStartDate))
			AND CONVERT(VARCHAR(36),inv.wh_item_master_id) = @in_vchWhItemMasterID
			GROUP BY wh_item_master_id,CONVERT(DATE,snap_date)
			 
			INSERT INTO @tInventory
			(
				snap_date,
				wh_item_master_id,
				close_inv_qty
			)
			SELECT tInv.snap_date
				,tInv.wh_item_master_id
				,SUM(ISNULL(close_inv_qty,0)) as close_inv_qty 
			FROM t_wms_snap_inventory_for_stock_card tInv
			WHERE CONVERT(VARCHAR,tInv.snap_date,112) = CONVERT(DATE,@in_vchStartDate)
			--WHERE (CONVERT(VARCHAR,tInv.snap_date,112) >= DATEADD(DAY,-1, CONVERT(DATE,@in_vchStartDate)) AND CONVERT(VARCHAR,tInv.snap_date,112) <= @in_vchEndDate)
			AND CONVERT(VARCHAR(36),tInv.wh_item_master_id) = @in_vchWhItemMasterID 
			GROUP BY tInv.snap_date,tInv.wh_item_master_id 
		END

--Get Current Trans log
	DECLARE @v_dtCurrentDate DATE = GETDATE()
	DECLARE @tTranLogCurrentDate TABLE
	(
		[snap_tran_id] [uniqueidentifier] NOT NULL,
		[snap_date] [date] NOT NULL,
		[tran_id] [uniqueidentifier] NULL,
		[tran_type] [nvarchar](20) NOT NULL,
		[sub_tran_type] [nvarchar](20) NOT NULL,
		[type] [varchar](5) NOT NULL,
		[wh_master_id] [uniqueidentifier] NOT NULL,
		[wh_id] [nvarchar](25) NULL,
		[owner_id] [uniqueidentifier] NOT NULL,
		[owner_code] [nvarchar](40) NULL,
		[location_id] [uniqueidentifier] NOT NULL,
		[location] [nvarchar](50) NULL,
		[parent_lpn] [nvarchar](25) NULL,
		[lpn] [nvarchar](25) NULL,
		[wh_item_master_id] [uniqueidentifier] NOT NULL,
		[item_master_id] [uniqueidentifier] NOT NULL,
		[item_number] [nvarchar](50) NULL,
		[item_description] [nvarchar](200) NULL,
		[min_qty] [float] NULL,
		[max_qty] [float] NULL,
		[quantity] [float] NULL,
		[quantity_uom] [nvarchar](40) NULL,
		[lot_number] [nvarchar](100) NULL,
		[expiry_date] [datetime] NULL,
		[attribute1] [nvarchar](100) NULL,
		[attribute2] [nvarchar](100) NULL,
		[attribute3] [nvarchar](100) NULL,
		[attribute4] [nvarchar](100) NULL,
		[attribute5] [nvarchar](100) NULL,
		[serial_number] [nvarchar](100) NULL,
		[inventory_status_id] [uniqueidentifier] NOT NULL,
		[inv_status] [nvarchar](40) NULL,
		[tran_datetime] [datetime] NULL,
		[zone_id] [uniqueidentifier] NULL,
		[zone] [nvarchar](40) NULL,
		[order_number] [nvarchar](50) NULL,
		[receive_date] [date] NULL,
		[erp_location] [nvarchar](50) NULL,
		[trans_create_by] [nvarchar](25) NULL
	)

	DECLARE @tAllLog TABLE
	(
		[tran_datetime] [datetime] NULL,
		[snap_date] [date] NOT NULL,
		[wh_master_id] [uniqueidentifier] NOT NULL,
		[wh_id] [nvarchar](25) NULL,
		[zone] [nvarchar](40) NULL,
		[location] [nvarchar](50) NULL,
		[wh_item_master_id] [uniqueidentifier] NOT NULL,
		[item_master_id] [uniqueidentifier] NOT NULL,
		[item_number] [nvarchar](50) NULL,
		[item_description] [nvarchar](200) NULL,
		[lot_number] [nvarchar](100) NULL,
		[expiry_date] [datetime] NULL,
		[attribute1] [nvarchar](100) NULL,
		[attribute2] [nvarchar](100) NULL,
		[attribute3] [nvarchar](100) NULL,
		[attribute4] [nvarchar](100) NULL,
		[attribute5] [nvarchar](100) NULL,
		[min_qty] [float] NULL,
		[max_qty] [float] NULL,
		[order_number] [nvarchar](50) NULL,
		[trans_create_by] [nvarchar](25) NULL,
		[quantity_in] [float] NULL,
		[quantity_out] [float] NULL
	)

	IF CONVERT(DATE,@in_vchEndDate) >= CONVERT(DATE,@v_dtCurrentDate)
		BEGIN
			SELECT tran_id
				,tran_type
				,sub_tran_type
				,description
				,warehouse
				,to_warehouse
				,owner
				,to_owner
				,location
				,to_location
				,parent_lpn
				,after_parent_lpn
				,lpn
				,after_lpn
				,item_number
				,quantity
				,quantity_uom
				,lot_number
				,after_lot_number
				,expiry_date
				,after_expiry_date
				,serial_number
				,attribute1
				,after_attribute1
				,attribute2
				,after_attribute2
				,attribute3
				,after_attribute3
				,attribute4
				,after_attribute4
				,attribute5
				,after_attribute5
				,status
				,after_status
				,order_number
				,reference_number
				,create_by		AS trans_create_by
				,create_date 
				,pick_location
				,receive_date
			INTO #tLog
			FROM t_com_tran_log
			WHERE tran_type IN ('IO_RECEIPT','BLIND_RECEIPT','OO_SHIP','OO_PARTIAL_SHIP','INV_ADJUST','INV_MOVE','INV_CHANGE')
			AND sub_tran_type IN ('RECEIPT','CONFIRM_SHIP','CONFIRM_TO_ERP','MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','ADJUST_IN_TO_ERP','ADJUST_IN_NOT_ERP','ADJUST_OUT_TO_ERP','ADJUST_OUT_NOT_ERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY','INV_CHANGE_ITEM_IN','INV_CHANGE_ITEM_OUT')
			AND CONVERT(DATE,create_date) = CONVERT(DATE,@v_dtCurrentDate)
 
			;WITH tLogAllCTE AS
				(
					--IN อย่างเดียว
					SELECT tran_id 
						,tran_type
						,sub_tran_type
						,'IN'				AS [type]
						,to_warehouse		AS wh_id
						,to_owner			AS owner_code
						,to_location		AS location
						,after_parent_lpn	AS parent_lpn
						,after_lpn			AS lpn
						,item_number
						,quantity
						,quantity_uom
						,after_lot_number	AS lot_number
						,after_expiry_date	AS expiry_date
						,after_attribute1	AS attribute1
						,after_attribute2	AS attribute2
						,after_attribute3	AS attribute3
						,after_attribute4	AS attribute4
						,after_attribute5	AS attribute5
						,serial_number
						,after_status		AS inv_status
						,trans_create_by
						,create_date
						,CASE WHEN ISNULL(order_number,'') = '' THEN (CASE WHEN (tran_type = 'INV_CHANGE' and sub_tran_type = 'INV_CHANGE_ITEM_IN') THEN '' ELSE ISNULL(reference_number,'') END) ELSE order_number END AS order_number
						,ISNULL(receive_date,create_date) AS receive_date 
					FROM #tLog
					WHERE tran_type IN ('IO_RECEIPT','BLIND_RECEIPT','INV_ADJUST','INV_CHANGE')
					AND sub_tran_type IN ('RECEIPT','ADJUST_IN_TO_ERP','ADJUST_IN_NOT_ERP','INV_CHANGE_ITEM_IN')
				UNION
					--OUT อย่างเดียว
					SELECT tran_id
						,tran_type
						,sub_tran_type
						,'OUT'			AS [type] 
						,warehouse		AS wh_id
						,owner			AS owner_code
						,(CASE WHEN (tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP') AND sub_tran_type IN ('CONFIRM_SHIP','CONFIRM_TO_ERP')) THEN pick_location ELSE location END) AS location
						,parent_lpn		AS parent_lpn
						,lpn			AS lpn
						,item_number
						,(CASE WHEN ISNULL(quantity,0) < 0 THEN ISNULL(quantity,0) * -1 ELSE ISNULL(quantity,0) END) AS quantity
						,quantity_uom
						,lot_number		AS lot_number
						,expiry_date	AS expiry_date
						,attribute1		AS attribute1
						,attribute2		AS attribute2
						,attribute3		AS attribute3
						,attribute4		AS attribute4
						,attribute5		AS attribute5
						,serial_number
						,status			AS inv_status
						,trans_create_by
						,create_date
						,CASE WHEN ISNULL(order_number,'') = '' THEN (CASE WHEN (tran_type = 'INV_CHANGE' and sub_tran_type = 'INV_CHANGE_ITEM_OUT') THEN '' ELSE ISNULL(reference_number,'') END) ELSE order_number END AS order_number
						,receive_date 
					FROM #tLog
					WHERE tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP','INV_ADJUST','INV_CHANGE')
					AND sub_tran_type IN ('CONFIRM_SHIP','CONFIRM_TO_ERP','ADJUST_OUT_TO_ERP','ADJUST_OUT_NOT_ERP','INV_CHANGE_ITEM_OUT')		 
				UNION
					--Location ต้นทาง OUT
					--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
					SELECT tran_id
						,tran_type
						,sub_tran_type
						,'OUT'			AS [type]
						,warehouse		AS wh_id
						,owner			AS owner_code
						,(CASE WHEN (tran_type IN ('OO_SHIP','OO_PARTIAL_SHIP') AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP')) THEN pick_location ELSE location END) AS location
						,parent_lpn		AS parent_lpn
						,lpn			AS lpn
						,item_number
						,quantity
						,quantity_uom
						,lot_number		AS lot_number
						,expiry_date	AS expiry_date
						,attribute1		AS attribute1
						,attribute2		AS attribute2
						,attribute3		AS attribute3
						,attribute4		AS attribute4
						,attribute5		AS attribute5
						,serial_number
						,status			AS inv_status
						,trans_create_by
						,create_date
						,CASE WHEN ISNULL(order_number,'') = '' THEN reference_number ELSE order_number END AS order_number
						,receive_date 
					FROM #tLog
					WHERE tran_type IN ('INV_MOVE','OO_SHIP','OO_PARTIAL_SHIP')
					AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY')
				UNION
					--Location ปลายทาง IN
					--TranType: INV_MOVE, SubTranType: MOVE_SOURCE จาก PDA
					SELECT tran_id
						,tran_type
						,sub_tran_type
						,'IN'				AS [type]
						,to_warehouse		AS wh_id
						,to_owner			AS owner_code
						,to_location		AS location
						,after_parent_lpn	AS parent_lpn
						,after_lpn			AS lpn
						,item_number
						,quantity
						,quantity_uom
						,after_lot_number	AS lot_number
						,after_expiry_date	AS expiry_date
						,after_attribute1	AS attribute1
						,after_attribute2	AS attribute2
						,after_attribute3	AS attribute3
						,after_attribute4	AS attribute4
						,after_attribute5	AS attribute5
						,serial_number
						,after_status		AS inv_status
						,trans_create_by
						,DATEADD(MILLISECOND,2,create_date)
						,CASE WHEN ISNULL(order_number,'') = '' THEN reference_number ELSE order_number END AS order_number
						,receive_date 
					FROM #tLog
					WHERE tran_type IN ('INV_MOVE','OO_SHIP','OO_PARTIAL_SHIP')
					AND sub_tran_type IN ('MOVE_BORROW','MOVE_CONSIGN','MOVE_CONSIGN_NOERP','MOVE_LPN','MOVE_ON_PC','MOVE_ON_PC_NO_ERP','MOVE_PUTAWAY')
				)
			INSERT INTO @tTranLogCurrentDate
					([snap_tran_id]					
					,[snap_date]
					,[tran_id]
					,[tran_type]
					,[sub_tran_type]
					,[type]
					,[wh_master_id]
					,[wh_id]
					,[owner_id]
					,[owner_code]
					,[location_id]
					,[location]
					,[parent_lpn]
					,[lpn]
					,[wh_item_master_id]
					,[item_master_id]
					,[item_number]
					,[item_description]
					,[min_qty]
					,[max_qty]
					,[quantity]
					,[quantity_uom]
					,[lot_number]
					,[expiry_date]
					,[attribute1]
					,[attribute2]
					,[attribute3]
					,[attribute4]
					,[attribute5]
					,[serial_number]
					,[inventory_status_id]
					,[inv_status]
					,[tran_datetime]
					,[zone_id]
					,[zone]
					,[order_number]
					,[receive_date]
					,[erp_location]
					,[trans_create_by])
				SELECT NEWID()
					,@v_dtCurrentDate AS snap_date 
					,t.tran_id
					,t.tran_type
					,t.sub_tran_type
					,t.[type]
					,wh.wh_master_id
					,wh.wh_id
					,own.owner_id
					,own.owner_code
					,loc.location_id
					,loc.location
					,ISNULL(t.parent_lpn,'') AS parent_lpn
					,ISNULL((CASE WHEN loc.lpn_controlled = 'NO' THEN NULL ELSE t.lpn END),'') AS lpn
					,whItem.wh_item_master_id
					,item.item_master_id
					,item.item_number
					,item.description
					,item.min_qty
					,item.max_qty
					,quantity
					,quantity_uom
					,ISNULL(t.lot_number,'') AS lot_number
					,(CASE WHEN item.expiry_date_control = 'NONE' THEN NULL ELSE CONVERT(VARCHAR,t.expiry_date,112) END) AS expiry_date
					,ISNULL(t.attribute1,'') AS attribute1
					,ISNULL(t.attribute2,'') AS attribute2
					,ISNULL(t.attribute3,'') AS attribute3
					,ISNULL(t.attribute4,'') AS attribute4
					,ISNULL(t.attribute5,'') AS attribute5
					,ISNULL(t.serial_number,'') AS serial_number
					,invStatus.inventory_status_id
					,invStatus.inv_status 
					,t.create_date
					,z.zone_id
					,z.zone
					,order_number
					,t.receive_date
					,loc.erp_location
					,trans_create_by 
				FROM tLogAllCTE t
				INNER JOIN t_wms_wh wh ON t.wh_id = wh.wh_id
				INNER JOIN t_wms_owner own ON t.owner_code = own.owner_code
				INNER JOIN t_wms_location loc ON t.location = loc.location AND loc.wh_master_id = wh.wh_master_id
				INNER JOIN t_wms_inventory_status invStatus ON t.inv_status = invStatus.inv_status
				INNER JOIN t_wms_item item ON t.item_number = item.item_number and own.owner_id = item.owner_id
				INNER JOIN t_wms_wh_item whItem ON item.item_master_id = whItem.item_master_id AND whItem.wh_master_id = wh.wh_master_id
				LEFT JOIN t_wms_zone_location zLoc on loc.location_id = zLoc.location_id
				LEFT JOIN t_wms_zone z ON zLoc.zone_id = z.zone_id

			IF OBJECT_ID('tempdb..#tLog') IS NOT NULL
				DROP TABLE #tLog

			SELECT snap_date
				,wh_master_id
				,wh_id
				,zone
				,[location]
				,wh_item_master_id
				,item_master_id
				,item_number
				,item_description
				,lot_number
				,expiry_date
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,min_qty
				,max_qty
				,order_number 
				,trans_create_by
				,tran_datetime
				,[IN]
				,[OUT]
			INTO #vInvStockCardCurrentDate
			FROM (SELECT tLog.snap_date
					,tLog.wh_master_id
					,tLog.wh_id
					,tLog.type
					,tLog.zone
					,tLog.[location]
					,tLog.wh_item_master_id
					,tLog.item_master_id
					,tLog.item_number
					,tLog.item_description
					,tLog.lot_number
					,tLog.expiry_date
					,tLog.attribute1
					,tLog.attribute2
					,tLog.attribute3
					,tLog.attribute4
					,tLog.attribute5
					,tLog.min_qty
					,tLog.max_qty
					,tLog.quantity
					,tLog.order_number 
					,tLog.trans_create_by
					,tLog.tran_datetime 
				 FROM @tTranLogCurrentDate tLog
				 ) AS SourceTable  
			PIVOT (SUM(quantity) FOR type IN ([IN], [OUT] )) AS PivotTable

			INSERT INTO @tAllLog
			(
				tran_datetime
				,snap_date
				,wh_master_id
				,wh_id
				,zone
				,location
				,wh_item_master_id
				,item_master_id
				,item_number
				,item_description
				,lot_number
				,expiry_date
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,min_qty
				,max_qty
				,order_number
				,trans_create_by
				,quantity_in
				,quantity_out
			)
			SELECT tran_datetime
				,snap_date
				,wh_master_id
				,wh_id
				,zone
				,location
				,wh_item_master_id
				,item_master_id
				,item_number
				,item_description
				,lot_number
				,expiry_date
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,min_qty
				,max_qty
				,order_number
				,trans_create_by
				,ISNULL(quantity_in,0) AS quantity_in
				,ISNULL(quantity_out,0) AS quantity_out
			FROM (
			SELECT tran_datetime
						,snap_date
						,wh_master_id
						,wh_id
						,zone
						,location
						,wh_item_master_id
						,item_master_id
						,item_number
						,item_description
						,lot_number
						,expiry_date
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,min_qty
						,max_qty
						,order_number
						,trans_create_by
						,ISNULL([IN],0) AS quantity_in
						,ISNULL([OUT],0) AS quantity_out 
					FROM v_wms_inventory_stock_card
					UNION ALL
					SELECT tran_datetime
						,snap_date
						,wh_master_id
						,wh_id
						,zone
						,location
						,wh_item_master_id
						,item_master_id
						,item_number
						,item_description
						,lot_number
						,expiry_date
						,attribute1
						,attribute2
						,attribute3
						,attribute4
						,attribute5
						,min_qty
						,max_qty
						,order_number
						,trans_create_by
						,ISNULL([IN],0) AS quantity_in
						,ISNULL([OUT],0) AS quantity_out 
					FROM #vInvStockCardCurrentDate
				) t 
			WHERE (CONVERT(VARCHAR,snap_date,112) >= @in_vchStartDate AND CONVERT(VARCHAR,snap_date,112) <= @in_vchEndDate)
			AND CASE WHEN ISNULL(@in_vchWhItemMasterID,'') = '' THEN '' ELSE CONVERT(VARCHAR(36),wh_item_master_id) END  = CASE WHEN ISNULL(@in_vchWhItemMasterID,'') = '' THEN '' ELSE CONVERT(VARCHAR(36),@in_vchWhItemMasterID) END
		END
	ELSE
		BEGIN
			INSERT INTO @tAllLog
			(
				tran_datetime
				,snap_date
				,wh_master_id
				,wh_id
				,zone
				,location
				,wh_item_master_id
				,item_master_id
				,item_number
				,item_description
				,lot_number
				,expiry_date
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,min_qty
				,max_qty
				,order_number
				,trans_create_by
				,quantity_in
				,quantity_out
			)
			SELECT tran_datetime
				,snap_date
				,wh_master_id
				,wh_id
				,zone
				,location
				,wh_item_master_id
				,item_master_id
				,item_number
				,item_description
				,lot_number
				,expiry_date
				,attribute1
				,attribute2
				,attribute3
				,attribute4
				,attribute5
				,min_qty
				,max_qty
				,order_number
				,trans_create_by
				,ISNULL([IN],0) AS quantity_in
				,ISNULL([OUT],0) AS quantity_out
			FROM v_wms_inventory_stock_card
			WHERE (CONVERT(VARCHAR,snap_date,112) >= @in_vchStartDate AND CONVERT(VARCHAR,snap_date,112) <= @in_vchEndDate)
			AND CASE WHEN ISNULL(@in_vchWhItemMasterID,'') = '' THEN '' ELSE CONVERT(VARCHAR(36),wh_item_master_id) END  = CASE WHEN ISNULL(@in_vchWhItemMasterID,'') = '' THEN '' ELSE CONVERT(VARCHAR(36),@in_vchWhItemMasterID) END
		END

--Get Data for View Stock Card
	SELECT tAll.snap_date
		,tLogCTE.tran_datetime 
		,tLogCTE.zone
		,tLogCTE.location
		,tAll.wh_item_master_id 
		,tLogCTE.lot_number 
		,tLogCTE.expiry_date
		,tLogCTE.attribute1
		,tLogCTE.attribute2
		,tLogCTE.attribute3
		,tLogCTE.attribute4
		,tLogCTE.attribute5 
		,tLogCTE.order_number
		,tLogCTE.trans_create_by
		,ISNULL(tLogCTE.quantity_in,0) as quantity_in
		,ISNULL(tLogCTE.quantity_out,0) as quantity_out
	INTO #tAllSnap
	FROM (SELECT snap_date
				,wh_item_master_id 
			FROM @tInventory 
			UNION
			SELECT snap_date
				,wh_item_master_id 
			FROM @tAllLog) tAll 
	LEFT JOIN @tAllLog tLogCTE ON tAll.wh_item_master_id = tLogCTE.wh_item_master_id AND CONVERT(VARCHAR,tAll.snap_date,112) = CONVERT(VARCHAR,tLogCTE.snap_date,112) 
	--WHERE tran_datetime IS NOT NULL

	SELECT #tAllSnap.snap_date
		,ISNULL(#tAllSnap.tran_datetime,#tAllSnap.snap_date)  AS tran_datetime
		,#tAllSnap.zone
		,#tAllSnap.location
		,#tAllSnap.wh_item_master_id 
		,#tAllSnap.lot_number 
		,#tAllSnap.expiry_date
		,#tAllSnap.attribute1
		,#tAllSnap.attribute2
		,#tAllSnap.attribute3
		,#tAllSnap.attribute4
		,#tAllSnap.attribute5 
		,#tAllSnap.order_number
		,#tAllSnap.trans_create_by
		,tClose.close_inv_qty AS open_stock_qty
		,ISNULL(#tAllSnap.quantity_in,0) as quantity_in
		,ISNULL(#tAllSnap.quantity_out,0) as quantity_out
		,ROW_NUMBER() OVER(PARTITION BY #tAllSnap.wh_item_master_id ORDER BY #tAllSnap.snap_date, #tAllSnap.tran_datetime) AS is_record
	INTO #tSnap
	FROM #tAllSnap
	LEFT JOIN @tCloseInv tClose ON tClose.wh_item_master_id = #tAllSnap.wh_item_master_id
	WHERE (CONVERT(VARCHAR,#tAllSnap.snap_date,112) >= CONVERT(DATE,@in_vchStartDate) AND CONVERT(VARCHAR,#tAllSnap.snap_date,112) <= @in_vchEndDate)

	SELECT tSnap.snap_date
		,tSnap.tran_datetime
		,wh.wh_master_id
		,wh.wh_id
		,tSnap.zone
		,ISNULL(tSnap.location,'') AS location
		,tSnap.wh_item_master_id
		,item.item_master_id
		,item.item_number
		,item.description AS item_description
		,tSnap.lot_number
		,tSnap.expiry_date
		,tSnap.attribute1
		,tSnap.attribute2
		,tSnap.attribute3
		,tSnap.attribute4
		,tSnap.attribute5 
		,uom.uom
		,uom.uom_prompt
		,tSnap.order_number
		,tSnap.trans_create_by
		,ISNULL(tSnap.open_stock_qty,0) AS open_stock_qty
		,ISNULL(tSnap.quantity_in,0) AS quantity_in
		,(CASE WHEN ISNULL(tSnap.quantity_out,0) < 0 THEN ISNULL(tSnap.quantity_out,0) *-1 ELSE ISNULL(tSnap.quantity_out,0) END) AS quantity_out
		--(Open stock + In - Out) = Total
		,ISNULL(SUM(((CASE WHEN tSnap.is_record = 1 THEN ISNULL(tSnap.open_stock_qty,0) ELSE 0 END) + ISNULL(tSnap.quantity_in,0)) - (CASE WHEN ISNULL(tSnap.quantity_out,0) < 0 THEN ISNULL(tSnap.quantity_out,0) * - 1 ELSE ISNULL(tSnap.quantity_out,0) END)) OVER (PARTITION BY tSnap.wh_item_master_id ORDER BY tSnap.wh_item_master_id, tSnap.is_record),0) AS total_qty
		,(CASE WHEN ISNULL(tSnap.location,'') = '' THEN 'EMPTY' ELSE 'DATA' END) AS record_type
	FROM #tSnap tSnap
	INNER JOIN t_wms_wh_item whItem ON tSnap.wh_item_master_id = whItem.wh_item_master_id
	INNER JOIN t_wms_item item ON whItem.item_master_id = item.item_master_id
	INNER JOIN t_wms_item_uom uom ON item.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
	INNER JOIN t_wms_wh wh ON whItem.wh_master_id = wh.wh_master_id
	WHERE tran_datetime IS NOT NULL
	ORDER BY snap_date,tSnap.wh_item_master_id,tSnap.is_record,tran_datetime
	 
	IF OBJECT_ID('tempdb..#tAllSnap') IS NOT NULL
		DROP TABLE #tAllSnap
	IF OBJECT_ID('tempdb..#tSnap') IS NOT NULL
		DROP TABLE #tSnap
	IF OBJECT_ID('tempdb..#vInvStockCardCurrentDate') IS NOT NULL
		DROP TABLE #vInvStockCardCurrentDate

END

