/****** Object:  StoredProcedure [dbo].[usp_wms_report_inventory_summary_by_item]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_inventory_summary_by_item] 
	-- Add the parameters for the stored procedure here
	@in_vchWarehouse		NVARCHAR(50) = null,
	@in_vchLocation			NVARCHAR(50) = null,
	@in_vchItemNumber		NVARCHAR(50) = null,
	@in_vchParentLPN		NVARCHAR(25) = null,
	@in_vchLPN				NVARCHAR(25) = null,
	@in_vchItemCategory		NVARCHAR(50) = null,
	@in_vchLotNumber		NVARCHAR(50) = null,
	@in_vchExpiryDate		NVARCHAR(50) = null,
	@in_vchSerialNumber		NVARCHAR(50) = null,
	@in_vchReceiveDate		NVARCHAR(50) = null,
	@in_vchInventoryStatus	NVARCHAR(50) = null,
	@in_vchGrade			NVARCHAR(50) = null,
	@in_vchDGCode			NVARCHAR(50) = null,
	@in_vchZone				NVARCHAR(50) = null,
	@in_vchOwner			NVARCHAR(50) = null,
	@in_vchExpiryDateTo		NVARCHAR(50) = null,
	@in_vchReceiveDateTo	NVARCHAR(50) = null,
	@in_vchUserId			NVARCHAR(50) = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	IF @in_vchWarehouse			= '' SET @in_vchWarehouse = NULL
	IF @in_vchLocation			= '' SET @in_vchLocation = NULL
	IF @in_vchItemNumber		= '' SET @in_vchItemNumber = NULL
	IF @in_vchParentLPN			= '' SET @in_vchParentLPN = NULL
	IF @in_vchLPN				= '' SET @in_vchLPN = NULL
	IF @in_vchItemCategory		= '' SET @in_vchItemCategory = NULL
	IF @in_vchLotNumber			= '' SET @in_vchLotNumber = NULL
	IF @in_vchExpiryDate		= '' SET @in_vchExpiryDate = NULL
	IF @in_vchSerialNumber		= '' SET @in_vchSerialNumber = NULL
	IF @in_vchReceiveDate		= '' SET @in_vchReceiveDate = NULL
	IF @in_vchInventoryStatus	= '' SET @in_vchInventoryStatus = NULL
	IF @in_vchGrade				= '' SET @in_vchGrade = NULL
	IF @in_vchDGCode			= '' SET @in_vchDGCode = NULL
	IF @in_vchZone				= '' SET @in_vchZone = NULL
	IF @in_vchOwner				= '' SET @in_vchOwner = NULL
	IF @in_vchExpiryDateTo		= '' SET @in_vchExpiryDateTo = NULL
	IF @in_vchReceiveDateTo		= '' SET @in_vchReceiveDateTo = NULL
	IF @in_vchUserId			= '' SET @in_vchUserId = NULL

	DECLARE @v_Owner TABLE
	(
		owner_id	uniqueidentifier,
		owner_code	nvarchar(40),
		owner_name	nvarchar(100)
	)

	DECLARE @v_Warehouse TABLE
	(
		wh_master_id	uniqueidentifier,
		wh_id	nvarchar(40),
		wh_name	nvarchar(100)
	)
	IF @in_vchUserId IS NOT NULL
		BEGIN
			INSERT INTO @v_Owner
			SELECT own.owner_id, own.owner_code, own.owner_name
			FROM t_wms_owner own
			INNER JOIN t_wms_owner_user uown ON own.owner_id = uown.owner_id
			WHERE 1=1 AND uown.is_active = 'YES'
				AND (Convert(nvarchar(50),own.owner_id) = @in_vchOwner OR @in_vchOwner IS NULL)
				AND uown.user_id = @in_vchUserId

			INSERT INTO @v_Warehouse
			SELECT wh.wh_master_id, wh.wh_id, wh.wh_name
			FROM t_wms_wh wh
			INNER JOIN t_wms_wh_user uwh ON wh.wh_master_id = uwh.wh_master_id
			WHERE 1 = 1 AND uwh.is_active = 'YES'
				AND (wh.wh_id LIKE @in_vchWarehouse + '%' OR @in_vchWarehouse IS NULL)
				AND uwh.user_id = @in_vchUserId
		END
	ELSE
		BEGIN
			INSERT INTO @v_Owner
			SELECT own.owner_id, own.owner_code, own.owner_name
			FROM t_wms_owner own
			INNER JOIN t_wms_owner_user uown ON own.owner_id = uown.owner_id
			WHERE 1=1 AND uown.is_active = 'YES'
				AND (Convert(nvarchar(50),own.owner_id) = @in_vchOwner OR @in_vchOwner IS NULL)

			INSERT INTO @v_Warehouse
			SELECT wh.wh_master_id, wh.wh_id, wh.wh_name
			FROM t_wms_wh wh
			INNER JOIN t_wms_wh_user uwh ON wh.wh_master_id = uwh.wh_master_id
			WHERE 1 = 1 AND uwh.is_active = 'YES'
				AND (wh.wh_id LIKE @in_vchWarehouse + '%' OR @in_vchWarehouse IS NULL)
		END;

    -- Insert statements for procedure here	
	WITH t_item_master AS
	(
		SELECT itm.item_master_id, itm.item_number, itm.description, itm.dg_code, itm.price, itm.grade, itm.min_qty, itm.max_qty
			 , cate.category_id, cate.item_category
			 , uom.uom, uom.uom_prompt
		FROM t_wms_item itm
		LEFT JOIN t_wms_category cate ON itm.category_id = cate.category_id
		LEFT JOIN t_wms_item_uom uom on itm.item_master_id = uom.item_master_id AND uom.primary_uom = 'YES'
		WHERE (itm.owner_id IN (SELECT owner_id FROM @v_Owner))
			AND (itm.item_number LIKE @in_vchItemNumber + '%' OR @in_vchItemNumber IS NULL)
	)
	SELECT wh.wh_id
		 , invStatus.inv_status
		 , own.owner_code
		 , own.owner_name
		 , itm.item_number
		 , itm.description
		 , itm.dg_code
		 , itm.price
		 , itm.grade
		 , itm.min_qty
		 , itm.max_qty
		 , itm.category_id
		 , itm.item_category
		 , itm.uom
		 , itm.uom_prompt
		 , SUM(inv.quantity) AS quantity
	FROM t_wms_inventory inv
	INNER JOIN t_wms_wh wh ON inv.wh_master_id = wh.wh_master_id
	INNER JOIN t_wms_inventory_status invStatus ON inv.inventory_status_id = invStatus.inventory_status_id
	INNER JOIN t_wms_owner own ON inv.owner_id = own.owner_id
	INNER JOIN t_wms_wh_item whitm ON inv.wh_item_master_id = whitm.wh_item_master_id
	INNER JOIN t_item_master itm ON whitm.item_master_id = itm.item_master_id
	INNER JOIN t_wms_location loc ON inv.location_id = loc.location_id
	LEFT JOIN t_wms_zone_location zl on loc.location_id = zl.location_id
	LEFT JOIN t_wms_zone z on zl.zone_id = z.zone_id
	WHERE 1 = 1
		AND (own.owner_id IN (SELECT owner_id FROM @v_Owner))
		AND (wh.wh_id IN (SELECT wh_id FROM @v_Warehouse))
		AND (loc.location LIKE @in_vchLocation + '%' OR @in_vchLocation IS NULL)
		AND (itm.item_number LIKE @in_vchItemNumber + '%' OR @in_vchItemNumber IS NULL)
		AND (itm.item_category LIKE @in_vchItemCategory + '%' OR @in_vchItemCategory IS NULL)
		AND (itm.grade LIKE @in_vchGrade + '%' OR @in_vchGrade IS NULL)
		AND (itm.dg_code LIKE @in_vchDGCode + '%' OR @in_vchDGCode IS NULL)
		AND (inv.parent_lpn LIKE @in_vchParentLPN + '%' OR @in_vchParentLPN IS NULL)
		AND (inv.lpn LIKE @in_vchLPN + '%' OR @in_vchLPN IS NULL)
		AND (invStatus.inv_status LIKE @in_vchInventoryStatus + '%' OR @in_vchInventoryStatus IS NULL)
		AND (z.zone LIKE @in_vchZone + '%' OR @in_vchZone IS NULL)
		AND (CAST(inv.receive_date AS datetime) BETWEEN CAST(@in_vchReceiveDate AS datetime) AND CAST(@in_vchReceiveDateTo AS datetime) OR @in_vchReceiveDate IS NULL OR @in_vchReceiveDateTo IS NULL)
	GROUP BY wh.wh_id
		 , invStatus.inv_status
		 , own.owner_code, own.owner_name
		 , itm.item_number, itm.description
		 , itm.dg_code, itm.price, itm.grade
		 , itm.min_qty, itm.max_qty
		 , itm.category_id, itm.item_category
		 , itm.uom, itm.uom_prompt
END
GO
