/****** Object:  StoredProcedure [dbo].[usp_wms_report_summary_packing_list]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- exec usp_wms_report_summary_packing_list '2018-01-23'
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_summary_packing_list] @ship_date_actual	nvarchar(50) 
AS
BEGIN
	--if exists (select * from tempdb.sys.objects where name like '#%')
	--	drop table #temp_order

	create table #temp_order
	(
		col1_outbound_order_number	nvarchar(50) NULL,
		col2_outbound_order_number	nvarchar(50) NULL,
		col3_outbound_order_number	nvarchar(50) NULL,
		col4_ship_date_actual	datetime NULL
	)
	declare @column_01	nvarchar(50)
	declare @column_02	nvarchar(50)
	declare @column_03	nvarchar(50)
	declare @outbound_order_number	nvarchar(50)
	declare	@introw		int
	declare order_cursor CURSOR FOR

		--22/03/2019
		--select twom.outbound_order_number
		--from t_wms_outbound_master twom		
		--where twom.order_status = 'SHIP'
		--and twom.order_type in ('Consignment', 'Sales Order')
		--and twom.department not in ('BSWT')
		--and (Convert(date,twom.ship_date_actual) = Convert(date,@ship_date_actual) or @ship_date_actual is null)
		----and Convert(date,twom.ship_date_actual) = Convert(date,@ship_date_actual)
		--order by twom.outbound_order_number asc	

		--03/04/2019
		select distinct thwsche.order_number
		from t_host_wms_ship_conf_header_export thwsche
		inner join t_wms_outbound_master twom on thwsche.order_number = twom.outbound_order_number
		where thwsche.order_status = 'SHIP'
		and thwsche.order_type in ('Consignment', 'Sales Order')
		and twom.department not in ('BSWT')
		and (Convert(date,thwsche.create_date) = Convert(date,@ship_date_actual) or @ship_date_actual is null)
		order by thwsche.order_number asc

		set @introw = 0;
		open order_cursor
			fetch next from order_cursor into @outbound_order_number
			
				while  @@FETCH_STATUS = 0 
					begin
						set @introw = @introw+1
						if @introw = 1 set @column_01 = @outbound_order_number
						else if @introw = 2 set @column_02 = @outbound_order_number
						else if @introw = 3 set @column_03 = @outbound_order_number

					if @introw = 3 
						begin
							set @introw = 0
							insert into #temp_order
							select @column_01, @column_02, @column_03, Convert(date,@ship_date_actual)
							set @column_01 = NULL
							set @column_02 = NULL
							set @column_03 = NULL
						end
					fetch next from order_cursor into @outbound_order_number
					end			
		close order_cursor
	deallocate order_cursor

	if @introw <> 3 and @introw <> 0
		begin
			insert into #temp_order
			select @column_01, @column_02, @column_03, Convert(date,@ship_date_actual)
		end

	select * from #temp_order
	drop table #temp_order
END
GO
/****** Object:  StoredProcedure [dbo].[usp_wms_report_user_ performance]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Web Report
-- Description:	Report KPI Month
-- =============================================
CREATE PROCEDURE [dbo].[usp_wms_report_user_ performance]	
	
	@para_date_start nvarchar(10),
	@para_date_end nvarchar(10),
	@para_table nvarchar(30),
	@para_wh nvarchar(50),
	@para_owner nvarchar(50)
	
AS
BEGIN
if(@para_table = 'INBOUND')	begin	
  
		select DATEDIFF(MINUTE,min(A.start_tran_datetime), max(A.start_tran_datetime)) as use_time,A.user_id,A.order_number
		from t_com_tran_log  A
		inner join t_wms_inbound_master B on A.order_number = B.inbound_order_number
 
		where A.tran_type like 'IO%'
		and B.order_status not in( 'OPEN','CANCEL')
		and DATEADD(dd, 0, DATEDIFF(dd, 0, B.create_date)) between @para_date_start and @para_date_end
		and A.to_warehouse like case when  @para_wh = '' then '%%' else @para_wh end
		and A.to_owner like case when  @para_owner = '' then '%%' else @para_owner end
 
		group by  order_number,user_id 
		order by order_number

 
 end
 --outbound
else begin
		select DATEDIFF(MINUTE,min(A.start_tran_datetime), max(A.start_tran_datetime)) as use_time,A.user_id,A.order_number
		from t_com_tran_log  A
		inner join t_wms_outbound_master B on A.order_number = B.outbound_order_number
 
		where A.tran_type like 'OO%'
		and B.order_status not in( 'OPEN','RELEASE')
		and DATEADD(dd, 0, DATEDIFF(dd, 0, B.order_date)) between @para_date_start and @para_date_end
		and A.warehouse like case when  @para_wh = '' then '%%' else @para_wh end
		and A.[owner] like case when  @para_owner = '' then '%%' else @para_owner end
 
		group by  order_number,user_id 
		order by order_number

end



END


GO
/****** Object:  StoredProcedure [dbo].[usp_wms_send_email]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_wms_send_email]
(
	@in_vchCountID	NVARCHAR(50),
	@in_vchUserID	NVARCHAR(50),
	@out_vchResult	NVARCHAR(500) OUTPUT
)
AS
BEGIN
	DECLARE		@v_vchEmail_To			NVARCHAR(250) = NULL,
				@v_vchEmail_CC			NVARCHAR(250) = NULL,
				@v_vchSubject			NVARCHAR(200) = NULL,
				@v_vchDetail			NVARCHAR(500) = NULL,
				@v_vchAttatched			NVARCHAR(200) = NULL,
				@v_vchPath				NVARCHAR(200) = NULL,
				@v_PathResult			INT,
				@v_SendResult			INT,
				@v_vchCloseBy			NVARCHAR(25),
				@v_vchCloseDate			DATETIME,
				@v_vchCountType			nvarchar(50),
				@v_vchCountDesc			nvarchar(200),
				@v_vchCountPlanDate		datetime,
				@v_vchCustomerCode		NVARCHAR(50),
				@v_vchCustomerName		NVARCHAR(200)

				
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	BEGIN TRY
		SELECT TOP 1 @v_vchEmail_To = REPLACE(cust.email,',',';')
			,@v_vchCloseBy = cMS.close_by
			,@v_vchCloseDate = cMS.close_date
			,@v_vchCustomerCode = cMS.customer_code
			,@v_vchCustomerName = cMS.customer_name
			,@v_vchCountType = cMS.count_plan_type
			,@v_vchCountDesc = cMS.description
			,@v_vchCountPlanDate = cMS.count_plan_date
		FROM t_wms_count_plan_master_external cMS
		LEFT JOIN t_wms_customer cust ON cMS.customer_id = cust.customer_id
		WHERE cMS.count_id = @in_vchCountID

		SELECT @v_vchEmail_CC = REPLACE(email_address,',',';')
		FROM v_wms_user
		WHERE user_id = @in_vchUserID

		SET @v_vchSubject = 'Count reconcile report ['+ ISNULL(@v_vchCustomerName,'') +']'
		SET @v_vchDetail = '<B>Count ID:</B> '+ @in_vchCountID + ' <BR>'
						   + '<B>Customer code:</B> '+ ISNULL(@v_vchCustomerCode,'') + ' <BR>'
						   + '<B>Customer name:</B> '+ ISNULL(@v_vchCustomerName,'') + ' <BR>'
						   + '<B>Count type:</B> '+ ISNULL(@v_vchCountType,'') + ' <BR>'
						   + '<B>Description:</B> '+ ISNULL(@v_vchCountDesc,'') + ' <BR>'
						   + '<B>Count plan date:</B> ' + ISNULL(CONVERT(VARCHAR,@v_vchCountPlanDate,103),'') + ' <BR>'
						   + '<B>Close by:</B> '+ ISNULL(@v_vchCloseBy,'') + ' <BR>'
						   + '<B>Close date:</B> ' + ISNULL(CONVERT(VARCHAR,@v_vchCloseDate,103),'') + ' <BR>'

		IF (ISNULL(@v_vchEmail_To,'') = '')
			BEGIN
				SELECT      @v_vchEmail_To = email_to
				FROM        t_wms_email
				WHERE		type = 'Count'
			END
		IF (ISNULL(@v_vchEmail_CC,'') = '')
			BEGIN
				SELECT      @v_vchEmail_CC = email_cc
				FROM        t_wms_email
				WHERE		type = 'Count'
			END

		-- SET @v_vchPath = 'C:\WM8\WMS_IOS\Crystal_to_PDF\'+ @in_vchCountID+'.pdf';
		SET @v_vchPath = 'C:\WMS\WebServiceLF\Crystal_to_PDF\'+ @in_vchCountID+'.pdf';
		EXEC master.dbo.xp_fileexist @v_vchPath, @v_PathResult OUTPUT
		IF(@v_PathResult = 1)
			BEGIN
				SET @v_vchAttatched = @v_vchPath

				EXEC @v_SendResult = msdb.dbo.sp_send_dbmail 
				@profile_name='Anonymous',
				@recipients=  @v_vchEmail_To,
				@copy_recipients = @v_vchEmail_CC,
				@subject= @v_vchSubject	,
				@body=@v_vchDetail,	
				@body_format = 'HTML',
				@file_attachments=@v_vchAttatched
			END
		ELSE
			BEGIN
				IF (ISNULL(@v_vchEmail_CC,'') = '')
					BEGIN
						SELECT @v_vchEmail_CC = email_cc
						FROM t_wms_email
						WHERE type = 'CountError'
					END

				EXEC @v_SendResult = msdb.dbo.sp_send_dbmail 
				@profile_name='Anonymous',
				@recipients=  @v_vchEmail_CC,
				--@copy_recipients = @v_vchEmail_CC,
				@subject= @v_vchSubject	,
				@body=@v_vchDetail,
				@body_format = 'HTML'
				--@file_attachments=@v_vchAttatched	
			END

		IF(@v_SendResult = 0)
			BEGIN
				SET @out_vchResult = 'Success';
			END
		ELSE
			BEGIN
				SET @out_vchResult = @@ERROR;
			END
	END TRY
	BEGIN CATCH
		SET @out_vchResult = ERROR_MESSAGE();
	END CATCH

END
