			END
		ELSE
			BEGIN
				SET @out_vchResult = @@ERROR;
				RETURN
			END

	-- Stock Expired 15 days
		SELECT     @v_vchEmail_To = email_to,@v_vchEmail_CC	= email_cc, @v_vchSubject = subject,@v_vchDetail = detail
		FROM        t_wms_email
		WHERE		type = 'Stock_Expired_15'

		IF(ISNULL(@v_vchEmail_To,'')='')
			BEGIN
				SET @out_vchResult = 'NOT-FOUND-EMAIL-DATA';
