		SET @Delimiter = CHAR(9)

		EXEC @v_SendResult = MSDB.dbo.sp_Send_DBMail 
							@profile_name = 'AutoReport',
							@Recipients=@v_vchEmail_To,
							@copy_recipients = @v_vchEmail_CC,
							@Subject = @v_vchSubject,
							@Body = @v_vchDetail,
							@Query='SELECT zone,location,customer_name,item_category,item_number,description,lot_number,expiry_date,serial_number,quantity,inv_status,CONVERT(NVARCHAR,last_inbound_transaction,103) AS last_inbound_transaction FROM WM3.dbo.v_wms_stock_expired15days_report Where zone in ("HOSPITAL","NORM") ORDER BY zone DESC,customer_name',
							@Attach_Query_Result_As_File = 1,
