/****** Object:  StoredProcedure [dbo].[usp_zone_item_category_mapping]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai Kokaew
-- Create date: 10/04/2012
-- Description:	Add/Update zone item category
-- =============================================
CREATE PROCEDURE [dbo].[usp_zone_item_category_mapping]
	@ApplicationID Varchar(40),
	@WarehouseID Varchar(40),
	@zone_id Varchar(40),
	@category_data NvarChar(max),
	@DeviceId NvarChar(50),
	@UserID NvarChar(10),
	@out_vchErrorCode	nvarchar(3) output,
	@out_vchErrorMessage	nvarchar(500) output
AS
BEGIN
	SET NOCOUNT ON;

	Declare @DocHandle Int,
			@IsSelect Bit,
			@category_id Varchar(40),
			@is_active bit,
			@active_value NvarChar(3)
	
	Exec sp_xml_preparedocument @DocHandle Output,@category_data
	
	Declare cursorZoneItemCategory Cursor For
		Select is_select,category_id
		From OpenXML(@DocHandle,'ZoneItem/ItemCategoryMapping',2)
		With(is_select bit,category_id varchar(40))	
	
	Open cursorZoneItemCategory;
	EXEC sp_xml_removedocument @DocHandle;
	
	Fetch From cursorZoneItemCategory Into @IsSelect,@category_id
	
	Begin Try
		Begin Transaction
		
			While @@Fetch_Status = 0
			Begin
				
				IF (@IsSelect = 'True')
					Begin
						IF (Not Exists(Select * from t_wms_zone_category Where zone_id = @zone_id and category_id = @category_id))
							Begin
								Insert Into t_wms_zone_category(zone_category_id, zone_id, category_id, is_active, create_date, create_by)
								Values(NewID(),@zone_id,@category_id,'YES',GetDate(),@UserID)
							End
					End
				Else
					Begin
						Delete From t_wms_zone_category Where zone_id = @zone_id and category_id = @category_id
					End

				Fetch Next From cursorZoneItemCategory Into @IsSelect,@category_id
			End
			
		Commit Transaction
		Close cursorZoneItemCategory;
		Deallocate cursorZoneItemCategory;

		set @out_vchErrorCode = '0';
		select @out_vchErrorMessage = dbo.usf_get_resouce_value(@ApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@UserID)),'@param1','@param2','@param3','@param4','@param5')	

	End Try
	Begin Catch
		Close cursorZoneItemCategory;
		Deallocate cursorZoneItemCategory;
		Rollback Transaction;
		DECLARE	@process_id varchar(40),
				@error_number Nvarchar(20),
				@error_message NvarChar(100)

		Set @process_id = NewId();
		Set @error_number = Error_Number();
		Set @error_message = Error_Message();

		set @out_vchErrorCode = @error_number;
		set @out_vchErrorMessage = @error_message;

		exec usp_LogManager
			@in_vchApplicationID = @ApplicationID,
			@in_vchWhID = WarehouseID,
			@in_vchDevice = DeviceId,
			@in_vchUserID = @UserID,
			@in_vchLogType = 'Error',
			@in_vchProcess = 'usp_ZoneItemCategoryMapping',
			@in_vchData1 = @error_number,
			@in_vchMessage = @error_message
			
	End Catch
END



GO
/****** Object:  StoredProcedure [dbo].[usp_zone_location_mapping]    Script Date: 08/08/2025 11:11:30 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Wuttichai K.
-- Create date: 23 Mar 2012
-- Description:	Warehouse item mapping
-- =============================================
CREATE PROCEDURE [dbo].[usp_zone_location_mapping]
	@ApplicationID Varchar(40),
	@WarehouseID Varchar(40),
	@ZoneID VarChar(40),
	@Data NvarChar(Max),
	@DeviceId NvarChar(50),
	@UserID NvarChar(10),
	@out_vchErrorCode	nvarchar(3) output,
	@out_vchErrorMessage	nvarchar(500) output
AS
BEGIN
	SET NOCOUNT ON;

	Declare @DocHandle Int,
			@IsSelect Bit,
			@Location NVarchar(50),
			@LocationID NVarchar(40),
			@IsActive NvarChar(5)
	
	Exec sp_xml_preparedocument @DocHandle Output,@Data
	
	Declare cursorZoneLocation Cursor For
		Select is_select,location_id
		From OpenXML(@DocHandle,'ZoneLocation/ZoneLocationMapping',2)
		With(is_select bit,location_id Nvarchar(40))
		
	Open cursorZoneLocation;
	EXEC sp_xml_removedocument @DocHandle;

	Fetch From cursorZoneLocation Into @IsSelect,@LocationID
	
	Begin Try
		Begin Transaction
		
		While @@Fetch_Status = 0
			Begin
				
				IF (@IsSelect = 'True')
					BEGIN
						--If Exists(Select * from t_wms_zone_location Where zone_id = @ZoneID and location_id = @LocationID)
						--	Begin
						--		Close cursorZoneLocation;
						--		Deallocate cursorZoneLocation;
						--		Rollback Transaction;
						--		SET @out_vchErrorCode = '999';
						--		SET @out_vchErrorMessage = 'Location already exists in zone location';
						--		return;
						--	End
						----IF (Exists(Select * from t_wms_zone_location Where zone_id = @ZoneID and location_id = @LocationID))
						----	Begin
						----		Update t_wms_zone_location Set is_active = @IsActive,create_date = GetDate(), create_by = @UserID
						----		Where zone_id = @ZoneID and location_id = @LocationID
						----	End
						----Else
						----	Begin
						IF Not Exists(Select * from t_wms_zone_location Where location_id = @LocationID)
							Begin
								Insert Into t_wms_zone_location(zone_location_id,zone_id,location_id ,is_active, create_date, create_by)
								Values(NewID(),@ZoneID,@LocationID,'YES',GetDate(),@UserID)
							End
						Else
							Begin
								Close cursorZoneLocation;
								Deallocate cursorZoneLocation;
								Rollback Transaction;
								select @Location = location from t_wms_location where location_id = @LocationID
								SET @out_vchErrorCode = '999';
								--SET @out_vchErrorMessage = 'Location already exists in another zone.Cannot map to new zone!';
								select @out_vchErrorMessage = dbo.usf_get_resouce_value(@ApplicationID,'LOCATION_IS_MAPPED_BY_OTHER_ZONE',(select dbo.usf_get_locale_id(@UserID)),@Location,'@param2','@param3','@param4','@param5')	
								return;
							End
					END
				ELSE
					BEGIN
						If Exists(select location_id from t_wms_inventory where location_id = @LocationID)
							Begin
								Close cursorZoneLocation;
								Deallocate cursorZoneLocation;
								Rollback Transaction;
								select @Location = location from t_wms_location where location_id = @LocationID
								SET @out_vchErrorCode = '999';
								--SET @out_vchErrorMessage = 'Location already exists in inventory.Cannot delete!';
								select @out_vchErrorMessage = dbo.usf_get_resouce_value(@ApplicationID,'LOCATION_IS_ALREADY_INVENTORY',(select dbo.usf_get_locale_id(@UserID)),@Location,'@param2','@param3','@param4','@param5')	
								return;
							End
						Delete From t_wms_zone_location Where zone_id = @ZoneID and location_id = @LocationID;
					END
					
				Fetch Next From cursorZoneLocation Into @IsSelect,@LocationID
			End
			
		Commit Transaction
		Close cursorZoneLocation;
		Deallocate cursorZoneLocation;

		SET @out_vchErrorCode = '0';
		--SET @out_vchErrorMessage = 'SAVE SUCCESSFULLY';
		select @out_vchErrorMessage = dbo.usf_get_resouce_value(@ApplicationID,'SAVE_SUCCESS',(select dbo.usf_get_locale_id(@UserID)),'@param1','@param2','@param3','@param4','@param5')	

	End Try
	Begin Catch
		Close cursorZoneLocation;
		Deallocate cursorZoneLocation;
		Rollback Transaction;

		DECLARE	@process_id varchar(40),
				@error_number Nvarchar(20),
				@error_message NvarChar(100)
		Set @process_id = NewId();
		Set @error_number = Error_Number();
		Set @error_message = Error_Message();

		set @out_vchErrorCode = @error_number;
		set @out_vchErrorMessage = @error_message;

		exec usp_LogManager
			@in_vchApplicationID = @ApplicationID,
			@in_vchWhID = WarehouseID,
			@in_vchDevice = DeviceId,
			@in_vchUserID = @UserID,
			@in_vchLogType = 'Error',
			@in_vchProcess = 'usp_ZoneLocationMapping',
			@in_vchData1 = @error_number,
			@in_vchMessage = @error_message
	End Catch
	
END



GO
